INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, '元始に神天地を創造たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, '地は定形なく曠空くして黑暗淵の面にあり神の靈水の面を覆たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, '神光あれと言たまひければ光ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, '神光を善と觀たまへり神光と暗を分ちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, '神光を晝と名け暗を夜と名けたまへり夕あり朝ありき是首の日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, '神言たまひけるは水の中に穹蒼ありて水と水とを分つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, '神穹蒼を作りて穹蒼の下の水と穹蒼の上の水とを判ちたまへり即ち斯なりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, '神穹蒼を天と名けたまへり夕あり朝ありき是二日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, '神言たまひけるは天の下の水は一處に集りて乾ける土顯べしと即ち斯なりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, '神乾ける土を地と名け水の集合るを海と名けたまへり神之を善と觀たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, '神言たまひけるは地は靑草と實蓏を生ずる草蔬と其類に從ひ果を結びみづから核をもつ所の果を結ぶ樹を地に發出すべしと即ち斯なりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, '地靑草と其類に從ひ實蓏を生ずる草蔬と其類に從ひ果を結てみづから核をもつ所の樹を發出せり神これを善と觀たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, '夕あり朝ありき是三日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, '神言たまひけるは天の穹蒼に光明ありて晝と夜とを分ち又天象のため時節のため日のため年のために成べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, '又天の穹蒼にありて地を照す光となるべしと即ち斯なりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, '神二の巨なる光を造り大なる光に晝を司どらしめ小き光に夜を司どらしめたまふまた星を造りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, '神これを天の穹蒼に置て地を照さしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, '晝と夜を司どらしめ光と暗を分たしめたまふ神これを善と觀たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, '夕あり朝ありき是四日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, '神云たまひけるは水には生物饒に生じ鳥は天の穹蒼の面に地の上に飛べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, '神巨なる魚と水に饒に生じて動く諸の生物を其類に從ひて創造り又羽翼ある諸の鳥を其類に從ひて創造りたまへり神之を善と觀たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, '神之を祝して曰く生よ繁息よ海の水に充牣よ又禽鳥は地に蕃息よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, '夕あり朝ありき是五日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, '神言給ひけるは地は生物を其類に從て出し家畜と昆蟲と地の獸を其類に從て出すべしと即ち斯なりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, '神地の獸を其類に從て造り家畜を其類に從て造り地の諸の昆蟲を其類に從て造り給へり神之を善と觀給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, '神言給けるは我儕に象りて我儕の像の如くに我儕人を造り之に海の魚と天空の鳥と家畜と全地と地に匍ふ所の諸の昆蟲を治めんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, '神其像の如くに人を創造たまへり即ち神の像の如くに之を創造之を男と女に創造たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, '神彼等を祝し神彼等に言たまひけるは生よ繁殖よ地に滿盈よ之を服從せよ又海の魚と天空の鳥と地に動く所の諸の生物を治めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, '神言たまひけるは視よ我全地の面にある實蓏のなる諸の草蔬と核ある木果の結る諸の樹とを汝等に與ふこれは汝らの糧となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, '又地の諸の獸と天空の諸の鳥および地に匍ふ諸の物等凡そ生命ある者には我食物として諸の靑き草を與ふと即ち斯なりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, '神其造りたる諸の物を視たまひけるに甚だ善りき夕あり朝ありき是六日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, '斯天地および其衆群悉く成ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, '第七日に神其造りたる工を竣たまへり即ち其造りたる工を竣て七日に安息たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, '神七日を祝して之を神聖めたまへり其は神其創造爲たまへる工を盡く竣て是日に安息みたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'ヱホバ神地と天を造りたまへる日に天地の創造られたる其由來は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, '野の諸の灌木は未だ地にあらず野の諸の草蔬は未生ぜざりき其はヱホバ神雨を地に降せたまはず亦土地を耕す人なかりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, '霧地より上りて土地の面を遍く潤したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'ヱホバ神土の塵を以て人を造り生氣を其鼻に嘘入たまへり人即ち生靈となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'ヱホバ神エデンの東の方に園を設て其造りし人を其處に置たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'ヱホバ神觀に美麗く食ふに善き各種の樹を土地より生ぜしめ又園の中に生命の樹および善惡を知の樹を生ぜしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, '河エデンより出て園を潤し彼處より分れて四の源となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, '其第一の名はピソンといふ是は金あるハビラの全地を繞る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, '其地の金は善し又ブドラクと碧玉彼處にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, '第二の河の名はギホンといふ是はクシの全地を繞る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, '第三の河の名はヒデケルといふ是はアッスリヤの東に流るるものなり第四の河はユフラテなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'ヱホバ神其人を挈て彼をエデンの園に置き之を埋め之を守らしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'ヱホバ神其人に命じて言たまひけるは園の各種の樹の果は汝意のままに食ふことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, '然ど善惡を知の樹は汝その果を食ふべからず汝之を食ふ日には必ず死べければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'ヱホバ神言たまひけるは人獨なるは善らず我彼に適ふ助者を彼のために造らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'ヱホバ神土を以て野の諸の獸と天空の諸の鳥を造りたまひてアダムの之を何と名るかを見んとて之を彼の所に率ゐいたりたまへりアダムが生物に名けたる所は皆其名となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'アダム諸の家畜と天空の鳥と野の諸の獸に名を與へたり然どアダムには之に適ふ助者みえざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, '是に於てヱホバ神アダムを熟く睡らしめ睡りし時其肋骨の一を取り肉をもて其處を填塞たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'ヱホバ神アダムより取たる肋骨を以て女を成り之をアダムの所に携きたりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'アダム言けるは此こそわが骨の骨わが肉の肉なれ此は男より取たる者なれば之を女と名くべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, '是故に人は其父母を離れて其妻に好合ひ二人一體となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'アダムと其妻は二人倶に裸體にして愧ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'ヱホバ神の造りたまひし野の生物の中に蛇最も狡猾し蛇婦に言ひけるは神眞に汝等園の諸の樹の果は食ふべからずと言たまひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, '婦蛇に言けるは我等園の樹の果を食ふことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, '然ど園の中央に在樹の果實をば神汝等之を食ふべからず又之に捫るべからず恐は汝等死んと言給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, '蛇婦に言けるは汝等必らず死る事あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, '神汝等が之を食ふ日には汝等の目開け汝等神の如くなりて善惡を知に至るを知りたまふなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, '婦樹を見ば食に善く目に美麗しく且智慧からんが爲に慕はしき樹なるによりて遂に其果實を取て食ひ亦之を己と偕なる夫に與へければ彼食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, '是において彼等の目倶に開て彼等其裸體なるを知り乃ち無花果樹の葉を綴て裳を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, '彼等園の中に日の清涼き時分歩みたまふヱホバ神の聲を聞しかばアダムと其妻即ちヱホバ神の面を避て園の樹の間に身を匿せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'ヱホバ神アダムを召て之に言たまひけるは汝は何處にをるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, '彼いひけるは我園の中に汝の聲を聞き裸體なるにより懼れて身を匿せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'ヱホバ言たまひけるは誰が汝の裸なるを汝に告しや汝は我が汝に食ふなかれと命じたる樹の果を食ひたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'アダム言けるは汝が與て我と偕ならしめたまひし婦彼其樹の果實を我にあたへたれば我食へりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'ヱホバ神婦に言たまひけるは汝がなしたる此事は何ぞや婦言けるは蛇我を誘惑して我食へりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'ヱホバ神蛇に言たまひけるは汝是を爲たるに因て汝は諸の家畜と野の諸の獸よりも勝りて詛はる汝は腹行て一生の間塵を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, '又我汝と婦の間および汝の苗裔と婦の苗裔の間に怨恨を置ん彼は汝の頭を碎き汝は彼の踵を碎かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, '又婦に言たまひけるは我大に汝の懷姙の劬勞を増すべし汝は苦みて子を產ん又汝は夫をしたひ彼は汝を治めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, '又アダムに言たまひけるは汝その妻の言を聽て我が汝に命じて食ふべからずと言たる樹の果を食ひしに縁て土は汝のために詛はる汝は一生のあひだ勞苦て其より食を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, '土は荊棘と薊とを汝のために生ずべしまた汝は野の草蔬を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, '汝は面に汗して食物を食ひ終に土に歸らん其は其中より汝は取れたればなり汝は塵なれば塵に皈るべきなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'アダム其妻の名をヱバと名けたり其は彼は群の生物の母なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'ヱホバ神アダムと其妻のために皮衣を作りて彼等に衣せたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'ヱホバ神曰たまひけるは視よ夫人我等の一の如くなりて善惡を知る然ば恐くは彼其手を舒べ生命の樹の果實をも取りて食ひ限無生んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'ヱホバ神彼をエデンの園よりいだし其取て造られたるところの土を耕さしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, '斯神其人を逐出しエデンの園の東にケルビムと自から旋轉る焔の劍を置て生命の樹の途を保守りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'アダム其妻エバを知る彼孕みてカインを生みて言けるは我ヱホバによりて一個の人を得たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, '彼また其弟アベルを生りアベルは羊を牧ふ者カインは土を耕す者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, '日を經て後カイン土より出る果を携來りてヱホバに供物となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'アベルもまた其羊の初生と其肥たる者を携來れりヱホバ、アベルと其供物を眷顧みたまひしかども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'カインと其供物をば眷み給はざりしかばカイン甚だ怒り且其面をふせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'ヱホバ、カインに言たまひけるは汝何ぞ怒るや何ぞ面をふするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, '汝若善を行はば擧ることをえざらんや若善を行はずば罪門戸に伏す彼は汝を慕ひ汝は彼を治めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'カイン其弟アベルに語りぬ彼等野にをりける時カイン其弟アベルに起かかりて之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'ヱホバ、カインに言たまひけるは汝の弟アベルは何處にをるや彼言ふ我しらず我あに我弟の守者ならんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'ヱホバ言たまひけるは汝何をなしたるや汝の弟の血の聲地より我に叫べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'されば汝は詛れて此地を離るべし此地其口を啓きて汝の弟の血を汝の手より受たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, '汝地を耕すとも地は再其力を汝に效さじ汝は地に吟行ふ流離子となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'カイン、ヱホバに言けるは我が罪は大にして負ふこと能はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, '視よ汝今日斯地の面より我を逐出したまふ我汝の面を觀ることなきにいたらん我地に吟行ふ流離子とならん凡そ我に遇ふ者我を殺さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'ヱホバ彼に言たまひけるは然らず凡そカインを殺す者は七倍の罰を受んとヱホバ、カインに遇ふ者の彼を撃ざるため印誌を彼に與へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'カイン、ヱホバの前を離て出でエデンの東なるノドの地に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'カイン其妻を知る彼孕みエノクを生りカイン邑を建て其邑の名を其子の名に循ひてエノクと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'エノクにイラデ生れたりイラデ、メホヤエルを生みメホヤエル、メトサエルを生みメトサエル、レメクを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'レメク二人の妻を娶れり一の名はアダと曰ひ一の名はチラと曰り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'アダ、ヤバルを生めり彼は天幕に住て家畜を牧ふ所の者の先祖なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, '其弟の名はユバルと云ふ彼は琴と笛とをとる凡ての者の先祖なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, '又チラ、トバルカインを生り彼は銅と鐡の諸の刃物を鍛ふ者なりトバルカインの妹をナアマといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'レメク其妻等に言けるはアダとチラよ我聲を聽けレメクの妻等よわが言を容よ我わが創傷のために人を殺すわが痍のために少年を殺す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'カインのために七倍の罰あればレメクのためには七十七倍の罰あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'アダム復其妻を知て彼男子を生み其名をセツと名けたり其は彼神我にカインの殺したるアベルのかはりに他の子を與へたまへりといひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'セツにもまた男子生れたりかれ其名をエノスと名けたり此時人々ヱホバの名を呼ことをはじめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'アダムの傳の書は是なり神人を創造りたまひし日に神に象りて之を造りたまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, '彼等を男女に造りたまへり彼等の創造られし日に神彼等を祝してかれらの名をアダムと名けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'アダム百三十歳に及びて其像に循ひ己に象りて子を生み其名をセツと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'アダムのセツを生し後の齡は八百歳にして男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'アダムの生存へたる齡は都合九百三十歳なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'セツ百五歳に及びてエノスを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'セツ、エノスを生し後八百七年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'セツの齡は都合九百十二歳なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'エノス九十歳におよびてカイナンを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'エノス、カイナンを生し後八百十五年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'エノスの齡は都合九百五歳なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'カイナン七十歳におよびてマハラレルを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'カイナン、マハラレルを生し後八百四十年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'カイナンの齡は都合九百十歳なりきしかして死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'マハラレル六十五歳に及びてヤレドを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'マハラレル、ヤレドを生し後八百三十年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'マハラレルの齡は都合八百九十五歳なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'ヤレド百六十二歳に及びてエノクを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'ヤレド、エノクを生し後八百年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'ヤレドの齡は都合九百六十二歳なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'エノク六十五歳に及びてメトセラを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'エノク、メトセラを生し後三百年神とともに歩み男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'エノクの齡は都合三百六十五歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'エノク神と偕に歩みしが神かれを取りたまひければをらずなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'メトセラ百八十七歳に及びてレメクを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'メトセラ、レメクを生しのち七百八十二年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'メトセラの齡は都合九百六十九歳なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'レメク百八十二歳に及びて男子を生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, '其名をノアと名けて言けるは此子はヱホバの詛ひたまひし地に由れる我操作と我勞苦とに就て我らを慰めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'レメク、ノアを生し後五百九十五年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'レメクの齡は都合七百七十七歳なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'ノア五百歳なりきノア、セム、ハム、ヤペテを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, '人地の面に繁衍はじまりて女子之に生るるに及べる時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, '神の子等人の女子の美しきを見て其好む所の者を取て妻となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'ヱホバいひたまひけるは我靈永く人と爭はじ其は彼も肉なればなり然ど彼の日は百二十年なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, '當時地にネピリムありき亦其後神の子輩人の女の所に入りて子女を生しめたりしが其等も勇士にして古昔の名聲ある人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'ヱホバ人の惡の地に大なると其心の思念の都て圖維る所の恒に惟惡きのみなるを見たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, '是に於てヱホバ地の上に人を造りしことを悔いて心に憂へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'ヱホバ言たまひけるは我が創造りし人を我地の面より拭去ん人より獸昆蟲天空の鳥にいたるまでほろぼさん其は我之を造りしことを悔ればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'されどノアはヱホバの目のまへに恩を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'ノアの傳は是なりノアは義人にして其世の完全き者なりきノア神と偕に歩めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'ノアはセム、ハム、ヤペテの三人の子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, '時に世神のまへに亂れて暴虐世に滿盈ちたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, '神世を視たまひけるに視よ亂れたり其は世の人皆其道をみだしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, '神ノアに言たまひけるは諸の人の末期わが前に近づけり其は彼等のために暴虐世にみつればなり視よ我彼等を世とともに剪滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, '汝松木をもて汝のために方舟を造り方舟の中に房を作り瀝靑をもて其内外を塗るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, '汝かく之を作るべし即ち其方舟の長は三百キユビト其濶は五十キユビト其高は三十キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, '又方舟に導光牖を作り上一キユビトに之を作り終べし又方舟の戸は其傍に設くべし下牀と二階と三階とに之を作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, '視よ我洪水を地に起して凡て生命の氣息ある肉なる者を天下より剪滅し絶ん地にをる者は皆死ぬべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, '然ど汝とは我わが契約をたてん汝は汝の子等と汝の妻および汝の子等の妻とともに其方舟に入るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, '又諸の生物總て肉なる者をば汝各其二を方舟に挈へいりて汝とともに其生命を保たしむべし其等は牝牡なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, '鳥其類に從ひ獸其類に從ひ地の諸の昆蟲其類に從ひて各二汝の所に至りて其生命を保つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, '汝食はるる諸の食品を汝の許に取て之を汝の所に集むべし是即ち汝と是等の物の食品となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'ノア是爲し都て神の己に命じたまひしごとく然爲せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'ヱホバ、ノアに言たまひけるは汝と汝の家皆方舟に入べし我汝がこの世の人の中にてわが前に義を視たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, '諸の潔き獸を牝牡七宛汝の許に取り潔らぬ獸を牝牡二');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, '亦天空の鳥を雌雄七宛取て種を全地の面に生のこらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, '今七日ありて我四十日四十夜地に雨ふらしめ我造りたる萬有を地の面より拭去ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'ノア、ヱホバの凡て己に命じたまひし如くなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, '地に洪水ありける時にノア六百歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'ノア其子等と其妻および其子等の妻と倶に洪水を避て方舟にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, '潔き獸と潔らざる獸と鳥および地に匍ふ諸の物');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, '牝牡二宛ノアに來りて方舟にいりぬ神のノアに命じたまへるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'かくて七日の後洪水地に臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'ノアの齡の六百歳の二月即ち其月の十七日に當り此日に大淵の源皆潰れ天の戸開けて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, '雨四十日四十夜地に注げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, '此日にノアとノアの子セム、ハム、ヤペテおよびノアの妻と其子等の三人の妻諸倶に方舟にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, '彼等および諸の獸其類に從ひ諸の家畜其類に從ひ都て地に匍ふ昆蟲其類に從ひ諸の禽即ち各樣の類の鳥皆其類に從ひて入りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, '即ち生命の氣息ある諸の肉なる者二宛ノアに來りて方舟にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, '入たる者は諸の肉なる者の牝牡にして皆いりぬ神の彼に命じたまへるが如しヱホバ乃ち彼を閉置たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, '洪水四十日地にありき是において水増し方舟を浮めて方舟地の上に高くあがれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, '而して水瀰漫りて大に地に増しぬ方舟は水の面に漂へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, '水甚大に地に瀰漫りければ天下の高山皆おほはれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, '水はびこりて十五キユビトに上りければ山々おほはれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, '凡そ地に動く肉なる者鳥家畜獸地に匍ふ諸の昆蟲および人皆死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, '即ち凡そ其鼻に生命の氣息のかよふ者都て乾土にある者は死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, '斯地の表面にある萬有を人より家畜昆蟲天空の鳥にいたるまで盡く拭去たまへり是等は地より拭去れたり唯ノアおよび彼とともに方舟にありし者のみ存れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, '水百五十日のあひだ地にはびこりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, '神ノアおよび彼とともに方舟にある諸の生物と諸の家畜を眷念ひたまひて神乃ち風を地の上に吹しめたまひければ水減りたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, '亦淵の源と天の戸閉塞りて天よりの雨止ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, '是に於て水次第に地より退き百五十日を經てのち水減り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, '方舟は七月に至り其月の十七日にアララテの山に止りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, '水次第に減て十月に至りしが十月の月朔に山々の嶺現れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, '四十日を經てのちノア其方舟に作りし窓を啓て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, '鴉を放出ちけるが水の地に涸るまで往來しをれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, '彼地の面より水の減少しかを見んとて亦鴿を放出いだしけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, '鴿其足の跖を止べき處を得ずして彼に還りて方舟に至れり其は水全地の面にありたればなり彼乃ち其手を舒て之を執へ方舟の中におのれの所に接入たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, '尚又七日待て再び鴿を方舟より放出ちけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, '鴿暮におよびて彼に還れり視よ其口に橄欖の新葉ありき是に於てノア地より水の減少しをしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, '尚又七日まちて鴿を放出ちけるが再び彼の所に歸らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, '六百一年の一月の月朔に水地に涸たりノア乃ち方舟の蓋を撤きて視しに視よ土の面は燥てありぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, '二月の二十七日に至りて地乾きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, '爰に神ノアに語りて言給はく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '汝および汝の妻と汝の子等と汝の子等の妻ともに方舟を出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, '汝とともにある諸の肉なる諸の生物諸の肉なる者即ち鳥家畜および地に匍ふ諸の昆蟲を率いでよ此等は地に饒く生育地の上に生且殖増すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'ノアと其子等と其妻および其子等の妻ともに出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, '諸の獸諸の昆蟲および諸の鳥等凡そ地に動く者種類に從ひて方舟より出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'ノア、ヱホバのために壇を築き諸の潔き獸と諸の潔き鳥を取て燔祭を壇の上に献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'ヱホバ其馨き香を聞ぎたまひてヱホバ其意に謂たまひけるは我再び人の故に因て地を詛ふことをせじ其は人の心の圖維るところ其幼少時よりして惡かればなり又我曾て爲たる如く再び諸の生る物を撃ち滅さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, '地のあらん限りは播種時、收穫時、寒熱夏冬および日と夜息ことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, '神ノアと其子等を祝して之に曰たまひけるは生よ増殖よ地に滿よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, '地の諸の獸畜天空の諸の鳥地に匍ふ諸の物海の諸の魚汝等を畏れ汝等に懾かん是等は汝等の手に與へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, '凡そ生る動物は汝等の食となるべし菜蔬のごとく我之を皆汝等に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, '然ど肉を其生命なる其血のままに食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, '汝等の生命の血を流すをば我必ず討さん獸之をなすも人をこれを爲すも我討さん凡そ人の兄弟人の生命を取ば我討すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, '凡そ人の血を流す者は人其血を流さん其は神の像のごとくに人を造りたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, '汝等生よ増殖よ地に饒くなりて其中に増殖よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, '神ノアおよび彼と偕にある其子等に告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '見よ我汝等と汝等の後の子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'および汝等と偕なる諸の生物即ち汝等とともなる鳥家畜および地の諸の獸と契約を立ん都て方舟より出たる者より地の諸の獸にまで至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, '我汝等と契約を立ん總て肉なる者は再び洪水に絶るる事あらじ又地を滅す洪水再びあらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, '神言たまひけるは我が我と汝等および汝等と偕なる諸の生物の間に世々限りなく爲す所の契約の徴は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, '我わが虹を雲の中に起さん是我と世との間の契約の徴なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, '即ち我雲を地の上に起す時虹雲の中に現るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, '我乃ち我と汝等および總て肉なる諸の生物の間のわが契約を記念はん水再び諸の肉なる者を滅す洪水とならじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, '虹雲の中にあらん我之を觀て神と地にある都て肉なる諸の生物との間なる永遠の契約を記念えん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, '神ノアに言たまひけるは是は我が我と地にある諸の肉なる者との間に立たる契約の徴なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'ノアの子等の方舟より出たる者はセム、ハム、ヤペテなりきハムはカナンの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, '是等はノアの三人の子なり全地の民は是等より出て蔓延れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, '爰にノアの農夫となりて葡萄園を植ることを始しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, '葡萄酒を飮て醉天幕の中にありて裸になれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'カナンの父ハム其父のかくし所を見て外にありし二人の兄弟に告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'セムとヤペテ乃ち衣を取て倶に其肩に負け後向に歩みゆきて其父の裸體を覆へり彼等面を背にして其父の裸體を見ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'ノア酒さめて其若き子の己に爲たる事を知れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, '是に於て彼言けるはカナン詛はれよ彼は僕輩の僕となりて其兄弟に事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, '又いひけるはセムの神ヱホバは讚べきかなカナン彼の僕となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, '神ヤペテを大ならしめたまはん彼はセムの天幕に居住はんカナン其僕となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'ノア洪水の後三百五十年生存へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'ノアの齡は都て九百五十年なりき而して死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'ノアの子セム、ハム、ヤペテの傳は是なり洪水の後彼等に子等生れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'ヤペテの子はゴメル、マゴグ、マデア、ヤワン、トバル、メセク、テラスなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'ゴメルの子はアシケナズ、リパテ、トガルマなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'ヤワンの子はエリシヤ、タルシシ、キツテムおよびドダニムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, '是等より諸國の洲島の民は派分れ出て各其方言と其宗族と其邦國とに循ひて其地に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'ハムの子はクシ、ミツライム、フテおよびカナンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'クシの子はセバ、ハビラ、サブタ、ラアマ、サブテカなりラアマの子はシバおよびデダンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'クシ、ニムロデを生り彼始めて世の權力ある者となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, '彼はヱホバの前にありて權力ある獵夫なりき是故にヱホバの前にある夫權力ある獵夫ニムロデの如しといふ諺あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, '彼の國の起初はシナルの地のバベル、エレク、アツカデ、及びカルネなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, '其地より彼アッスリヤに出でニネベ、レホポテイリ、カラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'およびニネベとカラの間なるレセンを建たり是は大なる城邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'ミツライム、ルデ族アナミ族レハビ族ナフト族');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'バテロス族カスル族およびカフトリ族を生りカスル族よりペリシテ族出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'カナン其冢子シドンおよびヘテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'エブス族アモリ族ギルガシ族');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'ヒビ族アルキ族セニ族');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'アルワデ族ゼマリ族ハマテ族を生り後に至りてカナン人の宗族蔓延りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'カナン人の境はシドンよりゲラルを經てガザに至りソドム、ゴモラ、アデマ、ゼボイムに沿てレシヤにまで及べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, '是等はハムの子孫にして其宗族と其方言と其土地と其邦國に隨ひて居りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'セムはヱベルの全の子孫の先祖にしてヤペテの兄なり彼にも子女生れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'セムの子はエラム、アシユル、アルパクサデルデ、アラムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'アラムの子はウヅ、ホル、ゲテル、マシなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'アルパクサデ、シラを生みシラ、エベルを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'エベルに二人の子生れたり一人の名をペレグ(分れ)といふ其は彼の代に邦國分れたればなり其弟の名をヨクタンと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'ヨクタン、アルモダデ、シヤレフ、ハザルマウテ、ヱラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'ハドラム、ウザル、デクラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'オバル、アビマエル、シバ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'オフル、ハビラおよびヨバブを生り是等は皆ヨクタンの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, '彼等の居住所はメシヤよりして東方の山セバルにまで至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, '是等はセムの子孫にして其宗族と其方言と其土地と其邦國とに隨ひて居りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, '是等はノアの子の宗族にして其血統と其邦國に隨ひて居りぬ洪水の後是等より地の邦國の民は派分れ出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, '全地は一の言語一の音のみなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, '茲に人衆東に移りてシナルの地に平野を得て其處に居住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, '彼等互に言けるは去來甎石を作り之を善く爇んと遂に石の代に甎石を獲灰沙の代に石漆を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, '又曰けるは去來邑と塔とを建て其塔の頂を天にいたらしめん斯して我等名を揚て全地の表面に散ることを免れんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'ヱホバ降臨りて彼人衆の建る邑と塔とを觀たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'ヱホバ言たまひけるは視よ民は一にして皆一の言語を用ふ今旣に此を爲し始めたり然ば凡て其爲んと圖維る事は禁止め得られざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, '去來我等降り彼處にて彼等の言語を淆し互に言語を通ずることを得ざらしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'ヱホバ遂に彼等を彼處より全地の表面に散したまひければ彼等邑を建ることを罷たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, '是故に其名はバベル(淆亂)と呼ばる是はヱホバ彼處に全地の言語を淆したまひしに由てなり彼處よりヱホバ彼等を全地の表に散したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'セムの傳は是なりセム百歳にして洪水の後の二年にアルパクサデを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'セム、アルパクサデを生し後五百年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'アルパクサデ三十五歳に及びてシラを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'アルパクサデ、シラを生し後四百三年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'シラ三十歳におよびてエベルを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'シラ、エベルを生し後四百三年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'エベル三十四歳におよびてペレグを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'エベル、ペレグを生し後四百三十年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'ペレグ三十歳におよびてリウを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'ペレグ、リウを生し後二百九年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'リウ三十二歳におよびてセルグを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'リウ、セルグを生し後二百七年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'セルグ三十年におよびてナホルを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'セルグ、ナホルを生しのち二百年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'ナホル二十九歳に及びてテラを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'ナホル、テラを生し後百十九年生存へて男子女子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'テラ七十歳に及びてアブラム、ナホルおよびハランを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'テラの傳は是なりテラ、アブラム、ナホルおよびハランを生ハラン、ロトを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'ハランは其父テラに先ちて其生處なるカルデアのウルにて死たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'アブラムとナホルと妻を娶れりアブラムの妻の名をサライと云ナホルの妻の名をミルカと云てハランの女なりハランはミルカの父にして亦イスカの父なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'サライは石女にして子なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'テラ、カナンの地に往とて其子アブラムとハランの子なる其孫ロト及其子アブラムの妻なる其媳サライをひき挈て倶にカルデアのウルを出たりしがハランに至て其處に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'テラの齡は二百五歳なりきテラはハランにて死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, '爰にヱホバ、アブラムに言たまひけるは汝の國を出で汝の親族に別れ汝の父の家を離れて我が汝に示さん其地に至れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, '我汝を大なる國民と成し汝を祝み汝の名を大ならしめん汝は祉福の基となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, '我は汝を祝する者を祝し汝を詛ふ者を詛はん天下の諸の宗族汝によりて福禔を獲と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'アブラム乃ちヱホバの自己に言たまひし言に從て出たりロト彼と共に行りアブラムはハランを出たる時七十五歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'アブラム其妻サライと其弟の子ロトおよび其集めたる總の所有とハランにて獲たる人衆を携へてカナンの地に往んとて出で遂にカナンの地に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'アブラム其地を經過てシケムの處に及びモレの橡樹に至れり其時にカナン人其地に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, '茲にヱホバ、アブラムに顯現れて我汝の苗裔に此地に與へんといひたまへり彼處にて彼己に顯現れたまひしヱホバに壇を築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, '彼其處よりベテルの東の山に移りて其天幕を張り西にベテル東にアイありき彼處にて彼ヱホバに壇を築きヱホバの名を龥り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'アブラム尚進て南に遷れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, '茲に饑饉其地にありければアブラム、エジプトに寄寓らんとて彼處に下れり其は饑饉其地に甚しかりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, '彼近く來りてエジプトに入んとする時其妻サライに言けるは視よ我汝を觀て美麗き婦人なるを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, '是故にエジプト人汝を見る時是は彼の妻なりと言て我を殺さん然ど汝をば生存かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, '請ふ汝わが妹なりと言へ然ば我汝の故によりて安にしてわが命汝のために生存ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'アブラム、エジプトに至りし時エジプト人此婦を見て甚だ美麗となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'またパロの大臣等彼を視て彼をパロの前に譽めければ婦遂にパロの家に召入れられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, '是に於てパロ彼のために厚くアブラムを待ひてアブラム遂に羊牛僕婢牝牡の驢馬および駱駝を多く獲るに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, '時にヱホバ、アブラムの妻サライの故によりて大なる災を以てパロと其家を惱したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'パロ、アブラムを召て言けるは汝が我になしたる此事は何ぞや汝何故に彼が汝の妻なるを我に告ざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, '汝何故に彼はわが妹なりといひしや我幾彼をわが妻にめとらんとせり然ば汝の妻は此にあり挈去るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'パロ即ち彼の事を人々に命じければ彼と其妻および其有る諸の物を送りさらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'アブラム其妻および其有る諸の物と偕にエジプトを出て南の地に上れりロト彼と共にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'アブラム甚家畜と金銀に富り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, '彼南の地より其旅路に進てベテルに至りベテルとアイの間なる其以前に天幕を張たる處に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, '即ち彼が初に其處に築きたる壇のある處なり彼處にアブラム、ヱホバの名を龥り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'アブラムと偕に行しロトも羊牛および天幕を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, '其地は彼等を載て倶に居しむること能はざりき彼等は其所有多かりしに縁て倶に居ることを得ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, '斯有かばアブラムの家畜の牧者とロトの家畜の牧者の間に競爭ありきカナン人とペリジ人此時其地に居住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'アブラム、ロトに言けるは我等は兄弟の人なれば請ふ我と汝の間およびわが牧者と汝の牧者の間に競爭あらしむる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, '地は皆爾の前にあるにあらずや請ふ我を離れよ爾若左にゆかば我右にゆかん又爾右にゆかば我左にゆかんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, '是に於てロト目を擧てヨルダンの凡ての低地を瞻望みけるにヱホバ、ソドムとゴモラとを滅し給はざりし前なりければゾアルに至るまであまねく善く潤澤ひてヱホバの園の如くエジプトの地の如くなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'ロト乃ちヨルダンの低地を盡く撰とりて東に徙れり斯彼等彼此に別たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'アブラムはカナンの地に住り又ロトは低地の諸邑に住み其天幕を遷してソドムに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'ソドムの人は惡くしてヱホバの前に大なる罪人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'ロトのアブラムに別れし後ヱホバ、アブラムに言たまひけるは爾の目を擧て爾の居る處より西東北南を瞻望め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, '凡そ汝が觀る所の地は我之を永く爾と爾の裔に與べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, '我爾の後裔を地の塵沙の如くなさん若人地の塵沙を數ふることを得ば爾の後裔も數へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, '爾起て縱横に其地を行き巡るべし我之を爾に與へんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'アブラム遂に天幕を遷して來りヘブロンのマムレの橡林に住み彼處にてヱホバに壇を築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, '當時シナルの王アムラペル、エラサルの王アリオク、エラムの王ケダラオメルおよびゴイムの王テダル等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'ソドムの王ベラ、ゴモルの王ビルシア、アデマの王シナブ、ゼボイムの王セメベルおよびベラ(即ち今のゾアル)の王と戰ひをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, '是等の五人の王皆結合てシデムの谷に至れり其處は今の鹽海なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, '彼等は十二年ケダラオメルに事へ第十三年に叛けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, '第十四年にケダラオメルおよび彼と偕なる王等來りてアシタロテカルナイムのレパイム人、ハムのズジ人、シヤベキリアタイムのエミ人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'およびセイル山のホリ人を撃て曠野の傍なるエルパランに至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, '彼等歸りてエンミシパテ(即ち今のカデシ)に至りアマレク人の國を盡く撃又ハザゾンタマルに住るアモリ人を撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, '爰にソドムの王ゴモラの王アデマの王ゼボイムの王およびベラ(即ち今のゾアル)の王出てシデムの谷にて彼等と戰ひを接たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, '即ち彼五人の王等エラムの王ケダラオメル、ゴイムの王テダル、シナルの王アムラペル、エラサルの王アリオクの四人と戰へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'シデムの谷には地瀝靑の坑多かりしがソドムとゴモラの王等遁て其處に陷りぬ其餘の者は山に遁逃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, '是に於て彼等ソドムとゴモラの諸の物と其諸の食料を取て去れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, '彼等アブラムの姪ロトと其物を取て去り其は彼ソドムに住たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, '茲に遁逃者來りてヘブル人アブラムに之を告たり時にアブラムはアモリ人マムレの橡林に住りマムレはエシコルの兄弟又アネルの兄弟なり是等はアブラムと契約を結べる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'アブラム其兄弟の擄にせられしを聞しかば其熟練したる家の子三百十八人を率ゐてダンまで追いたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, '其家臣を分ちて夜に乗じて彼等を攻め彼等を撃破りてダマスコの左なるホバまで彼等を追ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'アブラム斯諸の物を奪回し亦其兄弟ロトと其物および婦人と人民を取回せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'アブラム、ケダラオメルおよび彼と偕なる王等を撃破りて歸れる時ソドムの王シヤベの谷(即ち今の王の谷)にて彼を迎へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, '時にサレムの王メルキゼデク、パンと酒を携出せり彼は至高き神の祭司なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, '彼アブラムを祝して言けるは願くは天地の主なる至高神アブラムを祝福みたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, '願くは汝の敵を汝の手に付したまひし至高神に稱譽あれとアブラム乃ち彼に其諸の物の什分の一を饋れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, '茲にソドムの王アブラムに言けるは人を我に與へ物を汝に取れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'アブラム、ソドムの王に言けるは我天地の主なる至高き神ヱホバを指て言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, '一本の絲にても鞋帶にても凡て汝の所屬は我取ざるべし恐くは汝我アブラムを富しめたりと言ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, '但少者の旣に食ひたる物および我と偕に行し人アネル、エシコルおよびマムレの分を除くべし彼等には彼等の分を取しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, '是等の事の後ヱホバの言異象の中にアブラムに臨て曰くアブラムよ懼るなかれ我は汝の干櫓なり汝の賚は甚大なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'アブラム言けるは主ヱホバよ何を我に與んとしたまふや我は子なくして居り此ダマスコのエリエゼル我が家の相續人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'アブラム又言けるは視よ爾子を我にたまはず我の家の子わが嗣子とならんとすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'ヱホバの言彼にのぞみて曰く此者は爾の嗣子となるべからず汝の身より出る者爾の嗣子となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, '斯てヱホバ彼を外に携へ出して言たまひけるは天を望みて星を數へ得るかを見よと又彼に言たまひけるは汝の子孫は是のごとくなるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'アブラム、ヱホバを信ずヱホバこれを彼の義となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, '又彼に言たまひけるは我は此地を汝に與へて之を有たしめんとて汝をカルデアのウルより導き出せるヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, '彼言けるは主ヱホバよ我いかにして我之を有つことを知るべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'ヱホバ彼に言たまひけるは三歳の牝牛と三歳の牝山羊と三歳の牡羊と山鳩および雛き鴿を我ために取れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, '彼乃ち是等を皆取て之を中より剖き其剖たる者を各相對はしめて置り但鳥は剖ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, '鷙鳥其死體の上に下る時はアブラム之を驅はらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, '斯て日の沒る頃アブラム酣く睡りしが其大に暗きを覺えて懼れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, '時にヱホバ、アブラムに言たまひけるは爾確に知るべし爾の子孫他人の國に旅人となりて其人々に服事へん彼等四百年のあひだ之を惱さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, '又其服事たる國民は我之を鞫かん其後彼等は大なる財貨を携へて出ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, '爾は安然に爾の父祖の所にゆかん爾は遐齡に逹りて葬らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, '四代に及びて彼等此に返りきたらん其はアモリ人の惡未だ貫盈ざれば也と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, '斯て日の沒て黑暗となりし時烟と火焔の出る爐其切剖たる物の中を通過り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, '是日にヱホバ、アブラムと契約をなして言たまひけるは我此地をエジプトの河より彼大河即ちユフラテ河まで爾の子孫に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, '即ちケニ人ケナズ人カデモニ人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'ヘテ人ペリジ人レパイム人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'アモリ人カナン人ギルガシ人ヱブス人の地是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'アブラムの妻サライ子女を生ざりき彼に一人の侍女ありしがエジプト人にして其名をハガルと曰り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'サライ、アブラムに言けるは視よヱホバわが子を生むことを禁めたまひければ請ふ我が侍女の所に入れ我彼よりして子女を得ることあらんとアブラム、サライの言を聽いれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'アブラムの妻サライ其侍女なるエジプト人ハガルを取て之を其夫アブラムに與へて妻となさしめたり是はアブラムがカナンの地に十年住みたる後なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, '是においてアブラム、ハガルの所に入るハガル遂に孕みければ己の孕めるを見て其女主を藐視たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'サライ、アブラムに言けるはわが蒙れる害は汝に歸すべし我わが侍女を汝の懷に與へたるに彼己の孕るを見て我を藐視ぐ願はヱホバ我と汝の間の事を鞫きたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'アブラム、サライに言けるは視よ汝の侍女は汝の手の中にあり汝の目に善と見ゆる所を彼に爲すべしサライ乃ち彼を苦めければ彼サライの面を避て逃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'ヱホバの使者曠野の泉の旁即ちシユルの路にある泉の旁にて彼に遭ひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, '言けるはサライの侍女ハガルよ汝何處より來れるや又何處に往や彼言けるは我は女主サライの面をさけて逃るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'ヱホバの使者彼に言けるは汝の女主の許に返り身を其手に任すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'ヱホバの使者又彼に言ひけるは我大に汝の子孫を増し其數を衆多して數ふることあたはざらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'ヱホバの使者又彼に言けるは汝孕めり男子を生まん其名をイシマエル(神聽知)と名くべしヱホバ汝の艱難を聽知したまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, '彼は野驢馬の如き人とならん其手は諸の人に敵し諸の人の手はこれに敵すべし彼は其諸の兄弟の東に住んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'ハガル己に諭したまへるヱホバの名をアタエルロイ(汝は見たまふ神なり)とよべり彼いふ我視たる後尚生るやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, '是をもて其井はベエルラハイロイ(我を見る活る者の井)と呼ばる是はカデシとベレデの間にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'ハガル、アブラムの男子を生めりアブラム、ハガルの生める其子の名をイシマエルと名づけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'ハガル、イシマエルをアブラムに生める時アブラムは八十六歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'アブラム九十九歳の時ヱホバ、アブラムに顯れて之に言たまひけるは我は全能の神なり汝我前に行みて完全かれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, '我わが契約を我と汝の間に立て大に汝の子孫を増ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'アブラム乃ち俯伏たり神又彼に告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '我汝とわが契約を立つ汝は衆多の國民の父となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, '汝の名を此後アブラムと呼ぶべからず汝の名をアブラハム(衆多の人の父)とよぶべし其は我汝を衆多の國民の父と爲ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, '我汝をして衆多の子孫を得せしめ國々の民を汝より起さん王等汝より出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, '我わが契約を我と汝および汝の後の世々の子孫との間に立て永久の契約となし汝および汝の後の子孫の神となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, '我汝と汝の後の子孫に此汝が寄寓る地即ちカナンの全地を與へて永久の產業となさん而して我彼等の神となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, '神またアブラハムに言たまひけるは然ば汝と汝の後の世々の子孫わが契約を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, '汝等の中の男子は咸割禮を受べし是は我と汝等および汝の後の子孫の間の我が契約にして汝等の守るべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, '汝等其陽の皮を割べし是我と汝等の間の契約の徴なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, '汝等の代々の男子は家に生れたる者も異邦人より金にて買たる汝の子孫ならざる者も皆生れて八日に至らば割禮を受べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, '汝の家に生れたる者も汝の金にて買たる者も割禮を受ざるべからず斯我契約汝等の身にありて永久の契約となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, '割禮を受ざる男兒即ち其陽の皮を割ざる者は我契約を破るによりて其人其民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, '神又アブラハムの言たまひけるは汝の妻サライは其名をサライと稱ぶべからず其名をサラと爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, '我彼を祝み彼よりして亦汝に一人の男子を授けん我彼を祝み彼をして諸邦の民の母とならしむべし諸の民の王等彼より出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'アブラハム俯伏て哂ひ其心に謂けるは百歳の人に豈で子の生るることあらんや又サラは九十歳なれば豈で產ことをなさんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'アブラハム遂に神にむかひて願くはイシマエルの汝のまへに生存へんことをと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, '神言たまひけるは汝の妻サラ必ず子を生ん汝其名をイサクと名くべし我彼および其後の子孫と契約を立て永久の契約となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, '又イシマエルの事に關ては我汝の願を聽たり視よ我彼を祝みて多衆の子孫を得さしめ大に彼の子孫を増すべし彼十二の君王を生ん我彼を大なる國民となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, '然どわが契約は我翌年の今頃サラが汝に生ん所のイサクと之を立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, '神アブラハムと言ことを竟へ彼を離れて昇り給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, '是に於てアブラハム神の己に言たまへる如く此日其子イシマエルと凡て其家に生れたる者および凡て其金にて買たる者即ちアブラハムの家の人の中なる諸の男を將きたりて其陽の皮を割たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'アブラハムは其陽の皮を割れたる時九十九歳');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, '其子イシマエルは其陽の皮を割れたる時十三歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, '是日アブラハムと其子イシマエル割禮を受たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, '又其家の人家に生れたる者も金にて異邦人より買たる者も皆彼とともに割禮を受たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'ヱホバ、マムレの橡林にてアブラハムに顯現たまへり彼は日の熱き時刻天幕の入口に坐しゐたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, '目を擧て見たるに視よ三人の人其前に立り彼見て天幕の入口より趨り行て之を迎へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, '身を地に鞠めて言けるは我が主よ我若汝の目のまへに恩を得たるならば請ふ僕を通り過すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, '請ふ少許の水を取きたらしめ汝等の足を濯ひて樹の下に休憇たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, '我一口のパンを取來らん汝等心を慰めて然る後過ゆくべし汝等僕の所に來ればなり彼等言ふ汝が言るごとく爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, '是においてアブラハム天幕に急ぎいりてサラの許に至りて言けるは速に細麺三セヤを取り捏てパンを作るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, '而してアブラハム牛の群に趨ゆき犢の柔にして善き者を取りきたりて少者に付しければ急ぎて之を調理ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'かくてアブラハム牛酪と牛乳および其調理へたる犢を取て彼等のまへに供へ樹の下にて其側に立り彼等乃ち食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, '彼等アブラハムに言けるは爾の妻サラは何處にあるや彼言ふ天幕にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, '其一人言ふ明年の今頃我必ず爾に返るべし爾の妻サラに男子あらんサラ其後なる天幕の入口にありて聞ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, '抑アブラハムとサラは年邁み老いたる者にしてサラには婦人の常の經已に息たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, '是故にサラ心に哂ひて言けるは我は老衰へ吾が主も亦老たる後なれば我に樂あるべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'ヱホバ、アブラハムに言たまひけるは何故にサラは哂ひて我老たれば果して子を生ことあらんと言ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'ヱホバに豈爲し難き事あらんや時至らば我定めたる期に爾に歸るべしサラに男子あらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'サラ懼れたれば承ずして我哂はずと言へりヱホバ言たまひけるは否汝哂へるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, '斯て其人々彼處より起てソドムの方を望みければアブラハム彼等を送らんとて倶に行り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'ヱホバ言ひ給けるは我爲んとする事をアブラハムに隱すべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'アブラハムは必ず大なる強き國民となりて天下の民皆彼に由て福を獲に至るべきに在ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, '其は我彼をして其後の兒孫と家族とに命じヱホバの道を守りて公儀と公道を行しめん爲に彼をしれり是ヱホバ、アブラハムに其曾て彼に就て言し事を行はん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'ヱホバ又言給ふソドムとゴモラの號呼大なるに因り又其罪甚だ重に因て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, '我今下りて其號呼の我に逹れる如くかれら全く行ひたりしやを見んとす若しからずば我知るに至らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, '其人々其處より身を旋してソドムに赴むけりアブラハムは尚ほヱホバのまへに立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'アブラハム近よりて言けるは爾は義者をも惡者と倶に滅ぼしたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, '若邑の中に五十人の義者あるも汝尚ほ其處を滅ぼし其中の五十人の義者のためにこれを恕したまはざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'なんぢ斯の如く爲て義者と惡者と倶に殺すが如きは是あるまじき事なり又義者と惡者を均等するが如きもあるまじき事なり天下を鞫く者は公儀を行ふ可にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'ヱホバ言たまひけるは我若ソドムに於て邑の中に五十人の義者を看ば其人々のために其處を盡く恕さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'アブラハム應へていひけるは我は塵と灰なれども敢て我主に言上す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, '若五十人の義者の中五人缺たらんに爾五人の缺たるために邑を盡く滅ぼしたまふやヱホバ言たまひけるは我若彼處に四十五人を看ば滅さざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'アブラハム又重ねてヱホバに言上して曰けるは若彼處に四十人看えなば如何ヱホバ言たまふ我四十人のために之をなさじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'アブラハム曰ひけるは請ふわが主よ怒らずして言しめたまへ若彼處に三十人看えなば如何ヱホバいひたまふ我三十人を彼處に看ば之を爲じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'アブラハム言ふ我あへてわが主に言上す若彼處に二十人看えなば如何ヱホバ言たまふ我二十人のためにほろぼさじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'アブラハム言ふ請ふわが主怒らずして今一度言しめたまへ若かしこに十人看えなば如何ヱホバ言たまふ我十人のためにほろぼさじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'ヱホバ、アブラハムと言ふことを終てゆきたまへりアブラハムおのれの所にかへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, '其二個の天使黄昏にソドムに至るロト時にソドムの門に坐し居たりしがこれを視起て迎へ首を地にさげて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, '言けるは我主よ請ふ僕の家に臨み足を濯ひて宿りつとに起て途に遄征たまへ彼等言ふ否我等は街衢に宿らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, '然ど固く強ければ遂に彼の所に臨みて其家に入るロト乃ち彼等のために筵を設け酵いれぬパンを炊て食はしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, '斯て未だ寢ざる前に邑の人々即ちソドムの人老たるも若きも諸共に四方八方より來たれる民皆其家を環み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'ロトを呼て之に言けるは今夕爾に就たる人は何處にをるや彼等を我等の所に携へ出せ我等之を知らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'ロト入口に出て其後の戸を閉ぢ彼等の所に至りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, '言けるは請ふ兄弟よ惡き事を爲すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, '我に未だ男知ぬ二人の女あり請ふ我之を携へ出ん爾等の目に善と見ゆる如く之になせよ唯此人等は旣に我家の蔭に入たれば何をも之になすなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, '彼等曰ふ爾退け又言けるは此人は來り寓れる身なるに恒に士師とならんとす然ば我等彼等に加ふるよりも多くの害を爾に加へんと遂に彼等酷しく其人ロトに逼り前よりて其戸を破んとせしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, '彼二人其手を舒しロトを家の内に援いれて其戸を閉ぢ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, '家の入口にをる人衆をして大なるも小も倶に目を眩しめければ彼等遂に入口を索ぬるに困憊たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, '斯て二人ロトに言けるは外に爾に屬する者ありや汝の婿子女および凡て邑にをりて爾に屬する者を此所より携へ出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, '此處の號呼ヱホバの前に大になりたるに因て我等之を滅さんとすヱホバ我等を遣はして之を滅さしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'ロト出て其女を娶る婿等に告て言けるはヱホバが邑を滅したまふべければ爾等起て此處を出よと然ど婿等は之を戲言と視爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, '曉に及て天使ロトを促して言けるは起て此なる爾の妻と二人の女を携へよ恐くは爾邑の惡とともに滅されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, '然るに彼遲延ひしかば二人其手と其妻の手と其二人の女の手を執て之を導き出し邑の外に置りヱホバ斯彼に仁慈を加へたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, '旣に之を導き出して其一人曰けるは逃遁て汝の生命を救へ後を回顧るなかれ低地の中に止るなかれ山に遁れよ否ずば爾滅されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'ロト彼等に言けるはわが主よ請ふ斯したまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, '視よ僕爾の目のまへに恩を得たり爾大なる仁慈を吾に施してわが生命を救たまふ吾山に遁る能はず恐くは災害身に及びて死るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, '視よ此邑は遁ゆくに近くして且小し我をして彼處に遁れしめよしからば吾生命全からん是は小き邑なるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, '天使之にいひけるは視よ我此事に關ても亦爾の願を容たれば爾が言ふところの邑を滅さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, '急ぎて彼處に遁れよ爾が彼處に至るまでは我何事をも爲を得ずと是に因て其邑の名はゾアル(小し)と稱る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'ロト、ゾアルに至れる時日地の上に昇れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'ヱホバ硫黄と火をヱホバの所より即ち天よりソドムとゴモラに雨しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, '其邑と低地と其邑の居民および地に生るところの物を盡く滅したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'ロトの妻は後を回顧たれば鹽の柱となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'アブラハム其朝夙に起て其嘗てヱホバの前に立たる處に至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'ソドム、ゴモラおよび低地の全面を望み見るに其地の烟燄窰の烟のごとくに騰上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, '神低地の邑を滅したまふ時即ちロトの住る邑を滅したまふ時に當り神アブラハムを眷念て斯其滅亡の中よりロトを出したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, '斯てロト、ゾアルに居ることを懼れたれば其二人の女と偕にゾアルを出て上りて山に居り其二人の女子とともに巖穴に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, '茲に長女季女にいひけるは我等の父は老いたり又此地には我等に偶て世の道を成す人あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, '然ば我等父に酒を飮せて與に寢ね父に由て子を得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, '遂に其夜父に酒を飮せ長女入て其父と與に寢たり然るにロトは女の起臥を知ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, '翌日長女季女に言けるは我昨夜わが父と寢たり我等此夜又父に酒をのません爾入て與に寢よわれらの父に由て子を得ることをえんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, '乃ち其夜も亦父に酒をのませ季女起て父と與に寢たりロトまた女の起臥を知ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, '斯ロトの二人の女其父によりて孕みたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, '長女子を生み其名をモアブと名く即ち今のモアブ人の先祖なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, '季女も亦子を生み其名をベニアンミと名く即ち今のアンモニ人の先祖なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'アブラハム彼處より徒りて南の地に至りカデシとシユルの間に居りゲラルに寄留り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'アブラハム其妻サラを我妹なりと言しかばゲラルの王アビメレク人を遣してサラを召入たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, '然るに神夜の夢にアビメレクに臨みて之に言たまひけるは汝は其召入たる婦人のために死るなるべし彼は夫ある者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'アビメレク未だ彼に近づかざりしかば言ふ主よ汝は義き民をも殺したまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, '彼は我に是はわが妹なりと言しにあらずや又婦も自彼はわが兄なりと言たり我全き心と潔き手をもて此をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, '神又夢に之に言たまひけるは然り我汝が全き心をもて之をなせるを知りたれば我も汝を阻めて罪を我に犯さしめざりき彼に觸るを容ざりしは是がためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, '然ば彼の妻を歸せ彼は預言者なれば汝のために祈り汝をして生命を保しめん汝若歸ずば汝と汝に屬する者皆必死るべきを知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, '是に於てアビメレク其朝夙に起て臣僕を悉く召し此事を皆語り聞せければ人々甚く懼れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, '斯てアビメレク、アブラハムを召て之に言けるは爾我等に何を爲すや我何の惡き事を爾になしたれば爾大なる罪を我とわが國に蒙らしめんとせしか爾爲べからざる所爲を我に爲したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'アビメレク又アブラハムに言けるは爾何を見て此事を爲たるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'アブラハム言けるは我此處はかならず神を畏れざるべければ吾妻のために人我を殺さんと思ひたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, '又我は誠にわが妹なり彼はわが父の子にしてわが母の子にあらざるが遂に我妻となりたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, '神我をして吾父の家を離れて周遊しめたまへる時に當りて我彼に爾我等が至る處にて我を爾の兄なりと言へ是は爾が我に施す恩なりと言たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'アビメレク乃ち羊牛僕婢を將てアブラハムに與へ其妻サラ之に歸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, '而してアビメレク言けるは視よ我地は爾のまへにあり爾の好むところに住め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, '又サラに言けるは視よ我爾の兄に銀千枚を與へたり是は爾および諸の人にありし事等につきて爾の目を蔽ふ者なり斯爾償贖を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, '是に於てアブラハム神に祈りければ神アビメレクと其妻および婢を醫したまひて彼等子を產むにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'ヱホバさきにはアブラハムの妻サラの故をもてアビメレクの家の者の胎をことごとく閉たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'ヱホバ其言し如くサラを眷顧みたまふ即ちヱホバ其語しごとくサラに行ひたまひしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'サラ遂に孕み神のアブラハムに語たまひし期日に及びて年老たるアブラハムに男子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'アブラハム其生れたる子即ちサラが己に生る子の名をイサクと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'アブラハム神の命じたまひし如く八日に其子イサクに割禮を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'アブラハムは其子イサクの生れたる時百歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'サラ言けるは神我を笑はしめたまふ聞く者皆我とともに笑はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, '又曰けるは誰かアブラハムにサラ子女に乳を飮しむるにいたらんと言しものあらん然に彼が年老るに及びて男子を生たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, '偖其子長育ちて遂に乳を離るイサクの乳を離るる日にアブラハム大なる饗宴を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, '時にサラ、エジプト人ハガルがアブラハムに生たる子の笑ふを見て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'アブラハムに言けるは此婢と其子を遂出せ此婢の子は吾子イサクと共に嗣子となるべからざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'アブラハム其子のために甚く此事を憂たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, '神アブラハムに言たまひけるは童兒のため又汝の婢のために之を憂るなかれサラが汝に言ところの言は悉く之を聽け其はイサクより出る者汝の裔と稱らるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, '又婢の子も汝の胤なれば我之を一の國となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'アブラハム朝夙に起てパンと水の革嚢とを取りハガルに與へて之を其肩に負せ其子を携へて去しめければ彼往てベエルシバの曠野に躑躅しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, '革嚢の水遂に罄たれば子を灌木の下に置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, '我子の死るを見るに忍ずといひて遙かに行き箭逹を隔てて之に對ひ坐しぬ斯相嚮ひて坐し聲をあげて泣く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, '神其童兒の聲を聞たまふ神の使即ち天よりハガルを呼て之に言けるはハガルよ何事ぞや懼るるなかれ神彼處にをる童兒の聲を聞たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, '起て童兒を起し之を汝の手に抱くべし我之を大なる國となさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, '神ハガルの目を開きたまひければ水の井あるを見ゆきて革嚢に水を充し童兒に飮しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, '神童兒と偕に在す彼遂に成長り曠野に居りて射者となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'パランの曠野に住り其母彼のためにエジプトの國より妻を迎へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, '當時アビメレクと其軍勢の長ピコル、アブラハムに語て言けるは汝何事を爲にも神汝とともに在す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, '然ば汝が我とわが子とわが孫に僞をなさざらんことを今此に神をさして我に誓へ我が厚情をもて汝をあつかふごとく汝我と此汝が寄留る地とに爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'アブラハム言ふ我誓はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'アブラハム、アビメレクの臣僕等が水の井を奪ひたる事につきてアビメレクを責ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'アビメレク言ふ我誰が此事を爲しを知ず汝我に告しこと无く又我今日まで聞しことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'アブラハム乃ち羊と牛を取て之をアビメレクに與ふ斯て二人契約を結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'アブラハム牝の羔七を分ち置ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'アビメレク、アブラハムに言ふ汝此七の牝の羔を分ちおくは何のためなるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'アブラハム言けるは汝わが手より此七の牝の羔を取りて我が此井を掘たる證據とならしめよと彼等二人彼處に誓ひしによりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, '其處をベエルシバ(盟約の井)と名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, '斯彼等ベエルシバにて契約を結びアビメレクと其軍勢の長ピコルは起てペリシテ人の國に歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'アブラハム、ベエルシバに柳を植ゑ永遠に在す神ヱホバの名を彼處に龥り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, '斯してアブラハム久くペリシテ人の地に留寄りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, '是等の事の後神アブラハムを試みんとて之をアブラハムよと呼たまふ彼言ふ我此にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'ヱホバ言給ひけるは爾の子爾の愛する獨子即ちイサクを携てモリアの地に到りわが爾に示さんとする彼所の山に於て彼を燔祭として獻ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'アブラハム朝夙に起て其驢馬に鞍おき二人の少者と其子イサクを携へ且燔祭の柴薪を劈りて起て神の己に示したまへる處におもむきけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, '三日におよびてアブラハム目を擧て遙に其處を見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, '是に於てアブラハム其少者に言けるは爾等は驢馬とともに此に止れ我と童子は彼處にゆきて崇拜を爲し復爾等に歸ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'アブラハム乃ち燔祭の柴薪を取て其子イサクに負せ手に火と刀を執て二人ともに往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'イサク父アブラハムに語て父よと曰ふ彼答て子よ我此にありといひければイサク即ち言ふ火と柴薪は有り然ど燔祭の羔は何處にあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'アブラハム言けるは子よ神自ら燔祭の羔を備へたまはんと二人偕に進みゆきて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, '遂に神の彼に示したまへる處に到れり是においてアブラハム彼處に壇を築き柴薪を臚列べ其子イサクを縛りて之を壇の柴薪の上に置せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, '斯してアブラハム手を舒べ刀を執りて其子を宰んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, '時にヱホバの使者天より彼を呼てアブラハムよアブラハムよと言へり彼言ふ我此にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, '使者言けるは汝の手を童子に按るなかれ亦何をも彼に爲べからず汝の子即ち汝の獨子をも我ために惜まざれば我今汝が神を畏るを知ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, '茲にアブラハム目を擧て視れば後に牡綿羊ありて其角林叢に繋りたりアブラハム即ち往て其牡綿羊を執へ之を其子の代に燔祭として獻げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'アブラハム其處をヱホバエレ(ヱホバ預備たまはん)と名く是に縁て今日もなほ人々山にヱホバ預備たまはんといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'ヱホバの使者再天よりアブラハムを呼て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, '言けるはヱホバ諭したまふ我己を指て誓ふ汝是事を爲し汝の子即ち汝の獨子を惜まざりしに因て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, '我大に汝を祝み又大に汝の子孫を増して天の星の如く濱の沙の如くならしむべし汝の子孫は其敵の門を獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, '又汝の子孫によりて天下の民皆福祉を得べし汝わが言に遵ひたるによりてなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, '斯てアブラハム其少者の所に歸り皆たちて偕にベエルシバにいたれりアブラハムはベエルシバに住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, '是等の事の後アブラハムに告る者ありて言ふミルカ亦汝の兄弟ナホルにしたがひて子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, '長子はウヅ其弟はブヅ其次はケムエル是はアラムの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, '其次はケセデ、ハゾ、ピルダシ、ヱデラフ、ベトエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'ベトエルはリベカを生り是八人はミルカがアブラハムの兄弟ナホルに生たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'ナホルの妾名はルマといふ者も亦テバ、ガハム、タハシおよびマアカを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'サラ百二十七歳なりき是即ちサラの齡の年なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'サラ、キリアテアルバにて死り是はカナンの地のヘブロンなりアブラハム至りてサラのために哀み且哭り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, '斯てアブラハム死人の前より起ち出てヘテの子孫に語りて言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '我は汝等の中の賓旅なり寄居者なり請ふ汝等の中にて我は墓地を與へて吾が所有となし我をして吾が死人を出し葬ることを得せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'ヘテの子孫アブラハムに應て之に言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '我主よ我等に聽たまへ我等の中にありて汝は神の如き君なり我等の墓地の佳者を擇みて汝の死人を葬れ我等の中一人も其墓地を汝にをしみて汝をしてその死人を葬らしめざる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, '是に於てアブラハム起ち其地の民ヘテの子孫に對て躬を鞠む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, '而して彼等と語ひて言けるは若我をしてわが死人を出し葬るを得せしむる事汝等の意ならば請ふ我に聽て吾ためにゾハルの子エフロンに求め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, '彼をして其野の極端に有るマクペラの洞穴を我に與へしめよ彼其十分の値を取て之を我に與へ汝等の中にてわが所有なる墓地となさば善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, '時にエフロン、ヘテの子孫の中に坐しゐたりヘテ人エフロン、ヘテの子孫即ち凡て其邑の門に入る者の聽る前にてアブラハムに應へて言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '吾主よ我に聽たまへ其野は我汝に與ふ又其中の洞穴も我之を汝に與ふ我吾民なる衆人の前にて之を汝にあたふ汝の死人を葬れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, '是に於てアブラハム其地の民の前に躬を鞠たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, '而して彼其地の民に聽る前にてエフロンに語りて言けるは汝若之を肯はば請ふ吾に聽け我其野の値を汝に償はん汝之を吾より取れ我わが死人を彼處に葬らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'エフロン、アブラハムに答て曰けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'わが主よ我に聽たまへ彼地は銀四百シケルに當る是は我と汝の間に豈道に足んや然ば汝の死人を葬れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'アブラハム、エフロンの言に從ひエフロンがヘテの子孫の聽る前にて言たる所の銀を秤り商買の中の通用銀四百シケルを之に與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'マムレの前なるマクペラに在るエフロンの野は野も其中の洞穴も野の中と其四周の堺にある樹も皆');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'ヘテの子孫の前即ち凡て其邑に入る者の前にてアブラハムの所有と定りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, '厥後アブラハム其妻サラをマムレの前なるマクペラの野の洞穴に葬れり是即ちカナンの地のヘブロンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, '斯く其野と其中の洞穴はヘテの子孫之をアブラハムの所有なる墓地と定めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'アブラハム年邁て老たりヱホバ萬の事に於てアブラハムを祝みたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, '茲にアブラハム其凡の所有を宰る其家の年邁なる僕に言けるは請ふ爾の手を吾髀の下に置よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, '我爾をして天の神地の神ヱホバを指て誓はしめん即ち汝わが偕に居むカナン人の女の中より吾子に妻を娶るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, '汝わが故國に往き吾親族に到りて吾子イサクのために妻を娶れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, '僕彼に言けるは倘女我に從ひて此地に來ることを好まざる事あらん時は我爾の子を彼汝が出來りし地に導き歸るべきか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'アブラハム彼に曰けるは汝愼みて吾子を彼處に携かへるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, '天の神ヱホバ我を導きて吾父の家とわが親族の地を離れしめ我に語り我に誓ひて汝の子孫に此地を與へんと言たまひし者其使を遣して汝に先たしめたまはん汝彼處より我子に妻を娶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, '若女汝に從ひ來る事を好ざる時は汝吾此誓を解るべし唯我子を彼處に携へかへるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, '是に於て僕手を其主人アブラハムの髀の下に置て此事について彼に誓へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, '斯て僕其主人の駱駝の中より十頭の駱駝を取りて出たてり即ち其主人の諸の佳物を手にとりて起てメソポタミアに往きナホルの邑に至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, '其駱駝を邑の外にて井の傍に跪伏しめたり其時は黄昏にて婦女等の水汲にいづる時なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, '斯して彼言けるは吾主人アブラハムの神ヱホバよ願くは今日我にその者を逢しめわが主人アブラハムに恩惠を施し給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, '我この水井の傍に立ち邑の人の女等水を汲に出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, '我童女に向ひて請ふ汝の瓶をかたむけて我に飮しめよと言んに彼答へて飮め我また汝の駱駝にも飮しめんと言ば彼は汝が僕イサクの爲に定め給ひし者なるべし然れば我汝の吾主人に恩惠を施し給ふを知らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, '彼語ふことを終るまへに視よリベカ瓶を肩にのせて出きたる彼はアブラハムの兄弟ナホルの妻ミルカの子ベトエルに生れたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, '其童女は觀に甚だ美しく且處女にして未だ人に適しことあらず彼井に下り其瓶に水を盈て上りしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, '僕はせゆきて之にあひ請ふ我をして汝の瓶より少許の水を飮しめよといひけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, '彼主よ飮たまへといひて乃ち急ぎ其瓶を手におろして之にのましめたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, '飮せをはりて言ふ汝の駱駝のためにも其飮をはるまで水を汲て飽しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, '急ぎて其瓶を水鉢にあけ又汲んとて井にはせゆき其諸の駱駝のために汲みたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, '其人之を見つめヱホバが其途に幸福をくだしたまふや否やをしらんとして默し居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, '茲に駱駝飮をはりしかば其人重半シケルの金の鼻環一箇と重十シケルの金の手釧二箇をとりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, '言けるは汝は誰の女なるや請ふ我に告よ汝の父の家に我等が宿る隙地ありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, '女彼に曰けるは我はミルカがナホルに生みたる子ベトエルの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, '又彼にいひけるは家には藁も飼草も多くあり且宿る隙地もあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, '是に於て其人伏てヱホバを拜み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, '言けるは吾主人アブラハムの神ヱホバは讃美べきかなわが主人に慈惠と眞實とを缺きたまはず我途にありしにヱホバ我を吾主人の兄弟の家にみちびきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, '茲に童女走行て其母の家に此等の事を告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'リベカに一人の兄あり其名をラバンといふラバンはせいで井にゆきて其人の許につく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'すなはち彼鼻環および其妹の手の手釧を見又其妹リベカが其人斯我に語りといふを聞て其人の所に到り見るに井の側らにて駱駝の傍にたちゐたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, '之に言けるは汝ヱホバに祝るる者よ請ふ入れ奚ぞ外にたつや我家を備へ且駱駝のために所をそなへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, '是に於て其人家にいりぬラバン乃ち其駱駝の負を釋き藁と飼草を駱駝にあたへ又水をあたへて其人の足と其從者の足をあらはしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, '斯して彼の前に食をそなへたるに彼言ふ我はわが事をのぶるまでは食はじとラバン語れといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, '彼言ふわれはアブラハムの僕なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'ヱホバ大にわが主人をめぐみたまひて大なる者とならしめ又羊牛金銀僕婢駱駝驢馬をこれにたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'わが主人の妻サラ年老てのちわが主人に男子をうみければ主人其所有を悉く之に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'わが主人我を誓せて言ふ吾すめるカナンの地の人の女子の中よりわが子に妻を娶るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, '汝わが父の家にゆきわが親族にいたりわが子のために妻をめとれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, '我わが主人にいひけるは倘女我にしたがひて來ずば如何');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, '彼我にいひけるは吾事ふるところのヱホバ其使者を汝とともに遣はして汝の途に幸福を降したまはん爾わが親族わが父の家より吾子に妻をめとるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, '汝わが親族に至れる時はわが誓を解さるべし若彼等汝にあたへずば汝はわが誓をゆるさるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, '我今日井に至りて謂けらくわが主人アブラハムの神ヱホバねがはくはわがゆく途に幸福を降したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, '我はこの井水の傍に立つ水を汲にいづる處女あらん時我彼にむかひて請ふ汝の瓶より少許の水を我にのましめよと言んに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, '若我に答へて汝飮め我亦汝の駱駝のためにも汲んと言ば是ヱホバがわが主人の子のために定たまひし女なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, '我心の中に語ふことを終るまへにリベカ其瓶を肩にのせて出來り井にくだりて水を汲みたるにより我彼に請ふ我にのましめよと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, '彼急ぎ其瓶を肩よりおろしていひけるは飮めまた汝の駱駝にものましめんと是に於て我飮しが彼また駱駝にものましめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, '我彼に問て汝は誰の女なるやといひければミルカがナホルに生たる子ベトエルの女なりといふ是に於て我其鼻に環をつけ其手に手釧をつけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, '而して我伏てヱホバを拜み吾主人アブラハムの神ヱホバを頌美たりヱホバ我を正き途に導きてわが主人の兄弟の女を其子のために娶しめんとしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'されば汝等若わが主人にむかひて慈惠と眞誠をもて事をなさんと思はば我に告よ然ざるも亦我に告よ然ば我右か左におもむくをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'ラバンとベトエル答て言けるは此事はヱホバより出づ我等汝に善惡を言ふあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, '視よリベカ汝の前にをる携へてゆき彼をしてヱホバの言たまひし如く汝の主人の子の妻とならしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'アブラハムの僕彼等の言を聞て地に伏てヱホバを拜めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, '是に於て僕銀の飾品金の飾品および衣服をとりいだしてリベカに與へ亦其兄と母に寶物をあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, '是に於て彼および其從者等食飮して宿りしが朝起たる時彼言我をして吾主人に還らしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'リベカの兄と母言けるは童女を數日の間少くも十日我等と偕にをらしめよしかるのち彼ゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, '彼人之に言ヱホバ吾途に福祉をくだしたまひたるなれば我を阻むるなかれ我を歸してわが主人に往しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, '彼等いひけるは童女をよびて其言を問んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, '即ちリベカを呼て之に言けるは汝此人と共に往や彼言ふ往ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, '是に於て彼等妹リベカと其乳媼およびアブラハムの僕と其從者を遣り去しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, '即ち彼等リベカを祝して之にいひけるはわれらの妹よ汝千萬の人の母となれ汝の子孫をして其仇の門を獲しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, '是に於てリベカ起て其童女等とともに駱駝にのりて其人にしたがひ往く僕乃ちリベカを導きてさりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, '茲にイサク、ラハイロイの井の路より來れり南の國に住居たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'しかしてイサク黄昏に野に出て默想をなしたりしが目を擧て見しに駱駝の來るあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'リベカ目をあげてイサクを見駱駝をおりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, '僕にいひけるは野をあゆみて我等にむかひ來る者は何人なるぞ僕わが主人なりといひければリベカ覆衣をとりて身をおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, '茲に僕其凡てなしたる事をイサクに告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'イサク、リベカを其母サラの天幕に携至りリベカを娶りて其妻となしてこれを愛したりイサクは母にわかれて後茲に慰籍を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'アブラハム再妻を娶る其名をケトラといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, '彼ジムラン、ヨクシヤン、メダン、ミデアン、イシバク、シユワを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'ヨクシヤン、シバとデダンを生むデダンの子はアッシユリ族レトシ族リウミ族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'ミデアンの子はエパ、エペル、ヘノク、アビダ、エルダアなり是等は皆ケトラの子孫なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'アブラハム其所有を盡くイサクに與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'アブラハムの妾等の子にはアブラハム其生る間の物をあたへて之をして其子イサクを離れて東にさりて東の國に至らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'アブラハムの生存へたる齡の日は即ち百七十五年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'アブラハム遐齡に及び老人となり年滿て氣たえ死て其民に加る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, '其子イサクとイシマエル之をヘテ人ゾハルの子エフロンの野なるマクペラの洞穴に葬れり是はマムレの前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, '即ちアブラハムがヘテの子孫より買たる野なり彼處にアブラハムと其妻サラ葬らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'アブラハムの死たる後神其子イサクを祝みたまふイサクはベエルラハイロイの邊に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'サラの侍婢なるエジプト人ハガルがアブラハムに生たる子イシマエルの傳は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'イシマエルの子の名は其名氏と其世代に循ひて言ば是のごとしイシマエルの長子はネバヨテなり其次はケダル、アデビエル、ミブサム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'ミシマ、ドマ、マツサ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'ハダデ、テマ、ヱトル、ネフシ、ケデマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, '是等はイシマエルの子なり是等は其郷黨を其營にしたがひて言る者にして其國に循ひていへば十二の牧伯なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'イシマエルの齡は百三十七歳なりき彼いきたえ死て其民にくははる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'イシマエルの子等はハビラよりエジプトの前なるシユルまでの間に居住てアッスリヤまでにおよべりイシマエルは其すべての兄弟等のまへにすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'アブラハムの子イサクの傳は左のごとしアブラハム、イサクを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'イサク四十歳にしてリベカを妻に娶れりリベカはパダンアラムのスリア人ベトエルの女にしてスリア人ラバンの妹なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'イサク其妻の子なきに因て之がためにヱホバに祈願をたてければヱホバ其ねがひを聽たまへり遂に其妻リベカ孕みしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, '其子胎の内に爭そひければ然らば我いかで斯てあるべきと言て往てヱホバに問に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'ヱホバ彼に言たまひけるは二の國民汝の胎にあり二の民汝の腹より出て別れん一の民は一の民よりも強かるべし大は小に事へんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'かくて臨月みちて見しに胎には孿ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, '先に出たる者は赤くして躰中裘の如し其名をエサウと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, '其後に弟出たるが其手にエサウの踵を持り其名をヤコブとなづけたりリベカが彼等を生し時イサクは六十歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, '茲に童子人となりしがエサウは巧なる獵人にして野の人となりヤコブは質樸なる人にして天幕に居ものとなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'イサクは麆を嗜によりてエサウを愛したりしがリベカはヤコブを愛したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, '茲にヤコブ羹を煮たり時にエサウ野より來りて憊れ居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'エサウ、ヤコブにむかひ我憊れたれば請ふ其紅羹其處にある紅羹を我にのませよといふ是をもて彼の名はエドム(紅)と稱らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'ヤコブ言けるは今日汝の家督の權を我に鬻れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'エサウいふ我は死んとして居る此家督の權我に何の益をなさんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'ヤコブまた言けるは今日我に誓へと彼すなはち誓て其家督の權をヤコブに鬻ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, '是に於てヤコブ、パンと扁豆の羹とをエサウに與へければ食且飮て起て去り斯エサウ家督の權を藐視じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'アブラハムの時にありし最初の饑饉の外に又其國に饑饉ありければイサク、ゲラルに往てペリシテ人の王アビメレクの許にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, '時にヱホバ彼にあらはれて言たまひけるはエジプトに下るなかれ吾汝に示すところの地にをれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, '汝此地にとどまれ我汝と共にありて汝を祝まん我是等の國を盡く汝および汝の子孫に與へ汝の父アブラハムに誓ひたる誓言を行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'われ汝の子孫を増て天の星のごとくなし汝の子孫に凡て是等の國を與へん汝の子孫によりて天下の國民皆福祉を獲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, '是はアブラハムわが言に順ひわが職守とわが誡命とわが憲法とわが律法を守りしに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'イサク乃ちゲラルに居しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, '處の人其妻の事をとへば我妹なりと言ふリベカは觀に美麗かりければ其處の人リベカの故をもて我を殺さんと謂て彼をわが妻と言をおそれたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'イサク久しく彼處にをりし後一日ペリシテ人の王アビメレク\\牖より望みてイサクが其妻リベカと嬉戲るを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, '是に於てアビメレク、イサクを召て言けるは彼は必ず汝の妻なり汝なんぞ吾妹といひしやイサク彼に言けるは恐くは我彼のために死るならんと思たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'アビメレクいひけるは汝なんぞ此事を我等になすや民の一人もし輕々しく汝の妻と寢ることあらんその時は汝罪を我等に蒙らしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'アビメレク乃ちすべて民に皆命じて此人と其妻にさはるものは必ず死すべしと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'イサク彼地に種播て其年に百倍を獲たりヱホバ彼を祝みたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, '其人大になりゆきて進て盛になり遂に甚だ大なる者となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, '即ち羊と牛と僕從を多く有しかばペリシテ人彼を嫉みたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, '其父アブラハムの世に其父の僕從が掘たる諸の井はペリシテ人之をふさぎて土を之にみてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, '茲にアビメレク、イサクに言けるは汝は大に我等よりも強大ければ我等をはなれて去れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'イサク乃ち彼處をさりてゲラルの谷に天幕を張て其處に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, '其父アブラハムの世に掘たる水井をイサク茲に復び鑿り其はアブラハムの死たる後ペリシテ人之を塞ぎたればなり斯してイサク其父が之に名けたる名をもて其名となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'イサクの僕谷に掘て其處に泉の湧出る井を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'ゲラルの牧者此水は我儕の所屬なりといひてイサクの僕と爭ひければイサク其井の名をエセク(競爭)と名けたり彼等が己と之を競爭たるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, '是に於て又他の井を鑿しが彼等是をも爭ひければ其名をシテナ(敵)となづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'イサク乃ち彼處より遷りて他の井を鑿けるが彼等之をあらそはざりければ其名をレホボテ(廣塲)と名けて言けるは今ヱホバ我等の處所を廣くしたまへり我等此地を繁衍ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, '斯て彼其處よりベエルシバにのぼりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, '其夜ヱホバ彼にあらはれて言たまひけるは我は汝の父アブラハムの神なり懼るるなかれ我汝と偕にありて汝を祝み我僕アブラハムのために汝の子孫を増んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, '是に於て彼處に壇を築きてヱホバの名を龥び天幕を彼處に張り彼處にてイサクの僕井を鑿り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, '茲にアビメレク其友アホザテ及び其軍勢の長ピコルと共にゲラルよりイサクの許に來りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'イサク彼等に言ふ汝等は我を惡み我をして汝等をはなれて去らしめたるなるに何ぞ我許に來るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, '彼等いひけるは我等確然にヱホバが汝と偕にあるを見たれば我等の間即ち我等と汝の間に誓詞を立て汝と契約を結ばんと謂へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, '汝我等に惡事をなすなかれ其は我等は汝を害せず只善事のみを汝になし且汝を安然に去しめたればなり汝はヱホバの祝みたまふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'イサク乃ち彼等のために酒宴を設けたれば彼等食ひ且飮り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, '斯て朝夙に起て互に相誓へり而してイサク彼等を去しめたれば彼等イサクをはなれて安然にかへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, '其日イサクの僕來りて其ほりたる井につきて之に告て我等水を得たりといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, '即ち之をシバとなづく此故に其邑の名は今日までベエルシバ(誓詞の井)といふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'エサウ四十歳の時ヘテ人の女ユデテとヘテ人エロンの女バスマテを妻に娶り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, '彼等はイサクとリベカの心の愁煩となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'イサク老て目くもりて見るあたはざるに及びて其長子エサウを召て之に吾子よといひければ答へて我此にありといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'イサクいひけるは視よ我は今老て何時死るやを知ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, '然ば請ふ汝の器汝の弓矢を執て野に出でわがために麆を獵て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'わが好む美味を作り我にもちきたりて食はしめよ我死るまへに心に汝を祝せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'イサクが其子エサウに語る時にリベカ聞ゐたりエサウは麆を獵て携きたらんとて野に往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, '是に於てリベカ其子ヤコブに語りていひけるは我聞ゐたるに汝の父汝の兄エサウに語りて言けらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '吾ために麆をとりきたり美味を製りて我にくはせよ死るまへに我ヱホバの前にて汝を祝せんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, '然ば吾子よ吾言にしたがひわが汝に命ずるごとくせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, '汝群畜の所にゆきて彼處より山羊の二箇の善き羔を我にとりきたれ我之をもて汝の父のために其好む美味を製らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, '汝之を父にもちゆきて食しめ其死る前に汝を祝せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'ヤコブ其母リベカに言けるは兄エサウは毛深き人にして我は滑澤なる人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, '恐くは父我に捫ることあらん然らば我は欺く者と父に見えんされば祝をえずして返て呪詛をまねかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, '其母彼にいひけるは我子よ汝の詛はるる所は我に歸せん只わが言にしたがひ往て取來れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, '是において彼往て取り母の所にもちきたりければ母すなはち父の好むところの美味を製れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, '而してリベカ家の中に己の所にある長子エサウの美服をとりて之を季子ヤコブに衣せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, '又山羊の羔の皮をもて其手と其頸の滑澤なる處とを掩ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, '其製りたる美味とパンを子ヤコブの手にわたせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, '彼乃ち父の許にいたりて我父よといひければ我此にありわが子よ汝は誰なると曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'ヤコブ父にいひけるは我は汝の長子エサウなり我汝が我に命じたるごとくなせり請ふ起て坐しわが麆の肉をくらひて汝の心に我を祝せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'イサク其子に言けるは吾子よ汝いかにして斯速に獲たるや彼言ふ汝の神ヱホバ之を我にあはせたまひしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'イサク、ヤコブにいひけるはわが子よ請ふ近くよれ我汝に捫て汝がまことに吾子エサウなるや否やをしらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'ヤコブ父イサクに近よりければイサク之にさはりていひけるは聲はヤコブの聲なれども手はエサウの手なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, '彼の手其兄エサウの手のごとく毛深かりしに因て之を辨別へずして遂に之を祝したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, '即ちイサクいひけるは汝はまことに吾子エサウなるや彼然りといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'イサクいひけるは我に持きたれ吾子の麆を食ひてわが心に汝を祝せんと是に於てヤコブ彼の許にもちきたりければ食へり又酒をもちきたりければ飮り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'かくて父イサク彼にいひけるは吾子よ近くよりて我に接吻せよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, '彼すなはち近よりて之に接吻しければ其衣の馨香をかぎて彼を祝していひけるは嗚呼吾子の香はヱホバの祝たまへる野の馨香のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'ねがはくは神天の露と地の腴および饒多の穀と酒を汝にたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, '諸の民汝につかへ諸の邦汝に躬を鞠ん汝兄弟等の主となり汝の母の子等汝に身をかがめん汝を詛ふ者はのろはれ汝を祝す者は祝せらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'イサク、ヤコブを祝することを終てヤコブ父イサクの前より出さりし時にあたりて兄エサウ獵より歸り來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, '己も亦美味をつくりて之を其父の許にもちゆき父にいひけるは父よ起て其子の麆を食ひて心に我を祝せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, '父イサク彼にいひけるは汝は誰なるや彼いふ我は汝の子汝の長子エサウなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'イサク甚大に戰兢ていひけるは然ば彼麆を獵て之を我にもちきたりし者は誰ぞや我汝がきたるまへに諸の物を食ひて彼を祝したれば彼まことに祝福をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'エサウ父の言を聞て大に哭き痛く泣て父にいひけるは父よ我を祝せよ我をも祝せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'イサク言けるは汝の弟僞りて來り汝の祝を奪ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'エサウいひけるは彼をヤコブ(推除者)となづくるは宜ならずや彼が我をおしのくる事此にて二次なり昔にはわが家督の權を奪ひ今はわが祝を奪ひたり又言ふ汝は祝をわがために殘しおかざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'イサク對てエサウにいひけるは我彼を汝の主となし其兄弟を悉く僕として彼にあたへたり又穀と酒とを彼に授けたり然ば吾子よ我何を汝になすをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'エサウ父に言けるは父よ父の祝唯一ならんや父よ我を祝せよ我をも祝せよと聲をあげて哭ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, '父イサク答て彼にいひけるは汝の住所は地の膏腴にはなれ上よりの天の露にはなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, '汝は劍をもて世をわたり汝の弟に事ん然ど汝繋を離るる時は其軛を汝の頸より振ひおとすを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'エサウ父のヤコブを祝したる其祝の爲にヤコブを惡めり即ちエサウ心に謂けるは父の喪の日近ければ其時我弟ヤコブを殺さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, '長子エサウの此言リベカに聞えければ季子ヤコブを呼よせて之に言けるは汝の兄エサウ汝を殺さんとおもひて自ら慰む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'されば吾子よ我言にしたがひ起てハランにゆきわが兄ラバンの許にのがれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, '汝の兄の怒の釋るまで暫く彼とともに居れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, '汝の兄の鬱憤釋て汝をはなれ汝彼になしたる事を忘るるにいたらば我人をやりて汝を彼處よりむかへん我何ぞ一日のうちに汝等二人を喪ふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'リベカ、イサクに言けるは我はヘテの女等のために世を厭ふにいたるヤコブ若此地の彼女等の如きヘテの女の中より妻を娶らば我身生るも何の利益あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'イサク、ヤコブを呼て之を祝し之に命じて言けるは汝カナンの女の中より妻を娶るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, '起てパダンアラムに往き汝の母の父ベトエルの家にいたり彼處にて汝の母の兄ラバンの女の中より妻を娶れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, '願くは全能の神汝を祝み汝をして子女を多く得せしめ且汝の子孫を増て汝をして多衆の民とならしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, '又アブラハムに賜んと約束せし祝を汝および汝と共に汝の子孫に賜ひ汝をして神がアブラハムにあたへ給ひし此汝が寄寓る地を持たしめたまはんことをと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, '斯てイサク、ヤコブを遣しければパダンアラムにゆきてラバンの所にいたれりラバンはスリア人ベトエルの子にしてヤコブとエサウの母なるリベカの兄なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'エサウはイサクがヤコブを祝して之をパダンアラムにつかはし彼處より妻を娶しめんとしたるを見又之を祝し汝はカナンの女の中より妻をめとるなかれといひて之に命じたることを見');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, '又ヤコブが其父母の言に順ひてパダンアラムに往しを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'エサウまたカナンの女の其父イサクの心にかなはぬを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, '是においてエサウ、イシマエルの所にゆきて其有る妻の外に又アブラハムの子イシマエルの女ネバヨテの妹マハラテを妻にめとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, '茲にヤコブ、ベエルシバより出たちてハランの方におもむきけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, '一處にいたれる時日暮たれば即ち其處に宿り其處の石をとり枕となして其處に臥て寢たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, '時に彼夢て梯の地にたちゐて其巓の天に逹れるを見又神の使者の其にのぼりくだりするを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'ヱホバ其上に立て言たまはく我は汝の祖父アブラハムの神イサクの神ヱホバなり汝が偃臥ところの地は我之を汝と汝の子孫に與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, '汝の子孫は地の塵沙のごとくなりて西東北南に蔓るべし又天下の諸の族汝と汝の子孫によりて福祉をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'また我汝とともにありて凡て汝が往ところにて汝をまもり汝を此地に率返るべし我はわが汝にかたりし事を行ふまで汝をはなれざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'ヤコブ目をさまして言けるは誠にヱホバ此處にいますに我しらざりきと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, '乃ち惶懼ていひけるは畏るべき哉此處是即ち神の殿の外ならず是天の門なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'かくてヤコブ朝夙に起き其枕となしたる石を取り之を立て柱となし膏を其上に沃ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, '其處を名をベテル(神殿)と名けたり其邑の名は初はルズといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'ヤコブ乃ち誓をたてていひけるは若神我とともにいまし此わがゆく途にて我をまもり食ふパンと衣る衣を我にあたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, '我をしてわが父の家に安然に歸ることを得せしめたまはばヱホバをわが神となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, '又わが柱にたてたる此石を神の家となさん又汝がわれにたまふ者は皆必ず其十分の一を汝にささげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, '斯てヤコブ其途にすすみて東の民の地にいたりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, '見るに野に井ありて羊の群三其傍に臥ゐたり此井より群に飮へばなり大なる石井の口にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, '羊の群皆其處に集る時に井の口より石をまろばして羊に水飼ひ復故のごとく井の口に石をのせおくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'ヤコブ人々に言けるは兄弟よ奚よりきたれるや彼等いふ我等はハランより來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'ヤコブ彼等にいひけるは汝等ナホルの子ラバンをしるや彼等識といふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'ヤコブ又かれらにいひけるは彼は安きや彼等いふ安し視よ彼の女ラケル羊と偕に來ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'ヤコブ言ふ視よ日尚高し家畜を聚むべき時にあらず羊に飮ひて往て牧せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, '彼等いふ我等しかする能はず群の皆聚るに及て井の口より石をまろばして羊に飮ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'ヤコブ尚彼等と語れる時にラケル父の羊とともに來る其は之を牧居たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'ヤコブ其母の兄ラバンの女ラケルおよび其母の兄ラバンの羊を見しかばヤコブ進みよりて井の口より石をまろばし母の兄ラバンの羊に飮ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, '而してヤコブ、ラケルに接吻して聲をあげて啼哭ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, '即ちヤコブ、ラケルに己はその父の兄弟にしてリベカの子なることを告ければ彼はしりゆきて父に告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'ラバン其妹の子ヤコブの事を聞しかば趨ゆきて之を迎へ之を抱きて接吻し之を家に導きいたれりヤコブすなはち此等の事を悉くラバンに述たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'ラバン彼にいひけるは汝は誠にわが骨肉なりとヤコブ一月の間彼とともに居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, '茲にラバン、ヤコブにいひけるは汝はわが兄弟なればとて空く我に役事べけんや何の報酬を望むや我に告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'ラバン二人の女子を有り姉の名はレアといひ妹の名はラケルといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'レアは目弱かりしがラケルは美くして姝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'ヤコブ、ラケルを愛したれば言ふ我汝の季女ラケルのために七年汝に事ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'ラバンいひけるは彼を他の人にあたふるよりも汝にあたふるは善し我と偕に居れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'ヤコブ七年の間ラケルのために勤たりしが彼を愛するが爲に此を數日の如く見做り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, '茲にヤコブ、ラバンに言けるはわが期滿たればわが妻をあたへて我をしてかれの處にいることを得せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, '是に於てラバン處の人を盡く集めて酒宴を設けたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, '晩に及びて其女レアを携へて此をヤコブにつれ來れりヤコブ即ち彼の處にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'ラバンまた其侍婢ジルパを娘レアに與へて侍婢となさしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, '朝にいたりて見るにレアなりしかばヤコブ、ラバンに言けるは汝なんぞ此事を我になしたるや我ラケルのために汝に役事しにあらずや汝なんぞ我を欺くや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'ラバンいひけるは姉より先に妹を嫁しむる事は我國にて爲ざるところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, '其七日を過せ我等是をも汝に與へん然ば汝是がために尚七年我に事へて勤むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'ヤコブ即ち斯なして其七日をすごせしかばラバン其女ラケルをも之にあたへて妻となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'またラバン其侍婢ビルハを女ラケルにあたへて侍婢となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'ヤコブまたラケルの所にいりぬ彼レアよりもラケルを愛し尚七年ラバンに事たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'ヱホバ、レアの嫌るるを見て其胎をひらきたまへり然どラケルは姙なきものなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'レア孕みて子を生み其名をルベンと名けていひけるはヱホバ誠にわが艱苦を顧みたまへりされば今夫我を愛せんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, '彼ふたたび孕みて子を產みヱホバわが嫌るるを聞たまひしによりて我に是をもたまへりと言て其名をシメオンと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, '彼また孕みて子を生み我三人の子を生たれば夫今より我に膠漆んといへり是によりて其名をレビと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, '彼復姙みて子を生み我今ヱホバを讚美んといへり是によりて其名をユダと名けたり是にいたりて產ことやみぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'ラケル己がヤコブに子を生ざるを見て其姉を夢みヤコブに言けるは我に子を與へよ然らずば我死んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'ヤコブ、ラケルにむかひて怒を發して言ふ汝の胎に子をやどらしめざる者は神なり我神に代るをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'ラケルいふ吾婢ビルハを視よ彼の處に入れ彼子を生てわが膝に置ん然ば我もまた彼によりて子をうるにいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, '其仕女ビルハを彼にあたへて妻となさしめたりヤコブ即ち彼の處にいる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'ビルハ遂にはらみてヤコブに子を生ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'ラケルいひけるは神我を監み亦わが聲を聽いれて吾に子をたまへりと是によりて其名をダンと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'ラケルの仕女ビルハ再び姙みて次の子をヤコブに生ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'ラケル我神の爭をもて姉と爭ひて勝ぬといひて其名をナフタリと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, '茲にレア產ことの止たるを見しかば其仕女ジルパをとりて之をヤコブにあたへて妻となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'レアの仕女ジルパ、ヤコブに子を產ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'レア福來れりといひて其名をガドと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'レアの仕女ジルパ次子をヤコブに生ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'レアいふ我は幸なり女等我を幸なる者となさんと其名をアセルとなづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, '茲に麥苅の日にルベン出ゆきて野にて戀茄を獲これを母レアの許にもちきたりければラケル、レアにいひけるは請ふ我に汝の子の戀茄をあたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'レア彼にいひけるは汝のわが夫を奪しは微き事ならんや然るに汝またわが子の戀茄をも奪んとするやラケルいふ然ば汝の子の戀茄のために夫是夜汝と寢べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, '晩におよびてヤコブ野より來りければレア之をいでむかへて言けるは我誠にわが子の戀茄をもて汝を雇ひたれば汝我の所にいらざるべからずヤコブ即ち其夜彼といねたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, '神レアに聽たまひければ彼妊みて第五の子をヤコブに生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'レアいひけるは我わが仕女を夫に與へたれば神我に其値をたまへりと其名をイツサカルと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'レア復妊みて第六の子をヤコブに生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'レアいひけるは神我に嘉賚を貺ふ我六人の男子を生たれば夫今より我と偕にすまんと其名をゼブルンとなづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, '其後彼女子を生み其名をデナと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, '茲に神ラケルを念ひ神彼に聽て其胎を開きたまひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, '彼妊みて男子を生て曰ふ神わが恥辱を洒ぎたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, '乃ち其名をヨセフと名けて言ふヱホバ又他の子を我に加へたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, '茲にラケルのヨセフを生むに及びてヤコブ、ラバンに言けるは我を歸して故郷に我國に往しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'わが汝に事て得たる所の妻子を我に與へて我を去しめよわが汝になしたる役事は汝之を知るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'ラバン彼にいひけるは若なんぢの意にかなはばねがはくは留れ我ヱホバが汝のために我を祝みしを卜ひ得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, '又言ふ汝の望む値をのべよ我之を與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'ヤコブ彼にいひけるは汝は如何にわが汝に事しか如何に汝の家畜を牧しかを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'わが來れる前に汝の有たる者は鮮少なりしが増て遂に群をなすに至る吾來りてよりヱホバ汝を祝みたまへり然ども我は何時吾家を成にいたらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, '彼言ふ我何を汝に與へんかヤコブいひけるは汝何者をも我に與ふるに及ばず汝若此事を我になさば我復汝の群を牧守らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, '即ち我今日徧く汝の群をゆきめぐりて其中より凡て斑なる者點なる者を移し綿羊の中の凡て黑き者を移し山羊の中の點なる者と斑なる者を移さん是わが値なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, '後に汝來りてわが傭値をしらぶる時わが義我にかはりて應をなすべし若わが所に山羊の斑ならざる者點ならざる者あり綿羊の黑からざる者あらば皆盜る者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'ラバンいふ汝の言の如くなさんことを願ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, '是に於て彼其日牡山羊の斑入なる者斑點なる者を移し凡て牝山羊の斑駮なる者斑點なる者都て身に白色ある者を移し又綿羊の中の凡て黑き者を移して其子等の手に付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, '而して彼己とヤコブの間に三日程の隔をたてたりヤコブはラバンの餘の群を牧ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, '茲にヤコブ楊柳と楓と桑の靑枝を執り皮を剥て白紋理を成り枝の白き所をあらはし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, '其皮をはぎたる枝を群の來りて飮むところの水槽と水鉢に立て群に向はしめ群をして水のみの來る時に孕ましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, '群すなはち枝の前に孕みて斑入の者斑駮なる者斑點なる者を產しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'ヤコブ其羔羊を區分ちラバンの群の面を其群の斑入なる者と黑き者に對はしめたりしが己の群をば一所に置てラバンの群の中にいれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, '又家畜の壯健き者孕みたる時はヤコブ水槽の中にて其家畜の目の前に彼枝を置き枝の傍において孕ましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, '然ど家畜の羸弱かる時は之を置ず是に因て羸弱者はラバンのとなり壯健者はヤコブのとなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, '是に於て其人大に富饒になりて多の家畜と婢僕および駱駝驢馬を有にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, '茲にヤコブ、ラバンの子等がヤコブわが父の所有を盡く奪ひ吾父の所有によりて此凡の榮光を獲たりといふを聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, '亦ヤコブ、ラバンの面を見るに己に對すること疇昔の如くならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, '時にヱホバ、ヤコブに言たまへるは汝の父の國にかへり汝の親族に至れ我汝と偕にをらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, '是に於てヤコブ人をやりてラケルとレアを野に招きて群の所に至らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, '之にいひけるは我汝等の父の面を見るに其我に對すること疇昔の如くならず然どわが父の神は我と偕にいますなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, '汝等がしるごとく我力を竭して汝らの父に事へたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, '汝等の父我を欺きて十次もわが値を易たり然ども神彼の我を害するを容したまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, '彼斑駮なる者は汝の傭値なるべしといへば群の生ところ皆斑駮なり斑入の者は汝の値なるべしといへば群の生ところ皆斑入なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, '斯神汝らの父の家畜を奪て我に與へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, '群の孕む時に當りて我夢に目をあげて見しに群の上に乗る牡羊は皆斑入の者斑駮なる者白點なる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, '時に神の使者夢の中に我に言ふヤコブよと我此にありと對へければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, '乃ち言ふ汝の目をあげて見よ群の上に乗る牡羊は皆斑入の者斑駮なる者白點なる者なり我ラバンが凡て汝に爲すところを鑒みる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, '我はベテルの神なり汝彼處にて柱に膏を沃ぎ彼處にて我に誓を立たり今起て斯地を出て汝の親族の國に歸れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'ラケルとレア對て彼にいひけるは我等の父の家に尚われらの分あらんや我等の產業あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, '我等は父に他人のごとくせらるるにあらずや其は父我等を賣り亦我等の金を蝕减したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, '神がわが父より取たまひし財寶は我等とわれらの子女の所屬なり然ば都て神の汝に言たまひし事を爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, '是に於てヤコブ起て子等と妻等を駱駝に乗せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, '其獲たる凡の家畜と凡の所有即ちパダンアラムにてみづから獲たるところの家畜を携へ去てカナンの地に居所の其父イサクの所におもむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, '時にラバンは羊の毛を剪んとて往てありラケル其父のテラピムを竊めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'ヤコブは其去ことをスリア人ラバンに告ずして潛に忍びいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, '即ち彼その凡の所有を挈へて逃去り起て河を渡りギレアデの山にむかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'ヤコブの逃去しこと三日におよびてラバンに聞えければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, '彼兄弟を率てその後を追ひしが七日路をへてギレアデの山にて之に追及ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, '神夜の夢にスリア人ラバンに臨みて汝愼みて善も惡もヤコブに道なかれと之に告たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'ラバン遂にヤコブに追及しがヤコブは山に天幕を張ゐたればラバンもその兄弟と共にギレアデの山に天幕をはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, '而してラバン、ヤコブに言けるは汝我に知しめずして忍びいで吾女等を劍をもて執たる者のごとくにひき往り何ぞかかる事をなすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, '何故に汝潛に逃さり我をはなれて忍いで我につげざりしや我歡喜と歌謠と鼗と琴をもて汝を送りしならんを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, '何ぞ我をしてわが孫と女に接吻するを得ざらしめしや汝愚妄なる事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, '汝等に害をくはふるの能わが手にあり然ど汝等の父の神昨夜我に告て汝つつしみて善も惡もヤコブに語べからずといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, '汝今父の家を甚く戀て歸んと願ふは善れども何ぞわが神を竊みたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'ヤコブ答へてラバンにいひけるは恐くは汝強て女を我より奪ならんと思ひて懼れたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, '汝の神を持る者を見ば之を生しおくなかれ我等の兄弟等の前にて汝の何物我の許にあるかをみわけて之を汝に取れと其はヤコブ、ラケルが之を竊しを知ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, '是に於てラバン、ヤコブの天幕に入りレアの天幕に入りまた二人の婢の天幕にいりしが視いださざればレアの天幕を出てラケルの天幕にいる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'ラケル已にテラピムを執て之を駱駝の鞍の下にいれて其上に坐しければラバン遍く天幕の中をさぐりたれども見いださざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, '時にラケル父にいひけるは婦女の經の習例の事わが身にあれば父の前に起あたはず願くは主之を怒り給ふなかれと是をもて彼さがしたれども遂にテラピムを見いださざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, '是に於てヤコブ怒てラバンを謫即ちヤコブ應てラバンに言けるは我何の愆あり何の罪ありてか汝火急く我をおふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, '汝わが物を盡く索たるが汝の家の何物を見いだしたるや此にわが兄弟と汝の兄弟の前に其を置て我等二人の間をさばかしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, '我この二十年汝とともにありしが汝の牝綿羊と牝山羊其胎を殰ねしことなし又汝の群の牡綿羊は我食はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, '又噛裂れたる者は我これを汝の所に持きたらずして自ら之を補へり又晝竊るるも夜竊るるも汝わが手より之を要めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, '我は是ありつ晝は暑に夜は寒に犯されて目も寐るの遑なく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, '此二十年汝の家にありたり汝の二人の女の爲に十四年汝の群のために六年汝に事たり然に汝は十次もわが値を易たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, '若わが父の神アブラハムの神イサクのの畏む者我とともにいますにあらざれば汝今必ず我を空手にて去しめしならん神わが苦難とわが手の勞苦をかへりみて昨夜汝を責たまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'ラバン應てヤコブに言けるは女等はわが女子等はわが子群はわが群汝が見る者は皆わが所屬なり我今日此わが女等とその生たる子等に何をなすをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, '然ば來れ我と汝二人契約をむすび之を我と汝の間の證憑となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, '是に於てヤコブ石を執りこれを建て柱となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'ヤコブ又その兄弟等に石をあつめよといひければ即ち石をとりて垤を成れり斯て彼等彼處にて垤の上に食す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'ラバン之をエガルサハドタ(證憑の垤)と名けヤコブ之をギレアデ(證憑の垤)と名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'ラバン此垤今日われとなんぢの間の證憑たりといひしによりて其名はギレアデとと稱らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, '又ミヅパ(觀望樓)と稱らる其は彼我等が互にわかるるに及べる時ねがはくはヱホバ我と汝の間を監みたまへといひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, '彼又いふ汝もしわが女をなやまし或はわが女のほかに妻をめとらば人の我らと偕なる者なきも神と汝のあひだにいまして證をなしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'ラバン又ヤコブにいふ我われとなんぢの間にたてたる此垤を視よ柱をみよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, '此垤證とならん柱證とならん我この垤を越て汝を害せじ汝この垤この柱を越て我を害せざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'アブラハムの神ナホルの神彼等の父の神われらの間を鞫きたまへとヤコブ乃ちその父イサクの畏む者をさして誓へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, '斯てヤコブ山にて犧牲をささげその兄弟を招きてパンを食しむ彼等パンを食ひて山に宿れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'ラバン朝蚤に起き其孫と女に接吻して之を祝せりしかしてラバンゆきて其所にかへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, '茲にヤコブその途に進みしが神の使者これにあふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'ヤコブこれを見て是は神の陣營なりといひてその處の名をマハナイム(二營)となづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'かくてヤコブ己より前に使者をつかはしてセイルの地エドムの野にをる其兄エサウの所にいたらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, '即ち之に命じて言ふ汝等かくわが主エサウにいふべし汝の僕ヤコブ斯いふ我ラバンの所に寄寓て今までとどまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, '我牛驢馬羊僕婢あり人をつかはしてわが主に告ぐ汝の前に恩をえんことを願ふなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, '使者ヤコブにかへりて言けるは我等汝の兄エサウの許に至れり彼四百人をしたがへて汝をむかへんとて來ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, '是によりヤコブ大におそれ且くるしみ己とともにある人衆および羊と牛と駱駝を二隊にわかちて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, '言けるはエサウもし一の隊に來りて之をうたば遺れるところの一隊逃るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'ヤコブまた言けるはわが父アブラハムの神わが父イサクの神ヱホバよ汝甞て我につげて汝の國にかへり汝の親族に到れ我なんぢを善せんといひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, '我はなんぢが僕にほどこしたまひし恩惠と眞實を一も受るにたらざるなり我わが杖のみを持てこのヨルダンを濟りしが今は二隊とも成にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, '願くはわが兄の手よりエサウの手より我をすくひいだしたまへ我彼をおそる恐くは彼きたりて我をうち母と子とに及ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, '汝は甞て我かならず汝を惠み汝の子孫を濱の沙の多して數ふべからざるが如くなさんといひたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, '彼その夜彼處に宿りその手にいりし物の中より兄エサウへの禮物をえらべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, '即ち牝山羊二百牡山羊二十牝羊二百牡羊二十');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, '乳駱駝と其子三十牝牛四十牡牛十牝の驢馬二十驢馬の子十');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, '而して其群と群とをわかちて之を僕の手に授し僕にいひけるは吾に先ちて進み群と群との間を隔ておくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, '又その前者に命じて言けるはわが兄エサウ汝にあひ汝に問て汝は誰の人にして何處にゆくや是汝のまへなる者は誰の所有なるやといはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, '汝の僕ヤコブの所有にしてわが主エサウにたてまつる禮物なり視よ彼もわれらの後にをるといふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, '彼かく第二の者第三の者および凡て群々にしたがひゆく者に命じていふ汝等エサウにあふ時はかくの如く之にいふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, '且汝等いへ視よなんぢの僕ヤコブわれらの後にをるとヤコブおもへらく我わが前におくる禮物をもて彼を和めて然るのち其面を觀ん然ば彼われを接遇ることあらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, '是によりて禮物かれに先ちて行く彼は其夜陣營の中に宿りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, '其夜おきいでて二人の妻と二人の仕女および十一人の子を導きてヤボクの渡をわたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, '即ち彼等をみちびきて川を渉らしめ又その有る物を渡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, '而してヤコブ一人遺りしが人ありて夜の明るまで之と角力す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, '其人己のヤコブに勝ざるを見てヤコブの髀の樞骨に觸しかばヤコブの髀の樞骨其人と角力する時挫離たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, '其人夜明んとすれば我をさらしめよといひければヤコブいふ汝われを祝せずばさらしめずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, '是に於て其人かれにいふ汝の名は何なるや彼いふヤコブなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, '其人いひけるは汝の名は重てヤコブととなふべからずイスラエルととなふべし其は汝神と人とに力をあらそひて勝たればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'ヤコブ問て請ふ汝の名を告よといひければ其人何故にわが名をとふやといひて乃ち其處にて之を祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, '是を以てヤコブその處の名をベニエル(神の面)となづけて曰ふ我面と面をあはせて神とあひ見てわが生命なほ存るなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, '斯て彼日のいづる時にベニエルを過たりしが其髀のために歩行はかどらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, '是故にイスラエルの子孫は今日にいたるまで髀の樞の巨筋を食はず是彼人がヤコブの髀の巨筋に觸たるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, '爰にヤコブ目をあげて視にエサウ四百人をひきゐて來しかば即ち子等を分ちてレアとラケルと二人の仕女とに付し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, '仕女とその子等を前におきレアとその子等を次におきラケルとヨセフを後におきて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, '自彼等の前に進み七度身を地にかがめて遂に兄に近づきけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'エサウ趨てこれを迎へ抱きてその頸をかかへて之に接吻すしかして二人ともに啼泣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'エサウ目をあげて婦人と子等を見ていひけるは是等の汝とともなる者は誰なるやヤコブいひけるは神が僕に授たまひし子なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, '時に仕女等その子とともに近よりて拜し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'レアも亦その子とともに近よりて拜す其後にヨセフとラケルちかよりて拜す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'エサウ又いひけるは我あへる此諸の群は何のためなるやヤコブいふ主の目の前に恩を獲んがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'エサウいひけるは弟よわが有ところの者は足り汝の所有は汝自ら之を有てよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'ヤコブいひけるは否我もし汝の目の前に恩をえたらんには請ふわが手よりこの禮物を受よ我汝の面をみるに神の面をみるがごとくなり汝また我をよろこぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, '神我をめぐみたまひて我が有ところの者足りされば請ふわが汝にたてまつる禮物を受よと彼に強ければ終に受たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'エサウいひけるは我等いでたちてゆかん我汝にさきだつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'ヤコブ彼にいひけるは主のしりたまふごとく子等は幼弱し又子を持る羊と牛と我にしたがふ若一日これを驅すごさば群みな死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, '請ふわが主僕にさきだちて進みたまへ我はわが前にゆくところの家畜と子女に足にまかせて徐に導きすすみセイルにてわが主に詣らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'エサウいひけるは然ば我わがひきゐる人數人を汝の所にのこさんヤコブいひけるは何ぞ此を須んや我をして主の目の前に恩を得せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, '是に於てエサウは此日その途にしたがひてセイルに還りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, '斯てヤコブ、スコテに進みて己のために家を建て又家畜のために廬を作れり是によりて其處の名をスコテ(廬)といふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'ヤコブ、パダンアラムより來りて恙なくカナンの地にあるシケムの邑に至り邑の前にその天幕を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, '遂にその天幕をはりしところの野をシケムの父ハモルの子等の手により金百枚にて購とり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, '彼處に壇をきづきて之をエル、エロヘ、イスラエル(イスラエルの神なる神)となづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'レアのヤコブに生たる女デナその國の婦女を見んとていでゆきしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'その國の君主なるヒビ人ハモルの子シケムこれを見て之をひきいれこれと寢てこれを辱しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, '而してその心ふかくヤコブの女デナを戀ひて彼此女を愛しこの女の心をいひなだむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, '斯てシケムその父ハモルに語り此少き女をわが妻に獲よといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'ヤコブ彼がその女子デナを汚したることを聞しかどもその子等家畜を牧て野にをりしによりて其かへるまでヤコブ默しゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'シケムの父ハモル、ヤコブの許にいできたりて之と語らふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, '茲にヤコブの子等野より來りしが之を聞しかば其人々憂へかつ甚く怒れり是はシケムがヤコブの女と寢てイスラエルに愚なる事をなしたるに因り是のごとき事はなすべからざる者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'ハモル彼等に語りていひけるはわが子シケム心になんぢの女を戀ふねがはくは彼をシケムにあたへて妻となさしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, '汝ら我らと婚姻をなし汝らの女を我らにあたへ我らの女汝らに娶れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'かくして汝等われらとともに居るべし地は汝等の前にあり此に住て貿易をなし此にて產業を獲よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'シケム又デナの父と兄弟等にいひけるは我をして汝等の目のまへに恩を獲せしめよ汝らが我にいふところの者は我あたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'いかに大なる聘物と禮物を要るも汝らがわれに言ふごとくあたへん唯この女を我にあたへて妻となさしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'ヤコブの子等シケムとその父ハモルに詭りて答へたり即ちシケムがその妹デナを汚したるによりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, '彼等これに語りていひけるは我等この事を爲あたはず割禮をうけざる者にわれらの妹をあたふるあたはず是われらの恥辱なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, '然ど斯せば我等汝らに允さん若し汝らの中の男子みな割禮をうけてわれらの如くならば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, '我等の女子を汝等にあたへ汝らの女子をわれらに娶り汝らと偕にをりて一の民とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, '汝等もし我等に聽ずして割禮をうけずば我等女子をとりて去べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, '彼等の言ハモルとハモルの子シケムの心にかなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, '此若き人ヤコブの女を愛するによりて其事をなすを遲せざりき彼はその父の家の中にて最貴れたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'ハモルとその子シケム乃ちその邑の門にいたり邑の人々に語りていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '是人々は我等と睦し彼等をして此地に住て此に貿易をなさしめよ地は廣くして彼らを容るにたるなり我ら彼らの女を妻にめとり我らの女をかれらに與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, '若唯われらの中の男子みな彼らが割禮をうくるごとく割禮を受なば此人々われらに聽て我等と偕にをり一の民となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, '然ばかれらの家畜と財產と其諸の畜は我等が所有となるにあらずや只かれらに聽んしからば彼らわれらとともにをるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, '邑の門に出入する者みなハモルとその子シケムに聽したがひ邑の門に出入する男子皆割禮を受たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, '斯て三日におよび彼等その痛をおぼゆる時ヤコブの子二人即ちデナの兄弟なるシメオンとレビ各劍をとり往て思よらざる時に邑を襲ひ男子を悉く殺し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, '利刄をもてハモルとその子シケムをころしシケムの家よりデナを携へいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, '而してヤコブの子等ゆきて其殺されし者を剥ぎ其邑をかすめたり是彼等がその妹を汚したるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'またその羊と牛と驢馬およびその邑にある者と野にある者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, '並にその諸の貨財を奪ひその子女と妻等を悉く擄にし家の中なる物を悉く掠めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'ヤコブ、シメオンとレビに言けるは汝等我を累はし我をして此國の人即ちカナン人とベリジ人の中に避嫌れしむ我は數すくなければ彼ら集りて我をせめ我をころさん然ば我とわが家滅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, '彼らいふ彼豈われらの妹を娼妓のごとくしてよからんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, '茲に神ヤコブに言たまひけるは起てベテルにのぼりて彼處に居り汝が昔に兄エサウの面をさけて逃る時に汝にあらはれし神に彼處にて壇をきづけと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'ヤコブ乃ちその家人および凡て己とともなる者にいふ汝等の中にある異神を棄て身を清めて衣服を易よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, '我等起てベテルにのぼらん彼處にて我わが苦患の日に我に應へわが往ところの途にて我とともに在せし神に壇をきづくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, '是に於て彼等その手にある異神およびその耳にある耳環を盡くヤコブに與へしかばヤコブこれをシケムの邊なる橡樹の下に埋たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, '斯て彼等いでたちしが神其四周の邑々をして懼れしめたまひければヤコブの子の後を追ふ者なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'ヤコブ及び之と共なる諸の人遂にカナンの地にあるルズに至る是即ちベテルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, '彼かしこに壇をきづき其處をエルベテルと名けたり是は兄の面をさけて逃る時に神此にて己にあらはれ給しによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, '時にリベカの乳媼デボラ死たれば之をベテルの下にて橡樹の下に葬れり是によりてその樹の名をアロンバクテ(哀哭の橡)といふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'ヤコブ、パダンアラムより歸りし時神復これにあらはれて之を祝したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, '神かれに言たまはく汝の名はヤコブといふ汝の名は重てヤコブとよぶべからずイスラエルを汝の名となすべしとその名をイスラエルと稱たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, '神また彼にいひたまふ我は全能の神なり生よ殖よ國民および多の國民汝よりいで又王等なんぢの腰よりいでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'わがアブラハムおよびイサクに與し地は我これを汝にあたへん我なんぢの後の子孫にその地をあたふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, '神かれと言たまひし處より彼をはなれて昇りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, '是に於てヤコブ神の己と言いひたまひし處に柱すなはち石の柱を立て其上に酒を灌ぎまた其上に膏を沃げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, '而してヤコブ神の己にものいひたまひし處の名をベテルとなづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'かくてヤコブ等ベテルよりいでたちしがエフラタに至るまでは尚路の隔ある處にてラケル產にのぞみその產おもかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, '彼難產にのぞめる時產婆之にいひけるは懼るなかれ汝また此男の子を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, '彼死にのぞみてその魂さらんとする時その子の名をベノニ(吾苦痛の子)と呼たり然ど其父これをベニヤミン(右手の子)となづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'ラケル死てエフラタの途に葬らる是即ちベテレヘムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'ヤコブその墓に柱を立たり是はラケルの墓の柱といひて今日まで在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'イスラエル復いでたちてエダルの塔の外にその天幕を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'イスラエルかの地に住る時にルベン往て父の妾ビルハと寢たりイスラエルこれを聞く夫ヤコブの子は十二人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, '即ちレアの子はヤコブの長子ルベンおよびシメオン、レビ、ユダ、イッサカル、ゼブルンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'ラケルの子はヨセフとベニヤミンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'ラケルの仕女ビルハの子はダンとナフタリなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'レアの仕女ジルパの子はガドとアセルなり是等はヤコブの子にしてパダンアラムにて彼に生れたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'ヤコブ、キリアテアルバのマムレにゆきてその父イサクに至れり是すなはちヘブロンなり彼處はアブラハムとイサクの寄寓しところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'イサクの齡は百八十歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'イサク老て年滿ち氣息たえ死にて其民にくははれりその子エサウとヤコブ之をはうむる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'エサウの傳はかくのごとしエサウはすなはちエドムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'エサウ、カナンの女の中より妻をめとれり即ちヘテ人エロンの女アダおよびヒビ人ヂベオンの女なるアナの女アホリバマ是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, '又イシマエルの女ネバヨテの妹バスマテをめとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'アダはエリパズをエサウに生みバスマテはリウエルを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'アホリバマはヱウシ、ヤラムおよびコラを生り是等はエサウの子にしてカナンの地に於て彼に生れたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'エサウその妻と子女およびその家の諸の人並に家畜と諸の畜類およびそのカナンの地にて獲たる諸の物を挈へて弟ヤコブをはなれて他の地にゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, '其は二人の富有多くして倶にをるあたはざればなり彼らが寄寓しところの地はかれらの家畜のためにかれらを容るをえざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, '是に於てエサウ、セイル山に住りエサウはすなはちエドムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'セイル山にをりしエドミ人の先祖エサウの傳はかくのごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'エサウの子の名は左のごとしエサウの妻アダの子はエリパズ、エサウの妻バスマテの子はリウエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'エリパズの子はテマン、オマル、ゼポ、ガタムおよびケナズなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'テムナはエサウの子エリパズの妾にしてアマレクをエリパズに生り是等はエサウの妻アダの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'リウエルの子は左の如しナハテ、ゼラ、シヤンマおよびミザ是等はエサウの妻バスマテの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'ヂベオンの女なるアナの女にしてエサウの妻なるアホリバマの子は左のごとし彼ヱウシ、ヤラムおよびコラをエサウに生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'エサウの子孫の侯たる者は左のごとしエサウの冢子エリパスの子にはテマン侯オマル侯ゼボ侯ケナズ侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'コラ侯ガタム侯アマレク侯是等はエリパズよりいでたる侯にしてエドムの地にありき是等はアダの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'エサウの子リウエルの子は左のごとしナハテ侯ゼラ侯シヤンマ侯ミザ侯是等はリウエルよりいでたる侯にしてエドムの地にありき是等はエサウの妻バスマテの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'エサウの妻アホリバマの子は左のごとしヱウシ侯ヤラム侯コラ侯是等はアナの女にしてエサウの妻なるアホリバマよりいでたる侯なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, '是等はエサウすなはちエドムの子孫にしてその侯たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, '素より此地に住しホリ人セイルの子は左のごとしロタン、シヨバル 、ヂベオン、アナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'デシヨン、エゼル、デシヤン是等はセイルの子ホリ人の中の侯にしてエドムの地にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'ロタンの子はホリ、ヘマムなりロタンの妹はテムナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'シヨバルの子は左のごとしアルワン、マナハテ、エバル、シボ、オナム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'ヂベオンの子は左のごとし即ちアヤとアナ此アナその父ヂベオンの驢馬を牧をりし時曠野にて温泉を發見り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'アナの子は左のごとしデシヨンおよびアホリバマ、アホリバマはアナの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'デシヨンの子は左のごとしヘムダン、エシバン、イテラン、ケラン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'エゼルの子は左のごとしビルハン、ザワン、ヤカン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'デシヤンの子は左のごとしウヅ、アラン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'ホリ人の侯たる者は左のごとしロタン侯シヨバル侯ヂベオン侯アナ侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'デシヨン侯エゼル侯デシヤン侯是等はホリ人の侯にしてその所領にしたがひてセイルの地にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'イスラエルの子孫を治むる王いまだあらざる前にエドムの地を治めたる王は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'ベオルの子ベラ、エドムに王たりその都の名はデナバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'ベラ薨てボヅラのゼラの子ヨバブ之にかはりて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'ヨバブ薨てテマン人の地のホシヤムこれにかはりて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'ホシヤム薨てベダデの子ハダデの子ハダこれに代て王となる彼モアブの野にてミデアン人を撃しことあり其邑の名はアビテといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'ハダデ薨てマスレカのサムラこれにかはりて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'サラム薨て河の旁なるレホボテのサウル之にかはりて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'サウル薨てアクボルの子バアルハナンこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'アクボルの子バアルハナン薨てハダル之にかはりて王となる其都の名はパウといふその妻の名はメヘタベルといひてマテレデの女なりマテレデはメザハブの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'エサウよりいでたる侯の名はその宗族と居處と名に循ひていへば左のごとしテムナ侯アルワ侯エテテ侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'アホリバマ侯エラ侯ピノン侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'ケナズ侯テマン侯ミブザル侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'マグデエル侯イラム侯是等はエドムの侯にして其領地の居處によりて言る者なりエドミ人の先祖はエサウ是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'ヤコブはカナンの地に住り即ちその父が寄寓し地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'ヤコブの傳は左のごとしヨセフ十七歳にしてその兄弟と偕に羊を牧ふヨセフは童子にしてその父の妻ビルハの子およびジルパの子と侶たりしが彼等の惡き事を父につぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'ヨセフは老年子なるが故にイスラエルその諸の兄弟よりも深くこれを愛しこれがために綵る衣を製れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'その兄弟等父がその諸の兄弟よりも深く彼を愛するを見て彼を惡み穩和に彼にものいふことを得せざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, '茲にヨセフ夢をみてその兄弟に告ければ彼等愈これを惡めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'ヨセフ彼等にいひけるは請ふわが夢たる此夢を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, '我等田の中に禾束をむすび居たるにわが禾束おき且立り而して汝等の禾束環りたちてわが禾束を拜せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'その兄弟等之にいひけるは汝眞にわれらの君となるや眞に我等ををさむるにいたるやとその夢とその言のために益これを惡めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'ヨセフ又一の夢をみて之をその兄弟に述ていひけるは我また夢をみたるに日と月と十一の星われを拜せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, '則ちこれをその父と兄弟に述ければ父かれを戒めて彼にいふ汝が夢しこの夢は何ぞや我と汝の母となんぢの兄弟と實にゆきて地に鞠て汝を拜するにいたらんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, '斯しかばその兄弟かれを嫉めり然どその父はこの言をおぼえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, '茲にその兄弟等シケムにゆきて父の羊を牧ゐたりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'イスラエル、ヨセフにいひけるは汝の兄弟はシケムにて羊を牧をるにあらずや來れ汝を彼等につかはさんヨセフ父にいふ我ここにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, '父かれにいひけるは請ふ往て汝の兄弟と群の恙なきや否を見てかへりて我につげよと彼をヘブロンの谷より遣はしければ遂にシケムに至る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, '或人かれに遇ふに彼野にさまよひをりしかば其人かれに問て汝何をたづぬるやといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, '彼いふ我はわが兄弟等をたづぬ請ふかれらが羊をかひをる所をわれに告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'その人いひけるは彼等は此をされり我かれらがドタンにゆかんといふを聞たりと是に於てヨセフその兄弟の後をおひゆきドタンにて之に遇ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'ヨセフの彼等に近かざる前に彼ら之を遙に見てこれを殺さんと謀り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, '互にいひけるは視よ作夢者きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, '去來彼をころして阱に投いれ或惡き獸これを食たりと言ん而して彼の夢の如何になるかを觀るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'ルベン聞てヨセフを彼等の手より拯ひださんとして言けるは我等これを殺すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'ルベンまた彼らにいひけるは血をながすなかれ之を曠野の此阱に投いれて手をこれにつくるなかれと是は之を彼等の手よりすくひだして父に歸んとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, '茲にヨセフ兄弟の許に到りければ彼等ヨセフの衣即ちその着たる綵る衣を褫ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, '彼を執て阱に投いれたり阱は空にしてその中に水あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, '斯して彼等坐てパンを食ひ目をあげて見しに一群のイシマエル人駱駝に香物と乳香と沒藥をおはせてエジプトにくだりゆかんとてギレアデより來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'ユダその兄弟にいひけるは我儕弟をころしてその血を匿すも何の益かあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, '去來彼をイシマエル人に賣ん彼は我等の兄弟われらの肉なればわれらの手をかれにつくべからずと兄弟等これを善とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, '時にミデアンの商旅經過ければヨセフを阱よりひきあげ銀二十枚にてヨセフをイシマエル人に賣り彼等すなはちヨセフをエジプトにたづさへゆきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, '茲にルベンかへりて阱にいたり見しにヨセフ阱にをらざりしかばその衣を裂き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, '兄弟の許にかへりて言ふ童子はをらず嗚呼我何處にゆくべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, '斯て彼等ヨセフの衣をとり牡山羊の羔をころしてその衣を血に濡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'その綵る衣を父におくり遣していひけるは我等これを得たりなんぢの子の衣なるや否を知れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, '父これを知りていふわが子の衣なり惡き獸彼をくらへりヨセフはかならずさかれしならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'ヤコブその衣を裂き麻布を腰にまとひ久くその子のためになげけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'その子女みな起てかれを慰むれどもその慰謝をうけずして我は哀きつつ陰府にくだりて我子のもとにゆかんといふ斯その父かれのために哭ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, '偖ミデアン人はエジプトにてパロの侍衞の長ポテパルにヨセフを賣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, '當時ユダ兄弟をはなれて下りアドラム人名はヒラといふ者の近邊に天幕をはりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'ユダかしこにてカナン人名はシュアといふ者の女子を見これを娶りてその所にいる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, '彼はらみて男子を生みければユダその名をエルとなづく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, '彼ふたたび孕みて男子を生みその名をオナンとなづけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'またかさねて孕みて男子を生みてその名をシラとなづく此子をうみける時ユダはクジブにありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'ユダその長子エルのために妻をむかふその名をタマルといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'ユダの長子エル、ヱホバの前に惡をなしたればヱホバこれを死しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, '茲にユダ、オナンにいひけるは汝の兄の妻の所にいりて之をめとり汝の兄をして子をえせしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'オナンその子の己のものとならざるを知たれば兄の妻の所にいりし時兄に子をえせしめざらんために地に洩したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, '斯なせし事ヱホバの目に惡かりければヱホバ彼をも死しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'ユダその媳タマルにいひけるは嫠婦となりて汝の父の家にをりわが子シラの人となるを待てと恐らくはシラも亦その兄弟のごとく死るならんとおもひたればなりタマルすなはち往てその父の家にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, '日かさなりて後シュアの女ユダの妻死たりユダ慰をいれてその友アドラム人ヒラとともにテムナにのぼりその羊毛を剪る者の所にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, '茲にタマルにつげて視よなんぢの舅はその羊の毛を剪んとてテムナにのぼるといふ者ありしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, '彼その嫠の服を脱すて被衣をもて身をおほひつつみテムナの途の側にあるエナイムの入口に坐す其はシラ人となりたれども己これが妻にせられざるを見たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, '彼その面を蔽ひゐたりしかばユダこれを見て娼妓ならんとおもひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, '途の側にて彼に就き請ふ來りて我をして汝の所にいらしめよといふ其はその子の妻なるをしらざればなり彼いひけるは汝何を我にあたへてわが所にいらんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'ユダいひけるは我群より山羊の羔をおくらん彼いふ汝其をおくるまで質をあたへんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'ユダ何の質をなんぢに與ふべきやといふに彼汝の印と綬と汝の手の杖をといひければ即ちこれを與へて彼の所にいりぬ彼ユダに由て姙めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, '彼起て去りその被衣をぬぎすて嫠婦の服をまとふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'かくてユダ婦の手より質をとらんとてその友アドラム人の手に托して山羊の羔をおくりけるが彼婦を見ざれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'その處の人に問て途の側なるエナイムの娼妓は何處にをるやといふに此には娼妓なしといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'ユダの許にかへりていふ我彼を見いださず亦その處の人此には娼妓なしといへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'ユダいひけるは彼にとらせおけ恐くはわれら笑抦とならん我この山羊の羔をおくりたるに汝かれを見ざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, '三月ばかりありて後ユダに告る者ありていふ汝の媳タマル姦淫をなせり亦その姦淫によりて妊めりユダいひけるは彼を曵いだして焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, '彼ひきいだされし時その舅にいひつかはしけるは是をもてる人によりて我は妊りと彼すなはち請ふこの印と綬と杖は誰の所屬なるかを辨別よといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'ユダこれを見識ていひけるは彼は我よりも正しわれ彼をわが子わがシラにあたへざりしによりてなりと再びこれを知らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'かくて產の時にいたりて見るにその胎に孿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'その產時手出しかば產婆是首にいづといひて絳き線をとりてその手にしばりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, '手を引こむるにあたりて兄弟いでたれば汝なんぞ圻いづるやその圻汝に歸せんといへり故にその名はペレヅ(圻)と稱る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'その兄弟手に絳線のある者後にいづその名はゼラとよばる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'ヨセフ挈へられてエジプトにくだりしがエジプト人ポテパル、パロの臣侍衞の長なる者彼を其處にたづさへくだれるイシマエル人の手よりこれを買ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'ヱホバ、ヨセフとともに在す彼享通者となりてその主人なるエジプト人の家にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'その主人ヱホバの彼とともにいますを見またヱホバがかれの手の凡てなすところを享通しめたまふを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, '是によりてヨセフ彼の心にかなひて其近侍となる彼ヨセフにその家を宰どらしめその所有を盡くその手に委たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, '彼ヨセフにその家とその有る凡の物をつかさどらせし時よりしてヱホバ、ヨセフのために其エジプト人の家を祝みたまふ即ちヱホバの祝福かれが家と田に有る凡の物におよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, '彼その有る物をことごとくヨセフの手にゆだねその食ふパンの外は何もかへりみざりき夫ヨセフは容貌麗しくして顏美しかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'これらの事の後その主人の妻ヨセフに目をつけて我と寢よといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'ヨセフ拒みて主人の妻にいひけるは視よわが主人の家の中の物をかへりみずその有るものことごとくわが手に委ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'この家には我より大なるものなし又主人何をも我に禁ぜず只汝を除くのみ汝はその妻なればなり然ば我いかで此おほいなる惡をなして神に罪ををかすをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, '彼日々にヨセフに言よりたれどもヨセフきかずして之といねず亦與にをらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, '當時ヨセフその職をなさんとて家にいりしが家の人一箇もその内にをらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, '時に彼婦その衣を執て我といねよといひければヨセフ衣を彼の手に棄おきて外に遁いでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, '彼ヨセフがその衣を己の手に棄おきて遁いでしを見て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'その家の人々を呼てこれにいふ視よヘブル人を我等の所につれ來て我等にたはむれしむ彼我といねんとて我の所にいり來しかば我大聲によばはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, '彼わが聲をあげて呼はるを聞しかばその衣をわが許にすておきて外に遁いでたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, '其衣を傍に置て主人の家に歸るを待つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'かくて彼是言のごとく主人につげていふ汝が我らに携へきたりしヘブルの僕われにたはむれんとて我許にいりきたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, '我聲をあげてよばはりしかばその衣を我許にすておきて遁いでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, '主人その妻が己につげて汝の僕斯のごとく我になせりといふ言を聞て怒を發せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, '是に於てヨセフの主人彼を執へて獄にいる其獄は王の囚徒を繋ぐ所なりヨセフ彼處にて獄にをりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'ヱホバ、ヨセフとともに在して之に仁慈を加へ典獄の恩顧をこれにえさせたまひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, '典獄獄にある囚人をことごとくヨセフの手に付せたり其處になす所の事は皆ヨセフこれをなすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, '典獄そのまかせたる所の事は何をもかへりみざりき其はヱホバ、ヨセフとともにいませばなりヱホバかれのなすところをさかえしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'これらの事の後エジプト王の酒人と膳夫その主エジプト王に罪ををかす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'パロその二人の臣すなはち酒人の長と膳夫の長を怒りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, '之を侍衞の長の家の中なる獄に幽囚ふヨセフが繋れをる所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, '侍衞の長ヨセフをして彼等の側に侍しめたればヨセフ之につかふ彼等幽囚れて日を經たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, '茲に獄に繋れたるエジプト王の酒人と膳夫の二人ともに一夜の中に各夢を見たりその夢はおのおんおのその解明にかなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'ヨセフ朝に及びて彼等の所に入て視るに彼等物憂に見ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, '是に於てヨセフその主人の家に己とともに幽囚をるパロの臣に問て汝等なにゆゑに今日は顏色あやしきやといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, '彼等これにいふ我等夢を見たれど之を解く者なしとヨセフ彼等にいひけるは解く事は神によるにあらずや請ふ我に述よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, '酒人の長その夢をヨセフに述て之にいふ我夢の中に見しにわが前に一の葡萄樹あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'その樹に三の枝あり芽いで花ひらきて葡萄なり球をなして熟たるがごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, '時にパロの爵わが手にあり我葡萄を摘てこれをパロの爵に搾りその爵をパロの手に奉たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'ヨセフ彼にいひけるはその解明は是のごとし三の枝は三日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, '今より三日の中にパロなんぢの首を擧げ汝を故の所にかへさん汝は曩に酒人たりし時になせし如くパロの爵をその手に奉ぐるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, '然ば請ふ汝善ならん時に我をおもひて我に恩惠をほどこし吾事をパロにのべてこの家よりわれを出せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, '我はまことにヘブル人の地より掠れ來しものなればなりまた此にても我は牢にいれらるるがごとき事はなさざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, '茲に膳夫の長その解明の善りしを見てヨセフにいふ我も夢を得て見たるに白きパン三筐わが首にありて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'その上の筐には膳夫がパロのために作りたる各種の饌ありしが鳥わが首の筐の中より之をくらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'ヨセフこたへていひけるはその解明はかくのごとし三の筐は三日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, '今より三日の中にパロ汝の首を擧はなして汝を木に懸んしかして鳥汝の肉をくらひとるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, '第三日はパロの誕辰なればパロその諸の臣僕に筵席をなし酒人の長と膳夫の長をして首をその臣僕の中に擧しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, '即ちパロ酒人の長をその職にかへしければ彼爵をパロの手に奉たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'されど膳夫の長は木に懸らるヨセフの彼等に解明せるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, '然るに酒人の長ヨセフをおぼえずして之を忘れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, '二年の後パロ夢ることあり即ち河の濱にたちて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, '視るに七の美しき肥たる牝牛河よりのぼりて葦を食ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'その後また七の醜き痩たる牛河よりのぼり河の畔にて彼牛の側にたちしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'その醜き痩たる牛かの美しき肥たる七の牛を食ひつくせりパロ是にいたりて寤む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, '彼また寢て再び夢るに一の莖に七の肥たる佳き穗いできたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, '其のちに又しなびて東風に燒たる七の穗いできたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'その七のしなびたる穗かの七の肥實りたる穗を呑盡せりパロ寤て見に夢なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'パロ朝におよびてその心安からず人をつかはしてエジプトの法術士とその博士を皆ことごとく召し之にその夢を述たり然ど之をパロに解うる者なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, '時に酒人の長パロに告ていふ我今日わが過をおもひいづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, '甞てパロその僕を怒て我と膳夫の長を侍衞の長の家に幽囚へたまひし時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, '我と彼ともに一夜のうちに夢み各その解明にかなふ夢をみたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, '彼處に侍衞の長の僕なる若きヘブル人我らと偕にあり我等これにのべたれば彼われらの夢を解その夢にしたがひて各人に解明をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'しかして其事かれが解たるごとくなりて我はわが職にかへり彼は木に懸らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, '是に於てパロ人をやりてヨセフを召しければ急ぎてこれを獄より出せりヨセフすなはち髭を薙り衣をかへてパロの許にいり來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'パロ、ヨセフにいひけるは我夢をみたれど之をとく者なし聞に汝は夢をききて之を解くことをうると云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'ヨセフ、パロにこたへていひけるは我によるにあらず神パロの平安を告たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'パロ、ヨセフにいふ我夢に河の岸にたちて見るに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, '河より七の肥たる美しき牝牛のぼりて葦を食ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, '後また弱く甚だ醜き瘠たる七の牝牛のぼりきたる其惡き事エジプト全國にわが未だ見ざるほどなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'その瘠たる醜き牛初の七の肥たる牛を食ひつくしたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, '已に腹にいりても其腹にいりし事しれず尚前のごとく醜かりき我是にいたりて寤めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, '我また夢に見るに七の實たる佳き穗一の莖にいできたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'その後にまたいぢけ萎びて東風にやけたる七の穗生じたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'そのしなびたる穗かの七の佳穗を呑つくせり我これを法術士に告たれどもわれにこれをしめすものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'ヨセフ、パロにいひけるはパロの夢は一なり神その爲んとする所をパロに示したまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, '七の美牝牛は七年七の佳穗も七年にして夢は一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, '其後にのぼりし七の瘠たる醜き牛は七年にしてその東風にやけたる七の空穗は七年の饑饉なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, '是はわがパロに申すところなり神そのなさんとするところをパロにしめしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'エジプトの全地に七年の大なる豐年あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'その後に七年の凶年おこらん而してエジプトの地にありし豐作を皆忘るにいたるべし饑饉國を滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, '後にいたるその饑饉はなはだはげしきにより前の豐作國の中に知れざるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'パロのふたたび夢をかさね見たまひしは神がこの事をさだめて速に之をなさんとしたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'さればパロ慧く賢き人をえらみて之にエジプトの國を治めしめたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'パロこれをなし國中に官吏を置てその七年の豐年の中にエジプトの國の五分の一を取たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, '而して其官吏をして來らんとするその善き年の諸の糧食を斂めてその穀物をパロの手に蓄へしめ糧食を邑々にかこはしめたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'その糧食を國のために畜藏へおきてエジプトの國にのぞむ七年の饑饉に備へ國をして饑饉のために滅ざらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'パロとその諸の臣僕此事を善とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, '是に於てパロその臣僕にいふ我等神の靈のやどれる是のごとき人を看いだすをえんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'しかしてパロ、ヨセフにいひけるは神是を盡く汝にしめしたまひたれば汝のごとく慧く賢き者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, '汝わが家を宰るべしわが民みな汝の口にしたがはん唯位においてのみ我は汝より大なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'パロ、ヨセフにいひけるは視よ我汝をエジプト全國の冢宰となすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'パロすなはち指環をその手より脱して之をヨセフの手にはめ之を白布を衣せ金の索をその項にかけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, '之をして己のもてる次の輅に乗しめ下にゐよと其前に呼しむ是彼をエジプト全國の冢宰となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'パロ、ヨセフにいひけるは我はパロなりエジプト全國に汝の允准をえずして手足をあぐる者なかるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'パロ、ヨセフの名をザフナテパネアと名けまたオンの祭司ポテパルの女アセナテを之にあたへて妻となさしむヨセフいでてエジプトの地をめぐる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'ヨセフはエジプトの王パロのまへに立し時三十歳なりきヨセフ、パロのまへを出て遍くエジプトの地を巡れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, '七年の豐年の中に地山なして物を生ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'ヨセフすなはちエジプトの地にありしその七年の糧食を斂めてその糧食を邑々に藏む即ち邑の周圍の田圃の糧食を其邑の中に藏む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'ヨセフ海隅の沙のごとく甚だ多く穀物を儲へ遂に數ふることをやむるに至る其は數かぎり無ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, '饑饉の歳のいたらざる前にヨセフに二人の子うまる是はオンの祭司ポテパルの女アセナテの生たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'ヨセフその冢子の名をマナセ(忘)となづけて言ふ神我をしてわが諸の苦難とわが父の家の凡の事をわすれしめたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, '又次の子の名をエフライム(多く生る)となづけていふ神われをしてわが艱難の地にて多くの子をえせしめたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, '爰にエジプトの國の七年の豐年をはり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'ヨセフの言しごとく七年の凶年きたりはじむその饑饉は諸の國にあり然どエジプト全國には食物ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'エジプト全國饑し時民さけびてパロに食物を乞ふパロ、エジプトの諸の人にいひけるはヨセフに往け彼が汝等にいふところをなせと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, '饑饉全地の面にありヨセフすなはち諸の倉廩をひらきてエジプト人に賣わたせり饑饉ますますエジプトの國にはげしくなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, '饑饉諸の國にはげしくなりしかば諸國の人エジプトにきたりヨセフにいたりて穀物を買ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'ヤコブ、エジプトに穀物あるを見しかばその子等にいひけるは汝等なんぞたがひに面を見あはするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'ヤコブまたいふ我エジプトに穀物ありと聞り彼處にくだりて彼處より我等のために買きたれ然らばわれら生るを得て死をまぬかれんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'ヨセフの十人の兄弟エジプトにて穀物をかはんとて下りゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'されどヨセフの弟ベニヤミンはヤコブこれをその兄弟とともに遣さざりきおそらくは災難かれの身にのぞむことあらんと思たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'イスラエルの子等穀物を買んとて來る者とともに來る其はカナンの地に饑饉ありたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, '時にヨセフは國の總督にして國の凡の人に賣ことをなせりヨセフの兄弟等來りてその前に地に伏て拜す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'ヨセフその兄弟を見てこれを知たれども知ざる者のごとくして荒々しく之にものいふ即ち彼等に汝等は何處より來れるやといへば彼等いふ糧食を買んためにカナンの地より來れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'ヨセフはその兄弟をしりたれども彼等はヨセフをしらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'ヨセフその昔に彼等の事を夢たる夢をを憶いだし彼等に言けるは汝等は間者にして此國の隙を窺んとて來れるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, '彼等之にいひけるはわが主よ然らず唯糧食をかはんとて僕等は來れるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, '我等はみな一箇の人の子にして篤實なる者なり僕等は間者にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'ヨセフ彼等にいひけるは否汝等は此地の隙を窺んとて來れるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, '彼等いひけるは僕等は十二人の兄弟にしてカナンの地の一箇の人の子なり季子は今日父とともにをる又一人はをらずなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'ヨセフかれらにいひけるはわが汝等につげて汝等は間者なりといひしはこの事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, '汝等斯してその眞實をあかすべしパロの生命をさして誓ふ汝等の末弟ここに來るにあらざれば汝等は此をいづるをえじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, '汝等の一人をやりて汝等の弟をつれきたらしめよ汝等をば繋ぎおきて汝等の言をためし汝らの中に眞實あるや否をみんパロの生命をさして誓ふ汝等はかならず間者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, '彼等を皆ともに三日のあひだ幽囚おけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, '三日におよびてヨセフ彼等にいひけるは我神を畏る汝等是なして生命をえよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, '汝等もし篤實なる者ならば汝らの兄弟の一人をしてこの獄に繋れしめ汝等は穀物をたづさへゆきてなんぢらの家々の饑をすくへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, '但し汝らの末弟を我につれきたるべしさすればなんぢらの言の眞實あらはれて汝等死をまぬかるべし彼等すなはち斯なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, '茲に彼らたがひに言けるは我等は弟の事によりて信に罪あり彼等は彼が我らに只管にねがひし時にその心の苦を見ながら之を聽ざりき故にこの苦われらにのぞめるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'ルベンかれらに對ていひけるは我なんぢらにいひて童子に罪ををかすなかれといひしにあらずや然るに汝等きかざりき是故に視よ亦彼の血をながせし罪をたださると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, '彼等はヨセフが之を解するをしらざりき其は互に通辨をもちひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'ヨセフ彼等を離れゆきて哭き復かれらにかへりて之とかたり遂にシメオンを彼らの中より取りその目のまへにて之を縛れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, '而してヨセフ命じてその器に穀物をみたしめ其人々の金を嚢に返さしめ又途の食を之にあたへしむヨセフ斯かれらになせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, '彼等すなはち穀物を驢馬におはせて其處をさりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, '其一人旅邸にて驢馬に糧を與んとて嚢をひらき其金を見たり其は嚢の口にありければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, '彼その兄弟にいひけるは吾金は返してあり視よ嚢の中にありと是において彼等膽を消し懼れてたがひに神の我らになしたまふ此事は何ぞやといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'かくて彼等カナンの地にかへりて父ヤコブの所にいたり其身にありし事等を悉く之につげていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '彼國の主荒々しく我等にものいひ我らをもて國を偵ふ者となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, '我ら彼にいふ我等は篤實なる者なり間者にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, '我らは十二人の兄弟にして同じ父の子なり一人はをらずなり季のは今日父とともにカナンの地にありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, '國の主なるその人われらにいひけるは我かくして汝等の篤實なるをしらん汝等の兄弟の一人を吾もとにのこし糧食をたづさへゆきて汝らの家々の饑をすくへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'しかして汝らの季の弟をわが許につれきたれ然れば我なんぢらが間者にあらずして篤實なる者たるをしらん我なんぢらの兄弟を汝等に返し汝等をしてこの國にて交易をなさしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, '茲に彼等その嚢を傾たるに視よ各人の金包その嚢のなかにあり彼等とその父金包を見ておそれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'その父ヤコブ彼等にいひけるは汝等は我をして子を喪はしむヨセフはをらずなりシメオンもをらずなりたるにまたベニヤミンを取んとす是みなわが身にかかるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'ルベン父に告ていふ我もし彼を汝につれかへらずば吾ふたりの子を殺せ彼をわが手にわたせ我之をなんぢにつれかへらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'ヤコブいひけるはわが子はなんぢらとともに下るべからず彼の兄は死て彼ひとり遺たればなり若なんぢらが行ところの途にて災難かれの身におよばば汝等はわが白髮をして悲みて墓にくだらしむるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, '饑饉その地にはげしかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, '茲に彼等エジプトよりもちきたりし穀物を食つくせし時父かられらに再びゆきて少許の糧食を買きたれといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'ユダ父にかたりていひけるは彼人かたく我等をいましめていふ汝らの弟汝らとともにあるにあらざれば汝らはわが面をみるべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, '汝もし弟をわれらとともに遣さば我等下て汝のために糧食を買ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'されど汝もし彼をつかはさずば我等くだらざるべし其はかの人われらにむかひ汝等の弟なんぢらとともにあるにあらざれば汝ら吾面をみるべからずといひたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'イスラエルいひけるは汝等なにゆゑに汝等に尚弟のあることを彼人につげて我を惡くなすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, '彼等いふ其人われらの模樣とわれらの親族を問ただして汝らの父は尚生存へをるや汝等は弟をもつやといひしにより其言の條々にしたがひて彼につげたるなり我等いかでか彼が汝等の弟をつれくだれといふならんとしるをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'ユダ父イスラエルにいひけるは童子をわれとともに遣はせ我等たちて往ん然らば我儕と汝およびわれらの子女生ることを得て死をまぬかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, '我彼の身を保はん汝わが手にかれを問へ我もし彼を汝につれかへりて汝のまへに置ずば我永遠に罪をおはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, '我儕もし濡滯ことなかりしならば必ずすでにゆきて再びかへりしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, '父イスラエル彼等にいひけるは然ば斯なせ汝等國の名物を器にいれ携へくだりて彼人に禮物とせよ乳香少許、蜜少許、香物、沒藥、胡桃および巴旦杏');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, '又手に一倍の金を取りゆけ汝等の嚢の口に返してありし彼金を再び手にたづさへ行べし恐くは差謬にてありしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, '且また汝らの弟を挈へ起てふたたたび其人の所にゆけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'ねがはくは全能の神その人のまへにて汝等を矜恤みその人をして汝等の他の兄弟とベニヤミンを放ちかへさしめたまはんことを若われ子に別るべくあらば別れんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, '是に於てかの人々その禮物を執り一倍の金を手に執りベニヤミンを携へて起てエジプトにくだりヨセフの前に立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'ヨセフ、ベニヤミンの彼らと偕なるを見てその家宰にいひけるはこの人々を家に導き畜を屠て備へよこの人々卓午に我とともに食をなすべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, '其人ヨセフのいひしごとくなし其人この人々をヨセフの家に導けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, '人々ヨセフの家に導かれたるによりて懼れいひけるは初めにわれらの嚢にかへりてありし金の事のために我等はひきいれらる是われらを抑留へて我等にせまり執へて奴隸となし且われらの驢馬を取んとするなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, '彼等すなはちヨセフの家宰に進みよりて家の入口にて之にかたりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'いひけるは主よ我等實に最初くだりて糧食を買たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'しかるに我等旅邸に至りて嚢を啓き見るに各人の金その嚢の口にありて其金の量全かりし然ば我等これを手にもちかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, '又糧食を買ふ他の金をも手にもちくだる我等の金を嚢にいれたる者は誰なるかわれらは知ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, '彼いひけるは汝ら安ぜよ懼るなかれ汝らの神汝らの父の神財寶を汝等の嚢におきて汝らに賜ひしなり汝らの金は我にとどけりと遂にシメオンを彼等の所にたづさへいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'かくて其人この人々をヨセフの家に導き水をあたへてその足を濯はしめ又その驢馬に飼草をあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, '彼等其處にて食をなすなりと聞しかば禮物を調へてヨセフの日午に來るをまつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, '茲にヨセフ家にかへりしかば彼等その手の禮物を家にもちきたりてヨセフの許にいたり地に伏てこれを拜す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'ヨセフかれらの安否をとふていふ汝等の父汝らが初にかたりしその老人は恙なきや尚いきながらへをるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, '彼等こたへてわれらの父汝の僕は恙なくしてなほ生ながらへをるといひ身をかがめ禮をなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'ヨセフ目をあげてその母の子なる己の弟ベニヤミンを見ていひけるは是は汝らが初に我にかたりし汝らの若き兄弟なるや又いふわが子よ願はくは神汝をめぐみたまはんことをと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'ヨセフその弟のために心焚るがごとくなりしかば急ぎてその泣べきところを尋ね室にいりて其處に泣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, '而して面をあらひて出で自から抑へて食をそなへよといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'すなはちヨセフはヨセフ彼等は彼等陪食するエジプト人はエジプト人と別々に之を供ふ是はエジプト人ヘブル人と共に食することをえざるによる其事エジプト人の穢はしとするところなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'かくて彼等ヨセフの前に坐るに長子をばその長たるにしたがひて坐らせ若き者をばその幼少にしたがひてすわらせければその人々駭きあへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'ヨセフ己のまへより皿を彼等に供ふベニヤミンの皿は他の人のよりも五倍おほかりきかれら飮てヨセフとともに樂めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, '茲にヨセフその家宰に命じていふこの人々の嚢にその負うるほど糧食を充せ各人の金をその嚢の口に置れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'またわが杯すなはち銀の杯を彼の少き者の嚢の口に置てその穀物の金子とともにあらしめよと彼がヨセフがいひし言のごとくなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'かくて夜のあくるにおよびてその人々と驢馬をかへしけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'かれら城邑をいでてなほ程とほからぬにヨセフ家宰にいひけるは起てかの人々の後を追ひおひつきし時之にいふべし汝らなんぞ惡をもて善にむくゆるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, '其はわが主がもちひて飮み又用ひて常に卜ふ者にあらずや汝らかくなすは惡しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, '是に於て家宰かれらにおひつきてこの言をかれらにいひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'かれら之にいふ主なにゆゑに是事をいひたまふや僕等きはめてこの事をなさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, '視よ我らの嚢の口にありし金はカナンの地より汝の所にもちかへれり然ば我等いかで汝の主の家より金銀をぬすまんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, '僕等の中誰の手に見あたるも其者は死べし我等またわが主の奴隸となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, '彼いひけるはさらば汝らの言のごとくせん其の見あたりし者はわが奴隸となるべし汝等は咎なしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, '是において彼等急ぎて各その嚢を地におろし各その嚢をひらきしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, '彼すなはち索し長者よりはじめて少者にをはるに杯はベニヤミンの嚢にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, '斯有しかば彼等その衣を裂きおのおのその驢馬に荷を負せて邑にかへる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'しかしてユダとその兄弟等ヨセフの家にいたるにヨセフなほ其處にをりしかばその前に地に伏す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'ヨセフかれらにいひけるは汝等がなしたるこの事は何ぞや我のごとき人は善く卜ひうる者なるをしらざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'ユダいひけるは我等主に何をいはんや何をのべんや如何にしてわれらの正直をあらはさんや神僕等の罪を摘發したまへり然ば我等およびこの杯の見あたりし者倶に主の奴隸となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'ヨセフいひけるはきはめて然せじ杯の手に見あたりし人はわが奴隸となるべし汝等は安然に父にかへりのぼるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, '時にユダかれに近よりていひけるはわが主よ請ふ僕をして主の耳に一言いふをえせしめよ僕にむかひて怒を發したまふなかれ汝はパロのごとくにいますなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, '昔にわが主僕等に問て汝等は父あるや弟あるやといひたまひしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, '我等主にいへり我等にわが父あり老人なり又その老年子なる少者ありその兄は死てその母の遺せるは只是のみ故に父これを愛すと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, '汝また僕等にいひたまはく彼を我許につれくだり我をして之に目をつくることをえせしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'われら主にいへり童子父を離るをえず若父をはなるるならば父死べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, '汝また僕等にいひたまはく汝らの季の弟汝等とともに下るにあらざれば汝等ふたたたびわが面を見るべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, '我等すなはちなんぢの僕わが父の所にかへりのぼりて主の言をこれに告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, '我らの父再びゆきて少許の糧食を買きたれといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, '我らいふ我らくだりゆくことをえずわれらの季の弟われらと共にあらば下りゆくべし其は季の弟われらと共にあるにあらざれば彼人の面をみるをえざればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'なんぢの僕わが父われらにいふ汝らのしるごとく吾妻われに二人を生しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'その一人出てわれをはなれたれば必ず裂ころされしならんと思へり我今にいたるまで彼を見ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'なんぢら是をも我側より取ゆかんに若災害是の身におよぶあらば遂にわが白髮をして悲みて墓にくだらしむるにいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, '抑父の生命と童子の生命とは相結びてあれば我なんぢの僕わが父に歸りいたらん時に童子もしわれらと共に在ずば如何ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, '父童子の在ざるを見ば死るにいたらん然れば僕等なんぢの僕われらの父の白髮をして悲みて墓にくだらしむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, '僕わが父に童子の事を保ひて我もし是を汝につれかへらずば永久に罪を父に負んといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'されば請ふ僕をして童子にかはりをりて主の奴隸とならしめ童子をしてその兄弟とともに歸りのぼらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, '我いかでか童子を伴はずして父の許に上りゆくべけん恐くは災害の父におよぶを見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, '茲にヨセフその側にたてる人々のまへに自ら禁ぶあたはざるに至りければ人皆われを離ていでよと呼はれり是をもてヨセフが己を兄弟にあかしたる時一人も之とともにたつものなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'ヨセフ聲をあげて泣りエジプト人これを聞きパロの家またこれを聞く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'ヨセフすなはちその兄弟にいひけるは我はヨセフなりわが父はなほ生ながらへをるやと兄弟等その前に愕き懼れて之にこたふるをえざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'ヨセフ兄弟にいひけるは請ふ我にちかよれとかれらすなはち近よりければ言ふ我はなんぢらの弟ヨセフなんぢらがエジプトにうりたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'されど汝等我をここに賣しをもて憂ふるなかれ身を恨るなかれ神生命をすくはしめんとて我を汝等の前につかはしたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'この二年のあひだ饑饉國の中にありしが尚五年の間耕すことも穫こともなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, '神汝等の後を地につたへんため又大なる救をもて汝らの生命を救はんために我を汝等の前に遣したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, '然ば我を此につかはしたる者は汝等にはあらず神なり神われをもてパロの父となしその全家の主となしエジプト全國の宰となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, '汝等いそぎ父の許にのぼりゆきて之にいへ汝の子ヨセフかく言ふ神われをエジプト全國の主となしたまへりわが所にくだれ遲疑なかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, '汝ゴセンの地に住べし斯汝と汝の子と汝の子の子およびなんぢの羊と牛並に汝のすべて有ところの者われの近方にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'なほ五年の饑饉あるにより我其處にてなんぢを養はん恐くは汝となんぢの家族およびなんぢの凡て有ところの者匱乏ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, '汝等の目とわが弟ベニヤミンの目の視るごとく汝等にこれをいふ者はわが口なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, '汝等わがエジプトにて亨る顯榮となんぢらが見たる所とを皆悉く父につげよ汝ら急ぎて父を此にみちびき下るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, '而してヨセフその弟ベニヤミンの頸を抱へて哭にベニヤミンもヨセフの頸をかかへて哭く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'ヨセフ亦その諸の兄弟に接吻し之をいだきて哭く是のち兄弟等ヨセフと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, '茲にヨセフの兄弟等きたれりといふ聲パロの家にきこえければパロとその臣僕これを悦ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'パロすなはちヨセフにいひけるは汝の兄弟に言べし汝等かく爲せ汝等の畜に物を負せ往てカナンの地に至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'なんぢらの父となんぢらの家族を携へて我にきたれ我なんぢらにエジプトの地の嘉物をあたへん汝等國の膏腴を食ふことをうべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, '今汝命をうく汝等かく爲せ汝等エジプトの地より車を取ゆきてなんぢらの子女と妻等を載せ汝等の父を導きて來れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'また汝等の器を惜み視るなかれエジプト全國の嘉物は汝らの所屬なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'イスラエルの子等すなはち斯なせりヨセフ、パロの命にしたがひて彼等に車をあたへかつ途の餱糧をかれらにあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, '又かれらに皆おのおの衣一襲を與へたりしがベニヤミンには銀三百と衣五襲をあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, '彼また斯のごとく父に餽れり即ち驢馬十疋にエジプトの嘉物をおはせ牝の驢馬十疋に父の途の用に供ふる穀物と糧と肉をおはせて餽れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, '斯して兄弟をかへして去しめ之にいふ汝等途にて相あらそふなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'かれらエジプトより上りてカナンの地にゆきその父ヤコブにいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, '之につげてヨセフは尚いきてをりエジプト全國の宰となりをるといふしかるにヤコブの心なほ寒冷なりき其はこれを信ぜざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, '彼等またヨセフの己にいひたる言をことごとく之につげたりその父ヤコブ、ヨセフがおのれを載んとておくりし車をみるにおよびて其氣おのれにかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'イスラエルすなはちいふ足りわが子ヨセフなほ生をるわれ死ざるまへに往て之を視ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'イスラエルその己につける諸の者とともに出たちベエルシバにいたりてその父イサクの神に犧牲をささぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, '神夜の異象にイスラエルにかたりてヤコブよヤコブよといひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'ヤコブわれ此にありといひければ神いひたまふ我は神なり汝の父の神なりエジプトにくだることを懼るなかれわれ彼處にて汝を大なる國民となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, '我汝と共にエジプトに下るべし亦かならず汝を導のぼるべしヨセフ手をなんぢの目の上におかんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'かくてヤコブ、ベエルシバをたちいでたりイスラエルの子等すなはちパロの載んとておくりたる車に父ヤコブと己の子女と妻等を載せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'その家畜とカナンの地にてえたる貨財をたづさへ斯してヤコブとその子孫皆ともにエジプトにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'ヤコブかくその子と子の子およびその女と子の女すなはちその子孫を皆ともなひてエジプトににつれゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'イスラエルの子のエジプトにくだれる者の名は左のごとしヤコブとその子等ヤコブの長子はルベン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'ルベンの子はヘノク、パル、ヘヅロン、カルミ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'シメオンの子はヱムエル、ヤミン、オハデ、ヤキン、ゾハルおよびカナンの婦のうめる子シヤウル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'レビの子はゲルシヨン、コハテ、メラリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'ユダの子エル、オナン、シラ、ペレヅ、ゼラ但しエルとオナンはカナンの地に死たりペレヅの子はヘヅロンおよびハムルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'イツサカルの子はトラ、プワ、ヨブ、シムロン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'ゼブルンの子はセレデ、エロン、ヤリエルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, '是等および女子デナはレアがパダンアラムにてヤコブにうみたる者なりその男子女子あはせて三十三人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'ガドの子はゼボン、ハギ、シユニ、エヅポン、エリ、アロデ、アレリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'アセルの子はヱムナ、イシワ、イスイ、ベリアおよびその妹サラ並にベリアの子ヘベルとマルキエルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, '是等はラバンがその女レアにあたへたるジルパの子なり彼是等をヤコブにうめり都合十六人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'ヤコブの妻ラケルの子はヨセフとベニヤミンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'エジプトの國にてヨセフにマナセとエフライムうまれたり是はオンの祭司ポテパルの女アセナテが生たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'ベニヤミンの子はベラ、ベケル、アシベル、ゲラ、ナアマン、エヒ、ロシ、ムツピム、ホパム、アルデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, '是等はラケルの子にしてヤコブにうまれたる者なり都合十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'ダンの子はホシム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'ナフタリの子はヤジエル、グニ、ヱゼル、シレム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, '是等はラバンがその女ラケルにあたへたるビルハの子なり彼これらをヤコブにうめり都合七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'ヤコブとともにエジプトにいたりし者はヤコブの子の妻をのぞきて六十六人なりき是皆ヤコブの身よりいでたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'エジプトにてヨセフにうまれたる子二人ありヤコブの家の人のエジプトにいたりし者はあはせて七十人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'ヤコブ預じめユダをヨセフにつかはしおのれをゴセンにみちびかしむ而して皆ゴセンの地にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'ヨセフその車を整へゴセンにのぼりて父イスラエルを迓へ之にまみえてその頸を抱き頸をかかへて久く啼く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'イスラエル、ヨセフにいふ汝なほ生てをり我汝の面を見ることをえたれば今は死るも可しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'ヨセフその兄弟等と父の家族とにいひけるは我のぼりてパロにつげて之にいふべしわが兄弟等とわが父の家族カナンの地にをりし者我のところに來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'その人々は牧者にして牧畜の人なり彼等その羊と牛およびその有る諸の物をたづさへ來れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'パロもし汝等を召て汝等の業は何なるやと問ことあらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, '僕等は幼少より今に至るまで牧畜の人なり我儕も先祖等もともにしかりといへしからばなんぢらゴセンの地にすむことをえん牧者は皆エジプト人の穢はしとするものなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, '茲にヨセフゆきてパロにつげていひけるはわが父と兄弟およびその羊と牛と諸の所有物カナンの地よりいたれり彼らはゴセンの地にをると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'その兄弟の中より五人をとりてこれをパロにまみえしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'パロ、ヨセフの兄弟等にいひけるは汝らの業は何なるか彼等パロにいふ僕等は牧者なりわれらも先祖等もともにしかりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'かれら又パロにいひけるは此國に寓らんとて我等はきたる其はカナンの地に饑饉はげしくして僕等の群をやしなふ牧場なければなりされば請ふ僕等をしてゴセンの地にすましめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'パロ、ヨセフにかたりていふ汝の父と兄弟汝の所にきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'エジプトの地はなんぢの前にあり地の善き處に汝の父と兄弟をすましめよすなはちゴセンの地にかれらをすましめよ汝もし彼等の中に才能ある者あるをしらば其人々をしてわが家畜をつかさどらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'ヨセフまた父ヤコブを引ていりパロの前にたたしむヤコブ、パロを祝す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'パロ、ヤコブにいふ汝の齡の日は幾何なるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'ヤコブ、パロにいひけるはわが旅路の年月は百三十年にいたる我が齡の日は僅少にして且惡かり未だわが先祖等の齡の日と旅路の日にはおよばざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'ヤコブ、パロを祝しパロのまへよりいでさりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'ヨセフ、パロの命ぜしごとくその父と兄弟に居所を與へエジプトの國の中の善き地即ちラメセスの地をかれらにあたへて所有となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'ヨセフその父と兄弟と父の全家にその子の數にしたがひて食物をあたへて養へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, '却説饑饉ははなはだはげしくして全國に食物なくエジプトの國とカナンの國饑饉のために弱れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'ヨセフ穀物を賣あたへてエジプトの地とカナンの地にありし金をことごとく斂む而してヨセフその金をパロの家にもちきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'エジプトの國とカナンの國に金つきたればエジプト人みなヨセフにいたりていふ我等に食物をあたへよ如何ぞなんぢの前に死べけんや金すでにたえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'ヨセフいひけるは汝等の家畜をいだせ金もしたえたらば我なんぢらの家畜にかへて與ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'かれら乃ちその家畜をヨセフにひききたりければヨセフその馬と羊の群と牛の群および驢馬にかへて食物をかれらにあたへそのすべての家畜のために其年のあひだ食物をあたへてこれをやしなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'かくてその年暮けるが明年にいたりて人衆またヨセフにきたりて之にいふ我等主に隱すところなしわれらの金は竭たりまたわれらの畜の群は主に皈す主のまへにいだすべき者は何ものこりをらず唯われらの身體と田地あるのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'われらいかんぞわれらの田地とともに汝の目のまへに死亡ぶべけんや我等とわれらの田地を食物に易て買とれ我等田地とともにパロの僕とならんまた我等に種をあたへよ然ばわれら生るをえて死るにいたらず田地も荒蕪にいたらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, '是に於てヨセフ、エジプトの田地をことごとく購とりてパロに納る其はエジプト人饑饉にせまりて各人その田圃を賣たればなり是によりて地はパロの所有となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'また民はエジプトのこの境の極よりかの境の極の者までヨセフこれを邑々にうつせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, '但祭司の田地は購とらざりき祭司はパロより祿をたまはりをればパロの與る祿を食たるによりてその田地を賣ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, '茲にヨセフ民にいひけるは視よ我今日汝等となんぢらの田地をかひてパロに納る視よこの種子を汝らに與ふ地に播べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'しかして收穫の五分の一をパロに輸し四分をなんぢらに取て田圃の種としなんぢらの食としなんぢらの家族と子女の食とせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, '人衆いひけるは汝われらの生命を拯ひたまへりわれら主のまへに恩をえんことをねがふ我等パロの僕となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'ヨセフ、エジプトの田地に法をたてその五分の一をパロにをさめしむその事今日にいたる唯祭司の田地のみパロの有とならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'イスラエル、エジプトの國に於てゴセンの地にすみ彼處に產業を獲その數増て大に殖たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'ヤコブ、エジプトの國に十七年いきながらへたりヤコブの年齒の日は合て百四十七年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'イスラエル死る日ちかよりければその子ヨセフをよびて之にいひけるは我もし汝のまへに恩を得るならば請ふなんぢの手をわが髀の下にいれ懇に眞實をもて我をあつかへ我をエジプトに葬るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, '我は先祖等とともに偃んことをねがふ汝われをエジプトよ舁いだして先祖等の墓場にはうむれヨセフいふ我なんぢが言るごとくなすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'ヤコブまた我に誓へといひければすなはち誓へりイスラエル床の頭にて拜をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, '是等の事の後汝の父病にかかるとヨセフに告る者ありければヨセフ二人の子マナセとエフライムをともなひて至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, '人ヤコブに告て汝の子ヨセフなんぢの許にきたるといひければイスラエル強て床に坐す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'しかしてヤコブ、ヨセフにいひけるは昔に全能の神カナンの地のルズにて我にあらはれて我を祝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, '我にいひたまひけらく我なんぢをして多く子をえせしめ汝をふやし汝を衆多の民となさん我この地を汝の後の子孫にあたへて永久の所有となさしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'わがエジプトにきたりて汝に就まへにエジプトにて汝に生れたる二人の子エフライムとマナセ是等はわが子となるべしルベンとシメオンのごとく是等はわが子とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, '是等の後になんぢが得たる子は汝のものとすべし又その產業はその兄弟の名をもて稱らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, '我事をいはんに我昔パダンより來れる時ラケル我にしたがひをりて途にてカナンの地に死り其處はエフラタまで尚途の隔あるところなりわれ彼處にて彼をエフラタの途にはうむれり(エフラタはすなはちベテレヘムなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, '斯てイスラエル、ヨセフの子等を見て是等は誰なるやといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'ヨセフ父にいふ是は神の此にて我にたまひし子等なりと父すなはちいふ請ふ彼らを我所につれきたれ我これを祝せんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'イスラエルの目は年壽のために眯て見るをえざりしがヨセフかれらをその許につれきたりければ之に接吻してこれを抱けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'しかしてイスラエル、ヨセフにいひけるは我なんぢの面を見るあらんとは思はざりしに視よ神なんぢの子をもわれにしめしたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'ヨセフかれらをその膝の間よりいだし地に俯て拜せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'しかしてヨセフ、エフライムを右の手に執てヤコブに左の手にむかはしめマナセを左の手に執てヤコブの右の手にむかはしめ二人をみちびきてかれに就ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'イスラエル右の手をのべて季子エフライムの頭に按き左の手をのべてマナセの頭におけりマナセは長子なれども故にかくその手をおけるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, '斯してヨセフを祝していふわが父アブラハム、イサクの事へし神わが生れてより今日まで我をやしなひたまひし神');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, '我をして諸の災禍を贖はしめたまひし天使ねがはくは是童子等を祝たまへねがはくは是等の者わが名とわが父アブラハム、イサクの名をもて稱られんことをねがはくは是等地の中に繁殖がるにいたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'ヨセフ父が右の手をエフライムの頭に按るを見てよろこばず父の手をあげて之をエフライムの頭よりマナセの頭にうつさんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'ヨセフすなはち父にいひけるは然にあらず父よ是長子なれば右の手をその頭に按たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, '父こばみていひけるは我知るわが子よわれしる彼も一の民となり彼も大なる者とならん然れどもその弟は彼よりも大なる者となりてその子孫は多衆の國民となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, '此日彼等を祝していふイスラエル汝を指て人を祝し願くは神汝をしてエフライムのごとくマナセのごとくならしめたまへといふにいたらんとすなはちエフライムをマナセの先にたてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'イスラエルまたヨセフにいひけるは視よわれは死んされど神なんぢらとともにいまして汝等を先祖等の國にみちびきかへりたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, '且われ一の分をなんぢの兄弟よりもおほく汝にあたふ是わが刀と弓を以てアモリ人の手より取たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'ヤコブその子等を呼ていひけるは汝らあつまれ我後の日に汝らが遇んところの事を汝等につげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, '汝等つどひて聽けヤコブの子等よ汝らの父イスラエルに聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'ルベン汝はわが冢子わが勢わが力の始威光の卓越たる者權威の卓越たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, '汝は水の沸あがるがごとき者なれば卓越を得ざるべし汝父の床にのぼりて浼したればなり嗚呼彼はわが寢牀にのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'シメオン、レビは兄弟なりその劍は暴逆の器なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, '我魂よかれらの席にのぞむなかれ我寶よかれらの集會につらなるなかれ其は彼等その怒にまかせて人をころしその意にまかせて牛を筋截たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'その怒は烈しかれば詛ふべしその憤は暴あれば詛ふべし我彼らをヤコブの中に分ちイスラエルの中に散さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'ユダよ汝は兄弟の讚る者なり汝の手はなんぢの敵の頸を抑へんなんぢの父の子等なんぢの前に鞠ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'ユダは獅子の子の如しわが子よ汝は所掠物をさきてかへりのぼる彼は牡獅子のごとく伏し牝獅のごとく蹲まる誰か之をおこすことをせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, '杖ユダを離れず法を立る者その足の間をはなるることなくしてシロの來る時にまでおよばん彼に諸の民したがふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, '彼その驢馬を葡萄の樹に繋ぎその牝驢馬の子を葡萄の蔓に繋がん又その衣を酒にあらひ其服を葡萄の汁にあらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'その目は酒によりて紅くその齒は乳によりて白し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'ゼブルンは海邊にすみ舟の泊る海邊に住はんその界はシドンにおよぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'イッサカルは羊の牢の間に伏す健き驢馬の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, '彼みて安泰を善としその國を樂とし肩をさげて負ひ租税をいだして僕となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'ダンはイスラエルの他の支派の如く其民を鞫かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'ダンは路の旁の蛇のごとく途邊にある蝮のごとし馬の踵を噛てその騎者をして後に落しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'ヱホバよわれ汝の拯救を待り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'ガドは軍勢これにせまらんされど彼返てその後にせまらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'アセルよりいづる食物は美るべし彼王の食ふ美味をいださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'ナフタリは釋れたる麀のごとし彼美言をいだすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'ヨセフは實を結ぶ樹の芽のごとし即ち泉の傍にある實をむすぶ樹の芽のごとしその枝つひに垣を踰ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, '射者彼をなやまし彼を射かれを惡めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, '然どかれの弓はなほ勁くあり彼の手の臂は力あり是ヤコブの全能者の手によりてなり其よりイスラエルの磐なる牧者いづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, '汝の父の神による彼なんぢを助けん全能者による彼なんぢを祝まん上なる天の福、下によこたはる淵の福、乳哺の福、胎の福、汝にきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, '父の汝を祝することはわが父祖の祝したる所に勝て恒久の山の限極にまでおよばん是等の祝福はヨセフの首に歸しその兄弟と別になりたる者の頭頂に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'ベニヤミンは物を噛む狼なり朝にその所掠物を啖ひ夕にその所攫物をわかたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, '是等はイスラエルの十二の支派なり斯その父彼らに語り彼等を祝せりすなはちその祝すべき所にしたがひて彼等諸人を祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'ヤコブまた彼等に命じて之にいひけるは我はわが民にくははらんとすヘテ人エフロンの田にある洞穴にわが先祖等とともに我をはうむれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'その洞穴はカナンの地にてマムレのまへなるマクペラの田にあり是はアブラハムがヘテ人エフロンより田とともに購て所有の墓所となせし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'アブラハムとその妻サラ彼處にはうむられイサクとその妻リベカ彼處に葬られたり我またかしこにレアを葬れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, '彼田とその中の洞穴はヘテの子孫より購たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'ヤコブその子に命ずることを終し時足を床に斂めて氣たえてその民にくははる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'ヨセフ父の面に俯し之をいだきて哭き之に接吻す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, '而してヨセフその僕なる醫者に命じてその父に釁らしむ醫者イスラエルに釁れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'すなはち之がために四十日を用ふ其は尸に釁るにはこの日數を用ふべければなりエジプト人七十日の間之がために哭けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, '哀哭の日すぎし時ヨセフ、パロの家にかたりていひけるは我もし汝等の前に恩惠を得るならば請ふパロの耳にまうして言へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'わが父我死ばカナンの地にわが掘おきたる墓に我をはうむれといひて我を誓はしめたり然ば請ふわれをして上りて父を葬らしめたまへまた歸りきたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'パロいひけるは汝の父汝をちかはせしごとくのぼりて之を葬るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, '是に於てヨセフ父を葬らんとて上るパロの諸の臣パロの家の長老等エジプトの地の長老等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'およびヨセフの全家とその兄弟等およびその父の家之とともに上る只その子女と羊と牛はゴセンの地にのこせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'また車と騎兵ヨセフにしたがひてのぼり其隊ははなはだ大なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, '彼等つひにヨルダンの外なるアタデの禾場に到り彼にて大に泣き痛く哀しむヨセフすなはち七日父のために哭きぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'その國の居人なるカナン人等アタデの禾場の哀哭を見て是はエジプト人の痛くなげくなりといへり是によりて其處の名をアベルミツライム(エジプト人の哀哭)と稱ふヨルダンの外にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'ヤコブの子等その命ぜられたるごとく之になせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'すなはちヤコブの子等彼をカナンの地に舁ゆきて之をマクペラの田の洞穴にはうむれり是はアブラハムがヘテ人エフロンより田とともに購とりて所有の墓所となせし者にてマムレの前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'ヨセフ父を葬りてのち其兄弟および凡て己とともにのぼりて父をはうむれる者とともにエジプトにかへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'ヨセフの兄弟等その父の死たるを見ていひけるはヨセフあるいはわれらを恨むることあらん又かならずわれらが彼になしたる諸の惡にむくゆるならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'すなはちヨセフにいひおくりけるはなんぢの父死るまへに命じて言けらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '汝ら斯ヨセフにいふべし汝の兄弟汝に惡をなしたれども冀はくはその罪咎をゆるせと然ば請ふ汝の父の神の僕等の咎をゆるせとヨセフその言を聞て啼泣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, '兄弟等もまた自らきたりヨセフの面の前に俯し我儕は汝の僕とならんといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'ヨセフかれらに曰けるは懼るなかれ我あに神にかはらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, '汝等は我を害せんとおもひたれども神はそれを善にかはらせ今日のごとく多の民の生命を救ふにいたらしめんとおもひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, '故に汝らおそるるなかれ我なんぢらと汝らの子女をやしなはんと彼等をなぐさめ懇に之にかたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'ヨセフ父の家族とともにエジプトにすめりヨセフは百十歳いきながらへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'ヨセフ、エフライムの三世の子女をみるにいたれりマナセの子マキルの子女もうまれてヨセフの膝にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'ヨセフその兄弟等にいひけるは我死ん神かならず汝等を眷顧みなんぢらを此地よりいだしてそのアブラハム、イサク、ヤコブに誓ひし地にいたらしめたまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'ヨセフ神かならず汝等をかへりみたまはん汝らわが骨をここよりたづさへのぼるべしといひてイスラエルの子孫を誓はしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'ヨセフ百十歳にして死たれば之に釁りて櫃にをさめてエジプトにおけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'イスラエルの子等のエジプトに至りし者の名は左のごとし衆人各その家族をたづさへてヤコブとともに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'すなはちルベン、シメオン、レビ、ユダ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'イツサカル、ゼブルン、ベニヤミン、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'ダン、ナフタリ、ガド、アセルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'ヤコブの腰より出たる者は都合七十人ヨセフはすでにエジプトにありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'ヨセフとその諸の兄弟および當世の人みな死たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'イスラエルの子孫饒く子を生み彌増殖え甚だしく大に強くなりて國に滿るにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, '茲にヨセフの事をしらざる新き王エジプトに起りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, '彼その民にいひけるは視よ此民イスラエルの子孫われらよりも多く且強し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, '來れわれら機巧く彼等に事をなさん恐くは彼等多ならん又戰爭の起ることある時は彼等敵にくみして我等と戰ひ遂に國よりいでさらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'すなはち督者をかれらの上に立て彼らに重荷をおはせて之を苦む彼等パロのために府庫の邑ピトムとラメセスを建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, '然るにイスラエルの子孫は苦むるに隨ひて増し殖たれば皆これを懼れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'エジプト人イスラエルの子孫を嚴く動作かしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, '辛き力役をもて彼等をして苦みて生を度らしむ即ち和泥、作甎および田圃の諸の工にはたらかしめけるが其働かしめし工作は皆嚴かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'エジプトの王又ヘブルの產婆シフラと名くる者とブワと名くる者の二人に諭して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'いひけるは汝等ヘブルの婦女のために收生をなす時は床の上を見てその子若男子ならばこれを殺せ女子ならば生しおくべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, '然に產婆神を畏れエジプト王の命ぜしごとく爲ずして男子をも生しおけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'エジプト王產婆を召て之にいひけるは汝等なんぞ此事をなし男子を生しおくや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, '產婆パロに言けるはヘブルの婦はエジプトの婦のごとくならず彼等は健して產婆のかれらに至らぬ前に產をはるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, '是によりて神その產婆等に恩をほどこしたまへり是において民増ゆきて甚だ強くなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, '產婆神を畏れたるによりて神かれらのために家を成たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, '斯有しかばパロその凡の民に命じていふ男子の生るあらば汝等これを悉く河に投いれよ女子は皆生しおくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, '爰にレビの家の一箇の人往てレビの女を娶れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, '女妊みて男子を生みその美きを見て三月のあひだこれを匿せしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'すでにこれを匿すあたはざるにいたりければ萑の箱舟を之がために取て之に瀝靑と樹脂を塗り子をその中に納てこれを河邊の葦の中に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'その姉遥に立てその如何になるかを窺ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, '茲にパロの女身を洗んとて河にくだりその婢等河の傍にあゆむ彼葦の中に箱舟あるを見て使女をつかはしてこれを取きたらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'これを啓きてその子のをるを見る嬰兒すなはち啼く彼これを憐みていひけるは是はヘブル人の子なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, '時にその姉パロの女にいひけるは我ゆきてヘブルの女の中より此子をなんぢのために養ふべき乳母を呼きたらんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'パロの女往よと之にいひければ女子すなはち往てその子の母を呼きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'パロの女かれにいひけるは此子をつれゆきて我ために之を養へ我その値をなんぢにとらせんと婦すなはちその子を取てこれを養ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, '斯てその子の長ずるにおよびて之をパロの女の所にたづさへゆきければすなはちこれが子となる彼その名をモーセ(援出)と名けて言ふ我これを水より援いだせしに因ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, '茲にモーセ生長におよびて一時いでてその兄弟等の所にいたりその重荷を負ふを見しが會一箇のエジプト人が一箇のイスラエル人即ちおのれの兄弟を撃つを見たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, '右左を視まはして人のをらざるを見てそのエジプト人を撃ころし之を沙の中に埋め匿せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, '次の日また出て二人のヘブル人の相爭ふを見たればその曲き者にむかひ汝なんぞ汝の隣人を撃つやといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, '彼いひけるは誰が汝を立てわれらの君とし判官としたるや汝かのエジプト人をころせしごとく我をも殺さんとするやと是においてモーセ懼れてその事かならず知れたるならんとおもへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'パロ此事を聞てモーセを殺さんともとめければモーセすなはちパロの面をさけて逃げのびミデアンの地に住り彼井の傍に坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'ミデアンの祭司に七人の女子ありしが彼等來りて水を汲み水鉢に盈て父の羊群に飮はんとしけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, '牧羊者等きたりて彼らを逐はらひければモーセ起あがりて彼等をたすけその羊群に飮ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, '彼等その父リウエルに至れる時父言けるは今日はなんぢら何ぞかく速にかへりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'かれらいひけるは一箇のエジプト人我らを牧羊者等の手より救いだし亦われらのために水を多く汲て羊群に飮しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, '父女等にいひけるは彼は何處にをるや汝等なんぞその人を遺てきたりしや彼をよびて物を食しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'モーセこの人とともに居ることを好めり彼すなはちその女子チツポラをモーセに與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, '彼男子を生みければモーセその名をゲルシヨム(客)と名けて言ふ我異邦に客となりをればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, '斯て時をふる程にジプトの王死りイスラエルの子孫その勞役の故によりて歎き號ぶにその勞役の故によりて號ぶところの聲神に達りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, '神その長呻を聞き神そのアブラハム、イサク、ヤコブになしたる契約を憶え');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, '神イスラエルの子孫を眷み神知しめしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'モーセその妻の父なるミデアンの祭司ヱテロの群を牧ひをりしがその群を曠野の奧にみちびきて神の山ホレブに至るに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'ヱホバの使者棘の裏の火燄の中にて彼にあらはる彼見るに棘火に燃れどもその棘燬ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'モーセいひけるは我ゆきてこの大なる觀を見 何故に棘の燃たえざるかを見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'ヱホバ彼がきたり觀んとするを見たまふ即ち神棘の中よりモーセよモーセよと彼をよびたまひければ我ここにありといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, '神いひたまひけるは此に近よるなかれ汝の足より履を脱ぐべし汝が立つ處は聖き地なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, '又いひたまひけるは我はなんぢの父の神アブラハムの神イサクの神ヤコブの神なりとモーセ神を見ることを畏れてその面を蔽せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'ヱホバ言たまひけるは我まことにエジプトにをるわが民の苦患を觀また彼等がその驅使者の故をもて號ぶところの聲を聞り我かれらの憂苦を知るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'われ降りてかれらをエジプト人の手より救ひいだし之を彼地より導きのぼりて善き廣き地乳と蜜との流るる地すなはちカナン人ヘテ人アモリ人ベリジ人ヒビ人ヱブス人のをる處に至らしめんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, '今イスラエルの子孫の號呼われに達る我またエジプト人が彼らを苦むるその暴虐を見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, '然ば來れ我なんぢをパロにつかはし汝をしてわが民イスラエルの子孫をエジプトより導きいださしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'モーセ神にいひけるは我は如何なる者ぞや我豈パロの許に往きイスラエルの子孫をエジプトより導きいだすべき者ならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, '神いひたまひけるは我かならず汝とともにあるべし是はわが汝をつかはせる證據なり汝民をエジプトより導きいだしたる時汝等この山にて神に事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'モーセ神にいひけるは我イスラエルの子孫の所にゆきて汝らの先祖等の神我を汝らに遣はしたまふと言んに彼等もし其名は何と我に言ば何とかれらに言べきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, '神モーセにいひたまひけるは我は有て在る者なり又いひたまひけるは汝かくイスラエルの子孫にいふべし我有といふ者我を汝らに遣したまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, '神またモーセにいひたまひけるは汝かくイスラエルの子孫にいふべし汝らの先祖等の神アブラハムの神イサクの神ヤコブの神ヱホバわれを汝らにつかはしたまふと是は永遠にわが名となり世々にわが誌となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, '汝往てイスラエルの長老等をあつめて之にいふべし汝らの先祖等の神アブラハム、イサク、ヤコブの神ヱホバ我にあらはれて言たまひけらく我誠になんぢらを眷み汝らがエジプトにて蒙るところの事を見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, '我すなはち言り我汝らをエジプトの苦患の中より導き出してカナン人ヘテ人アモリ人ペリジ人ヒビ人エブス人の地すなはち乳と蜜の流るる地にのぼり至らしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, '彼等なんぢの言に聽したがふべし汝とイスラエルの長老等エジプトの王の許にいたりて之に言へヘブル人の神ヱホバ我らに臨めり然ば請ふわれらをして三日程ほど曠野に入しめわれらの神ヱホバに犠牲をささぐることを得せしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, '我しるエジプトの王は假令能力ある手をくはふるも汝等の往をゆるさざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, '我すなはちわが手を舒ベエジプトの中に諸の奇跡を行ひてエジプトを撃ん其後かれ汝等を去しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, '我エジプト人をして此民をめぐましめん汝ら去る時手を空うして去るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, '婦女皆その隣人とおのれの家に寓る者とに金の飾品銀の飾品および衣服を乞べし而して汝らこれを汝らの子女に穿戴せよ汝等かくエジプト人の物を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'モーセ對へていひけるは然ながら彼等我を信ぜず又わが言に聽したがはずして言んヱホバ汝にあらはれたまはずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'ヱホバかれにいひたまひけるは汝の手にある者は何なるや彼いふ杖なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'ヱホバいひたまひけるは其を地に擲よとすなはち之を地になぐるに蛇となりければモーセその前を避たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'ヱホバ、モーセにいひたまひけるは汝の手をのべて其尾を執れとすなはち手をのべて之を執ば手にいりて杖となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'ヱホバいひたまふ是は彼らの先祖等の神アブラハムの神イサクの神ヤコブの神ヱホバの汝にあらはれたることを彼らに信ぜしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'ヱホバまたかれに言たまひけるは汝の手を懐に納よとすなはち手を懐にいれて之を出し見るにその手癩病を生じて雪のごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'ヱホバまた言たまひけるは汝の手をふたたび懐にいれよと彼すなはちふたたび其手を懐にいれて之を懐より出し見るに變りて他處の肌膚のごとくになる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'ヱホバいひたまふ彼等もし汝を信ぜずまたその最初の徴の聲に聽從はざるならば後の徴の聲を信ぜん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, '彼らもし是ふたつの徴をも信ぜすして汝の言に聽從はざるならば汝河の水をとりて之を陸地にそそげ汝が河より取たる水陸地にて血となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'モーセ、ヱホバにいひけるはわが主よ我は素言辭に敏き人にあらず汝が僕に語りたまへるに及びても猶しかり我は口重く舌重き者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'ヱホバかれにいひたまひけるは人の口を造る者は誰なるや唖者聾者目明者瞽者などを造る者は誰なるや我ヱホバなるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, '然ば往けよ我なんぢの口にありて汝の言ふべきことを敎へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'モーセいひけるはわが主よ願くは遣すべき者をつかはしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, '是においてヱホバ、モーセにむかひ怒を發していひたまひけるはレビ人アロンは汝の兄弟なるにあらずや我かれが言を善するを知るまた彼なんぢに遇んとていで來る彼汝を見る時心に喜ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, '汝かれに語りて言をその口に授くべし我なんぢの口と彼の口にありて汝らの爲べき事を敎へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, '彼なんぢに代て民に語らん彼は汝の口に代らん汝は彼のために神に代るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'なんぢこの杖を手に執り之をもて奇蹟をおこなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, '是においてモーセゆきてその妻の父ヱテロの許にかへりて之にいふ請ふ我をして往てわがエジプトにある兄弟等の所にかへらしめ彼等のなほ生ながらへをるや否を見さしめよヱテロ、モーセに安然に往くべしといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, '爰にヱホバ、ミデアンにてモーセにいひたまひけるは往てエジプトにかへれ汝の生命をもとめし人は皆死たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'モーセすなはちその妻と子等をとり之を驢馬に乗てエジプトの地にかへるモーセは神の杖を手に執り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'ヱホバ、モーセにいひたまひけるは汝エジプトにかへりゆける時はかならず我がなんぢの手に授けたるところの奇跡を悉くパロのまへにおこなふべし但し我かれの心を剛愎にすれば彼民を去しめざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, '汝パロに言べしヱホバかく言ふイスラエルはわが子わが冢子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, '我なんぢにいふ我が子を去らしめて我に事ふることをえせしめよ汝もし彼をさらしむることを拒ば我なんぢの子なんぢの冢子を殺すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'モーセ途にある時ヱホバかれの宿所にて彼に遇てころさんとしたまひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'チツポラ利き石をとりてその男子の陽の皮を割りモーセの足下になげうちて言ふ汝はまことにわがためには血の夫なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, '是においてヱホバ、モーセをゆるしたまふ此時チツポラが血の夫といひしは割禮の故によりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, '爰にヱホバ、アロンにいひたまひけるに曠野にゆきてモーセを迎へよと彼すなはちゆきて神の山にてモーセに遇ひ之に接吻す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'モーセ、ヱホバがおのれに言ふくめて遣したまへる諸の言とヱホバのおのれに命じたまひし諸の奇跡とをアロンにつげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, '斯てモーセとアロン往てイスラエルの子孫の長老を盡く集む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, '而してアロン、ヱホバのモーセにかたりたまひし言を盡くつぐ又彼民の目のまへにて奇蹟をなしければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, '民すなはち信ず彼等ヱホバがイスラエルの民をかへりみその苦患をおもひたまふを聞て身をかがめて拝をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'その後モーセとアロン入てパロにいふイスラエルの神ヱホバ斯いひたまふ我民を去しめ彼等をして曠野に於て我を祭ることをえせしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'パロいひけるはヱホバは誰なればか我その聲にしたがひてイスラエルを去しむべき我ヱホバを識ず亦イスラエルを去しめじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, '彼ら言けるはヘブル人の神我らに顯れたまへり請ふ我等をして三日程ほど曠野にいりてわれらの神ヱホバに犠牲をささぐることをえせしめよ恐くはヱホバ疫病か又は刀兵をもて我らをなやましたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'エジプト王かれらに言けるは汝等モーセ、アロンなんぞ民の操作を妨ぐるや往てなんぢらの荷を負へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'パロまたいふ土民今は多かり然るに汝等かれらをして荷をおふことを止しめんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'パロ此日民が驅使ふ者等および民の有司等に命じていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '汝等再び前のごとく民に磚瓦を造る禾稈を與ふべからず彼等をして往てみづから禾稈をあつめしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'また彼等が前に造りし磚瓦の數のごとくに仍かれらに之をつくらしめよ其を減すなかれ彼等は懈惰が故に我儕をして往てわれらの神に犠牲をささげしめよと呼はり言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, '人々の工作を重くして之に勞かしめよ然ば偽の言を聽ことあらじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, '民を驅使ふ者等およびその有司等出ゆきて民にいひけるはパロかく言たまふ我なんぢらに禾稈をあたへじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, '汝等往て禾稈のある處にて之をとれ但しなんぢらの工作は分毫も減さざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, '是において民遍くエジプトの地に散て草藁をあつめて禾稈となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, '驅使者かれらを促たてて言ふ禾稈のありし時のごとく汝らの工作汝らの日々の業をなしをふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'パロの驅使者等がイスラエルの子孫の上に立たるところの有司等撻れなんぢら何ぞ昨日も今日も磚瓦を作るところの汝らの業を前のごとくに爲しをへざるやと言る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, '是に於てイスラエルの子孫の有司等來りてパロに呼はりて言ふ汝なんぞ斯僕等になすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, '僕等に禾稈を與へずしてわれらに磚瓦を作れといふ視よ僕等は撻る是なんぢの民の過なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, '然るにパロいふ汝等は懶惰し懶惰し故に汝らは我らをして往てヱホバに犠牲をささげしめよと言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, '然ば汝ら往て操作けよ禾稈はなんぢらに與ふることなかるべけれどなんぢら尚數のごとくに磚瓦を交納むべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'イスラエルの子孫の有司等汝等その日々につくる磚瓦を減すべからずと言るを聞て災害の身におよぶを知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, '彼らパロをはなれて出たる時モーセとアロンの對面にたてるを見たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, '之にいひけるは願くはヱホバ汝等を鑒みて鞫きたまへ汝等はわれらの臭をパロの目と彼の僕の目に忌嫌はれしめ刀を彼等の手にわたして我等を殺さしめんとするなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'モーセ、ヱホバに返りて言ふわが主よ何て此民をあしくしたまふや何のために我をつかはしたまひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'わがパロの許に來りて汝の名をもて語りしよりして彼この民をあしくす汝また絶てなんぢの民をすくひたまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'ヱホバ、モーセに言たまひけるは今汝わがパロに爲んところの事を見るべし能ある手の加はるによりてパロ彼らをさらしめん能ある手の加はるによりてパロ彼らを其國より逐いだすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, '神モーセに語りて之にいひたまひけるは我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, '我全能の神といひてアブラハム、イサク、ヤコブに顯れたり然ど我名のヱホバの事は彼等しらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, '我また彼らとわが契約を立て彼等が旅して寄居たる國カナンの地をかれらに與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, '我またエジプト人が奴隸となせるイスラエルの子孫の呻吟た聞き且我が契約を憶ひ出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, '故にイスラエルの子孫に言へ我はヱホバなり我汝らをエジプト人の重負の下より携出し其使役をまぬかれしめ又腕をのべ大なる罰をほどこして汝等を贖はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, '我汝等を取て吾民となし汝等の神となるべし汝等はわがエジプト人の重擔の下より汝らを携出したるなんぢらの神ヱホバなることを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, '我わが手をあげてアブラハム、イサク、ヤコブに與へんと誓ひし地に汝等を導きいたり之を汝等に與へて產業となさしめん我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'モーセかくイスラエルの子孫に語けれども彼等は心の傷ると役事の苦きとの爲にモーセに聽ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'ヱホバ、モーセに告ていひたまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '入てエジプトの王パロに語りイスラエルの子孫をその國より去しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'モーセ、ヱホバの前に申していふイスラエルの子孫旣に我に聽ず我は口に割禮をうけざる者なればパロいかで我にきかんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'ヱホバ、モーセとアロンに語り彼等に命じてイスラエルの子孫とエジプトの王パロの所に往しめイスラエルの子孫をエジプトの地より導きいださしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'かれらの父の家々の長は左のごとしイスラエルの冢子ルベンの子ヘノク、バル、ヘヅロン、カルミ是等はルベンの家族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'シメオンの子ヱムエル、ヤミン、オハデ、ヤキン、ゾハルおよびカナンの女の生しシヤウル是らはシメオンの家族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'レビの子の名はその世代にしたがひて言ば左のごとしゲルシヨン、コハテ、メラリ是なりレビの齢の年は百三十七年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'ゲルシヨンの子はその家族にしたがひて言ばリブニおよびシメイなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'コハテの子はアムラム、イヅハル、ヘブロン、ウジエルなりコハテの齢の年は百三十三年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'メラリの子はマヘリおよびムシなり是等はレビの家族にしてその世代にしたがひて言るものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'アムラム其伯母ヨケベデを妻にめとれり彼アロンとモーセを生むアムラムの齢の年は百三十七年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'イヅハルの子はコラ、ネベグ、ジクリなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'ウジエルの子はミサエル、エルザバン、シテリなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'アロン、ナシヨンの姉アミナダブの女エリセバを妻にめとれり彼ナダブ、アビウ、エレアザル、イタマルを生む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'コラの子はアツシル、エルカナ、アビアサフ是等はコラ人の族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'アロンの子エレアザル、ブテエルの女の中より妻をめとれり彼ピネハスを生む是等はレビ人の父の家々の長にしてその家族に循ひて言る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'ヱホバがイスラエルの子孫を其軍隊にしたがひてエジプトの地より導きいだせよといひたまひしは此アロンとモーセなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, '彼等はイスラエルの子孫をエジプトより導きいださんとしてエジプトの王パロに語りし者にして即ち此モーセとアロンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'ヱホバ、エジプトの地にてモーセに語りたまへる日に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'ヱホバ、モーセに語りて言たまひけるは我はヱホバなり汝わが汝にいふ所を悉皆くエジプトの王パロに語るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'モーセ、ヱホバの前に言けるは我は口に割禮を受ざる者なればパロいかで我に聽んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'ヱホバ、モーセに言たまひけるは視よ我汝をしてパロにおけること神のごとくならしむ汝の兄弟アロンは汝の預言者となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, '汝はわが汝に命ずる所を盡く宣べし汝の兄弟アロンはパロに告ることを爲べし彼イスラエルの子孫をその國より出すに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, '我パロの心を剛愎にして吾徴と奇跡をエジプトの國に多くせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, '然どパロ汝に聽ざるべし我すなはち吾手をエジプトに加へ大なる罰をほどこして吾軍隊わが民イスラエルの子孫をエジプトの國より出さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, '我わが手をエジプトの上に伸てイスラエルの子孫をエジプト人の中より出す時には彼等我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'モーセとアロン斯おこなひヱホバの命じたまへる如くに然なしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'そのパロと談論ける時モーセは八十歳アロンは八十三歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'ヱホバ、モーセとアロンに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'パロ汝等に語りて汝ら自ら奇蹟を行へと言時には汝アロンに言べし汝の杖をとりてパロの前に擲てよと其は蛇とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, '是に於てモーセとアロンはパロの許にいたりヱホバの命じたまひしごとくに行へり即ちアロンその杖をパロとその臣下の前に擲しに蛇となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, '斯在しかばパロもまた博士と魔術士を召よせたるにエジプトの法術士等もその秘術をもてかくおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, '即ち彼ら各人その杖を投たれば蛇となりけるがアロンの杖かれらの杖を呑つくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, '然るにパロの心剛愎になりて彼らに聽ことをせざりきヱホバの言たまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'ヱホバ、モーセに言たまひけるはパロは心頑にして民を去しむることを拒むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, '朝におよびて汝パロの許にいたれ視よ彼は水に臨む汝河の邊にたちて彼を逆ふべし汝かの蛇に化し杖を手にとりて居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, '彼に言ふべしヘブル人の神ヱホバ我を汝につかはして言しむ吾民を去しめて曠野にて我に事ふることを得せしめよ視よ今まで汝は聽入ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'ヱホバかく言ふ汝これによりて我がヱホバなるを知ん視よ我わが手の杖をもて河の水を撃ん是血に變ずべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, '而して河の魚は死に河は臭くならんエジプト人は河の水を飮ことを厭ふにいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'ヱホバまたモーセに言たまはく汝アロンに言へ汝の杖をとりて汝の手をエジプトの上に伸べ流水の上河々の上池塘の上一切の湖水の上に伸て血とならしめよエジプト全國に於て木石の器の中に凡て血あるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'モーセ、アロンすなはちヱホバの命じたまへるごとくに爲り即ち彼パロとその臣下の前にて杖をあげて河の水を撃しに河の水みな血に變じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, '是において河の魚死て河臭くなりエジプト人河の水を飮ことを得ざりき斯エジプト全國に血ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'エジプトの法術士等もその秘術をもて斯のごとく行へりパロは心頑固にして彼等に聽ことをせざりきヱホバの言たまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'パロすなはち身をめぐらしてその家に入り此事にも心をとめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'エジプト人河の水を飮ことを得ざりしかば皆飮水を得んとて河のまはりを掘たりヱホバ河を撃たまひてより後七日たちぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, '');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'ヱホバ、モーセに言たまひけるは汝パロに詣りて彼に言へヱホバかく言たまふ吾民を去しめて我に事ふることを得せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, '汝もし去しむることを拒まば我蛙をもて汝の四方の境を惱さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, '河に蛙むらがり上りきたりて汝の家にいり汝の寝室にいり汝の牀にのぼり汝の臣下の家にいり汝の民の所にいたり汝の竃におよび汝の搓鉢にいらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, '蛙なんぢの身にのぼり汝の民と汝の臣下の上にのぼるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'ヱホバ、モーセに言たまはく汝アロンに言へ汝杖をとりて手を流水の上に伸べ河々の上と池塘の上に伸て蛙をエジプトの地に上らしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'アロン手をエジプトの水のうへに伸たれば蛙のぼりきたりてエジプトの地を蔽ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, '法術士等もその秘術をもて斯おこなひ蛙をエジプトの地に上らしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'パロ、モーセとアロンを召て言けるはヱホバに願ひてこの蛙を我とわが民の所より取さらしめよ我この民を去しめてヱホバに犠牲をささぐることを得せしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'モーセ、パロに言けるは我なんぢと汝の臣下と汝の民のために願ひて何時此蛙を汝と汝の家より絶さりて河にのみ止らしむべきや我に示せと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, '彼明日といひければモーセ言ふ汝の言のごとくに爲し汝をして我らの神ヱホバのごとき者なきことを知しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, '蛙汝と汝の家を離れ汝の臣下と汝の民を離れて河にのみ止るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'モーセとアロンすなはちパロを離れて出でモーセそのパロに至らしめたまひし蛙のためにヱホバに呼はりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'ヱホバ、モーセの言のごとくなしたまひて蛙家より村より田野より死亡たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, '茲にこれを攢むるに山をなし地臭くなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, '然るにパロは嘘氣時あるを見てその心を頑固にして彼等に聽ことをせざりきヱホバの言たまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'ヱホバ、モーセに言たまひけるは汝アロンに言へ汝の杖を伸べ地の塵を打てエジプト全國に蚤とならしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, '彼等斯なせり即ちアロン杖をとりて手を伸べ地の塵を撃けるに蚤となりて人と畜につけりエジプト全國において地の塵みな蚤となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, '法術士等その秘術をもて斯おこなひて蚤を出さんとしたりしが能はざりき蚤は人と畜に著く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, '是において法術士等パロに言ふ是は神の指なりと然るにパロは心剛愎にして彼等に聽ざりきヱホバの言たまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'ヱホバ、モーセに言たまはく汝朝早く起てパロの前に立て視よ彼は水に臨む汝彼に言へヱホバかく言たまふわが民を去しめて我に事ふることを得せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, '汝もしわが民を去しめずば視よ我汝と汝の臣下と汝の民と汝の家とに蚋をおくらんエジプト人の家々には蚋充べし彼らの居るところの地も然らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'その日に我わが民の居るゴセンの地を區別おきて其處に蚋あらしめじ是地の中にありて我のヱホバなることを汝が知んためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, '我わが民と汝の民の間に區別をたてん明日この徴あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'ヱホバかく爲たまひたれば蚋おびただしく出來りてパロの家にいりその臣下の家にいりエジプト全國にたり蚋のために地害はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, '是においてパロ、モーセとアロンを召ていひけるは汝等往て國の中にて汝らの神に犠牲を献げよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'モーセ言ふ然するは宜からず我等はエジプト人の崇拝む者を犠牲としてわれらの神ヱホバに献ぐべければなり我等もしエジプト人の崇拝む者をその目の前にて犠牲に献げなば彼等石にて我等を撃ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, '我等は三日路ほど曠野にいりて我らの神ヱホバに犠牲を献げその命じたまひしごとくせんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'パロ言けるは我汝らを去しめて汝らの神ヱホバに曠野にて犠牲を献ぐることを得せしめん但餘に遠くは行べからず我ために祈れよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'モーセ言けるは視よ我汝をはなれて出づ我ヱホバに祈ん明日蚋パロとその臣下とその民を離れん第パロ再び偽をおこなひ民を去しめてヱホバに犠牲をささぐるを得せしめざるが如きことを爲ざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'かくてモーセ、パロをはなれて出でヱホバに祈りたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'ヱホバ、モーセの言のごとく爲したまへり即ちその蚋をパロとその臣下とその民よりはなれしめたまふ一ものこらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, '然るにパロ此時にもまたその心を頑固にして民を去しめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, '爰にヱホバ、モーセにいひたまひけるはパロの所にいりてかれに告よヘブル人の神ヱホバ斯いひたまふ吾民を去しめて我につかふることをえせしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, '汝もし彼等をさらしむることを拒みて尚かれらを拘留へなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'ヱホバの手野にをる汝の家畜馬驢馬駱駝牛および羊に加はらん即ち甚だ惡き疾あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'ヱホバ、イスラエルの家畜とエジプトの家畜とを別ちたまはんイスラエルの子孫に屬する者は死る者あらざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'ヱホバまた期をさだめて言たまふ明日ヱホバこの事を國になさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, '明日ヱホバこの事をなしたまひければエジプトの家畜みな死り然どイスラエルの子孫の家畜は一も死ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'パロ人をつかはして見さしめたるにイスラエルの家畜は一頭だにも死ざりき然どもパロは心剛愎にして民をさらしめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'またヱホバ、モーセとアロンにいひたまひけるは汝等竃爐の灰を一握とれ而してモーセ、パロの目の前にて天にむかひて之をまきちらすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, '其灰エジプト全國に塵となりてエジプト全國の人と畜獣につき膿をもちて脹るる腫物とならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, '彼等すなはち竃爐の灰をとりてパロの前に立ちモーセ天にむかひて之をまきちらしければ人と獣畜につき膿をもちて脹るる腫物となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, '法術士等はその腫物のためにモーセの前に立つことを得ざりき腫物は法術士等よりして諸のエジプト人にまで生じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, '然どヱホバ、パロの心を剛愎にしたまひたれば彼らに聽ざりきヱホバのモーセに言給ひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, '爰にヱホバ、モーセにいひたまひけるは朝早くおきてパロの前にたちて彼に言へヘブル人の神ヱホバ斯いひたまふ吾民を去しめて我に事ふるをえせしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, '我此度わが諸の災害を汝の心となんぢの臣下およびなんぢの民に降し全地に我ごとき者なきことを汝に知しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, '我もしわが手を伸べ疫病をもて汝となんぢの民を撃たらば汝は地より絶れしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, '抑わが汝をたてたるは即ちなんぢをしてわが權能を見さしめわが名を全地に傳へんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, '汝なほ吾民の前に立ふさがりて之を去しめざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, '視よ明日の今頃我はなはだ大なる雹を降すべし是はエジプトの開國より今までに嘗てあらざりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, '然ば人をやりて汝の家畜および凡て汝が野に有る物を集めよ人も獣畜も凡て野にありて家に歸らざる者は雹その上にふりくだりて死るにたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'パロの臣下の中ヱホバの言を畏る者はその僕と家畜を家に逃いらしめしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'ヱホバの言を意にとめざる者はその僕と家畜を野に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'ヱホバ、モーセにいひたまひけるは汝の手を天に舒てエジプト全國に雹あらしめエジプトの國中の人と獣畜と田圃の諸の蔬にふりくだらしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'モーセ天にむかひて杖を舒たればヱホバ雷と雹を遣りたまふ又火いでて地に馳すヱホバ雹をエジプトの地に降せたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, '斯雹ふり又火の塊雹に雑りて降る甚だ勵しエジプト全國には其國を成てよりこのかた未だ斯る者あらざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, '雹エジプト全國に於て人と獣畜とをいはず凡て田圃にをる者を撃り雹また田圃の諸の蔬を撃ち野の諸の樹を折り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, '唯イスラエルの子孫のをるゴセンの地には雹あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, '是に於てパロ人をつかはしてモーセとアロンを召てこれに言けるは我此度罪ををかしたりヱホバは義く我とわが民は惡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'ヱホバに願ひてこの神鳴と雹を最早これにて足しめよ我なんぢらを去しめん汝等今は留るにおよばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'モーセかれに曰けるは我邑より出て我手をヱホバに舒ひろげん然ば雷やみて雹かさねてあらざるべし斯して地はヱホバの所屬なるを汝にしらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, '然ど我しる汝となんぢの臣下等はなほヱホバ神を畏れざるならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, '偖麻と大麥は撃れたり大麥は穂いで麻は花さきゐたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, '然ど小麥と裸麥は未だ長ざりしによりて撃れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'モーセ、パロをはなれて邑より出でヱホバにむかひて手をのべひろげたれば雷と雹やみて雨地にふらずなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, '然るにパロ雨と雹と雷鳴のやみたるを見て復も罪を犯し其心を剛硬にす彼もその臣下も然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, '即ちパロは心剛愎にしてイスラエルの子孫を去しめざりきヱホバのモーセによりて言たまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, '爰にヱホバ、モーセにいひたまひけるはパロの所に入れ我かれの心とその臣下の心を剛硬にせり是はわが此等の徴を彼等の中に示さんため');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, '又なんぢをして吾がエジプトにて行ひし事等すなはち吾がエジプトの中にてなしたる徴をなんぢの子となんぢの子の子の耳に語らしめんためなり斯して汝等わがヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'モーセとアロン、パロの所にいりて彼にいひけるはヘブル人の神ヱホバかく言たまふ何時まで汝は我に降ることを拒むや我民をさらしめて我に事ふることをえせしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, '汝もしわが民を去しむることを拒まば明日我蝗をなんぢの境に入しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, '蝗地の面を蔽て人地を見るあたはざるべし蝗かの免かれてなんぢに遺れる者すなはち雹に打のこされたる者を食ひ野に汝らのために生る諸の樹をくらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, '又なんぢの家となんぢの臣下の家々および凡のエジプト人の家に滿べし是はなんぢの父となんぢの父の父が世にいでしより今日にいたるまで未だ嘗て見ざるものなりと斯て彼身をめぐらしてパロの所よりいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, '時にパロの臣下パロにいひけるは何時まで此人われらの羂となるや人々を去しめてその神ヱホバに事ふることをえせしめよ汝なほエジプトの滅ぶるを知ざるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, '是をもてモーセとアロンふたたび召れてパロの許にいたるにパロかれらにいふ往てなんぢらの神ヱホバに事よ但し往く者は誰と誰なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'モーセいひけるは我等は幼者をも老者をも子息をも息女をも挈へて往き羊をも牛をもたづさへて往くべし其は我らヱホバの祭禮をなさんとすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'パロかれらにいひけるは我汝等となんぢらの子等を去しむる時はヱホバなんぢらと偕に在れ愼めよ惡き事なんぢらの面のまへにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'そは宜からず汝ら男子のみ往てヱホバに事よ是なんぢらが求むるところなりと彼等つひにパロの前より逐いださる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, '爰にヱホバ、モーセにいひたまひけるは汝の手をエジプトの地のうへに舒て蝗をエジプトの國にのぞませて彼の雹が打殘したる地の諸の蔬を悉く食しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'モーセすなはちエジプトの地の上に其杖をのべければヱホバ東風をおこしてその一日一夜地にふかしめたまひしが東風朝におよびて蝗を吹きたりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, '蝗エジプト全國にのぞみエジプトの四方の境に居て害をなすこと太甚し是より先には斯のごとき蝗なかりし是より後にもあらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, '蝗全國の上を蔽ひければ國暗くなりぬ而して蝗地の諸の蔬および雹の打殘せし樹の菓を食ひたればエジプト全國に於て樹にも田圃の蔬にも靑き者とてはのこらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, '是をもてパロ急ぎモーセとアロンを召て言ふ 我なんちらの神ヱホバと汝等とにむかひて罪ををかせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, '然ば請ふ今一次のみ吾罪を宥してなんぢらの神ヱホバに願ひ唯此死を我より取はなさしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, '彼すなはちパロの所より出てヱホバにねがひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'ヱホバはなはだ強き西風を吹めぐらせて蝗を吹はらはしめ之を紅海に驅いれたまひてエジプトの四方の境に蝗ひとつも遺らざるにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, '然れどもヱホバ、パロの心を剛愎にしたまひたればイスラエルの子孫をさらしめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'ヱホバまたモーセにいひたまひけるは天にむかひて汝の手を舒べエジプトの國に黑暗を起すべし其暗黑は摸るべきなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'モーセすなはち天にむかひて手を舒ければ稠密黑暗三日のあひだエジプト全國にありて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, '三日の間は人々たがひに相見るあたはず又おのれの處より起ものなかりき然どイスラエルの子孫の居處には皆光ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, '是に於てパロ、モーセを呼ていひけるは汝等ゆきてヱホバに事よ唯なんぢらの羊と牛を留めおくべし汝らの子女も亦なんぢらとともに往べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'モーセいひけるは汝また我等の神ヱホバに献ぐべき犠牲と燔祭の物をも我儕に與ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'われらの家畜もわれらとともに往べし一蹄も後にのこすべからず其は我等その中を取てわれらの神ヱホバに事べきが故なりまたわれら彼處にいたるまでは何をもてヱホバに事ふべきかを知ざればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, '然れどもヱホバ、パロの心を剛愎にしたまひたればパロかれらをさらしむることを肯ぜざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'すなはちパロ、モーセに言ふ我をはなれて去よ自ら愼め重てわが面を見るなかれ汝わが面を見る日には死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'モーセいひけるは汝の言ふところは善し我重て復なんぢの面を見ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'ヱホバ、モーセにいひたまひけるは我今一箇の災をパロおよびエジプトに降さん然後かれ汝等を此處より去しむべし彼なんぢらを全く去しむるには必ず汝らを此より逐はらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, '然ば汝民の耳にかたり男女をしておのおのその隣々に銀の飾品金の飾具を乞しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'ヱホバつひに民をしてエジプト人の恩を蒙らしめたまふ又その人モーセはエジプトの國にてパロの臣下の目と民の目に甚だ大なる者と見えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'モーセいひけるはヱホバかく言たまふ夜半頃われ出てエジプトの中に至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'エジプトの國の中の長子たる者は位に坐するパロの長子より磨の後にをる婢の長子まで悉く死べし又獣畜の首出もしかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, '而してエジプト全國に大なる號哭あるべし是まで是のごとき事はあらずまた再び斯ること有ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, '然どイスラエルの子孫にむかひては犬もその舌をうごかさじ人にむかひても獣畜にむかひても然り汝等これによりてヱホバがエジプト人とイスラエルのあひだに區別をなしたまふを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, '汝の此臣等みなわが許に下り來てわれを拝し汝となんぢに從がふ民みな出よと言ん然る後われ出べしと烈しく怒りてパロの所より出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'ヱホバ、モーセにいひたまひけるはパロ汝に聽ざるべし是をもて吾がエジプトの國に奇蹟をおこなふこと増べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'モーセとアロンこの諸の奇蹟をことごとくパロの前に行ひたれどもヱホバ、パロの心を剛愎にしたまひければ彼イスラエルの子孫をその國より去しめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'ヱホバ、エジプトの國にてモーセとアロンに告ていひたまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '此月を汝らの月の首となせ汝ら是を年の正月となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, '汝等イスラエルの全會衆に告て言べし此月の十日に家の父たる者おのおの羔羊を取べし即ち家ごとに一箇の羔羊を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'もし家族少くして其羔羊を盡すことあたはずばその家の隣なる人とともに人の數にしたがひて之を取べし各人の食ふ所にしたがひて汝等羔羊を計るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, '汝らの羔羊は疵なき當歳の牡なるべし汝等綿羊あるひは山羊の中よりこれを取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, '而して此月の十四日まで之を守りおきイスラエルの會衆みな薄暮に之を屠り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'その血をとりて其之を食ふ家の門口の兩旁の橒と鴨居に塗べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, '而して此夜その肉を火に炙て食ひ又酵いれぬパンに苦菜をそへて食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, '其を生にても水に煮ても食ふなかれ火に炙べし其頭と脛と臓腑とを皆くらへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, '其を明朝まで殘しおくなかれ其明朝まで殘れる者は火にて燒つくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'なんぢら斯之を食ふべし即ち腰をひきからげ足に鞋を穿き手に杖をとりて急て之を食ふべし是ヱホバの逾越節なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, '是夜われエジプトの國を巡りて人と畜とを論ずエジプトの國の中の長子たる者を盡く撃殺し又エジプトの諸の神に罰をかうむらせん我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'その血なんぢらが居るところの家にありて汝等のために記號とならん我血を見る時なんぢらを逾越すべし又わがエジプトの國を撃つ時災なんぢらに降りて滅ぼすことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, '汝ら是日を記念えてヱホバの節期となし世々これを祝ふべし汝等之を常例となして祝ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, '七日の間酵いれぬパンを食ふべしその首の日にパン酵を汝等の家より除け凡て首の日より七日までに酵入たるパンを食ふ人はイスラエルより絶るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, '且首の日に聖會をひらくべし又第七日に聖會を汝らの中に開け是ふたつの日には何の業をもなすべからず只各人の食ふ者のみ汝等作ることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, '汝ら酵いれぬパンの節期を守るべし其は此日に我なんぢらの軍隊をエジプトの國より導きいだせばなり故に汝ら常例となして世々是日をまもるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, '正月に於てその月の十四日の晩より同月の二十一日の晩まで汝ら酵いれぬパンを食へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, '七日の間なんぢらの家にパン酵をおくべからず凡て酵いれたる物を食ふ人は其異邦人たると本國に生れし者たるとを問ず皆イスラエルの聖會より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, '汝ら酵いれたる物は何をも食ふべからず凡て汝らの居處に於ては酵いれぬパンを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, '是に於てモーセ、イスラエルの長老を盡くまねきて之にいふ汝等その家族に循ひて一頭の羔羊を撿み取り之を屠りて逾越節のために備へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, '又牛膝草一束を取て盂の血に濡し盂の血を門口の鴨居および二旁の柱にそそぐべし明朝にいたるまで汝等一人も家の戸をいづるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, '其はヱホバ、エジプトを撃に巡りたまふ時鴨居と兩旁の柱に血のあるを見ばヱキバ其門を逾越し殺滅者をして汝等の家に入て撃ざらしめたまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, '汝ら是事を例となして汝となんぢの子孫永くこれを守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, '汝等ヱホバがその言たまひし如くになんぢらに與へたまはんところの地に至る時はこの禮式をまもるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, '若なんぢらの子女この禮式は何の意なるやと汝らに問ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, '汝ら言ふべし是はヱホバの逾越節の祭祀なりヱホバ、エジプト人を撃たまひし時エジプトにをるイスラエルの子孫の家を逾越てわれらの家を救ひたまへりと民すなはち鞠て拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'イスラエルの子孫去てヱホバのモーセとアロンに命じたまひしごとくなし斯おこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, '爰にヱホバ夜半にエジプトの國の中の長子たる者を位に坐するパロの長子より牢獄にある俘虜の長子まで盡く撃たまふ亦家畜の首生もしかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, '期有しかばパロとその諸の臣下およびエジプト人みな夜の中に起あがりエジプトに大なる號哭ありき死人あらざる家なかりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'パロすなはち夜の中にモーセとアロンを召ていひけるは汝らとイスラエルの子孫起てわが民の中より出さり汝らがいへる如くに往てヱホバに事へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, '亦なんぢらが言るごとく汝らの羊と牛をひきて去れ汝らまた我を祝せよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, '是においてエジプト人我等みな死ると言て民を催逼て速かに國を去しめんとせしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, '民捏粉の未だ酵いれざるを執り捏盤を衣服に包みて肩に負ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, '而してイスラエルの子孫モーセの言のごとく爲しエジプト人に銀の飾物、金の飾物および衣服を乞たるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'ヱホバ、エジプト人をして民をめぐましめ彼等にこれを與へしめたまふ斯かれらエジプト人の物を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, '斯てイスラエルの子孫ラメセスよりスコテに進みしが子女の外に徒にて歩める男六十萬人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, '又衆多の寄集人および羊牛等はなはだ多の家畜彼等とともに上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, '爰に彼等エジプトより携へいでたる捏粉をもて酵いれぬパンを烘り未だ酵をいれざりければなり是かれらエジプトより逐いだされて濡滞るを得ざりしに由り又何の食糧をも備へざりしに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, '偖イスラエルの子孫のエジプトに住居しその住居の間は四百三十年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, '四百三十年の終にいたり即ち其日にヱホバの軍隊みなエジプトの國より出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, '是はヱホバが彼等をエジプトの國より導きいだしたまひし事のためにヱホバの前に守るべき夜なり是はヱホバの夜にしてイスラエルの子孫が皆世々まもるべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'ヱホバ、モーセとアロンに言たまひけるは逾越節の例は是のごとし異邦人はこれを食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, '但し各人の金にて買たる僕は割禮を施して然る後是を食しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, '外國の客および傭人は之を食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, '一の家にてこれを食ふべしその肉を少も家の外に持いづるなかれ又其骨を折べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'イスラエルの會衆みな之を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, '異邦人なんぢとともに寄居てヱホバの逾越節を守らんとせば其男悉く割禮を受て然る後に近りて守るべし即ち彼は國に生れたる者のごとくなるべし割禮をうけざる人はこれを食ふべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, '國に生れたる者にもまた汝らの中に寄居る異邦人にも此法は同一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'イスラエルの子孫みな斯おこなひヱホバのモーセとアロンに命じたまひしごとく爲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'その同じ日にヱホバ、イスラエルの子孫をその軍隊にしたがひてエジプトの國より導きいだしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, '爰にヱホバ、モーセに告ていひたまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '人と畜とを論ず凡てイスラエルの子孫の中の始て生れたる首生をば皆聖別て我に歸せしむべし是わが所屬なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'モーセ民にいひけるは汝等エジプトを出で奴隸たる家を出るこの日を誌えよヱホバ能ある手をもて汝等を此より導きいだしたまへばなり酵いれたるパンを食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'アビブの月の此日なんぢら出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'ヱホバ汝を導きてカナン人ヘテ人アモリ人ヒビ人エブス人の地すなはちその汝にあたへんと汝の先祖たちに誓ひたまひし彼乳と蜜の流るる地に至らしめたまはん時なんぢ此月に是禮式を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, '七日の間なんぢ酵いれぬパンを食ひ第七日にヱホバの節筵をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, '酵いれぬパンを七日くらふべし酵いれたるパンを汝の所におくなかれ又汝の境の中にて汝の許にパン酵をおくなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, '汝その日に汝の子に示して言べし是は吾がエジプトより出る時にヱホバの我に爲したまひし事のためなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, '斯是をなんぢの手におきて記號となし汝の目の間におきて記號となしてヱホバの法律を汝の口に在しむべし其はヱホバ能ある手をもて汝をエジプトより導きいだしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, '是故に年々その期にいたりてこの例をまもるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'ヱホバ汝となんぢの先祖等に誓ひたまひしごとく汝をカナン人の地にみちびきて之を汝に與へたまはん時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, '汝凡て始て生れたる者及び汝の有る畜の初生を悉く分ちてヱホバに歸せしむべし男牡はヱホバの所屬なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, '又驢馬の初子は皆羔羊をもて贖ふべしもし贖はずばその頸を折るべし汝の子等の中の長子なる人はみな贖ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, '後に汝の子汝に問て是は何なると言ばこれに言べしヱホバ能ある手をもて我等をエジプトより出し奴隸たりし家より出したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, '當時パロ剛愎にして我等を去しめざりしかばヱホバ、エジプトの國の中の長子たる者を人の長子より畜の初生まで盡く殺したまへり是故に始めて生れし牡を盡くヱホバに犠牲に献ぐ但しわが子等の中の長子は之を贖ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, '是をなんぢの手におきて號となし汝の目の間におきて誌となすべしヱホバ能ある手をもて我等をエジプトより導きいだしたまひたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, '偖パロ民をさらしめし時ペリシテ人の地は近かりけれども神彼等をみちびきて其地を通りたまはざりき其は民戰爭を見ば悔てエジプトに歸るならんと神おもひたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, '神紅海の曠野の道より民を導きたまふイスラエルの子孫行伍をたててエジプトの國より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, '其時モーセはヨセフの骨を携ふ是はヨセフ神かならず汝らを眷みたまふべければ汝らわが骨を此より携へ出づべしといひてイスラエルの子孫を固く誓せたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, '斯てかれらスコテより進みて曠野の端なるエタム比幕張す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'ヱホバかれらの前に往たまひ晝は雲の柱をもてかれらを導き夜は火の柱をもて彼らを照して晝夜往すすましめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, '民の前に晝は雲の柱を除きたまはず夜は火の柱をのぞきたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, '茲にヱホバ、モーセに告ていひ給ひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'イスラエルの子孫に言て轉回てミグドルと海の間なるピハヒロテの前にあたりてバアルゼポンの前に幕を張しめよ其にむかひて海の傍に幕を張るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'パロ、イスラエルの子孫の事をかたりて彼等はその地に迷ひをりて曠野に閉こめられたるならんといふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, '我パロの心を剛愎にすべければパロ彼等の後を追はん我パロとその凡の軍勢に由て譽を得エジプト人をして吾ヱホバなるを知しめんと彼等すなはち斯なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, '茲に民の逃さりたることエジプト王に聞えければパロとその臣下等民の事につきて心を變じて言ふ我等何て斯イスラエルを去しめて我に事ざらしむるがごとき事をなしたるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'パロすなはちその車を備へ民を將て己にしたがはしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, '撰抜の戰車六百兩にエジプトの諸の戰車および其の諸の軍長等を率ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'ヱホバ、エジプト王パロの心を剛愎にしたまひたれば彼イスラエルの子孫の後を追ふイスラエルの子孫は高らかなる手によりて出しなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'エジプト人等パロの馬、車およびその騎兵と軍勢彼等の後を追てそのバアルゼポンの前なるピハヒロテの邊にて海の傍に幕を張るに追つけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'パロの近よりし時イスラエルの子孫目をあげて視しにエジプト人己の後に進み來りしかば痛く懼れたり是に於てイスラエルの子孫ヱホバに呼號り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, '且モーセに言けるはエジプトに墓のあらざるがために汝われらをたづさへいだして曠野に死しむるや何故に汝われらをエジプトより導き出して斯我らに爲や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, '我等がエジプトにて汝に告て我儕を棄おき我らをしてエジプト人に事しめよと言し言は是ならずや其は曠野にて死るよりもエジプト人に事るは善ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'モーセ民にいひけるは汝ら懼るるなかれ立てヱホバが今日汝等のために爲たまはんところの救を見よ汝らが今日見たるエジプト人をば汝らかさねて復これを見ること絶てなかるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'ヱホバ汝等のために戰ひたまはん汝等は靜りて居るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, '時にヱホバ、モーセにいひたまひけるは汝なんぞ我に呼はるやイスラエルの子孫に言て進みゆかしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, '汝杖を擧げ手を海の上に伸て之を分ちイスラエルの子孫をして海の中の乾ける所を往しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, '我エジプト人の心を剛愎にすべければ彼等その後にしたがひて入るべし我かくしてパロとその諸の軍勢およびそ戰車と騎兵に囚て榮譽を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, '我がパロとその戰車と騎兵とによりて榮譽をえん時エジプト人は我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, '爰にイスラエルの陣營の前に行る神の使者移りてその後に行けり即ち雲の柱その前面をはなれて後に立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'エジプト人の陣營とイスラエル人の陣營の間に至りけるが彼がためには雲となり暗となり是がためには夜を照せり是をもて彼と是と夜の中に相近づかざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'モーセ手を海の上に伸ければヱホバ終夜強き東風をもて海を退かしめ海を陸地となしたまひて水遂に分れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'イスラエルの子孫海の中の乾ける所を行くに水は彼等の右左に墻となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'エジプト人等パロの馬車、騎兵みなその後にしたがひて海の中に入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, '暁にヱホバ火と雲との柱の中よりエジプト人の軍勢を望みエジプト人の軍勢を惱まし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, '其車の輪を脱して行に重くならしめたまひければエジプト人言ふ我儕イスラエルを離れて逃ん其はヱホバかれらのためにエジプト人と戰へばなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, '時にヱホバ、モーセに言たまひける汝の手を海の上に伸て水をエジプト人とその戰車と騎兵の上に流れ反らしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'モーセすなはち手を海の上に伸けるに夜明におよびて海本の勢力にかへりたればエジプト人之に逆ひて逃たりしがヱホバ、エジプト人を海の中に擲ちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, '即ち水流反りて戰車と騎兵を覆ひイスラエルの後にしたがひて海にいりしパロの軍勢を悉く覆へり一人も遺れる者あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, '然どイスラエルの子孫は海の中の乾ける所を歩みしが水はその右左に墻となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, '斯ヱホバこの日イスラエルをエジプト人の手より救ひたまへりイスラエルはエジプト人が海邊に死をるを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'イスラエルまたヱホバがエジプト人に爲たまひし大なる事を見たり是に於て民ヱホバを畏れヱホバとその僕モーセを信じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, '是に於てモーセおよびイスラエルの子孫この歌をヱホバに謡ふ云く我ヱホバを歌ひ頌ん彼は高らかに高くいますなり彼は馬とその乗者を海になげうちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'わが力わが歌はヱホバなり彼はわが救拯となりたまへり彼はわが神なり我これを頌美ん彼はわが父の神なり我これを崇めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'ヱホバは軍人にして其名はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, '彼パロの戰車とその軍勢を海に投すてたまふパロの勝れたる軍長等は紅海に沈めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, '大水かれらを掩ひて彼等石のごとくに淵の底に下る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'ヱホバよ汝の右の手は力をもて榮光をあらはすヱホバよ汝の右の手は敵を碎く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, '汝の大なる榮光をもて汝は汝にたち逆ふ者を滅したまふ汝怒を發すれば彼等は藁のごとくに焚つくさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, '汝の鼻の息によりて水積かさなり浪堅く立て岸のごとくに成り大水海の中に凝る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, '敵は言ふ我追て追つき掠取物を分たん我かれらに因てわが心を飽しめん我劍を抜んわが手かれらを亡さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, '汝氣を吹たまへば海かれらを覆ひて彼等は猛烈き水に鉛のごとくに沈めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'ヱホバよ神の中に誰か汝に如ものあらん誰か汝のごとく聖して榮あり讃べくして威ありて奇事を行なふ者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, '汝その右の手を伸たまへば地かれらを呑む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, '汝はその贖ひし民を恩惠をもて導き汝の力をもて彼等を汝の聖き居所に引たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, '國々の民聞て慄へペリシテに住む者畏懼を懐く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'エドムの君等駭きモアブの剛者戰慄くカナンに住る者みな消うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, '畏懼と戰慄かれらに及ぶ汝の腕の大なるがために彼らは石のごとくに默然たりヱホバよ汝の民の通り過るまで汝の買たまひし民の通り過るまで然るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, '汝民を導きてこれを汝の產業の山に植たまはんヱホバよ是すなはち汝の居所とせんとて汝の設けたまひし者なり主よ是汝の手の建たる聖所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'ヱホバは世々限なく王たるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, '斯パロの馬その車および騎兵とともに海にいりしにヱホバ海の水を彼等の上に流れ還らしめたまひしがイスラエルの子孫は海の中にありて旱地を通れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, '時にアロンの姉なる預言者ミリアム鼗を手にとるに婦等みな彼にしたがひて出で鼗をとり且踊る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'ミリアムすなはち彼等に和へて言ふ汝等ヱホバを歌ひ頌よ彼は高らかに高くいますなり彼は馬とその乗者を海に擲ちたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, '斯てモーセ紅海よりイスラエルを導きてシユルの曠野にいり曠野に三日歩みたりしが水を得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, '彼ら遂にメラにいたりしがメラの水苦くして飮ことを得ざりき是をもて其名はメラ(苦)と呼る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, '是に於て民モーセにむかひて呟き我儕何を飮んかと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'モーセ、ヱホバに呼はりしにヱホバこれに一本の木を示したまひたれば即ちこれを水に投いれしに水甘くなれり彼處にてヱホバ民のために法度と法律をたてたまひ彼處にてこれを試みて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, '言たまはく汝もし善く汝の神ヱホバの聲に聽したがひヱホバの口に善と見ることを爲しその誡命に耳を傾けその諸の法度を守ば我わがエジプト人に加へしところのその疾病を一も汝に加へざるべし其は我はヱホバにして汝を醫す者なればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, '斯て彼等エリムに至れり其處に水の井十二棕櫚七十本あり彼處にて彼等水の傍に幕張す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, '斯てエリムを出たちてイスラエルの子孫の會衆そのエジプトの地を出しより二箇月の十五日に皆エリムとシナイの間なるシンの曠野にいたりけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, '其曠野においてイスラエルの全會衆モーセとアロンに向ひて呟けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, '即ちイスラエルの子孫かれらに言けるは我儕エジプトの地に於て肉の鍋の側に坐り飽までにパンを食ひし時にヱホバの手によりて死たらば善りし者を汝等はこの曠野に我等を導きいだしてこの全會を饑に死しめんとするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, '時にヱホバ、モーセに言たまひけるは視よ我パンを汝らのために天より降さん民いでて日用の分を毎日斂むべし斯して我かれらが吾の法律にしたがふや否を試みん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, '第六日には彼等その取いれたる者を調理ふべし其は日々に斂る者の二倍なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'モーセとアロン、イスラエルの全の子孫に言けるは夕にいたらば汝等はヱホバが汝らをエジプトの地より導きいだしたまひしなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, '又朝にいたらば汝等ヱホバの榮光を見ん其はヱホバなんぢらがヱホバに向ひて呟くを聞たまへばなり我等を誰となして汝等は我儕に向ひて呟くや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'モーセまた言けるはヱホバ夕には汝等に肉を與へて食はしめ朝にはパンをあたへて飽しめたまはん其はヱホバ己にむかひて汝等が呟くところの怨言を聞給へばなり我儕を誰と爲や汝等の怨言は我等にむかひてするに非ずヱホバにむかひてするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'モーセ、アロンに言けるはイスラエルの子孫の全會衆に言へ汝等ヱホバの前に近よれヱホバなんぢらの怨言を聞給へりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'アロンすなはちイスラエルの子孫の全會衆に語しかば彼等曠野を望むにヱホバの榮光雲の中に顯はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'ヱホバ、モーセに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '我イスラエルの子孫の怨言を聞り彼等に告て言へ汝等夕には肉を食ひ朝にはパンに飽べし而して我のヱホバにして汝等の神なることを知にいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, '即ち夕におよびて鶉きたりて營を覆ふ又朝におよびて露營の四圍におきしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'そのおける露乾くにあたりて曠野の表に霜のごとき小き圓き者地にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'イスラエルの子孫これを見て此は何ぞやと互に言ふ其はその何たるを知ざればなりモーセかれらに言けるは是はヱホバが汝等の食にあたへたまふパンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'ヱホバの命じたまふところの事は是なり即ち各その食ふところに循ひて之を斂め汝等の人數にしたがひて一人に一オメルを取れ各人その天幕にをる者等のためにこれを取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'イスラエルの子孫かくなせしに其斂るところに多きと少きとありしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'オメルをもてこれむ量るに多く斂めし者にも餘るところ無く少く斂めし者にも足ぬところ無りき皆その食ふところに循ひてこれを斂めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'モーセ彼等に誰も朝までこれを殘しおく可らずと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, '然るに彼等モーセに聽したがはずして或者はこれを朝まで殘したりしが蟲たかりて臭なりぬモーセこれを怒る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, '人々各その食ふところに循ひて朝毎に之を斂めしが日熱なれば消ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, '第六日にいたりて人々二倍のパンを斂めたり即ち一人に二オメルを斂むるに會衆の長皆きたりて之をモーセに告ぐモーセ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'かれらに言ふヱホバの言たまふところ是のごとし明日はヱホバの聖安息日にして休息なり今日汝等烤んとする者を烤き煮んとする者を煮よ其殘れる者は皆明朝まで蔵めおくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, '彼等モーセの命ぜしごとくに翌朝まで蔵めおきしが臭なること無く又蟲もその中に生ぜざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'モーセ言ふ汝等今日其を食へ今日はヱホバの安息日なれば今日は汝等これを野に獲ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, '六日の間汝等これを斂むべし第七日は安息日なればその日には有ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, '然るに民の中に七日に出て斂めんとせし者ありしが得ところ無りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, '是に於てヱホバ、モーセに言たまひけるは何時まで汝等は吾が誡命とわが律法をまもることをせざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, '汝等視よヱホバなんぢらに安息日を賜へり故に第六日に二日の食物を汝等にあたへたまふなり汝等おのおのその處に休みをれ第七日にはその處より出る者あるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, '是民第七日に休息り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'イスラエルの家その物の名をマナと稱り是は莞の實のごとくにして白く其味は蜜をいれたる菓子のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'モーセ言ふヱホバの命じたまふところ是のごとし是を一オメル盛て汝等の代々の子孫のためにたくはへおくべし是はわが汝等をエジプトの地より導きいだせし時に曠野にて汝等を養ひしところのパンを之に見さしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, '而してモーセ、アロンに言けるは壷を取てその中にマナ一オメルを盛てこれをヱホバの前におき汝等の代々の子孫のためにたくはふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'ヱホバのモーセに命じたまひし如くにアロンこれを律法の前におきてたくはふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'イスラエルの子孫は人の住る地に至るまで四十年が間マナを食へり即ちカナンの地の境にいたるまでマナを食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'オメルはエパの十分の一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'イスラエルの子孫の會衆ヱホバの命にしたがひて皆シンの曠野を立出で旅路をかさねてレピデムに幕張せしが民の飮む水あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, '是をもて民モーセと爭ひて言ふ我儕に水をあたへて飮しめよモーセかれらに言けるは汝ら何ぞ我とあらそふや何ぞヱホバを試むるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, '彼處にて民水に渇き民モーセにむかひて呟き言ふ汝などて我等をエジプトより導きいだして我等とわれらの子女とわれらの家畜を渇に死しめんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, '是に於てモーセ、ヱホバに呼はりて言ふ我この民に何をなすべきや彼等は殆ど我を石にて撃んとするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'ヱホバ、モーセに言たまひけるは汝民の前に進み民の中の或長老等を伴ひかの汝が河を撃し杖を手に執て往よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, '視よ我そこにて汝の前にあたりてホレブの磐の上に立ん汝磐を撃べし然せば其より水出ん民これを飮べしモーセすなはちイスラエルの長老等の前にて斯おこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'かくて彼その處の名をマツサと呼び又メリバと呼り是はイスラエルの子孫の爭ひしに由り又そのヱホバはわれらの中に在すや否と言てヱホバを試みしに由なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, '時にアマレクきたりてイスラエルとレピデムに戰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'モーセ、ヨシユアに言けるは我等のために人を擇み出てアマレクと戰へ明日我神の杖を手にとりて岡の嶺に立ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'ヨシユアすなはちモーセの己に言しごとくに爲しアマレクと戰ふモーセ、アロンおよびホルは岡の嶺に登りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'モーセ手を擧をればイスラエル勝ち手を垂ればアマレク勝り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, '然るにモーセの手重くなりたればアロンとホル石をとりてモーセの下におきてその上に坐せしめ一人は此方一人は彼方にありてモーセの手を支へたりしかばその手日の沒まで垂下ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, '是においてヨシユア刃をもてアマレクとその民を敗れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'ヱホバ、モーセに言たまひけるは之を書に筆して記念となしヨシユアの耳にこれをいれよ我必ずアマレクの名を塗抹て天下にこれを誌ゆること无らしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, '斯てモーセ一座の壇を築きその名をヱホバニシ(ヱホバ吾旗)と稱ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'モーセ云けらくヱホバの寶位にむかひて手を擧ることありヱホバ世々アマレクと戰ひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, '茲にモーセの外舅なるミデアンの祭司ヱテロ神が凡てモーセのため又その民イスラエルのために爲したまひし事ヱホバがイスラエルをエジプトより導き出したまひし事を聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, '是に於てモーセの外舅ヱテロかの遣り還されてありしモーセの妻チッポラとその二人の子を挈へ來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'その子の一人の名はゲルシヨムと云ふ是はモーセ我他國に客となりをると言たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, '今一人の名はエリエゼルと曰ふ是はかれ吾父の神われを助け我を救ひてパロの劍を免かれしめたまふと言たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, '斯モーセの外舅ヱテロ、モーセの子等と妻をつれて曠野に來りモーセが神の山に陣を張る處にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, '彼すなはちモーセに言けるは汝の外舅なる我ヱテロ汝の妻および之と供なるその二人の子をたづさへて汝に詣ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'モーセ出てその外舅を迎へ禮をなして之に接吻し互に其安否を問て共に天幕に入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, '而してモーセ、ヱホバがイスラエルのためにパロとエジプト人とに爲たまひし諸の事と途にて遇し諸の艱難およびヱホバの己等を拯ひたまひし事をその外舅に語りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'ヱテロ、ヱホバがイスラエルをエジプト人の手より救ひいだして之に諸の恩典をたまひし事を喜べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'ヱテロすなはち言けるはヱホバは頌べき哉汝等をエジプト人の手とパロの手より救ひいだし民をエジプト人の手の下より拯ひいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, '今我知るヱホバは諸の神よりも大なり彼等傲慢を逞しうして事をなせしがヱホバかれらに勝りと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, '而してモーセの外舅ヱテロ燔祭と犠牲をヱホバに持きたれりアロンおよびイスラエルの長老等皆きたりてモーセの外舅とともに神の前に食をなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, '次の日にいたりてモーセ坐して民を審判きしが民は朝より夕までモーセの傍に立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'モーセの外舅モーセの凡て民に爲ところを見て言けるは汝が民になす此事は何なるや何故に汝は一人坐しをりて民朝より夕まで汝の傍にたつや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'モーセその外舅に言けるは民神に問んとて我に來るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, '彼等事ある時は我に來れば我此と彼とを審判きて神の法度と律法を知しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'モーセの外舅これに言けるは汝のなすところ善らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, '汝かならず氣力おとろへん汝も汝とともなる民も然らん此事汝には重に過ぐ汝一人にては之を爲ことあたはざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, '今吾言を聽け我なんぢに策を授けん願くは神なんぢとともに在せ汝民のために神の前に居り訴訟を神に陳よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, '汝かれらに法度と律法を敎へ彼等の歩むべき道と爲べき事とを彼等に示せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, '又汝全體の民の中より賢して神を畏れ眞實を重んじ利を惡むところの人を選み之を民の上に立て千人の司となし百人の司となし五十人の司となし十人の司となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, '而して彼等をして常に民を鞫かしめ大事は凡てこれを汝に陳しめ小事は凡て彼等みづからこれを判かしむべし斯汝の身の煩瑣を省き彼らをして汝とその任を共にせしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, '汝もし此事を爲し神また斯汝に命じなば汝はこれに勝ん此民もまた安然にその所に到ることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'モーセその外舅の言にしたがひてその凡て言しごとく成り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'モーセすなはちイスラエルの中より遍く賢き人を擇みてこれを民の長となし千人の司となし百人の司となし五十人の司となし十人の司となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, '彼等常に民を鞫き難事はこれをモーセに陳べ小事は凡て自らこれを判けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, '斯てモーセその外舅を還したればその國に往ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'イスラエルの子孫エジプトの地を出て後第三月にいたりて其日にシナイの曠野に至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, '即ちかれらレピデムを出たちてシナイの曠野にいたり曠野に幕を張り彼處にてイスラエルは山の前に營を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, '爰にモーセ登て神に詣るにヱホバ山より彼を呼て言たまはく汝かくヤコブの家に言ひイスラエルの子孫に告べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '汝らはエジプト人に我がなしたるところの事を見我が鷲の翼をのべて汝らを負て我にいたらしめしを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, '然ば汝等もし善く我が言を聽きわが契約を守らば汝等は諸の民に愈りてわが寶となるべし全地はわが所有なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, '汝等は我に對して祭司の國となり聖き民となるべし是等の言語を汝イスラエルの子孫に告べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, '是に於てモーセ來りて民の長老等を呼びヱホバの己に命じたまひし言を盡くその前に陳たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, '民皆等く應へて言けるはヱホバの言たまひし所は皆われら之を爲べしとモーセすなはち民の言をヱホバに告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'ヱホバ、モーセに言たまひけるは觀よ我密雲の中にをりて汝に臨む是民をして我が汝と語るを聞しめて汝を永く信ぜしめんがためなりとモーセ民の言をヱホバに告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'ヱホバ、モーセに言たまひけるは汝民の所に往て今日明日これを聖め之にその衣服を澣せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, '準備をなして三日を待て其は第三日にヱホバ全體の民の目の前にてシナイ山に降ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, '汝民のために四周に境界を設けて言べし汝等愼んで山に登るなかれその境界に捫るべからず山に捫る者はかならず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, '手を之に觸べからず其者はかならす石にて撃ころされ或は射ころさるべし獣と人とを言ず生ることを得じ喇叭を長く吹鳴さば人々山に上るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'モーセすなはち山を下り民にいたりて民を聖め民その衣服を濯ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'モーセ民に言けるは準備をなして三日を待て婦人に近づくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'かくて三日の朝にいたりて雷と電および密雲山の上にあり又喇叭の聲ありて甚だ高かり營にある民みな震ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'モーセ營より民を引いでて神に會しむ民山の麓に立に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'シナイ山都て煙を出せりヱホバ火の中にありてその上に下りたまへばなりその煙竃の煙のごとく立のぼり山すべて震ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, '喇叭の聲彌高くなりゆきてばげしくなりける時モーセ言を出すに神聲をもて應へたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'ヱホバ、シナイ山に下りその山の頂上にいまし而してヱホバ山の頂上にモーセを召たまひければモーセ上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'ヱホバ、モーセに言たまひけるは下りて民を警めよ恐らくは民推破りてヱホバに來りて見んとし多の者死るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, '又ヱホバに近くところの祭司等にその身を潔めしめよ恐くはヱホバかれらを撃ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'モーセ、ヱホバに言けるは民はシナイ山に得のぼらじ其は汝われらを警めて山の四周に境界をたて山を聖めよと言たまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'ヱホバかれに言たまひけるは往け下れ而して汝とアロンともに上り來るべし但祭司等と民には推破りてにのぼりきたらしめざれ恐らくは我かれらを撃ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'モーセ民にくだりゆきてこれに告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, '神この一切の言を宣て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '我は汝の神ヱホバ汝をエジプトの地その奴隸たる家より導き出せし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, '汝我面の前に我の外何物をも神とすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, '汝自己のために何の偶像をも彫むべからず又上は天にある者下は地にある者ならびに地の下の水の中にある者の何の形状をも作るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, '之を拝むべからずこれに事ふべからず我ヱホバ汝の神は嫉む神なれば我を惡む者にむかひては父の罪を子にむくいて三四代におよぼし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, '我を愛しわが誡命を守る者には恩惠をほどこして千代にいたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, '汝の神ヱホバの名を妄に口にあぐべからずヱホバはおのれの名を妄に口にあぐる者を罰せではおかざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, '安息日を憶えてこれを聖潔すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, '六日の間勞きて汝の一切の業を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, '七日は汝の神ヱホバの安息なれば何の業務をも爲べからず汝も汝の息子息女も汝の僕婢も汝の家畜も汝の門の中にをる他國の人も然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, '其はヱホバ六日の中に天と地と海と其等の中の一切の物を作りて第七日に息みたればなり是をもてヱホバ安息日を祝ひて聖日としたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, '汝の父母を敬へ是は汝の神ヱホバの汝にたまふ所の地に汝の生命の長からんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, '汝殺すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, '汝姦淫するなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, '汝盗むなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, '汝その隣人に對して虚妄の證據をたつるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, '汝その隣人の家を貧るなかれ又汝の鄰人の妻およびその僕婢牛驢馬ならびに凡て汝の隣人の所有を貧るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, '民みな雷と電と喇叭の音と山の煙るとを見たり民これを見て懼れをののきて遠く立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'モーセにいひけるは汝われらに語れ我等聽ん唯神の我らに語りたまふことあらざらしめよ恐くは我等死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'モーセ民に言けるは畏るるなかれ神汝らを試みんため又その畏怖を汝らの面の前におきて汝らに罪を犯さざらしめんために臨みたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, '是において民は遠くに立ちしがモーセは神の在すところの濃雲に進みいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'ヱホバ、モーセに言たまひけるは汝イスラエルの子孫に斯いふべし汝等は天よりわが汝等に語ふを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, '汝等何をも我にならべて造るべからず銀の神をも金の神をも汝等のために造るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, '汝土の壇を我に築きてその上に汝の燔祭と酬恩祭汝の羊と牛をそなふべし我は凡てわが名を憶えしむる處にて汝に臨みて汝を祝まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, '汝もし石の壇を我につくるならば琢石をもてこれを築くべからず其は汝もし鑿をこれに當なば之を汚すべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, '汝階よりわが壇に升るべからず是汝の恥る處のその上に露るることなからんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '是は汝が民の前に立べき律例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, '汝ヘブルの僕を買ふ時は六年の間之に職業を爲しめ第七年には贖を索ずしてこれを釋つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, '彼もし獨身にて來らば獨身にて去べし若妻あらばその妻これとともに去べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'もしその主人これに妻をあたへて男子又は女子これに生れたらば妻とその子等は主人に屬すべし彼は獨身にて去べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, '僕もし我わが主人と我が妻子を愛す我釋たるるを好まずと明白に言ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'その主人これを士師の所に携ゆき又戸あるひは戸柱の所につれゆくべし而して主人錐をもてかれの耳を刺とほすべし彼は何時までもこれに事ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, '人若その娘を賣て婢となす時は僕のごとくに去べからす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, '彼もしその約せし主人の心に適ざる時はその主人これを贖はしむることを得べし然ど之に眞實ならずして亦これを異邦人に賣ことをなすを得べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, '又もし之を己の子に與へんと約しなばこれを女子のごとくに待ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, '父もしその子のために別に娶ることあるとも彼に食物と衣服を與ふる事とその交接の道とはこれを間斷しむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, '其人かれに此三を行はずば彼は金をつくのはずして出さることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, '人を撃て死しめたる妻は必ず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, '若人みづから畫策ことなきに神人をその手にかからしめたまふことある時は我汝のために一箇の處を設くればその人其處に逃るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, '人もし故にその隣人を謀りて殺す時は汝これをわが壇よりも執へゆきて殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'その父あるひは母を撃ものは必ず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, '人を拐帶したる者は之を賣たるも尚その手にあるも必ず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'その父あるひは母を罵る者は殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, '人相爭ふ時に一人石または拳をもてその對手を撃ちしに死にいたらずして床につくことあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, '若起あがりて杖によりて歩むにいたらば之を撃たる者は赦さるべし但しその業を休める賠償をなして之を全く愈しむべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, '人もし杖をもてその僕あるひは婢を撃んにその手の下に死ば必ず罰せらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, '然ど彼もし一日二日生のびなば其人は罰せられざるべし彼はその人の金子なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, '人もし相爭ひて妊める婦を撃ちその子を堕させんに別に害なき時は必ずその婦人の夫の要むる所にしたがひて刑られ法官の定むる所を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, '若害ある時は生命にて生命を償ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, '目にて目を償ひ歯にて歯を償ひ手にて手を償ひ足にて足を償ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, '烙にて烙を償ひ傷にて傷を償ひ打傷にて打傷を償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, '人もしその僕の一の目あるひは婢の一の目を撃てこれを喪さばその目のために之を釋つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, '又もしその僕の一箇の歯か婢の一箇の歯を打落ばその歯のために之を釋つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, '牛もし男あるひは女を衝て死しめなばその牛をば必ず石にて撃殺すべしその肉は食べからず但しその牛の主は罪なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, '然ど牛もし素より衝くことをなす者にしてその主これがために忠告をうけし事あるに之を守りおかずして遂に男あるひは女を殺すに至らしめなばその牛は石にて撃れその主もまた殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, '若彼贖罪金を命ぜられなば凡てその命ぜられし者を生命の償に出すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, '男子を衝も女子を衝もこの例にしたがひてなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, '牛もし僕あるひは婢を衝ばその主人に銀三十シケルを與ふべし又その牛は石にて撃ころすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, '人もし坑を啓くか又は人もし穴を掘ことをなしこれを覆はずして牛あるひは驢馬これに陷ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, '穴の主これを償ひ金をその所有主に與ふべし但しその死たる畜は己の有となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, '此人の牛もし彼人のを衝殺さば二人その生る牛を賣てその價を分つべし又その死たるものをも分つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, '然どその牛素より衝ことをなす者なること知をるにその主これを守りおかざりしならばその人かならず牛をもて牛を償ふべし但しその死たる者は己の有となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, '人もし牛あるひは羊を竊みてこれを殺し又は賣る時は五の牛をもて一の牛を賠ひ四の羊をもて一の羊を賠ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'もし盗賊の壞り入るを見てこれを撃て死しむる時はこれがために血をながすに及ばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, '然ど若日いでてよりならば之がために血をながすべし盗賊は全く償をなすべし若物あらざる時は身をうりてその竊める物を償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, '若その竊める物眞に生てその手にあらばその牛驢馬羊たるにかかはらず倍してこれを償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, '人もし田圃あるひは葡萄園の物を食はせその家畜をはなちて人の田圃の物を食ふにいたらしむる時は自己の田圃の嘉物と自己の葡萄園の嘉物をもてその償をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, '火もし逸て荊棘にうつりその積あげたる穀物あるひは未だ刈ざる穀物あるひは田野を燬ばその火を焚たる者かならずこれを償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, '人もし金あるひは物を人に預るにその人の家より竊みとられたる時はその盗者あらはれなばこれを倍して償はしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, '盗者もしあらはれずば家の主人を法官につれゆきて彼がその人の物に手をかけたるや否を見るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, '何の過愆を論ず牛にもあれ驢馬にもあれ羊にもあれ衣服にもあれ又は何の失物にもあれ凡て人の見て是其なりと言ふ者ある時は法官その兩造の言を聽べし而して法官の罪ありとする者これを倍してその對手に償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, '人もし驢馬か牛か羊か又はその他の家畜をその隣人にあづけんに死か傷けらるるか又は搶ひさらるることありて誰もこれを見し者なき時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, '二人の間にその隣人の物に手をかけずとヱホバを指て誓ふことあるべし然る時はその持主これを承諾べし彼人は償をなすに及ばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, '然ど若自己の許より竊まれたる時はその所有主にこれを償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, '若またその裂ころされし時は其を證據のために持きたるべしその裂ころされし者は償ふにおよばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, '人もしその隣人より借たる者あらんにその物傷けられ又は死ることありてその所有主それとともにをらざる時は必ずこれを償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'その所有主それと共にをらばこれを償ふにむよばず雇し者なる時もしかり其は雇れて來りしなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, '人もし聘定あらざる處女を誘ひてこれと寝たらば必ずこれに聘禮して妻となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'その父もしこれをその人に與ふることを固く拒まば處女にする聘禮にてらして金をはらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, '魔術をつかふ女を生しおくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, '凡て畜を犯す者をば必ず殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'ヱホバをおきて別の神に犠牲を献る者をば殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, '汝他國の人を惱すべからず又これを虐ぐべからず汝らもエジプトの國にをる時は他國の人たりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, '汝凡て寡婦あるひは孤子を惱すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, '汝もし彼等を惱まして彼等われに呼らば我かならずその號呼を聽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'わが怒烈しくなり我劍をもて汝らを殺さん汝らの妻は寡婦となり汝らの子女は孤子とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, '汝もし汝とともにあるわが民の貧き者に金を貸す時は金貸のごとくなすべからず又これより利足をとるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, '汝もし人の衣服を質にとらば日のいる時までにこれを歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, '其はその身を蔽ふ者は是のみにして是はその膚の衣なればなり彼何の中に寝んや彼われに龥はらば我きかん我は慈悲ある者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, '汝神を罵るべからず民の主長を詛ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, '汝の豊滿なる物と汝の搾りたる物とを献ぐることを怠るなかれ汝の長子を我に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, '汝また汝の牛と羊をも斯なすべし即ち七日母とともにをらしめて八日にこれを我に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, '汝等は我の聖民となるべし汝らは野にて獣に裂れし者の肉を食ふべからず汝らこれを犬に投與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '汝虚妄の風説を言ふらすべからず惡き人と手をあはせて人を誣る證人となるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, '汝衆の人にしたがひて惡をなすべからず訴訟において答をなすに方りて衆の人にしたがひて道を曲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, '汝また貧き人の訴訟を曲て庇くべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, '汝もし汝の敵の牛あるひは驢馬の迷ひ去に遭ばかならずこれを牽てその人に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, '汝もし汝を惡む者の驢馬のその負の下に仆れ臥すを見ば愼みてこれを遺さるべからず必ずこれを助けてその負を釋べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, '汝貧き者の訴訟ある時にその判決を曲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, '虚假の事に遠かれ無辜者と義者とはこれを殺すなかれ我は惡き者を義とすることあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, '汝賄賂を受べからず賄賂は人の目を暗まし義者の言を曲しむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, '他國の人を虐ぐべからず汝等はエジプトの國にをる時は他國の人にてありたれば他國の人の心を知なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, '汝六年の間汝の地に種播きその實を穫いるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, '但し第七年にはこれを息ませて耕さずにおくべし而して汝の民の貧き者に食ふことを得せしめよ其餘れる者は野の獣これを食はん汝の葡萄園も橄欖園も斯のごとくなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, '汝六日の間汝の業をなし七日に息むべし斯汝の牛および驢馬を息ませ汝の婢の子および他國の人をして息をつかしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'わが汝に言し事に凡て心を用ひよ他の神々の名を稱ふべからずまた之を汝の口より聞えしめざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, '汝年に三度わがために節筵を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, '汝無酵パンの節禮をまもるべし即ちわが汝に命ぜしごとくアビブの月の定の時において七日の間酵いれぬパンを食ふべし其はその月に汝エジプトより出たればなり徒手にてわが前に出る者あるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'また穡時の節筵を守るべし是すなはち汝が勞苦て田野に播る者の初の實を祝ふなり又収蔵の節筵を守るべし是すなはち汝の勞苦によりて成る者を年の終に田野より収蔵る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, '汝の男たる者は皆年に三次主ヱホバの前に出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, '汝わが犠牲の血を酵いれしパンとともに献ぐべからず又わが節筵の脂を翌朝まで殘しおくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, '汝の地に初に結べる實の初を汝の神ヱホバの室に持きたるべし汝山羊羔をその母の乳にて煮べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, '視よ我天の使をかはして汝に先たせ途にて汝を守らせ汝をわが備へし處に導かしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, '汝等その前に愼みをりその言にしたがへ之を怒らするなかれ彼なんぢらの咎を赦さざるべしわが名かれの中にあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, '汝もし彼が言にしたがひ凡てわが言ところを爲ば我なんぢの敵の敵となり汝の仇の仇となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'わが使汝にさきだちゆきて汝をアモリ人ヘテ人ペリジ人カナン人ヒビ人およびヱブス人に導きたらん我かれらを絶べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, '汝かれらの神を拝むべからずこれに奉事べからず彼らの作にならふなかれ汝其等を悉く毀ちその偶像を打摧くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, '汝等の神ヱホバに事へよ然ばヱホバ汝らのパンと水を祝し汝らの中より疾病を除きたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, '汝の國の中には流產する者なく妊ざる者なかるべし我汝の日の數を盈さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, '我わが畏懼をなんぢの前に遣し汝が至るところの民をことごとく敗り汝の諸の敵をして汝に後を見せしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, '吾黄蜂を汝の先につかはさん是ヒビ人カナン人およびヘテ人を汝の前より逐はらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, '我かれらを一年の中には汝の前より逐はらはじ恐くは土地荒れ野の獣増て汝を害せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, '我漸々にかれらを汝の前より逐はらはん汝らは遂に増てその地を獲にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, '我なんぢの境をさだめて紅海よりペリシテ人の海にいたらせ曠野より河にいたらしめん我この地に住る者を汝の手に付さん汝かれらを汝の前より逐はらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, '汝かれらおよび彼らの神と何の契約をもなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, '彼らは汝の國に住べきにあらず恐くは彼ら汝をして我に罪を犯さしめん汝もし彼等の神に事なばその事かならず汝の機檻となるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, '又モーセに言たまひけるは汝アロン、ナダブ、アビウおよびイスラエルの七十人の長老とともにヱホバの許に上りきたれ而して汝等遥にたちて拝むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'モーセ一人ヱホバに近づくべし彼等は近るべからず又民もかれとともに上るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'モーセ來りてヱホバの諸の言およびその諸の典例を民に告しに民みな同音に應て云ふヱホバの宣ひし言は皆われらこれを爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'モーセ、ヱホバの言をことごとく書記し朝夙に興いでて山の麓に壇を築きイスラエルの十二の支派にしたがひて十二の柱を建て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, '而してイスラエルの子孫の中の少き人等を遣はしてヱホバに燔祭を献げしめ牛をもて酬恩祭を供へしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'モーセ時にその血の半をとりて鉢に盛れ又その血の半を壇の上に灌げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, '而して契約の書をとりて民に誦きかせたるに彼ら應へて言ふヱホバの宣ふ所は皆われらこれを爲て遵ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'モーセすなはちその血をとりて民に灌ぎて言ふ是すなはちヱホバが此諸の言につきて汝と結たまへる契約の血なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, '斯てモーセ、アロン、ナダブ、アビウおよびイスラエルの七十人の長老のぼりゆきて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'イスラエルの神を見るにその足の下には透明れる靑玉をもて作れるごとき物ありて耀ける天空にさも似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, '神はイスラエルの此頭人等にその手をかけたまはざりき彼等は神を見又食飮をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, '茲にヱホバ、モーセに言たまひけるは山に上りて我に來り其處にをれ我わが彼等を敎へんために書しるせる法律と誡命を載るところの石の板を汝に與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'モーセその從者ヨシユアとともに起あがりモーセのぼりて神の山に至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, '時に彼長老等に言けるは我等の汝等に歸るまで汝等は此に待ちをれ視よアロンとホル汝等とともに在り凡て事ある者は彼等にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, '而してモーセ山にのぼりしが雲山を蔽ひをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'すなはちヱホバの榮光シナイ山の上に駐りて雲山を蔽ふこと六日なりしが七日にいたりてヱホバ雲の中よりモーセを呼たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'ヱホバの榮光山の嶺に燃る火のごとくにイスラエルの子孫の目に見えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'モーセ雲の中に入り山に登りモーセ四十日四十夜山に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'ヱホバ、モーセに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'イスラエルの子孫に告て我に献物を持きたれと言へ凡てその心に好んで出す者よりは汝等その我に献ぐるところの物を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, '汝等がかれらより取べきその献物は是なり即ち金 銀 銅');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, '靑 紫 紅の線 麻 山羊毛');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, '赤染の牡羊の皮 貛の皮 合歓木');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, '燈油塗膏と馨しき香を調ふところの香料');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, '葱珩およびエポデと胸牌に嵌る玉');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, '彼等わがために聖所を作るべし我かれらの中に住ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, '凡てわが汝らに示すところに循ひ幕屋の式樣およびその器具の式樣にしたがひてこれを作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, '彼等合歓木をもて櫃を作るべしその長は二キユビト半その濶は一キユビト半その高は一キユビト半なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, '汝純金をもて之を蔽ふべし即ち内外ともにこれを蔽ひその上の周圍に金の縁を造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, '汝金の環四箇を鋳てその四の足につくべし即ち此旁に二箇の輪彼旁に二箇の輪をつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, '汝また合歓木をもて杠を作りてこれに金を著すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, '而してその杠を櫃の邊旁の環にさしいれてこれをもて櫃を舁べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, '杠は櫃の環に差いれおくべし其より脱はなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, '汝わが汝に與ふる律法をその櫃に蔵むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, '汝純金をもて贖罪所を造るべしその長は二キユビト半その濶は一キユビト半なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, '汝金をもて二箇のケルビムを作るべし即ち槌にて打てこれを作り贖罪所の兩旁に置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, '一のケルブを此旁に一のケルブを彼旁に造れ即ちケルビムを贖罪所の兩旁に造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'ケルビムは翼を高く展べその翼をもて贖罪所を掩ひその面を互に相向くべしすなはちケルビムの面は贖罪所に向ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, '汝贖罪所を櫃の上に置ゑまた我が汝に與ふる律法を櫃の中に蔵むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, '其處にて我なんぢに會ひ贖罪所の上より律法の櫃の上なる二箇のケルビムの間よりして我イスラエルの子孫のためにわが汝に命ぜんとする諸の事を汝に語ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, '汝また合歓木をもて案を作るべしその長は二キユビトその濶は一キユビトその高は一キユビト半なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, '而して汝純金をこれに著せその周圍に金の縁をつくるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, '汝その四圍に掌寛の邊をつくりその邊の周圍に金の小縁を作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'またそれがために金の環四箇を作りその足の四隅にその環をつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, '環は邊の側に附べし是は案を舁ところの杠をいるる處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'また合歓木をもてその杠をつくりてこれに金を著すべし案はこれに因て舁るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, '汝また其に用ふる皿匙杓および酒を灌ぐところの斝を作るべし即ち純金をもてこれを造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, '汝案の上に供前のパンを置て常にわが前にあらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, '汝純金をもて一箇の燈臺を造るべし燈臺は槌をもてうちて之を作るべしその臺座 軸 萼 節 花は其に聯らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, '又六の枝をその旁より出しむべし即ち燈臺の三の枝は此旁より出で燈臺の三の枝は彼旁より出しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, '巴旦杏の花の形せる三の萼節および花とともに此枝にあり又巴旦杏の花の形せる三の萼節および花とともに彼枝にあるべし燈臺より出る六の枝を皆斯のごとくにすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, '巴旦杏の花の形せる四の萼その節および花とともに燈臺にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, '兩箇の枝の下に一箇の節あらしめ又その兩箇の枝の下に一箇の節あらしめ又その兩箇の枝の下に一箇の節あらしむべし燈臺より出る六の枝みな是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'その節と枝とは其に連ならしめ皆槌にて打て純金をもて造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, '又それがために七箇の燈盞を造りその燈盞を上に置てその對向を照さしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'その燈鉗と剪燈盤をも純金ならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, '燈臺と此の諸の器具を造るには純金一タラントを用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, '汝山にて示されし式樣にしたがひて之を作ることに心を用ひよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '汝また幕屋のために十の幕を造るべしその幕は即ち麻の撚絲靑紫および紅の絲をもて之を造り精巧にケルビムをその上に織出すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, '一の幕の長は二十八キユビト一の幕の濶は四キユビトなるべし幕は皆その寸尺を同うすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'その幕五箇を互に連ねあはせ又その他の幕五箇をも互に連ねあはすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, '而してその一聯の幕の邊においてその聯絡處の端に靑色の襟を付べし又他の一聯の幕の聯絡處の邊にも斯なすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, '汝一聯の幕に襟五十をつけ又他の一聯の幕の聯絡處の邊にも襟五十をつけ斯その襟をして彼と此と相對せしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, '而して金の鐶五十を造りその鐶をもて幕を連ねあはせて一の幕屋となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, '汝また山羊の毛をもて幕をつくりて幕屋の上の蓋となすべし即ち幕十一をつくるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'その一箇の幕の長は三十キユビトその一箇の幕の濶は四キユビトなるべし即ちその十一の幕は寸尺を一にすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, '而してその幕五を一に聯ねまたその幕六を一に聯ねその第六の幕を幕屋の前に摺むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, '又その一聯の幕の邊すなはちその聯絡處の端に襟五十を付け又他の一聯の幕の聯絡處にも襟五十を付べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, '而して銅の鐶五十を作りその鐶を襟にかけてその幕を聯ねあはせて一となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'その天幕の幕の餘れる遺餘すなはちその餘れる半幕をば幕屋の後に垂しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, '天幕の幕の餘れる者は此旁に一キユビト彼旁に一キユビトあり之を幕屋の兩旁此方彼方に垂てこれを蓋ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, '汝赤く染たる牡山羊の皮をもて幕屋の蓋をつくりその上に貛の皮の蓋をほどこすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, '汝合歓木をもて幕屋のために竪板を造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, '一枚の板の長は十キユビト一枚の板の濶は一キユビト半なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, '板ごとに二の榫をつくりて彼と此と交指しめよ幕屋の板には皆斯のごとく爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, '汝幕屋のために板を造るべし即ち南向の方のために板二十枚を作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, '而してその二十枚の板の下に銀の座四十を造るべし即ち此板の下にもその二の榫のために二の座あらしめ彼板の下にもその二の榫のために二の座あらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, '幕屋の他の方すなはちその北の方のためにも板二十枚を作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, '而してこれに銀の座四十を作り此板の下にも二の座彼板の下にも二の座あらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, '幕屋の後すなはちその西の方のために板六枚を造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, '又幕屋の後の兩の隅のために板二枚を造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'その二枚は下にて相合せしめその頂まで一に連ならしむべし一箇の鐶に於て然りその二枚ともに是の如くなるべし其等は二の隅のために設くる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'その板は合て八枚その銀の座は十六座此板にも二の座彼板にも二の座あらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, '汝合歓木をもて横木を作り幕屋の此方の板のために五本を設くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'また幕屋の彼方の板のために横木五本を設け幕屋の後すなはちその西の方の板のために横木五本を設くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, '板の眞中にある中間の横木をば端より端まで通らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, '而してその板に金を着せ金をもて之がために鐶を作りて横木をこれに貫き又その横木に金を着すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, '汝山にて示されしところのその模範にしたがひて幕屋を建べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, '汝また靑紫紅の線および麻の撚絲をもて幕を作り巧にケルビムをその上に織いだすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, '而して金を着たる四本の合歓木の柱の上に之を掛べしその鈎は金にしその柱は四の銀の座の上に置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, '汝その幕を鐶の下に掛け其處にその幕の中に律法の櫃を蔵むべしその幕すなはち汝らのために聖所と至聖所を分たん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, '汝至聖所にある律法の櫃の上に贖罪所を置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, '而してその幕の外に案を置ゑ幕屋の南の方に燈臺を置て案に對はしむべし案は北の方に置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, '又靑紫紅の線および麻の撚絲をもて幔を織なして幕屋の入口に掛べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, '又その幔のために合歓木をもて柱五本を造りてこれに金を着せその鈎を金にすべし又その柱のために銅をもて五箇の座を鋳べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '汝合歓木をもて長五キユビト濶五キユビトの壇を作るべしその壇は四角その高は三キユビトなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'その四隅の上に其の角を作りてその角を其より出しめその壇には銅を着すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, '又灰を受る壷と火鏟と鉢と肉叉と火鼎を作るべし壇の器は皆銅をもて之を作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, '汝壇のために銅をもて金網を作りその網の上にその四隅に銅の鐶を四箇作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, '而してその網を壇の中程の邊の下に置て之を壇の半に達せしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, '又壇のために杠を作るべし即ち合歓木をもて杠を造り銅をこれに着すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'その杠を鐶に貫きその杠を壇の兩旁にあらしめて之を舁べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, '壇は汝板をもて之を空に造り汝が山にて示されしごとくにこれを造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, '汝また幕屋の庭をつくるべし南に向ひては庭のために南の方に長百キユピトの細布の幕を設けてその一方に當べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'その二十の柱およびその二十の座は銅にし其柱の鈎およびその桁は銀にすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, '又北の方にあたりて長百キユビトの幕をその樅に設くべしその二十の柱とその柱の二十の座は銅にし柱の鈎とその桁は銀にすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, '庭の横すなはちその西の方には五十キユビトの幕を設くべしその柱は十その座も十');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'また東に向ひては庭の東の方の濶は五十キユビトにすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, '而して此一旁に十五キユビトの幕を設くべしその柱は三その座も三');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, '又彼一旁にも十五キユビトの幕を設くべしその柱は三その座も三');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, '庭の門のために靑紫紅の線および麻の撚絲をもて織なしたる二十キユビトの幔を設くべしその柱は四その座も四');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, '庭の四周の柱は皆銀の桁をもて続けその鈎を銀にしその座を銅にすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, '庭の樅は百キユビトその横は五十キユビト宛その高は五キユビト麻の撚絲をもてつくりなしその座を銅にすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, '凡て幕屋に用ふるところの諸の器具並にその釘および庭の釘は銅をもて作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, '汝又イスラエルの子孫に命じ橄欖を搗て取たる清き油を燈火のために汝に持きたらしめて絶ず燈火をともすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, '集會の幕屋に於て律法の前なる幕の外にアロンとその子等晩より朝までヱホバの前にその燈火を整ふべし是はイスラエの子孫が世々たえず守るべき定例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '汝イスラエルの子孫の中より汝の兄弟アロンとその子等すなはちアロンとその子ナダブ、アビウ、エレアザル、イタマルを汝に至らしめて彼をして我にむかひて祭司の職をなさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, '汝また汝の兄弟アロンのために聖衣を製りて彼の身に顯榮と榮光あらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, '汝凡て心に智慧ある者すなはち我が智慧の霊を充しおきたる者等に語りてアロンの衣服を製しめ之を用てアロンを聖別て我に祭司の職をなさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, '彼等が製るべき衣服は是なり即ち胸牌エポデ明衣間格の裏衣頭帽および帶彼等汝の兄弟アロンとその子等のために聖衣をつくりて彼をして祭司の職を我にむかひてなすことをえせしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, '即ち彼等金靑紫紅の糸および麻糸をとりて用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, '又金靑紫紅の線および麻の撚糸をもて巧にエポデを織なすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'エポデには二の肩帶をほどこしその兩の端を連ねて之を合すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'エポデの上にありてこれを束ぬるところの帶はその物同うしてエポデの製のごとくにすべし即ち金靑紫紅の糸および麻の撚糸をもてこれを作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, '汝二箇の葱珩をとりてその上にイスラエルの子等の名を鐫つくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, '即ち彼等の誕生にしたがひてその名六を一の玉に鐫りその遺餘の名六を外の玉に鐫べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, '玉に雕刻する人の印を刻が如くに汝イスラエルの子等の名をその二の玉に鐫つけその玉を金の槽に嵌べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'この二の玉をエポデの肩帶の上につけてイスラエルの子等の記念の玉とならしむべし即ちアロン、ヱホバの前において彼等の名をその兩の肩に負て記念とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, '汝金の槽を作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, '而して純金を組て紐の如き二箇の鏈を作りその組る鏈をかの槽につくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, '汝また審判の胸牌を巧に織なしエポデの製のごとくに之をつくるべし即ち金靑紫紅の線および麻の撚糸をもてこれを製るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, '是は四角にして二重なるべく其長は半キユビトその濶も半キユビトなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, '汝またその中に玉を嵌て玉を四行にすべし即ち赤玉黄玉瑪瑙の一行を第一行とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, '第二行は紅玉靑玉金剛石');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, '第三行は深紅玉 白瑪瑙 紫玉');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, '第四行は黄緑玉 葱珩 碧玉 凡て金の槽の中にこれを嵌べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'その玉はイスラエルの子等の名に循ひその名のごとくにこれを十二にすべし而してその十二の支派の各々の名は印を刻ごとくにこれを鐫つくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, '汝純金を紐のごとくに組たる鏈を胸牌の上につくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'また胸牌の上に金の環二箇を作り胸牌の兩の端にその二箇の環をつけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'かの金の紐二條を胸牌の端の二箇の環につくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, '而してその二條の紐の兩の端を二箇の槽に結ひエポデの肩帶の上につけてその前にあらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, '又二箇の金の環をつくりて之を胸牌の兩の端につくべし即ちそのエポデに對ふところの内の邊に之をつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, '汝また金の環二箇を造りてこれをエポデの兩旁の下の方につけその前の方にてその聯接る處に對ひてエポデの帶の上にあらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, '胸牌は靑紐をもてその環によりて之をエポデの環に結ひつけエポデの帶の上にあらしむべし然せば胸牌エポデを離るること無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'アロン聖所に入る時はその胸にある審判の胸牌にイスラエルの子等の名を帶てこれをその心の上に置きヱホバの前に恒に記念とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, '汝審判の胸牌にウリムとトンミムをいれアロンをしてそのヱホバの前に入る時にこれをその心の上に置しむべしアロンはヱホバの前に常にイスラエルの子孫の審判を帶てその心の上に置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'エポデに屬する明衣は凡てこれを靑く作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, '頭をいるる孔はその眞中に設くべし又その孔の周圍には織物の縁をつけて鎧の領盤のごとくになして之を綻びざらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'その裾には靑紫紅の糸をもて石榴をつくりてその裾の周圍につけ又四周に金の鈴をその間々につくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, '即ち明衣の据には金の鈴に石榴又金の鈴に石榴とその周圍につくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'アロン奉事をなす時にこれを著べし彼が聖所にいりてヱホバの前に至る時また出きたる時にはその鈴の音聞ゆべし斯せば彼死ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, '汝純金をもて一枚の前板を作り印を刻がごとくにその上にヱホバに聖と鐫つけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, '之を靑紐につけて頭帽の上にあらしむべし即ち頭帽の前の方にこれをつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, '是はアロンの額にあるべしアロンはイスラエルの子孫が献ぐるところの聖物すなはちその献ぐる諸の聖き供物の上にあるとこるの罪を負べしこの板をば常にアロンの額にあらしむべし是ヱホバの前に其等の受納られんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, '汝麻糸をもて裏衣を間格に織り麻糸をもて頭帽を製りまた帶を繍工に織なすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, '汝またアロンの子等のために裏衣を製り彼らのために帶を製り彼らのために頭巾を製りてその身に顯榮と榮光あらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, '而して汝これを汝の兄弟アロンおよび彼とともなるその子等に着せ膏を彼等に灌ぎこれを立てこれを聖別てこれをして祭司の職を我になさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, '又かれらのためにその陰所を蔽ふ麻の褌を製り腰より髀に達らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'アロンとその子等は集會の幕屋に入る時又は祭壇に近づきて聖所に職事をなす時はこれを著べし斯せば愆をかうむりて死ることなからん是は彼および彼の後の子孫の永く守るべき例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '汝かれらを聖別て彼らをして我にむかひて祭司の職をなさしむるには斯これに爲べし即ち若き牡牛と二の全き牡山羊を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, '無酵パン油を和たる無酵菓子および油を塗たる無酵煎餅を取べし是等は麥粉をもて製るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, '而してこれを一箇の筐にいれ牡牛および二の牡山羊とともにこれをその筐のままに持きたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, '汝またアロンとその子等を集會の幕屋の口に携きたりて水をもてかれらを洗ひ清め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, '衣服をとりて裏衣エポデに屬する明衣エポデおよび胸牌をアロンに着せエポデの帶を之に帶しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, '而してかれの首に頭帽をかむらせその頭帽の上にかの聖金板を戴しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, '灌油を取てこれを彼の首に傾け灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, '又かれの子等を携來りて之に裏衣を着せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, '之に帶を帶しめ頭巾をこれにかむらすべし即ちアロンとその子等に斯なすべし祭司の職はかれらに歸す永くこれを例となすべし汝斯アロンとその子等を立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, '汝集會の幕屋の前に牡牛をひき來らしむべし而してアロンとその子等その牡牛の頭に手を按べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'かくして汝集會の幕屋の口にてヱホバの前にその牡牛を宰すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, '汝その牡牛の血をとり汝の指をもてこれを壇の角に塗りその血をばことごとく壇の下に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, '汝またその臓腑を裏むところの諸の脂肝の上の網膜および二の腎とその上の脂を取てこれを壇の上に燔べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, '但しその牡牛の肉とその皮および糞は營の外にて火に燒べし是は罪祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, '汝かの牡山羊一頭を取るべし而してアロンとその子等その牡山羊の上に手を按べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, '汝その牡山羊を宰しその血をとりてこれを壇の上の周圍に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, '汝その牡山羊を切割きその臓腑とその足を洗ひて之をその肉の塊とその頭の上におくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, '汝その牡山羊を壇の上に悉く燒べし是ヱホバにたてまつる燔祭なり是は馨しき香にしてヱホバにたてまつる火祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, '汝また今一の牡山羊をとるべし而してアロンとその子等その牡山羊の頭の上に手を按べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, '汝すなはちその牡山羊を殺しその血をとりてこれをアロンの右の耳の端およびその子等の右の耳の端につけ又その右の手の大指と右の足の栂指につけその血を壇の周圍に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, '又壇の上の血をとり灌油をとりて之をアロンとその衣服およびその子等とその子等の衣服に灌ぐべし斯彼とその衣服およびその子等とその子等の衣服清淨なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, '汝その牡山羊の脂と脂の尾および其臓腑を裏る脂肝の上の網膜二箇の腎と其上の脂および右の腿を取べし是は任職の牡山羊なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, '汝またヱホバの前にある無酵パンの筐の中よりパン一個と油ぬりたる菓子一箇と煎餅一個を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, '汝これらを悉くアロンの手と其子等の手に授けこれを搖てヱホバに搖祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, '而して汝これらを彼等の手より取て壇の上にて燔祭にくはへて燒くべし是ヱホバの前に馨しき香となるべし是すなはちヱホバにたてまつる火祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, '汝またアロンの任職の牡山羊の胸を取てこれをヱホバの前に搖て搖祭となすべし是汝の受るところの分なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, '汝その搖ところの搖祭の物の胸およびその擧るところの擧祭の物の腿すなはちアロンとその子等の任職の牡山羊の胸と腿を聖別つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, '是はアロンとその子等に歸すべしイスラエルの子孫永くこの例を守るべきなり是はイスラエルの子孫が酬恩祭の犠牲の中よりとるところの擧祭にしてヱホバになすところの擧祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'アロンの聖衣は其後の子孫に歸すべし子孫これを着て膏をそそがれ職に任ぜらるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'アロンの子孫の中彼にかはりて祭司となり集會の幕屋にいりて聖所に職をなす者は先七日の間これを着べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, '汝任職の牡山羊を取り聖所にてその肉を煮べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'アロンとその子等は集會の幕屋の戸口においてその牡山羊の肉と筐の中のパンを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, '罪を贖ふ物すなはち彼らを立て彼らを聖別るに用るところの物を彼らは食ふべし餘の人は食ふべからず其は聖物なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'もし任職の肉あるひはパン旦まで遺りをらばその遺者は火をもてこれを燒べし是は聖ければ食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, '汝わが凡て汝に命ずるごとくにアロンとその子等に斯なすべし即ちかれらのために七日のあひだ任職の禮をおこなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, '汝日々に罪祭の牡牛一頭をささげて贖をなすべし又壇のために贖罪をなしてこれを清めこれに膏を灌ぎこれを聖別べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, '汝七日のあひだ壇のために贖をなして之を聖別め至聖き壇とならしむべし凡て壇に捫る者は聖なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, '汝が壇の上にささぐべき者は是なり即ち一歳の羔二を日々絶ず献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, '一の羔は朝にこれを献げ一の羔は夕にこれを献べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, '一の羔に麥粉十分の一に搗たる油一ヒンの四分の一を和たるを添へ又灌祭として酒一ヒンの四分の一を添べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, '今一の羔羊は夕にこれを献げ朝とおなじき素祭と灌祭をこれと共にささげ馨しき香とならしめヱホバに火祭たらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, '是すなはち汝らが代々絶ず集會の幕屋の門口にてヱホバの前に献ぐべき燔祭なり我其處にて汝等に會ひ汝と語ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, '其處にて我イスラエルの子孫に會ん幕屋はわが榮光によりて聖なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, '我集會の幕屋と祭壇を聖めん亦アロンとその子等を聖めて我に祭司の職をなさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, '我イスラエルの子孫の中に居て彼らの神とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, '彼等は我が彼らの神ヱホバにして彼等の中に住んとて彼等をエジプトの地より導き出せし者なることを知ん我はかれらの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '汝香を焚く壇を造るべし即ち合歓木をもてこれを造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'その長は一キユビトその寛も一キユビトにして四角ならしめ其高は三キユビトにし其角は其より出しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, '而してその上その四傍その角ともに純金を着せその周圍に金の縁を作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, '汝またその兩面に金の縁の下に金の環二箇を之がために作るべし即ちその兩傍にこれを作るべし是すなはちこれを舁ところの杠を貫く所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'その杠は合歓木をもてこれを作りて之に金を着すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, '汝これを律法の櫃の傍なる幕の前に置て律法の上なる贖罪所に對はしむべし其處はわが汝に會ふ處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'アロン朝ごとにその上に馨しき香を焚べし彼燈火を整ふる時はその上に香を焚べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'アロン夕に燈火を燃す時はその上に香を焚べし是香はヱホバの前に汝等が代々絶すべからざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, '汝等その上に異る香を焚べからず燔祭をも素祭をも獻ぐべからず又その上に灌祭の酒を灌ぐべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'アロン年に一回贖罪の罪祭の血をもてその壇の角のために贖をなすべし汝等代々年に一度是がために贖をなすべし是はヱホバに最も聖き者たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '汝がイスラエルの子孫の數を數へしらぶるにあたりて彼等は各人その數へらるる時にその生命の贖をヱホバにたてまつるべし是はその數ふる時にあたりて彼等の中に災害のあらざらんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, '凡て數へらるる者の中に入る者は聖所のシケルに遵ひて半シケルを出すべし一シケルは二十ゲラなり即ち半シケルをヱホバにたてまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, '凡て數へらるる者の中に入る者即ち二十歳以上の者はヱホバに献納物をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, '汝らの生命を贖ふためにヱホバに献納物をなすにあたりては富者も半シケルより多く出すべからず貧者も其より少く出すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, '汝イスラエルの子孫より贖の金を取てこれを幕屋の用に供ふべし是はヱホバの前にイスラエルの子孫の記念となりて汝ら生命を贖ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '汝また銅をもて洗盤をつぐりその臺をも銅になして洗ふことのために供へ之を集會の幕屋と壇との間に置てその中に水をいれおくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'アロンとその子等はそれに就て手と足を洗ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, '彼等は集會の幕屋に入る時に水をもて洗ふことを爲て死をまぬかるべし亦壇にちかづきてその職をなし火祭をヱホバの前に焚く時も然すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, '即ち斯その手足を洗ひて死を免かるべし是は彼とその子孫の代々常に守るべき例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'ヱホバまたモーセに言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '汝また重立たる香物を取れ即ち淨沒薬五百シケル香しき肉桂その半二百五十シケル香しき菖蒲二百五十シケル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, '桂枝五百シケルを聖所のシケルに遵ひて取り又橄欖の油ヒンを取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, '汝これをもて聖灌膏を製るべしすなはち薫物を製る法にしたがひて香膏を製るべし是は聖灌膏たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, '汝これを集會の幕屋と律法の櫃に塗り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, '案とそのもろもろの器具燈臺とそのもろもろの器具および香壇');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, '並に燔祭の壇とそのもろもろの器具および洗盤とその臺とに塗べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, '汝是等を聖めて至聖らしむべし凡てこれに捫る者は聖くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, '汝アロンとその子等に膏をそそぎて之を立て彼らをして我に祭司の職をなさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, '汝イスラエルの子孫に告ていふべし是は汝らが代々我の爲に用ふべき聖灌膏なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, '是は人の身に灌ぐべからず汝等また此量をもて是に等き物を製るべからず是は聖し汝等これを聖物となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, '凡て之に等き物を製る者凡てこれを餘人につくる者はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'ヱホバ、モーセに言たまはく汝ナタフ、シケレテ、へルベナの香物を取りその香物を淨き乳香に和あはすべしその量は各等からしむべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, '汝これを以て香を製るべし即ち薫物を製る法にしたがひてこれをもて薫物を製り鹽をこれにくはへ潔く且聖らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, '汝またその幾分を細に搗て我が汝に會ふところなる集會の幕屋の中にある律法の前にこれを供ふべし是は汝等において最も聖き者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, '汝が製るところの香は汝等その量をもてこれを自己のために製るべからず是は汝においてヱホバのために聖き者たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, '凡て是に均き者を製りてこれを嗅ぐ者はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'ヱホバ、モーセに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '我ユダの支派のホルの子なるウリの子ベザレルを名指て召し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, '神の霊をこれに充して智慧と了知と智識と諸の類の工に長しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, '奇巧を盡して金銀及び銅の作をなすことを得せしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, '玉を切り嵌め木に彫刻みて諸の類の工をなすことを得せしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, '視よ我またダンの支派のアヒサマクの子アホリアブを與へて彼とともならしむ凡て心に智ある者に我智慧を授け彼等をして我が汝に命ずる所の事を盡くなさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, '即ち集會の幕屋律法の櫃その上の贖罪所幕屋の諸の器具');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, '案ならびにその器具純金の燈臺とその諸の器具および香壇');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, '燔祭の壇とその諸の器具洗盤とその臺');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, '供職の衣服祭司の職をなす時に用ふるアロンの聖衣およびその子等の衣服');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'および灌膏ならびに聖所の馨しき香是等を我が凡て汝に命ぜしごとくに彼等製造べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'ヱホバ、モーセに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '汝イスラエルの子孫に告て言べし汝等かならず吾安息日を守るべし是は我と汝等の間の代々の徴にして汝等に我の汝等を聖からしむるヱホバなるを知しむる爲の者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, '即ち汝等安息日を守るべし是は汝等に聖日なればなり凡て之を瀆す者は必ず殺さるべし凡てその日に働作をなす人はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, '六日の間業をなすべし第七日は大安息にしてヱホバに聖なり凡て安息日に働作をなす者は必ず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, '斯イスラエルの子孫は安息日を守り代々安息日を祝ふべし是永遠の契約なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, '是は永久に我とイスラエルの子孫の間の徴たるなり其はヱホバ六日の中に天地をつくりて七日に休みて安息に入たまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'ヱホバ、シナイ山にてモーセに語ることを終たまひし時律法の板二枚をモーセに賜ふ是は石の板にして神が手をもて書したまひし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, '茲に民モーセが山を下ることの遅きを見民集りてアロンの許に至り之に言けるは起よ汝われらを導く神を我儕のために作れ其は我らをエジプトの國より導き上りし彼モーセ其人は如何になりしか知ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'アロンかれらに言けるは汝等の妻と息子息女等の耳にある金の環をとりはづして我に持きたれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, '是において民みなその耳にある金の環をとりはづしてアロンの許に持來りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'アロンこれを彼等の手より取り鎚鑿をもて之が形を造りて犢を鋳なしたるに人々言ふイスラエルよ是は汝をエジプトの國より導きのぼりし汝の神なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'アロンこれを見てその前に壇を築き而してアロン宣告て明日はヱホバの祭禮なりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, '是において人衆明朝早く起いでて燔祭を献げ酬恩祭を供ふ民坐して飮食し起て戯る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'ヱホバ、モーセに言たまひけるは汝往て下れよ汝がエジプトの地より導き出せし汝の民は惡き事を行ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, '彼等は早くも我が彼等に命ぜし道を離れ己のために犢を鋳なしてそれを拝み其に犠牲を献げて言ふイスラエルよ是は汝をエジプトの地より導きのぼりし汝の神なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'ヱホバまたモーセに言たまひけるは我この民を觀たり視よ是は項の強き民なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, '然ば我を阻るなかれ我かれらに向ひて怒を發して彼等を滅し盡さん而して汝をして大なる國をなさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'モ−セその神ヱホバの面を和めて言けるはヱホバよ汝などて彼の大なる權能と強き手をもてエジプトの國より導きいだしたまひし汝の民にむかひて怒を發したまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, '何ぞエジプト人をして斯言しむべけんや曰く彼は禍をくだして彼等を山に殺し地の面より滅し盡さんとて彼等を導き出せしなりと然ば汝の烈き怒を息め汝の民にこの禍を下さんとせしを思ひ直したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, '汝の僕アブラハム、イサク、イスラエルを憶ひたまへ汝は自己さして彼等に誓ひて我天の星のごとくに汝等の子孫を増し又わが言ところの比地をことごとく汝等の子孫にあたへて永くこれを有たしめんと彼等に言たまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'ヱホバ是においてその民に禍を降んとせしを思ひ直したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'モーセすなはち身を轉して山より下れりかの律法の二枚の板その手にあり此板はその兩面に文字あり即ち此面にも彼面にも文字あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, '此板は神の作なりまた文字は神の書にして板に彫つけてあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'ヨシユア民の呼はる聲を聞てモーセにむかひ營中に戰爭の聲すと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'モーセ言ふ是は勝鬨の聲にあらず又敗北の號呼聲にもあらず我が聞ところのものは歌唱ふ聲なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, '斯てモ−セ營に近づくに及びて犢と舞跳を見たれば怒を發してその手よりかの板を擲ちこれを山の下に碎けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, '而して彼等が作りし犢をとりてこれを火に燒き碎きて粉となしてこれを水に撒きイスラエルの子孫に之をのましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'モーセ、アロンに言けるは此民汝に何をなしてか汝かれらに大なる罪を犯させしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'アロン言けるは吾主よ怒を發したまふ勿れ此民の惡なるは汝の知ところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, '彼等われに言けらく我らを導く神をわれらのために作れ其は我らをエジプトの國より導き上りし彼モーセ其人は如何になりしか知ざればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, '是において我凡て金をもつ者はそれをとりはづせと彼等に言ければ則ちそれを我に與へたり我これを火に投たれば此犢出きたれりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'モーセ民を視るに縦肆に事をなすアロン彼等をして縦肆に事をなさしめたれば彼等はその敵の中に嘲笑となれるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, '茲にモーセ營の門に立ち凡てヱホバに歸する者は我に來れと言ければレビの子孫みな集りてかれに至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'モーセすなはち彼等に言けるはイスラエルの神ヱホバ斯言たまふ汝等おのおの劍を横たへて門より門と營の中を彼處此處に行めぐりて各人その兄弟を殺し各人その伴侶を殺し各人その隣人を殺すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'レビの子孫すなはちモーセの言のごとくに爲たればその日民凡三千人殺されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, '是に於てモーセ言ふ汝等おのおのその子をもその兄弟をも顧ずして今日ヱホバに身を献げ而して今日福祉を得よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, '明日モーセ民に言けるは汝等は大なる罪を犯せり今我ヱホバの許に上りゆかんとす我なんちらの罪を贖ふを得ることもあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'モーセすなはちヱホバに歸りて言けるは嗚呼この民の罪は大なる罪なり彼等は自己のために金の神を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, '然どかなはば彼等の罪を赦したまへ然ずば願くは汝の書しるしたまへる書の中より吾名を抹さりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'ヱホバ、モーセに言たまひけるは凡てわれに罪を犯す者をば我これをわが書より抹さらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, '然ば今往て民を我が汝につげたる所に導けよ吾使者汝に先だちて往ん但しわが罰をなこなふ日には我かれらの罪を罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'ヱホバすなはち民を撃たまへり是はかれら犢を造りたるに因る即ちアロンこれを造りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, '茲にヱホバ、モーセに言たまひけるは汝と汝がエジプトの國より導き上りし民此を起いでて我がアブラハム、イサク、ヤコブに誓ひて之を汝の子孫に與へんと言しその地に上るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, '我一の使を遣して汝に先だたしめん我カナン人アモリ人ヘテ人ペリジ人ヒビ人ヱブス人を逐はらひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'なんぢらをして乳と蜜の流るる地にいたらしむべし我は汝の中にをりては共に上らじ汝は項の強き民なれば恐くは我途にて汝を滅すにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, '民この惡き告を聞て憂へ一人もその妝飾を身につくる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'ヱホバ、モーセに言たまひけるはイスラエルの子孫に言へ汝等は項の強き民なり我もし一刻も汝の中にありて往ば汝を滅すにいたらん然ば今汝らの妝飾を身より取すてよ然せば我汝に爲べきことを知んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, '是をもてイスラエルの子孫ホレブ山より以來はその妝飾を取すてて居ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'モーセ幕屋をとりてこれを營の外に張て營と遥に離れしめ之を集會の幕屋と名けたり凡てヱホバに求むることのある者は出ゆきて營の外なるその集會の幕屋にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'モーセの出て幕屋にいたる時には民みな起あがりてモーセが幕屋にいるまで各々その天幕の門口に立てかれを見る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'モーセ幕屋にいれば雲の柱くだりて幕屋の門口に立つ而してヱホバ、モーセとものいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, '民みな幕屋の門口に雲の柱の立つを見れば民みな起て各人その天幕の門口にて拝をなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, '人がその友に言談ごとくにヱホバ、モーセと面をあはせてものいひたまふモーセはその天幕に歸りしがその僕なる少者ヌンの子ヨシユアは幕屋を離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, '茲にモーセ、ヱホバに言けるは視たまへ汝はこの民を導き上れと我に言たまひながら誰を我とともに遣したまふかを我にしらしめたまはず汝かつて言たまひけらく我名をもて汝を知る汝はまた我前に恩を得たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, '然ば我もし誠に汝の目の前に恩を得たらば願くは汝の道を我に示して我に汝を知しめ我をして汝の目の前に恩を得せしめたまへ又汝この民の汝の有なるを念たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'ヱホバ言たまひけるは我親汝と共にゆくべし我汝をして安泰にならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'モーセ、ヱホバに言けるは汝もしみづから行たまはずは我等を此より上らしめたまふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, '我と汝の民とが汝の目の前に恩を得ることは如何にして知るべきや是汝が我等とともに往たまひて我と汝の民とが地の諸の民に異る者となるによるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'ヱホバ、モーセに言たまひけるは汝が言るこの事をも我爲ん汝はわが目の前に恩を得たればなり我名をもて汝を知なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'モーセ願くは汝の榮光を我に示したまへと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'ヱホバ言たまはく我わが諸の善を汝の前に通らしめヱホバの名を汝の前に宣ん我は惠んとする者を惠み憐まんとする者を憐むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, '又言たまはく汝はわが面を見ることあたはず我を見て生る人あらざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, '而してヱホバ言たまひけるは視よ我が傍に一の處あり汝磐の上に立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, '吾榮光其處を過る時に我なんぢを磐の穴にいれ我が過る時にわが手をもて汝を蔽はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, '而してわが手を除る時に汝わが背後を見るべし吾面は見るべきにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, '茲にヱホバ、モーセに言たまひけるは汝石の板二枚を前のごとくに斫て作れ汝が碎きし彼の前の板にありし言を我その板に書さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, '詰朝までに準備をなし朝の中にシナイ山に上り山の嶺に於て吾前に立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, '誰も汝とともに上るべからず又誰も山の中に居べからず又その山の前にて羊や牛を牧ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'モーセすなはち石の板二枚を前のごとくに斫て造り朝早く起て手に二枚石の板をとりヱホバの命じたまひしごとくにシナイ山にのぼりゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'ヱホバ雲の中にありて降り彼とともに其處に立ちてヱホバの名を宣たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'ヱホバすなはち彼の前を過て宣たまはくヱホバ、ヱホバ憐憫あり恩惠あり怒ることの遅く恩惠と眞實の大なる神');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, '恩惠を千代までも施し惡と過と罪とを赦す者又罰すべき者をば必ず赦すことをせず父の罪を子に報い子の子に報いて三四代におよぼす者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'モーセ急ぎ地に躬を鞠めて拝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, '言けるはヱホバよ我もし汝の目の前に恩を得たらば願くは主我等の中にいまして行たまへ是は項の強き民なればなり我等の惡と罪を赦し我等を汝の所有となしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'ヱホバ言たまふ視よ我契約をなす我未だ全地に行はれし事あらず何の國民の中にも行はれし事あらざるところの奇跡を汝の總躰の民の前に行ふべし汝が住ところの國の民みなヱホバの所行を見ん我が汝をもて爲ところの事は怖るべき者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, '汝わが今日汝に命ずるところの事を守れ視よ我アモリ人カナン人ヘテ人ペリジ人ヒビ人ヱブス人を汝の前より逐はらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, '汝みづから愼め汝が往ところの國の居民と契約をむすぶべからず恐くは汝の中において機檻となることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, '汝らかへつて彼等の祭壇を崩しその偶像を毀ちそのアシラ像を斫たふすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, '汝は他の神を拝むべからず其はヱホバはその名を嫉妒と言て嫉妒神たればたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, '然ば汝その地の居民と契約を結ぶべからず恐くは彼等がその神々を慕ひて其と姦淫をおこなひその神々に犠牲をささぐる時に汝を招きてその犠牲に就て食はしむる者あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, '又恐くは汝かれらの女子等を汝の息子等に妻すことありて彼等の女子等その神々を慕ひて姦淫を行ひ汝の息子等をして彼等の神々を慕て姦淫をおこなはしむるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, '汝おのれのために神々を鋳なすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, '汝無酵パンの節筵を守るべし即ち我が汝に命ぜしごとくアビブの月のその期におよびて七日の間無酵パンを食ふべし其は汝アビブの月にエジプトより出たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, '首出たる者は皆吾の所有なり亦汝の家畜の首出の牡たる者も牛羊ともに皆しかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, '但し驢馬の首出は羔羊をもて贖ふべし若し贖はずばその頸を折べし汝の息子の中の初子は皆贖ふべし我前に空手にて出るものあるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, '六日の間汝働作をなし第七日に休むべし耕耘時にも収穫時にも休むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, '汝七週の節筵すなはち麥秋の初穂の節筵を爲し又年の終に収蔵の節筵をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, '年に三回汝の男子みな主ヱホバ、イスラエルの神の前に出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, '我國々の民を汝の前より逐はらひて汝の境を廣くせん汝が年に三回のぼりて汝の神ヱホバのまへに出る時には誰も汝の國を取んとする者あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, '汝わが犠牲の血を有酵パンとともに供ふべからず又逾越の節の犠牲は明朝まで存しおくべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, '汝の土地の初穂の初を汝の神ヱホバの家に携ふべし汝山羊羔をその母の乳にて煮べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, '斯てヱホバ、モーセに言たまひけるは汝是等の言語を書しるせ我是等の言語をもて汝およびイスラエルと契約をむすべばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, '彼はヱホバとともに四十日四十夜其處に居しが食物をも食ず水をも飮ざりきヱホバその契約の詞なる十誡をかの板の上に書したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'モーセその律法の板二枚を己の手に執てシナイ山より下りしがその山より下りし時にモーセはその面の己がヱホバと言ひしによりて光を發つを知ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'アロンおよびイスラエルの子孫モーセを見てその面の皮の光を發つを視怖れて彼に近づかざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'モーセかれらを呼りアロンおよび會衆の長等すなはちモーセの所に歸りたればモーセ彼等と言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, '斯ありて後イスラエルの子孫みな近よりければモーセ、ヱホバがシナイ山にて己に告たまひし事等を盡くこれに諭せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'モーセかれらと語ふことを終て覆面帕をその面にあてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, '但しモーセはヱホバの前にいりてともに語ることある時はその出るまで覆面帕を除きてをりまた出きたりてその命ぜられし事をイスラエルの子孫に告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'イスラエルの子孫モーセの面を見るにモーセの面の皮光を發つモーセは入てヱホバと言ふまでまたその覆面帕を面にあてをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'モーセ、イスラエルの子孫の會衆を盡く集てこれに言ふ是はヱホバが爲せと命じたまへる言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, '即ち六日の間は働作を爲べし第七日は汝等の聖日ヱホバの大安息日なり凡てこの日に働作をなす者は殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, '安息日には汝等の一切の住處に火をたく可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'モーセ、イスラエルの子孫の會衆に徧く告て言ふ是はヱホバの命じたまへるところの事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, '曰く汝等が有る物の中より汝等ヱホバに献ぐる者を取べし凡て心より願ふ者に其を携へきたりてヱホバに献ぐべし即ち金 銀 銅');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, '靑 紫 紅の線 麻糸 山羊の毛');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, '赤染の牡羊の皮 貛の皮 合歓木');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, '燈油 灌膏と馨しき香をつくる香物');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, '葱珩 エポデと胸牌に嵌る玉');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, '凡て汝等の中の心に智慧ある者來りてヱホバの命じたまひし者を悉く造るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, '即ち幕屋その天幕その頂蓋その鈎その版その横木その柱その座');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'かの櫃とその杠 贖罪所 障蔽の幕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, '案子とその杠およびその諸の器具供前のパン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, '燈明の臺その器具とその盞および燈火の油');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, '香壇とその杠 灌膏 馨しき香 幕屋の入口の幔');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, '燔祭の壇およびその銅の網その杠その諸の器具洗盤とその臺');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, '庭の幕その柱その座庭の口の幔');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, '幕屋の釘庭の釘およびその紐');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, '聖所にて職をなすところの供職の衣即ち祭司の職をなす時に用ふる者なる祭司アロンの聖衣および其子等の衣服');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, '斯てイスラエルの子孫の會衆みなモーセの前を離れて去しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, '凡て心に感じたる者凡て心より願ふ者は來りてヱホバへの献納物を携へいたり集會の幕屋とその諸の用に供へ又聖衣のために供へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, '即ち凡て心より願ふ者は男女ともに環釦 耳環 指環 頸玉 諸の金の物を携へいたれり又凡て金の献納物をヱホバに爲す者も然せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, '凡て靑 紫 紅の線および麻絲 山羊の毛 赤染の牡羊の皮 貛の皮ある者は是を携へいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, '凡て銀および銅の献納物をなす者はこれを携へきたりてヱホバに献げ又物を造るに用ふべき合歓木ある者は其を携へいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'また凡て心に智慧ある婦女等はその手をもて紡ぐことをなしその紡ぎたる者なる靑紫 紅の線および麻絲を携へきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, '凡て智慧ありて心に感じたる婦人は山羊の毛を紡げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, '又長たる者どもは葱珩およびエポデと胸牌に嵌べき玉を携へいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, '燈火と灌膏と馨しき香とに用ふる香物と油を携へいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, '斯イスラエルの子孫悦んでヱホバに獻納物をなせり即ちヱホバがモーセに藉て爲せと命じたまひし諸の工事をなさしむるために物を携へきたらんと心より願ふところの男女は皆是のごとくになしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'モーセ、イスラエルの子孫に言ふ視よヱホバ、ユダの支派のホルの子なるウリの子ベザレルを名指て召たまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, '神の霊をこれに充して智慧と了知と知識と諸の類の工事に長しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, '奇巧を盡して金銀および銅の作をなすことを得せしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, '玉を切り嵌め木に彫刻みて諸の類の工をなすことを得せしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, '彼の心を明かにして敎ふることを得せしめたまふ彼とダンの支派のアヒサマクの子アホリアブ倶に然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, '斯智慧の心を彼等に充して諸の類の工事をなすことを得せしめたまふ即ち彫刻文織および靑紫紅の絲と麻絲の刺繍並に機織等凡て諸の類の工をなすことを得せしめ奇巧をこれに盡さしめたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, '偖ベザレルとアホリアブおよび凡て心の頴敏き人即ちヱホバが智慧と了知をあたへて聖所の用に供ふるところの諸の工をなすことを知得せしめたまへる者等はヱホバの凡て命じたまひし如くに事をなすべかりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'モーセすなはちベザレルとアホリアブおよび凡て心の頴敏き人すなはちその心にヱホバが智慧をさづけたまひし者凡そ來りてその工をなさんと心に望ところの者を召よせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, '彼等は聖所の用にそなふるところの工事をなさしむるためにイスラエルの子孫が携へきたりし諸の献納物をモーセの手より受とりしが民は尚また朝ごとに自意の献納物をモーセに持きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, '是に於て聖所の諸の工をなすところの智き人等みな各々その爲ところの工をやめて來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'モーセに告て言けるは民餘りに多く持きたればヱホバが爲せと命じたまひし工事をなすに用ふるに餘ありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'モーセすなはち命を傳へて營中に宣布しめて云く男女ともに今よりは聖所に獻納物をなすに及ばずと是をもて民は携へきたることを止たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, '其はその有ところの物すでに一切の工をなすに足て且餘あればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, '偖彼等の中心に智慧ありてその工を爲るところの者十の幕をもて幕屋を造れりその幕は麻の撚糸と靑紫紅の絲をもて巧にケルビムを織なして作れる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'その幕は各々長二十八キユビトその幕は各寛四キユビトその幕はみな寸尺一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, '而してその幕五箇を互に連ねあはせ又その幕五箇をたがひに連ねあはせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, '一聯の幕の邊においてその連絡處の端に靑色の襟を造り又他の一聯の幕の邊においてその連絡處にこれを造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, '一聯の幕に襟五十をつくりまた他の一聯の幕の連絡處の邊にも襟五十をつくれりその襟は彼と此と相對す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, '而して金の鈎五十をつくりその鈎をもてその幕を彼と此と相連ねたれば一箇の幕屋となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, '又山羊の毛をもて幕をつくりて幕屋の上の天幕となせりその造れる幕は十一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'その幕は各々長三十キユビトその幕はおのおの寛四キユビトにして十一の幕は寸尺同一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'その幕五を一幅に連ねまたその幕六を一幅に連ね');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'その幕の邊において連絡處に襟五十をつくり又次の一連の幕の邊にも襟五十をつくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, '又銅の鈎五十をつくりてその天幕をつらねあはせて一とならしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, '赤染の牡羊の皮をもてその天幕の頂蓋をつくりてその上に貛の皮の蓋を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, '又合歓木をもて幕屋の竪板をつくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, '板の長は十キユビト板の寛は一キユビト半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, '一の板に二の榫ありて彼と此と交指ふ幕屋の板には皆かくのごとく造りなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, '又幕屋のために板を作れり即ち南に於は南の方に板二十枚');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'その二十枚の板の下に銀の座四十をつくれり即ち此板の下にも二の座ありてその二の榫を承け彼板の下にも二の座ありてその二の榫を承く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, '幕屋の他の方すなはちその北の方のためにも板二十枚を作り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, '又その銀の座四十をつくれり即ち此板の下にも二の座あり彼板の下にも二の座あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, '又幕屋の後面すなはちその西のために板六枚をつくり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, '幕屋の後の兩隅のために板二枚宛をつくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'その二枚は下にて相合しその頂まで一に連なれり一箇の環に於て然りその二枚ともに是のごとし是等は二隅のために設けたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'その板は八枚ありその座は銀の座十六座あり各々の板の下に二の座あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, '又合歓木をもて横木を作れり即ち幕屋の此方の板のために五本を設け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, '幕屋の彼方の板のために横木五本を設け幕屋の後すなはちその西の板のために横木五本を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, '又中間の横木をつくりて板の眞中において端より端まで通らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, '而してその板に金を着せ金をもて之がために鐶をつくりて横木をこれに貫き又その横木に金を着たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, '又靑紫紅の絲および麻の撚絲をもて幕をつくり巧にケルビムをその上に織いだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'それがために合歓木をもて四本の柱をつくりてこれに金を着せたりその鈎は金なり又銀をもてこれがために座四を鋳たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, '又靑紫紅の絲および麻の撚絲をもて幕屋の入口に掛る幔を織なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'その五本の柱とその鈎とを造りその柱の頭と桁に金を着せたり但しその五の座は銅なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'ベザレル合歓木をもて櫃をつくれりその長は二キユビト半その寛は一キユビト半、その高は一キユビト半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, '而して純金をもてその内外を蔽ひてその上の周圍に金の縁を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, '又金の環四箇を鋳てその四の足につけたり即ち此旁に二箇の輪彼旁に二箇の輪を付く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, '又合歓木をもて杠を作りてこれに金を着せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'その杠を櫃の傍の環にさしいれて之をもて櫃をかくべからしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, '又純金をもて贖罪所を造れりその長は二キユビト半その寛は一キユビト半なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, '又金をもて二箇のケルビムを作れり即ち槌にて打て之を贖罪所の兩傍に作り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, '一箇のケルブを此方の末に一箇のケルブを彼方の末に置り即ち贖罪所の兩傍にケルビムを作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'ケルビムは翼を高く展べ其翼をもて贖罪所を掩ひ其面をたがひに相向く即ちケルビムの面は贖罪所に向ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, '又合歓木をもて案を作れり其長は二キユビト其寛は二キユビト其高は一キユビト半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, '而て純金を之に着せ其周圍に金の縁をつけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, '又其四圍に掌寛の邊を作り其邊の周圍に金の小縁を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, '而て之が爲に金の環四箇を鋳其足の四隅に其環を付たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, '即ち環は邊の側に在て案を舁く杠を入る處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, '而て合歓木をもて案を舁く杠を作りて之に金を着せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, '又案の上の器具即ち皿匙杓及び酒を灌ぐ斝を純金にて作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, '又純金をもて一箇の燈臺を造れり即ち槌をもて打て其燈臺を作れり其臺座軸萼節及び花は其に連る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, '六の枝その旁より出づ即ち燈臺の三の枝は此旁より出で燈臺の三の枝は彼傍より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, '巴旦杏の花の形せる三の萼節および花とともに此枝にあり又巴旦杏の花の形せる三の萼節および花とともに彼枝にあり燈臺より出る六の枝みな斯のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, '巴旦杏の花の形せる四の萼その節および花とともに燈臺にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, '兩箇の枝の下に一箇の節あり又兩箇の枝の下に一箇の節あり又兩箇の枝の下に一箇の節あり燈臺より出る六の枝みな是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'その節と枝とは其に連れり皆槌にて打て純金をもて造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, '又純金をもて七箇の燈盞と燈鉗と剪燈盤を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, '燈臺とその諸の器具は純金一タラントをもて作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, '又合歓木をもて香壇を造れり其長一キユピトその寛二キユビトにして四角なりその高は二キユビトにしてその角は其より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'その上その四旁その角ともに純金を着せその周圍に金の縁を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, '又その兩面に金の縁の下に金の環二箇をこれがために作れり即ちその兩旁にこれを作る是すなはち之を舁ところの杠を貫くところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, '又合歓木をもてその杠をつくりて之に金を着せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, '又薫物をつくる法にしたがひて聖灌膏と香物の清き香とを製れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, '又合歓木をもて燔祭の壇を築けりその長は五キユビト其寛は五キユビトにして四角その高は三キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, '而してその四隅の上に其の角を作りてその角を其より出しめその壇には銅を着せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, '又その壇の諸の器具すなはち壷と火鏟と鉢と肉叉と火鼎を作れり壇の器はみな銅にて造る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, '又壇のために銅の網をつくりこれを壇の中程の邊の下に置ゑて壇の半に達せしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'その銅の網の四隅に四箇の環を鋳て杠を貫く處となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, '合歓木をもてその杠をつくりて之に銅を着せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, '壇の兩旁の環にその杠をつらぬきて之を舁べからしむその壇は板をもてこれを空につくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'また銅をもで洗盤をつくりその臺をも銅にす即ち集會の幕屋の門にて役事をなすところの婦人等鏡をもて之を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, '又庭を作れり南に於ては庭の南の方に百キユビトの細布の幕を設く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'その柱は二十その座は二十にして共に銅なりその柱の鈎および桁は銀なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, '北の方には百キユビトの幕を設くその柱は二十その座は二十にして共に銅なりその柱の鈎と桁は銀なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, '西の方には五十キユビトの幕を設くその柱は十その座は十その柱の鈎と桁は銀なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, '東においては東の方に五十キユビトの幕を設く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, '而してこの一旁に十五キユビトの幕を設くその柱は三その座も三');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, '又かの一旁にも十五キユビトの幕を設くその柱は三その座も三即ち庭の門の此旁彼旁ともに然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, '庭の周圍の幕はみな細布なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, '柱の座は銅柱の鈎と桁は銀柱の頭の包は銀なり庭の柱はみな銀の桁にて連る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, '庭の門の幔は靑紫紅の絲および麻の撚絲をもて織なしたる者なりその長は二十キユビトその寛における高は五キユビトにして庭の幕と等し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'その柱は四その座は四にして共に銅その鈎は銀その頭の包と桁は銀なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, '幕屋およびその周圍の庭の釘はみな銅なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, '幕屋につける物すなはち律法の幕屋につける物を量るに左のごとし祭司アロンの子イタマル、モーセの命にしたがひてレビ人を率ゐ用ひてこれを量れるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'ユダの支派のホルの子なるウリの子ベザレル凡てヱホバのモーセに命じたまひし事等をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'ダンの支派のアヒサマクの子アホリアブ彼とともにありて雕刻織文をなし靑紫紅の絲および麻絲をもて文繍をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, '聖所の諸の工作をなすに用たる金は聖所のシケルにしたがひて言ば都合二十九タラント七百三十シケルなり是すなはち献納たるところの金なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, '會衆の中の核數られし者の献げし銀は聖所のシケルにしたがひて言ば百タラント千七百七十五シケルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, '凡て數らるる者の中に入し者即ち二十歳以上の者六十萬三千五百五十人ありたれば聖所のシケルにしたがひて言ば一人に一ベカとなる是すなはち半シケルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, '百タラントの銀をもて聖所の座と幕の座を鋳たり百タラントをもて百座をつくれば一座すなはち一タラントなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, '又千七百七十五シケルをもて柱の鈎をつくり柱の頭を包み又柱を連ねあはせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, '又獻納たるところの銅は七十タラント二千四百シケルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, '是をもちひて集會の幕屋の門の座をつくり銅の壇とその銅の網および壇の諸の器具をつくり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, '庭の周圍の座と庭の門の座および幕屋の諸の釘と庭の周圍の諸の釘を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, '靑紫紅の絲をもて聖所にて職をなすところの供職の衣服を製り亦アロンのために聖衣を製りヱホバのモーセに命じたまひしごとくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, '又金靑紫紅の絲および麻の撚絲をもてエポデを製り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, '金を薄片に打展べ剪て縷となしこれを靑紫 紅の絲および麻絲に和てこれを織なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, '又これがために肩帶をつくりて之を連ねその兩の端において之を連ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'エポデの上にありて之を束ぬるところの帶はその物同じうして其の製のごとし即ち金靑紫紅の絲および麻の撚絲をもて製る者なりヱホバのモーセに命じたまひしごとくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, '又葱珩を琢て金の槽に嵌め印を刻がごとくにイスラエルの子等の名をこれに鐫つけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'これをエボデの肩帶の上につけてイスラエルの子孫の記念の玉とならしむヱホバのモーセに命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'また胸牌を巧に織なしエポデの製のごとくに金靑紫紅の絲および麻の撚絲をもてこれを製れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, '胸牌は四角にして之を二重につくりたれば二重にしてその長半キユビトその濶半キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'その中に玉四行を嵌む即ち赤玉黄玉瑪瑙の一行を第一行とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, '第二行は紅玉 靑玉 金剛石');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, '第三行は深紅玉 白瑪瑙 紫玉');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, '第四行は黄緑玉 葱珩 碧玉 凡て金の槽の中にこれを嵌たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'その玉はイスラエルの子等の名にしたがひ其名のごとくに之を十二になし而して印を刻がごとくにその十二の支派の各の名をこれに鐫つけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, '又純金を紐のごとくに組たる鏈を胸牌の上につけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, '又金をもて二箇の槽をつくり二の金の環をつくりその二の環を胸牌の兩の端につけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'かの金の紐二條を胸牌の端の二箇の環につけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, '而してその二條の紐の兩の端を二箇の槽に結ひエポデの肩帶の上につけてその前にあらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, '又二箇の金の環をつくりて之を胸牌の兩の端につけたり即ちそのエポデに對ふところの内の邊にこれを付く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'また金の環二箇を造りてこれをエポデの兩傍の下の方につけてその前の方にてその聯接る處に對てエポデの帶の上にあらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, '胸牌は靑紐をもてその環によりて之をエポデの環に結つけエポデの帶の上にあらしめ胸牌をしてエポデを離るることなからしむヱホバのモーセに命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, '又エポデに屬する明衣は凡てこれを靑く織なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, '上衣の孔はその眞中にありて鎧の領盤のごとしその孔の周圍に縁ありて綻びざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, '而して明衣の裾に靑紫紅の撚絲をもて石榴を作りつけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, '又純金をもて鈴をつくりその鈴を明衣の裾の石榴の間につけ周圍において石榴の間々にこれをつけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, '即ち鈴に石榴鈴に石榴と供職の明衣の裾の周圍につけたりヱホバのモーセに命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, '又アロンとその子等のために織布をもて裏衣を製り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, '細布をもて頭帽を製り細布をもて美しき頭巾をつくり麻の撚絲をもて褌をつくり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, '麻の撚絲および靑紫紅の絲をもて帶を織なせりヱホバのモーセに命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, '又純金をもて聖冠の前板をつくり印を刻がごとくにその上にヱホバに聖といふ文字を書つけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, '之に靑紐をつけて之を頭帽の上に結つけたりヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, '斯集合の天幕なる幕屋の諸の工事成ぬイスラエルの子孫ヱホバの凡てモーセに命じたまひしごとくに爲て斯おこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, '人衆幕屋と天幕とその諸の器具をモーセの許に携へいたる即ちその鈎その板その横木その柱その座');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, '赤染の牡羊の皮の蓋貛の皮の蓋障蔽の幕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, '律法の櫃とその杠贖罪所');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, '案とその諸の器具供前のパン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, '純金の燈臺とその盞すなはち陳列る燈盞とその諸の器具ならびにその燈火の油');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, '金の壇灌膏香幕屋の門の幔子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, '銅の壇その銅の網とその杠およびその諸の器具洗盤とその臺');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, '庭の幕その柱とその座庭の門の幔子その紐とその釘ならびに幕屋に用ふる諸の器具集會の天幕のために用ふる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, '聖所にて職をなすところの供職の衣服即ち祭司の職をなす時に用ふる者なる祭司アロンの聖衣およびその子等の衣服');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, '斯ヱホバの凡てモーセに命じたまひしごとくにイスラエルの子孫その諸の工事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'モーセその一切の工作を見るにヱホバの命じたまひしごとくに造りてあり即ち是のごとくに作りてあればモーセ人衆を祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, '茲にヱホバ、モーセに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '正月の元日に汝集會の天幕の幕屋を建べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, '而して汝その中に律法の櫃を置ゑ幕をもてその櫃を障蔽し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, '又案を携へいり陳設の物を陳設け且燈臺を携へいりてその燈盞を置うべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, '汝また金の香壇を律法の櫃の前に置ゑ幔子を幕屋の門に掛け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, '燔祭の壇を集會の天幕の幕屋の門の前に置ゑ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, '洗盤を集會の天幕とその壇の間に置ゑて之に水をいれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, '庭の周圍に藩籬をたて庭の門に幔子を垂れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, '而して灌膏をとりて幕屋とその中の一切の物に灌ぎて其とその諸の器具を聖別べし是聖物とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, '汝また燔祭の壇とその一切の器具に膏をそそぎてその壇を聖別べし壇は至聖物とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, '又洗盤とその臺に膏をそそぎて之を聖別め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'アロンとその子等を集會の幕屋の門につれきたりて水をもて彼等を洗ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'アロンに聖衣を着せ彼に膏をそそぎてこれを聖別め彼をして祭司の職を我になさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, '又かれの子等をつれきたりて之に明衣を着せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'その父になせるごとくに之に膏を灌ぎて祭司の職を我になさしむべし彼等の膏そそがれて祭司たることは代々變らざるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'モーセかく行へり即ちヱホバの己に命じたまひし如くに爲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, '第二年の正月にいたりてその月の元日に幕屋建ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, '乃ちモーセ幕屋を建てその座を置ゑその板をたてその横木をさしこみその柱を立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, '幕屋の上に天幕を張り天幕の蓋をその上にほどこせりヱホバのモーセに命じ給ひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, '而してかれ律法をとりて櫃に蔵め杠を櫃につけ贖罪所を櫃の上に置ゑ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, '櫃を幕屋に携へいり障蔽の幕を垂て律法の櫃を隱せりヱホバのモーセに命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, '彼また集會の幕屋において幕屋の北の方にてかの幕の外に案を置ゑ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, '供前のパンをその上にヱホバの前に陳設たりヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, '又集會の幕屋において幕屋の南の方に燈臺をおきて案にむかはしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, '燈盞をヱホバの前にかかげたりヱホバのモーセに命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, '又集會の幕屋においてかの幕の前に金の壇を居ゑ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'その上に馨しき香を焚りヱホバのモーセに命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, '又幕屋の門に幔子を垂れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, '集會の天幕の幕屋の門に燔祭の壇を置ゑその上に燔祭と素祭をささげたりヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, '又集會の天幕とその壇の間に洗盤をおき其に水をいれて洗ふことの爲にす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'モーセ、アロンおよびその子等其につきて手足を洗ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, '即ち集會の幕屋に入る時または壇に近づく時に洗ふことをせりヱホバのモーセに命じたましごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'また幕屋と壇の周圍の庭に藩籬をたて庭の門に幔子を垂ぬ是モーセその工事を竣たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, '斯て雲集會の天幕を蓋てヱホバの榮光幕屋に充たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'モーセは集會の幕屋にいることを得ざりき是雲その上に止り且ヱホバの榮光幕屋に盈たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, '雲幕屋の上より昇る時にはイスラエルの子孫途に進めり其途々凡て然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, '然ど雲の昇らざる時にはその昇る日まで途に進むことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, '即ち晝は幕屋の上にヱホバの雲あり夜はその中に火ありイスラエルの家の者皆これを見るその途々すべて然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'ヱホバ集會の幕屋よりモーセを呼びこれに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'イスラエルの子孫に告てこれに言へ汝等の中の人もし家畜の禮物をヱホバに供んとせば牛あるひは羊をとりてその禮物となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'もし牛の燔祭をもてその禮物になさんとせば全き牡牛を供ふべしすなはち集會の幕屋の門にてこれをヱホバの前にその受納たまふやうに供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, '彼その燔祭とする者の首に手を按べし然ば受納られて彼のために贖罪とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, '彼ヱホバの前にその犢を宰るべし又アロンの子等なる祭司等はその血を携へきたりて集會の幕屋の門なる壇の四圍にその血を灑ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, '彼またその燔祭の牲の皮を剥ぎこれを切わかつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, '祭司アロンの子等壇の上に火を置きその火の上に薪柴を陳べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, '而してアロンの子等なる祭司等その切わかてる者その首およびその脂を壇の上なる火の上にある薪の上に陳ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'その臓腑と足はこれを水に洗ふべし斯て祭司は一切を壇の上に燒て燔祭となすべし是すなはち火祭にしてヱホバに馨しき香たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'またその禮物もし群の羊あるひは山羊の燔祭たらば全き牡を供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, '彼壇の北の方においてヱホバの前にこれを宰るべしアロンの子等なる祭司等はその血を壇の四圍に灑ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, '彼また之を切わかちその首とその脂を截とるべし而して祭司これを皆壇の上なる火の上にある薪柴の上に陳ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'またその臓腑と足はこれを水に洗ひ祭司一切を携へきたりて壇の上に燒べし是を燔祭となす是即ち火祭にしてヱホバに馨しき香たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, '若また禽を燔祭となしてヱホバに献るならば鳲鳩または雛き鴿を携へ來りて禮物となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, '祭司はこれを壇にたづさへゆきてその首を切やぶりこれを壇の上に燒べしまたその血はこれをしぼりいだして壇の一方にぬるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'またその穀袋とその内の物はこれを除きて壇の東の方なる灰棄處にこれを棄べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'またその翼は切はなすこと无にこれを割べし而して祭司これを壇の上にて火の上なる薪柴の上に燒べし是を燔祭となす是すなはち火祭にしてヱホバに馨しき香たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '人素祭の禮物をヱホバに供ふる時は麥粉をもてその禮物となしその上に油をそそぎ又その上に乳香を加へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'これをアロンの子等なる祭司等の許に携へゆくべし斯てまた祭司はその麥粉と油一握をその一切の乳香とともに取り之を記念の分となして壇の上に燒べし是すなはち火祭にしてヱホバに馨しき香たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, '素祭の餘はアロンとその子等に歸すべし是はヱホバに献る火祭の一にして至聖物たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, '汝もし爐に燒たる物をもて素祭の禮物となさんとせば麥粉に油を和て作れる無酵菓子および油を抹たる無酵煎餅を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, '汝の素祭とする禮物もし鍋に燒たる物ならば麥粉に油を和て酵いれずに作れる者を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, '汝これを細に割てその上に油をそそぐべし是を素祭となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, '汝の素祭とする禮物もし釜に煮たる物ならば麥粉と油をもて作れる者を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, '汝これ等の物をもて作れる素祭の物をヱホバに携へいたるべし是を祭司に授さば祭司はこれを壇にたづさへ往き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'その素祭の中より記念の分をとりて壇の上に焚べし是すなはち火祭にしてヱホバに馨しき香たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, '素祭の餘はアロンとその子等に皈すべし是はヱホバにささぐる火祭の一にして至聖物たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, '凡そ汝等がヱホバにたづさへいたる素祭は都て酵いれて作るべからず汝等はヱホバに献る火祭の中に酵または蜜を入て焚べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, '但し初熟の禮物をそなふる時には汝等これをヱホバにそなふべし然ど馨しき香のためにこれを壇にそなふる事はなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, '汝素祭を献るには凡て鹽をもて之に味くべし汝の神の契約の鹽を汝の素祭に缺こと勿れ汝禮物をなすには都て鹽をそなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, '汝初穂の素祭をヱホバにそなへんとせば穂を火にやきて殼をさりたる者をもて汝の初穂の禮物にそなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, '汝また油をその上にほどこし乳香をその上に加ふべし是を素祭となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, '祭司はその殻を去たる穀物の中および油の中よりその記念の分を取りその一切の乳香とともにこれを焚べし是すなはちヱホバにささぐる火祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '人もし酬恩祭の犠牲を献るに當りて牛をとりて之を献るならば牝牡にかかはらずその全き者をヱホバの前に供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'すなはちその禮物の首に手を按き集會の幕屋の門にこれを宰るべし而してアロンの子等なる祭司等その血を壇の周圍に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, '彼はまたその酬恩祭の犠牲の中よりして火祭をヱホバに献べし即ち臓腑を裹むところの脂と臓腑の上の一切の脂');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'および二箇の腎とその上の脂の腰の兩傍にある者ならびに肝の上の網膜の腎の上に達る者を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, '而してアロンの子等壇の上において火の上なる薪の上の燔祭の上にこれを焚べし是すなはち火祭にしてヱホバに馨しき香たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'もしまたヱホバに酬恩祭の犠牲を献るにあたりて羊をその禮物となすならば牝牡にかかはらず其全き者を供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, '若また羔羊をその禮物となすならば之をヱホバの前に牽來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'その禮物の首に手を按きこれを集會の幕屋の前に宰るべし而してアロンの子等その血を壇の四圍にそそぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, '彼その酬恩祭の犠牲の中よりして火祭をヱホバに献べし即ちその脂をとりその尾を脊骨より全く斷きりまた臓腑を裹ところの脂と臓腑の上の一切の脂');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'および兩箇の腎とその上の脂の腰の兩傍にある者ならびに肝の上の網膜の腎の上に達る者をとるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, '祭司はこれを壇の上に焚べし是は火祭にしてヱホバにたてまつる食物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'もし山羊を禮物となすならばこれをヱホバの前に牽來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, '其の首に手を按きこれを集會の幕屋の前に宰るべし而してアロンの子等その血を壇の四圍に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, '彼またその中よりして禮物をとりヱホバに火祭をささぐべしすなはち臓腑を裹むところの脂と臓腑の上のすべての脂');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'および兩箇の腎とその上の脂と腰の兩傍にある者ならびに肝の上の網膜の腎の上に達る者をとるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, '祭司はこれを壇の上に焚べし是は火祭として奉つる食物にして馨しき香たるなり脂はみなヱホバに歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, '汝等は脂と血を食ふべからず是は汝らがその一切の住處において代々永く守るべき例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'イスラエルの子孫に告ていふべし人もし誤りてヱホバの誡命に違ひて罪を犯しその爲べからざる事の一を行ふことあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'また若膏そそがれし祭司罪を犯して民を罪に陷いるるごとき事あらばその犯せし罪のために全き犢の若き者を罪祭としてヱホバに献べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, '即ちその牡犢を集會の幕屋の門に牽きたりてヱホバの前にいたりその牡犢の首に手を按きその牡犢をヱホバの前に宰るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'かくて膏そそがれし祭司その牡犢の血をとりてこれを集會の幕屋にたづさへ入り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, '而して祭司指をその血にひたしてヱホバの前聖所の障蔽の幕の前にその血を七次そそぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, '祭司またその血をとりてヱホバの前にて集會の幕屋にある馨香の壇の角にこれを塗べしその牡犢の血は凡てこれを集會の幕屋の門にある燔祭の壇の底下に灌べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'またその牡犢の脂をことごとく取て罪祭に用ふべし即ち臓腑を裹むところの油と臓腑の上の一切の脂');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'および兩箇の腎と其上の脂の腰の兩傍にある者ならびに肝の上の網膜の腎の上に達る者を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, '之を取には酬恩祭の犠牲の牛より取が如くすべし而して祭司これを燔祭の壇の上に焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'その牡犢の皮とその一切の肉およびその首と脛と臓腑と糞等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, '凡てその牡犢はこれを營の外に携へいだして灰を棄る場なる清淨處にいたり火をもてこれを薪柴の上に焚べし即ち是は灰棄處に焚べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'またイスラエルの全會衆過失をなしたるにその事會衆の目にあらはれすして彼等つひにヱホバの誡命の爲べからざる者を爲し罪を獲ることあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'もし其犯せし罪あらはれなば會衆の者若き犢を罪祭に献べし即ちこれを集會の幕屋の前に牽いたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, '會衆の長老等ヱホバの前にてその牡犢の首に手を按きその一人牡犢をヱホバの前に宰るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, '而して膏そそがれし祭司その牡犢の血を集會の幕屋に携へいり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, '祭司指をその血にひたしてヱホバの前障蔽の幕の前にこれを七次そそぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, '祭司またその血をとりヱホバの前にて集會の幕屋にある壇の角にこれを塗べし其血は凡てこれを集會の幕屋の門にある燔祭の壇の底下に灌べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'また其脂をことごとく取て壇の上に焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'すなはち罪祭の牡犢になしたるごとくにこの牡犢にもなし祭司これをもて彼等のために贖罪をなすべし然せば彼等赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'かくして彼その牡犢を營の外にたづさへ出し初次の牡犢を焚しごとくにこれを焚べし是すなはち會衆の罪祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'また牧伯たる者罪を犯しその神ヱホバの誡命の爲べからざる者を誤り爲て罪を獲ことあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, '若その罪を犯せしことを覺らば牡山羊の全き者を禮物に持きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'その山羊の首に手を按き燔祭の牲を宰る場にてヱホバの前にこれを宰るべし是すなはち罪祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, '祭司は指をもてその罪祭の牲の血をとり燔祭の壇の角にこれを抹り燔祭の壇の底下にその血を灌ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, '酬恩祭の犠牲の脂のごとくにその脂を壇の上に焚べし斯祭司かれの罪のために贖事をなすべし然せば彼は赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'また國の民の中に誤りて罪を犯しヱホバの誡命の爲べからざる者の一を爲て罪を獲る者あらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, '若その罪を犯せしことを覺らば牝山羊の全き者を牽きたりその犯せし罪のためにこれを禮物になすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, '即ちその罪祭の牲の首に手を按き燔祭の牲の場にてその罪祭の牲を宰るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, '而して祭司は指をもてその血を取り燔祭の壇の角にこれを抹りその血をことごとくその壇の底下に灌べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, '祭司また酬恩祭の牲より脂をとるごとくにその脂をことごとく取りこれを壇の上に焚てヱホバに馨しき香をたてまつるべし斯祭司かれのために贖罪をなすべし然せば彼は赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, '彼もし羔羊を罪祭の禮物に持きたらんとせば牝の全き者を携へきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'その罪祭の牲の首に手を按き燔祭の牲を宰る場にてこれを宰りて罪祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'かくて祭司指をもてその罪祭の牲の血を取り燔祭の壇の角にこれを抹りその血をことごとくその壇の底下に灌ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, '羔羊の脂を酬恩祭の犠牲より取るごとくにその脂をことごとく取べし而して祭司はヱホバに献ぐる火祭のごとくにこれを壇の上に焚べし斯祭司彼の犯せる罪のために贖をなすべし然せば彼は赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '人もし證人として出たる時に諭誓の聲を聽ながらその見たる事またはその知る事を陳ずして罪を犯さば己の咎は己の身に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, '人もし汚穢たる獣の死體汚穢たる家畜の死體汚穢たる昆蟲の死體など凡て汚穢たる物に捫ることあらばその事に心づかざるもその身は汚れて辜あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'もし又心づかずして人の汚穢にふるる事あらばその人の汚穢は如何なる汚穢にもあれその之を知るにいたる時は辜あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, '人もし心づかずして誓を發し妄に口をもて惡をなさんと言ひ善をなさんと言ばその人の誓を發して妄に言ふとこるは如何なる事にもあれそのこれを知るにいたる時は此等の一において辜あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, '若これらの一において辜ある時は某の事において罪を犯せりと言あらはし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'その愆のためその犯せし罪のために羊の牝なる者すなはち羔羊あるひは牝山羊をヱホバにたづさへ來りて罪祭となすべし斯て祭司は彼の罪のために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'もし羔羊にまで手のとどかざる時は鳲鳩二羽か雛鴿二羽をその犯せし愆のためにヱホバに持きたり一を罪祭にもちひ一を燔祭に用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, '即ちこれを祭司にたづさへ往べし祭司はその罪祭の者を先にささぐべし即ちその首を頸の根より切やぶるべし但しこれを切はなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, '而してその罪祭の者の血を壇の一方にそそぎその餘の血をば壇の底下にしぼり出すべし是を罪祭となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'またその次のは慣例のごとくに燔祭にささぐべし斯祭司彼が犯せし罪のために贖をなすべし然せば彼は赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'もし二羽の鳲鳩か二羽の雛き鴿までに手のとどかざる時はその罪ある者麥粉一エパの十分一を禮物にもちきたりてこれを罪祭となすべしその上に膏をかくべからず又その上に乳香を加ふべからず是は罪祭なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, '彼祭司の許にこれを携へゆくべし祭司はこれを一握とりて記念の分となし壇の上にてヱホバの火祭の上にこれを焚べし是を罪祭となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, '斯祭司は彼が是等の一を犯して獲たる罪のために贖をなすべし然せば彼は赦されんその殘餘は素祭とひとしく祭司に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '人もし過失を爲し知ずしてヱホバの聖物を于して罪を獲ことあらば汝の估價に依り聖所のシケルにしたがひて數シケルの銀にあたる全き牡羊を群の中よりとりその愆のためにこれをヱホバに携へきたりて愆祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, '而してその聖物を于して獲たる罪のために償をなしまた之に五分の一をくはへて祭司に付すべし祭司はその愆祭の牡羊をもて彼のために贖罪をなすべし然せば彼は赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, '人もし罪を犯しヱホバの誡命の爲べからざる者の一を爲すことあらば假令これを知ざるも尚罪ありその罪を任べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, '即ち汝の估價にしたがひて群の中より全き牡羊をとり愆祭となしてこれを祭司にたづさへいたるべし祭司は彼が知ずして誤りし過誤のために贖罪をなすべし然せば彼は赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, '是を愆祭となすその人は誠にヱホバに罪を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '人もしヱホバにむかひて不信をなして罪を獲ことあり即ち人の物をあづかり又は質にとり又は奪ひおきて然る事あらずと言ひ或は人を虐る事を爲し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, '或は人の落せし物を拾ひおきて然る事なしと言ひ偽りて誓ふことを爲す等凡て人の爲て罪を獲るところの事を一にても行はば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, '是罪を犯して身に罪ある者なればその奪し物その虐げて取たる物その預りし物その拾ひとりし物');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'および凡てその偽り誓し物を還すべし即ちその原物を還しその上に五分の一をこれに加へその愆祭をささぐる日にこれをその本主に付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, '彼その愆祭をヱホバに携へきたるべし即ち汝の估價にしたがひその愆のために群の中より全き牡羊をとりて祭司にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, '祭司はヱホバの前において彼のために贖罪をなすべし然せば彼はその中のいづれを行ひて愆を獲るもゆるさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'アロンとその子等に命じて言へ燔祭の例は是のごとし此燔祭は壇の上なる爐の上に旦まで終夜あらしむべし即ち壇の火をしてこれと共に燃つつあらしむべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, '祭司は麻の衣服を着て麻の褌をその肉に纒ひ壇の上にて火にやけたる燔祭の灰を取て壇の旁に置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, '而してその衣服を脱ぎ他の衣服をつけてその灰を營の外に携へいだし清淨地にもちゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, '壇の上の火をばたえず燃しむべし熄しむべからず祭司は朝ごとに薪柴をその上に燃し燔祭の物をその上に陳べまた酬恩祭の脂をその上に焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '火はつねに壇の上にたえず燃しむべし熄しむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, '素祭の例は是のごとしアロンの子等これをヱホバの前すなはち壇の前にささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, '即ち素祭の麥粉とその膏を一握とりまた素祭の上の乳香をことごとく取て之を壇の上に焚き馨しき香となし記念の分となしてヱホバにたてまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'その遺餘はアロンとその子等これを食ふべし即ち酵をいれずして之を聖所に食ふべし集會の幕屋の庭にて之を食ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, '之を酵いれて燒べからずわが火祭の中より我これを彼等にあたへてその分となさしか是は罪祭と愆祭のごとくに至聖し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'アロンの子等の男たる者はみな之を食ふことを得べし是はヱホバにたてまつる火祭の例にして汝等が代々永くまもるべき者なり凡てこれに觸る者は聖なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'アロンとその子等が膏そそがるる日にヱホバにささぐべき禮物は是のごとし麥粉一エパの十分の一を素祭となして恒に献ぐべし即ちその半を朝にその半を夕にささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, '是は鍋の内に油をもて作りその燒たる時に汝これを携へきたるべし即ちこれを幾個にも劈て素祭となしヱホバに献げて馨しき香とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'アロンの子等の中膏をそそがれて彼に継で祭司となる者はこれを献ぐべし斯はヱホバに對して永く守るべき例なり是は全く焚つくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, '凡て祭司の素祭はみな全く焚つくすべし食ふべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'アロンとその子等に告ていふべし罪祭の例は是のごとし燔祭の牲を宰る場にて罪祭の牲をヱホバの前に宰るべし是は至聖物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, '罪のために之をささぐるところの祭司これを食ふべし即ち集會の幕屋の庭において聖所に之を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, '凡てその肉に觸る者は聖なるべしその血もし衣服に灑ぎかかることあらばその灑ぎかかれる者を聖所に洗ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'またこれを煮たる土瓦の器皿は碎くべし若これを煮たる者銅の鍋ならば水をもてこれを磨き洗ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, '祭司等の中の男たる者は皆これを食ふことを得べし是は至聖し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, '然どその血を集會の幕屋にたづさへいりて聖所にて贖罪をなしたる罪祭はこれを食ふべからず火をもてこれを焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'また愆祭の例は是のごとし是は至聖者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, '燔祭を宰る場にて愆祭を宰るべし而して祭司その血を壇の四周にそそぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'その脂をことごとく献ぐべし即ちその脂の尾その臓腑を裹むところの諸の脂');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, '兩個の腎とその上の脂の腰の兩傍にある者および肝の上の網膜の腎の上におよべる者を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, '祭司これを壇の上に焚てヱホバに火祭とすべし之を愆祭となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, '祭司等の中の男たる者はみな之を食ふことを得是は聖所に食ふべし至聖者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, '罪祭も愆祭もその例は一にして異らずこれは贖罪をなすところの祭司に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, '人の燔祭をささぐるところの祭司その祭司はその献ぐる燔祭の物の皮を自己に得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, '凡て爐に燒たる素祭の物および凡て釜と鍋にて製へたる者はこれを献ぐるところの祭司に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, '凡そ素祭は油を和たる者も乾たる者もみなアロンの諸の子等に均く歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'ヱホバに献ぐべき酬恩祭の犠牲の例は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, '若これを感謝のために献ぐるならば油を和たる無酵菓子と油をぬりたる無酵煎餅および麥粉に油をませて燒たる菓子をその感謝の犠牲にあはせて献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'その菓子の外にまた有酵パンを酬恩祭なる感謝の犠牲にあはせてその禮物に供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, '即ちこの全體の禮物の中より一箇宛を取りヱホバにささげて擧祭となすべし是は酬恩祭の血を灑ぐところの祭司に歸すべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, '感謝のために献ぐる酬恩祭の犠牲の肉はこれを献げしその日の中に食ふべし少にても翌朝まで存しおくまじきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'その犠牲の禮物もし願還かまたは自意の禮物ならばその犠牲をささげし日にこれを食ふべしその殘餘はまた明日これを食ふことを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, '但しその犠牲の肉の殘餘は第三日にいたらば火に焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, '若その酬恩祭の犠牲の肉を第三日に少にても食ふことをなさば其は受納られずまた禮物と算らるることなくして反て憎むべき者とならん是を食ふ者その罪を任べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'その肉もし汚穢たる物にふるる事あらば食ふべからず火に焚べしその肉は淨き者みなこれを食ふことを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, '若その身に汚穢ある人ヱホバに屬する酬恩祭の犠牲の肉を食はばその人はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'また人もし人の汚穢あるひは汚たる獣畜あるひは忌しき汚たる物等都て汚穢に觸ることありながらヱホバに屬する酬恩祭の犠牲の肉を食はばその人はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'イスラエルの子孫に告て言べし牛羊山羊の脂は都て汝等これを食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, '自ら死たる獣畜の脂および裂ころされし獣畜の脂は諸般の事に用ふるを得れどもこれを食ふことは絶てなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, '人のヱホバに火祭として献ぐるところの牲畜の脂は誰もこれを食ふべからず之を食ふ人はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'また汝等はその一切の住處において鳥獣の血を決して食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, '何の血によらずこれを食ふ人あればその人は皆民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'イスラエルの子孫に告て言べし酬恩祭の犠牲をヱホバに献ぐる者はその酬恩祭の犠牲の中よりその禮物を取てヱホバにたづさへ來るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'ヱホバの火祭はその人手づからこれを携へきたるべし即ちその脂と胸とをたづさへ來りその胸をヱホバの前に搖て搖祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, '而して祭司その脂を壇の上に焚べしその胸はアロンとその子等に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, '汝等はその酬恩祭の犠牲の右の腿を擧祭となして祭司に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'アロンの子等の中酬恩祭の血と脂とを献ぐる者その右の腿を得て自己の分となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, '我イスラエルの子孫の酬恩祭の犠牲の中よりその搖る胸と擧たる腿をとりてこれを祭司アロンとその子等に與ふ是はイスラエルの子孫の中に永く行はるべき例典なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, '是はヱホバの火祭の中よりアロンに歸する分またその子等に歸する分なり彼等を立てヱホバに祭司の職をなさしむる日に斯定めらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'すなはち是は彼等に膏をそそぐ日にヱホバが命をくだしてイスラエルの子孫の中より彼等に歸せしめたまふ者にて代々永くまもるべき例典たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, '是すなはち燔祭素祭罪祭愆祭任職祭酬恩祭の犠牲の法なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'ヱホバ、シナイの野においてイスラエルの子孫にその禮物をヱホバに供ふることを命じたまひし日に是をシナイ山にてモーセに命じたまひしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '汝アロンとその子等およびその衣服と灌膏と罪祭の牡牛と二頭の牡羊と無酵パン一筐を携へきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'また會衆をことごとく集會の幕屋の門に集めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'モーセすなはちヱホバの己に命じたまひし如くなしたれば會衆は集會の幕屋の門に集りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'モーセ會衆にむかひて言ふヱホバの爲せと命じたまへる事は斯のごとしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, '而してモーセ、アロンとその子等を携きたり水をもて彼等を洗ひ清め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'アロンに裏衣を著せ帶を帶しめ明衣を纒はせエポデを着しめエポデの帶を之に帶しめこれをもてエポデを其身に結つけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'また胸牌をこれに着させその胸牌にウリムとトンミムをつけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'その首に頭帽をかむらしめその頭帽の上すなはちその額に金の板の聖前板をつけたりヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'モーセまた灌膏をとり幕屋とその中の一切の物に灌ぎてこれを聖別め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, '且これを七度壇にそそぎ壇とその諸の器具および洗盤とその臺に膏そそぎてこれを聖別め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'また灌膏をアロンの首にそそぎ之に膏そそぎて聖別たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'モーセまたアロンの子等をつれきたりて裏衣をこれに着せ帶をこれに帶しめ頭巾をこれに蒙らせたりヱホバのモーセに命じたまひし如くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'また罪祭の牡牛を牽きたりてアロンとその子等その罪祭の牡牛の頭に手を按り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, '斯てこれを殺してモーセその血をとり指をもてその血を壇の四周の角につけて壇を潔淨しまた壇の底下にその血を灌ぎて之を聖別め之がために贖をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'モーセまたその臓腑の上の一切の脂肝の上の網膜および兩箇の腎とその脂をとりて之を壇の上に焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, '但しその牡牛その皮その肉およびその糞は營の外にて火に焚りヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'また燔祭の牡羊を牽きたりてアロンとその子等その牡羊の頭に手を按たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, '斯てこれを宰してモーセその血を壇の周圍に灑げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, '而してモーセその牡羊を切さきその頭と肉塊と脂とを焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'また水をもてその臓腑と脛を洗ひてモーセその牡羊をことごとく壇の上に焚り是は馨しき香のためにささぐる燔祭にしてヱホバにたてまつる火祭たるなりヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'また他の牡羊すなはち任職の牡羊を牽きたりてアロンとその子等その牡羊の頭に手を按り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, '斯てこれを殺してモーセその血をとり之をアロンの右の耳の端とその右の手の大指と右の足の拇指につけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'またアロンの子等をつれきたりてその右の耳の端と右の手の大指と右の足の拇指にその血をつけたり而してモーセその血を壇の周圍に灑げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, '彼またその脂と脂の尾および臓腑の上の一切の脂と肝の上の網膜ならびに兩箇の腎とその脂とその右の腿とを取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'またヱホバの前なる無酵パンの筐の中より無酵菓子一箇と油ぬりたるパンの菓子一箇と煎餅一箇を取り是等をその脂の上とその右の腿の上に載せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, '是を凡てアロンの手とその子等の手に授け之をヱホバの前に搖て搖祭となさしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, '而してモーセまた之を彼等の手より取り壇の上にて燔祭の上にこれを焚り是は馨しき香のためにたてまつる任職祭にしてヱホバにささぐる火祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, '斯てモーセその胸をとりヱホバの前にこれを搖て搖祭となせり任職の牡羊の中是はモーセの分に歸する者なりヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, '而してモーセ灌膏と壇の上の血とをとりて之をアロンとその衣服に灑ぎまたその子等とその子等の衣服にそそぎアロンとその衣服およびその子等とその子等の衣服を聖別たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, '斯てモーセまたアロンとその子等に言けるは集會の幕屋の門にて汝等その肉を煮よ而して任職祭の筐の内なるパンと偕にこれを其處に食へ是はアロンとその子等これを食ふべしと我に命ありしにしたがふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'その肉とパンの餘れる者は汝等これを火に焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, '汝等はその任職祭の竟る日まで七日が間は集會の幕屋の門口より出べからず其は汝等の任職は七日にわたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, '今日行ひて汝等のために罪をあがなふが如くにヱホバ斯せよと命じたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, '汝等は集會の幕屋の門口に七日の間日夜居てヱホバの命令を守れ然せば汝等死る事なからん我かく命ぜられたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'すなはちアロンとその子等はヱホバのモーセによりて命じたまひし事等を盡く爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, '斯て第八日にいたりてモーセ、アロンとその子等およびイスラエルの長老等を呼');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, '而してアロンに言けるは汝若き牡犢の全き者を罪祭のために取りまた牡羊の全き者を燔祭のために取りてこれをヱホバの前に献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, '汝イスラエルの子孫に告て言べし汝等牡山羊を罪祭のために取りまた犢牛と羔羊の當歳にして全き者を燔祭のために取きたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'また酬恩祭のためにヱホバの前に供ふる牡牛と牡羊を取り且油を和たる素祭をとりきたるべしヱホバ今日汝等に顯れたまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, '是に於てモーセの命ぜし物を集會の幕屋の前に携へ來り會衆みな進よりてヱホバの前に立ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'モーセ言ふヱホバの汝等に爲と命じたまへる者はすなはち是なり斯せばヱホバの榮光汝等にあらはれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'モーセすなはちアロンに言けるは汝壇に往き汝の罪祭と汝の燔祭を献げて己のためと民のために贖罪を爲しまた民の禮物を献げて之がために贖罪をなし凡てヱホバの命じたまひし如くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, '是に於てアロン壇に往き自己のためにする罪祭の犢を宰れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'しかしてアロンの子等その血をアロンの許にたづさへ來りければアロン指をその血にひたして之を壇の角につけその血を壇の底下に灌ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'また罪祭の牲の脂と腎と肝の上の網膜を壇の上に燒り凡てヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'またその肉と皮は營の外にて火に焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'アロンまた燔祭の牲を宰りしがその子等これが血を自己の許に携へきたりければ之を壇の周圍に灌げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, '彼等また燔祭の牲すなはちその肉塊と頭をかれに持きたりければ彼壇の上にこれを焚き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'またその臓腑と脛を洗ひ壇の上にて之を燔祭の上に焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, '彼また民の禮物を携へきたれり即ち民のためにする罪祭の山羊を取て之を宰り前のごとくに之を献げて罪祭となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'また燔祭の牲を牽きたりて定例のごとくに之をささげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'また素祭を携へきたりてその中より一握をとり朝の燔祭にくはへてこれを壇の上に焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'アロンまた民のためにする酬恩祭の犠牲なる牡牛と牡羊を宰りしがその子等これが血を己にもちきたりければ之を壇の周圍に灑げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, '彼等またその牡牛と牡羊の脂およびその脂の尾と臓腑を裹む者と腎と肝の上の網膜とを携へきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, '即ち彼等その脂をその胸の上に載きたりけるにアロンその脂を壇の上に焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'その胸と右の腿はアロンこれをヱホバの前に搖て搖祭となせり凡てモーセの命じたる如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'アロン民にむかひて手を擧てこれを祝し罪祭燔祭酬恩祭を献ぐることを畢て下れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'モーセとアロン集會の幕屋にいり出きたりて民を祝せり斯てヱホバの榮光總體の民に顯れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, '火ヱホバの前より出て壇の上の燔祭と脂を燬つくせり民これを見て聲をあげ俯伏ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, '茲にアロンの子等なるナダブとアビウともにその火盤をとりて火をこれにいれ香をその上に盛て異火をヱホバの前に献げたり是はヱホバの命じたまひし者にあらざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, '火ヱホバより出て彼等を燬ほろぼせりすなはち彼等はヱホバの前に死うせぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'モーセ、アロンに言けるはヱホバの宣ふところは是のごとし云く我は我に近づく者等の中に我の聖ことを顯はし又全體の民の前に榮光を示さんアロンは默然たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'モーセかくてアロンの叔父ウジエルの子等なるミサエルとエルザパンを呼び汝等進みよりて聖所の前より汝等の兄弟等を營の外に携へ出せと之にいひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'すなはち進みよりて彼等をその裏衣のままに營の外に携へ出しモーセの言るごとくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'モーセまたアロンおよびその子エレアザルとイタマルにいひけるは汝らの頭を露すなかれまた汝らの衣を裂なかれ恐くは汝等死んまた震怒全體の民におよぶあらん但汝等の兄弟たるイスラエルの全家ヱホバのかく火をもて燬ほろぼしたまひし事を哀くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, '汝等はまた集會の幕屋の門より出べからず恐くは汝等死ん其はヱホバの灌膏汝らの上にあればなりと彼等モーセの言のごとくに爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, '茲にヱホバ、アロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '汝も汝の子等も集會の幕屋にいる時には葡萄酒と濃酒を飮なかれ恐くは汝等死ん是は汝らが代々永く守るべき例たるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, '斯するは汝等が物の聖と世間なるとを分ち汚たると潔淨とを分つことを得んため');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, '又ヱホバのモーセによりて告たまひし一切の法度をイスラエルの子孫に敎ふることを得んがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'モーセまたアロンおよびその遺れる子エレアザルとイタマルに言けるは汝等ヱホバの火祭の中より素祭の遺餘を取り酵をいれずして之を壇の側に食へ是は至聖物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, '是はヱホバの火祭の中より汝に歸する者また汝の子等に歸する者なれば汝等これを聖所にて食ふべし我かく命ぜられたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'また搖る胸と擧たる腿は汝および汝の男子と女子これを淨處にて食ふべし是はイスラエルの子孫の酬恩祭の中より汝の分と汝の子等の分に與へらるる者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, '彼等その擧るところの腿と搖ところの胸を火祭の脂とともに持きたりこれをヱホバの前に搖て搖祭となすべし其は汝と汝の子等に歸すべし是は永く守るべき例にしてヱホバの命じたまふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, '斯てモーセ罪祭の山羊を尋ね索めけるに旣にこれを燬たりしかばアロンの遺れる子等エレアザルとイタマルにむかひてモーセ怒を發し言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '罪祭の牲は至聖かるに汝等なんぞ之を聖所にて食ざりしや是は汝等をして會衆の罪を任て彼等のためにヱホバのまへに贖をなさしめんとて汝等に賜ふ者たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, '視よその血はまだこれを聖所に携へいることをせざりきかの物は我が命ぜしごとくに汝等これを聖所にて食ふべかりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'アロン、モーセに言けるは今日彼等その罪祭と燔祭をヱホバの前に献げしが斯る事我身に臨めり今日もし我罪祭の牲を食はばヱホバこれを善と觀たまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'モーセこれを聽て善とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'ヱホバ、モーセとアロンに告てこれに言給はく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'イスラエルの子孫に告て言へ地の諸の獣畜の中汝らが食ふべき四足は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, '凡て獣畜の中蹄の分たる者すなはち蹄の全く分たる反芻者は汝等これを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, '但し反芻者と蹄の分たる者の中汝等の食ふべからざる者は是なり即ち駱駝是は反芻ども蹄わかれざれば汝等には汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, '山鼠是は反芻ども蹄わかれざれば汝等には汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, '兎是は反芻ども蹄わかれざれば汝等には汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, '猪是は蹄あひ分れ蹄まったく分るれども反芻ことをせざれば汝等には汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, '汝等是等の者の肉を食ふべからずまたその死體にさはるべからず是等は汝等には汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, '水にある諸の族の中汝等の食ふべき者は是なり凡て水の中にをり海河に居る者にして翅と鱗のある者は汝等これを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, '凡て水に動く者凡て水に生る者即ち凡て海河にある者にして翅と鱗なき者は是汝等には忌はしき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, '是等は汝等には忌はしき者なり汝等その肉を食ふべからずまたその死體をば忌はしき者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, '凡て水にありて翅も鱗もなき者は汝等には忌はしき者たるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, '鳥の中に汝等が忌はしとすべき者は是なり是をば食ふべからず是は忌はしき者なり即ち鵰黄鷹鳶');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, '鸇鷹の類');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, '諸の鴉の類');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, '駝鳥梟鴎雀鷹の類');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, '鶴鵜鷺');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, '白鳥鸅鸕大鷹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, '鶴鸚鵡の類鷸および蝙蝠');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'また凡て羽翼のありて四爬にあるくところの昆蟲は汝等には忌はしき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, '但し羽翼のありて四爬にあるく諸の昆蟲の中その足に飛腿のありて地に飛ぶものは汝等これを食ふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, '即ちその中蝗蟲の類大蜢の類小蜢の類螇蚸の類を汝等食ふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, '凡て羽翼ありて四爬にあるくところの昆蟲はみな汝等には忌はしき者たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'これ等はなんぢらを汚すなり凡て是等の者の死體に捫る者は晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, '凡てその死體を身に携ふる者はその衣服を洗ふべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, '凡そ蹄の分れたる獣畜の中その蹄の全く分れざる者あるひは反芻ことをせざる者の死體は汝等には汚穢たるべし凡てこれに捫る者は汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, '四足にてあるく諸の獣畜の中その掌底にて歩む者は皆汝等には汚穢たるべしその死骸に捫る者は晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'その死體を身に携ふる者はその衣服を洗ふべしその身は晩まで汚るるなり是等は汝等には汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, '地に匍ところの匍行者の中汝等に汚穢となる者は是なり即ち鼬鼠鼫鼠大蜥蜴の類');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, '蛤蚧龍子守宮蛇醫蝘蜓');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, '諸の匍者の中是等は汝等には汚穢たるなり凡てその死たるに捫る者は晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, '是等の者の死て上に墜たる物は何にもあれ汚るべし木の器具にもあれ衣服にもあれ皮革にもあれ嚢袋にもあれ凡そ事に用ふる器は皆これを水にいるべし是は晩まで汚穢ん斯せば是は清まるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'また是等の中の者瓦の器におつればその内にある者みな汚るべし汝らその器を毀つべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'また水の入たる食ふべき食物も是等によりて汚るべく諸般の器にある飮べき飮物も是等に由て汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, '是等の者の死體物の上に堕ればその物都て汚るべし爐にもあれ土鍋にもあれ之を毀つべきなり是は汚れて汝等には汚れたる者となればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, '然ど泉水あるひは塘池水の潴は汚るること無し唯その死體に觸る者汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, '是等の者の死體は播べき種の上に堕るも其は汚るることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, '然ど種の上に水のかかれる時にその死體上に堕なば其は汝等には汚たるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, '汝等が食ふところの獣畜の死たる時はその死體に捫る者は晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'その死體を食ふ者はその衣服を濯ふべし其身は晩まで汚るるなりその死體を携ふる者もその衣服を洗ふべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, '地の上に匍ところの諸の匍行物は忌べき者なり食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, '即ち地に匍ところの諸の匍行物の中凡て腹ばひ行く者四足にて歩く者ならびに多の足を有つ者是等をば汝等食ふべからず是等は忌べき者たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, '汝等は匍ところの匍行物のためにその身を忌はしき者にするなかれ是等をもてその身を汚すなかれ又是等に汚さるるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, '我は汝等の神ヱホバなれば汝等その身を聖潔せよ然ば汝等聖者とならん我聖ければなり汝等は必ず地に匍ところの匍行者をもてその身を汚すことをせざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, '我は汝等の神とならんとて汝等をエジプトの國より導きいだせしヱホバなり我聖ければ汝等聖潔なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, '是すなはち獣畜と鳥と水に動く諸の生物と地に匍ふ諸の匍行物にかかはるところの例にして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, '汚たる者と潔き者とを分ち食るる生物と食はれざる生物とを分つ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'ヱホバまたモーセに告て曰たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'イスラエルの子孫に告て言へ婦女もし種をやどして男子を生ば七日汚るべし即ちその月の穢の日數ほど汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'また第八日に至らばその嬰の前の皮を割べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'その婦女は尚その成潔の血に三十三日を歴べしその成潔の日の滿るまでは聖物にさはるべからず聖所にいるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, '若女子を生ば二七日汚るべし月の穢におけるがごとしまたその成潔の血に六十六日を經べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, '而してその男子あるひは女子につきての成潔の日滿なば燔祭の爲に當歳の羔羊を取り罪祭のために雛き鴿あるひは鳲鳩を取てこれを集會の幕屋の門に携へきたり祭司にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, '祭司は之をヱホバの前にささげてその婦女のために贖罪をなすべし然せばその出血の穢潔まるべし是すなはち男子または女子を生る婦女にかかはるところの例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'その婦女もし羔羊にまで手の届かざる時は鳲鳩二羽か又は雛き鴿二羽を携へきたるべし是一は燔祭のため一は罪祭のためなり祭司これがために贖罪をなすべし然せば婦女は潔まるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'ヱホバ、モーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '人その身の皮に腫あるひは癬あるひは光る處あらんにもし之がその身の皮にあること癩病の患處のごとくならばその人を祭司アロンまたは祭司たるアロンの子等に携へいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'また祭司は肉の皮のその患處を觀べしその患處の毛もし白くなり且その患處身の皮よりも深く見えなば是癩病の患處なり祭司かれを見て汚たる者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'もし又その身の皮の光る處白くありて皮よりも深く見えずまたその毛も白くならずば祭司その患處ある人を七日の間禁鎖おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, '第七日にまた祭司之を觀べし若その患處變るところ無くまたその患處皮に蔓延ること無ば祭司またその人を七日の間禁鎖おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, '第七日にいたりて祭司ふたたびその人を觀べしその患處もし薄らぎまたその患處皮に蔓延らずば祭司これを潔者となすべし是は癬なりその人は衣服を洗ふべし然せば潔くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, '然どその人祭司に觀られて潔き者となりたる後にいたりてその癬皮に廣く蔓延らば再ひ祭司にその身を見すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, '祭司これを觀てその癬皮に蔓延るを見ば祭司その人を汚たる者となすべし是は癩病なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, '人もしその身に癩病の患處あらば祭司にこれを携ゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, '祭司これを觀にその皮の腫白くしてその毛も白くなり且その腫に爛肉の見ゆるあらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, '是舊き癩病のその身の皮にあるなれば祭司これを汚たる者となすべしその人は汚たる者なればこれを禁鎖るにおよばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, '若また癩病大にその皮に發しその患處ある者の皮に遍く滿て首より足まで凡て祭司の見るところにおよばば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, '祭司これを視若その身に遍く癩病の滿たるを見ばその患處ある者を潔き者となすべし其人は全く白くなりたれば潔きなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, '然どもし爛肉その人に顯れなば汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, '祭司爛肉を視ばその人を汚たる者となすべし爛肉は汚たる者なり是すなはち癩病たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, '若またその爛肉變て白くならばその人は祭司に詣るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, '祭司これを視るにその患處もし白くなりをらば祭司その患處ある者を潔き者となすべしその人は潔きなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'また肉の皮に瘍瘡ありしに癒て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'その瘍瘡の地方に白き腫おこり又は白くして微紅き光る處おこるありて之を祭司に見することあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, '祭司これを視るに皮よりも卑く見てその毛白くなりをらば祭司その人を汚たる者となすべし其は瘍瘡より起りし癩病の患處たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, '然ど祭司これを觀に其處に白き毛あらずまた皮よりも卑からずして却て薄らぎをらば祭司その人を七日の間禁鎖おくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, '而してもし大に皮に蔓延ば祭司その人を汚たる者となすべし是その患處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, '然どその光る處もしその所に止りて蔓延ずば是は瘍瘡の痕跡なり祭司その人を潔き者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'また肉の皮に火傷あらんにその火傷の跡もし微紅くして白く又は只白くして光る處とならば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, '祭司これを視べし若その光る處の毛白くなりてその處皮よりも深く見なば是火傷より起りし癩病なれば祭司その人を汚たる者となすべし是は癩病の患處たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, '然ど祭司これを視にその光る處に白き毛あらずまたその處皮よりも卑からずして却て薄らぎをらば祭司その人を七日の間禁鎖おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, '第七日に祭司これを視べしもし大に皮に蔓延りをらば祭司その人を汚たる者となすべし是は癩病の患處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'もしその光る處その所に止り皮に蔓延らずして却て薄らぎをらば是火傷の腫なり祭司其人を潔き者となすべし其は是火傷の痕迹なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, '男あるひは女もし頭または鬚に患處あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, '祭司その患處を觀べし若皮よりも深く見えまた其處に黄なる細き毛あらば祭司その人を汚れたる者となすべし其は瘡にして頭または鬚にある癩病なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, '若また祭司その瘡の患處を視に皮よりも深からずしてまた其處に黑き毛あること無ば祭司その瘡の患處ある者を七日の間禁鎖おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, '第七日に祭司その患處を視べしその瘡もし蔓延ずまた其處に黄なる毛あらずして皮よりもその瘡深く見ずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'その人は剃ことをなすべし但しその瘡の上は剃べからず祭司其瘡ある者を尚また七日の間禁鎖おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, '第七日に祭司またその瘡を視べし若その瘡皮に蔓延ずまた皮よりも深く見ずば祭司その人を潔き者となすべしその人はまたその衣服をあらふべし然せば潔くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, '若その潔き者となりし後にいたりてその瘡大に皮に蔓延りなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, '祭司その人を觀べし若その瘡皮に蔓延らば祭司は黄なる毛を尋るにおよばずその人は汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, '然ど若その瘡止たるごとくに見えて黑き毛の其處に生ずるあらばその瘡痊たる者にてその人は潔し祭司その人を潔き者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'また男あるひは女その身の皮に光る處すなはち白き光る處あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, '祭司これを視べし若その身の皮の光る處薄白からば是白斑のその皮に生じたるなればその人は潔し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, '人もしその髮毛頭より脱おつるあるも禿なれば潔し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, '人もしその面に近き處の頭の毛脱おつるあるも額の禿たるなれば潔し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, '然ども若その禿頭または禿額に白く微紅き患處あらば是その禿頭または禿額に癩病の發したるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, '祭司これを觀べし若その禿頭あるひは禿額の患處の腫白くして微紅くあり身の肉に癩病のあらはるるごとくならば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, '是癩病人にして汚たる者なり祭司その人をもて全く汚たる者となすべしその患處その頭にあるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, '癩病の患處ある者はその衣服を裂きその頭を露しその口に蓋をあてて居り汚たる者汚たる者とみづから稱ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'その患處の身にある日の間は恒に汚たる者たるべしその人は汚たる者なれば人に離れて居るべし即ち營の外に住居をなすべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, '若また衣服に癩病の患處起るあらん時は毛の衣にもあれ麻の衣にもあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, '又麻あるひは毛の經線にあるにもせよ緯線にあるにもせよ皮革にあるにもあれ又凡て皮革にて造れる物にあるにもあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, '若その衣服あるひは皮革あるひは經線あるひは緯線あるひは凡て皮革にて造れる物に有ところの患處靑くあるか又は赤くあらば是癩病の患處なり之を祭司に見べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, '祭司はその患處を視その患處ある物を七日の間禁鎖おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, '第七日にその患處を視べし若その衣服あるひは經線あるひは緯線あるひは毛あるひは皮革あるひは凡て皮革にて造れる物にあるところの患處蔓延をらばこれ惡き癩病にしてその物は汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, '彼その患處あるところの衣服毛または麻の經線緯線あるひは凡て皮革にて造れる物を燬べし是は惡き癩病なりその物を火に燒べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, '然ど祭司これを視に患處もしその衣服あるひは經線あるひは緯線あるひは凡て皮革にて造れる物に蔓延ずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, '祭司命じてその患處ある物を濯はせ尚七日の間之を禁鎖おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, '而して祭司その濯ひし患處を觀べし患處もし色の變ることなくば患處の蔓延ことあらざるも是は汚たる者なり汝これを火に燬べし是は表面にあるも裏面にあるも共に腐蝕の陷なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, '然ど濯たる後に祭司これを觀るにその患處薄らぎたらばその衣服あるひは皮革あるひは經線あるひは緯線より患處を切とるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, '然るに尚またその衣服あるひは經線あるひは緯線あるひは凡て皮革にて造れる物に患處のあらはるるあらば是再發なり汝その患處ある物を火に燒べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'また汝が濯ふところの衣服あるひは經線あるひは緯線あるひは凡て皮革にて造れる物よりして若その患處脱さらば再びこれを濯ふべし然せば潔し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, '是すなはち毛または麻の衣服および經線緯線ならびに凡て皮革にて造りたる物に起れる癩病の患處をしらべて潔と汚たるとを定むるところの條例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '癩病人の潔めらるる日の定例は是のごとし即ちその人を祭司の許に携へゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, '先祭司營より出ゆきて觀祭司もし癩病人の身にありし癩病の患處の痊たるを見ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, '祭司その潔めらるる者のために命じて生る潔き鳥二羽に香柏と紅の線と牛膝草を取きたらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, '祭司また命じてその鳥一羽を瓦の器の内にて活水の上に殺さしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, '而してその生る鳥を取り香柏と紅の線と牛膝草をも取て之を夫活水の上に殺したる鳥の血の中にその生る鳥とともに濡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, '癩病より潔められんとする者にこれを七回灑ぎてこれを潔き者となしその生る鳥をば野に放つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, '潔めらるる者はその衣服を濯ひその毛髮をことごとく剃おとし水に身を滌ぎて潔くなり然る後に營に入きたるべし但し七日が間は自己の天幕の外に居るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, '而して第七日にその身の毛髮をことごとく剃べし即ちその頭の髮と鬚と眉とをことごとく剃りまたその衣服を濯ひ且その身を水に滌ぎて潔くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, '第八日にいたりてその人二匹の全き羔羊の牡と當歳なる一匹の全き羔羊の牝を取りまた麥粉十分の三に油を和たる素祭と油一ログを取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, '潔禮をなす所の祭司その潔めらるべき人と是等の物とを集會の幕屋の門にてヱホバの前に置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, '而して祭司かの羔羊の牡一匹を取り一ログの油とともに之を愆祭に献げまた之をヱホバの前に搖て搖祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'この羔羊の牡は罪祭燔祭の牲を宰る處すなはち聖所にてこれを宰るべし罪祭の物の祭司に歸するごとく愆祭の物も然るなり是は至聖物たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, '而して祭司その愆祭の牲の血を取りその潔めらるべき者の右の耳の端と右の手の大指と右の足の拇指に祭司これをつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, '祭司またその一ログの油をとりて之を自身の左の手の掌に傾ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, '而して祭司その右の指を左の手の油にひたしその指をもて之を七回ヱホバの前に灑ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'その手の殘餘の油は祭司その潔らるべき者の右の耳の端と右の手の大指と右の足の拇指においてその愆祭の牲の血の上に之をつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, '而して尚その手に殘れる油は祭司これをその潔めらるべき者の首につけヱホバの前にて祭司その人のために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, '斯してまた祭司罪祭を献げその汚穢を潔めらるべき者のために贖罪を爲て然る後に燔祭の牲を宰るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, '而して祭司燔祭と素祭を壇の上に献げその人のために祭司贖罪を爲べし然せばその人は潔くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'その人もし貧くして之にまで手の届かざる時は搖て自己の贖罪をなさしむべき愆祭のために羔羊の牡一匹をとり又素祭のために麥粉十分の一に油を和たるを取りまた油一ログを取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, '且その手のとどくところに循ひて鳲鳩二羽かまたは雛き鴿二羽を取べし其一は罪祭のための者一は燔祭のための者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, '而してその潔禮の第八日に之を祭司に携へ集會の幕屋の門にきたりてヱホバの前にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'かくて祭司はその愆祭の牡羊と一ログの油を取り祭司これをヱホバの前に搖て搖祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, '而して愆祭の羔羊を宰りて祭司その愆祭の牲の血を取りこれをその潔めらるべき者の右の耳の端と右の手の大指と右の足の拇指につけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'また祭司その油の中を己の左の手の掌に傾ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, '而して祭司その右の指をもて左の手の油を七回ヱホバの前に灑ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, '亦祭司その潔めらるべき者の右の耳と右の手の大指と右の足の拇指において愆祭の牲の血をつけし處にその手の油をつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'またその手に殘れる油をば祭司その潔めらるべき者の首に之をつけヱホバの前にてその人のために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'その人はその手のおよぶところの鳲鳩または雛き鴿一羽を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, '即ちその手のおよぶところの者一を罪祭に一を燔祭に爲べし祭司はその潔めらるべき者のためにヱホバの前に贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, '癩病の患處ありし人にてその潔禮に用ふべき物に手の届ざる者は之をその條例とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'ヱホバ、モーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '我が汝らの產業に與ふるカナンの地に汝等の至らん時に我汝らの產業の地の或家に癩病の患處を生ぜしむること有ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'その家の主來り祭司に告て患處のごとき者家に現はると言べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, '然る時は祭司命じて祭司のその患處を視に行く前にその家を空しむべし是は家にある物の凡て汚れざらんためなり而して後に祭司いりてその家を觀べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'その患處を觀にもしその家の壁に靑くまたは赤き窪の患處ありて壁よりも卑く見えなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, '祭司その家を出て家の門にいたり七日の間家を閉おき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, '祭司第七日にまた來りて視るべしその患處もし家の壁に蔓延をらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, '祭司命じてその患處ある石を取のぞきて邑の外の汚穢所にこれを棄しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'またその家の内の四周を刮らしむべしその刮りし灰沙は之を邑の外の汚穢所に傾け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, '他の石を取てその石の所に入かふべし而して彼他の灰沙をとりて家を塗べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, '斯石を取のぞき家を刮りてこれを塗かへし後にその患處もし再びおこりて家に發しなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, '祭司また來りて視べし患處もし家に蔓延たらば是家にある惡き癩病なれば其は汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, '彼その家を毀ちその石その木およびその家の灰沙をことごとく邑の外の汚穢所に搬びいだすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'その家を閉おける日の間にこれに入る者は晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'その家に臥す者はその衣服を洗ふべしその家に食する者もその衣服を洗ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, '然ど祭司いりて視にその患處家を塗かへし後に家に蔓延ずば是患處の痊たる者なれば祭司その家を潔き者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, '彼すなはちその家を潔むるために鳥二羽に香柏と紅の線と牛膝草を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'その鳥一羽を瓦の器の内にて活る水の上に殺し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, '香柏と牛膝草と紅の線と生鳥を取てこれをその殺せし鳥の血なる活る水に浸し七回家に灑ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, '斯祭司鳥の血と活る水と生る鳥と香柏と牛膝草と紅の線をもて家を潔め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'その生る鳥を邑の外の野に縦ちその家のために贖罪をなすべし然せば其は潔くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, '是すなはち癩病の諸患處瘡');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'および衣服と家屋の癩病');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'ならびに腫と癬と光る處とに關る條例にして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, '何の日潔きか何の日汚たるかを敎ふる者なり癩病の條例は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'ヱホバ、モーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'イスラエルの子孫に告て言へ凡そ人その肉に流出あらばその流出のために汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'その流出に由て汚るること是のごとし即ちその肉の流出したたるもその肉の流出滞ほるも共にその汚穢となるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, '流出ある者の臥たる床は凡て汚るまたその人の坐したる物は凡て汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'その床に觸る人は衣服をあらひ水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, '流出ある人の坐したる物の上に坐する人は衣服を洗ひ水に身をそそぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, '流出ある者の身に觸る人は衣服を洗ひ水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'もし流出ある者の唾潔き者にかからばその人衣服を洗ひ水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, '流出ある者の乗たる物は凡て汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'またその下になりし物に觸る人は皆晩まで汚るまた其等の物を携ふる者は衣服を洗ひ水に身をそそぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, '流出ある者手を水に洗はずして人にさはらばその人は衣服を洗ひ水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, '流出ある者の捫りし瓦の器は凡て碎くべし木の器は凡て水に洗ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, '流出ある者その流出やみて潔くならば己の成潔のために七日を數へその衣服を洗ひ活る水にその體を滌ぐべし然せば潔くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, '而して第八日に鳲鳩二羽または雛き鴿二羽を自己のために取り集會の幕屋の門にきたりてヱホバの前にゆき之を祭司に付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, '祭司はその一を罪祭に一を燔祭に献げ而して祭司その人の流出のためにヱホバの前に贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, '人もし精の洩ることあらばその全身を水にあらふべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, '凡て精の粘着たる衣服皮革などは皆水に洗ふべし是は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, '男もし女と寝て精を洩さば二人ともに水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'また婦女流出あらんにその肉の流出もし血ならば七日の間不潔なり凡て彼に捫る者は晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'その不潔の間に彼が臥たるところの物は凡て汚るべし又彼がその上に坐れる物も皆汚れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'その床に捫る者は皆衣服を洗ひ水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, '彼が凡て坐りし物に捫る者は皆衣服を洗ひ水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, '彼の床の上またはその凡て坐りし物の上にある血に捫らばその人は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, '人もし婦女と寝てその不潔を身に得ば七日汚るべしその人の臥たる床は凡て汚れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, '婦女もしその血の流出不潔の期の外にありて多くの日に渉ることあり又その流出する事不潔の期に逾るあらばその汚穢の流出する日の間は凡てその不潔の時の如くにしてその身汚る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, '凡てその流出ある日の間彼が臥ところの床は彼におけること不潔の床のごとし凡そ彼が坐れる物はその汚るること不潔の汚穢のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, '是等の物に捫る人は凡て汚るその衣服を洗ひ水に身を滌ぐべしその身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, '彼もしその流出やみて淨まらば七日を算ふべし而して後潔くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, '彼第八日に鳲鳩二羽または雛き鴿二羽を自己のために取りこれを祭司に携へ來り集會の幕屋の門にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, '祭司その一を罪祭に一を燔祭に献げ而して祭司かれが汚穢の流出のためにヱホバの前に贖を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, '斯汝等イスラエルの子孫をその汚穢に離れしむべし是は彼等その中間にある吾が幕屋を汚してその汚穢に死ることなからん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, '是すなはち流出ある者その精を洩してこれに身を汚せし者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'その不潔を患ふ婦女或は男あるひは女の流出ある者汚たる婦女と寝たる者等に關るところの條例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'アロンの子等二人がヱホバの前に献ぐることを爲て死たる後にヱホバ、モーセに斯告たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, '即ちヱホバ、モーセに言たまひけるは汝の兄弟アロンに告よ時をわかたずして障蔽の幕の内なる聖所にいり櫃の上なる贖罪所の前にいたるべからず是死ることなからんためなり其は我雲のうちにありて贖罪所の上にあらはるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'アロン聖所にいるには斯すべしすなはち犢の牡を罪祭のために取り牡羊を燔祭のために取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, '聖き麻の裏衣を着麻の褌をその肉にまとひ麻の帶をもて身に帶し麻の頭帽を冠るべし是は聖衣なりその身を水にあらひてこれを着べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'またイスラエルの子孫の會衆の中より牡山羊二匹を罪祭のために取り牡羊一匹を燔祭のために取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'アロンは自己のためなるその罪祭の牡牛を牽きたりて自己とその家族のために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'アロンまたその兩隻の山羊を取り集會の幕屋の門にてヱホバの前にこれを置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'その兩隻の山羊のために籤を掣べし即ち一の籤をヱホバのためにし一の籤をアザゼルのためにすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, '而してアロンそのヱホバの籤にあたりし山羊を献げて罪祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, '又アザゼルの籤にあたりし山羊はこれをヱホバの前に生しおきこれをもて贖罪をなしこれを野におくりてアザゼルにいたらすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, '即ちアロン己のためなるその罪祭の牡牛を牽きたりて自己とその家族のために贖罪をなし自己のためなる其罪祭の牡牛を宰り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, '而して火鼎をとりヱホバの前の壇よりして熱れる火を之に盈てまた兩手に細末の馨しき香を盈て之を障蔽の幕の中に携へいり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'ヱホバの前に於て香をその火に放べ香の煙の雲をして律法の上なる贖罪所を蓋はしむべし然せば彼死ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, '彼またその牡牛の血をとり指をもて之を贖罪所の東面に灑ぎまた指をもてその血を贖罪所の前に七回灑ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, '斯してまた民のためなるその罪祭の山羊を宰りその血を障蔽の幕の内に携へいりかの牡牛の血をもて爲しごとくその血をもて爲しこれを贖罪所の上と贖罪所の前に灑ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'イスラエルの子孫の汚穢とその諸の悸れる罪とに縁て聖所のために贖罪を爲べし即ち彼等の汚穢の中間にある集會の幕屋のために斯なすべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, '彼が聖所において贖罪をなさんとて入たる時はその自己と己の家族とイスラエルの全會衆のために贖罪をなして出るまでは何人も集會の幕屋の内に居べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, '斯て彼ヱホバの前の壇に出きたり之がために贖罪をなすべし即ちその牡牛の血と山羊の血を取て壇の四周の角につけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'また指をもて七回その血を其の上に灑ぎイスラエルの子孫の汚穢をのぞきて其を潔ようし且聖別べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, '斯かれ聖所と集會の幕屋と壇のために贖罪をなしてかの生る山羊を牽きたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, '然る時アロンその生る山羊の頭に兩手を按きイスラエルの子孫の諸の惡事とその諸の悸反る罪をことごとくその上に承認はしてこれを山羊の頭に載せ選びおける人の手をもてこれを野に遣るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'その山羊彼等の諸惡を人なき地に任ゆくべきなり即ちその山羊を野に遣るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, '斯してアロン集會の幕屋にいりその聖所にいりし時に穿たる麻の衣を脱て其處に置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, '聖所においてその身を水にそそぎ衣服をつけて出で自己の燔祭と民の燔祭とを献げて自己と民とのために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'また罪祭の牲の脂を壇の上に焚べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'かの山羊をアザゼルに遣りし者は衣服を濯ひ水に身を滌ぎて然る後營にいるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, '聖所において贖罪をなさんために其血を携へ入たる罪祭の牡牛と罪祭の山羊とは之を營の外に携へいだしその皮と肉と糞を火に燒べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, '之を燒たる者は衣服を濯ひ水に身を滌ぎて然る後營にいるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, '汝等永く此例を守るべし即ち七月にいたらばその月の十日に汝等その身をなやまし何の工をも爲べからず自己の國の人もまた汝等の中に寄寓る外國の人も共に然すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, '其はこの日に祭司汝らのために贖罪をなして汝らを淨むればなり是汝らがヱホバの前にその諸の罪を清められんためになす者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, '是は汝らの大安息日なり汝ら身をなやますべし是永く守るべき例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, '膏をそそがれて任ぜられその父に代りて祭司の職をなすところの祭司贖罪をなすべし彼は麻の衣すなはち聖衣を衣べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, '彼すなはち至聖所のために贖罪をなしまた集會の幕屋のためと壇のために贖罪をなしまた祭司等のためと民の會衆のために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, '是汝等が永く守るべき例にしてイスラエルの子孫の諸の罪のために年に一度贖罪をなす者なり彼すなはちヱホバのモーセに命じたまひしごとく爲ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'アロンとその子等およびイスラエルの總の子孫に告てこれに言べしヱホバの命ずるところ斯のごとし云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, '凡そイスラエルの家の人の中牛羊または山羊を營の内に宰りあるひは營の外に宰ることを爲し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, '之を集會の幕屋の門に牽きたりて宰りヱホバの幕屋の前において之をヱホバに禮物として献ぐることを爲ざる者は血を流せる者と算らるべし彼は血を流したるなればその民の中より絶るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, '是はイスラエルの子孫をしてその野の表に犠牲とするところの犠牲をヱホバに牽きたらしめんがためなり即ち彼等は之を牽きたり集會の幕屋の門にいたりて祭司に就きこれを酬恩祭としてヱホバに献ぐべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, '然る時は祭司その血を集會の幕屋の門なるヱホバの壇にそそぎまたその脂を馨しき香のために焚てヱホバに奉つるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, '彼等はその慕ひて淫せし魑魅に重て犠牲をささぐ可らず是は彼等が代々永くまもるべき例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, '汝また彼等に言べし凡そイスラエルの家の人または汝らの中に寄寓る他國の人燔祭あるひは犠牲を献ぐることをせんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, '之を集會の幕屋の門に携へきたりてヱホバにこれを献ぐるにあらずばその人はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, '凡そイスラエルの家の人または汝らの中に寄寓る他國の人の中何の血によらず血を食ふ者あれば我その血を食ふ人にわが面をむけて攻めその民の中より之を斷さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, '其は肉の生命は血にあればなり我汝等がこれを以て汝等の霊魂のために壇の上にて贖罪をなさんために是を汝等に與ふ血はその中に生命のある故によりて贖罪をなす者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, '是をもて我イスラエルの子孫にいへり汝らの中何人も血をくらふべからずまた汝らの中に寄寓る他國の人も血を食ふべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, '凡そイスラエルの子孫の中または汝らの中に寄寓る他國の人の中もし食はるべき獣あるひは鳥を猟獲たる者あらばその血を灑ぎいだし土にて之を掩ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, '凡の肉の生命はその血にして是はすなはちその魂たるなり故に我イスラエルの子孫にいへりなんぢらは何の肉の血をもくらふべからず其は一切の肉の生命はその血なればなり凡て血をくらふものは絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'およそ自ら死たる物または裂ころされし物をくらふ人はなんぢらの國の者にもあれ他國の者にもあれその衣服をあらひ水に身をそそぐべしその身は晩までけがるるなりその後は潔し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'その人もし洗ふことをせずまたその身を水に滌がずばその罪を任べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'イスラエルの子孫に告て之に言へ我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, '汝らその住をりしエジプトの國に行はるる所の事等を傚ひ行ふべからずまた我が汝等を導きいたるカナンの國におこなはるる所の事等を傚ひおこなふべからずまたその例に歩行べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, '汝等は我が法を行ひ我が例をまもりてその中にあゆむべし我は汝等の神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, '汝等わが例とわが法をまもるべし人もし是を行はば之によりて生べし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, '汝等凡てその骨肉の親に近づきて之と淫するなかれ我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, '汝の母と淫するなかれ是汝の父を辱しむるなればなり彼は汝の母なれば汝これと淫するなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, '汝の父の妻と淫するなかれ是汝の父を辱しむるなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, '汝の姉妹すなはち汝の父の女子と汝の母の女子は家に生れたると家外に生れたるとによらず凡てこれと淫するなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, '汝の男子の女子または汝の女子の女子と淫する事なかれ是自己を辱しむるなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, '汝の父の妻が汝の父によりて產たる女子は汝の姉妹なれば之と淫する勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, '汝の父の姉妹と淫するなかれ是は汝の父の骨肉の親なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'また汝の母の姉妹と淫する勿れ是は汝の母の骨肉の親なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, '汝の父の兄弟の妻に親づきて之と淫する勿れ是は汝の叔伯母なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, '汝の媳と淫するなかれ是は汝の息子の妻なれば汝これと淫する勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, '汝の兄弟の妻と淫する勿れ是汝の兄弟を辱しむるなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, '汝婦人とその婦の女子とに淫する勿れまたその婦人の子息の女子またはその女子の女子を取て之に淫する勿れ是等は汝の骨肉の親なれば然するは惡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, '汝妻の尚生る間に彼の姉妹を取て彼とおなじく妻となして之に淫する勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, '婦のその行經の汚穢にある間はこれに近づきて淫するなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, '汝の鄰の妻と交合して彼によりて己が身を汚すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, '汝その子女に火の中を通らしめてこれをモロクにささぐることを絶て爲ざれ亦汝の神ヱホバの名を汚すことなかれ我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, '汝女と寝るごとくに男と寝るなかれ是は憎むべき事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, '汝獣畜と交合して之によりて己が身を汚すこと勿れまた女たる者は獣畜の前に立て之と接ること勿れ是憎むべき事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, '汝等はこの諸の事をもて身を汚すなかれ我が汝等の前に逐はらふ國々の人はこの諸の事によりて汚れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'その地もまた汚る是をもて我その惡のために之を罰すその地も亦自らそこに住る民を吐いだすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, '然ば汝等はわが例と法を守りこの諸の憎むべき事を一も爲べからず汝らの國の人も汝らの中間に寄寓る他國の人も然るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '汝等の先にありし此地の人々はこの諸の憎むべき事を行へりその地もまた汚る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, '汝等は是のごとくするなかれ恐くはこの地汝らの先にありし國人を吐いだす如くに汝らをも吐いださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, '凡そこの憎むべき事等を一にても行ふ者あれば之を行ふ人はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, '然ば汝等はわが例規を守り汝等の先におこなはれし是等の憎むべき習俗を一も行ふなかれまた之によりて汝等身を汚す勿れ我は汝等の神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '汝イスラエルの子孫の全會衆に告てこれに言へ汝等宜く聖あるべし其は我ヱホバ汝らの神聖あればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, '汝等おのおのその母とその父を畏れまた吾が安息日を守るべし我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, '汝等虚き物を恃むなかれまた汝らのために神々を鋳造ることなかれ我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, '汝等酬恩祭の犠牲をヱホバにささぐる時はその受納らるるやうに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, '之を食ふことは之を献ぐる日とその翌日に於てすべし若殘りて三日にいたらばこれを火に燒べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'もし第三日に少にても之を食ふことあらば是は憎むべき物となりて受納られざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, '之を食ふ者はヱホバの聖物を汚すによりてその罰を蒙むるべし即ちその人は民の中より絶さられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, '汝その地の穀物を穫ときには汝等その田野の隅々までを盡く穫可らず亦汝の穀物の遺穂を拾ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'また汝の菓樹園の菓を取つくすべからずまた汝の菓樹園に落たる菓を斂むべからず貧者と旅客のためにこれを遺しおくべし我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, '汝等竊むべからず偽べからず互に欺くべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, '汝等わが名を指て偽り誓ふべからずまた汝の神の名を汚すべからず我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, '汝の鄰人を虐ぐべからずまたその物を奪ふべからず傭人の値を明朝まで汝の許に留めおくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, '汝聾者を詛ふべからずまた瞽者の前に礙物をおくべからず汝の神を畏るべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, '汝審判をなすに方りて不義を行なふべからず貧窮者を偏り護べからず權ある者を曲て庇くべからず但公義をもて汝の鄰を審判べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, '汝の民の間に往めぐりて人を謗るべからず汝の鄰人の血をながすべからず我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, '汝心に汝の兄弟を惡むべからず必ず汝の鄰人を勸戒むべし彼の故によりて罪を身にうくる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, '汝仇をかへすべからず汝の民の子孫に對ひて怨を懐くべからず己のごとく汝の鄰を愛すべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, '汝らわが條例を守るべし汝の家畜をして異類と交らしむべからず異類の種をまぜて汝の田野に播べからず麻と毛をまじへたる衣服を身につくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, '凡そ未だ贖ひ出されず未だ解放れざる奴隸の女にして夫に適く約束をなせし者あらんに人もしこれと交合しなばその二人を鑓責むべし然ど之を殺すに及ばず是その婦いまだ解放れざるが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'その男は愆祭をヱホバに携へきたるべし即ち愆祭の牡羊を集會の幕屋の門に牽きたるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, '而して祭司その人の犯せる罪のためにその愆祭の牡羊をもてヱホバの前にこれがために贖罪をなすべし斯せばその人の犯せし罪赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, '汝等かの地にいたりて諸の果實の樹を植ん時はその果實をもて未だ割禮を受ざる者と見做べし即ち三年の間汝等これをもて割禮を受ざる者となすべし是は食はれざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, '第四年には汝らそのもろもろの果實を聖物となしこれをもてヱホバに感謝の祭を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, '第五年に汝等その果實を食ふべし然せば汝らのために多く實を結ばん我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, '汝等何をも血のままに食ふべからずまた魔術を行ふべからず卜筮をなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, '汝等頭の鬢を圓く剪べからず汝鬚の兩方を損ずべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, '汝等死る人のために己が身に傷くべからずまたその身に刺文をなすべからず我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, '汝の女子を汚して娼妓の業をなさしむべからず恐くは淫事國におこなはれ罪惡國に滿ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, '汝等わが安息日を守りわが聖所を敬ふべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, '汝等憑鬼者を恃むなかれ卜筮師に問ことを爲て之に身を汚さるるなかれ我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, '白髮の人の前には起あがるべしまた老人の身を敬ひ汝の神を畏るべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, '他國の人汝らの國に寄留て汝とともに在ばこれを虐ぐるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, '汝等とともに居る他國の人をば汝らの中間に生れたる者のごとくし己のごとくに之を愛すべし汝等もエジブトの國に客たりし事あり我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, '汝等審判に於ても尺度に於ても秤子に於ても升斗に於ても不義を爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, '汝等公平き秤公平き錘公平きエパ公平きヒンをもちふべし我は汝らの神ヱホバ汝らをエジブトの國より導き出せし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, '汝等わが一切の條例とわが一切の律法を守りてこれを行ふべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '汝イスラエルの子孫に言べし凡そイスラエルの子孫の中またはイスラエルに寄寓る他國の人の中その子をモロクに献ぐる者は必ず誅さるべし國の民石をもて之を撃べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, '我またわが面をその人にむけて之を攻めこれをその民の中より絶ん其は彼その子をモロクに献げて吾が聖所を汚しまたわが聖名を褻せばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'その人がモロクにその子を献ぐる時に國の民もし目を掩ひて見ざるがごとくし之を殺すことをせずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, '我わが面をその人とその家族にむけ彼および凡て彼に傚ひてモロクと淫をおこなふところの者等をその民の中より絶ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, '憑鬼者または卜筮師を恃みこれに從がふ人あらば我わが面をその人にむけ之をその民の中に絶べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, '然ば汝等宜く自ら聖潔して聖あるべし我は汝らの神ヱホバたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, '汝等わが條例を守りこれを行ふべし我は汝らを聖別るヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, '凡てその父またはその母を詛ふ者はかならず誅さるべし彼その父またはその母を詛ひたればその血は自身に歸すべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, '人の妻と姦淫する人すなはちその鄰の妻と姦淫する者あればその姦夫淫婦ともにかならず誅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'その父の妻と寝る人は父を辱しむるなり兩人ともにかならず誅さるべしその血は自己に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, '人もしその子の妻と寝る時は二人ともにかならず誅さるべし是憎むべき事を行へばなりその血は自己に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, '人もし婦人と寝るごとく男子と寝ることをせば是その二人憎むべき事をおこなふなり二人ともにかならず誅さるべしその血は自己に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, '人妻を娶る時にそれの母をともに娶らば是惡き事なり彼も彼等もともに火に燒るべし是汝らの中に惡き事の無らんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, '男子もし獣畜と交合しなばかならず誅さるべし汝らまたその獣畜を殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, '婦人もし獣畜に近づきこれと交らばその婦人と獣畜を殺すべし是等はともに必ず誅さるべしその血は自己に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, '人もしその姉妹すなはちその父の女子あるひは母の女子を取りて此は彼の陰所を見彼は此の陰所を見なば是恥べき事をなすなりその民の子孫の前にてその二人を絶べし彼その姉妹と淫したればその罪を任べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, '人もし經水ある婦人と寝て彼の陰所を露すことあり即ち男子その婦人の源を露し婦人また己の血の源を露すあらば二人ともにその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, '汝の母の姉妹または汝の父の姉妹の陰所を露すべからず斯する皆にその骨肉の親たる者の陰所をあらはすなれば二人ともにその罪を任べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, '人もしその伯叔の妻と寝る時は是その伯叔の陰所を露すなれば二人ともにその罪を任ひ子なくして死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, '人もしその兄弟の妻を取ば是汚はしき事なり彼その兄弟の陰所を露したるなればその二人は子なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, '汝等は我が一切の條例と一切の律法を守りて之を行ふべし然せば我が汝らを住せんとて導き行ところの地汝らを吐いだすことを爲じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, '汝らの前より我が逐はらふところの國人の例に汝ら歩行べからず彼等はこの諸の事をなしたれば我かれらを惡むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, '我さきに汝等に言へり汝等その地を獲ん我これを汝らに與へて獲さすべし是は乳と蜜の流るる地なり我は汝らの神ヱホバにして汝らを他の民より區別てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, '汝等は獣畜の潔と汚たると禽の潔と汚たるとを區別べし汝等は我が汚たる者として汝らのために區別たる獣畜または禽または地に匍ふ諸の物をもて汝らの身を汚すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, '汝等は我の聖者となるべし其は我ヱホバ聖ければなり我また汝等をして我の所有とならしめんがために汝らを他の民より區別たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, '男または女の憑鬼者をなし或は卜筮をなす者はかならず誅さるべし即ち石をもてこれを撃べし彼等の血は彼らに歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'ヱホバ、モーセに告て言たまはくアロンの子等なる祭司等に告てこれに言へ民の中の死人のために身を汚す者あるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, '但しその骨肉の親のためすなはちその母のため父のため男子のため女子のため兄弟のため');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'またその姉妹の處女にして未だ夫あらざる者のためには身を汚すも宜し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, '祭司はその民の中の長者なれば身を汚して褻たる者となるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, '彼等は髮をそりて頭に毛なき所をつくるべからずその鬚の兩傍を損ずべからずまたその身に傷つくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'その神に對て聖あるべくまたその神の名をけがすべからず彼等はヱホバの火祭すなはち其神の食物を献ぐる者なれば聖あるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, '彼等は妓女または汚れたる女を妻に娶るべからずまた夫に出されたる女を娶るべからず其はその身ヱホバにむかひて聖ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, '汝かれをもて聖者とすべし彼は汝の神ヱホバの食物を献ぐる者なればなり汝すなはちこれをもて聖者となすべし其は我ヱホバ汝らを聖別る者聖ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, '祭司の女たる者淫行をなしてその身を汚さば是その父を汚すなり火をもてこれを燒べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'その兄弟の中灌膏を首にそそがれ職に任ぜられて祭司の長となれる者はその頭をあらはすべからずまたその衣服を裂べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, '死人の所に往べからずまたその父のためにも母のためにも身を汚すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'また聖所より出べからずその神の聖所を褻すべからず其はその神の任職の灌膏首にあればなり我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, '彼妻には處女を娶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, '寡婦休れたる婦または汚れたる婦妓女等は娶るべからず惟自己の民の中の處女を妻にめとるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'その民の中に自己の子孫を汚すべからずヱホバこれを聖別ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'アロンに告て言へ凡そ汝の歴代の子孫の中身に疵ある者は進みよりてその神ヱホバの食物を献ぐる事を爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, '凡て疵ある人は進みよるべからずすなはち瞽者跛者および鼻の缺たる者成餘るところ身にある者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, '脚の折たる者手の折たる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, '傴僂者侏儒目に雲膜ある者疥ある者癬ある者外腎の壞れたる者等は進みよるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, '凡そ祭司アロンの子孫の中身に疵ある者は進みよりてヱホバの火祭を献ぐべからず彼は身に疵あるなれば進みよりてヱホバの食物を献ぐべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, '神の食物の至聖者も聖者も彼は食ふことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, '然ど障蔽の幕に至べからずまた祭壇に近よるべからず其は身に疵あればなり斯かれわが聖所を汚すべからず其は我ヱホバこれを聖別ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'モーセすなはちアロンとその子等およびイスラエルの一切の子孫にこれを告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '汝アロンとその子等に告て彼等をしてイスラエルの子孫の聖物をみだりに享用ざらしめまたその聖別て我にささげたる物についてわが名を汚すこと無らしむべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, '彼等に言へ凡そ汝等の歴代の子孫の中都てイスラエルの子孫の聖別て我にささげし聖物に汚たる身をもて近く者あればその人はわが前より絶るべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'アロンの子孫の中癩病ある者または流出ある者は凡てその潔くなるまで聖物を食ふべからずまた死躰に汚れたる物に捫れる者または精をもらせる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'または凡て人を汚すところの匍行物に捫れる者または何の汚穢を論はず人をして汚れしむるところの人に捫れる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, '此のごとき物に捫る者は晩まで汚るべしまたその身を水にて洗ふにあらざれば聖物を食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, '日の入たる時は潔くなるべければその後に聖物を食ふべし是その食物なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, '自ら死たる物または裂ころされし者を食ひて之をもて身を汚すべからず我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, '彼等これを褻してこれが爲に罪を獲て死るにいたらざるやう我が例規をまもるべし我ヱホバ是等を聖せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, '外國の人は聖物を食ふ可らず祭司の客あるひは傭人は聖物を食ふべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, '然ど祭司金をもて人を買たる時はその者はこれを食ふことを得またその家に生れし者も然り彼等は祭司の食物を食ふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, '祭司の女子もし外國の人に嫁ぎなば禮物なる聖物を食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, '祭司の女子寡婦となるありまたは出さるるありて子なくしてその父の家にかへり幼時のごとくにてあらばその父の食物を食ふことを得べし但し外國の人はこれを食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, '人もし誤りて聖物を食はばその聖物にこれが五分一を加へて祭司に付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'イスラエルの子孫がヱホバに献ぐるところの聖物を彼等褻すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'その聖物を食ふ者にはその愆の罰をかうむらしむべし其は我ヱホバこれを聖すればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'アロンとその子等およびイスラエルの一切の子孫に告てこれに言へ凡そイスラエルにをる外國の人の中願還の禮物または自意の禮物をヱホバに献げて燔祭となさんとする者は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'その受納らるるやうに牛羊あるひは山羊の牡の全き者を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, '凡て疵ある者は汝ら献ぐべからず是はその物なんぢらのために受納られざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, '凡て願を還さんとしまたは自意の禮物をなさんとして牛あるひは羊をもて酬恩祭の犠牲を献上る者はその受納らるるやうに全き者を取べし其物には何の疵もあらしむべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, '即ち盲なる者折たる所ある者切斷たる處ある者腫物ある者疥ある者癬ある者是の如き者は汝等これをヱホバに献ぐべからずまた壇の上に火祭となしてヱホバにたてまつるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, '牛あるひは羊の成餘れる所または成足ざる所ある者は汝らこれを自意の禮物には用ふるも宜し然ど願還においては是は受納らるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, '汝等外腎を打壞りまたは壓つぶしまたは割きまたは斬りたる者をヱホバに献ぐべからずまた汝らの國の中に斯る事を行ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, '汝らまた異邦人の手よりも是等の物を受て神の食に供ふることを爲べからず其は是等は缺あり疵ある者なるに因て汝らのために受納らるることあらざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '牛羊または山羊生れなば之を七日その母につけ置べし八日より後は是はヱホバに火祭とすれば受納らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, '牝牛にもあれ牝羊にもあれ汝らその母と子とを同日に殺すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, '汝ら感謝の犠牲をヱホバに献ぐる時は汝らの受納らるるやうに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, '是はその日の内に食つくすべし明日まで遺しおくべからず我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, '汝らわが誡命を守り且これを行ふべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, '汝等わが名を瀆すべからず我はかへつてイスラエルの子孫の中に聖者とあらはるべきなり我はヱホバにして汝らを聖くする者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, '汝らの神とならんとて汝らをエジプトの國より導きいだせし者なり我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'イスラエルの子孫につげて之に言へ汝らが宣告て聖會となすべきヱホバの節期は是のごとし我が節期はすなはち是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, '六日の間業務をなすべし第七日は休むべき安息日にして聖會なり汝ら何の業をもなすべからず是は汝らがその一切の住所において守るべきヱホバの安息日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'その期々に汝らが宣告べきヱホバの節期たる聖會は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'すなはち正月の十四日の晩はヱホバの逾越節なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'またその月の十五日はヱホバの酵いれぬパンの節なり七日の間汝等酵いれぬパンを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'その首の日には汝ら聖會をなすべし何の職業をも爲すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, '汝ら七日のあひだヱホバに火祭を献ぐべし第七日にはまた聖會をなし何の職業をもなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'ヱホバまたモーセにつげて言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'イスラエルの子孫につげて之に言へ汝らわが汝らにたまふところの地に至るにおよびて汝らの穀物を穫ときは先なんぢらの穀物の初穂一束を祭司にもちきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, '彼その束の受いれらるるやうに之をヱホバの前に搖べし即ちその安息日の翌日に祭司これを搖べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'また汝らその束を搖る日に當歳の牡羔の全き者を燔祭となしてヱホバに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'その素祭には油を和たる麥粉十分の二をもちひ之をヱホバに献げて火祭となし馨しき香たらしむべしまたその灌祭には酒一ヒンの四分の一をもちふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, '汝らはその神ヱホバに禮物をたづさへ來るその日まではパンをも烘麥をも靑穂をも食ふべからず是は汝らがその一切の住居において代々永く守るべき例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, '汝ら安息日の翌日より即ち汝らが搖祭の束を携へきたりし日より數へて安息日七をもてその數を盈すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'すなはち第七の安息日の翌日までに日數五十を數へをはり新素祭をヱホバに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'また汝らの居所より十分の二をもてつくりたるパン二箇を携へきたりて搖べし是は麥粉にてつくり酵をいれて燒べし是初穂をヱホバにささぐる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, '汝らまた當歳の全き羔羊七匹と少き牡牛一匹と牡山羊二匹を其パンとともに献ぐべしすなはち是等をその素祭およびその灌祭とともにヱホバにたてまつりて燔祭となすべし是は火祭にしてヱホバに馨しき香となる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, '斯てまた牡山羊一匹を罪祭にささげ當歳の羔羊二匹を酬恩祭の犠牲にささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, '而して祭司その初穂のパンとともにこの二匹の羔羊をヱホバの前に搖て搖祭となすべし是等はヱホバにたてまつる聖物にして祭司に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, '汝らその日に汝らの中に聖會を宣告いだすべし何の職業をも爲べからず是は汝らがその一切の住所において永く守るべき條例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, '汝らの地の穀物を穫ときは汝その穫るにのぞみて汝の田野の隅々までをことごとく穫つくすべからず又汝の穀物の遺穂を拾ふべからずこれを貧き者と客旅とに遺しおくべし我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'イスラエルの子孫に告て言へ七月においては汝らその月の一日をもて安息の日となすべし是は喇叭を吹て記念するの日にして即ち聖會たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, '汝ら何の職業をもなすべからず惟ヱホバに火祭を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '殊にまたその七月の十日は贖罪の日にして汝らにおいて聖會たり汝等身をなやましまた火祭をヱホバに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'その日には汝ら何の工をもなすべからず其は汝らのために汝らの神ヱホバの前に贖罪をなすべき贖罪の日なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, '凡てその日に身をなやますことをせざる者はその民の中より絶れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'またその日に何の工にても爲ものあれば我その人をその民の中より滅しさらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, '汝等何の工をもなすべからず是は汝らがその一切の住所において代々永く守るべき條例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, '是は汝らの休むべき安息日なり汝らその身をなやますべしまたその月の九日の晩すなはちその晩より翌晩まで汝等その安息をまもるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'イスラエルの子孫に告て言へその七月の十五日は結茅節なり七日のあひだヱホバの前にこれを守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, '首の日には聖會を開くべし何の職業をもなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, '汝等また七日のあひだ火祭をヱホバに献ぐべし而して第八日に汝等の中に聖會を開きまた火祭をヱホバに献ぐべし是は會の終結なり汝ら何の職業をもなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, '偖是等はヱホバの節期にして汝らが宣告て聖會となし火祭をヱホバに献ぐべき者なり即ち燔祭素祭犠牲および灌祭等をその献ぐべき日にしたがひて献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'この外にヱホバの諸安息日ありまた外に汝らの献物ありまた外に汝らの諸の願還の禮物ありまた外に汝らの自意の禮物あり是みな汝らがヱホバに献る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, '汝らその地の作物を斂めし時は七月の十五日よりして七日の間ヱホバの節筵をまもるべし即ち初の日にも安息をなし第八日にも安息をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'その首の日には汝等佳樹の枝を取べしすなはち棕櫚の枝と茂れる樹の條と水楊の枝とを取りて七日の間汝らの神ヱホバの前に樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, '汝ら歳に七日ヱホバに此節筵をまもるべし汝ら代々ながくこの條例を守り七月にこれを祝ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, '汝ら七日のあひだ茅廬に居りイスラエルに生れたる人はみな茅廬に居べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, '斯するは我がイスラエルの子孫をエジプトの地より導き出せし時にこれを茅廬に住しめし事を汝らの代々の子孫に知しめんためなり我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'モーセすなはちヱホバの節期をイスラエルの子孫に告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'イスラエルの子孫に命じ橄欖を搗て取たる清き油を燈火のために汝に持きたらしめて絶ず燈火をともすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'またアロンは集會の幕屋において律法の前なる幕の外にて絶ずヱホバの前にその燈火を整ふべし是は汝らが代々ながく守るべき定例なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, '彼すなはちヱホバの前にて純精の燈臺の上にその燈火を絶ず整ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, '汝麥粉を取りとれをもて菓子十二を燒べし菓子一箇には其の十分の二をもちふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, '而してこれをヱホバの前なる純精の案の上に二累に積み一累に六宛あらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, '汝また淨き乳香をその累の上に置きこれをしてそのパンの上にありて記念とならしめヱホバにたてまつりて火祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, '安息日ごとに絶ずこれをヱホバの前に供ふべし是はイスラエルの子孫の献ぐべき者にして永遠の契約たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'これはアロンとその子等に歸す彼等これを聖所に食ふべし是はヱホバの火祭の一にして彼に歸する者にて至聖し是をもて永遠の條例となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, '茲にその父はエジプト人母はイスラエル人なる者ありてイスラエルの子孫の中にいで來れることありしがそのイスラエルの婦の生たる者イスラエルの人と營の中に爭論をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, '時にそのイスラエルの婦の生たる者ヱホバの名を瀆して詛ふことをなしければ人々これをモーセの許にひき來れり(その母はダンの支派のデブリの女子にして名をシロミテと曰ふ)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, '人々かれを閉こめおきてヱホバの示諭をかうむるを俟り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, '時にヱホバ、モーセにつげて言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'かの詛ふことをなせし者を營の外に曳いだし之を聞たる者に皆その手を彼の首に按しめ全會衆をして彼を石にて撃しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, '汝またイスラエルの子孫に告て言べし凡てその神を詛ふ者はその罰を蒙るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'ヱホバの名を瀆す者はかならず誅されん全會衆かならず石をもて之を撃べし外國の人にても自己の國の人にてもヱホバの名を瀆すにおいては誅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, '人を殺す者はかならず誅さるベし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, '獣畜を殺す者はまた獣畜をもて獣畜を償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, '人もしその鄰人に傷損をつけなばそのなせし如く自己もせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, '即ち挫は挫目は目歯は歯をもて償ふべし人に傷損をつけしごとく自己も然せらるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, '獣畜を殺す者は是を償ふべく人を殺す者は誅さるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, '外國の人にも自己の國の人にもこの法は同一なり我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'モーセすなはちイスラエルの子孫にむかひかの營の外にて詛ふことをなせし者を曳いだして石にて撃てと言ければイラスエルの子孫ヱホバのモーセに命じたまひしごとく爲ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'ヱホバ、シナイ山にてモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'イスラエルの子孫につげて之に言ふべし我が汝らに與ふる地に汝ら至らん時はその地にもヱホバにむかひて安息を守らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, '六年のあひだ汝その田野に種播きまた六年のあひだ汝その菓園の物を剪伐てその果を斂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, '然ど第七年には地に安息をなさしむべし是ヱホバにむかひてする安息なり汝その田野に種播べからずまたその菓園の物を剪伐べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, '汝の穀物の自然生たる者は穫べからずまた汝の葡萄樹の修理なしに結べる葡萄は斂むべからず是地の安息の年なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, '安息の年の產物は汝らの食となるべしすなはち汝と汝の僕と汝の婢と汝の傭人と汝の所に寄寓る他國の人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'ならびに汝の家畜と汝の國の中の獣みなその產物をもて食となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, '汝安息の年を七次かぞふべし是すなはち七年を七回かぞふるなり安息の年七次の間はすなはち四十九年なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, '七月の十日になんぢ喇叭の聲を鳴わたらしむべし即ち贖罪の日になんぢら國の中にあまねく喇叭を吹ならさしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'かくしてその第五十年を聖め國中の一切の人民に自由を宣しめすべしこの年はなんぢらにはヨベルの年なりなんぢらおのおのその產業に歸りおのおのその家にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'その五十年はなんぢらにはヨベルなりなんぢら種播べからずまた自然生たる物を穫べからず修理なしになりたる葡萄を斂むべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'この年はヨベルにしてなんぢらに聖ければなりなんぢらは田野の產物をくらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'このヨベルの年にはなんぢらおのおのその產業にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'なんぢの鄰に物を賣りまたは汝の鄰の手より物を買ふ時はなんぢらたがひに相欺むくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'ヨベルの後の年の數にしたがひてなんぢその鄰より買ことをなすべし彼もまたその果を得べき年の數にしたがひてなんぢに賣ことをなすべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, '年の數多ときはなんぢその値を増し年の數少なきときはなんぢその値を減すべし即ち彼その果の多少にしたがひてこれを汝に賣るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, '汝らたがひに相欺むくべからず汝の神を畏るべし我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, '汝等わが法度を行ひまたわが律法を守りてこれを行ふべし然せば汝ら安泰にその地に住ことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, '地はその產物を出さん汝等は飽までに食ひて安泰に其處に住ことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, '汝等は我等もし第七年に種をまかずまたその產物を斂めずば何を食はんやと言か');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, '我命じて第六年に恩澤を汝等に降し三年だけの果を結ばしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, '汝等第八年には種を播ん然ど第九年までその舊き果を食ふことを得んすなはちその果のいできたるまで汝ら舊き者を食ふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, '地を賣には限りなく賣べからず地は我の有なればなり汝らは客旅また寄寓者にして我とともに在るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, '汝らの產業の地に於ては凡てその地を贖ふことを許すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, '汝の兄弟もし零落てその產業を賣しことあらばその贖業人たる親戚きたりてその兄弟の賣たる者を贖ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, '若また人の之を贖ふ者あらずして己みづから之を贖ふことを得にいたらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'その賣てよりの年を數へて之が餘の分をその買主に償ふべし然せばその產業にかへることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, '然ど若これをその人に償ふことを得ずばその賣たる者は買主の手にヨベルの年まで在てヨベルに及びてもどさるべし彼すなはちその產業にかへることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, '人石垣ある城邑の内の住宅を賣ことあらんに賣てより全一年の間はこれを贖ふことを得べし即ち期定の日の内にその贖をなすべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'もし全一年の内に贖ふことなくばその石垣ある城邑の内の家は買主の者に確定りて代々ながくこれに屬しヨベルにももどされざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, '然ど周圍に石垣あらざる村落の家はその國の田畝の附屬物と見做べし是は贖はるべくまたヨベルにいたりてもどさるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'レビ人の邑々すなはちレビ人の產業の邑々の家はレビ人何時にでも贖ふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, '人もしレビ人の產業の邑においてレビ人より家を買ことあらば彼の賣たる家はヨベルにおよびて返さるべし其はレビ人の邑々の家はイスラエルの子孫の中に是がもてる產業なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, '但しその邑々の郊地の田畝は賣べからず是その永久の產業なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, '汝の兄弟零落かつ手慄ひて汝の傍にあらば之を扶助け之をして客旅または寄寓者のごとくに汝とともにありて生命を保たしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, '汝の兄弟より利をも息をも取べからず神を畏るべしまた汝の兄弟をして汝とともにありて生命を保たしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, '汝かれに利をとりて金を貸べからずまた益を得んとて食物を貸べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, '我は汝等の神ヱホバにしてカナンの地を汝らに與へ且なんぢらの神とならんとて汝らをエジプトの國より導きいだせし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, '汝の兄弟零落て汝に身を賣ことあらば汝これを奴隸のごとくに使役べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, '彼をして傭人または寄寓者のごとくにして汝とともに在しめヨベルの年まで汝に仕へしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, '其時には彼その子女とともに汝の所より出去りその一族にかへりその父祖等の產業に歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, '彼らはエジプトの國より我が導き出せし我の僕なれば身を賣て奴隸となる可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, '汝嚴く彼を使ふべからず汝の神を畏るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, '汝の有つ奴隸は男女ともに汝の四周の異邦人の中より取べし男女の奴隸は是る者の中より買べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'また汝らの中に寄寓る異邦人の子女の中よりも汝ら買ことを得また彼等の中汝らの國に生れて汝らと偕に居る人々の家よりも然り彼等は汝らの所有となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, '汝ら彼らを獲て汝らの後の子孫の所有に遺し之に彼等を有ちてその所有となさしむることを得べし彼等は永く汝らの奴隸とならん然ど汝らの兄弟なるイスラエルの子孫をば汝等たがひに嚴しく相使ふべからす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, '汝の中なる客旅又は寄寓者にして富を致しその傍に住る汝の兄弟零落て汝の中なるその客旅あるひは寄寓者あるひは客旅の家の分支などに身を賣ることあらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'その身を賣たる後に贖はるることを得その兄弟の一人これを贖ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'その伯叔または伯叔の子これを贖ふべくその家の骨肉の親たる者これを贖ふべしまた若能せば自ら贖ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, '然る時は彼己が身を賣たる年よりヨベルの年までをその買主とともに數へその年の數にしたがひてその身の代の金を定むべしまたその人に仕へし日は人を傭ひし日のごとくに數ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, '若なほ遺れる年多からばその數にしたがひまたその買れし金に照して贖の金をその人に償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, '若またヨベルの年までに遺れる年少からばその人とともに計算をなしその年數にてらして贖の金を之に償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, '彼のその人に仕ふる事は歳雇の傭人のごとくなるべし汝の目の前において彼を嚴く使はしむべからす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, '彼もし斯く贖はれずばヨベルのの年にいたりてその子女とともに出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, '是イスラエルの子孫は我の僕なるに因る彼等はわが僕にして我がエジプトの地より導き出せし者なり我は汝らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '汝ら己のために偶像を作り木像を雕刻べからず柱の像を堅べからずまた汝らの地に石像を立て之を拝むべからず其は我は汝らの神ヱホバなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, '汝等わが安息日を守りわが聖所を敬ふべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, '汝等もしわが法令にあゆみ吾が誡命を守りてこれを行はば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, '我その時候に雨を汝らに與ふべし地はその產物を出し田野の樹木はその實を結ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, '是をもて汝らの麥打は葡萄を斂る時にまで及び汝らが葡萄を斂る事は種播時にまでおよばん汝等は飽までに食物を食ひ汝らの地に安泰に住ことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, '我平和を國に賜ふべければ汝等は安じて寝ることを得ん汝等を懼れしむる者なかるべし我また猛き獣を國の中より除き去ん劍なんぢらの國を行めぐることも有じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, '汝等はその敵を逐ん彼等は汝等の前に劍に殞るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, '汝らの五人は百人を逐ひ汝らの百人は萬人を逐あらん汝らの敵は皆汝らの前に劍に殞れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, '我なんぢらを眷み汝らに子を生こと多からしめて汝等を増汝らとむすびしわが契約を堅うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, '汝等は舊き穀物を食ふ間にまた新しき者を穫てその舊き者を出すに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, '我わが幕屋を汝らの中に立ん我心汝らを忌きらはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, '我なんぢらの中に歩みまた汝らの神とならん汝らはまたわが民となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, '我は汝らの神ヱホバ汝らをエジプトの國より導き出してその奴隸たることを免れしめし者なり我は汝らの軛の横木を碎き汝らをして眞直に立て歩く事を得せしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, '然ど汝等もし我に聽したがふ事をなさずこの諸の誡命を守らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'わが法度を蔑如にしまた心にわが律法を忌きらひて吾が諸の誡命をおこなはず却てわが契約を破ることをなさば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, '我もかく汝らになさんすなはち我なんぢらに驚恐を蒙らしむべし癆瘵と熱病ありて目を壞し霊魂を憊果しめん汝らの種播ことは徒然なり汝らの敵これを食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, '我わが面をなんぢらに向て攻ん汝らはその敵に殺されんまた汝らの惡む者汝らを治めん汝らはまた追ものなきに逃ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, '汝ら若かくのごとくなるも猶我に聽したがはずば我汝らの罪を罰する事を七倍重すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, '我なんぢらが勢力として誇るところの者をほろぼし汝らの天を鐵のごとくに爲し汝らの地を銅のごとくに爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, '汝等が力を用ふる事は徒然なるべし即ち地はその產物を出さず國の中の樹はその實を結ばざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, '汝らもし我に敵して事をなし我に聽したがふことをせずば我なんぢらの罪にしたがひて七倍の災を汝らに降さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, '我また野獣を汝らの中に遣るべし是等の者汝らの子女を攫くらひ汝ちの家畜を噬ころしまた汝らの數を寡くせん汝らの大路は通る人なきに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, '我これらの事をもて懲すも汝ら改めずなほ我に敵して事をなさば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, '我も汝らに敵して事をなし汝らの罪を罰することをまた七倍おもくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, '我劍を汝らの上にもちきたりて汝らの背約の怨を報さんまた汝らがその邑々に集る時は汝らの中に我疫病を遣らん汝らはその敵の手に付されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, '我なんぢらが杖とするパンを打くだかん時婦人十人一箇の爐にて汝らのパンを燒き之を稱りて汝らに付さん汝等は食ふも飽ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, '汝らもし是のごとくなるも猶我に聽したがふことをせず我に敵して事をなさば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, '我も汝らに敵し怒りて事をなすべし我すなはち汝らの罪をいましむることを七倍おもくせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, '汝らはその男子の肉を食ひまたその女子の肉を食ふにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, '我なんぢらの崇邱を毀ち汝らの柱の像を斫たふし汝らの偶像の尸の上に汝らの死體を投すて吾心に汝らを忌きらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'またなんぢらの邑々を滅し汝らの聖所を荒さんまた汝らの祭物の馨しき香を聞じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, '我その地を荒すべければ汝らの敵の其處に住る者これを奇しまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, '我なんぢらを國々に散し劍をぬきて汝らの後を追ん汝らの地は荒れ汝らの邑々は亡びん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, '斯その地荒はてて汝らが敵の國に居んその間地は安息を樂まん即ち斯る時はその地やすみて安息を樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, '是はその荒てをる日の間息まん汝らが其處に住たる間は汝らの安息に此休息を得ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'また汝らの中の遺れる者にはその敵の地において我これに恐懼を懐かしめん彼等は木葉の搖く聲にもおどろきて逃げその逃る事は劍をさけて逃るがごとくまた追ものもなきに顛沛ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, '彼等は追ものも無に劍の前にあるが如くたがひに相つまづきて倒れん汝等はその敵の前に立ことを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'なんぢ等はもろもろの國の中にありて滅うせんなんぢらの敵の地なんぢらを呑つくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'なんぢらの中の遺れる者はなんぢらの敵の地においてその罪の中に痩衰へまた己の身につけるその先祖等の罪の中に痩衰へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'かくて後彼らその罪とその先祖等の罪および己が我に悸りし咎と我に敵して事をなせし事を懺悔せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, '我も彼等に敵して事をなし彼らをその敵の地に曳いたりしが彼らの割禮を受ざる心をれて卑くなり甘んじてその罪の罰を受るに至るべければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, '我またヤコブとむすびし吾が契約およびイサクとむすびし吾が契約を追憶しまたアブラハムとむすびしわが契約を追憶し且その地を眷顧ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, '彼等その地を離るべければ地は彼等の之に居る者なくして荒てをる間その安息をたのしまん彼等はまた甘じてその罪の罰を受ん是は彼等わが律法を蔑如にしその心にわが法度を忌きらひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'かれ等斯のごときに至るもなほ我彼らが敵の國にをる時にこれを棄ずまたこれを忌きらはじ斯我かれらを滅ぼし盡してわがかれらと結びし契約をやぶることを爲ざるべし我は彼らの神ヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, '我かれらの先祖等とむすびし契約をかれらのために追憶さん彼らは前に我がその神とならんとて國々の人の目の前にてエジプトの地より導き出せし者なり我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, '是等はすなはちヱホバがシナイ山において己とイスラエルの子孫の間にモーセによりて立たまひし法度と條規と律法なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'イスラエルの子孫につげてこれに言へ人もし誓願をかけなばなんぢの估價にしたがひてヱホバに献納物をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'なんぢの估價はかくすべしすなはち二十歳より六十歳までは男には其價を聖所のシケルに循ひて五十シケルに估り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, '女にはその價を三十シケルに估るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'また五歳より二十歳までは男にはその價を二十シケルに估り女には十シケルに估るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'また一箇月より五歳までは男にはその價を銀五シケルに估り女にはその價を銀三シケルに估るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'また六十歳より上は男にはその價を十五シケルに估り女には十シケルに估るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'その人もし貧くして汝の估價に勝ざる時は祭司の前にいたり祭司の估價をうくべきなり祭司はその誓願者の力にしたがひて估價をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, '人もしそのヱホバに禮物として献ることを爲すとこるの牲畜の中を取り誓願の物となしてヱホバに献る時は其物は都て聖し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, '之を更むべからずまた佳を惡に惡を佳に易べからず若し牲畜をもて牲畜に易ることをせば其と其に易たる者ともに聖なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'もし人のヱホバに禮物として献ることを爲ざるとこるの汚たる畜の中ならばその畜を祭司の前に牽いたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, '祭司はまたその佳惡にしたがひてこれが估價をなすべし即ちその價は祭司の估るところによりて定むべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'その人若これを贖はんとせばその估る價にまた之が五分の一を加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'また人もしその家をヱホバに聖別ささげたる時は祭司その佳惡にしたがひて之が估價を爲べし即ちその價は祭司の估るところによりて定むべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'その人もし家を贖はんとせばその估價の金にまた之が五分の一を加ふべし然せば是は自分の有とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, '人もしその遺業の田野の中をヱホバに献る時は其處に撒るる種の多少にしたがひてこれが估價をなすべし即ち大麥の種一ホメルを五十シケルに算べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'もしその田野をヨベルの年より献たる時はその價は汝の估れる所によりて定むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'もし又その田野をヨベルの後に献たる時は祭司そのヨベルの年までに遺れる年の數にしたがひてその金を算へこれに準じてその估價を減すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'その田野を献たる者若これを贖はんとせばその估價の金の五分の一をこれに加ふべし然せば是はその人に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, '然ど若その田野を贖ふことをせず又はこれを他の人に賣ことをなさば再び贖ふことを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'その田野はヨベルにおよびて出きたる時は永く奉納たる田野のごとくヱホバに歸して聖き者となり祭司の產業とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, '若また自己が買たる田野にしてその遺業にあらざる者をヱホバに献たる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, '祭司その人のために估價してヨベルの年までの金を推算べし彼は汝の估れる金高をその日ヱホバにたてまつりて聖物となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'ヨベルの年にいたればその田野は賣主なるその本來の所有主に歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, '汝の估價はみな聖所のシケルにしたがびて爲べし二十ゲラを一シケルとなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, '但し牲畜の初子はヱホバに歸すべき初子なれば何人もこれを献べからず牛にもあれ羊にもあれ是はヱホバの所屬なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, '若し汚たる畜ならば汝の估價にしたがひこれにその五分の一を加へてその人これを贖ふべし若これを贖ふことをせずば汝の估價にしたがひて之を賣べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, '但し人がその凡て有る物の中より取て永くヱホバに納めたる奉納物は人にもあれ畜にもあれその遺業の田野にもあれ一切賣べからずまた贖ふべからず奉納物はみなヱホバに至聖物たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'また人の中永く奉納られて奉納物となれる者も贖ふべからず必ず殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, '地の十分の一は地の產物にもあれ樹の果にもあれ皆ヱホバの所屬にしてヱホバに聖きなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, '人もしその献る十分の一を贖はんとせば之にまたその五分の一を加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, '牛または羊の十分の一については凡て杖の下を通る者の第十番にあたる者はヱホバに聖き者なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'その佳惡をたづぬべからずまた之を易べからず若これを易る時は其とその易たる者ともに聖き者となるべしこれを贖ふことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, '是等はヱホバがシナイ山においてイスラエルの子孫のためにモーセに命じたまひし誡命なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'エジプトの國を出たる次の年の二月の一日にヱホバ、シナイの野に於て集會の幕屋の中にてモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '汝等イスラエルの子孫の全會衆の惣數をその宗族に依り其父祖の家に循ひて核べその諸の男丁の名の數と頭數とを得よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'すなはちイスラエルの中凡て二十歳以上にして戰爭にいづるに勝る者を汝とアロンその軍旅にしたがひて數ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'また諸の支派おのおのその父祖の家の長たる者一人を出して汝等とともならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, '汝らとともに立べき人々の名は是なり即ちルベンよりはシデウルの子エリヅル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'シメオンよりはツリシヤダイの子シルミエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'ユダよりはアミナダブの子ナシヨン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'イツサカルよりはツアルの子ネタニエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'ゼブルンよりはヘロンの子エリアブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'ヨセフの子等の中にてはエフライムよりはアミホデの子エリシヤマ、マナセよりはバダヅルの子ガマリエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'ベニヤミンよりはギデオニの子アビダン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'ダンよりはアミシヤダイの子アヒエゼル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'アセルよりはオクランの子バギエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'ガドよりはデウエルの子エリアサフ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'ナフタリよりはエナンの子アヒラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, '是等は會衆の中より選み出されし者にてその父祖の支派の牧伯またイスラエルの千人の長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'かくてモーセとアロンここに名を擧たる人々を率領て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, '二月の一日に會衆をことごとく集めければ彼等その宗族に循ひその父祖の家にしたがひその名の數にしたがひて自分の出生を述たりかく二十歳以上の者ことごとく核へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'ヱホバの命じたまひしごとくモーセ、シナイの野にて彼等を核數たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'すなはちイスラエルの長子ルベンの子等より生れたる者をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるに其名の數に依りその頭數によれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'ルベンの支派の中にその核數られし者四萬六千五百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'またシメオンの子等より生れたる者等をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數に依りその頭數に依ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'シメオンの支派の中にその核數られし者五萬九千三百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'またガドの子等より生れたる者をその宗族に依りその父祖の家にしたがひて核べ二十歳以上にして戰爭に出るに勝る男丁を數へたるにその名の數に依れば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'ガドの支派の中にその核數られし者四萬五千六百五十人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'ユダの子等より生れたる者をその宗族に依りその父祖の家に循ひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數に依れば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'ユダの支派の中にその核數られし者七萬四千六百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'イツサカルの子等より生れたる者をその宗族に依りその父祖の家にしたがひて核べ二十歳以上にして戰爭に出るに勝る男丁を數へたるにその名の數に依ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'イツサカルの支派の中にその核數られし者五萬四千四百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'ゼブルンの子等より生れたる者をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數によれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'ゼブルンの支派の中に其核數られし者五萬七千四百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'ヨセフの子等の中エフライムの子等より生れたる者をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數に依ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'エフライムの支派の中にその核數られし者四萬五百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, '又マナセの子等より生れたる者をその宗族に依りその父祖の家に循ひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數に依ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'マナセの支派の中にその核數られし者三萬二千二百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'ベニヤミンの子等より生れたる者をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數によれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'ベニヤミンの支派の中にその數へられし者三萬五千四百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'ダンの子等より生れたる者をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數によれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'ダンの支派の中にその核數られし者六萬二千七百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'アセルの子等より生れたる者をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數によれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'アセルの支派の中にその核數られし者四萬一千五百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'ナフタリの子等より生れたる者をその宗族によりその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁を數へたるにその名の數によれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'ナフタリの支派の中にその數へられし者五萬三千四百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, '是すなはちその核數られし者にしてモーセとアロンとイスラエルの牧伯等の數ふる所是のごとしその牧伯等は十二人にして各々その父祖の家のために出たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, '斯イスラエルの子孫をその父祖の家にしたがひて核べ二十歳以上にして戰爭にいづるに勝る男丁をイスラルの中に數へたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, '其核數られし者都合六十萬三千五百五十人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, '但しレビの支派の人はその父祖にしたがひて核數らるること無りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, '即ちヱホバ、モーセに告て言たまひけらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '惟レビの支派のみは汝これを核數べからずまたその總數をイスラエルの子孫とともに計ふべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'なんぢレビ人をして律法の幕屋とその諸の器具と其に屬する諸の物を管理らしむべし彼等はその幕屋とその諸の器具を運搬ぶことを爲しまたこれが役事を爲し幕屋の四圍にその營を張べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, '幕屋を移す時はレビ人これを折卸し幕屋を立る時はレビ人これを組たつべし外人のこれに近く者は殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'イスラエルの子孫はその軍旅に循ひて各々自己の營にその天幕を張り各人その隊の纛の下に天幕を張べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, '然どレビ人は律法の幕屋の四圍に營を張べし是イスラエルの子孫の全會衆の上に震怒のおよぶことなからん爲なりレビ人は律法の幕屋をあづかり守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, '是においてイスラエルの子孫ヱホバのモーセに命じたまひしごとくに凡て爲し斯おこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'ヱホバ、モーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'イスラエルの子孫は各々その隊の纛の下に營を張てその父祖の旗號の下に居るべくまた集會の幕屋の四圍において之にむかひて營を張べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, '即ち日の出る方東に於てはユダの營の纛の下につく者その軍旅にしたがひて營を張りアミナダブの子ナシヨン、ユダの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'その軍旅すなはちその核數られし者は七萬四千六百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'その傍に營を張る者はイツサカルの支派なるべし而してツアルの子ネタニエル、イツサカルの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'その軍旅すなはちその核數られし者は五萬四千四百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'またゼブルンの支派これと偕にありてヘロンの子エリアブ、ゼブルンの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'その軍旅すなはちその核數られし者は五萬七千四百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'ユダの營の軍旅すなはち核數られし者は都合十八萬六千四百人是等の者首先に進むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'また南の方に於てはルベンの營の纛の下につく者その軍旅にしたがひて居りシデウルの子エリヅル、ルベンの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'その軍旅すなはちその核數られし者は四萬六千五百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'その傍に營を張る者はシメオンの支派なるべし而してツリシヤダイの子シルミエル、シメオンの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'その軍旅すなはちその核數られし者は五萬九千三百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'ガドの支派これに次ぎデウエルの子エリアサフ、ガドの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'その軍旅すなはちその核數られし者は四萬五千六百五十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'ルベンの營の軍旅すなはちその核數られし者は都合十五萬一千四百五十人是等の者第二番に進むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'その次に律法の幕屋レビ人の營とともに諸營の眞中にありて進むべし彼等はその營を張がごとくに各々その隊にしたがひその纛にしたがひて進むべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'また西の方においてはエフライムの營の纛の下につく者その軍旅にしたがひて居りアミホデの子エリシヤマ、エフライムの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'その軍旅すなはちその核數られし者は四萬五百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'マナセの支派その傍にありてバダヅルの子ガマリエル、マナセの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'その軍旅すなはちその核數られし者は三萬二千二百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'ベニヤミンの支派これに次ぎギデオニの子アビダン、ベニヤミンの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'その軍旅すなはちその數へられし者は三萬五千四百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'ヱフライムの營の軍旅すなはちその核數られし者は都合十萬八千一百人是等の者第三番に進むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'また北の方に於てはダンの營の纛の下につく者その軍旅に循ひて居りアミシヤダイの子アヒエゼル、ダンの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'その軍旅すなはちその核數られし者は六萬二千七百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'その傍に營を張る者はアセルの支派なるべし而してオクランの子パギエル、アセルの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'その軍旅すなはちその核數られし者は四萬一千五百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'ナフタリの支派これに次ぎエナンの子アヒラ、ナフタリの子孫の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'その軍旅すなはちその核數られし者は五萬三千四百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'ダンの營の核數られし者は都合十五萬七千六百人是等の者その旗號にしたがひて最後に進むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'イスラエルの子孫のその父祖の家にしたがひて核數られし者は是のごとし諸營の軍旅すなはちその核數られし者は都合六十萬三千五百五十人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, '但しレビ人はイスラエルの子孫とともに計へらるること無りきすなはちヱホバのモーセに命じたまへる如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, '是においてイスラエルの子孫ヱホバの凡てモーセに命じたまひしごとくに行ひ各々その宗族に依りその父祖の家に依りその隊の纛にしたがひて營を張りまた進むことを爲せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'ヱホバ、シナイ山に於てモーセと語ひたまへる日にはアロンとモーセの一族左のごとくにてありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'アロンの子孫は是のごとし長子はナダブ次はアビウ、エレアザル、イタマル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, '是すなはちアロンの子等の名なり彼等は皆膏そそがれ祭司の職に任ぜられて祭司となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'ナダブとアビウはシナイの野にて異火をヱホバの前に献たる時にヱホバの前に死り子なしエレアザルとイタマルはその父アロンの目の前にて祭司の職を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'レビの支派を召よせ祭司アロンの前に侍りてこれに事へしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, '彼らは集會の幕屋の前にありてアロンの職と全會衆の職に替り幕屋の役事をなすべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'すなはち彼等は集會の幕屋の諸の器具を看守イスラエルの子孫の職に替りて幕屋の役事をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, '汝レビ人をアロンとその子等に與ふべしイスラエルの子孫の中より彼等は全くアロンに與へられたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, '汝アロンとその子等を立て祭司の職を行はしむべし外人の近づく者は殺されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'ヱホバすなはちモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '視よ我イスラエルの子孫の中なる始に生れたる者すなはち首出の代にレビ人をイスラエルの子孫の中より取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, '首出はすべて吾が有なり我エジプトの國の中の首出をことごとく撃ころせる時イスラエルの首出を人も畜もことごとく聖別て我に歸せしめたり是はわが有となるべし我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'ヱホバ、シナイの野にてモーセに告ていひたまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '汝レビの子孫をその父祖の家に依りその宗族にしたがひて核數よ即ちその一箇月以上の男子を核數べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, '是においてモーセ、ヱホバの言に循ひてその命ぜられしごとくに之を核數たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'レビの子等の名は左のごとしゲルシヨン、コハテ、メラリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'ゲルシヨンの子等の名はその宗族によれば左の如しリブニ、シメイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'コハテの子等の名はその宗族に依ば左のごとしアムラム、イヅハル、ヘブロン、ウジエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'メラリの子等の名はその宗族によればマヘリ、ムシなりレビ人の宗族はその父祖の家に依ば是のごとくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'ゲルシヨンよりリブニ人の族とシメイ人の族出たり是すなはちゲルシヨン人の族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'その核數られし者の數すなはち一箇月以上の男子の數は都合七千五百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'ゲルシヨン人の族は凡て幕屋の後すなはち西の方に營を張べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, '而してラエルの子エリアサフ、ゲルシヨン人の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, '集會の幕屋におけるゲルシヨンの子孫の職守は幕屋と天幕とその頂蓋および集會の幕屋の入口の幔と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, '庭の幕および幕屋と壇の周圍なる庭の入口の幔ならびにその繩等凡て之に用ふる物を守るべき事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'またコハテよりアムラミ人の族イヅハリ人の族ヘブロン人の族ウジエリ人の族出たり是すなはちコハテ人の族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, '一箇月以上の男子の數は都合八千六百人是みな聖所の職守を守るべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'コハテの子孫の族は凡て幕屋の南の方に營を張べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, '而してウジエルの子エリザパン、コハテ人の族の牧伯となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, '彼等の職守は律法の櫃案燈臺諸壇および聖所の役事に用ふる器具ならびに幔等凡て其處に用ふる物を守るべき事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, '祭司アロンの子エレアザル、レビ人の牧伯の長となり且聖所の職を守る者を統轄るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, '又メラリよりマヘリ人の族とムシ人の族出たり是すなはちメラリの族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'その核數られし者すなはち一箇月以上の男子の數は六千二百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'アビハイルの子ツリエル、メラリの族の牧伯となり此族幕屋の北の方に營を張べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'メラリの子孫の管理るべき者職守とすべき者は幕屋の板とその横木その柱その座その諸の器具および其に用ふる一切の物');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'ならびに庭の周圍の柱とその座その釘およびその繩なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'また幕屋の前その東の方すなはち集會の幕屋の東の方にはモーセとアロンおよびアロンの子等營を張りイスラエルの子孫の職守に代て聖所の職守を守るべし外人の近づく者は殺されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'モーセとアロン、ヱホバの言に依りレビ人を悉く核數たるに一箇月以上の男子の數二萬二千ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'ヱホバまたモーセに言たまはく汝イスラエルの子孫の中の首出たる男子の一箇月以上なる者を盡く數へてその名の數を計れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, '我はヱホバなり我ために汝レビ人を取りてイスラエルの子孫の中なる諸の首出子に代へまたレビ人の家畜を取てイスラエルの子孫の家畜の中なる諸の首出に代べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'モーセすなはちヱホバの己に命じたまへるごとくにイスラエルの子孫の中なる首出子を盡く數へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'その數へられし首出なる男子の一箇月以上なる者はその名の數に依ば都合二萬二千二百七十三人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'すなはちヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '汝レビ人を取てイスラエルの子孫の中なる諸の首出子に代へまたレビ人の家畜を取て彼等の家畜に代よレビ人はわが所有とならん我はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'またイスラエルの子孫の首出子はレビ人より多きこと二百七十三人なれば是等をば贖ふべき者となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'その頭數に依て一人ごとに五シケルを取べし即ち聖所のシケルに循ひて之を取べきなり一シケルは二十ゲラなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, '汝その餘れる者の贖の金をアロンとその子等に付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, '是においてモーセ、レビ人をもて贖ひ餘せるところの者の贖の金を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, '即ちモーセ、イスラエルの子孫の首出子の中より聖所のシケルにしたがひて金千三百六十五シケルを取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'その贖はるる者の金をヱホバの言にしたがひてアロンとその子等に付せりヱホバのモーセに命じたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'ヱホバまたモーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'レビの子孫の中よりコハテの子孫の總數をその宗族に依りその父祖の家にしたがひて計べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, '三十歳以上五十歳までにして能く軍団に入り集會の幕屋に働作をなすことを得る者をことごとく數へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'コハテの子孫が集會の幕屋においてなすべき勤務は至聖物に關る者にして是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, '即ち營を進むる時はアロンとその子等まづ往て障蔽の幕を取おろし之をもて律法の櫃を覆ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'その上に獾の皮の蓋をほどこしまたその上に總靑の布を打かけその杠を差いるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'また供前のパンの案の上には靑き布を打かけその上に皿匙杓および酒を灌ぐ斝を置きまた常供のパンをその上にあらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, '紅の布をその上に打かけ獾の皮の蓋をもてこれを覆ひ而してその杠を差いるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'また靑き布を取て燈臺とその盞その燈鉗その剪燈盤および其に用ふる諸の油の器を覆ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, '獾の皮の蓋の内に燈臺とその諸の器をいれてこれを棹にかくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'また金の壇の上に靑き布を打かけ獾の皮の蓋をもて之を蓋ひその杠を差いるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'また聖所の役事に用ふる役事の器をことごとく取靑き布に裹み獾の皮の蓋をもてこれを蓋ひて棹にかくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'また壇の灰を取さりて紫の布をその壇に打かけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'その上に役事をなすに用ふる諸の器具すなはち火鼎肉叉火鏟鉢および壇の一切の器具をこれに載せ獾の皮の蓋をその上に打かけ而してその杠を差とほすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, '營を進むるにあたりてアロンとその子等聖所と聖所の一切の器具を蓋ふことを畢りたらば即ちコハテの子孫いり來りてこれを舁べし然ながら彼等は聖物に捫るべからず恐くは死ん集會の幕屋の中なる是等の物はコハテの子孫の擔ふべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, '祭司アロンの子エレアザルは燈火の油馨しき香常供の素祭および灌膏を司どりまた幕屋の全體とその中なる一切の聖物および其處の諸の器具を司どるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'ヱホバまたモーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '汝等コハテ人の宗族の者をしてレビ人の中より絶るるに至らしむる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, '彼等が至聖物に近く時に生命を保ちて死ることなからん爲に汝等かく之に爲べし即ちアロンとその子等まづ入り彼等をして各箇その役事に就しめその擔ふべき物を取しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, '彼等は入て須臾も聖物を觀るべからず恐らくは死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '汝ゲルシヨンの子孫の總數をその父祖の家に依りその宗族に循ひてしらべ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, '三十歳以上五十歳までにして能く軍團に入り集會の幕屋に動作をなすことを得る者をことごとく數へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'ゲルシヨン人の働く事と擔ふ物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, '即ち彼等は幕屋の幕と集會の天幕およびその頂蓋とその上なる貛の皮の蓋ならびに集會の天幕の入口の幔を擔ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, '庭の幕および幕屋と壇の周圍なる庭の門の入口の幔とその繩ならびにそれに用ふる諸の器具と其がために造る一切の物を擔ふべし斯動作べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'ゲルシヨンの子孫の一切の役事すなはちその擔ふところと働くところはアロンとその子等の命に循ふべきなり汝等は彼等にその擔ふべき物を割交してこれを守らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'ゲルシヨンの子孫の宗族が集會の幕屋において爲べき動作は是のごとし彼等の守る所は祭司アロンの子イタマルこれを監督るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'メラリの子孫もまた汝これをその宗族に依りその父祖の家に循ひて計べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, '三十歳以上五十歳までにして能く軍團に入り集會の幕屋において勤務をなすことを得る者を盡く數へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, '彼等が集會の幕屋において爲べき一切の役事すなはちその擔ひ守るべき物は是のごとし幕屋の板その横木その柱その座');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, '庭の四周の柱その座その釘その繩およびこれがために用ふる一切の器具なり彼等が擔ひ守るべき器具は汝等その名を按べて之を數ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, '是すなはちメラリの子孫の族がなすべき役事にして彼等は祭司アロンの子イタマルの監督をうけて集會の幕屋において此すべての役事を爲べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, '是においてモーセとアロンおよび會衆の牧伯等コハテの子孫をその宗族に依りその父祖の家にしたがひてしらべ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, '三十歳以上五十歳までにして能く軍團に入り集會の幕屋において勤務をなすことを得る者を盡く數へたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'その宗族にしたがひて數へられし者二千七百五十人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, '是すなはちコハテ人の族の數へられし者にして皆集會の幕屋に於て役事をなすことを得る者なりモーセとアロン、ヱホバがモーセによりて命じたまひし所にしたがひて之を數へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'またゲルシヨンの子孫をその宗族に依りその父祖の家に循ひて計べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, '三十歳以上五十歳までにして能く軍團に入り集會の幕屋において勤務をなすことを得る者を數へたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'その宗族に依りその父祖の家に循ひて數へられし者二千六百三十人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, '是すなはちゲルシヨンの子孫の族の數へられし者にして皆集會の幕屋において勤務をなすことを得る者なりモーセとアロン、ヱホバの命にしたがひて之を數へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'またメラリの子孫の族をその宗族に依りその父祖の家に循ひて計べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, '三十歳以上五十歳までにして能く軍團に入り集會の幕屋において勤務をなすことを得る者を數へたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'その宗族にしたがひて數へられし者三千二百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, '是すなはちメラリの子孫の族の數へられし者なりモーセとアロン、ヱホバのモーセによりて命じたまひし所にしたがひて之を數へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'モーセとアロンおよびイスラエルの牧伯等レビ人をその宗族に依りその父祖の家にしたがひてしらべ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, '三十歳以上五十歳までにして能く來りて集會の幕屋の役事を爲し且これを擔ふ業を爲す者を數へたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'その數へられしものの數都合八千五百八十人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'ヱホバの命にしたがひてモーセかれらを數へ彼等をして各人その役事に就しめかつその擔ふ所をうけもたしめたりヱホバの命にしたがひて數へたるところ是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'イスラエルの子孫に命じて癩病人と流出ある者と死骸に汚されたる者とを盡く營の外に出さしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, '男女をわかたず汝等これを出して營の外に居しめ彼等をしてその營を汚さしむべからず我その諸營の中に住なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'イスラエルの子孫かく爲して之を營の外に出せりすなはちヱホバのモーセに告たまひし如くにイスラエルの子孫然なしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'イスラエルの子孫に告よ男または女もし人の犯す罪を犯してヱホバに悖りその身罪ある者とならば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'その犯せし罪を言あらはしその物の代價にその五分の一を加へてこれを己が罪を犯せる者に付してその償を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, '然ど若その罪の償を受べき親戚その人にあらざる時はその罪の償をヱホバになして之を祭司に歸せしむべしまた彼のために用ひて贖をなすところの贖罪の牡羊も祭司に歸す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'イスラエルの子孫の擧祭となして祭司に携へ來る所の聖物は皆祭司に歸す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, '諸の人の聖別て献る物は祭司に歸し凡て人の祭司に付す物は祭司に歸するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'イスラエルの子孫に告てこれに言へ人の妻道ならぬ事を爲てその夫に罪を犯すあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, '人かれと交合したるにその事夫の目にかくれて露顯ず彼その身を汚したれどこれが證人となる者なく彼またその時に執へられもせざるあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'すなはち妻その身を汚したる事ありて夫猜疑の心を起してその妻を疑ふことあり又は妻その身を汚したる事なきに夫猜疑の心を起してその妻を疑ふことある時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, '夫その妻を祭司の許に携へきたり大麥の粉一エパの十分の一をこれがために禮物として持きたるべしその上に油を灌べからずまた乳香を加ふべからず是は猜疑の禮物記念の禮物にして罪を誌えしむる者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, '祭司はまたその婦人を近く進ませてヱホバの前に立しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, '瓦の器に聖水を入れ幕屋の下の地の土を取てその水に放ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, '其婦人をヱホバの前に立せ婦人にその頭を露さしめて記念の禮物すなはち猜疑の禮物をその手に持すべし而して祭司は詛を來らするとこるの苦き水を手に執り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, '婦を誓せてこれに言べし人もし汝と寝たる事あらず汝また汝の夫を措て道ならぬ事を爲て汚穢に染しこと無ば詛を來する此苦水より害を受ること有ざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, '然ど汝もし汝の夫を措き道ならぬ事を爲てその身を汚し汝の夫ならざる人と寝たる事あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '(祭司その婦人をして詛を來らする誓をなさしめて祭司その婦人に言べし)ヱホバ汝の腿を痩しめ汝の腹を脹れしめ汝をして汝の民の指て詛ふ者指て誓ふ者とならしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'また詛を來らするこの水汝の腸にいりて汝の腹を脹れさせ汝の腿を痩させんとその時婦人はアーメン、アーメンと言べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, '而して祭司この詛を書に筆記しその苦水にて之を洗おとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, '婦人をしてその詛を來らする水を飮しむべしその詛を來らする水かれの中にいりて苦ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, '祭司まづその婦人の手より猜疑の禮物を取りその禮物をヱホバの前に搖てこれを壇に持來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, '而して祭司其禮物の中より記念の分一握をとりて之を壇の上に焚き然る後婦人にその水を飮しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'その水を之に飮しめたる時はもしかれその身を汚し夫に罪を犯したる事あるに於てはその詛を來らする水かれの中に入て苦くなりその腹脹れその腿痩て自己はその民の指て詛ふ者とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, '然ど彼もしその身を汚しし事あらずして潔からば害を受ずして能く子を生ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, '是すなはち猜疑の律法なり妻たる者その夫を措き道ならぬ事を爲て身を汚しし時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'また夫たる者猜疑の心を起してその妻を疑ふ時はその婦人をヱホバの前におきて祭司その律法のごとく之に行ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, '斯せば夫は罪なく妻はその罪を任ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'イスラエルの子孫に告て之に言へ男または女俗を離れてナザレ人の誓願を立て俗を離れてその身をヱホバに歸せしむる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, '葡萄酒と濃酒を斷ち葡萄酒の醋となれる者と濃酒の醋となれる者を飮ずまた葡萄の汁を飮ず葡萄の鮮なる者をも乾たる者をも食はざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'その俗を離れをる日の間は都て葡萄の樹より取たる者はその核より皮まで一切食ふべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'その誓願を立て俗を離れをる日の間は都て薙刀をその頭にあつべからずその俗を離れて身をヱホバに歸せしめたる日の滿るまで彼は聖ければその頭髮を長しおくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'その俗を離れて身をヱホバに歸せしむる日の間は凡て死骸に近づくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, '其父母兄弟姉妹の死たる時にもこれがために身を汚すべからず其はその俗を離れて神に歸したる記號その首にあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, '彼はその俗を離れをる日の間は凡てヱホバの聖者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'もし人計ずも彼の傍に死てそのナザレの頭を汚すことあらばその身を潔る日に頭を剃べしすなはち第七日にこれを剃べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, '而して第八日に鳲鳩二羽かまたは雛き鴿二羽を祭司に携へきたり集會の幕屋の門にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, '斯て祭司はその一を罪祭に一を燔祭に献げ彼が屍に由て獲たる罪を贖ひまたその日にかれの首を聖潔すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, '彼またその俗を離れてヱホバに歸するの日を新にし當歳の羔羊を携へきたりて愆祭となすべし彼その俗を離れをる時に身を汚したれば是より前の日はその中に算ふべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'ナザレ人の律法は是のごとしその俗を離るるの日滿たる時はその人を集會の幕屋の門に携へいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, '斯てその人は禮物をヱホバにささぐべし即ち當歳の羔羊の牡の全き者一匹を燔祭となし當歳の羔羊の牝の全き者一匹を罪祭となし牡羊の全き者一匹を酬恩祭となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'また無酵パン一筐麥粉に油を和て作れる菓子油を塗たる酵いれぬ煎餅およびその素祭と灌祭の物を持きたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, '斯て祭司これをヱホバの前に携へきたりその罪祭と酬恩祭を献げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'またその牡羊を筐の中なる酵いれぬパンとあはせこれを酬恩祭の犠牲としヱホバに献ぐべし祭司またその素祭と灌祭をも献ぐべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'ナザレ人は集會の幕屋の門に於てそのナザレの頭を剃りそのナザレの頭の髮を取てこれを酬恩祭の犠牲の下の火に放つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, '祭司その牡羊の煮たる肩と筐の中の酵いれぬ菓子一箇と酵いれぬ煎餅一箇をとりてこれをナザレ人がそのナザレの頭を剃におよびてこれをその手に授け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, '而して祭司ヱホバの前にて之を搖て搖祭となすべし是は聖物にしてその搖る胸と擧たる腿とともに祭司に歸すべし斯て後ナザレ人は洒を飮ことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, '是すなはち誓願を立たるナザレ人がその俗を離れ居し事によりてヱホバに禮物を献ぐるの律法なり此外にまたその能力の及ぶところの物を献ぐることを得べし即ちその立たる誓願のごとくその俗を離るるの律法にしたがひて爲べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'アロンとその子等に告て言へ汝等斯のごとくイスラエルの子孫を祝して言べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, '願くはヱホバ汝を惠み汝を守りたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, '願くはヱホバその面をもて汝を照し汝を憐みたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, '願くはヱホバその面を擧て汝を眷み汝に平安を賜へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'かくして彼等吾名をイスラエルの子孫に蒙らすべし然ば我かれらを惠まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'モーセ幕屋を建をはり之に膏を灌ぎてこれを聖別めまたその一切の器具およびその壇とその一切の器具に膏を灌ぎて之を聖別たる日に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'イスラエルの牧伯等すなはちその諸宗族の長諸支派の牧伯にしてその核數られし者を監督る者等献物を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, '彼等その禮物をヱホバに持きたるに蓋ある車六輛と牛十二匹あり牧伯二人に車一輛一人に牛一匹なり即ちこれか幕屋の前にひき至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, '時にヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '汝これを彼等より取て集會の幕屋の用に供へレビ人にその職分職分にしたがひて之を授すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, '是においてモーセその車と牛を取て之をレビ人に授せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, '即ちゲルシヨンの子孫にはその職分を按へて車二輛と牛四匹を授し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'メラリの子孫にはその職分を按へて車四輛と牛八匹を授し祭司アロンの子イタマルをしてこれを監督らしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, '然どコハテの子孫には何をも授さざりき是は彼等が聖所になすべき職分はその肩をもて擔ふの事なるが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, '壇に膏を灌ぐ日に牧伯等壇奉納の禮物を携へ來り牧伯等その禮物を壇の上に献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'ヱホバ先にモーセに言たまひけるは牧伯等は一日に一人宛その壇奉納の禮物を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, '第一日に禮物を献げし者はユダの支派のアミナダブの子ナシヨンなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふ此二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹アミナダブの子サションの禮物は是の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, '第二日にはイッサカルの牧伯ツアルの子ネタニエル献納を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'その献げし禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふ此二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹ツアルの子ネタニエルの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, '第三日にはゼブルンの子孫の牧伯ヘロンの子エリアブ献納を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふ此二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹ヘロンの子エリアブの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, '第四日にはルベンの子孫の牧伯シデウルの子エリヅル献納を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふ此二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹シデウルの子エリヅルの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, '第五日にはシメオンの子孫の牧伯ツリシヤダイの子シルミエル献物を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふ此二者には麥粉に油を和たる素祭の品を充す');
