INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹ツリシヤダイの子シルミエルの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, '第六日にはガドの子孫の牧伯デウエルの子エリアサフ献納をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふこの二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹デウエルの子エリアサフの禮物はかくのごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, '第七日にはエフライムの子孫の牧伯アミホデの子エリシヤマ献納をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふ此二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹アミホデの子エリシヤマの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, '第八日にはマナセの子孫の牧伯パダヅルの子ガマリエル献納をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケルみな聖所のシケルに循ふこの二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹パダヅルの子ガマリエルの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, '第九日にはベニヤミンの子孫の牧伯ギデオニの子アビダン献納をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケルみな聖所のシケルに循ふこの二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹ギデオニの子アビダンの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, '第十日にはダンの子孫の牧伯アミシヤダイの子アヒエゼル献納をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケル皆聖所のシケルに循ふこの二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹アミシヤダイの子アヒエゼルの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, '第十一日にはアセルの子孫の牧伯オクランの子パギエル献納を爲せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'その禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケルみな聖所のシケルに循ふこの二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, '亦金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, '亦燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹オクランの子パギエルの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, '第十二日にはナフタリの子孫の牧伯エナンの子アヒラ献物をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, '其禮物は銀の皿一箇その重は百三十シケル銀の鉢一箇是は七十シケルみな聖所のシケルに循ふこの二者には麥粉に油を和たる素祭の品を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'また金の匙の十シケルなる者一箇是には香を充す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'また燔祭に用ふる若き牡牛一匹牡羊一匹當歳の羔羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, '罪祭に用ふる牡山羊一匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, '酬恩祭の犠牲に用ふる牛二匹牡羊五匹牡山羊五匹當歳の羔羊五匹エナンの子アヒラの禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, '是すなはち壇に油を灌げる日にイスラエルの牧伯等が献げたる壇奉納の禮物なり即ち銀の皿十二銀の鉢十二金の匙十二');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, '銀の皿は各々百三十シケル鉢は各々七十シケル聖所のシケルに依ばこの諸の銀の器はその重都合二千四百シケルなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'また香を充せる金の匙十二ありその重は聖所のシケルに依ば各々十シケルその匙の金は都合百二十シケルなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'また燔祭に用ふる者は牡牛十二牡羊十二當歳の羔羊十二ありき之にその素祭の物を加ふまた罪祭の牡山羊十二あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'また酬恩祭の犠牲に用ふる者は牡牛二十四牡羊六十牡山羊六十當歳の羔羊六十あり壇に膏を灌ぎて後に献たる壇奉納の禮物は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, '斯てモーセはヱホバと語はんとて集會の幕屋に入けるに律法の櫃の上なる贖罪所の上兩箇のケルビムの間より聲いでて己に語ふを聽り即ち彼と語へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'アロンに告て之に言へ汝燈火を燃す時は七の燈盞をして均く燈臺の前を照さしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'アロンすなはち然なし燈火を燈臺の前の方にむけて燃せりヱホバのモーセに命じたまへる如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, '燈臺の作法は是のごとし是は槌にて椎て作れる者即ちその臺座よりその花まで槌にて椎て作れる者なりモーセ、ヱホバの己に示したまへる式樣にてらしてこの燈臺を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'レビ人をイスラエルの子孫の中より取てこれを潔めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, '汝かく彼らに爲て之を潔むべし即ち罪を潔むる水を彼等に灑ぎかけ彼等にその身をことごとく剃しめその衣服を洗はしめて之を潔め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, '而して彼等に若き牡牛一匹と麥粉に油を和たる者を取しめよ汝また別に若き牡牛を罪祭のために取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, '斯て汝レビ人を集會の幕屋の前に携きたりてイスラエルの子孫の全會を集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, '而してレビ人をヱホバの前に進ましめてイスラエルの子孫に其手をレビ人の上に按しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, '而してイスラエルの子孫の爲にレビ人を搖祭となしてヱホバの前に献ぐべし是彼らをしてヱホバの勤務を爲しめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, '斯て汝レビ人にその手をかの牛の頭に按しめその一を燔祭となしてヱホバに献げ之をもてレビ人のために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, '即ちレビ人をアロンとその子等の前に立しめ之を搖祭となしてヱホバに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, '汝レビ人をイスラエルの子孫の中より區分ちレビ人をしてわが所屬とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, '斯て後レビ人は入て集會の幕屋の役事をなすべし汝かれらを潔め之を献げて搖祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, '彼らはイスラエルの子孫の中よりして我に献げらるる者なりイスラエルの子孫の中なる始に生れたる者すなはちその首出子の代に我かれらを取なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'イスラエルの子孫の中の首出子は人たるも獣たるも凡てわが所屬となるべし其は我エジプトの地において首出子を盡く撃ころしたる時に彼等を聖者となして我に屬せしめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, '是をもて我イスラエルの子孫の中の一切の首出子の代にレビ人を取なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, '我イスラエルの子孫の中よりレビ人を取て之をアロンとその子等に與へ之をして集合の幕屋においてイスラエルの子孫に代てその役事を爲しめまたイスラエルの子孫のために贖罪をなさしめん是イスラエルの子孫が聖所に近く時にイスラエルの子孫の中に災害の起ざらんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'モーセとアロンおよびイスラエルの子孫の全會衆ヱホバがレビ人の事につきてモーセに命じたまへる所に悉くしたがひてレビ人におこなへり即ちイスラエルの子孫かくの如く彼等に行ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'レビ人是に於てその身を潔め衣服を洗ひたればアロンかれらをヱホバの前に献て搖祭となしアロンまた彼らのために贖罪をなして之を潔めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, '斯て後レビ人は集會の幕屋に入てアロンとその子等の前にてその役事を爲り彼等はレビ人の事につきてヱホバのモーセに命じたまへる所に循ひて斯のごとく之を行ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'レビ人は斯なすべし即ち二十五歳以上の者は軍団に入て集會の幕屋の役事をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, '然ど五十歳よりは軍団を退きて休み重て役事をなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, '唯集會の幕屋においてその兄弟等をつかさどり且伺ひ守ることを勤むべし役事を爲すべからず汝レビ人をしてその職務をなさしむるには斯のごとくなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'エジプトの國を出たる次の年の正月ヱホバ、シナイの野にてモーセに告ていひたまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'イスラエルの子孫をして逾越節をその期におよびて行はしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, '其期即ち此月の十四日の晩にいたりて汝等これを行ふべし汝等これをおこなふにはその諸の條例とその諸の式法に循ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, '是においてモーセ、イスラエルの子孫に逾越節を行ふべき事を告たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, '彼等正月の十四日の晩にシナイの野にて逾越節を行へり即ちイスラエルの子孫はヱホバのモーセに命じたまへる所に盡く循ひてこれを爲ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, '時に人の死骸に身を汚して逾越節を行ふこと能ざる人々ありてその日にモーセとアロンの前にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'その人々すなはち彼に言ふ我等は人の死骸に身を汚したり然ば我らはその期におよびてイスラエルの子孫と偕にヱホバに禮物を献ることを得ざるべき乎');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'モーセかれらに言けるは姑く待てヱホバ汝らの事を如何に宣ふかを聽ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'イスラエルの子孫に告て言へ汝等または汝等の子孫の中死屍に身を汚したる人も遠き途にある人も皆逾越節をヱホバにむかひて行ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, '即ち二月の十四日の晩に之をおこなひ酵いれぬパンと苦菜をそへて之を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, '朝までこれを少許も遺しおくべからず又その骨を一本も折べからず逾越節の諸の條例にしたがひて之を行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, '然ど人その身潔くありまた征途にもあらずして逾越節を行ふことをせざる時はその人民の中より斷れん斯る人はその期におよびてヱホバの禮物を持きたらざるが故にその罪を任べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, '他國の人もし汝らの中に寄寓をりて逾越節をヱホバにおこなはんとせば逾越節の條例に依りその法式にしたがひて之をおこなふべし他國の人にも自國の人にもその條例は同一なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, '幕屋を建たる日に雲幕屋を蔽へり是すなはち律法の幕屋なり而して夕にいたれば幕屋の上に火のごとき者あらはれて朝におよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, '即ち常に是のごとくにして晝は雲これを蔽ひ夜は火のごとき者ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, '雲幕屋を離れて上る時はイスラエルの子孫直に途に進みまた雲の止まる所にイスラエルの子孫營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, '即ちイスラエルの子孫はヱホバの命によりて途に進みまたヱホバの命によりて營を張り幕屋の上に雲の止まれる間は營を張をれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, '幕屋の上に雲の止ること日久しき時はイスラエルの子孫ヱホバの職守をまもりて途に進まざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'また幕屋の上に雲の止まる事日少き時も然り彼等は只ヱホバの命にしたがひて營を張りヱホバの命にしたがひて途に進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'また雲夕より朝まで止り朝におよびてその雲昇る時は彼等途に進めり夜にもあれ晝にもあれ雲の昇る時は即ち途に進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, '二日にもあれ一月にもあれまたは其よりも多くの日にもあれ幕屋の上に雲の止り居る間はイスラエルの子孫營を張居て途に進まずその昇るにおよびて途に進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, '即ち彼等はヱホバの命にしたがひて營を張りヱホバの命にしたがひて途に進み且モーセによりて傳はりしヱホバの命にしたがひてヱホバの職守を守れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '汝銀の喇叭二本を製れ即ち槌にて椎て之を製り之を用ひて人を呼集めまた營を進ますべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'この二者を吹ときは全會衆集會の幕屋の門に集りて汝に就べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'もし只その一を吹く時はイスラエルの千人の長たるその牧伯等集りて汝に就べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, '汝等これを吹鳴す時は東の方に營を張る者途に進むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'また二次これを吹ならす時は南の方に營を張る者途に進むべし凡て途に進まんとする時は音長く喇叭を吹ならすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'また會衆を集むる時にも喇叭をふくべし但し音長くこれを吹ならすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'アロンの子等の祭司たる者どもその喇叭を吹べし是すなはち汝らが代々ながく守るべき例たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'また汝らの國において汝等その己を攻るところの敵と戰はんとて出る時は喇叭を吹ならすべし然せば汝等の神ヱホバ汝らを記憶て汝らをその敵の手より救ひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'また汝らの喜樂の日汝らの節期および月々の朔日には燔祭の上と酬恩祭の犠牲の上に喇叭を吹ならすべし然せば汝らの神これに由て汝らを記憶たまはん我は汝らの神ヱホバ也');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, '斯て第二年の二月の二十日に雲律法の幕屋を離れて昇りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'イスラエルの子孫シナイの野より出でて途に進みたりしがパランの野にいたりて雲止れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, '斯かれらはヱホバのモーセによりて命じたまへるところに遵ひて途に進むことを始めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, '首先にはユダの子孫の營の纛の下につく者その軍旅にしたがひて進めりユダの軍旅の長はアミナダブの子ナシヨン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'イッサカルの子孫の支派の軍旅の長はツアルの子ネタニエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'ゼブルンの子孫の支派の軍旅の長はへロンの子エリアブなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, '乃ち幕屋を取くづしゲルシヨンの子孫およびメラリの子孫幕屋を擔ひて進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, '次にルベンの營の纛の下につく者その軍旅にしたがひて進めりルベンの軍旅の長はシデウルの子エリヅル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'シメオンの子孫の支派の軍旅の長はツリシヤダイの子シルミエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'ガドの子孫の支派の軍旅の長はデウエルの子エリアサフなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'コハテ人聖所を擔ひて進めり是が至るまでに彼その幕屋を建をはる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, '次にエフライムの子孫の營の纛の下につく者その軍旅にしたがひて進めりヱフライムの軍旅の長はアミホデの子エリシヤマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'マナセの子孫の支派の軍旅の長はパダヅルの子ガマリエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'ベニヤミンの子孫の支派の軍旅の長はギデオニの子アビダンなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, '次にダンの子孫の營の纛の下につく者その軍旅にしたがひて進めりこの軍旅は諸營の後驅なりきダンの軍旅の長はアミシヤダイの子アヒエゼル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'アセルの子孫の支派の軍旅の長はオクランの子バギエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'ナフタリの子孫の支派の軍旅の長はエナンの子アヒラなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'イスラエルの子孫はその途に進む時は是のごとくその軍旅にしたがひて進みたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, '茲にモーセその外舅なるミデアン人リウエルの子ホバブに言けるは我等はヱホバが甞て我これを汝等に與へんと言たまひし處に進み行なり汝も我等とともに來れ我等汝をして幸福ならしめん其はヱホバ、イスラエルに福祉を降さんと言たまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, '彼モーセに言ふ我は往じ我はわが國に還りわが親族に至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'モーセまた言けるは請ふ我等を棄去なかれ汝は我儕が曠野に營を張るを知ば願くは我儕の目となれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, '汝もし我儕とともに往ばヱホバの我儕に降したまふところの福祉を我儕また汝にもおよぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, '斯て彼等ヱホバの山をたち出て三日路ほど進み行りヱホバの契約の櫃その三日路の間かれらに先だち行て彼等の休息所を尋ね覓めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, '彼等營を出て途に進むに當りて晝はヱホバの雲かれらの上にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, '契約の櫃の進まんとする時にはモーセ言りヱホバよ起あがりたまへ然ば汝の敵は打散され汝を惡む者等は汝の前より逃さらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'またその止まる時は言りヱホバよ千萬のイスラエル人に歸りたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, '茲に民災難に罹れる者のごとくにヱホバの耳に呟きぬヱホバその怨言を聞て震怒を發したまひければヱホバの火かれらに向ひて燃いでその營の極端を燒り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, '是に於て民モーセに呼はりしがモーセ、ヱホバに祈ければその火鎮りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'ヱホバの火かれらに向ひて燃出たるに因てその處の名をタベラ(燃)と稱ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, '茲に彼等の中なる衆多の寄集人等慾心を起すイスラエルの子孫もまた再び哭て言ふ誰か我らに肉を與へて食しめんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, '憶ひ出るに我等エジプトにありし時は魚黄瓜水瓜韮葱靑蒜等を心のままに食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, '然るに今は我儕の精神枯衰ふ我らの目の前にはこのマナの外何も有ざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'マナは莞荽の實のごとくにしてその色はブドラクの色のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, '民行巡りてこれを斂め石磨にひき或は臼に搗てこれを釜の中に煮て餅となせりその味は油菓子の味のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, '夜にいりて露營に降る時にマナその上に降れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'モーセ聞に民の家々の者おのおのその天幕の門口に哭く是におひてヱホバ烈しく怒を發したまふこの事またモーセの目にも惡く見ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'モーセすなはちヱホバに言けるは汝なんぞ僕を惡くしたまふ乎いかなれば我汝の前に恩を獲ずして汝かく此すべての民をわが任となして我に負せたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'この總體の民は我が姙みし者ならんや我が生し者ならんや然るに汝なんぞ我に慈父が乳哺子を抱くがごとくに彼らを懐に抱きて汝が昔日かれらの先祖等に誓ひたまひし地に至れと言たまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, '我何處より肉を得てこの總體の民に與へんや彼等は我にむかひて哭き我等に肉を與へて食しめよと言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, '我は一人にてはこの總體の民をわが任として負ことあたはず是は我には重きに過ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, '我もし汝の前に恩を獲ば請ふ斯我を爲んよりは寧ろ直に我を殺したまへ我をしてわが困苦を見せしめたまふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, '是においてヱホバ、モーセに言たまはくイスラエルの老人の中民の長老たり有司たるを汝が知るところの者七十人を我前に集め集會の幕屋に携きたりて其處に汝とともに立しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, '我降りて其處にて汝と言はん又われ汝の上にあるところの霊を彼等にも分ち與へん彼等汝とともに民の任を負ひ汝をして只一人にて之を負ふこと無らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, '汝また民に告て言へ汝等身を潔めて明日を待て必ず肉を食ふことを得ん汝等ヱホバの耳に哭て誰か我等に肉を與へて食しめん我らエジプトにありし時は却て善りしと言たればヱホバなんぢらに肉を與へて食しめたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, '汝等がこれを食ふは一日や二日や五日や十日や二十日にはあらずして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, '一月におよび遂に汝らの鼻より出るにいたらん汝等これに饜はつべし是なんぢら己等の中にいますヱホバを軽んじてその前に哭き我等何とてエジプトより出しやと言たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'モーセ言けるは我が偕にをる民は歩卒のみにても六十萬あり然るに汝は我かれらに肉を與へて一月の間食しめんと言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, '羊と牛の群を宰るとも彼等を飽しむることを得んや海の魚をことごとく集むるとも彼等を飽しむることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'ヱホバ、モーセに言たまはくヱホバの手短からんや吾言の成と然らざるとは汝今これを見るあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, '是に於てモーセ出きたりてヱホバの言を民に告げ民の長老七十人を集めて幕屋の四圍に立しめけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'ヱホバ雲の中にありて降りモーセと言ひモーセのうへにある霊をもてその長老七十人にも分ち與へたまひしがその霊かれらの上にやどりしかば彼等預言せり但し此後はかさねて爲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, '時に彼等の中なる二人の者營に止まり居るその一人の名はエルダデといひ一人の名はメダデと曰ふ霊またかれらの上にもやどれり彼らは其名を録されたる者なりしが幕屋に往ざりければ營の中にて預言をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, '時に一人の少者奔りきたりモーセに告てエルダデとメダデ營の中にて預言すと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'その少時よりしてモーセの從者たりしヌンの子ヨシユアこたへて曰けるは吾主モーセこれを禁めたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'モーセこれに言けるは汝わがために媢嫉を起すやヱホバの民の皆預言者とならんことまたヱホバのその霊を之に降したまはんことこそ願しけれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, '斯てモーセ、イスラエルの長老等とともに營に返れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, '茲にヱホバの許より風おこり出て海の方より鶉を吹きたりこれをして營の周圍に堕しめたりその堕ひろがれること營の四周此旁も大約一日路彼旁も大約一日路地の表より高きこと大約二キユビトなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, '民すなはち起あがりてその日終日その夜終夜またその次の日終日鶉を拾ひ斂めけるが拾ひ斂むることの至て寡き者も十ホメルほど拾ひ斂めたり皆これを營の周圍に陳べおけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, '肉なほ歯のあひだにありていまだ食つくさざるにヱホバ民にむかひて怒を發しこれを撃ておほいに滅ぼしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, '是をもてその處の名をキブロテハッタワ(慾心の墓)とよべり其は慾心をおこせる人々を其處に埋たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, '斯て民キブロテハツタワよりハゼロテに進みゆきてハゼロテに居ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'モーセはエテオピアの女を娶りたりしがそのエテオピアの女を娶りしをもてミリアムとアロン、モーセを謗れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, '彼等すなはち言けるはヱホバただモーセによりてのみ語りたまはんやまた我等によりても語り給ふにあらずやとヱホバこれを聞たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, '(モーセはその人と爲温柔なること世の中の諸の人に勝れり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, '是に於てヱホバ遽にモーセ、アロン及びミリアムに言たまはく汝等三人集會の幕屋に出きたれと三人すなはち出きたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'ヱホバ雲の柱の中にありて降り幕屋の門に立てアロンとミリアムを呼たまひしがかれら二人進みたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, '之に言たまはく汝等わが言を聽け汝らの中にもし預言者あらば我ヱホバ異象において我をこれに知しめまた夢において之と語らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'わが僕モーセに於ては然らず彼はわが家に忠義なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, '彼とは我口をもて相語り明かに言ひて隠語を用ひず彼はまたヱホバの形を見るなり然るを汝等なんぞわが僕モーセを謗ることを畏れざるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'ヱホバかれらに向ひ忿怒を發して去たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, '雲すなはち幕屋をはなれて去ぬその時ミリアムに癩病生じてその身雪のごとく爲りアロン、ミリアムを見かへるに旣に癩病生じをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'アロン是においてモーセに言けるは嗟わが主よ我等愚なる事をなして罪を犯したれど願くは其罪を我等に蒙らしむる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, '彼をして母の胎より肉半分腐れて死て生れいづる者のごとくならしむる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'モーセすなはちヱホバに呼はりて言ふ嗚呼神よ願くは彼を醫したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'ヱホバ、モーセに言たまひけるは彼の父その面に唾する事ありてすら彼は七日の間羞をるべきに非ずや然ば七日の間かれを營の外に禁鎖おきて然る後に歸り入しむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'ミリアムはすなはち七日の間營の外に禁鎖られぬ民はミリアムの歸り入るまで途に進まざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'その後民ハゼロテより進みてバランの曠野に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, '茲にヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '汝人を遣して我がイスラエルの子孫に與ふるカナンの地を窺はしめよ即ち支派ごとに一人を取て之を遣すべし其人々は皆かれらの中の牧伯たる者なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'モーセすなはちヱホバの命にしたがひてバランの曠野よりこれを遣せりその人等は皆イスラエルの子孫の領袖たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'その名は是のごとしルベンの支派にてはザックルの子シヤンマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'シメオンの支派にてはホリの子シヤパテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'ユダの支派にてはエフンネの子カルブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'イッサカルの支派にてはヨセフの子イガル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'エフライムの支派にてはヌンの子ホセア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'ベニヤミンの支派にてはラフの子パルテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'ゼブルンの支派にてはソデの子ガデエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'ヨセフの支派すなはちマナセの支派にてはスシの子ガデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'ダンの支派にではゲマリの子アンミエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'アセルの支派にてはミカエルの子セトル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'ナフタリの支派にてはワフシの子ナヘビ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'ガドの支派にてはマキの子ギウエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, '是すなはちモーセがその地を窺はしめんとて遣したる人々の名なり時にモーセ、ヌンの子ホセアをヨシユアと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'モーセかれらを遣はしてカナンの地を窺はしめんとして之に言けるは汝等その南の方に赴きて山に登り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'その地の如何と其處に住む民の強か弱か多か寡かを觀');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'またその住ところの地は善か惡か其住ところの邑々は如何なるものなるか彼等は天幕に住をるか城の邑に住をるかを觀');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'またその地は腴なるか痩たるか其中に樹あるや否を觀よ汝等勇しかれその地の果物を携へきたれよとこの時は葡萄の熟し始むる時なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, '是において彼等上りゆきてその地を窺ひチンの曠野よりレホブにおよべり是はハマテに近し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, '彼等すなはち南の方に上りゆきてヘブロンにいたれり此にはアナクの子アヒマン、セシヤイおよびタルマイあり(ヘブロンはエジプトのゾアンよりも七年前に建たる者なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, '彼らつひにエシコルの谷にいたり其處より一球の葡萄のなれる枝を砍とりてこれを杠に貫き二人してこれを擔へりまた石榴と無花果を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'イスラエルの子孫其處より葡萄一球を砍とりしが故にその處をエシコル(一球の葡萄)の谷と稱ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, '彼ら四十日を經その地を窺ふことを竟て歸り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'パランの曠野なるカデシに至りてモーセとアロンおよびイスラエルの子孫の全會衆に就きかれらと全會衆にその復命を申しその地の果物をこれに見せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, '彼等すなはちモーセに語りて言ふ我等は汝が遣しし地にいたれり誠に其處は乳と蜜とながる是その果物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, '然ながらその地に住む民は猛くその邑々は堅固にして甚だ大なり我等またアナクの子孫の其處にをるを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'またアマレキ人その南の地に住みヘテ人エブス人およびアモリ人その山々に住みカナン人その海邊とヨルダンの邊に住をると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, '時にカルブ、モーセの前に民を靜めて言けるは我等直に上りゆきて之を攻取ん我等は必ずこれに勝ことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, '然ど彼とともに往たる人々は言ふ我等はかの民の所に攻上ることを得ず彼らは我らよりも強ければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, '彼等すなはちその窺ひたりし地の事をイスラエルの子孫の中に惡く言ふらして云く我等が行巡りて窺ひたる地は其中に住む者を呑ほろぼす地なり且またその中に我等が見し民はみな身幹たかき人なりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, '我等またアナクの子ネピリムを彼處に見たり是ネピリムより出たる者なり我儕は自ら見るに蝗のごとくまた彼らにも然見なされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, '是において會衆みな聲をあげて叫び民その夜哭あかせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'すなはちイスラエルの子孫みなモーセとアロンに對ひて呟き全會衆かれらに言けるは嗚呼我等はエジプトの國に死たらば善りしものを又はこの曠野に死ば善らんものを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, '何とてヱホバ我等をこの地に導きいりて劍に斃れしめんとし我らの妻子をして掠められしめんとするやエジプトに歸ること反て好らずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, '互に相語り我等一人の長を立てエジプトに歸らんと云り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, '是をもてモーセとアロンはイスラエルの子孫の全會衆の前において俯伏たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, '時にかの地を窺ひたりし者の中なるヌンの子ヨシユアとヱフンネの子カルブその衣服を裂き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'イスラエルの子孫の全會衆に語りて言ふ我等が行巡りて窺ひたりし地は甚だ善き地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'ヱホバもし我等を悦びたまはば我らをその地に導きいりて之を我等に賜はん是は乳と蜜との流るる地なるぞかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, '唯ヱホバに逆ふ勿れまたその地の民を懼るるなかれ彼等は我等の食物とならん彼等の影となる者は旣に去りかつヱホバわれらと共にいますなり彼等を懼るる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, '然るに會衆みな石をもて之を撃んとせり時にヱホバの榮光集會の幕屋の中よりイスラエルの全體の子孫に顯れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'ヱホバすなはちモーセに言たまはく此民は何時まで我を藐視るや我諸の休徴をかれらの中間に行ひたるに彼等何時まで我を賴むことを爲ざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, '我疫病をもてかれらを撃ち滅し汝をして彼等よりも大なる強き民とならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'モーセ、ヱホバに言けるは汝がその權能をもてこの民をエジプトより導き出したまひし事はエジプト人唯これを聞し而已ならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'また之をこの地に住る民に告たりまた彼等は汝ヱホバがこの民の中に在し汝ヱホバが明かにこれに顯れたまふことを聞きまたその上に汝の雲をりて汝が晝は雲の柱の中にあり夜は火の柱の中にありて之が前に行たまふを聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, '然ば汝もしこの民を一人のごとくに殺したまはば汝の名聲を聞る國人等言ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'ヱホバこの民を導きてその之に誓ひたりし地に至ること能はざるが故に之を曠野に殺せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, '吾主ねがはくは今汝の權能を大ならしめて汝の言たまへる如したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '汝曾言たまひけらくヱホバは怒ること遅く恩惠深く惡と過とを赦す者また罰すべき者をば必ず赦すことをせず父の罪を子に報いて三四代に及ぼす者と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, '願くは汝の大なる恩惠をもち汝がエジプトより今にいたるまでこの民を赦しし如くにこの民の惡を赦したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'ヱホバ言たまはく我汝の言にしたがひて之を赦す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, '然ながら我の活るごとくまたヱホバの榮光の全世界に充わたらん如く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'かのわが榮光および我がエジプトと曠野において行ひし休徴を見ながら斯十度も我を試みて我聲に聽したがはざる人々は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, '皆かならず我がその先祖等に誓ひし地を見ざるべしまた我を藐視る人々も之を見ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, '但しわが僕カルブはその心異にして我に全く從ひたれば彼の往たりし地に我かれを導きいらんその子孫これを有つに至るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'アマレキ人とカナン人谷にをれば明日汝等身を轉して紅海の路より曠野に退くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'ヱホバ、モーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '我この我にむかひて呟くところの惡き會衆を何時まで赦しおかんや我イスラエルの子孫が我にむかひて呟くところの怨言を聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, '彼等に言へヱホバ曰ふ我は活く汝等が我耳に言しごとく我汝等になすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, '汝らの屍はこの曠野に横はらん即ち汝ら核數られたる二十歳以上の者の中我に對ひて呟ける者は皆ことごとく此に斃るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'ヱフンネの子カルブとヌンの子ヨシュアを除くの外汝等は我が汝らを住しめんと手をあげて誓ひたりし地に至ることを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, '汝等が掠められんと言たりし汝等の子女等を我導きて入ん彼等は汝らが顧みざるところの地を知に至るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, '汝らの屍はかならずこの曠野に横はらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, '汝らの子女等は汝らが屍となりて曠野に朽るまで四十年の間曠野に流蕩て汝らの悸逆の罪にあたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, '汝らはかの地を窺ふに日數四十日を經たれば其一日を一年として汝等四十年の間その罪を任ひ我が汝らを離たるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, '我ヱホバこれを言り必ずこれをかの集りて我に敵する惡き會衆に盡く行なふべし彼らはこの曠野に朽ち此に死うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'モーセに遣されてかの地を窺ひに往き還り來りてその地を謗り全會衆をしてモーセに對ひて呟かしめたる人々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, '即ちその地を惡く言なしたるかの人々は罰をうけてヱホバの前に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, '但しその地を窺ひに往きたる人々の中ヌンの子ヨシユアとヱフンネの子カルブとは生のこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'モーセこれらの事をイスラエルの子孫に告ければ民痛く哀み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, '朝蚤く起いでて山の嶺に登りて言ふ視よ我儕此にあり率ヱホバの約束したまひし地に上りゆかん我等罪を犯したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'モーセ言けるは汝等なんぞ斯ヱホバの命に背くやこの事成就せざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, '汝ら上り行く勿れヱホバ汝らの中にいまさざれば恐くは汝らその敵の前に撃破られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'アマレキ人とカナン人其處に汝らの前にあれば汝等は劍に斃るるならん汝らヱホバに遵はざりし故にヱホバ汝等と偕に在さざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, '然るに彼等自擅に山の嶺に登れり但しヱホバの契約の櫃およびモーセは營を出ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, '斯りしかばその山に住るアマレキ人とカナン人下り來てこれを打敗りホルマまで追いたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, '茲にヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'イスラエルの子孫に告て之に言へ我が汝等に與へて住しむる地に汝等到り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'ヱホバに火祭を献る時すなはち願を還す時期又は自意の禮物を爲の時期または汝らの節期にあたりて牛あるひは羊をもて燔祭または犠牲を献げてヱホバに馨しき香を奉つる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'その禮物をヱホバに献る者もし羔羊をもて燔祭あるひは犠牲となすならば麥粉十分の一に油一ヒンの四分の一を混和たるをその素祭として供へ酒一ヒンの四分の一をその灌祭として供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'その禮物をヱホバに献る者もし羔羊をもて燔祭あるひは犠牲となすならば麥粉十分の一に油一ヒンの四分の一を混和たるをその素祭として供へ酒一ヒンの四分の一をその灌祭として供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, '若また牡羊を之に用ふるならば麥粉十分の二に油一ヒンの三分の一を混和たるをその素祭として供へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'また酒一ヒンの三分の一をその灌祭として献げヱホバに馨しき香をたてまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, '汝また願還あるひは酬恩祭をヱホバになすに當りて牡牛をもて燔祭あるひは犠牲となすならば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, '麥粉十分の三に油一ヒンの半を混和たるを素祭となしてその牡牛とともに献げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'また酒一ヒンの半をその灌祭として献ぐべし是すなはち火祭にしてヱホバに馨しき香をたてまつる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, '牡牛あるひは牡羊あるひは羔羊あるひは羔山羊は一匹ごとに斯爲べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, '即ち汝らが献ぐるところの數にてらしその數にしたがひて一匹ごとに斯なすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, '本國に生れたる者火祭を献げてヱホバに馨しき香をたてまつる時には凡て斯のごとく是等の事を行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'また汝らの中に寄寓る他國の人あるひは汝らの中に代々住ふところの人火祭をささげてヱホバに馨しき香をたてまつらんとする時は汝らの爲がごとくにその人もなすべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, '汝ら會衆および汝らの中に寄寓る他國の人は同一の例にしたがふべし是は汝らが代々永く守るべき例なり他國の人のヱホバの前に侍ることは汝等と異るところ無るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, '汝らと汝らの中に宿寓る他國の人とは同一の法同一の禮式にしたがふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'イスラエルの子孫に告てこれに言へ我が汝等を導き往ところの地に汝等いたらん時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'その地の食物を食ふにあたりて汝ら擧祭をヱホバにささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, '即ち汝らはその麥粉の初をもてパンを作りてこれを擧祭にそなふべし是は禾場より擧祭をそなふるが如くに擧てそなふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, '汝ら代々その麥粉の初をもて擧祭をヱホバにたてまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, '汝等もし誤りてヱホバのモーセに告たまへるこの諸の命令を行はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'ヱホバがモーセをもて命じたまひし事等並にその命ずることを始めたまひし日より以來汝らの代々にも命じたまはんところの事等を行はざる事有ん時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'すなはち會衆誤りて犯す所ありて之を知ざることあらん時は全會衆少き牡牛一匹を燔祭にささげてヱホバに馨しき香とならしめ之にその素祭と灌祭を禮式のごとくに加へまた牡山羊一匹を罪祭にささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, '而して祭司イスラエルの子孫の全會衆のために贖罪を爲べし斯せば是は赦されん是は過誤なればなり彼等はその禮物として火祭をヱホバにささげまたその過誤のために罪祭をヱホバの前にささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, '然せばイスラエルの子孫の會衆みな赦されんまた彼等の中に寄寓る他國の人も然るべし其は民みな誤り犯せるなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, '人もし誤りて罪を犯さば當歳の牝山羊一匹を罪祭に献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, '祭司はまたその誤りて罪を犯せる人が誤りてヱホバの前に罪を獲たるが爲に贖罪をなしてその罪を贖ふべし然せば是は赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'イスラエルの子孫の國の者にもあれまた其中に寄寓る他國の人にもあれ凡そ誤りて罪を犯す者には汝らその法を同じからしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, '本國の人にもあれ他國の人にもあれ凡そ擅横に罪を犯す者は是ヱホバを瀆すなればその人はその民の中より絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, '斯る人はヱホバの言を軽んじその誡命を破るなるが故に必ず絶れその罪を身に承ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'イスラエルの子孫曠野に居る時安息日に一箇の人の柴を拾ひあつむるを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, '是においてその柴を拾ひあつむるを見たる者等これをモーセとアロンおよび會衆の許に曳きたりけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, '之を如何に爲べきか未だ示諭を蒙らざるが故に之を禁錮おけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, '時にヱホバ、モーセに言たまひけるはその人はかならず殺さるべきなり全會衆營の外にて石をもて之を撃べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, '全會衆すなはち之を營の外に曳いだし石をもてこれを撃ころしヱホバのモーセに命じたまへるごとくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'ヱホバ亦モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '汝イスラエルの子孫に告げ代々その衣服の裾に襚をつけその裾の襚 の上に靑き紐をほどこすべしと之に命ぜよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, '此襚は汝らに之を見てヱホバの諸の誡命を記憶して其をおこなはしめ汝らをしてその放縦にする自己の心と目の欲に從がふこと無らしむるための者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, '斯して汝等吾もろもろの誡命を記憶して之を行ひ汝らの神の前に聖あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, '我は汝らの神ヱホバにして汝らの神とならんとて汝らをエジプトの地より導きいだせし者なり我は汝らの神ヱホバなるぞかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, '茲にレビの子コハテの子イヅハルの子なるコラおよびルベンの子等なるエリアブの子ダタンとアビラム並にペレテの子オン等相結び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'イスラエルの子孫の會衆の中に選まれて牧伯となれるところの名ある人々二百五十人とともに起てモーセに逆らふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'すなはち彼等集りてモーセとアロンに逆ひ之に言けるは汝らはその分を超ゆ會衆みな盡く聖者となりてヱホバその中に在すなるに汝ら尚ヱホバの會衆の上に立つや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'モーセこれを聞て俯伏たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'やがてコラとその一切の黨類に言けるは明日ヱホバ己の所屬は誰聖者は誰なるかを示して其者を己に近かせたまはん即ちその選びたまへる者を己に近かせたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, '汝等かく爲よコラとその黨類よ汝等みな火盤を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'その中に火をいれその中に香を盛て明日ヱホバの前に至れその時ヱホバの選みたまふ人は聖者たるべしレビの人々よ汝等はその分を超るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'モーセまたコラに言けるは汝等レビの子等よ請ふ聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'イスラエルの神汝らをイスラエルの會衆の中より分ち己に近かせてヱホバの幕屋の役事を爲しめ會衆の前に立て之にかはりて勤務をなさしめたまふ是あに汝らにとりて小き事ならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, '神すでに汝と汝の兄弟なるレビの兒孫等を己に近かせたまふに汝らまた祭司とならんことをも求むるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, '汝と汝の黨類は皆これがために集りてヱホバに敵するなりアロンを如何なる者として汝等これに對ひて呟くや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'かくてモーセ、エリアブの子ダタンとアビラムを呼に遣はしけるに彼等いひけるは我等は上り往じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, '汝は乳と蜜との流るる地より我らを導き出して曠野に我らを殺さんとす是あに小き事ならんや然るに汝また我等の上に君たらんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, '且また汝は我らを乳と蜜との流るる地にも導きゆかずまた田畝をも葡萄園をも我らに與へて有たしめず汝この人々の目を抉りとらんとするや我等は上りゆかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, '是においてモーセおほいに怒りヱホバに申しけるは汝かれらの禮物を顧みたまふ勿れ我はかれらより驢馬一匹をも取しことなくまた彼等を一人も害せしこと無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, '斯てモーセ、コラに言けるは汝と汝の黨類みなアロンと偕に明日ヱホバの前に至れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, '即ち汝らおのおの火盤を執てその中に香を盛り各人その火盤をヱホバの前に携へいたれその火祭は都合二百五十汝とアロンも各々その火盤を携へいたるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, '彼等すなはち各々火盤を執り火をその中にいれて香をその上に盛りモーセおよびアロンとともに集會の幕屋の門に立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'コラ會衆をことごとく集會の幕屋の門に集めおきてかれら二人に敵せしめんとせしにヱホバの榮光全會衆に顯れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'ヱホバ、モーセとアロンに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '汝等この會衆を離れよ我これを直に滅さんとすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, '是においてかれら二人俯伏て言ふ神よ一切の血肉ある者の生命の神よこの一人の者罪を犯したればとて汝全會衆にむかひて怒を發したまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '汝會衆にむかひてコラとダタンとアビラムの居所の周圍を去れと言へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'モーセすなはち起あがりてダタンとアビラムの所に往けるがイスラエルの長老等これに從がひいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, '而してモーセ會衆に告て言けるは汝らこの惡き人々の天幕を離れて去れ彼等の物には何にも捫る勿れ恐くは彼らの諸の罪のために汝らも滅ぼされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, '是において人々はコラとダタンとアビラムの居所を離れて四方に去ゆけりまたダタンとアビラムはその妻子ならびに幼兒とともに出てその天幕の門に立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'モーセやがて言けるは汝等ヱホバがこの諸の事をなさせんとて我を遣したまへる事また我がこれを自分の心にしたがひて行ふにあらざる事を是によりて知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'すなはちこの人々もし一般の人の死るごとくに死に一般の人の罰せらるる如くに罰せられなばヱホバわれを遣したまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, '然どヱホバもし新しき事を爲たまひ地その口を開きてこの人々と之に屬する者を呑つくして生ながら陰府に下らしめなばこの人々はヱホバを瀆ししなりと汝ら知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'モーセこの一切の言をのべ終れる時かれらの下なる土裂け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, '地その口を開きてかれらとその家族の者ならびにコラに屬する一切の男等と一切の所有品を呑つくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'すなはち彼等とかれらに屬する者はみな生ながら陰府に下りて地その上に閉ふさがりぬ彼等かく會衆の中より滅ぼされたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'その周圍に居たるイスラエル人は皆かれらの叫喊を聞て逃はしり恐くは地われらをも呑つくさんと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, '且またヱホバの許より火いでてかの香をそなへたる者二百五十人を燒つくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, '時にヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '汝祭司アロンの子エレアザルに告てその燃る火の中より彼の火盤を取いださしめその中の火を遠方に傾すてよその火盤は聖なりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, '而してその罪を犯して生命を喪へる者等の火盤は之を濶き展版となして祭壇を包むに用ひよ彼等ヱホバの前にそなへしに因て是は聖なりたればなり斯是はイスラエルの子孫に徴と爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, '是において祭司エンアザル彼の燒死されし者等が用ひてそなへたる銅の火盤を取いだしければ之を濶く打展し之をもて祭壇を包み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, '之をイスラエルの子孫の記念の物と爲り是はアロンの子孫たらざる外人が近りてヱホバの前に香を焚こと無らんため亦かかる人ありてコラとその黨類のごとくにならざらん爲なり是みなヱホバがモーセをもて彼にのたまひし所に依るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'その翌日イスラエルの子孫の會衆みなモーセとアロンにむかひて呟き汝等はヱホバの民を殺せりと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, '會衆集りてモーセとアロンに敵する時集會の幕屋を望み觀に雲ありてこれを覆ひヱホバの榮光顯れをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, '時にモーセとアロン集會の幕屋の前にいたりけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'ヱホバ、モーせに言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '汝らこの會衆をはなれて去れ我直にこれをほろぼさんとすと是において彼等二人は俯伏ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, '斯てモーセ、アロンに言けるは汝火盤を執り壇の火を之にいれ香をその上に盛て速かにこれを會衆の中に持ゆき之がために贖罪を爲せ其はヱホバ震怒を發したまひて疫病すでに始りたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'アロンすなはちモーセの命ぜしごとくに之を執て會衆の中に奔ゆきけるに疫病すでに民の中に始まり居たれば香を焚て民のために贖罪を爲し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, '旣に死る者と尚生る者との間に立ければ疫病止まれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'コラの事によりて死たる者の外この疫病に死たる者は一萬四千七百人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, '而してアロンはモーセの許にかへり集會の幕屋の門にいたれり疫病は斯やみぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'ヱホバ、モーセに告て言給はく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '汝イスラエルの子孫に語り之が中よりその各箇の父祖の家にしたがひて杖一本づつを取れ即ちその一切の牧伯等よりその父祖の家に循ひて杖都合十二本を取りその人等の名を各々その杖に書せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'レビの杖には汝アロンの名を書せ其はその父祖の家の長たる者各箇杖一本を出すべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, '而して集會の幕屋の中我が汝等に會ふ處なる律法の櫃の前に汝之を置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, '我が選める人の杖は芽さん我かくイスラエルの子孫が汝等にむかひて呟くところの怨言をわが前に止むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'モーセかくイスラエルの子孫に語りければその牧伯等おのおの杖一本づつを之に付せり即ち牧伯等おのおのその父祖の家にしたがひて一本づつを出したればその杖あはせて十二本アロンの杖もその杖の中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'モーセその杖を皆律法の幕屋の中にてヱホバの前に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, '斯てその翌日モーセ律法の幕屋にいりて視るにレビの家のために出せるアロンの杖芽をふき蕾をなし花咲て巴旦杏の果を結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'モーセその杖をことごとくヱホバの前よりイスラエルの子孫の所に取いだしければ彼ら見ておのおの自分の杖を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, '時にヱホバまたモーセに言たまはく汝アロンの杖を律法の櫃の前に携へかヘり其處にたくはへ置てこの背反者等のために徴とならしめよ斯して汝かれらの怨言を全く取のぞきかれらをして死ざらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'モーセすなはち然なしヱホバの己に命じたまへる如くせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'イスラエルの子孫モーセに語りて曰ふ嗚呼我等は死ん我等は滅びん我等はみな滅びん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, '凡そヱホバの幕屋に微にても近く者はみな死るなり我等はみな死斷べき歟');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, '斯てヱホバ、アロンに告て言たまはく汝と汝の子等および汝の父祖の家の者は聖所に關れる罪をその身に擔當べしまた汝と汝の子等は汝らがその祭司の職について獲ところの罪をその身に擔當べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, '汝また汝の兄弟たるレビの支派の者すなはち汝の父祖の支派の者等をも率て汝に合せしめ汝に事しむべし但し汝と汝の子等は律法の幕屋の前に侍るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, '彼らは汝の職守と聖所の職守とを守るべし只聖所の器具と壇とに近くべからず恐くは彼等も汝等も死るならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, '彼等は汝に合して集合の幕屋の職守を守り幕屋の諸の役事をなすべきなり外人は汝らに近づく可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, '斯なんぢらは聖所の職守と祭壇の職守を守るべし然せばヱホバの震怒かさねてイスラエルの子孫に及ぶこと有じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, '視よ我なんぢらの兄弟たるレビ人をイスラエルの子孫の中より取りヱホバのために之を賜物として汝らに賜ふて集會の幕屋の役事を爲しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, '汝と汝の子等は祭司の職を守りて祭壇の上と障蔽の幕の内の一切の事を執おこなひ斯ともに勤むべし我祭司の職の勤務と賜物として汝らに賜ふ外人の近く者は殺されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'ヱホバ又アロンに言たまはく我イスラエルの子孫の諸の聖禮物の中我に擧祭とするところの者をもて汝に賜ひて得さす即ち我これを汝と汝の子等にあたへてその分となさしめ是を永く例となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, '斯のごとく至聖禮物の中火にて燒ざる者は汝に歸すべし即ちその我に献る諸の禮物素祭罪祭愆祭等みな至聖くして汝と汝らの子等に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, '至聖所にて汝これを食ふべし男子等はみなこれを食ふことを得是は汝に歸すべき聖物たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, '汝に歸すべき物は是なり即ちイスラエルの子孫の献る擧祭と搖祭の物我これを汝と汝の男子と女子に與へ是を永く例となす汝の家の者の中潔き者はみな之を食ふことを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, '油の嘉者酒の嘉者穀物の嘉者など凡てヱホバに献るその初の物を我なんぢに與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, '最初に成る國の產物の中ヱホバに携へたる者は皆なんぢに歸すべし汝の家の者の中潔き者はみな之を食ふことを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'イスラエルの人の献納る物は皆汝に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, '凡そ血肉ある者の首出子にしてヱホバに献らるる者は人にもあれ畜にもあれ皆なんぢに歸すべし但し人の首出子は必ず贖ふべくまた汚れたる畜獣の首出子も贖ふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, '之を贖ふにはその人の生れて一箇月に至れる後に汝その估價に依り聖所のシケルに循ひて銀五シケルに之を贖ふべし一シケルはすなはち二十ゲラなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, '然ど牛の首出子羊の首出子山羊の首出子は贖ふべからず是等は聖しその血を壇の上に灑ぎまたその脂を焚て火祭となしてヱホバに馨しき香をたてまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'その肉は汝に歸すべし搖る胸と右の腿とおなじく是は汝に歸するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'イスラエルの子孫がヱホバに献て擧祭とする所の聖物はみな我これを汝と汝の男子女子に與へこれを永く例となす是はヱホバの前において汝と汝の子孫に對する鹽の契約にして變らざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'ヱホバまたアロンに告たまはく汝はイスラエルの子孫の地の中に產業を有べからずまた彼等の中に何の分をも有べからず彼らの中において我は汝の分汝の產業たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'またレビの子孫たる者には我イスラエルの中において物の十分の一を與へて之が產業となし其なすところの役事すなはち集會の幕屋の役事に報ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'イスラエルの子孫はかさねて集會の幕屋に近づくべからず恐くは罪を負て死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, '第レビ人集會の幕屋の役事をなすべしまた彼らはその罪な自己の身に負べし彼等はイスラエルの子孫の中に產業の地を有ざる事をもてその例となして汝らの世代の子孫の中に永く之を守るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'イスラエルの子孫が十に一を取り擧祭としてヱホバに献るところの物を我レビ人に與へてその產業となさしむるが故に我かれらにつきて言り彼等はイスラエルの子孫の中に產業の地を得べからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '汝かくレビ人に告て之に言べし我がイスラエルの子孫より取て汝等に與へて產業となさしむるその什一の物を汝ら之より受る時はその什一の物の十分の一を献てヱホバの擧祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, '汝等の擧祭の物品は禾場よりたてまつる穀物の如く酒醡の内よりたてまつる酒のごとくに見做れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, '此のごとく汝等もまたイスラエルの子孫より受る一切の什一の物の中よりヱホバに擧祭を献げそのヱホバの擧祭を祭司アロンに與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, '汝らの受る一切の禮物の中より汝らはその嘉ところ即ちその聖き分を取てヱホバの擧祭を献べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, '汝かく彼等に言べし汝らその中より嘉ところを取て献るに於てはその殘餘の物は汝等レビ人におけること禾場より取る物のごとく酒醡より取る物のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, '汝等と汝らの眷屬何處にても之を食ふことを得べし是は汝らが集會の幕屋に於て爲す役事の報酬たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, '汝らその嘉ところを献るに於ては之がために罪を負こと有じ汝らはイスラエルの子孫の聖別て献る物を汚すべからず恐くは汝ら死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'ヱホバ、モーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'ヱホバが命ずるところの律の例は是のごとし云くイスラエルの子孫に告て赤牝牛の全くして疵なく未だ軛を負しこと有ざる者を汝の許に牽きたらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, '汝ら之を祭司エレアザルに交すべし彼はまたこれを營の外に牽いだして自己の眼の前にこれを宰らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, '而して祭司エレアザルこれが血を其指につけ集會の幕屋の表にむかひてその血を七次灑ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'やがてその牝牛を自己の眼の前に燒しむべしその皮その肉その血およびその糞をみな燒べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'その時祭司香柏と牛膝草と紅の絲をとりて之をその燒る牝牛の中に投いるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'かくて祭司はその衣服を浣ひ水にてその身を滌ぎて然る後營に入べし祭司の身は晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'また之を燒たる者も水にその衣服を浣ひ水にその身を滌ぐべし彼も晩まで汚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, '斯て身の潔き人一人その牝牛の灰をかき斂めてこれを營の外の清淨處に蓄へ置べし是イスラエルの子孫の會衆のために備へおきて汚穢を潔る水を作るべき者にして罪を潔むる物に當るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'その牝牛の灰をかき斂めたる者はその衣服を浣ふべしその身は晩まで汚るるなりイスラエルの子孫とその中に寄寓る他國の人とは永くこれを例とすべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, '人の死屍に捫る者は七日の間汚る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, '第三日と第七日にこの灰水を以て身を潔むべし然せば潔くならん然ど若し第三日と第七日に身を潔むることを爲ざれば潔くならじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, '凡そ死人の屍に捫りて身を潔むることを爲ざる者はヱホバの幕屋を汚すなればイスラエルより斷るべし汚穢を潔むる水をその身に灑ざるによりて潔くならずその汚穢なほ身にあるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, '天幕に人の死ることある時に應用ふる律は是なり即ち凡てその天幕に入る者凡てその天幕にある物は七日の間汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, '凡そ蓋を取はなして蓋はざりし所の器皿はみな汚る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, '凡そ刀劍にて殺されたる者または死屍または人の骨または墓等に野の表にて捫る者はみな七日の間汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, '汚れたる者ある時はかの罪を潔むる者たる燒る牝牛の灰をとりて器に入れ活水を之に加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, '而して身の潔き人一人牛膝草を執てその水にひたし之をその天幕と諸の器皿および其處に居あはせたる人々に灑ぐべくまたは骨あるひは殺されし者あるひは死たる者あるひは墓などに捫れる者に灑ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, '即ち身の潔き人第三日と第七日にその汚れたる者に之を灑ぐべし而して第七日にはその人みづから身を潔むることを爲しその衣服をあらひ水に身を滌ぐべし然せば晩におよびて潔くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, '然ど汚れて身を潔ることを爲ざる人はヱホバの聖所を汚すが故にその身は會衆の中より絶るべし汚穢を潔むる水を身に灑がざるによりてその人は潔くならざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, '彼等また永くこれを例とすべし即ち汚穢を潔むる水を人に灑げる者はその衣服を浣ふべしまた汚穢を潔むる水に捫れる者も晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, '凡て汚れたる人の捫れる者は汚るべしまた之に捫る人も晩まで汚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, '斯てイスラエルの子孫の全會衆正月におよびてチンの曠野にいたれり而して民みなカデシに止りけるがミリアム其處にて死たれば之を其處に葬りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, '當時會衆水を得ざるによりて相集りてモーセとアロンに迫れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'すなはち民モーセと爭ひ言けるは嚮に我らの兄弟等がヱホバの前に死たる時に我等も死たらば善りしものを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, '汝等何とてヱホバの會衆をこの曠野に導き上りて我等とわれらの家畜を此に死しめんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, '汝らなんぞ我らをエジプトより上らしめてこの惡き處に導きいりしや此には種を播べき處なく無花果もなく葡萄もなく石榴も無くまた飮べき水も無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, '是においてモーセとアロンは會衆の前を去り集會の幕屋の門にいたりて俯伏けるにヱホバの榮光かれらに顯れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '汝杖を執り汝の兄弟アロンとともに會衆を集めその眼の前にて汝ら磐に命ぜよ磐その中より水を出さん汝かく磐より水を出して會衆とその獣畜に飮しむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'モーセすなはちその命ぜられしごとくヱホバの前より杖を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'アロンとともに會衆を磐の前に集めて之に言けるは汝ら背反者等よ聽け我等水をしてこの磐より汝らのために出しめん歟と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'モーセその手を擧げ杖をもて磐を二度撃けるに水多く湧出たれば會衆とその獣畜ともに飮り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, '時にヱホバ、モーセとアロンに言たまひけるは汝等は我を信ぜずしてイスラエルの子孫の目の前に我の聖を顯さざりしによりてこの會衆をわが之に與へし地に導きいることを得じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, '是をメリバ(爭論)の水とよべりイスラエルの子孫是がためにヱホバにむかひて爭ひたりしかばヱホバつひにその聖ことを顯したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, '茲にモーセ、カデシより使者をエドムの王に遣して言けるは汝の兄弟イスラエルかく言ふ汝はわれらが遭し諸の艱難を知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'そもそも我らの先祖等エジプトに下りゆきて我ら年ひさしくエジプトに住をりしがエジプト人われらと我らの先祖等をなやましたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, '我らヱホバに龥はりけるにヱホバわれらの聲を聽たまひ一箇の天の使を遣して我らをエジプトより導きいだしたまへり視よ我ら今は汝の邊境の邊端にあるカデシの邑に居るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, '願くは我らをして汝の國を通過しめよ我等は田畝をも葡萄園をも通過じまた井の水をも飮じ我らは第王の路を通過り汝の境をいづるまでは右にも左にもまがらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'エドム、モーセに言けるは汝我の中を通過べからず恐くは我いでて劍をもて汝にむかはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'イスラエルの子孫エドムに言ふ我らは大道を通過ん若われらと我らの獣畜なんぢの水を飮ことあらばその値を償ふべし我は徒行にて通過のみなれば何事にもあらざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, '然るにエドムは汝通過べからずといひて許多の群衆を率ゐて出で大なる力をもて之にむかへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'エドムかくイスラエルにその境の中を通過ことを容さざりければイスラエルは他にむかひて去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'かくてイスラエルの子孫の會衆みなカデシより進みてホル山にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'ヱホバ、エドムの國の境なるホル山にてモーセとアロンに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'アロンはその死たる民に列らんイスラエルの子孫に我が與へし地に彼は入ことを得ざるべし是メリバの水のある處にて汝等わが言に背きたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, '汝アロンとその子エレアザルをひきつれてホル山に登り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'アロンにその衣服を脱せてこれをその子エレアザルに衣せよアロンは其處に死てその民に列るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'モーセすなはちヱホバの命じたまへるごとく爲し相つれだちて全會衆の目の前にてホル山に登り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, '而してモーセはアロンにその衣服をぬがせて之をその子エレアデルに衣せたりアロンは其處にて山の嶺に死り斯てモーセとエレアザル山よりくだりけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, '會衆みなアロンの死たるを見て三十日のあひだ哀哭をなせりイスラエルの家みな然せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, '茲に南の方に住るカナン人アラデ王といふ者イスラエルが間者の道よりして來るといふを聞きイスラエルを攻うちてその中の數人を擄にせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, '是においてイスラエル誓願をヱホバに立て言ふ汝もしこの民をわが手に付したまはば我その城邑を盡く滅さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'ヱホバすなはちイスラエルの言を聽いれてカナン人を付したまひければ之とその城邑をことごとく滅せり是をもてその處の名をホルマ(殲滅)と呼なしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, '民はホル山より進みゆき紅海の途よりしてエドムを繞り通らんとせしがその途のために民心を苦めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'すなはち民神とモーセにむかいて呟きけるは汝等なんぞ我らをエジプトより導きのぼりて曠野に死しめんとするや此には食物も無くまた水も無し我等はこの粗き食物を心に厭ふなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, '是をもてヱバホ火の蛇を民の中に遣して民を咬しめたまひければイスラエルの民の中死る者多かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, '是によりて民モーセにいたりて言けるは我らヱホバと汝にむかひて呟きて罪を獲たり請ふ汝ヱホバに祈りて蛇を我等より取はなさしめよとモーセすなはち民のために祈ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'ヱホバ、モーセに言たまひけるは汝蛇を作りてこれを杆の上に載おくべし凡て咬れたる者は之を仰ぎ觀なば生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'モーセすなはち銅をもて一條の蛇をつくり之を杆の上に載おけり凡て蛇に咬れたる者その銅の蛇を仰ぎ觀ば生たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'イスラエルの子孫途に進みてオボテに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'またオボテより進み往きモアブの東の方に亘るところの曠野においてイヱアバリムに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'また其處より進みゆきてゼレデの谷に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, '其處より進みゆきてアルノンの彼旁に營を張りアルノンはアモリの境より出て曠野に流るる者にてモアブとアモリの間にありてモアブの界をなすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, '故にヱホバの戰爭の記に言るあり云くスパのワヘブ、アルノンの河');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, '河の流即ちアルの邑に落下りモアブの界に倚る者と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'かれら其處よりベエル(井)にいたれりヱホバがモーセにむかひて汝民を集めよ我これに水を與へんと言たまひしはこの井なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, '時にイスラエルこの歌を歌へり云く井の水よ湧あがれ汝等これがために歌へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, '此井は笏と杖とをもて牧伯等これを掘り民の君長等之を掘りと斯て曠野よりマツタナにいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'マツタナよりナハリエルにいたりナハリエルよりバモテにいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'バモテよりモアブの野にある谷に往き曠野に對するピスガの嶺にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'かくてイスラエル使者をアモリ人の王シホンに遣して言しめけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '我をして汝の國を通過しめよ我等は田畝にも葡萄園にも入じまた井の水をも飮じ我らは汝の境を出るまでは唯王の道を通りて行んのみと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, '然るにシホンはイスラエルに自己の境の中を通る事を容さざりき而してシホンその民をことごとく集め曠野にいでてイスラエルを攻んとしヤハヅに來りてイスラエルと戰ひけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'イスラエル刄をもて之を撃やぶりその地をアルノンよりヤボクまで奪ひ取りアンモンの子孫にまで至れりアンモンの子孫の境界は堅固なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'イスラエルかくその城邑を盡く取り而してイスラエルはアモリ人の諸の城邑に住みヘシボンとそれに附る諸の村々に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'ヘシボンはアモリ人の王シホンの都城なりシホンは曾てモアブの前の王と戰ひてかれの地をアルノンまで盡くその手より奪ひ取しなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, '故に歌をもて云るあり曰く汝らヘシボンに來れシホンの城邑を築き建よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'ヘシボンより火出でシホンの都城より熖いでてモアブのアルを焚つくしアルノンの邊の高處を占る君王等を滅ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'モアブよ汝は禍なる哉ケモシの民よ汝は滅ぼさるその男子は逃奔りその女子はアモリ人の王シホンに擄らるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, '我等は彼らを撃たふしヘシボンを滅ぼしてデボンに及び之を荒してまたノパに及びメデバにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, '斯イスラエルの子孫はアモリ人の地に住たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'モーセまた人を遣はしてヤゼルを窺はしめ遂にその村々を取て其處にをりしアモリ人を逐出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, '轉てバシヤンの路に上り往きけるにバシヤンの王オグその民を盡く率ゐて出で之を迎へてエデレイに戰はんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'ヱホバ、モーセに言たまひけるは彼を懼るる勿れ我かれとその民とその地を盡く汝の手に付す汝ヘシボンに住をりしアモリ人の王シホンに爲たるごとくに彼にも爲べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, '是において彼とその子とその民をことごとく撃ころし一人も生存る者なきに至らしめて之が地を奪ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'かくてイスラエルの子孫また途に進みてモアブの平野に營を張り此はヨルダンの此旁にしてヱリコに對ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'チッポルの子バラクはイスラエルが凡てアモリ人に爲たる所を見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, '是においてモアブ人大いにイスラエルの民を懼る是その數多きに因てなりモアブ人かくイスラエルの子孫のために心をなやましたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'すなはちミデアンの長老等に言ふこの群衆は牛が野の草を餂食ふごとくに我等の四圍の物をことごとく餂食はんとすとこの時にはチッポルの子バラク、モアブ人の王たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, '彼すなはち使者をペトルに遣してベオルの子バラムを招かしめんとすペトルはバラムの本國にありて河の邊に立りその之を招かしむる言に云く茲にエジプトより出來し民あり地の面を蓋ふて我の前にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, '然ば請ふ汝今來りて我ためにこの民を詛へ彼等は我よりも強ければなり然せば我これを撃やぶりて我國よりこれを逐はらふを得ることもあらん其は汝が祝する者は福徳を得汝が詛ふ者は禍を受くと我しればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'モアブの長老等とミデアンの長老等すなはち占卜の禮物を手にとりて出たちバラムにいたりてバラクの言をこれに告たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'バラムかれらに言ふ今晩は此に宿れヱホバの我に告るところに循ひて汝らに返答をなすべしと是をもてモアブの牧伯等バラムの許に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, '時に神バラムに臨みて言たまはく汝の許にをる此人々は何者なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'バラム神に言けるはモアブの王チッポルの子バラク我に言つかはしけらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '茲にエジプトより出きたりし民ありて地の面を蓋ふ請ふ今來りてわがために之を詛へ然せば我これに戰ひ勝てこれを逐はらふを得ることもあらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, '神バラムに言たまひけるは汝かれらとともに往べからず亦この民を詛ふべからず是は祝福るる者たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, '是においてバラム朝起てバラクの牧伯等に言けるは汝ら國に歸れよヱホバ我が汝らとともに往く事をゆるさざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'モアブの牧伯たちすなはち起あがりてバラクの許にいたりバラムは我らとともに來ることを肯ぜずと告たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'バラクまた前の者よりも尊き牧伯等を前よりも多く遣せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, '彼らバラムに詣りて之に言けるはチッボルの子バラクかく言ふ願くは汝何の障碍をも顧みずして我に來れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, '我汝をして甚だ大なる尊榮を得させん汝が我に言ところは凡て我これを爲べし然ば願くは來りて我ためにこの民を詛へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'バラム答へてバラクの臣僕等に言けるは假令バラクその家に盈るほどの金銀を我に與ふるとも我は事の大小を諭ずわが神ヱホバの言を踰ては何をも爲ことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, '然ば請ふ汝らも今晩此に宿り我をしてヱホバの再び我に何と言たまふかを知しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, '夜にいりて神バラムにのぞみて之に言たまひけるはこの人々汝を招きに來りたれば起あがりて之とともに往け但し汝は我が汝につぐる言のみを行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'バラム翌朝起あがりてその驢馬に鞍おきてモアブの牧伯等とともに往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, '然るにヱホバかれの往たるに縁て怒を發したまひければヱホバの使者かれに敵せんとて途に立り彼は驢馬に乗その僕二人はこれとともに在しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, '驢馬ヱホバの使者が劍を手に抜持て途に立るを見驢馬途より身を轉して田圃に入ければバラム驢馬を打て途にかへさんとせしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'ヱホバの使者また葡萄園の途に立り其處には此旁にも石垣あり彼旁にも石垣あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, '驢馬ヱホバの使者を見石垣に貼依てバラムの足を石垣に貼依たればバラムまた之を打り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, '然るにヱホバの使者また進みよりて狭き處に立けるが其處には右にも左にもまがる道あらざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, '驢馬ヱホバの使者を見てバラムの下に臥たり是においてバラム怒を發し杖をもて驢馬を打けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'ヱホバ驢馬の口を啓きたまひたれば驢馬バラムにむかひて言ふ我なんぢに何を爲せばぞ汝かく三次我を打や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'バラム驢馬に言ふ汝われを侮るが故なり我手に劍あらば今汝を殺さんものを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, '驢馬またバラムに言けるは我は汝の所有となりてより今日にいたるまで汝が常に乗ところの驢馬ならずや我つねに斯のごとく汝になしたるやとバラムこたへて否と言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, '時にヱホバ、バラムの目を啓きたまひければ彼ヱホバの使者の途に立て劍を手に抜持るを見身を鞠めて俯伏たるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'ヱホバの使者これに言ふ汝なにとて斯三度なんぢの驢馬を打や我汝の道の直に滅亡にいたる者なるを見て汝に敵せんとて出きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, '驢馬はわれを見て斯みたび身を轉して我を避たるなり是もし身を轉らして我を避ずば我すでに汝を殺して是を生しおきしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'バラム、ヱホバの使者に言けるは我罪を獲たり我は汝が我に敵せんとて途に立るを知ざりしなり汝もし之を惡しとせば我は歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'ヱホバの使者バラムに言けるはこの人々とともに往け但し汝は我が汝に告る言詞のみを宣べしとバラムすなはちバラクの牧伯等とともに往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'さてまたバラクはバラムの來るを聞てモアブの境の極處に流るるアルノンの旁の邑まで出ゆきて之を迎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'バラクすなはちバラムに言けるは我ことさらに人を遣はして汝を招きしにあらずや汝なにゆゑ我許に來らざりしや我あに汝に尊榮を得さすることを得ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'バラム、バラクに言けるは視よ我つひに汝の許に來れり然ど今は我何事をも自ら言を得んや我はただ神の我口に授る言語を宣んのみと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, '斯てバラムはバラクとともに往てキリアテホゾテに至りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'バラク牛と羊を宰りてバラムおよび之と偕なる牧伯等に餽れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, '而してその翌朝にいたりバラクはバラムを件ひこれを携へてバアルの崇邱に登イスラエルの民の極端を望ましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'バラム、バラクに言けるは我ために此に七個の壇を築き此に七匹の牡牛と七匹の牡羊を備へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'バラクすなはちバラムの言るごとく爲しバラクとバラムその壇ごとに牡牛一匹と牡羊一匹を献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, '而してバラムはバラクにむかひ汝は燔祭の傍に立をれ我は往んとすヱホバあるひは我に來りのぞみたまはんその我に示したまふところの事は凡てこれを汝に告んと言て一の高處に登たるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, '神バラムに臨みたまひければバラムこれに言けるは我は七箇の壇を設けその壇ごとに牡牛一匹と牡羊一匹を献げたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'ヱホバ、バラムの口に言を授けて言たまはく汝バラクの許に歸りて斯いふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, '彼すなはちバラクの許に至るにバラクはモアブの諸の牧伯等とともに燔祭の傍に立をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'バラムすなはちこの歌をのべて云くモアブの王バラク、スリアより我を招き寄せ東の邦の山より我を招き寄て云ふ來りて我ためにヤコブを詛へ來りてわがためにイスラエルを呪れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, '神の詛はざる者を我いかで詛ふことを得んやヱホバの呪らざる者を我いかで呪ることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, '磐の頂より我これを觀岡の上より我これを望むこの民は獨り離れて居ん萬の民の中に列ぶことなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, '誰かヤコブの塵を計へ得んやイスラエルの四分一を數ふることを能せんや願くは義人のごとくに我死ん願くはわが終これが終にひとしかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, '是においてバラク、バラムに言けるは汝我に何を爲や我はわが敵を詛はしめんとて汝を携きたりしなるに汝はかへつて全くこれを祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'バラムこたへて言けるは我は愼みてヱホバの我口に授る事のみを宣べきにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'バラクこれに言けるは請ふ汝われとともに他の處に來りて其處より彼らを觀よ汝ただ彼らの極端のみを觀ん彼らを全くは觀ことを得ざるべし請ふ其處にて我ために彼らを詛へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'やがて之を導きてピスガの嶺なる斥候の原に至り七箇の壇を築きて壇ごとに牡牛一匹と牡羊一匹を献たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, '時にバラム、バラクに言けるは汝此にて燔祭の傍に立をれ我またも往て會見ゆることをせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'ヱホバまたバラムに臨みて言をその口に授け汝バラクの許に歸りてかく言へとのたまひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, '彼バラクの許にかへりけるにバラクは燔祭の傍に立をりモアブの牧伯等これとともに居りしがバラクすなはちバラムにむかひヱホバ何と言しやと問ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'バラムまたこの歌を宣たり云くバラクよ起て聽けチッポルの子よ我に耳を傾けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, '神は人のごとく謊ること无しまた人の子のごとく悔ること有ずその言ところは之を行はざらんやその語るところは之を成就ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, '我はこれがために福祉をいのれとの命令を受く旣に之に福祉をたまへば我これを變るあたはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'ヱホバ、ヤコブの中に惡き事あるを見ずイスラエルの中に憂患あるを見ずその神ヱホバこれとともに在し王を喜びて呼はる聲その中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, '神かれらをエジプトより導き出したまふイスラエルは強きこと兕のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'ヤコブには魔術なしイスラエルには占卜あらず神はその爲ところをその時にヤコブに告げイスラエルにしめしたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, '觀よこの民は牝獅子のごとくに起あがり牡獅子のごとくに身を興さん是はその攫得たる物を食ひその殺しし物の血を飮では臥ことを爲じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, '是においてバラクはバラムに向ひ汝かれらを詛ふことをも祝することをも爲なかれと言けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'バラムこたへてバラクに言ふ我はヱホバの宣まふ事は凡てこれを爲ざるを得ずと汝に告おきしにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'バラクまたバラムに言けるは請ふ來れ我なんぢを他の處に導き往ん神あるひは汝が其處より彼らを我ために詛ふことを善とせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'バラクすなはちバラムを導きて曠野に對するペオルの嶺に至るに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'バラム、バラクに言けるは我ために七箇の壇を此に築き牡牛七匹牡羊七匹を此に備へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'バラクすなはちバラムの言るごとく爲しその壇ごとに牡牛一匹と牡羊一匹を献たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'バラムはイスラエルを祝することのヱホバの心に適ふを視たれば此度は前の時のごとくに往て法術を求むる事を爲ずその面を曠野に向て居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'バラム目を擧てイスラエルのその支派にしたがひて居るを觀たり時に神の霊かれに臨みければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, '彼すなはちこの歌をのべて云くベオルの子バラム言ふ目の啓きたる人言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, '神の言詞を聞し者能はざる無き者をまぼろしに觀し者倒れ臥て其目の啓けたる者言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'ヤコブよ汝の天幕は美しき哉イスラエルよ汝の住所は美しき哉');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, '是は谷々のごとくに布列ね河邊の園のごとくヱホバの栽し沈香樹のごとく水の邊の香柏のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'その桶よりは水溢れんその種は水の邊に發育んその王はアガグよりも高くなりその國は振ひ興らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, '神これをエジプトより導き出せり是は強きこと兕のごとくその敵なる國々の民を呑つくしその骨を摧き矢をもて之を衝とほさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, '是は牡獅子のごとくに身をかがめ牝獅子のごとくに臥す誰か敢てこれを起さんやなんぢを祝するものは福祉を得なんぢをのろふものは災禍をかうむるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'ここにおいてバラクはバラムにむかひて怒を發しその手を拍ならせり而してバラク、バラムにいひけるは我はなんぢをしてわが敵を詛はしめんとてなんぢを招きたるに汝は却て斯三度までも彼らを大に祝したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, '然ば汝今汝の處に奔り往け我は汝に大なる尊榮を得させんと思ひたれどヱホバ汝を阻めて尊榮を得るに至らざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'バラム、バラクに言けるは我は汝が我に遣しし使者等に告て言ざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '假令バラクその家に盈るほどの金銀を我に與ふるとも我はヱホバの言を踰て自己の心のままに善も惡きも爲ことを得ず我はヱホバの宣まふ事のみを言べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, '今われは吾民にかへる然ば來れ我この民が後の日に汝の民に爲んところの事を汝に告しらせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'すなはちこの歌をのべて云くベオルの子バラム言ふ目の啓きたる人言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, '神の言を聞るあり至高者を知の知識あり能はざる無き者をまぼろしに觀倒れ臥て其目の啓けたる者言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, '我これを見ん然ど今にあらず我これを望まん然ど近くはあらずヤコブより一箇の星いでんイスラエルより一條の杖おこりモアブを此旁より彼旁に至まで撃破りまた鼓譟者どもを盡く滅すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, '其敵なるエドムは是が產業となりセイルは之が產業とならんイスラエルは盛になるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, '權を秉る者ヤコブより出で遺れる者等を城より滅し絶ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'バラム又アマレクを望みこの歌をのべて云くアマレクは國々の中の最初なる者なり其終には滅び絶るに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, '亦ケニ人を望みこの歌をのべて云く汝の住所は堅固なり汝は磐に巣をつくる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, '然どカインは亡て終にアッスリアの爲に擄へ移されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, '彼亦この歌をのべて云く嗟神これを爲たまはん時は誰か生ることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'キッテムの方より船來てアッスリアを攻なやましエベルを攻なやますべし而して是もまた終に亡失ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, '斯てバラムは起あがりて自己の處に歸り往きぬバラクも亦去ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'イスラエルはシッテムに止まり居けるがその民モアブの婦女等と婬をおこなふことを始めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'その婦女等其神々に犠牲を献る時に民を招けば民は往て食ふことを爲しかつその神々を拝めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'イスラエルかくバアルベオルに附ければイスラエルにむかひてヱホバ怒を發したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'ヱホバすなはちモーセに告て言たまはく民の首をことごとく携きたりヱホバのためにかの者等を日に曝せ然せばヱホバの烈しき怒イスラエルを離るるあらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, '是においてモーセ、イスラエルの士師等にむかひ汝らおのおのその配下の人々のバアルベオルに附る者を殺せと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'モーセとイスラエルの子孫の全會衆集合の幕屋の門にて哭をる時一箇のイスラエル人ミデアンの婦人一箇を携きたり彼らの目の前にてその兄弟等の中に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, '祭司アロンの子なるエレアザルの子ピネハスこれを見會衆の中より起あがりて槍を手に執り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'そのイスラエルの人の後を追て之が寝室に入りイスラエルの人を衝きまたその婦女の腹を衝とほして二人を殺せり是において疫病のイスラエルの子孫におよぶこと止れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'その疫病にて死たる者は二萬四千人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '祭司アロンの子なるエレアザルの子ピネハスはわが熱心をイスラエルの子孫の中にあらはして吾怒をその中より取去り我として熱心をもてイスラエルの子孫を滅し盡すにいたらざらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, '故に汝言へ我これに平和のわが契約をさづく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, '即ち彼とその後の子孫永く祭司の職を得べし是は彼その神のために熱心にしてイスラエルの子孫のために贖をなしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'その殺されしイスラエル人すなはちミデアンの婦人とともに殺されし者はその名をジムリと言てサルの子にしてシメオン人の宗族の牧伯の一人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'またその殺されしミデアンの婦人は名をコズビと曰てツルの女子なりツルはミデアンの民の宗族の首なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'ミデアン人に逼りてこれを撃て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, '其は彼ら謀計をもて汝に逼りペオルの事とその姉妹なるミデアンの牧伯の女すなはちペオルのために疫病の起れる日に殺されしコズビの事において汝らを惑したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, '疫病の後ヱホバ、モーセと祭司アロンの子エレアザルに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'イスラエルの全會衆の總數をその父祖の家にしたがひて核べイスラエルの中凡そ二十歳以上にして戰爭に出るに勝る者を數へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'モーセ及び祭司エレアザルすなはちヱリコに對してヨルダンの邊にあるモアブの平野に於てかれらに告て言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'エジプトの地より出きたれるモーセとイスラエルの子孫にヱホバの命じ給へる如く汝ら其中の二十歳以上の者を計へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'イスラエルの長子はルベン、ルベンの子孫はヘノクよりヘノク人の族出でパルよりパル人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'ヘヅロンよりヘヅロン人の族出でカルミよりカルミ人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'ルベンの宗族は是のごとくにしてその核數られし者は四萬三千七百三千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'またパルの子はエリアブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'エリアブの子はネムエル、ダタン、アビラムこのダタンとアビラムは會衆の中に名ある者にてコラの黨類とともにモーセとアロンに逆ひてヱホバに悸りし事ありしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, '地その口を開きて彼らとコラとを呑みその黨類二百五十人は火に燒れて死うせ人の鑑戒となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, '但しコラの子等は死ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'シメオンの子孫はその宗族に依ば左のごとしネムエルよりはネムエル人の族出でヤミンよりはヤミン人の族出でヤキンよりはヤキン人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'ゼラよりはゼラ人の族出でシヤウルよりはシヤウル人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'シメオン人の宗族は是の如くにして其數られし者は二萬二千二百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'ガドの子孫は其宗族に依ば左の如しゼポンよりはゼポン人の族出でハギよりはハギ人の族出でシユニよりはシユニ人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'オズニよりはオズニ人の族出でエリよりはエリ人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'アロドよりはアロド人の族出でアレリよりはアレリ人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'ガドの宗族は是のごとくにしてその核數られし者は四萬五百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'ユダの子等はエルとオナン、エルとオナンはカナンの地に死たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'ユダの子孫はその宗族によれば左のごとしシラよりはシラ人の族出でペレヅよりはペレヅ人の族出でゼラよりはゼラ人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'ペレヅの子孫は左のごとしヘヅロンよりはヘヅロン人の族出でハムルよりけハムル人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'ユダの宗族は是のごとくにしてその核數られし者は七萬六千五百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'イツサカルの子孫はその宗族によれば左のごとしトラよりはトラ人の族出でプワよりはプワ人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'ヤシユブよりはヤシユブ人の族出でシムロンよりはシムロン人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'イッサカルの宗族は是のごとくにしてその數へられし者は六萬四千三百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'ゼブルンの子孫はその宗族によれば左の如しセレデよりはセレデ人の族出でエロンよりはエロン人の族出でヤリエルよりはヤリエル人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'ゼブルン人の宗族は是のごとくにしてその核數られし者は六萬五百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'ヨセフの子等はその宗族に依ばマナセとエフライム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'マナセの子等の中マキルよりマキル人の族出づマキル、ギレアデを生りギレアデよりギレアデ人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'ギレアデの子孫は左のごとしイエゼルよりはイエゼル人の族出でヘレクよりはヘレク人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'アスリエルよりはアスリエル人の族出でシケムよりはシケム人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'セミダよりはセミダ人の族出でヘペルよりはヘペル人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'ヘペルの子ゼロペハデには男子なく惟女子ありしのみその名はマアラ、ノア、ホグラ、ミルカ、テルザと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'マナセの宗族は是のごとくにしてその核數られし者は五萬二千七百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'エフライムの子孫はその宗族によれば左のごとしシユテラよりはシユテラ人の宗族出でベケルよりはベケル人の族出でタハンよりはタハン人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'シユテラの子孫は左のごとしエランよりエラン人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'エフライムの子孫の宗族は是のごとくにしてその核數られし者は三萬二千五百人ヨセフの子孫はその宗族に依ば是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'ベニヤミンの子孫はその宗族によれば左のごとしベラよりはベラ人の族出でアシベルよりはアシベル人の族出でアヒラムよりはアヒラム人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'シユパムよりはシユパム人の族出でホパムよりはホパム人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'ベラの子等はアルデとナアマン、アルデよりはアルデ人の族出でナアマンよりはナアマン人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'ベニヤミンの子孫はその宗族に依ば是のごとくにしてその核數られし者は四萬五千六百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'ダンの子孫はその宗族に依ば左のごとしシユハムよりシユハム人の族出づダンの宗族はその宗族によれば是の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'シユハム人の諸の族の中核數られし者は六萬四千四百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'アセルの子孫はその宗族によれば左のごとしヱムナよりはヱムナ人の族出でヱスイよりはヱスイ人の族出でベリアよりはベリア人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'ベリアの子孫の中ヘベルよりはヘベル人の族出でマルキエルよりはマルキエル人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'アセルの女子の名はサラと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'アセルの子孫の宗族は是のごとくにしてその核數られし者五萬三千四百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'ナフタリの子孫はその宗族によれば左のごとしヤジエルよりヤジエル人の族出でグニよりグニ人の族出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'ヱゼルよりヱゼル人の族出でシレムよりシレム人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'ナフタリの宗族はその宗族によればかくのごとくにしてその核數られしものは四萬五千四百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'すなはちイスラエルの子孫の核數られし者は六十萬一千七百三十人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'この人々にその名の數にしたがひて地を分ち與へてこれが產業となさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, '人衆には汝多くの產業を與へ人寡には少の產業を與ふべし即ちその核數られし數にしたがひておのおの產業を受べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, '但しその地は鬮をもて之を分ちその父祖の支派の名にしたがひて之を獲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, '即ち鬮をもてその產業を人衆き者と寡き者とに分つべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'レビ人のその宗族にしたがひて數へられし者は左のごとしゲルションよりはゲルション人の族出でコハテよりはコハテ人の族出でメラリよりはメラリ人の族出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'レビの族は左のごとしリブニ人の族ヘブロン人の族マヘリ人の族ムシ人の族コラ人の族コハテ、アムラムを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'アムラムの妻の名はヨケベデといひてレビの女子なり是はエジプトにてレビに生れし者なりしがアムラムにそひてアロンとモーセおよびその姉妹ミリアムを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'アロンにはナダブ、アビウ、エレアザルおよびイタマル生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'ナダブとアビウは異火をヱホバの前にささげし時死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'その核數られし一箇月以上の男子は都合二萬三千人レビ人はイスラエルの子孫の中に產業を與へられざるが故にイスラエルの子孫の中に核數られざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, '是すなはちモーセと祭司エレアザルがヨルダンの邊なるヱリコに對するモアブの平野にて數へたるイスラエルの子孫の數なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, '但しその中にはモーセとアロンがシナイの曠野においてイスラエルの子孫をかぞへし時に數へたる者は一人もあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, '其はヱホバ曾て彼らの事を宣て是はかならず曠野に死んといひたまひたればなり是をもてヱフンネの子カルブとヌンの子ヨシュアの外は一人も遺れる者あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, '茲にヨセフの子マナセの族の中なるヘペルの子ゼロペハデの女子等きたれりヘペルはギレアデの子ギレアデはマキルの子マキルはマナセの子なりその女子等の名はマアラ、ノア、ホグラ、ミルカ、テルザといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, '彼ら集會の幕屋の門にてモーセと祭司エレアザルと牧伯等と全會衆の前に立ち言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '我等の父は曠野に死り彼はかのコラに與して集りてヱホバに逆ひし者等の中に加はらず自己の罪に死り然るに男子なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, '我らの父の名なんぞその男子あらざるがためにその族の中より削らるることある可んや我らの父の兄弟の中において我らにも產業を與へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'モーセすなはちその事をヱホバの前に陳けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'ゼロペハデの女子等の言ところは道理なり汝かならず彼らの父の兄弟の中において彼らに產業を與へて獲さすべし即ちその父の產業をこれに歸せしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, '汝イスラエルの子孫に告て言べし人もし男子なくして死ばその產業をこれが女子に歸せしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'もしまた女子もあらざる時はその產業をその兄弟に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'もし兄弟あらざる時はその產業をその父の兄弟に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'もしまたその父に兄弟あらざる時はその親戚の最も近き者にその產業を與へて獲さすべしヱホバのモーセに命ぜしごとくイスラエルの子孫は永く之をもて律法の例とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, '茲にヱホバ、モーセに言たまはく汝このアバリム山にのぼり我イスラエルの子孫に與へし地を觀よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, '汝これを觀なばアロンの旣に加はりしごとく汝もその民に加はるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, '是チンの曠野において會衆の爭論をなせる砌に汝らわが命に悸りかの水の側にて我の聖き事をかれらの目のまへに顯すことを爲ざりしが故なり是すなはちチンの曠野のカデシにあるメリバの水なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'モーセ、ヱホバに申して言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'ヱホバ一切の血肉ある者の生命の神よ願くはこの會衆の上に一人を立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, '之をして彼等の前に出かれらの前に入り彼らを導き出し彼らを導き入る者とならしめヱホバの會衆をして牧者なき羊のごとくならざらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'ヱホバ、モーセに言たまはくヌンの子ヨシユアといふ霊のやどれる人を取り汝の手をその上に按き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'これを祭司エレアザルと全會衆の前に立せて彼らの前にて之に命ずる事をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, '汝これに自己の尊榮を分ち與ヘイスラエルの子孫の全會衆をしてこれに順がはしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, '彼は祭司エレアザルの前に立べしエレアザルはウリムをもて彼のためにヱホバの前に問ことを爲べしヨシユアとイスラエルの子孫すなはちその全會衆はエレアザルの言にしたがひて出でエレアザルの言にしたがひて入べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, '是においてモーセはヱホバの己に命じたまへるごとく爲しヨシユアを取て之を祭司エレアザルと全會衆の前に立せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'その手をこれが上に按き之に命ずることを爲しヱホバのモーセをもて命じたまへる如くなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'イスラエルの子孫に命じて之に言へわが禮物わが食物なる火祭わが馨香の物は汝らこれをその期にいたりて我に献ぐることを怠るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, '汝かれらに言べし汝らがヱホバに献ぐる火祭は是なり即ち當歳の全たき羔羊二匹を日々に献げて常燔祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, '即ち一匹の羔羊を朝に献げ一匹の羔羊を夕に献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'また麥粉一エパの十分の一に搗て取たる油一ヒンの四分の一を混和て素祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, '是すなはちシナイ山において定めたる常燔祭にしてヱホバに馨しき香としてたてまつる火祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'またその灌祭は羔羊一匹に一ヒンの四分の一を用ふべし即ち聖所において濃酒をヱホバのために灌ぎて灌祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, '夕にはまた今一の羔羊を献ぐべしその素祭と灌祭とは朝のごとくになし之を献げて火祭となしてヱホバに馨しき香をたてまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'また安息日には當歳の羔羊の全き者二匹と麥粉十分の二に油をまじへたるその素祭とその灌祭を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, '是すなはち安息日ごとの燔祭にして常燔祭とその灌祭の外なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'また汝ら月々の朔日には燔祭をヱホバに献ぐべし即ち少き牡牛二匹牡羊一匹當歳の羔羊の全き者七匹を献げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, '牡牛一匹には麥粉十分の三に油を和たるをもてその素祭となし牡羊一匹には麥粉十分の二に油をまじへたるをもてその素祭となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, '羔羊一匹には麥粉十分の一に油を混和たるをもてその素祭となし之を馨しき香の燔祭としてヱホバに火祭をたてまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'またその灌祭は牡牛一匹に酒一ヒンの半牡羊一匹に一ヒンの三分の一羔羊一匹に一ヒンの四分の一を用ふべし是すなはち年の月々の中月ごとに献ぐべき燔祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'また常燔祭とその灌祭の外に牡山羊一匹を罪祭としてヱホバに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, '正月の十四日はヱホバの逾越節なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'またその月の十五日は節日なり七日の間酵いれぬパンを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'その首の日には聖會をひらくべし汝等何の職業をも爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, '汝ら火祭を献げてヱホバに燔祭たらしむるには少き牡牛二匹牡羊一匹當歳の羔羊七匹をもてすべし是等は皆全き者なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'その素祭には麥粉に油を和たるを用べし即ち牡牛一匹には麥粉十分の三を献げ牡羊一匹には十分の二を献げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'また羔羊は七匹ともその羔羊一匹ごとに十分の一を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'また牡山羊一匹を罪祭に献げて汝らのために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, '朝に献ぐる常燔祭なる燔祭の外に汝ら是らを献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, '是のごとく汝ら七日の間日ごとに火祭の食物を献げてヱホバに馨しき香をたてまつるべし是は常燔祭とその灌祭の外に献ぐべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, '而して第七日には汝ら聖會を開くべし何の職業をち爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, '七七日の後すなはち汝らが新しき素祭をヱホバに携へきたる初穂の日にも汝ら聖會を開くべし何の職業をも爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, '汝ら燔祭を献げてヱホバに馨しき香をたてまつるべし即ち少き牡牛二匹牡羊一匹當歳の羔羊七匹を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'その素祭には麥粉に油を混和たるを用ふべし即ち牡牛一匹に十分の三牡羊一匹に十分の二を用ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'また羔羊には七匹ともに羔羊一匹に十分の一を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'また牡山羊一匹をささげて汝らのために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, '汝ら常燔祭とその素祭とその灌祭の外に是等を献ぐべし是みな全き者なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '七月にいたりその月の朔日に汝ら聖會を開くべし何の職業をも爲べからず是は汝らが喇叭を吹べき日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, '汝ら燔祭をささげてヱホバに馨しき香をたてまつるべし即ち少き牡牛一匹牡羊一匹當歳の羔羊の全き者七匹を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'その素祭には麥粉に油を混和たるを用ふべし即ぢ牡牛一匹に十分の三牡羊一匹に十分の二をもちひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'また羔羊には七匹とも羔羊一匹に十分の一を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'また牡山羊一匹を罪祭に献げて汝らのために贖罪をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, '是は月々の朔日の燔祭とその素祭および日々の燔祭とその素祭と灌祭の外なる者なり是らの物の例にしたがひて之をヱホバにたてまつりて馨しき香の火祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'またその七月の十日に汝ら聖會を開きかつ汝らの身をなやますべし何の職業をも爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, '汝らヱホバに燔祭を献げて馨しき香をたてまつるべし即ち少き牡牛一匹牡羊一匹當歳の羔羊七匹是みな全き者なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'その素祭には麥粉に油を混和たるを用ふべし即ち牡牛一匹に十分の三牡羊一匹に十分の二を用ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'また羔羊には七匹とも羔羊一匹に十分の一を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'また牡山羊一匹を罪祭に献ぐべし是等は贖罪の罪祭と常燔祭とその素祭と灌祭の外なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, '七月の十五日に汝ら聖會を開くべし何の職業をも爲べからず汝ら七日の間ヱホバに向て節筵を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, '汝ら燔祭を献げてヱホバに馨しき香の火祭をたてまつるべし即ち少き牡牛十三牡羊二匹當歳の羔羊十四是みな全き者なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'その素祭には麥粉に油を混和たるを用ふべし即ちその十三の牡牛には各箇十分の三その二匹の牡羊には各箇十分の二を用ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'その十四の羔羊には各箇十分の一を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'また牡山羊一匹を罪祭に献ぐべし是等は常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, '第二日には少き牡牛十二牡羊二匹當歳の羔羊の全き者十四を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'その牡牛と牡羊と羔羊のために用ふる素祭と灌祭はその數に循ひて例のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'また牡山羊一匹を罪祭に献ぐべし是らは常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, '第三日には少き牡牛十一牡羊二匹當歳の羔羊の全き者十四を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'その牡牛と牡羊と羔羊のために用ふる素祭と灌祭はその數に循ひて例のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'また牡山羊一匹を罪祭に献ぐべし是らは常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, '第四日には少き牡牛十匹牡羊二匹當歳の羔羊の全き者十四を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'その牡牛と牡羊と羔羊のために用ふる素祭と灌祭はその數に循ひて例のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'また牡山羊一匹を罪祭に献ぐべし是等は常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, '第五日には少き牡牛九匹牡羊二匹當歳の羔羊の全き者十四を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'その牡牛と牡羊と羔羊のために用ふる素祭と灌祭はその數にしたがひて例のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'また牡山羊一匹を罪祭に献ぐべし是らは常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, '第六日には少き牡牛八匹牡羊二匹當歳の羔羊の全き者十四を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'その牡牛と牡羊と羔羊のために用ふる素祭と灌祭はその數にしたがひて例のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'また牡山羊一匹を罪祭に献ぐべし是等は常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, '第七日には少き牡牛七匹牡羊二匹當歳の羔羊の全き者十四を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'その牡牛と牡羊と羔羊のために用ふる素祭と灌祭はその數にしたがひて例のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'また牡山羊一匹を罪祭に献ぐべし是等は常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, '第八日にはまた汝ら會をひらくべし何の職業をも爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, '燔祭を献げてヱホバに馨しき香の火祭をたてまつるべし即ち牡牛一匹牡羊一匹當歳の羔羊の全き者七匹を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'その牡牛と牡羊と羔羊のために用ふる素祭と灌祭はその數にしたがひて例のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'また牡山羊一匹を罪祭に献ぐべし是らは常燔祭およびその素祭と灌祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, '汝らその節期にはヱホバに斯なすべし是らは皆汝らが願還のために献げまたは自意の禮物として献ぐる所の燔祭素祭灌祭および酬恩祭の外なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'モーセはヱホバのモーセに命じたまへる事をことごとくイスラエルの子孫に告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'モーセ、イスラエルの子孫の支派の長等に告て云ふヱホバの命じたまふ事は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, '人もしヱホバに誓願をかけ又はその身に斷物をなさんと誓ひなばその言詞を破るべからずその口より出ししごとく凡て爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'また女もし若くしてその父の家に居る時ヱホバに誓願をかけ又はその身斷物を爲ことあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'その父これが誓願またはその身に斷し斷物を聞て之にむかひて言ふこと無ば其かけたる誓願を行ひまたその身に斷し斷物を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, '然どその父これを聞る日に之を允さざるあらばその誓願およびその身に斷し斷物を凡て止ることを得べしその父の允さざるなればヱホバこれを赦したまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'もしまた夫に適く身にして自ら誓願をかけまたはその身に斷物せんと軽々しく口より言いだすことあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'その夫これを聞もそのこれを聞る日にこれに向ひて言ふこと無ばその誓願を行ひその身に斷し斷物を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'されど夫もし之を聞る日にこれを允さざるならば之がかけし誓願または之がその身に斷物せんと軽々しく口に出ししところの事を空うするを得べしヱホバはその女を赦したまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'また寡婦あるひは去れたる婦人の誓願など凡てその身になしし斷物はこれを守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, '婦女もしその夫の家において誓願をかけ又はその身に斷物せんと誓ふことあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, '夫これを聞てこれに對ひて言ふことなく之を允さざること無ばその誓願は凡てこれを行ふべくその身に斷し斷物は凡てこれを守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, '然どその夫もしこれを聞る日に全くこれを空うせばその誓願またはその斷物につき口より出しし事は凡て守るに及ばずその夫これを空くなしたるなればヱホバその婦女を赦したまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, '凡の誓願および凡てその身をなやますところの誓約は夫これを堅うすることを得夫これを空うすることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'その夫もし之にむかひて言ふことなくして日をおくらば之が誓願またはこれが斷物を凡て堅うするなり彼これを聞る日に妻にむかひて言ふことを爲ざるに因て之を堅うせるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, '然どその夫もしこれを聞たる後にいたりてこれを空うする事あらばその妻の罪を任べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, '是すなはちヱホバがモーセに命じたまへる法令にして夫と妻および父とその女子の少くして父の家にある者とにかかはる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, '茲にヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '汝イスラエルの子孫の仇をミデアン人に報ゆべし其後汝はその民に加はらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'モーセすなはち民に告て言けるは汝らの中より人を選みて戰爭にいづる准備をなさしめ之をしてミデアン人に攻ゆかしめてヱホバの仇をミデアン人に報ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, '即ちイスラエルの諸の支派につきて各々の支派より千人づつを取りこれを戰爭につかはすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, '是において各々の支派より千人づつを選みイスラエルの衆軍の中より一萬二千人を得て戰爭にいづる准備をなさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'モーセすなはち各々の支派より千人宛を戰爭に遣しまた祭司エレアザルの子ピネハスに聖器と吹鳴す喇叭を執しめて之とともに戰爭に遣せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, '彼らヱホバのモーセに命じたまへるごとくミデアン人を攻撃ち遂にその中の男子をことごとく殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'その殺しし者の外にまたミデアンの王五人を殺せりそのミデアンの王等はエビ、レケム、ツル、ホル、レバといふまたベオルの子バラムをも劍にかけて殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'イスラエルの子孫すなはちミデアンの婦女等とその子女を生擒りその家畜と羊の群とその貨財をことごとく奪ひ取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'その住居の邑々とその村々とを盡く火にて燒り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'かくて彼等はその奪ひし物と掠めし物を人と畜ともに取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'ヱリコに對するヨルダンの邊なるモアブの平野の營にその生擒し者と掠めし物と奪ひし物とを携へきたりてモーセと祭司エレアザルとイスラエルの子孫の會衆に詣れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, '時にモーセと祭司エレアザルおよび會衆の牧伯等みな營の外に出て之を迎へたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'モーセはその軍勢の領袖等すなはち戰爭より歸りきたれる千人の長等と百人の長等のなせる所を怒れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'モーセすなはち彼等に言けるは汝らは婦女等をことごとく生し存しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, '視よ是等の者はバラムの謀計によりイスラエルの子孫をしてペオルの事においてヱホバに罪を犯さしめ遂にヱホバの會衆の中に疫病おこるにいたらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, '然ばこの子等の中の男の子を盡く殺しまた男と寝て男しれる婦人を盡く殺せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, '但し未だ男と寝て男しれる事あらざる女の子はこれを汝らのために生し存べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, '而して汝らは七日の間營の外に居れ汝らの中凡そ人を殺せし者または殺されし者に捫りたる者は第三日と第七日にその身を潔め且その俘囚を潔むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'また一切の衣服と一切の皮の器具および凡て山羊の毛にて作れる物と凡て木にて造れる物を潔むべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, '祭司エレアザル戰にいでし軍人等に言けるはヱホバのモーセに命じたまへる律法の例は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, '金銀銅鐵錫鉛など');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, '凡て火に勝る物は火の中を通すべし然せば潔くならん然ながら尚また潔淨の水をもてこれを潔むべしまた凡て火に勝ざる者は水の中を通すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, '汝等は第七日にその衣服を洗ひて潔くなり然る後營にいるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'その時ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '汝と祭司エレアザルおよび會衆の族長等この取獲たる人と畜の總數をしらべ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'その獲物を二分に分てその一を戰爭にいでて戰ひし者に予へその一を全會衆に予へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, '而して戰ひに出し軍人をして人または牛または驢馬または羊おのおの五百ごとに一をとりてヱホバに貢として奉つらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, '即ち彼らの一半より之をとりヱホバの擧祭として祭司エレアザルに與へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'またイスラエルの子孫の一半よりはその獲たる人または牛または驢馬または羊または種々の獣畜五十ごとに一を取りヱホバの幕屋の職守を守るところのレビ人にこれを與へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'モーセと祭司エレアザルすなはちヱホバのモーセに命じたまへるごとく爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'その掠取物すなはち軍人等が奪ひ獲たる物の殘餘は羊六十七萬五千');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, '牛七萬二千');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, '驢馬六萬一千');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, '人三萬二千是みな未だ男と寝て男しれる事あらざる女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'その一半すなはち戰爭にいでし者の分は羊三十三萬七千五百');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'ヱホバに貢として奉つれる羊は六百七十五');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, '牛三萬六千その中よりヱホバに貢とせし者は七十二');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, '驢馬三萬五百その中よりヱホバに貢とせし者は六十一');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, '人一萬六千その中よりヱホバに貢とせし者は三十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'モーセその貢すなはちヱホバの擧祭なる者を祭司エレアザルに與へたりヱホバのモーセに命じたまへる如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'モーセが戰爭に出しものより分ちとりてイスラエルの子孫に予へし一半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'すなはち會衆に屬する一半は羊三十三萬七千五百');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, '牛三萬六千');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, '驢馬三萬五百');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, '人一萬六千');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'すなはちイスラエルの子孫のその一半よりモーセ人と畜ともに各箇五十ごとに一を取りヱホバの幕屋の職守をまもるレビ人に之を與へたりヱホバのモーセに命じたまへるごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, '時に其軍勢の帥士たりし者等すなはち千人の長百人の長等モーセにきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'モーセに言けるは僕等我らの手に屬する軍人を數へたるにわれらの中一人も缺たる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, '是をもて我ら各人その獲たる金の飾品すなはち鏈子釧指鐶耳環頸玉等をヱホバに携へきたりて禮物となし之をもて我らの生命のためにヱホバの前に贖罪をなさんとすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'モーセと祭司エレアザルすなはち彼らよりその金を受たり是みな製り成る飾品なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, '千人の長と百人の長たちがヱホバに献げて擧祭となせしその金は都合一萬六千七百五十シケル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '軍人は各箇その掠取物をもて自分の有となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'モーセと祭司エレアザルは千人の長と百人の長等よりその金を受て集會の幕屋に携へいりヱホバの前におきてイスラエルの子孫の記念とならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'ルベンの子孫とガドの子孫は甚だ多くの家畜の群を有り彼等ヤゼルの地とギレアデの地を觀るにその處は家畜に適き所なりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'ガドの子孫とルベンの子孫來りてモーセと祭司エレアザルと會衆の牧伯等に言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'アタロテ、デボン、ヤゼル、ニムラ、ヘシボン、エレアレ、シバム、ネボ、ベオン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, '即ちヱホバがイスラエルの會衆の前に撃ほろぼしたまひし國は家畜に適き所なるが我らは家畜あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'また曰ふ然ば我らもし汝の目の前に恩を獲たらば請ふこの地を僕等に與へて產業となさしめ我らをしてヨルダンを濟ること無らしめよと斯いへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'モーセ、ガドの子孫とルベンの子孫に言けるは汝らの兄弟たちは戰ひに往に汝らは此に坐しをらんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, '汝ら何ぞイスラエルの子孫の心を挫きてヱホバのこれに賜ひし地に濟ることを得ざらしめんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, '汝らの先祖等も我がカデシバルネアより其地を觀に遣せし時に然なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, '即ち彼らエシコルの谷に至りて其地を觀し時イスラエルの子孫の心を挫きて之をしてヱホバの賜ひし地に往ことを得ざらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'その時ヱホバ怒を發し誓ひて言たまひけらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'エジプトより出きたれる人々の二十歳以上なる者は一人も我がアブラハム、イサク、ヤコブに誓ひたる地を見ざるべし其はかれら我に全くは從はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, '第ケナズ人ヱフンネの子カルブとヌンの子ヨシユアとを除く此二人はヱホバに全く從ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'ヱホバかくイスラエルにむかひて怒を發し之をして四十年のあひだ曠野にさまよはしめたまひければヱホバの前に惡をなししその代の人みな終に亡ぶるに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, '抑汝らはその父に代りて起れる者即ち罪人の種にしてヱホバのイスラエルにむかひて懐たまふ烈しき怒を更に増んとするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, '汝ら若反きてヱホバに從はずばヱホバまたこの民を曠野に遺おきたまはん然せば汝等すなはちこの民を滅ぼすにいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, '彼らモーセの側に進みよりて言けるは我らは此に我らの群のために羊の圈を建我らの少者のために邑を建んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, '然ど我らはイスラエルの子孫をその處に導きゆくまでは身をよろひて之が前に奮ひ進まん第われらの少者はこの國に住る者等のために堅固なる邑に居ざるを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, '我らはイスラエルの子孫が皆おのおのその產業を獲までは我らの家に歸らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, '我らはヨルダンの彼旁において彼らと偕に產業を獲ことを爲じ我らはヨルダンの此旁すなはち東の方に產業を獲ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'モーセかれらに言けるは汝らもしこの事を爲し汝らみな身をよろひてヱホバの前に往て戰ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, '汝ら皆身をよろひヱホバの前にゆきてヨルダンを濟りヱホバのその敵を己の前より逐はらひたまひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'この國のヱホバに服ふにおよびて後汝ら歸ばヱホバの前にもイスラエルの前にも汝ら罪なかるべし然せばこの地はヱホバの前において汝らの產業とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, '然ど汝らもし然せずば是ヱホバにむかひて罪を犯すなれば必ずその罪汝らの身におよぶと知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, '汝らその少者のために邑を建てその羊のために圈を建よ而して汝らの口より出せるところを爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'ガドの子孫とルベンの子孫モーセにこたへて言けるはわが主の命じたまふごとく僕等行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, '我らの少者と妻と羊と諸の家畜は此にギレアデの邑々に居べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, '然ど僕等はおのおの戰爭のために身をよろひてわが主の言たまふ如くヱホバの前に渉りゆきて戰ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, '是においてモーセかれらの爲に祭司エレアザルとヌンの子ヨシユアとイスラエルの支派の族長等に命ずる事ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'すなはちモーセかれらに言けるはガドの子孫とルベンの子孫もし汝らとともにヨルダンを濟りゆき各箇身をよろひてヱホバの前に戰ひてこの地汝らに服ふにいたらば汝らギレアデの地をかれらに與へて產業となさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, '然ど彼らもし汝らとともに身をよろひて濟りゆかずば彼らはカナンの地に於て汝らの中に產業を獲ざる可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'ガドの子孫とルベンの子孫こたへて言ふヱホバが僕等に言たまふごとく我ら爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, '我らは身をよろひてヱホバの前にカナンの地に濟りゆきヨルダンの此旁なる我らの產業を保つことを爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, '是においてモーセはアモリ人の王シホンの國とバシヤンの王オグの國をもてガドの子孫とルベンの子孫とヨセフの子マナセの支派の半とに與へたり即ちその國およびその境の内の邑々とその邑々の周圍の地とを之に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'ガドの子孫はデボン、アタロテ、アロエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'アテロテ、シヨバン、ヤゼル、ヨグベハ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'ベテニムラ、ベテハランなどの堅固なる邑を建て羊のために圈を建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'またルベンの子孫はヘシボン、エレアレ、キリヤタイム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'ネボ、バアルメオン等の邑を建てその名を更めまたシブマの邑を建たりその建たる邑々には新しき名をつけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'またマナセの子マキルの子孫はギレアデに至りてこれを取り其處にをりしアモリ人を逐はらひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'モーセ、ギレアデをマナセの子マキルに與へて其處に住しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'またマナセの子ヤイルは往てその村々を取りこれをハヲテヤイル(ヤイル村)と名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'またノバは往てケナテとその村々を取り自己の名にしたがひて之をノバと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'イスラエルの子孫がモーセとアロンに導かれ其軍旅にしたがひてエジプトの國より出きたりて經たる旅路は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'モーセ、ヱホバの命に依りその旅路にしたがひてこれが發程を記せりその發程によればその旅路は左のごとくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, '彼らは正月の十五日にラメセスより出立り即ぢ逾越の翌日にイスラエルの子孫は一切のエジプト人の目の前にて高らかなる手によりて出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, '時にエジプト人はヱホバに撃ころされし其長子を葬りて居りヱホバはまた彼らの神々にも罰をかうむらせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'イスラエルの子孫ラメセスより出立てスコテに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'スコテより出立て曠野の極端なるエタムに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'エタムより出立てバアルゼポンの前なるピハヒロテに轉りゆきてミグドルに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'ピハヒロテの前より出立ち海の中を通りて曠野にいりエタムの曠野に三日路ほど入てメラに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'メラより出立てヱリムに至れりエリムには泉十二棕櫚七十本あり乃ち此に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'かくてエリムより出たちて紅海の邊に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, '紅海より出たちてシンの曠野に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'シンの曠野より出たちてドフカに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'ドフカより出たちてアルシに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'アルシより出たちてレピデムに營を張り此には民の飮む水あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'かくてレピデムより出たちてシナイの曠野に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'シナイの曠野より出たちてキブロテハッタワに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'キブロテハッタワより出たちてハゼロテに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'ハゼロテより出たちてリテマに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'リテマより出たちてリンモンバレツに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'リンモンパレツより出たちてリブナに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'リブナより出たちてリッサに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'リッサより出たちてケヘラタに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'ケヘラタより出たちてシヤペル山に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'シヤペル山より出たちてハラダに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'ハラダより出たちてマケロテに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'マケロテより出たちてタハテに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'タハテより出たちてテラに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'テラより出たちてミテカに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'ミテカより出たちてハシモナに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'ハシモナより出たちてモセラに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'モセラより出たちてベネヤカンに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'ベネヤカンより出たちてホルハギデガデに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'ホルハギデガデより出たちてヨテバタに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'ヨテバタより出たちてアブロナに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'アブロナより出たちてエジオングベルに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'エジオングベルより出たちてカデシのチンの曠野に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'カデシより出たちてエドムの國の界なるホル山に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'イスラエルの子孫がエジプトの國を出てより四十年の五月の朔日に祭司アロンはヱホバの命によりてホル山に登て其處に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'アロンはホル山に死たる時は百二十三歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'カナンの地の南に住るカナン人アラデ王といふ者イスラエルの子孫の來るを聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'かくてホル山より出たちてザルモナに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'ザルモナより出立てプノンに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'プノンより出たちてオボテに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'オボテより出たちてモアブの界なるイヱアバリムに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'イヰムより出たちてデボンガドに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'デボンガドより出たちてアルモンデブラタイムに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'アルモンデブラタイムより出たちてネボの前なるアバリムの山々に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'アバリムの山々より出たちてヱリコに對するヨルダンの邊なるモアブの平野に營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'すなはちモアブの平野においてヨルダンの邊に營を張りベテヱシモテよりアベルシッテムにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'ヱリコに對するヨルダンの邊なるモアブの平野においてヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'イスラエルの子孫に告てこれに言へ汝らヨルダンを濟りてカナンの地に入る時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'その地に住る民をことごとく汝らの前より逐はらひその石の像をことごとく毀ちその鋳たる像を毀ちその崇邱をことごとく毀ちつくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, '汝らその地の民を逐はらひて其處に住べし其は我その地を汝らの產業として汝らに與へたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, '汝らの族にしたがひ鬮をもてその地を分ちて產業となし人多きには多くの產業を與へ人少きには少しの產業を與ふべし各人の分はその鬮にあたれる處にあるべきなり汝らその先祖の支派にしたがひて之を獲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, '然ど汝らもしその地に住る民を汝らの前より逐はらはずば汝らが存しおくところの者汝らの目に莿となり汝の脇に棘となり汝らの住む國において汝らを惱さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, '且また我は彼らに爲んと思ひし事を汝らに爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'ヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'イスラエルの子孫に告てこれに言へ汝らがカナンの地にいる時に汝らに歸して產業となる地は是なり即ち是カナンの地その境に循へる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, '汝らの南の方はエドムに接すろチンの曠野より起り南の界は鹽海の極端より東の方にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'また汝らの界は南より繞りてアクラビムの坂にいたりてチンに赴き南よりカデシバルネアに亘りハザルアダルに進みアズモンに赴くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'その界はまたアズモンより繞りてエジプトの河にいたり海におよびて盡べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, '西の界においては大海をもてその界とすべし是を汝らの西の界とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, '汝らの北の界は是のごとし即ち大海よりホル山までを畫り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'ホル山よりハマテの入口までを畫りその界をしてゼダデまで亘らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'またその界はジフロンに進みハザルエノンにいたりて盡べし是を汝らの北の界とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, '汝らの東の界はハザルエノンよりシバムまでを畫るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'またその界はアインの東の方においてシバムよりリブラに下りゆくべし斯その界は下りてキンネレテの海の東の傍に抵り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'その界ヨルダンに下りゆきて鹽海におよびて盡べし汝らの國はその周圍の界に依ば是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'モーセ、イスラエルの子孫に命じて言けるは是すなはち汝らが鬮をもて獲べき地なりヱホバこれを九の支派と半支派とに與へよと命じたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'そはルベンの子孫の支派とガドの子孫の支派はともにその宗族にしたがひてその產業を受けまたマナセの半支派もその產業を受たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'この二の支派と半支派とはヱリコに對するヨルダンの彼旁すなはちその東日の出る方においてその產業を受たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '汝らに地を分つ人々の名は是なり即ち祭司エレアザルとヌンの子ヨシユア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, '汝らまた各箇の支派より牧伯一人づつを簡びて地を分つことを爲しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'その人々の名は是のごとしユダの支派にてはエフンネの子カルブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'シメオンの子孫の支派にてはアミホデの子サムエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'ベニヤミンの支派にてはキスロンの子エリダデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'ダンの子孫の支派の牧伯はヨグリの子ブッキ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'ヨセフの子孫すなはちマナセの子孫の支派の牧伯はエポデの子ハニエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'エフライムの子孫の支派の牧伯はシフタンの子ケムエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'ゼブルンの子孫の支派の牧伯はパルナクの子エリザバン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'イッサカルの子孫の支派の牧伯はアザンの子パルテエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'アセルの子孫の支派の牧伯はシロミの子アヒウデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'ナフタリの子孫の支派の牧伯はアミホデの子パダヘル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'カナンの地においてイスラエルの子孫に產業を分つことをヱホバの命じたまへる人は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'ヱリコに對するヨルダンの邊なるモアブの平野においてヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'イスラエルの子孫に命じてその獲たる產業の中よりレビ人に住べき邑々を與へしめよ汝らまたその邑々の周圍に郊地をつけてレビ人に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'その邑々は彼らの住べき所その郊地は彼らの家畜貨財および諸の獣をおくところたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, '汝らがレビ人に與ふる邑々の郊地は邑の石垣より外四周一千キユビトなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'すなはち邑の外に於て東の方に二千キユビト南の方に二千キユビト西の方に二千キユビト北の方に二千キユビトを量り邑をその中にあらしむべし彼らの邑の郊地は是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, '汝らがレビ人に與ふる邑々は是のごとくなるべし即ち逃遁邑六を與ふべし是は人を殺せる者の其處に逃るべきための者なり此外にまた邑四十二を與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, '汝らがレビ人に與ふる邑は都合四十八邑これを其郊地とともに與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, '汝らイスラエルの子孫の產業の中よりレビ人に邑を與ふるには多く有る者は多く與へ少く有る者は少く與へ各人その獲たる產業にしたがひてその邑々を之に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'ヱホバまたモーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'イスラエルの子孫に告てこれに言へ汝らヨルダンを濟りてカナンの地に入ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, '汝らのために邑を設けて逃遁邑と爲し誤りて人を殺せる者をして其處に逃るべからしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, '其は汝らが仇打する者を避て逃るべき邑なり是あるは人を殺せる者が未だ會衆の前にたちて審判をうけざる先に殺さるること無らんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, '汝らが予ふる邑々の中六をもて逃遁邑とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'すなはち汝らヨルダンの此旁において三の邑を予ヘカーナンの地において三の邑を予へて逃遁邑となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'この六の邑はイスラエルの子孫と他國人およびその中に寄寓る者の逃遁場たるべし凡て誤りて人を殺せる者は其處に逃るることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'もし鐵の器をもて人を撃て死しめなば是故殺なり故殺人はかならず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'もし人を殺すほどの石を執て人を撃て死しめなば是故殺なり故殺人はかならず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'また人を殺すほどの木の器をとりて人を撃て死しめなば是故殺なり故殺人はかならず殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, '仇を打つ者その故殺人を殺すことを得すなはち之に遭ふところにて之を殺すことを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'もしまた怨恨のために人を推しまたは意ありて人に物を投うちて死しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'または敵の心を挾さみ手をもて人を撃て死しめなばその人を撃たる者は必ず殺さるべし是故殺なればなり仇を打つ者これに遭ふところにて之を殺すことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, '然どもし敵の心なくして思はず人を推しまたは意なくして人に物を擲ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'または人あるを見ずして人を殺すほどの石を之に投つけて死しむること有んにその人これが敵にもあらずまた之を害せんとせしにもあらざる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, '會衆この律法によりてその人を殺せる者と仇打する者とに審判を言わたすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, '即ち會衆はその人を殺せる者を仇打する者の手より救ひ出してこれをその逃れゆきたる逃遁邑に還すべしその者は聖膏を灌れたる祭司の長の死るまで其處に居べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, '然ど人を殺しし者その逃れし逃遁邑の境を出でたらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, '仇打する者その逃遁邑の境の外にてこれに遭ことありて仇打する者すなはちその人を殺しし者を殺すことあるとも血をながせる罪あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, '其は彼は祭司の長の死るまでその逃遁邑に居べき者なればなり祭司の長の死たる後はその人を殺せし者おのれの產業の地にかへることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, '汝ら代々その住所において之を審判の法度とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, '凡て人を殺せる者すなはち故殺人は證人の口にしたがひて殺さるべし然ど只一人の證人の言にしたがひて人を殺すことを爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, '汝ら死に當る故殺人の生命を贖はしむべからず必ずこれを殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'また逃遁邑に逃れたる者の贖を容て祭司の死ざる前にこれを自己の地に歸り住しむる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, '汝らその居ところの地を汚すべからず血は地を汚すなり地の上に流せる血は之を流せる者の血をもてするに非れば贖ふことを得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, '汝らその住ところの地すなはち我が居ところの地を汚すなかれ其は我ヱホバ、イスラエルの子孫の中に居ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'ヨセフの子等の族の中マナセの子マキルの子なるギレアデの子等の族の族長等進みよりてモーセの前とイスラエルの子孫の族長たる牧伯等の前に語り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, '言けるはイスラエルの子孫にその產業の地を鬮によりて與ふることをヱホバわが主に命じたまへり吾主またわれらの兄弟ゼロペハデの產業をその女子等に與ふべしとヱホバに命ぜられたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, '彼らもしイスラエルの子孫の中他の支派の人々に嫁ぎなば彼らの產業はわれらの父祖の產業の中より除去れてその適る支派の產業に加はるべし斯是は我らの產業の分の中より除去れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, '而して彼らの產業はイスラエルの子孫のヨベルに至りてその適る支派の產業に加はるべし斯かれらの產業は我らの父祖の支派の產業の中より除去れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'モーセ、ヱホバの言にしたがひてイスラエルの子孫に命じて言ふヨセフの子等の支派の言ところは善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'ゼロペハデの女子等の事につきてヱホバの命じたまふところは是のごとし云く彼らはその心に適ふ者に嫁ぐべけれど惟その父祖の支派の家にのみ嫁ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, '然せばイスラエルの子孫の產業この支派よりかの支派に移ることあらじイスラエルの子孫はみな各箇その父祖の支派の產業に止まるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'イスラエルの子孫の支派の中凡そ產業を有る女は皆おのれの父の支派の家に嫁ぐべし然せばイスラエルの子孫おのおのその父祖の產業を保つことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, '產業をしてこの支派よりかの支派に移らしむべからずイスラエルの子孫の支派の者は皆おのおの自己の產業にとどまるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, '是においてゼロペハデの女子等はヱホバのモーセに命じたまへる如くせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, '即ちゼロペハデの女子等マアラ、テルザ、ホグラ、ミルカおよびノアはその父の兄弟の子等に嫁げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, '彼らはヨセフの子マナセの子等の家に嫁ぎたればその產業はその父の族の支派に止まれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, '是等はヱリコに對するヨルダンの邊なるモアテの平野においてヱホバがモーセによりてイスラエルの子孫に命じたまひし命令と律法なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, '是はモーセがヨルダンの此旁の曠野紅海に對する平野に在てバラン、トベル、ラバン、ハゼロテ、デザハブの間にてイスラエルの一切の人に告たる言語なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'ホレブよりセイル山の路を經てカデシバルネアに至るには十一日路あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, '第四十年の十一月にいたりその月の一日にモーセはイスラエルの子孫にむかひてヱホバが彼等のために自己に授けたまひし命令を悉く告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, '是はモーセがヘシボンに住るアモリ人の王シホン及びエデレイのアシタロテに住るバシヤンの王オグを殺したる後なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, '即ちモーセ、ヨルダンの此旁なるモアブの地においてこの律法を解明すことを爲し始めたり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '我らの神ヱホバ、ホレブにて我らに告て言たまへり汝らはこの山に居こと日すでに久し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, '汝ら身を轉らして途に進みアモリ人の山に往き其に鄰れる處々に往き平野山地窪地南の地海邊カナン人の地レバノンおよび大河ユフラテ河に至れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, '我この地を汝らの前に置り入てこの地を獲よ是はヱホバが汝らの先祖アブラハム、イサク、ヤコブに誓ひて之を彼らとその後の子孫に與へんと言たまひし者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, '彼時我なんぢらに語りて言り我は一人にては汝らをわが任として負ことあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, '汝らの神ヱホバ汝らを衆多ならしめたまひたれば汝ら今日は天空の星のごとくに衆し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, '願くは汝らの先祖の神ヱホバ汝らをして今あるよりは千倍も多くならしめ又なんぢらに約束せしごとく汝らを祝福たまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, '我一人にては爭で汝らを吾任となしまた汝らの重負と汝らの爭競に當ることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, '汝らの支派の中より智慧あり知識ありて人に識れたる人々を簡べ我これを汝らの首長となさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, '時に汝ら答へて言り汝が言ところの事を爲は善しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, '是をもて我汝らの支派の首長なる智慧ありて人に知れたる者等を取て汝らの首長となせり即ち之をもて千人の長百人の長五十人の長十人の長となしまた汝らの支派の中の官吏となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'また彼時に我汝らの士師等に命じて言り汝らその兄弟の中の訴訟を聽き此人と彼人の間を正く審判くべし他國の人においても然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, '汝ら人を視て審判すべからず小き者にも大なる者にも聽べし人の面を懼るべからず審判は神の事なればなり汝らにおいて斷定がたき事は我に持きたれ我これを聽ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, '我かの時に汝らの爲べき事をことごとく汝らに命じたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, '我等の神ヱホバの我等に命じたまひしごとくに我等はホレブより出たち汝らが見知るかの大なる畏しき曠野を通りアモリ人の山を指てガデシバルネアに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, '時に我なんぢらに言り汝らは我らの神ヱホバの我らに與へたまへるアモリ人の山に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, '視よ汝の神ヱホバこの地を汝の前に置たまふ汝の先祖の神ヱホバの汝に言たまふごとく上り往てこれを獲よ懼るるなかれ猶豫なかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, '汝らみな我に近りて言り我等人を我らの先に遣してその地を伺察しめ彼らをして返て何の途より上るべきか何の邑々に入べきかを我らに告しめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'この言わが目に善と見ければ我汝らの中より十二人の者を取り即ち一の支派より一人宛なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, '彼等前みゆきて山に登りエシコルの谷にいたり之を伺ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'その地の菓物を手に取てわれらの許に持くだり我らに復命して言り我等の神ヱホバの我等に與へたまへる地は善地なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, '然るに汝等は上り往ことを好まずして汝らの神ヱホバの命令に背けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'すなはち汝らその天幕にて呟きて言りヱホバわれらを惡むが故に我らをアモリ人の手に付して滅ぼさんとてエジプトの國より我らを導き出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, '我等は何方に往べきや我らの兄弟等は言ふその民は我らよりも大にして身長たかく邑々は大にしてその石垣は天に達る我らまたアナクの子孫を其處に見たりと斯いひて我らの氣を挫けりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, '時に我なんぢらに言り怖る勿れ懼るるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, '汝らに先ち行たまふ汝らの神ヱホバ、エジプトにおいて汝らの爲に汝らの目の前にて諸の事をなしたまひし如く今また汝らのために戰ひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, '曠野においては汝また汝の神ヱホバが人のその子を抱くが如くに汝を抱きたまひしを見たり汝らが此處にいたるまでその路すがら常に然ありしなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'この言をなせども汝らはなほその神ヱホバを信ぜざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'ヱホバは途にありては汝らに先ちゆきて汝らが營を張べき處を尋ね夜は火の中にあり晝は雲の中にありて汝らの行べき途を示したまへる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'ヱホバ汝らの言語の聲を聞て怒り誓て言たまひけらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'この惡き代の人々の中には我が汝らの先祖等に與へんと誓ひしかの善地を見る者一人も有ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, '只ヱフンネの子カルブのみ之を見ることを得ん彼が踐たりし地をもて我かれとかれの子孫に與ふべし其は彼まったくヱホバに從ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'ヱホバまた汝らの故をもて我をも怒て言たまへり汝もまた彼處に入ことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, '汝の前に侍るヌンの子ヨシユアかしこに入べし彼に力をつけよ彼イスラエルをして之を獲しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'また汝等が掠められんと言たりしその汝らの子女および當日になほ善惡を辨へざりし汝らの幼兒等彼ら即ちかしこに入べし我これを彼らに與へて獲さすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, '汝らは身をめぐらし紅海の途より曠野に進みいるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, '然るに汝ら對て我にいへり我等はヱホバにむかひて罪を犯せり然ばわれらの神ヱホバの凡て我らに命じたまへるがごとく我ら上りゆきて戰はんと汝らおのおの武器を身に帶て軽々しく山に登らんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, '時にヱホバわれに言たまひけるは汝かれらに言へ汝ら上りゆくなかれ又戰ふなかれ我なんぢらの中間に居ざればなり汝ら恐らくはその敵に打敗られんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'われかく汝らに告たるに汝ら聽ずしてヱホバの命令に背き自檀に山に登りたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'その山に住るアモリ人汝等にむかひて出きたり蜂の驅がごとくに汝らを驅ちらしなんぢらをセイルに打敗りてホルマにおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, '斯りしかばなんぢら還りきたりてヱホバの前に哭きたりしがヱホバなんぢらの聲を聽たまはず汝らに耳を傾むけたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, '是をもてなんぢらは日久しくカデシに居りなんぢらが其處に居たる日數のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, '斯て我らは身を轉らしヱホバの我に命じたまへる如く紅海の途より曠野に進みいりて日久しくセイル山を行めぐりたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'ヱホバつひに我に告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '汝等はこの山を行めぐること旣に久し今よりは北に轉りて進め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, '汝また民に命じて言へ汝らはセイルに住るヱサウの子孫なる汝らの兄弟の境界を通らんとす彼らはなんぢらを懼れん汝ら深く自ら謹むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, '彼らを攻る勿れ彼らの地は足の跖に踐ほどをも汝らに與へじ其は我セイル山をエサウにあたへて產業となさしめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, '汝ら金をもて彼らより食物を買て食ひまた金をもて彼らより水をもとめて飮め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, '汝の神ヱホバ汝が手に作ところの諸の事において汝をめぐみ汝がこの大なる曠野を通るを看そなはしたまへり汝の神ヱホバこの四十年のあひだ汝とともに在したれば汝は乏しき所あらざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, '我らつひにセイル山に住るエサウの子孫なる我らの兄弟を離れてアラバの路を通りエラテとエジオンゲベルを經て/轉りてモアブの曠野の路に進みいれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, '時にヱホバわれに言たまひけるはモアブ人をなやますなかれまた之を攻て戰ふなかれ彼らの地をば我なんぢらの產業に與へじ其は我ロトの子孫にアルをあたへて產業となさしめたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(昔エミ人ここに住り是民は大にして數多くアナク人のごとくに身長高かり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'アナク人とおなじくレバイムと呼なされたりしがモアブ人はこれをエミ人とよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'ホリ人もまた昔セイルに住をりしがエサウの子孫これを逐滅し之にかはりて其處に住りイスラエルがヱホバに賜はりしその產業の地になせるが如し)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '茲に汝等今たちあがりゼレデ川を渉れとありければ我らすなはちゼレデ川を渉れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'カデシバルネアを出てよりゼレデ川を渉るまでの間の日は三十八年にしてその代の軍人はみな亡果て營中にあらずなりぬヱホバのかれらに誓ひたまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, '誠にヱホバ手をもて之を攻めこれを營中より滅ぼしたまひければ終にみな亡はてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'かく軍人みなその民の中より死亡たる時にあたりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'ヱホバ我に告て言たまひけらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '汝は今日モアブの境なるアルを通らんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, '汝アンモンの子孫に近く時に之をなやます勿れ之を攻るなかれアンモンの子孫の地は我これを汝らの產業に與へじ其は我これをロトの子孫にあたへて產業となさしめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(是もまたレバイムの國とよびなされたり昔レバイムここに住ゐたればなりアンモン人はかれらをザムズミ人とよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'この民は大にして數多くアナク人のごとくに身長たかかりしがヱホバ、アンモン人の前に之を滅ぼしたまひたればアンモン人これを逐はらひて之にかはりて住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'その事はセイルに住るエサウの子孫の前にホリ人を滅ぼしたまひしが如し彼らはホリ人を逐はらひ之にかはりて今日まで其處に住をるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'カフトルより出たるカフトリ人はまたかの村々に住ひてガザにまで到るととろのアビ人を滅ぼし之にかはりて其處に居る)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '汝ら起あがり進みてアルノン河を渉れ我ヘシボンの王アモリ人シホンとこれが國を汝らの手に付す進んで之を獲よ彼を攻て戰へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, '今日我一天下の國人に汝を畏ぢ汝を懼れしめん彼らは汝の名聲を聞て慄ひ汝の爲に心を苦めんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, '茲に我ケデモテの曠野よりヘシボンの王シホンに使者をおくり和好の言を述しめたり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '我に汝の國を通らしめよ我は大路を通りて行ん右にも左にも轉らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, '汝金をとりて食物を我に賣て食はせ金をとりて水を我にあたへて飮せよ我はただ徒歩にて通らんのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'セイルに住るエサウの子孫とアルに住るモアブ人とが我になしたる如くせよ然せば我はヨルダンを濟りて我らの神ヱホバの我らに賜ひし地にいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, '然るにヘシボンの王シホンは我らの通ることを容さざりき是は汝の神ヱホバ彼を汝の手に付さんとてその氣を頑梗しその心を剛愎にしたまひたればなり今日見るが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, '時にヱホバ我に言たまひけるは視よ我いまシホンとこれが地を汝に與へんとす進んでその地を獲て汝の產業とせよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, '茲にシホンその民をことごとく率ゐて出きたりヤハヅに於て戰ひけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, '我らの神ヱホバ彼をわれらに付したまひたれば我らかれとその子等とその一切の民を撃殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'その時に我らは彼の邑々を盡く取りその一切の邑の男女および兒童を滅して一人をも遺さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, '只その家畜および邑々より取たる掠取物は我らこれを獲て自分の物となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'アルノンの河邊のアロエルおよび河の傍なる邑よりギレアデにいたるまで我らの攻取がたき邑とては一もあらざりき我らの神ヱホバこれを盡くわれらに付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, '第アンモンの子孫の地ヤボク川の全岸山地の邑々など凡てわれらの神ヱホバが我らの往を禁じたまへる處には汝いたらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, '斯てわれら身をめぐらしてバシヤンの路に上り行けるにバシヤンの王オグその民をことごとく率ゐ出てエデレイに戰はんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, '時にヱホバわれに言たまひけらく彼を懼るるなかれ我かれとその一切の民とその地とを汝の手に付さん汝かのヘシボンに住たるアモリ人の王シホンになせし如く彼に爲べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, '我らの神ヱホバすなはちバシヤンの王オグとその一切の民を我らの手に付したまひしかば我ら之を撃ころして一人をも遺さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'その時に我らこれが邑々をことごとく取り取ざる邑は一も有ざりきその取る邑は六十是すなはちアルゴブの地にしてバシヤンにおけるオグの國なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'この邑々はみな高き石垣あり門あり關ありて堅固なりき外にまた石垣あらざる邑甚だ多くありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, '我らはヘシボンの王シホンになせし如く之を滅しその一切の邑の男女および兒童をことごとく滅せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, '惟その一切の家畜とその邑々よりの掠取物とはこれを獲てわれらの物となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'その時我らヨルダンの此旁の地をアルノン河よりヘルモン山までアモリ人の王二人の手より取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(ヘルモンはシドン人これをシリオンと呼びアモリ人これをセニルと呼ぶ)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'すなはち平野の一切の邑ギレアデの全地バシヤンの全地サルカおよびエデレイなどバシヤンに於るオグの國をことごとく取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '彼レバイムの遺れる者はバシヤンの王オグ只一人なりき彼の寝臺は鐵の寝臺なりき是は今なほアンモンの子孫のラバにあるに非ずや人の肘によれば是はその長九キユビトその寛四キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'その時に我らこの地を獲たりしがアルノン河の邊なるアロエルよりの地とギレアデの山地の半とその中の邑々とは我これをルベン人とガド人に與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'またオグの國なりしギレアデの殘餘の地とバシヤンの全地とは我これをマナセの半支派に與へたりアルゴブの全地すなはちバシヤンの全體はレバイムの國と稱へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'マナセの子ヤイルはアルゴブの全地を取てゲシユルの境界とマアカの境界にまで至り自分の名にしたがひてバシヤンをハヲテヤイルと名けたりその名今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'またマキルには我ギレアデを與へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'ルベン人とガド人にはギレアデよりアルノン河までを與へその河の眞中をもて界となしまたアンモンの子孫の地の界なるヤボク河にまで至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'またアラバおよびヨルダンとその邊の地をキンネレテよりアラバの海すなはち鹽海まで之にあたへて東の方ピスガの麓にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'その時我なんぢらに命じて言り汝らの神ヱホバこの地を汝らに與へて產業となさしめたまへば汝ら軍人に身をよろひて汝らの兄弟なるイスラエルの子孫に先だちて渉りゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, '但し汝らの妻と子女と家畜は我が汝らに與へし邑に止るべし我なんぢらが衆多の家畜を有を知なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'ヱホバなんぢらに賜ひしごとく汝らの兄弟にも安息を賜ひて彼らもまたヨルダンの彼旁にて汝らの神ヱホバにたまはるところの地を獲て產業となすに至らば汝らおのおの我なんぢらに與へし產業に歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'かの時に我ヨシユアに命じて言り汝はこの二人の王に汝らの神ヱホバのおこなひたまふ所の事を目に視たりヱホバまた汝が往ところの諸の國にも斯のごとく行ひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, '汝これを懼るる勿れ汝らの神ヱホバ汝らのために戰ひたまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, '當時われヱホバに求めて言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '主ヱホバよ汝は汝の大なる事と汝の強き手を僕に見すことを始めたまへり天にても地にても何の神か能なんぢの如き事業を爲し汝のごとき能力を有んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, '願くは我をして渉りゆかしめヨルダンの彼旁なる美地美山およびレバノンを見ことを得させたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, '然るにヱホバなんぢらの故をもて我を怒り我に聽ことを爲たまはずヱホバすなはち我に言たまひけるは旣に足りこの事を重て我に言なかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, '汝ビスガの嶺にのぼり目を擧て西北南東を望み汝の目をもて其地を觀よ汝はヨルダンを濟ることを得ざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, '汝ヨシユアに命じ之に力をつけ之を堅うせよ其はこの民を率ゐて渉りゆき之に汝が見るところの地を獲さする者は彼なればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'かくて我らはベテベオルに對する谷に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '今イスラエルよ我が汝らに敎ふる法度と律法を聽てこれを行へ然せば汝らは生ることを得汝らの先祖の神ヱホバの汝らに賜ふ地にいりて之を產業となすを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, '我が汝らに命ずる言は汝らこれを増しまたは減すべからず我が汝らに命ずる汝らの神ヱホバの命令を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, '汝らはヱホバがバアルペオルの事によりて行ひたまひし所を目に觀たり即ちバアルペオルに從ひたる人々は汝の神ヱホバことごとく之を汝らの中間より滅し去たまひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, '汝らの神ヱホバに附て離れざりし汝等はみな今日までも生ながらへ居るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, '我はわが神ヱホバの我に命じたまひし如くに法度と律法を汝らに敎へ汝らをしてその往て獲ところの地において之を行はしめんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, '然ば汝ら之を守り行ふべし然する事は國々の民の目の前において汝らの智慧たり汝らの知識たるなり彼らこの諸の法度を聞て言んこの大なる國人は必ず智慧あり知識ある民なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'われらの神ヱホバは我らがこれに龥もとむるに常に我らに近く在すなり何の國人か斯のごとく大にして神これに近く在すぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'また何の國人か斯のごとく大にして今日我が汝らの前に立るこの一切の律法の如き正しき法度と律法とを有るぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, '汝深く自ら愼み汝の心を善く守れ恐くは汝その目に觀たる事を忘れん恐くは汝らの生存らふる日の中に其等の事汝の心を離れん汝それらの事を汝の子汝の孫に敎へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, '汝がホレブにおいて汝の神ヱホバの前に立る日にヱホバわれに言たまひけらく我ために民を集めよ我これに吾言を聽しめ之をしてその世に存らふる日の間我を畏るることを學ばせまたその子女を敎ふることを爲しめんとすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, '是において汝らは前みよりて山の麓に立ちけるが山は火にて燒てその燄は中天に沖り暗くして雲あり黑雲深かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, '時にヱホバ火の中より汝らに言ひたまひしが汝らは言詞の聲を聞る而已にて聲の外は何の像をも見ざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'ヱホバすなはち其契約を汝らに述て汝らに之を守れと命じたまへり是すなはち十誡にしてヱホバこれを二枚の石の板に書したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'かの時にヱホバ我に命じて汝らに法度と律法を敎へしめたまへり是汝らにその往て獲ところの地にて之を爲しめんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'ホレブにおいてヱホバ火の中より汝らに言ひたまひし日には汝ら何の像をも見ざりしなり然ば汝ら深く自ら愼み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, '道をあやまりて自己のために偶像を刻む勿れ物の像は男の形にもあれ女の形にもあれ凡て造るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, '即ち地の上にをる諸の獣の像空に飛ぶ諸の鳥の像');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, '地に匍ふもろもろの物の像地の下の水の中に居る諸の魚の像など凡て造る勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, '汝目をあげて天を望み日月星辰など凡て天の衆群を觀誘はれてこれを拝み之に事ふる勿れ是は汝の神ヱホバが一天下の萬國の人々に分ちたまひし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'ヱホバ汝らを取り汝らを鐵の爐の中すなはちエジプトより導きいだして自己の產業の民となしたまへること今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, '然るにヱホバなんぢらの故によりて我を怒り我はヨルダンを濟りゆくことを得ずまた汝の神ヱホバが汝の產業に賜ひしその美地に入ことを得ずと誓ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, '我はこの地に死ざるを得ず我はヨルダンを濟りゆくことあたはずなんぢらは濟りゆきて之を獲て產業となすことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, '汝ら自ら愼み汝らの神ヱホバが汝らに立たまひし契約を忘れて汝の神ヱホバの禁じたまふ偶像など凡て物の像を刻むことを爲なかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, '汝の神ヱホバは燬盡す火嫉妬神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, '汝ら子を擧け孫を得てその地に長く居におよびて若し道をあやまりて偶像など凡て物の像を刻み汝の神ヱホバの惡と觀たまふ事をなしてその震怒を惹おこすことあらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, '我今日天と地を呼て證となす汝らはかならずそのヨルダンを濟りゆきて獲たる地より速かに滅亡うせん汝らはその上に汝らの日を永うする能はず必ず滅びうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'ヱホバなんぢらを國々に散したまべしヱホバの汝らを逐やりたまふ國々の中に汝らの遺る者はその數寡なからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, '其處にて汝らは人の手の作なる見ことも聞ことも食ふことも嗅こともなき木や石の神々に事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, '但しまた其處にて汝その神ヱホバを求むるあらんに若し心をつくし精神を盡してこれを求めなば之に遇ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, '後の日にいたりて汝艱難にあひて此もろもろの事の汝に臨まん時に汝もしその神ヱホバにたち歸りてその言にしたがはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, '汝の神ヱホバは慈悲ある神なれば汝を棄ず汝を滅さずまた汝の先祖に誓ひたりし契約を忘れたまはざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, '試に問へ汝の前に過さりし日神が地の上に人を造りたまひし日より已來天の此極より彼極までに曾て斯のごとき大なる事ありしや是のごとき事の聞えたる事ありしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, '曾て人神が火の中より言ふ聲を汝らが聞るごとくに聞て尚生る者ありしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, '汝らの神ヱホバがエジプトにおいて汝らの目の前にて汝らの爲に諸の事を爲たまひし如く曾て試探と徴證と奇蹟と戰爭と強き手と伸たる腕と大なる恐嚇をもて來りこの民をかの民の中より領いださんとせし神ありしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, '汝にこの事を示ししはヱホバはすなはち神にしてその外には有ことなしと汝に知しめんがためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, '汝を敎へんためにヱホバ天より汝に聲を聞しめ地に於てはまたその大なる火を汝に示したまへり即ち汝はその言の火の中より出るを聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'ヱホバ汝の先祖等を愛したまひしが故にその後の子孫を選び大なる能力をもて親ら汝をエジプトより導き出したまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, '汝よりも大にして強き國々の民を汝の前より逐はらひ汝をその地に導きいりて之を汝の產業に與へんとしたまふこと今日のごとくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, '然ば汝今日知て心に思念べし上は天下は地においてヱホバは神にいましその外には神有こと無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, '今日わが汝に命ずるヱホバの法度と命令を守るべし然せば汝と汝の後の子孫祥を得汝の神ヱホバの汝にたまふ地において汝その日を永うすることを得て疆なからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, '斯てモーセ、ヨルダンの此旁日の出る方にないて邑三を別てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, '是素より怨なきに誤りて人を殺せる者をして其處に逃れしむる爲なり其邑の一に逃るる時はその人生命を全うするを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, '即ち一は曠野の内の平野にあるベゼル是はルベン人のためなり一はギレアデのラモテ是はガド人のためなり一はバシヤンのゴラン是はマナセ人のためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'モーセがイスラエルの子孫の前に示しし律法は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'イスラエルの子孫のエジプトより出たる後モーセこの誡命と法度と律法を之に述たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, '即ちヨルダンの此旁なるアモリ人の王シホンの地にありベテペオルに對する谷に於て之を述たりシホンはヘシボンに住をりしがモーセとイスラエルの子孫エジプトより出きたりし後これを撃ほろぼして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, '之が地を獲またバシヤンの王オグの地を獲たり彼ら二人はアモリ人の王にしてヨルダンの此旁日の出る方に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'その獲たる地はアルノン河の邊なるアロエルよりヘルモンといふシオン山にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'ヨルダンの此旁すなはちその東の方なるアラバの全部を括てアラバの鹽海に達しピスガの麓におよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, '茲にモーセ、イスラエルをことごとく召て之に言ふイスラエルよ今日我がなんぢらの耳に語るところの法度と律法とを聽きこれを學びこれを守りて行へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, '我らの神ヱホバ、ホレブに於て我らと契約を結びたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'この契約はヱホバわれらの先祖等とは結ばずして我ら今日此に生存へをる者と結びたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'ヱホバ山において火の中より汝らと面をあはせて言ひたまひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'その時我はヱホバと汝らの間にたちてヱホバの言を汝らに傳へたり汝ら火に懼れて山にのぼり得ざりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'ヱホバすなはち言たまひけらく我は汝の神ヱホバ汝をエジプトの地その奴隸たる家より導き出せし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, '汝わが面の前に我の外何物をも神とすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, '汝自己のために何の偶像をも彫むべからず又上は天にある者下は地にある者ならびに地の下の水の中にある者の何の形状をも作るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, '之を拝むべからず之に事ふべからず我ヱホバ汝の神は嫉む神なれば我を惡む者にむかひては父の罪を子に報いて三四代におよぼし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, '我を愛しわが誡命を守る者には恩惠を施して千代にいたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, '汝の神ヱホバの名を妄に口にあぐべからずヱホバは己の名を妄に口にあぐる者を罰せではおかざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, '安息日を守りて之を聖潔すること汝の神ヱホバの汝に命ぜしごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, '六日のあひだ勞きて汝の一切の業を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, '七日は汝の神ヱホバの安息なれば何の業務をも爲べからず汝も汝の男子女子も汝の僕婢も汝の牛驢馬も汝の諸の家畜も汝の門の中にをる他國の人も然り斯なんぢ僕婢をして汝とおなじく息ましむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, '汝誌ゆべし汝かつてエジプトの地に奴隸たりしに汝の神ヱホバ強き手と伸べたる腕とをもて其處より汝を導き出したまへり是をもて汝の神ヱホバなんぢに安息日を守れと命じたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, '汝の神ヱホバの汝に命じたまふごとく汝の父母を敬へ是汝の神ヱホバの汝に賜ふ地において汝の日の長からんため汝に祥のあらんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, '汝殺す勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, '汝姦淫する勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, '汝盗むなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, '汝その隣に對して虚妄の證據をたつる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, '汝その隣人の妻を貧るなかれまた隣人の家 田野 僕 婢牛 驢馬ならびに凡て汝の隣人の所有を貧るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, '是等の言をヱホバ山において火の中雲の中黑雲の中より大なる聲をもて汝らの全會衆に告たまひしが此外には言ことを爲ず之を二枚の石の版に書して我に授けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, '時にその山は火にて燒をりしが汝ら黑暗の中よりその聲の出るを聞におよびて汝らの支派の長および長老等我に進みよりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, '言けるは視よ我らの神ヱホバその榮光とその大なる事を我らに示したまひて我らその聲の火の中より出るを聞り我ら今日ヱホバ人と言ひたまふてその人の尚生るを見る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, '我らなんぞ死にいたるべけんや此大なる火われらを燒ほろぼさんとするなり我らもし此上になほ我らの神ヱホバの聲を聞ば死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, '凡そ肉身の者の中誰か能く活神の火の中より言ひたまふ聲を我らのごとくに聞てなほ生る者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, '請ふ汝進みゆきて我らの神ヱホバの言たまふとこるを都て聽き我らの神ヱホバの汝に告給ふところを都て我らに告よ我ら聽て行はんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'ヱホバなんぢらが我に語れる言の聲を聞てヱホバ我に言たまひけるは我この民が汝に語れる言の聲を聞り彼らの言ところは皆善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, '只願しきは彼等が斯のごとき心を懐いて恒に我を畏れ吾が誡命を守りてその身もその子孫も永く福祉を得にいたらん事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, '汝ゆきて彼らに言へ汝らおのおのその天幕にかへるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, '然ど汝は此にて我傍に立て我なんぢに諸の誡命と法度と律法とを告しめさん汝これを彼らに敎へ我が彼らに與へて產業となさしむる地において彼らにこれを行はしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, '然ば汝らの神ヱホバの汝等に命じたまふごとくに汝ら謹みて行ふべし右にも左にも曲るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, '汝らの神ヱホバの汝らに命じたまふ一切の道に歩め然せば汝らは生ることを得かつ福祉を得て汝らの產業とする地に汝らの日を長うすることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '是すなはち汝らの神ヱホバが汝らに敎へよと命じたまふところの誡命と法度と律法とにして汝らがその濟りゆきて獲ところの地にて行ふべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, '是は汝と汝の子および汝の孫をしてその生命ながらふる日の間つねに汝の神ヱホバを畏れしめて我が汝らに命ずるその諸の法度と誡命とを守らしめんため又なんぢの日を永からしめんための者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, '然ばイスラエルよ聽て謹んでこれを行へ然せば汝は福祉を獲汝の先祖の神ヱホバの汝に言たまひしごとく乳と蜜の流るる國にて汝の數おほいに増ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'イスラエルよ聽け我らの神ヱホバは惟一のヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, '汝心を盡し精神を盡し力を盡して汝の神ヱホバを愛すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, '今日わが汝に命ずる是らの言は汝これをその心にあらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, '勤て汝の子等に敎へ家に坐する時も路を歩む時も寝る時も興る時もこれを語るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, '汝またこれを汝の手に結びて號となし汝の目の間におきて誌となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'また汝の家の柱と汝の門に書記すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, '汝の神ヱホバその汝の先祖アブラハム、イサク、ヤコブにむかひて汝に與んと誓ひたりし地に汝を入しめん時は汝をして汝が建たる者にあらざる大なる美しき邑々を得させ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, '汝が盈せるに非る諸の佳物を盈せる家を得させ汝が堀たる者にあらざる堀井を得させたまふべし汝は食ひて飽ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, '然る時は汝愼め汝をエジプトの地奴隸たる家より導き出ししヱホバを忘るる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, '汝の神ヱホバを畏れてこれに事へその名を指て誓ふことをすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, '汝ら他の神々すなはち汝の四周なる民の神々に從ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '汝らの中にいます汝の神ヱホバは嫉妬神なれば恐くは汝の神ヱホバ汝にむかひて怒を發し汝を地の面より滅し去たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, '汝マツサにおいて試みしごとく汝の神ヱホバを試むるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, '汝らの神ヱホバの汝らに命じたまへる誡命と律法と法度とを汝ら謹みて守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, '汝ヱホバの義と視善と視たまふ事を行ふべし然せば汝福祉を獲かつヱホバの汝の先祖に誓ひたまひしかの美地に入てこれを產業となすことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'ヱホバまたその言たまひし如く汝の敵をことごとく汝の前より逐はらひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, '後の日に至りて汝の子なんぢに問てこの汝らの神ヱホバが汝らに命じたまひし誡命と法度と律法とは何のためなるやと言ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, '汝その子に告て言べし我らは昔エジプトにありてパロの奴隸たりしがヱホバ強き手をもて我らをエジプトより導き出したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, '即ちヱホバわれらの目の前において大なる畏るべき徴と奇蹟をエジプトとパロとその全家とに示したまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, '我らを其處より導き出して其曾て我等の先祖に誓ひし地に我らを入せて之を我らに與へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, '而してヱホバ我らにこの諸の法度を守れと命じたまふ是われらをして我らの神ヱホバを畏れて常に幸ならしめんため又ヱホバ今日のごとく我らを守りて生命を保たしめんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, '我らもしその命ぜられたるごとく此一切の誡命を我らの神ヱホバの前に謹んで守らば是われらの義となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, '汝の神ヱホバ汝が往て獲べきところの地に汝を導きいり多の國々の民ヘテ人ギルガシ人アモリ人カナン人ペリジ人ヒビ人ヱブス人など汝よりも數多くして力ある七の民を汝の前より逐はらひたまはん時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'すなはち汝の神ヱホバかれらを汝に付して汝にこれを撃せたまはん時は汝かれらをことごとく滅すべし彼らと何の契約をもなすべからず彼らを憫むべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'また彼らと婚姻をなすべからず汝の女子を彼の男子に與ふべからず彼の女子を汝の男子に娶るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, '其は彼ら汝の男子を惑はして我を離れしめ之をして他の神々に事へしむるありてヱホバこれがために汝らにむかひて怒を發し俄然に汝を滅したまふにいたるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, '汝らは反て斯かれらに行ふべし即ちかれらの壇を毀ちその偶像を打擢きそのアシラ像を斫たふし火をもてその雕像を焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, '其は汝は汝の神ヱホバの聖民なればなり汝の神ヱホバは地の面の諸の民の中より汝を擇びて己の寶の民となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'ヱホバの汝らを愛し汝らを擇びたまひしは汝らが萬の民よりも數多かりしに因にあらず汝らは萬の民の中にて最も小き者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, '但ヱホバ汝らを愛するに因りまた汝らの先祖等に誓し誓を保たんとするに因てヱホバ強き手をもて汝らを導きいだし汝らを其奴隸たりし家よりエジプトの王パロの手より贖ひいだしたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, '汝知べし汝の神ヱホバは神にましまし眞實の神にましまして之を愛しその誡命を守る者には契約を保ち恩惠をほどこして千代にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'また之を惡む者には覿面にその報をなしてこれを滅ぼしたまふヱホバは己を惡む者には緩ならず覿面にこれに報いたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, '然ば汝わが今日汝に命ずるところの誡命と法度と律法とを守りてこれを行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, '汝らもし是らの律法を聽きこれを守り行はば汝の神ヱホバ汝の先祖等に誓ひし契約を保ちて汝に恩惠をほどこしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, '即ち汝を愛し汝を惠み汝の數を増したまひその昔なんぢに與へんと汝らの先祖等に誓たりし地において汝の兒女をめぐみ汝の地の產物穀物酒油等を殖し汝の牛の產汝の羊の產を増たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, '汝は惠まるること萬の民に愈らん汝らの中および汝らの家畜の中には男も女も子なき者は無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'ヱホバまた諸の疾病を汝の身より除きたまひ汝らが知る彼のエジプトの惡き病を汝の身に臨ましめず但汝を惡む者に之を臨ませたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, '汝は汝の神ヱホバの汝に付したまはんところの民をことごとく滅しつくすべし彼らを憫み見べからずまた彼らの神に事ふべからずその事汝の罟となればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, '汝是らの民は我よりも衆ければ我いかでか之を逐はらふことを得んと心に謂ふか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, '汝かれらを懼るるなかれ汝の神ヱホバがパロとエジプトに爲たまひしところの事を善く憶えよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, '即ち汝が眼に見たる大なる試煉と徴證と奇蹟と強き手と伸たる腕とを憶えよ汝の神ヱホバこれをもて汝を導き出したまへり是のごとく汝の神ヱホバまた汝が懼るる一切の民に爲たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, '即ち汝の神ヱホバ黄蜂を彼らの中に遣りて終に彼らの遺れる者と汝の面を避て匿れたる者とを滅したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, '汝かれらを懼るる勿れ其は汝の神ヱホバ能力ある畏るべき神汝らの中にいませばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, '汝の神ヱホバ是等の國人を漸々に汝の前より逐はらひたまはん汝は急速に彼らを滅しつくす可らず恐くは野の獣殖て汝に逼らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, '汝の神ヱホバかれらを汝に付し大にこれを惶れ慄かしめて終にこれを滅し盡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, '彼らの王等を汝の手に付したまはん汝かれらの名を天が下より削るべし汝には當ることを得る者なくして汝つひに之を滅ぼし盡すに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, '汝かれらの神の雕像を火にて焚べし之に著せたる銀あるひは金を貧るべからず之を己に取べからず恐くは汝これに因て罟にかからん是は汝の神ヱホバの憎みたまふ者なれば也');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, '憎むべき物を汝の家に携へいるべからず恐くは汝も其ごとくに詛はるる者とならん汝これを大に忌み痛く嫌ふべし是は詛ふべき者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, '我が今日なんぢに命ずるところの諸の誡命を汝ら謹んで行ふべし然せば汝ら生ることを得かつ殖増しヱホバの汝の先祖等に誓たまひし地に入てこれを產業となすことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, '汝記念べし汝の神ヱホバこの四十年の間汝をして曠野の路に歩ましめたまへり是汝を苦しめて汝を試驗み汝の心の如何なるか汝がその誡命を守るや否やを知んためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, '即ち汝を苦しめ汝を饑しめまた汝も知ず汝の先祖等も知ざるところのマナを汝らに食はせたまへり是人はパン而已にて生る者にあらず人はヱホバの口より出る言によりて生る者なりと汝に知しめんが爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'この四十年のあひだ汝の衣服は古びて朽ず汝の足は腫ざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, '汝また心に念ふべし人のその子を懲戒ごとく汝の神ヱホバも汝を懲戒たまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, '汝の神ヱホバの誡命を守りその道にあゆみてこれを畏るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, '汝の神ヱホバ汝をして美地に到らしめたまふ是は谷にも山にも水の流あり泉あり瀦水ある地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, '小麥 大麥 葡萄 無花果および石榴ある地油 橄欖および蜜のある地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, '汝の食ふ食物に缺るところなく汝に何も乏しきところあらざる地なりその地の石はすなはち鐵その山よりは銅を掘とるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, '汝は食ひて飽き汝の神ヱホバにその美地を己にたまひし事を謝すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, '汝わが今日なんぢに命ずるヱホバの誡命と律法と法度とを守らずして汝の神ヱホバを忘るるにいたらざるやう愼めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, '汝食ひて飽き美しき家を建て住ふに至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'また汝の牛羊殖増し汝の金銀殖増し汝の所有みな殖増にいたらん時に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, '恐くは汝心に驕りて汝の神ヱホバを忘れんヱホバは汝をエジプトの地奴隸たる家より導き出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, '汝をみちびきて彼の大にして畏るべき曠野すなはち蛇火の蛇蠍などありて水あらざる乾ける地を通り汝らのために堅き磐の中より水を出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, '汝の先祖等の知ざるマナを曠野にて汝に食せたまへり是みな汝を苦しめ汝を試みて終に福祉を汝にたまはんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, '汝我力とわが手の動作によりて我この資財を得たりと心に謂なかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, '汝の神ヱホバを憶えよ其はヱホバ汝に資財を得の力をたまふなればなり斯したまふは汝の先祖等に誓し契約を今日の如く行はんとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, '汝もし汝の神ヱホバを忘れ果て他の神々に從がひ之に事へこれを拝むことを爲ば我今日汝らに證をなす汝らはかならず滅亡ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'ヱホバの汝らの前に滅ぼしたまひし國々の民のごとく汝らも滅亡べし是なんぢらの神ヱホバの聲に汝らしたがはざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'イスラエルよ聽け汝は今日ヨルダンを濟りゆき汝よりも大にして強き國々に入てこれを取んとすその邑々は大にして石垣は天に達り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'その民は汝が知ところのアナクの子孫にして大くかつ身長たかし汝また人の言るを聞り云く誰かアナクの子孫の前に立ことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, '汝今日知る汝の神ヱホバは燬つくす火にましまして汝の前に進みたまふとヱホバかならず彼らを滅ぼし彼らを汝の前に攻伏たまはんヱホバの汝に言たまひし如く汝かれらを逐はらひ速かに彼らを滅ぼすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, '汝の神ヱホバ汝の前より彼らを逐はらひたまはん後に汝心に言なかれ云く我の義がためにヱホバ我をこの地に導きいりてこれを獲させたまへりとそはこの國々の民の惡きがためにヱホバ之を汝の前より逐はらひたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, '汝の往てその地を獲は汝の義きによるにあらず又なんぢの心の直によるに非ずこの國々の民惡きが故に汝の神ヱホバこれを汝の前より逐はらひたまふなりヱホバの斯したまふはまた汝の先祖アブラハム、イサク、ヤコブに誓たりし言を行はんとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, '汝知る汝の神ヱホバの汝に此美地を與へて獲させたまふは汝の義きによるに非ず汝は項の強き民なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, '汝曠野に於て汝の神ヱホバを怒せし事を憶えて忘るる勿れ汝らはエジプトの地を出し日より此處にいたる日まで常にヱホバに悖れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'ホレブにおいて汝らヱホバを怒せたればヱホバ汝らを怒りて汝らを滅ぼさんとしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'かの時われ石の板すなはちヱホバの汝らに立たまへる契約を載る石の板を受んとて山に上り四十日四十夜山に居りパンも食ず水も飮ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'ヱホバ我に神の指をもて書しるしたる文字ある石の板二枚を授けたまへりその上には集會の日にヱホバが山において火の中より汝らに告たまひし言をことごとく載す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'すなはち四十日四十夜過し時ヱホバ我にその契約を載る板なる石の板二枚を授け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, '而してヱホバ我に言たまひけるは汝起あがりて速かに此より下れ汝がエジプトより導き出しし民は惡き事を行ふなり彼らは早くもわが彼らに命ぜし道を離れて自己のために偶像を鋳造れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'ヱホバまた我に言たまひけるは我この民を觀たり視よ是は項の強き民なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, '我を阻むるなかれ我かれらを滅ぼしその名を天が下より抹さり汝をして彼らよりも強くまた大なる民とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, '是に於て我身をめぐらして山を下りけるが山は火にて燒をる又その契約の板二枚はわが兩の手にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, '斯て我觀しに汝らはその神ヱホバにむかひて罪を犯し自己のために犢を鋳造りて早くもヱホバの汝らに命じたまひし道を離れたりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, '我その二枚の板をとりてわが兩の手よりこれを擲ち汝らの目の前にこれを碎けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, '而して我は前のごとく四十日四十夜ヱホバの前に伏て居りパンも食ず水も飮ざりき是は汝らヱホバの目の前に惡き事をおこなひ之を怒せて大に罪を獲たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'ヱホバ忿怒を發し憤恨をおこし汝らを怒りて滅ぼさんとしたまひしかば我懼れたりしが此度もまたヱホバ我に聽たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'ヱホバまた痛くアロンを怒りてこれを滅ぼさんとしたまひしかば我その時またアロンのために祈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, '斯て我なんぢらが作りて罪を犯しし犢を取り火をもて之を燒きこれを搗きこれを善く打碎きて細き塵となしその塵を山より流れ下るところの渓流に投棄たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, '汝らはタベラ、マツサおよびキブロテハツタワにおいてもまたヱホバを怒らせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'またヱホバ、カデシバルネアより汝らを遣さんとせし時言たまひけるは汝ら上りゆきて我がなんぢらに與ふる地を獲て產業とせよと然るに汝らはその神ヱホバの命に悖り之を信ぜずまたその言を聽ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, '我が汝らを識し日より以來汝らは常にヱホバに悖りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'かの時ヱホバ汝らを滅さんと言たまひしに因て我最初に伏たる如く四十日四十夜ヱホバの前に伏し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'ヱホバに祈りて言けるは主ヱホバよ汝その大なる權能をもて贖ひ強き手をもてエジプトより導き出しし汝の民汝の產業を滅したまふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, '汝の僕アブラハム、イサク、ヤコブを念たまへ此民の剛愎と惡と罪とを鑑みたまふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, '恐くは汝が我らを導き出したまひし國の人言んヱホバその約せし地にかれらを導きいること能はざるに因りまた彼らを惡むに因て彼らを導き出して曠野に殺せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, '抑かれらは汝の民汝の產業にして汝が強き能力をもて腕を伸て導き出したまひし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'かの時ヱホバ我に言たまひけるは汝石の板二枚を前のごとくに斫て作りまた木の櫃一箇を作りて山に登り來れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, '汝が碎きしかの前の板に載たる言を我その板に書さん汝これをその櫃に蔵むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, '我すなはち合歓木をもて櫃一箇を作りまた石の板二枚を前のごとくに斫て作りその板二枚を手に執て山に登りしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'ヱホバかの集會の日に山において火の中より汝らに告たるその十誡を前に書したるごとくその板に書し而してヱホバこれを我に授けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, '是に於て我身を轉らして山より下りその板を我が造りしかの櫃に蔵めたり今なほその中にありヱホバの我に命じたまへる如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, '斯てイスラエルの子孫はヤカン人の井より出たちてモセラにいたれりアロン其處に死て其處に葬られその子エレアザルこれに代りて祭司となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, '又其處より出たちてグデゴダにいたりグデゴダより出たちてヨテバにいたれりこの地には水の流多かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'かの時ヱホバ、レビの支派を區分てヱホバの契約の櫃を舁しめヱホバの前に立てこれに事へしめ又ヱホバの名をもて祝することを爲せたまへり其事今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, '是をもてレビはその兄弟等の中に分なくまた產業なし惟ヱホバその產業たり汝の神ヱホバの彼に言たまへる如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, '我は前の日數のごとく四十日四十夜山に居しがヱホバその時にもまた我に聽たまへりヱホバ汝を滅すことを好みたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, '斯てヱホバ我に言たまひけるは汝起あがり民に先だちて進み行き彼らをして我が之に與へんとその先祖に誓ひたる地に入てこれを獲せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'イスラエルよ今汝の神ヱホバの汝に要めたまふ事は何ぞや惟是のみ即ち汝がその神ヱホバを畏れその一切の道に歩み之を愛し心を盡し精神を盡して汝の神ヱホバに事へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, '又我が今日汝らに命ずるヱホバの誡命と法度とを守りて身に福祉を得るの事のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, '夫天と諸天の天および地とその中にある者は皆汝の神ヱホバに屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, '然るにヱホバただ汝の先祖等を悦こびて之を愛しその後の子孫たる汝らを萬の民の中より選びたまへり今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, '然ば汝ら心に割禮を行へ重て項を強くする勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, '汝の神ヱホバは神の神主の主大にしてかつ權能ある畏るべき神にましまし人を偏り視ずまた賄賂を受ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, '孤兒と寡婦のために審判を行ひまた旅客を愛してこれに食物と衣服を與へたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, '汝ら旅客を愛すべし其は汝らもエジプトの國に旅客たりし事あればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, '汝の神ヱホバを畏れ之に事へこれに附從がひその名を指て誓ふことをすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, '彼は汝の讃べき者また汝の神にして汝が目に見たる此等の大なる畏るべき事業をなしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, '汝の先祖等は僅か七十人にてエジプトに下りたりしに今汝の神ヱホバ汝をして天空の星のごとくに多くならしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, '然ば汝の神ヱホバを愛し常にその職守と法度と律法と誡命とを守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, '汝らの子女は知ずまた見ざれば我これに言ず惟汝らに言ふ汝らは今日すでに汝らの神ヱホバの懲戒とその大なる事とその強き手とその伸たる腕とを知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'またそのエジプトの中においてエジプト王パロとその全國にむかひておこなひたまひし徴證と行爲とを知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'またヱホバがエジプトの軍勢とその馬とその車とに爲たまひし事すなはち彼らが汝らの後を追きたれる時に紅海の水を彼らの上に覆ひかからしめ之を滅ぼして今日までその跡方なからしめし事を知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'また此處にいたるまで曠野に於て汝らに爲たまひし事等を知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'またそのルベンの子孫なるエリアブの子等ダタンとアビラムに爲たまひし事すなはちイスラエルの全家の眞中において地その口を啓きて彼らとその家族とその天幕とその足下に立つ者とを呑つくしし事を知なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, '即ち汝らはヱホバの行ひたまひし此諸の大なる作爲を目に覩たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, '然ば汝ら我今日汝らに命ずる誡命を盡く守るべし然せば汝らは強くなり汝らが濟りゆきて獲んとする地にいりて之を獲ことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'またヱホバが汝らと汝らの後の子孫にあたへんと汝らの先祖等に誓たまひし地乳と蜜との流るる國において汝らの日を長うすることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, '汝らが進みいりて獲んとする地は汝らが出來りしエジプトの地のごとくならず彼處にては汝ら種を播き足をもて之に灌漑げりその状蔬菜園におけるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, '然ど汝らが濟りゆきて獲ところの地は山と谷の多き地にして天よりの雨水を吸ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'その地は汝の神ヱホバの顧みたまふ者にして年の始より年の終まで汝の神ヱホバの目常にその上に在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, '汝らもし我今日なんぢらに命ずる吾命令を善守りて汝らの神ヱホバを愛し心を盡し精神を盡して之に事へなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, '我なんぢらの地の雨を秋の雨春の雨ともに時に隨ひて降し汝らをしてその穀物を收入しめ且酒と油を獲せしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'また汝の家畜のために野に草を生ぜしむべし汝は食ひて飽ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, '汝ら自ら愼むべし心迷ひ翻へりて他の神々に事へこれを拝む勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, '恐くはヱホバ汝らにむかひて怒を發して天を閉たまひ雨ふらず地物を生ぜずなりて汝らそのヱホバに賜れる美地より速かに滅亡るに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, '汝ら是等の我言を汝らの心と魂との中に蔵めまた之を汝らの手に結びて徴となし汝らの目の間におきて誌となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, '之をなんぢらの子等に敎へ家に坐する時も路を歩む時も寝る時も興る時もこれを語り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'また汝の家の柱となんぢの門に之を書記べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, '然せばヱホバが汝らの先祖等に與へんと誓ひたまひし地に汝らのをる日および汝らの子等のをる日は數多くして天の地を覆ふ日の久きが如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, '汝らもし我が汝らに命ずる此一切の誡命を善く守りてこれを行ひ汝等の神ヱホバを愛しその一切の道に歩み之に附從がはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'ヱホバこの國々の民をことごとく汝らの前より逐はらひたまはん而して汝らは己よりも大にして能力ある國々を獲にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, '凡そ汝らが足の蹠にて踏む處は皆汝らの有とならん即ち汝らの境界は曠野よりレバノンに亘りまたユフラテ河といふ河より西の海に亘るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, '汝らの前に立ことを得る人あらじ汝らの神ヱホバ汝らが踏いるところの地の人々をして汝らを怖ぢ汝らを畏れしめたまふこと其嘗て汝らに言たまひし如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, '視よ我今日汝らの前に祝福と呪詛とを置く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, '汝らもし我が今日なんぢらに命ずる汝らの神ヱホバの誡命に遵はば祝福を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, '汝らもし汝らの神ヱホバの誡命に遵はず翻へりて我が今日なんぢらに命ずる道を離れ素知ざりし他の神々に從がひなば呪詛を蒙らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, '汝の神ヱホバ汝が往て獲んとする地に汝を導きいりたまふ時は汝ゲリジム山に祝福を置きエバル山に呪詛をおくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'この二山はヨルダンの彼旁アラバに住るカナン人の地において日の出る方の道の後にありギルガルに對ひてモレの橡樹と相去こと遠らざるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, '汝らはヨルダンを濟り汝らの神ヱホバの汝らに賜ふ地に進みいりて之を獲んとす必ずこれを獲て其處に住ことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, '然ば我が今日なんぢらに授くるところの法度と律法を汝らことごとく守りて行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '是は汝の先祖等の神ヱホバの汝に與へて獲させたまふところの地において汝らが世に生存ふる日の間常に守り行ふべき法度と律法となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, '汝らが逐はらふ國々の民がその神々に事へし處は山にある者も岡にある者も靑樹の下にある者もみな之を盡く毀ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'その壇を毀ちその柱を碎きそのアシラ像を火にて燒きまたその神々の雕像を斫倒して之が名をその處より絶去べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, '但し汝らの神ヱホバには汝ら是のごとく爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, '汝らの神ヱホバがその名を置んとて汝らの支派の中より擇びたまふ處なるヱホバの住居を汝ら尋ね求めて其處にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, '汝らの燔祭と犠牲汝らの什一と汝らの手の擧祭汝らの願還と自意の禮物および汝らの牛羊の首出等を汝ら其處に携へ詣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, '其處にて汝らの神ヱホバの前に食をなし又汝らと汝らの家族皆その手を勞して獲たる物をもて快樂を取べし是なんぢの神ヱホバの祝福によりて獲たるものなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, '汝ら彼處にては我らが今日此に爲ごとく各々その目に善と見ところを爲べからす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, '汝らは尚いまだ汝らの神ヱホバの賜ふ安息と產業にいたらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, '然ど汝らヨルダンを渡り汝らの神ヱホバの汝らに與へて獲させたまふ地に住にいたらん時またヱホバ汝らの周圍の敵を除き汝らに安息を賜ひて汝等安泰に住ふにいたらん時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, '汝らの神ヱホバその名を置んために一の處を擇びたまはん汝ら其處に我が命ずる物を都て携へゆくべし即ち汝らの燔祭と犠牲と汝らの什一と汝らの手の擧祭および汝らがヱホバに誓願をたてて献んと誓ひし一切の佳物とを携へいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, '汝らは汝らの男子女子僕婢とともに汝らの神ヱホバの前に樂むべしまた汝らの門の内にをるレビ人とも然すべし其は是は汝らの中間に分なく產業なき者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, '汝愼め凡て汝が自ら擇ぶ處にて燔祭を献ることをする勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, '唯汝らの支派の一の中にヱホバの選びたまはんその處に於て汝燔祭を献げまた我が汝に命ずる一切の事を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, '彼處にては汝の神ヱホバの汝にたまふ祝福に循ひて汝その心に好む獣畜を汝の門の内に殺してその肉を食ふことを得即ち汚れたる人も潔き人もこれを食ふを得ること羚羊と牡鹿に於けるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, '但しその血は食ふべからず水の如くにこれを地に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, '汝の穀物と酒と油の什一および汝の牛羊の首出ならびに汝が立し誓願を還すための禮物と汝の自意の禮物および汝の手の擧祭の品は汝これを汝の門の内に食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, '汝の神ヱホバの選びたまふ處において汝の神ヱホバの前に汝これを食ふべし即ち汝の男子女子僕婢および汝の門の内にをるレビ人とともに之を食ひ汝の手を勞して獲たる一切の物をもて汝の神ヱホバの前に快樂を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, '汝愼め汝が世に生存ふる日の間レビ人を棄る勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, '汝の神ヱホバ汝に言しごとくに汝の境界を廣くしたまふに及び汝心に肉を食ふことを欲して言ん我肉を食はんと然る時は汝すべてその心に好む肉を食ふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'もし汝の神ヱホバのその名を置んとて擇びたまへる處汝と離るること遠からば我が汝に命ぜし如く汝そのヱホバに賜はれる牛羊を宰り汝の門の内にて凡てその心に好む者を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, '牡鹿と羚羊を食ふがごとく汝これを食ふことを得汚れたる者も潔き者も均くこれを食ふことを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, '唯堅く愼みてその血を食はざれ血はこれが生命なればなり汝その生命を肉とともに食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, '汝これを食ふ勿れ水のごとくにこれを地に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, '汝血を食はざれ汝もし斯ヱホバの善と觀たをふ事を爲ば汝の身と汝の後の子孫とに福祉あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, '唯汝の献げたる聖物と誓願の物とはこれをヱホバの擇びたまふ處に携へゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, '汝燔祭を献る時はその肉と血を汝の神ヱホバの壇に供ふべくまた犠牲を献る時はその血を汝の神ヱホバの壇の上に灌ぎその肉を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'わが汝に命ずる是等の言を汝聽て守れ汝かく汝の神ヱホバの善と觀正と觀たまふ事を爲ば汝と汝の後の子孫に永く福祉あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, '汝の神ヱホバ汝が往て逐はらはんとする國々の民を汝の前より絶去たまひて汝つひにその國々を獲てその地に住にいたらん時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, '汝みづから愼め彼らが汝の前に亡びたる後汝かれらに倣ひて罟にかかる勿れまた彼らの神を尋求めこの國々の民は如何なる樣にてその神々に事へたるか我もその如くにせんと言ことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, '汝の神ヱホバに向ひては汝然す可らず彼らはヱホバの忌かつ憎みたまふ諸の事をその神にむかひて爲しその男子女子をさへ火にて焚てその神々に献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, '我が汝らに命ずるこの一切の言をなんぢら守りて行ふべし汝これを増なかれまた之を減すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, '汝らの中に預言者あるひは夢者興りて徴證と奇蹟を汝に見し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, '汝に告て我らは今より汝と我とが是まで識ざりし他の神々に從ひて之に事へんと言ことあらんにその徴證または奇蹟これが言ごとく成とも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, '汝その預言者または夢者の言に聽したがふ勿れ其は汝等の神ヱホバ汝らが心を盡し精神を盡して汝らの神ヱホバを愛するや否やを知んとて斯なんぢらを試みたまふなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, '汝らは汝らの神ヱホバに從ひて歩み之を畏れその誡命を守りその言に遵ひ之に事へこれに附從ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'その預言者または夢者をば殺すべし是は彼汝らをして汝らをエジプトの國より導き出し奴隸の家より贖ひ取たる汝らの神ヱホバに背かせんとし汝の神ヱホバの汝に歩めと命ぜし道より汝を誘ひ出さんとして語るに因てなり汝斯して汝の中より惡を除き去べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, '汝の母の生る汝の兄弟または汝の男子女子または汝の懐の妻または汝と身命を共にする汝の友潜に汝を誘ひて言あらん汝も汝の先祖等も識ざりし他の神々に我ら往て事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, '即ち汝の周圍にある國々の神の或は汝に近く或は汝に遠くして地の此極より地の彼極までに鎮り坐る者に我ら事へんと斯言ことあるとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, '汝これに從ふ勿れ之に聽なかれ之を惜み視る勿れ之を憐むなかれ之を庇ひ匿す勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, '汝かならず之を殺すべし之を殺すには汝まづ之に手を下し然る後に民みな手を下すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, '彼はエジプトの國奴隸の家より汝を導き出したまひし汝の神ヱホバより汝を誘ひ離さんと求めたれば汝石をもて之を撃殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, '然せばイスラエルみな聞て懼れ重ねて斯る惡き事を汝らの中に行はざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, '汝聞に汝の神ヱホバの汝に與へて住しめたまへる汝の邑の一に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, '邪僻なる人々興り我らは今まで識ざりし他の神々に往て事へんと言てその邑に住む人を誘ひ惑はしたりと言あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, '汝これを尋ね探り善問べし若その事眞にその言確にして斯る憎むべき事汝らの中に行はれたらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, '汝かならずその邑に住む者を刃にかけて撃ころしその邑とその中に居る一切の者およびその家畜を刃にかけて盡く撃ころすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'またその中より獲たる掠取物は凡てこれをその衢に集め火をもてその邑とその一切の掠取物をことごとく焚て汝の神ヱホバに供ふべし是は永く荒邱となりて再び建なほさるること無るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, '斯汝この詛はれし物を少許も汝の手に附おく勿れ然せばヱホバその烈しき怒を靜め汝に慈悲を加へて汝を憐れみ汝の先祖等に誓ひしごとく汝の數を衆くしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, '汝もし汝の神ヱホバの言を聽き我が今日なんぢに命ずるその一切の誡命を守り汝の神ヱホバの善と觀たまふ事を行はば是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, '汝らは汝等の神ヱホバの子等なり汝ら死る者のために己が身に傷くべからずまた己が目の間にあたる頂の髮を剃べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, '其は汝は汝の神ヱホバの聖民なればなりヱホバは地の面の諸の民の中より汝を擇びて己の寶の民となし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, '汝穢はしき物は何をも食ふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, '汝らが食ふべき獣畜は是なり即ち牛 羊 山羊');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, '牡鹿 羚羊 小鹿 麣 麞 麈 麖など');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, '凡て獣畜の中蹄の分れ割て二つの蹄を成る反芻獣は汝ら之を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, '但し反芻者と蹄の分れたる者の中汝らの食ふべからざる者は是なり即ち駱駝 兎および山鼠是らは反芻ども蹄わかれざれば汝らには汚れたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'また豚是は蹄わかるれども反芻ことをせざれば汝らには汚たる者なり汝ら是等の物の肉を食ふべからずまたその死體に捫るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, '水にをる諸の物の中是のごとき者を汝ら食ふべし即ち凡て翅と鱗のある者は皆汝ら之を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, '凡て翅と鱗のあらざる者は汝らこれを食ふべからず是は汝らには汚たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'また凡て潔き鳥は皆汝らこれを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, '但し是等は食ふべからず即ち鵰黄鷹鳶');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, '鸇鷹 黑鷹の類');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, '各種の鴉の類');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, '駝鳥 梟 鴎 雀鷹の類');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, '鸛 鷺 白鳥');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, '鸅鸕 大鷹 鵜');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, '鶴 鸚鵡の類 鷸および蝙蝠');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'また凡て羽翼ありて匍ところの者は汝らには汚たる者なり汝らこれを食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, '凡て羽翼をもて飛ところの潔き物は汝らこれを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, '凡そ自ら死たる者は汝ら食ふべからず汝の門の内にをる他國の人に之を與へて食しかべし又これを異邦人に賣も可し汝は汝の神ヱホバの聖民なればなり汝山羊羔をその母の乳にて煮べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, '汝かならず年々に田畝に種蒔て獲ところの產物の什一を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, '而して汝の神ヱホバの前すなはちヱホバのその名を置んとて擇びたまはん處において汝の穀物と酒と油の什一を食ひまた汝の牛羊の首出を食ひ斯して汝の神ヱホバを常に畏るることを學ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, '但しその路行に勝がたくして之を携へいたること能はざる時または汝の神ヱホバのその名を置んとて擇びたまへる處汝を離るること餘りに遠き時は汝もし汝の神ヱホバの恩惠に潤ふ身ならば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'その物を金に易へその金を包みて手に執り汝の神ヱホバの擇びたまへる處に往き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, '凡て汝の心の好む物をその金に易べし即ち牛羊葡萄酒濃酒など凡て汝が心に欲する物をもとめ其處にて汝の神ヱホバの前にこれを食ひ汝と汝の家族ともに樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, '汝の門の内にをるレビ人を棄る勿れ是は汝の中間に分なく產業なき者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, '三年の末に到る毎にその年の產物の十分の一を盡く持出してこれを汝の門の内に儲蓄ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, '然る時は汝の中間に分なく產業なきレビ人および汝の門の内にをる他國の人と孤子と寡婦など來りてこれを食ひて飽ん斯せば汝の神ヱホバ汝が手をもて爲ところの諸の事において汝に福祉を賜ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, '七年の終に至るごとに汝放釋を行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'その放釋の例は是のごとし凡てその鄰に貸ことを爲しその債主は之を放釋べしその鄰またはその兄弟にこれを督促べからず是はヱホバの放釋と稱へらるればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, '異國の人には汝これを督促ことを得されど汝の兄弟に貸たる物は汝の手よりこれを放釋べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, '斯せば汝らの中間に貧者なからん其は汝の神ヱホバその汝に與へて產業となさしめたまふ地において大に汝を祝福たまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, '只汝もし謹みて汝の神ヱホバの言に聽したがひ我が今日なんぢに命ずるこの誡命を盡く守り行ふに於ては是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, '汝の神ヱホバ汝に言しごとく汝を祝福たまふべければ汝は衆多の國人に貸ことを得べし然ど借こと有じまた汝は衆多の國人を治めん然ど彼らは汝を治むることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, '汝の神ヱホバの汝に賜ふ地において若汝の兄弟の貧き人汝の門の中にをらばその貧しき兄弟にむかひて汝の心を剛愎にする勿れまた汝の手を閉る勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'かならず汝の手をこれに開き必ずその要むる物をこれに貸あたへてこれが乏しきを補ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, '汝愼め心に惡き念を起し第七年放釋の年近づけりと言て汝の貧き兄弟に目をかけざる勿れ汝もし斯之に何をも與へずしてその人これがために汝をヱホバに訴へなば汝罪を獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, '汝かならず之に與ふることを爲べしまた之に與ふる時は心に惜むこと勿れ其は此事のために汝の神ヱホバ汝の諸の事業と汝の手の諸の働作とに於て汝を祝福たまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, '貧き者は何時までも國にたゆること無るべければ我汝に命じて言ふ汝かならず汝の國の中なる汝の兄弟の困難者と貧乏者とに汝の手を開くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, '汝の兄弟たるヘブルの男またはヘブルの女汝の許に賣れたらんに若六年なんぢに事へたらば第七年に汝これを放ちて去しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, '汝これを放ちて去しむる時は空手にて去しむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, '汝の群と禾場と搾場の中より贈物を取て之が肩に負すべし即ち汝の神ヱホバの汝を祝福て賜ふところの物をこれに與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, '汝記憶べし汝はエジプトの國に奴隸たりしが汝の神ヱホバ汝を贖ひ出したまへり是故に我今日この事を汝に命ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'その人もし汝と汝の家を愛し汝と偕にをるを善として汝にむかひ我汝を離れて去を好まずと言ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, '汝錐を取て彼の耳を戸に刺とほすべし然せば彼は永く汝の僕たるべし汝の婢にもまた是のごとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, '汝これを放ちて去しむるを難き事と見るべからず其は彼が六年汝に事へて働きしは工價を取る傭人の二倍に當ればなり汝斯なさば汝の神ヱホバ汝が凡て爲ところの事に於て汝をめぐみたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, '汝の牛羊の產る初子は皆これを聖別て汝の神ヱホバに歸せしむべし汝の牛の初子をもちゐて何の工作をも爲べからず又汝の羊の初子の毛を剪べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, '汝の神ヱホバの選びたまへる處にてヱホバの前に汝と汝の家族年々にこれを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, '然どその畜もし疵ある者すなはち跛足盲目なるなど凡て惡き疵ある者なる時は汝の神ヱホバにこれを宰りて献ぐべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, '汝の門の内にこれを食ふべし汚れたる者も潔き者も均くこれを食ふを得ること牡鹿と羚羊のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, '但しその血はこれを食ふべからず水のごとくにこれを地に灌ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, '汝アビブの月を守り汝の神ヱホバに對ひて逾越節を行なへ其はアビブの月に於て汝の神ヱホバ夜の間に汝をエジプトより導き出したまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, '汝すなはちヱホバのその名を置んとて擇びたまふ處にて羊および牛を宰り汝の神ヱホバの前に逾越節をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, '酵いれたるパンを之とともに食ふべからず七日の間酵いれぬパン即ち憂患のパンを之とともに食ふべし其は汝エジプトの國より出る時は急ぎて出たればなり斯おこなひて汝その世に生存ふる日の間恒に汝がエジプトの國より出來し日を誌ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'その七日の間は汝の四方の境の内にパン酵の見ること有しむべからず又なんぢが初の日の薄暮に宰りたる者の肉を翌朝まで存しおくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, '汝の神ヱホバの汝に賜ふ汝の門の内にて逾越の牲畜を宰ることを爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, '惟汝の神ヱホバのその名を置んとて選びたまふ處にて汝薄暮の日の入る頃汝がエジプトより出たる時刻に逾越の牲畜を宰るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, '而して汝の神ヱホバの選びたまふ處にて汝これを燔て食ひ朝におよびて汝の天幕に歸り往くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, '汝六日の間酵いれぬパンを食ひ第七日に汝の神ヱホバの前に會を開くべし何の職業をも爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, '汝また七七日を計ふべし即ち穀物に鎌をいれ初る時よりしてその七七日を計へ始むべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, '而して汝の神ヱホバの前に七週の節筵を行なひ汝の神ヱホバの汝を祝福たまふ所にしたがひ汝の力に應じてその心に願ふ禮物を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, '斯して汝と汝の男子女子僕婢および汝の門の内に居るレビ人ならびに汝らの中間にをる賓旅と孤子と寡婦みなともに汝の神ヱホバのその名を置んとて選びたまふ處にて汝の神ヱホバの前に樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, '汝その昔エジプトに奴隸たりしことを誌え是等の法度を守り行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, '汝禾場と搾場の物を収蔵たる時七日の間結茅節をおこなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, '節筵をなす時には汝と汝の男子女子僕婢および汝の門の内なるレビ人賓旅孤子寡婦など皆ともに樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'ヱホバの選びたまふ處にて汝七日の間なんぢの神ヱホバの前に節筵をなすべし汝の神ヱホバ汝の諸の產物と汝が手の諸の工事とについて汝を祝福たまふべければ汝かならず樂むことを爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, '汝の中間の男は皆なんぢの神ヱホバの擇びたまふ處にて一年に三次即ち酵いれぬパンの節と七週の節と結茅の節とに於てヱホバの前に出べし但し空手にてヱホバの前に出べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, '各人汝の神ヱホバに賜はる恩惠にしたがひて其力におよぶ程の物を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, '汝の神ヱホバの汝に賜ふ一切の邑々に汝の支派に循がひて士師と官人を立べし彼らはまだ義き審判をもて民を審判べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, '汝裁判を枉べからず人を偏視るべからずまた賄賂を取べからず賄賂は智者の目を暗まし義者の言を枉ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, '汝ただ公義を而已求むべし然せば汝生存へて汝の神ヱホバの汝に賜ふ地を獲にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, '汝の神ヱホバのために築くところの壇の傍にアシラの木像を立べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'また汝の神ヱホバの惡みたまふ偶像を己のために造るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, '凡て疵あり惡き處ある牛羊は汝これを汝の神ヱホバに献ぐべからず斯る者は汝の神ヱホバの忌嫌ひたまふ者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, '汝の神ヱホバの汝に賜ふ邑々の中にて汝らの中間に若し或男または女汝の神ヱホバの目の前に惡事を行ひてその契約に悖り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, '往て他の神々に事へてこれを拝み我が命ぜざる日や月や天の衆群などを拝むあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'その事を汝に告る者ありて汝これを聞き細かにこれを査べ見るにその事眞にその言確にしてイスラエルの中に斯る憎むべき事行はれ居たらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, '汝その惡き事を行へる男または女を汝の門に曳いだし石をもてその男または女を撃殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, '殺すべき者は二人の證人または三人の證人の口に依てこれを殺すべし惟一人の證人の口のみをもて之を殺すことは爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, '斯る者を殺すには證人まづその手を之に加へ然る後に民みなその手を加ふべし汝かく惡事を汝らの中より除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, '汝の門の内に訟へ爭ふ事おこるに當りその事件もし血を相流す事または權理を相爭ふ事または互に相撃たる事などにして汝に裁判かぬる者ならば汝起あがりて汝の神ヱホバの選びたまふ處に上り往き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, '祭司なるレビ人と當時の士師とに詣りて問べし彼ら裁判の言詞を汝に示さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'ヱホバの選びたまふ處にて彼らが汝に示す命令の言のごとくに汝行ひ凡て彼らが汝に敎ふるごとくに愼みて爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, '即ち故らが汝に敎ふる律法の命令に循がひ彼らが汝に告る裁判に依て行ふべし彼らが汝に示す言に違ふて右にも左にも偏るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, '人もし自ら壇斷にしその汝の神ヱホバの前に立て事ふる祭司またはその士師に聽したがはざる有ばその人を殺しイスラエルの中より惡を除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, '然せば民みな聞て畏れ重て壇斷に事をなさざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, '汝の神ヱホバの汝に賜ふ地に汝いたり之を獲て其處に住におよべる時汝もし我周圍の一切の國人のごとくに我も王をわが上に立んと言あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, '只なんぢの神ヱホバの選びたまふ人を汝の上にたてて王となすべしまた汝の上に王を立るには汝の兄弟の中の人をもてすべし汝の兄弟ならざる他國の人を汝の上に立べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, '但し王となれる者は馬を多く得んとすべからず又馬を多く得んために民を率てエジプトに還るべからず其はヱホバなんぢらに向ひて汝らはこの後かさねて此路に歸るべからずと宣ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'また妻を多くその身に有て心を迷すべからずまた金銀を己のために多く蓄積べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, '彼その國の位に坐するにいたらば祭司なるレビ人の前にある書よりしてこの律法を一の書に書寫さしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, '世に生存ふる日の間つねにこれを己の許に置て誦み斯してその神ヱホバを畏るることを學びこの律法の一切の言と是等の法度を守りて行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, '然せば彼の心その兄弟の上に高ぶること無くまたその誡命を離れて右にも左にもまがること無してその子女とともにその國においてイスラエルの中にその日を永うすることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, '祭司たるレビ人およびレビの支派は都てイスラエルの中に分なく產業なし彼らはヱホバの火祭の品とその產業の物を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, '彼らはその兄弟の中間に產業を有じヱホバこれが產業たるたり即ちその曾て之に言たまひしが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, '祭司が民より受べき分は是なり即ち凡て犠牲を献ぐる者は牛にもあれ羊にもあれその肩と兩方の頬と胃とを祭司に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'また汝の穀物と酒と油の初および羊の毛の初をも之にあたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, '其は汝の神ヱホバ汝の諸の支派の中より彼を選び出し彼とその子孫をして永くヱホバの名をもて立て奉事をなさしめたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'レビ人はイスラエルの全地の中何の處に居る者にもあれその寄寓たる汝の邑を出てヱホバの選びたま處に到るあらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'その人はヱホバの前に侍るその諸兄弟のレビ人とおなじくその神ヱホバの名をもて奉事をなすことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'その人の得て食ふ分は彼らと同じ但しその父の遺業を賣て獲たる物はこの外に彼に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, '汝の神ヱホバの汝に賜ふ池にいたるに及びて汝その國々の民の憎むべき行爲を倣ひ行ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, '汝らの中間にその男子女子をして火の中を通らしむる者あるべからずまた卜筮する者邪法を行なふ者禁厭する者魔術を使ふ者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, '法印を結ぶ者憑鬼する者巫覡の業をなす者死人に詢ことをする者あるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, '凡て是等の事を爲す者はヱホバこれを憎たまふ汝の神ヱホバが彼らを汝の前より逐はらひたまひしも是等の憎むべき事のありしに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, '汝の神ヱホバの前に汝完き者たれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, '汝が逐はらふ故の國々の民は邪法師卜筮師などに聽ことをなせり然ど汝には汝の神ヱホバ然する事を許したまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, '汝の神ヱホバ汝の中汝の兄弟の中より我のごとき一箇の預言者を汝のために興したまはん汝ら之に聽ことをすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, '是まったく汝が集會の日にホレブにおいて汝の神ヱホバに求めたる所なり即ち汝言けらく我をして重てこの我神ヱホバの聲を聞しむる勿れまた重てこの大なる火を見さする勿れ恐くは我死んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, '是においてヱホバ我に言たまひけるは彼らの言る所は善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, '我かれら兄弟の中より汝のごとき一箇の預言者を彼らのために興し我言をその口に授けん我が彼に命ずる言を彼ことごとく彼らに告べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, '凡て彼が吾名をもて語るところの吾言に聽したがはざる者は我これを罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, '但し預言者もし我が語れと命ぜざる言を吾名をもて縦肆に語りまたは他の神々の名をもて語ることを爲すならばその預言者は殺さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, '汝あるひは心に謂ん我ら如何にしてその言のヱホバの言たまふ者にあらざるを知んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, '然ば若し預言者ありてヱホバの名をもて語ることをなすにその言就ずまた效あらざる時は是ヱホバの語りたまふ言にあらずしてその預言者が縦肆に語るところなり汝その預言者を畏るるに及ばす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, '汝の神ヱホバこの國々の民を滅し絶ち汝の神ヱホバこれが地を汝に賜ふて汝つひにこれを獲その邑々とその家々に住にいたる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, '汝の神ヱホバの汝に與へて產業となさしめたまふ地の中に三の邑を汝のために區別べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, '而して汝これに道路を開きまた汝の神ヱホバの汝に與へて產業となさしめたまふ地の全體を三の區に分ち凡て人を殺せる者をして其處に逃れしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, '人を殺せる者の彼處に逃れて生命を全うすべきその事は是のごとし即ち凡て素より惡むことも無く知ずしてその鄰人を殺せる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, '例ば人木を伐んとてその鄰人とともに林に入り手に斧を執て木を斫んと撃おろす時にその頭の鐵柯より脱てその鄰人にあたりて之を死しめたるが如き是なり斯る人は是等の邑の一に逃れて生命を全うすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, '恐くは復仇する者心熱してその殺人者を追かけ道路長きにおいては遂に追しきて之を殺さん然るにその人は素より之を惡みたる者にあらざれば殺さるべき理あらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, '是をもて我なんぢに命じて三の邑を汝のために區別べしと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, '汝の神ヱホバ汝の先祖等に誓ひしごとく汝の境界を廣め汝の先祖等に與へんと言し地を盡く汝に賜ふにいたらん時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '即ち汝我が今日なんぢに命ずるこの一切の誡命を守りてこれを行なひ汝の神ヱホバを愛し恒にその道に歩まん時はこの三の外にまた三の邑を増加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, '是汝の神ヱホバの汝に與へて產業となさしめたまふ地に辜なき者の血を流すこと無らんためなり斯せずばその血汝に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, '然どもし人その隣人を惡みて之を附覘ひ起かかり撃てその生命を傷ひて之を死しめ而してこの邑の一に逃れたる事あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'その邑の長老等人を遣て之を其處より曳きたらしめ復仇者の手にこれを付して殺さしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, '汝かれを憫み視るべからず辜なき者の血を流せる咎をイスラエルより除くべし然せば汝に福祉あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, '汝の神ヱホバの汝に與へて獲させたまふ地の中において汝が嗣ぐところの產業に汝の先人の定めたる汝の鄰の地界を侵すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, '何の惡にもあれ凡てその犯すところの罪は只一人の證人によりて定むべからず二人の證人の口によりまたは三人の證人の口によりてその事を定むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'もし偽妄の證人起りて某の人は惡事をなせりと言たつること有ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'その相爭ふ二人の者ヱホバの前に至り當時の祭司と士師の前に立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, '然る時士師詳細にこれを査べ視るにその證人もし偽妄の證人にしてその兄弟にむかひて虚妄の證をなしたる者なる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, '汝兄弟に彼が蒙らさんと謀れる所を彼に蒙らし斯して汝らの中より惡事を除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, '然せばその遺れる者等聞て畏れその後かさねて斯る惡き事を汝らの中におこなはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, '汝憫み視ることをすべからず生命は生命眼は眼歯は歯手は手足は足をもて償はしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, '汝その敵と戰はんとて出るに當り馬と車を見また汝よりも數多き民を見るもこれに懼るる勿れ其は汝をエジプトの國より導き上りし汝の神ヱホバなんぢとともに在せばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, '汝ら戰闘に臨む時は祭司進みいで民に告て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, '之に言べしイスラエルよ聽け汝らは今日なんぢらの敵と戰はんとて進み來れり心に臆する勿れ懼るるなかれ倉皇なかれ彼らに怖るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, '其は汝らの神ヱホバ汝らとともに行き汝らのために汝らの敵と戰ひて汝らを救ひたまふべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, '斯てまた有司等民に告て言べし誰か新しき家を建て之に移らざる者あるかその人は家に歸りゆくべし恐くは自己戰闘に死て他の人これに移らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, '誰か菓物園を作りてその果を食はざる者あるかその人は家に歸りゆくべし恐くは自己戰闘に死て他の人これを食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, '誰か女と契りて之を娶らざる者あるかその人は家に歸りゆくべし恐くは自己戰闘に死て他の人これを娶らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, '有司等なほまた民に告て言べし誰か懼れて心に臆する者あるかその人は家に歸りゆくべし恐くはその兄弟たちの心これが心のごとく挫けんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, '有司等かく民に告ることを終たらば軍勢の長等を立て民を率しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, '汝ある邑に進みゆきて之を攻んとする時は先これに平穩に降ることを勸むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'その邑もし平穩に降らんと答へてその門を汝に開かば其處なる民をして都て汝に貢を納しめ汝に事へしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, '其もし平穩に汝に降ることを肯んぜずして汝と戰かはんとせば汝これを攻べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, '而して汝の神ヱホバこれを汝の手に付したまふに至らば刃をもてその中の男を盡く撃殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, '惟その婦女嬰孩家畜および凡てその邑の中にて汝が奪ひ獲たる物は盡く己に取べし抑汝がその敵より奪ひ獲たる物は汝の神ヱホバの汝に賜ふ者なれば汝これをもて樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, '汝を離るることの遠き邑々すなはち是等の國々に屬せざるところの邑々には凡てかくのごとく行なふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, '但し汝の神ヱホバの汝に與へて產業となさしめたまふこの國々の邑々においては呼吸する者を一人も生し存べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, '即ちヘテ人 アモリ人 カナン人 ペリジ人 ヒビ人 ヱブス人などは汝かならずこれを滅ぼし盡して汝の神ヱホバの汝に命じたまへる如くすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, '斯するは彼らがその神々にむかひて行ふところの憎むべき事を汝らに敎へて之を倣ひおこなはしめ汝らをして汝らの神ヱホバに罪を獲せしむる事のなからんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, '汝久しく邑を圍みて之を攻取んとする時においても斧を振ふて其處の樹を砍枯すべからず是は汝の食となるべき者なり且その城攻において田野の樹あに人のごとく汝の前に立ふさがらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, '但し果を結ばざる樹と知る樹はこれを砍り枯し汝と戰ふ邑にむかひて之をもて雲梯を築きその降るまで之を攻るも宜し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, '汝の神ヱホバの汝に與へて獲させたまふ地において若し人殺されて野に仆れをるあらんに之を殺せる者の誰なるかを知ざる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, '汝の長老等と士師等出きたりその人の殺されをる處よりその四周の邑々までを度るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, '而してその人の殺されをる處に最も近き邑すなはちその邑の長老等は未だ使はず未だ軛を負せて牽ざるところの少き牝牛を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, '邑の長老等その牝牛を耕すことも種蒔こともせざる流つきせぬ谷に牽ゆきその谷において牝牛の頸を折べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'その時は祭司たるレビの子孫等其處に進み來るべし彼らは汝の神ヱホバが選びて己に事へしめまたヱホバの名をもて祝することを爲しめたまふ者にて一切の訴訟と一切の爭競は彼らの口によりて決定るべきが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, '而してその人の殺されをりし處に最も近き邑の長老等その谷にて頸を折たる牝牛の上において手を洗ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, '答へて言べし我らの手はこの血を流さず我らの目はこれを見ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'ヱホバよ汝が贖ひし汝の民イスラエルを赦したまへこの辜なき者の血を流せる罰を汝の民イスラエルの中に降したまふ勿れと斯せば彼らその血の罪を赦されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, '汝かくヱホバの善と觀たまふ事をおこなひその辜なき者の血を流せる咎を汝らの中より除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, '汝出て汝の敵と戰ふにあたり汝の神ヱホバこれを汝の手に付したまひて汝これを俘虜となしたる時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, '汝もしその俘虜の中に貌美しき女あるを見てこれを悦び取て妻となさんとせば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, '汝の家の中にこれを携へゆくべし而して彼はその髮を剃り爪を截り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'まだ俘虜の衣服を脱すてて汝の家に居りその父母のために一月のあひだ哀哭べし然る後なんぢ故の處に入りてこれが夫となりこれを汝の妻とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'その後汝もし彼を好まずなりなば彼の心のままに去ゆかしむべし決して金のためにこれを賣べからず汝すでにこれを犯したれば之を嚴く待遇べからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, '人二人の妻ありてその一人は愛する者一人は惡む者ならんにその愛する者と惡む者の二人ともに男の子を生ありてその長子もし惡む婦の產る者なる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'その子等に己の所有を嗣しむる日にその惡む婦の產る長子を措てその愛する婦の產る子を長子となすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, '必ずその惡む者の產る子を長子となし己の所有を分つ時にこれには二倍を與ふべし是は己の力の始にして長子の權これに屬すればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, '人にもし放肆にして背悖る子ありその父の言にも母の言にも順はず父母これを責るも聽ことをせざる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'その父母これを執へてその處の門にいたり邑の長老等に就き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, '邑の長老たちに言べし我らの此子は放肆にして背悖る者我らの言にしたがはざる者放蕩にして酒に耽る者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, '然る時は邑の人みな石をもて之を撃殺すべし汝かく汝らの中より惡事を除き去べし然せばイスラエルみな聞て懼れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, '人もし死にあたる罪を犯して死刑に遇ことありて汝これを木に懸て曝す時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, '翌朝までその體を木の上に留おくべからず必ずこれをその日の中に埋むべし其は木に懸らるる者はヱホバに詛はるる者なればなり斯するは汝の神ヱホバの汝に賜ふて產業となさしめたまふ地の汚れざらんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '汝の兄弟の牛または羊の迷ひをるを見てこれを見すて置べからず必ずこれを汝の兄弟に牽ゆきて歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, '汝の兄弟もし汝に近からざるか又は汝かれを知ざる時はこれを汝の家に牽ゆきて汝の許におき汝の兄弟の尋ねきたるに及びて之を彼に還すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, '汝の兄弟の驢馬におけるも是のごとく爲しまたその衣服におけるも斯なすべし凡て汝の兄弟の失ひたる遺失物を得たる時も汝かく爲べし之を見すておくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'また汝の兄弟の驢馬または牛の途に踣れをるを見て見すておくべからず必ずこれを助け起すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, '女は男の衣服を纒ふべからずまた男は女の衣裳を著べからず凡て斯する者は汝の神ヱホバこれを憎みたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, '汝鳥の巣の路の頭または樹の上または土の上にあるを見んに雛または卵その中にありて母鳥その雛または卵の上に伏をらばその母鳥を雛とともに取べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'かならずその母鳥を去しめ唯その雛のみをとるべし然せば汝福祉を獲かつ汝の日を永うすることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, '汝新しき家を建る時はその屋蓋の周圍に欄杆を設くべし是は人その上より堕てこれが血の汝の家に歸すること無らんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, '汝菓物園に異類の種を混て播べからず然せば汝が播たる種より產する物および汝の菓物園より出る菓物みな聖物とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, '汝牛と驢馬とを耦せて耕すことを爲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, '汝毛と麻とをまじへたる衣服を著べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, '汝が上に纒ふ衣服の裾の四方に繸をつくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, '人もし妻を娶り之とともに寝て後これを嫌ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, '我この婦人を娶りしが之と寝たる時にその處女なるを見ざりしと言て誹謗の辭抦を設けこれに惡き名を負せなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'その女の父と母その女の處女なる證跡を取り門にをる邑の長老等にこれを差出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, '而してその女の父長老等に言べし我この人にわが女子を與へて妻となさしめしにこの人これを嫌ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, '誹謗の辭抦を設けて言ふ我なんぢの女子の處女なるを見ざりしと然るに吾女子の處女なりし證跡は此にありと斯いひてその父母かの布を邑の長老等の前に展べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, '然る時は邑の長老等その人を執へてこれを鞭ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, '又これに銀百シケルを罰してその女の父に償はしむべし其はイスラエルの處女に惡き名を負せたればなり斯てその人はこれを妻とすべし一生これを去ことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, '然どこの事もし眞にしてその女の處女なる證跡あらざる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'その女をこれが父の家の門に曳いだしその邑の人々石をもてこれを撃ころすべし其は彼その父の家にて淫なる事をなしてイスラエルの中に惡をおこなひたればなり汝かく惡事を汝らの中より除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'もし夫に適し婦と寝る男あるを見ばその婦と寝たる男と其婦とをともに殺し斯して惡事をイスラエルの中より除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, '處女なる婦人すでに夫に適の約をなせる後ある男これに邑の内に遇てこれを犯さば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, '汝らその二人を邑の門に曳いだし石をもてこれを撃ころすべし是その女は邑の内にありながら叫ぶことをせざるに因りまたその男はその鄰の妻を辱しめたるに因てなり汝かく惡事を汝らの中より除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, '然ど男もし人に適の約をなしし女に野にて遇ひこれを強て犯すあらば之を犯しし男のみを殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'その女には何をも爲べからず女には死にあたる罪なし人その鄰人に起むかひてこれを殺せるとその事おなじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, '其は男野にてこれに遇たるが故にその人に適の約をなしし女叫びたれども拯ふ者なかりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, '男もし未だ人に適の約をなさざる處女なる婦に遇ひこれを執へて犯すありてその二人見あらはされなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'これを犯せる男その女の父に銀五十シケルを與へて之を己の妻とすべし彼その女を辱しめたれば一生これを去るべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, '人その父の妻を娶るべからずその父の被を掀開べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, '外腎を傷なひたる者または玉莖を切りたる者はヱホバの會に入べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, '私子はヱホバの會にいるべからず是は十代までもヱホバの會にいるべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'アンモン人およびモアブ人はヱホバの會にいる可らず故らは十代までも何時までもヱホバの會にいるべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, '是汝らがエジプトより出きたりし時に彼らはパンと水とをもて汝らを途に迎へずメソポタミアのペトル人ベオルの子バラムを倩ひて汝を詛はせんと爲たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, '然れども汝の神ヱホバ、バラムに聽ことを爲給はずして汝の神ヱホバその呪詛を變て汝のために祝福となしたまへり是汝の神ヱホバ汝を愛したまふが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, '汝一生いつまでも彼らのために平安をもまた福禄をも求むべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, '汝エドム人を惡べからず是は汝の兄弟なればなりまたエジプト人を惡むべからず汝もこれが國に客たりしこと有ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, '彼等の生たる子等は三代におよばばヱホバの會にいることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, '汝軍旅を出して汝の敵を攻る時は諸の惡き事を自ら謹むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, '汝らの中間にもし夜中計ずも汚穢にふれて身の潔からざる人あらば陣營の外にいづべし陣營の内に入べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, '而して薄暮に水をもて身を洗ひ日の入て後陣營に入べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, '汝陣營の外に一箇の處を設けおき便する時は其處に往べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'また器具の中に小鍬を備へおき外に出て便する時はこれをもて土を掘り身を返してその汝より出たる物を蓋ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, '其は汝の神ヱホバ汝を救ひ汝の敵を汝に付さんとて汝の陣營の中を歩きたまへばなり是をもて汝の陣營を聖潔すべし然せば汝の中に汚穢物あるを見て汝を離れたまふこと有ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'その主人を避て汝の許に逃きたる僕をその主人に交すべからす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'その者をして汝らの中に汝とともに居しめ汝の一の邑の中にて之が善と見て擇ぶ處に住しむべし之を虐遇べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'イスラエルの女子の中に娼妓あるべからずイスラエルの男子の中に男娼あるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, '娼妓の得たる價および狗の價を汝の神ヱホバの家に携へいりて何の誓願にも用ゐるべからず是等はともに汝の神ヱホバの憎みたまふ者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, '汝の兄弟より利息を取べからず即ち金の利息食物の利息など凡て利息を生ずべき物の利息を取べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, '他國の人よりは汝利息を取も宜し惟汝の兄弟よりは利息を取べからず然ば汝が往て獲ところの地において汝の神ヱホバ凡て汝が手に爲ところの事に福祥をくだしたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, '汝の神ヱホバに誓願をかけなば之か還すことを怠るべからず汝の神ヱホバかならずこれを汝に要めたまふべし怠る時は汝罪あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, '汝誓願をかけざるも罪を獲ること有じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, '汝が口より出しし事は守りて行ふべし凡て自意の禮物は汝の神ヱホバに汝が誓願し口をもて約せしごとくに行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, '汝の鄰の葡萄園に至る時汝意にまかせてその葡萄を飽まで食ふも宜し然ど器の中に取いるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'また汝の鄰の麥圃にいたる時汝手にてその穂を摘食ふも宜し然ど汝の鄰の麥圃に鎌をいるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, '人妻を取てこれを娶れる後恥べき所のこれにあるを見てこれを好まずなりたらば離縁状を書てこれが手に交しこれをその家より出すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'その婦これが家より出たる後往て他の人に嫁ぐことをせんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, '後の夫もこれを嫌ひ離縁状を書てその手にわたして之を家より出し又はこれを妻にめとれるその後の夫死るあるも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, '是は已に身を汚玷したるに因て之を出したるその先の夫ふたたびこれを妻にめとるべからず是ヱホバの憎みたまふ事なればなり汝の神ヱホバの汝に與へて產業となさしめたまふ地に汝罪を負すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, '人あらたに妻を娶りたる時は之を軍に出すべからずまた何の職務をもこれに任すべからずその人は一年家に間居してその娶れる妻を慰むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, '人その磨礱を質におくべからず是その生命をつなぐ物を質におくなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'イスラエルの子孫の中なるその兄弟を拐帶してこれを使ひまたはこれを賣る人あるを見ばその拐帶者を殺し然して汝らの中より惡を除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, '汝癩病を愼み凡て祭司たるレビ人が汝らに敎ふる所を善く守りて行ふべし即ち我が彼らに命ぜしごとくに汝ら守りて行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, '汝らがエジプトより出きたれる路にて汝の神ヱホバがミリアムに爲たまひしところの事を誌えよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, '凡て汝の鄰に物を貸あたふる時は汝みづからこれが家にいりてその質物を取べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, '汝は外に立をり汝が貸たる人その質物を外に持いだして汝に付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'その人もし困苦者ならば之が質物を留おきて睡眠に就べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'かならず日の入る頃その質物を之に還すべし然せばその人おのれの上衣をまとふて睡眠につくことを得て汝を祝せん是汝の神ヱホバの前において汝の義となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, '困苦る貧き傭人は汝の兄弟にもあれ又は汝の地にてなんぢの門の内に寄寓る他國の人にもあれ之を虐ぐべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, '當日にこれが値をはらふべし日の入るまで延すべからず其は貧き者にてその心にこれを慕へばなり恐らくは彼ヱホバに汝を訴ふるありて汝罪を獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, '父はその子等の故によりて殺さるべからず子等はその父の故によりて殺さるべからず各人おのれの罪によりて殺さるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, '汝他國の人または孤子の審判を曲べからずまた寡婦の衣服を質に取べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, '汝誌ゆべし汝はエジプトに奴隸たりしが汝の神ヱホバ汝を其處より贖ひいだしたまへり是をもて我この事をなせと汝に命ずるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, '汝田野にて穀物を刈る時もしその一束を田野に忘れおきたらば返りてこれを取べからず他國の人と孤子と寡婦とにこれを取すべし然せば汝の神ヱホバ凡て汝が手に作ところの事に祝福を降したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, '汝橄欖を打落す時は再びその枝をさがすべからずその遺れる者を他國の人と孤子と寡婦とに取すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'また葡萄園の葡萄を摘とる時はその遺れる者を再びさがすべからず他國の人と孤子と寡婦とにこれを取すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, '汝誌ゆべし汝はエジプトの國に奴隸たりしなり是をもて我この事を爲せと汝に命ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, '人と人との間に爭辯ありて來りて審判を求むる時は士師これを鞫きその義き者を義とし惡き者を惡とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'その惡き者もし鞭つべき者ならば士師これを伏せその罪にしたがひて數のごとく自己の前にてこれを扑すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'これを扑ことは四十を逾べからず若これを逾て是よりも多く扑ときは汝その汝の兄弟を賤め視にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, '穀物を碾す牛に口籠をかく可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, '兄弟ともに居んにその中の一人死て子を遺さざる時はその死たる者の妻いでて他人に嫁ぐべからず其夫の兄弟これの所に入りこれを娶りて妻となし斯してその夫の兄弟たる道をこれに盡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, '而してその婦の生ところの初子をもてその死たる兄弟の後を嗣しめその名をイスラエルの中に絶ざらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, '然どその人もしその兄弟の妻をめとることを肯ぜずばその兄弟の妻門にいたりて長老等に言べし吾夫の兄弟はその兄弟の名をイスラエルの中に興ることを肯ぜず吾夫の兄弟たる道を盡すことをせずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, '然る時はその邑の長老等かれを呼よせて諭すべし然るも彼堅く執て我はこれを娶ることを好まずと言ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'その兄弟の妻長老等の前にて彼の側にいたりこれが鞋をその足より脱せその面に唾して答て言べしその兄弟の家を興ることを肯ぜざる者には斯のごとくすべきなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'またその人の名は鞋を脱たる者の家とイスラエルの中に稱へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, '人二人あひ爭そふ時に一人の者の妻その夫を撃つ者の手より夫を救はんとて進みより手を伸てその人の陰所を執ふるあらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, '汝その婦の手を切おとすべし之を憫れみ視るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, '汝の嚢の中に一箇は大く一箇は小き二種の權衡石をいれおくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, '汝の家に一箇は大く一箇は小き二種の升斗をおくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, '唯十分なる公正き權衡を有べくまた十分なる公正き升斗を有べし然せば汝の神ヱホバの汝にたまふ地に汝の日永からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, '凡て斯る事をなす者凡て正しからざる事をなす者は汝の神ヱホバこれを憎みたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, '汝らがエジプトより出きたりし時その路においてアマレクが汝に爲たりし事を記憶よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, '即ち彼らは汝を途に迎へ汝の疲れ倦たるに乗じて汝の後なる弱き者等を攻撃り斯かれらは神を畏れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, '然ば汝の神ヱホバの汝に與へて產業となさしめたまふ地において汝の神ヱホバ汝にその周圍の敵を盡く攻ふせて安泰ならしめたまふに至らば汝アマレクの名を天が下より塗抹て之をおぼゆる者なからしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, '汝その神ヱホバの汝に與へて產業となさしめたまふ地にいりこれを獲てそこに住にいたらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, '汝の神ヱホバの汝に與へたまへる地の諸の土產の初を取て筐にいれ汝の神ヱホバのその名を置んとて選びたまふ處にこれを携へゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, '而して汝當時の祭司に詣り之にいふべし我は今日なんぢの神ヱホバに申さん我はヱホバが我らに與へんと我らの先祖等に誓ひたまひし地に至れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, '然る時は祭司汝の手よりその筐をとりて汝の神ヱホバの壇のまへに之を置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, '汝また汝の神ヱホバの前に陳て言べし我先祖は憫然なる一人のスリア人なりしが僅少の人を將てエジプトに下りゆきて其處に寄寓をりそこにて終に大にして強く人口おほき民となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, '然るにエジプト人我らに害を加へ我らを惱まし辛き力役を我らに負せたりしに因て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, '我等先祖等の神ヱホバに向ひて呼はりければヱホバわれらの聲を聽き我らの艱難と勞苦と虐遇を顧みたまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, '而してヱホバ強き手を出し腕を伸べ大なる威嚇と徴證と奇跡とをもてエジプトより我らを導きいだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'この處に我らを携へいりてこの地すなはち乳と蜜との流るる地を我らに賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'ヱホバよ今我なんぢが我に賜ひし地の產物の初を持きたれりと斯いひて汝その筐を汝の神ヱホバの前にそなへ汝の神ヱホバの前に禮拝をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, '而して汝は汝の神ヱホバの汝と汝の家に降したまへる諸の善事のためにレビ人および汝の中間なる旅客とともに樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, '第三年すなはち十に一を取の年に汝その諸の產物の什一を取りレビ人と客旅と孤子と寡婦とにこれを與へて汝の門の内に食ひ飽しめたる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, '汝の神ヱホバの前に言べし我は聖物を家より執いだしまたレビ人と客旅と孤子と寡婦とにこれを與へ全く汝が我に命じたまひし命令のごとくせり我は汝の命令に背かずまたこれを忘れざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, '我はこの聖物を喪の中に食ひし事なくをた汚穢たる身をもて之を携へ出しし事なくまた死人のためにこれを贈りし事なきなり我はわが神ヱホバの言に聽したがひて凡て汝が我に命じたまへるごとく行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, '願くは汝の聖住所なる天より臨み觀汝の民イスラエルと汝の我らに與へし地とに福祉をくだしたまへ是は我がわれらの先祖等に誓ひたまひし乳と蜜との流るる地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, '今日汝の神ヱホバこれらの法度と律法とを行ふことを汝に命じたまふ然ば汝心を盡し精心を盡してこれを守りおこなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, '今日なんぢヱホバを認めて汝の神となし且その道に歩みその法度と誡法と律法とを守りその聲に聽したがはんと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, '今日ヱホバまたその言しごとく汝を認めてその寶の民となし且汝にその諸の誡命を守れと言たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'ヱホバ汝の名譽と聲聞と榮耀とをしてその造れる諸の國の人にまさらしめたまはん汝はその神ヱホバの聖民となることその言たまひしごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'モーセ、イスラエルの長老等とともにありて民に命じて曰ふ我が今日なんぢらに命ずるこの誡命を汝ら全く守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, '汝らヨルダンを濟り汝の神ヱホバが汝に與へたまふ地にいる時は大なる石數箇を立て石灰をその上に塗り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, '旣に濟りて後この律法の諸の言語をその上に書すべし然すれば汝の神ヱホバの汝にたまふ地なる乳と蜜の流るる國に汝いるを得ること汝の先祖等の神ヱホバの汝に言たまひしごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, '即ち汝らヨルダンを濟るにおよばば我が今日なんぢらに命ずるその石をエバル山に立て石灰をその上に塗べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'また其處に汝の神ヱホバのために石の壇一座を築くべし但し之を築くには鐵の器を用ゐるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, '汝新石をもて汝の神ヱホバのその壇を築きその上にて汝の神ヱホバに燔祭を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, '汝また彼處にて酬恩祭を獻げその物を食ひて汝の神ヱホバの前に樂むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, '汝この律法の諸の言語をその石の上に明白に書すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'モーセまた祭司たるレビ人とともにイスラエルの全家に告て曰ふイスラエルよ謹みて聽け汝は今日汝の神ヱホバの民となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, '然ば汝の神ヱホバの聲に聽從ひ我が今日汝に命ずる之が誡命と法度をおこなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'その日にモーセまた民に命じて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '汝らがヨルダンを渡りし後是らの者ゲリジム山にたちて民を祝すべし即ちシメオン、レビ、ユダ、イツサカル、ヨセフおよびベニヤミン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'また是らの者はエバル山にたちて呪詛ことをすべし即ちルベン、ガド、アセル、ゼブルン、ダンおよびナフタリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'レビ人大聲にてイスラエルの人々に告て言べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '偶像は工人の手の作にしてヱホバの憎みたまふ者なれば凡てこれを刻みまたは鋳造りて密に安置く人は詛はるべしと民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'その父母を軽んずる者は詛はるべし民みな對てアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'その鄰の地界を侵す者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '盲者をして路に迷はしむる者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '客旅孤子および寡婦の審判を枉る者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'その父の妻と寝る者はその父を辱しむるなれば詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '凡て獣畜と交る者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'その父の女子またはその母の女子たる己の姉妹と寝る者は詛はるべし民みな對へてアーメンとふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'その妻の母と寝る者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '暗の中にその鄰を撃つ者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '報酬をうけて無辜者を殺してその血を流す者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'この律法の言を守りて行はざる者は詛はるべし民みな對へてアーメンといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '汝もし善く汝の神ヱホバの言に聽したがひ我が今日なんぢに命ずるその一切の誡命を守りて行はば汝の神ヱホバ汝をして地の諸の國人の上に立しめたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, '汝もし汝の神ヱホバの言に聽したがふ時はこの諸の福祉汝に臨み汝におよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, '汝は邑の内にても福祉を得田野にても福祉を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'また汝の胎の產汝の地の產汝の家畜の產汝の牛の產汝の羊の產に福祉あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'また汝の飯籃と汝の捏盤に福祉あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, '汝は入にも福祉を得出るにも福祉を得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, '汝の敵起て汝を攻るあればヱホバ汝をして之を打敗らしめたまふべし彼らは一條の路より攻きたり汝の前にて七條の路より逃はしらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'ヱホバ命じて福祉を汝の倉庫に降しまた汝が手にて爲ところの事に降し汝の神ヱホバの汝に與ふる地においてヱホバ汝を祝福たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, '汝もし汝の神ヱホバの誡命を守りてその道に歩まばヱホバ汝に誓ひしごとく汝を立て己の聖民となしたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, '然る時は地の民みな汝がヱホバの名をもて稱へらるるを視て汝を畏れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'ヱホバが汝に與へんと汝の先祖等に誓ひたまひし地においてヱホバ汝の佳物すなはち汝の身の產と汝の家畜の產と汝の地の產とを饒にしたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'ヱホバその寶の蔵なる天を啓き雨をその時にしたがびて汝の地に降し汝の手の諸の行爲に祝福をたまはん汝は許多の國々の民に貸ことをなすに至らん借ことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'ヱホバ汝をして首とならしめたまはん尾とはならしめたまはじ汝は只上におらん下には居じ汝もし我が今日汝に命ずる汝の神ヱホバの誡命に聽したがひてこれを守りおこなはばかならず斯のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, '汝わが今日汝に命ずるこの言語を離れ右または左にまがりて他の神々にしたがひ事ふることをすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, '汝もし汝の神ヱホバの言に聽したがはず我が今日なんぢに命ずるその一切の誡命と法度とを守りおこなはずば此もろもろの呪詛汝に臨み汝におよぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, '汝は邑の内にても詛はれ田野にても詛はれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'また汝の飯籃も汝の捏盤も詛はれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, '汝の胎の產汝の地の產汝の牛の產汝の羊の產も詛はれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, '汝は入にも詛はれ出るにも詛はれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'ヱホバ汝をしてその凡て手をもて爲ところにおいて呪詛と恐懼と鑓責を蒙らしめたまふべければ汝は滅びて速かに亡はてん是は汝惡き事をおこなひて我を棄るによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'ヱホバ疫病を汝の身に着せて遂に汝をその往て得るとこるの地より滅ぼし絶たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'ヱホバまた癆瘵と熱病と傷寒と瘧疾と刀劍と枯死と汚腐とをもて汝を撃なやましたまふべし是らの物汝を追ひ汝をして滅びうせしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, '汝の頭の上なる天は銅のごとくになり汝の下なる地は鐵のごとくになるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'ヱホバまた雨のかはりに沙と灰とを汝の地に降せたまはん是らの物天より汝の上に下りて遂に汝を滅ぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'ヱホバまた汝をして汝の敵に打敗られしめたまふべし汝は彼らにむかひて一條の路より進み彼らの前にて七條の路より逃はしらん而して汝はまた地の諸の國にて虐遇にあはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, '汝の死屍は空の諸の鳥と地の獣の食とならん然るもこれを逐はらふ者あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'ヱホバまたエジプトの瘍瘡と痔と癰と癢とをもて汝を撃たまはん汝はこれより愈ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'ヱホバまた汝を撃ち汝をして狂ひ且目くらみて心に驚き悸れしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, '汝は瞽者が暗にたどるごとく眞晝においても尚たどらん汝その途によりて福祉を得ることあらじ汝は只つねに虐げられ掠められんのみ汝を救ふ者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, '汝妻を娶る時は他の人これと寝ん汝家を建るもその中に住ことを得ず葡萄園を作るもその葡萄を摘とることを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, '汝の牛汝の目の前に宰らるるも汝は之を食ふことを得ず汝の驢馬は汝の目の前にて奪ひさられん再び汝にかへることあらじ又なんぢの羊は汝の敵の有とならん然ど汝にはこれを救ふ道あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, '汝の男子と汝の女子は他邦の民の有とならん汝は終日これを慕ひ望みて目を喪ふに至らん汝の手には何の力もあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, '汝の地の產物および汝の努苦て得たる物は汝の識ざる民これを食はん汝は只つねに虐げられ窘められん而已');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, '汝はその目に見るところの事によりて心狂ふに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'ヱホバ汝の膝と脛とに惡くして愈ざる瘍瘡を生ぜしめて終に足の蹠より頭の頂にまでおよぼしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'ヱホバ汝と汝が立たる王とを携へて汝も汝の先祖等も知ざりし國々に移し給はん汝は其處にて木または石なる他の神々に事ふるあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, '汝はヱホバの汝を遣はしたまふ國々にて人の詑異む者となり諺語となり諷刺とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, '汝は多分の種を田野に携へ出すもその刈とるとこるは少かるべし蝗これを食ふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, '汝葡萄園を作りてこれに培ふもその酒を飮ことを得ずまたその果を斂むることを得じ蟲これを食ふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, '汝の國には遍く橄欖の樹あらん然ど汝はその油を身に膏ことを得じ其果みな堕べければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, '汝男子女子を擧くるもこれを汝の有とすることを得じ皆擄へゆかるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, '汝の諸の樹および汝の地の產物はみな蝗これを取て食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, '汝の中間にある他國の人はますます高くなりゆきて汝の上に出で汝はますます卑くなりゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, '彼は汝に貸ことをせん汝は彼に貸ことを得じ彼は首となり汝は尾とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'この諸の災禍汝に臨み汝を追ひ汝に及びてつひに汝を滅ぼさん是は汝その神ヱホバの言に聽したがはず其なんぢに命じたまへる誡命と法度とを守らざるによるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, '是等の事は恒になんぢと汝の子孫の上にありて徴證となり人を驚かす者となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'なんぢ萬の物の豊饒なる中にて心に歓び樂みて汝の神ヱホバに事へざるに因り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, '饑ゑ渇きかつ裸になり萬の物に乏しくしてヱホバの汝に攻きたらせたまふところの敵に事ふるに至らん彼鐵の軛をなんぢの頸につけて遂に汝をほろぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, '即ちヱホバ遠方より地の極所より一の民を鵰の飛がごとくに汝に攻きたらしめたまはん是は汝がその言語を知ざる民');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'その面の猛惡なる民にして老たる者の身を顧みず幼稚者を憐まず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, '汝の家畜の產と汝の地の產を食ひて汝をほろぼし穀物をも酒をも油をも牛の產をも羊の產をも汝のために遺さずして終に全く汝を滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'その民は汝の全國において汝の一切の邑々を攻圍み遂にその汝が賴む堅固なる高き石垣をことごとく打圮し汝の神ヱホバの汝にたまへる國の中なる一切の邑々をことごとく攻圍むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, '汝は敵に圍まれ烈しく攻なやまさるるによりて終にその汝の神ヱホバに賜はれる汝の胎の產なる男子女子の肉を食ふにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, '汝らの中の柔生育にして軟弱なる男すらもその兄弟とその懐の妻とその遺れる子女とを疾視');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, '自己の食ふその子等の肉をこの中の誰にも與ふることを好まざらん是は汝の敵汝の一切の邑々を圍み烈しく汝を攻なやまして何物をも其人に遺さざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, '又汝らの中の柔生育にして繊弱なる婦女すなはちその柔生育にして繊弱なるがために足の蹠を土につくることをも敢てせざる者すらもその懐の夫とその男子とその女子とを疾視');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, '己の足の間より出る胞衣と己の產ところの子を取て密にこれを食はん是は汝の敵なんぢの邑々を圍み烈しくこれを攻なやますによりて何物をも得ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, '汝もしこの書に記したるこの律法の一切の言を守りて行はず汝の神ヱホバと云榮ある畏るべき名を畏れずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'ヱホバ汝の災禍と汝の子孫の災禍を烈しくしたまはん其災禍は大にして久しくその疾病は重くして久しかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'ヱホバまた汝が懼れし疾病なるエジプトの諸の疾病を持きたりて汝の身に纏ひ附しめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'また此律法の書に載ざる諸の疾病と諸の災害を汝の滅ぶるまでヱホバ汝に降したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, '汝らは空の星のごとくに衆多かりしも汝の神ヱホバの言に聽したがはざるによりて殘り寡に打なさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'ヱホバさきに汝らを善して汝等を衆くすることを喜びしごとく今はヱホバ汝らを滅ぼし絶すことを喜びたまはん汝らは其往て獲ところの地より抜さらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'ヱホバ地のこの極よりかの極までの國々の中に汝を散したまはん汝は其處にて汝も汝の先祖等も知ざりし木または石なる他の神々に事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'その國々の中にありて汝は安寧を得ずまた汝の足の跖を休むる所を得じ其處にてヱホバ汝をして心慄き目昏み精神亂れしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, '汝の生命は細き糸に懸るが如く汝に見ゆ汝は夜晝となく恐怖をいだき汝の生命おぼつかなしと思はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, '汝心に懼るる所によりまた目に見る所によりて朝においては言ん嗚呼夕ならば善らんとまた夕においては言ん嗚呼朝ならば善らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'ヱホバなんぢを舟にのせ彼の昔わが汝に告て汝は再びこれを見ることあらじと言たるその路より汝をエジプトに曳ゆきたまはん彼處にて人汝らを賣て汝らの敵の奴婢となさん汝らを買ふ人もあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'ヱホバ、モーセに命じモアブの地にてイスラエルの子孫と契約を結ばしめたまふその言は斯のごとし是はホレブにてかれらと結びし契約の外なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'モーセ、イスラエルの全家を呼あつめて之に言けるは汝らはヱホバがエジプトの地において汝らの目の前にてパロとその臣下とその全地とに爲たまひし一切の事を觀たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, '即ち其大なる試煉と徴證と大なる奇跡とを汝目に觀たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, '然るにヱホバ今日にいたるまで汝らの心をして悟ることなく目をして見ることなく耳をして聞ことなからしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, '四十年の間われ汝らを導きて曠野を通りしが汝らの身の衣服は古びず汝の足の鞋は古びざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, '汝らはまたパンをも食はず葡萄酒をも濃酒をも飮ざりき斯ありて汝らは我が汝らの神ヱホバなることを知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, '汝らこの處に來りし時ヘシボンの王シホンおよびバシヤンの王オグ我らを迎へて戰ひしが我らこれを打敗りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'その地を取りこれをルベン人とガド人とマナセの半支派とに與へて產業となさしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, '然ば汝らこの契約の言を守りてこれを行ふべし然れば汝らの凡て爲ところに祥あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, '汝らみな今日なんぢらの神ヱホバの前に立つ即ち汝らの首領等なんぢらの支派なんぢらの長老等および汝らの牧司等などイスラエルの一切の人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, '汝らの小き者等汝らの妻ならびに汝らの營の中にをる客旅など凡て汝のために薪を割る者より水を汲む者にいたるまで皆ヱホバの前に立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, '汝の神ヱホバの契約に入んとし又汝の神ヱホバの汝にむかひて今日なしたまふところの誓に入んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, '然ばヱホバさきに汝に言しごとくまた汝の先祖アブラハム、イサク、ヤコブに誓ひしごとく今日なんぢを立て己の民となし己みづから汝の神となりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, '我はただ汝らと而已此契約と誓とを結ぶにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, '今日此にてわれらの神ヱホバの前に我らとともにたちをる者ならびに今日われらとともに此にたち居ざる者ともこれを結ぶなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, '我らは如何にエジプトの地に住をりしか如何に國々を通り來りしか汝らこれを知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, '汝らはまた木石金銀にて造れる憎むべき物および偶像のその國々にあるを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, '然ば汝らの中に今日その心に我らの神ヱホバを離れて其等の國々の神に往て事ふる男女宗族支派などあるべからず又なんぢらの中に葶藶または茵蔯を生ずる根あるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, '斯る人はこの呪詛の言を聞もその心に自ら幸福なりと思ひて言ん我はわが心を剛愎にして事をなすも尚平安なり終には酔飽る者をもて渇ける者を除くにいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, '是のごとき人はヱホバかならず之を赦したまはじ還てヱホバの忿怒と嫉妬の火これが上に燃えまたこの書にしるしたる災禍みなその身に加はらんヱホバつひにその人の名を天が下より抹さりたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'ヱホバすなはちイスラエルの諸の支派の中よりその人を分ちてこれに災禍を下しこの律法の書にしるしたる契約中の諸の呪詛のごとくしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, '汝等の後に起る汝らの子孫の代の人および遠き國より來る客旅この地の災禍を見またヱホバがこの地に流行せたまふ疾病を見て言ところあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, '即ち彼ら見るにその全地は硫黄となり鹽となり且燒土となりて種も蒔れず產する所もなく何の草もその上に生せずして彼の昔ヱホバがその震怒と忿恨とをもて毀ちたましソドム、ゴモラ、アデマ、ゼポイムの毀たれたると同じかるべければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, '彼らも國々の人もみな言んヱホバ何とて斯この地になしたるやこの烈しき大なる震怒は何事ぞやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'その時人應へて曰ん彼らはその先祖たちの神ヱホバがエジプトの地より彼らを導きいだして彼らと結びたるその契約を棄て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, '往て己の識ずまた授らざる他の神々に事へてこれを拝みたるが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, '是をもてヱホバこの地にむかひて震怒を發しこの書にしるしたる諸の災禍をこれに下し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, '而してヱホバ震怒と忿恨と大なる憤怨をもて彼らをこの地より抜とりてこれを他の國に投やれりその状今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, '隠微たる事は我らの神ヱホバに屬する者なりまた顯露されたる事は我らと我らの子孫に屬し我らをしてこの律法の諸の言を行はしむる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, '我が汝らの前に陳たるこの諸の祝福と呪詛の事すでに汝に臨み汝その神ヱホバに逐やられたる諸の國々において此事を心に考ふるにいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, '汝と汝の子等ともに汝の神ヱホバに起かへり我が今日なんぢに命ずる所に全たく循がひて心をつくし精神をつくしてヱホバの言に聽したがはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, '汝の神ヱホバ汝の俘擄を解て汝を憐れみ汝の神ヱホバ汝を顧みその汝を散しし國々より汝を集めたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, '汝たとひ天涯に逐やらるるとも汝の神ヱホバ其處より汝を集め其處より汝を携へかへりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, '汝の神ヱホバ汝をしてその先祖の有ちし地に歸らしめたまふて汝またこれを有つにいたらんヱホバまた汝を善し汝を増て汝の先祖よりも衆からしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, '而して汝の神ヱホバ汝の心と汝の子等の心に割禮を施こし汝をして心を盡し精神をつくして汝の神ヱホバを愛せしめ斯して汝に生命を得させたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, '汝の神ヱホバまた汝の敵と汝を惡み攻る者とにこの諸の災禍をかうむらせたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, '然ど汝は再びヱホバの言に聽したがひ我が今日なんぢに命ずるその一切の誡命を行ふにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, '然る時は汝の神ヱホバ汝をして汝が手をかくる諸の物と汝の胎の產と汝の家畜の產と汝の地の產に富しめて汝を善したまはん即ちヱホバ汝の先祖たちを悦こびしごとく再び汝を悦こびて汝を善したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, '是は汝その神ヱホバの言に聽したがひ此律法の書にしるされたる誡命と法度を守り心をつくし精神を盡して汝の神ヱホバに歸するによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, '我が今日なんぢに命ずる誡命は汝が理會がたき者にあらずまた汝に遠き者にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, '是は天に在ならねば汝は誰か我らのために天にのぼりてこれを我らに持くだり我らにこれを聞せて行はせんかと曰ふにおよばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'また是は海の外にあるならねば汝は誰か我らのために海をわたりゆきてこれを我らに持きたり我らにこれを聞せて行はせんかと曰におよばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, '是言は甚だ汝に近くして汝の口にあり汝の心にあれば汝これを行ふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, '視よ我今日生命と福徳および死と災禍を汝の前に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, '即ち我今日汝にむかひて汝の神ヱホバを愛しその道に歩みその誡命と法度と律法とを守ることを命ずるなり然なさば汝生ながらへてその數衆くならんまた汝の神ヱホバ汝が往て獲るところの地にて汝を祝福たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, '然ど汝もし心をひるがへして聽從がはず誘はれて他の神々を拝みまたこれに事へなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, '我今日汝らに告ぐ汝らは必ず滅びん汝らはヨルダンを渡りゆきて獲るところの地にて汝らの日を永うすることを得ざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, '我今日天と地を呼て證となす我は生命と死および祝福と呪詛を汝らの前に置り汝生命をえらぶべし然せば汝と汝の子孫生存らふることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, '即ち汝の神ヱホバを愛してその言を聽き且これに附從がふべし斯する時は汝生命を得かつその日を永うすることを得ヱホバが汝の先祖アブラハム、イサク、ヤコブに與へんと誓ひたまひし地に住ことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, '茲にモーセ往てイスラエルの一切の人にこの言をのべたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, '即ちこれに言けるは我は今日すでに百二十歳なれば最早出入をすること能はず且またヱホバ我にむかひて汝はこのヨルダンを濟ることを得ずと宣へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, '汝の神ヱホバみづから汝に先だちて渡りゆき汝の前よりこの國々の人を滅ぼしさりて汝にこれを獲させたまふべしまたヱホバのかつて宣まひしごとくヨシユア汝を率ゐて濟るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'ヱホバさきにアモリ人の王シホンとオグおよび之が地になしたる如くまた彼らにも爲てこれを滅ぼしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'ヱホバかれらを汝らの前に付したまふべければ汝らは我が汝らに命ぜし一切の命令のごとくこれに爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, '汝ら心を強くしかつ勇め彼らを懼るる勿れ彼らの前に慄くなかれ其は汝の神ヱホバみづから汝とともに往きたまへばなり必ず汝を離れず汝を棄たまはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, '斯てモーセ、ヨシユアを呼びイスラエルの一切の人の目の前にてこれに言ふ汝はこの民とともに往き在昔ヱホバがかれらの先祖たちに與へんと誓ひたまひし地に入るべきが故に心を強くしかつ勇め汝彼らにこれを獲さすることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'ヱホバみづから汝に先だちて往きたまはんまた汝とともに居り汝を離れず汝を棄たまはじ懼るる勿れ驚くなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'モーセこの律法を書きヱホバの契約の櫃を舁ところのレビの子孫たる祭司およびイスラエルの諸の長老等に授けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, '而してモーセ彼らに命じて言けるは七年の末年すなはち放釋の年の節期にいたり結茅の節において');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'イスラエルの人皆なんぢの神ヱホバの前に出んとてヱホバの選びたまふ處に來らんその時に汝イスラエルの一切の人の前にこの律法を誦てこれに聞すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, '即ち男女子等および汝の門の内なる他國の人など一切の民を集め彼らをしてこれを聽かつ學ばしむべし然すれば彼等汝らの神ヱホバを畏れてこの律法の言を守り行はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'また彼らの子等のこれを知ざる者も之を聞て汝らの神ヱホバを畏るることを學ばん汝らそのヨルダンを濟りゆきて獲ところの地に存ふる日の間つねに斯すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'ヱホバまたモーセに言たまひけるは視よ汝の死る日近しヨシユアを召てともに集會の幕屋に立て我かれに命ずるところあらんとモーセとヨシユアすなはち往て集會の幕屋に立けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'ヱホバ幕屋において雲の柱の中に現はれたまへりその雲の柱は幕屋の門口の上に駐まれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'ヱホバ、モーセに言たまひけるは汝は先祖たちとともに寝らん此民は起あがりその往ところの他國の神々を慕ひて之と姦淫を行ひかつ我を棄て我が彼らとむすびし契約を破らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'その日には我かれらにむかひて怒を發し彼らを棄て吾面をかれらに隱すべければ彼らは呑ほろぼされ許多の災害と艱難かれらに臨まん是をもてその日に彼ら言ん是等の災禍の我らにのぞむは我らの神ヱホバわれらとともに在さざるによるならずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, '然るも彼ら諸の惡をおこなひて他の神々に歸するによりて我その日にはかならず吾面をかれらに隱さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, '然ば汝ら今この歌を書きイスラエルの子孫にこれを敎へてその口に念ぜしめ此歌をしてイスラエルの子孫にむかひて我の證とならしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, '我かれらの先祖たちに誓ひし乳と蜜の流るる地にかれらを導きいらんに彼らは食ひて飽き肥太るにおよばば翻へりて他の神々に歸してこれに事へ我を軽んじ吾契約を破らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, '而して許多の災禍と艱難彼らに臨むにいたる時はこの歌かれらに對ひて證をなす者とならん其はこの歌かれらの口にありて忘るることなかるべければなり我いまだわが誓ひし地に彼らを導きいらざるに彼らは早く已に思ひ量る所あり我これを知ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'モーセすなはちその日にこの歌を書てこれをイスラエルの子孫に敎へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'ヱホバまたヌンの子ヨシユアに命じて曰たまはく汝はイスラエルの子孫を我が其に誓ひし地に導きいるべきが故に心を強くしかつ勇め我なんぢとともに在べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'モーセこの律法の言をことごとく書に書しるすことを終たる時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'モーセ、ヱホバの契約の櫃を舁ところのレビ人に命じて言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'この律法の書をとりて汝らの神ヱホバの契約の櫃の傍にこれを置き之をして汝にむかひて證をなす者たらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, '我なんぢの悖る事と頑梗なるとを知る見よ今日わが生存へて汝らとともにある間すら汝らはヱホバに悖れり况てわが死たる後においてをや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, '汝らの諸支派の長老等および牧伯たちを吾許に集めよ我これらの言をかれらに語り聞せ天と地とを呼てかれらに證をなさしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, '我しる我が死たる後には汝ら必らず惡き事を行ひ我が汝らに命ぜし道を離れん而して後の日に災害なんぢらに臨まん是なんぢらヱホバの惡と觀たまふ事をおこなひ汝らの手の行爲をもてヱホバを怒らするによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'かくてモーセ、イスラエルの全會衆にこの歌の言をことごとく語り聞せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '天よ耳を傾むけよ我語らん地よ吾口の言を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'わが敎は雨の降るがごとし吾言は露のおくがごとく靀の若艸の上にふるごとく細雨の靑艸の上にくだるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, '我はヱホバの御名を頌揚ん我らの神に汝ら榮光を歸せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'ヱホバは磐にましましてその御行爲は完くその道はみな正しまた眞實ある神にましまして惡きところ無し只正くして直くいます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, '彼らはヱホバにむかひて惡き事をおこなふ者にてその子にはあらず只これが玷となるのみ其人と爲は邪僻にして曲れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, '愚にして智慧なき民よ汝らがヱホバに報ゆること是のごとくなるかヱホバは汝の父にして汝を贖ひまた汝を造り汝を建たまはずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, '昔の日を憶え過にし世代の年を念へよ汝の父に問べし彼汝に示さん汝の中の年老に問べし彼ら汝に語らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, '至高者人の子を四方に散して萬の民にその產業を分ちイスラエルの子孫の數に照して諸の民の境界を定めたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'ヱホバの分はその民にしてヤユブはその產業たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'ヱホバこれを荒野の地に見これに獣の吼る曠野に遇ひ環りかこみて之をいたはり眼の珠のごとくにこれを護りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, '鵰のその巣雛を喚起しその子の上に翺翔ごとくヱホバその羽を展て彼らを載せその翼をもてこれを負たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'ヱホバは只独にてかれを導きたまへり別神はこれとともならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'ヱホバかれに地の高處を乗とほらせ田園の產物を食はせ石の中より蜜を吸しめ磐の中より油を吸しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, '牛の乳 羊の乳 羔羊の脂 バシヤンより出る牡羊 牡山羊および小麥の最も佳き者をこれに食はせたまひき汝はまた葡萄の汁の紅き酒を飮り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, '然るにヱシユルンは肥て踢ことを爲す汝は肥太りて大きくなり己を造りし神を棄て己が救拯の磐を軽んず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, '彼らは別神をもて之が嫉妬をおこし憎むべき者をもて之が震怒を惹く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, '彼らが犠牲をささぐる者は鬼にして神にあらず彼らが識ざりし鬼神近頃新に出たる者汝らの遠つ親の畏まざりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, '汝を生し磐をば汝これを棄て汝を造りし神をば汝これを忘る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'ヱホバこれを見その男子女子を怒りてこれを棄たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'すなはち曰たまはく我わが面をかれらに隱さん我かれらの終を觀ん彼らはみな背き悖る類の者眞實あらざる子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, '彼らは神ならぬ者をもて我に嫉妬を起させ虚き者をもて我を怒らせたれば我も民ならぬ者をもて彼らに嫉妬を起させ愚なる民をもて彼らを怒らせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, '即ちわが震怒によりて火燃いで深き陰府に燃いたりまた地とその產物とを燒つくし山々の基をもやさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, '我禍災をかれらの上に積かさね吾矢をかれらにむかひて射つくさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, '彼らは饑て痩おとろへ熱の病患と惡き疫とによりて滅びん我またかれらをして獣の歯にかからしめ地に匍ふ者の毒にあたらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, '外には劒内には恐惶ありて少き男をも少き女をも幼兒をも白髮の人をも滅ぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, '我は曰ふ我彼等を吹掃ひ彼らの事をして世の中に記憶らるること無らしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, '然れども我は敵人の怒を恐る即ち敵人どれを見あやまりて言ん我らの手能くこれを爲り是はすべてヱホバの爲るにあらずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, '彼らはまつたく智慧なき民なりその中には知識ある者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, '嗚呼彼らもし智慧あらば之を了りてその身の終を思慮らんものを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, '彼らの磐これを賣ずヱホバごれを付さずば爭か一人にて千人を逐ひ二人にて萬人を敗ることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, '彼らの磐は我らの磐にしかず我らの敵たる者等も然認めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, '彼らの葡萄の樹はソドムの葡萄の樹またゴモラの野より出たる者その葡萄は毒葡萄その球は苦し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'その葡萄酒は蛇の毒のごとく蝮の惡き毒のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, '是は我の許に蓄へあり我の庫に封じこめ有にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, '彼らの足の躚かん時に我仇をかへし應報をなさんその災禍の日は近く其がために備へられたる事は迅速にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'ヱホバつひにその民を鞫きまたその僕に憐憫をくはへたまはん其は彼らの力のすでに去うせて繋がれたる者も繋がれざる者もあらずなれるを見たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'ヱホバ言たまはん彼らの神々は何處にをるや彼らが賴める磐は何處ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, '即ちその犠牲の膏油を食ひその灌祭の酒を飮たる者は何處にをるや其等をして起て汝らを助けしめ汝らを護しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, '汝ら今觀よ我こそは彼なり我の外には神なし殺すこと活すこと撃こと愈すことは凡て我是を爲す我手より救ひ出すことを得る者あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, '我天にむかひて手をあげて言ふ我は永遠に活く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, '我わが閃爍く刃を磨ぎ審判をわが手に握る時はかならず仇をわが敵にかへし我を惡む者に返報をなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, '我わが箭をして血に酔しめ吾劍をして肉を食しめん即ち殺るる者と擄らるる者の血を之に飮せ敵の髮おほき首の肉をこれに食はせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, '國々の民よ汝らヱホバの民のために歓悦をなせ其はヱホバその僕の血のために返報をなしその敵に仇をかへしその地とその民の汚穢をのぞきたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'モーセ、ヌンの子ヨシユアとともに到りてこの歌の言をことごとく民に誦きかせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'モーセこの言語をことごとくイスラエルの一切の人に告をはりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'これに言けるは我が今日なんぢらに對ひて證するこの一切の言語を汝ら心に蔵め汝らの子等にこの律法の一切の言語を守りおこなふことを命ずべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, '抑この言は汝らには虚しき言にあらず是は汝らの生命なりこの言によりて汝らはそのヨルダンを濟りゆきて獲ところの地にて汝らの生命を永うすることを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'この日にヱホバ、モーセに告て言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '汝ヱリコに對するモアブの地のアバリム山に登りてネボ山にいたり我がイスラエルの子孫にあたへて產業となさしむるカナンの地を觀わたせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, '汝はその登れる山に死て汝の民に列ならん是汝の兄弟アロンがホル山に死てその民に列りしごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, '是は汝らチンの曠野なるカデシのメリバの水の邊においてイスラエルの子孫の中間にて我に悖りイスラエルの子孫の中に我の聖きことを顯さざりしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, '然ども汝は我がイスラエルの子孫に與ふる地を汝の前に觀わたすことを得ん但しその地には汝いることを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, '神の人モーセその死る前にイスラエルの子孫を祝せりその祝せし言は是のごとし云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'ヱホバ、シナイより來りセイルより彼らにむかひて昇りバランの山より光明を發ちて出で千萬の聖者の中間よりして格りたまへりその右の手には輝やける火ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'ヱホバは民を愛したまふ其聖者は皆その手にあり皆その足下に坐りその言によりて起あがる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'モーセわれらに律法を命ぜり是はヤコブの會衆の產業たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, '民の首領等イスラエルの諸の支派あひ集れる時に彼はヱシユルンの中に王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'ルベンは生ん死はせじ然どその人數は寡少ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'ユダにつきては斯いふヱホバよユダの聲を聽きこれをその民に引かへしたまへ彼はその手をもて己のために戰はん願くは汝これを助けてその敵にあたらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'レビについては言ふ汝のトンミムとウリムは汝の聖人に歸す汝かつてマツサにて彼を試みメリバの水の邊にてかれと爭へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, '彼はその父またはその母につきて言り我はこれを見ずと又彼は自己の兄弟を認ずまた自己の子等を顧みざりき是はなんぢの言に遵がひ汝の契約を守りてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, '彼らは汝の式例をヤコブに敎へ汝の律法をイスラエルに敎へ又香を汝の鼻の前にそなへ燔祭を汝の壇の上にささぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'ヱホバよ彼の所有を祝し彼が手の作爲を悦こびて納れたまへ又起てこれに逆らふ者とこれを惡む者との腰を摧きて復起あがることあたはざらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'ベニヤミンについては言ふヱホバの愛する者安然にヱホバとともにあり日々にその庇護をかうむりてその肩の間に居ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'ヨセフについては言ふ願くはその地ヱホバの祝福をかうむらんことを即ち天の寶物なる露淵の底なる水');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, '日によりて產する寶物月によりて生ずる寶物');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, '古山の嶺の寶物老嶽の寶物');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, '地の寶物地の中の產物および柴の中に居たまひし者の恩惠などヨセフの首に臨みその兄弟と別になりたる者の頂に降らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, '彼の牛の首出はその身に榮光ありてその角は兕の角のごとく之をもて國々の民を衝たふして直に地の四方の極にまで至る是はエフライムの萬々是はマナセの千々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'ゼブルンについては言ふゼブルンよ汝は外に出て快樂を得よイツサカルよ汝は家に居て快樂を得よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, '彼らは國々の民を山に招き其處にて義の犠牲を献げん又海の中に盈る物を得て食ひ沙の中に蔵れたる物を得て食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'ガドについては言ふガドをして大ならしむる者は讃べき哉ガドは獅子のごとくに伏し腕と首の頂とを掻裂ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, '彼は初穂の地を自己のために選べり其處には大將の分もこもれり彼は民の首領等とともに至りイスラエルとともにヱホバの公義と審判とをなこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'ダンについては言ふダンは小獅子のごとくバシヤンより跳り出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'ナフタリについては言ふナフタリよ汝は大に福祉をかうむりヱホバの恩惠にうるほふて西と南の部を獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'アセルについては言ふアセルは他の子等よりも幸福なりまた其兄弟等にこえて惠まれその足を膏の中に浸さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, '汝の門閂は鐵のごとく銅のごとし汝の能力は汝が日々に需むるところに循はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'ヱシユルンよ全能の神のごとき者は外に無し是は天に乗て汝を助け雲に駕てその威光をあらはしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, '永久に在す神は住所なり下には永遠の腕あり敵人を汝の前より驅はらひて言たまふ滅ぼせよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'イスラエルは安然に住をりヤコブの泉は穀と酒との多き地に獨り在らんその天はまた露をこれに降すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'イスラエルよ汝は幸福なり誰か汝のごとくヱホバに救はれし民たらんヱホバは汝を護る楯汝の榮光の劍なり汝の敵は汝に諂ひ服せん汝はかれらの高處を踐ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, '斯てモーセ、モアブの平野よりネボ山にのぼりヱリコに對するピスガの嶺にいたりければヱホバ之にギレアデの全地をダンまで見し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'ナフタリの全部エフライムとマナセの地およびユダの全地を西の海まで見し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, '南の地と棕櫚の邑なるヱリコの谷の原をゾアルまで見したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, '而してヱホバかれに言たまひけるは我がアブラハム、イサク、ヤコブにむかひ之を汝の子孫にあたへんと言て誓ひたりし地は是なり我なんぢをして之を汝の目に觀ことを得せしむ然ど汝は彼處に濟りゆくことを得ずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, '斯の如くヱホバの僕モーセはヱホバの言の如くモアブの地に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'ヱホバ、ベテペオルに對するモアブの地の谷にこれを葬り給へり今日までその墓を知る人なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'モーセはその死たる時百二十歳なりしがその目は曚まずその氣力は衰へざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'イスラエルの子孫モアブの地において三十日のあひだモーセのために哭泣をなしけるがモーセのために哭き哀しむ日つひに滿り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'ヌンの子ヨシユアは心に智慧の充る者なりモーセその手をこれが上に按たるによりて然るなりイスラエルの子孫は之に聽したがひヱホバのモーセに命じたまひし如くおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'イスラエルの中にはこの後モーセのごとき預言者おこらざりきモーセはヱホバが面を對せて知たまへる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, '即ちヱホバ、エジプトの地においてかれをパロとその臣下とその全地とにつかはして諸々の徴證と奇蹟を行はせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'またイスラエルの一切の人の目の前にてモーセその大なる能力をあらはし大なる畏るべき事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'ヱホバの僕モーセの死し後ヱホバ、モーセの從者ヌンの子ヨシユアに語りて言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'わが僕モーセは已に死り然ば汝いま此すべての民とともに起てこのヨルダンを濟り我がイスラエルの子孫に與ふる地にゆけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, '凡そ汝らが足の蹠にて踏む所は我これを盡く汝らに與ふ我が前にモーセに語し如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, '汝らの疆界は荒野および此レバノンより大河ユフラテ河に至りてヘテ人の全地を包ね日の沒る方の大海に及ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, '汝が生ながらふる日の間なんぢに當る事を得る人なかるべし我モーセと偕に在しごとく汝と偕にあらん我なんぢを離れず汝を棄じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, '心を強くしかつ勇め汝はこの民をして我が之に與ふることをその先祖等に誓ひたりし地を獲しむべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, '惟心を強くし勇み勵んで我僕モーセが汝に命ぜし律法をことごとく守りて行へ之を離れて右にも左にも曲るなかれ然ば汝いづくに往ても利を得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'この律法の書を汝の口より離すべからず夜も晝もこれを念ひて其中に録したる所をことごとく守りて行へ然ば汝の途福利を得汝かならず勝利を得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, '我なんぢに命ぜしにあらずや心を強くしかつ勇め汝の凡て往く處にて汝の神ヱホバ偕に在せば懼るる勿れ戰慄なかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, '茲にヨシユア民の有司等に命じて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '陣營の中を行めぐり民に命じて言へ汝等糧食を備へよ三日の内に汝らは此ヨルダンを濟り汝らの神ヱホバが汝らに與へて獲させんとしたまふ地を獲んために進みゆくべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'ヨシユアまたルベン人ガド人およびマナセの支派の半に告て言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'ヱホバの僕モーセ前に汝らに命じて言り汝らの神ヱホバ今なんぢらに安息を賜へり亦この地を汝らに與へたまふべしと汝らこの言詞を記念よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, '汝らの妻子および家畜はモーセが汝らに與へしヨルダンの此旁の地に止まるべし然ど汝ら勇者は皆身をよろひて兄弟等の先にたち進濟りて之を助けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, '而してヱホバが汝らに賜ひし如くなんぢらの兄弟等にも安息を賜ふにおよばば又かれらもなんぢらの神ヱホバの與へたまふ地を獲るにおよばば汝らヱホバの僕モーセより與へられしヨルダンの此旁日の出る方なる己が所有の地に還りてこれを保つべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, '彼らヨシユアに應て言ふ汝が我等に命ぜし所は我等盡く爲べし凡て汝が我らを遣す處には我ら往べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, '我らは一切の事モーセに聽したがひし如く亦なんぢに聽したがはん唯ねがはくは汝の神ヱホバ、モーセと偕にいまししごとく汝と偕に在さんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, '誰にもあれ汝が命令に背き凡て汝が命ずるところの言に聽したがはざる者あらば之を殺すべし唯なんぢ心を強くしかつ勇め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, '茲にヌンの子ヨシユア、シツテムより潜かに二人の間者を發し之にいひけるは往てかの地およびヱリコを窺ひ探れ乃ち彼ら往て妓婦ラハブと名づくる者の家に入て其處に寝けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, '或人ヱリコの王に告て觀よイスラエルの子孫の者この地を探らんとて今宵ここに入きたれりといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, '是に於てヱリコの王ラハブに言つかはしけるは汝にきたりて汝の家に入し人を曳いだせ彼らは此全國を探らんとて來れるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, '婦人かのふたりの人を將て之を匿し而して言ふ實にその人々はわが許に來れり然れども我その何處よりか知ざりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, '黄昏どき門を閉るころに出されり我その人々の何處へ往しかを知ず急ぎその後を追へ然ば之に追及んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'その實は婦すでにかれらを領て屋葢に升り屋葢の上に列べおきたる麻のなかに之をかくししなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'かくてその人々彼らの後を追ひヨルダンの路をゆきて渡場に赴むけり、かれらの後を追ふ者出るや直に門を閉しぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, '二人のもの未だ寝ずラハブ屋背に上りて彼らのもとに來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'これに言けるはヱホバこの地を汝らに賜へり我らは甚く汝らを懼る此地の民盡く汝らの前に消亡ん我この事を知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, '其は汝らがエジプトより出來し時ヱホバなんぢらの前にて紅海の水を乾たまひし事および汝らがヨルダンの彼旁にありしアモリ人の二箇の王シホンとオグとになししこと即ちことごとく之を滅ぼしたりし事を我ら聞たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, '我ら之を聞や心怯けなんぢらの故によりて人の魂きえうせたり汝らの神ヱホバは上の天にも下の地にも神たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, '然ば請ふ我すでに汝らに恩を施したれば汝らも今ヱホバを指て我父の家に恩をほどこさんことを誓ひて我に眞實の記號を與へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, '又わが父母兄弟姉妹および凡て彼らに屬る者をながらへしめ我らの生命を拯ひて死を免かれしめんことを誓へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, '二人のものこれに言けるは汝ら若しわれらの此事を洩すことなくば我らの生命汝らに代りて死ん又ヱホバわれらに此地を與へたまふ時には我らなんぢに恩を施し眞實を盡さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, '是においてラハブ繩をもて彼らを窓より縋おろせり是は其家邑の石垣の上にありてかれ石垣の上に住しによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'ラハブかれらに言けるは恐らくは追者なんぢに遇ん汝ら山に往て三日が間そこに隱れをり追者の還るを待て後去ゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, '二人のものかれに言けるは汝が我らに誓しし此誓につきては我ら罪を獲じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, '我らが此地に打いらん時は汝我らを縋おろしたりし窓に此一條の赤き紐を結つけ且つ汝の父母兄弟および汝の父の家の眷族を悉く汝の家に聚むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, '凡て汝の家の門を出て街衢に來る者はその血自身の首に歸すべし我らは罪なし然どもし汝とともに家にをる者に手をくはふることをせばその血は我らの首に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, '將た汝もし我らのこの事を洩さば汝が我らに誓せたる誓に我らあづかることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'ラハブいひけるはなんぢらの言のごとくすべしと斯てかれらを出し去しめて赤き紐を窓に結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'かれら往て山にいり追來るもののかへるを待て三日が間そこに居れりおひ來れるもの徧ねく彼らを途に尋ねしかども終に獲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, '而してかの二箇の人は山を下り河を濟りて歸りヌンの子ヨシユアに詣りて其有し事等をつぶさに陳ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'またヨシユアにいふ誠にヱホバこの國をことごとく我らの手に付したまへりこの國の民は皆我らの前に消うせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'ヨシユア朝はやく起いでてイスラエルの人々とともにシツテムを打發てヨルダンにゆき之を濟らずして其處に宿りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, '斯て三日の後有司ら陣營の中をめぐり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, '民に命じて曰ふ汝ら祭司等レビ人がなんぢらの神ヱホバの契約の櫃を舁出すを見ば其處を發出てその後に從がへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'されど汝らとその櫃との間には量りて凡そ二千キユビト許の隔離あるべし之に近づく勿れなんぢらその行べき途を知んためなり汝らは未だこの途を經しことなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'ヨシユアまた民に言ふ汝ら身を潔めよヱホバ明日なんぢらの中に妙なる事を行ひたまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'ヨシユア祭司等に告ていふ契約の櫃を舁き民に先だちて濟れと則ち契約の櫃を舁き民に先だちて進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'ヱホバ、ヨシユアに言たまひけるは今日よりして我イスラエルの衆の目の前に汝を尊くし我がモーセと偕にありし如く汝と偕にあることを之に知せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'なんぢ契約の櫃を舁ところの祭司等に命じて言へ汝らヨルダンの水際にゆかばヨルダンにいりて立べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'ヨシユアでイスラエルの人々にむかひて汝ら此に近づき汝らの神ヱホバの言を聽けと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, '而してヨシユア語りけらく活神なんぢらの中に在してカナン人ヘテ人ヒビ人ペリジ人ギルガジ人アモリ人ヱブス人を汝らの前より必ず逐はらひたまふべきを左の事によりてなんぢら知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, '視よ全地の主の契約の櫃なんぢらに先だちてヨルダンにすすみ入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, '然ば今イスラエルの支派の中より支派ごとに一人づつ合せて十二人を擧よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, '全地の主ヱホバの櫃を舁ところの祭司等の足の蹠ヨルダンの水の中に踏とどまらばヨルダンの水上より流れくだる水きれとどまり立てうづだかくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'かくて民はヨルダンを濟らんとてその幕屋を立出祭司等は契約の櫃を舁て之に先だちゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, '抑々ヨルダンは収穫の頃には絶ずその岸にことごとく溢るるなれど櫃を舁く者等ヨルダンに到り櫃を舁ける祭司等の足水際に浸ると斉しく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, '上より流れくだる水止まりて遥に遠き處まで涸れザレタンに近きアダム邑の邊にて積り起て堆かくなりアラバの海すなはち鹽海の方に流れくだる水まつたく截止りたれば民ヱリコにむかひて直に濟れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, '即ちヱホバの契約の櫃を舁る祭司等ヨルダンの中の乾ける地に堅く立をりてイスラエル人みな乾ける地を渉りゆき遂に民ことごとくヨルダンを濟りつくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, '民ことごとくヨルダンを濟りつくしたる時ヱホバ、ヨシユアに語りて言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '汝ら民の中より支派ごとに一人づつ合せて十二人を擧げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'これに命じて言へ汝らヨルダンの中祭司等の足を踏とめしその處より石十二を取あげてこれを負ひ濟り此夜なんぢらが宿る宿場に居ゑよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'ヨシユアすなはちイスラエルの人々の中より支派ごとに預て一人づつを取て備へおきぬその十二人の者を召よせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, '而してヨシユアこれに言けるは汝らの神ヱホバの契約の櫃の前に當りて汝らヨルダンの中にすすみ入りイスラエルの人々の支派の數に循ひて各々石ひとつを取あげて肩に負きたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, '是は汝らの中に徴となるべし後の日にいたりて汝らの子輩是等の石は何のこころなりやと問て言ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, '之にいへ往昔ヨルダンの水ヱホバの契約の櫃の前にて裁斷りたる事を表はすなり即ちそのヨルダンを濟れる時にヨルダンの水きれ止まれりこの故にこれらの石を永くイスラエルの人々の記念となすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'イスラエルのひとびとヨシユアの命ぜしごとく然なしヱホバのヨシユアに告げたまひし如くイスラエルの人々の支派の數にしたがひてヨルダンの中より石十二を取あげ之を負わたりてその宿る處にいたり之を其處にすゑたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'ヨシユアまたヨルダンの中において契約の櫃を舁る祭司等の足を踏立し處に石十二を立たりしが今日までも尚ほ彼處にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, '櫃を舁る祭司等はヱホバのヨシユアに命じて民に告しめたまひし事の悉く成るまでヨルダンの中に立をれり凡てモーセのヨシユアに命ぜし所に適へり民は急ぎて濟りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, '民の悉く濟りつくせるときヱホバの櫃および祭司等は民の觀る前にて濟りたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'ルベンの子孫ガドの子孫およびマナセの支派の半モーセの之に言たりし如く身をよろひてイスラエルの人々に先だちて濟りゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, '凡そ四萬人ばかりの者軍の装に身を堅め攻戰はんとてヱホバに先だち濟りてヱリコの平野に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'ヱホバこの日イスラエルの衆人の目の前にてヨシユアを尊くしたまひければ皆モーセを畏れしごとくに彼を畏る其一生の間常に然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'ヱホバ、ヨシユアに語りて言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'なんぢ證詞の櫃を舁る祭司等にヨルダンを出きたれと命ぜよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'ヨシユアすなはち祭司等に命じヨルダンを出きたれと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'ヱホバの契約の櫃を舁る祭司等ヨルダンの中より出きたる 祭司等足の蹠を陸地に擧ると斉くヨルダンの水故の處に流れかへりて初のごとくその岸にことごとく溢れぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, '正月の十日に民ヨルダンを出きたりヱリコの東の境界なるギルガルに營を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, '時にヨシユアそのヨルダンより取きたらせし十二の石をギルガルにたて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'イスラエルの人々に語りて言ふ後の日にいたりて汝らの子輩その父に問て是らの石は何の意なりやと言ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'その子輩に告しらせて言へ在昔イスラエルこのヨルダンを陸地となして濟りすぎし事あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, '即ち汝らの神ヱホバ、ヨルダンの水を汝らの前に乾涸して汝らを濟らせたまへり其事は汝らの神ヱホバの我らの前に紅海を乾涸して我らを渡らせたまひし状况の如くなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, '斯なしたまひしは地の諸の民をしてヱホバの手の力あるを知しめ汝らの神ヱホバを恒に畏れしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'ヨルダンの彼旁に居るアモリ人の諸の王および海邊に居るカナン人の諸の王はヱホバ、ヨルダンの水をイスラエルの人々の前に乾涸して我らを濟らせたまひしと聞きイスラエルの人々の事によりて神魂消え心も心ならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'その時ヱホバ、ヨシユアに言たまひけるは汝石の小刀を作り重て復イスラエルの人々に割禮を行なへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'ヨシユアすなはち石の小刀を作り陽皮山にてイスラエルの人々に割禮を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'ヨシユアが割禮を行ひし所以は是なりエジプトより出きたりし民の中の一切の男すなはち軍人は皆エジプトを出し後途にて荒野に死たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'その出來し民はみな割禮を受たる者なりき然どエジプトを出し後途にて荒野に生れし民には皆割禮を施こさざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'そもそもイスラエルの人々は四十年の間荒野を歩みをりて終にそのエジプトより出來し民すなはち軍人等ことごとく亡はてたり是ヱホバの聲に聽したがはざりしに因てなり是をもてヱホバかれらの先祖等に誓ひて我等に與へんと宣まひし地なる乳と蜜との流るる地を之に見せじと誓たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'かれらに継て興らしめたまひしその子輩にはヨシユア割禮を行へりかれらは途にて割禮を施さざりしによりて割禮なきものなりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, '一切の民に割禮を行ふこと畢りぬれば民は陣營に其儘居てその痊るを待り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, '時にヱホバ、ヨシユアにむかひて我今日エジプトの羞辱を汝らの上より轉ばし去りと宣まへり是をもてその處の名を今日までギルガル(轉)と稱ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'イスラエルの人々ギルガルに營を張りその月の十四日の晩ヱリコの平野にて逾越節を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, '而して逾越節の翌日その地の穀物酵いれぬパンおよび烘麥をその日に食ひけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'その地の穀物を食ひし翌日よりしてマナの降ることを止みてイスラエルの人々かさねてマナを獲ざりき其年はカナンの地の產物を食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'ヨシユア、ヱリコの邊にあひける時目を擧て觀しに一箇の人劍を手に抜持て己にむかひて立ゐければヨシユアすなはちその許にゆきて之に言ふ汝は我等を助くるか將われらの敵を助くるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'かれいひけるは否われはヱホバの軍旅の將として今來れるなりとヨシユア地に俯伏て拝し我主なにを僕に告んとしたまふやと之に言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'ヱホバの軍旅の將ヨシユアに言けるは汝の履を足より脱され汝が立をる處は聖きなりとヨシユア然なしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, '(イスラエルの人々の故によりてヱリコは堅く閉して出入する者なし)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'ヱホバ、ヨシユアに言ひたまひけるは觀よわれヱリコおよびその王と大勇士とを汝の手に付さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, '汝ら軍人みな邑を繞りて邑の周圍を一次まはるべし汝六日が間かく爲よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, '祭司等七人おのおのヨベルの喇叭をたづさへて櫃に先だつべし而して第七日には汝ら七次邑をめぐり祭司等喇叭を吹ならすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, '然して祭司等ヨベルの角を音ながくふきならして喇叭の聲なんぢらに聞ゆる時は民みな大に呼はり喊ぶべし然せばその邑の石垣崩れおちん民みな直に進て攻のぼるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'ヌンの子ヨシユアやがて祭司等を召て之に言ふ汝ら契約の櫃を舁き祭司等七人ヨベルの喇叭七をたづさへてヱホバの櫃に先だつべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, '而して民に言ふ汝ら進みゆきて邑を繞れ甲冑のものどもヱホバの櫃に先だちて進むべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'ヨシユアかく民に語りしかば七人の祭司等おのおのヨベルの喇叭をたづさへヱホバに先だちすきみて喇叭を吹きヱホバの契約の櫃これにしたがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, '即ち甲冑のものどもは喇叭を吹くところの祭司等にさきだちて行き後軍は櫃の後に行く祭司たちは喇叭を吹きつつすすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'ヨシユア民に命じて言ふ汝ら呼はる勿れ汝らの聲を聞えしむるなかれまた汝らの口より言を出すなかれわが汝らに呼はれと命ずる日におよびて呼はるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, '而してヱホバの櫃をもち邑を繞りて一周し陣營に來りて營中に宿れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, '又あくる朝ヨシユアはやく興いで祭司等ヱホバの櫃を舁き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, '七人の祭司等おのおのヨベルの喇叭をたづさへヱホバの櫃に先だちて行き喇叭を吹きつつすすみ甲冑の者等これに先だちて行き後軍はヱホバの櫃の後に行く祭司等喇叭をふきつつ進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'その次の日にも一次邑を繞りて陣營に歸り六日が間然なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, '第七日には夜明に早く興いで前のごとくして七次邑を繞れり唯この日のみ七次邑を繞りたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, '七次目にいたりて祭司等喇叭を吹くときにヨシユア民に言ふ汝ら呼はれヱホバこの邑を汝らに賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'この邑およびその中の一切の物をば詛はれしものとしてヱホバに献ぐべし唯妓婦ラハブおよび凡て彼とともに家に在るものは生し存べしわれらが遣しし使者を匿したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, '唯汝ら詛はれし物を愼め恐らくは汝ら其を詛はれしものとして献ぐるに方りその詛はれし物を自ら取りてイスラエルの陣營をも詛はるるものとならしめ之をして惱ましむるに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, '但し銀金銅器鐵器などは凡てヱホバに聖別て奉まつるべきものなればヱホバの府庫にこれを携へいるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, '是において民よばはり祭司喇叭を吹ならしけるが民喇叭の聲をきくと斉しくみな大聲を擧て呼はりしかば石垣崩れおちぬ斯りしかば民おのおの直に邑に上りいりて邑を攻取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, '邑にある者は男女少きもの老たるものの區別なく盡くこれを刃にかけて滅ぼし且つ牛羊驢馬にまで及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, '時にヨシユアこの地を窺ひたりし二箇の人にむかひ汝らかの妓婦の家に入りかの婦人およびかれに屬る一切のものを携へいだしかれに誓ひし如くせよと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, '間者たりし少き人等すなはち入てラハブおよびその父母兄弟ならびに彼につけるすべてのものを携へ出しまたその親戚をも携へ出しイスラエルの陣營の外にかれらを置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, '斯て火をもて邑とその中の一切のものを焚ぬ但し銀金銅器鐵器などはヱホバの室の府庫に納めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, '妓婦ラハブおよびその父の家の一族と彼に屬る一切の者とはヨシユアこれを生し存ければラハブは今日までイスラエルの中に住をる是はヨシユアがヱリコを窺はせんとて遣はしし使者を匿したるに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'ヨシユアその時人衆に誓ひて命じ言けるは凡そ起てこのヱリコの邑を建る者はヱホバの前に詛はるべし其石礎をすゑなば長子を失ひその門を建なば季子を失はんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'ヱホバ、ヨシユアとともに在してヨシユアの名あまねく此地に聞ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, '時にイスラエルの人々その詛はれし物につきて罪を犯せり即ちユダの支派の中なるゼラの子ザブデの子なるカルミの子アカン詛はれし物を取り是をもてヱホバ、イスラエルの人々にむかひて震怒を發ちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'ヨシユア、ヱリコより人を遣はしベテルの東に當りてベテアベンの邊にあるアイに到らしめんとし之に語りて言ふ汝ら上りゆきてかの地を窺へとその人々上りゆきてアイを窺ひけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'ヨシユアの許に歸て之に言ふ民を盡くは上り往しめざれ唯二三千人を上らせてアイを撃しめよかれらは寡ければ一切の民を彼處に遣て勞せしむるなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, '是において民およそ三千人ばかり彼處に上りゆきけるが遂にアイの人の前より遁はしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'アイの人彼らを門の前より追てシバリムにいたり下坂にてその三十六人ばかりを撃り民は魂神消て水のごとくになりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, '斯りしかばヨシユア衣を裂きイスラエルの長老等とともにヱホバの櫃の前にて暮まで地に俯伏をり首に塵を蒙れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'ヨシユア言けらく嗟主ヱホバよ何とて此民を導きてヨルダンを濟らせ我らをアモリ人の手に付して滅亡させんとしたまふや我等ヨルダンの彼旁に安んじ居しならば善りしものを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, '嗟主よイスラエルすでに敵に背を見せたれば我また何をか言ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'カナン人およびこの地の一切の民これを聞きわれらを攻かこみてわれらの名をこの世より絶ん然らば汝の大なる御名を如何にせんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'ヱホバ、ヨシユアに言たまひけるは立よなんぢ何とて斯は俯伏すや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'イスラエルすでに罪を犯しわが彼らに命じおける契約を破れり即ち彼らは詛はれし物を取り窃みかつ詐りてこれを己の所有物の中にいれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, '是をもてイスラエルの人々は敵に當ること能はず敵に背を見す是は彼らも詛はるる者となりたればなり汝ら其詛はれし物を汝らの中より絶にあらざれば我ふたたび汝らと偕にをらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'たてよ民を潔めて言へ汝ら身を潔めて明日を待てイスラエルの神ヱホバかく言たまふイスラエルよ汝の中に詛はれしものあり汝その詛はれし物を汝らの中より除き去るまでは汝の敵に當ること能はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, '然ば翌朝汝らその支派にしたがひて進みいづべし而してヱホバの掣たまふ支派はその宗族にしたがひて進み出でヱホバの掣たまふ宗族はその家にしたがひて進み出でヱホバの掣たまふ家は男ひとりびとりに從がひて進みいづべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, '凡そ掣れて詛はれし物を有りと定まる者は其一切の所有物とともに火に焚るべし是はヱホバの契約を破りイスラエルの中に愚なる事を行ひたるが故なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'ヨシユア是において朝はやく興いでてイスラエルをその支派にしたがひて進出しめけるにユダの支派掣れたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'ユダのもろもろの宗族を進み出でしめけるにゼラの宗族掣れゼラの宗族の人々を進み出しめけるにザブデ掣れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'ザブデの家の人々を進み出しめけるにアカン掣れぬ彼はユダの支派なるゼラの子ザブデの子なるカルミの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'ヨシユア、アカンに言けるは我子よ請ふイスラエルの神ヱホバに稱讃を歸し之にむかひて懺悔し汝の爲たる事を我に告よ其事を我に隱すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'アカン、ヨシユアに答へて言けるは實にわれはイスラエルの神ヱホバに對ひて罪ををかし如此々々行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, '即ちわれ掠取物の中にバビロンの美しき衣服一枚に銀二百シケルと重量五十シケルの金の棒あるを見欲く思ひて其を取れりそれはわが天幕の中に地に埋め匿してあり銀も下にありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, '爰にヨシユア使者を遣はしければ即ち彼の天幕に奔りゆきて視しに其は彼の天幕の中に匿しありて銀も下にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, '彼ら其を天幕の中より取出してヨシユアとイスラエルの一切の人々の所に携へきたりければ則ちそれをヱホバの前に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'ヨシユアやがてイスラエルの一切の人とともにゼラの子アカンを執へかの銀と衣服と金の棒およびその男子女子牛驢馬羊天幕など凡て彼の有る物をことごとく取てアコルの谷にこれを曳ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, '而してヨシユア言けらく汝なんぞ我らを惱まししやヱホバ今日汝を惱ましたまふべしと頓てイスラエル人みな石をもて彼を撃ころし又その家族等をも石にて撃ころし火をもて之を焚けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, '而してアカンの上に大なる石堆を積揚たりしが今日まで存るかくてヱホバその烈しき忿怒を息たまへり是によりてその處の名を今日までアコル(惱)の谷と呼ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, '茲にヱホバ、ヨシユアに言たまひけるは懼るる勿れ戰慄なかれ軍人をことごとく率ゐ起てアイに攻のぼれ視よ我アイの王およびその民その邑その地を都て汝の手に授く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, '汝さきにヱリコとその王とに爲し如くアイとその王とに爲べし今回は其貨財およびその家畜を奪ひて自ら取べし汝まづ邑の後に伏兵を設くべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'ヨシユアすなはち起あがり軍人をことごとく將てアイに攻のぼらんとしまづ大勇士三萬人を選びて夜の中にこれを遣はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'ヨシユアこれに命じて言く汝らは邑に對ひて邑の後に伏すべし邑に遠く離れをる勿れ皆準備をなして待をれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, '我と我に從がふ民みな共に邑に攻よせん而して彼らが初のごとく我らにむかひて打出んとき我らは彼らの前より逃はしらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, '然せば彼ら我らを追て出來べければ我等つひに之を邑より誘き出すことを得ん其は彼等いはんこの人衆は初めのごとくまた我等の前より逃ぐと斯てわれらその前より逃はしらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, '汝らその伏をる處より起りて邑を取べし汝らの神ヱホバ之を汝らの手に付したまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, '汝ら邑を乗取たらば邑に火を放ちヱホバの言詞の如く爲べし我これを汝らに命ず努よやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'かくてヨシユアかれらを遣はしければ即はち往てアイの西の方にてベテルとアイとの間に身を伏せたりヨシユアはその夜民の中に宿れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'ヨシユア朝はやく興いでて民をあつめイスラエルの長老等とともに民に先だちてアイにのぼりゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, '彼に從がふ軍人ことごとく上りゆきて攻寄せ邑の前に至りてアイの北に陣をとれり彼とアイの間には一の谷ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'ヨシユア五千人許を擧て邑の西の方にてベテルとアイとの間にこれを伏せおけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'かく民の全軍を邑の北に置きその伏兵を邑の西に置てヨシユアその夜谷の中にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'アイの王これを視しかばその邑の人々みな急ぎて蚤に起き進み出てイスラエルと戰ひけるが預て諜しあはせ置る頃には王とその一切の民アラバの前に進み來れり王は邑の後に伏兵ありて已を伺ふを知らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, '時にヨシユア、イスラエルの一切の人とともに彼らに打負し状して荒野の路を指て逃はしりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'その邑の民みな之を追撃んとて呼はり集まりヨシユアの後を追て邑を出離れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'アイにもベテルにもイスラエルを追ゆかずして遺りをる者は一人もなく皆邑を開き放してイスラエルの後を追り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, '時にヱホバ、ヨシユアに言たまはく汝の手にある矛をアイの方に指伸よ我これを汝の手に授くべしとヨシユアすなはち己の手にある矛をアイの方に指伸るに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, '伏兵たちまち其處より起りヨシユアが手を伸ると齊しく奔きたりて邑に打いり之を取りて直に邑に火をかけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, '茲にアイの人々背をふりかへりて觀しに邑の焚る煙天に立騰りゐたれば此へも彼へも逃るに術なかりき斯る機しも荒野に逃ゆける民も身をかへして其追きたる者等に逼れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'ヨシユアおよび一切のイスラエル人伏兵の邑を取て邑の焚る煙の立騰るを見身を還してアイの人々を殺しけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'かの兵また邑より出きたりて彼らに向ひければ彼方にも此方にもイスラエル人ありて彼らはその中間に挾まれぬイスラエル人かくして彼らを攻撃て一人をも餘さず逃さず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'つひにアイの王を生擒てヨシユアの許に曳きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'イスラエル人己を荒野に追きたりしアイの民をことごとく野に殺し刃をもてこれを仆し盡すにおよびて皆アイに歸り刃をもてこれを撃ほろぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'その日アイの人々ことごとく斃れたりその數男女あはせて一萬二千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'ヨシユア、アイの民をことごとく滅ぼし絶まではその矛を指伸たる手を垂ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, '但しその邑の家畜および貨財はイスラエル人これを奪ひて自ら取り是はヱホバのヨシユアに命じたまひし言に依なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'ヨシユア、アイを燬て永くこれを墟垤とならしむ是は今日まで荒地となりをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'ヨシユアまたアイの王を薄暮まで木に掛てさらし日の沒におよびて命じてその死骸を木より取おろさしめ邑の門の入口にこれを投すて其上に石の大垤を積おこせり其は今日まで存る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'かくてヨシユア、エバル山にてイスラエルの神ヱホバに一の壇を築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, '是はヱホバの僕モーセがイスラエルの子孫に命ぜしことに本づきモーセの律法の書に記されたる所に循がひて新石をもて作れる壇にて何人も鐵器をその上に振あげず人衆その上にてヱホバに燔祭を献げ酬恩祭を供ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, '彼處にてヨシユア、モーセの書しるしし律法をイスラエルの子孫の前にて石に書うつせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'かくてイスラエルの一切の人およびその長老官吏裁判人など他國の者も本國の者も打まじりてヱホバの契約の櫃を舁る祭司等レビ人の前にあたりて櫃の此旁と彼旁に分れ半はゲリジム山の前に半はエバル山の前に立り是ヱホバの僕モーセの命ぜし所にしたがひて最初に先イスラエルの民を祝せんとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, '然る後ヨシユア律法の書に凡てしるされたる所に循ひて祝福と呪詛とにかかはる律法の言をことごとく誦り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'モーセの命じたる一切の言の中にヨシユアがイスラエルの全會衆および婦人子等ならびにイスラエルの中にをる他國の人の前にて誦ざるは無りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, '茲にヨルダンの彼旁において山地平地レバノンに對へる大海の濱邊に居る諸の王すなはちヘテ人アモリ人カナン人ペリジ人ヒビ人ヱブス人たる者どもこれな聞て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, '心を同うし相集まりてヨシユアおよびイスラエルと戰はんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, '然るにギベオンの民ヨシユアがヱリコとアイとに爲たりし事を聞しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, '己も詭計をめぐらして使者の状にいでたち古き袋および古び破れたるを結びとめたる酒の革嚢を驢馬に負せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, '補ひたる古履を足にはき古衣を身にまとひ來れり其糧のパンは凡て乾きかつ黴てありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, '彼等ギルガルの陣營に來りてヨシユアの許にいたり彼とイスラエルの人々に言ふ我らは遠き國より來れり然ば今われらと契約を結べと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'イスラエルの人々ヒビ人に言けるは汝らは我等の中に住をるならんも計られねば我ら爭か汝らと契約を結ぶことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, '彼ら又ヨシユアにむかひて我らは汝の僕なりと言ければヨシユアかれらに汝らは何人にして何處より來りしやと問しに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, '彼らヨシユアに言けるは僕等は汝の神ヱホバの名の故によりて遥に遠き國より來れり其は我ら彼の聲譽および彼がエジプトにて行ひたりし一切の事を聞き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'また彼がヨルダンの彼旁にをりしアモリ人の二箇の王すなはちヘシボンの王シホンおよびアシタロテにをりしバシヤンの王オグに爲たりし一切の事を聞たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, '是をもて我らの長老および我らの國に住をるものみなわれらに告て言り汝ら旅路の糧を手に携さへ往てかれらを迎へて彼らに言へ我らは汝らの僕なり請ふ我らと契約を結べと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, '我らの此パンは汝らの所に來らんとて出たちし日に我ら家々より其なほ温煖なるをとり備へしなるが視よ今は已に乾きて黴たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'また酒をみたせるこれらの革嚢も新しかりしが破るるに至り我らのこの衣服も履も旅路の甚だ長きによりて古びぬと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, '然るに人々は彼らの糧を取りヱホバの口を問ことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'ヨシユアすなはち彼らと好を爲し彼らを生しおかんといふ契約を結び會中の長等かれらに誓ひたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'その彼らと契約を結びてより三日を經て後かれらは己に近き人にして己の中に住をる者なりと聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'イスラエルの子孫やがて進みて第三日に彼らの邑々に至れり其邑はギベオン、ケピラ、ベエロテおよびキリアテヤリムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, '然れども會中の長等イスラエルの神ヱホバを指て彼らに誓ひたりしをもてイスラエルの子孫これを攻撃ざりき是をもて會衆みな長等にむかひて呟けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, '然ど長等は凡て全會衆に言ふ我らイスラエルの神ヱホバを指て彼らに誓へり然ば今彼らに觸べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, '我ら斯かれらに爲て彼らを生しおかん然すれば彼らに誓ひし誓によりて震怒の我らに及ぶことあらじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, '長等また人衆にむかひて彼らを生しおくべしと言ければ彼らは遂に全會衆のために薪を斬り水を汲ことをする者となれり長等の彼等に言たるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'ヨシユアすなはち彼らを召よせて彼らに語りて言けるは汝らは我らの中に住をりながら何とて我らは汝らに甚だ遠しと言て我らを誑かししや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, '然ば汝らは詛はる汝らは永く奴隸となり皆わが神の室のために薪を斬り水を汲ことをする者となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, '彼らヨシユアに應へて言けるは僕等はなんぢの神ヱホバその僕モーセに此地をことごとく汝らに與へ此地の民をことごとく汝らの前より滅ぼし去ことを命ぜしと明白に傳へ聞たれば汝らのために生命の危からんことを太く懼れて斯は爲けるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, '視よ我らは今汝の手の中にあり汝の我らに爲を善とし正當とする所を爲たまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'ヨシユアすなはち其ごとく彼らに爲し彼らをイスラエルの子孫の手より救ひて殺さしめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'ヨシユアその日かれらをして會衆のためおよびヱホバの壇の爲に其えらびたまふ處において薪を斬り水を汲ことをする者とならしめたりしが今日まで然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, '茲にエルサレムの王アドニゼデクはヨシユアがアイを攻取てこれを全く滅ぼし嚮にヱリコとその王とに爲しごとくにアイとその王とにも爲たる事およびギベオンの民がイスラエルと好を爲て之が中にをる事を聞て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, '大に懼る是ギベオンは大なる邑にして都府に等しきに因りまたアイよりも大きくしてその内の人々凡て強きに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'エルサレムの王アドニゼデク是においてヘブロンの王ホハム、ヤルムテの王ピラム、ラキシの王ヤピアおよびエグロンの王デビルに人を遣はして云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '我の處に上りきたりて我を助けよ我らギベオンを攻撃ん其はヨシユアおよびイスラエルの子孫と好を結びたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, '而してこのアモリ人の王五人すなはちエルサレムの王ヘブロンの王ヤルムテの王ラキシの王およびエグロンの王あひ集まりそり諸軍勢を率て上りきたりギベオンに對ひて陣を取り之を攻て戰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'ギベオンの人々ギルガルの陣營に人を遣はしヨシユアに言しめけるは僕等を助くることを緩うする勿れ迅速に我らの所に上り來りて我らを救ひ助けよ山地に住をるアモリ人の王みな相集りて我らを攻るなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'ヨシユアすなはち一切の軍人および一切の大勇士を率ゐてギルガルより進みのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, '時にヱホバ、ヨシユアに言たまひけるは彼らを懼るるなかれ我かれらを汝の手に付す彼らの中には汝に當ることを得る者一人もあらじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'この故にヨシユア、ギルガルより終夜進みのぼりて猝然にかれらに攻よせしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'ヱホバかれらをイスラエルの前に敗りたまひければヨシユア、ギベオンにおいて彼らを夥多く撃殺しベテホロンの昇阪の路よりしてアゼカおよびマツケダまで彼らを追撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, '彼らイスラエルの前より逃はしりてベテホロンの降阪にありける時ヱホバ天より大石を降しそのアゼカに到るまで然したまひければ多く死りイスラエルの子孫が劍をもて殺しし者よりも雹石にて死し者の方衆かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'ヱホバ、イスラエルの子孫の前にアモリ人を付したまひし日にヨシユア、ヱホバにむかひて申せしことあり即ちイスラエルの目の前にて言けらく日よギベオンの上に止まれ月よアヤロンの谷にやすらへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, '民その敵を撃やぶるまで日は止まり月はやすらひぬ是はヤシヤルの書に記さるるにあらずや即ち日空の中にやすらひて急ぎ沒ざりしこと凡そ一日なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, '是より先にも後にもヱホバ是のごとく人の言を聽いれたまひし日は有ず是時にはヱホバ、イスラエルのために戰ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'かくてヨシユア一切のイスラエル人とともにギルガルの陣營に歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'かの五人の王は逃ゆきてマツケダの洞穴に隱れたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, '五人の王はマツケダの洞穴に隱れをるとヨシユアに告て言ふ者ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'ヨシユアいひけるは汝ら洞穴の口に大石を轉ばしその傍に人を置てこれを守らせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, '但し汝らは止る勿れ汝らの敵の後を追てその殿軍を撃て彼らをその邑々に入しむる勿れ汝らの神ヱホバかれらを汝らの手に付したまへるぞかしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'ヨシユアおよびイスラエルの子孫おびただしく彼らを撃殺して遂に殺し盡しその撃もらされて遺れる者等城々に逃いるにおよびて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, '民みな安然にマツケダの陣營にかへりてヨシユアの許にいたりけるがイスラエルの子孫にむかひて舌を鳴すもの一人もなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, '時にヨシユア言ふ洞穴の口を開きて洞穴よりかの五人の王を我前に曳いだせと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'やがて然なしてかの五人の王すなはちエルサレムの王ヘブロンの王ヤルムテの王ラキシの王およびエグロンの王を洞穴より彼の前に曳いだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'かの王等をヨシユアの前に曳いだしし時ヨシユア、イスラエルの一切の人々を呼よせ己とともに往し軍人の長等に言けるは汝ら近よりて此王等の頸に足をかけよと乃はち近よりてその王等の頸に足をかけければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'ヨシユアこれに言ふ汝ら懼るる勿れ慄く勿れ心を強くしかつ勇めよ汝らが攻て戰ふ諸の敵にはヱホバすべて斯のごとく爲たまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'かくて後ヨシユア彼らを撃て死しめ五個の木にかけて晩暮まで木の上にこれを曝しおきしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, '日の沒る時におよびてヨシユア命を下しければ之を木より取おろしその隱れたりし洞穴に投いれて洞穴の口に大石を置り是は今日が日までも存す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'ヨシユアかの日マツケダを取り刃をもて之とその王とを撃ち之とその中たる一切の人をことごとく滅して一人をも遺さずヱリコの王になしたるごとくにマツケダの王にも爲しぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'かくてヨシユア一切のイスラエル人を率ゐてマツケダよりリブナに進みてリブナを攻て戰ひけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'ヱホバまた之とその王をもイスラエルの手に付したまひしかば刃をもて之とその中なる一切の人を撃ほろぼし一人をもその中に遺さずヱリコの王に爲たるごとくにその王にも爲ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'ヨシユアまた一切のイスラエル人を率ゐてリブナよりラキシに進み之にむかひて陣をとり之を攻めて戰ひけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'ヱホバでラキシをイスラエルの手に付したまひけれぼ第二日にこれを取り刃をもて之とその中なる一切の人々を撃ちほろぼせり凡てリブナに爲たるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, '時にゲゼルの王ホラム、ラキシを援けんとて上りきたりければヨシユアかれとその民とを撃ころして終に一人をも遺さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, '斯てヨシユア一切のイスラエル人を率ゐてラキシよりエグロンに進み之に對ひて陣を取りこれを攻て戰ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'その日にこれを取り刃をもて之を撃その中なる一切の人をことごとくその日に滅ぼせり凡てラキシに爲たるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'ヨシユアまた一切のイスラエル人をひきゐてエグロンよりヘブロンに進みのぼり之を攻て戰ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'やがてこれを取り之とその王およびその一切の邑々とその中なる一切の人を刃にかけて撃ころして一人をも遺さざりき凡てエグロンに爲たるが如し即ち之とその中なる一切の人をことごとく滅ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'かくてヨシユア一切のイスラエル人を率ゐ歸りてデビルに至り之を攻て戰ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, '之とその王およびその一切の邑を取り刃をもて之を撃てその中なる一切の人をことごとく滅ぼし一人をも遺さざりき其デビルと其王に爲たる所はヘブロンに爲たるが如く又リブナとその王に爲たるがごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'ヨシユアかく此全地すなはち山地南の地平地および山腹の地ならびに其すべての王等を撃ほろぼして人一箇をも遺さず凡て氣息する者は盡くこれを滅ぼせりイスラエルの神ヱホバの命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'ヨシユア、カデシバルネアよりガザまでの國々およびゴセンの全地を撃ほろぼしてギベオンにまで及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'イスラエルの神ヱホバ、イスラエルのために戰ひたまひしに因てヨシユアこれらの諸王およびその地を一時に取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'かくてヨシユア一切のイスラエル人を率ゐてギルガルの陣營にかへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'ハゾルの王ヤビン之を聞およびマドンの王ヨバブ、シムロンの王アクサフの王');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'および北の地山地キンネロテの南のアラバ平地西の方なるドルの高處などに居る王等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'すなはち東西のカナン人アモリ人ヘテ人ペリジ人山地のエブス人ミヅバの地なるヘルモンの麓のヒビ人などに人を遣はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, '爰に彼らその諸軍勢を率ゐて出きたれり其民の衆多ことは濱の砂の多きがごとくにして馬と車もまた甚だ多かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'これらの王たち皆あひ會して進みきたり共にメロムの水の邊に陣をとりてイスラエルと戰はんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, '時にヱホバ、ヨシユアに言たまひけるは彼らの故によりて懼るる勿れ明日の今頃われ彼らをイスラエルの前に付して盡く殺さしめん汝かれらの馬の足の筋を截り火をもて彼らの車を焚べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'ヨシユアすなはち一切の軍人を率ゐて俄然にメロムの水の邊に押寄て之を襲ひけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'ヱホバこれをイスラエルの手に付したまひしかば則ち之を撃やぶりて大シドンおよびミスレポテマイムまで之を追ゆき東の方にては又ミヅバの谷までこれを追ゆき遂に一人をも遺さず撃とれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'ヨシユアすなはちヱホバの己に命じたまひしことにしたがひて彼らに馬の足の筋を截り火をもてその車を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'その時ヨシユア歸りきたりてハゾルを取り刃をもてその王を撃り在昔ハゾルは是らの諸國の盟主たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, '即ち刃をもてその中なる一切の人を撃てことごとく之を滅ぼし氣息する者は一人だに遺さざりき又火をもてハゾルを焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'ヨシユアこれらの王の一切の邑々およびその諸王を取り刃をもてこれを撃て盡く滅ぼせり、ヱホバの僕モーセの命じたるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, '但しその岡の上にたちたる邑々はイスラエルこれを焚ず唯ハゾルのみをヨシユア焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, '是らの邑の諸の貨財及び家畜はイスラエルの人々奪ひて自ら之を取り人はみな刃をもて撃て滅ぼし盡し氣息する者は一人だに遺さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'ヱホバその僕モーセに命じたまひし所をモーセまたヨシユアに命じ置たりしがヨシユアその如くに行へり凡てヱホバのモーセに命じたまひし所はヨシユア一だに爲で置し事なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'ヨシユア斯その全地すなはち山地南の全地ゴセンの全地平地アラバ、イスラエルの山地およびその平地を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'セイルに上りゆくでハラク山よりヘルモン山の麓なるレバノン谷のバアルガデまでを獲その王等をことごとく執へて之を撃て死しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'ヨシユア此すべての王等と戰爭をなすこと日ひさし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'ギベオンの民ヒビ人を除くの外はイスラエルの子孫と好をなしし邑なかりき皆戰爭をなしてこれを攻とりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'そもそも彼らが心を剛愎にしてイスラエルに攻よせしはヱホバの然らしめたまひし者なり彼らは詛はれし者となり憐憫を乞ふこととせず滅ぼされんがためなりき是全くヱホバのモーセに命じたまひしが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'その時ヨシユアまた往て山地ヘブロン、デビル、アナブ、ユダの一切の山地イスラエルの一切の山地などよりしてアナク人を絶ち而してヨシユア彼らの邑々をも與に滅ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, '然からにイスラエルの子孫の地の内にはアナク人一人も遺りをらず只ガザ、ガテ、アシドドに少く遺りをる而已');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'ヨシユアかく此地を盡く取り全くヱホバのモーセに告たまひし如し而してヨシユア、イスラエルの支派の區別にしたがひ之を與へて產業となさしめたり遂に此地に戰爭やみぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, '偖ヨルダンの彼旁日の出る方に於てアルノンの谷よりヘルモン山および東アラバの全土までの間にてイスラエルの子孫が撃ほろぼして地を取たりし其國の王等は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, '先アモリ人の王シホン彼はヘシボンに住をれり其治めたる地はアルノンの谷の端なるアロエルより谷の中の邑およびギレアデの半を括てアンモンの子孫の境界なるヤボク河にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'アラバをキンネレテの海の東まで括またアラバの海すなはち鹽海の東におよびてベテエシモテの路にいたり南の方ビスガの山腹にまで達す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, '次にレバイムの殘餘なりしバシヤンの王オグの國境を言んに彼はアシタロテとエデレイに住をり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'ヘルモン山サレカおよびバシヤンの全土よりしてゲシユリ人マアカ人およびギレアデの半を治めてヘシボンの王シホンと境を接ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'ヱホバの僕モーセ、イスラエルの子孫とともに彼らを撃ほろぼせり而してヱホバの僕モーセ之が地をルベン人ガド人およびマナセの支派の半に與へて產業となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'またヨルダンの此旁西の方においてレバノンの谷のバアルガデよりセイル山の上途なるハラク山までの間にてヨシユアとイスラエルの子孫が撃ほろぼしたりし其國の王等は左のごとしヨシユア、イスラエルの支派の區別にしたがひその地をあたへて產業となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, '是は山地平地アラバ山腹荒野南の地などにしてヘテ人アモリ人カナン人ペリジ人ヒビ人ヱブス人等が有ちたりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'ヱリコの王一人ベテルの邊なるアイの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'エルサレムの王一人ヘブロンの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'ヤルムテの王一人ラキシの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'エグロンの王一人ゲゼルの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'デビルの王一人ゲデルの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'ホルマの王一人アラデの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'リブナの王一人アドラムの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'マツケダの王一人ベテルの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'タッブアの王一人へペルの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'アペクの王一人ラシヤロンの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'マドンの王一人ハゾルの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'シムロンメロンの王一人アクサフの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'タアナクの王一人メギドンの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'ケデシの王一人カルメルのヨクネアムの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'ドルの高處なるドルの王一人ギルガのゴイイムの王一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'テルザの王一人合せて三十一王');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'ヨシユアすでに年邁みて老たりしがヱホバかれに言たまひけらく汝は年邁みて老たるが尚取るべき地の殘れる者甚だおほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'その尚のこれる地は是なりペリシテ人の全州ゲシユル人の全土');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'エジプトの前なるシホルより北の方カナン人に屬すると人のいふエクロンの境界までの部ペリシテ人の五人の主の地すなはちガザ人アシドド人アシケロン人ガテ人エクロン人の地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, '南のアビ人カナン人の全地シドン人に屬するメアラおよびアモリ人の境界なるアベクまでの部');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'またへルモン山の麓なるバアルガデよりハマテの入口までに亘るゲバル人の地およびレバノンの東の全土');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'レバノンよりミスレポテマイムまでの山地の一切の民すなはちシドン人の全土我かれらをイスラエルの子孫の前より逐はらふべし汝は我が命じたりしごとくその地をイスラエルに分ち與へて產業となさしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, '即ちその地を九の支派とマナセの支派の半とに分ちて產業となさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'マナセとともにルベン人およびガド人はヨルダンの彼旁東の方にてその產業をモーセより賜はり獲たりヱホバの僕モーセの彼らに與へし者は即ち是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'アルノンの谷の端にあるアロエルより此方の地谷の中にある邑デボンまでに亘るメデバの一切の平地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'ヘシボンにて世を治めしアモリ人の王シホンの一切の邑々よりしてアンモンの子孫の境界までの地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'ギレアデ、ゲシユル人及びマアカ人の境界に沿る地へルモン山の全土サルカまでバシヤン一圓');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'アシタロテおよびエデレイにて世を治めしバシヤンの王オグの全國オグはレバイムの餘民の遺れる者なりモーセこれらを撃て逐はらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, '但しゲシユル人およびマアカ人はイスラエルの子孫これを逐はらはざりきゲシユル人とマアカ人は今日までイスラエルの中に住をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, '唯レビの支派にはヨシユア何の產業をも與へざりき是イスラエルの神ヱホバの火祭これが產業たればなり其かれに言たまひしが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'モーセ、ルベンの子孫の支派にその宗族にしたがひて與ふる所ありしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'その境界の内はアルノンの谷の端なるアロエルよりこなたの地谷の中なる邑メデバの邊の一切の平地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'ヘシボンおよびその平地の一切の邑々 デボン、バモテバアル、ベテバアルメオン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'ヤハズ、ケデモテ、メバアテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'キリアタイム、シブマ、谷中の山のゼレテシヤル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'ベテペオル、ピスガの山腹ベテヱシモテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, '平地の一切の邑々 ヘシボンにて世を治めしアモリ人の王シホンの全國 モーセ、シホンをミデアンの貴族エビ、レケム、ツル、ホルおよびレバとあはせて撃ころせり是みなシホンの大臣にしてその地に住をりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'イスラエルの子孫またベオルの子卜筮師バラムをも刃にかけてその外に殺せし者等とともに殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'ルベンの子孫はヨルダンおよびその河岸をもて己の境界とせり ルベンの子孫がその宗族に循がひて獲たる產業は是のごとくにして邑も村もこれに准らふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'モーセまたガドの子孫たるガドの支派にもその宗族にしたがひて與ふる所ありしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'その境界の内はヤゼル、ギレアデの一切の邑々アンモンの子孫の地の半ラバの前なるアロエルまでの地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'ヘシボンよりラマテミヅバまでの地およびベトニム、マナハイムよりデビルの境界までの地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, '谷においてはベテハラム、ベテニムラ、スコテ、ザポンなどヘシボンの王シホンの國の殘れる部分 ヨルダンおよびその河岸よりしてヨルダンの東の方キンネレテの海の岸までの地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'ガドの子孫がその宗族にしたがひて獲たる產業は是のごとくにして邑も村も之に准らふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'モーセまたマナセの支派の半にも與ふる所ありき是すなはちマナセの支派の半にその宗族にしたがひて與へしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'その境界の内はマナハイムより此方の地 バシヤンの全土 バシヤンの王オグの全國 バシヤンにあるヤイルの一切の邑すなはち其六十の邑');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'ギレアデの半バシヤンにおけるオグの國の邑々 アシタロテおよびエデレイ是等はマナセの子マキルの子孫に歸せり即ちマキルの子孫の半その宗族にしたがひて之を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'ヨルダンの東の方に於てヱリコに對ひをるモアブの野にてモーセが分ち與へし產業は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, '但しレビの支派にはモーセ何の產業をも與へざりきイスラエルの神ヱホバこれが產業たればなり其かれらに言たまひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'イスラエルの子孫がカナンの地にて取しその產業の地は左のごとし即ち祭司エレアザル、ヌンの子ヨシユアおよびイスラエルの子孫の支派の族長等これを彼らに分ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'ヱホバがモーセによりて命じたまひしごとく產業の籤によりて之を九の支派および半の支派に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, '其はヨルダンの彼旁にてモーセ已にかの二の支派と半の支派とに產業を與へたればなり但しレビ人には之が中に產業を與へざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, '是はヨセフの子孫マナセ、エフライムの二の支派と成たるに因て然りレビ人には此地において何の分をも與へず唯その住べき邑々およびその家畜と貨財を置べき郊地を與へしのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'イスラエルの子孫ヱホバのモーセに命じたまひしごとく行ひてその地を分てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, '茲にユダの子孫ギルガルにてヨシユアの許に至りケニズ人ヱフンネの子カレブ、ヨシユアに言けるはヱホバ、カデシバルネアにて我と汝との事につきて神の人モーセに告たまひし事あり汝これを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'ヱホバの僕モーセが此地を窺はせんとて我をカデシバルネアより遣はしし時に我は四十歳なりき其時我は心に思ふまにまに彼に復命したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, '我とともに上り往しわが兄弟等は民の心を挫くことを爲たりしが我は全く我神ヱホバに從へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'その日モーセ誓ひて言けらく汝の足の踐たる地は必ず永く汝と汝の子孫の產業となるべし汝まったく我神ヱホバに從がひたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'ヱホバこの言をモーセに語りたまひし時より已來イスラエルが荒野に歩みたる此四十五年の間かく其のたまひし如く我を生存らへさせたまへり視よ我は今日すでに八十五歳なるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, '今日もなほモーセの我を遣はしたりし日のごとく健剛なり我が今の力はかの時の力のごとくにして出入し戰闘をなすに堪ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, '然ば彼日ヱホバの語りたまひし此山を我に與へよ汝も彼日聞たる如く彼處にはアナキ人をりその邑々は大にして堅固なり然ながらヱホバわれとともに在して我つひにヱホバの宣ひしごとく彼らを逐はらふことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'ヨシユア、ヱフンネの子カレブを祝しヘブロンをこれに與へて產業となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, '是をもてヘブロンは今日までケニズ人ヱフンネの子カレブの產業となりをる是は彼まつたくイスラエルの神ヱホバに從がひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'ヘブロンの名は元はキリアテアルバと曰ふアルバはアナキ人の中の最も大なる人なりき茲にいたりてその地に戰爭やみぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'ユダの子孫の支派がその宗族にしたがひて籤にて獲たる地はエドムの境界に達し南の方ヂンの荒野にわたり南の極端に及ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'その南の境界は鹽海の極端なる南に向へる入海より起り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'アクラビムの坂の南にわたりてヂンに進みカデシバルネアの南より上りてヘヅロンに沿て進みアダルに上りゆきてカルカに環り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'アズモンに進みてエジプトの河にまで達しその境界海にいたりて盡く汝らの南の境界は是の如くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'その東の境界は鹽海にしてヨルダンの河口に達す北の方の境界はヨルダンの河口なる入海より起り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, '上りてベテホグラにいたりベテアラバの北をすぎ上りてルベン人ボハンの石に達し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'またアコルの谷よりデビルに上りて北におもむき河の南にあるアドミムの坂に對するギルガルに向ひすすみてエンシメシの水に達しエンロゲルにいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, '又その境界はベニヒンノムの谷に沿てヱブス人の地すなはちヱルサレムの南の脇に上りゆきヒンノムの谷の西面に横はる山の嶺に上る是はレバイムの谷の北の極處にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, '而してその境界この山の嶺より延てネフトアの水の泉源にいたりエフロン山の邑々にわたりその境昇延てバアラにいたる是すなはちキリアテヤリムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'その境界バアラより西の方セイル山に環りヤリム山(すなはちケサロン)の北の脇をへてベテシメシに下りテムナに沿て進み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'エクロンの北の脇にわたり延てシツケロンに至りバアラ山に進みヤブネルに達し海にいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'また西の境界は大海にいたりその濱をもて限とすユダの子孫がその宗族にしたがひて獲たる地の四方の境界は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'ヨシユアそのヱホバに命ぜられしごとくヱフンネの子カレブにユダの子孫の中にてキリアテアルバすなはちヘブロンを與へてその分となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'アルバはアナクの父なりカレブかしこよりアナクの子三人を逐はらへり是すなはちアナクより出たるセシヤイ、アヒマンおよびタルマイなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, '而して彼かしこよりデビルの民の所に攻上れりデビルの名は元はキリアテセペルといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'カレブ言けらくキリアテセペルを撃てこれを取る者には我女子アクサを妻に與へんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'ケナズの子にしてカレブの弟なるオテニエルといふ者これを取ければカレブその女子アタサを之が妻に與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'アクサ適く時田野をその父に求むべきことをオテニエルに勸め遂にみづから驢馬より下れりカレブこれに何を望むやと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, '答へて言ふ我に粧奩を與へよ汝われを南の地に遣なれば水泉をも我に與へよと乃ち上の泉と下の泉とをこれに與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'ユダの子孫の支派がその宗族にしたがひて獲たる產業は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'ユダの子孫の支派が南においてエドムの境界の方に有るその遠き邑々は左のごとしカブジエル、エデル、ヤグル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'キナ、デモナ、アダダ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'ケデシ、ハゾル、イテナン、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'ジフ、テレム、ベアロテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'ハゾルハダツタ、ケリオテヘヅロンすなはちハゾル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'アマム、シマ、モラダ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'ハザルガダ、ヘシモン、ベテパレテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'ハザルシユアル、ベエルシバ、ビジヨテヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'バアラ、イヰム、エゼム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'エルトラデ、ケシル、ホルマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'チクラグ、マデマンナ、サンサンナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'レバオテ、シルヒム、アイン、リンモン、その邑あはせて二十九ならびに之に屬る村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, '平野にてはエシタオル、ゾラ、アシナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'ザノア、エンガンニム、タップア、エナム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'ヤルムテ、アドラム、シヨコ、アゼカ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'シヤアライム、アデタイム、ゲデラ、ゲデロタイム合せて十四邑ならびに之に屬る村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'ゼナン、ハダシヤ、ミグダルガデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'デラン、ミヅバ、ヨクテル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'ラキシ、ボヅカテ、エグロン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'カボン、ラマム、キリテシ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'ゲデロテ、ベテダゴン、ナアマ、マツケダ合せて十六邑ならびに之に屬る村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'またリブナ、エテル、アシヤン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'イフタ、アシナ、ネジブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'ケイラ、アクジブ、マレシア合せて九邑ならびに之に屬ける村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'エクロンならびにその郷里および村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'エクロンより海まで凡てアシドドの邊にある處々ならびに之につける村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'アシドドならびにその郷里および村々 ガザならびにその郷里および村々 エジプトの河および大海の濱にいたるまでの處々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, '山地にてはシヤミル、ヤツテル、シヨコ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'ダンナ、キリアテサンナすなはちデビル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'アナブ、エシテモ、アニム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'ゴセン、ホロン、ギロ、合せて十一邑ならびに之に屬る村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'アラブ、ドマ、エシヤン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'ヤニム、ベテタツプア、アペカ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'ホムタ、キリアテアルバすなはちヘブロン、デオルあはせて九邑ならびに之につける村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'マオン、カルメル、ジフ、ユダ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'ヱズレル、ヨグテアム、ザノア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'カイン、ギベア、テムナあはぜて十邑ならびに之に屬る村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'ハルホル、ベテズル、ゲドル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'マアラテ、ベテアノテ、エルテコンあはせて六邑ならびに之に屬る村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'キリアテバアルすなはちキリアテヤリムおよびラバあはせて二邑ならびに之につける村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, '荒野にてはベテアラバ、ミデン、セカカ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'ニブシヤン鹽邑エングデあはせて六邑ならびに之につける村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'ヱルサレムの民ヱブス人はユダの子孫これを逐はらふことを得ざりき是をもてヱブス人は今日までユダの子孫とともにエルサレムに住ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'ヨセフの子孫が籤によりて獲たる地の境界はヱリコの邊なるヨルダンすなはちヱリコの東の水の邊より起りてヱリコにかかり更に上りて山地を過ぎベテルにいたりて荒野に沿ひ行き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'ベテルよりルズにおもむきアルキ人の境界なるアタロテに進み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'また西の方ヤフレテ人の境界に下り下ベテホロンの境界に及びゲゼルにまで達し海にいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'かくヨセフの子孫マナセ及びエフライムその產業を受たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'エフライムの子孫がその宗族にしたがひて獲たる地の境界は是のごとしその產業の境界東はアタロテアダルにて上はベテホロンに達し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'ミクメタの北より西におもむき東にをれてタアナテシロにいたり之に沿てヤノアの東を過ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'ヤノアより下りてアタロテおよびナアラにいたりヱリコに達しヨルダンにいたりて盡き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'タツプアよりして西に進みカナの河にまで達し海にいたりて盡くエフライムの子孫の支派がその宗族にしたがひて獲たる產業は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'この外にマナセの子孫の產業の中にてエフライムの子孫に別ち與へし邑々ありエフライムの一切の邑およびその村々を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, '但しゲゼルに住るカナン人をば逐はらはざりき是をもてカナン人は今日までエフライムの中に住み僕となりて之に使役せらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'マナセの支派が籤によりて獲たる地は左のごとしマナセはヨセフの長子なりきマナセの長子にしてギレアデの父なるマキルは軍人なるが故にギレアデとバシヤンを獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, '此餘のマナセの子等即ちアビエゼルの子孫ヘレクの子孫アスリエルの子孫シケムの子孫へペルの子孫セミダの子孫などもその宗族にしたがひて獲る所ありき是等はヨセフの子マナセが男の子にしてその宗族に循ひて言るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'マナセの子マキルその子ギレアデその子へペルその子なるゼロペハデといふ者は女の子のみありて男の子あらざりきその女の子の名はマヘラ、ノア、ホグラ、ミルカ、テルザといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, '彼等祭司エレアザル、ヌンの子ヨシユアおよび長等の前に進み出て言けらく我らの兄弟の中にて我らにも產業を與へよとヱホバ、モーセに命じおきたまへりヨシユアすなはちヱホバの命にしたがひて彼らの父の兄弟の中にて彼らにも產業を與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'マナセはヨルダンの彼旁にてギレアデおよびバシヤンの地の外になほ十部の地を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, '是はマナセの女の子等もその男の子等の中にて產業を獲たればなりギレアデの地はマナセのその餘の子等に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'マナセの境界はアセルよりシケムの前なるミクメタテに及び右におもむきてエンタツプアの民に達す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'タツプアの地はマナセに屬す但しマナセの境界にあるタツプアはエフライムの子孫に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'またその境界カナの河に下りてその河の南に至る是等の邑はマナセの邑々の中にありてエフライムに屬すマナセの境界はその河の北にあり海にいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'その南の方はエフライムに屬し北の方はマナセに屬し海これらの境界を成すマナセは北はアセルに達し東はイツサカルに達す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'イツサカルおよびアセルの中にてマナセはベテシヤンとその郷里イブレアムとその郷里ドルの民とその郷里およびエンドルの民とその郷里タアナクの民とその郷里メギドンの民とその郷里など合せて三の高處を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, '但しマナセの子孫は是らの邑の民を逐はらふことを得ざりければカナン人この地に固く住ひをりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'イスラエルの子孫強くなるに及びてカナン人を使役し之を盡く逐ことはせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, '茲にヨセフの子孫ヨシユアに語りて言けるはヱホバ今まで我を祝福たまひて我は大なる民となりけるに汝わが產業にとて只一の籤一の分のみを我に與へしは何ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'ヨシユアかれらに言けるは汝もし大なる民となりしならば林に上りゆきて彼處なるペリジ人およびレバイム人の地を自ら斬ひらくべしエフライムの山地は汝には狭しと言ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'ヨセフの子孫言けるは山地は我らには足ずかつ又谷の地にをるカナン人はベテシヤンとその郷里にをる者もヱズレルの谷にをる者も凡て鐵の戰車を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'ヨシユアかさねてヨセフの家すなはちエフライムとマナセに語りて言ふ汝は大なる民にして大なる力あり然れば只一籤のみを取てをる可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, '山地をも汝の有とすべし是は林なれども汝これを斬ひらきてその極處を獲べしカナン人は鐵の戰車を有をりかつ強くあれども汝これを逐はらふことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'かくてイスラエルの子孫の會衆ことごとくシロに集り集會の幕屋をかしこに立つその地は已に彼らに歸服ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'この時なほイスラエルの子孫の中に未だその產業を分ち取ざる支派七のこりゐければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'ヨシユア、イスラエルの子孫に言けるは汝らは汝らの先祖の神ヱホバの汝らに與へたまひし地を取に往くことを何時まで怠りをるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, '汝ら支派ごとに三人づつを擧よ我これを遣さん彼らは起てその地を歩きめぐりその產業にしたがひて之を描き寫して我に歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, '彼らその地を分ちて七分となすべしユダは南にてその境界の内にをりヨセフの家は北にてその境界の内にをるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, '汝らその地を描き寫して七分となし此にわが許に持きたれ我ここにて我等の神ヱホバの前になんぢらの爲に籤を掣ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'レビ人は汝らの中に何の分をも有ずヱホバの祭司となることをもて其產業とす又ガド、ルベンおよびマナセの支派の半はヨルダンの彼旁東の方にて已にその產業を受たり是ヱホバの僕モーセの之に與へし者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'その人々すなはち起て往り其地を描き寫さんとて出ゆける此者等にヨシユア命じて云ふ汝等ゆきてその地を歩きめぐり之を描き寫して我に歸りきたれ我シロにて此にヱホバの前にて汝らのために籤を掣んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'その人々ゆきてその地を經めぐり邑にしたがひて之を七分となして書に描き寫しシロの營に歸りてヨシユアに詣りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'ヨシユア、シロにて彼らのためにヱホバの前に籤を掣り而してヨシユア彼所にてイスラエルの子孫の區分にしたがひて其地を分ち與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'まづベニヤミンの子孫の支派のためにその宗族にしたがひて籤を掣りその籤によりて獲たる地の境界はユダの子孫とヨセフの子孫の間にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, '即ちその北の方の境界はヨルダンよりしてヱリコの北の脇に上り西の山地を逾てまた上りベテアベンの荒野にいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, '彼處よりその境界ルズに進みルズの南の脇にいたるルズはベテルなり而して其境界下ベテホロンの南に横たはる山に沿てアタロテアダルに下り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, '延て西の方にて南に曲りベテホロンの南面に横はるところの山より進みユダの子孫の邑キリアテバアル即ちキリアテヤリムにいたりて盡くその西の境界は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'またその南の方はキリアテヤリムの極處よりして西におもむきてネフトアの水の源にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'レバイムの谷の中の北の方にてベニヒンノムの谷の前に横たはる所の山の極處に下り其處よりしてヒンノムの谷に下りてヱブス人の南の脇にいたりエンロゲルに下り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, '北に延てエンシメシにおもむきアドミムの阪に對へるゲリロテにおもむきルベン人、ボハンの石まで下り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, '北の方にてアラバに對する處にわたりてアラバに下り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'ベテホグラの北の脇にわたりヨルダンの南の極にて鹽海の北の入海にいたりて盡くその南の境界は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, '東の方にてはヨルダンその境界となる是すなはちベニヤミンの子孫がその宗族にしたがひて獲たる產業の周圍の境界なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'ベニヤミンの子孫の支派がその宗族にしたがひて獲たる邑々はヱリコ、ベテホグラ、エメクケジツ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'ベテアラバ、ゼマライム、ベテル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'アビム、パラ、オフラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'ケパルアンモン、オフニ、ケバの十二邑ならびに之に屬る村々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'ギベオン、ラマ、ベエロテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'ミヅパ、ケピラ、モザ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'レケム、イルピエル、タララ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'ゼラ、エレフ、ヱブスすなはちエルサレム、ギベア、キリアテの十四邑ならびに之につける村々是なり ベニヤミンの子孫がその宗族にしたがひて獲たる產業は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, '次にシメオンのため即ちシメオン子孫の支派のためにその宗族にしたがひて籤を掣りその產業ばユダの子孫の產業の中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'その有る產業はベエルシバ即ちシバ、モラダ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'ハザルシユアル、バラ、エゼム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'エルトラデ、ベトル、ホルマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'チクラグ、ベテマルカボテ、ハザルスサ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'ベテレバオテ、シヤルヘンの十三邑並びに之につける村々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'およびアイン、リンモン、エテル、アシヤンの四邑ならびに之につける村々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'および此邑々の周圍にありてバアラテベエルすなはち南のラマまでに至るところの一切の村々等なりシメオンの子孫の支派がその宗族にしたがひて獲たる產業は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'シメオンの子孫の產業はユダの子孫の分の中より出づ是ユダの子孫の分自分のためには多かりしに因てシメオンの子孫のおのれの產業を彼らの產業の中に獲たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, '第三にゼブルンの子孫のために其宗族にしたがひて籤を掣り其產業の境界はサリデに及び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'また西に上りてマララに至りダバセテに達しヨグネアムの前なる河に達し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'サリデよりして東の方日のいづる方にまがりてキスロテタボルの境界にいたりタベラに出でヤピアに上り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, '彼處より東の方ガテヘペルにわたりてイツタカジンにいたりネアまで廣がるところのリンモンに至りて盡き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'また北にまはりてハンナトンにいたりイフタエルの谷にいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'カツタテ、ナハラル、シムロン、イダラ、ベテレヘムなどの十二邑ならびに之につける村々あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'ゼブルンの子孫がその宗族にしたがひて獲たる產業およびその邑と村とは是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, '第四にイツサカルすなはちイツサカルの子孫のためにその宗族にしたがひて籤を掣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'その境界の包括る處はヱズレル、ケスロテ、シユネム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'ハパライム、シオン、アナハラテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'ラビテ、キシン、エベツ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'レメテ、エンガンニム、エンハダ、ベテパツゼズなどなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'その境界タボル、シヤハヂマおよびベテシメシに達しその境界ヨルダンにいたりて盡く其邑あはせて十六また之につける村々あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'イツサカルの子孫の支派が其宗族にしたがひて獲たる產業および其邑々村々は是の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, '第五にアセルの子孫の支派のために其宗族にしたがひて籤を掣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, '其境界の内はヘルカテ、ハリ、ベテン、アクサフ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'アランメレク、アマデ、ミシヤルなり其境界西の方カルメルに達しまたシホルリブナテに達し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, '日の出る方に折てベテダゴンにいたりゼブルンに達し北の方イフタヱルの谷のベテエメク及びネイエルに達し左してカブルに出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'エプロン、レホブ、ハンモン、カナにわたりて大シドンにまでいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'ラマに旋りツロの城に及びまたホサに旋りアクジブの邊にて海にいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'またウンマ、アベクおよびレホブありその邑あはせて二十二また之につける村々あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'アセルの子孫の支派がその宗族にしたがひて獲たる產業およびその邑々村々は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, '第六にナフタリの子孫のためにナフタリの子孫の宗族にしたがひて籤を掣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'その境界はヘレフより即ちザアナイムの樫の樹より起りアダミネケブおよびヤブニエルを經てラクムにいたりヨルダンにいたりて盡く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, '而して其境界西に旋りてアズノテタボルにいたり彼處よりホツコクに出で南はゼブルンに達し西はアセルに達し日の出る方はヨルダンの邊にてユダに達す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'その堅固たる邑々はヂデム、ゼル、ハンマテ、ラツカテ、キンネレテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'アダマ、ラマ、ハゾル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'ケデシ、エデレイ、エンハゾル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'イロン、ミグダルエル、ホレム、ベテアナテ、ベテシメシなど合せて十九邑亦これにつける村々あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'ナフタリの子孫の支派がその宗族にしたがひて獲たる產業およびその邑々村々は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, '第七にダンの子孫の支派のためにその宗族にしたがひて籤を掣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'その產業の境界の内はゾラ、エシタオル、イルシメシ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'シヤラビム、アヤロン、イテラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'エロン、テムナ、エクロン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'エルテケ、ギベトン、バアラテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'ヱホデ、ベネベラク、ガテリンモン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'メヤルコン、ラツコン、ヨツパと相對ふ地などなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, '但しダンの子孫の境界は初よりは廣くなれり其はダンの子孫上りゆきてライシを攻取り刃をもちてこれを撃ほろぼし之を獲て其處に住たればなり而してその先祖ダンの名にしたがびてライシをダンと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'ダンの子孫の支派がその宗族にしたがひて獲たる產業およびその邑々村々は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'かく境界を畫りて產業の地を與ふることを終ぬ而してイスラエルの子孫おのれの中にてヌンの子ヨシユアに產業を與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'すなはちヱホバの命にしたがひて彼にその求むる邑を與ふエフライムの山地なるテムナテセラ是なり彼その邑を建なほして其處に住む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, '祭司エレアザル、ヌンの子ヨシユアおよびイスラエルの子孫の支派の族長等がシロにおいて集會の幕屋の門にてヱホバの前に籤をもて分與へし產業は是のごとし斯地を分つことを終たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, '茲にヱホバ、ヨシユアに告て言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '汝イスラエルの子孫に告て言へ汝等モーセによりて我が汝らに語りおきし逃遁の邑を擇び定め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, '誤りて知ずに人を殺せる者を其處に逃れしめよ是は汝らが仇打する者を避て逃るべき處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, '斯る者は是等の邑の一に逃れゆき邑の門の入口に立てその邑の長老等の耳にその事情を述べし然る時は彼ら之をその邑に受いれ處を與へて己の中に住しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, '假令仇打する者追ゆくとも彼らその人を殺せる者を之が手に交すべからず其は彼知ずして人を殺せるにて素より之を惡みをりしに非ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'その人は會衆の前に立て審判を受るまで其時の祭司の長の死る迄その邑に住をるべし然る後その人を殺せる者己の邑に歸り往てその家にいたり己が逃いでし邑に住むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, '爰にナフタリの山地なるガリラヤのケデシ、エフライムの山地なるシケムおよびユダの山地なるキリアテアルバ(すなはちヘブロン)を之がために分ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'またヨルダンの彼旁ヱリコの東の方にてはルベンの支派の中より平地なる荒野のベゼルを擇び定めガドの支派の中よりギレアデのラモテを擇び定めマナセの支派の中よりバシヤンのゴランを擇び定めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, '是すなはちイスラエルの一切の子孫および之が中に寄寓をる他國人のために設けたる邑々にして凡て人を誤まり殺せる者を此に逃れしめ其會衆の前に立ざる中に仇打の手に死るがごときことなからしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, '茲にレビの族長等來りて祭司ヱレアザル、ヌンの子ヨシユアおよびイスラエルの子孫の支派の族長等の許にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'カナンの地シロにおいて之に語りて言ふヱホバかつて我らに住べき邑々を與ふることおよびその郊地を我らの家畜のために與ふる事をモーセによりて命じおきたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'イスラエルの子孫すなはちヱホバの命にしたがひて自己の產業の中より左の邑々とその郊地とをレビ人に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, '先コハテ人の宗族のために籤を掣り祭司アロンの子孫たるレビ人籤によりてユダの支派の中シメオンの支派の中およびベニヤミンの支派の中より十三の邑を獲');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'その餘のコハテの子孫は籤によりてエフライムの支派の宗族の中ダンの支派の中マナセの支派の半の中より十の邑を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'またゲシヨンの子孫は籤によりてイツサカルの支派の宗族の中アセルの支派の中ナフタリの支派の中およびバシヤンにあるマナセの支派の半の中より十三の邑を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'またメラリの子孫は其宗族にしたがひてルベンの支派の中ガドの支派の中およびゼブルンの支派の中より十二の邑を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'イスラエルの子孫ヱホバのモーセによりて命じたまひし所にしたがひて此の邑々とその郊地とを籤によりてレビ人に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, '即ち先ユダの子孫の支派の中およびシメオンの子孫の支派の中より左に名を擧たる邑々を與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, '是はレビの子孫コハテ人の宗族なるアロンの子孫に歸す其は彼ら第一の籤にあたりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, '即ちユダの山地なるキリアテアルバ即ちヘブロンおよびその周圍の郊地をこれに與ふ此アルバはアナクの父なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'その邑の田野およびその村々はこれをエフンネの子カレブに與へて所有となさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, '祭司アロンの子孫に與へし者は即ち人を殺し者の逃るべき邑なるヘブロンとその郊地リブナとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'ヤツテルとその郊地エシテモアとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'ホロンとその郊地デビルとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'アインとその郊地ユツタとその郊地ベテシメシとその郊地此九の邑は此ふたつの支派の中より分ちしものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'またベニヤミンの支派の中よりギベオンとその郊地ゲバとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'アナトテとその郊地アルモンとその郊地など四の邑をあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'アロンの子孫たる祭司等の邑は合せて十三邑又之につける郊地あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'この他のコハテの子孫なるレビ人の宗族籤によりてエフライムの支派の中より邑を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, '即ち之に與へしは人を殺せる者の逃るべき邑なるエフライムの山地のシケムとその郊地およびゲゼルとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'キブザイムとその郊地ベテホロンとその郊地など四の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, '又ダンの支派の中より分ちて與へし者はエルテケとその郊地ギベトンとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'アヤロンとその郊地ガテリンモンとその郊地など四の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, '又マナセの支派の半の中より分ちて與へし者はタアナクとその郊地ガテリンモンとその郊地など二の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, '外のコハテの子孫の宗族の邑は合せて十また之につける郊地あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'ゲルシヨンの子孫たるレビ人の宗族に與へし者はマナセの支派の半の中よりは人を殺せる者の逃るべき邑なるバシヤンのゴランとその郊地およびベエシテラとその郊地など二の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'イツサカルの支派の中よりはキシオンとその郊地ダベラとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'ヤルムテとその郊地エンガンニムとその郊地など四の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'アセルの支派の中よりはミシヤルとその郊地アブドンとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'ヘルカテとその郊地レホブとその郊地など四の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'ナフタリの支派の中よりは人を殺せる者の逃るべき邑なるガリラヤのケデシとその郊地およだハンモテドルとその郊地カルタンとその郊地など三の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'ゲルシヨン人がその宗族にしたがひて獲たる邑は合せて十三邑にして又これに屬る郊地あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'この餘のレビ人なるメラリの子孫の宗族に與へし者はゼブルンの支派の中よりはヨクネアムと其郊地カルタとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'デムナとその郊地ナハラルとその郊地など四の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'ルベンの支派の中よりはべゼルとその郊地ヤハヅとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'ケデモテとその郊地メバアテとその郊地など四の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'ガドの支派の中よりは人を殺せる者の逃るべき邑なるギレアデのラモテとその郊地およびマハナイムとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'ヘシボンとその郊地ヤゼルとその郊地など合せて四の邑');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, '是みな外のレビ人なるメラリの子孫がその宗族にしたがひて獲たる邑々なり其籤によりて獲たる邑は合せて十二');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'イスラエルの子孫の所有の中にレビ人が有る邑々は合せて四十八邑又之につける郊地あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'この邑々は各々その周圍に郊地あり此邑々みな然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'かくヱホバ、イスラエルに與へんとその先祖等に誓ひたまひし地をことごとく與へたまひければ彼ら之を獲て其處に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'ヱホバ凡てその先祖等に誓ひたまひし如く四方におて彼らに安息を賜へり其すべての敵の中に一人も之に當ることを得る者なかりきヱホバかれらの敵をことごとくその手に付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'ヱホバがイスラエルの家に語りたまひし善事は一だに缺ずして悉くみな來りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, '茲にヨシユア、ルベン人ガド人およびマナセの支派の半を召て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'これに言けるは汝らはヱホバの僕モーセが汝らに命ぜし所をことごとく守り又わが汝らに命ぜし一切の事において我言に聽したがへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, '汝らは今日まで日ひさしく汝らの兄弟を離れずして汝らの神ヱホバの命令の言を守り來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, '今は已に汝らの神ヱホバなんぢらの兄弟に向に宣まひし如く安息を賜ふに至れり然ば汝ら身を轉らしヱホバの僕モーセが汝らに與へしヨルダンの彼方なる汝等の產業の地に歸りて自己の天幕にゆけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, '只ヱホバの僕モーセが汝らに命じおきし誡命と律法とを善く謹しみて行ひ汝らの神ヱホバを愛しその一切の途に歩みその命令を守りて之に附したがひ心を盡し精神を盡して之に事ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'かくてヨシユア彼らを祝して去しめければ彼らはその天幕に往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'マナセの支派の半にはモーセ、バシヤンにて產業を與へおけりその他の半にはヨシユア、ヨルダンの此旁西の方にてその兄弟等の中に產業を與ふヨシユア彼らをその天幕に歸し遣るに當りて之を祝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, '之に告て言けるは汝ら衆多の貨財夥多しき家畜金銀銅鐵および夥多しき衣服をもちて汝らの天幕に歸り汝らの敵より獲たるその物を汝らの兄弟の中に分つべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, '爰にルベンの子孫ガドの子孫およびマナセの支派の半はヱホバのモーセによりて命じ給ひし所に循ひて己の所有の地すなはち已に獲たるギレアデの地に往んとてカナンの地のシロよりしてイスラエルの子孫に別れて歸りけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'ルベンの子孫ガドの子孫およびマナセの支派の半カナンの地のヨルダンの岸邊にいたるにおよびて彼處にてヨルダンの傍に一の壇を築けりその壇は大にして遥に見えわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'イスラエルの子孫はルベンの子孫ガドの子孫およびマナセの支派の半カナンの地の前の部にてヨルダンの岸邊イスラエルの子孫に屬する方にて一の壇を築けりと言を聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'イスラエルの子孫これを聞と斉しくイスラエルの子孫の會衆ことごとくシロに集まりて彼らの所に攻のぼらんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'イスラエルの子孫すなはち祭司エレアザルの子ピハネスをギレアデの地に遣はしてルベンの子孫ガドの子孫およびマナセの支派の半の所に至らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'イスラエルの各々の支派の中より父祖の家の牧伯一人づつを擧て合せて十人の牧伯を之に伴なはしむ是みなイスラエルの家族の中にて父祖の家の長たる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, '彼らギレアデの地に往きルベンの子孫ガドの子孫およびマナセの支派の半にいたりて之に語りて言けらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'ヱホバの全會衆かく言ふ汝らイスラエルの神にむかひて愆を犯し今日すでに翻へりてヱホバに從がはざらんとし即ち己のために一の壇を築きて今日ヱホバに叛かんとするは何事ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'ベオルの罪われらに足ざらんや之がためにヱホバの會衆に災禍くだりたりしかども我ら今日までも尚身を潔めてその罪を棄ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, '然るに汝らは今日ひるがへりてヱホバに從がはざらんとするや汝ら今日ヱホバに叛けば明日はヱホバ、イスラエルの全會衆を怒りたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, '然ながら汝らの所有の地もし潔からずばヱホバの幕屋のたてるヱホバの產業の地に濟り來て我らの中にて所有を獲よ惟われらの神ヱホバの壇の外に壇を築きてヱホバに叛く勿れまた我らに悖るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'ゼラの子アカン詛はれし物につきて愆を犯しつひにイスラエルの全會衆に震怒臨みしにあらずや且また其罪にて滅亡し者は彼人ひとりにはあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'ルベンの子孫ガドの子孫およびマナセの支派の半答へてイスラエルの宗族の長等に言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '諸の神の神ヱホバ諸の神の神ヱホバ知しめすイスラエルも亦知んもし叛く事あるひはヱホバに罪を犯す事ならば汝今日我らを救ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, '我らが壇を築きし事もし翻がへりてヱホバに從がはざらんが爲なるか又は其上に燔祭素祭を献げんが爲なるか又はその上に酬恩祭の犠牲を獻げんがためならばヱホバみづからその罪を問討したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, '我等は遠き慮をもて故に斯なしたるなり即ち思ひけらく後の日にいたりて汝らの子孫われらの子孫に語りて言ならん汝らはイスラエルの神ヱホバと何の關係あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'ルベンの子孫およびガドの子孫よヱホバ我らと汝らの間にヨルダンを界となしたまへり汝らはヱホバの中に分なしと斯いひてなんぢらの子孫われらの子孫としてヱホバを畏るることを息しめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, '是故に我ら言けらく我らいま一の壇を我らのために築かんと是燔祭のために非ずまた犠牲のために非ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, '惟し之をして我らと汝らの間および我らの後の子孫の間に證とならしめて我ら燔祭犠牲および酬恩祭をもてヱホバの前にその職務をなさんがためなり然せば汝らの子孫後の日いたりて我らの子孫に汝らはヱホバの中に分なしと言こと無らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, '是をもて我ら言り彼らが我らまたは後の日に我らの子孫に然いはばその時我ら言ん我らの父祖の築きたりしヱホバの壇の模形を見よ是は燔祭のためにも非ずまた犠牲のためにもあらず我らと汝らとの間の證なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'ヱホバに叛き翻へりて今日ヱホバに從がふことを息め我らの神ヱホバの幕屋の前にあるその祭壇の外に燔祭素祭犠牲などのために壇を築くことは我らの絶て爲ざる所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, '祭司ピネハスおよび會衆の長等即ち彼とともなるイスラエルの宗族の首等はルベンの子孫ガドの子孫およびマナセの子孫が述たる言を聞て善とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, '祭司エレアザルの子ピネハスすなはちルベンの子孫ガドの子孫およびマナセの子孫に言けるは我ら今日ヱホバの我らの中に在すを知る其は汝らヱホバにむかひて此愆を犯さざればなり今なんぢらはイスラエルの子孫をヱホバの手より救ひいだせりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, '祭司エレアザルの子ピネハスおよび牧伯等すなはちルベンの子孫およびガドの子孫に別れてギレアデの地よりカナンの地に歸りイスラエルの子孫にいたりて復命しけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'イスラエルの子孫これを善とせり而してイスラエルの子孫神を讃めルベンの子孫およびガドの子孫の住をる國を滅ぼしに攻上らんと重ねて言ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'ルベンの子孫およびガドの子孫その壇をエド(證)と名けて云ふ是は我らの間にありてヱホバは神にいますとの證をなす者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'ヱホバ、イスラエルの四方の敵をことごとく除きて安息をイスラエルに賜ひてより久しき後すなはちヨシユア年邁みて老たる後');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'ヨシユア一切のイスラエル人すなはち其長老首領裁判人官吏などを招きよせて之に言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, '我は年すすみて老ゆ汝らは已に汝らの神ヱホバが汝らのために此もろもろの國人に行ひたまひし事を盡く見たり即ち汝らの神ヱホバみづから汝らのために戰ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, '視よ我ヨルダンより日の入る方大海までの此もろもろの漏のこれる國々および已に滅ぼしたる一切の國々を籤にて汝らに分ちて汝らの支派の產業となさしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, '汝らの神ヱホバみづから汝らの前よりその國民を打攘ひ汝らの目の前よりこれを逐はらひたまはん而して汝らは汝らの神ヱホバの汝らに宣まひしごとく之が地を獲にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, '然ば汝ら勵みてモーセの律法の書に記されたる所を盡く守り行なへ之を離れて右にも左にも曲るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, '汝らの中間に遺りをる是等の國人の中に往なかれ彼らの神の名を唱ふるなかれ之を指て誓はしむる勿れ又これに事へこれを拝むなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, '惟今日まで爲たるごとく汝らの神ヱホバに附したがへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'それヱホバは大にして且強き國民を汝らの前より逐はらひたまへり汝らには今日まで當ることを得る人一箇もあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, '汝らの一人は千人を逐ことを得ん其は汝らの神ヱホバ汝らに宣まひしごとく自ら汝らのために戰ひたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, '然ば汝ら自ら善く愼しみて汝らの神ヱホバを愛せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, '然らずして汝ら若後もどりしつつ是等の國人の漏のこりて汝らの中間に止まる者等と親しくなり之と婚姻をなして互に相往來しなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, '汝ら確く知れ汝らの神ヱホバかさねて是等の國人を汝らの目の前より逐はらひたまはじ彼ら反て汝らの羂となり罟となり汝らの脇に鞭となり汝らの目に莿となりて汝ら遂に汝らの神ヱホバの汝らに賜ひしこの美地より亡び絶ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, '視よ今日われは世人の皆ゆく途を行んとす汝ら一心一念に善く知るならん汝らの神ヱホバの汝らにつきて宣まひし諸の善事は一も缺る所なかりき皆なんぢらに臨みてその中一も缺たる者なきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, '汝らの神ヱホバの汝らに宣まひし諸の善事の汝らに臨みしごとくヱホバまた諸の惡き事を汝らに降して汝らの神ヱホバの汝らに與へしこの美地より終に汝らを滅ぼし絶たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, '汝ら若なんぢらの神ヱホバの汝らに命じたまひしその契約を犯し往て他神に事へてこれに身を鞠むるに於てはヱホバの震怒なんぢらに向ひて燃いでてなんぢらヱホバに與へられし善地より迅速に亡びうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, '茲にヨシユア、イスラエルの一切の支派をシケムに集めイスラエルの長老首領裁判人官吏などを招きよせて諸共に神の前に進みいで');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, '而してヨシユアすべての民に言けるはイスラヱルの神ヱホバかく言たまふ汝らの遠祖すなはちアブラハムの父たりナホルの父たりしテラのごときは在昔河の彼旁に住て皆他神に事へたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, '我なんぢらの先祖アブラハムを河の彼旁より携へ出してカナンの全地を導きてすぎその子孫を増んとして之にイサクを與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, '而してイサクにヤコブとエサウを與へエサウにセイル山を與へて獲させたりまたヤコブとその子等はエジプトに下れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, '我モーセおよびアロンを遣はしまた災禍をエジプトに降せり我がその中に爲たる所の事のごとし而して後われ汝らを導びき出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, '我なんぢらの父をエジプト入り導き出し汝ら海に至りしにエジプト人戰車と騎兵とをもて汝らの後を追て紅海に來りけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, '汝らの父等ヱホバに呼はりければヱホバ黑暗を汝らとエジプト人との間に置き海を彼らの上に傾むけて彼らを淹へり汝らは我がエジプトにて爲たる事を目に觀たり斯て汝らは日ひさしく曠野に住をれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, '我またヨルダンの彼旁にすめるアモリ人の地に汝らを携へいれたり彼ら汝らと戰ひければ我かれらを汝らの手に付しかれらの地をなんぢらに獲しめ彼らを汝らの前より滅ぼし去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, '時にモアブの王チツポルの子バラク起てイスラエルに敵し人を遣はしてペオルの子バラムを招きて汝らを詛はせんとしたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, '我バラムに聽ことを爲ざりければ彼かへつて汝らを祝せり斯われ汝らを彼の手より拯出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, '而して汝らヨルダンを濟りてヱリコに至りしにヱリコの人々すなはちアモリ人ペリジ人カナン人ヘテ人ギルガシ人ヒビ人ヱブス人等なんぢらに敵したりしが我かれらを汝らの手に付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'われ黄蜂を汝らの前に遣はして彼のアモリ人の王二人を汝らの前より逐はらへり汝らの劍または汝らの弓を用ひて斯せしに非ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, '而して我なんちらが勞せしに非ざる地を汝らに與へ汝らが建たるに非ざる邑を汝らに與へたり汝らは今その中に住をる汝らは亦己が作りたるに非ざる葡萄園と橄欖園とにつきて食ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, '然ば汝らヱホバを畏れ赤心と眞實とをもて之に事へ汝らの先祖が河の彼邊およびエジプトにて事へたる神を除きてヱホバに事へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, '汝ら若ヱホバに事ふることを惡とせば汝らの先祖が河の彼邊にて事へし神々にもあれ又は汝らが今をる地のアモリ人の神々にもあれ汝らの事ふべき者を今日選べ但し我と我家とは共にヱホバに事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, '民こたへて言けるはヱホバを棄て他神に事ふることは我等きはめて爲じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, '其は我らの神ヱホバみづから我等と我らの先祖とをエジプトの地奴隸の家より導き上りかつ我らの目の前にかの大なる徴を行ひ我らが往し一切の路にて我らを守りまた我らが其中間を通りし一切の民の中にて我らを守りたまひければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, '而してヱホバ此地に住をりしアモリ人などいふ一切の民を我らの前より逐はらひたまへり然ば我らもヱホバに事へん彼は我らの神なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'ヨシユア民に言けるは汝らはヱホバに事ふること能はざらん其は彼は聖神また妬みたまふ神にして汝らの罪愆を赦したまはざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, '汝ら若ヱホバを棄て他神に事へなば汝らに福祉を降したまへる後にも亦ひるがへりて汝らに災禍を降して汝らを滅ぼしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, '民ヨシユアに言けるは否我ら必らずヱホバに事ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'ヨシユア民に向ひて汝らはヱホバを選びて之に事へんといへりなんぢら自らその證人たりと言ければ皆我らは證人なりと答ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'ヨシユアまた言り然ば汝らの中にある異なる神を除きてイスラエルの神ヱホバに汝らの心を傾むけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, '民ヨシユアに言けるは我らの神ヱホバに我らは事へ其聲に我らは聽したがふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'ヨシユアすなはち其日民と契約を結びシケムにおいて法度と定規とを彼らのために設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'ヨシユアこれらの言を神の律法の書に書しるし大なる石をとり彼處にてヱホバの聖所の傍なる樫の樹の下に之を立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, '而してヨシユア一切の民に言けるは視よ此石われらの證となるべし是はヱホバの我らに語りたまひし言をことごとく聞たればなり然ば汝らが己の神を棄ること無らんために此石なんぢらの證となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'かくてヨシユア民を各々その產業に歸しさらしめたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, '是らの事の後ヱホバの僕ヌンの子ヨシユア百十歳にして死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, '人衆これをその產業の地の内にてテムナテセラに葬むれりテムナテセラはエフライムの山地にてガアシ山の北にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'イスラエルはヨシユアの世にある日の間またヱホバがイスラエルのために行ひたまひし諸の事を識ゐてヨシユアの後に生存れる長老等の世にある日の間つねにヱホバに事へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'イスラエルの子孫のエジプトより携さへ上りしヨセフの骨を昔ヤコブが銀百枚をもてシケムの父ハモルの子等より買たりしシケムの中なる一の地に葬れり是はヨセフの子孫の產業となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'アロンの子エレアザルもまた死り人衆これを其子ピネハスがエフライムの山地にて受たりし岡に葬れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'ヨシユアの死にたるのちイスラエルの子孫ヱホバに問ひていひけるはわれらの中孰か先に攻め登りてカナン人と戰ふべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'ヱホバいひたまひけるはユダ上るべし視よ我此國を其の手に付すと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'ユダその兄弟シメオンに言けるは我と共にわが領地にのぼりてカナン人と戰へわれもまた偕に汝の領地に往べしとここにおいてシメオンかれとともにゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'ユダすなはち上りゆきけるにヱホバその手にカナン人とペリジ人とを付したまひたればベゼクにて彼ら一萬人を殺し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'またベゼクにおいてアドニベゼクにゆき逢ひこれと戰ひてカナン人とペリジ人を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'しかるにアドニベゼク逃れ去りしかばそのあとを追ひてこれを執へその手足の巨擘を斫りはなちたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'アドニベゼクいひけるは七十人の王たちかつてその手足の巨擘を斫られて我が食几のしたに屑を拾へり神わが曾て行ひしところをもてわれに報いたまへるなりと衆之を曳てエルサレムに至りしが其處にしねり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'ユダの子孫エルサレムを攻めてこれを取り刃をもてこれを撃ち邑に火をかけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'かくてのちユダの子孫山と南方の方および平地に住めるカナン人と戰はんとて下りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'ユダまづヘブロンに住るカナン人を攻めてセシヤイ、アヒマンおよびタルマイを殺せり〔ヘブロンの舊の名はキリアテアルバなり〕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'またそこより進みてデビルに住るものを攻む〔デビルの舊の名はキリアテセペルなり〕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, '時にカレブいひけるはキリアテセペルをうちてこれを取るものにはわが女アクサをあたへて妻となさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'カレブの舍弟ケナズの子オテニエルこれを取ければすなはちその女アクサをこれが妻にあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'アクサ往くときおのれの父に田圃を求めんことを夫にすすめたりしがつひにアクサ驢馬より下りければカレブこれは何事ぞやといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, '答へけるはわれに惠賜をあたへよなんぢ南の地をわれにあたへたればねがはくは源泉をもわれにあたへよとここにおいてカレブ上の源泉と下の源泉とをこれにあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'モーセの外舅ケニの子孫ユダの子孫と偕に棕櫚の邑よりアラドの南なるユダの野にのぼり來りて民のうちに住居せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, '茲にユダその兄弟シメオンとともに往きてゼバテに住るカナン人を撃ちて盡くこれを滅ぼせり是をもてその邑の名をホルマと呼ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'ユダまたガザと其の境アシケロンとその境およびエクロンとその境を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'ヱホバ、ユダとともに在したればかれつひに山地を手に入れたりしが谷に住る民は鐵の戰車をもちたるが故にこれを逐出すこと能はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, '衆モーセのかつていひし如くヘブロンをカレブに與ふカレブそのところよりアナクの三人の子をおひ出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'ベニヤミンの子孫はエルサレムに住るエブス人を追出さざりしりかばエブス人は今日に至るまでベニヤミンの子孫とともにエルサレムに住ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, '茲にヨセフの族またベテルをさして攻め上るヱホバこれと偕に在しき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'ヨセフの族すなはちベテルを窺察しむ〔此邑の舊の名はルズなり〕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'その間者邑より人の出來るを見てこれにいひけるは請ふわれらに邑の入口を示せさらば汝に恩慈を施さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, '彼邑の入口を示したればすなはち刃をもて邑を撃てり然ど彼の人と其家族をばみな縱ち遣りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'その人ヘテ人の地にゆき邑を建てルズと名けたり今日にいたるまでこれを其名となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'マナセはベテシヤンとその村里の民タアナクとその村里の民ドルとその村里の民イプレアムとその村里の民メギドンとその村里の民を逐ひ出さざりきカナン人はなほその地に住ひ居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'イスラエルはその強なりしときカナン人をして貢を納れしめたりしが之を全く追ひいだすことは爲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'エフライムはゲゼルに住るカナン人を逐ひいださざりきカナン人はゲゼルにおいてかれらのうちに住み居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'ゼブルンはまたキテロンの民およびナハラルの民を逐ひいださざりきカナン人かれらのうちに住みて貢ををさむるものとなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'アセルはアツコの民およびシドン、アヘラブ、アクジブ、ヘルバ、アピク、レホブの民を逐ひ出さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'アセル人は其地の民なるカナン人のうちに住み居たりそはこれを逐ひ出さざりしゆゑなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'ナフタリはベテシメシの民およびベテアナテの民を逐ひ出さずその地の民なるカナン人のうちに住み居たりベテシメシとベテアナテの民はつひにかれらに貢を納むるものとなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'アモリ人ダンの子孫を山におひこみ谷に下ることを得させざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'アモリ人はなほヘレス山アヤロン、シヤラビムに住ひ居りしがヨセフの家の手力勝りたれば終に貢を納むるものとなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'アモリ人の界はアクラビムの阪よりセラを經て上に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'ヱホバの使者ギルガルよりボキムに上りていひけるは我汝等をエジプトより上らしめわが汝らの先祖に誓ひたる地に携へ來れりまた我いひけらくわれ汝らと締べる契約を絶てやぶることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, '汝らはこの國の民と契約を締ぶべからずかれらの祭壇を毀つべしとしかるに汝らはわが聲に從はざりき汝ら如何なれば斯ることをなせしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, '我またいひけらくわれ汝らの前より彼らを追ふべからずかれら反て汝等の肋を刺す荊棘とならんまた彼らの神々は汝等の罟となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'ヱホバの使これらの言をイスラエルのすべての子孫に語しかば民聲をあげて哭ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, '故に其所の名をボキム(哭者)と呼ぶかれら彼所にてヱホバに祭物を獻げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'ヨシユア民を去しめたればイスラエルの子孫おのおのその領地におもむきて地を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'ヨシユアの世にありし間またヨシユアより後に生きのこりたる長老等の世にありしあひだ民はヱホバに事へたりこの長老等はヱホバのかつてイスラエルのために成したまひし諸の大なる行爲を見しものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'ヱホバの僕ヌンの子ヨシユア百十歳にて死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, '衆人エフライムの山のテムナテヘレスにあるかれらの產業の地においてガアシ山の北にこれを葬れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'かくてまたその時代のものことごとくその先祖のもとにあつめられその後に至りて他の時代おこりしが是はヱホバを識ずまたそのイスラエルのために爲したまひし行爲をも識ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'イスラエルの子孫ヱホバのまへに惡きことを作してバアリムにつかへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'かつてエジプトの地よりかれらを出したまひしその先祖の神ヱホバを棄てて他の神すなはちその四周なる國民の神にしたがひ之に跪づきてヱホバの怒を惹起せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, '即ちかれらヱホバをすててバアルとアシタロテに事へたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'ヱホバはげしくイスラエルを怒りたまひ掠むるものの手にわたして之を掠めしめかつ四周なるもろもろの敵の手にこれを賣たまひしかばかれらふたたびその敵の前に立つことを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'かれらいづこに往くもヱホバの手これに災をなしぬ是はヱホバのいひたまひしごとくヱホバのこれに誓ひたまひしごとしここにおいてかれら惱むこと甚だしかりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'ヱホバ士師を立てたまひたればかれらこれを掠むるものの手よりすくひ出したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, '然るにかれらその士師にもしたがはず反りて他の神を慕て之と淫をおこなひ之に跪き先祖がヱホバの命令に從がひて歩みたることろの道を頓に離れ去りてその如くには行はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'かれらのためにヱホバ士師を立てたまひし時に方りてはヱホバつねにその士師とともに在しその士師の世に在る間はヱホバかれらを敵の手よりすくひ出したまへり此はかれらおのれを虐げくるしむるものありしを呻きかなしめるによりてヱホバ之を哀れみたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'されどその士師の死しのちまた戻きて先祖よりも甚だしく邪曲を行ひ他の神にしたがひてこれに事へ之に跪きておのれの行爲を息めずその頑固なる路を離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, '是をもてヱホバはげしくイスラエルをいかりていひたまはく此民はわがかつてその列祖に命じたる契約を犯し吾聲に從がはざるがゆゑに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, '我もまたいまよりはヨシユアがその死しときに存しおけるいづれの國民をもかれらのまへより逐ひはらはざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, '此は我イスラエルがその先祖の守りしごとくヱホバの道を守りてこれに歩むやいなやを試みんがためなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'ヱホバはこれらの國民を逐はらふことを速にせずして之を遺しおきてヨシユアの手に付したまはざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'ヱホバが凡てカナンの諸の戰爭を知ざるイスラエルの者どもをこころみんとて遺しおきたまへる國民は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, '〔こはただイスラエルの代々の子孫特にいまだ戰爭を知ざるものにこれををしへ知らしめんがためなり〕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, '即ちペリシテ人の五人の伯すべてのカナン人シドン人およびレバノン山に住みてバアルヘルモンの山よりハマテに入るところまでを占めたるヒビ人是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'これらをもてイスラエルをこころみかれらがヱホバのモーセによりてその先祖に命じたまひし命令に遵ふや否を可知りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'イスラエルの子孫はカナン人ヘテ人アモリ人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'ペリジ人ヒビ人エブス人のうちに住みかれらの女を妻に娶りまたおのれの女をかれらの子に與へかつかれらの神に事へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, '斯くイスラエルの子孫ヱホバのまへに惡をおこなひ己れの神なるヱホバをわすれてバアリムおよびアシラに事へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, '是においてヱホバはげしくイスラエルを怒りてこれをメソポタミヤの王クシヤンリシヤタイムの手に賣り付したまひしかばイスラエルの子孫はおよそ八年のあひだクシヤンリシヤタイムにつかへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, '茲にイスラエルの子孫ヱホバによばはりしかばヱホバはイスラエルの子孫の爲にひとりの救者を起して之を救はしめ給ふすなはちカレブの舍弟ケナズの子オテニエル是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'ヱホバの靈オテニエルにのぞみたれば彼イスラエルを治め戰ひに出づヱホバ、メソポタミヤの王クシヤンリシヤタイムをその手に付したまひたればオテニエルの手クシヤンリシヤタイムに勝ことを得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'かくて國は四十年のあひだ太平なりきケナズの子オテニエルつひに死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'イスラエルの子孫復ヱホバの眼のまへに惡をおこなふヱホバかれらがヱホバのまへに惡をおこなふによりてモアブの王エグロンをつよくなしてイスラエルに敵せしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'エグロンすなはちアンモンおよびアマレクの子孫を招き聚め往きてイスラエルを撃ち椶櫚の邑を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'ここにおいてイスラエルの子孫は十八年のあひだモアブの王エグロンに事へたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'イスラエルの子孫ヱホバに呼はりけるときヱホバかれらの爲に一個の救者を起したまふすなはちベニヤミン人ゲラの子なる左手利捷のエホデ是なりイスラエルの子孫かれを以てモアブの王エグロンに餽物せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'エホデ長一キユビトなる兩刃の劍を作らせこれを衣のしたに右の股のあたりにおび');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, '餽物を齎してモアブの王エグロンのもとに詣るエグロンは甚だ肥たる人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'さて餽物を獻ぐることをはりしかば彼餽物を負ひ來りしものをかへし去らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, '自らはギルガルの傍なる石像の在る所より引き回していひけるは王よ我爾に告ぐべき密事ありと王人拂を命じたればその旁に立つものみな出で去りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'エホデすなはち王のところに入來れり時に王はひとり上なる涼殿に坐し居たりしがエホデ我神の命に由りて爾に傳ふべきことありといひければ王すなはち座より起に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'エホデ左の手を出し右の股より劍を取りてその腹を刺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, '抦もまた刃とともに入りたりしが脂肉刃を塞ぎて之を腹より拔き出すことあたはずその鋒鋩うしろに出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'エホデすなはち廊をとほりてその後に樓の戸を閉てこれを鎖せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'その出でしのち王の僕來りて樓の戸の鎖したるを見いひけるは王はかならず涼殿の間に足を蔽ひ居るならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, '僕ども耻るまでに俟居たれど王樓の戸をひらかざれば鑰をとりて之を開き見るにその君は地に仆れて死をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'エホデは彼等の猶豫ふ間に逃れて石像の在るところを過りセイラテに遁げゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'かれ旣に至りエフライムの山に箛を吹きければイスラエルの子孫これとともに山より下るエホデこれを導けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'かれ人衆にいひけるは我に續て來れヱホバ汝等の敵モアブ人を汝等の手に付したまふなりここにおいてかれらエホデにしたがひて下りモアブにおもむくところのヨルダンの津を取りて一人も渡ることを允さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'そのとき彼らモアブ人およそ一萬人を殺せり是皆肥太たる勇士なりそのうち一人も脱れたるものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'モアブはその日イスラエルの手に服せり而して國は八十年の間太平なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'エホデの後にアナテの子シヤムガルといふものあり牛の策を以てペリシテ人六百人を殺せり此人もまたイスラエルを救へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'エホデの死たるのちイスラエルの子孫復ヱホバの目前に惡を行しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'ヱホバ、ハゾルにて世を治むるカナンの王ヤビンの手に之を賣たまふヤビンの軍勢の長はシセラといふ彼異邦人のハロセテに住居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, '鐵の戰車九百輌を有居て二十年の間イスラエルの子孫を甚だしく虐げしかばイスラエルの子孫ヱホバに呼はれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, '當時ラピドテの妻なる預言者デボラ、イスラエルの士師なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, '彼エフライムの山のラマとベテルの間に在るデボラの棕櫚の樹の下に坐せりイスラエルの子孫はその許に上りて審判を受く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'デボラ人をつかはしてケデシ、ナフタリよりアビノアムの子バラクを招きこれにいひけるはイスラエルの神ヱホバ汝に斯く命じたまふにあらずやいはく汝ナフタリの子孫とゼブルンの子孫とを一萬人ひきゐゆきてタボル山におもむけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, '我ヤビンの軍勢の長シセラおよびその戰車とその群衆とをキシオン河に引き寄せて汝のもとに至らせ之を汝の手に付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'バラク之にいひけるは汝もし我とともにゆかば我往べし然ど汝もし我とともに行ずば我行ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'デボラいひけるは我かならず汝とともに往くべし然ど汝は今往くところの途にては榮譽を得ることなからんヱホバ婦人の手にシセラを賣りたまふべければなりとデボラすなはち起ちてバラクと共にケデシに往けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'バラク、ゼブルンとナフタリをケデシに招き一萬人を從へて上るデボラもまた之とともに上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'ここにケニ人ヘベルといふ者あり彼はモーセの外舅ホバブの裔なるがケニを離れてケデシの邊なるザアナイムの橡の樹のかたはらにその天幕を張り居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, '衆アビノアムの子バラクがタボル山に上れるよしをシセラに告げたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'シセラそのすべての戰車すなはち鐵の戰車九百輌およびおのれとともに在るすべての民を異邦人のハロセテよりキシオン河に招き集へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'デボラ、バラクにいひけるは起よ是ヱホバがシセラを汝の手に付したまふ日なりヱホバ汝に先き立ちて出でたまひしにあらずやとバラクすなはち一萬人をしたがへてタボル山より下る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'ヱホバ刃をもてシセラとその諸の戰車およびその全軍をバラクの前に打敗りたまひたればシセラ戰車より飛び下り徒歩になりて遁れ走れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'バラク戰車と軍勢とを追ひ撃て異邦人のハロセテに至れりシセラの軍勢は悉く刃にたふれて殘れるもの一人もなかりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'シセラは徒歩にて奔りケニ人ヘベルの妻ヤエルの天幕に來れり是はハゾルの王ヤビンとケニ人ヘベルの家とは互ひに睦じかりしゆゑなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'ヤエル出來りてシセラを迎へ之にいひけるは來れわが主よ入り來れ怖るるなかれとシセラその天幕に入たればヤエル被をもてこれを覆へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'シセラ之にいひけるはねがはくは少しの水をわれに飮ませよ我渇けりとヤエルすなはち乳嚢を啓きて之に飮ませまた之を覆へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'シセラまた之にいひけるは天幕の門邊に立て居れもし人來り汝にとふて誰かここに居るやといはば否と答ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, '彼疲れて熟睡せしかばヘベルの妻ヤエル天幕の釘子を取り手に鎚を携へてそのかたはらに忍び寄り鬢のあたりに釘子をうちこみて地に刺し通したればシセラすなはち死たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'バラク、シセラを追ひ來りしときヤエル之を出むかへていひけるは來れ我汝の索るところの人を示さんとかれそのところに入て見にシセラ鬢のあたりに釘子うたれて死たふれをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'その日に神カナンの王ヤビンをイスラエルの子孫のまへに打敗りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'かくてイスラエルの子孫の手ますます強くなりてカナンの王ヤビンに勝ちつひにカナンの王ヤビンを亡ぼすに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'その日デボラとアビノアムの子バラク謳ひていはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'イスラエルの首長みちびきをなし民また好んで出でたればヱホバを頌美よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'もろもろの王よ聽けもろもろの伯よ耳をかたぶけよ我はそのヱホバに謳はん我はイスラエルの神ヱホバを讚へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'ああヱホバよ汝セイルより出でエドムの野より進みたまひしとき地震ひ天また滴りて雲水を滴らせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'もろもろの山はヱホバのまへに撼動ぎ彼のシナイもイスラエルの神ヱホバのまへに撼動げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'アナテの子シヤムガルのときまたヤエルの時には大路は通行る者なく途行く人は徑を歩み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'イスラエルの村莊には住者なく住む者あらずなりけるがつひに我デボラ起れり我起りてイスラエルに母となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, '人々新しき神を選みければ戰鬪門におよべりイスラエルの四萬人のうちに盾或は鎗の見しことあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, '吾が心は民のうちに好んでいでたるイスラエルの有司等に傾けり汝らヱホバを頌美よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'しろき驢馬に乗るもの毛氈に坐するものおよび路歩む人よ汝ら謳ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, '矢叫の聲に遠かり水汲むところにおいてヱホバの義しき所爲をとなへそのイスラエルを治理めたまふ義しき所爲を唱へよその時ヱホバの民は門に下れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, '興よ起よデボラ興よ起よ歌を謳ふべし起てよバラク汝の俘虜を擄きたれアビノアムの子よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, '其時民の首長等の殘餘者くだり來るヱホバ勇士の中にいまして我にくだりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'エフライムより出る者ありその根アマレクにありベニヤミン汝のあとにつきて汝の民の中にありマキルよりは牧伯下りゼブルンよりは采配を執るものいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'イッサカルの伯たちはデボラとともに居るイッサカルはバラクとおなじく足の進みて平地に至るルベンの河邊にて大に心にはかる事あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, '何故に汝は圈のうちに止まりて羊の群に笛吹くを聽くやルベンの河邊にて大に心に考ふることあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'ギレアデはヨルダンの彼方に臥し居る何故にダンは舟のかたはらに止まりしやアセルは濱邊に坐してその港に臥し居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'ゼブルンは生命を捐て死を冒せる民なり野の高きところに居るナフタリまた是の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'もろもろの王來りて戰へる時にカナンのもろもろの王メギドンの水の邊においてタアナクに戰へり彼ら一片の貨幣をも獲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, '天よりこれを攻るものありもろもろの星其の道を離れてシセラを攻む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'キシオンの河之を押し流しぬ是彼の古への河キシオンの河なりわが靈魂よ汝ますます勇みて進め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'その時馬の蹄は強きももの馳に馳るに由りて地を踏鳴せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'ヱホバの使いひけるはメロズを詛ふべし汝ら重ね重ねその民を詛ふべきなり彼等來りてヱホバを助けずヱホバを助けて猛者を攻めざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'ケニ人ヘベルの妻ヤエルは婦女のうちの最も頌むべき者なり彼は天幕に居る婦女のうち最も頌むべきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'シセラ水を乞ふにヤエル乳を與ふ即ち貴き盤に乳の油を盛てささぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'ヤエル釘子に手をかけ右の手に重き椎をとりてシセラを打ちその頭を碎きその鬢のあたりをうちて貫ぬく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'シセラ、ヤエルの足の間に屈みて仆れ偃しその足のあはひに屈みて仆れその屈みたる所にて仆れ亡ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'シセラの母窓より望み格子のうちより叫びて言ふ彼が車のきたること何て遲きや彼が馬の歩何てはかどらざるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'その賢き侍女こたへをなす(母また獨語して斯いへり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'かれら獲ものしてこれを分たざらんや人ごとに一人二人の女子を獲んシセラの獲るものは彩る衣ならんその獲る者は彩る衣にして文繍を施せる者ならん即ち彩りて兩面に文繍をほどこせる衣をえてその頸にまとはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'ヱホバよ汝の敵みな是のごとくに亡びよかしまたヱホバを愛するものは日の眞盛に昇るが如くなれよかし とかくて後國は四十年のあひだ太平なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'イスラエルの子孫またヱホバの目のまへに惡を行ひたればヱホバ七年の間之をミデアン人の手に付したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'ミデアン人の手イスラエルにかてりイスラエルの子孫はミデアン人の故をもて山にある窟と洞穴と要害とをおのれのために造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'イスラエル人蒔種してありける時しもミデアン人アマレキ人及び東方の民上り來りて押寄せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'イスラエル人に向ひて陣を取り地の產物を荒してガザにまで至りイスラエルのうちに生命を維ぐべき物を遺さず羊も牛も驢馬も遺ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, '夫この衆人は家畜と天幕を携へ上り蝗蟲の如くに數多く來れりその人と駱駝は數ふるに勝ず彼ら國を荒さんとて入きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'かかりしかばイスラエルはミデアン人のために大いに衰へイスラエルの子孫ヱホバに呼れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'イスラエルの子孫ミデアン人の故をもてヱホバに呼はりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'ヱホバひとりの預言者をイスラエルの子孫に遣りて言しめたまひけるはイスラエルの神ヱホバ斯くいひたまふ我かつて汝らをエジプトより上らせ汝らを奴隸たるの家より出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'エジプト人の手およびすべて汝らを虐ぐるものの手より汝らを拯ひいだし汝らの前より彼らを追ひはらひてその邦土を汝らに與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, '我また汝らに言り我は汝らの神ヱホバなり汝らが住ひ居るアモリ人の國の神を懼るるなかれとしかるに汝らは我が聲に從はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, '茲にヱホバの使者來りてアビエゼル人ヨアシの所有なるオフラの橡の樹のしたに坐す時にヨアシの子ギデオン、ミデアン人に奪はれざらんために酒榨のなかに麥を打ち居たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'ヱホバの使之に現れて剛勇丈夫よヱホバ汝とともに在すといひたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'ギデオン之にいひけるはああ吾が主よヱホバ我らと偕にいまさばなどてこれらのことわれらの上に及びたるやわれらの先祖がヱホバは我らをエジプトより上らしめたまひしにあらずやといひて我らに告たりしその諸の不思議なる行爲は何處にあるや今はヱホバわれらを棄てミデアン人の手に付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'ヱホバ之を顧みていひたまひけるは汝此汝の力をもて行きミデアン人の手よりイスラエルを拯ひいだすべし我汝を遣すにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'ギデオン之にいひけるはああ主よ我何をもてかイスラエルを拯ふべき視よわが家はマナセのうちの最も弱きもの我はまた父の家の最も卑賤きものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'ヱホバ之にいひたまひけるは我かならず汝とともに在ん汝は一人を撃がごとくにミデアン人を撃つことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'ギデオン之にいひけるは我もし汝のまへに恩を蒙るならば請ふ我と語る者の汝なる證據を見せたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'ねがはくは我復び汝に來りわが祭物をたづさへて之を汝のまへに供ふるまでここを去たまふなかれ彼いひたまひけるは我汝の還るまで待つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'ギデオンすなはち往て山羊の羔を調へ粉一エパをもて無酵パンをつくり肉を筺にいれ羹を壺に盛り橡樹の下にもち出て之を供へたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, '神の使之にいひたまひけるは肉と無酵パンをとりて此巖のうへに置き之に羹を斟げとすなはちそのごとくに行ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'ヱホバの使手にもてる杖の末端を出して肉と無酵パンに觸れたりしかば巖より火燃えあがり肉と無酵パンを燒き盡せりかくてヱホバの使去てその目に見ずなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'ギデオン是において彼がヱホバの使者なりしを覺りギデオンいひけるはああ神ヱホバよ我面を合せてヱホバの使者を見たれば將如何せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'ヱホバ之にいひたまひけるは心安かれ怖るる勿れ汝死ぬることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'ここにおいてギデオン彼所にヱホバのために祭壇を築き之をヱホバシヤロムと名けたり是は今日に至るまでアビエゼル人のオフラに存る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, '其夜ヱホバ、ギデオンにいひ給ひけるは汝の父の少き牡牛および七歳なる第二の牛を取り汝の父のもてるバアルの祭壇を毀ち其上なるアシラの像を斫り仆し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, '汝の神ヱホバのためにこの堡砦の頂において次序をただしくし祭壇を築き第二の牛を取りて汝が斫り倒せるアシラの木をもて燔祭を供ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'ギデオンすなはちその僕十人を携へてヱホバのいひたまひしごとく行へりされど父の家のものどもおよび邑の人を怖れたれば晝之をなすことを得ず夜に入りて之を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, '邑の衆朝興出て視にバアルの祭壇は摧け其の上なるアシラの像は斫仆されて居り新に築る祭壇に第二の牛の供へてありしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'たがひに此は誰が所爲ぞやと言ひつつ尋ね問ひけるに此はヨアシの子ギデオンの所爲なりといふものありたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, '邑の人々ヨアシにむかひ汝の子を曳き出して死なしめよそは彼バアルの祭壇を摧き其上に在しアシラの像を斫仆したればなりといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'ヨアシおのれの周圍に立るすべてのものにいひけるは汝らはバアルの爲に爭論ふや汝らは之を救んとするや之が爲に爭論ふ者は朝の中に死べしバアルもし神ならば人其祭壇を摧きたれば自ら爭論ふ可なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, '是をもて人衆ギデオンその祭壇を摧きたればバアル自ら之といひあらそはんといひて此日かれをヱルバアル(バアルいひあらそはん)と呼なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, '茲にミデアン人アマレク人および東方の民相集まりて河を濟りヱズレルの谷に陣を取しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'ヱホバの靈ギデオンに臨みてギデオン箛を吹たればアビエゼル人集りて之に從ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'ギデオン徧くマナセに使者を遣りしかばマナセ人また集りて之に從ふ彼またアセル、ゼブルン及びナフタリに使者を遣りしにその人々も上りて之を迎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'ギデオン神にいひけるは汝かつていひたまひしごとくわが手をもてイスラエルを救はんとしたまはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, '視よ我一箇の羊の毛を禾塲におかん露もし羊毛にのみおきて地はすべて燥きをらば我之れによりて汝がかつて言たまひし如く吾が手をもてイスラエルを救ひたまふを知んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'すなはち斯ありぬ彼明る朝早く興きいで羊毛をかき寄てその毛より露を搾りしに鉢に滿つるほどの水いできたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'ギデオン神にいひけるは我にむかひて怒を發したまふなかれ我をしていま一回いはしめたまへねがはくは我をして羊の毛をもていま一回試さしめたまへねがはくは羊毛のみを燥して地には悉く露あらしめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'その夜神かくの如くに爲したまふすなはち羊毛のみ燥きて地には凡て露ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, '斯てヱルバアルと呼るるギデオンおよび之とともにあるすべての民朝夙に興きいでてハロデの井のほとりに陣を取るミデアン人の陣はかれらの北の方にあたりモレの山に沿ひ谷のうちにありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'ヱホバ、ギデオンにいひたまひけるは汝とともに在る民は餘りに多ければ我その手にミデアン人を付さじおそらくはイスラエル我に向ひ自ら誇りていはん我わが手をもて己を救へりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'されば民の耳に告示していふべし誰にても懼れ慄くものはギレアデ山より歸り去るべしとここにおいて民のかへりしもの二萬二千人あり殘しものは一萬人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'ヱホバまたギデオンにいひたまひけるは民なほ多し之を導きて水際に下れ我かしこにて汝のために彼らを試みんおほよそ我が汝に告て此人は汝とともに行くべしといはんものはすなはち汝とともに行くべしまたおほよそ我汝に告て此人は汝とともに行くべからずといはんものはすなはち行くべからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'ギデオン民をみちびきて水際に下りしにヱホバ之にいひたまひけるはおほよそ犬の餂るがごとくその舌をもて水を餂るものは汝之を別けおくべしまたおほよそ其の膝を折り屈みて水を飮むものをも然すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, '手を口にあてて水を餂しものの數は三百人なり餘の民は盡くその膝を折り屈みて水を飮り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'ヱホバ、ギデオンにいひたまひけるは我水を餂たる三百人の者をもて汝らを救ひミデアン人を汝の手に付さん餘の民はおのおの其所に歸るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'ここにおいて彼ら民の兵粮とその箛を手にうけとれりギデオンすなはちすべてのイスラエル人を各自その天幕に歸らせ彼の三百人を留めおけり時にミデアン人の陣はその下の谷のなかにありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'その夜ヱホバ、ギデオンにいひたまはく起よ下りて敵陣に入るべし我之を汝の手に付すなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'されど汝もし下ることを怖れなば汝の僕フラを伴ひ陣所に下りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, '彼らのいふ所を聞べし然せば汝の手強くなりて汝敵陣にくだることを得んとギデオンすなはち僕フラとともに下りて陣中にある隊伍のほとりに至るに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'ミデアン人アマレク人およびすべて東方の民は蝗蟲のごとくに數衆く谷のうちに堰しをりその駱駝は濱の砂の多きがごとくにして數ふるに勝ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'ギデオン其處に至りしに或人その伴侶に夢を語りて居りすなはちいふ我夢を見たりしが夢に大麥のパンひとつミデアンの陣中に轉びいりて天幕に至り之をうち仆し覆したれば天幕倒れ臥り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, '其の伴侶答へていふ是イスラエルの人ヨアシの子ギデオンの劍に外ならず神ミデアンとすべての陣營を之が手に付したまふなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'ギデオン夢の説話とその解釋を聞しかば拜をなしてイスラエルの陣所にかへりいひけるは起よヱホバ汝らの手にミデアンの陣をわたしたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'かくて三百人を三隊にわかち手に手に箛および空瓶を取せその瓶のなかに燈火をおかしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'これにいひけるは我を視てわが爲すところにならへ我が敵陣の邊に至らんときに爲すごとく汝らも爲すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, '我およびわれとともに在るものすべて箛を吹ば汝らもまたすべて陣營の四方にて箛を吹き此ヱホバのためなりギデオンのためなりといへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, '而してギデオンおよび之とともなる百人中更の初に陣營の邊に至るにをりしも番兵を更代たるときなりければ箛を吹き手に携へたる瓶をうちくだけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, '即ち三隊の兵隊箛を吹き瓶をうちくだき左の手には燈火を執り右の手には箛をもちて之を吹きヱホバの劍ギデオンの劍なるぞと叫べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'かくておのおのその持場に立ち陣營を取り圍みたれば敵軍みな走り叫びてにげゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, '三百人のもの箛を吹くにあたりヱホバ敵軍をしてみなたがひに同士撃せしめたまひければ敵軍にげはしりてゼレラのベテシツダ、アベルメホラの境およびタバテに至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'イスラエルの人々すなはちナフタリ、アセルおよびマナセ中より集ひ來りてミデアン人を追撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'ギデオン使者をあまねくエフライムの山に遣していはせけるは下りてミデアン人を攻めベタバラにいたる渡口およびヨルダンを遮斷るべしと是においてエフライムの人盡く集ひ來りてベタバラにいたる渡口およびヨルダンを取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'ミデアン人の君主オレブとゼエブの二人を俘へてオレブをばオレブ砦の上に殺しゼエブをばゼエブの酒搾のほとりに殺しまたミデアン人を追撃ちオレブとゼエブの首を携へてヨルダンの彼方よりギデオンの許にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'エフライムの人々ギデオンにむかひ汝ミデアン人と戰はんとて往る時われらを召ざりしが斯ることを我らになすは何故ぞといひていたく之を詰りたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'ギデオン之にいひけるは今吾が成るところは汝らのなせる所に比ぶべけんやエフライムの拾ひ得し遺餘の葡萄はアビエゼルの收穫し葡萄にも勝れるならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, '神はミデアンの群伯オレブとゼエブを汝等の手に付したまへりわが成えたるところは汝らの成る所に比ぶべけんやとギデオン此の語をのべしかば彼らの憤解たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'ギデオン自己に從がへる三百人とともにヨルダンに至りて之を濟り疲れながらも仍追撃しけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, '遂にスコテの人々に言けるは願くは我にしたがへる民に食を與へよ彼等疲れをるに我ミデアンの王ゼバとザルムンナを追行なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'スコテの群伯等いひけるはゼバとザルムンナの手すでに汝の手のうちに在るや我らなんぞ汝の軍勢に食を與ふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'ギデオンいひけるは然らばヱホバの吾が手にゼバをザルムンナを付したまふときに我野の荊と棘とをもて汝の肉を打つべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'かくて其所よりペヌエルにのぼりおなじことを彼らにのべたるにペヌエルの人もスコテの人の答へしごとくに答へしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'またペヌエルの人につげていひけるは我平康に歸るときに此の城樓を毀つべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, '偖ゼバとザルムンナはその軍勢おほよそ一萬五千人をひきゐてカルコルに居る是皆東方の人の全軍の中の生殘れるものなり戰死せし者は劍を拔ところのもの十二萬人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'ギデオンすなはちノバとヨグベバの東にて天幕にすめるものの路より上りて敵軍の慮りなく居るを撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'ここにおいてゼバとザルムンナにげ走りたればギデオン之を追撃ちミデアンの二人の王ゼバとザルムンナを生捕て悉くその軍勢を敗れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, '斯てヨアシの子ギデオン、ヘレシの阪よりして戰陣よりかへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'スコテの人の少壯者一人を執へて之に尋ねたれば即ちスコテの群伯およびその長老等七十七人をこれがために書き録せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'ギデオン、スコテの人の所に詣りていひけるは汝らが曾て我を罵りゼバとザルムンナの手すでに汝の手のうちにあるや我ら何ぞ汝の疲れたる人に食をあたふべけんやと言たりしそのゼバとザルムンナを見よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'すなはちその邑の長老等を執へ野の荊と棘を取り之をもちてスコテの人を懲し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'またペヌヘルの城樓を毀ちて邑の人を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'かくてギデオン、ゼバとザルムンナにいひけるは汝らがタボルにて殺せしものは如何なるものなりしや答へていふ彼らは汝に似てみな王子の如くに見えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'ギデオンいひけるは彼らは我が兄弟我が母の子なりヱホバは活く汝らもし彼らを生し置たらば我汝らを殺すまじきをと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'すなはちその長子ヱテルに起て彼らを殺せといひたりしが彼の少者は年尚わかかりしかば懼れて劍を拔ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'ここにおいてゼバとザルムンナいひけるは汝みづから起て我らを撃よ人の如何によりてその力量異る者なりとギデオンすなはち起てゼバとザルムンナを殺しその駱駝の頸にかけたる半月の飾を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, '茲にイスラエルの衆ギデオンにいひけるは汝ミデアンの手より我らを救ひたれば汝と汝の子及び汝の孫我らを治めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'ギデオン之にいひけるは我汝らを治むることをせじまた我が子も汝らを治むべからずヱホバ汝らを治めたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'ギデオンまた之にいひけるは我汝らにひとつの願ふべきことあり汝らおのおの掠取の環を我にあたへよと是は彼らイシマエル人なるをもて金の環を着けたるに由る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, '衆答へけるは我ら悦んで之を與へんとて衣を布きおのおの掠取の環を其うちに投げいれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'ギデオンが求め得たる金の環の重量は金一千七百シケルなり外に半月の飾および耳環とミデアンの王たちの着たる紫のころもおよび駱駝の頸にかけたる鏈などもありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'ギデオン之をもて一箇のエポデを造り之をおのれの郷里オフラに藏むイスラエルみなこれを慕ひてこれと淫をおこなふこの物ギデオンと其家を陷るる罟となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'ミデアン人は是の如くイスラエルの子孫に攻ふせられてふたたびその頭を擡ることを得ざりきかくて國はギデオンの世にある中四十年の間平穩にてありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'ヨアシの子ヱルバアル往ておのれの家に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'ギデオンは妻を多く有ちたれば其身より出たる子七十人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'シケムに居しその妾またひとりの子を產たれば之をアビメレクと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'ヨアシの子ギデオン妙齡に邁みて死にアビエゼル人のオフラに在るその父ヨアシの墓に葬られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'ギデオンの死るに及びてイスラエルの子孫復ひるがへりてバアルを慕ひて之と淫をおこなひバアルベリテをおのれの神と爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'イスラエルの子孫その四周のもろもろの敵の手よりおのれを救ひ出したまひし神ヱホバを記憶えず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'またヱルバアルといふギデオンがイスラエルになせし諸の善行にしたがひて彼の家を厚く待ふことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'ヱルバアルの子アビメレク、シケムに往きその母の兄弟のもとに至りて彼らおよびすべて其母の父の家の一族に語りて云ひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'ねがはくはシケムのすべての民の耳に斯く告よヱルバアルのすべての子七十人して汝らを治むると一人して汝らを治むると孰れか汝らのためによきやまた我は汝らの骨肉なるを記えよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'その母の兄弟アビメレクのことにつきて此等の言をことごとくシケムの人々の耳に語りしに是はわれらの兄弟なりといひて心をアビメレクに傾むけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'バアルベリテの社より銀七十をとりて之に與ふアビメレクこれをもて遊蕩にして輕躁なる者等を傭ひておのれに從はせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'オフラに在る父の家に往きてヱルバアルの子なるその兄弟七十人を一つの石の上に殺せり但しヱルバアルの季の子ヨタムは身を潜めしに由て遺されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'ここにおいてシケムのすべての民およびミロの諸の人集り往てシケムの碑の旁なる橡樹の邊にてアビメレクを立て王となしけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'ヨタムにかくと告るものありければ往てゲリジム山の巓に立ち聲を揚て號びかれらにいひけるはシケムの民よ我に聽よ神また汝らに聽たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, '樹木出ておのれのうへに王を立んとし橄欖の樹に汝われらの王となれよといひけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, '橄欖の樹之にいふ我いかで人の我に取て神と人とを崇むるところのそのわが油を棄て往て樹木の上に戰ぐべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, '樹木また無花果樹に汝來りて我らの王となれといひけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, '無花果樹之にいひけらく我いかでわが甜美とわが善き果を棄て往きて樹木の上に戰ぐべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, '樹木また葡萄の樹に汝來りて我らの王となれよといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, '葡萄の樹之にいひけるは我いかで神と人を悦こばしむるわが葡萄酒を棄て往て樹木の上に戰ぐべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'ここにおいてすべての樹木荊に汝來りて我らの王となれよといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, '荊樹木にいふ汝らまことに我を立て汝らの王と爲さば來りて我が庇蔭に托れ然せずば荊より火出てレバノンの香柏を燒き殫すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, '抑汝らがアビメレクを立て王となせしは眞實と誠意をもて爲しことなるや汝等はヱルバアルと其家を善く待ひかれの手のなせし所に循ひて之にむくいしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '夫わが父は汝らのため戰ひ生命を惜まずして汝らをミデアンの手より救ひ出したるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, '汝ら今日おこりてわが父の家を攻めその子七十人を一つの石の上に殺しその侍妾の子アビメレクは汝らの兄弟なるをもて之を立てシケムの民の王となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, '汝らが今日ヱルバアルとその家になせしこと眞實と誠意をもてなせし者ならば汝らアビメレクのために悦べ彼も汝らのために悦ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, '若し然らずばアビメレクより火いでてシケムの民とミロの家を燬つくさんまたシケムの民とミロの家よりも火いでてアビメレクを燬つくすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'かくてヨタム走り遁れてベエルに往きその兄弟アビメレクの面を避て彼所に住めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'アビメレク三年の間イスラエルを治めたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, '神アビメレクとシケムの民のあひだに惡鬼をおくりたまひたればシケムの民アビメレクを欺くにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, '是ヱルバアルの七十人の子が受たる殘忍と彼らの血のこれを殺せしその兄弟アビメレクおよび彼の手に力をそへてその兄弟を殺さしめたるシケムの人々に報い來るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'シケムの人伏兵を山の巓に置て彼を窺はしめ其途を經て傍を過る者を凡て褫しめたり或人之をアビメレクに告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'ここにエベデの子ガアル其の兄弟とともにシケムに越ゆきたりしかばシケムの民かれを恃めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, '民田野に出て葡萄を收穫れこれを踐み絞りて祭禮をなしその神の社に入り食ひかつ飮みてアビメレクを詛ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'エベデの子ガアルいひけるはアビメレクは如何なるものシケムは如何なるものなればか我ら彼に從ふべき彼はヱルバアルの子に非ずやゼブルその輔佐なるにあらずやむしろシケムの父ハモルの一族に事ふべし我らなんぞ彼に事ふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, '嗚呼此の民を吾が手に屬しむるものもがな然ば我アビメレクを除かんと而してガアル、アビメレクに汝の軍勢を益て出きたれよと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, '邑の宰ゼブル、エベデの子ガアルの言をききて怒を發し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, '私かに使者をアビメレクに遣りていひけるはエベデの子ガアル及びその兄弟シケムに來り邑をさわがして汝に敵せしめんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, '然ば汝及び汝と共なる民夜の中に興て野に身を伏よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, '而て朝に至り日の昇る時汝夙く興出て邑に攻かかれガアル及び之とともなる民出て汝に當らん汝機を見てこれに事をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'アビメレクおよび之とともなるすべての民夜の中に興出て四隊に分れ身を伏てシケムを伺ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'エベデの子ガアル出て邑の門の口に立るにアビメレク及び之とともなる民その伏たるところより起りしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'ガアル民を見てゼブルにいひけるは視よ民山の峰々より下るとゼブル之に答へて汝山の影を見て人と做すのみといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'ガアルふたたび語りていひけるは視よ民地の高處より下りまた一隊は法術士の橡樹の途より來ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'ゼブル之にいひけるは汝がかつてアビメレクは何者なればか我ら之に事ふべきといひしその汝の口今いづこに在るや是汝が侮りたる民にあらずや今乞ふ出て之と戰へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'ここにおいてガアル、シケム人を率ゐ往てアビメレクと戰ひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'アビメレク之を追くづしたればガアル其まへより逃走れりかくて殺されて斃るるもの多くして邑の門の口までに及ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'かくてアビメレクはアルマに居しがゼブルはガアルおよびその兄弟等を逐いだしてシケムに居ることを得ざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'あくる日民田畑に出しに人之をアビメレクに告げしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'アビメレクおのれの民を率ゐてこれを三隊に分ち野に埋伏して伺ふに民邑より出來りたればすなはち起りて之を撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'アビメレクおよび之とともに在る隊の者は襲ひゆきて邑の門の入口に立ち餘の二隊は野に在るすべてのものをおそふて之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'アビメレク其日終日邑を攻めつひに邑を取りてそのうちの民を殺し邑を破却ちて鹽を撒布ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'シケムの櫓の人みな之を聞てベリテ神の廟の塔に入たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'シケムの櫓の人のことごとく集れるよしアビメレクに聞えければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'アビメレク己とともなる民をことごとく率ゐてザルモン山に上りアビメレク手に斧を取り木の枝を斫落し之をおのれの肩に載せ偕に居る民にむかひて汝ら吾が爲ところを見る急ぎてわがごとく爲せよといひしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, '民もまた皆おのおのその枝を斫りおとしアビメレクに從ひて枝を塔に倚せかけ塔に火をかけて彼等を攻むここにおいてシケムの櫓の人もまた悉く死り男女およそ一千人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, '茲にアビメレク、テベツに赴きテベツに對て陣を張て之を取しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, '邑のなかに一の堅固なる櫓ありてすべての男女および邑の民みな其所に遁れ往き後を鎖して櫓の頂に上りたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'アビメレクすなはち櫓のもとに押寄て之を攻め櫓の口に近きて火をもて之を焚んとせしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, '一人の婦アビメレクの頭に磨石の上層石を投げてその腦骨を碎けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'アビメレクおのれの武器を執る少者を急ぎ召て之にいひけるは汝の劍を拔て我を殺せおそらくは人吾をさして婦に殺されたりといはんと其少者之を刺し通したればすなはち死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'イスラエルの人々はアビメレクの死たるを見ておのおのおのれの處に歸り去りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, '神はアビメレクがその七十人の兄弟を殺しておのれの父になしたる惡に斯く報いたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'またシケムの民のすべての惡き事をも神は彼等の頭に報いたまへりすなはちヱルバアルの子ヨタムの詛彼らの上に及べるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'アビメレクの後イッサカルの人にてドドの子なるプワの子トラ起りてイスラエルを救ふ彼エフライムの山のシヤミルに住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, '二十三年の間イスラエルを審判しがつひに死てシヤミルに葬らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, '彼の後にギレアデ人ヤイル起りて二十二年の間イスラエルを審判たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, '彼に子三十人ありて三十の驢馬に乗る彼等三十の邑を有りギレアデの地において今日までヤイルの村ととなふるものすなはち是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'ヤイル死てカモンに葬らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'イスラエルの子孫ふたたびヱホバの目のまへに惡を爲しバアルとアシタロテ及びスリヤの神シドンの神モアブの神アンモンの子孫の神ペリシテ人の神に事へヱホバを棄て之に事へざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'ヱホバ烈しくイスラエルを怒りて之をペリシテ人及びアンモンの子孫の手に賣付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, '其年に彼らイスラエルの子孫を虐げ難せりヨルダンの彼方においてギレアデにあるところのアモリ人の地に居るイスラエルの子孫十八年の間斯せられたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'アンモンの子孫またユダとベニヤミンとエフライムの族とを攻んとてヨルダンを渡りしかばイスラエル太く苦めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'ここにおいてイスラエルの子孫ヱホバに呼りていひけるは我らおのれの神を棄てバアルに事へて汝に罪を犯したりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'ヱホバ、イスラエルの子孫にいひたまひけるは我かつてエジプト人アモリ人アンモンの子孫ペリシテ人より汝らを救ひ出せしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, '又シドン人アマレク人及びマオン人の汝らを困しめしとき汝ら我に呼りしかば我汝らを彼らの手より救ひ出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, '然るに汝ら我を棄て他の神に事ふれば我かさねて汝らを救はざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, '汝らが擇める神々に往て呼れ汝らの艱難のときに之をして汝らを救はしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'イスラエルの子孫ヱホバに言けるは我ら罪を犯せりすべて汝の目に善と見るところを我らになしたまへねがはくは唯今日我らを救ひたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, '而して民おのれの中より異なる神々を取除きてヱホバに事へたりヱホバの心イスラエルの艱難を見るに忍びずなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, '茲にアンモンの子孫集てギレアデに陣を取りしがイスラエルの子孫は聚りてミヅパに陣を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, '時に民ギレアデの群伯たがひにいひけるは誰かアンモンの子孫に打ちむかひて戰を始むべき人ぞ其人をギレアデのすべての民の首となすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'ギレアデ人ヱフタはたけき勇士にして妓婦の子なりギレアデ、ヱフタをうましめしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'ギレアデの妻子等をうみしが妻の子等成長におよびてヱフタをおひいだしてこれにいひけるは汝は他の婦の子なればわれらが父の家を嗣べきにあらずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'ヱフタ其の兄弟の許より逃さりてトブの地に住けるに遊蕩者ヱフタのもとに集ひ來りて之とともに出ることをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, '程經てのちアンモンの子孫イスラエルとたたかふに至りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'アンモンの子孫のイスラエルとたたかへるときにギレアデの長老等ゆきてヱフタをトブの地より携來らんとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'ヱフタにいひけるは汝來りて吾らの大將となれ我らアンモンの子孫とたたかはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'ヱフタ、ギレアデの長老等にいひけるは汝らは我を惡みてわが父の家より逐いだしたるにあらずやしかるに今汝らが艱める時に至りて何ぞ我に來るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'ギレアデの長老等ヱフタにこたへけるは其がために我ら今汝にかへる汝われらとともにゆきてアンモンの子孫とたたかはばすべて我等ギレアデにすめるものの首領となすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'ヱフタ、ギレアデの長老等にいひけるは汝らもし我をたづさへかへりてアンモンの子孫とたたかはしめんにヱホバ之を我に付したまはば我は汝らの首となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'ギレアデの長老等ヱフタにいひけるはヱホバ汝と我との間の證者たり我ら誓つて汝の言のごとくになすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, '是に於てヱフタ、ギレアデの長老等とともに往くに民之を立ておのれの首領となし大將となせりヱフタ即ちミヅパにおいてヱホバのまへにこの言をことごとく陳たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'かくてヱフタ、アンモンの子孫の王に使者をつかはしていひけるは汝と我の間に何事ありてか汝われに攻めきたりてわが地に戰はんとする');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'アンモンの子孫の王ヱフタの使者に答へけるはむかしイスラエル、エジプトより上りきたりし時にアルノンよりヤボクにいたりヨルダンに至るまで吾が土地を奪ひしが故なり然ば今穩便に之を復すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'ヱフタまた使者をアンモンの子孫の王に遣りて之にいはせけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'ヱフタ斯いへりイスラエルはモアブの地を取ずまたアンモンの子孫の地をも取ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, '夫イスラエルはエジプトより上りきたれる時に曠野を經て紅海に到りカデシに來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, '而してイスラエル使者をエドムの王に遣して言けるはねがはくは我をして汝の土地を經過しめよと然るにエドムの王之をうけがはずまたおなじく人をモアブの王に遣したれども是もうべなはざりしかばイスラエルはカデシに留まりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, '遂にイスラエル曠野を經てエドムの地およびモアブの地を繞りモアブの地の東の方に出てアルノンの彼方に陣を取り然どモアブの界には入らざりきアルノンはモアブの界なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'かくてイスラエル、ヘシボンに王たりしアモリ人の王シホンに使者を遣せりすなはちイスラエル之にいひけらくねがはくは我らをして汝の土地を經過てわがところにいたらしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, '然るにシホン、イスラエルを信ぜずしてその界をとほらしめずかへつてそのすべての民を集めてヤハヅに陣しイスラエルとたたかひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'イスラエルの神ヱホバ、シホンとそのすべての民をイスラエルの手に付したまひたればイスラエル之を撃敗りてその土地にすめるアモリ人の地を悉く手に入れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'アルノンよりヤボクに至るまでまた曠野よりヨルダンに至るまですべてアモリ人の土地を手に入たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, '斯のごとくイスラエルの神ヱホバは其の民イスラエルのまへよりアモリ人を逐しりぞけたまひしに汝なほ之を取んとする乎');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, '汝は汝の神ケモシが汝に取しむるものを取ざらんやわれらは我らの神ヱホバが我らに取しむる物を取ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, '汝は誠にモアブの王チツポルの子バラクにまされる處ありとするかバラク曾てイスラエルとあらそひしことありや曾て之とたたかひしことありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'イスラエルがヘシボンとその村里アロエルとその村里およびアルノンの岸に沿ひたるすべての邑々に住ること三百年なりしに汝などてかその間に之を回復さざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, '我は汝に罪を犯せしことなきに汝はわれとたたかひて我に害をくはへんとす願くは審判をなしたまふヱホバ今日イスラエルの子孫とアンモンの子孫との間を鞫きたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'しかれどもアンモンの子孫の王はヱフタのいひつかはせる言を聽いれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'ここにヱホバの靈ヱフタに臨みしかばヱフタすなはちギレアデおよびマナセを經過りギレアデのミヅパにいたりギレアデのミヅパよりすすみてアンモンの子孫に向ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'ヱフタ、ヱホバに誓願を立ていひけるは汝誠にアンモンの子孫をわが手に付したまはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, '我がアンモンの子孫の所より安然かに歸らんときに我家の戸より出きたりて我を迎ふるもの必ずヱホバの所有となるべし我之を燔祭となしてささげんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'ヱフタすなはちアンモンの子孫の所に進みゆきて之と戰ひしにヱホバかれらをその手に付したまひしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'アロエルよりミンニテにまで至りこれが二十の邑を打敗りてアベルケラミムにいたり甚だ多の人をころせりかくアンモンの子孫はイスラエルの子孫に攻伏られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'かくてヱフタ、ミヅパに來りておのが家にいたるに其女鼓を執り舞ひ踊りて之を出で迎ふ是彼が獨子にて其のほかには男子もなくまた女子も有ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'ヱフタ之を視てその衣を裂ていひけるはああ吾が女よ汝實に我を傷しむ汝は我を惱すものなり其は我ヱホバにむかひて口を開きしによりて改むることあたはざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, '女之にいひけるはわが父よ汝ヱホバにむかひて口をひらきたれば汝の口より言出せしごとく我になせよ其はヱホバ汝のために汝の敵なるアンモンの子孫に仇を復したまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, '女またその父にいひけるはねがはくは此事をわれに允せすなはち二月の間我をゆるし我をしてわが友等とともに往て山にくだりてわが處女たることを歎かしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'ヱフタすなはち往けといひて之を二月のあひだ出し遣ぬ女その友等とともに往き山の上にておのれの處女たるを歎きしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, '二月滿てその父に歸り來りたれば父その誓ひし誓願のごとくに之に行へり女は終に男を知ことなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, '是よりして年々にイスラエルの女子等往て年に四日ほどギレアデ人ヱフタの女のために哀哭ことをなす是イスラエルの規矩となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'エフライムの人々つどひて北にゆきヱフタにいひけるは汝何故に往きてアンモンの子孫と戰ひながらわれらをまねきて汝とともに行せざりしや我ら火をもて汝の家を汝とともに焚くべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'ヱフタ之にいひけるは我とわが民の曾てアンモンの子孫と大に爭ひしときに我汝らをよびしに汝らかれらの手より我を救ふことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, '我汝らが我を救はざるを見たればわが命をかけてアンモンの子孫の所に攻ゆきしにヱホバかれらを我が手に付したまへり然ば汝らなんぞ今日我が許に上り來りて我とたたかはんとするやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'ヱフタここにおいてギレアデの人をことごとくつどへてエフライムとたたかひしがギレアデの人々エフライムを撃破れり是はエフライム汝らギレアデ人はエフライムの逃亡者にしてエフライムとマナセの中にをるなりと言しに由る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, '而してギレアデ人エフライムにおもむくところのヨルダンの津をとりきりしがエフライム人の逃れ來る者ありて我を渡らせよといへばギレアデの人之に汝はエフライム人なるかと問ひ彼もし然らずと言ときは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'また之に請ふシボレテといへといふに彼その音を正しくいひ得ずしてセボレテと言ばすなはち之を引捕へてヨルダンの津に屠せりその時にエフライム人のたふれし者四萬二千人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'ヱフタ六年のあひだイスラエルを審きたりギレアデ人ヱフタつひに死てギレアデのある邑に葬むらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, '彼の後にベテレヘムのイブザン、イスラエルを審きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, '彼に三十人の男子ありまた三十人の女子ありしがこれをば外に嫁がしめてその子息等のために三十人の女を外より娶れり彼七年のあひだイスラエルを審きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'イブザンつひに死てベテレヘムに葬むらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, '彼の後にゼブルン人エロン、イスラエルを審きたりゼブルン人エロン十年のあひだイスラエルを審きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'ゼブルン人エロンつひに死てゼブルンの地のアヤロンに葬むらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, '彼の後にピラトン人ヒレルの子アブドン、イスラエルを審きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, '彼に四十人の男子および三十人の孫ありて七十の驢馬に乗る彼八年のあひだイスラエルを審けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'ピラトン人ヒレルの子アブドンつひに死てエフライムの地のピラトンに葬むらる是はアマレク人の山にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'イスラエルの子孫またヱホバのまへにて惡を行ひしかばヱホバこれを四十年の間ペリシテ人の手にわたしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'ここにダン人の族にて名をマノアとよべるゾラ人あり其の妻は石婦にして子を生みしことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'ヱホバの使その女に現れて之にいひけるは汝は石婦にして子を生しことあらず然ど汝孕みて子をうまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'されば汝つつしみて葡萄酒および濃き酒を飮むことなかれまたすべて穢たるものを食ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, '視よ汝孕みて子を產ん其の頭には剃刀をあつべからずその兒は胎を出るよりして神のナザレ人〔神に身を獻げし者〕たるべし彼ペリシテ人の手よりイスラエルを拯ひ始めんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'その婦人來りて夫に告て曰けるは神の人我にのぞめりその容貌は神の使の容貌のごとくにして甚おそろしかりしが我其のいづれより來れるやを問ず彼また其の名を我に告ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, '彼我にいひけるは視よ汝孕みて子を產まん然ば葡萄酒および濃き酒を飮むなかれまたすべてけがれたるものを食ふなかれその兒は胎を出るより其の死る日まで神のナザレ人たるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'マノア、ヱホバにこひ求めていひけるはああわが主よ汝がさきに遣はしたまひし神の人をふたたび我らにのぞませ之をして我らがその產るる兒になすべき事を敎へしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, '神マノアの聲をききいれたまひて神の使者婦人の田野に坐しをる時に復之にのぞめり時に夫マノアは共にをらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, '是において婦いそぎ走りて夫に告て之にいひけるは先頃我にのぞみし人また我に現はれたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'マノアすなはち起て妻のあとに付て行き其人のもとに至りて之に汝はかつて此婦に語言し人なるかといふに然りとこたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'マノアいひけるは汝の言のごとく成ん時は其兒の養育方および之になすべき事は如何');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'ヱホバの使者マノアにいひけるはわがさきに婦に言しところのことどもは婦之をつつしむべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'すなはち葡萄樹よりいづる者は凡て食ふべからず葡萄酒と濃き酒を飮ずまたすべて穢たるものを食ふべからずすべてわが彼に命じたることどもを彼守るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'マノア、ヱホバの使者にいひけるは請我らをして汝を款留しめ汝のまへに山羊羔を備へしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'ヱホバの使者マノアにいひける汝我を款留るも我は汝の食物をくらはじまた汝燔祭をそなへんとならばヱホバにこれをそなふべしとマノアは彼がヱホバの使者なるを知ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'マノア、ヱホバの使者にいひけるは汝の名はなにぞ汝の言の效驗あらんときは我ら汝を崇ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'ヱホバの使者之にいひけるは我が名は不思議なり汝何故に之をたづぬるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'マノア山羊羔と素祭物とをとり磐のうへにて之をヱホバにささぐ使者すなはち不思議なる事をなせりマノアとその妻之を視る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'すなはち火燄壇より天にあがれるときヱホバの使者壇の火燄のうちにありて昇れりマノアと其の妻これを視をりて地にひれふせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'ヱホバの使者そののち重ねてマノアと其の妻に現はれざりきマノアつひに彼がヱホバの使者たりしを暁れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, '茲にマノアその妻にむかひ我ら神を視たれば必ず死ぬるならんといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, '其の妻之にいひけるはヱホバもし我らを殺さんとおもひたまはばわれらの手より燔祭及び素祭をうけたまはざりしならんまたこれらの諸のことを我らに示すことをなしこたびのごとく我らに斯ることを告たまはざりしなるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'かくて婦子を產てその名をサムソンと呼べりその子育ち行くヱホバこれを惠みたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'ヱホバの靈ゾラとエシタオルのあひだなるマハネダンにて始て感動す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'サムソン、テムナテに下り、ペリシテ人の女にてテムナテに住る一人の婦を見');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, '歸り上りておのが父母に語ていひけるは我ペリシテ人の女にてテムナテに住るひとりの婦を見たりされば今之をめとりてわが妻とせよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'その父母之にいひけるは汝ゆきて割禮を受けざるペリシテ人のうちより妻を迎んとするは汝が兄弟等の女のうちもしくはわがすべての民のうちに婦女無が故なるかとしかるにサムソン父にむかひ彼婦わがこころに適へば之をわがために娶れと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'その父母はこの事のヱホバより出しなるを知ざりきサムソンはペリシテ人を攻んと釁をうかがひしなりそは其のころペリシテ人イスラエルを轄め居たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'サムソン父母とともにテムナテに下りてテムナテの葡萄園にいたるに稚き獅子咆哮りて彼に向ひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'ヱホバの靈彼にのぞみたれば山羊羔を裂がごとくに之を裂たりしが手には何の武器も持ざりきされどサムソンはその爲せしことを父にも母にも告ずしてありぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'サムソンつひに下りて婦とうちかたらひしが婦その心にかなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'かくて日を經て後サムソンかれを娶らんとて立かへりしが身を轉して彼の獅子の屍を見るに獅子の體に蜂の群と蜜とありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'すなはちその蜜を手にとりて歩みつつ食ひ父母の許にいたりて之を與へけるに彼ら之を食へりされど獅子の體よりその蜜を取來れることをば彼らにかたらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, '斯て其の父下りて婦のもとに至りしかばサムソン少年の習例にしたがひてそこに饗宴をまうけたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'サムソンを見て三十人の者をつれ來りて之が伴侶とならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'サムソンかれらにいひけるは我汝らにひとつの隱語をかけん汝ら七日の筵宴の内に之を解てあきらかに之を我に告なば我汝らに裏衣三十と衣三十襲をあたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, '然どもし之をわれに告得ずば汝ら我に裏衣三十と衣三十襲を與ふべしと彼等之にいひけるは汝の隱語をかけて我らに聽しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'サムソン之にいひけるは食ふ者より食物出で強き者より甘き物出でたりと彼ら三日の中に之を解ことあたはざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, '第七日にいたりてサムソンの妻にいひけるは汝の夫を説すすめて隱語を我らに明さしめよ然せずば火をもて汝と汝の父の家を焚ん汝らはわれらの物をとらんとてわれらを招けるなるか然るにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, '是においてサムソンの妻サムソンのまへに泣ていひけるは汝はわれを惡む而巳われを愛せざるなり汝わが民の子孫に隱語をかけて之をわれに説あかさずとサムソン之にいふ我これをわが父や母にも説あかさざればいかで汝に説あかすべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, '婦七日の筵宴のあひだ彼のまへに泣き居りしが第七日に至りてサムソンつひに之を彼に説あかせり其は太く強たればなり婦すなはち隱語をおのが民の子孫に明せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, '是において第七日に及びて日の沒るまへに邑の人々サムソンにいひけるは何ものか蜜よりあまからん何ものか獅子より強からんとサムソン之にいひけるは汝らわが牝犢をもて耕さざりしならばわが隱語を解得ざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, '茲にヱホバの靈サムソンに臨みしかばサムソン、アシケロンに下りてかしこの者三十人を殺しその物を奪ひ彼の隱語を解し者等にその衣服を與へはげしく怒りて其父の家にかへり上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'サムソンの妻はサムソンの友となり居たるその伴侶の妻となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, '日を經てのち麥秋の時にサムソン山羊羔をたづさへて妻のもとを訪ていひけるは我室に入てわが妻に會んと然るに妻の父其の入ことをゆるさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, '其父すなはちいひけるはわれまことに汝は彼の婦を嫌ひたりと意ひしがゆゑに彼を汝の伴侶たりし者に與へたり彼が妹は彼よりも善にあらずやねがはくは彼に代て之を汝のものとせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'サムソン彼らにいひけるは今回はわれペリシテ人に害を加ふるとも彼らに對して罪なかるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'サムソンすなはち往て山犬三百をとらへ火炬をとり尾と尾をあはせてその二つの尾の間に一つの火炬を結ひつけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, '火炬に火をつけてペリシテ人のいまだ刈ざる麥のなかにこれを放ち入れその束ね積たるものといまだ刈ざるものを焚き橄欖の園にまで及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'ペリシテ人いひけるは是は誰の行爲なるやこたへて言ふテムナテ人の婿サムソンなりそは彼サムソンの妻をとりて其伴侶なりし者に與へたればなりとここにおいてペリシテ人上りきたりて彼の婦とその父とを火にて燒きうしなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'サムソンかれらに言ふ汝ら斯おこなへば我汝らに仇をむくはでは止じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'すなはち脛に腿に彼らを撃て大いに之を殺せりかくてサムソンは下りてエタムの巖間に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'ここにおいてペリシテ人上り來りてユダに陣を取りレヒに布き備へたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'ユダの人々いひけるは汝ら何の故にわれらに攻めのぼりたるやとかれらこたへけるはサムソンをしばりて彼がわれらに爲しごとくかれに爲んとてのぼれるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, '是をもてユダの人三千人エタムの巖間にくだりてサムソンにいふ汝ペリシテ人はわれらを轄るものなるを知らざるや汝などてかわれらに斯る事をなせしやサムソンかれらにいひけるは我は彼らが我に爲しごとく彼らに爲しなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'かれらまたサムソンにいひけるは我らは汝をしばりてペリシテ人の手にわたさんとて下りきたれりサムソンかれらにいひけるは汝らの自われを害すまじきことを我に誓へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, '彼ら之にかたりていふいなわれらはただ汝を縛りいましめてペリシテ人の手にわたさんのみわれらは必らず汝を殺さざるべしとすなはち二條の新しき索をもてかれをいましめて巖より之を携かへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'サムソン、レヒにいたれるときペリシテ人聲を揚てかれに近づきしが時しもヱホバの靈彼にのぞみたればその腕にかかれる索は火に焚たる麻のごとくになりて手のいましめ解はなれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'サムソンすなはち驢馬のあたらしき腮骨ひとつを見出し手をのべて之を取り其をもて一千人を殺し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, '而して言ふ驢馬の腮骨をもて山をきづき山をつくる驢馬の腮骨をもて我一千人を撃殺せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'かく言終りてその手より腮骨をうちすて其處をラマテレヒと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, '時に彼渇をおぼゆること甚だしかりしかばヱホバによばはりていふ汝のしもべの手をもて汝この大なる拯をほどこしたまへるにわれ今渇きて死に割禮を受けざるものの手におちいらんとすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'ここにおいて神レヒに在るくぼめる所を裂きたまひしかば水そこより流れいでしがサムソン之を飮たれば精神舊に返りてふたたび爽になりぬ故に其名をエンハッコレ(呼はれるものの泉)と呼ぶ是今日にいたるまでレヒに在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'サムソンはペリシテ人の治世の時に二十年イスラエルをさばけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'サムソン、ガザに往きかしこにて一人の妓を見てそれの處に入しに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'サムソンここに來れりとガザ人につぐるものありければすなはち之を取り圍みよもすがら邑の門に埋伏し詰朝におよび夜の明たる時に之をころすべしといひてよもすがら靜まりかへりて居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'サムソン夜半までいね夜半にいたりて興き邑の門の扉とふたつの柱に手をかけて楗もろともに之をひきぬき肩に載てヘブロンの向ひなる山の巓に負のぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'こののちサムソン、ソレクの谷に居る名はデリラと言ふ婦人を愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'ペリシテ人の群伯その婦のもとに上り來て之にいひけるは汝サムソンを説すすめてその大いなる力は何に在るかまたわれら如何にせば之に勝て之を縛りくるしむるを得べきかを見出せ然すればわれらおのおの銀千百枚づつをなんぢに與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'ここにおいてデリラ、サムソンにいひけるは汝の大なる力は何にあるかまた如何せば汝を縛りて苦むることを得るや請ふ之をわれにつげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'サムソン之にいひけるは人もし乾きしことなき七條の新しき繩をもてわれを縛るときはわれ弱くなりて別の人のごとくならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'ここに於てペリシテ人の群伯乾きしことなき七條の新しき繩を婦にもち來りければ婦之を以てサムソンをしばりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'かねて室のうちに人しのび居て己とともにありたれば斯してサムソンにむかひサムソンよペリシテ人汝に及ぶと言にサムソンすなはちその索を絶りあたかも麻絲の火にあひて斷るるがごとし斯其の力の原由知れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'デリラ、サムソンにいひけるは視よ汝われを欺きてわれに謊を告たり請ふ何をもてせば汝を縛ることをうるや今我に告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, '彼之にいひけるはもし人用ひたることなき新しき索をもてわれを縛りいましめなばわれ弱くなりて別の人のごとくならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, '是をもてデリラあたらしき索をとり其をもて彼を縛りしかして彼にいふサムソンよペリシテ人汝におよぶと時に室のうちに人しのび居たりしがサムソン絲の如くにその索を腕より絶おとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'デリラ、サムソンにいひけるに今までは汝われを欺きて我に謊をつげたるが何をもてせば汝をしばることをうるやわれに告よと彼之にいひけるは汝もしわが髮毛七繚を機の緯線とともに織ばすなはち可しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, '婦すなはち釘をもて之をとめおきて彼にいひけるはサムソンよペリシテ人汝におよぶとサムソンすなはちその寢をさまし織機の釘と緯線とを曳拔り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, '婦ここにおいてサムソンにいひけるは汝の心われに居ざるに汝いかでわれを愛すといふや汝すでに三次われをあざむきて汝が大なる力の何にあるかをわれに告ずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, '日々にその言をもて之にせまりうながして彼の心を死るばかりに苦ませたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, '彼つひにその心をことごとく打明して之にいひけるはわが頭にはいまだかつて剃刀を當しことあらずそはわれ母の胎を出るよりして神のナザレ人たればなりもしわれ髮をそりおとされなばわが力われをはなれわれは弱くなりて別の人のごとくならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'デリラ、サムソンがことごとく其のこころを明したるを見人をつかはしてペリシテ人の群伯を召ていひけるはサムソンことごとくその心をわれに明したれば今ひとたび上り來るべしとここにおいてペリシテ人の群伯かの銀を携へて婦のもとにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, '婦おのが膝のうへにサムソンをねむらせ人をよびてその頭髮七繚をきりおとさしめ之を苦めはじめたるにその力すでにうせさりてあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, '婦ここにおいてサムソンよペリシテ人汝におよぶといひければ彼睡眠をさましていひけるはわれ毎のごとく出て身を振はさんと彼はヱホバのおのれをはなれたまひしを覺らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'ペリシテ人すなはち彼を執へ眼を抉りて之をガザにひき下り銅の鏈をもて之を繋げりかくてサムソンは囚獄のうちに磨を挽居たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'その髮の毛剃りおとされてのち復長はじめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, '茲にペリシテ人の群伯共にあつまりてその神ダゴンに大なる祭物をささげて祝をなさんとしすなはち言ふわれらの神はわれらの敵サムソンをわれらの手に付したりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, '民サムソンを見ておのれの神をほめたたへて言ふわれらの神はわれらの敵たる者われらの地を荒せしものわれらを數多殺せしものをわれらの手に付したりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'その心に喜びていひけるはサムソンを召てわれらのために戲技をなさしめよとて囚獄よりサムソンを召いだせしかばサムソン之がために戲技をなせり彼等サムソンを柱の間に立しめしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'サムソンおのが手をひきをる少者にいひけるはわれをはなして此家の倚て立ところの柱をさぐりて之に倚しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'その家には男女充ちペリシテ人の群伯もまたみな其處に居る又屋蓋のうへには三千ばかりの男女をりてサムソンの戲技をなすを觀てありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, '時にサムソン、ヱホバに呼はりいひけるはああ主ヱホバよねがはくは我を記念えたまへ嗚呼神よ願くは唯今一度われを強くしてわがふたつの眼のひとつのためにだにもペリシテ人に仇をむくいしめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'サムソンすなはちその家の倚てたつところの兩箇の中柱のひとつを右の手ひとつを左の手にかかへて身をこれによせたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'サムソン我はペリシテ人とともに死なんといひて力をきはめて身をかがめたれば家はそのなかに居る群伯とすべての民のうへに倒れたりかくサムソンが死るときに殺せしものは生けるときに殺せし者よりもおほかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'こののちサムソンの兄弟およびその父の家族ことごとく下りて之を取り携へのぼりてゾラとエシタオルのあひだなる其の父マノアの墓にはうむれりサムソンがイスラエルをさばきしは二十年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'ここにエフライムの山の人にて名をミカとよべるものありしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'その母に言けるは汝かつてその千百枚の銀を取れしことを吾が聞ところにて詛ひて語りしが視よその銀はわが手に在り我之を取るなりと母すなはちわが子よねがはくはヱホバ汝に祝福をたまへと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, '彼千百枚の銀をその母にかへせしかば母いひけらくわれわが子のためにひとつの像を雕みひとつの像を鑄んためにその銀をわが手よりヱホバに納む然ばわれ今之を汝にかへすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'ミカその銀を母にかへせしかば母その銀二百枚をとりて之を鑄物師にあたへてひとつの像をきざませひとつの像を鑄させたり其像はミカの家に在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'このミカといふ人神の殿をもちをりエポデおよびテラピムを造りひとりの子を立ておのが祭司となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, '此ときにはイスラエルに王なかりければ人々おのれの目に是とみゆることをおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'ここにひとりの少者ありてベテレヘムユダに於てユダの族の中にをる彼はレビ人にしてかしこに寓居るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'この人居べきところをたづねてその邑ベテレヘムユダを去しが遂に旅してエフライムの山にゆきてミカの家にいたりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'ミカ之にいひけるは汝いづこよ來れるやと彼之にいふ我はベテレヘムユダのレビ人なるが居べきところをたづねに往くものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'ミカ之に言けるは汝われと偕に居りわがために父とも祭司ともなれよ然ばわれ年に銀十枚および衣服食物を汝にあたへんとレビ人すなはち入しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'レビ人つひにその人と偕に居んことを肯ふ是においてその少者はかれの子の一人のごとくなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'ミカ、レビ人なるこの少者をたてて祭司となしたればすなはちミカの家に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'ミカここにおいて言ふ今われ知るヱホバわれに恩惠をたまはんそはこのレビ人われの祭司となればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, '當時イスラエルには王なかりしがダン人の支派其頃住むべき地を求めたり是は彼らイスラエルの支派の中にありて其日まで未だ產業の地を得ざりしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'ダンの子孫すなはちゾラとエシタオルよりして自己の族の勇者五人を遣はしその境を出て土地を窺ひ探らしむ即ち彼等に言ふ往て土地を探れと彼等エフライムの山にいたりミカの家につきて其處に宿れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'かれらミカの家の傍にある時レビ人なる少者の聲を聞認たれば身をめぐらして其處にいりて之に言ふ誰が汝を此に携きたりしや汝此處にて何をなすや此に何の用あるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, '其人かれらに言けるはミカ斯々我を待ひ我を雇ひて我その祭司となれりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, '彼等これに言ふ請ふ神に問ひ我等が往ところの途に利逹あるや否を我等にしらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'その祭司かれらに言けるは安んじて往よ汝らが往ところの途はヱホバの前にあるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, '是に於て五人の者往てライシに至り其處に住る人民を視るに顧慮なく住ひをり其安穩にして安固なることシドン人のごとし此國には政權を握りて人を煩はす者絶てあらず其シドン人と隔たること遠くまた他の人民と交ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, '斯て彼等ゾラとエシタオルに返りてその兄弟等にいたるに兄弟等如何なりしやと彼等に問ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, '答て言ふ起よ彼等の所に攻のぼらん我等その地を見るに甚だ善し汝等は安んじをるなり進みいたりてその地を取ることを怠るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, '汝等往ば安固なる人民の所に至らんその地は堅横ともに廣し神これを汝らの手に與へたまふなり此處には世にある物一箇も缺ることあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, '是に於てダン人の族の者六百人武器を帶てゾラとエシタオルより出ゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, '上りてユダのキリヤテヤリムに陣を張り是をもてその處をマハネダンと名けしがその名今日に存る是はキリヤテヤリムの後にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, '彼等其處よりエフライム山に進みミカの家に至りけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, '夫のライシの國を窺ひに往たりし五人の者その兄弟等に告て言けるは是等の家にはエポデ、テラピムおよび雕める像と鑄たる像あるを汝等知や然ば汝ら今その爲べきことを考へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, '乃ち其方に身をめぐらして夫のレビ人の少者の家なるミカの家に至りてその安否を問けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, '武器を帶たる六百人のダンの子孫は門の入口に立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, '夫の土地を窺ひに往たりし五人の者上りて其處にいりその雕める像とエポデとテラピムおよび鑄たる像を取けるが祭司は武器を帶たる六百人の者とともに門の入口に立ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, '此人々ミカの家にいりて其雕める像とエポデとテラピムと鑄たる像とを取しかば祭司かれらに汝ら何をなすやと言ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, '彼等これに言けるは汝默せよ汝手を口にあてて我らとともに來り我らの父とも祭司ともなれよかし一人の家の祭司たるとイスラエルの一の支派一の族の祭司たるとは何か好や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, '祭司すなはち心に悦びてエポデとテラピムと雕める像とを取て民の中に入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, '斯てかれら身をめぐらしその子女と家畜と財寳を前にたてて進みしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'ミカの家を遙かに離れし時ミカの家に近きところの家の人々呼はり集てダンの子孫に追ひつき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'ダンの子孫を呼たれば彼等回顧てミカに言ふ汝何事ありて集りしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'かれら言けるは汝らはわが造れる神々および祭司を奪ひさりたれば我尚何かあらん然るに汝等何ぞ我にむかひて何事ぞやと言や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'ダンの子孫かれに言けるは汝の聲を我らの中に聞えしむるなかれ恐くは心の荒き人々汝に撃かかるありて汝おのれの生命と家族の生命とを失ふにいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, '而してダンの子孫進みゆきけるがミカは彼らが己よりも強きを見て身をめぐらして家に返れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, '彼等ミカが造りし者とその有し祭司をとりてライシにおもむき平穩にして安樂なる民の所にいたり刃をもて之を撃ち火をもてその邑を燬たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, '其シドンと隔たること遠きが上に他の人民と交際ざりしによりて之を救ふ者なかりきその邑はベテレホブの邊の谷にあり彼ら邑を建なほして其處に住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'イスラエルの生たるその先祖ダンの名にしたがひて其邑の名をダンと名けたりその邑の名は本はライシなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, '斯てダンの子孫その雕める像を安置りモーセの子なるゲルシヨムの子ヨナタンとその子孫ダンの支派の祭司となりて國の奪はるる時にまでおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, '神の家のシロにありし間恒に彼等はミカが造りしかの雕める像を安置おきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, '其頃イスラエルに王なかりし時にあたりてエフライムの山の奧に一人のレビ人寄寓をりベテレヘムユダより一人の婦人をとりて妾となしたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'その妾彼に背きて姦淫を爲し去てベテレヘムユダなるその父の家にかへり其所に四月といふ日をおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, '是に於てその夫彼をなだめて携かへらんとてその僕と二頭の驢馬をしたがへ起てかれの後をしたひゆきければその父の家に之を導きいたりしに女の父これを見て之に遇ことを悦こべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, '而してその女の父なる外舅彼をひきとめたれば則ち三日これと共に居り皆食飮して其所に宿りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, '四日におよびて朝早く起あがり彼たちて去んとしければ女の父その婿に言ふ少許の食物をもて汝の心を強くして然る後に去れよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, '二人すなはち坐りて共に食飮しけるが女の父その人にいひけるは請ふ幸に今一夜を明し汝の心を樂ましめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, '其人起て去んとしけるに外舅これを強たれば遂に復其所に宿り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, '五日におよびて朝はやく起いでて去んとしたるに女の父これに言けるは請ふ汝の心を強くせよと是をもて日の昃るまでとどまりて共に食をなしけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, '其人つひに妾および僕とともに去んとて起あがりければ女の父彼に言ふ視よ今は日暮なんとす請ふ今一夜を明されよ視よ日昃たり汝此にやどりて汝の心をたのしませ明日蚤く起て出たち汝の家にいたれよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, '然るに其人止宿ることを肯はずして起て去りヱブスの對面に至れり是はエルサレムなり鞍おける二の驢馬彼とともにあり妾も彼とともなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, '彼らヱブスの近傍にをる時日はや沒んとしければ僕その主人にいひけるは請ふ來れ我等身をめぐらしてヱブス人の此邑にいりて其所に宿らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'その主人これに言けるは我等は彼所に身をめぐらしてイスラエルの子孫の邑ならざる外國の人の邑にいるべからずギベアに進みゆかんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'すなはちその僕にいひけるは來れ我らギベアかラマか是等の處の一に就て止宿んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, '皆すすみ往きけるがベニヤミンのギベアの近邊にて日暮たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'ギベアにゆきて宿らんとて其所に身をめぐらし入て邑の衢に坐しけるに誰も彼を家に接て宿らしむる者なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, '時に一人の老人日暮に田野の働作をやめて歸りきたる此人はエフライム山の者にしてギベアに寄寓れるなり但し此處の人はベニヤミン人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, '彼目をあげて旅人の邑の衢にをるを見たり老人すなはちいひけるは汝は何所にゆくなるや何所より來れるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'その人これにいひけるは我らはベテレヘムユダよりエフライム山の奧におもむく者なり我は彼所の者にて旣にベテレヘムユダにゆき今ヱホバの室に詣らんとするなるが誰もわれを家に接ものあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, '然ど驢馬の藁も飼蒭もあり又我と汝の婢および僕等とともなる少者の用ふべき食物も酒も在て何も事缺るところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, '老人いひけるは願くは汝安かれ汝が需むる者は我そなへん唯衢に宿るなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'かれをその家に携れ驢馬に飼ふ彼らすなはち足をあらひて食飮せしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'その心を樂ませをる時にあたりて邑の人々の邪なる者その家をとりかこみ戸を打たたきて家の主人なる老人に言ふ汝の家にきたれる人をひき出せ我らこれを犯さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, '是に於て家の主人なる人かれらの所にいでゆきてこれに言けるは否わが兄弟よ惡をなす勿れ此人すでにわが家にいりたればこの愚なる事をなすなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, '我が處女なる女と此人の妾とあるにより我これを今つれいだすべければ汝らかれらを辱しめ汝等の好むところをこれに爲せ唯この人には斯る愚なる事を爲すなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, '然るにその人々これを聽いれざるにより其人その妾をとりてこれを彼らの所にいだしやりければすなはちこれを犯して朝にいたるまで終夜これを辱しめ日のいづる頃にいたりて釋てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, '是をもて婦黎明にきたりてその夫のをる彼人の家の門に仆れ夜のあくるまで其處に臥をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'その主朝におよびておきいで家の戸をひらきて出去んとせしがその妾の婦の家の門にたふれをりて手を閾の上におくを見ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'これにむかひ起よ我ら出往んと言たれども何の答もあらざりき是によりてその人これを驢馬にのせたちて己の所におもむきしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, '家にいたるにおよびて刀をとり其妾を執へて骨ぐるみこれを十二分にたちわりて之をイスラエルの四方の境におくりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, '之を見る者皆いふイスラエルの子孫がエジプトの地より出のぼりし日より今日にいたるまで斯のごとき事は行はれしことなく見えしことなし思をめぐらし相議りて言ふことをせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, '是に於てイスラエルの子孫ダンよりベエルシバにいたりギレアデの地にいたるまで皆出きたり其會衆一人のごとくにしてミヅパに於てヱホバの前に集り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, '衆民の長たる者すなはちイスラエルの諸の支派の長等みづから神の民の集會に出づ劍をぬくところの歩兵四十萬人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'ベニヤミンの子孫はイスラエルの子孫がミヅパにのぼれることを聞り斯てイスラエルの子孫此惡事の樣を語れと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, '彼殺されし婦の夫なるレビの人こたへていふ我わが妾とともにベニヤミンのギベアに宿らんとて往たるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'ギベアの人起りたちて我をせめ夜の間に我がをる家をとりかこみて我を殺さんと企て遂にわが妾を辱しめてこれを死しめたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, '我わが妾をとらへてこれをたちわり是をイスラエルの產業なる全地に遣れり是は彼らイスラエルにおいて淫事をなし愚なる事をなしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, '汝等は皆イスラエルの子孫なり今汝らの意見と思考をのべよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, '民みな一人のごとくに起ていひけるは我らは誰もおのれの天幕にゆかずまた誰もおのれの家におもむかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, '我らがギベアになさんところの事は是なりすなはち鬮にしたがひて之を攻ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, '我らイスラエルの諸の支派の中に於て百人より十人千人より百人萬人より千人を取りて民の糧食を執せ之をしてベニヤミンのギベアにいたり彼らがイスラエルにおこなひたるその愚なる事にしたがひて事をなさしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, '斯イスラエルの人々皆あつまりて此邑を攻んとせしが其相結べること一人のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'イスラエルの諸の支派遍く人をベニヤミンの支派の中に遣して言しめけるは汝らの中に此惡事のおこなはれしは何事ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, '然ばギベアにをるかの邪なる人々をわたせ我らこれを誅して惡をイスラエルに絶べしと然るにベニヤミンの子孫はその兄弟なるイスラエルの子孫の言を聽いれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, '却てベニヤミンの子孫は邑々よりギベアにあつまりて出てイスラエルの子孫と戰はんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'その時邑々より出たるベニヤミンの子孫を數ふるに劍をぬく所の人二萬六千あり外にまたギベアの居民ありて之をかぞふるに精兵七百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'この諸の民の中に左手利の精兵七百人あり皆能く投石器をもて石を投るに毫末もたがふことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'イスラエルの人を數ふるにベニヤミンを除きて劍をぬくところの者四十萬人ありき是みな軍人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, '爰にイスラエルの子孫起あがりてベテルにのぼり神に問て我等の中孰か最初にのぼりてベニヤミンの子孫と戰ふべきやと言ふにヱホバ、ユダ最初にと言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'イスラエルの子孫すなはち朝おきてギベアにむかひて陣をとりけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'イスラエルの人々ベニヤミンと戰はんとて出でゆきイスラエルの人々行伍をたててギベアにて彼らと戰はんとしければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'ベニヤミンの子孫ギベアより進みいで其日イスラエル人二萬二千を地に撃仆せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, '然るにイスラエルの民の人々みづから奮ひその初の日に行伍をたてし所にまた行伍をたてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, '而してイスラエルの子孫上りゆきてヱホバの前に夕暮まで哭きヱホバに問て言ふ我復進みよりて吾兄弟なるベニヤミンの子孫とたたかふべきやとヱホバ彼に攻のぼれと言たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, '是に於てイスラエルの子孫次の日またベニヤミンの子孫の所に攻よするに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'ベニヤミンまた次の日ギベアより進みて之にいであい再びイスラエルの子孫一萬八千人を地に撃仆せり是みな劍をぬくところの者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, '斯在しかばイスラエルの子孫と民みな上りてベテルにいたりて哭き其處にてヱホバの前に坐りその日の夕暮まで食を斷ち燔祭と酬恩祭をヱホバの前に獻げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, '而してイスラエルの子孫ヱホバにとへり(その頃は神の契約の櫃彼處にありて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'アロンの子エレアザルの子なるピネハス當時これに事へたり)即ち言けるは我またも出てわが兄弟なるベニヤミンの子孫とたたかふべきや或は息べきやヱホバ言たまふ上れよ明日はわれ汝の手にかれらを付すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'イスラエル是に於てギベアの周圍に伏兵を置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, '而してイスラエルの子孫三日目にまたベニヤミンの子孫の所に攻のぼり前のごとくにギベアにむかひて行伍をたてたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'ベニヤミンの子孫民に出あひしが遂に邑より誘出されたり彼等始は民を撃ち大路にて前のごとくイスラエルの人三十人許を殺せりその大路は一筋はベテルにいたり一筋は野のギベアに至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'ベニヤミンの子孫すなはち言ふ彼らは初のごとく我らに撃破らると然るにイスラエルの人は云ふ我等逃て彼らを邑より大路に誘き出さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'イスラエルの人々みなその所を起て去りバアルタマルに行伍をたてたり而して伏兵その處より即ちギベアの野原より起れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'イスラエルの全軍の中より選拔たる兵一萬來りてギベアを襲ひ其戰鬪はげしかりしがベニヤミン人は葘害の己にのぞむを知ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'ヱホバ、イスラエルのまへにベニヤミンを撃敗りたまひしかばイスラエルの子孫その日ベニヤミン人二萬五千一百人を殺せり是みな劍をぬくところの者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'ベニヤミンの子孫すなはち己の撃敗らるるを見たり偖イスラエルの人々そのギベアにむかひて設たる所の伏兵を恃てベニヤミン人を避て退きけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, '伏兵急ぎてギベアに突いり伏兵進みて刃をもて邑を盡く撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'イスラエルの人々とその伏兵との間に定めたる合圖は邑より大なる黑烟をあげんとの事なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'イスラエルの人々戰陣より引き退ぞくベニヤミン初が程はイスラエルの人々を撃ちて三千人許を殺し乃ち言ふ彼等はまことに最初の戰のごとく我等に撃やぶらると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, '然るに火焔烟の柱なして邑より上りはじめしかばベニヤミン人後を見かへりしに邑は皆烟となりて空にのぼる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, '時にイスラエルの人々ふりかへりしかばベニヤミンの人々葘害のおのれに迫るを見て狼狽へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'イスラエルの人々の前より身をめぐらして野の途におもむきけるが戰鬪これに追せまりて遂にその邑々よりいでたる者どもその中に戰死す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'イスラエルの人すなはちベニヤミン人をとりまきて之を追うち容易くこれを踏たふして東の方ギベアの對面にまでおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'ベニヤミンの仆るる者一萬八千人是みな勇士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, '茲に彼等身をめぐらして野の方ににげリンモンの磐にいたれりイスラエルの人大路にて彼等五千人を伐とり尚もこれを追うちてギドムにいたりその二千人を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, '是をもて其日ベニヤミンの仆れし者は劍をぬくところの人あはせて二萬五千なりき是みな勇士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, '但六百人の者身をめぐらして野の方にのがれリンモンの磐にいたりて四月があひだリンモンの磐にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, '是に於てイスラエルの人々また身をかへしてベニヤミンの子孫をせめ刃をもて邑の人より畜にいたるまで凡て目にあたる者を撃ち亦その至るところの邑々に火をかけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'イスラエルの人々曾てミヅパにて誓ひ曰けるは我等の中一人もその女をベニヤミンの妻にあたふる者あるべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, '茲に民ベテルに至り彼處にて夕暮まで神の前に坐り聲を放ちて痛く哭き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, '言けるはイスラエルの神ヱホバよなんぞイスラエルに斯ること起り今日イスラエルに一の支派の缺るにいたりしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, '而して翌日民蚤に起て其處に壇を築き燔祭と酬恩祭をささげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, '茲にイスラエルの子孫いひけるはイスラエルの支派の中に誰か會衆とともに上りてヱホバにいたらざる者あらんと其は彼らミヅパに來りてヱホバにいたらざる者の事につきて大なる誓をたてて其人をばかならず死しむべしと言たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'イスラエルの子孫すなはち其兄弟ベニヤミンの事を憫然におもひて言ふ今日イスラエルに一の支派絶ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, '我等ヱホバをさして我らの女をかれらの妻にあたへじと誓ひたれば彼の遺る者等に妻をめとらしめんには如何にすべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, '又言ふイスラエルの支派の中孰の者かミヅパにのぼりてヱホバにいたらざると而して視るにヤベシギレアデよりは一人も陣營にきたり集會に臨める者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, '即ち民をかぞふるにヤベシギレアデの居民は一人も其處にをらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, '是に於て會衆勇士一萬二千を彼處に遣し之に命じて言ふ往て刃をもてヤベシギレアデの居民を撃て婦女兒女をも餘すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, '汝ら斯おこなふべし即ち汝等男人および男と寢たる婦人をば悉く滅し盡すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, '彼等ヤベシギレアデの居民の中にて四百人の若き處女を獲たり是は未だ男と寢て男しりしことあらざる者なり彼らすなはち之をシロの陣營に曳きたる是はカナンの地にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, '斯て全會衆人をやりてリンモンの磐にをるベニヤミン人と語はしめ和睦をこれに宣しめたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'ベニヤミンすなはち其時に歸りきたれり是において彼らヤベシギレアデの婦人の中より生しおきたるところの女子を之にあたへけるが尚足ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'ヱホバ、イスラエルの支派の中に缺を生ぜしめたまひしに因て民ベニヤミンの事を憫然におもへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, '會衆の長老等いひけるはベニヤミンの婦女絶たれば彼の遺れる者等に妻をめとらせんには如何すべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, '又言けるはベニヤミンの中の逃れたる者等に產業あらしめん然らばイスラエルに一の支派の消ることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, '然ながら我等は我等の女子を彼らの妻にあたふべからず其はイスラエルの子孫誓をなしベニヤミンに妻を與ふる者は詛はれんと言たればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, '而して言ふ歳々シロにヱホバの祭ありと其處はベテルの北にあたりてベテルよりシケムにのぼるところの大路の東レバナの南にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, '是に於てかれらベニヤミンの子孫に命じて言ふ汝らゆきて葡萄園に伏して窺ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, '若シロの女等舞をどらんと出きたらば葡萄園より出でシロの女の中より各人妻を執てベニヤミンの地に往け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, '若その父あるひは兄弟來りて我らに愬へなば我らこれに言ふべし請ふ幸に彼らを我らに取せよ我等戰爭の時に皆ことごとくその妻をとりしにあらざればなり汝等今かれらに與へしにあらざれば汝等は罪なしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'ベニヤミンの子孫すなはちかく行なひその踊れる者等を執へてその中より己の數にしたがひて妻を取り往てその地にかへり邑々を建なほして其處に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, '斯てイスラエルの子孫その時に其處を去て各人その支派に往きその族にいたれり即ち其處より出て各人その地にいたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, '當時はイスラエルに王なかりしかば各人その目に善と見るところを爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, '士師の世ををさむる時にあたりて國に饑饉たありければ一箇の人その妻と二人の男子をひきつれてベテレヘムユダを去りモアブの地にゆきて寄寓る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'その人の名はエリメレクその妻の名はナオミその二人の男子の名はマロンおよびキリオンといふベテレヘムユダのエフラテ人なり 彼等モアブの地にいたりて其處にをりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'ナオミの夫エリメレク死てナオミとその二人の男子のこさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, '彼等おのおのモアブの婦人を妻にめとる その一人の名はオルパといひ一人の名はルツといふ 彼處にすむこと十年許にして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'マロンとキリオンの二人もまた死り 斯ナオミは二人の男子と夫に後れしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'モアブの地にて彼ヱホバその民を眷みて食物を之にたまふと聞ければその媳とともに起ちてモアブの地より歸らんとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'その在ところを出たりその 二人の媳これとともにあり 彼等ユダの地にかへらんと途にすすむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, '爰にナオミその二人の媳にいひけるは汝らはゆきておのおの母の家にかへれ 汝らがかの死たる者と我とを善く待ひしごとくにねがはくはヱホバまたなんぢらを善くあつかひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'ねがはくはヱホバなんぢらをして各々その夫の家にて安身處をえせしめたまへと 乃ちかれらに接吻しければ彼等聲をあげて哭き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, '之にいひけるは我ら汝とともに汝の民にかへらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'ナオミいひけるは女子よ返れ 汝らなんぞ我と共にゆくべけんや 汝らの夫となるべき子猶わが胎にあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, '女子よかへりゆけ 我は老たれば夫をもつをえざるなり 假設われ指望ありといふとも今夜夫を有つとも而してまた子を生むとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, '汝等これがために其子の生長までまちをるべけんや 之がために夫をもたずしてひきこもりをるべけんや 女子よ然すべきにあらず 我はヱホバの手ののぞみてわれを攻しことを汝らのために痛くうれふるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, '彼等また聲をあげて哭く 而してオルパはその姑に接吻せしがルツは之を離れず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, '是によりてナオミまたいひけるは視よ汝の妯娌はその民とその神にかへり往く 汝も妯娌にしたがひてかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'ルツいひけるは汝を棄て汝をはなれて歸ることを我に催すなかれ我は汝のゆくところに往き汝の宿るところにやどらん 汝の民はわが民汝の神はわが神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, '汝の死るところに我は死て其處に葬らるべし 若死別にあらずして我なんぢとわかれなばヱホバわれにかくなし又かさねてかくなしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, '彼 媳が固く心をさだめて己とともに來らんとするを見しかば之に言ふことを止たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'かくて彼等二人ゆきて終にベテレヘムにいたりしがベテレヘムにいたれる時 邑こぞりて之がためにさわぎたち婦女等是はナオミなるやといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'ナオミかれらにいひけるは我をナオミ(樂し)と呼なかれ マラ(苦し)とよぶべし 全能者痛く我を苦め給ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, '我盈足て出たるにヱホバ我をして空くなりて歸らしめたまふ ヱホバ我を攻め全能者われをなやましたまふに汝等なんぞ我をナオミと呼や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, '斯ナオミそのモアブの地より歸れる 媳モアブの女ルツとともに歸り來れり 即ち彼ら大麥刈の初にベテレヘムにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'ナオミにその夫の知己あり 即ちエリメレクの族にして大なる力の人なり その名をボアズといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, '茲にモアブの女ルツ、ナオミにいひけるは請ふわれをして田にゆかしめよ 我何人かの目のまへに恩をうることあらばその人の後にしたがひて穗を拾はんと ナオミ彼に女子よ往べしといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, '乃ち往き遂に至りて刈者の後にしたがひ田にて穗を拾ふ 彼意はずもエリメレクの族なるボアズの田の中にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, '時にボアズ、ベテレヘムより來り その刈者等刈者等に言ふ ねがはくはヱホバ汝等とともに在せと 彼等すなはち答てねがはくはヱホバ汝を祝たまへといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'ボアズその刈者を督る僕にいひけるは此は誰の女なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, '刈者を督る人こたへて言ふ是はモアブの女にしてモアブの地よりナオミとともに還りし者なるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'いふ請ふ我をして刈者の後にしたがひて禾束の間に穗をひろひあつめしめよと 而して來りて朝より今にいたるまで此にあり 其家にやすみし間は暫時のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'ボアズ、ルツにいひけるは女子よ聽け 他の田に穗をひろひにゆくなかれ 又此よりいづるなかれわが婢等に離ずして此にをるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, '人々の刈ところの田に目をとめてその後にしたがひゆけ 我少者等に汝にさはるなかれと命ぜしにあらずや 汝渇く時は器の所にゆきて少者の汲るを飮めと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, '彼すなはち伏て地に拜し之にいひけるは我如何して汝の目の前に恩惠を得たるか なんぢ異邦人なる我を顧みると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'ボアズこたへて彼にいひけるは汝が夫の死たるより巳來姑に盡したる事汝がその父母および生れたる國を離れて見ず識ずの民に來りし事皆われに聞えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'ねがはくはヱホバ汝の行爲に報いたまへ ねがはくはイスラエルの神ヱホバ即ち汝がその翼の下に身を寄んとて來れる者汝に十分の報施をたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, '彼いひけるは主よ我をして汝の目の前に恩をえせしめたまへ 我は汝の仕女の一人にも及ざるに汝かく我を慰め斯仕女に懇切に語りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'ボアズかれにいひけるは食事の時は此にきたりてこのパンを食ひ且汝の食物をこの醋に濡せよと 彼すなはち刈者の傍に坐しければボアズ烘麥をかれに與ふ 彼くらひて飽き其餘を懷む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'かくて彼また穗をひろはんとて起あがりければボアズその少者に命じていふ 彼をして禾束の間にても穗をひろはしめよ かれを羞しむるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, '且手の穗を故に彼がために抽落しおきて彼に拾はしめよ 叱るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, '彼かく薄暮まで田に穗をひろひてその拾ひし者を撲しに大麥一斗許ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, '彼すなはち之を携へて邑にいり姑にその拾ひし者を看せ且その飽たる後に懷めおきたる者を取出して之にあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, '姑かれにいひけるは汝今日何處にて穗をひろひしや 何の處にて工作しや 願くは汝を眷顧たる者に福祉あれ 彼すなはち姑にその誰の所に工作しかを告ていふ 今日われに工作をなさしめたる人の名はボアズといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'ナオミ媳にいひけるは願はヱホバの恩かれに至れ 彼は生る者と死る者とを棄ずして恩をほどこす ナオミまた彼にいひけるは其人は我等に縁ある者にして我等の贖業者の一人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'モアブの女ルツいひけるは彼また我にかたりて汝わが穫刈の盡く終るまでわが少者の傍をはなるるなかれといへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'ナオミその媳ルツにいひけるは女子よ汝かれの婢等とともに出るは善し 然れば他の田にて人に見らるることを免かれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, '是によりて彼ボアズの婢等の傍を離れずして穗をひろひ大麥刈と小麥刈の終にまでおよぶ 彼その姑とともにをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, '爰に姑ナオミ彼にいひけるは女子よ我汝の安身所を求めて汝を幸ならしむべきにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, '夫汝が偕にありし婢等を有る彼ボアズは我等の知己なるにあらずや 視よ彼は今夜 禾塲にて大麥を簸る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, '然ば汝の身を洗て膏をぬり衣服をまとひて禾塲に下り汝をその人にしらせずしてその食飮を終るを待て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, '而て彼が臥す時に汝その臥す所を見とめおき入てその脚を掀開りて其處に臥せよ 彼なんぢの爲べきことを汝につげんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'ルツ姑にいひけるは汝が我に言ところは我皆なすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'すなはち禾塲に下り凡てその姑の命ぜしごとくなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, '偖ボアズは食飮をなしてその心をたのしませ往て麥を積る所の傍に臥す 是に於て彼潜にゆきその足を掀開て其處に臥す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, '夜半におよびて其人畏懼をおこし起かへりて見るに一人の婦その足の方に臥ゐたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, '汝は誰なるやといふに婦こたへて我は汝の婢ルツなり 汝の裾をもて婢を覆ひたまへ 汝は贖業者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'ボアズいひけるは女子よねがはくはヱホバの恩典なんぢにいたれ 汝の後の誠實は前のよりも勝る 其は汝貧きと富とを論ず少き人に從ふことをせざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'されば女子よ懼るなかれ 汝が言ふところの事は皆われ汝のためになすべし 其はわが邑の人皆なんぢの賢き女なるをしればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, '我はまことに贖業者なりと雖も我よりも近き贖業者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, '今夜は此に住宿れ 朝におよびて彼もし汝のために贖ふならば善し彼に贖はしめよ 然ど彼もし汝のために贖ふことを好まずばヱホバは活く我汝のために贖はん 朝まで此に臥せよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'ルツ朝までその足の方に臥て誰彼の辨がたき頃に起あがる ボアズ此女の禾塲に來りしことを人にしらしむべからずといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, '而していひけるは汝の著る袿衣を將きたりて其を開げよと 即ち開げければ大麥六升を量りて之に負せたり 斯して彼邑にいたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, '爰にルツその姑の許に至るに姑いふ 女子よ如何ありしやと 彼すなはち其人の己になしたる事をことごとく之につげて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, '而していひけるは彼空手にて汝の姑の許に往くなかれといひて此六升の大麥を我にあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, '姑いひけるは女子よ坐して待ち事の如何になりゆくかを見よ 彼人今日その事を爲終ずば安んぜざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, '爰にボアズ門の所にのぼり往て其處に坐しけるに前にボアズの言たる贖業者過りければ之に言ふ 某よ來りて此に坐せよと 即ち來りて坐す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'ボアズまた邑の長老十人を招き汝等此に坐せよといひければ則ち坐す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, '時に彼その贖業人にいひけるはモアブの地より還りしナオミ我等の兄弟エリメレクの地を賣る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, '我汝につげしらせて此に坐する人々の前わが民の長老の前にて之を買へと言んと想へり 汝もし之を贖はんと思はば贖ふべし 然どもし之を贖はずば吾に告てしらしめよ 汝の外に贖ふ者なければなり 我はなんぢの次なりと彼我これを贖はんといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'ボアズいふ 汝ナオミの手よりその地を買ふ日には死る者の妻なりし モアブの女ルツをも買て死る者の名をその產業に存すべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, '贖業人いひけるは我はみづから贖ふあたはず 恐くはわが產業を壞はん 汝みづから我にかはりてあがなへ 我あがなふことあたはざればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, '昔イスラエルにて物を贖ひ或は交易んとする事につきて萬事を定めたる慣例は斯のごとし 即ち此人鞋を脱て彼人にわたせり 是イスラエルの中の證なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, '是によりてその贖業人ボアズにむかひ汝みづから買ふべしといひて其鞋を脱たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'ボアズ長老および諸の民にいひけるは汝等今日見證をなす 我エリメレクの凡の所有およびキリオンとマロンの凡の所有をナオミの手より買たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, '我またマロンの妻なりしモアブの女ルツを買て妻となし彼死る者の名をその產業に存すべし 是かの死る者の名を其兄弟の中とその處の門に絶ざらしめんためなり 汝等今日證をなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, '門にをる人々および長老等いひけるはわれら證をなす 願くはヱホバ汝の家にいるところの婦人をして彼イスラエルの家を造りなしたるラケルとレアの二人のごとくならしめたまはんことを 願くは汝エフラタにて能を得ベテレヘムにて名をあげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'ねがはくはヱホバが此若き婦よりして汝にたまはんところの子に由て汝の家かのタマルがユダに生たるペレズの家のごとくなるにいたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, '斯てボアズ、ルツを娶りて妻となし彼の所にいりければヱホバ彼を孕ましめたまひて彼男子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, '婦女等ナオミにいひけるはヱホバは讚べきかな 汝を遺ずして今日汝に贖業人あらしめたまふ その名イスラエルに揚れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, '彼は汝の心をなぐさむる者 汝の老を養ふ者とならん 汝を愛する汝の媳即ち七人の子よりも汝に善もの之をうみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'ナオミその子をとりて之を懷に置き之が養育者となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'その隣人なる婦女等これに名をつけて云ふ ナオミに男子うまれたりと その名をオベデと稱り 彼はダビデの父なるヱサイの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, '偖ペレヅの系圖は左のごとし ペレヅ、ヘヅロンを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'ヘヅロン、ラムを生み ラム、アミナダブを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'アミナダブ、ナシヨンを生み ナシヨン、サルモンを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'サルモン、ボアズを生み ボアズ、オベデを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'オベデ、ヱサイを生み ヱサイ、ダビデを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'エフライムの山地のラマタイムゾビムにエルカナと名くる人ありエフライテ人にしてエロハムの子なりエロハムはエリウの子エリウはトフの子トフはツフの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'エルカナに二人の妻ありてひとりの名をハンナといひひとりの名をペニンナといふペニンナには子ありたれどもハンナには子あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, '是人毎歳に其邑をいで上りてシロにおいて萬軍のヱホバを拝み之に祭物をささぐ其處にエリの二人の子ホフニとピネハスをりてヱホバに祭司たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'エルカナ祭物をささぐる時其妻ペニンナと其すべての息子女子にわかちあたへしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'ハンナには其倍をあたふ是はハンナを愛するが故なりされどヱホバ其孕みをとどめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, '其敵もまた痛くこれをなやましてヱホバが其はらみをとどめしを怒らせんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, '歳々ハンナ、ヱホバの家にのぼるごとにエルカナかくなせしかばペニンナかくのごとく之をなやます是故にハンナないてものくはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, '其夫エルカナ之にいひけるはハンナよ何故になくや何故にものくはざるや何故に心かなしむや我は汝のためには十人の子よりもまさるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'かくてシロにて食飮せしのちハンナたちあがれり時に祭司エリ、ヱホバの宮の柱の傍にある壇に坐す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'ハンナ心にくるしみヱホバにいのりて甚く哭き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, '誓をなしていひけるは萬軍のヱホバよ若し誠に婢の惱をかへりみ我を憶ひ婢を忘れずして婢に男子をあたへたまはば我これを一生のあひだヱホバにささげ剃髮刀を其首にあつまじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'ハンナ、ヱホバのまへに長くいのりければエリ其口に目をとめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'ハンナ心の中にものいへば只唇うごくのみにて聲きこえず是故にエリこれを酔たる者と思ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, '之にいひけるは何時まで酔ひをるか爾の酒をされよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'ハンナこたへていひけるは主よ然るにあらず我は氣のわづらふ婦人にして葡萄酒をも濃き酒をものまず惟わが心をヱホバのまへに明せるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, '婢を邪なる女となすなかれ我はわが憂と悲みの多きよりして今までかたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'エリ答へていひけるは安んじて去れ願くはイスラエルの神汝の求むる願ひを許したまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'ハンナいひけるはねがはくは仕女の汝のまへに恩をえんことをと斯てこの婦さりて食ひ其顔ふたたび哀しげならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, '是に於て彼等朝はやくおきてヱホバの前に拝をしかへりてラマの家にいたる而してエルカナ其つまハンナとまじはるヱホバ之をかへりみたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'ハンナ孕みてのち月みちて男子をうみ我これをヱホバに求めし故なりとて其名をサムエル(ヱホバに聽る)となづく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, '爰に其人エルカナ及び其家族みな上りて年々の祭物及び其誓ひし物をささぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, '然どもハンナは上らず其夫にいひけるは我はこの子の乳ばなれするに及びてのち之をたづさへゆきヱホバのまへにあらはれしめ恒にかしこに居らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, '其夫エルカナ之にいひけるは汝の善と思ふところを爲し此子を乳ばなすまでとどまるべし只ヱホバの其言を確實ならしめ賜んことをねがふと斯くこの婦止まりて其子に乳をのませ其ちばなれするをまちしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, '乳ばなせしとき牛三頭粉一斗酒一嚢を取り其子をたづさへてシロにあるヱホバの家にいたる其子なほ幼稚し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, '是に於て牛をころしその子をエリの許に携へゆきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'ハンナいひけるは主よ汝のたましひは活くわれはかつてここにてなんぢの傍にたちヱホバにいのりし婦なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'われ此子のためにいのりしにヱホバわが求めしものをあたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, '此故にわれまたこれをヱホバにささげん其一生のあひだ之をヱホバにささぐ斯てかしこにてヱホバををがめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'ハンナ祷りて言けるは我心はヱホバによりて喜び我角はヱホバによりて高し我口はわが敵の上にはりひらく是は我汝の救拯によりて樂むが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'ヱホバのごとく聖き者はあらず其は汝の外に有る者なければなり又われらの神のごとき磐はあることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, '汝等重ねて甚く誇りて語るなかれ汝等の口より漫言を出すなかれヱホバは全知の神にして行爲を裁度りたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, '勇者の弓は折れ倒るる者は勢力を帶ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, '飽足る者は食のために身を傭はせ饑たる者は憩へり石女は七人を生み多くの子を有る者は衰ふるにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'ヱホバは殺し又生したまひ陰府に下し又上らしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'ヱホバは貧からしめ又富しめたまひ卑くしまた高くしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, '荏弱者を塵の中より擧げ窮乏者を埃の中より升せて王公の中に坐せしめ榮光の位をつがしめ給ふ地の柱はヱホバの所屬なりヱホバ其上に世界を置きたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'ヱホバ其聖徒の足を守りたまはん惡き者は黑暗にありて默すべし其は人力をもて勝つべからざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'ヱホバと爭ふ者は破碎かれんヱホバ天より雷を彼等の上にくだしヱホバは地の極を審き其王に力を與へ其膏そそぎし者の角を高くし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'エルカナ、ラマに往て其家にいたりしが稚子は祭司エリのまへにありてヱホバにつかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'さてエリの子は邪なる者にしてヱホバをしらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, '祭司の民に於る習慣は斯のごとし人祭物をささぐる時肉を烹るあひだに祭司の僕三の歯ある肉叉を手にとりて來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, '之を釜あるひは鍋あるひは鼎又は炮烙に突きいれ肉叉の引きあぐるところの肉は祭司みなこれを己にとる是くシロに於て凡てそこに來るイスラエル人になせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, '脂をやく前にも亦祭司のしもべ來り祭物をささぐる人にいふ祭司のために燒くべき肉をあたへよ祭司は汝より烹たる肉を受けず生腥の肉をこのむと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'もし其人これにむかひ直ちに脂をやくべければ後心のこのむままに取れといはば僕之にいふ否今あたへよ然らずば我強て取んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, '故に其壯者の罪ヱホバのまへに甚だ大なりそは人々ヱホバに祭物をささぐることをいとひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'サムエルなほ幼して布のエポデを著てヱホバのまへにつかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'また其母これがために小き明衣をつくり歳毎にその夫とともに年の祭物をささげにのぼる時これをもちきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'エリ、エルカナとその妻を祝していひけるは汝がヱホバにささげたる者のためにヱホバ此婦よりして子を汝にあたへたまはんことをねがふと斯てかれら其郷にかへる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'しかしてヱホバ、ハンナをかへりみたまひければハンナ孕みて三人の男子と二人の女子をうめり童子サムエルはヱホバのまへにありて生育てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'ここにエリ甚だ老て其子等がイスラエルの人々になせし諸の事を聞きまた其集會の幕屋の門にいづる婦人たちと寝たるを聞て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'これにいひけるは何ぞ斯る事をなすや我このすべての民より汝らのあしき行をきく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'わが子よ然すべからず我きくところの風聞よからず爾らヱホバの民をしてあやまたしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, '人もし人にむかひて罪ををかさば神之をさばかんされど人もしヱホバに向ひて罪ををかさば誰かこれがためにとりなしをなさんやとしかれども其子父のことばを聽ざりきそはヱホバかれらを殺さんと思ひたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, '童子サムエル生長ゆきてヱホバと人とに愛せらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, '茲に神の人エリの許に來りこれにいひけるはヱホバ斯くいひたまふ爾の父祖の家エジプトにおいてパロの家にありしとき我明かに之にあらはれしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, '我これをイスラエルの諸の支派のうちより選みてわが祭司となしわが壇の上に祭物をささげ香をたかしめ我前にエポデを衣しめまたイスラエルの人の火祭を悉く汝の父の家にあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'なんぞわが命ぜし犠牲と禮物を汝の家にてふみつくるや何ぞ我よりもなんぢの子をたふとみわが民イスラエルの諸の祭物の最も嘉きところをもて己を肥すや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, '是ゆゑにイスラエルの神ヱホバいひたまはく我誠に曾ていへり汝の家およびなんぢの父祖の家永くわがまへにあゆまんと然ども今ヱホバいひたまふ決めてしからず我をたふとむ者は我もこれをたふとむ我を賤しむる者はかろんぜらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, '視よ時いたらん我汝の腕と汝の父祖の家の腕を絶ち汝の家に老たるもの无らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, '我大にイスラエルを善すべけれど汝の家内には災見えん汝の家にはこののち永く老るものなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'またわが壇より絶ざる汝の族の者は汝の目をそこなひ汝の心をいたましめん又汝の家にうまれいづるものは壯年にして死なん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, '汝のふたりの子ホフニとピネスの遇ところの事を其徴とせよ即ち二人ともに同じ日に死なん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, '我はわがために忠信なる祭司をおこさん其人わが心とわが意にしたがひておこなはんわれその家をかたうせんかれわが膏そそぎし者のまへに恒にあゆむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'しかして汝の家にのこれる者は皆きたりてこれに屈み一厘の金と一片のパンを乞ひ且いはんねがはくは我を祭司の職の一に任じて些少のパンにても食ふことをえせしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, '童子サムエル、エリのまへにありてヱホバにつかふ當時はヱホバの言まれにして默示あること恒ならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, '偖エリ目漸くくもりて見ることをえず此時其室に寝たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, '神の燈なほきえずサムエル神の櫃あるヱホバの宮に寝ね');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, '時にヱホバ、サムエルをよびたまふ彼我此にありといひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'エリの許に趨ゆきいひけるは汝われをよぶ我ここにありエリいひけるは我よばず反りて臥よと乃ちゆきていぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'ヱホバまたかさねてサムエルよとよびたまへばサムエルおきてエリのもとにいたりいひけるは汝われをよぶ我ここにありエリこたへけるは我よばずわが子よ反りていねよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'サムエルいまだヱホバをしらずまたヱホバのことばいまだかれにあらはれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'ヱホバ、三たびめに又サムエルをよびたまへばサムエルおきてエリの許にたりいひけるは汝われをよぶ我ここにありとエリ乃ちヱホバの童子をよびたまひしをさとる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, '故にエリ、サムエルにいひけるはゆきて寝よ彼若し汝をよばば僕聽くヱホバ語りたまへといへとサムエルゆきて其室にいねしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'ヱホバ來りて立ちまへの如くサムエル、サムエルとよびたまへばサムエル僕きく語りたまへといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'ヱホバ、サムエルにいひ賜けるは視よ我イスラエルのうちに一の事をなさんこれをきくものは皆其耳ふたつながら鳴ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, '其日にはわれ嘗てエリの家について言しことを始より終までことごとくエリになすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'われかつてエリに其惡事のために永くその家をさばかんとしめせりそは其子の詛ふべきことをなすをしりて之をとどめざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, '是故に我エリのいへに誓ひてエリの家の惡は犠牲あるひは禮物をもて永くあがなふ能はずといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'サムエル朝までいねてヱホバの家の戸を開きしが其異象をエリにしめすことをおそる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'エリ、サムエルをよびていひけるはわが子サムエルよ答へけるはわれここにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'エリいひけるは何事を汝につげたまひしや請ふ我にかくすなかれ汝もし其汝に告げたまひしところを一にてもかくすときは神汝にかくなし又かさねてかくなしたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'サムエル其事をことごとくしめして彼に隱すことなかりきエリいひけるは是はヱホバなり其よしと見たまふことをなしたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'サムエルそだちぬヱホバこれとともにいましてそのことばをして一も地におちざらしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'ダンよりベエルシバにいたるまでイスラエルの人みなサムエルがヱホバの預言者とさだまれるをしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'ヱホバふたたびシロにてあらはれたまふヱホバ、シロにおいてヱホバの言によりてサムエルにおのれをしめしたまふなりサムエルの言あまねくイスラエル人におよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'イスラエル人ペリシテ人にいであひて戰はんとしエベネゼルの邊に陣をとりペリシテ人はアベクに陣をとる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'ペリシテ人イスラエル人にむかひて陣列をなせり戰ふにおよびてイスラエル人ペリシテ人のまへにやぶるペリシテ人戰場において其軍四千人ばかりを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, '民陣營にいたるにイスラエルの長老曰けるはヱホバ何故に今日我等をペリシテ人のまへにやぶりたまひしやヱホバの契約の櫃をシロより此にたづさへ來らん其櫃われらのうちに來らば我らを敵の手よりすくひいだすことあらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'かくて民人をシロにつかはしてケルビムの上に坐したまふ萬軍のヱホバの契約の櫃を其處よりたづさへきたらしむ時にエリの二人の子ホフニとピネハス神の契約のはことともに彼處にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'ヱホバの契約の櫃陣營にいたりしときイスラエル人皆大によばはりさけびければ地なりひびけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'ペリシテ人喊呼の聲を聞ていひけるはヘブル人の陣營に起れる此大なるさけびの聲は何ぞやと遂にヱホバの櫃の其陣營にいたれるを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'ペリシテ人おそれていひけるは神陣營にいたる又いひけるは鳴呼われら禍なるかな今にいたるまで斯ることなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'ああ我等禍なるかな誰かわれらを是らの強き神の手よりすくひいださんや此等の神は昔し諸の災を以てエジプト人を曠野に撃し者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'ペリシテ人よ強くなり豪傑のごとく爲せヘブル人がかつて汝らに事へしごとく汝らこれに事ふるなかれ豪傑のごとく爲して戰へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'かくてペリシテ人戰ひしかばイスラエル人やぶれて各々其天幕に逃かへる戰死はなはだ多くイスラエルの歩兵の仆れし者三萬人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, '又神の櫃は奪はれエリの二人の子ホフニとピネハス殺さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, '是日ベニヤミンの一人軍中より走來り其衣を裂き土をかむりてシロにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, '其いたれる時エリ道の傍に壇に坐して觀望居たり其心に神の櫃のことを思ひ煩らひたればなり其人いたり邑にて人々に告ければ邑こぞりてさけびたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'エリ此呼號の聲をききていひけるは是喧嘩の聲は何なるやと其人いそぎきたりてエリにつぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, '時にエリ九十八歳にして其目かたまりて見ることあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, '其人エリにいひけるは我は軍中より來れるもの我今日軍中より逃れたりエリいひけるは吾子よ事いかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, '使人答へていひけるはイスラエル人ペリシテ人の前に逃げ且民の中に大なる戰死ありまた汝の二人の子ホフニとピネハスは殺され神の櫃は奪はれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, '神の櫃のことを演しときエリ其壇より仰けに門の傍におち頸をれて死ねり是はかれ老て身重かりければなり其イスラエルを鞫しは四十年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'エリの媳ピネハスの妻孕みて子產ん時ちかかりしが神の櫃の奪はれしと舅と夫の死にしとの傳言を聞しかば其痛みおこりきたり身をかがめて子を產り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, '其死なんとする時傍にたてる婦人これにいひけるは懼るるなかれ汝男子を生りと然ども答へず又かへりみず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, '只榮光イスラエルをさりぬといひて其子をイカボデ(榮なし)と名く是は神の櫃奪はれしによりまた舅と夫の故に因るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'またいひけるは榮光イスラエルをさりぬ神の櫃うばはれたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'ペリシテ人神の櫃をとりて之をエベネゼルよりアシドドにもちきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, '即ちペリシテ人神の櫃をとりて之をダゴンの家にもちきたりダゴンの傍に置ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'アシドド人次の日夙く興きヱホバの櫃のまへにダゴンの俯伏に地にたふれをるをみ乃ちダゴンをとりて再びこれを本の處におく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'また翌朝夙く興きヱホバの櫃のまへにダゴン俯伏に地にたふれをるを見るダゴンの頭と其兩手門閾のうへに斷ち切れをり只ダゴンの體のみのこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, '是をもてダゴンの祭司およびダゴンの家にいるもの今日にいたるまでアシドドにあるダゴンの閾をふまず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'かくてヱホバの手おもくアシドド人にくははりヱホバこれをほろぼし腫物をもてアシドドおよび其四周の人をくるしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'アシドド人その斯るを見ていひけるはイスラエルの神の櫃を我らのうちにとどむべからず其は其手いたくわれらおよび我らの神ダゴンにくははればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, '是故に人をつかはしてペリシテ人の諸君主を集めていひけるはイスラエルの神の櫃をいかにすべきや彼らいひけるはイスラエルの神のはこはガテに移さんと遂にイスラエルの神のはこをうつす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, '之をうつせるのち神の手其邑にくははりて滅亡るもの甚だおほし即ち老たると幼とをいはず邑の人をうちたまひて腫物人々におこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, '是において神のはこをエクロンにおくりたるに神の櫃エクロンにいたりしときエクロン人さけびていひけるは我等とわが民をころさんとてイスラエルの神のはこを我等にうつすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'かくて人を遣してペリシテ人の諸君主をあつめていひけるはイスラエルの神の櫃をおくりて本のところにかへさん然らば我等とわが民をころすことなからん蓋は邑中に恐ろしき滅亡おこり神の手甚だおもく其處にくははればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, '死なざる者は腫物にくるしめられ邑の號呼天に達せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'ヱホバの櫃七月のあひだペリシテ人の國にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'ペリシテ人祭司と卜筮師をよびていひけるは我らヱホバの櫃をいかがせんや如何にして之をもとの所にかへすべきか我らにつげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, '答へけるはイスラエルの神の櫃をかへすときはこれを空しくかへすなかれ必らず彼に過祭をなすべし然なさば汝ら愈ことをえ且彼の手の汝らをはなれざる故を知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, '人々いひけるは如何なる過祭を彼になすべきや答へけるはペリシテ人の諸君主の數にしたがひて五の金の腫物と五の金の鼠をつくれ是は汝ら皆と汝らの諸伯におよべる災は一なるによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, '汝らの腫物の像および地をあらす鼠の像をつくりイスラエルの神に榮光を皈すべし庶幾はその手を汝等およびなんぢらの神と汝等の地にくはふることを軽くせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, '汝らなんぞエジプト人とパロの其心を頑にせしごとくおのれの心をかたくなにするや神かれらの中に數度其力をしめせしのち彼ら民をゆかしめ民つひにさりしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'されば今あたらしき車一輛をつくり乳牛のいまだ軛をつけざるもの二頭をとり其牛を車に繋ぎ其犢をはなして家につれゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'ヱホバの櫃をとりて之を其車に載せ汝らが過祭として彼になす金の製作物を檟にをさめて其傍におき之をおくりて去らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'しかして見よ若し其境のみちよりベテシメシにのぼらばこの大なる災を我らになせるものは彼なり若ししかせずば我等をうちしは彼の手にあらずしてそのことの偶然なりしをしるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, '人々つひに斯なし二つの乳牛をとりて之を車につなぎその犢を室にとぢこめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'ヱホバの櫃および金の鼠と其腫物の像ををさめたる檟を車に載す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, '牝牛直にあゆみてベテシメシの路をゆき鳴つつ大路をすすみゆきて右左にまがらずペリシテ人の君主ベテシメシの境まで其うしろにしたがひゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, '時にベテシメシ人谷に麥を刈り居たりしが目をあげて其櫃をみ之を見るをよろこべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, '車ベテシメシ人ヨシユアの田にいりて其處にとどまる此に大なる石あり人々車の木を劈り其牝牛を燔祭としてヱホバにささげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'レビの人ヱホバの櫃とこれとともなる檟の金の製作物ををさめたる者をとりおろし之を其大石のうへにおくしかしてベテシメシ人此日ヱホバに燔祭をそなへ犠牲をささげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'ペリシテ人の五人の君主これを見て同じ日にエクロンにかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'さてペリシテ人が過祭としてヱホバにたせし金の腫物はこれなり即ちアシドドのために一ガザのために一アシケロンのために一ガテのために一エクロンのために一なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'また金の鼠は城邑と郷里をいはず凡て五人の君主に屬するペリシテ人の邑の數にしたがひて造れりヱホバの櫃をおろせし大石今日にいたるまでベテシメシ人ヨシユアの田にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'ベテシメシの人々ヱホバの櫃をうかがひしによりヱホバこれをうちたまふ即ち民の中七十人をうてりヱホバ民をうちて大にこれをころしたまひしかば民なきさけべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'ベテシメシ人いひけるは誰かこの聖き神たるヱホバのまへに立つことをえんヱホバ我らをはなれて何人のところにのぼりゆきたまふべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'かくて使者をキリアテヤリムの人に遣はしていひけるはペリシテ人ヱホバの櫃をかへしたれば汝らくだりて之を汝らの所に携へのぼるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'キリアテヤリムの人來りヱホバのはこを携へのぼりこれを山のうへなるアビナダブの家にもちきたり其子エレアザルを聖てヱホバの櫃をまもらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, '其櫃キリアテヤリムにとどまること久しくして二十年をへたりイスラエルの全家ヱホバをしたひて歎けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, '時にサムエル、イスラエルの全家に告ていひけるは汝らもし一心を以てヱホバにかへり異る神とアシタロテを汝らの中より棄て汝らの心をヱホバに定め之にのみ事へなばヱホバ汝らをペリシテ人の手より救ひださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'ここにおいてイスラエルの人々バアルとアシタロテをすててヱホバにのみ事ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'サムエルいひけるはイスラエル人をことごとくミズパにあつめよ我汝らのためにヱホバにいのらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'かれらミズパに集り水を汲て之をヱホバのまへに注ぎ其日斷食して彼處にいひけるは我等ヱホバに罪ををかしたりとサムエル、ミズパに於てイスラエルの人を鞫く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'ペリシテ人イスラエルの人々のミズパに集れるを聞しかばペリシテ人の諸君主イスラエルにせめのぼれりイスラエル人これを聞てペリシテ人をおそれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'イスラエルの人々サムエルに云けるは我らのために我らの神ヱホバに祈ることをやむるなかれ然らばヱホバ我らをペリシテ人の手よりすくひいださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'サムエル哺乳羊をとり燔祭となしてこれをまつたくヱホバにささぐまたサムエル、イスラエルのためにヱホバにいのりければヱホバこれにこたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'サムエル燔祭をささげ居し時ペリシテ人イスラエル人と戰はんとて近づきぬ是日ヱホバ大なる雷をくだしペリシテ人をうちて之を亂し賜ければペリシテ人イスラエル人のまへに敗れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'イスラエル人ミズパをいでてペリシテ人をおひ之をうちてベテカルの下にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'サムエル一の石をとりてミズパとセンの間におきヱホバ是まで我らを助けたまへりといひて其名をエベネゼル(助けの石)と呼ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'ペリシテ人攻伏られて再びイスラエルの境にいらずサムエルの一生のあひだヱホバの手ペリシテ人をふせげり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'ペリシテ人のイスラエルより取たる邑々はエクロンよりガテまでイスラエルにかへりぬまた其周圍の地はイスラエル人これをペリシテ人の手よりとりかへせりまたイスラエル人とアモリ人と好をむすべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'サムエル一生のあひだイスラエルをさばき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, '歳々ベテルとギルガルおよびミズパをめぐりて其處々にてイスラエル人をさばき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'またラマにかへれり此處に其家あり此にてイスラエルをさばき又此にてヱホバに壇をきづけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'サムエル年老て其子をイスラエルの士師となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, '兄の名をヨエルといひ弟の名をアビヤといふベエルシバにありて士師たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, '其子父の道をあゆまずして利にむかひ賄賂をとりて審判を曲ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, '是においてイスラエルの長老みなあつまりてラマにゆきサムエルの許に至りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'これにいひけるは視よ汝は老い汝の子は汝の道をあゆまずさればわれらに王をたててわれらを鞫かしめ他の國々のごとくならしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'その我らに王をあたへて我らを鞫かしめよといふを聞てサムエルよろこばず而してサムエル、ヱホバにいのりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'ヱホバ、サムエルにいひたまひけるは民のすべて汝にいふところのことばを聽け其は汝を棄るにあらず我を棄て我をして其王とならざらしめんとするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'かれらはわがエジプトより救ひいだせし日より今日にいたるまで我をすてて他の神につかへて種々の所行をなせしごとく汝にもまた然す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, '然れどもいま其言をきけ但し深くいさめて其治むべき王の常例をしめすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'サムエル王を求むる民にヱホバのことばをことごとく告て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'いひけるは汝等ををさむる王の常例は斯のごとし汝らの男子をとり己れのために之をたてて車の御者となし騎兵となしまた其車の前驅となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'また之をおのれの爲に千夫長五十夫長となしまた其地をたがへし其作物を刈らしめまた武器と車器とを造らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'また汝らの女子をとりて製香者となし厨婢となし灸麺者となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, '又汝らの田畝と葡萄園と橄欖園の最も善きところを取て其臣僕にあたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, '汝らの穀物と汝らの葡萄の什分一をとりて其官吏と臣僕にあたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'また汝らの僕婢および汝らの最も善き牛と汝らの驢馬を取ておのれのために作かしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, '又汝らの羊の十分一をとり又汝らを其僕となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, '其日において汝等己のために擇みし王のことによりて呼號らんされどヱホバ其日に汝らに聽たまはざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, '然るに民サムエルの言にしたがふことをせずしていひけるは否われらに王なかるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, '我らも他の國々の如くになり我らの王われらを鞫きわれらを率て我らの戰にたたかはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'サムエル民のことばを盡く聞て之をヱホバの耳に告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'ヱホバ、サムエルにいひたまひけるはかれらのことばを聽きかれらのために王をたてよサムエル、イスラエルの人々にいひけるは汝らおのおの其邑にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, '茲にベニヤミンの人にてキシと名くる力の大なるものありキシはアビエルの子アビニルはゼロンの子ゼロンはベコラテの子ベコラテはアビヤの子アビヤはベニヤミンの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'キシにサウルと名くる子あり壯にして美はしイスラエルの子孫の中に彼より美はしき者たく肩より上民のいづれの人よりも高し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'サウルの父キシの驢馬失ぬキシ其子サウルにいひけるは一人の僕をともなひ起ちてゆき驢馬を尋ねよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'サウル、ニフライムの山地を通り過ぎシヤリシヤの地を通りすぐれども見あたらずシヤリムの地を通りすぐれども居らずベニヤミンの地をとほりすぐれども見あたらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'かれらツフの地にいたれる時サウル其ともなへる僕にいひけるはいざ還らん恐らくはわが父驢馬の事を措て我等の事を思ひ煩はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, '僕これにいひけるは此邑に神の人あり尊き人にして其言ふところは皆必らず成る我らかしこにいたらんかれ我らがゆくべき路をわれらにしめすことあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'サウル僕にいひけるは我らもしゆかば何を其人におくらんか器のパンは旣に罄て神の人におくるべき禮物あらず何かあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, '僕またサウルにこたへていひけるは視よわが手に銀一シケルの四分の一あり我これを神の人にあたへて我らに路をしめさしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '昔しイスラエルにおいては人神にとはんとてゆく時はいざ先見者にゆかんといへり其は今の預言者は昔しは先見者とよばれたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'サウル僕にいひけるは善くいへりいざゆかんとて神の人のをる邑におもむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'かれら邑にいる坂をのぼれる時童女數人の水くみにいづるにあひ之にいひけるは先見者は此にをるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, '答ていひけるはをる視よ汝のまへにをる急ぎゆけ今日民崇邱にて祭をなすにより彼けふ邑にきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, '汝ら邑にる時かれが崇邱にのぼりて食に就くまへに直ちにかれにあはん其は彼まづ祭品を祝してしかるのち招かれたる者食ふべきに因りかれが來るまでは民食はざるなり故に汝らのぼれ今かれにあはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'かれら邑にのぼりて邑のなかにいるとき視よサムエル崇邱にのぼらんとてかれらにむかひて出きたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'ヱホバ、サウルのきたる一日まへにサムエルの耳につげていひたまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '明日いまごろ我ベニヤミンの地より一箇の人を汝につかはさん汝かれに膏を注ぎてわが民イスラエルの長となせかれわが民をペリシテ人の手より救ひいださんわが民のさけび我に達せしにより我是をかへりみるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'サムエル、サウルを見るときヱホバこれにいひたまひけるは視よわが汝につげしは此人なり是人わが民ををさむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'サウル門の中にてサムエルにちかづきいひけるは先見者の家はいづくにあるや請ふ我につげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'サムエル、サウルにこたへていひけるは我はすなはち先見者なり汝わがまへにゆきて崇邱にのぼれ汝ら今日我とともに食す可し明日われ汝をさらしめ汝の心にあることを悉く汝にしめさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, '三日まへに失たる汝の驢馬は旣に見あたりたれば之をおもふなかれ抑もイスラエルの總ての寶は誰の者なるや即ち汝と汝の父の家のものならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'サウルこたへていひけるは我はイスラエルの支派の最も小き支派なるベニヤミンの人にしてわが族はベニヤミンの支派の諸の族の最も小き者に非やなんぞ斯る事を我にかたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'サムエル、サウルと其僕をみちびきて堂にいり招かれたる三十人ばかりの者の中の最も上に坐せしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'サムエル庖人にいひけるはわが汝にわたして汝の許におけといひし分をもちきたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, '庖人肩と肩に屬る者をとりあげて之をサウルのまへに置くサムエルいひけるは視よ是は存へおきたる物なり汝のまへにおきて食へ其はわれ民をまねきし時よりこれを汝の爲にたくはへおきたればなりかくてサウル此日サムエルとともに食せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, '崇邱をくだりて邑にいりし時サムエル、サウルとともに屋背の上にてものがたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'かれら早くおく即ちサムエル曙に屋背の上なるサウルをよびていけるは起よわれ汝をかへさんとサウルすなはちおきあがるサウルとサムエルともに外にいで');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, '邑の極處にくだれるときサムエル、サウルにいひけるは僕に命じて我等の先にゆかしめよ(僕先にゆく)しかして汝暫くとどまれ我汝に神の言をしめさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'サムエルすなはち膏の瓶をとりてサウルの頭に沃ぎ口接して曰けるはヱホバ汝をたてて其產業の長となしたまふにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, '汝今日我をはなれて去りゆく時ベニヤミンの境のゼルザにあるラケルの墓のかたはらにて二人の人にあふべしかれら汝にいはん汝がたづねにゆきし驢馬は見あたりぬ汝の父驢馬のことをすてて汝らのことをおもひわづらひわが子の事をいかがすべきやといへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, '其處より汝尚すすみてタボルの橡の樹のところにいたらんに彼處にてベテルにのぼり神にまうでんとする三人の者汝にあはん一人は三頭の山羊羔を携へ一人は三團のパンをたづさへ一人は一嚢の酒をたづさふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'かれら汝に安否をとひ二團のパンを汝にあたへん汝之を其手よりうくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, '其の後汝神のギベアにいたらん其處にペリシテ人の代官あり汝彼處にゆきて邑にいるとき一群の預言者の瑟と鼗と笛と琴を前に執らせて預言しつつ崇邱をくだるにあはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, '其の時神のみたま汝にのぞみて汝かれらとともに預言し變りて新しき人とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, '是らの徴汝の身におこらば手のあたるにまかせて事を爲すべし神汝とともにいませばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, '汝我にさきだちてギルガルにくだるべし我汝の許にくだりて燔祭を供へ酬恩祭を献げんわが汝のもとに至り汝の爲すべきことを示すまで汝七日のあひだ待つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'サケウル背をかへしてサムエルを離れし時神之に新しき心をあたへたまふしかして此しるし皆其日におこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'ふたり彼處にゆきてギベアにいたれるときみよ一群の預言者これにあふしかして神の霊サウルにのぞみてサウルかれらの中にありて預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, '素よりサウルを識る人々サウルの預言者と偕に預言するを見て互ひにいひけるはキシの子サウル今何事にあふやサウルも預言者の中にあるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, '其處の人ひとり答へて彼等の父は誰ぞやといふ是故にサウルも預言者の中にあるやといふは諺となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'サウル預言を終て崇邱にいたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'サウルの叔父サウルと僕にいひけるは汝ら何處にゆきしやサウルいひけるは驢馬を尋ねに出しが何處にもをらざるを見てサムエルの許にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'サウルの叔父いひけるはサムエルは汝に何をいひしか請ふ我につげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'サウル叔父にいひけるは明かに驢馬の見あたりしを告げたりと然れどもサムエルが言る國王の事はこれにつげざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'サムエル民をミヅパにてヱホバのまへに集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'イスラエルの子孫にいひけるはイスラエルの神ヱホバ斯くいひたまふ我イスラエルをみちびきてエジプトより出し汝らをエジプト人の手および凡て汝らを虐遇る國人の手より救ひいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, '然るに汝らおのれを患難と難苦のうちより救ひいだしたる汝らの神を棄て且否われらに王をたてよといへり是故にいま汝等の支派と群にしたがひてヱホバのまへに出よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'サムエル、イスラエルの諸の支派を呼よせし時ベニヤミンの支派籤にあたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'またベニヤミンの支派を其族のかずにしたがひて呼よせしときマテリの族籤にあたりキシの子サウル籤にあたれり人々かれを尋ねしかども見出ざれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'またヱホバに其人は此に來るや否やを問しにヱホバ答たまはく視よ彼は行李のあひだにかくると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, '人々はせゆきて彼を其處よりつれきたれり彼民の中にたつに肩より以上民の何の人よりも高かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'サムエル民にいひけるは汝らヱホバの擇みたまひし人を見るか民のうちに是人の如き者とし民みなよばはりいひけるは願くは王いのちながかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, '時にサムエル王國の典章を民にしめして之を書にしるし之をヱホバのまへに蔵めたりしかしてサムエル民をことごとく其家にかへらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'サウルもまたギベアの家にかへるに神に心を感ぜられたる勇士等これとともにゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, '然れども邪なる人々は彼人いかで我らを救はんやといひて之を蔑視り之に禮物をおくらざりしかどサウルは唖のごとくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'アンモニ人ナハシ、ギレアデのヤベシにのぼりて之を圍むヤベシの人々ナハシにいひけるは我らと約をなせ然らば汝につかへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'アンモニ人ナハシこれに答へけるは我かくして汝らと約をなさん即ち我汝らの右の目を抉りてイスラエルの全地に恥辱をあたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'ヤベシの長老これにいひけるは我らに七日の猶予をあたへて使をイスラエルの四方の境におくることを得さしめよ而して若し我らを救ふ者なくば我ら汝にくだらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, '斯て使サウルのギベアにいたり此事を民の耳に告しかば民皆聲をあげて哭きぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, '爰にサウル田より牛にしたがひて來るサウルいひけるは民何によりて哭くやと人々これにヤベシ人の事を告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'サウル之を聞るとき神の霊これに臨みてその怒甚だしく燃えたち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, '一軛の牛をころしてこれを切り割き使の手をもてこれをイスラエルの四方の境にあまねくおくりていはしめけるは誰にてもサウルとサムエルにしたがひて出ざる者は其牛かくのごとくせらるべしと民ヱホバを畏み一人のごとく均くいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'サウル、ベゼクにてこれを數ふるにイスラエルの子孫三十萬ユダの人三萬ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, '斯て人々來れる使にいひけるはギレアデのヤベシの人にかくいへ明日日の熱き時汝ら助を得んと使かへりてヤベシ人に告げければ皆よろこびぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, '是をもてヤベシの人云けるは明日汝らに降らん汝らの善と思ふところを爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, '明日サウル民を三隊にわかち暁更に敵の軍の中にいりて日の熱くなる時までアンモニ人をころしければ遺れる者は皆ちりぢりになりて二人倶にあるものなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, '民サムエルにいひけるはサウル豈我らの王となるべけんやと言しは誰ぞや其人を引き來れ我ら之をころさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'サウルいひけるは今日ヱホバ救をイスラエルに施したまひたれば今日は人をころすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, '茲にサムエル民にいひけるはいざギルガルに往て彼處にて王國を新にせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, '民みなギルガルにゆきて彼處にてヱホバのまへにサウルを王となし彼處にて酬恩祭をヱホバのまへに献げサウルとイスラエルの人々皆かしこにて大に祝へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'サムエル、イスラエルの人々にいひけるは視よ我汝らが我にいひし言をことごとく聽て汝らに王を立たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, '見よ今王汝らのまへにあゆむ我は老て髮しろし視よわが子ども汝らと共にあり我幼稚時より今日にいたるまで汝等のまへにあゆめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, '視よ我ここにありヱホバのまへと其膏そそぎし者のまへに我を訴へよ我誰の牛を取りしや誰の驢馬をとりしや誰を掠めしや誰を虐遇しや誰の手より賄賂をとりてわが目を矇せしや有ば我これを汝らにかへさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, '彼らいひけるは汝は我らをかすめずくるしめず又何をも人の手より取りしことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'サムエルかれらにいひけるは汝らが我手のうちに何をも見いださざるをヱホバ汝らに證したまふ其膏そそぎし者も今日證す彼ら答へけるは證したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'サムエル民にいひけるはヱホバはモーセとアロンをたてし者汝らの先祖をエジプトの地より導きいだせしものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, '立ちあがれヱホバが汝らおよび汝らの先祖になしたまひし諸の義しき行爲につきて我ヱホバのまへに汝らと論ぜん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'ヤコブのエジプトにいたるにおよびて汝らの先祖のヱホバに呼はりし時ヱホバ、モーセとアロンを遣はしたまひて此二人汝らの先祖をエジプトより導きいだして此處にすましめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'しかるに彼ら其神ヱホバを忘れしかばヱホバこれをハゾルの軍の長シセラの手とペリシテ人の手およびモアブ王の手にわたしたまへり斯て彼らこれを攻ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, '民ヱホバに呼はりていひけるは我らヱホバを棄てバアルとアシタロテに事へてヱホバに罪を犯したりされど今我らを敵の手より救ひいだしたまへ我ら汝につかへんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, '是においてヱホバ、ヱルバアルとバラクとエフタとサムエルを遣はして汝らを四方の敵の手より救ひいだしたまひて汝ら安らかに住めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'しかるに汝らアンモンの子孫の王ナハシの汝らを攻んとて來るを見て汝らの神ヱホバ汝らの王なるに汝ら我にいふ否我らををさむる王なかるべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, '今汝らが選みし王汝らがねがひし王を見よ視よヱホバ汝らに王をたてたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, '汝らもしヱホバを畏みて之につかへ其言にしたがひてヱホバの命にそむかずまた汝らと汝らををさむる王恒に汝らの神ヱホバに從はば善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'しかれども汝らもしヱホバの言にしたがはずしてヱホバの命にそむかばヱホバの手汝らの先祖をせめしごとく汝らをせむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, '汝ら今たちてヱホバが爾らの目のまへになしたまふ此大なる事を見よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, '今日は麥刈時にあらずや我ヱホバを呼んヱホバ雷と雨をくだして汝らが王をもとめてヱホバのまへに爲したる罪の大なるを見しらしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'かくてサムエル、ヱホバをよびければヱホバ其日雷と雨をくだしたまへり民みな大にヱホバとサムエルを恐る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, '民みなサムエルにいひけるは僕らのために汝の神ヱホバにいのりて我らを死なざらしめよ我ら諸の罪にまた王を求むるの惡をくはへたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'サムエル民にいひけるは懼るなかれ汝らこの總ての惡をなしたりされどヱホバに從ふことを息ず心をつくしてヱホバに事へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, '虚しき物に迷ひゆくなかれ是は虚しき物なれば汝らを助くることも救ふことも得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'ヱホバ其大なる名のために此民をすてたまはざるべし其はヱホバ汝らをおのれの民となすことを善としたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'また我は汝らのために祈ることをやめてヱホバに罪ををかすことは決てせざるべし且われ善き正しき道をもて汝らををしへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, '汝ら只ヱホバをかしこみ心をつくして誠にこれにつかへよ而して如何に大なることをヱホバ汝らになしたまひしかを思ふ可し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'しかれども汝らもしなほ惡をなさば汝らと汝らの王ともにほろぼさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'サウル三十歳にて王の位に即く彼二年イスラエルををさめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, '爰にサウル、イスラエル人三千を擇む其二千はサウルとともにミクマシおよびベテルの山地にあり其一千はヨナタンとともにベニヤミンのギベアにあり其餘の民はサウルおのおの其幕屋にかへらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'ヨナタン、ゲバにあるペリシテ人の代官をころせりペリシテ人之れをきく是においてサウル國中にあまねくラツパを吹ていはしめけるはヘブル人よ聞くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'イスラエル人皆聞けるに云くサウル、ペリシテ人の代官を撃りしかしてイスラエル、ペリシテ人の中に惡まると斯て民めされてサウルにしたがひギルガルにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'ペリシテ人イスラエルと戰はんとて集りけるが兵車三百騎兵六千にして民は濱の沙の多きがごとくなりき彼らのぼりてベテアベンにむかへるミクマシに陣をとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'イスラエルの人苦められ其危きを見て皆巖穴に林叢に崗巒に高塔に坎阱にかくれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'また或るヘブル人はヨルダンを渉りてガドとギレアデの地にいたる然るにサウルは尚ギルガルにあり民皆戰慄て之にしたがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'サウル、サムエルの定めし期にしたがひて七日とどまりしがサムエル、ギルガルに來らず民はなれて散ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'サウルいひけるは燔祭と酬恩祭を我にもちきたれと遂に燔祭をささげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, '燔祭をささぐることを終しときに視よサムエルいたるサウル安否を問はんとてこれをいで迎ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'サムエルいひけるは汝何をなせしやサウルいひけるは我民の我をはなれてちりまた汝の定まれる日のうちに來らずしてペリシテ人のミクマシに集まれるを見しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'ペリシテ人ギルガルに下りて我をおそはんに我いまだヱホバをなごめずといひて勉て燔祭をささげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'サムエル、サウルにいひけるは汝おろかなることをなせり汝その神ヱホバのなんぢに命じたまひし命令を守らざりしなり若し守りしならばヱホバ、イスラエルををさむる位を永く汝に定めたまひしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, '然どもいま汝の位たもたざるべしヱホバ其心に適ふ人を求めてヱホバ之に其民の長を命じたまへり汝がヱホバの命ぜしことを守らざるによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'かくてサムエルたちてギルガルよりベニヤミンのギベアにのぼりいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'サウルおのれとともにある民をかぞふるに凡そ六百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'サウルおよび其子ヨナタン並にこれとともにある民はベニヤミンのゲバに居りペリシテ人はミクマシに陣を張る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, '劫掠人三隊にわかれてペリシテ人の陣よりいで一隊はオフラの路にむかひてシユアルの地にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, '一隊はベテホロンの道に向ひ一隊は曠野の方にあるゼボイムの谷をのぞむ境の路にむかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, '時にイスラエルの地のうち何處にも鐵工なかりき是はペリシテ人ヘブル人の劍あるひは槍を作ることを恐れたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'イスラエル人皆其耜鋤斧耒即ち耜鋤三歯鍬斧の錣に缺ありてこれを鍛ひ改さんとする時又は鞭を尖らさんとする時は常にペリシテ人の所にくだれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, '是をもて戰の日にサウルおよびヨナタンとともにある民の手には劍も槍も見えず只サウルと其子ヨナクンのみ持り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, '茲にペリシテ人の先陣ミクマシの渡口に進む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, '其時サウルの子ヨナタン武器を執る若者にいひけるはいざ對面にあるペリシテ人の先陣に渉りゆかんと然ど其父には告ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'サウル、ギベアの極においてミグロンにある石榴の樹の下に住まりしが倶にある民はおよそ六百人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, '又アヒヤ、エポデを衣てともにをるアヒヤはアヒトブの子アヒトブはイカボデの兄弟イカボデばピネハスの子ピネハスはシロにありてヱホバの祭司たりしエリの子なり民ヨナタンの行けるをしらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'ヨナタンの渉りてペリシテ人の先陣にいたらんとする渡口の間に此傍に巉巌あり彼傍にも巉巌あり一の名をボゼツといひ一の名をセネといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, '其一は北に向ひてミクマシに對し一に南にむかひてゲバに對す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'ヨナタン武器を執る少者にいふいざ我ら此割禮なき者どもの先陣にわたらんヱホバ我らのためにはたらきたまことあらん多くの人をもて救ふも少き人をもてすくふもヱホバにおいては妨げなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, '武器をとるもの之にいひけるは總て汝の心にあるところをなせ進めよ我汝の心にしたがひて汝とともにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'ヨナタンいひけるは見よ我らかの人々のところにわたり身をかれらにあらはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'かれら若し我らが汝らにいたるまでとどまれと斯く我らにいはば我らはこのままとどまりてかれらの所にのぼらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'されど若し我らのところにのぼれとかくいはば我らのぼらんヱホバかれらを我らの手にわたしたまふなり是を徴となさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, '斯て二人其身をペリシテ人の先陣にあらはしければペリシテ人いひけるは視よヘブル人其かくれたる穴よりいで來ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'すなはち先陣の人ヨナタンと其武器を執る者にこたへて我等の所に上りきたれ目に物見せんといひしかばヨナタン武器を執る者にいひけるは我にしたがひてのぼれヱホバ彼らをイスラエルの手にわたしたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'ヨナタン攀のぼり其武器を執るもの之にしたがふペリシテ人ヨナタンのまへに仆る武器をとる者も後にしたがひて之をころす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'ヨナタンと其武器を取るもの手はじめに殺せし者およそ二十人此事田畑半段の内になれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'しかして野にある陣のものおよび凡ての民の中に戰慄おこり先陣の人および劫掠人もまたおののき地ふるひ動けり是は神よりの戰慄なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'ベニヤミンのギベアにあるサウルの戌卒望見しに視よペリシテ人の群衆くづれて此彼にちらばる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, '時にサウルおのれとともなる民にいひけるは汝ら點驗て誰が我らの中よりゆきしかを見よとすなはちしらべたるにヨナタンとその武器を執るもの居らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'サウル、アヒヤにエポデを持きたれといふ其はかれ此時イスラエルのまへにエポデを著たれば也');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'サウル祭司にかたれる時ペリシテ人の軍の騒いよいよましたりければサウル祭司にいふ姑く汝の手を措けと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'かくてサウルおよびサウルと共にある民皆呼はりて戰ひに至るにペリシテ人おのおの劍を以て互に相撃ちければその敗績はなはだ大なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'また此時よりまへにペリシテ人とともにありてペリシテ人と共に上りて陣に來るところのヘブル人もまた翻へりてサウルおよびヨナタンと共にあるイスラエル人に合せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, '又エフライムの山地にかくれたるイスラエル人皆ペリシテ人の逃るを聞てまた戰ひに出て之を追撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, '是の如くヱホバ此日イスラエルをすくひたまふ而して戰はベテアベンにうつれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'されど此日イスラエル人苦めり其はサウル民を誓はせて夕まで即ちわが敵に仇をむくゆるまでに食物を食ふ者は呪詛れんと言たればなり是故に民の中に食物を味ひし者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, '爰に民みな林森に至に地の表に蜜あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, '即ち民森にいたりて蜜のながるるをみる然ども民誓を畏るれば誰も手を口につくる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, '然にヨナタンは其父が民をちかはせしを聞ざりければ手にある杖の末をのばして蜜にひたし手を口につけたり是に由て其目あきらかになりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, '時に民のひとり答て言けるは汝の父かたく民をちかはせて今日食物をくらふ人は呪詛はれんと言り是に由て民つかれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'ヨナタンいひけるはわが父國を煩せり請ふ我この蜜をすこしく嘗しによりて如何にわが目の明かになりしかを見よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'ましてや民今日敵よりうばひし物を十分に食しならばペリシテ人をころすこと更におほかるべきにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'イスラエル人かの日ペリシテ人を撃てミクマシよりアヤロンにいたる而して民はなはだ疲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, '是において民劫掠物に走かかり羊と牛と犢とを取りて之を地のうへにころし血のままに之をくらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, '人々サウルにつげていひけるは民肉を血のままに食ひて罪をヱホバにをかすとサウルいひけるは汝ら背けり直ちにわがもとに大石をまろばしきたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'サウルまたいひけるは汝らわかれて民のうちにいりていへ人各其牛と各其羊をわがもとに引ききたり此處にてころしくらへ血のままにくらひて罪をヱホバに犯すなかれと此において民おのおのこの夜其牛を手にひききたりて之をかしこにころせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'しかしてサウル、ヱホバに一つの壇をきづく是はサウルのヱホバに壇を築ける始なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, '斯てサウルいひけるは我ら夜のうちにペリシテ人を追くだり夜明までかれらを掠めて一人をも殘すまじ皆いひけるは凡て汝の目に善とみゆる所をなせと時に祭司いひけるは我ら此にちかより神にもとめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'サウル神に我ペリシテ人をおひくだるべきか汝かれらをイスラエルの手にわたしたまふやと問けれど此日はこたへたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, '是においてサウルいひけるは民の長たちよ皆此にちかよれ汝らみて今日のこの罪のいづくにあるを知れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'イスラエルを救ひたまへるヱホバはいく假令わが子ヨナタンにもあれ必ず死なざるべからずとされど民のうち一人もこれにこたへざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'サウル、イスラエルの人々にいひけるはなんぢらは彼處にをれ我とわが子ヨナタンは此處にをらんと民いひけるは汝の目によしとみゆるところをなせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'サウル、イスラエルの神ヱホバにいひけるはねがはくは眞實をしめしたまへとかくてヨナタンとサウル籤にあたり民はのがれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'サウルいひけるは我とわが子のあひだの鬮を掣けと即ちヨナタンこれにあたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'サウル、ヨナタンにいひけるは汝がなせしところを我に告よヨナタンつげていひけるは我は只わが手の杖の末をもて少許の蜜をなめしのみなるが我しなざるをえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'サウルこたへけるは神かくなしまたかさねてかくなしたまヘヨナタンよ汝死ざるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, '民サウルにいひけるはイスラエルの中に此大なるすくひをなせるヨナタン死ぬべけんや決めてしからずヱホバは生くヨナタンの髮の毛ひとすぢも地におつべからず其はかれ神とともに今日はたらきたればなりとかく民ヨナタンをすくひて死なざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'サウル、ペリシテ人を追ことを息てのぼりぬペリシテ人其國にかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'かくてサウル、イスラエルの王の位につきて四方の敵を攻む即ちモアブ、アンモンの子孫エドム、ゾバの王たちおよびペリシテ人をせめけるに凡てむかふところにて勝利を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'サウル力をえアマレク人をうちてイスラエルを其劫掠人の手よりすくひいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'サウルの男子はヨナタン、ヱスイおよびマルキシユアなり其二人の女子の名は姉はメラブといひ妹はミカルといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'サウルの妻の名はアヒノアムといひてアヒマアズの女子なり其軍の長の名はアブネルといひてサウルの叔父なるネルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'サウルの父キシとアブネルの父ネルはアビエルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'サウルの一生のあひだ恒にペリシテ人と烈しき戰ありサウルは力ある人または勇ある人を見るごとにこれをかかへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, '茲にサムエル、サウルにいひけるはヱホバ我をつかはし汝に膏を沃ぎて其民イスラエルの王となさしめたりさればヱホバの言の聲をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, '萬軍のヱホバかくいひたまふ我アマレクがイスラエルになせし事すなはちエジプトよりのぼれる時其途を遮りしをかへりみる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, '今ゆきてアマレクを撃ち其有る物をことごとく滅しつくし彼らを憐むなかれ男女童稚哺乳兒牛羊駱駝驢馬を皆殺せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'サウル民をよびあつめてこれをテライムに核ふ歩兵二十萬ユダの人一萬あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'しかしてサウル、アマレクの邑にいたりて谷に兵を伏たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'サウル、ケニ人にいひけるは汝らゆきてさりアマレク人をはなれくだるべし恐らくはかれらとともに汝らをほろぼすにいたらんイスラエルの子孫のエジプトよりのぼれる時汝らこれに恩みをほどこしたりと即ちケニ人アマレク人をはなれてさりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'サウル、アマレク人をうちてハビラよりエジプトの東面なるシユルにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'サウル、アマレク人の王アガグを生擒り刃をもて其民をことごとくほろぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, '然ども、サウルと民アガグをゆるしまた羊と牛の最も嘉きもの及び肥たる物並に羔と凡て善き物を殘して之をほろぼしつくすをこのまず但惡き弱き物をほろぼしつくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, '時にヱホバの言サムエルにのぞみていはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '我サウルを王となせしを悔ゆ其は彼背きて我にしたがはずわが命をおこなはざればなりとサムエル憂て終夜ヱホバによばはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'かくてサムエル、サウルにあはんとて夙く起きけるにサムエルにつぐるものありていふサウル、カルメルにいたり勝利の表を立て轉り進みてギルガルにくだれりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'サムエル、サウルの許に至りければサウルこれにいひけるは汝がヱホバより福祉を得んことをねがふ我ヱホバの命を行へりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'サムエルいひけるは然らばわが耳にいる此羊の聲およびわがきく牛のこゑは何ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'サウルいひけるは人々これをアマレク人のところより引ききたれり其は民汝の神ヱホバにささげんために羊と牛の最も嘉きものをのこせばなり其ほかは我らほろぼしつくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'サムエル、サウルにいけるは止まれ昨夜ヱホバの我にかたりたまひしことを汝につげんサウルいひけるはいへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'サムエルいひけるはさきに汝が微き者とみづから憶へる時に爾イスラエルの支派の長となりしに非ずや即ちヱホバ汝に膏を注いでイスラエルの王となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'ヱホバ汝を途に遣はしていひたまはく往て惡人なるアマレク人をほろぼし其盡るまで戰へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, '何故に汝ヱホバの言をきかずして敵の所有物にはせかかりヱホバの目のまへに惡をなせしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'サウル、サムエルにひけるは我誠にヱホバの言にしたがひてヱホバのつかはしたまふ途にゆきアマレクの王アガグを執きたりアマレクをほろぼしつくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'ただ民其ほろぼしつくすべき物の最初としてギルガルにて汝の神ヱホバにささげんとて敵の物の中より羊と牛をとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'サムエルいひけるはヱホバはその言にしたがふ事を善したまふごとく燔祭と犠牲を善したまふや夫れ順ふ事は犠牲にまさり聽く事は牡羔の脂にまさるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, '其は違逆は魔術の罪のごとく抗戻は虚しき物につかふる如く偶像につかふるがごとし汝ヱホバの言を棄たるによりヱホバもまた汝をすてて王たらざらしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'サウル、サムエルにいひけるに我ヱホバの命と汝の言をやぶりて罪ををかしたり是は民をおそれて其言にしたがひたるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'されば今ねがはくはわがつみをゆるし我とともにかへりて我をしてヱホバを拝することをえさしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'サムエル、サウルにいひけるは我汝とともにかへらじ汝ヱホバの言を棄たるによりヱホバ汝をすててイスラエルに王たらしめたまはざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'サムエル去らんとて振還しときサウルその明衣の裾を捉へしかば裂たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'サムエルかれにいひけるは今日ヱホバ、イスラエルの國を裂て汝よりはなし汝の隣なる汝より善きものにこれをあたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'またイスラエルの能力たる者は謊らず悔ず其はかれは人にあらざればくゆることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'サウルいひけるは我罪ををかしたれどねがはくはわが民の長老のまへおよびイスラエルのまへにて我をたふとみて我とともにかへり我をして汝の神ヱホバを拝むことをえさしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'ここにおいてサムエル、サウルにしたがひてかへるしかしてサウル、ヱホバを拝む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, '時にサムエルいひけるは汝らわが許にアマレクの王アガグをひききたれとアガグ喜ばしげにサムエルの許にきたりアガグいひけるは死の苦みは必ず過さりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'サムエルいひけるに汝の劍はおほくの婦人を子なき者となせりかくのごとく汝の母は婦人の中の最も子なき者となるべしとサムエル、ギルガルにてヱホバのまへにおいてアガグを斬り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'かくてサムエルはラマにゆきサウルはサウルのギベアにのぼりてその家にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'サムエル其しぬる日までふたたびきたりてサウルをみざりきしかれどもサムエル、サウルのためにかなしめりまたヱホバはサウルをイスラエルの王となせしを悔たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, '爰にヱホバ、サムエルにいひたまひけるは我すでにサウルを棄てイスラエルに王たらしめざるに汝いつまでかれのために歎くや汝の角に膏油を滿してゆけ我汝をベテレヘム人ヱサイの許につかはさん其は我其子の中にひとりの王を尋ねえたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'サムエルいひけるは我いかで往くことをえんサウル聞て我をころさんヱホバいひたまひけるは汝一犢を携へゆきて言へヱホバに犠牲をささげんために來ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'しかしてヱサイを犠牲の場によべ我汝が爲すべき事をしめさん我汝に告るところの人に膏をそそぐ可し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'サムエル、ヱホバの語たまひしごとくなしてベテレヘムにいたる邑の長老おそれて之をむかへいひけるは汝平康なる事のためにきたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'サムエルいひけるは平康なることのためなり我はヱホバに犠牲をささげんとてきたる汝ら身をきよめて我とともに犠牲の場にきたれと斯てヱサイと其諸子を潔めて犠牲の場によびきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'かれらが至れる時サムエル、エリアブを見ておもへらくヱホバの膏そそぐものは必ず此人ならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'しかるにヱホバ、サムエルにいひたまひけるは其容貌と身長を觀るなかれ我すでにかれをすてたりわが視るところは人に異なり人は外の貌を見ヱホバは心をみるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'ヱサイ、ヘアビナダブをよびてサムエルのまへを過しむサムエルいひけるは此人もまたヱホバ擇みたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'ヱサイ、シヤンマを過しむサムエルいひけるは此人もまたヱホバえらみたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'ヱサイ其七人の子をしてサムエルの前をすぎしむサムエル、ヱサイにいふヱホバ是等をえらみたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'サムエル、ヱサイにいひけるは汝の男子は皆此にをるやヱサイいひけるは尚季子のこれり彼は羊を牧をるなりとサムエル、ヱサイにいひけるは彼を迎へきたらしめよかれが此にいたるまでは我ら食に就かざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, '是において人をつかはしてかれをつれきたらしむ其人色赤く目美しくして其貌麗しヱホバいひたまひけるは起てこれにあぶらを沃げ是其人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'サムエル膏の角をとりて其兄弟の中にてこれに膏をそそげり此日よりのちヱホバの霊ダビデにのぞむサムエルはたちてラマにゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'かくてヱホバの霊サウルをはなれヱホバより來る惡鬼これを惱せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'サウルの臣僕これにいひけるは視よ神より來れる惡鬼汝をなやます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'ねがはくはわれらの主汝のまへにつかふる臣僕に命じて善く琴を鼓く者一人を求めしめよ神よりきたれる惡鬼汝に臨む時彼手をもて琴を鼓て汝いゆることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'サウル臣僕にいひけるはわがために巧に鼓琴者をたづねてわがもとにつれきたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, '時に一人の少者こたへていひけるは我ベテレヘム人ヱサイの子を見しが琴に巧にしてまた豪氣して善くたたかふ辯舌さはやかなる美しき人なりかつヱホバこれとともにいます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'サウルすなはち使者をヱサイにつかはしていひけるは羊をかふ汝の子ダビデをわがもとに遣はせと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'ヱサイすなはち驢馬にパンを負せ一嚢の酒と山羊の羔を執りてこれを其子ダビデの手によりてサウルにおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'ダビデ、サウルの許にいたりて其まへに事ふサウル大にこれを愛し其武器を執る者となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'サウル人をヱサイにつかはしていひけるはねがはくはダビデをしてわが前に事へしめよ彼はわが心にかなへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, '神より出たる惡鬼サウルに臨めるときダビデ琴を執り手をもてこれを弾にサウル慰さみて愈え惡鬼かれをはなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, '爰にペリシテ人其軍を集めて戰はんとしユダに屬するシヨコにあつまりシヨコとアゼカの間なるバスダミムに陣をとる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'サウルとイスラエルの人々集まりてエラの谷に陣をとりペリシテ人にむかひて軍の陣列をたつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'ペリシテ人は此方の山にたちイスラエルは彼方の山にたつ谷は其あひだにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, '時にペリシテ人の陣よりガテのゴリアテと名くる挑戰者いできたる其身の長六キユビト半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, '首に銅の盔を戴き身に鱗綴の鎧甲を着たり其よろひの銅のおもさは五千シケルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'また脛には銅の脛當を着け肩の間に銅の矛戟を負ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, '其槍の柄は機の梁のごとく槍の鋒刃の鐵は六百シケルなり楯を執る者其前にゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'ゴリアテ立てイスラエルの諸行伍によばはり云けるは汝らはなんぞ陣列をなして出きたるや我はペリシテ人にして汝らはサウルの臣下にあらずや汝ら一人をえらみて我ところにくだせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, '其人もし我とたたかひて我をころすことをえば我ら汝らの臣僕とならんされど若し我かちてこれを殺さば汝ら我らの僕となりて我らに事ふ可し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'かくて此ペリシテ人いひけるは我今日イスラエルの諸行伍を挑む一人をいだして我と戰はしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'サウルおよびイスラエルみなペリシテ人のこの言を聞き驚きて大に懼れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, '抑ダビデはかのベテレヘムユダのエフラタ人ヱサイとなづくる者の子なり此人八人の子ありしがサウルの世には年邁みてすでに老たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'ヱサイの長子三人ゆきてサウルにしたがひて戰爭にいづ其戰にいでし三人の子の名は長をエリアブといひ次をアビナダブといひ第三をシヤンマといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'ダビデは季子にして其兄三人はサウルにしたがへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'ダビデはサウルに往來してベテレヘムにて其父の羊を牧ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, '彼ペリシテ人四十日のあひだ朝夕近づきて前にたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, '時にヱサイ其子ダビデにいひけるは今汝の兄のために此烘麥一斗と此十のパンを取りて陣營にをる兄のところにいそぎゆけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'また此十の乾酪をとりて其千夫の長におくり兄の安否を視て其返事をもちきたれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'サウルと彼等およびイスラエルの人は皆ペリシテ人とたたかひてエラの谷にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'ダビデ朝夙くおきて羊をひとりの牧者にあづけヱサイの命ぜしごとく携へゆきて車營にいたるに軍勢いでて行伍をなし鯨波をあげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'しかしてイスラエルとペリシテ人陣列をたてて行伍を行伍に相むかはせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'ダビデ其荷をおろして荷をまもる者の手にわたし行伍の中にはせゆきて兄の安否を問ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'ダビデ彼等と倶に語れる時視よペリシテ人の行伍よりガテのペリシテのゴリアテとなづくる彼の挑戰者のぼりきたり前のことばのごとく言しかばダビデ之を聞けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'イスラエルの人其人を見て皆逃て之をはなれ痛く懼れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'イスラエルの人いひけるは汝らこののぼり來る人を見しや誠にイスラエルを挑んとて上りきたるなり彼をころす人は王大なる富を以てこれをとまし其女子をこれにあたへて其父の家にはイスラエルの中にて租税をまぬかれしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'ダビデ其傍にたてる人々にかたりていひけるは此ペリシテ人をころしイスラエルの耻辱を雪ぐ人には如何なることをなすや此割禮なきペリシテ人は誰なればか活る神の軍を搦む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, '民まへのごとく答へていひけるはかれを殺す人には斯のごとくせらるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, '兄エリアブ、ダビデが人々とかたるを聞しかばエリアブ、ダビデにむかひて怒りを發しいひけるは汝なにのために此に下りしや彼の野にあるわづかの羊を誰にあづけしや我汝の傲慢と惡き心を知る其は汝戰爭を見んとて下ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'ダビデいひけるは我今なにをなしたるや只一言にあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, '又ふりむきて他の人にむかひ前のごとく語れるに民まへのごとく答たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, '人々ダビデが語れる言をききてこれをサウルのまへにつげければサウルかれを召す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'ダビデ、サウルにいひけるは人々かれがために氣をおとすべからず僕ゆきてかのペリシテ人とたたかはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'サウル、ダビデにいひけるは汝はかのペリシテ人をむかへてたたかふに勝ず其は汝は少年なるにかれは若き時よりの戰士なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'ダビデ、サウルにいひけるは僕さきに父の羊を牧るに獅子と熊と來りて其群の羔を取たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, '其後をおひて之を搏ち羔を其口より援ひいだせりしかして其獣我に猛りかかりたれば其鬚をとらへてこれを撃ちころせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, '僕は旣に獅子と熊とを殺せり此割禮なきペリシテ人活る神の軍をいどみたれば亦かの獣の一のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'ダビデまたいひけるはヱホバ我を獅子の爪と熊の爪より援ひいだしたまひたれば此ペリシテ人の手よりも援ひいだしたまはんとサウル、ダビデにいふ往けねがはくはヱホバ汝とともにいませ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, '是においてサウルおのれの戎衣をダビデに衣せ銅の盔を其首にかむらせ亦鱗綴の鎧をこれにきせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'ダビデ戎衣のうへに劍を佩て往かんことを試む未だ驗せしことなければなりしかしてダビデ、サウルにいひけるは我いまだ驗せしことなければ是を衣ては往くあたはずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'ダビデこれを脱ぎすて手に杖をとり谿間より五の光滑なる石を拾ひて之を其持てる牧羊者の具なる袋に容れ手に投石索を執りて彼ペリシテ人にちかづく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'ペリシテ人進みきてダビデに近づけり楯を執るもの其まへにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'ペリシテ人環視てダビデを見て之を藐視る其は少くして赤くまた美しき貌なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'ペリシテ人ダビデにいひけるは汝杖を持てきたる我豈犬ならんやとペリシテ人其神の名をもってダビデを呪詛ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'しかしてペリシテ人ダビデにいひけるは我がもとに來れ汝の肉を空の鳥と野の獣にあたへんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'ダビデ、ペリシテ人にいひけるは汝は劍と槍と矛戟をもて我にきたる然ど我は萬軍のヱホバの名すなはち汝が搦みたるイスラエルの軍の神の名をもて汝にゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, '今日ヱホバ汝をわが手に付したまはんわれ汝をうちて汝の首級を取りペリシテ人の軍勢の尸體を今日空の鳥と地の野獣にあたへて全地をしてイスラエルに神あることをしらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, '且又この群衆みなヱホバは救ふに劍と槍を用ひたまはざることをしるにいたらん其は戰はヱホバによれば汝らを我らの手にわたしたまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'ペリシテ人すなはち立あがり進みちかづきてダビデをむかへしかばダビデいそぎ陣にはせゆきてペリシテ人をむかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'ダビデ手を嚢にいれて其中より一つの石をとり投てペリシテ人の顙を撃ければ石其顙に突きいりて俯伏に地にたふれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'かくダビデ投石索と石をもてペリシテ人にかちペリシテ人をうちて之をころせり然どダビデの手には劍なかりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'ダビデはしりてペリシテ人の上にのり其劍を取て之を鞘より抜きはなしこれをもて彼をころし其首級を斬りたり爰にペリシテの人々其勇士の死るを見てにげしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'イスラエルとユダの人おこり喊呼をあげてペリシテ人をおひガテの入口およびエクロンの門にいたるペリシテ人の負傷人シヤライムの路に仆れてガテおよびエクロンにおよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'イスラエルの子孫ペリシテ人をおふてかへり其陣を掠む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'ダビデかのペリシテ人の首を取りて之をエルサレムにたづさへきたりしが其甲冑はおのれの天幕におけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'サウル、ダビデがペリシテ人にむかひて出るを見て軍長アブネルにいひけるはアブネル此少者はたれの子なるやアブネルいひけるは王汝の霊魂は生くわれしらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, '王いひけるはこの少年はたれの子なるかを尋ねよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'ダビデかのペリシテ人を殺してかへれる時アブネルこれをひきて其ペリシテ人の首級を手にもてるままサウルのまへにつれゆきければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'サウルかれにいひけるは若き人よ汝はたれの子なるやダビデこたへけるは汝の僕ベテレヘム人ヱサイの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'ダビデ、サウルにかたることを終しときヨナタンの心ダビデの心にむすびつきてヨナタンおのれの命のごとくダビデを愛せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, '此日サウル、ダビデをかかへて父の家にかへらしめず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'ヨナタンおのれの命のごとくダビデを愛せしかばヨナタンとダビデ契約をむすべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'ヨナタンおのれの衣たる明衣を脱てダビデにあたふ其戎衣および其刀も弓も帶もまたしかせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'ダビデは凡てサウルが遣はすところにいでゆきて功をあらはしければサウルかれを兵隊の長となせりしかしてダビデ民の心にかなひ又サウルの僕の心にもかなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, '衆人かへりきたれる時すなはちダビデ、ペリシテ人をころして還れる時婦女イスラエルの邑々よりいできたり鼗と祝歌と磬をもちて歌ひまひつつサウル王を迎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, '婦人踊躍つつ相こたへて歌ひけるはサウルは千をうち殺しダビデは萬をうちころすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'サウル甚だ怒りこの言をよろこばずしていひけるは萬をダビデに歸し千をわれに歸す此上かれにあたふべき者は唯國のみと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'サウルこの日より後ダビデを目がけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, '次の日神より出たる惡鬼サウルにのぞみてサウル家のなかにて預言したりしかばダビデ故のごとく手をもつて琴をひけり時にサウルの手に投槍ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'サウル我ダビデを壁に刺とほさんといひて其投槍をさしあげしがダビデ二度身をかはしてサウルをさけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'ヱホバ、サウルをはなれてダビデと共にいますによりてサウル彼をおそれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, '是故にサウル彼を遠ざけて千夫長となせりダビデすなはち民のまへに出入す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'またダビデすべて其ゆくところにて功をあらはし且ヱホバかれとともにいませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'サウル、ダビデが大に功をあらはすをみてこれを恐れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'しかれどもイスラエルとユダの人はみなダビデを愛せり彼が其前に出入するによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'サウル、ダビデにいひけるはわれわが長女メラブを汝に妻さん汝ただわがために勇みヱホバの軍に戰ふべしと其はサウルわが手にてかれを殺さでペリシテ人の手にてころさんとおもひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'ダビデ、サウルにいひけるは我は誰ぞわが命はなんぞわが父の家はイスラエルにおいて何なる者ぞや我いかでか王の婿となるべけんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, '然るにサウルの女子メラブはダビデに嫁ぐべき時におよびてメホラ人アデリエルに妻されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'サウルの女ミカル、ダビデを愛す人これを王に告ければサウル其事を善しとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'サウルいひけるは我ミカルをかれにあたへて彼を謀る手段となしペリシテ人の手にてかれを殺さんといひてサウル、ダビデにいひけるは汝今日ふたたびわが婿となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'かくてサウル其僕に命じけるは汝ら密にダビデにかたりて言へ視よ王汝を悦び王の僕みな汝を愛すされば汝王の婿となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'サウルの僕此言をダビデの耳に語りしかばダビデいひけるは王の婿となること汝らの目には易き事とみゆるや且われは貧しく賤しき者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'サウルの僕サウルにつげてダビデ是の如くかたれりといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'サウルいひけるはなんぢらかくダビデにいへ王は聘禮を望まずただペリシテ人の陽皮一百をえて王の仇をむくいんことを望むと是はサウル、ダビデをペリシテ人の手に殞沒しめんとおもへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'サウルの僕此言をダビデにつげしかばダビデは王の婿となることを善とせり斯て其時いまだ滿ざるあひだに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'ダビデ起て其從者とともにゆきペリシテ人二百人をころして其陽皮をたづさへきたり之を悉く王にささげて王の婿とならんとすサウル乃はち其女ミカルをダビデに妻せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'サウル見てヱホバのダビデとともにいますを知りぬまたサウルの女ミカルはダビデを愛せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'サウルさらにますますダビデを恐れサウル一生のあひだダビデの敵となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, '爰にペリシテ人の諸伯攻きたりしがダビデかれらが攻めきたるごとにサウルの諸の臣僕よりは多の功をたてしかば其名はなはだ尊まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'サウル其子ヨナタンおよび諸の臣僕にダビデをころさんとすることを語れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'されどサウルの子ヨナタン深くダビデを愛せしかばヨナタン、ダビデにつげていひけるはわが父サウル汝をころさんことを求むこのゆゑに今ねがはくは汝翌朝謹恪で潜みをりて身を隱せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, '我いでゆきて汝がをる野にてわが父の傍にたちわが父とともに汝の事を談はんしかして我其事の如何なるを見て汝に告ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'ヨナタン其父サウルに向ひダビデを褒揚ていひけるは願くは王其僕ダビデにむかひて罪ををかすなかれ彼は汝に罪ををかさずまた彼が汝になす行爲ははなはだ善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'またかれは生命をかけてかのペリシテ人をころしたりしかしてヱホバ、イスラエルの人々のためにおほいなる救をほどこしたまふ汝見てよろこべりしかるに何ぞゆゑなくしてダビデをころし無辜者の血をながして罪ををかさんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'サウル、ヨナタンの言を聽いれサウル誓ひけるはヱホバはいくわれかならずかれをころさじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'ヨナタン、ダビデをよびてヨナタン其事をみなダビデにつげ遂にダビデをサウルの許につれきたりければダビデさきのごとくサウルの前にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, '爰に再び戰爭おこりぬダビデすなはちいでてペリシテ人とたたかひ大にかれらを殺せしかばかれら其まへを逃げされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'サウル手に投槍を執て室に坐する時ヱホバより出たる惡鬼これにのりうつれり其時ダビデ乃ち手をもて琴を弾く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'サウル投槍をもてダビデを壁に刺とほさんとしたりしがダビデ、サウルのまへを避ければ投槍を壁に衝たてたりダビデ其夜逃さりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'サウル使者をダビデの家につかはしてかれを守らしめ朝におよびてかれをころさしめんとすダビデの妻ミカル、ダビデにつげていひけるは若し今夜爾の命を援ずば明朝汝は殺されんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'ミカル即ち牖よりダビデを縋おろしければ往て逃されり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, '斯てミカル像をとりて其牀に置き山羊の毛の編物を其頭におき衣服をもて之をおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'サウル、ダビデを執ふる使者をつかはしければミカルいふかれは疾ありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'サウル使者をつかはしダビデを見させんとていひけるはかれを牀のまま我にたづさきたれ我これをころさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, '使者いりて見たるに牀には像ありて其頭に山羊の毛の編物ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'サウル、ミカルにいひけるはなんぞかく我をあざむきてわが敵を逃しやりしやミカル、サウルにこたへけるは彼我にいへり我をはなちてさらしめよ然らずば我汝をころさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'ダビデにげさりてラマにゆきサムエルの許にいたりてサウルがおのれになせしことをことごとくつげたりしかしてダビデとサムエルはゆきてナヨテにすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'サウルに告る者ありていふ視よダビデはラマのナヨテにをると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'サウル乃ちダビデを執ふる使者をつかはせしが彼等預言者の一群の預言しをりてサムエルが其中の長となりて立てるを見るにおよび神の霊サウルの使者にのぞみて彼等もまた預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, '人々これを告ければサウル他の使者を遣しけるにかれらも亦預言せしかばサウルまた三度使者を遣はしけるが彼等もまた預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, '是においてサウルもまたラマにゆきけるがセクの大井にいたれる時問ていひけるはサムエルとダビデは何處にをるや答ていふラマのナヨテにをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'サウルかしこにゆきてラマのナヨテに至りけるに神の霊また彼にのぞみて彼ラマのナヨテにいたるまで歩きつつ預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, '彼もまた其衣服をぬぎすて同くサムエルのまへに預言し其一日一夜裸體にて仆臥たり是故に人々サウルもまた預言者のうちにあるかといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'ダビデ、ラマのナヨテより逃きたりてヨナタンにいひけるは我何をなし何のあしき事あり汝の父のまへに何の罪を得てか彼わが命を求むる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'ヨナタンかれにいひけるは汝決て殺さるることあらじ視よわが父は事の大なるも小なるも我につげずしてなすことなしわが父なんぞこの事を我にかくさんやこの事しからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'ダビデまた誓ひていひけるは汝の父必ずわが汝のまへに恩惠をうるを知る是をもてかれ思へらく恐らくはヨナタン悲むべければこの事をかれにしらしむべからずとしかれどもヱホバはいくまたなんぢの霊魂はいくわれは死をさること只一歩のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'ヨナタン、ダビデにいひけるはなんぢの心なにをねがふか我爾のために之をなさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'ダビデ、ヨナタンにいひけるは明日は月朔なれば我王とともに食につかざるべからず然ども我をゆるして去らしめ三日の晩まで野に隱るることをえさしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, '若汝の父まことに我をもとめなば其時言へダビデ切に其邑ベテレヘムにはせゆかんことを我に請り其は彼處に全家の歳祭あればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, '彼もし善しといはば僕やすからんされど彼もし甚しく怒らば彼の害をくはへんと決しを知れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, '汝ヱホバのまへに僕と契約をむすびたれば願くは僕に恩をほどこせ然ど若我に惡き事あらば汝自ら我をころせ何ぞ我を汝の父に引ゆくべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'ヨナタンいひけるは斯る事かならず汝にあらざれ我わが父の害を汝にくはへんと決るをしらば必ず之を汝につげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'ダビデ、ヨナタンにいひけるは若し汝の父荒々しく汝にこたふる時は誰か其事を我に告ぐべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'ヨナタン、ダビデにいひけるは來れ我ら野にいでゆかんと倶に野にいでゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'しかしてヨナタン、ダビデにいひけるはイスラエルの神ヱホバよ明日か明後日の今ごろ我わが父を窺ひて事のダビデのために善きを見ながら人を汝に遣はして告しらさずばヱホバ、ヨナタンに斯なしまた重て斯くなしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'されど若しわが父汝に害をくはへんと欲せば我これを告げしらせて汝をにがし汝を安らかにさらしめん願くはヱホバわが父とともに坐せしごとく汝とともにいませ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, '汝只わが生るあひだヱホバの恩を我にしめして死ざらしむるのみならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'ヱホバがダビデの敵を悉く地の表より絶ちさりたまふ時にもまた汝わが家を永く汝の恩にはなれしむるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'かくヨナタン、ダビデの家と契約をむすぶヱホバ之に關てダビデの敵を討したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'しかしてヨナタンふたたびダビデに誓はしむかれを愛すればなり即ちおのれの生命を愛するごとく彼を愛せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'またヨナタン、ダビデにいひけるは明日は月朔なるが汝の座空かるべければ汝求めらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, '汝三日とどまりて速かに下り嘗てかの事の日に隱れたるところに至りてエゼルの石の傍に居るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, '我的を射るごとくして其石の側に三本の矢をはなたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'しかしてゆきて矢をたづねよといひて僮子をつかはすべし我もし故に僮子に視よ矢は汝の此旁にあり其を取と曰ばなんぢきたるべしヱホバは生く汝安くして何もなかるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'されど若し我少年に視よ矢は汝の彼旁にありといはば汝さるべしヱホバ汝をさらしめたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, '汝と我とかたれることについては願はくはヱホバ恒に汝と我との間にいませと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'ダビデ即ち野にかくれぬ偖月朔になりければ王坐して食に就く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, '即ち王は常のごとく壁によりて座を占むヨナタン立あがりアブネル、サウルの側に坐すダビデの座はなむし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'されど其日にはサウル何をも曰ざりき其は何事か彼におこりしならん彼きよからず定て潔からずと思ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, '明日すなはち月の二日におよびてダビデの座なほ虚しサウル其子ヨナタンにいひけるは何ゆゑにヱサイの子は昨日も今日も食に來らざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'ヨナタン、サウルにこたへけるはダビデ切にベテレヘムにゆかんことを我にこひて曰けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'ねがはくは我をゆるしてゆかしめよわが家邑にて祭をなすによりわが兄我にきたることを命ぜり故に我もし汝のまへにめぐみをえたるならばねがはくは我をゆるして去しめ兄弟をみることを得さしめよと是故にかれは王の席に來らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'サウル、ヨナタンにむかひて怒りを發しかれにいひけるは汝は曲り且悖れる婦の子なり我あに汝がヱサイの子を簡みて汝の身をはづかしめまた汝の母の膚を辱しむることを知ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'ヱサイの子の此世にながらふるあひだは汝と汝の位固くたつを得ず是故に今人をつかはして彼をわが許に引きたれ彼は死ぬべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'ヨナタン父サウルに對へていひけるは彼なにによりて殺さるべきか何をなしたるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'ここにおいてサウル、ヨナタンを撃んとて投槍をさしあげたりヨナタンすなはち其父のダビデを殺さんと決しをしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'かくてヨナタン烈しく怒りて席を立ち月の二日には食をなさざりき其は其父のダビデをはづかしめしによりてダビデのために憂へたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, '翌朝ヨナタン一小童子を從がヘダビデと約せし時刻に野にいでゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, '童にいひけるは走りて我はなつ矢をたづねよと童子はしる時ヨナタン矢を彼のさきに發てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, '童子がヨナタンの發ちたる矢のところにいたれる時ヨナタン童子のうしろに呼はりていふ矢は汝のさきにあるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'ヨナタンまた童子のうしろによばはりていひけるは速かにせよ急げ止まるなかれとヨナタンの童子矢をひろひあつめて其主人のもとにかへる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'されど童子は何をも知ざりき只ヨナタンとダビデ其事をしりたるのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'かくてヨナタン其武器を童子に授ていひけるは往けこれを邑に携へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, '童子すなはち往けり時にダビデ石の傍より立ちあがり地にふして三たび拝せりしかしてふたり互に接吻してたがひに哭くダビデ殊にはなはだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'ヨナタン、ダビデにいひけるは安じて往け我ら二人ともにヱホバの名に誓ひて願くはヱホバ恒に我と汝のあひだに坐し我が子孫と汝の子孫のあひだにいませといへりとダビデすなはちたちて去るヨナタン邑にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'ダビデ、ノブにゆきて祭司アヒメレクにいたるアヒメレク懼れてダビデを迎へこれにいひけるは汝なんぞ獨にして誰も汝とともならざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'ダビデ祭司アヒメレクにいふ王我に一の事を命じて我にいふ我が汝を遣はすところの事およびわが汝に命じたる所については何をも人にしらするなかれと我某處に我少者を出おけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'いま何か汝の手にあるや我手に五のパンか或はなににてもある所を與よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, '祭司ダビデに對ていひけるは常のパンはわが手になしされど若し少者婦女をだに愼みてありしならば聖きパンあるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'ダビデ祭司に對へていひけるは實にわがいでしより此三日は婦女われらにちかづかず且少者等の器は潔し又パンは常の物のごとし今日器に潔きパンあれば殊に然と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, '祭司かれに聖きパンを與たり其はかしこに供前のパンの外はパン无りければなり即ち其パンは下る日に熱きパンをささげんとて之をヱホバのまへより取されるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, '其日かしこにサウルの僕一人留められてヱホバのまへにあり其名をドエグといふエドミ人にしてサウルの牧者の長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'ダビデまたアヒメレクにいふ此に汝の手に槍か劍あらぬか王の事急なるによりて我は刀も武器も携へざりしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, '祭司いひけるは汝がエラの谷にて殺したるペリシテ人ゴリアテの劍布に裏みてエポデの後にあり汝もし之をとらんとおもはば取れ此にはほかの劍なしダビデいひけるはそれにまさるものなし我にあたへよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'ダビデ其日サウルをおそれて立てガテの王アキシのところに逃げゆきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'アキシの臣僕アキシに曰けるは此は其地の王ダビデにあらずや人々舞踏のうちにこの人のことを歌ひあひてサウルは千をうちころしダビデは萬をうちころすといひしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'ダビデこの言を心に蔵め深くガテの王アキシをおそれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, '人々のまへに佯て其氣を變じ執はれて狂人のさまをなし門の扉に書き其涎沫を鬚にながれくだらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'アキシ僕に云けるは汝らの見るごとく此人は狂人なり何ぞかれを我にひき來るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, '我なんぞ狂人を須ひんや汝ら此者を引きたりてわがまへに狂しめんとするや此者なんぞ吾が家にいるべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, '是故にダビデ其處をいでたちてアドラムの洞穴にのがる其兄弟および父の家みな聞きおよびて彼處にくだり彼の許に至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'また惱める人負債者心に嫌ぬ者皆かれの許にあつまりて彼其長となれりかれとともにある者はおよそ四百人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'ダビデ其處よりモアブのミヅパにいたりモアブの王にいひけるは神の我をいかがなしたまふかを知るまでねがはくはわが父母をして出て汝らとともにをらしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, '遂にかれらをモアブの王のまへにつれきたるかれらはダビデが要害にをる間王とともにありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, '預言者ガデ、ダビデに云けるは要害に住るなかれゆきてユダの地にいたれとダビデゆきてハレテの叢林にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, '爰にサウル、ダビデおよびかれとともなる人々の見露されしを聞けり時にサウルはギベアにあり手に槍を執て岡巒の柳の樹の下にをり臣僕ども皆其傍にたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'サウル側にたてる僕にいひけるは汝らベニヤミン人聞けよヱサイの子汝らおのおのに田と葡萄園をあたへ汝らおのおのを千夫長百夫長となすことあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, '汝ら皆我に敵して謀り一人もわが子のヱサイの子と契約を結びしを我につげしらする者なしまた汝ら一人もわがために憂へずわが子が今日のごとくわが僕をはげまして道に伏て我をおそはしめんとするを我につげしらす者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, '時にエドミ人ドエグ、サウルの僕の中にたち居りしが答へていひけるは我ヱサイの子のノブにゆきてアヒトブの子アヒメレクに至るを見しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'アヒメレクかれのためにヱホバに問ひまたかれに食物をあたへペリシテ人ゴリアテの劍をあたへたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, '王すなはち人をつかはしてアヒトブの子祭司アヒメレクなよびその父の家すなはちノブの祭司たる人々を召したればみな王の許にきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'サウルいひけるは汝アヒトブの子聽よ答へけるは主よ我ここにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'サウルかれにいふ汝なんぞヱサイの子とともに我に敵して謀り汝かれにパンと劍をあたへ彼が爲に神に問ひかれをして今日のごとく道に伏て我をおそはしめんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'アヒメレク王にこたへていひけるは汝の臣僕のうち誰かダビデのごとく忠義なる彼は王の婿にして親しく汝に見ゆるもの汝の家に尊まるる者にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, '我其時かれのために神に問ことを始めしや決てしからずねがはくは王僕およびわが父の全家に何をも歸するなかれ其は僕この事については多少をいはず何をもしらざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, '王いひけるはアヒメレク汝必ず死ぬべし汝の父の全家もしかりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, '王旁にたてる前驅の人々にいひけるは身をひるがへしてヱホバの祭司を殺せかれらもダビデと力を合するが故またかれらダビデの逃たるをしりて我に告ざりし故なりと然ど王の僕手をいだしてヱホバの祭司を撃ことを好まざれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, '王ドエグにいふ汝身をひるがへして祭司をころせとエドミ人ドエグ乃ち身をひるがへして祭司をうち其日布のエポデを衣たる者八十五人をころせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'かれまた刃を以て祭司の邑ノブを撃ち刃をもて男女童稚嬰孩牛驢馬羊を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'アヒトブの子アヒメレクの一人の子アビヤタルとなづくる者逃れてダビデにはしり從がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'アビヤタル、サウルがヱホバの祭司を殺したることをダビデに告しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'ダビデ、アビヤタルにいふかの日エドミ人ドエグ彼處にをりしかば我かれが必らずサウルにつげんことを知れり我汝の父の家の人々の生命を喪へる源由となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, '汝我とともに居れ懼るるなかれわが生命を求むる者汝の生命をも求むるなり汝我とともにあらば安全なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, '人々ダビデにつげていひけるは視よペリシテ人ケイラを攻め穀場を掠むと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'ダビデ、ヱホバに問ていひけるは我ゆきて是のペリシテ人を撃つべきかとヱホバ、ダビデにいひたまひけるは往てペリシテ人をうちてケイラを救ヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'ダビデの從者かれにいひけるは視よわれら此にユダにあるすら尚ほおそる况やケイラにゆきてペリシテ人の軍にあたるをやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'ダビデふたたびヱホバに問ひけるにヱホバ答ていひたまひけるは起てケイラにくだれ我ペリシテ人を汝の手にわたすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'ダビデとその從者ケイラにゆきてペリシテ人とたたかひ彼らの家畜を奪ひとり大にかれらをうちころせりかくダビデ、ケイラの居民をすくふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'アヒメレクの子アビヤタル、ケイラにのがれてダビデにいたれる時其手にエポデを執てくだれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, '爰にダビデのケイラに至れる事サウルに聞えければサウルいふ神かれを我手にわたしたまへり其はかれ門あり關ある邑にいりたれば閉こめらるればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'サウルすなはち民をことごとく軍によびあつめてケイラにくだりてダビデと其從者を圍んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'ダビデはサウルのおのれを害せんと謀るを知りて祭司アビヤタルにいひけるはエポデを持ちきたれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'しかしてダビデいひけるはイスラエルの神ヱホバよ僕たしかにサウルがケイラにきたりてわがために此邑をほろぼさんと求むるを聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'ケイラの人々我をかれの手にわたすならんか僕のきけるごとくサウル下るならんかイスラエルの神ヱホバよ請ふ僕につげたまへとヱホバいひたまひけるは彼下るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'ダビデいひけるはケイラの人々われとわが從者をサウルの手にわたすならんかヱホバいひたまひけるは彼らわたすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, '是においてダビデと其六百人ばかりの從者起てケイラをいで其ゆきうる所にゆけりダビデのケイラをにげはなれしことサウルに聞えければサウルいづることを止たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'ダビデは曠野にをり要害の地にをりまたジフの野にある山に居るサウル恒にかれを尋ねたれども神かれを其手にわたしたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'ダビデ、サウルがおのれの生命を求めんために出たるを見る時にダビデはジフの野の叢林にをりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'サウルの子ヨナタンたちて叢林にいりてダビデにいたり神によりて其力を強うせしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, '即ちヨナタンかれにいひけるに懼るるなかれわが父サウルの手汝にとどくことあらじ汝はイスラエルの王とならん我は汝の次なるべし此事はわが父サウルもしれりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'かくて彼ら二人ヱホバのまへに契約をむすびダビデは叢林にとどまりヨナタンは其家にかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, '時にジフ人ギベアにのぼりサウルの許にいたりていひけるはダビデは曠野の南にあるハキラの山の叢林の中なる要害に隱れて我らとともにをるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, '今王汝のくだらんとする望のごとく下りたまへ我らはかれを王の手にわたさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'サウルいひけるは汝ら我をあはれめば願くは汝等ヱホバより福祉をえよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, '請ふゆきて尚ほ心を用ひ彼の踪跡ある處と誰がかれを見たるかを見きはめよ其は人我にかれが甚だ機巧く事を爲すを告たれば也');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'されば汝ら彼が隱るる逃躱處を皆たしかに見きはめて再び我にきたれ我汝らとともにゆかん彼もし其地にあらば我ユダの郡中をあまねく尋ねて彼を獲んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'かれらたちてサウルに先てジフにゆけりダビデと其從者は曠野の南のアラバにあるマオンの野にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, '斯てサウルと其從者ゆきて彼を尋ぬ人々これをダビデに告ければダビデ巌を下てマオンの野にをるサウル之を聞てマオンの野に至てダビデを追ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'サウルは山の此旁に行ダビデと其從者は山の彼旁に行ダビデは周章てサウルの前を避んとしサウルと其從者はダビデと其從者を圍んで之を取んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, '時に使者サウルに來て言けるはペリシテ人國ををかす急ぎきたりたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, '故にサウル、ダビデを追ことを止てかへり往てペリシテ人にあたるここをもて人々その處をセラマレコテ(逃岩)となづく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'ダビデ其處よりのぼりてエンゲデの要害にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'サウル、ペリシテ人を追ふことをやめて還りし時人々かれにつげていひけるは視よダビデはエンゲデの野にありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'サウル、イスラエルの中より選みたる三千の人を率ゐゆきて野羊の巌にダビデと其從者を尋ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, '途にて羊の棧にいたるに其處に洞穴ありサウル其足を掩んとていりぬ時にダビデと其從者洞の隅に居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'ダビデの從者これにいひけるはヱホバが汝に告て視よ我汝の敵を汝の手にわたし汝をして善と見るところを彼になさしめんといひたまひし日は今なりとダビデすなはち起てひそかにサウルの衣の裾をきれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'ダビデ、サウルの衣の裾をきりしによりて後ち其心みづから責む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'ダビデ其從者にいひけるはヱホバの膏そそぎし者なるわが主にわが此事をなすをヱホバ禁じたまふかれはヱホバの膏そそぎし者なればかれに敵してわが手をのぶるは善らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'ダビデ此ことばをもって其從者を止めサウルに撃ちかかる事を容さずサウルたちて洞を出て其道にゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'ダビデもまた後よりたちて洞をいでサウルのうしろに呼はりて我主王よといふサウル後をかへりみる時ダビデ地にふして拝す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'ダビデ、サウルにいひけるは汝なんぞダビデ汝を害せん事を求むといふ人の言を聽くや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, '視よ今日汝の目ヱホバの汝を洞のうちにて今日わが手にわたしたまひしことを見たり人々我に汝をころさんことを勸めたれども我汝を惜めり我いひけらくわが主はヱホバの膏そそぎし者なればこれに敵してわが手をのぶべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'わが父よ視よわが手にある汝の衣の裾を見よわが汝の衣の裾をきりて汝を殺さざるを見ばわが手には惡も罪過もなきことを汝見て知るべし我汝に罪ををかせしことなし然るに汝わが生命をとらんとねらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'ヱホバ我と汝の間を審きたまはんヱホバわがために汝に報いたまふべし然どわが手は汝に加へざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, '古への諺にいふごとく惡は惡人よりいづされどわが手は汝にくはへざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'イスラエルの王は誰を趕んとて出たるや汝たれを追ふや死たる犬をおひ一の蚤をおふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'ねがはくはヱホバ審判者となりて我と汝のあひだをさばきかつ見てわが訟を理し我を汝の手よりすくひいだしたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'ダビデこれらの言をサウルに語りをへしときサウルいひけるはわが子ダビデよ是は汝の聲なるかとサウル聲をあげて哭きぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'しかしてダビデにいひけるは汝は我よりも正し我は汝に惡をむくゆるに汝は我に善をむくゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, '汝今日いかに汝が我に善くなすかを明かにせりヱホバ我を爾の手にわたしたまひしに爾我をころさざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, '人もし其敵にあはばこれを安らかに去しむべけんや爾が今日我になしたる事のためにヱホバ爾に善をむくいたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, '視よ我爾が必ず王とならんことを知りまたイスラエルの王國の爾の手によりて堅くたたんことをしる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, '今爾ヱホバをさして我にわが後にてわが子孫を斷ずわが名をわが父の家に滅せざらんことを誓へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'ダビデすなはちサウルにちかふ是においてサウルは家にかへりダビデと其從者は要害にのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, '爰にサムエル死にしかばイスラエル人皆あつまりて之をかなしみラマにあるその家にてこれを葬むれりダビデたちてバランの野にくだる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'マオンに一箇の人あり其所有はカルメルにあり其人甚だ大なる者にして三千の羊と一千の山羊をもちしがカルメルにて羊の毛を剪り居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, '其人の名はナバルといひ其妻の名はアビガルといふアビガルは賢く顔美き婦なりされど其夫は剛愎にして其爲すところ惡かりきかれはカレブの人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'ダビデ野にありてナバルが其羊の毛を剪りをるを聞き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'ダビデ十人の少者を遣はすダビデ其少者にいひけるはカルメルにのぼりナバルにいたりわが名をもてかれに安否をとひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'かくのごとくいへ願くは壽ながかれ爾平安なれ爾の家やすらかなれ爾が有ところの物みなやすらかなれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, '我爾が羊毛を剪せをるを聞り爾の牧羊者は我らとともにありしが我らこれを害せざりきまたかれらがカルメルにありしあひだかれらの物何も失たることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, '爾の少者に問へかれら爾につげん願くは少者をして爾のまへに恩をえせしめよ我ら吉日に來る請ふ爾の手にあるところの物を爾の僕らおよび爾の子ダビデにあたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'ダビデの少者いたりダビデの名をもって是らのことばの如くナバルに語りてやめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'ナバル、ダビデの僕にこたへていひけるはダビデは誰なるヱサイの子は誰なる此頃は主人をすてて遁逃るる僕おほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, '我あにわがパンと水およびわが羊毛をきる者のために殺したる肉をとりて何處よりか知れざるところの人々にあたふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'ダビデの少者ふりかへりて其道に就き歸りきたりて此等の言のごとくダビデに告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, '是においてダビデ其從者に爾らおのおの劍を帶よと言ければ各劍をおぶダビデもまた劍をおぶ而して四百人ばかりダビデにしたがひて上り二百人は輜重のところに止れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, '時にひとりの少者ナバルの妻アビガルに告ていひけるは視よダビデ野より使者をおくりて我らの主人を祝したるに主人かれらを詈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'されどかの人々はわれらに甚だ善くなし我らは害をかうむらず亦われら野にありし時かれらとともにをるあひだはなにをも失なはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, '我らが羊をかひて彼らとともにありしあひだ彼らは日夜われらの墻となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'されば爾今しりてなにをなさんかを考ふべし其はわれらの主人および主人の全家に定めて害きたるべければなり主人は邪魔なる者にして語ることをえずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'アビガルいそぎパン二百酒の革嚢二旣に調へたる羊五烘麥五セア乾葡萄百球乾無花果の團塊二百を取て驢馬にのせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, '其少者にいひけるは我先に進め視よ我爾らの後にゆくと然ど其夫ナバルには告げざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'アビガル驢馬にのりて山の僻處にくだれる時視よダビデと其從者かれにむかひてくだりければかれ其人々にあふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'ダビデかつていひけるは誠にわれ徒に此人の野にて有る物をみなまもりてその物をして何もうせざらしめたりかれは惡をもてわが善にむくゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'ねがはくは神ダビデの敵にかくなしまた重ねてかくなしたまへ明晨までに我はナバルに屬する總ての物の中ひとりの男をものこさざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'アビガル、ダビデを視しとき急ぎ驢馬よりおりダビデのまへに地に俯して拝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, '其足もとにふしていひけるはわが主よ此咎を我に歸したまへ但し婢をして爾の耳にいふことを得さしめ婢のことばを聽たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'ねがはくは我主この邪なる人ナバル(愚)の事を意に介むなかれ其はかれは其名の如くなればなりかれの名はナバルにしてかれは愚なりわれなんぢの婢はわが主のつかはせし少ものを見ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'さればわがしゆよヱホバはいくまたなんぢのたましひはいくヱホバなんぢのきたりて血をながしまた爾がみづから仇をむくゆるを阻めたまへりねがはくは爾の敵たるものおよびわが主に害をくはへんとする者はナバルのごとくなれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'さて仕女がわが主にもちきたりしこの禮物をねがはくはわが主の足迹にあゆむ少者にたてまつらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, '請ふ婢の過をゆるしたまへヱホバ必ずわが主のために堅き家を立たまはん是はわが主ヱホバの軍に戰ふにより又世にいでてよりこのかた爾の身に惡きこと見えざるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, '人たちて爾を追ひ爾の生命を求むれどもわが主の生命は爾の神ヱホバとともに生命の包裏の中に包みあり爾の敵の生命は投石器のうちより投すつる如くヱホバこれをなげすてたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'ヱホバその爾につきて語りたまひし諸の善き事をわが主になして爾をイスラエルの主宰に命じたまはん時にいたりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, '爾の故なくして血をながしたることも又わが主のみづから其仇をむくいし事も爾の憂となることなくまたわが主の心の責となることなかるべし但しヱホバのわが主に善くなしたまふ時にいたらばねがはくは婢を憶たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'ダビデ、アビガルにいふ今日汝をつかはして我をむかへしめたまふイスラエルの神ヱホバは頌美べきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'また汝の智慧はほむべきかな又汝はほむべきかな汝今日わがきたりて血をながし自ら仇をむくゆるを止めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'わが汝を害するを阻めたまひしイスラエルの神ヱホバは生く誠にもし汝いそぎて我を來り迎ずば必ず翌朝までにナバルの所にひとりの男ものこらざりしならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'ダビデ、アビガルの携へきたりし物を其手より受てかれにいひけるは安かに汝の家にかへりのぼれ視よわれ汝の言をききいれて汝の顔を立たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'かくてアビガル、ナバルにいたりて視にかれは家に酒宴を設け居たり王の酒宴のごとしナバルの心これがために樂みて甚だしく酔たればアビガル多少をいはず何をも翌朝までかれにつげざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, '朝にいたりナバルの酒のさめたる時妻かれに是等の事をつげたるに彼の心そのうちに死て其身石のごとくなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, '十日ばかりありてヱホバ、ナバルを撃ちたまひければ死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'ダビデ、ナバルの死たるを聞ていひけるはヱホバは頌美べきかなヱホバわが蒙むりたる恥辱の訟を理してナバルにむくい僕を阻めて惡をおこなはざらしめたまふ其はヱホバ、ナバルの惡を其首に歸し賜へばなりと爰にダビデ、アビガルを妻にめとらんとて人を遣はしてこれとかたらはしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'ダビデの僕カルメルにをるアビガルの許にいたりてこれにかたりいひけるはダビデ汝を妻にめとらんとて我らを汝に遣はすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'アビガルたちて地にふして拝しいひけるは視よ婢はわが主の僕等の足を洗ふ仕女なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'アビガルいそぎたちて驢馬に乗り五人の侍女とともにダビデの使者にしたがひゆきてダビデの妻となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'ダビデまたヱズレルのアヒノアムを娶れり彼ら二人ダビデの妻となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, '但しサウルはダビデの妻なりし其女ミカルをガリムの人なるライシの子パルテにあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'ジフ人ギベアにきたりサウルの許にいたりてひけるはダビデは曠野のまへなるハキラの山にかくれをるにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'サウルすなはち起ちジフの野にダビデを尋ねんとイスラエルの中より選みたる三千の人をしたがへてジフの野にくだる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'サウルは曠野のまへなるハキラの山において路のほとりに陣を取るダビデは曠野に居てサウルのおのれをおふて曠野にきたるをさとりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'ダビデ斥候を出してサウルの誠に來しをしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'ここにおいてダビデたちてサウルの陣をとれるところにいたりサウルおよび其軍の長ネルの子アブネルの寝たるところを見たりすなはちサウルは車營の中に寝ぬ民其まはりに陣をはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'ダビデ答へてヘテ人アヒメレクおよびゼルヤの子にしてヨアブの兄弟なるアビシヤイにいひけるは誰か我とともにサウルの陣にくだらんかとアビシヤイいふ我汝とともに下らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'ダビデとアビシヤイすなはち夜にいりて民の所にいたるに視よサウルは車營のうちに寝臥し其槍地にさして枕邊にありアブネルと民は其まはりに寝たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'アビシヤイ、ダビデにいひけるは神今日爾の敵を爾の手にわたしたまふ請ふいま我に槍をもてかれを一度地にさしとほさしめよ再びするにおよばじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'ダビデ、アビシヤイにいふ彼をころすなかれ誰かヱホバの膏そそぎし者に敵して其手をのべて罪なからんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'ダビデまたいひけるはヱホバは生くヱホバかれを撃たまはんあるひはその死ぬる日來らんあるひは戰ひにくだりて死うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'わがヱホバのあぶらそそぎしものに敵して手をのぶることはきはめて善らずヱホバ禁じたまふされどいま請ふ爾そのまくらもとの槍と水の瓶をとれしかして我らさりゆかんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'ダビデ、サウルの枕邊より槍と水の瓶を取りてかれらさりゆきしが誰も見ず誰もしらず誰も目を醒さざりき其はかれら皆眠り居たればなり即ちヱホバかれらをふかく睡らしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'かくてダビデは彼旁にわたりて遥に山の頂にたてり彼と此とのへだたり大なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'ダビデ民とネルの子アブネルによばはりいひけるはアブネルよ爾こたへざるかアブネルこたへていふ王をよぶ爾はたれなるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'ダビデ、アブネルにいひけるは爾は勇士ならずやイスラエルの中にて誰か爾に如ものあらんしかるに爾なんぞ爾の主なる王をまもらざるや民のひとり爾の主なる王を殺さんとていりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, '爾がなせる此事よからずヱホバは生くなんぢらの罪死にあたれり爾らヱホバの膏そそぎし爾らの主をまもらざればなり今王の槍と王の枕邊にありし水の瓶はいづくにあるかを見よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'サウル、ダビデの聲をしりていひけるはわが子ダビデよ是は爾の聲なるかダビデいひけるは王わが主よわが聲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'ダビデまたいひけるはわが主なにゆゑに斯くその僕をおふや我なにをなせしや何の惡き事わが手にあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, '王わが主よ請ふいま僕の言を聽きたまへ若しヱホバ爾を我に敵せしめたまふならばねがはくはヱホバ禮物をうけたまへされど若し人ならばねがはくは其人々ヱホバのまへにのろはれよ其は彼等爾ゆきて他の神につかへよといひて今日我を追ひヱホバの產業に連なることをえざらしむるが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'ねがはくは我血をしてヱホバのまへをはなれて地におちしむるなかれそは人の山にて鷓鴣をおふがごとくイスラエルの王一の蚤をたづねにいでたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'サウルいひけるは我罪ををかせりわが子ダビデよ歸れわが生命今日爾の目に寶と見なされたる故により我々かさねて爾に害を加へざるべし嗚呼われ愚なることをなして甚だしく過てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'ダビデこたへていひけるは王よ槍を視よ請ひとりの少者をしてわたりてこれを取しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'ねがはくはヱホバおのおのに其義と眞實とにしたがひて報いたまへ共はヱホバ今日爾をわが手にわたしたまひしに我ヱホバの受膏者に敵してわが手をのぶることをせざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, '爾の生命を今日わがおもんぜしごとくねがはくはヱホバわが生命をおもんじて諸の艱難のうちより我をすくひいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'サウル、ダビデにいひけるはわが子ダビデよ爾はほむべきかな爾大なる事を爲さん亦かならず勝をえんとしかしてダビデは其道にさりサウルはおのれの所にかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'ダビデ心の中にいひけるは是のごとくば我早晩サウルの手にほろびん速にペリシテ人の地にのがるるにまさることあらず然らばサウルかさねて我をイスラエルの四方の境にたづぬることをやめて我かれの手をのがれんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'ダビデたちておのれとともな六百人のものとともにわたりてガテの王マオクの子アキシにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'ダビデと其從者ガテにてアキシとともに住ておのおの其家族とともにをるダビデはその二人の妻すなはちヱズレル人アヒノアムとカルメル人ナバルの妻なりしアビガルとともにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'ダビデのガテににげしことサウルにきこえければサウルかさねてかれをたづねざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'ここにダビデ、アキシにいひけるは我もし爾のまへに恩を得たるならばねがはくは郷里にある邑のうちにて一のところを我にあたへて其處にすむことを得さしめよ僕なんぞ爾とともに王城にすむべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'アキシ其日チクラグをかれにあたへたり是故にヂクラグは今日にいたるまでユダの王に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'タビデのペリシテ人の國にをりし日數は一年と四箇月なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'ダビデ其從者と共にのぼりゲシユル人ゲゼリ人アマレク人を襲ふたり昔より是等はシユルにいたる地にすみてエジプトの地にまでおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'ダビデ其地をうちて男をも女をも生し存さず羊と牛と駱駝と衣服をとりて還りてアキシに至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'アキシいひけるは爾ら今日何地を襲ひしやダビデいひけるはユダの南とヱラメルの南とケニ人の南ををかせりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'ダビデ男も女も生存らしめずして一人をもガテにひきゆかざりき其はダビデ恐くは彼らダビデかくなせりといひて我儕の事を告んといひたればなりダビデ、ペリシテ人の地にすめるあひだは其なすところ常にかくのごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'アキシ、ダビデを信じていひけるは彼は其民イスラエルをして全くおのれを惡ましむされば永くわが僕となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, '其頃ペリシテ人イスラエルと戰はんとて軍のために軍勢を集めたればアキシ、ダビデにいひけるは爾明かにこれをしれ爾と爾の從者我とともに出て軍にくははるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'ダビデ、アキシにいひけるはされば爾僕のなさんところをしるべしとアキシ、ダビデにさらば我爾を永く我身をまもる者となさんといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'サムエルすでに死たればイスラエルみなこれをかなしみてこれをそのまちラマにはうむれりまたサウルは口寄者と卜筮師を其地よりおひいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'ペリシテ人あつまりきたりてシユネムに陣をとりければサウル、イスラエルを悉くあつめてギルボアに陣をとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'サウル、ペリシテ人の軍を見しときおそれて其心大にふるへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'サウル、ヱホバに問ひけるにヱホバ對たまはず夢に因てもウリムによりても預言者によりてもこたへたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'サウル僕等にいひけるは口寄の婦を求めよわれそのところにゆきてこれに尋ねんと僕等かれにいひけるは視よエンドルに口寄の婦あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'サウル形を變へて他の衣服を著二人の人をともなひてゆき彼等夜の間に其婦の所にいたるサウルいひけるは請ふわがために口寄の術をおこなひてわが爾に言ふ人をわれに呼おこせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, '婦かれにいひけるはなんぢサウルのなしたる事すなはち如何にかれが口寄者と卜筮師を國より斷さりたるを知る爾なんぞ我を死しめんとてわが生命を亡す謀計をなすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'サウル、ヱホバを指てかれに誓ひいひけるはヱホバは生く此事のためになんぢ罪にあふことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, '婦いひけるは誰を我なんぢに呼起すべきかサウルいふサムエルをよびおこせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, '婦サムエルを見て大なる聲にてさけびいだせりしかして婦サウルにいひけるは爾なにゆゑに我を欺きしや爾はすなはちサウルなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, '王かれにいひけるは恐るるなかれ爾なにを見しや婦サウルにいひけるは我神の地よりのぼるを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'サウルかれにいひけるは其形容は如何彼いひけるは一人の老翁のぼる其人明衣を衣たりサウル其人のサムエルなるをしりて地にふして拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'サムエル、サウルにいひけるは爾なんぞ我をよびおこして我をわづらはすやサウルこたへけるは我いたく惱むペリシテ人我にむかひて軍をおこし又神我をはなれて預言者によりても又夢によりてもふたたび我にこたへたまはずこのゆゑに我なすべき事を爾にまなばんとて爾を呼り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'サムエルいひけるはヱホバ爾をはなれて爾の敵となりたまふに爾なんぞ我にとふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'ヱホバわれをもて語りたまひしことをみづから行ひてヱホバ國を爾の手より割きはなち爾の隣人ダビデにあたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, '爾ヱホバの言にしたがはず其烈しき怒をアマレクにもらさざりしによりてヱホバ此事を今日爾になしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'ヱホバ、イスラエルをも爾とともにペリシテ人の手にわたしたまふべし明日爾と爾の子等我とともなるべしまたイスラエルの陣營をもヱホバ、ペリシテ人の手にわたしたまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'サウル直ちに地に伸びたふれサムエルの言のために痛くおそれ又其力を失へり其はかれ其一日一夜物食ざりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'かの婦サウルにいたり其痛く慄くを見てこれにいひけるは視よ仕女爾の言をききわが生命をかけて爾が我にいひし言にしたがへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'されば請ふ爾も仕女の言を聽て我をして一口のパンを爾のまへにそなへしめよしかして爾くらひて途に就く時に力を得よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'されどサウル否みて我は食はじといひしを其僕および婦強ければ其言をききいれて地より立あがり床のうへに坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, '婦の家に肥たる犢ありしかば急ぎて之を殺しまた粉をとり摶て酵いれぬパンを炊き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'サウルのまへと其僕等のまへに持ちきたりければ彼等くらひて立ちあがり其夜のうちにされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, '爰にペリシテ人其軍をことごとくアペクにあつむイスラエルはヱズレルにある泉水の傍に陣をとる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'ペリシテ人の君等あるひは百人或は千人をひきゐて進みダビデと其從者はアキシとともに其後にすすむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'ペリシテ人の諸伯いひけるは是等のヘブル人は何なるやアキシ、ペリシテ人の諸伯にいひけるは此はイスラエルの王サウルの僕ダビデにあらずやかれ此日ごろ此年ごろ我とともにをりしがその逃げおちし日より今日にいたるまで我かれの身に咎あるを見ずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'ペリシテ人の諸伯これを怒る即ちペリシテ人の諸伯彼にいひけるは此人をかへらしめて爾が之をおきし其所にふたたびいたらしめよ彼は我らとともに戰ひにくだるべからず然ば彼戰爭においてわれらの敵とならざるべしかれ其主と和がんとせば何をもてすべきやこの人々の首級をもてすべきにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, '是はかつて人々が舞踏の中にて歌ひあひサウルは千をうちころしダビデは萬をうちころすといひたるダビデにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'アキシ、ダビデをよびてこれにいひけるはヱホバは生くまことになんぢは正し爾の我とともに陣營に出入するはわが目には善と見ゆ其は爾が我に來りし日より今日にいたるまで我爾の身に惡き事あるを見ざればなり然ど諸伯の目には爾よからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'されば今かへりて安かにゆきペリシテ人の諸伯の目に惡く見ゆることをなすなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'ダビデ、アキシにいひけるは我何をなせしやわが爾のまへに出し日より今日までに爾何を僕の身に見たればか我ゆきてわが主なるわうの敵とたたかふことをえざると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'アキシこたへてダビデにいひけるは我爾のわが目には神の使のごとく善きをしるされどペリシテ人の諸伯かれは我らとともに戰ひにのぼるべからずといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'されば爾および爾の主の僕の爾とともにきたれる者明朝夙く起よ爾ら朝はやくおきて夜のあくるに及ばばさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, '是をもてダビデと其從者ペリシテ人の地にかへらんと朝はやく起てされりしかしてペリシテ人はヱズレルにのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'ダビデと其從者第三日にチクラグにいたるにアマレク人すでに南の地とチクラグを侵したりかれらチクラグを撃ち火をもて之を燬き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, '其中に居りし婦女を擄にし老たるをも若きをも一人も殺さずして之をひきて其途におもむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'ダビデと其從者邑にいたりて視に邑は火に燬けその妻と男子女子は擄にせられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'ダビデおよびこれとともにある民聲をあげて哭き終に哭く力もなきにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'ダビデのふたりの妻すなはちヱズレル人アヒノアムとカルメル人ナバルの妻なりしアビガルも虜にせられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, '時にダビデ大に心を苦めたり其は民おのおの其男子女子のために氣をいらだてダビデを石にて撃んといひたればなりされどダビデ其神ヱホバによりておのれをはげませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'ダビデ、アヒメレクの子祭司アビヤタルにいひけるは請ふエポデを我にもちきたれとアビヤタル、エポデをダビデにもちきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'ダビデ、ヱホバに問ていひけるは我此軍の後を追ふべきや我これに追つくことをえんかとヱホバかれにこたへたまはく追ふべし爾かならず追つきてたしかに取もどすことをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'ダビデおよびこれとともなる六百人の者ゆきてベソル川にいたれり後にのこれる者はここにとどまる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, '即ちダビデ四百人をひきゐて追ゆきしが憊れてベソル川をわたることあたはざる者二百人はとどまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, '衆人野にて一人のエジプト人を見これをダビデにひききたりてこれに食物をあたへければ食へりまたこれに水をのませたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'すなはち一段の乾無花果と二球の乾葡萄をこれにあたへたり彼くらひて其氣ふたたび爽かになれりかれは三日三夜物をもくはず水をものまざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'ダビデかれにいひけるは爾は誰の人なる爾はいづくの者なるやかれいひけるは我はエジプトの少者にて一人のアマレク人の僕なり三日まへに我疾にかかりしゆゑにわが主人我をすてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, '我らケレテ人の南とユダの地とカレブの南ををかしまた火をもてチクラグをやけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'ダビデかれにいひけるは爾我を此軍にみちびきくだるやかれいひけるは爾我をころさずまた我をわが主人の手にわたさざるを神をさして我に誓へ我爾を此軍にみちびきくだらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'かれダビデをみちびきくだりしが視よ彼等はペリシテ人の地とユダの地より奪ひたる諸の大なる掠取物のためによろこびて飮食し踊りつつ地にあまねく散ひろがりて居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'ダビデ暮あひより次日の晩にいたるまでかれらを撃しかば駱駝にのりて逃げたる四百人の少者の外は一人ものがれたるもの无りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'ダビデはすべてアマレク人の奪ひたる物を取りもどせり其二人の妻もダビデとりもどせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, '小きも大なるも男子も女子も掠取物もすべてアマレク人の奪さりし物は一も失はずダビデことごとく取かへせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'ダビデまた凡の羊と牛をとれり人々この家畜をそのまへに驅きたり是はダビデの掠取物なりといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'かくてダビデかの憊れてダビデにしたがひ得ずしてベソル川のほとりに止まりし二百人の者のところにいたるに彼らダビデをいでむかへまたダビデとともなる民をいでむかふダビデかの民にちかづきてその安否をたづぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'ダビデとともにゆきし人々の中の惡く邪なる者みなこたへていひけるは彼等は我らとともにゆかざりければ我らこれに取りもどしたる掠取物をわけあたふべからず唯おのおのにその妻子をあたへてこれをみちびきさらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'ダビデ言けるはわが兄弟よヱホバ我らをまもり我らにせめきたりし軍を我らの手にわたしたまひたれば爾らヱホバのわれらにたまひし物をしかするは宜からず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, '誰か爾らにかかることをゆるさんや戰ひにくだりし者の取る分のごとく輜重のかたはらに止まりし者の取る分もまた然あるべし共にひとしく取るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'この日よりのちダビデこれをイスラエルの法となし例となせり其事今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'ダビデ、チクラグにいたりて其掠取物をユダの長老なる其朋友にわかちおくりて曰しめけるは是はヱホバの敵よりとりて爾らにおくる饋物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'ベテルにをるもの南のラモテにをるものヤツテルにをる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'アロエルにをる者シフモテにをるものエシテモにをるもの');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'ラカルにをるものヱラメル人の邑にをるものケニ人の邑にをるもの');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'ホルマにをるものコラシヤンにをるものアタクにをるもの');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'ヘブロンにをるものおよびすべてダビデが其從者とともに毎にゆきし所にこれをわかちおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'ペリシテ人イスラエルと戰ふイスラエルの人々ペリシテ人のまへより逃げ負傷者ギルボア山に斃れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'ペリシテ人サウルと其子等に攻よりペリシテ人サウルの子ヨナタン、アビナダブおよびマルキシユアを殺したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, '戰はげしくサウルにせまりて射手の者サウルを射とめければ彼痛く射手の者のために苦しめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'サウル武器を執る者にいひけるは爾の劍を抜き其をもて我を刺とほせ恐らくは是等の割禮なき者きたりて我を刺し我をはづかしめんと然ども武器をとるもの痛くおそれて肯ぜざればサウル劍をとりて其上に伏したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, '武器を執るものサウルの死たるを見ておのれも劍の上にふしてかれとともに死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'かくサウルと其三人の子およびサウルの武器をとるもの並に其從者みな此日倶に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'イスラエルの人々の谷の對向にをるもの及びヨルダンの對面にをるものイスラエルの人々の逃るを見サウルと其子等の死るをみて諸邑を棄て逃ければペリシテ人きたりて其中にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, '明日ペリシテ人戰沒せる者を剥んとてきたりサウルと其三人の子のギルボア山にたふれをるを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, '彼等すなはちサウルの首を斬り其鎧甲をはぎとりペリシテ人の地の四方につかはして此好報を其偶像の家および民の中につげしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'またかれら其鎧甲をアシタロテの家におき其體をベテシヤンの城垣に釘けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'ヤベシギレアデの人々ペリシテ人のサウルになしたる事を聞きしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, '勇士みなおこり終夜ゆきてサウルの體と其子等の體をベテシヤンの城垣よりとりおろしヤベシにいたりて之を其處に焚き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, '其骨をとりてヤベシの柳樹の下にはうむり七日のあひだ斷食せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'サウルの死し後ダビデ、アマレク人を撃てかへりチクラグに二日とどまりけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, '第三日に及びて一個の人其衣を裂き頭に土をかむりて陣營より即ちサウルの所より來りダビデの許にいたり地にふして拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'ダビデかれにいひけるは汝いづくより來れるやかれダビデにいひけるはイスラエルの陣營より逃れきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'ダビデかれにいひけるは事いかん請ふ我につげよかれこたへけるは民戰に敗れて逃げ民おほく仆れて死りまたサウルと其子ヨナタンも死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'ダビデ其おのれにつぐる少者にいひけるは汝いかにしてサウルと其子ヨナタンの死たるをしるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'ダビデにつぐる少者いひけるは我はからずもギルボア山にのぼり見しにサウル其槍に倚かかりをりて戰車と騎兵かれにせめよらんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, '彼うしろにふりむきて我を見我をよびたれば我こたへて我ここにありといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'かれ我に汝は誰なるやといひければ我かれにこたへて我はアマレク人なりといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'かれまた我にいひけるはわが身いたく攣ば請ふ我うへにのりて我をころせわが生命なほわれの中にまつたければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, '我すなはちかれの上にのりてかれを殺したり其は我かれが旣に仆て生ることをえざるをしりたればなりしかして我その首にありし冕とその腕にありし釧を取りてこれをわが主に携へきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, '是においてダビデおのれの衣を執てこれを裂けりまた彼とともにある者も皆しかせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, '彼等サウルのためまた其子ヨナタンのためまたヱホバの民のためイスラエルの家のために哭きかなしみて晩まで食を斷り其は彼ら劍にたふれたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'ダビデおのれに告し少者にいひけるは汝は何處の者なるやかれこたへけるは我は他國の人すなはちアマレク人なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'ダビデかれにいひけるは汝なんぞ手をのばしてヱホバの膏そそぎし者をころすことを畏ざりしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'ダビデ一人の少者をよびていひけるは近よりてかれをころせとすなはちかれをうちければ死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'ダビデかれにいひけるは汝の血は汝の首に歸せよ其は汝口づから我ヱホバのあぶらそそぎし者をころせりといひて己にむかひて證をたつればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'ダビデ悲歌をもてサウルと其子ヨナタンを吊ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'ダビデ命じてこれをユダの族にをしへしむ即ち弓の歌是なり是はヤシル書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'イスラエルよ汝の榮耀は汝の崇邱に殺さる嗚呼勇士は仆れたるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, '此事をガテに告るなかれアシケロンの邑に傳るなかれ恐くはペリシテ人の女等喜ばん恐くは割禮を受ざる者の女等樂み祝はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'ギルボアの山よ願は汝の上に雨露降ることあらざれ亦供物の田園もあらざれ其は彼處に勇士の干棄らるればなり即ちサウルの干膏を沃がずして彼處に棄らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, '殺せし者の血をのまずしてヨナタンの弓は退かず勇士の脂を食ずしてサウルの劍は空く歸らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'サウルとヨナタンは愛らしく樂げにして生死ともに離れず二人は鷲よりも捷く獅子よりも強かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'イスラエルの女等よサウルのために哀けサウルは絳き衣をもて汝等を華麗に粧ひ金の飾を汝等の衣に着たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, '嗚呼勇士は戰の中に仆たるかなヨナタン汝の崇邱に殺されぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, '兄弟ヨナタンよ我汝のために悲慟む汝は大に我に樂き者なりき汝の我をいつくしめる愛は尋常ならず婦の愛にも勝りたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, '嗚呼勇士は仆たるかな戰の具は失たるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, '此のちダビデ、ヱホバに問ていひけるは我ユダのひとつの邑にのぼるべきやヱホバかれにいひたまひけるはのぼれダビデいひけるは何處にのぼるべきやヱホバいひたまひけるはヘブロンにのぼるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'ダビデすなはち彼處にのぼれりその二人の妻ヱズレル人アヒノアムおよびカルメル人ナバルの妻なりしアビガルもともにのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'ダビデ其おのれとともにありし從者と其家族をことごとく將のぼりければ皆ヘブロンの諸巴にすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, '時にユダの人々きたり彼處にてダビデに膏をそそぎてユダの家の王となせり 人々ダビデにつげてサウルを葬りしはヤベシギレアデの人なりといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'ダビデ使者をヤベシギレアデの人におくりてこれにいひけるは汝らこの厚意を汝らの主サウルにあらはしてかれを葬りたればねがはくは汝らヱホバより福祉をえよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'ねがはくはヱホバ恩寵と眞實を汝等にしめしたまへ汝らこの事をなしたるにより我亦汝らに此恩惠をしめすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'されば汝ら手をつよくして勇ましくなれ汝らの主サウルは死たり又ユダの家我に膏をそそぎて我をかれらの王となしたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, '爰にサウルの軍の長ネルの子アブネル、サウルの子イシボセテを取りてこれをマナイムにみちびきわたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'ギレアデとアシユリ人とヱズレルとエフライムとベニヤミンとイスラエルの衆の王となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'サウルの子イシボセテはイスラエルの王となりし時四十歳にして二年のあひだ位にありしがユダの家はダビデにしたがへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'ダビデのヘブロンにありてユダの家の王たりし日數は七年と六ヶ月なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'ネルの子アブネル及びサウルの子なるイシボセテの臣僕等マハナイムを出てギベオンに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'セルヤの子ヨアブとダビデの臣僕もいでゆけり彼らギベオンの池の傍にて出會一方は池の此畔に一方は池の彼畔に坐す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'アブネル、ヨアブにいひけるはいざ少者をして起て我らのまへに戯れしめんヨアブいひけるは起しめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'サウルの子イシボセテに屬するベニヤミンの人其數十二人及びダビデの臣僕十二人起て前み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'おのおの其敵手の首を執へて劍を其敵手の脅に刺し斯して彼等倶に斃れたり是故に其處はヘルカテハヅリム(利劍の地)と稱らる即ちギベオンにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, '此日戰甚だ烈しくしてアブネルとイスラエルの人々ダビデの臣僕のまへに敗る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, '其處にゼルヤの三人の子ヨアブ、アビシヤイ、アサヘル居たりしがアサヘルは疾足なること野にをる麆のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'アサヘル、アブネルの後を追ひけるが行に右左にまがらずアブネルの後をしたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'アブネル後を顧みていふ汝はアサヘルなるか彼しかりと答ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'アブネルかれにいひけるは汝の右か左に轉向て少者の一人を擒へて其戎服を取れと然どアサヘル、アブネルをおふことを罷て外に向ふを肯ぜず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'アブネルふたたびアサヘルにいふ汝我を追ことをやめて外に向へ我なんぞ汝を地に撃ち仆すべけんや然せば我いかでかわが面を汝の兄ヨアブにむくべけんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, '然どもかれ外にむかふことをいなむによりアブネル槍の後銛をもてかれの腹を刺しければ槍その背後にいでたりかれ其處にたふれて立時に死り斯しかばアサヘルの仆れて死るところに來る者は皆たちどまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'されどヨアブとアビシヤイはアブネルの後を追きたりしがギベオンの野の道傍にギアの前にあるアンマの山にいたれる時日暮ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'ベニヤミンの子孫アブネルにしたがひて集まり一隊となりてひとつの山の頂にたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, '爰にアブネル、ヨアブをよびていひけるは刀劍豈永久にほろぼさんや汝其終りには怨恨を結ぶにいたるをしらざるや汝何時まで民に其兄弟を追ふことをやめてかへることを命ぜざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'ヨアブいひけるは神は活く若し汝が言出さざりしならば民はおのおの其兄弟を追はずして今晨のうちにさりゆきしならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'かくてヨアブ喇叭を吹きければ民皆たちどまりて再イスラエルの後を追はずまたかさねて戰はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'アブネルと其從者終夜アラバを經ゆきてヨルダンを濟りビテロンを通りてマハナイムに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'ヨアブ、アブネルを追ことをやめて歸り民をことごとく集めたるにダビデの臣僕十九人とアサヘル缺てをらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'されどダビデの臣僕はベニヤミンとアブネルの從者三百六十人を撃ち殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, '人々アサヘルを取りあげてベテレヘムにある其父の墓に葬るヨアブと其從者は終夜ゆきて黎明にヘブロンにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'サウルの家とダビデの家の間の戰爭久しかりしがダビデは益強くなりサウルの家はますます弱くなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'ヘブロンにてダビデに男子等生る其首出の子はアムノンといひてヱズレル人アヒノアムより生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, '其次はギレアブといひてカルメル人ナバルの妻なりしアビガルより生る第三はアブサロムといひてゲシユルの王タルマイの女子マアカの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, '第四はアドニヤといひてハギテの子なり第五はシバテヤといひてアビタルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, '第六はイテレヤムといひてダビデの妻エグラの子なり是等の子ヘブロンにてダビデに生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'サウルの家とダビデの家の間に戰爭ありし間アブネルは堅くサウルの家に荷擔り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, '嚮にサウル一人の妾を有り其名をリヅパといふアヤの女なり爰にイシボセテ、アブネルにいひけるは汝何ぞわが父の妾に通じたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'アブネル甚しくイシボセテの言を怒りていひけるは我今日汝の父サウルの家とその兄弟とその朋友に厚意をあらはし汝をダビデの手にわたさざるに汝今日婦人の過を擧て我を責む我あに犬の首ならんやユダにくみする者ならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, '神アブネルに斯なしまたかさねて斯なしたまへヱホバのダビデに誓ひたまひしごとく我かれに然なすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, '即ち國をサウルの家より移しダビデの位をダンよりベエルシバにいたるまでイスラエルとユダの上にたてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'イシボセテ、アブネルを恐れたればかさねて一言も之にこたふるをえざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'アブネルおのれの代に使者をダビデにつかはしていひけるは此地は誰の所有なるや又いひけるは汝我と契約を爲せ我力を汝に添へてイスラエルを悉く汝に歸せしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'ダビデいひけるは善し我汝と契約をなさん但し我一の事を汝に索む即ち汝來りてわが面を覿る時先づサウルの女ミカルを携きたらざれば我面を覿るを得じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'ダビデ使者をサウルの子イシボセテに遣していひけるはわがペリシテ人の陽皮一百を以て聘たるわが妻ミカルを我に交すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'イシボセテ人をつかはしてかれを其夫ライシの子パルテより取しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, '其夫哭つつ歩みて其後にしたがひて倶にバホリムにいたりしがアブネルかれに歸り往けといひければすなはち歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'アブネル、イスラエルの長老等と語りていひけるは汝ら前よりダビデを汝らの王となさんことを求め居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'されば今これをなすべし其はヱホバ、ダビデに付て語りて我わが僕ダビデの手を以てわが民イスラエルをペリシテ人の手よりまたその諸の敵の手より救ひいださんといひたまひたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'アブネル亦ベニヤミンの耳に語れりしかしてアブネル自らイスラエルおよびベニヤミンの全家の善とおもふ所をヘブロンにてダビデの耳に告んとて往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'すなはちアブネル二十人をしたがへてヘブロンにゆきてダビデの許にいたりければダビデ、アブネルと其したがへる從者のために酒宴を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'アブネル、ダビデにいひけるは我起てゆきイスラエルをことごとくわが主王の所に集めて彼等に汝と契約を立しめ汝をして心の望む所の者をことごとく治むるにいたらしめんと是においてダビデ、アブネルを歸してかれ安然に去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, '時にダビデの臣僕およびヨアブ人の國を侵して歸り大なる掠取物を携へきたれり然どアブネルはタビデとともにヘブロンにはをらざりき其はダビデかれを歸してかれ安然に去りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'ヨアブおよびともにありし軍兵皆かへりきたりしとき人々ヨアブに告ていひけるはネルの子アブネル王の所にきたりしが王かれを返してかれ安然にされりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'ヨアブ王に詣りていひけるは汝何を爲したるやアブネル汝の所にきたりしに汝何故にかれを返して去ゆかしめしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, '汝ネルの子アブネルが汝を誑かさんとてきたり汝の出入を知りまた汝のすべて爲す所を知んために來りしを知ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'かくてヨアブ、ダビデの所より出來り使者をつかはしてアブネルを追しめたれば使者シラの井よりかれを將返れりされどダビデは知ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'アブネル、ヘブロンに返りしかばヨアブ彼と密に語らんとてかれを門の内に引きゆき其處にてその腹を刺てこれを殺し己の兄弟アサヘルの血をむくいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, '其後ダビデ聞ていひけるは我と我國はネルの子アブネルの血につきてヱホバのまへに永く罪あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, '其罪はヨアブの首と其父の全家に歸せよねがはくはヨアブの家には白濁を疾ものか癩病人か杖に倚ものか劍に仆るものか食物に乏しき者か絶ゆることあらざれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'ヨアブとその弟アビシヤイのアブネルを殺したるは彼がギベオンにて戰陣のうちにおのれの兄弟アサヘルをころせしによれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'ダビデ、ヨアブおよびおのれとともにある民にいひけるは汝らの衣服を裂き麻の衣を著てアブネルのために哀哭くべしとダビデ王其棺にしたがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, '人衆アブネルをヘブロンに葬れり王聲をあげてアブネルの墓に哭き又民みな哭けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, '王アブネルの爲に悲の歌を作りて云くアブネル如何にして愚なる人の如くに死けん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, '汝の手は縛もあらず汝の足は鏈にも繋れざりしものを嗚呼汝は惡人のために仆る人のごとくにたふれたり斯て民皆再びかれのために哭けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, '民みな日のあるうちにダビデにパンを食はしめんとて來りしにダビデ誓ひていひけるは若し日の沒まへに我パンにても何にても味ひなば神我にかくなし又重ねて斯なしたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, '民皆見て之を其目に善しとせり凡て王の爲すところの事は皆民の目に善と見えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, '其日民すなはちイスラエル皆ネルの子アブネルを殺たるは王の所爲にあらざるを知れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, '王その臣僕にいひけるは今日一人の大將大人イスラエルに斃る汝らこれをしらざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, '我は膏そそがれし王なれども今日尚弱しゼルヤの子等なる此等の人我には制しがたしヱホバ惡をおこな者に其惡に隨ひて報いたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'サウルの子はアブネルのヘブロンにて死たるを聞きしかば其手弱くなりてイスラエルみな憂へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'サウルの子隊長二人を有てり其一人をバアナといひ一人をレカブといふベニヤミンの支派なるベロテ人リンモンの子等なり其はベロテも亦ベニヤミンの中に數らるればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, '昔にペロテ人ギツタイムに逃遁れて今日にいたるまで彼處に旅人となりて止まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'サウルの子ヨナタンに跛足の子一人ありヱズレルよりサウルとヨナタンの事の報いたりし時には五歳なりき其乳媼かれを抱きて逃れたりしが急ぎ逃る時其子堕て跛者となれり其名をメピボセテといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'ベロテ人リンモンの子レカブとバアナゆきて日の熱き頃イシボセテの家にいたるにイシボセテ午睡し居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'かれら麥を取らんといひて家の中にいりきたりかれの腹を刺りしかしてレカブと其兄弟バアナ逃げさりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, '彼等が家にいりしときイシボセテは其寝室にありて床の上に寝たりかれら即ちこれをうちころしこれを馘りて其首級をとり終夜アラバの道をゆきて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'イシボセテの首級をヘブロンにダビデの許に携へいたりて王にいひけるは汝の生命を求めたる汝の敵サウルの子イシボセテの首を視よヱホバ今日我主なる王の仇をサウルと其裔に報いたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'ダビデ、ベロテ人リンモンの子レカブと其兄弟バアナに答へていひけるはわが生命を諸の艱難の中に救ひたまひしヱホバは生く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, '我は嘗て人の我に告て視よサウルは死りと言ひて自ら我に善き事を傳ふる者と思ひをりしを執てこれをチクラグに殺し其消息に報いたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, '况や惡人の義人を其家の床の上に殺したるをやされば我彼の血をながせる罪を汝らに報い汝らをこの地より絶ざるべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'ダビデ少者に命じければ少者かれらを殺して其手足を切離しヘブロンの池の上に懸たり又イシボセテの首を取りてヘブロンにあるアブネルの墓に葬れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, '爰にイスラエルの支派咸くヘブロンにきたりダビデにいたりていひけるは視よ我儕は汝の骨肉なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, '前にサウルが我儕の王たりし時にも汝はイスラエルを率ゐて出入する者なりきしかしてヱホバ汝に汝わが民イスラエルを牧養はん汝イスラエルの君長とならんといひたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, '斯くイスラエルの長老皆ヘブロンにきたり王に詣りければダビデ王ヘブロンにてヱホバのまへにかれらと契約をたてたり彼らすなはちダビデに膏を灑でイスラエルの王となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'ダビデは王となりし時三十歳にして四十年の間位に在き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, '即ちヘブロンにてユダを治むること七年と六箇月またエルサレムにてイスラエルとユダを全く治むること三十三年なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, '茲に王其從者とともにエルサレムに往き其地の居民ヱブス人を攻んとすヱブス人ダビデに語りていひけるは汝此に入ること能はざるべし反て盲者跛者汝を追はらはんと是彼らダビデ此に入るあたはずと思へるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, '然るにダビデ、シオンの要害を取り是即ちダビデの城邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'ダビデ其日いひけるは誰にても水道にいたりてヱブス人を撃ちまたダビデの心の惡める跛者と盲者を撃つ者は(首となし長となさん)と是によりて人々盲者と跛者は家に入るべからずといひなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'ダビデ其要害に住て之をダビデの城邑と名けたりまたダビデ、ミロ(城塞)より内の四方に建築をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'かくてダビデはますます大に成りゆき且萬軍の神ヱホバこれと共にいませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'ツロの王ヒラム使者をダビデに遣はして香柏および木匠と石工をおくれり彼らダビデの爲に家を建つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'ダビデ、ヱホバのかたく己をたててイスラエルの王となしたまへるを暁りまたヱホバの其民イスラエルのために其國を興したまひしを暁れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'ダビデ、ヘブロンより來りし後エルサレムの中よりまた妾と妻を納たれば男子女子またダビデに生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'ヱルサレムにて彼に生れたる者の名はかくのごとしシヤンマ、シヨバブ、ナタン、ソロモン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'イブハル、エリシユア、ネペグ、ヤピア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'エリシヤマ、エリアダ、エリバレテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, '爰に膏を沃いでダビデをイスラエルの王と爲し事ペリシテ人に聞えければペリシテ人皆ダビデを獲んとて上るダビデ聞て要害に下れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'ペリシテ人臻りてレバイムの谷に布き備たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'ダビデ、ヱホバに問ていひけるは我ペリシテ人にむかひて上るべきや汝かれらをわが手に付したまふやヱホバ、ダビデにいひたまひけるは上れ我必らずペリシテ人を汝の手にわたさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'ダビデ、バアルペラジムに至りかれらを其所に撃ていひけるはヱホバ水の破壞り出るごとく我敵をわが前に破壞りたまへりと是故に其所の名をバアルペラジム(破壞の處)と呼ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, '彼處に彼等其偶像を遺たればダビデと其從者これを取あげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'ペリシテ人再び上りてレバイムの谷に布き備へたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'ダビデ、ヱホバに問にヱホバいひたまひけるは上るべからず彼等の後にまはりベカの樹の方より彼等を襲へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, '汝ベカの樹の上に進行の音を聞ばすなけち突出づべし其時にはヱホバ汝のまへにいでてペリシテ人の軍を撃たまふべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'ダビデ、ヱホバのおのれに命じたまひしごとくなしペリシテ人を撃てゲバよりガゼルにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'ダビデ再びイスラエルの選抜の兵士三萬人を悉く集む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'ダビデ起ておのれと共にをる民とともにバアレユダに往て神の櫃を其處より舁上らんとす其櫃はケルビムの上に坐したまふ萬軍のヱホバの名をもて呼る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'すなはち神の櫃を新しき車に載せて山にあるアビナダブの家より舁だせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'アビナダブの子ウザとアヒオ神の櫃を載たる其新しき車を御しアヒオは櫃のまへにゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'ダビデおよびイスラエルの全家琴と瑟と鼗と鈴と鐃鈸をもちて力を極め謡を歌ひてヱホバのまへに躍踴れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, '彼等がナコンの禾場にいたれる時ウザ手を神の櫃に伸してこれを扶へたり其は牛振たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'ヱホバ、ウザにむかひて怒りを發し其誤謬のために彼を其處に撃ちたまひければ彼そこに神の櫃の傍に死ねり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'ヱホバ、ウザを撃ちたまひしによりてダビデ怒り其處をペレヅウザ(ウザ撃)と呼り其名今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, '其日ダビデ、ヱホバを畏れていひけるはヱホバの櫃いかで我所にいたるべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'ダビデ、ヱホバの櫃を己に移してダビデの城邑にいらしむるを好まず之を轉してガテ人オベデエドムの家にいたらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'ヱホバの櫃ガテ人オベデエドムの家に在ること三月なりきヱホバ、オベデエドムと其全家を惠みたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'ヱホバ神の櫃のためにオベデエドムの家と其所有を皆惠みたまふといふ事ダビデ王に聞えけれぼダビデゆきて喜樂をもて神の櫃をオベデエドムの家よりダビデの城邑に舁上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'ヱホバの櫃を舁者六歩行](ゆき)}たる時ダビデ牛と肥たる者を献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'ダビデ力を極めてヱホバの前に踊躍れり時にダビデ布のエポデを著け居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'ダビデおよびイスラエルの全家歓呼と喇叭の聲をもてヱホバの櫃を舁のぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, '神の櫃ダビデの城邑にいりし時サウルの女ミカル窻より窺ひてダビデ王のヱホバのまへに舞躍るを見其心にダビデを蔑視む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, '人々ヱホバの櫃を舁入てこれをダビデが其爲に張たる天幕の中なる其所に置りしかしてダビデ燔祭と酬恩祭をヱホバのまへに献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'ダビデ燔祭と酬恩祭を献ぐることを終し時萬軍のヱホバの名を以て民を祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'また民の中即ちイスラエルの衆庶の中に男にも女にも倶にパン一箇 肉一斤 乾葡萄一塊を分ちあたへたり斯て民皆おのおの其家にかへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, '爰にダビデ其家族を祝せんとて歸りしかばサウルの女ミカル、ダビデをいでむかへていひけるはイスラエルの王今日如何に威光ありしや自ら遊蕩者の其身を露すがごとく今日其臣僕の婢女のまへに其身を露したまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'ダビデ、ミカルにいふ我はヱホバのまへに即ち汝の父よりもまたその全家よりも我を選みて我をヱホバの民イスラエルの首長に命じたまへるヱホバのまへに躍れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, '我は此よりも尚鄙からんまたみづから賤しと思はん汝が語る婢女等とともにありて我は尊榮をえんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, '是故にサウルの女ミカルは死ぬる日まで子あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, '王其家に住にいたり且ヱホバ其四方の敵を壞てかれを安らかならしめたまひし時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, '王預言者ナタンに云けるは視よ我は香柏の家に住む然ども神の櫃は幔幕の中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'ナタン王に云けるはヱホバ汝と共に在せば往て凡て汝の心にあるところを爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, '其夜ヱホバの言ナタンに臨みていはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '往てわが僕ダビデに言へヱホバ斯く言ふ汝わがために我の住むべき家を建んとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, '我はイスラエルの子孫をエジプトより導き出せし時より今日にいたるまで家に住しことなくして但天幕と幕屋の中に歩み居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, '我イスラエルの子孫と共に凡て歩める處にて汝ら何故に我に香柏の家を建ざるやとわが命じてわが民イスラエルを牧養しめしイスラエルの士師の一人に一言も語りしことあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, '然ば汝わが僕ダビデに斯く言ふべし萬軍のヱホバ斯く言ふ我汝を牧場より取り羊に隨ふ所より取りてわが民イスラエルの首長となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, '汝がすべて往くところにて汝と共にあり汝の諸の敵を汝の前より斷さりて地の上の大なる者の名のごとく汝に大なる名を得さしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, '又我わが民イスラエルのために處を定めてかれらを植つけかれらをして自己の處に住て重て動くことなからしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'また惡人昔のごとくまたわが民イスラエルの上に士師を立てたる時よりの如くふたたび之を惱ますことなかるべし我汝の諸の敵をやぶりて汝を安かならしめたり又ヱホバ汝に告ぐヱホバ汝のために家をたてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, '汝の日の滿て汝が汝の父祖等と共に寝らん時に我汝の身より出る汝の種子を汝の後にたてて其國を堅うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, '彼わが名のために家を建ん我永く其國の位を堅うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, '我はかれの父となり彼はわが子となるべし彼もし迷はば我人の杖と人の子の鞭を以て之を懲さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'されど我の恩惠はわが汝のまへより除きしサウルより離れたるごとくに彼よりは離るることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, '汝の家と汝の國は汝のまへに永く保つべし汝の位は永く堅うせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'ナタン凡て是等の言のごとくまたすべてこの異象のごとくダビデに語りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'ダビデ王入りてヱホバの前に坐していひけるは主ヱホバよ我は誰わが家は何なればか爾此まで我を導きたまひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, '主ヱホバよ此はなほ汝の目には小き事なり汝また僕の家の遥か後の事を語りたまへり主ヱホバよ是は人の法なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'ダビデ此上何を汝に言ふを得ん其は主ヱホバ汝僕を知たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, '汝の言のためまた汝の心に隨ひて汝此諸の大なることを爲し僕に之をしらしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, '故に神ヱホバよ爾は大なり其は我らが凡て耳に聞る所に依ば汝の如き者なくまた汝の外に神なければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, '地の何れの國か汝の民イスラエルの如くなる其は神ゆきてかれらを贖ひ己の民となして大なる名を得たまひまた彼らの爲に大なる畏るべき事を爲したまへばなり即ち汝がエジプトより贖ひ取たまひし民の前より國々の人と其諸神を逐拂ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, '汝は汝の民イスラエルをかぎりなく汝の民として汝に定めたまへりヱホバよ汝はかれの神となりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'されば神ヱホバよ汝が僕と其家につきて語りたまひし言を永く堅うして汝のいひしごとく爲たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'ねがはくは永久に汝の名を崇めて萬軍のヱホバはイスラエルの神なりと曰しめたまへねがはくは僕ダビデの家をして汝のまへに堅く立しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, '其は萬軍のヱホバ、イスラエルの神よ汝僕の耳に示して我汝に家をたてんと言たまひたればなり 是故に僕此祈祷を汝に爲す道を心の中に得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, '主ヱホバよ汝は神なり汝の言は眞なり汝この惠を僕に語りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, '願くは僕の家を祝福て汝のまへに永く続くことを得さしめたまへ其は主ヱホバ汝これを語りたまへばなりねがはくは汝の祝福によりて僕の家に永く祝福を蒙らしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, '此後ダビデ、ペリシテ人を撃てこれを服すダビデまたペリシテ人の手よりメテグアンマをとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'ダビデまたモアブを撃ち彼らをして地に伏しめ繩をもてかれらを度れり即ち二條の繩をもて死す者を度り一條の繩をもて生しおく者を量度るモアブ人は貢物を納てダビデの臣僕となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'ダビデまたレホブの子なるゾバの王ハダデゼルがユフラテ河の邊にて其勢を新にせんとて往るを撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'しかしてダビデ彼より騎兵千七百人歩兵二萬人を取りまたダビデ一百の車の馬を存して其餘の車馬は皆其筋を切斷り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'ダマスコのスリア人ゾバの王ハダデゼルを援んとて來りければダビデ、スリア人二萬二千を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'しかしてダビデ、ダマスコのスリアに代官を置きぬスリア人は貢物を納てダビデの臣僕となれりヱホバ、ダビデを凡て其往く所にて助けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'ダビデ、ハダデゼルの臣僕等の持る金の楯を奪ひてこれをエルサレムに携きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'ダビデ王又ハダデゼルの邑ベタとベロタより甚だ多くの銅を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, '時にハマテの王トイ、ダビデがハダデゼルの總の軍を撃破りしを聞て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'トイ其子ヨラムをダビデ王につかはし安否を問ひかつ祝を宣しむ其はハダデゼル嘗てトイと戰を爲したるにダビデ、ハダデゼルとたたかひてこれを撃やぶりたればなりヨラム銀の器と金の器と銅の器を携へ來りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'ダビデ王其攻め伏せたる諸の國民の中より取りて納めたる金銀と共に是等をもヱホバに納めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, '即ちエドムよりモアブよりアンモンの子孫よりペリシテ人よりアマレクよりえたる物およびゾバの王レホブの子ハダデゼルより得たる掠取物とともにこれを納めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'ダビデ鹽谷にてエドム人一萬八千を撃て歸て名譽を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'ダビデ、エドムに代官を置り即ちエドムの全地に徧く代官を置てエドム人は皆ダビデの臣僕となれりヱホバ、ダビデを凡て其往くところにて助け給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'ダビデ、イスラエルの全地を治め其民に公道と正義を行ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'ゼルヤの子ヨアブは軍の長アヒルデの子ヨシヤバテは史官');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'アヒトブの子ザドクとアビヤタルの子アヒメレクは祭司セラヤは書記官');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'ヱホヤダの子ベナヤはケレテ人およびペレテ人の長ダビデの子等は大臣なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, '爰にダビデいひけるはサウルの家の遺存れる者尚あるや我ヨナタンの爲に其人に恩惠をほどこさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'サウルの家の僕なるヂバと名くる者ありければかれをダビデの許に召きたるに王かれにいひけるは汝はヂバなるか彼いふ僕是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, '王いひけるは尚サウルの家の者あるか我其人に神の恩惠をほどこさんとすヂバ王にいひけるはヨナタンの子尚あり跛足なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, '王かれにいひけるは其人は何處にをるやヂバ王にいひけるはロデバルにてアンミエルの子マキルの家にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'ダビデ王人を遣はしてロデバルより即ちアンミエルの子マキルの家よりかれを携來らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'サウルの子ヨナタンの子なるメピボセテ、ダビデの所に來り伏て拝せりダビデ、メピボセテよといひければ答て僕此にありと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'ダビデかれにいひけるは恐るるなかれ我必ず汝の父ヨナタンの爲に恩惠を汝にしめさん我汝の父サウルの地を悉く汝に復すべし又汝は恒に我席において食ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'かれ拝して言けるは僕何なればか汝死たる犬のごとき我を眷顧たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, '王サウルの僕ヂバを呼てこれにいひけるは凡てサウルとその家の物は我皆汝の主人の子にあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, '汝と汝の子等と汝の僕かれのために地を耕へして汝の主人の子に食ふべき食物を取りきたるべし但し汝の主人の子メピボセテは恒に我席において食ふべしとヂバは十五人の子と二十人の僕あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'ヂバ王にいひけるは總て王わが主の僕に命じたまひしごとく僕なすべしとメピボセテは王の子の一人のごとくダビデの席にて食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'メピボセテに一人の若き子あり其名をミカといふヂバの家に住る者は皆メピボセテの僕なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'メピボセテはエルサレムに住みたり其はかれ恒に王の席にて食ひたればなりかれは兩の足ともに跛たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, '此後アンモンの子孫の王死て其子ハヌン之に代りて位に即く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'ダビデ我ナハシの子ハヌンにその父の我に恩惠を示せしごとく恩惠を示さんといひてダビデかれを其父の故によりて慰めんとて其僕を遣せりダビデの僕アンモンの子孫の地にいたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'アンモンの子孫の諸伯其主ハヌンにいひけるはダビデ慰者を汝に遣はしたるによりて彼汝の父を崇むと汝の目に見ゆるやダビデ此城邑を窺ひこれを探りて陷いれんために其僕を汝に遣はせるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, '是においてハヌン、ダビデの僕を執へ其鬚の半を剃り落し其衣服を中より斷て股までにしてこれを歸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, '人々これをダビデに告たればダビデ人を遣はしてかれらを迎へしむ其人々大に恥たればなり即ち王いふ汝ら鬚の長るまでヱリコに止まりて然るのち歸るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'アンモンの子孫自己のダビデに惡まるるを見しかばアンモンの子孫人を遣はしてベテレホブのスリア人とゾバのスリア人の歩兵二萬人およびマアカの王より一千人トブの人より一萬二千人を雇いれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'ダビデ聞てヨアブと勇士の惣軍を遣はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'アンモンの子孫出て門の入口に軍の陣列をなしたりゾバとレホブのスリア人およびトブの人とマアカの人は別に野に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'ヨアブ戰の前後より己に向ふを見てイスラエルの選抜の兵の中を選みてこれをスリア人に對ひて備へしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, '其餘の民をば其兄弟アビシヤイの手に交してアンモンの子孫に向て備へしめて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'いひけるは若スリア人我に手強からば汝我を助けよ若アンモンの子孫汝に手剛からば我ゆきて汝をたすけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, '汝勇ましくなれよ我ら民のためとわれらの神の諸邑のために勇しく爲んねがはくはヱホバ其目によしと見ゆるところをなしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'ヨアブ己と共に在る民と共にスリア人にむかひて戰んとて近づきければスリア人彼のまへより逃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'アンモンの子孫スリア人の逃たるを見て亦自己等もアビシヤイのまへより逃て城邑にいりぬヨアブすなはちアンモンの子孫の所より還りてエルサレムにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'スリア人其イスラエルのまへに敗れたるを見て倶にあつまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'ハダデゼル人をやりて河の前岸にをるスリア人を將ゐ出して皆ヘラムにきたらしむハダデゼルの軍の長シヨバクかれらを率ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, '其事ダビデに聞えければ彼イスラエルを悉く集めてヨルダンを渉りてヘラムに來れりスリア人ダビデに向ひて備へ之と戰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'スリア人イスラエルのまへより逃ければダビデ、スリアの兵車の人七百騎兵四萬を殺し又其軍の長シヨバクを撃てこれを其所に死しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'ハダデゼルの臣なる王等其イスラエルのまへに壞れたるを見てイスラエルと平和をなして之に事へたり斯スリア人は恐れて再びアンモンの子孫を助くることをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, '年歸りて王等の戰に出る時におよびてダビデ、ヨアブおよび自己の臣僕並にイスラエルの全軍を遣はせり彼等アンモンの子孫を滅ぼしてラバを圍めりされどダビデはエルサレムに止りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, '爰に夕暮にダビデ其床より興きいでて王の家の屋蓋のうへに歩みしが屋蓋より一人の婦人の體をあらふを見たり其婦は觀るに甚だ美し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'ダビデ人を遣して婦人を探らしめしに或人いふ此はエリアムの女ハテシバにてヘテ人ウリヤの妻なるにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'ダビデ乃ち使者を遣はして其婦を取る婦彼に來りて彼婦と寝たりしかして婦其不潔を清めて家に歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'かくて婦孕みければ人をつかはしてダビデに告ていひけるは我子を孕めりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, '是においてダビデ人をヨアブにつかはしてヘテ人ウリヤを我に遣はせといひければヨアブ、ウリヤをダビデに遣はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'ウリヤ、ダビデにいたりしかばダビデこれにヨアブの如何なると民の如何なると戰爭の如何なるを問ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'しかしてダビデ、ウリヤにいひけるは汝の家に下りて足を洗へとウリヤ王の家を出るに王の贈物其後に從ひてきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, '然どウリヤは王の家の門に其主の僕等とともに寝ておのれの家にくだりいたらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, '人々ダビデに告てウリヤ其家にくだり至らずといひければダビデ、ウリヤにいひけるは汝は旅路をなして來れるにあらずや何故に自己の家にくだらざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'ウリヤ、ダビデにいひけるは櫃とイスラエルとユダは小屋の中に住まりわが主ヨアブとわが主の僕は野の表に陣を取るに我いかでわが家にゆきて食ひ飮しまた妻と寝べけけんや汝は生また汝の霊魂は活く我此事をなさじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'ダビデ、ウリヤにいふ今日も此にとどまれ明日我汝を去しめんとウリヤ其日と次の日エルサレムにとどまりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'ダビデかれを召て其まへに食ひ飮せしめダビデかれを酔しめたり晩にいたりて彼出て其床に其主の僕と共に寝たりされどおのれの家にはくだりゆかざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, '朝におよびてダビデ、ヨアブヘの書を認めて之をウリヤの手によりて遣れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'ダビデ其書に書ていはく汝らウリヤを烈しき戰の先鉾にいだしてかれの後より退きて彼をして戰死せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, '是においてヨアブ城邑を窺ひてウリヤをば其勇士の居ると知る所に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, '城邑の人出てヨアブと戰ひしかばダビデの僕の中の數人仆れヘテ人ウリヤも死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'ヨアブ人をつかはして軍の事を悉くダビデに告げしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'ヨアブ其使者に命じていひけるは汝が軍の事を皆王に語り終しとき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, '王もし怒りを發して汝に汝らなんぞ戰はんとて城邑に近づきしや汝らは彼らが石墻の上より射ることを知らざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'ヱルベセテの子アビメレクを撃し者は誰なるや一人の婦が石垣の上より磨の上石を投て彼をテベツに殺せしにあらずや何ぞ汝ら城垣に近づきしやと言はば汝言べし汝の僕ヘテ人ウリヤもまた死りと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, '使者ゆきてダビデにいたりヨアブが遣はしたるところのことをことごとく告げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, '使者ダビデにいひけるは敵我儕に手強かりしが城外にいでて我儕にいたりしかば我儕これに迫りて門の入口にまでいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, '時に射手の者城垣の上より汝の僕を射たりければ王の僕の或者死に亦汝の僕ヘテ人ウリヤも死りと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'ダビデ使者にいひけるは斯汝ヨアブに言べし此事を憂ふるなかれ刀劍は此をも彼をも同じく殺すなり強く城邑を攻て戰ひ之を陷いるべしと汝かくヨアブを勵ますべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'ウリヤの妻其夫ウリヤの死たるを聞て夫のために悲哀り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, '其喪の過し時ダビデ人を遣はしてかれをおのれの家に召いる彼すなはちその妻となりて男子を生り但しダビデの爲たる此事はヱホバの目に惡かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'ヱホバ、ナタンをダビデに遣はしたまへば彼ダビデに至りてこれにいひけるは一の邑に二箇の人あり一は富て一は貧し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, '其富者は甚だ多くの羊と牛を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'されど貧者は唯自己の買て育てたる一の小き牝羔の外は何をも有ざりき其牝羔彼およびかれの子女とともに生長ちかれの食物を食ひかれの椀に飮みまた彼の懐に寝て彼には女子のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, '時に一人の旅人其富る人の許に來りけるが彼おのれの羊と牛の中を取りてそのおのれに來れる旅人のために烹を惜みてかの貧き人の牝羔を取りて之をおのれに來れる人のために烹たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'ダビデ其人の事を大に怒りてナタンにいひけるはヱホバは生く誠に此をなしたる人は死べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, '且彼此事をなしたるに因りまた憐憫まざりしによりて其牝羔を四倍になして償ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'ナタン、ダビデにいひけるは汝は其人なりイスラエルの神ヱホバ斯いひたまふ我汝に膏を沃いでイスラエルの王となし我汝をサウルの手より救ひいだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, '汝に汝の主人の家をあたへ汝の主人の諸妻を汝の懐に與へまたイスラエルとユダの家を汝に與へたり若し少からば我汝に種々の物を増くはへしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, '何ぞ汝ヱホバの言を藐視じて其目のまへに惡をなせしや汝刃劍をもてヘテ人ウリヤを殺し其妻をとりて汝の妻となせり即ちアンモンの子孫の劍をもて彼を斬殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, '汝我を軽んじてヘテ人ウリヤの妻をとり汝の妻となしたるに因て劍何時までも汝の家を離るることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'ヱホバ斯いひたまふ視よ我汝の家の中より汝の上に禍を起すべし我汝の諸妻を汝の目のまへに取て汝の隣人に與へん其人此日のまへにて汝の諸妻とともに寝ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, '其は汝は密に事をなしたれど我はイスラエルの衆のまへと日のまへに此事をなすべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'ダビデ、ナタンにいふ我ヱホバに罪を犯したりナタン、ダビデにいひけるはヱホバまた汝の罪を除きたまへり汝死ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'されど汝此所行によりてヱホバの敵に大なる罵る機會を與へたれば汝に生れし其子必ず死べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'かくてナタン其家にかへれり 爰にヱホバ、ウリヤの妻がダビデに生る子を撃たまひければ痛く疾めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'ダビデ其子のために神に乞求む即ちダビデ斷食して入り終夜地に臥したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'ダビデの家の年寄等彼の傍に立ちてかれを地より起しめんとせしかども彼肯ぜず又かれらとともに食を爲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, '第七日に其子死りダビデの僕其子の死たることをダビデに告ることを恐れたりかれらいひけるは子の尚生る間に我儕彼に語たりしに彼我儕の言を聽いれざりき如何ぞ彼に其子の死たるを告ぐべけんや彼害を爲んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, '然にダビデ其僕の私語くを見てダビデ其子の死たるを暁れりダビデ乃ち其僕に子は死たるやといひければかれら死りといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, '是においてダビデ地よりおきあがり身を洗ひ膏をぬり其衣服を更てヱホバの家にいりて拝し自己の家に至り求めておのれのために食を備へしめて食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, '僕等彼にいひけるは此の汝がなせる所は何事なるや汝子の生るあひだはこれがために斷食して哭きながら子の死る時に汝は起て食を爲すと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'ダビデいひけるは嬰孩の尚生るあひだにわが斷食して哭きたるは我誰かヱホバの我を憐れみて此子を生しめたまふを知んと思ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'されど今死たれば我なんぞ斷食すべけんや我再びかれをかへらしむるを得んや我かれの所に往べけれど彼は我の所にかへらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'ダビデ其妻バテシバを慰めかれの所にいりてかれとともに寝たりければ彼男子を生りダビデ其名をソロモンと呼ぶヱホバこれを愛したまひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, '預言者ナタンを遣はし其名をヱホバの故によりてヱデデア(ヱホバの愛する者)と名けしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, '爰にヨアブ、アンモンの子孫のラバを攻めて王城を取れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'ヨアブ使者をダビデにつかはしていひけるは我ラバを攻て水城を取れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'されば汝今餘の民を集め斯城に向て陣どりて之を取れ恐らくは我此城を取て人我名をもて之を呼にいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, '是においてダビデ民を悉くあつめてラバにゆき攻て之を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'しかしてダビデ、アンモン王の冕を其首より取はなしたり其金の重は一タラントなりまた寶石を嵌たりこれをダビデの首に置ダビデ其邑の掠取物を甚だ多く持出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'かくてダビデ其中の民を將いだしてこれを鋸と鐵の千歯と鐵の斧にて斬りまた瓦陶の中を通行しめたり彼斯のごとくアンモンの子孫の凡ての城邑になせりしかしてタビデと民は皆エルサレムに還りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, '此後ダビデの子アブサロムにタマルと名くる美しき妹ありしがダビデの子アムノンこれを戀ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'アムノン心を苦しめて遂に其姉妹タマルのためにわづらへり其はタマルは處女なりければアムノンかれに何事をも爲しがたしと思ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, '然るにアムノンに一人の朋友ありダビデの兄弟シメアの子にして其名をヨナダブといふヨナダブに甚だ有智き人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, '彼アムノンにいひけるは汝王の子なんぞ日に日に斯く痩ゆくや汝我に告ざるやアムノン彼にいひけるは我わが兄弟アブサロムの妹タマルを戀ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'ヨナダブかれにいひけるは床に臥て病と佯り汝の父の來りて汝を見る時これにいへ請ふわが妹タマルをして來りて我に食を予へしめわが見て彼の手より食ふことをうる樣にわが目のまへにて食物を調理しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'アムノンすなはち臥して病と佯りしが王の來りておのれを見る時アムノン王にいひけるは請ふ吾妹タマルをして來りてわが目のまへにて二の菓子を作へしめて我にかれの手より食ふことを得さしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, '是においてダビデ、タマルの家にいひつかはしけるは汝の兄アムノンの家にゆきてかれのために食物を調理よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'タマル其兄アムノンの家にいたるにアムノンは臥し居たりタマル乃ち粉をとりて之を摶てかれの目のまへにて菓子を作へ其菓子を燒き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, '鍋を取て彼のまへに傾出たりしかれども彼食ふことを否めりしかしてアムノンいひけるは汝ら皆我を離れていでよと皆かれをはなれていでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'アムノン、タマルにいひけるは食物を寝室に持きたれ我汝の手より食はんとタマル乃ち己の作りたる菓子を取りて寝室に持ゆきて其兄アムノンにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'タマル彼に食しめんとて近く持いたれる時彼タマルを執へて之にいひけるは妹よ來りて我と寝よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'タマルかれにいひける否兄上よ我を辱しむるなかれ是のごとき事はイスラエルに行はれず汝此愚なる事をなすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, '我は何處にわが恥辱を棄んか汝はイスラエルの愚人の一人となるべしされば請ふ王に語れ彼我を汝に予ざることなかるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, '然どもアムノン其言を聽ずしてタマルよりも力ありければタマルを辱しめてこれと偕に寝たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, '遂にアムノン甚だ深くタマルを惡むにいたる其かれを惡む所の惡みはかれを戀ひたるところの戀よりも大なり即ちアムノンかれにいひけるは起て往けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'かれアムノンにいひけるは我を返して此惡を作るなかれ是は汝がさきに我になしたる所の惡よりも大なりとしかれども聽いれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, '其側に仕ふる少者を呼ていひけるは汝此女をわが許より遣りいだして其後に戸を楗せと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'タマル振袖を着ゐたり王の女等の處女なるものは斯のごとき衣服をもて粧ひたりアムノンの侍者かれを外にいだして其後に戸を楗せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'タマル灰を其首に蒙り着たる振袖を裂き手を首にのせて呼はりつつ去ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, '其兄アブサロムかれにいひけるは汝の兄アムノン汝と偕に在しや然ど妹よ默せよ彼は汝の兄なり此事を心に留るなかれとかくてタマルは其兄アブサロムの家に凄しく住み居れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'ダビデ王是等の事を悉く聞て甚だ怒れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'アブサロムはアムノンにむかひて善も惡きも語ざりき其はアブサロム、アムノンを惡みたればたり是はかれがおのれの妹タマルを辱しめたるに由り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, '全二年の後アブサロム、エフライムの邊なるバアルハゾルにて羊の毛を剪しめ居て王の諸子を悉く招けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'アブサロム王の所にいりていひけるは視よ僕羊の毛を剪しめをるねがはくは王と王の僕等僕とともに來りたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, '王アブサロムに云けるは否わが子よ我儕を皆いたらしむるなかれおそらくは汝の費を多くせんアブサロム、ダビデを強ふしかれどもダビデ往ことを肯ぜずして彼を祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'アブサロムいひけるは若しからずば請ふわが兄アムノンをして我らとともに來らしめよ王かれにいひけるは彼なんぞ汝とともにゆくべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'されどアブサロムかれを強ければアムノンと王の諸子を皆アブサロムとともにゆかしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, '爰にアブサロム其少者等に命じていひけるは請ふ汝らアムノンの心の酒によりて樂む時を視すましてわが汝等にアムノンを撃てと言ふ時に彼を殺せ懼るるなかれ汝等に之を命じたるは我にあらずや汝ら勇しく武くなれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'アブサロムの少者等アブサロムの命ぜしごとくアムノンになしければ王の諸子皆起て各其騾馬に乗て逃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, '彼等が路にある時風聞ダビデにいたりていはくアブサロム王の諸子を悉く殺して一人も遺るものなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, '王乃ち起ち其衣を裂きて地に臥す其臣僕皆衣を裂て其傍にたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'ダビデの兄弟シメアの子ヨナダブ答へていひけるは吾主よ王の御子等なる少年を皆殺したりと思たまふなかれアムノン獨り死るのみ彼がアブサロムの妹タマルを辱かしめたる日よりアブサロム此事をさだめおきたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'されば吾主王よ王の御子等皆死りといひて此事をおもひ煩ひたまふなかれアムノン獨死たるなればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, '斯てアブサロムは逃れたり爰に守望ゐたる少者目をあげて視たるに視よ山の傍よりして己の後の道より多くの人來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'ヨナダブ王にいひけるは視よ王の御子等來る僕のいへるがごとくしかりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, '彼語ることを終し時視よ王の子等來り聲をあげて哭り王と其僕等も皆大に甚く哭り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, '偖アブサロムは逃てゲシユルの王アミホデの子タルマイにいたるダビデは日々其子のために悲めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'アブサロム逃てゲシユルにゆき三年彼處に居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'ダビデ王アブサロムに逢んと思ひ煩らふ其はアムノンは死たるによりてダビデかれの事はあきらめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'ゼルヤの子ヨアブ王の心のアブサロムに趣くを知れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'ヨアブ乃ちテコアに人を遣りて彼處より一人の哲婦を呼きたらしめて其婦にいひけるは請ふ汝喪にある眞似して喪の服を着油む身にぬらず死者のために久しく哀しめる婦のごとく爲りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, '王の所にいたり是のごとくかれに語るべしとヨアブ其語言をかれの口に授けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'テコアの婦王にいたり地に伏て拝し王にいひけるは王よ助けたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, '王婦にひけるは何事なるや婦いひけるは我は實に嫠婦にしてわが夫は死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, '仕女に二人の子あり倶に野に爭ひしが誰もかれらを排解ものなきにより此遂に彼を撃て殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, '是において視よ全家仕女に逼りていふ其兄弟を撃殺したる者を付せ我らかれをその殺したる兄弟の生命のために殺さんと斯く嗣子をも滅ぼし存れるわが炭火を熄てわが夫の名をも遺存をも地の面に無らしめんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, '王婦にいひけるは汝の家に往け我汝の事につきて命令を下さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'テコアの婦王にいひけるは王わが主よねがはくは其罪は我とわが父の家に歸して王と王の位には罪あらざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, '王いひけるは誰にても爾に語る者をば我に將來れしかせば彼かさねて爾に觸ること无るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, '婦いひけるは願くは王爾の神ヱホバを憶えてかの仇を報ゆる者をして重て滅すことを爲しめず我子を斷ことなからしめたまへと王いひけるはヱホバは生く爾の子の髮毛一すぢも地に隕ることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, '婦いひけるは請ふ仕女をして一言わが主王に言しめたまヘダビデいひけるは言ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, '婦いひけるは爾なんぞ斯る事を神の民にむかひて思ひたるや王此言を言ふにより王は罪ある者のごとし其は王その放れたる者を歸らしめざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, '抑我儕は死ざるべからず我儕は地に潟れたる水の再び聚る能はざるがごとし神は生命を取りたまはず方法を設けて其放れたる者をして己の所より放たれをることなからしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, '我此事を王我主に言んとて來れるは民我を恐れしめたればなり故に仕女謂らく王に言ん王婢の言を行ひたまふならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, '其は王聞て我とわが子を共に滅して神の產業に離れしめんとする人の手より婢を救ひいだしたまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, '仕女また思り王わが主の言は慰となるべしと其は神の使のごとく王わが主は善も惡も聽たまへばなりねがはくは爾の神ヱホバ爾と共に在せと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, '王こたへて婦にいひけるは請ふわが爾に問んところの事を我に隱すなかれ婦いふ請ふ王わが主言たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, '王いひけるは比すべての事においてはヨアブの手爾とともにあるや婦答へていひけるは爾の霊魂は活く王わが主よ凡て王わが主の言たまひしところは右にも左にもまがらず皆に爾の僕ヨアブ我に命じ是等の言を悉く仕女の口に授けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, '其事の見ゆるとこるを變んとて爾の僕ヨアブ此事をなしたるなり然どわが主は神の使の智慧のごとく智慧ありて地にある事を悉く知たまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, '是において王ヨアブにいひけるは視よ我此事を爲すされば往て少年アブサロムを携歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'ヨアブ地に伏し拝し王を祝せりしかしてヨアブいひけるは王わが主よ王僕の言を行ひたまへば今日僕わが爾に惠るるを知ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'ヨアブ乃ち起てゲシユルに往きアブサロムをエルサレムに携きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, '王いひけるは彼は其家に退くべしわが面を見るべからずと故にアブサロム己の家に退きて王の面を觀ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, '偖イスラエルの中にアブサロムのごとく其美貌のために讃られたる人はなかりき其足の跖より頭の頂にいたるまで彼には瑕疵あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'アブサロム其頭を剪る時其頭の髮を衡るに王の權衡の二百シケルあり毎年の終にアブサロム其頭を剪り是は己の重によりて剪たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'アブサロムに三人の男子と一人のタマルといふ女子生れたりタマルは美女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'アブサロム二年のあひだエルサレムにをりたれども王の顔を見ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, '是によりてアブサロム王に遣さんとてヨアブを呼に遣はしけるが彼來ることを肯ぜず再び遣せしかども來ることを肯ぜざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'アブサロム其僕にいひけるは視よヨアブの田地は我の近くにありて其處に大麥あり往て其に火を放てとアブサロムの僕等田地に火を放てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'ヨアブ起てアブサロムの家に來りてこれにいひけるは何故に爾の僕等田地に火を放たるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'アブサロム、ヨアブにいひけるは我人を爾に遣はして此に來れ我爾を王につかはさんと言り即ち爾をして王に我何のためにゲシユルよりきたりしや彼處に尚あらば我ためには反て善しと言しめんとせり然ば我今王の面を見ん若し我に罪あらば王我を殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'ヨアブ王にいたりてこれに告たれば王アブサロムを召す彼王にいたりて王のまへに地に伏て拝せり王アブサロムに接吻す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, '此後アブサロム己のために戰車と馬ならびに己のまへに驅る者五十人を備たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'アブサロム夙く興きて門の途の傍にたち人の訴訟ありて王に裁判を求めんとて來る時はアブサロム其人を呼ていふ爾は何の邑の者なるやと其人僕はイスラエルの某の支派の者なりといへば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'アブサロム其人にいふ見よ爾の事は善くまた正し然ど爾に聽くべき人は王いまだ立ずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'アブサロム又嗚呼我を此地の士師となす者もがな然れば凡て訴訟と公事ある者は我に來りて我之に公義を爲しあたへんといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'また人彼を拝せんとて近づく時は彼手をのばして其人を扶け之に接吻す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'アブサロム凡て王に裁判を求めんとて來るイスラエル人に是のごとくなせり斯アブサロムはイスラエルの人々の心を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, '斯て四年の後アブサロム王にいひけるは請ふ我をして往てヘブロンにてヱホバに我嘗て立し願を果さしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, '其は僕スリアのゲシユルに居し時願を立て若しヱホバ誠に我をエルサレムに携歸りたまはば我ヱホバに事へんと言たればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, '王かれにいひけるは安然に往けと彼すなはち起てヘブロンに往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'しかしてアブサロム窺ふ者をイスラエルの支派の中に徧く遣はして言せけるは爾等喇叭の音を聞ばアブサロム、ヘブロンにて王となれりと思ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, '二百人の招かれたる者エルサレムよりアブサロムとともにゆけり彼らは何心なくゆきて何事をもしらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'アブサロム犠牲をささぐる時にダビデの議官ギロ人アヒトペルを其邑ギロより呼よせたり徒黨強くして民次第にアブサロムに加はりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, '爰に使者ダビデに來りてイスラエルの人の心アブサロムにしたがふといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'ダビデおのれと共にエルサレムに居る凡ての僕にいひけるは起てよ我ら逃ん然らずば我らアブサロムより遁るるあたはざるべし急ぎ往け恐らくは彼急ぎて我らに追ひつき我儕に害を蒙らせ刃をもて邑を撃ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, '王の僕等王にいひけるは視よ僕等王わが主の選むところを凡て爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, '王いでゆき其全家これにしたがふ王十人の妾なる婦を遺して家をまもらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, '王いでゆき民みな之にしたがふ彼等遠の家に息めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'かれの僕等みな其傍に進みケレテ人とペレテ人および彼にしたがひてガテよりきたれる六百人のガテ人みな王のまへに進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, '時に王がガテ人イツタイにいひけるは何ゆゑに爾もまた我らとともにゆくや爾かへりて王とともにをれ爾は外國人にして移住て處をもとむる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, '爾は昨日來れり我は今日わが得るところに往くなれば豈爾をして我らとともにさまよはしむべけんや爾歸り爾の兄弟をも携歸るべしねがはくは恩と眞實爾とともにあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'イツタイ王に答へていひけるはヱホバは活く王わが主は活く誠に王わが主いかなる處に坐すとも生死ともに僕もまた其處に居るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'ダビデ、イツタイにいひけるは進みゆけガテ人イツタイ乃ち進みかれのすべての從者およびかれとともにある妻子皆進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, '國中皆大聲をあげて哭き民皆進む王もまたキデロン川を渡りて進み民皆進みて野の道におもむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, '視よザドクおよび倶にあるレビ人もまた皆神の契約の櫃を舁ていたり神の櫃をおろして民の悉く邑よりいづるをまてりアビヤタルもまたのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'ここに王ザドクにいひけるは神の櫃を邑に舁もどせ若し我ヱホバのまへに恩をうるならばヱホバ我を携かへりて我にこれを見し其往處を見したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'されどヱホバもし汝を悦ばずと斯いひたまはば視よ我は此にあり其目に善と見ゆるところを我になしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, '王また祭司ザドクにいひけるは汝先見者汝らの二人の子即ち汝の子アヒマアズとアビヤタルの子ヨナタンを伴ひて安然に城邑に歸れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, '見よ我は汝より言のきたりて我に告るまで野の渡場に留まらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'ザドクとアビヤタルすなはち神の櫃をエルサレムに舁もどりて彼處に止まれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'ここにダビデ橄欖山の路を陟りしが陟るときに哭き其首を蒙みて跣足にて行りかれと倶にある民皆各其首を蒙みてのぼり哭つつのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, '時にアヒトペルがアブサロムに與せる者の中にあることダビデに聞えければダビデいふヱホバねがはくはアヒトペルの計策を愚ならしめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'ダビデ嶺にある神を拝する處に至れる時視よアルキ人ホシヤイ衣を裂き土を頭にかむりてきたりてダビデを迎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'ダビデかれにいひけるは爾若し我とともに進まば我の負となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'されど汝もし城邑にかへりてアブサロムにむかひ王よ我爾の僕となるべし此まで爾の父の僕たりしごとく今また汝の僕となるべしといはば爾はわがためにアヒトペルの計策を敗るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, '祭司ザドクとアビヤタル爾とともに彼處にあるにあらずや是故に爾が王の家より聞たる事はことごとく祭司ザドクとアビヤタルに告べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, '視よかれらとともに彼處にはその二人の子即ちザドクの子アヒマアズとアビヤタルの子ヨナタンをるなり爾ら其聞たる事をことごとく彼等の手によりて我に通ずべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'ダビデの友ホシヤイすなはち城邑にいたりぬ時にアブサロムはエルサレムに入居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'ダビデ少しく嶺を過ゆける時視よメピボセテの僕ヂバ鞍おける二頭の驢馬を引き其上にパン二百乾葡萄一百球乾棗の團塊一百酒一嚢を載きたりてダビデを迎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, '王ヂバにいひけるは此等は何なるかヂバいひけるは驢馬は王の家族の乗るためパンと乾棗は少者の食ふため洒は野に困憊たる者の飮むためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, '王いひけるは爾の主人の子は何處にあるやヂバ王にいひけるはかれはエルサレムに止まる其は彼イスラエルの家今日我父の國を我にかへさんと言をればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, '王ヂバにいひけるは視よメピボセテの所有は悉く爾の所有となるべしヂバいひけるは我拝す王わが主よ我をして爾のまへに恩を蒙むらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, '斯てダビデ王バホリムにいたるに視よ彼處よりサウルの家の族の者一人出きたる其名をシメイといふゲラの子なり彼出きたりて來りつつ詛へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, '又彼ダビデとダビデ王の諸の臣僕にむかひて石を投たり時に民と勇士皆王の左右にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'シメイ詛の中に斯いへり汝血を流す人よ爾邪なる人よ出され出され');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, '爾が代りて位に登りしサウルの家の血を凡てヱホバ爾に歸したまへりヱホバ國を爾の子アブサロムの手に付したまへり視よ爾は血を流す人なるによりて禍患の中にあるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'ゼルヤの子アビシヤイ王にいひけるは此死たる犬なんぞ王わが主を詛ふべけんや請ふ我をして渉りゆきてかれの首を取しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, '王いひけるはゼルヤの子等よ爾らの與るところにあらず彼の詛ふはヱホバ彼にダビデを詛へと言たまひたるによるなれば誰か爾なんぞ然するやと言べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'ダビデ又アビシヤイおよび己の諸の臣僕にいひけるは視よわが身より出たるわが子わが生命を求む况や此ベニヤミン人をや彼を聽して詛はしめよヱホバ彼に命じたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'ヱホバわが艱難を俯視みたまふことあらん又ヱホバ今日彼の詛のために我に善を報いたまふことあらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, '斯てダビデと其從者途を行けるにシメイはダビデに對へる山の傍に行て行つつ詛ひまた彼にむかひて石を投げ塵を揚たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, '王および倶にある民皆アエピムに來りて彼處に息をつげり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, '偖アブサロムと總ての民イスラエルの人々エルサレムに至れりアヒトペルもアブサロムとともにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'ダビデの友なるアルキ人ホシヤイ、アブサロムの許に來りし時アブサロムにいふ願くは王壽かれ願くは王壽かれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'アブサロム、ホシヤイにいひけるは此は爾が其友に示す厚意なるや爾なんぞ爾の友と往ざるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'ホシヤイ、アブサロムにいひけるは然らずヱホバと此民とイスラエルの總の人々の選む者に我は屬し且其人とともに居るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, '且又我誰に事ふべきか其子の前に事べきにあらずや我は爾の父のまへに事しごとく爾のまへに事べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, '爰にアブサロム、アヒトベルにいひけるは我儕如何に爲べきか爾等計を爲すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'アヒトペル、アブサロムにいひけるは爾の父が遺して家を守らしむる妾等の處に入れ然ばイスラエル皆爾が其父に惡まるるを聞ん而して爾とともにをる總の者の手強くなるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, '是において屋脊にアブサロムのために天幕を張ければアブサロム、イスラエルの目のまへにて其父の妾等の處に入りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, '當時アヒトペルが謀れる謀計は神の言に問たるごとくなりきアヒトペルの謀計は皆ダビデとアブサロムとに倶に是のごとく見えたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, '時にアヒトペル、アブサロムにいひけるは請ふ我に一萬二千の人を擇み出さしめよ我起て今夜ダビデの後を追ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, '彼が憊れて手弱なりし所を襲ふて彼をおびえしめん而して彼とともにをる民の逃ん時に我王一人を撃とり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, '總の民を爾に歸せしむべし夫衆の歸するは爾が求むる此人に依なれば民みな平穩になるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, '此言アブサロムの目とイスラエルの總の長老の目に的當と見えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'アブサロムいひけるはアルキ人ホシヤイをも召きたれ我等彼が言ふ所をも聞んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'ホシヤイ乃ちアブサロムに至るにアブサロムかれにかたりていひけるはアヒトペル是のごとく言り我等其言を爲べきか若し可ずば爾言ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'ホシヤイ、アブサロムにいひけるは此時にあたりてアヒトペルが授けし計略は善らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'ホシヤイまたいひけるは爾の知るごとく爾の父と其從者は勇士なり且彼等は野にて其子を奪れたる熊の如く其氣激怒をれり又爾の父は戰士なれば民と共に宿らざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, '彼は今何の穴にか何の處にか匿れをる若し數人の者手始に仆なば其を聞く者は皆アブサロムに從ふ者の中に敗ありと言はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'しからば獅子の心のごとき心ある勇猛き夫といふとも全く挫碎ん其はイスラエル皆爾の父の勇士にして彼とともにある者の勇猛き人なるをしればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, '我は計議るイスラエルをダンよりベエルシバにいたるまで海濱の沙の多きが如くに悉く爾の處につどへ集めて爾親ら戰陣に臨むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, '我等彼の見出さるる處にて彼を襲ひ露の地に下るがごとく彼のうへに降らんしかして彼および彼とともにあるすべての人々を一人も遺さざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, '若し彼何かの城邑に集らばイスラエル皆繩を其城邑にかけ我等これを河に曳きたふして其處に一の小石も見えざらしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'アブサロムとイスラエルの人々皆アルキ人ホシヤイの謀計はアヒトペルの謀計よりも善しといふ其はヱホバ、アブサロムに禍を降さんとてヱホバ、アヒトペルの善き謀計を破ることを定めたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, '爰にホシヤイ祭司ザドクとアビヤタルにいひけるはアヒトペル、アブサロムとイスラエルの長老等のために斯々に謀れりきた我は斯々に謀れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'されば爾ら速に人を遣してダビデに告て今夜野の渡場に宿ることなく速に渡りゆけといへおそらくは王および倶にある民皆呑つくされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, '時にヨナタンとアヒマアズはエンロゲルに俟居たり是は城邑にいるを見られざらんとてなり爰に一人の仕女ゆきて彼等に告げければ彼らダビデ王に告んとて往く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'しかるに一人の少者かれらを見てアブザロムにつげたりされど彼等二人は急ぎさりてバホリムの或人の家にいたる其人の庭に井ありてかれら其處にくだりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, '婦蓋をとりて井の口のうへに掩け其上に擣たる麥をひろげたり故に事知れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, '時にアブサロムの僕等其婦の家に來りていひけるはアヒマアズとヨナタンは何處にをるや婦かれらに彼人々は小川を濟れりといふかれら尋ねたれども見當ざればエルサレムに歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, '彼等が去し時かの二人は井よりのぼりて往てダビデ王に告げたり即ちダビデに言けるは起て速かに水を濟れ其はアヒトベル斯爾等について謀計を爲したればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'ダビデ起て己とともにある凡ての民とともにヨルダンを濟れり曙には一人もヨルダンを濟らざる者はなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'アヒトベルは其謀計の行れざるを見て其驢馬に鞍おき起て其邑に往て其家にいたり家の人に遺言して自ら縊れ死て其父の墓に葬らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, '爰にダビデ、マナハイムに至る又アブサロムは己とともにあるイスラエルの凡の人々とともにヨルダンを濟れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'アブサロム、アマサをヨアブの代りに軍の長と爲りアマサは夫のナハシの女にてヨアブの母ゼルヤの妹なるアビガルに通じたるイシマエル人名はヱテルといふ人の子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'かくてイスラエルとアブサロムはギレアデの地に陣どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'ダビデ、マハナイムにいたれる時アンモンの子孫の中なるラバのナハシの子シヨビとロデバルのアンミエルの子マキルおよびロゲリムのギレアデ人バルジライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, '臥床と鍋釜と陶器と小麥と大麥と粉と烘麥と豆と小豆の烘たる者と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, '蜜と牛酪と羊と犢をダビデおよび倶にある民の食ふために持來れり其は彼等民は野にて饑憊れ渇くならんと謂たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, '爰にダビデ己とともにある民を核べて其上に千夫の長百夫の長を立たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'しかしてダビデ民を三に分ちて其一をヨアブの手に託け一をゼルヤの子ヨアブの兄弟アビシヤイの手に託け一をガテ人イツタイの手に託けたりかくして王民にいひけるは我もまた必ず汝らとともに出んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'されど民いふ汝は出べからず我儕如何に逃るとも彼等は我儕に心をとめじ又我儕半死とも我儕に心をとめざるべしされど汝は我儕の一萬に等し故に汝は城邑の中より我儕を助けなば善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, '王かれらにいひけるは汝等の目に善と見ゆるところを爲すべしとかくて王門の傍に立ち民皆或は百人或は千人となりて出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, '王ヨアブ、アビシヤイおよびイツタイに命じてわがために少年アブサロムを寛に待へよといふ王のアブサロムの事について諸の將官に命を下せる時民皆聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, '爰に民イスラエルにむかひて野に出でエフライムの叢林に戰ひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'イスラエルの民其處にてダビデの臣僕のまへに敗る其日彼處の戰死大にして二萬にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'しかして戰徧く其地の表に廣がりぬ是日叢林の滅ぼせる者は刀劒の滅ぼせる者よりも多かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, '爰にアブサロム、ダビデの臣僕に行き遭り時にアブサロム騾馬に乗居たりしが騾馬大なる橡樹の繁き枝の下を過ければアブサロムの頭其橡に繋りて彼天地のあひだにあがれり騾馬はかれの下より行過たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, '一箇の人見てヨアブに告ていひけるは我アブサロムが橡樹に懸りをるを見たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'ヨアブ其告たる人にいひけるはさらば爾見て何故に彼を其處にて地に撃落さざりしや我爾に銀十枚と一本の帶を與へんものを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, '其人ヨアブにいひけるは假令わが手に銀千枚を受べきも我は手をいだして王の子に敵せじ其は王我儕の聞るまへにて爾とアビシヤイとイツタイに命じて爾ら各少年アブサロムを害するなかれといひたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, '我若し反いてかれの生命を戕賊はば何事も王に隱るる所なければ爾自ら立て我を責んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, '時にヨアブ我かく爾とともに滞るべからずといひて手に三本の槍を携へゆきて彼の橡樹の中に尚生をるアブサロムの胸に之を衝通せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'ヨアブの武器を執る十人の少者繞きてアブサロムを撃ち之を死しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'かくてヨアブ喇叭を吹ければ民イスラエルの後を追ふことを息てかへれりヨアブ民を止めたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, '衆アブサロムを將て叢林の中なる大なる穴に投げいれ其上に甚だ大きく石を疊あげたり是においてイスラエル皆おのおの其天幕に逃かへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'アブサロム我はわが名を傳ふべき子なしと言て其生る間に己のために一の表柱を建たり王の谷にあり彼おのれの名を其表柱に與たり其表柱今日にいたるまでアブサロムの碑と稱らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, '爰にザドクの子アヒマアズいひけるは請ふ我をして趨りて王にヱホバの王をまもりて其敵の手を免かれしめたまひし音信を傳へしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'ヨアブかれにいひけるは汝は今日音信を傳ふるものとなるべからず他日に音信を傳ふべし今日は王の子死たれば汝音信を傳ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'ヨアブ、クシ人にいひけるは往て爾が見たる所を王に告よクシ人ヨアブに禮をなして走れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'ザドクの子アヒマアズ再びヨアブにいひけるは請ふ何にもあれ我をも亦クシ人の後より走ゆかしめよヨアブいひけるは我子よ爾は充分の音信を持ざるに何故に走りゆかんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'かれいふ何れにもあれ我をして走りゆかしめよとヨアブかれにいふ走るべし是においてアヒマアズ低地の路をはしりてクシ人を走越たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, '時にダビデは二の門の間に坐しゐたり爰に守望者門の蓋上にのぼり石墻にのぼりて其目を擧て見るに視よ獨一人にて走きたる者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, '守望者呼はりて王に告ければ王いふ若し獨ならば口に音信を持つならんと其人進み來りて近づけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, '守望者復一人の走りきたるを見しかば守望者守門者に呼はりて言ふ獨一人にて走きたる者あり王いふ其人もまた音信を持ものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, '守望者言ふ我先者の走を見るにザドクの子アヒマアズの走るが如しと王いひけるは彼は善人なり善き音信を持來るならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'アヒマアズ呼はりて王にいひけるはねがはくは平安なれとかくて王のまへに地に伏していふ爾の神ヱホバは讃べきかなヱホバかの手をあげて王わが主に敵したる人々を付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, '王いひけるは少年アブサロムは平安なるやアヒマアズこたへけるは王の僕ヨアブ僕を遣はせし時我大なる噪を見たれども何をも知らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, '王いひけるは側にいたりて其處に立よと乃ち側にいたりて立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, '時に視よクシ人來れりクシ人いひけるはねがはくは王音信を受たまへヱホバ今日爾をまもりて凡て爾にたち逆ふ者の手を免かれしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, '王クシ人にいひけるは少年アブサロムは平安なるやクシ人いひけるはねがはくは王わが主の敵および凡て汝に起ち逆ひて害をなさんとする者は彼少年のごとくなれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, '王大に感み門の樓にのぼりて哭り彼行ながらかくいへりわが子アブサロムよわが子わが子アブサロムよ鳴呼われ汝に代りて死たらん者をアブサロムわが子よわが子よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, '時にヨアブに告る者ありていふ視よ王はアブサロムの爲に哭き悲しむと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, '其日の勝利は凡の民の悲哀となれり其は民其日王は其子のために憂ふと言ふを聞たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, '其日民は戰爭に逃て羞たる民の竊て去がごとく竊て城邑にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, '王は其面を掩へり王大聲に叫てわが子アブサロムよアブサロムわが子よわが子よといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'ここにヨアブ家にいり王の許にいたりていひけるは汝今日汝の生命と汝の男子汝の女子の生命および汝の妻等の生命と汝の妾等の生命を救ひたる汝の凡の臣僕の顔を羞させたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, '是は汝おのれを惡む者を愛しおのれを愛する者を惡むなり汝今日汝が諸侯伯をも諸僕をも顧みざるを示せり今日我さとる若しアブサロム生をりて我儕皆死たらば汝の目に適ひしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'されど今立て出で汝の諸僕を慰めてかたるべし我ヱホバを指て誓ふ汝若し出ずば今夜一人も汝とともに止るものなかるべし是は汝が若き時より今にいたるまでに蒙りたる諸の災禍よりも汝に惡かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, '是に於て王たちて門に坐す人々凡の民に告て視よ王は門に坐し居るといひければ民皆王のまへにいたる然どイスラエルはおのむの其天幕に逃かへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'イスラエルの諸の支派の中に民皆爭ひていひけるは王は我儕を敵の手より救ひいだしまた我儕をペリシテ人の手より助けいだせりされど今はアブサロムのために國を逃いでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'また我儕が膏そそぎて我儕の上にかきしアブサロムは戰爭に死ねりされば爾ら何ぞ王を導きかへらんことと言ざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'ダビデ王祭司ザドクとアビヤタルに言つかはしけるはユダの長老等に告て言ヘイスラエルの全家の言語王の家に達せしに爾ら何ぞ王を其家に導きかへる最後となるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, '爾等はわが兄弟爾らはわが骨肉なりしかるになんぞ爾等王を導き歸る最後となるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, '又アマサに言べし爾はわが骨肉にあらずや爾ヨアブにかはりて常にわがまへにて軍長たるべし若しからずば神我に斯なし又重ねてかくなしたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'かくダビデ、ユダの凡の人をして其心を傾けて一人のごとくにならしめければかれら王にねがはくは爾および爾の諸の臣僕歸りたまへといひおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, '是において王歸りてヨルダンにいたるにユダの人々王を迎へんとて來りてギルガルにいたり王を送りてヨルダンを濟らんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, '時にバホリムのベニヤミン人ゲラの子シメイ急ぎてユダの人々とともに下りダビデ王を迓ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, '一千のベニヤミン人彼とともにあり亦サウルの家の僕ヂバも其十五人の男子と二十人の僕をしたがへて偕に居たりしが皆王のまへにむかひてヨルダンをこぎ渡れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, '時に王の家族を濟しまた王の目に善と見ゆるところを爲んとて濟舟を濟せり爰にゲラの子シメイ、ヨルダンを濟れる時王のまへに伏して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, '王にいひけるはわが主よねがはくは罪を我に歸するなかれまた王わが主のエルサレムより出たまへる日に僕が爲たる惡き事を記憶えたまふなかれねがはくは王これを心に置たまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, '其は僕我罪を犯したるを知ればなり故に視よ我今日ヨセフの全家の最初に下り來りて王わが主を迓ふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, '然にゼルヤの子アビシヤイ答へていひけるはシメイはヱホバの膏そそぎし者を詛たるに因て其がために誅さるべきにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'ダビデいひけるは爾らゼルヤの子よ爾らのあづかるところにあらず爾等今日我に敵となる今日豈イスラエルの中にて人を誅すべけんや我豈わが今日イスラエルの王となりたるをしらざらんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, '是をもて王はシメイに爾は誅されじといひて王かれに誓へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, '爰にサウルの子メピボセテ下りて王をむかふ彼は王の去し日より安かに歸れる日まで其足を飾らず其鬚を飾らず又其衣を濯ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, '');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, '彼エルサレムよりきたりて王を迓ふる時王かれにいひけるはメビボセテ爾なんぞ我とともに往ざりしや 彼こたへけるはわが主王よわが僕我を欺けり僕はわれ驢馬に鞍おきて其に乗て王の處にゆかんといへり僕跛者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'しかるに彼僕を王わが主に讒言せり然ども王わが主は神の使のごとし故に爾の目に善と見るところを爲たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'わが父の全家は王わが主のまへには死人なるのみなるに爾僕を爾の席にて食ふ者の中に置たまへりされば我何の理ありてか重ねて王に哀訴ることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, '王かれにいひけるは爾なんぞ重ねて爾の事を言や我いふ爾とヂバ其地を分つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'メピボセテ王にいひけるは王わが主安然に其家に歸りたまひたればかれに之を悉くとらしめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, '爰にギレアデ人バルジライ、ロゲリムより下り王を送りてヨルダンを渡らんとて王とともにヨルダンを濟れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'バルジライは甚だ老たる人にて八十歳なりきかれは甚だ大なる人なれば王のマハナイムに留れる間王を養へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, '王バルジライにいひけるは爾我とともに濟り來れ我エルサレムにて爾を我とともに養はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'バルジライ王にいひけるはわが生命の年の日尚幾何ありてか我王とともにエルサレムに上らんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, '我は今日八十歳なり善きと惡きとを辨へるをえんや僕其食ふところと飮ところを味ふをえんや我再び謳歌之男と謳歌之女の聲を聽えんや僕なんぞ尚王わが主の累となるべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, '僕は王とともにヨルダンを濟りて只少しくゆかん王なんぞこの報賞を我に報ゆるに及ばんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, '請ふ僕を歸らしめよ我自己の邑にてわが父母の墓の側に死ん但し僕キムハムを視たまへかれを王わが主とともに濟り往しめたまへ又爾の目に善と見る所を彼になしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, '王いひけるはキムハム我とともに濟り往くべし我爾の目に善と見ゆる所をかれに爲ん又爾が望みて我に求むる所は皆我爾のために爲すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, '民皆ヨルダンを濟れり王渡りし時王バルジライに接吻してこれを祝す彼遂に己の所に歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'かくて王ギルガルに進むにキムハムかれとともに進めりユダの民皆王を送れりイスラエルの民の半も亦しかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, '是にイスラエルの人々皆王の所にいたりて王にいひけるは我儕の兄弟なるユダの人々何故に爾を竊みさり王と其家族およびダビデとともなる其凡の從者を送りてヨルダンを濟りしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'ユダの人々皆イスラエルの人々に對へていふ王は我に近きが故なり爾なんぞ此事について怒るや我儕王の物を食ひしことあるや王我儕に賜物を與へたることあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'イスラエルの人ユダの人に對ていひけるは我は王のうちに十の分を有ち亦ダビデのうちにも我は爾よりも多を有つなりしかるに爾なんぞ我らを軽じたるやわが王を導きかへらんと言しは我最初なるにあらずやとされどユダの人々の言はイスラエルの人々の言よりも厲しかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, '爰に一人の邪なる人あり其名をシバといビクリの子にしてベニヤミン人なり彼喇叭を吹ていひけるは我儕はダビデの中に分なし又ヱサイの子のうちに產業なしイスラエルよ各人其天幕に歸れよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, '是によりてイスラエルの人皆ダビデに随ふことを止てのぼりビクリの子シバにしたがへり然どユダの人々は其王に附てヨルダンよりエルサレムにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'ダビデ、エルサレムにある己の家にいたり王其遺して家を守らせたる妾なる十人の婦をとりてこれを一の室に守り置て養へりされどかれらの處には入ざりき斯かれらは死る日まで閉こめられて生涯嫠婦にてすごせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, '爰に王アマサにいひけるは我ために三日のうちにユダの人々を召きたれしかして爾此處にをれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'アマサ乃ちユダを召あつめんとて往たりしが彼ダビデが定めたる期よりも長く留れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, '是においてダビデ、アビシヤイにいひけるはビクリの子シバ今我儕にアブサロムよりもおほくの害をなさんとす爾の主の臣僕を率ゐて彼の後を追へ恐らくは彼堅固なる城邑を獲て我儕の目を逃れんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, '是によりてヨアブの從者とケレテ人とペレテ人および都の勇士彼にしたがびて出たり即ち彼等エルサレムより出てビクリの子シバの後を追ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, '彼等がギベオンにある大石の傍に居りし時アマサかれらにむかひ來れり時にヨアブ戎衣に帶を結て衣服となし其上に刀を鞘にをさめ腰に結びて帶び居たりしが其劍脱け堕ちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'ヨアブ、アマサにわが兄弟よ爾は平康なるやといひて右の手をもてアマサの鬚を將て彼に接吻せんとせしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'アマサはヨアブの手にある劍に意を留ざりければヨアブ其をもてアマサの腹を刺して其膓を地に流しいだし重ねて撃に及ばざらしめてこれをころせり かくてヨアブと其兄弟アビシヤイ、ビクリの子シバの後を追り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, '時にヨアブの少者の一人アマサの側にたちていふヨアブを助くる者とダビデに附從ものはヨアブの後に隨へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'アマサは血に染て大路の中に轉び居たり斯人民の皆立どまるを見てアマサを大路より田に移したるが其側にいたれる者皆見て立ちとまりければ衣を其上にかけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'アマサ大路より移されければ人皆ヨアブにしたがひ進みてビクリの子シバの後を追ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, '彼イスラエルの凡の支派の中を行てアベルとベテマアカに至るに少年皆集りて亦かれにしたがひゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'かくて彼等來りて彼をアベル、ベテマアカに圍み城邑にむかひて壘を築けり是は壕の中にたてりかくしてヨアブとともにある民皆石垣を崩さんとてこれを撃居りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, '一箇の哲き婦城邑より呼はりていふ爾ら聽よ爾ら聽よ請ふ爾らヨアブに此に近よれ我爾に言んと言へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'かれ其婦にちかよるに婦いひけるは爾はヨアブなるやかれ然りといひければ婦彼にいふ婢の言を聽けかれ我聽くといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, '婦即ち語りていひけるは昔人々誠に語りて人必ずアベルにおいて索問べしといひて事を終ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, '我はイスラエルの中の平和なる忠義なる者なりしかるに爾はイスラルの中にて母ともいふべき城邑を滅さんことを求む何ゆゑに爾ヱホバの產業を呑み盡さんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'ヨアブ答へていひけるは決めてしからず決めてしからずわれ呑み盡し或は滅ぼさんとすることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, '其事しからずエフライムの山地の人ビクリの子名はシバといふ者手を擧て王ダビデに敵せり爾ら只彼一人を付せ然らば我此邑をさらんと婦ヨアブにいひけるは視よ彼の首級は石垣の上より爾に投いだすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'かくて婦其智慧をもて凡の民の所にいたりければかれらビクリの子シバの首級を刎てヨアブの所に投出せり是においてヨアブ喇叭を吹ならしければ人々散て邑より退きておのおの其天幕に還りぬヨアブはエルサレムにかへりて王の處にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'ヨアブはイスラエルの全軍の長なりヱホヤダの子ベナヤはケレテ人とペレテ人の長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'アドラムは徴募長なりアヒルデの子ヨシヤパテは史官なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'シワは書記官なりザドクとアビヤタルは祭司なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, '亦ヤイル人イラはダビデの大臣なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'ダビデの世に年復年と三年饑饉ありければダビデ、ヱホバに問にヱホバ言たまひけるは是はサウルと血を流せる其家のためなり其は彼嘗てギベオン人を殺したればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, '是において王ギベオン人を召てかれらにいへりギベオン人はイスラエルの子孫にあらずアモリ人の殘餘なりしがイスラエルの子孫昔彼等に誓をなしたり然るにサウル、イスラエルとユダの子孫に熱心なるよりして彼等を殺さんと求めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, '即ちダビデ、ギベオン人にいひけるは我汝等のために何を爲すべきか我何の賠償を爲さば汝等ヱホバの產業を祝するや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'ギベオン人彼にいひけるは我儕はサウルと其家の金銀を取じ又汝は我らのためにイスラエルの中の人一人をも殺すなかれダビデいひけるは汝等が言ふ所は我汝らのために爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, '彼等王にいひけるは我儕を滅したる人我儕を殲してイスラエルの境の中に居留ざらしめんとて我儕にむかひて謀を設けし人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, '請ふ其人の子孫七人を我儕に與へよ我儕ヱホバの選みたるサウルのギベアにて彼等をヱホバのまへに懸ん王いふ我與ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'されど王サウルの子ヨナタンの子なるメピボセテを惜めり是は彼等のあひだ即ちダビデとサウルの子ヨナタンとの間にヱホバを指して爲る誓あるに因り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'されど王アヤの女リヅパがサウルに生し二人の子アルモニとメピボセテおよびサウルの女メラブがメホラ人バルジライの子アデリエルに生し五人の子を取りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'かれらをギベオン人の手に與へければギベオン人かれらを山の上にてヱホバの前に懸たり彼等七人倶に斃れて刈穫の初日即ち大麥刈の初時に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'アヤの女リヅパ麻布を取りて刈穫の初時より其屍上に天より雨ふるまでこれをおのれのために磐の上に布きおきて晝は空の鳥を屍の上に止らしめず夜は野の獣をちかよらしめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, '爰にアヤの女サウルの妾リヅパの爲しことダビデに聞えければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'ダビデ往てサウルの骨と其子ヨナタンの骨をヤベシギレアデの人々の所より取り是はペリシテ人がサウルをギルボアに殺してベテシヤンの衢に懸たるをかれらが竊みさりたるものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'ダビデ其處よりサウルの骨と其子ヨナタンの骨を携へ上れりまた人々其懸られたる者等の骨を斂たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'かくてサウルと其子ヨナタンの骨をベニヤミンの地のゼラにて其父キシの墓に葬り都て王の命じたる所を爲り比より後神其地のため祈祷を聽たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'ペリシテ人復イスラエルと戰爭を爲すダビデ其臣僕とともに下りてペリシテ人と戰ひけるがダビデ困憊居りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'イシビベノブ、ダビデを殺さんと思へり(イシビベノブは巨人の子等の一人にて其槍の銅の重は三百シケルあり彼新しき劒を帶たり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'しかれどもゼルヤの子アビシヤイ、ダビデを助けて其ペリシテ人を撃ち殺せり是においてダビデの從者かれに誓ひていひけるは汝は再我儕と共に戰爭に出べからず恐らくは爾イスラエルの燈光を消さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, '此後再びゴブにおいてペリシテ人と戰あり時にホシヤ人シベカイ巨人の子等の一人なるサフを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, '爰に復ゴブにてペリシテ人と戰あり其處にてベテレヘム人ヤレオレギムの子エルハナン、ガテのゴリアテの兄弟ラミを殺せり其槍の柄は機の梁の如くなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, '又ガテに戰ありしが其處に一人の身長き人あり手には各六の指あり足には各六の指ありて其數合せて二十四なり彼もまた巨人の生る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, '彼イスラエルを挑みしかばダビデに兄弟シメアの子ヨナタン彼を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, '是らの四人はガテにて巨人の生るものなりしがダビデの手と其臣僕の手に斃れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'ダビデ、ヱホバが己を諸の敵の手とサウルの手より救ひいだしたまへる日に此歌の言をヱホバに陳たり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'ヱホバはわが巌わが要害我を救ふ者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'わが磐の神なりわれ彼に倚賴むヱホバはわが干わが救の角わが高櫓わが逃躱處わが救主なり爾我をすくひて暴き事を免れしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, '我ほめまつるべきヱホバに呼はりてわが敵より救はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, '死の波涛われを繞み邪曲なる者の河われをおそれしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, '冥府の繩われをとりまき死の機檻われにのぞめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'われ艱難のうちにヱホバをよびまたわが神に龥れりヱホバ其殿よりわが聲をききたまひわが喊呼其耳にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, '爰に地震ひ撼き天の基動き震へりそは彼怒りたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, '烟其鼻より出てのぽり火その口より出て燒きつくしおこれる炭かれより燃いづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, '彼天を傾けて下りたまふ黑雲その足の下にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'ケルブに乗て飛び風の翼の上にあらはれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, '其周圍に黑暗をおき集まれる水密雲を幕としたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'そのまへの光より炭火燃いづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'ヱホバ天より雷をくだし最高者聲をいだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, '又箭をはなちて彼等をちらし電をはなちて彼等をうちやぶりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'ヱホバの叱咤とその鼻の氣吹の風によりて海の底あらはれいで地の基あらはになりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'ヱホバ上より手をたれて我をとり洪水の中より我を引あげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'またわが勁き敵および我をにくむ者より我をすくひたまへり彼等は我よりも強かりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, '彼等はわが菑災の日にわれに臨めりされどヱホバわが支柱となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, '我を廣き處にひきいだしわれを喜ぶがゆゑに我をすくひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'ヱホバわが義にしたがひて我に報い吾手の清潔にしたがひて我に酬したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, '其はわれヱホバの道をまもり惡をなしてわが神に離しことなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'その律例は皆わがまへにあり其法憲は我これを離れざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'われ神にむかひて完全かり又身を守りて惡を避たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, '故にヱホバわが義にしたがひ其目のまへにわが潔白あるに循ひてわれに報いたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, '矜恤者には爾矜恤ある者のごとくし完全人には爾完全者のごとくし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, '潔白者には爾潔白もののごとくし邪曲者には爾嚴刻者のごとくしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, '難る民は爾これを救たまふ然ど矜高者は爾の目見て之を卑したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'ヱホバ爾はわが燈火なりヱホバわが暗をてらしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'われ爾によりて軍隊の中を驅とほりわが神に由て石垣を飛こゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, '神は其道まつたしヱホバの言は純粋なし彼は都て己に倚賴む者の干となりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, '夫ヱホバのほか誰か神たらん我儕の神のほか敦か磐たらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, '神はわが強き堅衆にてわが道を全うし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'わが足を麀の如くなし我をわが崇邱に立しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, '神わが手に戰を敎へたまへばわが腕は銅の弓をも挽を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, '爾我に爾の救の干を與へ爾の慈悲われを大ならしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, '爾わが身の下の歩を恢廓しめたまへば我踝ふるへず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'われわが敵を追て之をほろぼし之を絶すまではかへらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'われ彼等を絶し彼等を破碎ば彼等たちえずわが足の下にたふる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, '汝戰のために力をもて我に帶しめ又われに逆ふ者をわが下に拝跪しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, '爾わが敵をして我に後を見せしめたまふ我を惡む者はわれ之をほろぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, '彼等環視せど救ふ者なしヱホバを仰視ど彼等に應たまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, '地の塵の如くわれ彼等をうちくだき又衢間の泥のごとくわれ彼等をふみにぢる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, '爾われをわが民の爭闘より救ひ又われをまもりて異邦人等の首長となしたまふわが知ざる民我につかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, '異邦人等は我に媚び耳に聞と均しく我にしたがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, '異邦人等は衰へ其衛所より戰慄て出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'ヱホバは活る者なりわが磐は讃べきかなわが救の磐の神はあがめまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, '此神われに仇を報いしめ國々の民をわが下にくだらしめたまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, '又わが敵の中よりわれを出し我にさからふ者の上に我をあげまた強暴人の許よりわれを救ひいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, '是故にヱホバよわれ異邦人等のうちに爾をほめ爾の名を稱へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'ヱホバその王の救をおほいにしその受膏者なるダビデと其裔に永久に恩を施したまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'ダビデの最後の言は是なりヱサイの子ダビデの詔言即ち高く擧られし人ヤコブの神に膏をそそがれし者イスラエルの善き歌人の詔言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'ヱホバの霊わが中にありて言たまふ其諭言わが舌にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'イスラエルの神いひたまふイスラエルの磐われに語たまふ人を正く治むる者神を畏れて治むる者は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, '日の出の朝の光のごとく雲なき朝のごとく又雨の後の日の光明によりて地に茁いづる新草ごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'わが家かく神とともにあるにあらずや神萬具備りて鞏固なる永久の契約を我になしたまへり吾が救と喜を皆いかで生ぜしめたまはざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'しかれども邪なる者は荊棘のごとくにして手をもて取がたければ皆ともにすてられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, '之にふるる人は鐵と槍の柯とを其身に備ふべし是は火にやけて燒たゆるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, '是等はダビデの勇士の名なりタクモニ人ヤシヨベアムは三人衆の長なりしが一時八百人にむかひて槍を揮ひて之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, '彼の次はアホア人ドドの子エルアザルにして三勇士の中の者なり彼其處に戰はんとて集まれるペリシテ人にむかひて戰を挑みイスラエルの人々の進みのぼれる時にダビデとともに居たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'たちてペリシテ人を撃ち終に其手疲て其手劍に固着て離れざるにいたれり此日ヱホバ大なる救拯を行ひたまふ民は彼の跡にしたがひゆきて只褫取而巳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, '彼の次はハラリ人アゲの子シヤンマなり一時ペリシテ人一隊となりて集まれり彼處に扁豆の滿たる地の處あり民ペリシテ人のまへより逃たるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, '彼其地の中に立て禦ぎペリシテ人を殺せりしかしてヱホバ大なる救拯を行ひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, '刈穫の時に三十人衆の首長なる三人下りてアドラムの洞穴に往てダビデに詣れり時にペリシテ人の隊レパイムの谷に陣どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, '其時ダビデは要害に居りペリシテ人の先陣はベテレヘムにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'ダビデ慕ひていひけるは誰かベテレヘムの門にある井の水を我にのましめんかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, '三勇士乃ちペリシテ人の陣を衝き過てベテレヘムの門にある井の水を汲取てダビデの許に携へ來れり然どダビデ之をのむことをせずこれをヱホバのまへに灌ぎて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'いひけるはヱホバよ我決てこれを爲じ是は生命をかけて往し人の血なりと彼これを飮ことを好まざりき三勇士は是等の事を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'ゼルヤの子ヨアブの兄弟アビシヤイは三十人衆の首たり彼三百人にむかひて槍を揮ひて殺せり彼其三十人衆の中に名を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, '彼は三十人衆の中の最も尊き者にして彼等の長とたれり然ども三人衆には及ばざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'ヱホヤダの子カブジエルのベナヤは勇氣あり多くの功績ありし者なり彼モアブの人の獅子の如きもの二人を撃殺せり彼は亦雪の時に下りて穴の中にて獅子を撃殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, '彼また容貌魁偉たるエジプト人を撃殺せり其エジプト人は手に槍を持たるに彼は杖を執て下りエジプト人の手より槍を捩とりて其槍をもてこれを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'ヱホヤダの子ベナヤ是等の事を爲し三十勇士の中に名を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, '彼は三十人衆の中に尊かりしかども三人衆には及ばざりきダビデかれを參議の中に列しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, '三十人衆の中にはヨアブの兄弟アサヘル、ベテレヘムのドドの子エルハナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'ハロデ人シヤンマ、ハロデ人エリカ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'パルデ人ヘレヅ、テコア人イツケシの子イラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'アネトテ人アビエゼル、ホシヤ人メブンナイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'アホア人ザルモン、ネトバ人マハライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'ネトパ人バアナの子ヘレブ、ベニヤミンの子孫のギベアより出たるリバイの子イツタイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'ヒラトン人ベナヤ、ガアシの谷のヒダイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'アルパテ人アビアルボン、バホリム人アズマウテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'シヤルボニ人エリヤバ、キゾニ人ヤセン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'ハラリ人シヤンマの子ヨナタン、アラリ人シヤラルの子アヒアム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'ウルの子エリパレテ、マアカ人へペル、ギロ人アヒトペルの子エリアム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'カルメル人ヘヅライ、アルバ人パアライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'ゾバのナタンの子イガル、ガド人バニ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'アンモニ人ゼレク、ゼルヤの子ヨアブの武器を執る者ベエロデ人ナハライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'ヱテリ人イラ、ヱテリ人ガレブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'ヘテ人ウリヤあり都三十七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'ヱホバ復イスラエルにむかひて怒を發しダビデを感動して彼等に敵對しめ往てイスラエルとユダを數へよと言しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, '王乃ちヨアブおよびヨアブとともにある軍長等にいひけるは請ふイスラエルの諸の支派の中をダンよりベエルシバに至るまで行めぐりて民を核べ我をして民の數を知しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'ヨアブ王にいひけるは幾何あるともねがはくは汝の神ヱホバ民を百倍に増たまへ而して王わが主の目それを視るにいたれ然りといへども王わが主の此事を悦びたまふは何故ぞやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'されど王の言ヨアブと軍長等に勝ければヨアブと軍長等王の前を退きてイスラエルの民を核べに往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'かれらヨルダンを濟りアロエルより即ち河の中の邑より始めてガドにいたりヤゼルにいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'ギレアデにいたりタテムホデシの地にいたり又ダニヤンにいたりてシドンに旋り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'またツロの城にいたりヒビ人とカナン人の諸の邑にいたりユダの南に出てベエルシバにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, '彼等國を徧く行めぐり九月と廿日を經てルサレムに至りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'ヨアブ人口の數を王に告たり即ちイスラエルに劍を抜く壯士八十萬ありき又ユダの人は五十萬ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'ダビデ民の數を書し後其心自ら責む是においてダビデ、ヱホバにいふ我これを爲して大に罪を犯したりねがはくはヱホバよ僕の罪を除きたまへ我甚だ愚なる事を爲りと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'ダビデ朝興し時ヱホバの言ダビデの先見者なる預言者ガデに臨みて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '往てダビデに言へヱホバ斯いふ我汝に三を示す汝其一を擇べ我其を汝に爲んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'ガデ、ダビデの許にいたりこれに告てこれにいひけるは汝の地に七年の饑饉いたらんか或は汝敵に追れて三月其前に遁んか或は爾の地に三日の疫病あらんか爾考へてわが如何なる答を我を遣はせし者に爲べきかを決めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'ダビデ、ガデにいひけるは我大に苦しむ請ふ我儕をしてヱホバの手に陷らしめよ其憐憫大なればなり我をして人の手に陷らしむるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, '是においてヱホバ朝より集會の時まで疫病をイスラエルに降したまふダンよりベエルシバまでに民の死る者七萬人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, '天の使其手をエルサレムに伸てこれを滅さんとしたりしがヱホバ此害惡を悔て民を滅す天使にいひたまひけるは足り今汝の手を住めよと時にヱホバの使はヱブス人アラウナの禾場の傍にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'ダビデ民を撃つ天使を見し時ヱホバに申していひけるは嗚呼我は罪を犯したり我は惡き事を爲たり然ども是等の羊群は何を爲たるや請ふ爾の手を我とわが父の家に對たまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, '此日ガデ、ダビデの所にいたりてかれにいひけるは上りてヱブス人アラウナの禾場にてヱホバに壇を建よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'ダビデ、ガデの言に隨ひヱホバの命じたまひしごとくのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'アラウナ觀望て王と其臣僕の己の方に進み來るを見アラウナ出て王のまへに地に伏て拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'かくてアラウナいひけるは何に因てか王わが主僕の所にきませるやダビデひけるは汝より禾場を買ひとりヱホバに壇を築きて民に降る災をとどめんとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'アラウナ、ダビデにいひけるはねがはくは王わが主其目に善と見ゆるものを取て献げたまへ燔祭には牛あり薪には打禾車と牛の器ありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'アラリナこれを悉く王に奉呈ぐアラウナ又王にねがはくは爾の神ヱホバ爾を受納たまはんことをといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, '王アラウナにいひけるは斯すべからず我必ず値をはらひて爾より買とらん我費なしに燔祭をわが神ヱホバに献ぐることをせじとダビデ銀五十シケルにて禾場と牛を買とれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'ダビデ其處にてヱホバに壇を築き燔祭と酬恩祭を献げたり是においてヱホバ其地のために祈祷を聽たまひて災のイスラエルに降ること止りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, '爰にダビデ王年邁みて老い寝衣を衣するも温らざりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, '其臣僕等彼にいひけるは王わが主のために一人の若き處女を求めしめて之をして王のまへにたちて王の左右となり汝の懐に臥て王わが主を暖めしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, '彼等乃ちイスラエルの四方の境に美き童女を求めてシユナミ人アビシヤグを得て之を王に携きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, '此童女甚だ美くして王の左右となり王に事たり然ど王之と交はらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, '時にハギテの子アドニヤ自ら高くし我は王とならんと言て己のために戰車と騎兵および自己のまへに驅る者五十人を備へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, '其父は彼が生れてより已來汝何故に然するやと言てかれを痛しめし事なかりきアドニヤも亦容貌の甚だ美き者にてアブサロムの次に生れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, '彼ゼルヤの子ヨアブおよび祭司アビヤタルと商議ひしかば彼等之に從ひゆきて助けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'されど祭司ザドクとヱホヤダの子ベナヤと預言者ナタンおよびシメイとレイならびにダビデに屬したる勇士はアドニヤに與せざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'アドニヤ、エンロゲルの近邊なるゾヘレテの石の傍にて羊と牛と肥畜を宰りて王の子なる己の兄弟および王の臣僕なるユダの人を盡く請けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'されども預言者ナタンとベナヤと勇士とおのれの兄弟ソロモンとをば招かざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, '爰にナタン、ソロモンの母バテシバに語りていひけるは汝ハギテの子アドニヤが王となれるを聞ざるかしかるにわれらの主ダビデはこれを知ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'されば請ふ來れ我汝に計を授て汝をして己の生命と汝の子ソロモンの生命を救しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, '汝往てダビデ王の所に入り之にいへ王わが主よ汝は婢に誓ひて汝の子ソロモンは我に継で王となりわが位に坐せんといひたまひしにあらずや然にアドニヤ何故に王となれるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'われまた汝が尚其處にて王と語ふ時に汝に次て入り汝の言を證すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, '是においてバテシバ寝室に入りて王の所にいたるに王は甚だ老てシユナミ人アビシヤグ王に事へ居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'バテシバ躬を鞠め王を拝す王いふ何なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'かれ王にいひけるはわが主汝は汝の神ヱホバを指て婢に汝の子ソロモンは我に継で王となりわが位に坐せんと誓ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'しかるに視よ今アドニヤ王となれり而て王わが主汝は知たまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, '彼は牛と肥畜と羊を饒く宰りて王の諸子および祭司アビヤタルと軍の長ヨアブを招けりされど汝の僕ソロモンをば招かざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, '汝王わが主よイスラエルの目皆汝に注ぎ汝が彼等に誰が汝に継で王わが主の位に坐すべきを告るを望む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, '王わが主の其父祖と共に寝たまはん時に我とわが子ソロモンは罪人と見做さるるにいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'バテシバ尚王と語ふうちに視よ預言者ナタンも亦入きたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, '人々王に告て預言者ナタン此にありと曰ふ彼王のまへに入り地に伏て王を拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'しかしてナタンいひけるは王わが主汝はアドニヤ我に継で王となりわが位に坐すべしといひたまひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, '彼は今日下りて牛と肥畜と羊を饒く宰りて王の諸子と軍の長等と祭司アビヤタルを招けりしかして彼等はアドニヤのまへに飮食してアドニヤ王壽かれと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'されど汝の僕なる我と祭司ザドクとヱホヤダの子ベナヤと汝の僕ソロモンとは彼請かざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, '此事は王わが主の爲たまふ所なるかしかるに汝誰が汝に継で王わが主の位に坐すべきを僕に知せたまはざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'ダビデ王答ていふバテシバをわが許に召せと彼乃ち王のまへに入て王のまへにたつに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, '王誓ひていひけるはわが生命を諸の艱難の中に救ひたまひしヱホバは活く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, '我イスラエルの神ヱホバを指て誓ひて汝の子ソロモン我に継で王となり我に代りてわが位に坐すべしといひしごとくに我今日爲すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, '是においてバテシバ躬を鞠め地に伏て王を拝し願くはわが主ダビデ王長久に生ながらへたまへといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'ダビデ王いひけるはわが許に祭司ザドクと預言者ナタンおよびヱホヤダの子ベナヤを召と彼等乃ち王のまへに來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, '王彼等にいひけるは汝等の主の臣僕を伴ひわが子ソロモンをわが身の騾に乗せ彼をギホンに導き下り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, '彼處にて祭司ザドクと預言者ナタンは彼に膏をそそぎてイスラエルの上に王と爲すべししかして汝ら喇叭を吹てソロモン王壽かれと言へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'かくして汝ら彼に隨ひて上り來るべし彼は來りてわが位に坐し我に代りて王となるべし我彼を立てイスラエルとユダの上に主君となせりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'ヱホヤダの子ベナヤ王に對へていひけるはアメンねがはくは王わが主の神ヱホバ然言たまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'ねがはくはヱホバ王わが主とともに在せしごとくソロモンとともに在してその位をわが主ダビデ王の位よりも大ならしめたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, '斯て祭司ザドクと預言者ナタンおよびヱホヤダの子ベナヤ並にケレテ人とペレテ人下りソロモンをダビデ王の騾に乗せて之をギホンに導きいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'しかして祭司ザドク幕屋の中より膏の角を取てソロモンに膏そそげりかくて喇叭を吹きならし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, '民みなソロモン王壽かれと言り民みなかれに隨ひ上りて笛を吹き大に喜祝ひ地はかれらの聲にて裂たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'アドニヤおよび彼とともに居たる賓客其食を終たる時に皆これを聞りヨアブ喇叭の聲を聞ていひけるは城邑の中の聲音何ぞ喧囂やと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, '彼が言をる間に視よ祭司アビヤタルの子ヨナタン來るアドニヤ彼にいひけるは入よ汝は勇ある人なり嘉音を持きたれるならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'ヨナタン答へてアドニヤにいひけるは誠にわが主ダビデ王ソロモンを王となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, '王祭司ザドクと預言者ナタンおよびヱホヤダの子ベナヤ並にケレテ人とペレテ人をソロモンとともに遣したまふ即ち彼等はソロモンを王の騾に乗せてゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, '祭司ザドクと預言者ナタン、ギホンにて彼に膏をそそぎて王となせり而して彼等其處より歓て上るが故に城邑は諠囂し汝らが聞る聲音は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, '又ソロモン國の位に坐し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, '且王の臣僕來りてわれらの主ダビデ王に祝を陳て願くは汝の神ソロモンの名を汝の名よりも美し其位を汝の位よりも大たらしめたまへと言りしかして王は牀の上にて拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, '王また斯いへりイスラエルの神ヱホバはほむべきかなヱホバ今日わが位に坐する者を與たまひてわが目亦これを見るなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'アドニヤとともにある賓客皆驚愕き起て各其途に去りゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, '茲にアドニヤ、ソロモンの面を恐れ起て往き壇の角を執へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, '或人ソロモンに告ていふアドニヤ、ソロモン王を畏る彼壇の角を執て願くはソロモン王今日我に劍をもて僕を殺じと誓ひ給へと言たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'ソロモンいひけるは彼もし善人となるならば其髮の毛一すぢも地におちざるべし然ど彼の中に惡の見るあらば死しむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'ソロモン王乃ち人を遣て彼を壇より携下らしむ彼來りてソロモン王を拝しければソロモン彼に汝の家に往といへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'ダビデ死ぬる日近よりければ其子ソロモンに命じていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '我は世人の皆往く途に往んとす汝は強く丈夫のごとく爲れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, '汝の神ヱホバの職守を守り其道に歩行み其法憲と其誡命と其律例と其證言とをモーセの律法に録されたるごとく守るべし然らば汝凡て汝の爲ところと凡て汝の向ふところにて榮ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, '又ヱホバは其甞に我の事に付て語りて若汝の子等其道を愼み心を盡し精神を盡して眞實をもて吾前に歩ばイスラエルの位に上る人汝に缺ることなかるべしと言たまひし言を堅したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, '又汝はゼルヤの子ヨアブが我に爲たる事即ち彼がイスラエルの二人の軍の長ネルの子アブネルとヱテルの子アマサに爲たる事を知る彼此二人を切殺し太平の時に戰の血を流し戰の血を己の腰の周圍の帶と其足の履に染たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, '故に汝の智慧にしたがひて事を爲し其白髮を安然に墓に下らしむるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, '但しギレアデ人バルジライの子等には恩惠を施こし彼等をして汝の席にて食ふ者の中にあらしめよ彼等はわが汝の兄弟アブサロムの面を避て逃し時我に就たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, '視よ又バホリムのベニヤミン人ゲラの子シメイ汝とともに在り彼はわがマナハイムに往し時勵しき詛言をもて我を詛へり然ども彼ヨルダンに下りて我を迎へたれば我ヱホバを指て誓ひて我劍をもて汝を殺さじといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, '然りといへども彼を辜なき者とする勿れ汝は智慧ある人なれば彼に爲べき事を知るなり血を流して其白髮を墓に下すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, '斯てダビデは其父祖と偕に寝りてダビデの城に葬らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'ダビデのイスラエルに王たりし日は四十年なりき即ちヘブロンにて王たりし事七年エルサレムにて王たりし事三十三年');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'ソロモン其父ダビデの位に坐し其國は堅固く定まりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, '爰にハギテの子アドニヤ、ソロモンの母バテシバの所に來りければバテシバいひけるは汝は平穩なる事のために來るや彼いふ平穩たる事のためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, '彼又いふ我は汝に言さんとする事ありとバテシバいふ言されよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'かれいひけるは汝の知ごとく國は我の有にしてイスラエル皆其面を我に向て王となさんと爲りしかるに國は轉てわが兄弟の有となれり其彼の有となれるはヱホバより出たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, '今我一の願を汝に求む請ふわが面を黜くるなかれバテシバかれにいひけるは言されよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, '彼いひけるは請ふソロモン王に言て彼をしてシエナミ人アビシヤグを我に與て妻となさしめよ彼は汝の面を黜けざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'バテシバいふ善し我汝のために王に言んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'かくてバテシバ、アドニヤのために言とてソロモン王の許に至りければ王起てかれを迎へ彼を拝して其位に坐なほり王母のために座を設けしむ乃ち其右に坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'しかしてバテシバいひけるは我一の細小き願を汝に求むわが面を黜くるなかれ王かれにいひけるは母上よ求めたまへ我汝の面を黜けざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, '彼いひけるは請ふシユナミ人アビシヤグをアドニヤに與て妻となさしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'ソロモン王答て其母にいひけるは何ぞアドニヤのためにシユナミ人アビシヤグを求めらるるや彼のために國をも求められよ彼は我の兄なればなり彼と祭司アビヤタルとゼルヤの子ヨアブのために求められよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'ソロモン王乃ちヱホバを指て誓ひていふ神我に斯なし又重ねて斯なしたまへアドニヤは其身の生命を喪はんとて此言を言いだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, '我を立てわが父ダビデの位に上しめ其約せしごとく我に家を建たまひしヱホバは生くアドニヤは今日戮さるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'ソロモン王ヱホヤダの子ベナヤを遣はしければ彼アドニヤを撃て死しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, '王また祭司アビヤタルにいひけるは汝の故田アナトテにいたれ汝は死に當る者なれども嚮にわが父ダビデのまへに神ヱホバの櫃を舁き又凡てわが父の艱難を受たる處にて汝も艱難を受たれば我今日は汝を戮さじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'ソロモン、アビヤタルを逐いだしてヱホバの祭司たらしめざりき斯ヱホバがシロにてエリの家につきて言たまひし言應たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, '爰に其風聞ヨアブに達りければヨアブ、ヱホバの幕屋に遁れて壇の角を執たり其はヨアブは轉てアブサロムには隨はざりしかどもアドニヤに隨ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'ヨアブがヱホバの幕屋に遁れて壇の傍に居ることソロモンに聞えければソロモン、ヱホヤダの子ベナヤを遣はしいひけるは往て彼を撃てと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'ベナヤ乃ちヱホバの幕屋にいたり彼にいひけるは王斯言ふ出來れ彼いひけるは否我は此に死んとベナヤ反て王に告てヨアブ斯言ひ斯我に答へたりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, '王ベナヤにいひけるは彼が言ふごとく爲し彼を撃て葬りヨアブが故なくして流したる血を我とわが父の家より除去べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, '又ヱホバはヨアブの血を其身の首に歸したまふべし其は彼は己よりも義く且善りし二の人を撃ち劍をもてこれを殺したればなり即ちイスラエルの軍の長ネルの子アブネルとユダの軍の長ヱテルの子アマサを殺せり然るに吾父ダビデは與り知ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'されば彼等の血は長久にヨアブの首と其苗裔の首に皈すべし然どダビデと其苗裔と其家と其位にはヱホバよりの平安永久にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'ヱホヤダの子ベナヤすなはち上りて彼を撃ち彼を殺せり彼は野にある己の家に葬らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, '王乃ちヱホヤダの子ベナヤをヨアブに代て軍の長となせり王また祭司ザドクをしてアビヤタルに代しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, '又王人を遣てシメイを召て之に曰けるはエルサレムに於て汝の爲に家を建て其處に住み其處より此にも彼にも出るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, '汝が出てキデロン川を濟る日には汝確に知れ汝必ず戮さるべし汝の血は汝の首に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'シメイ王にいひけるは此言は善し王わが主の言たまへるごとく僕然なすべしと斯シメイ日久しくエルサレムに住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, '三年の後シメイの二人の僕ガテの王マアカの子アキシの所に逃されり人々シメイに告ていふ視よ汝の僕はガテにありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'シメイ乃ち起て其驢馬に鞍置きガテに往てアキシに至り其僕を尋ねたり即ちシメイ往て其僕をガテより携來りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'シメイのエルサレムよりガテにゆきて歸しことソロモンに聞えければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, '王人を遣てシメイを召て之にいひけるは我汝をしてヱホバを指て誓しめ且汝を戒めて汝確に知れ汝が出て此彼に歩く日には汝必ず戮さるべしと言しにあらずや又汝は我に我聞る言葉は善しといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'しかるに汝なんぞヱホバの誓とわが汝に命じたる命令を守ざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, '王又シメイにいひけるは汝は凡て汝の心の知る諸の惡即ち汝がわが父ダビデに爲たる所を知るヱホバ汝の惡を汝の首に歸したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'されどソロモン王は福祉を蒙らんまたダビデの位は永久にヱホバのまへに固く立べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, '王ヱホヤダの子ベナヤに命じければ彼出てシメイを撃ちて死しめたりしかして國はソロモンの手に固く立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'ソロモン、エジプトの王パロと縁を結びパロの女を娶て之を携來り自己の家とヱホバの家とエルサレムの周圍の石垣を建築ことを終るまでダビデの城に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, '當時までヱホバの名のために建たる家なかりければ民は崇邱にて祭を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'ソロモン、ヱホバを愛し其父ダビデの法憲に歩めり但し彼は崇邱にて祭を爲し香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, '爰に王ギベオンに往て其處に祭を爲んとせり其は彼處は大なる崇邱なればなり即ちソロモン一千の燔祭を其壇に献たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'ギベオンにてヱホバ夜の夢にソロモンに顯れたまへり神いひたまひけるは我何を汝に與ふべきか汝求めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'ソロモンいひけるは汝は汝の僕わが父ダビデが誠實と公義と正心を以て汝と共に汝の前に歩みしに囚て大なる恩惠を彼に示したまへり又汝彼のために此大なる恩惠を存て今日のごとくかれの位に坐する子を彼に賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'わが神ヱホバ汝は僕をして我父ダビデに代て王とならしめたまへり而るに我は小き子にして出入することを知ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, '且僕は汝の選みたまひし汝の民の中にあり即ち大なる民にて其數衆くして數ふることも書すことも能はざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, '是故に聽き別る心を僕に與へて汝の民を鞫しめ我をして善惡を辨別ることを得さしめたまへ誰か汝の此夥多き民を鞫くことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'ソロモン此事を求めければ其言主の心にかなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, '是において神かれにいひたまひけるは汝此事を求めて己の爲に長壽を求めず又己のために富有をも求めず又己の敵の生命をも求めずして惟訟を聽き別る才智を求めたるに因て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, '視よ我汝の言に循ひて爲り我汝に賢明く聡慧き心を與ふれば汝の先には汝の如き者なく汝の後にも汝の如き者興らざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, '我亦汝の求めざる者即ち富と貴とをも汝に與ふれば汝の生の涯王等の中に汝の如き者あらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, '又汝若汝の父ダビデの歩し如く吾道に歩みてわが法憲と命令を守らば我汝の日を長うせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'ソロモン目寤て視るに夢なりき斯てソロモン、エルサレムに至りヱホバの契約の櫃の前に立ち燔祭を献げ酬恩祭を爲して其諸の臣僕に饗宴を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, '爰に娼妓なる二人の婦王の所に來りて其前に立ちしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, '一人の婦いひけるはわが主よ我と此婦は一の家に住む我此婦と偕に家にありて子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'しかるにわが生し後第三日に此婦もまた生りしかして我儕偕にありき家には他人の我らと偕に居りし者なし家には只我儕二人のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, '然るに此婦其子の上に臥たるによりて夜の中に其子死たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, '中夜に起て婢の眠れる間にわが子をわれの側より取りて之を己の懐に臥しめ己の死たる子をわが懐に臥しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, '朝に及びて我わが子に乳を飮せんとて興て見るに死ゐたり我朝にいたりて其を熟く視たるに其はわが生るわが子にはあらざりしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, '今一人の婦いふ否活るはわが子死るは汝の子なりと此婦いふ否死るは汝の子活るはわが子なりと彼等斯王のまへに論り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, '時に王いひけるは一人は此活るはわが子死るは汝の子なりと言ひ又一人は否死るは汝の子活るはわが子なりといふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, '王乃ち劍を我に持來れといひければ劍を王の前に持來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, '王いひけるは活る子を二に分て其半を此に半を彼に與へよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, '時に其活子の母なる婦人心其子のために焚がごとくなりて王に言していひけるは請ふわが主よ活る子を彼に與へたまへ必ず殺したまふなかれと然ども他の一人は是を我のにも汝のにもならしめず判たせよと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, '王答ていひけるは活子を彼に與へよ必ず殺すなかれ彼は其母なるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'イスラエル皆王の審理し所の判決を聞て王を畏れたり其は神の智慧の彼の中にありて審理を爲しむるを見たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'ソロモン王はイスラエルの全地に王たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, '其有る群卿は左の如しザドクの子アザリヤは相國');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'シシヤの子エリホレフとアヒヤは書記官アヒルデの子ヨシヤパテは史官');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'ヱホヤダの子ベナヤは軍の長ザドクとアビヤタルは祭司');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'ナタンの子アザリヤは代官の長ナタンの子ザブデは大臣にして王の友たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'アヒシヤルは宮内卿アブダの子アドニラムは徴募長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'ソロモン又イスラエルの全地に十二の代官を置り其人々王と其家のために食物を備へたり即ち各一年に一月宛食物を備へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, '其名左のごとしエフライムの山地にはベンホル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'マカヅとシヤラビムとベテシメシとエロンベテハナンにはベンデケル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'アルポテにはベンヘセデありシヨコとヘベルの全地とは彼擔任り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'ドルの高地の全部にはベンアヒナダブあり彼はソロモンの女タパテを妻とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'アルヒデの子バアナはタアナクとメギドとヱズレルの下にザルタナの邊にあるベテシヤンの全地とを擔任てベテシヤンよりアベルメホラにいたりヨクネアムの外にまで及ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'ギレアデのラモテにはベンゲベルあり彼はギレアデにあるマナセの子ヤイルの諸村を擔任ち又バシヤンなるアルゴブの地にある石垣と銅の關を有る大なる城六十を擔任り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'イドの子アヒナダブはマハナイムを擔任り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'ナフタリにはアヒマアズあり彼もソロモンの女バスマテを妻に娶れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'アセルとアロテにはホシヤイの子バアナあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'イツサカルにはパルアの子ヨシヤパテあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'ベニヤミンにはエラの子シメイあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'アモリ人の王シホンの地およびバシヤンの王オグの地なるギレアデの地にはウリの子ゲベルあり其地にありし代官は唯彼一人のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'ユダとイスラエルの人は多くして濱の沙の多きがごとくなりしが飮食して樂めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'ソロモンは河よりペリシテ人の地にいたるまでとエジプトの境に及ぶまでの諸國を治めたれば皆禮物を餽りてソロモンの一生の間事へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, '偖ソロモンの一日の食物は細麺三十石粗麺六十石');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, '肥牛十牧場の牛二十羊一百其外に牡鹿羚羊小鹿および肥たる禽あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, '其はソロモン河の此方をテフサよりガザまで盡く治めたればなり即ち河の此方の諸王を悉く統治たり彼は四方の臣僕より平安を得たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'ソロモンの一生の間ユダとイスラエルはダンよりベエルシバに至るまで安然に各其葡萄樹の下と無花果樹の下に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'ソロモン戰車の馬の厩四千騎兵一萬二千を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, '彼代官等各其月にソロモン王のためおよび總てソロモン王の席に來る者の爲に食を備へて缺るとこるなからしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, '又彼等各其職に循ひて馬および疾足の馬に食する大麥と蒭蕘を其馬の在る處に携へ來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, '神ソロモンに智慧と聰明を甚だ多く賜ひ又廣大き心を賜ふ海濱の沙のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'ソロモンの智慧は東洋の人々の智慧とエジプトの諸の智慧よりも大なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, '彼は凡の人よりも賢くエズラ人エタンよりも又マホルの子なるヘマンとカルコルおよびダルダよりも賢くして其名四方の諸國に聞えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, '彼箴言三千を説り又其詩歌は一千五首あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, '彼又草木の事を論じてレバノンの香柏より墻に生る苔に迄及べり彼亦獣と鳥と匐行物と魚の事を論じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, '諸の國の人々ソロモンの智慧を聽んとて來り天下の諸の王ソロモンの智慧を聞及びて人を遣はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'ツロの王ヒラム、ソロモンの膏そそがれて其父にかはりて王となりしを聞て其臣僕をソロモンに遣せりヒラムは恒にダビデを愛したる者なりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, '是に於てソロモン、ヒラムに言遣はしけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, '汝の知ごとく我父ダビデは其周圍にありし戰爭に因て其神ヱホバの名のために家を建ること能はずしてヱホバが彼等を其足の跖の下に置またふを待り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, '然るに今わが神ヱホバ我に四方の太平を賜ひて敵もなく殃もなければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, '我はヱホバのわが父ダビデに語てわが汝の代に汝の位に上しむる汝の子其人はわが名のために家を建べしと言たまひしに循ひてわが神ヱホバの名のために家を建んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'されば汝命じてわがためにレバノンより香柏を砍出さしめよわが僕汝の僕と共にあるべし又我は凡て汝の言ふごとく汝の僕の賃銀を汝に付すべし其は汝の知ごとく我儕の中にはシドン人の如く木を砍に巧みなる人なければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'ヒラム、ソロモンの言を聞て大に喜び言けるは今日ヱホバに稱譽あれヱホバ、ダビデに此夥多しき民を治むる賢き子を與たまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'かくてヒラム、ソロモンに言遣りけるは我汝が言ひ遣したる所の事を聽り我香柏の材木と松樹の材木とに付ては凡て汝の望むごとく爲すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'わが僕レバノンより海に持下らんしかして我これを海より桴にくみて汝が我に言ひ遣す處におくり其處にて之をくづすべし汝之を受よ又汝はわが家のために食物を與へてわが望を成せと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, '斯てヒラムはソロモンに其凡て望むごとく香柏の材木と松の材木を與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, '又ソロモンはヒラムに其家の食物として小麥二萬石を與へまた清油二十石をあたへたり斯ソロモン年々ヒラムに與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'ヱホバ其言たまひしごとくソロモンに智慧を賜へりまたヒラムとソロモンの間睦しくして二人偕に契約を結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, '爰にソロモン王イスラエルの全地に徴募人を興せり其徴募人の數は三萬人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'ソロモンかれらを一月交代に一萬人づつレバノンに遣せり即ち彼等は一月レバノンに二月家にありアドニラムは徴募人の督者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'ソロモン負載者七萬人山に於て石を砍る者八萬人あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, '外に又其工事の長なる官吏三千三百人ありて工事に作く民を統たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'かくて王命じて大なる石貴き石を鑿出さしめ琢石を以て家の基礎を築かしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'ソロモンの建築者とヒラムの建築者およびゲバル人之を砍り斯彼等材木と石を家を建るに備へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'イスラエルの子孫のエジプトの地を出たる後四百八十年ソロモンのイスラエルに王たる第四年ジフの月即ち二月にソロモン、ヱホバのために家を建ることを始めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'ソロモン王のヱホバの爲に建たる家は長六十キユビト濶二十キユビト高三十キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, '家の拝殿の廊は家の濶に循ひて長二十キユビト家の前の其濶十キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, '彼家に造り附の格子ある窻を施たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, '又家の墻壁に附て四周に連接屋を建て家の墻壁即ち拝殿と神殿の墻壁の周圍に環らせり又四周に旁房を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, '下層の連接屋は濶五キユビト中層のは濶六キユビトを第三層のは濶七キユビトなり即ち家の外に階級を造り環らして何者をも家の墻壁に挿入ざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, '家は建る時に鑿石所にて鑿り預備たる石にて造りたれば造れる間に家の中には鎚も鑿も其外の鐵器も聞えざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, '中層の旁房の戸は家の右の方にあり螺旋梯より中層の房にのぼり中層の房より第三層の房にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, '斯彼家を建終り香柏の橡と板をもて家を葺り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, '又家に附て五キユビトの高たる連接屋を建環し香柏をもて家に交接たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, '爰にヱホバの言ソロモンに臨みて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '汝今此家を建つ若し汝わが法憲に歩みわが律例を行ひわが諸の誡命を守りて之にしたがひて歩まばわれはが汝の父ダビデに言し語を汝に固うすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, '我イスラエルの子孫の中に住わが民イスラエルを棄ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, '斯ソロモン家を建終れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, '彼香柏の板を以て家の墻壁の裏面を作れり即ち家の牀板より頂格の墻壁まで木をもて其裏面をはりまた松の板をもて家の牀板をはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, '又家の奧に二十キユビトの室を牀板より墻壁まで香柏をもて造れり即ち家の内に至聖所なる神殿を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, '家即ち前にある拝殿は四十キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, '家の内の香柏は瓠と咲る花を雕刻める者なり皆香柏にして石は見えざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, '神殿は彼其處にヱホバの契約の櫃を置んとて家の内の中に設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, '神殿の内は長二十キユビト濶二十キユビト高二十キユビトなり純金をもて之を蔽ひ又香柏の壇を覆へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, '又ソロモン純金をもて家の内を蔽ひ神殿の前に金の鏈をもて間隔を造り金をもて之を蔽へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, '又金をもて殘るところなく家を蔽ひ遂に家を飾ることを悉く終たりまた神殿の傍にある壇は皆金をもて蔽へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, '神殿の内に橄欖の木をもて二のケルビムを造れり其高十キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, '其ケルブの一の翼は五キユビト又其ケルブの他の翼も五キユビトなり一の翼の末より他の翼の末までは十キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, '他のケルブも十キユビトなり其ケルビムは偕に同量同形なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, '此ケルブの高十キユビト彼ケルブも亦しかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'ソロモン家の内の中にケルビムを置ゑケルビムの翼を展しければ此ケルブの翼は此墻壁に及び彼ケルブの翼は彼の墻壁に及びて其兩翼家の中にて相接れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, '彼金をもてケルビムを蔽へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, '家の周圍の墻壁には皆内外ともにケルビムと棕櫚と咲る花の形を雕み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, '家の牀板には内外ともに金を蔽へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, '神殿の入口には橄欖の木の戸を造れり其木匡の門柱は五分の一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, '其二の扉も亦橄欖の木なりソロモン其上にケルビムと棕櫚と咲る花の形を雕刻み金をもて蔽へり即ちケルビムと棕櫚の上に金を鍍たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, '斯ソロモン亦拝殿の戸のために橄欖の木の門柱を造れり即ち四分の一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, '其二の戸は松の木にして此戸の兩扉は摺むべく彼戸の兩扉も摺むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'ソロモン其上にケルビムと棕櫚と咲る花を雕刻み金をもてこれを蔽ひて善く其雕工に適はしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'また鑿石三層と香柏の厚板一層をもて内庭を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, '第四年のジフの月にヱホバの家の基礎を築き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, '第十一年のブルの月即ち八月に凡て其箇條のごとく其定例のごとくに家成りぬ斯ソロモン之に建るに七年を渉れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'ソロモン己の家を建しが十三年を經て全く其家を建終たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, '彼レバノン森の家を建たり其長は百キユビト其濶は五十キユビト其高は三十キユビトなり香柏の柱四行ありて柱の上に香柏の梁あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, '四十五本の柱の上なる梁の上は香柏にて蓋へり柱は一行に十五本あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'また窻三行ありて牖と牖と三段に相對ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, '戸と戸柱は皆大木をもて角に造り牖と牖と三段に相對へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, '又柱の廊を造れり其長五十キユビト其濶三十キユビトなり柱のまへに一の廊ありまた其柱のまへに柱と階あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, '又ソロモン審判を爲すために位の廊即ち審判の廊を造り牀板より牀板まで香柏をもて蔽へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'ソロモンの居住る家は其廊の後の他の庭にありて其工作同じかりきソロモン亦其娶りたるパロの女のために家を建しが此廊に同じかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, '是等は内外とも基礎より檐にいたるまで又外面にては大庭にいたるまで皆鑿石の量にしたがひて鋸にて剖たる貴き石をもて造れるものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, '又基礎は貴き石大なる石即ち十キユビトの石八キユビトの石なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, '其上には鑿石の量に循ひて貴き石と香柏あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, '又大庭の周圍にに三層の鑿石と一層の香柏の厚板ありヱホバの家の内庭と家の廊におけるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, '爰にソロモン人を遣はしてヒラムをツロより召び來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, '彼はナフタリの支派なる嫠婦の子にして其父はツロの人にて銅の細工人なりヒラムは銅の諸の細工を爲すの智慧と慧悟と知識の充ちたる者なりしがソロモン王の所に來りて其諸の細工を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, '彼銅の柱二を鋳たり其高各十八キユビトにして各十二キユビトの繩を環らすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, '又銅を鎔して柱頭を鋳て柱の顛に置ゆ此の頭の高も五キユビト彼の頭の高も五キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, '柱の上にある頭の爲に組物の網と鏈樣の槎物を造れり此頭に七つ彼頭に七つあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, '又二行の石榴を一の網工の上の四周に造りて柱の上にある頭を蓋ふ他の頭をも亦然せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, '柱の上にある頭は四キユビトの百合花の形にして廊におけるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, '二の柱の頭の上には亦網工の外なる腹の所に接きて石榴あり他の柱の四周にも石榴二百ありて相列べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, '此柱を拝殿の廊に竪つ即ち右の柱を立て其名をヤキンと名け左の柱を竪て其名をボアズと名く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, '其柱の上に百合花の形あり斯其柱の作成り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, '又海を鋳なせり此邊より彼邊まで十キユビトにして其四周圓く其高五キユビトなり其四周は三十キユビトの繩を環らすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, '其邊の下には四周に匏瓜ありて之を環れり即ち一キユビトに十づつありて海の周圍を圍り其匏瓜は海を鋳たる時に二行に鋳たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, '其海は十二の牛の上に立り其三は北に向ひ三は西に向ひ三は南に向ひ三は東に向ふ海其上にありて牛の後は皆内に向ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, '海の厚は手寛にして其邊は百合花にて杯の邊の如くに作れり海は二千斗を容たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, '又銅の臺十を造れり一の臺の長四キユビト其濶四キユビト其高三キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, '其臺の製作は左のごとし臺には嵌板あり嵌板は邊の中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, '邊の中にある嵌板の上に獅子と牛とケルビムあり又邊の上に座あり獅子と牛の下に花飾の垂下物あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, '其臺には各四の銅の輪と銅の軸あり其四の足には肩のごとき者あり其肩のごとき者は洗盤の下にありて凡の花飾の旁に鋳つけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, '其口は頭の内より上は一キユビトなり其口は圓く一キユビト半にして座の作の如し又其口には雕工あり其鏡板は四角にして圓からず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, '四の輪は鏡板の下にあり輪の手は臺の中にあり輪は各高一キュビト半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, '輪の工作は戰車の輪の工作の如し其手と縁と輻と轂とは皆鋳物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, '臺の四隅に四の肩の如き者あり其肩のごとき者は臺より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, '臺の上の所の高半キユビトは其周圍圓し又臺の上の所の手と鏡板も臺より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, '其手の板と鏡板には其各の隙處に循ひてケルビムと獅子と棕櫚を雕刻み又其四周に花飾を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, '是のごとく十の臺を造れり其鋳法と量と形は皆同じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, '又銅の洗盤十を造れり洗盤は各四十斗を容れ洗盤は各四キユビトなり十の臺の上には各一の洗盤あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, '其臺五を家の右の旁に五を家の左の旁に置ゑ家の右の東南に其海を置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'ヒラム又鍋と火鏟と鉢とを造れり斯ヒラム、ヱホバの家の爲にソロモン王に爲る諸の細工を成終たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, '即ち二の往と其柱の上なる頭の二の毬と柱の上なる其頭の二の毬を蓋ふ二の網工と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, '其二の網工の爲の石榴四百是は一の網工に石榴二行ありて柱の上なる二の毬を蓋ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, '又十の臺と其臺の上の十の洗盤と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, '一の海と其海の下の十二の牛');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, '及び鍋と火鏟と鉢是也ヒラムがソロモン王にヱホバの家のために造りし此等の器は皆光明ある銅なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, '王ヨルダンの低地に於てスコテとザレタンの間の粘土の地にて之を鋳たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'ソロモン其器甚だしく多かりければ皆權ずに措り其銅の重しれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, '又ソロモン、ヱホバの家の諸の器を造れり即ち金の壇と供前のパンを載る金の案');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'および純金の燈臺是は神殿のまへに五は右に五は左にあり又金の花と燈盞と燈鉗と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, '純金の盆と剪刀と鉢と皿と滅燈器と至聖所なる内の家の戸のため及び拝殿なる家の戸のためなる金の肘鈕是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, '斯ソロモン王のヱホバの家のために爲る諸の細工終れり是においてソロモン其父ダビデが奉納めたる物即ち金銀および器を携へいりてヱホバの家の寳物の中に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, '爰にソロモン、ヱホバの契約の櫃をダビデの城即ちシオンより舁上らんとてイスラエルの長老と諸の支派の首イスラエルの子孫の家の長等をエルサレムにてソロモン王の所に召集む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'イスラエルの人皆エタニムの月即ち七月の節筵に當てソロモン王の所に集まれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'イスラエルの長老皆至り祭司櫃を執りあげて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'ヱホバの櫃と集會の幕屋と幕屋にありし諸の聖き器を舁上れり即ち祭司とレビの人之を舁のぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'ソロモン王および其許に集れるイスラエルの會衆皆彼と偕に櫃の前にありて羊と牛を献げたりしが其數多くして書すことも數ふることも能はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, '祭司ヱホバの契約の櫃を其處に舁いれたり即ち家の神殿なる至聖所の中のケルビムの翼の下に置めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'ケルビムは翼を櫃の所に舒べ且ケルビム上より櫃と其棹を掩へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, '杠長かりければ杠の末は神殿の前の聖所より見えたり然ども外には見えざりき其杠は今日まで彼處にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, '櫃の内には二の石牌の外何もあらざりき是はイスラエルの子孫のエジプトの地より出たる時ヱホバの彼等と契約を結たまへる時にモーセがホレブにて其處に置めたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, '斯て祭司聖所より出けるに雲ヱホバの家に盈たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, '祭司は雲のために立て供事ること能はざりき其はヱホバの榮光ヱホバの家に盈たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, '是においてソロモンいひけるはヱホバは濃き雲の中に居んといひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, '我誠に汝のために住むべき家永久に居べき所を建たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, '王其面を轉てイスラエルの凡の會衆を祝せり時にイスラエルの會衆は皆立ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, '彼言けるはイスラエルの神ヱホバは譽べきかなヱホバは其口をもて吾父ダビデに言ひ其手をもて之を成し遂げたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '即ち我は吾民イスラエルをエジプトより導き出せし日より我名を置べき家を建しめんためにイスラエルの諸の支派の中より何れの城邑をも選みしことなし但ダビデを選みてわが民イスラエルの上に立しめたりと言たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, '夫イスラエルの神ヱホバの名のために家を建ることはわが父ダビデの心にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'しかるにヱホバわが父ダビデにいひたまひけるはわが名のために家を建ること汝の心にあり汝の心に此事あるは善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, '然ども汝は其家を建べからず汝の腰より出る汝の子其人吾名のために家を建べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, '而してヱホバ其言たまひし言を行ひたまへり即ち我わが父ダビデに代りて立ちヱホバの言たまひし如くイスラエルの位に坐しイスラエルの神ヱホバの名のために家を建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, '我又其處にヱホバの契約を蔵めたる櫃のために一の所を設けたり即ち我儕の父祖をエジプトの地より導き出したまひし時に彼等に爲したまひし者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'ソロモン、イスラエルの凡の會衆の前にてヱホバの壇のまへに立ち其手を天に舒て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, '言けるはイスラエルの神ヱホバよ上の天にも下の地にも汝の如き神なし汝は契約を持ちたまひ心を全うして汝のまへに歩むところの汝の僕等に恩惠を施したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, '汝は汝の僕わが父ダビデに語たまへる所を持ちたまへり汝は口をもて語ひ手をもて成し遂たまへること今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'イスラエルの神ヱホバよ然ば汝が僕わが父ダビデに語りて若し汝の子孫其道を愼みて汝がわが前に歩めるごとくわが前に歩まばイスラエルの位に坐する人わがまへにて汝に缺ること無るべしといひたまひし事をダビデのために持ちたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, '然ばイスラエルの神よ爾が僕わが父ダビデに言たまへる爾の言に效驗あらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, '神果して地の上に住たまふや視よ天も諸の天の天も爾を容るに足ず况て我が建たる此家をや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, '然どもわが神ヱホバよ僕の祈祷と懇願を顧みて其號呼と僕が今日爾のまへに祈る祈祷を聽たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, '願くは爾の目を夜晝此家に即ち爾が我名は彼處に在べしといひたまへる處に向ひて開きたまへ願くは僕の此處に向ひて祈らん祈祷を聽たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, '願くは僕と爾の民イスラエルが此處に向ひて祈る時に爾其懇願を聽たまへ爾は爾の居處なる天において聽き聽て赦したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, '若し人其隣人に對ひて犯せることありて其人誓をもて誓ふことを要られんに來りて此家において爾の壇のまへに誓ひなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, '爾天において聽て行ひ爾の僕等を鞫き惡き者を罪して其道を其首に歸し義しき者を義として其義に循ひて之に報いたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, '若爾の民イスラエル爾に罪を犯したるがために敵の前に敗られんに爾に歸りて爾の名を崇め此家にて爾に祈り願ひなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, '爾天において聽き爾の民イスラエルの罪を赦して彼等を爾が其父祖に與へし地に歸らしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, '若彼等が爾に罪を犯したるが爲に天閉て雨无らんに彼等若此處にむかひて祈り爾の名を崇め爾が彼等を苦めたまふときに其罪を離れなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, '爾天において聽き爾の僕等爾の民イスラエルの罪を赦したまへ爾彼等に其歩むべき善道を敎へたまふ時は爾が爾の民に與へて產業となさしめたまひし爾の地に雨を降したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, '若國に饑饉あるか若くは疫病枯死朽腐噬亡ぼす蝗蟲あるか若くは其敵國にいりて彼等を其門に圍むか如何なる災害如何なる病疾あるも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, '若一人か或は爾の民イスラエル皆各己の心の災を知て此家に向ひて手を舒なば其人如何なる祈祷如何なる懇願を爲とも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, '爾の居處なる天に於て聽て赦し行ひ各の人に其心を知給ふ如く其道々にしたがひて報い給へ其は爾のみ凡の人の心を知たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, '爾かく彼等をして爾が彼等の父祖に與へたまへる地に居る日に常に爾を畏れしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, '且又爾の民イスラエルの者にあらずして爾の名のために遠き國より來る異邦人は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(其は彼等爾の大なる名と強き手と伸たる腕を聞およぶべければなり)若來りて此家にむかひて祈らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, '爾の居處なる天に於て聽き凡て異邦人の爾に龥求むる如く爲たまへ爾かく地の諸の民をして爾の名をしらしめ爾の民イスラエルのごとく爾を畏れしめ又我が建たる此家は爾の名をもて稱呼るるといふことを知しめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, '爾の民其敵と戰はんとて爾の遣はしたまふ所に出たる時彼等若爾が選みたまへる城とわが爾の名のために建たる家の方に向ひてヱホバに祈らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, '爾天において彼等の祈祷と懇願を聽て彼等を助けたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, '人は罪を犯さざる者なければ彼等爾に罪を犯すことありて爾彼等を怒り彼等を其敵に付し敵かれらを虜として遠近を諭ず敵の地に引ゆかん時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, '若彼等虜れゆきし地において自ら顧みて悔い己を虜へゆきし者の地にて爾に願ひて我儕罪を犯し悖れる事を爲たり我儕惡を行ひたりと言ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, '己を虜ゆきし敵の地にて一心一念に爾に歸り爾が其父祖に與へたまへる地爾が選みたまへる城とわが爾の名のために建たる家の方に向ひて爾に祈らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, '爾の居處なる天において爾彼等の祈祷と懇願を聽てかれらを助け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, '爾の民の爾に對て犯したる事と爾に對て過てる其凡の罪過を赦し彼等を虜ゆける者の前にて彼等に憐を得させ其人々をして彼等を憐ましめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, '其は彼等は爾がエジプトより即ち鐵の鑪の中よりいだしたまひし爾の民爾の產業なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, '願くは僕の祈祷と爾の民イスラエルの祈願に爾の目を開きて凡て其爾に龥求むる所を聽たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, '其は爾彼等を地の凡の民の中より別ちて爾の產業となしたまへばなり神ヱホバ爾が我儕の父祖をエジプトより導き出せし時モーセによりて言給ひし如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'ソロモン此祈祷と祈願を悉くヱホバに祈り終りし時其天にむかひて手を舒べ膝を屈居たるを止てヱホバの壇のまへより起あがり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, '立て大なる聲にてイスラエルの凡の會衆を祝して言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'ヱホバは譽べきかなヱホバは凡て其言たまひし如く其民イスラエルに太平を與へたまへり其僕モーセによりて言たまひし其善言は皆一も違はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, '願くは我儕の神ヱホバ我儕の父祖と偕に在せしごとく我儕とともに在せ我儕を離れたまふなかれ我儕を棄たまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, '願くは我儕の心をおのれに傾けたまひて其凡の道に歩ましめ其我儕の父祖に命じたまひし誡命と法憲と律例を守らしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, '願くはヱホバの前にわが願し是等の言日夜われらの神ヱホバに近くあれ而してヱホバ日々の事に僕を助け其民イスラエルを助けたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, '斯して地の諸の民にヱホバの神なることと他に神なきことを知しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'されば爾等我儕の神ヱホバとともにありて今日の如く爾らの心を完全しヱホバの法憲に歩み其誡命を守るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, '斯て王および王と偕にありしイスラエル皆ヱホバのまへに犠牲を献たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'ソロモン酬恩祭の犠牲を献げたり即ち之をヱホバに献ぐ其牛二萬二千羊十二萬なりき斯王とイスラエルの子孫皆ヱホバの家を開けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, '其日に王ヱホバの家の前なる庭の中を聖別め其處にて燔祭と禴祭と酬恩祭の脂とを献げたり是はヱホバの前なる銅の壇小くして燔祭と禴祭と酬恩祭の脂とを受るにたらざりしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, '其時ソロモン七日に七日合て十四日我儕の神ヱホバのまへに節筵を爲りイスラエルの大なる會衆ハマテの入處よりエジプトの河にいたるまで悉く彼と偕にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, '第八日にソロモン民を歸せり民は王を祝しヱホバが其僕ダビデと其民イスラエルに施したまひし諸の恩惠のために喜び且心に樂みて其天幕に往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'ソロモン、ヱホバの家と王の家を建る事を終へ且凡てソロモンが爲んと欲し望を遂し時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'ヱホバ再ソロモンに甞てギベオンにて顯現たまひし如くあらはれたまひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, '彼に言たまひけるは我は爾が我まへに願し祈祷と祈願を聽たり我爾が建たる此家を聖別てわが名を永く其處に置べし且わが目とわが心は恒に其處にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, '爾若爾の父ダビデの歩みし如く心を完うして正しく我前に歩みわが爾に命じたる如く凡て行ひてわが憲法と律例を守らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, '我は爾の父ダビデに告てイスラエルの位に上る人爾に缺ること無るべしと言しごとく爾のイスラエルに王たる位を固うすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, '若爾等又は爾等の子孫全く轉きて我にしたがはずわが爾等のまへに置たるわが誡命と法憲を守らずして往て他の神に事へ之を拝まば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, '我イスラエルをわが與へたる地の面より絶ん又わが名のために我が聖別たる此家をば我わがまへより投げ棄んしかしてイスラエルは諸の民の中に諺語となり嘲笑となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, '且又此家は高くあれども其傍を過る者は皆之に驚き嘶きて言んヱホバ何故に此地に此家に斯爲たまひしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, '人答へて彼等は己の父祖をエジプトの地より導き出せし其神ヱホバを棄て他の神に附從ひ之を拝み之に事へしに因てヱホバ此の凡の害惡を其上に降せるなりと言ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'ソロモン二十年を經て二の家即ちヱホバの家と王の家を建をはりヒウムにガリラヤの地の城邑二十を與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '其はツロの王ヒラムはソロモンに凡て其望に循ひて香柏と松の木と金を供給たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'ヒラム、ツロより出てソロモンが己に與へたる諸邑を見しに其目に善らざりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, '我兄第よ爾が我に與へたる此等の城邑は何なるやといひて之をカブルの地となづけたり其名今日までのこる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, '甞てヒラムは金百二十タラントを王に遣れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'ソロモン王の徴募人を興せし事は是なり即ちヱホバの家と自己の家とミロとエルサレムの石垣とハゾルとメギドンとゲゼルを建んが爲なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'エジプトの王パロ嘗て上りてゲゼルを取り火を以て之を燬き其邑に住るカナン人を殺し之をソロモンの妻なる其女に與へて粧奩と爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'ソロモン、ゲゼルと下ベテホロンと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'バアラと國の野にあるタデモル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, '及びソロモンの有てる府庫の諸邑其戰車の諸邑其騎兵の諸邑並にソロモンがエルサレム、レバノンおよび其凡の領地に於て建んと欲し者を盡く建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, '凡てイスラエルの子孫に非るアモリ人ヘテ人ペリジ人ヒビ人ヱブス人の遺存る者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, '其地に在て彼等の後に遺存る子孫即ちイスラエルの子孫の滅し盡すことを得ざりし者にソロモン奴隸の徴募を行ひて今日に至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, '然どもイステエルの子孫をばソロモン一人も奴隸と爲ざりき其は彼等は軍人彼の臣僕牧伯大將たり戰車と騎兵の長たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'ソロモンの工事を管理れる首なる官吏は五百五十人にして工事に働く民を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, '爰にパロの女ダビデの城より上りてソロモンが彼のために建たる家に至る其時にソロモン、ミロを建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'ソロモン、ヱホバに築きたる壇の上に年に三次燔祭と酬恩祭を献げ又ヱホバの前なる壇に香を焚りソロモン斯家を全うせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'ソロモン王エドムの地紅海の濱に於てエラテの邊なるエジオンゲベルにて船數雙を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'ヒラム海の事を知れる舟人なる其僕をソロモンの僕と偕に其船にて遣せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, '彼等オフルに至り其處より金四百二十タラントを取てこれをソロモン王の所に携來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'シバの女王ヱホバの名に關るソロモンの風聞を聞き及び難問を以てソロモンを試みんとて來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, '彼甚だ多くの部從香物と甚だ多くの金と寶石を負ふ駱駝を從へてエルサレムに至る彼ソロモンの許に來り其心にある所を悉く之に言たるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'ソロモン彼に其凡の事を告たり王の知ずして彼に告ざる事無りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'シバの女王ソロモンの諸の智慧と其建たる家と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, '其席の食物と其臣僕の列坐る事と其侍臣の伺候および彼等の衣服と其酒人と其ヱホバの家に上る階級とを見て全く其氣を奪はれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, '彼王にいひけるは我が自己の國にて爾の行爲と爾の智慧に付て聞たる言は眞實なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, '然ど我來りて目に見るまでは其言を信ぜざりしが今視るに其半も我に聞えざりしなり爾の智慧と昌盛はわが聞たる風聞に越ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, '常に爾の前に立て爾の智慧を聽く是等の人爾の臣僕は幸福なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, '爾の神ヱホバは讃べきかなヱホバ爾を悦び爾をイスラエルの位に上らせたまへりヱホバ永久にイスラエルを愛したまふに因て爾を王となして公道と義を行はしめたまふなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, '彼乃ち金百二十タラント及び甚だ多くの香物と寶石とを王に饋れりシバの女王のソロモン王に饋りたるが如き多くの香物は重て至ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'オフルより金を載來りたるヒラムの船は亦オフルより多くの白檀木と寶石とを運び來りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, '王白檀木を以てヱホバの家と王の家とに欄干を造り歌謡者のために琴と瑟を造れり是の如き白檀木は至らざりき亦今日までも見たることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'ソロモン王王の例に循ひてシバの女王に物を饋りたる外に又彼が望に任せて凡て其求むる物を饋れり斯て彼其臣僕等とともに歸りて其國に往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, '偖一年にソロモンの所に至れる金の重量は六百六十六タラントなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, '外に又商買および商旅の交易並にアラビヤの王等と國の知事等よりも至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'ソロモン王展金の大楯二百を造れり其大楯には各六百シケルの金を用ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, '又展金の干三百を造れり一の干に三斤の金を用ひたり王是等をレバノン森林の家に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, '王又象牙をもて大なる寳座を造り純金を以て之を蔽へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, '其寳座に六の階級あり寳座の後に圓き頭あり坐する處の兩旁に扶手ありて扶手の側に二の獅子立てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, '又其六の階級に十二の獅子此旁彼旁に立り是の如き者を作れる國はあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'ソロモン王の用ひて飮る器は皆金なり又レバノン森林の家の器も皆純金にして銀の物無りき銀はソロモンの世には貴まざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, '其は王海にタルシシの船を有てヒラムの船と供にあらしめタルシシの船をして三年に一度金銀象牙猿猴および孔雀を載て來らしめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, '抑ソロモン王は富有と智慧に於て天下の諸の王よりも大なりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, '天下皆神がソロモンの心に授けたまへる智慧を聽んとてソロモンの面を見んことを求めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, '人々各其禮物を携へ來る即ち銀の器金の器衣服甲冑香物馬騾毎歳定分ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'ソロモン戰車と騎兵を集めたるに戰車千四百輛騎兵壱萬二千ありきソロモン之を戰車の城邑に置き或はエルサレムにて王の所に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, '王エルサレムに於て銀を石の如くに爲し香柏を平地の桑樹の如くに爲して多く用ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'ソロモンの馬を獲たるはエジプトとコアよりなり即ち王の商賣コアより價値を以て取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'エジプトより上り出る戰車一輛は銀六百にして馬は百五十なりき斯のごとくヘテ人の凡の王等およびスリアの王等のために其手をもて取出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'ソロモン王パロの女の外に多の外國の婦を寵愛せり即ちモアブ人アンモニ人エドミ人シドン人ヘテ人の婦を寵愛せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'ヱホバ曾て是等の國民についてイスラエルの子孫に言たまひけらく爾等は彼等と交るべからず彼等も亦爾等と交るべからず彼等必ず爾等の心を轉して彼等の神々に從はしめんとしかるにソロモン彼等を愛して離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, '彼妃公主七百人嬪三百人あり其妃等彼の心を轉せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'ソロモンの年老たる時妃等其心を轉移して他の神に從はしめければ彼の心其父ダビデの心の如く其神ヱホバに全からざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, '其はソロモン、シドン人の神アシタロテに從ひアンモニ人の惡むべき者なるモロクに從ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'ソロモン斯ヱホバの目のまへに惡を行ひ其父ダビデの如く全くはヱホバに從はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, '爰にソロモン、モアブの憎むべき者なるケモシの爲又アンモンの子孫の憎むべき者なるモロクのためにエルサレムの前なる山に崇邱を築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, '彼又其異邦の凡の妃の爲にも然せしかば彼等は香を焚て己々の神を祭れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'ソロモンの心轉りてイスラエルの神ヱホバを離れしによりてヱホバ彼を怒りたまふヱホバ嘗て兩次彼に顯れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, '此事に付て彼に他の神に從ふべからずと命じたまひけるに彼ヱホバの命じたまひし事を守らざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'ヱホバ、ソロモンに言たまひけるは此事爾にありしに因り又汝わが契約とわが爾に命じたる法憲を守らざりしに因て我必ず爾より國を裂きはなして之を爾の臣僕に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, '然ど爾の父ダビデの爲に爾の世には之を爲ざるべし我爾の子の手より之を裂きはなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, '但し我は國を盡くは裂きはなさずしてわが僕ダビデのために又わが選みたるエルサレムのために一の支派を爾の子に與へんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, '是に於てヱホバ、エドミ人ハダデを興してソロモンの敵と爲したまふ彼はエドム王の裔なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, '曩にダビデ、エドムに事ありし時軍の長ヨアブ上りて其戰死せし者を葬りエドムの男を盡く撃殺しける時に方りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(ヨアブはエドムの男を盡く絶までイスラエルの群衆と偕に六月其處に止れり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'ハダデ其父の僕なる數人のエドミ人と共に逃てエジブトに往んとせり時にハダデは尚小童子なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, '彼等ミデアンを起出てバランに至りパランより人を伴ひてエジプトに往きエジプトの王パロに詣るにバロ彼に家を與へ食糧を定め且土地を與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'ハダデ大にパロの心にかなひしかばパロ己の妻の妹即ち王妃タペネスの妹を彼に妻せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'タペネスの妹彼に男子ゲヌバテを生ければタペネス之をパロの家の中にて乳離せしむゲヌバテ、パロの家にてパロの子の中にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'ハダデ、エジプトに在てダビデの其先祖と偕に寝りたると軍の長ヨアブの死たるを聞しかばハダデ、パロに言けるは我を去しめてわが國に往しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'パロ彼にいひけるは爾我とともにありて何の缺たる處ありてか爾の國に往ん事を求むる彼言ふ何も無し然どもねがはくは我を去しめよ去しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, '神父エリアダの子レゾンを興してソロモンの敵となせり彼は其主人ゾバの王ハダデゼルの許を逃さりたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'ダビデがゾバの人を殺したる時に彼人を自己に集めて一隊の首領となりしが彼等ダマスコに往て彼處に住みダマスコを治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'ハダデが爲たる害の外にレゾン、ソロモンの一生の間イスラエルの敵となれり彼イステエルを惡みてスリアに王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'ゼレダのヱフラタ人ネバテの子ヤラベアムはソロモンの僕なりしが其母の名はゼルヤと曰て嫠婦なりき彼も亦其手を擧て王に敵す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, '彼が手を擧て王に敵せし故は此なりソロモン、ミロを築き其父ダビデの城の損缺を塞ぎ居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, '其人ヤラベアムは大なる能力ある者なりしかばソロモン此少者が事に勤むるを見て之を立てヨセフの家の凡の役を督どらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, '其頃ヤラベアム、エルサレムを出し時シロ人なる預言者アヒヤ路にて彼に遭へり彼は新しき衣服を著ゐたりしが彼等二人のみ野にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'アヒヤ其著たる新しき衣服を執へて之を十二片に裂き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'ヤラベアムに言けるは爾自ら十片を取れイスラエルの神ヱホバ斯言たまふ視よ我國をソロモンの手より裂きはなして爾に十の支派を與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(但し彼はわが僕ダビデの故に因り又わがイスラエルの凡の支派の中より選みたる城エルサレムの故に因りて一の支派を有つべし)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, '其は彼等我を棄てシドン人の神アシタロテとモアブの神ケモシとアンモンの子孫の神モロクを拝み其父ダビデの如くわが道に歩てわが目に適ふ事わが法ととわが律例を行はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, '然ども我は國を盡くは彼の手より取ざるべし我が選みたるわが僕ダビデわが命令とわが法憲を守りたるに因て我彼が爲にソロモンを一生の間主たらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, '然ど我其子の手より國を取て其十の支派を爾に與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, '其子には我一の支派を與へてわが僕ダビデをしてわが己の名を置んとてわがために擇みたる城エルサレムにてわが前に常に一の光明を有しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, '我爾を取ん爾は凡て爾の心の望む所を治めイスラエルの上に王となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, '爾若わが爾に命ずる凡の事を聽て吾が道に歩みわが目に適ふ事を爲しわが僕ダビデが爲し如く我が法憲と誡命を守らば我爾と偕にありてわがダビデのために建しごとく爾のために鞏固き家を建てイスラエルを爾に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, '我之がためにダビデの裔を苦めんされど永遠には非じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'ソロモン、ヤラベアムを殺さんと求めければヤラベアム起てエジプトに逃遁れエジプトの王シシヤクに至りてソロモンの死ぬるまでエジプトに居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'ソロモンの其餘の行爲と凡て彼が爲たる事および其智慧はソロモンの行爲の書に記さるるにあらすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'ソロモンのエルサレムにてイスラエルの全地を治めたる日は四十年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'ソロモン其父祖と偕に寝りて其父ダビデの城に葬らる其子レハベアム之に代て王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, '爰にレハベアム、シケムに往り其はイスラエル皆彼を王と爲んとてシケムに至りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'ネバテの子ヤラベアム尚エジブトに在て聞りヤラベアムはソロモン王の面をさけて逃さりエジプトに住居たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, '時に人衆人を遣はして彼を招けり斯てヤラベアムとイスラエルの會衆皆來りてレハベアムに告て言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '汝の父我儕の軛を難くせり然ども爾今爾の父の難き役と爾の父の我儕に蒙らせたる重き軛を軽くせよ然ば我儕爾に事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'レハベアム彼等に言けるは去て三日を經て再び我に來れと民乃ち去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'レハベアム王其父ソロモンの生る間其前に立たる老人等と計りていひけるは爾等如何に敎へて此民に答へしむるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, '彼等レハベアムに告て言けるは爾若今日此民の僕となり之に事へて之に答へ善き言を之に語らば彼等永く爾の僕となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, '然に彼老人の敎へし敎を棄て自己と倶に生長て己のまへに立つ少年等と計れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, '即ち彼等に言けるは爾等何を敎へて我儕をして此我に告て爾の父の我儕に蒙むらせし軛を軽くせよと言ふ民に答へしむるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, '彼と偕に生長たる少年彼に告ていひけるは爾に告て爾の父我儕の軛を重くしたれど爾これを我儕のために軽くせよと言たる此民に爾斯言ベし我が小指はわが父の腰よりも太し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'またわが父爾等に重き軛を負せたりしが我は更に爾等の軛を重くせん我父は鞭にて爾等を懲したれども我は蠍をもて爾等を懲んと爾斯彼等に告べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'ヤラベアムと民皆王の告て第三日に再び我に來れと言しごとく第三日にレハベアムに詣りしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, '王荒々しく民に答へ老人の敎へし敎を棄て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, '少年の敎の如く彼等に告て言けるは我父は爾等の軛を重くしたりしが我は更に爾等の軛を重くせん我父は鞭を以て爾等を懲したれども我は蠍をもて爾等を懲さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, '王斯民に聽ざりき此事はヱホバより出たる者なり是はヱホバその甞てシロ人アヒヤに由てネバテの子ヤラベアムに告し言をおこなはんとて爲たまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'かくイスラエル皆王の己に聽ざるを見たり是において民王に答へて言けるは我儕ダビデの中に何の分あらんやヱサイの子の中に產業なしイスラエルよ爾等の天幕に歸れダビデよ今爾の家を視よと而してイスラエルは其天幕に去りゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, '然どもユダの諸邑に住るイスラエルの子孫の上にはレハベアム其王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'レハベアム王徴募頭なるアドラムを遣はしけるにイスラエル皆石にて彼を撃て死しめたればレハベアム王急ぎて其車に登りエルサレムに逃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, '斯イスラエル、ダビデの家に背きて今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, '爰にイスラエル皆ヤラベアムの歸りしを聞て人を遣して彼を集會に招き彼をイスラエルの全家の上に王と爲りユダの支派の外はダビデの家に從ふ者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'ソロモンの子レハベアム、エルサレムに至りてユダの全家とベニヤミンの支派の者即ち壯年の武夫十八萬を集む斯してレハベアム國を己に皈さんがためにイスラエルの家と戰はんとせしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, '神の言神の人シマヤに臨みて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'ソロモンの子ユダの王レハベアムおよびユダとベニヤミンの全家並に其餘の民に告て言べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'ヱホバ斯言ふ爾等上るべからず爾等の兄弟なるイスラエルの子孫と戰ふべからず各人其家に歸れ此事は我より出たるなりと彼等ヱホバの言を聽きヱホバの言に循ひて轉り去りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'ヤラベアムはエフライムの山地にシケムを建て其處に住み又其所より出てペヌエルを建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, '爰にヤラベアム其心に謂けるは國は今ダビデの家に歸らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, '若此民エルサレムにあるヱホバの家に禮物を献げんとて上らば此民の心ユダの王なる其主レハベアムに歸りて我を殺しユダの王レハベアムに歸らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, '是に於て王計議て二の金の犢を造り人々に言けるは爾らのエルサレムに上ること旣に足りイスラエルよ爾をエジブトの地より導き上りし汝の神を視よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, '而して彼一をベテルに安ゑ一をダンに置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, '此事罪となれりそは民ダンに迄往て其一の前に詣たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, '彼又崇邱の家を建てレビの子孫にあらざる凡民を祭司となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'ヤラベアム八月に節期を定めたり即ち其月の十五日なりユダにある節期に等し而して壇の上に上りたりベテルにて彼斯爲し其作りたる犢に禮物を献げたり又彼其造りたる崇邱の祭司をベテルに立たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'かく彼其ベテルに造れる壇の上に八月の十五日に上れり是は彼が己の心より造り出したる月なり而してイスラエルの人々のために節期を定め壇の上にのぼりて香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, '視よ爰に神の人ヱホバの言に由てユダよりベテルに來れり時にヤラベアムは壇の上に立て香を焚ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, '神の人乃ちヱホバの言を以て壇に向ひて呼はり言けるは壇よ壇よヱホバ斯言たまふ視よダビデの家にヨシアと名くる一人の子生るべし彼爾の上に香を焚く所の崇邱の祭司を爾の上に献げん且人の骨爾の上に燒れんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, '是日彼異蹟を示して言けるは是はヱホバの言たまへる事の異蹟なり視よ壇は裂け其上にある灰は傾出んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'ヤラベアム王神の人がベテルにある壇に向ひて呼はりたる言を聞る時其手を壇より伸し彼を執へよと言けるが其彼に向ひて伸したる手枯て再び屈縮ることを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'しかして神の人がヱホバの言を以て示したる異蹟の如く壇は裂け灰は壇より傾出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, '王答て神の人に言けるは請ふ爾の神ヱホバの面を和めわが爲に祈りてわが手を本に復しめよ神の人乃ちヱホバの面を和めければ王の手本に復りて前のごとくに成り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, '是において王神の人に言けるは我と與に家に來りて身を息めよ我爾に禮物を與へんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, '神の人王に言けるは爾假令爾の家の半を我に與ふるも我は爾とともに入じ又此所にてパンを食ず水を飮ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, '其はヱホバの言我にパンを食ふなかれ水を飮なかれ又爾が往る途より歸るなかれと命じたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, '斯彼他途を往き自己がベテルに來れる途よりは歸らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, '爰にベテルに一人の老たる預言者住ゐたりしが其子等來りて是日神の人がベテルにて爲たる諸事を彼に宣たり亦神の人の王に言たる言をも其父に宣たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, '其父彼等に彼は何の途を往しやといふ其子等ユダより來りし神の人の往たる途を見たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, '彼其子等に言けるは我ために驢馬に鞍おけと彼等驢馬に鞍おきければ彼之に乗り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, '神の人の後に往きて橡の樹の下に坐するを見之にいひけるは汝はユダより來れる神の人なるか其人然りと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, '彼其人にいひけるは我と偕に家に往てパンを食へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, '其人いふ我は汝と偕に歸る能はず汝と偕に入あたはず又我は此處にて爾と偕にパンを食ず水を飮じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, '其はヱホバの言我に爾彼處にてパンを食ふなかれ水を飮なかれ又爾が至れる所の途より歸り往なかれと言たればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, '彼其人にいひけるは我も亦爾の如く預言者なるが天の使ヱホバの言を以て我に告て彼を爾と偕に爾の家に携かへり彼にパンを食はしめ水を飮しめよといへりと是其人を誑けるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, '是において其人彼と偕に歸り其家にてパンを食ひ水を飮り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, '彼等が席に坐せし時ヱホバの言其人を携歸し預言者に臨みければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, '彼ユダより來れる神の人に向ひて呼はり言けるはヱホバ斯言たまふ爾ヱホバの口に違き爾の神ヱホバの爾に命じたまひし命令を守らずして歸り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'ヱホバの爾にパンを食ふなかれ水を飮なかれと言たまひし處にてパンを食ひ水を飮たれば爾の屍は爾の父祖の墓に至らざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, '其人のパンを食ひ水を飮し後彼其人のため即ち己が携歸りたる預言者のために驢馬に鞍おけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, '斯て其人往けるが獅子途にて之に遇ひて之を殺せり而して其屍は途に棄られ驢馬は其傍に立ち獅子も亦其屍の側に立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, '人々經過て途に棄られたる屍と其屍の側に立る獅子を見て來り彼老たる預言者の住る邑にて語れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, '彼人を途より携歸りたる預言者聞て言けるは其はヱホバの口に違きたる神の人なりヱホバの彼に言たまひし言の如くヱホバ彼を獅子に付したまひて獅子彼を裂き殺せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'しかして其子等に語りて言けるは我ために驢馬に鞍おけと彼等鞍おきければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, '彼往て其屍の途に棄られ驢馬と獅子の其屍の傍に立るを見たり獅子は屍を食はず驢馬をも裂ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, '預言者乃ち神の人の屍を取あげて之を驢馬に載せて携歸れりしかして其老たる預言者邑に入り哀哭みて之を葬れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, '即ち其屍を自己の墓に置め皆之がために嗚呼わが兄弟よといひて哀哭り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, '彼人を葬りし後彼其子等に語りて言けるは我が死たる時は神の人を葬りたる墓に我を葬りわが骨を彼の骨の側に置めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, '其は彼がヱホバの言を以てベテルにある壇にむかひ又サマリアの諸邑に在る崇邱の凡の家に向ひて呼はりたる言は必ず成べければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, '斯事の後ヤラベアム其惡き途を離れ歸ずして復凡の民を崇邱の祭司と爲り即ち誰にても好む者は之を立てければ其人は崇邱の祭司と爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, '此事ヤラベアムの家の罪戻となりて遂に之をして地の表面より消失せ滅亡に至らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, '當時ヤラベアムの子アビヤ疾ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'ヤラベアム其妻に言けるは請ふ起て装を改へ人をして汝がヤラベアムの妻なるを知しめずしてシロに往け彼處にわが此民の王となるべきを我に告たる預言者アヒヤをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, '汝の手に十のパン及び菓子と一瓶の蜜を取て彼の所に往け彼汝に此子の如何になるかを示すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'ヤラベアムの妻是爲し起てシロに往きアヒヤの家に至りしがアヒヤは年齢のために其目凝て見ることを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'ヱホバ、アヒヤにいひたまひけるは視よヤラベアムの妻其子疾るに因て其に付て汝に一の事を諮んとて來る汝斯々彼に言べし其は彼入り來る時其身を他の人とすべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, '彼が戸の所に入來れる時アヒヤ其履聲を聞て言けるはヤラベアムの妻入よ汝何ぞ其身を他の人とするや我汝に嚴酷き事を告るを命ぜらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, '往てヤラベアムに告べしイスラエルの神ヱホバ斯言たまふ我汝を民の中より擧げ我民イスラエルの上に汝を君となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, '國をダビデの家より裂き離して之を汝に與へたるに汝は我僕ダビデの我が命令を守りて一心に我に從ひ唯わが目に適ふ事のみを爲しが如くならずして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, '汝の前に在し凡の者よりも惡を爲し往て汝のために他の神と鋳たる像を造り我が怒を激し我を汝の背後に棄たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, '是故に視よ我ヤラベアムの家に災害を下しヤラベアムに屬する男はイスラエルにありて繋がれたる者も繋がれざる者も盡く絶ち人の塵埃を殘りなく除くがごとくヤラベアムの家の後を除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'ヤラベアムに屬する者の邑に死るをば犬之を食ひ野に死ぬるをば天空の鳥之を食はんヱホバ之を語たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, '爾起て爾の家に往け爾の足の邑に入る時子は死ぬべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, '而してイスラエル皆彼のために哀みて彼を葬らんヤラベアムに屬する者は唯是のみ墓に入るべし其はヤラベアムの家の中にて彼はイスラエルの神ヱホバに向ひて善き意を懐けばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'ヱホバ、イスラエル上に一人の王を興さん彼其日にヤラベアムの家を斷絶べし但し何れの時なるか今即ち是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, '又ヱホバ、イスラエルを撃て水に搖撼ぐ葦の如くになしたまひイスラエルを其父祖に賜ひし此善地より抜き去りて之を河の外に散したまはん彼等其アシラ像を造りてヱホバの怒を激したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'ヱホバ、ヤラベアムの罪の爲にイスラエルを棄たまふべし彼は罪を犯し又イスラエルに罪を犯さしめたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'ヤラベアムの妻起て去テルザに至りて家の閾に臻れる時子は死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'イスラエル皆彼を葬り彼の爲に哀めりヱホバの其僕預言者アヒヤによりて言たまへる言の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'ヤラベアムの其餘の行爲彼が如何に戰ひしか如何に世を治めしかは視よイスラエルの王の歴代志の書に記載る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'ヤラベアムの王たりし日は二十二年なりき彼其父祖と偕に寝りて其子ナダブ之に代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'ソロモンの子レハベアムはユダに王たりきレハベアムは王と成る時四十一歳なりしがヱホバの其名を置んとてイスラエルの諸の支派の中より選みたまひし邑なるエルサレムにて十七年王たりき其母の名はナアマといひてアンモニ人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'ユダ其父祖の爲たる諸の事に超てヱホバの目の前に惡を爲し其犯したる罪に由てヱホバの震怒を激せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, '其は彼等も諸の高山の上と諸の靑木の下に崇邱と碑とアシラ像を建たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, '其國には亦男色を行ふ者ありぎ彼等はヱホバがイスラエルの子孫の前より逐攘ひたまひし國民の中にありし諸の憎むべき事を傚ひ行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'レハベアム王の第五年にエジプトの王シシヤク、エルサレムに攻上り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'ヱホバの家の寶物と王の家の寶物を奪ひたり即ち盡く之を奪ひ亦ソロモンの造りたる金の楯を皆奪ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'レハベアム王其代に銅の楯を造りて王の家の門を守る侍衛の長の手に付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, '王のヱホバの家に入る毎に侍衛之を負ひ復之を侍衛の房に携歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'レハベアムの其餘の行爲と其凡て爲たる事はユダの王の歴代志の書に記さるるに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'レハベアムとヤラベアムの間に戰爭ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'レハベアム其父祖と偕に寝りて其父祖と共にダビデの城に葬らる其母のナアマといひてアンモニ人なり其子アビヤム之に代りて王と爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'ネバテの子ヤラベアム王の第十八年にアビヤム、ユダの王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'エルサレムにて三年世を治めたり其母の名はマアカといひてアブサロムの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, '彼は其父が己のさきに爲たる諸の罪を行ひ其心其父ダビデの心の如く其神ヱホバに完全からざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, '然に其神ヱホバ、ダビデの爲にエルサレムに於て彼に一の燈明を與へ其子を其後に興しエルサレムを固く立しめ賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, '其はダビデはヘテ人ウリヤの事の外は一生の間ヱホバの目に適ふ事を爲て其己に命じたまへる諸の事に背かざりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'レハベアムとヤラベアムの間には其一生の間戰爭ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'アビヤムの其餘の行爲と凡て其爲たる事はユダの王の歴代志の書に記載さるるにあらずやアビヤムとヤラベアムの間に戰爭ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'アビヤム其先祖と倶に寝りしかば之をダビデの城に葬りぬ其子アサ之に代りて王と爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'イスラエルの王ヤラベアムの第二十年にアサ、ユダの王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'エルサレムにて四十一年世を治めたり其母の名はマアカといひてアブサロムの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'アサは其父ダビデの如くヱホバの目に適ふ事を爲し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, '男色を行ふ者を國より逐ひ出し其父祖等の造りたる諸の偶像を除けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, '彼は亦其母マアカのアシラの像を造りしがために之を貶して太后たらしめざりき而してアサ其像を毀ちてキデロンの谷に焚棄たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, '但し崇邱は除かざりき然どアサの心は一生の間ヱホバに完全かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, '彼其父の献納めたる物と己のをさめたる物金銀器をヱホバの家に携へいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'アサとイスラエルの王バアシヤの間に一生の間戰爭ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'イスラエルの王バアシヤ、ユダに攻上りユダの王アサの所に誰をも往來せざらしめん爲にラマを築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, '是に於てアサ王ヱホバの家の府庫と王の家の府庫に殘れる所の金銀を盡く將て之を其臣僕の手に付し之をダマスコに住るスリアの王ヘジヨンの子タブリモンの子なるベネハダデに遣はして言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'わが父と爾の父の間の如く我と爾の間に約を立ん視よ我爾に金銀の禮物を餽れり往て爾とイスラエルの王バアシヤとの約を破り彼をして我を離れて上らしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'ベネハダデ、アサ王に聽きて自己の軍勢の長等を遣はしてイスラエルの諸邑を攻めイヨンとダンとアベルベテマアカおよびキンネレテの全地とナフタリの全地とを撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'バアシヤ聞及びラマを築くことを罷てテルザに止り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, '是に於てアサ王令をユダ全國に降したり一人も免かれし者なし斯して即ちバアシヤが用ひてラマを築きたる石と材木を取きたらしめアサ王之を用てべニヤミンのゲバとミズパを築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'アサの其餘の行爲と其諸の功業と凡て其爲たる事および其建たる城邑はユダの王の歴代志の書に記載さるるにあらずや但し彼は年老るに及びて其足を病たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'アサ其父祖と時に寝りて其父ダビデの城に其父祖と偕に葬らる其子ヨシヤパテ之に代りて王と爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'ユダの王アサの第二年にヤラベアムの子ナダブ、イスラエルの王と爲り二年イスラエルを治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, '彼ヱホバの目のまへに惡を爲其父の道に歩行み其イスラエルに犯させたる罪を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, '爰にイツサカルの家のアヒヤの子バアシヤ彼に敵して黨を結びペリシテ人に屬するギベトンにて彼を撃り其はナダブとイスラエル皆ギベトンを圍み居たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'ユダの王アサの第三年にバアシヤ彼を殺し彼に代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'バアシヤ王となれる時ヤラベアムの全家を撃ち氣息ある者は一人もヤラベアムに殘さずして盡く之を滅せりヱホバの其僕シロ人アヒヤに由て言たまへる言の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, '是はヤラベアムが犯し又イスラエルに犯させたる罪の爲め又彼がイスラエルの神ヱホバの怒を惹き起したる事に因るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'ナダブの其餘の行爲と凡て其爲たる事はイスラエルの王の歴代志の書に記載さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'アサとイスラエルの王バアシヤの間に一生のあひだ戰爭ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'ユダの王アサの第三年にアヒヤの子バアシヤ、テルザに於てイスラエルの全地の王となりて二十四年を經たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, '彼ヱホバの目のまへに惡を爲しヤラベアムの道にあゆみ其イスラエルに犯させたる罪を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, '爰にヱホバの言ハナニの子ヱヒウに臨みバアシヤを責て曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '我爾を塵の中より擧て我民イスラエルの上に君となしたるに爾はヤラベアムの道に歩行みわが民イスラエルに罪を犯させて其罪をもて我怒を激したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'されば我バアシヤの後と其家の後を除き爾の家をしてネバテの子ヤラベアムの家の如くならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'バアシヤに屬する者の城邑に死るをば犬之を食ひ彼に屬する者の野に死るをば天空の鳥これを食はんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'バアシヤの其餘の行爲と其爲たる事と其功績はイスラエルの王の歴代志の書に記載さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'バアシヤ其父祖と倶に寝りてテルザに葬らる其子エラ之に代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'ヱホバの言亦ハナニの子ヱヒウに由て臨みバアシヤと其家を責む是は彼がヱホバの目のまへに諸の惡事を行ひ其手の所爲を以てヱホバの怒を激してヤラベアムの家に傚たるに縁り又其ナダブを殺したるに縁てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'ユダの王アサの第二十六年にバアシヤの子エラ、テルザに於てイスラエルの王となりて二年を經たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, '彼がテルザにありてテルザの宮殿の宰アルザの家において飮み酔たる時其僕ジムリ戰車の半を督どる者之に敵して黨を結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, '即ちユダの王アサの第二十七年にジムリ入て彼を撃ち彼を殺し彼にかはりて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, '彼王となりて其位に上れる時バアシヤの全家を殺し男子は其親族にもあれ朋友にもあれ一人も之に遺さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'ジムリ斯バアシヤの全家を滅ぼせりヱホバが預言者ヱヒウに由てバアシヤを責て言たまへる言の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, '是はバアシヤの諸の罪と其子エラの罪のためなり彼等は罪を犯し又イスラエルをして罪を犯し其虚物を以てイスラエルの神ヱホバの怒を激さしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'エラの其餘の行爲と凡て其爲たる事はイスラエルの王の歴代志の書に記載さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'ユダの王アサの第二十七年にジムリ、テルザにて七日の間王たりき民はペリシテ人に屬するギベトンに向ひて陣どり居たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, '陣どれる民ジムリは黨を結び亦王を殺したりと言を聞り是に於てイスラエル皆其日陣營にて軍の長オムリをイスラエルの王となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'オムリ乃ちイスラエルの衆と偕にギベトンより上りてテルザを圍り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'ジムリ其邑の陷るを見て王の家の天守に入り王の家に火をかけて其中に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, '是は其犯したる罪によりてなり彼ヱホバの目のまへに惡を爲しヤラベアムの道にあゆみヤラベアムがイスラエルに罪を犯させて爲したるところの罪を行ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'ジムリの其餘の行爲と其なしたる徒黨はイスラエルの王の歴代志の書に記載るるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, '其時にイスラエルの民二に分れ民の半はギナラの子テブニに從ひて之を王となさんとし半はオムリに從へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'オムリに從へる民ギナテの子テブニに從へる民に勝てテブニは死てオムリ王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'ユダの王アサの第三十一年にオムリ、イスラエルの王となりて十二年を經たり彼テルザにて六年王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, '彼銀二タラントを以てセメルよりサマリア山を買ひ其上に邑を建て其建たる邑の名を其山の故主なりしセメルの名に循ひてサマリアと稱り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'オムリ、ヱホバの目のまへに惡を爲し其先に在し凡の者よりも惡き事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, '彼はネバテの子ヤラベアムの凡の道にあゆみヤラベアムがイスラエルをして罪を犯し其虚物を以てイスラエルの神ヱホバの怒をおこさしめたる其罪を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'オムリの爲たる其餘の行爲と其なしたる功績はイスラエルの王の歴代志の書に記載るるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'オムリ其父祖と偕に寝りてサマリアに葬らる其子アハブ之に代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'ユダの王アサの第三十八年にオムリの子アハブ、イスラエルの王となれりオムリの子アハブ、サマリアに於て二十二年イスラエルに王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'オムリの子アハブは其先に在し凡の者よりも多くヱホバの目のまへに惡を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, '彼はネバテの子ヤラベアムの罪を行ふ事を軽き事となせしがシドン人の王エテバアルの女イゼベルを妻に娶り往てバアルに事へ之を拝めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, '彼其サマリアに建たるバアルの家の中にバアルのために壇を築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'アハブ又アシラ像を作れりアハブは其先にありしイスラエルの諸の王よりも甚だしくイスラエルの神ヱホバの怒を激すことを爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, '其代にベテル人ヒエル、ヱリコを建たり彼其基を置る時に長子アビラムを喪ひ其門を立る時に季子セグブを喪へりヌンの子ヨシユアによりてヱホバの言たまへるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'ギレアデに居住れるテシベ人エリヤ、アハブに言ふ吾事ふるイスララエルの神ヱホバは活くわが言なき時は數年雨露あらざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'ヱホバの言彼に臨みて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '爾此より往て東に赴きヨルダンの前にあるケリテ川に身を匿せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, '爾其川の水を飮べし我鴉に命じて彼處にて爾を養はしむと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, '彼往てヱホバの言の如く爲り即ち往てヨルダンの前にあるケリテ川に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, '彼の所に鴉朝にパンと肉亦夕にパンと肉を運べり彼は川に飮り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'しかるに國に雨なかりければ數日の後其川涸ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'ヱホバの言彼に臨みて曰');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '起てシドンに屬するザレバテに往て其處に住め視よ我彼處の嫠婦に命じて爾を養はしむと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, '彼起てザレパテに往けるが邑の門に至れる時一人の嫠婦の其處に薪を採ふを見たり乃ち之を呼て曰けるは請ふ器に少許の水を我に携來りて我に飮せよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, '彼之を携きたらんとて往る時エリヤ彼を呼て言けるは請ふ爾の手に一口のパンを我に取きたれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, '彼いひけるは爾の神ヱホバは活く我はパン無し只桶に一握の粉と瓶に少許の油あるのみ觀よ我は二の薪を採ふ我いりてわれとわが子のために調理て之をくらひて死んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'エリヤ彼に言ふ懼るるなかれ往て汝がいへる如くせよ但し先其をもてわが爲に小きパン一を作りて我に携きたり其後爾のためと爾の子のために作るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, '其はヱホバの雨を地の面に降したまふ日までは其桶の粉は竭ず其瓶の油は絶ずとイスラエルの神ヱホバ言たまへばなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, '彼ゆきてエリヤの言るごとくなし彼と其家及びエリヤ久く食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'ヱホバのエリヤに由て言たまひし言のごとく桶の粉は竭ず瓶の油は絶ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, '是等の事の後其家の主母なる婦の子疾に罹しが其病甚だ劇くして氣息其中に絶て無きに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, '婦エリアに言けるは神の人よ汝なんぞ吾事に關渉るべけんや汝はわが罪を憶ひ出さしめんため又わが子を死しめんために我に來れるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'エリヤ彼に爾の子を我に授せと言て之を其懐より取り之を己の居る桜に抱のぼりて己の牀に臥しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'ヱホバに呼はりていひけるは吾神ヱホバよ爾は亦吾ともに宿る嫠に菑をくだして其子を死しめたまふやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, '而して三度身を伸して其子の上に伏しヱホバに呼はりて言ふわが神ヱホバ願くは此子の魂を中に歸しめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'ヱホバ、エリヤの聲を聽いれたまひしかば其子の魂中にかへりて生たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'エリヤ乃ち其子を取て之を桜より家に携くだり其母に與していひけるは視よ爾の子は生くと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, '婦エリヤにいひけるは此に縁て我は爾が神の人にして爾の口にあるヱホバの言は眞實なるを知ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, '衆多の日を經たるのち第三年にヱホバの言エリヤに臨みて曰く往て爾の身をアハブに示せ我雨を地の面に降さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'エリヤ其身をアハブに示さんとて往り時に饑饉サマリアに甚しかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, '茲にアハブ家宰なるオバデヤを召たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, '(オバデヤは大にヱホバを畏みたる者にてイゼベルがヱホバの預言者を絶たる時にオバデヤ百人の預言者を取て之を五十人づつ洞穴に匿しパンと水をもて之を養へり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'アハブ、オバデヤにいひけるは國中の水の諸の源と諸の川に往け馬と騾を生活むる草を得ることあらん然ば我儕牲畜を盡くは失なふに至らじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, '彼等巡るべき地を二人に分ちアハブは獨にて此途に往きオバデヤは獨にて彼途に往けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'オバデヤ途にありし時觀よエリヤ彼に遭り彼エリヤを識て伏て言けるは我主エリヤ汝は此に居たまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'エリヤ彼に言けるは然り往て汝の主にエリヤは此にありと告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, '彼言けるは我何の罪を犯したれば汝僕をアハブの手に付して我を殺さしめんとする');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, '汝の神ヱホバは生くわが主の人を遣はして汝を尋ねざる民はなく國はなし若しエリヤは在ずといふ時は其國其民をして汝を見ずといふ誓を爲しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, '汝今言ふ往て汝の主にエリヤは此にありと告よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, '然ど我汝をはなれて往ときヱホバの霊我しらざる處に汝を携へゆかん我至りてアハブに告て彼汝を尋獲ざる時は彼我を殺さん然ながら僕はわが幼少よりヱホバを畏むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'イゼベルがヱホバの預言者を殺したる時に吾なしたる事即ち我がヱホバの預言者の中百人を五十人づつ洞穴に匿してパンと水を以て之を養ひし事は吾主に聞えざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'しかるに今汝言ふ往て汝の主にエリヤは此にありと告よと然らば彼我を殺すならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'エリヤいひけるは我が事ふる萬軍のヱホバは活く我は必ず今日わが身を彼に示すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'オバデヤ乃ち往てアハブに會ひ之に告ければアハブはエリヤに會んとて往きけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'アハブ、エリヤを見し時アハブ、エリヤに言けるは汝イスラエルを惱ます者此にをるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, '彼答へけるは我はイスラエルを惱さず但汝と汝の父の家之を惱すなり即ち汝等はヱホバの命令を棄て且汝はバアルに從ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'されば人を遣てイスラエルの諸の人およびバアルの預言者四百五十人並にアシラ像の預言者四百人イゼベルの席に食ふ者をカルメル山に集めて我に詣しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, '是においてアハブ、イスラエルの都の子孫の中に人を遣り預言者をカルメル山に集めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, '時にエリヤ總の民に近づきて言けるは汝等何時まで二の物の間にまよふやヱホバ若し神ならば之に從へされどバアル若し神ならば之に從へと民は一言も彼に答ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'エリヤ民に言けるは惟我一人存りてヱホバの預言者たり然どバアルの預言者は四百五十人あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, '然ば二の犢を我儕に與へよ彼等は其一の犢を選みて之を截り剖き薪の上に載せて火を縦たずに置べし我も其一の犢を調理へ薪の上に載せて火を縦ずに置べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, '斯して汝等は汝等の神の名を龥べ我はヱホバの名を龥ん而して火をもて應る神を神と爲べしと民皆答て斯言は善と言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'エリヤ、バアルの預言者に言けるは汝等は多ければ一の犢を選みて最初に調理へ汝等の神の名を呼ぶべし但し火を縦なかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, '彼等乃ち其與られたる犢を取て調理へ朝より午にいたるまでバアルの名を龥てバアルよ我儕に應へたまへと言り然ど何の聲もなく又何の應る者もなかりければ彼等は其造りたる壇のまはりに踊れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, '日中におよびてエリヤ彼等を嘲りていひけるは大聲をあげて呼べ彼は神なればなり彼は默想をるか他處に行しか又は旅にあるか或は假寐て醒さるべきかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, '是において彼等は大聲に呼はり其例に循ひて刀劍と槍を以て其身を傷つけ血を其身に流すに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, '斯して午時すぐるに至りしが彼等なほ預言を言ひて晩の祭物を献ぐる時にまで及べり然ども何の聲もなく又何の應ふる者も无く又何の顧る者もなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, '時にエリヤ都の民にむかひて我に近よれと言ければ民皆彼に近よれり彼乃ち破壞たるヱホバの壇を修理ヘり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'エリヤ、ヤコブの子等の支派の數に循ひて十二の石を取れり(ヱホバの言昔ヤコブに臨みてイスラエルを汝の名とすべしと言り)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, '彼其石にてヱホバの名を以て壇を築き壇の周圍に種子二セヤを容べき溝を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, '又薪を陳列べ犢を截剖て薪の上に載せて言けるは四の桶に水を滿て燔祭と薪の上に沃げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, '又いひけるは再び之を爲せと再びこれをなせしかば又言ふ三次これを爲せと三次これをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, '水に壇の周廻に流るまた溝にも水をみたしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, '晩の祭物を献ぐる時に及て預言者エリヤ近よりて言けるはアブラハム、イサク、イスラエルの神ヱホバよ汝のイスラエルにおいて神なることおよび我が汝の僕にして汝の言に循ひて是等の諸の事を爲せることを今日知しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'ヱホバよ我に應へたまへ我に應へたまへ此民をして汝ヱホバは神なることおよび汝は彼等の心を翻へしたまふといふことを知しめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, '時にヱホバの火降りて燔祭と薪と石と塵とを焚つくせり亦溝の水を餂涸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, '民皆見て伏ていひけるはヱホバは神なりヱホバは神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'エリヤ彼等に言けるはバアルの預言者を執へよ其一人をも逃遁しむる勿れと即ち之を執へたればエリヤ之をキシヨン川に曳下りて彼處に之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, '斯てエリヤ、アハブにいひけるは大雨の聲あれば汝上りて食飮すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'アハブ乃ち食飮せんとて上れり然どエリヤはカルメルの嶺に登り地に伏て其面を膝の間に容ゐたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, '其少者にいひけるは請ふ上りて海の方を望めと彼上り望みて何もなしといひければ再び往けといひて遂に七次に及べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, '第七次に及びて彼いひけるは視よ海より人の手のごとく微の雲起るとエリヤいふ上りてアハブに雨に阻められざるやう車を備へて下りたまへと言ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, '驟に雲と風おこり霄漢黑くなりて大雨ありきアハブはヱズレルに乗り往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'ヱホバの能力エリヤに臨みて彼其腰を束帶びヱズレルの入口までアハブの前に趨りゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'アハブ、イゼベルにエリヤの凡て爲たる事及び其如何に諸の預言者を刀劍にて殺したるかを告しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'イゼベル使をエリヤに遣はして言けるは神等斯なし復重て斯なしたまへ我必ず明日の今時分汝の命を彼人々の一人の生命のごとくせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'かれ恐れて起ち其生命のために逃げ往てユダに屬するベエルシバに至り少者を其處に遺して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, '自ら一日程ほど曠野に入り往て金雀花の下に坐し其身の死んことを求めていふヱホバよ足り今わが生命を取たまへ我はわが父祖よりも善にはあらざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, '彼金雀花の下に伏して寝りしが天の使彼に捫り興て食へと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, '彼見しに其頭の側に炭に燒きたるパンと一瓶の水ありき乃ち食ひ飮て復偃臥たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'ヱホバの使者復再び來りて彼に捫りていひけるは興て食へ其は途長くして汝勝べからざればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, '彼興て食ひ且飮み其食の力に仗て四十日四十夜行て神の山ホレブに至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, '彼處にて彼洞穴に入りて其處に宿りしが主の言彼に臨みて彼に言けるはエリヤよ汝此にて何を爲や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, '彼いふ我は萬軍の神ヱホバのために甚だ熱心なり其はイスラエルの子孫汝の契約を棄て汝の壇を毀ち刀劍を以て汝の預言者を殺したればなり惟我一人存るに彼等我生命を取んことを求むと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'ヱホバ言たまひけるは出てヱホバの前に山の上に立てと茲にヱホバ過ゆきたまふにヱホバのまへに當りて大なる強き風山を裂き岩石を碎しが風の中にはヱホバ在さざりき風の後に地震ありしが地震の中にはヱホバ在さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, '又地震の後に火ありしが火の中にはヱホバ在さざりき火の後に靜なる細微き聲ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'エリヤ聞て面を外套に蒙み出て洞穴の口に立ちけるに聲ありて彼に臨みエリヤよ汝此にて何をなすやといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'かれいふ我は萬軍の神ヱホバの爲に甚だ熱心なり其はイスラエルの子孫汝の契約を棄て汝の壇を毀ち刀劍を以て汝の預言者を殺したればなり惟我一人存れるに彼等我が生命を取んことを求むと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'ヱホバかれに言たまひけるは往て汝の途に返りダマスコの曠野に至り往てハザエルに膏を沃ぎてスリアの王となせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, '又汝ニムシの子エヒウに膏を注ぎてイスラエルの王となすべし又アベルメホラのシヤパテの子エリシヤに膏をそそぎ爾に代りて預言者とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'ハザエルの刀劍を逃るる者をばエヒウ殺さんエヒウの刀劍を逃るる者をばエリシヤ殺さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, '又我イスラエルの中に七千人を遺さん皆其膝をバアルに跼めず其口を之に接ざる者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'エリヤ彼處よりゆきてシヤパテの子エリシヤに遭ふ彼は十二軛の牛を其前に行しめて己は其第十二の牛と偕にありて耕し居たりエリヤ彼の所にわたりゆきて外套を其上にかけたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, '牛を棄てエリヤの後に趨ゆきて言けるは請ふ我をしてわが父母に接吻せしめよしかるのち我爾にしたがはんとエリヤかれに言けるは行け還れ我爾に何をなしたるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'エリシヤ彼をはなれて還り一軛の牛をとりて之をころし牛の器具を焚て其肉を煮て民にあたへて食はしめ起て往きエリヤに從ひて之に事へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'スリアの王ベネハダデ其軍勢を悉く集む王三十二人彼と偕にあり又馬と戰車とあり乃ち上りてサマリアを圍み之を攻む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, '彼使をイスラエルの王アハブに遣し邑に至りて彼に言しめけるはベネハダデ斯言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, '爾の金銀は我の所有なり亦爾の妻等と爾の子等の美秀者は我の所有なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'イスラエルの王答へて言けるは王わが主よ爾の言の如く我と我が有つ者は皆爾の所有なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, '使者再び來りて言けるはベネハダデ斯語て言ふ我爾に爾我に爾の金銀妻子を付すべしと言遣れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, '然ど明日今頃我が僕を爾に遣さん彼等爾の家と爾の臣僕の家を探索りて凡て爾の日に好ましく見ゆる者を其手に置て取り去るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, '是においてイスラエルの王國の長老を皆召て言けるは請ふ爾等見て此人の害をなさんと求るを知れ彼人を我に遣りて我が妻子とわが金銀を索めたり而るに我之を謝絶ざりしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, '諸の長老および民皆彼に言けるは爾聽なかれ許すなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, '是故に彼ベネハダデの使者に言けるは王わが主に告よ爾が最初に僕に言つかはしたる事は皆我爲べし然ど比事は我爲あたはずと使者往て反命をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'ベネハダデ彼に言つかはしけるは神等我に斯なし亦重て斯なしたまへサマリアの塵は我に從ふ諸の民の手に滿るに足ざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'イスラエルの王答へて帶る者は解く者の如く誇るべからずと告よと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'ベネハダデ天幕にありて王等と飮ゐたりしが此事を聞て其臣僕に言けるは爾等陣列を爲せと即ち邑に向ひて陣列をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, '時に一人の預言者イスラエルの王アハブの許に至りて言けるはヱホバ斯言たまふ爾此諸の大軍を見るや視よ我今日之を爾の手に付さん爾は我がヱホバなるを知にいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'アハブ言けるは誰を以てせんか彼いひけるはヱホバ斯いひたまふ諸省の牧伯の少者を以てすべしアハブ言ふ誰か戰爭を始むべき彼答けるは爾なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'アハブ乃ち諸省の牧伯の少者を核るに二百三十二人あり次に凡の民即ちイスラエルの凡の子孫を核るに七千人あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, '彼等日中出たちたりしがベネハダデは天幕にて王等即ち己を助る三十二人の王等とともに飮て酔居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, '諸省の牧伯の少者等先に出たりベネハダデ人を出すにサマリアより人衆出來ると彼に告ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, '彼言けるは和睦のために出來るも之を生擒べし又戰爭のために出來るも之を生擒べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, '諸省の牧伯の是等の少者および之に從ふ軍勢邑より出きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, '各其敵手を撃ち殺しければスリア人逃たりイスラエル之を追ふスリアの王ベネハダデは馬に乗り騎兵を從へて逃遁たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'イスラエルの王出て馬と戰車を撃ち又大にスリア人を撃殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, '茲に彼預言者イスラエルの王の許に詣て彼に言けるは往て爾の力を養ひ爾の爲すべき事を知り辨ふべし年歸らばスリアの王爾に攻上るべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'スリアの王の臣僕王に言けるは彼等の神等は山崗の神なるが故に彼等は我等よりも強かりしなり然ども我等若平地に於て彼等と戰はば必ず彼等よりも強かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, '但し此事を爲せ即ち王等を除きて各其處を離しめ方伯を置て之に代べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, '又爾の失ひたる軍勢に均き軍勢を爾のために備へ馬は馬戰車は戰車をもて補ふべし斯して我儕平地において彼等と戰はば必ず彼等よりも強かるべしと彼其言を聽いれて然なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, '年かへるに及びてベネハダデ、スリア人を核めてアペクに上りイスラエルと戰はんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'イスラエルの子孫核められ兵糧を受て彼等に出會んとて往けりイスラエルの子孫は山羊の二の小群の如く彼等の前に陣どりしがスリア人は其地に充滿たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, '時に神の人至りてイスラエルの王に告ていひけるはヱホバ斯言たまふスリア人ヱホバは山獄の神にして谿谷の神にあらずと言ふによりて我此諸の大軍を爾の手に付すべし爾等は我がヱホバなるを知に至らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, '彼等七日互に相對て陣どり第七日におよびて戰爭を交接しがイスラエルの子孫一日にスリア人の歩兵十萬人を殺しければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, '其餘の者はアベクに逃て邑に入ぬ然るに其石垣崩れて其存れる二萬七千人の上にたふれたりベネハダデは逃て邑にいたり奧の間に入ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, '其臣僕彼にいひけるは我儕イスラエルの家の王等は仁慈ある王なりと聞り請ふ我儕粗麻布を腰につけ繩を頭につけてイスラエルの王の所にいたらん彼爾の命を生むることあらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, '斯彼等粗麻布を腰にまき繩を頭にまきてイスラエルの王の所にいたりていひけるは爾の僕ベネハダデ請ふ我が生命を生しめたまへと言ふとアハブいひけるは彼は尚生をるや彼はわが兄弟なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, '其人々これを吉兆と爲し速に彼の言を承て爾の兄弟ベネハダデといへり彼言けるは爾等ゆきて彼を導ききたるべしと是においてベネハダデ彼の所に出來りしかば彼之を車に登しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'ベネハダデ彼に言けるは我父の爾の父より取たる諸邑は我返すべし又我が父のサマリアに造りたる如く爾ダマスコに於て爾のために街衢を作るべしアハブ言ふ我此契約を以て爾を歸さんと斯彼と契約を爲て彼を歸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, '爰に預言者の徒の一人ヱホバの言によりて其同儕に請我を撃てといひけるが其人彼を撃つことを肯ぜざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, '彼其人に言ふ汝ヱホバの言を聽ざりしによりて視よ汝の我をはなれて往く時獅子汝をころさんと其人彼の側を離れて往きけるに獅子之に遇て之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, '彼また他の人に遭て請ふ我を撃といひければ其人之を撃ち撃て傷けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, '預言者往て王を途に待ち其目に掩巾をあてて儀容を變ゐたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, '王の經過る時王に呼はりていひけるは僕戰爭の中に出しに人轉りて一箇の人を我の所に曳きたりて言けるは此人を守れ若彼失ゆく事あらば汝の生命を彼の生命に代べし或は爾銀一タラントを出すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, '而るに僕此彼に事をなしゐたれば彼遂に失たりとイスラエルの王彼にいひけるは爾の擬定は然なるべし爾之を決めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, '彼急ぎて其目の掩巾を取除たればイスラエルの王彼が預言者の一人なるを識り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, '彼王に言けるはヱホバ斯言たまふ爾はわが殲滅んと定めたる人を爾の手より放ちたれば爾の命は彼の生命に代り爾の民は彼の民に代るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'イスラエルの王憂へ且怒て其家に赴きサマリアに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, '是等の事の後ヱズレル人ナボテ、ヱズレルに葡萄園を有ちゐたりしがサマリアの王アハブの殿の側に在りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'アハブ、ナボテに語て言けるは爾の葡萄園は近くわが家の側にあれば我に與へて蔬采の圃となさしめよ我之がために其よりも美き葡萄園を爾に與へん若し爾の心にかなはば其價を銀にて爾に予へんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'ナボテ、アハブに言けるはわが父祖の產業を爾に與ふる事は決て爲べからずヱホバ禁じたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'アハブはヱズレル人ナボテの己に言し言のために憂ひ且怒りて其家に入ぬ其は彼わが父祖の產業を爾に與へじと言たればなりアハブ床に臥し其面を轉けて食をなさざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, '其妻イゼベル彼の處にいりて彼に言けるは爾の心何を憂へて爾食を爲ざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, '彼之に言けるは我ヱズレル人ナボテに語りて爾の葡萄園を銀に易て我に與へよ若また爾好ば我其に易て葡萄園を爾に與へんと彼に言たるに彼答へて我が葡萄園を爾に與へじと言たればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, '其妻イゼベル彼に言けるは爾今イステエルの國を治むることを爲すや興て食を爲し爾の心を樂ましめよ我ヱズレル人ナボテの葡萄園を爾に與へんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, '彼アハブの名をもて書を書き彼の印を捺し其邑にナボテとともに住る長老と貴き人に其書をおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, '彼其書にしるして曰ふ斷食を宣傳てナボテを民の中に高く坐せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, '又邪なる人二人を彼のまへに坐せしめ彼に對ひて證を爲して爾神と王を詛ひたりと言しめよ斯して彼を曳出し石にて撃て死しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, '其邑の人即ち其邑に住る長老および貴き人等イゼベルが己に言つかはしたる如く即ち彼が己に遣りたる書に書したる如く爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, '彼等斷食を宣達てナボテを民の中に高く坐せしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, '時に二人の邪なる人入來りて其前に坐し其邪なる人民のまへにてナボテに對て證をなして言ふナボテ神と王を詛ひたりと人衆彼を邑の外に曳出し石にて之を撃て死しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, '斯てイゼベルにナボテ撃れて死たりと言遣れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'イゼベル、ナボタの撃れて死たるを聞しかばイゼベル、アハブに言けるは起て彼ヱズレル人ナボテが銀に易て爾に與ることを拒みし葡萄園を取べし其はナボテは生をらず死たればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'アハブ、ナボテの死たるを聞しかばアハブ起ちヱズレル人ナボテの葡萄園を取んとて之に下れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, '時にヱホバの言テシベ人エリヤに臨みて曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '起て下りサマリアにあるイスラエルの王アハブに會ふべし彼はナボテの葡萄園を取んとて彼處に下りをるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, '爾彼に告て言べしヱホバ斯言ふ爾は殺し亦取たるやと又爾彼に告て言ふべしヱホバ斯言ふ犬ナボテの血を銛し處にて犬爾の身の血を銛べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'アハブ、エリヤに言けるは我敵よ爾我に遇や彼言ふ我遇ふ爾ヱホバの目の前に惡を爲す事に身を委しに縁り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, '我災害を爾に降し爾の後裔を除きアハブに屬する男はイスラエルにありて繋がれたる者も繋がれざる者も悉く絶ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, '又爾の家をネバテの子ヤラベアムの家の如くなしアヒヤの子バアシヤの家のごとくなすべし是は爾我の怒を惹起しイスラエルをして罪を犯させたるに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'イゼベルに關てヱホバ亦語て言給ふ犬ヱズレルの濠にてイゼベルを食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'アハブに屬する者の邑に死るをば犬之を食ひ野に死るをば天空の鳥之を食はんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '誠にアハブの如くヱホバの目の前に惡をなす事に身をゆだねし者はあらざりき其妻イゼベル之を慫憊たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, '彼はヱホバがイスラエルの子孫のまへより逐退けたまひしアモリ人の凡てなせし如く偶像に從ひて甚だ惡むべき事を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'アハブ此等の言を聞ける時其衣を裂き粗麻布を體にまとひ食を斷ち粗麻布に臥し遅々に歩行り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, '茲にヱホバの言テシベ人エリヤに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '爾アハブの我前に卑下るを見るや彼わがまへに卑下るに縁て我災害を彼の世に降さずして其子の世に災害を彼の家に降すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'スリアとイスラエルの間に戰爭なくして三年を經たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, '第三年にユダの王ヨシヤパテ、イスラエルの王の所に降れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'イスラエルの王其臣僕に言けるはギレアデのラモテは我儕の所有なるを爾等知や然るに我儕はスリアの王の手より之を取ることをせずして默しをるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, '彼ヨシヤパテに言けるは爾我と共にギレアデのラモテに戰ひにゆくやヨシヤパテ、イスラエルの王にいひけるは我は爾のごとくわが民は爾の民の如くわが馬は爾の馬の如しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'ヨシヤパテ、イスラエルの王に言けるは請ふ今日ヱホバの言を問へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, '是においてイスラエルの王預言者四百人許を集めて之に言けるは我ギレアデのラモテに戰ひにゆくべきや又は罷べきや彼等曰けるは上るべし主之を王の手に付したまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'ヨシヤパテ曰けるは外に我儕の由て問べきヱホバの預言者此にあらざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'イスラエルの王ヨシヤパテに言けるは外にイムラの子ミカヤ一人あり之に由てヱホバに問ふことを得ん然ど彼は我に關て善事を預言せず唯惡事のみを預言すれば我彼を惡むなりとヨシヤパテ曰けるは王然言たまふなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, '是によりてイスラエルの王一箇の官吏を呼てイムラの子ミカヤを急ぎ來らしめよと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'イスラエルの王およびユダの王ヨシヤパテ朝衣を著てサマリアの門の入口の廣場に各其位に坐しゐたり預言者は皆其前に預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'ケナアナの子ゼデキヤ鐵の角を造りて言けるはヱホバ斯言給ふ爾是等を以てスリア人を抵觸て之を盡すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, '預言者皆斯預言して言ふギレアデのラモテに上りて勝利を獲たまへヱホバ之を王の手に付したまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, '茲にミカヤを召んとて往たる使者之に語りて言けるは預言者等の言一の口の如くにして王に善し請ふ汝の言を彼等の一人の言の如くならしめて善事を言へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'ミカヤ曰けるはヱホバは生くヱホバの我に言たまふ事は我之を言んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'かくて彼王に至るに王彼に言けるはミカヤよ我儕ギレアデのラモテに戰ひに往くべきや又は罷べきや彼王に言けるは上りて勝利を得たまへヱホバ之を王の手に付したまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, '王彼に言けるは我幾度汝を誓はせたらば汝ヱホバの名を以て唯眞實のみを我に告るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, '彼言けるは我イスラエルの皆牧者なき羊のごとく山に散をるを見たるにヱホバ是等の者は主なし各安然に其家に歸るべしと言たまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'イスラエルの王ヨシヤパテに言けるは我汝に彼は我について善き事を預言せず唯惡き事のみを預言すと告たるにあらすやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'ミカヤ言けるは然ば汝ヱホバの言を聽べし我ヱホバの其位に坐しゐたまひて天の萬軍の其傍に右左に立つを見たるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'ヱホバ言たまひけるは誰かアハブを誘ひて彼をしてギレアデのラモテに上りて弊れしめんかと則ち一は此の如くせんと言ひ一は彼の如くせんといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, '遂に一の霊進み出てヱホバの前に立ち我彼を誘はんと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'ヱホバ彼に何を以てするかと言たまふに我出て虚言を言ふ霊となりて其諸の預言者の口にあらんと言りヱホバ言たまひけるは汝は誘ひ亦之を成し遂ん出て然なすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, '故に視よヱホバ虚言を言ふ霊を爾の此諸の預言者の口に入たまへり又ヱホバ爾に關て災禍あらんことを言たまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'ケナアナの子ゼデキヤ近よりてミカヤの頬を批て言けるはヱホバの霊何途より我を離れゆきて爾に語ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'ミカヤいひけるは爾奧の間に入て身を匿す日に見るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'イスラエルの王言けるはミカヤを取て之を邑の宰アモンと王の子ヨアシに曳かへりて言ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, '王斯言ふ此を牢に置れて苦惱のパンと苦惱の水を以て之を養ひ我が平安に來るを待てと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'ミカヤ言けるは爾若眞に平安に歸るならばヱホバ我によりて言たまはざりしならん又曰けるは爾等民よ皆聽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'かくてイスラエルの王とユダの王ヨシヤパテ、ギレアデのラモテに上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'イスラエルの王ヨシヤパテに言けるは我装を改て戰陣の中に入らん然ど爾は王衣を衣るべしとイスラエルの王装を改て戰陣の中にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'スリアの王其戰車の長三十二人に命じて言けるは爾等小者とも大者とも戰ふなかれ惟イスラエルの王とのみ戰へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, '戰車の長等ヨシヤパテを見て是必ずイスラエルの王ならんと言ひ身をめぐらして之と戰はんとしければヨシヤパテ號呼れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, '戰車の長彼がイスラエルの王にあらざるを見しかば之を追ふことをやめて返れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, '茲に一個の人偶然弓を挽てイスラエルの王の胸當と艸摺の間を射たりければ彼其御者に言けるは我傷を受たれば爾の手を旋して我を軍中より出すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, '是日戰爭嚴くなりぬ王は車の中に扶持られて立ちスリア人に對ひをりしが晩景にいたりて死たり創の血車の中に流る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, '日の沒る頃軍中に呼はりて曰ふあり各其邑に各其郷に歸るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, '王死て携へられてサマリアに至りたれば衆人王をサマリアに葬れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, '又其車をサマリアの池に濯ひけるに犬其血を舐たり又遊女其所に身をあらへりヱホバの言たまへる言の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'アハブの其餘の行爲と凡て其爲たる事と其建たる象牙の家と其建たる諸の邑はイスラエルの王の歴代志の書に記載るにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'アハブ其父祖と共に寝りて其子アハジア之にかはりて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'アサの子ヨシヤパテ、イスラエルの王アハブの第四年にユダの王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'ヨシヤパテ王となりし時三十五歳なりしがエルサレムにおいて二十五年王たりき其母の名はアズバといひてシルヒの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'ヨシヤパテ其父アサの諸の道に歩行み轉て之を離れずヱホバの目に適ふ事をなせり但し崇邱は除かざりき民尚崇邱に犠牲を献げ香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'ヨシヤパテ、イスラエルの王と和好を結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'ヨシヤパテの其餘の行爲と其なせる功績および如何に戰爭をなせしかはユダの王の歴代志の書に記載るにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, '彼其父アサの世に尚ほありし彼の男色を行ふ者の殘餘を國の中より逐はらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, '當時エドムには王なくして代官王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'ヨシヤパテ、タルシシの船を造りて金を取ためにオフルに往しめんとしたりしが其船エジオンゲベルに壞れたれば遂に往に至らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, '是においてアハブの子アハジア、ヨシヤパテに言けるはわが僕をして爾の僕と偕に船にて往しめよと然どヨシヤパテ聽ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'ヨシヤパテ其父祖とともに寝りて其父ダビデの城邑に其父祖と共に葬らる其子ヨラム之に代て王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'アハブの子アハジア、ユダの王ヨシヤパテの第十七年にサマリアにてイスラエルの王となり二年イスラエルを治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, '彼はヱホバの目のまへに惡をなし其父の道と其母の道および彼のイスラエルに罪を犯させたるネバテの子ヤラベアムの道に歩行み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'バアルに事へて之を拝みイスラエルの神ヱホバの怒を激せり其父の凡て行へるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'アハブの死しのちモアブ、イスラエルにそむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'アハジヤ、サマリヤにあるその樓の欄杆よりおちて病をおこせしかば使を遣さんとして之にいひけるは往てエクロンの神バアルゼブブにわがこの病の愈るや否を問べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, '時にヱホバの使テシベ人エリヤにいひけるは起てサマリヤ王の使にあひて之に言べし汝等がエクロンの神バアルゼブブに問んとてゆくはイスラエルに神なきがゆゑなるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, '是によりてヱホバかくいふ汝はその登りし牀より下ることなかるべし汝かならず死んとエリヤ乃ち往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, '使者たちアハジアに返りければアハジア彼等に何故に返りしやといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'かれら之にいひけるは一箇の人上りきたりて我らに會ひわれらにいひけるは往てなんぢらを遣はせし王の所にかへり之にいふべしヱホバ斯いひたまふなんぢエクロンの神バアルゼブブに問んとて人を遣すはイスラエルに神なきがゆゑなるか然ば汝その登りし牀より下ることなかるべし汝かならず死んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'アハジア彼等にいひけるはそののぼりきたりて汝等に會ひ此等の言を汝らに告たる人の形状は如何なりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'かれら對へていひけるはそれは毛深き人にして腰に革の帶をむすび居たり彼いひけるはその人はテシベ人エリヤなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, '是に於て王五十人の長とその五十人をエリヤの所に遣はせり彼エリヤの所に上りゆくに視よエリヤは山の嶺に坐し居たりかれエリヤにいひけるは神の人よ王いひたまふ下るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'エリヤこたへて五十人の長にいひけるはわれもし神の人たらば火天より降りて汝と汝の五十人とを燒盡すべしと火すなはち天より降りて彼とその五十人とを燒盡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'アハジアまた他の五十人の長とその五十人をエリヤに遣せりかれ上りてエリヤにいひけるは神の人よ王かく言たまふ速かに下るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'エリヤ答て彼にいひけるはわれもし神の人たらば火天より降りて爾となんぢの五十人を燒盡すべしと神の火すなはち天より降りてかれとその五十人を燒盡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'かれまた第三の五十人の長とその五十人を遣せり第三の五十人の長のぼりいたりてエリヤのまへに跪きこれに願ひていひけるは神の人よ願くはわが生命となんぢの僕なるこの五十人の生命をなんぢの目に貴重き者と見なしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, '視よ火天より降りて前の五十人の長二人とその五十人を燒盡せり然どわが生命をば汝の目に貴重き者となしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, '時にヱホバの使エリヤに云けるはかれとともに下れかれをおそるることなかれとエリヤすなはち起てかれとともに下り王の許に至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, '之にいひけるはヱホバかくいひたまふ汝エクロンの神バアルゼブブに問んとて使者を遣るはイスラエルにその言を問ふべき神なきがゆゑなるか是によりて汝はその登し牀より下ることなかるべし汝かならず死んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, '彼エリヤの言たるヱホバの言の如く死けるが彼に子なかりしかばヨラムこれに代りて王となれり是はユダの王ヨシヤパテの子ヨラムの二年にあたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'アハジヤのなしたる其餘の事業はイスラエルの王の歴代志の書に記載さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'ヱホバ大風をもてエリヤを天に昇らしめんとしたまふ時エリヤはエリシヤとともにギルガルより出往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'エリヤ、エリシヤにいひけるは請ふここに止まれヱホバわれをベテルに遣はしたまふなりとエリシヤいひけるはヱホバは活く汝の霊魂は活く我なんぢをはなれじと彼等つひにベテルに下れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'ベテルに在る預言者の徒エリシヤの許に出きたりて之にいひけるはヱホバの今日なんぢの主をなんぢの首の上よりとらんとしたまふを汝知やかれいふ然りわれ知り汝等默すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'エリヤかれにいひけるはエリシヤよ請ふ汝ここに止れヱホバわれをヱリコに遣したまふなりとエリシヤいふヱホバは活くなんぢの霊魂は活く我なんぢを離じとかれらヱリコにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'ヱリコに在る預言者の徒エリシヤに詣りて彼にいひけるはヱホバの今日なんぢの主をなんぢの首の上よりとらんとしたまふを汝知るやエリシヤ言ふ然り知り汝ら默すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'エリヤまたかれにいひけるは請ふここに止れヱホバわれをヨルダンにつかはしたまふなりとかれいふヱホバは活くなんぢの霊魂は活くわれ汝をはなれじと二人進ゆくに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, '預言者の徒五十人ゆきて遥に立て望めり彼ら二人はヨルダンの濱に立けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'エリヤその外套をとりて之を巻き水をうちけるに此旁と彼旁にわかれたれば二人は乾ける土の上をわたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, '渉りける時エリヤ、エリシヤにいひけるは我が取れてなんぢを離るる前に汝わが汝になすべきことを求めよエリシヤいひけるはなんぢの霊の二の分の我にをらんことを願ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'エリヤいひけるは汝難き事を求む汝もしわが取れてなんぢを離るるを見ばこの事なんぢにならんしからずば此事なんぢにならじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, '彼ら進みながら語れる時火の車と火の馬あらはれて二人を隔てたりエリヤは大風にのりて天に昇れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'エリシヤ見てわが父わが父イスラエルの兵車よその騎兵よと叫びしが/再びかれを見ざりき是においてエリシヤその衣をとらへて之を二片に裂き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'エリヤの身よりおちたるその外套をとりあげ返りてヨルダンの岸に立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'エリヤの身よりおちたる外套をとりて水をうちエリヤの神ヱホバはいづくにいますやと言ひ而して己も水をうちけるに水此旁と彼旁に分れたればエリシヤすなはち渡れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'ヱリコにある預言者の徒對岸にありて彼を見て言けるはエリヤの霊エリシヤの上にとどまるとかれら來りてかれを迎へその前に地に伏て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'かれにいひけるは僕等に勇力者五十人あり請ふかれらをして往てなんぢの主を尋ねしめよ恐くはヱホバの霊かれを曳あげてこれを或山か或谷に放ちしならんとエリシヤ遣すなかれと言けれども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'かれら彼の愧るまでに強ければすなはち遣せといへり是に於てかれら五十人の者を遣しけるが三日の間たづねたれども彼を看いださざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'エリシヤの尚ヱリコに止れる時かれら返りてかれの許にいたりしにエリシヤかれらに言けるはわれ往ことなかれと汝らにいひしにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, '邑の人々エリシヤにいひけるは視よ吾主の見たまふごとく此邑の建る處は善しされど水あしくしてこの地流產をおこす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'かれ言けるは新しき皿に鹽を盛て我に持ち來れよと乃ちもちきたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, '彼いでて水の源に至り鹽を其處になげ入ていひけるはヱホバかくいひたまふわれこの水を愈す此處よりして重て死あるひは流產おこらじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, '其水すなはちエリシヤのいひし如くに愈て今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'かれそこよりベテルに上りしが上りて途にありけるとき小童等邑よりいでて彼を嘲り彼にむかひて禿首よのぼれ禿首よのぼれといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'かれ回轉りてかれらをみヱホバの名をもてかれらを呪詛ひければ林の中より二頭の牝熊出てその兒子輩の中四十二人をさきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'かれ彼處よりカルメル山にゆき其處よりサマリヤにかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'ユダの王ヨシヤパテの十八年にアハブの子ヨラム、サマリヤにありてイスラエルを治め十二年位にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'かれはヱホバの目のまへに惡をなせしかどもその父母の如くはあらざりきそは彼その父の造りしバアルの像を除きたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'されど彼はかのイスラエルに罪を犯させたるネバテの子ヤラベアムの罪を行ひつづけて之をはなれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'モアブの王メシヤは羊を有つ者にして十萬の羔と十萬の牡羊の毛とをイスラエルの王に納めをりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'アハブの死しのちモアブの王はイスラエルの王にそむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, '是に於てヨラム王其時サマリヤを出てイスラエル人をことごとく集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'また往て人をユダの王ヨシヤパテに遣していはしむモアブの王われに背けり汝われとともにモアブに攻ゆくやと彼いひけるは我上らん我は汝の如くわが民はなんぢの民のごとくまたわが馬は汝の馬の如しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'ヨラムいひけるは我儕いづれの路より上らんかかれいふエドムの曠野の途よりせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'イスラエルの王すなはちユダの王およびエドムの王と共に出ゆきけるが行めぐること七日路にして軍勢とこれにしたがふ家畜の飮むべき水なかりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'イスラエルの王いひけるは嗚呼ヱホバこの三人の王をモアブの手にわたさんと召し集めたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'ヨシヤバテいひけるは我儕が由てヱホバに問ふべきヱホバの預言者此にあらざるやとイスラエルの王の臣僕の一人答へていふエリヤの手に水をそそぎたるシヤパテの子エリシヤ此にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'ヨシヤパテいひけるはヱホバの言彼にありとかくてイスラエルの王およびヨシヤパテとエドムの王かれの許に下りゆきけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'エリシヤ、イスラエルの王に言けるはわれ汝と何の干與あらんや汝の父の預言者と汝の母の預言者の所にゆくべしとイスラエルの王かれにいひけるは然ずそはヱホバこの三人の王をモアブの手に付さんとて召集めたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'エリシヤ言けるはわが事ふる萬軍のヱホバは活く我ユダの王ヨシヤパテのためにするにあらすばかならず汝を顧みず汝を見ざらんものを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, '今樂人をわれにつれ來れと而して樂人の樂をなすにおよびてヱホバの手かれに臨みて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, '彼いひけるはヱホバかくいひたまふ此谷に許多の溝を設けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'それヱホバかく言ひたまふ汝ら風を見ず雨をも見ざるに此谷に水盈て汝等と汝等の家畜および汝らの獣飮ことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, '然るも是はヱホバの目には瑣細き事なりヱホバ、モアブ人をも汝らの手にわたしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, '汝等は保障ある諸の邑と諸の美しき邑とを撃ち諸の佳樹を斫倒し諸の水の井を塞ぎ石をもて諸の善地を壞ふにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'かくて朝におよびて供物を献ぐる時に水エドムの途より流れきたりて水國に充つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, '偖またモアブ人はみな王等の己に攻のぼれるを聞しかば甲を著ることを得る以上の者を盡く集めてその境に備へしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, '朝はやく興いでしに水の上に日昇りゐて對面の水血の如くに赤かりければモアブ人これを見て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'いひけるはこれ乃はち血なり王たち戰ひて死たるならん互に相撃たるなるべし然ばモアブよ掠取に行けと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, '而してモアブ人イスラエルの陣營に至るにイスラエル人起てこれを撃たればすなはちその前より逃はしれり是においてイスラエル人進みてモアブ人を撃てその國にいり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'その邑々を撃圮し各石を諸の善地に投てこれに填し水の井をことごとく塞ぎ佳樹をことごとく斫たふし唯キルハラセテにその石をのこせしのみなるに至る但し石を投るもの周りあるきてこれを撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'モアブ王戰闘の手いたくして當りがたきを見て劍を抜く者七百人をひきゐてエドム王の所にまで衝きいたらんとせしが遂に果さざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, '己の位を継べきその長子をとりてこれを石垣の上にささげて燔祭となしたり是に於てイスラエルに大なる憤怒おこりぬ彼等すなはちかれをすててその國に歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, '預言者の徒の妻の中なる一人の婦人エリシヤに呼はりていひけるは汝の僕なるわが夫死りなんぢの僕のヱホバを畏れしことはなんぢの知るところなり今債主きたりてわが二人の子をとりて奴僕となさんとすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'エリシヤ之にいひけるはわれなんぢの爲に何をなすべきや汝の家に如何なる物あるかわれに告よ彼いひけるは僅少の油のほかは汝の婢の家に有ものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, '彼いひけるは往て外より鄰の人々より器を借よ空たる器を借るべし少許を借るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, '而してなんぢ入て汝の子等とともに戸の内に閉こもりそのすべての器に油をつぎてその盈るところの者をとりのけおくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, '婦人すなはち彼を離れて去りその子等とともに戸の内に閉こもり子等のもちきたる器に油をつぎたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, '器のみな盈たるときその子にむかひ尚われに器をもちきたれといひけるに器はもはやあらずといひたればその油すなはち止る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, '是においてその婦神の人にいたりてかくと告ければかれいふ往て油をうりてその負債をつくのひその餘分をもて汝と汝の子等生計をなすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, '一日エリシヤ、シユネムにゆきしに其所に一人の大なる婦人ありてしきりにこれに食をすすめたれば彼かしこを過る毎にそこに入て食をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, '茲にその婦人夫にいひけるは視よ此つねにわれらを過る人は我これを見るに神の聖き人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, '請ふ小き室を石垣の上につくりそこに臥床と案と榻と燭臺をかれのために備へん彼われらに至る時はそこに入るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'かくてのちある日エリシヤそこに至りその室に入てそこに臥たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'その僕ゲハジにむかひ彼のシユナミ人を召きたれといへり彼かの婦人を召たればその前にきたりて立つに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'エリシヤ、ゲハジにいひけるは彼にかく言へ汝かく懇に我らのために意を用ふ汝のために何をなすべきや王または軍勢の長に汝のことを告られんことを望むかと彼答へてわれはわが民の中にをるなりといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'エリシヤいひけるは然ばかれのために何をなすべきやゲハジ答へけるは誠にかれは子なくその夫は老たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, '是においてエリシヤかれを召といひければこれを呼に來りて戸口に立たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'エリシヤいふ明る年の今頃汝子を抱くあらん彼いひけるはいなわが主神の人よなんぢの婢をあざむきたまふなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'かくて婦つひに孕て明る年にいたりてエリシヤのいへるその頃に子を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'その子育ちてある日刈獲人の所にいでゆきてその父にいたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, '父にわが首わが首といひたれば父少者に彼を母のもとに負ゆけと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'すなはちこれを負て母にいたりしに午まで母の膝に坐り居て遂に死たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, '母のぼりゆきてこれを神の人の臥床の上に置きこれをとぢこめて出で');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'その夫をよびていひけるは請ふ一人の僕と一頭の驢馬を我につかはせ我神の人の許にはせゆきて歸らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, '夫いふ何故に汝は今日かれにいたらんとするや今日は朔日にもあらず安息日にもあらざるなり彼いひけるは宜しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, '婦すなはち驢馬に鞍おきてその僕にいひけるは驅て進め吾が命ずることなくば我が騎すすむることに緩漫あらしめざれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'つひにカルメル山にゆきて神の人にいたるに/神の人遥にかれの來るを見て僕ゲハジにいひけるは視よかしこにかのシユナミ人をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, '請ふ汝はしりゆきて彼をむかへて言へなんぢは平安なるやなんぢの夫はやすらかなるやなんぢの子はやすらかなるやと彼こたへて平安なりといひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, '遂に山にきたりて神の人にいたりその足を抱きたればゲハジこれを逐ひはらはんとて近よりしに神の人いひけるは容しおけ彼は心の中に苦あるなりまたヱホバその事を我にかくしていまだわれに告たまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, '婦いひけるはわれわが主に子を求めしやわれをあざむきたまふなかれとわれは言ざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'エリシヤすなはちゲハジにいひけるはなんぢ腰をひきからげわが杖を手にもちて行け誰に逢も禮をなすべからず又なんぢに禮をなす者あるともそれに答ふることなかれわが杖をかの子の面の上におけよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'その子の母いひけるはヱホバは活くなんぢの霊魂は生く我は汝を離れじと是をもてエリシヤついに起て婦に從ひ行ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'ゲハジはかれらに先だちゆきて杖をかの子の面の上に置たるが聲もなく聞もせざりしかばかへりきたりてエリシヤに逢てこれに子いまだ目をさまさずと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'エリシヤここにおいて家に入て視に子は死ておのれの臥床の上に臥てあれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'すなはち入り戸をとぢて二人内におりてヱホバに祈り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, '而してエリシヤ上りて子の上に伏し己が口をその口におのが目をその目に己が手をその手の上にあて身をもてその子を掩しに子の身體やうやく温まり來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'かくしてエリシヤかへり來て家の内に其處此處とあゆみをり又のぼりて身をもて子をおほひしに子七度嚏して目をひらきしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'ゲハジを呼てかのシユナミ人をよべと言ければすなはちこれを呼り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, '彼入來りしかばエリシヤなんぢの子を取ゆけと言りかれすなはち入りてエリシヤの足下に伏し地に身をかがめて其子を取あげて出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, '斯てエリシヤまたギルガルにいたりしがその地に饑饉あり預言者の徒その前に坐しをる是において彼その僕にいひけるは大なる釜をすゑて預言者の徒のために羹を煮よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, '時に一人田野にゆきて菜蔬を摘しが野籐のあるを見て其より野瓜を一風呂鋪摘きたりて羹の釜の中に截こみたり其は皆それをしらざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, '斯てこれを盛て人々に食はせんとせしに彼等その羹を食はんとするにあたりて叫びて嗚呼神の人よ釜の中に死をきたらする者ありといひて得食はざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'エリシヤさらば粉をもちきたれといひてこれを釜になげ入れ盛て人々に食しめよと言り釜の中にはすなはち害物あらずなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, '茲にバアルシヤリシヤより人來り初穂のパンと大麥のパン二十と圃の初物一袋とを神の人の許にもちいたりたればエリシヤ衆人にあたへて食はしめよと言ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'その奴僕いひけるは如何にとや我これを百人の前にそなふべきかと然るに彼また言ふ衆人にあたへて食しめよ夫ヱホバかくいひたまふかれら食ふて尚あます所あらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'すなはち之をその前にそなへたればみな食ふてなほ餘せりヱホバの言のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'スリア王の軍勢の長ナアマンはその主君のまへにありて大なる者にしてまた貴き者なりき是はヱホバ曾て彼をもてスリアに拯救をほどこしたまひしが故なり彼は大勇士なりしが癩病をわづらひ居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, '昔にスリア人隊を組ていでたりし時にイスラエルの地より一人の小女を執へゆけり彼ナアマンの妻に事たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'その女主にむかひわが主サマリヤに居る預言者の前にいまさば善らん者をかれその癩病を痊すならんと言たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'ナアマン入りてその主君に告てイスラエルの地よりきたれる女子斯々語りたりと言ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'スリヤ王いひけるは往よ往よ我イスラエルの王に書をおくるべしと是において彼いでゆき銀十タラントと金六千および衣服十襲をたづさヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'イスラエルの王にその書をもちゆけりその文に曰くこの書汝にいたらば視よ我わが臣ナアマンをなんぢに遣はせるなりこは汝にその癩病を痊されんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'イスラエルの王その書を讀み衣を裂ていふ我神ならんや爭か殺すことをなし生すことをなしえん然るに此人なんぞ癩病の人を我に遣はしてこれを痊さしめんとするや然ば請ふ汝等彼が如何に我に爭を求むるかを見て知れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, '茲に神の人エリシヤ、イスラエルの王がその衣を裂たることをきき王に言遣しけるは汝何とて汝の衣をさきしや彼をわがもとにいたらしめよ然ば彼イスラエルに預言者のあることを知にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, '是においてナアマンその馬と車とをしたがへ來りてエリシヤの家の門に立けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'エリシヤ使をこれに遣して言ふ汝ゆきて身をヨルダンに七たび洗へ然ば汝の肉本にかへりて汝は清く爲べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'ナアマン怒りて去り言けるは我は彼かならず我もとにいできたりて立ちその神ヱホバの名を呼てその所の上に手を動して癩病を痊すならんと思へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'ダマスコの河アバナとパルパルはイスラエルのすべての河水にまさるにあらずや我これらに身を洗ふて清まることを得ざらんやと乃ち身をめぐらし怒りて去る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, '時にその僕等近よりてこれにいひけるは我父よ預言者なんぢに大なる事をなせと命ずるとも汝はそれを爲ざらんや况て彼なんぢに身を洗ひて清くなれといふをやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, '是においてナアマン下りゆきて神の人の言のごとくに七たびヨルダンに身を洗ひしにその肉本にかへり嬰兒の肉の如くになりて清くなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'かれすなはちその從者とともに神の人の許にかへりきたりてその前に立ていふ我いまイスラエルのほかは全地に神なしと知る然ば請ふ僕より禮物をうけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'エリシヤいひけるはわが事へまつるヱホバは活く肯て禮物をうけじとかれ強て之を受しめんとしたれども遂にこれを辭したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'ナアマンいひけるは然ば請ふ騾馬に二駄の土を僕にとらせよ僕は今よりのち他の神には燔祭をも祭品をもささげずして只ヱホバにのみ献げんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'ねがはくは主この事につきて僕をゆるしたまへ即ちわが主君リンモンの宮にいりそこにて崇拝をなしてわが手に倚ることありまた我リンモンの宮にありて身をかがむることあらんわがリンモンの宮において身をかがむる時に願くはヱホバその事につきて僕をゆるしたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'エリシヤ彼になんぢ安じて去れといひければ彼エリシヤをはなれて少しく進みゆきけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, '神の人エリシヤの僕ゲハジいいひけるは吾が主人は此スリア人ナアマンをいたはりて彼が手に携へきたれるものを受ざりしがヱホバは活くわれ彼のあとを追かけて彼より少く物をとらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'ゲハジすなはちナアマンのあとをおひ行くにナアマンはおのれのあとに走り來る者あるを見て車より下りこれを迎へて皆平安やと言ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, '彼言けるは皆平安しわが主我を遣していはしむ只今エフライムの山より預言者の徒なる二人の少者わが許に來れり請ふ汝かれらに銀一タラントと衣二襲をあたへよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'ナアマンいひけるは望むらくは二タラントを取れとてかれを強ひ銀二タラントを二の袋にいれ衣二襲を添て二人の僕に負せたれば彼等これをゲハジの前に負きたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, '彼岡に至りしとき之をかれらの手より取て室のうちにをさめかれらを放ちて去しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, '而して入てその主人のまへに立つにエリシヤこれにいひけるはゲハジよ何處より來りしや答へていふ僕は何處にもゆかず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'エリシヤいひけるはその人が車をはなれ來りてなんぢを迎へし時にわが心其處にあらざりしや今は金をうけ衣をうけ橄欖園葡萄園羊牛僕婢をうくべき時ならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, '然ばナアマンの癩病はなんぢにつき汝の子孫におよびて限なからんと彼その前より退ぞくに癩病發して雪のごとくになりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, '茲に預言者の徒エリシヤに言けるは視よ我儕が汝とともに住ふ所はわれらのために隘し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, '請ふ我儕をしてヨルダンに往しめよ我儕おのおの彼處より一の材木を取て其處に我儕の住べき處を設けんエリシヤ往よと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, '時にその一人希はくは汝も僕等と共に往けと言ければエリシヤ答へて我ゆかんと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'エリシヤかく彼等とともに往り彼等すなはちヨルダンにいたりて樹を砍りたふしけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, '一人の材木を砍りたふすに方りてその斧水におちいりしかば叫びて嗚呼主よ是は乞得たる者なりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, '神の人其は何處におちいりしやと言ふにその處をしらせしかば則ち枝を切おとして其處に投いれてその斧を浮ましめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, '汝これを取れと言ければその人手を伸てこれを取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, '茲にスリアの王イスラエルと戰ひをりその臣僕と評議して斯々の處に我陣を張んと言たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, '神の人イスラエルの王に言おくりけるは汝愼んで某の處を過るなかれ其はスリア人其處に下ればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'イスラエルの王是において神の人が己に告げ己に敎たる處に人を遣して其處に自防しこと一二回に止まらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, '是をもてスリアの王是事のために心をなやましその臣僕を召て我儕の中誰がイスラエルの王と通じをるかを我に告ざるやと言ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'その臣僕の一人言ふ王わが主よ然るにあらず但イスラエルの預言者エリシヤ汝が寝室にて語る所の言語をもイスラエルの王に告るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, '王いひけるは往て彼が安に居かを見よ我人をやりてこれを執へんと茲に彼はドタンに居ると王に告ていふ者ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, '王そこに馬と車および大軍をつかはせり彼等すなはち夜の中に來りてその邑を取かこみけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, '神の人の從屬夙に興て出て見に軍勢馬と車をもて邑を取かこみ居ればその少者エリシヤに言けるは嗚呼わが主よ我儕如何にすべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'エリシヤ答へけるは懼るなかれ我儕とともにある者は彼等とともにある者よりも多しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'ヱリシヤ祈りて願くはヱホバかれの目を開きて見させたまへと言ければヱホバその少者の眼を開きたまへり彼すなはち見るに火の馬と火の車山に盈てエリシヤの四面に在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'スリア人エリシヤの所に下りいたれる時エリシヤ、ヱホバに祈りて言ふ願くは此人々をして目昏しめたまへと即ちエリシヤの言のごとくにその目を昏しめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, '是においてエリシヤ彼らに言けるは是はその途にあらず是はその城にもあらず我に從ひて來れ我汝らを汝らが尋ぬる人の所に携ゆかんとて彼等をサマリヤにひき至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, '彼等がサマリヤに至りし時エリシヤ言けるはヱホバよ此人々の目をひらきて見させたまへと即ちヱホバかれらの目を開きたまひたれば彼等見るにその身はサマリヤの中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'イスラエルの王かれらを見てエリシヤに言けるはわが父よ我撃殺すべきや撃殺すべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'エリシヤ答けるは撃殺すべからず汝劍と弓をもて擄にせる者等を撃殺すことを爲んやパンと水と彼らの前にそなへて食飮せしめてその主君に往しむべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, '王すなはちかれらの爲に大なる饗宴をまうけ其食飮ををはるに及びてこれを去しめたればすなはち其主君に歸れり是をもてスリアの兵ふたたびイスラエルの地に入ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, '此後スリアの王ベネハダデその全軍を集めて上りきたりてサマリヤを攻圍みければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'サマリヤ大に糧食に乏しくなれり即ちかれら之を攻かこみたれば遂に驢馬の頭一箇は銀八十枚にいたり鳩の糞一カブの四分の一は銀五枚にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, '茲にイスラエルの王石垣の上を通りをる時一人の婦人かれに呼はりて我主王よ助けたまへと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, '彼言ふヱホバもし汝を助けたまはずば我何をもてか汝を助くることを得ん禾場の物をもてせんか酒榨の中の物をもてせんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, '王すなはち婦に何事なるやと言ば答へて言ふ此婦人我にむかひ汝の子を與へよ我儕今日これを食ひて明日わが子を食ふべしと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, '斯われら吾子を煮てこれを食ひけるが我次の日にいたりて彼にむかひ汝の子を與へよ我儕これを食はんと言しに彼その子を隱したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, '王その婦人の言を聞て衣を裂き而して石垣の上を通りをりしが民これを見るにその膚に麻布を著居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, '王言けるは今日シヤパテの子エリシヤの首その身の上にすわりをらば神われに斯なしまた重ねてかく成たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, '時にエリシヤはその家に坐しをり長老等これと共に坐し居る王すなはち己の所より人を遣しけるがエリシヤはその使者の未だ己にいたらざる前に長老等に言ふ汝等この人を殺す者の子が我の首をとらんとて人を遣はすを見るや汝等觀てその使者至らば戸を閉てこれを戸の内にいるるなかれ彼の主君の足音その後にするにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, '斯彼等と語をる間にその使者かれの許に來りしが王もつづいて來り言けるは此災はヱホバより出たるなり我なんぞ此上ヱホバを待べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'エリシヤ言けるは汝らヱホバの言を聽けヱホバかく言たまふ明日の今頃サマリヤの門にて麥粉一セアを一シケルに賣り大麥二セアを一シケルに賣にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, '時に一人の大將すなはち王のその手に依る者神の人に答へて言けるは由やヱホバ天に窓をひらきたまふも此事あるべけんやエリシヤいひけるは汝は汝の目をもて之を見ん然どこれを食ふことはあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, '茲に城邑の門の入口に四人の癩病人をりしが互に言けるは我儕なんぞ此に坐して死るを待べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, '我ら若邑にいらんと言ば邑には食物竭てあれば我ら其處に死んもし又此に坐しをらば同く死ん然ば我儕ゆきてスリアの軍勢の所にいたらん彼ら我らを生しおかば我儕生ん若われらを殺すも死るのみなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'すなはちスリア人の陣營にいたらんとて黄昏に起あがりしがスリアの陣營の邊にいたりて視に一人も其處にをる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, '是より先に主スリアの軍勢をして車の聲馬の聲大軍の聲を聞しめたまひしかば彼ら互に言けるは視よイスラエルの王われらに敵せんとてヘテ人の王等およびエジプトの王等を傭ひきたりて我らを襲はんとすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'すなはち黄昏に起て逃げその天幕と馬と驢馬とを棄て陣營をその儘になしおき生命を全うせんとて逃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'かの癩病人等陣營の邊に至りしが遂に一の天幕にいりて食飮し其處より金銀衣服を持さりて往てこれを隱し又きたりて他の天幕にいり其處よりも持さりて往てこれを隱せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'かくて彼等互に言けるは我儕のなすところ善らず今日は好消息ある日なるに我儕は默し居る若夜明まで待ば菑害身におよばん然ば來れ往て王の眷屬に告んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'すなはち來りて邑の門を守る者を呼びこれに告て言けるは我儕スリア人の陣營にいたりて視に其處には一人も居る者なく亦人の聲もせず但馬のみ繋ぎてあり驢馬のみ繋ぎてあり天幕は其儘なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, '是において門を守る者呼はりてこれを王の家の中に報せたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, '王夜の中に興いでてその臣下に言けるは我スリア人が我儕になせる所の如何を汝等に示さん彼等はわれらの饑たるを知が故に陣營を去て野に隱る是はイスラエル人邑を出なば生擒て邑に推いらんと言て然せるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'その臣下の一人對へて言けるは請ふ尚遺されて邑に存れる馬の中五匹を取しめよ我儕人を遣て窺はしめん視よ是等は邑の中に遺れるイスラエルの全群衆のごとし視よ是等は滅び亡たるイスラエルの全群衆のごとくなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, '是において二輛の戰車とその馬を取り王すなはち往て見よといひて人を遣はしてスリアの軍勢の跡を尾しめたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, '彼らその跡を尾てヨルダンにいたりしが途には凡てスリア人が狼狽逃る時に棄たる衣服と器具盈りその使者かへりてこれを王に告ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, '民いでてスリア人の陣營を掠めたり斯在しかば麥粉一セアは一シケルとなり大麥二セアは一シケルと成るヱホバの言のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, '爰に王その手に依ところの彼大將を立て門を司らしめたるに民門にて彼を踐たれば死り即ち神の人が王のおのれに下り來し時に言たる言のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, '又神の人が王につげて明日の今頃サマリヤの門にて大麥二セアを一シケルに賣り麥粉二セアを一シケルに賣にいたらんと言しごとくに成ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, '彼大將その時に神の人にこたへてヱホバ天に窓をひらきたまふも此事あるべけんやと言たりしかば答へて汝目をもてこれを見べけれどもこれを食ふことはあらじと言たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'そのごとくになりぬ即ち民門にてかれを踐て死しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'エリシヤ甞てその子を甦へらせて與へし婦に言しことあり曰く汝起て汝の家族とともに往き汝の寄寓んとおもふ處に寄寓れ其はヱホバ饑饉を呼くだしたまひたれば七年の間この地に臨むべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, '是をもて婦起て神の人の言のごとくに爲しその家族とともに往てペリシテ人の地に七年寄寓ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'かくて七年を經て後婦人ペリシテ人の地より歸りしが自己の家と田畝のために王に呼もとめんとて往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, '時に王は神の人の僕ゲハジにむかひ請ふエリシヤが爲し諸の大なる事等を我に告よと言てこれと談話をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, '即ち彼エリシヤが死人を甦らせしことを王にものがたりをる時にその子を彼が甦らせし婦自己の家と田畝のために王に呼もとめければゲハジ言ふわが主王よ是すなはちその婦人なり是すなはちエリシヤが甦らせしその子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, '王すなはちその婦に尋ねけるにこれを陳たれば王彼のために一人の官吏を派出して言ふ凡て彼に屬する物並に彼がこの地を去し日より今にいたるまでの其田畝の產出物を悉く彼に還せよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'エリシヤ、ダマスコに至れる事あり時にスリアの王ベネハダデ病にかかりをりしがこれにつげて神の人此にきたると言ふ者ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, '王ハザエルに言ふ汝手に禮物をとり往て神の人を迎へ彼によりてヱホバに吾この病は愈るやと言て問へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, '是においてハザエルかれを迎へんとて出往きダマスコのもろもろの佳物駱駝に四十駄を禮物に携へて到りて彼の前に立ち曰けるは汝の子スリアの王ベネハダデ我を汝につかはして吾この病は愈るやと言しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'エリシヤかれに言けるは往てかれに汝はかならず愈べしと告よ但しヱホバかれはかならず死んと我にしめしたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, '而して神の人瞳子をさだめて彼の羞るまでに見つめ乃て哭いでたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'ハザエルわが主よ何て哭たまふやと言ふにエリシヤ答へけるは我汝がイスラエルの子孫になさんところの害惡を知ばなり即ち汝は彼等の城に火をかけ壯年の人を劍にころし子等を挫ぎ孕女を刳ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'ハザエル言けるは汝の僕は犬なるか何ぞ斯る大なる事をなさんエリシヤ答へけるはヱホバ我にしめしたまふ汝はスリアの王となるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, '斯て彼エリシヤを離れて去てその主君にいたるにエリシヤは汝に何と言しやと尋ければ答へて彼汝はかならず愈るあらんと我に告たりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, '翌日にいたりてハザエル粗き布をとりて水に浸しこれをもて王の面を覆ひたれば死りハザエルすなはち之にかはりて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'イスラエルの王アハブの子ヨラムの五年にはヨシヤパテ尚ユダの王たりき此年にユダの王ヨシヤバテの子ヨラム位に即り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, '彼は位に即し時三十二歳にして八年の間エルサレムにて世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, '彼はアハブの家のなせるがごとくにイスラエルの王等の道を行へりアハブの女かれの妻なりければなり斯彼はヱホバの目の前に惡をなせしかども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'ヱホバその僕ダビデのためにユダを滅すことを好みたまはざりき即ち彼にその子孫によりて恒に光明を與んと言たまひしがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'ヨラムの代にエドム叛きてユダの手に服せず自ら王を立たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'ヨラムその一切の戰車をしたがへてザイルに渉りしが遂に夜の中に起あがりて自己を圍めるエドム人を撃ちその戰車の長等を撃り斯して民はその天幕に逃ゆきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'エドムは斯叛きてユダの手に服せずなりしが今日まで然り此時にあたりてリブナもまた叛けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'ヨラムのその餘の行爲およびその凡て爲たる事等はユダの王の歴代志の書に記さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'ヨラムその先祖等とともに寝りてダビデの邑にその先祖たちと同じく葬られその子アハジアこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'イスラエルの王アハブの子ヨラムの十二年にユダの王ヨラムの子アハジア位に即り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'アハジアは位に即し時二十二歳にしてエルサレムにて一年世を治めたりその母はイスラエルの王オムリの孫女にして名をアタリヤといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'アハジアはアハブの家の道にあゆみアハブの家のごとくにヱホバの目の前に惡をなせり是かれはアハブの家の婿なりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, '茲にアハブの子ヨラム自身ゆきてスリアの王ハザエルとギレアデのラモテに戰ひけるがスリア人等ヨラムに傷を負せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, '是に於てヨラム王はそのスリアの王ハザエルと戰ふにあたりてラマに於てスリア人に負せられたるところの傷を療さんとてヱズレルに歸れりユダの王ヨラムの子アハジアはアハブの子ヨラムが病をるをもてヱズレルに下りて之を訪ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, '茲に預言者エリシヤ預言者の徒一人を呼てこれに言ふ汝腰をひきからげ此膏の瓶を手にとりてギレアデのラモテに往け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, '而して汝かしこに到らばニムシの子なるヨシヤパテの子ヱヒウを其處に尋獲て内に入り彼をその兄弟の中より起しめて奧の間につれゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, '膏の瓶をとりその首に灌ぎて言へヱホバかく言たまふ我汝に膏をそそぎてイスラエルの王となすと而して戸を開きて逃されよ止ること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, '是において預言者の僕なるその少者ギレアデのラモテに往けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, '到りて見るに軍勢の長等坐してをりければ將軍よ我汝に告べき事ありと言ふにヱヒウこたへて我儕諸人の中の誰にかと言たれば將軍よ汝にと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'ヱヒウすなはち起て家にいりければ彼その首に膏をそそぎて之に言ふイスラエルの神ヱホバかく言たまふ我汝に膏をそそぎてヱホバの民イスラエルの王となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, '汝はその主アハブの家を撃ほろぼすべし其によりて我わが僕なる預言者等の血とヱホバの諸の僕等の血をイゼベルの身に報いん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'アハブの家は全く滅亡べしアハブに屬する男はイスラエルにありて繋がれたる者も繋がれざる者もともに之を絶べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, '我アハブの家をネバテの子ヤラベアムの家のごとくに爲しアヒヤの子バアシヤの家のごとくになさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'ヱズレルの地において犬イゼベルを食ふべし亦これを葬るものあらじと而して戸を啓きて逃されり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'かくてヱヒウその主の臣僕等の許にいできたりたれば一人之に言ふ平安なるやこの狂る者何のために汝にきたりしやヱヒウこたへて汝等はかの人を知りまたその言ところを知なりと言ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, '彼等言けらく謊なり其を我儕に告よと是においてヱヒウ言けるは彼斯々我につげて言りヱホバかく言たまふ我汝に膏をそそぎてイスラエルの王となすと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, '彼等すなはち急ぎて各人その衣服をとりこれを階の上ヱヒウの下に布き喇叭を吹てヱヒウは王たりと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'ニムシの子なるヨシヤバテの子ヱヒウ斯ヨラムに叛けり(ヨラムはイスラエルを盡くひきゐてギレアデのラモテに於てスリアの王ハザエルを禦ぎたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'ヨラム王はそのスリアの王ハザエルと戰ふ時にスリア人に負せられたるところの傷を痊さんとてヱズレルに歸りてをる)ヱヒウ言けるは若なんぢらの心にかなはば一人もこの邑より走いでてこれをヱズレルに言ふ者なからしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'ヱヒウすなはちヱズレルをさして乗往りヨラムかしこに臥をればなりまたユダの王アハジアはヨラムを訪に下りてをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'ヱズレルの戌樓に一箇の守望者立をりしがヱヒウの群衆のきたるを見て我群衆を見るといひければヨラム言ふ一人を馬に乗て遣し其に會しめて平安なるやと言しめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, '是において一人馬にて行てこれに會ひ王かく宣まふ平安なるやと言ふにヱヒウ言けるは平安は汝の與るところならんや吾後にまはれと守望者また告て言ふ使者かれらの許に往たるが歸り來ずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, '是をもて再び人を馬にて遣したればその人かれらに到りて王かく宣まふ何か變事あるやと言ふにヱヒウ答て平安は汝の與るところならんや吾後にまはれと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, '守望者また告て言ふ彼も彼等の所にまで到りしが歸り來ずその車を趨するはニムシの子ヱヒウが趨するに似狂ふて趨らせ來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, '是においてヨラム車を整へよと言ひけるが車整ひたればイスラエルの王ヨラムとユダの王アハジアおのおのその車にて出たり即ちかれらヱヒウにむかひて出きたりヱズレル人ナボテの地にて之に會けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'ヨラム、ヱヒウを見てヱヒウよ平安なるやといひたればヱヒウこたへて汝の母イゼベルの姦淫と魔術と斯多かれば何の平安あらんやと云り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'ヨラムすなはち手をめぐらして逃げアハジアにむかひ反逆なりアハジアよと言ふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'ヱヒウ手に弓をひきしぼりてヨラムの肩の間を射たればその矢かれの心をいぬきて出で彼は車の中に偃ししづめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'ヱヒウその將ビデカルに言けるは彼をとりてヱズレル人ナボテの地の中に投すてよ其は汝憶ふべし甞て我と汝と二人ともに乗て彼の父アハブに從へる時にヱホバ斯かれの事を預言したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '曰くヱホバ言ふ誠に我昨日ナボテの血とその子等の血を見たりヱホバ言ふ我この地において汝にむくゆることあらんと然ば彼をとりてその地になげすててヱホバの言のごとくにせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'ユダの王アハジアはこれを視て園の家の途より逃ゆきけるがヱヒウその後を追ひ彼をも車の中に撃ころせと言しかばイブレアムの邊なるグルの坂にてこれを撃たればメギドンまで逃ゆきて其處に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'その臣僕等すなはち之を車にのせてエルサレムにたづさへゆきダビデの邑においてかれの墓にその先祖等とおなじくこれを葬れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'アハブの子ヨラムの十一年にアハジアはユダの王となりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, '斯てヱヒウ、ヱズレルにきたりしかばイゼベル聞てその目を塗り髮をかざりて窓より望みけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'ヱヒウ門に入きたりたればその主を弑せしジムリよ平安なるやと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'ヱヒウすなはち面をあげて窓にむかひ誰か我に與ものあるや誰かあるやと言けるに二三の寺人ヱヒウを望みたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, '彼を投おとせと言りすなはち之を投おとしたればその血牆と馬とにほどばしりつけりヱヒウこれを踏とほれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, '斯て彼内にいりて食飮をなし而して言けるは往てかの詛はれし婦を見これを葬れ彼は王の女子なればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, '是をもて彼を葬らんとて往て見るにその頭骨と足と掌とありしのみなりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, '歸りで彼につぐるに彼言ふ是すなはちヱホバがその僕なるテシベ人エリヤをもて告たまひし言なり云くヱズレルの地において犬イゼベルの肉を食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'イゼベルの屍骸はヱズレルの地に於て糞土のごとくに野の表にあるべし是をもて是はイゼベルなりと指て言ふこと能ざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'アハブ、サマリヤに七十人の子あり茲にヱヒウ書をしたためてサマリヤにおくり邑の牧伯等と長老等とアハブの子等の師傳等とに傳へて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '汝らの主の子等汝らとともにあり又汝等は車も馬も城もあり且武器もあれば此書汝らの許にいたらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, '汝らの主の子等の中より最も優れる方正き者を選みだ出してその父の位に置ゑ汝等の主の家のために戰へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, '彼ら大に恐れて言ふ二人の王等すでに彼に當ることを得ざりしなれば我儕いかでか當ることを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, '乃ち家宰邑宰長老師傳等ヱヒウに言おくりけるは我儕は汝の僕なり凡て汝が我儕に命ずる事を爲ん我儕は王を立るを好まず汝の目に善と見ゆる所を爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, '是においてヱヒウ再度かれらに書をおくりて云ふ汝らもし我に與き我言にしたがふならば汝らの主の子なる人々の首をとりて明日の今頃ヱズレルにきたりて吾許にいたれと當時王の子七十人はその師傳なる邑の貴人等とともに居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'その書かれらに至りしかば彼等王の子等をとらへてその七十人をことごとく殺しその首を籃につめてこれをヱズレルのヱヒウの許につかはせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'すなはち使者いたりてヱヒウに告て人衆王の子等の首をたづさへ來れりと言ければ明朝までそれを門の入口に二山に積おけと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, '朝におよび彼出て立ちすべての民に言ふ汝等は義し我はわが主にそむきて之を弑したり然ど此すべての者等を殺せしは誰なるぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, '然ば汝等知れヱホバがアハブの家につきて告たまひしヱホバの言は一も地に隕ず即ちヱホバはその僕エリヤによりて告し事を成たまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, '斯てヱヒウはアハブの家に屬する者のヱズレルに遺れるを盡く殺しまたその一切の重立たる者その親き者およびその祭司等を殺して彼に屬する者を一人も遺さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'ヱヒウすなはち起て往てサマリヤに至りしがヱヒウ途にある時牧者の集會所において');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'ユダの王アハジアの兄弟等に遇ひ汝等は何人なるやと言けるに我儕はアハジアの兄弟なるが王の子等と王母の子等の安否を問んとて下るなりと答へたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, '彼等を生擒れと言り即ちかれらを生擒りその集會所の穴の側にて彼等四十二人を盡く殺し一人をも遺さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, '斯てヱヒウ其處より進みゆきしがレカブの子ヨナダブの己を迎にきたるに遭ければその安否をとふてこれに汝の心はわが心の汝の心と同一なるがごとくに眞實なるやと言けるにヨナダブ答へて眞實なりと言たれば然ば汝の手を我に伸よと言ひその手を伸ければ彼を挽て己の車に登らしめて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, '言ふ我とともに來りて我がヱホバに熱心なるを見よと斯かれを己の車に乗しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'サマリヤにいたりてアハブに屬する者のサマリヤに遺れるを盡く殺して遂にその一族を滅せりヱホバのエリヤに告たまひし言語のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, '茲にヱヒウ民をことごとく集てこれに言けるはアハブは少くバアルに事たるがヱヒウは大にこれに事へんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, '然ば今バアルの諸の預言者諸の臣僕諸の祭司等を我許に召せ一人も來らざる者なからしめよ我大なる祭祀をバアルのためになさんとするなり凡て來らざる者は生しおかじと但しヱヒウ、バアルの僕等を滅さんとて偽りて斯なせるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'ヱヒウすなはちバアルの祭禮を設よと言ければ之を宣たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, '是てヱヒウあまねくイスラエルに人をつかはしたればバアルの僕たる者皆きたれり一人も來らずして遺れるものはあらざりき彼等バアルの家にいりたればバアルの家は末より末まで充わたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, '時にヱヒウ衣裳を掌どる者てむかひ禮服をとりいだしてバアルの凡の僕等にあたへよといひければすなはち禮服をとりいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, '斯ありてヱヒウはレカブの子ヨナダブとともにバアルの家にいりしがバアルの僕等に言ふ汝等尋ね見て此には只バアルの僕のみあらしめヱホバの僕を一人も汝らの中にあらしめざれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, '彼等犠牲と燔祭を献げんとて入し時ヱヒウ八十人の者を外に置て言ふ凡てわがその手にわたすところの人を一人にても逃れしむる者は己の生命をもてその人の生命に代べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, '期て燔祭を献ぐることの終りし時ヱヒウその士卒と諸將に言ふ入てかれらを殺せ一人をも出すなかれとすなはち刃をもて彼等を撃ころせり而して士卒と諸將これを投いだしてバアルの家の内殿に入り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, '諸の像をバアルの家よりとりいだしてこれを燒り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, '即ちかれらバアルの像をこぼちバアルの家をこぼち其をもて厠を造りしが今日までのこる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'ヱヒウかくイスラエルの中よりバアルを絶さりたりしかども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'ヱヒウは尚かのイスラエルに罪を犯させたるネバテの子ヤラベアムの罪に離るることをせざりき即ち彼なほベテルとダンにあるところの金の犢に事たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'ヱホバ、ヱヒウに言たまひけらく汝わが義と視るところの事を行ふにあたりて善く事をなしまたわが心にある諸の事をアハブの家になしたれば汝の子孫は四代までイスラエルの位に坐せんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, '然るにヱヒウは心を盡してイスラエルの神ヱホバの律法をおこなはんとはせず尚かのイスラエルに罪を犯させたるヤラベアムの罪に離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, '是時にあたりてヱホバ、イスラエルを割くことを始めたまへりハザエルすなはちイスラエルの一切の邊境を侵し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'ヨルダンの東においてギレアデの全地ガド人ルベン人マナセ人の地を侵しアルノン河の邊なるアロエルよりギレアデにいたりバシヤンにおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'ヱヒウのその餘の行爲とその凡て爲たる事むよびその大なる能はイスラエルの王の歴代志の書に記さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'ヱヒウその先祖等とともに寝りたればこれをサマリヤに葬りぬその子ヱホアハズこれに代て王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'ヱヒウがサマリヤにをりてイスラエルに王たりし間は二十八年なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, '茲にアハジアの母アタリヤその子の死たるを見て起て王の種を盡く滅したりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'ヨラム王の女にしてアハジアの姉妹なるヱホシバといふ者アハジアの子ヨアシを王の子等の殺さるる者の中より竊みとり彼とその乳母を夜着の室にいれて彼をアタリヤに匿したれば終にころされざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'ヨアシは彼とともに六年ヱホバの家に隱れてをりアタリヤ國を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, '第七年にいたりヱホヤダ人を遣して近衛兵の大將等を招きよせヱホバの家にきたりて己に就しめ彼等と契約を結び彼らにヱホバの家にて誓をなさしめて王の子を見し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'かれらに命じて言ふ汝等がなすべき事は是なり汝等安息日に入きたる者は三分の一は王の家をまもり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, '三分の一はスル門にをり三分の一は近衛兵の後の門にをるべし斯なんぢら宮殿をまもりて人をいるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'また凡て汝等安息日に出ゆく者はその二手ともにヱホバの家において王をまもるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'すなはち汝らおのおの武器を手にとりて王を環て立べし凡てその列を侵す者をば殺すべし汝等又王の出る時にも入る時にも王とともにをるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, '是においてその將官等祭司ヱホヤダが凡て命ぜしごとくにおこなへり即ちかれらおのおの其手の人の安息日に入くべき者と安息日に出ゆくべき者とを率て祭司ヱホヤダに至りしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, '祭司はヱホバの殿にあるダビデ王の槍と楯を大將等にわたせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, '近衛兵はおのおの手に武器をとりて王の四周にをり殿の右の端より左の端におよびて壇と殿にそひて立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'ヱホヤダすなはち王子を進ませて之に冠冕をいただかせ律法をわたし之を王となして之に膏をそそぎければ人衆手を拍て王長壽かれと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, '茲にアタリヤ近衛兵と民の聲を聞きヱホバの殿にいりて民の所にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, '見るに王は常例のごとくに高座の上に立ち其傍に大將等と喇叭手立をり又國の民みな喜びて喇叭を吹をりしかばアタリヤ其衣を裂て反逆なり反逆なりと叫べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, '時に祭司ヱホヤダ大將等と軍勢の士官等に命じてこれに言ふ彼をして列の間をとほりて出しめよ彼に從がふ者をば劍をもて殺せと前にも祭司は彼をヱホバの家に殺すべからずと言おけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, '是をもて彼のために路をひらきければ彼王の家の馬道をとほりゆきしが遂に其處に殺されぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, '斯てヱホヤダはヱホと王と民の間にその皆ヱホバの民とならんといふ契約を立しめたり亦王と民の間にもこれを立しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, '是をもて國の民みなバアルの家にいりてこれを毀ちその壇とその像を全く打碎きバアルの祭司マツタンをその壇の前に殺せり而して祭司ヱホバの家に監督者を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'ヱホヤダすなはち大將等と近衛兵と國の諸の民を率てヱホバの家より王をみちびき下り近衛兵の門の途よりして王の家にいたり王の位に坐せしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, '斯有しかば國の民はみな喜びて邑は平穩なりきアタリヤは王の家に殺されぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'ヨアシは位に即し時七歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'ヨアシはヱヒウの七年に位に即きエルサレムにおいて四十年世を治めたりその母はベエルシバより出たるものにて名をヂビアといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'ヨアシは祭司ヱホヤダの己を誨ふる間は恒にヱホバの善と視たまふ事をおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, '然ど崇邱は除かずしてあり民は尚その崇邱において犠牲をささげ香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, '茲にヨアシ祭司等に言けるは凡てヱホバの家に聖別て献納るところの金即ち核數らるる人の金估價にしたがひて出すところの身の代の金および人々が心より願てヱホバの家に持きたるところの金');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'これを祭司等おのおのその知人より受をさめ何處にても殿に破壞の見る時はこれをもてその破壞を修繕ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, '然るにヨアシ王の二十三年におよぶまで祭司等殿の破壞を修繕ふにいたらざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'ヨアシ王祭司ヱホヤダおよびその他の祭司等を召てこれに言ふ汝等などて殿の破壞を修繕はざるや然ば今よりは汝等の知人より金を受て自己のためにすべからず唯殿の破壞の修理に其を供ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, '祭司等は重て民より自己のために金を受ず又殿の破壞を修理ふことをせじと約せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, '斯て後祭司ヱホヤダ一箇の櫃をとりその蓋に孔を穿ちてこれをヱホバの家の入口の右において壇の傍に置り門守の祭司等すなはちヱホバの家に入きたるところの金をことごとくその中に入たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, '爰にその櫃の中に金の多くあることを見たれば王の書記と祭司長と上り來りてそのヱホバの家に積りし金を包みてこれを數へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'その數へし金をこの工事をなす者に付せり即ちヱホバの家の監督者にこれを付しければ彼等またヱホバの家を修理ふところの木匠と建築師にこれを與へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, '石工および琢石者に與へまたこれをもてヱホバの家の破壞を修繕ふ材木と琢石を買ひ殿を修理ふために用ふる諸の物のためにこれを費せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, '但しヱホバの家にり來れるその金をもてヱホバの家のために銀の盂燈剪鉢喇叭金の器銀の器等を造ることはせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, '唯これをその工事をなす者にわたして之をもてヱホバの家を修理はしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'またその金を手にわたして工人にはらはしめたる人々と計算をなすことをせざりき是は彼等忠厚に事をなしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, '愆金と罪金はヱホバの家にいらずして祭司に歸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, '當時スリアの王ハザエルのぼり來りてガテを攻てこれを取り而してハザエル、エルサレムに攻のぼらんとてその面をこれに向たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, '是をもてユダの王ヨアシその先祖たるユダの王ヨシヤパテ、ヨラム、アハジア等が聖別て献げたる一切の物および自己が聖別て献げたる物ならびにヱホバの家の庫と王の家とにあるところの金を悉く取てこれをスリアの王ハザエルにおくりければ彼すなはちエルサレムを離れて去ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'ヨアシのその餘の行爲およびその凡て爲たる事はユダの王の歴代志の書に記さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, '茲にヨアシの臣僕等おこりて黨をむすびシラに下るところのミロの家にてヨアシを弑せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, '即ちその僕シメアテの子ヨザカルとシヨメルの子ヨザバデかれを弑して死しめたればその先祖とおなじくこれをダビデの邑に葬れりその子アマジヤこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'ユダの王アハジアの子ヨアシの二十三年にヱヒウの子ヨハアズ、サマリヤにおいてイスラエルの王となり十七年位にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, '彼はヱホバの目の前に惡をなし夫のイスラエルに罪を犯させたるネバテの子ヤラベアムの罪を行ひつづけて之に離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, '是においてヱホバ、イスラエルにむかひて怒を發しこれをその代のあひだ恒にスリアの王ハザエルの手にわたしおき又ハザエルの子ベネハダデの手に付し置たまひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'ヨアハズ、ヱホバに請求めたればヱホバつひにこれを聽いれたまへり其はイスラエルの苦難を見そなはしたればなり即ちスリアの王これをなやませるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'ヱホバつひに救者をイスラエルにたまひたればイスラエルの子孫はスリア人の手を脱れて疇昔の如くに己々の天幕に住にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, '但し彼等はイスラエルに罪を犯さしめたるヤラベアムの家の罪をはなれずして之をおこなひつづけたりサマリヤにも亦アシタロテの像たちをりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, '嚮にスリアの王は民を滅し踐くだく塵のごとくに是をなして只騎兵五十人車十輌歩兵一萬人而巳をヨアハズに遺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'ヨアハズのその餘の行爲とその凡て爲たる事およびその能はイスラエルの王の歴代志の書にしるさるるに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'ヨアハズその先祖等とともに寝りたればこれをサマリヤに葬れりその子ヨアシこれに代て王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'ユダの王ヨアシの三十七年にヨアハズの子ヨアシ、サマリヤにおいてイスラエルの王となり十六年位にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, '彼ヱホバの目の前に惡をなし夫のイスラエルに罪を犯させたるネバテの子ヤラベアムの諸の罪にはなれずしてこれを行ひつづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'ヨアシのその餘の行爲とその凡て爲たる事およびそのユダの王アマジヤと戰ひし能はイスラエルの王の歴代志の書に記さるるに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'ヨアシその先祖等とともに寝りてヤラベアム位にのぼれりヨアシはイスラエルの王等とおなじくサマリヤに葬らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, '茲にエリシヤ死病にかかりて疾をりしかばイスラエルの王ヨアシ彼の許にくだり來てその面の上に涙をこぼし吾父吾父イスラエルの兵車よその騎兵よと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'エリシヤかれにむかひ弓矢をとれと言ければすなはち弓矢をとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'エリシヤまたイスラエルの王に汝の手を弓にかけよと言ければすなはちその手をかけたり是においてエリシヤその手を王の手の上に按て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, '東向の窓を開けと言たれば之を開きけるにエリシヤまた射よと言り彼すなはち射たればエリシヤ言ふヱホバよりの拯救の矢スリアに對する拯救の矢汝必らずアベクにおいてスリア人を撃やぶりてこれを滅しつくすにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'エリシヤまた矢を取れと言ければ取りエリシヤまたイスラエルの王に地を射よといひけるに三次射て止たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, '神の人怒て言ふ汝は五回も六回も射るべかりしなり然せしならば汝スリアを撃やぶりて之を滅しつくすことを得ん然ど今然せざれば汝がスリアを撃やぶることは三次のみなるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'エリシヤ終に死たればこれを葬りしが年の立かへるに及てモアブの賊黨國にいりきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, '時に一箇の人を葬らんとする者ありしが賊黨を見たればその人をエリシヤの墓におしいれけるにその人いりてエリシヤの骨にふるるや生かへりて起あがれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'スリアの王ハザエルはヨアハズの一生の間イスラエルをなやましたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'ヱホバそのアブラハム、イサク、ヤコブと契約をむすびしがためにイスラエルをめぐみ之を憐みこれを眷みたまひ之を滅すことを好まず尚これをその前より棄はなちたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'スリアの王ハザエルつひに死てその子ベネハダデこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, '是においてヨアズの子ヨアシはその父ヨアハズがハザエルに攻取れたる邑々をハザエルの子ベネハダデの手より取かへせり即ちヨアシは三次かれを敗りてイスラエルの邑々を取かへしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'イスラエルの王ヨアハズの子ヨアシの二年にユダの王ヨアシの子アマジヤ王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, '彼は王となれる時二十五歳にして二十九年の間エルサレムにて世を治めたりその母はエルサレムの者にして名をヱホアダンと云り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'アマジヤはヱホバの善と見たまふ事をなしたりしがその先祖ダビデのごとくはあらざりき彼は萬の事において其父ヨアシがなせしごとくに事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, '惟崇邱はのぞかずしてあり民はなほその崇邱において犠牲をささげ香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, '彼は國のその手に堅くたつにおよびてその父王を弑せし臣僕等を殺したりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'その弑殺人の子女等は殺さざりき是はモーセの律法の書に記されたる所にしたがへるなり即ちヱホバ命じて言たまはく子女の故によりて父を殺すべからず父の故によりて子女を殺すべからず人はみなその身の罪によりて死べき者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'アマジヤまた鹽谷においてエドミ人一萬を殺せり亦セラを攻とりてその名をヨクテルとなづけしが今日まで然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'かくてアマジヤ使者をヱヒウの子ヨアハズの子なるイスラエルの王ヨアシにおくりて來れ我儕たがひに面をあはせんと言しめければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'イスラエルの王ヨアシ、ユダの王アマジヤに言おくりけるはレバノンの荊棘かつてレバノンの香柏に汝の女子をわが子の妻にあたへよと言おくりたることありしにレバノンの野獣とほりてその荊棘を踏たふせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, '汝は大にエドムに勝たれば心に誇るその榮譽にやすんじて家に居れなんぞ禍を惹おこして自己もユダもともに亡んとするやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, '然るにアマジヤ聽ことをせざりしかばイスラエルの王ヨアシのぼり來れり是において彼とユダの王アマジヤはユダのベテシメシにてたがひに面をあはせたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'ユダ、イスラエルに敗られて各人その天幕に逃かへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, '是においてイスラエルの王ヨアシはアジアの子ヨアシの子なるユダの王アマジヤをベテシメシに擒へ而してエルサレムにいたりてエルサレムの石垣をエフライムの門より隅の門まで凡そ四百キユビトを毀ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'またヱホバの家と王の家の庫とにあるところの金銀および諸の器をとりかつ人質をとりてサマリヤにかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'ヨアシがなしたるその餘の行爲とその能およびそのイスラエルの王アマジヤと戰ひし事はイスラエルの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'ヨアシその先祖等とともに寝りてイスラエルの王等とともにサマリヤに葬られその子ヤラベアムこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'ヨアシの子なるユダの王アマジヤはヨアハズの子なるイスラエルの王ヨアシの死てより後なほ十五年生存へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'アマジヤのその餘の行爲はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, '茲にエルサレムにおいて黨をむすびて彼に敵する者ありければ彼ラキシに逃ゆきけるにその人々ラキシに人をやりて彼を彼處に殺さしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, '人衆かれを馬に負せてもちきたりエルサレムにおいてこれをその先祖等とともにダビデの邑に葬りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'ユダの民みなアザリヤをとりて王となしてその父アマジヤに代しめたり時に年十六なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, '彼エラテの邑を建てこれを再びユダに歸せしめたり是はかの王がその先祖等とともに寝りし後なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'ユダの王ヨアシの子アマジヤの十五年にイスラエルの王ヨアシの子ヤラベアム、サマリヤにおいて王となり四十一年位にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, '彼はヱホバの目の前に惡をなし夫のイスラエルに罪を犯さしめたるネバテの子ヤラベアムの罪に離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, '彼ハマテの入處よりアラバの海までイスラエルの邊境を恢復せりイスラエルの神ヱホバがガテヘペルのアミツタイの子なるその僕預言者ヨナによりて言たまひし言のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'ヱホバ、イスラエルの艱難を見たまふに其は甚だ苦かり即ち繋れたる者もあらず繋れざる者もあらず又イスラエルを助る者もあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'ヱホバは我イスラエルの名を天下に塗抹んとすと言たまひしこと無し反てヨアシの子ヤラベアムの手をもてこれを拯ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'ヤラベアムのその餘の行爲とその凡てなしたる事およびその戰爭をなせし能その昔にユダに屬し居たることありしダマスコとハマテを再びイスラエルに歸せしめたる事はイスラエルの王の歴代志の書に記さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'ヤラベアムその先祖たるイスラエルの王等とともに寝りその子ザカリヤこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'イスラエルの王ヤラベアムの二十七年にユダの王アマジヤの子アザリヤ王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, '彼は王となれる時に十六歳なりしが五十二年の間エルサレムにおいて世を治めたりその母はエルサレムの者にして名をヱコリアと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, '彼はヱホバの善と見たまふ事をなし萬の事においてその父アマジヤがなしたるごとく行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, '惟崇邱は除かずしてあり民は尚その崇邱の上に犠牲をささげ香をたけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'ヱホバ王を撃たまひしかばその死る日まで癩病人となり別殿に居ぬその子ヨタム家の事を管理て國の民を審判り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'アザリヤのその餘の行爲とその凡てなしたる事はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'アザリヤその先祖等とともに寝りたればこれをダビデの邑にその先祖等とともに葬れりその子ヨタムこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'ユダの王アザリヤの三十八年にヤラベアムの子ザカリア、サマリヤにおいてイスラエルの王となれりその間は六月');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, '彼その先祖等のなせしごとくヱホバの目の前に惡を爲し夫のイスラエルに罪を犯させたるネバテの子ヤラベアムの罪に離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, '茲にヤベシの子シヤルム黨をむすびて之に敵し民の前にてこれを撃て弑しこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'ザカリヤのその餘の行爲はイスラエルの王の歴代志の書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'ヱホバのヱヒウに告たまひし言は是なり云く汝の子孫は四代までイスラエルの位に坐せんと果して然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'ヤベシの子シヤルムはユダの王ウジヤの三十九年に王となりサマリヤにおいて一月の間王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, '時にガデの子メナヘム、テルザより上りでサマリヤに來りヤベシの子シヤルムをサマリヤに撃てこれを殺し之にかはりて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'シヤルムのその餘の行爲とその徒黨をむすびし事はイスラエルの王の歴代志の書にしるさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'その後メナヘム、テルザよりいたりてテフサとその中にあるところの者およびその四周の地を撃り即ちかれら己がために開くことをせざりしかばこれを撃てその中の孕婦をことごとく刳剔たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'ユダの王アザリヤの三十九年にガデの子メナヘム、イスラエルの王となりサマリヤにおいて十年の間世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, '彼ヱホバの目の前に惡をなし彼のイスラエルに罪を犯させたるネバテの子ヤラベアムの罪に生涯離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, '茲にアツスリヤの王ブルその地に攻きたりければメナヘム銀一千タラントをブルにあたへたり是は彼をして己を助けしめ是によりて國を己の手に堅く立しめんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, '即ちメナヘムその銀をイスラエルの諸の大富者に課しその人々に各々銀五十シケルを出さしめてこれをアツスリヤの王にあたへたり是をもてアツスリヤの王は歸りゆきて國に止ることをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'メナヘムのその餘の行爲とその凡てなしたる事はイスラエルの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'メナヘムその先祖等とともに寝りその子ペカヒヤこれに代て王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'メナヘムの子ペカヒヤはユダの王アザリヤの五十年にサマリヤにおいてイスラエルの王となり二年のあひだ位にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, '彼ヱホバの目のまへに惡をなし彼のイスラエルに罪を犯させたるネバテの子ヤラベアムの罪に離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, '茲にその將官なるレマリヤの子ペカ黨をむすびて彼に敵しサマリヤにおいて王の家の奧の室にこれを撃ころしアルゴブとアリエをもこれとともに殺せり時にギレアデ人五十人ペカとともにありきペカすなはち彼をころしかれに代て王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'ベカヒヤのその餘の行爲とその凡て爲たる事はイスラエルの王の歴代志の書にしるさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'レマリヤの子ペカはユダの王アザリヤの五十二年にサマリヤに於てイスラエルの王となり二十年位にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, '彼ヱホバの目の前に惡をなし彼のイスラエルに罪ををかさせたるネバテの子ヤラベアムの罪にはなれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'イスラエルの王ペカの代にアツスリヤの王テグラテビレセル來りてイヨン、アベルベテマアカ、ヤノア、ケデシ、ハゾルおよびギレアデならびにナフタリの全地ガリラヤを取りその人々をアツスリヤに擄へうつせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, '茲にエラの子ホセア黨をむすびてレマリヤの子ペカに敵しこれを撃て殺しこれに代て王となれり是はウジヤの子ヨタムの二十年にあたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'ペカのその餘の行爲とその凡てなしたる事はイスラエルの王の歴代志の書にしるさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'レマリヤの子イスラエルの王ペカの二年にウジヤの子ユダの王ヨタム王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, '彼は王となれる時二十五歳なりしがヱルサレムにて十六年世を治めたり母はザドクの女にして名をヱルシヤといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, '彼はヱホバの目にかなふ事をなし凡てその父ウジヤのなしたるごとくにおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, '惟崇邱は除かずしてあり民なほその崇邱の上に犠牲をささげ香を焚り彼ヱホバの家の上の門を建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'ヨタムのその餘の行爲とその凡てなしたる事はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, '當時ヱホバ、スリアの王レヂンとレマリヤの子ペカをユダにせめきたらせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'ヨタムその先祖等とともに寝りてその父ダビデの邑にその先祖等とともに葬られその子アハズこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'レマリヤの子ペカの十七年にユダの王ヨタムの子アハズ王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'アハズは王となれる時二十歳にしてエルサレムにおいて十六年世を治めたりしがその神ヱホバの善と見たまふ事をその父ダビデのごとくは行はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, '彼はイスラエルの王等の道にあゆみまたその子に火の中を通らしめたり是はヱホバがイスラエルの子孫の前より逐はらひたまひし異邦人のおこなふところの憎むべき事にしたがへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, '彼は崇邱の上丘の上一切の靑木の下に犠牲をささげ香をたけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'この頃スリアの王レヂンおよびレマリヤの子なるイスラエルの王ペカ、エルサレムにせめのぼりてアハズを圍みけるが勝ことを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'この時にあたりてスリアの王レヂン復エラテをスリアに歸せしめユダヤ人をエラテより逐いだせり而してスリア人エラテにきたりて其處に住み今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, '是においてアハズ使者をアツスリヤの王テグラテピレセルにつかはして言しめけるは我は汝の臣僕汝の子なりスリアの王とイスラエルの王と我に攻かかりをれば請ふ上りきたりてかれらの手より我を救ひいだしたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'アハズすなはちヱホバの家と王の家の庫とにあるところの銀と金をとりこれを禮物としてアツスリヤの王におくりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'アツスリヤの王かれの請を容たりアツスリヤの王すなはちダマスコに攻のぼりて之をとりその民をキルに擄うつしまたレヂンを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'かくてアハズはアツスリヤの王テグラテピレセルに會んとてダマスコにゆきけるがダマスコにおいて一箇の祭壇を見たればアスス王その祭壇の工作にしたがひて委くこれが圖と式樣を制へて祭司ウリヤにこれをおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, '是において祭司ウリヤはアハズ王がダマスコよりおくりたる所にてらして一箇の祭壇をつくりアハズ王がダマスコより來るまでにこれを作りおけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, '茲に王ダマスコより歸りてその祭壇を見壇にちかよりてこれに上り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, '壇の上に燔祭と素祭を焚き灌祭をそそぎ酬恩祭の血を灑げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, '彼またヱホバの前なる銅の壇を家の前より移せり即ちこれをかの新しき壇とヱホバの家の間より移してかの壇の北の方に置たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, '而してアハズ王祭司ウリヤに命じて言ふ朝の燔祭夕の素祭および王の燔祭とその素祭ならびに國中の民の燔祭とその素祭および灌祭はこの大なる壇の上に焚べし又この上に燔祭の牲の血と犠牲の物の血をすべて灑ぐべし彼の銅の壇の事はなほ考ふるあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, '祭司ウリヤすなはちアハズ王のすべて命じたるごとくに然なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'またアハズ王臺の邊を削りて洗盤をその上よりうつしまた海をその下なる銅の牛の上よりおろして石の座の上に置ゑ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'また家に造りたる安息日用の遊廊および王の外の入口をアツスリヤの王のためにヱホバの家の中に變じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'アハズのなしたるその餘の行爲はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'アハズその先祖等とともに寝りてダビデの邑にその先祖等とともに葬られその子ヒゼキヤこれにかはりて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'ユダの王アハズの十二年にエラの子ホセア王となりサマリヤにおいて九年イスラエルを治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, '彼ヱホバの目の前に惡をなせしがその前にありしイスラエルの王等のごとくはあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'アッスリヤの王シヤルマネセル攻のぼりたればホセアこれに臣服して貢を納たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'アッスリヤの王つひにホセアの己に叛けるを見たり其は彼使者をエジプトの王ソにおくり且前に歳々なせしごとくに貢をアッスリヤ王に納ざりければなり是においてアツスリヤの王かれを禁錮て獄におけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'すなはちアッスリヤの王せめ上りて國中を遍くゆきめぐりサマリヤにのぼりゆきて三年が間これをせめ圍みたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'ホセアの九年におよびてアッスリヤの王つひにサマリヤを取りイスラエルをアッスリヤに擄へゆきてこれをハラとハボルとゴザン河の邊とメデアの邑々とにおきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, '此事ありしはイスラエルの子孫己をエジプトの地より導きのぼりてエジプトの王パロの手を脱しめたるその神ヱホバに對て罪を犯し他の神々を敬ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'ヱホバがイスラエルの子孫の前より逐はらひたまひし異邦人の法度にあゆみ又イスラエルの王等の設けし法度にあゆみたるに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'イスラエルの子孫義からぬ事をもてその神ヱホバを掩ひかくしその邑々に崇邱をたてたり看守臺より城にいたるまで然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, '彼等一切の高丘の上一切の靑樹の下に偶像とアシラ像を立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'ヱホバがかれらの前より移したまひし異邦人のなせしごとくにその崇邱に香を焚き又惡を行ひてヱホバを怒らせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'ヱホバかれらに汝等これらの事を爲べからずと言おきたまひしに彼等偶像に事ふることを爲しなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'ヱホバ諸の預言者諸の先見者によりてイスラエルとユダに見證をたて汝等翻へりて汝らの惡き道を離れわが誡命わが法度をまもり我が汝等の先祖等に命じまたわが僕なる預言者等によりて汝等に傳へし法に率由ふやうにせよと言たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, '然るに彼ら聽ことをせずしてその項を強くせり彼らの先祖等がその神ヱホバを信ぜずしてその項を強くしたるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, '彼等はヱホバの法度を棄てヱホバがその先祖等と結びたまひし契約を棄てまたその彼等に見證したまひし證言を棄て且虚妄物にしたがひて虚浮なりまたその周圍なる異邦人の跡をふめり是はヱホバが是のごとくに事をなすべからずと彼らに命じ給ひし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, '彼等その神ヱホバの諸の誡命を遺て己のために二の牛の像を鑄なし又アシラ像を造り天の衆群を拝み且バアルに事へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'またその子息息女に火の中を通らしめ卜筮および禁厭をなしヱホバの目の前に惡を爲ことに身を委ねてその怒を惹起せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, '是をもてヱホバ大にイスラエルを怒りこれをその前より除きたまひたればユダの支派のほかは遺れる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, '然るにユダもまたその神ヱホバの誡命を守ずしてイスラエルの立たる法度にあゆみたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'ヱホバ、イスラエルの苗裔ぞことごとく棄これを苦しめこれをその掠むる者の手に付して遂にこれをその前より打すてたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'すなはちイスラエルをダビデの家より裂はなしたまひしかばイスラエル、ネバテの子ヤラベアムを王となせしにヤラベアム、イスラエルをしてヱホバにしたがふことを止しめてこれに大なる罪を犯さしめたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'イスラエルの子孫はヤラベアムのなせし諸の罪をおこなひつづけてこれに離るることなかりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, '遂にヱホバその僕なる諸の預言者をもて言たまひしごとくにイスラエルをその前より除きたまへりイスラエルはすなはちその國よりアッスリヤにうつされて今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, '斯てアッスリヤの王バビロン、クタ、アワ、ハマテおよびセパルワイムより人をおくりてこれをイスラエルの子孫の代にサマリヤの邑々に置ければその人々サマリヤを有ちてその邑々に住しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'その彼處に始て住る時には彼等ヱホバを敬ふことをせざりしかばヱホバ獅子をかれらの中に送りたまひてその獅子かれら若干を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, '是によりてアッスリヤの王に告て言ふ汝が移てサマリヤの邑々におきたまひしかの國々の民はこの地の神の道を知ざるが故にその神獅子をかれらの中におくりて獅子かれらを殺せり是は彼等その國の神の道を知ざるに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'アッスリヤの王すなはち命を下して言ふ汝等が彼處より曳きたりし祭司一人を彼處に携ゆけ即ち彼をして彼處にいたりて住しめその國の神の道をその人々に敎へしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, '是に於てサマリヤより移れし祭司一人きたりてベテルに住みヱホバの敬ふべき事をかれらに敎へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'その民はまた各々自分自分の神々を造りてこれをかのサマリア人が造りたる諸の崇邱に安置せり民みなその住る邑々において然なしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, '即ちバビロンの人々はスコテペノテを作りクタの人々はネルガルを作りハマテの人々はアシマを作り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'アビ人はニブハズとタルタクを作りセパルワイ人は其子女を火に焚てセパルワイムの神アデランメルクおよびアナンメルクに奉げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, '彼ら又ヱホバを敬ひ凡俗の民をもて崇邱の祭司となしたれば其人これがために崇邱に家々にて職務をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, '斯その人々ヱホバを敬ひたりしが亦その携へ出されし國々の風俗にしたがひて自己自己の神々に事へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, '今日にいたるまで彼等は前の習俗にしたがひて事をなしヱホバを敬はず彼等の法度をも例典をも行はず又ヱホバがイスラエルを名けたまひしヤコブの子孫に命じたまひし律法をも誡命をも行はざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, '昔ヱホバこれと契約をたてこれに命じて言たまひけらく汝等は他の神を敬ふべからずまたこれを拝みこれに事へこれに犠牲をささぐべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, '只大なる能をもて腕を伸て汝等をエジプトの地より導き上りしヱホバをのみ汝等敬ひこれを拝みこれにこれに犠牲をささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'またその汝等のために録したまへる法度と例典と律法と誡命を汝等謹みて恒に守るべし他の神々を敬ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, '我が汝等とむすびし契約を汝等忘るべからず又他の神々を敬ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, '只汝らの神ヱホバを敬ふべし彼なんじらをその諸の敵の手より救ひいださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, '然るに彼等は聽ことをせずしてなほ前の習俗にしたがひて事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, '偖この國々の民は斯ヱホバを敬ひまたその雕める像に事たりしがその子も孫も共に然りその先祖のなせしごとくに今日までも然なすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'イスラエルの王エラの子ホセアの三年にユダの王アハズの子ヒゼキア王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, '彼は王となれる時二十五歳にしてエルサレムにて二十九年世ををさめたりその母はザカリヤの女にして名をアビといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'ヒゼキヤはその父ダビデの凡てなせしごとくヱホバの善と見たまふ事をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, '崇邱を除き偶像を毀ちアシラ像を斫たふしモーセの造りし銅の蛇を打碎けりこの時までイスラエルの子孫その蛇にむかひて香を焚たればなり人々これをネホシタン(銅物)と稱なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'ヒゼキヤはイスラエルの神ヱホバを賴り是をもて彼の後にも彼の先にもユダの諸の王等の中に彼に如ものなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, '即ち彼は固くヱホバに身をよせてこれに從ふことをやめずヱホバがモーセに命じたまひしその誡命を守れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'ヱホバ彼とともに在したれば彼はその往ところにて凡て利達を得たり彼はアッスリヤの王に叛きてこれに事へざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, '彼ペリシテ人を撃敗りてガザにいたりその境に達し看守臺より城にまで及べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'ヒゼキヤ王の四年すなはちイスラエルの王エラの子ホセアの七年にアッスリヤの王シヤルマネセル、サマリヤに攻のぼりてこれを圍みけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, '三年の後つひに之を取りサマリヤの取れしはヒゼキヤの六年にしてイスラエルの王ホセアの九年にあたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'アッスリヤの王イスラエルをアッスリヤに擄へゆきてこれをハラとゴザン河の邊とメデアの邑々におきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, '是は彼等その神ヱホバの言に遵はずその契約を破りヱホバの僕モーセが凡て命じたる事をやぶりこれを聽ことも行ふこともせざるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'ヒゼキヤ王の十四年にアッスリヤの王セナケリブ攻のぼりてユダの諸の堅き邑を取ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'ユダの王ヒゼキヤ人をラキシにつかはしてアッスリヤの王にいたらしめて言ふ我過てり我を離れて歸りたまへ汝が我に蒙らしむる者は我これを爲べしとアッスリヤの王すなはち銀三百タラント金三十タラントをユダの王ヒゼキヤに課したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, '是においてヒゼキヤ、ヱホバの家と王の家の庫とにあるところの銀をことごとく彼に與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, '此時ユダの王ヒゼキヤまた己が金を著たりしヱホバの宮の戸および柱を剥てこれをアッスリヤの王に與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'アッスリヤの王またタルタン、ラブサリスおよびラブシヤケをしてラキシより大軍をひきゐてエルサレムにむかひてヒゼキヤ王の所にいたらしめたればすなはち上りてエルサレムにきたれり彼等則ち上り來り漂布場の大路に沿るよの池塘の水道の邊にいたりて立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, '而して彼等王を呼たればヒルキヤの子なる宮内卿エリアキム書記官セブナおよびアサフの子なる史官ヨア出きたりて彼等に詣りけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'ラブシヤケこれに言けるは汝等ヒゼキヤに言べし大王アッスリヤの王かく言たまふ此汝が賴むところの者は何ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, '汝戰爭をなすの謀計と勇力とを言も只これ口の先の言語たるのみ誰を恃みて我に叛くことをせしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, '視よ汝は折かかれる葦の杖なるエジプトを賴む其は人の其に倚るあればすなはちその手を刺とほすなりエジプトの王パロは凡てこれを賴む者に斯あるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, '汝等あるひは我はわれらの神ヱホバを賴むと我に言ん彼はヒゼキヤがその崇邱と祭壇とを除きたる者にあらずやまた彼はユダとエルサレムに告て汝等はエルサレムに於てこの壇の前に祷拝をなすべしと言しにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, '然ば請ふわが主君アッスリヤの王に約をなせ汝もし人を乗しむることを得ば我馬二千匹を汝にあたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, '汝いかにしてか吾主君の諸臣の中の最も微き一將だにも退くることを得ん汝なんぞエジプトを賴みて兵車と騎兵をこれに仰がんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'また我とても今ヱホバの旨によらずして比處を滅しに上れるならんやヱホバ我に此處に攻のぼりてこれを滅せと言たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, '時にヒルキヤの子エリアキムおよびセブナとヨア、ラダシヤケにいひけるは請ふスリアの語をもて僕等に語りたまへ我儕これを識なり石垣の上にをる民の聞るところにてユダヤ語をもて我儕に言談たまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'ラブシヤケかれらに言ふわが君唯我を汝の主と汝とにつかはして此言をのべしめたまふならんや亦石垣の上に坐する人々にも我を遣して彼等をして汝等とともに自己の便溺を食ひ且飮にいたらしめんとしたまふにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, '而してラブシヤケ起あがりユダヤ語をもて大聲に呼はり言をいだして曰けるは汝等大王アッスリヤの王の言を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, '王かく言たまふ汝等ヒゼキヤに欺かるるなかれ彼は汝等をわが手より救ひいだすことをえざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'ヒゼキヤがヱホバかならず我らを救ひたまはん此邑はアッスリヤの王の手に陷らじと言て汝らにヱホバを賴ましめんとするとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, '汝等ヒゼキヤの言を聽なかれアッスリヤの王かく言たまふ汝等約をなして我に降れ而して各人おのれの葡萄の樹の果を食ひ各人おのれの無花果樹の果をくらひ各人おのれの井水を飮めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, '我來りて汝等を一の國に携ゆかん其は汝儕の國のごとき國穀と酒のある地パンと葡萄園のある地油の出る橄欖と蜜とのある地なり汝等は生ることを得ん死ることあらじヒゼキヤ、ヱホバ我儕を救ひたまはんと言て汝らを勸るともこれを聽なかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, '國々の神の中執かその國をアッスリヤの王の手より救ひたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'ハマテおよびアルパデの神々は何處にあるセパルワイム、ヘナおよびアワの神々は何處にあるやサマリヤをわが手より救ひ出せし神々あるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, '國々の神の中にその國をわが手より救ひいだせし者ありしや然ばヱホバいかでかエルサレムをわが手より救ひいだすことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, '然ども民は默して一言もこれに應へざりき其は王命じてこれに應ふるなかれと言おきたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'かくてヒルキヤの子なる宮内卿エリアキム書記官セブナおよびアサの子なる史官ヨアその衣をさきてヒゼキヤの許にいたりラブシヤケの言をこれに告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'ヒゼキヤ王これを聞てその衣を裂き麻布を身にまとひてヱホバの家に入り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, '宮内卿エリアキムと書記官セブナと祭司の中の長老等とに麻布を衣せてこれをアモツの子預言者イザヤに遣せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, '彼等イザヤに言けるはヒゼキヤかく言ふ今日は艱難の日懲罰の日打棄らるる日なり嬰孩すでに產門にいたりて之を產いだす力なき也');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'ラブシヤケその主君なるアッスリヤの王に差遣れて來り活る神を謗る汝の神ヱホバあるひは彼の言を聞たまはん而して汝の神ヱホバその聞る言語を責罰たまふこともあらん然ば汝この遺る者の爲に祈祷をたてまつれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'ヒゼキヤ王の僕等すなはちイザヤの許にいたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'イザヤかれらに言けるは汝等の主君にかく言べしヱホバかく言たまふアッスリヤの王の臣僕等が我を謗るところの言を汝聞て懼るるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, '我かれの氣をうつして風聲を聞て己の國にかへるにいたらしめん我また彼をして自己の國に於て劍に斃れしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, '偖またラブシヤケは歸りゆきてアッスリヤの王がリブナに戰爭をなしをるとこるに至れり其は彼そのラキシを離れしを聞たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, '茲にアッスリヤの王はエテオピアの王テルハカ汝に攻きたると言ふを聞てまた使者をヒゼキヤにつかはして言しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '汝等ユダの王ヒゼキヤに告て言べし汝エルサレムはアッスリヤの王の手に陷らじと言て汝が賴むところの神に欺かるるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, '汝はアッスリヤの王等が萬の國々になしたるところの事を知る即ちこれを滅しつくせしなり然ば汝いかで救らんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, '吾父等はゴザン、ハラン、レゼフおよびテラサルのエデンの人々等を滅ぼせしがその國々の神これを救ひたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'ハマテの王アルバデの王セバルワイムの邑およびヘナとアワの王等は何處にあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'ヒゼキヤ使者の手より書を受てこれを讀みヱホバの家にのぼりゆきてヱホバの前にこれを展開げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, '而してヒゼキヤ、ヱホバの前に祈りて言けるはケルビムの間にいますイスラエルの神ヱホバよ世の國々の中において只汝のみ神にいます也汝は天地を造りたまひし者にいます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'ヱホバよ耳を傾けて聞たまへヱホバよ目を開きて見たまへセナケリブが活る神を謗りにおくれる言語を聞たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'ヱホバよ誠にアッスリヤの王等は諸の民とその國々を滅し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, '又その神々を火になげいれたり其等は神にあらず人の手の作れる者にして木石たればこれを滅せしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, '今われらの神ヱホバよ願くは我らをかれの手より拯ひいだしたまへ然ば世の國々皆汝ヱホバのみ神にいますことを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, '茲にアモツの子イザヤ、ヒゼキヤに言つかはしけるはイスラエルの神ヱホバかく言たまふ汝がセナケリブの事につきて我に祈るところの事は我これを聽り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'ヱホバが彼の事につきて言ふところの言語は是のごとし云く處女なる女子シオンは汝を藐視じ汝を嘲る女子エルサレムは汝にむかひて頭を搖る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, '汝誰を謗りかつ罵詈しや汝誰にむかひて聲をあげしや汝はイスラエルの聖者にむかひて汝の目を高く擧たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, '汝使者をもて主を謗て言ふ我夥多き兵車をひきゐて山々の嶺にのぼりレバノンの奧にいたり長高き香柏と美しき松樹を斫たふす我その境の休息所にいたりその園の林にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, '我は外國の地をほりて水を飮む我は足の跖をもてエジプトの河々をことごとくふみ涸すなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, '汝聞ずや昔われ之を作し古時よりわれ之を定めたり今われ之をおこなふ即ち堅き邑々は汝のために坵墟となるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, '是をもてそれらの中にすむ民は力弱かり懼れかつ驚くなり彼等は野の草のごとく靑菜のごとく屋蓋の草のごとく枯る苗のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, '汝の止ると汝の出ると汝の入と汝の我にむかひて怒くるふとは我の知ところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, '汝の怒くるふ事と汝の傲慢ところの事上りてわが耳にいりたれば我圏を汝の鼻につけ轡を汝の唇にほどこして汝を元來し道へひきかへすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, '是は汝にあたふる徴なり即ち一年は穭を食ひ第二年には又その穭を食ふあらん第三年には汝ら稼ことをし穡ことをし又葡萄園をつくりてその果を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'ユダの家の逃れて遺れる者は復根を下に張り實を上に結ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, '即ち殘餘者エルサレムより出で逃避たる者シオン山より出きたらんヱホバの熱心これを爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, '故にヱホバ、アッスリヤの王の事をかく言たまふ彼は此邑に入じ亦これに矢を發つことあらず楯を之にむかひて竪ることあらず亦壘をきづきてこれを攻ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, '彼はその來し路より歸らん此邑にいることあらじヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, '我わが身のため又わが僕ダビデのためにこの邑を守りてこれを救ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'その夜ヱホバの使者いでてアッスリヤ人の陣營の者十八萬五千人を撃ころせり朝早く起いでて見るに皆死て屍となりをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'アッスリヤの王セナケリブすなはち起いで歸りゆきてニネベに居しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'その神ニスロクの家にありて禮拝をなしをる時にその子アデランメレクとシヤレゼル劍をもてこれを殺せり而して彼等はアララテの池に逃ゆけり是においてその子エサルハドンこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, '當時ヒゼキヤ病て死なんとせしことありアモツの子預言者イザヤ彼の許にいたりて之にいひけるはヱホバかく言たまふ汝家の人に遺命をなせ汝は死ん生ることを得じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, '是においてヒゼキヤその面を壁にむけてヱホバに祈り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '嗚呼ヱホバよ願くは我が眞實と一心をもて汝の前にあゆみ汝の目に適ふことを行ひしを記憶たまへと言て痛く泣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'かくてイザヤ未だ中の邑を出はなれざる間にヱホバの言これに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '汝還りてわが民の君ヒゼキヤに告よ汝の父ダビデの神ヱホバかく言ふ我汝の祈祷を聽り汝の涙を看たり然ば汝を愈すべし第三日には汝ヱホバの家に入ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, '我汝の齢を十五年増べし我汝とこの邑とをアッスリヤの王の手より救ひ我名のため又わが僕ダビデのためにこの邑を守らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, '是に於てイザヤ乾無花果の団塊一箇を持きたれと言ければすなはち之を持きたりてその腫物に貼たればヒゼキヤ愈ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'ヒゼキヤ、イザヤに言けるはヱホバが我を愈したまふ事と第三日に我がヱホバの家にのぼりゆく事とにつきては何の徴あるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'イザヤ言けるはヱホバがその言しところを爲たまはん事につきては汝ヱホバよりこの徴を得ん日影進めること十度なり若日影十度退かば如何');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'ヒゼキヤ答へけるは日影の十度進むは易き事なり然せざれ日影を十度しりぞかしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, '是において預言者イザヤ、ヱホバに龥はりければアハスの日晷の上に進みし日影を十度しりぞかしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'その頃バラダンの子なるバビロンの王メロダクバラダン書および禮物をヒゼキヤにおくれり是はヒゼキヤの疾をるを聞たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'ヒゼキヤこれがために喜びその寶物の庫金銀香物貴き膏および武器庫ならびにその府庫にあるところの一切の物を之に見せたりその家にある物もその國の中にある物も何一箇としてヒゼキヤが彼等に見せざる者はなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, '茲に預言者イザヤ、ヒゼキヤ王のもとに來りてこれに言けるは夫の人々は何を言しや何處より來りしやヒゼキヤ言けるは彼等は遠き國より即ちバビロンより來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'イザヤ言ふ彼等は汝の家にて何を見しやヒゼキヤ答へて云ふ吾家にある物は皆かれら之を見たり我庫の中には我がかれに見せざる者なきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'イザヤすなはちヒゼキヤに言けるは汝ヱホバの言を聞け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'ヱホバ言たまふ視よ日いたる凡て汝の家にある物および汝の先祖等が今日までに積蓄へたる物はバビロンに携ゆかれん遺る者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, '汝の身より出る汝の生んところの子等の中を彼等携へ去ん其等はバビロンの王の殿において官吏となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'ヒゼキヤ、イザヤに言ふ汝が語れるヱホバの言は善し又いふ若わが世にある間に大平と眞實とあらば善にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'ヒゼキヤのその餘の行爲その能およびその池塘と水道を作りて水を邑にひきし事はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'ヒゼキヤその先祖等とともに寝りてその子マナセこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'マナセ十二歳にして王となり五十五年の間ヱルサレムにて世を治めたりその母の名はヘフジバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'マナセはヱホバの目の前に惡をなしヱホバがイスラエルの子孫の前より逐はらひたまひし國々の人がなすところの憎むべき事に傚へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, '彼はその父ヒゼキヤが毀たる崇邱を改め築き又イスラエルの王アハブのなせしごとくバアルのために祭壇を築きアシラ像を作り天の衆群を拝みてこれに事へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'またヱホバの家の中に數箇の祭壇を築けり是はヱホバがこれをさして我わが名をヱルサレムにおかんと言たまひし家なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, '彼ヱホバの家の二の庭に祭壇を築き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'またその子に火の中を通らしめ卜占をなし魔術をおこなひ口寄者と卜筮師を取もちひヱホバの目の前に衆多の惡を爲てその震怒を惹おこせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, '彼はその作りしアシラの銅像を殿にたてたりヱホバこの殿につきてダビデとその子ソロモンに言たまひしことあり云く我この家と我がイスラエルの諸の支派の中より選みたるヱルサレムとに吾名を永久におかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, '彼等もし我が凡てこれに命ぜし事わが僕モーセがこれに命ぜし一切の律法を謹みて行はば我これが足をしてわがその先祖等に與へし地より重てさまよひ出ることなからしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, '然るに彼等は聽ことをせざりきマナセが人々を誘ひて惡をなせしことはヱホバがイスラエルの子孫の前に滅したまひし國々の人よりも甚だしかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, '是においてヱホバその僕なる預言者等をもて語て言給はく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'ユダの王マナセこれらの憎むべき事を行ひその前にありしアモリ人の凡て爲しところにも踰たる惡をなし亦ユダをしてその偶像をもて罪を犯させたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'イスラエルの神ヱホバかく言ふ視よ我ヱルサレムとユダに災害をくだす是を聞く者はその耳ふたつながら鳴ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, '我サマリヤを量りし繩とアハブの家にもちひし準縄をヱルサレムにほどこし人が皿を拭ひこれを拭ひて反覆がごとくにヱルサレムを拭ひさらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, '我わが產業の民の殘餘を棄てこれをその敵の手に付さん彼等はその諸の敵の擄掠にあひ掠奪にあふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, '是は彼等その先祖等がエジプトより出し日より今日にいたるまで吾目の前に惡をおこなひて我を怒らするが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'マナセはヱホバの目の前に惡をおこなひてユダに罪を犯させたる上にまた無辜者の血を多く流してヱルサレムのこの極よりかの極にまで盈せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'マナセのその餘の行爲とその凡て爲たる事およびその犯したる罪はユダの王の歴代志の書にしるさるるにあらすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'マナセその先祖等とともに寝りてその家の園すなはちウザの園に葬られその子アモンこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'アモンは王となれる時二十二歳にしてヱルサレムにおいて二年世を治めたりその母はヨテバのハルツの女にしてその名をメシユレメテと云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'アモンはその父マナセのなせしごとくヱホバの目の前に惡をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'すなはち彼は凡てその父のあゆみし道にあゆみその父の事へし偶像に事へてこれを拝み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'その先祖等の神ヱホバを棄てヱホバの道にあゆまざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, '茲にアモンの臣僕等黨をむすびて王をその家に弑したりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, '國の民そのアモン王に敵して黨をむすびし者をことごとく撃ころせり而して國の民アモンの子ヨシアを王となしてそれに代らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'アモンのなしたるその餘の行爲はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'アモンはウザの園にてその墓に葬られその子ヨシアこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'ヨシアは八歳にして王となりヱルサレムにおいて三十一年世を治めたり其母はボヅカテのアダヤの女にして名をヱデダと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'ヨシアはヱホバの目に適ふ事をなしその父ダビデの道にあゆみて右にも左にも轉らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'ヨシア王の十八年に王メシユラムの子アザリヤの子なる書記官シヤパンをヱホバの家に遣せり即ちこれに言けらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '汝祭司の長ヒルキヤの許にのぼり行てヱホバの家にいりし銀すなはち門守が民よりあつめし者を彼に計算しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, '工事を司どるヱホバの家の監督者の手にこれを付さしめ而してまた彼らをしてヱホの家にありて工事をなすところの者にこれを付さしめ殿の破壞を修理はしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, '即ち工匠と建築者と石工にこれを付さしめ又これをもて殿を修理ふ材木と斫石を買しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, '但し彼らは誠實に事をなせば彼らの手にわたすところの銀の計算をかれらとするには及ばざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, '時に祭司の長ヒルキヤ書記官シヤパンに言けるは我ヱホバの家において律法の書を見いだせりとヒルキヤすなはちその書をシヤパンにわたしたれば彼これを讀り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'かくて書記官シヤパン王の許にいたり王に返事まうして言ふ僕等殿にありし金を打あけてこれを工事を司どるヱホバの家の監督者の手に付せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, '書記官シヤパンまた王につげて祭司ヒルキヤ我に一書をわたせりと言ひシヤパン其を王の前に讀けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, '王その律法の書の言を聞やその衣を裂り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, '而して王祭司ヒルキヤとシヤパンの子アヒカムとミカヤの子アクボルと書記官シヤパンと王の内臣アサヤとに命じて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '汝等往てこの見當し書の言につきて我のため民のためユダ全國のためにヱホバに問へ其は我儕の先祖等はこの書の言に聽したがひてその凡て我儕のために記されたるところを行ふことをせざりしに因てヱホバの我儕にむかひて怒を發したまふこと甚だしかるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, '是において祭司ヒルキヤ、アヒカム、アクボル、シヤパンおよびアサヤ等シヤルムの妻なる女預言者ホルダの許にいたれりシヤルムはハルハスの子なるテクワの子にして衣裳の室を守る者なり時にホルダはヱルサレムの下邑に住をる彼等すなはちホルダに物語せしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'ホルダかれらに言けるはイスラエルの神ヱホバかく言たまふ汝等を我につかはせる人に告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'ヱホバかく言ふ我ユダの王が讀たるかの書の一切の言にしたがひて災害をこの處と此にすめる民に降さんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, '彼等はわれを棄て他の神に香を焚きその手に作れる諸の物をもて我を怒らするなり是故に我この處にむかひて怒の火を發す是は滅ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, '但し汝等をつかはして我に問しむるユダの王には汝等かく言べし汝が聞る言につきてイスラエルの神ヱホバかく言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, '汝はわが此處と此にすめる民にむかひて是は荒地となり呪詛とならんと言しを聞たる時に心柔にしてヱホバの前に身を卑し衣を裂て吾前に泣たれば我もまた聽ことをなすなりヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, '然ば視よ我なんぢを汝の先祖等に歸せしめん汝は安全に墓に歸することをうべし汝はわが此處にくだす諸の災害を目に見ることあらじと彼等すなはち王に返事まうしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, '是において王人をつかはしてユダとヱルサレムの長老をことごとく集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, '而して王ヱホバの家にのぼれりユダの諸の人々ヱルサレムの一切の民および祭司預言者ならびに大小の民みな之にしたがふ王すなはちヱホバの家に見あたりし契約の書の言をことごとくかれらの耳に讀きかせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, '而して王高座の上に立てヱホバの前に契約をなしヱホバにしたがひて歩み心をつくし精神をつくしてその誡命と律法と法度を守り此書にしるされたる此契約の言をおこなはんと言り民みなその契約に加はりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'かくして王祭司の長ヒルキヤとその下にたつところの祭司等および門守等に命じてヱホバの家よりしてバアルとアシラと天の衆群との爲に作りたる諸の器と執いださしめヱルサレムの外にてキデロンの野にこれを燒きその灰をベテルに持ゆかしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, '又ユダの王等が立てダの邑々とヱルサレムの四圍なる崇邱に香をたかしめたる祭司等を廢しまたバアルと日月星宿と天の衆群とに香を焚く者等をも廢せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, '彼またヱホバの家よりアシラ像をとりいだしヱルサレムの外に持ゆきてキデロン川にいたりキデロン川においてこれを燒きこれを打碎きて粉となしその粉を民の墓に散し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'またヱホバの家の旁にある男娼の家を毀てり其處はまた婦人がアシラのために天幕を織ところなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, '彼またユダの邑々より祭司をことごとく召よせまた祭司が香をたきたる崇邱をばゲバよりベエルシバまでこれを汚しまた門にある崇邱を毀てり是等の崇邱は一は邑の宰ヨシユアの門の入口にあり一は邑の門にありて之に入る人の左にあたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, '崇邱の祭司等はエルサレムにおいてヱホバの壇にのぼることをせざりき但し彼等はその兄弟の中にありて無酵パンを食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, '王また人がその子息息女に火の中を通らしめて之をモロクにささぐることなからんためにベンヒンノムの谷にあるトペテを汚し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'またユダの王等が日のためにささげてヱホバの家の門における馬をうつせりこの馬はパルリムにある侍從ナタンメレクの室にをりしなり彼また日の車を皆火に焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'またユダの王等がアハズの桜の屋背につくりたる祭壇とマナセがヱホバの家の兩の庭につくりたる祭壇とは王これを毀ちこれを其處より取くづしてその碎片をキデロン川になげ捨たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'またイスラエルの王ソロモンが昔シドン人の憎むべき者なるアシタロテとモアブ人の憎むべき者なるケモシとアンモンの子孫の憎むべき者なるモロクのためにヱルサレムの前において殲滅山の右に築きたる崇邱も王これを汚し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'また諸の像をうち碎きアシラ像をきりたふし人の骨をもてその處々に充せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'またベテルにある壇かのイスラエルに罪を犯させたるネバテの子ヤラベアムが造りし崇邱すなはちその壇もその崇邱も彼これを毀ちその崇邱を焚てこれを粉にうち碎きかつアシラ像を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, '茲にヨシア身をめぐらして山に墓のあるを見人をやりてその墓より骨をとりきたらしめ之をその壇の上に焚てそれを汚せり即ち神の人が宣たるヱホバの言のごとし昔神の人この言語を宣しことありしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'ヨシアまた其處に見ゆる碑は何なるやと言しに邑の人々これに告て其は汝がベテルの壇にむかひて爲るこの事等をユダより來りて宣たる神の人の墓なりと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'すなはち其には手をつくるなかれ誰もその骨を移すなかれと言り是をもてその骨とサマリヤより來りし預言者の骨には手をつけざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'またイスラエルの王等がサマリヤの邑々に造りてヱホバを怒せし崇邱の家も皆ヨシアこれを取のぞき凡てそのベテルになせしごとくに之に事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, '彼また其處にある崇邱の祭司等を壇の上にころし人の骨を壇の上に焚てヱルサレムに歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, '而して王一切の民に命じて言ふ汝らこの契約の書に記されたるごとくに汝らの神ヱホバに逾越の節を執行ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, '士師のイスラエルを治めし日より已來もまたユダの王等とイスラエルの王等の代にも斯のごとき逾越の節を守りしことはなかりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'ヨシア王の十八年にいたりてヱルサレムにて斯逾越節をヱホバに守りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'ヨシアまた祭司ヒルキヤがヱホバの家にて見いだせし書に記されたる律法の言を世におこなはんために口寄者と卜筮師とテラピムと偶像およびユダの地とヱルサレムに見ゆる諸の憎むべき者を取のぞけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'ヨシアの如くに心を盡し精神を盡し力を盡してモーセの法に全くしたがひてヱホに歸向せし王はヨシアの先にはあらざりきまた彼の後にも彼のごとき者はなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, '斯有しかどもヱホバはユダにむかひて怒を發したるその大いなる燃たつ震怒を息ることをしたまはざりき是はマナセ諸の憤らしき事をもてヱホバを怒らせしによるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'ヱホバすなはち言たまはく我イスラエルを移せし如くにユダをもわが目の前より拂ひ移し我が選みし此ヱルサレムの邑と吾名をそこに置んといひしこの殿とを棄べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'ヨシアのその餘の行爲とその凡て爲たる事はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'ヨシアの代にエジプトの王パロネコ、アッスリヤの王と戰はんとてユフラテ河をさして上り來しがヨシア王これを防がんとて進みゆきければ彼これに出あひてメギドンにこれを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'その僕等すなはちこれが死骸を車にのせてメギドンよりヱルサレムに持ゆきこれをその墓に葬れり國の民ここに於てヨシアの子ヱホアハズを取りこれに膏をそそぎて王となしてその父にかはらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'ヱホアハズは王となれる時二十三歳にしてヱルサレムにて三月世を治めたりその母はリブナのエレミヤの女にして名をハムタルと云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'ヱホアハズはその先祖等が凡てなしたるごとくにヱホバの目の前に惡をなせしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'パロネコ彼をハマテの地のリブラに繋ぎおきてヱルサレムにおいて王となりをることを得ざらしめ且銀百タラント金一タラントの罰金を國に課したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, '而してパロネコはヨシアの子エリアキムをしてその父ヨシアにかはりて王とならしめ彼の名をヱホヤキムと改めヱホアハズを曳て去ぬヱホアハズはエジプトにいたりて其處に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'ヱホヤキムは金銀をパロにおくれり即ち彼國に課してパロの命のままに金を出さしめ國の民各人に割つけて金銀を征取りてこれをパロネコにおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'ヱホヤキムは二十五歳にして王となりヱルサレムにおいて十一年世を治めたりその母はルマのペダヤの女にして名をゼブタと云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'ヱホヤキムはその先祖等が凡てなしたるごとくにヱホバの目の前に惡をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'ヱホヤキムの代にバビロンの王ネブカデネザル上り來りければヱホヤキムこれに臣服して三年をへたりしが遂にひるがへりて之に叛けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'ヱホバ、カルデヤの軍兵スリアの軍兵モアブの軍兵アンモンの軍兵をしてヱホヤキムの所に攻きたらしめたまへり即ちユダを滅さんがためにこれをユダに遣はしたまふヱホバがその僕なる預言者等によりて言たまひし言語のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'この事は全くヱホバの命によりてユダにのぞみし者にてユダをヱホバの目の前より拂ひ除かんがためなりき是はマナセがその凡てなす所において罪を犯したるにより');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'また無辜人の血をながし無辜人の血をヱルサレムに充したるによりてなりヱホバはその罪を赦すことをなしたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'ヱホヤキムのその餘の行爲とその凡て爲たる事はユダの王の歴代志の書にしるさるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'ヱホヤキムその先祖等とともに寝りその子ヱコニアこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, '却説またエジプトの王は重てその國より出きたらざりき其はバビロンの王エジプトの河よりユフラテ河まで凡てエジプトの王に屬する者を悉く取たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'ヱコニアは王となれる時十八歳にしてヱルサレムにて三月世を治めたりその母はヱルサレムのエルナタンの女にして名をネホシタと云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'ヱコニアはその父の凡てなしたるごとくにヱホバの目の前に惡をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'その頃バビロンの王ネブカデネザルの臣ヱルサレムに攻のぼりて邑を圍めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, '即ちバビロンの王ネブカデネザル邑に攻來りてその臣にこれを攻惱さしめたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'ユダの王ヱコニアその母その臣その牧伯等およびその侍從等とともに出てバビロンの王に降れりバビロンの王すなはち彼を執ふ是はその代の八年にあたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, '而して彼ヱホバの家の諸の寶物および王の家の寶物を其處より携へ去りイスラルの王ソロモンがヱホバの宮に造りたる諸の金の器を切はがせりヱホバの言たまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, '彼またヱルサレムの一切の民および一切の牧伯等と一切の大なる能力ある者ならびに工匠と鍛冶とを一萬人擄へゆけり遺れる者は國の民の賤き者のみなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, '彼すなはちヱコニアをバビロンに擄へゆきまた王の母王の妻等および侍從と國の中の能力ある者をもエルサレムよりバビロンに擄へうつせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, '凡て能力ある者七千人工匠と鍛冶一千人ならびに強壯して善戰ふ者是等をバビロンの王擄へてバビロンにうつせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, '而してバビロンの王またヱコニアの父の兄弟マツタニヤを王となしてヱコニアに代へ其が名をゼデキヤと改めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'ゼデキヤは二十一歳にして王となりヱルサレムにて十一年世を治めたりその母はリブナのヱレミヤの女にして名をハムタルと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'ゼデキヤはエホヤキムが凡てなしたるごとくにヱホバの目の前に惡をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'ヱルサレムとユダに斯る事ありしはヱホバの震怒による者にしてヱホバつひにその人々を自己の前よりはらひ棄たまへり偖またゼデキヤはバビロンの王に叛けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, '茲にゼデキヤの代の九年の十月十日にバビロンの王ネブカデネザルその諸軍勢を率てヱルサレムに攻きたりこれにむかひて陣を張り周圍に雲梯を建てこれを攻たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'かくこの邑攻かこまれてゼデキヤ王の十一年にまでおよびしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'その四月九日にいたりて城邑の中饑ること甚だしくなりその地の民食物を得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, '是をもて城邑つひに打破られければ兵卒はみな王の園の邊なる二箇の石垣の間の途より夜の中に逃いで皆平地の途にしたがひておちゆけり時にカルデア人は城邑を圍みをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, '茲にカルデア人の軍勢王を追ゆきヱリコの平地にてこれに追つきけるにその軍勢みな彼を離れて散しかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'カルデア人王を執へてこれをリブラにをるバビロンの王の許に曳ゆきてその罪をさだめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'ゼデキヤの子等をゼデキヤの目の前に殺しゼデキヤの目を抉しこれを鋼索につなぎてバビロンにたづさへゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'バビロンの王ネブカデネザルの代の十九年の五月七日にバビロンの王の臣侍衛の長ネブザラダン、ヱルサレムにきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'ヱホバの室と王の室を燒き火をもてヱルサレムのすべての室と一切の大なる室を燒り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'また侍衛の長とともにありしカルデア人の軍勢ヱルサレムの四周の石垣を毀てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, '侍衛の長ネブザラダンすなはち邑に遺されし殘餘の民およびバビロンの王に降りし降人と群衆の殘餘者を擄へうつせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, '但し侍衛の長その地の或貧者をのこして葡萄をつくる者となし農夫となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'カルデア人またヱホバの家の銅の柱と洗盤の臺と銅の海をくだきてその銅をバビロンに運び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'また鍋と火鏟と燈剪と匙および凡て役事に用ふる銅の器を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, '侍衛の長また火盤と鉢など金銀にて作れる物を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'またソロモンがヱホバの室に造しところの二の柱と一の海と臺とを取り此もろもろの銅の重は量るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'この柱は高さ十八キユビトにしてその上に銅の頂ありその頂の高は三キユビトその頂の四周に網子と石榴とありて皆銅なり他の柱とその網子もこれに同じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, '侍衛の長は祭司の長セラヤと第二の祭司ゼパニヤと三人の門守を執へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'また兵卒を督どる一人の寺人と王の前にはべる者の中邑にて遇しところの者五人とその地の民を募る軍勢の長なる書記官と城邑の中にて遇しところの六十人の者を邑より擄へされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, '侍衛の長ネブザラダンこれらを執へてリブラにをるバビロンの王の許にいたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'バビロンの王ハマテの地のリブラにてこれらを撃殺せりかくユダはおのれの地よりとらへ移されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'かくてバビロンの王ネブカデネザルは自己が遺してユダの地に止らしめし民の上にシヤパンの子なるアヒカムの子ゲダリヤをたててこれをその督者となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, '茲に軍勢の長等およびこれに屬する人々みなバビロンの王がゲダリヤを督者となせしことを聞しかばすなはちネタニヤの子イシマエル、カレヤの子ヨナハン、ネトバ人タンホメテの子セラヤおよび或マアカ人の子ヤザニヤならびに彼らに屬する人々ミヅパにきたりてゲダリヤの許にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'ゲダリヤすなはち彼等とかれらに屬する人々に誓ひてこれに言けるは汝等カルデア人の僕となることを恐るるなかれこの地に住てバビロンの王につかへなば汝等幸福ならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, '然るに七月に王の血統なるエリシヤマの子ネタニヤの子なるイシマエル十人の者とともに來りてゲダリヤを撃ころし又彼とともにミヅパにをりしユダヤ人とカルデア人を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, '是において大小の民および軍勢の長等みな起てエジプトにおもむけり是はカルデヤ人をおそれたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'ユダの王ヱホヤキムがとらへ移れたる後三十七年の十二月二十七日バビロンの王エビルメロダクその代の一年にユダの王ヱホヤキムを獄より出してその首をあげしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, '善言をもて彼をなぐさめその位をバビロンにともに居るところの王等の位よりも高くし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'その獄の衣服を易しめたりヱホヤキムは一生のあひだつねに王の前に食をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'かれ一生のあひだたえず日々の分を王よりたまはりてその食物となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'アダム、セツ、エノス');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'ケナン、マハラレル、ヤレド');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'エノク、メトセラ、ラメク');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'ノア、セム、ハム、ヤペテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'ヤベテの子等はゴメル、マゴグ、マデア、ヤワン、トバル、メセク、テラス');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'ゴメルの子等はアシケナズ、リパテ、トガルマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'ヤワンの子等はエリシヤ、タルシシ、キツテム、ドダニム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'ハムの子等はクシ、ミツライム、プテ、カナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'クシの子等はセバ、ハビラ、サブタ、ラアマ、サブテカ、ラアマの子等はセバとデダン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'クシ、ニムロデを生り彼はじめて世の權力ある者となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'ミツライムはルデ族アナミ族レハビ族ナフト族');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'パテロス族カスル族カフトリ族を生りカスル族よりペリシテ族出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'カナンその冢子シドンおよびヘテを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'またヱブス族アモリ族ギルガシ族');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'ヒビ族アルキ族セニ族');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'アルワデ族ゼマリ族ハマテ族を生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'セムの子等はエラム、アシユル、アルバクサデ、ルデ、アラム、ウズ、ホル、ゲテル、メセク');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'アルバクサデ、シラを生みシラ、エベルを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'エベルに二人の子生れたりその一人の名をベレグ(分)と曰ふ其は彼の代に地の人散り分れたればなりその弟の名をヨクタンと曰ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'ヨクタンはアルモダデ、シヤレフ、ハザルマウテ、ヱラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'ハドラム、ウザル、デクラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'エバル、アビマエル、シバ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'オフル、ハビラおよびヨハブを生り是等はみなヨクタンの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'セム、アルバクサデ、シラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'エベル、ベレグ、リウ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'セルグ、ナホル、テラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'アブラム是すなはちアブラハムなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'アブラハムの子等はイサクおよびイシマエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, '彼らの子孫は左のごとしイシマエルの冢子はネバヨテ次はケダル、アデビエル、ミブサム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'ミシマ、ドマ、マツサ、ハダデ、テマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'ヱトル、ネフシ、ケデマ、イシマエルの子孫は是の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'アブラハムの妾ケトラの生る子は左のごとし彼ジムラン、ヨクシヤン、メダン、ミデアン、イシバク、シユワを生りヨクシヤンの子等はシバおよびデダン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'ミデアンの子等はエバ、エペル、ヘノク、アビダ、エルダア是等はみなケトラの生る子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'アブラハム、イサクを生りイザクの子等はヱサウとイスラエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'エサウの子等はエリバズ、リウエル、ヱウシ、ヤラム、コラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'エリバズの子等はテマン、オマル、ゼビ、ガタム、ケナズ、テムナ、アマレク');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'リウエルの子等はナハテ、ゼラ、シヤンマ、ミツザ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'セイの子等はロタン、シヨバル、ヂベオン、アナ、デシヨン、エゼル、デシヤン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'ロタンの子等はホリとホマム、ロタンの妹はテムナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'シヨバルの子等はアルヤン、マナハテ、エバル、シピ、オナム、ヂベオンの子等はアヤとアナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'アナの子等はデシヨン、デシヨンの子等はハムラム、エシバン、イテラン、ケラン、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'エゼルの子等はビルハン、ザワン、ヤカン、デシヤンの子等はウズおよびアラン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'イスラエルの子孫を治むる王いまだ有ざる前にエドムの地を治めたる王等は左のごとしベオルの子ベラその都城の名はデナバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'ベラ薨てボズラのゼラの子ヨバブこれに代りて王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'ヨバブ薨てテマン人の地のホシヤムこれにかはりて王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'ホシヤム薨てベダデの子ハダデこれにかはりて王となれり彼モアブの野にてミデアン人を撃りその都城の名はアビテといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'ハダデ薨てマスレカのサムラこれに代りて王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'サムラ薨て河の旁なるレホボテのサウルこれに代りて王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'サウル薨てアクボルの子バアルハナンこれに代りて王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'バアルハナン薨てハダデこれにかはりて王となれりその都城の名はパイといふその妻はマテレデの女子にして名をメヘタベルといへりマテレデはメザハブの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'ハダデも薨たり/エドムの諸侯は左のごとし、テムナ侯アルヤ侯ヱテテ侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'アホリバマ侯エラ侯ピノン侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'ケナズ侯テマン侯ミブザル侯');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'マグデエル侯イラム侯エドムの諸侯は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'イスラエルの子等は左のごとしルベン、シメオン、レビ、ユダ、イツサカル、ゼブルン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'ダン、ヨセフ、ベニヤミン、ナフタリ、ガド、アセル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'ユダの子等はエル、オナン、シラなり この三人はカナンの女バテシユアがユダによりて生たるなり ユダの長子エルはヱホバの前に惡き事をなしたれば之を殺したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'ユダの媳タマルはユダによりてペレヅとゼラとを生りユダの子等は都合五人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'ペレヅの子等はヘヅロンおよびハムル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'ゼラの子等はジムリ、エタン、ヘマン、カルコル、ダラ都合五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'カルミの子はアカル、アカルは詛はれし物につきて罪を犯してイスラエルを惱ませし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'エタンの子はアザリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'ヘヅロンに生れたる子等はヱラメル、ラム、ケルバイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'ラム、アミナダブを生みアミナダブ、ナシヨンを生りナシヨンはユダの子孫の牧伯なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'ナシヨン、サルマを生みサルマ、ボアズを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'ボアズ、オベデを生み、オベデ、ヱツサイを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'ヱツサイの生る者は長子はエリアブ その次はアミナダブ その三はシヤンマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'その四はネタンエル その五はラダイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'その六はオゼム その七はダビデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'かれらの姉妹はゼルヤとアビガル、ゼルヤの產る子はアビシヤイ、ヨアブ、アサヘルあはせて三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'アビガルはアマサを產り アサの父はイシマエル人ヱテルといふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'ヘヅロンの子カレブはその妻アズバによりまたヱリオテによりて子を擧けたりその產る子等は左のごとし ヱシル、シヨバブおよびアルドン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'アズバ死たればカレブまたエフラタを娶れり エフラタ、カレブによりてホルを產り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'ホル、ウリを生み ウリ、ベザレルを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'その後ヘヅロンはギレアデの父マキルの女の所にいれりその之を娶れる時は六十歳なりき彼ヘヅロンによりてセグブを產り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'セグブ、ヤイルを生りヤイルはギレアデの地に邑二十三を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, '然るにゲシユルおよびアラム彼等よりヤイルの邑々およびケナテとその郷里など都合六十の邑を取り是皆ギレアデの父マキルの子等なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'ヘヅロン、カレブエフテタに死て後ヘヅロンの妻アビヤその子アシユルを生りアシユルはテコアの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'ヘヅロンの長子ヱラメルの子等は長子はラム 次はブナ、オレン、オゼム、アヒヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'ヱラメルはまた他の妻をもてりその名をアタラといふ彼はオナムの母なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'ヱラメルの長子ラムの子等はマアツ、ヤミン、エケル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'オナムの子等はシヤンマイ、ヤダ、シヤンマイの子等はナダブおよびアビシユル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'アビシユルの妻の名はアビハイルといふ彼アバンおよびモリデを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'ナダブの子等はセレデおよびアツパイム、セレデは子なくして死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'アツパイムの子はイシ、イシの子はセシヤン、セシヤンの子はアヘライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'シヤンマイの兄弟ヤダの子はヱテルおよびヨナタン、ヱテルは子なくして死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'ヨナタンの子等はペレテおよびザザ、ヱラメルの子孫は斯のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'セシヤンは男子なくして惟女子ありしのみなるがセシヤンにヤルハと名くるエジプトの僕ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'セシヤンその女をこの僕ヤルハに與へて妻となさしめたり彼ヤルハによりてアツタイを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'アツタイ、ナタンを生みナタン、ザバデを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'ザバデ、エフラルを生み エフラル、オベデを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'オベデ、ヱヒウを生み ヱヒウ、アザリヤを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'アザリヤ、ヘレヅを生み ヘレヅ、ヱレアサを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'ヱレアサ、シスマイを生み シスマイ、シヤルムを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'シヤルム、ヱカミヤを生み ヱカミヤ、エリシヤマを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'ヱラメルの兄弟カレブの子等はその長子をメシヤといふ是はジフの父なり ジフの子はマレシヤ、マレシヤはヘブロンの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'ヘブロンの子等はコラ、タツプア、レケム、シマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'シマはラハムを生り ラハムはヨルカムの父なり レケムはシヤンマイを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'シヤンマイの子はマオン、マオンはベテスルの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'カレブの妾エパでハラン、モザおよびガゼズを產り ハランはガゼズを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'ヱダイの子等はレゲム、ヨタム、ゲシヤン、ペレテ、エバ、シヤフ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'カレブの妾マアカはシベルおよびテルハナを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'またマデマンナの父シヤフおよびマクベナとギベアの父シワを生り カレブの女子はアクサといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'カレブの子孫は左のごとしエフラタの長子ホルの子はキリアテヤリムの父シヨバル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'ベテレヘムの父サルマおよびベテカデルの父ハレフ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'キリアタヤリムの父シヨバルの子等はハロエにメヌコテ人の半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'またキリアテヤリムの宗族はイテリ族プヒ族シユマ族ミシラ族 是等よりザレア族およびエシタオル族出たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'サルマの子孫はベテレヘム、ネトバ族アタロテベテヨアブ、マナハテ族の半およびゾリ族');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'ならびにヤベヅに住る諸士の宗族すなはちテラテ族シメアテ族スカテ族是等はケニ人にしてレカブの家の先祖ハマテより出たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'ヘブロンにて生れたるダビデの子等は左のごとし長子はアムノンといひてヱズレル人アヒノアムより生れ其次はダニエルといひてカルメル人アビガルより生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'その三はアブサロムといひてゲシユルの王タルマイの女マアカの生る子其四はアドニヤといひてハギテの生る子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'その五はシバテヤといひてアビタルより生れ其六はイテレアムといひて妻エグラより生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'この六人ヘブロンにてかれに生れたりダビデ彼處にて王たりし事七年と六箇月またヱルサレムにて王たりし事三十三年');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'ヱルサレムにて生れたるその子等は左のごとしシメア、シヨバブ、ナタン、ソロモンこの四人はアンミエルの女バテシユアより生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'またイブハル、エリシヤマ、エリペレテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'ノガ、ネペグ、ヤピア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'エリシヤマ、エリアダ、エリペレテの九人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, '是みなダビデの子なり此外にまた妾等の生る子等あり彼らの姉妹にタマルといふ者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'ソロモンの子はレハベアムその子はアビヤその子はアサその子はヨシヤパテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'その子はヨラムその子はアハジアその子はヨアシ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'その子はアマジヤその子はアザリヤモの子はヨタム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'その子はアハズその子はヒゼキヤその子はマナセ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'その子はアモンその子はヨシア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'ヨシアの子等は長子はヨハナンその次はヱホヤキムその三はゼデキヤその四はシヤルム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'ヱホヤキムの子等はその子はヱコニアその子はゼデキヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, '俘擄人ヱコニアの子等はその子シヤルテル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'マルキラム、ペダヤ、セナザル、ヱカミア、ホシヤマ、ネダビヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'ペダヤの子等はゼルバベルおよびシメイ、ゼルバベルの子等はメシユラムおよびハナニヤその姉妹にシロミテといふ者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'またハシユバ、オヘル、ベレキヤ、ハサデヤ、ユサブヘセデの五人あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'ハナニヤの子等はベラテヤおよびヱサヤまたレバヤの子等アルナンの子等オバデヤの子等シカニヤの子等あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'シカニヤの子はシマヤ、シマヤの子等はハツトシ、イガル、バリア、ネアリア、シヤパテの六人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'ネアリアの子等はエリヨエナイ、ヒゼキヤ、アズリカムの三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'エリヨエナイの子等はホダヤ、エリアシブ、ペラヤ、アツクブ、ヨハナン、デラヤ、アナニの七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'ユダの子等はペレヅ、ヘヅロン、カルミ、ホル、シヨバル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'シヨバルの子レアヤ、ヤハテを生みヤハテ、アホマイおよびラハデを生り是等はザレア人の宗族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'エタムの父の生る者は左のごとしヱズレル、イシマおよびイデバシその姉妹の名はハゼレルポニといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'ゲドルの父ペヌエル、ホシヤの父エゼル是等はベテレヘムの父エフラタの長子ホルの子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'テコアの父アシユルは二人の妻を有り即ちヘラとナアラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'ナアラ、アシユルによりてアホザム、へペル、テメニおよびアハシタリを產り是等はナアラの產る子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'ヘラの產る子はゼレテ、ヱゾアル、エテナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'ハツコヅはアヌブおよびゾベバを產り ハルムの子アハルヘルの宗族も彼より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'ヤベヅはその兄弟の中にて最も尊ばれたる者なりきその母我くるしみてこれを產たればといひてその名をヤベヅ(くるしみ)と名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'ヤベヅ、イスラエルの神に龥はり我を祝福に祝福て我境を擴め御手をもて我を助け我をして災難に罹りてくるしむこと無らしめたまへと言り神その求むる所を允したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'シユワの兄弟ケルブはメヒルを生りメヒルはエシトンの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'エシトンはベテラパ、パセアおよびイルハナシの父テヒンナを生り是等はレカの人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'ケナズの子等はオテニエルおよびセラヤ、オテニエルの子はハタテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'メオノタイはオフラを生みセラヤはヨアブを生りヨアブはカラシム(工匠)谷の人々の父なり彼處のものは工匠なればかくいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'ヱフンネの子カレブの子等はイル、エラおよびナアム、エラの子等およびケナズ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'ヱハレレルの子等はジフ、ジバ、テリア、アサレル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'エズラの子等はヱテル、メレデ、エペル、ヤロン、メレデの妻はミリアム、シヤンマイおよびイシバを產り イシバはエシテモアの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'そのユダヤ人なる妻はゲドルの父ヱレデとシヨコの父へベルとザノアの父ヱクテエルを產り是等はメレデが娶りたるパロの女ビテヤの生る子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'ナハムの姉妹なるホデヤの妻の生める子等はガルミ人ケイラの父およびマアカ人エシテモアなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'シモンの子等はアムノン、リンナ、ベネハナン、テロン、イシの子等はゾヘテおよびべネゾヘテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'ユダの子シラの子等はレカの父エル、マレシヤの父ラダおよび織布者の家の宗族すなはちアシベアの家の者等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'ならびにモアブに主たりしヨキム、コゼバの人々ヨアシおよびサラフ等なり またヤシユブ、レハムといふ者ありその記録は古し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, '是等の者は陶工にしてネタイムおよびゲデラに住み王の地に居りてその用をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'シメオンの子等はネムエル、ヤミン、ヤリブ、ゼラ、シヤウル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'シヤウルの子はシヤルム その子はミブサムその子はミシマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'ミシマの子はハムエル その子はザツクル その子はシメイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'シメイには男子十六人女子六人ありしがその兄弟等には多の子あらざりきまたその宗族の者は凡てユダの子孫ほどには殖増ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, '彼らの住る處はベエルシバ、モラダ、ハザルシユアル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'ビルハ、エゼム、トラデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'ベトエル、ホルマ、チクラグ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'ベテマルカボテ、ハザルスシム、ベテビリ、シヤライム是等の邑はダビデの世にたるまで彼等の有たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'その村郷はエタム、アイン、リンモン、トケン、アシヤンの五の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'またこの邑々の周圍に衆多の村ありてバアルにまでおよべり彼らの住處は是のごとくにして彼ら各々系譜あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'メシヨバブ、ヤムレク、アマジヤの子ヨシヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'ヨエル、アシエルの曾孫セラヤの孫ヨシビアの子ヱヒウ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'ヱリオエナイ、ヤコバ、ヱシヨハヤ、アサヤ、アデヱル、ヱシミエル、ベナヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'およびシピの子ジザ、シピはアロンの子 アロンはヱダヤの子 ヱダヤはシムリの子 シムリはシマヤの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, '此に名を擧げたる者等はその宗族の中の長たる者にしてその宗家は大に蔓延り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, '彼等はその群のために牧場を求めんとてゲドルの西におもむき谷の東の方にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'つひに膏腴なる善き牧場を見いだせしがその地は廣く靜穩にして安寧なりき其は昔より其處に住たりし者はハム人なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, '即ち上にその名を記したる者等ユダの王ヒゼキヤの代に往て彼らの幕屋を撃やぶり彼らと其處に居しメウニ人を盡く滅ぼし之に代りて其處に住て今日にいたる是はその群を牧べき牧場其處にありたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'またシメオンの子孫の者五百人許イシの子等ペラテア、ネアリア、レバヤ、ウジエルを長としてセイル山に攻ゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'アマレキ人の逃れて遺れる者を撃ほろぼして今日まで其處に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'イスラエルの長子ルベンの子等は左のごとしルベンは長子なりしがその父の床を瀆ししによりてその長子の權はイスラエルの子ヨセフの子等に與へらる然れども系譜は長子の權にしたがひて記すべきに非ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'そはユダその諸兄弟に勝る者となりて君たる者その中より出ればなり但し長子の權はヨセフに屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, '即ちイスラエルの長子ルベンの子等はハノク、パル、ヘヅロン、カルミ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'ヨエルの子はシマヤ その子はゴグ その子はシメイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'その子はミカ その子はレアヤ その子はバアル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'その子はベエラ このべエラはアッスリヤの王テルガテピルネセルに擄へられてゆけり彼はルベン人の中に牧伯たる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, '彼の兄弟等はその宗族に依りその歴代の系譜によれば左のごとし長ヱイエルおよびゼカリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'ベラ等なりベラはアザズの子シマの孫ヨエルの曾孫なりかれアロエルに住みて地をネボ、バアルメオンにまでおよぼししが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'ギレアデの地にてその家畜殖増ければまた地を東の方ユフラテ河の此方なる荒野の極端にまでおよぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'またサウルの時にハガリ人と戰爭してこれを打破りギレアデの東の全部なる彼らの幕屋に住たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'ガドの子孫はこれと相對ひてバシヤンの地にすみて地をサルカにまで及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, '長はヨエル次はシヤパム、ヤアナイ、シヤパテ共にバシヤンに居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, '彼らの兄弟等はその宗家によればミカエル、メシユラム、シバ、ヨライ、ヤカン、ジア、ヘベル都合七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, '是等はホリの子アビハイルの子等なり ホリはヤロアの子ヤロアはギレアデの子ギレアデはミカエルの子ミカエはヱシサイの子ヱシサイはヤドの子ヤドはブズの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'アヒはアブデルの子アブデルはグニの子グニは其宗家の長たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, '彼らはギレアデとバシヤンと其郷里とシヤロンの諸郊地に住て地を其四方の境に及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, '是等はみなユダの王ヨタムの世とイスラエルの王ヤラベアムの世に系譜に載たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'ルベンの子孫とガド人とマナセの半支派には出て戰ふべき者四萬四千七百六十人あり皆勇士にして能く楯と矛とを執り善く弓を彎きかつ善戰ふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, '彼等ハガリ人およびヱトル、ネフシ、ノダブ等と戰爭しけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, '助力をかうむりて攻撃たればハガリ人および之と偕なりし者等みな彼らの手におちいれり是は彼ら陣中にて神を呼びこれを賴みしによりて神これを聽いれたまひしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'かくて彼らその家畜を奪ひとりしに駱駝五萬 羊二十五萬 驢馬二千あり人十萬ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'またころされて倒れたる者衆しその戰爭神に由るがゆゑなり而して彼らはこれが地に代りて住その擄移さるる時におよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'マナセの半支派の人々はこの地に住み殖蔓りてつひにバシヤンよりバアルヘルモン、セニルおよびヘルモン山まで地をおよぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'その宗家の長は左のごとし即ちエペル、イシ、エリエル、アズリエル、ヱレミヤ、ホダヤ、ヤデエル是みなその宗家の長にして名ある大勇士なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, '彼等その先祖等の神にむかひて罪を犯し曾て彼等の前に神の滅ぼしたまひし國の民等の神を慕ひてこれと姦淫したれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'イスラエルの神アッスリヤの王ブルの心を振興しまたアッスリヤの王テグラテビレセルの心を振興したまへり彼つひにルベン人とガド人とマナセの半支派とを擄へゆきこれをハウラとハボルとハラとゴザンの河の邊とに移せり彼等は今日まで其處にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'レビの子等はゲルシヨン、コハテ、メラリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'コハテの子等はアムラム、イヅハル、ヘブロン、ウジエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'アムラムの子等はアロン、モーセ、ミリアム、アロンの子等はナダブ、アビウ、エレアザル、イタマル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'エレアザル、ピネハスを生み ピネハス、アビシユアを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'アビシユア、ブツキを生み ブツキ、ウジを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'ウジ、ゼラヒヤを生み ゼラヒヤ、メラヨテを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'メラヨテ、アマリヤを生み アマリヤ、アヒトブを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'アヒトブ、ザドクを生み ザドク、アヒマアズを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'アヒマアズ、アザリヤを生み アザリヤ、ヨハナンを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'ヨハナン、アザリヤを生り此アザリヤはヱルサレムなるソロモンの建たる宮にて祭司の職をなせし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'アザリヤ、アマリヤを生み アマリヤ、アヒトブを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'アヒトブ、ザドクを生み ザドク、シヤルムを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'シヤルム、ヒルキヤを生み ヒルキヤ、アザリヤを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'アザリヤ、セラヤを生み セラヤ、ヨザダクを生む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'ヨザダグはヱホバ、ネブカデネザルの手をもてユダおよびヱルサレムの人を擄へうつしたまひし時に擄へられて往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'レビの子等はゲルシヨン、コハテおよびメラリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'ゲルシヨンの子等の名は左のごとしリブニおよびシメイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'コハテの子等はアムラム、イヅハル、ヘブロン、ウジエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'メラリの子等はマヘリおよびムシ、レビ人の宗族はその宗家によれば是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'ゲシヨンの子はリブニ その子はヤハテ その子はジンマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'その子はヨア その子はイド その子はゼラ その子はヤテライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'コハテの子はアミナダブ その子はコラ その子はアシル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'その子はエルカナ その子はエビアサフ その子はアシル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'その子はタハテ その子はウリエル その子はウジヤ その子はシヤウル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'エルカナの子等はアマサイおよびアヒモテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'エルカナについてはエルカナの子はゾバイ その子はナハテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'その子はエリアブ その子はヱロハム その子はエルカナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'サムエルの子等は長子はヨエル 次はアビヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'メラリの子はマヘリ その子はリブニ その子はシメイ その子はウザ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'その子はシメア その子はハギヤ その子はアサヤなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, '契約の櫃を安置せし後ダビデ左の人々を立てヱホバの家にて謳歌事を司どらせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, '彼等は集會の幕屋の住所の前にて謳歌事をおこなひ來りしがソロモン、ヱルサレムにヱホバの室を建るにおよびその次序に循ひてその職をつとめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, '立て奉事をなせるものおよびその子等は左のごとしコハテの子等の中ヘマンは謳歌師長たり ヘマンはヨルの子 ヨエルはサムエルの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'サムエルはエルカナの子 エルカナはヱロハムの子 ヱロハムはエリエルの子 エリエルはトアの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'トアはヅフの子 ヅフはエルカナの子 エルカナはマハテの子 マハテはアマサイの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'アマサイはヱルカナの子 エルカナはヨエルの子 ヨエルはアザリヤの子 アザリヤはゼパニヤの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'ゼパニヤはタハテの子 タハテはアシルの子 アシルはエビアサフの子 エビアサフはコラの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'コラはイヅハルの子 イヅハルはコハテの子 コハテはレビの子 レビはイスラエルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'ヘマンの兄弟アサフ、ヘマンの右に立り アサフはベレキヤの子 ベレキヤはシメアの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'シメアはミカエルの子 ミカエルはバアセヤの子 バアセヤはマルキヤの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'マルキヤはエテニの子 エテニはゼラの子 ゼラはアダヤの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'アダヤはエタンの子 エタンはジンマの子 ジンマはシメイの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'シメイはヤハテの子 ヤハテはゲルシヨンの子 ゲルシヨンはレビの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'また彼らの兄弟なるメラリ人等その左に立り 其中のエタンはキシの子なり キシはアブデの子 アブデはマルクの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'マルクはハシヤビヤの子 ハシヤビヤはアマジヤの子 アマジヤはヒルキヤの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'ヒルキヤはアムジの子 アムジはバニの子 バニはセメルの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'セメルはマヘリの子 マヘリはムシの子 ムシはメラリの子 メラリはレビの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, '彼らの兄弟なるレビ人等は神の室の幕屋の諸の職に任ぜられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'アロンおよびその子等は燔祭の壇と香壇の上に物を献ぐることを司どりまた至聖所の諸の工をなし且イスラエルのために贖をなすことを司どれり凡て神の僕モーセの命じたるごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'アロンの子孫は左のごとし アロンの子はエレアザル その子はピネハス その子はアビシユア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'その子はブツキ その子はウジ その子はゼラヒヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'その子はメラヨテ その子はアマリヤ その子はアヒトブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'その子はザドク その子はアヒマアズ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'アロンの子孫の住處は四方の境の内にありその閭里に循ひていはば左の如し先コハテ人の宗族が籤によりて得たるところは是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'すなはちユダの地の中よりはヘブロンとその周圍の郊地を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, '但しその邑の田野と村々はヱフンネの子カレブに歸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'すなはちアロンの子孫の得たる邑は逃遁邑なるヘブロン、リブナとその郊地 ヤツテルおよびエシテモアとそれらの郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'ホロンとその郊地 デビルとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'アシヤンとその郊地 ベテシメシとその郊地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'またベニヤミンの支派の中よりはゲバとその郊地 アレメテとその郊地 アナトテとその郊地を得たり 彼らの邑はその宗族の中に都合十三ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'またコハテの子孫の支派の中此他なる者はかの半支派の中即ちマナセの半支派の中より籤によりて十の邑を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'またゲルシヨンの子孫の宗族はイツサカルの支派アセルの支派ナフタリの支派及びバシヤンなるマナセの支派の中より十三の邑を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'またメラリの子孫の宗族はルベンの支派ガドの支派およびゼブルンの支派の中より籤によりて十二の邑を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'イスラエルの子孫は邑とその郊地とをレビ人に與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, '即ちユダの子孫の支派とシメオンの子孫の支派とベニヤミンの子孫の支派の中よりして此に名を擧たる是等の邑を籤によりて之に與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'コハテの子孫の宗族はまたエフライムの支派の中よりも邑を得てその領地となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, '即ちその得たる逃遁邑はエフライム山のシケムとその郊地およびゲゼルとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'ヨクメアムとその郊地 ベテホロンとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'アヤロンとその郊地 ガテリンモンとその郊地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'またマナセの半支派の中よりはアネルとその郊地 ビレアムとその郊地是みなコハテの子孫の遺れる宗族に歸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'ゲルシヨンの子孫に歸せし者はマナセの半支派の宗族の中よりはバシヤンのゴランとその郊地 アシタロテとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'イツサカルの支派の中よりはゲデシとその郊地 ダベラテとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'ラモテとその郊地 アネムとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'アセル支派の中よりはミシアルとその郊地 アブドンとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'ホコクとその郊地レホブとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'ナフタリの支派の中よりはガリラヤのゲデシとその郊地 ハンモンとその郊地 キリアタイムとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, '比外の者すなはちメラリの子孫に歸せし者はゼブルンの支派の中よりはリンモンとその郊地 タボルとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'ヱリコに對するヨルダンの彼旁すなはちヨルダンの東においてルベンの支派の中よりは曠野のベゼルとその郊地 ヤザとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'ケデモテとその郊地 メバアテとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'ガドの支派の中よりはギレアデのラモテとその郊地 マハナイムとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'ヘシボンとその郊地 ヤゼルとその郊地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'イツサカルの子等はトラ、プワ、ヤシユブ、シムロムの四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'トラの子等はウジ、レバヤ、ヱリエル、ヤマイ、ヱブサム、サムエル是みなトラの子にして宗家の長なり其子孫の大勇士たる者はダビデの世にはその數二萬二千六百人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'ウジの子はイズラヒヤ、イズラヒヤの子等はミカエル、オバデヤ、ヨエル、イツシヤの五人是みな長たる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'その宗家によればその子孫の中に軍旅の士卒三萬六千人ありき是は彼等妻子を衆く有たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'イツサカルの諸の宗族の中なるその兄弟等すなはち名簿に記載たる大勇士は都合八萬七千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'ベニヤミンの子等はベラ、ベケル、ヱデアエルの三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'ベラの子等はエヅボン、ウジ、ウジエル、ヱレモテ、イリの五人 皆その宗家の長なりその名簿に記載たる大勇士は二萬二千三十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'ベケルの子等はセミラ、ヨアシ、エリエゼル、エリオエナイ、オムリ、ヱレモテ、アビヤ、アナトテ、アラメテ是みなベケルの子等にして宗家の長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'その子孫の中名簿に記載たる大勇士は二萬二百人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'またヱデアエルの子はビルハン、ビルハンの子等はヱウシ、ベニヤミン、エホデ、ケナアナ、ゼタン、タルシシ、アビシヤハル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, '是みなヱデアエルの子にして宗家の長たりきその子孫の中に能く陣にのぞみて戰ふ大勇士一萬七千二百人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'またイリの子等はシユパムおよびホパム、またアヘラの子はホシム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'ナフタリの子等はヤジエル、グニ、ヱゼル、シヤルム是みなビルハの產る子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'マナセの子等はその妻の產る者はアシリエルその妾なるスリアの女の產る者はギレアデの父マキル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'マキルはホパムとシユバムの妹名はマアカとい者を妻に娶れりその次の者はゼロペハデといふゼロペハデには女子ありしのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'マキルの妻マアカ男子を產てその名をペレシとよべりその弟の名はシヤレシ、シヤレシの子等はウラムおよびラケム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'ウラムの子はベダン是等はマナセの子マキルの子なるギレアデの子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'その妹ハンモレケテはイシホデ、アビエゼル、マヘラを產り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'セミダの子等はアヒアン、シケム、リキ、アニヤム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'エフライムの子はシユテラ その子はベレデ その子はタハテ その子はエラダ その子はタハテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'その子はザバデ その子はシユテラ エゼルとエレアデはガテの土人等これを殺せり其は彼ら下りゆきてこれが家畜を奪はんとしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'その父エフライムこれがために哀むこと日久しかりければその兄弟等きたりてこれを慰さめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'かくて後エフライムその妻の所にいりけるに胎みて男子を生たればその名をベリア(災難)ごとなづけたりその家に災難ありたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'エフライムの女子セラは上下のベテホロンおよびウゼンセラを建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'ベリアの子はレバおよびレセフ その子はテラ その子はタハン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'その子はラダン その子はアミホデ その子はエリシヤマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'その子はヌン その子はヨシユア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'エフライムの子孫の產業と住處はベテルとその郷里 また東の方にてはナアラン 西の方にてはゲゼルとその郷里 またシケムとその郷里 およびアワとその郷里');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'またマナセの子孫の國境に沿てはベテシヤンとその郷里 タアナクとその郷里 メギドンとその郷里 ドルとその郷里なり イスラエルの子ヨセフの子孫は是等の處に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'アセルの子等はイムナ、イシワ、ヱスイ、ベリアおよびその姉妹セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'ベリアの子等はヘベルおよびマルキエル、マルキエルはビルザヒテの父なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'ヘベルはヤフレテ、シヨメル、ホタムおよびその姉妹シユワを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'ヤフレテの子等はバサク、ビムハル、アシワテ、ヤフレテの子等は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'シヨメルの子等はアヒ、ロガ、ホバおよびアラム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'シヨメルの兄弟ヘレムの子等はゾバ、イムナ、シレン、アマル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'ゾバの子等はスア、ハルネペル、シユアル、ベリ、イムラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'ベゼル、ホド、シヤンマ、シルシヤ、イテラン、ベエラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'ヱテルの子等はヱフンネ、ピスパおよびアラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'ウラの子等はアラ、ハニエルおよびリヂア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, '是みなアセルの子孫にして宗家の長たり挺出たる大勇士たり將官の長たりきその名簿に記載たる能く陣にのぞみて戰ふ者二萬六千人あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'ベニヤミンの生る者は長子はベラ その次はアシベル その三はアハラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'その四はアハ その五はラパ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'ベラの子等はアダル、ゲラ、アビウデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'アビシユア、ナアマン、アホア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'ゲラ、シフパム、ヒラム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'エホデの子等は左のごとし是等はゲバの民の宗家の長なり是はマナハテに移されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'すなはちナアマンおよびアヒヤとともにゲラこれを移せるなりエホデの子等はすなはちウザとアヒウデ是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'シヤハライムはその妻ホシムとバアラを去し後モアブの國においてまた子等を擧けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, '彼がその妻ホデシによりて擧けたる子等はヨバブ、ヂビア、メシヤ、マルカム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'ヱウツ、シヤキヤおよびミルマ是その子等にして宗家の長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, '彼またホシムによりてアビトブとエルパアルを擧けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'エルパアルの子等はエベル、ミシヤムおよびシヤメル彼はオノとロドとその郷里を建たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'またベリア、シマあり是等はアヤロンの民の宗家の長たる者にしてガテの民を逐はらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'またアヒオ、シヤシヤク、エレモテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'ゼバデヤ、アラデ、アデル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'ミカエル、イシパ、ヨハ是等はベリアの子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'ゼバデヤ、メシユラム、ヘゼキ、ヘベル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'イシメライ、ヱズリア、ヨバブ是等はエルパアルの子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'ヤキン、ジクリ、ザベデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'エリエナイ、チルタイ、エリエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'アダヤ、ベラヤ、シムラテ是等はシマの子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'イシパン、へベル、エリエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'アブドン、ジクリ、ハナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'ハナニヤ、エラム、アントテヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'イペデヤ、ペヌエル是等はシヤシヤタの子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'シヤムセライ、シハリア、アタリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'ヤレシヤ、エリヤ、ジクリ是等はヱロハムの子等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, '是等は歴代の宗家の長にして首たるものなり是らはエルサレムに住たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'ギベオンの祖はギベオンに住りその妻の名はマアカといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'その長子はアブドン、次はツル、キシ、バアル、ナダブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'ゲドル、アヒオ、ザケル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'ミクロテはシメアを生り是等も又その兄弟等とともにヱルサレムに住てこれに對ひ居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'ネル、キシを生み キシ、サウルを生みサウルはヨナタン、マルキシユア、アビナダプ、エシバアルを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'ヨナタンの子はメリバアル、メリバアル、ミカを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'ミカの子等はピトン、メレク、ダレア、アハズ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'アハズはヱホアダを生み ヱホアダはアレメテ、アズマウテおよびジムリを生み ジムリはモザを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'モザはビネアを生り その子はラパ その子はニレアサ その子はアゼル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'アゼルには六人の子あり其名は左のごとしアズリカム、ボケル、イシマエル、シヤリヤ、オバデヤ、ハナン是みなアゼルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'その兄弟エセクの子等の長子はウラムその次はヱウンその三はエリペレテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'ウラムの子等は大勇士にして善く弓を射る者なりき彼は孫子多くして百五十人もありき是みなベニヤミンの子孫なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'イスラエルの人は皆名簿に記載られたり視よ是は皆イスラエルの列王紀に録さるユダはその罪のためにバビロンに擄へられてゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'その產業の邑々に最初に住ひし者にイスラエル人 祭司等レビ人およびネテニ人等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'またヱルサレムにはユダの子孫ベニヤミンの子孫およびエフライムとマナセの子孫等住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, '即ちユダの子ペレヅの子孫の中にてはアミホデの子ウタイ、アミホデはオムリの子 オムリはイムリの子イムリはバニの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'シロ族の中にてはシロの長子アサヤおよびその他の子等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'ゼラの子孫の中にてはユエルおよびその兄弟六百九十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'ベニヤミンの子孫の中にてけハセヌアの子ハダヤの子なるメシユラムの子サル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'ヱロハムの子イブニヤ、ミクリの子なるウジの子エラおよびイブニヤの子リウエルの子なるシパテヤの子メシユラム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, '並に彼らの兄弟等その世系によれば合せて九百五十六人是みなその宗家の長たる人々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'また祭司の中にてはヱダヤ、ヨアリブ、ヤキン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'およびヒルキヤの子アザリヤ、ヒルキヤはメシユラムの子 メシユラムはザドクの子 ザドクはメラヨテの子 メラヨテはアヒトブの子なり アザリヤは神の室の宰たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'またヱロハムの子アダヤ、ヱロハムはバシユルの子 バシユルはマルキヤの子なり またアデエルの子マアセヤ、アデエルはヤゼラの子 ヤゼラはメシユラムの子 メシユラムはメシレモテの子 メシレモテはインメルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'また彼らの兄弟等是等は宗家の長たる者にして合せて一千七百六十人あり皆神の室の奉事をなすの力あるものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'レビ人の中にてはハシユブの子シマヤ、ハシユブはアズリカムの子 アズリカムはハシヤビヤの子 是はメラリの子孫なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'またバクバツカル、ヘレシ、ガラルおよびアサフの子ジクリの子なるミカの子マツタニヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'ならびにヱドトンの子ガラルの子なるシマヤの子オバデヤおよびエルカナの子なるアサの子ベレキヤ、エルカナはネトバ人の郷里に住たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, '門を守る者はシヤルム、アツクブ、タルモン、アヒマンおよびその兄弟等にしてシヤレムその長たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, '彼は今日まで東の方なる王の門を守りをる是等はレビの子孫の營の門を守る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'コラの子エビアサフの子なるコレの子シヤルムおよびその父の家の兄弟等などのコラ人は幕屋の門々を守る職務を主どれりその先祖等はヱホバの營の傍にありてその入口を守れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'エレアザルの子ピネハス昔彼らの主宰たりきヱホバ彼とともに在せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'メシレミヤの子ゼカリヤは集會の幕屋の門を守る者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, '是みな選ばれて門を守る者にて合せて二百十二人ありき皆その村々の名簿に記載たる者なりしがダビデと先見者サムエルこれをその職に任じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, '彼等とその子孫は順番にヱホバの室すなはち幕屋の門を司どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, '門を守る者は西東北南の四方に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'またその村々に居る兄弟等は七日ごとに迭り來りて彼らを助けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, '門を守る者の長たるこの四人のレビ人はその職にをりて神の室の諸の室と府庫とを司どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, '彼らは番守をなす身なるに因て神の室の四周に舎れり而して朝ごとにこれを開くことをせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'その中に奉事の器皿を司どる者あり是はその數を按べて携へいりそり數を按べて携へいだすべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'またその他の器皿すなはち聖所の一切の器皿および麥粉 酒 油 乳香 香料を司どる者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'また祭司の徒の中に香料をもて香膏を製る者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'コラ人シヤルムの長子なるマツタテヤといふレビ人は鍋にて製るところの物を司どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'またコハテ人の子孫たるその兄弟等の中に供前のパンを司どりて安息日ごとにこれを調ふる者等あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'レビ人の宗家の長たる是等の者は謳歌師にして殿の諸の室に居て他の職を爲ざりき其は日夜その職務にかかりをればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, '是等はレビ人の歴代の宗家の長にして首長たる者なり是等はヱルサレムに住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'ギベオンの祖ヱヒエルはギベオンに住りその妻の名はマアカといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'その長子はアブドン次はツル、キシ、バアル、ネル、ナダブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'ゲドル、アヒオ、ゼカリヤ、ミクロテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'ミクロテ、シメアムを生り彼等もその兄弟等とともにヱルサレムに住てその兄弟等と相對ひ居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'ネルはキシを生み キシはサウルを生み サウルはヨナタン、マルキシユア、アビナダブおよびエシバアタを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'ヨナタンの子はメリバアル、メリバアル、ミカを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'ミカの子等はピトン、メレク、タレアおよびアハズ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'アハズはヤラを生み ヤラはアレメテ、アズマウテおよびジムリを生み ジムリはモザを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'モザはピネアを生り ピネアの子はレバヤ その子はエレアサ その子はアゼル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'アゼルは六人の子ありきその名は左のごとしアズリカム、ボケル、イシマエル、シヤリヤ、オバデヤ、ハナン是等はアゼルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, '茲にペリシテ人イスラエルと戰ひけるがイスラエルの人々はペリシテ人の前より逃げギルボア山に殺されて倒れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'ペリシテ人はサウルとその子等を追撃しかしてペリシテ人サウルの子ヨナタン、アビナダブおよびマルキシユアを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, '斯その戰闘烈しうしてサウルにおし迫り射手の者等つひにサウルに追つきければサウルは射手の者等のために惱めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'サウル是におひてその武器を執る者に言けるは汝の劍をぬき其をもて我を刺せ恐らくはこの割禮なき者等きたりて我を辱しめんと然るにその武器を執る者痛くおそれて肯はざりければサウルすなはちその劍をとりてその上に伏たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, '武器を執る者サウルの死たるを見て己もまた劍の上に伏て死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, '斯サウルとその三人の子等およびその家族みな共に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, '谷に居るイスラエルの人々みな彼らの逃るを見またサウルとその子等の死るを見てその邑々を棄て逃ければペリシテ人來りてその中に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, '明る日ペリシテ人殺されたる者を剥んとて來りサウルとその子等のギルボア山にたふれをるを見');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'すなはちサウルを剥てその首とその鎧甲を取りペリシテの國の四方に人を遣はしてこの事をその偶像と民に告しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'しかしてかれが鎧甲をその神の室に蔵め彼が首をダゴンの宮に釘けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, '茲にペリシテ人がサウルになしたる事ことごとくヤベシギレアデ中に聞えければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, '勇士等みな起りサウルの體とその子等の體とを奪ひ取てこれをヤベシに持きたりヤベシの橡樹の下にその骨を葬りて七日のあひだ斷食せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, '斯サウルはヱホバにむかひて犯せし罪のために死たり即ち彼はヱホバの言を守らすまた憑鬼者に問ことを爲して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'ヱホバに問ことをせざりしなり是をもてヱホバかれを殺しその國を移してヱツサイの子ダビデに與へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, '茲にイスラエルの人みなヘブロンに集まりてダビデの許に詣り言けるは我らは汝の骨肉なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, '前にサウルが王たりし時にも汝はイスラエルを率ゐで出入する者なりき又なんぢの神ヱホバ汝にむかひて汝はわが民イスラエルを牧養ふ者となり我民イスラエルの君とならんと言たまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, '斯イスラエルの長老みなヘブロンにきたりて王の許にいたりければダビデ、ヘブロンにてヱホバの前に彼らと契約をたてたり彼らすなはちダビデに膏をそそぎてイスラエルの王となしサムエルによりて傳はりしヱホバの言のごとくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'かくてダビデはイスラエルの人々を率ゐてエルサレムに往りヱルサレムは即ちヱブスなりその國の土人ヱブス人其處に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, '是においてヱブスの民ダビデに言けるは汝は此に入べからずと然るにダビデはシオンの城を取り是すなはちダビデの邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'この時ダビデいひけるは誰にもあれ第一にエブス人を撃やぶる者を首となし將となさんと斯てゼルヤの子ヨアブ先登して首となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'ダビデその城に住たればこれをダビデの邑と稱へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'ダビデまたその邑の四方すなはちミロ(城塞)より内の四方に建築をなせり邑の中のその餘の處はヨアブこれを修理へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, '斯てダビデはますます大になりゆけり萬軍のヱホバこれとともに在したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'ダビデが有る勇士の重なる者は左のごとし是等はイスラエルの一切の人とともにダビデに力をそへて國を得させ終にこれを王となしてヱホバがイスラエルにつきて宣ひし言を果せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'ダビデの有る勇士の數は是のごとし第一は三十人の長たるハクモニ人の子ヤシヨベアム彼は槍を揮ひて一時に三百人を衝殺せし事あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, '彼の次はアホア人ドドの子エレアザルにして三勇士の中なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, '彼ダビデとともにパスダミムに在けるにペリシテ人其處に集りきて戰へり其處に大麥の滿たる地一箇所あり時に民ペリシテ人の前より逃たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, '彼その地所の中に踐とどまり之を護りてペリシテ人を殺せり而してヱホバ大なる拯救をほどこして之を救ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, '三十人の長なる三人の者アドラムの洞穴に下り磐の處に往てダビデに詣りし事あり時にペリシテ人の軍兵はレパイムの谷に陣どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'その時ダビデは砦に居りペリシテ人の鎮臺兵はベテレヘムにありけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'ダビデ慕ひ望みて言けるは誰かベテレヘムの門にある井の水を持來りて我に飮せよかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'この三人すなはちペリシテ人の軍兵の中を衝とほりてベテレヘムの門にある井の水を汲取てダビデの許に携へきたれり然どダビデこれを飮ことをせす之をヱホバの前に灌ぎて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, '言けるは我神よ我決てこれを爲じ我いかで命をかけし此三人の血を飮べけんやと彼らその命をかけて之を携へきたりたればなり故にダビデこれを飮ことを爲ざりき此三勇士は是らの事を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'ヨアブの兄弟アビシヤイは三人の長たり彼は槍を揮ひて三百人を衝ころし三人の中に名を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, '彼は第二の三人の中にて尤も貴くしてその首にせらる然ど第一の三人には及ばざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'ヱホヤダの子カブジエルのベナヤは勇氣あり衆多の功績ありし者なり彼はモアブのアリエルの二人の子を撃殺せりまた雪の日に下りゆきて穴の中にて獅子一匹を撃殺せし事ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, '彼はまた長身五キユビト程なるエジプト人を殺せりそのエジプト人は機織の滕のごとき槍を手に執をりしに彼は杖をとりて之が許に下りゆきエジプト人の手よりその槍を捩とりてその槍をもて之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'ヱホヤダの子ベナヤ是等の事を爲し三勇士の中に名を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, '彼は三十人の中にて尊かりしかども第一の三人には及ばざりきダビデかれを親兵の長となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, '軍兵の中の勇士はヨアブの兄弟アサヘル、ベテレヘムのドドの子エルハナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'ハロデ人シヤンマ、ペロニ人ヘレヅ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'テコア人イツケシの子イラ、アナトテ人アビエゼル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'ホシヤ人シベカイ、アホア人イライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'ネトパ人マハライ、ネトパ人バナアの子ヘレデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'ベニヤミンの子孫のギベアより出たるリバイの子イツタイ、ピラトン人ベナヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'ガアシの谷のホライ、アルバテ人アビエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'バハルム人アズマウテ、シヤルボニ人エリヤバ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'ギゾニ人ハセム、ハラリ人シヤゲの子ヨナタン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'ハラリ人サカルの子アヒアム、ウルの子エリパル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'メケラ人へペル、ペロニ人アヒヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'カルメル人ヘヅライ、エズバイの子ナアライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'ナタンの兄弟ヨエル、ハグリの子ミブハル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'アンモニ人ゼレク、ゼルヤの子ヨアブの武器を執る者なるベエロテ人ナハライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'エテリ人イラ、エテリ人ガレブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'ヘテ人ウリヤ、アヘライの子ザバデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'ルベン人シザの子アデナ是はルベン人の軍長の一人にして從者三十人を率ゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'マアカの子ハナン、ミテニ人ヨシヤバテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'アシテラ人ウジヤ、アロエル人ホタンの子等シヤマとヱイエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'デジ人シムリの子エデアエルおよびその兄弟ヨハ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'マハウ人エリエル、エルナアムの子等エリバイおよびヨシヤワヤ、モアブ人イテマ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'エリエル、オベデ、ソメバ人ヤシエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'ダビデがキシの子サウルの故によりて尚チクラグに閉こもり居ける時に彼處にゆきてダビデに就し者は左のごとしその人々は勇士の中にしてダビデを助けて戰ひたる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, '能く弓を彎き右左の手を用ゐて善く石を投げ弓矢を發つ者なりしが倶にベニヤミン人にしてサウルの宗族たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, '首はアヒエゼル次はヨアシ是らはギベア人シマアの子等なり又ヱジエルおよびペレテ是らはアズマウラの子等なり又ベラカおよびアナトテ人ヱヒウ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'またギベオン人イシマヤ彼は三十人の中の勇士にして三十人の首なり又エレミヤ、ヤハジエル、ヨハナン、ゲデラ人ヨザバデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'エルザイ、エリモテ、ベアリヤ、シマリヤ、ハリフ人シバテヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'エルカナ、エシヤ、アザリエル、ヨエゼル、ヤシヨベアム是等はコラ人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'またゲドルのエロハムの子等たるヨエラおよひゼバデヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'ガド人の中より曠野の砦に脱きたりてダビデに歸せし者あり是みな大勇士にして善戰かふ軍人能く楯と戈とをつかふ者にてその面は獅子の面のごとくその捷きことは山にをる鹿のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'その首はエゼルその二はオバデヤその三はエリアブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'その四はミシマンナその五はヱレミヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'その六はアツタイその六はエリエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'その八はヨハナンその九はエルザバデ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'その十はヱレミヤその十一はマクバナイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, '是等はガドの人々にして軍旅の長たりそ最も小き者は百人に當りその最も大なる者は千人に當れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, '正月ヨルダンその全岸に溢れたる時に是らの者濟りゆきて谷々に居る者をことごとく東西に打奔らせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, '茲にベニヤミンとユダの子孫の中の人々砦に來りてダビデに就きけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'ダビデこれを出むかへ應へて之に言けるは汝ら厚志をもて我を助けんとて來れるならば我心なんぢらと相結ばん然ど汝らもし我手に惡きこと有ざるに我を欺きて敵に付さんとせば我らの先祖の神ねがはくは之を監みて責たまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, '時に聖霊三十人の長アマサイに臨みて彼すなはち言けるはダビデよ我らは汝に屬すヱツサイの子よ我らは汝を助けん願くは平安あれ汝にも平安あれ汝を助くる者にも平安あれ汝の神汝を助けたまふなりと是においてダビデ彼らを接いれて軍旅の長となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, '前にダビデ、ペリシテ人とともにサウルと戰はんとて攻きたれる時マナセ人數人ダビデに屬り但しダビデ等は遂にペリシテ人を助けざりき其はペリシテ人の君等あひ謀り彼は我らの首級をもてその主君サウルに歸らんと言て彼を去しめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, '斯てダビデ、チクラグに往る時マナセ人アデナ、ヨザバデ、ヱデアエル、ミカエル、ヨザバデ、エリウ、ヂルタイこれに歸せり皆マナセ人の千人の長たる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, '彼等ダビデを助けて敵軍に當れり彼らは皆大勇士にして軍旅の長となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, '當時ダビデに歸して之を助くる者日々に加はりて終に大軍となり神の軍旅のごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, '戰爭のために身をよろひヘブロンに來りてダビデに就きヱホバの言のごとくサウルの國をダビデに歸せしめんとしたる武士の數は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'ユダの子孫にして楯と戈とを執り戰爭のために身をよろへる者は六千八百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'シメオンの子孫にして善戰かふ大勇士は七千一百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'レビの子孫たる者は四千六百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'ヱホヤダ、アロン人を率ゐたり之に屬する者は三千七百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'またザドクといふ年若き勇士ありきその宗家の長たる者二十二人ありたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'サウルの宗族ベニヤミンの子孫たる者は三千人是ベニヤミン人は多くサウルの家に尚も忠義を盡しゐたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'エフライムの子孫たる者は二萬八百人皆大勇士にしてその宗家の名ある人々たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'マナセの半支派の者は一萬八千人皆名を録されたる者なるが來りてダビデを王にたてんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'イツサカルの子孫たる者の中より善く時勢に通じイスラエルの爲べきことを知る者きたれりその首二百人ありその兄弟等は皆これが指揮にしたがへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'ゼブルンの者は五萬人皆よく身をよろひ各種の武器をもて善く戰闘をなし一心に行伍を守る者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'ナフタリの者は將たる者千人楯と戈とを執てこれに從ふ者三萬七千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'ダン人は二萬八千六百人にして皆そなへを守る者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'アセルの者は四萬人にして皆よく陣にのぞみ且行伍を守る者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'またヨルダンの彼旁なるルベン人とガド人とマナセの半支派の者は十二萬人みな各種の武器を執て戰爭にいづるに勝る者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, '是等の行伍を守る軍人等眞實の心を懐きてヘブロンに來りダビデをもてイスラエル全國の王となさんとせり其餘のイスラエル人もまた心を一にしてダビデを王となさんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, '彼ら彼處に三日をりてダビデとともに食ひかつ飮り其はその兄弟等これがために備をなしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'また近處の者よりイツサカル、ゼブルンおよびナフタリの者に至るまでパンと麥粉の食物と乾無花果と乾葡萄と酒と油等を驢馬駱駝牛馬に載きたりかつ牛羊を多く携へいたれり是イスラエルみな喜びたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, '茲にダビデ千人の長百人の長などの諸將とあひ議り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, '而してダビデ、イスラエルの全會衆に言けるは汝らもし之を善とし我らの神ヱホバこれを允したまはば我ら徧く人を遣してイスラエルの各地に留まれる我らの兄弟ならびにその諸郊地の邑々にをる祭司とレビ人とに至らせ之をして我らの所に集まらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, '而して我らまた我らの神の契約の櫃を我らの所に移さんサウルの世には我ら之に就て詢ことをせざりしなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, '會衆みな然すべしと言り其は民みな此事を善と觀たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, '是においてダピデはキリアテヤリムより神の契約の櫃を舁きたらんとてエジプトのジホルよりハマテの入口までのイスラエル人をことごとく召あつめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, '而してダビデ、イスラエルの一切の人とともにバアラといふユダのキリアテヤリムに上り往きケルビムの上に坐したまふヱホバ神の名をもて稱らるる契約の櫃を其處より舁のぼらんとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, '乃ち神の契約の櫃を新しき車に載てアビナダブの家より牽いだしウザとアヒオその車を御せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'ダビデおよびイスラエルの人はみな歌と琴と瑟と鼗鼓と鐃鈸と喇叭などを以て力をきはめ歌をうたひて神の前に踊れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'かくてキドンの禾場に至れる時ウザ手を神の契約の櫃に伸してこれを扶へたり其は牛これを振たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'ウザその手を伸て契約の櫃につけたるによりてヱホバこれに向ひて忿怒を發してこれを撃たまびければ其處にて神の前に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'ヱホバ、ウザを撃たまひしに因てダビデ怒れり其處は今日までペレヅウザ(ウザ撃)と稱へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'その日ダビデ神を畏れて言り我なんぞ神の契約の櫃を我所に舁ゆくべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'ダビデその契約の櫃を己のところダビデの城邑にうつさず之を轉らしてガテ人オベデエドムの家に舁いらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, '神の契約の櫃オベデエドムの家にありて其家族とともにおかかるること三月なりきヱホバ、オベデエドムの家とその一切の所有を祝福たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, '茲にツロの王ヒラム使者をダビデに遣はし之がために家を建させんとて香柏および木匠と石工をおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'ダビデはヱホバの固く己をたててイスラエルの王となしたまへるを暁れり其はその民イスラエルの故によりてその國振ひ興りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'ダビデ、ヱルサレムにおいてまた妻妾を納たり而してダビデまた男子女子を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'そのヱルサレムにて得たる子等の名は左のごとしシヤンマ、シヨバブ、ナタン、ソロモン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'イブハル、エリシユア、エルバレテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'ノガ、ネベグ、ヤピア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'エリシヤマ、ベエリアダ、エリバレテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, '茲にダビデの膏そそがれてイスラエル全國の王となれる事ペリシテ人に聞えければペリシテ人みなダビデを獲んとて上れりダビデは聞て之に當らんとて出たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'ペリシテ人すでに來りてレバイムの谷を侵したりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, '時にダビデ神に問て言けるは我ペリシテ人にむかひて攻上るべきや汝彼らを吾手に付し給ふやヱホバ、ダビデに言たまひけるは攻上れ我かれらを汝の手に付さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, '是において皆バアルベラジムに上りゆきけるがダビデつひに彼處にて彼らを打敗り而してダビデ言り神水の破壞り出るごとくに我手をもてわが敵を敗りたまへりと是をもてその處の名をバアルペラジム(破壞の處)と呼ぶなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, '彼ら其處にその神々を遺ゆきたればダビデ命じて火をもてこれを焚せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, '斯て後ペリシテ人復谷を侵しければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'ダビデまた神に問に神これに言たまひけるは彼らを追て上るべからず彼らを離れて回りベカの樹の方よりこれを襲へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, '汝ベカの樹の上に進行の音あるを聞ば即ち進んで戰ふべし神汝のまへに進みいでペリシテ人の軍勢を撃たまふべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'ダビデすなはち神の己に命じたまひし如くしてペリシテ人の軍勢を撃やぶりつつギベオンよりガゼルにまでいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, '是においてダビデの名諸の國々に聞えわたりヱホバ諸の國人に彼を懼れしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'ダビデはダビデの邑の中に自己のために家を建て又神の契約の櫃のために處を備へてこれがために幕屋を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, '而してダビデ言けるは神の契約の櫃を舁べき者は只レビ人のみ其はヱホバ神の契約の櫃を舁しめまた己に永く事しめんとてレビ人を擇びたまひたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'ダビデすなはちヱホバの契約の櫃をその之がために備へたる處に舁のぼらんとてイスラエルをことごとくエルサレムに召集めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'ダビデまたアロンの子孫とレビ人を集めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, '即ちコハテの子孫の中よりはウリエルを長としてその兄弟百二十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'メラリの子孫の中よりはアサヤを長としてその兄弟二百二十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'ゲルシヨンの子孫の中よりはヨエルを長としてその兄弟百三十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'エリザバンの子孫の中よりはシマヤを長としてその兄弟二百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'ヘブロンの子孫の中よりはエリエルを長としてその兄弟八十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'ウジエルの子孫の中よりはアミナダブを長としてその兄弟百十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'ダビデ祭司ザドクとアビヤタルおよびレビ人ウリエル、アサヤ、ヨエル、シマヤ、エリエル、アミナダブを召し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'これに言けるは汝らはレビ人の宗家の長たり汝らと汝らの兄弟共に身を潔めイスラエルの神ヱホバの契約の櫃を我が其の爲に備へたる處に舁のぼれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, '前には之をかきしもの汝らにあらざりしに縁て我らの神ヱホバわれらを撃たまへり是は我らそのさだめにしたがひて之に求めざりしが故なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, '是において祭司等とレビ人等イスラエルの神ヱホバの契約の櫃を舁のぼらんと身を潔め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'レビの子孫たる人々すなはちモーセがヱホバの言にしたがひて命じたるごとく神の契約の櫃をその貫ける枉によりて肩に負り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'ダビデまたレビ人の長等に告げその兄弟等を選びて謳歌者となし瑟と琴と鐃鈸などの樂器をもちて打はやして歓喜の聲を擧しめよと言たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'レビ人すなはちヨエルの子ヘマンとその兄弟ベレキヤの子アサフおよびメラリの子孫たる彼らの兄弟クシャヤの子エタンを選べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'また之に次るその兄弟等これと偕にあり即ちゼカリヤ、ベン、ヤジエル、セミラモテ、ヱイエル、ウンニ、エリアブ、ベナヤ、マアセヤ、マツタテヤ、エリペレホ、ミクネヤおよび門を守る者なるオベデエドムとヱイエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, '謳歌者ヘマン、アサフおよびエタンは銅の鐃鈸をもて打はやす者となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'ゼカリヤ、アジエル、セミラモテ、ヱイエル、ウンニ、エリアブ、マアセヤ、ベナヤは瑟をもて細き音を出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'マツタテヤ、エリペレテ、ミクネヤ、オベデエドム、ヱイエル、アザジヤは琴をもて太き音を出して拍子をとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'ケナニヤはレビ人の長にして負舁事に通じをるによりて負舁事を指揮せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'またベレキヤとエルカナは契約の櫃の門を守り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, '祭司シバニヤ、ヨシヤパテ、ネタネル、アマサイ、ゼカリヤ、ベナヤ、ヱリエゼル等は神の契約の櫃の前に進みて喇叭を吹きオベデエドムとヱヒアは契約の櫃の門を守れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, '斯ダビデとイスラエルの長老および千人の長等は往てオベデエドムの家よりヱホバの契約の櫃を歓び勇みて舁のぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, '神ヱホバの契約の櫃を舁ところのレビ人を助けたまひければ牡牛七匹牡羊七匹を献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'ダビデは細布の衣をまとへり又契約の櫃を舁ところの一切のレビ人と謳歌者および負舁事を主どれるケナニヤも然りダビデはまた白布のエポデを着居たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, '斯てイスラエルみな聲を擧げ角を吹ならし喇叭と鐃鈸と瑟と琴とをもて打はやしてヱホバの契約の櫃を舁のぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'ヱホバの契約の櫃ダビデの邑にいりし時サウルの女ミカル窻より窺ひてダビデ王の舞躍るを見その心にこれを藐視めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, '人々神の契約の櫃を舁いりて之をダビデがその爲に張たる幕屋の中に置ゑ而して燔祭と酬恩祭を神の前に献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'ダビデ燔祭と酬恩祭を献ぐることを終しかばヱホバの名をもて民を祝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'イスラエルの衆庶に男にも女にも都てパン一箇肉一片乾葡萄一塊を分ち與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'ダビデまたレビ人を立てヱホバの契約の櫃の前にて職事をなさしめ又イスラエルの神ヱホバを崇め讃めかつ頌へしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, '伶長はアサフその次はゼカリヤ、ヱイエル、セミラモテ、ヱヒエル、マツタテヤ、エリアブ、ベナヤ、オベデエドム、ヱイエルこれは瑟と琴とを弾じアサフは鐃鈸を打鳴し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'また祭司ベナヤとヤハジエルは喇叭をとりて恒に神の契約の櫃の前に侍れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, '當日ダビデ始めてアサフとその兄弟等を立てヱホバを頌へしめたり其言に云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'ヱホバに感謝しその名をよびその作たまへることをもろもろの民輩の中にしらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'ヱホバにむかひてうたへヱホバを讃うたへそのもろもろの奇しき跡をかたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'そのきよき名をほこれヱホバをたづぬるものの心はよろこぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'ヱホバとその能力とをたづねよ恒にその聖顔をたづねよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'その僕イスラエルの裔よヤコダの子輩よそのえらびたまひし所のものよそのなしたまへる奇しき跡とその異事とその口のさばきとを心にとむれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'その僕イスラエルの裔よヤコダの子輩よそのえらびたまひし所のものよそのなしたまへる奇しき跡とその異事とその口のさばきとを心にとむれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, '彼はわれらの神ヱホバなりそのおほくの審判は全地にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'なんぢらたえずその契約をこころに記よ此はよろづ代に命じたまひし聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'アブラハムとむすびたまひし契約イサクに與へたまひし誓なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, '之をかたくしヤコブのために律法となしイスラエルのためにとこしへの契約となして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, '言たまひけるは我なんぢにカナンの地をたまひてなんぢらの嗣業の分となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'この時なんぢらの數おほからず甚すくなくしてかしこにて旅人となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'この國よりかの國にゆきこの國よりほかの民にゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, '人のかれらを虐ぐるをゆるしたまはずかれらの故によりて王たちを懲しめて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '宣給くわが受膏者たちにふるるなかれわが預言者たちをそこなふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, '全地よヱホバにむかひて謳へ日ごとにその拯救をのべつたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'もろもろの國のなかにその榮光をあらはしもろもろの民のなかにその奇しきみわざを顯すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'そはヱホバはおほいなり大にほめたたふべきものなりまたもろもろの神にまさりて畏るべきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'もろもろの民のすべての神はことごとく虚しされどヱホはもろもろの天をつくりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, '尊貴と稜威とはその前にあり能とよろこびとはその聖所にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'もろもろのたみの諸族よ榮光とちからとをヱホバにあたへよヱホバにあたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'その聖名にかなふ榮光をもてヱホバにあたへ献物をたづさへて其前にきたれきよき美はしき物をもてヱホバを拝め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, '全地よその前にをののけ世界もかたくたちて動かさるることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, '天はよろこび地はたのしむべしもろもろの國のなかにいへヱホバは統治たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, '海とそのなかに盈るものとはなりどよみ田畑とその中のすべての物とはよろこぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'かくて林のもろもろの樹もまたヱホバの前によろこびうたはんヱホバ地をさばかんとて來りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'ヱホバに感謝せよそのめぐみはふかくその憐憫はかぎりなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, '汝ら言へ我らの拯救の神よ我らを救ひ我らを取り集め列邦のなかより救ひいだしたまへ我らは聖名に謝しなんぢのほむべき事をほこらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'イスラエルの神ヱホバは窮なきより窮なきまでほむべきかなすべての民はアーメンととなへてヱホバを讃稱へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'ダビデはアサフとその兄弟等をヱホバの契約の櫃の前に留めおきて契約の櫃の前に常に侍りて日々の事を執行なはせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'オベデエドムとその兄弟等は合せて六十八人またヱドトンの子なるオベデエドムおよびホサは司門たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, '祭司ザドクおよびその兄弟たる祭司等はギベオンなる崇邱においてヱホバの天幕の前に侍り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, '燔祭の壇の上にて朝夕斷ず燔祭をヱホバに献げ且ヱホバがイスラエルに命じたまひし律法に記されたる諸の事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'またヘマン、ヱドトンおよびその餘の選ばれて名を記されたる者等彼らとともにありてヱホバの恩寵の世々限なきを讃まつれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, '即ちヘマンおよびヱドトンかれらとともに居て喇叭鐃鈸など神の樂器を操て樂を奏せり又ヱドトンの子等は門を守れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'かくて民みな各々その家にかへれり又ダビデはその家族を祝せんとて還りゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'ダビデその家に住にいたりてダビデ預言者ナタンに言けるは觀よ我は香柏の家に住む然れどもヱホバの契約の櫃は幕の下にありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'ナタン、ダビデに言けるは神なんぢとともに在せば凡て汝の心にある所を爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'その夜神の言ナタンに臨みて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '往てわが僕ダビデに言へヱホバかく言ふ汝は我ために我の住べき家を建べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, '我はイスラエルを導びき上りし日より今日にいたるまで家に住しこと無して但幕屋より幕屋に移り天幕より天幕に遷れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, '我イスラエルの人々と共に歩みたる處々にて我わが民を牧養ふことを命じたるイスラエルの士師の一人にもなんぢ何故に香柏の家を我ために建ざるやと一言にても言し事ありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, '然ば汝わが僕ダビデに斯言べし萬軍のヱホバかく言ふ我なんぢを牧場より取り羊に隨がふ處より取て我民イスラエルの君長と爲し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, '汝が凡て往る處にて汝と偕にあり汝の諸の敵を汝の前より斷されり我また世の中の大なる人の名のごとき名を汝に得させん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'かつ我わが民イスラエルのために處を定めて彼らを植つけ彼らをして自己の處に住て重て動くこと無らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, '又惡人昔のごとく即ち我民イスラエルの上に士師を立たる時より已來のごとく重ねて彼らを荒すこと無るべし我汝の諸の敵を圧服ん且今我汝に告ぐヱホバまた汝のために家を建ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, '汝の日の滿汝ゆきて先祖等と偕になる時は我汝の生る汝の子を汝の後に立て且その國を堅うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, '彼わが爲に家を建ん我ながく彼の位を堅うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, '我は彼の父となり彼はわが子となるべし我は汝の先にありし者より取たるごとくに彼よりは我恩惠を取さらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, '却て我かれを永く我家に我國に居置ん彼の位は何時までも堅く立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'ナタン凡て是等の言のごとく凡てこの異象のごとくダビデに語りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'ダビデ王入てヱホバの前に坐して言けるはヱホバ神よ我は誰わが家は何なれば汝此まで我を導きたまひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, '神よ是はなほ汝の目には小き事たりヱホバ神よ汝はまた僕の家の遥後の事を語り高き者のごとくに我を見俲たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, '僕の名譽についてはダビデこの上何をか汝に望むべけん汝は僕を知たまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'ヱホバよ汝は僕のため又なんぢの心に循ひて此もろもろの大なる事を爲し此すべての大なる事を示たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'ヱホバよ我らが凡て耳に聞る所に依ば汝のごとき者は無くまた汝の外に神は無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, '地の何の國か汝の民イスラエルに如ん是は在昔神の往て贖ひて己の民となして大なる畏るべき事を行なひて名を得たまひし者なり汝はそのエジプトより贖ひいだせし汝の民の前より國々の人を逐はらひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, '而して汝は汝の民イスラエルを永く汝の民となしたまふヱホバよ汝は彼らの神となりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, '然ばヱホバよ汝が僕とその家につきて宣まひし言を永く堅うして汝の言し如く爲たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, '願くは汝の名の堅く立ち永久に崇められて萬軍のヱホバ、イスラエルの神はイスラエルに神たりと曰れんことを願くは僕ダビデの家の汝の前に堅く立んことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, '我神よ汝は僕の耳に示して之が爲に家を建んと宣へり是によりて僕なんぢの前に祈る道を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'ヱホバよ汝は即ち神にましまし此恩典を僕に傳たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, '願くは今僕の家を祝福て汝の前に永く在しめたまへ其はヱホバよ汝の祝福たまへる者は永く祝福を蒙ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, '此後ダビデ、ベリシテ人を撃てこれを服し又ペリシテ人の手よりガテとその郷里を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, '彼またモアダを撃ければモアブ人はダビデの臣となりて貢を納たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'ダビデまたハマテの邊にてゾバの王ハダレゼルを撃り是は彼がユフラテ河の邊にてその權勢を振はんとて往る時なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, '而してダビデ彼より車千輛騎兵七千歩兵二萬を取りダビデまた一百の車の馬を存してその餘の車馬は皆その足の筋を切り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'その時ダマスコのスリア人ゾバの王ハダレゼルを援けんとて來りければダビデそのスリア人二萬二千を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, '而してダビデ、ダマスコのスリアに鎮臺を置ぬスリア人は貢を納てダビデの臣となれりヱホバ、ダビデを凡てその往く處にて助たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'ダビデ、ハダレゼルの臣僕等の持る金の楯を奪ひて之をヱルサレムに持きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'またハダレゼルの邑テブハテとクンより甚だ衆多の銅を取きたれりソロモンこれを用て銅の海と柱と銅の器具を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, '時にハマテの王トイ、ダビデがゾバの王ハダレゼルの總の軍勢を撃破りしを聞て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'その子ハドラムをダビデ王に遣し安否を問ひかつこれを賀せしむ其はハダレゼル曾てトイと戰闘をなしたるにダビデ、ハダレゼルと戰ひて之を撃やぶりたればなりハドラム金銀および銅の種々の器を携へきたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'ダビデ王そのエドム、モアブ、アンモンの子孫ペリシテ人アマレクなどの諸の國民の中より取きたりし金銀とともに是等をもヱホバに奉納たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'ゼルヤの子アビシヤイ鹽谷にてエドム人一萬八千を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, '斯てダビデ、エドムに鎮臺を置エドム人は皆ダビデの臣となりぬヱホバかくダビデを凡その往處にて助けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'ダビデはイスラエルの全地を治めてその諸の民に公平と正義を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'ゼルヤの子ヨアブは軍旅の長アヒルデの子ヨシヤパテは史官');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'アヒトブの子ザドクとアビヤタルの子アビメレクは祭司シヤウシヤは書記官');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'ヱホヤダの子ベナヤはケレテ人とペレテ人の長ダビデの子等は王の座側に侍る大臣なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, '此後アンモンの子孫の王ナハシ死ければその子これに代りて王となりたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'ダビデ言けるは我ナハシの子ヌンをねんごろに遇らはんかれが父われをねんごろにあしらひたればなりとダビデすなはち彼をその父の故によりて慰めんとて使者を遣はせりダビデの臣僕等アンモンの子孫の地に往きハヌンに詣りてこれを慰めけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'アンモンの子孫の牧伯等ハヌンに言けるはダビデ慰籍者を汝につかはしたるに因て彼なんぢの父を尊ぶと汝の目に見ゆるや彼の臣僕等は此國を窺ひ探りて滅ぼさんとて來れるならずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, '是においてハヌン、ダビデの臣僕等を執へてその鬚を剃おとしその衣服を中より斷て腎までにして之を歸したりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, '或人きたりて此人々の爲られし事をダビデに告ければダビデ人をつかはして之を迎へしめたりその人々おほいに愧たればなり即ち王いひけるは汝ら鬚の長るまでヱリコに止まりて然る後かへるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'アンモンの子孫自己のダビデに惡まるる樣になれるを見しかばハヌンおよびアンモンの子孫すなはち銀一千タラントをおくりてメソポタミヤとスリアマアカおよびゾバより戰車と騎兵とを雇ひいれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, '即ち戰車三萬二千乗にマアカの王とその兵士を雇ひければ彼ら來りてメデバの前に陣を張り是においてアンモンの子孫その邑々より寄あつまりて戰はんとて來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'ダビデ聞てヨアブと勇士の惣軍を遣しけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'アンモンの子孫は出て邑の門の前に戰爭の陣列をなせり又援助に來れる王等は別に野に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, '時にヨアブ前後より敵の攻寄るを見てイスラエルの倔強の兵士の中を抽擢て之をしてスリア人にむかひて陣列しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'その餘の民をばその兄弟アビシヤイの手に交してアンモンの子孫にむかひて陣列しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, '而して言けるはスリア人もし我に手強からば汝我を助けよアンモンの子孫もし汝に手強からば我なんぢを助けん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, '汝勇しくなれよ我儕の民のためと我らの神の諸邑のために我ら勇しく爲ん願くはヱホバその目に善と見ゆる所をなしたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'ヨアブ己に從へる民とともに進みよりてスリア人を攻撃けるにスリア人かれの前より潰奔れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'アンモンの子孫はスリア人の潰奔れるを見て自己等もまたその兄弟アビシヤイの前より逃奔りて城邑にいりぬ是においてヨアブはヱルサレムに歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'スリア人はそのイスラエルに撃やぶられたるを見て使者を遣はして河の彼旁なるスリア人を將ゐ出せりハダレゼルの軍旅の長シヨバクこれを率ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'その事ダビデに聞えければ彼イスラエルを悉く集めヨルダンを渡りて彼らの所に來り之にむかひて戰爭の陣列を立たりダビデかく彼らにむかひて戰爭の陣列を立たれば彼らこれと戰へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, '然るにスリア人イスラエルの前に潰たればダビデ、スリアの兵車の人七千歩兵四萬を殺しまた軍旅の長シヨバクを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'ハダレゼルの臣たる者等そのイスラエルに撃やぶられたるを見てダピデと和睦をなしてこれが臣となれりスリア人は此後ふたたびアンモンの子孫を助くることを爲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, '年かへりて王等の戰爭に出る時におよびてヨアブ軍勢を率ゐて出でアンモン人の地を打荒し往てラバを攻圍りされどダビデはヱルサレムに止まりたりヨアブつひにラバを撃壞りてこれを滅ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'ダビデ彼らの王の冠冕をその首より取はなしたりしがその金の重を量り見るに一タラントありまたその中に寶石を嵌たるありき之をダビデの首に冠らせたり彼また甚だ衆多の掠取物をその邑より取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, '而して彼またその中の民を曳いだし鋸と鐵の打車と斧とをもてこれを斬りダビデ、アンモンの子孫の一切の邑に斯く爲り而してダビデとその民はみなヱルサレムに歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'この後ゲゼルにおいてペリシテ人と戰爭おこりたりしがその時にホシヤ人シベカイ巨人の子孫の一人なるシバイを殺せり彼等つひに攻伏られき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, '復ペリシテ人と戰爭ありしがヤイルの子エルハナン、ガテのゴリアテの兄弟ラミを殺せりラミの槍の柄は機の滕の如くなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'またガテに戰爭ありしが其處に一人の身長き人ありその手の指と足の趾は六宛にして合せて二十四あり彼も巨人の生る者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, '彼イスラエルを挑みしかばダビデの兄弟シメアの子ヨナタンこれを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, '是等はガテにて巨人の生る者なりしがダビデの手とその臣僕の手に斃れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, '茲にサタン起りてイスラエルに敵しダビデを感動してイスラエルを核數しめんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'ダビデすなはちヨアブと民の牧伯等に言けるは汝等ゆきてベエルシバよりダンまでのイスラエル人を數へその數をとりきたりて我に知せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'ヨアブ答へけるは幾何あるとも願くはヱホバその民を百倍に増たまへ然ながら王わが主よ是はみな我主の僕ならずや然に何とて我主この事を爲んと要たまふや何ぞイスラエルをして之によりて罪を獲せしむべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'されど王つひにヨアブに言勝たればヨアブすなはち出ゆきイスラエルを徧く行めぐりてヱルサレムに還れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, '而してヨアブ民の總數をダビデに告たり即ちイスラエルの中には劍を帶る者一百十萬人ありユダの中には劍を帶る者四十七萬人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, '但しレビとベニヤミンとはその中に數へざりき其はヨアブ王の言を惡みたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'この事神の目に惡かりければイスラエルを撃なやましたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'ダビデ是において神に申しけるは我この事をなして大に罪を獲たり然ども今ねがはくは僕の罪を除きたまへ我はなはだ愚なる事をなせりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, '時にヱホバ、ダビデの先見者ガデにきて言たまひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '往てダビデに告て言へヱホバかく言ふ我なんぢに三のものを示す汝その一を撰べ我それを汝に爲んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'ガデすなはちダビデの許に至り之に言けるはヱホバかく言たまふ汝擇べよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, '即ち三年の饑饉か又は汝三月の間汝の敵の前に敗れて汝の仇の劍に追しかれんか又は三日の間ヱホバの劍すなはち疫病この國にありてヱホバの使者イスラエルの四方の境の中にて撃滅ぼすことをせんか我が如何なる答を我を遣せし者に爲べきかを汝決めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'ダビデ、ガデに言けるは我おほいに苦む請ふ我はヱホバの手に陷らん其憐憫甚だおほいなればなり人の手には陷らじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, '是においてヱホバ、イスラエルに疫病を降したまひければイスラエルの人七萬人斃れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, '神また使者をヱルサレムに遣してこれを滅ぼさんとしたまひしが其これを滅ぼすにあたりてヱホバ視てこの禍害をなせしを悔い其ほろぼす使者に言たまひけるは足り今なんぢの手を住めよと時にヱホバの使者はヱブス人オルナンの打場の傍に立をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'ダビデ目をあげて視るにヱホバの使者地と天の間に立て抜身の劍を手にとりてヱルサレムの方にこれを伸をりければダビデと長老等麻布を衣て俯伏り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, '而してダビデ神に申しけるは民を數へよと命ぜし者は我ならずや罪を犯し惡き事をなしたる者は我なり然れども是等の羊は何をなせしや我神ヱホバよ請ふ汝の手を我とわが父の家に加へたまへ惟汝の民に加へて之を疚めたまふ勿れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, '時にヱホバの使者ガデに命じ汝ダビデに告てダビデをして上りゆきてヱブス人オルナンの打場にてヱホバのために一箇の壇を築しめよと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, '是においてダビデはガデがヱホバの名をもて告たる言にしたがひて上りゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'オルナンは麥を打ゐけるが回顧て天の使の居るを視その四人の子等とともに匿れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'やがてダビデはオルナンの方に來りけるがオルナン望てダビデを見すなはち打場より出ゆきて面を地につけてダビデを拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'ダビデ、オルナンに言けるは此打場の處を我に與へよ我そこにてヱホバに一箇の壇を築かん汝その十分の値をとりて之を我にあたへ災害の民におよぶことを止めしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'オルナン、ダビデに言けるは請ふ之を取り王わが主の目に善と觀るところを爲たまへ我なんぢに献げて牛を燔祭の料とし打禾車を柴薪とし麥を素祭とせん我みなこれを奉呈ると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'ダビデ王オルナンに言けるは然るべからず我かならず十分の値をはらひて之を買ん我は汝の物を取てヱホバに奉まつらじ又費なしに燔祭を献ぐることをせじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'ダビデすなはち其處のために金六百シケルを衡りてオルナンに與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, '而してダビデ其處にてヱホバに一箇の祭壇を築き燔祭と酬恩祭を献げてヱホバを龥けるに天より燔祭の壇の上に火を降して之に應へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'ヱホバすなはちその使者に命じたまひければ彼その劍を鞘に蔵めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'その時ダビデはヱホバがヱブス人オルナンの打場において己に應へたまふを見たれば其處にて犠牲を献ぐることを爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'モーセが荒野にて造りたるヱホバの幕屋と燔祭の壇とは當時ギベオンの崇邱にありけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'ダビデはその前に進みゆきて神に求むることを得せざりき是は彼ヱホバの使者の劍のために懼れたるに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'ダビデ言けるはヱホバ神の室は此なりイスラエルの燔祭の壇は此なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'ダビデすなはち命じてイスラエルの地に居る異邦人を集めしめ又神の室を建るに用ふる石を琢ために石工を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'ダビデまた門の扉の釘および鎹に用ふる鐵を夥しく備へたり又銅を數しれぬほどに夥しく備へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'また香柏を備ふること數しれず是はシドン人およびツロの者夥多しく香柏をダビデの所に運びきたりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'ダビデ言けるは我子ソロモンは少くして弱し又ヱホバのために建る室は極めて高大にして萬國に名を得榮を得る者たらざる可らず今我其がために準備をなさんとダビデその死る前に大に之が準備をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, '而して彼その子ソロモンを召てイスラエルの神ヱホバのために家を建ることを之に命ぜり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, '即ちダビデ、ソロモンに言けるは我子よ我は我神ヱホバの名のために家を建る志ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, '然るにヱホバの言われに臨みて言り汝は多くの血を流し大なる戰爭を爲したり汝我前にて多の血を地に流したれば我名の爲に家を建べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, '視よ男子汝に生れん是は平安の人なるべし我これに平安を賜ひてその四周の諸の敵に煩はさるること無らしめん故に彼の名はソロモン(平安)といふべし彼の世に我平安と靜謐をイスラエルに賜はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, '彼わが名のために家を建ん彼はわが子となり我は彼の父とならん我かれの國の祚を固うして永くイスラエルの上に立しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, '然ば我子よ願くはヱホバ汝とともに在し汝を盛ならしめ汝の神ヱホバの室を建させて其なんぢにつきて言たる如くしたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, '惟ねがはくはヱホバ汝に智慧と穎悟を賜ひ汝をイスラエルの上に立て汝の神ヱホバの律法を汝に守らせたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, '汝もしヱホバがイスラエルにつきてモーセに命じたまひし法度と例規を謹みて行はば汝旺盛になるべし心を強くしかつ勇め懼るる勿れ慄くなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, '視よ我患難の中にてヱホバの室のために金十萬タラント銀百萬タラントを備へまた銅と鐵とを數しれぬほど夥多しく備へたり又材木と石をも備へたり汝また之に加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'かつまた工人夥多しく汝の手にあり即ち石や木を琢刻む者および諸の工作を爲すところの工匠など都てあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, '夫金銀銅鐵は數限りなし汝起て爲せ願くはヱホバ汝とともに在せと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'ダビデまたイスラエルの一切の牧伯等にその子ソロモンを助くることを命じて云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '汝らの神ヱホバなんぢらと偕に在すならずや四方において泰平を汝らに賜へるならずや即ちこの地の民を我手に付したまひてこの地はヱホバの前とその民の前に服せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, '然ば汝ら心をこめ精神をこめて汝らの神ヱホバを求めよ汝ら起てヱホバ神の聖所を建てヱホバの名のために建るその室にヱホバの契約の櫃と神の聖器を携さへいるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'ダビデ老てその日滿ければその子ソロモンをイスラエルの王となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'ダビデ、イスラエルの一切の牧伯および祭司とレビ人をあつめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'レビ人の三十歳以上なる者を數へたるにその人々の頭數は三萬八千');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'その中二萬四千はヱホバの室の事幹を掌どり六千は有司および裁判人たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, '四千は門を守る者たりまた四千はダビデが造れる讃美の樂器をとりてヱホバを頌ることをせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'ダビデ、レビの子孫を分ちて班列を立たり即ちゲルシヨン、コハテおよびメラリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'ゲルシヨン人たる者はラダンおよびシメイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'ラダンの子等は長エヒエルにゼタムとヨエル合せて三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'シメイの子等はシロミテ、ハジエル、ハランの三人是等はラダンの宗家の長たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'シメイの子等はヤハテ、ジナ、ヱウシ、ベリア この四人はシメイの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'ヤハデは長 ジナはその次 ヱウシ、ベリアは子多からざるが故に之をともに數へて一の宗家となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'コハテの子等はアムラム、イヅハル、ヘブロン、ウジエルの四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'アムラムの子等はアロンとモーセ、アロンはその子等とともに永く區別れてその身を潔めて至聖者となりヱホバの前に香を焚き之に事へ恒にこれが名をもて祝することを爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, '神の人モーセの子等はレビの支派の中に數へいれらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'モーセの子等はゲルシヨンおよびエリエゼル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'ゲルシヨンの子等は長はシブエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'エリエゼルの子等は長はレハビヤ、エリエゼルは此外に男子あらざりき但しレハビヤの子等は甚だ多かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'イヅハルの子等は長はシロミテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'ヘブロンの子等は長子はヱリヤ その次はアマリヤ その三はヤハジエル その四はヱカメアム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'ウジエルの子等は長子はミカ 次はヱシヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'メラリの子等はマヘリおよびムシ、マヘリの子等はエレアザルおよびキシ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'エレアザルは男子なくして死り惟女子ありし而已その女子等はキシの子たるその兄弟等これを娶れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'ムシの子等はマヘリ、エデル、ヱレモテの三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'レビの子孫をその宗家に循ひて言ば是のごとし是皆かの頭數を數へられその名を録されてヱホバの家の役事をなせる二十歳以上の者の宗家の長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'ダビデ言けらくイスラエルの神ヱホバその民を安んじて永くヱルサレムに住たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'レビ人はまた重ねて幕屋およびその奉事の器具を舁ことあらずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'ダビデの最後の詞にしたがひてレビ人は二十歳以上よりして數へられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, '彼らの職はアロンの子孫等の手に屬して神の家の役事を爲し庭と諸の室の用を爲し一切の聖物を潔むるなど凡て神の家の役事を勤むるの事なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'また供前のパン素祭の麥粉酵いれぬ菓子鍋にて製る者燒て製る者などを掌どりまた凡て容積と長短を量度ることを掌どり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'また朝ごとに立てヱホバを頌へ讃ることを掌どれり夕もまた然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, '又安息日と朔日と節會においてヱホバに諸の燔祭を献げ其命ぜられたる所に循ひて數のごとくに斷ずこれをヱホバの前にたてまつる事を掌どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, '是のごとく彼らは集會の幕屋の職守と聖所の職守とアロンの子孫たるその兄弟等の職守とを守りてヱホバの家の役事をおこなふ可りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'アロンの子孫の班列は左のごとしアロンの子等はナダブ、アビウ、エレアザル、イタマル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'ナダブとアビウはその父に先だちて死て子なかりければエレアザルとイタマル祭司となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'ダビデ、エレアザルの子孫ザドクおよびイタマルの子孫アヒメレクとともに彼らを分ちて各その職と務に任じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'エレアザルの子孫の中にはイタマルの子孫の中よりも長たる人多かりき是をもてその分かれし班列はエレアザルの子孫たる宗家の長には十六ありイタマルの子孫たる宗家の長には八あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, '斯彼らは籤によりて分たる彼と此と相等し其は聖所の督者および神の督者はエレアザルの子孫の中よりも出でイタマルの子孫の中よりも出ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'レビ人ネタネルの子シマヤといふ書記王と牧伯等と祭司ザドクとアビヤタルの子アヒメレクと祭司およびレビ人の宗家の長の前にて之を書しるせり即ちエレアザルのために宗家一を取ばまたイタマルのために宗家一を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, '第一の籤はヨアリブに當り第二はヱダヤに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, '第三はハリムに當り第四はセオリムに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, '第五はマルキヤに當り第六はミヤミンに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, '第七はハツコヅに當り第八はアビアに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, '第九はヱシユアに當り第十はシカニヤに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, '第十一はヱリアシブに當り第十二はヤキンに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, '第十三はホツバに當り第十四はエシバブに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, '第十五はビルガに當り第十六はインメルに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, '第十七はヘジルに當り第十八はハビセツに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, '第十九はベタヒヤに當り第二十はエゼキエルに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, '第二十一はヤキンに當り第二十一はガムルに當り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, '第二十三はデラヤに當り第二十四はマアジアに當れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, '是その職務の順序なり彼らは之にしたがひてヱホバの家にいり其先祖アロンより傳はりし例規によりて勤むべかりしなり即ちイスラエルの神ヱホバの彼に命じたまひしごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'その餘のレビの子孫は左の如しアムラムの子等の中にてはシユバエル、シユバエルの子等の中にてはヱデヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'レハビヤについてはレハビヤの子等の中にては長子イツシア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'イヅハリ人の中にてはシロミテ、シロミテの子等の中にてはヤハテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'ヘブロンの子等の中にては長子ヱリヤ二子アマリヤ三子ヤハジエル四子ヱカメアム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'ウジエルの子等の中にてはミカ、ミカの子等の中にてはシヤミル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'ミカの兄弟をイツシアといふイツシアの子等の中にてはゼカリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'メラリの子等はマヘリおよびムシ、ヤジアの子等はベノ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'メラリの子孫のヤジアより出たる者はベノ、シヨハム、ザツクル、イブリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'マヘリよりエレアザル出たりエレアザルは子等なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'キシについてはキシの子はヱラメル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'ムシの子等はマヘリ、エデル、ヱリモテ是等はレビの子孫にしてその宗家にしたがひて言る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, '是らの者もまたダビデ王とザドクとアヒメレクと祭司およびレビ人の宗家の長たる者等の前にてアロンの子孫たるその兄弟等のごとく籤を掣り兄の宗家も弟の宗家も異なること無りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'ダビデと軍旅の牧伯等またアサフ、ヘマンおよびヱドトンの子等を選びて職に任じ之をして琴と瑟と鐃鈸を執て預言せしむその職によれば伶人の數左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'アサフの子等はザツクル、ヨセフ、ネタニア、アサレラ 皆アサフの子等にしてアサフの手に屬すアサフは王の手につきて預言す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'ヱドトンについてはヱドトンの子等はゲダリア、ゼリ、ヱサヤ、ハシヤビヤ、マツタテヤの六人 皆琴を操てその父ヱドトンの手に屬すヱドトンはヱホバを讃めかつ頌へて預言す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'ヘマンについてはヘマンの子等たる者はブツキヤ、マツタニヤ、ウジエル、シブエル、ヱレモテ、ハナニヤ、ハナニ、エリアタ、ギダルテ、ロマムテエゼル、ヨシベカシヤ、マロテ、ホテル、マハジオテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, '是みな神の言をつたふる王の先見者ヘマンの子等にして角を擧ぐ 神ヘマンに男子十四人女子三人を賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, '是等の者は皆その父の手に屬しヱホバの家において歌を謡ひ鐃鈸と瑟と琴をもて神の家の奉事をなせり アサフ、ヱドトンおよびヘマンは王の手につけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, '彼等およびヱホバに歌を謡ふことを習へるその兄弟等即ち巧なる者の數は二百八十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, '彼ら大も小も巧なる者も習ふ者も皆ともにその職務の籤を掣けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, '第一の籤はアサフの家のヨセフに當り第二はゲダリアに當れり彼もその兄弟等および子等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, '第三はザツクルに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, '第四はイヅリに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, '第五はネタニヤに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, '第六はブツキアに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, '第七はアサレラに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, '第八はヱサヤに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, '第九はマツタニヤに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, '第十はシメイに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, '第十一はアザリエルに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, '第十二はハシヤビアに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, '第十三はシユバエルに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, '第十四はマツタテヤに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, '第十五はヱレモテに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, '第十六はハナニヤに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, '第十七はヨシベカシヤに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, '第十八はでハナニに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, '第十九はマロテに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, '第二十はエリアタに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, '第二十一はホテルに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, '第二十二はギダルテに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, '第二十三はマハジオテに富れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, '第二十四はロマムテエゼルに當れりその子等とその兄弟等十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, '門を守る者の班列は左のごとしコラ人の中にてはアサフの子コレの子なるメシレミヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'メシレミヤの子等は長子はゼカリヤその次はヱデアエルその三はゼバデヤその四はヤテニエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'その五はエラムその六はヨハナンその七はエリヨエナイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'またオベデエドムの子等は長子はシマヤその次はヨザバデその三はヨアその四はサカルその五はネタネル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'その六はアシミエルその七はイツサカルその八はピウレタイ是は神かれを祝福たまひしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'また彼の子シマヤにも數人の子生れたりしがその子等は大勇士にしてその父の家の主たる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'すなはちシマヤの子等はオテニ、レバエル、オベデ、エルザバデ、エルザバデの兄弟エリウとセマキヤは力ある人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, '是みなオベデエドムの孫子なり彼らとその子等および其兄弟等は合せて六十二人皆力ある者にしてその職に堪ふ是みなオベデエドムに屬する者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'メシレミヤも子等と兄弟等合せて十八人あり皆力ある者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'メラリの子孫ホサもまた子等ありき其長はシムリ是は長子ならざりしかどもその父これを長となせしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'その次はヒルキヤその三はデバリヤその四はゼカリヤ、ホサの子等と兄弟等は合せて十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, '門を守るところの班列此長等の中より出でみなその兄弟と等く勤務をなしてヱホバの家に仕ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, '彼ら門々を分つために小も大もともにその宗家に循ひて籤を掣たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, '東の方の籤はシレミヤに當れり又その子ゼカリヤのために籤を掣けるに北の方の籤これに當れりゼカリヤは智慧ある議士なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'オベデエドムは南の方の籤に當りその子等は倉の籤に當れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'シユパムおよびホサは西の方の籤にあたり坂の大路にあるシヤレケテの門の傍に居り守者はみな相對ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, '東の方にはレビ人六人北の方には日々に四人南の方にも日々に四人倉のかたはらには二人に二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, '西の方バルバルにおいては大路に四人バルバルに二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, '門を守る者の班列は是のごとし皆コラの子孫とメラリの子孫なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'また神の府庫および聖物の府庫を司どれる彼らの兄弟なるレビ人は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'ラダンの子孫すなはちラダンより出たるゲルシヨン人にしてゲルシヨン人ラダンの宗家の長たる者の中にてはヱヒエリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'およびヱヒエリの子等ならびにその兄弟ゼタムとヨエル是らはヱホバの家の府庫を司どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'アムラミ人イヅハリ人ヘブロン人ウジエリ人の中においては左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'モーセの子ゲルシヨムの子なるシブエルは府庫の宰たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'その兄弟にしてエリエゼルより出たる者は即ちエリエゼルの子レハビヤその子ヱサヤその子ヨラムその子ジクリその子シロミテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, '此シロミテとその兄弟等はすべての聖物の府庫を掌どれりその聖物はすなはちダビデ王宗家の長千人の長百人の長軍旅の長等などが奉納たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, '即ち戰爭において獲たる物および掠取物を奉納てヱホバの家の修繕に供へたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, '凡て先見者サムエル、キシの子サウル、ネルの子アブネル、ゼルヤの子ヨアブ等が奉献たる物および其他の奉納物は皆シロミテとその兄弟等の手の下にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'イヅハリ人の中にてはケナニヤとその子等イスラエルの外事を理め有司となり裁判人となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'ヘブロン人の中にてはハシヤビアおよびその兄弟などの勇士一千七百人ありてヨルダンの此旁すなはち西の方にてイスラエルの監督者となりヱホバの一切の事を行ひ王の用を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'ヘブロン人の中にてはその系譜と宗家とに依ばヱリヤといふ者ヘブロン人の長なりダビデの治世の四十年に彼らを尋ね求めギレアデのヤゼルにおいて彼らの中より大勇士を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'ヱリヤの兄弟たる勇士は二千七百人にして皆宗家の長たりダビデ王かれらをしてルベン人ガド人およびマナセの半支派を監督しめ神につける事と王につける事とを宰どらせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'イスラエルの子孫すなはち宗家の長千人の長百人の長およびその有司等は年の惣の月のあひだ月ごとに更り入り更り出で其班列の諸の事をつとめて王に事へたるが其數を按ふるに一班列に二萬四千人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, '先第一の班列すなはち正月の分はザブデエルの子ヤシヨベアムこれを率ゆ其班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, '彼は正月の軍團の長等の首たる者にしてペレヅの子孫なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, '二月の班列はアホア人ドダイその班列の者とともにこれを率ゆミクロテといふ宰あり其班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, '三月の軍團を統る第三の將は祭司の長ヱホヤダの子ベナヤその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'このベナヤはかの三十人の中の勇士にして三十人の上にたてり彼の子アミザバデその班列にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, '四月の分を統る第四の將はヨアブの弟アサヘルにしてその子ゼバデヤこれに次り其班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, '五月の分を統る第五の將はイズラヒ人シヤンモテその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, '六月の分を統る第六の將はテコア人イツケシの子イラその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, '七月の分を統る第七の將はエフライムの子孫たるペロニ人ヘレヅその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, '八月の分を統る第八の將はゼラの子孫たるホシヤ人シベカイその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, '九月の分をすぶる第九の將はベニヤミンの子孫たるアナトテ人アビエゼルその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, '十月の分をすぶる第十の將はゼラの子孫たるネトパ人マハライその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, '十一月の分をすぶる第十一の將はエフライムの子孫たるピラトン人ベナヤその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, '十二月の分を統る第十二の將はオテニエルの子孫たるネトパ人ヘルダイその班列は二萬四千人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'イスラエルの支派を治むる者は左のごとしルベン人の牧伯はヂクリの子エリエゼル、シメオンの牧伯はマアカの子シバテヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'レビ人の牧伯はケムエルの子ハシヤビヤ、アロン人の牧伯はザドク');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'ユダの牧伯はダビデの兄弟エリウ、イツサカルの牧伯はミカエルの子オムリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'ゼブルンの牧伯はオバデヤの子イシマヤ、ナフタリの牧伯はアズリエルの子ヱレモテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'エフライムの子孫の牧伯はアザジヤの子ホセア、マナセの半支派の牧伯はペダヤの子ヨエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'ギレアデなるマナセのご半支派の牧伯はゼカリヤの子イド、ペニヤミンの牧伯はアブネルの子ヤシエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'ダンの牧伯はヱロハムの子アザリエル、イスラエルの支派の牧伯等は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, '二十歳以下なる者はダビデこれを數へざりき其はヱホバかつてイスラエルを増て天空の星のごとくにせんと言たまひしことあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'ゼルヤの子ヨアブ數ふることを始めたりしがこれを爲をへざりきそのかぞふることによりて震怒イスラエルにおよべりその數はまたダビデ王の記録の籍に載ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'アデエルの子アズマウテは王の府庫を掌どりウジヤの子ヨナタンは田野邑々村々城などにある府庫を掌どり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'ケルブの子エズリは地を耕す農業の人を掌どり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'ラマテ人シメイは葡萄園を掌どりシフミ人ザブデはその葡萄園より取る葡萄酒の蔵を掌どり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'ゲデラ人バアルハナンは平野なる橄欖樹と桑樹を掌どりヨアシは油の蔵を掌どり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'シヤロン人シテナイはシヤロンにて牧ふ牛の群を掌どりアデライの子シヤバテは谷々にある牛の群を掌どり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'イシマエル人オビルは駱駝を掌どりメロノテ人ヱデヤは驢馬を掌どり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'ハガリ人ヤジズは羊の群を掌どれり是みなダビデ王の所有を掌どれる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'またダビデの叔父ヨナタンは議官たり彼は智慧あり學識ある者なり又ハクモニの子ヱヒエルは王の子等の補佐たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'アヒトペルは王の議官たりアルキ人ホシヤイは王の伴侶たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'アヒトペルに次ぐ者はベナヤの子ヱホヤダおよびアビヤタル王の軍旅の長はヨアブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, '茲にダビデ、イスラエルの一切の長支派の長王に事ふる班列の長千人の長百人の長王とその子等の所有及び家畜を掌どる者閹官有力者諸勇士などを盡くヱルサレムに召集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, '而してダビデ王その足にて起て言けるは我兄弟等我民よ我に聽け我はヱホバの契約の櫃のため我らの神の足臺のために安居の家を建んとの志ありて已にこれを建る準備をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, '然るに神我に言たまへり汝は我名のために家を建べからず汝は軍人にして許多の血を流したればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, '然りと雖もイスラエルの神ヱホバ我父の全家の中より我を選びて永くイスラエルに王たらしめたまふ即ちユダを選びて長となしユダの全家の中より我父の家を選び我父の子等の中にて我を悦びイスラエルの王とならしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, '而してヱホバ我に衆多の子をたまひて其わが諸の子等の中より我子ソロモンを選び之をヱホバの國の位に坐せしめてイスラエルを治めしめんとしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'ヱホバまた我に言たまひけるは汝の子ソロモンはわが家および我庭を作らん我かれを選びて吾子となせり我かれの父となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, '彼もし今日のごとく我誡命と律法を堅く守り行はば我その國を永く堅うせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, '然ば今ヱホバの會衆たるイスラエルの全家の目の前および我らの神の聞しめす所にて汝らに勸む汝らその神ヱホバの一切の誡命を守りかつ之を追もとむべし然せば汝等この美地を保ちてこれを汝らの後の子孫に永く傳ふることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, '我子ソロモンよ汝の父の神を知り完全心をもて喜び勇んで之に事へよヱホバは一切の心を探り一切の思想を暁りたまふなり汝もし之を求めなば之に遇ん然ど汝もし之を棄なば永く汝を棄たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, '然ば汝謹めよヱホバ汝を選びて聖所とすべき家を建させんと爲たまへば心を強くしてこれを爲べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, '而してダビデは殿の廊およびその家その府庫その上の室その内の室贖罪所の室などの式樣をその子ソロモンに授け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'また其心に思ひはかれる一切の物すなはちヱホバの家の庭四周の諸の室神の家の府庫聖物の府庫などの式樣を授け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'また祭司およびレビ人の班列とヱホバの家の諸の奉事の工とヱホバの家の諸の奉事の器皿とにつきて諭すところあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'また諸の奉事に用ふる金の器皿を作る金の重量を定め又諸の奉事の器に用ふる諸の銀の器皿の銀の重量を定む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, '即ち金の燈臺とその金の燈盞の重量を宣て一切の燈臺とその燈盞の重量を定め又銀の燈臺につきても各々の燈臺の用法にしたがひて燈臺とその燈盞の重量を定め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'また供前のパンの案につきてはその各の案のために金の重量を定め又銀の案のためにも銀を定め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, '又肉鉤盂杓のために用ふる純金の重量を定め金の大斝につきてもまた各々の大斝のために重量を定め銀の一切の大斝のためにも重量を定め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'また香壇のために用ふる精金の重量を定めかつ車なるケルビムの式樣の金を定む此ケルビムはその翼を展てヱホバの契約の櫃を覆ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '而してダビデ言けらく此工事の式樣は皆ことごとくヱホバのその手を我上にくだして我を敎へて書せたまひし者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'かくてダビデその子ソロモンに言けるは汝心を強くし勇みてこれを爲せ懼るる勿れ慄くなかれヱホバ神我神汝とともに在さん彼かならず汝を離れず汝を棄ず汝をしてヱホバの家の奉事の諸の工を成終しめたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, '視よ神の家の諸の役事をなすためには祭司とレビ人の班列あり又諸の工と從事を悦こびて爲ところの諸の技巧者汝とともに在り且また牧伯等および一切の民汝の命ずるところを悉く行はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'ダビデ王また全會衆に言けるは我子ソロモンは神の惟獨選びたまへる者なるが少くして弱く此工事は大なり此殿は人のために非ずヱホバ神のためにする者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, '是をもて我力を盡して我神の家のために物を備へたり即ち金の物を作る金 銀の物の銀 銅の物の銅 鐵の物の鐵 木の物の木を備へたり又葱珩 嵌石 黑石火崗諸の寶石蝋石など夥多し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'かつまた我わが神の家を悦ぶが故に聖所のために備へたる一切の物の外にまた自己の所有なる金銀をわが神の家に献ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, '即ちオフルの金三千タラント精銀七千タラントを献げてその家々の壁を蔽ふに供ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, '金は金の物に銀は銀の物に凡て工人の手にて作るものに用ふべし誰か今日自ら進んでヱホバのためにその手に物を盈さんかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, '是において宗家の長イスラエルの支派の牧伯等千人の長百人の長および王の工事を掌どる者等誠意より献物をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'その神の家の奉事のために献げたるものは金五千タラント一萬ダリク銀一萬タラント銅一萬八千タラント鐵十萬タラント');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'また寶石ある者はゲルシヨン人ヱヒエルの手に託て之を神の家の府庫に納めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, '彼ら斯誠意よりみづから進んでヱホバに献げたれば民その献ぐるを喜べりダビデ王もまた大に喜びぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, '茲にダビデ全會衆の前にてヱホバを頌へたりダビデの曰く我らの先祖イスラエルの神ヱホバよ汝は世々限なく頌へまつるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'ヱホバよ權勢と能力と榮光と光輝と威光とは汝に屬す凡て天にある者地にある者はみな汝に屬すヱホバよ國もまた汝に屬す汝は萬有の首と崇られたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, '富と貴とは共に汝より出づ汝は萬有を主宰たまふ汝の手には權勢と能力あり汝の手は能く一切をして大たらしめ又強くならしむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, '然ば我儕の神よ我儕今なんぢに感謝し汝の尊き名を讃美す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, '但し我ら斯のごとく自ら進んで献ぐることを得たるも我は何ならんやまた我民は何ならんや萬の物は汝より出づ我らは只汝の手より受て汝に献げたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, '汝の前にありては我らは先祖等のごとく旅客たり寄寓者たり我らの世にある日は影のごとし望む所ある無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, '我らの神ヱホバよ汝の聖名のために汝に家を建んとて我らが備へたる此衆多の物は凡て汝の手より出づ亦皆なんぢの所有なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, '我神よ我また知る汝は心を鑒みたまひ又正直を悦びたまふ我は正き心をもて眞實より此一切の物を献げたり今我また此にある汝の民が眞實より献物をするを見て喜悦にたへざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, '我らの先祖アブラハム、イサク、イスラエルの神ヱホバよ汝の民をして此精神を何時までもその心の思念に保たしめその心を固く汝に歸せしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, '又わが子ソロモンに完全心を與へ汝の誡命と汝の證言と汝の法度を守らせて之をことごとく行はせ我が備をなせるその殿を建させたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'ダビデまた全會衆にむかひて汝ら今なんぢらの神ヱホバを頌へよと言ければ全會衆その先祖等の神ヱホバを頌へ俯てヱホバと王とを拝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, '而して其翌日に至りてイスラエルの一切の人のためにヱホバに犠牲を献げヱホバに燔祭を献げたり其牡牛一千牡羊一千羔羊一千またその灌祭と祭物夥多しかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'その日彼ら大に喜びてヱホバの前に食ひかつ飮み/さらに改めてダビデの子ソロモンを王となしヱホバの前にてこれに膏をそそぎて主君となし又ザドクを祭司となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'かくてソロモンはヱホバの位に坐しその父ダビデに代りて王となりその繁榮を極むイスラエルみな之に從がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'また一切の牧伯等勇士等およびダビデ王の諸の子等みなソロモン王に服事す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'ヱホバ、イスラエルの目の前にてソロモンを甚だ大ならしめ彼より前のイスラエルの王の未だ得たること有ざる王威を之に賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, '夫ヱツサイの子ダビデはイスラエルの全地を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'そのイスラエルを治めし間は四十年なり即ちヘブロンにて七年世を治めヱルサレムにて三十三年世を治めたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, '遐齡にいたり年も富も尊貴も滿足て死り其子ソロモンこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'ダビデ王が始より終まで爲たる事等は先見者サムエルの書預言者ナタンの書および先見者ガドの書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, '其中にはまた彼の政治とその能力および彼とイスラエルと國々の諸の民に臨みしところの事等を載す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'ダビデの子ソロモン堅くその國にたてりその神ヱホバこれとともに在して之を甚だ大ならしめたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, '茲にソロモン、イスラエルの一切の人々すなはち千人の長百人の長裁判人ならびにイスラエルの全地の諸の牧伯等宗家の長などに告る所あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, '而してソロモンおよび全會衆ともにギベオンなる崇邱に往りヱホバの僕モーセが荒野にて作りたる神の集會の幕屋かしこにあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'されど神の契約の櫃はダビデすでにキリアテヤリムよりこれが爲に備へたる處に携へ上れりダビデ曩にヱルサレムにて之が爲に幕屋を張まうけたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'またホルの子ウリの子なるベザレルが作りたる銅の壇彼處においてヱホバの幕屋の前にありソロモンおよび會衆これに就きて求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, '即ちソロモン彼處に上りゆき集會の幕屋の中にあるヱホバの前なる銅の壇に就き燔祭一千を其上に献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'その夜神ソロモンに顯れてこれに言たまひけるは我なんぢに何を與ふべきか求めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'ソロモン神に申しけるは汝は我父ダビデに大なる恩惠をほどこし又我をして彼に代りて王とならしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, '今ヱホバ神よ願くは我父ダビデに宣ひし事を堅うしたまへ其は汝地の塵のごとき衆多の民の上に我を王となしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, '我が此民の前に出入することを得んために今我に智慧と智識とを與へたまへ斯のごとき大なる汝の民を誰か鞫きえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, '神ソロモンに言たまひけるは此事なんぢの心にあり汝は富有をも財寶をも尊貴をも汝を惡む者の生命をも求めずまた壽長からんことをも求めず惟智慧と智識とを己のためにもとめて我が汝を王となしたる我民を鞫かんとすれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, '智慧と智識は已に汝に授かれり我また汝の前の王等の未だ得たること有ざる程の富有と財寳と尊貴とを汝に與へん汝の後の者もまた是のごときを得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, '斯てソロモンはギベオンの崇邱を去り集會の幕屋の前を去りてヱルサレムに歸りイスラエルを治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'ソロモン戰車と騎兵とを集めしに戰車一千四百輛騎兵一萬二千人ありきソロモンこれを戰車の邑々に置き又ヱルサレムにて王の所に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, '王銀と金とを石のごとくヱルサレムに多からしめまた香柏を平野の桑樹のごとく多からしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'ソロモンの有る馬は皆エジプトよりひききたれり王の商買一群一群となして之を取いだし群ごとに價金をはらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'エジプトより取いだして携へ上る戰車一輛は銀六百馬一匹は百五十なりき是のごとくヘテ人の諸の王等およびスリアの王等のためにもその手をもて取いだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, '茲にソロモン、ヱホバの名のために一の家を建てまた己の國のために一の家を建んとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'ソロモンすなはち荷を負べき者七萬人山において木や石を斫べき者八萬人是等を監督すべき者三千六百人を數へ出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'ソロモンまづツロの王ヒラムに人を遣して言しめけるは汝はわが父ダビデにその住むべき家を建る香柏をおくれり請ふ彼になせしごとく亦我にもせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, '今我わが神ヱホバの名のために一の家を建て之を聖別て彼に奉つり彼の前に馨しき香を焚き常に供前のパンを供へ燔祭を朝夕に献げまた安息日月朔ならびに我らの神ヱホバの節期などに献げんとす是はイスラエルの永く行ふべき事なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, '我建る家は大なり其は我らの神は諸の神よりも大なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, '然ながら天も諸天の天も彼を容ること能はざれば誰か彼のために家を建ることを得んや我は何人ぞや爭か彼のために家を建ることを得ん唯彼の前に香を焚くためのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, '然ば請ふ今金銀銅鐵の細工および紫赤靑の製造に精しく雕刻の術に巧なる工人一箇を我に遣り我父ダビデが備へおきたるユダとヱルサレムのわが工人とともに操作しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, '請ふ汝また香柏松木および白檀をレバノンより我におくれ我なんぢの僕等がレバノンにて木を斫ることを善するを知るなり我僕また汝の僕と共に操作べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, '是のごとくして我ために材木を多く備へしめよ其は我が建んとする家は高大を極むる者なるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, '我は木を斫る汝の僕に搗麥二萬石大麥二萬石酒二萬バテ油二萬バテを與ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, '是においてツロの王ヒラム書をソロモンにおくりて之に答へて云ふヱホバその民を愛するが故に汝をもて之が王となせりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'ヒラムまた言けるは天地の造主なるイスラエルの神ヱホバは讃べきかな彼はダビデ王に賢き子を與へて之に分別と才智とを賦け之をしてヱホバのために家を建てまた己の國のために家を建ることを得せしむ 今我わが達人ヒラムといふ才智ある工人一人を汝におくる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, '');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, '彼はダンの子孫たる婦の產る者にて其父はツロの人なるが金銀銅鐵木石の細工および紫布靑布細布赤布の織法に精しく又能く各種の雕刻を爲し奇巧を凝して諸の工をなすなり然ば彼を用ひてなんぢの工人および汝の父わが主ダビデの工人とともに操作しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, '是については我主の宣まへる小麥大麥油および酒をその僕等に遣りたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, '汝の凡て需むるごとく我らレバノンより木を斫いだしこれを筏にくみて海よりヨツバにおくるべければ汝これをヱルサレムに運びのぼりたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'ここにおいてソロモンその父ダビデが核數しごとくイスラエルの國にをる異邦人をことごとく核數みるに合せて十五萬三千六百人ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'その七萬人をもて荷を負ふ者となし八萬人をもて山にて木や石を斫る者となし三千六百人をもて民を操作かしむる監督者となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'ソロモン、ヱルサレムのモリア山にヱホバの家を建ることを始む彼處はその父ダビデにヱホバの顯はれたまひし所にて即ちヱブス人オルナンの打場の中にダピデが備へし處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, '之を建ることを始めたるはその治世の四年の二月二日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, '神の家を建るためにソロモンの置たる基は是のごとし長六十キユビト濶二十キユビト皆古の尺に循がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, '家の前の廊は家の濶にしたがひてその長二十キユビトまたその高は百二十キユビトその内は純金をもて蔽ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'またその大殿は松の木をもて張つめ美金をもて之を蔽ひその上に棕櫚と鏈索の形を施こし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'また寶石をもてその家を美しく飾るその金はパルワイムの金なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, '彼また金をもてその家その樑その閾その壁およびその戸を蔽ひ壁の上にケルビムを刻つく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'また至聖所の家を造りしがその長は家の濶にしたがひて二十キユビトその濶も二十キユビト、美金をもてこれを蔽ふその金六百タラント');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'その釘の金は重五十シケルまた上の室も金にて覆ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'また至聖所の家の内に刻鐫めたる二のケルビムを造り金をこれに覆ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'そのケルビムの翼は長二十キユビト此ケルブの一の翼は五キユビトにして家の壁に達しその他の翼も五キユビトにして彼のケルブの翼に達す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'また彼ケルブの一の翼は五キユビトにして家の壁に達しその他の翼も五キユビトにして此ケルブの翼と相接はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, '是等のケルビムの翼はその舒ひろがること二十キユビト共にその足にて立ちその面を家に向く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, '彼また靑紫赤の布および細布をもて障蔽の幕を作りケルビムをその上に繍ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'また家の前に柱二本を作るその高は三十五キユビトその頂の頭は五キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'また環飾を造り鏈索を之に繞らしてこれを柱の頂に施こし石榴一百をつくりてその鏈索の上に施こす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'この柱を拝殿の前に竪て一本を右に一本を左に置ゑ右なる者をヤキンと名け左なる者をボアズと名く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'ソロモンまた銅の壇を作れりその長二十キユビト濶二十キユビトその高十キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'また海を鋳造れり此邊より彼邊まで十キユビトにしてその周圍は圓くその高は五キユビトその周圍には三十キユビトの繩をめぐらすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'その下には牛の像ありてその周圍を繞る即ち一キユビトに十宛ありて海の周圍を繞れり此牛は二行にして海を鋳る時に鋳付たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'その海は十二の牛の上に立りその三は北にむかひ三は西にむかひ三は南にむかひ三は東にむかふ海はその上にありて牛の後はみな内にむかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'その厚は手寛その邊は百合花形にして杯の邊の如くに作れり是は三千バテを受容る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, '彼また洗盤十箇を作りて五箇を右に五箇を左に置たり是はものを洗ふ所にして燔祭の品をその中にて灌ぐ海は祭司が其身を洗ふ處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'また金の燈臺十をその例規に從ひて作り拝殿の中に五を右に五を左に置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'また案十を作りて拝殿の中に五を右に五を左に据ゆ又金の鉢一百を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, '彼また祭司の庭と大庭および庭の戸を作り銅をもてその扉を覆ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, '海は東のかた右の方に置て南に向はしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'ヒラムまた鍋と火鏟と鉢とを作れり/斯ヒラムはソロモン王のためになせる神の家の諸の工事を終たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, '即ち二の柱と毬とその二の柱の頂の頭およびその柱の頂なる頭の二の毬を包む二の網工');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'ならびに其ふたつの網工の上にほどこす石榴四百この石榴は各々の網工の上に二行づつありて柱の頂なる頭の二の毬を包む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'また臺を作り臺の上の洗盤を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'また一の海とその下なる十二の牛');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'および鍋火鏟肉叉などヱホバの家の諸の器具を達人ヒラム ソロモン王の爲に作りたり是みな磨銅なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, '王ヨルダンの窪地に於てスコテとゼレダタの間の黏土の地にて是等を鋳させたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, '是のごとくソロモン是らの諸の器皿を甚だ多く造りたればその銅の重は測られざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'ソロモン神の家の一切の器皿を造れり即ち金の壇供前のパンを載る案');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'また定規のごとく神殿の前にて火をともすべき純金の燈臺およびその燈盞');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'その花その燈盞その燈鉗是等は金の純精なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'また剪刀鉢匙火盤是等も純金なり又家の内の戸すなはち至聖所の戸および拝殿の戸の肘鈕是も金なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, '斯ソロモンがヱホバの家のために爲る一切の工事をはれり是においてソロモンその父ダビデが奉納たる物なる金銀および諸の器皿を携へいりて神の家の府庫の中に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, '茲にソロモン、ヱホバの契約の櫃をダビデの邑シオンより舁のぼらんとてイスラエルの長老者と諸の支派の長等イスラエルの子孫の宗家の長をヱルサレムに召集めければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'イスラエルの人みな七月の節筵に當りて王の所に集まり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'イスラエルの長老等みな至りレビ人契約の櫃を執あげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'その契約の櫃と集會の幕屋と幕屋にありし諸の聖器を舁のぼれり即ち祭司レビ人これを舁のぼりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, '時にソロモン王および彼の許に集まれるイスラエルの會衆契約の櫃の前にありて羊と牛を献げたりしがその數多くして書すことも數ふることも能はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'かくて祭司等ヱホバの契約の櫃をその處に舁いれたり即ち室の神殿なる至聖所の中のケルビムの翼の下に舁いりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'ケルビムは翼を契約の櫃の所の上に舒べケルビム上より契約の櫃とその杠を掩ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, '杠長かりければ杠の末は神殿の前の契約の櫃より見えたり然れども外には見えざりき其は今日まで彼處にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, '契約の櫃の内には二枚の板の外何もあらず是はイスラエルの子孫のエジプトより出たる時ヱホバが彼らと契約を結びたまへる時にモーセがホレブにて蔵めたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, '斯て祭司等は聖所より出たり此にありし祭司はみな身を潔めその班列によらずして職務をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'またレビ人の謳歌者すなはちアサフ、ヘマン、ヱドトン及び彼らの子等と兄弟等はみな細布を纒ひ鐃鈸と瑟と琴とを操て壇の東に立りまた祭司百二十人彼らとともにありて喇叭を吹り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, '喇叭を吹く者と謳歌者とは一人のごとくに聲を斉うしてヱホバを讃かつ頌へたりしが彼ら喇叭鐃鈸等の樂器をもちて聲をふりたて善かなヱホバその矜憫は世々限なしと言てヱホバを讃ける時に雲その室すなはちヱホバの室に充り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, '祭司は雲の故をもて立て奉事をなすことを得ざりきヱホバの榮光神の室に充たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, '是においてソロモン言けるはヱホバは濃き雲の中に居んと言たまひしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, '我汝のために住むべき家永久に居べき所を建たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, '而して王その面をふりむけてイスラエルの全會衆を祝せり時にイスラエルの會衆は皆立をれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, '彼いひけるはイスラエルの神ヱホバは讃べき哉ヱホバはその口をもて吾父ダビデに言ひその手をもて之を成とげたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '即ち言たまひけらく我はわが民をエジプトの地より導き出せし日より我名を置べき家を建しめんためにイスラエルの諸の支派の中より何の邑をも選みしこと無く又何人をも選みて我民イスラエルの君となせしこと無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, '只我はわが名を置くためにヱルサレムを選みまた我民イスラエルを治めしむるためにダビデを選めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, '夫イスラエルの神ヱホバの名のために家を建ることは我父ダビデの心にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, '然るにヱホバわが父ダビデに言たまひけるは我名のために家を建ること汝の心にあり汝の心にこの事あるは善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, '然れども汝はその家を建べからず汝の腰より出る汝の子その人わが名のために家を建べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, '而してヱホバその言たまひし言をおこなひたまへり即ち我わが父ダビデに代りて立ちヱホバの言たまひしごとくイスラエルの位に坐しイスラエルの神ヱホバの名のために家を建て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'その中にヱホバがイスラエルの子孫になしたまひし契約を容る櫃ををさめたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'ソロモン、イスラエルの全會衆の前にてヱホバの壇の前に立てその手を舒ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'ソロモンさきに長五キユビト濶五キユビト高三キユビトの銅の臺を造りてこれを庭の眞中に据おきたりしが乃ちその上に立ちイスラエルの全會衆の前にて膝をかがめ其手を天に舒て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, '言けるはイスラエルの神ヱホバ天にも地にも汝のごとき神なし汝は契約を保ちたまひ心を全うして汝の前に歩むところの汝の僕等に恩惠を施こしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, '汝は汝の僕わが父ダビデにのたまひし所を保ちたまへり汝は口をもて言ひ手をもて成就たまへること今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'イスラエルの神ヱホバよ然ば汝が僕わが父ダビデに語りて若し汝の子孫その道を愼みて汝がわが前に歩めるごとくに我律法にあゆまばイスラエルの位に坐する人わが前にて汝に缺ること無るべしと言たまひし事をダビデのために保ちたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, '然ばイスラエルの神ヱホバよ汝が僕ダビデに言たまへるなんぢの言に效驗あらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, '但し神果して地の上に人とともに居たまふや夫天も諸天の天も汝を容るに足ず况て我が建たる此家をや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, '然れども我神ヱホバよ僕の祈祷と懇願をかへりみて僕が今汝の前に祈るその號呼と祈祷を聽たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, '願くは汝の目を夜晝此家の上即ち汝が其名を置んと言たまへる所の上に開きたまへ願くは僕がこの處にむかひて祈らん祈祷を聽たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, '願くは僕と汝の民イスラエルがこの處にむかひて祈る時にその懇願を聽たまへ請ふ汝の住處なる天より聽き聽て赦したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, '人その隣人にむかひて罪を犯せることありてその人誓をもて誓ふことを要められんに若し來りてこの家において汝の壇の前に誓ひなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, '汝天より聽て行ひ汝の僕等を鞫き惡き者に返報をなしてその道をその首に歸し義者を義としてその義にしたがひて之を待ひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, '汝の民イスラエルなんぢに罪を犯したるがために敵の前に敗れんに若なんぢに歸りて汝の名を崇め此家にて汝の前に祈り願ひなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, '汝天より聽て汝の民イスラエルの罪を赦し汝が彼等とその先祖に與へし地に彼等を歸らしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, '彼らが汝に罪を犯したるがために天閉て雨なからんに彼ら若この處にむかひて祈り汝の名を崇め汝が彼らを苦しめたまふ時にその罪を離れなば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, '汝天より聽きて汝の僕等なんぢの民イスラエルの罪を赦したまへ汝旣にかれらにその歩むべき善道を敎へたまへり汝の民に與へて產業となさしめたまひし汝の地に雨を降したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, '若くは國に饑饉あるか若くは疫病枯死朽腐蟊賊稲蠹あるか若くは其敵かれらをその國の邑に圍む等如何なる災禍如何なる疾病あるとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'もし一人或は汝の民イスラエルみな各々おのれの災禍と憂患を知てこの家にむかひて手を舒なば如何なる祈祷如何なる懇願をなすとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, '汝の住處なる天より聽て赦し各々の人にその心を知たまふごとくその道々にしたがひて報いたまへ其は汝のみ人々の心を知たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, '汝かく彼らをして汝が彼らの先祖に與へたまへる地に居る日の間つねに汝を畏れしめ汝の道に歩ましめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, '且汝の民イスラエルの者にあらずして汝の大なる名と強き手と伸たる腕とのために遠き國より來れる異邦人においてもまた若來りてこの家にむかひて祈らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, '汝の住處なる天より聽き凡て異邦人の汝に龥もとむるごとく成たまへ汝かく地の諸の民をして汝の名を知らしめ汝の民イスラエルの爲ごとくに汝を畏れしめ又わが建たる此家は汝の名をもて稱らるるといふことを知しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, '汝の民その敵と戰はんとて汝の遣はしたまふ道に進める時もし汝が選びたまへるこの邑およびわが汝の名のために建たる家にむかひて汝に祈らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, '汝天より彼らの祈祷と懇願を聽て彼らを助けたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, '人は罪を犯さざる者なければ彼ら汝に罪を犯すことありて汝かれらを怒り彼らをその敵に付したまひて敵かれらを虜として遠き地または近き地に曳ゆかん時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, '彼らその擄れゆきし地において自ら心に了るところあり其俘擄の地において翻へりて汝に祈り我らは罪を犯し悖れる事を爲し惡き事を行ひたりと言ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'その擄へゆかれし俘擄の地にて一心一念に汝に立歸り汝がその先祖に與へたまへる地にむかひ汝が選びたまへる邑と我が汝の名のために建たる家にむかひて祈らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, '汝の住處なる天より彼らの祈祷と懇願を聽て彼らを助け汝の民が汝にむかひて罪を犯したるを赦したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, '然ば我神よ願くは此處にて爲す祈祷に汝の目を開き耳を傾むけたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'ヱホバ神よ今汝および汝の力ある契約の櫃起て汝の安居の所にいりたまへヱホバ神よ願くは汝の祭司等に拯救の衣を纒はせ汝の聖徒等に恩惠を喜こばせたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'ヱホバ神よ汝の膏そそぎし者の面を黜ぞけたまふ勿れ汝の僕ダビデの徳行を記念たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'ソロモン祈ることを終し時天より火くだりて燔祭と犠牲とを焚きヱホバの榮光その家に充り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'ヱホバの榮光ヱホバの家に充しに因て祭司はヱホバの家に入ことを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'イスラエルの子孫は皆火の降れるを見またヱホバの榮光のその家にのぞめるを見て敷石の上にて地に俯伏て拝しヱホバを讃て云り善かなヱホバその恩惠は世々限なしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, '斯て王および民みなヱホバの前に犠牲を献ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'ソロモン王の献げたる犠牲は牛二萬二千羊十二萬斯王と民みな神の家を開けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, '祭司は立てその職をなしレビ人はヱホバの樂器を執て立つ其樂器はダビデ王彼らの手によりて讃美をなすに當り自ら作りてヱホバの恩惠は世々限なしと頌へしめし者なり祭司は彼らの前にありて喇叭を吹きイスラエルの人は皆立をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'ソロモンまたヱホバの家の前なる庭の中を聖め其處にて燔祭と酬恩祭の脂とを献げたり是はソロモンの造れる銅の壇その燔祭と素祭と脂とを受るに足ざりしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'その時ソロモン七日の間節筵をなしけるがイスラエル全國の人々すなはちハマテの入口よりエジプトの河までの人々あつまりて彼とともにあり其會はなはだ大なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'かくて第八日に聖會を開けり彼らは七日のあひだ壇奉納の禮をおこなひまた七日のあひだ節筵を守りけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, '七月の二十三日にいたりてソロモン民をその天幕に歸せり皆ヱホバがダビデ、ソロモンおよびその民イスラエルに施こしたまひし恩惠のために喜こび且心に樂しみて去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'ソロモン、ヱホバの家と王の家とを造了へヱホバの家と己の家とにつきて爲んと心に思ひし事を盡く成就たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, '時にヱホバ夜ソロモンに顯れて之に言たまひけるは我すでに汝の祈祷を聽きまた此處をわがために選びて犠牲を献ぐる家となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, '我天を閉て雨なからしめ又は蟊賊に命じて地の物を食はしめ又は疫病を我民の中におくらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, '我名をもて稱らるる我民もし自ら卑くし祈りてわが面を求めその惡き道を離れなば我天より聽てその罪を赦しその地を醫さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, '今より我この處の祈祷に目を啓き耳を傾むけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, '今我すでに此家を選びかつ聖別む我名は永く此にあるべしまた我目もわが心も恒に此にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, '汝もし汝の父ダビデの歩みしごとく我前に歩み我が汝に命じたるごとく凡て行ひてわが法度と律例を守らば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, '我は汝の父ダビデに契約してイスラエルを治むる人汝に缺ること無るべしと言しごとく汝の國の祚を堅うすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, '然ど汝ら若ひるがへり我が汝らの前に置たる法度と誡命を棄て往て他の神々に事へかつ之を拝まば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, '我かれらを我が與へたる地より抜さるべし又我名のために我が聖別たる此家は我これを我前より投棄て萬國の中に諺語となり嘲笑とならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, '且又この家は高くあれども終にはその傍を過る者は皆これに驚きて言んヱホバ何故に此地に此家に斯なしたるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, '人これに答へて言ん彼ら己の先祖をエジプトの地より導き出ししその神ヱホバを棄て他の神々に附從がひ之を拝み之に事へしによりてなりヱホバ之がためにこの諸の災禍を彼らに降せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'ソロモン二十年を經てヱホバの家と己の家を建をはりけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'ヒラム邑幾何をソロモンに歸しければソロモンまた之を建なほしイスラエルの子孫をしてその中に住しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'ソロモンまたハマテゾバに往て之に勝り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, '彼また曠野のタデモルを建てハマテの諸の府庫邑を建つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'また上ベテホロンおよび下ベテホロンを建つ是は堅固の邑にして石垣あり門あり關木あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'ソロモンまたバアラテとおのが有る府庫の邑々と戰車の諸の邑々と騎兵の邑々ならびにそのエルサレム、レバノンおよび己が治むるところの全地に建んと望みし者を盡く建つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, '凡てイスラエルの子孫にあらざるヘテ人アモリ人ペリジ人ヒビ人ヱブス人の遺れる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'その地にありて彼らの後に遺れるその子孫即ちイスラエルの子孫の滅ぼし盡さざりし民はソロモンこれを使役して今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, '然れどもイスラエルの子孫をばソロモン一人も奴隸となして其工事に使ふことをせざりき彼らは軍人となり軍旅の長となり戰車と騎兵の長となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'ソロモン王の有司の首は二百五十人ありて民を統ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'ソロモン、パロの女をダビデの邑より携へのぼりて曩にこれがために建おきたる家にいたる彼すなはち言り我妻はイスラエルの王ダビデの家に居べからずヱホバの契約の櫃のいたれる處は皆聖ければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, '茲にソロモン曩に廊の前に築きおきたるヱホバの壇の上にてヱホバに燔祭を献ぐることをせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, '即ちモーセの命令にしたがひて毎日例のごとくに之を献げ安息日月朔および年に三次の節會すなはち酵いれぬパンの節と七週の節と結茅節とに之を献ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'ソロモンその父ダビデの定めたる所にしたがひて祭司の班列を定めてその職に任じ又レビ人をその勤務に任じて日々例のごとく祭司の前にて頌讃をなし奉事をなさしめ又門を守る者をしてその班列にしたがひて諸門を守らしむ神の人ダビデの命ぜしところ是の如くなりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, '祭司とレビ人は諸の事につきまた府庫の事につきて王に命ぜられたる所に違ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'ソロモンはヱホバの家の基を置る日までにその工事の準備をことごとく爲しおきて遂に之を成をへたればヱホバの家は全備せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, '茲にソロモン、ヱドムの地の海邊にあるエジオンゲベルおよびエロテに往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, '時にヒラムその僕等の手に託て船を彼に遣りまた海の事を知る僕等を遣りけるが彼等すなはちソロモンの僕とともにオフルに往て彼處より金四百五十タラントを取てソロモン王の許に携へ來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, '茲にシバの女王ソロモンの風聞を聞および難問をもてソロモンを試みんとて甚だ衆多の部從をしたがへ香物と夥多き金と寶石とを駱駝に負せてヱルサレムに來りソロモンの許にいたりてその心にある所をことごとく之に陳けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'ソロモンこれが問に盡く答へたりソロモンの知ずして答へざる事は無りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'シバの女王ソロモンの智慧とその建たる家を觀');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'またその席の食物とその諸臣の列坐る状とその侍臣の伺候状と彼らの衣服およびその酒人とその衣服ならびに彼がヱホバの家に上りゆく昇道を觀におよびて全くその氣を奪はれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, '是において彼王に言けるは我が自己の國にて汝の行爲と汝の智慧とにつきて聞およびたる言は眞實なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, '然るに我は來りて目に觀るまではその言を信ぜざりしが今視ば汝の智慧の大なる事我が聞たるはその半分にも及ばざりき汝は我が聞たる風聞に愈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, '汝の人々は幸福なるかな汝の前に常に立て汝の智慧を聽る此なんぢの臣僕等は幸福なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, '汝の神ヱホバは讃べき哉彼なんぢを悦こびてその位に上らせ汝の神ヱホバの爲に汝を王となしたまへり汝の神イスラエルを愛して永く之を堅うせんとするが故に汝を之が王となして公平と正義を行はせたまふなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'すなはち金百二十タラントおよび莫大の香物と寶石とを王に饋れりシバの女王がソロモン王に饋りたるが如き香物は未だ曾て有ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, '(かのオフルより金を取きたりしヒラムの臣僕とソロモンの臣僕等また白檀木と寶石とをも携さへいたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, '王その白檀木をもてヱホバの家と王の宮とに段階を作りまた謳歌者のために琴と瑟とを作れり是より前には是のごとき者ユダの地に見しこと無りき)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'ソロモン王シバの女王に物を饋りてその携へきたれる所に報いたるが上にまた之が望にまかせて凡てその求むる者を與へたり斯て彼はその臣僕とともに去てその國に還りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, '一年にソロモンの所に來れる金の重量は六百六十六タラントなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'この外にまた商賣および商旅の携へきたる者ありアラビアの一切の王等および國の知事等もまた金銀をソロモンに携へ至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'ソロモン王展金の大楯二百を作れりその大楯一枚には展金六百シケルを用ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'また展金の小干三百を作れり其小干一枚には金三百シケルを用ふ王これらをレバノン森の家に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, '王また象牙をもて大なる寳座一を造り純金をもて之を蔽へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'その寳座には六の階級あり又金の足臺ありて共にその寳座に連なりその坐する處の此旁彼旁に按手ありて按手の側に二頭の獅子立をり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'その六の階級に十二の獅子ありて此旁彼旁に立り是のごとき者を作れる國は未だ曾て有ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'ソロモン王の用ゐる飮料の器は皆金なりまたレバノン森の家の器もことごとく精金なり銀はソロモンの世には何とも算ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, '其は王の舟ヒラムの僕を乗てタルシシに往き三年毎に一回その舟タルシシより金銀象牙猿および孔雀を載て來りたればたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'ソロモン王は天下の諸王に勝りて富有と智慧とをもちたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, '天下の諸王みな神がソロモンの心に授けたまへる智慧を聽んとてソロモンの面を見んことを求め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, '各々その禮物を携さへ來る即ち銀の器金の器衣服甲冑香物馬騾など年々定分ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'ソロモン戰車の馬四千厩騎兵一萬二千あり王これを戰車の邑々に置きまたヱルサレムにて自己の所に置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, '彼は河よりペリシテの地とエジプトの界までの諸王を統治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, '王は銀を石のごとくヱルサレムに多からしめまた香柏を平野の桑木のごとく多からしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'また人衆エジプトなどの諸國より馬をソロモンに率いたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'ソロモンのその餘の始終の行爲は預言者ナタンの書とシロ人アヒヤの預言と先見者イドがネバテの子ヤラベアムにつきて述たる默旨の中に記さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'ソロモンはヱルサレムにて四十年の間イスラエルの全地を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'ソロモンその先祖等と倶に寝りてその父ダビデの邑に葬られ其子レハベアムこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, '爰にレハベアム、シケムに往り其はイスラエルみな彼を王となさんとてシケムに到りたればたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'ネバテの子ヤラベアムはさきにソロモン王の面を避てエジプトに逃れ居しがこのことを聞てエジプトより歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, '人衆人を遣はして之を招きたるなり斯てヤラベアムとイスラエルの人みな來りてレハベアムに語りて言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '汝の父我らの軛を苦しくせり然ば汝今汝の父の苦しき役とその我らに蒙むらせたる重き軛を軽くしたまへ然れば我儕なんぢに事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'レハベアムかれらに言けるは汝ら三日を經て再び我に來れと民すなはち去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, '是においてレハベアム王その父ソロモンの生る間これが前に立たる老人等に計りて言けるは汝ら如何に敎へて此民に答へしむるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, '彼らレハベアムに語りて言けるは汝もし此民を厚く待ひ之を悦こばせ善言を之に語らば永く汝の僕たらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, '然るに彼その老人等の敎へし敎を棄て自己とともに生長て己の前に立ところの少年等と計れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, '即ち彼らに言けるは汝ら如何に敎へて我らをして此我に語りて汝の父の我らに蒙むらせし軛を軽くせよと言ふ民に答へしむるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, '彼とともに生長たる少年等かれに語りて言けるは汝に語りて汝の父我らの軛を重くしたれば汝これを我らのために軽くせよと言たる此民に汝かく答へ斯これに言べし吾小指は我父の腰よりも太し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, '我父は汝らに重き軛を負せたりしが我は更に汝らの軛を重くせん我父は鞭をもて汝らを懲せしが我は蠍をもて汝らを懲さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, '偖またヤラベアムと民等は皆王の告て第三日に再び我にきたれと言しごとく第三日にレハベアムに詣りしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, '王荒々しく彼らに答へたり即ちレハベアム王老人の敎を棄て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, '少年の敎のごとく彼らに告て言けるは我父は汝らの軛を重くしたりしが我は更に之を重くせん我父は鞭をもて汝らを懲せしが我は蠍をもて汝らを懲さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, '王かく民に聽ことをせざりき此事は神より出たる者にしてその然るはヱホバかつてシロ人アヒヤによりてネバテの子ヤラベアムに告たる言を成就んがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'イスラエルの民みな王の己に聽ざるを見しかば王に答へて言けるは我らダビデの中に何の分あらんやヱッサイの子の中には所有なしイスラエルよ汝ら各々その天幕に歸れダビデ族よ今おのれの家を顧みよと斯イスラエルは皆その天幕に歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, '但しユダの邑々に住るイスラエルの子孫の上にはレハベアムなほ王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'レハベアム王役夫の頭なるアドラムを遣はしけるにイスラエルの子孫石をもてこれを撃て死しめたればレハベアム王急ぎてその車に登りてエルサレムに逃かへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, '是のごとくイスラエルはダビデの家に背きて今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, '茲にレハベアム、ヱルサレムに至りてユダとベニヤミンの家より倔強の武者十八萬を集め而してレハベアム國を己に歸さんためにイスラエルと戰はんとせしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'ヱホバの言神の人シマヤに臨みて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'ソロモンの子ユダの王レハベアムおよびユダとベニヤミンにあるイスラエルの人々に告て言べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'ヱホバかく言ふ汝ら攻上るべからず又なんぢらの兄弟と戰ふべからず各々その家に歸れ此事は我より出たる者なりと彼ら乃はちヱホバの言にしたがひヤラベアムに攻ゆくことを止て歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, '斯てレハベアム、ヱルサレムに居りユダに守衛の邑々を建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, '即ちその建たる者はベテレヘム、エタム、テコア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'ベテズル`シヨコ、アドラム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'ガテ、マレシヤ、ジフ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'アドライム、ラキシ、アゼカ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'ゾラ、アヤロン、ヘブロン是等はユダとベニヤミンにありて守衛の邑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, '彼その守衛の邑々を堅固にし之に軍長を置き糧食と油と酒とを貯はへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'またその一切の邑に盾と矛とを備へて之を甚だ強からしむユダとベニヤミンこれに附り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'イスラエルの全地の祭司とレビ人は四方の境より來りてレハベアムに投ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, '即ちレビ人はその郊地と產業とを離れてユダとヱルサレムに至れり是はヤラベアムとその子等かれらを廢して祭司の職をヱホバの前に爲しめざりし故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'ヤラベアムは崇邱と牡山羊と己が作れる犢とのために自ら祭司を立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'またイスラエルの一切の支派の中凡てその心を傾むけてイスラエルの神ヱホバを求むる者はその先祖の神ヱホバに禮物を献げんとてレビ人にしたがひてヱルサレムに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, '是のごとく彼等ユダの國を固うしソロモンの子レハベアムをして三年の間強からしめたり即ち民は三年の間ダビデとソロモンの道に歩めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'レハベアムはダビデの子ヱレモテの女マハラテを妻に娶れりマハラテはヱッサイの子エリアブの女アビハイルの產し者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, '彼ヱウシ、シヤマリヤおよびザハムの三子を產む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'また之が後にアブサロムの女マアカを娶れり彼アビヤ、アツタイ、ジザおよびシロミテを產む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'レハベアムはアブサロムの女マアカをその一切の妻と妾とにまさりて愛せり彼は妻十八人妾六十人を取り男子二十八人女子六十人を擧く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'レハベアム、マアカの子アビヤを王となさんと思ふが故に之を立て首となしその兄弟の長となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, '斯るが故に慧く取行ひ其男子等を盡くユダとベニヤミンの地なる守衛の邑々に散し置き之に糧食を多く與へかつ衆多の妻を求得させたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'レハベアムその國を固くしその身を強くするに及びてヱホバの律法を棄たりイスラエルみな之に傚ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, '彼ら斯ヱホバにむかひて罪を犯すによりてレハベアムの五年にエジプトの王シシヤク、ヱルサレムに攻のぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'その戰車は一千二百騎兵は六萬また彼に從がひてエジプトより來れる民ルビ人スキ人エテオピヤ人等は數しれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, '彼すなはちユダの守衛の邑々を取り進てヱルサレムに至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, '是においてレハベアムおよびユダの牧伯等シシヤクの故によりてヱルサレムに集まり居けるに預言者シマヤこれが許にいたりて之に言けるはヱホバかく言たまふ汝等は我を棄たれば我も汝らをシシヤクの手に遺おけりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, '是をもてイスラエルの牧伯等および王は自ら卑くしてヱホバは義と言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'ヱホバかれらが自ら卑くするを見たまひければヱホバの言シマヤに臨みて言ふ彼等は自ら卑くしたれば我かれらを滅ぼさず少く拯救を彼らに施こさん我シシヤクの手をもて我忿怒をヱルサレムに洩さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, '然ながら彼等は之が臣とならん是彼らが我に事ふる事と國々の王等に事ふる事との辨をしらん爲なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'エジプトの王シシヤクすなはちヱルサレムに攻のぼりヱホバの家の寶物と王の家の寶物とを奪ひて盡くこれを取り又ソロモンの作りたる金の楯を奪ひされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, '是をもてレハベアム王その代に銅の楯を作り王の家の門を守る侍衛の長等の手にこれを交し置けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, '王ヱホバの家に入る時には侍衛きたりて之を負ひまた侍衛の房にこれを持かへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'レハベアム自ら卑くしたればヱホバの忿怒かれを離れこれを盡く滅ぼさんとは爲たまはず又ユダにも善事ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'レハベアム王はヱルサレムにありてその力を強くし世を治めたり即ちレハベアムは四十一歳のとき位に即き十七年の間ヱルサレムにて世を治む是すなはちヱホバがその名を置んとてイスラエルの一切の支派の中より選びたまへる邑なり彼の母はアンモニ人にしてその名をナアマといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'レハベアムはヱホバを求むる事に心を傾けずして惡き事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'レハベアムの始終の行爲は預言者シマヤの書および先見者イドの書の中に系圖の形に記さるるに非ずやレハベアムとヤラベアムの間には絶ず戰爭ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'レハベアムその先祖等とともに寝りてダビデの邑に葬られ其子アビヤ之にかはりて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'ヤラベアム王の十八年にアビヤ、ユダの王となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'ヱルサレムにて三年の間世を治めたり其母はギベアのウリエルの女にして名をミカヤといふ茲にアビヤとヤラベアムの間に戰爭あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'アビヤは四十萬の軍勢をもて戰闘に備ふ是みな倔強の猛き武夫なり又ヤラベアムは倔強の人八十萬をもて之にむかひて戰爭の行伍を立つ是また大勇士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, '時にアビヤ、エフライムの山地なるゼマライム山の上に立て言けるはヤラベアムおよびイスラエルの人々皆聽よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, '汝ら知ずやイスラエルの神ヱホバ鹽の契約をもてイスラエルの國を永くダビデとその子孫に賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, '然るにダビデの子ソロモンの臣たるネバテの子ヤラベアム興りてその主君に叛き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, '邪曲なる放蕩者これに集り附き自ら強くしてソロモンの子レハベアムに敵せしがレハベアムは少くまた心弱くして之に當る力なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, '今またなんぢらはダビデの子孫の手にあるヱホバの國に敵對せんとす汝らは大軍なり又ヤラベアムが作りて汝らの神と爲たる金の犢なんぢらと偕にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, '汝らはアロンの子孫たるヱホバの祭司とレビ人とを逐放ち國々の民の爲がごとくに祭司を立るにあらずや即ち誰にもあれ少き牡牛一匹牡羊七匹を携へきたりて手に充す者は皆かの神ならぬ者の祭司となることを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, '然ど我儕に於てはヱホバ我儕の神にましまして我儕は之を棄ずまたヱホバに事ふる祭司はアロンの子孫にして役事をなす者はレビ人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, '彼ら朝ごと夕ごとにヱホバに燔祭を献げ香を焚くことを爲し又供前のパンを純精の案の上に供へまた金の燈臺とその燈盞を整へて夕ごとに點すなり斯われらは我らの神ヱホバの職守を守れども汝らは却て彼を棄たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, '視よ神みづから我らとともに在して我らの大將となりたまふまた其祭司等は喇叭を吹ならして汝らを攻むイスラエルの子孫よ汝らの先祖の神ヱホバに敵して戰ふ勿れ汝ら利あらざるべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'ヤラベアム伏兵を彼らの後に回らせたればイスラエルはユダの前にあり伏兵は其後にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'ユダ後を顧みるに敵前後にありければヱホバにむかひて號呼り祭司等喇叭を吹り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'ユダの人々すなはち吶喊を擧けるがユダの人々吶喊を擧るにあたりて神ヤラベアムとイスラエルの人々をアビヤとユダの前に打敗り給ひしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'イスラエルの子孫はユダの前より逃はしれり神かく彼らを之が手に付したまひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'アビヤとその民彼らを夥多く撃殺せりイスラエルの殺されて倒れし者は五十萬人みな倔強の人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, '是時にはイスラエルの子孫打負されユダの子孫勝を得たり是は彼らその先祖の神ヱホバを賴みしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'アビヤすなはちヤラベアムを追撃て邑數箇を彼より取れり即ちベテルとその郷里ヱシヤナとその郷里エフロンとその郷里是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'ヤラベアムはアビヤの世に再び權勢を奮ふことを得ずヱホバに撃れて死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, '然どアビヤは權勢を得妻十四人を娶り男子二十二人女子十六人を擧けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'アビヤのその餘の作爲とその行爲とその言は預言者イドの註釋に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'アビヤその先祖等とともに寝りてダビデの邑に葬られその子アサこれに代りて王となれりアサの代になりて其國十年の間平穩なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'アサはその神ヱホバの目に善と視正義と視たまふ事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, '即ち異なる祭壇を取のぞき諸の崇邱を毀ち柱像を打碎きアシラ像を斫倒し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'ユダに命じてその先祖等の神ヱホバを求めしめその律法と誡命を行はしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'ユダの一切の邑々より崇邱と日の像とを取除けり而して國は彼の前に平穩なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, '彼また守衛の邑數箇をユダに建たり是はその國平安を得て此年頃戰爭なかりしに因る即ちヱホバ彼に安息を賜ひしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, '彼すなはちユダに言けるは我儕是等の邑を建てその四周に石垣を築き戌樓を起し門と門閂とを設けん我儕の神ヱホバを我儕求めしに因て此國なほ我儕の前にあり我ら彼を求めたれば四方において我らに平安を賜へりと斯彼ら阻滞なく之を建了たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'アサの軍勢はユダより出たる者三十萬ありて楯と戈とを執りベニヤミンより出たる者二十八萬ありて小楯を執り弓を彎く是みな大勇士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, '茲にエテオピア人ゼラ軍勢百萬人戰車三百輌を率ゐて攻きたりマレシヤに至りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'アサこれにむかひて進み出で共にマレシヤのゼパタの谷において戰爭の陣列を立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, '時にアサその神ヱホバにむかひて呼はりて言ふヱホバよ力ある者を助くるも力なき者を助くるも汝においては異ること無し我らの神ヱホバよ我らを助けたまへ我らは汝に倚賴み汝の名に託りて往て此群集に敵るヱホバよ汝は我らの神にましませり人をして汝に勝せたまふ勿れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'ヱホバすなはちアサの前とユダの前においてエテオピア人を撃敗りたまひしかばエテオピア人逃はしりけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'アサと之に從がふ民かれらをゲラルまで追撃り斯エテオピア人は倒れて再び振ふことを得ざりき其は彼等ヱホバとその軍旅に打敗られたればなりユダの人々の得たる掠取物は甚だ多りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'かれらはまたゲラルの四周の邑々を盡く撃やぶれり是その邑々ヱホバを畏れたればなり是において彼らその一切の邑より物を掠めたりしがその中より得たる掠取物は夥多かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'また家畜のをる天幕を襲ふて羊と駱駝を多く奪ひ取り而してヱルサレムに歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, '茲に神の霊オデデの子アザリヤに臨みければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, '彼出ゆきてアサを迎へ之に言けるはアサおよびユダとベニヤミンの人々よ我に聽け汝等がヱホバと偕にをる間はヱホバも汝らと偕に在すべし汝ら若かれを求めなば彼に遇ん然どかれを棄なば彼も汝らを棄たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, '抑イスラエルには眞の神なく敎訓を施こす祭司なく律法なきこと日久しかりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, '患難の時にイスラエルの神ヱホバに立かへりて之を求めたれば即ちこれに遇り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, '當時は出る者にも入る者にも平安なく惟大なる苦患くにぐにの民に臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, '國は國に邑は邑に撃碎かる其は神諸の患難をもて之を苦しめたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, '然ば汝ら強かれよ汝らの手を弱くする勿れ汝らの行爲には賞賜あるべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'アサこれらの言および預言者オデデの預言を聽て力を得憎むべき者をユダとベニヤミンの全地より除きまた其エフライムの山地に得たる邑々より除きヱホバの廊の前なるヱホバの壇を再興せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, '彼またユダとベニヤミンの人々およびエフライム、マナセ、シメオンより來りて寄寓る者を集めたりイスラエルの人々の中ヱホバ神のアサと偕に在すを見てアサに降れる者夥多しかりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, '彼等すなはちアサの治世の十五年の三月にヱルサレムに集り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, '其たづさへ來れる掠取物の中より牛七百羊七千をその日ヱホバに献げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, '皆契約を結びて曰く心を盡し精神を盡して先祖の神ヱホバを求めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, '凡てイスラエルの神ヱホバを求めざる者は大小男女の區別なく之を殺さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, '而して大聲を擧げ號呼をなし喇叭を吹き角を鳴してヱホバに誓を立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'ユダみなその誓を喜べり即ち彼ら一心をもて誓を立て一念にヱホバを求めたればヱホバこれに遇ひ四方において之に安息をたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, '偖またアサ王の母マアカ、アシラ像を作りしこと有ければアサこれを貶して太后たらしめずその像を斫たふして粉々に碎きキデロン川にてこれを焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, '但し崇邱は尚イスラエルより除かざりき然どもアサの心は一生の間全かりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, '彼はまたその父の納めたる物および己が納めたる物すなはち金銀ならびに器皿等をヱホバの家に携へいれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'アサの治世の三十五年までは再び戰爭あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'アサの治世の三十六年にイスラエルの王バアシヤ、ユダに攻のぼりユダの王アサの所に誰をも往來せざらしめんとてラマを建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, '是においてアサ、ヱホバの家と王の家との府庫より金銀を取いだしダマスコに住るスリアの王ベネハダデに餽りて言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '我父と汝の父の間の如く我と汝の間に約を立ん視よ我今汝に金銀を餽れり往て汝とイスラエルの王バアシヤとの約を破り彼をして我を離れて去しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'ベネハダデすなはちアサ王に聽き自己の軍勢の長等をイスラエルの邑々に攻遣ければ彼等イヨン、ダン、アベルマイムおよびナフタリの一切の府庫の邑々を撃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'バアシヤ聞てラマを建ることを罷めその工事を廢せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, '是においてアサ王ユダ全國の人を率ゐバアシヤがラマを建るに用ひたる石と材木を運びきたらしめ之をもてゲバとミズパを建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'その頃先見者ハナニ、ユダの王アサの許にいたりて之に言けるは汝はスリアの王に倚賴みて汝の神ヱホバに倚賴まざりしに因てスリア王の軍勢は汝の手を脱せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'かのエテオピア人とルビ人は大軍にして戰車および騎兵はなはだ多かりしにあらずや然るも汝ヱホバに倚賴みたればヱホバかれらを汝の手に付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'ヱホバは全世界を徧く見そなはし己にむかひて心を全うする者のために力を顯したまふこの事において汝は愚なる事をなせり故に此後は汝に戰爭あるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, '然るにアサその先見者を怒りて之を獄舎にいれたり其は烈しくこの事のために彼を怒りたればなりアサまた其頃民を虐げたる事ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'アサの始終の行爲はユダとイスラエルの列王の書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'アサはその治世の三十九年に足を病みその病患つひに劇しくなりしがその病患の時にもヱホバを求めずして醫師を求めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'アサその先祖等と偕に寝りその治世の四十一年に死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, '人衆これをその己のためにダビデの邑に堀おける墓に葬り製香の術をもて製したる種々の香物を盈せる床の上に置き之がために夥多しく焚物をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'アサの子ヨシヤパテ、アサに代りて王となりイスラエルにむかひて力を強くし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'ユダの一切の堅固なる邑々に兵を置きユダの地およびその父アサが取たるエフライムの邑々に鎮臺を置く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'ヱホバ、ヨシヤパテとともに在せり其は彼その父ダビデの最初の道に歩みてバアル等を求めず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'その父の神を求めてその誡命に歩みイスラエルの行爲に傚はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'このゆゑにヱホバ國を彼の手に堅く立たまへりまたユダの人衆みなヨシヤパテに禮物を餽れり彼は富と貴とを極めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, '是において彼ヱホバの道にその心を勵まし遂に崇邱とアシラ像とをユダより除けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, '彼またその治世の三年にその牧伯ベネハイル、オバデヤ、ゼカリヤ、ネタンエルおよびミカヤを遣はしてユダの邑々にて敎誨をなさしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'またレビ人の中よりシマヤ、ネタニヤ、ゼバデヤ、アサヘル、セミラモテ、ヨナタン、アドニヤ、トビヤ、トバドニヤなどいふレビ人を遣して之と偕ならしめ且祭司エリシヤマとヨラムをも之と偕に遣はしけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, '彼らはヱホバの律法の書を携ヘユダにおいて敎誨をなしユダの邑々を盡く行めぐりて民を敎へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, '是においてユダの周圍の地の國々みなヱホバを懼れてヨシヤパテを攻ることをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'またペリシテ人の中に禮物および貢の銀をヨシヤパテに餽れる者あり且又アラビヤ人は家畜をこれに餽れり即ち牡羊七千七百牡山羊七千七百');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'ヨシヤパテは益々大になりゆきてユダに城および府庫邑を多く建て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'ユダの邑々に多くの工事を爲し大勇士たる軍人をヱルサレムに置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, '彼等を數ふるにその宗家に循へば左のごとしユダより出たる千人の長の中にはアデナといふ軍長あり大勇士三十萬これに從がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'その次は軍長ヨハナン之に從ふ者は二十八萬人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'その次はジクリの子アマシヤ彼は悦びてその身をヱホバに献げたり大勇士二十萬これに從がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'ベニヤミンより出たる者の中にはエリアダといふ大勇士あり弓および楯を持もの二十萬これに從がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'その次はヨザバデ戰門の準備をなせる者十八萬これに從がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, '是等は皆王に事ふる者等なり此外にまたユダ全國の堅固なる邑々に王の置る者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'ヨシヤパテは富と貴とを極めアハブと縁を結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'かれ數年の後サマリアに下りてアハブを訪ければアハブ彼およびその部從のために牛羊を多く宰りギレアデのラモテに倶に攻上らんことを彼に勸む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'すなはちイスラエルの王アハブ、ユダの王ヨシヤパテに言けるは汝我とともにギレアデのラモテに攻ゆくやヨシヤパテこれに答へけるは我は汝のごとく我民は汝の民のごとし汝とともに戰門に臨まんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'ヨシヤパテまたイスラエルの王に言けるは請ふ今日ヱホバの言を問たまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, '是においてイスラエルの王預言者四百人を集めて之に言けるは我らギレアデのラモテに往て戰ふべきや又は罷べきや彼等いひけるは攻上りたまへ神これを王の手に付したまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'ヨシヤパテいひけるは此外に我らの由て問べきヱホバの預言者此にあらざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'イスラエルの王こたへてヨシヤパテに言けるは外になほ一人あり我ら之によりてヱホバに問ことを得ん然ど彼は今まで我につきて善事を預言せず恒に惡き事のみを預言すれば我彼を惡むなり其者は即ちイムラの子ミカヤなりと然るにヨシヤパテこたへて王しか宣ふ勿れと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'イスラエルの王一人の官吏を呼てイムラの子ミカヤを急ぎ來らしめよと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'イスラエルの王およびユダの王ヨシヤパテは朝衣を纏ひサマリアの門の入口の廣場にて各々その位に坐し居り預言者は皆その前に預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, '時にケナアナの子ゼデキヤ鐵の角を造りて言けるはヱホバかく言たまふ汝是等をもてスリア人を衝て滅ぼし盡すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, '預言者みな斯預言して云ふギレアデのラモテに攻上りて勝利を得たまへヱホバこれを王の手に付したまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, '茲にミカヤを召んとて往たる使者これに語りて言けるは預言者等の言は一の口より出るがごとくにして王に善し請ふ汝の言をも彼らの一人のごとくなして善事を言ヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'ミカヤ言けるはヱホバは活く我神の宣ふ所を我は陳べんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'かくて王に至るに王彼に言けるはミカヤよ我らギレアデのラモテに往て戰かふべきや又は罷べきや彼言けるは上りゆきて利を得たまへ彼らは汝の手に付されんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, '王かれに言けるは我幾度なんぢを誓はせたらば汝ヱホバの名をもて唯眞實のみを我に告るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, '彼言けるは我イスラエルが皆牧者なき羊のごとく山に散をるを見たるがヱホバ是等の者は主なし各々やすらかに其家に歸るべしと言たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'イスラエルの王是においてヨシヤパテに言けるは我なんぢに告て彼は善事を我に預言せず只惡き事のみを預言せんと言しに非ずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'ミカヤまた言けるは然ば汝らヱホバの言を聽べし我視しにヱホバその位に坐し居たまひて天の萬軍その傍に右左に立をりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'ヱホバ言たまひけるは誰かイスラエルの王アハブを誘ひて彼をしてギレアデのラモテにのぼりゆきて彼處に斃れしめんかと即ち一は此ごとくせんと言ひ一は彼ごとくせんと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, '遂に一の霊すすみ出てヱホバの前に立ち我かれを誘はんと言たればヱホバ何をもてするかと之に問たまふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, '我いでて虚言を言ふ霊となりてその諸の預言者の口にあらんと言りヱホバ言たまひけるは汝は誘なひ且これを成就ん出て然すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, '故に視よヱホバ虚言を言ふ霊を汝のこの預言者等の口に入たまへり而してヱホバ汝に災禍を降さんと定めたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, '時にケナアナの子ゼデキヤ近よりてミカヤの頬を批て言けるはヱホバの霊何の途より我を離れゆきて汝と言ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'ミカヤ言けるは汝奧の室にいりて身を匿す日に見るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'イスラエルの王いひけるはミカヤを取てこれを邑の宰アモンおよび王の子ヨアシに曳かへりて言べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, '王かく言ふ我が安然に歸るまで比者を牢にいれて苦惱のパンを食せ苦惱の水を飮せよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'ミカヤ言けるは汝もし眞に平安に歸るならばヱホバ我によりて斯宣ひし事あらずと而してまた言り汝ら民よ皆聽べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'かくてイスラエルの王およびユダの王ヨシヤパテはギレアデのラモテに上りゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'イスラエルの王時にヨシヤパテに言けるは我は服装を變て戰陣の中にいらん汝は朝衣を纒ひたまへとイスラエルの王すなはち服装を變へ二人倶に戰陣の中にいれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'スリアの王その戰車の長等にかねて命じおけり云く汝ら小き者とか大なる者とも戰ふなかれ惟イスラエルの王とのみ戰へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, '戰車の長等ヨシヤパテを見て是はイスラエルの王ならんと言ひ身をめぐらして之と戰はんとせしがヨシヤパテ號呼ければヱホバこれを助けたまへり即ち神彼らを感動して之を離れしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, '戰車の長等彼がイスラエルの王にあらざるを見しかば之を追ことをやめて引返せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, '茲に一箇の人何心なく弓を彎てイスラエルの王の胸當と草摺の間に射あてたれば彼その御者に言けるは我傷を受たれば汝手を旋らして我を軍中より出せと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, '此日戰爭烈しくなりぬイスラエルの王は車の中に自ら扶持て立ち薄暮までスリア人をささへをりしが日の沒る頃にいたりて死り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'ユダの王ヨシヤパテは恙なくヱルサレムに歸りてその家に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, '時に先見者ハナニの子ヱヒウ、ヨシヤパテ王を出むかへて之に言けるは汝惡き者を助けヱホバを惡む者を愛して可らんや之がためにヱホバの前より震怒なんぢの上に臨む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, '然ながら善事もまた汝の身に見ゆ即ち汝はアシラ像を國中より除きかつ心を傾けて神を求むるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'ヨシヤパテはヱルサレムに住をりしが復出てベエルシバよりエフライムの山地まで民の間を行めぐりその先祖の神ヱホバにこれを導き歸せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, '彼またユダの一切の堅固なる邑に裁判人を立つ國中の邑々みな然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, '而して裁判人に言けるは汝等その爲ところを愼め汝らは人のために裁判するに非ずヱホバのために裁判するなり裁判する時にはヱホバ汝らと偕にいます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, '然ば汝らヱホバを畏れ愼みて事をなせ我らの神ヱホバは惡き事なく人を偏視ことなく賄賂を取こと無ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'ヨシヤパテまたレビ人祭司およびイスラエルの族長を選びてヱルサレムに置きヱホバの事および訴訟を審判しむ彼らはヱルサレムにかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'ヨシヤパテこれに命じて云く汝らヱホバを畏れ眞實と誠心をもて斯おこなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, '凡てその邑々に住む汝らの兄弟血を相流せる事または律法と誡命法度と條例などの事につきて汝らに訴へ出ること有ばこれを諭してヱホバに罪を犯さざらしめよ恐らくは震怒なんぢと汝らの兄弟にのぞまん汝ら斯おこなはば愆なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, '視よ祭司の長アマリヤ汝らの上にありてヱホバの事を凡て司どりユダの家の宰イシマエルの子ゼバデヤ王の事を凡て司どる亦レビ人汝らの前にありて官吏とならん汝ら心を強くして事をなせヱホバ善人を祐けたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'この後モアブの子孫アンモンの子孫およびマオニ人等ヨシヤパテと戰はんとて攻きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, '時に或人きたりてヨシヤパテに告て云ふ海の彼旁スリアより大衆汝に攻きたる視よ今ハザゾンタマルにありとハザゾンタマルはすなはちエンゲデなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, '是においてヨシヤパテ懼れ面をヱホバに向てその助を求めユダ全國に斷食を布令しめたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'ユダ擧て集りヱホバの助を求めたり即ちユダの一切の邑より人々きたりてヱホバを求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, '時にヨシヤパテ、ヱホバの室の新しき庭の前においてユダとヱルサレムの會衆の中に立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, '言けるは我らの先祖の神ヱホバよ汝は天の神にましますに非ずや異邦人の諸國を統たまふに非ずや汝の手には能力あり權勢ありて誰もなんぢを禦ぐこと能はざるに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, '我らの神よ汝は此國の民を汝の民イスラエルの前より逐はらひて汝の友アブラハムの子孫に之を永く與へたまひしに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, '彼らは此に住み汝の名のために此に聖所を建て言へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '刑罰の劍疫病饑饉などの災禍われらに臨まん時は我らこの家の前に立て汝の前にをりその苦難の中にて汝に呼號らんしかして汝聽て助けたまはん汝の名はこの家にあればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, '今アンモン、モアブおよびセイル山の子孫を視たまへ在昔イスラエル、エジプトの國より出きたれる時汝イスラエルに是等を侵さしめたまはざりしかば之を離れさりて滅ぼさざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'かれらが我らに報ゆる所を視たまへ彼らは汝がわれらに有たしめたまへる汝の產業より我らを逐はらはんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, '我らの神よ汝かれらを鞫きたまはざるや我らは此斯く攻よせたる此の大衆に當る能力なく又爲ところを知ず唯汝を仰ぎ望むのみと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'ユダの人々はその小者および妻子とともに皆ヱホバの前に立をれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, '時に會衆の中にてヱホバの霊アサフの子孫たるレビ人ヤハジエルに臨めりヤハジエルはゼカリヤの子ゼカリヤはベナヤの子ベナヤはヱイエルの子ヱイエルはマツタニヤの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'ヤハジエルすなはち言けるはユダの人衆およびヱルサレムの居民ならびにヨシヤパテ王よ聽べしヱホバかく汝らに言たまふ此大衆のために懼るる勿れ慄くなかれ汝らの戰に非ずヱホバの戰なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'なんぢら明日彼らの所に攻くだれ彼らはヂヅの坡より上り來る汝らヱルエルの野の前なる谷の口にて之に遇ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'この戰爭には汝ら戰ふにおよばずユダおよびヱルサレムよ汝ら惟進みいでて立ち汝らとともに在すヱホバの拯救を見よ懼る勿れ慄くなかれ明日彼らの所に攻いでよヱホバ汝らとともに在せばなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, '是においてヨシヤパテ首をさげて地に俯伏りユダの人衆およびヱルサレムの民もヱホバの前に伏てヱホバを拝す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, '時にコハテの子孫およびコラの子孫たるレビ人立あがり聲を高くあげてイスラエルの神ヱホバを讃美せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'かくて皆朝はやく起てテコアの野に出ゆけり其いづるに當りてヨシヤパテ立て言けるはユダの人衆およびヱルサレムの民よ我に聽け汝らの神ヱホバを信ぜよ然ば汝ら堅くあらんその預言者を信ぜよ然ば汝ら利あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, '彼また民と議りて人々を選び之をして聖き飾を著て軍勢の前に進ましめヱホバにむかひて歌をうたひ且これを讃美せしめヱホバに感謝せよ其恩惠は世々かぎりなしと言しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'その歌を歌ひ讃美をなし始むるに當りてヱホバ伏兵を設けかのユダに攻きたれるアンモン、モアブ、セイル山の子孫をなやましたまひければ彼ら打敗られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, '即ちアンモンとモアブの子孫起てセイル山の民にむかひ盡くこれを殺して滅ししがセイルの民を殺し盡すに及びて彼らも亦力をいだして互に滅ぼしあへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'ユダの人々野の觀望所に至りてかの群衆を觀たりければ唯地に仆れたる死屍のみにして一人だに逃れし者なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, '是においてヨシヤパテおよびその民彼らの物を奪はんとて來り觀にその死屍の間に財寳衣服および珠玉などおびただしく在たれば則ち各々これを剥とりけるが餘に多くして携さへ去こと能はざる程なりき其物多かりしに因て之を取に三日を費しけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, '第四日にベラカ(感謝)の谷に集り其處にてヱホバに感謝せり是をもてその處の名を今日までベラカ(感謝)の谷と呼ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, '而してユダとヱルサレムの人々みな各々歸りきたりヨシヤパテの後にしたがひ歓びてヱルサレムに至れり其はヱホバ彼等をしてその敵の故によりて歓喜を得させたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, '即ち彼ら瑟と琴および喇叭を合奏してヱルサレムに往てヱホバの室にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, '諸の國の民ヱホバがイスラエルの敵を攻撃たまひしことを聞て神を畏れたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'ヨシヤパテの國は平穩なりき即ちその神四方において之に安息を賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'ヨシヤパテはユダの王となり三十五歳のときその位に即き二十五年の間ヱルサレムにて世を治めたり其母はシルヒの女にして名をアズバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'ヨシヤパテはその父アサの道にあゆみて之を離れずヱホバの目に善と觀たまふ事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, '然れども崇邱はいまだ除かず又民はいまだその先祖の神に心を傾けざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'ヨシヤパテのその餘の始終の行爲はハナニの子ヱヒウの書に記さるヱヒウの事はイスラエルの列王の書に載す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'ユダの王ヨシヤパテ後にイスラエルの王アハジアと相結べりアハジアは大に惡を行ふ者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'ヨシヤパテ、タルシシに遣る舟を造らんとて彼と相結びてエジオンゲベルにて共に舟數隻を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, '時にマレシヤのドダワの子エリエゼル、ヨシヤパテにむかひて預言して云ふ汝アハジアと相結びたればヱホバなんぢの作りし者を毀ちたまふと即ちその舟は皆壞れてタルシシに往くことを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'ヨシヤパテその先祖等とともに寝りてダビデの邑にその先祖等とともに葬られその子ヨラムこれに代て王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'ヨシヤパテの子たるその兄弟はアザリヤ、ヱヒエル、ゼカリヤ、アザリヤ、ミカエルおよびシバテヤ是みなイスラエルの王ヨシヤパテの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'その父彼らに金銀寶物の賜物を多く與へまたユダの守衛の邑々を與へけるが國はヨラムに與へたりヨラム長子なりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'ヨラムその父の位に登りて力つよくなりければその兄弟等をことごとく劍にかけて殺し又イスラエルの牧伯等數人を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'ヨラムは三十二歳の時位に即ヱルサレムにて八年の間世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, '彼はアハブの家のなせるごとくイスラエルの王等の道にあゆめりアハブの女を妻となしたればなり斯かれヱホバの目に惡と觀たまふ事をなせしかども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'ヱホバ曩にダビデに契約をなし且彼とその子孫とに永遠に光明を與へんと言たまひし故によりてダビデの家を滅ぼすことを欲み給はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'ヨラムの世にエドム人叛きてユダの手に服せず自ら王を立たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'ヨラム其牧伯等および一切の戰車をしたがへて渉りゆき夜の中に起いでて自己を圍めるエドム人を撃ちその戰車の長等を撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'エドム人は斯叛きてユダの手に服せずなりしが今日まで然り此時にあたりてリブナもまた叛きてユダの手に服せずなりぬ是はヨラムその先祖の神ヱホバを棄たるに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, '彼またユダの山々に崇邱を作りてヱルサレムの民に姦淫をおこなはせユダを惑はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, '時に預言者エリヤの書ヨラムの許に達せり其言に云く汝の先祖ダビデの神ヱホバかく言たまふ汝はその父ヨシヤパテの道にあゆまずまたユダの王アサの道にあゆまずして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'イスラエルの王等の道にあゆみユダの人とヱルサレムの民をしてアハブの家の姦淫をなせるごとくに姦淫を行はしめまた汝の父の家の者にて汝に愈れるところの汝の兄弟等を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, '故にヱホバ大なる災禍をもて汝の民汝の子女汝の妻等および汝の一切の所有を撃たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, '汝はまた臓腑の疾を得て大病になりその疾日々に重りて臓腑つひに墜んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, '即ちヱホバ、ヨラムを攻させんとてエテオピアに近きところのペリシテ人とアラビヤ人の心を振起したまひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, '彼らユダに攻のぼりて之を侵し王の家に在ところの貨財を盡く奪ひ取りまたヨウムの子等と妻等をも携へ去れり是をもてその末子ヱホアハズの外には一人も遺れる者なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, '此もろもろの事の後ヱホバ彼を撃て臓腑に愈ざる疾を生ぜしめたまひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, '月日を送り二年を經るにおよびてその臓腑疾のために墜ち重き病苦によりて死ねり民かれの先祖のために焚物をなせし如く彼のためには焚物をなさざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, '彼は三十二歳の時位に即き八年の間ヱルサレムにて世を治めて終に薨去れり之を惜む者なかりき人衆これをダビデの邑に葬れり但し王等の墓にはあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'ヱルサレムの民ヨラムの季子アハジアを王となして之に継しむ其は曾てアラビヤ人とともに陣營に攻きたりし軍兵その長子をことごとく殺したればなり是をもてユダの王ヨラムの子アハジア王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'アハジアは四十二歳の時位に即きヱルサレムにて一年の間世を治めたりその母はオムリの女にして名をアタリヤといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'アハジアもまたアハブの家の道に歩めり其母かれを敎へて惡をなさしめたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, '即ち彼はアハブの家のごとくにヱホバの目の前に惡をおこなへり其父の死し後彼かくアハブの家の者の敎にしたがひたれば終に身を滅ぼすに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'アハジアまた彼らの敎にしたがひイスラエルの王アハブの子ヨラムとともにギレアデのラモテにゆきてスリアの王ハザエルと戰ひけるにスリア人ヨラムに傷を負せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, '是においてヨラムはそのスリアの王ハザエルと戰ふにあたりてラムにて負たる傷を療さんとてヱズレルに歸れりユダの王ヨラムの子アザリヤはアハブの子ヨラムが病をるをもてヱズレルに下りてこれを訪ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'アハジアがヨラムを訪ふて害に遇しは神の然らしめたまへるなり即ちアハジアは來り居てヨラムとともに出てニムシの子ヱヒウを迎へたりヱヒウはヱホバが曩にアハブの家を絶去しめんとて膏を沃ぎたまひし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'ヱヒウ、アハブの家を罰するに方りてユダの牧伯等およびアハジアの兄弟等の子等がアハジアに奉へをるに遇て之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'アハジアはサマリヤに匿れたりしがヱヒウこれを探求めければ人々これを執ヘヱヒウの許に曳きたりて之を殺せり但し彼は心を盡してヱホバを求めたるヨシヤパテの子なればとてこれを葬れり斯りしかばアハジアの家は國を統治むる力なくなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, '茲にアハジアの母アタリヤその子の死たるを見て起てユダの家の王子をことごとく滅ぼしたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, '王の女ヱホシバ、アハジアの子ヨアシを王の子等の殺さるる者の中より竊み取り彼とその乳媼を夜衣の室におきて彼をアタリヤに匿したればアタリヤかれを殺さざりきヱホシバはヨラム王の女アハジアの妹にして祭司ヱホヤダの妻なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'かくてヨアシはヱホバの家に匿れて彼らとともにをること六年アタリヤ國に王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, '第七年にいたりヱホヤダ力を強してヱロハムの子アザリヤ、ヨハナンの子イシマエル、オベデの子アザリア、アダヤの子マアセヤ、ジクリの子エシヤパテなどいふ百人の長等を招きて己と契約を結ばしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, '是において彼らユダを行めぐりてユダの一切の邑よりレビ人を集めまたイスラエルの族長を集めてヱルサレムに歸り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, '而してその會衆みな神の家において王と契約を結べり時にヱホヤダかれらに言けるけるはダビデの子孫の事につきてヱホバの宣まひしごとく王の子位に即べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, '然ば汝ら斯なすべし汝ら祭司およびレビ人の安息日に入きたる者は三分の一は門を守り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, '三分の一は王の家に居り三分の一は基礎の門に居り民はみなヱホバの室の庭に居べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, '祭司と奉事をするレビ人の外は何人もヱホバの家に入べからず彼らは聖者なれば入ことを得るなり民はみなヱホバの殿を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'レビ人はおのおの手に武器を執て王を繞りて立べし家に入る者をば凡て殺すべし汝らは王の出る時にも入る時にも王とともに居れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, '是においてレビ人およびユダの人衆は祭司ヱホヤダが凡て命じたる如くに行ひ各々その手の人の安息日に入來べき者と安息日に出ゆくべき者とを率ゐ居れり祭司ヱホヤダ班列の者を去せざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, '祭司ヱホヤダすなはち神の家にあるダビデ王の鎗および大楯小楯を百人の長等に交し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, '一切の民をして各々武器を手に執て王の四周に立ち殿の右の端より殿の左の端におよびて壇と殿にそふて居しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, '斯て人衆王の子を携へ出し之に冠冕を戴かせ證詞をわたして王となし祭司ヱホヤダおよびその子等これに膏をそそげり而して皆王長壽かれと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, '茲にアタリヤ民と近衛兵と王を讃る者との聲を聞きヱホバの室に入て民の所に至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, '視に王は入口にてその柱の傍に立ち王の側に軍長と喇叭手立をり亦國の民みな喜びて喇叭を吹き謳歌者樂を奏し先だちて讃美を歌ひをりしかばアタリヤその衣を裂き叛逆なり叛逆なりと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, '時に祭司ヱホヤダ軍兵を統る百人の長等を呼出してこれに言ふ彼をして列の間を通りて出しめよ凡て彼に從がふ者をば劍をもて殺すべしと祭司は彼をヱホバの室に殺すべからずとて斯いへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, '是をもて之がために路をひらき王の家の馬の門の入口まで往しめて其處にて之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, '斯てヱホヤダ己と一切の民と王との間にわれらは皆ヱホバの民とならんことの契約を結べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, '是において民みなバアルの室にゆきて之を毀ちその壇とその像を打碎きバアルの祭司マツタンを壇の前に殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'ヱホヤダまたヱホバの室の職事を祭司レビ人の手に委ぬ昔ダビデ、レビ人を班列にわかちてヱホバの室におきモーセの律法に記されたる所にしたがひて歓喜と謳歌とをもてヱホバの燔祭を献げしめたりき今このダビデの例に傚ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, '彼またヱホバの室の門々に看守者を立せ置き身の汚れたる者には何によりて汚れたるにもあれ凡て入ことを得ざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, '斯てヱホヤダ百人の長等と貴族と民の牧伯等および國の一切の民を率ゐてヱホバの家より王を導きくだり上の門よりして王の家にいり王を國の位に坐せしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, '斯りしかば國の民みな喜こびて邑は平穩なりきアタリヤは劍にて殺さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'ヨアシは七歳の時位に即きヱルサレムにて四十年の間世を治めたりその母はベエルシバより出たる者にして名をヂビアといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'ヨアシは祭司ヱホヤダの世にある日の間は恒にヱホバの善と觀たまふことを行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'ヱホヤダ彼のために二人の妻を娶れり男子女子生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, '此後ヨアシ、ヱホバの室を修繕んと志し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, '祭司とレビ人を集めて之に言けるは汝ら出てユダの邑々に往き汝らの神ヱホバの室を歳々修繕ふべき金子をイスラエルの人衆より聚むべし其事を亟にせよと然るにレビ人これを亟にせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, '王ヱホヤダ長を召てこれに言けるは汝なんぞレビ人に求めてヱホバの僕モーセおよびイスラエルの會衆の古昔證詞の幕屋のために集めたるが如き税をユダとヱルサレムより取きたらせざるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'かの惡き婦アタリヤの子等神の家を壞りかつヱホバの家の諸の奉納物をバアルに供へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, '是において王の命にしたがひて一箇の匱を作りヱホバの室の門の外にこれを置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'ユダとヱルサレムに宣布て汝ら神の僕モーセが荒野にてイスラエルに課したる如き税をヱホバに携へきたれと言けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, '一切の牧伯等および一切の民みな喜びて携へきたりその匱に投いれて遂に納めをはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'レビ人その匱に金の多くあるを見てこれを王の廳に携へゆく時は王の書記と祭司の長の下役きたりてその匱を傾むけ復これを取て本の處に持ゆけり日々に斯のごとくして金を聚むること夥多し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, '而して王とヱホヤダこれをヱホバの家の工事を爲す者に付し石工および木匠を雇ひてヱホバの室を修繕はせまた鐵工および銅工を雇ひてヱホバの室を修復せしめけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, '工人動作てその工事を成をへ神の室を本の状に復してこれを堅固にす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'その旣に成るにおよびて餘れる金を王とヱホヤダの前に持いたりければ其をもてヱホバの室のために器皿を作れり即ち奉事の器献祭の器および匙ならびに金銀の器を作れりヱホヤダが世に在る日の間はヱホバの室にて燔祭をささぐること絶ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'ヱホヤダは年邁み日滿て死りその死る時は百三十歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, '人衆ダビデの邑にて王等の中間にこれを葬むる其は彼イスラエルの中において神とその殿とにむかひて善事をおこなひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'ヱホヤダの死たる後ユダの牧伯等きたりて王を拝す是において王これに聽したがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, '彼らその先祖の神ヱホバの室を棄てアシラ像および偶像に事へたればその愆のために震怒ユダとヱルサレムに臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'ヱホバかれらを己にひきかへさんとて預言者等を遣はし之にむかひて證をたてさせたまひしかども聽ことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, '是において神の霊祭司ヱホヤダの子ゼカリヤに臨みければ彼民の前に高く起あがりて之に言けるは神かく宣ふ汝らヱホバの誡命を犯して災禍を招くは何ぞや汝らヱホバを棄たればヱホバも汝らを棄たまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, '然るに人衆かれを害せんと謀り王の命によりて石をもてこれをヱホバの室の庭にて撃殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, '斯ヨアシ王はゼカリヤの父ヱホヤダが己にほどこせし恩を念ずしてその子を殺せり彼死る時にヱホバこれを顧みこれを問討したまへと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'かくてその年の終るにおよびてスリアの軍勢かれにむかひて攻のぼりユダとヱルサレムにいたりて民の牧伯等をことごとく民の中より滅ぼし絶ちその掠取物を凡てダマスコの王に遣れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'この時スリアの軍勢は小勢にて來りけるにヱホバ大軍をこれが手に付したまへり是はその先祖の神ヱホバを棄たるが故なり斯かれらヨアシを罰せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'スリア人ヨアシに大傷をおはせて遺去けるがヨアシの臣僕等祭司ヱホヤダの子等の血のために黨をむすびて之に叛き之をその床の上に弑して死しめたり人衆これをダビデの邑に葬れり但し王の墓には葬らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, '黨をむすびて之に叛きし者はアンモンの婦シメアテの子ザバデおよびモアブの婦シムリテの子ヨザバデなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'ヨアシの子等の事ヨアシの告られし預言および神の室を修繕し事などは列王の書の註釋に記さるヨアシの子アマジヤこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'アマジヤは二十五歳の時位に即きヱルサレムにて二十九年の間世を治めたりその母はヱルサレムの者にして名をヱホアダンといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'アマジヤはヱホバの善と視たまふ事を行なひしかども心を全うしてこれを爲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, '彼國のおのが手に堅く立つにおよびてその父王を弑せし臣僕等を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, '然どその子女等をば殺さずしてモーセの書の律法に記せるごとく爲り即ちヱホバ命じて言たまはく父はその子女の故によりて殺さるべからず子女はその父の故によりて殺さるべからず各々おのれの罪によりて殺さるべきなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'アマジヤ、ユダの人を集めその父祖の家にしたがひて或は千人の長に附屬せしめ或に百人の長に附屬せしむユダとベニヤミンともに然り且二十歳以上の者を數へ戈と楯とを執て戰闘に臨む倔強の士三十萬を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'また銀百タラントをもてイスラエルより大勇士十萬を傭へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, '時に神の人かれに詣りて言けるは王よイスラエルの軍勢をして汝とともに往しむる勿れヱホバはイスラエル人すなはちエフライムの子孫とは偕にいまさざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, '汝もし往ば心を強くして戰闘を爲せ神なんぢをして敵の前に斃れしめたまはん神は助くる力ありまた倒す力あるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'アマジヤ神の人にいひけるは然ば已にイスラエルの軍隊に與へたる百タラントを如何にすべきや神の人答へけるはヱホバは其よりも多き者を汝に賜ふことを得るなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, '是においてアマジヤかのエフライムより來りて己に就る軍隊を分離してその處に歸らしめければ彼らユダにむかひて烈しく怒を發し火のごとくに怒りてその處に歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'かくてアマジヤは力を強くしその民を率ゐて鹽の谷に往きセイル人一萬を撃殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'ユダの子孫またこの外に一萬人を生擒て磐の頂に曳ゆき磐の頂よりこれを投おとしければ皆微塵に碎けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, '前にアマジヤが己とともに戰闘に往べからずとして歸し遣たる軍卒等サマリアよりベテホロンまでのユダの邑々を襲ひ人三千を撃ころし物を多く奪ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'アマジヤ、エドム人を戮して歸る時にセイル人の神々を携さへ來り之を安置して己の神となしその前に禮拝をなし之に香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, '是をもてヱホバ、アマジヤにむかひて怒を發し預言者をこれに遣はして言しめたまひけるは彼民の神々は己の民を汝の手より救ふことを得ざりし者なるに汝なにとて之を求むるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, '彼かく王に語れる時王これにむかひ我儕汝を王の議官となせしや止よ汝なんぞ撃殺されんとするやと言ければ預言者すなはち止て言り我知る汝この事を行びて吾諌を聽いれざるによりて神なんぢを滅ぼさんと決めたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, '斯てユダの王アマジヤ相議りて人をヱヒウの子ヱホアハズの子なるイスラエルの王ヨアシに遣し來れ我儕たがひに面をあはせんと言しめければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'イスラエルの王ヨアシ、ユダの王アマジヤに言おくりけるはレバノンの荊蕀かつてレバノンの香柏に汝の女子を我子の妻に與へよと言おくりたること有しにレバノンの野獣とほりてその荊蕀を踏たふせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, '汝はエドム人を撃破れりと謂ひ心にたかぶりて誇る然ば汝家に安んじ居れ何ぞ禍を惹おこして自己もユダもともに亡びんとするやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, '然るにアマジヤ聽ことをせざりき此事は神より出たる者にて彼らをその敵の手に付さんがためなり是は彼らエドムの神々を求めしに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, '是においてイスラエルの王ヨアシ上りきたりユダのベテシメシにてユダの王アマジヤと面をあはせたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'ユダ、イスラエルに撃敗られて各々その天幕に逃かへりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, '時にイスラエルの王ヨアシはヱホアハズの子ヨアシの子なるユダの王アマジヤをベテシメシに執へてヱルサレムに携へゆきヱルサレムの石垣をエフライムの門より隅の門まで四百キユビト程を毀ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'また神の室の中にてオベデエドムが守り居る一切の金銀および諸の器皿ならびに王の家の財寳を取りかつ人質をとりてサマリアに歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'ユダの王ヨアシの子アマジヤはイスラエルの王ヱホアハズの子ヨアシの死てより後なほ十五年生存らへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'アマジヤのその餘の始終の行爲はユダとイスラエルの列王の書に記さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'アマジヤ翻へりてヱホバに從がはずなりし後ヱルサレムにおいて黨を結びて彼に敵する者ありければ彼ラキシに逃ゆきけるにその人々ラキシに人をやりて彼を其處に殺さしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, '人衆これを馬に負せてきたりユダの邑にてその先祖等とともにこれを葬りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, '是においてユダの民みなウジヤをとりて王となしてその父アマジヤに代らしめたり時に年十六なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, '彼エラテの邑を建てこれを再びユダに歸せしむ是はかの王がその先祖等とともに寝りし後なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'ウジヤは十六歳の時位に即きヱルサレムにて五十二年の間世を治めたりその母はヱルサレムの者にして名をヱコリアといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'ウジヤはその父アマジヤが凡てなしたる如くヱホバの善と觀たまふ事を行ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, '神の默示に明なりしかのゼカリヤの世にある日の間心をこめてヱホバを求めたりそのヱホバを求むる間は神これをして幸福ならしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, '彼いでてペリシテ人と戰ひガテの石垣ヤブネの石垣およびアシドドの石垣を圮しアシドドの地ならびにペリシテ人の中間に邑を建つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, '神かれを助けてペリシテ人グルバアルに住むアラビヤ人およびメウニ人を攻撃しめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'アンモニ人はまたウジヤに貢を納るウジヤの名つひにエジプトの入口までも廣まれり其は甚だ強くなりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'ウジヤ、ヱルサレムの隅の門谷の門および角隅に戌樓を建てこれを堅固にし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'また荒野に戌樓を建て許多の水溜を掘り其は家畜を多く有たればなり亦平野にも平地にも家畜を有り又山々およびカルメルには農夫と葡萄を修る者を有り農事を好みたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'ウジヤ戰士一旅團あり書記ヱイエルと牧伯マアセヤの數調査によりて隊々にわかれて戰爭に出づ皆王の軍長ハナニヤの手に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, '大勇士の族長の數は都合二千六百');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'その手に屬する軍勢は三十萬七千五百人みな大なる力をもて戰ひ王を助けて敵に當る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'ウジヤその全軍のために楯戈兜鎧弓および投石器の石を備ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, '彼またヱルサレムにおいて工人に機械を案へ造らしめ之を戌樓および石垣に施こし之をもて矢ならびに大石を射出せり是においてその名遠く廣まれり其は非常の援助を蒙りて旺盛になりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, '然るに彼旺盛になるにおよびその心に高ぶりて惡き事を行なへり即ち彼その神ヱホバにむかひて罪を犯しヱホバの殿に入て香壇の上に香を焚んとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, '時に祭司アザリヤ、ヱホバの祭司たる勇者八十人を率ゐて彼の後にしたがひ入り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'ウジヤ王を阻へてこれに言けるはウジヤよヱホバに香を焚ことは汝のなすべき所にあらずアロンの子孫にして香を焚ために潔められたる祭司等のなすべき所なり聖所より出よ汝は罪を犯せりヱホバ神なんぢに榮を加へたまはじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, '是においてウジヤ怒を發し香爐を手にとりて香を焚んとせしがその祭司にむかひて怒を發しをる間に癩病その額に起れり時に彼はヱホバの室にて祭司等の前にあたりて香壇の側にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, '祭司の長アザリヤおよび一切の祭司等彼を見しに已にその額に癩病生じゐたれば彼を其處より速にいだせり彼もまたヱホバの己を撃たまへるを見て自ら急ぎて出去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'ウジヤ王はその死る日まで癩病人となり居しがその癩病人となるにおよびては別殿に住りヱホバの室より斷れたればなり其子ヨタム王の家を管理て國の民を審判り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'ウジヤのその餘の始終の行爲はアモツの子預言者イザヤこれを書記したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'ウジヤその先祖等とともに寝りたれば彼は癩病人なりとて王等の墓に連接る地にこれを葬りてその先祖等とともならしむその子ヨタムこれに代りて王となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'ヨタムは二十五歳の時位に即きヱルサレムにて十六年の間世を治めたり其母はザドクの女にして名をヱルシヤといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'ヨタムはその父ウジヤの凡て爲たるごとくヱホバの善と視たまふ事をなせり但しヱホバの殿には入ざりき民は尚惡き事を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, '彼ヱホバの家の上の門を建なほしオペルの石垣を多く築き増し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'ユダの山地に數箇の邑を建て林の間に城および戌楼を築けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, '彼アンモニ人の王と戰ひこれに勝り其年アンモンの子孫銀百タラント小麥一萬石大麥一萬石を彼におくれりアンモンの子孫は第二年にも第三年にも是のごとく彼に貢をいる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'ヨタムその神ヱホバの前においてその行を堅うしたるに因て權能ある者となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'ヨタムのその餘の行爲その一切の戰闘およびその行などはイスラエルとユダの列王の書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, '彼は二十五歳の時位に即きヱルサレムにて十六年の間世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'ヨタムその先祖等とともに寝りたればダビデの邑にこれを葬れりその子アハズこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'アハズは二十歳の時位に即きヱルサレムにて十六年の間世を治めたりしがその父ダビデと異にしてヱホバの善と觀たまふ所を行はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'イスラエルの王等の道にあゆみ亦諸のバアルのために像を鋳造り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'ベンヒンノムの谷にて香を焚きその子を火に燒きなどしてヱホバがイスラエルの子孫の前より逐はらひたまひし異邦人の行ふところの憎むべき事に傚ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'また崇邱の上丘の上一切の靑木の下にて犠牲をささげ香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, '是故にその神ヱホバかれをスリアの王の手に付したまひてスリア人つひに彼を撃破りその人々を衆く虜囚としてダマスコに曳ゆけり彼はまたイスラエルの王の手にも付されたればイスラエルの王かれを撃て大にその人を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'すなはちレマリヤの子ペカ、ユダにおいて一日の中に十二萬人を殺せり皆勇士なりき是は彼らその先祖の神ヱホバを棄しによるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'その時にエフライムの勇士ジクリといふ者王の子マアセヤ宮内卿アズリカムおよび王に亞ぐ人エルカナを殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'イスラエルの子孫つひにその兄弟の中より婦人ならびに男子女子など合せて二十萬人を俘擄にしまた衆多の掠取物を爲しその掠取物をサマリアに携へゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, '時に彼處にヱホバの預言者ありその名をオデデといふ彼サマリアに歸れる軍勢の前に進みいでて之に言けるは汝らの先祖の神ヱホバ、ユダを怒りてこれを汝らの手に付したまひしが汝らは天に達するほどの忿怒をもて之を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, '然のみならず汝ら今ユダとヱルサレムの子孫を圧つけて己の奴婢となさんと思ふ然ども汝ら自身もまた汝らの神ヱホバに罪を獲たる身にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, '然ば今我に聽き汝らがその兄弟の中より擄へ來りし俘擄を放ち歸せヱホバの烈しき怒なんぢらの上に臨まんとすればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, '是においてエフライム人の長たる人々すなはちヨハナンの子アザリヤ、メシレモテの子ベレキヤ、シヤルムの子ヒゼキヤ、ハデライの子アマサ等戰爭より歸れる者等の前に立ふさがりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, '之にいひけるは汝ら俘擄を此に曳いるべからず汝らは我らをしてヱホバに愆を得せしめて更に我らの罪愆を増んとす我らの愆は大にして烈しき怒イスラエルにのぞまんとするなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, '是において兵卒等その俘擄と掠取物を牧伯等と全會衆の前に遺おきければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, '上に名を擧げたる人々たちて俘擄を受取り掠取物の中より衣服を取てその裸なる者に着せ之に靴を穿せ食飮を爲しめ膏油を沃ぎ等しその弱き者をば盡く驢馬に乗せ斯して之を棕櫚の邑ヱリコに導きゆきてその兄弟に詣らしめ而してサマリアに歸れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, '當時アハズ王人をアツスリヤの王等に遣はして援助を乞しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, '其はエドム人また來りてユダを攻撃ち民を擄へて去たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'ベリシテ人もまた平野の邑々およびユダの南の邑々を侵してベテシメシ、アヤロン、ゲデロテおよびシヨコとその郷里テムナとその郷里ギムゾとその郷里を取て其處に住めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'イスラエルの王アハズの故をもてヱホバかくユダを卑くしたまふ其は彼ユダの中に淫逸なる事を行ひかつヱホバにむかひて大に罪を犯したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'アツスリヤの王テグラテピレセルは彼の所に來りしかども彼に力をそへずして反てこれを煩はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'アハズ、ヱホバの家と王の家および牧伯等の家の物を取てアツスリヤの王に與へけれどもアハズを援くることをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'このアハズ王はその困難の時に當りてますますヱホバに罪を犯せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, '即ち彼おのれを撃るダマスコの神々に犠牲を献げて言ふスリアの王等の神々はその王等を助くれば我もこれに犠牲を献げん然ば彼ら我を助けんと然れども彼等はかへつてアハズとイスラエル全國を仆す者となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'アハズ神の室の器皿を取聚めて神の室の器皿を切やぶりヱホバの室の戸を閉ぢヱルサレムの隅々に凡て祭壇を造り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'ユダの一切の邑々に崇邱を造りて別神に香を焚き等してその先祖の神ヱホバの忿怒を惹おこせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'アハズのその餘の始終の行爲およびその一切の行跡はユダとイスラエルの列王の書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'アハズその先祖等とともに寝りたればエルサレムの邑にこれを葬れり然どイスラエルの王等の墓にはこれを持ゆかざりき其子ヒゼキヤこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'ヒゼキヤは二十五歳の時位に即きヱルサレムにて二十九年の間世を治めたりその母はゼカリヤの女にして名をアビヤといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'ヒゼキヤはその父ダビデの凡てなしたる如くヱホバの目に善と視たまふ事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, '即ち彼その治世の第一年一月にヱホバの室の戸を開きかつ之を修繕ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, '祭司およびレビ人を携さへいりて東の廣場にこれを集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, '而して之にいひけるはレビ人よ我に聽け汝等いま身を潔めて汝等の先祖の神ヱホバの室を潔め汚穢を聖所より除きされ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, '夫我らの先祖は罪を犯し我らの神ヱホバの目に惡しと見たまふことを行ひてヱホバを棄てヱホバの住所に面を背けて後をこれに向け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'また廊の戸を閉ぢ燈火を消し聖所にてイスラエルの神に香を焚ず燔祭を献けざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, '是をもてヱホバの忿怒ユダとヱルサレムに臨みヱホバ彼等をして打ただよはされしめ詑異とならしめ胡盧とならしめたまへり汝らが目に覩るごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, '即ち我儕の父は劍に斃れ我らの男子女子及び妻等はこれがために俘擄となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, '今我イスラエルの神ヱホバと契約を結ばんとする意志ありその烈しき怒我らを離るることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, '我子等よ今は怠たる勿れヱホバ汝らを擇びて己の前に立て事へしめ己に事ふる者となし香を焚く者となしたまひたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, '是においてレビ人起り即ちコハテの子孫の中にてはアマサイの子マハテおよびアザリヤの子ヨエル、メラリの子孫の中にてはアブデの子キシおよびヱハレレルの子アザリヤ、ゲルシヨン人の中にてはジンマの子ヨアおよびヨアの子エデン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'エリザパンの子孫の中にてはシムリおよびヱイエル、アサフの子孫の中にてはゼカリヤおよびマツタニヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'ヘマンの子孫の中にてはヱヒエルおよびシメイ、ヱドトンの子孫の中にてはシマヤおよびウジエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'かれらその兄弟を集へて身を潔めヱホバの言に依りて王の傳へし命令にしたがひてヱホバの室を潔めんとて入きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, '祭司等ヱホバの室の奧に入りてこれを潔めヱホバの殿にありし汚穢をことごとくヱホバの室の庭に携へいだせばレビ人それを受て外にいだしキデロン河に持いたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, '彼ら正月の元日に潔むることを始めてその月の八日にヱホバの廊におよびまたヱホバの家を潔むるに八日を費し正月の十六日にいたりて之を終れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'かくて彼らヒゼキヤ王の處に入て言ふ我らヱホバの室をことごとく潔めまた燔祭の壇とその一切の器具および供前のパンの案とその一切の器皿とを潔めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'またアハズ王がその治世に罪を犯して棄たりし一切の器皿をも整へてこれを潔めヱホバの壇の前にこれを据置りと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, '是においてヒゼキヤ王蚤に起いで邑の牧伯等をあつめてヱホバの家にのぼり往き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, '牡牛七匹牡羊七匹羔羊七匹牡山羊七匹を牽きたらしめ國と聖所とユダのためにこれを罪祭となしアロンの子孫たる祭司等に命じてこれをヱホバの壇の上に献げしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, '即ち牡牛を宰れば祭司等その血を受て壇に灑ぎまた牡羊を宰ればその血を壇に灑ぎまた羔羊を宰ればその血を壇に灑げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'かくて人々罪祭の牡山羊を王と會衆の前に牽きたりければ彼らその上に手を按り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, '而して祭司これを宰りその血を罪祭として壇の上に献げてイスラエル全國のために贖罪をなせり是は王イスラエル全國の爲に燔祭および罪祭を献ぐることを命じたるに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, '王レビ人をヱホバの室に置きダビデおよび王の先見者ガデと預言者ナタンの命令にしたがひて之に鐃鈸瑟および琴を執しむ是はヱホバがその預言者によりて命じたまひし所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, '是においてレビ人はダビデの樂器をとり祭司は喇叭をとりて立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, '時にヒゼキヤ燔祭を壇の上に献ぐることを命ぜり燔祭をささげ始むるときヱホバの歌をうたひ喇叭を吹きイスラエルの王ダビデの樂器をならしはじめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'しかして會衆みな禮拝をなし謳歌者歌をうたひ喇叭手喇叭を吹ならし燔祭の終るまで凡て斯ありしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, '献ぐる事の終るにおよびて王および之と偕に在る者皆身をかがめて禮拝をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'かくて又ヒゼキヤ王および牧伯等レビ人に命じダビデと先見者アサフの詞をもてヱホバを讃美せしむ彼等喜樂をもて讃美し首をさげて禮拝す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, '時にヒゼキヤこたへて言けるは汝らすでにヱホバに事へんために身を潔めたれば進みよりてヱホバの室に犠牲および感謝祭を携へきたれと會衆すなはち犠牲および感謝祭を携へきたる又志ある者はみな燔祭を携ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, '會衆の携へきたりし燔祭の數は牡牛七十牡羊一百羔羊二百是みなヱホバに燔祭として奉つる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'また奉納物は牛六百羊三千なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, '然るに祭司寡くしてその燔祭の物の皮を剥つくすこと能はざりければその兄弟たるレビ人これを助けてその工を終ふ斯る間に他の祭司等も身を潔むレビ人は祭司よりも心正しくして身を潔めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, '燔祭夥多しくあり酬恩祭の脂及びすべての燔祭の酒も然り斯ヱホバの室の奉事備はれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'この事俄なりしかども神かく民の爲に備をなしたまひしに因てヒゼキヤおよび一切の民喜べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, '茲にヒゼキヤ、イスラエルとユダに遍ねく人を遣しまた書をエフライムとマナセに書おくりヱルサレムなるヱホバの室に來りてイスラエルの神ヱホバに逾越節を行はんことを勸む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, '王すでにその牧伯等およびヱルサレムにある會衆と議り二月をもて逾越節を行はんと定めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, '其は祭司の身を潔めし者足ず民またヱルサレムに集らざりしに因て彼時にこれを行ふことを得ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, '王も會衆もこの事を見て善となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, '即ちこの事を定めてベエルシバよりダンまでイスラエルに遍ねく宣布しめしヱルサレムに來りてイスラエルの神ヱホバに逾越節を行はんことを勸む是はその録されたるごとくにこれを行ふ事久しく無りしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, '飛脚すなはち王とその牧伯等が授けし書をもちてイスラエルとユダを遍ねく行めぐり王の命を傳へて云ふイスラエルの子孫よ汝らアブラハム、イサク、イスラエルの神ヱホバに起歸れ然ばヱホバ、アツスリヤの王等の手より逃れて遺るところの汝らに歸りたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, '汝らの父および兄弟の如くならざれ彼らその先祖の神ヱホバにむかひて罪を犯したればこれを滅亡に就しめたまへり汝らが見るごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, '然ば汝らの父のごとく汝ら項を強くせずしてヱホバに歸服しその永久に聖別たまひし聖所に入り汝らの神ヱホバに事へよ然ればその烈しき怒なんぢらを離れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, '汝ら若ヱホバに歸らば汝らの兄弟および子女その己を擄へゆきし者の前に衿憫を得て遂にまた此國にかへらん汝らの神ヱホバは恩惠あり憐憫ある者にましませば汝らこれに起かへるにおいては面を汝らに背けたまはじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'かくのごとく飛脚エフライム、マナセの國にいりて邑より邑に行めぐりて遂にゼブルンまで至りしが人衆これを嘲り笑へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, '但しアセル、マナセおよびゼブルンの中より身を卑くしてヱルサレムに來りし者もあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'またユダに於ては神その力をいだして人々に心を一にせしめ王と牧伯等がヱホバの言に依て傳へし命令を之に行はしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, '斯りしかば二月にいたりて民酵いれぬバンの節をおこなはんとて多くヱルサレムに來り集れりその會はなはだ大なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, '彼等すなはち起てヱルサレムにある諸の壇を取のぞきまた一切の香壇を取のぞきてこれをキデロン川に投すて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, '二月の十四日に逾越の物を宰れり是において祭司等およびレビ人は自ら恥ぢ身を潔めてヱホバの室に燧祭を携へきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, '神の人モーセの律法に循ひ例に依て各々その所に立ち而して祭司等レビ人の手より血を受て灑げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, '時に會衆の中に未だ身を潔めざる者多かりければレビ人その潔からざる一切の人々に代りて逾越の物を宰りてヱホバに潔め献ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'また衆多の民すたはちエフライム、マナセ、イツサカル、ゼブルンより來りし衆多の者未だ身を潔むる事をせずその書録されし所に違ひて逾越の物を食へり是をもてヒゼキヤこれがために祈りて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, '惠ふかきヱホバよ凡そその心を傾けて神を求めその先祖の神ヱホバを求むる者は假令聖所の潔斎に循はざるとも願くは是を赦したまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'ヱホバ、ヒゼキヤに聽て民を醫したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'ヱルサレムにきたれるイスラエルの子孫は大なる喜悦をいだきて七日の間酵いれぬパンの節をおこなへり又レビ人と祭司は日々にヱホバを讃美し高聲の樂を奏してヱホバを頌へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'ヒゼキヤ、ヱホバの奉事に善通じをる一切のレビ人を深く勞らふ斯人衆酬恩祭を献げその先祖の神ヱホバに感謝して七日のあひだ節の物を食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'かくて又全會あひ議りて更に七日を守らんと決め喜悦をいだきてまた七日を守れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, '時にユダの王ヒゼキヤは牡牛一千羊七千を會衆に餽り又牧伯等は牡牛一千羊一萬を會衆に餽れり祭司もまた衆く身を潔めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'ユダの全會衆および祭司レビ人ならびにイスラエルより來れる全會衆およびイスラエルの地より來れる異邦人とユダに住む異邦人みな喜べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'かくヱルサレムに大なる喜悦ありきイスラエルの王ダビデの子ソロモンの時より以來かくのごとき事ヱルサレムに在ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'この時祭司レビ人起て民を祝しけるにその言聽れその祈祷ヱホバの聖き住所なる天に達せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'この事すべて終りしかば其處に在しイスラエル人みなユダの邑々に出ゆき柱像を碎きアシラ像を斫たふしユダとベニヤミンの全地より崇邱と祭壇を崩し絶ちエフライム、マナセにも及ぼして遂にまつたく之を毀ち而してイスラエルの子孫おのおのその邑々に還りて己の產業にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'ヒゼキヤ祭司およびレビ人の班列を定めその班列にしたがひて各々にその職を行はしむ即ち祭司とレビ人をして燔祭および酬恩祭を献げしめヱホバの營の門において奉事をなし感謝をなし讃美をなさしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'また己の財產の中より王の分を出して燔祭のためにす即ち朝夕の燔祭および安息日朔日節會などの燔祭のために之を出してヱホバの律法に記さるる如くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, '彼またヱルサレムに住む民に祭司とレビ人にその分を與へんことを命ず是かれらをしてヱホバの律法に身を委ねしめんとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, '其命令の傳はるや否やイスラエルの子孫穀物酒油蜜ならびに田野の諸の產物の初を多く献げまた一切の物の什一を夥多しく携へきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'ユダの邑々に住るイスラエルとユダの子孫もまた牛羊の什一ならびにその神ヱホバに納むべき聖物の什一を携へきたりてこれを積疊ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, '三月に之を積疊ぬることを始め七月にいたりて之を終れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'ヒゼキヤおよび牧伯等きたりて其積疊ねたる物を見ヱホバとその民イスラエルを祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'ヒゼキヤその積疊ねたる物の事を祭司とレビ人に問尋ねければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'ザドクの家より出し祭司の長アザリヤ彼に應へて言けるは民ヱホバの室に禮物を携ふることを始めしより以來我儕飽までに食ひしがその餘れる所はなはだ多しヱホバその民をめぐみたまひたればなりその餘れる所かくのごとく夥多しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'ヒゼキヤ、ヱホバの家の内に室を設くることを命じければ則ちこれを設け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, '忠實にその禮物什一および奉納物を携へいれりレビ人コナニヤこれを主どりその兄弟シメイこれに副ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'ヱヒエル、アザジヤ、ナハテ、アサヘル、ヱレモテ、ヨザバデ、ヱリエル、イスマキヤ、マハテ、ベナヤ等ヒゼキヤ王および神の室の宰アザリヤの命に依りコナニヤ及びその兄弟シメイの手下につきてこれが監督者となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, '東の門を守る者レビ人ヱムナの子コレ神に献ぐる誠意よりの禮物を司どりてヱホバの献納物および至聖物を頒つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'その手につく者はエデン、ミニヤミン、ヱシユア、シマヤ、アマリヤおよびシカニヤみな祭司の邑々に居てその職を盡しその兄弟に班列に依て之を頒つ大小ともに均し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, '此外にまた凡て名簿に載たる男子三歳以上にしてヱホバの室に入りその班列にしたがひて日々の職分を盡し擔任の勤務を爲すところの者に之を頒つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'またその宗家にしたがひて名簿に載られその班列にしたがひて擔任の事を執行ふところの祭司および二十歳以上のレビ人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'ならびに名簿に載たるその小き者その妻その男子その女子などに盡く之を頒つ會中すべて然り即ち彼等は潔白忠實にその職を盡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'また邑々の郊地に居るアロンの子孫たる祭司等のためには邑ごとに人を名指し選び祭司の中の一切の男およびレビ人の中の名簿に載せたる一切の者にその分を予へしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'ヒゼキヤ、ユダ全國に斯のごとく爲し善事正き事忠實なる事をその神ヱホバの前に行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, '凡てその神の室の職務につき律法につき誡命につきて行ひ始めてその神を求めし工は悉く心をつくして行ひてこれを成就たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'ヒゼキヤが此等の事を行ひ且つ忠實なりし後アツスリヤの王セナケリブ來りてユダに入り堅固なる邑々にむかひて陣を張り之を攻取んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'ヒゼキヤ、セナケリブの旣に來りヱルサレムに攻むかはんとするを見');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'その牧伯等および勇士等と謀りて邑の外なる一切の泉水を塞がんとす彼等これを助く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, '衆多の民あつまりて一切の泉水および國の中を流れわたる渓河を塞ぎていひけるはアツスリヤの王等來りて水を多く得ば豈で可らんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'ヒゼキヤまた力を強くし破れたる石垣をことごとく建なほして之を戌樓まで築き上げその外にまた石垣をめぐらしダビデの邑のミロを堅くし戈盾を多く造り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, '軍長を多く民の上に立て邑の門の廣場に民を集めてこれを努ひて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '汝ら心を強くし且勇めアツスリヤの王のためにも彼とともなる群衆のためにも懼るる勿れ慄く勿れ我らとともなる者は彼とともになる者よりも多きぞかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, '彼とともなる者は肉の腕なり然れども我らとともなる者は我らの神ヱホバにして我らを助け我らに代りて戰かひたまふべしと民はユダの王ヒゼキヤの言に安んず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, '此後アツスリヤの王セナケリブその全軍をもてラキシを攻圍み居りて臣僕をヱルサレムに遣はしてユダの王ヒゼキヤおよびヱルサレムにをる一切のユダ人に告しめて云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'アツスリヤの王セナケリブかく言ふ汝ら何を恃みてヱルサレムに閉籠りをるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'ヒゼキヤ我らの神ヱホバ、アツスリヤの王の手より我らを救ひ出したまはんと言て汝らを浚かし汝らをして饑渇て死しめんとするに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, '此ヒゼキヤはすなはちヱホバの諸の崇邱と祭壇を取のぞきユダとヱルサレムとに命じて汝らは唯一の壇の前にて崇拝を爲しその上に香を焚べしと言し者にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, '汝らは我およびわが先祖等が諸の國の民に爲したる所を知ざるか其等の國々の民の神少許にてもその國をわが手より救ひ取ることを得しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'わが先祖等の滅ぼし盡せし國民の諸の神の中誰か己の民をわが手より救ひ出すことを得し者あらんや然れば汝らの神いかでか汝らをわが手より救ひいだすことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, '然れば斯ヒゼキヤに欺かるる勿れ浚かさるる勿れまた彼を信ずる勿れ何の民何の國の神もその民を我手または我父祖の手より救ひ出すことを得ざりしなれば况て汝らの神いかでか我手より汝らを救ひ出すことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'セナケリブの臣僕等この外にも多くヱホバ神およびその僕ヒゼキヤを誹れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'セナケリブまた書をかきおくりてイスラエルの神ヱホバを嘲りかつ誹り諸國の民の神々その民をわが手より救ひいださざりし如くヒゼキヤの神もその民をわが手より救ひ出さじと云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, '彼ら遂に大聲を擧げユダヤ語をもて石垣の上なるヱルサレムの民に語ひ之を威しかつ擾せり是は邑を取んとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, '斯かれらはヱルサレムの神を論ずること人の手の作なる地上の民の神々を論ずるがごとくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, '是によりてヒゼキヤ王およびアモツの子預言者イザヤともに祈祷て天に呼はりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'ヱホバ天の使一箇を遣はしてアツスリヤ王の陣營にある一切の大勇士および將官軍長等を絶しめたまへり斯りしかば王面を赧らめて己の國に還りけるがその神の家にいりし時其身より出たる者等劍をもて之を其處に弑せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, '是のごとくヱホバ、ヒゼキヤとヱルサレムの民をアツスリヤの王セナケリブの手および諸人の手より救ひいだし四方において之を守護たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, '是において衆多の人献納物をヱルサレムに携へきたりてヱホバに奉りまた財寳をユダの王ヒゼキヤに餽れり此後ヒゼキヤは萬國の民に尊び見らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, '當時ヒゼキヤ病て死んとせしがヱホバに祈りければヱホバこれに告をなし之に休徴を賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, '然るにヒゼキヤその蒙むりし恩に酬ゆることをせずして心に高ぶりければ震怒これに臨まんとしまたユダとヱルサレムに臨まんとせしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'ヒゼキヤその心に高慢を悔て身を卑くしヱルサレムの民も同じく然なしたるに因てヒゼキヤの世にはヱホバの震怒かれらに臨まざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'ヒゼキヤは富と貴を極め府庫を造りて金銀寶石香物楯および各種の寶貴き器物を蔵め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'また倉廩を造りて穀物酒油などの產物を蔵め圈を造りて種々の家畜を置き牢を造りて羊の群を置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'また許多の邑を設けかつ牛羊を夥多しく有り是は神貨財を甚だ多くこれに賜ひしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'このヒゼキヤまたギホンの水の上の源を塞ぎてこれを下より眞直にダビデの邑の西の方に引り斯ヒゼキヤはその一切の工を善なし就たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, '但しバビロンの君等が使者を遣はしてこの國にありし奇蹟を問しめたる時には神かれを棄おきたまへり是その心に有ところの事を盡く知んがために之を試みたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'ヒゼキヤのその餘の行爲およびその徳行はユダとイスラエルの列王紀の書の中なるアモツの子預言者イザヤの默示の中に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'ヒゼキヤその先祖等と偕に寝りたればダビデの子孫の墓の中なる高き處にこれを葬りユダの人々およびヱルサレムの民みな厚くその死を送れり其子マナセこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'マナセは十二歳の時位に即きヱルサレムにて五十五年の間世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, '彼はヱホバの目に惡と觀たまふことを爲しイスラエルの子孫の前よりヱホバの逐はらひたまひし國人の行ふところの憎むべき事に傚へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, '即ちその父ヒゼキヤの毀ちたりし崇邱を改ため築き諸のバアルのために壇を設けアシラ像を作り天の衆群を拝みて之に事へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'またヱホバが我名は永くヱルサレムに在べしと宣まひしヱホバの室の内に數箇の壇を築き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, '天の衆群のためにヱホバの室の兩の庭に壇を築き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'またベンヒンノムの谷にてその子女に火の中を通らせかつ占卜を行ひ魔術をつかひ禁厭を爲し憑鬼者と卜筮師を取用ひなどしてヱホバの目に惡と視たまふ事を多く行ひてその震怒を惹起せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, '彼またその作りし偶像を神の室に安置せり神此室につきてダビデとその子ソロモンに言たまひし事あり云く我この室と我がイスラエルの諸の支派の中より選びたるヱルサレムとに我名を永く置ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, '彼らもし我が凡て命ぜし事すなはちモーセが傳へし一切の律法と法度と例典を謹みて行はば我が汝らの先祖のために定めし地より我これが足を重てうつさじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'マナセかくユダとヱルサレムの民とを迷はして惡を行はしめたり其状イスラエルの子孫の前にヱホバの滅ぼしたまひし異邦人よりも甚だし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'ヱホバ、マナセおよびその民を諭したまひしかども聽ことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, '是をもてヱホバ、アッスリヤの王の軍勢の諸將をこれに攻來らせたまひて彼等つひにマナセを鉤にて擄へ之を杻械に繋ぎてバビロンに曳ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, '然るに彼患難に罹るにおよびてその神ヱホバを和めその先祖の神の前に大に身を卑くして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, '神に祈りければその祈祷を容れその懇願を聽きこれをヱルサレムに携へかへりて再び國に莅ましめたまへり是によりてマナセ、ヱホバは誠に神にいますと知り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'この後かれダビデの邑の外にてギホンの西の方なる谷の内に石垣を築き魚門の入口までに及ぼし又オベルに石垣を環らして甚だ高く之を築き上げユダの一切の堅固なる邑に軍長を置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'またヱホバの室より異邦の神々および偶像を取除きヱホバの室の山とヱルサレムとに自ら築きし一切の壇を取のぞきて邑の外に投すて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'ヱホバの壇を修復ひて酬恩祭および感謝祭をその上に献げユダに命じてイスラエルの神ヱホバに事へしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, '然れども民は猶崇邱にて犠牲を献ぐることなを爲り但しその神ヱホバに而已なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'マナセのその餘の行爲その神になせし祈祷およびイスラエルの神ヱホバの名をもて彼を諭せし先見者等の言はイスラエルの列王の言行録に見ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'またその祈祷を爲たる事その聽れたる事その諸の罪愆その身を卑くする前に崇邱を築きてアシラ像および刻たる像を立たる處々などはホザイの言行録の中に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'マナセその先祖とともに寝りたれば之をその家に葬れり其子アモンこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'アモンは二十二歳の時位に即きヱルサレムにて二年の間世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, '彼は其父マナセの爲しごとくヱホバの目に惡と觀たまふ事を爲り即ちアモンその父マナセが作りたる諸の刻たる像に犠牲を献げてこれに事へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'その父マナセが身を卑くせしごとくヱホバの前に身を卑くすることを爲ざりき斯このアモン愈その愆を増たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'その臣僕黨を結びて之に叛きこれをその家の内に弑せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, '然るに國の民その黨を結びてアモン王に叛きし者等を盡く誅し而して國の民その子ヨシアを王となしてその後を嗣しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'ヨシアは八歳の時位に即きヱルサレムにて三十一年の間世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, '彼はヱホバの善と觀たまふ事を爲しその父ダビデの道にあゆみて右にも左にも曲らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, '即ち尚若かりしかどもその治世の八年にその父ダビデの神を求むる事を始めその十二年には崇邱アシラ像刻たる像鋳たる像などを除きてユダとヱルサレムを潔むることを始め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, '諸のバアルの壇を己の前にて毀たしめ其上に立る日の像を斫たふしアシラ像および雕像鋳像を打碎きて粉々にし是等に犠牲を献げし者等の墓の上に其を撒ちらし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, '祭司の骨をその諸の壇の上に焚き斯してユダとヱルサレムを潔めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'またマナセ、エフライム、シメオンおよびナフタリの荒たる邑々にも斯なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, '諸壇を毀ちアシラ像および諸の雕像を微塵に打碎きイスラエル全國の日の像を盡く斫たふしてヱルサレムに歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'ヨシアその治世の十八年にいたりて已に國と殿とを潔め了りその神ヱホバの家を修繕はしめんとてアザリヤの子シヤパン邑の知事マアセヤおよびヨアハズの子史官ヨアを遣せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, '彼ら祭司の長ヒルキヤの許に至りてヱホバの室に入し金を交せり是は門守のレビ人がマナセ、エフライムおよび其餘の一切のイスラエル人ならびにユダとベニヤミンの人およびヱルサレムの民の手より斂めたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'やがてヱホバの室を監督するところの工師等の手にこれを交しければ彼等ヱホバの室にて操作ところの工人にこれを交して室を繕ひ修めしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, '即ち木匠および建築者に之を交しユダの王等が壞りたる家々のために琢石および骨木を買しめ梁木をととのはしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'その人々忠實に操作けりその監督者はメラリの子孫たるヤハテ、オバデヤおよびコハテの子孫たるゼカリヤ、メシユラムなどのレビ人なりき彼等すなはち之を主どる又樂器を弄ぶに精巧なるレビ人凡て之に伴なふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, '彼等亦荷を負ものを監督し種々の工事に操作ところの諸の工人をつかさどれり別のレビ人書記となり役人となり門守となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'ヱホバの室にいりし金を取いだすに當りて祭司ヒルキヤ、モーセの傳へしヱホバの律法の書を見いだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'ヒルキヤ是において書記官シヤパンにきて言けるは我ヱホバの室にて律法の書を見いだせりと而してヒルキヤその書をシヤパンに付しければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'シヤパンその書を王の所に持ゆき王に復命まうして言ふ僕等その手に委ねられし所を盡く爲し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'ヱホバの室にありし金を打あけて之を監督者の手および工人の手に交せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, '書記官シヤパン亦王に告て祭司ヒルキヤ我に一の書を交せりと言ひシヤパンそれを王の前に讀けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, '王その律法の言を聞て衣服を裂り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, '而して王ヒルキヤとシヤパンの子アヒカムとミカの子アブドンと書記官シヤパンと王の内臣アサヤとに命じて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '汝ら往てこの見當りし書の言につきて我の爲またイスラエルとユダに遺れる者等のためにヱホバに問へ我らの先祖等はヱホバの言を守らず凡て此書に記されたる所を行ふことを爲ざりしに因てヱホバ我等に大なる怒を斟ぎ給ふべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, '是においてヒルキヤおよび王の人々シヤルムの妻なる女預言者ホルダの許に往りシヤルムはハルハスの子なるテクワの子にして衣裳を守る者なり時にホルダはヱルサレムの第二の邑に住をれり彼等すなはちホルダに斯と語りしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'ホルダこれに答へけるはイスラエルの神ヱホバかく言たまふ汝らを我に遣はせる人に告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'ヱホバかく言たまふユダの王の前に讀し書に記されたる諸の呪詛に循ひて我この處と此に住む者に災害を降さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, '其は彼ら我を棄て他の神に香を焚きおのが手にて作れる諸の物をもて我怒を惹起さんとしたればなりこの故にわが震怒この處に斟ぎて滅ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'されど汝らを遣はしてヱホバに問しむるユダの王には汝ら斯いふべしイスラエルの神ヱホバかく言たまふ汝が聞る言につきては');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, '汝此處と此にすむ者を責る神の言を聞し時に心やさしくして神の前に於て身を卑くし我前に身を卑くし衣服を裂て我前に泣たれば我も汝に聽りとヱホバ宣まふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, '然ば我汝をして汝の先祖等に列ならしめん汝は安然に墓に歸する事を得べし汝は我が此處と此に住む者に降すところの諸の災害を目に見る事あらじと彼等即ち王に復命まうしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, '是において王人を遣はしてユダとヱルサレムの長老をことごとく集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, '而して王ヱホバの室に上りゆけりユダの人々ヱルサレムの民祭司レビ人及び一切の民大より小にいたるまでことごとく之にともなふ王すなはちヱホバの室に見あたりし契約の書の言を盡く彼らの耳に讀聞せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, '而して王己の所に立ちてヱホバの前に契約を立てヱホバにしたがひて歩み心を盡し精神を盡してその誡命と證詞と法度を守り此書にしるされたる契約の言を行はんと言ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'ヱルサレムおよびベニヤミンの有ゆる人々をみな之に加はらしめたりヱルサレムの民すなはちその先祖の神にまします御神の契約にしたがひて行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'かくてヨシア、イスラエルの子孫に屬する一切の地より憎むべき者を盡く取のぞきイスラエルの有ゆる人をしてその神ヱホバに事まつらしめたりヨシアの世にある日の間は彼らその先祖の神ヱホバに從ひて離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, '茲にヨシア、ヱルサレムにおいてヱホバに逾越節を行はんとし正月の十四日に逾越の物を宰らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, '祭司をしてその職を執行はせ之を勵してヱホバの室の務をなさしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'またヱホバの聖者となりてイスラエルの人衆を誨ふるレビ人に言ふ汝らイスラエルの王ダビデの子ソロモンが建たる家に聖契約の匱を放け再び肩に擔ふこと有ざるべし然ば今汝らの神ヱホバおよびその民イスラエルに事ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, '汝らまたイスラエルの王ダビデの書およびその子ソロモンの書に本づきて父祖の家に循がひその班列に依て自ら準備をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, '汝らの兄弟なる民の人々の宗家の區分に循ひて聖所に立ち之にレビ人の宗族の分缺ること無らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, '汝ら逾越の物を宰り身を潔め汝らの兄弟のために準備をなしモーセが傳へしヱホバの言のごとく行ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'ヨシアすなはち羔羊および羔山羊を民の人々に餽る其數三萬また牡牛三千を餽る是みな王の所有の中より出して其處に居る一切の人のために逾越の祭物となせるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'その牧伯等も民と祭司とレビ人に誠意より與ふる所ありまた神の室の長等ヒルキヤ、ゼカリヤ、ヱヒエルも綿羊二千六百牛三百を祭司に與へて逾越の祭物と爲す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'またレビ人の長たる人々すなはちコナニヤおよびその兄弟シマヤ、ネタンエル並にハシヤビヤ、ヱイエル、ヨザバデなども綿羊五千牛五百をレビ人に餽りて逾越の祭物となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, '是のごとく献祭の事備はりぬれば王の命にしたがひて祭司等はその擔任場に立ちレビ人はその班列に循がひ居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'やがて逾越の物を宰りければ祭司その血をこれが手より受て洒げりレビ人その皮を剥り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'かくて燔祭の物を移して民の人々の父祖の家の區分に付してヱホバに献げしむモーセの書に記されたるが如し其牛に行ふところも亦是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, '而して例規のごとくに逾越の物を火にて炙りその他の聖物を鍋釜鼎などに烹て一切の民の人々に奔配れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'かくて後かれら自身のためと祭司等のために備ふ其はアロンの子孫たる祭司等は燔祭と脂を献げて夜に入たればなり是に因て斯レビ人自分のためとアロンの子孫たる祭司等のために備ふるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'アサフの子孫たる謳歌者等はダビデ、アサフ、ヘマンおよび王の先見者ヱドトンの命にしたがひてその擔任場に居り門を守る者等は門々に居てその職務を離るるに及ばざりき其はその兄弟たるレビ人これがために備へたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, '斯のごとく其日ヱホバの献祭の事ことごとく備はりければヨシア王の命にしたがひて逾越節を行ひヱホバの壇に燔祭を献げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, '即ち其處に來れるイスラエルの子孫その時逾越節を行ひ七日の間酵いれぬパンの節を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, '預言者サムエルの日より以來イスラエルにて是のごとくに逾越節を行ひし事なし又イスラエルの諸王の中にはヨシアが祭司レビ人ならびに來りあつまれるユダとイスラエルの諸人およびヱルサレムの民とともに行ひし如き逾越節を行ひし者一人もあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'この逾越節はヨシアの治世の十八年に行ひしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, '是のごとくヨシア殿をととのへし後エジプトの王ネコ、ユフラテの邊なるカルケミシを攻撃んとて上り來りけるにヨシアこれを禦がんとて出往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, '是においてネコ使者をかれに遣はして言ふユダの王よ是あに汝の與る所ならんや今日は汝を攻んとには非ず我敵の家を攻んとするなり神われに命じて急がしむ神われとともにあり汝神に逆ふことを罷よ恐らくは彼なんぢを滅ぼしたまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, '然るにヨシア面を轉して去ことを肯はず却てこれと戰はんとて服装を變へ神の口より出しネコの言を聽いれずしてメギドンの谷に到りて戰ひけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, '射手の者等ヨシア王に射中たれば王その臣僕にむかひて我を扶け出せ我太痍を負ふと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, '是においてその臣僕等かれをその車より扶けおろし其引せたる次の車に乗てヱルサレムにつれゆきけるが遂に死たればその先祖の墓にこれを葬りぬユダとヱルサレムみなヨシアのために哀しめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, '時にヱレミヤ、ヨシアのために哀歌を作れり謳歌男謳歌女今日にいたるまでその哀歌の中にヨシアの事を述べイスラエルの中に之を例となせりその詞は哀歌の中に書さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'ヨシアのその餘の行爲そのヱホバの律法に録されたる所にしたがひて爲し徳行');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'およびその始終の行爲などはイスラエルとユダの列王の書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, '是において國の民ヨシアの子ヱホアハズを取りヱルサレムにてその父にかはりて王とならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'ヱホアハズは二十三歳の時位に即きヱルサレムにて三月が間世を治めけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'エジプトの王ヱルサレムにて彼を廢し且銀百タラント金一タラントの罰金を國に課せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, '而してエジプトの王ネコ彼の兄弟エリアキムをもてユダとヱルサレムの王となして之が名をヱホヤキムと改めその兄弟ヱホアハズを執へてエジプトに曳ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'ヱホヤキムは二十五歳の時位に即きヱルサレムにて十一年の間世を治めその神ヱホバの惡と視たまふことを爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, '彼の所にバビロンの王ネブカデネザル攻のぼりバビロンに曳ゆかんとて之を杻械に繋げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'ネブカデネザルまたヱホバの家の器具をバビロンに携へゆきてバビロンにあるその宮にこれを蔵めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'ヱホヤキムのその餘の行爲その行ひし憎むべき事等およびその心に企みし事などはイスラエルとユダの列王の書に記さる其子ヱホヤキンこれに代りて王となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'ヱホヤキンは八歳の時位に即きヱルサレムにて三月と十日の間世を治めヱホバの惡と視たまふ事を爲けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, '歳の歸るにおよびてネブカデネザル王人を遣はして彼とヱホバの室の貴き器皿とをバビロンに携へいたらしめ之が兄弟ゼデキヤをもてユダとヱルサレムの王となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'ゼデキヤは二十一歳の時位に即きヱルサレムにて十一年の間世を治めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, '彼はその神ヱホバの惡と視たまふ事を爲しヱホバの言を傳ふる預言者ヱレミヤの前に身を卑くせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'ネブカデネザル彼をして神を指て誓はしめたりしにまた之にも叛けり彼かくその項を強くしその心を剛愎にしてイスラエルの神ヱホバに立かへらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, '祭司の長等および民もまた凡て異邦人の中にある諸の憎むべき事に傚ひて太甚しく大に罪を犯しヱホバのヱルサレムに聖め置たまへるその室を汚せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, '其先祖の神ヱホバその民とその住所とを恤むが故に頻りにその使者を遣はして之を諭したまひしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, '彼ら神の使者等を嘲けり其御言を軽んじその預言者等を罵りたればヱホバの怒その民にむかひて起り遂に救ふべからざるに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, '即ちヱホバ、カルデヤ人の王を之に攻きたらせたまひければ彼その聖所の室にて劍をもて少者を殺し童男をも童女をも老人をも白髮の者をも憐まざりき皆ひとしく彼の手に付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, '神の室の諸の大小の器皿ヱホバの室の貨財王とその牧伯等の貨財など凡て之をバビロンに携へゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, '神の室を焚きヱルサレムの石垣を崩しその中の宮殿を盡く火にて焚きその中の貴き器を盡く壞なへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'また劍をのがれし者等はバビロンに擄れゆきて彼處にて彼とその子等の臣僕となりペルシヤの國の興るまで斯てありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, '是ヱレミヤの口によりて傳はりしヱホバの言の應ぜんがためなりき斯この地遂にその安息を享たり即ち是はその荒をる間安息して終に七十年滿ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'ペルシヤ王クロスの元年に當りヱホバ曩にヱレミヤの口によりて傳へたまひしその聖言を成んとてペルシヤ王クロスの心を感動したまひければ王すなはち宣命をつたへ詔書を出して徧く國中に告示して云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'ペルシヤ王クロスかく言ふ天の神ヱホバ地上の諸國を我に賜へりその家をユダのエルサレムに建ることを我に命ず凡そ汝らの中もしその民たる者あらばその神ヱホバの助を得て上りゆけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'ペルシヤ王クロスの元年に當りヱホバ曩にエレミヤの口によりて傳へたまひしその聖言を成んとてペルシヤ王クロスの心を感動したまひければ王すなはち宣命をつたへ詔書を出して徧く國中に告示して云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'ペルシヤ王クロスかく言ふ 天の神ヱホバ地上の諸國を我に賜へり その家をユダのヱルサレムに建ることを我に命ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, '凡そ汝らの中もしその民たる者あらばその神の助を得てユダのヱルサレムに上りゆきヱルサレムなるイスラエルの神ヱホバの室を建ることをせよ 彼は神にましませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'その民にして生存れる者等の寓りをる處の人々は之に金銀貨財家畜を予へて助くべし その外にまたヱルサレムなる神の室のために物を誠意よりささぐべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, '是にユダとベニヤミンの宗家の長祭司レビ人など凡て神にその心を感動せられし者等ヱルサレムなるヱホバの室を建んとて起おこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'その周圍の人々みな銀の器黄金貨財家畜および寳物を予へて之に力をそへこの外にまた各種の物を誠意より獻げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'クロス王またネブカデネザルが前にヱルサレムより携へ出して己の神の室に納めたりしヱホバの室の器皿を取いだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, '即ちペルシヤ王クロス庫官ミテレダテの手をもて之を取いだしてユダの牧伯セシバザルに數へ交付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'その數は是のごとし 金の盤三十 銀の盤一千 小刀二十九');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, '金の大斝三十、二等の銀の大斝四百十 その他の器具一千');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, '金銀の器皿は合せて五千四百ありしがセシバザル俘擄人等をバビロンよりヱルサレムに將て上りし時に之をことごとく携さへ上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, '往昔バビロンの王ネブカデネザルに擄へられバビロンに遷されたる者のうち俘囚をゆるされてヱルサレムおよびユダに上りおのおの己の邑に歸りし此州の者は左の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, '是皆ゼルバベル、ヱシユア、ネヘミヤ、セラヤ、レエラヤ、モルデカイ、ビルシヤン、ミスパル、ビグワイ、レホム、バアナ等に隨ひ來れり 其イスラエルの民の人數は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'パロシの子孫二千百七十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'シパテヤの子孫三百七十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'アラの子孫七百七十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'ヱシユアとヨアブの族たるパハテモアブの子孫二千八百十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'エラムの子孫千二百五十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'ザツトの子孫九百四十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'ザツカイの子孫七百六十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'バニの子孫六百四十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'ベバイの子孫六百二十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'アズガデの子孫千二百二十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'アドニカムの子孫六百六十六人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'ビグワイの子孫二千五十六人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'アデンの子孫四百五十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'ヒゼキヤの家のアテルの子孫九十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'ベザイの子孫三百二十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'ヨラの子孫百十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'ハシユムの子孫二百二十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'ギバルの子孫九十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'ベテレヘムの子孫百二十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'ネトパの人五十六人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'アナトテの人百二十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'アズマウテの民四十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'キリアテヤリム、ケピラおよびベエロテの民七百四十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'ラマおよびゲバの民六百二十一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'ミクマシの人百二十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'ベテルおよびアイの人二百二十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'ネボの民五十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'マグビシの民百五十六人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, '他のエラムの民千二百五十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'ハリムの民三百二十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'ロド、ハデデおよびオノの民七百二十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'ヱリコの民三百四十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'セナアの民三千六百三十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, '祭司はヱシユアの家のヱダヤの子孫九百七十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'インメルの子孫千五十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'パシュルの子孫千二百四十七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'ハリムの子孫千十七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'レビ人はホダヤの子等ヱシユアとカデミエルの子孫七十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, '謳歌者はアサフの子孫百二十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, '門を守る者の子孫はシヤルムの子孫アテルの子孫タルモンの子孫アツクブの子孫ハテタの子孫シヨバイの子孫合せて百三十九人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'ネテニ人はヂハの子孫ハスパの子孫タバオテの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'ケロスの子孫シアハの子孫パドンの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'レバナの子孫ハガバの子孫アツクブの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'ハガブの子孫シヤルマイの子孫ハナンの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'ギデルの子孫ガハルの子孫レアヤの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'レヂンの子孫ネコダの子孫ガザムの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'ウザの子孫パセアの子孫ベサイの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'アスナの子孫メウニムの子孫ネフシムの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'バクブクの子孫ハクパの子孫ハルホルの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'バヅリテの子孫メヒダの子孫ハルシヤの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'バルコスの子孫シセラの子孫テマの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'ネヂアの子孫ハテパの子孫等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'ソロモンの僕たりし者等の子孫すなはちソタイの子孫ハッソペレテの子孫ペリダの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'ヤアラの子孫ダルコンの子孫ギデルの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'シパテヤの子孫ハッテルの子孫ポケレテハツゼバイムの子孫アミの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'ネテニ人とソロモンの僕たりし者等の子孫とは合せて三百九十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'またテルメラ、テルハレサ、ケルブ、アダンおよびインメルより上り來れる者ありしがその宗家の長とその血統とを示してイスラエルの者なるを明かにすることを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, '是すなはちデラヤの子孫トビヤの子孫ネコダの子孫にして合せて六百五十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, '祭司の子孫たる者の中にハバヤの子孫ハッコヅの子孫バルジライの子孫あり バルジライはギレアデ人バルジライの女を妻に娶りてその名を名りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, '是等の者譜系に載たる者等の中におのが名を尋ねたれども在ざりき 是の故に汚れたる者として祭司の中より除かれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'テルシヤタは之に告てウリムとトンミムを帶る祭司の興るまでは至聖物を食ふべからずと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, '會衆あはせて四萬二千三百六十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'この外にその僕婢七千三百三十七人 謳歌男女二百人あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'その馬七百三十六匹 その騾二百四十五匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'その駱駝四百三十五匹 驢馬六千七百二十匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, '宗家の長數人ヱルサレムなるヱホバの室にいたるにおよびてヱホバの室をその本の處に建んとて物を誠意より獻げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, '即ちその力にしたがひて工事のために庫を納めし者は金六萬一千ダリク銀五千斤祭司の衣服百襲なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, '祭司レビ人民等謳歌者門を守る者およびネテニ人等その邑々に住み一切のイスラエル人その邑々に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'イスラエルの子孫かくその邑々に住居しが七月に至りて民一人のごとくにヱルサレムに集まれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, '是に於てヨザダクの子ヱシユアとその兄弟なる祭司等およびシヤルテルの子ゼルバベルとその兄弟等立おこりてイスラエルの神の壇を築けり 是神の人モーセの律法に記されたる所に循ひてその上に燔祭を獻げんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, '彼等は壇をその本の處に設けたり 是國々の民を懼れしが故なり 而してその上にて燔祭をヱホバに獻げ朝夕にこれを獻ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'またその録されたる所に循ひて結茅節を行ひ毎日の分を按へて例に照し數のごとくに日々の燔祭を獻げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, '是より後は常の燔祭および月朔とヱホバの一切のきよき節會とに用ゐる供物ならびに人の誠意よりヱホバにたてまつる供物を獻ぐることをす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, '即ち七月の一日よりして燔祭をヱホバに獻ぐることを始めけるがヱホバの殿の基礎は未だ置ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, '是において石工と木工に金を交付しまたシドンとツロの者に食物飮物および油を與へてペルシヤの王クロスの允准にしたがひてレバノンよりヨツパの海に香柏を運ばしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, '斯てヱルサレムより神の室に歸りたる次の年の二月にシヤルテルの子ゼルバベル、ヨザダクの子ヱシユアおよびその兄弟たる他の祭司レビ人など凡て俘囚をゆるされてヱルサレムに歸りし者等を始め二十歳以上のレビ人を立てヱホバの室の工事を監督せしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, '是に於てユダの子等なるヱシユアとその子等および兄弟カデミエルとその子等齊しく立て神の家の工人を監督せり ヘナダデの子等およびその子等と兄弟等のレビ人も然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'かくて建築者ヱホバの殿の基礎を置る時祭司等禮服を衣て喇叭を執りアサフの子孫たるレビ人鐃鈸を執りイスラエルの王ダビデの例に循ひてヱホバを讃美す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, '彼等班列にしたがひて諸共に歌を謠ひてヱホバを讃めかつ頌へヱホバは恩ふかく其矜恤は永遠にたゆることなければなりと言り そのヱホバを讃美する時に民みな大聲をあげて呼はれり ヱホバの室の基礎を据ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'されど祭司レビ人宗家の長等の中に以前の室を見たりし老人ありけるが今この室の基礎をその目の前に置るを見て多く聲を放ちて泣り また喜悦のために聲をあげて呼はる者も多かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, '是をもて人衆民の歡こびて呼はる聲と民の泣く聲とを聞わくることを得ざりき そは民大聲に呼はり叫びければその聲遠くまで聞えわたりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, '茲にユダとベニヤミンの敵たる者等夫俘囚より歸り來りし人々イスラエルの神ヱホバのために殿を建ると聞き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, '乃ちゼルバベルと宗家の長等の許に至りて之に言けるは我儕をして汝等と共に之を建しめよ 我らは汝らと同じく汝らの神を求む アッスリヤの王エサルハドンが我儕を此に携へのぼりし日より以來我らはこれに犠牲を獻ぐるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, '然るにゼルバベル、ヱシユアおよびその餘のイスラエルの宗家の長等これに言ふ 汝らは我らの神に室を建ることに與るべからず 我儕獨りみづからイスラエルの神ヱホバのために建ることを爲べし 是ペルシヤの王クロス王の我らに命ぜし所なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, '是に於てその地の民ユダの民の手を弱らせてその建築を妨げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, '之が計る所を敗らんために議官に賄賂して之に敵せしむペルシヤ王クロスの世にある日よりペルシヤ王ダリヨスの治世まで常に然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'アハシユエロスの治世すなはち其治世の初に彼ら表を上りてユダとヱルサレムの民を誣訟へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'またアルタシヤスタの世にビシラム、ミテレダテ、タビエルおよびその餘の同僚同じく表をペルシヤの王アルタシヤスタに上つれり その書の文はスリヤの文字にて書きスリヤ語にて陳述たる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, '方伯レホム書記官シムシヤイ書をアルタシヤスタ王に書おくりてヱルサレムを誣ゆ左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, '即ち方伯レホム書記官シムシヤイおよびその餘の同僚デナ人アパルサテカイ人タルペライ人アパルサイ人アルケロイ人バビロン人シユシヤン人デハウ人エラマイ人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'ならびに其他の民すなはち大臣オスナパルが移してサマリアの邑および河外ふのその他の地に置し者等云々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, '其アルタシヤスタ王に上りし書の稿は是なく云く河外ふの汝の僕等云々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, '王知たまへ汝の所より上り來りしユダヤ人ヱルサレムに到りてわれらの中にいりかの背き悖る惡き邑を建なほし石垣を築きあげその基礎を固うせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, '然ば王いま知たまへ 若この邑を建て石垣を築きあげなば彼ら必ず貢賦租税税金などを納じ 然すれば終に王等の不利とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'そもそも我らは王の鹽を食む者なれば王の輕んぜらるるを見るに忍びず 茲に人を遣はし王に奏聞す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, '列祖の記録の書を稽へたまへ必ずその記録の書の中において此邑は背き悖る邑にして諸王と諸州とに害を加へし者なるを見その中に古來叛逆の事ありしを知たまふべし此邑の滅ぼされしは此故に縁るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, '我ら王に奏聞す 若この邑を建て石垣を築きあげなばなんぢは之がために河外ふの領分をうしなふなるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, '王すなはち方伯レホム書記官シムシヤイこの餘サマリアおよび河外ふのほかの處に住る同僚に答書をおくりて云く平安あれ云々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, '汝らが我儕におくりし書をば我前に讀解しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, '我やがて詔書を下して稽考しめしに此邑の古來起りて諸王に背きし事その中に反亂謀叛のありし事など詳悉なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'またヱルサレムには在昔大なる王等ありて河外ふをことごとく治め貢賦租税税金などを己に納しめたる事あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, '然ば汝ら詔言を傳へて其人々を止め我が詔言を下すまで此邑を建ること無らしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, '汝ら愼め 之を爲ことを忽にする勿れ 何ぞ損害を増て王に害を及ぼすべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'アルタシヤスタ王の書の稿をレホム及び書記官シムシヤイとその同僚の前に讀あげければ彼等すなはちヱルサレムに奔ゆきてユダヤ人に就き腕力と權威とをもて之を止めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, '此をもてヱルサレムなる神の室の工事止みぬ 即ちペルシヤ王ダリヨスの治世の二年まで止みたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, '爰に預言者ハガイおよびイドの子ゼカリヤの二人の預言者ユダとヱルサレムに居るユダヤ人に向ひてイスラエルの神の名をもて預言する所ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'シヤルテルの子ゼルバベルおよびヨザダクの子ヱシユア起あがりてヱルサレムなる神の室を建ることを始む 神の預言者等これと共に在て之を助く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'その時に河外の總督タテナイといふ者セタルボズナイおよびその同僚とともにその所に來り誰が汝らに此室を建て此石垣を築きあぐることを命ぜしやと斯言ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'また此建物を建る人々の名は何といふやと斯これに問り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, '然るにユダヤ人の長老等の上にはその神の目そそぎゐたれば彼等これを止むること能はずして遂にその事をダリヨスに奏してその返答の來るを待り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, '河外ふの總督タテナイおよびセタルボズナイとその同僚なる河外ふのアパルサカイ人がダリヨス王に上まつりし書の稿は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, '即ち其上まつりし書の中に書しるしたる所は是のごとし 云く願くはダリヨス王に大なる平安あれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, '王知たまへ我儕ユダヤ州に往てかの大神の室に至り視しに巨石をもて之を建て材木を組て壁を作り居り其工事おほいに捗どりてその手を下すところ成ざる無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, '是に於て我儕その長老等に問てこれに斯いへり 誰が汝らに此室を建てこの石垣を築きあぐることを命ぜしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, '我儕またその首長たる人々の名を書しるして汝に奏聞せんがためにその名を問り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, '時に彼等かく我らに答へて言り 我儕は天地の神の僕にして年久しき昔に建おかれし殿を再び建るなり 是は素イスラエルの大なる王某の建築きたる者なしりが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, '我らの父等天の神の震怒を惹起せしに縁てつひに之をカルデヤ人バビロンの王ネブカデネザルの手に付したまひければ彼この殿を毀ち民をバビロンに擄へゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, '然るにバビロンの王クロスの元年にクロス王神のこの室を建べしとの詔言を下したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, '然のみならず ヱルサレムの殿よりネブカデネザルが取いだしてバビロンの殿に携へいれし神の室の金銀の器皿もクロス王これをバビロンの殿より取いだし其立たる總督セシバザルと名くる者に之を付し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, '而して彼に言けらく是等の器皿を取り往て之をヱルサレムの殿に携へいれ神の室をその本の處に建よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, '是において其セシバザル來りてヱルサレムなる神の室の石礎を置たりき 其時よりして今に至るまで之を建つつありしが猶いまだ竣らざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, '然ば今王もし善となされなば請ふ御膝下バビロンにある所の王の寳蔵を査べたまひて神のこの室を建べしとの詔言のクロス王より出しや否を稽へ而して王此事につきて御旨を我らに諭したまえ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, '是に於てダリヨス王詔言を出しバビロンにて寳物を蔵むる所の文庫に就て査べ稽しめしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'メデア州の都城アクメタにて一の卷物を得たり その内に書しるせる記録は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'クロス王の元年にクロス王詔言を出せり云くヱルサレムなる神の室の事につきて諭す その犠牲を獻ぐる所なる殿を建てその石礎を堅く置ゑ其室の高を六十キユビトにし其濶を六十キユビトにし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, '巨石三行新木一行を以せよ 其費用は王の家より授くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'またネブカデネザルがヱルサレムの殿より取いだしてバビロンに携へきたりし神の室の金銀の器皿は之を還してヱルサレムの殿に持ゆかしめ神の室に置てその故の所にあらしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '然ば河外ふの總督タテナイおよびセタルボズナイとその同僚なる河外ふのアパルサカイ人汝等これに遠ざかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, '神のその室の工事を妨ぐる勿れ ユダヤ人の牧伯とユダヤ人の長老等に神のその家を故の處に建しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, '我また詔言を出し其神の家を建ることにつきて汝らが此ユダヤ人の長老等に爲べきことを示す 王の財寳の中すなはち河外ふの租税の中より迅速に費用をその人々に與へよその工事を滯ほらしむる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, '又その需むる物即ち天の神にたてまつる燔祭の小牛牡羊および羔羊ならびに麥鹽酒油など凡てヱルサレムにをる祭司の定むる所に循ひて日々に怠慢なく彼等に與へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, '彼らをして馨しき香の犠牲を天の神に獻ぐることを得せしめ王とその子女の生命のために祈ることを得せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'かつ我詔言を出す誰にもせよ此言を易る者あらば其家の梁を抜きとり彼を擧て之に釘ん その家はまた之がために厠にせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, '凡そ之を易へまたヱルサレムなるその神の室を毀たんとて手を出す王あるひは民は彼處にその名を留め給ふ神ねがはくはこれを倒したまへ 我ダリヨス詔言を出せり 迅速に之を行なへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'ダリヨス王かく諭しければ河外ふの總督タテナイおよびセタルボズナイとその同僚迅速に之を行なへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'ユダヤ人の長老等すなはち之を建て預言者ハガイおよびイドの子ゼカリヤの預言に由て之を成就たり 彼等イスラエルの神の命に循ひクロス、ダリヨスおよびペルシヤ王アルタシヤスタの詔言に依て之を建竣ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'ダリヨス王の治世の六年アダルの月の三日にこの室成り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, '是に於てイスラエルの子孫祭司レビ人およびその餘の俘擄人よろこびて神のこの室の落成禮を行なへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, '即ち神のこの室の落成禮において牡牛一百牡羊二百 羔羊四百を獻げまたイスラエルの支派の數にしたがひて牡山羊十二を獻げてイスラエル全體のために罪祭となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, '祭司をその分別にしたがひて立て レビ人をその班列にしたがひて立て ヱルサレムに於て神に事へしむ 凡てモーセの書に書しるしたるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, '斯て俘囚より歸り來りし人々正月の十四日に逾越節を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, '即ち祭司レビ人共に身を潔めて皆潔くなり一切俘囚より歸り來りし人々のため其兄弟たる祭司等のため又自己のために逾越の物を宰れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, '擄はれゆきて歸り來しイスラエルの子孫および其國の異邦人の汚穢を棄て是等に附てイスラエルの神ヱホバを求むる者等すべて之を食ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, '喜びて七日の間酵いれぬパンの節を行へり 是はヱホバかれらを喜ばせアッスリヤの王の心を彼らに向はせ彼をしてイスラエルの神にまします神の家の工事を助けさせたまひしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, '是等の事の後ペルシヤ王アルタシヤスタの治世にエズラといふ者あり エズラはセラヤの子セラヤはアザリヤの子アザリヤはヒルキヤの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'ヒルキヤはシヤルムの子シヤルムはザドクの子ザドクはアヒトブの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'アヒトブはアマリヤの子アマリヤはアザリヤの子アザリヤはメラヨテの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'メラヨテはゼラヒヤの子ゼラヒヤはウジの子ウジはブツキの子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'ブツキはアビシユアの子アビシユアはピネハスの子ピネハスはエレアザルの子エレアザルは祭司の長アロンの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, '此エズラ、バビロンより上り來れり 彼はイスラエルの神ヱホバの授けたまひしモーセの律法に精しき學士なりき 其神ヱホバの手これが上にありしに因てその求むる所を王ことごとく許せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'アルタシヤスタ王の七年にイスラエルの子孫および祭司レビ人謳歌者門を守る者ネテニ人など多くヱルサレムに上れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, '王の七年の五月にエズラ、ヱルサレムに到れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, '即ち正月の一日にバビロンを出たちて五月の一日にヱルサレムに至る 其神のよき手これが上にありしに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'エズラは心をこめてヱホバの律法を求め之を行ひてイスラエルの中に法度と例規とを敎へたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'ヱホバの誡命の言に精しく且つイスラエルに賜ひし法度に明かなる學士にて祭司たるエズラにアルタシヤスタ王の與へし書の言は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '諸王の王アルタシヤスタ天の神の律法の學士なる祭司エズラに諭す 願くは全云々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, '我詔言を出す 我國の内にをるイスラエルの民およびその祭司レビ人の中凡てヱルサレムに往んと志す者は皆なんぢと偕に往べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, '汝はおのが手にある汝の神の律法に照してユダとヱルサレムの模樣とを察せんために王および七人の議官に遣はされて往くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, '且汝は王とその議官がヱルサレムに宮居するところのイスラエルの神のために誠意よりささぐる金銀を携へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'またバビロン全州にて汝が獲る一切の金銀および民と祭司とがヱルサレムなる其神の室のために誠意よりする禮物を携さふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, '然ば汝その金をもて牡牛牡羊羔羊およびその素祭と灌祭の品を速に買ひヱルサレムにある汝らの神の室の壇の上にこれを獻ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'また汝と汝の兄弟等その餘れる金銀をもて爲んと欲する所あらば汝らの神の旨にしたがひて之を爲せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'また汝の神の室の奉事のために汝が賜はりし器皿は汝これをヱルサレムの神の前に納めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'その外汝の神の室のために需むる所あらば汝の用ひんとする所の者をことごとく王の府庫より取て用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, '我や我アルタシヤスタ王 河外ふの一切の庫官に詔言を下して云ふ 天の神の律法の學士祭司エズラが汝らに需むる所は凡てこれを迅速に爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, '即ち銀は百タラント小麥は百石酒は百バテ油は百バテ鹽は量なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, '天の神の室のために天の神の命ずる所は凡て謹んで之を行なへ しからずば王とその子等との國に恐くは震怒のぞまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'かつ我儕なんぢらに諭す 祭司レビ人謳歌者門を守る者ネテニ人および神のその室の役者などには貢賦租税税金などを課すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, '汝エズラ汝の手にある汝の神の智慧にしたがひて有司および裁判人を立て河外ふの一切の民すなはち汝の神の律法を知る者等を盡く裁判しめよ 汝らまた之を知ざる者を敎へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, '凡そ汝の神の律法および王の律法を行はざる者をば迅速にその罪を定めて或は殺し或は追放ち或はその貨財を沒収し或は獄に繋ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, '我らの先祖の神ヱホバは讃べき哉 斯王の心にヱルサレムなるヱホバの室を飾る意を起させ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'また王の前とその議官の前と王の大臣の前にて我に矜恤を得させたまへり 我神ヱホバの手わが上にありしに因て我は力を得 イスラエルの中より首領たる人々を集めて我とともに上らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'アルタシヤスタ王の治世に我とともにバビロンより上り來りし者等の宗家の長およびその系譜は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'ピネハスの子孫の中にてはゲルシヨム、イタマルの子孫の中にてはダニエル、ダビデの子孫の中にてはハットシ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'シカニヤの子孫の中パロシの子孫の中にてはゼカリヤ彼と偕にありて名簿に載られたる男子百五十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'パハテモアブの子孫の中にてはゼラヒヤの子エリヨエナイ彼と偕なる男二百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'シカニヤの子孫の中にてはヤハジエルの子 彼と偕なる男三百人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'アデンの子孫の中にてはヨナタンの子エベデ彼とともなる男五十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'エラムの子孫の中にてはアタリヤの子ヱサヤ彼と偕なる男七十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'シパテヤの子孫の中にてはミカエルの子ゼバデヤ彼とともなる男八十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'ヨハブの子孫の中にてはヱヒエルの子オバデヤ彼とともなる男二百十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'シロミテの子孫の中にてはヨシピアの子 彼とともなる男百六十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'ベバイの子孫の中にてはベバイの子ゼカリヤ彼と偕なる男二十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'アズガデの子孫の中にてはハッカタンの子ヨハナン彼とともなる男百十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'アドニカムの子孫の中の後なる者等あり 其名をエリペレテ、ユエル、シマヤといふ彼らと偕なる男六十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'ビグワイの子孫の中にてはウタイおよびザブデ彼等とともなる男七十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, '我かれらをアハワに流るる所の河の邊に集めて三日が間かしこに天幕を張居たりしが我民と祭司とを閲せしにレビの子孫一人も其處に居ざりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'すなはち人を遣てエリエゼル、アリエル、シマヤ、エルナタン、ヤリブ、エルナタン、ナタン、ゼカリヤ、メシユラムなどいふ長たる人々を招きまた敎晦を施こす所のヨヤリブおよびエルナタンを招けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, '而して我カシピアといふ處の長イドの許に彼らを出し遣せり 即ち我カシピアといふ處にをるイドとその兄弟なるネテニ人に告ぐべき詞を之が口に授け我等の神の室のために役者を我儕に携へ來れと言けるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, '我らの神よく我儕を助けたまひて彼等つひにイスラエルの子レビの子マヘリの子孫イシケセルを我らに携さへ來り又セレビヤといふ者およびその子等と兄弟十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'ハシヤビヤならびにメラリの子孫のヱサヤおよびその兄弟とその子等二十人を携へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'またネテニ人すなはちダビデとその牧伯等がレビ人に事へしむるために設けたりしネテニ人二百二十人を携へ來れり 此等の者は皆その名を掲げられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, '斯て我かしこなるアハワの河の邊にて斷食を宣傳へ我儕の神の前にて我儕身を卑し我らと我らの小き者と我らの諸の所有のために正しき途を示されんことを之に求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, '其は我儕さきに王に告て我らの神は己を求むる者を凡て善く助けまた己を棄る者にはその權能と震怒とをあらはしたまふと言しに因て我道路の敵を防ぎて我儕を護るべき歩兵と騎兵とを王に請ふを羞ぢたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'かくてこのことを我ら斷食して我儕の神に求めけるに其祈禱を容たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, '時に我祭司の長十二人即ちセレビヤ、ハシヤビヤおよびその兄弟十人を之とともに擇び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, '金銀および器皿すなはち王とその議官とその牧伯と彼處の一切のイスラエル人とが我らの神の室のために獻げたる奉納物を量りて彼らに付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'その量りて彼らの手に付せし者は銀六百五十タラント銀の器百タラント金百タラントなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'また金の大斝二十あり一千ダリクに當るまた光り輝く精銅の器二箇あり その貴きこと金のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, '而して我かれらに言り汝等はヱホバの聖者なり 此器皿もまた聖し又この金銀は汝らの先祖の神ヱホバに奉まつりし誠意よりの禮物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, '汝等ヱルサレムに至りてヱホバの家の室に於て祭司レビ人の長等およびイスラエルの宗家の首等の前に量るまで之を伺ひ守るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, '是に於て祭司およびレビ人その金銀および器皿をヱルサレムなる我らの神の室に携へゆかんとて其重にしたがひて之を受取れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, '我ら正月の十二日にアハワの河邊を出たちてヱルサレム赴きけるが我らの神その手を我らの上におき我らを救ひて敵の手また路に伏て窺ふ者の手に陷らしめたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, '我儕すなはちヱルサレムに至りて三日かしこに居しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, '四日にいたりて我らの神の室においてその金銀および器皿をウリヤの子祭司メレモテの手に量り付せり ピネハスの子エレアザル彼に副ふ又ヱシユアの子ヨザバデおよびビンヌイの子ノアデヤの二人のレビ人かれらに副ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, '即ちその一々の重と數を査べ其重をことごとく其時かきとめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, '俘囚の人々のその俘囚をゆるされて歸り來し者イスラエルの神に燔祭を獻げたり 即ちイスラエル全體にあたる牡牛十二を獻げまた牡羊九十六羔羊七十七罪祭の牡山羊十二を獻げたり 是みなヱホバにたてまつりし燔祭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, '彼等王の勅諭を王の代官と河外ふの總督等に示しければその人々民を助けて神の室を建しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, '是等の事の成し後牧伯等我許にきたりて言ふ イスラエルの民祭司およびレビ人は諸國の民とはなれずしてカナン人ヘテ人ペリジ人エビス人アンモニ人モアブ人エジプト人アモリ人などの中なる憎むべき事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, '即ち彼等の女子を自ら娶りまたその男子に娶れば聖種諸國の民と相雜れり牧伯たる者 長たる者さきだちてこの愆を犯せりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, '我この事を聞て我衣と袍を裂き頭髮と鬚を抜き驚き呆れて坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'イスラエルの神の言を戰慄おそるる者はみな俘囚より歸り來し者等の愆の故をもて我許に集まりしが我は晩の供物の時まで驚きつつ茫然として坐しぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, '晩の供物の時にいたり我その苦行より起て衣と袍とを裂たるまま膝を屈めてわが神ヱホバにむかひ手を舒て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, '言けるは我神よ我はわが神に向ひて面を擧るを羞て赧らむ 其は我らの罪積りて頭の上に出で我らの愆重りて天に達すればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, '我らの先祖の日より今日にいたるまで我らは大なる愆を身に負り 我らの罪の故によりて我儕と我らの王等および祭司たちは國々の王等の手に付され劍にかけられ擄へゆかれ掠められ面に恥をかうぶれり 今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, '然るに今われらの神ヱホバ暫く恩典を施こして逃れ存すべき者を我らの中に殘し我らをしてその聖所にうちし釘のごとくならしめ斯して我らの神われらの目を明にし我らをして奴隸の中にありて少く生る心地せしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'そもそも我らは奴隸の身なるがその奴隸たる時にも我らの神われらを忘れず反てペルシヤの王等の目の前にて我らに憐憫を施こして我らに活る心地せしめ我らの神の室を建しめ其破壞を修理はしめユダとヱルサレムにて我らに石垣をたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, '我らの神よ已に是のごとくなれば我ら今何と言のべんや 我儕はやくも汝の命令を棄たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, '汝かつて汝の僕なる預言者等によりて命じて宣へり 云く汝らが往て獲んとする地はその各地の民の汚穢により其憎むべき事によりて汚れたる地にして此極より彼極までその汚穢盈わたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, '然ば汝らの女子を彼らの男子に與ふる勿れ 彼らの女子をなんぢらの男子に娶る勿れ 又何時までもかれらの爲に平安をも福祿をも求むべからず 然すれば汝ら旺盛にしてその地の佳物を食ふことを得永くこれを汝らの子孫に傳へて產業となさしむることを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, '我らの惡き行により我らの大なる愆によりて此事すべて我儕に臨みたりしが汝我らの神はわれらの罪よりも輕く我らを罰して我らの中に是のごとく人を遺したまひたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, '我儕再び汝の命令を破りて是等の憎むべき行ある民と縁を結ぶべけんや 汝我らを怒りて終に滅ぼし盡し遺る者も逃るる者も無にいたらしめたまはざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'イスラエルの神ヱホバよ汝は義し 即ち我ら逃れて遺ること今日のごとし 今我ら罪にまとはれて汝の前にあり 是がために一人として汝の前に立ことを得る者なきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'エズラ神の室の前に泣伏して禱りかつ懺悔しをる時に男女および兒女はなはだし多くイスラエルの中より集ひて彼の許に聚り來れり すべての民はいたく泣かなしめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, '時にエラムの子ヱヒエルの子シカニヤ答へてエズラに言ふ 我らはわれらの神に對ひて罪を犯し此地の民なる異邦人の婦女を娶れり 然ながら此事につきてはイスラエルに今なほ望あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, '然ば我儕わが主の敎晦にしたがひ又我らの神の命令に戰慄く人々の敎晦にしたがひて斯る妻をことごとく出し之が產たる者を去んといふ契約を今われらの神に立てん 而して律法にしたがひて之を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, '起よ是事は汝の主どる所なり 我ら汝を助くべし心を強くして之を爲せと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'エズラやがて起あがり祭司の長等レビ人およびイスラエルの人衆をして此言のごとく爲んと誓はしめたり 彼ら乃ち誓へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'かくてエズラ神の家の前より起いでてエリアシブの子ヨハナンの室に入しが彼處に至りてもパンを食ず水を飮ざりき 是は俘囚より歸り來りし者の愆を憂へたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, '斯てユダおよびヱルサレムに遍ねく宣て俘囚の人々に盡く示して云ふ 汝ら皆ヱルサレムに集まるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, '凡そ牧伯等と長老等の諭言にしたがひて三日の内に來らざる者は皆その一切の所有を取あげられ俘擄人の會より黜けらるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, '是においてユダとベニヤミンの人々みな三日の内にヱルサレムに集まれり 是は九月にして恰もその月の廿日なりき 民みな神の室の前なる廣塲に坐して此事のためまた大雨のために震ひ慄けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, '時に祭司エズラ起て之に言けるは汝らは罪を犯し異邦の婦人を娶りてイスラエルの愆を増り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, '然ば今なんぢらのの先祖の神ヱホバに懺悔してその御旨を行へ 即ち汝等この地の民等および異邦の婦人とはなるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, '會衆みな聲をあげて答へて言ふ 汝が我らに諭せるごとく我儕かならず爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, '然ど民は衆し 又今は大雨の候なれば我儕外に立こと能はず 且これは一日二日の事業にあらず 其は我らこの事について大に罪を犯したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, '然ば我らの牧伯等この全會衆のために立れよ 凡そ我儕の邑の内にもし異邦の婦人を娶りし者あらば皆定むる時に來るべし 又その各々の邑の長老および裁判人これに伴ふべし 斯して此事を成ば我らの神の烈しき怒つひに我らを離るるあらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'その時立てこれに逆ひし者はアサヘルの子ヨナタンおよびテクワの子ヤハジア而已メシユラムおよびレビ人シヤベタイこれを贊く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, '俘囚より歸り來りし者つひに然なし 祭司エズラおよび宗家の長數人その宗家にしたがひて名指して撰ばれ十月の一日より共に坐してこの事を査べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, '正月の一日に至りてやうやく異邦の婦人を娶りし人々を盡く査べ畢れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, '祭司の徒の中にて異邦の婦人を娶りし者は即ちヨザダクの子ヱシユアの子等およびその兄弟マアセヤ、エリエゼル、ヤリブ、ゲダリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, '彼らはその妻を出さんといふ誓をなし已に愆を獲たればとて牡羊一匹をその愆のために獻げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'インメルの子孫ハナニおよびゼバデヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'ハリムの子孫マアセヤ、エリヤ、シマヤ、ヱヒエル、ウジヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'パシユルの子孫エリオエナイ、マアセヤ、イシマエル、ネタンエル、ヨザバデ、エラサ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'レビ人の中にてはヨザバデ、シメイ、ケラヤ(即ちケリタ)ペタヒヤ、ユダ、エリエゼル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, '謳歌者の中にてはエリアシブ 門を守る者の中にてはシヤルム、テレムおよびウリ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'イスラエルの中にてはパロシの子孫ラミヤ、エジア、マルキヤ、ミヤミン、エレアザル、マルキヤ、ベナヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'エラムの子孫マッタニヤ、ゼカリヤ、ヱヒエル、アブデ、ヱレモテ、エリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'ザットの子孫エリオエナイ、エリアシブ、マッタニヤ、ヱレモテ、ザバデ、アジザ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'ベバイの子孫ヨハナン、ハナニヤ、ザバイ、アテライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'バニの子孫メシユラム、マルク、アダヤ、ヤシュブ、シヤル、ヱレモテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'パハテモアブの子孫アデナ、ケラル、ベナヤ、マアセヤ、マッタニヤ、ベザレル、ビンヌイ、マナセ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'ハリムの子孫エリエゼル、ヱシヤ、マルキヤ、シマヤ、シメオン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'ベニヤミン、マルク、シマリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'ハシュムの子孫マッテナイ、マツタタ、ザバデ、エリパレテ、ヱレマイ、マナセ、シメイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'バニの子孫マアダイ、アムラム、ウエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'ベナヤ、ベデヤ、ケルヒ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'ワニヤ、メレモテ、エリアシブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'マッタニヤ、マッテナイ、ヤアス');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'バニ、ビンヌイ、シメイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'シレミヤ、ナタン、アダヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'マクナデバイ、シヤシヤイ、シヤライ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'アザリエル、シレミヤ、シマリヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'シヤルム、アマリヤ、ヨセフ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'ネボの子孫ヱイエル、マッタテヤ、ザバデ、ゼビナ、イド、ヨエル、ベナヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, '是みな異邦の婦人を娶りし者なり その婦人の中には子女を產し者もありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'ハカリヤの子ネヘミヤの言詞/第二十年キスレウの月我シユシヤンの都にありける時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'わが兄弟の一人なるハナニ數人の者とともにユダより來りしかば我俘虜人の遺餘なる夫の逃れかへりしユダヤ人の事およびヱルサレムの事を問たづねしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, '彼ら我に言けるは俘虜人の遺餘なる夫の州内の民は大なる患難に遭ひ凌辱に遭ふ又ヱルサレムの石垣は打崩され其門は火に焚たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, '我この言を聞坐りて泣き數日の間哀しみ斷食し天の神に祈りて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, '天の神ヱホバ大なる畏るべき神己を愛し己の誡命を守る者にむかひて契約を保ち恩惠を施こしたまふ者よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'ねがはくは耳を傾むけ目を開きて僕の祈祷を聽いれたまへ我いま汝の僕なるイスラエルの子孫のために日夜なんぢの前に祈り我儕イスラエルの子孫が汝にむかひて犯せし罪を懺悔す誠に我も我父の家も罪を犯せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, '我らは汝にむかひて大に惡き事を行ひ汝の僕モーセに汝の命じたまひし誡命をも法度をも例規をも守らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, '請ふ汝の僕モーセに命じたまひし言を憶ひたまへ其言に云く汝ら若罪を犯さば我汝らを國々に散さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, '然れども汝らもし我にたちかへり我誡命を守りてこれを行なはば暇令逐れゆきて天の涯にをるとも我そこより汝等をあつめ我名を住はせんとて撰びし處にきたらしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'そもそも是等の者は汝が大なる能力と強き手をもて贖ひたまひし汝の僕なんぢの民なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, '主よ請ふ僕の祈祷および汝の名を畏むことを悦こぶ汝の僕等の祈祷に耳を傾けたまへ願くは今日僕を助けて此人の目の前に憐憫を得させたまへこの時我は王の酒人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, '茲にアルタシヤスタ王の二十年ニサンの月王の前に酒のいでし時我酒をつぎて王にたてまつれり我は今まで王の前にて憂色を帶しこと有ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, '王われに言けるは汝は疾病も有ざるに何とて面に憂色を帶るや是他ならず心に憂ふる所あるなりと是において我甚だ大に懼れたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, '遂に王に奏して曰ふ願くは王長壽かれ我が先祖の墓の地たるその邑は荒蕪その門は火にて焚たれば我いかで顔に憂色を帶ざるを得んやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, '王われに向ひて然らば汝何をなさんと願ふやと言ければ我すなはち天の神に祈りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, '王に言けるは王もし之を善としたまひ我もし汝の前に恩を得たる者なりせば願くはユダにあるわが先祖の墓の邑に我を遣はして我にこれを建起さしめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, '時に后妃も傍に坐しをりしが王われに言けるは汝が往てをる間は何程なるべきや何時頃歸りきたるやと王かく我を遣はすことを善としければ我期を定めて奏せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, '而して我また王に言けるは王もし善としたまはば請ふ河外ふの總督等に與ふる書を我に賜ひ彼らをして我をユダまで通さしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'また王の山林を守るアサフに與ふる書をも賜ひ彼をして殿に屬する城の門を作り邑の石垣および我が入べき家に用ふる材木を我に授けしめたまへと我神善く我を助けたまひしに因て王これを我に允せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, '是に於て我河外ふの總督等に詣りて王の書をこれに付せり王は軍長數人に騎兵をそへて我に伴なはせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, '時にホロニ人サンバラテおよびアンモニ人奴隸トビヤこれを聞きイスラエルの子孫の安寧を求むる人來れりとて大に憂ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, '我ついにヱルサレムに到りて彼處に三日居りける後');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, '夜中に起いでたり數人の者われに伴なふ我はわが神がヱルサレムのために爲せんとて我心に入たまひし所の事を何人にも告しらせず亦我が乗る一匹の畜の外には畜を引つれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, '我すなはち夜中に立いで谷の門を通り龍井の對面を經糞門に至りてヱルサレムの石垣を閲せしにその石垣は頽れをりその門は已に火に焚てありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'かくて又前みて泉の門にゆき王の池にいたりしに我が乗る畜の通るべき處なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, '我亦その夜の中に渓川に沿て進みのぼりて石垣を觀めぐり頓て身を反して谷の門より歸りいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, '然るに牧伯等は我が何處に往しか何を爲しかを知ざりき我また未だこれをユダヤ人にも祭司にも貴き人にも方伯等にも其他の役人にも告しらせざりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, '遂に彼らに言けるは汝らの見るごとく我儕の境遇は惡くヱルサレムは荒はてその門は火に焚たり來れ我儕ヱルサレムの石垣を築きあげて再び世の凌辱をうくることなからんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, '而して我わが神の善われを助けたまひし事を彼らに告げまた王の我に語りし言詞をも告しらせければ去來起て築かんと言ひ皆奮ひてこの美事を爲んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, '時にホロニ人サンバラテ、アンモニ人奴隸トビヤおよびアラビヤ人ガシムこれを聞て我らを嘲けり我儕を悔りて言ふ汝ら何事をなすや王に叛かんとするなるかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, '我すなはち答へて彼らに言ふ天の神われらをして志を得させたまはん故に其僕たる我儕起て築くべし然ど汝らはヱルサレムに何の分もなく權理もなく記念もなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, '茲に祭司の長ヱリアシブその兄弟の祭司等とともに起て羊の門を建て之を聖別てその扉を設け尚も之を聖別てハンメアの戌樓に及ぼし又ハナネルの戌樓に及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'その次にはヱリコの人々を築き建て其次にはイムリの子ザツクル築き建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, '魚の門はハツセナアの子等これを建構へその扉を設けて之に鎖と閂を施こせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'その次にはハツコヅの子ウリヤの子メレモタ修繕をなし其次にはメシザベルの子ベレキヤの子メシユラム修繕をなしその次にはバアナの子ザドク修繕をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'その次にはテコア人等修繕をなせり但しその貴き族はその主の工事に服せざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, '古門はパセアの子ヨイアダおよびベソデヤの子メシユラムこれを修繕ひ構へその扉を設けて之に鎖と閂を施せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'その次にはギベオン人メラテヤ、メロノテ人ヤドン河外ふの總督の管轄に屬するギベオンとミヅパの人々等修繕をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'その次にはハルハヤの子ウジエルなどの金工修繕をなし其次には製香者ハナニヤなど修繕をなしヱルサレムを堅うして石垣の廣き處にまで及べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'その次にはエルサレムの郡の半の知事ホルの子レパヤ修繕をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'その次にはハルマフの子ヱダヤ己の家と相對ふ處を修繕りその次にはハシヤブニヤの子ハツトシ修繕をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'ハリムの子マルキヤおよびバハテモアブの子ハシユブも一方を修繕ひまた爐戍樓を修繕へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'その次にはヱルサレムの郡の半の知事ハロヘシの子シヤルムその女子等とともに修繕をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, '谷の門はハヌン、ザノアの民と偕に之を修繕ひ之を建なほしてその扉を設け之に鎖と閂を施しまた糞の門までの石垣一千キユビトを修繕り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, '糞の門はベテハケレムの郡の半の知事レカブの子マルキヤこれを修繕ひ之を建なほしてその扉を設け之に鎖と閂を施こせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, '泉の門はミヅパの郡の知事コロホゼの子シヤルンこれを修繕ひ之を建なほして覆ひその扉を設け之に鎖と閂を施こしまた王の園の邊なるシラの池に沿る石垣を修繕てダビデの邑より下るところの階級にまで及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'その後にはベテズルの郡の半の知事アズブクの子ネヘミヤ修繕をなしてダビデの墓に對ふ處にまで及ぼし堀池に至り勇士宅に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'その後にはバニの子レホムなどのレビ人修繕をなし其次にはケイラの郡の半の知事ハシヤビヤその郡の爲に修繕をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'その後にはケイラの郡の半の知事ヘナダデの子バワイなどいふ其兄弟修繕をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'その次にはヱシユアの子ミヅパの知事エゼル石垣の彎にある武器庫に上る所に對へる部分を修繕ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'その後にはザバイの子バルク力を竭して石垣の彎より祭司の長エリアシブの家の門までの部分を修繕ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'その次にはハツコヅの子ウリヤの子メレモテ、エリアシブの家の門よりエジアシブの家の極までの部分を修繕ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'その次には窪地の人なる祭司等修繕をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'その次にはベニヤミンおよびハシユブ己の家と相對ふ處を修繕ひ其次にはアナニヤの子マアセヤの子アザリヤ己の家に近き處を修繕ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'その次にはヘナダデの子ビンヌイ、アザリヤの家より石垣の彎角までの部分を修繕へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'ウザイの子パラルは石垣の彎に對ふ處および王の上の家より聳え出たる戍樓に對ふ處を修繕り是は侍衛の廳に近し其次にはパロシの子ペダヤ修繕をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '時にネテニ人オペルに住をりて東の方水の門に對ふ處および聳え出たる戍樓に對ふ處まで及べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'その次にはテコア人聳出たる大戍樓に對ふところの部分を修繕てオペルの石垣に及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, '馬の門より上は祭司等おのおのその己の家と相對ふ處を修繕り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'その次にはインメルの子ザドク己の家と相對ふ處を修繕ひ其次にはシカニヤの子シマヤといふ東の門を守る者修繕をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'その次にはシレミヤの子ハナニヤおよびザラフの第六の子ハヌン一方を修繕ひその後にはベレキヤの子メシユラム己の室と相對ふ處を修繕へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'その次には金工の一人マルキヤといふ者ハンミフカデの門と相對ふ處を修繕ひて隅の昇口に至りネテニ人および商人の家に及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'また隅の昇口と羊の門の間は金工および商人等これを修繕へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, '茲にサンバラテわれらが石垣を築くを聞て怒り大に憤ほりてユダヤ人を罵れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, '即ち彼その兄弟等およびサマリアの軍兵の前に語りて言ふ此軟弱しきユダヤ人何を爲や自ら強くせんとするか獻祭をなさんとするか一日に事を終んとするか塵堆の中の石は旣に燬たるに之を取出して活さんとするかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, '時にアンモニ人トビヤその傍にありてまた言ふ彼らの築く石垣は狐上るも圮るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, '我らの神よ聽たまへ我らは侮らる願くは彼らの出す凌辱をその身の首に歸し彼らを他國に擄はれしめ掠られしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, '彼らの愆を蔽ひたまふ勿れ彼らの罪を汝の前より消去しめたまはざれ其は彼ら築建者の前にて汝の怒を惹おこしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, '斯われら石垣を築きけるが石垣はみな已に相連なりてその高さの半にまで及べり其は民心をこめて操作たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, '然るにサンバラテ、トビヤ、アラビヤ人アンモニ人アシドド人等ヱルサレムの石垣改修れ其破壞も次第に塞がると聞て大に怒り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, '皆ともに相結びてヱルサレムに攻來らんとしその中に擾亂をおこさんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, '是において我ら神に祈祷をなしかれらのために日夜守望者を置て之に備ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'ユダ人は言り荷を負ふ者の力衰へしが上に灰土おびただしくして我ら石垣を築くこと能はずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, '我らの敵は言り彼等が知ずまた見ざる間に我ら其中に入り之を殺してその工事を止めんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, '又彼らの邊に住るユダヤ人來る時は我らに告て言ふ汝ら我らの所に歸らざるべからずと其事十次にも及べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, '是に因て我石垣の後の顯露なる低き處に民を置き劍鎗または弓を持せてその宗族にしたがひて之をそなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, '我觀めぐり起て貴き人々および牧伯等ならびにその餘の民に告て云ふ汝ら彼等のために懼るる勿れ主の大にして畏るべきを憶ひ汝らの兄弟のため男子女子のため妻および家のために戰かへよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, '我らの敵おのが事の我らに知れたるをききておのが謀計を神に破られたるを聞しによりて我ら皆石垣に歸り各々その工事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, '其時より後わが僕半は工事に操作き半は鎗楯弓などを持て鎧を着たり牧伯等はユダの全家の後にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, '石垣を築く者および荷を負ひはこぶ者は各々片手もて工事を爲し片手に武器を執り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, '築建者はおのおのその腰に劍を帶て築き建つ又喇叭を吹く者は我傍にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, '我貴き人々および牧伯等ならびにその餘の民に告て云ふ此工事は大にして廣ければ我儕石垣にありて彼此に相離ること遠し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, '何處にもあれ汝ら喇叭の音のきこゆるを聞ば其處に奔あつまりて我らに就け我らの神われらのために戰ひたまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, '我ら斯して工事をなしけるが半の者は東雲の出るより星の現はるるまで鎗を持をれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, '當時われ亦民に言らく皆おのおのその僕とともにヱルサレムの中に宿り夜は我らの防守となり晝は工事をつとむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, '而して我もわが兄弟等もわが僕も我に從がふ防守の人々もその衣服を脱ず水を汲に出るにも皆武器を執れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, '茲に民その妻とともにその兄弟なるユダヤ人にむかひて大に叫べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, '或人言ふ我儕および我らの男子女子は多し我ら穀物を得食ふて生ざるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, '或人は言ふ我らは我らの田畑葡萄園および家をも質となすなり旣に饑に迫れば我らに穀物を獲させよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, '或は言ふ我らは我らの田畝および葡萄園をもて金を貸て王の租税を納む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, '然ど我らの肉も我らの兄弟の肉と同じく我らの子女も彼らの子女と同じ視よ我らは男子女子を人に伏從はせて奴隸となす我らの女子の中すでに人に伏從せし者もあり如何とも爲ん方法なし其は我らの田畝および葡萄園は別の人の有となりたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, '我は彼らの叫および是等の言を聞て大に怒れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, '是において我心に思ひ計り貴き人々および牧伯等を責てこれに言けるは汝らは各々その兄弟より利息を取るなりと而して我かれらの事につきて大會を開き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, '彼らに言けるは我らは異邦人の手に賣れたる我らの兄弟ユダヤ人を我らの力にしたがひて贖へり然るにまた汝等は己の兄弟を賣んとするやいかで之をわれらの手に賣るべけんやと彼らは默して言なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, '我また言けるは汝らの爲すところ善らず汝らは我らの敵たる異邦人の誹謗をおもひて我儕の神を畏れつつ事をなすべきに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, '我もわが兄弟および僕等も同じく金と穀物とを貸て利息を取ことをなす願くは我らこの利息を廢ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, '請ふ汝ら今日にも彼らの田畝葡萄園橄欖園および家を彼らに還しまた彼らに貸あたへて金穀物および酒油などの百分の一を取ることを廢よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, '彼ら即ち言けるは我ら之を還すべし彼らに何をも要めざらん汝の言るごとく我ら然なすべしと是に於て我祭司を呼び彼らをして此言のごとく行なふといふ誓を立しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, '而して我わが胸懐を打拂ひて言ふ此言を行はざる者をば願くは神是のごとく凡て打拂ひてその家およびその業を離れさせたまへ即ちその人は斯打拂はれて空しくなれかしと時に會衆みなアーメンと言てヱホバを讃美せり而して民はこの言のごとくに行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, '且また我がユダの地の總督に任ぜられし時より即ちアルタシヤユタ王の二十年より三十二年まで十二年の間は我もわが兄弟も總督の受べき禄を食ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'わが以前にありし舊の總督等は民に重荷を負せてパンと酒とを是より取り其外にまた銀四十シケルを取れり然のみならずその僕等も亦民を圧せり然ども我は神を畏るるに因て然せざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, '我は反てこの石垣の工事に身を委ね我儕は何の田地をも買しこと無し我僕は皆かしこに集りて工事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, '且また我席にはユダヤ人および牧伯等百五十人あり其外にまた我らの周圍の異邦人の中より我らに來れる者等もありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, '是をもて一日に牛一匹肥たる羊六匹を備へ亦鶏をも許多備へ十日に一回種々の酒を多く備へたり是ありしかどもこの民の役おもきに因て我は總督の受くべき禄を要めざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'わが神よ我が此民のために爲る一切の事を憶ひ仁慈をもて我をあしらひ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'サンバラテ、トビヤおよびアラビヤ人ガシムならびにその餘の我らの敵我が石垣を築き終りて一の破壞も遺らずと聞り(然どその時は未だ門に扉を設けざりしなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, '是においてサンバラテとガシム我に言つかはしけるは來れ我らオノの平野なる某の村にて相會せんとその實は我を害せんと思ひしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, '我すなはち使者を彼らに遣はして言らく我は大なる工事をなし居れば下りゆくことを得ずなんぞ工事を離れ汝らの所に下りゆきてその間工事を休ますべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, '彼ら四次まで是のごとく我に言遣はしけるが我は何時もかくのごとく之に答へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, '是においてサンバラテまた五次目にその僕を前のごとく我に遣はせり其手には封ぜざる書を携さふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'その文に云く國々にて言傳ふガシムもまた然いふ汝はユダヤ人とともに叛かんとして之がために石垣を築けり而して汝はその王とならんとすとその言ところ是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'また汝は預言者を設けて汝の事をヱルサレムに宣しめユダに王ありと言しむといひ傳ふ恐くはその事この言のごとく王に聞えん然ば汝いま來れ我ら共に相議らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, '我すなはち彼に言つかはしけるは汝が言るごとき事を爲し事なし惟なんぢ之を己の心より作りいだせるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, '彼らは皆われらを懼れしめんとせり彼ら謂らく斯なさば彼ら手弱りて工事を息べければ工事成ざるべしと今ねがはくは我手を強くしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'かくて後我メヘタベルの子デラヤの子シマヤの家に往しに彼閉こもり居て言らく我ら神の室に到りて神殿の内に相會し神殿の戸を閉おかん彼ら汝を殺さんとて來るべければなり必ず夜のうちに汝を殺さんとて來るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, '我言けるは我ごとき人いかで逃べけんや我ごとき身にして誰か神殿に入て生命を全うすることを爲んや我は入じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, '我暁れるに神かれを遣はしたまひしに非ず彼が我にむかひて此預言を説しはトビヤとサンバラテ彼に賄賂したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, '彼に賄賂せしは此事のためなり即ち我をして懼れて然なして罪を犯さしめ惡き名を我に負する種を得て我を辱しめんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'わが神よトビヤ、サンバラテおよび女預言者ノアデヤならびにその他の預言者など凡て我を懼れしめんとする者等を憶えてその行爲に報をなしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, '石垣は五十二日を歴てエルルの月の二十五日に成就せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, '我らの敵皆これを聞ければ我らの周圍の異邦人は凡て怖れ大に面目をうしなへり其は彼等この工事は我らの神の爲たまひし者なりと暁りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, '其頃ユダの貴き人々しばしば書をトビヤにおくれりトビヤの書もまた彼らに來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'トビヤはアラの子シカニヤの婿なるをもてユダの中に彼と盟を結べる者多かりしが故なりトビヤの子ヨハナンも亦ベレキヤの子メシユラムの女子を妻に娶りたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, '彼らはトビヤの善行を我前に語りまた我言を彼に通ぜりトビヤは常に書をおくりて我を懼れしめんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, '石垣を築き扉を設け門を守る者謳歌者およびレビ人を立るにおよびて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, '我わが兄弟ハナニおよび城の宰ハナニヤをしてヱルサレムを治めしむ彼は忠信なる人にして衆多の者に超りて神を畏るる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, '我かれらに言ふ日の熱くなるまではヱルサレムの門を啓くべからず人々の立て守りをる間に門を閉させて汝らこれを堅うせよ汝らヱルサレムの民を番兵に立て各々にその所を守らしめ各々にその家と相對ふ處を守らしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, '邑は廣くして大なりしかどもその内の民は寡くして家は未だ建ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, '我神はわが心に貴き人々牧伯等および民を集めてその名簿をしらぶる思念を起さしめたまへり我最先に上り來りし者等の系圖の書を得て見にその中に書しるして曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, '往昔バビロンの王ネブカデネザルに擄へられバビロンに遷されたる者のうち俘囚をゆるされてヱルサレムおよびユダに上りおのおの己の邑に歸りし此州の者は左の如し 是皆ゼルバベル、ヱシユア、ネヘミヤ、アザリヤ、ラアミヤ、ナハマニ、モルデカイ、ビルシヤン、ミスペレテ、ビグワイ、ネホム、バアナ等に隨ひ來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'そのイスラエルの民の人數は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'パロシの子孫二千百七十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'シパテヤの子孫三百七十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'アラの子孫六百五十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'ヱシユアとヨアブの族たるパハテモアブの子孫二千八百十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'エラムの子孫千二百五十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'ザツトの子孫八百四十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'ザツカイの子孫七百六十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'ビンヌイの子孫六百四十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'ベバイの子孫六百二十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'アズガデの子孫二千三百二十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'アドニカムの子孫六百六十七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'ビグワイの子孫二千六十七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'アデンの子孫六百五十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'ヒゼキヤの家のアテルの子孫九十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'ハシユムの子孫三百二十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'ベザイの子孫三百二十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'ハリフの子孫百十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'ギベオンの子孫九十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'ベテレヘムおよびネトパの人百八十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'アナトテの人百二十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'ベテアズマウテの人四十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'キリアテヤリム、ケピラおよびベエロテの人七百四十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'ラマおよびゲバの人六百二十一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'ミクマシの人百二十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'ベテルおよびアイの人百二十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, '他のネボの人五十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, '他のエラムの民千二一百五十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'ハリムの民三百二十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'ヱリコの民三百四十五人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'ロド、ハデデおよびオノの民七百二十一人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'セナアの子孫三千九百三十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, '祭司はヱシユアの家のヱダヤの子孫九百七十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'インメルの子孫千五十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'パシユルの子孫一千二百四十七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'ハリムの子孫一千十七人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'レビ人はホデワの子等ヱシユアとカデミエルの子孫七十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, '謳歌者はアサフの子孫百四十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, '門を守る者はシヤルムの子孫アテルの子孫タルモンの子孫アツクブの子孫ハテタの子孫シヨバイの子孫百三十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'ネテニ人はジハの子孫ハスパの子孫タバオテの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'ケロスの子孫シアの子孫パドンの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'レバナの子孫ハガバの子孫サルマイの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'ハナンの子孫ギデルの子孫ガハルの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'レアヤの子孫レヂンの子孫ネコダの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'ガザムの子孫ウザの子孫パセアの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'ベサイの子孫メウニムの子孫ネフセシムの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'バクブクの子孫ハクパの子孫ハルホルの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'バヅリテの子孫メヒダの子孫ハルシヤの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'バルコスの子孫シセラの子孫テマの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'ネヂアの子孫ハテパの子孫等なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'ソロモンの僕たりし者等の子孫は即ちソタイの子孫ソペレテの子孫ペリダの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'ヤアラの子孫ダルコンの子孫ギデルの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'シパテヤの子孫ハツテルの子孫ポケレテハツゼバイムの子孫アモンの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'ネテニ人とソロモンの僕たりし者等の子孫とは合せて三百九十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'またテルメラ、テルハレサ、ケルブ、アドンおよびインメルより上り來れる者ありしがその宗家とその血統とを示してイスラエルの者なるを明かにすることを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, '是すなはちデラヤの子孫トビヤの子孫ネコダの子孫にして合せて六百四十二人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, '祭司の中にホバヤの子孫ハツコヅの子孫バルジライの子孫ありバルジライはギレアデ人バルジライの女を妻に娶りてその名を名りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, '是等の者系圖に載る者等の中にその籍を尋ねたれども在ざりき是故に汚れたる者として祭司の中より除かれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'テルシヤタ即ち之に告てウリムとトンミムを帶る祭司の興るまでは至聖物を食ふべからずと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, '會衆あはせて四萬二千三百六十人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'この外にその僕婢七千三百三十七人謳歌男女二百四十五人あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'その馬七百三十六匹その騾二百四十五匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, '駱駝四百三十五匹驢馬六千七百二十匹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, '宗家の長の中工事のために物を納めし人々ありテルシヤタは金一千ダリク鉢五十 祭司の衣服五百三十襲を施して庫に納む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'また宗家の長數人は金二萬ダリク銀二千二百斤を工事のために庫に納む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'その餘の民の納めし者は金二萬ダリク銀二千斤祭司の衣服六十七襲なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'かくて祭司レビ人門を守る者謳歌者民等ネテニ人およびイスラエル人すべてその邑々に住り/イスラエルの子孫かくてその邑々に住みをりて七月にいたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, '茲に民みな一人のごとくになりて水の門の前なる廣場に集り學士エズラに請てヱホバのイスラエルに命じたまひしモーセの律法の書を携へきたらんことを求めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'この日すなはち七月一日祭司エズラ律法を携へ來りてその集りをる男女および凡て聽て了ることを得るところの人々の前に至り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, '水の門の前なる廣場にて曙より日中まで男女および了り得る者等の前にこれを誦めり民みな律法の書に耳を傾く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, '學士エズラこの事のために預て設けたる木の臺の上に立たりしがその傍には右の方にマツタテヤ、シマ、アナヤ、ウリヤ、ヒルキヤおよびマアセヤ立をり左の方にペダヤ、ミサエル、マルキヤ、ハシユム、ハシバダナ、ゼカリヤおよびメシユラム立をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'エズラ一切の民の目の前にその書を開けり(彼一切の民より高きところに立たり)かれが開きたる時に民みな起あがれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'エズラすなはち大神ヱホバを祝しければ民みなその手を擧て應へてアーメン、アーメンと言ひ首を下げ地に俯伏てヱホバを拝めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'ヱシユア、バニ、セレビヤ、ヤミン、アツクブ、シヤベタイ、ホデヤ、マアセヤ、ケリタ、アザリヤ、ヨザバテ、ハナン、ペラヤおよびレビ人等民に律法を了らしめたり民はその所に立をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, '彼等その書に就て神の律法を朗かに誦み且その意を解あかしてその誦ところを之に了らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, '時にテルシヤタたるネヘミヤ祭司たる學士エズラおよび民を敎ふるレビ人等一切の民にむかひて此日は汝らの神ヱホバの聖日なり哭くなかれ泣なかれと言り其は民みな律法の言を聽て泣たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, '而して彼らに言けるは汝ら去て肥たる者を食ひ甘き者を飮め而してその備をなし得ざる者に之を分ちおくれ此日は我らの主の聖日なり汝ら憂ふることをせざれヱホバを喜ぶ事は汝らの力なるぞかしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'レビ人も亦一切の民を靜めて言ふ汝ら默せよ此日は聖きぞかし憂ふる勿れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, '一切の民すなはち去りて食ひかつ飮み又人に分ちおくりて大なる喜悦をなせり是はその誦きかされし言を了りしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'その翌日一切の民の族長等祭司およびレビ人等律法の語を學ばんとて學士エズラの許に集り來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, '律法を視るにヱホバのモーセによりて命じたまひし所を録して云く七月の節會にはイスラエルの子孫茅廬に居るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, '又云く一切の邑々及びヱルサレムに布傳へて言べし汝ら山に出ゆき橄欖の枝油木の枝烏拈の枝棕櫚の枝および茂れる木の枝を取きたりて録されたるごとくに茅廬を造れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, '是において民出ゆきて之を取きたり各々その家の屋背の上あるひはその庭あるひは神の室の庭あるひは水の門の廣場あるひはエフライムの門の廣場に茅廬を造れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, '擄はれゆきて歸り來りし會衆みな斯茅廬を造りて茅廬に居りヌンの子ヨシユアの日より彼日までにイスラエルの子孫斯おこなひし事なし是をもてその喜悦はなはだ大なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, '初の日より終の日までエズラ日々に神の律法の書を誦り人衆七日の間節筵をおこなひ第八日にいたり例にしたがひて聖會を開けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'その月の二十四日にイスラエルの子孫あつまりて斷食し麻布を纒ひ土を蒙れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'イスラエルの裔たる者一切の異邦人とはなれ而して立て己の罪と先祖の愆とを懺悔し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, '皆おのおのがその處に立てこの日の四分の一をもてその神ヱホバの律法の書を誦み他の四分の一をもて懺悔をなしその神ヱホバを拝めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, '時にヱシユア、バニ、カデミエル、シバニヤ、ブンニ、セレビヤ、バニ、ケナニ等レビ人の臺に立ち大聲を擧てその神ヱホバに呼はれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, '斯てまたヱシユア、カデミエル、バニ、ハシヤブニヤ、セレビヤ、ホデヤ、セバニヤ、ペタヒヤなどのレビ人言けらく汝ら起あがり永遠より永遠にわたりて在す汝らの神ヱホバを讃よ汝の尊き御名は讃べきかな是は一切の讃にも崇にも遠く超るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, '汝は唯なんぢのみヱホバにまします汝は天と諸天の天およびその萬象地とその上の一切の物ならびに海とその中の一切の物を造り之をことごとく保存せたまふなり天軍なんぢを拝す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, '汝はヱホバ神にまします汝は在昔アブラムを撰みてカルデヤのウルより之を導きいだしアブラハムといふ名をこれにつけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'その心の汝の前に忠信なるを觀そなはし之に契約を立てカナン人ヘテ人アモリ人ペリジ人ヱブス人およびギルガシ人の地をこれに與へその子孫に授けんと宣まひて終に汝の言を成たまへり汝は實に義し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, '汝は我らの先祖がエジプトにて艱難を受るを鑒みその紅海の邊にて呼はり叫ぶを聽いれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, '異兆と奇蹟とをあらはしてパロとその諸臣とその國の庶民とを攻たまへりそはかれらは傲りて我らの先祖等を攻しことを知たまへばなり而して汝の名を揚たまへること尚今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, '汝はまた彼らの前にあたりて海を分ち彼らをして旱ける地を踏て海の中を通らしめ彼らを追ふ者をば石を大水に投いるるごとくに淵に投いれたまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'また晝は雲の柱をもて彼らを導き夜は火の柱をもて其往べき路を照したまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, '汝はまたシナイ山の上に降り天より彼らと語ひ正しき例規および眞の律法善き法度および誡命を之に授け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, '汝の聖安息日を之に示し汝の僕モーセの手によりて誡命と法度と律法を之に命じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, '天より食物を之に與へてその餓をとどめ磐より水を之がために出してその渇を濕し且この國をなんぢらに與へんと手を擧て誓ひ給ひしその國に入これを獲べきことをかれらに命じたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, '然るに彼等すなはち我らの先祖みづから傲りその項を強くして汝の誡命に聽したがはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, '聽從ふことを拒み亦なんぢが其中にて行ひたまひし奇蹟を憶はず還てその項を強くし悖りて自ら一人の首領を立てその奴隸たりし處に歸らんとせり然りと雖も汝は罪を赦す神にして恩惠あり憐憫あり怒ること遅く慈悲厚くましまして彼らを棄たまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'また彼ら自ら一箇の犢を鋳造りて是は汝をエジプトより導き上りし汝の神なりと言て大に震怒をひきおこす事を行ひし時にすら');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, '汝は重々も憐憫を垂て彼らを荒野に棄たまはず晝は雲の柱その上を離れずして之を途に導き夜は火の柱離れずして之を照しその行べき路を示したりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, '汝はまた汝の善霊を賜ひて彼らを訓へ汝のマナを常に彼らの口にあたへまた水を彼らに與へてその渇をとどめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, '四十年の間かれらを荒野に養ひたまたれば彼らは何の缺る所もなくその衣服も古びずその足も腫ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, '而して汝諸國諸民を彼らにあたへて之を各々に分ち取しめ給へりかれらはシホンの地ヘシボンの王の地およびバシヤンの王オグの地を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, '斯てまた汝は彼らの子孫を増て空の星のごなくならしめ前にその先祖等に入て獲よと宣まひたる地に之を導きいりたまひしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, '則ちその子孫入てこの地を獲たり斯て汝この地にすめるカナン人をかれらの前に打伏せその王等およびその國の民をかれらの手に付して意のままに之を待はしめたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, '斯りしかば彼ら堅固なる邑々および膏腴なる地を取り各種の美物の充る家鑿井葡萄園橄欖園および許多の菓の樹を獲乃はち食ひて飽き肥太り汝の大なる恩惠に沾ひて樂みたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, '尚も悖りて汝に叛き汝の律法を後に抛擲ち己を戒しめて汝に歸らせんとしたる預言者等を殺し大に震怒を惹おこす事を行なへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, '是に因て汝かれらをその敵の手に付して窘しめさせたまひしが彼らその艱難の時に汝に呼はりければ汝天より之を聽て重々も憐憫を加へ彼らに救ふ者を多く與へて彼らをその敵の手より救はせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, '然るに彼らは安を獲の後復も汝の前に惡き事を行ひしかば汝かれらをその敵の手に棄おきて敵にこれを治めしめたまひけるが彼ら復立歸りて汝に呼はりたれば汝天よりこれを聽き憐憫を加へてしばしば彼らを助け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, '彼らを汝の律法に引もどさんとして戒しめたまへり然りと雖も彼らは自ら傲りて汝の誡命に聽したがはず汝の例規(人のこれを行はば之によりて生べしといふ者)を犯し肩を聳かし項を強くして聽ことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, '斯りしかど汝は年ひさしく彼らを容しおき汝の預言者等に由て汝の霊をもて彼らを戒めたまひしが彼等つひに耳を傾けざりしに因て彼らを國々の民等の手に付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'されど汝は憐憫おほくして彼らを全くは絶さず亦彼らを棄たまふことをも爲たまはざりき汝は恩惠あり憐憫ある神にましませばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, '然ば我らの神大にして力強く且畏るべくして契約を保ち恩惠を施こしたまふ御神ねがはくはアッスリヤの王等の日より今日にいたるまで我儕の王等牧伯等祭司預言者我らの先祖汝の一切の民等に臨みし諸の苦難を小き事と觀たまはざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, '我らに臨みし諸の事につきては汝義く在せり汝の爲たまひし所は誠實にして我らの爲しところは惡かりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, '我らの王等牧伯等祭司父祖等は汝の律法を行はず汝が用ひて彼らを戒しめたまひしその誡命と證詞に聽從はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, '即ち彼らは己の國に居り汝の賜ふ大なる恩惠に沾ひ汝が與へてその前に置たまひし廣き膏腴なる地にありける時に汝に事ふることを爲ず又ひるがへりて自己の惡き業をやむる事もせざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, '鳴呼われらは今日奴隸たり汝が我らの先祖に與へてその中の產出物およびその中の佳物を食はせんとしたまひし地にて我らは奴隸となりをるこそはかなけれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'この地は汝が我らの罪の故によりて我らの上に立たまひし王等のために衆多の產物を出すなり且また彼らは我らの身をも我らの家畜をも意のままに左右することを得れば我らは大難の中にあるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, '此もろもろの事のために我ら今堅き契約を立てこれを書しるし我らの牧伯等我らのレビ人我らの祭司これに印す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, '印を捺る者はハカリヤの子テルシヤタ、ネヘミヤおよびゼデキヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'セラヤ、アザリヤ、ヱレミヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'パシユル、アマリヤ、マルキヤ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'ハツトシ、シバニヤ、マルク');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'ハリム、メレモテ、オバデヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'ダニエル、ギンネトン、バルク');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'メシユラム、アビヤ、ミヤミン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'マアジア、ビルガ、シマヤ是等は祭司なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'レビ人は即ちアザニヤの子ヱシユア 、ヘナダデの子ビンヌイ、カデミエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'ならびに其兄弟シバ二ヤ、ホデヤ、ケリタ、ペラヤ、ハナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'ミカ、レホブ、ハシヤビヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'ザツクル、セレビヤ、シバ二ヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'ホデヤ、バニ、ベニヌ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, '民の長たる者はパロシ、パハテモアブ、エラム、ザツト、バニ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'ブンニ、アズカデ、ベバイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'アドニヤ、ビグワイ、アデン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'アテル、ヒゼキヤ、アズル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'ホデヤ、ハシユム、ベザイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'ハリフ、アナトテ、ノバイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'マグピアシ、メシユラム、ヘジル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'メシザベル、ザドク、ヤドア');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'ペラテヤ、ハナン、アナニヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'ホセア、ハナニヤ、ハシユブ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'ハロヘシ、ピルハ、シヨベク');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'レホム、ハシヤブナ、マアセヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'アヒヤ、ハナン、アナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'マルク、ハリム、バアナ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'その餘の民祭司レビ人門をまもる者謳歌者ネテニ人ならびに都て國々の民等と離れて神の律法に附る者およびその妻その男子女子など凡そ事を知り辨まふる者は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, '皆その兄弟たる貴き人々に附したがひ呪詛に加はり誓を立て云く我ら神の僕モーセによりて傳はりし神の律法に歩み我らの主ヱホバの一切の誡命およびその例規と法度を守り行はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, '我らは此地の民等に我らの女子を與へじ亦われらの男子のために彼らの女子を娶らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, '比地の民等たとひ貨物あるひは食物を安息日に携へ來りて賣んとするとも安息日または聖日には我儕これを取じ又七年ごとに耕作を廢め一切の負債を免さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, '我らまた自ら例を設けて年々にシケルの三分の一を出して我らの神の室の用となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, '供物のパン常素祭常燔祭のため安息日月朔および節會の祭物のため聖物のためイスラエルの贖をなす罪祭および我らの神の家の諸の工のために之を用ゐることを定む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'また我ら祭司レビ人および民籤を掣き律法に記されたるごとく我らの神ヱホバの壇の上に焚べき薪木の禮物を年々定まれる時にわれらの宗家にしたがひて我らの神の室に納むる者を定め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'かつ誓ひて云ふ我らの產物の初および各種の樹の果の初を年々ヱホバの室に携へきたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'また我らの子等および我らの獣畜の首出および我らの牛羊の首出を律法に記されたるごとく我らの神の室に携へ來りて我らの神の室に事ふる祭司に交し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, '我らの麥粉の初われらの擧祭の物各種の樹の果および洒油を祭司の許に携へ到りて我らの神の家の室に納め我らの產物の什一をレビ人に與へんレビ人は我らの一切の農作の邑においてその什一を受べき者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'レビ人什一を受る時にはアロンの子孫たる祭司一人そのレビ人と偕にあるべし而してまたレビ人はその什一の十分の一を我らの神の家に携へ上りて府庫の諸室に納むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, '即ちイスラエルの子孫およびレビの子孫は穀物および酒油の擧祭を携さへいたり聖所の器皿および奉事をする祭司門を守る者謳歌者などが在るところの室に之を納むべし我らは我らの神の家を棄じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, '民の牧伯等はヱルサレムに住りその餘の民もまた籤を掣き十人の中よりして一人宛を聖邑ヱルサレムに來りて住しめその九人を他の邑々に住しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, '又すべて自ら進でヱルサレムに住んと言ふ人々は民これを祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'イスラエル祭司レビ人ネテニ人およびソロモンの臣僕たりし者等の子孫すべてユダの邑々にありておのおのその邑々なる自己の所有地に住をれり此州の貴き人々のヱルサレムに住をりし者は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, '即ちユダの子孫およびベニヤミンの子孫のヱルサレムに住る者は是なりユダの子孫はウジヤの子アタヤ、ウジヤはゼカリヤの子ゼカリヤはアマリヤの子アマリヤはシパテヤの子シパテヤはマハラレルの子是はペレズの子孫なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, '又バルクの子マアセヤといふ者ありバルクはコロホゼの子コロホゼはハザヤの子ハザヤはアダヤの子アダヤはヨヤリブの子ヨヤリブはゼカリヤの子ゼカリヤはシロニ人の子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'ペレズの子孫のヱルサレムに住る者は合せて四百六十八人にして皆勇士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'ベニヤミンの子孫は左のごとしメシユラムの子サル、メシユラムはヨエデの子ヨエデはペダヤの子ペダヤはコラヤの子コラヤはマアセヤの子マアセヤはイテエルの子イテエルはヱサヤの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'その次はガバイおよびサライなどにして合せて九百二十八人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'ジクリの子ヨエルかれらの監督たりハツセヌアの子ユダこれに副ふて邑を治む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, '祭司はヨヤリブの子ヱダヤ、ヤキン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'および神の室の宰セラヤ、セラヤはヒルヤキの子ヒルキヤはメシユラムの子メシユラムはザドクの子ザドクはメラヨテの子メラヨテはアヒトブの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, '殿の職事をするその兄弟八百二十二人あり又アダヤといふ者ありアダヤはヱロハムの子ヱロハムはペラリヤの子ペラリヤはアムジの子アムジはゼカリヤの子ゼカリヤはパシホルの子パシホルはマルキヤの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'アダヤの兄弟たる宗家の長二百四十二人あり又アマシサイといふ者ありアマシサイはアザリエルの子アザリエルはアハザイの子アハザイはメシレモテの子メシレモテはイシメルの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'その兄弟たる勇士百二十八人ありハツゲドリムの子ザブデエル彼らの監督たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'レビ人はハシユブの子シマヤ、ハシユブはアズリカムの子アズリカムはハシヤビヤの子ハシヤビヤはブンニの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'またシヤベタイおよびヨザバデあり是等はレビ人の長にして神の室の外の事を掌どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'またマツタニヤといふ者ありマツタニヤはミカの子ミカはザブデの子ザブデはアサフの子なりマツタニヤは祈祷の時に感謝の詞を唱へはじむる者なり彼の兄弟の中にてバクブキヤといふ者かれに次り又アブダといふ者ありアブダはシヤンマの子シヤンマはガラルの子ガラルはヱドトンの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, '聖邑にあるレビ人は合せて二百八十四人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, '門を守る者アツクブ、タルモンおよびその兄弟等合せて百七十二人あり皆門々にありて伺守ることをせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'その餘のイスラエル人祭司およびレビ人は皆ユダの一切の邑々にありて各々おのれの產業に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, '但しネテニ人はオペルに居りヂハ及びギシパ、ネタニ人を統ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'ヱルサレムにをるレビ人の監督はウジといふ者なりウジはバニの子バニはハシヤビヤの子ハシヤビヤはマツタニヤの子マツタニヤはミカの子なり是は謳歌者なるアサフの子孫なりその職務は神の室の事にかかはる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, '王より命令ありて是らの事を定め謳歌者に日々の定まれる分を與へしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'ユダの子ゼラの子孫メシザベルの子ペタヒヤといふ者王の手に屬して民に關る一切の事を取あつかへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, '又村荘とその田圃につきてはユダの子孫の者キリアテアルバとその郷里デボンとその郷里およびヱカブジエルとその村荘に住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'ヱシユア、モラダおよびベテペレテに住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'ハザルシユアルおよびベエルシバとその郷里に住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'ヂクラグおよびメコナとその郷里に住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'エンリンモン、ザレア、ヤルムテに住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'ザノア、アドラムおよび其等の村荘ラキシとその田野およびアゼカとその郷里に住り斯かれらはベエルシバよりヒンノムの谷までに天幕を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'ベニヤミンの子孫はまたゲバよりしてミクマシ、アヤおよびベテルとその郷里に住み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'アナトテ、ノブ、アナニヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'ハゾル、ラマ、ギツタイム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'ハデデ、ゼボイム、ネバラテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'ロド、オノ工匠谷に住り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'レビ人の班列のユダにある者の中ベニヤミンに合せし者もありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'シヤルテルの子ゼルバベルおよびヱシユアと偕に上りきたりし祭司とレビ人は左のごとしセラヤ、ヱレミヤ、エズラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'アマリヤ、マルク、ハツトシ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'シカニヤ、レホム、メレモテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'イド、ギンネトイ、アビヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'ミヤミン、マアデヤ、ビルガ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'シマヤ、ヨヤリブ、ヱダヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'サライ、アモク、ヒルキヤ、ヱダヤ是等の者はヱシユアの世に祭司およびその兄弟等の長たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'またレビ人はヱシユア、ビンヌイ、カデミエル、セレビヤ、ユダ、マツタニヤ、マツタニヤはその兄弟とともに感謝の事を掌どれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'またその兄弟バクブキヤおよびウンノ之と相對ひて職務をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'ヱシユア、ヨアキムを生みヨアキム、エリアシブを生みエリアシブ、ヨイアダを生み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'ヨイアダ、ヨナタンを生みヨナタン、ヤドアを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'ヨアキムの日に祭司等の宗家の長たりし者はセラヤの族にてはメラヤ、ヱレミヤの族にてはハナニヤ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'エズラの族にてはメシユラム、アマリヤの族にてはヨハナン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'マルキの族にてはヨナタン、シバニヤの族にてはヨセフ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'ハリムの族にてはアデナ、メラヨテの族にてはヘルカイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'イドの族にではゼカリヤ、ギンネトン膳良にてはメシユラム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'アビヤの族にてはジクリ、ミニヤミンの族モアデヤの族にてはピルタイ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'ビルガの族にてはシヤンマ、シマヤの族にてはヨナタン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'ヨヤリブの族にてはマツテナイ、ヱダヤの族にてはウジ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'サライの族にてはカライ、アモクの族にてはエベル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'ヒルキヤの族にてはハシヤビヤ、ヱダヤの族にてはネタンエル');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'エリアシブ、ヨイアダ、ヨハナンおよびヤドアの日にレビ人の宗家の長等冊に録さる亦ペルシヤ王ダリヨスの治世に祭司等も然せらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, '宗家の長たるレビ人はエリアシブの子ヨハナンの日まで凡て歴代志の書に記さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'レビ人の長はハシヤビヤ、セレビヤおよびカデミエルの子ヱシユアなりその兄弟等これと相對ひて居る即ち彼らは班列と班列とあひむかひ居り神の人ダビデの命令に本づきて讃美と感謝とをつとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'マツタニヤ、バクブキヤ、オバデヤ、メシユラム、タルモン、アツクブは門を守る者にして門の内の府庫を伺ひ守れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, '是等はヨザダクの子ヱシユアの子ヨアキムの日に在り總督ネヘミヤおよび學士たる祭司エズラの日に在りし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'ヱルサレムの石垣の落成せし節會に當りてレビ人をその一切の處より招きてヱルサレムに來らせ感謝と歌と鐃鈸と瑟と琴とをもて歓喜を盡してその落成の節會を行はんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, '是において謳歌ふ徒輩ヱルサレムの周圍の窪地およびネトパ人の村々より集り來り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'またベテギルガルおよびゲバとアズマウテとの野より集り來れりこの謳歌者等はヱルサレムの周圍に己の村々を建たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, '茲に祭司およびレビ人身を潔めまた民および諸の門と石垣とを潔めければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, '我すなはちユダの牧伯等をして石垣の上に上らしめ又二の大なる隊を作り設けて之に感謝の詞を唱へて並進ましむ即ちその一は糞の門を指て石垣の上を右に進めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'その後につきて進める者はホシヤヤおよびユダの牧伯の半');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'ならびにアザリヤ、エズラ、メシユラム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'ユダ、ベニヤミン、シマヤ、ヱレミヤなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, '又祭司の徒數人喇叭を吹て伴ふあり即ちヨナタンの子ゼカリヤ、ヨナタンはシマヤの子シマヤはマツタニヤの子マツタニヤはミカヤの子ミカヤはザツクルの子ザツクルはアサフの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'またゼカリヤの兄弟シマヤ、アザリエル、ミラライ、ギラライ、マアイ、ネタンエル、ユダ、ハナニ等ありて神の人ダビデの樂器を執り學士エズラこれに先だつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, '而して彼ら泉の門を經ただちに進みて石垣の上口に於てダビデの城の段階より登りダビデの家の上を過て東の方水の門に至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'また今一隊の感謝する者は彼らに對ひて進み我は民の半とともにその後に從がへり而して皆石垣の上を行き爐戌樓の上を過て石垣の廣き處にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'エフライムの門の上を通り舊門を過ぎ魚の門およびハナニエルの戌樓とハンメアの戌樓を過て羊の門に至り牢の門に立どまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'かくて二隊の感謝する者神の室にいりて立り我もそこにたち牧伯等の半われと偕にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'また祭司エリアキム、マアセヤ、ミニヤミン、ミカヤ、エリヨエナイ、ゼカリヤ、ハナニヤ等喇叭を執て居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'マアセヤ、シマヤ、エレアザル、ウジ、ヨナハン、マルキヤ、エラム、エゼル之と偕にあり謳歌ふ者聲高くうたへりヱズラヒヤはその監督なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, '斯してその日みな大なる犠牲を献げて喜悦を盡せり其は神かれらをして大に喜こび樂ませたまひたればなり婦女小兒までも喜悦り是をもてヱルサレムの喜悦の聲とほくまで聞えわたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'その日府庫のすべての室を掌どるべき人々を撰びて擧祭の品初物および什一など律法に定むるところの祭司とレビ人との分を邑々の田圃に准ひて取あつめてすべての室にいるることを掌どらしむ是は祭司およびレビ人の立て奉ふるをユダ人喜こびたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, '彼らは神の職守および潔齋の職守を勤む謳歌者および門を守る者も然り皆ダビデとその子ソロモンの命令に依る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, '在昔ダビデおよびアサフの日には謳歌者の長一人ありて神に讃美感謝をたてまつる事ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'またゼルバベルの日およびネヘミヤの日にはイスラエル人みな謳歌者と門を守る者に日々の分を與へまたレビ人に物を聖別て與へレビ人またこれを聖別てアロンの子孫に與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'その日モーセの書を讀て民に聽しめけるに其中に録して云ふアンモニ人およびモアブ人は何時までも神の會に入べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, '是は彼らパンと水とをもてイスラエルの子孫を迎へずして還て之を詛はせんとてバラムを傭ひたりしが故なり斯りしかども我らの神はその呪詛を變て祝福となしたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, '衆人この律法を聞てのち雑りたる民を盡くイスラエルより分ち離てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, '是より先我らの神の家の室を掌れる祭司エリアシブといふ者トビヤと近くなりたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, '彼のために大なる室を備ふ其室は元來素祭の物乳香器皿および例によりてレビ人謳歌者門を守る者等に與ふる穀物酒油の什一ならびに祭司に與ふる擧祭の物を置し處なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, '當時は我ヱルサレムに居ざりき我はバビロンの王アルタシヤスタの三十二年に王の所に往たりしが數日の後王に暇を乞て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'エルサレムに來りエリアシブがトビヤのために爲たる惡事すなはちかれがために神の家の庭に一の室を備へし事を詳悉にせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, '我はなはだこれを憂ひてトビヤの家の器皿をことごとくその室より投いだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, '頓て命じてすべての室を潔めさせ而して神の家の器皿および素祭乳香などを再び其處に携へいれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, '我また査べ觀しにレビ人そのうくべき分を與へられざりきこの故に其職務をなす所のレビ人および謳歌者等各々おのれの田に奔り歸りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, '是において我何故に神の室を棄させしやと言て牧伯等を詰り頓てまたレビ人を招き集めてその故の所に立しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, '斯りしかばユダ人みな穀物酒油の什一を府庫に携へ來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'その時我祭司シレミヤ學士ザドクおよびレビ人ペダヤを府庫の有司とし之にマツタニヤの子ザツクルの子ハナンを副て庫をつかさどらしむ彼らは忠信なる者と思はれたればなり其職は兄弟等に分配るの事なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'わが神よ此事のために我を記念たまへ我神の室とその職事のために我が行ひし善事を拭ひ去たまはざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, '當時われ觀しにユダの中にて安息日に酒榨を踏む者あり麥束を持きたりて驢馬に負するあり亦酒葡萄無花果および各種の荷を安息日にヱルサレムに携へいるるあり我かれらが食物を鬻ぎをる日に彼らを戒しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, '彼處にまたツロの人々も住をりしが魚および各種の貨物を携へいりて安息日にユダの人々に之を鬻ぎかつヱルサレムにて商賣せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, '是において我ユダの貴き人々を詰りて之に言ふ汝ら何ぞ此惡き事をなして安息日を瀆すや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, '汝らの先祖等も斯おこなはざりしや我らの神これが爲にこの一切の災禍を我らとこの邑とに降したまひしにあらずや然るに汝らは安息日を瀆して更に大なる震怒をイスラエルに招くなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, '而して安息日の前の日ヱルサレムの門々暗くならんとする頃ほひに我命じてその扉を閉させ安息日の過さるまで之を開くべからずと命じ我僕數人を門々に置て安息日に荷を携へいるる事なからしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, '斯りしかば商賣および各種の品を賣る者等一二回ヱルサレムの外に宿れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, '我これを戒めてこれに言ふ汝ら石垣の前に宿るは何ぞや汝等もし重ねて然なさば我なんぢらに手をかけんと其時より後は彼ら安息日には來らざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, '我またレビ人に命じてその身を潔めさせ來りて門を守らしめて安息日を聖くす我神よ我ために此事を記念し汝の大なる仁慈をもて我を憫みたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, '當時われアシドド、アンモン、モアブなどの婦女を娶りしユダヤ人を見しに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'その子女はアシドドの言語を半雑へて言ひユダヤの言語を言ことあたはず各國の言語を雑へ用ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, '我彼等を詰りまた詬りその中の數人を撻ちその毛を抜き神を指て誓はしめて言ふ汝らは彼らの男子におのが女子を與ふべからず又なんぢらの男子あるひはおのれ自身のために彼らの女子を娶るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, '是らの事についてイスラエルの王ソロモンは罪を獲たるに非ずや彼がごとき王は衆多の國民の中にもあらずして神に愛せられし者なり神かれをイスラエル全國の王となしたまへり然るに尚ほ異邦の婦女等はこれに罪を犯さしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, '然ば汝らが異邦の婦女を娶りこの一切の大惡をなして我らの神に罪を犯すを我儕聽し置べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, '祭司の長エリアシブの子ヨイアダの一人の子はホロニ人サンバラテの婿なりければ我これを逐出して我を離れしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'わが神よ彼らは祭司の職を汚し祭司およびレビ人の契約に背きたり彼らのことを忘れたまふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, '我かく人衆を潔めて異邦の物を盡く棄しめ祭司およびレビ人の班列を立て各々その職務に服せしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'また人衆をして薪柴の禮物をその定まる期に献げしめかつ初物を奉つらしむ我神よ我を憶ひ仁慈をもて我を待ひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'アハシユエロスすなはち印度よりエテオピヤまで百二十七州を治めたるアハシユエロスの世');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'アハシユエロス王シユシヤンの城にてその國の祚に坐しをりける当時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'その治世の第三年にその牧伯等および臣僕等のために酒宴を設けたり ペルシヤとメデアの武士および貴族と諸州の牧伯等その前にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, '時に王その盛なる國の富有とその大なる威光の榮を示して衆多の日をわたり百八十日に及びぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'これらの日のをはりし時王また王の宮の園の庭にてシユシヤンに居る大小のすべての民のために七日の間酒宴を設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, '白緑靑の帳幔ありて細布と紫色の紐にて銀の環および蝋石の柱に繋がるまた牀榻は金銀にして赤白黄黑の蝋石の上に居らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, '金の酒盃にて酒を賜ふその酒盃は此と彼おのおの異なり王の用ゐる酒をたまふこと夥だし王の富有に適へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'その飮むことは法にかなひて誰も強ることを爲ず 其は王人として各々おのれの好むごとく爲しむべしとその宮内のすべての有司に命じたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, '后ワシテもまたアハシユエロス王に屬する王宮の内にて婦女のために酒宴をまうけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, '第七日にアハシユエロス王酒のために心樂み王の前に事ふる七人の侍從メホマン、ビスタ、ハルボナ、ビグタ、アバグタ、セタルおよびカルカスに命じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, '后ワシテをして后の冠冕をかぶりて王の前に來らしめよと言り 是は彼觀に美しければその美麗を民等と牧伯等に見さんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'しかるに后ワシテ侍從が傳へし王の命に從ひて來ることを肯はざりしかば王おほいに憤ほりて震怒その衷に燃ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, '是において王時を知る智者にむかひて言ふ(王はすべて法律と審理に明かなる者にむかひて是の如くするを常とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, '時に彼の次にをりし者はペルシヤおよびメデアの七人の牧伯カルシナ、セタル、アデマタ、タルシシ、メレス、マルセナ、メムカンなりき 是みな王の面を見る者にして國の第一に位せり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '后ワシテ、アハシユエロス王が侍從をもて傳へし命を爲ざれば法律にしたがひて如何に彼になすべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'メムカン王と牧伯たちの前に答へて曰ふ 后ワシテは唯王にむかひて惡き事をなしたる而已ならず一切の牧伯たちおよびアハシユエロス王の各州のもろもろの民にむかひてもまた之を爲るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, '后のこの事あまねく一切の婦女に聞えて彼らつひにその夫を藐め觀て言ん アハシユエロス王后ワシテに己のまへに來れと命じたりしに來らざりしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, '而して后の此所行を聞るペルシヤとメデアの諸夫人もまた今日王のすべての牧伯等に是のごとく言ん然すれば必らず藐視と忿怒多く起るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, '王もし之を善としたまはばワシテは此後ふたたびアハシユエロス王の前に來るべからずといふ王命を下し之をペルシヤとメデアの律法の中に書いれて更ること無らしめ而してその后の位を彼に勝れる他の者に與へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, '王の下したまはん御詔この大なる御國に徧ねく聞えわたる時は妻たる者ことごとくその夫を大小となく共に敬まふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, '王と牧伯等この言を善としければ王メムカンの言のごとく爲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'かくて王の諸州に徧ねく書をおくりもろもろの州にその文字にしたがひて書おくりもろもろの民にその言語にしたがひて書おくり凡て男子たる者はその家の主となるべくまたおのれの民の言を用ひてものいふべしと諭しぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'これらの事の後アハシユエロス王忿怒とけてワシテおよび彼が爲たる所またその彼にむかひて議定めしところの事を憶ひおこせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'ここに王の前に事ふる僕等いひけるは請ふ美しき少き處女等を王のために尋もとめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, '願はくは王御國の各州において官吏を擇び之をして美はしき處女をことごとくシユシヤンの城に集めしめ婦人を管理る王の侍從ヘガイの手にわたして婦人の局に入らしめ而して潔淨の物をこれに與へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, '斯して王の御意に適ふ女子を取りワシテに代りて后とならしめたまへと王この事を善として然なしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, '茲にシユシヤンの城に一人のユダヤ人ありその名をモルデカイと曰ひキシの曾孫シメイの孫ヤイルの子にしてベニヤミン人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'かれはバビロンの王ネブカデネザルが擄へゆきしユダのヱコニヤとともに擄はれ往る俘囚の中にありてヱサレムより移されたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'かれその叔父の女ハダツサすなはちエステルを養ひ育てたり 是は父も母もなかりければなり この女子顔貌勝れてうるはしかりしがその父母の死たる後モルデカイこれを取ておのれの女となせるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, '王の命令と詔言の聞え傳はり衆多の女子シユシヤンの城にあつめられてヘガイの手にわたされし時エステルも亦王の家に携へられてゆき婦人を管理るヘガイの手に交されしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'この女子ヘガイの意にかなひて之が惠を受たり即はちヘガイすみやかに之に潔淨の物およびその分を與へまた王の家の中より七人の侍女を擧てこれに附そはしめ彼とその侍女等を婦人の局の中なる最も佳き處に移しぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'エステルはおのれの民をもおのれの宗族をも顯はさざりき其はモルデカイこれを顯はすなかれと彼に言ふくめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'またモルデカイはエステルの模樣およびその如何になれるかを知んため日々に婦人の局の庭の前をあゆめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, '女子はおのおの婦人の則にしたがひて十二ヶ月を經しかる後順番にいりてアハシユエロス王にいたる是その潔淨の日を終るはかくのごとくなるが故なり 即ち沒薬の油を用ふること六ヶ月また各種の薫物および婦人の潔淨ごとにあつる物等を用ふること六ヶ月');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, '女子の王にいたるは是のごとしその婦人の局より出て王の家にゆく時には凡てその望む物をことごとく與へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, '而して夕に往き朝におよびて婦人の第二の局に還り妃嬪をつかさどる王の侍從シヤシガスの手に屬す王これを喜こびて名をさして召すにあらざれば重ねて王にいたることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'ここにモルデカイの叔父アビハイルの女すなはちモルデカイが取ておのれの女となしたるエステル入て王にいたるべき順番にあたりけるが彼は婦人をつかさどる王の侍從ヘガイが言きかせたる事の外には何をももとめざりき エステルは凡て彼を見る者によろこばれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'かくエステルは王の家に召いれられてアハシユエロス王にいたれり是その治世の第七年十月即ちテベテの月なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, '王一切の婦人に超てエステルを愛しければエステルはすべての處女にまさりて王の前に恩寵と厚情を得たり 王つひに后の冕をかれの首に戴かせ彼をしてワシテにかはりて后とならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'ここにおいて王おほいなる酒宴を設けてそのもろもろの牧伯と臣僕を饗す これをエステルの酒宴と稱ふまた諸州に租税をゆるし王の富有にかなひて物を賜ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, '再度處女の集められし時モルデカイは王の門に坐しをりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'エステルはモルデカイがかれに言ふくめたる如くして未だおのれの宗族をもおのれの民をも顯はさざりき エステルはモルデカイの言語にしたがふことその彼に養なひ育てられし時と異ならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, '當時モルデカイ王の門に坐し居ける時王の侍從にて戸を守る者の中ビグタンおよびテレシの二人怨むる事ありてアハシユエロス王を弑せんともとめたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'その事モルデカイに知れければモルデカイこれを后エステルに告げエステルまたモルデカイの名をもてこれを王に告げたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'ここにおいて此事をしらべさせしにその然ること顯はれければ彼ら二人は木にかけられその事は王の前なる日誌の書にかきしるさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'これらの事の後アハシユエロス王アガグ人ハンメダタの子ハマンを貴びこれを高くして己とともにある一切の牧伯の上にその席を定めしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, '王の門にある主の諸臣みな跪づきてハマンを拝せり 是は王斯かれになすことを命じたればなり 然れどもモルデカイは跪まづかず又これを拝せざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'ここをもて王の門にある王の諸臣モデカイにむかひて言ふ 汝いかなれば王の命に背くやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'かれらモルデカイに日々かく言ふといへども聽ざりければその事の爲をふさるべきか否を見んとてハマンにこれを告たり 其はモルデカイおのれのユダヤ人なることを語りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'ハマン、モルデカイの跪づかずまた己を拝せざるを見たれば ハマン忿怒にたへざりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'ただモルデカイ一人を殺すは事小さしと思へり彼らモルデカイの屬する民をハマンに顯はしければハマンはアハシユエロスの國の中にある一切のユダヤ人すなはちモルデカイの屬する民をことごとく殺さんと謀れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'アハシユエロス王の十二年正月即ちニサンの月にハマンの前にて十二月すなはちアダルの月まで一日一日のため一月一月のためにプルを投しむプルは即ち籤なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'ハマンかくてアハシユエロス王に言けるは御國の各州にある諸民の中に散されて別れ別れになりをる一の民ありその律法は一切の民と異り また王の法律を守らずこの故にこれを容しおくは王の益にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, '王もしこれを善としたまはば願くは彼らを滅ぼせと書くだしたまへ さらば我王の事をつかさどる者等の手に銀一萬タラントを秤り交して王の府庫に入しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, '王すなはち指環をその手より取はづしアガグ人ハンメダタの子ハマンすなはちユダヤ人の敵たる者に交し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'しかしてハマンに言けるはその銀はなんぢに與ふ その民もまた汝にあたふれば汝に善と見ゆるごとく爲よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'ここにおいて正月の十三日に王の書記官を召あつめ王に屬する州牧各州の方伯およびもろもろの民の牧伯にハマンが命ぜんとする所をことごとく書しるさしむ 即ちもろもろの州におくるものは其文字をもちひ もろもろの民におくるものはその言語をもちひ おのおのアハシユエロス王の名をもてこれを書き王の指環をもてこれに印したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'しかして驛卒をもて書を王の諸州におくり十二月すなはちアダルの月の十三日において一日の内に一切のユダヤ人を若き者老たる者小兒婦人の差別なくことごとく滅ぼし殺し絶しかつその所有物を奪ふべしと諭しぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'この詔旨を諸州に傳へてかの日のために準備をなさしめんとてその書る物の寫本を一切の民に開きて示せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, '驛卒王の命によりて急ぎて出ゆきぬ この詔書はシユシヤンの城に於て出されたり かくて王とハマンは坐して酒飮ゐたりしがシユシヤンの邑は惑ひわづらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'モルデカイ凡てこの爲れたる事を知しかばモルデカイ衣服を裂き麻布を纒ひ灰をかぶり邑の中に行て大に哭き痛く號び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, '王の門の前までも斯して來れり 其は麻布をまとふては王の門の内に入ること能はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'すべて王の命とその詔書と到れる諸州にてはユダヤ人の中におほいなる哀みあり斷食哭泣號呼おこれり また麻布をまとふて灰の上に坐する者おほかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'ここにエステルの侍女およびその侍從等きたりてこれを告ければ后はなはだしく憂ひ衣服をおくり之をモルデカイにきせてその麻布を脱しめんとしたりしがうけざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'ここをもてエステルは王の侍從の一人すなはち王の命じて己に侍らしむるハタクといふ者を召しモルデカイの許に往きてその何事なるか何故なるかを知きたれと命ぜり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'ハタクいでて王の門の前なる邑の廣場にをるモルデカイにいたりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'モルデカイおのれの遇たるところを具にこれに語りかつハマンがユダヤ人を滅ぼす事のために王の府庫に秤りいれんと約したる銀の額を告げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'またその彼等をほろぼさしむるためにシユシヤンにおいて書て與へられし詔書の寫本を彼にわたし之をエステルに見せかつ解あかし また彼に王の許にゆきてその民のためにこれに矜恤を請ひその前に願ふことを爲べしと言つたへよと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'ハタクかへり來りてモルデカイの言詞をエステルに告ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'エステル、ハタクに命じモルデカイに言をつたへしむ云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '王の諸臣がよび王の諸州の民みな知る男にもあれ女にもあれ凡て召れずして内庭に入て王にいたる者は必ず殺さるべき一の法律あり されど王これに金圭を伸れば生るを得べし かくて我此三十日は王にいたるべき召をかうむらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'エステルの言をモルデカイに告げけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'モルデカイ命じてエステルに答へしめて曰く 汝王の家にあれば一切のユダヤ人の如くならずして免かるべしと心に思ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'なんぢ若この時にあたりて默して言ずば他の處よりして助援と拯救ユダヤ人に興らんされど汝どなんぢの父の家は亡ぶべし 汝が后の位を得たるは此のごとき時のためなりしやも知るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'エステルまたモルデカイに答へしめて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'なんぢ往きシユシヤンにをるユダヤ人をことごとく集めてわがために斷食せよ 三日の間夜晝とも食ふことも飮むこともするなかれ 我とわが侍女等もおなじく斷食せん しかして我法律にそむく事なれども王にいたらん 我もし死べくば死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'ここにおいてモルデカイ往てエステルが凡ておのれに命じたるごとく行なへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, '第三日にエステル后の服を着王の家の内庭にいり王の家にむかひて立つ王は王宮の玉座に坐して王宮の戸口にむかひをりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, '王后エステルが庭にたちをるを見てこれに恩をくはへ其手にある金圭をエステルの方に伸しければエステルすすみよりてその圭の頭にさはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, '王かれに言けるは后エステルなんぢ何をもとむるやなんぢの願意は何なるや國の半分にいたるとも汝にあたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'エステルいひけるは王もし善としたまはば願くは今日わが王のために設けたる酒宴に王とハマンと臨みたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'ここに於て王ハマンを急がしめてエステルの言るごとくならしめよと命じ王とハマンやがてエステルが設けたる酒宴に臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, '酒宴の時王またエステルに言けるは汝の所求は何なるやかならずゆるさるべし なんぢの願意は何なるや國の半分にいたるとも成就らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'エステル言けるは我が所求わが願意は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'われもし王の目の前に恩を得 王もしわが所求をゆるしわが願意を成就しむることを善としたまはば願くは王とハマンまたわが設けんとする酒宴に臨みたまへ われ明日王の宣まへる言にしたがはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'かくてハマンはその日よろこび心たのしみて出きたりけるがハマン、モルデカイが王の門に居て己にむかひて起もあがらず身動もせざるを見しかば 痛くモルデカイを怒れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'されどもハマン耐忍びて家にかへりその朋友等および妻ゼレシをまねき來らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, '而してハマンその富の榮耀とその子の衆多ことと凡て王の己を貴とびし事また己をたかくして王の牧伯および臣僕の上にあらしむることを之に語れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'しかしてハマンまた言けらく后エステル酒宴を設けたりしが我のほかは何人をも王とともに之に臨ましめず明日もまた我は王とともに后に招かれをるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, '然れどユダヤ人モルデカイが王の門に坐しをるを見る間は是らの事も快樂からず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, '時にその妻ゼレシとその一切の朋友かれに言けるは請ふ高五十キユビトの木を立しめ明日の朝モルデカイをその上に懸んことを王に奏せ而して王とともに樂しみてその酒宴におもむけとハマンこの事を善としてその木を立しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'その夜王ねむること能はざりければ命じて日々の事を記せる記録の書を持きたらしめ王の前にこれを讀しめけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'モルデカイ曾て王の侍從の二人戸を守る者なるビグタンとテレシがアハシユエロス王を殺さんと謀れるを告たりと記せるに遇ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, '王すなはち言けるは之がために何の榮譽と爵位をモルデカイにあたへしや 王に事ふる臣僕等こたへて何をも彼にあたへしこと無しといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'ここにおいて王誰ぞ庭にあるやと問ふ この時ハマンは己がモルデカイのために設けたる木にモルデカイを懸ることを王に奏せんとして已に王の家の外庭に來りて居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, '王の臣僕等王につげてハマン庭に立をると言ければ王かれをして入來らしめよと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'ハマンやがて入きたりしに王かれにいひけるは王の尊とばんと欲する人には如何になさば善らんかとハマン心におもひけるは王の尊ばんとずる者は我にあらずして誰ぞやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'ハマンすなはち王にいひけるは王の尊ばんと欲する人のためには');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, '王の着たまへる衣服を携さへ來らしめかつ王の乗たまへる馬即ちその頭に王の冠冕を戴ける馬をひき來らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'これを王の最も貴とき一人の牧伯の手にわたし王の尊ばんとする人に其衣服を衣せしめこれを馬にのせて邑の街衢をみちびき通り 王の尊とばんと欲する人には是のごとくなすべしと呼はらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, '王ハマンに言けるは急ぎなんぢが言しごとくその衣服と馬とを取り王の門に坐するユダヤ人モルデカイに斯なせよ なんぢが言しところを一も缺こと無らしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'ここにおいてハマン衣服と馬とを取りモルデカイにその衣服を着せ彼をして邑の街衢を乗とほらしめその前に呼はりて云ふ王の尊ばんと欲する人には是のごとくなすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'かくてモルデカイは王の門にかへりたりしがハマンは愁へなやみ首をおほふておのれの家にはしりゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'しかしてハマンおのが遇る事をことごとくその妻ゼレシとその朋友等に告げるにその智者等およびその妻ゼレシかれに言けるは 彼のモルデカイすなはちなんぢがその前に敗れはじめたる者もしユダヤ人ならば汝これに勝ことを得じ必らずその前にやぶれんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'かれら尚ハマンとものいひをる間に王の侍從きたりてハマンをうながしエステルが設けたる酒宴にのぞましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, '王またハマンとともに后エステルと酒宴せんとて來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'この第二の酒宴の日に王またエステルに言けるは后エステルよなんぢのもとめは何なるや かならず許さるべし 汝のねがひは何なるや國の半分にいたるとも成就らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, '后エステルこたへて言けるは王よ我もし王の御目の前に恩を得王もし善と見たまはばわがもとめにしたがりこわが生命をわれに賜へ またわが願にしたがひてわが民を我に賜へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, '我とわが民は賣れて滅ぼされ殺され絶されんとす 我らもし奴婢に賣れたるならんには我默してはべらん 敵人は王の損害を償なふ事能はざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'アハシユエロス王后エステルにこたへて言けるは之をなさんと心にたくめる者は誰また何處にをるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'エステルいひけるはその敵その仇人は即ちこの惡きハマンなりと 是によりてハマンは王と后の前にありて懼れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, '王怒り酒宴の席をたちて宮殿の園に往きければハマンたちあがりて后エステルに生命を乞り 其はかれ王のおのれに禍災をなさんと決めしを見たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, '王宮殿の園より歸りて酒宴の場にいたりしにエステルのをる牀榻の上にハマン俯伏ゐたれば王いひけるは彼はまた家の内にてわが前に后を辱しめんとするかと此ことば王の口より出るや人々ハマンの面をおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, '時に王の前にある一人の侍從ハルボナいひけるは王の爲に善き事を言たりしかのモルデカイを懸んとてハマンが作りたる五十キユビトの木ハマンの家に立をるなりと王いひけるは彼をその上に懸よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, '人々ハマンを其モルデカイをかけんとて設けし木の上に懸たり 王の震怒つひに解く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'その日アハシユエロス王ユダヤ人の敵ハマンの家を后エステルに賜ふ モダカイもまた王の前に來れり 是はエステル彼が己と何なる係りなるかを告たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, '王ハマンより取かへせし己の指環をはづしてモルデカイに與ふ 而してエステル、モルデカイをしてハマンの家をつかさどらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'エステルふたたび王の前に奏してその足下にひれふしアガグ人ハマンがユダヤ人を害せんと謀りしその謀計を除かんことを涙ながらに乞求めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, '王エステルにむかひて金圭を伸ければエステル起て王の前に立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, '言けるは王もし之を善としたまひ我もし王の前に恩を得この事もし王に正と見え我もし御目にかなひたらば アガグ人ハンメダタの子ハマンが王の諸州にあるユダヤ人をほろぼさんと謀りて書おくりたる書をとりけすべき旨を書くだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'われ豈わが民に臨まんとする禍害を見るに忍びんや 豈わが宗族のほろぶるを見るにしのびんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'アハシユエロス王后エステルとユダヤ人モルデカイにいひけるはハマン、ユダヤ人を殺さんとしたれば我すでにハマンの家をエステルに與へまたハマンを木にかけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'なんぢらも亦おのれの好むごとく王の名をもて書をつくり王の指環をもてこれに印してユダヤ人につたへよ王の名をもて書き王の指環をもて印したる書は誰もとりけすこと能はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'ここをもてその時また王の書記官を召あつむ是三月すなはちシワンの月の二十三日なりきしかして印度よりエテオピアまでの百二十七州のユダヤ人州牧諸州の方伯牧伯等にモルデカイが命ぜんとするところを盡く書しるさしむ 即ちもろもろの州におくるものはその文字をもちひ諸の民におくるものはその言語をもちひて書おくりユダヤ人におくるものはその文字と言語をもちふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'かれアハシユエロス王の名をもてこれをかき王の指環をもてこれに印し驛卒をして御厩にてそだてたる逸足の御用馬にのりてその書をおくりつたへしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'その中に云ふ王すべての邑にあるユダヤ人に許す彼らあひ集まり立ておのれの生命を保護しおのれを襲ふ諸國諸州の一切の兵民をその妻子もろともにほろぼし殺し絶し且その所有物を奪ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'アハシユエロス王の諸州において十二月すなはちアダルの月の十三日一日の内かくのごとくするを許さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'この詔旨を諸州につたへんがためまたユダヤ人をしてかの日のために準備してその敵に仇をかへさしめんがためにその書る物の寫本を一切の民に開きて示せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, '驛卒逸足の御用馬にのり王の命によりて急がせられせきたてられて出ゆけりこの詔書はシユシヤンの城において出されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'かくてモルデカイは藍と白の朝服を着大なる金の冠を戴き紫色の細布の外衣をまとひて王の前よりいできたれり シユシヤンの邑中聲をあげて喜びぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'ユダヤ人には光輝あり喜悦あり快樂あり尊榮ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'いづれの州にても何の邑にても凡て王の命令と詔書のいたるところにてはユダヤ人よろこぴ樂しみ酒宴をひらきて此日を吉日となせりしかして國の民おほくユダヤ人となれり是はユダヤ人を畏るる心おこりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, '十二月すなはちアダルの月の十三日王の命令と詔書のおこなはるべき時いよいよ近づける時すなはちユダヤ人の敵ユダヤ人を打伏んとまちかまへたりしに却てユダヤ人おのれを惡む者を打ふする事となりける其日に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'ユダヤ人アハシユエロス王の各州にある己の邑々に相あつまりおのれを害せんとする者どもを殺さんとせり誰も彼らに敵ることを得る者なかりき 其は一切の民ユダヤ人を畏れたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, '諸州の牧伯州牧方伯など凡て王の事を辨理ふ者は皆ユダヤ人をたすけたり 是モルデカイを畏るるによりてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'モルデカイは王の家にて大なる者となりその名各州にきこえわたれり斯その人モルデカイはますます大になりゆきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'ユダヤ人すなはち刀刃をもてその一切の敵を撃て殺し滅ぼしおのれを惡む者を意のままに爲したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'ユダヤ人またシユシヤンの城においても五百人を殺しほろぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'パルシヤンダタ、ダルポン、アスパタ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'ポラタ、アダリヤ、アリダタ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'パルマシタ、アリサイ、アリダイ、ワエザタ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'これらの者すなはちハンメダタの子ユダヤ人の敵たるハマンの十人の子をも彼ら殺せりされどその所有物には手をかけざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'シユシヤンの城の内にて殺されし者の數をその日王にまうしあげければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, '王きさきエステルにいひけるはユダヤ人シユシヤンの城の内にて五百人を殺しまたハマンの十人の子をころせり王のその餘の諸州においては幾何なりしぞや 汝また何か求むるところあるやかならず許さるべし尚何かねがふところあるや必らず成就らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'エステルいひけるは王もし之を善としたまはば願くはシユシヤンにあるユダヤ人に允して明日も今日の詔旨のごとくなさしめ且ハマンの十人の子を木に懸しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, '王かく爲せと命じシユシヤンにおいて詔旨を出せりマンの十人の子は木に懸らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'アダルの月の十四日にシユシヤンのユダヤ人また集まりシユシヤンの内にて三百人をころせり然れどもその所有物には手をかけざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, '王の諸州にあるその餘のユダヤ人もまた相あつまり立ておのれの生命を保護しその敵に勝て安んじおのれを惡む者七萬五千人をころせり然れどもその所有には手をかけざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'アダルの月の十三日にこの事をおこなひ十四日にやすみてその日に酒宴をなして喜こべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'されどシユシヤンにをるユダヤ人はその十三日と十四日とにあひ集まり十五日にやすみてその日に酒宴をなして喜こべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'これによりて村々のユダヤ人すなはち石垣なき邑々にすめる者はアダルの月の十四日をもて喜樂の日酒宴の日吉日となして互に物をやりとりす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'モルデカイこれらの事を書しるしてアハシユエロス王の諸州にをるユダヤ人に遠きにも近きにも書をおくり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'アダルの月の十四日と十五日を年々にいはふことを命じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'この兩の日にユダヤ人その敵に勝て休みこの月は彼のために憂愁より喜樂にかはり悲哀より吉日にかはりたれば是らの日に酒宴をなして喜びたがひに物をやりとりし貧しき者に施與をなすべしと諭しぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'ここをもてユダヤ人はその已にはじめたるごとくモルデカイがかれらに書おくりしごとく行なひつづけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'アガグ人ハンメダタの子ハマンすなはちすべてのユダヤ人の敵たる者ユダヤ人を滅ぼさんと謀りプルすなはち籤を投てこれを滅ぼし絶さんとしたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'その事王の前に明かになりし時王書をおくりて命じハマンがユダヤ人を害せんとはかりしその惡き謀計をしてハマンのかうべに歸らしめ彼とその子等を木に懸しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'このゆゑに此兩の日をそのプルの名にしたがひてプリムとなづけたり斯りしかばこの書のすべての詞によりこの事につきて見たるところ己の遇たるところに依て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'ユダヤ人あひ定め年々その書るところにしたがひその定めたる時にしたがひてこの兩の日をまもり己とおのれの子孫および凡て已につらなる者これを行ひつづけて廢すること無く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'この兩の日をもて代々家々州々邑々において必ず記念てまもるべき者となしこれらのプリムの日をしてユダヤ人の中に廢せらるること無らしめまたこの記念をしてその子孫の中に絶ること無らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'かくてアビハイルの女なる后エステルとユダヤ人モルデカイおほいなる力をもて此プリムの第二の書を書おくりてこれを堅うす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'すなはちモルデカイ、アハシユエロスの國の百二十七州にある一切のユダヤ人に平和と眞實の言語をもて書をおくり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, '斷食と悲哀のことにつきてプリムのこれらの日を堅うしてその定めたる時を守らしむすなはちユダヤ人モルデカイと后エステルが曾てかれらに命じたるごとくまたユダヤ人等が曾てみづから己のためおよびおのれの子孫のために定めたるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'エステルの語プリムにかかはる是等の事をかたうせり是は書にしるされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'アハシユエロス王國土および海の島々に貢をたてまつらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'アハシユエロス王が權勢と能力をもて爲たる一切の事業および彼がモルデカイを高くして大いなる者とならしめたる事の委き話はメデアとペルシヤの列王の日誌の書に記さるるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'ユダヤ人モルデカイはアハシユエロス王に次ぐ者となりユダヤ人の中にありて大なる者にしてその衆多の兄弟によろこばれたり彼はその民の福祉をもとめその一切の宗族に平和の言をのべたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'ウヅの地にヨブと名くる人あり 其人と爲完全かつ正くして神を畏れ惡に遠ざかる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'その生る者は男の子七人女の子三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'その所有物は羊七千 駱駝三千 牛五百軛 牝驢馬五百 僕も夥多しくあり 此人は東の人の中にて最も大なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'その子等おのおの己の家にて己の日に宴筵を設くる事を爲し その三人の姉妹をも招きて與に食飮せしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'その宴筵の日はつる毎にヨブかならず彼らを召よせて潔む 即ち朝はやく興き彼ら一切の數にしたがひて燔祭を獻ぐ 是はヨブ我子ら罪を犯し心を神を忘れたらんも知べからずと謂てなり ヨブの爲ところ常に是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, '或日神の子等きたりてヱホバの前に立つ サタンも來りてその中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'ヱホバ、サタンに言たまひけるは汝何處より來りしや サタン、ヱホバに應へて言けるは地を行めぐり此彼經あるきて來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'ヱホバ、サタンに言たまひけるは汝心をもちひてわが僕ヨブを觀しや 彼のごとく完全かつ正くして神を畏れ惡に遠ざかる人世にあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'サタン、ヱホバに應へて言けるはヨブあにもとむることなくして神を畏れんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, '汝彼とその家およびその一切の所有物の周圍に藩屏を設けたまふにあらずや 汝かれが手に爲ところを盡く成就せしむるがゆゑにその所有物地に遍ねし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, '然ど汝の手を伸て彼の一切の所有物を撃たまへ 然ば必ず汝の面にむかひて汝を詛はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'ヱホバ、サタンに言たまひけるは視よ彼の一切の所有物を汝の手に任す 唯かれの身に汝の手をつくる勿れ サタンすなはちヱホバの前よりいでゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, '或日ヨブの子女等その第一の兄の家にて物食ひ酒飮ゐたる時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, '使者ヨブの許に來りて言ふ 牛耕しをり牝驢馬その傍に草食をりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'シバ人襲ひて之を奪ひ刄をもて少者を打殺せり 我ただ一人のがれて汝に告んとて來れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, '彼なほ語ひをる中に又一人きたりて言ふ 神の火天より降りて羊および少者を焚て滅ぼせり 我ただ一人のがれて汝に告んとて來れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, '彼なほ語ひをる中に又一人きたりて言ふ カルデヤ人三隊に分れ來て駱駝を襲ひてこれを奪ひ刄をもて少者を打殺せり我ただ一人のがれて汝に告んとて來れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, '彼なほ語ひをる中に又一人來りて言ふ汝の子女等その第一の兄の家にて物食ひ酒飮をりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, '荒野の方より大風ふき來て家の四隅を撃ければ夫の若き人々の上に潰れおちて皆しねり 我これを汝に告んとて只一人のがれ來れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, '是においてヨブ起あがり外衣を裂き髮を斬り地に伏して拜し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, '言ふ我裸にて母の胎を出たり 又裸にて彼處に歸らん ヱホバ與へヱホバ取たまふなり ヱホバの御名は讚べきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'この事においてヨブは全く罪を犯さず神にむかひて愚なることを言ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, '或日神の子等きたりてヱホバの前に立つ サタンも來りその中にありてヱホバの前に立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'ヱホバ、サタンに言たまひけるは汝何處より來りしや サタン、ヱホバに應へて言けるは地を行めぐり此彼經あるきて來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'ヱホバ、サタンに言たまひけるは汝心をもちひて我僕ヨブを見しや 彼のごとく完全かつ正くして神を畏れ惡に遠ざかる人世にあらざるなり 汝われを勸めて故なきに彼を打惱さしめしかど彼なほ己を完うして自ら堅くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'サタン、ヱホバに應へて言けるは皮をもて皮に換るなれば人はその一切の所有物をもて己の生命に換ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, '然ど今なんぢの手を伸て彼の骨と肉とを撃たまへ 然ば必らず汝の面にむかひて汝を詛はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'ヱホバ、サタンに言たまひけるは彼を汝の手に任す 只かれの生命を害ふ勿れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'サタンやがてヱホバの前よりいでゆきヨブを撃てその足の跖より頂までに惡き腫物を生ぜしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'ヨブ土瓦の碎片を取り其をもて身を掻き灰の中に坐りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, '時にその妻かれに言けるは汝は尚も己を完たうして自ら堅くするや 神を詛ひて死るに如ずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, '然るに彼はこれに言ふ汝の言ところは愚なる婦の言ところに似たり 我ら神より福祉を受るなれば災禍をも亦受ざるを得んやと 此事においてはヨブまつたくその唇をもて罪を犯さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, '時にヨブの三人の友この一切の災禍の彼に臨めるを聞き各々おのれの處よりして來れり 即ちテマン人エリパズ、シユヒ人ビルダデおよびマアナ人ゾパル是なり 彼らヨブを弔りかつ慰めんとて互に約してきたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, '目を擧て遙に觀しに其ヨブなるを見識がたき程なりければ齊く聲を擧て泣き 各おのれの外衣を裂き天にむかひて塵を撒て己の頭の上にちらし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, '乃ち七日七夜かれと偕に地に坐しゐて 一言も彼に言かくる者なかりき 彼が苦惱の甚だ大なるを見たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, '斯て後ヨブ口を啓きて自己の日を詛へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'ヨブすなはち言詞を出して云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '我が生れし日亡びうせよ 男子胎にやどれりと言し夜も亦然あれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'その日は暗くなれ 神上よりこれを顧みたまはざれ 光これを照す勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, '暗闇および死蔭これを取もどせ 雲これが上をおほえ 日を暗くする者これを懼しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'その夜は黑暗の執ふる所となれ 年の日の中に加はらざれ 月の數に入ざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'その夜は孕むこと有ざれ 歡喜の聲その中に興らざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, '日を詛ふ者レビヤタンを激發すに巧なる者これを詛へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'その夜の晨星は暗かれ その夜には光明を望むも得ざらしめ 又東雲の眼蓋を見ざらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, '是は我母の胎の戸を闔ずまた我目に憂を見ること無らしめざりしによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, '何とて我は胎より死て出ざりしや 何とて胎より出し時に氣息たえざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, '如何なれば膝ありてわれを接しや 如何なれば乳房ありてわれを養ひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, '否らずば今は我偃て安んじかつ眠らん 然ばこの身やすらひをり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'かの荒墟を自己のために築きたりし世の君等臣等と偕にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'かの黄金を有ち白銀を家に充したりし牧伯等と偕にあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, '又人しれず墮る胎兒のごとくにして世に出ず また光を見ざる赤子のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, '彼處にては惡き者 虐遇を息め倦憊たる者安息を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, '彼處にては俘囚人みな共に安然に居りて驅使者の聲を聞ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, '小き者も大なる者も同じく彼處にあり僕も主の手を離る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, '如何なれば艱難にをる者に光を賜ひ 心苦しむ者に生命をたまひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, '斯る者は死を望むなれどもきたらず これをもとむるは藏れたる寳を掘るよりも甚だし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'もし墳墓を尋ねて獲ば大に喜こび樂しむなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'その道かくれ神に取籠られをる人に如何なれば光明を賜ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'わが歎息はわが食物に代り我呻吟は水の流れそそぐに似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, '我が戰慄き懼れし者我に臨み我が怖懼れたる者この身に及べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, '我は安然ならず穩ならず安息を得ず唯艱難のみきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, '時にテマン人エリパズ答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '人もし汝にむかひて言詞を出さば汝これを厭ふや 然ながら誰か言で忍ぶことを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'さきに汝は衆多の人を誨へ諭せり 手の埀たる者をばこれを強くし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'つまづく者をば言をもて扶けおこし 膝の弱りたる者を強くせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, '然るに今この事汝に臨めば汝悶え この事なんぢに加はれば汝おぢまどふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, '汝は神を畏こめり 是なんぢの依賴む所ならずや 汝はその道を全うせり 是なんぢの望ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, '請ふ想ひ見よ 誰か罪なくして亡びし者あらん 義者の絶れし事いづくに在や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, '我の觀る所によれば不義を耕へし惡を播く者はその穫る所も亦是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'みな神の氣吹によりて滅びその鼻の息によりて消うす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, '獅子の吼 猛き獅子の聲ともに息み 少き獅子の牙折れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, '大獅子獲物なくして亡び小獅子散失す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, '前に言の密に我に臨めるありて我その細聲を耳に聞得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, '即ち人の熟睡する頃我夜の異象によりて想ひ煩ひをりける時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, '身に恐懼をもよほして戰慄き 骨節ことごとく振ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, '時に靈ありて我面の前を過ければ我は身の毛よだちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'その物立とまりしが我はその状を見わかつことえざりき 唯一の物の象わが目の前にあり 時に我しづかなる聲を聞けり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '人いかで神より正義からんや 人いかでその造主より潔からんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, '彼はその僕をさへに恃みたまはず 其使者をも足ぬ者と見做たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, '况んや土の家に住をりて塵を基とし蜉蝣のごとく亡ぶる者をや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, '是は朝より夕までの間に亡びかへりみる者もなくして永く失逝る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'その魂の緒あに絶ざらんや皆悟ること無して死うす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '請ふなんぢ龥びて看よ 誰か汝に應ふる者ありや 聖者の中にて誰に汝むかはんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, '夫愚なる者は憤恨のために身を殺し 癡き者は嫉媢のために己を死しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, '我みづから愚なる者のその根を張るを見たりしがすみやかにその家を詛へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'その子等は助援を獲ることなく 門にて惱まさる 之を救ふ者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'その穡とれる物は饑たる人これを食ひ 荊棘の籬の中にありてもなほ之を奪ひいだし 羂をその所有物にむかひて口を張る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, '災禍は塵より起らず 艱難は土より出ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, '人の生れて艱難をうくるは火の子の上に飛がごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'もし我ならんには我は必らず神に告求め 我事を神に任せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, '神は大にして測りがたき事を行ひたまふ 其不思議なる事を爲たまふこと數しれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, '雨を地の上に降し 水を野に遣り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, '卑き者を高く擧げ 憂ふる者を引興して幸福ならしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, '神は狡しき者の謀計を敗り 之をして何事をもその手に成就ること能はざらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, '慧き者をその自分の詭計によりて執へ 邪なる者の謀計をして敗れしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, '彼らは晝も暗黑に遇ひ 卓午にも夜の如くに摸り惑はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, '神は惱める者を救ひてかれらが口の劍を免かれしめ 強き者の手を免かれしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, '是をもて弱き者望あり 惡き者口を閉づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, '神の懲したまふ人は幸福なり 然ば汝全能者の儆責を輕んずる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, '神は傷け又裹み 撃ていため又その手をもて善醫したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, '彼はなんぢを六の艱難の中にて救ひたまふ 七の中にても災禍なんぢにのぞまじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, '饑饉の時にはなんぢを救ひて死を免れしめ 戰爭の時には劍の手を免れしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, '汝は舌にて鞭たるる時にも隱るることを得 壞滅の來る時にも懼るること有じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, '汝は壞滅と饑饉を笑ひ地の獸をも懼るること無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, '田野の石なんぢと相結び野の獸なんぢと和がん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, '汝はおのが幕屋の安然なるを知ん 汝の住處を見まはるに缺たる者なからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, '汝また汝の子等の多くなり 汝の裔の地の草の如くになるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, '汝は遐齡におよびて墓にいらん 宛然麥束を時にいたりて運びあぐるごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, '視よ我らが尋ね明めし所かくのごとし 汝これを聽て自ら知れよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'ヨブ應へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '願はくは我憤恨の善く權られ 我懊惱の之とむかひて天秤に懸られんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, '然すれば是は海の沙よりも重からん 斯ればこそ我言躁妄なりけれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'それ全能者の箭わが身にいりわが魂神その毒を飮り 神の畏怖我を襲ひ攻む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, '野驢馬あに靑草あるに鳴んや 牛あに食物あるに吽らんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, '淡き物あに鹽なくして食はれんや 蛋の白あに味あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'わが心の觸ることを嫌ふ物是は我が厭ふ所の食物のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, '願はくは我求むる所を得んことを願はくは神わが希ふ所の物を我に賜はらんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, '願はくは神われを滅ぼすを善とし 御手を伸て我を絶たまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, '然るとも我は尚みづから慰むる所あり 烈しき苦痛の中にありて喜ばん 是は我聖者の言に悖りしことなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, '我何の氣力ありてか尚俟ん 我の終いかなれば我なほ耐へ忍ばんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'わが氣力あに石の氣力のごとくならんや 我肉あに銅のごとくならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'わが助われの中に無にあらずや 救拯我より逐はなされしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, '憂患にしづむ者はその友これを憐れむべし 然らずば全能者を畏るることを廢ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'わが兄弟はわが望を充さざること溪川のごとく 溪川の流のごとくに過さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, '是は氷のために黑くなり 雪その中に藏るれども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, '温暖になる時は消ゆき熱くなるに及てはその處に絶はつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, '隊旅客身をめぐらして去り空曠處にいたりて亡ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'テマの隊旅客これを望みシバの旅客これを慕ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, '彼等これを望みしによりて愧恥を取り 彼處に至りてその面を赧くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'かく汝等も今は虚しき者なり 汝らは怖ろしき事を見れば則ち懼る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, '我あに汝等我に予へよと言しこと有んや 汝らの所有物の中より物を取て我ために饋れと言しこと有んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'また敵人の手より我を救ひ出せと言しことあらんや 虐ぐる者の手より我を贖へと言しことあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, '我を敎へよ 然らば我默せん 請ふ我の過てる所を知せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, '正しき言は如何に力あるものぞ 然ながら汝らの規諫る所は何の規諫とならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, '汝らは言を規正んと想ふや 望の絶たる者の語る所は風のごときなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, '汝らは孤子のために籤を掣き 汝らの友をも商貨にするならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, '今ねがはくは我に向へ 我は汝らの面の前に僞はらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, '請ふ再びせよ 不義あらしむる勿れ 請ふ再びせよ 此事においては我正義し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, '我舌に不義あらんや 我口惡き物を辨へざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'それ人の世にあるは戰鬪にあるがごとくならずや 又其日は傭人の日のごとくなるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, '奴僕の暮を冀がふが如く傭人のその價を望むがごとく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, '我は苦しき月を得させられ 憂はしき夜をあたへらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, '我臥ば乃はち言ふ何時夜あけて我おきいでんかと 曙まで頻に輾轉ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'わが肉は蟲と土塊とを衣服となし 我皮は愈てまた腐る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'わが日は機の梭よりも迅速なり 我望む所なくし之を送る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, '想ひ見よ わが生命が氣息なる而已 我目は再び福祉を見ること有じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, '我を見し者の眼かさねて我を見ざらん 汝目を我にむくるも我は已に在ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, '雲の消て逝がごとく陰府に下れる者は重ねて上りきたらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, '彼は再びその家に歸らず 彼の郷里も最早かれを認めじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, '然ば我はわが口を禁めず 我心の痛によりて語ひ わが神魂の苦しきによりて歎かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, '我あに海ならんや鰐ならんや 汝なにとて我を守らせおきたまふぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'わが牀われを慰め わが寢床わが愁を解んと思ひをる時に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, '汝夢をもて我を驚かし 異象をもて我を懼れしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, '是をもて我心は氣息の閉んことを願ひ我この骨よりも死を冀がふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'われ生命を厭ふ 我は永く生るをことを願はず 我を捨おきたまへ 我日は氣のごときなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, '人を如何なる者として汝これを大にし 之を心に留');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, '朝ごとに之を看そなはし 時わかず之を試みたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, '何時まで汝われに目を離さず 我が津を咽む間も我を捨おきたまはざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, '人を鑒みたまふ者よ我罪を犯したりとて汝に何をか爲ん 何ぞ我を汝の的となして我にこの身を厭はしめたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, '汝なんぞ我の愆を赦さず我罪を除きたまはざるや 我いま土の中に睡らん 汝我を尋ねたまふとも我は在ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, '時にシユヒ人ビルダデ答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '何時まで汝かかる事を言や 何時まで汝の口の言語を大風のごとくにするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, '神あに審判を曲たまはんや 全能者あに公義を曲たまはんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, '汝の子等かれに罪を獲たるにや之をその愆の手に付したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, '汝もし神に求め 全能者に祈り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, '清くかつ正しうしてあらば必ず今汝を顧み汝の義き家を榮えしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, '然らば汝の始は微小くあるとも汝の終は甚だ大ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, '請ふ汝過にし代の人に問へ 彼らの父祖の尋究めしところの事を學べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(我らは昨日より有しのみにて何をも知ず 我らが世にある日は影のごとし)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, '彼等なんぢを敎へ汝を諭し 言をその心より出さざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, '葦あに泥なくして長んや 萩あに水なくしてそだたんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, '是はその靑くして未だ刈ざる時にも他の一切の草よりは早く槁る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, '神を忘るる者の道は凡て是のごとく 悖る者の望は空しくなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'その恃む所は絶れ その倚ところは蜘蛛網のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'その家に倚かからんとすれば家立ず 之に堅くとりすがるも保たじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, '彼日の前に靑緑を呈はし その枝を園に蔓延らせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'その根を石堆に盤みて石の屋を眺むれども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, '若その處より取のぞかれなばその處これを認めずして我は汝を見たる事なしと言ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, '視よその道の喜樂是のごとし 而してまた他の者地より生いでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'それ神は完全人を棄たまはず また惡き者の手を執りたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, '遂に哂笑をもて汝の口に充し歡喜を汝の唇に置たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, '汝を惡む者は羞恥を着せられ 惡き者の住所は無なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'ヨブこたへて言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '我まことに其事の然るを知り 人いかでか神の前に義かるべけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'よし人は神と辨爭はんとするとも千の一も答ふること能はざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, '神は心慧く力強くましますなり 誰か神に逆ひてその身安からんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, '彼山を移したまふに山しらず 彼震怒をもて之を飜倒したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, '彼地を震ひてその所を離れしめたまへばその柱ゆるぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, '日に命じたまへば日いでず 又星辰を封じたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, '唯かれ獨天を張り海の濤を覆たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'また北斗參宿昴宿および南方の密室を造りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, '大なる事を行ひたまふこと測られず奇しき業を爲たまふこと數しれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, '視よ彼わが前を過たまふ 然るに我これを見ず彼すすみゆき賜ふ然るに我之を曉ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, '彼奪ひ去賜ふ 誰か能之を沮まん 誰か之に汝何を爲やと言ことを得爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, '神其震怒を息賜はず ラハブを助る者等之が下に屈む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, '然ば我爭か彼に回答を爲ことを得ん 爭われ言を選びて彼と論ふ事をえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, '假令われ義かるとも彼に回答をせじ 彼は我を審判く者なれば我彼に哀き求ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, '假令我彼を呼て彼われに答たまふともわが言を聽いれ賜ひしとは我信ぜざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, '彼は大風をもて我を撃碎き 故なくして我に衆多の傷を負せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, '我に息をつかさしめず 苦き事をもて我身に充せ賜ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, '強き者の力量を言んか 視よ此にあり 審判の事ならんか 誰か我を喚出すことを得爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, '假令われ義かるとも我口われを惡しと爲ん 假令われ完全かるとも尚われを罪ありとせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, '我は全し 然ども我はわが心を知ず 我生命を賤む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, '皆同一なり 故に我は言ふ神は完全者と惡者とを等しく滅したまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, '災禍の俄然に人を誅す如き事あれば彼は辜なき者の苦痛を笑ひ見たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, '世は惡き者の手に交されてあり 彼またその裁判人の面を蔽ひたまふ 若彼ならずば是誰の行爲なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'わが日は驛使よりも迅く 徒に過さりて福祉を見ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, '其はしること葦舟のごとく 物を攫まんとて飛かける鷲のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'たとひ我わが愁を忘れ面色を改めて笑ひをらんと思ふとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, '尚この諸の苦痛のために戰慄くなり 我思ふに汝われを釋し放ちたまはざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, '我は罪ありとせらるるなれば何ぞ徒然に勞すべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'われ雪水をもて身を洗ひ 灰汁をもて手を潔むるとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, '汝われを汚はしき穴の中に陷いれたまはん 而して我衣も我を厭ふにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, '神は我のごとく人にあらざれば我かれに答ふべからず 我ら二箇して共に裁判に臨むべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'また我らの間には我ら二箇の上に手を置べき仲保あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, '願くは彼その杖を我より取はなし その震怒をもて我を懼れしめたまはざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, '然らば我 言語て彼を畏れざらん 其は我みづから斯る者と思はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'わが心生命を厭ふ 然ば我わが憂愁を包まず言あらはし わが魂神の苦きによりて語はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'われ神に申さん 我を罪ありしとしたまふ勿れ 何故に我とあらそふかを我に示したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'なんぢ虐遇を爲し 汝の手の作を打棄て惡き者の謀計を照すことを善としたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, '汝は肉眼を有たまふや 汝の觀たまふ所は人の觀るがごとくなるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'なんぢの日は人間の日のごとく 汝の年は人の日のごとくなるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, '何とて汝わが愆を尋ねわが罪をしらべたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'されども汝はすでに我の罪なきを知たまふ また汝の手より救ひいだし得る者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, '汝の手われをいとなみ我をことごとく作れり 然るに汝今われを滅ぼしたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, '請ふ記念たまへ 汝は土塊をもてすてるがごとくに我を作りたまへり 然るに復われを塵に歸さんとしたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, '汝は我を乳のごとく斟ぎ牛酪のごとくに凝しめたまひしに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, '汝は皮と肉とを我に着せ骨と筋とをもて我を編み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, '生命と恩惠とをわれに授け我を眷顧てわが魂神を守りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, '然はあれど汝これらの事を御心に藏しおきたまへり 我この事汝の心にあるを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, '我もし罪を犯さば汝われをみとめてわが罪を赦したまはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, '我もし行状あしからば禍あらん 假令われ義かるとも我頭を擧じ 其は我は衷に羞耻充ち 眼にわが患難を見ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'もし頭を擧なば獅子のごとくに汝われを追打ち 我身の上に復なんぢの奇しき能力をあらはしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, '汝はしばしば證する者を入かへて我を攻め 我にむかひて汝の震怒を増し新手に新手を加へて我を攻めたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, '何とて汝われを胎より出したまひしや 然らずば我は息絶え目に見らるること無く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, '曾て有ざりし如くならん 即ち我は胎より墓に持ゆかれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'わが日は幾時も无きに非ずや 願くは彼姑らく息て我を離れ我をして少しく安んぜしめんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, '我が往て復返ることなきその先に斯あらしめよ 我は暗き地死の蔭の地に往ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'この地は暗くして晦冥に等しく死の蔭にして區分なし 彼處にては光明も黑暗のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, '是においてナアマ人ゾパル答へて言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '言語多からば豈答へざるを得んや 口おほき人あに義とせられんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, '汝も空しき言あに人をして口を閉しめんや 汝嘲らば人なんぢをして羞しめざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, '汝は言ふ 我敎は正し 我は汝の目の前に潔しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, '願くは神言を出し 汝にむかひて口を開き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, '智慧の秘密をなんぢに示してその知識の相倍するを顯したまはんことを 汝しれ神はなんぢの罪よりも輕くなんぢを處置したまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'なんぢ神の深事を窮むるを得んや 全能者を全く窮むることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'その高きことは天のごとし 汝なにを爲し得んや 其深きことは陰府のごとし 汝なにを知えんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'その量は地よりも長く海よりも濶し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, '彼もし行めぐりて人を執へて召集めたまふ時は誰か能くこれを阻まんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, '彼は僞る人を善く知りたまふ 又惡事は顧みること無して見知たまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, '虚しき人は悟性なし その生るるよりして野驢馬の駒のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, '汝もし彼にむかひて汝の心を定め 汝の手を舒べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, '手に罪のあらんには之を遠く去れ 惡をなんぢの幕屋に留むる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, '然すれば汝 面を擧て玷なかるべく堅く 立て懼るる事なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'すなはち汝憂愁を忘れん 汝のこれを憶ゆることは流れ去し水のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'なんぢの生存らふる日は眞晝よりも輝かん 假令暗き事あるとも是は平旦のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'なんぢは望あるに因て安んじ 汝の周圍を見めぐりて安然に寐るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'なんぢは何にも懼れさせらるること無して偃やまん 必ず衆多の者なんぢを悦こばせんと務むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, '然ど惡き者は目曚み逃遁處を失なはん 其望は氣の斷ると等しかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'ヨブこたへて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'なんぢら而已まことに人なり 智慧は汝らと共に死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, '我もなんぢらと同じく心あり 我はなんぢらの下に立ず 誰か汝らの言し如き事を知ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, '我は神に龥はりて聽るる者なるに今その友に嘲けらるる者となれり 嗚呼正しくかつ完たき人あざけらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, '安逸なる者は思ふ 輕侮は不幸なる者に附そひ足のよろめく者を俟と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, '掠奪ふ者の天幕は繁榮え 神を怒らせ自己の手に神を携ふる者は安泰なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, '今請ふ獸に問へ然ば汝に敎へん 天空の鳥に問へ然ばなんぢに語らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, '地に言へ然ばなんぢに敎へん 海の魚もまた汝に述べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, '誰かこの一切の者に依てヱホバの手のこれを作りしなるを知ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, '一切の生物の生氣および一切の人の靈魂ともに彼の手の中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, '耳は説話を辨へざらんや その状あたかも口の食物を味ふがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, '老たる者の中には智慧あり 壽長者の中には穎悟あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, '智慧と權能は神に在り 智謀と穎悟も彼に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, '視よ彼毀てば再び建ること能はず 彼人を閉こむれば開き出すことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, '視よ彼水を止むれば則ち涸れ 水を出せば則ち地を滅ぼす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, '權能と穎悟は彼に在り 惑はさるる者も惑はす者も共に彼に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, '彼は議士を裸體にして擄へゆき 審判人をして愚なる者とならしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, '王等の權威を解て反て之が腰に繩をかけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, '祭司等を裸體にして擄へゆき 權力ある者を滅ぼし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, '言爽なる者の言語を取除き 老たる者の了知を奪ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, '侯伯たる者等に恥辱を蒙らせ 強き者の帶を解き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, '暗中より隱れたる事等を顯し 死の蔭を光明に出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, '國々を大にしまた之を滅ぼし 國々を廣くしまた之を舊に歸し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, '地の民の長たる者等の了知を奪ひ これを路なき荒野に吟行はしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, '彼らは光明なき暗にたどる 彼また彼らを醉る人のごとくによろめかしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, '視よわが目これを盡く觀 わが耳これを聞て通逹れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, '汝らが知るところは我もこれを知る 我は汝らに劣らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, '然りと雖ども我は全能者に物言ん 我は神と論ぜんことをのぞむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, '汝らは只謊言を造り設くる者 汝らは皆無用の醫師なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, '願くは汝ら全く默せよ 然するは汝らの智慧なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, '請ふわが論ずる所を聽き 我が唇にて辨爭ふ所を善く聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, '神のために汝ら惡き事を言や 又かれのために虚僞を述るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, '汝ら神の爲に偏るや またかれのために爭はんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, '神もし汝らを鑒察たまはば豈善らんや 汝等人を欺むくごとくに彼を欺むき得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, '汝等もし密に私しするあらば彼かならず汝らを責ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'その威光なんぢらを懼れしめざらんや 彼を懼るる畏懼なんぢらに臨まざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'なんぢらの諭言は灰に譬ふべし なんぢらの城は土の城となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, '默して我にかかはらざれ 我言語んとす 何事にもあれ我に來らば來れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, '我なんぞ我肉をわが齒の間に置き わが生命をわが手に置かんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, '彼われを殺すとも我は彼に依賴まん 唯われは吾道を彼の前に明かにせんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, '彼また終に我救拯とならん 邪曲なる者は彼の前にいたること能はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'なんぢら聽よ 我言を聽け我が述る所をなんぢらの耳に入しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, '視よ我すでに吾事を言竝べたり 必ず義しとせられんと自ら知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, '誰か能われと辨論ふ者あらん 若あらば我は口を緘て死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, '惟われに二の事を爲たまはざれ 然ば我なんぢの面をさけて隱れじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'なんぢの手を我より離したまへ 汝の威嚴をもて我を懼れしめたまはざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, '而して汝われを召たまへ 我こたへん 又われにも言はしめて汝われに答へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, '我の愆われの罪いくばくなるや 我の背反と罪とを我に知しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, '何とて御顏を隱し我をもて汝の敵となしたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'なんぢは吹廻さるる木の葉を威し 干あがりたる籾殼を追たまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, '汝は我につきて苦き事等を書しるし 我をして我が幼稚時の罪を身に負しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'わが足を足械にはめ 我すべての道を伺ひ 我足の周圍に限界をつけたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, '我は腐れたる者のごとくに朽ゆき 蠹に食るる衣服に等し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, '婦の產む人はその日少なくして艱難多し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'その來ること花のごとくにして散り 其馳ること影のごとくにして止まらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'なんぢ是のごとき者に汝の目を啓きたまふや 汝われを汝の前にひきて審判したまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, '誰か清き物を汚れたる物の中より出し得る者あらん 一人も無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'その日旣に定まり その月の數なんぢに由り 汝これが區域を立て越ざらしめたまふなれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, '是に目を離して安息を得させ 之をして傭人のその日を樂しむがごとくならしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'それ木には望あり 假令砍るるとも復芽を出してその枝絶ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'たとひ其根地の中に老い 幹土に枯るとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, '水の潤霑にあへば即ち芽をふき枝を出して若樹に異ならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, '然ど人は死れば消うす 人氣絶なば安に在んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, '水は海に竭き河は涸てかわく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, '是のごとく人も寢臥てまた興ず 天の盡るまで目覺ず睡眠を醒さざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, '願はくは汝われを陰府に藏し 汝の震怒の息むまで我を掩ひ 我ために期を定め而して我を念ひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, '人もし死ばまた生んや 我はわが征戰の諸日の間望みをりて我が變更の來るを待ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'なんぢ我を呼たまはん 而して我こたへん 汝かならず汝の手の作を顧みたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, '今なんぢは我に歩履を數へたまふ 我罪を汝うかがひたまはざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'わが愆は凡て嚢の中に封じてあり汝わが罪を縫こめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'それ山も倒れて終に崩れ巖石も移りてその處を離る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, '水は石を鑿ち 浪は地の塵を押流す 汝は人の望を斷たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'なんぢは彼を永く攻なやまして去ゆかしめ 彼の面容の變らせて逐やりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'その子尊貴なるも彼は之を知ず 卑賤なるもまた之を曉らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, '只己みづからその肉に痛苦を覺え己みづからその心に哀く而已');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'テマン人エリパズ答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '智者あに虚しき知識をもて答へんや豈東風をその腹に充さんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'あに裨なき談益なき詞をもて辨論はんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'まことに汝は神を畏るる事を棄て その前に祷ることを止む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'なんぢの罪なんぢの口を敎ふ 汝はみづから擇びて狡猾人の舌を用ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'なんぢの口みづから汝の罪を定む 我には非ず汝の唇なんぢの惡きを證す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, '汝あに最初に世に生れたる人ならんや 山よりも前に出來しならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, '神の御謀議を聞しならんや 智慧を獨にて藏めをらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'なんぢが知る所は我らも知ざらんや 汝が曉るところは我らの心にも在ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, '我らの中には白髮の人および老たる人ありて汝の父よりも年高し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, '神の慰藉および夫の柔かき言詞を汝小しとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'なんぢ何ぞかく心狂ふや 何ぞかく目をしばたたくや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'なんぢ是のごとく神に對ひて氣をいらだて 斯る言詞をなんぢの口よりいだすは如何ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, '人は如何なる者ぞ 如何してか潔からん 婦の產し者は如何なる者ぞ 如何してか義からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'それ神はその聖者にすら信を置たまはず 諸の天もその目の前には潔からざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, '况んや罪を取ること水を飮がごとくする憎むべき穢れたる人をや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, '我なんぢに語る所あらん 聽よ 我見たる所を述ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, '是すなはち智者等が父祖より受て隱すところ無く傳へ來し者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, '彼らに而已この地は授けられて外國人は彼等の中に往來せしこと無りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, '惡き人はその生る日の間つねに悶へ苦しむ 強暴人の年は數へて定めおかる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'その耳には常に懼怖しき音きこえ平安の時にも滅ぼす者これに臨む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, '彼は幽暗を出得るとは信ぜず 目ざされて劒に付さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, '彼食物は何處にありやと言つつ尋ねありき 黑暗日の備へられて己の側にあるを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, '患難と苦痛とはかれを懼れしめ 戰鬪の準備をなせる王のごとくして彼に打勝ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, '彼は手を伸て神に敵し 傲りて全能者に悖り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, '頸を強くし 厚き楯の面を向て之に馳かかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, '面に肉を滿せ 腰に脂を凝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, '荒されたる邑々に住居を設けて人の住べからざる家 石堆となるべき所に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, '是故に彼は富ず その貨物は永く保たず その所有物は地に蔓延ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'また自己は黑暗を出づるに至らず 火燄その枝葉を枯さん 而してその身は神の口の氣吹によりて亡ゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, '彼は虚妄を恃みて自ら欺くべからず 其報は虚妄なるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, '彼の日の來らざる先に其事成べし 彼の枝は緑ならじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, '彼は葡萄の樹のその熟せざる果を振落すがごとく 橄欖の樹のその花を落すがごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, '邪曲なる者の宗族は零落れ 賄賂の家は火に焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, '彼等は惡念を孕み 虚妄を生み その胎にて詭計を調ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'ヨブ答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '斯る事は我おほく聞り 汝らはみな人を慰めんとして却つて人を煩はす者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, '虚しき言語あに終極あらんや 汝なにに勵されて應答をなすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, '我もまた汝らの如くに言ことを得 もし汝らの身わが身と處を換なば我は言語を練て汝らを攻め 汝らにむかひて首を搖ことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'また口をもて汝らを強くし 唇の慰藉をもて汝らの憂愁を解ことを得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'たとひ我言を出すとも我憂愁は解ず 默するとても何ぞ我身の安くなること有んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, '彼いま已に我を疲らしむ 汝わが宗族をことごとく荒せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'なんぢ我をして皺らしめたり 是われに向ひて見證をなすなり 又わが痩おとろへたる状貌わが面の前に現はれ立て我を攻む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'かれ怒てわれを撕裂きかつ窘しめ 我にむかひて齒を噛鳴し我敵となり目を鋭して我を看る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, '彼ら我にむかひて口を張り 我を賤しめてわが頬を打ち 相集まりて我を攻む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, '神われを邪曲なる者に交し 惡き者の手に擲ちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, '我は安穩なる身なりしに彼いたく我を打惱まし 頸を執へて我をうちくだき遂に我を立て鵠となしたまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'その射手われを遶り圍めり やがて情もなく我腰を射透し わが膽を地に流れ出しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, '彼はわれを打敗りて破壞に破壞を加へ 勇士のごとく我に奔かかりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'われ麻布をわが肌に縫つけ我角を塵にて汚せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, '我面は泣て頳くなり 我目縁には死の蔭あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, '然れども我手には不義あること無く わが祈祷は清し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, '地よ我血を掩ふなかれ 我號呼は休む處を得ざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, '視よ今にても我證となる者天にあり わが眞實を表明す者高き處にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'わが朋友は我を嘲けれども我目は神にむかひて涙を注ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, '願くは彼人のために神と論辨し 人の子のためにこれが朋友と論辨せんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, '數年すぎさらば我は還らぬ旅路に往べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'わが氣息は已にくさり 我日すでに盡なんとし墳墓われを待つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'まことに嘲弄者等わが傍に在り 我目は彼らの辨爭ふを常に見ざるを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, '願くは質を賜ふて汝みづから我の保證となりたまへ 誰か他にわが手をうつ者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, '汝彼らの心を閉て悟るところ無らしめたまへり 必ず彼らをして愈らしめたまはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, '朋友を交付して掠奪に遭しむる者は其子等の目潰るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, '彼われを世の民の笑柄とならしめたまふ 我は面に唾せらるべき者となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'かつまた我目は憂愁によりて昏み 肢體は凡て影のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, '義しき者は之に驚き 無辜者は邪曲なる者を見て憤ほる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, '然ながら義しき者はその道を堅く持ち 手の潔淨き者はますます力を得るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, '請ふ汝ら皆ふたたび來れ 我は汝らの中に一人も智き者あるを見ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'わが日は已に過ぎ わが計る所わが心に冀ふ所は已に敗れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, '彼ら夜を晝に變ふ 黑暗の前に光明ちかづく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, '我もし俟つところ有ば是わが家たるべき陰府なるのみ 我は黑暗にわが牀を展ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'われ朽腐に向ひては汝はわが父なりと言ひ 蛆に向ひては汝は我母わが姉妹なりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, '然ばわが望はいづくにかある 我望は誰かこれを見る者あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, '是は下りて陰府の關に到らん 之と齊しく我身は塵の中に臥靜まるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'シユヒ人ビルダデこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '汝等いつまで言語を獵求むることをするや 汝ら先曉るべし 然る後われら辨論はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'われら何ぞ獸畜とおもはるべけんや 何ぞ汝らの目に汚穢たる者と見らるべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'なんぢ怒りて身を裂く者よ 汝のためとて地あに棄られんや 磐あに其處より移されんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, '惡き者の光明は滅され 其火の焔は照じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'その天幕の内なる光明は暗くなり其が上の燈火は滅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'またその強き歩履は狹まり 其計るところは自分を陷いる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'すなはち其足に逐れて網に到り また陷阱の上を歩むに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, '索はその踵に纒り 羂これを執ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, '索かれを執ふるために地に隱しあり 羂かれを陷しいるるために路に設けあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, '怖ろしき事四方において彼を懼れしめ 其足にしたがひて彼をおふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'その力は餓ゑ 其傍には災禍そなはり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'その膚の肢は蝕壞らる 即ち死の初子これが肢を蝕壞るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'やがて彼はその恃める天幕より曳離されて懼怖の王の許に驅やられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, '彼に屬せざる者かれの天幕に住み 硫礦かれの家の上に降ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, '下にてはその根枯れ 上にてはその枝砍る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, '彼の跡は地に絶え 彼の名は街衢に傳はらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, '彼は光明の中より黑暗に逐やられ 世の中より驅出されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, '彼はその民の中に子も無く孫も有じ また彼の住所には一人も遺る者なからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, '之が日を見るにおいて後に來る者は駭ろき 先に出し者は怖おそれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'かならず惡き人の住所は是のごとく 神を知ざる者の所は是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'ヨブこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '汝ら我心をなやまし 言語をもて我を打くだくこと何時までぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'なんぢら已に十次も我を辱しめ我を惡く待ひてなほ愧るところ無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, '假令われ眞に過ちたらんもその過は我の身に止れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'なんぢら眞に我に向ひて誇り我身に羞べき行爲ありと證するならば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, '神われを虐げその網羅をもて我を包みたまへりと知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, '我虐げらるると叫べども答なく 呼はり求むれども審理なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, '彼わが路の周圍に垣を結めぐらして逾る能はざらしめ 我が行く途に黑暗を蒙むらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'わが光榮を褫ぎ我冠冕を首より奪ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, '四方より我を毀ちて失しめ 我望を樹のごとくに根より拔き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, '我にむかひて震怒を燃し 我を敵の一人と見たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'その軍旅ひとしく進み途を高くして我に攻寄せ わが天幕の周圍に陣を張り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, '彼わが兄弟等をして遠くわれを離れしめたまへり 我を知る人々は全く我に疎くなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'わが親戚は往來を休め わが朋友はわれを忘れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'わが家に寄寓る者およびわが婢等は我を見て外人のごとくす 我かれらの前にては異國人のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'われわが僕を喚どもこたへず 我口をもて彼に請はざるを得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'わが氣息はわが妻に厭はれ わが臭氣はわが同胎の子等に嫌はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, '童子等さへも我を侮どり 我起あがれば即ち我を嘲ける');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'わが親しき友われを惡みわが愛したる人々ひるがへりてわが敵となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'わが骨はわが皮と肉とに貼り 我は僅に齒の皮を全うして逃れしのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'わが友よ汝等われを恤れめ 我を恤れめ 神の手われを撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, '汝らなにとて神のごとくして我を攻め わが肉に饜ことなきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, '望むらくは我言の書留られんことを 望むらくは我言書に記されんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, '望むらくは鐡の筆と鉛とをもて之を永く磐石に鐫つけおかんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'われ知る我を贖ふ者は活く 後の日に彼かならず地の上に立ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'わがこの皮この身の朽はてん後 われ肉を離れて神を見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, '我みづから彼を見たてまつらん 我目かれを見んに識らぬ者のごとくならじ 我が心これを望みて焦る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'なんぢら若われら如何に彼を攻んかと言ひ また事の根われに在りと言ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, '劍を懼れよ 忿怒は劍の罰をきたらす 斯なんぢら遂に審判のあるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'ナアマ人ゾパルこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'これに因てわれ答をなすの思念を起し心しきりに之がために急る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, '我を辱しむる警語を我聞ざるを得ず 然しながらわが了知の性われをして答ふることを得せしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'なんぢ知ずや古昔より地に人の置れしより以來');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, '惡き人の勝誇は暫時にして邪曲なる者の歡樂は時の間のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'その高天に逹しその首雲に及ぶとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, '終には己の糞のごとくに永く亡絶べし 彼を見識る者は言ん彼は何處にありやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, '彼は夢の如く過さりて復見るべからず 夜の幻のごとく追はらはれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, '彼を見たる目かさねてかれを見ることあらず 彼の住たる處も再びかれを見ること無らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'その子等は貧しき者に寛待を求めん 彼もまたその取し貨財を手づから償さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'その骨に少壯氣勢充り 然れどもその氣勢もまた塵の中に彼とおなじく臥ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'かれ惡を口に甘しとして舌の底に藏め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, '愛みて捨ず 之を口の中に含みをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, '然どその食物膓の中にて變り 腹の内にて蝮の毒とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'かれ貨財を呑たれども復之を吐いださん 神これを彼の腹より推いだしたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'かれは蝮の毒を吸ひ 虺の舌に殺されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'かれは蜂蜜と牛酪の湧て流るる河川を視ざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'その勞苦て獲たる物は之を償して自ら食はず 又それを求めたる所有よりは快樂を得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, '是は彼貧しき者を虐遇げて之を棄たればなり 假令家を奪ひとるとも之を改め作ることを得ざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'かれはその腹に飽ことを知ざるが故に自己の深く喜ぶ物をも保つこと能はじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'かれが遺して食はざる物とては一も無し 是によりてその福祉は永く保たじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'その繁榮の眞盛において彼は艱難に迫られ 乏しき者すべて手をこれが上に置ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'かれ腹を充さんとすれば神烈しき震怒をその上に下し その食する時にこれをその上に降したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'かれ鐡の器を避れば銅の弓これを射透す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, '是に於て之をその身より拔ば閃く鏃その膽より出きたりて畏懼これに臨む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, '各種の黑暗これが寳物ををほろぼすために蓄へらる 又人の吹おこせしに非る火かれを焚き その天幕に遺りをる者をも焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, '天かれの罪を顯はし 地興りて彼を攻ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'その家の儲蓄は亡て神の震怒の日に流れ去ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, '是すなはち惡き人が神より受る分 神のこれに定めたまへる數なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'ヨブこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '請ふ汝等わが言を謹んで聽き 之をもて汝らの慰藉に代よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, '先われに容して言しめよ 我が言る後なんぢ嘲るも可し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'わが怨言は世の人の上につきて起れる者ならんや 我なんぞ氣をいらだつ可らざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'なんぢら我を視て驚き手を口にあてよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'われ思ひまはせば畏しくなりて身體しきりに戰慄く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, '惡き人何とて生ながらへ 老かつ勢力強くなるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'その子等はその周圍にありてその前に堅く立ち その子孫もその目の前に堅く立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'またその家は平安にして畏懼なく 神の杖その上に臨まじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'その牡牛は種を與へて過らず その牝牛は子を產てそこなふ事なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, '彼等はその少き者等を外に出すこと群のごとし その子等は舞をどる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, '彼等は鼓と琴とをもて歌ひ 笛の音に由て樂み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'その日を幸福に暮し まばたくまに陰府にくだる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, '然はあれども彼等は神に言らく我らを離れ賜へ 我らは汝の道をしることを好まず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, '全能者は何者なれば我らこれに事ふべき 我儕これに祈るとも何の益を得んやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, '視よ彼らの福祿は彼らの力に由にあらざるなり 惡人の希圖は我の與する所にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, '惡人のその燈火を滅るる事幾度ありしか その滅亡のこれに臨む事 神の怒りて之に艱苦を蒙らせたまふ事幾度有しか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'かれら風の前の藁の如く 暴風に吹さらるる籾殼の如くなること幾度有しか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, '神かれの愆を積たくはへてその子孫に報いたまふか 之を彼自己の身に報い知しむるに如ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'かれをして自らその滅亡を目に視させ かつ全能者の震怒を飮しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'その月の數すでに盡るに於ては何ぞその後の家に關はる所あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, '神は天にある者等をさへ審判たまふなれば誰か能これに知識を敎へんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, '或人は繁榮を極め全く平穩にかつ安康にして死に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'その器に乳充ち その骨の髓は潤ほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'また或人は心を苦しめて死し 終に福祉をあぢはふる事なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, '是等は倶に齊しく塵に臥して蛆におほはる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, '我まことに汝らの思念を知り 汝らが我を攻撃んとするの計略を知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'なんぢらは言ふ王侯の家は何に在る 惡人の住所は何にあると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, '汝らは路往く人々に詢ざりしや 彼等の證據を曉らざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'すなはち滅亡の日に惡人遺され 烈しき怒の日に惡人たづさへ出さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, '誰か能かれに打向ひて彼の行爲を指示さんや 誰か能彼の爲たる所を彼に報ゆることを爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, '彼は舁れて墓に到り 塚の上にて守護ることを爲す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, '谷の土塊も彼には快し 一切の人その後に從ふ 其前に行る者も數へがたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, '旣に是の如くなるに汝等なんぞ徒に我を慰さめんとするや 汝らの答ふる所はただ虚僞のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, '是においてテマン人エリパズこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '人神を益する事をえんや 智人も唯みづから益する而已なるぞかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'なんぢ義かるとも全能者に何の歡喜かあらん なんぢ行爲を全たふするとも彼に何の利益かあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, '彼汝の畏懼の故によりて汝を責め汝を鞫きたまはんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'なんぢの惡大なるにあらずや 汝の罪はきはまり無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, '即はち汝は故なくその兄弟の物を抑へて質となし 裸なる者の衣服を剥て取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, '渇く者に水を與へて飮しめず 饑る者に食物を施こさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, '力ある者土地を得 貴き者その中に住む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'なんぢは寡婦に手を空しうして去しむ 孤子の腕は折る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, '是をもて網羅なんぢを環り 畏懼にはかに汝を擾す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'なんぢ黑暗を見ずや 洪水のなんぢを覆ふを見ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, '神は天の高に在すならずや 星辰の巓ああ如何に高きぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, '是によりて汝は言ふ 神なにをか知しめさん 豈よく黑雲の中より審判するを得たまはんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, '濃雲かれを蔽へば彼は見たまふ所なし 唯天の蒼穹を歩みたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'なんぢ古昔の世の道を行なはんとするや 是あしき人の踐たりし者ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, '彼等は時いまだ至らざるに打絶れ その根基は大水に押流されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, '彼ら神に言けらく我儕を離れたまへ 全能者われらのために何を爲ことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'しかるに彼は却つて佳物を彼らの家に盈したまへり 但し惡人の計畫は我に與する所にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, '義しき者は之を見て喜び 無辜者は彼らを笑ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '曰く我らの仇は誠に滅ぼされ 其盈餘れる物は火にて焚つくさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, '請ふ汝神と和らぎて平安を得よ 然らば福祿なんぢに來らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, '請ふかれの口より敎晦を受け その言語をなんぢの心に藏めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'なんぢもし全能者に歸向り且なんぢの家より惡を除き去ば 汝の身再び興されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'なんぢの寳を土の上に置き オフルの黄金を谿河の石の中に置け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, '然れば全能者なんぢの寳となり汝のために白銀となりたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, '而してなんぢは又全能者を喜び且神にむかひて面をあげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'なんぢ彼に祈らば彼なんぢに聽たまはん 而して汝その誓願をつくのひ果さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'なんぢ事を爲んと定めなばその事なんぢに成ん 汝の道には光照ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, '其卑く降る時は汝いふ昇る哉と 彼は謙遜者を拯ひたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'かれは罪なきに非ざる者をも拯ひたまはん 汝の手の潔淨によりて斯る者も拯はるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'ヨブこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '我は今日にても尚つぶやきて服せず わが禍災はわが嘆息よりも重し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'ねがはくは神をたづねて何處にか遇まつるを知り其御座に參いたらんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, '我この愁訴をその御前に陳べ口を極めて辨論はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, '我その我に答へたまふ言を知り また其われに言たまふ所を了らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'かれ大なる能をもて我と爭ひたまはんや 然らじ反つて我を眷みたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, '彼處にては正義人かれと辨爭ふことを得 斯せば我を鞫く者の手を永く免かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'しかるに我東に往くも彼いまさず 西に往くも亦見たてまつらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, '北に工作きたまへども遇まつらず 南に隱れ居たまへば望むべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'わが平生の道は彼知たまふ 彼われを試みたまはば我は金のごとくして出きたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'わが足は彼の歩履に堅く隨がへり 我はかれの道を守りて離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, '我はかれの唇の命令に違はず 我が法よりも彼の口の言語を重ぜり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'かれは一に居る者にまします 誰か能かれをして意を變しめん 彼はその心に慾する所をかならず爲たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, '然ば我に向ひて定めし事を必らず成就たまはん 是のごとき事を多く彼は爲たまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, '是故に我かれの前に慄ふ 我考ふれば彼を懼る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, '神わが心を弱くならしめ 全能者われをして懼れしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'かく我は暗の來らぬ先わが面を黑暗の覆ふ前に打絶れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'なにゆゑに全能者時期を定めおきたまはざるや 何故に彼を知る者その日を見ざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, '人ありて地界を侵し群畜を奪ひて牧ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, '孤子の驢馬を驅去り 寡婦の牛を取て質となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, '貧しき者を路より推退け 世の受難者をして盡く身を匿さしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, '視よ彼らは荒野にをる野驢馬のごとく出て業を爲て食を求め 野原よりその子等のために食物を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, '圃にて惡き者の麥を刈り またその葡萄の遺餘を摘む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'かれらは衣服なく裸にして夜を明し 覆ふて寒氣を禦ぐべき物なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, '山の暴風に濡れ 庇はるるところ無して岩を抱く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, '孤子を母の懷より奪ふ者あり 貧しき者の身につける物を取て質となす者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, '貧き者衣服なく裸にて歩き 饑つつ麥束を擔ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, '人の垣の内にて油を搾め また渇きつつ酒醡を踐む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, '邑の中より人々の呻吟たちのぼり 傷けられたる者の叫喚おこる 然れども神はその怪事を省みたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'また光明に背く者あり 光の道を知ず 光の路に止らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, '人を殺す者昧爽に興いで 受難者や貧しき者を殺し 夜は盜賊のごとくす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, '姦淫する者は我を見る目はなからんと言てその目に昏暮をうかがひ待ち而してその面に覆ふ物を當つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'また夜分家を穿つ者あり 彼等は晝は閉こもり居て光明を知らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, '彼らには晨は死の蔭のごとし 是死の蔭の怖ろしきを知ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, '彼は水の面に疾ながるる物の如し その產業は世の中に詛はる その身重ねて葡萄圃の路に向はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, '亢旱および炎熱は雪水を直に乾涸す 陰府が罪を犯せし者におけるも亦かくのごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'これを宿せし腹これを忘れ 蛆これを好みて食ふ 彼は最早世におぼえらるること無く その惡は樹を折るが如くに折る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, '是すなはち孕まず產ざりし婦人をなやまし 寡婦を憐れまざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, '神はその權能をもて強き人々を保存へさせたまふ 彼らは生命あらじと思ふ時にも復興る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, '神かれらに安泰を賜へば彼らは安らかなり 而してその目をもて彼らの道を見そなはしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'かれらは旺盛になり暫時が間に無なり卑くなりて一切の人のごとくに沒し麥の穗のごとくに斷る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'すでに是のごとくなれば誰か我の謬まれるを示してわが言語を空しくすることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, '時にシユヒ人ビルダデこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '神は大權を握りたまふ者 畏るべき者にましまし 高き處に平和を施したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'その軍旅數ふることを得んや 其光明なに物をか照さざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, '然ば誰か神の前に正義かるべき 婦人の產し者いかでか清かるべき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, '視よ月も輝かず 星も其目には清明ならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'いはんや蛆のごとき人 蟲のごとき人の子をや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'ヨブこたへて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'なんぢ能力なき者を如何に助けしや 氣力なきものを如何に救ひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, '智慧なき者を如何に誨へしや 穎悟の道を如何に多く示ししや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'なんぢ誰にむかひて言語を出ししや なんぢより出しは誰が靈なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, '陰靈水またその中に居る者の下に慄ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'かれの御前には陰府も顯露なり 滅亡の坑も蔽ひ匿す所なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, '彼は北の天を虚空に張り 地を物なき所に懸けたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, '水を濃雲の中に包みたまふてその下の雲裂ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, '御寳座の面を隱して雲をその上に展べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, '水の面に界を設けて光と暗とに限を立たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'かれ叱咤たまへば天の柱震ひかつ怖る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'その權能をもて海を靜め その智慧をもてラハブを撃碎き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'その氣嘘をもて天を輝かせ 其手をもて逃る蛇を衝とほしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, '視よ是等はただその御工作の端なるのみ 我らが聞ところの者は如何にも微細なる耳語ならずや 然どその權能の雷轟に至りては誰かこれを曉らんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'ヨブまた語を繼ぎていはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'われに義しき審判を施したまはざる神 わが心魂をなやまし給ふ全能者此神は活く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, '(わが生命なほ全くわれの衷にあり 神の氣息なほわが鼻にあり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'わが口は惡を言ず わが舌は謊言を語らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, '我決めて汝等を是とせじ 我に死るまで我が罪なきを言ことを息じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'われ堅くわが正義を持ちて之を棄じ 我は今まで一日も心に責られし事なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, '我に敵する者は惡き者と成り我を攻る者は義からざる者と成るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, '邪曲なる者もし神に絶れその魂神を脱とらるるに於ては何の望かあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'かれ艱難に罹る時に神その呼號を聽いれたまはんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'かれ全能者を喜こばんや 常に神を龥んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'われ神の御手を汝等に敎へん 全能者の道を汝等に隱さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, '視よ汝等もみな自らこれを觀たり 然るに何ぞ斯愚蒙をきはむるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, '惡き人の神に得る分 強暴の人の全能者より受る業は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'その子等蕃れば劍に殺さる その子孫は食物に飽ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'その遺れる者は疫病に斃れて埋められ その妻等は哀哭をなさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'かれ銀を積こと塵のごとく衣服を備ふること土のごとくなるとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'その備ふる者は義き人これを着ん またその銀は無辜者これを分ち取ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'その建る家は蟲の巣のごとく また番人の造る茅家のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, '彼は富る身にて寢臥し重ねて興ること無し また目を開けば即ちその身きえ亡す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, '懼ろしき事大水のごとく彼に追及き 夜の暴風かれを奪ひ去る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, '東風かれを颺げて去り 彼をその處より吹はらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, '神かれを射て恤まず 彼その手より逃れんともがく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, '人かれに對ひて手を鳴し 嘲りわらひてその處をいでゆかしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, '白銀掘いだす坑あり 煉るところの黄金は出處あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, '鐡は土より取り 銅は石より鎔して獲るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, '人すなはち黑暗を破り極より極まで尋ね窮めて黑暗および死蔭の石を求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'その穴を穿つこと深くして上に住む人と遠く相離れ その上を歩む者まつたく之を覺えず 是のごとく身を縋下げ 遙に人と隔りて空に懸る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, '地その上は食物を出し 其下は火に覆へさるるがごとく覆へる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'その石の中には碧の玉のある處あり 黄金の沙またその内にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'その逕は鷙鳥もこれを知ず 鷹の目もこれを看ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, '鷙き獸も未だこれを踐ず 猛き獅子も未だこれを通らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, '人堅き磐に手を加へまた山を根より倒し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, '岩に河を掘り各種の貴き物を目に見とめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, '水路を塞ぎて漏ざらしめ隱れたる寳物を光明に取いだすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, '然ながら智慧は何處よりか覓め得ん 明哲の在る所は何處ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, '人その價を知ず人のすめる地に獲べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, '淵は言ふ我の内に在ずと 海は言ふ我と偕ならずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, '精金も之に換るに足ず 銀も秤りてその價となすを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'オフルの金にてもその價を量るべからず 貴き靑玉も碧玉もまた然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, '黄金も玻璃もこれに並ぶ能はず 精金の器皿も之に換るに足ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, '珊瑚も水晶も論にたらず 智慧を得るは眞珠を得るに勝る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'エテオビアより出る黄玉もこれに並ぶあたはず 純金をもてするともその價を量るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, '然ば智慧は何處より來るや 明哲の在る所は何處ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, '是は一切の生物の目に隱れ 天空の鳥にも見えず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, '滅亡も死も言ふ 我等はその風聲を耳に聞し而已');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, '神その道を曉り給ふ 彼その所を知りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'そは彼は地の極までも觀そなはし天が下を看きはめたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, '風にその重量を與へ 水を度りてその量を定めたまひし時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, '雨のために法を立て 雷霆の光のために途を設けたまひし時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, '智慧を見て之を顯はし之を立て試みたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'また人に言たまはく視よ主を畏るるは是智慧なり 惡を離るるは明哲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'ヨブまた語をつぎて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '嗚呼過にし年月のごとくならまほし 神の我を護りたまへる日のごとくならまほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'かの時には彼の燈火わが首の上に輝やき彼の光明によりて我黑暗を歩めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'わが壯なりし日のごとくならまほし 彼時には神の恩惠わが幕屋の上にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'かの時には全能者なほ我とともに在し わが子女われの周圍にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, '乳ながれてわが足跡を洗ひ 我が傍なる磐油を灌ぎいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'かの時には我いでて邑の門に上りゆき わが座を街衢に設けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, '少き者は我を見て隱れ 老たる者は起あがりて立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, '牧伯たる者も言談ずしてその口に手を當て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, '貴き者も聲ををさめてその舌を上顎に貼たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, '我事を耳に聞る者は我を幸福なりと呼び 我を目に見たる者はわがために證據をなしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, '是は我助力を求むる貧しき者を拯ひ 孤子および助くる人なき者を拯ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, '亡びんとせし者われを祝せり 我また寡婦の心をして喜び歌はしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'われ正義を衣また正義の衣る所となれり 我が公義は袍のごとく冠冕のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'われは盲目の目となり跛者の足となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, '貧き者の父となり知ざる者の訴訟の由を究め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, '惡き者の牙を折り その齒の間より獲物を取いだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, '我すなはち言けらく 我はわが巣に死ん 我が日は砂の如く多からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'わが根は水の邊に蔓り 露わが枝に終夜おかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'わが榮光はわが身に新なるべくわが弓はわが手に何時も強からんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, '人々われに聽き默して我が敎を俟ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'わが言し後は彼等言を出さず 我説ところは彼等に甘露のごとく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'かれらは我を望み待つこと雨のごとく 口を開きて仰ぐこと春の雨のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'われ彼等にむかひて笑ふとも彼等は敢て眞實とおもはず我面の光を彼等は除くことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'われは彼等のために道を擇び その首として座を占め 軍中の王のごとくして居り また哀哭者を慰さむる人のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, '然るに今は我よりも年少き者等われを笑ふ 彼等の父は我が賤しめて群の犬と並べ置くことをもせざりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'またかれらの手の力もわれに何の用をかなさん 彼らは其氣力すでに衰へたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'かれらは缺乏と饑とによりて痩おとろへ 荒かつ廢れたる暗き野にて乾ける地を咬む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'すなはち灌木の中にて藜を摘み苕の根を食物となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, '彼らは人の中より逐いださる 盜賊を追ふがごとくに人かれらを追て呼はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, '彼等は懼ろしき谷に住み 土坑および磐穴に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, '灌木の中に嘶なき 荊棘の下に偃す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, '彼らは愚蠢なる者の子 卑むべき者の子にして國より撃いださる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'しかるに今は我かれらの歌謠に成り 彼らの嘲哢となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'かれら我を厭ふて遠く我を離れ またわが面に唾することを辭まず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, '神わが綱を解て我をなやましたまへば彼等もわが前にその韁を縱せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'この輩わが右に起あがり わが足を推のけ我にむかひて滅亡の路を築く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, '彼らは自ら便なき者なれども尚わが逕を毀ち わが滅亡を促す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'かれらは石垣の大なる崩口より入がごとくに進み來り 破壞の中にてわが上に乗かかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, '懼ろしき事わが身に臨み 風のごとくに我が尊榮を吹はらふ わが福祿は雲のごとくに消失す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, '今はわが心われの衷に鎔て流れ 患難の日かたく我を執ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, '夜にいれば我骨刺れて身を離る わが身を噬む者つひに休むこと無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'わが疾病の大なる能によりてわが衣服は醜き樣に變り 裏衣の襟の如くに我身に固く附く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, '神われを泥の中に投こみたまひて我は塵灰に等しくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'われ汝にむかひて呼はるに汝答へたまはず 我立をるに 汝只われをながめ居たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'なんぢは我にむかひて無情なりたまひ 御手の能力をもて我を攻撃たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'なんぢ我を擧げ風の上に乗て負去しめ 大風の音とともに消亡しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'われ知る汝はわれを死に歸らしめ一切の生物の終に集る家に歸らしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'かれは必ず荒垤にむかひて手を舒たまふこと有じ 假令人滅亡に陷るとも是等の事のために號呼ぶことをせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, '苦みて日を送る者のために我哭ざりしや 貧しき者のために我心うれへざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'われ吉事を望みしに凶事きたり 光明を待しに黑暗きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'わが膓沸かへりて安からず 患難の日我に追及ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'われは日の光を蒙らずして哀しみつつ歩き 公會の中に立て助を呼もとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'われは山犬の兄弟となり 駝鳥の友となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'わが皮は黑くなりて剥落ち わが骨は熱によりて焚け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'わが琴は哀の音となり わが笛は哭の聲となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, '我わが目と約を立たり 何ぞ小艾を慕はんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, '然せば上より神の降し給ふ分は如何なるべきぞ 高處より全能者の與へ給ふ業は如何なるべきぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, '惡き人には滅亡きたらざらんや 善らぬ事を爲す者には常ならぬ災禍あらざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, '彼わが道を見そなはし わが歩履をことごとく數へたまはざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, '我虚誕とつれだちて歩みし事ありや わが足虚僞に奔從がひし事ありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, '請ふ公平き權衡をもて我を稱れ 然ば神われの正しきを知たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'わが歩履もし道を離れ わが心もしわが目に隨がひて歩み わが手にもし汚のつきてあらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, '我が播たるを人食ふも善し わが產物を根より拔るるも善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'われもし婦人のために心まよへる事あるか 又は我もしわが隣の門にありて伺ひし事あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'わが妻ほかの人のために臼磨き ほかの人々かれの上に寢るも善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, '其は是は重き罪にして裁判人に罰せらるべき惡事なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, '是はすなはち滅亡にまでも燬いたる火にしてわが一切の產をことごとく絶さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'わが僕あるひは婢の我と辯爭ひし時に我もし之が權理を輕んぜし事あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, '神の起あがりたまふ時には如何せんや 神の臨みたまふ時には何と答へまつらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'われを胎内に造りし者また彼をも造りたまひしならずや われらを腹の内に形造りたまひし者は唯一の者ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, '我もし貧き者にその願ふところを獲しめず 寡婦をしてその目おとろへしめし事あるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'または我獨みづから食物を啖ひて孤子にこれを啖はしめざりしこと有るか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '(却つて彼らは我が若き時より我に育てられしこと父におけるが如し 我は胎内を出てより以來寡を導びく事をせり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'われ衣服なくして死んとする者あるひは身を覆ふ物なくして居る人を見し時に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'その腰もし我を祝せず また彼もしわが羊の毛にて温まらざりし事あるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'われを助くる者の門にをるを見て我みなしごに向ひて手を上し事あるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, '然ありしならば肩骨よりしてわが肩おち骨とはなれてわが腕折よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, '神より出る災禍は我これを懼る その威光の前には我 能力なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, '我もし金をわが望となし 精金にむかひて汝わが所賴なりと言しこと有か');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, '我もしわが富の大なるとわが手に物を多く獲たることを喜びしことあるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'われ日の輝くを見または月の輝わたりて歩むを見し時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, '心竊にまよひて手を口に接しことあるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, '是もまた裁判人に罪せらるべき惡事なり 我もし斯なせし事あらば上なる神に背しなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, '我もし我を惡む者の滅亡るを喜び 又は其災禍に罹るによりて自ら誇りし事あるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '(我は之が生命を呪ひ索めて我口に罪を犯さしめし如き事あらず)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'わが天幕の人は言ずや彼の肉に飽ざる者いづこにか在んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, '旅人は外に宿らず わが門を我は街衢にむけて啓けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, '我もしアダムのごとくわが罪を蔽ひ わが惡事を胸に隱せしことあるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'すなはち大衆を懼れ宗族の輕蔑に怖ぢて口を閉ぢ門を出ざりしごとき事あるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, '嗚呼われの言ところを聽わくる者あらまほし(我が花押ここに在り 願くは全能者われに答へたまへ)我を訴ふる者みづから訴訟状を書け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'われ必らず之を肩に負ひ冠冕のごとくこれを首に結ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, '我わが歩履の數を彼に述ん 君王たる者のごとくして彼に近づかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'わが田圃號呼りて我を攻め その阡陌ことごとく泣さけぶあるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, '若われ金を出さずしてその產物を食ひ またはその所有主をして生命を失はしめし事あらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, '小麥の代に蒺藜生いで 大麥のかはりに雜草おひ出るとも善し ヨブの詞をはりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'ヨブみづから見て己の正義とするに因て此三人の者之に答ふる事を止む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, '時にラムの族ブジ人バラケルの子エリフ怒を發せり ヨブ神よりも己を正しとするに因て彼ヨブにむかひて怒を發せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'またヨブの三人の友答ふるに詞なくして猶ヨブを罪ありとせしによりて彼らにむかひて怒を發せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'エリフはヨブに言ふことをひかへて俟をりぬ 是は自己よりも彼等年老たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, '茲にエリフこの三人の口に答ふる詞の有ざるを見て怒を發せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'ブジ人バラケルの子エリフすなはち答へて曰く 我は年少く汝等は年老たり是をもて我はばかりて我意見をなんぢらに陳ることを敢てせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, '我意へらく日を重ねたる者宜しく言を出すべし 年を積たる者宜しく智慧を敎ふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, '但し人の衷には靈あり 全能者の氣息人に聰明を與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, '大なる人すべて智慧あるに非ず 老たる者すべて道理に明白なるに非ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, '然ば我言ふ 我に聽け 我もわが意見を陳ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, '視よ我は汝らの言語を俟ち なんぢらの辯論を聽き なんぢらが言ふべき言語を尋ね盡すを待り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'われ細に汝らに聽しが汝らの中にヨブを駁折る者一人も無く また彼の言詞に答ふる者も無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'おそらくは汝等いはん 我ら智慧を見得たり 彼に勝つ者は唯神のみ 人は能はずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, '彼はその言語を我に向て發さざりき 我はまた汝らの言ふ所をもて彼に答へじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, '彼らは愕ろきて復答ふる所なく 言語かれらの衷に浮ばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, '彼等ものいはず立とどまりて重ねて答へざればとて我あに俟をるべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, '我も自らわが分を答へわが意見を吐露さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'われには言滿ち わが衷の心しきりに迫る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'わが腹は口を啓かざる酒のごとし 新しき皮嚢のごとく今にも裂んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'われ説いだして胸を安んぜんとす われ口を啓きて答へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'かならず我は人に偏らず 人に諂はじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, '我は諂らふことを知ず もし諂らはば我の造化主ただちに我を絶たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, '然ばヨブよ請ふ我が言ふ事を聽け わが一切の言語に耳を傾むけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, '視よ我口を啓き 舌を口の中に動かす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'わが言ふ所は正義き心より出づ わが唇あきらかにその知識を陳ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, '神の靈われを造り 全能者の氣息われを活しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, '汝もし能せば我に答へよ わが前に言をいひつらねて立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, '我も汝とおなじく神の者なり 我もまた土より取てつくられしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'わが威嚴はなんぢを懼れしめず わが勢はなんぢを壓せず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, '汝わが聽くところにて言談り 我なんぢの言語の聲を聞けり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'われは潔淨くして愆なし 我は辜なく惡き事わが身にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, '視よ彼われを攻る釁隙を尋ね われを己の敵と算へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'わが脚を桎に夾めわが一切の擧動に目を着たまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, '視よ我なんぢに答へん なんぢ此事において正義からず 神は人よりも大なる者にいませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, '彼その凡て行なふところの理由を示したまはずとて汝かれにむかひて辯爭そふは何ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'まことに神は一度二度と告示したまふなれど人これを曉らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, '人熟睡する時または床に睡る時に夢あるひは夜の間の異象の中にて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'かれ人の耳をひらき その敎ふるところを印して堅うし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, '斯して人にその惡き業を離れしめ 傲慢を人の中より除き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, '人の魂靈を護りて墓に至らしめず 人の生命を護りて劍にほろびざらしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, '人床にありて疼痛に攻られ その骨の中に絶ず戰鬪のあるあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'その氣食物を厭ひ その魂靈うまき物をも嫌ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'その肉は痩おちて見えず その骨は見えざりし者までも顯露になり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'その魂靈は墓に近より その生命は滅ぼす者に近づく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'しかる時にもし彼とともに一箇の使者あり 千の中の一箇にして中保となり 正しき道を人に示さば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, '神かれを憫れみて言給はん彼を救ひて墓にくだること無らしめよ 我すでに收贖の物を得たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'その肉は小兒の肉よりも瑞々しくなり その若き時の形状に歸らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'かれ若し神に祷らば神かれを顧りみ 彼をしてその御面を喜こび見ることを得せしめたまはん 神は人の正義に報をなしたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'かれ人の前に歌ひて言ふ 我は罪を犯し正しきを抂たり 然ど報を蒙らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, '神わが魂靈を贖ひて墓に下らしめず わが生命光明を見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'そもそも神は是等のもろもろの事をしばしば人におこなひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'その魂靈を墓より牽かへし生命の光明をもて彼を照したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'ヨブよ耳を傾むけて我に聽け 請ふ默せよ 我かたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'なんぢもし言ふべきことあらば我にこたへよ 請ふ語れ 我なんぢを義とせんと慾すればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'もし無ば我に聽け 請ふ默せよ 我なんぢに智慧を敎へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'エリフまた答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'なんぢら智慧ある者よ我言を聽け 知識ある者よ我に耳を傾むけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, '口の食物を味はふごとく耳は言詞を辨まふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'われら自ら是非を究め われらもろともに善惡を明らかにせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'それヨブは言ふ我は義し 神われに正しき審判を施こしたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'われは義しかれども僞る者とせらる 我は愆なけれどもわが身の矢創愈がたしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, '何人かヨブのごとくならん彼は罵言を水のごとくに飮み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, '惡き事を爲す者等と交はり 惡人とともに歩むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'すなはち彼いへらく 人は神と親しむとも身に益なしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, '然ばなんぢら心ある人々よ我に聽け 神は惡を爲すことを決めて無く 全能者は不義を行ふこと決めて無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, '却つて人の所爲をその身に報い 人をしてその行爲にしたがひて獲るところあらしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'かならず神は惡き事をなしたまはず全能者は審判を抂たまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'たれかこの地を彼に委ねし者あらん 誰か全世界を定めし者あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, '神もしその心を己にのみ用ひ その靈と氣息とを己に收回したまはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'もろもろの血肉ことごとく亡び人も亦塵にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'なんぢもし曉ることを得ば請ふ我に聽けわが言詞の聲に耳を側だてよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, '公義を惡む者あに世ををさむるを得んや なんぢあに至義き者を惡しとすべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, '王たる者にむかひて汝は邪曲なりと言ひ 牧伯たる者にむかひて汝らは惡しといふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'まして君王たる者をも偏視ず貧しき者に超て富る者をかへりみるごとき事をせざる者にむかひてをや 斯爲たまふは彼等みな同じくその御手の作るところなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, '彼らは瞬く時間に死に 民は夜の間に滅びて消失せ 力ある者も人手によらずして除かる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'それ神の目は人の道の上にあり 神は人の一切の歩履を見そなはす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, '惡を行なふ者の身を匿すべき黑暗も無く死蔭も无し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, '神は人をして審判を受しむるまでに長くその人を窺がふに及ばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, '權勢ある者をも査ぶることを須ひずして打ほろぼし他の人々を立て之に替たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'かくの如く彼らの所爲を知り 夜の間に彼らを覆がへしたまへば彼らは乃て滅ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, '人の觀るところにて彼等を惡人のごとく撃たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, '是は彼ら背きて之に從はずその道を全たく顧みざるに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'かれら是のごとくして遂に貧しき者の號呼を彼の許に逹らしめ患難者の號呼を彼に聽しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'かれ平安を賜ふ時には誰か惡しと言ふことをえんや 彼面をかくしたまふ時には誰かこれを見るを得んや 一國におけるも一人におけるも凡て同じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'かくのごとく邪曲なる者をして世を治むること無らしめ 民の機檻となることなからしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, '人は宜しく神に申すべし 我は已に懲しめられたり再度惡き事を爲じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'わが見ざる所は請ふ我にをしへたまへ 我もし惡き事を爲たるならば重ねて之をなさじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'かれ豈なんぢの好むごとくに應報をなしたまはんや 然るに汝はこれを咎む 然ばなんぢ自ら之を選ぶべし 我は爲じ 汝の知るところを言へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, '心ある人々は我に言ん 我に聽ところの智慧ある人々は言ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'ヨブの言ふ所は辨知なし その言詞は明哲からずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'ねがはくはヨブ終まで試みられんことを其は惡き人のごとくに應答をなせばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'まことに彼は自己の罪に愆を加へわれらの中間にありて手を拍ちかつ言詞を繁くして神に逆らふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'エリフまた答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'なんぢは言ふ 我が義しきは神に愈れりと なんぢ之を正しとおもふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'すなはち汝いへらく 是は我に何の益あらんや 罪を犯すに較ぶれば何の愈るところか有んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'われ言詞をもて汝およびなんぢにそへる汝の友等に答へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, '天を仰ぎて見よ 汝の上なる高き空を望め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'なんぢ罪を犯すとも神に何の害か有ん 愆を熾んにするとも神に何を爲えんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, '汝正義かるとも神に何を與るを得んや 神なんぢの手より何をか受たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'なんぢの惡は只なんぢに同じき人を損ぜん而已 なんぢの善は只人の子を益せんのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, '暴虐の甚だしきに因て叫び 權勢ある者の腕に壓れて呼はる人々あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, '然れども一人として我を造れる神は何處にいますやといふ者なし 彼は人をして夜の中に歌を歌ふに至らしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, '地の獸畜よりも善くわれらを敎へ 空の鳥よりも我らを智からしめたまふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, '惡き者等の驕傲ぶるに因て斯のごとく人々叫べども應ふる者あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, '虚しき語は神かならず之を聽たまはず 全能者これを顧みたまはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, '汝は我かれを見たてまつらずと言といへども審判は神の前にあり この故に汝彼を待べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, '今かれ震怒をもて罰することを爲ず 罪愆を深く心に留たまはざる(が如くなる)に因て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'ヨブ口を啓きて虚しき事を述べ無知の言語を繁くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'エリフまた言詞を繼て曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '暫らく我に容せ我なんぢに示すこと有ん 尚神のために言ふべき事あればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'われ廣くわが知識を取り我の造化主に正義を歸せんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'わが言語は眞實に虚僞ならず 知識の完全き者なんぢの前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, '視よ神は權能ある者にましませども何をも藐視めたまはず その了知の能力は大なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, '惡しき者を生し存ず 艱難者のために審判を行ひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, '義しき者に目を離さず 位にある王等とともに永遠に坐せしめて之を貴くしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'もし彼ら鏈索に繋がれ 艱難の繩にかかる時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, '彼らの所行と愆尤とを示してその驕れるを知せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, '彼らの耳を開きて敎を容れしめ かつ惡を離れて歸れよと彼らに命じたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'もし彼ら聽したがひて之に事へなば繁昌てその日を送り 樂しくその年を渉らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, '若かれら聽したがはずば刀劍にて亡び 知識を得ずして死なん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'しかれども心の邪曲なる者等は忿怒を蓄はへ 神に縛しめらるるとも祈ることを爲ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'かれらは年わかくして死亡せ 男娼とその生命をひとしうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, '神は艱難者を艱難によりて救ひ 之が耳を虐遇によりて開きたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, '然ば神また汝を狹きところより出して狹からぬ廣き所に移したまふあらん 而して汝の席に陳ぬる物は凡て肥たる物ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, '今は惡人の鞫罰なんぢの身に充り 審判と公義となんぢを執ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'なんぢ忿怒に誘はれて嘲笑に陷いらざるやう愼しめよ 收贖の大なるが爲に自ら誤るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'なんぢの號叫なんぢを艱難の中より出さんや 如何に力を盡すとも所益あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, '世の人のその處より絶る其夜を慕ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, '愼しみて惡に傾むくなかれ 汝は艱難よりも寧ろ之を取んとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'それ神はその權能をもて大なる事を爲したまふ 誰か能く彼のごとくに敎晦を埀んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'たれか彼のためにその道を定めし者あらんや 誰かなんぢは惡き事をなせりと言ふことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'なんぢ神の御所爲を讚歎ふることを忘れざれ これ世の人の歌ひ崇むる所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, '人みな之を仰ぎ觀る 遠き方より人これを視たてまつるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, '神は大なる者にいまして我儕かれを知たてまつらず その御年の數は計り知るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'かれ水を細にして引あげたまへば霧の中に滴り出て雨となるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, '雲これを降せて人々の上に沛然に灌ぐなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'たれか能く雲の舒展る所以 またその幕屋の響く所以を了知んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, '視よ彼その光明を自己の周圍に繞らし また海の底をも蔽ひたまひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'これらをもて民を鞫き また是等をもて食物を豐饒に賜ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, '電光をもてその兩手を包み その電光に命じて敵を撃しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'その鳴聲かれを顯はし 家畜すらも彼の來ますを知らすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, '之がためにわが心わななき その處を動き離る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, '神の聲の響およびその口より出る轟聲を善く聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'これを天が下に放ち またその電光を地の極にまで至らせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'その後聲ありて打響き 彼威光の聲を放ちて鳴わたりたまふ その御聲聞えしむるに當りては電光を押へおきたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, '神奇しくも御聲を放ちて鳴わたり 我儕の知ざる大なる事を行ひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'かれ雪にむかひて地に降れと命じたまふ 雨すなはちその權能の大雨にも亦しかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, '斯かれ一切の人の手を封じたまふ 是すべての人にその御工作を知しめんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'また獸は穴にいりてその洞に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, '南方の密室より暴風きたり 北より寒氣きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, '神の氣吹によりて氷いできたり 水の寛狹くせらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'かれ水をもて雲に搭載せまた電光の雲を遠く散したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, '是は神の導引によりて週る 是は彼の命ずるところを盡く世界の表面に爲んがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'その之を來らせたまふは或は懲罰のため あるひはその地のため 或は恩惠のためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'ヨブよ是を聽け 立ちて神の奇妙き工作を考がへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, '神いかに是等に命を傳へその雲の光明をして輝やかせたまふか汝これを知るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'なんぢ雲の平衡知識の全たき者の奇妙き工作を知るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, '南風によりて地の穩かになる時なんぢの衣服は熱くなるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'なんぢ彼とともに彼の堅くして鑄たる鏡のごとくなる蒼穹を張ることを能せんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'われらが彼に言ふべき事を我らに敎へよ 我らは暗昧して言詞を列ぬること能はざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'われ語ることありと彼に告ぐべけんや 人あに滅ぼさるることを望まんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, '人いまは雲霄に輝やく光明を見ること能はず 然れど風きたりて之を吹清む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, '北より黄金いできたる 神には畏るべき威光あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, '全能者はわれら測りきはむることを得ず 彼は能おほいなる者にいまし審判をも公義をも抂たまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'この故に人々かれを畏る 彼はみづから心に有智とする者をかへりみたまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, '茲にヱホバ大風の中よりヨブに答へて宣まはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '無智の言詞をもて道を暗からしむる此者は誰ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'なんぢ腰ひきからげて丈夫のごとくせよ 我なんぢに問ん 汝われに答へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, '地の基を我が置たりし時なんぢは何處にありしや 汝もし穎悟あらば言へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'なんぢ若知んには誰が度量を定めたりしや 誰が準繩を地の上に張りたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'その基は何の上に奠れたりしや その隅石は誰が置たりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'かの時には晨星あひともに歌ひ 神の子等みな歡びて呼はりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, '海の水ながれ出で 胎内より涌いでし時誰が戸をもて之を閉こめたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'かの時我雲をもて之が衣服となし 黑暗をもて之が襁褓となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'これに我法度を定め關および門を設けて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, '曰く此までは來るべし此を越べからず 汝の高浪ここに止まるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'なんぢ生れし日より以來朝にむかひて命を下せし事ありや また黎明にその所を知しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'これをして地の縁を取へて惡き者をその上より振落さしめたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, '地は變りて土に印したるごとくに成り 諸の物は美はしき衣服のごとくに顯る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'また惡人はその光明を奪はれ 高く擧たる手は折らる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'なんぢ海の泉源にいたりしことありや 淵の底を歩みしことありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, '死の門なんぢのために開けたりしや 汝死蔭の門を見たりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'なんぢ地の廣を看きはめしや 若これを盡く知ば言へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, '光明の在る所に往く路は孰ぞや 黑暗の在る所は何處ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'なんぢ之をその境に導びき得るや その家の路を知をるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'なんぢ之を知ならん汝はかの時すでに生れをり また汝の經たる日の數も多ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'なんぢ雪の庫にいりしや 雹の庫を見しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'これ我が艱難の時にために蓄はへ 戰爭および戰鬪の日のために蓄はへ置くものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, '光明の發散る道 東風の地に吹わたる所の路は何處ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, '誰が大雨を灌ぐ水路を開き雷電の光の過る道を開き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, '人なき地にも人なき荒野にも雨を降し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, '荒かつ廢れたる處々を潤ほし かつ若菜蔬を生出しむるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, '雨に父ありや 露の珠は誰が生る者なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, '氷は誰が胎より出るや 空の霜は誰が產むところなるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, '水かたまりて石のごとくに成り 淵の面こほる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'なんぢ昴宿の鏈索を結びうるや 參宿の繋繩を解うるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'なんぢ十二宮をその時にしたがひて引いだし得るや また北斗とその子星を導びき得るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'なんぢ天の常經を知るや 天をして其權力を地に施こさしむるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'なんぢ聲を雲に擧げ滂沛の水をして汝を掩はしむるを得るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'なんぢ閃電を遣はして往しめ なんぢに答へて我儕は此にありと言しめ得るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, '胸の中の智慧は誰が與へし者ぞ 心の内の聰明は誰が授けし者ぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'たれか能く智慧をもて雲を數へんや たれか能く天の瓶を傾むけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, '塵をして一塊に流れあはしめ土塊をしてあひかたまらしめんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'なんぢ牝獅子のために食物を獵や また小獅子の食氣を滿すや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'その洞穴に伏し 森の中に隱れ伺がふ時なんぢこの事を爲うるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'また鴉の子 神にむかひて呼はり 食物なくして徘徊る時 鴉に餌を與ふる者は誰ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'なんぢ岩間の山羊が子を產む時をしるや また麀鹿の產に臨むを見しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'なんぢ是等の在胎の月を數へうるや また是等が產む時を知るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'これらは身を鞠めて子を產みその痛苦を出す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'またその子は強くなりて野に育ち 出ゆきて再たびその親にかへらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, '誰が野驢馬を放ちて自由にせしや 誰が野驢馬の繋繩を解しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'われ野をその家となし 荒野をその住所となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, '是は邑の喧閙を賤しめ 馭者の號呼を聽いれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, '山を走まはりて草を食ひ 各種の靑き物を尋ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, '兕肯て汝に事へ なんぢの飼草槽の傍にとどまらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'なんぢ兕に綱附て阡陌をあるかせ得んや 是あに汝にしたがひて谷に馬鈀を牽んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'その力おほいなればとて汝これに恃まんや またなんぢの工事をこれに任せんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'なんぢこれにたよりて己が穀物を運びかへらせ之を打禾塲にあつめしめんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, '駝鳥は歡然にその翼を皷ふ 然どもその羽と毛とはあに鶴にしかんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, '是はその卵を土の中に棄おき これを砂の中にて暖たまらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, '足にてその潰さるべきと 野の獸のこれを踐むべきとを思はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'これはその子に情なくして宛然おのれの子ならざるが如くし その劬勞の空しくなるも繋念ところ無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, '是は神これに智慧を授けず穎悟を與へざるが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'その身をおこして走るにおいては馬をもその騎手をも嘲けるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'なんぢ馬に力を與へしや その頸に勇ましき鬣を粧ひしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'なんぢ之を蝗蟲のごとく飛しむるや その嘶なく聲の響は畏るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, '谷を踋爬て力に誇り 自ら進みて兵士に向ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, '懼るることを笑ひて驚ろくところ無く 劍にむかふとも退ぞかず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, '矢筒その上に鳴り 鎗に矛あひきらめく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, '猛りつ狂ひつ地を一呑にし 喇叭の聲鳴わたるも立どまる事なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, '喇叭の鳴ごとにハーハーと言ひ遠方より戰鬪を嗅つけ 將帥の大聲および吶喊聲を聞しる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, '鷹の飛かけり その羽翼を舒て南に向ふは豈なんぢの智慧によるならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, '鷲の翔のぼり 高き處に巣を營なむは豈なんぢの命令に依んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'これは岩の上に住所を構へ 岩の尖所または峻險き所に居り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, '其處よりして攫むべき物をうかがふ その目のおよぶところ遠し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'その子等もまた血を吸ふ 凡そ殺されし者のあるところには是そこに在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'ヱホバまたヨブに對へて言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '非難する者ヱホバと爭はんとするや 神と論ずる者これに答ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'ヨブ是においてヱホバに答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '嗚呼われは賤しき者なり 何となんぢに答へまつらんや 唯手をわが口に當んのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'われ已に一度言たり 復いはじ 已に再度せり 重ねて述じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, '是に於てヱホバまた大風の中よりヨブに應へて言たまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'なんぢ腰ひきからげて丈夫のごとくせよ 我なんぢに問ん なんぢ我にこたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'なんぢ我審判を廢んとするや 我を非として自身を是とせんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'なんぢ神のごとき腕ありや 神のごとき聲をもて轟きわたらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'さればなんぢ威光と尊貴とをもて自ら飾り 榮光と華美とをもて身に纒へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'なんぢの溢るる震怒を洩し 高ぶる者を視とめて之をことごとく卑くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'すなはち高ぶる者を見てこれを盡く鞠ませ また惡人を立所に踐つけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'これを塵の中に埋め これが面を隱れたる處に閉こめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'さらば我もなんぢを讚てなんぢの右の手なんぢを救ひ得ると爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, '今なんぢ我がなんぢとともに造りたりし河馬を視よ 是は牛のごとく草を食ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, '觀よその力は腰にあり その勢力は腹の筋にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'その尾の搖く樣は香柏のごとく その腿の筋は彼此に盤互ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'その骨は銅の管ごとくその肋骨は鐡の棒のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'これは神の工の第一なる者にして之を造りし者これに劍を賦けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, '山もこれがために食物を產出し もろもろの野獸そこに遊ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'これは蓮の樹の下に臥し 葦蘆の中または沼の裏に隱れをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, '蓮の樹その蔭をもてこれを覆ひ また河の柳これを環りかこむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'たとひ河荒くなるとも驚ろかず ヨルダンその口に注ぎかかるも惶てず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'その目の前にて誰か之を執ふるを得ん 誰か羂をその鼻に貫ぬくを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'なんぢ鈎をもて鱷を釣いだすことを得んや その舌を糸にひきかくることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'なんぢ葦の繩をその鼻に通し また鈎をその齶に衝とほし得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, '是あに頻になんぢに願ふことをせんや 柔かになんぢに言談んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'あに汝と契約を爲んや なんぢこれを執て永く僕と爲しおくを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'なんぢ鳥と戲むるる如くこれとたはむれ また汝の婦人等のために之を繋ぎおくを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'また漁夫の社會これを商貨と爲して商賣人の中間に分たんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'なんぢ漁叉をもてその皮に滿し 魚矛をもてその頭を衝とほし得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, '手をこれに下し見よ 然ばその戰鬪をおぼえて再びこれを爲ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, '視よその望は虚し 之を見てすら倒るるに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, '何人も之に激する勇氣あるなし 然ば誰かわが前に立うる者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, '誰か先に我に與へしところありて我をして之に酬いしめんとする者あらん 普天の下にある者はことごとく我有なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, '我また彼者の肢體とその著るしき力とその美はしき身の構造とを言では措じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, '誰かその外甲を剥ん 誰かその雙齶の間に入ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, '誰かその面の戸を開きえんや その周圍の齒は畏るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'その並列る鱗甲は之が誇るところ その相闔たる樣は堅く封じたるがごとく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, '此と彼とあひ接きて風もその中間にいるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, '一々あひ連なり堅く膠て離すことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, '嚔すれば即はち光發す その目は曙光の眼瞼(を開く)に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'その口よりは炬火いで火花發し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'その鼻の孔よりは煙いできたりて宛然葦を焚く釜のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'その氣息は炭火を爇し 火燄その口より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, '力氣その頸に宿る 懼るる者その前に彷徨まよふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'その肉の片は密に相連なり 堅く身に着て動かす可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'その心の堅硬こと石のごとく その堅硬こと下磨のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'その身を興す時は勇士も戰慄き 恐怖によりて狼狽まどふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '劍をもて之を撃とも利ず 鎗も矢も漁叉も用ふるところ無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '是は鐡を見ること稿のごとくし銅を見ること朽木のごとくす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '弓箭もこれを逃しむること能はず 投石機の石も稿屑と見做る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '棒も是には稿屑と見ゆ 鎗の閃めくを是は笑ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'その下腹には瓦礫の碎片を連ね 泥の上に麥打車を引く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '淵をして鼎のごとく沸かへらしめ 海をして香油の釜のごとくならしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '己が後に光る道を遺せば淵は白髮をいただけるかと疑がはる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '地の上には是と並ぶ者なし 是は恐怖なき身に造られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '是は一切の高大なる者を輕視ず 誠に諸の誇り高ぶる者の王たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'ヨブ是に於てヱホバに答へて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '我知る汝は一切の事をなすを得たまふ また如何なる意志にても成あたはざる無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '無知をもて道を蔽ふ者は誰ぞや 斯われは自ら了解らざる事を言ひ 自ら知ざる測り難き事を述たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, '請ふ聽たまへ 我言ふところあらん 我なんぢに問まつらん 我に答へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'われ汝の事を耳にて聞ゐたりしが今は目をもて汝を見たてまつる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, '是をもて我みづから恨み 塵灰の中にて悔ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'ヱホバ是等の言語をヨブに語りたまひて後ヱホバ、テマン人エリパズに言たまひけるは我なんぢと汝の二人の友を怒る 其はなんぢらが我に關て言述べたるところはわが僕ヨブの言たることのごとく正當からざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, '然ば汝ら牡牛七頭 牡羊七頭を取てわが僕ヨブに至り汝らの身のために燔祭を獻げよ わが僕ヨブなんぢらのために祈らん われかれを嘉納べければ之によりて汝らの愚を罰せざらん 汝らの我について言述たるところは我僕ヨブの言たることのごとく正當からざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, '是においてテマン人エリパズ、シユヒ人ビルダデ、ナアマ人ゾパル往てヱホバの自己に宣まひしごとく爲ければヱホバすなはちヨブを嘉納たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'ヨブその友のために祈れる時 ヱホバ、ヨブの艱難をときて舊に復ししかしてヱホバつひにヨブの所有物を二倍に増たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, '是において彼の諸の兄弟諸の姉妹およびその舊相識る者等ことごとく來りて彼とともにその家にて飮食を爲しかつヱホバの彼に降したまひし一切の災難につきて彼をいたはり慰さめ また各金一ケセタと金の環一箇を之に贈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'ヱホバかくのごとくヨブをめぐみてその終を初よりも善したまへり 即ち彼は綿羊一萬四千匹 駱駝六千匹 牛一千軛 牝驢馬一千匹を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'また男子七人 女子三人ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'かれその第一の女をエミマと名け第二をケジアと名け 第三をケレンハツプクと名けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, '全國の中にてヨブの女子等ほど美しき婦人は見えざりき その父之にその兄弟等とおなじく產業をあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'この後ヨブは百四十年いきながらへてその子その孫と四代までを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'かくヨブは年老い日滿て死たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, '惡きものの謀略にあゆまず つみびとの途にたたず 嘲るものの座にすわらぬ者はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'かかる人はヱホバの法をよろこびて日も夜もこれをおもふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'かかる人は水流のほとりにうゑし樹の期にいたりて實をむすび 葉もまた凋まざるごとく その作ところ皆さかえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'あしき人はしからず 風のふきさる粃糠のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, '然ばあしきものは審判にたへず罪人は義きものの會にたつことを得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'そはヱホバはただしきものの途をしりたまふ されど惡きものの途はほろびん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, '何なればもろもろの國人はさわぎたち諸民はむなしきことを謀るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, '地のもろもろの王はたちかまへ群伯はともに議り ヱホバとその受膏者とにさからひていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'われらその械をこぼち その繩をすてんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, '天に坐するもの笑ひたまはん 主かれらを嘲りたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'かくて主は忿恚をもてものいひ大なる怒をもてかれらを怖まどはしめて宣給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'しかれども我わが王をわがきよきシオンの山にたてたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'われ詔命をのべんヱホバわれに宣まへり なんぢはわが子なり今日われなんぢを生り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'われに求めよ さらば汝にもろもろの國を嗣業としてあたへ地の極をなんぢの有としてあたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, '汝くろがねの杖をもて彼等をうちやぶり陶工のうつはもののごとくに打碎かんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'されば汝等もろもろの王よ さとかれ地の審士輩をしへをうけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, '畏をもてヱホバにつかへ戰慄をもてよろこべ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, '子にくちつけせよ おそらくはかれ怒をはなちなんぢら途にほろびんその忿恚はすみやかに燃べければなり すべてかれに依賴むものは福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'ダビデその子アブサロムを避しときのうた ヱホバよ我にあたする者のいかに蔓延れるや 我にさからひて起りたつもの多し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'わが霊魂をあげつらひて かれは神にすくはるることなしといふ者ぞおほき セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'されどヱホバよ なんぢは我をかこめる盾わが榮わが首をもたげ給ふものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'われ聲をあげてヱホバによばはればその聖山より我にこたへたまふ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'われ臥していね また目さめたり ヱホバわれを支へたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'われをかこみて立かまへたる千萬の人をも我はおそれじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'ヱホバよねがはくは起たまへ わが神よわれを救ひたまへ なんぢ曩にわがすべての仇の頬骨をうち惡きものの歯ををりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, '救はヱホバにあり ねがはくは恩惠なんぢの民のうへに在んことを セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, '琴にあはせて伶長にうたはしめたるダビデの歌 わが義をまもりたまふ神よ ねがはくはわが呼るときに答へたまへ わがなやみたる時なんぢ我をくつろがせたまへり ねがはくは我をあはれみ わが祈をききたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, '人の子よなんぢらわが榮をはぢしめて幾何時をへんとするか なんぢらむなしき事をこのみ虚偽をしたひていくそのときを經んとするか セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, '然どなんぢら知れ ヱホバは神をうやまふ人をわかちて己につかしめたまひしことを われヱホバによばはらば聽たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'なんぢら愼みをののきて罪ををかすなかれ 臥床にておのが心にかたりて默せ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'なんぢら義のそなへものを献てヱホバに依賴め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'おほくの人はいふたれか嘉事をわれらに見するものあらんやと ヱホバよねがはくは聖顔の光をわれらの上にのぼらせたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'なんぢのわが心にあたへたまひし歓喜はかれらの穀物と酒との豊かなる時にまさりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'われ安然にして臥またねぶらん ヱホバよわれを獨にて坦然にをらしむるものは汝なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, '簫にあはせて伶長にうたはしめたるダビデのうた ヱホバよねがはくは我がことばに耳をかたむけ わが思にみこころを注たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'わが王よわが神よ わが號呼のこゑをききたまへ われ汝にいのればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'ヱホバよ朝になんぢわが聲をききたまはん 我あしたになんぢの爲にそなへして俟望むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'なんぢは惡きことをよろこびたまふ神にあらず 惡人はなんぢの賓客たるを得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'たかぶる者はなんぢの目前にたつをえず なんぢはすべて邪曲をおこなふものを憎みたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'なんぢは虚偽をいふ者をほろぼしたまふ 血をながすものと詭計をなすものとは ヱホバ憎みたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, '然どわれは豊かなる仁慈によりてなんぢの家にいらん われ汝をおそれつつ聖宮にむかひて拝まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'ヱホバよ願くはわが仇のゆゑになんぢの義をもて我をみちびき なんぢの途をわが前になほくしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'かれらの口には眞實なく その衷はよこしま その喉はあばける墓 その舌はへつらひをいへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, '神よねがはくはかれらを刑なひ その謀略によりてみづから仆れしめ その愆のおほきによりて之をおひいだしたまへ かれらは汝にそむきたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'されど凡てなんぢに依賴む者をよろこばせ永遠によろこびよばはらせたまへ なんぢ斯る人をまもりたまふなり 名をいつくしむ者にもなんぢによりて歓喜をえしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'ヱホバよなんぢに義者にさいはひし盾のごとく恩惠をもて之をかこみたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, '八音ある琴にあはせて伶長にうたはしめたるダビデのうた ヱホバよねがはくは忿恚をもて我をせめ烈しき怒をもて我をこらしめたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'ヱホバよわれを憐みたまへ われ萎みおとろふなり ヱホバよ我を醫したまへ わが骨わななきふるふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'わが霊魂さへも甚くふるひわななく ヱホバよかくて幾何時をへたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'ヱホバよ歸りたまへ わがたましひを救ひたまへ なんぢの仁慈の故をもて我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'そは死にありては汝をおもひいづることなし 陰府にありては誰かなんぢに感謝せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'われ歎息にてつかれたり 我よなよな床をただよはせ涙をもてわが衾をひたせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'わが目うれへによりておとろへ もろもろの仇ゆゑに老ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'なんぢら邪曲をおこなふ者ことごとく我をはなれよ ヱホバはわが泣こゑをききたまひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'ヱホバわが懇求をききたまへり ヱホバわが祈をうけたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'わがもろもろの仇ははぢて大におぢまどひ あわただしく恥てしりぞきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'ベニヤミンの人クシの言につきダビデ、ヱホバに對ひてうたへるシガヨンの歌 わが神ヱホバよわれ汝によりたのむ 願くはすべての逐せまるものより我をすくひ我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'おそらくはかれ獅の如くわが霊魂をかきやぶり援るものなき間にさきてずたずたに爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'わが神ヱホバよ もしわれ此事をなししならんには わが手によこしまの纏りをらんには');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, '故なく仇ずるものをさへ助けしに禍害をもてわが友にむくいしならんには');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'よし仇人わがたましひを逐とらへ わが生命をつちにふみにじりわが榮を塵におくとも その作にまかせよ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'ヱホバよなんぢの怒をもて起わが仇のいきどほりにむかひて立たまへ わがために目をさましたまへ なんぢは審判をおほせ出したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'もろもろの國人の會がなんぢのまはりに集はしめ 其上なる高座にかへりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'ヱホバはもろもろの民にさばきを行ひたまふ ヱホバよわが正義とわが衷なる完全とにしたがひて我をさばきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'ねがはくは惡きものの曲事をたちて義しきものを堅くしたまへ ただしき神は人のこころと腎とをさぐり知たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'わが盾をとるものは心のなほきものをすくふ神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, '神はただしき審士ひごとに忿恚をおこしたまふ神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, '人もしかへらずば神はその劍をとぎ その弓をはりてかまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'これに死の器をそなへ その矢に火をそへたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, '視よその人はよこしまを產んとしてくるしむ 殘害をはらみ虚偽をうむなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'また坑をほりてふかくし己がつくれるその溝におちいれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'その殘害はおのが首にかへり その強暴はおのが頭上にくだらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'われその義によりてヱホバに感謝し いとたかきヱホバの名をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'ギデトの琴にあはせて伶長にうたはしめたるダビデの歌 われらの主ヱホバよなんぢの名は地にあまねくして尊きかな その榮光を天におきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'なんぢは嬰兒ちのみごの口により力の基をおきて敵にそなへたまへり こは仇人とうらみを報るものを鎭靜めんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, '我なんぢの指のわざなる天を觀なんぢの設けたまへる月と星とをみるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, '世人はいかなるものなればこれを聖念にとめたまふや 人の子はいかなるものなればこれを顧みたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, '只すこしく人を神よりも卑つくりて榮と尊貴とをかうぶらせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'またこれに手のわざを治めしめ萬物をその足下におきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'すべての羊うしまた野の獣');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'そらの鳥うみの魚もろもろの海路をかよふものをまで皆しかなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'われらの主ヱホバよなんぢの名は地にあまねくして尊きかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'ムツラベン(調子の名)にあはせて伶長にうたはしめたるダビデのうた われ心をつくしてヱホバに感謝し そのもろもろの奇しき事迹をのべつたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'われ汝によりてたのしみ且よろこばん 至上者よなんぢの名をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'わが仇しりぞくとき躓きたふれて御前にほろぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'なんぢわが義とわが訟とをまもりたまへばなり なんぢはだしき審判をしつつ寳座にすわりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'またもろもろの國をせめ惡きものをほろぼし 世々かぎりなくかれらが名をけしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, '仇はたえはてて世々あれすたれたり 汝のくつがへしたまへるもろもろの邑はうせてその跡だにもなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'ヱホバはとこしへに聖位にすわりたまふ 審判のためにその寳座をまうけたまひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'ヱホバは公義をもて世をさばき 直をもてもろもろの民に審判をおこなひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'ヱホバは虐げらるるものの城また難みのときの城なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, '聖名をしるものはなんぢに依賴ん そはヱホバよなんぢを尋るものの棄られしこと斷てなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'シオンに住たまふヱホバに對ひてほめうたへ その事迹をもろもろの民のなかにのべつたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, '血を問糺したまふものは苦しむものを心にとめてその號呼をわすれたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'ヱホバよ我をあはれみたまへ われを死の門よりすくひいだしたまへる者よ ねがはくは仇人のわれを難むるを視たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'さらば我なんぢのすべての頌美をのぶるを得またシオンのむすめの門にてなんぢの救をよろこばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'もろもろの國民はおのがつくれる阱におちいり そのかくしまうけたる網におのが足をとらへらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'ヱホバは己をしらしめ審判をおこなひたまへり あしき人はおのが手のわざなる羂にかかれり ヒガイオン セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'あしき人は陰府にかへるべし 神をわするるもろもろの國民もまたしからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, '貧者はつねに忘らるるにあらず苦しむものの望はとこしへに滅ぶるにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'ヱホバよ起たまへ ねがはくは勝を人にえしめたまふなかれ御前にてもろもろのくにびとに審判をうけしめたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'ヱホバよ願くはかれらに懼をおこさしめたまへ もろもろの國民におのれただ人なることを知しめたまヘ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'ああヱホバよ何ぞはるかに立たまふや なんぞ患難のときに匿れたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'あしき人はたかぶりて苦しむものを甚だしくせむ かれらをそのくはだての謀略にとらはれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'あしきひとは己がこころの欲望をほこり貪るものを祝してヱホバをかろしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'あしき人はほこりかにいふ 神はさぐりもとむることをせざるなりと 凡てそのおもひに神なしとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'かれの途はつねに堅く なんぢの審判はその眼よりはなれてたかし 彼はそのもろもろの敵をくちさきらにて吹く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'かくて己がこころの中にいふ 我うごかさるることなく世々われに禍害なかるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'その口にはのろひと虚偽としへたげとみち その舌のしたには殘害とよこしまとあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'かれは村里のかくれたる處にをり隠やかなるところにて罪なきものをころす その眼はひそかに倚仗なきものをうかがひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, '窟にをる獅のごとく潜みまち苦しむものをとらへんために伏ねらひ 貧しきものをその網にひきいれてとらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'また身をかがめて蹲まるその強勁によりて依仗なきものは仆る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'かれ心のうちにいふ 神はわすれたり神はその面をかくせり神はみることなかるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'ヱホバよ起たまへ 神よ手をあげたまへ 苦しむものを忘れたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'いかなれば惡きもの神をいやしめて心中になんぢ探求むることをせじといふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'なんぢは鍳たまへりその殘害と怨恨とを見てこれに手をくだしたまへり 倚仗なきものは身をなんぢに委ぬ なんぢは昔しより孤子をたすけたまふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'ねがはくは惡きものの臂ををりたまへあしきものの惡事を一つだにのこらぬまでに探究したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'ヱホバはいやとほながに王なり もろもろの國民はほろびて神の國より跡をたちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'ヱホバよ汝はくるしむものの懇求をききたまへり その心をかたくしたまはん なんぢは耳をかたぶけてきき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, '孤子と虐げらる者とのために審判をなし地につける人にふたたび恐嚇をもちひざらしめ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'うたのかみに謳はしめたるダビデのうた われヱホバに依賴めり なんぢら何ぞわが霊魂にむかひて鳥のごとくなんぢの山にのがれよといふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, '視よあしきものは暗處にかくれ心なほきものを射んとて弓をはり絃に矢をつがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, '基みなやぶれたらんには義者なにをなさんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'ヱホバはその聖宮にいます ヱホバの寳座は天にありその目はひとのこを鑒 その眼瞼はかれらをこころみたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'ヱホバは義者をこころむ そのみこころは惡きものと強暴をこのむ者とをにくみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, '羂をあしきもののうへに降したまはん火と硫磺ともゆる風とはかれらの酒杯にうくべきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'ヱホバはただしき者にして義きことを愛したまへばなり 直きものはその聖顔をあふぎみん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, '八音にあはせて伶長にうたはしめたるダビデのうた ああヱホバよ助けたまへ そは神をうやまふ人はたえ誠あるものは人の子のなかより消失るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, '人はみな虚偽をもてその隣とあひかたり滑なるくちびると貳心とをもてものいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'ヱホバはすべての滑なるくちびると大なる言をかたる舌とをほろぼし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'かれらはいふ われら舌をもて勝をえん この口唇はわがものなり誰かわれらに主たらんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'ヱホバのたまはく 苦しむもの掠められ貧しきもの歎くがゆゑに我いま起てこれをその慕ひもとむる平安におかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'ヱホバの言はきよきことばなり 地にまうけたる爐にてねり七次きよめたる白銀のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'ヱホバよ汝はかれらをまもり之をたすけてとこしへにこの類より免れしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, '人の子のなかに穢しきことの崇めらるるときは惡者ここやかしこにあるくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, '伶長にうたはしめたるダビデのうた ああヱホバよ かくて幾何時をへたまふや 汝とこしへに我をわすれたまふや 聖顔をかくしていくそのときを歴たまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'われ心のうちに終日かなしみをいだき籌畫をたましひに用ひて幾何時をふべきか わが仇はわがうへに崇められて幾何時をふべきか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'わが神ヱホバよ我をかへりみて答をなしたまへ わが目をあきらかにしたまへ 恐らくはわれ死の睡につかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'おそらくはわが仇いはん 我かれに勝りと おそらくはわが敵わがうごかさるるによりて喜ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'されど我はなんぢの憐憫によりたのみ わが心はなんぢの救によりてよろこばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'ヱホバはゆたかに我をあしらひたまひたれば われヱホバに對ひてうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'うたのかみに謳はしめたるダビデのうた 愚なるものは心のうちに神なしといへり かれらは腐れたり かれらは憎むべき事をなせり 善をおこなふ者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'ヱホバ天より人の子をのぞみみて悟るもの神をたづぬる者ありやと見たまひしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'みな逆きいでてことごとく腐れたり 善をなすものなし一人だになし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, '不義をおこなふ者はみな智覺なきか かれらは物くふごとくわが民をくらひ またヱホバをよぶことをせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, '視よかかる時かれらは大におそれたり 神はただしきものの類のなかに在せばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'なんぢらは苦しめるものの謀略をあなどり辱かしむ されどヱホバはその避所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'ねがはくはシオンよりイスラエルの救のいでんことを ヱホバその民のとらはれたるを返したまふときヤコブはよろこびイスラエルは樂まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'ダビデのうた ヱホバよなんぢの帷幄のうちにやどらん者はたれぞ なんぢの聖山にすまはんものは誰ぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, '直くあゆみ義をおこなひ そのこころに眞實をいふものぞその人なる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'かかる人は舌をもてそしらず その友をそこなはず またその隣をはぢしむる言をあげもちひず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, '惡にしづめるものを見ていとひかろしめ ヱホバをおそるるものをたふとび 誓ひしことはおのれに禍害となるも變ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, '貨をかして過たる利をむさぼらず 賄賂をいれて無辜をそこなはざるなり 斯ることどもを行ふものは永遠にうごかさるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'ダビデがミクタムの歌 神よねがはくは我を護りたまへ 我なんぢに依賴む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'われヱホバにいへらくなんぢはわが主なり なんぢのほかにわが福祉はなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, '地にある聖徒はわが極めてよろこぶ勝れしものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'ヱホバにかへて他神をとるものの悲哀はいやまさん 我かれらがささぐる血の御酒をそそがず その名を口にとなふることをせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'ヱホバはわが嗣業またわが酒杯にうくべき有なり なんぢはわが所領をまもりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, '準繩はわがために樂しき地におちたり 宜われよき嗣業をえたるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'われは訓諭をさづけたまふヱホバをほめまつらん 夜はわが心われををしふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'われ常にヱホバをわが前におけり ヱホバわが右にいませばわれ動かさるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'このゆゑにわが心はたのしみ わが榮はよろこぶ わが身もまた平安にをらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'そは汝わがたましひを陰府にすておきたまはず なんぢの聖者を墓のなかに朽しめたまはざる可ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'なんぢ生命の道をわれに示したまはん なんぢの前には充足るよろこびあり なんぢの右にはもろもろの快樂とこしへにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'ダビデの祈祷 ああヱホバよ公義をききたまへ わが哭聲にみこころをとめたまへ いつはりなき口唇よりいづる我がいのりに耳をかたぶけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'ねがはくはわが宣告みまへよりいでてなんぢの目公平をみたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'なんぢわが心をこころみ また夜われにのぞみたまへり 斯てわれを糺したまへど我になにの惡念あるをも見出たまはざりき わが口はつみを犯すことなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, '人の行爲のことをいはば我なんぢのくちびるの言によりて暴るものの途をさけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'わが歩はかたくなんぢの途にたちわが足はよろめくことなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, '神よなんぢ我にこたへたまふ 我なんぢをよべり ねがはくは汝の耳をかたぶけてわが陳るところをききたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'なんぢに依賴むものを右手をもて仇するものより救ひたまふ者よ ねがはくはなんぢの妙なる仁慈をあらはしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, '願くはわれを瞳のごとくにまもり汝のつばさの蔭にかくし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, '我をなやむるあしき者また我をかこみてわが命をそこなはんとする仇よりのがれしめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'かれらはおのが心をふさぎ その口をもて誇かにものいへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'いづこにまれ往ところにてわれらを打圍み われらを地にたふさんと目をとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'かれは抓裂んといらだつ獅のごとく隠やかなるところに潜みまつ壯獅のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'ヱホバよ起たまへ ねがはくはかれに立對ひてこれをたふし御劍をもて惡きものよりわが霊魂をすくひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'ヱホバよ手をもて人より我をたすけいだしたまへ おのがうくべき有をこの世にてうけ 汝のたからにてその腹をみたさるる世人より我をたすけいだし給へ かれらはおほくの子にあきたり その富ををさなごに遺す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'されどわれは義にありて聖顔をみ目さむるとき容光をもて飽足ることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, '伶長にうたはしめたるヱホバの僕ダビデの歌、このうたの詞はもろもろの仇およびサウルの手より救れしときヱホバに對ひてうたへるなり 云く ヱホバわれの力よ われ切になんぢを愛しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'ヱホバはわが巌 わが城 われをすくふ者 わがよりたのむ神 わが堅固なるいはほ わが盾 わがすくひの角 わがたかき櫓なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'われ讃稱ふべきヱホバをよびて仇人よりすくはるることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, '死のつな我をめぐり惡のみなぎる流われをおそれしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, '陰間のなは我をかこみ死のわな我にたちむかへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'われ窮苦のうちにありてヱホバをよび又わが神にさけびたり ヱホバはその宮よりわが聲をききたまふ その前にてわがよびし聲はその耳にいれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'このときヱホバ怒りたまひたれば地はふるひうごき山の基はゆるぎうごきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, '烟その鼻よりたち火その口よりいでてやきつくし炭はこれがために燃あがれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'ヱホバは天をたれて臨りたまふ その足の下はくらきこと甚だし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'かくてケルブに乗りてとび風のつばさにて翔り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, '闇をおほひとなし水のくらきとそらの密雲とをそのまはりの幕となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'そのみまへの光輝よりくろくもをへて雹ともえたる炭とふりきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'ヱホバは天に雷鳴をとどろかせたまへり 至上者のこゑいでて雹ともえたる炭とふりきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'ヱホバ矢をとばせてかれらを打ちらし數しげき電光をはなちてかれらをうち敗りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'ヱホバよ斯るときになんぢの叱咤となんぢの鼻のいぶきとによりて水の底みえ地の基あらはれいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'ヱホバはたかきより手をのべ我をとりて大水よりひきあげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'わがつよき仇とわれを憎むものとより我をたすけいだしたまへり かれらは我にまさりて最強かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'かれらはわが災害の日にせまりきたれり 然どヱホバはわが支柱となりたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'ヱホバはわれを悦びたまふがゆゑにわれをたづさへ廣處にだして助けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'ヱホバはわが正義にしたがひて恩賜をたまひ わが手のきよきにしたがひて報賞をたれたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'われヱホバの道をまもり惡をなしてわが神よりはなれしことなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'そのすべての審判はわがまへにありて われその律法をすてしことなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'われ神にむかひて缺るところなく己をまもりて不義をはなれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'この故にヱホバはわがただしきとその目前にわが手のきよきとにしたがひて我にむくいをなし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'なんぢ憐憫あるものには憐みあるものとなり完全ものには全きものとなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'きよきものには潔きものとなり僻むものにはひがむ者となりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'そは汝くるしめる民をすくひたまへど高ぶる目をひくくしたまふ可ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'なんぢわが燈火をともし給ふべければなり わが神ヱホバわが暗をてらしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, '我なんぢによりて軍の中をはせとほり わが神によりて垣ををどりこゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, '神はしもその途またくヱホバの言はきよし ヱホバはすべて依賴むものの盾なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'そはヱホバのほかに神はたれぞや われらの神のほかに巌はたれぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, '神はちからをわれに帶しめ わが途を全きものとなしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, '神はわが足を麀のあしのごとくし我をわが高處にたたせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, '神はわが手をたたかひにならはせてわが臂に銅弓をひくことを得しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, '又なんぢの救の盾をわれにあたへたまへり なんぢの右手われをささへなんぢの謙卑われを大ならしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'なんぢわが歩むところを寛濶ならしめたまひたれば わが足ふるはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'われ仇をおひてこれに追及かれらのほろぶるまでは歸ることをせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'われかれらを撃てたつことを得ざらしめん かれらはわが足の下にたふるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'そはなんぢ戰爭のために力をわれに帶しめ われにさからひておこりたつ者をわが下にかがませたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, '我をにくむ者をわが滅しえんがために汝またわが仇の背をわれにむけしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'かれら叫びたれども救ふものなく ヱホバに對ひてさけびたれども答へたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, '我かれらを風のまへの塵のごとくに搗碎き ちまたの坭のごとくに打棄たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'なんぢわれを民のあらそひより助けいだし我をたててもろもろの國の長となしたまへり わがしらざる民われにつかへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'かれらわが事をききて立刻われにしたがひ異邦人はきたりて佞りつかへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'ことくにびとは衰へてその城よりをののきいでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'ヱホバは活ていませり わが磐はほむべきかな わがすくひの神はあがむべきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'わがために讎をむくい異邦人をわれに服はせたまふはこの神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, '神はわれを仇よりすくひたまふ實になんぢは我にさからひて起りたつ者のうへに我をあげ あらぶる人より我をたすけいだし給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'この故にヱホバよ われもろもろの國人のなかにてなんぢに感謝し なんぢの名をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'ヱホバはおほいなる救をその王にあたへ その受膏者ダビデとその裔とに世々かぎりなく憐憫をたれたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'うたのかみに謳はしめたるダビデのうた もろもろの天は神のえいくわうをあらはし 穹蒼はその手のわざをしめす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'この日ことばをかの日につたへこのよ知識をかの夜におくる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, '語らずいはずその聲きこえざるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'そのひびきは全地にあまねく そのことばは地のはてにまでおよぶ 神はかしこに帷幄を日のためにまうけたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, '日は新婿がいはひの殿をいづるごとく勇士がきそひはしるをよろこぶに似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'そのいでたつや天の涯よりし その運りゆくや天のはてにいたる 物としてその和喣をかうぶらざるはなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'ヱホバの法はまたくして霊魂をいきかへらしめ ヱホバの證詞はかたくして愚なるものを智からしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'ヱホバの訓諭はなほくして心をよろこばしめ ヱホバの誡命はきよくして眼をあきらかならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'ヱホバを惶みおそるる道はきよくして世々にたゆることなく ヱホバのさばきは眞實にしてことごとく正し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'これを黄金にくらぶるもおほくの純精金にくらぶるも 彌増りてしたふべく これを蜜にくらぶるも蜂のすの滴瀝にくらぶるもいやまさりて甘し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'なんぢの僕はこれらによりて儆戒をうく これらをまもらば大なる報賞あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'たれかおのれの過失をしりえんや ねがはくは我をかくれたる愆より解放ちたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, '願くはなんぢの僕をひきとめて故意なる罪ををかさしめず それをわが主たらしめ給ふなかれ さればわれ玷なきものとなりて大なる愆をまぬかるるをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'ヱホバわが磐わが贖主よ わがくちの言わがこころの思念なんぢのまへに悦ばるることを得しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, '伶長にうたはしめたるダビデのうた ねがはくはヱホバなやみの日になんぢにこたヘヤユブのかみの名なんぢを高にあげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, '聖所より援助をなんぢにおくりシオンより能力をなんぢにあたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, '汝のもろもろの献物をみこころにとめ なんぢの燔祭をうけたまはんことを セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'ねがはくはなんちがこころの願望をゆるし なんぢの謀略をことごとく遂しめたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, '我儕なんぢの救によりて歓びうたひ われらの神の名によりて旗をたてん ねがはくはヱホバ汝のもろもろの求をとげしめたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'われ今ヱホバその受膏者をすくひたまふを知る ヱホバそのきよき天より右手なるすくひの力にてかれに應へたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'あるひは車をたのみあるひは馬をたのみとする者あり されどわれらはわが神ヱホバの名をとなへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'かれらは屈みまた仆るわれらは起てかたくたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'ヱホバよ王をすくひたまへ われらがよぶとき應へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, '伶長にうたはしめたるダビデのうた ヱホバよ王はなんぢの力によりてたのしみ汝のすくひによりて奈何におほいなる歓喜をなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'なんぢ彼がこころの願望をゆるし そのくちびるの求をいなみ給はざりき セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'そはよきたまものの惠をもてかれを迎へ まじりなきこがねの冕弁をもてかれの首にいただかせ給ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'かれ生命をもとめしに汝これをあたへてその齢の日を世々かぎりなからしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'なんぢの救によりてその榮光おほいなり なんぢは尊貴と稜威とをかれに衣せたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'そは之をとこしへに福ひなるものとなし聖顔のまへの歓喜をもて樂しませたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, '王はヱホバに依賴み いとたかき者のいつくしみを蒙るがゆゑに動かさるることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'なんぢの手はそのもろもろの仇をたづねいだし 汝のみぎの手はおのれを憎むものを探ねいだすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'なんぢ怒るときは彼等をもゆる爐のごとくにせんヱホバはげしき怒によりてかれらを呑たまはん 火はかれらを食つくさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, '汝かれらの裔を地よりほろぼし かれらの種を人の子のなかよりほろぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'かれらは汝にむかひて惡事をくはだて遂がたき謀略をおもひまはせばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, '汝かれらをして背をむけしめ その面にむかひて弓絃をひかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'ヱホバよ能力をあらはしてみづからを高くしたまへ 我儕はなんぢの稜威をうたひ且ほめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'あけぼのの鹿の調にあはせて伶長にうたはしめたるダビデの歌 わが神わが神なんぞ我をすてたまふや 何なれば遠くはなれて我をすくはず わが歎きのこゑをきき給はざるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'ああわが神われ晝よばはれども汝こたへたまはず 夜よばはれどもわれ平安をえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, '然はあれイスラエルの讃美のなかに住たまふものよ汝はきよし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'われらの列祖はなんぢに依賴めり かれら依賴みたればこれを助けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'かれら汝をよびて援をえ汝によりたのみて恥をおへることなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, '然はあれどわれは蟲にして人にあらず 世にそしられ民にいやしめらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'すべてわれを見るものはわれをあざみわらひ 口唇をそらし首をふりていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'かれはヱホバによりたのめりヱホバ助くべし ヱホバかれを悦びたまふが故にたすくべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'されど汝はわれを胎内よりいだし給へるものなり わが母のふところにありしとき旣になんぢに依賴ましめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, '我うまれいでしより汝にゆだねられたり わが母われを生しときより汝はわが神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'われに遠ざかりたまふなかれ 患難ちかづき又すくふものなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'おほくの牡牛われをめぐりバサンの力つよき牡牛われをかこめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'かれらは口をあけて我にむかひ物をかきさき吼うだく獅のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'われ水のごとくそそぎいだされ わがもろもろの骨ははづれ わが心は蝋のごとくなりて腹のうちに鎔たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'わが力はかわきて陶器のくだけのごとく わが舌は齶にひたつけり なんぢわれを死の塵にふさせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'そは犬われをめぐり惡きものの群われをかこみてわが手およびわが足をさしつらぬけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'わが骨はことごとく數ふるばかりになりぬ 惡きものの目をとめて我をみる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'かれらたがひにわが衣をわかち我がしたぎを鬮にす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'ヱホバよ遠くはなれ居たまふなかれ わが力よねがはくは速きたりてわれを授けたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'わがたましひを劍より助けいだし わが生命を犬のたけきいきほひより脱れしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'われを獅の口また野牛のつのより救ひいだしたまへ なんぢ我にこたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'われなんぢの名をわが兄弟にのべつたへ なんぢを會のなかにて讃たたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'ヱホバを懼るるものよヱホバをほめたたへよ ヤコブのもろもろの裔よヱホバをあがめよ イスラエルのもろもろのすゑよヱホバを畏め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'ヱホバはなやむものの辛苦をかろしめ棄たまはず これに聖顔をおほふことなくしてその叫ぶときにききたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, '大なる會のなかにてわが汝をほめたたふるは汝よりいづるなり わが誓ひしことはヱホバをおそるる者のまへにてことごとく償はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, '謙遜者はくらひて飽ことをえ ヱホバをたづねもとむるものはヱホバをほめたたへん 願くはなんぢらの心とこしへに生んことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, '地のはては皆おもひいだしてヱホバに歸りもろもろの國の族はみな前にふしをがむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, '國はヱホバのものなればなり ヱホバはもろもろの國人をすべをさめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, '地のこえたるものは皆くらひてヱホバををがみ塵にくだるものと己がたましひを存ふること能はざるものと皆そのみまへに拝跪かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'たみの裔のうちにヱホバにつかる者あらん 主のことは代々にかたりつたへらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'かれら來りて此はヱホバの行爲なりとてその義を後にうまるる民にのべつたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'ダビデのうた ヱホバは我が牧者なり われ乏しきことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'ヱホバは我をみどりの野にふさせ いこひの水濱にともなひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'ヱホバはわが霊魂をいかし名のゆゑをもて我をただしき路にみちびき給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'たとひわれ死のかげの谷をあゆむとも禍害をおそれじ なんぢ我とともに在せばなり なんぢの笞なんぢの杖われを慰む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'なんぢわが仇のまへに我がために筵をまうけ わが首にあぶらをそそぎたまふ わが酒杯はあふるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'わが世にあらん限りはかならず恩惠と憐憫とわれにそひきたらん 我はとこしへにヱホバの宮にすまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'ダビデのうた 地とそれに充るもの世界とその中にすむものとは皆ヱホバのものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'ヱホバはそのもとゐを大海のうへに置これを大川のうへに定めたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'ヱホバの山にのぼるべきものは誰ぞ その聖所にたつべき者はたれぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, '手きよく心いさぎよき者そのたましひ虚きことを仰ぎのぞまず偽りの誓をせざるものぞ その人なる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'かかる人はヱホバより福祉をうけ そのすくひの神より義をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, '斯のごとき者は神をしたふものの族類なり ヤコブの神よなんぢの聖顔をもとむる者なり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, '門よなんぢらの首をあげよ とこしへの戸よあがれ 榮光の王いりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'えいくわうの王はたれなるか ちからをもちたまふ猛きヱホバなり 戰闘にたけきヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, '門よなんぢらの首をあげよ とこしへの戸よあがれ 榮光の王いりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'この榮光の王はたれなるか 萬軍のヱホバ是ぞえいくわうの王なる セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'ダビデのうた ああヱホバよ わがたましひは汝をあふぎ望む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'わが神よわれなんぢに依賴めり ねがはくはわれに愧をおはしめたまふなかれ わが仇のわれに勝誇ることなからしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, '實になんぢを俟望むものははぢしめられず 故なくして信をうしなふものは愧をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'ヱホバよなんぢの大路をわれにしめし なんぢの徑をわれにをしへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, '我をなんぢの眞理にみちびき我ををしへたまへ 汝はわがすくひの神なり われ終日なんぢを俟望む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'なんぢのあはれみと仁慈とはいにしへより絶ずあり ヱホバよこれを思ひいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'わがわかきときの罪とわが愆とはおもひいでたまふなかれ ヱホバよ汝のめぐみの故になんぢの仁慈にしたがひて我をおもひいでたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'ヱホバはめぐみ深くして直くましませり 斯るがゆゑに道をつみびとにをしへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, '謙だるものを正義にみちびきたまはん その道をへりくだる者にしめしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'ヱホバのもろもろの道はそのけいやくと證詞とをまもるものには仁慈なり眞理なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'わが不義はおほいなり ヱホバよ名のために之をゆるしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'ヱホバをおそるる者はたれなるか 之にそのえらぶべき道をしめしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'かかる人のたましひは平安にすまひ その裔はくにをつぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'ヱホバの親愛はヱホバをおそるる者とともにあり ヱホバはその契約をかれらに示したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'わが目はつねにヱホバにむかふ ヱホバわがあしを網よりとりいだしたまふ可ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'ねがはくは歸りきたりて我をあはれみたまへ われ獨わびしくまた苦しみをるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, '願くはわが心のうれへをゆるめ我をわざはひより脱かれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'わが患難わが辛苦をかへりみ わがすべての罪をゆるしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'わが仇をみたまへ かれらの數はおほし情なき憾をもてわれをにくめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'わがたましひをまもり我をたすけたまへ われに愧をおはしめたまふなかれ 我なんぢに依賴めばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'われなんぢを挨望むねがはくは完全と正直とわれをまもれかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, '神よすべての憂よりイスラエルを贖ひいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'ダビデの歌 ヱホバよねがはくはわれを鞫きたまへわれわが完全によりてあゆみたり 然のみならず我たゆたはずヱホバに依賴めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'ヱホバよわれを糺しまた試みたまへ わが腎とこころとを錬きよめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'そは汝のいつくしみわが眼前にあり 我はなんぢの眞理によりてあゆめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'われは虚しき人とともに座らざりき 惡をいつはりかざる者とともにはゆかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, '惡をなすものの會をにくみ惡者とともにすわることをせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'われ手をあらひて罪なきをあらはす ヱホバよ斯てなんぢの祭壇をめぐり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, '感謝のこゑを聞えしめ すべてなんぢの奇しき事をのべつたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'ヱホバよ我なんぢのまします家となんぢが榮光のとどまる處とをいつくしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, '願くはわがたましひを罪人とともに わが生命を血をながす者とともに取收めたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'かかる人の手にはあしきくはだてあり その右の手は賄賂にてみつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'されどわれはわが完全によりてあゆまん願くはわれをあがなひ我をあはれみたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'わがあしは平坦なるところにたつ われもろもろの會のなかにてヱホバを讃まつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'ダビデの歌 ヱホバはわが光わが救なり われ誰をかおそれん ヱホバはわが生命のちからなり わが懼るべきものはたれぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'われの敵われの仇なるあしきもの襲ひきたりてわが肉をくらはんとせしが蹶きかつ仆れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, '縦ひいくさびと營をつらねて我をせむるともわが心おそれじ たとひ戰ひおこりて我をせむるとも我になほ恃あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'われ一事をヱホバにこへり我これをもとむ われヱホバの美しきを仰ぎその宮をみんがためにわが世にあらん限りはヱホバの家にすまんとこそ願ふなれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'ヱホバはなやみの日にその行宮のうちに我をひそませその幕屋のおくにわれをかくし巌のうへに我をたかく置たまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, '今わが首はわれをめぐれる仇のうへに高くあげらるべし この故にわれヱホバのまくやにて歓喜のそなへものを献ん われうたひてヱホバをほめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'わが聲をあげてさけぶときヱホバよきき給へ また憐みてわれに應へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'なんぢらわが面をたづねもとめよと(斯る聖言のありしとき)わが心なんぢにむかひてヱホバよ我なんぢの聖顔をたづねんといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'ねがはくは聖顔をかくしたまふなかれ 怒りてなんぢの僕をとほざけたまふなかれ汝はわれの助なり 噫わがすくひの神よ われをおひいだし我をすてたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'わが父母われをすつるともヱホバわれを迎へたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'ヱホバよなんぢの途をわれにをしへ わが仇のゆゑに我をたひらかなる途にみちびきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'いつはりの證をなすもの暴厲を吐もの我にさからひて起りたてり 願くはわれを仇にわたしてその心のままに爲しめたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'われもしヱホバの恩寵をいけるものの地にて見るの侍なからましかば奈何ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'ヱホバを俟望ぞめ雄々しかれ汝のこころを堅うせよ 必ずやヱホバをまちのぞめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'ダビデの歌 ああヱホバよわれ汝をよばん わが磐よねがはくは我にむかひて暗唖となりたまふなかれ なんぢ默したまはば恐らくはわれ墓にいるものとひとしからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'われ汝にむかひてさけび聖所の奧にむかひて手をあぐるときわが懇求のこゑをききたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'あしき人また邪曲をおこなふ者とともに我をとらへてひきゆき給ふなかれ かれらはその隣にやはらぎをかたれども心には殘害をいだけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'その事にしたがひそのなす惡にしたがひて彼等にあたへ その手の行爲にしたがひて與へこれにその受べきものを報いたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'かれらはヱホバのもろもろの事とその手のなしわざとをかへりみず この故にヱホバかれらを毀ちて建たまふことなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'ヱホバは讃べきかな わが祈のこゑをききたまひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'ヱホバはわが力わが盾なり わがこころこれに依賴みたれば我たすけをえたり 然るゆゑにわが心いたくよろこぶ われ歌をもてほめまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'ヱホバはその民のちからなり その受膏者のすくひの城なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'なんぢの民をすくひなんぢの嗣業をさきはひ且これをやしなひ之をとこしなへに懐きたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'ダビデの歌 なんぢら神の子らよ ヱホバに獻げまつれ榮と能とをヱホバにささげまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'その名にふさはしき榮光をヱホバにささげ奉れ きよき衣をつけてヱホバを拝みまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'ヱホバのみこゑは水のうへにあり えいくわうの神は雷をとどろかせたまふ ヱホバは大水のうへにいませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'ヱホバの聲はちからあり ヱホバのみこゑは稜威あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'ヱホバのみこゑは香柏ををりくだく ヱホバ、レバノンのかうはくを折くだきたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'これを犢のごとくをどらせレバノンとシリオンとをわかき野牛のごとくをどらせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'ヱホバのみこゑは火焔をわかつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'ヱホバのみこゑは野をふるはせヱホバはカデシの野をふるはせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'ヱホバのみこゑは鹿に子をうませ また林木をはだかにす その宮にあるすべてのもの呼はりて榮光なるかなといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'ヱホバは洪水のうへに坐したまへり ヱホバは寳座にざして永遠に王なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'ヱホバはその民にちからをあたへたまふ 平安をもてその民をさきはひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, '殿をささぐるときに謳へるダビデのうた ヱホバよわれ汝をあがめん なんぢ我をおこしてわが仇のわがことによりて喜ぶをゆるし給はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'わが神ヱホバよわれ汝によばはれば汝我をいやしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'ヱホバよ汝わがたましひを陰府よりあげ我をながらへしめて墓にくだらせたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'ヱホバの聖徒よ ヱホバをほめうたへ奉れ きよき名に感謝せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'その怒はただしばしにてその惠はいのちとともにながし 夜はよもすがら泣かなしむとも朝にはよろこびうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'われ安けかりしときに謂く とこしへに動かさるることなからんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'ヱホバよなんぢ惠をもてわが山をかたく立せたまひき 然はあれどなんぢ面をかくしたまひたれば我おぢまどひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'ヱホバよわれ汝によばはれり 我ひたすらヱホバにねがへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'われ墓にくだらばわが血なにの益あらん 塵はなんぢを讃たたへんや なんぢの眞理をのべつたへんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'ヱホバよ聽たまへ われを憐みたまへ ヱホバよ願くはわが助となりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'なんぢ踴躍をもてわが哀哭にかへわが麁服をとき歓喜をもてわが帶としたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'われ榮をもてほめうたひつつ默すことなからんためなり わが神ヱホバよわれ永遠になんぢに感謝せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, '伶長にうたはしめたるダビデのうた ヱホバよわれ汝によりたのむ 願くはいづれの日までも愧をおはしめたまふなかれ なんぢの義をもてわれを助けたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'なんぢの耳をかたぶけて速かにわれをすくひたまへ 願くはわがためにかたき磐となり我をすくふ保障の家となりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'なんぢはわが磐わが城なり されば名のゆゑをもてわれを引われを導きたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'なんぢ我をかれらが密かにまうけたる網よりひきいだしたまへ なんぢはわが保砦なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'われ霊魂をなんぢの手にゆだぬ ヱホバまことの神よなんぢはわれを贖ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'われはいつはりの虚きことに心をよする者をにくむ われは獨ヱホバによりたのむなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, '我はなんぢの憐憫をよろこびたのしまん なんぢわが艱難をかへりみ わがたましひの禍害をしり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'われを仇の手にとぢこめしめたまはず わが足をひろきところに立たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'われ迫りくるしめり ヱホバよ我をあはれみたまへ わが目はうれひによりておとろふ 霊魂も身もまた衰へぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'わが生命はかなしみによりて消えゆき わが年華はなげきによりて消ゆけばなり わが力はわが不義によりておとろへ わが骨はかれはてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'われもろもろの仇ゆゑにそしらる わが隣にはわけて甚だし相識ものには忌憚られ衢にてわれを見るもの避てのがる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'われは死たるもののごとく忘られて人のこころに置れず われはやぶれたる器もののごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'そは我おほくの人のそしりをきい到るところに懼あり かれら我にさからひて互にはかりしが わが生命をさへとらんと企てたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'されどヱホバよわれ汝によりたのめり また汝はわが神なりといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'わが時はすべてなんぢの手にあり ねがはくはわれを仇の手よりたすけ われに追迫るものより助けいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'なんぢの僕のうへに聖顔をかがやかせ なんぢの仁慈をもて我をすくひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'ヱホバよわれに愧をおはしめ給ふなかれ そは我なんぢをよべばなり 願くはあしきものに恥をうけしめ陰府にありて口をつぐましめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, '傲慢と軽侮とをもて義きものにむかひ妄りにののしるいつはりの口唇をつぐましめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, '汝をおそるる者のためにたくはへ なんぢに依賴むもののために人の子のまへにてほどこしたまへる汝のいつくしみは大なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, '汝かれらを御前なるひそかなる所にかくして人の謀略よりまぬかれしめ また行宮のうちにひそませて舌のあらそひをさけしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, '讃べきかなヱホバは堅固なる城のなかにて奇しまるるばかりの仁慈をわれに顯したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'われ驚きあわてていへらく なんぢの目のまへより絶れたりと 然どわれ汝によびもとめしとき汝わがねがひの聲をききたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'なんぢらもろもろの聖徒よヱホバをいつくしめ ヱホバは眞實あるものをまもり傲慢者におもく報をほどこしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'すべてヱホバを俟望むものよ雄々しかれ なんぢら心をかたうせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'ダビデの訓諭のうた その愆をゆるされその罪をおほはれしものは福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, '不義をヱホバに負せられざるもの心にいつはりなき者はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, '我いひあらはさざりしときは終日かなしみさけびたるが故にわが骨ふるびおとろへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'なんぢの手はよるも晝もわがうへにありて重し わが身の潤澤はかはりて夏の旱のごとくなれり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, '斯てわれなんぢの前にわが罪をあらはしわが不義をおほはざりき 我いへらくわが愆をヱホバにいひあらはさんと 斯るときしも汝わがつみの邪曲をゆるしたまへり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'されば神をうやまふ者はなんぢに遇ことをうべき間になんぢに祈らん 大水あふれ流るるともかならずその身におよばじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, '汝はわがかくるべき所なり なんぢ患難をふせぎて我をまもり救のうたをもて我をかこみたまはん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'われ汝ををしへ汝をあゆむべき途にみちびき わが目をなんぢに注てさとさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, '汝等わきまへなき馬のごとく驢馬のごとくなるなかれ かれらは鑣たづなのごとき具をもてひきとめずば近づききたることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, '惡者はかなしみ多かれどヱホバに依賴むものは憐憫にてかこまれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'ただしき者よヱホバを喜びたのしめ 凡てこころの直きものよ喜びよばふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'ただしき者よヱホバによりてよろこべ 讃美はなほきものに適はしきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, '琴をもてヱホバに感謝せよ 十絃のことをもてヱホバをほめうたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'あたらしき歌をヱホバにむかひてうたひ歓喜の聲をあげてたくみに琴をかきならせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'ヱホバのことばは直く そのすべて行ひたまふところ眞實なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'ヱホバは義と公平とをこのみたまふ その仁慈はあまねく地にみつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'もろもろの天はヱホバのみことばによりて成り てんの萬軍はヱホバの口の氣によりてつくられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'ヱホバはうみの水をあつめてうづだかくし深淵を庫にをさめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, '全地はヱホバをおそれ世にすめるもろもろの人はヱホバをおぢかしこむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'そはヱホバ言たまへば成り おほせたまへば立るがゆゑなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'ヱホバはもろもろの國のはかりごとを虚くし もろもろの民のおもひを徒勞にしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'ヱホバの謀略はとこしへに立ち そのみこころのおもひは世々にたつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'ヱホバをおのが神とする國はさいはひなり ヱホバ嗣業にせんとて撰びたまへるその民はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'ヱホバ天よりうかがひてすべての人の子を見');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'その在すところより地にすむもろもろの人をみたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'ヱホバはすべてかれらの心をつくり その作ところをことごとく鑒みたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, '王者いくさびと多をもて救をえず勇士ちから大なるをもて助をえざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, '馬はすくひに益なく その大なるちからも人をたすくることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, '視よヱホバの目はヱホバをおそるるもの並その憐憫をのぞむもののうへにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, '此はかれらのたましひを死よりすくひ饑饉たるときにも世にながらへしめんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'われらのたましひはヱホバを侯望めり ヱホバはわれらの援われらの盾なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'われらはきよき名にりたのめり 斯てぞわれらの心はヱホバにありてよろこばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'ヱホバよわれら汝をまちのぞめり これに循ひて憐憫をわれらのうへに垂たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'ダビデ、アビメレクのまへにて狂へる状をなし逐れていでさりしときに作れるうた われつねにヱホバを祝ひまつらんその頌詞はわが口にたえじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'わがたましひはヱホバによりて誇らん 謙だるものは之をききてよろこばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'われとともにヱホバを崇めよ われらともにその名をあげたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'われヱホバを尋ねたればヱホバわれにこたへ我をもろもろの畏懼よりたすけいだしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'かれらヱホバを仰ぎのぞみて光をかうぶれり かれらの面ははぢあからむことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'この苦しむもの叫びたればヱホバこれをきき そのすべての患難よりすくひいだしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'ヱホバの使者はヱホバをおそるる者のまはりに營をつらねてこれを援く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'なんぢらヱホバの恩惠ふかきを嘗ひしれ ヱホバによりたのむ者はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'ヱホバの聖徒よヱホバを畏れよヱホバをおそるるものには乏しきことなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'わかき獅はともしくして饑ることあり されどヱホバをたづぬるものは嘉物にかくることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, '子よきたりて我にきけ われヱホバを畏るべきことを汝等にをしへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, '福祉をみんがために生命をしたひ存へんことをこのむ者はたれぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'なんぢの舌をおさへて惡につかしめず なんぢの口唇をおさへて虚偽をいはざらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, '惡をはなれて善をおこなひ和睦をもとめて切にこのことを勉めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'ヱホバの目はただしきものをかへりみ その耳はかれらの號呼にかたぶく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'ヱホバの聖顔はあくをなす者にむかひてその跡を地より斷滅したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, '義者さけびたればヱホバ之をききてそのすべての患難よりたすけいだしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'ヱホバは心のいたみかなしめる者にちかく在してたましひの悔頽れたるものをすくひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'ただしきものは患難おほし されどヱホバはみなその中よりたすけいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'ヱホバはかれがすべての骨をまもりたまふ その一つだに折らるることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, '惡はあしきものをころさん 義人をにくむものは刑なはるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'ヱホバはその僕等のたましひを贖ひたまふ ヱホバに依賴むものは一人だにつみなはるることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'ダビデのうた ヱホバよねがはくは我にあらそふ者とあらそひ我とたたかふものと戰ひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, '干と大盾とをとりてわが援にたちいでたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, '戟をぬきいだしたまひて我におひせまるものの途をふさぎ且わが霊魂にわれはなんぢの救なりといひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, '願くはわが霊魂をたづぬるものの恥をえていやしめられ 我をそこなはんと謀るものの退けられて惶てふためかんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'ねがはくはかれらが風のまへなる粃糠のごとくなりヱホバの使者におひやられんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, '願くはかれらの途をくらくし滑らかにしヱホバの使者にかれらを追ゆかしめたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'かれらは故なく我をとらへんとて網をあなにふせ 故なくわが霊魂をそこなはんとて阱をうがちたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, '願くはかれらが思ひよらぬ間にほろびきたり己がふせたる網にとらへられ自らその滅におちいらんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, '然ときわが霊魂はヱホバによりてよろこび その救をもて樂しまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'わがすべての骨はいはん ヱホバよ汝はくるしむものを之にまさりて力つよきものより並くるしむもの貧しきものを掠めうばふ者よりたすけいだし給ふ 誰かなんぢに比ふべき者あらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'こころあしき證人おこりてわが知ざることを詰りとふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'かれらは惡をもてわが善にむくい我がたましひを依仗なきものとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, '然どわれかれらが病しときには麁服をつけ糧をたちてわが霊魂をくるしめたり わが祈はふところにかへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'わがかれに作ることはわが友わが兄弟にことならず母の喪にありて痛哭がごとく哀しみうなたれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, '然どかれらはわが倒れんとせしとき喜びつどひわが知ざりしとき匪類あつまりきたりて我をせめ われを裂てやめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'かれらは洒宴にて穢きことをのぶる嘲笑者のごとく我にむかひて歯をかみならせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, '主よいたづらに見るのみにして幾何時をへたまふや 願くはわがたましひの彼等にほろぼさるるを脱れしめ わが生命をわかき獅よりまぬかれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'われ大なる會にありてなんぢに感謝し おほくの民のなかにて汝をほめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, '虚偽をもてわれに仇するもののわが故によろこぶことを容したまなかれ 故なくして我をにくむ者のたがひに眴せすることなからしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'かれらは平安をかたらず あざむきの言をつくりまうけて國内におだやかにすまふ者をそこなはんと謀る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, '然のみならず我にむかひて口をあけひろげ ああ視よや視よやわれらの眼これをみたりといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'ヱホバよ汝すでにこれを視たまへり ねがはくは默したまふなかれ主よわれに遠ざかりたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'わが神よわが主よ おきたまへ醒たまへ ねがはくはわがために審判をなしわが訟ををさめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'わが神ヱホバよなんぢの義にしたがひて我をさばきたまへ わが事によりてかれらに歓喜をえしめたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'かれらにその心裡にて ああここちよきかな觀よこれわが願ひしところなりといはしめたまふなかれ 又われらかれを呑つくせりといはしめたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, '願くはわが害なはるるを喜ぶもの皆はぢて惶てふためき 我にむかひてはこりかに高ぶるものの愧とはづかしめとを衣んことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'わが義をよみする者をばよろこび謳はしめ大なるかなヱホバその僕のさいはひを悦びたまふと恒にいはしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'わが舌は終日なんぢの義となんぢの譽とをかたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, '伶長にうたはしめたるヱホバの僕ダビデのうた あしきものの愆はわが心のうちにかたりて その目のまへに神をおそるるの畏あることなしといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'かれはおのが邪曲のあらはるることなく憎まるることなからんとて自からその目にて謟る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'その口のことばは邪曲と虚偽となり智をこばみ善をおこなふことを息たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'かつその寝床にてよこしまなる事をはかり よからぬ途にたちとまりて惡をきらはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'ヱホバよなんぢの仁慈は天にあり なんぢの眞實は雲にまでおよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, '汝のただしきは神の山のごとく なんぢの審判はおほいなる淵なり ヱホバよなんぢは人とけものとを護りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, '神よなんぢの仁慈はたふときかな 人の子はなんぢの翼の蔭にさけどころを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'なんぢの屋のゆたかなるによりてことごとく飽ことをえん なんぢはその歓樂のかはの水をかれらに飮しめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'そはいのちの泉はなんぢに在り われらはなんぢの光によりて光をみん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'ねがはくはなんぢを知るものにたえず憐憫をほどこし心なほき者にたえず正義をほどこしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'たかぶるものの足われをふみ惡きものの手われを逐去ふをゆるし給ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, '邪曲をおこなふ者はかしこに仆れたり かれら打伏られてまた起ことあたはざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'ダビデのうた 惡をなすものの故をもて心をなやめ 不義をおこなふ者にむかひて嫉をおこすなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'かれらはやがて草のごとくかりとられ靑菜のごとく打萎るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'ヱホバによりたのみて善をおこなへ この國にとどまり眞實をもて糧とせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'ヱホバによりて歓喜をなせ ヱホバはなんぢが心のねがひを汝にあたへたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'なんぢの途をヱホバにゆだねよ 彼によりたのまば之をなしとげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, '光のごとくなんぢの義をあきらかにし午日のごとくなんぢの訟をあきらかにしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'なんぢヱホバのまへに口をつぐみ忍びてこれを俟望め おのが途をあゆみて榮るものの故をもて あしき謀略をとぐる人の故をもて心をなやむるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, '怒をやめ忿恚をすてよ 心をなやむるなかれ これ惡をおこなふ方にうつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'そは惡をおこなふものは斷滅され ヱホバを俟望むものは國をつぐべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'あしきものは久しからずしてうせん なんぢ細密にその處をおもひみるともあることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'されど謙だるものは國をつぎ また平安のゆたかなるを樂まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, '惡きものは義きものにさからはんとて謀略をめぐらし之にむかひて切歯す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, '主はあしきものを笑ひたまはん かれが日のきたるを見たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'あしきものは劍をぬき弓をはりて苦しむものと貧しきものとをたふし行ひなほきものを殺さんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'されどその劍はおのが胸をさしその弓はをらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, '義人のもてるもののすくなきは多くの惡きものの豊かなるにまされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'そは惡きものの臂はをらるれどヱホバは義きものを扶持たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'ヱホバは完全もののもろもろの日をしりたまふ かれらの嗣業はかぎりなく久しからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'かれらは禍害にあふとき愧をおはず饑饉の日にもあくことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'あしき者ははろびヱホバのあたは牧場のさかえの枯るがごとくうせ烟のごとく消ゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'あしき者はものかりて償はず 義きものは惠ありて施しあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, '神のことほぎたまふ人は國をつぎ 神ののろひたまふ人は斷滅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, '人のあゆみはヱホバによりて定めらる そのゆく途をヱホバよろこびたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, '縦ひその人たふるることありとも全くうちふせらるることなし ヱホバかれが手をたすけ支へたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'われむかし年わかくして今おいたれど 義者のすてられ或はその裔の糧こひありくを見しことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'ただしきものは終日めぐみありて貸あたふ その裔はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, '惡をはなれて善をなせ 然ばなんぢの住居とこしへならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'ヱホバは公平をこのみ その聖徒をすてたまはざればなり かれらは永遠にまもりたすけらるれど惡きもののすゑは斷滅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'ただしきものは國をつぎ その中にすまひてとこしへに及ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'ただしきものの口は智慧をかたり その舌は公平をのぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'かれが神の法はそのこころにあり そのあゆみは一歩だにすべることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'あしきものは義者をひそみうかがひて之をころさんとはかる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'ヱホバは義者をあしきものの手にのこしおきたまはず 審判のときに罰ひたまふことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'ヱホバを俟望みてその途をまもれ さらば汝をあげて國をつがせたまはん なんぢ惡者のたちほろぼさるる時にこれをみん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, '我あしきものの猛くしてはびこれるを見るに生立たる地にさかえしげれる樹のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, '然れどもかれは逝ゆけり 視よたちまちに無なりぬ われ之をたづねしかど邁ことをえざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, '完人に目をそそぎ直人をみよ 和平なる人には後あれど');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, '罪ををかすものらは共にほろぼされ惡きものの後はかならず斷るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'ただしきものの救はヱホバよりいづ ヱホバはかれらが辛苦のときの保砦なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'ヱホバはかれらを助け かれらを解脱ちたまふ ヱホバはかれらを惡者よりときはなちて救ひたまふ かれらはヱホバをその避所とすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, '記念のためにつくれるダビデのうた ヱホバよねがはくは忿恚をもて我をせめ はげしき怒をもて我をこらしめ給ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'なんぢの矢われにあたり なんぢの手わがうへを壓へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'なんぢの怒によりてわが肉には全きところなく わが罪によりてわが骨には健かなるところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'わが不義は首をすぎてたかく重荷のごとく負がたければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'われ愚なるによりてわが傷あしき臭をはなちて腐れただれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'われ折屈みていたくなげきうなたれたり われ終日かなしみありく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'わが腰はことごとく燒るがごとく肉に全きところなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, '我おとろへはて甚くきずつけられわが心のやすからざるによりて欷歔さけべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'ああ主よわがすべての願望はなんぢの前にあり わが嘆息はなんぢに隠るることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'わが胸をどりわが力おとろへ わが眼のひかりも亦われをはなれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'わが友わが親めるものはわが痍をみて遥にたち わが隣もまた遠かりてたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'わが生命をたづぬるものは羂をまうけ我をそこなはんとするものは惡言をいひ また終日たばかりを謀る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, '然はあれどわれは聾者のごとくきかず われは口をひらかぬ唖者のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, '如此われはきかざる人のごとく口にことあげせぬ人のごときなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'ヱホバよ我なんぢを俟望めり 主わが神よなんぢかならず答へたまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'われ曩にいふ おそらくはかれらわが事によりて喜び わが足のすべらんとき我にむかひて誇りかにたかぶらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'われ仆るるばかりになりぬ わが悲哀はたえずわが前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'そは我みづから不義をいひあらはし わが罪のためにかなしめばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'わが仇はいきはたらきてたけく故なくして我をうらむるものおほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, '惡をもて善にむくゆるものはわれ善事にしたがふが故にわが仇となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'ヱホバよねがはくは我をはなれたたまふなかれ わが神よわれに遠かりたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, '主わがすくひよ速きたりて我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, '伶長エドトンにうたはしめたるダビデのうた われ曩にいへり われ舌をもて罪ををかさざらんために我すべての途をつつしみ惡者のわがまへに在るあひだはわが口に衝をかけんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'われ默して唖となり善言すらことばにいださず わが憂なほおこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'わが心わがうちに熱し おもひつづくるほどに火もえぬればわれ舌をもていへらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'ヱホバよ願くはわが終とわが日の數のいくばくなるとを知しめたまへ わが無常をしらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, '觀よなんぢわがすべての日を一掌にすぎさらしめたまふ わがかいのち主前にてはなきにことならず 實にすべての人は皆その盛時だにもむなしからざるはなし セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, '人の世にあるは影にことならず その思ひなやむことはむなしからざるなし その積蓄ふるものはたが手にをさまるをしらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, '主よわれ今なにをかまたん わが望はなんぢにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'ねがはくは我ぞすべて愆より助けいだしたまへ 愚なるものに誹らるることなからしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'われは默して口をひらかず 此はなんぢの成したまふ者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, '願くはなんぢの責をわれよりはなちたまへ 我なんぢの手にうちこらさるるによりて亡ぶるばかりになりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'なんぢ罪をせめて人をこらし その慕ひよろこぶところのものを蠧のくらふがごとく消うせしめたまふ 實にもろもろの人はむなしからざるなし セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'ああヱホバよねがはくはわが祈をきき わが號呼に耳をかたぶけたまへ わが涙をみて默したまふなかれ われはなんぢに寄る旅客すべてわが列祖のごとく宿れるものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, '我ここを去てうせざる先になんぢ面をそむけてわれを爽快ならしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, '伶長にうたはしめたるダビデのうた 我たへしのびてヱホバを俟望みたり ヱホバ我にむかひてわが號呼をききたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'また我をほろびの阱より泥のなかよりとりいだしてわが足を磐のうへにおきわが歩をかたくしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'ヱホバはあたらしき歌をわが口にいれたまへり此はわれらの神にささぐる讃美なり おほくの人はこれを見ておそれ かつヱホバによりたのまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'ヱホバをおのが賴となし高るものによらず虚偽にかたぶく者によらざる人はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'わが神ヱホバよなんぢの作たまへる奇しき迹と われらにむかふ念とは甚おほくして汝のみまへにつらねいふことあたはず 我これをいひのべんとすれどその數かぞふることあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'なんぢ犠牲と祭物とをよろこびたまはず汝わが耳をひらきたまへり なんぢ燔祭と罪祭とをもとめたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'そのとき我いへらく 觀よわれきたらんわがことを書の巻にしるしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'わが神よわれは聖意にしたがふことを樂む なんぢの法はわが心のうちにありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'われ大なる會にて義をつげしめせり 視よわれ口唇をとぢず ヱホバよなんぢ之をしりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'われなんぢの義をわが心のうちにひめおかず なんぢの眞實となんぢの拯救とをのべつたへたり 我なんぢの仁慈となんぢの眞理とをおほいなる會にかくさざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'ヱホバよなんぢ憐憫をわれにをしみたまふなかれ 仁慈と眞理とをもて恒にわれをまもりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'そはかぞへがたき禍害われをかこみ わが不義われに追及てあふぎみること能はぬまでになりぬ その多きことわが首の髮にもまさり わが心きえうするばかりなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'ヱホバよ願くはわれをすくひたまへ ヱホバよ急ぎきたりて我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, '願くはわが霊魂をたづねほろぼさんとするものの皆はぢあわてんことを わが害はるるをよろこぶもののみな後にしりぞきて恥をおはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'われにむかひて ああ視よや視よやといふ者おのが恥によりておどろきおそれんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, '願くはなんぢを尋求むるものの皆なんぢによりて樂みよろこばんことを なんぢの救をしたふものの恒にヱホバは大なるかなととなへんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'われはくるしみ且ともし 主われをねんごろに念ひたまふ なんぢはわが助なり われをすくひたまふ者なり ああわが神よねがはくはためらひたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'うたのかみに謳はしめたるダビデのうた よわき人をかへりみる者はさいはひなり ヱホバ斯るものを禍ひの日にたすけたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'ヱホバ之をまもり之をながらへしめたまはん かれはこの地にありて福祉をえん なんぢ彼をその仇ののぞみにまかせて付したまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'ヱホバは彼がわづらひの床にあるをたすけ給はん なんぢかれが病るときその衾裯をしきかへたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, '我いへらくヱホバよわれを憐みわがたましひを醫したまへ われ汝にむかひて罪ををかしたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'わが仇われをそしりていへり 彼いづれのときに死いづれのときにその名ほろびんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'かれ又われを見んとてきたるときは虚偽をかたり邪曲をその心にあつめ 外にいでてはこれを述ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'すべてわれをにくむもの互ひにささやき我をそこなはんとて相謀る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'かつ云 かれに一のわざはひつきまとひたれば仆れふしてふたたび起ることなからんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'わが恃みしところ わが糧をくらひしところのわが親しき友さへも我にそむきてその踵をあげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, '然はあれどヱホバよ汝ねがはくは我をあはれみ我をたすけて起したまへ されば我かれらに報ることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'わが仇われに打勝てよろこぶこと能はざるをもて汝がわれを愛いつくしみたまふを我しりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'わが事をいはば なんぢ我をわが完全うちにてたもち我をとこしへに面のまへに置たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'イスラエルの神ヱホバはとこしへより永遠までほむべきかな アーメン アーメン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, '伶長にうたはしめたるコラの子のをしへの歌 ああ神よしかの渓水をしたひ喘ぐがごとく わが霊魂もなんぢをしたひあへぐなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'わがたましひは渇けるごとくに神をしたふ 活神をぞしたふ 何れのときにか我ゆきて神のみまへにいでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'かれらが終日われにむかひて なんぢの神はいづくにありやとののしる間はただわが涙のみ晝夜そそぎてわが糧なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'われむかし群をなして祭日をまもる衆人とともにゆき歓喜と讃美のこゑをあげてかれらを神の家にともなへり 今これらのことを追想してわが衷よりたましひを注ぎいだすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'ああわが霊魂よ なんぢ何ぞうなたるるや なんぞわが衷におもひみだるるや なんぢ神をまちのぞめ われに聖顔のたすけありて我なほわが神をほめたたふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'わが神よわがたましひはわが衷にうなたる 然ばわれヨルダンの地よりヘルモンよりミザルの山より汝をおもひいづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'なんぢの大瀑のひびきによりて淵々よびこたへ なんぢの波なんぢの猛浪ことごとくわが上をこえゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, '然はあれど晝はヱホバその憐憫をほどこしたまふ 夜はその歌われとともにあり 此うたはわがいのちの神にささぐる祈なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'われわが磐なる神にいはん なんぞわれを忘れたまひしや なんぞわれは仇のしへたげによりて悲しみありくや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'わが骨もくだくるばかりにわがてきはひねもす我にむかひて なんぢの神はいづくにありやといひののしりつつ我をそしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'ああわがたましひよ 汝なんぞうなたるるや 何ぞわがうちに思ひみだるるや なんぢ神をまちのぞめ われ尚わがかほの助なるわが神をほめたたふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, '神よねがはくは我をさばき 情しらぬ民にむかひてわが訟をあげつらひ詭計おほきよこしまなる人より我をたすけいだし給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'なんぢはわが力の神なり なんぞ我をすてたまひしや 何ぞわれは仇の暴虐によりてかなしみありくや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, '願くはなんぢの光となんぢの眞理とをはなち我をみちびきてその聖山とその帷幄とにゆかしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'さらばわれ神の祭壇にゆき又わがよろこびよろこぶ神にゆかん ああ神よわが神よわれ琴をもてなんぢを讃たたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'ああわが霊魂よなんぢなんぞうなたるるや なんぞわが衷におもひみだるるや なんぢ神によりて望をいだけ 我なほわが面のたすけなるわが神をほめたたふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, '伶長にうたはしめたるコラの子のをしへの歌 ああ神よむかしわれらの列祖の日になんぢがなしたまひし事迹をわれら耳にきけり 列祖われらに語れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'なんぢ手をもてもろもろの國人をおひしりぞけ われらの列祖をうゑ並もろもろの民をなやましてわれらの列祖をはびこらせたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'かれらはおのが劍によりて國をえしにあらず おのが臂によりて勝をえしにあらず 只なんぢの右の手なんぢの臂なんぢの面のひかりによれり 汝かれらを惠みたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, '神よなんぢはわが王なり ねがはくはヤコブのために救をほどこしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'われらは汝によりて敵をたふし また我儕にさからひて起りたつものをなんぢの名によりて踐壓ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'そはわれわが弓によりたのまず わが劍もまた我をすくふことあたはざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'なんぢわれらを敵よりすくひ またわれらを惡むものを辱かしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'われらはひねもす神によりてほこり われらは永遠になんぢの名に感謝せん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'しかるに今はわれらをすてて恥をおはせたまへり われらの軍人とともに出ゆきたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'われらを敵のまへより退かしめたまへり われらを惡むものその任意にわれらを掠めうばへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'なんぢわれらを食にそなへらるる羊のごとくにあたへ斯てわれらをもろもろの國人のなかにちらし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, '得るところなくしてなんぢの民をうり その價によりてなんぢの富をましたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, '汝われらを隣人にそしらしめ われらを環るものにあなどらしめ 嘲けらしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, '又もろもろの國のなかにわれらを談柄となし もろもろの民のなかにわれらを頭ふらるる者となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'わが凌辱ひねもす我がまへにあり わがかほの恥われをおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'こは我をそしり我をののしるものの聲により我にあだし我にうらみを報るものの故によるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'これらのこと皆われらに臨みきつれどわれらなほ汝をわすれず なんぢの契約をいつはりまもらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'われらの心しりぞかずわれらの歩履なんぢの道をはなれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, '然どなんぢは野犬のすみかにてわれらをきずつけ死蔭をもてわれらをおほひ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'われらもしおのれの神の名をわすれ或はわれらの手を異神にのべしことあらんには');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, '神はこれを糺したまはざらんや 神はこころの隠れたることをも知たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'われらは終日なんぢのために死にわたされ屠られんとする羊の如くせられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, '主よさめたまへ何なればねぶりたまふや起たまへ われらをとこしへに棄たまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'いかなれば聖顔をかくしてわれらがうくる苦難と虐待とをわすれたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'われらのたましひはかがみて塵にふし われらの腹は土につきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'ねがはくは起てわれらをたすけたまへ なんぢの仁慈のゆゑをもてわれらを贖ひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, '百合花のしらべにあはせて伶長にうたはしめたるコラの子のをしへのうた 愛のうた わが心はうるはしき事にてあふる われは王のために詠たるものをいひいでん わが舌はすみやけく寫字人の筆なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'なんぢは人の子輩にまさりて美しく文雅そのくちびるにそそがる このゆゑに神はとこしへに汝をさいはひしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, '英雄よなんぢその劍その榮その威をこしに佩べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'なんぢ眞理と柔和とただしきとのために威をたくましくし勝をえて乗すすめ なんぢの右手なんぢに畏るべきことををしへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'なんぢの矢は鋭して王のあたの胸をつらぬき もろもろの民はなんぢの下にたふる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, '神よなんぢの寳座はいやとほ永くなんぢの國のつゑは公平のつゑなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'なんぢは義をいつくしみ惡をにくむ このゆゑに神なんぢの神はよろこびの膏をなんぢの侶よりまさりて汝にそそぎたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'なんぢの衣はみな沒薬蘆薈肉桂のかをりあり 琴瑟の音ざうげの諸殿よりいでて汝をよろこばしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'なんぢがたふとき婦のなかにはもろもろの王のむすめあり 皇后はオフルの金をかざりてなんぢの右にたつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, '女よきけ目をそそげ なんぢの耳をかたぶけよ なんぢの民となんぢが父の家とをわすれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'さらば王はなんぢの美麗をしたはん 王はなんぢの主なりこれを伏拝め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'ツロの女は贈物をもてきたり民間のとめるものも亦なんぢの惠をこひもとめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, '王のむすめは殿のうちにていとど榮えかがやき そのころもは金をもて織なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'かれは鍼繍せる衣をきて王のもとにいざなはる 之にともなへる處女もそのあとにしたがひて汝のもとにみちびかれゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'かれらは歓喜と快樂とをもていざなはれ斯して王の殿にいらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'なんぢの子らは列祖にかはりてたち なんぢはこれを全地に君となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, '我なんぢの名をよろづ代にしらしめん この故にもろもろの民はいやとほ永くなんぢに感謝すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, '女音のしらべにしたがひて伶長にうたはしめたるコラの子のうた 神はわれらの避所また力なり なやめるときの最ちかき助なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'さればたとひ地はかはり山はうみの中央にうつるとも我儕はおそれじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'よしその水はなりとどろきてさわぐとも その溢れきたるによりて山はゆるぐとも何かあらん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, '河ありそのながれは神のみやこをよろこばしめ至上者のすみたまふ聖所をよろこばしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, '神そのなかにいませば都はうごかじ 神は朝つとにこれを助けたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'もろもろの民はさわぎたち もろもろの國はうごきたり 神その聲をいだしたまへば地はやがてとけぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, '萬軍のヱホバはわれらとともなり ヤコブの神はわれらのたかき櫓なり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'きたりてヱホバの事跡をみよ ヱホバはおほくの懼るべきことを地になしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'ヱホバは地のはてまでも戰闘をやめしめ弓ををり戈をたち戰車を火にてやきたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '汝等しづまりて我の神たるをしれ われはもろもろの國のうちに崇められ全地にあがめらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, '萬軍のヱホバはわれらと偕なり ヤコブの神はわれらの高きやぐらなり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, '伶長にうたはしめたるコラの子のうた もろもろのたみよ手をうち歓喜のこゑをあげ神にむかひてさけべ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'いとたかきヱホバはおそるべく また地をあまねく治しめす大なる王にてましませばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'ヱホバはもろもろの民をわれらに服はせ もろもろの國をわれらの足下にまつろはせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, '又そのいつくしみたまふヤコブが譽とする嗣業をわれらのために選びたまはん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, '神はよろこびさけぶ聲とともにのぼり ヱホバはラッパの聲とともにのぼりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'ほめうたへ神をほめうたへ 頌歌へわれらの王をほめうたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'かみは地にあまねく王なればなり 敎訓のうたをうたひてほめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, '神はもろもろの國をすべをさめたまふ 神はそのきよき寳座にすわりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'もろもろのたみの諸侯はつどひきたりてアブラハムの神の民となれり 地のもろもろの盾は神のものなり神はいとたふとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'コラの子のうたなり讃美なり ヱホバは大なり われらの神の都そのきよき山のうへにて甚くほめたたへられたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'シオンの山はきたの端たかくしてうるはしく喜悦を地にあまねくあたふ ここは大なる王のみやこなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'そのもろもろの殿のうちに神はおのれをたかき櫓としてあらはしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'みよ王等はつどひあつまりて偕にすぎゆきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'かれらは都をみてあやしみ且おそれて忽ちのがれされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, '戰慄はかれらにのぞみ その苦痛は子をうまんとする婦のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'なんぢは東風をおこしてタルシシの舟をやぶりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, '曩にわれらが聞しごとく今われらは萬軍のヱホバの都われらの神のみやこにて之をみることをえたり 神はこの都をとこしへまで固くしたまはん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, '神よ我らはなんぢの宮のうちにて仁慈をおもへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, '神よなんぢの譽はその名のごとく地の極にまでおよべり なんぢの右手はただしきにて充り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'なんぢのもろもろの審判によりてシオンの山はよろこびユダの女輩はたのしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'シオンの周圍をありき徧くめぐりてその櫓をかぞへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'その石垣に目をとめよ そのもろもろの殿をみよ なんぢらこれを後代にかたりつたへんが爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'そはこの神はいや遠長にわれらの神にましましてわれらを死るまでみちびきたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, '伶長にうたはしめたるコラの子のうた もろもろの民よきけ賤きも貴きも富るも貧きもすべて地にすめる者よ なんぢらともに耳をそばだてよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, '伶長にうたはしめたるコラの子のうた もろもろの民よきけ賤きも貴きも富るも貧きもすべて地にすめる者よ なんぢらともに耳をそばだてよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'わが口はかしこきことをかたり わが心はさときことを思はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'われ耳を喩言にかたぶけ琴をならしてわが幽玄なる語をときあらはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'わが踵にちかかる不義のわれを打圍むわざはひの日もいかで懼るることあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'おのが富をたのみ財おほきを誇るもの');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'たれ一人おのが兄弟をあがなふことあたはず之がために贖價を神にささげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '之をとこしへに生存へしめて朽ざらしむることあたはず(霊魂をあがなふには費いとおほくして此事をとこしへに捨置ざるを得ざればなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, '之をとこしへに生存へしめて朽ざらしむることあたはず(霊魂をあがなふには費いとおほくして此事をとこしへに捨置ざるを得ざればなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'そは智きものも死 おろかものも獣心者もひとしくほろびてその富を他人にのこすことは常にみるところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'かれら竊におもふ わが家はとこしへに存りわがすまひは世々にいたらんと かれらはその地におのが名をおはせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'されど人は譽のなかに永くとどまらず亡びうする獣のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, '斯のごときは愚かなるものの途なり 然はあれど後人はその言をよしとせん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'かれらは羊のむれのごとくに陰府のものと定めらる 死これが牧者とならん直きもの朝にかれらををさめん その美容は陰府にほろぼされて宿るところなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'されど神われを接たまふべければわが霊魂をあがなひて陰府のちからより脱かれしめたまはん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, '人のとみてその家のさかえくははらんとき汝おそるるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'かれの死るときは何一つたづさへゆくことあたはず その榮はこれにしたがひて下ることをせざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'かかる人はいきながらふるほどに己がたましひを祝するとも みづからを厚うするがゆゑに人々なんぢをほむるとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'なんぢ列祖の世にゆかん かれらはたえて光をみざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, '尊貴なかにありて暁らざる人はほろびうする獣のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'アサフのうた ぜんのうの神ヱホバ詔命して日のいづるところより日のいるところまであまねく地をよびたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'かみは美麗の極なるシオンより光をはなちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'われらの神はきたりて默したまはじ火その前にものをやきつくし暴風その四周にふきあれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, '神はその民をさばかんとて上なる天および地をよびたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'いはく祭物をもて我とけいやくをたてしわが聖徒をわがもとに集めよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'もろもろの天は神の義をあらはせり 神はみづから審士たればなり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'わが民よきけ我ものいはんイスラエルよきけ我なんぢにむかひて證をなさん われは神なんぢの神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'わがなんぢを責るは祭物のゆゑにあらず なんぢの燔祭はつねにわが前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, '我はなんぢの家より牡牛をとらず なんぢの牢より牡山羊をとらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, '林のもろもろのけもの山のうへの千々の牲畜はみなわが有なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'われは山のすべての鳥をしる 野のたけき獣はみなわがものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, '世界とそのなかに充るものとはわが有なれば縦ひわれ饑るともなんぢに告じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'われいかで牡牛の肉をくらひ牡山羊の血をのまんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, '感謝のそなへものを神にささげよ なんぢのちかひを至上者につくのへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'なやみの日にわれをよべ我なんぢを援けん而してなんぢ我をあがむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, '然はあれど神あしきものに言給く なんぢは敎をにくみ わが言をその後にすつるものなるに何のかかはりありてわが律法をのべ わがけいやくを口にとりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, '然はあれど神あしきものに言給く なんぢは敎をにくみ わが言をその後にすつるものなるに何のかかはりありてわが律法をのべ わがけいやくを口にとりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'なんぢ盗人をみれば之をよしとし姦淫をおこなふものの伴侶となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'なんぢその口を惡にわたす なんぢの舌は詭計をくみなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'なんぢ坐りて兄弟をそしり己がははの子を誣ののしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, '汝これらの事をなししをわれ默しぬれば なんぢ我をおのれに恰にたるものとおもへり されど我なんぢを責めてその罪をなんぢの目前につらぬべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, '神をわするるものよ今このことを念へ おそらくは我なんぢを抓さかんとき助るものあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, '感謝のそなへものを献るものは我をあがむ おのれの行爲をつつしむ者にはわれ神の救をあらはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'ダビデがバテセバにかよひしのち預言者ナタンの來れるときよみて伶長にうたはしめたる歌 ああ神よねがはくはなんぢの仁慈によりて我をあはれみ なんぢの憐憫のおほきによりてわがもろもろの愆をけしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'わが不義をことごとくあらひさり我をわが罪よりきよめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'われはわが愆をしる わが罪はつねにわが前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, '我はなんぢにむかひて獨なんぢに罪ををかし聖前にあしきことを行へり されば汝ものいふときは義とせられ なんぢ鞫くときは咎めなしとせられ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, '視よわれ邪曲のなかにうまれ罪ありてわが母われをはらみたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'なんぢ眞實をこころの衷にまでのぞみ わが隠れたるところに智慧をしらしめ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'なんぢヒソブをもて我をきよめたまへ さらばわれ淨まらん 我をあらひたまへ さらばわれ雪よりも白からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'なんぢ我によろこびと快樂とをきかせ なんぢが碎きし骨をよろこばせたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'ねがはくは聖顔をわがすべての罪よりそむけ わがすべての不義をけしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'ああ神よわがために清心をつくり わが衷になほき霊をあらたにおこしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'われを聖前より棄たまふなかれ 汝のきよき霊をわれより取りたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'なんぢの救のよろこびを我にかへし自由の霊をあたへて我をたもちたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'さらばわれ愆ををかせる者になんぢの途ををしへん罪人はなんぢに歸りきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, '神よわが救のかみよ血をながしし罪より我をたすけいだしたまへ わが舌は聲たからかになんぢの義をうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, '主よわが口唇をひらきたまへ 然ばわが口なんぢの頌美をあらはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'なんぢは祭物をこのみたまはず もし然らずば我これをささげん なんぢまた燔祭をも悦びたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, '神のもとめたまふ祭物はくだけたる霊魂なり 神よなんぢは碎けたる悔しこころを藐しめたまふまじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'ねがはくは聖意にしたがひてシオンにさいはひし ヱルサレムの石垣をきづきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'その時なんぢ義のそなへものと燔祭と全きはんさいとを悦びたまはん かくて人々なんぢの祭壇に牡牛をささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'エドム人ドエグ、サウルにきたりてダビデはアビメレクの家にきぬと告しときダビデがよみて伶長にうたはしめたる敎訓のうた 猛者よなんぢ何なればあしき企圖をもて自らほこるや神のあはれみは恒にたえざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'なんぢの舌はあしきことをはかり利き剃刀のごとくいつはりをおこなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'なんぢは善よりも惡をこのみ正義をいふよりも虚偽をいふをこのむ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'たばかりの舌よなんぢはすべての物をくひほろぼす言をこのむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'されば神とこしへまでも汝をくだき また汝をとらへてその幕屋よりぬきいだし生るものの地よりなんぢの根をたやしたまはん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, '義者はこれを見ておそれ彼をわらひていはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '神をおのが力となさず その富のゆたかなるをたのみ その惡をもて己をかたくせんとする人をみよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, '然はあれどわれは神の家にあるあをき橄欖の樹のごとし 我はいやとほながに神のあはれみに依賴まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'なんぢこの事をおこなひ給ひしによりて我とこしへになんぢに感謝し なんぢの聖徒のまへにて聖名をまちのぞまん こは宜しきことなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'マハラツ(樂器の名、あるひはいふ調べの名)にあはせて伶長にうたはしめたるダビデの敎訓のうた 愚かなるものは心のうちに神なしといへり かれらは腐れたりかれらは憎むべき不義をおこなへり善をおこなふ者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, '神は天より人の子をのぞみて悟るものと神をたづぬる者とありやなしやを見たまひしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'みな退ぞきてことごとく汚れたり善をなすものなし一人だになし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, '不義をおこなふものは知覺なきか かれらは物くふごとくわが民をくらひ また神をよばふことをせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'かれらは懼るべきことのなきときに大におそれたり 神はなんぢにむかひて營をつらぬるものの骨をちらしたまへばなり 神かれらを棄たまひしによりて汝かれらを辱かしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, '願くはシオンよりイスラエルの救のいでんことを 神その民のとらはれたるを返したまふときヤコブはよろこびイスラエルは樂まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'ジフ人のサウルにきたりてダビデはわれらの處にかくれをるにあらずやといひたりしとき ダビデうたのかみに琴にてうたはしめたる敎訓のうた 神よねがはくは汝の名によりて我をすくひ なんぢの力をもて我をさばきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, '神よわが祈をききたまへ わが口のことばに耳をかたぶけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'そは外人はわれにさからひて起りたち強暴人はわがたましひを索むるなり かれらは神をおのが前におかざりき セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'みよ神はわれをたすくるものなり 主はわがたましひを保つものとともに在せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, '主はわが仇にそのあしきことの報をなしたまはん 願くはなんぢの眞實によりて彼等をほろぼしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, '我よろこびて祭物をなんぢに献ん ヱホバよ我なんぢの名にむかひて感謝せん こは宜しきことなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'そはヱホバはすべての患難より我をすくひたまへり わが目はわが仇につきての願望をみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'ダビデうたのかみに琴にてうたはしめたる敎訓のうた 神よねがはくは耳をわが祈にかたぶけたまへ わが懇求をさけて身をかくしたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'われに聖意をとめ 我にこたへたまへ われ歎息によりてやすからず悲みうめくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'これ仇のこゑと惡きものの暴虐とのゆゑなり そはかれら不義をわれに負せ いきどほりて我におひせまるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'わが心わがうちに憂ひいたみ死のもろもろの恐懼わがうへにおちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'おそれと戰慄とわれにのぞみ甚だしき恐懼われをおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'われ云ねがはくは鴿のごとく羽翼のあらんことを さらば我とびさりて平安をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'みよ我はるかにのがれさりて野にすまん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'われ速かにのがれて暴風と狂風とをはなれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'われ都のうちに強暴とあらそひとをみたり 主よねがはくは彼等をほろぼしたまへ かれらの舌をわかれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, '彼等はひるもよるも石垣のうへをあるきて邑をめぐる 邑のうちには邪曲とあしき企圖とあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'また惡きこと邑のうちにあり しへたげと欺詐とはその街衢をはなるることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'われを謗れるものは仇たりしものにあらず もし然りしならば尚しのばれしなるべし 我にむかひて己をたかくせし者はわれを恨たりしものにあらず若しかりしならば身をかくして彼をさけしなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'されどこれ汝なり われとおなじきもの わが友われと親しきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'われら互にしたしき語らひをなし また會衆のなかに在てともに神の家にのぼりたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, '死は忽然かれらにのぞみ その生るままにて陰府にくだらんことを そは惡事その住處にありその中にあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'されど我はただ神をよばんヱホバわれを救ひたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, '夕にあしたに晝にわれなげき且かなしみうめかん ヱホバわが聲をききたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'ヱホバは我をせむる戰闘よりわが霊魂をあがなひいだして平安をえしめたまへり そはわれを攻るもの多かりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, '太古よりいます者なる神はわが聲をききてかれらを惱めたまべし セラ かれらには變ることなく神をおそるることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'かの人はおのれと睦みをりしものに手をのべてその契約をけがしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'その口はなめらかにして乳酥のごとくなれどもその心はたたかひなり その言はあぶらに勝りてやはらかなれどもぬきたる劍にことならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'なんぢの荷をヱホバにゆだねよさらば汝をささへたまはん ただしき人のうごかさるることを常にゆるしたまふまじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'かくて神よなんぢはかれらを亡の坑におとしいれたまはん血をながすものと詭計おほきものとは生ておのが日の半にもいたらざるべし 然はあれどわれは汝によりたのまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'ダビデがガテにてペリシテ人にとらへられしとき詠て「遠きところにをる音をたてぬ鴿」のしらべにあはせて伶長にうたはしめたるミクタムの歌 ああ神よねがはくは我をあはれみたまへ 人いきまきて我をのまんとし終日たたかひて我をしへたぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'わが仇ひねもす急喘てわれをのまんとす誇りたかぶりて我とたたかふものおほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'われおそるるときは汝によりたのまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'われ神によりてその聖言をほめまつらん われ神に依賴みたればおそるることあらじ肉體われになにをなし得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'かれらは終日わがことばを曲るなり その思念はことごとくわれにわざはひをなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'かれらは群つどひて身をひそめ わが歩に目をとめてわが霊魂をうかがひもとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'かれらは不義をもてのがれんとおもへり 神よねがはくは憤ほりてもろもろの民をたふしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, '汝わがあまた土の流離をかぞへたまへり なんぢの革嚢にわが涙をたくはへたまへ こは皆なんぢの冊にしるしあるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'わがよびもとむる日にはわが仇しりぞかん われ神のわれを守りたまふことを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'われ神によりてその聖言をはめまつらん 我ヱホバによりてそのみことばを讃まつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'われ神によりたのみたれば懼るることあらじ 人はわれに何をなしえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, '神よわがなんぢにたてし誓はわれをまとへり われ感謝のささげものを汝にささげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, '汝わがたましひを死よりすくひたまへばなり なんぢ我をたふさじとわが足をまもり生命の光のうちにて神のまへに我をあゆませ給ひしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'ダビデが洞にいりてサウルの手をのがれしとき詠て「ほろぼすなかれ」にといふ調にあはせて伶長にうたはしめたるミクタムのうた 我をあはれみたまへ神よわれをあはれみたまへ わが霊魂はなんぢを避所とす われ禍害のすぎさるまではなんぢの翼のかげを避所とせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, '我はいとたかき神によばはん わがために百事をなしをへたまふ神によばはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, '神はたすけを天よりおくりて我をのまんとする者のそしるときに我を救ひたまはん セラ 神はその憐憫その眞實をおくりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'わがたましひは群ゐる獅のなかにあり 火のごとくもゆる者 その歯は戈のごとく矢のごとくその舌はとき劍のごとき人の子のなかに我ふしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, '神よねがはくはみづからを天よりも高くしみさかえを全地のうへに擧たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'かれらはわが足をとらへんとて網をまうく わが霊魂はうなたる かれらはわがまへに阱をほりたり而してみづからその中におちいれり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'わが心さだまれり神よわがこころ定まれり われ謳ひまつらん頌まつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'わが榮よさめよ 筝よ琴よさめよ われ黎明をよびさまさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, '主よわれもろもろの民のなかにてなんぢに感謝し もろもろの國のなかにて汝をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'そは汝のあはれみは大にして天にまでいたり なんぢの眞實は雲にまでいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, '神よねがはくは自からを天よりも高くし光榮をあまねく地のうへに擧たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'ダビデがよみて「ほろぼすなかれ」といふ調にあはせて伶長にうたはしめたるミクタムのうた なんぢら默しゐて義をのべうるか 人の子よなんぢらなほき審判をおこなふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, '否なんぢらは心のうちに惡事をおこなひ その手の強暴をこの地にはかりいだすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'あしきものは胎をはなるるより背きとほざかり生れいづるより迷ひていつはりをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'かれらの毒は蛇のどくのごとし かれらは蠱術をおこなふものの甚たくみにまじなふその聲をだにきかざる耳ふさぐ聾ひの蝮のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'かれらの毒は蛇のどくのごとし かれらは蠱術をおこなふものの甚たくみにまじなふその聲をだにきかざる耳ふさぐ聾ひの蝮のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, '神よかれらの口の歯ををりたまヘ ヱホバよ壯獅の牙をぬきくだきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, '願くはかれらを流れゆく水のごとくに消失しめ その矢をはなつときは折れたるごとくなし給はんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'また融てきえゆく蝸牛のごとく婦のときならず產たる目をみぬ嬰のごとくならしめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'なんぢらの釜いまだ荊蕀の火をうけざるさきに靑をも燃たるをもともに狂風にて吹さりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, '義者はかれらが讎かへさるるを見てよろこび その足をあしきものの血のなかにてあらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'かくて人はいふべし實にただしきものに報賞あり實にさばきをほどこしたまふ神はましますなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'サウル、ダビデを殺さんとし人をおくりてその家をうかがはしめし時ダビデがよみて「ほろぼすなかれ」といふ調にあはせて伶長にうたはしめたるミクタムの歌 わが神よねがはくは我をわが仇よりたすけいだし われを高處におきて我にさからひ起立つものより脱かれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, '邪曲をおこなふものより我をたすけいだし血をながす人より我をすくひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, '視よかれらは潜みかくれてわが霊魂をうかがひ猛者むれつどひて我をせむ ヱホバよ此はわれに愆あるにあらず われに罪あるにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'かれら趨りまはりて過失なきに我をそこなはんとて備をなす ねがはくは我をたすくるために目をさまして見たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'なんぢヱホバ萬軍の神イスラエルの神よ ねがはくは目をさましてもろもろの國にのぞみたまへ あしき罪人にあはれみを加へたまふなかれ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'かれらは夕にかへりきたり犬のごとくほえて邑をへありく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, '視よかれらは口より惡をはく そのくちびるに劍あり かれらおもへらく誰ありてこの言をきかんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'されどヱホバよ汝はかれらをわらひ もろもろの國をあざわらひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'わが力よわれ汝をまちのぞまん 神はわがたかき櫓なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, '憐憫をたまふ神はわれを迎へたまはん 神はわが仇につきての願望をわれに見させたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, '願くはかれらを殺したまふなかれ わが民つひに忘れやはせん 主われらの盾よ 大能をもてかれらを散し また卑したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'かれらがくちびるの言はその口のつみなり かれらは詛と虚偽とをいひいづるによりてその傲慢のためにとらへられしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, '忿恚をもてかれらをほろぼしたまへ 再びながらふることなきまでに彼等をほろぼしたまへ ヤコブのなかに神いまして統治めたまふことをかれらに知しめて地の極にまでおよぼしたまへ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'かれらは夕にかへりきたり犬のごとくほえて邑をへありくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'かれらはゆききして食物をあさり もし飽ことなくば終夜とどまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'されど我はなんぢの大能をうたひ清晨にこゑをあげてなんぢの憐憫をうたひまつらん なんぢわが迫りくるしみたる日にたかき櫓となり わが避所となりたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'わがちからよ我なんぢにむかひて頌辭をうたひまつらん 神はわがたかき櫓われにあはれみをたまふ神なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'ダビデ、ナハライムのアラムおよびゾバのアラムとたたかひをりしがヨアブかへりゆき鹽谷にてエドム人一萬二千をころししとき敎訓をなさんとてダビデがよみて「證詞の百合花」といふ調にあはせて伶長にうたはしめたるミクタムの歌 神よなんぢわれらを棄われらをちらし給へり なんぢは憤ほりたまへり ねがはくは再びわれらを歸したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'なんぢ國をふるはせてこれを裂たまへり ねがはくはその多くの隙をおぎなひたまへ そは國ゆりうごくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'なんぢはその民にたへがたきことをしめし 人をよろめかする酒をわれらに飮しめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'なんぢ眞理のために擧しめんとて汝をおそるるものに一つの旗をあたへたまへり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'ねがはくは右の手をもて救をほどこし われらに答をなして愛しみたまふものに助をえしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, '神はその聖をもていひたまへり われ甚くよろこばん われシケムをわかちスコテの谷をはからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'ギレアデはわがもの マナセはわが有なり エフライムも亦わが首のまもりなり ユダはわが杖');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'モアブはわが足盥なり エドムにはわが履をなげん ベリシテよわが故によりて聲をあげよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'たれかわれを堅固なる邑にすすましめんや 誰かわれをみちびきてエドムにゆきたるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, '神よなんぢはわれらを棄たまひしにあらずや 神よなんぢはわれらの軍とともにいでゆきたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'ねがはくは助をわれにあたへて敵にむかはしめたまへ 人のたすけは空しければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'われらは神によりて勇しくはたらかん われらの敵をみたまふものは神なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, '琴にあはせて伶長にうたはしめたるダビデのうた ああ神よねがはくはわが哭聲をききたまへ わが祈にみこころをとめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'わが心くづほるるとき地のはてより汝をよばん なんぢ我をみちびきてわが及びがたきほどの高き磐にのぼらせたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'なんぢはわが避所われを仇よりのがれしむる堅固なる櫓なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'われ永遠になんぢの帷幄にすまはん我なんぢの翼の下にのがれん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, '神よなんぢはわがもろもろの誓をきき名をおそるるものにたまふ嗣業をわれにあたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'なんぢは王の生命をのばし その年を幾代にもいたらせたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, '王はとこしへに神のみまへにとどまらん ねがはくは仁慈と眞實とをそなへて彼をまもりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'さらば我とこしへに名をほめうたひて日ごとにわがもろもろの誓をつくのひ果さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'エドトンの體にしたがひて伶長にうたはしめたるダビデのうた わがたましひは默してただ神をまつ わがすくひは神よりいづるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, '神こそはわが磐わがすくひなれ またわが高き櫓にしあれば我いたくは動かされじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'なんぢらは何のときまで人におしせまるや なんぢら相共にかたぶける石垣のごとく搖ぎうごける籬のごとくに人をたふさんとするか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'かれらは人をたふとき位よりおとさんとのみ謀り いつはりをよろこびまたその口にてはいはひその心にてはのろふ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'わがたましひよ默してただ神をまて そはわがのぞみは神よりいづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, '神こそはわが磐わがすくひなれ 又わがたかき櫓にしあれば我はうごかされじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'わが救とわが榮とは神にあり わがちからの磐わがさけどころは神にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, '民よいかなる時にも神によりたのめ その前になんぢらの心をそそぎいだせ 神はわれらの避所なり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, '實にひくき人はむなしくたかき人はいつはりなり すべてかれらを權衡におかば上にあがりて虚しきものよりも軽きなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, '暴虐をもて恃とするなかれ 掠奪ふをもてほこるなかれ 富のましくははる時はこれに心をかくるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'ちからは神にあり神ひとたび之をのたまへり われ二次これをきけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'ああ主よあはれみも亦なんぢにあり なんぢは人おのおのの作にしたがひて報をなしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'ユダの野にありしときに詠るダビデのうた ああ神よなんぢはわが神なり われ切になんぢをたづねもとむ 水なき燥きおとろへたる地にあるごとくわが霊魂はかわきて汝をのぞみ わが肉體はなんぢを戀したふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, '曩にも我かくのごとく大權と榮光とをみんことをねがひ聖所にありて目をなんぢより離れしめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'なんぢの仁慈はいのちにも勝れるゆゑにわが口唇はなんぢを讃まつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, '斯われはわが生るあひだ汝をいはひ名によりてわが手をあげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'われ床にありて汝をおもひいで夜の更るままになんぢを深くおもはん時 わがたましひは髓と脂とにて饗さるるごとく飽ことをえ わが口はよろこびの口唇をもてなんぢを讃たたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'われ床にありて汝をおもひいで夜の更るままになんぢを深くおもはん時 わがたましひは髓と脂とにて饗さるるごとく飽ことをえ わが口はよろこびの口唇をもてなんぢを讃たたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'そはなんぢわが助となりたまひたれば 我なんぢの翼のかげに入てよろこびたのしまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'わがたましひはなんぢを慕追ふ みぎの手はわれを支ふるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, '然どわがたましひを滅さんとて尋ねもとむるものは地のふかきところにゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, '又つるぎの刃にわたされ野犬の獲るところとなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'しかれども王は神をよろこばん 神によりて誓をたつるものはみな誇ることをえん 虚偽をいふものの口はふさがるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, '伶長にうたはしめたるダビデのうた 神よわがなげくときわが聲をききたまへ わが生命をまもりて仇のおそれより脱かれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'ねがはくは汝われをかくして惡をなすものの陰かなる謀略よりまぬかれしめ不義をおこなふものの喧嘩よりまぬかれしめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'かれらは劍のごとくおのが舌をとぎ その弓をはり矢をつがへるごとく苦言をはなち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, '隠れたるところにて全者を射んとす俄かにこれを射ておそるることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'また彼此にあしき企圖をはげまし共にはかりてひそかに羂をまうく 斯ていふ誰かわれらを見んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'かれらはさまざまの不義をたづねいだして云われらは懇ろにたづね終れりと おのおのの衷のおもひと心とはふかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, '然はあれど神は矢にてかれらを射たまふべし かれらは俄かに傷をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, '斯てかれらの舌は其身にさからふがゆゑに遂にかれらは蹟かん これを見るものみな逃れさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'もろもろの人はおそれん而して神のみわざをのべつたへ その作たまへることを考ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, '義者はヱホバをよろこびて之によりたのまん すべて心のなほきものは皆ほこることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, '伶長にうたはしめたる歌ダビデの讃美なり ああ神よさんびはシオンにて汝をまつ 人はみまへにて誓をはたさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, '祈をききたまふものよ諸人こぞりて汝にきたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, '不義のことば我にかてり なんぢ我儕のもろもろの愆をきよめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, '汝にえらばれ汝にちかづけられて大庭にすまふ者はさいはひなり われらはなんぢの家なんぢの宮のきよき處のめぐみにて飽ことをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'われらが救のかみよ 地と海とのもろもろの極なるきはめて遠ものの恃とするなんぢは公義によりて畏るべきことをもて我儕にこたへたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'かみは大能をおび その權力によりてもろもろの山をかたくたたしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, '海のひびき狂瀾のひびき もろもろの民のかしがましきを鎮めたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'されば極遠にすめる人々もなんぢのくさぐさの豫兆をみておそる なんぢ朝夕のいづる處をよろこび謳はしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'なんぢ地にのぞみて漑そぎおほいに之をゆたかにしたまへり 神のかはに水みちたり なんぢ如此そなへをなして穀物をかれらにあたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'なんぢ畎をおほいにうるほし畝をたひらにし白雨にてこれをやはらかにし その萌芽るを祝し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'また恩惠をもて年の冕弁としたまへり なんぢの途には膏したたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'その恩滴は野の牧場をうるほし小山はみな歓びにかこまる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, '牧場はみな羊のむれを衣もろもろの谷は穀物におほはれたり かれらは皆よろこびてよばはりまた謳ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, '伶長にうたはしめたる讃美なり 歌なり 全地よ神にむかひて歓びよばはれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'その名の榮光をうたへその頌美をさかえしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'かみに告まつれ 汝のもろもろの功用はおそるべきかな大なる力によりてなんぢの仇はなんぢに畏れしたがひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, '全地はなんぢを拝みてうたひ名をほめうたはんと セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, '來りて神のみわざをみよ 人の子輩にむかひて作たまふことはおそるべきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, '神はうみをかへて乾ける地となしたまへり ひとびと歩行にて河をわたりき その處にてわれらは神をよろこべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, '神はその大能をもてとこしへに統治め その目は諸國をみたまふ そむく者みづからを崇むべからず セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'もろもろの民よ われらの神をほめまつれ神をほめたたふる聲をきこえしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, '神はわれらの霊魂をながらへしめ われらの足のうごかさるることをゆるしたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, '神よなんぢはわれらを試みて白銀をねるごとくにわれらを錬たまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, '汝われらを網にひきいれ われらの腰におもき荷をおき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, '人々をわれらの首のうへに騎こえしめたまひき われらは火のなか水のなかをすぎゆけり されど汝その中よりわれらをひきいたし豊盛なる處にいたらしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'われ燔祭をもてなんぢの家にゆかん 迫りくるしみたるときにわが口唇のいひいでわが口ののべし誓をなんぢに償はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'われ燔祭をもてなんぢの家にゆかん 迫りくるしみたるときにわが口唇のいひいでわが口ののべし誓をなんぢに償はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'われ肥たるものを燔祭とし牡羊を馨香として汝にささげ牡牛と牡山羊とをそなへまつらん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, '神をおそるる人よ みな來りてきけ われ神のわがたましひのために作たまへることをのべん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'われわが口をもて神によばはり また舌をもてあがむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, '然るにわが心にしれる不義あらば主はわれにききたまふまじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'されどまことに神はききたまへり聖意をわがいのりの聲にとめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, '神はほむべきかな わが祈をしりぞけず その憐憫をわれよりとりのぞきたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, '琴にあはせて伶長にうたはしめたる歌なり 讃美なり ねがはくは神われらをあはれみ われらをさきはひてその聖顔をわれらのうへに照したまはんことを セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, '此はなんぢの途のあまねく地にしられ なんぢの救のもろもろの國のうちに知れんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'かみよ庶民はなんぢに感謝し もろもろの民はみな汝をほめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'もろもろの國はたのしみ又よろこびうたふべし なんぢ直をもて庶民をさばき地のうへなる萬の國ををさめたまべければなり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, '神よたみらはなんぢに感謝し もろもろの民はみな汝をほめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, '地は產物をいだせり 神わが神はわれらを福ひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, '神われらをさきはひたまふべし かくて地のもろもろの極ことごとく神をおそれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, '伶長にうたはしめたるダビデのうたなり 讃美なり ねがはくは神おきたまへ その仇はことごとくちり 神をにくむものは前よりにげさらんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, '烟のおひやらるるごとくかれらを驅逐たまへ 惡きものは火のまへに蝋のとくるごとく 神のみまへにてほろぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'されど義きものには歓喜あり かれら神の前にてよろこびをどらん實にたのしみて喜ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, '神のみまへにうたへ その名をほめたたへよ 乗て野をすぐる者のために大道をきづけ かれの名をヤハとよぶ その前によろこびをどれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'きよき住居にまします神はみなしごの父やもめの審士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, '神はよるべなきものを家族の中にをらしめ囚人をとき福祉にみちびきたまふ されど悖逆者はうるほひなき地にすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, '神よなんぢは民にさきだちいでて野をすすみゆきたまひき セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'そのとき地ふるひ天かみのみまへに漏る シナイの山すら神イスラエルの神の前にふるひうごけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, '神よなんぢの嗣業の地のつかれおとろへたるとき豊かなる雨をふらせて之をかたくしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, '曩になんぢの公會はその中にとどまれり 神よなんぢは惠をもて貧きもののために預備をなしたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, '主みことばを賜ふ その佳音をのぶる婦女はおほくして群をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'もろもろの軍旅の王たちはにげさる 逃去りたれば家なる婦女はその掠物をわかつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'なんぢら羊の牢のうちにふすときは鴿のつばさの白銀におほはれその毛の黄金におほはるるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, '全能者かしこにて列王をちらし給へるときはサルモンの山に雪ふりたるがごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'バシャンのやまは神の山なりバシャンのやまは峰かさなれる山なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, '峰かさなれるもろもろの山よ なんぢら何なれば神の住所にえらびたまへる山をねたみ見るや 然れヱホバは永遠にこの山にすみたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, '神の戰車はよろづに萬をかさね千にちぢをくはふ 主その中にいませり 聖所にいますがごとくシナイの山にいまししがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'なんぢ高處にのぼり虜者をとりこにしてひきゐ禮物を人のなかよりも叛逆者のなかよりも受たまへり ヤハの神ここに住たまはんが爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, '日々にわれらの荷をおひたまふ主われらのすくひの神はほむべきかな セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, '神はしばしばわれらを助けたまへる神なり 死よりのがれうるは主ヱホバに由る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, '神はその仇のかうべを撃やぶりたまはん 愆のなかにとどまるものの髮おほき顱頂をうちやぶりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, '主いへらく我バシャンよりかれらを携へかへり海のふかき所よりたづさへ歸らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, '斯てなんぢの足をそのあたの血にひたし之をなんぢの犬の舌になめしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, '神よすべての人はなんぢの進行きたまふをみたり わが神わが王の聖所にすすみゆきたまふを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, '鼗うつ童女のなかにありて謳ふものは前にゆき琴ひくものは後にしたがへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'なんぢらすべての會にて神をほめよイスラエルのみなもとより出るなんぢらよ 主をほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, '彼處にかれらを統るとしわかきベニヤミンあり ユダの諸侯とその群衆とありまたゼブルンのきみたちナフタリの諸侯あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'なんぢの神はなんぢの力をたてたまへり 神よなんぢ我儕のためになしたまひし事をかたくしたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'ヱルサレムなるなんぢの宮のために列王なんぢに禮物をささげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'ねがはくは葦間の獣むらがれる牯犢のごときもろもろの民をいましめてかれらに白銀をたづさへきたり みづから服ふことを爲しめたまへ 神はたたかひを好むもろもろの民をちらしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, '諸侯はエジプトよりきたり エテオピアはあわただしく神にむかひて手をのべん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, '地のもろもろのくによ神のまへにうたへ主をほめうたへ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, '上古よりの天の天にのりたま者にむかひてうたへ みよ主はみこゑを發したまふ勢力ある聲をいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'なんぢらちからを神に歸せよその稜威はイスラエルの上にとどまり その大能は雲のなかにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, '神のおそるべき状はきよき所よりあらはる イスラエルの神はその民にちからと勢力とをあたへたまふ 神はほむべきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, '百合花にあはせて伶長にうたはしめたるダビデのうた 神よねがはくは我をすくひたまへ 大水ながれきたりて我がたましひにまでおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'われ立止なきふかき泥の中にしづめり われ深水におちいるおほみづわが上をあふれすぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'われ歎息によりてつかれたり わが喉はかわき わが目はわが神をまちわびておとろへぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, '故なくしてわれをにくむ者わがかしらの髮よりもおほく謂なくしてわが仇となり我をほろぼさんとするものの勢力つよし われ掠めざりしものをも償はせらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, '神よなんぢはわが愚なるをしりたまふ わがもろもろの罪はなんぢにかくれざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, '萬軍のヱホバ主よ ねがはくは汝をまちのぞむ者をわが故によりて辱かしめらるることなからしめたまへ イスラエルの神よねがはくはなんぢを求むる者をわが故によりて恥をおはしめらるることなからしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, '我はなんぢのために謗をおひ恥はわが面をおほひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'われわが兄弟には旅人のごとく わが母の子には外人のごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'そはなんぢの家をおもふ熱心われをくらひ汝をそしるものの謗われにおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'われ涙をながして食をたち わが霊魂をなげかすれば反てこれによりて謗をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'われ麁布をころもとなししにかれらが諺語となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, '門にすわる者はわがうへをかたる われは酔狂たるものに謳ひはやされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, '然はあれどヱホバよわれは惠のときに汝にいのる ねがはくは神よなんぢの憐憫のおほきによりて汝のすくひの眞實をもて我にこたへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'ねがはくは泥のなかより我をたすけいだして沈ざらしめたまへ 我をにくむものより深水よりたすけいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, '大水われを淹ふことなく淵われをのむことなく坑その口をわがうへに閉ることなからしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'ヱホバよねがはくは我にこたへたまへ なんぢの仁慈うるはしければなり なんぢの憐憫はおほしわれに歸りきたりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, '面をなんぢの僕にかくしたまふなかれ われ迫りくるしめり ねがはくは速かに我にこたへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'わがたましひに近くよりて之をあがなひわが仇のゆゑに我をすくひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, '汝はわがうくる謗とはぢと侮辱とをしりたまへり わが敵はみな汝のみまへにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, '譭謗わが心をくだきぬれば我いたくわづらへり われ憐憫をあたふる者をまちたれど一人だになく慰むるものを俟たれど一人をもみざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'かれら苦草をわがくひものにあたへ わが渇けるときに醋をのませたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'ねがはくは彼等のまへなる筵は網となり そのたのむ安逸はつひに羂となれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'その目をくらくして見しめず その腰をつねにふるはしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, '願くはなんぢの忿恚をかれらのうへにそそぎ汝のいかりの猛烈をかれらに追及せたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'かれらの屋をむなしくせよ その幕屋に人をすまはするなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'かれらはなんぢが撃たまひたる者をせめ なんぢが傷けたまひたるものの痛をかたりふるればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'ねがはくはれらの不義に不義をくはへてなんぢの義にあづからせ給ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'かれらを生命の册よりけして義きものとともに記さるることなからしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, '斯てわれはくるしみ且うれひあり 神よねがはくはなんぢの救われを高處におかんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'われ歌をもて神の名をほめたたへ 感謝をもて神をあがめまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, '此はをうしまたは角と蹄とある力つよき牡牛にまさりてヱホバよろこびたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, '謙遜者はこれを見てよろこべり 神をしたふ者よなんぢらの心はいくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'ヱホバは乏しきものの聲をきき その俘囚をかろしめたまはざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, '天地はヱホバをほめ蒼海とその中にうごくあらゆるものとはヱホバを讃まつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, '神はシオンをすくひユダのもろもろの邑を建たまふべければなり かれらは其處にすみ且これをおのが有とせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'その僕のすゑも亦これを嗣その名をいつくしむ者その中にすまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, '伶長にうたはしめたるダビデが記念のうた 神よねがはくは我をすくひたまヘ ヱホバよ速きたりて我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'わが霊魂をたづぬるものの恥あわてんことを わが害はるるをよろこぶものの後にしりぞきて恥をおはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'ああ視よや視よやといふもののおのが恥によりて後にしりぞかんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'すべて汝をたづねもとむる者のなんぢによりて樂みよろこばんことを なんぢの救をしたふもののつねに神は大なるかなととなへんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'われは苦しみ且ともし神よいそぎて我にきたりたまへ 汝はわが助われを救ふものなり ヱホバよねがはくは猶豫たまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'ヱホバよ我なんぢに依賴む ねがはくは何の日までも恥うくることなからしめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'なんぢの義をもて我をたすけ我をまぬかれしめたまへ なんぢの耳をわれに傾けて我をすくひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'ねがはくは汝わがすまひの磐となりたまへ われ恒にそのところに往ことを得ん なんぢ我をすくはんとて勅命をいだしたまへり そは汝はわが磐わが城なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'わが神よあしきものの手より不義殘忍なる人のてより 我をまぬかれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, '主ヱホバよなんぢはわが望なり わが幼少よりの恃なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'われ胎をはなるるより汝にまもられ母の腹にありしときより汝にめぐまれたり 我つねに汝をほめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, '我おほくの人にあやしまるるごとき者となれり 然どなんぢはわが堅固なる避所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'なんぢの頌辭となんぢの頌美とは終日わが口にみちん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'わが年老ぬるとき我をすてたまふなかれ わが力おとろふるとき我をはなれたまなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'わが仇はわがことを論ひ ひわが霊魂をうかがふ者はたがひに議ていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, '神かれを離れたり彼をたすくる者なし かれを追てとらへよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, '神よわれに遠ざかりたまふなかれ わが神よとく來りて我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'わがたましひの敵ははぢ且おとろへ我をそこなはんとするものは謗と辱とにおほはれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'されど我はたえず望をいだきていやますます汝をほめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'わが口はひねもす汝の義となんぢの救とをかたらん われその數をしらざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'われは主ヱホバの大能の事跡をたづさへゆかん われは只なんぢの義のみをかたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, '神よなんぢわれを幼少より敎へたまへり われ今にいたるまで汝のくすしき事跡をのべつたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, '神よねがはくはわれ老て頭髮しろくなるとも我がなんぢの力を次代にのべつたへ なんぢの大能を世にうまれいづる凡のものに宣傳ふるまで我をはなれ給ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, '神よなんぢの義もまた甚たかし なんぢは大なることをなしたまへり 神よたれか汝にひとしき者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, '汝われらを多のおもき苦難にあはせたまへり なんぢ再びわれらを活しわれらを地の深所よりあげたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'ねがはくは我をいよいよ大ならしめ歸りきたりて我をなぐさめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'わが神よさらばわれ筝をもて汝をほめ なんぢの眞實をほめたたへん イスラエルの聖者よわれ琴をもてなんぢを讃うたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'われ聖前にうたときわが口唇よろこびなんぢの贖ひたまへるわが霊魂おほいに喜ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'わが舌もまた終日なんぢの義をかたらん われを害はんとするもの愧惶つればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'ソロモンのうた 神よねがはくは汝のもろもろの審判を王にあたへ なんぢの義をわうの子にあたへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'かれは義をもてなんぢの民をさばき公平をもて苦しむものを鞫かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, '義によりて山と岡とは民に平康をあたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'かれは民のくるしむ者のために審判をなし乏しきものの子輩をすくひ虐ぐるものを壞きたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'かれらは日と月とのあらんかぎり世々おしなべて汝をおそるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'かれは苅とれる牧にふる雨のごとく地をうるほす白雨のごとくのぞまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'かれの世にただしき者はさかえ平和は月のうするまで豊かならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'またその政治は海より海にいたり河より地のはてにおよぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, '野にをる者はそのまへに屈み そり仇は塵をなめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'タルシシおよび島々の王たちは貢ををさめ シバとセバの王たちは禮物をささげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'もろもろの王はそのまへに俯伏し もろもろの國はかれにつかへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'かれは乏しき者をその叫ぶときにすくひ 助けなき苦しむ者をたすけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, '弱きものと乏しき者とをあはれみ乏しきものの霊魂をすくひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'かれらのたましひを暴虐と強暴とよりあがなひたまふ その血はみまへに貴かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'かれらは存ふべし 人はシバの黄金をささげてかれのために恒にいのり終日かれをいははん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, '國のうち五穀ゆたかにしてその實はレバノンのごとく山のいただきにそよぎ 邑の人々は地の草のごとく榮ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'かれの名はつねにたえず かれの名は日の久しきごとくに絶ることなし 人はかれによりて福祉をえん もろもろの國はかれをさいはひなる者ととなへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'ただイスラエルの神のみ奇しき事跡をなしたまへり 神ヱホバはほむべきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'その榮光の名はよよにほむべきかな全地はその榮光にて滿べしアーメン アーメン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'ヱッサイの子ダビデの祈はをはりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'アサフのうた 神はイスラエルにむかひ心のきよきものに對ひてまことに惠あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, '然はあれどわれはわが足つまづくばかりわが歩すべるばかりにてありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'こはわれ惡きものの榮ゆるを見てその誇れる者をねたみしによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'かれらは死るに苦しみなくそのちからは反てかたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'かれらは人のごとく憂にをらず人のごとく患難にあふことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'このゆゑに傲慢は妝飾のごとくその頸をめぐり強暴はころものごとく彼等をおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'かれら肥ふとりてその目とびいで心の欲にまさりて物をうるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'また嘲笑をなし惡をもて暴虐のことばをいだし高ぶりてものいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'その口を天におきその舌を地にあまねく往しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'このゆゑにかれの民はここにかへり水のみちたる杯をしぼりいだして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'いへらく神いかで知たまはんや至上者に知識あらんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, '視よかれらは惡きものなるに常にやすらかにしてその富ましくははれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, '誠に我はいたづらに心をきよめ罪ををかさずして手をあらひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'そはわれ終日なやみにあひ朝ごとに責をうけしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'われもし斯ることを述んといひしならば我なんぢが子輩の代をあやまらせしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'われこれらの道理をしらんとして思ひめぐらししにわが眼いたく痛たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'われ神の聖所にゆきてかれらの結局をふかく思へるまでは然りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, '誠になんぢはかれらを滑かなるところにおきかれらを滅亡におとしいれ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'かれらは瞬間にやぶれたるかな彼等は恐怖をもてことごとく滅びたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, '主よなんぢ目をさましてかれらが像をかろしめたまはんときは夢みし人の目さめたるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'わが心はうれへ わが腎はさされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'われおろかにして知覺なし聖前にありて獣にひとしかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'されど我つねになんぢとともにあり汝わが右手をたもちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'なんぢその訓諭をもて我をみちびき後またわれをうけて榮光のうちに入たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, '汝のほかに我たれをか天にもたん地にはなんぢの他にわが慕ふものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'わが身とわが心とはおとろふ されど神はわがこころの磐わがとこしへの嗣業なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, '視よなんぢに遠きものは滅びん 汝をはなれて姦淫をおこなふ者はみななんぢ之をほろぼしたまひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, '神にちかづき奉るは我によきことなり われは主ヱホバを避所としてそのもろもろの事跡をのべつたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'アサフの敎訓のうた 神よいかなれば汝われらをかぎりなく棄たまひしや 奈何ばなんぢの草苑の羊にみかいかりの煙あがれるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'ねがはくは往昔なんぢが買求めたまへる公會ゆづりの支派となさんとて贖ひたまへるものを思ひいでたまへ又なんぢが住たまふシオンの山をおもひいで給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'とこしへの滅亡の跡にみあしを向たまへ仇は聖所にてもろもろの惡きわざをおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'なんぢの敵はなんぢの集のなかに吼たけびおのが旗をたてて誌とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'かれらは林のしげみにて斧をあぐる人の状にみゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'いま鉞と鎚とをもて聖所のなかなる彫刻めるものをことごとく毀ちおとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'かれらはなんぢの聖所に火をかけ名の居所をけがして地におとしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'かれら心のうちにいふ われらことごとく之をこぼちあらさんと かくて國内なる神のもろもろの會堂をやきつくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'われらの誌はみえず預言者も今はなし 斯ていくその時をかふべき われらのうちに知るものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, '神よ敵はいくその時をふるまでそしるや 仇はなんぢの名をとこしへに汚すならんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'いかなれば汝その手みぎの手をひきたまふや ねがはくは手をふところよりいだしてかれらを滅したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, '神はいにしへよりわが王なり すくひを世の中におこなひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'なんぢその力をもて海をわかち水のなかなる龍の首をくだき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, '鰐のかうべをうちくだき野にすめる民にあたへて食となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'なんぢは泉と水流とをひらき又もろもろの大河をからしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, '晝はなんぢのもの夜も又汝のものなり なんぢは光と日とをそなへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'あまねく地のもろもろの界をたて夏と冬とをつくりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'ヱホバよ仇はなんぢをそしり愚かなる民はなんぢの名をけがせり この事をおもひいでたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, '願くはなんぢの鴿のたましひを野のあらき獣にわたしたまふなかれ 苦しむものに命をとこしへに忘れたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, '契約をかへりみたまへ地のくらきところは強暴の宅にて充たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'ねがはくは虐げらるるものを慚退かしめ給ふなかれ 惱るものと苦しむものとに聖名をほめたたへしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, '神よおきてなんぢの訟をあげつらひ愚かなるものの終日なんぢを謗れるをみこころに記たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'なんぢの敵の聲をわすれたまふなかれ 汝にさからひて起りたつ者のかしがましき聲はたえずあがれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, '「滅すなかれ」といふ調にあはせて伶長にうたはしめたるアサフの歌なり讃美なり 神よわれら汝にかんしやす われら感謝すなんぢの名はちかく坐せばなり もろもろの人はなんぢの奇しき事跡をかたりあへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, '定りたる期いたらば我なほき審判をなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, '地とすべての之にすむものと消去しとき我そのもろもろの柱をたてたり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'われ誇れるものに誇りかにおこなふなかれといひ 惡きものに角をあぐるなかれといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'なんぢらの角をたかく擧るなかれ頸をかたくして高りいふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, '擧ることは東よりにあらず西よりにあらずまた南よりにもあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'ただ神のみ審士にましませば此をさげ彼をあげたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'ヱホバの手にさかづきありて酒あわだてり その中にものまじりてみつ 神これをそそぎいだせり 誠にその滓は地のすべてのあしき者しぼりて飮むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'されど我はヤコブの神をのべつたへん とこしへに讃うたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'われ惡きもののすべての角をきりはなたん 義きものの角はあげらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, '琴にあはせて伶長にうたはしめたるアサフの歌なり讃美なり 神はユダにしられたまへり その名はイスラエルに大なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'またサレムの中にその幕屋あり その居所はシオンにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, '彼所にてかれは弓の火矢ををり盾と劍と戰陣とをやぶりたまひき セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'なんぢ榮光あり掠めうばふ山よりもたふとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, '心のつよきものは掠めらる かれらは睡にしづみ勇ましきものは皆その手を見うしなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'ヤコブの神よなんぢの叱咤によりて戰車と馬とともに深睡につけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, '神よなんぢこそ懼るべきものなれ 一たび怒りたまふときは誰かみまへに立えんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'なんぢ天より宣告をのりたまへり 地のへりくだる者をみなすくはんとて神のさばきに立たまへるとき地はおそれて默したり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'なんぢ天より宣告をのりたまへり 地のへりくだる者をみなすくはんとて神のさばきに立たまへるとき地はおそれて默したり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, '實に人のいかりは汝をほむべし 怒のあまりは汝おのれの帶としたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'なんぢの神ヱホバにちかひをたてて償へ そのまはりなるすべての者はおそるべきヱホバに禮物をささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'ヱホバはもろもろの諸侯のたましひを絶たまはん ヱホバは地の王たちのおそるべき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'エドトンの體にしたがひて伶長にうたはしめたるアサフのうた 我わがこゑをあげて神によばはん われ聲を神にあげなばその耳をわれにかたぶけたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'わがなやみの日にわれ主をたづねまつれり 夜わが手をのべてゆるむることなかりき わがたましひは慰めらるるをいなみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'われ神をおもひいでて打なやむ われ思ひなげきてわが霊魂おとろへぬ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'なんぢはわが眼をささへて閉がしめたまはず 我はものいふこと能はぬほどに惱みたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'われむかしの日いにしへの年をおもへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'われ夜わが歌をむもひいづ 我わが心にてふかくおもひわが霊魂はねもころに尋ねもとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, '主はとこしへに棄たまふや 再びめぐみを垂たまはざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'その憐憫はのこりなく永遠にさり そのちかひは世々ながく廢れたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, '神は恩をほどこすことを忘れたまふや 怒をもてそのあはれみを絨たまふや セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, '斯るときに我いへらく此はただわが弱きがゆゑのみいで至上者のみぎの手のもろもろの年をおもひいでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'われヤハの作爲をのべとなへん われ往古よりありし汝がくすしきみわざを思ひいたさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'また我なんぢのすべての作爲をおもひいで汝のなしたまへることを深くおもはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, '神よなんぢの途はいときよし 神のごとく大なる神はたれぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'なんぢは奇きみわざをなしたまへる神なり もろもろの民のあひだにその大能をしめし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'その臂をもてヤコブ、ヨセフの子輩なんぢの民をあがなひたまへり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'かみよ大水なんぢを見たり おほみづ汝をみてをののき淵もまたふるへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, '雲はみづをそそぎいだし空はひびきをいだし なんぢの矢ははしりいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'なんぢの雷鳴のこゑは暴風のうちにありき 電光は世をてらし地はふるひうごけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'なんぢの大道は海のなかにあり なんぢの徑はおほみづの中にあり なんぢの蹤跡はたづねがたかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'なんぢその民をモーセとアロンとの手によりて羊の群のごとくみちびきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'アサフの敎訓のうた わが民よわが敎訓をきき、わが口のことばになんぢらの耳をかたぶけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'われ口をひらきて譬喩をまうけ いにしへの玄幽なる語をかたりいでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, '是われらが曩にききしところ知しところ又われらが列祖のかたりつたへし所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'われら之をその子孫にかくさずヱホバのもろもろの頌美と能力とそのなしたまへる奇しき事跡とをきたらんとする世につげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'そはヱホバ證詞をヤコブのうちにたて律法をイスラエルのうちに定めてその子孫にしらすべきことをわれらの列祖におほせたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'これ來らんとする代のちに生るる子孫がこれを知みづから起りてそのまた子孫につたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'かれらをして神によりたのみ神のみわざを忘れずその誡命をまもらしめん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'またその列祖のごとく頑固にしてそむくものの類となり そのこころ修まらず そのたましひ神に忠ならざる類とならざらん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'エフライムのこらは武具ととのへ弓をたづさへしに戰ひの日にうしろをそむけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'かれら神のちかひをまもらず そのおきてを履ことをいなみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'ヱホバのなしたまへることとかれらに示したまへる奇しき事跡とをわすれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, '神はエジプトの國にてゾアンの野にて妙なる事をかれらの列祖のまへになしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'すなはち海をさきてかれらを過ぎしめ水をつみて堆かくしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'ひるは雲をもてかれらをみちびき夜はよもすがら火の光をもてこれを導きたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, '神はあれのにて磐をさき大なる淵より汲がごとくにかれらに飮しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'また磐より流をひきて河のごとくに水をながれしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, '然るにかれら尚たえまなく罪ををかして神にさからひ荒野にて至上者にそむき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'またおのが慾のために食をもとめてその心のうちに神をこころみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, '然のみならずかれらは神にさからひていへり 神は荒野にて筵をまうけたまふを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'みよ神いはを撃たまへば水ほどばしりいで流あぶれたり 糧をもあたへたまふを得んや神はその民のために肉をそなへたまはんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'この故にヱホバこれを聞ていきどほりたまひき 火はヤコブにむかひてもえあがり怒はイスラエルにむかひて立騰れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'こはかれら神を信ぜずその救にたのまざりし故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'されどなほ神はうへなる雲に命じて天の戸をひらき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, '彼等のうへにマナをふらせて食はしめ天の穀物をあたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, '人みな勇士の糧をくらへり 神はかれらに食物をおくりて飽足らしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, '神は天に東風をふかせ大能もて南の風をみちびきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, '神はかれらのうへに塵のごとく肉をふらせ海の沙のごとく翼ある鳥をふらせて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'その營のなかその住所のまはりに落したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, '斯てかれらは食ひて飽たりぬ 神はこれにその欲みしものを與へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'かれらが未だその慾をはなれず食物のなほ口のうちにあるほどに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, '神のいかり旣にかれらに對ひてたちのぼり彼等のうちにて最もこえたる者をころしイスラエルのわかき男をうちたふしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'これらの事ありしかど彼等はなほ罪ををかしてその奇しきみわざを信ぜざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, '神はかれらの日を空しくすぐさせ その年をおそれつつ過させたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, '神かれらを殺したまへる時かれら神をたづね歸りきたりて懇ろに神をもとめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'かくて神はおのれの磐いとたかき神はおのれの贖主なることをおもひいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, '然はあれど彼等はただその口をもて神にへつらひその舌をもて神にいつはりをいひたりしのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'そはかれらのこころは神にむかひて堅からず その契約をまもるに忠信ならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'されど神はあはれみに充たまへばかれらの不義をゆるして亡したまはず屡ばそのみいかりを轉してことごとくは忿恚をふりおこし給はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, '又かれがただ肉にして過去ばふたたび歸りこぬ風なるをおもひいで給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'かれらは野にて神にそむき荒野にて神をうれへしめしこと幾次ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'かれらかへすがへす神をこころみイスラエルの聖者をはづかしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'かれらは神の手をも敵より贖ひたまひし日をもおもひいでざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, '神はそのもろもろの豫兆をエジプトにあらはしその奇しき事をゾアンの野にあらはし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'かれらの河を血にかはらせてその流を飮あたはざらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'また蝿の群をおくりてかれらをくはしめ蛙をおくりてかれらを亡させたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, '神はかれらの田產を蟊賊にわたし かれらの勤勞を蝗にあたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, '神は雹をもてかれらの葡萄の樹をからし霜をもてかれらの桑の樹をからし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'その家畜をへうにわたしその群をもゆる閃電にわたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'かれらの上にはげしき怒といきどほりと怨恨となやみと禍害のつかひの群とをなげいだし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, '神はその怒をもらす道をまうけ かれらのたましひを死よりまぬかれしめず そのいのちを疫癘にわたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'エジプトにてすべての初子をうちハムの幕屋にてかれらの力の始をうちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'されどおのれの民を羊のごとくに引いだし かれらを曠野にてけだものの群のごとくにみちびき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'かれらをともなひておそれなく安けからしめ給へり されど海はかれらの仇をおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, '神はその聖所のさかひ その右の手にて購たまへるこの山に彼らを携へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, '又かれらの前にてもろもろの國人をおもひいだし準縄をもちゐ その地をわかちて嗣業となし イスラエルの族をかれらの幕屋にすまはせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, '然はあれど彼等はいとたかき神をこころみ之にそむきてそのもろもろの證詞をまもらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, '叛きしりぞきてその列祖の如く眞實をうしなひ くるへる弓のごとくひるがへりて逸ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, '高處をまうけて神のいきどほりをひき刻める像にて神の嫉妬をおこしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, '神ききたまひて甚だしくいかり大にイスラエルを憎みたまひしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, '人々の間におきたまひし幕屋なるシロのあげばりを棄さり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'その力をとりことならしめ その榮光を敵の手にわたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'その民を劍にあたへ その嗣業にむかひて甚だしく怒りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, '火はかれらのわかき男をやきつくし かれらの處女はその婚姻の歌によりて譽らるることなく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'かれらの祭司はつるぎにて仆れ かれらの寡婦は喪のなげきだにせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, '斯るときに主はねぶりし者のさめしごとく勇士の酒によりてさけぶがごとく目さめたまひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'その敵をうちしりぞけ とこしへの辱をかれらに負せたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'またヨセフの幕屋をいなみエフライムの族をえらばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'ユダの族そのいつくしみたまふシオンの山をえらびたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'その聖所を山のごとく永遠にさだめたまへる地のごとくに立たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'またその僕ダビデをえらびて羊の牢のなかよりとり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, '乳をあたふる牝羊にしたがひゆく勤のうちより携へきたりてその民ヤコブその嗣業イスラエルを牧はせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, '斯てダビデはそのこころの完全にしたがひてかれらを牧ひ その手のたくみをもて之をみちびけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'アサフのうた ああ神よもろもろの異邦人はなんぢの嗣業の地ををかし なんぢの聖宮をけがしヱルサレムをこぼちて礫堆となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'なんぢの僕のしかばねをそらの鳥に與へて餌となし なんぢの聖徒の肉を地のけものにあたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'その血をヱルサレムのめぐりに水のごとく流したりされど之をはうむる人なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'われらは隣人にそしられ四周のひとびとに侮られ嘲けらるるものとなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'ヱホバよ斯て幾何時をへたまふや 汝とこしへに怒たまふや なんぢのねたみは火のごとく燃るか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, '願くはなんぢを識ざることくにびと聖名をよばざるもろもろの國のうへに烈怒をそそぎたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'かれらはヤコブを呑その住處をあらしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'われらにむかひて先祖のよこしまなるわざを記念したまふなかれ願くはなんぢの憐憫をもて速かにわれらを迎へたまへ われらは貶されて甚だしく卑くなりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'われらのすくひの神よ名のえいくわうのために我儕をたすけ名のためにわれらを救ひ われらの罪をのぞきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'いかなれば異邦人はいふ かれらの神はいづくにありやと 願くはなんぢの僕等がながされし血の報をわれらの目前になして異邦人にしらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'ねがはくは汝のみまへにとらはれびとの嘆息のとどかんことを なんぢの大なる能力により死にさだめられし者をまもりて存へしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, '主よわれらの隣人のなんぢをそしりたる謗を七倍ましてその懐にむくいかへしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, '然ばわれらなんぢの民なんぢの草苑のひつじは永遠になんぢに感謝しその頌辭を世々あらはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, '證詞の百合花といへる調にあはせて伶長にうたはしめたるアサフの歌 イスラエルの牧者よひつじの群のごとくヨセフを導きたまものよ 耳をかたぶけたまへ ケルビムのうへに坐したまふものよ 光をはなちたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'エフライム、ベニヤミン、マナセの前になんぢの力をふりおこし來りてわれらを救ひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, '神よふたたびわれらを復し なんぢの聖顔のひかりをてらしたまへ 然ばわれら救をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'ばんぐんの神ヱホバよなんぢその民の祈にむかひて何のときまで怒りたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, '汝かれらになみだの糧をくらはせ涙を量器にみちみつるほどあたへて飮しめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, '汝われらを隣人のあひあらそふ種料となしたまふ われらの仇はたがひにあざわらへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, '萬軍の神よふたたびわれらを復したまへ 汝のみかほの光をてらしたまへ さらばわれら救をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'なんぢ葡萄の樹をエジプトより携へいだしもろもろの國人をおひしりぞけて之をうゑたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, '汝そのまへに地をまうけたまひしかば深く根して國にはびこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'その影はもろもろの山をおほひ そのえだは神の香柏のごとくにてありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'その樹はえだを海にまでのべ その若枝を河にまでのべたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, '汝いかなればその垣をくづして路ゆくすべての人に嫡取らせたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'はやしの猪はこれをあらし野のあらき獣はこれをくらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'ああ萬軍の神よねがはくは歸りたまへ 天より俯視てこの葡萄の樹をかへりみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'なんぢが右の手にてうゑたまへるもの自己のために強くなしたまへる枝をまもりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'その樹は火にて燒れまた斫たふさる かれらは聖顔のいかりにて亡ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'ねがはくはなんぢの手をその右の手の人のうへにおき自己のためにつよくなしたまへる人の子のうへにおきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'さらばわれら汝をしりぞき離るることなからん 願くはわれらを活したまへ われら名をよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'ああ萬軍の神ヱホバよふたたび我儕をかへしたまへ なんぢの聖顔のひかりを照したまへ 然ばわれら救をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'ギテトの琴にあはせて伶長にうたはしめたるアサフのうた われらの力なる神にむかひて高らかにうたひヤコブの神にむかひてよろこびの聲をあげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, '歌をうたひ鼓とよき音のことと筝とをもちきたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, '新月と滿月とわれらの節會の日とにラッパをふきならせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'これイスラエルの律法ヤコブのかみの格なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, '神さきにエジプトを攻たまひしときヨセフのなかに之をたてて證となしたまへり 我かしこにて未だしらざりし方言をきけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'われかれの肩より重荷をのぞき かれの手を籃よりまぬかれしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '汝なやめるとき呼しかば我なんぢをすくへり われ雷鳴のかくれたるところにて汝にこたへメリバの水のほとりにて汝をこころみたり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'わが民よきけ我なんぢに證せん イスラエルよ汝がわれに從はんことをもとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, '汝のうちに他神あるべからず なんぢ他神ををがむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'われはエジプトの國よりなんぢを携へいでたる汝の神ヱホバなり なんぢの口をひろくあけよ われ物をみたしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'されどわが民はわか聲にしたがはず イスラエルは我をこのまず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'このゆゑに我かれらが心のかたくななるにまかせ彼等がその任意にゆくにまかせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'われはわが民のわれに從ひイスフルのわが道にあゆまんことを求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'さらば我すみやかにかれらの仇をしたがへ わが手をかれらの敵にむけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, '斯てヱホバをにくみし者もかれらに從ひ かれらの時はとこしへにつづかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, '神はむぎの最嘉をもてかれらをやしなひ 磐よりいでたる蜜をもて汝をあかしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'アサフのうた かみは神のつどひの中にたちたまふ 神はもろもろの神のなかに審判をなしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'なんぢらは正からざる審判をなし あしきものの身をかたよりみて幾何時をへんとするや セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'よわきものと孤兒とのためにさばき苦しむものと乏しきものとのために公平をほどこせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, '弱きものと貧しきものとをすくひ彼等をあしきものの手よりたすけいだせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'かれらは知ることなく悟ることなくして暗中をゆきめぐりぬ 地のもろもろの基はうごきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, '我いへらく なんぢらは神なりなんぢらはみな至上者の子なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, '然どなんぢらは人のごとくに死もろもろの侯のなかの一人のごとく仆れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, '神よおきて全地をさばきたまへ 汝もろもろの國を嗣たまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'アサフの歌なり讃美なり 神よもだしたまふなかれ神よものいはで寂靜たまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, '視よなんぢの仇はかしがきしき聲をあげ汝をにくむものは首をあげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'かれらはたくみなる謀略をもてなんぢの民にむかひ相共にはかりて汝のかくれたる者にむかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'かれらいひたりき 來かれらを斷滅してふたたび國をたつることを得ざらしめイスラエルの名をふたたび人にしられざらしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'かれらは心を一つにしてともにはかり互にちかひをなしてなんぢに逆ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'こはエドムの幕屋にすめる人イシマエル人モアブ、ハガル人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'ゲバル、アンモン、アマレク、ペリシテおよびツロの民などなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'アッスリヤも亦かれらにくみせり 斯てロトの子輩のたすけをなせり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'なんぢ曩にミデアンになしたまへる如くキションの河にてシセラとヤビンとに作たまへるごとく彼等にもなしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'かれらはエンドルにてほろび地のために肥料となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'かれらの貴人をオレブ、ゼエブのごとくそのもろもろの侯をゼバ、ザルムンナのごとくなしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'かれらはいへり われら神の草苑をえてわが有とすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'わが神よかれらをまきあげらるる塵のごとく風のまへの藁のごとくならしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, '林をやく火のごとく山をもやす熖のごとく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'なんぢの暴風をもてかれらを追ひなんぢの旋風をもてかれらを怖れしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'かれらの面に恥をみたしめたまへ ヱホバよ然ばかれらなんぢの名をもとめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'かれらをとこしへに恥おそれしめ惶てまどひて亡びうせしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, '然ばかれらはヱホバてふ名をもちたまふ汝のみ全地をしろしめす至上者なることを知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'ギテトの琴にあはせて伶長にうたはしめたるコラの子のうた 萬軍のヱホバよなんぢの帷幄はいかに愛すべきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'わが霊魂はたえいるばかりにヱホバの大庭をしたひ わが心わが身はいける神にむかひて呼ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, '誠やすずめは窩をえ燕子はその雛をいるる巣をえたり萬軍のヱホバわが王わが神よ これなんぢの祭壇なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'なんぢの家にすむものは福ひなり かかるひとはつねに汝をたたへまつらん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'その力なんぢにあり その心シオンの大路にある者はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'かれらは涙の谷をすぐれども其處をおほくの泉あるところとなす また前の雨はもろもろの惠をもて之をおほへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'かれらは力より力にすすみ遂におのおのシオンにいたりて神にまみゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'ばんぐんの神ヱホバよわが祈をききたまへ ヤコブの神よ耳をかたぶけたまへ セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'われらの盾なる神よ みそなはして なんぢの受膏者の顔をかへりみたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'なんぢの大庭にすまふ一日は千日にもまされり われ惡の幕屋にをらんよりは 寧ろわが神のいへの門守とならんことを欲ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'そは神ヱホバは日なり盾なり ヱホバは恩とえいくわうとをあたへ直くあゆむものに善物をこばみたまふことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, '萬軍のヱホバよなんぢに依賴むものはさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, '伶長にうたはしめたるコラの子のうた ヱホバよなんぢは御國にめぐみをそそぎたまへり なんぢヤコブの俘囚をかへしたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'なんぢおのが民の不義をゆるしそのもろもろの罪をおほひたまひき セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, '汝すべての怒をすてその烈しきいきどほりを遠けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'われらのすくひの神よかへりきたり我儕にむかひて忿怒をやめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'なんぢ永遠にわれらをいかり萬世にみいかりをひきのべたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, '汝によりてなんぢの民の喜悦をえんが爲に我儕を活したまはざるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'ヱホバよなんぢの憐憫をわれらにしめし汝のすくひを我儕にあたへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'わが神ヱホバのいたりたまふ事をきかん ヱホバはその民その聖徒に平和をかたりたまへばなり さればかれらは愚かなる行爲にふたたび歸るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, '實にそのすくひは神をおそるる者にちかし かくて榮光はわれらの國にとどまらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'あはれみと眞實とともにあひ義と平和とたがひに接吻せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'まことは地よりはえ義は天よりみおろせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'ヱホバ善物をあたへたまへばわれらの國は物產をいださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, '義はヱホバのまへにゆきヱホバのあゆみたまふ跡をわれに踏しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'ダビデの祈祷 ヱホバよなんぢ耳をかたぶけて我にこたへたまへ 我はくるしみかつ乏しければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'ねがはくはわが霊魂をまもりたまへ われ神をうやまふ者なればなり わが神よなんぢに依賴める汝のしもべを救ひ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, '主よわれを憐みたまへ われ終日なんぢによばふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'なんぢの僕のたましひを悦ばせたまへ 主よわが霊魂はなんぢを仰ぎのぞむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, '主よなんぢは惠ふかくまた赦をこのみたまふ 汝によばふ凡てのものを豊かにあはれみたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'ヱホバよわがいのりに耳をかたぶけ わが懇求のこゑをききたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'われわが患難の日になんぢに呼はん なんぢは我にこたへたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, '主よもろもろの神のなかに汝にひとしきものはなく汝のみわざに侔しきものはなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, '主よなんぢの造れるもろもろの國はなんぢの前にきたりて伏拝まん かれらは聖名をあがむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'なんぢは大なり奇しき事跡をなしたまふ 唯なんぢのみ神にましませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'ヱホバよなんぢの道をわれに敎へたまへ我なんぢの眞理をあゆまん ねがはくは我をして心ひとつに聖名をおそれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, '主わが神よ我心をつくして汝をほめたたへ とこしへに聖名をあがめまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'そはなんぢの憐憫はわれに大なり わがたましひを陰府のふかき處より助けいだしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, '神よたかぶれるものは我にさからひて起りたち暴ぶる人の會はわがたましひをもとめ 斯てなんぢを己がまへに置ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'されど主よなんぢは憐憫とめぐみとにとみ怒をおそくし愛しみと眞實とにゆたかなる神にましませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, '我をかへりみ我をあはれみたまへ ねがはくは汝のしもべに能力を與へ汝のはしための子をすくひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, '我にめぐみの憑據をあらはしたまへ 然ばわれをにくむ者これをみて恥をいだかん そはヱホバよなんぢ我をたすけ我をなぐさめたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'コラの子のうたなり讃美なり ヱホバの基はきよき山にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'ヱホバはヤコブのすべての住居にまさりてシオンのもろもろの門を愛したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, '神の都よなんぢにつきておほくの榮光のことを語りはやせり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'われはラハブ、バビロンをも我をしるものの中にあげん ペリシテ、ツロ、エテオピアを視よこの人はかしこに生れたりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'シオンにつきては如此いはん 此もの彼ものその中にうまれたり至上者みづからシオンを立たまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'ヱホバもろもろの民をしるしたまふ時このものは彼處にうまれたりと算へあげたまはん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'うたふもの踊るもの皆いはん わがもろもろの泉はなんぢの中にありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'マハラテ、レアノテの調にあはせて伶長にうたはしめたるコラの子のうたなり 讃美なり、エズフ人ヘマンのをしへの歌なり わがすくひの神ヱホバよわれ晝も夜もなんぢの前にさけべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, '願くはわが祈をみまへにいたらせ汝のみみをわが號呼のこゑにかたぶけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'わがたましひは患難にてみち我がいのちは陰府にちかづけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'われは穴にいるものとともにかぞへられ依仗なき人のごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'われ墓のうちなる殺されしもののごとく死者のうちにすてらる汝かれらを再びこころに記たまはず かれらは御手より斷滅されしものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'なんぢ我をいとふかき穴 くらき處 ふかき淵におきたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'なんぢの怒はいたくわれにせまれり なんぢそのもろもろの浪をもて我をくるしめ給へり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'わが相識ものを我よりとほざけ我をかれらに憎ませたまへり われは錮閉されていづることあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'わが眼はなやみの故をもておとろへぬ われ日ごとに汝をよべり ヱホバよなんぢに向ひてわが兩手をのべたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'なんぢ死者にくすしき事跡をあらはしたまはんや 亡にしもの立てなんぢを讃たたへんや セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, '汝のいつくしみは墓のうちに汝のまことは滅亡のなかに宣傳へられんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, '汝のくすしきみわざは幽暗になんぢの義は忘失のくにに知るることあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'されどヱホバよ我なんぢに向ひてさけべり わがいのりは朝にみまへに達らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'ヱホバよなんぢ何なればわが霊魂をすてたまふや何なればわれに面をかくしたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'われ幼稚よりなやみて死るばかりなり我なんぢの恐嚇にあひてくるしみまどへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, '汝のはげしき怒わがうへをすぐ汝のおびやかし我をほろぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'これらの事ひねもす大水のごとく我をめぐり ことごとく來りて我をかこみふさげり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'なんぢ我をいつくしむ者とわが友とをとほざけ わが相識るものを幽暗にいれたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'エズラ人エタンのをしへの歌 われヱホバの憐憫をとこしへにうたはん われ口もてヱホバの眞實をよろづ代につげしらせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'われいふ あはれみは永遠にたてらる 汝はその眞實をかたく天にさだめたまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'われわが撰びたるものと契約をむすびわが僕ダビデにちかひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'われなんぢの裔をとこしへに固うしなんぢの座位をたてて代々におよばしめん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'ヱホバよもろもろの天はなんぢの奇しき事跡をほめん なんぢの眞實もまた潔きものの會にてほめらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, '蒼天にてたれかヱホバに類ふものあらんや 神の子のなかに誰かヱホバのごとき者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, '神はきよきものの公會のなかにて畏むべきものなり その四周にあるすべての者にまさりて懼るべきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, '萬軍の神ヱホバよヤハよ汝のごとく大能あるものは誰ぞや なんぢの眞實はなんぢをめぐりたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'なんぢ海のあるるををさめ その浪のたちあがらんときは之をしづめたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'なんぢラハブを殺されしもののごとく撃碎きおのれの仇どもを力ある腕をもて打散したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'もろもろの天はなんぢのもの地もまた汝のものなり世界とその中にみつるものとはなんぢの基したまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, '北と南はなんぢ造りたまへり タボル、ヘルモンはなんぢの名によりて歓びよばふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'なんぢは大能のみうでをもちたまふ なんぢの手はつよく汝のみぎの手はたかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, '義と公平はなんぢの寳座のもとゐなり あはれみと眞實とは聖顔のまへにあらはれゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'よろこびの音をしる民はさいはひなり ヱホバよかれらはみかほの光のなかをあゆめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'かれらは名によりて終日よろこび 汝の義によりて高くあげられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'かれらの力の榮光はなんぢなり 汝の惠によりてわれらの角はたかくあげられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'そはわれらの盾はヱホバに屬われらの王はイスラエルの聖者につけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'そのとき異象をもてなんぢの聖徒につげたまはく われ佑助をちからあるものに委ねたり わが民のなかより一人をえらびて高くあげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'われわが僕ダビデをえて之にわが聖膏をそそげり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'わが手はかれとともに堅くわが臂はかれを強くせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, '仇かれをしへたぐることなし惡の子かれを苦しむることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'われかれの前にそのもろもろの敵をたふし彼をにくめるものを撃ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'されどわが眞實とわが憐憫とはダビデとともに居り わが名によりてその角はたかくあげられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'われ亦かれの手を海のうへにおき そのみぎの手を河のうへにおかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'ダビデ我にむかひて汝はわが父わが神わがすくひの岩なりとよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'われまた彼をわが初子となし地の王たちのうち最もたかき者となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'われとこしへに憐憫をかれがためにたもち 之とたてし契約はかはることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'われまたその裔をとこしへに存へ そのくらゐを天の日數のごとくながらへしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'もしその子わが法をはなれ わが審判にしたがひて歩まず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'わが律法をやぶりわが誡命をまもらずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'われ杖をもてかれらの愆をただし鞭をもてその邪曲をただすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'されど彼よりわが憐憫をことごとくはとりさらず わが眞實をおとろへしむることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'われおのれの契約をやぶらず己のくちびるより出しことをかへじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'われ曩にわが聖をさして誓へり われダビデに虚偽をいはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'その裔はとこしへにつづきその座位は日のごとく恒にわが前にあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'また月のごとく永遠にたてられん空にある證人はまことなり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'されどその受膏者をとほざけて棄たまへり なんぢ之をいきどほりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'なんぢ己がしもべの契約をいみ 其かんむりをけがして地にまでおとし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'またその垣をことごとく倒し その保砦をあれすたれしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'その道をすぐるすべての者にかすめられ隣人にののしらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'なんぢかれが敵のみぎの手をたかく擧そのもろもろの仇をよろこばしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'なんぢかれの劍の刃をふりかへして戰闘にたつに堪へざらしめたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'またその光輝をけしその座位を地になげおとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'その年若き日をちぢめ恥をそのうへに覆たまへり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'ヱホバよかくて幾何時をへたまふや自己をとこしへに隠したまふや忿怒は火のもゆるごとくなるべきか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'ねがはくはわが時のいかに短かきかを思ひたまへ 汝いたづらにすべての人の子をつくりたまはんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, '誰かいきて死をみず又おのがたましひを陰府より救ひうるものあらんや セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, '主よなんぢが眞實をもてダビデに誓ひたまへる昔日のあはれみはいづこにありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, '主よねがはくはなんぢの僕のうくる謗をみこころにとめたまへ ヱホバよ汝のもろもろの仇はわれをそしりなんぢの受膏者のあしあとをそしれり 我もろもろの民のそしりをわが懐中にいだく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, '主よねがはくはなんぢの僕のうくる謗をみこころにとめたまへ ヱホバよ汝のもろもろの仇はわれをそしりなんぢの受膏者のあしあとをそしれり 我もろもろの民のそしりをわが懐中にいだく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'ヱホバは永遠にほむべきかな アーメン アーメン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, '神の人モーセの祈祷 主よなんぢは往古より世々われらの居所にてましませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, '山いまだ生いでず汝いまだ地と世界とをつくりたまはざりしとき 永遠よりとこしへまでなんぢは神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'なんぢ人を塵にかへらしめて宣はく 人の子よなんぢら歸れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'なんぢの目前には千年もすでにすぐる昨日のごとく また夜間のひとときにおなじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'なんぢこれらを大水のごとく流去らしめたまふ かれらは一夜の寝のごとく朝にはえいづる靑草のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, '朝にはえいでてさかえ夕にはかられて枯るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'われらはなんぢの怒によりて消うせ 汝のいきどほりによりて怖まどふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, '汝われらの不義をみまへに置 われらの隠れたるつみを聖顔のひかりのなかにおきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'われらのもろもろの日はなんぢの怒によりて過去り われらがすべての年のつくるは一息のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'われらが年をふる日は七十歳にすぎず あるひは壯やかにして八十歳にいたらん されどその誇るところはただ勤勞とかなしみとのみ その去ゆくこと速かにしてわれらもまた飛去れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, '誰かなんぢの怒のちからを知らんや たれか汝をおそるる畏にたくらべて汝のいきどほりをしらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, '願くはわれらにおのが日をかぞふることををしへて智慧のこころを得しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'ヱホバよ歸りたまへ斯ていくそのときを歴たまふや ねがはくは汝のしもべらに係れるみこころを變へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'ねがはくは朝にわれらを汝のあはれみにてあきたらしめ 世をはるまで喜びたのしませたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, '汝がわれらを苦しめたまへるもろもろの日と われらが禍害にかかれるもろもろの年とにたくらべて我儕をたのしませたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'なんぢの作爲をなんぢの僕等に なんぢの榮光をその子等にあらはしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, '斯てわれらの神ヱホバの佳美をわれらのうへにのぞましめ われらの手のわざをわれらのうへに確からしめたまへ 願くはわれらの手のわざを確からしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, '至上者のもとなる隠れたるところにすまふその人は全能者の蔭にやどらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'われヱホバのことを宣て ヱホバはわが避所わが城わがよりたのむ神なりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'そは神なんぢを狩人のわなと毒をながす疫癘よりたすけいだしたまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'かれその翮をもてなんぢを庇ひたまはん なんぢその翼の下にかくれん その眞實は盾なり干なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, '夜はおどろくべきことあり晝はとびきたる矢あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, '幽暗にはあゆむ疫癘あり日午にはそこなふ勵しき疾あり されどなんぢ畏るることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, '千人はなんぢの左にたふれ萬人はなんぢの右にたふる されどその災害はなんぢに近づくことなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'なんぢの眼はただこの事をみるのみ なんぢ惡者のむくいを見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'なんぢ曩にいへりヱホバはわが避所なりと なんぢ至上者をその住居となしたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, '災害なんぢにいたらず苦難なんぢの幕屋に近づかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'そは至上者なんぢのためにその使者輩におほせて 汝があゆむもろもろの道になんぢを守らせ給へばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, '彼ら手にてなんぢの足の石にふれざらんために汝をささへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'なんぢは獅と蝮とをふみ壯獅と蛇とを足の下にふみにじらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '彼その愛をわれにそそげるがゆゑに我これを助けん かれわが名をしるがゆゑに我これを高處におかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'かれ我をよはば我こたへん 我その苦難のときに偕にをりて之をたすけ之をあがめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'われ長寿をもてかれを足はしめ且わが救をしめさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, '安息日にもちゐる歌なり 讃美なり いとたかき者よヱホバにかんしやし聖名をほめたたふるは善かな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'あしたに汝のいつくしみをあらはし 夜々なんぢの眞實をあらはすに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, '十絃のなりものと筝とをもちゐ 琴の妙なる音をもちゐるはいと善かな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'そはヱホバよ なんぢその作爲をもて我をたのしませたまへり 我なんぢの手のわざをよろこびほこらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'ヱホバよ汝のみわざは大なるかな汝のもろもろの思念はいとふかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, '無知者はしることなく愚なるものは之をさとらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, '惡きものは草のごとくもえいで 不義をおこなふ衆庶はさかゆるとも 遂にはとこしへにほろびん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'されどヱホバよ汝はとこしへに高處にましませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'ヱホバよ吁なんぢの仇ああなんぢの仇はほろびん 不義をおこなふ者はことごとく散されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'されど汝わが角をたかくあげて 野の牛のつののごとくならしめたまへり 我はあたらしき膏をそそがれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, '又わが目はわが仇につきて願へることを見わが耳はわれにさからひておこりたつ惡をなすものにつきて願へることをききたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, '義しきものは棕櫚の樹のごとく榮え レバノンの香柏のごとくそだつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'ヱホバの宮にうゑられしものはわれらの神の大庭にさかえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'かれらは年老てなほ果をむすび豊かにうるほひ緑の色みちみちて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'ヱホバの直きものなることを示すべし ヱホバはわが巌なりヱホバには不義なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'ヱホバは統治たまふ ヱホバは稜威をきたまへり ヱホバは能力をころもとなし帶となしたまへり さればまた世界もかたくたちて動かさるることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'なんぢの寳座はいにしへより堅くたちぬ 汝はとこしへより在せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, '大水はこゑをあげたり ヱホバよおほみづは聲をあげたり おほみづは浪をあぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'ヱホバは高處にいましてその威力はおほくの水のこゑ海のさかまくにまさりて盛んなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'なんぢの證詞はいとかたし ヱホバよ聖潔はなんぢの家にとこしへまでも適應なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'ヱホバよ仇をかへすは汝にあり神よあたを報すはなんぢにあり ねがはくは光をはなちたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, '世をさばきたまふものよ 願くは起てたかぶる者にそのうくべき報をなしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'ヱホバよ惡きもの幾何のときを經んとするや あしきもの勝誇りていくそのとしを經るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'かれらはみだりに言をいだして誇りものいふ すべて不義をおこなふ者はみづから高ぶれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'ヱホバよ彼等はなんぢの民をうちくだき なんぢの業をそこなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'かれらは嫠婦と旅人との生命をうしなひ孤子をころす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'かれらはいふ ヤハは見ずヤコブの神はさとらざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, '民のなかなる無知よ なんぢらさとれ 愚かなる者よ いづれのときにか智からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'みみを植るものきくことをせざらんや 目をつくれるもの見ることをせざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'もろもろの國ををしふる者ただすことを爲ざらんや 人に知識をあたふる者しることなからんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'ヱホバは人の思念のむなしきを知りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'ヤハよなんぢの懲めたまふ人なんぢの法ををしへらるる人は さいはひなるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'かかる人をわざはひの日よりのがれしめ 惡きもののために坑のほらるるまで これに平安をあたへたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'そはヱホバその民をすてたまはず その嗣業をはなれたまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, '審判はただしきにかへり心のなほき者はみなその後にしたがはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, '誰かわがために起りたちて惡きものを責んや 誰か我がために立て不義をおこなふ者をせめんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'もしヱホバ我をたすけたまはざりせば わが霊魂はとくに幽寂ところに住ひしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'されどわが足すべりぬといひしとき ヱホバよなんぢの憐憫われをささへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'わがうちに憂慮のみつる時 なんぢの安慰わがたましひを喜ばせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, '律法をもて害ふことをはかる惡の位はなんぢに親むことを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, '彼等はあひかたらひて義人のたましひをせめ罪なき血をつみに定む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, '然はあれどヱホバはわがたかき櫓 わが神はわが避所の磐なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, '神はかれらの邪曲をその身におはしめ かれらをその惡き事のなかに滅したまはん われらの神ヱホバはこれを滅したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, '率われらヱホバにむかひてうたひ すくひの磐にむかひてよろこばしき聲をあげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'われら感謝をもてその前にゆき ヱホバにむかひ歌をもて歓ばしきこゑをあげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'そはヱホバは大なる神なり もろもろの神にまされる大なる王なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, '地のふかき處みなその手にあり 山のいただきもまた神のものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'うみは神のものその造りたまふところ旱ける地もまたその手にて造りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'いざわれら拝みひれふし我儕をつくれる主ヱホバのみまへに曲跪くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, '彼はわれらの神なり われらはその草苑の民その手のひつじなり 今日なんぢらがその聲をきかんことをのぞむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'なんぢらメリバに在りしときのごとく 野なるマサにありし日の如く その心をかたくなにするなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'その時なんぢらの列祖われをこころみ我をためし 又わがわざをみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'われその代のためにうれへて四十年を歴 われいへり かれらは心あやまれる民わが道を知ざりきと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'このゆゑに我いきどほりて彼等はわが安息にいるべからずと誓ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'あたらしき歌をヱホバにむかひてうたへ 全地よヱホバにむかひて謳ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'ヱホバに向ひてうたひその名をほめよ 日ごとにその救をのべつたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'もろもろの國のなかにその榮光をあらはし もろもろの民のなかにその奇しきみわざを顯すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'そはヱホバはおほいなり大にほめたたふべきものなり もろもろの神にまさりて畏るべきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'もろもろの民のすべての神はことごとく虚し されどヱホバはもろもろの天をつくりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, '尊貴と稜威とはその前にあり能と善美とはその聖所にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'もろもろの民のやからよ榮光とちからとをヱホバにあたへよヱホバにあたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'その聖名にかなふ榮光をもてヱホバにあたへ 献物をたづさへてその大庭にきたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'きよき美しきものをもてヱホバををがめ 全地よその前にをののけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'もろもろの國のなかにいへ ヱホバは統治たまふ世界もかたくたちて動かさるることなし ヱホバは正直をもてすべての民をさばきたまはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, '天はよろこび地はたのしみ海とそのなかに盈るものとはなりどよみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, '田畑とその中のすべての物とはよろこぶべし かくて林のもろもろの樹もまたヱホバの前によろこびうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'ヱホバ來りたまふ地をさばかんとて來りたまふ 義をもて世界をさばきその眞實をもてもろもろの民をさばきたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'ヱホバは統治たまふ 全地はたのしみ多くの島々はよろこぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, '雲とくらきとはそり周環にあり 義と公平とはその寳座のもとゐなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, '火ありそのみまへにすすみ その四周の敵をやきつくす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'ヱホバのいなびかりは世界をてらす 地これを見てふるへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'もろもろの山はヱホバのみまへ全地の主のみまへにて蝋のごとくとけぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'もろもろの天はその義をあらはし よろづの民はその榮光をみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'すべてきざめる像につかへ虚しきものによりてみづから誇るものは恥辱をうくべし もろもろの神よみなヱホバをふしをがめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'ヱホバよなんぢの審判のゆゑによりシオンはききてよろこびユダの女輩はみな樂しめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'ヱホバよなんぢ全地のうへにましまして至高く なんぢもろもろの神のうへにましまして至貴とし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'ヱホバを愛しむものよ惡をにくめ ヱホバはその聖徒のたましひをまもり 之をあしきものの手より助けいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, '光はただしき人のためにまかれ 欣喜はこころ直きもののために播れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, '義人よヱホバにより喜べ そのきよき名に感謝せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, '歌なり あたらしき歌をヱホバにむかひてうたへ そは妙なる事をおこなひその右の手そのきよき臂をもて 己のために救をなし畢たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'ヱホバはそのすくひを知しめ その義をもろもろの國人の目のまへにあらはし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, '又その憐憫と眞實とをイスラエルの家にむかひて記念したまふ 地の極もことごとくわが神のすくひを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, '全地よヱホバにむかひて歓ばしき聲をあげよ 聲をはなちてよろこびうたへ讃うたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, '琴をもてヱホバをほめうたへ 琴の音と歌のこゑとをもてせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'ラッパと角笛をふきならし 王ヱホバのみまへによろこばしき聲をあげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, '海とそのなかに盈るもの 世界とせかいにすむものと鳴響むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, '大水はその手をうち もろもろの山はあひともにヱホバの前によろこびうたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'ヱホバ地をさばかんために來りたまへばなり ヱホバ義をもて世界をさばき 公平をもてもろもろの民をさばきたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'ヱホバは統治たまふ もろもろの民はをののくべし ヱホバはケルビムの間にいます 地ふるはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'ヱホバはシオンにましまして大なり もろもろの民にすぐれてたふとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'かれらは汝のおほいなる畏るべき名をほめたたふべし ヱホバは聖なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, '王のちからは審判をこのみたまふ 汝はかたく公平をたてヤコブのなかに審判と公義とをおこなひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'われらの神ヱホバをあがめ その承足のもとにて拝みまつれ ヱホバは聖なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'その祭司のなかにモーセとアロンとあり その名をよぶ者のなかにサムエルあり かれらヱホバをよびしに應へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'ヱホバ雲の柱のうちにましましてかれらに語りたまへり かれらはその證詞とその賜はりたる律法とを守りたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'われらの神ヱホバよなんぢ彼等にこたへたまへり かれらのなしし事にむくいたまひたれど また赦免をあたへたまへる神にてましませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'われらの神ヱホバを崇めそのきよき山にてをがみまつれ そはわれらの神ヱホバは聖なるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, '感謝のうた 全地よヱホバにむかひて歡ばしき聲をあげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, '欣喜をいだきてヱホバに事へ うたひつつその前にきたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, '知れヱホバこそ神にますなれ われらを造りたまへるものはヱホバにましませば我儕はその屬なり われらはその民その草苑のひつじなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, '感謝しつつその門にいり ほめたたへつつその大庭にいれ 感謝してその名をほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'ヱホバはめぐみふかくその憐憫かぎりなく その眞實よろづ世におよぶべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'ダビデのうた われ憐憫と審判とをうたはん ヱホバよ我なんぢを讃うたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'われ心をさとくして全き道をまもらん なんぢいづれの時われにきたりたまふや 我なほき心をもてわが家のうちをありかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'われわが眼前にいやしき事をおかず われ叛くものの業をにくむ そのわざは我につかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, '僻めるこころは我よりはなれん 惡きものを知ることをこのまず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, '隠にその友をそしるものは我これをほろぼさん 高ぶる眼また驕れる心のものは我これをしのばじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'わが眼は國のうちの忠なる者をみて之をわれとともに住はせん 全き道をあゆむ人はわれに事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, '欺くことをなす者はわが家のうちに住むことをえず 虚偽をいふものはわが目前にたつことを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'われ朝な朝なこの國のあしき者をことごとく滅し ヱホバの邑より不義をおこなふ者をことごとく絶除かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'なやみたる者おもひくづほれてその歎息をヱホバの前にそそぎいだせるときの祈祷 ヱホバよわが祈をききたまへ 願くはわが號呼のこゑの御前にいたらんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'わが窮苦の日みかほを蔽ひたまふなかれ なんぢの耳をわれにかたぶけ 我がよぶ日にすみやかに我にこたへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'わがもろもろの日は煙のごとくきえ わが骨はたきぎのごとく焚るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'わがこころは草のごとく撃れてしほれたり われ糧をくらふを忘れしによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'わが歎息のこゑによりてわが骨はわが肉につく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'われは野の鸅鸕のごとく荒たる跡のふくろふのごとくになりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'われ醒てねぶらず ただ友なくして屋蓋にをる雀のごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'わが仇はひねもす我をそしる 猖狂ひて我をせむるもの我をさして誓ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'われは糧をくらふごとくに灰をくらひ わが飮ものには涙をまじへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'こは皆なんぢの怒と忿恚とによりてなり なんぢ我をもたげてなげすて給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'わが齡はかたぶける日影のごとし またわれは草のごとく萎れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'されどヱホバよなんぢは永遠にながらへ その名はよろづ世にながらへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'なんぢ起てシオンをあはれみたまはん そはシオンに恩惠をほどこしたまふときなり そのさだまれる期すでに來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'なんぢの僕はシオンの石をもよろこび その塵をさへ愛しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'もろもろの國はヱホバの名をおそれ 地のもろもろの王はその榮光をおそれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'ヱホバはシオンをきづき榮光をもてあらはれたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'ヱホバは乏しきものの祈をかへりみ彼等のいのりを藐しめたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, '來らんとするのちの世のためにこの事をしるさん 新しくつくられたる民はヤハをほめたたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'ヱホバその聖所のたかき所よりみおろし天より地をみたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'こは俘囚のなげきをきき死にさだまれる者をときはなち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, '人々のシオンにてヱホバの名をあらはしヱルサレムにてその頌美をあらはさんが爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'かかる時にもろもろの民もろもろの國つどひあつまりてヱホバに事へまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'ヱホバはわがちからを途にておとろへしめ わが齢をみじかからしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, '我いへりねがはくはわが神よわがすべての日のなかばにて我をとりさりたまふなかれ 汝のよはひは世々かぎりなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, '汝いにしへ地の基をすゑたまへり 天もまたなんぢの手の工なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'これらは亡びん されど汝はつねに存らへたまはん これらはみな衣のごとくふるびん 汝これらを袍のごとく更たまはん されば彼等はかはらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, '然れども汝はかはることなし なんぢの齢はをはらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, '汝のしもべの子輩はながらへん その裔はかたく前にたてらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'ダビデのうた わが霊魂よヱホバをほめまつれ わが衷なるすべてのものよそのきよき名をほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'わがたましひよヱホバを讃まつれ そのすべての恩惠をわするるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'ヱホバはなんぢがすべての不義をゆるし汝のすべての疾をいやし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'なんぢの生命をほろびより贖ひいだし 仁慈と憐憫とを汝にかうぶらせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'なんぢの口を嘉物にてあかしめたまふ 斯てなんぢは壯ぎて鷲のごとく新になるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'ヱホバはすべて虐げらるる者のために公義と審判とをおこなひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'おのれの途をモーセにしらしめ おのれの作爲をイスラエルの子輩にしらしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'ヱホバはあはれみと恩惠にみちて怒りたまふことおそく仁慈ゆたかにましませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, '恒にせむることをせず永遠にいかりを懐きたまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'ヱホバはわれらの罪の量にしたがひて我儕をあしらひたまはず われらの不義のかさにしたがひて報いたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'ヱホバをおそるるものにヱホバの賜ふそのあはれみは大にして 天の地よりも高きがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'そのわれらより愆をとほざけたまふことは東の西より遠きがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'ヱホバの己をおそるる者をあはれみたまふことは父がその子をあはれむが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'ヱホバは我儕のつくられし状をしり われらの塵なることを念ひ給へばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, '人のよはひは草のごとく その榮はのの花のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, '風すぐれば失てあとなくその生いでし處にとへど尚しらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, '然はあれどヱホバの憐憫はとこしへより永遠まで ヱホバをおそるるものにいたり その公義は子孫のまた子孫にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'その契約をまもりその訓諭を心にとめて行ふものぞその人なる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'ヱホバはその寳座をもろもろの天にかたく置たまへり その政權はよろづのもののうへにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'ヱホバにつかふる使者よ ヱホバの聖言のこゑをきき その聖言をおこなふ勇士よ ヱホバをほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'その萬軍よ その聖旨をおこなふ僕等よ ヱホバをほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'その造りたまへる萬物よ ヱホバの政權の下なるすべての處にてヱホバをほめよ わがたましひよヱホバを讃まつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'わが霊魂よヱホパをほめまつれ わが神ヱホバよなんぢは至大にして尊貴と稜威とを衣たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'なんぢ光をころものごとくにまとひ天を幕のごとくにはり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, '水のなかにおのれの殿の棟梁をおき 雲をおのれの車となし 風の翼にのりあるき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'かぜを使者となし熖のいづる火を僕となしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'ヱホバは地を基のうへにおきて 永遠にうごくことなからしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, '衣にておほふがごとく大水にて地をおほひたまへり 水たたへて山のうへをこゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'なんぢ叱咤すれば水しりぞき 汝いかづちの聲をはなてば水たちまち去ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'あるひは山にのぼり或ひは谷にくだりて 汝のさだめたまへる所にゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'なんぢ界をたてて之をこえしめず ふたたび地をおほふことなからしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'ヱホバはいづみを谷にわきいだし給ふ その流は山のあひだにはしる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'かくて野のもろもろの獣にのましむ 野の驢馬もその渇をやむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, '空の鳥もそのほとりにすみ 樹梢の間よりさえづりうたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'ヱホバはその殿よりもろもろの山に灌漑たまふ 地はなんぢのみわざの實によりて飽足ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'ヱホバは草をはえしめて家畜にあたへ 田產をはえしめて人の使用にそなへたまふ かく地より食物をいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, '人のこころを歓ばしむる葡萄酒 ひとの顔をつややかならしむるあぶら 人のこころを強からしむる糧どもなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'ヱホバの樹とその植たまへるレバノンの香柏とは飽足ぬべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, '鳥はそのなかに巣をつくり鶴は松をその棲とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'たかき山は山羊のすまひ磐石は山鼠のかくるる所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'ヱホバは月をつくりて時をつかさどらせたまへり 日はその西にいることをしる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'なんぢ黑暗をつくりたまへば夜あり そのとき林のけものは皆しのびしのびに出きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'わかき獅ほえて餌をもとめ神にくひものをもとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, '日いづれば退きてその穴にふす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, '人はいでて工をとりその勤勞はゆふべにまでいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'ヱホバよなんぢの事跡はいかに多なる これらは皆なんぢの智慧にてつくりたまへり 汝のもろもろの富は地にみつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'かしこに大なるひろき海あり そのなかに數しられぬ匍ふもの小なる大なる生るものあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, '舟そのうへをはしり汝のつくりたまへる鰐そのうちにあそびたはぶる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, '彼ら皆なんぢを俟望む なんぢ宜時にくひものを之にあたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, '彼等はなんぢの予へたまふ物をひろふ なんぢ手をひらきたまへばかれら嘉物にあきたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'なんぢ面をおほひたまへば彼等はあわてふためく 汝かれらの氣息をとりたまへばかれらは死て塵にかへる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'なんぢ霊をいだしたまへば百物みな造らるなんぢ地のおもてを新にしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, '願くはヱホバの榮光とこしへにあらんことを ヱホバそのみわざを喜びたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'ヱホバ地をみたまへば地ふるひ山にふれたまへば山は煙をいだす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, '生るかぎりはヱホバに向ひてうたひ 我ながらふるほどはわが神をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'ヱホバをおもふわが思念はたのしみ深からん われヱホバによりて喜ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, '罪人は地より絶滅され あしきものは復あらざるべし わが霊魂よヱホバをほめまつれヱホバを讃稱へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'ヱホバに感謝してその名をよび そのなしたまへる事をもろもろの民輩のなかにしらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'ヱホバにむかひてうたへヱホバを讃うたへ そのもろもろの妙なる事跡をかたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'そのきよき名をほこれ ヱホバをたづねもとむるものの心はよろこぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'ヱホバとその能力とをたづねもとめよ つねにその聖顔をたづねよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'その僕アブラムの裔よヤコブの子輩よ そのえらびたまひし所のものよ そのなしたまへる妙なるみわざと奇しき事跡とその口のさばきとを心にとむれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'その僕アブラムの裔よヤコブの子輩よ そのえらびたまひし所のものよ そのなしたまへる妙なるみわざと奇しき事跡とその口のさばきとを心にとむれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, '彼はわれらの神ヱホバなり そのみさばきは全地にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'ヱホバはたえずその契約をみこころに記たまへり 此はよろづ代に命じたまひし聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'アブラハムとむすびたまひし契約イサクに與へたまひし誓なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, '之をかたくしヤコブのために律法となし イスラエルのためにとこしへの契約となして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, '言たまひけるは我なんぢにカナンの地をたまひてなんぢらの嗣業の分となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'この時かれらの數おほからず甚すくなくしてかしこにて旅人となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'この國よりかの國にゆき この國よりほかの民にゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, '人のかれらを虐ぐるをゆるし給はず かれらの故によりて王たちを懲しめて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '宣給くわが受膏者たちにふるるなかれ わが預言者たちをそこなふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'ヱホバは饑饉たを地にまねき 人の杖とする糧をことごとく碎きたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, '又かれらの前にひとりを遣したまへり ヨセフはうられて僕となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'かれら足械をもてヨセフの足をそこなひ くろかねの鏈をもてその霊魂をつなげり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, '斯てそのことばの驗をうるまでに及ぶ ヱホバのみことば彼をこころみたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, '王は人をつかはしてこれを解き もろもろの民の長はこれをゆるし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, '之をその家司となし その財寶をことごとく司どらせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'その心のままにかの國のきみたちを縛しめ 長老たちに智慧ををしへしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'イスラエルも亦エジプトにゆき ヤコブはハムの地にやどれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'ヱホバはその民を大にましくはへ之をその敵よりも強くしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'また敵のこころをかへておのれの民をにくましめ おのれの僕輩をあざむき待さしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, '又そのしもべモーセとその選びたまへるアロンとを遣したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'かれらはヱホバの預兆をハムの地におこなひ またその國にくすしき事をおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'ヱホバは闇をつかはして暗くしたまへり かれらその聖言にそむくことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, '彼等のすべての水を血にかへてその魚をころしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'かれらの國は蛙むれいでて王の殿のうちにまでみちふさがりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'ヱホバいひたまへば蝿むらがり蚤そのすべての境にいりきたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'また雨にかへて霰をかれらに與へもゆる火をかれらの國にふらし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'かれらの葡萄の樹といちじくの樹とをうちその境のもろちろの樹ををりくだきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'ヱホバいひたまへば算しられぬ蝗と蟊賊きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'かれらの國のすべての田產をはみつくしその地のすべての實を食つくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'ヱホバはかれらの國のすべての首出者をうち かれらのすべての力の始をうちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'しろかね黄金をたづさへて彼等をいでゆかしめたまへり その家族のうちに一人のよわき者もなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'エジプトはかれらの出るをよろこべり かれらをおそるるの念そのうちにおこりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'ヱホバは雲をしきて蓋となし夜は火をもて照したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, '又かれらの求によりて鶉をきたらしめ天の餅にてかれらを飽しめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, '磐をひらきたまへば水ほどばしりいで 潤ひなきところに川をなして流れいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'ヱホバそのきよき聖言とその僕アブラハムとをおもひいでたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'その民をみちびきて歓びつついでしめ そのえらべる民をみちびきて謳ひつついでしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'もろもろの國人の地をかれらに與へたまひしかば 彼等もろもろのたみの勤勞をおのが有とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'こは彼等がその律にしたがひその法をまもらんが爲なり ヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'ヱホバをほめたたへヱホバに感謝せよ そのめぐみはふかくその憐憫はかぎりなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'たれかヱホバの力ある事跡をかたり その讃べきことを悉とくいひあらはし得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, '審判をまもる人々つねに正義をおこなふ者はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'ヱホバよなんぢの民にたまふ惠をもて我をおぼえ なんぢの救をもてわれに臨みたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'さらば我なんぢの撰びたまへる者のさいはひを見 なんぢの國の歓喜をよろこび なんぢの嗣業とともに誇ることをせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'われら列祖とともに罪ををかせり 我儕よこしまをなし惡をおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'われらの列祖はなんぢがエジプトにてなしたまへる奇しき事跡をさとらず 汝のあはれみの豊かなるを心にとめず 海のほとり即ち紅海のほとりにて逆きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'されどヱホバはその名のゆゑをもて彼等をすくひたまへり こは大なる能力をしらしめんとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'また紅海を叱咤したまひたれば乾きたり かくて民をみちびきて野をゆくがごとくに淵をすぎしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, '恨むるものの手よりかれらをすくひ 仇の手よりかれらを贖ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, '水その敵をおほひたればその一人だにのこりし者なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'このとき彼等そのみことばを信じその頌美をうたへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, '彼等しばしがほどにその事跡をわすれその訓誨をまたず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, '野にていたくむさぼり荒野にて神をこころみたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'ヱホバはかれらの願欲をかなへたまひしかど その霊魂をやせしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'たみは營のうちにてモーセを嫉みヱホパの聖者アロンをねたみしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, '地ひらけてダタンを呑みアビラムの黨類をおほひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, '火はこのともがらの中にもえおこり熖はあしき者をやきつくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'かれらはホレブの山にて犢をつくり鑄たる像ををがみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'かくの如くおのが榮光をかへて草をくらふ牛のかたちに似す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, '救主なる神はエジプトにて大なるわざをなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'ハムの地にて奇しき事跡をなし紅海のほとりにて懼るべきことを爲たまへり かれは斯る神をわすれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'この故にヱホバかれらを亡さんと宣まへり されど神のえらみたまへる者モーセやぶれの間隙にありてその前にたちその烈怒をひきかへして滅亡をまぬかれしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'かれら美しき地を蔑しそのみことばを信ぜず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, '剰さへその幕屋にてつぶやきヱホバの聲をもきかざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'この故に手をあげて彼等にむかひたまへり これ野にてかれらを斃れしめんとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, '又もろもろの國のうちにてその裔をたふれしめ もろもろの地にかれらを散さんとしたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, '彼らはバアルベオルにつきて死るものの祭物をくらひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, '斯のごとくその行爲をもてヱホバの烈怒をひきいだしければえやみ侵しいりたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'そのときピネハスたちて裁判をなせり かくて疫癘はやみぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'ピネハスは萬代までとこしへにこのことを義とせられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, '民メリバの水のほとりにてヱホバの烈怒をひきおこししかば かれらの故によりてモーセも禍害にあへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'かれら神の霊にそむきしかばモーセその口唇にて妄にものいひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'かれらはヱホバの命じたまへる事にしたがはずしてもろもろの民をほろぼさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, '反てもろもろの國人とまじりをりてその行爲にならひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'おのが羂となりしその偶像につかへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'かれらはその子女を鬼にささぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, '罪なき血すなはちカナンの偶像にささげたる己がむすこむすめの血をながしぬ 斯てくには血にてけがされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'またそのわざは自己をけがし そのおこなふところは姦淫なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'このゆゑにヱホバの怒その民にむかひて起り その嗣業をにくみて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'かれらをもろもろの國の手にわたしたまへり 彼等はおのれを恨るものに制へられ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'おのれの仇にしへたげられ その手の下にうちふせられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'ヱホバはしばしば助けたまひしかどかれらは謀略をまうけて逆き そのよこしまに卑くせられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'されどヱホバはかれらの哭聲をききたまひしとき その患難をかへりみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'その契約をかれらの爲におもひいだし その憐憫のゆたかなるにより聖意をかへさせ給ひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'かれらを己がとりこにせられたる者どもに憐まるることを得しめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'われらの神ヱホバよ われらをすくひて列邦のなかより取集めたまへ われらは聖名に謝し なんぢのほむべき事をほこらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'イスラエルの神ヱホバはとこしへより永遠までほむべきかな すべての民はアーメンととなふべし ヱホバを讃稱へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'ヱホバに感謝せよ ヱホバは惠ふかくましましてその憐憫かぎりなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'ヱホバの救贖をかうぶる者はみな然いふべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'ヱホバは敵の手よりかれらを贖ひもろもろの地よ東西北南よりとりあつめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'かれら野にてあれはてたる路にさまよひその住ふべき邑にあはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'かれら饑また渇きそのうちの霊魂おとろへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, '斯てその困苦のうちにてヱホバをよばはりたればヱホバこれを患難よりたすけいだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, '住ふべき邑にゆかしめんとて直き路にみちびきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, '願くはすべての人はヱホバの惠により人の子になしたまへる奇しき事跡によりてヱホバを讃稱へんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'ヱホバは渇きしたふ霊魂をたらはせ饑たるたましひを嘉物にてあかしめ給へばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'くらきと死の蔭とに居るもの患難とくろがねとに縛しめらるるもの');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, '神の言にそむき至高者のをしへを蔑しめければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, '勤勞をもてその心をひくうしたまへり かれら仆れたれど助くるものもなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, '斯てその困苦のうちにてヱホバをよばはりたればヱホバこれを患難よりすくひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'くらきと死のかげより彼等をみちびき出してその械をこぼちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, '願くはすべての人はヱホバの惠により人の子になしたまへる奇しき事跡によりてヱホバを讃稱へんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'そはあかがねの門をこぼち くろがねの關木をたちきりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, '愚かなる者はおのが愆の道により己がよこしまによりて惱めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'かれらの霊魂はすべての食物をきらひて死の門にちかづく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'かくてその困苦のうちにてヱホバをよばふ ヱホバこれを患難よりすくひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'その聖言をつかはして之をいやし之をその滅亡よりたすけいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, '願くはすべての人ヱホバのめぐみにより人の子になしたまへる奇しき事跡によりてヱホバをほめたたへんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'かれらは感謝のそなへものをささげ喜びうたひてその事跡をいひあらはすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, '舟にて海にうかび大洋にて事をいとなむ者は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'ヱホバのみわざを見また淵にてその奇しき事跡をみる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'ヱホバ命じたまへばあらき風おこりてその浪をあぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'かれら天にのぼりまた淵にくだり患難によりてその霊魂とけさり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, '左た右たにかたぶき酔たる者のごとく踉蹌てなす所をしらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'かくてその困苦のうちにてヱホバをよばふ ヱホバこれを患難よりたづさへいで');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, '狂風をしづめて浪をおだやかになし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'かれらはおのが靜かなるをよろこぶ 斯てヱホバはかれらをその望むところの湊にみちびきたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, '願くはすべての人ヱホバの惠により人の子になしたまへる奇しき事跡によりてヱホバをほめたたへんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'かれら民の會にてこれをあがめ長老の座にてこれを讃稱ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'ヱホバは河を野にかはらせ泉をかわける地に變らせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'また豊かなる地にすめる民の惡によりてそこを鹵の地にかはらせ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, '野を池にかはらせ乾ける地をいづみにかはらせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'ここに餓たるものを住はせたまふ されば彼らは己がすまひの邑をたて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, '畠にたねをまき葡萄園をまうけてそのむすべる實をえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'ヱホバはかれらの甚くふえひろごれるまでに惠をあたへ その牲畜のへることをも許したまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'されどまた虐待くるしみ悲哀によりて減ゆき且うなたれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'ヱホバもろもろの君に侮辱をそそぎ道なき荒地にさまよはせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, '然はあれど貧しきものを患難のうちより擧てその家族をひつじの群のごとくならしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, '直きものは之をみて喜びもろもろの不義はその口をふさがん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'すべて慧者はこれらのことに心をよせヱホバの憐憫をさとるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'ダビデの歌なり讃美なり 神よわが心はさだまれり われ謳ひまつらん 稱まつらん わが榮をもてたたへまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, '筝よ琴よさむべし われ黎明をよびさまさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'ヱホバよ我もろもろの民のなかにてなんぢに感謝し もろもろの國のなかにてなんぢをほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'そは汝のあはれみは大にして天のうへにあがり なんぢの眞實は雲にまでおよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, '神よねがはくはみづからを天よりもたかくし榮光を全地のうへに擧たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'ねがはくは右の手をもて救をほどこし われらに答をなして愛しみたまふものに助をえしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, '神はその聖をもていひたまへり われ甚くよろこばん我シケムをわかちスコテの谷をはからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'ギレアデはわがものマナセはわが有なりエフライムも亦わが首のまもりなりユダはわが杖');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'モアブはわが足盥なりエドムにはわが履をなげんペリシテよわが故によりて聲をあげよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, '誰かわれを堅固なる邑にすすましめんや 誰かわれをみちびきてエドムにゆきしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, '神よなんぢはわれらを棄たまひしにあらずや 神よなんぢはわれらの軍とともに出ゆきたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'ねがはくは助をわれにあたへて敵にむかはしめたまへ 人のたすけは空しければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'われらは神によりて勇しくはたらかん われらの敵をふみたまふものは神なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, '伶長にうたはしめたるダビデのうた わが讃たたふる神よもだしたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'かれらは惡の口とあざむきの口とをあけて我にむかひ いつはりの舌をもて我にかたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'うらみの言をもて我をかこみ ゆゑなく我をせめて闘ふことあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'われ愛するにかれら反りてわが敵となる われただ祈るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'かれらは惡をもてわが善にむくい恨をもてわが愛にむくいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'ねがはくは彼のうへに惡人をたてその右方に敵をたたしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'かれが鞫かるるときはその罪をあらはにせられ又そのいのりは罪となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'その日はすくなく その職はほかの人にえられ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'その子輩はみなしごとなり その妻はやもめとなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'その子輩はさすらひて乞丐 そのあれたる處よりいできたりて食をもとむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, '彼のもてるすべてのものは債主にうばはれ かれの勤勞は外人にかすめらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'かれに惠をあたふる人ひとりだになく かれの孤子をあはれむ者もなく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'その裔はたえその名はつぎの世にきえうすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'その父等のよこしまはヱホバのみこころに記され その母のつみはきえざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'かれらは恒にヱホバの前におかれ その名は地より斷るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'かかる人はあはれみを施すことをおもはず反りて貧しきもの乏しきもの心のいためる者をころさんとして攻たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'かかる人は詛ふことをこのむ この故にのろひ己にいたる惠むことをたのしまず この故にめぐみ己にとほざかれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'かかる人はころものごとくに詛をきる この故にのろひ水のごとくにおのれの衷にいり油のごとくにおのれの骨にいれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'ねがはくは詛をおのれのきたる衣のごとく帶のごとくなして恒にみづから纏はんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'これらの事はわが敵とわが霊魂にさからひて惡言をいふ者とにヱホバのあたへたまふ報なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'されど主ヱホバよなんぢの名のゆゑをもて我をかへりみたまへ なんぢの憐憫はいとふかし ねがはくは我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'われは貧しくして乏し わが心うちにて傷をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'わがゆく状はゆふ日の影のごとく また蝗のごとく吹さらるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'わが膝は斷食によりてよろめき わが肉はやせおとろふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'われは彼等にそしらるる者となれり かれら我をみるときは首をふる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'わが神ヱホバよねがはくは我をたすけその憐憫にしたがひて我をすくひたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'ヱホバよこれらは皆なんぢの手よりいで 汝のなしたまへることなるを彼等にしらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'かれらは詛へども汝はめぐみたまふ かれらの立ときは恥かしめらるれどもなんぢの僕はよろこばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'わがもろもろの敵はあなどりを衣おのが恥を外袍のごとくにまとふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'われはわが口をもて大にヱホバに謝し おほくの人のなかにて讃まつらむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'ヱホバはまづしきものの右にたちてその霊魂を罪せんとする者より之をすくひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'ダビデのうた ヱホバわが主にのたまふ 我なんぢの仇をなんぢの承足とするまではわが右にざすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'ヱホバはなんぢのちからの杖をシオンよりつきいださしめたまはん 汝はもろもろの仇のなかに王となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'なんぢのいきほひの日になんぢの民は聖なるうるはしき衣をつけ 心よりよろこびて己をささげん なんぢは朝の胎よりいづる壯きものの露をもてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'ヱホバ誓をたてて聖意をかへさせたまふことなし 汝はメルキセデクの状にひとしくとこしへに祭司たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, '主はなんぢの右にありてそのいかりの日に王等をうちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, '主はもろもろの國のなかにて審判をおこなひたまはん 此處にも彼處にも屍をみたしめ 寛濶なる地をすぶる首領をうちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'かれ道のほとりの川より汲てのみ斯てかうべを擧ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'ヱホバを讃たたへよ 我はなほきものの會あるひは公會にて心をつくしてヱホバに感謝せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'ヱホバのみわざは大なりすべてその事跡をしたふものは之をかんがへ究む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'その行ひたまふところは榮光ありまた稜威あり その公義はとこしへに失することなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'ヱホバはその奇しきみわざを人のこころに記しめたまへり ヱホバはめぐみと憐憫とにて充たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'ヱホバは己をおそるるものに糧をあたへたまへり またその契約をとこしへに心にとめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'ヱホバはもろもろの國の所領をおのれの民にあたへてその作爲のちからを之にあらはしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'その手のみわざは眞實なり公義なり そのもろもろの訓諭はかたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'これらは世々かぎりなく堅くたち眞實と正直とにてなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'ヱホバはそのたみに救贖をほどこし その契約をとこしへに立たまへり ヱホバの名は聖にしてあがむべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'ヱホバをおそるるは智慧のはじめなり これらを行ふものは皆あきらかなる聰ある人なり ヱホバの頌美はとこしへに失ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'ヱホバを讃まつれヱホバを畏れてそのもろもろの誡命をいたく喜ぶものはさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'かかる人のすゑは地にてつよく直きものの類はさいはひを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, '富と財とはその家にあり その公義はとこしへにうすることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, '直き者のために暗きなかにも光あらはる 彼は惠ゆたかに憐憫にみつる義しきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, '惠をほどこし貸ことをなす者はさいはひなり かかる人は審判をうくるときおのが訴をささへうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, '又とこしへまで動かさるることなからん義者はながく忘れらるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, '彼はあしき音信によりて畏れず その心ヱホバに依賴みてさだまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'その心かたくたちて懼るることなく敵につきての願望をつひに見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, '彼はちらして貧者にあたふ その正義はとこしへにうすることなし その角はあがめをうけて擧られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, '惡者はこれを見てうれへもだえ切歯しつつ消さらん また惡きものの願望はほろぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'ヱホバをほめまつれ汝等ヱホバの僕よほめまつれヱホバの名をほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, '今より永遠にいたるまでヱホバの名はほむべきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, '日のいづる處より日のいる處までヱホバの名はほめらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'ヱホバはもろもろの國の上にありてたかく その榮光は天よりもたかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'われらの神ヱホバにたぐふべき者はたれぞや 寳座をその高處にすゑ己をひくくして天と地とをかへりみ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'われらの神ヱホバにたぐふべき者はたれぞや 寳座をその高處にすゑ己をひくくして天と地とをかへりみ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'まづしきものを塵よりあげ乏しきものを糞土よりあげて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'もろもろの諸侯とともにすわらせ その民のきみたちと共にすわらせたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, '又はらみなき婦に家をまもらせ おほくの子女のよろこばしき母たらしめたまふ ヱホバを讃まつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'イスラエルの民エジプトをいで ヤコブのいへ異言の民をはなれしとき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'ユダはヱホバの聖所となりイスラエルはヱホバの所領となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, '海はこれを見てにげヨルダンは後にしりぞき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, '山は牡羊のごとくをどり小山はこひつじのごとく躍れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, '海よなんぢ何とてにぐるやヨルダンよなんぢ何とて後にしりぞくや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, '山よなにとて牡羊のごとくをどるや小山よなにとて小羊のごとく躍るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, '地よ主のみまへヤコブの神の前にをののけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, '主はいはを池にかはらせ石をいづみに變らせたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'ヱホバよ榮光をわれらに歸するなかれ われらに歸するなかれ なんぢのあはれみと汝のまこととの故によりてただ名にのみ歸したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'もろもろの國人はいかなればいふ 今かれらの神はいづくにありやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, '然どわれらの神は天にいます 神はみこころのままにすべての事をおこなひ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'かれらの偶像はしろかねと金にして人の手のわざなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'その偶像は口あれどいはず目あれどみず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, '耳あれどきかず鼻あれどかがず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, '手あれどとらず脚あれどあゆまず喉より聲をいだすことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, '此をつくる者とこれに依賴むものとは皆これにひとしからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'イスラエルよなんぢヱホバに依賴め ヱホバはかれらの助かれらの盾なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'アロンの家よなんぢらヱホバによりたのめ ヱホバはかれらの助かれらの盾なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'ヱホバを畏るるものよヱホバに依賴め ヱホバはかれらの助かれらの盾なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'ヱホバは我儕をみこころに記たまへり われらを惠みイスラエルの家をめぐみアロンのいへをめぐみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'また小なるも大なるもヱホバをおそるる者をめぐみたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, '願くはヱホバなんぢらを増加へ なんぢらとなんぢらの子孫とをましくはへ給はんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'なんぢらは天地をつくりたまへるヱホバに惠まるる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, '天はヱホバの天なり されど地は人の子にあたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, '死人も幽寂ところに下れるものもヤハを讃稱ふることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, '然どわれらは今より永遠にいたるまでヱホバを讃まつらむ 汝等ヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'われヱホバを愛しむ そはわが聲とわが願望とをききたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'ヱホバみみを我にかたぶけたまひしが故に われ世にあらんかぎりヱホバを呼まつらむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, '死の繩われをまとひ陰府のくるしみ我にのぞめり われは患難とうれへとにあへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'その時われヱホバの名をよべり ヱホバよ願くはわが霊魂をすくひたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'ヱホバは恩惠ゆたかにして公義ましませり われらの神はあはれみ深し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'ヱホバは愚かなるものを護りたまふ われ卑くせられしがヱホバ我をすくひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'わが霊魂よなんぢの平安にかへれ ヱホバは豊かになんぢを待ひたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, '汝はわがたましひを死より わが目をなみだより わが足を顛蹶よりたすけいだしたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'われは活るものの國にてヱホバの前にあゆまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'われ大になやめりといひつつもなほ信じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'われ惶てしときに云らく すべての人はいつはりなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, '我いかにしてその賜へるもろもろの恩惠をヱホバにむくいんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'われ救のさかづきをとりてヱホバの名をよびまつらむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, '我すべての民のまへにてヱホバにわが誓をつくのはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'ヱホバの聖徒の死はそのみまへにて貴とし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'ヱホバよ誠にわれはなんぢの僕なり われはなんぢの婢女の子にして汝のしもべなり なんぢわが縲絏をときたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'われ感謝をそなへものとして汝にささげん われヱホバの名をよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, '我すべての民のまへにてヱホバにわがちかひを償はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'ヱルサレムよ汝のなかにてヱホバのいへの大庭のなかにて此をつくのふべし ヱホバを讃まつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'もろもろの國よなんぢらヱホバを讃まつれ もろもろの民よなんぢらヱホバを稱へまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'そはわれらに賜ふその憐憫はおほいなり ヱホバの眞實はとこしへに絶ることなし ヱホバをほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'ヱホバに感謝せよヱホバは恩惠ふかくその憐憫とこしへに絶ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'イスラエルは率いふべし その憐憫はとこしへにたゆることなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'アロンの家はいざ言ふべし そのあはれみは永遠にたゆることなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'ヱホバを畏るるものは率いふべし その憐憫はとこしへにたゆることなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'われ患難のなかよりヱホバをよべば ヱホバこたへて我をひろき處におきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'ヱホバわが方にいませばわれにおそれなし 人われに何をなしえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'ヱホバはわれを助くるものとともに我がかたに坐す この故にわれを憎むものにつきての願望をわれ見ることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'ヱホバに依賴むは人にたよるよりも勝りてよし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'ヱホバによりたのむはもろもろの侯にたよるよりも勝りてよし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'もろもろの國はわれを圍めり われヱホバの名によりて彼等をほろぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'かれらは我をかこめり我をかこめりヱホバの名によりて彼等をほろぼさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'かれらは蜂のごとく我をかこめり かれらは荊の火のごとく消たり われはヱホバの名によりてかれらを滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, '汝われを倒さんとしていたく剌つれど ヱホバわれを助けたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'ヱホバはわが力わが歌にしてわが救となりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, '歓喜とすくひとの聲はただしきものの幕屋にあり ヱホバのみぎの手はいさましき動作をなしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'ヱホバのみぎの手はたかくあがりヱホバの右の手はいさましき動作をなしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'われは死ることなからん 存へてヤハの事跡をいひあらはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'ヤハはいたく我をこらしたまひしかど死には付したまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'わがために義の門をひらけ 我そのうちにいりてヤハに感謝せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'こはヱホバの門なりただしきものはその内にいるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'われ汝に感謝せん なんぢ我にこたへてわが救となりたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, '工師のすてたる石はすみの首石となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'これヱホバの成たまへる事にしてわれらの目にあやしとする所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'これヱホバの設けたまへる日なり われらはこの日によろこびたのしまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'ヱホバよねがはくはわれらを今すくひたまへ ヱホバよねがはくは我儕をいま榮えしめたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'ヱホバの名によりて來るものは福ひなり われらヱホバの家よりなんぢらを祝せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'ヱホバは神なり われらに光をあたへたまへり 繩をもて祭壇の角にいけにへをつなげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'なんぢはわが神なり我なんぢに感謝せん なんぢはわが神なり我なんぢを崇めまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'ヱホバにかんしやせよ ヱホバは恩惠ふかくその憐憫とこしへに絶ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'アレフ おのが道をなほくしてヱホバの律法をあゆむ者はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'ヱホバのもろもろの證詞をまもり 心をつくしてヱホバを尋求むるものは福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'かかる人は不義をおこなはずしてヱホバの道をあゆむなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'ヱホバよなんぢ訓諭をわれらに命じてねんごろに守らせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'なんぢわが道をかたくたててその律法をまもらせたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'われ汝のもろもろの誡命にこころをとむるときは恥ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'われ汝のただしき審判をまなばば 直き心をもてなんぢに感謝せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'われは律法をまもらん われを棄はてたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, '○ベテ わかき人はなにによりてかその道をきよめん 聖言にしたがひて愼むのほかぞなき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'われ心をつくして汝をたづねもとめたり 願くはなんぢの誡命より迷ひいださしめ給ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'われ汝にむかひて罪ををかすまじき爲になんぢの言をわが心のうちに蔵へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, '讃べきかなヱホバよねがはくは律法をわれに敎へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'われわが口唇をもてなんぢの口よりいでしもろもろの審判をのべつたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, '我もろもろの財貨をよろこぶごとくに汝のあかしの道をよろこべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, '我なんぢの訓諭をおもひ汝のみちに心をとめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'われは律法をよろこび聖言をわするることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, '○ギメル ねがはくは汝のしもべを豊にあしらひて存へしめたまへ さらばわれ聖言をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'なんぢわが眼をひらき なんぢの法のうちなる奇しきことを我にみせたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'われは世にある旅客なり 我になんぢの誡命をかくしたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, '斷るときなくなんぢの審判をしたふが故にわが霊魂はくだくるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, '汝はたかぶる者をせめたまへり なんぢの誡命よりまよひづる者はのろはる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, '我なんぢの證詞をまもりたり 我より謗とあなどりとを取去たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, '又もろもろの侯は坐して相語りわれをそこなはんとせり 然はあれど汝のしもべは律法をふかく思へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, '汝のもろもろの證詞はわれをよろこばせわれをさとす者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, '○ダレテ わが霊魂は塵につきぬ なんぢの言にしたがひて我をいかしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, '我わがふめる道をあらはししかば汝こたへを我になしたまへり なんぢの律法をわれに敎へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'なんぢの訓諭のみちを我にわきまへしめたまへ われ汝のくすしき事跡をふかく思はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'わがたましひ痛めるによりてとけゆく ねがはくは聖言にしたがひて我にちからを予へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, '願くはいつはりの道をわれより遠ざけ なんぢの法をもて我をめぐみたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'われは眞實のみちをえらび 恒になんぢのもろもろの審判をわが前におけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, '我なんぢの證詞をしたひて離れず ヱホバよねがはくは我をはづかしめ給ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'われ汝のいましめの道をはしらん その時なんぢわが心をひろく爲たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, '○へ ヱホバよ願くはなんぢの律法のみちを我にをしへたまへ われ終にいたるまで之をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'われに智慧をあたへ給へ さらば我なんぢの法をまもり心をつくして之にしたがはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'われに汝のいましめの道をふましめたまへ われその道をたのしめばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'わが心をなんぢの證詞にかたぶかしめて 貪利にかたぶかしめ給ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'わが眼をほかにむけて虚しきことを見ざらしめ 我をなんぢの途にて活し給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'ひたすらに汝をおそるる汝のしもべに 聖言をかたくしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'わがおそるる謗をのぞきたまへ そはなんぢの審判はきはめて善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, '我なんぢの訓諭をしたへり 願くはなんぢの義をもて我をいかしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, '○ワウ ヱホバよ聖言にしたがひてなんぢの憐憫なんぢの拯救を我にのぞませたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'さらば我われを謗るものに答ふることをえん われ聖言によりたのめばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, '又わが口より眞理のことばをことごとく除き給ふなかれ われなんぢの審判をのぞみたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'われたえずいや永久になんぢの法をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'われなんぢの訓諭をもとめたるにより障なくしてあゆまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'われまた王たちの前になんぢの證詞をかたりて恥ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, '我わが愛するなんぢの誡命をもて己をたのしましめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'われ手をわがあいする汝のいましめに擧げ なんぢの律法をふかく思はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, '○ザイン ねがはくは汝のしもべに宣ひたる聖言をおもひいだしたまへ 汝われに之をのぞましめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'なんぢの聖言はわれを活ししがゆゑに 今もなほわが艱難のときの安慰なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, '高ぶる者おほいに我をあざわらへり されど我なんぢの法をはなれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'ヱホバよわれ汝がふるき往昔よりの審判をおもひいだして自から慰めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'なんぢの法をすつる惡者のゆゑによりて 我はげしき怒をおこしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'なんぢの律法はわが旅の家にてわが歌となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'ヱホバよわれ夜間になんぢの名をおもひいだして なんぢの法をまもれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'われ汝のさとしを守りしによりてこの事をえたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, '○ヘテ ヱホバはわがうくべき有なり われ汝のもろもろの言をまもらんといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'われ心をつくして汝のめぐみを請求めたり ねがはくは聖言にしたがひて我をあはれみたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, '我わがすべての途をおもひ 足をかへしてなんぢの證詞にむけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, '我なんぢの誡命をまもるに速けくしてたゆたはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, '惡きものの繩われに纏ひたれども 我なんぢの法をわすれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, '我なんぢのただしき審判のゆゑに 夜半におきてなんぢに感謝せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'われは汝をおそるる者 またなんぢの訓諭をまもるものの侶なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'ヱホバよ汝のあはれみは地にみちたり 願くはなんぢの律法をわれにをしへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, '○テテ ヱホバよなんぢ聖言にしたがひ惠をもてその僕をあしらひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'われ汝のいましめを信ず ねがはくはわれに聡明と智識とををしへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'われ苦しまざる前にはまよひいでぬ されど今はわれ聖言をまもる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'なんぢは善にして善をおこなひたまふ ねがはくは汝のおきてを我にをしへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, '高ぶるもの虚偽をくはだてて我にさからへり われ心をつくしてなんぢの訓諭をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'かれらの心はこえふとりて脂のごとし されど我はなんぢの法をたのしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, '困苦にあひたりしは我によきことなり 此によりて我なんぢの律法をまなびえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'なんぢの口の法はわがためには千々のこがね白銀にもまされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, '○ヨーデ なんぢの手はわれを造りわれを形づくれり ねがはくは智慧をあたへて我になんぢの誡命をまなばしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'なんぢを畏るるものは我をみて喜ばん われ聖言によりて望をいたきたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'ヱホバよ我はなんぢの審判のただしく又なんぢが眞實をもて我をくるしめたまひしを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'ねがはくは汝のしもべに宣ひたる聖言にしたがひて 汝の仁慈をわが安慰となしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'なんぢの憐憫をわれに臨ませたまへ さらばわれ生ん なんぢの法はわが樂しめるところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, '高ぶるものに恥をかうぷらせたまへ かれらは虚偽をもて我をくつがへしたればなり されど我なんぢの訓諭をふかくおもはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, '汝をおそるる者となんぢの證詞をしるものとを我にかへらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'わがこころを全くして汝のおきてを守らしめたまへ さらばわれ恥をかうぶらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, '○カフ わが霊魂はなんぢの救をしたひてたえいるばかりなり 然どわれなほ聖言によりて望をいだく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'なんぢ何のとき我をなぐさむるやといひつつ 我みことばを慕ふによりて眼おとろふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, '我は煙のなかの革嚢のごとくなりぬれども 尚なんぢの律法をわすれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, '汝のしもべの日は幾何ありや 汝いづれのとき我をせむるものに審判をおこなひたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'たかぶる者われを害はんとて阱をほれり かれらはなんぢの法にしたがはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'なんぢの誡命はみな眞實なり かれらは虚偽をもて我をせむ ねがはくは我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'かれらは地にてほとんど我をほろぼせり されど我はなんぢの訓諭をすてざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, '願くはなんぢの仁慈にしたがひて我をいかしたまへ 然ばわれ御口よりいづる證詞をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, '○ラメテ ヱホバよみことばは天にてとこしえに定まり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'なんぢの眞實はよろづ世におよぶ なんぢ地をかたく立たまへば地はつねにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'これらのものはなんぢの命令にしたがひ 恒にありて今日にいたる 萬のものは皆なんぢの僕なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'なんぢの法わがたのしみとならざりしならば我はつひに患難のうちに滅びたるならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'われ恒になんぢの訓諭をわすれじ 汝これをもて我をいかしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, '我はなんぢの有なりねがはくは我をすくひたまへ われ汝のさとしを求めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, '惡きものは我をほろぼさんとして窺ひぬ われは唯なんぢのもろもろの證詞をおもはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, '我もろもろの純全に限あるをみたり されど汝のいましめはいと廣し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, '○メム われなんぢの法をいつくしむこといかばかりぞや われ終日これを深くおもふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'なんぢの誡命はつねに我とともにありて 我をわが仇にまさりて慧からしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, '我はなんぢの證詞をふかくおもふが故に わがすべての師にまさりて智慧おほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, '我はなんぢの訓諭をまもるがゆゑに 老たる者にまさりて事をわきまふるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'われ聖言をまもらんために わが足をとどめてもろもろのあしき途にゆかしめず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'なんぢ我ををしへたまひしによりて 我なんぢの審判をはなれざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'みことばの滋味はわが腭にあまきこといかばかりぞや 蜜のわが口に甘きにまされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, '我なんぢの訓諭によりて智慧をえたり このゆゑに虚偽のすべての途をにくむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, '○ヌン なんぢの聖言はわがあしの燈火わが路のひかりなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'われなんぢのただしき審判をまもらんことをちかひ且かたくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'われ甚いたく苦しめり ヱホバよねがはくは聖言にしたがひて我をいかしたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'ヱホバよねがはくは誠意よりするわが口の献物をうけて なんぢの審判ををしへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'わが霊魂はつねに危険ををかす されど我なんぢの法をわすれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'あしき者わがために羂をまうけたり されどわれ汝のさとしより迷ひいでざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'われ汝のもろもろの證詞をとこしへにわが嗣業とせり これらの證詞はわが心をよろこばしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'われ汝のおきてを終までとこしへに守らんとて之にこころを傾けたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, '○サメク われ二心のものをにくみ汝のおきてを愛しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'なんぢはわが匿るべき所わが盾なり われ聖言によりて望をいだく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, '惡きをなすものよ我をはなれされ われわが神のいましめを守らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, '聖言にしたがひ我をささへて生存しめたまへ わが望につきて恥なからしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'われを支へたまへ さらばわれ安けかるべし われ恒になんぢの律法にこころをそそがん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'すべて律法よりまよひいづるものを汝かろしめたまへり かれらの欺詐はむなしければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'なんぢは地のすべての惡きものを渣滓のごとく除きさりたまふ この故にわれ汝のあかしを愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'わが肉體なんぢを懼るるによりてふるふ 我はなんぢの審判をおそる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, '○アイン われは審判と公義とをおこなふ 我をすてて虐ぐるものに委ねたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, '汝のしもべの中保となりて福祉をえしめたまへ 高ぶるものの我をしへたぐるを容したまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'わが眼はなんぢの救となんぢのただしき聖言とをしたふによりておとろふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'ねがはくはなんぢの憐憫にしたがひてなんぢの僕をあしらひ 我になんぢの律法ををしへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, '我はなんぢの僕なり われに智慧をあたへてなんぢの證詞をしらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, '彼等はなんぢの法をすてたり 今はヱホバのはたらきたまふべき時なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'この故にわれ金よりもまじりなき金よりもまさりて汝のいましめを愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'この故にもろもろのことに係るなんぢの一切のさとしを正しとおもふ 我すべてのいつはりの途をにくむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, '○べ 汝のあかしは妙なり かかるが故にわが霊魂これをまもる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, '聖言うちひらくれば光をはなちて 愚かなるものをさとからしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, '我なんぢの誡命をしたふが故に わが口をひろくあけて喘ぎもとめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'ねがはくは聖名を愛するものに恒になしたまふごとく身をかへして我をあはれみたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, '聖言をもてわが歩履をととのへ もろもろの邪曲をわれに主たらしめたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'われを人のしへたげより贖ひたまへ さらばわれ訓諭をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'ねがはくは聖顔をなんぢの僕のうへにてらし 汝のおきてを我にをしへ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, '人なんぢの法をまもらざるによりて わが眼のなみだ河のごとくに流る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, '○ツァデー ヱホバよなんぢは義しくなんぢの審判はなほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, '汝ただしきと此上なき眞實とをもて その證詞を命じ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'わが敵なんぢの聖言をわすれたるをもて わが熱心われをほろぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'なんぢの聖言はいときよし 此故になんぢの僕はこれを愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'われは微なるものにて人にあなどらるれども汝のさとしを忘れず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'なんぢの義はとこしへの義なり汝ののりは眞理なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'われ患難と憂とにかかれども 汝のいましめはわが喜樂なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'なんぢの證詞はとこしへに義し ねがはくはわれに智慧をたまへ 我ながらふることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, '○コフ われ心をつくしてよばはれり ヱホバよ我にこたへたまへ 我なんぢの律法をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'われ汝をよばはれり ねがはくはわれを救ひ給へ 我なんぢの證詞をまもらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'われ詰朝おきいでて呼はれり われ聖言によりて望をいだけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, '夜の更のきたらぬに先だち わが眼はさめて汝のみことばを深くおもふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'ねがはくはなんぢの仁慈にしたがひてわが聲をききたまへ ヱホバよなんぢの審判にしたがひて我をいかしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, '惡をおひもとむるものは我にちかづけり 彼等はなんぢの法にとほくはなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'ヱホバよ汝はわれに近くましませり なんぢのすべての誡命はまことなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'われ早くよりなんぢの證詞によりて汝がこれを永遠にたてたまへることを知れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, '○レシ ねがはくはわが患難をみて我をすくひたまへ 我なんぢの法をわすれざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'ねがはくはわが訟をあげつらひて我をあがなひ 聖言にしたがひて我をいかしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'すくひは惡きものより遠くはなる かれらはなんぢの律法をもとめざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'ヱホバよなんぢの憐憫はおほいなり 願くはなんぢの審判にしたがひて我をいかしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, '我をせむる者われに敵するものおほし 我なんぢの證詞をはなるることなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, '虚偽をおこなふもの汝のみことばを守らざるにより 我かれらを見てうれへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'ねがはくはわが汝のさとしを愛すること幾何なるをかへりみたまへ ヱホバよなんぢの仁慈にしたがひて我をいかしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'なんぢのみことばの總計はまことなり 汝のただしき審判はとこしへにいたるまで皆たゆることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, '○シン もろもろの侯はゆゑなくして我をせむ 然どわが心はただ汝のみことばを畏る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'われ人のおほいなる掠物をえたるごとくに 汝のみことばをよろこぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'われ虚偽をにくみ之をいみきらへども 汝ののりを愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'われ汝のただしき審判のゆゑをもて 一日に七次なんぢを讃稱ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'なんぢの法をあいするものには大なる平安あり かれらには躓礙をあたふる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'ヱホバよ我なんぢの救をのぞみ汝のいましめをおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'わが霊魂はなんぢの證詞をまもれり 我はいたく之をあいす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'われなんぢの訓諭となんぢの證詞とをまもりぬ わがすべての道はみまへにあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, '○タウ ヱホバよ願くはわがよぶ聲をみまへにちかづけ 聖言にしたがひて我にちゑをあたへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'わが願をみまへにいたらせ 聖言にしたがひて我をたすけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'わがくちびるは讃美をいだすべし 汝われに律法ををしへ給へばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'わが舌はみことばを謳ふべし なんぢの一切のいましめは義なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'なんぢの手をつねにわが助となしたまへ われなんぢの訓諭をえらび用ゐたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'ヱホバよ我なんぢの救をしたへり なんぢの法はわがたのしみなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, '願くはわが霊魂をながらへしめたまへ さらば汝をほめたたへん 汝のさばきの我をたすけんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'われは亡はれたる羊のごとく迷ひいでぬ なんぢの僕をたづねたまへ われ汝のいましめを忘れざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, '京詣のうた われ困苦にあひてヱホバをよびしかば我にこたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'ヱホバよねがはくは虚偽のくちびる欺詐の舌よりわが霊魂をたすけいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'あざむきの舌よなんぢに何をあたへられ 何をくはへらるべきか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'ますらをの利き箭と金萑花のあつき炭となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'わざはひなるかな我はメセクにやどりケダルの幕屋のかたはらに住めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'わがたましひは平安をにくむものと偕にすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'われは平安をねがふ されど我ものいふときにかれら戰爭をこのむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, '京まうでの歌 われ山にむかひて目をあぐ わが扶助はいづこよりきたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'わがたすけは天地をつくりたまへるヱホバよりきたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'ヱホバはなんぢの足のうごかさるるを容したまはず 汝をまもるものは微睡たまふことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, '視よイスラエルを守りたまふものは微睡こともなく寝ることもなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'ヱホバは汝をまもる者なり ヱホバはなんぢの右手をおほふ蔭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'ひるは日なんぢをうたず夜は月なんぢを傷じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'ヱホバはなんぢを守りてもろもろの禍害をまぬかれしめ並なんぢの霊魂をまもりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'ヱホバは今よりとこしへにいたるまで 汝のいづると入るとをまもりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'ダビデがよめる京まうでの歌 人われにむかひて率ヱホバのいへにゆかんといへるとき我よろこべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'ヱルサレムよわれらの足はなんぢの門のうちにたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'ヱルサレムよなんぢは稠くつらなりたる邑のごとく固くたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'もろもろのやから即ちヤハの支派かしこに上りきたり イスラエルにむかひて證詞をなし またヱホバの名にかんしやをなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, '彼處にさばきの寳座まうけらる これダビデの家のみくらなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'ヱルサレムのために平安をいのれ ヱルサレムを愛するものは榮ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'ねがはくはなんぢの石垣のうちに平安あり なんぢの諸殿のうちに福祉あらんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'わが兄弟のためわが侶のために われ今なんぢのなかに平安あれといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'われらの神ヱホバのいへのために我なんぢの福祉をもとめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, '京まうでの歌 天にいますものよ我なんぢにむかひて目をあぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'みよ僕その主の手に目をそそぎ 婢女その主母の手に目をそそぐがごとく われらはわが神ヱホバに目をそそぎて そのわれを憐みたまはんことをまつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'ねがはくはわれらを憐みたまヘ ヱホバよわれらを憐みたまへ そはわれらに軽侮はみちあふれぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'おもひわづらひなきものの凌辱と たかぶるものの軽侮とはわれらの霊魂にみちあふれぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'ダビデのよめる京まうでの歌 今イスラエルはいふべし ヱホバもしわれらの方にいまさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, '人々われらにさからひて起りたつとき ヱホバもし我儕のかたに在さざりしならんには');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'かれらの怒のわれらにむかひておこりし時 われらを生るままにて呑しならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'また水はわれらをおほひ 流はわれらの霊魂をうちこえ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, '高ぶる水はわれらの霊魂をうちこえしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'ヱホバはほむべきかな我儕をかれらの歯にわたして噛くらはせたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, '我儕のたましひは捕鳥者のわなをのがるる鳥のごとくにのがれたり 羅はやぶれてわれらはのがれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'われらの助は天地をつくりたまへるヱホバの名にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'みやこ詣のうた ヱホバに依賴むものはシオンの山のうごかさるることなくして永遠にあるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'ヱルサレムを山のかこめるごとくヱホバも今よりとこしへにその民をかこみたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, '惡の杖はただしきものの所領にとどまることなかるべし斯てただしきものはその手を不義にのぶることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'ヱホバよねがはくは善人とこころ直きものとに福祉をほどこしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'されどヱホバは轉へりておのが曲れる道にいるものを惡きわざをなすものとともに去しめたまはん 平安はイスラエルのうへにあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, '京まうでの歌 ヱホバ、シオンの俘囚をかへしたまひし時 われらは夢みるもののごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'そのとき笑はわれらの口にみち歌はわれらの舌にみてり ヱホバかれらのために大なることを作たまへりといへる者もろもろの國のなかにありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'ヱホバわれらのために大なることをなしたまひたれば我儕はたのしめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'ヱホバよ願くはわれらの俘囚をみなみの川のごとくに歸したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, '涙とともに播くものは歡喜とともに穫らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'その人は種をたづさへ涙をながしていでゆけど禾束をたづさへ喜びてかへりきたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'ソロモンがよめる京まうでのうた ヱホバ家をたてたまふにあらずば 建るものの勤勞はむなしく ヱホバ城をまもりたまふにあらずば衛士のさめをるは徒勞なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'なんぢら早くおき遅くいねて辛苦の糧をくらふはむなしきなり 斯てヱホバその愛しみたまふものに寝をあたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'みよ子輩はヱホバのあたへたまふ嗣業にして 胎の實はその報のたまものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, '年壯きころほひの子はますらをの手にある矢のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, '矢のみちたる箙をもつ人はさいはひなり かれら門にありて仇とものいふとき恥ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, '京まうでの歌 ヱホバをおそれその道をあゆむものは皆さいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'そはなんぢおのが手の勤勞をくらふべければなり なんぢは福祉をえまた安處にをるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'なんぢの妻はいへの奧にをりておほくの實をむすぶ葡萄の樹のごとく汝の子輩はなんぢの筵に円居してかんらんの若樹のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, '見よヱホバをおそるる者はかく福祉をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'ヱホバはシオンより惠をなんぢに賜はん なんぢ世にあらんかぎりヱルサレムの福祉をみん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'なんぢおのが子輩の子をみるべし 平安はイスラエルの上にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, '京まうでのうた 今イスラエルはいふべし彼等はしばしば我をわかきときより惱めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'かれらはしばしば我をわかきときより惱めたり されどわれに勝ことを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, '耕すものはわが背をたがへしてその畎をながくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'ヱホバは義し あしきものの繩をたちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'シオンをにくむ者はみな恥をおびてしりぞかせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'かれらは長たざるさきにかるる屋上の草のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'これを刈るものはその手にみたず 之をつかぬるものはその束ふところに盈ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'かたはらを過るものはヱホバの惠なんぢの上にあれといはず われらヱホバの名によりてなんぢらを祝すといはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, '京まうでの歌 ああヱホバよわれふかき淵より汝をよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, '主よねがはくはわが聲をきき汝のみみをわが懇求のこゑにかたぶけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'ヤハよ主よなんぢ若もろもろの不義に目をとめたまはば誰たれかよく立ことをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'されどなんぢに赦あれば人におそれかしこまれ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, '我ヱホバを俟望む わが霊魂はまちのぞむ われはその聖言によりて望をいだく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'わがたましひは衛士があしたを待にまさり 誠にゑじが旦をまつにまさりて主をまてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'イスラエルよヱホバによりて望をいだけ そはヱホバにあはれみあり またゆたかなる救贖あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'ヱホバはイスラエルをそのもろもろの邪曲よりあがなひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'ダビデのよめる京まうでのうた ヱホバよわが心おごらずわが目たかぶらず われは大なることと我におよばぬ奇しき事とをつとめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'われはわが霊魂をもださしめまた安からしめたり 乳をたちし嬰兒のその母にたよるごとく 我がたましひは乳をたちし嬰兒のごとくわれに恃れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'イスラエルよ今よりとこしへにヱホバにたよりて望をいだけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, '京まうでの歌 ヱホバよねがはくはダビデの爲にそのもろもろの憂をこころに記たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'ダビデ、ヱホバにちかひヤコブの全能者にうけひていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'われヱホバのために處をたづねいだし ヤコブの全能者のために居所をもとめうるまでは 我家の幕屋にいらず わが臥床にのぼらず わが目をねぶらしめず わが眼瞼をとぢしめざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'われヱホバのために處をたづねいだし ヤコブの全能者のために居所をもとめうるまでは 我家の幕屋にいらず わが臥床にのぼらず わが目をねぶらしめず わが眼瞼をとぢしめざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'われヱホバのために處をたづねいだし ヤコブの全能者のために居所をもとめうるまでは 我家の幕屋にいらず わが臥床にのぼらず わが目をねぶらしめず わが眼瞼をとぢしめざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'われらエフラタにて之をききヤアルの野にて見とめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'われらはその居所にゆきて その承足のまへに俯伏さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'ヱホバよねがはくは起きて なんぢの稜威の櫃とともになんぢの安居所にいりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'なんぢの祭司たちは義を衣 なんぢの聖徒はみな歓びよばふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'なんぢの僕ダビデのためになんぢの受膏者の面をしりぞけたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'ヱホバ眞實をもてダビデに誓ひたまひたれば之にたがふことあらじ 曰くわれなんぢの身よりいでし者をなんぢの座位にざせしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'なんぢの子輩もしわがをしふる契約と證詞とをまもらばかれらの子輩もまた永遠になんぢの座位にざすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'ヱホバはシオンを擇びておのが居所にせんとのぞみたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '曰くこれは永遠にわが安居處なり われここに住ん そはわれ之をのぞみたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'われシオンの糧をゆたかに祝し くひものをもてその貧者をあかしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'われ救をもてその祭司たちに衣せん その聖徒はみな聲たからかによろこびよばふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'われダビデのためにかしこに一つの角をはえしめん わが受膏者のために燈火をそなへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'われかれの仇にはぢを衣せん されどかれはその冠弁さかゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'ダビデがよめる京まうでの歌 觀よはらから相睦てともにをるはいかに善いかに樂きかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, '首にそそがれたる貴きあぶら鬚にながれ アロンの鬚にながれ その衣のすそにまで流れしたたるるがごとく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'またヘルモンの露くだりてシオンの山にながるるがごとし そはヱホバかしこに福祉をくだし窮なき生命をさへあたへたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, '京まうでの歌 夜間ヱホバの家にたちヱホバに事ふるもろもろの僕よ ヱホバをほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'なんぢら聖所にむかひ手をあげてヱホバをほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'ねがはくはヱホバ天地をつくりたまへるもの シオンより汝をめぐみたまはんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'なんぢらヱホバを讃稱へよ ヱホバの名をほめたたへよ ヱホバの僕等ほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'ヱホバの家われらの神のいへの大庭にたつものよ讃稱へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'ヱホバは惠ふかし なんぢらヱホバをほめたたへよ その聖名はうるはし讃うたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'そはヤハおのがためにヤコブをえらみ イスラエルをえらみてその珍寳となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'われヱホバの大なるとわれらの主のもろもろの神にまされるとをしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'ヱホバその聖旨にかなふことを天にも地にも海にも淵にもみなことごとく行ひ給ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'ヱホバは地のはてより霧をのぼらせ 雨のために電光をつくりその庫より風をいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'ヱホバは人より畜類にいたるまでエジプトの首出をうちたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'エジプトよヱホバはなんぢの中にしるしと奇しき事跡とをおくりて パロとその僕とに臨ませ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'ヱホバはおほくの國々をうち 又いきほひある王等をころし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'アモリ人のわうシホン、バシヤンの王オグならびにカナンの國々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'かれらの地をゆづりとしその民イスフルの嗣業としてあたへ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'ヱホバよなんぢの名はとこしへに絶ることなし ヱホバよなんぢの記念はよろづ世におよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'ヱホバはその民のために審判をなしその僕等にかかはれる聖意をかへたまふ可ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'もろもろのくにの偶像はしろかねと金にして人の手のわざなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'そのぐうざうは口あれどいはず目あれど見ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, '耳あれどきかず またその口に氣息あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'これを造るものと之によりたのむものとは皆これにひとしからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'イスラエルの家よヱホバをほめまつれ アロンのいへよヱホバをほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'レビの家よヱホバをほめまつれ ヱホバを畏るるものよヱホバをほめまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'ヱルサレムにすみたまふヱホバはシオンにて讃まつるべきかな ヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'ヱホバに感謝せよヱホバはめぐみふかし その憐憫はとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'もろもろの神の神にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'もろもろの主の主にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'ただ獨りおほいなる奇跡なしたまふものに感謝せよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, '智慧をもてもろもろの天をつくりたまへるものに感謝せよ そのあはれみはとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, '地を水のうへに布たまへるものに感謝せよ そのあはれみは永遠にたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, '巨大なる光をつくりたまへる者にかんしやせよ その憐憫はとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, '晝をつかさどらするために日をつくりたまへる者にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, '夜をつかさどらするために月ともろもろの星とをつくりたまへる者にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'もろもろの首出をうちてエジプトを責たまへるものに感謝せよ そのあはれみは永遠にたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'イスラエルを率てエジプト人のなかより出したまへる者にかんしやせよ そのあはれみはとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, '臂をのばしつよき手をもて之をひきいだしたまへる者にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, '紅海をふたつに分たまへる者にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'イスラエルをしてその中をわたらしめ給へるものに感謝せよ そのあはれみは永遠にたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'パロとその軍兵とを紅海のうちに仆したまへるものに感謝せよ そのあはれみは永遠にたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'その民をみちびきて野をすぎしめたまへる者にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, '大なる王たちを撃たまへるものに感謝せよ そのあはれみは永遠にたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, '名ある王等をころしたまへる者にかんしやせよ その憐憫はとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'アモリ人のわうシホンをころしたまへる者にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'バシヤンのわうオグを誅したまへるものに感謝せよ そのあはれみは永遠にたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'かれらの地を嗣業としてあたへたまへる者にかんしやせよ その憐憫はとこしへにたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'その僕イスラエルにゆづりとして之をあたへたまへるものに感謝せよ そのあはれみは永遠にたゆることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'われらが微賤かりしときに記念したまへる者にかんしやせよ その憐憫はとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'わが敵よりわれらを助けいだしたまへる者にかんしやせよ その憐憫はとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'すべての生るものに食物をあたへたまふものに感謝せよ そのあはれみはとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, '天の神にかんしやせよ その憐憫はとこしへに絶ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'われらバビロンの河のほとりにすわり シオンをおもひいでて涙をながしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'われらそのあたりの柳にわが琴をかけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'そはわれらを虜にせしものわれらに歌をもとめたり 我儕をくるしむる者われらにおのれを歓ばせんとて シオンのうた一つうたへといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'われら外邦にありていかでヱホバの歌をうたはんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'エルサレムよもし我なんぢをわすれなばわが右の手にその巧をわすれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'もしわれ汝を思ひいでず もしわれヱルサレムをわがすべての歓喜の極となさずばわが舌をわが腭につかしめたまヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'ヱホバよねがはくはヱルサレムの日にエドムの子輩がこれを掃除けその基までもはらひのぞけといへるを聖意にとめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'ほろぼさるべきバビロンの女よ なんぢがわれらに作しごとく汝にむくゆる人はさいはひなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'なんぢの嬰兒をとりて岩のうへになげうつものは福ひなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'ダビデのうた われはわが心をつくしてなんぢに感謝し もろもろの神のまへにて汝をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, '我なんぢのきよき宮にむかひて伏拝み なんぢの仁慈とまこととの故によりて聖名にかんしやせん そは汝そのみことばをもろもろの聖名にまさりて高くしたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, '汝わがよばはりし日にわれにこたへ わが霊魂にちからをあたへて雄々しからしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'ヱホバよ地のすべての王はなんぢに感謝せん かれらはなんぢの口のもろもろの言をききたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'かれらはヱホバのもろもろの途についてうたはん ヱホバの榮光おほいなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'ヱホバは高くましませども卑きものを顧みたまふ されど亦おごれるものを遠よりしりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, '縦ひわれ患難のなかを歩むとも汝われをふたたび活し その手をのばしてわが仇のいかりをふせぎ その右の手われをすくひたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'ヱホバはわれに係れることを全うしたまはん ヱホバよなんぢの憐憫はとこしへにたゆることなし願くはなんぢの手のもろもろの事跡をすてたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, '伶長にうたはしめたるダビデの歌 ヱホバよなんぢは我をさぐり我をしりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'なんぢはわが坐るをも立をもしり 又とほくよりわが念をわきまへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'なんぢはわが歩むをもわが臥をもさぐりいだし わがもろもろの途をことごとく知たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'そはわが舌に一言ありとも觀よヱホバよなんぢことごとく知たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'なんぢは前より後よりわれをかこみ わが上にその手をおき給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'かかる知識はいとくすしくして我にすぐ また高くして及ぶことあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, '我いづこにゆきてなんぢの聖霊をはなれんや われいづこに往てなんぢの前をのがれんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'われ天にのぼるとも汝かしこにいまし われわが榻を陰府にまうくるとも 觀よなんぢ彼處にいます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, '我あけぼのの翼をかりて海のはてにすむとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'かしこにて尚なんぢの手われをみちびき汝のみぎの手われをたもちたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, '暗はかならす我をおほひ 我をかこめる光は夜とならんと我いふとも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, '汝のみまへには暗ものをかくすことなく 夜もひるのごとくに輝けり なんぢにはくらきも光もことなることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, '汝はわがはらわたをつくり 又わがははの胎にわれを組成たまひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'われなんぢに感謝す われは畏るべく奇しくつくられたり なんぢの事跡はことごとくくすし わが霊魂はいとつばらに之をしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'われ隠れたるところにてつくられ地の底所にて妙につづりあはされしとき わが骨なんぢにかくるることなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'わが體いまだ全からざるに なんぢの目ははやくより之をみ 日々かたちづくられしわが百體の一だにあらざりし時に ことごとくなんぢの冊にしるされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, '神よなんぢりもろもろの思念はわれに寶きこといかばかりぞや そのみおもひの總計はいかに多きかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, '我これを算へんとすれどもそのかずは沙よりもおほし われ眼さむるときも尚なんぢとともにをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, '神よなんぢはかならず惡者をころし給はん されば血をながすものよ我をはなれされ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'かれらはあしき企圖をもて汝にさからひて言ふ なんぢの仇はみだりに聖名をとなふるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'ヱホバよわれは汝をにくむ者をにくむにあらずや なんぢに逆ひておこりたつものを厭ふにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'われ甚くかれらをにくみてわが仇とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, '神よねがはくは我をさぐりてわが心をしり 我をこころみてわがもろもろの思念をしりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'ねがはくは我によこしまなる途のありやなしやを見て われを永遠のみちに導きたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, '伶長にうたはしめたるダビデのうた ヱホバよねがはくは惡人よりわれを助けいだし 我をまもりて強暴人よりのがれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'かれらは心のうちに殘害をくはだて たえず戰闘をおこす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'かれらは蛇のごとくおのが舌を利す そのくちびるのうちに蝮の毒あり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'ヱホバよ願くはわれを保ちてあしきひとの手よりのがれしめ 我をまもりてわが足をつまづかせんと謀るあらぶる人よりのがれしめ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, '高ぶるものはわがために羂と索とをふせ 路のほとりに網をはり かつ機をまうけたり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'われヱホバにいへらく汝はわが神なり ヱホバよねがはくはわが祈のこゑをきき給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'わが救のちからなる主の神よ なんぢはたたかひの日にわが首をおほひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'ヱホバよあしきひとの欲のままにすることをゆるしたまふなかれ そのあしき企圖をとげしめたまふなかれ おそらくは彼等みづから誇らん セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'われを圍むものの首はおのれのくちびるの殘害におほはるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'もえたる炭はかれらのうへにおち かれらは火になげいれられ ふかき穴になげいれられて再びおきいづることあたはざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, '惡言をいふものは世にたてられず 暴ぶるものはわざはひに追及れてたふさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'われは苦しむものの訴とまづしきものの義とをヱホバの守りたまふを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, '義者はかならず聖名にかんしやし直者はみまへに住ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'ダビデのうた ヱホバよ我なんぢを呼ふ ねがはくは速かにわれにきたりたまへ われ汝をよばふときわが聲に耳をかたぶけたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'われは薫物のごとくにわが祈をみまへにささげ 夕のそなへものの如くにわが手をあげて聖前にささげんことをねがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'ヱホバよねがはくはわが口に門守をおきて わがくちびるの戸をまもりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, '惡事にわがこころを傾かしめて邪曲をおこなふ者とともに惡きわざにあづからしめ給ふなかれ 又かれらの珍饈をくらはしめたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, '義者われをうつとも我はこれを愛しみとしその我をせむるを頭のあぶらとせん わが頭はこれを辭まず かれらが禍害にあふときもわが祈はたえじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'その審士ははほの崕になげられん かれらわがことばの甘美によりて聽ことをすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, '人つちを耕しうがつがごとく我儕のほねははかの口にちらさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'されど主ヱホバよわが目はなほ汝にむかふ 我なんぢに依賴めり ねがはくはわが霊魂をともしきままに捨おきたまなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, '我をまもりてかれらがわがためにまうくる羂とよこしまを行ふものの機とをまぬかれしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'われは全くのがれん あしきものをおのれの網におちいらしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'ダビデが洞にありしときよみたる敎へのうたなり祈なり われ聲をいだしてヱホバによばはり 聲をいだしてヱホバにこひもとむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'われはその聖前にわが歎息をそそぎいだし そのみまへにわが患難をあらはす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'わが霊魂わがうちにきえうせんとするときも汝わがみちを識たまへり 人われをとらへんとてわがゆくみちに羂をかくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, '願くはわがみぎの手に目をそそぎて見たまへ 一人だに我をしるものなし われには避所なくまたわが霊魂をかへりみる人なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'ヱホバよわれ汝をよばふ 我いへらく汝はわがさけどころ有生の地にてわがうべき分なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'ねがはくはわが號呼にみこころをとめたまへ われいたく卑くせられたればなり 我をせむる者より助けいだしたまへ 彼等はわれにまさりて強ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, '願くはわがたましひを囹圄よりいだし われに聖名を感謝せしめたまへ なんぢ豊かにわれを待ひたまふべければ 義者われをめぐらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'ダビデのうた ヱホバよねがはくはわが祈をきき わが懇求にみみをかたぶけたまへ なんぢの眞實なんぢの公義をもて我にこたへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, '汝のしもべの審判にかかつらひたまふなかれ そはいけるもの一人だにみまへに義とせらるるはなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, '仇はわがたましひを迫めわが生命を地にうちすて 死てひさしく世を經たるもののごとく我をくらき所にすまはせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, '又わがたましひはわが衷にきえうせんとし わが心はわがうちに曠さびれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'われはいにしへの日をおもひいで 汝のおこなひたまひし一切のことを考へ なんぢの手のみわざをおもふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'われ汝にむかひてわが手をのべ わがたましひは燥きおとろへたる地のごとく汝をしたへり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'ヱホバよ速かにわれにこたへたまへ わが霊魂はおとろふ われに聖顔をかくしたまふなかれ おそらくはわれ穴にくだるもののごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, '朝になんぢの仁慈をきかしめたまへ われ汝によりたのめばなり わが歩むべき途をしらせたまへ われわが霊魂をなんぢに擧ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'ヱホバよねがはくは我をわが仇よりたすけ出したまへ われ匿れんとして汝にはしりゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, '汝はわが神なり われに聖旨をおこなふことををしへたまへ 惠ふかき聖霊をもて我をたひらかなる國にみちびきたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'ヱホバよねがはくは聖名のために我をいかし なんぢの義によりてわがたましひを患難よりいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, '又なんぢの仁慈によりてわが仇をたち 霊魂をくるしむる者をことごとく滅したまへ そは我なんぢの僕なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'ダビデのうた 戰することをわが手にをしへ 闘ふことをわが指にをしへたまふ わが磐ヱホバはほむべきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'ヱホバはわが仁慈わが城なり わがたかき櫓われをすくひたまふ者なり わが盾わが依賴むものなり ヱホバはわが民をわれにしたがはせたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'ヱホバよ人はいかなる者なれば之をしり 人の子はいかなる者なれば之をみこころに記たまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, '人は氣息にことならず その存らふる日はすぎゆく影にひとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'ヱホバよねがはくはなんぢの天をたれてくだり 手を山につけて煙をたたしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, '電光をうちいだして彼等をちらし なんぢの矢をはなちてかれらを敗りたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, '上より手をのべ我をすくひて 大水より外人の手よりたすけいだしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'かれらの口はむなしき言をいひ その右の手はいつはりのみぎの手なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, '神よわれ汝にむかひて新らしき歌をうたひ 十絃の琴にあはせて汝をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'なんぢは王たちに救をあたへ 僕ダビデをわざはひの劍よりすくひたまふ神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'ねがはくは我をすくひて外人の手よりたすけいだしたまへ かれらの口はむなしき言をいひ その右の手はいつはりのみぎの手なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'われらの男子はとしわかきとき育ちたる草木のごとくわれらの女子は宮のふりにならひて刻みいだしし隅の石のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'われらの倉はみちたらひてさまざまのものをそなへ われらの羊は野にて千萬の子をうみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'われらの牡牛はよく物をおひ われらの衢にはせめいることなく亦おしいづることなく叫ぶこともなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'かかる状の民はさいはひなり ヱホバをおのが神とする民はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'ダビデの讃美のうた わがかみ王よわれ汝をあがめ 世かぎりなく聖名をほめまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'われ日ごとに汝をほめ世々かぎりなく聖名をはめたたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'ヱホバは大にましませば最もほむべきかな その大なることは尋ねしることかたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'この代はかの代にむかひてなんぢの事跡をほめたたへ なんぢの大能のはたらきを宣つたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'われ汝のほまれの榮光ある稜威となんぢの奇しきみわざとを深くおもはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, '人はなんぢのおそるべき動作のいきほひをかたり 我はなんぢの大なることを宣つたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'かれらはなんぢの大なる惠の跡をいひいで なんぢの義をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'ヱホバは惠ふかく憐憫みち また怒りたまふことおそく憐憫おほいなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'ヱホバはよろづの者にめぐみあり そのふかき憐憫はみわざの上にあまねし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'ヱホバよ汝のすべての事跡はなんぢに感謝し なんぢの聖徒はなんぢをほめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'かれらは御國のえいくわうをかたり汝のみちからを宣つたへて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'その大能のはたらきとそのみくにの榮光あるみいづとを人の子輩にしらすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'なんぢの國はとこしへの國なり なんぢの政治はよろづ代にたゆることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'ヱホバはすべて倒れんとする者をささへ かがむものを直くたたしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'よろづのものの目はなんぢを待 なんぢは時にしたがひてかれらに糧をあたへ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'なんぢ手をひらきてもろもろの生るものの願望をあかしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'ヱホバはそのすべての途にただしく そのすべての作爲にめぐみふかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'すべてヱホバをよぶもの 誠をもて之をよぶものに ヱホバは近くましますなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'ヱホバは己をおそるるものの願望をみちたらしめ その號呼をききて之をすくひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'ヱホバはおのれを愛しむものをすべて守りたまへど 惡者をことごとく滅したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'わが口はヱホバの頌美をかたり よろづの民は世々かぎりなくそのきよき名をほめまつるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'ヱホバを讃稱へよ わがたましひよヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'われ生るかぎりはヱホバをほめたたへ わがながらふるほどはわが神をほめうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'もろもろの君によりたのむことなく 人の子によりたのむなかれ かれらに助あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'その氣息いでゆけばかれ土にかへる その日かれがもろもろの企圖はほろびん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'ヤコブの神をおのが助としその望をおのが神ヱホバにおくものは福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, '此はあめつちと海とそのなかなるあらゆるものを造り とこしへに眞實をまもり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, '虐げらるるもののために審判をおこなひ 饑ゑたるものに食物をあたへたまふ神なり ヱホバはとらはれたる人をときはなちたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'ヱホバはめしひの目をひらき ヱホバは屈者をなほくたたせ ヱホバは義しきものを愛しみたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'ヱホバは他邦人をまもり 孤子と寡婦とをささへたまふ されど惡きものの徑はくつがへしたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'ヱホバはとこしへに統治めたまはん シオンよなんぢの神はよろづ代まで統治めたまはん ヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'ヱホバをほめたたへよ われらの神をほめうたふは善ことなり樂しきことなり 稱へまつるはよろしきに適へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'ヱホバはヱルサレムをきづきイスラエルのさすらへる者をあつめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'ヱホバは心のくだけたるものを醫しその傷をつつみたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'ヱホバはもろもろの星の數をかぞへてすべてこれに名をあたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'われらの主はおほいなりその能力もまた大なりその智慧はきはまりなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'ヱホバは柔和なるものをささへ惡きものを地にひきおとし給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'ヱホバに感謝してうたへ琴にあはせてわれらの神をほめうたヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'ヱホバは雲をもて天をおほひ地のために雨をそなへ もろもろの山に草をはえしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'くひものを獣にあたへ並なく小鴉にあたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'ヱホバは馬のちからを喜びたまはず 人の足をよみしたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'ヱホバはおのれを畏るるものと おのれの憐憫をのぞむものとを好したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'ヱルサレムよヱホバをほめたたへよ シオンよなんぢの神をほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'ヱホバはなんぢの門の關木をかたうし 汝のうちなる子輩をさきはひ給ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'ヱホバは汝のすべての境にやはらぎをあたへ いと嘉麥をもて汝をあかしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'ヱホバはそのいましめを地にくだしたまふ その聖言はいとすみやかにはしる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'ヱホバは雪をひつじの毛のごとくふらせ霜を灰のごとくにまきたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'ヱホバは氷をつちくれのごとくに擲ちたまふ たれかその寒冷にたふることをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'ヱホバ聖言をくだしてこれを消し その風をふかしめたまへばもろもろの水はながる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'ヱホバはそのみことばをヤコブに示し そのもろもろの律法とその審判とをイスラエルにしめしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'ヱホバはいづれの國をも如此あしらひたまひしにあらず ヱホバのもろもろの審判をかれらはしらざるなり ヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'ヱホバをほめたたへよ もろもろの天よりヱホバをほめたたへよ もろもろの高所にてヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'その天使よみなヱホバをほめたたへよ その萬軍よみなヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, '日よ月よヱホバをほめたたへよ ひかりの星よみなヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'もろもろの天のてんよ 天のうへなる水よ ヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'これらはみなヱホバの聖名をほめたたふべし そはヱホバ命じたまひたればかれらは造られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'ヱホバまた此等をいやとほながに立たまひたり 又すぎうすまじき詔命をくだしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, '龍よ すべての淵よ地よりヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, '火よ霰よ雪よ霧よみことばにしたがふ狂風よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'もろもろの山もろもろのをか實をむすぶ樹すべての香柏よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, '獣もろもろの牲畜はふもの翼ある鳥よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, '地の王たち もろもろのたみ 地の諸侯よ 地のもろもろの審士よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, '少きをのこ 若きをみな 老たる人 をさなきものよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'みなヱホバの聖名をほめたたふべし その聖名はたかくして類なく そのえいくわうは地よりも天よりもうへにあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'ヱホバはその民のために一つの角をあげたまへり こはそもろもろの聖徒のほまれ ヱホバにちかき民なるイスラエルの子輩のほまれなり ヱホバを讃稱へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'ヱホバをほめたたへよ ヱホバに對ひてあたらしき歌をうたへ 聖徒のつどひにてヱホバの頌美をうたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'イスラエルはおのれを造りたまひしものをよろこび シオンの子輩は己が王のゆゑによりて樂しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'かれらをどりつつその聖名をほめたたへ 琴鼓にてヱホバをほめうたべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'ヱホバはおのが民をよろこび 救にて柔和なるものを美しくしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, '聖徒はえいくわうの故によりてよろこび その寝牀にてよろこびうたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'その口に神をほむるうたあり その手にもろはの劍あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'こはもろもろの國に仇をかへし もろもろの民をつみなひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'かれらの王たちを鏈にてかれらの貴人をくろかねの械にていましめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, '録したる審判をかれらに行ふべきためなり 斯るほまれはそのもろもろの聖徒にあり ヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'ヱホバをほめたたへよ その聖所にて神をほめたたへよ その能力のあらはるる穹蒼にて神をほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'その大能のはたらきのゆゑをもて神をほめたたへよ その秀ておほいなることの故によりてヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'ラッパの聲をもて神をほめたたへよ 筝と琴とをもて神をほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'つづみと蹈舞とをもて神をほめたたへよ 絃簫をもて神をほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, '音のたかき鐃鈸をもて神をほめたたへよ なりひびく鐃鈸をもて神をほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, '氣息あるものは皆ヤハをほめたたふべし なんぢらヱホバをほめたたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'ダビデの子イスラエルの王ソロモンの箴言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'こは人に智慧と訓誨とをしらしめ哲言を暁らせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'さとき訓と公義と公平と正直とをえしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, '拙者にさとりを與へ少者に知識と謹愼とを得させん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, '智慧ある者は之を聞て學にすすみ 哲者は智略をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, '人これによりて箴言と譬喩と智慧ある者の言とその隠語とを悟らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'ヱホバを畏るるは知識の本なり 愚なる者は智慧と訓誨とを軽んず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, '我が子よ汝の父の敎をきけ 汝の母の法を棄ることなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'これ汝の首の美しき冠となり 汝の項の妝飾とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'わが子よ惡者なんぢ誘ふとも從ふことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, '彼等なんぢにむかひて請ふ われらと偕にきたれ 我儕まちぶせして人の血を流し 無辜ものを故なきに伏てねらひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, '陰府のごとく彼等を活たるままにて呑み 壯健なる者を墳に下る者のごとくになさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'われら各樣のたふとき財貨をえ 奪ひ取たる物をもて我儕の家に盈さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, '汝われらと偕に籤をひけ 我儕とともに一の金嚢を持べしと云とも');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, '我が子よ彼等とともに途を歩むことなかれ 汝の足を禁めてその路にゆくこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'そは彼らの足は惡に趨り 血を流さんとて急げばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, '(すべて鳥の目の前にて羅を張は徒勞なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, '彼等はおのれの血のために埋伏し おのれの命をふしてねらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, '凡て利を貧る者の途はかくの如し 是その持主をして生命をうしなはしむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, '智慧外に呼はり衢に其聲をあげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, '熱閙しき所にさけび 城市の門の口邑の中にその言をのべていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'なんぢら拙者のつたなきを愛し 嘲笑者のあざけりを樂しみ 愚なる者の知識を惡むは幾時までぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'わが督斥にしたがひて心を改めよ 視よわれ我が霊を汝らにそそぎ 我が言をなんぢらに示さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'われ呼たれども汝らこたへず 手を伸たれども顧る者なく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'かへつて我がすべての勸告をすて我が督斥を受ざりしに由り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'われ汝らが禍災にあふとき之を笑ひ 汝らの恐懼きたらんとき嘲るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'これは汝らのおそれ颶風の如くきたり 汝らのほろび颺風の如くきたり 艱難とかなしみと汝らにきたらん時なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'そのとき彼等われを呼ばん 然れどわれ應へじ 只管に我を求めん されど我に遇じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'かれら知識を憎み又ヱホバを畏るることを悦ばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'わが勸に從はず凡て我督斥をいやしめたるによりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, '己の途の果を食ひおのれの策略に飽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, '拙者の違逆はおのれを殺し 愚なる者の幸福はおのれを滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'されど我に聞ものは平穩に住ひかつ禍害にあふ恐怖なくして安然ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, '我が子よ汝もし我が言をうけ 我が誡命を汝のこころに蔵め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, '斯て汝の耳を智慧に傾け汝の心をさとりにむけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'もし知識を呼求め聰明をえんと汝の聲をあげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, '銀の如くこれを探り 秘れたる寳の如くこれを尋ねば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, '汝ヱホバを畏るることを暁り 神を知ることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'そはヱホバは智慧をあたへ 知識と聰明とその口より出づればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'かれは義人のために聰明をたくはへ 直く行む者の盾となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'そは公平の途をたもち その聖徒の途すぢを守りたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, '斯て汝はつひに公義と公平と正直と一切の善道を暁らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'すなはち智慧なんぢの心にいり 知識なんぢの霊魂に樂しからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, '謹愼なんぢを守り 聰明なんぢをたもちて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, '惡き途よりすくひ虚偽をかたる者より救はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, '彼等は直き途をはなれて幽暗き路に行み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, '惡を行ふを樂しみ 惡者のいつはりを悦び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'その途はまがり その行爲は邪曲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, '聰明はまた汝を妓女より救ひ 言をもて諂ふ婦より救はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, '彼はわかき時の侶をすて その神に契約せしことを忘るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'その家は死に下り その途は陰府に赴く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, '凡てかれにゆく者は歸らず また生命の途に達らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, '聰明汝をたもちてよき途に行ませ 義人の途を守らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'そは義人は地にながらへをり 完全者は地に止らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'されど惡者は地より亡され悖逆者は地より抜さらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, '我が子よわが法を忘るるなかれ 汝の心にわが誡命をまもれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'さらば此事は汝の日をながくし生命の年を延べ平康をなんぢに加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, '仁慈と眞實とを汝より離すことなかれ 之を汝の項にむすび これを汝の心の碑にしるせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'さらばなんぢ神と人との前に恩寵と好名とを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, '汝こころを盡してヱホバに倚賴め おのれの聰明に倚ることなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, '汝すべての途にてヱホバをみとめよ さらばなんぢの途を直くしたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, '自から看て聰明とする勿れ ヱホバを畏れて惡を離れよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'これ汝の身に良薬となり汝の骨に滋潤とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, '汝の貨財と汝がすべての產物の初生をもてヱホバをあがめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'さらば汝の倉庫はみちて餘り 汝の酒醡は新しき酒にて溢れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, '我子よ汝ヱホバの懲治をかろんずる勿れ その譴責を受くるを厭ふこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'それヱホバはその愛する者をいましめたまふ あたかも父のその愛する子を譴むるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, '智慧を求め得る人および聰明をうる人は福なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'そは智慧を獲るは銀を獲るに愈りその利は精金よりも善ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, '智慧は眞珠よりも尊し 汝の凡ての財貨も之と比ぶるに足らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, '其右の手には長壽あり その左の手には富と尊貴とあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'その途は樂しき途なり その徑すぢは悉く平康し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'これは執る者には生命の樹なり これ持ものは福なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'ヱホバ智慧をもて地をさだめ 聰明をもて天を置たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'その知識によりて海洋はわきいで 雲は露をそそぐなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, '我が子よこれらを汝の眼より離す勿れ 聰明と謹愼とを守れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, '然ばこれは汝の霊魂の生命となり汝の項の妝飾とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'かくて汝やすらかに汝の途をゆかん 又なんぢの足つまづかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'なんぢ臥とき怖るるところあらず 臥ときは酣く睡らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'なんぢ猝然なる恐懼をおそれず 惡者の滅亡きたる時も之を怖るまじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'そはヱホバは汝の倚賴むものにして汝の足を守りてとらはれしめたまはざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, '汝の手善をなす力あらば之を爲すべき者に爲さざること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'もし汝に物あらば汝の鄰に向ひ 去て復來れ明日われ汝に予へんといふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, '汝の鄰なんぢの傍に安らかに居らば之にむかひて惡を謀ること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, '人もし汝に惡を爲さずば故なく之と爭ふこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, '暴虐人を羨むことなく そのすべての途を好とすることなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'そは邪曲なる者はヱホバに惡まるればなり されど義者はその親き者とせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'ヱホバの呪詛は惡者の家にあり されど義者の室はかれにめぐまる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, '彼は嘲笑者をあざけり 謙る者に恩惠をあたへたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, '智者は尊榮をえ 愚なる者は羞辱之をとりさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, '小子等よ父の訓をきけ 聰明を知んために耳をかたむけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'われ善敎を汝らにさづく わが律を棄つることなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'われも我が父には子にして 我が母の目には獨の愛子なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, '父われを敎へていへらく我が言を汝の心にとどめ わが誡命をまもれ 然らば生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, '智慧をえ聰明をえよ これを忘るるなかれ また我が口の言に身をそむくるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, '智慧をすつることなかれ彼なんぢを守らん 彼を愛せよ彼なんぢを保たん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, '智慧は第一なるものなり 智慧をえよ 凡て汝の得たる物をもて聰明をえよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, '彼を尊べ さらば彼なんぢを高く擧げん もし彼を懐かば彼汝を尊榮からしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'かれ美しき飾を汝の首に置き 榮の冠弁を汝に予へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, '我が子よきけ 我が言を納れよ さらば汝の生命の年おほからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'われ智慧の道を汝に敎へ義しき徑筋に汝を導けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, '歩くとき汝の歩は艱まず 趨るときも躓かじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, '堅く訓誨を執りて離すこと勿れ これを守れ これは汝の生命なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, '邪曲なる者の途に入ることなかれ 惡者の路をあやむこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'これを避よ 過ること勿れ 離れて去れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'そは彼等は惡を爲さざれば睡らず 人を躓かせざればいねず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, '不義のパンを食ひ暴虐の酒を飮めばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, '義者の途は旭光のごとし いよいよ光輝をまして晝の正午にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, '惡者の途は幽冥のごとし 彼らはその蹟くもののなになるを知ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'わが子よ我が言をきけ 我が語るところに汝の耳を傾けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, '之を汝の目より離すこと勿れ 汝の心のうちに守れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, '是は之を得るものの生命にしてまたその全體の良薬なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'すべての操守べき物よりもまさりて汝の心を守れ そは生命の流これより出ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, '虚偽の口を汝より棄さり 惡き口唇を汝より遠くはなせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, '汝の目は正く視 汝の眼瞼は汝の前を眞直に視るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, '汝の足の徑をかんがへはかり 汝のすべての道を直くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, '右にも左にも偏ること勿れ汝の足を惡より離れしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, '我が子よわが智慧をきけ 汝の耳をわが聰明に傾け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'しかしてなんぢ謹愼を守り汝の口唇に知識を保つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, '娼妓の口唇は蜜を滴らし 其口は脂よりも滑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'されど其終は茵蔯の如くに苦く兩刃の劍の如くに利し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'その足は死に下り その歩は陰府に趣く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, '彼は生命の途に入らず 其徑はさだかならねども自ら之を知ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, '小子等よいま我にきけ 我が口の言を棄つる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, '汝の途を彼より遠く離れしめよ 其家の門に近づくことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, '恐くは汝の榮を他人にわたし 汝の年を憐憫なき者にわたすにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, '恐くは他人なんぢの資財によりて盈され 汝の勞苦は他人の家にあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, '終にいたりて汝の身なんぢの體亡ぶる時なんぢ泣悲みていはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'われ敎をいとひ 心に譴責をかろんじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, '我が師の聲をきかず 我を敎ふる者に耳を傾けず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'あつまりの中會衆のうちにてほとんど諸の惡に陷れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, '汝おのれの水溜より水を飮み おのれの泉より流るる水をのめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, '汝の流をほかに溢れしめ 汝の河の水を衢に流れしむべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'これを自己に歸せしめ 他人をして汝と偕にこに與らしむること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, '汝の泉に福祉を受しめ 汝の少き時の妻を樂しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, '彼は愛しき麀のごとく美しき鹿の如し その乳房をもて常にたれりとし その愛をもて常によろこべ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, '我子よ何なればあそびめをたのしみ 淫婦の胸を懐くや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'それ人の途はヱホバの目の前にあり 彼はすべて其行爲を量りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, '惡者はおのれの愆にとらへられ その罪の繩に繋る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, '彼は訓誨なきによりて死 その多くの愚なることに由りて亡ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, '我子よ汝もし朋友のために保證をなし 他人のために汝の手を拍ば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, '汝その口の言によりてわなにかかり その口の言によりてとらへらるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, '我子よ汝友の手に陷りしならば斯して自ら救へ すなはち往て自ら謙だり只管なんぢの友に求め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, '汝の目をして睡らしむることなく 汝の眼瞼をして閉しむること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'かりうどの手より鹿ののがるるごとく 鳥とる者の手より鳥ののがるる如くして みづからを救へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, '惰者よ蟻にゆき其爲すところを觀て智慧をえよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, '蟻は首領なく有司なく君主なけれども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, '夏のうちに食をそなへ 収穫のときに糧を斂む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, '惰者よ汝いづれの時まで臥息むや いづれの時まで睡りて起ざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'しばらく臥ししばらく睡り 手を叉きてまた片時やすむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'さらば汝の貧窮は盗人の如くきたり汝の缺乏は兵士の如くきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, '邪曲なる人あしき人は虚偽の言をもて事を行ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, '彼は眼をもて眴せし 脚をもてしらせ 指をもて示す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'その心に虚偽をたもち 常に惡をはかり 爭端を起す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'この故にその禍害にはかに來り 援助なくして立刻に敗らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'ヱホバの憎みたまふもの六あり 否その心に嫌ひたまふもの七あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, '即ち驕る目いつはりをいふ舌 つみなき人の血を流す手');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, '惡き謀計をめぐらす心 すみやかに惡に趨る足');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, '詐僞をのぶる證人 および兄弟のうちに爭端をおこす者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, '我子よ汝の父の誡命を守り 汝の母の法を棄る勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, '常にこれを汝の心にむす び之をなんぢの頸に佩よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'これは汝のゆくとき汝をみちびき 汝の寝るとき汝をまもり 汝の寤るとき汝とかたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'それ誡命は燈火なり 法は光なり 敎訓の懲治は生命の道なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'これは汝をまもりて惡き婦よりまぬかれしめ 汝をたもちて淫婦の舌の諂媚にまどはされざらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'その艶美を心に戀ふことなかれ その眼瞼に捕へらるること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'それ娼妓のために人はただ僅に一撮の糧をのこすのみにいたる 又淫婦は人の尊き生命を求むるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, '人は火を懐に抱きてその衣を焚れざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, '人は熱火を踏て其足を焚れざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'その隣の妻と姦淫をおこなふ者もかくあるべし 凡て之に捫る者は罪なしとせられず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, '竊む者もし饑しときに其饑を充さん爲にぬすめるならば人これを藐ぜじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'もし捕へられなばその七倍を償ひ其家の所有をことごとく出さざるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, '婦と姦淫をおこなふ者は智慧なきなり 之を行ふ者はおのれの霊魂を亡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, '傷と陵辱とをうけて其恥を雪ぐこと能はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, '妒忌その夫をして忿怒をもやさしむればその怨を報ゆるときかならず寛さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'いかなる贖物をも顧みず 衆多の饋物をなすともやはらがざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, '我子よわが言をまもり我が誡命を汝の心にたくはへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, '我が誡命をまもりで生命をえよ 我法を守ること汝の眸子を守るが如くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'これを汝の指にむすび これを汝の心の碑に銘せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'なんぢ智慧にむかひて汝はわが姉妹なりといひ 明理にむかひて汝はわが友なりといへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'さらば汝をまもりて淫婦にまよはざらしめ 言をもて媚る娼妓にとほざからしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'われ我室の牖により檑子よりのぞきて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, '拙き者のうち幼弱者のうちに一人の智慧なき者あるを觀たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, '彼衢をすぎ婦の門にちかづき其家の路にゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, '黄昏に半宵に夜半に黑暗の中にあるけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, '時に娼妓の衣を着たる狡らなる婦かれにあふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'この婦は譁しくしてつつしみなく 其足は家に止らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'あるときは衢にあり 或時はひろばにあり すみずみにたちて人をうかがふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'この婦かれをひきて接吻し恥しらぬ面をもていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'われ酬恩祭を献げ今日すでにわが誓願を償せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'これによりて我なんぢを迎へんとていで 汝の面をたづねて汝に逢へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'わが榻には美しき褥およびエジプトの文枲をしき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, '沒藥蘆薈桂皮をもて我が榻にそそげり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, '來れわれら詰朝まで情をつくし愛をかよはして相なぐさめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'そは夫は家にあらず遠く旅立して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, '手に金嚢をとれり 望月ならでは家に歸らじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, '多の婉言をもて惑し口唇の諂媚をもて誘へば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'わかき人ただちにこれに隨へり あだかも牛の宰地にゆくが如く 愚なる者の桎梏をかけらるる爲にゆくが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, '遂には矢その肝を刺さん 鳥の速かに羅にいりてその生命を喪ふに至るを知ざるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, '小子等よいま我にきけ 我が口の言に耳を傾けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'なんぢの心を淫婦の道にかたむくること勿れ またこれが徑に迷ふこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'そは彼は多の人を傷つけて仆せり 彼に殺されたる者ぞ多かる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'その家は陰府の途にして死の室に下りゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, '智慧は呼はらざるか 聰明は聲を出さざるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, '彼は路のほとりの高處また街衢のなかに立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, '邑のもろもろの門 邑の口および門々の入口にて呼はりいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '人々よわれ汝をよび 我が聲をもて人の子等をよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, '拙き者よなんぢら聰明に明かなれ 愚なる者よ汝ら明かなる心を得よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, '汝きけ われ善事をかたらん わが口唇をひらきて正事をいださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, '我が口は眞實を述べ わが口唇はあしき事を憎むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'わが口の言はみな義し そのうちに虚偽と奸邪とあることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, '是みな智者の明かにするところ 知識をうる者の正とするところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'なんぢら銀をうくるよりは我が敎をうけよ 精金よりもむしろ知識をえよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'それ智慧は眞珠に愈れり 凡の寳も之に比ぶるに足らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'われ智慧は聰明をすみかとし 知識と謹愼にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'ヱホバを畏るるとは惡を憎むことなり 我は傲慢と驕奢 惡道と虚偽の口とを憎む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, '謀略と聰明は我にあり 我は了知なり 我は能力あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, '我に由て王者は政をなし 君たる者は義しき律をたて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, '我によりて主たる者および牧伯たちなど凡て地の審判人は世ををさむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'われを愛する者は我これを愛す 我を切に求むるものは我に遇ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, '富と榮とは我にあり 貴き寳と公義とも亦然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'わが果は金よりも精金よりも愈り わが利は精銀よりもよし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, '我は義しき道にあゆみ 公平なる路徑のなかを行む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'これ我を愛する者に貨財をえさせ 又その庫を充しめん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'ヱホバいにしへ其御わざをなしそめたまへる前に その道の始として我をつくりたまひき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, '永遠より元始より地の有ざりし前より我は立られ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'いまだ海洋あらず いまだ大なるみづの泉あらざりしとき我すでに生れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, '山いまださだめられず 陵いまだ有ざりし前に我すでに生れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, '即ち神いまだ地をも野をも地の塵の根元をも造り給はざりし時なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'かれ天をつくり海の面に穹蒼を張たまひしとき我かしこに在りき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, '彼うへに雲氣をかたく定め 淵の泉をつよくならしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, '海にその限界をたて 水をしてその岸を踰えざらしめ また地の基を定めたまへるとき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, '我はその傍にありて創造者となり 日々に欣び恒にその前に樂み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'その地にて樂み又世の人を喜べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'されば小子等よ いま我にきけ わが道をまもる者は福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, '敎をききて智慧をえよ 之を棄ることなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, '凡そ我にきき 日々わが門の傍にまち わが戸口の柱のわきにたつ人は福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'そは我を得る者は生命をえ ヱホバより恩寵を獲ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, '我を失ふものは自己の生命を害ふ すべて我を惡むものは死を愛するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, '智慧はその家を建て その七の柱を砍成し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'その畜を宰り その酒を混和せ その筵をそなへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'その婢女をつかはして邑の高處に呼はりいはしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '拙者よここに來れと また智慧なき者にいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '汝等きたりて我が糧を食ひ わがまぜあはせたる酒をのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, '拙劣をすてて生命をえ 聰明のみちを行め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, '嘲笑者をいましむる者は恥を己にえ 惡人を責むる者は疵を己にえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, '嘲笑者を責むることなかれ 恐くは彼なんぢを惡まん 智慧ある者をせめよ 彼なんぢを愛せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, '智慧ある者に授けよ 彼はますます智慧をえん 義者を敎へよ 彼は知識に進まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'ヱホバを畏るることは智慧の根本なり 聖者を知るは聰明なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, '我により汝の日は多くせられ 汝のいのちの年は増べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, '汝もし智慧あらば自己のために智慧あるなり 汝もし嘲らば汝ひとり之を負ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, '愚なる婦は嘩しく且つたなくして何事をも知らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'その家の門に坐し邑のたかき處にある座にすわり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, '道をますぐに過る往來の人を招きていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '拙者よここに來れと また智慧なき人にむかひては之にいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '竊みたる水は甘く密かに食ふ糧は美味ありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, '彼處にある者は死し者その客は陰府のふかき處にあることを是等の人は知らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'ソロモンの箴言 智慧ある子は父を欣ばす 愚なる子は母の憂なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, '不義の財は益なし されど正義は救ひて死を脱かれしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'ヱホバは義者の霊魂を餓ゑしめず 惡者にその欲するところを得ざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, '手をものうくして動くものは貧くなり 勤めはたらく者の手は富を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, '夏のうちに斂むる者は智き子なり 収穫の時にねむる者は辱をきたす子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, '義者の首には福祉きたり 惡者の口は強暴を掩ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, '義者の名は讃られ 惡者の名は腐る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, '心の智き者は誡命を受く されど口の頑愚なる者は滅さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, '直くあゆむ者はそのあゆむこと安し されどその途を曲ぐる者は知らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, '眼をもて眴せする者は憂をおこし 口の頑愚なる者は亡さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, '義者の口は生命の泉なり 惡者の口は強暴を掩ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, '怨恨は爭端をおこし 愛はすべての愆を掩ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, '哲者のくちびるには智慧あり 智慧なき者の背のためには鞭あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, '智慧ある者は知識をたくはふ 愚かなる者の口はいまにも滅亡をきたらす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, '富者の資財はその堅き城なり 貧者のともしきはそのほろびなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, '義者が動作は生命にいたり 惡者の利得は罪にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, '敎をまもる者は生命の道にあり懲戒をすつる者はあやまりにおちいる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, '怨をかくす者には虚偽のくちびるあり 誹謗をいだす者は愚かなる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, '言おほけれぼ罪なきことあたはず その口唇を禁むるものは智慧あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, '義者の舌は精銀のごとし 惡者の心は値すくなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, '義者の口唇はおほくの人をやしなひ 愚なる者は智慧なきに由て死ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'ヱホバの祝福は人を富す 人の勞苦はこれに加ふるところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, '愚かなる者は惡をなすを戯れごとのごとくす 智慧のさとかる人にとりても是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, '惡者の怖るるところは自己にきたり 義者のねがふところはあたへらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, '狂風のすぐるとき惡者は無に歸せん 義者は窮なくたもつ基のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, '惰る者のこれを遣すものに於るは酢の歯に於るが如く煙の目に於るが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'ヱホバを畏るることは人の日を多くす されど惡者の年はちぢめらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, '義者の望は喜悦にいたり惡者の望は絶べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'ヱホバの途は直者の城となり 惡を行ふものの滅亡となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, '義者は何時までも動かされず 惡者は地に住むことを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, '義者の口は智慧をいだすなり 虚偽の舌は抜るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, '義者のくちびるは喜ばるべきことをわきまへ 惡者の口はいつはりを語る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'いつはりの權衝はヱホバに惡まれ 義しき法馬は彼に欣ばる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, '驕傲きたれば辱も亦きたる謙だる者には智慧あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, '直者の端荘は己を導き悖逆者の邪曲は己を亡す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, '寳は震怒の日に益なし されど正義は救ふて死をまぬかれしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, '完全者はその正義によりてその途を直くせられ 惡者はその惡によりて跌るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, '直者はその正義によりて救はれ 悖逆者は自己の惡によりて執へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, '惡人は死るときにその望たえ 不義なる者の望もまた絶べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, '義者は艱難より救はれ 惡者はこれに代る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, '邪曲なる者は口をもてその鄰を亡す されど義しき者はその知識によりて救はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, '義しきもの幸福を受ればその城邑に歓喜あり 惡きもの亡さるれば歓喜の聲おこる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, '城邑は直者の祝ふに倚て高く擧られ 惡者の口によりて亡さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'その鄰を侮る者は智慧なし 聰明人はその口を噤む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, '往て人の是非をいふ者は密事を洩し 心の忠信なる者は事を隱す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'はかりごとなければ民たふれ 議士多ければ平安なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, '他人のために保證をなす者は苦難をうけ 保證を嫌ふ者は平安なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, '柔順なる婦は榮譽をえ 強き男子は資財を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, '慈悲ある者は己の霊魂に益をくはへ 殘忍者はおのれの身を擾はす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, '惡者の獲る報はむなしく 義を播くものの得る報賞は確し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, '堅く義をたもつ者は生命にいたり 惡を追もとむる者はおのれの死をまねく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, '心の戻れる者はヱホバに憎まれ 直く道を歩む者は彼に悦ばる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, '手に手をあはするとも惡人は罪をまぬかれず 義人の苗裔は救を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, '美しき婦のつつしみなきは金の環の豕の鼻にあるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, '義人のねがふところは凡て福祉にいたり 惡人ののぞむところは震怒にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'ほどこし散して反りて増ものあり 與ふべきを吝みてかへりて貧しきにいたる者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, '施與を好むものは肥え 人を潤ほす者はまた利潤をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, '穀物を蔵めて糶ざる者は民に詛はる 然れど售る者の首には祝福あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, '善をもとむる者は恩惠をえん 惡をもとむる者には惡き事きたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'おのれの富を恃むものは仆れん されど義者は樹の靑葉のごとくさかえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'おのれの家をくるしむるものは風をえて所有とせん 愚なる者は心の智きものの僕とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, '義人の果は生命の樹なり 智慧ある者は人を捕ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'みよ義人すらも世にありて報をうくべし况て惡人と罪人とをや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, '訓誨を愛する者は知識を愛す 懲戒を惡むものは畜のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, '善人はヱホバの恩寵をうけ 惡き謀略を設くる人はヱホバに罰せらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, '人は惡をもて堅く立ことあたはず 義人の根は動くことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, '賢き婦はその夫の冠弁なり 辱をきたらする婦は夫をしてその骨に腐あるが如くならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, '義者のおもひは直し 惡者の計るところは虚偽なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, '惡者の言は人の血を流さんとて伺ふ されど直者の口は人を救ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, '惡者はたふされて無ものとならん されど義者の家は立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, '人はその聰明にしたがひて譽られ 心の悖れる者は藐めらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, '卑賤してしもべある者は自らたかぶりて食に乏き者に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, '義者はその畜の生命を顧みる されど惡者は殘忍をもてその憐憫とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'おのれの田地を耕すものは食にあく 放蕩なる人にしたがふ者は智慧なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, '惡者はあしき人の獲たる物をうらやみ 義者の根は芽をいだす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, '惡者はくちびるの愆によりて罟に陷る されど義者は患難の中よりまぬかれいでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, '人はその口の徳によりて福祉に飽ん 人の手の行爲はその人の身にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, '愚なる者はみづからその道を見て正しとす されど智慧ある者はすすめを容る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, '愚なる者はただちに怒をあらはし 智きものは恥をつつむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, '眞實をいふものは正義を述べ いつはりの證人は虚偽をいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, '妄りに言をいだし劍をもて刺がごとくする者あり されど智慧ある者の舌は人をいやす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, '眞理をいふ口唇は何時までも存つ されど虚偽をいふ舌はただ瞬息のあひだのみなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, '惡事をはかる者の心には欺詐あり 和平を謀る者には歓喜あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, '義者には何の禍害も來らず 惡者はわざはひをもて充さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'いつはりの口唇はヱホバに憎まれ 眞實をおこなふ者は彼に悦ばる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, '賢人は知識をかくす されど愚なる者のこころは愚なる事を述ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, '勤めはたらく者の手は人ををさむるにいたり惰者は人に服ふるにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'うれひ人の心にあれば之を屈ます されど善言はこれを樂します');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, '義者はその友に道を示す されど惡者は自ら途にまよふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, '惰者はおのれの猟獲たる物をも燔ず 勉めはたらくことは人の貴とき寳なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, '義しき道には生命ありその道すぢには死なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, '智慧ある子は父の敎訓をきき 戯謔者は懲治をきかず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, '人はその口の徳によりて福祉をくらひ悖逆者の霊魂は強暴をくらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'その口を守る者はその生命を守る その口唇を大きくひらく者には滅亡きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, '惰る者はこころに慕へども得ることなし 勤めはたらく者の心は豊饒なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, '義者は虚偽の言をにくみ 惡者ははぢをかうむらせ面を赤くせしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, '義は道を直くあゆむ者をまもり 惡は罪人を倒す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, '自ら富めりといひあらはして些少の所有もなき者あり 自ら貧しと稱へて資財おほき者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, '人の資財はその生命を贖ふものとなるあり 然ど貧者は威嚇をきくことあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, '義者の光は輝き惡者の燈火はけさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, '驕傲はただ爭端を生ず 勸告をきく者は智慧あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, '詭計をもて得たる資財は減る されど手をもて聚めたくはふる者はこれを増すことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, '望を得ること遅きときは心を疾しめ 願ふ所旣にとぐるときは生命の樹を得たるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, '御言をかろんずる者は亡され 誡命をおそるる者は報賞を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, '智慧ある人の敎訓はいのちの泉なり 能く人をして死の罟を脱れしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, '善にして哲きものは恩を蒙る されど悖逆者の途は艱難なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, '凡そ賢者は知識に由りて事をおこなひ 愚なる者はおのれの痴を顯す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, '惡き使者は災禍に陷る されど忠信なる使者は良薬の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, '貧乏と恥辱とは敎訓をすつる者にきたる されど譴責を守る者は尊まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, '望を得れば心に甘し 愚なる者は惡を棄つることを嫌ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, '智慧ある者と偕にあゆむものは智慧をえ 愚なる者の友となる者はあしくなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'わざはひは罪人を追ひ 義者は善報をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, '善人はその產業を子孫に遺す されど罪人の資財は義者のために蓄へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, '貧しき者の新田にはおほくの糧あり されど不義によりて亡る者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, '鞭をくはへざる者はその子を憎むなり 子を愛する者はしきりに之をいましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, '義しき者は食をえて飽く されど惡者の腹は空し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, '智慧ある婦はその家をたて 愚なる婦はおのれの手をもて之を毀つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, '直くあゆむ者はヱホバを畏れ 曲りてあゆむ者はこれを侮る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, '愚なる者の口にはその傲のために鞭笞あり 智者の口唇はおのれを守る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, '牛なければ飼蒭倉むなし牛の力によりて生產る物おほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, '忠信の證人はいつはらず 虚偽のあかしびとは謊言を吐く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, '嘲笑者は智慧を求むれどもえず 哲者は知識を得ること容易し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, '汝おろかなる者の前を離れされ つひに知識の彼にあるを見ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, '賢者の智慧はおのれの道を暁るにあり 愚なる者の痴は欺くにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'おろろかなる者は罪をかろんず されど義者の中には恩惠あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, '心の苦みは心みづから知る其よろこびには他人あづからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, '惡者の家は亡され 正直き者の幕屋はさかゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, '人のみづから見て正しとする途にしてその終はつひに死にいたる途となるものあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, '笑ふ時にも心に悲あり 歓樂の終に憂あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, '心の悖れる者はおのれの途に飽かん 善人もまた自己に飽かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, '拙者はすべての言を信ず 賢者はその行を愼む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, '智慧ある者は怖れて惡をはなれ 愚なる者はたかぶりて怖れず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, '怒り易き者は愚なることを行ひ 惡き謀計を設くる者は惡まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, '拙者は愚なる事を得て所有となし 賢者は知識をもて冠弁となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, '惡者は善者の前に俯伏し 罪ある者は義者の門に俯伏す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, '貧者はその鄰にさへも惡まる されど富者を愛する者はおほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'その鄰を藐むる者は罪あり 困苦者を憐むものは幸福あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, '惡を謀る者は自己をあやまるにあらずや 善を謀る者には憐憫と眞實とあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'すべての勤勞には利益あり されど口唇のことばは貧乏をきたらするのみなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, '智慧ある者の財寳はその冠弁となる 愚なる者のおろかはただ痴なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, '眞實の證人は人のいのちを救ふ 謊言を吐く者は偽人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'ヱホバを畏るることは堅き依賴なり その兒輩は逃避場をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'ヱホバを畏るることは生命の泉なり 人を死の罟より脱れしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, '王の榮は民の多きにあり 牧伯の衰敗は民を失ふにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, '怒を遅くする者は大なる知識あり 氣の短き者は愚なることを顯す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, '心の安穩なるは身のいのちなり 娼嫉は骨の腐なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, '貧者を虐ぐる者はその造主を侮るなり 彼をうやまふ者は貧者をあはれむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, '惡者はその惡のうちにて亡され義者はその死ぬる時にも望あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, '智慧は哲者の心にとどまり 愚なる者の衷にある事はあらはる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, '義は國を高くし罪は民を辱しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'さとき僕は王の恩を蒙ぶり 辱をきたらす者はその震怒にあふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, '柔和なる答は憤恨をとどめ厲しき言は怒を激す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, '智慧ある者の舌は知識を善きものとおもはしめ 愚なる者の口はおろかをはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'ヱホバの目は何處にもありて惡人と善人とを鑒みる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, '温柔き舌は生命の樹なり 悖れる舌は霊魂を傷ましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, '愚なる者はその父の訓をかろんず 誡命をまもる者は賢者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, '義者の家には多くの資財あり 惡者の利潤には擾累あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, '智者のくちびるは知識をひろむ 愚なる者の心は定りなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, '惡者の祭物はヱホバに憎まれ 直き人の祈は彼に悦ばる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, '惡者の道はヱホバに憎まれ 正義をもとむる者は彼に愛せらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, '道をはなるる者には嚴しき懲治あり 譴責を惡む者は死ぬべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, '陰府と沉淪とはヱホバの目の前にあり 况て人の心をや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, '嘲笑者は誡めらるることを好まず また智慧ある者に近づかず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, '心に喜樂あれば顔色よろこばし 心に憂苦あれば氣ふさぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, '哲者のこころは知識をたづね 愚なる者の口は愚をくらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, '艱難者の日はことごとく惡く 心の懽べる者は恒に酒宴にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'すこしの物を有てヱホバを畏るるは多の寳をもちて擾煩あるに愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, '蔬菜をくらひて互に愛するは肥たる牛を食ひて互に恨むるに愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, '憤ほり易きものは爭端をおこし 怒をおそくする者は爭端をとどむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, '惰者の道は棘の籬に似たり 直者の途は平坦なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, '智慧ある子は父をよろこばせ 愚なる人はその母をかろんず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, '無知なる者は愚なる事をよろこび 哲者はその途を直くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, '相議ることあらざれば謀計やぶる 議者おほければ謀計かならず成る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, '人はその口の答によりて喜樂をう 言語を出して時に適ふはいかに善らずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, '智人の途は生命の路にして上へ昇りゆく これ下にあるところの陰府を離れんが爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'ヱホバはたかぶる者の家をほろぼし 寡婦の地界をさだめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'あしき謀計はヱホバに憎まれ 温柔き言は潔白し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, '不義の利をむさぼる者はその家をわづらはせ 賄賂をにくむ者は活ながらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, '義者の心は答ふべきことを考へ 惡者の口は惡を吐く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'ヱホバは惡者に遠ざかり 義者の祈祷をききたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, '目の光は心をよろこばせ 好音信は骨をうるほす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, '生命の誡命をきくところの耳は智慧ある者の中間に駐まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, '敎をすつる者は自己の生命をかろんずるなり 懲治をきく者は聰明を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'ヱホバを畏るることは智慧の訓なり 謙遜は尊貴に先だつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, '心に謀るところは人にあり 舌の答はヱホバより出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, '人の途はおのれの目にことごとく潔しと見ゆ 惟ヱホバ霊魂をはかりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'なんぢの作爲をヱホバに託せよ さらば汝の謀るところ必ず成るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'ヱホバはすべての物をおのおのその用のために造り 惡人をも惡き日のために造りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'すべて心たかぶる者はヱホバに惡まれ 手に手をあはするとも罪をまぬかれじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, '憐憫と眞實とによりて愆は贖はる ヱホバを畏るることによりて人惡を離る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'ヱホバもし人の途を喜ばば その人の敵をも之と和がしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, '義によりて得たるところの僅少なる物は不義によりて得たる多の資財にまさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, '人は心におのれの途を考へはかる されどその歩履を導くものはヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, '王のくちびるには神のさばきあり 審判するときその口あやまる可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, '公平の權衡と天秤とはヱホバのものなり 嚢にある法馬もことごとく彼の造りしものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, '惡をおこなふことは王の憎むところなり 是その位は公義によりて堅く立ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, '義しき口唇は王によろこばる 彼等は正直をいふものを愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, '王の怒は死の使者のごとし 智慧ある人はこれをなだむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, '王の面の光には生命あり その恩寵は春雨の雲のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, '智慧を得るは金をうるよりも更に善らずや 聰明をうるは銀を得るよりも望まし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, '惡を離るるは直き人の路なり おのれの道を守るは霊魂を守るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, '驕傲は滅亡にさきだち誇る心は傾跌にさきだつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, '卑き者に交りて謙だるは驕ぶる者と偕にありて贓物をわかつに愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, '愼みて御言をおこなふ者は益をうべし ヱホバに倚賴むものは福なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, '心に智慧あれば哲者と稱へらる くちびる甘ければ人の知識をます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, '明哲はこれを持つものに生命の泉となる 愚なる者をいましむる者はおのれの痴是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, '智慧ある者の心はおのれの口ををしへ 又おのれの口唇に知識をます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'こころよき言は蜂蜜のごとくにして 霊魂に甘く骨に良薬となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, '人の自から見て正しとする途にして その終はつひに死にいたる途となるものあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, '勞をるものは飮食のために骨をる 是その口おのれに迫ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, '邪曲なる人は惡を掘る その口唇には烈しき火のごときものあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'いつはる者はあらそひを起し つけぐちする者は朋友を離れしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, '強暴人はその鄰をいざなひ 之を善らざる途にみちびく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'その目を閉て惡を謀り その口唇を蹙めて惡事を成遂ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, '白髮は榮の冠弁なり 義しき途にてこれを見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, '怒を遅くする者は勇士に愈り おのれの心を治むる者は城を攻取る者に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, '人は籤をひく されど事をさだむるは全くヱホバにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, '睦じうして一塊の乾けるパンあるは あらそひありて宰れる畜の盈たる家に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'かしこき僕は恥をきたらする子ををさめ 且その子の兄弟の中にありて產業を分ち取る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, '銀を試むる者は坩堝 金を試むる者は鑢 人の心を試むる者はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, '惡を行ふものは虚偽のくちびるにきき 虚偽をいふ者はあしき舌に耳を傾ぶく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, '貧人を嘲るものはその造主をあなどるなり 人の災禍を喜ぶものは罪をまぬかれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, '孫は老人の冠弁なり 父は子の榮なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, '勝れたる事をいふは愚なる人に適はず 况て虚偽をいふ口唇は君たる者に適はんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, '贈物はこれを受る者の目には貴き珠のごとし その向ふところにて凡て幸福を買ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, '愛を追求むる者は人の過失をおほふ 人の事を言ひふるる者は朋友をあひ離れしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, '一句の誡命の智人に徹るは百囘扑つことの愚なる人に徹るよりも深し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, '叛きもとる者はただ惡きことのみをもとむ 比故に彼にむかひて殘忍なる使者遣はさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, '愚なる者の愚妄をなすにあはんよりは寧ろ子をとられたる牝熊にあへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, '惡をもて善に報ゆる者は惡その家を離れじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, '爭端の起源は堤より水をもらすに似たり この故にあらそひの起らざる先にこれを止むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, '惡者を義とし義者を惡しとするこの二の者はヱホバに憎まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, '愚なる者はすでに心なし何ぞ智慧をかはんとて手にその價の金をもつや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, '朋友はいづれの時にも愛す 兄弟は危難の時のために生る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, '智慧なき人は手を拍てその友の前にて保證をなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, '爭端をこのむ者は罪を好み その門を高くする者は敗壞を求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, '邪曲なる心ある者はさいはひを得ず その舌をみだりにする者はわざはひに陷る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, '愚なる者を產むものは自己の憂を生じ 愚なる者の父は喜樂を得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, '心のたのしみは良薬なり 霊魂のうれひは骨を枯す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, '惡者は人の懐より賄賂をうけて審判の道をまぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, '智慧は哲者の面のまへにあり されど愚なる者は目を地の極にそそぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, '愚なる子は其父の憂となり 亦これを生る母の煩勞となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, '義者を罰するは善らず 貴き者をその義きがために扑は善らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, '言を寡くする者は知識あり 心の靜なる者は哲人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, '愚なる者も默するときは智慧ある者と思はれ その口唇を閉るときは哲者とおもはるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, '自己を人と異にする者はおのれの欲するところのみを求めてすべての善き考察にもとる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, '愚なる者は明哲を喜ばず 惟おのれの心意を顯すことを喜ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, '惡者きたれば藐視したがひてきたり 恥きたれば凌辱もともに來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, '人の口の言は深水の如し 湧てながるる川 智慧の泉なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, '惡者を偏視るは善らず 審判をなして義者を惡しとするも亦善らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, '愚なる者の口唇はあらそひを起し その口は打るることを招く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, '愚なる者の口はおのれの敗壞となり その口唇はおのれの霊魂の罟となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, '人の是非をいふものの言はたはぶれのごとしといへども反つて腹の奧にいる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'その行爲をおこたる者は滅すものの兄弟なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'ヱホバの名はかたき櫓のごとし 義者は之に走りいりて救を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, '富者の資財はその堅き城なり これを高き石垣の如くに思ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, '人の心のたかぶりは滅亡に先だち 謙遜はたふとまるる事にさきだつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'いまだ事をきかざるさきに應ふる者は愚にして辱をかうぶる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, '人の心は尚其疾を忍ぶべし されど心の傷める時は誰かこれに耐んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, '哲者の心は知識をえ 智慧ある者の耳は知識を求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, '人の贈物はその人のために道をひらき かつ貴きものの前にこれを導く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, '先に訴訟の理由をのぶるものは正義に似たれども その鄰人きたり詰問ひてその事を明かにす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, '籤は爭端をとどめ且つよきものの間にへだてとなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, '怒れる兄弟はかたき城にもまさりて説き伏せがたし 兄弟のあらそひは櫓の貫木のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, '人は口の徳によりて腹をあかし その口唇の徳によりて自ら飽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, '死生は舌の權能にあり これを愛する者はその果を食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, '妻を得るものは美物を得るなり 且ヱホバより恩寵をあたへらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, '貧者は哀なる言をもて乞ひ 富人は厲しき答をなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, '多の友をまうくる人は遂にその身を亡す 但し兄弟よりもたのもしき知己もまたあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'ただしく歩むまづしき者は くちびるの悖れる愚なる者に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, '心に思慮なければ善らず 足にて急ぐものは道にまよふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, '人はおのれの痴によりて道につまづき 反て心にヱホバを怨む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, '資財はおほくの友をあつむ されど貧者はその友に疎まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, '虚偽の證人は罰をまぬかれず 謊言をはくものは避るることをえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, '君に媚る者はおほし 凡そ人は贈物を與ふる者の友となるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, '貧者はその兄弟すらも皆これをにくむ 况てその友これに遠ざからざらんや 言をはなちてこれを呼とも去てかへらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, '智慧を得る者はおのれの霊魂を愛す 聰明をたもつ者は善福を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, '虚偽の證人は罰をまぬかれず 謊言をはく者はほろぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, '愚なる者の驕奢に居るは適当からず 况て僕にして上に在る者を治むることをや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, '聰明は人に怒をしのばしむ 過失を宥すは人の榮譽なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, '王の怒は獅の吼るが如く その恩典は草の上におく露のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, '愚なる子はその父の災禍なり 妻の相爭そふは雨漏のたえぬにひとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, '家と資財とは先祖より承嗣ぐもの 賢き妻はヱホバより賜ふものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, '懶惰は人を酣寐せしむ 懈怠人は饑べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, '誡命を守るものは自己の霊魂を守るなり その道をかろむるものは死ぬべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, '貧者をあはれむ者はヱホバに貸すなり その施濟はヱホバ償ひたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, '望ある間に汝の子を打て これを殺すこころを起すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, '怒ることの烈しき者は罰をうく 汝もしこれを救ふともしばしば然せざるを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'なんぢ勸をきき訓をうけよ 然ばなんぢの終に智慧あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, '人の心には多くの計畫あり されど惟ヱホバの旨のみ立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, '人のよろこびは施濟をするにあり 貧者は謊人に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'ヱホバを畏るることは人をして生命にいたらしめ かつ恒に飽足りて災禍に遇ざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, '惰者はその手を盤にいるるも之をその口に擧ることをだにせず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, '嘲笑者を打て さらば拙者も愼まん 哲者を譴めよ さらばかれ知識を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, '父を煩はし母を逐ふは羞赧をきたらし凌辱をまねく子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'わが子よ哲言を離れしむる敎を聽くことを息めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, '惡き證人は審判を嘲り 惡者の口は惡を呑む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, '審判は嘲笑者のために備へられ 鞭は愚なる者の背のために備へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, '酒は人をして嘲らせ 濃酒は人をして騒がしむ 之に迷はさるる者は無智なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, '王の震怒は獅の吼るがごとし 彼を怒らする者は自己のいのちを害ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, '穩かに居りて爭はざるは人の榮譽なりすべて愚なる者は怒り爭ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, '惰者は寒ければとて耕さず この故に収穫のときにおよびて求るとも得るところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, '人の心にある謀計は深き井の水のごとし 然れど哲人はこれを汲出す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, '凡そ人は各自おのれの善を誇る されど誰か忠信なる者に遇しぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, '身を正しくして歩履む義人はその後の子孫に福祉あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, '審判の位に坐する王はその目をもてすべての惡を散す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'たれか我わが心をきよめ わが罪を潔められたりといひ得るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, '二種の權衡二種の斗量は等しくヱホバに憎まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, '幼子といへどもその動作によりておのれの根性の清きか或は正しきかをあらはす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, '聽くところの耳と視るところの眼とはともにヱホバの造り給へるものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'なんぢ睡眠を愛すること勿れ 恐くは貧窮にいたらん 汝の眼をひらけ 然らば糧に飽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '買者はいふ惡し惡しと 然れど去りて後はみづから誇る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, '金もあり眞珠も多くあれど貴き器は知識のくちびるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, '人の保證をなす者よりは先その衣をとれ 他人の保證をなす者をばかたくとらへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, '欺きとりし糧は人に甜し されど後にはその口に沙を充されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, '謀計は相議るによりて成る 戰はんとせば先よく議るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'あるきめぐりて人の是非をいふ者は密事をもらす 口唇をひらきてあるくものと交ること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'おのれの父母を罵るものはその燈火くらやみの中に消ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, '初に俄に得たる產業はその終さいはひならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'われ惡に報いんと言ふこと勿れ ヱホバを待て 彼なんぢを救はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, '二種の法馬はヱホバに憎まる 虚偽の權衡は善らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, '人の歩履はヱホバによる 人いかで自らその道を明かにせんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, '漫に誓願をたつることは其人の罟となる誓願をたててのちに考ふることも亦然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, '賢き王は箕をもて簸るごとく惡人を散し 車輪をもて碾すごとく之を罰す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, '人の霊魂はヱホバの燈火にして人の心の奧を窺ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, '王は仁慈と眞實をもて自らたもつ その位もまた恩惠のおこなひによりて堅くなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, '少者の榮はその力 おいたる者の美しきは白髮なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, '傷つくまでに打たば惡きところきよまり 打てる鞭は腹の底までもとほる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, '王の心はヱホバの手の中にありて恰かも水の流れのごとし 彼その聖旨のままに之を導きたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, '人の道はおのれの目に正しとみゆ されどヱホバは人の心をはかりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, '正義と公平を行ふは犠牲よりも愈りてヱホバに悦ばる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, '高ぶる目と驕る心とは惡人の光にしてただ罪のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, '勤めはたらく者の圖るところは遂にその身を豊裕ならしめ 凡てさわがしく急ぐ者は貧乏をいたす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, '虚偽の舌をもて財を得るは吹はらはるる雲烟のごとし 之を求むる者は死を求むるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, '惡者の殘虐は自己を亡す これ義しきを行ふことを好まざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, '罪人の道は曲り 潔者の行爲は直し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, '相爭ふ婦と偕に室に居らんよりは屋蓋の隅にをるはよし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, '惡者の霊魂は惡をねがふ その鄰も彼にあはれみ見られず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'あざけるもの罰をうくれば拙者は智慧を得 ちゑあるもの敎をうくれば知識を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, '義しき神は惡者の家をみとめて惡者を滅亡に投いれたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, '耳を掩ひて貧者の呼ぶ聲をきかざる者は おのれ自ら呼ぶときもまた聽れざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, '潜なる饋物は忿恨をなだめ 懐中の賄賂は烈しき瞋恚をやはらぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, '公義を行ふことは義者の喜樂にして 惡を行ふものの敗壞なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'さとりの道を離るる人は死し者の集會の中にをらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, '宴樂を好むものは貧人となり 酒と膏とを好むものは富をいたさじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, '惡者は義者のあがなひとなり 悖れる者は直き者に代る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, '爭ひ怒る婦と偕にをらんよりは荒野に居るはよし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, '智慧ある者の家には貴き寳と膏とあり 愚なる人は之を呑つくす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, '正義と憐憫と追求むる者は生命と正義と尊貴とを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, '智慧ある者は強者の城にのぼりて その堅く賴むところを倒す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, '口と舌とを守る者はその霊魂を守りて患難に遇せじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, '高ぶり驕る者を嘲笑者となづく これ驕奢を逞しくして行ふものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, '惰者の情慾はおのれの身を殺す 是はその手を肯て働かせざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, '人は終日しきりに慾を圖る されど義者は與へて吝まず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, '惡者の献物は憎まる 况て惡き事のために献ぐる者をや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, '虚偽の證人は滅さる 然れど聽く人は恒にいふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, '惡人はその面を厚くし 義者はその道を謹む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'ヱホバにむかひては智慧も明哲も謀略もなすところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, '戰闘の日のために馬を備ふ されど勝利はヱホバによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, '嘉名は大なる富にまさり恩寵は銀また金よりも佳し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, '富者と貧者と偕に世にをる 凡て之を造りし者はヱホバなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, '賢者は災禍を見てみづから避け 拙者はすすみて罰をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, '謙遜とヱホバを畏るる事との報は富と尊貴と生命となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, '悖れる者の途には荊棘と罟とあり 霊魂を守る者は遠くこれを離れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, '子をその道に從ひて敎へよ 然ばその老たる時も之を離れじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, '富者は貧者を治め借者は貸人の僕となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, '惡を播くものは禍害を穡り その怒の杖は廢るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, '人を見て惠む者はまた惠まる 此はその糧を貧者に與ふればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, '嘲笑者を逐へば爭論も亦さり 且闘諍も恥辱もやむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, '心の潔きを愛する者はその口唇に憐憫をもてり 王その友とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'ヱホバの目は知識ある者を守る 彼は悖れる者の言を敗りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, '惰者はいふ獅そとにあり われ衢にて殺されんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, '妓婦の口は深き坑なり ヱホバに憎まるる者これに陷らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, '痴なること子の心の中に繋がる 懲治の鞭これを逐いだす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, '貧者を虐げて自らを富さんとする者と富者に與ふる者とは遂にかならず貧しくなる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, '汝の耳を傾ぶけて智慧ある者の言をきき且なんぢの心をわが知識に用ゐよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, '之を汝の腹にたもちて 盡くなんぢの口唇にそなはらしめば樂しかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, '汝をしてヱホバに倚賴ましめんが爲にわれ今日これを汝に敎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'われ勸言と知識とをふくみたる勝れし言を汝の爲に録ししにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'これ汝をして眞の言の確實なることを暁らしめ 且なんぢを遣しし者に眞の言を持歸らしめん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, '弱き者を弱きがために掠むることなかれ 艱難者を門にて壓つくること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'そはヱホバその訴を糺し且かれらを害ふものの生命をそこなはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, '怒る者と交ること勿れ 憤ほる人とともに往ことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, '恐くは汝その道に效ひてみづから罟に陷らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'なんぢ人と手をうつ者となることなかれ 人の負債の保證をなすこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, '汝もし償ふべきものあらずば人なんぢの下なる臥牀までも奪ひ取ん 是豈よからんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'なんぢの先祖がたてし古き地界を移すこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, '汝その業に巧なる人を見るか 斯る人は王の前に立ん かならず賤者の前にたたじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'なんぢ侯たる者とともに坐して食ふときは 愼みて汝の前にある者の誰なるかを思へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, '汝もし食を嗜む者ならば汝の喉に刀をあてよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'その珍饈を貧り食ふこと勿れ これ迷惑の食物なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, '富を得んと思煩らふこと勿れ 自己の明哲を恃むこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'なんぢ虚しきに歸すべき者に目をとむるか 富はかならず自ら翅を生じて鷲のごとく天に飛さらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, '惡目をする者の糧をくらふことなく その珍饈をむさぼりねがふことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'そはその心に思ふごとくその人となりも亦しかればなり 彼なんぢに食へ飮めといふこといへどもその心は汝に眞實ならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, '汝つひにその食へる物を吐出すにいたり 且その出しし懇懃の言もむなしくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, '愚なる者の耳に語ること勿れ 彼なんぢが言の示す明哲を藐めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, '古き地界を移すことなかれ 孤子の畑を侵すことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'そはかれが贖者は強し 必ず汝に對らひて之が訴をのべん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, '汝の心を敎に用ゐ 汝の耳を知識の言に傾けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, '子を懲すことを爲ざるなかれ 鞭をもて彼を打とも死ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'もし鞭をもて彼をうたばその霊魂を陰府より救ふことをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'わが子よもし汝のこころ智からば我が心もまた歓び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'もし汝の口唇ただしき事をいはば我が腎腸も喜ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'なんぢ心に罪人をうらやむ勿れ ただ終日ヱホバを畏れよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'そは必ず應報ありて汝の望は廢らざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'わが子よ 汝ききて智慧をえ かつ汝の心を道にかたぶけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, '酒にふけり肉をたしむものと交ること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'それ酒にふける者と肉を嗜む者とは貧しくなり 睡眠を貧る者は敞れたる衣をきるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, '汝を生る父にきけ 汝の老たる母を軽んずる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, '眞理を買へ これを售るなかれ 智慧と誡命と知識とまた然あれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, '義き者の父は大によろこび 智慧ある子を生る者はこれがために樂しまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, '汝の父母を樂しませ 汝を生る者を喜ばせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'わが子よ汝の心を我にあたへ 汝の目にわが途を樂しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'それ妓婦は深き坑のごとく 淫婦は狭き井のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, '彼は盗賊のごとく人を窺ひ かつ世の人の中に悖れる者を増なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, '禍害ある者は誰ぞ 憂愁ある者は誰ぞ 爭端をなす者は誰ぞ 煩慮ある者は誰ぞ 故なくして傷をうくる者は誰ぞ 赤目ある者は誰ぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, '是すなはち酒に夜をふかすもの 往て混和せたる酒を味ふる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, '酒はあかく盃の中に泡だち滑かにくだる 汝これを見るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, '是は終に蛇のごとく噬み蝮の如く刺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'また汝の目は怪しきものを見 なんぢの心は諕言をいはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, '汝は海のなかに偃すもののごとく帆桅の上に偃すもののごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '汝いはん人われを撃ども我いたまず 我を拷けども我おぼえず 我さめなばまた酒を求めんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'なんぢ惡き人を羨むことなかれ 又これと偕に居らんことを願ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'そはその心に暴虐をはかり その口唇に人を害ふことをいへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, '家は智慧によりて建られ 明哲によりて堅くせられ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'また室は知識によりて各種の貴く美しき寳にて充されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, '智慧ある者は強し 知識ある人は力をます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, '汝よき謀計をもて戰闘をなせ 勝利は議者の多きによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, '智慧は高くして愚なる者の及ぶところにあらず 愚なる者は門にて口を啓くことをえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, '惡をなさんと謀る者を邪曲なる者と稱ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, '愚なる者の謀るところは罪なり 嘲笑者は人に憎まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, '汝もし患難の日に氣を挫かば汝の力は弱し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'なんぢ死地に曳れゆく者を拯へ 滅亡によろめきゆく者をすくはざる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, '汝われら之を知らずといふとも心をはかる者これを暁らざらんや 汝の霊魂をまもる者これを知ざらんや 彼はおのおのの行爲によりて人に報ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'わが子よ蜜を食へ 是は美ものなり また蜂のすの滴瀝を食へ 是はなんぢの口に甘し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, '智慧の汝の霊魂におけるも是の如しと知れ これを得ばかならず報いありて汝の望すたれじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, '惡者よ義者の家を窺ふことなかれ その安居所を攻ること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'そは義者は七次たふるるともまた起く されど惡者は禍災によりて亡ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, '汝の仇たふるるとき樂しむこと勿れ 彼の亡ぶるときこころに喜ぶことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, '恐くはヱホバこれを見て惡しとし その震怒を彼より離れしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'なんぢ惡者を怒ることなかれ 邪曲なる者を羨むなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'それ惡者には後の善賚なし 邪曲なる者の燈火は滅されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'わが子よヱホバと王とを畏れよ 叛逆者に交ること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, '斯るものらの災禍は速におこる この兩者の滅亡はたれか知えんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, '是等もまた智慧ある者の箴言なり 偏り鞫するは善らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, '罪人に告て汝は義しといふものをは衆人これを詛ひ諸民これを惡まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'これを譴る者は恩をえん また福祉これにきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'ほどよき應答をなす者は口唇に接吻するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, '外にて汝の工をととのへ田圃にてこれを自己のためにそなへ 然るのち汝の家を建よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, '故なく汝の鄰に敵して證することなかれ 汝なんぞ口唇をもて欺くべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, '彼の我に爲しし如く我も亦かれになすべし われ人の爲ししところに循ひてこれに報いんといふこと勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'われ曾て惰人の田圃と智慧なき人の葡萄園とをすぎて見しに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, '荊棘あまねく生え薊その地面を掩ひ その石垣くづれゐたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, '我これをみて心をとどめ これを觀て敎をえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'しばらく臥し 暫らく睡り 手を叉きて又しばらく休む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'さらば汝の貧窮は盗人のごとく汝の缺乏は兵士の如くきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, '此等もまたソロモンの箴言なり ユダの王ヒゼキヤに屬せる人々これを輯めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, '事を隱すは神の榮譽なり 事を窮むるは王の榮譽なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, '天の高さと地の深さと 王たる者の心とは測るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, '銀より渣滓を除け さらば銀工の用ふべき器いでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, '王の前より惡者をのぞけ 然ばその位義によりて堅く立ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, '王の前に自ら高ぶることなかれ 貴人の場に立つことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'なんぢが目に見る王の前にて下にさげらるるよりは ここに上れといはるること愈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, '汝かろがろしく出でて爭ふことなかれ 恐くは終にいたりて汝の鄰に辱しめられん その時なんぢ如何になさんとするか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'なんぢ鄰と爭ふことあらば只これと爭へ 人の密事を洩すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, '恐くは聞者なんぢを卑しめん 汝そしられて止ざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, '機にかなひて語る言は銀の彫刻物に金の林檎を嵌たるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, '智慧をもて譴むる者の之をきく者の耳におけることは 金の耳環と精金の飾のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, '忠信なる使者は之を遣す者におけること穡收の日に冷かなる雪あるがごとし 能その主の心を喜ばしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'おくりものすと偽りて誇る人は雨なき雲風の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, '怒を緩くすれば君も言を容る 柔かなる舌は骨を折く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'なんぢ蜜を得るか 惟これを足る程に食へ 恐くは食ひ過して之を吐出さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'なんぢの足を鄰の家にしげくするなかれ 恐くは彼なんぢを厭ひ惡まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'その鄰に敵して虚偽の證をたつる人は斧刃または利き箭のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, '艱難に遇ふとき忠實ならぬ者を賴むは惡しき歯または跛たる足を恃むがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, '心の傷める人の前に歌をうたふは寒き日に衣をぬぐが如く 曹達のうへに酢を注ぐが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'なんぢの仇もし饑ゑなば之に糧をくらはせ もし渇かば之に水を飮ませよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'なんぢ斯するは火をこれが首に積むなり ヱホバなんぢに報いたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, '北風は雨をおこし かげごとをいふ舌は人の顔をいからす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, '爭ふ婦と偕に室に居らんより屋蓋の隅にをるは宜し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, '遠き國よりきたる好き消息は渇きたる人における冷かなる水のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, '義者の惡者の前に服するは井の濁れるがごとく泉の汚れたるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, '蜜をおほく食ふは善らず 人おのれの榮譽をもとむるは榮譽にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'おのれの心を制へざる人は石垣なき壞れたる城のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, '榮譽の愚なる者に適はざるは夏の時に雪ふり 穡收の時に雨ふるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, '故なき詛は雀の翔り燕の飛ぶが如くにきたるものにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, '馬の爲には策あり 驢馬の爲には銜あり 愚なる者の背のために杖あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, '愚なる者の痴にしたがひて答ふること勿れ 恐くはおのれも是と同じからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, '愚なる者の痴にしたがひて之に答へよ 恐くは彼おのれの目に自らを智者と見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, '愚なる者に托して事を言おくる者はおのれの足をきり身に害をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, '跛者の足は用なし 愚なる者の口の箴もかくのごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, '榮譽を愚なる者に與ふるは石を投石索に繋ぐが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, '愚なる者の口にたもつ箴言は酔へるものの刺ある杖を手にて擧ぐるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, '愚なる者を傭ひ流浪者を傭ふ者は すべての人を傷くる射手の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, '狗のかへり來りてその吐たる物を食ふがごとく 愚なる者は重ねてその痴なる事をおこなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, '汝おのれの目に自らを智慧ある者とする人を見るか 彼よりも却て愚なる人に望あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, '惰者は途に獅あり 衢に獅ありといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, '戸の蝶鉸によりて轉るごとく惰者はその牀に輾轉す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, '惰者はその手を盤にいるるも之をその口に擧ることを厭ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, '惰者はおのれの目に自らを善く答ふる七人の者よりも智慧ありとなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, '路をよぎり自己に關りなき爭擾にたづさはる者は狗の耳をとらふる者のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, '旣にその鄰を欺くことをなして我はただ戯れしのみといふ者は 火箭または鎗または死を擲つ狂人のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, '旣にその鄰を欺くことをなして我はただ戯れしのみといふ者は 火箭または鎗または死を擲つ狂人のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, '薪なければ火はきえ 人の是非をいふ者なければ爭端はやむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, '煨火に炭をつぎ火に薪をくぶるがごとく爭論を好む人は爭論を起す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, '人の是非をいふものの言はたはぶれのごとしと雖もかへつて腹の奧に入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, '温かき口唇をもちて惡き心あるは銀の滓をきせたる瓦片のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, '恨むる者は口唇をもて自ら飾れども 心の衷には虚偽をいだく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, '彼その聲を和らかにするとも之を信ずるなかれ その心に七の憎むべき者あればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'たとひ虚偽をもてその恨をかくすとも その惡は會集の中に顯はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, '坑を掘るものは自ら之に陷らん 石を轉ばしあぐる者の上にはその石まろびかへらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, '虚偽の舌はおのれの害す者を憎み 諂ふ口は滅亡をきたらす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'なんぢ明日のことを誇るなかれ そは一日の生ずるところの如何なるを知ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, '汝おのれの口をもて自ら讃むることなく人をして己を讃めしめよ 自己の口唇をもてせず 他人をして己をほめしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, '石は重く沙は軽からず 然ど愚なる者の怒はこの二よりも重し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, '忿怒は猛く憤恨は烈し されど嫉妬の前には誰か立ことをを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, '明白に譴むるに秘に愛するに愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, '愛する者の傷つくるは眞實よりし 敵の接吻するは偽詐よりするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, '飽るものは蜂の蜜をも踐つく されど饑たる者には苦き物さへもすべて甘し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'その家を離れてさまよふ人は その巣を離れてさまよふ鳥のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, '膏と香とは人の心をよろこばすなり 心よりして勸言を與ふる友の美しきもまた斯のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'なんぢの友と汝の父の友とを棄るなかれ なんぢ患難にあふ日に兄弟の家にいることなかれ 親しき隣は疏き兄弟に愈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'わが子よ智慧を得てわが心を悦ばせよ 然ば我をそしる者に我こたふることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, '賢者は禍害を見てみづから避け 拙者はすすみて罰をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, '人の保證をなす者よりは先その衣をとれ 他人の保證をなす者をば固くとらへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, '晨はやく起て大聲にその鄰を祝すれば却て呪詛と見なされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, '相爭ふ婦は雨ふる日に絶ずある雨漏のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'これを制ふるものは風をおさふるがごとく 右の手に膏をつかむがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, '鐵は鐵をとぐ 斯のごとくその友の面を研なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, '無花果の樹をまもる者はその果をくらふ 主を貴ぶものは譽を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, '水に照せば面と面と相肖るがごとく 人の心は人の心に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, '陰府と沈淪とは飽ことなく 人の目もまた飽ことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, '坩堝によりて銀をためし鑢によりて金をためし その讃らるる所によりて人をためす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'なんぢ愚なる者を臼にいれ杵をもて麥と偕にこれを搗ともその愚は去らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'なんぢの羊の情况をよく知り なんぢの群に心を留めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, '富は永く保つものにあらず いかで位は世々にたもたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, '艸枯れ苗いで山の蔬菜あつめらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, '羔羊はなんぢの衣服を出し 牝羊は田圃を買ふ價となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, '牝羊の乳はおほくして汝となんぢの家人の糧となり汝の女をやしなふにたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, '惡者は逐ふ者なけれども逃げ 義者は獅子のごとくに勇まし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, '國の罪によりて侯伯多くなり 智くして知識ある人によりて國は長く保つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, '弱者を虐ぐる貧人は糧をのこさざる暴しき雨のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, '律法を棄るものは惡者をほめ 律法を守る者はこれに敵す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, '惡人は義きことを覺らず ヱホバを求むる者は凡の事をさとる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, '義しくあゆむ貧者は曲れる路をあゆむ富者に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, '律法を守る者は智子なり 放蕩なる者に交るものは父を辱かしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, '利息と高利とをもてその財產を増すものは貧人をめぐむ者のために之をたくはふるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, '耳をそむけて律法を聞ざる者はその祈すらも憎まる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, '義者を惡き道に惑す者はみづから自己の阱に陷らん されど質直なる者は福祉をつぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, '富者はおのれの目に自らを智慧ある者となす されど聰明ある貧者は彼をはかり知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, '義者の喜ぶときは大なる榮あり 惡者の起るときは民身を匿す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'その罪を隱すものは榮ゆることなし 然ど認らはして之を離るる者は憐憫をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, '恒に畏るる人は幸福なり その心を剛愎にする者は災禍に陷るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, '貧しき民を治むるあしき侯伯は吼る獅子あるひは饑たる熊のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, '智からざる君はおほく暴虐をおこなふ 不義の利を惡む者は遐齢をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, '人を殺してその血を心に負ふ者は墓に奔るなり 人これを阻むること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, '義く行む者は救をえ 曲れる路に行む者は直に跌れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'おのれの田地を耕す者は糧にあき 放蕩なる者に從ふものは貧乏に飽く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, '忠信なる人は多くの幸福をえ 速かに富を得んとする者は罪を免れず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, '人を偏視るはよからず 人はただ一片のパンのために愆を犯すなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, '惡目をもつ者は財をえんとて急がはしく 却て貧窮のおのれに來るを知らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, '人を譴むる者は舌をもて諂ふ者よりも大なる感謝をうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, '父母の物を竊みて罪ならずといふ者は滅す者の友なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, '心に貧る者は爭端を起し ヱホバに倚賴むものは豊饒になるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'おのれの心を恃む者は愚なり 智慧をもて行む者は救をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, '貧者に賙すものは乏しからず その目を掩ふ者は詛を受ること多し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, '惡者の起るときは人匿れ その滅るときは義者ます');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'しばしば責られてもなほ強項なる者は救はるることなくして猝然に滅されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, '義者ませば民よろこび 惡きもの權を掌らば民かなしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, '智慧を愛する人はその父を悦ばせ 妓婦に交る者はその財產を費す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, '王は公義をもて國を堅うす されど租税を征取る者はこれを滅す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'その鄰に諂ふ者はかれの脚の前に羅を張る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, '惡人の罪の中には罟あり 然ど義者は歓び樂しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, '義きものは貧きものの訟をかへりみる 然ど惡人は之を知ることを願はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, '嘲笑人は城邑を擾し 智慧ある者は怒をしづむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, '智慧ある人おろかなる人と爭へば或は怒り或は笑ひて休むことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, '血をながす人は直き人を惡む されど義き者はその生命を救はんことを求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, '愚なる者はその怒をことごとく露はし 智慧ある者は之を心に蔵む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, '君王もし虚偽の言を聽かばその臣みな惡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, '貧者と苛酷者と偕に世にをる ヱホバは彼等の目に光をあたへ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, '眞實をもて弱者を審判する王はその位つねに堅く立つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, '鞭と譴責とは智慧をあたふ 任意になしおかれたる子はその母を辱しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, '惡きもの多ければ罪も亦おほし 義者は彼等の傾覆をみん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'なんぢの子を懲せ さらば彼なんぢを安からしめ 又なんぢの心に喜樂を與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, '默示なければ民は放肆にす 律法を守るものは福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, '僕は言をもて譴むるとも改めず 彼は知れども從はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'なんぢ言を謹まざる人を見しや 彼よりは却て愚なる者に望あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, '僕をその幼なき時より柔かに育てなば終には子の如くならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, '怒る人は爭端を起し憤る人は罪おほし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, '人の傲慢はおのれを卑くし 心に謙だる者は榮譽を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, '盗人に黨する者はおのれの霊魂を惡むなり 彼は誓を聽けども説述べず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, '人を畏るれば罟におちいる ヱホバをたのむ者は護られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, '君の慈悲を求むる者はおほし 然れど人の事を定むるはヱホバによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, '不義をなす人は義者の惡むところ 義くあゆむ人は惡者の惡むところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'ヤケの子アグルの語なる箴言 かれイテエルにむかひて之をいへり 即ちイテエルとウカルとにいへる所のものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, '我は人よりも愚なり 我には人の聰明あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, '我いまた智慧をならひ得ず またいまだ至聖きものを暁ることをえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, '天に昇りまた降りし者は誰か 風をその掌中に聚めし者は誰か 水を衣につつみし者は誰か 地のすべての限界を定めし者は誰か その名は何ぞ その子の名は何ぞ 汝これを知るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, '神の言はみな潔よし 神は彼を賴むものの盾なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, '汝その言に加ふること勿れ 恐くは彼なんぢをせめ 又なんぢを謊る者となしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'われ二の事をなんぢに求めたり 我が死ざる先にこれをたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, '即ち虚假と謊言とを我より離れしめ 我をして貧からしめずまた富しめず 惟なくてならぬ糧をあたへ給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'そは我あきて神を知ずといひヱホバは誰なりやといはんことを恐れ また貧くして窃盗をなし我が神の名を汚さんことを恐るればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'なんぢ僕をその主に讒ることなかれ 恐くは彼なんぢを詛ひてなんぢ罪せられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'その父を詛ひその母を祝せざる世類あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'おのれの目に自らを潔者となして尚その汚穢を滌はれざる世類あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'また一の世類あり 嗚呼その眼はいかに高きぞや その瞼は昂れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'その歯は劍のごとく その牙は刃のごとき世類あり 彼等は貧き者を地より呑み 窮乏者を人の中より食ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, '蛭に二人の女あり 與ヘよ與へよと呼はる 飽ことを知ざるもの三あり 否な四あり皆たれりといはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, '即ち陰府姙まざる胎水に滿されざる地 足りといはざる火これなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'おのれの父を嘲り母に從ふことをいやしとする眼は 谷の鴉これを抜いだし鷲の雛これを食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'わが奇とするもの三あり否な四あり共にわが識ざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, '即ち空にとぷ鷲の路 磐の上にはふ蛇の路 海にはしる舟の路 男の女にあふの路これなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, '淫婦の途も亦しかり 彼は食ひてその口を拭ひ われ惡きことを爲ざりきといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, '地は三の者によりて震ふ否な四の者によりて耐ることあたはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, '即ち僕たるもの王となるに因り愚なるもの糧に飽るにより');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, '厭忌はれたる婦の嫁ぐにより婢女その主母に續に因りてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, '地に四の物あり微小といへども最智し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, '蟻は力なき者なれどもその糧を夏のうちに備ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, '山鼠ば強からざれどもその室を磐につくる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, '蝗は王なけれどもみな隊を立ていづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, '守宮は手をもてつかまり王の宮にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, '善あゆむもの三あり否な四あり皆よく歩く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, '獣の中にて最も強くもろもろのものの前より退かざる獅子');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, '肚帶せし戰馬 牡野羊 および當ること能はざる王これなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, '汝もし愚にして自から高ぶり或は惡きことを計らば汝の手を口に當つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'それ乳を搾れば乾酪いで鼻を搾れば血いで 怒を激ふれば爭端おこる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'レムエル王のことば即ちその母の彼に敎へし箴言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'わが子よ何を言んか わが胎の子よ何をいはんか 我が願ひて得たる子よ何をいはんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'なんぢの力を女につひやすなかれ 王を滅すものに汝の途をまかする勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'レムエルよ酒を飮は王の爲べき事に非ず 王の爲べき事にあらず 醇醪を求むるは牧伯の爲すべき事にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, '恐くは酒を飮て律法をわすれ 且すべて惱まさるる者の審判を枉げん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, '醇醪を亡びんとする者にあたへ 酒を心の傷める者にあたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'かれ飮てその貧窮をわすれ 復その苦楚を憶はざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'なんぢ瘖者のため又すべての孤者の訟のために口をひらけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'なんぢ口をひらきて義しき審判をなし貧者と窮乏者の訟を糺せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, '誰か賢き女を見出すことを得ん その價は眞珠よりも貴とし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'その夫の心は彼を恃み その產業は乏しくならじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, '彼が存命ふる間はその夫に善事をなして惡き事をなさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, '彼は羊の毛と麻とを求め喜びて手から操き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, '商賈の舟のごとく遠き國よりその糧を運び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, '夜のあけぬ先に起てその家人に糧をあたへ その婢女に日用の分をあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, '田畝をはかりて之を買ひ その手の操作をもて葡萄園を植ゑ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, '力をもて腰に帶し その手を強くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, '彼はその利潤の益あるを知る その燈火は終夜きえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'かれ手を紡線車にのべ その指に紡錘をとり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, '手を貧者にのべ 手を困苦者に舒ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, '彼は家人の爲に雪をおそれず 蓋その家人みな蕃紅の衣をきればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, '彼はおのれの爲に美しき褥子をつくり 細布と紫とをもてその衣とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'その夫はその地の長老とともに邑の門に坐するによりて人に知るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, '彼は細布の衣を製りてこれをうり 帶をつくりて商賈にあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, '彼は筋力と尊貴とを衣とし且のちの日を笑ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, '彼は口を啓きて智慧をのぶ 仁愛の敎誨その舌にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'かれはその家の事を鑒み 怠惰の糧を食はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'その衆子は起て彼を祝す その夫も彼を讃ていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '賢く事をなす女子は多けれども 汝はすべての女子に愈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, '艶麗はいつはりなり 美色は呼吸のごとし 惟ヱホバを畏るる女は譽られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'その手の操作の果をこれにあたへ その行爲によりてこれを邑の門にほめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'ダビデの子 ヱルサレムの王 傳道者の言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, '傳道者言く 空の空 空の空なる哉 都て空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, '日の下に人の勞して爲ところの諸の動作はその身に何の益かあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, '世は去り世は來る 地は永久に長存なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, '日は出で日は入り またその出し處に喘ぎゆくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, '風は南に行き又轉りて北にむかひ 旋轉に旋りて行き 風復その旋轉る處にかへる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, '河はみな海に流れ入る 海は盈ること無し 河はその出きたれる處に復還りゆくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, '萬の物は勞苦す 人これを言つくすことあたはず 目は見に飽ことなく耳は聞に充ること無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, '曩に有し者はまた後にあるべし 曩に成し事はまた後に成べし 日の下には新しき者あらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, '見よ是は新しき者なりと指て言べき物あるや 其は我等の前にありし世々に旣に久しくありたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, '己前のものの事はこれを記憶ることなし 以後のものの事もまた後に出る者これをおぼゆることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'われ傳道者はヱルサレムにありてイスラエルの王たりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, '我心を盡し智慧をもちひて天が下に行はるる諸の事を尋ねかつ考覈たり此苦しき事件は神が世の人にさづけて之に身を勞せしめたまふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, '我日の下に作ところの諸の行爲を見たり 嗚呼皆空にして風を捕ふるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, '曲れる者は直からしむるあたはず缺たる者は數をあはするあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, '我心の中に語りて言ふ 嗚呼我は大なる者となれり 我より先にヱルサレムにをりしすべての者よりも我は多くの智慧を得たり 我心は智慧と知識を多く得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, '我心を盡して智慧を知んとし狂妄と愚癡を知んとしたりしが 是も亦風を捕ふるがごとくなるを暁れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, '夫智慧多ければ憤激多し 知識を増す者は憂患を増す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, '我わが心に言けらく 來れ我試みに汝をよろこばせんとす 汝逸樂をきはめよと 嗚呼是もまた空なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, '我笑を論ふ是は狂なり 快樂を論ふ是何の爲ところあらんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, '我心に智慧を懐きて居つつ酒をもて肉身を肥さんと試みたり 又世の人は天が下において生涯如何なる事をなさば善らんかを知んために我は愚なる事を行ふことをせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, '我は大なる事業をなせり 我はわが爲に家を建て葡萄園を設け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, '園をつくり囿をつくり 又菓のなる諸の樹を其處に植ゑ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'また水の塘池をつくりて樹木の生茂れる林に其より水を灌がしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, '我は僕婢を買得たり また家の子あり 我はまた凡て我より前にヱルサレムにをりし者よりも衆多の牛羊を有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, '我は金銀を積み 王等と國々の財寶を積あげたり また歌詠之男女を得 世の人の樂なる妻妾を多くえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, '斯我は大なる者となり 我より前にヱルサレムにをりし諸の人よりも大になりぬ 吾智慧もまたわが身を離れざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, '凡そわが目の好む者は我これを禁ぜす 凡そわが心の悦ぶ者は我これを禁ぜざりき 即ち我はわが諸の勞苦によりて快樂を得たり 是は我が諸の勞苦によりて得たるところの分なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, '我わが手にて爲たる諸の事業および我が勞して事を爲たる勞苦を顧みるに 皆空にして風を捕ふるが如くなりき 日の下には益となる者あらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, '我また身を轉らして智慧と狂妄と愚癡とを觀たり 抑王に嗣ぐところの人は如何なる事を爲うるや その旣になせしところの事に過ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, '光明の黑暗にまさるがごとく智慧は愚癡に勝るなり 我これを暁れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, '智者の目はその頭にあり愚者は黑暗に歩む 然ど我しる其みな遇ふところの事は同一なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, '我心に謂けらく 愚者の遇ふところの事に我もまた遇ふべければ 我なんぞ智慧のまさる所あらんや 我また心に謂り是も亦空なるのみと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, '夫智者も愚者と均しく永く世に記念らるることなし 來らん世にいたれば皆早く旣に忘らるるなり 嗚呼智者の愚者とおなじく死るは是如何なる事ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, '是に於て我世にながらふることを厭へり 凡そ日の下に爲ところの事は我に惡く見ればなり 即ち皆空にして風を捕ふるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, '我は日の下にわが勞して諸の動作をなしたるを恨む其は我の後を嗣ぐ人にこれを遺さざるを得ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, '其人の智愚は誰かこれを知らん然るにその人は日の下に我が勞して爲し智慧をこめて爲たる諸の工作を管理るにいたらん是また空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, '我身をめぐらし日の下にわが勞して爲たる諸の動作のために望を失へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, '今茲に人あり 智慧と知識と才能をもて勞して事をなさんに終には之がために勞せざる人に一切を遺してその所有となさしめざるを得ざるなり 是また空にして大に惡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, '夫人はその日の下に勞して爲ところの諸の動作とその心勞によりて何の得ところ有るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'その世にある日には常に憂患あり その勞苦は苦し その心は夜の間も安んずることあらず 是また空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, '人の食飮をなしその勞苦によりて心を樂しましむるは幸福なる事にあらず 是もまた神の手より出るなり 我これを見る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, '誰かその食ふところその歓樂を極むるところに於て我にまさる者あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, '神はその心に適ふ人には智慧と知識と喜樂を賜ふ 然れども罪を犯す人には勞苦を賜ひて斂めかつ積ことを爲さしむ 是は其を神の心に適ふ人に與へたまはんためなり 是もまた空にして風を捕ふるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, '天が下の萬の事には期あり 萬の事務には時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, '生るるに時あり死るに時あり 植るに時あり植たる者を抜に時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, '殺すに時あり醫すに時あり 毀つに時あり建るに時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, '泣に時あり笑ふに時あり 悲むに時あり躍るに時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, '石を擲つに時あり石を斂むるに時あり 懐くに時あり懐くことをせざるに時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, '得に時あり失ふに時あり 保つに時あり棄るに時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, '裂に時あり縫に時あり 默すに時あり語るに時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, '愛しむに時あり惡むに時あり 戰ふに時あり和ぐに時あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, '働く者はその勞して爲ところよりして何の益を得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, '我神が世の人にさづけて身をこれに勞せしめたまふところの事件を視たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, '神の爲したまふところは皆その時に適ひて美麗しかり 神はまた人の心に永遠をおもふの思念を賦けたまへり 然ば人は神のなしたまふ作爲を始より終まで知明むることを得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, '我知る人の中にはその世にある時に快樂をなし善をおこなふより外に善事はあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'また人はみな食飮をなしその勞苦によりて逸樂を得べきなり 是すなはち神の賜物たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, '我知る凡て神のなしたまふ事は限なく存せん 是は加ふべき所なく是は減すべきところ無し 神の之をなしたまふは人をしてその前に畏れしめんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, '昔ありたる者は今もあり 後にあらん者は旣にありし者なり 神はその遂やられし者を索めたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, '我また日の下を見るに審判をおこなふ所に邪曲なる事あり 公義を行ふところに邪曲なる事あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, '我すなはち心に謂けらく神は義者と惡者とを鞫きたまはん 彼處において萬の事と萬の所爲に時あるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, '我また心に謂けらく是事あるは是世の人のためなり 即ち神は斯世の人を撿して之にその獣のごとくなることを自ら暁らしめ給ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, '世の人に臨むところの事はまた獣にも臨む この二者に臨むところの事は同一にして是も死ば彼も死るなり 皆同一の呼吸に依れり 人は獣にまさる所なし皆空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, '皆一の所に往く 皆塵より出で皆塵にかへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, '誰か人の魂の上に昇り獣の魂の地にくだることを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, '然ば人はその動作によりて逸樂をなすに如はなし 是その分なればなり 我これを見る その身の後の事は誰かこれを携へゆきて見さしむる者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, '茲に我身を轉して日の下に行はるる諸の虐遇を視たり 嗚呼虐げらる者の涙ながる 之を慰むる者あらざるなり また虐ぐる者の手には權力あり 彼等はこれを慰むる者あらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, '我は猶生る生者よりも旣に死たる死者をもて幸なりとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'またこの二者よりも幸なるは未だ世にあらずして日の下におこなはるる惡事を見ざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, '我また諸の勞苦と諸の工事の精巧とを觀るに 是は人のたがひに嫉みあひて成せる者たるなり 是も空にして風を捕ふるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, '愚なる者は手を束ねてその身の肉を食ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, '片手に物を盈て平穩にあるは 兩手に物を盈て勞苦て風を捕ふるに愈れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, '我また身をめぐらし日の下に空なる事のあるを見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, '茲に人あり只獨にして伴侶もなく子もなく兄弟もなし 然るにその勞苦は都て窮なくの目は富に飽ことなし 彼また言ず嗚呼我は誰がために勞するや何とて我は心を樂ませざるやと 是もまた空にして勞力の苦き者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, '二人は一人に愈る其はその勞苦のために善報を得ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, '即ちその跌倒る時には一箇の人その伴侶を扶けおこすべし 然ど孤身にして跌倒る者は憐なるかな之を扶けおこす者なきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, '又二人ともに寝れば温暖なり一人ならば爭で温暖ならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, '人もしその一人を攻撃ば二人してこれに當るべし 三根の繩は容易く斷ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, '貧くして賢き童子は 老て愚にして諌を納れざる王に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, '彼は牢獄より出て王となれり 然どその國に生れし時は貧かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, '我日の下にあゆむところの群生が彼王に続てこれに代りて立ところの童子とともにあるを觀たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, '民はすべて際限なし その前にありし者みな然り 後にきたる者また彼を悦ばず 是も空にして風を捕ふるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, '汝ヱホバの室にいたる時にはその足を愼め 進みよりて聽聞は愚なる者の犠牲にまさる 彼等はその惡をおこなひをることを知ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, '汝神の前にありては軽々し口を開くなかれ 心を攝めて妄に言をいだすなかれ 其は神は天にいまし汝は地にをればなり 然ば汝の言詞を少からしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, '夫夢は事の繁多によりて生じ 愚なる者の聲は言の衆多によりて識るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, '汝神に誓願をかけなば之を還すことを怠るなかれ 神は愚なる者を悦びたまはざるなり 汝はそのかけし誓願を還すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, '誓願をかけてこれを還さざるよりは寧ろ誓願をかけざるは汝に善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, '汝の口をもて汝の身に罪を犯さしむるなかれ 亦使者の前に其は過誤なりといふべからず 恐くは神汝の言を怒り汝の手の所爲を滅したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, '夫夢多ければ空なる事多し 言詞の多きもまた然り 汝ヱホバを畏め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, '汝國の中に貧き者を虐遇る事および公道と公義を枉ることあるを見るもその事あるを怪むなかれ 其はその位高き人よりも高き者ありてその人を伺へばなり又其等よりも高き者あるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, '國の利益は全く是にあり 即ち王者が農事に勤むるにあるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, '銀を好む者は銀に飽こと無し 豊富ならんことを好む者は得るところ有らず 是また空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, '貨財増せばこれを食む者も増すなり その所有主は唯目にこれを看るのみ その外に何の益かあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, '勞する者はその食ふところは多きも少きも快く睡るなり 然れども富者はその貨財の多きがために睡ることを得せず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, '我また日の下に患の大なる者あるを見たり すなはち財寶のこれを蓄ふる者の身に害をおよぼすことある是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'その財寶はまた災難によりて失落ことあり 然ばその人子を擧ることあらんもその手には何物もあることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, '人は母の胎より出て來りしごとくにまた裸體にして皈りゆくべし その勞苦によりて得たる者を毫厘も手にとりて携へゆくことを得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, '人は全くその來りしごとくにまた去ゆかざるを得ず 是また患の大なる者なり 抑風を追て勞する者何の益をうること有んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, '人は生命の涯黑暗の中に食ふことを爲す また憂愁多かり 疾病身にあり 憤怒あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, '視よ我は斯觀たり 人の身にとりて善かつ美なる者は 神にたまはるその生命の極食飮をなし 且その日の下に勞して働ける勞苦によりて得るところの福禄を身に享るの事なり是その分なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, '何人によらず神がこれに富と財を與へてそれに食ことを得せしめ またその分を取りその勞苦によりて快樂を得ることをせさせたまふあれば その事は神の賜物たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'かかる人はその年齢の日を憶ゆること深からず 其は神これが心の喜ぶところにしたがひて應ることを爲したまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, '我觀るに日の下に一件の患あり是は人の間に恒なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'すなはち神富と財と貴を人にあたへて その心に慕ふ者を一件もこれに缺ることなからしめたまひながらも 神またその人に之を食ふことを得せしめたまはずして 他人のこれを食ふことあり 是空なり惡き疾なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, '假令人百人の子を擧けまた長壽してその年齢の日多からんも 若その心景福に滿足せざるか又は葬らるることを得ざるあれば 我言ふ流產の子はその人にまさるたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, '夫流產の子はその來ること空しくして黑暗の中に去ゆきその名は黑暗の中にかくるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, '又是は日を見ることなく物を知ることなければ彼よりも安泰なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, '人の壽命千年に倍するとも福祉を蒙れるにはあらず 皆一所に往くにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, '人の勞苦は皆その口のためなり その心はなほも飽ざるところ有り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, '賢者なんぞ愚者に勝るところあらんや また世人の前に歩行ことを知ところの貧者も何の勝るところ有んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, '目に觀る事物は心のさまよひ歩くに愈るなり 是また空にして風を捕ふるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, '嘗て在し者は久しき前にすでにその名を命られたり 即ち是は人なりと知る 然ば是はかの自己よりも力強き者と爭ふことを得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, '衆多の言論ありて虚浮き事を増す然ど人に何の益あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, '人はその虚空き生命の日を影のごとくに送るなり 誰かこの世において如何なる事か人のために善き者なるやを知ん 誰かその身の後に日の下にあらんところの事を人に告うる者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, '名は美膏に愈り 死る日は生るる日に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, '哀傷の家に入は宴樂の家に入に愈る 其は一切の人の終かくのごとくなればなり 生る者またこれをその心にとむるあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, '悲哀は嬉笑に愈る 其は面に憂色を帶るなれば心も善にむかへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, '賢き者の心は哀傷の家にあり 愚なる者の心は喜樂の家にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, '賢き者の勸責を聽は愚なる者の歌詠を聽に愈るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, '愚なる者の笑は釜の下に焚る荊棘の聲のごとし是また空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, '賢き人も虐待る事によりて狂するに至るあり賄賂は人の心を壞なふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, '事の終はその始よりも善し 容忍心ある者は傲慢心ある者に勝る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, '汝氣を急くして怒るなかれ 怒は愚なる者の胸にやどるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, '昔の今にまさるは何故ぞやと汝言なかれ 汝の斯る問をなすは是智慧よりいづる者にあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, '智慧の上に財產をかぬれば善し 然れば日を見る者等に利益おほかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, '智慧も身の護庇となり銀子も身の護庇となる 然ど智惠はまたこれを有る者に生命を保しむ 是知識の殊勝たるところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, '汝神の作爲を考ふべし 神の曲たまひし者は誰かこれを直くすることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, '幸福ある日には樂め 禍患ある日には考へよ 神はこの二者をあひ交錯て降したまふ 是は人をしてその後の事を知ることなからしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, '我この空の世にありて各樣の事を見たり 義人の義をおこなひて亡ぶるあり 惡人の惡をおこなひて長壽あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, '汝義に過るなかれまた賢に過るなかれ 汝なんぞ身を滅すべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, '汝惡に過るなかれまた愚なる勿れ 汝なんぞ時いたらざるに死べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, '汝此を執は善しまた彼にも手を放すなかれ 神を畏む者はこの一切の者の中より逃れ出るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, '智慧の智者を幇くることは邑の豪雄者十人にまさるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, '正義して善をおこなひ罪を犯すことなき人は世にあることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, '人の言出す言詞には凡て心をとむる勿れ 恐くは汝の僕の汝を詛ふを聞こともあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, '汝も屡人を詛ふことあるは汝の心に知ところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, '我智慧をもてこの一切の事を試み我は智者とならんと謂たりしが遠くおよばざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, '事物の理は遠くして甚だ深し 誰かこれを究むることを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, '我は身をめぐらし心をもちひて物を知り事を探り 智慧と道理を索めんとし 又惡の愚たると愚癡の狂妄たるを知んとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, '我了れり 婦人のその心羅と網のごとくその手縲絏のごとくなる者は是死よりも苦き者なり 神の悦びたまふ者は之を避ることを得ん罪人は之に執らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, '傳道者言ふ 視よ我その數を知んとして一々に算へてつひに此事を了る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, '我なほ尋ねて得ざる者は是なり 我千人の中には一箇の男子を得たれども その數の中には一箇の女子をも得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, '我了れるところは唯是のみ 即ち神は人を正直者に造りたまひしに人衆多の計略を案出せしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, '誰か智者に如ん誰か事物の理を解ことを得ん 人の智慧はその人の面に光輝あらしむ 又その粗暴面も變改べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, '我言ふ王の命を守るべし旣に神をさして誓ひしことあれば然るべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, '早まりて王の前を去ることなかれ 惡き事につのること勿れ 其は彼は凡てその好むところを爲ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, '王の言語には權力あり 然ば誰か之に汝何をなすやといふことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, '命令を守る者は禍患を受るに至らず 智者の心は時期と判斷を知なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, '萬の事務には時あり判斷あり是をもて人大なる禍患をうくるに至るあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, '人は後にあらんところの事を知ず また誰か如何なる事のあらんかを之に告る者あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, '霊魂を掌管て霊魂を留めうる人あらず 人はその死る日には權力あること旡し 此戰爭には釋放たるる者あらず 又罪惡はこれを行ふ者を救ふことを得せざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, '我この一切の事を見また日の下におこなはるる諸の事に心を用ひたり時としては此人彼人を治めてこれに害を蒙らしむることあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, '我見しに惡人の葬られて安息にいるあり また善をおこなふ者の聖所を離れてその邑に忘らるるに至るあり是また空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, '惡き事の報速にきたらざるが故に世人心を専にして惡をおこなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, '罪を犯す者百次惡をなして猶長命あれども 我知る神を畏みてその前に畏怖をいだく者には幸福あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, '但し惡人には幸福あらず またその生命も長からずして影のごとし 其は神の前に畏怖をいだくことなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, '我日の下に空なる事のおこなはるるを見たり 即ち義人にして惡人の遭べき所に遭ふ者あり 惡人にして義人の遭べきところに遭ふ者あり 我謂り是もまた空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, '是に於て我喜樂を讃む 其は食飮して樂むよりも好き事は日の下にあらざればなり 人の勞して得る物の中是こそはその日の下にて神にたまはる生命の日の間その身に離れざる者なれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, '茲に我心をつくして智慧を知らんとし世に爲ところの事を究めんとしたり 人は夜も晝もその目をとぢて眠ることをせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, '我神の諸の作爲を見しが人は日の下におこなはるるところの事を究むるあたはざるなり 人これを究めんと勞するもこれを究むることを得ず 且又智者ありてこれを知ると思ふもこれを究むることあたはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, '我はこの一切の事に心を用ひてこの一切の事を明めんとせり 即ち義き者と賢き者およびかれらの爲ところは神の手にあるなるを明めんとせり 愛むや惡むやは人これを知ることなし一切の事はその前にあるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, '諸の人に臨む所は皆同じ 義き者にも惡き者にも善者にも 淨者にも穢れたる者にも 犠牲を献ぐる者にも犠牲を献げぬ者にもその臨むところの事は同一なり 善人も罪人に異ならず 誓をなす者も誓をなすことを畏るる者に異ならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, '諸の人に臨むところの事の同一なるは是日の下におこなはるる事の中の惡き者たり 抑人の心には惡き事充をり その生る間は心に狂妄を懐くあり 後には死者の中に往くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, '凡活る者の中に列る者は望あり 其は生る犬は死る獅子に愈ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, '生者はその死んことを知る 然ど死る者は何事をも知ずまた應報をうくることも重てあらず その記憶らるる事も遂に忘れらるるに至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'またその愛も惡も嫉も旣に消うせて彼等は日の下におこなはるる事に最早何時までも關係ことあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, '汝往て喜悦をもて汝のパンを食ひ樂き心をも汝の酒を飮め 其は神久しく汝の行爲を嘉納たまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, '汝の衣服を常に白からしめよ 汝の頭に膏を絶しむるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, '日の下に汝が賜はるこの汝の空なる生命の日の間汝その愛する妻とともに喜びて度生せ 汝の空なる生命の日の間しかせよ 是は汝が世にありて受る分汝が日の下に働ける勞苦によりて得る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, '凡て汝の手に堪ることは力をつくしてこれを爲せ 其は汝の往んところの陰府には工作も計謀も知識も智慧もあることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, '我また身をめぐらして日の下を觀るに 迅速者走ることに勝にあらず強者戰爭に勝にあらず 智慧者食物を獲にあらず 明哲人財貨を得にあらず 知識人恩顧を得にあらず 凡て人に臨むところの事は時ある者偶然なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, '人はまたその時を知ず 魚の禍の網にかかり鳥の鳥羅にかかるが如くに世の人もまた禍患の時の計らざるに臨むに及びてその禍患にかかるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, '我日の下に是事を觀て智慧となし大なる事となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'すなはち茲に一箇の小き邑ありて その中の人は鮮かりしが大なる王これに攻きたりてこれを圍みこれに向ひて大なる雲梯を建たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, '時に邑の中に一人の智慧ある貧しき人ありてその智慧をもて邑を救へり 然るに誰ありてその貧しき人を記念もの無りし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, '是において我言り智慧は勇力に愈る者なりと 但しかの貧しき人の智慧は藐視られその言詞は聽れざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, '靜に聽る智者の言は愚者の君長たる者の號呼に愈る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, '智慧は軍の器に勝れり一人の惡人は許多の善事を壞ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, '死し蝿は和香者の膏を臭くしこれを腐らす 少許の愚癡は智慧と尊榮よりも重し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, '智者の心はその右に愚者の心はその左に行くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, '愚者は出て途を行にあたりてその心たらず自己の愚なることを一切の人に告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, '君長たる者汝にむかひて腹たつとも汝の本處を離るる勿れ温順は大なる愆を生ぜしめざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, '我日の下に一の患事あるを見たり是は君長たる者よりいづる過誤に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'すなはち愚なる者高き位に置かれ貴き者卑き處に坐る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, '我また僕たる者が馬に乗り王侯たる者が僕のごとく地の上に歩むを觀たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, '坑を掘る者はみづから之におちいり石垣を毀つ者は蛇に咬れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, '石を打くだく者はそれがために傷を受け木を割る者はそれがために危難に遭ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, '鐵の鈍くなれるあらんにその刃を磨ざれば力を多く之にもちひざるを得ず 智慧は功を成に益あるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, '蛇もし呪術を聽ずして咬ば呪術師は用なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, '智者の口の言語は恩徳あり 愚者の唇はその身を呑ほろぼす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, '愚者の口の言は始は愚なり またその言は終は狂妄にして惡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, '愚者は言詞を衆くす 人は後に有ん事を知ず 誰かその身の後にあらんところの事を述るを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, '愚者の勞苦はその身を疲らす彼は邑にいることをも知ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'その王は童子にしてその侯伯は朝に食をなす國よ 汝は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'その王は貴族の子またその侯伯は酔樂むためならず力を補ふために適宜き時に食をなす國よ 汝は福なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, '懶惰ところよりして屋背は落ち 手を垂をるところよりして家屋は漏る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, '食事をもて笑ひ喜ぶの物となし酒をもて快樂を取れり 銀子は何事にも應ずるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, '汝心の中にても王たる者を詛ふなかれ また寝室にても富者を詛なかれ 天空の鳥その聲を傳へ羽翼ある者その事を布べければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, '汝の糧食を水の上に投げよ 多くの日の後に汝ふたたび之を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, '汝一箇の分を七また八にわかて 其は汝如何なる災害の地にあらんかを知ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, '雲もし雨の充るあれば地に注ぐ また樹もし南か北に倒るるあればその樹は倒れたる處にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, '風を伺ふ者は種播ことを得ず 雲を望む者は刈ことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, '汝は風の道の如何なるを知ず また孕める婦の胎にて骨の如何に生長つを知ず 斯汝は萬事を爲たまふ神の作爲を知ことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, '汝朝に種を播け 夕にも手を歇るなかれ 其はその實る者は此なるか彼なるか又は二者ともに美なるや汝これを知ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, '夫光明は快き者なり 目に日を見るは樂し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, '人多くの年生ながらへてその中凡て幸福なるもなほ幽暗の日を憶ふべきなり 其はその數も多かるべければなり 凡て來らんところの事は皆空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, '少者よ汝の少き時に快樂をなせ 汝の少き日に汝の心を悦ばしめ汝の心の道に歩み汝の目に見るところを爲せよ 但しその諸の行爲のために神汝を鞫きたまはんと知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, '然ば汝の心より憂を去り 汝の身より惡き者を除け 少き時と壯なる時はともに空なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, '汝の少き日に汝の造主を記えよ 即ち惡き日の來り年のよりて我は早何も樂むところ無しと言にいたらざる先');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'また日や光明や月や星の暗くならざる先 雨の後に雲の返らざる中に汝然せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'その日いたる時は家を守る者は慄ひ 力ある人は屈み 磨碎者は寡きによりて息み 窓より窺ふ者は目昏むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, '磨こなす聲低くなれば衢の門は閉づ その人は鳥の聲に起あがり 歌の女子はみな身を卑くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'かかる人々は高き者を恐る畏しき者多く途にあり 巴旦杏は花咲くまた蝗もその身に重くその嗜欲は廢る 人永遠の家にいたらんとすれば哭婦衢にゆきかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, '然る時には銀の紐は解け金の盞は碎け吊瓶は泉の側に壞れ轆轤は井の傍に破ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, '而して塵は本の如くに土に皈り 霊魂はこれを賦けし神にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, '傳道者云ふ空の空なるかな皆空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'また傳道者は智慧あるが故に恒に知識を民に敎へたり 彼は心をもちひて尋ね究め許多の箴言を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, '傳道者は務めて佳美き言詞を求めたり その書しるしたる者は正直して眞實の言語なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, '智者の言語は刺鞭のごとく 會衆の師の釘たる釘のごとくにして 一人の牧者より出し者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'わが子よ是等より訓誡をうけよ 多く書をつくれば竟なし 多く學べば體疲る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, '事の全體の皈する所を聽べし 云く 神を畏れその誡命を守れ 是は諸の人の本分たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, '神は一切の行爲ならびに一切の隠れたる事を善惡ともに審判たまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'これはソロモンの雅歌なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'ねがはしきは彼その口の接吻をもて我にくちつけせんことなり 汝の愛は酒よりもまさりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'なんぢの香膏は其香味たへに馨しくなんぢの名はそそがれたる香膏のごとし 是をもて女子等なんぢを愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'われを引たまへ われら汝にしたがひて走らん 王われをたづさへてその後宮にいれたまへり 我らは汝によりて歡び樂しみ酒よりも勝りてなんぢの愛をほめたたふ 彼らは直きこころをもて汝を愛す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'ヱルサレムの女子等よ われは黑けれどもなほ美はし ケダルの天幕のごとく またソロモンの帷帳に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'われ色くろきが故に日のわれを燒たるが故に我を視るなかれ わが母の子等われを怒りて我に葡萄園をまもらしめたり 我はおのが葡萄園をまもらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'わが心の愛する者よなんぢは何處にてなんぢの群を牧ひ 午時いづこにて之を息まするや請ふわれに告よ なんぞ面を覆へる者の如くしてなんぢが伴侶の群のかたはらにをるべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '婦女の最も美はしき者よ なんぢ若しらずば群の足跡にしたがひて出ゆき 牧羊者の天幕のかたはらにて汝の羔山羊を牧へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'わが佳耦よ 我なんぢをパロの車の馬に譬ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'なんぢの臉には鏈索を垂れ なんぢの頭には珠玉を陳ねて至も美はし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'われら白銀の星をつけたる黄金の鏈索をなんぢのために造らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '王其席につきたまふ時 わがナルダ其香味をいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'わが愛する者は我にとりてはわが胸のあひだにおきたる沒藥の袋のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'わが愛する者はわれにとりてはエンゲデの園にあるコペルの英華のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'ああ美はしきかな わが佳耦よ ああうるはしきかな なんぢの目は鴿のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'わが愛する者よ ああなんぢは美はしくまた樂しきかな われらの牀は靑緑なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'われらの家の棟梁は香柏 その垂木は松の木なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'われはシャロンの野花 谷の百合花なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '女子等の中にわが佳耦のあるは荊棘の中に百合花のあるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'わが愛する者の男子等の中にあるは林の樹の中に林檎のあるがごとし 我ふかく喜びてその蔭にすわれり その實はわが口に甘かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, '彼われをたづさへて酒宴の室にいれたまへり その我上にひるがへしたる旗は愛なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, '請ふ なんぢら乾葡萄をもてわが力をおぎなへ 林檎をもて我に力をつけよ 我は愛によりて疾わづらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, '彼が左の手はわが頭の下にあり その右の手をもて我を抱く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'ヱルサレムの女子等よ我なんぢらに獐と野の鹿とをさし誓ひて請ふ 愛のおのづから起るときまでは殊更に喚起し且つ醒すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'わが愛する者の聲きこゆ 視よ 山をとび 岡を躍りこえて來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'わが愛する者は獐のごとくまた小鹿のごとし 視よ彼われらの壁のうしろに立ち 窓より覗き 格子より窺ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'わが愛する者われに語りて言ふ わが佳耦よ わが美はしき者よ 起ていできたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, '視よ 冬すでに過ぎ 雨もやみてはやさりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'もろもろの花は地にあらはれ 鳥のさへづる時すでに至り 班鳩の聲われらの地にきこゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, '無花果樹はその靑き果を赤らめ 葡萄の樹は花さきてその馨はしき香氣をはなつ わが佳耦よ わが美しき者よ 起て出きたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, '磐間にをり 斷崖の匿處にをるわが鴿よ われに汝の面を見させよ なんぢの聲をきかしめよ なんぢの聲は愛らしく なんぢの面はうるはし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'われらのために狐をとらへよ 彼の葡萄園をそこなふ小狐をとらへよ 我等の葡萄園は花盛なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'わが愛する者は我につき我はかれにつく 彼は百合花の中にてその群を牧ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'わが愛する者よ 日の涼しくなるまで 影の消るまで身をかへして出ゆき 荒き山々の上にありて獐のごとく 小鹿のごとくせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, '夜われ床にありて我心の愛する者をたづねしが尋ねたれども得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '我おもへらく今おきて邑をまはりありき わが心の愛する者を街衢あるひは大路にてたづねんと 乃ちこれを尋ねたれども得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, '邑をまはりありく夜巡者らわれに遇ければ 汝らわが心の愛する者を見しやと問ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'これに別れて過ゆき間もなくわが心の愛する者の遇たれば 之をひきとめて放さず 遂にわが母の家にともなひゆき 我を產し者の室にいりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'ヱルサレムの女子等よ 我なんぢらに獐と野の鹿とをさし誓ひて請ふ 愛のおのづから起る時まで殊更に喚起し且つ醒すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'この沒藥乳香など商人のもろもろの薫物をもて身をかをらせ 煙の柱のごとくして荒野より來る者は誰ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, '視よ こはソロモンの乗輿にして 勇士六十人その周圍にあり イスラエルの勇士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'みな刀劍を執り 戰鬪を善す 各人腰に刀劍を帶て夜の警誡に備ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'ソロモン王レバノンの木をもて己のために輿をつくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'その柱は白銀 その欄杆は黄金 その座は紫色にて作り その内部にはイスラエルの女子等が愛をもて繍たる物を張つく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'シオンの女子等よ 出きたりてソロモン王を見よ かれは婚姻の日 心の喜べる日にその母の己にかうぶらしし冠冕を戴けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'ああなんぢ美はしきかな わが佳耦よ ああなんぢうるはしきかな なんぢの目は面帕のうしろにありて鴿のごとし なんぢの髮はギレアデ山の腰に臥たる山羊の群に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'なんぢの齒は毛を剪たる牝羊の浴塲より出たるがごとし おのおの雙子をうみてひとつも子なきものはなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'なんぢの唇は紅色の線維のごとく その口は美はし なんぢの頬は面帕のうしろにありて石榴の半片に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'なんぢの頸項は武器庫にとて建たるダビデの戍樓のごとし その上には一千の盾を懸け列ぬ みな勇士の大楯なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'なんぢの兩乳房は牝獐の雙子なる二箇の小鹿が百合花の中に草はみをるに似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, '日の涼しくなるまで 影の消るまでわれ沒藥の山また乳香の岡に行べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'わが佳耦よ なんぢはことごとくうるはしくしてすこしのきずもなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, '新婦よ レバノンより我にともなへ レバノンより我とともに來れ アマナの巓セニルまたヘルモンの巓より望み 獅子の穴また豹の山より望め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'わが妹わが新婦よ なんぢはわが心を奪へり なんぢは只一目をもてまた頸玉の一をもてわが心をうばへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'わが妹わが新婦よ なんぢの愛は樂しきかな なんぢの愛は酒よりも遙にすぐれ なんぢの香膏の馨は一切の香物よりもすぐれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, '新婦よ なんぢの唇は蜜を滴らす なんぢの舌の底には蜜と乳とあり なんぢの衣裳の香氣はレバノンの香氣のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'わが妹わがはなよめよ なんぢは閉たる園 閉たる水源 封じたる泉水のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'なんぢの園の中に生いづる者は石榴及びもろもろの佳果またコペル及びナルダの草');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'ナルダ 番紅花 菖蒲 桂枝さまざまの乳香の木および沒藥 蘆薈一切の貴とき香物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'なんぢは園の泉水 活る水の井 レバノンよりいづる流水なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, '北風よ起れ 南風よ來れ 我園を吹てその香氣を揚よ ねがはくはわが愛する者のおのが園にいりきたりてその佳き果を食はんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'わが妹わがはなよめよ 我はわが園にいり わが沒藥と薫物とを採り わが蜜房と蜜とを食ひ わが酒とわが乳とを飮り わが伴侶等よ 請ふ食へ わが愛する人々よ 請ふ飮あけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'われは睡りたれどもわが心は醒ゐたり 時にわが愛する者の聲あり 即はち門をたたきていふ わが妹わが佳耦 わが鴿 わが完きものよ われのために開け わが首には露滿ち わが髮の毛には夜の點滴みてりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'われすでにわが衣服を脱り いかでまた着るべき 已にわが足をあらへり いかでまた汚すべき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'わが愛する者戸の穴より手をさしいれしかば わが心かれのためにうごきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'やがて起いでてわが愛する者の爲に開かんとせしとき 沒藥わが手より沒藥の汁わが指よりながれて關木の把柄のうへにしたたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, '我わが愛する者の爲に開きしに わが愛する者は已に退き去りぬ さきにその物いひし時はわが心さわぎたり 我かれをたづねたれども遇ず 呼たれども答應なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, '邑をまはりありく夜巡者等われを見てうちて傷つけ 石垣をまもる者らはわが上衣をはぎとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'ヱルサレムの女子等よ 我なんぢらにかたく請ふ もしわが愛する者にあはば汝ら何とこれにつぐべきや 我愛によりて疾わづらふと告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'なんぢの愛する者は別の人の愛する者に何の勝れるところありや 婦女の中のいと美はしき者よ なんぢが愛する者は別の人の愛する者に何の勝れるところありて斯われらに固く請ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'わが愛する者は白くかつ紅にして萬人の上に越ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'その頭は純金のごとく その髮はふさやかにして黑きこと烏のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'その目は谷川の水のほとりにをる鴿のごとく 乳にて洗はれて美はしく嵌れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'その頬は馨しき花の床のごとく 香草の壇のごとし その唇は百合花のごとくにして沒藥の汁をしたたらす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'その手はきばみたる碧玉を嵌し黄金の釧のごとく 其躰は靑玉をもておほひたる象牙の彫刻物のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'その脛は蝋石の柱を黄金の臺にてたてたるがごとく その相貌はレバノンのごとく その優れたるさまは香柏のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'その口ははなはだ甘く誠に彼には一つだにうつくしからぬ所なし ヱルサレムの女子等よ これぞわが愛する者 これぞわが伴侶なる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, '婦女のいと美はしきものよ 汝の愛する者は何處へゆきしや なんぢの愛する者はいづこへおもむきしや われら汝とともにたづねん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'わが愛するものは己の園にくだり 香しき花の床にゆき 園の中にて群を牧ひ また百合花を採る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, '我はわが愛する者につき わが愛する者はわれにつく 彼は百合花の中にてその群を牧ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'わが佳耦よ なんぢは美はしきことテルザのごとく 華やかなることヱルサレムのごとく 畏るべきこと旗をあげたる軍旅のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'なんぢの目は我をおそれしむ 請ふ我よりはなれしめよ なんぢの髮はギレアデ山の腰に臥たる山羊の群に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'なんぢの齒は毛を剪たる牝羊の浴塲より出たるがごとし おのおの雙子をうみてひとつも子なきものはなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'なんぢの頬は面帕の後にありて石榴の半片に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, '后六十人 妃嬪八十人 數しられぬ處女あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'わが鴿わが完き者はただ一人のみ 彼はその母の獨子にして產たる者の喜ぶところの者なり 女子等は彼を見て幸福なる者ととなへ 后等妃嬪等は彼を見て讃む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'この晨光のごとくに見えわたり 月のごとくに美はしく 日のごとくに輝やき 畏るべきこと旗をあげたる軍旅のごとき者は誰ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'われ胡桃の園にくだりゆき 谷の靑き草木を見 葡萄や芽しし石榴の花や咲しと見回しをりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, '意はず知ず我が心われをしてわが貴とき民の車の中間にあらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '歸れ歸れシユラミの婦よ 歸れ歸れ われら汝を觀んことをねがふ なんぢら何とてマハナイムの跳舞を觀るごとくにシユラミの婦を觀んとねがふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '君の女よ なんぢの足は鞋の中にありて如何に美はしきかな 汝の腿はまろらかにして玉のごとく 巧匠の手にて作りたるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'なんぢの臍は美酒の缺ることあらざる圓き杯盤のごとく なんぢの腹は積かさねたる麥のまはりを百合花もてかこめるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'なんぢの兩乳房は牝鹿の雙子なる二の小鹿のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'なんぢの頸は象牙の戍樓の如く 汝の目はヘシボンにてバテラビムの門のほとりにある池のごとく なんぢの鼻はダマスコに對へるレバノンの戍樓のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'なんぢの頭はカルメルのごとく なんぢの頭の髮は紫花のごとし 王その垂たる髮につながれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'ああ愛よ もろもろの快樂の中にありてなんぢは如何に美はしく如何に悦ばしき者なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'なんぢの身の長は棕櫚の樹に等しく なんぢの乳房は葡萄のふさのごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'われ謂ふこの棕櫚の樹にのぼり その枝に執つかんと なんぢの乳房は葡萄のふさのごとく なんぢの鼻の氣息は林檎のごとく匂はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'なんぢの口は美酒のごとし わが愛する者のために滑かに流れくだり 睡れる者の口をして動かしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'われはわが愛する者につき 彼はわれを戀したふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'わが愛する者よ われら田舍にくだり 村里に宿らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'われら夙におきて葡萄や芽しし莟やいでし石榴の花やさきし いざ葡萄園にゆきて見ん かしこにて我わが愛をなんぢにあたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, '戀茄かぐはしき香氣を發ち もろもろの佳き果物古き新らしき共にわが戸の上にあり わが愛する者よ我これをなんぢのためにたくはへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'ねがはくは汝わが母の乳をのみしわが兄弟のごとくならんことを われ戸外にてなんぢに遇ふとき接吻せん 然するとも誰ありてわれをいやしむるものあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'われ汝をひきてわが母の家にいたり 汝より敎晦をうけん 我かぐはしき酒 石榴のあまき汁をなんぢに飮しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'かれが左の手はわが頭の下にあり その右の手をもて我を抱く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'ヱルサレムの女子等よ 我なんぢ等に誓ひて請ふ 愛のおのづから起る時まで殊更に喚起し且つ醒すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'おのれの愛する者に倚かかりて荒野より上りきたる者は誰ぞや 林檎の樹の下にてわれなんぢを喚さませり なんぢの母かしこにて汝のために劬勞をなし なんぢを產し者かしこにて劬勞をなしぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'われを汝の心におきて印のごとくし なんぢの腕におきて印のごとくせよ 其の愛は強くして死のごとく 嫉妬は堅くして陰府にひとし その熖は火のほのほのごとし いともはげしき熖なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, '愛は大水も消ことあたはず 洪水も溺らすことあたはず 人その家の一切の物をことごとく與へて愛に換んとするとも尚いやしめらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'われら小さき妹子あり 未だ乳房あらず われらの妹子の問聘をうくる日には之に何をなしてあたへんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'かれもし石垣ならんには我ら白銀の城をその上にたてん 彼もし戸ならんには香柏の板をもてこれを圍まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'われは石垣わが乳房は戍樓のごとし 是をもてわれは情をかうむれる者のごとく彼の目の前にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'バアルハモンにソロモンの葡萄園をもてり これをその守る者等にあづけおき 彼等をしておのおの銀一千をその果のために納めしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'われ自らの有なる葡萄園われの手にあり ソロモンなんぢは一千を獲よ その果をまもる者も二百を獲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'なんぢ園の中に住む者よ 伴侶等なんぢの聲に耳をかたむく 請ふ我にこれを聽しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'わが愛する者よ 請ふ急ぎはしれ 香はしき山々の上にありて獐のごとく 小鹿のごとくあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'アモツの子イザヤがユダの王ウジヤ、ヨタム、アハズ、ヒゼキヤのときに示されたるユダとヱルサレムとに係る異象');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, '天よきけ地よ耳をかたぶけよ ヱホバの語りたまふ言あり 曰く われ子をやしなひ育てしにかれらは我にそむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, '牛はその主をしり驢馬はそのあるじの厩をしる 然どイスラエルは識ず わが民はさとらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'ああ罪ををかせる國人よこしまを負ふたみ 惡をなす者のすゑ 壞りそこなふ種族 かれらはヱホバをすてイスラエルの聖者をあなどり之をうとみて退きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'なんぢら何ぞかさねがさね悖りて猶撻れんとするか その頭はやまざる所なくその心はつかれはてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, '足のうらより頭にいたるまで全きところなくただ創痍と打傷と腫物とのみなり 而してこれを合すものなく包むものなく亦あぶらにて軟らぐる者もなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'なんぢらの國はあれすたれなんぢらの諸邑は火にてやかれなんぢらの田畑はその前にて外人にのまれ旣にあだし人にくつがへされて荒廢れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'シオンの女はぶだうぞのの廬のごとく瓜田の假舎のごとくまた圍をうけたる城のごとく唯ひとり遺れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, '萬軍のヱホバわれらに少しの遺をとどめ給ふことなくば我儕はソドムのごとく又ゴモラに同じかりしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'なんぢらソドムの有司よヱホバの言をきけ なんぢらゴモラの民よ われらの神の律法に耳をかたぶけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'ヱホバ言たまはくなんぢらが獻ぐるおほくの犠牲はわれに何の益あらんや 我はをひつじの燔祭とこえたるけものの膏とにあけり われは牡牛あるひは小羊あるひは牡山羊の血をよろこばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'なんぢらは我に見えんとてきたる このことを誰がなんぢらに要めしや 徒らにわが庭をふむのみなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'むなしき祭物をふたたび携ふることなかれ 燻物はわがにくむところ 新月および安息日また會衆をよびあつむることも我がにくむところなり なんぢらは聖會に惡を兼ぬ われ容すにたへず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'わが心はなんぢらの新月と節會とをきらふ 是わが重荷なり われ負にうみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, '我なんぢらが手をのぶるとき目をおほひ 汝等がおほくの祈禱をなすときも聞ことをせじ なんぢらの手には血みちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'なんぢら己をあらひ己をきよくしわが眼前よりその惡業をさり 惡をおこなふことを止め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, '善をおこなふことをならひ 公平をもとめ 虐げらるる者をたすけ 孤子に公平をおこなひ 寡婦の訟をあげつらへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'ヱホバいひたまはく 率われらともに論らはん なんぢらの罪は緋のごとくなるも雪のごとく白くなり紅のごとく赤くとも羊の毛のごとくにならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, '若なんぢら肯ひしたがはば地の美產をくらふことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'もし汝等こばみそむかば劍にのまるべし 此はヱホバその御口よりかたりたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, '忠信なりし邑いかにして妓女とはなれる 昔しは公平にてみち正義その中にやどりしに今は人をころす者ばかりとなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'なんぢの白銀は滓となり なんぢの葡萄酒は水をまじへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'なんぢの長輩はそむきて盗人の伴侶となり おのおの賄賂をよろこび 贓財をおひもとめ 孤子に公平をおこなはず 寡婦の訟はかれらの前にいづること能はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'このゆゑに主萬軍のヱホバ、イスラエルの全能者のたまはく 唉われ敵にむかひて念をはらし仇にむかひて報をすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, '我また手をなんぢの上にそへ なんぢの滓をことごとく淨くし なんぢの鉛をすべて取去り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'なんぢの審士を舊のごとく なんぢの議官を始のごとくに復すべし 然るのちなんぢは正義の邑忠信の邑ととなへられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'シオンは公平をもてあがなはれ 歸來るものも正義をもて贖はるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'されど愆ををかすものと罪人とはともに敗れ ヱホバをすつる者もまた亡びうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'なんぢらはその喜びたる橿樹によりて恥をいだき そのえらびたる園によりて慙赧むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'なんぢらは葉のかるる橿樹のごとく水なき園のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, '權勢あるものは麻のごとく その工は火花のごとく 二つのもの一同もえてこれを撲滅すものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'アモツの子イザヤが示されたるユダとヱルサレムとにかかる言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'すゑの日にヱホバの家の山はもろもろの山のいただきに堅立ち もろもろの嶺よりもたかく擧り すべての國は流のごとく之につかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'おほくの民ゆきて相語いはん 率われらヱホバの山にのぼりヤコブの神の家にゆかん 神われらにその道ををしへ給はん われらその路をあゆむべしと そは律法はシオンよりいでヱホバの言はヱルサレムより出べければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'ヱホバはもろもろの國のあひだを鞫き おほくの民をせめたまはん 斯てかれらはその劒をうちかへて鋤となし その鎗をうちかへて鎌となし 國は國にむかひて劍をあげず 戰鬪のことを再びまなばざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'ヤコブの家よきたれ 我儕ヱホバの光にあゆまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, '主よなんぢはその民ヤコブの家をすてたまへり 此はかれらのなかに東のかたの風俗みち 皆ペリシテ人のごとく陰陽師となり 異邦人のともがらと手をうちて盟をたてしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'かれらの國には黄金白銀みちて財寶の數かぎりなし かれらの國には馬みちて戰車のかず限りなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'かれらの國には偶像みち 皆おのが手の工その指のつくれる者ををがめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, '賤しきものは屈められ尊きものは卑せらる かれらを容したまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'なんぢ岩間にいり また土にかくれて ヱホバの畏るべき容貌とその稜威の光輝とをさくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'この日には目をあげて高ぶるもの卑せられ 驕る人かがめられ 唯ヱホバのみ高くあげられ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'そは萬軍のヱホバの一の日あり すべて高ぶる者おごる者みづからを崇るものの上にのぞみて之をひくくし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'またレバノンのたかく聳たるすべての香柏バシヤンのすべての橿樹');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'もろもろの高山もろもろの聳えたる嶺');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'すべてのたかき櫓すべての堅固なる石垣');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'およびタルシシのすべての舟すべての慕ふべき美はしきものに臨むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'この日には高ぶる者はかがめられ 驕る人はひくくせられ 唯ヱホバのみ高くあげられ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'かくて偶像はことごとく亡びうすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'ヱホバたちて地を震動したまふとき人々そのおそるべき容貌とその稜威の光輝とをさけて巖の洞と地の穴とにいらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'その日人々おのが拜せんとて造れる白銀のぐうざうと黄金のぐうざうとを鼹鼠のあな蝙蝠の穴になげすて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, '岩々の隙けはしき山峽にいり ヱホバの起て地をふるひうごかしたまふその畏るべき容貌と稜威のかがやきとを避ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'なんぢら鼻より息のいでいりする人に倚ることをやめよ斯るものは何ぞかぞふるに足らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'みよ主ばんぐんのヱホバ、ヱルサレムおよびユダの賴むところ倚ところなる凡てその賴むところの糧 すべてその賴むところの水');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, '勇士 戰士 審士 預言者 卜筮者 長老');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, '五十人の首 貴顯者 議官 藝に長たる者および言語たくみなるものを除去りたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'われ童子をもてかれらの君とし嬰兒にかれらを治めしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, '民たがひに相虐げ 人おのおのその隣をしへたげ 童子は老たる者にむかひて高ぶり 賤しきものは貴きものに對ひてたかぶらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'そのとき人ちちの家にて兄弟にすがりていはん 汝なほ衣あり われらの有司となりてこの荒敗をその手にてをさめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'その日かれ聲をあげていはん 我なんぢらを愈すものとなるを得じ わが家に糧なくまた衣なし 我をたてて民の有司とすることなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, '是かれらの舌と行爲とはみなヱホバにそむきてその榮光の目ををかししが故に ヱルサレムは敗れユダは仆れたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'かれらの面色はその惡きことの證をなし ソドムのごとくその罪をあらはして隱すことをせざるなり かれらの靈魂はわざはひなるかな自らその惡の報をとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'なんぢら義人にいへ かならず福祉をうけんと 彼等はそのおこなひの實をくらふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, '惡者はわざはひなる哉かならず災禍をうけん その手の報きたるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'わが民はをさなごに虐げられ婦女にをさめらる 唉わが民よなんぢを導くものは反てなんぢを迷はせ汝のゆくべき途を絶つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'ヱホバ立いでて公理をのべ起てもろもろの民を審判し給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'ヱホバ來りておのが民の長老ともろもろの君とをさばきて言給はん なんぢらは葡萄園をくひあらせり 貧きものより掠めとりたる物はなんぢらの家にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'いかなれば汝等わが民をふみにじり貧きものの面をすりくだくやと これ主萬軍のヱホバのみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'ヱホバまた言給はくシォンの女輩はおごり 項をのばしてあるき 眼にて媚をおくり 徐々としてあゆみゆくその足にはりんりんと音あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'このゆゑに主シオンのむすめらの頭をかぶろにしヱホバ彼らの醜所をあらはし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'その日主かれらが足にかざれる美はしき釧をとり 瓔珞 半月飾');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, '耳環 手釧 面帕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, '華冠 脛飾 紳 香盒 符嚢');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, '指環 鼻環');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, '公服 上衣 外帔 金嚢');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, '鏡 細布の衣 首帕 被衣などを取除きたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, '而して馨はしき香はかはりて臭穣となり 紳はかはりて繩となり 美はしく編たる髮はかぶろとなり 華かなる衣はかはりて麁布のころもとなり 麗顔はかはりて烙鐵せられたる痕とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'なんぢの男はつるぎにたふれ なんぢの勇士はたたかひに仆るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'その門はなげきかなしみ シオンは荒廢れて地にすわらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'その日七人のをんな一人の男にすがりていはん 我儕おのれの糧をくらひ己のころもを着るべし ただ我儕になんぢの名をとなふることを許してわれらの恥をとりのぞけと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'その日ヱホバの枝はさかえて輝かん 地よりなりいづるものの實はすぐれ並うるはしくして逃れのこれるイスラエルの益となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, '而してシオンに遣れるもの ヱルサレムにとどまれる者 すべて此等のヱルサレムに存ふる者のなかに録されたるものは聖ととなへられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'そは主さばきするみたまと燒つくす靈とをもてシオンのむすめらの汚をあらひ ヱルサレムの血をその中よりのぞきたまふ期きたるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, '爰にヱホバはシオンの山のすべての住所と もろもろの聚會とのうへに 晝は雲と煙とをつくり夜はほのほの光をつくり給はん あまねく榮のうへに覆庇あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'また一つの假廬ありて 晝はあつさをふせぐ陰となり 暴風と雨とをさけてかくるる所となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'われわが愛する者のために歌をつくり 我があいするものの葡萄園のことをうたはん わが愛するものは土肥たる山にひとつの葡萄園をもてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, '彼その園をすきかへし石をのぞきて嘉ぶだうをうゑ そのなかに望樓をたて酒榨をほりて嘉葡萄のむすぶを望みまてり 然るに結びたるものは野葡萄なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'さればヱルサレムに住るものとユダの人よ 請なんぢら我とわがぶだうぞのとの間をさばけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'わが葡萄園にわれの作たるほか何のなすべき事ありや 我はよきぶだうの結ぶをのぞみまちしに 何なれば野葡萄をむすびしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, '然ばわれわが葡萄園になさんとすることを汝等につげん 我はぶだうぞのの籬芭をとりさりてその食あらさるるにまかせ その垣をこぼちてその踐あらさるるにまかせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, '我これを荒してふたたび剪ことをせず耕すことをせず棘と荊とをはえいでしめん また雲に命せてそのうへに雨ふることなからしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'それ萬軍のヱホバの葡萄園はイスラエルの家なり その喜びたまふところの植物はユダの人なり これに公平をのぞみたまひしに反りて血をながし これに正義をのぞみ給ひしにかへりて號呼あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, '禍ひなるかな彼らは家に家をたてつらね 田圃に田圃をましくはへて 餘地をあまさず 己ひとり國のうちに住んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, '萬軍のヱホバ我耳につげて宣はく 實におほくの家はあれすたれ大にして美しき家は人のすむことなきにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, '十段のぶだうぞの僅かに一バテをみのり一ホメルの穀種はわづかに一エパを實るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, '禍ひなるかなかれらは朝つとにおきて濃酒をおひもとめ 夜のふくるまで止まりてのみ 酒にその身をやかるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'かれらの酒宴には琴あり 瑟あり 鼓あり 笛あり 葡萄酒あり されどヱホバの作爲をかへりみずその手のなしたまふところに目をとめず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, '斯るが故にわが民は無知にして虜にせられ その貴顯者はうゑ そのもろもろの民は渇によりて疲れはてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'また陰府はその欲望をひろくし その度られざる口をはる かれらの榮華 かれらの群衆 かれらの饒富 および喜びたのしめる人みなその中におつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, '賤しき者はかがめられ 貴きものは卑くせられ 目をあげて高ぶる者はひくくせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'されど萬軍のヱホバは公平によりてあがめられ 聖なる神は正義によりて聖とせられ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, '而して小羊おのが牧場にあるごとくに草をはみ 豐かなるものの田はあれて旅客にくらはれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, '禍ひなるかな彼等はいつはりを繩となして惡をひき 索にて車をひくごとく罪をひけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'かれらは云 その成んとする事をいそぎて速かになせ 我儕これを見ん イスラエルの聖者のさだむることを逼來らせよ われらこれを知んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, '禍ひなるかな かれらは惡をよびて善とし善をよびて惡とし 暗をもて光とし光をもて暗とし 苦をもて甘とし甘をもて苦とする者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'わざはひなる哉 かれらは己をみて智しとし自らかへりみて聰とする者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, '禍ひなるかな かれらは葡萄酒をのむに丈夫なり 濃酒を和するに勇者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'かれらは賄賂によりて惡きものを義となし 義人よりその義をうばふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, '此によりて火舌の刈株をくらふがごとく また枯草の火焰のなかにおつるがごとく その根はくちはてその花は塵のごとくに飛さらん かれらは萬軍のヱホバの律法をすててイスラエルの聖者のことばを蔑したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'この故にヱホバその民にむかひて怒をはなち 手をのべてかれらを撃たまへり 山はふるひうごきかれらの屍は衢のなかにて糞土のごとくなれり 然はあれどヱホバの怒やまずして尚その手を伸したまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'かくて旗をたててとほき國々をまねき彼等をよびて地の極より來らしめたまはん 視よかれら趨りて速かにきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'その中には疲れたふるるものなく眠りまたは寢るものなし その腰の帶はとけずその履の紐はきれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'その矢は鋭その弓はことごとく張り その馬のひづめは石のごとくその車の輪は疾風のごとしと稱へられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'その嘷ること獅のごとく また小獅のごとく嘷うなりつつ獲物をつかみて掠去れども之をすくふ者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'その日かれらが嘯響めくこと海のなりどよめくがごとし もし地をのぞまば暗と難とありて光は黑雲のなかにくらくなりたるを見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'ウジヤ王のしにたる年われ高くあがれる御座にヱホバの坐し給ふを見しにその衣裾は殿にみちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'セラピムその上にたつ おのおの六の翼あり その二をもて面をおほひ その二をもて足をおほひ 其二をもて飛翔り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'たがひに呼いひけるは聖なるかな聖なるかな聖なるかな萬軍のヱホバ その榮光は全地にみつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, '斯よばはる者の聲によりて閾のもとゐ搖うごき家のうちに煙みちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'このとき我いへり 禍ひなるかな我ほろびなん 我はけがれたる唇の民のなかにすみて穢たるくちびるの者なるに わが眼ばんぐんのヱホバにまします王を見まつればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, '爰にかのセラピムのひとり鉗をもて壇の上よりとりたる熱炭を手にたづさへて我にとびきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'わが口に觸ていひけるは 視よこの火なんぢの唇にふれたれば旣になんぢの惡はのぞかれ なんぢの罪はきよめられたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, '我またヱホバの聲をきく曰く われ誰をつかはさん誰かわれらのために往べきかと そのとき我いひけるはわれ此にあり我をつかはしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'ヱホバいひたまはく往てこの民にかくのごとく告よ なんぢら聞てきけよ然どさとらざるべし 見てみよ然どしらざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'なんぢこの民のこころを鈍くしその耳をものうくし その眼をおほへ 恐らくは彼らその眼にて見その耳にてきき その心にてさとり翻へりて醫さるることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'ここに我いひけるは 主よいつまで如此あらんか 主こたへたまはく 邑はあれすたれて住むものなく 家に人なく 邦ことごとく荒土となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, '人々ヱホバに遠方までうつされ 廢りたるところ國中におほくならん時まで 如此あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'そのなかに十分の一のこる者あれども此もまた呑つくされん されど聖裔のこりてこの地の根となるべし彼のテレビントまたは橿樹がきらるることありともその根ののこるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'ウジヤの子ヨタムその子ユダヤ王アハズのとき アラムの王レヂンとレマリヤの子イスラエル王ペカと上りきたりてヱルサレムを攻しがつひに勝ことあたはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'ここにアラムとエフライムと結合なりたりとダビデの家につぐる者ありければ 王のこころと民の心とは林木の風にうごかさるるが如くに動けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'その時ヱホバ、イザヤに言たまひけるは今なんぢと汝の子シヤルヤシユブと共にいでて布をさらす野の大路のかたはらなる上池の樋口にゆきてアハズを迎へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'これに告べし なんぢ 謹みて靜かなれ アラムのレヂン及びレマリヤの子はげしく怒るとも二の燼餘りたる煙れる片柴のごとし 懼るるなかれ心をよわくするなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'アラム、エフライム及びレマリヤの子なんぢにむかひて惡き謀ごとを企てていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'われらユダに攻上りて之をおびやかし我儕のためにこれを破りとり タビエルの子をその中にたてて王とせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'されど主ヱホバいひたまはく この事おこなはれずまた成ことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'アラムの首はダマスコ、ダマスコの首はレヂンなり エフライムは六十五年のうちに敗れて國をなさざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'またエフライムの首はサマリヤ、サマリヤの首はレマリヤの子なり 若なんぢら信ぜずばかならず立ことを得じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'ヱホバ再びアハズに告ていひたまはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'なんぢの神ヱホバに一の豫兆をもとめよ 或はふかき處あるひは上のたかき處にもとめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'アハズいひけるは我これを求めじ 我はヱホバを試むることをせざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'イザヤいひけるは ダビデのいへよ請なんぢら聞 なんぢら人をわづらはしこれを小事として亦わが神をも煩はさんとするか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'この故に主みづから一の豫兆をなんぢらに賜ふべし 視よをとめ孕みて子をうまん その名をインマヌエルと稱ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'かれ惡をすて善をえらぶことを知ころほひにいたりて乳酥と蜂蜜とをくらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'そはこの子いまだ惡をすて善をえらぶことを知ざるさきになんぢが忌きらふ兩の王の地はすてらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'ヱホバはエフライムがユダを離れし時よりこのかた臨みしことなき日を汝となんぢの民となんぢの父の家とにのぞませ給はん是アツスリヤの王なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, '其日ヱホバ、エジプトなる河々のほとりの蠅をまねきアツスリヤの地の蜂をよびたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, '皆きたりて荒たるたに岩穴すべての荊棘すべての牧場のうへに止まるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'その日主はかはの外ふより雇へるアツスリヤの王を剃刀として首と足の毛とを剃たまはん また髯をも除きたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'その日人わかき牝犢ひとつと羊ふたつとを飼をらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'その出すところの乳おほきによりて乳酥をくらふことを得ん すべて國のうちに遺れるものは乳酥と蜂蜜とをくらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'その日千株に銀一千の價をえたる葡萄ありし處もことごとく荊と棘はえいづべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, '荊とおどろと地にあまねきがゆゑに人々矢と弓とをもて彼處にゆくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, '鋤をもて掘たがへしたる山々もいばらと棘のために人おそれてその中にゆくことを得じ その地はただ牛をはなち羊にふましむる處とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'ヱホバ我にいひたまひけるは一の大なる牌をとり そのうへに平常の文字にてマヘル シャラル ハシ バズと録せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'われ信實の證者なる祭司ウリヤおよびエベレキヤの子ゼカリヤをもてその證をなさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'われ預言者の妻にちかづきしとき彼はらみて子をうみければ ヱホバ我にいひたまはく その名をマヘル シャラル ハシ バズと稱へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'そはこの子いまだ我が父わが母とよぶことを知らざるうちに ダマスコの富とサマリヤの財寳はうばはれてアツスリヤ王のまへに到るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'ヱホバまた重て我につげたまへり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'この民はゆるやかに流るるシロアの水をすててレヂンとレマリヤの子とをよろこぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, '此によりて主はいきほひ猛くみなぎりわたる大河の水をかれらのうへに堰入たまはん 是はアツスリヤ王とそのもろもろの威勢とにして 百の支流にはびこり もろもろの岸をこえ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'ユダにながれいり 溢れひろごりてその項にまで及ばん インマヌエルよ そののぶる翼はあまねくなんぢの地にみちわたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'もろもろの民よ さばめき騒げなんぢら摧かるべし 遠きくにぐにの者よ きけ 腰におびせよ 汝等くだかるべし 腰に帶せよ なんぢら摧かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'なんぢら互にはかれ つひに徒勞ならん なんぢら言をいだせ遂におこなはれじ そは神われらとともに在せばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'ヱホバつよき手をもて此如われに示し この民の路にあゆまざらんことを我にさとして言給はく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '此民のすべて叛逆ととなふるところの者をなんぢら叛逆ととなふるなかれ 彼等のおそるるところを汝等おそるるなかれ慴くなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'なんぢらはただ萬軍のヱホバを聖としてこれを畏みこれを恐るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, '然らばヱホバはきよき避所となりたまはん 然どイスラエルの兩の家には躓く石となり妨ぐる磐とならん ヱルサレムの民には網罟となり機濫とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'おほくの人々これによりて蹶きかつ仆れやぶれ 網せられまた捕へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, '證詞をつかね律法をわが弟子のうちに封べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'いま面をおほひてヤコブの家をかへりみ給はずといへども 我そのヱホバを待そのヱホバを望みまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, '視よわれとヱホバが我にたまひたる子輩とはイスラエルのうちの豫兆なり奇しき標なり 此はシオンの山にいます萬軍のヱホバの與へたまふ所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'もし人なんぢらにつげて巫女および魔術者のさえづるがごとく細語がごとき者にもとめよといはば民はおのれの神にもとむべきにあらずや いかで活者のために死者にもとむることを爲んといへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'ただ律法と證詞とを求むべし 彼等のいふところ此言にかなはずば晨光あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'かれら國をへあるきて苦みうゑん その饑るとき怒をはなち己が王おのが神をさして誼ひかつその面をうへに向ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'また地をみれば艱難と幽暗とくるしみの闇とあり かれらは昏黑におひやられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, '今くるしみを受れども後には闇なかるべし 昔しはゼブルンの地ナフタリの地をあなどられしめ給ひしかど 後には海にそひたる地ヨルダンの外の地 ことくに人のガリラヤに榮をうけしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, '幽暗をあゆめる民は大なる光をみ 死蔭の地にすめる者のうへに光てらせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'なんぢ民をましその歡喜を大にしたまひければ かれらは收穫時によろこぶがごとく掠物をわかつときに樂むがごとく汝の前によろこべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'そは汝かれらがおへる軛とその肩の笞と虐ぐるものの杖とを折り これを折りてミデアンの日のごとくなし給ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'すべて亂れたたかふ兵士のよろひと血にまみれたる衣とはみな火のもえくさとなりて焚るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'ひとりの嬰兒われらのために生れたり 我儕はひとりの子をあたへられたり 政事はその肩にあり その名は奇妙また議士 また大能の神とこしへのちち 平和の君ととなへられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'その政事と平和とはましくははりて窮りなし 且ダビデの位にすわりてその國ををさめ今よりのちとこしへに公平と正義とをもてこれを立これを保ちたまはん 萬軍のヱホバの熱心これを成たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, '主一言をヤコブにおくり之をイスラエルの上にのぞませ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'すべてのこの民エフライムとサマリヤに居るものとは知ならん かれらは高ぶり誇る心をもていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '瓦くづるるともわれら斫石をもて建 くはの木きらるるともわれら香柏をもて之にかへんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'この故にヱホバ、レヂンの敵をあげもちゐてイスラエルを攻しめ その仇をたけび勇しめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, '前にアラム人あり後にペシリテ人あり 口をはりてイスラエルを呑んとす 然はあれどヱホバの怒やまずして尚その手をのばしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, '然どこの民はおのれをうつものに歸らず萬軍のヱホバを求めず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, '斯るゆゑにヱホバ一日のうちに首と尾と椶櫚のえだと葦とをイスラエルより斷切たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'その首とは老たるもの尊きもの その尾とは謊言をのぶる預言者をいふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'この民をみちびく者はこれを迷はせその引導をうくる者はほろぶるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'このゆゑに主はその少壯者をよろこびたまはず その孤兒と寡婦とを憐みたまはざるべし 是その民はことごとく邪まなり惡をおこなふ者なり おのおのの口は愚かなる言をかたればなり 然はあれどヱホバの怒やまずして尚その手をのばしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, '惡は火のごとくもえ棘と荊とを食つくし茂りあふ林をやくべければみな煙となりむらがりて上騰らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, '萬軍のヱホバの怒によりて地はくろく燒 その民は火のもえくさとなり人々たがひに相憐むことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, '人みぎに攫めどもなほ饑 ひだりに食へども尚あかず おのおのその腕の肉をくらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'マナセはエフライムを エフライムはマナセをくらひ 又かれら相合てユダを攻めん 然はあれどヱホバの怒やまずして尚その手をのばしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, '不義のおきてをさだめ暴虐のことばを録すものは禍ひなるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'かれらは乏きものの訴をうけず わが民のなかの貧しきものの權利をはぎ寡婦の資產をうばひ孤兒のものを掠む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'なんぢら懲しめらるる日きたらば何をなさんとするか 敗壞とほきより來らんとき何をなさんとするか なんぢら逃れゆきて誰にすくひを求めんとするか また何處になんぢらの榮をのこさんとするか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'ただ縛められたるものの下にかがみ 殺されたるもののしたに伏仆れんのみ 然はあれどヱホバのいかり止ずして尚ほその手をのばしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, '咄アツスリヤ人 なんぢはわが怒の杖なり その手の笞はわが忿恚なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'われ彼をつかはして邪曲なる國をせめ我かれに命じて我がいかれる民をせめてその所有をかすめその財寶をうばはしめ かれらを街の泥のごとくに蹂躪らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'されどアツスリヤ人のこころざしは斯のごとくならず その心の念もまた斯のごとくならず そのこころは敗壞をこのみ あまたの國をほろぼし絶ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'かれ云 わが諸侯はみな王にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'カルノはカルケミシの如く ハマテはアルパデの如く サマリヤはダマスコの如きにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'わが手は偶像につかふる國々を得たり その彫たる像はヱルサレムおよびサマリヤのものに勝れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'われ旣にサマリヤとその偶像とに行へるごとく亦ヱルサレムとその偶像とにおこなはざる可んやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'このゆゑに主いひたまふ 我シオンの山とヱルサレムとに爲んとする事をことごとく遂をはらんとき 我アツスリヤ王のおごれる心の實とその高ぶり仰ぎたる眼とを罰すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'そは彼いへらく われ手の力と智慧とによりて之をなせり 我はかしこし 國々の境をのぞき その獲たるものをうばひ 又われは丈夫にしてかの位に坐するものを下したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'わが手もろもろの民のたからを得たりしは巣をとるが如く また天が下を取收めたりしは遺しすてたる卵をとりあつむるが如くなりき あるひは翼をうごかし あるひは口をひらき あるひは喃々する者もなかりしなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, '斧はこれをもちゐて伐ものにむかひて己みづから誇ることをせんや 鋸は これを動かす者にむかひて己みづから高ぶることをせんや 此はあだかも笞がおのれを擧るものを動かし杖みづから木にあらざるものを擧んとするにひとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'このゆゑに主萬軍のヱホバは肥たるものを瘠しめ 且その榮光のしたに火のもゆるが如き火焰をおこし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'イスラエルの光は火のごとく その聖者はほのほの如くならん 斯て一日のうちに荊とおどろとを燒ほろぼし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, '又かの林と土肥たる田圃の榮をうせしめ 靈魂をも身をもうせしめて病るものの衰へたるが如くなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'かつ林のうちに殘れる木わづかにして童子も算へうるが如くになるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'その日イスラエルの遺れる者とヤコブの家ののがれたる者とは再びおのれを撃し者にたよらず誠意をもてイスラエルの聖者ヱホバにたよらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'その遺れるものヤコブの遺れるものは大能の神にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'ああイスラエルよ なんぢの民は海の沙のごとしといへども遺りて歸りきたる者はただ僅少ならん そは敗壞すでにさだまり義にて溢るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, '主萬軍のヱホバの定めたまへる敗壞はこれを徧く國内におこなひ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'このゆゑに主萬軍のヱホバいひたまはく シオンに住るわが民よアツスリヤ人エジプトの例にならひ笞をもて汝をうち杖をあげて汝をせむるとも懼るるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'ただ頃刻にして忿恚はやまん 我がいかりは彼等をほろぼして息ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, '萬軍のヱホバむかしミデアン人をオレブの巖のあたりにて撃たまひしごとくに禍害をおこして之をせめ 又その杖を海のうへに伸しエジプトの例にしたがひてこれを擧たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'その日かれの重荷はなんぢの肩より下 かれの軛はなんぢの頸よりはなれ その軛はあぶらの故をもて壞れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'かれアイにきたりミグロンを過ミクマシにてその輜重をとどめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, '渡口をすぎてゲバに宿る ここに於てラマはをののきサウルギべア人は逃れはしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'ガリムの女よなんぢ聲をあげて叫べ ライシよ耳をかたぶけて聽け アナトテよなんぢも聲をあげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'マデメナはさすらひゲビムの民はのがれ走れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'この日かれノブに立とどまり シオンのむすめの山ヱルサレムの岡にむかひて手をふりたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, '主ばんぐんのヱホバは雄々しくたけびてその枝を斷たまはん 丈高きものは伐おとされ聳えたる者はひくくせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'また銕をもて茂りあふ林をきり給はん レバノンは能力あるものに倒さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'ヱツサイの株より一つの芽いで その根より一つの枝はえて實をむすばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'その上にヱホバの靈とどまらん これ智慧聰明の靈 謀略才能の靈 知識の靈 ヱホバをおそるるの靈なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'かれはヱホバを畏るるをもて歡樂とし また目みるところによりて審判をなさず 耳きくところによりて斷定をなさず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, '正義をもて貧しき者をさばき 公平をもて國のうちの卑しき者のために斷定をなし その口の杖をもて國をうちその口唇の氣息をもて惡人をころすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, '正義はその腰の帶となり 忠信はその身のおびとならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'おほかみは小羊とともにやどり 豹は小山羊とともにふし 犢 をじし 肥たる家畜ともに居てちひさき童子にみちびかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, '牝牛と熊とはくひものを同にし 熊の子と牛の子とともにふし 獅はうしのごとく藁をくらひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, '乳兒は毒蛇のほらにたはふれ 乳ばなれの兒は手をまむしの穴にいれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, '斯てわが聖山のいづこにても害ふことなく傷ることなからん そは水の海をおほへるごとくヱホバをしるの知識地にみつべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'その日ヱツサイの根たちてもろもろの民の旂となり もろもろの邦人はこれに服ひきたり榮光はそのとどまる所にあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'その日主はまたふたたび手をのべてその民ののこれる僅かのものをアツスリヤ、エジプト、パテロス、エテオピア、エラム、シナル、ハマテおよび海のしまじまより贖ひたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'ヱホバは國々の爲に旂をたててイスラエルの逐やられたる者をあつめ地の四極よりユダの散失たるものを集へたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'またエフライムの猜はうせ ユダを惱ますものは斷れ エフライムはユダをそねまず ユダはエフライムを惱ますことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'かれらは西なるペリシテ人の境にとびゆき相共にひがしの子輩をかすめ その手をエドムおよびモアブにのべアンモンの子孫をおのれに服はしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'ヱホバ、エジプトの海汊をからし河のうへに手をふりて熱風をふかせ その河をうちて七の小流となし 履をはきて渉らしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, '斯てその民ののこれる僅かのものの爲にアツスリヤより來るべき一つの大路あり 昔しイスラエルがエジプトの地よりいでし時のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'その日なんぢ言ん ヱホバよ我なんぢに感謝すべし 汝さきに我をいかり給ひしかどその怒はやみて我をなぐさめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, '視よ神はわが救なり われ依賴ておそるるところなし 主ヱホバはわが力わが歌なり ヱホバは亦わが救となりたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, '此故になんぢら欣喜をもて救の井より水をくむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'その日なんぢらいはん ヱホバに感謝せよ その名をよべ その行爲をもろもろの民の中につたへよ その名のあがむべきことを語りつげよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'ヱホバを頌うたへ そのみわざは高くすぐれたればなり これを全地につたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'シオンに住るものよ聲をあげてよばはれ イスラエルの聖者はなんぢの中にて大なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'アモツの子イザヤが示されたるバビロンにかかる重負の預言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'なんぢらかぶろの山に旂をたて聲をあげ手をふり彼等をまねきて貴族の門にいらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'われ旣にきよめ別ちたるものに命じ わが丈夫ほこりかにいさめる者をよびて わが怒をもらさしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, '山におほくの人の聲きこゆ大なる民あるがごとし もろもろの國民のよりつどひて喧めく聲きこゆ これ萬軍のヱホバたたかひの軍兵を召したまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'かれらはとほき國より天の極よりきたる これヱホバとその忿恚をもらす器とともに全國をほろぼさんとて來るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'なんぢら泣號ぶべしヱホバの日ちかづき全能者よりいづる敗亡きたるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'この故にすべての手はたれ凡の人のこころは消ゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'かれら慴きおそれ艱難と憂とにせまられ 子をうまんとする婦のごとく苦しみ互におどろき 相みあひてその面は燄のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, '視よヱホバの日苛くして忿恚とはげしき怒とをもて來り この國をあらしその中よりつみびとを絶滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, '天のもろもろの星とほしの宿は光をはなたず 日はいでてくらく月は その光をかがやかさざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'われ惡ことのために世をつみし 不義のために惡きものをばつし 驕れるものの誇をとどめ 暴ぶるものの傲慢をひくくせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'われ人をして精金よりもすくなくオフルの黄金よりも少なからしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'かくて亦われ萬軍のヱホバの忿恚のとき烈しき怒りの日に天をふるはせ地をうごかしてその處をうしなはしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'かれらは逐るる鹿のごとく集むるものなき羊のごとくなりて各自おのれの民にかへりおのれの國にのがれゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'すべて其處にあるもの見出さるれば 刺れ 拘留らるるものは劍にたふされ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, '彼等の嬰兒はその目前にてなげくだかれ その家財はかすめうばはれ その妻はけがさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, '視よわれ白銀をもかへりみず黄金をもよろこばざるメデア人をおこして之にむかはしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'かれらは弓をもて若きものを射くだき腹の實をあはれむことなく小子をみてをしむことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'すべての國の中にてうるはしくカルデヤ人がほこり飾となせるバビロンはむかし神にほろぼされたるソドム、ゴモラのごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'ここに住むもの永くたえ世々にいたるまで居ものなく アラビヤ人もかしこに幕屋をはらず牧人もまたかしこにはその群をふさすることなく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'ただ猛獸かしこにふし 吼るものその家にみち 鴕鳥かしこにすみ 牡山羊かしこに躍らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, '豺狼その城のなかになき野犬えいぐわの宮にさけばん その時のいたるは近きにあり その日は延ることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'ヱホバ、ヤコブを憐みイスラエルをふたたび撰びて之をおのれの地におきたまはん 異邦人これに加りてヤコブの家にむすびつらなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'もろもろの民はかれらをその處にたづさへいたらん而してイスラエルの家はヱホバの地にてこれを奴婢となし曩におのれを虜にしたるものを虜にし おのれを虐げたるものを治めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'ヱホバなんぢの憂と艱難とをのぞき 亦なんぢが勤むるからき役をのぞきて安息をたまふの日');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'なんぢこの歌をとなへバビロン王をせめていはん虐ぐる者いかにして息みしや 金をはたる者いかにして息みしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'ヱホバあしきものの笞ともろもろの有司の杖とををりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'かれらは怒をもてもろもろの民をたえず撃てはうち 忿恚をもてもろもろの國ををさむれど その暴虐をとどむる者なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, '今は全地やすみを得おだやかを得 ことごとく聲をあげてうたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, '實にまつの樹およびレバノンの香柏さへもなんぢの故により歡びていふ 汝すでに仆たれば樵夫のぼりきたりてわれらを攻ることなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, '下の陰府はなんぢの故により動きて汝のきたるをむかへ世のもろもろの英雄の亡靈をおこし國々のもろもろの王をその位より起おこらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'かれらは皆なんぢに告ていはん 汝もわれらのごとく弱くなりしや 汝もわれらと同じくなりしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'なんぢの榮華となんぢの琴の音はすでに陰府におちたり 蛆なんぢの下にしかれ蚯蚓なんぢをおほふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'あしたの子明星よいかにして天より隕しや もろもろの國をたふしし者よいかにして斫れて地にたふれしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, '汝さきに心中におもへらく われ天にのぼり我くらゐを神の星のうへにあげ北の極なる集會の山にざし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'たかき雲漢にのぼり至上者のごとくなるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, '然どなんぢは陰府におとされ坑の最下にいれられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'なんぢを見るものは熟々なんぢを視なんぢに目をとめていはん この人は地をふるはせ列國をうごかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, '世を荒野のごとくし もろもろの邑をこぼち 捕へたるものをその家にときかへさざりしものなるかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'もろもろの國の王たちはことごとく皆たふとき狀にておのおのその家にねぶる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, '然どなんぢは忌きらふべき枝のごとく おのが墓のそとにすてられその周圍には劍にて刺ころされ坑におろされ 石におほはれたる者ありて踐つけらるる屍にことならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, '汝おのれの國をほろぼし おのれの民をころししが故に かれらとおなじく葬らるることあたはず それ惡をおこなふものの裔はとこしへに名をよばるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, '先祖のよこしまの故をもて その子孫のために戮場をそなへ 彼等をしてたちて地をとり世界のおもてに邑をみたすことなからしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, '萬軍のヱホバのたまはく 我立てかれらを攻めバビロンよりその名と遺りたるものとを絶滅し その子その孫をたちほろぼさんと これヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'われバビロンを刺蝟のすみかとし沼とし且ほろびの箒をもてこれを掃除かんと これ萬軍のヱホバのみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, '萬軍のヱホバ誓をたてて言給はくわがおもひし事はかならず成 わがさだめし事はかならず立ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'われアツスリヤ人をわが地にてうちやぶり わが山々にてふみにじらん ここにおいて彼がおきし軛はイスラエル人よりはなれ 彼がおはせし重負はイスラエル人の肩よりはなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'これは全地のことにつきて定めたる謀略なり 是はもろもろの國のうへに伸したる手なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, '萬軍のヱホバさだめたまへり誰かこれを破ることを得んや その手をのばしたまへり誰かこれを押返すことを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'アハズ王の死たる年おもにの預言ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, '曰く ペリシテの全地よなんぢをうちし杖をれたればとて喜ぶなかれ 蛇の根より蝮いでその果はとびかける巨蛇となるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'いと貧しきものはものくひ乏しきものは安然にふさん われ饑饉をもてなんぢの根をしなせ汝がのこれる者をころすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, '門よなげけ邑よさけべ ペリシテよなんぢの全地きえうせたり そはけぶり北よりいできたり その軍兵の列におくるるものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'その國の使者たちに何とこたふべきや 答へていはん ヱホバ、シオンの基をおきたまへり その民のなかの苦しむものは避所をこの中にえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'モアブにかかる重負のよげん 曰く/モアブのアルは一夜の間にあらされて亡びうせ モアブのキルは一夜のまに荒されてほろびうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'かれバイテおよびデボンの高所にのぼりて哭き モアブはネボ及びメデバの上にてなげきさけぶ おのおのその頭を禿にしその鬚をことごとく剃たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'かれら麁服をきてその衢にあり 屋蓋または廣きところにて皆なきさけび悲しむこと甚だし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'ヘシボンとエレアレと叫びてその聲ヤハズにまで聞ゆ この故にモアブの軍兵こゑをあげ その靈魂うちに在てをののけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'わが心モアブのために叫びよばはれり その貴族はゾアルおよびヱグラテシリシヤにのがれ 哭つつルヒテの坂をのぼり ホロナイムの途にて敗亡の聲をあぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'ニムリムの水はかわき草はかれ苗はつきて緑蔬あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'このゆゑに彼等はその獲たる富とその藏めたる物をたづさへて柳の河をわたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'その泣號のこゑはモアブの境をめぐり 悲歎のこゑはエグライムにいたり なげきの聲はべエルエリムにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'デモンの水は血にて充 われデモンの上にひとしほ禍害をくはへ モアブの遁れたる者とこの地の遺りたるものとに獅をおくらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'なんぢら荒野のセラより羔羊をシオンの女の山におくりて國の首にをさむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'モアブの女輩はアルノンの津にありてさまよふ鳥のごとく巣をおはれたる雛のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '相謀りて審判をおこなひ 亭午にもなんぢの蔭を夜のごとくならしめ 驅逐人をかくし 遁れきたるものを顯はすなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'わが驅逐人をなんぢとともに居しめ 汝モアブの避所となりて之をそこなふ者のまへより脱れしめよ 勒索者はうせ害ふものはたえ暴虐者は地より絶れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'ひとつの位あはれみをもて堅くたち眞實をおこなふ者そのうへに坐せん 彼ダビデの幕屋にをりて審判をなし公平をもとめて義をおこなふに速し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'われらモアブの傲慢をきけり その高ぶること甚だし われらその誇とたかぶりと忿恚とをきけり その大言はむなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'この故にモアブはモアブの爲になきさけび民みな哭さけぶべし なんぢら必らず甚だしく心をいためてキルハレステの乾葡萄のためになげくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'そはヘシボンの畑とシブマのぶだうの樹とは凋みおとろへたり その枝さきにはヤゼルにまでいたりて荒野にはびこりのびて海をわたりしが 國々のもろもろの主その美はしき枝ををりたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'この故にわれヤゼルの哭とひとしくシブマの葡萄の樹のためになかん ヘシボンよエレアレよわが涙なんぢをひたさん そは鬨聲なんぢが果物なんぢが收穫の實のうへにおちきたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, '欣喜とたのしみとは土肥たる畑より取さられ 葡萄園には謳ふことなく歡呼ばふことなく酒榨にはふみて酒をしぼるものなし 我そのよろこびたつる聲をやめしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'このゆゑにわが心腸はモアブの故をもて琴のごとく鳴ひびき キルハレスの故をもてわが衷もまた然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'モアブは高處にいでて倦つかれその聖所にきたりて祈るべけれど驗あらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'こはヱホバが曩にモアブに就てかたりたまへる聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'されど今ヱホバかたりて言たまはくモアブの榮はその大なる群衆とともに傭人の期にひとしく 三年のうちに恥かしめをうけ 遺れる者はなはだ少なくして力なからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'ダマスコにかかはる重負の預言 いはく/視よダマスコは邑のすがたをうしなひて荒墟となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'アロエルの諸邑はすてられん獸畜のむれそこにすみてその伏やすめるをおびやかす者もなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'エフライムの城はすたりダマスコの政治はやみ スリアの遺れる者はイスラエルの子輩のさかえのごとく消うせん 是は萬軍のヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'その日ヤコブの榮はおとろへその肥たる肉はやせて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'あだかも收穫人の麥をかりあつめ腕をもて穂をかりたる後のごとくレパイムの谷に穂をひろひたるあとの如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'されど橄欖樹をうつとき二つ三の核を杪にのこし あるひは四つ五をみのりおほき樹の外面のえだに遺せるが如く採のこさるるものあるべし 是イスラエルの神ヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'その日人おのれを造れるものを仰ぎのぞみイスラエルの聖者に目をとめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, '斯ておのれの手の工なる祭壇をあふぎ望まず おのれの指のつくりたるアシラの像と日の像とに目をとめじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'その日かれが堅固なるまちまちは 昔イスラエルの子輩をさけてすてさりたる森のなか嶺のうへに今のこれる荒跡のごとく荒地となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'そは汝おのがすくひの神をわすれ 己がちからとなるべき磐を心にとめざりしによる このゆゑになんぢ美くしき植物をうゑ異やうの枝をさし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'かつ植たる日に籬をまはし朝に芽をいださしむれども 患難の日といたましき憂の日ときたりて收穫の果はとびさらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, '唉おほくの民はなりどよめけり海のなりどよめく如くかれらも鳴動めけり もろもろの國はなりひびけり大水のなりひびくが如くかれらも鳴響けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'もろもろの國はおほくの水のなりひびくがごとく鳴響かん されど神かれらを攻たまふべし かれら遠くのがれて風にふきさらるる山のうへの粃糠のごとく また旋風にふきさらるる塵のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, '視よゆふぐれに恐怖あり いまだ黎明にいたらずして彼等は亡たり これ我儕をかすむる者のうくべき報われらを奪ふもののひくべき鬮なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, '唉エテオピアの河の彼方なるさやさやと羽音のきこゆる地');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'この地蒹のふねを水にうかべ海路より使者をつかはさんとてその使者にいへらく 疾走る使よなんぢら河々の流のわかるる國にゆけ丈たかく肌なめらかなる 始めより今にいたるまで懼るべく繩もてはかり人を踐にじる民にゆけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'すべて世にをるもの地にすむものよ 山のうへに旗のたつとき汝等これを見ラッパの鳴響くときなんぢら之をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'そはヱホバわれに如此いひ給へりいはく 空はれわたり日てり收穫の熱むしてつゆけき雲のたるる間 われわが居所にしづかに居てながめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, '收穫のまへにその芽またく生その花ぶだうとなりて熟せんとするとき かれ鎌をもて蔓をかり枝をきり去ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, '斯てみな山のたけきとりと地の獸とになげあたへらるべし 猛鳥そのうへにて夏をすごし地のけものその上にて冬をわたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'そのとき河々の流のわかるる國の丈たかく肌なめらかなる 始めより今にいたるまで懼るべく繩もてはかり人をふみにじる民より 萬軍のヱホバにささぐる禮物をたづさへて 萬軍のヱホバの聖名のところシオンの山にきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'エジプトにかかる重負のよげん いはく/ヱホバははやき雲にのりてエジプトに來りたまふ エジプトのもろもろの偶像はその前にふるひをののき エジプト人のこころはその衷にて消ゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, '我エジプト人をたけび勇ましめてエジプト人を攻しめん斯てかれら各自その兄弟をせめおのおのその鄰をせめ 邑は邑をせめ國はくにを攻べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'エジプト人の靈魂うせてその中むなしくならん われその謀略をほろぼすべし かれらは偶像および呪文をとなふるもの巫女魔術者にもとむることを爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'われエジプト人を苛酷なる主人の手にわたさん あらあらしき王かれらを治むべし是主萬軍のヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, '海の水はつき河もまた涸てかわかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'また河々はくさき臭をはなちエジプトの堭はみな漸次にへりてかわき葦と蘆とかれはてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'ナイルのほとりの草原ナイルの岸にほどちかき所すべてナイルの最寄にまきたる者はことごとく枯てちりうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, '漁者もまた歎き すべてナイルに釣をたるる者はかなしみ網を水のうへに施ものはおとろふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, '練たる麻にて物つくるもの白布を織ものは恥あわて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'その柱はくだけ一切のやとはれたる者のこころ憂ひかなしまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, '誠やゾアンの諸侯は愚なりパロの最もかしこき議官のはかりごとは癡鈍べし 然ばなんぢら何でパロにむかひて我はかしこきものの子 われは古への王の子なりといふを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'なんぢの智者いづくにありや 彼らもし萬軍のヱホバの定めたまひしエジプトに係はることを暁得ばこれをなんぢに告るこそよけれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'ゾアンのもろもろの諸侯は愚かなり ノフの諸侯は惑ひたり かれらはエジプトのもろもろの支派の隅石なるに却てエジプトをあやまらせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'ヱホバ曲れる心をその中にまじへ給ひしにより 彼等はエジプトのすべて作ところを謬らせ恰かも酔る人の哇吐ときによろめくが如くならしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'エジプトにて或は首あるひは尾あるひは椶櫚のえだまたは葦すべてその作ところの工なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'その日エジプトは婦女のごとくならん 萬軍のヱホバの動かしたまふ手のその上にうごくが故におそれをののくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'ユダの地はエジプトに懼れらる この事をかたりつぐれば聽くもの皆おそる これ萬軍のヱホバ、エジプトに對ひて定めたまへる謀略の故によるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'その日エジプトの地に五の邑あり カナンの方言をかたりまた萬軍のヱホバに誓ひをたてん その中のひとつは日邑ととなへらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'その日エジプトの地の中にヱホバをまつる一つの祭壇あり その境にヱホバをまつる一柱あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'これエジプトの地にて萬軍のヱホバの徴となり證となるなり かれら暴虐者の故によりてヱホバに號求むべければ ヱホバは救ふもの護るものを遣してこれを助けたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'ヱホバおのれをエジプトに知せたまはん その日エジプト人はヱホバをしり犠牲と祭物とをもて之につかへん 誓願をヱホバにたてて成とぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'ヱホバ、エジプトを撃たまはん ヱホバこれを撃これを醫したまふ この故にかれらヱホバに歸らん ヱホバその懇求をいれて之をいやし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'その日エジプトよりアツスリヤにかよふ大路ありて アツスリヤ人はエジプトにきたり エジプト人はアツスリヤにゆき エジプト人とアツスリヤ人と相共につかふることをせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'その日イスラエルはエジプトとアツスリヤとを共にし三あひならび地のうへにて福祉をうくる者となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, '萬軍のヱホバこれを祝して言たまはく わが民なるエジプトわが手の工なるアツスリヤわが產業なるイスラエルは福ひなるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'アツスリヤのサルゴン王タルタンを遣してアシドドにゆかしむ 彼がアシドドを攻てとりし年にあたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'この時ヱホバ、アモツの子イザヤに托てかたりたまはく 往なんぢの腰よりあらたへの衣をとき汝の足より履をぬげ ここに於てかれその如くなし赤裸跣足にて歩めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'ヱホバ言給く わが僕イザヤは三年の間はだかはだしにてあゆみ エジプトとエテオピアとの豫兆となり奇しき標となりたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, '斯のごとくエジプトの虜とエテオピアの俘囚とはアツスリヤの王にひきゆかれ その若きも老たるもみな赤裸跣足にて臀までもあらはしエジプトの恥をしめすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'かれらはその恃とせるエテオピアその誇とせるエジプトのゆゑをもて懼れはぢん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'その日この濱邊の民いはん 視よ われらの恃とせる國われらが遁れゆきて助をもとめアツスリヤ王の手より救出されんとせし國すでに斯のごとし 我儕はいかにして脱かるるを得んやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'うみべの荒野にかかる重負のよげん いはく/荒野よりおそるべき地より南のかたの暴風のふきすぐるが如くきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'われ苛き默示をしめされたり 欺騙者はあざむき荒すものはあらすべし エラムよ上れメデアよかこめ 我すでにすべての歎息をやめしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'この故にわが腰は甚だしくいたみ 產にのぞめる婦人の如き苦しみ我にせまれり われ悶へ苦しみて聞ことあたはず我をののきて見ことあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'わが心みだれまどひて慴き怖ること甚だし わが樂しめる夕はかはりて懼れとなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, '彼らは席をまうけ筵をしきてくひのみす もろもろの君よたちて盾にあぶらぬれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'ヱホバかく我にいひ給へり 汝ゆきて斥候をおきその見るところを告しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'かれ馬にのりて二列にならび來るものを見 また驢馬にのりたると駱駝にのりたるとをみば 耳をかたぶけて詳細にきくことをせしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'かれ獅の如く呼はりて曰けるは わが主よわれ終日やぐらに立よもすがら斥候の地にたつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, '馬にのりて二列にならびたる者きたれり 彼こたへていはくバビロンは倒れたり 倒れたりそのもろもろの神の像はくだけて地にふしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, '蹂躙らるるわが民よわが打場のたなつものよ 我イスラエルの神萬軍のヱホバに聞るところのものを汝につげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'ドマに係るおもにの預言 いはく/人ありセイルより我をよびていふ 斥候よ夜はなにのときぞ 斥候よ夜はなにの時ぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'ものみ答へていふ 朝きたり夜またきたる 汝もしとはんとおもはば問 なんぢら歸りきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'アラビヤにかかる重負のよげん 曰く/デダンの客商よなんぢらはアラビヤの林にやどらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'テマの地のたみよ水をたづさへて渇ける者をむかへ 糧をもて逃遁れたるものを迎へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'かれらは刃をさけ 旣にぬきたる劍すでに張たる弓およびたたかひの艱難をさけて逃きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'そは主われにいひたまはく 傭人の期にひとしく一年のうちにケダルのすべての榮華はつきはてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'そののこれる弓士のかずとケダルの子孫のますらをとは少なかるべし 此はイスラエルの神ヱホバのかたり給へるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, '異象の谷にかかる重負のよげん 曰く/なんぢら何故にみな屋蓋にのぼれるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, '汝はさわがしく喧すしき邑ほこりたのしむ邑 なんぢのうちの殺されたるものは劍をもて殺されしにあらず 亦たたかひにて死しにもあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'なんぢの有司はみな共にのがれゆきしかど弓士にいましめられ 汝の民はとほくにげゆきしかど見出されて皆ともに縛められたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'この故にわれいふ回顧てわれを見るなかれ 我いたく哭かなしまん わが民のむすめの害はれたるによりて我をなぐさめんと勉むるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'そは主萬軍のヱホバ異象のたにに騒亂ふみにじり惶惑の日をきたらせたまふ 垣はくづれ號呼のこゑは山々にきこゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'エラムは箙をおひたり 歩兵と騎兵とありキルは盾をあらはせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'かくて戰車はなんぢの美しき谷にみち 騎兵はその門にむかひてつらなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'ユダの庇護はのぞかる その日なんぢは林のいへの武具をあふぎのぞめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'なんぢらダビデのまちの壞おほきを見る なんぢら下のいけの水をあつめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'またヱルサレムの家をかぞへ且その家をこぼちて垣をかたくし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, '一つの水坑をかきとかきとの間につくりて古池の水をひけりされどこの事をなし給へるものを仰望まず この事をむかしより營みたまへる者をかへりみざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'その日主萬軍のヱホバ命じて哭かなしみ首をかぶろにし麁服をまとへと仰せたまひしかど');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'なんぢらは喜びたのしみ牛をほふり羊をころし肉をくらひ酒をのみていふ 我儕くらひ且のむべし明日はしぬべければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, '萬軍のヱホバ默示をわが耳にきかしめたまはく まことにこの邪曲はなんぢらが死にいたるまで除き清めらるるを得ずと これ主萬軍のヱホバのみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, '主ばんぐんのヱホバ如此のたまふ ゆけ宮ををさめ庫をつかさどるセブナにゆきていへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'なんぢここに何のかかはりありや また茲にいかなる人のありとして己がために墓をほりしや 彼はたかきところに墓をほり磐をうがちて己がために住所をつくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, '視よヱホバはつよき人のなげうつ如くに汝をなげうち給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'なんぢを包みかためふりまはして闊かなる地に球のごとくなげいだしたまはん 主人のいへの恥となるものよ汝そこにて死そのえいぐわの車もそこにあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, '我なんぢをその職よりおひその位よりひきおとさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'その日われわが僕ヒルキヤの子エリアキムを召て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'なんぢの衣をきせ汝の帶をもて固め なんぢの政權をその手にゆだぬべし 斯て彼ヱルサレムの民とユダの家とに父とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, '我またダビデのいへの鑰をその肩におかん 彼あくればとづるものなく彼とづればあくるものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, '我かれをたてて堅處にうちし釘のごとくすべし 而してかれはその父の家のさかえの位とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'その父の家のもろもろの榮は彼がうへに懸る その子その孫およびすべての器のちひさきもの皿より瓶子にいたるまでも然らざるなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, '萬軍のヱホバのたまはくその日かたき處にうちたる釘はぬけいで斫れておちん そのうへにかかれる負もまた絶るべし こはヱホバ語り給へるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'ツロに係るおもにの預言 いはく/タルシシのもろもろの舟よなきさけべ ツロは荒廢れて屋なく入べきところなければなり かれら此事をキツテムの地にて告しらせらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'うみべの民よもだせ 曩には海をゆきかふシドンの商賣くさぐさの物をかしこに充せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'ツロは大なる水をわたりくるシホルの種物とナイルがはの穀物とによりて収納をえたり ツロはもろもろの國のつどふ市なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'シドンよはづべし そは海すなはち海城かくいへり曰く われ苦しまずうまず壯男をやしなはず處女をそだてざりきと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'この音信のエジプトにいたるとき彼等ツロのおとづれによりて甚くうれふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'なんぢらタルシシにわたれ 海邊のたみよ汝等なきさけぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'これは上れる世いにしへよりありし邑おのが足にてうつり遠くたびずまひせる邑なんぢらの樂しみの邑なりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, '斯のごとくツロに對ひてはかりしは誰なるか ツロは冕をさづけし邑 その中のあきうどは君 その中の貿易するものは地のたふとき者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'これ萬軍のヱホバの定め給ふところにして すべて華美にかざれる驕奢をけがし地のもろもろの貴者をひくくしたまはんが爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'タルシシの女よナイルのごとく己が地にあふれよ なんぢを結びかたむる帶ふたたびなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'ヱホバその手を海の上にのべて國々をふるひうごかし給へり ヱホバ、カナンにつきて詔命をいだしその保砦をこぼたしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, '彼いひたまはく虐げられたる處女シドンのむすめよ 汝ふたたびよろこぶことなかるべし 起てキツテムにわたれ彼處にてなんぢまた安息をえじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'カルデヤ人のくにを視よ この民はふたたびあることなし アツスリヤ人この國を野のけものの居所にさだめたり かれら櫓をたてもろもろの殿をこぼちて荒墟となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'タルシシのもろもろの舟よなきさけべ なんぢの保砦はくだかれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'その日ツロは七十年のあひだ忘れらるべし ひとりの王のながらふる日のかずなり七十年終りてのちツロは妓女のうたの如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'さきに忘れられたるうかれめよ琴をとりて城市をへめぐり 巧に弾じておほくの歌をうたひ人にふたたび記念らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, '七十年をはりてヱホバまたツロを顧みたまはん ツロはふたたびその利潤をえて地のおもてにあるもろもろの國と淫をおこなふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'その貿易とその獲たる利潤とはきよめてヱホバに獻ぐべければ之をたくはへず積ことをせざるなり その貿易はヱホバの前にをるものの用となり飽くらふ料となり華美なるころもの料とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, '視よヱホバこの地をむなしからしめ荒廢れしめこれを覆へしてその民をちらしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'かくて民も祭司もひとしく 僕も主もひとしく 下婢も主婦もひとしく 買ものも賣ものもひとしく 貸ものも借ものもひとしく 利をはたるものも利をいだす者もひとしくこの事にあふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, '地はことごとく空しくことごとく掠められん こはヱホバの言たまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, '地はうれへおとろへ世は萎おとろへ地のたふときものも萎はてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, '民おきてにそむき法ををかし とこしへの契約をやぶりたるがゆゑに 地はその下にけがされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'このゆゑに呪詛は地をのみつくしそこに住るものは罪をうけまた地の民はやかれて僅かばかり遺れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'あたらしき酒はうれへ葡萄はなえ 心たのしめるものはみな歎息せざるはなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, '鼓のおとは寂まり歡ぶものの聲はやみ琴の音もまたしづまれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, '彼等はふたたび歌うたひ酒のまず濃酒はこれをのむものに苦くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, '騒ぎみだれたる邑はすでにやぶられ毎家はことごとく閉て人のいるなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, '街頭には酒の故によりて叫ぶこゑあり すべての歡喜はくらくなり地のたのしみは去ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, '邑はあれすたれたる所のみのこり その門もこぼたれて破れぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, '地のうちにてもろもろの民のなかにて遺るものは橄欖の樹のうたれしのちの果の如く葡萄の収穫はてしのちの實のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'これらのもの聲をあげてよばはん ヱホバの稜威のゆゑをもて海より歡びよばはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'この故になんぢら東にてヱホバをあがめ 海のしまじまにてイスラエルの神ヱホバの名をあがむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'われら地の極より歌をきけり いはく榮光はただしきものに歸すと/われ云らく我やせおとろへたり我やせおとろへたり 我はわざはひなるかな 欺騙者はあざむき欺騙者はいつはりをもて欺むけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, '地にすむものよ恐怖と陷阱と罟とはなんぢに臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'おそれの聲をのがるる者はおとしあなに陷り おとしあなの中よりいづるものは罟にかかるべし そは高處の窓ひらけ地の基ふるひうごけばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, '地は碎けにくだけ地はやぶれにやぶれ地は搖にゆれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, '地はゑへる者のごとく蹌きによろめき假廬のごとくふりうごく その罪はそのうへにおもく遂にたふれて再びおくることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'その日ヱホバはたかき處にて高きところの軍兵を征め 地にて地のもろもろの王を征めたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'かれらは囚人が阱にあつめらるるごとく集められて 獄中にとざされ多くの日をへてのち刑せらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'かくて萬軍のヱホバ、シオンの山およびヱルサレムにて統治め かつその長老たちのまへに榮光あるべければ 月は面あからみ日ははぢて色かはるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'ヱホバよ汝はわが神なり 我なんぢを崇めなんぢの名をほめたたへん 汝さきに妙なる事をおこなひ 古時より定めたることを眞實をもて成たまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'なんぢ邑をかへて石堆となし 堅固なる城を荒墟となし 外人の京都を邑とならしめず永遠にたつることを得ざらしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'この故につよき民はなんぢをあがめ 暴びたる國々の城はなんぢをおそるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'そはなんぢ弱きものの保砦となり 乏しきものの難のときの保砦となり 雨風のふききたりて垣をうつごとく暴ぶるものの荒きたるときの避所となり 熱をさくる蔭となりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'なんぢ外人の喧嘩をおさへて旱ける地より熱をとりのぞく如くならしめ 暴ぶるものの凱歌をとどめて雪の陰をもて熱をとどむる如くならしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, '萬軍のヱホバこの山にてもろもろの民のために肥たるものをもて宴をまうけ 久しくたくはへたる葡萄酒をもて宴をまうく 膸おほき肥たるもの久しくたくはへたる清るぶだう酒の宴なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, '又この山にてもろもろの民のかぶれる面帕と もろもろの國のおほへる外帔をとりのぞき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'とこしへまで死を呑たまはん 主ヱホバはすべての面より涙をぬぐひ 全地のうへよりその民の凌辱をのぞき給はん これはヱホバの語りたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'その日此如いはん これはわれらの神なり われら俟望めり 彼われらを救ひたまはん 是ヱホバなり われらまちのぞめり 我儕そのすくひを歡びたのしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'ヱホバの手はこの山にとどまり モアブはその處にてあくたの水のなかにふまるる藁のごとく蹂躙られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, '彼そのなかにて游者のおよがんとして手をのばすが如く己が手をのばさん 然どヱホバその手の脆計とともにその傲慢を伏たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'なんぢの垣たかき堅固なる城はヱホバかたぶけたふし 地におとして塵にまじへたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'その日ユダの國にてこの歌をうたはん われらに堅固なる邑あり 神すくひをもてその垣その藩となしたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'なんぢら門をひらきて忠信を守るただしき國民をいれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'なんぢは平康にやすきをもて心志かたき者をまもりたまふ 彼はなんぢに依賴めばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'なんぢら常盤にヱホバによりたのめ 主ヱホバはとこしへの巌なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'たかきに居るものを仆し そびえたる城をふせしめ 地にふせしめて塵にまじへ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'かくて足これをふまん 苦しむものは足にて之をふみ 貧しき者はその上をあゆまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, '義きものの道は直からざるなし なんぢ義きものの途を直く平らかにし給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'ヱホバよ審判をおこなひたまふ道にてわれら汝をまちのぞめり われらの心はなんぢの名となんぢの記念の名とをしたふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'わがこころ夜なんぢを慕ひたり わがうちなる靈あしたに汝をもとめん そは汝のさばき地におこなはるるとき世にすめるもの正義をまなぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, '惡者はめぐまるれども公義をまなばず 直き地にありてなほ不義をおこなひヱホバの稜威を見ることをこのまず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'ヱホバよなんぢの手たかく擧れどもかれら顧みず 然どなんぢが民をすくひたまふ熱心を見ばはぢをいだかん 火なんぢの敵をやきつくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'ヱホバよ汝はわれらのために平和をまうけたまはん 我儕のおこなひしことは皆なんぢの成たまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'ヱホバわれらの神よなんぢにあらぬ他の主ども曩にわれらを治めたり 然どわれらはただ汝によりて汝の名をかたりつげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'かれら死たればまたいきず 亡靈となりたればまた復らず なんぢかれらを糺してこれを滅ぼし その記念の名をさへ悉くうせしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'ヱホバよなんぢこの國民をましたまへり此くにびとを増たまへり なんぢは尊ばれたまふ なんぢ地の界をことごとく擴めたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'ヱホバよかれら苦難のときに汝をあふぎのぞめり 彼等なんぢの懲罰にあへるとき切になんぢに禱告せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'ヱホバよわれらは孕める婦のうむとき近づきてくるしみ その痛みによりて叫ぶがごとく汝のまへに然ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'われらは孕みまた苦しみたれどその產るところは風ににたり われら救を地にほどこさず世にすむ者うまれいでざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'なんぢの死者はいきわが民の屍はおきん 塵にふすものよ醒てうたうたふべし なんぢの露は草木をうるほす露のごとく地はなきたまをいださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'わが民よゆけ なんぢの室にいり汝のうしろの戸をとぢて忿恚のすぎゆくまで暫時かくるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, '視よヱホバはその處をいでて地にすむものの不義をただしたまはん 地はその上なる血をあらはにして殺されたるものをまた掩はざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'その日ヱホバは硬く大いなるつよき劍をもて 疾走るへびレビヤタン曲りうねる蛇レビヤタンを罰しまた海にある鱷をころし給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'その日如此うたはん うるはしき葡萄園あり之をうたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'われヱホバこれを護り をりをり水そそぎ 夜も晝もまもりて害ふものあらざらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, '我にいきどほりなし願はくは荊棘のわれと戰はんことを 然ばわれすすみ迎へて皆もろともに焚盡さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, '寧ろわが力にたよりて我とやはらぎを結べ われと平和をむすぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, '後にいたらばヤコブは根をはりイスラエルは芽をいだして花さきその實せかいの面にみちん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'ヤコブ主にうたるるといへども彼をうちしものの主にうたるるが如きことあらんや ヤコブの殺さるるは彼をころししものの殺さるるが如きことあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, '汝がヤコブを逐たまへる懲罰は度にかなひぬ 東風のふきし日なんぢあらき風をもてこれをうつし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, '斯るがゆゑにヤコブの不義はこれによりて潔められん これに因てむすぶ果は罪をのぞくことをせん 彼は祭壇のもろもろの石を碎けたる石灰のごとくになし アシラの像と日の像とをふたたび建ることなからしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, '堅固なる邑はあれてすさまじく棄去れたる家のごとく また荒野のごとし 犢このところにて草をはみ此所にてふし 且そこなる樹のえだをくらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'その枝かるるとき折とらる 婦人きたりてこれを燒ん これは無知の民なるが故に之をつくれる者あはれまず これを形づくれるもの惠まざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'その日なんぢらイスラエルの子輩よ ヱホバは打落したる果をあつむるごとく 大河の流よりエジプトの川にいたるまでなんぢらを一つ一つにあつめたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'その日大なるラッパ鳴ひびきアツスリヤの地にさすらひたる者 エジプトの地におひやられたる者 きたりてヱルサレムの聖山にてヱホバを拜むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, '酔るものなるエフライム人よなんぢらの誇の冠はわざはひなるかな 酒におぼるるものよ肥たる谷の首にある凋んとする花のうるはしき飾はわざはひなるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'みよ主はひとりの力ある强剛者をもち給へり それは雹をまじへたる暴風のごとく壞りそこなふ狂風のごとく大水のあぶれ漲るごとく烈しくかれを地になげうつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, '酔るものなるエフライム人のほこりの冠は足にて踐にじられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, '肥たる谷のかしらにある凋んとする花のうるはしきかざりは 夏こぬに熟したる初結の無花果のごとし 見るものこれをみて取る手おそしと呑いるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'その日萬軍のヱホバその民ののこれる者のために榮のかんむりとなり美しき冠となり給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'さばきの席にざするものには審判の靈をあたへ軍を門よりおひかへす者には力をあたへ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, '然どかれらも酒によりてよろめき濃酒によりてよろぼひたり 祭司と預言者とは濃酒によりてよろめき 酒にのまれ濃酒によりてよろぼひ 而して默示をみるときにもよろめき審判をおこなふときにも躓けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'すべて膳には吐たるものと穢とみちて潔きところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'かれは誰にをしへて知識をあたへんとするか 誰にしめして音信を暁らせんとするか 乳をたち懷をはなれたる者にするならんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'そは誡命にいましめをくはへ誡命にいましめをくはへ 度にのりをくはへ度にのりをくはへ 此にもすこしく彼にもすこしく敎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'このゆゑに神あだし唇と異なる舌とをもてこの民にかたりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, '曩にかれらに言たまひけるは此は安息なり疲困者にやすみをあたへよ 此は安慰なりと されど彼らは聞ことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, '斯るがゆゑにヱホバの言かれらにくだりて 誡命にいましめをくはへ誡命にいましめをくはへ 度にのりをくはへ度にのりをくはへ 此にもすこしく彼にも少しくをしへん 之によりて彼等すすみてうしろに仆れそこなはれ罟にかかりて捕へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'なんぢら此ヱルサレムにある民ををさむるところの輕慢者よヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'なんぢらは云り 我ら死と契約をたて陰府とちぎりをむすべり 漲りあふるる禍害のすぐるときわれらに來らじ そはわれら虛僞をもて避所となし欺詐をもて身をかくしたればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'このゆゑに神ヱホバかくいひ給ふ 視よわれシオンに一つの石をすゑてその基となせり これは試をへたる石たふとき隅石かたくすゑたる石なり これに依賴むものはあわつることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'われ公平を準繩とし正義を錘とす 斯て雹はいつはりにてつくれる避所をのぞきさり水はその匿れたるところに漲りあふれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, '汝らが死とたてし契約はきえうせ陰府とむすべるちぎりは成ことなし されば漲り溢るるわざはひのすぐるとき汝等はこれに踐たふさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'その過るごとになんぢらを捕へん 朝々にすぎ晝も夜もすぐ この音信をきき わきまふるのみにても慴きをるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'その狀は床みじかくして身をのぶることあたはず 衾せまくして身をおほふこと能はざるが如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'そはヱホバ往昔ペラヂムの山にて起たまひしがごとくにたち ギベオンの谷にて忿恚をはなちたまひしが如くにいきどほり 而してその所爲をおこなひ給はん 奇しき所爲なり その工を成たまはん 異なる工なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'この故になんぢら侮るなかれ 恐くはなんぢらの縲絏きびしくならん 我すでに全地のうへにさだまれる敗亡あるよしを主萬軍のヱホバより聞たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'なんぢら耳をかたぶけてわが聲をきけ懇ろにわが言をきくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, '農夫たねをまかんに何で日々たがへし日々その地をすき その土塊をくだくことのみを爲んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'もし地の面をたひらかにせばいかで罌粟をまき 馬芹の種をおろし 小麥をうねにうゑ 大麥をさだめたる處にうゑ 粗麥を畔にうゑざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, '斯のごときはかれの神これに智慧をあたへて敎へたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'けしは連耞にてうたず 馬芹はそのうへに車輪をきしらせず罌栗をうつには杖をもちひ 馬芹をうつには棒をもちふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, '麥をくだくか否くるまにきしらせ馬にふませて落すことはすれども斷ずしかするにあらず これを碎くことをせざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, '此もまた萬軍のヱホバよりいづ その謀略はくすしくその智慧はすぐれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'ああアリエルよアリエルよ ああダビデの營をかまへたる邑よ としに年をくはへ節會まはりきたらば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'われアリエルをなやまし之にかなしみと歎息とあらしめん 彼をアリエルのごとき者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'われ汝のまはりに營をかまへ保砦をきづきて汝をかこみ櫓をたててなんぢを攻べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'かくてなんぢは卑くせられ 地にふしてものいひ塵のなかより低聲をいだしてかたらん 汝のこゑは巫女のこゑのごとく地よりいで汝のことばは塵のなかより囀づるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, '然どなんぢのあだの群衆はこまやかなる塵の如く あらぶるものの群衆はふきさらるる粃糠の如くならん 俄にまたたく間にこの事あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, '萬軍のヱホバはいかづち 地震 おほごゑ 暴風 つむじかぜ及びやきつくす火の燄をもて臨みたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, '斯てアリエルを攻てたたかふ國々のもろもろ アリエルとその城とをせめたたかひて難ますものは みな夢のごとく夜のまぼろしの如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, '饑たるものの食ふことを夢みて醒きたればその心なほ空しきがごとく 渇けるものの飮ことを夢みて醒きたれば疲れかつ頻にのまんことを欲するがごとく シオンの山をせめて戰ふくにぐにの群衆もまた然あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'なんぢらためらへ而しておどろかん なんぢら放肆にせよ而して目くらまん かれらは酔りされど酒のゆゑにあらず かれらはよろめけりされど濃酒のゆゑにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'そはヱホバ酣睡の靈をなんぢらの上にそそぎ 而してなんぢらの目をとぢ なんぢらの面をおほひたまへり その目は預言者そのかほは先知者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'かかるが故にすべての默示はなんぢらには封じたる書のことばのごとくなり 文字しれる人にわたして請これを讀といはんに答へて封じたるがゆゑによむこと能はずといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'また文字しらぬ人にわたして請これをよめといはんにこたへて文字しらざるなりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, '主いひ給はく この民は口をもて我にちかづき口唇をもてわれを敬へども その心はわれに遠かれり そのわれを畏みおそるるは人の誡命によりてをしへられしのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'この故にわれこの民のなかにて再びくすしき事をおこなはん そのわざは奇しくしていとあやし かれらの中なる智者のちゑはうせ聰明者のさときはかくれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, '己がはかりごとをヱホバに深くかくさんとする者はわざはひなるかな 暗中にありて事をおこなひていふ 誰かわれを見んや たれか我をしらんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'なんぢらは曲れり いかで陶工をみて土塊のごとくおもふ可んや 造られし者おのれを作れるものをさして我をつくれるにあらずといふをえんや 形づくられたる器はかたちづくりし者をさして智慧なしといふを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, '暫くしてレバノンはかはりて良田となり 良田は林のごとく見ゆるとききたるならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'その日聾者はこの書のことばをきき盲者の目はくらきより闇よりみることを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, '謙だるものはヱホバによりてその歡喜をまし 人のなかの貧きものはイスラエルの聖者によりて快樂をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, '暴るものはたえ 侮慢者はうせ 邪曲の機をうかがふ者はことごとく斷滅さるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'かれらは訟をきく時まげて人をつみし 邑門にていさむるものを謀略におとしいれ 虛しき語をかまへて義人をしりぞく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'この故にむかしアブラハムを贖ひたまひしヱホバはヤコブの家につきて如此いひたまふ ヤコブは今より恥をかうむらず その面はいまより色をうしなはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'かれの子孫はその中にわがおこなふ手のわざをみん その時わが名を聖としヤコブの聖者を聖としてイスラエルの神をおそるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, '心あやまれるものも知識をえ つぶやけるものも敎誨をまなばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'ヱホバのたまはく 悖るる子輩はわざはひなるかな かれら謀略をすれども我によりてせず 盟をむすべどもわが靈にしたがはず ますます罪につみをくはへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'かれらわが口にとはずしてエジプトに下りゆきパロの力をかりておのれを强くしエジプトの蔭によらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'パロのちからは反てなんぢらの恥となり エジプトの蔭によるは反てなんぢらの辱かしめとなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'かれの君たちはゾアンにあり かれの使者たちはハネスにきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'かれらは皆おのれを益することあたはざる民によりて恥をいだく かの民はたすけとならず益とならず かへりて恥となり謗となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, '南のかたの牲畜にかかる重負のよげん 曰く/かれらその財貨を若き驢馬のかたにおはせ その寳物を駱駝の背におはせて 牝獅 牡獅 まむし及びとびかける蛇のいづる苦しみと艱難との國をすぎて 己をえきすること能はざる民にゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'そのエジプトの助はいたづらにして虛し このゆゑに我はこれを休みをるラハブとよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'いま往てこれをその前にて牌にしるし書にのせ 後の世に傳へてとこしへに證とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'これは悖れる民いつはりをいふ子輩ヱホバの律法をきくことをせざる子輩なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'かれら見るものに對ひていふ見るなかれと 默示をうる者にむかひていふ直きことを示すなかれ 滑かなることをかたれ虛僞をしめせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'なんぢら大道をさり逕をはなれ われらが前にイスラエルの聖者をあらしむるなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, '此によりてイスラエルの聖者かくいひ給ふ なんぢらこの言をあなどり暴虐と邪曲とをたのみて之にたよれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, '斯るがゆゑにこの不義なんぢらには凸出ておちんとするたかき垣のさけたるところのごとく その破壞にはかに暫しが間にきたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, '主これを破りあだかも陶工の瓶をくだきやぶるがごとくして惜みたまはず その碎のなかに爐より火をとり池より水をくむほどの一片だに見出すことなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, '主ヱホバ、イスラエルの聖者かくいひたまへり なんぢら立かへりて靜かにせば救をえ 平穩にして依賴まば力をうべしと 然どなんぢらこの事をこのまざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'なんぢら反ていへり 否われら馬にのりて逃走らんと この故になんぢら逃走らん 又いへりわれら疾きものに乗んと この故になんぢらを追もの疾かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'ひとり叱咤すれば千人にげはしり 五人しつたすればなんぢら逃走りて その遺るものは僅かに山嶺にある杆のごとく 岡のうへにある旗のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'ヱホバこれにより俟てのち恩惠を汝等にほどこし これにより上りてのちなんぢらを憐れみたまはん ヱホバは公平の神にましませり 凡てこれを俟望むものは福ひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'シオンにをりヱルサレムにをる民よ なんぢは再びなくことあらじ そのよばはる聲に應じて必ずなんぢに惠をほどこしたまはん 主ききたまふとき直にこたへたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, '主はなんぢらになやみの糧とくるしみの水とをあたへ給はん なんぢを敎るもの再びかくれじ 汝の目はその敎るものを恒にみるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'なんぢ右にゆくも左にゆくもその耳に これは道なりこれを歩むべしと後邊にてかたるをきかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, '又なんぢら白銀をおほひし刻める像 こがねをはりし鑄たる像をけがれとし 穢物のごとく打棄ていはん 去れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'なんぢが地にまく種に主は雨をあたへ また地になりいづる糧をたまふ その土產こえて豐かならん その日なんぢの家畜はひろき牧場に草をはむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, '地をたがへす牛と驢馬とは團扇にてあふぎ箕にてとほし鹽をくはへたる飼料をくらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, '大なる殺戮の日やぐらのたふるる時もろもろのたかき山もろもろのそびえたる嶺に河とみづの流とあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'かくてヱホバその民のきずをつつみ そのうたれたる創痍をいやしたまふ日には月のひかりは日の光のごとく日のひかりは七倍をくはへて七の日のひかりの如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, '視よヱホバの名はとほき所よりきたり そのはげしき怒はもえあがる焰のごとく その唇はいきどほりにてみち その舌はやきつくす火のごとく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'その氣息はみなぎりて項にまでいたる流のごとし 且ほろびの篩にてもろもろの國をふるひ又まどはす韁をもろもろの民の口におきたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'なんぢらは歌うたはん節會をまもる夜のごとし なんぢらは心によろこばん笛をならしヱホバの山にきたりイスラエルの磐につくときの如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'ヱホバはその稜威のこゑをきかしめ 烈しき怒をはなちて燒つくす火のほのほと暴風と大雨と雹とをもて その臂のくだることを示したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'ヱホバのこゑによりてアツスリヤ人はくじけん 主はこれを笞にてうち給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'ヱホバの豫じめさだめたまへる杖をアツスリヤのうへにくはへたまふごとに 鼓をならし琴をひかん 主はうごきふるふ戰闘をもてかれらとたたかひ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'トペテは往古よりまうけられ また王のために備へられたり これを深くしこれを廣くしここに火とおほくの薪とをつみおきたり ヱホバの氣息これを硫黄のながれのごとくに燃さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, '助をえんとてエジプトにくだり馬によりたのむものは禍ひなるかな 戰車おほきが故にこれにたのみ騎兵はなはだ强きがゆゑに之にたのむ されどイスラエルの聖者をあふがずヱホバを求ることをせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, '然はあれどもヱホバもまた智慧あるべし かならず禍害をくだしてその言をひるがへしたまはず 起てあしきものの家をせめ また不義を行ふ者の助をせめ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'かのエジプト人は人にして神にあらずその馬は肉にして靈にあらず ヱホバその手をのばしたまはば助くるものも蹟き たすけらるる者もたふれてみなひとしく亡びん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'ヱホバ如此われにいひたまふ 獅のほえ壯獅の獲物をつかみてほえたけれるとき 許多のひつじかひ相呼つどひてむかひゆくとも その聲によりて挫けずその喧譁しきによりて臆せざるごとく 萬軍のヱホバくだりてシオンの山およびその岡にて戰ひ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, '鳥の雛をまもるがごとく萬軍のヱホバはヱルサレムをまもりたまはん これを護りてこれをすくひ踰越てこれを援けたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'イスラエルの子輩よなんぢらさきには甚だしく主にそむけり 今たちかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'なんぢらおのが手につくりて罪ををかしし白銀のぐうざう黄金の偶像をその日おのおのなげすてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, '爰にアツスリヤびとは劍にてたふれん されど人のつるぎにあらず 劍かれらをほろぼさん されど世の人のつるぎにあらず かれら劍のまへより逃はしりその壯きものは役丁とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'かれらの磐はおそれによりて逝去り その君たちは旗をみてくじけん こはヱホバの御言なり ヱホバの火はシオンにありヱホバの爐はヱルサレムにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, '茲にひとりの王あり 正義をもて統治め その君たちは公平をもて宰さどらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'また人ありて風のさけどころ暴雨ののがれどころとなり 旱ける地にある水のながれのごとく 倦つかれたる地にある大なる岩陰の如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, '見るものの目はくらまず 聞ものの耳はかたぶけきくをうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, '躁がしきものの心はさとりて知識をえ 吃者の舌はすみやけくあざやかに語るをうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, '愚かなる者はふたたび尊貴とよばるることなく 狡猾なる者はふたたび大人とよばるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'そは愚なるものは愚なることをかたり その心に不義をかもし邪曲をおこなひ ヱホバにむかひて妄なることをかたり 饑たる者のこころを空しくし渇けるものの飮料をつきはてしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, '狡猾なるものの用ゐる器はあしし 彼あしき企圖をまうけ虛僞のことばをもて苦しむ者をそこなひ 乏しき者のかたること正理なるも尚これを害へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'たふとき人はたふとき謀略をまうけ恒にたふとき事をおこなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, '安逸にをる婦等よおきてわが聲をきけ 思煩ひなき女等よわが言に耳を傾けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, '思煩ひなきをんなたちよ一年あまりの日をすぎて摺きあわてん そは葡萄の収穫むなしく果ををさむる期きたるまじければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'やすらかにをる婦等よふるひおそれよ おもひわづらひなき者よをののきあわてよ 衣をぬぎ裸體になりて腰に麁服をまとへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'かれら良田のため實りゆたかなる葡萄の樹のために胸をうたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, '棘と荊わが民の地にはえ 樂みの邑なるよろこびの家々にもはえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'そは殿はすてられ にぎはひたる邑はあれすたれ オペルと櫓とはとこしへに洞穴となり 野の驢馬のたのしむところ羊のむれの草はむところとなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'されど遂には靈うへより我儕にそそぎて 荒野はよき田となり 良田は林のごとく見ゆるとききたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'そのとき公平はあれのにすみ 正義はよき田にをらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'かくて正義のいさをは平和 せいぎのむすぶ果はとこしへの平隱とやすきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'わが民はへいわの家にをり 思ひわづらひなき住所にをり 安らかなる休息所にをらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'されどまづ雹ふりて林くだけ邑もことごとくたふるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'なんぢらもろもろの水のほとりに種をおろし 牛および驢馬の足をはなちおく者はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, '禍ひなるかななんぢ害はれざるに人をそこなひ 欺かれざるに人をあざむけり なんぢが害ふこと終らば汝そこなはれ なんぢが欺くことはてなば汝あざむかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'ヱホバよわれらを惠み給へわれらなんぢを俟望めり なんぢ朝ごとにわれらの臂となり また患難のときにわれらの救となりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'なりとどろく聲によりてもろもろの民にげはしり なんぢの起たまふによりてもろもろの國はちりうせぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, '蟊賊のものをはみつくすがごとく人なんぢらの財をとり盡さん また蝗のとびつどふがごとく人なんぢらの財にとびつどふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'ヱホバは最たかし高處にすみたまふなり ヱホバはシオンに公正と正義とを充せたまひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'なんぢの代はかたくたち 救と智惠と知識とはゆたかにあらん ヱホバをおそるるは國の寳なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, '視よかれらの勇士は外にありてさけび 和をもとむる使者はいたく哭く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, '大路あれすたれて旅客たえ 敵は契約をやぶり諸邑をなみし人をもののかずとせず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, '地はうれへおとろへ レバノンは恥らひて枯れ シヤロンはアラバの如くなり バシヤンとカルメルとはその葉をおとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'ヱホバ言給はく われ今おきん今たたん 今みづからを高くせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'なんぢらの孕むところは枇糠のごとく なんぢらの生ところは藁のごとし なんぢらの氣息は火となりてなんぢらを食ひつくさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'もろもろの民はやかれて灰のごとくなり 荊のきられて火にもやされたるが如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'なんぢら遠にあるものよ わが行ひしことをきけ なんぢら近にあるものよ わが能力をしれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'シオンの罪人はおそる 戰慄はよこしまなる者にのぞめり われらの中たれか燒つくす火に止ることを得んや 我儕のうち誰かとこしへに燒るなかに止るをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, '義をおこなふもの直をかたるもの虐げてえたる利をいとひすつるもの手をふりて賄賂をとらざるもの 耳をふさぎて血をながす謀略をきかざるもの 目をとぢて惡をみざる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'かかる人はたかき處にすみ かたき磐はその櫓となり その糧はあたへられその水はともしきことなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'なんぢの目はうるはしき狀なる王を見 とほくひろき國をみるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, '汝の心はかの懼しかりしことどもを思ひいでん 會計せし者はいづくにありや 貢をはかりし者はいづくにありや 櫓をかぞへし者はいづくにありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, '汝ふたたび暴民をみざるべし かの民の言語はふかくして悟りがたくその舌は異にして解がたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'われらの節會の邑シオンを見よ なんぢの目はやすらかなる居所となれるヱルサレムを見ん ヱルサレムはうつさるることなき幕屋にして その杙はとこしへにぬかれず その繩は一すぢだに斷れざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'ヱホバ我らとともに彼處にいまして稜威をあらはし給はん 斯てそのところはひろき川ひろき流あるところとなりて その中には漕舟もいらず巨艦もすぐることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'ヱホバはわれらを鞫きたまふもの ヱホバはわれらに律法をたてたまひし者 ヱホバはわれらの王にましまして我儕をすくひ給ふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'なんぢの船纜はとけたり その桅杆のもとを結びかたむることあたはず 帆をあぐることあたはず その時おほくの財をわかち跛者までも掠物あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'かしこに住るものの中われ病りといふ者なし彼處にをる民の咎はゆるされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'もろもろの國よちかづきてきけ もろもろの民よ耳をかたぶけよ 地と地にみつるもの世界とせかいより出るすべての者きけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'ヱホバはよろづの國にむかひて怒り そのよろづの軍にむかひて忿恚り かれらをことごとく滅し かれらを屠らしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'かれらは殺されて抛棄られ その屍の臭氣たちのぼり山はその血にて融されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, '天の萬象はきえうせ もろもろの天は書巻のごとくにまかれん その萬象のおつるは葡萄の葉のおつるがごとく無花果のかれたる葉のおつるが如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'わが劍は天にてうるほひたり 視よエドムの上にくだり滅亡に定めたる民のうへにくだりて之をさばかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'ヱホバの劍は血にてみち脂にてこえ小羊と山羊との血 牡羊の腎のあぶらにて肥ゆ ヱホバはボズラにて牲のけものをころしエドムの地にて大にほふることをなし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'その屠場には野牛 こうし 牡牛もともに下る そのくには血にてうるほされ その塵はあぶらにて肥さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'こはヱホバの仇をかへしたまふ日にしてシオンの訟のために報をなしたまふ年なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'エドムのもろもろの河はかはりて樹脂となり その塵はかはりて硫磺となり その土はかはりてもゆる樹脂となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, '晝も夜もきえずその烟つくる期なく上騰らん かくて世々あれすたれ永遠までもその所をすぐる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, '鵜と刺猬とそこを己がものとなし鷺と鴉とそこにすまん ヱホバそのうへに亂をおこす繩をはり空虛をきたらする錘をさげ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, '國をつぐべき者をたてんとて貴者ふたたび呼集ることをせじ もろもろの諸侯はみな失てなくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'その殿にはことごとく荊はえ 城にはことごとく刺草と薊とはえ 野犬のすみか駝鳥の場とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, '野のけものと豺狼とここにあひ 牡山羊その友をよび 鴟鴞もまた宿りてここを安所とせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, '蛇ここに穴をつくり卵をうみてこれを孚しおのれの影の下に子をあつむ 鳶もまたその偶とともに此處にあつまらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'なんぢらヱホバの書をつまびらかにたづねて讀べし これらのもの一つも缺ることなく又ひとつもその偶をかくものあらじ そはヱホバの口このことを命じ その靈これらを集めたまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'ヱホバこれらのものに鬮をひかせ手づから繩をもて量り この地をわけあたへて永くかれらに保たしめ 世々にいたるまでここに住しめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, '荒野とうるほひなき地とはたのしみ 沙漠はよろこびて番紅の花のごとくに咲かがやかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, '盛に咲かがやきてよろこび且よろこび且うたひ レバノンの榮をえカルメルおよびシヤロンの美しきを得ん かれらはヱホバのさかえを見われらの神のうるはしきを見るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'なんぢら萎たる手をつよくし弱りたる膝をすこやかにせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, '心さわがしきものに對ていへ なんぢら雄々しかれ懼るるなかれ なんぢらの神をみよ 刑罰きたり神の報きたらん 神きたりてなんぢらを救ひたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'そのとき瞽者の目はひらけ聾者の耳はあくことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'そのとき跛者は鹿の如くにとびはしり唖者の舌はうたうたはん そは荒野に水わきいで沙漠に川ながるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'やけたる沙は池となり うるほひなき地はみづの源となり 野犬のふしたるすみかは蘆葦のしげりあふ所となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'かしこに大路あり そのみちは聖道ととなへられん 穢れたるものはこれを過ることあたはず ただ主の民のために備へらる これを歩むものはおろかなりとも迷ふことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'かしこに獅をらず あらき獸もその路にのぼることなし 然ばそこにて之にあふ事なかるべし ただ贖はれたる者のみそこを歩まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'ヱホバに贖ひすくはれし者うたうたひつつ歸てシオンにきたり その首にとこしへの歡喜をいただき樂とよろこびとをえん 而して悲哀となげきとは逃さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'ヒゼキヤ王の十四年にアツスリヤの王セナケリブ上りきたりてユダのもろもろの堅固なる邑をせめとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'アツスリヤ王ラキシよりラブシヤケをヱルサレムに遣はし大軍をひきゐてヒゼキヤ王のもとに往しむ ラブシヤケ漂工の野のおほぢの傍なる上の池の樋にそひてたてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'この時ヒゼキヤの子なる家司エリアキム 書記セブナ、アサフの子なる史官ヨア出てこれを迎ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'ラブシヤケかれらにいひけるは なんぢら今ヒゼキヤにいへ大王アツスリヤの王かくいへり なんぢの恃とするその恃むところは何なるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, '我いふ なんぢが説ところの軍のはかりごととその能力とはただ口唇のことばのみ 今なんぢ誰によりたのみて我にさかふことをなすや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, '視よなんぢエジプトに依賴めり これ傷める葦の杖によりたのめるがごとし もし人これに倚もたれなばその手をつきさされん エジプト王パロがすべて己によりたのむものに對するは斯のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, '汝われらはわれらの神ヱホバに依賴めりと我にいはんかそは曩にヒゼキヤが高きところと祭壇とをみな取去てユダとヱルサレムとにむかひ汝等ここなる一つの祭壇のまへにて拜すべしといへる夫ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'いま請わが君アツスリヤ王に賭をせよ われ汝に二千の馬を與ふべければ汝よりこれに乗ものをいだせ 果して出しうべしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, '然ばいかで我君のいとちひさき僕の長一人をだに退くることを得んや なんぞエジプトによりたのみて戰車と騎兵とをえんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'いま我のぼりきたりてこの國をせめほろぼすはヱホバの旨にあらざるべけんや ヱホバわれにいひたまはく のぼりゆきてこの國をせめぼろぼせと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, '爰にエリアキムとセブナとヨアと共にラブシヤケにいひけるは請スリアの方言にて僕輩にかたれ我儕これをさとりうるなり石垣のうへなる民のきくところにてはユダヤの方言をもてわれらに語るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'ラブシヤケいひけるは わが君はこれらのことをなんぢの君となんぢとにのみ語らんために我をつかはししならんや なんぢらと共におのが糞をくらひおのが溺をのまんとする石垣のうへに坐する人々にも我をつかはししならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, '斯てラブシヤケたちてユダヤの方言もて大聲によばはりいひけるは なんぢら大王アツスリヤ王のことばをきくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, '王かくのたまへり なんぢらヒゼキヤに惑はさるるなかれ 彼なんぢらを救ふことあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'ヒゼキヤがなんぢらをヱホバに賴しめんとする言にしたがふなかれ 彼いへらく ヱホバかならず我儕をすくひこの邑はアツスリヤ王の手にわたさるることなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'ヒゼキヤに聽從ふなかれ アツスリヤ王かくのたまへり なんぢらわれと親和をなし出できたりて我にくだれ おのおのその葡萄とその無花果とをくらひ かのおのその井の水をのむことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, '遂には我きたりて汝等をほかの國にたづさへゆかん その國はなんぢの國のごとき國にして 穀物 ぶだう酒 パンおよび葡萄園あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'おそらくはをヒゼキヤなんぢらに説てヱホバわれらを救ふべしといはん 然どももろもろの國の神等のなかにその國をアツスリヤ王の手より救へる者ありしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'ハマテ、アルバデの神等いづこにありや セバルワイムの神等いづこにありや 又わが手よりサマリヤを救出しし神ありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'これらの國のもろもろの神のなかに誰かその國をわが手よりすくひいだしし者ありや さればヱホバも何でわが手よりヱルサレムを救ひいだし得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, '如此ありければ民は默して一言をもこたへざりき そは之にこたふるなかれとの王のおほせありつればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'そのときヒルキヤの子なる家司エリアキム書記セブナおよびアサフの子なる史官ヨアころもを裂てヒゼキヤにゆき之にラブシヤケの言をつげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'ヒゼキヤ王これをききてその衣をさき麁衣をまとひてヱホバの家にゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, '家司エリアキム書記セブナおよび祭司のなかの長老等をして皆あらたへをまとはせてアモツの子預言者イザヤのもとにゆかしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'かれらイザヤにいひけるは ヒゼキヤ如此いへり けふは患難と責と辱かしめの日なり そは子うまれんとして之をうみいだすの力なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'なんぢの神ヱホバあるひはラブシヤケがもろもろの言をききたまはん 彼はその君アツスリヤ王につかはされて活る神をそしれり なんぢの神ヱホバその言をききて或はせめたまふならん されば請なんぢこの遺れるもののために祈禱をささげよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'かくてヒゼキヤ王の諸僕イザヤにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'イザヤかれらに言けるは なんぢらの君につげよ ヱホバ斯いひたまへり曰く アツスリヤ王のしもべら我をののしりけがせり なんぢらその聞しことばによりて懼るるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, '視よわれかれが意をうごかすべければ 一つの風聲をききておのが國にかへらん かれをその國にて劍にたふれしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, '爰にラブシヤケはアツスリヤ王がラキシを離れさりしとききて歸りけるとき際しも王はリブナを攻をれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'このときエテオピアの王テルハカの事についてきけり云く かれいでて汝とたたかふべしと このことをききて使者をヒゼキヤに遣していふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'なんぢらユダの王ヒゼキヤにつげて如此いへ なんぢが賴める神なんぢを欺きてヱルサレムはアツスリヤ王の手にわたされじといふを聽ことなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, '視よアツスリヤの王等もろもろの國にいかなることをおこなひ如何してこれを悉くほろぼししかを汝ききしならん されば汝すくはるることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'わが先祖たちの滅ぼししゴザン、ハラン、レゼフおよびテラサルなるエデンの族など此等のくにぐにの神はその國をすくひたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'ハマテの王アルバデの王セバルワイムの都の王ヘナの王およびイワの王はいづこにありやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'ヒゼキヤつかひの手より書をうけて之を讀り しかしてヒゼキヤ、ヱホバの宮にのぼりゆきヱホバの前にこのふみを展ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'ヒゼキヤ、ヱホバに祈ていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'ケルビムの上に坐したまふ萬軍のヱホバ、イスラエルの神よ ただ汝のみ地のうへなるよろづの國の神なり なんぢは天地をつくりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'ヱホバよ耳をかたむけて聽たまへ ヱホバよ目をひらきて視たまへ セナケリブ使者して活る神をそしらしめし言をことごとくききたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'ヱホバよ實にアツスリヤの王等はもろもろの國民とその地とをあらし毀ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'かれらの神たちを火になげいれたり これらのものは神にあらず 人の手の工にして あるひは木あるひは石なり 斯るがゆゑに滅ぼされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'さればわれらの神ヱホバよ 今われらをアツスリヤ王の手より救ひいだして 地のもろもろの國にただ汝のみヱホバなることを知しめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'ここにアモツの子イザヤ人をつかはしてヒゼキヤにいはせけるは イスラエルの神ヱホバかくいひたまふ 汝はアツスリヤ王セナケリブのことにつきて我にいのれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'ヱホバが彼のことにつきて語り給へるみことばは是なり いはくシオンの處女はなんぢを侮りなんぢをあざけり ヱルサレムの女子はなんぢの背後より頭をふれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, '汝がそしりかつ罵れるものは誰ぞ なんぢが聲をあげ目をたかく向てさからひたるものはたれぞ イスラエルの聖者ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'なんぢその使者によりて主をそしりていふ 我はおほくの戰車をひきゐて山々のいただきに登りレバノンの奧にまでいりぬ 我はたけたかき香柏とうるはしき松樹とをきり またその境なるたかき處にゆき腴たる地の林にゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, '我は井をほりて水をのみたり われは足跖をもてエジプトの河々をからさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'なんぢ聞ずや これらのことはわが昔よりなす所 いにしへの日よりさだめし所なり 今なんぢがこの堅城をこぼちあらして石堆となすも亦わがきたらしし所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'そのなかの民はちから弱くをののきて恥をいだき 野草のごとく靑き菜のごとく屋蓋の草のごとく未だそだたざる苗のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, '我なんぢが居ること出入すること又われにむかひて怒りさけべることをしる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'なんぢが我にむかひて怒りさけべると汝がほこれる言とわが耳にいりたれば我なんぢの鼻に環をはめ汝のくちびるに鑣をつけて汝がきたれる路よりかへらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'ヒゼキヤよ我がなんぢにたまふ徴はこれなり なんぢら今年は落穂より生たるものを食ひ 明年は糵生より出たるものを食はん 三年にあたりては種ことをなし收ことをなし 葡萄ぞのを作りてその果を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'ユダの家ののがれて遺れる者はふたたび下は根をはり上は果を結ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'そは遺るものはヱルサレムよりいで脱るるものはシオンの山よりいづるなり 萬軍のヱホバの熱心これを成たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'この故にヱホバ、アツスリヤの王については如此いひたまふ 彼はこの城にいらず ここに箭をはなたず盾を城のまへにならべず 壘をきづきて攻ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'かれはそのきたりし道よりかへりてこの城にいらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, '我おのれの故によりて僕ダビデの故によりて この城をまもり この城をすくはん これヱホバ宣給るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'ヱホバの使者いできたりアツスリヤの陣營のなかにて十八萬五千人をうちころせり早晨におきいでて見ればみな死てかばねとなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'アツスリヤ王セナケリブ起てかへりゆきニネベにとどまる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, '一日おのが神ニスロクのみやにて禮拜をなし居しにその子アデランメレクとシヤレゼルと劍をもて彼をころし而してアララテの地ににげゆけり かれが子エサルハドンつぎて王となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'そのころヒゼキヤやみて死んとせしにアモツの子預言者イザヤきたりて彼にいふ ヱホバ如此いひたまはく なんぢ家に遺言をとどめよ 汝しにて活ることあたはざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, '爰にヒゼキヤ面を壁にむけてヱホバに祈りいひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'ああヱホバよ 願くはわがなんぢの前に眞實をもて一心をもてあゆみ なんぢの目によきことを行ひたるをおもひいでたまへ 斯てヒゼキヤ甚くなきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'ヱホバの言イザヤにのぞみて曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'なんぢ往てヒゼキヤにいへ なんぢの祖ダビデの神ヱホバかくいひ給はく 我なんぢの禱告をききなんぢの涙をみたり 我なんぢの齢を十五年ましくはへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, '且なんぢとこの城とを救ひてアツスリヤわうの手をのがれしめん又われこの城をまもるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'ヱホバ語りたまひたる此事を成たまふ證にこの徴をなんぢに賜ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, '視よわれアハズの日晷にすすみたる日影を十度しりぞかしめんといひければ乃ちひばかりにすすみたる日影十度しりぞきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'ユダの王ヒゼキヤ病にかかりてその病のいえしのち記しし書は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '我いへり わが齢ひの全盛のとき陰府の門にいりわが餘年をうしなはんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, '我いへり われ再びヱホバを見奉ることあらじ再びいけるものの地にてヱホバを見奉ることあらじ われは無ものの中にいりてふたたび人を見ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'わが住所はうつされて牧人の幕屋をとりさるごとくに我をはなる わがいのちは織工の布をまきをはりて機より翦はなすごとくならん なんぢ朝夕のあひだに我をたえしめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'われは天明におよぶまで己をおさへてしづめたり 主は獅のごとくに我もろもろの骨を碎きたまふ なんぢ朝夕の間にわれを絶しめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'われは燕のごとく鶴のごとくに哀みなき鳩のごとくにうめき わが眼はうへを視ておとろふ ヱホバよわれは迫りくるしめらる 願くはわが中保となりたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, '主はわれとものいひ且そのごとくみづから成たまへり われ何をいふべきか わが世にある間わが靈魂の苦しめる故によりて愼みてゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, '主よこれらの事によりて人は活るなり わが靈魂のいのちも全くこれらの事によるなり 願くはわれを醫しわれを活したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, '視よわれに甚しき艱苦をあたへたまへるは我に平安をえしめんがためなり 汝わがたましひを愛して滅亡の穴をまぬかれしめ給へり そはわが罪をことごとく背後にすてたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, '陰府はなんぢに感謝せず 死はなんぢを讃美せず 墓にくだる者はなんぢの誠實をのぞまず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, '唯いけるもののみ活るものこそ汝にかんしやするなれ わが今日かんしやするが如し 父はなんぢの誠實をその子にしらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'ヱホバ我を救ひたまはん われら世にあらんかぎりヱホバのいへにて琴をひきわが歌をうたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'イザヤいへらく無花果の一團をとりきたりて腫物のうへにつけよ 王かならずいえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'ヒゼキヤも亦いへらく わがヱホバの家にのぼることにつきては何の兆あらんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'そのころバラダンの子バビロン王メロダクバラダン、ヒゼキヤが病をうれへて愈しことをききければ書と禮物とをおくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'ヒゼキヤその使者のきたるによりて喜びこれに財物 金銀 香料 たふとき油ををさめたる家およびすべての軍器ををさめたる家また庫のなかなる物をことごとく見す おほよそヒゼキヤのいへの裏にあるものと全國のうちにあるものと 見せざるものは一もあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'ここに預言者イザヤ、ヒゼキヤ王のもとに來りていひけるは この人々はなにをいひしや何處よりなんぢのもとに來りしや ヒゼキヤ曰けるは かれらはとほき國よりバビロンより我にきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'イザヤいふ 彼等はなんぢの家にてなにを見たりしや ヒゼキヤ答ふ かれらはわが家にあるものを皆みたり又わが庫のなかにあるものは一つをもかれらに見せざるものなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'イザヤ、ヒゼキヤにいふ なんぢ萬軍のヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'みよ日きたらん なんぢの家のものなんぢの列祖がけふまで蓄へたるものは皆バビロンにたづさへゆかれて遺るもの一もなかるべし 是はヱホバのみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'なんぢの身より生れいでん者もとらはれ寺人とせられてバビロン王の宮のうちにあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'ヒゼキヤ、イザヤにいひけるは 汝がかたるヱホバのみことばは善し また云 わが世にあるほどは太平と眞理とあるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'なんぢらの神いひたまはく なぐさめよ汝等わが民をなぐさめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, '懇ろにヱルサレムに語り之によばはり告よ その服役の期すでに終り その咎すでに赦されたり そのもろもろの罪によりてヱホバの手よりうけしところは倍したりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'よばはるものの聲きこゆ云く なんぢら野にてヱホバの途をそなへ沙漠にわれらの神の大路をなほくせよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'もろもろの谷はたかくもろもろの山と岡とはひくくせられ 曲りたるはなほく崎嶇はたひらかにせらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, '斯てヱホバの榮光あらはれ人みな共にこれを見ん こはヱホバの口より語りたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, '聲きこゆ云く よばはれ答へていふ何とよばはるべきか いはく人はみな草なり その榮華はすべて野の花のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, '草はかれ花はしぼむ ヱホバの息そのうへに吹ければなり 實に民はくさなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, '草はかれ花はしぼむ 然どわれらの神のことばは永遠にたたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'よき音信をシオンにつたふる者よ なんぢ高山にのぼれ 嘉おとづれをヱルサレムにつたふる者よ なんぢ強く聲をあげよ こゑを揚ておそるるなかれ ユダのもろもろの邑につけよ なんぢらの神きたり給へりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'みよ主ヱホバ能力をもちて來りたまはん その臂は統治めたまはん 賞賜はその手にあり はたらきの値はその前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, '主は牧者のごとくその群をやしなひ その臂にて小羊をいだき之をその懷中にいれてたづさへ乳をふくまする者をやはらかに導きたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'たれか掌心をもてもろもろの水をはかり指をのばして天をはかり また地の塵を量器にもり天秤をもてもろもろの山をはかり權衡をもてもろもろの岡をはかりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, '誰かヱホバの靈をみちびきその議士となりて敎しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'ヱホバは誰とともに議りたまひしや たれかヱホバを聰くしこれに公平の道をまなばせ知識をあたへ明通のみちを示したりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, '視よもろもろの國民は桶のひとしづくのごとく 權衡のちりのごとくに思ひたまふ島々はたちのぼる塵埃のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'レバノンは柴にたらずそのなかの獸は燔祭にたらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'ヱホバの前にはもろもろの國民みななきにひとし ヱホバはかれらを無もののごとく空きもののごとく思ひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, '然ばなんぢら誰をもて神にくらべ いかなる肖像をもて神にたぐふか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, '偶像はたくみ鑄てつくり 金工こがねをもて之をおほひ白銀をもて之がために鏈をつくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'かかる寳物をそなへえざる貧しきものは朽まじき木をえらみ良匠をもとめてうごくことなき像をたたしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'なんぢら知ざるか なんぢら聞ざるか 始よりなんぢらに傳へざりしか なんぢらは地の基をおきしときより悟らざりしか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'ヱホバは地のはるか上にすわり地にすむものを蝗のごとく視たまふ おほぞらを薄絹のごとく布き これを住ふべき幕屋のごとくはり給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, '又もろもろの君をなくならしめ地の審士をむなしくせしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'かれらは僅かに植られ僅かに播れ その幹わづかに地に根ざししに 神そのうへを吹たまへば即ちかれて藁のごとく暴風にまきさらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '聖者いひ給はく さらばなんぢら誰をもて我にくらべ我にたぐふか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'なんぢら眼をあげて高をみよ たれか此等のものを創造せしやをおもへ 主は數をしらべてその萬象をひきいだしおのおのの名をよびたまふ 主のいきほひ大なり その力のつよきがゆゑに一も缺ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'ヤコブよなんぢ何故にわが途はヱホバにかくれたりといふや イスラエルよ汝なにゆゑにわが訟はわが神の前をすぎされりとかたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, '汝しらざるか聞ざるかヱホバはとこしへの神地のはての創造者にして倦たまふことなく また疲れたまふことなく その聰明こと測りがたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, '疲れたるものには力をあたへ勢力なきものには強きをまし加へたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, '年少きものもつかれてうみ壯んなるものも衰へおとろふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, '然はあれどヱホバを俟望むものは新なる力をえん また鷲のごとく翼をはりてのぼらん 走れどもつかれず歩めども倦ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'もろもろの島よわがまへに默せ もろもろの民よあらたなる力をえて近づききたれ 而して語れ われら寄集ひて諭らはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'たれか東より人をおこししや われは公義をもて之をわが足下に召し その前にもろもろの國を服せしめ また之にもろもろの王ををさめしめ かれらの劍をちりのごとくかれらの弓をふきさらるる藁のごとくならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, '斯て彼はこれらのものを追 その足いまだ行ざる道をやすらかに過ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'このことは誰がおこなひしや たが成しや たが太初より世々の人をよびいだししや われヱホバなり 我ははじめなり終なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'もろもろの島はこれを見ておそれ地の極はをののきて寄集ひきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'かれら互にその隣をたすけ その兄弟にいひけるは なんぢ雄々しかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, '木匠は鐵工をはげまし鎚をもて平らぐるものは鐵碪をうつものを勵ましていふ 接合せいとよしと また釘をもて堅うして搖くことなからしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, '然どわが僕イスラエルよ わが選めるヤコブわが友アブラハムの裔よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'われ地のはてより汝をたづさへきたり地のはしよりなんぢを召 かくて汝にいへり 汝はわが僕われ汝をえらみて棄ざりきと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'おそるるなかれ 我なんぢとともにあり 驚くなかれ我なんぢの神なり われなんぢを強くせん 誠になんぢを助けん 誠にわがただしき右手なんぢを支へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, '視よなんぢにむかひて怒るものはみな恥をえて惶てふためかん なんぢと爭ふものは無もののごとくなりて滅亡せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'なんぢ尋ぬるとも汝とたたかふ人々にあはざるべし 汝といくさする者はなきものの如くなりて虚しくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'そは我ヱホバなんぢの神はなんぢの右手をとりて汝にいふ 懼るるなかれ我なんぢを助けんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'またヱホバ宣給ふ なんぢ虫にひとしきヤコブよイスラエルの人よ おそるるなかれ我なんぢをたすけん汝をあがなふものはイスラエルの聖者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, '視よわれ汝をおほくの鋭歯ある新しき打麥の器となさん なんぢ山をうちて細微にし岡を粃糠のごとくにすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'なんぢ簸げば風これを巻さり 狂風これを吹ちらさん 汝はヱホバによりて喜びイスラエルの聖者によりて誇らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, '貧しきものと乏しきものと水を求めて水なくその舌かわきて衰ふるとき われヱホバ聽てこたへん 我イスラエルの神かれらを棄ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'われ河をかぶろの山にひらき泉を谷のなかにいだし また荒野を池となし乾ける地を水の源と變ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, '我あれのに香柏 合歎樹 もちの樹 および油の樹をうゑ沙漠に松 杉 及び黄楊をともに置ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'かくて彼等これを見てヱホバの手の作たまふところイスラエルの聖者の造り給ふ所なるをしり且こころをとめ且ともどもにさとらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'ヱホバ言給く なんぢらの道理をとり出せ ヤコブの王いひたまはく 汝等のかたき證をもちきたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'これを持來りてわれらに後ならんとする事をしめせ そのいやさきに成るべきことを示せ われら心をとめてその終をしらん 或はきたらんとする事をわれらに聞すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'なんぢら後ならんとすることをしめせ我儕なんぢらが神なることを知らん なんぢら或はさいはひし或はわざはひせよ 我儕ともに見ておどろかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, '視よなんぢらは無もののごとし なんぢらの事はむなし なんぢらを撰ぶものは憎むべきものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'われ一人を起して北よりきたらせ我が名をよぶものを東よりきたらしむ 彼きたりもろもろの長をふみて泥のごとくにし陶工のつちくれを踐がごとくにせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'たれか初よりこれらの事をわれらに告てしらしめたりや たれか上古よりわれらに告てこは是なりといはしめたりや 一人だに告るものなし一人だに聞するものなし 一人だになんぢらの言をきくものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'われ豫じめシオンにいはん なんぢ視よ かれらを見よと われ又よきおとづれを告るものをヱルサレムに予へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'われ見るに一人だになし かれらのなかに謀略をまうくるもの一人だになし 我かれらに問どこたふるもの一人だになし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'かれらの爲はみな徒然にして無もののごとし その偶像は風なりまた空しきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'わが扶くるわが僕わが心よろこぶわが撰人をみよ 我わが靈をかれにあたへたり かれ異邦人に道をしめすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'かれは叫ぶことなく聲をあぐることなくその聲を街頭にきこえしめず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'また傷める蘆ををることなくほのくらき燈火をけすことなく 眞理をもて道をしめさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'かれは衰へず喪膽せずして道を地にたてをはらん もろもろの島はその法言をまちのぞむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, '天をつくりてこれをのべ 地とそのうへの產物とをひらき そのうへの民に息をあたへ その中をあゆむものに靈をあたへたまふ神ヱホバかく言給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '云くわれヱホバ公義をもてなんぢを召たり われなんぢの手をとり汝をまもり なんぢを民の契約とし異邦人のひかりとなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, '而して瞽の目を開き俘囚を獄よりいだし 暗にすめるものを檻のうちより出さしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'われはヱホバなり是わが名なり 我はわが榮光をほかの者にあたへず わがほまれを偶像にあたへざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'さきに預言せるところはや成れり 我また新しきことをつげん 事いまだ兆さざるさきに我まづなんぢらに聞せんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, '海にうかぶもの 海のなかに充るもの もろもろの島およびその民よ ヱホバにむかひて新しき歌をうたひ 地の極よりその頌美をたたへまつれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, '荒野とその中のもろもろの邑とケダル人のすめるもろもろの村里はこゑをあげよ セラの民はうたひて山のいただきよりよばはれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, '榮光をヱホバにかうぶらせ その頌美をもろもろの島にて語りつげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'ヱホバ勇士のごとく出たまふ また戰士のごとく熱心をおこし 聲をあげてよばはり大能をあらはして仇をせめ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'われ久しく聲をいださず默して己をおさへたり 今われ子をうまんとする婦人のごとく叫ばん 我いきづかしくかつ喘がん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'われ山と岡とをあらし且すべてその上の木草をからし もろもろの河を島としもろもろの池を涸さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'われ瞽者をその未だしらざる大路にゆかしめ その未だしらざる徑をふましめ 暗をその前に光となし 曲れるをその前になほくすべし 我これらの事をおこなひて彼らをすてじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, '刻みたる偶像にたのみ鑄たる偶像にむかひて汝等はわれらの神なりといふものは退けられて大に恥をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, '聾者よきけ 瞽者よ眼をそそぎてみよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, '瞽者はたれぞ わが僕にあらずや 誰かわがつかはせる使者の如き瞽者あらんや 誰かわが友の如きめしひあらんや 誰かヱホバの僕のごときめしひあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, '汝おほくのことを見れども顧みず 耳をひらけども聞ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'ヱホバおのれ義なるがゆゑに大にしてたふとき律法をたまふをよろこび給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, '然るにこの民はかすめられ奪はれて みな穴中にとらはれ獄のなかに閉こめらる 斯てその掠めらるるを助くる者なく その奪はれたるを償へといふ者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'なんぢらのうち誰かこのことに耳をかたぶけん たれか心をもちゐて後のために之をきかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'ヤコブを奪はせしものは誰ぞ かすむる者にイスラエルをわたしし者はたれぞ 是ヱホバにあらずや われらヱホバに罪ををかし その道をあゆまず その律法にしたがふことを好まざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'この故にヱホバ烈しき怒をかたぶけ 猛きいくさをきたらせ その烈しきこと火の如く四圍にもゆれども彼しらず その身に焚せまれども心におかざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'ヤコブよなんぢを創造せるヱホバいま如此いひ給ふ イスラエルよ汝をつくれるもの今かく言給ふ おそるるなかれ我なんぢを贖へり 我なんぢの名をよべり汝はわが有なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'なんぢ水中をすぐるときは我ともにあらん河のなかを過るときは水なんぢの上にあふれじ なんぢ火中をゆくとき焚るることなく火焰もまた燃つかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, '我はヱホバなんぢの神イスラエルの聖者 なんぢの救主なり われエジプトを予えてなんぢの贖代となし エテオピアとセバとをなんぢに代ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'われ看てなんぢを寶とし尊きものとして亦なんぢを愛す この故にわれ人をもてなんぢにかへ 民をなんぢの命にかへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, '懼るるなかれ我なんぢとともにあり 我なんぢの裔を東よりきたらせ西より汝をあつむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'われ北にむかひて釋せといひ南にむかひて留るなかれといはん わが子輩を遠きよりきたらせ わが女らを地の極よりきたらせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'すべてわが名をもて稱へらるる者をきたらせよ 我かれらをわが榮光のために創造せり われ曩にこれを造りかつ成をはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, '目あれども瞽者のごとく耳あれど聾者のごとき民をたづさへ出よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, '國々はみな相集ひもろもろの民はあつまるべし 彼等のうち誰かいやさきに成るべきことをつげ之をわれらに聞することを得んや その證人をいだして己の是なるをあらはすべし 彼等ききて此はまことなりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'ヱホバ宣給くなんぢらはわが證人わがえらみし僕なり 然ばなんぢら知てわれを信じわが主なるをさとりうべし 我よりまへにつくられし神なく我よりのちにもあることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'ただ我のみ我はヱホバなり われの外にすくふ者あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'われ前につげまた救をほどこし また此事をきかせたり 汝等のうちには他神なかりき なんぢらはわが證人なり 我は神なり これヱホバ宣給るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, '今よりわれは主なりわが手より救ひいだし得るものなし われ行はば誰かとどむることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'なんぢらを贖ふものイスラエルの聖者ヱホバかく言たまふ なんぢらの爲にわれ人をバビロンにつかはし彼處にあるカルデヤ人をことごとく下らせ その宴樂の船にのりてのがれしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'われはヱホバなんぢらの聖者イスラエルを創造せしもの又なんぢらの王なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'ヱホバは海のなかに大路をまうけ大なる水のなかに徑をつくり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, '戰車および馬 軍兵 武士をいできたらせ ことごとく仆れて起ることあたはず 皆ほろびて燈火のきえうするが如くならしめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'ヱホバ言給く なんぢら往昔のことを思ひいづるなかれ また上古のことをかんがふるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, '視よわれ新しき事をなさん頓ておこるべし なんぢら知ざるべけんや われ荒野に道をまうけ沙漠に河をつくらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, '野の獸われを崇むべし 野犬および駝鳥もまた然り われ水を荒野にいだし河を沙漠にまうけてわが民わがえらびたる者にのましむべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'この民はわが頌美をのべしめんとて我おのれのために造れるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, '然るにヤコブよ汝われを呼たのまざりき イスラエルよ汝われを厭ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'なんぢ燔祭のひつじを我にもちきたらず犠牲をもて我をあがめざりき われ汝にそなへものの荷をおはせざりき また乳香をもて汝をわづらはせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'なんぢは銀貨をもて我がために菖蒲をかはず 犠牲のあぶらをもて我をあかしめず 反てなんぢの罪の荷をわれに負せ なんぢの邪曲にて我をわづらはせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'われこそ我みづからの故によりてなんぢの咎をけし汝のつみを心にとめざるなれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'なんぢその是なるをあらはさんがために己が事をのべて我に記念せしめよ われら相共にあげつらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'なんぢの遠祖つみををかし汝のをしへの師われにそむけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'この故にわれ聖所の長たちを汚さしめヤコブを詛はしめイスラエルをののしらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'されどわが僕ヤコブよわが撰みたるイスラエルよ今きけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'なんぢを創造し なんぢを胎内につくり又なんぢを助くるヱホバ如此いひたまふ わがしもベヤコブよわが撰みたるヱシュルンよおそるるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'われ渇けるものに水をそそぎ乾たる地に流をそそぎ わが靈をなんぢの子輩にそそぎ わが恩惠をなんぢの裔にあたふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, '斯てかれらは草のなかにて川のほとりの柳のごとく生そだつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'ある人はいふ我はヱホバのものなりと ある人はヤコブの名をとなへん ある人はヱホバの有なりと手にしるしてイスラエルの名をなのらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'ヱホバ、イスラエルの王イスラエルをあがなふもの萬軍のヱホバ如此いひたまふ われは始なりわれは終なり われの外に神あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, '我いにしへの民をまうけしより以來 たれかわれのごとく後事をしめし又つげ又わが前にいひつらねんや 試みに成んとすること來らんとすることを告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'なんぢら懼るるなかれ慴くなかれ 我いにしへより聞せたるにあらずや告しにあらずや なんぢらはわが證人なり われのほか神あらんや 我のほかには磐あらず われその一つだに知ことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, '偶像をつくる者はみな空しく かれらが慕ふところのものは益なし その證を見るものは見ことなく知ことなし 斯るがゆゑに恥をうくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'たれか神をつくり又えきなき偶像を鑄たりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, '視よその伴侶はみなはぢん その匠工らは人なり かれら皆あつまりて立ときはおそれてもろともに恥るなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, '鐵匠は斧をつくるに炭の火をもてこれをやき鎚もてこれを鍛へつよき碗をもてこれをうちかたむ 饑れば力おとろへ水をのまざればつかれはつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, '木匠はすみなはをひきはり朱にてゑがき鐁にてけづり文回をもて畫き 之を人の形にかたどり人の美しき容にしたがひて造り 而して家のうちに安置す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'あるひは香柏をきりあるひは槲をとり あるひは橿をとり 或ははやしの樹のなかにて一をえらび あるひは杉をうゑ雨をえて長たしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, '而して人これを薪となし之をもておのが身をあたため又これを燃してパンをやき又これを神につくりてをがみ偶像につくりてその前にひれふす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'その半は火にもやしその半は肉をにて食ひ あるひは肉をあぶりてくひあき また身をあたためていふ ああ我あたたまれり われ熱きをおぼゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, '斯てその餘をもて神につくり偶像につくりてその前にひれふし之ををがみ之にいのりていふ なんぢは吾神なり我をすくへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'これらの人は知ことなく悟ることなし その眼ふさがりて見えず その心とぢてあきらかならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, '心のうちに思ふことをせず智識なく明悟なきがゆゑに我そのなかばを火にもやしその炭火のうへにパンをやき肉をあぶりて食ひ その木のあまりをもて我いかで憎むべきものを作るべけんや 我いかで木のはしくれに俯伏すことをせんやといふ者もなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'かかる人は灰をくらひ 迷へる心にまどはされて己がたましひを救ふあたはず またわが右手にいつはりあるにあらずやとおもはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'ヤコブよ イスラエルよ 此等のことを心にとめよ 汝はわが僕なり 我なんぢを造れり なんぢわが僕なり イスラエルよ我はなんぢを忘れじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, '我なんぢの愆を雲のごとくに消し なんぢの罪を霧のごとくにちらせり なんぢ我にかへれ我なんぢを贖ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, '天よ うたうたへヱホバこのことを成たまへり 下なる地よよばはれ もろもろの山よ林およびその中のもろもろの木よ こゑを發ちてうたふべし ヱホバはヤコブを贖へり イスラエルのうちに榮光をあらはし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'なんぢを贖ひなんぢを胎内につくれるヱホバかく言たまふ 我はヱホバなり我よろづのものを創造し ただ我のみ天をのべ みづから地をひらき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'いつはるものの豫兆をむなしくし卜者をくるはせ智者をうしろに退けてその知識をおろかならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'われわが僕のことばを遂しめ わが使者のはかりごとを成しめ ヱルサレムについては民また住はんといひ ユダのもろもろの邑については重ねて建らるべし我その荒廢たるところを舊にかへさんといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'また淵に命ず かわけ我なんぢのもろもろの川をほさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, '又クロスについては彼はわが牧者すべてわが好むところを成しむる者なりといひ ヱルサレムについてはかさねて建られその宮の基すゑられんといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'われヱホバわが受膏者クロスの右手をとりてもろもろの國をそのまへに降らしめ もろもろの王の腰をとき扉をその前にひらかせて門をとづるものなからしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'われ汝のまへにゆきて崎嶇をたひらかにし 銅の門をこぼち くろがねの關木をたちきるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'われなんぢに暗ところの財貨とひそかなるところに藏せるたからとを予へ なんぢに我はヱホバなんぢの名をよべるイスラエルの神なるを知しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'わが僕ヤコブわが撰みたるイスラエルのために我なんぢの名をよべり 汝われを知ずといへどわれ名をなんぢに賜ひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'われはヱホバなり 我のほかに神なし 一人もなし 汝われをしらずといへども我なんぢを固うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, '而して日のいづるところより西のかたまで人々我のほかに神なしと知べし 我はヱホバなり他にひとりもなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'われは光をつくり又くらきを創造す われは平和をつくりまた禍害をさうざうす 我はヱホバなり 我すべてこれらの事をなすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, '天ようへより滴らすべし 雲よ義をふらすべし 地はひらけて救を生じ義をもともに萌いだすべし われヱホバ之を創造せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, '世人はすゑものの中のひとつの陶器なるに己をつくれる者とあらそふはわざはひなるかな 泥塊はすゑものつくりにむかひて汝なにを作るかといふべけんや 又なんぢの造りたる者なんぢを手なしといふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, '父にむかひて汝なにゆゑに生むことをせしやといひ 婦にむかひて汝なにゆゑに產のくるしみをなししやといふ者はわざはひなるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'ヱホバ、イスラエルの聖者イスラエルを造れるもの如此いひたまふ 後きたらんとすることを我にとへ またわが子女とわが手の工とにつきて汝等われに言せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'われ地をつくりてそのうへに人を創造せり われ自らの手をもて天をのべ その萬象をさだめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'われ義をもて彼のクロスを起せり われそのすべての道をなほくせん 彼はわが邑をたてわが俘囚を價のためならず報のためならずして釋すべし これ萬軍のヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'ヱホバ如此いひたまふ エジプトがはたらきて得しものとエテオピアがあきなひて得しものとはなんぢの有とならん また身のたけ高きセバ人きたりくだりて汝にしたがひ繩につながれて降り なんぢのまへに伏しなんぢに祈りていはん まことに神はなんぢの中にいませり このほかに神なし一人もなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, '救をほどこし給ふイスラエルの神よ まことに汝はかくれています神なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, '偶像をつくる者はみな恥をいだき辱かしめをうけ諸共にはぢあわてて退かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'されどイスラエルはヱホバにすくはれて永遠の救をえん なんぢらは世々かぎりなく恥をいだかず辱かしめをうけじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'ヱホバは天を創造したまへる者にしてすなはち神なり また地をもつくり成てこれを堅くし徒然にこれを創造し給はず これを人の住所につくり給へり ヱホバかく宣給ふ われはヱホバなり我のほかに神あることなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'われは隱れたるところ地のくらき所にてかたらず 我はヤコブの裔になんぢらが我をたづぬるは徒然なりといはず 我ヱホバはただしき事をかたり直きことを告ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, '汝等もろもろの國より脱れきたれる者よ つどひあつまり共にすすみききたれ 木の像をになひ救ふことあたはざる神にいのりするものは無智なるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'なんぢらその道理をもちきたりて述よ また共にはかれ 此事をたれか上古より示したりや 誰かむかしより告たりしや 此はわれヱホバならずや 我のほかに神あることなし われは義をおこなひ救をほどこす神にして我のほかに神あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, '地の極なるもろもろの人よ なんぢら我をあふぎのぞめ然ばすくはれん われは神にして他に神なければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'われは己をさして誓ひたり この言はただしき口よりいでたれば反ることなし すべての膝はわがまへに屈み すべての舌はわれに誓をたてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, '人われに就ていはん正義と力とはヱホバにのみありと 人々ヱホバにきたらん すべてヱホバにむかひて怒るものは恥をいだくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'イスラエルの裔はヱホバによりて義とせられ且ほこらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'ベルは伏しネボは屈む かれらの像はけものと家畜とのうへにあり なんぢらが擡げあるきしものは荷となりて疲れおとろへたるけものの負ところとなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'かれらは屈みかれらは共にふし その荷となれる者をすくふこと能はずして己とらはれゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'ヤコブの家よイスラエルのいへの遺れるものよ 腹をいでしより我におはれ胎をいでしより我にもたげられしものよ 皆われにきくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'なんぢらの年老るまで我はかはらず白髮となるまで我なんぢらを負ん 我つくりたれば擡ぐべし我また負ひかつ救はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'なんぢら我をたれに比べ たれに配ひ たれに擬らへ かつ相くらぶべきか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, '人々ふくろより黄金をかたぶけいだし權衡をもて白銀をはかり金工をやとひてこれを神につくらせ之にひれふして拜む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, '彼等はこれをもたげて肩にのせ 負ひゆきてその處に安置す すなはち立てその處をはなれず 人これにむかひて呼はれども答ふること能はず 又これをすくひて苦難のうちより出すことあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'なんぢら此事をおもひいでて堅くたつべし 悖逆者よこのことを心にとめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, '汝等いにしへより以來のことをおもひいでよ われは神なり我のほかに神なし われは神なり我のごとき者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'われは終のことを始よりつげ いまだ成ざることを昔よりつげ わが謀畧はかならず立つといひ すべて我がよろこぶことを成んといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'われ東より鷲をまねき遠國よりわが定めおける人をまねかん 我このことを語りたれば必らず來らすべし 我このことを謀りたればかならず成すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'なんぢら心かたくなにして義にとほざかるものよ我にきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'われわが義をちかづかしむ可ればその來ること遠からず わが救おそからず 我すくひをシオンにあたへ わが榮光をイスラエルにあたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'バビロンの處女よ くだりて塵のなかにすわれ カルデヤ人のむすめよ座にすわらずして地にすわれ 汝ふたたび婀娜にして嬌なりととなへらるることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, '礱をとりて粉をひけ 面帕をとりさり袿をぬぎ髓をあらはして河をわたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'なんぢの肌はあらはれなんぢの恥はみゆべし われ仇をむくいて人をかへりみず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'われらを贖ひたまふ者はその名を萬軍のヱホバ、イスラエルの聖者といふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'カルデヤ人のむすめよ なんぢ口をつぐみてすわれ 又くらき所にいりてをれ 汝ふたたびもろもろの國の主母ととなへらるることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'われわが民をいきどほりわが產業をけがして之をなんぢの手にあたへたり 汝これに憐憫をほどこさず年老たるもののうへに甚だおもき軛をおきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, '汝いへらく我とこしへに主母たらんと 斯てこれらのことを心にとめず亦その終をおもはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'なんぢ歡樂にふけり安らかにをり 心のうちにただ我のみにして我のほかに誰もなく我はやもめとなりてをらず また子をうしなふことを知まじとおもへる者よなんぢ今きけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, '子をうしなひ寡婦となるこの二つのこと一日のうちに俄になんぢに來らん汝おほく魔術をおこなひひろく呪詛をほどこすと雖もみちみちて汝にきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, '汝おのれの惡によりたのみていふ 我をみるものなしと なんぢの智慧となんぢの聰明とはなんぢを惑せたり なんぢ心のうちにおもへらくただ我のみにして我のほかに誰もなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'この故にわざはひ汝にきたらん なんぢ呪ひてこれを除くことをしらず 艱難なんぢに落きたらん 汝これをはらふこと能はず なんぢの思ひよらざる荒廢にはかに汝にきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, '今なんぢわかきときより勤めおこなひたる呪詛とおほくの魔術とをもて立むかふべしあるひは益をうることあらん あるひは敵をおそれしむることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'なんぢは謀畧おほきによりて倦つかれたり かの天をうらなふもの星をみるもの新月をうらなふ者もし能はば いざたちて汝をきたらんとする事よりまぬかれしむることをせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, '彼らは藁のごとくなりて火にやかれん おのれの身をほのほの勢力よりすくひいだすこと能はず その火は身をあたたむべき炭火にあらず又その前にすわるべき火にもあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, '汝がつとめて行ひたる事は終にかくのごとくならん 汝のわかきときより汝とうりかひしたる者おのおのその所にさすらひゆきて一人だになんぢを救ふものなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'ヤコブの家よなんぢら之をきけ 汝らはイスラエルの名をもて稱へられ ユダの根源よりいでヱホバの名によりて誓ひイスラエルの神をかたりつぐれども 眞實をもてせず正義をもてせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'かれらはみづから聖京のものととなへイスラエルの神によりたのめり その名は萬軍のヱホバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'われ今よりさきに成しことを旣にいにしへより告たり われ口よりいだして旣にのべつたへたり 我にはかにこの事をおこなひ而して成ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'われ汝がかたくなにして項の筋はくろがねその額はあかがねなるを知れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'このゆゑに我はやくよりかの事をなんぢにつげ その成ざるさきに之をなんぢに聞しめたり 恐くはなんぢ云ん わが偶像これを成せり刻みたるざう鑄たる像これを命じたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'なんぢ旣にきけり 凡てこれを視よ 汝ら之をのべつたへざるか われ今より新なる事なんぢが未だしらざりし秘事をなんぢに示さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'これらの事はいま創造せられしにて上古よりありしにあらず この日よりさきに汝これを聞ざりき 然らずば汝いはん視よわれこれを知れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, '汝これを聞こともなく知こともなく なんぢの耳はいにしへより開けざりき 我なんぢが欺きあざむきて生れながら悖逆者ととなへられしを知ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'わが名のゆゑによりて我いかりを遲くせん わが頌美のゆゑにより我しのびてなんぢを絶滅すことをせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, '視よわれなんぢを煉たり されど白銀の如くせずして患難の爐をもてこころみたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'われ己のため我おのれの爲にこれを成ん われ何でわが名をけがさしむべき 我わが榮光をほかの者にあたることをせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'ヤコブよわが召たるイスラエルよ われにきけ われは是なり われは始また終なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'わが手は地のもとゐを置わが右の手は天をのべたり 我よべば彼等はもろともに立なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, '汝ら皆あつまりてきけ ヱホバの愛するものヱホバの好みたまふ所をバビロンに成し その腎はカルデヤ人のうへにのぞまん 彼等のうち誰かこれらの事をのべつげしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'ただ我のみ我かたれり 我かれをめし我かれをきたらせたり その道さかゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'なんぢら我にちかよりて之をきけ 我はじめより之をひそかに語りしにあらず その成しときより我はかしこに在り いま主ヱホバわれとその靈とをつかはしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'なんぢの贖主イスラエルの聖者ヱホバかく言給く われはなんぢの神ヱホバなり 我なんぢに益することを敎へ なんぢを導きてそのゆくべき道にゆかしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, '願くはなんぢわが命令にききしたがはんことを もし然らばなんぢの平安は河のごとく 汝の義はうみの波のごとく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'なんぢの裔はすなのごとく 汝の體よりいづる者は細沙のごとくになりて その名はわがまへより絶るることなく亡さるることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'なんぢらバビロンより出てカルデヤ人よりのがれよ なんらぢ歡の聲をもてのべきかせ地のはてにいたるまで語りつたへ ヱホバはその僕ヤコブをあがなひ給へりといへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'ヱホバかれらをして沙漠をゆかしめ給へるとき彼等はかわきたることなかりき ヱホバ彼等のために磐より水をながれしめ また磐をさきたまへば水ほどばしりいでたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'ヱホバいひたまはく惡きものには平安あることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'もろもろの島よ我にきけ 遠きところのもろもろの民よ耳をかたむけよ 我うまれいづるよりヱホバ我を召し われ母の胎をいづるよりヱホバわが名をかたりつげたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'ヱホバわが口を利劍となし我をその手のかげにかくし 我をとぎすましたる矢となして箙にをさめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'また我にいひ給はく 汝はわが僕なり わが榮光のあらはるべきイスラエルなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'されど我いへり われは徒然にはたらき益なくむなしく力をつひやしぬと 然はあれど誠にわが審判はヱホバにあり わが報はわが神にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'ヤコブをふたたび己にかへらしめイスラエルを己のもとにあつまらせんとて 我をうまれいでしより立ておのれの僕となし給へるヱホバいひ給ふ(我はヱホバの前にたふとくせらる 又わが神はわが力となりたまへり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'その聖言にいはく なんぢわが僕となりてヤコブのもろもろの支派をおこし イスラエルのうちののこりて全うせしものを歸らしむることはいと輕し 我また汝をたてて異邦人の光となし 我がすくひを地のはてにまで到らしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'ヱホバ、イスラエルの贖主イスラエルの聖者は人にあなどらるるもの 民にいみきらはるるもの 長たちに役せらるる者にむかひて如此いひたまふ もろもろの王は見てたちもろもろの君はみて拜すべし これ信實あるヱホバ、イスラエルの聖者なんぢを選びたまへるが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'ヱホバ如此いひたまふ われ惠のときに汝にこたへ救の日になんぢを助けたり われ汝をまもりて民の契約とし國をおこし荒すたれたる地をまた產業としてかれらにつがしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'われ縛しめられたる者にいでよといひ暗にをるものに顯れよといはん かれら途すがら食ふことをなし もろもろの禿なる山にも牧草をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'かれらは饑ずかわかず 又やけたる砂もあつき日もうつことなし 彼等をあはれむもの之をみちびきて泉のほとりに和かにみちびき給ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, '我わがもろもろの山を路とし わが大路をたかくせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, '視よ人々あるひは遠きよりきたり あるひは北また西よりきたらん 或はまたシニムの地よりきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, '天ようたへ地よよろこべ もろもろの山よ聲をはなちてうたへ ヱホバはその民をなぐさめその苦むものを憐みたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, '然どシオンはいへりヱホバ我をすて主われをわすれたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, '婦その乳兒をわすれて己がはらの子をあはれまざることあらんや 縦ひかれら忘るることありとも我はなんぢを忘るることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'われ掌になんぢを彫刻めり なんぢの石垣はつねにわが前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'なんぢの子輩はいそぎ來り なんぢを毀つもの汝をあらす者は汝より出さらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'なんぢ目をあげて環視せよ これらのもの皆あひあつまりて汝がもとに來るべし ヱホバ宣給く われは活なんぢ此等をみな身によそほひて飾となし 新婦の帶のごとくに之をまとふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'なんぢの荒かつ廢れたるところ毀たれたる地は こののち住ふもの多くして狹きをおぼえん なんぢを呑つくししもの遙にはなれ去るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'むかし別れたりしなんぢの子輩はのちの日なんぢの耳のあたりにて語りあはん云く ここは我がために狹し なんぢ外にゆきて我にすむべき所をえしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'その時なんぢ心裏にいはん 誰かわがために此等のものを生しや われ子をうしなひて獨居りかつ俘れ且さすらひたり 誰かこれを育てしや 視よわれ一人のこされたり 此等はいづこに居しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, '主ヱホバいひたまはく 視よわれ手をもろもろの國にむかひてあげ 旗をもろもろの民にむかひてたてん 斯てかれらはその懷中になんぢの子輩をたづさへ その肩になんぢの女輩をのせきたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'もろもろの王はなんぢの養父となり その后妃はなんぢの乳母となり かれらはその面を地につけて汝にひれふし なんぢの足の塵をなめん 而して汝わがヱホバなるをしり われを俟望むものの恥をかうぶることなきを知るならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, '勇士がうばひたる掠物をいかでとりかへし 強暴者がかすめたる虜をいかで救いだすことを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'されどヱホバ如此いひたまふ云く ますらをが掠めたる虜もとりかへされ 強暴者がうばひたる掠物もすくひいださるべし そは我なんぢを攻るものをせめてなんぢの子輩をすくふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, '我なんぢを虐ぐるものにその肉をくらはせ またその血をあたらしき酒のごとくにのませて酔しめん 而して萬民はわがヱホバにして汝をすくふ者なんぢを贖ふものヤコブの全能者なることを知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'ヱホバかくいひ給ふ わがなんぢらの母をさりたる離書はいづこにありや 我いづれの債主になんぢらを賣わたししや 視よなんぢらはその不義のために賣られ なんぢらの母は汝らの咎戻のために去られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'わがきたりし時なにゆゑ一人もをらざりしや 我よびしとき何故ひとりも答ふるものなかりしや わが手みぢかくして贖ひえざるか われ救ふべき力なからんや 視よわれ叱咤すれば海はかれ河はあれのとなりそのなかの魚は水なきによりかわき死て臭氣をいだすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'われ黑きころもを天にきせ麁布をもて蔽となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, '主ヱホバは敎をうけしものの舌をわれにあたへ言をもて疲れたるものを扶支ふることを知得しめたまふ また朝ごとに醒しわが耳をさまして敎をうけし者のごとく聞ことを得しめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, '主ヱホバわが耳をひらき給へり われは逆ふことをせず退くことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'われを撻つものにわが背をまかせわが鬚をぬくものにわが頬をまかせ 恥と唾とをさくるために面をおほふことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, '主ヱホバわれを助けたまはん この故にわれ恥ることなかるべし 我わが面を石の如くして恥しめらるることなきを知る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'われを義とするもの近きにあり たれか我とあらそはんや われら相共にたつべし わが仇はたれぞや近づききたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, '主ヱホバわれを助け給はん 誰かわれを罪せんや 視よかれらはみな衣のごとくふるび蠧のためにくひつくされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, '汝等のうちヱホバをおそれその僕の聲をきくものは誰ぞや 暗をあゆみて光をえざるともヱホバの名をたのみおのれの神にたよれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, '火をおこし火把を帶るものよ汝等みなその火のほのほのなかをあゆめ 又なんぢらの燃したる火把のなかをあゆめ なんぢら斯のごとき事をわが手よりうけて悲みのうちに臥べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, '義をおひ求めヱホバを尋ねもとむるものよ我にきけ なんぢらが斫出されたる磐となんぢらの掘出されたる穴とをおもひ見よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'なんぢらの父アブラハム及びなんぢらを生たるサラをおもひ見よ われ彼をその唯一人なりしときに召しこれを祝してその子孫をまし加へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'そはヱホバ、シオンを慰め またその凡てあれたる所をなぐさめて その荒野をエデンのごとくその沙漠をヱホバの園のごとくなしたまへり 斯てその中によろこびと歡樂とあり感謝とうたうたふ聲とありてきこゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'わが民よわが言にこころをとめよ わが國人よわれに耳をかたぶけよ 律法はわれより出づ われわが途をかたく定めてもろもろの民の光となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'わが義はちかづきわが救はすでに出たり わが臂はもろもろの民をさばかん もろもろの島はわれを俟望み わがかひなに依賴ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'なんぢら目をあげて天を觀また下なる地をみよ 天は烟のごとくきえ地は衣のごとくふるびその中にすむ者これとひとしく死ん されどわが救はとこしへにながらへ わが義はくだくることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, '義をしるものよ心のうちにわが律法をたもつ民よ われにきけ 人のそしりをおそるるなかれ人のののしりに慴くなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'そはかれら衣のごとく蠧にはまれ羊の毛のごとく蟲にはまれん されどわが義はとこしへに存らへ わがすくひ萬代におよぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'さめよ醒よヱホバの臂よちからを着よ さめて古への時むかしの代にありし如くなれ ラハブをきりころし鱷をさしつらぬきたるは汝にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, '海をかわかし大なる淵の水をかわかし また海のふかきところを贖はれたる人のすぐべき路となししは汝にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'ヱホバに贖ひすくはれしもの歌うたひつつ歸りてシオンにきたり その首にとこしへの歡喜をいただきて快樂とよろこびとをえん 而してかなしみと歎息とはにげさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, '我こそ我なんぢらを慰むれ 汝いかなる者なれば死べき人をおそれ草の如くなるべき人の子をおそるるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'いかなれば天をのべ地の基をすゑ汝をつくりたまへるヱホバを忘れしや 何なれば汝をほろぼさんとて豫備する虐ぐるものの憤れるをみて常にひねもす懼るるか 虐ぐるものの忿恚はいづこにありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, '身をかがめゐる俘囚はすみやかに解れて 死ることなく穴にくだることなく その食はつくること無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, '我は海をふるはせ波をなりどよめかする汝の神ヱホバなり その御名を萬軍のヱホバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, '我わが言をなんぢの口におきわが手のかげにて汝をおほへり かくてわれ天をうゑ地の基をすゑ シオンにむかひて汝はわが民なりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'ヱルサレムよさめよさめよ起よ なんぢ前にヱホバの手よりその忿恚のさかづきをうけて飮み よろめかす大杯をのみ且すひほしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'なんぢの生るもろもろの子のなかに汝をみちびく者なく 汝のそだてたるもろもろの子の中にてなんぢの手をたづさふる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'この二のこと汝にのぞめり誰かなんぢのために歎んや 荒廢の饑饉ほろびの劍なんぢに及べり我いかにして汝をなぐさめんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'なんぢの子らは息たえだえにして網にかかれる羚羊のごとくし街衢の口にふす ヱホバの忿恚となんぢの神のせめとはかれらに滿たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'このゆゑに苦しめるもの酒にあらで酔たるものよ之をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'なんぢの主ヱホバおのが民の訟をあげつらひ給ふ なんぢの神かくいひ給ふ 我よろめかす酒杯をなんぢの手より取除き わがいきどほりの大杯をとりのぞきたり 汝ふたたびこれを飮ことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, '我これを汝をなやますものの手にわたさん 彼らは曩になんぢの靈魂にむかひて云らく なんぢ伏せよわれら越ゆかんと 而してなんぢその背を地のごとくし衢のごとくし彼等のこえゆくに任せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'シオンよ醒よさめよ汝の力を衣よ 聖都ヱルサレムよなんぢの美しき衣をつけよ 今より割禮をうけざる者および潔からざるものふたたび汝にいること無るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'なんぢ身の塵をふりおとせ ヱルサレムよ起よすわれ 俘れたるシオンのむすめよ汝がうなじの繩をときすてよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'そはヱホバかく言給ふ なんぢらは價なくして賣られたり 金なくして贖はるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, '主ヱホバ如此いひ給ふ 曩にわが民エジプトにくだりゆきて彼處にとどまれり アツスリヤ人ゆゑなくして彼等をしへたげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'ヱホバ宣給く わが民はゆゑなくして俘れたり されば我ここに何をなさん ヱホバのたまはく 彼等をつかさどる者さけびよばはり わが名はつねに終日けがさるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'この故にわが民はわが名をしらん このゆゑにその日には彼らこの言をかたるものの我なるをしらん 我ここに在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'よろこびの音信をつたへ平和をつげ 善おとづれをつたへ救をつげ シオンに向ひてなんぢの神はすべ治めたまふといふものの足は山上にありていかに美しきかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'なんぢが斥候の聲きこゆ かれらはヱホバのシオンに歸り給ふを目と目とあひあはせて視るが故にみな聲をあげてもろともにうたへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'ヱルサレムの荒廢れたるところよ聲をはなちて共にうたふべし ヱホバその民をなぐさめヱルサレムを贖ひたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'ヱホバそのきよき手をもろもろの國人の目のまへにあらはしたまへり 地のもろもろの極までもわれらの神のすくひを見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'なんぢら去よされよ 彼處をいでて汚れたるものに觸るなかれ その中をいでよ ヱホバの器をになふ者よ なんぢら潔くあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'なんぢら急ぎいづるにあらず趨りゆくにあらず ヱホバはなんぢらの前にゆきイスラエルの神はなんぢらの軍後となり給ふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, '視よわがしもべ智慧をもておこなはん 上りのぼりて甚だたかくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, '曩にはおほくの人かれを見ておどろきたり(その面貌はそこなはれて人と異なりその形容はおとろへて人の子とことなれり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, '後には彼おほく國民にそそがん 王たち彼によりて口を緘まん そはかれら未だつたへられざることを見いまだ聞ざることを悟るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'われらが宣るところを信ぜしものは誰ぞや ヱホバの手はたれにあらはれしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'かれは主のまへに芽えのごとく 燥きたる土よりいづる樹株のごとくそだちたり われらが見るべきうるはしき容なく うつくしき貌はなく われらがしたふべき艶色なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'かれは侮られて人にすてられ 悲哀の人にして病患をしれり また面をおほひて避ることをせらるる者のごとく侮られたり われらも彼をたふとまざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'まことに彼はわれらの病患をおひ我儕のかなしみを擔へり 然るにわれら思へらく彼はせめられ神にうたれ苦しめらるるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, '彼はわれらの愆のために傷けられ われらの不義のために碎かれ みづから懲罰をうけてわれらに平安をあたふ そのうたれし痍によりてわれらは癒されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'われらはみな羊のごとく迷ひておのおの己が道にむかひゆけり 然るにヱホバはわれら凡てのものの不義をかれのうへに置たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, '彼はくるしめらるれどもみづから謙だりて口をひらかず 屠場にひかるる羔羊の如く毛をきる者のまへにもだす羊の如くしてその口をひらかざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'かれは虐待と審判とによりて取去れたり その代の人のうち誰か彼が活るものの地より絶れしことを思ひたりしや 彼はわが民のとがの爲にうたれしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'その墓はあしき者とともに設けられたれど 死るときは富るものとともになれり かれは暴をおこなはずその口には虚僞なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'されどヱホバはかれを碎くことをよろこびて之をなやましたまへり 斯てかれの靈魂とがの献物をなすにいたらば彼その末をみるを得その日は永からん かつヱホバの悦び給ふことは彼の手によりて榮ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'かれは己がたましひの煩勞をみて心たらはん わが義しき僕はその知識によりておほくの人を義とし又かれらの不義をおはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'このゆゑに我かれをして大なるものとともに物をわかち取しめん かれは強きものとともに掠物をわかちとるべし 彼はおのが靈魂をかたぶけて死にいたらしめ愆あるものとともに數へられたればなり 彼はおほくの人の罪をおひ愆あるものの爲にとりなしをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'なんぢ孕まず子をうまざるものよ歌うたふべし 產のくるしみなきものよ聲をはなちて謳ひよばはれ 夫なきものの子はとつげるものの子よりおほしと 此はヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, '汝が幕屋のうちを廣くし なんぢが住居のまくをはりひろげて吝むなかれ 汝の綱をながくしなんぢの杙をかたくせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'そはなんぢが右に左にひろごり なんぢの裔はもろもろの國をえ 荒廢れたる邑をもすむべき所となさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, '懼るるなかれなんぢ恥ることなからん 惶てためくことなかれ汝はぢしめらるることなからん 若きときの恥をわすれ寡婦たりしときの恥辱をふたたび覺ることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'なんぢを造り給へる者はなんぢの夫なり その名は萬軍のヱホバ なんぢを贖ひ給ふものはイスラエルの聖者なり 全世界の神ととなへられ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'ヱホバ汝をまねきたまふ 棄られて心うれふる妻また若きとき嫁てさられたる妻をまねくがごとしと 此はなんぢの神のみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, '我しばし汝をすてたれど大なる憐憫をもて汝をあつめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'わが忿恚あふれて暫くわが面をなんぢに隱したれど 永遠のめぐみをもて汝をあはれまんと 此はなんぢをあがなひ給ふヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'このこと我にはノアの洪水のときのごとし 我むかしノアの洪水をふたたび地にあふれ流るることなからしめんと誓ひしが そのごとく我ふたたび汝をいきどほらず 再びなんぢを責じとちかひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, '山はうつり岡はうごくとも わが仁慈はなんぢよりうつらず 平安をあたふるわが契約はうごくことなからんと 此はなんぢを憐みたまふヱホバのみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'なんぢ苦しみをうけ暴風にひるがへされ 安慰をえざるものよ 我うるはしき彩色をなしてなんぢの石をすゑ 靑き玉をもてなんぢの基をおき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'くれなゐの玉をもてなんぢの櫓をつくり むらさきの玉をもてなんぢの門をつくり なんぢの境内はあまねく寳石にてつくるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, '又なんぢの子輩はみなヱホバに敎をうけ なんぢの子輩のやすきは大ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'なんぢ義をもて堅くたち 虐待よりとほざかりて慴ることなく また恐懼よりとほざかるべし そは恐懼なんぢに近づくことなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, '縦ひかれら群集ふとも我によるにあらず 凡てむれつどひて汝をせむる者はなんぢの故にたふるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'みよ炭火をふきおこして用ゐべき器をいだす鐵工はわが創造するところ 又あらし滅ぼす者もわが創造するところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'すべてなんぢを攻んとてつくられしうつはものは利あることなし 興起ちてなんぢとあらそひ訴ふる舌はなんぢに罪せらるべし これヱホバの僕等のうくる產業なり 是かれらが我よりうくる義なりとヱホバのたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, '噫なんぢら渇ける者ことごとく水にきたれ 金なき者もきたるべし 汝等きたりてかひ求めてくらへ きたれ金なく價なくして葡萄酒と乳とをかへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'なにゆゑ糧にもあらぬ者のために金をいだし 飽ことを得ざるもののために勞するや われに聽從へ さらばなんぢら美物をくらふをえ脂をもてその靈魂をたのしまするを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, '耳をかたぶけ我にきたりてきけ 汝等のたましひは活べし われ亦なんぢらととこしへの契約をなしてダビデに約せし變らざる惠をあたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, '視よわれ彼をたててもろもろの民の證とし又もろもろの民の君となし命令する者となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'なんぢは知ざる國民をまねかん 汝をしらざる國民はなんぢのもとに走りきたらん 此はなんぢの神ヱホバ、イスラエルの聖者のゆゑによりてなり ヱホバなんぢを尊くしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'なんぢら遇ことをうる間にヱホバを尋ねよ 近くゐたまふ間によびもとめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, '惡きものはその途をすて よこしまなる人はその思念をすててヱホバに反れ さらば憐憫をほどこしたまはん 我等の神にかへれ豐に赦をあたへ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'ヱホバ宣給くわが思はなんぢらの思とことなり わが道はなんぢらのみちと異なれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, '天の地よりたかきがごとく わが道はなんぢらの道よりも高く わが思はなんぢらの思よりもたかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, '天より雨くだり雪おちて復かへらず 地をうるほして物をはえしめ 萌をいださしめて播ものに種をあたへ 食ふものに糧をあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, '如此わが口よりいづる言もむなしくは我にかへらず わが喜ぶところを成し わが命じ遣りし事をはたさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'なんぢらは喜びて出きたり平穩にみちびかれゆくべし山と岡とは聲をはなちて前にうたひ野にある樹はみな手をうたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, '松樹はいばらにかはりてはえ岡拈樹は棘にかはりてはゆべし 此はヱホバの頌美となり並とこしへの徴となりて絶ることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'ヱホバ如此いひ給ふ なんぢら公平をまもり正義をおこなふべし わが救のきたるはちかく わが義のあらはるるは近ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, '安息日をまもりて汚さず その手をおさへて惡きことをなさず 斯おこなふ人かく堅くまもる人の子はさいはひなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'ヱホバにつらなれる異邦人はいふなかれ ヱホバ必ず我をその民より分ち給はんと 寺人もまたいふなかれ われは枯たる樹なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'ヱホバ如此いひたまふ わが安息日をまもり わが悦ぶことをえらみて我が契約を堅くまもる寺人には');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, '我わが家のうちにてわが垣のうちにて子にも女にもまさる記念のしるしと名とをあたへ 並とこしへの名をたまふて絶ることなからしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'またヱホバにつらなりこれに事へ ヱホバの名を愛しその僕となり 安息日をまもりて汚すことなく凡てわが契約をかたくまもる異邦人は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, '我これをわが聖山にきたらせ わが祈の家のうちにて樂ましめん かれらの燔祭と犠牲とはわが祭壇のうへに納めらるべし わが家はすべての民のいのりの家ととなへらるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'イスラエルの放逐れたるものを集めたまふ主ヱホバのたまはく 我さらに人をあつめて旣にあつめられたる者にくはへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, '野獸よみなきたりてくらへ 林にをるけものよ皆きたりてくらへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, '斥候はみな瞽者にしてしることなし みな唖なる犬にして吠ることあたはず みな夢みるもの臥ゐるもの眠ることをこのむ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'この犬はむさぼること甚だしくして飽ことをしらず かれらは悟ることを得ざる牧者にして皆おのが道にむかひゆき 何れにをる者もおのおの己の利をおもふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'かれら互にいふ請われ酒をたづさへきたらん われら濃酒にのみあかん かくて明日もなほ今日のごとく大にみち足はせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, '義者ほろぶれども心にとむる人なく 愛しみ深き人々とりさらるれども義きものの禍害のまへより取去るるなるを悟るものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'かれは平安にいり 直きをおこなふ者はその寐床にやすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'なんぢら巫女の子 淫人また妓女の裔よ 近ききたれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'なんぢら誰にむかひて戯れをなすや 誰にむかひて口をひらき舌をのばすや なんぢらは悖逆の子輩いつはりの黨類にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'なんぢらは橿樹のあひだ緑りなる木々のしたに心をこがし 谷のなか岩の狹間に子をころせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'なんぢは谷のなかの滑かなる石をうくべき嗣業とし これをなんぢが所有とす なんぢ亦これに灌祭をなし之にそなへものを献げたり われ之によりていかで心をなだむべしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'なんぢは高くそびえたる山の上になんぢの床をまうけ かつ其處にのぼりゆきて犠牲をささげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'また戸および柱のうしろに汝の記念をおけり なんぢ我をはなれて他人に身をあらはし 登りゆきてその床をひろくし かれらと誓をなし 又かれらの床を愛し これがためにその所をえらびたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'なんぢ香膏とおほくの薫物とをたづさへて王にゆき 又なんぢの使者をとほきにつかはし陰府にまで己をひくくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'なんぢ途のながきに疲れたれどなほ望なしといはず なんぢ力をいきかへされしによりて衰弱ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'なんぢ誰をおそれ誰のゆゑに慴きていつはりをいひ 我をおもはず亦そのことを心におかざりしや われ久しく默したれど汝かへりて我をおそれざりしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, '我なんぢの義をつげしめさん なんぢの作はなんぢに益せじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'なんぢ呼るときその集めおきたるもの汝をすくへ 風はかれらを悉くあげさり 息はかれらを吹さらん 然どわれに依賴むものは地をつぎわが聖山をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'また人いはん 土をもり土をもりて途をそなへよ わが民のみちより躓礙をとりされと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, '至高く至上なる永遠にすめるもの聖者となづくるもの如此いひ給ふ 我はたかき所きよき所にすみ 亦こころ碎けてへりくだる者とともにすみ 謙だるものの靈をいかし碎けたるものの心をいかす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'われ限なくは爭はじ我たえずは怒らじ 然らずば人のこころ我がまへにおとろへん わが造りたる靈はみな然らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, '彼のむさぼりの罪により我いかりて之をうちまた面をおほひて怒りたり 然るになほ悖りて己がこころの途にゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'されど我その途をみたり 我かれを愈すべし 又かれを導きてふたたび安慰をかれとその中のかなしめる者とにかへすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, '我くちびるの果をつくれり 遠きものにも近きものにも平安あれ平安あれ 我かれをいやさん 此はヱホバのみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, '然はあれど惡者はなみだつ海のごとし 靜かなること能はずしてその水つねに濁と泥とをいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'わが神いひたまはく惡きものには平安あることなしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, '大によばはりて聲ををしむなかれ 汝のこゑをラッパのごとくあげ わが民にその愆をつげヤコブの家にその罪をつげしめせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'かれらは日々われを尋求めわが途をしらんことをこのむ 義をおこなひ神の法をすてざる國のごとく義しき法をわれにもとめ神と相近づくことをこのめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'かれらはいふ われら斷食するになんぢ見たまはず われら心をくるしむるになんぢ知たまはざるは何ぞやと 視よなんぢらの斷食の日にはおのがこのむ作をなし その工人をことごとく惱めつかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, '視よなんぢら斷食するときは相あらそひ相きそひ惡の拳をもて人をうつ なんぢらの今のだんじきはその聲をうへに聞えしめんとにあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, '斯のごとき斷食はわが悦ぶところのものならんや かくのごときは人その靈魂をなやますの日ならんや その首を葦のごとくにふし麁服と灰とをその下にしくをもて斷食の日またヱホバに納らるる日ととなふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'わが悦ぶところの斷食はあくの繩をほどき 軛のつなをとき虐げらるるものを放ちさらしめ すべての軛ををるなどの事にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'また饑たる者になんぢのパンを分ちあたへ さすらへる貧民をなんぢの家にいれ裸かなるものを見てこれに衣せ おのが骨肉に身をかくさざるなどの事にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'しかる時はなんぢのひかり暁の如くにあらはれいで 汝すみやかに愈さるることを得 なんぢの義はなんぢの前にゆき ヱホバの榮光はなんぢの軍後となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'また汝よぶときはヱホバ答へたまはん なんぢ叫ぶときは我ここに在りといひ給はん/もし汝のなかより軛をのぞき指點をのぞき惡きことをかたるを除き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'なんぢの靈魂の欲するものをも饑たる者にほどこし 苦しむものの心を滿足しめば なんぢの光くらきにてりいで なんぢの闇は晝のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'ヱホバは常になんぢをみちびき 乾けるところにても汝のこころを滿足しめ なんぢの骨をかたうし給はん なんぢは潤ひたる園のごとく水のたえざる泉のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, '汝よりいづる者はひさしく荒廢れたる所をおこし なんぢは累代やぶれたる基をたてん 人なんぢをよびて破隙をおぎなふ者といひ 市街をつくろひてすむべき所となす者といふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'もし安息日になんぢの歩行をとどめ 我聖日になんぢの好むわざをおこなはず 安息日をとなへて樂日となし ヱホバの聖日をとなへて尊むべき日となし 之をたふとみて己が道をおこなはず おのが好むわざをなさず おのが言をかたらずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'その時なんぢヱホバを樂しむべし ヱホバなんぢを地のたかき處にのらしめ なんぢが先祖ヤコブの產業をもて汝をやしなひ給はん こはヱホバ口より語りたまへるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'ヱホバの手はみぢかくして救ひえざるにあらず その耳はにぶくして聞えざるにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, '惟なんぢらの邪曲なる業なんぢらとなんぢらの神との間をへだてたり 又なんぢらの罪その面をおほひて聞えざらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'そはなんぢらの手は血にてけがれ なんぢらの指はよこしまにて汚れ なんぢらのくちびるは虚僞をかたり なんぢらの舌は惡をささやき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'その一人だに正義をもてうつたへ眞實をもて論らふものなし 彼らは虚浮をたのみ虚僞をかたり 惡しきくはだてをはらみ不義をうむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'かれらは蝮の卵をかへし蛛網をおる その卵をくらふものは死るなり 卵もし踐るればやぶれて毒蛇をいだす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'その織るところは衣になすあたはず その工をもて身をおほふこと能はず かれらの工はよこしまの工なり かれらの手には暴虐のおこなひあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'かれらの足はあくにはしり罪なき血をながすに速し かれらの思念はよこしまの思念なり 殘害と滅亡とその路徑にのこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, '彼らは平穩なる道をしらず その過るところに公平なく又まがれる小徑をつくる 凡てこれを踐ものは平穩をしらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'このゆゑに公平はとほくわれらをはなれ正義はわれらに追及ず われら光をのぞめど暗をみ 光輝をのぞめど闇をゆく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'われらは瞽者のごとく牆をさぐりゆき目なき者のごとく模りゆき正午にても日暮のごとくにつまづき 強壯なる者のなかにありても死るもののごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, '我儕はみな熊のごとくにほえ鴿のごとくに甚くうめき 審判をのぞめどもあることなく 救をのぞめども遠くわれらを離る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'われらの愆はなんぢの前におほく われらのつみは證してわれらを訟へ われらのとがは我らとともに在り われらの邪曲なる業はわれら自らしれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'われら罪ををかしてヱホバを棄われらの神にはなれてしたがはず 暴虐と悖逆とをかたり虚僞のことばを心にはらみて説出すなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, '公平はうしろに退けられ正義ははるかに立り そは 眞實は衢間にたふれ 正直はいることを得ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, '眞實はかけてなく惡をはなるるものは掠めうばはる/ヱホバこれを見てその公平のなかりしを悦びたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'ヱホバは人なきをみ中保なきを奇しみたまへり 斯てその臂をもてみづから助け その義をもてみづから支たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'ヱホバ義をまとひて護胸とし救をその頭にいただきて兜となし 仇をまとひて衣となし 熱心をきて外服となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'かれらの作にしたがひて報をなし敵にむかひていかり仇にむかひて報をなし また島々にむくいをなし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, '西方にてヱホバの名をおそれ 日のいづる所にてその榮光をおそるべし ヱホバは堰ぎとめたる河のその氣息にふき潰えたるがごとくに來りたまふ可ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'ヱホバのたまはく贖者シオンにきたりヤコブのなかの愆をはなるる者につかんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'ヱホバいひ給く なんぢの上にあるわが靈なんぢの口におきたるわがことばは 今よりのち永遠になんぢの口よりなんぢの裔の口より汝のすゑの裔の口よりはなれざるべし わがかれらにたつる契約はこれなりと此はヱホバのみことばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, '起よひかりを發て なんぢの光きたりヱホバの榮光なんぢのうへに照出たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, '視よくらきは地をおほひ闇はもろもろの民をおほはん されど汝の上にはヱホバ照出たまひてその榮光なんぢのうへに顯はるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'もろもろの國はなんぢの光にゆき もろもろの王はてり出るなんぢが光輝にゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'なんぢの目をあげて環視せ かれらは皆つどひて汝にきたり 汝の子輩はとほきより來り なんぢの女輩はいだかれて來らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'そのときなんぢ視てよろこびの光をあらはし なんぢの心おどろきあやしみ且ひろらかになるべし そは海の富はうつりて汝につき もろもろの國の貨財はなんぢに來るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'おほくの駱駝ミデアンおよびエバのわかき駱駝なんぢの中にあまねくみち シバのもろもろの人こがね乳香をたづさへきたりてヱホバの譽をのべつたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'ケダルのひつじの群はみな汝にあつまりきたり ネバヨテの牡羊はなんぢに事へ わが祭壇のうへにのぼりて受納られん 斯てわれわが榮光の家をかがやかすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, '雲のごとくにとび鳩のその窠にとびかへるが如くしてきたる者はたれぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'もろもろの島はわれを俟望み タルシシのふねは首先になんぢの子輩をとほきより載きたり 並かれらの金銀をともにのせきたりてなんぢの神ヱホバの名にささげ イスラエルの聖者にささげん ヱホバなんぢを輝かせたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, '異邦人はなんぢの石垣をきづき かれらの王等はなんぢに事へん そは我いかりて汝をうちしかどまた惠をもて汝を憐みたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'なんぢの門はつねに開きて夜も日もとざすことなし こは人もろもろの國の貨財をなんぢに携へきたり その王等をひきゐ來らんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'なんぢに事へざる國と民とはほろび そのくにぐには全くあれすたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'レバノンの榮はなんぢにきたり 松 杉 黄楊はみな共にきたりて我が聖所をかがやかさん われ亦わが足をおく所をたふとくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, '汝を苦しめたるものの子輩はかがみて汝にきたり 汝をさげしめたる者はことごとくなんぢの足下にふし 斯て汝をヱホバの都イスラエルの聖者のシオンととなへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'なんぢ前にはすてられ憎まれてその中をすぐる者もなかりしが 今はわれ汝をとこしへの華美よよの歡喜となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'なんぢ亦もろもろの國の乳をすひ王たちの乳房をすひ 而して我ヱホバなんぢの救主なんぢの贖主ヤコブの全能者なるを知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'われ黄金をたづさへきたりて赤銅にかへ 白銀をたづさへきたりて鐵にかへ 赤銅を木にかへ鐵を石にかへ なんぢの施政者をおだやかにし なんぢを役するものを義うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, '強暴のこと再びなんぢの地にきこえず 殘害と敗壞とはふたたびなんぢの境にきこえず 汝その石垣をすくひととなへ その門を譽ととなへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, '晝は日ふたたびなんぢの光とならず 月もまた輝きてなんぢを照さず ヱホバ永遠になんぢの光となり なんぢの神はなんぢの榮となり給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'なんぢの日はふたたび落ず なんぢの月はかくることなかるべし そはヱホバ永遠になんぢの光となり 汝のかなしみの日畢るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, '汝の民はことごとく義者となりてとこしへに地を嗣ん かれはわが植たる樹株わが手の工わが榮光をあらはす者となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'その小きものは千となり その弱きものは強國となるべし われヱホバその時いたらば速かにこの事をなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, '主ヱホバの靈われに臨めり こはヱホバわれに膏をそそぎて貧きものに福音をのべ傳ふることをゆだね 我をつかはして心の傷める者をいやし俘囚にゆるしをつげ 縛められたるものに解放をつげ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'ヱホバのめぐみの年とわれらの神の刑罰の日とを告しめ 又すべて哀むものをなぐさめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, '灰にかへ冠をたまひてシオンの中のかなしむ者にあたへ 悲哀にかへて歡喜のあぶらを予へ うれひの心にかへて讃美の衣をかたへしめたまふなり かれらは義の樹 ヱホバの植たまふ者 その榮光をあらはす者ととなへられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, '彼等はひさしく荒たる處をつくろひ 上古より廢れたる處をおこし 荒たる邑々をかされて新にし世々すたれたる處をふたたび建べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, '外人はたちてなんぢらの群をかひ 異邦人はなんぢらの畑をたがへす者となり 葡萄をつくる者とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, '然どなんぢらはヱホバの祭司ととなへられ われらの神の役者とよばれ もろもろの國の富をくらひ かれらの榮をえて自らほこるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, '曩にうけし恥にかへ倍して賞賜をうけ凌辱にかへ嗣業をえて樂むべし 而してその地にありて倍したる賞賜をたもち永遠によろこびを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'われヱホバは公平をこのみ邪曲なるかすめごとをにくみ 眞實をもて彼等にむくいをあたへ 彼等ととこしへの契約をたつべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'かれらの裔はもろもろの國のなかに知れ かれらの子輩はもろもろの民のなかに知れん すべてこれを見るものはそのヱホバの祝したまへる裔なるを辨ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'われヱホバを大によろこび わが靈魂はわが神をたのしまん そは我にすくひの衣をきせ義の外服をまとはせて 新郎が冠をいただき新婦が玉こがねの飾をつくるが如くなしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, '地は芽をいだし畑はまけるものを生ずるがごとく 主ヱホバは義と譽とをもろもろの國のまへに生ぜしめ給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'われシオンの義あさ日の光輝のごとくにいで ヱルサレムの救もゆる松火のごとくになるまではシオンのために默さずヱルサレムのために休まざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'もろもろの國はなんぢの義を見 もろもろの王はみななんぢの榮をみん 斯てなんぢはヱホバの口にて定め給ふ新しき名をもて稱へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'また汝はうるはしき冠のごとくヱホバの手にあり 王の冕のごとくなんぢの神のたなごころにあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, '人ふたたび汝をすてられたる者といはず 再びなんぢの地をあれたる者といはじ 却てなんぢをヘフジバ(わが悦ぶところ)ととなへ なんぢの地をベウラ(配偶)ととなふべし そはヱホバなんぢをよろこびたまふ なんぢの地は配偶をえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'わかきものの處女をめとる如くなんぢの子輩はなんぢを娶らん 新郎の新婦をよろこぶごとくなんぢの神なんぢを喜びたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'ヱルサレムよ我なんぢの石垣のうへに斥候をおきて終日終夜たえず默すことなからしむ なんぢらヱホバに記念したまはんことを求むるものよ 自らやすむなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'ヱホバ、ヱルサレムをたてて全地に譽をえしめ給ふまでは息め奉るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'ヱホバその右手をさしその大能の臂をさし誓ひて宣給く われ再びなんぢの五穀をなんぢの敵にあたへて食はせず 異邦人はなんぢが勞したる酒をのまざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, '収穫せしものは之をくらひてヱホバを讃たたへ 葡萄をあつめし者はわが聖所の庭にて之をのむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, '門よりすすみゆけ進みゆけ 民の途をそなへ土をもり土をもりて大路をまうけよ 石をとりのぞけ もろもろの民に旗をあげて示せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'ヱホバ地の極にまで告てのたまはく 汝等シオンの女にいへ 視よなんぢらの救きたる 視よ主の手にその恩賜あり はたらきの價はその前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, '而してかれらはきよき民またヱホバにあがなはれたる者ととなへられん なんぢは人にもとめ尋らるるもの棄られざる邑ととなへらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'このエドムよりきたり緋衣をきてボヅラよりきたる者はたれぞ その服飾はなやかに大なる能力をもて嚴しく歩みきたる者はたれぞ これは義をもてかたり大にすくひをほどこす我なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'なんぢの服飾はなにゆゑに赤くなんぢの衣はなにゆゑに酒榨をふむ者とひとしきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '我はひとりにて酒榨をふめり もろもろの民のなかに我とともにする者なし われ怒によりて彼等をふみ忿恚によりてかれらを蹈にじりたれば かれらの血わが衣にそそぎわが服飾をことごとく汚したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'そは刑罰の日わが心の中にあり 救贖の歳すでにきたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'われ見てたすくる者なく扶る者なきを奇しめり この故にわが臂われをすくひ我いきどほり我をささへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'われ怒によりてもろもろの民をふみおさへ 忿恚によりてかれらを酔しめ かれらの血を地に流れしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'われはヱホバのわれらに施したまへる各種のめぐみとその譽とをかたりつげ 又その憐憫にしたがひ其おほくの恩惠にしたがひてイスラエルの家にほどこし給ひたる大なる恩寵をかたり告ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'ヱホバいひたまへり 誠にかれらはわが民なり 虚僞をせざる子輩なりと 斯てヱホバはかれらのために救主となりたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'かれらの艱難のときはヱホバもなやみ給ひてその面前の使をもて彼等をすくひ その愛とその憐憫とによりて彼等をあがなひ彼等をもたげ昔時の日つねに彼等をいだきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, '然るにかれらは悖りてその聖靈をうれへしめたる故にヱホバ翻然かれらの仇となりて自らこれを攻たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, '爰にその民いにしへのモーセの日をおもひいでて曰けるは かれらとその群の牧者とを海より携へあげし者はいづこにありや 彼等のなかに聖靈をおきしものは何處にありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, '榮光のかひなをモーセの右にゆかしめ 彼等のまへに水をさきて自らとこしへの名をつくり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, '彼等をみちびきて馬の野をはしるがごとく躓かで淵をすぎしめたりし者はいづこに在りや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, '谷にくだる家畜の如くにヱホバの靈かれらをいこはせ給へり 主よなんぢは斯おのれの民をみちびきて榮光の名をつくり給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'ねがはくは天より俯觀なはし その榮光あるきよき居所より見たまへ なんぢの熱心となんぢの大能あるみわざとは今いづこにありや なんぢの切なる仁慈と憐憫とはおさへられて我にあらはれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, '汝はわれらの父なり アブラハムわれらを知ず イスラエルわれらを認めず されどヱホバよ汝はわれらの父なり 上古よりなんぢの名をわれらの贖主といへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'ヱホバよ何故にわれらをなんぢの道より離れまどはしめ我儕のこころを頑固にして汝を畏れざらしめたまふや 願くはなんぢの僕等のためになんぢの產業なる支派のために歸りたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, '汝のきよきたみ地をえて久しからざるにわれらの敵なんぢの聖所をふみにじれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, '我儕はなんぢに上古より治められざる者のごとく なんぢの名をもて稱られざる者のごとくなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, '願くはなんぢ天を裂てくだり給へ なんぢのみまへに山々ふるひ動かんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, '火の柴をもやし火の水を沸すがごとくして降りたまへ かくて名をなんぢの敵にあらはし もろもろの國をなんぢのみまへに戰慄かしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, '汝われらが逆料あたはざる懼るべき事をおこなひ給ひしときに降りたまへり 山々はその前にふるひうごけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, '上古よりこのかた汝のほかに何なる神ありて俟望みたる者にかかる事をおこなひしや いまだ聽ず いまだ耳にいらず いまだ目にみしことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, '汝はよろこびて義をおこなひなんぢの途にありてなんぢを紀念するものを迎へたまふ 視よなんぢ怒りたまへり われらは罪ををかせり かかる狀なること旣にひさし 我儕いかで救はるるを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, '我儕はみな潔からざる物のごとくなり われらの義はことごとく汚れたる衣のごとし 我儕はみな木葉のごとく枯れ われらのよこしまは暴風のごとく我らを吹去れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'なんぢの名をよぶ者なく みづから勵みて汝によりすがる者なし なんぢ面をおほひてわれらを顧みたまはず われらが邪曲をもてわれらを消失せしめたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'されどヱホバよ汝はわれらの父なり われらは泥塊にしてなんぢは陶工なり 我らは皆なんぢの御手のわざなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'ヱホバよいたく怒りたまふなかれ 永くよこしまを記念したまふなかれ 願くは顧みたまへ 我儕はみななんぢの民なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, '汝のきよき諸邑は野となりシオンは野となりヱルサレムは荒廢れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, '我らの先祖が汝を讃たたへたる榮光ある我儕のきよき宮は火にやかれ 我儕のしたひたる處はことごとく荒はてたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'ヱホバよこれらの事あれども汝なほみづから制へたまふや なんぢなほ默してわれらに深くくるしみを受しめたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, '我はわれを求めざりしものに問もとめられ 我をたづねざりしものに見出され わが名をよばざりし國にわれ曰らく われは此にあり我はここに在と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, '善らぬ途をあゆみおのが思念にしたがふ悖れる民をひねもす手をのべて招けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'この民はまのあたり恒にわが怒をひき 園のうちにて犠牲をささげ 瓦の壇にて香をたき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, '墓のあひだにすわり隱密なる處にやどり 猪の肉をくらひ憎むべきものの羹をその器皿にもりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, '人にいふなんぢ其處にたちて我にちかづくなかれ そは我なんぢよりも聖しと 彼らはわが鼻のけぶり終日もゆる火なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, '視よこの事わが前にしるされたり われ默さずして報いかへすべし 必ずかれらの懷中に報いかへすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'ヱホバいひ給く なんぢらの邪曲となんぢらが列祖のよこしまとはともに報いかへすべし かれらは山上にて香をたき岡のうへにて我を汚ししがゆゑに 我まづその作をはかりてその懷中にかへすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'ヱホバ如此いひたまふ 人ぶだうのなかに汁あるを見ばいはん これを壞るなかれ福祉その中にあればなりと 我わが僕等のために如此おこなひてことごとくは壞らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'ヤコブより一裔をいだしユダよりわれ山々をうけつぐべき者をいださん わが撰みたる者はこれをうけつぎ我がしもべらは彼處にすむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'シヤロンは羊のむれの牧場となりアコルの谷はうしの群のふす所となりて我をたづねもとめたるわが民の有とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, '然どなんぢらヱホバを棄わがきよき山をわすれ 机をガド(禍福の神)にそなへ雜合せたる酒をもりてメニ(運命の神)にささぐる者よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'われ汝らを劍にわたすべく定めたり なんぢらは皆かがみて屠らるべし 汝等はわが呼しときこたへず わが語りしとききかず わが目にあしき事をおこなひ わが好まざりし事をえらみたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'このゆゑに主ヱホバかく言給ふ わが僕等はくらへども汝等はうゑ わが僕等はのめども汝等はかわき 我しもべらは喜べどもなんぢらははぢ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'わが僕等はこころ樂きによりて歌うたへども汝等はこころ哀きによりて叫び また靈魂うれふるによりて泣嗁ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'なんぢらが遺名はわが撰みたるものの呪詛の料とならん 主ヱホバなんぢらを殺したまはん 然どおのれの僕等をほかの名をもて呼たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, '斯るがゆゑに地にありて己のために福祉をねがふものは眞實の神にむかひて福祉をもとめ 地にありて誓ふものは眞實の神をさして誓ふべし さきの困難は忘れられてわが目よりかくれ失たるに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, '視よわれ新しき天とあたらしき地とを創造す 人さきのものを記念することなく之をその心におもひ出ることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, '然どなんぢらわが創造する者によりて永遠にたのしみよろこべ 視よわれはヱルサレムを造りてよろこびとしその民を快樂とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'われヱルサレムを喜びわが民をたのしまん 而して泣聲とさけぶ聲とはふたたびその中にきこえざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, '日數わづかにして死る嬰兒といのちの日をみたさざる老人とはその中にまたあることなかるべし 百歳にて死るものも尚わかしとせられ 百歳にて死るものを詛れたる罪人とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'かれら家をたてて之にすみ葡萄園をつくりてその果をくらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'かれらが建るところにほかの人すまず かれらが造るところの果はほかの人くらはず そはわが民のいのちは樹の命の如く 我がえらみたる者はその手の工ふるびうするとも存ふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'かれらの勤勞はむなしからず その生ところの者はわざはひにかからず 彼等はヱホバの福祉をたまひしものの裔にしてその子輩もあひ共にをる可ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'かれらが呼ざるさきにわれこたへ 彼らが語りをへざるに我きかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, '豺狼とこひつじと食物をともにし 獅は牛のごとく藁をくらひ 蛇はちりを糧とすべし 斯てわが聖山のいづこにても害ふことなく傷ることなからん これヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'ヱホバ如此いひたまふ 天はわが位地はわが足臺なり なんぢら我がために如何なる家をたてんとするか 又いかなる處かわが休憩の場とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'ヱホバ宣給く 我手はあらゆる此等のものを造りてこれらの物ことごとく成れり 我はただ苦しみまた心をいため我がことばを畏れをののくものを顧みるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, '牛をほふるものは人をころす者のごとく 羔を犠牲とするものは狗をくびりころす者のごとく 祭物をささぐるものは豕の血をささぐる者のごとく 香をたくものは偶像をほむる者のごとし 彼等はおのが途をえらみその心ににくむべき者をたのしみとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, '我もまた災禍をえらびて彼等にあたへ その懼るるところの事を彼らに臨ましめん そは我よびしとき應ふるものなく我かたりしとき聽ことをせざりき わが目にあしき事をおこなひわが好まざる事をえらみたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'なんぢらヱホバの言をおそれをののく者よヱホバの言をきけ なんぢらの兄弟なんぢらを憎みなんぢらをわが名のために逐出していふ 願くはヱホバその榮光をあらはして我儕になんぢらの歡喜を見せしめよと 然どかれらは恥をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, '騒亂るこゑ邑よりきこえ聲ありて宮よりきこゆ 此はヱホバその仇にむくいをなしたまふ聲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'シオンは產のなやみを知ざるさきに生 その劬勞きたらざるさきに男子をうみいだせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, '誰がかかる事をききしや誰がかかる類をみしや 一の國はただ一日のくるしみにて成べけんや 一つの國民は一時にうまるべけんや 然どシオンはくるしむ間もなく直にその子輩をうめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'ヱホバ言給く われ產にのぞましめしに何でうまざらしめんや なんぢの神いひたまはく 我はうましむる者なるにいかで胎をとざさんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'ヱルサレムを愛するものよ皆かれとともに喜べ かれの故をもてたのしめ 彼のために悲めるものよ皆かれとともに喜びたのしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'そはなんぢら乳をすふ如くヱルサレムの安慰をうけて飽ことを得ん また乳をしぼるごとくその豐なる榮をうけておのづから心さわやかならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'ヱホバ如此いひたまふ 視よわれ河のごとく彼に平康をあたへ 漲ぎる流のごとく彼にもろもろの國の榮をあたへん 而して汝等これをすひ背におはれ膝におかれて樂しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, '母のその子をなぐさむるごとく我もなんぢらを慰めん なんぢらはヱルサレムにて安慰をうべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'なんぢら見て心よろこばん なんぢらの骨は若草のさかゆるごとくだるべし ヱホバの手はその僕等にあらはれ又その仇をはげしく怒りたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, '視よヱホバは火中にあらはれて來りたまふその 車輦ははやちのごとし 烈しき威勢をもてその怒をもらし火のほのほをもてその譴をほどこし給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'ヱホバは火をもて劍をもてよろづの人を刑ひたまはん ヱホバに刺殺さるるもの多かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'ヱホバ宣給く みづからを潔くしみづからを別ちて園にゆき その中にある木の像にしたがひ 豕の肉けがれたる物および鼠をくらふ者はみな共にたえうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, '我かれらの作爲とかれらの思念とをしれり 時きたらばもろもろの國民ともろもろの族とをあつめん 彼等きたりてわが榮光をみるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, '我かれらのなかに一つの休徴をたてて逃れたる者をもろもろの國すなはちタルシシよく弓をひくブル、ルデおよびトバル、ヤワン又わが聲名をきかずわが榮光をみざる遙かなる諸島につかはさん 彼等はわが榮光をもろもろの國にのべつたふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'ヱホバいひ給ふ かれらはイスラエルの子輩がきよき器にそなへものをもりてヱホバの家にたづさへきたるが如く なんぢらの兄弟をもろもろの國の中よりたづさへて馬 車 轎 騾 駱駝にのらしめ わが聖山ヱルサレムにきたらせてヱホバの祭物とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'ヱホバいひ給ふ 我また彼等のうちより人をえらびて祭司としレビ人とせんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'ヱホバ宣給く わが造らんとする新しき天とあたらしき地とわが前にながくとどまる如く なんちの裔となんぢの名はながくとどまらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'ヱホバいひ給ふ新月ごとに安息日ごとによろづの人わが前にきたりて崇拜をなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'かれら出てわれに逆きたる人の屍をみん その蛆しなずその火きえず よろづの人にいみきらはるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'こはベニヤミンの地アナトテの祭司の一人なるヒルキヤの子ヱレミヤの言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'アモンの子ユダの王ヨシヤの時すなはちその治世の十三年にヱホバの言ヱレミヤに臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'その言またヨシヤの子ユダの王ヱホヤキムの時にものぞみてヨシヤの子ユダの王ゼデキヤの十一年のをはり即ちその年の五月ヱルサレムの民の移されたる時までにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'ヱホバの言我にのぞみて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'われ汝を腹につくらざりし先に汝をしり汝が胎をいでざりし先に汝を聖め汝をたてて萬國の預言者となせりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, '我こたへけるは噫主ヱホバよ視よわれは幼少により語ることを知らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'ヱホバわれにいひたまひけるは汝われは幼少といふ勿れすべて我汝を遣すところにゆき我汝に命ずるすべてのことを語るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'なんぢ彼等の面を畏るる勿れ蓋われ汝と偕にありて汝をすくふべければなりとヱホバいひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'ヱホバ遂にその手をのべて我口につけヱホバ我にいひたまひけるは視よわれ我言を汝の口にいれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'みよ我けふ汝を萬民のうへと萬國のうへにたて汝をして或は抜き或は毀ち或は滅し或は覆し或は建て或は植しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'ヱホバの言また我に臨みていふヱレミヤよ汝何をみるや我こたへけるは巴旦杏の枝をみる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'ヱホバ我にいひたまひけるは汝善く見たりそはわれ速に我言をなさんとすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'ヱホバの言ふたたび我に臨みていふ汝何をみるや我こたへけるは沸騰たる鑊をみるその面は北より此方に向ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'ヱホバ我にいひたまひけるは災北よりおこりてこの地に住るすべての者にきたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'ヱホバいひたまひけるはわれ北の國々のすべての族をよばん彼等きたりてヱルサレムの門の入口とその周圍のすべての石垣およびユダのすべての邑々に向ひておのおのその座を設けん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'われかれらの凡の惡事のために我鞫をかれにつげん是はかれら我をすてて別の神に香を焚きおのれの手にて作りし物を拝するによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, '汝腰に帶して起ちわが汝に命ずるすべての事を彼等につげよその面を畏るる勿れ否らざれば我かれらの前に汝を辱かしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, '視よわれ今日この全國とユダの王とその牧伯とその祭司とその地の民の前に汝を堅き城 鐵の柱 銅の牆となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, '彼等なんぢと戰はんとするも汝に勝ざるべしそはわれ汝とともにありて汝をすくふべければなりとヱホバいひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'ヱホバの言我にのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'ゆきてヱルサレムに住る者の耳につげよヱホバ斯くいふ我汝につきて汝の若き時の懇切なんぢが契をなせしときの愛曠野なる種播ぬ地にて我に從ひしことを憶ゆと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'イスラエルはヱホバの聖物にしてその初に結べる實なりすべて之を食ふものは罰せられ災にあふべしとヱホバ云ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'ヤコブの家とイスラエルの家の諸の族よヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'ヱホバかくいひたまふ汝等の先祖は我に何の惡事ありしを見て我に遠かり 虛しき物にしたがひて虛しくなりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'かれらは我儕をエジプトの地より導きいだし曠野なる岩穴ある荒たる地 旱きたる死の蔭の地 人の過ぎざる地 人の住はざる地を通らしめしヱホバはいづこにあるといはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'われ汝等を導きて園のごとき地にいれ其實と佳物をくらはしめたり然ど汝等此處にいり我地を汚し我產業を憎むべきものとなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, '祭司はヱホバは何處にいますといはず律法をあつかふ者は我を知らず牧者は我に背き預言者はバアルによりて預言し益なきものに從へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, '故にわれ尚汝等とあらそはん且汝の子孫とあらそふべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, '汝等キッテムの諸島にわたりて觀よまた使者をケダルにつかはし斯のごとき事あるや否やを詳細に察せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'その神を神にあらざる者に易たる國ありや然るに我民はその榮を益なき物にかへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, '天よこの事を驚け慄けいたく怖れよとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, '蓋わが民はふたつの惡事をなせり即ち活る水の源なる我をすて自己水溜を掘れりすなはち壞れたる水溜にして水を有たざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'イスラエルはしもべなるか家にうまれし僕なるかいかにして擄掠となれるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'わかき獅子かれにむかひて哮えその聲をあげてその地を荒せりその諸邑は焚れて住む人なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'ノフとタパネスの諸子も汝の頭首の髮をくらはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, '汝の神ヱホバの汝を途にみちびきたまへる時に汝これを棄たるによりて此事汝におよぶにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, '汝ナイルの水を飮んとてエジプトの路にあるは何ゆゑぞまた河の水を飮んとてアツスリヤの路にあるは何故ぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, '汝の惡は汝をこらしめ汝の背は汝をせめん斯く汝が汝の神ヱホバをすてたると我を畏るることの汝の衷にあらざるとは惡く且つ苦きことなるを汝見てしるべしと主なる萬軍のヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, '汝昔より汝の軛ををり汝の縛を截ちていひけるは我つかふることをせじと即ち汝すべての高山のうへと諸の靑木の下に妓女のごとく身をかがめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'われ汝を植て佳き葡萄の樹となし全き眞の種となせしにいかなれば汝われに向ひて異なる葡萄の樹の惡き枝にかはりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'たとひ嚥哘をもて自ら濯ひまたおほくの灰汁を加ふるも汝の惡はわが前に汚れたりと主ヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, '汝いかで我は汚れずバアルに從はざりしといふことを得んや汝谷の中のおこなひを觀よ汝のなせしことを知れ汝は疾走るわかき牝の駱駝にしてその途にさまよへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, '汝は曠野になれたる野の牝驢馬なり其欲のために風にあへぐその欲のうごくときは誰かこれをとどめえん凡てこれを尋る者は自ら勞するにおよばすその月の中に之にあふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, '汝足をつつしみて跣足にならざるやうにし喉をつつしみて渇かぬやうにせよしかるに汝いふ是は徒然なり然りわれ異なる國の者を愛してこれに從ふなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, '盜人の執へられて恥辱をうくるがごとくイスラエルの家恥辱をうく彼等その王その牧伯その祭司その預言者みな然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, '彼等木にむかひて汝は我父なりといひまた石にむかひて汝は我を生みたりといふ彼等は背を我にむけて其面をわれに向けずされど彼等災にあふときは起てわれらを救ひ給へといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, '汝がおのれの爲に造りし神はいづこにあるやもし汝が災にあふときかれら汝を救ふを得ば起つべきなりそはユダよ汝の神は汝の邑の數に同じければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, '汝等なんぞ我とあらそふや汝らは皆我に背けりとヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, '我が汝らの衆子を打しは益なかりき彼等は懲治をうけず汝等の劍は猛き獅子のごとく汝等の預言者を滅せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'なんぢらこの世の人よヱホバの言をきけ我はイスラエルのために曠野となりしや暗き地となりしや何故にわが民はわれら徘徊りて復汝に來らじといふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'それ處女はその飾物を忘れんや新婦はその帶をわすれんや然ど我民の我を忘れたる日は數へがたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, '汝愛を得んとて如何に汝の途を美くするぞよされば汝の行はあしき事を爲すに慣たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'また汝の裾に辜なき貧者の生命の血ありわれ盜人の穿たる所にて之を見ずしてすべて此等の上にこれを見る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'されど汝いふわれは辜なし故にその怒はかならず我に臨まじとみよ汝われ罪を犯さざりしといふにより我汝とあらそふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'なんぢ何故にその途を易んとて迅くはしるや汝アツスリヤに恥辱をうけしごとくエジプトにも亦恥辱をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, '汝兩手を頭に置てかしこよりも出去らんそはヱホバ汝のたのむところの者を棄れば汝彼等によりて望を遂ること無るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, '世にいへるあり人もしその妻をいださんに去りゆきてほかの人の妻とならば其夫ふたたび彼に歸るべけんやさすれば其地はおほいに汚れざらんや汝はおほくの者と姦淫を行へりされど汝われに皈れよとヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, '汝目をあげてもろもろの童山をみよ姦淫を行はざる所はいづこにあるや汝は曠野にをるアラビヤ人の爲すがごとく路に坐して人をまてり汝は姦淫と惡をもて此地を汚せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'この故に雨はとどめられ春の雨はふらざりし然れど汝娼妓の額あれば肯て恥ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, '汝いまより我を呼ていはざらんや我父よ汝はわが少時の交友なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, '窮なくその怒を含まんや恒に之を存たんやと視よ汝はかくいへど力をきはめて惡を爲すなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'ヨシヤ王のときヱホバまた我にいひ給ひけるは汝そむけるイスラエルのなせしことを見しや彼はすべての高山にのぼりすべての靑木の下にゆきて其處に姦淫を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, '彼このすべての事を爲せしのち我かれに汝われに歸れと言しかどもわれに歸らざりき其悖れる姊妹なるユダ之を見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, '我に背けるイスラエル姦淫をなせしにより我かれを出して離緣状をあたへたれどその悖れる姊妹なるユダは懼れずして往て姦淫を行ふ我これを見る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'また其姦淫の噪をもてこの地を汚し且石と木とに姦淫を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, '此諸の事あるも仍其悖れる姊妹なるユダは眞心をもて我にかへらず僞れるのみとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'ヱホバまた我にいひたまひけるは背けるイスラエルは悖れるユダよりも自己を義とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, '汝ゆきて北にむかひ此言を宣ていふべしヱホバいひたまふ背けるイスラエルよ歸れわれ怒の面を汝らにむけじわれは矜恤ある者なり怒を限なく含みをることあらじとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, '汝ただ汝の罪を認はせそは汝の神ヱホバにそむき經めぐりてすべての靑木の下にて異邦人にゆき汝等わが聲をきかざればなりとヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'ヱホバいひたまふ背ける衆子よ我にかへれそはわれ汝等を娶ればなりわれ邑より一人支派より二人を取りて汝等をシオンにつれゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'われ我心に合ふ牧者を汝等にあたへん彼等は知識と明哲をもて汝等を養ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'ヱホバいひたまふ汝等地に增して多くならんときは人々復ヱホバの契約の櫃といはず之を想ひいでず之を憶えずこれを尋ねずこれを作らざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'その時ヱルサレムはヱホバの座位と稱へられ萬國の民ここに集るべし即ちヱホバの名によりてヱルサレムに集り重て其惡き心の剛愎なるにしたがひて行まざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'その時ユダの家はイスラエルの家とともに行みて北の地よりいで我汝らの先祖たちに與へて嗣しめし地に偕にきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, '我いへり嗚呼われいかにして汝を諸子の中に置き萬國の中にて最も美しき產業なる此美地を汝にあたへんと我またいへり汝われを我父とよび亦我を離れざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, '然にイスラエルの家よ妻の誓に違きてその夫を棄るがごとく汝等われに背けりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, '聲山のうへに聞ゆ是はイスラエルの民の悲み祈るなり蓋彼等まがれる途にあゆみ其神ヱホバを忘るればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, '背ける諸子よ我に歸れわれ汝の退違をいやさん/視よ我儕なんぢに到る汝はわれらの神ヱホバなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, '信に諸の岡とおほくの山に救を望むはいたづらなり誠にイスラエルの救はわれらの神ヱホバにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, '羞恥はわれらの幼時より我儕の先祖の產業すなはち其多の羊とそのおほくの牛および其子その女を呑盡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'われらは羞恥に臥し我らは恥辱に覆はるべしそは我儕とわれらの列祖は我らの幼時より今日にいたるまで罪をわれらの神ヱホバに犯し我儕の神ヱホバの聲に遵はざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'ヱホバいひたまふイスラエルよ汝もし歸らば我に歸れ汝もし憎むべき者を我前より除かば流蕩はじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'かつ汝は眞實と正直と公義とをもてヱホバは活くと誓はんさらば萬國の民は彼によりて福祉をうけ彼によりて誇るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'ヱホバ、ユダとヱルサレムの人々にかくいひ給ふ汝等の新田を耕せ荊棘の中に種くなかれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'ユダの人々とヱルサレムに住める者よ汝等みづから割禮をおこなひてヱホバに屬きおのれの心の前の皮を去れ然らざれば汝等の惡行のためわが怒火の如くに發して燃えんこれを滅すものなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, '汝等ユダに告げヱルサレムに示していへ箛を國の中に吹けとまた大聲に呼はりていへ汝等あつまれ我儕堅き邑にゆくべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'シオンに指示す合圖の旗をたてよ逃よ留まる勿れそは我北より災とおほいなる敗壞をきたらすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, '獅子は其森よりいでて上り國々を滅すものは進みきたる彼汝の國を荒さんとて旣にその處よりいでたり汝の諸邑は滅されて住む者なきに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'この故に汝等麻の衣を身にまとひて悲み哭けそはヱホバの烈しき怒いまだ我儕を離れざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'ヱホバいひたまひけるはその日王と牧伯等はその心をうしなひ祭司は驚き預言者は異むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, '我いひけるは嗚呼主ヱホバよ汝はまことに此民とヱルサレムを大にあざむきたまふすなはち汝はなんぢら安かるべしと云給ひしに劍命にまでおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'その時この民とヱルサレムにいふものあらん熱き風 曠野の童山よりわが民の女にふききたると此は簸るためにあらず潔むる爲にもあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'これよりも猶はげしき風われより來らん今我かれらに鞫を示さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'みよ彼は雲のごとく上りきたらん其車は颶風のごとくにしてその馬は鷹よりも疾し嗚呼われらは禍なるかな我儕滅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'ヱルサレムよ汝の心の惡をあらひ潔めよ然ばすくはれん汝の惡き念いつまで汝のうちにあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'ダンより告ぐる聲ありエフライムの山より災を知するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, '汝ら國々の民に告げまたヱルサレムに知らせよ攻めかこむ者遠き國より來りユダの諸邑にむかひて其聲を揚ぐと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, '彼らは田圃をまもる者のごとくにこれを圍むこは我に從はざりしに由るとヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, '汝の途と汝の行これを汝に招けりこれは汝の惡なり誠に苦くして汝の心におよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, '嗚呼わが腸よ我腸よ痛苦心の底におよびわが心胸とどろくわれ默しがたし我靈魂よ汝箛の聲と軍の鬨をきくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, '敗滅に敗滅のしらせありこの地は皆荒されわが幕屋は頃刻にやぶられ我幕は忽ち破られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, '我が旗をみ箛の聲をきくは何時までぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'それ我民は愚にして我を識らず拙き子等にして曉ることなし彼らは惡を行ふに智けれども善を行ふことを知ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'われ地を見るに形なくして空くあり天を仰ぐに其處に光なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, '我山を見るに皆震へまた諸の丘も動けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, '我見に人あることなし天空の鳥も皆飛されり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, '我みるに肥美なる地は沙漠となり且その諸の邑はヱホバの前にその烈しき怒の前に毀たれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'そはヱホバかくいひたまへりすべて此地は荒地とならんされど我ことごとくは之を滅さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, '故に地は皆哀しみ上なる天は暗くならん我すでに之をいひ且これを定めて悔いずまた之をなす事を止ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, '邑の人みな騎兵と射者の咄喊のために逃て叢林にいり又岩の上に升れり邑はみな棄られて其處に住む人なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, '滅されたる者よ汝何をなさんとするや設令汝くれなゐの衣をき金の飾物をもて身を粧ひ目をぬりて大くするとも汝が身を粧ふはいたづらなり汝の戀人らは汝をいやしめ汝のいのちを索るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'われ子をうむ婦のごとき聲首子をうむ者の苦むがごとき聲を聞く是れシオンの女の聲なりかれ自ら歎き手をのべていふ嗚呼われは禍なるかな我靈魂殺す者のために疲れはてぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, '汝等ヱルサレムの邑をめぐりて視且察りその街を尋ねよ汝等もし一人の公義を行ひ眞理を求る者に逢はばわれ之(ヱルサレム)を赦すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, '彼らヱホバは活くといふとも實は僞りて誓ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'ヱホバよ汝の目は誠實を顧みるにあらずや汝彼らを撻どもかれら痛苦をおぼえず彼等を滅せどもかれら懲治をうけず其面を磐よりも硬くして歸ることを拒めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, '故に我いひけるは此輩は惟いやしき愚なる者なればヱホバの途と其神の鞫を知ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'われ貴人にゆきて之に語らんかれらはヱホバの途とその神の鞫を知るなり然に彼らも皆軛を折り縛を斷り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, '故に林よりいづる獅子は彼らを殺しアラバの狼はかれらを滅し豹はその邑をねらふ此處よりいづる者は皆裂るべしそは其罪おほくその背違はなはだしければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, '我なに故に汝をゆるすべきや汝の諸子われを棄て神にあらざる神を指して誓ふ我すでに彼らを誓はせたれど彼ら姦淫して娼妓の家に群集る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, '彼らは肥たる牡馬のごとくに行めぐりおのおの嘶きて隣の妻を慕ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'ヱホバいひたまふ我これらの事のために彼らを罰せざらんや我心はかくの如き民に仇を復さざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, '汝等その石垣にのぼりて滅せされど悉くはこれを滅す勿れその枝を截除けヱホバのものに有ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'イスラエルの家とユダの家は大に我に悖るなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, '彼等はヱホバを認ずしていふヱホバはある者にあらず災われらに來らじ我儕劍と饑饉をも見ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, '預言者は風となり言はかれらの衷にあらず斯彼らになるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, '故に萬軍の神ヱホバかくいひたまふ汝等この言を語により視よわれ汝の口にある我言を火となし此民を薪となさんその火彼らを焚盡すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'ヱホバいひ給ふイスラエルの家よみよ我遠き國人をなんぢらに來らしめん其國は強くまた古き國なり汝等その言をしらず其語ることをも曉らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'その箙は啓きたる墓のごとし彼らはみな勇士なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, '彼らは汝の穡れたる物と汝の糧食を食ひ汝の子女を食ひ汝の羊と牛を食ひ汝の葡萄の樹と無花果の樹を食ひまた劍をもて汝の賴むところの堅き邑を滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'されど其時われことごとくは汝を滅さじとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, '汝等何ゆゑにわれらの神ヱホバ此等の諸のことを我儕になしたまふやといはば汝かれらに答ふべし汝ら我をすて汝らの地に於て異なる神に奉へしごとく汝らのものにあらざる地に於て異邦人につかふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, '汝これをヤコブの家にのべまたこれをユダに示していへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, '愚にして了知なく目あれども見えず耳あれども聞えざる民よこれをきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'ヱホバいひ給ふ汝等われを畏れざるか我前に戰慄かざるか我は沙を置て海の界となしこれを永遠の限界となし踰ることをえざらしむ其浪さかまきいたるも勝ことあたはず澎湃もこれを踰るあたはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, '然るにこの民は背き且悖れる心あり旣に背きて去れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, '彼らはまた我儕に雨をあたへて秋の雨と春の雨を時にしたがひて下し我儕のために收穫の時節を定め給へる我神ヱホバを畏るべしと其心にいはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, '汝等の愆はこれらの事を退け汝等の罪は嘉物を汝らに來らしめざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, '我民のうちに惡者あり網を張る者のごとくに身をかがめてうかがひ罟を置て人をとらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, '樊籠に鳥の盈るがごとく不義の財彼らの家に充つこの故に彼らは大なる者となり富る者となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, '彼らは肥て光澤あり其惡き行は甚し彼らは訟をたださず孤の訟を糺さずして利達をえ亦貧者の訴を鞫かず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'ヱホバいひ給ふわれかくのごときことを罰せざらんや我心は是のごとき民に仇を復さざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'この地に驚くべき事と憎むべきこと行はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, '預言者は僞りて預言をなし祭司は彼らの手によりて治め我民は斯る事を愛すされど汝等その終に何をなさんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'ベニヤミンの子等よヱルサレムの中より逃れテコアに箛をふきベテハケレムに合圖の火をあげよそは北より災と大なる敗壞のぞめばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'われ美しき窈窕なるシオンの女を滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, '牧者は其群を牽て此處にきたりその周圍に天幕をはらん群はおのおのその處にて草を食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '汝ら戰端を開きて之を攻べし起よわれら日午にのぼらん嗚呼惜かな日ははや昃き夕日の影長くなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, '起よわれら夜の間にのぼりてその諸の殿舍を毀たん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, '萬軍のヱホバかくいひたまへり汝ら樹をきりヱルサレムに向ひて壘を築けこれは罰すべき邑なりその中には唯暴逆のみあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, '源の水をいだすがごとく彼その惡を流すその中に暴逆と威虐きこゆ我前に憂と傷たえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'ヱルサレムよ汝訓戒をうけよ然らざれば我心汝をはなれ汝を荒蕪となし住む人なき地となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, '萬軍のヱホバかくいひたまふ彼らは葡萄の遺餘を摘みとるごとくイスラエルの遺れる者を摘とらん汝葡萄を摘取者のごとく屢手を筐に入るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, '我たれに語り誰を警めてきかしめんや視よその耳は割禮をうけざるによりて聽えず彼らはヱホバの言を嘲りこれを悦ばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'ヱホバの怒わが身に充つわれ忍ぶに倦むこれを衢街にある童子と集れる年少者とに泄すべし夫も婦も老たる者も年邁し者も執へらるるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'その家と田地と妻はともに佗人にわたらん其はわれ手を擧てこの地に住る者を撃ばなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, '夫彼らは少さき者より大なる者にいたるまで皆貪婪者なり又預言者より祭司にいたるまで皆詭詐をなす者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'かれら淺く我民の女の傷を醫し平康からざる時に平康平康といへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, '彼らは憎むべき事を爲て恥辱をうくれども毫も恥ずまた愧を知らずこの故に彼らは傾仆るる者と偕にたふれん我來るとき彼ら躓かんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'ヱホバかくいひたまふ汝ら途に立て見古き徑に就て何か善道なるを尋ねて其途に行めさらば汝らの靈魂安を得ん然ど彼らこたへて我儕はそれに行まじといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, '我また汝らの上に守望者をたて箛の聲をきけといへり然ど彼等こたへて我儕は聞じといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, '故に萬國の民よきけ會衆よかれらの遇ところを知れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, '地よきけわれ災をこの民にくださんこは彼らの思の結ぶ果なりかれら我言とわが律法をきかずして之を棄るによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'シバより我許に乳香きたり遠き國より菖蒲きたるは何のためぞやわれは汝らの燔祭をよろこばず汝らの犠牲を甘しとせず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, '故にヱホバかくいひたまふみよ我この民の前に躓礙をおく父と子とそれに蹶き隣人とその友偕に滅ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'ヱホバかくいひたまふみよ民北の國よりきたる大なる民地の極より起る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, '彼らは弓と槍をとる殘忍にして憫なしその聲は海の如く鳴るシオンの女よかれらは馬に乗り軍人のごとく身をよろひて汝を攻めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, '我儕その風聲をききたれば我儕の手弱り子をうむ婦のごとき苦痛と劬勞われらに迫る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, '汝ら田地に出る勿れまた路に行むなかれ敵の劍と畏怖四方にあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, '我民の女よ麻衣を身にまとひ灰のうちにまろび獨子を喪ひしごとくに哀みていたく哭けそは毀滅者突然に我らに來るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'われ汝を民のうちに立て金を驗る者のごとくなし又城のごとくなすこは汝をしてその途を知しめまた試みしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, '彼らは皆いたく悖れる者なり歩行て人を謗る者なり彼らは銅のごとく鐵のごとし皆邪なる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, '韛は火に焚け鉛はつき鎔匠はいたづらに鎔す惡者いまだ除かれざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'ヱホバ彼らを棄たまふによりて彼等は棄られたる銀と呼ばれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'ヱホバよりヱレミヤにのぞめる言云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '汝ヱホバの室の門にたち其處にてこの言を宣て言へヱホバを拜まんとてこの門にいりしユダのすべての人よヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, '萬軍のヱホバ、イスラエルの神かくいひ給ふ汝らの途と汝らの行を改めよさらばわれ汝等をこの地に住しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, '汝ら是はヱホバの殿なりヱホバの殿なりヱホバの殿なりと云ふ僞の言をたのむ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, '汝らもし全くその途と行を改め人と人との間を正しく鞫き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, '異邦人と孤兒と寡を虐げず無辜者の血をこの處に流さず他の神に從ひて害をまねかずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, '我なんぢらを我汝等の先祖にあたへしこの地に永遠より永遠にいたるまで住しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'みよ汝らは益なき僞の言を賴む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, '汝等は盜み殺し姦淫し妄りて誓ひバアルに香を焚き汝らがしらざる他の神にしたがふなれど');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, '我名をもて稱へらるるこの室にきたりて我前にたち我らはこれらの憎むべきことを行ふとも救はるるなりといふは何にぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'わが名をもて稱へらるる此室は汝らの目には盜賊の巢と見ゆるや我も之をみたりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, '汝等わが初シロに於て我名を置し處にゆき我がイスラエルの民の惡のために其處になせしところのことをみよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'ヱホバいひたまふ今汝ら此等のすべての事をなす又われ汝らに語り頻にかたりたれども聽かず汝らを呼びたれども答へざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'この故に我シロになせしごとく我名をもて稱へらるる此室になさんすなはち汝等が賴むところ我汝らと汝らの先祖にあたへし此處になすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'またわれ汝等のすべての兄弟すなはちエフライムのすべての裔を棄てしごとく我前より汝らをも棄つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, '故に汝この民のために祈る勿れ彼らの爲に歎くなかれ求むるなかれ又我にとりなしをなす勿れわれ汝にきかじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, '汝かれらがユダの邑とヱルサレムの街になすところを見ざるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, '諸子は薪を拾め父は火を燃き婦は麺を搏ねパンをつくりて之を天后にそなふ又かれら他の神の前に酒をそそぎて我を怒らす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'ヱホバいひたまふ彼ら我を怒らするか是れおのが面を辱むるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, '是故に主ヱホバかくいひたまふ視よわが震怒とわが憤怒はこの處と人と獸と野の樹および地の果にそそがん且燃て滅ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, '萬軍のヱホバ、イスラエルの神かくいひたまふ汝らの犠牲に燔祭の物をあはせて肉をくらへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'そはわれ汝等の先祖をエジプトより導きいだせし日に燔祭と犠牲とに就てかたりしことなく又命ぜしことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, '惟われこの事を彼等に命じ汝ら我聲を聽ばわれ汝らの神となり汝ら我民とならん且わが汝らに命ぜしすべての道を行みて福祉をうべしといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'されど彼らはきかず其耳を傾けずおのれの惡き心の謀と剛愎なるとにしたがひて行みまた後を我にむけて其面を向けざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, '汝らの先祖がエジプトの地をいでし日より今日にいたるまでわれ我僕なる預言者を汝らにつかはし日々晨より之をつかはせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'されど彼らは我にきかず耳を傾けずして其項を強くしその列祖よりも愈りて惡をなすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, '汝彼らに此等のすべてのことばを語るとも汝にきかずかれらを呼ぶとも汝にこたへざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, '汝かく彼らに語れこれは其神ヱホバの聲を聽ずその訓を受ざる民なり眞實はうせてその口に絕たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, '(シオンの女よ)汝の髮を剃りてこれを棄て山の上に哀哭の聲をあげよヱホバその怒るところの世の人をすててこれを離れたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'ヱホバいひたまふユダの民は我前に惡を行へり即ちその憎むべき者を我名をもて稱へらるる室に置てこれを汚せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, '又ベンヒンノムの谷に於てトペテの崇邱を築きてその子女を火に焚かんとせり我これを命ぜずまた斯ることを思はざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'ヱホバいひたまふ然ば視よ此處をトペテまたはベンヒンノムの谷と稱へずして殺戮の谷と稱ふる日きたらん其は葬るべき地所なきまでにトペテに葬るべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'この民の屍は天空の鳥と地の獸の食物とならんこれを逐ふものなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'その時われユダの邑とヱルサレムの街に欣喜の聲 歡樂の聲 新婿の聲 新婦の聲なからしむべしこの地荒蕪ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'ヱホバいひたまふその時人ユダの王等の骨とその牧伯等の骨と祭司の骨と預言者の骨とヱルサレムの民の骨をその墓よりほりいだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, '彼等の愛し奉へ從ひ求め且祭れるところの日と月と天の衆群の前にこれを曝すべし其骨はあつむる者なく葬る者なくして糞土のごとくに地の面にあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'この惡き民の中ののこれる餘遺の者すべてわが逐やりしところに餘れる者皆生るよりも死ぬることを願んと萬軍のヱホバ云たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, '汝また彼らにヱホバかくいふと語るべし人もし仆るれば起きかへるにあらずやもし離るれば歸り來るにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, '何故にヱルサレムにをる此民は恒にわれを離れて歸らざるや彼らは詐僞をかたく執て歸ることを否めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'われ耳を側てて聽に彼らは善ことを云ず一人もその惡を悔いてわがなせし事は何ぞやといふ者なし彼らはみな戰場に馳入る馬のごとくにその途に歸るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, '天空の鶴はその定期を知り斑鳩と燕と鴈はそのきたる時を守るされど我民はヱホバの律法をしらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, '汝いかで我ら智慧ありわれらにはヱホバの律法ありといふことをえんや視よまことに書記の僞の筆之を僞とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, '智慧ある者は辱しめられまたあわてて執へらる視よ彼等ヱホバの言を棄たり彼ら何の智慧あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, '故にわれその妻を他人にあたへ其田圃を他人に嗣しめん彼らは小さき者より大なる者にいたるまで皆貪婪者また預言者より祭司にいたるまで皆詭詐をなす者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, '彼ら我民の女の傷を淺く醫し平康からざる時に平康平康といへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, '彼ら憎むべき事をなして恥辱らる然れど毫も恥ずまた恥を知らずこの故に彼らは仆るる者と偕に仆れんわが彼らを罰するときかれら躓くべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'ヱホバいひたまふ我彼らをことごとく滅さん葡萄の樹に葡萄なく無花果の樹に無花果なしその葉も槁れたり故にわれ殲滅者を彼らにつかはす.');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, '我ら何ぞ此にとどまるやあつまれよ我ら堅き城邑にゆきて其處に滅ん我儕ヱホバに罪を犯せしによりて我らの神ヱホバ我らを滅し毒なる水を飮せたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'われら平康を望めども善こと來らず慰めらるる時を望むにかへつて恐懼きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'その馬の嘶はダンよりきこえこの地みなその強き馬の聲によりて震ふ彼らきたりて此地とその上にある者および邑とその中に住る者を食ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, '視よわれ呪詛のきかざる蛇蝮を汝らのうちに遣はさん是汝らを嚙べしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, '嗚呼われ憂ふいかにして慰藉をえんや我衷の心惱む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'みよ遠き國より我民の女の聲ありていふヱホバはシオンに在さざるか其王はその中に在ざるかと(ヱホバいひたまふ)彼らは何故にその偶像と異邦の虛き物をもて我を怒らせしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '收穫の時は過ぎ夏もはや畢りぬされど我らはいまだ救はれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, '我民の女の傷によりて我も傷み且悲しむ恐懼我に迫れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'ギレアデに乳香あるにあらずや彼處に醫者あるにあらずやいかにして我民の女はいやされざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'ああ我わが首を水となし我目を涙の泉となすことをえんものを我民の女の殺されたる者の爲に晝夜哭かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, '嗚呼われ曠野に旅人の寓所をえんものを我民を離れてさりゆかん彼らはみな姦淫するもの悖れる者の族なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, '彼らは弓を援くがごとく其舌をもて僞をいだす彼らは此地において眞實のために強からず惡より惡にすすみまた我を知ざるなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, '汝らおのおの其隣に心せよ何の兄弟をも信ずる勿れ兄弟はみな欺きをなし隣はみな讒りまはればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, '彼らはおのおの其隣を欺きかつ眞實をいはず其舌に謊をかたることを敎へ惡をなすに勞る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, '汝の住居は詭譎の中にあり彼らは詭譎のために我を識ことをいなめりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, '故に萬軍のヱホバかくいひたまへり視よ我かれらを鎔し試むべしわれ我民の女の事を如何になすべきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, '彼らの舌は殺す矢のごとしかれら詭をいふまた其口をもて隣におだやかにかたれども其心の中には害をはかるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'ヱホバいひたまふ我これらの事のために彼らを罰せざらんや我心はかくのごとき民に仇を復さざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'われ山のために泣き咷び野の牧場のために悲むこれらは焚れて過る人なしまたここに牛羊の聲をきかず天空の鳥も獸も皆逃てさりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'われヱルサレムを邱墟とし山犬の巢となさんまたユダの諸の邑々を荒して住む人なからしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, '智慧ありてこの事を曉る人は誰ぞやヱホバの口の言を受てこれを示さん者は誰ぞやこの地滅されまた野のごとく焚れて過る者なきにいたりしは何故ぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'ヱホバいひたまふ是彼ら我その前に立しところの律法をすて我聲をきかず之に從はざるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, '彼らはその心の剛愎なるとその列祖たちがおのれに敎へしバアルとに從へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'この故に萬軍のヱホバ、イスラエルの神かくいひたまふ視よわれ彼等すなはち斯民に茵蔯を食はせ毒なる水を飮せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, '彼らもその先祖たちもしらざりし國人のうちに彼らを散しまた彼らを滅し盡すまで其後に劍をつかはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, '萬軍のヱホバかくいひたまふ汝らよく考へ哭婦をよびきたれ又人を遣して智き婦をまねけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, '彼らは速にきたりて我儕のために哭哀しみ我儕の目に涙をこぼさせ我儕の目蓋より水を溢れしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'シオンより哀の聲きこゆ云く嗚呼われら滅され我ら痛く辱めらる我らは其地を去り彼らはわが住家を毀ちたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, '婦たちよヱホバの言をきけ汝らの耳に其口の言をいれよ汝らの女に哭ことを敎へおのおのその隣に哀の歌を敎ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'そは死のぼりてわれらの窓よりいり我らの殿舍に入り外にある諸子を絕し街にある壯年を殺さんとすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'ヱホバかくいへりと汝云ふべし人の屍は糞土のごとく田野に墮ちんまた收穫者のうしろに殘りて斂めずにある把のごとくならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'ヱホバかくいひたまふ智慧ある者はその智慧に誇る勿れ力ある者は其力に誇るなかれ富者はその富に誇ること勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, '誇る者はこれをもて誇るべし即ち明哲して我を識る事とわがヱホバにして地に仁惠と公道と公義とを行ふ者なるを知る事是なり我これらを悦ぶなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'ヱホバいひたまひけるは視よわれすべて陽の皮に割禮をうけたる者すなはちエジプトとユダとエドムとアンモンの子孫とモアブと野にをりてその鬚を剃る者とを罰する日きたらんそはすべて異邦人は割禮をうけずまたイスラエルの家も心に割禮をうけざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'ヱホバいひたまひけるは視よわれすべて陽の皮に割禮をうけたる者すなはちエジプトとユダとエドムとアンモンの子孫とモアブと野にをりてその鬚を剃る者とを罰する日きたらんそはすべて異邦人は割禮をうけずまたイスラエルの家も心に割禮をうけざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'イスラエルの家よヱホバの汝らに語たまふ言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'ヱホバかくいひたまふ汝ら異邦人の途に效ふ勿れ異邦人は天にあらはるる徴を懼るるとも汝らはこれを懼るる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, '異國人の風俗はむなしその崇むる者は林より斫たる木にして木匠の手に斧をもて作りし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, '彼らは銀と金をもてこれを飾り釘と鎚をもて之を堅めて搖動かざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'こは圓き柱のごとくにして言はずまた歩むこと能はざるによりて人にたづさへらる是は災害をくだし亦は福祉をくだすの權なきによりて汝らこれを畏るる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'ヱホバよ汝に比ふべき者なし汝は大なり汝の名は其權威のために大なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, '汝萬國の王たる者よ誰か汝を畏れざるべきや汝を畏るるは當然なりそは萬國のすべての博士たちのうちにもその諸國のうちにも汝に比ふべき者なければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, '彼らはみな獸のことくまた痴愚なり虛しき者の敎は惟木のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'タルシシより携へ來し銀箔ウパズより携へ來し金は鍛冶と鑄匠の作りし物なり靑と紫をその衣となす是はすべて巧みなる細工人の工作なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'ヱホバは眞の神なり彼は活る神なり永遠の王なり其怒によりて地は震ふ萬國はその憤怒にあたること能はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, '汝等かく彼らにいふべし天地を造らざりし諸神は地の上よりこの天の下より失さらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'ヱホバはその能をもて地をつくり其智慧をもて世界を建てその明哲をもて天を舒べたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'かれ聲をいだせば天に衆の水ありかれ雲を地の極よりいだし電と雨をおこし風をその府庫よりいだす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'すべての人は獸の如くにして智なしすべての鑄匠はその作りし像のために辱をとる其鑄るところの像は僞物にしてその中に靈魂なければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, '是らは虛き者にして迷妄の工作なりその罰せらるるときに滅ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'ヤコブの分は是のごとくならず彼は萬物の造化主なりイスラエルはその產業の杖なりその名は萬軍のヱホバといふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, '圍の中に坐する者よ汝の包を地より取りあげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'ヱホバかくいひたまふみよ我この地にすめる者を此度擲たん且かれらをせめなやまして擄へられしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'われ毀傷をうく嗚呼われは禍なるかな我傷は重し我いふこれまことにわが患難なりわれ之を忍べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'わが幕屋はやぶれわが繩索は悉く斷れ我衆子は我をすてゆきて居ずなりぬ幕屋を張る者なくわが幃をかくる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, '牧者は愚にしてヱホバを求めず故に利達ずその群はみな散れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'きけよ風聲あり北の國より大なる騒きたる是ユダの諸邑を荒して山犬の巢となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'ヱホバよわれ知る人の途は自己によらず且歩行む人は自らその歩履を定むること能はざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'ヱホバよ我を懲したまへ但道にしたがひ怒らずして懲したまへおそらくは我無に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, '汝を知ざる國人と汝の名を龥ざる族に汝の怒を斟ぎたまへ彼らはヤコブを噬ひ之をくらふて滅しその牧場を荒したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'ヱホバよりヱレミヤにのぞめる言いふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '汝らこの契約の言をききユダの人とヱルサレムにすめる者に告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, '汝かれらに語れイスラエルの神ヱホバかくいひたまふこの契約の言に遵はざる人は詛はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'この契約はわが汝らの先祖をエジプトの地鐵の爐の中より導き出せし日にかれらに命ぜしものなり即ち我いひけらく汝ら我聲をきき我汝らに命ぜし諸の事に從ひて行はば汝らは我民となり我は汝らの神とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'われ汝らの先祖に乳と蜜の流るる地を與へんと誓ひしことを成就んと即ち今日のごとしその時我こたへてアーメン、ヱホバといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'またヱホバ我にいひたまひけるは汝すべて此等の言をユダの諸邑とヱルサレムの衢にしめし汝ら此契約の言をききてこれを行へといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'われ汝らの列祖をエジプトの地より導出せし日より今日にいたるまで切に彼らを戒め頻に戒めて汝ら我聲に遵へといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, '然ど彼らは遵はずその耳を傾けずおのおの其惡き心の剛愎なるにしたがひて歩めり故にわれ此契約の言を彼等にきたらす是はわがかれらに之を行へと命ぜしかども彼等がおこなはざりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'またヱホバ我にいひたまひけるはユダの人々とヱルサレムに住る者の中に叛逆の事あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, '彼らは我言をきくことを好まざりしところのその先祖の罪にかへり亦他の神に從ひて之に奉へたりイスラエルの家とユダの家はわがその列祖たちと締たる契約をやぶれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'この故にヱホバかくいひ給ふみよわれ災禍をかれらにくださん彼らこれを免かるることをえざるべし彼ら我をよぶとも我聽じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'ユダの邑とヱルサレムに住る者はゆきてその香を焚し神を龥んされど是等はその災禍の時に絕てかれらを救ふことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'ユダよ汝の神の數は汝の邑の數のごとし且汝らヱルサレムの衢の數にしたがひて恥べき者に壇をたてたり即ちバアルに香を焚んとて壇をたつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, '故に汝この民の爲に祈る勿れ又その爲に泣きあるひは求る勿れ彼らがその災禍のために我を呼ときわれ彼らに聽ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'わが愛する者は我室にて何をなすや惡き謀をなすや願と聖き肉汝に災を脱れしむるやもし然らば汝よろこぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'ヱホバ汝の名を嘉果ある美しき靑橄欖の樹と稱たまひしがおほいなる喧嚷の聲をもて之に火をかけ且その枝を折りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, '汝を植し萬軍のヱホバ汝の災をさだめ給へりこれイスラエルの家とユダの家みづから害ふの惡をなしたるによるなり即ちバアルに香を焚きてわれを怒らせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'ヱホバ我に知せたまひければ我これを知るその時汝彼らの作爲を我にしめしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, '我は牽れて宰られにゆく羔の如く彼らが我をそこなはんとて謀をなすを知ず彼らいふいざ我ら樹とその果とを共に滅さんかれを生る者の地より絕てその名を人に忘れしむべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, '義き鞫をなし人の心腸を察りたまふ萬軍のヱホバよ我わが訴を汝にのべたればわれをして汝が彼らに仇を報すを見せしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, '是をもてヱホバ、アナトテの人々につきてかくいひたまふ彼等汝の生命を取んと索めて言ふ汝ヱホバの名をもて預言する勿れ恐らくは汝我らの手に死んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, '故に萬軍のヱホバかくいひ給ふみよ我かれらを罰すべし壯丁は劍に死にその子女は饑饉にて死なん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, '餘る者なかるべし我災をアナトテの人々にきたらしめわが彼らを罰するの年をきたらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'ヱホバよわが汝と爭ふ時に汝は義し惟われ鞫の事につきて汝と言ん惡人の途のさかえ悖れる者のみな福なるは何故ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, '汝かれらを植たり彼らは根づき成長て實を結べりその口は汝に近けどもその心は汝に遠ざかる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'ヱホバ汝われを知り我を見またわが心の汝にむかひて何なるかを試みたまふ羊を宰りに牽いだすがごとく彼らを牽いだし殺す日の爲にかれらをそなへたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'いつまでこの地は哭きすべての畑の蔬菜は枯をるべけんやこの地に住る者の惡によりて畜獸と鳥は滅さる彼らいふ彼は我らの終をみざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '汝もし歩行者とともに趨てつかれなばいかで騎馬者と競はんや汝平安なる地を恃まばいかでヨルダンの傍の叢に居ることをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, '汝の兄弟と汝の父の家も汝を欺きまた大聲をあげて汝を追ふかれらしたしく汝に語るともこれを信ずる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'われ我家を離れわが產業をすて我靈魂の愛するところの者をその敵の手にわたせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'わが產業は林の獅子のごとし我にむかひて其聲を揚ぐ故にわれ之を惡めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, '我產業は我におけること班駁ある鳥のごとくならずや鳥之を圍むにあらずや野のすべての獸きたりあつまれ來てこれを食へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, '衆の牧者わが葡萄園をほろぼしわが地を踐踏しわがうるはしき地を荒野となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, '彼らこれを荒地となせりその荒地我にむかひて哭くなり一人もかへりみる者なければこの全地は荒たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, '毀滅者は野のすべての童山のうへに來れりヱホバの劍地のこの極よりかの極までを滅ぼすすべて血氣ある者は安をえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, '彼らは麥を播て荊棘をかる勞れども得るところなし汝らはその作物のために恥るにいたらん是ヱホバの烈き怒によりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'わがイスラエルの民に嗣しむる產業をせむるところのすべてのわが惡き隣にむかひてヱホバかくいふみよわれ彼等をその地より拔出しまたユダの家を彼らの中より拔出すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'われ彼らを拔出せしのちまた彼らを恤みておのおのを其產業にかへし各人をその地に歸らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, '彼等もし我民の道をまなび我名をさしてヱホバは活くと誓ふこと嘗て我民を敎へてバアルを指て誓はしめし如くせば彼らはわが民の中に建らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'されど彼らもし聽かざれば我かならずかかる民を全く拔出して滅すべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'ヱホバかくいひたまへり汝ゆきて麻の帶をかひ汝の腰にむすべ水に入る勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'われすなはちヱホバの言に遵ひ帶をかひてわが腰にむすべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'ヱホバの言ふたたび我にのぞみて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '汝が買て腰にむすべる帶を取り起てユフラテにゆき彼處にてこれを磐の穴にかくせと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'ここに於てわれヱホバの命じたまひし如く往てこれをユフラテの涯にかくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'おほくの日を經しのちヱホバ我にいひたまひけるは起てユフラテにゆきわが汝に命じて彼處にかくさしめし帶を取れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'われすなはちユフラテにゆき帶を我隱せしところより掘取りしにその帶は朽て用ふるにたへず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'またヱホバの言われにのぞみて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'ヱホバかくいふ我かくの如くユダの驕傲とヱルサレムの大なる驕傲をやぶらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'この惡き民はわが言を聽ことをこばみ己の心の剛愎なるにしたがひて行み且他の神に從ひてこれにつかへ之を拜す彼等は此帶の用ふるにたへざるが如くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'ヱホバいふ帶の人の腰に附がごとくわれイスラエルのすべての家とユダのすべての家を我に附しめ之を我民となし名となし譽となし榮となさんとせり然るに彼等はきかざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, '故に汝この言を彼らに語るべしイスラエルの神ヱホバかくいふ酒壺には皆酒盈つと彼汝にこたへていはん我儕豈酒壺に酒の盈ることを知ざらんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, '其時汝かれらにいふべしヱホバかくいふみよわれ此地に住るすべての者とダビデの位に坐する王等と祭司と預言者およびヱルサレムに住るすべての者に醉を盈せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, '彼らを此と彼と打あはせて碎かん父と子をも然すべしわれ彼らを恤まず惜まず憐まずして滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, '汝らきけ耳を傾けよ驕る勿れヱホバかたりたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, '汝らの神ヱホバに其いまだ暗を起したまはざる先汝らの足のくらき山に躓かざる先に榮光を皈すべし汝ら光明を望まんにヱホバ之を死の蔭に變へ之を昏黑となしたまふにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, '汝ら若これを聽ずば我靈魂は汝らの驕を隱なるところに悲まん又ヱホバの群の掠めらるるによりて我目いたく泣て涙をながすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'なんぢ王と大后につげよ汝ら自ら謙りて坐せそはなんぢらの美しき冕汝らの首より落べければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, '南の諸邑は閉てこれを啓く人なしユダは皆擄移され盡くとらへ移さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, '汝ら目を擧げて北より來る者をみよ汝らが賜はりし群汝のうるはしき群はいづこにあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'かれ汝の親み馴たる者を汝の上にたてて首領となさんとき汝何のいふべきことあらんや汝の痛は子をうむ婦のごとくならざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, '汝心のうちに何故にこの事我にきたるやといふか汝の罪の重によりて汝の裾は掲げられなんぢの踵はあらはさるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'エテオピア人その膚をかへうるか豹その斑駁をかへうるか若これを爲しえば惡に慣たる汝らも善をなし得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, '故にわれ彼らを散して野の風に吹散さるる皮壳のごとくせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'ヱホバいひたまふこは汝の得べき分わが量て汝にあたふる產業なり汝我をわすれて虛假を依賴ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, '故にわれ汝の前の裳を剥ぎて汝の羞恥をあらはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'われ汝の姦淫と汝の嘶と汝が岡のうへと野になせし汝の亂淫の罪と汝の憎むべき行をみたりヱルサレムよ汝は禍なるかな汝の潔くせらるるには尚いくばくの時を經べきや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, '乾旱の事につきてヱレミヤにのぞみしヱホバの言は左のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'ユダは悲むその門は傾き地にたふれて哭くヱルサレムの咷は上る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'その侯伯等は僕をつかはして水を汲しむ彼ら井にいたれども水を見ず空き器をもちて歸り恥かつ憂へてその首をおほふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, '地に雨ふらずして土燥裂たるにより農夫は恥て首を掩ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'また野にある麀は子をうみて之を棄つ草なければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, '野の驢馬は童山のうへにたちて山犬のごとく喘ぎ草なきによりて目眩む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'ヱホバよ我儕の罪われらを訟へて證をなすとも願くは汝の名の爲に事をなし給へ我儕の違背はおほいなり我儕汝に罪を犯したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'イスラエルの企望なる者その艱るときに救ひたまふ者よ汝いかなれば此地に於て他邦人のごとくし一夜寄宿の旅客のごとくしたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, '汝いかなれば呆てをる人のごとくし救をなすこと能はざる勇士のごとくしたまふやヱホバよ汝は我らの間にいます我儕は汝の名をもて稱へらるる者なり我らを棄たまふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'ヱホバこの民にかくいひたまへり彼らかく好んでさまよひ其足を禁めざればヱホバ彼らを悦ばずいまその愆をおぼえ其罪を罰すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'ヱホバまた我にいひたまひけるは汝この民のために恩をいのる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, '彼ら斷食するとも我その呼龥をきかず燔祭と素祭を献るとも我これをうけず却てわれ劍と饑饉と疫病をもて彼らを滅すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'われいひけるは嗚呼主ヱホバよみよ預言者たちはこの民にむかひ汝ら劍を見ざるべし饑饉は汝らにきたらじわれ此處に鞏固なる平安を汝らにあたへんといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'ヱホバ我にいひたまひけるは預言者等は我名をもて詭を預言せりわれ之を遣さず之に命ぜずまた之にいはず彼らは虛誕の默示と卜筮と虛きことと己の心の詐を汝らに預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'この故にかの吾が遣さざるに我名をもて預言して劍と饑饉はこの地にきたらじといへる預言者等につきてヱホバかくいふこの預言者等は劍と饑饉に滅さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'また彼等の預言をうけし民は饑饉と劍によりてヱルサレムの街に擲棄られんこれを葬る者なかるべし彼等とその妻および其子その女みな然りそはわれ彼らの惡をその上に斟げばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, '汝この言を彼らに語るべしわが目は夜も晝もたえず涙を流さんそは我民の童女大なる滅と重き傷によりて亡さるればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'われ出て畑にゆくに劍に死る者あり我邑にいるに饑饉に艱むものあり預言者も祭司もみなその地にさまよひて知ところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, '汝はユダを悉くすてたまふや汝の心はシオンをきらふや汝いかなれば我儕を撃て愈しめざるか我ら平安を望めども善ことあらず又醫さるる時を望むに却て驚懼あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'ヱホバよ我らはおのれの惡と先祖の愆を知るわれら汝に罪を犯したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, '汝の名のために我らを棄たまふ勿れ汝の榮の位を辱めたまふ勿れ汝のわれらに立し契約をおぼえて毀りたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, '異邦の虛き物の中に雨を降せうるものあるや天みづから白雨をくだすをえんや我らの神ヱホバ汝これを爲したまふにあらずや我ら汝を望むそは汝すべて此等を悉く作りたまひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'ヱホバ我にいひたまひけるはたとひモーセとサムエルわが前にたつとも我こころは斯民を顧ざるべしかれらを我前より逐ひていでさらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, '彼らもし汝にわれら何處にいでさらんやといはば汝彼らにヱホバかくいへりといへ死に定められたる者は死にいたり劍に定められたる者は劍にいたり饑饉に定められたる者は饑饉にいたり虜に定められたる者は虜にいたるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'ヱホバ云たまひけるはわれ四の物をもて彼らを罰せんすなはち劍をもて戮し犬をもて噬せ天空の鳥および地の獸をもて食ひ滅さしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'またユダの王ヒゼキヤの子マナセがヱルサレムになせし事によりわれ彼らをして地のすべての國に艱難をうけしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'ヱルサレムよ誰か汝を憐まんたれか汝のために嘆かん誰かちかづきて汝の安否を問はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'ヱホバいひたまふ汝われをすてたり汝退けり故にわれ手を汝のうへに伸て汝を滅さんわれ憫に倦り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'われ風扇をもて我民をこの地の門に煽がんかれらは其途を離れざるによりて我その子を絕ち彼らを滅すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, '彼らの寡婦はわが前に海濱の沙よりも多し晝われほろぼす者を携へきたりて彼らと壯者の母とをせめ驚駭と恐懼を突然にかれの上におこさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, '七人の子をうみし婦は衰へて氣たえ尚晝なるにその日は早く沒る彼は辱められて面をあからめん其餘れる者はわれ之をその敵の劍に付さんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, '嗚呼われは禍なるかな我母よ汝なに故に我を生しや全國の人我と爭ひ我を攻むわれ人に貸さず人また我に貸さず皆我を詛ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'ヱホバいひたまひけるは我實に汝に益をえせしめんために汝を惱す我まことに敵をして其艱の時と災の時に汝に求むることをなさしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, '鐵いかで北の鐵と銅を碎かんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'われ汝の資產と汝の資財を擄掠物とならしめ價をうることなからしめん是汝のすべての罪によるなりすべて汝の境のうちにかくなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'われ汝の敵をして汝を汝の識ざる地にとらへ移さしめん夫我怒によりて火燃え汝を焚んとするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'ヱホバよ汝これを知りたまふ我を憶え我をかへりみたまへ我を迫害るものに仇を復したまへ汝の容忍によりて我をとらへられしむる勿れ我汝の爲に辱を受るを知りたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'われ汝の言を得て之を食へり汝の言はわが心の欣喜快樂なり萬軍の神ヱホバよわれは汝の名をもて稱へらるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'われ嬉笑者の會に坐せずまた喜ばずわれ汝の手によりて獨り坐す汝憤怒をもて我に充したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, '何故にわが痛は息ずわが傷は重くして愈ざるか汝はわれにおけること水をたもたずして人を欺く溪河のごとくなるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, '是をもてヱホバかくいひたまへり汝もし歸らば我また汝をかへらしめて我前に立しめん汝もし賤をすてて貴をいださば我口のごとくならん彼らは汝に歸らんされど汝は彼らにかへる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'われ汝をこの民の前に堅き銅の牆となさんかれら汝を攻るとも汝にかたざるべしそはわれ汝と偕にありて汝をたすけ汝を救へばなりとヱホバいひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, '我汝を惡人の手より救ひとり汝を怖るべき者の手より放つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'ヱホバの言また我にのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '汝この處にて妻を娶るなかれ子女を得るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, '此處に生るる子女とこの地に之を生む母と之を生む父とに就てヱホバかくいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, '彼らは慘しき病に死し哀まれず葬られずして糞土のごとくに田地の面にあらんまた劍と饑饉に滅されて其屍は天空の鳥と地の獸の食物とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'ヱホバかくいひたまへり喪ある家にいる勿れまた往て之を哀み嗟く勿れそはわれ我平安と恩寵と矜恤をこの民より取ばなりとヱホバいひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, '大なる者も小さき者もこの地に死べし彼らは葬られずまた彼らのために哀む者なく自ら傷くる者なく髮をそる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'またその哀むときパンをさきて其死者のために之を慰むるものなく又父あるひは母のために慰藉の杯を彼らに飮しむる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, '汝また筵宴の家にいりて偕に坐して食飮する勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, '萬軍のヱホバ、イスラエルの神かくいひたまふ視よ汝の目の前汝の世に在るときにわれ欣喜の聲と歡樂の聲と新娶者の聲と新婦の聲とを此處に絕しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, '汝このすべての言を斯民に告るとき彼ら汝に問ふてヱホバわれらを責てこの大なる災を示したまふは何故ぞやまたわれらに何の惡事あるやわが神ヱホバに背きてわれらのなせし罪は何ぞやといはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, '汝かれらに答ふべしヱホバいひたまふ是汝らの先祖われを棄て他の神に從ひこれに奉へこれを拜しまた我をすてわが律法を守らざりしによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, '汝らは汝らの先祖よりも多く惡をなせりみよ汝らはおのおの自己の惡き心の剛愎なるにしたがひて我にきかず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, '故にわれ汝らを此の地より逐ひて汝らと汝らの先祖の識ざる地にいたらしめん汝らかしこにて晝夜ほかの神に奉へん是わが汝らを憐まざるによるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'ヱホバいひたまふ然ばみよ此後イスラエルの民をエジプトの地より導きいだせしヱホバは活くといふことなくして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'イスラエルの民を北の地とそのすべて逐やられし地より導出せしヱホバは活くといふ日きたらん我かれらを我その先祖に與へしかれらの地に導きかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'ヱホバいひたまふみよ我おほくの漁者をよび來りて彼らを漁らせまたその後おほくの獵者を呼來りて彼らを諸の山もろもろの岡および岩の穴より獵いださしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, '我目はかれらの諸の途を鑒る皆我にかくるるところなし又その惡は我目に匿れざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'われまづ倍して其惡とその罪に報いんそは彼らその汚れたる者の屍をもて我地を汚しその惡むべきものをもて我產業に充せばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'ヱホバ我の力 我の城 難の時の逃場よ萬國の民は地の極より汝にきたりわれらの先祖の嗣るところの者は惟謊と虛浮事と益なき物のみなりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, '人豈神にあらざる者をおのれの神となすべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '故にみよわれ此度かれらに知らしむるところあらん即ち我手と我能をかれらに知らしめん彼らは我名のヱホバなるを知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'ユダの罪は鐵の筆金剛石の尖をもてしるされその心の碑と汝らの祭壇の角に鐫らるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, '彼らはその子女をおもふが如くに靑木の下と高岡のうへなるその祭壇とアシラをおもふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'われ野に在る我山と汝の資產と汝のもろもろの財產および汝の四方の境の内なる汝の罪を犯せる崇邱を擄掠物とならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'わが汝にあたへし產業より汝手をはなさん又われ汝をして汝の識ざる地に於て汝の敵につかへしめんそは汝ら我をいからせて限なく燃る火を發したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'ヱホバかくいひたまふおほよそ人を恃み肉をその臂とし心にヱホバを離るる人は詛るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, '彼は荒野に棄られたる者のごとくならん彼は善事のきたるをみず荒野の燥きたる處鹽あるところ人の住ざる地に居らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'おほよそヱホバをたのみヱホバを其恃とする人は福なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, '彼は水の旁に植たる樹の如くならん其根を河にのべ炎熱きたるも恐るるところなしその葉は靑く亢旱の年にも憂へずして絕ず果を結ぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, '心は萬物よりも僞る者にして甚だ惡し誰かこれを知るをえんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'われヱホバは心腹を察り腎腸を試みおのおのに其途に順ひその行爲の果によりて報ゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, '鷓鴣のおのれの生ざる卵をいだくが如く不義をもて財を獲る者あり其人は命の半にてこれに離れその終に愚なる者とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, '榮の位よ原始より高き者わが聖所たる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'イスラエルの望なるヱホバよ凡て汝を離るる者は辱められん我を棄る者は土に錄されん此はいける水の源なるヱホバを離るるによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'ヱホバよ我を醫し給へ然らばわれ愈んわれを救ひたまへさらば我救はれん汝はわが頌るものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, '彼ら我にいふヱホバの言は何にあるやいま之をのぞましめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'われ牧者の職を退かずして汝にしたがひ又禍の日を願はざりき汝これを知りたまふ我唇よりいづる者は汝の面の前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, '汝我を懼れしむる者となり給ふ勿れ禍の時に汝は我避場なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, '我を攻る者を辱しめ給へ我を辱しむるなかれ彼らを怖れしめよ我を怖れしめ給ふなかれ禍の日を彼らに來らしめ滅亡を倍して之を滅し給へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'ヱホバ我にかくいひ給へり汝ゆきてユダの王等の出入する民の門及びヱルサレムの諸の門に立て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, '彼らにいへ此門より入る所のユダの王等とユダのすべての民とヱルサレムに住るすべての者よ汝らヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'ヱホバかくいひたまふ汝ら自ら愼め安息日に荷をたづさへてヱルサレムの門にいる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'また安息日に汝らの家より荷を出す勿れ諸の工作をなす勿れ我汝らの先祖に命ぜしごとく安息日を聖くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'されど彼らは遵はず耳を傾けずまたその項を強くして聽ず訓をうけざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'ヱホバいひ給ふ汝らもし謹愼て我にきき安息日に荷をたづさへてこの邑の門にいらず安息日を聖くなして諸の工作をなさずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'ダビデの位に坐する王等牧伯たちユダの民ヱルサレムに住る者車と馬に乗てこの邑の門よりいることをえんまた此邑には限なく人すまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'また人々ユダの邑とヱルサレムの四周およびベニヤミンの地と平地と山と南の方よりきたり燔祭 犠牲 素祭 馨香 謝祭を携へてヱホバの室にいらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'されど汝らもし我に聽ずして安息日を聖くせず安息日に荷をたづさへてヱルサレムの門にいらばわれ火をその門の内に燃してヱルサレムの殿舍を燬んその火は滅ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'ヱホバよりヱレミヤにのぞめる言いふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '汝起て陶人の屋にくだれ我かしこに於てわが言を汝に聞しめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'われすなはち陶人の屋にくだり視るに轆轤をもて物をつくりをりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'その泥をもて造れるところの器陶人の手のうちに傷ねたれば彼その心のままに之をもて別の器をつくれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, '時にヱホバの言我にのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'ヱホバいふイスラエルの家よこの陶人のなすが如くわれ汝になすことをえざるかイスラエルの家よ陶人の手に泥のあるごとく汝らはわが手にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'われ急に民あるひは國をぬくべし敗るべし滅すべしといふことあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'もし我いひしところの國その惡を離れなば我之に災を降さんとおもひしことを悔ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, '我また急に民あるいは國を立べし植べしといふことあらんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'もし其國わが目に惡く見ゆるところの事を行ひわが聲に遵はずば我これに福祉を錫へんといひしことを悔ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, '汝いまユダの人々とヱルサレムに住る者にいへヱホバかくいへり視よ我汝らに災をくださんと思ひめぐらし汝らをはかる計策を設く故に汝らおのおの其惡き途を離れ其途と行をあらためよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'しかるに彼らいふ是は徒然なりわれらは自己の圖維ところにしたがひ各自その惡き心の剛愎なるを行はんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'この故にヱホバかくいひたまふ汝ら異國のうちに問へ斯の如きことを聞し者ありやイスラエルの處女はいと驚くべきことをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'レバノンの雪豈野の磐を離れんや遠方より流くる冷なる水豈涸かんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'しかるに我民は我をわすれて虛き物に香を焚り是等の物彼らをその途すなはち古き途に蹶かせまた徑すなはち備なき道に行しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'その地を荒して恒に人の笑とならしめん凡て其處を過る者は驚きてその首を搖らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'われ東風のごとくに彼らをその敵の前に散さん其滅亡の日にはわれ背を彼らに向て面をむけじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, '彼らいふ去來われら計策を設てヱレミヤをはからんそれ祭司には律法あり智慧ある者には謀畧あり預言者には言ありて失ざるべし去來われら舌をもて彼を撃ちその諸の言を聽ことをせざらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'ヱホバよ我にききたまへ又我と爭ふ者の聲をききたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, '惡をもて善に報ゆべきものならんや彼らはわが生命をとらん爲に坑を掘れりわが汝の前に立て彼らを善く言ひ汝の憤怒を止めんとせしを憶えたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'さればかれらの子女を饑饉にあたへ彼らを劍の刃にわたしたまへ其妻は子を失ひ且寡となり其男は死をもて亡されその少者は劍をもて戰に殺されよかし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, '汝突然に敵をかれらに臨ませたまふ時號呼をその家の内より聞えしめよそは彼ら坑を掘りて我を執へんとしまた機檻を置てわが足を執へんとすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'ヱホバよ汝はかれらが我を殺さんとするすべての謀畧を知りたまふ其惡を赦すことなく其罪を汝の前より抹去りたまふなかれ彼らを汝の前に仆れしめよ汝の怒りたまふ時にかく彼らになしたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'ヱホバかくいひたまふ往て陶人の瓦罇をかひ民の長老と祭司の長老の中より數人をともなひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, '陶人の門の前にあるベンヒンノムの谷にゆき彼處に於てわが汝に告んところの言を宣よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, '云くユダの王等とヱルサレムに住る者よヱホバの言をきけ萬軍のヱホバ、イスラエルの神かくいひたまふ視よ我災を此處にくだすべし凡そ之をきく者の耳はかならず鳴らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'こは彼ら我を棄てこの處を瀆し此にて自己とその先祖およびユダの王等の知ざる他の神に香を焚き且辜なきものの血をこの處に盈せばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, '又彼らはバアルの爲に崇邱を築き火をもて己の兒子を焚き燔祭となしてバアルにささげたり此わが命ぜしことにあらず我いひしことにあらず又我心に意はざりし事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'ヱホバいひたまふさればみよ此處をトペテまたはベンヒンノムの谷と稱ずして屠戮の谷と稱ふる日きたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'また我この處に於てユダとヱルサレムの謀をむなしうし劍をもて彼らを其敵の前とその生命を索る者の手に仆しまたその屍を天空の鳥と地の獸の食物となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'かつ此邑を荒して人の胡盧とならしめん凡そここを過る者はその諸の災に驚きて笑ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'また彼らがその敵とその生命を索る者とに圍みくるしめらるる時我彼らをして己の子の肉女の肉を食はせん又彼らは互にその友の肉を食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, '汝ともに行く人の目の前にてその瓦罇を毀ちて彼らにいふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, '萬軍のヱホバかくいひ給ふ一回毀てば復全うすること能はざる陶人の器を毀つが如くわれ此民とこの邑を毀たんまた彼らは葬るべき地なきによりてトペテに葬られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'ヱホバいひ給ふ我この處とこの中に住る者とに斯なし此邑をトペテの如くなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, '且ヱルサレムの室とユダの王等の室はトペテの處のごとく汚れん其は彼らすべての室の屋蓋のうへにて天の衆群に香をたき他の神に酒をそそげばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'ヱレミヤ、ヱホバの己を遣はして預言せしめたまひしトペテより歸りきたりヱホバの室の庭に立ちすべての民に語りていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '萬軍のヱホバ、イスラエルの神かくいひたまふ視よわれ我いひし諸の災をこの邑とその諸の郷村にくださん彼らその項を強くして我言を聽ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, '祭司インメルの子ヱホバの室の宰の長なるパシユル、ヱレミヤがこの言を預言するをきけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, '是に於てパシユル預言者ヱレミヤを打ちヱホバの室にある上のベニヤミンの門の桎梏に繋げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, '翌日パシユル、ヱレミヤを桎梏より釋はなちしにヱレミヤ彼にいひけるはヱホバ汝の名をパシユルと稱ずしてマゴルミッサビブ(驚懼周圍にあり)と稱び給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, '即ちヱホバかくいひたまふ視よわれ汝をして汝と汝のすべての友に恐怖をおこさしむる者となさん彼らはその敵の劍に仆れん汝の目はこれを見べし我またユダのすべての民をバビロン王の手に付さん彼は彼らをバビロンに移し劍をもて殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, '我またこの邑のすべての貨財とその得たる諸の物とその諸の珍寶とユダの王等のすべての儲蓄を其敵の手に付さん彼らはこれを掠めまた民を擄へてバビロンに移すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'パシユルよ汝と汝の家にすめる者は悉く擄へ移されん汝はバビロンにいたりて彼處に死にかしこに葬られん汝も汝が僞りて預言せし言を聽し友もみな然らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'ヱホバよ汝われを勸めたまひてわれ其勸に從へり汝我をとらへて我に勝給へりわれ日々に人の笑となり人皆我を嘲りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'われ語り呼はるごとに暴逆殘虐の事をいふヱホバの言日々にわが身の恥辱となり嘲弄となるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, '是をもて我かさねてヱホバの事を宣ず又その名をもてかたらじといへり然どヱホバのことば我心にありて火のわが骨の中に閉こもりて燃るがごとくなれば忍耐につかれて堪難し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'そは我おほくの人の讒をきく驚懼まはりにあり訴へよ彼を訴へん我親しき者はみな我蹶くことあらんかと窺ひて互にいふ彼誘はるることあらんしからば我儕彼に勝て仇を報ゆることをえんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, '然どヱホバは強き勇士のごとくにして我と偕にいます故に我を攻る者は蹶きて勝ことをえずそのなし遂ざるが爲に大なる恥辱を取ん其羞恥は何時迄も忘られざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, '義人を試み人の心膓を見たまふ萬軍のヱホバよ我汝に訴を申たれば我をして汝が彼らに仇を報すを見せしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'ヱホバに歌を謠へよヱホバを頌めよそは貧者の生命を惡者の手より救ひ給へばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'ああ我生れし日は詛はれよ我母のわれを生し日は祝せられざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'わが父に男子汝に生れしと告て父を大に喜ばせし人は詛はれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, '其人はヱホバの憫まずして滅したまひし邑のごとくなれよ彼をして朝に號呼をきかしめ午間に鬨聲をきかしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, '彼我を胎のうちに殺さず我母を我の墓となさず常にその胎を大ならしめざりしが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, '我何なれば胎をいでて艱難と憂患をかうむり恥辱をもて日を送るや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'ゼデキヤ王マルキヤの子パシユルと祭司マアセヤの子ゼパニヤをヱレミヤに遣し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'バビロンの王ネブカデネザル我らを攻むれば汝われらの爲にヱホバに求めよヱホバ恒のごとくそのもろもろの奇なる跡をもて我らを助けバビロンの王を我らより退かしめたまふことあらんと曰しむ其時ヱホバの言ヱレミヤに臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'ヱレミヤ彼らにこたへけるは汝らゼデキヤにかく語ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'イスラエルの神ヱホバかくいひたまふ視よわれ汝らがこの邑の外にありて汝らを攻め圍むところのバビロン王およびカルデヤ人とたたかひて手に持ところのその武器をかへし之を邑のうちに聚めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'われ手を伸べ臂をつよくし震怒と憤恨と烈き怒をもて汝らをせむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, '我また此邑にすめる人と畜を撃ん皆重き疫病によりて死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'ヱホバいひたまふ此後われユダの王ゼデキヤとその諸臣および民此邑に疫病と劍と饑饉をまぬかれて遺れる者をバビロンの王ネブカデネザルの手と其敵の手および凡そその生命を索る者の手に付さんバビロンの王は劍の刃をもて彼らを撃ちかれらを惜まず顧みず恤れまざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, '汝また此民にヱホバかくいふと語るべし視よわれ生命の道と死の道を汝らの前に置く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'この邑にとどまる者は劍と饑饉と疫病に死べしされど汝らを攻め圍むところのカルデヤ人に出降る者はいきん其命はおのれの掠取物となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'ヱホバいひたまふ我この邑に面を向しは福をあたふる爲にあらず禍をあたへんが爲なりこの邑はバビロンの王の手に付されん彼火をもて之を焚くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'またユダの王の家に告べし汝らヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'ダビデの家よヱホバかくいふ汝朝ごとに義く鞫をなし物を奪はるる人をその暴逆者の手より救へ否ざれば汝らの行の惡によりて我怒火のごとくに發で燃て滅ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'ヱホバいひたまふ谷と平原の磐とにすめる者よみよ我汝に敵す汝らは誰か降て我儕を攻んや誰かわれらの居處にいらんやといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, '我汝らをその行の果によりて罰せん又其林に火を起し其四周をことごとく焚つくすべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'ヱホバかくいひたまへり汝ユダの王の室にくだり彼處にこの言をのべていへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'ダビデの位に坐するユダの王よ汝と汝の臣および此門よりいる汝の民ヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'ヱホバかくいふ汝ら公道と公義を行ひ物を奪はるる人をその暴虐者の手より救ひ異邦人と孤子と嫠婦をなやまし虐ぐる勿れまた此處に無辜の血を流す勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, '汝らもし此言を眞に行はばダビデの位に坐する王とその臣および其民は車と馬に乗てこの室の門にいることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, '然ど汝らもし此言を聽ずばわれ自己を指して誓ふ此室は荒地となるべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'ヱホバ、ユダの王の家につきてかく曰たまふ汝は我におけることギレアデのごとくレバノンの巓のごとし然どわれかならず汝を荒野となし人の住はざる邑となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'われ破壞者をまふけて汝を攻めしめん彼ら各人その武器を執り汝の美しき香柏を斫てこれを火に投いれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, '多の國の人此邑をすぎ互に語てヱホバ何なれば此大なる邑にかく爲せしやといはんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, '人こたへて是は彼等其神ヱホバの契約をすてて他の神を拜し之に奉へしに由なりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, '死者の爲に泣くことなくまた之が爲に嗟くこと勿れ寧擄へ移されし者の爲にいたく嗟くべし彼は再び歸てその故園を見ざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'ユダの王ヨシヤの子シヤルム即ちその父に繼で王となりて遂に此處をいでたる者につきてヱホバかくいひたまへり彼は再び此處に歸らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, '彼はその移されし處に死んふたたび此地を見ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, '不義をもて其室をつくり不法をもて其樓を造り其隣人を傭て何をも與へず其價を拂はざる者は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, '彼いふ我己の爲に廣厦と涼しき樓をつくり又己の爲に窓を造り香柏をもて之を蔽ひ赤く之を塗んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, '汝香柏を爭ひもちふるによりて王たるを得るか汝の父は食飮せざりしや公義と公道を行ひて福を得ざりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, '彼は貧者と患艱者の訟を理して祥をえたりかく爲すは我を識ことに非ずやとヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, '然ど汝の目と心は惟貪をなさんとし無辜の血を流さんとし虐遇と暴逆をなさんとするのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, '故にヱホバ、ユダの王のヨシヤの子ヱホヤキムにつきてかく曰たまふ衆人は哀しいかな我兄かなしいかな我姊といひて嗟かず又哀しいかな主よ哀しいかな其榮と曰て嗟かじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, '彼は驢馬を埋るがごとく埋られん即ち曳れてヱルサレムの門の外に投棄らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, '汝レバノンに登りて呼ばはりバシヤンに汝の聲を揚げアバリムより呼はれ其は汝の愛する者悉く滅されたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, '汝の平康なる時我汝に語しかども汝は我にきかじといへり汝いとけなき時よりわが聲を聽ずこれ汝の故習なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, '汝の牧者はみな風に呑つくされ汝の愛する者はとらへ移されん其時汝はおのれの諸の惡のために痛く恥べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, '汝レバノンにすみ巢を香柏につくる者よ汝の劬勞子を產む婦の痛苦のごとくにきたらんとき汝の哀慘はいかにぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'ヱホバいひたまふ我は活くユダの王ヱホヤキムの子ヱコニヤは我右の手の指環なれども我これを拔ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'われ汝の生命を索る者の手および汝が其面を畏るる者の手すなはちバビロンの王ネブカデネザルの手とカルデヤ人の手に汝を付さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'われ汝と汝を生し母を汝等がうまれざりし他の地に逐やらん汝ら彼處に死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, '彼らの靈魂のいたく歸らんことを願ふところの地に彼らは歸ることをえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'この人ヱコニヤは賤しむべき壞れたる器ならんや好ましからざる器具ならんや如何なれば彼と其子孫は逐出されてその識ざる地に投やらるるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, '地よ地よ地よヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'ヱホバかくいひたまふこの人を子なくして其生命の中に榮えざる人と錄せそはその子孫のうちに榮えてダビデの位に坐しユダを治る人かさねてなかるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'ヱホバいひ給ひけるは嗚呼わが養ふ群を滅し散す牧者は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, '故にイスラエルの神ヱホバ我民を養ふ牧者につきて斯いふ汝らはわが群を散しこれを逐はなちて顧みざりき視よわれ汝らの惡き行によりて汝等に報ゆべしとヱホバいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'われ我群の遺餘たる者をその逐はなちたる諸の地より集め再びこれを其牢に歸さん彼らは子を產て多くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, '我これを養ふ牧者をその上に立ん彼等はふたたび慄かず懼ずまた失じとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'ヱホバいひたまひけるは視よわがダビデに一の義き枝を起す日來らん彼王となりて世を治め榮え公道と公義を世に行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, '其日ユダは救をえイスラエルは安に居らん其名はヱホバ我儕の義と稱らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'この故にヱホバいひ給ふ視よイスラエルの民をエジプトの地より導出せしヱホバは活くと人衆復いはずして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'イスラエルの家の裔を北の地と其諸て逐やりし地より導出せしヱホバは活くといふ日來らん彼らは自己の地に居るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, '預言者輩のために我心はわが衷に壞れわが骨は皆震ふ且ヱホバとその聖言のためにわれは醉る人のごとく酒に勝るる人のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'この地は姦淫をなすもの盈ち地は呪詛によりて憂へ曠野の艸は枯る彼らの途はあしく其力は正しからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, '預言者と祭司は偕に邪惡なりわれ我家に於てすら彼等の惡を見たりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, '故にかれらの途は暗に在る滑なる途の如くならん彼等推れて其途に仆るべし我災をその上にのぞましめん是彼らが刑罰らるる年なりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'われサマリヤの預言者の中に愚昧なる事あるをみたり彼等はバアルに託りて預言し我民イスラエルを惑はせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, '我ヱルサレムの預言者の中にも憎むべき事あるを見たり彼等は姦淫をなし詐僞をおこなひ惡人の手を堅くして人をその惡に離れざらしむ彼等みな我にはソドムのごとく其民はゴモラのごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'この故に萬軍のヱホバ預言者につきてかくいひたまふ視よわれ茵蔯を之に食はせ毒水をこれに飮せんそは邪惡ヱルサレムの預言者よりいでて此全地に及べばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, '萬軍のヱホバかくいひたまふ汝等に預言する預言者の言を聽く勿れ彼等は汝らを欺きヱホバの口よりいでざるおのが心の默示を語るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, '常に彼らは我を藐忽ずる者にむかひて汝等平安をえんとヱホバいひたまへりといひ又己が心の剛愎なるに循ひて行むところのすべての者に向ひて災汝らに來らじといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, '誰かヱホバの議會に立て其言を見聞せし者あらんや誰か其耳を傾けて我言を聽し者あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'みよヱホバの暴風あり怒と旋轉風いでて惡人の首をうたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'ヱホバの怒はかれがその心の思を行ひてこれを遂げ給ふまでは息じ末の日に汝ら明にこれを曉らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, '預言者等はわが遣さざるに趨り我告ざるに預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, '彼らもし我議會に立ちしならば我民にわが言をきかしめて之をその惡き途とその惡き行に離れしめしならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'ヱホバいひ給ふ我はただ近くにおいてのみ神たらんや遠くに於ても神たるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'ヱホバいひたまふ人我に見られざる樣に密かなる處に身を匿し得るかヱホバいひたまふ我は天地に充るにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'われ我名をもて謊を預言する預言者等がわれ夢を見たりわれ夢を見たりと曰ふをきけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, '謊を預言する預言者等はいつまで此心をいだくや彼らは其心の詐僞を預言するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, '彼らは其先祖がバアルによりて我名を忘れしごとく互に夢をかたりて我民にわが名を忘れしめんと思ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, '夢をみし預言者は夢を語るべし我言を受し者は誠實をもて我言を語るべし糠いかで麥に比擬ことをえんやとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'ヱホバ言たまはく我言は火のごとくならずや又磐を打碎く槌の如くならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, '故に視よわれ我言を相互に竊める預言者の敵となるとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, '視よわれは彼いひたまへりと舌をもて語るところの預言者の敵となるとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'ヱホバいひたまひけるは視よわれ僞の夢を預言する者の敵となる彼らは之を語りまたその謊と其誇をもて我民を惑はす我かれらを遣さずかれらに命ぜざるなり故に彼らは斯民に益なしとヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'この民或は預言者又は祭司汝に問てヱホバの重負は何ぞやといはば汝彼等にこたへてヱホバの重負は我汝等を棄んとヱホバの云たまひし事是なりといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'ヱホバの重負といふところの預言者と祭司と民には我その人と其家にこれを降さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, '汝らはおのおの斯互に言ひその兄弟にいふべしヱホバは何と應へたまひしやヱホバは何と云たまひしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, '汝ら復びヱホバの重負といふべからず人の重負となる者は其人の言なるべし汝らは活る神萬軍のヱホバなる我らの神の言を枉るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, '汝かく預言者にいふべしヱホバは汝に何と答へ給ひしやヱホバは何といひたまひしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, '汝らもしヱホバの重負といはばヱホバそれにつきてかくいひたまふ我人を汝らに遣して汝等ヱホバの重負といふべからずといはしむるも汝らはヱホバの重負といふ此言をいふによりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'われ必ず汝らを忘れ汝らと汝らの先祖にあたへし此邑と汝らとを我前より棄ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, '且われ永遠の辱と永遠なる忘らるることなき恥を汝らにかうむらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'バビロンの王ネブカデネザル、ユダの王ヱホヤキムの子ヱコニヤおよびユダの牧伯等と木匠と鐵匠をヱルサレムよりバビロンに移せしのちヱホバ我にヱホバの殿の前に置れたる二筐の無花果を示したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'その一の筐には始に熟せしがごとき至佳き無花果ありその一の筐にはいと惡くして食ひ得ざるほどなる惡き無花果あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'ヱホバ我にいひ給ひけるはヱレミヤよ汝何を見しや我答へけるは無花果なりその佳き無花果はいと佳しその惡きものは至惡しくして食ひ得ざるほどに惡し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'ヱホバの言また我にのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'イスラエルの神ヱホバかくいふ我わが此處よりカルデヤ人の地に逐ひやりしユダの虜人を此佳き無花果のごとくに顧みて惠まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, '我彼等に目をかけて之をめぐみ彼らを此地にかへし彼等を建て仆さず植て拔じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, '我彼らに我のヱホバなるを識るの心をあたへん彼等我民となり我彼らの神とならん彼等は一心をもて我に歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'ヱホバかくいひたまへり我ユダの王ゼデキヤとその牧伯等およびヱルサレムの人の遺りて此地にをる者ならびにエジプトの地に住る者とを此惡くして食はれざる惡き無花果のごとくになさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, '我かれらをして地のもろもろの國にて虐遇と災害にあはしめん又彼らをしてわが逐やらん諸の處にて辱にあはせ諺となり嘲と詛に遭しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'われ劍と饑饉と疫病をかれらの間におくりて彼らをしてわが彼らとその先祖にあたへし地に絕るにいたらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'ユダの王ヨシヤの子ヱホヤキムの四年バビロンの王ネブカデネザルの元年にユダのすべての民にかかはる言ヱレミヤにのぞめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, '預言者ヱレミヤこの言をユダのすべての民とヱルサレムにすめるすべての者に告ていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'ユダの王アモンの子ヨシヤの十三年より今日にいたるまで二十三年のあひだヱホバの言我にのぞめり我これを汝等に告げ頻にこれを語りしかども汝らきかざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'ヱホバその僕なる預言者を汝らに遣し頻に遣したまひけれども汝らはきかず又きかんとて耳を傾けざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, '彼らいへり汝等おのおのいま其惡き途とその惡き行を棄よ然ばヱホバが汝らと汝らの先祖に與へたまひし地に永遠より永遠にいたるまで住ことをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, '汝ら他の神に從ひこれに事へこれを拜み汝らの手にて作りし物をもて我を怒らする勿れ然ば我汝らを害はじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, '然ど汝らは我にきかず汝等の手にて作りし物をもて我を怒らせて自ら害へりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'この故に萬軍のヱホバかく云たまふ汝ら我言を聽ざれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, '視よ我北の諸の族と我僕なるバビロンの王ネブカデネザルを招きよせ此地とその民と其四圍の諸國を攻滅さしめて之を詫異物となし人の嗤笑となし永遠の荒地となさんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'またわれ欣喜の聲 歡樂の聲 新夫の聲 新婦の聲 磐磨の音および燈の光を彼らの中にたえしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'この地はみな空曠となり詫異物とならん又その諸國は七十年の間バビロンの王につかふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'ヱホバいひたまふ七十年のをはりし後我バビロンの王と其民とカルデヤの地をその罪のために罰し永遠の空曠となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, '我かの地につきて我かたりし諸の言をその上に臨しめん是ヱレミヤが萬國の事につきて預言したる者にて皆この書に錄さるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, '多の國々と大なる王等は彼らをして己につかへしめん我かれらの行爲とその手の所作に循ひてこれに報いん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'イスラエルの神ヱホバかく我に云たまへり我手より此怒の杯をうけて我汝を遣はすところの國々の民に飮しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, '彼らは飮てよろめき狂はんこは我かれらの中に劍をつかはすによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, '是に於てわれヱホバの手より杯をうけヱホバのわれを遣したまふところの國々の民に飮しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, '即ちヱルサレムとユダの諸の邑とその王等およびその牧伯等に飮せてこれをほろぼし詫異物となし人の嗤笑となし詛るる者となせり今日のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'またエジプトの王パロと其臣僕その牧伯等その諸の民と');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, '諸の雜種の民およびウズの諸の王等およびペリシテ人の地の諸の王等アシケロン、ガザ、エクロン、アシドドの遺餘の者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'エドム、モアブ、アンモンの子孫');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'ツロのすべての王等シドンのすべての王等海のかなたの島々の王等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'デダン、テマ、ブズおよびすべて鬚をそる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'アラビヤのすべての王等曠野の雜種の民の諸の王等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'ジムリの諸の王等エラムの諸の王等メデアのすべての王等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, '北のすべての王等その彼と此とにおいて或は遠者或は近きもの凡地の面にある世の國々の王等はこの杯を飮んセシヤク王はこれらの後に飮べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, '故に汝かれらに語ていへ萬軍のヱホバ、イスラエルの神かくいひたまふ我汝等の中に劍を遣すによりて汝らは飮みまた醉ひまた吐き又仆て再び起ざれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, '彼等もし汝の手より此杯を受て飮ずば汝彼らにいへ萬軍のヱホバかくいひたまふ汝ら必ず飮べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, '視よわれ我名をもて稱へらるるこの邑にすら災を降すなり汝らいかで罰を免るることをえんや汝らは罰を免れじ蓋われ劍をよびて地に住るすべての者を攻べければなりと萬軍のヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, '汝彼等にこの諸の言を預言していふべしヱホバ高き所より呼號り其聖宮より聲を出し己の住家に向てよばはり地に住る諸の者にむかひて葡萄を踐む者のごとく咷たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, '號咷地の極まで聞ゆ蓋ヱホバ列國と爭ひ萬民を審き惡人を劍に付せば也とヱホバ曰たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, '萬軍のヱホバかく曰たまふ視よ災いでて國より國にいたらん大なる暴風地の極よりおこるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, '其日ヱホバの戮したまふ者は地の此極より地の彼の極に及ばん彼等は哀まれず殮められず葬られずして地の面に糞土とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, '牧者よ哭き叫べ群の長等よ汝ら灰の中に轉ぶべし蓋汝らの屠らるる日滿れば也我汝らを散すべければ汝らは貴き器のごとく堕べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, '牧者は避場なく群の長等は逃る處なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, '牧者の呼號の聲と群の長等の哀哭きこゆ蓋ヱホバ其牧場を滅したまへば也');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'ヱホバの烈き怒によりて平安なる牧場は滅さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, '彼は獅子の如く其巢を出たり滅す者の怒と其烈き忿によりて彼らの地は荒されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'ユダの王ヨシヤの子ヱホヤキムが位に即し初のころヱホバより此言いでていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'ヱホバかくいふ汝ヱホバの室の庭に立我汝に命じていはしむる諸の言をユダの邑々より來りてヱホバの室に拜をする人々に告よ一言をも減す勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, '彼等聞ておのおの其惡き途を離るることあらん然ば我かれらの行の惡がために災を彼らに降さんとせることを悔べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, '汝彼等にヱホバかくいふといへ汝等もし我に聽ずわが汝らの前に置し律法を行はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, '我汝らに遣し切に遣せし我僕なる預言者の言を聽ずば(汝らは之をきかざりき)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, '我この室をシロの如くになし又この邑を地の萬國に詛はるる者となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, '祭司と預言者及び民みなヱレミヤがヱホバの室に立てこの言をのぶるをきけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'ヱレミヤ、ヱホバに命ぜられし諸の言を民に告畢りしとき祭司と預言者および諸の民彼を執へいひけるは汝は必ず死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, '汝何故にヱホバの名をもて預言し此室はシロの如くになりこの邑は荒蕪となりて住む者なきにいたらんと云しやと民みなヱホバの室にあつまりてヱレミヤを攻む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'ユダの牧伯等この事をききて王の家をいでヱホバの室にのぼりてヱホバの家の新しき門の入口に坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, '祭司と預言者等牧伯等とすべての民に訴ていふ此人は死にあたる者なり是は汝らが耳に聽しごとくこの邑にむかひて惡き預言をなしたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, '是に於てヱレミヤ牧伯等とすべての民にいひけるはヱホバ我を遣し汝らが聽る諸の言をもて此宮とこの邑にむかひて預言せしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, '故に汝らいま汝らの途と行爲をあらためて汝らの神ヱホバの聲にしたがへ然ばヱホバ汝らに災を降さんとせしことを悔たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'みよ我は汝らの手にあり汝らの目に善とみゆるところ義とみゆることを我に行へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, '然ど汝ら善くこれを知れ汝らもし我を殺さば必ず無辜ものの血なんぢらの身とこの邑と其中に住る者に歸せんヱホバ我を遣してこの諸の言を汝らの耳につげしめたまひしなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, '牧伯等とすべての民すなはち祭司と預言者にいひけるは此人は死にあたる者にあらず是は我らの神ヱホバの名によりて我儕に語りしなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, '時にこの地の長老數人立て民のすべての集れる者につげていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'ユダの王ヒゼキヤの代にモレシテ人ミカ、ユダの民に預言して云けらく萬軍のヱホバかくいひ給ふシオンは田地のごとく耕されヱルサレムは邱墟となり此室の山は樹深き崇邱とならんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'ユダの王ヒゼキヤとすべてのユダ人は彼を殺さんとせしことありしやヒゼキヤ、ヱホバを畏れヱホバに求ければヱホバ彼らに降さんと告給ひし災を悔給ひしにあらずや我儕かく爲すは自己の靈魂をそこなふ大なる惡をなすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, '又前にヱホバの名をもて預言せし人あり即ちキリヤテヤリムのシマヤの子ウリヤなり彼ヱレミヤの凡ていへるごとく此邑とこの地にむかひて預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'ヱホヤキム王と其すべての勇士とすべての牧伯等その言を聽り是において王彼を殺さんと欲ひしがウリヤこれをきき懼てエジプトに逃ゆきしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'ヱホヤキム王人をエジプトに遣せり即ちアクボルの子エルナタンに數人をそへてエジプトにつかはしければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, '彼らウリヤをエジプトより引出しヱホヤキム王の許に携きたりしに王劍をもて之を殺し其屍骸を賤者の墓に棄させたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, '時にシヤパンの子アヒカム、ヱレミヤをたすけこれを民の手にわたして殺さざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'ユダの王ヨシヤの子ヱホヤキムが位に即し初のころヱホバより此言ヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'すなはちヱホバかく我に云たまへり汝索と軛をつくりて汝の項に置き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, '之をヱルサレムにきたりてゼデキヤ王にいたるところの使臣等の手によりてエドムの王モアブの王アンモン人の王ツロの王シドンの王に送るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, '汝彼らに命じて其主にいはしめよ萬軍のヱホバ、イスラエルの神かくいひたまふ汝ら其主にかく告べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'われ我大なる能力と伸たる臂をもて地と地の上にをる人と獸とをつくり我心のままに地を人にあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'いま我この諸の地を我僕なるバビロンの王ネブカデネザルの手にあたへ又野の獸を彼にあたへてかれにつかへしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'かれの地の時期いたるまで萬國民は彼と其子とその孫につかへん其時いたらばおほくの國と大なる王は彼を己に事へしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'バビロンの王ネブカデネザルに事へずバビロンの王の軛をその項に負ざる國と民は我彼の手をもて悉くこれを滅すまで劍と饑饉と疫病をもてこれを罰せんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, '故に汝らの預言者なんぢらの占筮師汝らの夢みる者汝らの法術士汝らの魔法士汝らに告て汝らはバビロンの王に事ふることあらじといふとも聽なかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, '彼らは謊を汝らに預言して汝らをその國より遠く離れしめ且我をして汝らを逐しめ汝らを滅さしむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, '然どバビロンの王の軛をその項に負ふて彼に事ふる國々の人は我これをその故土に存し其處に耕し住しむべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, '我この諸の言のごとくユダの王ゼデキヤに告ていひけるは汝らバビロンの王の軛を汝らの項に負ふて彼と其民につかへよ然ば生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, '汝と汝の民なんぞヱホバがバビロンの王につかへざる國につきていひたまひし如く劍と饑饉と疫病に死ぬべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, '故に汝らはバビロンの王に事ふることあらじと汝等に告る預言者の言を聽なかれ彼らは謊を汝らに預言するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'ヱホバいひたまひけるは我彼らを遣さざるに彼らは我名をもて謊を預言す是をもて我汝らを逐はなち汝らと汝らに預言する預言者等を滅すにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, '我また祭司とこのすべての民に語りていひけるはヱホバかくいひたまふ視よヱホバの室の器皿いま速にバビロンより持歸さるべしと汝らに預言する預言者の言をきく勿れそは彼ら謊を汝らに預言すればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, '汝ら彼らに聽なかれバビロンの王に事へよ然ば生べしこの邑を何ぞ荒蕪となすべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'もし彼ら預言者にしてヱホバの言かれらの衷にあらばヱホバの室とユダの王の家とヱルサレムとに餘れるところの器皿のバビロンに移されざることを萬軍のヱホバに求むべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, '萬軍のヱホバ柱と海と臺およびこの邑に餘れる器皿につきてかくいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, '是はバビロンの王ネブカデネザルがユダの王ヱホヤキムの子ヱコニヤおよびユダとヱルサレムのすべての牧伯等をヱルサレムよりバビロンにとらへ移せしときに掠ざりし器皿なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'すなはち萬軍のヱホバ、イスラエルの神ヱホバの室とユダの王の室とヱルサレムとに餘れる器皿につきてかくいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'これらはバビロンに携へゆかれ我これを顧る日まで彼處にあらん其後我これを此處にたづさへ歸らしめんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'この年すなはちユダの王ゼデキヤが位に即し初その四年の五月ギベオンのアズルの子なる預言者ハナニヤ、ヱホバの室にて祭司と凡の民の前にて我に語りいひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '萬軍のヱホバ、イスラエルの神かくいひたまふ我バビロンの王の軛を摧けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, '二年の内にバビロンの王ネブカデネザルがこの處より取てバビロンに携へゆきしヱホバの室の器皿を再び悉くこの處に歸らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, '我またユダの王ヱホヤキムの子ヱコニヤおよびバビロンに住しユダのすべての擄人をこの處に歸らしめんそは我バビロンの王の軛を摧くべければなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, '是に於て預言者ヱレミヤ、ヱホバの家に立る祭司の前とすべての民の前にて預言者ハナニヤと語ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, '預言者ヱレミヤすなはちいひけるはアーメン願くはヱホバかくなし給へ願くはバビロンに携へゆかれしヱホバの室の器皿及びすべて虜へうつされし者をヱホバ、バビロンより復びこの處に歸らしめたまはんと汝の預言せし言の成らんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, '然ど汝いま我なんぢの耳と諸の民の耳に語らんとする此言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, '我と汝の先にいでし預言者は古昔より多くの地と大なる國につきて戰鬪と災難と疫病の事を預言せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, '泰平を預言するところの預言者は若しその預言者の言とげなばその誠にヱホバの遣したまへる者なること知らるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'ここに於て預言者ハナニヤ預言者ヱレミヤの項より軛を取てこれを摧けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'ハナニヤ諸の民の前にて語りヱホバかくいひたまふわれ二年のうちに是の如く萬國民の項よりバビロン王ネブカデネザルの軛を摧きはなさんといふ預言者ヱレミヤ遂に去りぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, '預言者ハナニヤ預言者ヱレミヤの項より軛を摧きはなせし後ヱホバの言ヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '汝ゆきてハナニヤにヱホバかくいふと告よ汝木の軛を摧きたれども之に代て鐵の軛を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, '萬軍のヱホバ、イスラエルの神かくいふ我鐵の軛をこの萬國民の項に置きてバビロンの王ネブカデネザルに事へしむ彼ら之につかへんわれ野の獸をもこれに與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'また預言者ヱレミヤ預言者ハナニヤにいひけるはハナニヤよ請ふ聽けヱホバ汝を遣はし給はず汝はこの民に謊を信ぜしむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, '是故にヱホバいひ給ふ我汝を地の面よりのぞかん汝ヱホバに叛くことを敎ふるによりて今年死ぬべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, '預言者ハナニヤはこの年の七月死ねり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, '預言者ヱレミヤ、ヱルサレムより書をかの擄へうつされて餘れるところの長老および祭司と預言者ならびにネブカデネザルがヱルサレムよりバビロンに移したるすべての民に送れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '是より先ヱコニヤ王と王后と寺人およびユダとヱルサレムの牧伯等および木匠と鐵匠はヱルサレムをされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'ヱレミヤその書をシヤパンの子エラサおよびヒルキヤの子ゲマリヤ即ちユダの王ゼデキヤがバビロンにつかはしてバビロンの王ネブカデネザルにいたらしむる者の手によりて送れり其書にいはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '萬軍のヱホバ、イスラエルの神すべて擄うつされし者即ち我ヱルサレムよりバビロンに移さしめし者にかくいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, '汝ら屋を建てこれに住ひ圃をつくりてその果をくらへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, '妻を娶て子女をうみ又汝らの子に媳を娶り汝らの女を嫁がしめ彼らに子女を生しめよ此は汝等かしこに減ずして增んがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, '我汝らを擄移さしめしところの邑の安を求めこれが爲にヱホバにいのれその邑の安によりて汝らもまた安をうればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, '萬軍のヱホバ、イスラエルの神かくいひたまふ汝らの中の預言者と卜筮士に惑はさるる勿れまた汝ら自ら作りしところの夢に聽したがふ勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'そは彼ら我名をもて謊を汝らに預言すればなり我彼らを遣さずヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'ヱホバかくいひたまふバビロンに於て七十年滿なばわれ汝らを眷み我嘉言を汝らになして汝らをこの處に歸らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'ヱホバいひたまふ我が汝らにむかひて懷くところの念は我これを知るすなはち災をあたへんとにあらず平安を與へんとおもひ又汝らに後と望をあたへんとおもふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, '汝らわれに龥はり往て我にいのらん我汝らに聽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, '汝らもし一心をもて我を索めなば我に尋ね遇はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'ヱホバいひたまふ我汝らの遇ところとならんわれ汝らの俘擄を解き汝らを萬國よりすべて我汝らを逐やりし處より集め且我汝らをして擄らはれて離れしめしその處に汝らをひき歸らんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'ヱホバわれらの爲にバビロンに於て預言者を立たまひしと汝らはいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'ダビデの位に坐する王とこの邑に住るすべての民汝らと偕にとらへ移されざりし兄弟につきてヱホバかくいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, '萬軍のヱホバかくいふ視よわれ劍と饑饉と疫病を彼らにおくり彼らを惡くして食はれざる惡き無花果のごとくになさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'われ劍と饑饉と疫病をもて彼らを逐ひまた彼らを地の萬國にわたして虐にあはしめ我彼らを逐やる諸國に於て呪詛となり詫異となり人の嗤笑となり恥辱とならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, '是彼ら我言を聽ざればなりとヱホバいひたまふ我この言を我僕なる預言者によりて遣り頻におくれども汝ら聽ざるなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'わがヱルサレムよりバビロンにおくりし諸の俘擄人よ汝らヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, '我名をもて謊を汝らに預言するコラヤの子アハブとマアセヤの子ゼデキヤにつきて萬軍のヱホバ、イスラエルの神かくいふ視よわれ彼らをバビロンの王ネブカデネザルの手に付さん彼これを汝らの目の前に殺すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'バビロンにあるユダの俘擄人は皆彼らをもて詛となし願くはヱホバ汝をバビロンの王が火にて焚しゼデキヤとアハブのごとき者となしたまはん事をといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'こは彼らイスラエルの中に惡をなし鄰の妻を犯し且我彼らに命ぜざる謊の言をわが名をもて語りしによる我これを知りまた證すとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, '汝ネヘラミ人シマヤにかく語りいふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, '萬軍のヱホバ、イスラエルの神かくいふ汝おのれの名をもて書をヱルサレムにある諸の民と祭司マアセヤの子ゼパニヤおよび諸の祭司に送りていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'ヱホバ汝を祭司ヱホヤダに代て祭司となし汝らをヱホバの室の監督となしたまふ此すべて狂妄ひ且みづから預言者なりといふ者を獄と桎梏につながしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, '然るに汝いま何故に汝らにむかひてみづから預言者なりといふところのアナトテのヱレミヤを斥責めざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'そは彼バビロンにをる我儕に書を送り時尚長ければ汝ら家を建て之に住ひ圃をつくりてその實をくらへといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, '祭司ゼパニヤこの書を預言者ヱレミヤに讀きかせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, '時にヱホバの言ヱレミヤにのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '諸の俘擄人に書をおくりて云べしネヘラミ人シマヤの事につきてヱホバかくいふ我シマヤを遣さざるに彼汝らに預言し汝らに謊を信ぜしめしによりて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'ヱホバかくいふ視よ我ネヘラミ人シマヤと其子孫を罰すべし彼ヱホバに逆くことを敎へしによりて此民のうちに彼に屬する者一人も住ふことなからん且我民に吾がなさんとする善事をみざるべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'ヱホバよりヱレミヤにのぞめる言いふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'イスラエルの神ヱホバかく告ていふ我汝に言し言をことごとく書に錄せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'ヱホバいふわれ我民イスラエルとユダの俘囚人を返す日きたらんヱホバこれをいふ我彼らをその先祖にあたへし地にかへらしめん彼らは之をたもたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'ヱホバのイスラエルとユダにつきていひたまひし言は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'ヱホバかくいふ我ら戰慄の聲をきく驚懼あり平安あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, '汝ら子を產む男あるやを尋ね觀よ我男が皆子を產む婦のごとく手をその腰におき且その面色皆靑く變るをみるこは何故ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, '哀しいかなその日は大にして之に擬ふべき日なし此はヤコブの患難の時なり然ど彼はこれより救出されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, '萬軍のヱホバいふ其日我なんぢの項よりその軛をくだきはなし汝の繩目をとかん異邦人は復彼を使役はざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, '彼らは其神ヱホバと我彼らの爲に立んところの其王ダビデにつかふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'ヱホバいふ我僕ヤコブよ懼るる勿れイスラエルよ驚く勿れ我汝を遠方より救ひかへし汝の子孫を其とらへ移されし地より救ひかへさんヤコブは歸りて平穩と寧靜をえん彼を畏れしむる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'ヱホバいふ我汝と偕にありて汝を救はん設令われ汝を散せし國々を悉く滅しつくすとも汝をば滅しつくさじされど我道をもて汝を懲さん汝を全たく罰せずにはおかざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'ヱホバかくいふ汝の創は愈ず汝の傷は重し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, '汝の訟を理す者なく汝の創を裹む膏藥あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, '汝の愛する者は皆汝を忘れて汝を求めず是汝の愆の多きと罪の數多なるによりて我仇敵の撃がごとく汝を撃ち嚴く汝を懲せばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, '何ぞ汝の創のために叫ぶや汝の患は愈ることなし汝の愆の多きと罪の數多なるによりて我これを汝になすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, '然どすべて汝を食ふ者は食はれすべて汝を虐ぐる者は皆とらはれ汝を掠むる者は掠められん凡て汝の物を奪ふ者は我これをして奪はるる事にあはしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'ヱホバいふ我汝に膏藥を貼り汝の傷を醫さんそは人汝を棄られし者とよび尋る者なきシオンといへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'ヱホバかくいふ視よわれかの擄移されたるヤコブの天幕をかへし其住居をあはれまん斯邑はその故の丘垤に建られん城には宜き樣に人住はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, '感謝と歡樂者の聲とその中よりいでん我かれらを增ん彼ら少からじ我彼らを崇せん彼ら藐められじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, '其子は疇昔のごとくあらん其集會は我前に固く立ん凡かれを虐ぐる者は我これを罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, '其首領は本族よりいで其督者はその中よりいでん我彼をちかづけ彼に近かん誰かその生命を繋て我に近くものあらんやとヱホバいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, '汝等は我民となり我は汝らの神とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'みよヱホバの暴風あり怒と旋轉風いでて惡人の首をうたん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'ヱホバの烈き忿はかれがその心の思を行ひてこれを遂るまでは息じ末の日に汝ら明にこれを曉らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'ヱホバいひたまふ其時われはイスラエルの諸の族の神となり彼らは我民とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'ヱホバかくいひたまふ劍をのがれて遺りし民は曠野の中に恩を獲たりわれ往て彼イスラエルに安息をあたへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, '遠方よりヱホバ我に顯れていひたまふ我窮なき愛をもて汝を愛せり故にわれたえず汝をめぐむなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'イスラエルの童女よわれ復び汝を建ん汝は建らるべし汝ふたたび鼗をもて身を飾り歡樂者の舞にいでん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, '汝また葡萄の樹をサマリヤの山に植ん植る者は植てその果を食ふことをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'エフライムの山の上に守望者の立て呼はる日きたらんいはく汝ら起よ我らシオンにのぼりて我儕の神ヱホバにまうでんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'ヱホバかくいひたまふ汝らヤコブの爲に歡びて呼はり萬國の首なる者のために叫べ汝ら示し且歌ひて言へヱホバよ願くはイスラエルの遺れる者汝の民を救ひたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'みよ我彼らを北の地よりひきかへり彼らを地の極より集めん彼らの中には瞽者 跛者 孕める婦 子を產みし婦ともに居る彼らは大なる群をなして此處にかへらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, '彼ら悲泣來らん我かれらをして祈禱をもて來らしめ直くして蹶かざる途より水の流に歩みいたらしめん我はイスラエルの父にしてエフライムは我長子なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, '萬國の民よ汝らヱホバの言をきき之を遠き諸島に示していえへイスラエルを散せしものこれを聚め牧者のその群を守るが如く之を守らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'すなはちヱホバ、ヤコブを贖ひ彼等よりも強き者の手よりかれを救出したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, '彼らは來てシオンの頂によばはりヱホバの賜ひし福なる麥と酒と油および若き羊と牛の爲に寄集はんその靈魂は灌ふ園のごとくならん彼らは重て愁ふること無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'その時童女は舞てたのしみ壯者と老者もろともに樂しまん我かれらの悲をかへて喜となしかれらの愁をさりてこれを慰さめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'われ膏をもて祭司の心を飫しめ我恩をもて我民に滿しめんとヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'ヱホバかくいひたまふ歎き悲みいたく憂ふる聲ラマに聞ゆラケルその兒子のために歎きその兒子のあらずなりしによりて慰をえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'ヱホバかくいひ給ふ汝の聲を禁て哭こと勿れ汝の目を禁て涙を流すこと勿れ汝の工に報あるべし彼らは其敵の地より歸らんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, '汝の後の日に望あり兒子等その境に歸らんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'われ固にエフライムのみづから歎くをきけり云く汝は我を懲しめたまふ我は軛に馴ざる犢のごとくに懲治を受たりヱホバよ汝はわが神なれば我を牽轉したまへ然ば我轉るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'われ轉りし後に悔い敎を承しのちに我髀を撃つ我幼時の羞を身にもてば恥ぢかつ辱しめらるるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'ヱホバいひたまふエフライムは我愛するところの子悦ぶところの子ならずや我彼にむかひてかたるごとに彼を念はざるを得ず是をもて我膓かれの爲に痛む我必ず彼を恤むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, '汝のために指路號を置き汝のために柱をたてよ汝のゆける道なる大路に心をとめよイスラエルの童女よ歸れこの汝の邑々にかへれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, '違ける女よ汝いつまで流蕩ふやヱホバ新しき事を地に創造らん女は男を抱くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, '萬軍のヱホバ、イスラエルの神かくいひ給ふ我かの俘囚し者を返さん時人々復ユダの地とその邑々に於て此言をいはん義き居所よ聖き山よ願くはヱホバ汝を祝みたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'ユダとその諸の邑々に農夫と群を牧ふもの偕に住はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'われ疲れたる靈魂を飫しめすべての憂ふる靈魂をなぐさむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, '茲にわれ目を醒しみるに我眠は甘かりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'ヱホバいひたまふ視よ我が人の種と畜の種とをイスラエルの家とユダの家とに播く日いたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, '我彼らを拔き毀ち覆し滅し難さんとうかがひし如くまた彼らを建て植ゑんとうかがふべしとヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'その時彼らは父が酸き葡萄を食ひしによりて兒子の齒齪くと再びいはざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, '人はおのおの自己の惡によりて死なん凡そ酸き葡萄をくらふ人はその齒齪く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'ヱホバいひたまふみよ我イスラエルの家とユダの家とに新しき契約を立つる日きたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'この契約は我彼らの先祖の手をとりてエジプトの地よりこれを導きいだせし日に立しところの如きにあらず我かれらを娶りたれども彼らはその我契約を破れりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, '然どかの日の後に我イスラエルの家に立んところの契約は此なり即ちわれ我律法をかれらの衷におきその心の上に錄さん我は彼らの神となり彼らは我民となるべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, '人おのおの其隣とその兄弟に敎へて汝ヱホバを識と復いはじそは小より大にいたるまで悉く我をしるべければなりとヱホバいひたまふ我彼らの不義を赦しその罪をまた思はざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'ヱホバかく言すなはち是日をあたへて晝の光となし月と星をさだめて夜の光となし海を激してその濤を鳴しむる者その名は萬軍のヱホバと言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'ヱホバいひたまふもし此等の規律我前に廢らばイスラエルの子孫も我前に廢りて永遠も民たることを得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'ヱホバかくいひたまふ若し上の天量ることを得下の地の基探ることをえば我またイスラエルのすべての子孫を其もろもろの行のために棄べしヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'ヱホバいひたまふ視よ此邑ハナネルの塔より隅の門までヱホバの爲に建つ日きたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, '量繩ふたたび直ちにガレブの岡をこえゴアテの方に轉るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, '屍と灰の谷またケデロンの溪にいたるまでと東の方の馬の門の隅にいたるまでの諸の田地皆ヱホバの聖き處となり永遠におよぶまで再び拔れまた覆さるる事なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'ユダの王ゼデキヤの十年即ちネブカデネザルの十八年の頃ヱホバの言ヱレミヤにのぞめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'その時バビロンの軍勢ヱルサレムを攻環み居て預言者ヱレミヤはユダの王の室にある獄の庭の内に禁錮られたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'ユダの王ゼデキヤ彼を禁錮ていひけるは汝何故に預言してヱホバかく云たまふといふや云く視よ我この邑をバビロン王の手に付さん彼之を取るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'またユダの王ゼデキヤはカルデヤ人の手より脱れず必ずバビロン王の手に付され口と口とあひ語り目と目あひ觀るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, '彼ゼデキヤをバビロンに携きゆかんゼデキヤはわが彼を顧る時まで彼處に居んとヱホバいひたまふ汝らカルデヤ人と戰ふとも勝ことを得じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'ヱレミヤいふヱホバの言われに臨みていはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'みよ汝の叔父シヤルムの子ハナメル汝にきたりていはん汝アナトテに在るわが田地を買へそは之を贖ふ事は汝の分なればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'かくてヱホバの言のごとく我叔父の子ハナメル獄の庭にて我に來り云けるは願くは汝ベニヤミンの地のアナトテに在るわが田地を買へそは之を嗣ぎこれを贖ふことは汝の分なれば汝みつからこれを買ひとれとここに於てわれ此はヱホバの言なりと知りたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, '我叔父の子ハナメルがアナトテにもてる田地をかひて彼に銀十七シケルを稱てあたふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'すなはち我その契劵を書てこれに封印し證人をたて權衡をもて銀を稱て與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, '而してわれその約定をのするところの封印せし買劵とその開きたるものを取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'わが叔父の子ハナメルと買劵に印せし證人の前および獄の庭に坐するユダ人の前にてその買劵をマアセヤの子なるネリヤの子バルクに與へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, '彼らの前にてわれバルクに命じていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '萬軍のヱホバ、イスラエルの神かく云たまふ汝これらの契劵すなはち此買劵の封印せし者と開きたるものを取り之を瓦器の中に貯へて多くの日の間保たしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, '萬軍のヱホバ、イスラエルの神かくいひたまふそは此地に於て人復屋と田地と葡萄園を買ふにいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'われ買契をネリヤの子バルクに付せしのちヱホバに祈りて云ひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '嗚呼主ヱホバよ汝はその大なる能力と伸たる腕をもて天と地を造りたまへり汝には爲す能はざるところなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, '汝は恩寵を千萬人に施し又父の罪をその後の子孫の懷に報いたまふ汝は大なる全能の神にいまして其名は萬軍のヱホバとまうすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, '汝の謀略は大なり汝は事をなすに能あり汝の目は人のこどもらの諸の途を鑒はしおのおのの行に循ひその行爲の果によりて之に報いたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, '汝休徴と奇跡をエジプトの地に行ひたまひて今日にまでいたるまたイスラエルと他の民の中にも然りかくして今日のごとくに汝の名を揚たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, '汝は休徴と奇跡と強き手と伸たる腕と大なる怖しき事をもて汝の民イスラエルをエジプトの地より導きいだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'この地を彼らにたまへり是即ち汝がかれらの先祖等に與へんと誓ひたまひし乳と蜜の流るる地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, '彼等すなはち入てこれを獲たりしかども汝の聲に遵はず汝の例典を行はず凡て汝がなせと命じたまひし事を爲ざりしによりて汝この災を其上にくだらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'みよ壘成れり是この邑を取んとて來れるなり劍と饑饉と疫病のためにこの邑は之を攻むるカルデヤ人の手に付さる汝のいひたまひしことば旣に成れり汝之を見たまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, '主ヱホバよ汝われに銀をもて田地を買へ證人を立よといひたまへり然るにこの邑はカルデヤ人の手に付さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, '時にヱホバの言ヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'みよ我はヱホバなりすべて血氣ある者の神なり我に爲す能はざるところあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, '故にヱホバかくいふ視よわれ此邑をカルデヤ人の手とバビロンの王ネブカデネザルの手に付さん彼これを取るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'この邑を攻るところのカルデヤ人きたり火をこの邑に放ちて之を焚ん屋蓋のうへにて人がバアルに香を焚き他の神に酒をそそぎて我を怒らせしその屋をも彼ら亦焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'そはイスラエルの子孫とユダの子孫はその幼少時よりわが前に惡き事のみをなしまたイスラエルの民はその手の作爲をもて我をいからする事のみをなしたればなりヱホバ之をいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, '此邑はその建し日より今日にいたるまで我震怒を惹き我憤恨をおこすところの者なれば我前よりわれ之を除かんとするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'こはイスラエルの民とユダの民諸の惡を行ひて我を怒らせしによりてなり彼らその王等その牧伯等その祭司その預言者およびユダの人々とヱルサレムに住る者皆然なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, '彼ら背を我にむけて面を我にむけずわれ彼らををしへ頻に敎ふれどもかれらは敎をきかずしてうけざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, '彼らは憎むべき物をわが名をもて稱へらるる室にたてて之を汚し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, '又ベンヒンノムの谷にあるバアルの崇邱を築きその子女をモロクに献げたりわれは彼らにこの憎むべきことを行ひてユダに罪を犯さしむることを命ぜず斯る事は我心におこらざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'いまイスラエルの神ヱホバこの邑すなはち汝らが劍と饑饉と疫病のためにバビロン王の手に付されんといひしところの邑につきて斯いひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'みよわれ我震怒と憤恨と大なる怒をもて彼らを逐やりし諸の國より彼らを集め此處に導きかへりて安然に居らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, '彼らは我民となり我は彼らの神とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'われ彼らに一の心と一の途をあたへて常に我を畏れしめんこは彼らと其子孫とに福をえせしめん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'われ彼らを棄ずして恩を施すべしといふ永遠の契約をかれらにたて我を畏るるの畏をかれらの心におきて我を離れざらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'われ悦びて彼らに恩を施し心を盡し精神をつくして誠に彼らを此地に植べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'ヱホバかくいひたまふわれ此諸の大なる災をこの民に降せしごとくわがかれらに言し諸の福を彼等に降さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, '人衆この地に田野を買はん是汝等が荒て人も畜もなきにいたりカルデヤ人の手に付されしといへる地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, '人衆ベニヤミンの地とヱルサレムの四周とユダの邑々と山の邑々と平地の邑々と南の方の邑々において銀をもて田野をかひ契劵を書きてこれに封印し又證人をたてんそは我かの俘囚者を歸らしむればなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'ヱレミヤ尚獄の庭に禁錮られてをる時ヱホバの言ふたたび彼に臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '事をおこなふヱホバ事をなして之を成就るヱホバ其名をヱホバと名る者かく言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, '汝我に龢求めよわれ汝に應へん又汝が知ざる大なる事と秘密たる事とを汝に示さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'イスラエルの神ヱホバ壘と劍によりて毀たれたる此邑の室とユダの王の室につきてかくいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, '彼らカルデヤ人と戰はんとて來る是には我震怒と憤恨をもて殺すところの人々の屍體充るにいたらん我かれらの諸の惡のためにわが面をこの邑に蔽ひかくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, '視よわれ卷布と良藥をこれに持きたりて人々を醫し平康と眞實の豐厚なるをこれに示さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, '我ユダの俘囚人とイスラエルの俘囚人を歸らしめ彼らを建て從前のごとくになすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'われ彼らが我にむかひて犯せし一切の罪を潔め彼らが我にむかひて犯し且行ひし一切の罪を赦さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, '此邑は地のもろもろの民の中において我がために欣喜の名となり頌美となり榮耀となるべし彼等はわが此民にほどこすところの諸の恩惠を聞ん而してわがこの邑にほどこすところの諸の恩惠と諸の福祿のために發振へ且身を動搖さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'ヱホバかくいひ給へり汝らが荒れて人もなく畜もなしといひしこの處即ち荒れて人もなく住む者もなく畜もなきユダの邑とヱルサレムの街に');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, '再び欣喜の聲 歡樂の聲 新娶者の聲 新婦の聲および萬軍のヱホバをあがめよヱホバは善にしてその矜恤は窮なしといひて其感謝の祭物をヱホバの室に携ふる者の聲聞ゆべし蓋われこの地の俘囚人を返らしめて初のごとくになすべければなりヱホバ之をいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, '萬軍のヱホバかくいひたまふ荒れて人もなく畜もなきこの處と其すべての邑々に再び牧者のその群を伏しむる牧場あるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, '山の邑と平地の邑と南の方の邑とベニヤミンの地とヱルサレムの四周とユダの邑において群ふたたびその之を核ふる者の手の下を過らんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'ヱホバ言たまはく視よ我イスラエルの家とユダの家に語りし善言を成就ぐる日きたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'その日その時にいたらばわれダビデの爲に一の義き枝を生ぜしめん彼は公道と公義を地に行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'その日ユダは救をえヱルサレムは安らかに居らんその名はヱホバ我儕の義と稱へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'ヱホバかくいひたまふイスラエルの家の位に坐する人ダビデに缺ることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'また我前に燔祭をささげ素祭を燃し恒に犠牲を献ぐる人レビ人なる祭司に絕ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'ヱホバのことばヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'ヱホバかくいふ汝らもし我晝につきての契約と我夜につきての契約を破りてその時々に晝も夜もなからしむることをえば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, '僕ダビデに吾が立し契約もまた破れその子はかれの位に坐して王となることをえざらんまたわが我に事ふるレビ人なる祭司に立し契約も破れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, '天の星は數へられず濱の沙は量られずわれその如く我僕ダビデの裔と我に事ふるレビ人を增ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'ヱホバの言またヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '汝この民の語りてヱホバはその選みし二の族を棄たりといふを聞ざるか彼らはかく我民を藐じてその眼にこれを國と見なさざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'ヱホバかくいひ給ふもしわれ晝と夜とについての契約を立ずまた天地の律法を定めずば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'われヤコブと我僕ダビデとの裔をすてて再びかれの裔の中よりアブラハム、イサク、ヤコブの裔を治むる者を取ざるべし我その俘囚し者を返らしめこれを恤れむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'バビロンの王ネブカデネザルその全軍および己の手の下に屬するところの地の列國の人および諸の民を率てヱルサレムとその諸邑を攻めて戰ふ時ヱホバの言ヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'イスラエルの神ヱホバかくいふ汝ゆきてユダの王ゼデキヤに告ていふべしヱホバかくいひたまふ視よわれ此邑をバビロン王の手に付さん彼火をもてこれを焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, '汝はその手を脱れず必ず擒へられてこれが手に付されん汝の目はバビロン王の目をみ又かれの口は汝の口と語ふべし汝はバビロンにゆくにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, '然どユダの王ゼデキヤよヱホバの言をきけヱホバ汝の事につきてかくいひたまふ汝は劍に死じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, '汝は安らかに死なん民は汝の先祖たる汝の先の王等の爲に香を焚しごとく汝のためにも香を焚き且汝のために嘆て嗚呼主よといはん我この言をいふとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, '預言者エレミヤすなはち此言をことごとくヱルサレムにてユダの王ゼデキヤにつげたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, '時にバビロン王の軍勢はヱルサレムおよび存れるユダの諸の邑を攻めラキシとアゼカを攻て戰ひをる其はユダの諸邑のうちに是等の城の邑尚存りゐたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'ゼデキヤ王ヱルサレムに居る諸の民と契約を立てて彼らに釋放の事を宣示せし後ヱホバの言ヱレミヤに臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'その契約はすなはち人をしておのおの其僕婢なるヘブルの男女を釋たしめその兄弟なるユダヤ人を奴隸となさざらしむる者なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'この契約をなせし牧伯等とすべての民は人おのおのその僕婢を釋ちて再び之を奴隸となすべからずといふをききて遂にそれに聽したがひてこれを釋ちしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, '後に心をひるがへしてその釋ちし僕婢をひきかへりて再び之を伏從はしめて僕婢となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, '是故にヱホバの言ヱホバよりヱレミヤにのぞみて云');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'イスラエルの神ヱホバかくいふ我汝らの先祖をエジプトの地その奴隸たりし宅より導きいだせし時彼らと契約を立ていひけらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, '汝らの兄弟なるヘブル人の身を汝らに賣たる者をば七年の終に汝らおのおのこれを釋つべし彼六年汝につかへたらば之を釋つべしと然るに汝らの先祖等は我に聽ず亦その耳を傾けざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, '然ど汝らは今日心をあらためておのおの其鄰人に釋放の事を示してわが目に正とみゆる事を行ひ且我名をもて稱へらるる室に於て我前に契約を立たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, '然るに汝ら再び心をひるがへして我名を汚し各自釋ちて其心に任せしめたる僕婢をひき歸り再び之を伏從はしめて汝らの僕婢となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'この故にヱホバかくいひたまふ汝ら我に聽ておのおの其兄弟とその鄰に釋放の事を示さざりしによりて視よわれ汝らの爲に釋放を示して汝らを劍と饑饉と疫病にわたさん我汝らをして地の諸の國にて艱難をうけしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'ヱホバこれを云ふ犢を兩にさきて其二個の間を過り我前に契約をたてて却つて其言に從はずわが契約をやぶる人々');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, '即ち兩に分ちし犢の間を過りしユダの牧伯等ヱルサレムの牧伯等と寺人と祭司とこの地のすべての民を');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'われ其敵の手とその生命を索る者の手に付さんその屍體は天空の鳥と野の獸の食物となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, '且われユダの王ゼデキヤとその牧伯等をその敵の手其生命を索むる者の手汝らを離れて去しバビロン王の軍勢の手に付さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'ヱホバいひたまふ視よ我彼らに命じて此邑に歸らしめん彼らこの邑を攻て戰ひ之を取り火をもて焚くべしわれユダの諸邑を住人なき荒地となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'ユダの王ヨシヤの子ヱホヤキムの時ヱレミヤにのぞみしヱホバの言いふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '汝レカブ人の家に往て彼らとかたり彼らをヱホバの室の一房に携きたりて酒をのませよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, '是に於てわれハバジニヤの子なるヱレミヤの子ヤザニヤとその兄弟とその諸子およびレカブ人の全家を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'これをヱホバの室にあるハナンの諸子の房につれきたれりハナンはイグダリヤの子にして神の人なり其房は牧伯等の房の次にして門を守るシヤレムの子マアセヤの房のうへに在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, '我すなはちレカブ人の家の諸子の前に酒を滿したる壺と杯を置き彼らに告て汝ら酒を飮めといひければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, '彼らこたへけるは我儕は酒をのまず蓋レカブの子なる我らの先祖ヨナダブ我らに命じて汝等と汝らの子孫はいつまでも酒をのむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'また汝ら屋を建ず種をまかず葡萄園を植ざれ亦これを有べからず汝らの生存ふるあひだ幕屋にをれ然らば汝らが寄寓ところの地に於て汝らの生命長からんと云たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, '斯我らはレカブの子なるわれらの先祖ヨナダブの凡て命ぜし言に遵ひて我儕とわれらの妻と子女は生存ふるあひだ酒を飮ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, '我らは住べき屋を建てず葡萄園も田野も種も有ずして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, '幕屋にをりすべて我儕の先祖ヨナダブが我らに命ぜしごとく行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, '然どバビロンの王ネブカデネザルがこの地に上り來りしとき我ら云けるは我らカルデヤ人の軍勢とスリア人の軍勢を畏るれば去來ヱルサレムにゆかんとすなはち我らはヱルサレムに住へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, '時にヱホバの言ヱレミヤにのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '萬軍のヱホバ、イスラエルの神かくいふ汝ゆきてユダの人々とヱルサレムに住る者とに告よヱホバいひたまふ汝らは我言を聽て敎を受ざるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'レカブの子ヨナダブがその子孫に酒をのむべからずと命ぜし言は行はる彼らは今日に至るまで酒をのまず其先祖の命令に遵ふなり然るに汝らは吾汝らに語り頻りに語れども我にきかざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, '我また我僕なる預言者たちを汝らに遣し頻りにこれを遣していはせけるは汝らいまおのおの其惡き道を離れて歸り汝らの行をあらためよ他の神に從ひて之に奉ふる勿れ然ば汝らはわが汝らと汝らの先祖に與へたるこの地に住ことをえんと然ど汝らは耳を傾けず我にきかざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'レカブの子ヨナダブの子孫はその先祖が彼らに命ぜしところの命令に遵ふなり然ど此民は我に聽ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'この故に萬軍の神ヱホバ、イスラエルの神かくいふ視よわれユダとヱルサレムに住る者とに我彼らにつきていひし所の災を降さん我かれらに語れども聽ずかれらを召ども應へざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, '茲にヱレミヤ、レカブ人の家にいひけるは萬軍のヱホバ、イスラエルの神かくいひたまふ汝らはその先祖ヨナダブの命に遵ひその凡の誡を守り彼が汝らに命ぜしことを行ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, '是によりて萬軍のヱホバ、イスラエルの神かくいひたまふレカブの子ヨナダブには我前に立つ人いつまでも缺ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'ユダの王ヨシヤの子ヱホヤキムの四年にこの言ヱホバよりヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '汝卷物をとり我汝に語りし日即ちヨシヤの日より今日に至るまでイスラエルとユダと萬國とにつきてわが汝に語りしすべての言を之に錄せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'ユダの家わが降さんと擬るところの災をききて各自その惡き途をはなれて轉ることもあらん然ばわれ其愆とその罪を赦すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, '是に於てヱレミヤ、ネリヤの子バルクを召べりバルクすなはちヱレミヤの口にしたがひヱホバの彼に告たまひし言をことごとく卷物に錄せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'ヱレミヤ、バルクに云ひけるはわれは禁錮られたればヱホバの室に往くことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, '故に汝ゆきて汝が我の口にしたがひて卷物に錄したるヱホバの言をよみ斷食の日にヱホバの室に於て民の耳にこれを聽しめよまた之を讀みてユダの人々のその邑々より來れる者の耳に聽しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, '彼らヱホバの前にその祈禱を献り各自其惡き途をはなれて轉ることもあらんヱホバの此民につきてのべたまひし怒と憤は大なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, '斯てネリヤの子バルクは凡て預言者ヱレミヤが己に命ぜしごとくヱホバの室にてその卷物よりヱホバの言を讀り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'ユダの王ヨシヤの子ヱホヤキムの五年九月ヱルサレムの諸の民およびユダの諸邑よりヱルサレムに來れる諸の民にヱホバの前に斷食を行ふべきこと宣示さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'バルク、ヱホバの室の上庭に於てヱホバの室の新しき門の入口の旁にあるシヤパンの子なる書記ゲマリヤの房にてその書よりヱレミヤの言を民に讀きかせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'シヤパンの子なるゲマリヤの子ミカヤその書のヱホバの言を盡くききて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, '王の宮にある書記の房にくだりいたるに諸の牧伯等即ち書記エリシヤマ、シマヤの子デラヤ、アカボルの子エルナタン、シヤパンの子ゲマリヤ、ハナニヤの子ゼデキヤおよび諸の牧伯等そこに坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'ミカヤ、バルクが書を讀て民の耳に聽せしときに己が聽しところのすべての言を彼らに告ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, '牧伯等クシの子シレミヤの子なるネタニヤの子エホデをバルクに遣はしていはせけるは汝が民に讀きかせしその卷物を手に取て來れとネリヤの子バルクすなはち手に卷物を取りて彼らの許にきたりたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, '彼らバルクにいひけるは請ふ坐して之を我らに讀きかせよとバルクすなはち彼らに讀聞せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, '彼らその諸の言をききて倶に懼れバルクにいひけるは我ら必ずこの諸の言を王に告んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'またバルクに問ていひけるは請ふ汝いかにこの諸の言をかれの口にしたがひて錄せしや我らに告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'バルク答へけるは彼その口をもてこの諸の言を我に述べたればわれ墨をもて之を書に錄せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, '牧伯等バルクにいひけるは汝ゆきてヱレミヤとともに身を匿し在所を人に知しむべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'すなはち卷物を書記エリシヤマの房に置きて庭にいり王に詣りてこの諸の言を王につげければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, '王その卷物を持來らせんとてヱホデを遣せりヱホデすなはち書記エリシヤマの房より卷物を取來りて之を王と王の側に立るすべての牧伯等に讀みきかせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, '時は九月にして王冬の室に坐せり其前に火の燃る爐あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'ヱホデ三枚か四枚を讀けるとき王小刀をもてその卷物を切割き爐の火に投いれて之を盡く爐の火に焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, '王とその臣僕等はこの諸の言をきけども懼れず亦その衣を裂ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'エルナタン、デラヤ、ゲマリヤ等王にその卷物を焚たまふ勿れと求めたれども聽ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, '王ハンメレクの子ヱラメルとアヅリエルの子セラヤとアブデルの子セレミヤに書記バルクと預言者ヱレミヤを執へよと命ぜしがヱホバかれらを匿したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, '王卷物およびバルクがヱレミヤの口にしたがひて記せし言を焚しのちヱホバの言ヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '汝また他の卷物をとりユダの王ヱホヤキムが焚しところの前の卷物の中の言をことごとく其に錄せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, '汝またユダの王ヱホヤキムに告よヱホバかくいふ汝かの卷物を焚ていへり汝何なれば此卷物に錄してバビロンの王必ず來りてこの地を滅し此に人と畜を絕さんと云しやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'この故にヱホバ、ユダの王ヱホヤキムにつきてかくいひ給ふ彼にはダビデの位に坐する者無にいたらん且かれの屍は棄られて晝は熱氣にあひ夜は寒氣にあはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, '我また彼とその子孫とその臣僕等をその惡のために罰せんまた彼らとヱルサレムの民とユダの人々には我わが彼らにつきて語りしかども彼らが聽ことをせざりし所の禍を降すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, '是に於てヱレミヤ他の卷物を取てネリヤの子書記バルクにあたふバルクすなはちユダの王ヱホヤキムが火に焚たるところの書の諸の言をヱレミヤの口にしたがひて之に錄し外にまた斯る言を多く之に加へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'ヨシヤの子ゼデキヤ、ヱホヤキムの子コニヤに代りて王となるバビロンの王ネブカデネザル彼をユダの地に王となせしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, '彼もその臣僕等もその地の人々もヱホバが預言者ヱレミヤによりて示したまひし言を聽ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'ゼデキヤ王シレミヤの子ユカルとマアセヤの子祭司ゼパニヤを預言者ヱレミヤに遣して請ふ汝我らの爲に我らの神ヱホバに祈れといはしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'ヱレミヤは民の中に出入せりそはいまだ獄に入られざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'パロの軍勢のエジプトより來りしかばヱルサレムを攻圍みたるカルデヤ人は其音信をききてヱルサレムを退けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, '時にヱホバの言預言者ヱレミヤにのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'イスラエルの神ヱホバかくいふ汝らを遣して我に求めしユダの王にかくいへ汝らを救はんとて出きたりしパロの軍勢はおのれの地エジプトへ歸らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'カルデヤ人再び來りてこの邑を攻て戰ひこれを取り火をもて焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'ヱホバかくいふ汝らカルデヤ人は必ず我らをはなれて去んといひて自ら欺く勿れ彼らは去ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, '設令汝らおのれを攻て戰ふところのカルデヤ人の軍勢を悉く撃ちやぶりてその中に負傷人のみを遺すとも彼らはおのおの其幕屋に起ちあがり火をもて此邑を焚かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, '茲にカルデヤ人の軍勢パロの軍勢を懼れてヱルサレムを退きければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'ヱレミヤ、ベニヤミンの地にて民の中にその分を分ち取らんとてヱルサレムを出でてかの地に行きしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'ベニヤミンの門にいりし時そこにハナニヤの子シレミヤの子なるイリヤと名くる門守をり預言者ヱレミヤを執へて汝はカルデヤ人に降るなりといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'ヱレミヤいひけるは詐なり我はカルデヤ人に降るにあらずと然どイリヤこれを聽ずヱレミヤを執へて侯伯等の許に引ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, '侯伯等すなはち怒りてヱレミヤを撻ちこれを書記ヨナタンの室の獄にいれたり蓋この室を獄となしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'ヱレミヤ獄にいり土牢に入りてそこに多の日を送りしのち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'ゼデキヤ王人を遣して彼をひきいださしむ而して王室にて竊にかれにいひけるはヱホバより臨める言あるやとヱレミヤ答へていひけるは有り汝はバビロン王の手に付されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'ヱレミヤまたゼデキヤ王にいひけるは我汝あるいは汝の臣僕或はこの民に何なる罪を犯したれば汝ら我を獄にいれしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, '汝らに預言してバビロンの王は汝らにも此地にも攻來らじといひし汝らの預言者はいま何處にあるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'されば王わが君よ願くはいま我に聽たまへ請ふわが願望を受納れ給へ我を書記ヨナタンの家に歸らしめたまふなかれ恐らくは我彼處に死なんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, '是においてゼデキヤ王命じてヱレミヤを獄の庭にいれしめ且邑のパンの悉く盡るまでパンを製る者の街より日々に一片のパンを彼に與へしむ即ちヱレミヤは獄の庭にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'マツタンの子シパテヤ、パシユルの子ゲダリヤ、シレミヤの子ユカル、マルキヤの子パシユル、ヱレミヤがすべての民に告たるその言を聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '云くヱホバかくいひたまふこの邑に留まるものは劍と饑饉と疫病に死べし然どいでてカルデヤ人に降る者は生んすなはちその生命をおのれの掠取物となして生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'ヱホバかくいひたまふこの邑は必ずバビロン王の軍勢の手に付されん彼之を取べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, '是をもてかの牧伯等王にいひけるは請ふこの人を殺したまへ彼はかくの如き言をのべて此邑に遺れる兵卒の手と民の手を弱くす夫人は民の安を求めずして其害を求むるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'ゼデキヤ王いひけるは視よ彼は汝らの手にあり王は汝らに逆ふこと能はざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, '彼らすなはちヱレミヤを取て獄の庭にあるハンメレクの子マルキヤの阱に投いる即ち索をもてヱレミヤを縋下せしがその阱は水なくして汚泥のみなりければヱレミヤは汚泥のなかに沈めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, '王の室の寺人エテオピア人エベデメレク彼らがヱレミヤを阱になげいれしを聞り時に王ベニヤミンの門に坐しゐたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'エベデメレク王の室よりいでゆきて王にいひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '王わが君よかの人々が預言者ヱレミヤに行ひし事は皆好らず彼らこれを阱になげ入たり邑の中に食物なければ彼はその居るところに餓死せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, '王エテオピヤ人エベデメレクに命じていひけるは汝ここより三十人を携へゆきて預言者ヱレミヤをその死ざる先にを阱より曳あげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'エベデメレクすなはちその人々を携へて王の室の庫の下にいり其處より破れたる舊き衣の布片をとり索をもてこれをを阱にをるヱレミヤの所に縋下せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, '而してエテオピア人エベデメレク、ヱレミヤに告て汝この破れたる舊き衣の布片を汝の腋の下にはさみて索に當よと云ければヱレミヤ然なせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, '彼らすなはち索をもてヱレミヤを阱より曳あげたりヱレミヤは獄の庭にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'かくてゼデキヤ王人を遣はして預言者ヱレミヤをヱホバの室の第三の門につれきたらしめ王ヱレミヤにいひけるは我汝に問ことあり毫もわれに隱す勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'ヱレミヤ、ゼデキヤにいひけるは我もし汝に示さば汝かならず我を殺さざらんや假令われ汝を勸むるとも汝われに聽じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'ゼデキヤ王密にヱレミヤに誓ひていひけるは我らにこの靈魂を造りあたへしヱホバは活く我汝を殺さず汝の生命を索むる者の手に汝を付さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'ヱレミヤ、ゼデキヤにいひけるは萬軍の神イスラエルの神ヱホバかくいひたまふ汝もしまことにバビロン王の牧伯等に降らば汝の生命活んまた此邑は火にて焚れず汝と汝の家の者はいくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, '然ど汝もし出てバビロンの王の牧伯等に降らずば此邑はカルデヤ人の手に付されん彼らは火をもて之を焚ん汝はその手を脱れざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'ゼデキヤ王ヱレミヤに云けるは我カルデヤ人に降りしところのユダ人を恐る恐くはカルデヤ人我をかれらの手に付さん彼ら我を辱しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'ヱレミヤいひけるは彼らは汝を付さじ願くはわが汝に告しヱホバの聲に聽したがひたまへさらば汝祥をえん汝の生命いきん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, '然ど汝もし降ることを否まばヱホバこの言を我に示し給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'すなはちユダの王の室に遺れる婦は皆バビロンの王の牧伯等の所に曳いだされん其婦等いはん汝の朋友等は汝を誘ひて汝に勝り汝の足は泥に沈む彼らは退き去る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, '汝の妻たちと汝の子女等はカルデヤ人の所に曳出されん汝は其手を脱れじバビロンの王の手に執へられん汝此邑をして火に焚しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'ゼデキヤ、ヱレミヤにいひけるは汝この事を人に知する勿れさらば汝殺されじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'もし牧伯等わが汝と語りしことを我儕に告げよ我らに隱す勿れ然ば我ら汝を殺さじ又王の汝に語りしことを告よといはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, '汝彼らに答へて我王に求めて我をヨナタンの家に歸して彼處に死しむること勿れといへりといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'かくて牧伯等ヱレミヤにきたりて問けるに彼王の命ぜし言のごとく彼らに告たればその事露はれざりき是をもて彼ら彼とものいふことを罷たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'ヱレミヤはヱルサレムの取るる日まで獄の庭に居りしがヱルサレムの取れし時にも彼處にをれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'ユダの王ゼデキヤの九年十月バビロンの王ネブカデネザルその全軍をひきゐヱルサレムにきたりて之を攻圍みけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'ゼデキヤの十一年四月九日にいたりて城邑破れたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'バビロンの王の牧伯等即ちネルガルシヤレゼル、サムガルネボ 寺人の長サルセキム 博士の長ネルガルシヤレゼルおよびバビロンの王のその外の牧伯等皆ともに入て中の門に坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'ユダの王ゼデキヤおよび兵卒ども之を見て逃げ夜の中に王の園の途より兩の石垣の間の門より邑をいでてアラバの途にゆきしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'カルデヤ人の軍勢これを追ひヱリコの平地にてゼデキヤにおひつき之を執へてハマテの地リブラにをるバビロンの王ネブカデネザルの許に曳ゆきければ王かしこにて彼の罪をさだめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'すなはちバビロンの王リブラにてゼデキヤの諸子をかれの目の前に殺せりバビロンの王またユダのすべての牧伯等を殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, '王またゼデキヤの目を抉さしめ彼をバビロンに曳ゆかんとて銅索に縛げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'またカルデヤ人火をもて王の室と民の家をやき且ヱルサレムの石垣を毀てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'かくて侍衞の長ネブザラダンは邑の中に餘れる民とおのれに降りし者およびその外の遺れる民をバビロンに移せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'されど侍衞の長ネブザラダンはその時民の貧しくして所有なき者等をユダの地に遺し葡萄園と田地とをこれにあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, '爰にバビロンの王ネブカデネザル、ヱレミヤの事につきて侍衞の長ネブザラダンに命じていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '彼を取りて善く待へよ害をくはふる勿れ彼が汝に云ふごとくなすべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, '是をもて侍衞の長ネブザラダン寺人の長ネブシヤスバン博士の長ネルガルシヤレゼルおよびバビロンの王の牧伯等');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, '人を遣してヱレミヤを獄の庭よりたづさへ來らしめシヤパンの子アヒカムの子なるゲダリヤに付して之を家につれゆかしむ斯彼民の中に居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'ヱレミヤ獄の庭に禁錮られをる時ヱホバの言彼にのぞみていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '汝ゆきてエテオピア人エベデメレクに告よ萬軍のヱホバ、イスラエルの神かくいふわれ我語しところの禍を此邑に降さん福はこれに降さじその日この事汝の目前にならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'ヱホバいひたまふその日にはわれ汝を救はん汝はその畏るるところの人衆の手に付されじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'われ必ず汝を救はん汝は劍をもて殺されじ汝の生命は汝の掠取物とならん汝われに倚賴めばなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, '侍衞の長ネブザラダンかのバビロンにとらへ移さるるヱルサレムとユダの人々の中にヱレミヤを鏈につなぎおきてこれを執へゆきけるが遂にこれを放ちてラマを去しめたりその後ヱホバの言ヱレミヤにのぞめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, '茲に侍衞の長ヱレミヤを召てこれにいひけるは汝の神ヱホバ此處にこの災あらんことを言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'ヱホバこれを降しその云し如く行へり汝らヱホバに罪を犯しその聲に聽したがはざりしによりてこの事汝らに來りしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, '視よ我今日汝の手の鏈を解て汝を放つ汝もし我とともにバビロンにゆくことを善とせば來れわれ汝を善くあしらはん汝もし我と偕にバビロンにゆくを惡とせば留れ視よこの地は皆汝の前に在り汝の善とする所汝の心に合ふところに往べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'ヱレミヤいまだ答へざるに彼またいひけるは汝バビロンの王がユダの諸邑の上にたてて有司となせしシヤパンの子アヒカムの子なるゲダリヤの許に歸り彼とともに民の中に居れ或は汝の善とおもふところにゆくべしと侍衞の長彼に食糧と禮物をとらせて去しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'ヱレミヤすなはちミヅパに往きてアヒカムの子ゲダリヤに詣りその地に遺れる民のうちに彼と偕にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, '茲に田舍にある軍勢の長等および彼らに屬する人々バビロンの王がアヒカムの子ゲダリヤを立てこの地の有司となし男女嬰孩および國の中のバビロンに移されざる貧者を彼にあづけたることをききしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, '即ちネタニヤの子イシマエルとカレヤの子ヨハナンとヨナタンおよびタンホメテの子セラヤとネトパ人なるエパイの諸子と或マアカ人の子ヤザニヤおよび彼らに屬する人々ミヅパにゆきてゲダリヤの許にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'シヤパンの子アヒカムの子なるゲダリヤ彼らと彼らに屬する人々に誓ひていひけるは汝らカルデヤ人に事ることを怖るる勿れこの地に住てバビロンの王に事へなば汝ら幸幅ならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, '我はミヅパに居り我らに來らんところのカルデヤ人に事へん汝らは葡萄酒と菓物と油とをあつめて之を器に蓄へ汝らが獲るところの諸邑に住めと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, '又モアブとアンモン人の中およびエドムと諸の邦にをるところのユダヤ人はバビロンの王がユダに人を遺したるシヤパンの子アヒカムの子なるゲダリヤを立てこれが有司となしたることを聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, '是においてそのユダヤ人皆その追やられし諸の處よりかへりてユダの地のミヅパに來りゲダリヤに詣れり而して多くの葡萄酒と菓物をあつむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, '又カレヤの子ヨハナンおよび田舍にをりし軍勢の長たちミヅパにきたりてゲダリヤの許にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, '彼にいひけるは汝アンモン人の王バアリスが汝を殺さんとてネタニヤの子イシマエルを遣せしを知るやと然どアヒカムの子ゲダリヤこれを信ぜざりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'カレヤの子ヨハナン、ミヅパにて密にゲダリヤに語りて言けるは請ふわれゆきて人知ずにネタニヤの子イシマエルを殺さんいかで彼汝を殺し汝に集れるユダ人を散しユダの遺れる者を滅すべけんやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, '然るにアヒカムの子ゲダリヤ、カレヤの子ヨハナンにいひけるは汝この事をなすべからず汝イシマエルにつきて僞をいふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, '七月ごろ王の血統なるエリシヤマの子ネタニヤの子イシマエル王の十人の牧伯等とともにミヅパにゆきてアヒカムの子ゲダリヤにいたりミヅパにて偕に食をなせしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'ネタニヤの子イシマエルおよび偕にをりし十人の者起上りバビロンの王がこの地の有司となせしシヤパンの子アヒカムの子なるゲダリヤを刀にて殺せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'イシマエルまたミヅパにゲダリヤと偕にをりし諸のユダヤ人と彼處にをりしカルデヤ人の兵卒を殺したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, '彼がゲダリヤを殺してより二日の後いまだ誰も之を知ざりし時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'ある人八十人その鬚を薙り衣を裂き身に傷つけ手に素祭の物と香を携へてシケム、シロ、サマリヤよりきたりてヱホバの室にいたらんとせしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'ネタニヤの子イシマエル、ミヅパよりいでて哭きつつ行て彼らを迎へ彼等に逢てアヒカムの子ゲダリヤの許に來れといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, '而して彼ら邑の中に入しときネタニヤの子イシマエル己と偕にある人々とともに彼らを殺してその屍を阱に投いれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, '但しその中の十人イシマエルにむかひ我らは田地に小麥 麰麥油および蜜を藏し有り我らをころすなかれと言たれば彼らをその兄弟と偕に殺さずして已ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'イシマエルがゲダリヤの名をもて殺せし人の屍を投入れし阱はアサ王がイスラエルの王バアシヤを怖れて鑿し阱なりネタニヤの子イシマエルその殺せし人々を之に充せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'イシマエルはミヅパに遺りをる諸の民即ち王の諸女と侍衞の長ネブザラダンがアヒカムの子ゲダリヤに交付しところのミヅパに遺れる諸の民とを擄にせりネタニヤの子イシマエルすなはち彼らを擄にしアンモン人に往んとて去れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'カレヤの子ヨハナンおよび彼と偕に在る軍勢の長たちネタニヤの子イシマエルの爲し諸の惡事を聞ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'その衆卒を率てネタニヤの子イシマエルと戰はんとて出でギベオンの池の旁にて彼に遇ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'イシマエルと偕に在る人々はカレヤの子ヨハナンおよび彼とともに在る軍勢の長たちを見て欣べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, '是をもてイシマエルがミヅパより擄へきたりし所の人々身をめぐらしてカレヤの子ヨハナンの許にゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'ネタニヤの子イシマエルは八人の者と偕にヨハナンを避け逃てアンモン人に往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'カレヤの子ヨハナンおよび彼とともにある軍勢の長等はネタニヤの子イシマエルがアヒカムの子ゲダリヤを殺してミヅパより擄へゆけるところの彼遺れる民すなはち兵卒婦人兒女寺人等を其手より取りかへして之をギベオンより携かへりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, '進てエジプトにいたらんとてベツレヘムの近傍にあるキムハムの住處に往て留れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'こはネタニヤの子イシマエルがバビロンの王の此地の有司となしたるアヒカムの子ゲダリヤを殺せしによりカルデヤ人を懼たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, '茲に軍勢の長たちおよびカレヤの子ヨハナンとホシャヤの子ヱザニヤ並に民の至微者より至大者にいたるまで');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, '皆預言者ヱレミヤの許に來りて言けるは汝の前に我らの求の受納られんことを願ふ請ふ我ら遺れる者の爲に汝の神ヱホバに祈れ(今汝の目に見がごとく我らは衆多の中の遺れる者にして寡なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'さらば汝の神ヱホバ我らの行むべき途となすべき事を示したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, '預言者ヱレミヤ彼らに云けるは我汝らに聽り汝らの言に循ひて汝らの神ヱホバに祈らん凡そヱホバが汝らに應へたまふことはわれ隱す所なく汝らに告べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, '彼らヱレミヤにいひけるは願くはヱホバ我儕の間にありて眞實なる信ずべき證者となりたまへ我らは汝の神ヱホバの汝を遣して我らに告しめたまふ諸の事に遵ひて行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, '我らは善にまれ惡きにまれ我らが汝を遣すところの我らの神ヱホバの聲に遵はん斯我らの神ヱホバの聲に遵ひてわれら福をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, '十日の後ヱホバの言ヱレミヤにのぞみしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'ヱレミヤ、カレヤの子ヨハナンおよび彼と偕に在る軍勢の長たち並に民の至微者より至大者までを悉く招きて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'これにいひけるは汝らが我を遣して汝らの祈を献げしめしところのイスラエルの神ヱホバかくいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, '汝らもし信に此地に留らばわれ汝らを建てて倒さず汝らを植て拔じそは我汝らに災を降せしを悔ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'ヱホバいひたまふ汝らが畏るるところのバビロンの王を畏るる勿れ彼をおそるる勿れわれ汝らとともにありて汝らを救ひ彼の手より汝らを拯ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'われ汝らを恤みまた彼をして汝らを恤ませ汝らを故土に歸らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, '然ど汝らもし我らはこの地に留らじ汝らの神ヱホバの聲に遵はじと言ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'また然りわれらはかの戰爭を見ず箛の聲をきかず食物に乏しからざるエジプトの地にいたりて彼處に住はんといはば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, '汝らユダの遺れる者よヱホバの言をきけ萬軍のヱホバ、イスラエルの神かくいひたまふ汝らもし強てエジプトにゆきて彼處に住はば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, '汝らが懼るるところの劍エジプトの地にて汝らに臨み汝らが恐るるところの饑饉エジプトにて汝らにおよばん而して汝らは彼處に死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, '凡そエジプトにおもむき至りて彼處に住はんとする人々は劍と饑饉と疫病に死べしその中には我彼らに降さんところの災を脱れて遺る者無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, '萬軍のヱホバ、イスラエルの神かくいひたまふ我震怒と憤恨のヱルサレムに住る者に注ぎし如くわが憤恨汝らがエジプトにいらん時に汝らに注がん汝らは呪詛となり詫異となり罵詈となり凌辱とならん汝らは再びこの處を見ざるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'ユダの遺れる者よヱホバ汝らにつきていひたまへり汝らエジプトにゆく勿れと汝ら今日わが汝らを警めしことを確に知れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, '汝ら我を汝らの神ヱホバに遣して言へり我らの爲に我らの神ヱホバに祈り我らの神ヱホバの汝に示したまふ事をことごとく我らに告よ我ら之を行はんと斯なんぢら自ら欺けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'われ今日汝らに告たれど汝らは汝らの神ヱホバの聲に遵はず汝らはヱホバが我を遣して命ぜしめたまひし事には都て遵はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, '然ば汝らはその往て住んとねがふ處にて劍と饑饉と疫病に死ることを今確に知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'ヱレミヤ諸の民にむかひて其神ヱホバの言を盡く宣べその神ヱホバが己を遣して言しめたまへる其諸の言を宣をはりし時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'ホシャヤの子アザリヤ、カレヤの子ヨハナンおよび驕る人皆ヱレミヤに語りていひけるは汝は謊をいふ我らの神ヱホバはエジプトにゆきて彼處に住む勿れと汝をつかはして云せたまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'ネリヤの子バルク汝を唆して我らに逆はしむ是我らをカルデヤ人の手に付して殺さしめバビロンに移さしめん爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, '斯カレヤの子ヨハナンと軍勢の長等および民皆ヱホバの聲に遵はずしてユダの地に住ことをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, '斯てカレヤの子ヨハナンと軍勢の長等はユダに遺れる者即ちその逐やられし國々よりユダの地に住んとて皈りし者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, '男女嬰孩王の女たちおよび凡て侍衞の長ネブザラダンがシヤパンの子なるアヒカムの子ゲダリヤに付し置し者並に預言者ヱレミヤとネリヤの子バルクを取て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'エジプトの地に至れり彼ら斯ヱホバの聲に遵はざりき而して遂にタパネスに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'ヱホバの言タパネスにてヱレミヤに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '汝大なる石を手に取りユダの人々の目の前にてこれをタパネスに在るパロの室の入口の旁なる磚窰の泥土の中に藏して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, '彼らにいへ萬軍のヱホバ、イスラエルの神かくいひたまふ視よわれ使者を遣はしてわが僕なるバビロンの王ネブカデネザルを召きその位をこの藏したる石の上に置しめん彼錦繡をその上に敷べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'かれ來りてエジプトの地を撃ち死に定まれる者を死しめ虜に定まれる者を虜にし劍に定まれる者を劍にかけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'われエジプトの諸神の室に火を燃さんネブカデネザル之を焚きかれらを虜にせん而して羊を牧ふ者のその身に衣を纒ふがごとくエジプトの地をその身に纒はん彼安然に其處をさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, '彼はエジプトの地のベテシメシの偶像を毀ち火をもてエジプト人の諸神の室を焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'エジプトの地に住るところのユダの人衆すなはちミグドル、タパネス、ノフ、パテロスの地に住る者の事につきてヱレミヤに臨みし言に曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '萬軍のヱホバ、イスラエルの神かくいふ汝らは我ヱルサレムとユダの諸邑に降せしところの災をみたり視よこれらは今日すでに空曠となりて住む人なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'こは彼ら惡をなして我を怒らせしによる即ちかれらは己も汝らも汝らの先祖等も識ざるところの他の神にゆきて香を焚き且これに奉へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'われ我僕なる預言者たちを汝らに遣し頻にこれを遣して請ふ汝らわが嫌ふところの此憎むべき事を行ふ勿れといはせけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, '彼ら聽かず耳を傾けず他の神に香を焚きてその惡を離れざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, '是によりて我震怒とわが憤恨ユダの諸邑とヱルサレムの街にそそぎて之を焚たれば其等は今日のごとく荒れかつ傾圮たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, '萬軍の神イスラエルの神ヱホバいまかくいふ汝ら何なれば大なる惡をなして己の靈魂を害しユダの中より汝らの男と女と孩童と乳哺子を絕て一人も遺らざらしめんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, '何なれば汝ら其手の行爲をもて我を怒らせ汝らが往て住ふところのエジプトの地に於て他の神に香を焚きて己の身を滅し地の萬國の中に呪詛となり凌辱とならんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'ユダの地とヱルサレムの街にて行ひし汝らの先祖等の惡ユダの王等の惡其妻等の惡および汝らの身の惡汝らの妻等の惡を汝ら忘れしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, '彼らは今日にいたるまで悔いずまた畏れず汝らと汝らの先祖等の前に立たる我律法とわが典例に循ひて行まざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, '是故に萬軍のヱホバ、イスラエルの神かくいふ視よわれ面を汝らにむけて災を降しユダの人衆を悉く絕ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, '又われエジプトの地にすまんとてその面をこれにむけて往しところの彼ユダの遺れる者を取らん彼らは皆滅されてエジプトの地に仆れん彼らは劍と饑饉に滅され微者も大者も劍と饑饉によりて死べし而して呪詛となり詫異となり罵詈となり凌辱とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'われヱルサレムを罰せし如く劍と饑饉と疫病をもてエジプトに住る者を罰すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, '是をもてエジプトの地に往て彼處に住るところのユダの遺れる者の中に一人も逃れまたは遺りてその心にしたひて歸り住はんとねがふところのユダの地に歸るもの無るべし逃るる者の外には歸る者無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, '是に於てその妻が香を他の神に焚しことを知れる人々および其處に立てる婦人等の大なる群衆並にエジプトの地のパテロスに住るところの民ヱレミヤに答へて云けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '汝がヱホバの名をもてわれらに述し言は我ら聽かじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, '我らは必ず我らの口より出る言を行ひ我らが素なせし如く香を天后に焚きまた酒をその前に灌ぐべし即ちユダの諸邑とヱルサレムの街にて我らと我らの先祖等および我らの王等と我らの牧伯等の行ひし如くせん當時われらは糧に飽き福をえて災に遇ざりし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, '我ら天后に香を焚くことを止め酒をその前に灌がずなりし時より諸の物に乏しくなり劍と饑饉に滅されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, '我らが天后に香を焚き酒をその前に灌ぐに方りて之に象りてパンを製り酒を灌ぎしは我らの夫等の許せし事にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'ヱレミヤ即ち男女の諸の人衆および此言をもて答へたる諸の民にいひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'ユダの諸邑とヱルサレムの街にて汝らと汝らの先祖等および汝等の王等と汝らの牧伯等および其地の民の香を焚しことはヱホバ之を憶えまた心に思ひたまふにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'ヱホバは汝らの惡き爲のため汝らの憎むべき行の爲に再び忍ぶことをえせざりきこの故に汝らの地は今日のごとく荒地となり詫異となり呪詛となり住む人なき地となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, '汝ら香を焚きヱホバに罪を犯しヱホバの聲に聽したがはずその律法と憲法と證詞に循ひて行まざりしに由て今日のごとく此災汝らにおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'ヱレミヤまたすべての民と婦等にいひけるはエジプトの地に居るユダの子孫よヱホバの言をきけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, '萬軍のヱホバ、イスラエルの神かくいひたまふ汝らと汝らの妻等は口をもていひ手をもて成し我ら香を天后に焚き酒を灌ぎて立しところの誓を必ず成就んといふ汝ら必ず誓をたてかならず其誓を成就んとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'この故にエジプトの地に住るユダの人々よヱホバの言をきけヱホバいひたまふわれ我大なる名を指て誓ふエジプトの全地にユダの人々一人もその口に主ヱホバは活くといひて再び我名を稱ふることなきにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, '視よわれ彼らをうかがはん是福をあたふる爲にあらず禍をくださん爲なりエジプトの地に居るユダの人々は劍と饑饉に滅びて絕るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, '然ど劍を逃るる僅少の者はエジプトの地を出てユダの地に歸らん又エジプトの地にゆきて彼處に寄寓れるユダの遺れる者はその立ところの言は我のなるか彼らのなるかを知るにいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'ヱホバいひ給ふわがこの處にて汝らを罰する兆は是なり我かくして我汝らに禍をくださんといひし言の必ず立ことを知しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'すなはちヱホバかくいひたまふ視よわれユダの王ゼデキヤを其生命を索むる敵なるバビロンの王ネブカデネザルの手に付せしが如くエジプトの王パロホフラを其敵の手その生命を索むる者の手に付さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'ユダの王ヨシヤの子ヱホヤキムの四年ネリヤの子バルクが此等の言をヱレミヤの口にしたがひて書に錄せしとき預言者ヱレミヤこれに語りていひけるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'バルクよイスラエルの神ヱホバ汝にかくいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, '汝曾ていへり嗚呼我は禍なるかなヱホバ我憂に悲を加へたまへり我は歎きて疲れ安きをえずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, '汝かく彼に語れヱホバかくいひたまふ視よわれ我建しところの者を毀ち我植しところの者を拔ん是この全地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, '汝己れの爲に大なる事を求むるかこれを求むる勿れ視よわれ災をすべての民に降さん然ど汝の生命は我汝のゆかん諸の處にて汝の掠物とならしめんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, '茲にヱホバの言預言者ヱレミヤに臨みて諸國の事を論ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, '先エジプトの事すなはちユフラテ河の邊なるカルケミシの近傍にをるところのエジプト王パロネコの軍勢の事を論ふ是はユダの王ヨシヤの子ヱホヤキムの四年にバビロンの王ネブカデネザルが撃やぶりし者なり其言にいはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, '汝ら大楯小干を備へて進み戰へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, '馬を車に繋ぎ馬に乗り盔を被りて立て戈を磨き甲を着よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'われ見るに彼らは懼れて退きその勇士は打敗られ狼狽遁て後をかへりみず是何故ぞや畏懼かれらのまはりにありとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, '快足なる者も逃えず強者も遁れえず皆北の方にてユフラテ河の旁に蹶き仆れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'かのナイルのごとくに湧あがり河のごとくに其水さかまく者は誰ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'エジプトはナイルの如くに湧あがりその水は河の如くに逆まくなり而していふ我上りて地を蔽ひ邑とその中に住る者とを滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, '汝等馬に乗り車を驅馳らせよ勇士よ盾を執るエテオピア人プテ人および弓を張り挽くルデ人よ進みいづべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, '此は主なる萬軍のヱホバの復仇の日即ちその敵に仇を復し給ふ日なり劍は食ひて飽きその血に醉はん主なる萬軍のヱホバ北の地にてユフラテ河の旁に宰ることをなし給へばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, '處女よエジプトの女よギレアデに上りて乳香を取れ汝多くの藥を用ふるも益なし汝は愈ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, '汝の恥辱は國々にきこえん汝の號泣は地に滿てり勇士は勇士にうち觸てともに仆る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'バビロンの王ネブカデネザルが來りてエジプトの地を撃んとする事につきてヱホバの預言者ヱレミヤに告たまひし言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '汝らエジプトに宣べミグドルに示し又ノフ、タパネスに示しいふべし汝ら堅く立ちて自ら備よ 劍なんぢの四周を食ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, '汝の力ある者いかにして拂ひ除かれしやその立ざるはヱホバこれを仆したまふに由るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, '彼多の者を蹶かせたまふ人其友の上に仆れかさなり而していふ起よ我ら滅すところの劍を避けてわが國にかへり故土にいたらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, '人彼處に叫びてエジプトの王パロは滅されたり彼は機會を失へりといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, '萬軍のヱホバと名りたまふところの王いひたまふ我は活く彼は山々の中のタボルのごとく海の旁のカルメルのごとくに來らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'エジプトに住る女よ汝移轉の器皿を備へよそはノフは荒蕪となり燒れて住む人なきにいたるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'エジプトは至美しき牝の犢のごとし蜚虻きたり北の方より來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'また其中の傭人は肥たる犢のごとし彼ら轉向てともに逃げ立ことをせず是その滅さるる日いたり其罰せらるる時來りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, '彼は蛇の如く聲をいだす彼ら軍勢を率ゐて來り樵夫の如く斧をもて之にのぞめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'ヱホバいひ給ふ彼らは探りえざるに由りて彼の林を砍仆せり彼等は蝗蟲よりも多して數へがたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'エジプトの女は辱められ北の民の手に付されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, '萬軍のヱホバ、イスラエルの神いひ給ふ視よわれノフのアモンとパロとエジプトとその諸神とその王等すなはちパロとかれを賴むものとを罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'われ彼らを其生命を索むる者の手とバビロンの王ネブカデネザルの手とその臣僕の手に付すべしその後この地は昔のごとく人の住むところとならんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, '我僕ヤコブよ怖るる勿れイスラエルよ驚く勿れ視よわれ汝を遠方より救ひきたり汝の子孫をその擄移されたる地より救ひとるべしヤコブは歸りて平安と寧靜をえん彼を畏れしむる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'ヱホバいひたまふ我僕ヤコブよ汝怖るる勿れ我汝と偕にあればなり我汝を逐やりし國々を悉く滅すべけれど汝をば悉くは滅さじわれ道をもて汝を懲し汝を全くは罪なき者とせざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'パロがガザを撃ざりし先にペリシテ人の事につきて預言者ヱレミヤに臨みしヱホバの言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'ヱホバかくいひたまふ視よ水北より起り溢れながれて此地と其中の諸の物とその邑と其中に住る者とに溢れかかるべしその時人衆は叫びこの地に住る者は皆哭くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'その逞しき馬の蹄の蹴たつる音のため其車の響のため其輪の轟のために父は手弱りて己の子女を顧みざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, '是ペリシテ人を滅しつくしツロとシドンにのこりて助力をなす者を悉く絕す日來ればなりヱホバ、カフトルの地に遺れるペリシテ人を滅したまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'ガザには髮を剃るの事はじまるアシケロンと其剩餘の平地は滅ぼさる汝いつまで身に傷くるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'ヱホバの劍よ汝いつまで息まざるや汝の鞘に歸りて息み靜まれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'ヱホバこれに命じたるなればいかで息むことをえんやアシケロンと海邊を攻ることを定めたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, '萬軍のヱホバ、イスラエルの神モアブの事につきてかくいひたまふ嗚呼ネボは禍なるかな是滅されたりキリヤタイムは辱められて取られミスガブは辱められて毀たる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'モアブの榮譽は失さりぬヘシボンにて人衆モアブの害を謀り去來之を絕ちて國をなさざらしめんといふマデメンよ汝は滅されん劍汝を追はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'ホロナイムより號咷の聲きこゆ毀敗と大なる滅亡あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'モアブ滅されてその嬰孩等の號咷聞ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, '彼らは哭き哭きてルヒテの坂を登る敵はホロナイムの下り路にて滅亡の號咷をきけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, '逃て汝らの生命を救へ曠野に棄られたる者の如くなれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, '汝は汝の工作と財寶を賴むによりて汝も執へられん又ケモシは其祭司およびその牧伯等と偕に擄へうつさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, '殘害者諸の邑に來らん一の邑も免れざるべし谷は滅され平地は荒されんヱホバのいひたまひしがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, '翼をモアブに予へて飛さらしむ其諸邑は荒て住者なからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'ヱホバの事を行ふて怠る者は詛はれ又その劍をおさへて血を流さざる者は詛はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'モアブはその幼時より安然にして酒の其滓のうへにとざまりて此器よりかの器に斟うつされざるが如くなりき彼擄うつされざりしに由て其味尚存ちその香氣變らざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'ヱホバいひたまふ此故にわがこれを傾くる者を遣はす日來らん彼らすなはち之を傾け其器をあけ其罇を碎くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'モアブはケモシのために羞をとらん是イスラエルの家がその恃めるところのベテルのために羞をとりしが如くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, '汝ら何ぞ我らは勇士なり強き軍人なりといふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'モアブはほろぼされその諸邑は騰りその選擇の壯者は下りて殺さる萬軍のヱホバと名る王これをいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'モアブの滅亡近けりその禍速に來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, '凡そ其四周にある者よ彼のために歎けその名を知る者よ強き竿美しき杖いかにして折しやといへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'デボンに住る女よ榮をはなれて下り燥ける地に坐せよモアブを敗る者汝にきたりて汝の城を滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'アロエルに住る婦よ道の側にたちて闥ひ逃きたる者と脱れいたる者に事いかんと問へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'モアブは敗られて羞をとる汝ら呼はり咷びモアブは滅されたりとアルノンに告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, '鞫災平地に臨みホロン、ヤハヅ、メパアテ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'デボン、ネボ、ベテデブラタイム');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'キリヤタイム、ベテガムル、ベテメオン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'ケリオテ、ボズラ、モアブの地の諸邑の遠き者にも近き者にも臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'モアブの角は碎け其臂は折たりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, '汝らモアブを醉はしめよ彼ヱホバにむかひて驕傲ればなりモアブは其吐たる物に轉びて笑柄とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'イスラエルは汝の笑柄にあらざりしや彼盜人の中にありしや汝彼の事を語るごとに首を搖たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'モアブに住る者よ汝ら邑を離れて磐の間にすめ穴の口の側に巢を作る斑鳩の如くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'われらモアブの驕傲をきけり其驕傲は甚だし即ち其驕慢矜高驕誇およびその心の自ら高くするを聞り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'ヱホバいひたまふ我モアブの驕傲とその言の虛きとを知る彼らは僞を行ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'この故に我モアブの爲に咷びモアブの全地の爲に呼はるキルハレスの人々の爲に嗟歎あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'シブマの葡萄の樹よわれヤゼルの哭泣にこえて汝の爲になげくべし汝の蔓は海を踰え延てヤゼルの海にまでいたる掠奪者來りて汝の果と葡萄をとらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, '欣喜と歡樂園とモアブの地をはなれ去る我酒醡に酒無からしめん呼はりて葡萄を踐もの無るべし其喚呼は葡萄をふむ喚呼にあらざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'ヘシボンよりエレアレとヤハヅにいたりゾアルよりホロナイムとエグラテシリシヤにいたるまで人聲を揚ぐそはニムリムの水までも絕たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'ヱホバいひたまふ我祭物を崇邱に献げ香をその諸神に焚くところの者をモアブの中に滅さんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'この故に我心はモアブの爲に簫のごとく歎き我心はキルハレスの人衆のために蕭のごとく歎く是其獲たるところの財うせたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, '人みなその髮を剃り皆その鬚をそり皆その手に傷け腰に麻布をまとはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'モアブにては家蓋の上と街のうちに遍く悲哀ありそはわれ心に適ざる器のごとくにモアブを碎きたればなりとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, '嗚呼モアブはほろびたり彼らは咷ぶ嗚呼モアブは羞て面を背けたりモアブはその四周の者の笑柄となり恐懼となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'ヱホバかくいひたまふ視よ敵鷲のごとくに飛來りて翼をモアブのうへに舒ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'ケリオテは取られ城はみな奪はるその日にはモアブの勇士の心子を產む婦のごとくになるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'モアブはヱホバにむかひて傲りしゆゑに滅ぼされて再び國を成ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'ヱホバいひたまふモアブにすめる者よ恐怖と陷阱と罟汝に臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, '恐怖をさけて逃るものは陷阱におちいり陷阱より出るものは罟にとらへられん其はわれモアブにその罰をうくべき年をのぞましむればなりヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, '遁逃者は力なくしてヘシボンの蔭に立つ是は火ヘシボンより出で火焔シホンのうちより出てモアブの地および喧閙をなす者の首の頂を燒ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, '嗚呼禍なるかなモアブよケモシの民は亡びたり即ち汝の諸子は擄へうつされ汝の女等は執へゆかれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, '然ど末の日に我モアブの擄移されたる者を返さんとヱホバいひ給ふ此まではモアブの鞫をいへる言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'アンモン人の事につきてヱホバかくいひたまふイスラエルに子なからんや嗣子なからんや何なれば彼らの王ガドを受嗣ぎ彼の民その邑々に住や');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'ヱホバいひたまふ是故に視よわが戰鬪の號呼をアンモン人のラバに聞えしむる日いたらんラバは荒垤となりその女等は火に焚れんその時イスラエルはおのれの嗣者となりし者等の嗣者となるべしヱホバこれをいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'ヘシボンよ咷べアイは滅びたりラバの女たちよ呼はれ麻布を身にまとひ嗟て籬のうちに走れマルカムとその祭司およびその牧伯等は偕に擄へ移されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, '汝何なれば谷の事を誇るや背ける女よ汝の谷は流るるなり汝財貨に倚賴みていふ誰か我に來らんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, '主なる萬軍のヱホバいひたまふ視よ我畏懼を汝の四周の者より汝に來らしめん汝らおのおの逐れて直にすすまん逃る者を集むる人無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, '然ど後にいたりてわれアンモン人の擄移されたる者を返さんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'エドムの事につきて萬軍のヱホバかくいひたまふテマンの中には智慧あることなきにいたりしや明哲者には謀略あらずなりしやその智慧は盡はてしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'デダンに住る者よ逃よ遁れよ深く竄れよ我エサウの滅亡をかれの上にのぞませ彼を罰する時をきたらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, '葡萄を斂むる者もし汝に來らば少許の果をも餘さざらんもし夜間盜人きたらばその飽まで滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'われエサウを裸にし又その隱處を露にせん彼は身を匿すことをえざるべしその裔も兄弟も隣舍も滅されん而して彼は在ずなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, '汝の孤子を遺せわれ之を生存へしめん汝の嫠は我に倚賴むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'ヱホバかくいひ給ふ視よ杯を飮べきにあらざる者もこれを飮ざるをえざるなれば汝まつたく罰を免るることをえんや汝は罰を免れじ汝これを飮ざるべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'ヱホバいひたまふ我おのれを指して誓ふボズラは詫異となり羞辱となり荒地となり呪詛とならんその諸邑は永く荒地となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'われヱホバより音信をきけり使者遣されて萬國にいたり汝ら集りて彼に攻めきたり起て戰へよといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, '視よわれ汝を萬國の中に小者となし人々の中に藐めらるる者となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, '磐の隱場にすみ山の高處を占る者よ汝の恐ろしき事と汝の心の驕傲汝を欺けり汝鷹のごとくに巢を高き處に作りたれどもわれ其處より汝を取り下さんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'エドムは詫異とならん凡そ其處を過る者は驚きその災害のために笑ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'ヱホバいひたまふソドムとゴモラとその隣の邑々の滅しがごとく其處に住む人なく其處に宿る人の子なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, '視よ敵獅子のヨルダンの叢より上るがごとく堅き宅に攻めきたらんわれ直に彼を其處より逐奔らせわが選みたる者をその上に立てん誰か我のごとき者あらん誰か我爲に時期を定めんや孰の牧者か我前にたつことをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'さればエドムにつきてヱホバの謀りたまひし御謀とテマンに住る者につきて思ひたまひし思をきけ群の弱者はかならず曳ゆかれん彼かならずかれらの住宅を滅すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'その傾圮の響によりて地は震ふ號咷ありその聲紅海にきこゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'みよ彼鷹のごとくに上り飛びその翼をボズラの上に舒べんその日エドムの勇士の心は子を產む婦の心の如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'ダマスコの事 ハマテとアルパデは羞づそは凶き音信をきけばなり彼らは心を喪へり海の上に恐懼あり安き者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'ダマスコは弱り身をめぐらして逃んとす恐懼これに及び憂愁と痛劬子を產む婦にあるごとくこれにおよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, '頌美ある邑我欣ぶところの邑を何なれば棄さらざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'さればその日に壯者は街に仆れ兵卒は悉く滅されんと萬軍のヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'われ火をダマスコの石垣の上に燃しベネハダデの殿舍をことごとく焚くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'バビロンの王ネブカデネザルが攻め撃たるケダルとハゾルの諸國の事につきて/ヱホバかくいひたまふ汝ら起てケダルに上り東の衆人を滅せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'その幕屋とその羊の群は彼等これを取りその幕とその諸の器と駱駝とは彼等これを奪ひとらん人これに向ひ惶懼四方にありと呼るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'ヱホバいひたまふハゾルに住る者よ逃よ急に走りゆき深き處に居れバビロンの王ネブカデネザル汝らをせむる謀略を運らし汝らをせむる術計を設けたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'ヱホバいひ給ふ汝ら起て穩なる安かに住める民の所に攻め上れ彼らは門もなく關もなくして獨り居ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'その駱駝は擄掠とせられその多の畜は奪はれん我かの毛の角を剪る者を四方に散しその滅亡を八方より來らせんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'ハゾルは山犬の窟となり何までも荒蕪となりをらん彼處に住む人なく彼處に宿る人の子なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'ユダの王ゼデキヤが位に即し初のころヱホバの言預言者ヱレミヤに臨みてエラムの事をいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, '萬軍のヱホバかくいひたまふ視よわれエラムが權能として賴むところの弓を折らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'われ天の四方より四方の風をエラムに來らせ彼らを四方の風に散さんエラムより追出さるる者のいたらざる國はなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'ヱホバいひたまふわれエラムをしてその敵の前とその生命を索むるものの前に懼れしめん我災をくだし我烈しき怒をその上にいたらせんまたわれ劍をその後につかはしてこれを滅し盡すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'われ我位をエラムに居ゑ王と牧伯等を其處より滅したたんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, '然ど末の日にいたりてわれエラムの擄移されたる者を返すべしとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'ヱホバ預言者ヱレミヤによりてバビロンとカルデヤ人の地のことを語り給ひし言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '汝ら國々の中に告げまた宣示せ纛を樹よ隱すことなく宣示して言へバビロンは取られベルは辱められメロダクは碎かれ其像は辱められ其木像は碎かると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'そは北の方より一の國人きたりて之を攻めその地を荒して其處に住む者無らしむればなり人も畜も皆逃去れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'ヱホバいひたまふその日その時イスラエルの子孫かへり來らん彼らと偕にユダの子孫かへり來るべし彼らは哭きつつ行てその神ヱホバに請求むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, '彼ら面をシオンに向てその路を問ひ來れ我らは永遠わするることなき契約をもてヱホバにつらならんといふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, '我民は迷へる羊の群なりその牧者之をいざなひて山にふみ迷はしめたれば山より岡とゆきめぐりて其休息所を忘れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, '之に遇ふもの皆之を食ふその敵いへり我らは罪なし彼らヱホバすなはち義きの在所その先祖の望みしところなるヱホバに罪を犯したるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, '汝らバビロンのうちより逃よカルデヤ人の地より出よ群の前にゆくところの牡山羊のごとくせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, '視よわれ大なる國々より人を起しあつめて北の地よりバビロンに攻め來らしめん彼ら之にむかひて備をたてん是すなはち取るべし彼らの矢は空しく返らざる狡き勇士の矢のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'カルデヤは人に掠められん之を掠むる者は皆飽ことをえんとヱホバ曰たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, '我產業を掠る者よ汝らは喜び樂み穀物を碾す犢のごとくに躍り牡馬のごとく嘶けども');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, '汝らの母は痛く辱められん汝らを生しものは恥べし視よ國々の中の終末の者荒野となり燥ける地となり沙漠とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'ヱホバの怒りの爲に之に住む者なくして悉く荒地となるべしバビロンを過る者は皆その禍に驚き且嗤はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, '凡そ弓を張る者よバビロンの四周に備をなして攻め矢を惜まずして之を射よそは彼ヱホバに罪を犯したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'その四周に喊き叫びて攻めかかれ是手を伸ぶその城堞は倒れその石垣は崩る是ヱホバ仇を復したまふなり汝らこれに仇を復せ是の行ひしごとく是に行へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, '播種者および穡收時に鎌を執る者をバビロンに絕せその滅すところの劍を怖れて人おのおの其民に歸り各その故土に逃べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'イスラエルは散されたる羊にして獅子之を追ふ初にアツスリヤの王之を食ひ後にこのバビロンの王ネブカデネザルその骨を碎けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'この故に萬軍のヱホバ、イスラエルの神かくいひたまふ視よわれアツスリヤの王を罰せしごとくバビロンの王とその地を罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'われイスラエルを再びその牧場に歸さん彼カルメルとバシヤンの上に草をくらはんまたエフライムとギレアデの山にてその心を飽すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'ヱホバいひたまふ其日その時にはイスラエルの愆を尋るも有らず又ユダの罪を尋るも遇じそはわれ我存せしところの者を赦すべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'ヱホバいひたまふ汝ら上りて悖れる國罰を受べき民を攻めその後より之を荒し全くこれを滅せ我汝らに命ぜしごとく行ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'その地に戰鬪の咷と大なる敗壤あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, '嗚呼全地を摧きし鎚折れ碎くるかな嗚呼バビロン國々の中に荒地となるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'バビロンよわれ汝をとるために罟を置けり汝は擒へらるれども知ず汝ヱホバに敵せしにより尋られて獲へらるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'ヱホバ庫を啓きてその怒りの武器をいだしたまふ是主なる萬軍のヱホバ、カルデヤ人の地に事をなさんとしたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, '汝ら終の者にいたるまで來りてこれを攻めその庫を啓き之を積て塵垤のごとくせよ盡くこれを滅ぼして其處に遺る者なからしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'その牡牛を悉く殺せこれを屠場にくだらしめよ其等は禍なるかな其日その罰を受べき時來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'バビロンの地より逃げて遁れ來し者の聲ありて我らの神ヱホバの仇復その殿の仇復をシオンに宣ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, '射者をバビロンに召集めよ凡そ弓を張る者よその四周に陣どりて之を攻め何人をも逃す勿れその作爲に循ひて之に報いそのすべて行ひし如くこれに行へそは彼イスラエルの聖者なるヱホバにむかひて驕りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, '是故にその日壯者は衢に踣れその兵卒は悉く絕されんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, '主なる萬軍のヱホバいひたまふ驕傲者よ視よわれ汝の敵となる汝の日わが汝を罰する時きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, '驕傲者は蹶きて仆れん之を扶け起す者なかるべしわれ火をその諸邑に燃しその四周の者を燒盡さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, '萬軍のヱホバかくいひたまふイスラエルの民とユダの民は偕に虐げらる彼らを擄にせし者は皆固くこれを守りて釋たざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, '彼らを贖ふ者は強しその名は萬軍のヱホバなり彼必ずその訴を理してこの地に安を與へバビロンに住る者を戰慄しめ給はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'ヱホバいひたまふカルデヤ人の上バビロンに住る者の上およびその牧伯等とその智者等の上に劍あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, '劍僞る者の上にあり彼ら愚なる者とならん劍その勇士の上にあり彼ら懼れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, '劍その馬の上にあり其車の上にあり又その中にあるすべての援兵の上にあり彼ら婦女のごとくにならん劍その寶の上にあり是掠めらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, '旱その水の上にあり是涸かん斯は偶像の地にして人々偶像に迷へばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, '是故に野の獸彼處に山犬と偕に居り鴕鳥も彼處に棲べし何時までも其地に住む人なく世々ここに住む人なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'ヱホバいひたまふ神のソドム、ゴモラとその近隣の邑々を滅せしごとく彼處に住む人なく彼處に宿る人の子なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, '視よ北の方より民きたるあらん大なる國の人とおほくの王たち地の極より起らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, '彼らは弓と槍をとる情なく矜恤なしその聲は海のごとくに鳴るバビロンの女よ彼らは馬に乗り戰士のごとくに備へて汝を攻ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'バビロンの王その風聲をききしかば其手弱り苦痛と子を產む婦の如き劬勞彼に迫る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, '視よ敵獅子のヨルダンの叢より上るが如く堅き宅に攻めきたらんわれ直に彼等を其處より逐奔らせわが選みたる者をその上に立ん誰か我のごとき者あらんや誰かわが爲に時期を定めんや何の牧者か我前に立ことをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'さればバビロンにつきてヱホバの謀りたまひし御謀とカルデヤ人の地につきて思ひたまひし思想をきけ群の弱者必ず曳ゆかれん彼必ずかれらの住居を滅すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'バビロンは取れたりとの聲によりて地震へその號咷國々の中に聞ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'ヱホバかくいひたまふ視よわれ滅すところの風を起してバビロンを攻め我に悖る者の中に住む者を攻べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'われ簸者をバビロンに遣さん彼らこれを簸てその地を空くせん彼らすなはちその禍の日にこれを四方より攻むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, '弓を張る者に向ひまた鎧を被て立あがる者に向ひて射者の者其弓を張らん汝らその壯者を憫れまず其軍勢を悉く滅すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, '然ば殺さるる者カルデヤ人の地に踣れ刺るる者その街に踣れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'イスラエルとユダはその神萬軍のヱホバに棄てられず彼らの地にはイスラエルの至聖者にむかひて犯せるところの罪充つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, '汝らバビロンのうちより逃げいでておのおの其生命をすくへ其の罪のために滅さるる勿れ今はヱホバの仇をかへしたまふ時なれば報をそれになしたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'バビロンは金の杯にしてヱホバの手にあり諸の地を醉せたり國々その酒を飮めり是をもて國々狂へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'バビロンは忽ち踣れて壞る之がために哭けその傷のために乳香をとれ是或は愈ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'われらバビロンを醫さんとすれども愈ず我らこれをすてて各その國に歸るべしそはその罰天におよび雲にいたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'ヱホバわれらの義をあらはしたまふ來れシオンに於て我らの神ヱホバの作爲をのべん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, '矢を磨ぎ楯を取れヱホバ、メデア人の王等の心を激發したまふヱホバ、バビロンをせめんと謀り之を滅さんとしたまふ是ヱホバの復仇その殿の復仇たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'バビロンの石垣に向ひて纛を樹て圍を堅くし番兵を設け伏兵をそなへよ蓋ヱホバ、バビロンに住める者をせめんとて謀りその言しごとく行ひたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'おほくの水の傍に住み多くの財寶をもてる者よ汝の終汝の貧婪の限來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, '萬軍のヱホバおのれを指して誓ひいひ給ふ我まことに人を蝗のごとくに汝の中に充さん彼ら汝に向ひて鯨波の聲を揚ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'ヱホバその能力をもて地をつくり其知慧をもて世界を建てその明哲をもて天を舒たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, '彼聲を發したまふ時は天に衆の水いづかれ雲を地の極より起らしめ電光と雨をおこし風をその庫よりいだしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'すべての人は獸のごとくにして智慧なし諸の鑄物師はその作りし像のために辱を取る其鑄るところの像は僞の者にしてその中に靈なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, '其等は空しき者にして迷妄の工作なりわが臨むとき其等は滅べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'ヤコブの分は此の如くならず彼は萬物およびその產業の族の造化主なりその名は萬軍のヱホバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, '汝はわが鎚にして戰の器具なりわれ汝をもて諸の邦を碎き汝をもて萬國を滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'われ汝をもて馬とその騎る者を摧き汝をもて車とその御する者を碎かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'われ汝をもて男と女をくだき汝をもて老たる者と幼き者をくだき汝をもて壯者と童女をくだくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'われ汝をもて牧者とその群をくだき汝をもて農夫とその軛を負ふ牛をくだき汝をもて方伯等と督宰等をくだかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, '汝らの目の前にて我バビロンとカルデヤに住るすべての者がシオンになせし諸の惡きことに報いんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'ヱホバ言ひたまはく全地を滅したる滅す山よ視よわれ汝の敵となるわれ手を汝の上に伸て汝を巖より轉ばし汝を焚山となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'ヱホバいひたまふ人汝より石を取て隅石となすことあらじ亦汝より石を取りて基礎となすことあらじ汝はいつまでも荒地となりをらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, '纛を地に樹て箛を國々の中に吹き國々の民をあつめて之を攻めアララテ、ミンニ、アシケナズの諸國を招きて之を攻め軍長をたてて之を攻め恐しき蝗のごとくに馬をすすめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, '國々の民をあつめて之を攻めメデア人の王等とその方伯等とその督宰等およびそのすべての領地の人をあつめて之を攻めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, '地は震ひ搖かんそはヱホバその意旨をバビロンになしバビロンの地をして住む人なき荒地とならしめたまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'バビロンの勇者は戰をやめて其城にこもりその力失せて婦のごとくにならん其宅は燒けその門閂は折れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, '馹は趨て馹にあひ使者は趨て使者にあひバビロンの王につげて邑は盡く取られ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, '渡口は取られ沼は燒れ兵卒は怖るといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, '萬軍のヱホバ、イスラエルの神かくいひたまふバビロンの女は禾場のごとしその踏るる時きたれり暫くありてその苅るる時いたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'バビロンの王ネブカデネザル我を食ひ我を滅し我を空き器のごとくなし龍の如くに我を呑みわが珍饈をもて其腹を充し我を逐出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'シオンに住る者いはんわがうけし虐遇と我肉はバビロンにかかるべしヱルサレムいはん我血はカルデヤに住める者にかかるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'さればヱホバかくいひたまふ視よわれ汝の訟を理し汝の爲に仇を復さん我その海を涸かし其泉を乾かすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'バビロンは頽壘となり山犬の巢窟となり詫異となり嗤笑となり人なき所とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, '彼らは獅子のごとく共に吼え小獅のごとくに吼ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, '彼らの慾の燃る時にわれ筵を設けてかれらを醉せ彼らをして喜ばしめながき寢にいりて目を醒すことなからしめんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'われ屠る羔羊のごとく又牡羊と牡山羊のごとくにかれらをくだらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'セシヤクいかにして取られしや全地の人の頌美者いかにして執へられしや國々の中にバビロンいかにして詫異となりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, '海バビロンに溢れかかりその多くの波濤これを覆ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'その諸邑は荒れて燥ける地となり沙漠となり住む人なき地とならん人の子そこを過ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'われベルをバビロンに罰しその呑みたる者を口より取出さん國々はまた川の如くに彼に來らじバビロンの石垣踣れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, '我民よ汝らその中よりいで各ヱホバの烈しき怒をまぬかれてその命を救へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, '汝ら心を弱くする勿れ此地にてきく所の浮言によりて畏るる勿れ浮言は此年も來り次の年も亦きたらん此地に强暴あり宰者と宰者とあひ攻むることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, '故に視よ我バビロンの偶像を罰する日來らんその全地は辱められ其殺さるる者は悉くその中に踣れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, '然して天と地とその中にあるところのすべての者はバビロンの事の爲に歡び歌はんそは敗壞者北の方より此處に來ればなりヱホバこれをいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'バビロンがイスラエルの殺さるる者を踣せし如く全地の殺さるる者バビロンに踣るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, '劍を逃るる者よ往け止る勿れ遠方よりヱホバを憶えヱルサレムを汝らの心に置くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, '罵言をきくによりて我ら羞づ異邦人ヱホバの室の聖處にいるによりて我らの面には羞恥盈つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'この故にヱホバいひたまふ視よわがその偶像を罰する日いたらん傷けられたる者はその全國に呻吟べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'たとひバビロン天に昇るとも其城を高くして堅むるとも敗壞者我よりいでて彼らにいたらんとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'バビロンに號咷の聲ありカルデヤ人の地に大なる敗壞あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'ヱホバ、バビロンをほろぼし其中に大なる聲を絕したまふ其波濤は巨水のごとくに鳴りその聲は響わたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, '破滅者これに臨みバビロンにいたる其勇士は執へられ其弓は折らるヱホバは施報をなす神なればかならず報いたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'われその牧伯等と博士等と督宰等と勇士とを醉せん彼らは永き寢にいりて目を醒すことあらじ萬軍のヱホバと名くる王これをいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, '萬軍のヱホバかくいひたまふバビロンの闊き石垣は悉く毀たれその高き門は火に焚れん斯民の勞苦は徒となるべし民は火のために憊れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'これマアセヤの子なるネリヤの子セラヤがユダの王ゼデキヤとともに其治世の四年にバビロンに往くときにあたりて豫言者ヱレミヤがこれに命ぜし言なりこのセラヤは侍從の長なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'ヱレミヤ、バビロンにのぞまんとする諸の災を書にしるせり是即ちバビロンの事につきて錄せる此すべての言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'ヱレミヤ、セラヤにいひけるは汝バビロンに往しとき愼みてこの諸の言を讀め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, '而して汝いふべしヱホバよ汝はこの處を滅し人と畜をいはず凡て此處に住む者なからしめて窮なくこれを荒地となさんと此處にむかひていひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, '汝この書を讀畢りしとき之に石をむすびつけてユフラテの中に投いれよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, '而していふべしバビロンは我これに災菑をくだすによりて是しづみて復おこらざるべし彼らは絕はてんと/此まではヱレミヤの言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'ゼデキヤは位に即きしとき二十一歳なりしがヱルサレムに於て十一年世ををさめたりその母の名はハムタルといひてリブナのヱレミヤの女なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'ゼデキヤはヱホヤキムが凡てなしたる如くヱホバの目の前に惡をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'すなはちヱホバ、ヱルサレムとユダとを怒りて之をその前より棄てはなちたまふ/是に於てゼデキヤ、バビロンの王に叛けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'ゼデキヤの世の九年十月十日にバビロンの王ネブカデネザルその軍勢をひきゐてヱルサレムに攻めきたり之に向ひて陣をはり四周に戌樓を建て之を攻めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'かくこの邑攻圍まれてゼデキヤ王の十一年にまでおよびしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'その四月九日にいたりて城邑のうち饑ること甚だしくなり其地の民食物をえざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, '是をもて城邑つひに打破られたれば兵卒は皆逃て夜の中に王の園の邊なる二個の石垣の間の門より城邑をぬけいで平地の途に循ひておちゆけり時にカルデヤ人は城邑を圍みをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, '茲にカルデヤ人の軍勢王を追ひゆきヱリコの平地にてゼデキヤに追付けるにその軍勢みな彼を離れて散りしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'カルデヤ人王を執へて之をハマテの地のリブラにをるバビロンの王の所に曳きゆきければ王彼の罪をさだめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'バビロンの王すなはちゼデキヤの子等をその目の前に殺さしめユダの牧伯等を悉くリブラに殺さしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'またゼデキヤの目を抉さしめたり斯てバビロンの王かれを銅索に繋ぎてバビロンに携へゆきその死る日まで獄に置けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'バビロン王ネブカデネザルの世の十九年の五月十日バビロンの王の前につかふる侍衞の長ネブザラダン、ヱルサレムにきたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'ヱホバの室と王の室を燒き火をもてヱルサレムのすべての室と大なる諸の室を燒けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'また侍衞の長と偕にありしカルデヤ人の軍勢ヱルサレムの四周の石垣を悉く毀てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, '侍衞の長ネブザラダンすなはち民のうちの貧乏者城邑の中に餘れる者およびバビロンの王に降りし人と民の餘れる者を擄へ移せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, '但し侍衞の長ネブザラダンその地のある貧者を遺して葡萄を耕る者となし農夫となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'カルデヤ人またヱホバの室の銅の柱と洗盥の臺と銅の海を碎きてその銅を悉くバビロンに運び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'また鍋と火鑪と燭剪と鉢と匙およびすべて用ふるところの銅器を取れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, '侍衞の長もまた洗盥と火盤と鉢と鍋と燭臺と匙と斝など凡て金銀にて作れる者を取り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'またソロモン王がヱホバの室に造りしところの二つの柱と一の海と臺の下なる十二の銅の牛を取れりこのもろもろの銅の重は稱る可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'この柱は高さ十八キユビトなり又紐をもてその周圍を測るに十二キユビトあり指四本の厚にして空なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'その上に銅の頂ありその頂の高さは五キユビトその周圍は銅の網子と石榴にて飾れり他の柱とその石榴も之におなじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'その四方に九十六の石榴あり網子の上なるすべての石榴の數は百なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, '侍衞の長は祭司の長セラヤと第二の祭司ゼパニヤと三人の門守を執へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'また兵卒を督る一人の寺人と王の前にはべるもののうち城邑にて遇しところの者七人とその地の民を募る軍勢の長なる書記と城邑の中にて遇しところの六十人の者を邑よりとらへされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, '侍衞の長ネブザラダンこれらを執へてリブラに居るバビロンの王の許にいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'バビロンの王ハマテの地のリブラにこれを撃ち殺せりかくユダはおのれの地よりとらへ移されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'ネブカデネザルがとらへ移せし民は左の如し第七年にユダ人三千二十三人');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'またネブカデネザルその十八年にヱルサレムより八百三十二人をとらへ移せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'ネブカデネザルの二十三年に侍衞の長ネブザラダン、ユダ人七百四十五人をとらへ移したり其總ての數は四千六百人なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'ユダの王ヱホヤキンがとらへ移されたる後三十七年の十二月二十五日バビロンの王エビルメロダクその治世の一年にユダの王ヱホヤキンを獄よりいだしてその首をあげしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, '善言をもて彼を慰めその位をバビロンに偕に居るところの王等の位よりもたかくし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, '其獄の衣服を易へしむヱホヤキンは一生の間つねに王の前に食せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'かれ其死る日まで一生の間たえず日々の分をバビロンの王よりたまはりて其食物となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'ああ哀しいかな古昔は人のみちみちたりし此都邑 いまは凄しき樣にて坐し 寡婦のごとくになれり 嗟もろもろの民の中にて大いなりし者 もろもろの州の中に女王たりし者 いまはかへつて貢をいるる者となりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, '彼よもすがら痛く泣きかなしみて涙面にながる その戀人の中にはこれを慰むる者ひとりだに無く その朋これに背きてその仇となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'ユダは艱難の故によりまた大いなる苦役のゆゑによりて擄はれゆき もろもろの國に住ひて安息を得ず これを追ふものみな狭隘にてこれに追しきぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'シオンの道路は節會の上り來る者なきがために哀しみ その門はことごとく荒れ その祭司は歎き その處女は憂へ シオンもまた自から苦しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'その仇は首となり その敵は享ゆ その愆の多きによりてヱホバこれをなやませたまへるなり そのわかき子等は擄はれて仇の前にゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'シオンの女よりはその榮華ことごとく離れされり またその牧伯等は草を得ざる鹿のごとくに成り おのれを追ふものの前に力つかれて歩みゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'ヱルサレムはその艱難と窘迫の時むかしの代にありしもろもろの樂しき物を思ひ出づ その民仇の手におちいり誰もこれを助くるものなき時 仇人これを見てその荒はてたるを笑ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'ヱルサレムははなはだしく罪ををかしたれば汚穢たる者のごとくになれり 前にこれを尊とびたる者もその裸體を見しによりて皆これをいやしむ 是もまたみづから嗟き身をそむけて退ぞけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'その汚穢これが裾にあり 彼その終局をおもはざりき 此故に驚ろくまでに零落たり 一人の慰さむる者だに無し ヱホバよわが艱難をかへりみたまへ 敵は勝ほこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, '敵すでに手を伸てその財寳をことごとく奪ひたり 汝さきに異邦人等はなんぢの公會にいるべからずと命じおきたまひしに 彼らが聖所を侵しいるをシオンは見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'その民はみな哀きて食物をもとめ その生命を支へんがために財寳を出して食にかへたり ヱホバよ見そなはし我のいやしめらるるを顧りみたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'すべて行路人よ なんぢら何ともおもはざるか ヱホバその烈しき震怒の日に我をなやましてわれに降したまへるこの憂苦にひとしき憂苦また世にあるべきや考がへ見よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'ヱホバ上より火をくだしわが骨にいれて之を克服せしめ 網を張りわが足をとらへて我を後にむかしめ 我をして終日心さびしくかつ疾わづらはしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'わが愆尤の軛は主の御手にて結ばれ諸の愆あひ纒はりてわが項にのれり 是はわが力をしておとろへしむ 主われを敵たりがたき者の手にわたしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, '主われの中なる勇士をことごとく除き 節會をもよほして我を攻め わが少き人を打ほろぼしたまへり 主酒榨をふむがごとくにユダの處女をふみたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'これがために我なげく わが目やわが目には水ながる わがたましひを活すべき慰さむるものわれに遠ければなり わが子等は敵の勝るによりて滅びうせにき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'シオンは手をのぶれども誰もこれを慰さむる者なし ヤコブにつきてはヱホバ命をくだしてその周圍の民をこれが敵とならしめたまふ ヱルサレムは彼らの中にありて汚れたる者のごとくなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'ヱホバは正し 我その命令にそむきたるなり 一切の民よわれに聽け わが憂苦をかへりみよ わが處女もわかき男も俘囚て往り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'われわが戀人を呼たれども彼らはわれを欺むけり わが祭司およびわが長老は生命を繋がんとて食物を求むる間に都邑の中にて氣息たえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'ヱホバよかへりみたまへ 我はなやみてをり わが膓わきかへり わが心わが衷に顛倒す 我甚しく悖りたればなり 外には劍ありてわが子を殺し 内には死のごとき者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'かれらはわが嗟歎をきけり 我をなぐさむるもの一人だに无し わが敵みなわが艱難をききおよび 汝のこれを爲たまひしを喜こべり 汝はさきに告しらせしその日を來らせたまはん 而して彼らもつひに我ごとくに成るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'ねがはくは彼等が與へし艱難をことごとくなんぢの御前にあらはし 前にわがもろもろの罪愆のために我におこなひし如く彼らにも行ひたまへ わが嗟歎は多くわが心はうれひかなしむなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'ああヱホバ震怒をおこし 黑雲をもてシオンの女を蔽ひたまひ イスラエルの榮光を天より地におとし その震怒の日に己の足凳を心にとめたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, '主ヤコブのすべての住居を呑つくしてあはれまず 震怒によりてユダの女の保砦を毀ち これを地にたふし その國とその牧伯等を辱かしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, '烈しき震怒をもてイスラエルのすべての角を絶ち 敵の前にて己の右の手をひきちぢめ 四面を焚きつくす燃る火のごとくヤコブを焚き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, '敵のごとく弓を張り 仇のごとく右の手を挺て立ち 凡て目に喜こばしきものを滅し シオンの女の幕屋に火のごとくその怒をそそぎたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, '主敵のごとくに成たまひてイスラエルを呑ほろぼし その諸の殿を呑ほろぼし そのもろもろの保砦をこぼち ユダの女の上に憂愁と悲哀を増くはへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, '園のごとく己の幕屋を荒し その集會の所をほろぼしたまへり ヱホバ節會と安息日とをシオンに忘れしめ 烈しき怒によりて王と祭司とをいやしめ棄たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, '主その祭壇を忌棄て その聖所を嫌ひ憎みて その諸の殿の石垣を敵の手にわたしたまへり 彼らは節會の日のごとくヱホバの室にて聲をたつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'ヱホバ、シオンの女の石垣を毀たんと思ひさだめ 繩を張り こぼち進みてその手をひかず 壕と石垣とをして哀しましめたまふ 是らは共に憂ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'その門は地に埋もれ ヱホバその關木をこぼちくだき その王ともろもろの牧伯は律法なき國人の中にあり その預言者はヱホバより異象を蒙らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'シオンの女の長老等は地に坐りて默し 首に灰をかむり 身に麻をまとふ ヱルサレムの處女は首を地に低る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'わが目は涙の爲に潰れんとし わが膓は沸かへり わが肝は地に塗る わが民の女ほろぼされ 幼少ものや乳哺子は疲れはてて邑の街衢に氣息たへなんとすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'かれらは疵を負る者の如く邑のちまたにて氣息たえなんとし 母の懐にその靈魂をそそがんとし 母にむかひて言ふ 穀物と酒とはいづくにあるやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'ヱルサレムの女よ 我なにをもて汝にあかしし 何をもて汝にならべんや シオンの處女よ われ何をもて汝になぞらへて汝をなぐさめんや 汝のやぶれは海のごとく大なり 嗟たれか能く汝を醫さんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'なんぢの預言者は虚しき事と愚なることとなんぢに預言し かつて汝の不義をあらはしてその俘囚をまぬかれしめんとはせざりき その預言するところは唯むなしき重荷および追放たるる根本となるべき事のみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'すべて往來の人なんぢにむかひて手を拍ち ヱルサレムの女にむかひて嘲りわらひ かつ頭をふりて言ふ 美麗の極全地の欣喜ととなへたりし邑は是なるかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'なんぢのもろもろの敵はなんぢに對ひて口を開け あざけり笑ひて切齒をなす 斯て言ふわれら之を呑つくしたり 是われらが望みたりし日なり 我ら已に之にあへり 我らすでに之を見たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'ヱホバはその定めたまへることを成し いにしへより其命じたまひし言を果したまへり ヱホバはほろぼして憐れまず 敵をして汝にかちほこらしめ汝の仇の角をたかくしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'かれらの心は主にむかひて呼はれり シオンの女の墻垣よ なんぢ夜も晝も河の如く涙をながせ みづから安んずることをせず 汝の瞳子を休むることなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'なんぢ夜の初更に起いでて呼さけべ 主の御前に汝の心を水のごとく灌げ 街衢のほとりに饑たふるるなんぢの幼兒の生命のために主にむかひて兩手をあげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'ヱホバよ視たまへ 汝これを誰におこなひしか 願はくは顧みたまへ 婦人おのが實なるその懷き育てし孩兒を食ふべけんや 祭司預言者等主の聖所において殺さるべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'をさなきも老たるも街衢にて地に臥し わが處女も若き男も刄にかかりて斃れたり なんぢはその震怒の日にこれを殺し これを屠りて恤れみたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'なんぢ節會の日のごとくわが懼るるところの者を四方より呼あつめたまへり ヱホバの震怒の日には遁れたる者なく又のこりたる者なかりき わが懷き育てし者はみなわが敵のためにほろぼされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, '我はかれの震怒の笞によりて艱難に遭たる人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'かれは我をひきて黑暗をあゆませ光明にゆかしめたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'まことに屢々その手をむけて終日われを攻なやまし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'わが肉と肌膚をおとろへしめ わが骨を摧き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'われにむかひて患苦と艱難を築きこれをもて我を圍み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'われをして長久に死し者のごとく暗き處に住しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, '我をかこみて出ること能はざらしめわが鏈索を重くしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, '我さけびて助をもとめしとき彼わが祈禱をふせぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, '斫たる石をもてわが道を塞ぎわが途をまげたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'その我に對することは伏て伺がふ熊のごとく潜みかくるる獅子のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'われに路を離れしめ 我をひきさきて獨くるしましめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, '弓を張りてわれを矢先の的となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, '矢筒の矢をもてわが腰を射ぬきたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'われはわがすべての民のあざけりとなり 終日うたひそしらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'かれ我をして苦き物に飽しめ茵蔯を飮しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, '小石をもてわが齒を摧き灰をもて我を蒙ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'なんぢわが靈魂をして平和を遠くはなれしめたまへば我は福祉をわすれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, '是において我みづから言り わが氣力うせゆきぬ ヱホバより何を望むべきところ無しと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'ねがはくは我が艱難と苦楚茵蔯と膽汁とを心に記たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'わがたましひは今なほ是らの事を想ひてわが衷に鬱ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'われこの事を心におもひ起せり この故に望をいだくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'われらの尚ほろびざるはヱホバの仁愛によりその憐憫の盡ざるに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'これは朝ごとに新なり なんぢの誠實はおほいなるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'わが靈魂は言ふ ヱホバはわが分なり このゆゑに我彼を待ち望まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'ヱホバはおのれを待ち望む者とおのれを尋ねもとむる人に恩惠をほどこしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'ヱホバの救拯をのぞみて靜にこれを待は善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, '人わかき時に軛を負は善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'ヱホバこれを負せたまふなれば獨坐して默すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, '口を塵につけよ あるひは望あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'おのれを撃つ者に頬をむけ 充足れるまでに恥辱をうけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'そは主は永久に棄ることを爲たまはざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'かれは患難を與へ給ふといへどもその慈悲おほいなればまた憐憫を加へたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, '心より世の人をなやましかつ苦しめ給ふにはあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, '世のもろもろの俘囚人を脚の下にふみにじり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, '至高者の面の前にて人の理を抂げ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, '人の詞訟を屈むることは主のよろこび給はざるところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, '主の命じたまふにあらずば誰か事を述んにその事即ち成んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, '禍も福もともに至高者の口より出るにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, '活る人なんぞ怨言べけんや 人おのれの罪の罰せらるるをつぶやくべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, '我等みづからの行をしらべかつ省みてヱホバに歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, '我ら天にいます神にむかひて手とともに心をも擧べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'われらは罪ををかし我らは叛きたり なんぢこれを赦したまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'なんぢ震怒をもてみづから蔽ひ 我らを追攻め殺してあはれまず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, '雲をもてみづから蔽ひ 祈禱をして通ぜざらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'もろもろの民の中にわれらを塵埃となしたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, '敵は皆われらにむかひて口を張れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, '恐懼と陷阱また暴行と滅亡我らに來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'わが民の女の滅亡によりてわが眼には涙の河ながる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'わが目は斷ず涙をそそぎて止ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, '天よりヱホバの臨み見て顧みたまふ時にまで至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'わが邑の一切の女等の故によりてわが眼はわが心をいたましむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, '故なくして我に敵する者ども鳥を追ごとくにいたく我をおひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'わが生命を坑の中にほろぼし わが上に石を投かけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'また水わが頭の上に溢る 我みづから言り滅びうせぬと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'ヱホバよ われ深き坑の底より汝の名を呼り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'なんぢ我が聲を聽たまへり わが哀歎と祈求に耳をおほひたまふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'わが汝を龥たりし時なんぢは近よりたまひて恐るるなかれと宣へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, '主よなんぢはわが靈魂の訴を助け伸べ わが生命を贖ひ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'ヱホバよ なんぢは我がかうむりたる不義を見たまへり 願はくは我に正しき審判を與へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'なんぢは彼らが我を怨み われを害せんとはかるを凡て見たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'ヱホバよなんぢは彼らが我を詈り 我を害せんとはかるを凡て聞たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'かの立て我に逆らふ者等の言語およびその終日われを攻んとて運らす謀計もまた汝これを聞たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'ねがはくは彼らの起居をかんがみたまへ 我はかれらに歌ひそしらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'ヱホバよ なんぢは彼らが手に爲すところに循がひて報をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'かれらをして心くらからしめたまはん なんぢの呪詛かれらに歸せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'なんぢは震怒をもてかれらを追ひ ヱホバの天の下よりかれらをほろぼし絶たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'ああ黄金は光をうしなひ純金は色を變じ 聖所の石はもろもろの街衢の口に投すてられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'ああ精金にも比ぶべきシオンの愛子等は陶噐師の手の作なる土の器のごとくに見做る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, '山犬さへも乳房をたれてその子に乳を哺す 然るにわが民の女は殘忍荒野の鴕鳥のごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, '乳哺兒の舌は渇きて上顎にひたと貼き 幼兒はパンをもとむるも擘てあたふる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, '肥甘物をくらひ居りし者はおちぶれて街衢にあり 紅の衣服にて育てられし者も今は塵堆を抱く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, '今我民の女のうくる愆の罰はソドムの罪の罰よりもおほいなり ソドムは古昔人に手を加へらるることなくして瞬く間にほろぼされしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'わが民の中なる貴き人は從前には雪よりも咬潔に乳よりも白く 珊瑚よりも躰紅色にしてその形貌のうるはしきこと藍玉のごとくなりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'いまはその面くろきが上に黑く 街衢にあるとも人にしられず その皮は骨にひたと貼き 乾きて枯木のごとくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, '劍にて死る者は饑て死る者よりもさいはひなり そは斯る者は田圃の產物の罄るによりて漸々におとろへゆき刺れし者のごとくに成ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'わが民の女のほろぶる時には情愛ふかき婦人等さへも手づから己の子等を煮て食となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'ヱホバその憤恨をことごとく洩し 烈しき怒をそそぎ給ひ シオンに火をもやしてその基礎までも燒しめ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, '地の諸王も世のもろもろの民もすべてヱルサレムの門に仇や敵の打いらんとは信ぜざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, '斯なりしはその預言者の罪によりその祭司の愆によれり かれらは即ち正しき者の血をその邑の中にながしたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, '今かれらは盲人のごとく街衢にさまよひ 身は血にて汚れをれば人その衣服にふるるあたはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '人かれらに向ひて呼はり言ふ 去れよ穢らはし 去れ去れ觸るなかれと 彼らはしり去りて流離ば異邦人の中間にても人々また言ふ 彼らは此に寓るべからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'ヱホバ怒れる面をもてこれを散し給へり 再びこれを顧みたまはじ 人々祭司の面をも尊ばず長老をもあはれまざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'われらは賴まれぬ救援を望みて目つかれおとろふ 我らは俟ゐたりしが救拯をなすこと能はざる國人を待をりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, '敵われらの脚をうかがへば我らはおのれの街衢をも歩くことあたはず 我らの終ちかづけり 我らの日つきたり 即ち我らの終きたりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, '我らを追ふものは天空ゆく鷲よりも迅し 山にて我らを追ひ 野に伏てわれらを伺ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'かの我らが鼻の氣息たる者ヱホバに膏そそがれたるものは陷阱にて執へられにき 是はわれらが異邦にありてもこの蔭に住んとおもひたりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'ウズの地に住むエドムの女よ悦び樂しめ 汝にもまたつひに杯めぐりゆかん なんぢも醉て裸になるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'シオンの女よ なんぢが愆の罰はをはれり 重ねてなんぢを擄へゆきたまはじ エドムの女よ なんぢの愆を罰したまはん 汝の罪を露はしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'ヱホバよ我らにありし所の事をおもひたまへ 我らの恥辱をかへりみ觀たまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'われらの產業は外國人に歸し われらの家屋は他國人の有となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'われらは孤子となりて父あらず われらの母は寡婦にひとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'われらは金を出して自己の水を飮み おのれの薪を得るにも價をはらふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'われらを追ふ者われらの頸に迫る 我らは疲れて休むことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, '食物を得て饑を凌がんとてエジプト人およびアッスリヤ人に手を與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'われらの父は罪ををかして已に世にあらず 我らその罪を負ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, '奴僕等われらを制するに誰ありて我らを之が手よりすくひ出すものなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, '荒野の刀兵の故によりて我ら死を冒して食物を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, '饑饉の烈しき熱氣によりてわれらの皮膚は爐のごとく熱し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'シオンにて婦人等をかされユダの邑々にて處女等けがさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, '侯伯たる者も敵の手にて吊され 老たる者の面も尊とばれず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, '少き者は石磨を擔はせられ 童子は薪を負ふてよろめき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, '長老は門にあつまることを止め 少き者はその音樂を廢せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, '我らが心の快樂はすでに罷み われらの跳舞はかはりて悲哀となり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'われらの冠冕は首より落たり われら罪ををかしたれば禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'これが爲に我らの心うれへ これらのために我らが目くらくなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'シオンの山は荒はて 山犬はその上を歩くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'ヱホバよなんぢは永遠に在す なんぢの御位は世々かぎりなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, '何とて我らを永く忘れ われらを斯ひさしく棄おきたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'ヱホバよねがはくは我らをして汝に歸らしめたまへ われら歸るべし 我らの日を新にして昔日の日のごとくならしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'さりとも汝まつたく我らを棄てたまひしや 痛くわれらを怒りゐたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, '第三十年四月の五日に我ケバル河の邊にてかの擄うつされたる者の中にをりしに天ひらけて我神の異象を見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, '是ヱコニヤ王の擄ゆかれしより第五年のその月の五日なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, '時にカルデヤ人の地に於てケバル河の邊にてヱホバの言祭司ブシの子エゼキエルに臨めりヱホバの手かしこにて彼の上にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, '我見しに視よ烈き風大なる雲および燃る火の團塊北より出きたる又雲の周圍に輝光ありその中よりして火の中より熱たる金族のごときもの出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, '其火の中に四箇の生物にて成る一箇の形あり其狀は是のごとし即ち人の象あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, '各四の面あり各四の翼あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'その足は直なる足その足の跖は犢牛の足の跖のごとくにして磨ける銅のごとくに光れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'その生物の四方に翼の下に人の手ありこの四箇の物皆面と翼あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'その翼はたがひに相つらなれりその往ときに回轉ずして各その面の向ふところに行く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'その面の形は人の面のごとし四箇の者右には獅子の面あり四箇の者左には牛の面あり又四箇の者鷲の面あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'その面とその翼は上にて分るその各箇の翼二箇は彼と此と相つらなり二箇はその身を覆ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, '各箇その面の向ふところへ行き靈のゆかんとする方に行く又行にまはることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'その生物の形は爇る炭の火のごとく松明のごとし火生物の中に此彼に行き火輝きてその火の中より電光いづ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'その生物奔りて電光の如くに往來す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, '我生物を觀しに生物の近邊にあたりてその四箇の面の前に地の上に輪あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, '其輪の形と作は黄金色の玉のごとしその四箇の形は皆同じその形と作は輪の中に輪のあるがごとくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'その行く時は四方に行く行にまはることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'その輪輞は高くして畏懼かり輪輞は四箇ともに皆遍く目あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, '生物の行く時は輪その傍に行き生物地をはなれて上る時は輪もまた上る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, '凡て靈のゆかんとする所には生物その靈のゆかんとする方に往く輪またその傍に上る是生物の靈輪の中にあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, '此の行く時は彼もゆき此の止る時は彼も止り此地をはなれて上る時は輪も共にあがる是生物の靈輪の中にあればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, '生物の首の上に畏しき水晶のごとき穹蒼ありてその首の上に展開る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, '穹蒼の下に其翼直く開きて此と彼とあひ連る又各二箇の翼ありその各の二箇の翼此方彼方にありて身をおほふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, '我その行く時の羽聲を聞に大水の聲のごとく全能者の聲のごとし其聲音の響は軍勢の聲のごとしその立どまる時は翼を垂る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'その首の上なる穹蒼の上より聲ありその立どまる時は翼を垂る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, '首の上なる穹蒼の上に靑玉のごとき寶位の狀式ありその寶位の狀式の上に人のごとき者在す、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, '又われその中と周圍に磨きたる銅のごとく火のごとくなる者を見る其人の腰より上も腰より下も火のごとくに見ゆ其周圍に輝光あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'その周圍の輝光は雨の日に雲にあらはるる虹のごとしヱホバの榮光かくのごとく見ゆ我これを見て俯伏したるに語る者の聲あるを聞く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, '彼われに言たまひけるは人の子よ起あがれ我なんぢに語はんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, '斯われに言給ひし時靈われにきたりて我を立あがらしむ爰に我その我に語りたまふを聞くに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'われに言たまひけるは人の子よ我なんぢをイスラエルの子孫に遣すすなはち我に叛ける叛逆の民につかはさん彼等とその先祖我に悖りて今日にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'その子女等は厚顏にして心の剛愎なる者なり我汝をかれらに遣す汝かれらに主ヱホバかくいふと告べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, '彼等は悖逆る族なり彼等は之を聽も之を拒むも預言者の己等の中にありしを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, '汝人の子よたとひ薊と棘汝の周圍にあるとも亦汝蠍の中に住ともこれを懼るるなかれその言をおそるるなかれ夫かれらは悖逆る族なり汝その言をおそるるなかれ其面に慄くなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, '彼等は悖逆る族なり彼らこれを聽もこれを拒むも汝吾言をかれらに告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, '人の子よわが汝に言ところを聽け汝かの悖逆る族のごとく悖るなかれ汝の口を開きてわが汝にあたふる者をくらふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, '時に我見に吾方に伸たる手ありて其中に卷物あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, '彼これをわが前に開けり卷物は裏と表に文字ありて上に嗟嘆と悲哀と憂患とを錄す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, '彼また我に言たまひけるは人の子よ汝獲るところの者を食へ此卷物を食ひ往てイスラエルの家に告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, '是に於て我口をひらけばその卷物を我に食はしめて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, '我にいひ給ひけるは人の子よわが汝にあたふる此卷物をもて腹をやしなへ膓にみたせよと我すなはち之をくらふに其わが口に甘きこと蜜のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, '彼また我にいひたまひけるは人の子よイスラエルの家にゆきて吾言を之につげよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, '我なんぢを唇の深き舌の重き民につかはすにあらずイスラエルの家につかはすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, '汝がその言語をしらざる唇の深き舌の重き多くの國人に汝をつかはすにあらず我もし汝を彼らに遣さば彼等汝に聽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, '然どイスラエルの家は我に聽ことを好まざれば汝に聽ことをせざるべしイスラエルの全家は厚顏にして心の剛愎なる者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, '視よ我かれらの面のごとく汝の面をかたくしかれらの額のごとく汝の額を堅くせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, '我なんぢの額を金剛石のごとくし磐よりも堅くせり彼らは背逆る族なり汝かれらを懼るるなかれ彼らの面に戰慄くなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, '又われに言たまひけるは人の子よわが汝にいふところの凡の言を汝の心にをさめ汝の耳にきけよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, '往てかの擄へ移されたる汝の民の子孫にいたりこれに語りて主ヱホバかく言たまふと言へ彼ら聽も拒むも汝然すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, '時に靈われを上に擧しが我わが後に大なる響の音ありてヱホバの榮光のその處より出る者は讚べきかなと云ふを聞けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'また生物の互にあひ連る翼の聲とその傍にある輪の聲および大なる響の音を聞く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, '靈われを上にあげて携へゆけば我苦々しく思ひ心を熱くして往くヱホバの手強くわが上にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, '爰に我ケバル河の邊にてテラアビブに居るかの擄移れたる者に至り驚きあきれてその坐する所に七日俱に坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, '七日すぎし後ヱホバの言われにのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '人の子よ我なんぢを立てイスラエルの家の爲に守望者となす汝わが口より言を聽き我にかはりてこれを警むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, '我惡人に汝かならず死べしと言んに汝かれを警めず彼をいましめ語りその惡き道を離れしめて之が生命を救はずばその惡人はおのが惡のために死んされど其血をば我汝の手に要むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, '然ど汝惡人を警めんに彼その惡とその惡き道を離れずば彼はその惡の爲に死ん汝はおのれの靈魂を救ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, '又義人その義事をすてて惡を行はんに我躓礙をその前におかば彼は死べし汝かれを警めざれば彼はその罪のために死てそのおこなひし義き事を記ゆる者なきにいたらん然ば我その血を汝の手に要むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, '然ど汝もし義き人をいましめ義き人に罪ををかさしめずして彼罪を犯すことをせずば彼は警戒をうけたるがためにかならずその生命をたもたん汝はおのれの靈魂を救ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, '茲にヱホバの手かしこにてわが上にあり彼われに言たまひけるは起て平原にいでよ我そこにて汝にかたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, '我すなはち起て平原に往にヱホバの榮光わがケバル河の邊にて見し榮光のごとく其處に立ければ俯伏たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, '時に靈われの中にいりて我を立あがらせ我にかたりていふ往て汝の家にこもれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, '人の子よ彼等汝に繩をうちかけ其をもて汝を縛らん汝はかれらの中に出ゆくことを得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, '我なんぢの舌を上咢に堅く着しめて汝を啞となし彼等を警めざらしむべし彼等は悖逆る族なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, '然ど我汝に語る時は汝の口をひらかん汝彼らにいふべし主ヱホバかく言たまふ聽者は聽べし拒む者は拒むべし彼等は悖逆る族なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '人の子よ汝磚瓦をとりて汝の前に置きその上にヱルサレムの邑を畵け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, '而して之を取圍み之にむかひて雲梯を建て壘を築き陣營を張り邑の周圍に破城槌を備へて之を攻めよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, '汝また鐵の鍋を取り汝と邑の間に置て鐵の石垣となし汝の面を之に向よ斯この邑圍まる汝之を圍むべし是すなはちイスラエルの家にあたふる徴なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, '又汝左側を下にして臥しイスラエルの家の罪を其上に置よ汝が斯臥ところの日の數は是なんぢがその罪を負ふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, '我かれらが罪を犯せる年を算へて汝のために日の數となす即ち三百九十日の間汝イスラエルの家の罪を負ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, '汝これを終なば復右側を下にして臥し四十日の間ユダの家の罪を負ふべし我汝のために一日を一年と算ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, '汝ヱルサレムの圍に面を向け腕を袒して其の事を預言すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, '視よ我索を汝にかけて汝の圍の日の終るまで右左に動くことを得ざらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, '汝 小麥 大麥 豆 扁豆 粟および裸麥を取て之を一箇の器にいれ汝が横はる日の數にしたがひてこれを食とせよ即ち三百九十日の間これを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, '汝食を權りて一日に二十シケルを食へ時々これを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, '又汝水を量りて一ヒンの六分一を飮め時々これを飮むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, '汝大麥のパンの如くにして之を食へ即ち彼等の目のまへにて人の糞をもて之を烘べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'ヱホバいひ給ふ是のごとくイスラエルの民はわが追やらんところの國々においてその汚穢たるパンを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, '是において我いふ嗚呼主ヱホバよわが魂は絕て汚れし事なし我は幼少時より今にいたるまで自ら死し者や裂殺れし者を食ひし事なし又絕て汚れたる肉わが口にいりしことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'ヱホバ我にいひ給ふ我牛の糞をもて人の糞にかふることを汝にゆるす其をもて汝のパンを調ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, '又われに言たまふ人の子よ視よ我ヱルサレムに於て人の杖とするパンを打碎かん彼等は食をはかりて惜みて食ひ水をはかりて驚きて飮まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, '斯食と水と乏しくなりて彼ら互に面を見あはせて駭きその罪に亡びん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '人の子よ汝利き刀を執り之を剃刀となして汝の頭と頷をそり權衡をとりてその毛を分てよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, '而して圍城の日の終る時邑の中にて火をもて其三分の一を燒き又三分の一を取り刀をもて邑の周圍を撃ち三分の一を風に散すべし我刀をぬきて其後を追ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, '汝その毛を少く取りて裾に包み');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, '又その中を取りてこれを火の中になげいれ火をもて之をやくべし火その中より出てイスラエルの全家におよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, '主ヱホバかくいひ給ふ我このヱルサレムを萬國の中におき列邦をその四圍に置けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'ヱルサレムは異邦よりも惡くわが律法に悖り其四圍の國々よりもわが法憲に悖る即ち彼等はわが律法を蔑如にしわが法憲に歩行まざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, '故に主ヱホバかくいひたまふ汝等はその周圍の異邦人よりも甚だしく噪ぎたち吾憲にあゆまず吾法をおこなはず又汝らの周圍なる異邦人の法のごとくに行ふことすらもせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, '是故に主ヱホバかくいひ給ふ視よ我 われは汝を攻め異邦人の目の前にて汝の中に鞫をおこなはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'なんぢの爲せし諸の惡むべき事のために我わが未だ爲ざりしところの事此後ふたたび其ごとく爲ざるべきところの事を汝になさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, '是がために汝の中にて父たる者はその子を食ひ子たる者はその父を食はん我汝の中に鞫をおこなひ汝の中の餘れる者を盡く四方の風に散さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, '是故に主ヱホバいひ給ふ我は活く汝その忌むべき物とその憎むべきところの事とをもてわが聖所を穢したれば我かならず汝を減さん我目なんぢを惜み見ず我なんぢを憐まざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, '汝の三分の一は汝の中において疫病にて死に饑饉にて滅びん又三分の一は汝の四周にて刀に仆れん又三分の一をば我四方の風に散し刀をぬきて其後をおはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, '斯我怒を洩し盡しわが憤を彼らの上にかうむらせて心を安んぜん我わが憤を彼らの上に洩し盡す時は彼ら我ヱホバの熱心をもてかたりたる事をしるに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, '我汝を荒地となし汝の周圍の國々の中に汝を笑柄となし凡て往來の人の目に斯あらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, '我怒と憤と重き責をもて鞫を汝に行ふ時は汝はその周圍の邦々の笑柄となり嘲となり警戒となり驚懼とならん我ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, '即ち我饑饉の惡き矢を彼等に放たん是は滅亡すための者なり我汝らを滅さんために之を放つべし我なんぢらの上に饑饉を増しくはへ汝らが杖とするところのパンを打碎かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, '我饑饉と惡き獸を汝等におくらん是汝をして子なき者とならしめん又疫病と血なんぢの間に行わたらん我刀を汝にのぞましむべし我ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '人の子よ汝の面をイスラエルの山々にむけて預言して言ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'イスラエルの山よ主ヱホバの言を聽け主ヱホバ山と岡と谷と平原にむかひて斯いひたまふ視よ我劍を汝等に遣り汝らの崇邱を滅ぼす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, '汝等の壇は荒され日の像は毀たれん我汝らの中の殺さるる者をして汝らの偶像の前に仆れしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, '我イスラエルの子孫の尸骸をその偶像の前に置ん汝らの骨をその壇の周圍に散さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, '凡て汝らの住ところにて邑々は滅され崇邱は荒されん斯して汝らの壇は壞れて荒れ汝らの偶像は毀たれて滅び汝等の日の像は斫たふされ汝等の作りし者は絕されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, '又殺さるる者なんぢらの中に仆れん汝等これに由て吾ヱホバなるを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, '我或者を汝らにのこす即ち劍をのがれて異邦の中にをる者國々の中にちらさるる者是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, '汝等の中の逃れたる者はその擄ゆかれし國々において我を記念ふに至らん是は我かれらの我をはなれたるその姦淫をなすの心を挫き且かれらの姦淫を好みてその偶像を慕ふところの目を挫くに由てなり而して彼等はその諸の憎むべき者をもて爲たるところの惡のために自ら恨むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, '斯彼等はわがヱホバなるを知るにいたらん吾がこの災害をかれらになさんと語しことは徒然にならざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, '主ヱホバかく言たまふ汝手をもて撃ち足を踏ならして言へ嗚呼凡てイスラエルの家の惡き憎むべき者は禍なるかな皆刀と饑饉と疫病に仆るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, '遠方にある者は疫病にて死に近方にある者は刀に仆れん又生存りて身を全うする者は饑饉に死ぬべし斯我わが憤怒を彼等に洩しつくすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, '彼等の殺さるる者その偶像の中にありその壇の周圍にあり諸の高岡にあり諸の山の頂にあり諸の靑樹の下にあり諸の茂れる橡樹の下にあり彼等が馨しき香をその諸の偶像にささげたる處にあらん其時汝等はわがヱホバなるを知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, '我手をかれらの上に伸べ凡てかれらの住居ところにて其地を荒してデブラの野にもまさる荒地となすべし是によりて彼らはわがヱホバなるを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '汝人の子よ主ヱホバかくいふイスラエルの地の末期いたる此國の四方の境の末期來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, '今汝の末期いたる我わが忿怒を汝に洩らし汝の行にしたがひて汝を鞫き汝の諸の憎むべき物のために汝を罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'わが目は汝を惜み見ず我なんぢを憫まず汝の行の爲に汝を罰せん汝のなせし憎むべき事の報汝の中にあるべし是によりて汝等はわがヱホバなるを知らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, '主ヱホバかくいひ給ふ視よ災禍あり非常災禍きたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, '末期きたる其末期きたる是起りて汝に臨む視よ來る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, '此地の人よ汝の命數いたる時いたる日ちかし山々には擾亂のみありて喜樂の聲なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, '今我すみやかに吾憤恨を汝に蒙らせわが怒氣を汝に洩しつくし汝の行爲にしたがひて汝を鞫き汝の諸の憎むべきところの事のために汝を罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'わが目は汝を惜み見ず我汝をあはれまず汝の行のために汝を罰せん汝の爲し憎むべき事の果報汝の中にあるべし是によりて汝等は我ヱホバの汝を撃なるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, '視よ日きたる視よ來れり命數いたりのぞむ杖花咲き驕傲茁す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, '暴逆おこりて惡の杖と成る彼等もその群衆もその驕奢も皆失んかれらの中には何も殘る者なきにいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, '時きたる日ちかづけり買者は喜ぶなかれ賣者は思ひわづらふなかれ怒その群衆におよぶべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, '賣者は假令その生命ながらふるともその賣たる者に歸ることあたはじ此地の全の群衆をさすところの預言は廢らざるべければなり其惡の中にありて生命を全うする者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, '人衆ラツパを吹て凡て預備をなせども戰にいづる者なし其はわが怒その全の群衆におよべばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, '外には劍あり内には疫病と饑饉あり田野にをる者は劍に死なん邑の中にをる者は饑饉と疫病これをほろぼすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'その中の逃るる者は逃れて谷の鴿のごとくに山の上にをりて皆その罪のために悲しまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, '手みな弱くなり膝みな水となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, '彼等は麻の衣を身にまとはん恐懼かれらを蒙まん諸の面には羞あらはれ諸の首は髮をそりおとされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, '彼等その銀を街にすてん其金はかれらに塵芥のごとくなるべしヱホバの怒の日にはその金銀もかれらを救ふことあたはざるなり是等はその心魂を滿足せしめず其腹を充さず唯彼等をつまづかせて惡におとしいるる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, '彼の美しき飾物を彼等驕傲のために用ひ又これをもてその憎べき偶像その憎むべき物をつくれり是をもて我これを彼らに芥とならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, '我これを外國人にわたして奪はしめ地の惡人にわたして掠めしめん彼等すなはちこれを汚すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, '我かれらにわが面を背くべければ彼等わが密たる所を汚さん強暴人其處にいりてこれを汚すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, '汝鏈索を作れよ死にあたる罪國に滿ち暴逆邑に充たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, '我國々の中の惡き者等を招きて彼らの家を奪しめん我強者の驕傲を止めんその聖所は汚さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, '滅亡きたれり彼等平安を求むれども得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, '災害に災害くははり注進に注進くははる彼等預言者に默示を求めん律法は祭司の中に絕え謀略は長老の中に絕べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, '王は哀き牧伯は驚惶を身に纏ひ國の民の手は慄へん我その行爲に循ひて彼らを處置ひその審判に循ひて彼らを罰せん彼等は我ヱホバなるを知にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, '爰に六年の六月五日に我わが家に坐しをりユダの長老等わがまへに坐りゐし時主ヱホバの手われの上に降れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, '我すなはち視しに火のごとくに見ゆる形象あり腰より下は火のごとく見ゆ腰より上は光輝て見え燒たる金屬の色のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, '彼手のごとき者を伸て吾が頭髮を執りしかば靈われを地と天の間に曳あげ神の異象の中に我をヱルサレムに携へゆき北にむかへる内の門の口にいたらしむ其處に嫉妬をおこすところの嫉妬の像たてり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, '彼處にイスラエルの神の榮光あらはる吾が平原にて見たる異象のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, '彼われに言たまふ人の子よ目をあげて北の方をのぞめと我すなはち目をあげて北の方を望むに視よ壇の門の北にあたりてその入口に此嫉妬の像あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, '彼また我にいひたまふ人の子よ汝かれらが爲ところ即ちイスラエルの家が此にてなすところの大なる憎むべき事を見るや我これがために吾が聖所をはなれて遠くさるべし汝身を轉らせ復大なる憎むべき事等を見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, '斯て彼われを領て庭の門にいたりたまふ我見しに其壁に一の穴あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, '彼われに言たまふ人の子よ壁を穿てよと我すなはち壁を鑿つに一箇の戸あるを視る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, '茲に彼われにいひ給ひけるは入て彼等が此になすところの惡き憎むべき事等を見よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, '便ち入りて見るに諸の爬蟲と憎むべき獸畜の形およびイスラエルの家の諸の偶像その周圍の壁に畵きてあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'イスラエルの家の長老七十人その前に立てりシヤパンの子ヤザニヤもかれらの中に立ちてあり各手に香爐を執るその香の煙雲のごとくにのぼれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, '彼われに言たまひけるは人の子よ汝イスラエルの家の長老等が暗におこなふ事即ちかれらが各人その偶像の間におこなふ事を見るや彼等いふヱホバは我儕を見ずヱホバこの地を棄てたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'また我に言たまはく汝身を轉らせ復かれらが爲すところの大なる憎むべき事等を見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, '斯て彼我を携てヱホバの家の北の門の入口にいたるに其處に婦女等坐してタンムズのために哭をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, '彼われに言たまふ人の子よ汝これを見るや又身を轉らせよ汝これよりも大なる憎むべき事等を見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, '彼また我を携てヱホバの家の内庭にいたるにヱホバの宮の入口にて廊と壇の間に二十五人ばかりの人その後をヱホバの宮にむけ面を東にむけ東にむかひて日の前に身を鞠めをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, '彼われに言たまふ人の子よ汝これを見るやユダの家はその此におこなふところの憎むべき事等をもて瑣細き事となすにや亦暴逆を國に充して大に我を怒らす彼等は枝をその鼻につくるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, '然ば我また怒をもて事をなさん吾目はかれらを惜み見ず我かれらを憫まじ彼等大聲にわが耳に呼はるとも我かれらに聽じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, '斯て彼大聲に吾耳に呼はりて言たまふ邑を主どる者等各々剪滅の器具を手にとりて前み來れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, '即ち北にむかへる上の門の路より六人の者おのおの打壞る器具を手にとりて來る其中に一人布の衣を着筆記人の墨盂を腰におぶる者あり彼等來りて銅の壇の傍に立てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, '爰にイスラエルの神の榮光その居るところのケルブの上より起あがりて家の閾にいたり彼の布の衣を着て腰に筆記人の墨盂をおぶる者を呼ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, '時にヱホバかれに言たまひけるは邑の中ヱルサレムの中を巡れ而して邑の中に行はるるところの諸の憎むべき事のために歎き哀しむ人々の額に記號をつけよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, '我聞に彼またその他の者等にいひたまふ彼にしたがひて邑を巡りて撃てよ汝等の目人を惜み見るべからず憐れむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, '老人も少者も童女も孩子も婦人も悉く殺すべし然ど身に記號ある者には觸べからず先わが聖所より始めよと彼等すなはち家の前にをりし老人より始む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, '彼またかれらに言たまふ家を汚し死人をもて庭に充せよ汝等往けよと彼等すなはち出ゆきて邑の中に人を撃つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, '彼等人を撃ちける時我遺されたれば俯伏て叫び言ふ嗚呼主ヱホバよ汝怒をヱルサレムにもらしてイスラエルの殘餘者を悉くほろぼしたまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, '彼われに言たまひけるはイスラエルとユダの家の罪甚だ大なり國には血盈ち邑には邪曲充つ即ち彼等いふヱホバは此地を棄てたりヱホバは見ざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, '然ば亦わが目かれらを惜み見ず我かれらを憐まじ彼らの行ふところを彼等の首に報いん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, '時にかの布の衣を着て腰に筆記人の墨盂をおぶる人復命まをして言ふ汝が我に命じたまひしごとく爲たりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, '茲に我見しにケルビムの首の上なる穹蒼に靑玉のごとき者ありて寶位の形に見ゆ彼そのケルビムの上にあらはれたまひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'かの布の衣を着たる人に告て言たまひけるはケルビムの下なる輪の間に入りて汝の手にケルビムの間の炭火を盈し之を邑に散すべしとすなはち吾目の前にて其處に入しが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, '其人の入る時ケルビムは家の右に立をり雲その内庭に盈り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, '茲にヱホバの榮光ケルブの上より昇りて家の閾にいたる又家には雲滿ちその庭にはヱホバの榮光の輝光盈てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, '時にケルビムの羽音外庭に聞ゆ全能の神の言語たまふ聲のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, '彼布の衣を着たる人に命じて輪の間ケルビムの間より火を取れと言たまひければ即ち入りて輪の傍に立ちけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, '一のケルブその手をケルビムの間より伸てケルビムの間の火を取り之をかの布の衣を着たる人の手に置れたれば彼これを取りて出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'ケルビムに人の手の形の者ありて其翼の下に見ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, '我見しにケルビムの側に四箇の輪あり此ケルブにも一箇の輪あり彼ケルブにも一箇の輪あり輪の式は黄金色の玉のごとくに見ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'その式は四箇みな同じ形にして輪の中に輪のあるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'その行ときは四方に行く行にまはることなし首の向ふところに從ひ行く行にまはることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'その全身その脊その手その翼および輪には四周に徧く目ありその四箇みな輪あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, '我聞に轉回れと輪にむかひてよばはるあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, '其は各々四の面あり第一の面はケルブの面第二の面は人の面第三のは獅子の面第四のは鷲の面なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'ケルビムすなはち昇れり是わがケバル河の邊にて見たるところの生物なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'ケルビムの行く時は輪もその傍に行きケルビム翼をあげて地より飛上る時は輪またその傍を離れず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'その立つときは立ちその上る時は俱に上れりその生物の靈は其等の中にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, '時にヱホバの榮光家の閾より出ゆきてケルビムの上に立ちければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'ケルビムすなはちその翼をあげ出ゆきてわが目の前にて地より飛のぼれり輪はその傍にあり而して遂にヱホバの家の東の門の入口にいたりて止るイスラエルの神の榮光その上にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, '是すなはち吾がケバル河の邊にてイスラエルの神の下に見たるところの生物なり吾そのケルビムなるを知れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, '是等には各々四宛の面あり各箇四の翼あり又人の手のごとき物その翼の下にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'その面の形は吾がケバル河の邊にて見たるところの面なりその姿も身も然り各箇その面にしたがひて行けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, '茲に靈我を擧げてヱホバの室の東の門に我を携へゆけり門は東に向ふ視るにその門の入口に二十五人の人あり我その中にアズルの子ヤザニヤおよびベナヤの子ペラテヤ即ち民の牧伯等を見る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, '彼われに言たまひけるは人の子よ此邑において惡き事を考へ惡き計謀をめぐらす者は此人々なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, '彼等いふ家を建ることは近からず此邑は鍋にして我儕は肉なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, '是故にかれらに預言せよ人の子よ預言すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, '時にヱホバの靈わが上に降りて我にいひ給ひけるはヱホバかく言ふと言べしイスラエルの家よ汝等は斯いへり汝等の心におこる所の事は我これを知るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, '汝等は此邑に殺さるる者を増し死人をもて街衢に充せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, '是故に主ヱホバ斯いふ汝等が邑の中に置くところのその殺されし者はすなはち肉にして邑は鍋なり然ど人邑の中より汝等を曳いだすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, '汝等は刀劍を懼る我劍を汝等にのぞましめんと主ヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, '我なんぢらを其中よりひき出し外國人の手に付して汝等に罰をかうむらすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, '汝等は劍に踣れん我イスラエルの境にて汝等を罰すべし汝等は是によりてわがヱホバなるを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, '是は汝らの鍋とならず汝らはその中の肉たることを得ざるなりイスラエルの境にて我汝らに罰をかうむらすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, '汝ら即ちわがヱホバなるを知にいたらん汝らはわが憲法に遵はずわが律法を行はずしてその周圍の外國人の慣例のごとくに事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, '斯てわが預言しをる時にベナヤの子ペラテヤ死たれば我俯向に伏て大聲に叫び嗚呼主ヱホバよイスラエルの遺餘者を盡く滅ぼさんとしたまふやといふに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'ヱホバの言われに臨みていふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '人の子よ汝の兄弟汝の兄弟たる者は汝の親族の人々にして即ちイスラエルの全家全躰なりヱルサレムに居る人々は是にむかひて汝等は遠くヱホバをはなれて居れ此地はわれらの所有としてあたへらると言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, '是故に汝言ふべしヱホバかく言ひたまふ我かれらを遠く逐やりて國々に散したればその往る國々に於て暫時の間かれらの聖所となると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, '是故に言ふべし主ヱホバかく言たまふ我なんぢらを諸の民の中より集へ汝等をその散されたる國々より聚めてイスラエルの地を汝らに與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, '彼等は彼處に到りその諸の汚たる者とその諸の憎むべき者を彼處より取除かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, '我かれらに唯一の心を與へ新しき靈を汝らの衷に賦けん我かれらの身の中より石の心を取さりて肉の心を與ヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, '彼らをしてわが憲法に遵はしめ吾律法を守りて之を行はしむべし彼らはわが民となり我はかれらの神とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, '然どその汚れたる者とその憎むべき者の心をもておのれの心となす者等は我これが行ふところをその首に報ゆべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, '茲にケルビムその翼をあぐ輪その傍にありイスラエルの神の榮光その上に在す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'ヱホバの榮光つひに邑の中より昇りて邑の東の山に立てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, '時に靈われを擧げ神の靈に由りて異象の中に我をカルデヤに携へゆきて俘囚者の所にいたらしむ吾見たる異象すなはちわれを離れて昇れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'かくて我ヱホバの我にしめしたまひし言を盡く俘囚者に告たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'ヱホバの言また我にのぞみて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '人の子よ汝は背戻る家の中に居る彼等は見る目あれども見ず聞く耳あれども聞ず背戻る家なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, '然ば人の子よ移住の器具を備へかれらの目の前にて晝の中に移れ彼らの目の前にて汝の處より他の處に移るべし彼等は背戻る家なれども或は見て考ふることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, '汝移住の器具のごとき器具を彼等の目の前にて晝の中に持いだせ而して移住者の出ゆくがごとく彼等の目の前にて宵の中に出ゆくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, '即ちかれらの目の前にて壁をやぶりて之を其處より持いだせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, '彼らの目の前にてこれを肩に負ひ黑暗の中にこれを持いだすべし汝の面を掩へ地を見るなかれ我汝を豫兆となしてイスラエルの家に示すなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, '我すなはち命ぜられしごとく爲し移住の器具のごとき器具を晝の中に持いだし又宵に手をもて壁をやぶり黑暗の中にこれを持いだし彼らの目の前にてこれを肩に負り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, '明旦におよびてヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '人の子よ背戻る家なるイスラエルの家汝にむかひて汝なにを爲やと言しにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, '汝かれらに言ふべし主ヱホバかく言たまふこの負荷はヱルサレムの君主および彼等の中なるイスラエルの全家に當るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, '汝また言ふべし我は汝等の豫兆なりわが爲るごとく彼等然なるべし彼等は擄へうつされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, '彼らの中の君主たる者黑暗のうちに物を肩に載て出ゆかん彼等壁をやぶりて其處より物を持いだすべし彼はその面を覆ひて土地を目に見ざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, '我わが網を彼の上に打かけん彼はわが羅にかかるべし我かれをカルデヤ人の地に曳ゆきてバビロンにいたらしめん然れども彼はこれを見ずして其處に死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, '凡て彼の四周にありて彼を助くる者およびその軍兵は皆我これを四方に散し刀刃をぬきて其後をおふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, '吾がかれらを諸の民の中に散し國々に撒布さん時にいたりて彼らは我のヱホバなるをしるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, '但し我かれらの中に僅少の人を遺して劍と饑饉と疫病を免れしめ彼らをしてそのおこなひし諸の憎むべき事をその到るところの民の中に述しめん彼等はわがヱホバなるを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '人の子よ汝發震て食物を食ひ戰慄と恐懼をもて水を飮め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, '而してこの地の民に言べし主ヱホバ、ヱルサレムの民のイスラエルにをる者に斯いひたまふ彼等は懼れて食物を食ひ驚きて水を飮にいたるべし是はその地凡てその中に住る者の暴逆のために富饒をうしなひて荒地となるが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, '人の住る邑々は荒はて國は滅亡ぶべし汝等すなはち我がヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '人の子よイスラエルの國の中に汝等いふ日は延び默示はみな空しくなれりと是何の言ぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, '是故に汝彼等に言べし主ヱホバかくいひ給ふ我この言を止め彼等をして再びこれをイスラエルの中に言ことなからしめん即ち汝かれらに言へ其日とその諸の默示の言は近づけりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'イスラエルの家には此後重ねて空浮き默示と虛僞の占卜あらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, '夫我はヱホバなり我わが言をいださん吾いふところは必ず成んかさねて延ることあらじ背戻る家よ汝等が世にある日に我言を發して之を成すべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '人の子よ視よイスラエルの家言ふ彼が見たる默示は許多の日の後の事にして彼は遙後の事を預言するのみと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, '是故にかれらに言ふべし主ヱホバかくいひたまふ我言はみな重ねて延ず吾がいへる言は成べしと主ヱホバこれを言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '人の子よ預言を事とするイスラエルの預言者にむかひて預言せよ彼のおのれの心のままに預言する者等に言ふべし汝らヱホバの言を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, '主ヱホバかくいひ給ふ彼の何をも見ずして己の心のままに行ふところの愚なる預言者は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'イスラエルよ汝の預言者は荒墟にをる狐のごとくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, '汝等は破壞口を守らずまたイスラエルの家の四周に石垣を築きてヱホバの日に防ぎ戰はんともせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, '彼らは虛浮者および虛妄の占卜を見る彼等はヱホバいひたまふと言ふといへどもヱホバはかれらを遣さざるなり然るに彼らその言の成らんことを望む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, '汝らは空しき異象を見虛妄の占卜を宣べ吾が言ふことあらざるにヱホバいひ給ふと言ふにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, '是故に主ヱホバかくいひたまふ汝等空虛き事を言ひ虛僞の物を見るによりて我なんぢらを罰せん主ヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, '我手はかの虛浮き事を見虛僞の事を卜ひいふところの預言者等に加はるべし彼等はわが民の會にをらずなりイスラエルの家の籍にしるされずイスラエルの地にいることをえざるべし汝等すなはち吾のヱホバなるをしるにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'かれらは吾民を惑し平安あらざるに平安といふ又わが民の屏を築くにあたりて彼等灰砂をもて之を圬る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, '是故にその灰砂を圬る者に是は圮るべしと言へ大雨くだらん雹よ降れ大風よ吹べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, '視よ屏は圮る然ば人々汝等が用ひて圬たる灰砂は何處にあるやと汝等に言ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, '即ち主ヱホバかく言たまふ我憤恨をもて大風を吹せ忿怒をもて大雨を注がせ憤恨をもて雹を降せてこれを毀つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, '我なんぢらが灰砂をもて圬たる屏を毀ちてこれを地に倒しその基礎を露にすべし是すなはち圮れん汝等はその中にほろびて吾のヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, '斯われその屏とこれを灰砂にてぬれる者とにむかひてわが憤恨を洩しつくして汝等にいふべし屏はあらずなり又灰砂にてこれを圬る者もあらずなれりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, '是すなはちイスラエルの預言者等なり彼等はヱルサレムにむかひて預言をなし其處に平安のあらざるに平安の默示を見たりといへり主ヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, '人の子よ汝の民の女等の其心のままに預言する者に汝の面をむけ之にむかひて預言し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, '言べし主ヱホバかくいひたまふ吾手の節々の上に小枕を縫つけ諸の大さの頭に帽子を造り蒙せて靈魂を獵んとする者は禍なるかな汝等はわが民の靈魂を獵て己の靈魂を生しめんとするなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, '汝等小許の麥のため小許のパンのために吾民の前にて我を汚しかの僞言を聽いるる吾民に僞言を陳て死べからざる者を死しめ生べからざる者を生しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, '是故に主ヱホバかくいひたまふ我汝等が用ひて靈魂を獵ところの小枕を奪ひ靈魂を飛さらしめん我なんぢらの臀より小枕を裂とりて汝らが獵ところの靈魂を釋ち其靈魂を飛さらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, '我なんぢらの帽子を裂き吾民を汝らの手より救ひいださん彼等はふたたび汝等の手に陷りて獵れざるべし汝らは吾ヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, '汝等虛僞をもて義者の心を憂へしむ我はこれを憂へしめざるなり又汝等惡者の手を強くし之をしてその惡き道を離れかへりて生命を保つことをなさしめず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, '是故に汝等は重ねて虛浮き物を見ることを得ず占卜をなすことを得ざるに至るべし我わが民を汝らの手より救ひいださん汝等すなはちわがヱホバなるを知にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, '爰にイスラエルの長老の中の人々我にきたりて吾前に坐しけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '人の子よこの人々はその偶像を心の中に立しめ罪に陷いるるところの障礙をその面の前に置なり我あに是等の者の求を容べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, '然ば汝かれらに告げて言ふべし主ヱホバかくいひたまふ凡そイスラエルの家の人のその心の中に偶像を立しめその面のまへに罪に陷いるるところの障礙を置きて預言者に來る者には我ヱホバその偶像の多衆にしたがひて應をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, '斯して我イスラエルの家の人の心を執へん是かれら皆その偶像のために我を離れたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, '是故にイスラエルの家に言ふべし主ヱホバかくいひたまふ汝等悔い汝らの偶像を棄てはなるべし汝等面を回らしてその諸の憎むべき物を離れよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, '凡てイスラエルの家およびイスラエルに寓るところの外國人若われを離れてその偶像を心の中に立しめ其面の前に罪に陷るるところの障礙をおきて預言者に來りその心のままに我に求むる時は我ヱホバわが心のままにこれに應ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, '即ち我面をその人にむけこれを滅して兆象となし諺語となし之をわが民の中より絕さるべし汝等これによりて我がヱホバなるを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'もし預言者欺かれて言を出すことあらば我ヱホバその預言者を欺けるなり我かれの上にわが手を伸べ吾民イスラエルの中より彼を絕さらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, '彼等その罪を負ふべしその預言者の罪はかの問求むる者の罪のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, '是イスラエルの民をして重ねて我を離れて迷はざらしめ重ねてその諸の愆に汚れざらしめんため又かれらの吾民となり我の彼らの神とならんためなり主ヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '人の子よ國もし悖れる事をおこなひて我に罪を犯すことあり我手をその上に伸て其杖とたのむところのパンを打碎き饑饉を之におくりて人と畜とをその中より絕ことある時には');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, '其處にかのノア、ダニエル、ヨブの三人あるも只其義によりて己の生命を救ふことをうるのみなり主ヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, '我もし惡き獸を國に行めぐらしめて之を子なき處となし荒野となして其獸のために其處を通る者なきに至らん時には');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, '主ヱホバ言ふ我は活く此三人そこにをるもその子女を救ふことをえず只その身を救ふことを得るのみ國は荒野となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, '又は我劍を國に臨ませて劍よ國を行めぐるべしと言ひ人と畜をそこより絕さらん時には');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, '主ヱホバいふ我は活く此三人そこにをるもその子女をすくふことをえず只その身をすくふことを得るのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, '又われ疫病を國におくり血をもてわが怒をその上にそそぎ人と畜をそこより絕さらん時には');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, '主ヱホバいふ我は活くノア、ダニエル、ヨブそこにをるもその子女を救ふことをえず只その義によりて己の生命を救ふことを得るのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, '主ヱホバかくいひたまふ然ばわが四箇の嚴しき罰すなはち劍と饑饉と惡き獸と疫病をヱルサレムにおくりて人と畜をそこより絕さらんとする時は如何にぞや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, '其中に逃れて遺るところの男子女子あり彼等携へ去らるべし彼ら出ゆきて汝等の所にいたらん汝らかれらの行爲と擧動を見ば吾がヱルサレムに災をくだせし事につきて心をやすむるにいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, '汝ら彼らの行爲と擧動を見ばこれがためにその心をやすむるにいたりわがこれに爲たる事は皆故なくして爲たるにあらざるなるをしるにいたらん主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '人の子よ葡萄の樹森の中にあるところの葡萄の枝なんぞ他の樹に勝るところあらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, '其木物をつくるに用ふべけんや又人これを用ひて器をかくる木釘を造らんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, '視よ是は火に投いれられて燃ゆ火もしその兩の端を燒くあり又その中間焦たらば爭でか物をつくるに勝べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, '是はその全かる時すらも物を造るに用ふべからざれば况て火のこれを焚焦したる時には爭で物をつくるに用ふべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, '是故に主ヱホバかく言たまふ我森の樹の中なる葡萄の樹を火になげいれて焚く如くにヱルサレムの民をも然するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, '我面をかれらに向けて攻む彼らは火の中より出たれども火なほこれを燒つくすべし我面をかれらにむけて攻むる時に汝らは我のヱホバなるをしらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, '彼等悖逆る事をおこなひしに由て我かの地を荒地となすべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '人の子よヱルサレムに其憎むべき事等を示して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, '言ふべし主ヱホバ、ヱルサレムに斯いひたまふ汝の起本汝の誕生はカナンの地なり汝の父はアモリ人汝の母はヘテ人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, '汝の誕生を言んに汝の生れし日に汝の臍帶を斷ことなく又水にて汝を洗ひ潔むることなく鹽をもて汝を擦ることなく又布に裹むことなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, '一人も汝を憐み見憫をもて是等の事の一をも汝になせし者なし汝の生れたる日に人汝の生命を忌て汝を野原に棄たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, '我汝のかたはらを通りし時汝が血の中にをりて踐るるを見汝が血の中にある時汝に生よと言り即ち我なんぢが血の中にある時に汝に生よといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, '我野の百卉のごとくに汝を増して千萬となせり汝は生長て大きくなり美しき姿となるにいたり乳は堅くなり髮は長たりしが衣なくして裸なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, '茲に我汝の傍を通りて汝を見に今は汝の時汝の愛せらるべき時なりければ我衣服の裾をもて汝を覆ひ汝の恥るところを蔽し而して汝に誓ひ汝に契約をたてたり汝すなはち吾所屬となれり主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, '斯て我水をもてなんぢを洗ひ汝の血を滌ぎおとして膏を汝にぬり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, '文繡あるものを着せ皮の鞋を穿たしめ細布を蒙らせ絹をもて汝の身を罩めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, '而して飾物をもて汝をかざり腕環をなんぢの手にはめ金索を汝の項にかけしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, '鼻には鼻環 耳には耳環 首には華美なる冠冕をほどこせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, '汝すなはち金銀をもて身を飾り細布と絹および文繡をその衣服となし麥粉と蜜と油とを食へり汝は甚だ美しくして遂に榮えて王の權勢に進みいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, '汝の美貌のために汝の名は國々にひろまれり是わが汝にほどこせしわれの飾物によりて汝の美麗極りたればなり主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, '然るに汝その美麗を恃み汝の名によりて姦淫をおこなひ凡て其傍を過る者と縱恣に姦淫をなしたり是その人の所屬となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, '汝おのれの衣服をとりて崇邱を彩り作りその上に姦淫をおこなへり是爲べからず有べからざる事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, '汝はわが汝にあたへし金銀の飾の品を取り男の像を造りて之と姦淫をおこなひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, '汝の繡衣を取りて之に纒ひ吾の膏と香をその前に陳へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, '亦わが汝にあたへし我の食物我が用ひて汝をやしなふところの麥粉油および蜜を其前に陳へて馨しき香氣となせり是事ありしと主ヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, '汝またおのれの我に生たる男子女子をとりてこれをその像にそなへて食はしむ汝が姦淫なほ小き事なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, '汝わが子等を殺し亦火の中を通らしめてこれに献ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, '汝その諸の憎むべき事とその姦淫とをおこなふに當りて汝が若かりし日に衣なくして裸なりしことおよび汝が血のうちにをりて蹈れしことを想はざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, '主ヱホバまた言たまふ汝は禍なるかな禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, '汝その諸の惡をおこなひし後街衢街衢に樓をしつらひ臺を造り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'また路の辻々に臺をつくりて汝の美麗を汚辱むることを爲し凡て傍を過るところの者に足をひらきて大に姦淫をおこなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, '汝かの肉の大なる汝の隣人エジプトの人々と姦淫をおこなひ大に姦淫をなして我を怒らせたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, '我手を汝の上にのべて汝のたまはる分を減し彼の汝を惡み汝の淫なる行爲を羞るところのペリシテ人の女等の心に汝をまかせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, '然るに汝は厭ことなければ亦アツスリヤの人々と姦淫をおこなひしが之と姦淫をおこなひたるも尚厭ことなかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, '汝また大に姦淫をおこなひてカナンの國カルデヤに迄およびしが是にても尚厭ことなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, '主ヱホバいひたまふ汝の心如何に戀煩ふにや汝この諸の事を爲り是氣隨なる遊女の行爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, '汝道の辻々に樓をしつらひ衢々に臺を造りしが金錢を輕んじたれば娼妓のごとくならざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, '夫淫婦はその夫のほかに他人と通ずるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, '人は凡て娼妓に物を贈るなるに汝はその諸の戀人に物をおくり且汝と姦淫せんとて四方より汝に來る者に報金を與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, '汝は姦淫をおこなふに當りて他の婦と反す即ち人汝を戀求むるにあらざるなり汝金錢を人にあたへて人金錢を汝にあたへざるは是その相反するところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, '然ば娼妓よヱホバの言を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, '主ヱホバかく言たまふ汝金銀を撒散し且汝の戀人と姦淫して汝の恥處を露したるに由り又汝の憎むべき諸の偶像と汝が之にささげたる汝の子等の血の故により');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, '視よ我汝が交れる諸の戀人および凡て汝が戀たる者並に凡て汝が惡みたる者を集め四方よりかれらを汝の所に集め汝の恥處を彼らに現さん彼ら汝の恥處を悉く見るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, '我姦淫を爲せる婦および血をながせる婦を鞫くがごとくに汝を鞫き汝をして忿怒と嫉妬の血とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, '我汝を彼等の手に付せば彼等汝の樓を毀ち汝の臺を倒しなんぢの衣服を褫取り汝の美しき飾を奪ひ汝をして衣服なからしめ裸にならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, '彼等群衆をひきゐて汝の所にのぼり石をもて汝を撃ち劍をもて汝を切さき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, '火をもて汝の家を焚き多くの婦女の目の前にて汝を鞫かん斯われ汝をして姦淫を止しむべし汝は亦ふたたび金錢をあたふることなからん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, '我ここに於て汝に對するわが怒を息め汝にかかはるわが嫉妬を去り心をやすんじて復怒らざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, '主ヱホバいひたまふ汝その若かりし日の事を記憶えずしてこの諸の事をもて我を怒らせたれば視よ我も汝の行ふところを汝の首に報ゆべし汝その諸の憎むべき事の上に此惡事をなしたるにあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, '視よ諺語をもちふる者みな汝を指てこの諺を用ひ言ん母のごとくに女も然りと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, '汝の母はその夫と子女を棄たり汝はその女なり汝の姉妹はその夫と子女を棄たり汝はその姉妹なり汝の母はヘテ人汝の父はアモリ人なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, '汝の姉はサマリヤなり彼その女子等とともに汝の左に住む汝の妹はソドムなり彼その女子等とともに汝の右に住む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, '汝は只少しく彼らの道に歩み彼らの憎むべきところの事等を行ひしのみにあらず汝の爲る事は皆かれらのよりも惡かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, '主ヱホバ言たまふ我は活く汝の妹ソドムと其女子らが爲しところは汝とその女子らが爲しところの如くはあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, '汝の妹ソドムの罪は是なり彼は傲り食物に飽きその女子らとともに安泰にをり而して難める者と貧しき者を助けざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'かれらは傲りわが前に憎むべき事をなしたれば我見てかれらを掃ひ除けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'サマリヤは汝の罪の半分ほども罪を犯さざりき汝は憎むべき事等を彼らよりも多く行ひ増し汝の爲たる諸の憎むべき事のために汝の姉妹等をして義きが如くならしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, '然ば汝が曾てその姉妹等の蒙るべき者と定めたるところの恥辱を汝もまた蒙れよ汝が彼等よりも多くの憎むべき事をなしたるその罪の爲に彼等は汝よりも義くなれり然ば汝も辱を受け恥を蒙れ是は汝その姉妹等を義き者となしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, '我ソドムとその女等の俘囚をかへしサマリヤとその女等の俘囚をかへさん時に其と同じ擄はれたる汝の俘囚人を歸し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, '汝をして恥を蒙らしめ汝が凡て爲たるところの事を羞しむべし汝かく彼らの慰とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, '汝の姉妹ソドムとその女子等は舊の樣に歸りサマリヤとその女子等は舊の樣に歸らん又汝と汝の女子等も舊の樣にかへるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, '汝はその驕傲れる日には汝の姉妹ソドムの事を口に述ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, '汝の惡の露れし時まで即ちスリアの女子等と凡て汝の周圍の者ペリシテ人の女等が四方より汝を嬲りて辱しめし時まで汝は是のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'ヱホバいひたまふ汝の淫なる行爲と汝のもろもろの憎むべき事とは汝みづからこれを身に負ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, '主ヱホバかく言たまふ誓言を輕んじて契約をやぶりたるところの汝には我汝の爲るところにしたがひて爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, '我汝の若かりし日に汝になせし契約を記憶え汝と限りなき契約をたてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, '汝その姉妹の汝より大なる者と小き者とを得る時にはおのれの行爲をおぼえて羞ん彼等は汝の契約に屬する者にあらざれども我かれらを汝にあたへて女となさしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, '我汝と契約をたてん汝すなはち吾のヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, '我なんぢの凡て行ひしところの事を赦す時には汝憶えて羞ぢその恥辱のために再び口を開くことなかるべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, '爰にヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '人の子よ汝イスラエルの家に謎をかけ譬言を語りて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, '言べし主ヱホバかく言たまふ大なる翼長き羽ありて種々の色の毛の滿たる大鷲レバノンに來りて香柏の梢を採り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, '其芽の巓を摘みカナンの地にこれを持きたりて商人の邑に置きけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, '又その地の種をとりて之を種田に播けりすなはち之を水の多き處にもちゆきて柳のごとくにこれを樹しに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, '成長ちて丈卑き垂さがりたる葡萄樹となり其枝は鷲にむかひその根は鷲の下にあり遂に葡萄樹となりて芽をふき葉を出す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, '此に又大なる翼多くの羽ある一箇の大鷲ありしがその葡萄樹根をこれにむかひて張り枝をこれにむかひて伸べ之をしてその植りたる地の外より水を灌がしめんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, '抑是を善き圃に多くの水の旁に植たるは根を張り實をむすびて盛なる葡萄樹とならしめんためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'なんぢ主ヱホバかく言ふといふべし是旺盛になるや鷲その根を拔きその果を絕ちて之を枯しめざらんや其芽の若葉は皆枯ん之を根より擧るには強き腕と多くの人を用ふるにおよばざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, '是は樹られたれども旺盛にならんや東風これに當らば枯果ざらんや是その生たるところの地に枯べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '背ける家に言ふべし汝等此の何たるを知ざるかと又言へ視よバビロンの王ヱルサレムに來りその王とその牧伯等を執へてこれをバビロンに曳ゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, '彼また王の族の一人を取てこれと契約を立て誓言をなさしめ又國の強き者等を執へゆけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, '是この國を卑くして自ら立つことを得ざらしめその人をして契約を守りてこれを堅うせしめんがためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, '然るに彼これに背きて使者をエジプトに遣し馬と多くの人を己におくらしめんとせり彼旺盛にならんや是を爲る者逃るることをえんや彼その契約をやぶりたり爭で逃るることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, '主ヱホバいひたまふ我は活く必ず彼は己を王となしたる彼王の處に偕にをりてバビロンに死べし彼その王の誓言を輕んじ其契約を破りたるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, '夫壘を築き雲梯を建てて衆多の人を殺さんとする時にはパロ大なる軍勢と衆多の人をもて彼のために戰爭をなさじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, '彼は誓言を輕んじて契約を破る彼手を與へて却て此等の事をなしたれば逃るることを得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, '故に主ヱホバかく言たまふ我は活く彼が我の誓言を輕んじ我の契約をやぶりたる事を必ずかれの首にむくいん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, '我わが網をかれの上にうちかけ彼をわが羅にとらへてバビロンに曳ゆき彼が我にむかひて爲しところの叛逆につきて彼を鞫くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, '彼の諸の軍隊の逃脱者は皆刀に仆れ生殘れる者は八方に散さるべし汝等は我ヱホバがこれを言しなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, '主ヱホバかく言たまふ我高き香柏の梢の一を取てこれを樹ゑその芽の巓より若芽を摘みとりて之を高き勝れたる山に樹べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'イスラエルの高山に我これを植ん是は枝を生じ果をむすびて榮華なる香柏となり諸の類の鳥皆その下に棲ひその枝の蔭に住はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, '是に於て野の樹みな我ヱホバが高き樹を卑くし卑き樹を高くし綠なる樹を枯しめ枯木を綠ならしめしことを知ん我ヱホバこれを言ひ之を爲なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '汝等なんぞイスラエルの地に於て此諺語を用ひ父等酸き葡萄を食ひたれば子等の齒齼くと言ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, '主ヱホバいふ我は生く汝等ふたたびイスラエルに於てこの諺語をもちふることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, '夫凡の靈魂は我に屬す父の靈魂も子の靈魂も我に屬するなり罪を犯せる靈魂は死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, '若人正義して公道と公義を行ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, '山の上に食をなさず目をあげてイスラエルの家の偶像を仰がず人の妻を犯さず穢れたる婦女に近づかず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, '何人をも虐げず質物を還し物を奪はずその食物を饑る者に與へ裸なる者に衣を着せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, '利を取て貸さず息を取ず手をひきて惡を行はず眞實の判斷を人と人の間になし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'わが法憲にあゆみ又吾が律例を守りて眞實をおこなはば是義者なり彼は生べし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, '然ど彼子を生んにその子暴き者にして人の血をながし是の如き事の一箇を行ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, '是をば凡て行はずして山の上に食をなし人の妻を犯し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, '惱める者と貧しき者を虐げ物を奪ひ質物を還さず目をあげて偶像を仰ぎ憎むべき事をおこなひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, '利をとりて貸し息を取ば彼は生べきや彼は生べからず彼この諸の憎むべき事をなしたれば必ず死べしその血はかれに歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, '又子生れんに其子父のなせる諸の罪を視しかども視て斯有ことを行はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, '山の上に食をなさず目をあげてイスラエルの家の偶像を仰がず人の妻を犯さず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, '何人をも虐げず質物を存留めず物を奪はず饑る者にその食物を與へ裸なる者に衣を着せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'その手をひきて惱める者を苦めず利と息を取ずわが律法を行ひわが法度に歩まば彼はその父の惡のために死ことあらじ必ず生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'その父は甚だしく人を掠めその兄弟を痛く虐げその民の中に善らぬ事をなしたるに由てその惡のために死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'しかるに汝等は子なんぞ父の惡を負ざるやと言ふ夫子は律法と公義を行ひわが凡ての法度を守りてこれを行ひたれば必ず生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, '罪を犯せる靈魂は死べし子は父の惡を負ず父は子の惡を負ざるなり義人の義はその人に歸し惡人の惡はその人に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, '然ど惡人もしその凡て行ひしところの惡を離れわが諸の法度を守り律法と公義を行ひなばかならず生ん死ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'その爲しところの咎は皆記念られざるべしその爲し義き事のために彼は生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, '主ヱホバ言たまふ我爭で惡人の死を好まんや寧彼がその道を離れて生んことを好まざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, '若義人その義をはなれて惡を行ひ惡人の爲る諸の憎むべき事をなさば生べきや其なせし義き事は皆記念られざるべし彼はその爲る咎とその犯せる罪とのために死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, '然るに汝等主の道は正しからずと言ふ然ばイスラエルの家よ聽け吾道正しからざるやその正しからざる者は汝らの道にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, '若義人その義をはなれて惡を爲し其がために死ることあらば是その爲る惡のために死るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, '若惡人その爲る惡をはなれて律法と公義を行はばその靈魂を生しむることをえん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, '彼もし視てその行ひし諸の咎を離れなば必ず生ん死ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, '然るにイスラエルの家は主の道は正しからずといふイスラエルの家よわが道正しからざるやその正しからざる者は汝らの道にあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, '主ヱホバいひ給ふ是故に我汝らをば各その道にしたがひて審くべし汝らその諸の咎を悔改めよ然らば惡汝らを躓かせて滅ぼすことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, '汝等その行ひし諸の罪を棄去り新しき心と新しき靈魂を起すべしイスラエルの家よ汝らなんぞ死べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, '我は死者の死を好まざるなり然ば汝ら悔て生よ主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '汝イスラエルの君等のために哀の詞をのべて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, '言ふべし汝の母なる牝獅は何故に牡獅の中に伏し小獅の中にその子を養ふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, '彼その一の子を育てたれば小獅となりて食を攫ことを學ひ遂に人を食へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, '國々の人これの事を聞きこれを陷阱にて執へ鼻環をほどこしてこれをエジプトの地にひきいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, '牝獅姑く待しがその望を失ひしを見たれば又一個の子を取てこれを小獅とならしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, '是すなはち牝獅の中に歩みて小獅となり食を攫ことを學ひしが亦人を食ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, '其寡婦をしりその邑々を滅せりその咆哮聲によりてその地とその中に盈る者荒たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, '是をもて四方の國人その國々より攻來り網をこれにうちかけ陷阱にてこれを執へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, '鼻環をほどこして籠にいれ之をバビロンの王の許に曳いたりて城の中に携へ入れ其聲を再びイスラエルの山々に聞えざらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, '汝の母は汝の血にして水の側に植たる葡萄樹のごとし水の多きがために結實多く蔓はびこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, '是に強き枝ありて君王等の杖となすべし是の長は雲に至りその衆多の枝のために高く聳えて見へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, '然るに是怒をもて拔れて地に擲たる東風その實を吹乾かしその強き枝は折れて枯れ火に焚る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, '今これは荒野にて乾ける水なき地に植りてあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'その枝の芽より火いでてその果を燒けば復強き枝の君王等の杖となるべき者其になし是哀の詞なり哀の詞となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, '七年の五月十日にイスラエルの長老の中の人々ヱホバに問んとて來りてわが前に坐しけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'ヱホバの言我にのぞみて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '人の子よイスラエルの長老等に告て之にいふべし主ヱホバかく言ふ汝等我に問んとて來れるや主ヱホバいふ我は活く我汝らの問を容じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, '汝かれらを鞫かんとするや人の子よ汝かれらを鞫かんとするや彼等の先祖等のなしたる憎むべき事等をかれらに知しめて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, '言べし主ヱホバかくいふ我イスラエルを選みヤコブの家の裔にむかひてわが手をあげエジプトの地にて我をかれらに知せかれらにむかひて吾手をあげて我は汝らの神ヱホバなりと言し日');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'その日に我かれらにむかひて吾手をあげエジプトの地よりかれらをいだし吾がかれらのために求め得たるその乳と蜜の流るる地に導かんとせり是諸の地の中の美しき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, '而して我かれらに言けらく各人その目にあるところの憎むべき事等を棄てよエジプトの偶像をもてその身を汚すなかれ我は汝らの神ヱホバなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, '然るに彼らは我に背きて我に聽したがふことを好まざりき彼等一人もその目にあるところの憎むべき者を棄てずエジプトの偶像を棄てざりしかば我エジプトの地の中において吾憤恨をかれらに注ぎわが忿怒をかれらに洩さんと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, '然れども我わが名のために事をなして彼らをエジプトの地より導きいだせり是吾名の異邦人等の前に汚されざらんためなりその異邦人等の中に彼等居り又その前にて我おのれを彼等に知せたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'すなはち我エジプトの地より彼等を導き出して曠野に携ゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'わが法憲をこれに授けわが律法をこれに示せり是は人の行ひて之に由て生べき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, '我また彼らに安息日を與へて我と彼らの間の徴となしかれらをして吾ヱホバが彼らを聖別しを知しめんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, '然るにイスラエルの家は曠野にて我に背き人の行ひて之によりて生べき者なるわが法度にあゆまず吾が律法を輕んじ大に吾が安息日を汚したれば曠野にてわが憤恨をかれらに注ぎてこれを滅さんと言ひたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, '我わが名のために事をなせり是わが彼らを導きいだして見せしところの異邦人等の目のまへにわが名を汚されざらしめんためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, '但し我曠野にて彼らにむかひて吾手をあげ彼らをわが與へしその乳と蜜の流るる地に導かじと誓へり是は諸の地の中の美しき者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, '是かれら心にその偶像を慕ひてわが律法を輕んじ棄てわが法憲にあゆまずわが安息日を汚したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, '然りといへども吾かれらを惜み見てかれらを滅ぼさず曠野にて彼らを絕さざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, '我曠野にてかれらの子等に言り汝らの父の法度にあゆむなかれ汝らの律法を守るなかれ汝らの偶像をもて汝らの身を汚すなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, '我は汝らの神ヱホバなり吾法度にあゆみ吾律法を守りてこれを行ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'わが安息日を聖くせよ是は我と汝らの間の徴となりて汝らをして我が汝らの神ヱホバなるを知しめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, '然るにその子等我にそむき人の行ひてこれによりて活べき者なるわが法度にあゆまず吾律法をまもりて之をおこなはずわが安息日を汚したれば我わが憤恨を彼らにそそぎ曠野にてわが忿怒をかれらに洩さんと言たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, '吾手を翻してわが名のために事をなせり是わが彼らを導き出して見せしところの異邦人等の目のまへにわが名を汚されざらしめんためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, '但し我汝らを國々に散し處々に撒んと曠野にてかれらにむかひて我手を擧たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, '是かれらわが律法を行はずわが法度を輕じわが安息日をけがしその父の偶像を目に慕ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, '我かれらに善らぬ法度を與へかれらが由て活べからざる律法を與へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, '彼らをしてその禮物によりて己の身を汚さしむ即ちかれらその長子をして火の中を通過しめたり是は我彼らを滅し彼らをして我のヱホバなるを知しめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, '然ば人の子よイスラエルの家につげて之にいふべし主ヱホバかくいひたまふ彼らの父等は更にまた不忠の罪ををかし我を瀆せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, '我わが彼らに與へんと手をあげし此地にかれらを導きいれしに彼ら諸の高丘と諸の茂樹を尋ね得てその犠牲を其處に供へその憤らしき禮物をそこに獻げその馨しき佳氣をそこに奉つりその神酒をそこに灌げり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, '我かれらに言り汝らが往ところの崇き處は何なるやと其名は今日にいたるまでバマと言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'この故にイスラエルの家に言ふべし主ヱホバかくいひたまふ汝らの先祖の途をもて汝らはその身を汚し彼等の憎むべき物をしたひてこれと姦淫を行ふにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, '汝等はその禮物を獻げその子女に火の中を通らしめて今日にいたるまで汝らの諸の偶像をもてその身を汚すなり然ばイスラエルの家よ我なんぢらの問を容るべけんや主ヱホバいふ我は活く我は汝らの問を容ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, '汝ら我儕は木と石に事へて異邦人の如くなり國々の宗族のごとくならんと言ば汝らの心に起るところの事は必ず成ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, '主ヱホバいふ我は生く我かならず強き手と伸たる腕をもて怒を注ぎて汝らを治めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, '我強き手と伸たる腕をもて怒を注ぎて汝らを國々より曳いだし汝らが散れたる處々より汝らを集め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, '國々の曠野に汝らを導き其處にて面をあはせて汝らを鞫かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, '主ヱホバいふ我エジプトの曠野にて汝らの先祖等を鞫きしごとくに汝らを鞫くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, '我なんぢらをして杖の下を通らしめ契約の索に汝らを入しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, '汝らの中より背ける者および我に悖れる者を別たんその寓れる地より我かれらをいだすべし彼らはイスラエルの地に來らざるべし汝らすなはち我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, '然ばイスラエルの家よ主ヱホバかくいふ汝等おのおの往てその偶像に事へよ然ど後には汝らかならず我に聽て重てその禮物と偶像をもてわが名を汚さざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, '主ヱホバいふ吾が聖山の上イスラエルの高山の上にてイスラエルの全家その地の者皆我に事へん其處にて我かれらを悦びて受納ん其處にて我なんぢらの獻物および初成の禮物すべて汝らが聖別たる者を求むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, '我汝らを國々より導き出し汝らが散されたる處々より汝らを集むる時馨しき香氣のごとくに汝らを悦びて受納れ汝らによりて異邦人等の目のまへに我の聖ことをあらはすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, '我が汝らをイスラエルの地すなはちわが汝らの先祖等にあたへんと手をあげしところの地にいたらしめん時に汝等は我のヱホバなるを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, '汝らは其身を汚したるところの汝らの途と汝らのもろもろの行爲を彼處にて憶え其なしたる諸の惡き作爲のために自ら恨み視ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'イスラエルの家よ我汝らの惡き途によらず汝らの邪なる作爲によらずして吾名のために汝等を待はん時に汝らは我のヱホバなるを知るにいたらん主ヱホバこれを言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '人の子よ汝の面を南方に向け南にむかひて言を垂れ南の野の森の事を預言せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'すなはち南の森に言ふべしヱホバの言を聽け主ヱホバかく言ふ視よ我なんぢの中に火を燃さん是なんぢの中の諸の靑樹と諸の枯木を焚べしその烈しき火焰消ることなし南より北まで諸の面これがために燒ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, '肉ある者みな我ヱホバのこれを燒しなるを見ん是は消ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, '我是において言り嗚呼主ヱホバよ人われを指て言ふ彼は譬言をもて語るにあらずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'ヱホバの言われにのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '人の子よ汝の面をヱルサレムに向け聖き處々にむかひて言を垂れイスラエルの地にむかひて預言し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'イスラエルの地に言ふべしヱホバかく言ふ視よ我汝を責め吾刀を鞘より拔はなし義者と惡者とを汝の中より絕ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, '我義者と惡者とを汝の中より絕んとすればわが刀鞘より脱出て南より北までの凡て肉ある者を責ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, '肉ある者みな我ヱホバのその刀を鞘より拔はなちしを知らん是は歸りをさまらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, '人の子よ腰の碎くるまでに歎き彼らの目のまへにて痛く歎け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, '人汝に何て歎くやと言ば汝言べし來るところの風聞のためなり心みな鎔け手みな痿え魂みな弱り膝みな水とならん視よ事いたれりかならず成ん主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'ヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, '人の子よ預言して言ふべしヱホバかく言ふ劍あり研ぎ且磨きたる劍あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, '是は大に殺す事をなさんがために研てあり光り閃かんがために磨きてあり我子の杖は萬の樹を藐視ずとて我等喜ぶべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, '是を手に執んために與へて磨かしむ是劍は殺す者の手に付さんために之を研かつ磨かしむるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, '人の子よ叫び哭け其は是わが民の上に臨みイスラエルの諸の牧伯等の上に臨めばなり彼らはわが民とともに劍に仆る故に汝腿を撃べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'その試すでに成る若かの藐視ずるところの杖きたらずば如何ぞや主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, '人の子よ汝預言し手を拍べし劍人を刺透すところの劍三倍に働かん是は人を刺透し大なる者を殺すところの劍にして彼らを責る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, '彼らの心を鎔し礙く物を増んがために我拔身の劍をその諸の門に立つ嗚呼是は光ひらめき脱いでて人を殺さんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, '汝合して右に向へ進んで左に向へ汝の刃の向ふところに隨ヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, '我また吾手を拍ちわが怒を靜めん我ヱホバこれを言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '人の子よバビロンの王の劍の由て來るべき二の途を設けよ其二の途を一の國より出しめて道標の記號を畵き邑の途の首處にこれを畵くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, '汝またアンモンの子孫のラバとユダの堅き城の邑ヱルサレムとに劍のきたるべき途を設けよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'バビロンの王その道の首處その途の岐處に止りて占卜をなし箭を搖りテラピムに問ひ肝を察べをるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, '彼の右にヱルサレムといふ占卜いづ云く破城槌を備へ口をひらきて喊き殺し聲をあげて吶喊を作り門にむかひて破城槌を備へ壘をきづき雲梯を建べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, '是はかれらの目には虛僞の占考と見ゆ聖き誓言かれらに在ばなり然れども彼罪を憶ひおこさしむ即ちかれらは取るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, '是故に主ヱホバかく言ふ汝ら旣にその罪を憶おこさしめて汝らの愆著明になりたれば汝らの罪その諸の行爲に顯る汝ら旣に憶いださるれば必ず手に執へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, '汝刺透さるる者罪人イスラエルの君主よ汝の罪その終を來らしめて汝の罰せらるる日至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, '主ヱホバかく言ふ冕旒を去り冠冕を除り離せ是は是ならざるべし卑き者は高くせられ高き者は卑くせられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, '我顚覆をなし顚覆をなし顚覆を爲ん權威を持べき者の來る時まで是は有ことなし彼に我之を與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, '人の子よ汝預言して言べし主ヱホバ、アンモンの子孫とその嘲笑につきて斯言ふと即ち汝言べし劍あり劍あり是殺すことのために拔てあり滅すことのために磨きありて光ひらめくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, '人なんぢに虛淨を預言し汝に假僞の占考を示して汝をその殺さるる惡人の頸の上に置んとす彼らの罪その終を來らしめて彼らの罰せらるる日いたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'これをその鞘にかへし納めよ汝の造られし處なんぢの生れし地にて我汝を鞫き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'わが怒を汝に斟ぎ吾憤恨の火を汝にむかひて燃し狂暴人滅すことに巧なる者の手に汝を付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, '汝は火の薪となり汝の血は國の中にあらん汝は重ねて憶えらるることなかるべし我ヱホバこれを言ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '人の子よ汝鞫かんとするや此血を流すところの邑を鞫かんとするや汝これにその諸の憎むべき事を示して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, '言へ主ヱホバかく言ふ己の中に血を流してその罰せらるる時を來らせ己の中に偶像を作りてその身を汚すところの邑よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, '汝はその流せる血によりて罪を得その作れる偶像をもて身を汚し汝の日を近づかせすでに汝の年にいたれり是故に我汝を國々の嘲とならしめ萬國の笑とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, '汝に近き者も遠き者も汝が名の汚れたると混亂の多きとを笑はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, '視よイスラエルの君等各その力にしたがひて血を流さんと汝の中にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, '彼ら汝の中にて父母を賤め汝の中にて他國の人を虐げ汝の中にて孤兒と寡婦を惱ますなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, '汝わが聖き物を賤めわが安息日を汚す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, '人を譖づる者血を流さんと汝の中にあり人汝の中にて山の上に食をなし汝の中にて邪淫をおこなひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, '汝の中にてその父の妻に交り汝の中にて月經のさはりに穢れたる婦女を犯す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, '又汝の中にその鄰の妻と憎むべき事をおこなふものあり邪淫をおこなひてその嫁を犯すものありその父の女なる己の姊妹を犯すものあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, '人汝の中にて賄賂をうけて血を流すことをなすなり汝は利と息を取り汝の隣の物を掠め取り又我を忘る主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, '見よ我汝が掠めとる事をなし且血を汝の中に流すによりて我手を拍つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, '我が汝を攻る日には汝の心堅く立ち汝の手強くあることを得んや我ヱホバこれを言ひこれをなすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, '我汝を異邦の中に散し國々の中に播き全く汝の汚穢を取のぞくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, '汝は己の故によりて異邦人の目に汚れたる者と見えん而して汝我のヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '人の子よイスラエルの家は我に渣滓のごとくなれり彼等は凡て爐の中の銅錫鐵鉛のごとし彼らは銀の渣滓のごとく成れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, '此故に主ヱホバかく言ふ汝らは皆渣滓となりたれば視よ我なんぢらをヱルサレムの中に集む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, '人の銀銅鐵鉛錫を爐の中に集め火を吹かけて鎔すが如く我怒と憤をもて汝らを集め入て鎔すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, '即ち我汝らを集め吾怒の火を汝らに吹かけん汝らはその中に鎔ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, '銀の爐の中に鎔るがごとくに汝らはその中に鎔け我ヱホバが怒を汝らに斟ぎしを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '人の子よ是に言ふべし汝は怒の日に日も照らず雨もふらざる地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, '預言者等の徒黨その中にありその食を撕くところの吼ゆる獅子のごとくに彼らは靈魂を呑み財寶と貴き物を取り寡婦をその中に多くす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'その祭司等はわが法を犯しわが聖き物を汚し聖きと聖からざるとの區別をなさず潔きと穢たるとの差別を敎へずその目を掩ひてわが安息日を顧みず我はかれらの中に汚さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'その中にある公伯等は食を撕くところの豺狼のごとくにして血をながし靈魂を滅し物を掠めとらんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'その預言者等は灰砂をもて是等を塗り虛浮物を見僞の占卜を人になしヱホバの告あらざるに主ヱホバかく言たまふと言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, '國の民は暴虐をおこなひ奪ふ事をなし難める者と貧き者を掠め道に反きて他國の人を虐ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, '我一箇の人の國のために石垣を築き我前にあたりてその破壞處に立ち我をして之を滅さしめざるべき者を彼等の中に尋れども得ざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, '主ヱホバいふ是故に我わが怒を彼らに斟ぎわが憤の火をもて彼らを滅し彼らの行爲をその首に報ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '人の子よ爰に二人の婦女あり一人の母の女子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, '彼等エジプトにおいて淫を行ひその少き時に淫を行へり即ち彼處において人かれらの乳を拈り彼處においてその處女の乳房に觸る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'その名は姊はアホラ妹はアホリバと云ふ彼ら我に歸して男子女子を生り彼らの本名はアホラはサマリヤと言ひアホリバはヱルサレムと云ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'アホラは我有たる間に淫を行ひてその戀人等に焦れたり是すなはちその隣なるアツスリヤ人にして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, '紫の衣を着る者牧伯たる者督宰たる者なり是等は皆美麗き秀でたる人馬に乗る者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, '彼凡てアツスリヤの秀でたる者と淫を行ひ且その焦れたる諸の者すなはちその諸の偶像をもてその身を汚せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, '彼またエジプトよりの淫行を捨ざりき即ち彼の少き時に彼ら彼と寢ねその處女の乳房にさはりその淫慾を彼の身の上に洩せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, '是故に我彼をその戀人の手に付しその焦れたるアツスリヤの子孫の手に付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, '是に於て彼等かれの陰所を露しその子女を奪ひ劍をもて彼を殺して婦人の中にその名を聞えしめその身の上に鞫を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, '彼の妹アホリバこれを見彼よりも甚だしくその慾を縱恣にしその姊の淫行よりもましたる淫行をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'その隣なるアツスリヤの人々に戀焦れたり彼らはすなはち牧伯たる者 督宰たる者 華美に粧ひたる者 馬に騎る者にして皆美しき秀でたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, '我かれがその身を汚せしを見たり彼らは共に一の途をあゆめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, '彼その淫行を増り彼壁に彫つけたる人々を見たり是すなはち朱をもて壁に彫つけたるカルデヤ人の像にして');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, '腰には帶を結び首には垂さがれる帓巾を戴けり是等は皆君王たる者の形ありてその生れたる國なるカルデヤのバビロン人に似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, '彼その目に是等を見てこれに戀焦れ使者をカルデヤにおくりて之にいたらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, '是に於てバビロンの人々彼の許にきたりて戀の床に就きその淫行をもて彼を汚したりしが彼らにその身を汚さるるにおよびて彼その心にかれらを疎んず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, '彼その淫行を露しその陰所を顯したれば我心彼を疎んず吾心かれの姊を疎んじたるがごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, '彼その淫行を増しその少き日にエジプトに於て淫をおこなひし事を憶え');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, '彼らの戀人に焦るその人の肉は驢馬の肉のごとく其精は馬の精のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, '汝は己の少き時にエジプト人が汝の處女の乳房のために汝の乳にさはりたる時の淫行を顧みるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'この故に主ヱホバかく言ふアホリバよ我汝が心に疎んずるに至りしところの戀人等を激して汝を攻しめ彼らをして四方より汝に攻きたらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, '即ちバビロンの人々およびカルデヤの諸の人々ペコデ、シヨワ、コア並にアツスリヤの諸の人々美しき秀でたる人々牧伯等および督宰等 大君および名高き人 凡て馬に騎る者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, '鋒車および輪を持ち衆多の民をひきゐて汝に攻め來り大楯小楯および兜をそなへて四方より汝に攻かからん我裁判をかれらに委ぬべし彼らすなはち其律法によりて汝を鞫かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, '我汝にむかひてわが嫉妬を發すれば彼ら怒をもて汝を待ひ汝の鼻と耳を切とるべし汝のうちの存れる者は劍に仆れん彼ら汝の子女を奪ふべし汝の中の殘れる者は火に燒ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, '彼ら汝の衣を剝脱り汝の美しき妝飾を取べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, '我汝の淫行を除き汝がエジプトの地より行ひ來れるところの邪淫を除き汝をして重て彼らに目をつけざらしめ再びエジプトの事を憶はざらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, '主ヱホバかく言ふ視よ我汝が惡む者の手汝が心に疎ずる者の手に汝を付せば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, '彼ら怨憎をもて汝を待ひ汝の得たる物を盡く取り汝を赤裸に成おくべし是をもて汝が淫をおこなヘる陰所露にならん汝の淫行と邪淫もしかり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, '汝異邦人を慕ひて淫をおこなひ彼らの偶像をもて身を汚したるに由て是等の事汝におよぶなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, '汝その姊の途に歩みたれば我かれの杯を汝の手に交す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, '主ヱホバかく言ふ汝その姊の深き大なる杯を飮べし是は笑と嘲を充す者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, '醉と憂汝に滿ちん汝の姊サマリヤの杯は駭異と滅亡の杯なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, '汝これを飮み乾しこれを吸つくしその碎片を咬み汝の乳房を摘去ん我これを言ふと主ヱホバ言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, '然ば主ヱホバかく言ふ汝我を忘れ我を後に棄たれば汝またその淫行と邪淫の罪を負べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, '斯てヱホバ我にいひたまふ人の子よ汝アホラとアホリバを鞫かんとするや然らば彼らにその憎むべき事等を示せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, '夫彼らは姦淫をおこなへり又血その手にあり彼らその偶像と姦淫をおこなひ又その我に生たる男子等に火の中をとほらしめてこれを燒り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, '加之また是をなせり即ち彼ら同日にわが聖處を汚しわが安息日を犯せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, '彼らその偶像のために男子等を宰りしその日にわが聖處に來りてこれを汚し斯わが家の中に事をなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, '且又彼らは使者をやりて遠方より人を招きて至らしむ其人々のために汝身を洗ひ目を畵き妝飾を着け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, '華美なる床に坐し臺盤をその前に備へその上にわが香とわが膏を置り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, '斯て群衆の喧噪その中に靜りしがその多衆の人々の上にまた曠野よりサバ人を招き寄たり彼らは手に腕環をはめ首に美しき冠を戴けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, '我かの姦淫のために衰弱たる女の事を云り今は早彼の姦淫その姦淫をなしをはらんかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, '彼らは遊女の所にいるごとくに彼の所に入たり斯かれらすなはち淫婦アホラとアホリバの所に入ぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, '義人等姦婦の律法に照し故殺の律法に照して彼らを鞫かん彼らは姦婦にしてまたその手に血あればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, '主ヱホバかく言ふ我群衆を彼等に攻きたらしめ彼らを是に付して虐と掠にあはしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, '群衆かれらを石にて撃ち劍をもて斬りその子女を殺し火をもてその家を燒べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, '斯我この地に邪淫を絕さん婦女みな自ら警めて汝らのごとくに邪淫をおこなはざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, '彼ら汝らの邪淫の罪を汝らに報いん汝らはその偶像の罪を負ひ而して我の主ヱホバなるを知にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, '九年の十月十日にヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '人の子よ汝此日すなはち今日の名を書せバビロンの王今日ヱルサレムを攻をるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, '汝背ける家に譬喩をかたりて之に言へ主ヱホバかく言たまふ釜を居ゑ居ゑてこれに水を斟いれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, '其肉の凡て佳き所を集めて股と肩とを之に入れ佳き骨をこれに充し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, '羊の選擇者を取れ亦薪一束を取り下に入れて骨を煮釜を善く煮たて亦その中の骨を煮よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, '是故に主ヱホバかく言ふ禍なるかな血の流るる邑銹のつきたる釜 その銹これを離れざるなり肉を一箇一箇に取いだせ之がために籤を掣べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, '彼の血はその中にあり彼乾ける磐の上にこれを置りこれを土にそそぎて塵に覆はれしめず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, '我怒を來らせ仇を復さんがためにその血を乾ける磐の上に置て塵に覆はれざらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, '是故に主ヱホバかく言ふ禍なるかな血の流るる邑我またその薪の束を大にすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, '薪を積かさね火を燃し肉を善く煮てこれを煮つくしその骨をも燒しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, '而して釜を空にして炭火の上に置きその銅をして熱くなりて燒しめ其汚穢をして中に鎔しめその銹を去しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, '旣に手を盡したれどもその大なる銹さらざればその銹を火に投棄べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, '汝の汚穢の中に淫行あり我汝を淨めんとしたれども汝淨まらざりしに因てわが怒を汝に洩しつくすまでは汝その汚穢をはなれて淨まることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, '我ヱホバこれを言り是至る我これを爲べし止ず惜まず悔ざるなり汝の道にしたがひ汝の行爲にしたがひて彼ら汝を鞫かん主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '人の子よ我頓死をもて汝の目の喜ぶ者を取去ん汝哀かず泣ず涙をながすべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, '聲をたてずして哀け死人のために哀哭をなすなかれ冠物を戴き足に鞋を穿べし鬚を掩ふなかれ人のおくれる食物を食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, '朝に我人々に語りしが夕にわが妻死ねり明朝におよびて我命ぜられしごとくなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, '茲に人々我に言けるは此汝がなすところの事は何の意なるや我らに告ざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, '我かれらに言けるはヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'イスラエルの家にいふべし主ヱホバかく言ふ視よ我汝らの勢力の榮汝らの目の喜愛汝らの心の望なるわが聖所を汚さん汝らが遺すところの子女等は劍に仆れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, '汝らもわが爲るごとくなし鬚を覆はず人のおくれる食物を食はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, '首に冠物を戴き足に履を穿き哀かず泣ずその罪の中に痩衰へて互に呻かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, '斯エゼキエル汝らに兆とならん彼がなしたるごとく汝ら爲ん是事の至らん時に汝ら我の主ヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, '人の子よわが彼らの力かれらの樂むところの榮その目の喜愛その心の望その子女を取去る日');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'その日に逃亡者汝の許に來り汝の耳に告ることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'その日に汝逃亡者にむかひて口を啓き語りて再び默せざらん斯汝かれらに兆となるべし彼らは遂に我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'ヱホバの言我に臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '人の子よ汝の面をアンモンの人々に向けこれに向ひて預言し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'アンモンの人々に言べし汝ら主ヱホバの言を聽け主ヱホバかく言ひたまふ汝わが聖處の汚さるる事につきイスラエルの地の荒さるる事につき又ユダの家の擄へ移さるることにつきて嗚呼心地善しと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, '是故に視よ我汝を東方の人々に付して所有と爲さしめん彼等汝の中に畜圈を設け汝の中にその住宅を建て汝の作物を食ひ汝の乳を飮ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'ラバをば我駱駝を豢ふ地となしアンモンの人々の地をば羊の臥す所となすべし汝ら我のヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, '主ヱホバかく言たまふ汝イスラエルの地の事を見て手を拍ち足を蹈み傲慢を極めて心に喜べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, '是故に視よ我わが手を汝に伸べ汝を國々に付して掠奪に遭しめ汝を國民の中より絕ち諸國に斷し滅すべし汝我のヱホバなるを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, '主ヱホバかく言たまふモアブとセイル言ふユダの家は他の諸の國と同じと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, '是故に我モアブの肩を闢くべし即ちその邑々その最遠の邑にして國の莊嚴なるベテエシモテ、バアルメオンおよびキリヤタイムよりこれを闢き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, '之をアンモンの人々に添て東方の人々に與へその所有となさしめアンモンの人々をして國々の中に記憶らるること无しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, '我モアブに鞫を行ふべし彼ら我のヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, '主ヱホバかく言たまふエドムは怨恨をふくんでユダの家に事をなし且これに怨を復して大に罪を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, '是故に主ヱホバかく言たまふ我エドムの上にわが手を伸して其中より人と畜を絕去り之をテマンより荒地となすべしデダンの者は劍に仆れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, '我わが民イスラエルの手をもてエドムにわが仇を報いん彼らわが怒にしたがひわが憤にしたがひてエドムに行ふべしエドム人すなはち我が仇を復すなるを知ん主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, '主ヱホバかく言たまふペリシテ人は怨を含みて事をなし心に傲りて仇を復し舊き恨を懷きて滅すことをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, '是故に主ヱホバかく言たまふ視よ我ペリシテ人の上に手を伸べケレテ人を絕ち海邊に遺れる者を滅すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, '我怒の罰をもて大なる復仇を彼らに爲ん我仇を彼らに復す時に彼らは我のヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, '十一年の月の首の日にヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '人の子よツロはヱルサレムの事につきて言り嗚呼心地よし諸の國民の門破る是我に移るならん我は豐滿になるべし彼は荒はてたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, '是故に主ヱホバかく言たまふツロよ我汝を攻め海のその波濤を起すが如く多くの國人を汝に攻きたらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, '彼らツロの石墻を毀ちその櫓を倒さん我その塵を拂ひ去りて是を乾ける磐と爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, '是は海の中の網を張る處とならん我これを言ばなりと主ヱホバいひたまふ是は諸の國人に掠めらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'その野にをる女子等は劍に殺されん彼らすなはち我のヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, '主ヱホバかく言たまふ視よ我王の王なるバビロンの王ネブカデネザルをして馬車騎兵群衆および多くの民を率て北よりツロに攻きたらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, '野にをる汝の女子等をば彼劍にかけて殺し又汝にむかひて雲梯を建て汝にむかひて壘を築き汝にむかひて干を備へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, '破城槌を汝の石垣に向けその斧をもて汝の櫓を打碎かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'その衆多の馬の煙塵汝を覆はん彼等敝れたる城に入るごとくに汝の門々に入來らん時その騎兵と輪と車の聲のために汝の石垣震動べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, '彼その馬の蹄をもて汝の諸の衢を踏あらし劍をもて汝の民を殺さん汝の榮光の柱地に仆るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, '彼ら汝の財寶を奪ひ汝の商貨を掠め汝の石垣を打崩し汝の樂き舘を毀ち汝の石と木と土を水に沈めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, '我汝の歌の聲を止めん汝の琴の音は復聞えざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, '我汝を乾ける磐となさん汝は網を張る處となり再び建ことなかるべし我ヱホバこれを言ふと主ヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, '主ヱホバ、ツロにかく言たまふ島々汝の仆るる聲 手負の呻吟 および汝の中の殺戮によりて震動ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, '海の君主等皆その座を下り朝服を脱ぎ繡ある衣を去り恐懼を身に纏ひ地に坐し時となく怖れ汝の事を驚かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, '彼ら汝の爲に哀の詞を擧て汝に言ふべし汝海より出たる住處名の高き邑自己もその居民も共に海に於て勢力ある者その凡の居民に己を恐れしむる者よ汝如何にして亡びたるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'それ島々は汝の仆るる日に震ひ海の島々は汝の亡ぶるに驚くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, '主ヱホバかく言たまふ我汝を荒たる邑となし人の住はざる邑々のごとく爲し洋海を沸あがらしめて大水に汝を掩沒しめん時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, '汝を墓に往る者等の所昔時の民の所に下し汝をして下の國に住しめ古昔よりの墟址に於て彼の墓に下れる者等とともに居しめ汝の中に復人の住こと无らしむべし而して我活る人の地に榮を創造いださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, '我汝をもて人の戒懼となすべし汝は復有ることなし人汝を尋るも終に汝を看ざるべし主ヱホバこれを言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'ヱホバの言また我に臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '人の子よ汝ツロのために哀の詞を宣べ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'ツロに言べし汝海の口に居りて諸の國人の商人となり多衆の島々に通ふ者よ主ヱホバかく言たまふツロよ汝言ふ我の美は極れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, '汝の國は海の中にあり汝を建る者汝の美を盡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, '人セニルの樅をもて船板を作りレバノンより香柏を取て汝のために檣を作り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'バシヤンの樫をもて汝の漿を作りキッテムの島より至れる黄楊に象牙を嵌て汝の坐板を作れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, '汝の帆はエジプトより至れる文布にして旗に用ふべし汝の天遮はエリシヤの島より至れる藍と紫の布なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, '汝の水手はシドンとアルワデの人なりツロよ汝の中にある賢き者汝の舵師となる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'ゲバルの老人等およびその賢き者汝の中にをりて汝の漏を繕ひ海の諸の船およびその舟子汝の中にありて汝の貨物を交易す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'ペルシヤ人ルデ人フテ人汝の軍にありて汝の戰士となる彼等汝の中に干と兜を懸け汝に光輝を與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'アルワデの人々および汝の軍勢汝の四周の石垣の上にあり勇士等汝の櫓にあり彼等汝の四周の石垣にその楯をかけ汝の美を盡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'その諸の貨物に富るがためにタルシシ汝と商をなし銀 鐵 錫および鉛をもて汝と交易を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'ヤワン、トバルおよびメセクは汝の商賈にして人の身と銅の器をもて汝と貿易を行ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'トガルマの族馬と騎馬および騾をもて汝と交易し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'デダンの人々汝と商をなせり衆の島々汝の手にありて交易し象牙と黑檀をもて汝と貿易せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, '汝の製造品の多がためにスリア汝と商をなし赤玉 紫貨 繡貨 細布 珊瑚および瑪瑙をもて汝と交易す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'ユダとイスラエルの地汝に商をなしミンニテの麥と菓子と蜜と油と乳香をもて汝と交易す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, '汝の製造物の多がため諸の貨物の多きがためにダマスコ、ヘルボンの酒と曝毛をもて汝と交易せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'ウザルのベダンとヤワン熟鐵をもて汝と交易す肉桂と菖蒲汝の市にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'デダン車の毛氈を汝に商へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'アラビヤとケダルの君等とは汝の手に在りて商をなし羔羊と牡羊と牡山羊をもて汝と交易す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'シバとラアマの商人汝と商をなし諸の貴き香料と諸の寶石と金をもて汝と交易せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'ハランとカンネとエデンとシバの商賈とアツスリヤとキルマデ汝と商をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, '華美なる物と紫色なる繡の衣服と香柏の箱の綾を盛て紐にて結たる者とをもて汝の市にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'タルシシの船汝のために往來して商賣を爲す汝は海の中にありて豐滿にして榮あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, '水手汝を蕩て大水の中にいたるに海の中にて東風汝を打破る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, '汝の財寶汝の商貨物汝の交易の物汝の舟子汝の舵師汝の漏を繕ふ者汝の貨物を商ふ者汝の中にあるところの凡ての軍人並に汝の中の乗者みな汝の壞るる日に海の中に陷るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, '汝の舵師等の叫號の聲にその處々震ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, '凡て棹を執る者舟子および凡て海の舵師その船より下りて陸に立ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, '汝のために聲を擧げて痛く哭き塵を首に蒙り灰の中に輾轉び');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, '汝のために髮を剃り麻布を纏ひ汝のために心を痛めて泣き甚く哭くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, '彼等悲みて汝のために哀の詞を宣べ汝を弔ひて言ふ孰かツロの如くなる海の中に滅びたる者の如くなると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, '汝の商貨の海より出し時は汝衆多の國民を厭しめ汝の衆多の財寶と貨物をもて世の王等を富しめたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, '汝海に壞れて深き水にあらん時は汝の貨物汝の乗人みな陷らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, '島々に住る者皆汝に駭かんその君等大に恐れてその面を振はすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, '國々の商賈汝のために嘶かん汝は人の戒懼となり限りなく失果ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '人の子よツロの君に言ふべし主ヱホバかく言たまふ汝心に高ぶりて言ふ我は神なり神の座に坐りて海の中にありと汝は人にして神にあらず而して神の心のごとき心を懷くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, '夫汝はダニエルよりも賢かり隱れたる事として汝に明ならざるは无し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, '汝の智慧と明哲によりて汝富を獲金銀を汝の庫に收め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, '汝の大なる智慧と汝の貿易をもて汝の富有を増しその富有のために心に高ぶれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, '是故に主ヱホバかく言ふ汝神の心のごとき心を懷くに因り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, '視よ我異國人を汝に攻きたらしめん是國々の暴き人々なり彼ら劍を拔きて汝が智慧をもて得たるところの美しき者に向ひ汝の美を汚し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, '汝を穴に投いれん汝は海の中にて殺さるる者のごとき死を遂べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, '汝は人にして神にあらず汝を殺す者の手にあるも尚その己を殺す者の前に我は神なりと言んとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, '汝は割禮をうけざる者の死を異國人の手に遂べし我これを言ばなりとヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'ヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '人の子よツロの王のために哀の詞を述べこれに言べし主ヱホバかく言たまふ汝は全く整へたる者の印智慧の充ち美の極れる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, '汝神の園エデンに在りき諸の寶石 赤玉 黄玉 金剛石 黄綠玉 葱垳 碧玉 靑玉 紅玉 瑪瑙および金汝を覆へり汝の立らるる日に手鼓と笛汝のために備へらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, '汝は膏そそがれしケルブにして掩ふことを爲り我汝を斯なせしなり汝神の聖山に在り又火の石の間に歩めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, '汝はその立られし日より終に汝の中に惡の見ゆるにいたるまでは其行全かりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, '汝の交易の多きがために汝の中には暴逆滿ちて汝罪を犯せり是故に掩ふことを爲ところのケルブよ我神の山より汝を汚し出し火の石の間より汝を滅し去べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, '汝その美麗のために心に高ぶり其榮耀のために汝の智慧を汚したれば我汝を地に擲ち汝を王等の前に置て觀物とならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, '汝正しからざる交易をなして犯したる多くの罪を以て汝の聖所を汚したれば我なんぢの中より火を出して汝を燒き凡て汝を見る者の目の前にて汝を地に灰となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, '國々の中にて汝を知る者は皆汝に驚かん汝は人の戒懼となり限なく失果てん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'ヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '人の子よ汝の面をシドンに向けこれに向ひて預言し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, '言べし主ヱホバかく言たまふシドンよ視よ我汝の敵となる我汝の中において榮耀を得ん我彼らを鞫き我の聖き事を彼らに顯す時彼ら我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'われ疫病を是におくりその衢に血あらしめんその四方より是に來るところの劍に殺さるる者その中に仆るべし彼らすなはち我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'イスラエルの家にはその周圍にありて之を賤むる者の所より重て惡き荊棘苦き芒薊來ることなし彼らは我の主ヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, '主ヱホバかく言ふ我イスラエルの家をその散されたる國々より集めん時彼らに由りて我の聖き事を異國人の目の前にあらはさん彼らはわが僕ヤコブに與へたるその地に住ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, '彼ら彼處に安然に住み家を建て葡萄園を作らん彼らの周圍にありて彼らを藐視る者を悉く我が鞫かん時彼らは安然に住み我ヱホバの己の神なるを知らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, '十年の十月の十二日にヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '人の子よ汝の面をエジプトの王パロにむけ彼とエジプト全國にむかひて預言し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, '語りて言べし主ヱホバかく言たまふエジプトの王パロよ視よ我汝の敵となる汝その河に臥すところの鱷よ汝いふ河は我の所有なり我自己のためにこれを造れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, '我鉤を汝の腮に鉤け汝の河の魚をして汝の鱗に附しめ汝および汝の鱗に附る諸の魚を汝の河より曳いだし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, '汝と汝の河の諸の魚を曠野に投すてん汝は野の面に仆れん汝を取あぐる者なく集むる者なかるべし我汝を地の獸と天の鳥の餌に與へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'エジプトの人々皆我のヱホバなるを知ん彼等のイスラエルの家におけるは葦の杖のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'イスラエル汝の手を執ば汝折れてその肩を盡く裂き又汝に倚ば汝破れてその腰を盡く振へしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, '是故に主ヱホバかく言ふ視よ我劍を汝に持きたり人と畜を汝の中より絕ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'エジプトの地は荒て空曠なるべし彼らすなはち我のヱホバなるを知ん彼河は我の有なり我これを作れりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, '是故に我汝と汝の河々を罰しエジプトの地をミグドルよりスエネに至りエテオピアの境に至るまで盡く荒して空曠くせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, '人の足此を渉らず獸の足此を渉らじ四十年の間此に人の住ことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, '我エジプトの地を荒して荒たる國々の中にあらしめんその邑々は荒て四十年の間荒たる邑々の中にあるべし我エジプト人を諸の民の中に散し諸の國に散さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, '但し主ヱホバかく言たまふ四十年の後我エジプト人をその散されたる諸の民の中より集めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, '即ちエジプトの俘囚人を歸しその生れし國なるバテロスの地にかへらしむべし彼らは其處に卑き國を成ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, '是は諸の國よりも卑くして再び國々の上にいづることなかるべし我かれらを小くすれば彼らは重て國々を治むることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, '彼らは再びイスラエルの家の恃とならじイスラエルはこれに心をよせてその罪をおもひ出さしむることなかるべし彼らすなはち我の主ヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, '茲に二十七年の一月の一日にヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '人の子よバビロンの王ネブカデネザルその軍勢をしてツロにむかひて大に働かしむ皆首禿げ皆肩破る然るに彼もその軍勢もその爲るところの事業のためにツロよりその報を得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, '是故に主ヱホバかくいふ視よ我バビロンの王ネブカデネザルにエジプトの地を與へん彼その衆多の財寳を取り物を掠め物を奪はん是その軍勢の報たらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, '彼の勞動る値として我エジプトの地をかれに與ふ彼わがために之をなしたればなり主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, '當日に我イスラエルの家に一の角を生ぜしめ汝をして彼らの中に口を啓くことを得せしめん彼等すなはち我がヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'ヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '人の子よ預言して言へ主ヱホバかく言たまふ汝ら叫べ其日は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'その日近しヱホバの日近し是雲の日これ異邦人の時なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, '劍エジプトに臨まん殺さるる者のエジプトに仆るる時エテオピアに痛苦あるべし敵その財寶を奪はんその基址は毀たるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'エテオピア人フテ人ルデ人凡て加勢の兵およびクブ人ならびに同盟の國の人々彼らとともに劍にたふれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'ヱホバかく言ふエジプトを扶くる者は仆れ其驕るところの勢力は失せんミグドルよりスエネにいたるまで人劍によりて己の中に仆るべし主ヱホバこれを言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, '其は荒て荒地の中にあり其邑々は荒たる邑の中にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, '我火をエジプトに降さん時又是を助くる者の皆ほろびん時は彼等我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'その日には使者船にて我より出てかの心強きエテオピア人を懼れしめんエジプトの日にありし如く彼等の中に苦痛あるべし視よ是は至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, '主ヱホバかく言たまふ我バビロンの王ネブカデネザルをもてエジプトの喧噪を止むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, '彼および彼にしたがふ民即ち國民の中の暴き者を召來りてその國を滅さん彼ら劍をぬきてエジプトを攻めその殺せる者を國に滿すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, '我その河々を涸し國を惡き人の手に賣り外國人の手をもて國とその中の物を荒すべし我ヱホバこれを言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, '主ヱホバかく言たまふ我偶像を毀ち神々をノフに絕さんエジプトの國よりは再び君のいづることなかるべし我エジプトの國に畏怖を蒙らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, '我バテロスを荒しゾアンに火を擧げノに鞫を行ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'わが怒をエジプトの要害なるシンに洩しノの群衆を絕つべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, '我火をエジプトに降さんシンは苦痛に悶えノは打破られノフは日中敵をうけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'アベンとピベセテの少者は劍に仆れ其中の人々は擄ゆかれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'テバネスに於ては吾がエジプトの軛を其處に摧く時に日暗くならんその誇るところの勢力は失せん雲これを覆はんその女子等は擄へゆかれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'かく我エジプトに鞫をおこなはん彼等すなはち我のヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, '十一年の一月の七日にヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '人の子よ我エジプトの王パロの腕を折れり是は再び束へて藥を施し裹布を卷て之を裹み強く爲して劍を執にたへしむること能はざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, '是故に主ヱホバかく言たまふ視よ我エジプトの王パロを罰し其強き腕と折たる腕とを俱に折り劍をその手より落しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, '我エジプト人を諸の民の中に散し諸の國に散さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, '而してバビロンの王の腕を強くして我劍をこれに授けん然ど我パロの腕を折れば彼は刺透されたる者の呻くが如くにその前に呻かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, '我バビロンの王の腕を強くせんパロの腕は弱くならん我わが劍をバビロンの王の手に授けて彼をしてエジプトにむかひて之を伸しむる時は人衆我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, '我エジプト人を諸の民の中に散し諸の國に散さん彼らすなはち我のヱホバなるを知るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, '十一年の三月の一日にヱホバの言我に臨みて云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '人の子よエジプトの王パロとその群衆に言へ汝はその大なること誰に似たるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'アツスリヤはレバノンの香柏のごとし其枝美しくして生茂りその丈高くして其巓雲に至る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, '水これを大ならしめ大水これを高からしむ其川々その植れる處を環りその流を野の諸の樹に及ぼせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, '是によりてその長野の諸の樹よりも高くなりその生長にあたりて多の水のために枝葉茂りその枝長く伸たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'その枝葉に空の諸の鳥巢をくひ其枝の下に野の諸の獸子を生みその蔭に諸の國民住ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, '是はその大なるとその枝の長きとに由て美しかりき其根多くの水の傍にありたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, '神の園の香柏これを蔽ふことあたはず樅もその枝葉に及ばず槻もその枝に如ず神の園の樹の中その美しき事これに如ものあらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, '我これが枝を多してこれを美しくなせりエデンの樹の神の園にある者皆これを羨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, '是故に主ヱホバかく言ふ汝その長高くなれり是は其巓雲に至りその心高く驕れば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, '我これを萬國の君たる者の手に付さん彼これを處置せん其惡のために我これを打棄たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, '他國人國々の暴き者これを截倒して棄つ其枝葉は山々に谷々に墮ち其枝は碎けて地の諸の谷川にあり地の萬民その蔭を離れてこれを遺つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'その倒れたる上に空の諸の鳥止まり其枝の上に野の諸の獸居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, '是水の邊の樹その高のために誇ることなくその巓を雲に至らしむることなからんためまた水に濕ふ者の高らかに自ら立ことなからんためなり夫是等は皆死に付されて下の國に入り他の人々の中にあり墓に下る者等と偕なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, '主ヱホバかく言たまふ彼が下の國に下れる日に我哀哭あらしめ之がために大水を蓋ひその川々をせきとめたれば大水止まれり我レバノンをして彼のために哭かしめ野の諸の樹をして彼のために痩衰へしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, '我かれを陰府に投くだして墓に下る者と共ならしむる時に國々をしてその墮る響に震動しめたり又エデンの諸の樹レバノンの勝れたる最美しき者凡て水に濕ふ者皆下の國に於て慰を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, '彼等も彼とともに陰府に下り劍に刺れたる者の處にいたる是すなはちその助者となりてその蔭に坐し萬國民の中にをりし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'エデンの樹の中にありて汝は其榮とその大なること孰に似たるや汝は斯エデンの樹とともに下の國に投下され劍に刺透されたる者とともに割禮を受ざる者の中にあるべしパロとその群衆は是のごとし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, '茲にまた十二年の十二月の一日にヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '人の子よエジプトの王パロのために哀の詞を述て彼に言ふべし汝は自ら萬國の中の獅子に擬へたるが汝は海の鱷の如くなり汝河の中に跳起き足をもて水を濁しその河々を蹈みだす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, '主ヱホバかく言たまふ我衆多の國民の中にてわが網を汝に打掛け彼らをしてわが網にて汝を引あげしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, '而して我汝を地上に投すて汝を野の面に擲ち空の諸の鳥をして汝の上に止らしめ全地の獸をして汝に飽しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, '我汝の肉を山々に遺て汝の屍を堆くして谷々を埋むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, '我汝の溢るる血をもて地を濕し山にまで及ぼさん谷川には汝盈べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, '我汝を滅する時は空を蔽ひその星を暗くし雲をもて日を掩はん月はその光を發たざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, '我空の照る光明を盡く汝の上に暗くし汝の地を黑暗となすべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, '我なんぢの滅亡を諸の民汝の知ざる國々の中に知しめて衆多の民をして心を傷ましめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, '我衆多の民をして汝に驚かしめんその王等はわが其前にわれの劍を振ふ時に戰慄かん汝の仆るる日には彼ら各人その生命のために絕ず發振ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, '即ち主ヱホバかく言たまふバビロンの王の劍汝に臨まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, '我汝の群衆をして勇士の劍に仆れしめん彼等は皆國々の暴き者なり彼らエジプトの驕傲を絕さん其の群衆は皆ほろぼさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, '我その家畜を盡く多の水の傍より絕去ん人の足再び之を濁すことなく家畜の蹄これを濁すことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, '我すなはちその水を淸しめ其河々をして油のごとく流れしめん主ヱホバこれを云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, '我エジプトの國を荒地となしてその國荒てこれが富を失ふ時また我その中に住る者を盡く撃つ時人々我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, '是哀の詞なり人悲みてこれを唱へん國々の女等悲みて之を唱ふべし即ち彼等エジプトとその諸の群衆のために悲みて之を唱へん主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, '十二年の月の十五日にヱホバの言また我に臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '人の子よエジプトの群衆のために哀き是と大なる國々の女等とを下の國に投くだし墓にくだる者と共ならしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, '汝美しき事誰に勝るや下りて割禮なき者とともに臥せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, '彼らは劍に殺さるる者の中に仆るべし劍已に付してあり是とその諸の群衆を曳下すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, '勇士の強き者陰府の中より彼にその助者と共に言ふ割禮を受ざる者劍に殺されたる者彼等下りて臥す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, '彼處にアツスリアとその凡の群衆をりその周圍に之が墓あり彼らは皆殺され劍に仆れたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'かれの墓は穴の奧に設けてありその群衆墓の四周にあり是皆殺されて劍に仆れたる者生者の地に畏怖をおこせし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, '彼處にエラムありその凡の群衆その墓の周圍にあり是皆ころされて劍に仆れ割禮を受ずして下の國に下りし者生者の地に畏怖をおこせし者にて夫穴に下れる者等とともに恥辱を蒙るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, '殺されたる者の中にその床を置きてその凡の群衆と共にすその墓周圍にあり彼等は皆割禮を受ざる者にして劍に殺さる彼ら生者の地に畏怖をおこしたれば穴に下れる者とともに恥辱を蒙るなり彼は殺されし者の中に置る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, '彼處にメセクとトバルおよびその凡の群衆ありその墓周圍にあり彼らは皆割禮を受ざる者にして劍に殺さる是生者の地に畏怖をおこしたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, '彼らは割禮を受ずして仆れたる勇士とともに臥さず是等はその武器を持て陰府に下りその劍を枕にすその罪は骨にあり是生者の地に於て勇士を畏れしめたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, '汝は割禮を受ざる者の中に打碎け劍に殺されたる者とともに臥ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, '彼處にエドムとその王等とその諸の君等あり彼らは勇力をもちながら劍に殺さるる者の中に入り割禮なき者および穴に下れる者とともに臥すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, '彼處に北の君等皆あり又シドン人皆あり彼らは殺されし者等とともに下り人を怖れしむる勇力をもちて羞辱を受く彼處に彼らは割禮を受ずして劍に殺されたる者とともに臥し穴に下れる者とともに恥辱を蒙る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'パロかれらを見その諸の群衆の事につきて心を安めんパロとその軍勢皆劍に殺さる主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, '我かれをして生者の地に畏怖をおこさしめたりパロとその諸の群衆は割禮をうけざる者の中にありて劍に殺されし者とともに臥す主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, '爰にヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '人の子よ汝の民の人々に告て之に言へ我劍を一の國に臨ましめん時その國の民おのれの國人の中より一人を選みて之を守望人となさんに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'かれ國に劍の臨むを見ラッパを吹てその民を警むることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, '然るに人ラッパの音を聞て自ら警めず劍つひに臨みて其人を失ふにいたらばその血はその人の首に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, '彼ラッパの音を聞て自ら警むることを爲ざればその血は己に歸すべし然どもし自ら警むることを爲ばその生命を保つことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, '然れども守望者劍の臨むを見てラッパを吹ず民警戒をうけざるあらんに劍のぞみて其中の一人を失はば其人は己の罪に死るなれど我その血を守望者の手に討問めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, '然ば人の子よ我汝を立てイスラエルの家の守望者となす汝わが口より言を聞き我にかはりて彼等を警むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, '我惡人に向ひて惡人よ汝死ざるべからずと言んに汝その惡人を警めてその途を離るるやうに語らずば惡人はその罪に死んなれどその血をば我汝の手に討問むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, '然ど汝もし惡人を警めて翻りてその途を離れしめんとしたるに彼その途を離れずば彼はその罪に死ん而して汝はおのれの生命を保つことを得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, '然ば人の子よイスラエルの家に言へ汝らは斯語りて言ふ我らの愆と罪は我らの身の上にあり我儕はその中にありて消失ん爭でか生ることを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, '汝かれらに言べし主ヱホバ言たまふ我は活く我惡人の死るを悦ばず惡人のその途を離れて生るを悦ぶなり汝ら翻へり翻へりてその惡き道を離れよイスラエルの家よ汝等なんぞ死べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, '人の子よ汝の民の人々に言べし義人の義はその人の罪を犯せる日にはその人を救ふことあたはず惡人はその惡を離れたる日にはその惡のために仆るることあらじ義人はその罪を犯せる日にはその義のために生ることを得じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, '我義人に汝かならず生べしと言んに彼その義を恃みて罪ををかさばその義は悉く忘らるべし其をかせる罪のために彼は死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, '我惡人に汝かならず死べしと言んに彼その惡を離れ公道と公義を行ふことあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, '即ち惡人質物を歸しその奪ひし者を還し惡をなさずして生命の憲法にあゆみなば必ず生ん死ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'その犯したる各種の罪は記憶らるることなかるべし彼すでに公道と公義を行ひたれば必ず生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, '汝の民の人々は主の道正しからずと言ふ然ど實は彼等の道の正しからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, '義人もしその義を離れて罪ををかさば是がために死べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, '惡人もしその惡を離れて公道と公義を行ひなば是がために生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, '然るに汝らは主の道正しからずといふイスラエルの家よ我各人の行爲にしたがひて汝等を鞫くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, '我らが擄へうつされし後すなはち十二年の十月の五日にヱルサレムより脱逃者きたりて邑は撃敗られたりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'その逃亡者の來る前の夜ヱホバの手我に臨み彼が朝におよびて我に來るまでに我口を開けり斯わが口開けたれば我また默せざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, '即ちヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '人の子よイスラエルの地の彼の墟址に住る者語りて云ふアブラハムは一人にして此地を有てり我等は衆多し此地はわれらの所有に授かると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, '是故に汝かれらに言ふべし主ヱホバかく言ふ汝らは血のままに食ひ汝らの偶像を仰ぎ且血を流すなれば尚此地を有つべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, '汝等は劍を恃み憎むべき事を行ひ各々人の妻を汚すなれば此地を有つべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, '汝かれらに斯言べし主ヱホバかく言ふ我は活くかの荒場に居る者は劍に仆れん野の表にをる者をば我獸にあたへて噬はしめん要害と洞穴とにをる者は疫病に死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, '我この國を全く荒さん其誇るところの權勢は終に至らんイスラエルの山々は荒て通る者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, '彼らが行ひたる諸の憎むべき事のために我その國を全く荒さん時に彼ら我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, '人の子よ汝の民の人々垣の下家の門にて汝の事を論じ互に語りあひ各々その兄弟に言ふ去來われら如何なる言のヱホバより出るかを聽んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, '彼ら民の集會のごとくに汝に來り吾民のごとくに汝の前に坐して汝の言を聞ん然ども之を行はじ彼らは口に悦ばしきところの事をなし其心は利にしたがふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, '彼等には汝悦ばしき歌美しき聲美く奏る者のごとし彼ら汝の言を聞ん然ど之をおこなはじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, '視よその事至る其事のいたる時には彼らおのれの中に預言者あるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'ヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '人の子よ汝イスラエルの牧者の事を預言せよ預言して彼ら牧者に言ふべし主ヱホバかく言ふ己を牧ふところのイスラエルの牧者は禍なるかな牧者は群を牧ふべき者ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, '汝らは脂を食ひ毛を纏ひ肥たる物を屠りその群をば牧はざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, '汝ら其弱き者を強くせずその病る者を醫さずその傷ける者を裹まず散されたる者をひきかへらず失たる者を尋ねず手荒に嚴刻く之を治む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, '是は牧者なきに因て散り失せ野の諸の獸の餌となりて散失するなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, '我羊は諸の山々に諸の高丘に迷ふ我羊全地の表に散りをれど之を索す者なく尋ぬる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, '是故に牧者よ汝らヱホバの言を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, '主ヱホバ言たまふ我は活く我羊掠められわが羊野の諸の獸の餌となる又牧者あらず我牧者わが羊を尋ねず牧者己を牧ふてわが羊を牧はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, '是故に牧者よ汝らヱホバの言を聞け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, '主ヱホバ斯言たまふ視よ我牧者等を罰し吾羊を彼らの手に討問め彼等をしてわが群を牧ふことを止しめて再び己を牧ふことなからしめ又わが羊をかれらの口より救とりてかれらの食とならざらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, '主ヱホバかく言たまふ我みづからわが群を索して之を守らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, '牧者がその散たる羊の中にある日にその群を守るごとく我わが群を守り之がその雲深き暗き日に散たる諸の處よりこれを救ひとるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, '我かれらを諸の民の中より導き出し諸の國より集めてその國に携へいりイスラエルの山の上と谷の中および國の凡の住居處にて彼らを養はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, '善き牧場にて我かれらを牧はんその休息處はイスラエルの高山にあるべし彼處にて彼らは善き休息所に臥しイスラエルの山々の上にて肥たる牧場に草を食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, '主ヱホバいひたまふ我みづから我群を牧ひ之を偃しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, '亡たる者は我これを尋ね逐はなたれたる者はこれを引返り傷けられたる者はこれを裹み病る者はこれを強くせん然ど肥たる者と強き者は我これを滅さん我公道をもて之を牧ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, '主ヱホバかく言たまふ汝等わが群よ我羊と羊の間および牡羊と牡山羊の間の審判をなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, '汝等は善き牧場に草食ひ足をもてその殘れる草を蹈あらし又淸たる水を飮み足をもてその殘餘を濁す是汝等にとりて小き事ならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'わが群汝等が足にて蹈あらしたる者を食ひ汝等が足にて濁したる者を飮べけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, '是をもて主ヱホバ斯かれらに言たまふ視よ我肥たる羊と痩たる羊の間を審判くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, '汝等は脅と肩とをもて擠し角をもて弱き者を盡く衝て遂に之を外に逐散せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, '是によりて我わが群を助けて再び掠められざらしめ又羊と羊の間をさばくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, '我かれらの上に一人の牧者をたてん其人かれらを牧ふべし是わが僕ダビデなり彼はかれらを牧ひ彼らの牧者となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, '我ヱホバかれらの神とならん吾僕ダビデかれらの中に君たるべし我ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, '我かれらと平和の契約を結び國の中より惡き獸を滅し絕つべし彼らすなはち安かに野に住み森に眠らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, '我彼らおよび吾山の周圍の處々に福祉を下し時に隨ひて雨を降しめん是すなはち福祉の雨なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, '野の樹はその實を結び地はその產物を出さん彼等は安然にその國にあるべし我がかれらの軛を碎き彼らをその僕となせる人の手より救ひいだす時に彼等は我のヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, '彼等は重ねて國々の民に掠めらるる事なく野の獸かれらを食ふことなかるべし彼等は安然に住はん彼等を懼れしむる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, '我かれらのために一の栽植處を起してその名を聞えしめん彼等は重ねて國の饑饉に滅ぶることなく再び外邦人の凌辱を蒙ることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, '彼らはその神なる我ヱホバが己と共にあるを知り自己イスラエルの家はわが民なることを知るべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, '汝等はわが羊わが牧場の群なり汝等は人なり我は汝らの神なりと主ヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, '爰にヱホバの言われに臨みて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '人の子よ汝の面をセイル山にむけ之にむかひて預言し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, '之にいふべし主ヱホバかく言ふセイル山よ視よ我汝を罰し汝にむかひてわが手を伸べ汝を全く荒し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, '汝の邑々を滅すべし汝は荒はてん而して我のヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, '汝果しなき恨を懷きてイスラエルの人々をその艱難の時その終の罪の時に劍の手に付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, '是故に主ヱホバ言ふ我は活く我汝を血になさん血汝を追べし汝血を嫌はざれば血汝を追ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, '我セイル山を全く荒し其處に往來する者を絕ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, '殺されし者をその山々に滿すべし劍に殺されし者汝の岡々谷々および窪地窪地に仆れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, '我汝を長に荒地となさん汝の邑々には人の住むことあらじ汝等すなはち我のヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, '汝言ふこの二箇の民二箇の國は我が所有なり我等これを獲んとヱホバ其處に居せしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, '是故に主ヱホバいふ我は活く汝が恨をもて彼らに示したる忿怒と嫉惡に循ひて我汝に事をなさん我汝を鞫くことを以て我を彼等に示すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, '汝は我ヱホバの汝がイスラエルの山々にむかひて是は荒はて我儕の食に授かるといひて吐たるところの諸の謗讟を聞たることを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, '汝等口をもて我にむかひて誇り我にむかひて汝等の言を多くせり我これを聞く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, '主ヱホバ斯いひたまふ全地の歡ぶ時に我汝を荒地となさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, '汝イスラエルの家の產業の荒るを喜びたれば我汝をも然なすべしセイル山よ汝荒地とならんエドムも都て然るべし人衆すなはち我のヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '人の子よ汝イスラエルの山々に預言して言べしイスラエルの山々よヱホバの言を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, '主ヱホバかく言たまふ敵汝等の事につきて言ふ嗚呼是等の舊き高處我儕の所有となると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, '是故に汝預言して言へ主ヱホバかく言ふ彼等汝らを荒し四方より汝らを呑り是をもて汝等は國民の中の殘餘者の所有となり亦人の口齒にかかりて噂せらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, '然ばイスラエルの山々よ主ヱホバの言を聞け主ヱホバ山と岡と窪地と谷と滅びたる荒跡と人の棄たる邑々即ちその周圍に殘れる國民に掠められ嘲けらるる者にかく言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, '即ち主ヱホバかく言たまふ我まことに吾が嫉妬の火焰をもやして國民の殘餘者とエドム全國の事を言り是等は心に歡樂を極め心に誇りて吾地をおのれの所有となし之を奪ひ掠めし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, '然ばイスラエルの國の事を預言し山と岡と窪地と谷とに言ふべし主ヱホバかく言たまふ汝等諸の國民の羞辱を蒙りしに因て我わが嫉妬と忿怒を發して語れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, '是をもて主ヱホバかく言たまふ我わが手を擧ぐ汝の周圍の諸の國民は必ず自身羞辱を蒙るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, '然どイスラエルの山々よ汝等は枝を生じわが民イスラエルのために實を結ばん此事遠からず成ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, '視よ我汝らに臨み汝らを眷みん汝らは耕されて種をまかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, '我汝等の上に人を殖さん是皆悉くイスラエルの家の者なるべし邑々には人住み墟址は建直さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, '我なんぢらの上に人と牲畜を殖さん是等は殖て多く子を生ん我汝らの上に昔時のごとくに人を住しめ汝らの初の時よりもまされる恩惠を汝等に施すべし汝等は我がヱホバなるを知にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, '我わが民イスラエルの人を汝らの上に歩ましめん彼等汝を有つべし汝はかれらの產業となり重ねて彼等に子なからしむることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, '主ヱホバかく言ひたまふ彼等汝らに向ひ汝は人を食ひなんぢの民をして子なからしめたりと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, '是故に主ヱホバ言たまふ汝ふたたび人を食ふべからず再び汝の民を躓かしむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, '我汝をして重ねて國々の民の嘲笑を聞しめじ汝は重ねて國々の民の羞辱を蒙ることあらず汝の民を躓かしむることあらじ主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'ヱホバの言また我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '人の子よ昔イスラエルの家その國に住み己の途と行爲とをもて之を汚せりその途は月穢ある婦の穢のごとくに我に見えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, '彼等國に血を流し且その偶像をもて國を汚したるに因て我わが怒を彼等に斟ぎ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, '彼らを諸の國の民の中に散したれば則ち諸の國に散ぬ我かれらの道と行爲とにしたがひて彼等を鞫けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, '彼等その往ところの國々に至りしが遂にわが聖き名を汚せり即ち人かれらを見てこれはヱホバの民にしてかれの國より出來れる者なりと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, '是をもて我イスラエルの家がその至れる國々にて瀆せしわが聖き名を惜めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, '此故に汝イスラエルの家に言べし主ヱホバかく言たまふイスラエルの家よ我汝らのために之をなすにあらず汝らがその至れる國々にて汚せしわが聖き名のためになすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, '我國々の民の中に汚されたるわが大なる名即ち汝らがかれらの中にありて汚したるところの者を聖くせん國々の民はわが汝らに由て我の聖き事をその目の前にあらはさん時我がヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, '我汝等を諸の民の中より導き出し諸の國より集めて汝らの國に携いたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, '淸き水を汝等に灑ぎて汝等を淸くならしめ汝等の諸の汚穢と諸の偶像を除きて汝らを淸むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, '我新しき心を汝等に賜ひ新しき靈魂を汝らの衷に賦け汝等の肉より石の心を除きて肉の心を汝らに與へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, '吾靈を汝らの衷に置き汝らをして我が法度に歩ましめ吾律を守りて之を行はしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, '汝等はわが汝らの先祖等に與へし地に住て吾民とならん我は汝らの神となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, '我汝らを救ひてその諸の汚穢を離れしめ穀物を召て之を増し饑饉を汝らに臨ませず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, '樹の果と田野の作物を多くせん是をもて汝らは重て饑饉の羞を國々の民の中に蒙ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, '汝らはその惡き途とその善らぬ行爲を憶えてその罪とその憎むべき事のために自ら恨みん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, '主ヱホバ言たまふ我が之を爲は汝らのためにあらず汝らこれを知れよイスラエルの家よ汝らの途を愧て悔むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, '主ヱホバかく言たまふ我汝らの諸の罪を淸むる日に邑々に人を住しめ墟址を再興しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, '荒たる地は前に往來の人々の目に荒地と見たるに引かへて耕さるるに至るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, '人すなはち言ん此荒たりし地はエデンの園のごとくに成り荒滅び圮れたりし邑々は堅固なりて人の住に至れりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, '汝らの周圍に殘れる國々の民はすなはち我ヱホバが圮れし者を再興し荒たるところに栽植することを知にいたらん我ヱホバこれを言ふ之を爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, '主ヱホバかく言たまふイスラエルの家我が是を彼らのために爲んことをまた我に求むべきなり我群のごとくに彼ら人々を殖さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, '荒たる邑々には聖き群のごとくヱルサレムの節日の群のごとくに人の群滿ん人々すなはち我がヱホバなるを知べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, '爰にヱホバの手我に臨みヱホバ我をして靈にて出行しめ谷の中に我を放賜ふ其處には骨充てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, '彼その周圍に我をひきめぐりたまふに谷の表には骨はなはだ多くあり皆はなはだ枯たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, '彼われに言たまひけるは人の子よ是等の骨は生るや我言ふ主ヱホバよ汝知たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, '彼我に言たまふ是等の骨に預言し之に言べし枯たる骨よヱホバの言を聞け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, '主ヱホバ是らの骨に斯言たまふ視よ我汝らの中に氣息を入しめて汝等を生しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, '我筋を汝らの上に作り肉を汝らの上に生ぜしめ皮をもて汝らを蔽ひ氣息を汝らの中に與へて汝らを生しめん汝ら我がヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, '我命ぜられしごとく預言しけるが我が預言する時に音あり骨うごきて骨と骨あひ聯る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, '我見しに筋その上に出きたり肉生じ皮上よりこれを蔽ひしが氣息その中にあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, '彼また我に言たまひけるは人の子よ氣息に預言せよ人の子よ預言して氣息に言へ主ヱホバかく言たまふ氣息よ汝四方の風より來り此殺されし者等の上に呼吸きて是を生しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, '我命ぜられしごとく預言せしかば氣息これに入て皆生きその足に立ち甚だ多くの群衆となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, '斯て彼われに言たまふ人の子よ是等の骨はイスラエルの全家なり彼ら言ふ我らの骨は枯れ我らの望は竭く我儕絕はつるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, '是故に預言して彼らに言へ主ヱホバかく言たまふ吾民よ我汝等の墓を啓き汝らをその墓より出きたらしめてイスラエルの地に至らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'わが民よ我汝らの墓を開きて汝らを其墓より出きたらしむる時汝らは我のヱホバなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, '我わが靈を汝らの中におきて汝らを生しめ汝らをその地に安んぜしめん汝等すなはち我ヱホバがこれを言ひ之を爲たることを知にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'ヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '人の子よ汝一片の木を取てその上にユダおよびその侶なるイスラエルの子孫と書き又一片の木をとりてその上にヨセフおよびその侶なるイスラエルの全家と書べし是はエフライムの木なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, '而して汝これを俱にあはせて一の木となせ是汝の手の中にて相聯らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, '汝の民の人々汝に是は何の意なるか我儕に示さざるやと言ふ時は');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'これに言ふべし主ヱホバかく言たまふ我エフライムの手にあるヨセフとその侶なるイスラエルの支派の木を取り之をユダの木に合せて一の木となしわが手にて一とならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, '汝が書つけたるところの木を彼らの目のまへにて汝の手にあらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'かれらに言ふべし主ヱホバかく言たまふ我イスラエルの子孫をその往るところの國々より出し四方よりかれを集めてその地に導き');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'その地に於て汝らを一の民となしてイスラエルの山々にをらしめん一人の王彼等全體の王たるべし彼等は重て二の民となることあらず再び二の國に分れざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, '彼等またその偶像とその憎むべき事等およびその諸の愆をもて身を汚すことあらじ我かれらをその罪を犯せし諸の住處より救ひ出してこれを淸むべし而して彼らはわが民となり我は彼らの神とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'わが僕ダビデかれらの王とならん彼ら全體の者の牧者は一人なるべし彼らはわが律法にあゆみ吾法度をまもりてこれを行はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, '彼らは我僕ヤコブに我が賜ひし地に住ん是其先祖等が住ひし所なり彼處に彼らとその子及びその子の子とこしなへに住はん吾僕ダビデ長久にかれらの君たるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, '我かれらと和平の契約を立ん是は彼らに永遠の契約となるべし我かれらを堅うし彼らを殖しわが聖所を長久にかれらの中におかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, '我が住所は彼らの上にあるべし我かれらの神となり彼らわが民とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'わが聖所長久にかれらの中にあるにいたらば國々の民は我のヱホバにしてイスラエルを淸むる者なるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'ヱホバの言我にのぞみて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '人の子よロシ、メセクおよびトバルの君たるマゴグの地の王ゴグに汝の面をむけ之にむかひて預言し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, '言べし主ヱホバかく言たまふロシ、メセク、トバルの君ゴグよ視よ我なんぢを罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, '我汝をひきもどし汝の腮に鉤をほどこして汝および汝の諸の軍勢と馬とその騎者を曳いだすべし是みな其服粧に美を極め大楯小楯をもち凡て劍を執る者にして大軍なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'ペルシヤ、エテオピアおよびフテこれとともにあり皆楯と盔をもつ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'ゴメルとその諸の軍隊北の極のトガルマの族とその諸の軍隊など衆多の民汝とともにあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, '汝準備をなせ汝と汝にあつまれるところの軍隊みな備をせよ而して汝かれらの保護となれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, '衆多の日の後なんぢ罰せられん末の年に汝かの劍をのがれてかへり衆多の民の中より集りきたれる者の地にいたり久しく荒ゐたるイスラエルの山々にいたらん是は國々より導きいだされて皆安然に住ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, '汝その諸の軍隊および衆多の民をひきゐて上り暴風のごとく至り雲のごとく地を覆はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, '主ヱホバかくいひたまふ其日に汝の心に思想おこり惡き謀計をくはだてて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, '言ん我平原の邑々にのぼり穩にして安然に住る者等にいたらん是みな石垣なくして居り關も門もあらざる者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, '斯して汝物を奪ひ物を掠め汝の手をかへして彼の人の住むにいたれる墟址を攻め又かの國々より集りきたりて地の墺區にすみて群と財寶をもつところの民をせめんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'シバ、デダン、タルシシの商賈およびその諸の小獅子汝に言ん汝物を奪はんとて來れるや汝物を掠めんために軍隊をあつめしや金銀をもちさり群と財寶を取り多くの物を奪はんとするやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, '是故に人の子よ汝預言してゴグに言へ主ヱホバかくいひたまふ其日に汝わが民イスラエルの安然に住むを知ざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, '汝すなはち北の極なる汝の處より來らん衆多の民汝とともにあり皆馬に乗る其軍隊は大にしてその軍勢は夥多し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, '而して汝わが民イスラエルに攻きたり雲のごとくに地を覆はんゴグよ末の日にこの事あらんすなはち我汝をわが地に攻きたらしめ汝をもて我の聖き事を國々の民の目のまへにあらはして彼らに我をしらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, '主ヱホバかく言たまふ我の昔日わが僕なるイスラエルの預言者等をもて語りし者は汝ならずや即ち彼ら其頃年ひさしく預言して我汝を彼らに攻きたらしめんと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, '主ヱホバいひたまふ其日すなはちゴグがイスラエルの地に攻來らん日にわが怒面にあらはるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, '我嫉妬と燃たつ怒をもて言ふ其日には必ずイスラエルの地に大なる震動あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, '海の魚空の鳥野の獣凡て地に匍ふところの昆蟲凡て地にある人わが前に震へん又山々崩れ嶄巌たふれ石垣みな地に仆れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, '主ヱホバいひたまふ我劍をわが諸の山に召きたりて彼をせめしめん人々の劍その兄弟を撃べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, '我疫病と血をもて彼の罪をたださん我漲ぎる雨と雹と火と硫磺を彼とその軍勢および彼とともなる多の民の上に降すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, '而して我わが大なることと聖きことを明かにし衆多の國民の目のまへに我を示さん彼らはすなはち我のヱホバなることをしるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '人の子よゴグにむかひ預言して言へ主ヱホバかく言たまふロシ、メセク、トバルの君ゴグよ視よ我汝を罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, '我汝をひきもどし汝をみちびき汝をして北の極より上りてイスラエルの山々にいたらしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, '汝の左の手より弓をうち落し右の手より矢を落しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, '汝と汝の諸の軍勢および汝とともなる民はイスラエルの山々に仆れん我汝を諸の類の鷙鳥と野の獣にあたへて食しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, '汝は野の表面に仆れん我これを言ばなりと主ヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, '我マゴグと島々に安然に住る者とに火をおくり彼らをして我のヱホバなるを知しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, '我わが聖き名をわが民イスラエルの中に知しめ重てわが聖き名を汚さしめじ國々の民すなはち我がヱホバにしてイスラエルにありて聖者なることを知るにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, '主ヱホバいひたまふ視よ是は來れり成れり是わが言る日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, '茲にイスラエルの邑々に住る者出きたり甲冑 大楯 小楯 弓 矢 手鎗 手矛および槍を燃し焚き之をもて七年のあひだ火を燃さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, '彼ら野より木をとりきたること無く林より木をきりとらずして甲冑をもて火を燃しまた己を掠めし者をかすめ己の物を奪ひし者の物を奪はん主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, '其日に我イスラエルにおいて墓地をゴグに與へん是往來の人の谷にして海の東にあり是往來の人を礙げん其處に人ゴグとその群衆を埋めこれをゴグの群衆の谷となづけん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'イスラエルの家之を埋めて地を淸むるに七月を費さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, '國の民みなこれを埋め之によりて名をえん是我が榮光をあらはす日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, '彼等定れる人を選む其人國の中をゆきめぐりて往來の人とともにかの地の面に遺れる者を埋めてこれを淸む七月の終れる後かれら尋ぬることをなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, '國を行巡る者往來し人の骨あるを見るときはその傍に標をたつれば死人を埋むる者これをゴグの群衆の谷に埋む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, '邑の名もまた群衆ととなへられん斯かれら國を淸めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, '人の子よ主ヱホバかく言ふ汝諸の類の鳥と野の諸の獸に言べし汝等集ひ來り我が汝らのために殺せるところの犧牲に四方より聚れ即ちイスラエルの山々の上なる大なる犠牲に臨み肉を食ひ血を飮め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, '汝ら勇士の肉を食ひ地の君等の血を飮め 牡羊 羔羊 牡山羊 牡牛など凡てバシヤンの肥たる畜を食ヘ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, '汝らわが汝らのために殺せるところの犠牲につきて飽まで脂を食ひ醉まで血を飮べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, '汝らわが席につきて馬と騎者と勇士と諸の軍人に黶べしと主ヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, '我わが榮光を國々の民にしめさん國々の民みな我がおこなふ審判を見我がかれらの上に加ふる手を見るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, '是日より後イスラエルの家我ヱホバの己の神なることを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, '又國々の民イスラエルの家の擄へうつされしは其惡によりしなるを知べし彼等われに背きたるに因て我わが面を彼らに隱し彼らをその敵の手に付したれば皆劍に仆れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, '我かれらの汚穢と愆惡とにしたがひて彼らを待ひわが面を彼等に隱せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, '然ば主ヱホバかく言たまふ我今ヤコブの俘擄人を歸しイスラエルの全家を憐れみ吾聖き名のために熱中せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, '彼らその地に安然に住ひて誰も之を怖れしむる者なきに至る時はその我にむかひて爲たるところの諸の悖れる行爲のために愧べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, '我かれらを國々より導きかへりその敵の國々より集め彼らをもて我の聖き事を衆多の國民にしめす時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, '彼等すなはち我ヱホバの己の神なるを知ん是は我かれらを國々に移し又その地にひき歸りて一人をも其處にのこさざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, '我わが靈をイスラエルの家にそそぎたれば重て吾面を彼らに隱さじ主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, '我らの擄へ移されてより二十五年邑の撃破られて後十四年その年の初の月の十日其日にヱホバの手われに臨み我を彼處に携へ往く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, '即ち神異象の中に我をイスラエルの地にたづさへゆきて甚だ高き山の上におろしたまふ其處に南の方にあたりて邑のごとき者建てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, '彼我をひきて彼處にいたり給ふに一箇の人あるを見るその面容は銅のごとくにして手に麻の繩と間竿を執り門に立てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, '其人われに言けるは人の子よ汝目をもて視耳をもて聞き我が汝にしめす諸の事に心をとめよ汝を此にたづさへしはこれを汝にしめさんためなり汝が見るところの事を盡くイスラエルの家に告よと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, '斯ありて視るに家の外の四周に墻垣ありその人の手に六キユビトの間竿ありそのキユビトは各一キユビトと一手濶なり彼その墻の厚を量るに一竿ありその高もまた一竿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, '彼東向の門にいたりその階をのぼりて門の閾を量るに其濶一竿あり即ち第一の閾の濶一竿なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, '守房は長一竿廣一竿守房と守房の間は五キユビトあり内の門の廊の傍なる門の閾も一竿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, '内の門の廊を量るに一竿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, '又門の廊を量るに八キユビトありその柱は二キユビトなりその門の廊は内にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, '東向の門の守房は此旁に三箇彼處に三箇あり此三みな其寸尺おなじ柱もまた此處彼處ともにその寸尺おなじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, '門の入口の廣をはかるに十キユビトあり門の長は十三キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, '守房の前に一キユビトの界あり彼旁の界も一キユビトなり守房は此旁彼旁ともに六キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, '彼また此守房の屋背より彼屋背まで門をはかるに入口より入口まで二十五キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, '柱は六十キユビトに作れる者なり門のまはりに庭ありて柱にまでおよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, '入口の門の前より内の門の廊の前にいたるまで五十キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, '守房と門の内面の周圍の柱とに閉窓あり墻垣の差出たる處にもしかり内面の周圍には窓あり柱には棕櫚あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, '彼また我を外庭に携ゆくに庭の周圍に設けたる室と鋪石あり鋪石の上に三十の室あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, '鋪石は門の側にありて門の長におなじ是下鋪石なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, '彼下の門の前より内庭の外の前までの廣を量るに東と北とに百キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, '又外庭なる北向の門の長と寛をはかれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, '守房その此旁に三箇彼旁に三箇あり柱および差出たる處もあり是は前の門の寸尺のごとく長五十キユビト濶二十五キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'その窓と差出たる處と棕櫚は東向の門にある者の寸尺と同じ七段の階級を經て上るに差出たる處その前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, '内庭の門は北と東の門に向ふ彼門より門までを量るに百キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, '彼また我を南に携ゆくに南向の門ありその柱と差出たる處をはかるに前の寸尺の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, '是とその差出たる處の周圍に窓あり彼窓のごとしその門は長五十キユビト濶二十五キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, '七段の階級をへて登るべし差出たる處その前にありその柱の上には此旁に一箇彼旁に一箇の棕櫚あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, '内庭に南向の門あり門より門まで南の方をはかるに百キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, '彼我を携へて南の門より内庭に至る彼南の門をはかるにその寸尺前のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'その守房と柱と差出たる處は前の寸尺のごとしその門と差出たる處の周圍とに窓あり門の長五十キユビト濶二十五キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, '差出たる處周圍にありその長二十五キユビト濶五キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, '其差出たる處は外庭に出づその柱の上に棕櫚あり八段の階級をへて升るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, '彼また内庭の東の方に我をたづさへゆきて門をはかるに前の寸尺の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'その守房と柱および差出たる處は寸尺前のごとしその門と差出たる處の周圍とに窓あり門の長五十キユビト濶二十五キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'その差出たる處は外庭にいづ柱の上には此旁彼旁に棕櫚あり八段の階級をへて升るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, '彼われを北の門にたづさへゆきてこれを量るに寸尺おなじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'その守房と柱と差出たる處ありその周園に窓あり門の長五十キユビト濶二十五キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'その柱は外庭に出づ柱の上に此旁彼旁に棕櫚あり八段の階をへて升るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, '門の柱の傍に戸のある室あり其處は燔祭の牲を洗ふところなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, '門の廊に此旁に二の臺彼旁に二の臺あり其上に燔祭 罪祭 愆祭の牲畜を屠るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, '北の門の入口に升るに外面に於て門の廊の傍に二の臺あり亦他の旁にも二の臺あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, '門の側に此旁に四の臺彼旁に四の臺ありて八なり其上に屠ることを爲す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, '升口に琢石の四の臺あり長一キユビト半廣一キユビト半高一キユビトなり燔祭および犠牲を宰るところの器具をその上に置く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, '内の周圍に一手寛の曲釘うちてあり犠牲の肉は臺の上におかる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, '内の門の外において内庭に謳歌人の室あり一は北の門の側にありて南にむかひ一は南の門の側にありて北にむかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, '彼われに言ふ此南にむかへる室は殿をまもる祭司のための者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, '北にむかへる室は壇をまもる祭司のための者なり彼等はレビの子孫の中なるザドクの後裔にしてヱホバに近よりて之に事ふるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, '而して彼庭をはかるに長百キユビト寛百キユビトにして四角なり殿の前に壇あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, '彼殿の廊に我をひきゆきて廊の柱を量るに此旁も五キユビト彼方も五キユビトあり門の廣は此旁三キユビト彼旁三キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, '廊の長は二十キユビト寛は十一キユビト階級によりて升るべし柱にそふて柱あり此旁に一箇彼旁に一箇');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, '彼殿に我をひきゆきて柱を量るに此旁の寛六キユビト彼旁の寛六キユビト幕屋の寛なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, '戸の寛は十キユビト戸の側柱は此旁も五キユビト彼旁も五キユビト彼量るに其長四十キユビト廣二十キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, '内にいりて戸の柱を量るに二キユビトあり戸は六キユビト戸の濶は七キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, '彼量るに其長二十キユビト廣二十キユビトにして殿に向ふ彼我に言けるは是至聖所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, '彼室の壁を量るに六キユビトあり室の周圍の連接屋の寛は四キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, '連接屋は三階にして各三十の間あり室の壁周圍の連接屋の側にありて連接屋は之に連りて堅く立つ然れども室の壁に挿入て堅く立るにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, '連接屋は上にいたるに隨ひて廣くなり行く即ち家の圍牆家の四周に高くのぼれば家は上廣くして下のより上のにのぼる樣は中の割合にしたがふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, '我室に高き處あるを見る連接屋の基は一竿に足てその連接る處まで六キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, '連接屋にある外の壁の厚は五キユビト室の連接屋の傍の隙もまた然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, '室の間にあたりて家の四周に廣二十キユビトの處あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, '連接屋の戸は皆かの隙にむかふ一の戸は北にむかひ一の戸は南にむかふ其隙たる處は四周にありて廣五キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, '西の方にあたる離處の前の建物は廣七十キユビトその建物の周圍の壁は厚五キユビト長九十キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, '彼殿をはかるにその長百キユビトあり離處とその建物とその壁は長百キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, '殿の面および離處の東面は廣百キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, '彼後なる離處の前の建物の長を量れり其此旁彼旁の廊下は百キユビトありまた内殿と庭の廊を量り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, '彼の三にある處の閾と閉窓と周圍の廊下を量れり閾の對面に當りて周圍に嵌板あり窓まで地を量りしが窓は皆蔽ふてあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, '戸の上なる處内室と外の處および内外の周圍の諸の壁まで量ることをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'ケルビムと棕櫚と造りてあり二のケルビムの間毎に一本の棕櫚ありケルブには二の面あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, '此旁には人の面ありて棕櫚にむかひ彼旁には獅子の面ありて棕櫚にむかふ家の周圍に凡て是のごとく造りてあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, '地より戸の上までケルビムと棕櫚の設あり殿の壁も然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, '殿には四角の戸柱あり聖所の前にも同形の者あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, '壇は木にして高三キユビト長二キユビトなり是に隅木ありその臺と其周圍も木なり彼われに言けるは是はヱホバの前の壇なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, '殿と聖所とには二の戸あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'その戸に二の扉あり是二の開扉なり此戸に二箇彼戸に二箇の扉あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, '殿の戸にケルビムと棕櫚つくりてあり壁におけるがごとし外の廊の前に木の段あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, '廊の横壁と家の連接屋と段には此旁彼旁に閉窓と棕櫚あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, '彼われを携へ出して北におもむく路よりして外庭にいたり我を室に導く是は北の方にありて離處に對ひ建物に對ひをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'その百キユビトの長ある所の前に至るに戸は北の方にあり寛は五十キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, '内庭の二十キユビトなる處に對ひ外庭の鋪石に對ふ廊下の上に廊下ありて三なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, '室の前に寛十キユビトの路あり又内庭にいたるところの百キユビトの路あり室の戸は北にむかふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'その建物の上の室は下のと中のとに比れば狹し是は廊下の爲に其場を削らるればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, '是等は三階にして庭の柱の如くは柱あらず是をもて上のは下のと中のよりもその場狹し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, '室の前にあたりて外に垣あり室にそひて外庭にいたる其長五十キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, '外庭の室の長は五十キユビトにして殿に對ふ所は百キユビトあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'その下の方より是等の室いづ外庭よりこれに往ときは其入口東にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, '南の庭垣の廣き方にあたり離處とその建物にむかひて室あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, '北の方なる室のごとく其前に路ありその長寛およびその出口その建築みな同じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'その入口のごとく南の方なる室の入口も然り路の頭に入口あり是は垣に連るところの路にて東より來る路なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, '彼われに言けるは離處の前なる北の室と南の室は聖き室にしてヱホバに近くところの祭司の至聖き物を食ふべき所なり其處にかれら最聖き物 素祭 罪祭 愆祭の物を置べし其處は聖ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, '祭司は入たるときは聖所より外庭に出べからず彼等職掌を行ふところの衣服を其處に置べし是聖ければなり而して他の衣を着て民に屬するの處に近くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, '彼内室を量ることを終て東向の門の路より我を携へ出して四方を量れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, '彼間竿をもて東面を量るにその周圍 間竿五百竿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, '又北面をはかるにその周圍 間竿五百竿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'また南面をはかるに間竿五百竿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'また西面にまはりて量るに間竿五百竿あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, '斯四方を量れり周圍に牆ありその長 五百竿 寛 五百竿 聖所と俗所とを區別つなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, '彼われを携へて門にいたる其門は東に向ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, '時にイスラエルの神の榮光東よりきたりしがその聲大水の音のごとくにして地その榮光に照さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, '其狀を見るに我がこの邑を滅しに來りし時に見たるところの狀の如くに見ゆ又ケバル河の邊にて我が見しところの形のごとき形の者あり我すなはち俯伏す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'ヱホバの榮光東向の門よりきたりて室に入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, '靈われを引あげて内庭にたづさへいるにヱホバの榮光室に充をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, '我聽に室より我に語ふ者あり又人ありてわが傍に立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, '彼われに言たまひけるは人の子よ吾位のある所我脚の跖のふむ所此にて我長久にイスラエルの子孫の中に居んイスラエルの家とその王等再びその姦淫とその王等の屍骸およびその崇邱をもてわが聖き名を汚すことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, '彼らその閾をわが閾の側に設け其門柱をわが門柱の傍に設けたれば我と其等との間には只壁一重ありしのみ而して彼ら憎むべき事等をおこなひて吾が聖名を汚したるが故に我怒りてかれらを滅したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, '彼ら今はその姦淫とその王等の屍骸をわが前より除き去ん我また彼らの中に長久に居べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, '人の子よ汝この室をイスラエルの家に示せ彼らその惡を愧ぢまたこの式樣を量らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, '彼らその爲たる諸の事を愧なば彼らに此室の製法とその式樣その出口入口その一切の製法その一切の則その一切の製法その一切の法をしらしめよ是をかれらの目の前に書て彼らにその諸の製法とその一切の則を守りてこれを爲しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, '室の法は是なり山の頂の上なるその地は四方みな最聖し是室の法なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, '壇の寸尺はキユビトをもて言ば左のごとしそのキユビトは一キユビトと手寛あり壇の底は一キユビト寛一キユビトその周圍の邊は半キユビト是壇の臺なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, '土に坐れる底座より下の層まで二キユビト寛一キユビト又小き層より大なる層まで四キユビト寛一キユビトなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, '正壇は四キユビト壇の上の面に四の角あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, '壇の上の面は長十二キユビト寛十二キユビトにしてその四面角なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'その層は四方とも長十四キユビト寛十四キユビトその四周の縁は半キユビトその底は四方一キユビトその階は東に向ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, '彼われに言けるは人の子よ主ヱホバかく言たまふ壇を建て其上に燔祭を献げ血を灑ぐ日には是をその則とすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, '主ヱホバかく言ふ汝レビの支派ザドクの裔にして我にちかづき事ふるところの祭司等に犢なる牡牛を罪祭として與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, '又その血を取てこれをその四の角と層の四隅と四周の邊に抹り斯して之を淸め潔ようすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, '汝罪祭の牛を取てこれを聖所の外にて殿の中の定まれる處に焚べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, '第二日に汝全き牡山羊を罪祭に献ぐべし即ちかれら牡牛をもて淸めしごとく之をもて壇を淸むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, '汝潔禮を終たる時は犢なる牡牛の全き者および群の全き牡羊を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, '汝これをヱホバの前に持きたるべし祭司等これに鹽を撒かけ燔祭としてヱホバに献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, '七日の間汝日々に牡山羊を罪祭に供ふべしまた彼ら犢なる牡牛と群の牡羊との全き者を供ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, '七日の間かれら壇を潔ようしこれを淸めその手を滿すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, '是等の日滿て八日にいたりて後は祭司等汝らの燔祭と酬恩祭をその壇の上に奉へん我悦びて汝らを受納べし主ヱホバこれを言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, '斯て彼我を引て聖所の東向なる外の門の路にかへるに門は閉てあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'ヱホバすなはち我に言たまひけるは此門は閉おくべし開くべからず此より誰も入るべからずイスラエルの神ヱホバ此より入たれば是は閉おくべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'その君は君たるが故にこの内に坐してヱホバの前に食をなさん彼は門の廊の路より入りまたその路より出ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, '彼また我をひきて北の門の路より家の前に至りしが視るにヱホバの榮光ヱホバの家に滿ゐたれば我俯伏けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'ヱホバわれに言たまふ人の子よヱホバの家の諸の則とその諸の法につきて我が汝に告るところの諸の事に心を用ひ目を注ぎ耳を傾け又殿の入口と聖所の諸の出口に心を用ひよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, '而して悖れる者なるイスラエルの家に言べし主ヱホバ斯いふイスラエルの家よ汝らその行ひし諸の憎むべき事等をもて足りとせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, '即ち汝等は心にも割禮をうけず肉にも割禮をうけざる外國人をひききたりて吾聖所にあらしめてわが家を汚し又わが食なる脂と血を獻ぐることを爲り斯汝らの諸の憎むべき事の上に彼等また吾契約を破れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, '汝ら我が聖物を守る職守を怠り彼らをして我が聖所において汝らにかはりて我の職守を守らしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, '主ヱホバかく言たまふイスラエルの子孫の中に居るところの諸の異邦人の中凡て心に割禮をうけず肉に割禮をうけざる異邦人はわが聖所に入るべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, '亦レビ人も迷へるイスラエルがその憎むべき偶像をしたひて我を棄て迷ひし時に我を棄ゆきたる者はその罪を蒙るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, '即ち彼らは吾が聖所にありて下僕となり家の門を守る者となり家にて下僕の業をなさん又彼ら民のために燔祭および犠牲の牲畜を殺し民のまへに立てこれに事へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, '彼等その偶像の前にて民に事ヘイスラエルの家を礙かせて罪におちいらしめたるが故に主ヱホバ言ふ我手をあげて彼らを罰し彼らをしてその罪を蒙らしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, '彼らは我に近づきて祭司の職をなすべからず至聖所にきたりわが諸の聖き物に近よるべからずその恥とその行ひし諸の憎むべき事等の報を蒙るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, '我かれらをして宮守の職務をおこなはしめ宮の諸の業および其中に行ふべき諸の事を爲しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, '然どザドクの裔なるレビの祭司等すなはちイスラエルの子孫が我を棄て迷謬し時にわが聖所の職守を守りたる者等は我に近づきて事へ我まへに立ち脂と血をわれに獻げん主ヱホバこれを言ふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, '即ち彼等わが聖所にいり吾が臺にちかづきて我に事へわが職守を守るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, '彼等内庭の門にいる時は麻の衣を衣べし内庭の門および家において職をなす時は毛服を身につくべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, '首には麻の冠をいただき腰には麻の袴を穿つべし汗のいづるごとくに身をよそほふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, '彼ら外庭にいづる時すなはち外庭にいでて民に就く時はその職をなせるところの衣服を脱てこれを聖き室に置き他の衣服をつくべし是その服をもて民を聖くすること無らんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, '彼ら頭を剃べからず又髮を長く長すべからずその頭髮を剪るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, '祭司たる者は内庭に入ときに酒をのむべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, '又寡婦および去れたる婦を妻にめとるべからず唯イスラエルの家の出なる處女を娶るべし又は祭司の妻の寡となりし者を娶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, '彼らわが民を敎へ聖き物と俗の物の區別および汚れたる物と潔き物の區別を之に知しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, '爭論ある時は彼ら起ちて判决き吾定例にしたがひて斷决をなさん我が諸の節期において彼らわが法と憲を守るべく又わが安息日を聖くすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, '死人の許にいたりて身を汚すべからず只父のため母のため息子のため息女のため兄弟のため夫なき姉妹のためには身を汚すも宜し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, '斯る人にはその潔齋の後なほ七日を數へ加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, '彼聖所にいたり内庭にいり聖所にて職を執行ふ日には罪祭を獻ぐべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, '彼らの產業は是なり即ち我これが產業たり汝らイスラエルの中にて彼らに所有を與ふべからず我すなはちこれが所有たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, '祭物および罪祭愆祭の物是等を彼等食ふべし凡てイスラエルの中の奉納物は彼らに歸す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, '諸の物の初實の初および凡て汝らが献ぐる諸の献物みな祭司に歸すべし汝等その諸の麥粉の初を祭司に與ふべし是汝の家に幸福あらしめんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, '鳥にもあれ獸にもあれ凡て自ら死にたる者又は裂ころされし者をば祭司たる者食ふべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, '汝ら籤をひき地をわかちて產業となす時は地の一分を取り聖き者となしてヱホバに献ぐべし其長は二萬五千寛は一萬なるべし是は其四方周圍凡て聖し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, '此中聖所に屬する者は長五百寛五百にして周圍四角なり又五十キユビトの隙地その周圍にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, '汝この量りたる處より長二萬五千寛一萬の場を度り取るべし此うちに聖所至聖所を設くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, '是は地の聖場なりヱホバに近づき事ふる聖所の役者なる祭司等に屬すべし是かれらの家を建てまた聖所を設くる聖地なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, '又長二萬五千寛一萬の處家に事ふるレビ人に屬し其所有に二十の室あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'その献げたる聖地に並びて汝ら寛五千長二萬五千の處を分ち邑の所有となすべし是はイスラエルの全家に屬す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, '又君たる者の分はかの献げたる聖地と邑の所有の此處彼處にあり献げたる聖地に沿ひ邑の所有に沿ひ西は西にわたり東は東に渉るべし西の極より東の極まで其長は支派の分の一と等し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'イスラエルの中に彼が有ところの者は地にあり吾君等は重てわが民を虐ぐることなくイスラエルの家にその支派にしたがひて地を與へおかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, '主ヱホバかく言たまふイスラエルの君等よ汝ら足ことを知れ虐ぐることと掠むる事を止め公道と公義を行へ我民を逐放すことを止よ主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, '汝ら公平き權衡公平きエパ公平きバテを用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'エパとバテとはその量を同じうすべし即ちバテもホメルの十分一を容れエパもホメルの十分一を容るべしホメルに準じてその度量を定むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'シケルは二十ゲラに當る二十シケル二十五シケル十五シケルを汝等マネとなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, '汝らが献ぐべき献物は左のごとし一ホメルの小麥の中よりエパの六分一を献げ一ホメルの大麥の中よりエパの六分一を献ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, '油の例油のバテは是のごとし一コルの中よりバテの十分一を献ぐべしコルは十バテを容る者にて即ちホメルなり十バテ一ホメルとなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, '又イスラエルの腴なる地より群二百ごとに一箇の羊を出して素祭および燔祭 酬恩祭の物に供へ民の罪を贖ふことに用ひしむべし主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, '國の民みなこの獻物をイスラエルの君にもちきたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, '又君たる者は祭日朔日安息日およびイスラエルの家の諸の節期に燔祭 素祭 灌祭を奉ぐべし即ち彼イスラエルの家の贖罪をなすために罪祭 素祭 燔祭 酬恩祭を執行なふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, '主ヱホバかく言たまふ正月の元日に汝犢なる全き牡牛を取り聖所を淸むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, '又祭司は罪祭の牲の血を取りて殿の門柱にぬり壇の層の四隅と内庭の門の柱に塗べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, '月の七日に汝等また迷ふ人および拙き者のために斯なして殿のために贖をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, '正月の十四日に汝ら逾越節を守り七日の間祝をなし無酵パンを食ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'その日に君は己のため又國の諸の民のために牡牛を備へて罪祭となし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, '七日の節筵の間七箇の牡牛と七箇の牡羊の全き者を日々に七日の間備へてヱホバに燔祭となし又牡山羊を日々に備へて罪祭となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, '彼また素祭として一エパを牡牛のために一エパを牡山羊のために備へ油一ヒンをエパに加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, '七月の十五日の節筵に彼また罪祭 燔祭 素祭および油を是のごとく七日の間備ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, '主ヱホバかく言たまふ内庭の東向の門は事務をなすところの六日の間は閉ぢ置き安息日にこれを開き又月朔にこれを開くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, '君たる者は外より門の廊の路をとほりて入り門の柱の傍に立つべし祭司等その時かれの爲に燔祭と酬恩祭を備ふべし彼は門の閾において禮拜をなして出べし但し門は暮まで閉べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, '國の民は安息日と月朔とにその門の入口においてヱホバの前に禮拜をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, '君が安息日にヱホバに獻ぐる燔祭には六の全き羔羊と一の全き牡羊を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, '又素祭は牡羊のために一エパを用ふべし羔羊のために用ふる素祭はその手の出しうる程を以し一エパに油一ヒンを加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, '月朔には犢なる一頭の全き牡牛および六の羔羊と一の牡羊の全き者を用ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, '素祭は牛のために一エパ牡羊のために一エパ羔羊のために其手のおよぶ程を備へ一エパに油一ヒンを加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, '君は來る時に門の廊の路より入りまたその路より出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, '國の民祭日にヱホバの前に來る時は北の門よりいりて禮拜をなせる者は南の門より出で南の門より入る者は北の門より出べし其入りたる門より歸るべからず眞直に進みて出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, '君彼らの中にありてその入る時に入りその出る時に出べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, '祭日と祝日には素祭として牛のために一エパ牡羊のために一エパ羔羊のためにその手の出し得る程を備へ一エパに油一ヒンを加ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, '君もし自ら好んでヱホバに燔祭を備へんとし又は自ら好んで酬恩祭を備へんとせば彼のために東向の門を開くべし彼は安息日に爲ごとくその燔祭と酬恩祭を備ふべし又彼が出たる時はその出たる後に門を閉べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, '汝日々に一歳の全き羔羊一箇を燔祭としてヱホバに備ふべし即ち朝ごとにこれを備ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, '汝朝ごとに素祭をこれに加ふべし即ち一エパの六分一と麥粉を濕す油一ヒンの三分一とを素祭としてヱホバに獻ぐべし是は長久に續くところの例典なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, '即ち朝ごとに羔羊と素祭と油とを燔祭にそなへて止ことなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, '主ヱホバかく言たまふ君もし其子の一人に讓物をなす時は是その人の產業となりその子孫に傳はりて之が所有となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, '然ど若その產業の中をその僕の一人に與ふる時は是は解放の年までその人に屬し居て遂に君にかへるべし彼の產業は只その子孫にのみ傳はるべきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, '君たる者は民の產業を取て民をその所有より逐放すべからず只己の所有の中をその子等に傳ふべし是わが民のその所有をはなれて散ことなからんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, '斯て彼門の傍の入口より我をたづさへいりて北向なる祭司の聖き室にいたるに西の奧に一箇の處あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, '彼われに言けるは是は祭司が愆祭および罪祭の物を烹 素祭の物を拷ところなり斯するはこれを外庭に携へいでて民を聖くすることなからんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, '彼また我を外庭に携へいだして庭の四隅をとほらしむるに庭の隅々にまた庭あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, '即ち庭の四隅に庭の設ありてその長四十キユビト廣三十キユビトなり四隅の處その寸尺みな同じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, '凡てその四の周圍なるその建物の下に烹飪の處造りてあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, '彼われに云けるは是等は家の役者等が民の犧牲の品を烹る厨房なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, '斯てかれ我を室の門に携へかへりしが室の閾の下より水の東の方に流れ出るあり室の面は東にむかひをりその水下より出で室の右の方よりして壇の南より流れ下る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, '彼北の門の路より我を携へいだして外面をまはらしめ東にむかふ外の門にいたらしむるに水門の右の方より流れ出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'その人東に進み手に度繩を持て一千キユビトを度り我に水をわたらしむるに水踝骨にまでおよぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, '彼また一千を度り我を渉らしむるに水膝にまでおよぶ而してまた一千を度り我を渉らしむるに水腰にまで及ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, '彼また一千を度るに早わが渉るあたはざる河となり水高くして泅ぐほどの水となり徒渉すべからざる河とはなりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, '彼われに言けるは人の子よ汝これを見とめたるやと乃ち河の岸に沿て我を將かへれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, '我歸るに河の岸の此方彼方に甚だ衆多の樹々生ひ立るあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, '彼われに言ふこの水東の境に流れゆきアラバにおち下りて海に入る是海に入ればその水すなはち醫ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, '凡そ此河の往ところには諸の動くところの生物みな生ん又甚だ衆多の魚あるべし此水到るところにて醫すことをなせばなり此河のいたる處にては物みな生べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, '漁者その傍に立んエンゲデよりエネグライムまでは網を張る處となるべしその魚はその類にしたがひて大海の魚のごとく甚だ多からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, '但しその澤地と濕地とは愈ることあらずして鹽地となりをるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, '河の傍その岸の此旁彼旁に食はるる果を結ぶ諸の樹生そだたんその葉は枯ずその果は絕ず月々新しき果をむすぶべし是その水かの聖所より流れいづればなりその果は食となりその葉は藥とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, '主ヱホバかく言たまふ汝らイスラエルの十二の支派の中に地を分ちてその產業となさしむるにはその界を斯さだむべしヨセフは二分を得べきなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, '汝ら各々均しく之を獲て產業とすべし是は我が手をあげて汝らの先祖等に與へし者なり斯この地汝らに歸して產業とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, '地の界は左のごとし北は大海よりヘテロンの路をへてゼダデの方にいたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'ハマテ、ベロクにいたりダマスコの界とハマテの界の間なるシブライムにいたりハウランの界なるハザルハテコンにいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, '海よりの界はダマスコの界のハザルエノンにいたる北の方においてはハマテその界たり北の方は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, '東の方はハウラン、ダマスコ、ギレアデとイスラエルの地との間にヨルダンあり汝らかの界より東の海までを量るべし東の方は斯のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, '南の方はタマルよりメリボテカデシにおよび河に沿て大海にいたる南の方は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, '西の方は大海にしてこの界よりハマテにおよぶ西の方は是のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, '汝らイスラエルの支派にしたがひて此地を汝らの中にわかつべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, '汝ら籤をもて之を汝らの中に分ち又汝らの中にをりて汝らの中に子等を擧けたる異邦人の中に分ちて產業となすべし斯る人は汝らにおけることイスラエルの子孫の中に生れたる本國人のごとし彼らも汝らと共に籤をひきてイスラエルの支派の中に產業を得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, '異邦人にはその住ところの支派の中にて汝ら之に產業を與ふべし主ヱホバこれを言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, '支派の名は是のごとしダンの一分は北の極よりヘテロンの路の傍にいたりハマテにいたり北におもむきてダマスコの界なるハザルエノンにいたりハマテの傍におよぶ是その東の方と西の方なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'アセルの一分はダンの界にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'ナフタリの一分はアセルの界にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'マナセの一分はナフタリの界にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'エフライムの一分はマナセの界にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'ルペンの一分はエフライムの界にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'ユダの一分はルベンの界にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'ユダの界にそひて東の方より西の方にわたる處をもて汝らが献ぐるところの献納地となすべし其廣二萬五千其東の方より西の方にわたる長は他の一の分のごとし聖所はその中にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, '即ち汝らがヱホバに献ぐるところの献納地は長二萬五千廣一萬なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'この聖き献納地は祭司に屬し北は二萬五千西は廣一萬東は廣一萬南は長二萬五千ヱホバの聖所その中にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'ザドクの子孫たる者すなはち我が職守をまもりイスラエルの子孫が迷謬し時にレビ人の迷ひしごとく迷はざりし者の中聖別られて祭司となれる者に是は屬すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'その献げたる地の中より一分の至聖き献納地かれらに屬してレビの境界に沿ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'レビ人の地は祭司の地にならびて其長二萬五千廣一萬なり即ちその都の長二萬五千その廣一萬なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, '彼らこれを賣べからず換べからず又その地の初實は人にわたすべからず是ヱホバに屬する聖物なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, '彼二萬五千の處に沿て殘れる廣五千の處は俗地にして邑を建て住家を設くべし又郊地となすべし邑その中にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'その廣狹は左のごとし北の方四千五百南の方四千五百東の方四千五百西の方四千五百');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, '邑の郊地は北二百五十南二百五十東二百五十西二百五十');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, '聖き献納地にならびて餘れる處の長は東へ一萬西へ一萬なり是は聖き献納地に並びその產物は邑の役人の食物となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, '邑の役人はイスラエルの諸の支派より出てその職をなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'その献納地の惣體は堅二萬五千横二萬五千なりこの聖き献納地の四分の一にあたる處を取て邑の所有となすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, '聖き献納地と邑の所有との此旁彼旁に餘れる處は君に屬すべし是はすなはち献納地の二萬五千なる所に沿て東の界にいたり西はかの二萬五千なる所にそひて西の界に至りて支派の分と相並ぶ是君に屬すべし聖き献納地と室の聖所とはその中間にあるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, '君に屬する所の中間にあるレビ人の所有と邑の所有の兩傍ユダの境とベニヤミンの境の間にある所は君の所有たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'その餘の支派はベニヤミンの一分東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'シメオンの一分はベニヤミンの境にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'イッサカルの一分はシメオンの境にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'ゼブルンの一分はイッサカルの境にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'ガドの一分はゼブルンの境にそひて東の方より西の方にわたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, '南の方はその界ガドの境界にそひてタマルよりメリボテカデシにおよび河に沿て大海にいたる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, '是は汝らが籤をもてイスラエルの支派の中にわかちて產業となすべき地なりその分は斯のごとし主ヱホバこれを言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, '邑の出口は斯のごとしすなはち北の方の廣四千五百あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, '邑の門はイスラエルの支流の名にしたがひ北に三あり即ちルベンの門一ユダの門一レビの門一');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, '東の方も四千五百にして三の門あり即ちヨセフの門一ベニヤミンの門一ダンの門一');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, '南の方も四千五百にして三の門ありすなはちシメオンの門一イツサカルの門一ゼブルンの門一');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, '西の方も四千五百にしてその門三あり即ちガドの門一アセルの門一ナフタリの門一');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, '四周は一萬八千あり邑の名は此日よりヱホバ此に在すと云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'ユダの王エホヤキムの治世の第三年にバビロンの王ネブカデネザル、ヱルサレムにきたりて之を攻圍みしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, '主ユダの王ヱホヤキムと神の家の器具幾何とをかれの手にわたしたまひければ則ちこれをシナルの地に携へゆきて己の神の家にいたりその器具を己の神の庫に蔵めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, '茲に王寺人の長アシベナズに命じてイスラエルの子孫の中より王の血統の者と貴族たる者幾何を召寄しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, '即ち身に疵なく容貌美しくして一切の智慧の道に頴く知識ありて思慮深く王の宮に侍るに足る能幹ある少き者を召寄しめこれにカルデヤ人の文學と言語とを學ばせんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, '是をもて王は命を下して日々に王の用ゐる饌と王の飮む酒とを彼らに與へしめ三年の間かく彼らを養ひ育てしめんとす是その後に彼らをして王の前に立ことを得せしめんとてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, '是等の中にユダの人ダニエル、ハナニヤ、ミシヤエル、アザリヤありしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, '寺人の長かれらに名をあたへてダニエルをベルテシヤザルと名けハナニヤをシヤデラクと名けミシヤエルをメシヤクと名けアザリヤをアベデネゴと名く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, '然るにダニエルは王の用ゐる饌と王の飮む酒とをもて己の身を汚すまじと心に思ひさだめたれば己の身を汚さざらしめんことを寺人の長に求む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, '以前よりヱホバ、ダニエルをして寺人の長の慈悲と寵愛とを蒙らしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, '是において寺人の長ダニエルに言けるは吾主なる王すでに命をくだして汝らの食物と汝らの飮物とを頒たしめたまへば我かれを畏る恐くは彼なんぢらの面の其同輩の少者等と異にして憂色あるを見ん然る時は汝らのために我首王の前に危からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, '寺人の長はメルザル官をしてダニエル、ハナニヤ、ミシヤエル及びアザリヤを監督らせ置たればダニエル之に言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '請ふ十日の間僕等を驗したまへ即ち我らには菜蔬を與へて食せ水を與へて飮せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, '而して我らの面と王の饌を食ふ少者どもの面とを較べ見汝の視るところにしたがひて僕等を待ひたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, '是において彼この事を聽いれ十日のあひだ彼らを驗しけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, '十日の後にいたりて見るに王の饌を食へる諸の少者よりも彼らの面は美しくまた肥え膩つきてありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'メルザル官すなはち彼らの分なる饌と彼らの飮べき酒とを撤きさりて菜蔬をこれに與へたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'この四人の少者には神知識を得させ諸の文學と智慧に頴からしめたまへりダニエはまた能く各諸の異象と夢兆を暁る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, '王かねて命をくだし少者どもを召いるる迄に經べき日を定めおきしがその日數も過たるに因て寺人の長かれらを引てネブカデザルの前にいたりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, '王かれらと言談へり彼ら一切の中にはダニエル、ハナニヤ、ミシヤエル、アザリヤに比ぶ者あらざりければこの四人は王の前に侍れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, '王かれらに諸の事を詢たづね見に彼らは智慧の學においてその全國の博士と法術士に愈ること十倍なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'ダニエルはクロス王の元年までありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'ネブカデネザルの治世の二年にネブカデネザル夢を見それがために心に思ひなやみて復睡ること能はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, '是をもて王は命を下し王のためにその夢を解せんとて博士と法術士と魔術士とカルデヤ人とを召しめたれば彼ら來りて王の前に立つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, '王すなはち彼らにむかひ我夢を見その夢の義を知んと心に思ひなやむと言ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'カルデヤ人等スリア語をもて王に申しけるは願くは王長壽かれ請ふ僕等にその夢を語りたまへ我らその解明を進めたてまつらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, '王こたへてカルデヤ人に言けるは我すでに命を出せり汝等もしその夢とこれが解明とを我に示さざるにおいては汝らの身は切裂れ汝らの家は厠にせられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, '又汝らもしその夢とこれが解明を示さば贐物と賞賚と大なる尊榮とを我より獲ん然ばその夢と之が解明を我に示せ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, '彼らまた對へて言けるは願くは王僕どもにその夢を語りたまへ然ば我らその解明を奏すべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, '王こたへて言けるは我あきらかに知る汝らは吾命の下りしを見るが故に時を延さんことを望むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, '汝らもしその夢を我に示さずば汝らを處置するの法は只一のみ汝らは相語らひて虚言と妄誕なる詞を我前にのべて時の變るを待んとするなり汝ら今先その夢を我に示せ然すれば汝らがその解明をも我にしめし得ることを我しらんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'カルデヤ人等こたへて王の前に申しけるは世の中には王のその事を示し得る人一箇もなし是をもて王たる者主たる者君たる者等の中に斯る事を博士または法術士またはカルデヤ人に問たづねし者絶てあらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, '王の問たまふその事は甚だ難し肉身なる者と共に居ざる神々を除きては王の前にこれを示すことを得る者無るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, '斯りしかば王怒を發し大に憤りバビロンの智者をことごとく殺せと命じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, '即ち此命くだりければ智者等は殺されんとせり又ダニエルとその同僚をも殺さんともとめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, '茲に王の侍衛の長アリオク、バビロンの智者等を殺さんとて出きたりければダニエル遠慮と智慧とをもて之に應答せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'すなはち王の高官アリオクに對へて言けるは王なにとて斯すみやかにこの命を下したまひしやとアリオクその事をダニエルに告しらせたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'ダニエルいりて王に乞求めて言ふ暫くの時日を賜へ然ばその解明を王に奏せんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, '斯てダニエルその家にかへりその同僚ハナニヤ、ミシヤエルおよびアザリヤにこの事を告しらせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, '共にこの秘密につき天の神の憐憫を乞ひダニエルとその同僚等をしてその他のバビロンの智者とともに滅びさらしめんことを求めたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'ダニエルつひに夜の異象の中にこの秘密を示されければダニエル天の神を稱賛ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, '即ちダニエル應へて言けるは永遠より永遠にいたるまでこの神の御名は讃まつるべきなり智慧と權能はこれが有なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, '彼は時と期とを變じ王を廢し王を立て智者に智慧を與へ賢者に知識を賜ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, '彼は深妙秘密の事を顯し幽暗にあるところの者を知たまふまた光明彼の裏にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'わが先祖等の神よ汝は我に智慧と權能を賜ひ今われらが汝に乞求めたるところの事を我にしめし給へば我感謝して汝を稱賛ふ即ち汝は王のかの事を我らに示したまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, '是においてダニエルは王がバビロンの智者等を殺すことを命じおけるアリオクの許にいたり即ちいりてこれに言けるはバビロンの智者等を殺す勿れ我を王の前に引いたれよ我その解明を王に奏上ぐべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'アリオクすなはちダニエルを引て急ぎ王の前にいたり王にまうしけるは我ユダの俘囚人の中に一箇の人を得たり是者その解明を王にまうしあげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, '王こたへてベルテシヤザルと名くるダニエルに言けるは汝は我が見たる夢とその解明とを我に知らすることを得るやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'ダニエルすなはち應へて王の前に言けるは王の問たまふ秘密は智者法術士博士卜筮師など之を王に奏上ぐることを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, '然ど天に一の神ありて秘密をあらはし給ふ彼後の日に起らんところの事の如何なるかをネブカデネザル王にしらせたまふなり汝の夢汝が牀にありて想見たまひし汝の腦中の異象は是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, '王よ汝牀にいりし時將來の事の如何を想ひまはしたまひしが秘密を顯す者將來の事の如何を汝にしめし給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, '我がこの示現を蒙れるは凡の生る者にまさりて我に智慧あるに由にあらず唯その解明を王に知しむる事ありて王のつひにその心に想ひたまひし事を知にいたり給はんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, '王よ汝は一箇の巨なる像の汝の前に立るを見たまへり其像は大くしてその光輝は常ならずその形は畏ろしくあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, '其像は頭は純金 胸と兩腕とは銀 腹と腿とは銅');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, '脛は鐵 脚は一分は鐵一分は泥土なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, '汝見て居たまひしに遂に一箇の石人手によらずして鑿れて出でその像の鐵と泥土との脚を撃てこれを碎けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, '斯りしかばその鐵と泥土と銅と銀と金とは皆ともに碎けて夏の禾場の糠のごとくに成り風に吹はらはれて止るところ無りき而してその像を撃たる石は大なる山となりて全地に充り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, '是その夢なり我らその解明を王の前に陳ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, '王よ汝は諸王の王にいませり即ち天の神汝に國と權威と能力と尊貴とを賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'また人の子等野の獣畜および天空の鳥は何處にをる者にもあれ皆これを汝の手に與へて汝にこれをことごとく治めしめたまふ汝はすなはち此金の頭なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, '汝の後に汝に劣る一の國おこらんまた第三に銅の國おこりて全世界を治めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, '第四の國は堅きこと鐵のごとくならん鐵は能く萬の物を毀ち碎くなり 鐵の是等をことごとく打碎くがごとく其國は毀ちかつ碎くことをせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, '汝その足と足の趾を見たまひしに一分は陶人の泥土一分は鐵なりければその國は分裂たる者ならん又汝鐵と粘土との混和たるを見たまひたればその國は鐵のごとく強からん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'その足の趾の一分は鐵一分は泥土なりしごとくその國は強きところもあり脆きところも有ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, '汝が鐵と粘土との混りたるを見たまひしごとく其等は人草の種子と混らん然ど鐵と泥土との相合せざるごとく彼と此と相合すること有じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'この王等の日に天の神一の國を建たまはん是は何時までも滅ぶること無らん此國は他の民に歸せず却てこの諸の國を打破りてこれを滅せん是は立ちて永遠にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'かの石の人手によらずして山より鑿れて出で鐵と銅と泥土と銀と金とを打碎きしを汝が見たまひしは即ちこの事なり大御神この後に起らんところの事を王にしらせたまへるなりその夢は眞にしてこの解明は確なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, '是においてネブカデネザル王は俯伏てダニエルを拝し禮物と香をこれに献ぐることを命じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, '而して王こたへてダニエルに言けるは汝がこの秘密を明かに示すことを得たるを見れば誠に汝らの神は神等の神王等の主にして能く秘密を示す者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'かくて王はダこエルに高位を授け種々の大なる賜物を與へてこれをバビロン全州の總督となしまたバビロンの智者等を統る者の首長となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, '王またダニエルの願によりてシヤデラクとメシヤクとアベデネゴを擧てバビロン州の事務をつかさどらしめたりダニエルは王の宮にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, '茲にネブカデネザル王 一箇の金の像を造れりその高は六十キユビトその横の廣は六キユビトなりき即ちこれをバビロン州のドラの平野に立たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, '而してネブカデネザル王は州牧將軍方伯刑官庫官法官士師および州郡の諸有司を召集めそのネブカデネザル王の立たる像の告成禮に臨ましめんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, '是においてその州牧將軍方伯刑官庫官法官士師および州郡の諸有司等はネブカデネザル王の立たる像の告成禮に臨みそのネブカデネザル王の立たる像の前に立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, '時に傳令者大聲に呼はりて言ふ諸民諸族諸音よ汝らは斯命ぜらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, '汝ら喇叭簫琵琶琴瑟篳篥などの諸の樂器の音を聞く時は俯伏しネブカデネザル王の立たまへる金像を拝すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, '凡て俯伏て拝せざる者は即時に火の燃る爐の中に投こまるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, '是をもて諸民等喇叭簫琵琶琴瑟などの諸の樂器の音を聞くや直に諸民諸族諸音みな俯伏しネブカデネザル王の立たる金像を拝したり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'その時或カルデヤ人等進みきたりてユダヤ人を讒奏せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, '即ち彼らネブカデネザル王に奏聞して言ふ願くは王長壽かれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, '王よ汝は命を出して宣へり凡て喇叭簫琵琶琴瑟篳篥などの諸の樂器の音を聞く者はみな俯伏しこの金像を拝すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, '凡て俯伏し拝せざる者はみな火の燃る爐の中に投こまるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, '此に汝が立てバビロン州の事務を司どらせ給へるユダヤ人シヤデラク、メシヤクおよびアベデネゴあり王よ此人々は汝を尊ばず汝の神々にも事へず汝の立たまへる金像をも拝せざるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, '是においてネブカデネザル怒りかつ憤りてシヤデラク、メシヤクおよびアベデネゴを召寄よと命じければ即ちこの人々を王の前に引きたりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'ネブカデネザルかれらに問て言けるはジヤデラク、メシヤク、アベデネゴよ汝ら我神に事へずまた我が立たる金像を拝せざるは是故意にするなるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, '汝らもし何の時にもあれ喇叭簫琵琶琴瑟篳篥などの諸の樂器の音を聞く時に俯伏し我が造れる像を拝することを爲ば可し然ど汝らもし拝することをせずば即時に火の燃る爐の中に投こまるべし何の神か能く汝らをわが手より救ひいだすことをせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'シヤデラク、メシヤクおよびアベデネゴ對へて王に言けるはネブカデネザルよこの事においては我ら汝に答ふるに及ばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'もし善らんには王よ我らの事ふる我らの神我らを救ふの能あり彼その火の燃る爐の中と汝の手の中より我らを救ひいださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, '假令しからざるも王よ知たまへ我らは汝の神々に事へずまた汝の立たる金像を拝せじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, '是においてネブカデネザル怒氣を充しシヤデラク、メシヤクおよびアベデネゴにむかひてその面の容を變へ即ち爐を常に熱くするよりも七倍熱くせよと命じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'またその軍勢の中の力強き人々を喚てシヤデラク、メシヤクおよびアベデネゴを縛りてこれを火の燃る爐の中に投こめと命じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, '是をもて此人々はその褲子羽織外套およびその他の服装を着たるままにて縛られて火の燃る爐の中に投こまれたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, '王の命はなはだ急にして爐は甚だしく熱しゐたれば彼のシヤデラク、メシヤクおよびアベデネゴを引抱へゆける者等はその火焔に燒ころされたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'また此シヤデラク、メシヤク、デベデネゴの三人は縛られたるままにて燃る爐の中に落いりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, '時にネブカデネザル王驚きて急忙しくたちあがり大臣等に言ふ我らは三人を縛りて火の中に投いれざりしや彼ら王にこたへて言ふ王よ然りと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, '王また應へて言ふ今我見るに四人の者縲絏解て火の中に歩みをり凡て何の害をも受ずまたその第四の者の容は神の子のごとしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'ネブカデネザルすなはちその火の燃る爐の口に進みよりて呼て言ふ至高神の僕シヤデラク、メシヤク、アベデネゴよ汝ら出きたれと是においてシヤデラク、メシヤクおよびアベデネゴその火の中より出きたりしかば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, '州牧將軍方伯および王の大臣等集りて比人々を見たり此人々の身は火もこれを害する力なかりきまたその頭の髮は燒けずその衣裳は傷ねず火の臭氣もこれに付ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'ネブカデネザルすなはち宣て曰くシヤデラク、メシヤク、アベデネゴの神は讃べき哉彼その使者を遣りて己を賴む僕を救へりまた彼らは自己の神の外には何の神にも事へずまた拝せざらんとて王の命をも用ひず自己の身をも捨んとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, '然ば我今命を下す諸民諸族諸音の中凡てシヤデラク、メシヤクおよびアベダネゴの神を詈る者あらばその身は切裂れその家は厠にせられん其は是のごとくに救を施す神他にあらざればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'かくて王またシヤデラク、メシヤクおよびアベデネゴの位をすすめてバビロン州にをらしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'ネブカデネザル王全世界に住める諸民諸族諸音に諭す願くは大なる平安汝らにあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, '至高神我にむかひて徴證と奇蹟を行へり我これを知しむることを善と思ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, '嗚呼大なるかなその徴證嗚呼盛なるかなその奇蹟その國は永遠の國その權は世々限なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, '我ネブカデネザルわが家に安然に居りわが宮に榮え居れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, '我一の夢を見て之がために懼れ即ち床にありてその事を想ひめぐらしその我腦中の異象のために心をなやませり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, '是に於て我命を下しバビロンの智者をことごとく我前に召よせしめてその夢の解明を我にしめさせんと爲たれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'すなはち博士法術士カルデヤ人卜筮師等きたりしに囚て我その夢を彼らに語りけるに彼らはその解明を我にしめすことを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'かくて後ダニエルわが前に來れり彼の名は吾神の名にしたがひてベルテシヤザルと稱へられその裏には聖神の霊やどれり我その夢を彼の前に語りて曰けらく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '博士の長ベルテシヤザルよ我しる汝の裏には聖神の霊やどれば如何なる秘密も汝には難き事なし我が夢に見たるところの事等を聞きその解明を我に告げよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, '我が床にありて見たる吾腦中の異象は是のごとし我觀しに地の當中に一の樹ありてその丈高かりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'その樹長じて強固なり天に達するほどの高となりて地の極までも見えわたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'その葉は美しくその菓は饒にして一切の者その中より食を得また野の獣その蔭に臥し空の鳥その枝に棲み凡て血氣ある者みな是によりて身を養ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, '我床にありて得たる腦中の異象の中に一箇の警寤者一箇の聖者の天より下るを見たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, '彼聲高く呼はりて斯いへり此樹を伐たふしその枝を斫はなしその葉を搖おとしその果を打散し獣をしてその下より逃はしらせ鳥をしてその枝を飛さらしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, '但しその根の上の斬株を地に遺しおき鐵と銅の索をかけて之を野の草の中にあらしめよ是は天よりくだる露に濕れまた地の草の中にて獣とその分を同じうせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, '又その心は變りて人間の心のごとくならず獣の心を稟て七の時を經ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'この事は警寤者等の命によりこの事は聖者等の言による是至高者人間の國を治めて自己の意のままにこれを人に與へまた人の中の最も賤き者をその上に立たまふといふ事を一切の者に知しめんがためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, '我ネブカデネザル王この夢を見たりベルテシヤザルよ汝その解明を我に述よ我國の智者は執も皆その解明を我に示すことを得ざりしが汝は之を能せん其は汝の裏には聖神の霊やどればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'その時ダニエル又の名はベルテシヤザルとい者暫時の間驚き居り心に深く懼れたれば王これに告て言りベルテシヤザルよ汝この夢とその解明のために懼るるにおよばずとベルテシヤザルすなはち答へて言けらく我主よ願くはこの夢汝を惡む者の上にかからん事を願くは此解明汝の敵にのぞまんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, '汝が見たまひし樹すなはちその長じて強くなり天に達するほどの高となりて地の極までも見えわたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'その葉は美しくその果は饒にして一切の者その中より食を得またその下に野の獣臥しその枝に空の鳥棲たる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, '王よ是はすなはち汝なり汝は長じて強くなり汝の勢ひは盛にして天におよび汝の權は地の極にまでおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, '王また一箇の警寤者一箇の聖者の天より下りて斯言ふを見たまへり云くこの樹を伐たふして之をそこなへ但し其根の上の斬株を地に遺しおき鐵と銅の索をかけて之を野の草の中にあらしめよ是は天より下る露に濡れ野の獣とその分を同じうして七の時を經ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, '王よその解明は是の如し是即ち至高者の命にして王我主に臨まんとする者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, '即ち汝は逐れて世の人と離れ野の獣とともに居り牛のごとくに草を食ひ天よりくだる露に濡れん是の如くにして七の時を經て汝つひに知ん至高者人間の國を治めて自己の意のままに之を人に與へ給ふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, '又彼らその樹の根の上の斬株を遺しおけと言たれば汝の國は汝が天は主たりと知にいたる時まで汝を離れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, '然ば王よ吾諌を容れ義をおこなひて罪を離れ貧者を憐みて惡を離れよ然らば汝の平安あるひは長く続かんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'この事みなネブカデネザル王に臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, '十二箇月を經て後王バビロンの王宮の上に歩みをり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, '王すなはち語りて言ふ此大なるバビロンは我が大なる力をもて建て京城となし之をもてわが威光を耀かす者ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'その言なほ王の口にある中に天より聲降りて言ふネブカデネザル王よ汝に告ぐ汝は國の位を失はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, '汝は逐れて世の人と離れ野の獣と共に居り牛のごとくに草を食はん斯の如くにして七の時を經て汝つひに知ん至高者人間の國を治めて己れの意のままにこれを人に與へたまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'その時直にこの事ネブカデネザルに臨み彼は逐れて世の人に離れ牛のごとくに草を食ひてその身は天よりくだる露に濡れ終にその髮毛は鷲の羽のごとくになりその爪は鳥の爪のごとくになりぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, '斯てその日の滿たる後我ネブカデネザル目をあげて天を望みしにわが分別性我に歸りたれば我至高者に感謝しその永遠に生る者を讃かつ崇めたり彼の御宇は永遠の御宇彼の國は世々かぎり無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '地上の居民は凡て無き者のごとし天の衆群にも地の居民にも彼はその意のままに事をなしたまふ誰も彼の手をおさへて汝なんぞ然するやと言ことを得る者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'この時わが分別性かく我に歸りたりしがわが國の榮光につきてはまた我の尊嚴と光耀我にかへれり且また大臣牧伯等我に請求めて我ふたたび國の祚を踐み前よりも著しく威光を増たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '是において我ネブカデネザル今は天の王を讃頌へかつ崇む彼の作爲は凡て眞實彼の道は正義自ら高ぶる者は彼能くこれを卑くしたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'ベルシヤザル王その大臣一千人のために酒宴を設けその一千人の者の前に酒を飮たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, '酒の進むにいたりてベルシヤザルはその父ネブカデネザルがヱルサレムの宮より取きたりし金銀の器を携へいたれと命ぜり是王とその大臣および王の妻妾等みな之をもて酒を飮んとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, '是をもてそのヱルサレムなる神の宮の内院より取たりし金の器を携へいたりければ王とその大臣および王の妻妾等これをもて飮めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'すなはち彼らは酒をのみて金銀銅鐵木石などの神を讃たたへたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'その時に人の手の指あらはれて燭臺と相對する王の宮の粉壁に物書り王その物書る手の末を見たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, '是において王の愉快なる顔色は變りその心は思ひなやみて安からず腿の關節はゆるみ膝はあひ撃り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, '王すなはち大聲に呼はりて法術士カルデヤ人卜筮師等を召きたらしめ而して王バビロンの智者等に告て言ふこの文字を讀みその解明を我に示す者には紫の衣を衣せ頸に金の鏈をかけさせて之を國の第三の牧伯となさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, '王の智者等は皆きたりしかどもその文字を讀こと能はずまたその解明を王にしめすこと能はざりければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'ベルシヤザル王おほいに思ひなやみてその顔色を失へりその大臣等もまた驚き懼れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, '時に大后王と大臣等の言を聞てその酒宴の室にいりきたり大后すなはち陳て言ふ願くは王長壽かれ汝心に思ひなやむ勿れまた顔色を失ふにおよばず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, '汝の國に聖神の霊のやどれる一箇の人あり汝の父の代に彼聰明了知および神の智慧のごとき智慧あることを顯せり汝の父ネブカデネザル王すなはち汝の父の王彼を立てて博士法術士カルデヤ人卜筮師等の長となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, '彼はダニエルといへる者なるが王これにベルテシヤザルといふ名を與へたり彼は心の殊勝たる者にて了知あり知識ありて能く夢を解き隠語を解き難問を解くなり然ばダニエルを召されよ彼その解明をしめさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, '是においてダニエル召れて王の前に至りければ王ダニエルに語りて言ふ汝は吾父の王がユダより曳きたりしユダの俘囚人なるそのダニエルなるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, '我聞になんぢの裏には神の霊やどりをりて汝は聰明了知および非凡の智慧ありと云ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, '我智者法術士等を吾前に召よせてこの文字を讀しめその解明を我にしめさせんと爲たれども彼らはこの事の解明を我にしめすことを得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, '我聞に汝は能く物事の解明をなしかつ難問を解くと云ふ然ば汝もし能くこの文字を讀みその解明を我に示さば汝に紫の衣を衣せ金の索を汝の頸にかけさせて汝をこの國の第三の牧伯となさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'ダニエルこたへて王に言けるは汝の賜物は汝みづからこれを取り汝の饒物はこれを他の人に與へたまへ然ながら我は王のためにその文字を讀みその解明をこれに知せたてまつらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, '王よ至高神汝の父ネブカデネザルに國と權勢と榮光と尊貴を賜へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, '彼に權勢を賜ひしによりて諸民諸族諸音みな彼の前に慄き畏れたり彼はその欲する者を殺しその欲する者を活しその欲する者を上げその欲する者を下ししなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, '而して彼心に高ぶり氣を剛愎にして驕りしかばその國の位をすべりてその尊貴を失ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, '逐れて世の人と離れその心は獣のごとくに成りその住所は野馬の中にあり牛のごとくに草を食ひてその身は天よりの露に濡たり是のごとくにして終に彼は至高神の人間の國を治めてその意のままに人を立たまふといふことをしるにいたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'ベルシヤザルよ汝は彼の子にして此事を盡く知るといへども猶その心を卑くせず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, '却つて天の主にむかひて自ら高ぶりその家の器皿を汝の前に持きたらしめて汝と汝の大臣と汝の妻妾等それをもて酒を飮み而して汝は見ことも聞ことも知こともあらぬ金銀銅鐵木石の神を讃頌ふることを爲し汝の生命をその手に握り汝の一切の道を主どりたまふ神を崇むることをせず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, '是をもて彼の前よりこの手の末いできたりてこの文字を書るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'その書る文字は是のごとしメネ、メネ、テケル、ウバルシン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'その言の解明は是のごとしメネ(數へたり)は神汝の治世を數へてこれをその終に至らせしを謂なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'テケル(秤れり)は汝が權衡にて秤られて汝の重の足らざることの顯れたるを謂なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'ペレス(分たれたり)は汝の國の分たれてメデアとペルシヤに與へらるるを謂なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, '是においてベルシヤザル命を降してダニエルに紫の衣を着せしめ金の鏈をこれが頸にかけさせて彼は國の第三の牧伯なりと布告せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'カルデヤ人の王ベルシヤザルはその夜の中に殺され');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'メデア人ダリヨスその國を獲たり此時ダリヨスは六十二歳なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'ダリヨスはその國に百二十人の牧伯を立ることを善とし即ちこれを立て全國を治理しめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'また彼らの上に監督三人を立たりダニエルはその一人なりき是その州牧をして此三人の前にその職を述しめて王に損失の及ぶこと無らしめんためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'ダニエルは心の殊勝たる者にしてその他の監督および州牧等に勝りたれば王かれを立て全國を治めしめんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, '是においてその監督と州牧等國事につきてダエルを訟ふる隙を得んとしたりしが何の隙をも何の咎をも見いだすことを得ざりき其は彼は忠義なる者にてその身に何の咎もなく何の過失もなかりければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, '是においてその人々言けるはこのダニエルはその神の例典について之が隙を獲にあらざればついにこれを訟るに由なしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'すなはちその監督と州牧等王の許に集り來りて斯王に言りダリヨス王よ願くは長壽かれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, '國の監督將軍州牧牧伯方伯等みな相議りて王に一の律法を立て一の禁令を定めたまはんことを求めんとす王よその事は是の如し即ち今より三十日の内は唯汝にのみ願事をなさしめ若汝をおきて神または人にこれをなす者あらば凡て獅子の穴に投いれんといふ是なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, '然ば王よねがはくはその禁令を立てその詔書を認めメデアとペルシヤの廢ることなき律法のごとくに之をして變らざらしめたまへと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, '王すなはち詔書をしたためてその禁令を出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, '茲にダニエルはその詔書を認めたることを知りて家にかへりけるがその二階の窓のヱルサレムにむかひて開ける處にて一日に三度づつ膝をかがめて祷りその神に向て感謝せり是その時の前よりして斯なし居たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, '斯りしかばその人々馳よりてダニエルがその神にむかひて祷りかつ求めをるを見あらはせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, '而して彼ら進みきたり王の禁令の事につきて王に奏上して言けるは王よ汝は禁令をしたため出し今より三十日の内には只なんぢにのみ願事をなさしめ若し汝をおきて神または人にこれをなす者あらば凡てその者を獅子の穴に投いれんと定めたまへるならずやと王こたへて言ふ其事は眞實にしてメデアとペルシヤの律法のごとく廢べからざる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, '彼らまた對へて王の前に言けるは王よユダの俘擄人なるダニエルは汝をも汝の認め出し給ひし禁令をも顧みずして一日に三度づつ祈祷をなすなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, '王この事を聞てこれがために大に愁ひダニエルを救はんと心を用ひ即ちこれを拯けんと力をつくして日の入る頃におよびければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'その人々また王の許に集ひきたりて王に言けるは王よ知りたまへメデアとペルシヤの律法によれば王の立たる禁令または法度は變べからざる者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, '是において王命を下しければダニエルを曳きたりて獅子の穴に投いれたり王ダニエルに語りて言ふ願くは汝が恒に事ふる神汝を救はんことをと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, '時に石を持きたりてその穴の口を塞ぎければ王おのれの印と大臣等の印をもてこれに封印をなせり是ダニエルの處置をして變ることなからしめんためなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, '斯て後王はその宮にかへりけるがその夜は食をなさずまた嬪等を召よせずして全く寝ることをせざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, '而して王は朝まだきに起いでてその獅子の穴に急ぎいたりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, '穴にいたりける時哀しげなる聲をあげてダニエルを呼りすなはち王ダニエルに言けるは活神の僕ダニエルよ汝が恒に事ふる神汝を救ふて獅子の害を免れしむることを得しや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'ダニエル王にいひけるは願くは王長壽かれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, '吾神その使をおくりて獅子の口を閉させたまひたれば獅子は我を害せざりき其は我の辜なき事かれの前に明かなればなり王よ我は汝にも惡しき事をなさざりしなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, '是において王おほいに喜びダニエルを穴の中より出せと命じければダニルは穴の中より出されけるがその身に何の害をも受をらざりき是は彼おのれの神を賴みたるによりてなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'かくて王また命を下しかのダニエルを讒奏せし者等を曳きたらせて之をその妻子とともに獅子の穴に投いれしめたるにその穴の底につかざる内に獅子はやくも彼らを攫みてその骨までもことごとく咬碎けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, '是においてダリヨス王全世界に住る諸民諸族諸音に詔書を頒てり云く願くは大なる平安なんぢらにあれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, '今我詔命を出す我國の各州の人みなダニエルの神を畏れ敬ふべし是は活神にして永遠に立つ者またその國は亡びずその權は終極まで続くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, '是は救を施し拯をなし天においても地においても休徴をほどこし奇蹟をおこなふ者にてすなはちダニエルを救ひて獅子の力を免れしめたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'このダニエルはダリヨスの世とペルシヤ人クロスの世においてその身榮えたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'バビロンの王ベルシヤザルの元年にダニエルその牀にありて夢を見 腦中に異象を得たりしが即ちその夢を記してその事の大意を述ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'ダニエル述て曰く我夜の異象の中に見てありしに四方の天風大海にむかひて烈しく吹きたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, '四箇の大なる獣海より上りきたれりその形はおのおの異なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, '第一のは獅子の如くにして鷲の翼ありけるが我見てをりしに是はその翼を抜とられまた地より起され人のごとく足にて立せられ且人の心を賜はれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, '第二の獣は熊のごとくなりき是はその體の一方を擧げその口の歯の間に三の脇骨を啣へ居けるが之にむかひて言る者あり曰く起あがりて許多の肉を食へと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'その後に我見しに豹のごとき獣いでたりしがその背には鳥の翼四ありこの獣はまた四の頭ありて統轄權をたまはれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, '我夜の異象の中に見しにその後第四の獣いでたりしが是は畏しく猛く大に強くして大なる鐵の歯あり食ひかつ咬碎きてその殘餘をば足にて踏つけたり是はその前に出たる諸の獣とは異なりてまた十の角ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, '我その角を考へ觀つつありけるにその中にまた一箇の小き角出きたりしがこの小き角のために先の角三箇その根より抜おちたりこの小き角には人の目のごとき目ありまた大なる事を言ふ口あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, '我觀つつありしに遂に寳座を置列ぶるありて日の老たる者座を占めたりしがその衣は雪のごとくに白くその髮毛は漂潔めたる羊の毛のごとし又その寳座は火の熖にしてその車輪は燃る火なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, '而して彼の前より一道の火の流わきいづ彼に仕ふる者は千々彼の前に侍る者は萬々審判すなはち始りて書を開けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'その角の大なる事を言ふ聲によりて我觀つつありけるが我が見る間にその獣は終に殺され體を壞はれて燃る火に投いれられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'またその餘の獣はその權威を奪はれたりしがその生命は時と期の至るまで延されたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, '我また夜の異象の中に觀てありけるに人の子のごとき者雲に乗て來り日の老たる者の許に到りたればすなはちその前に導きけるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, '之に權と榮と國とを賜ひて諸民諸族諸音をしてこれに事へしむその權は永遠の權にして移りさらず又その國は亡ぶることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, '是において我ダニエルその體の内の魂を憂へしめわが腦中の異象のために思ひなやみたれば');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'すなはち其處にたてる者の一箇に就てこの一切の事の眞意を問けるに其者われにこの事の解明を告しらせて云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'この四の大なる獣は地に興らんとする四人の王なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, '然ど終には至高者の聖徒國を受け長久にその國を保ちて世々限りなからんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, '是において我またその第四の獣の眞意を知んと欲せり此獣は他の獣と異なりて至畏ろしくその歯は鐵その爪は銅にして食ひかつ咬碎きてその殘餘を足にて踏つけたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, '此獣の頭には十の角ありしが其他にまた一の角いできたりしかば之がために三の角抜おちたり此角には目ありまた大なる事を言ふ口ありてその状はその同類よりも強く見えたり我またこの事を知んと欲せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, '我觀つつありけるに此角聖徒と戰ひてこれに勝たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, '終に日の老たる者來りて至高者の聖徒のために公義をおこなへり而してその時いたりて聖徒國を獲たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, '彼かく言り第四の獣は地上の第四の國なり是は一切の國と異なり全世界を并呑しこれを踏つけかつ打破らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'その十の角はこの國に興らんところの十人の王なり之が後にまた一人興るべし是は先の者と異なり且その王三人を倒すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'かれ至高者に敵して言を出しかつ至高者の聖徒を惱まさん彼また時と法とを變んことを望まん聖徒は一時と二時と半時を經るまで彼の手に付されてあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, '斯て後審判はじまり彼はその權を奪はれて終極まで滅び亡ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, '而して國と權と天下の國々の勢力とはみな至高者の聖徒たる民に歸せん至高者の國は永遠の國なり諸國の者みな彼に事へかつ順はんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'その事此にて終れり我ダニエルこれを思ひまはして大に憂へ顔色も變りぬ我この事を心に蔵む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, '我ダニエル前に異象を得たりしが後またベルシヤザルの第三年にいたりて異象を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, '我異象を見たり我これを見たる時に吾身はエラム州なるシユシヤンの城にあり我が異象を見たるはウライ河の邊においてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, '我目を擧て觀しに河の上に一匹の牡羊立をり之に二の角ありてその角共に長かりしが一の角はその他の角よりも長かりきその長き者は後に長たるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, '我觀しにその牡羊西北南にむかひて牴觸りけるが之に敵ることを得る獣一匹も無くまたその手より救ひいだすことを得る者絶てあらざりき是はその意にまかせて事をなしその勢威はなはだ盛なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, '我これを考へ見つつありけるにて一匹の牡山羊全地の上を飛わたりて西より來りしがその足は土を履ざりきこの牡山羊は目の間に著明しき一の角ありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, '此者さきに我が河の上に立るを見たる彼の二の角ある牡羊に向ひ來り熾盛なる力をもて之の所に跑いたりけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, '我觀てあるに牡羊に近づくに至りて之にむかひて怒を發し牡羊を撃てその二の角を碎きたるに牡羊には之に敵る力なかりければこれを地に打倒して踏つけたり然るにその牡羊をこれが手より救ひ得る者あらざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, '而してその牡山羊甚だ大きくなりけるがその盛なる時にあたりてかの大なる角折れその代に四の著明しき角生じて天の四方に對へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'またその角の一よりして一の小き角いできたり南にむかひ東にむかひ美地にむかひて甚だ大きくなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, '天軍におよぶまでに高くなりその軍と星數箇を地に投くだしてこれを踏つけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'また自ら高ぶりてその軍の主に敵しその常供の物を取のぞきかつその聖所を毀てり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, '一軍罪の故によりて常供の物とともに棄られたり彼者はまた眞理を地に擲ち事をなしてその意志を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'かくて我聞に一箇の聖者語ひをりしが又一箇の聖者ありてその語ひをる聖者にむかひて言ふ常供の物と荒廢を來らする罪とにつきて異象にあらはれたるところの事聖所とその軍との棄られて踏つけらるる事は何時まで斯てあるべきかと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, '彼すなはち我に言けるは二千三百の朝夕をかさぬるまで斯てあらん而して聖所は潔めらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, '我ダニエルこの異象を見てその意義を知んと求めをりける時人のごとく見ゆる者わが前に立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, '時に我聞にウライ河の兩岸の間より人の聲出て呼はりて言ふガブリエルよこの異象をその人に暁らしめよと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, '彼すなはち我の立る所にきたりしがその到れる時に我おそれて仆れ伏たるに彼われに言けるは人の子よ暁れ此異象は終の時にかかはる者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, '彼の我に語ひける時我は氣を喪へる状にて地に俯伏をりしが彼我に手をつけて我を立せ言けるは');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, '視よ我忿怒の終に起らんところの事を汝に知せん此事は終末の期におよびてあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, '汝が見たるかの二の角ある牡羊はメデアとペルシヤの王なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'またかの牡山羊はギリシヤの王その目の間の大なる角はその第一の王なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'またその角をれてその代に四の角生じたればその民よりして四の國おこらん然ど第一の者の權勢には及ばざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, '彼らの國の末にいたり罪人の罪貫盈におよびて一人の王おこらんその顔は猛惡にして巧に詭譎を言ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'その權勢は熾盛ならん但し自己の能力をもて之を致すに非ずその毀滅ことを爲は常ならず意志を得て事を爲し權能ある者等と聖民とを滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, '彼は機巧をもて詭譎をその手に行ひ遂げ心にみづから高ぶり平和の時に衆多の人を打滅しまた君の君たる者に敵せん然ど終には人手によらずして滅されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, '前に告たる朝夕の異象は眞實なり汝その異象の事を秘しおけ是は衆多の日の後に有べき事なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, '是において我ダニエル疲れはてて數日の間病わづらひて後興いでて王の事務をおこなへり我はこの異象の事を案ひて駭けり人もまたこれを暁ることを得ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'メデア人アハシユエロスの子ダリヨスがカルデヤ人の王とせられしその元年');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'すなはちその世の元年に我ダニエル、ヱホバの言の預言者ヱレミヤにのぞみて告たるその年の數を書によりて暁れり即ちその言にヱルサレムは荒て七十年を經んとあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, '是にかいて我面を主ヱホバに向け斷食をなし麻の衣を着灰を蒙り祈りかつ願ひて求むることをせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, '即ち我わが神ヱホバに祷り懺悔して言り嗚呼大にして畏るべき神なる主自己を愛し自己の誡命を守る者のために契約を保ち之に恩惠を施したまふ者よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, '我等は罪を犯し悖れる事を爲し惡を行ひ叛逆を爲して汝の誡命と律法を離れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, '我等はまた汝の僕なる預言者等が汝の名をもて我らの王等君等先祖等および全國の民に告たる所に聽したがはざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, '主よ公義は汝に歸し羞辱は我らに歸せりその状今日のごとし即ちユダの人々ヱルサレムの居民およびイスラエルの全家の者は近き者も遠き者も皆汝の逐やりたまひし諸の國々にて羞辱を蒙れり是は彼らが汝に背きて獲たる罪によりて然るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, '主よ羞辱は我儕に歸し我らの王等君等および先祖等に歸す是は我儕なんぢに向ひて罪を犯したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, '憐憫と赦宥は主たる我らの神の裏にあり其は我らこれに叛きたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, '我らはまた我らの神ヱホバの言に遵はずヱホバがその僕なる預言者等によりて我らの前に設けたまひし律法を行はざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, '抑イスラエルの人は皆汝の律法を犯し離れさりて汝の言に遵はざりき是をもて神の僕モーセの律法に記したる呪詛と誓詞我らの上に斟ぎかかれり是は我らこれに罪を獲たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, '即ち神は大なる災害を我らに蒙らせたまひてその前に我らと我らを鞫ける士師とにむかひて宣ひし言を行ひとげたまへりかのエルサレムに臨みたる事の如きは普天の下に未だ曾て有ざりしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'モーセの律法に記したる如くにこの災害すべて我らに臨みしかども我らはその神ヱホバの面を和めんとも爲ずその惡を離れて汝の眞理を暁らんとも爲ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, '是をもてヱホバ心にかけて災害を我らに降したまへり我らの神ヱホバは何事をなしたまふも凡て公義いますなり然るに我らはその言に遵はざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, '主たる我らの神よ汝は強き手をもて汝の民をエジプトの地より導き出して今日のごとく汝の名を揚たまふ我らは罪を犯し惡き事を行へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, '主よ願くは汝が是まで公義き御行爲を爲たまひし如く汝の邑ヱルサレム汝の聖山より汝の忿怒と憤恨を取離し給へ其は我らの罪と我らの先祖の惡のためにヱルサレムと汝の民は我らの周圍の者の笑柄となりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, '然ば我らの神よ僕の祷と願を聽たまへ汝は主にいませばかの荒をる汝の聖所に汝の面を耀かせたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, '我神よ耳を傾けて聽たまへ目を啓きて我らの荒蕪たる状を觀汝の名をもて稱へらるる邑を觀たまへ我らが汝の前に祈祷をたてまつるは自己の公義によるに非ず唯なんぢの大なる憐憫によるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, '主よ聽いれたまへ主よ赦したまへ主よ聽いれて行ひたまへこの事を遅くしたまふなかれわが神よ汝みづからのために之をなしたまへ其は汝の邑と汝の民は汝の名をもて稱へらるればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, '我かく言て祈りかつわが罪とわが民イスラエルの罪を懺悔し我神の聖山の事につきてわが神ヱホバのまへに願をたてまつりをる時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, '即ち我祈祷の言をのべをる時我が初に異象の中に見たるかの人ガブリエル迅速に飛て晩の祭物を献ぐる頃我許に達し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, '我に告げ我に語りて言けるはダニエルよ今我なんぢを敎へて了解を得せしめんとて出きたれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, '汝が祈祷を始むるに方りて我言を受たれば之を汝に示さんとて來れり汝は大に愛せらるる者なり此言を了りその現れたる事の義を暁れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, '汝の民と汝の聖邑のために七十週を定めおかる而して惡を抑へ罪を封じ愆を贖ひ永遠の義を携へ入り異象と預言を封じ至聖者に膏を灌がん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, '汝暁り知べしヱルサレムを建なほせといふ命令の出づるよりメッシヤたる君の起るまでに七週と六十二週ありその街と石垣とは擾亂の間に建なほされん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'その六十二週の後にメッシャ絶れん但し是は自己のために非ざるなりまた一人の君の民きたりて邑と聖所とを毀たんその終は洪水に由れる如くなるべし戰爭の終るまでに荒蕪すでに極る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, '彼一週の間衆多の者と固く契約を結ばん而して彼その週の半に犠牲と供物を廢せんまた殘暴可惡者羽翼の上に立たん斯てつひにその定まれる災害殘暴るる者の上に斟ぎくだらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'ペルシヤの王クロスの三年にベルテシヤザルといふダニエル一の事の默旨を得たるがその事は眞實にしてその戰爭は大なり彼その事を暁りその示現の義を暁れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, '當時我ダニエル三七日の間哀めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, '即ち三七日の全く滿るまでは旨き物を食ず肉と酒とを口にいれずまた身に膏油を抹ざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, '正月の二十四日に我ヒデケルといふ大河の邊に在り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, '目を擧て望觀しに一箇の人ありて布の衣を衣ウバズの金の帶を腰にしめをり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'その體は黄金色の玉のごとくその面は電光の如くその目は火の熖のごとくその手とその足の色は磨ける銅のごとくその言ふ聲は群衆の聲の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'この示現は唯我ダニエル一人これを觀たり我と偕なる人々はこの示現を見ざりしが何となくその身大に慄きて逃かくれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, '故に我ひとり遺りたるがこの大なる示現を觀るにおよびて力ぬけさり顔色まつたく變りて毫も力なかりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, '我その語ふ聲を聞けるがその語ふ聲を聞る時我は氣を喪へる状にて俯伏し面を土につけゐたりしに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, '一の手ありて我に捫りければ我戰ひながら跪づきて手をつきたるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, '彼われに言けるは愛せらるる人ダニエルよ我が汝に告る言を暁れよ汝まづ起あがれ我は今汝の許に遣されたるなりと彼がこの言を我に告る時に我は戰ひて立り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, '彼すなはち我に言けるはダニエルよ懼るる勿れ汝が心をこめて悟らんとし汝の神の前に身をなやませるその初の日よりして汝の言はすでに聽れたれば我汝の言によりて來れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, '然るにペルシヤの國の君二十一日の間わが前に立塞がりけるが長たる君の一なるミカエル來りて我を助けたれば我勝留りてペルシヤの王等の傍にをる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, '我は末の日に汝の民に臨まんとするところの事を汝に暁らせんとて來れりまた後の日に關はる所の異象ありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'かれ是等の言を我に宣たる時に我は面を土につけて居り辭を措ところ無りしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, '人の子のごとき者わが唇に捫りければ我すなはち口を開きわが前に立る者に陳て言り我主よこの示現によりて我は畏怖にたへず全く力を失へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, '此わが主の僕いかでか此わが主と語ふことを得んとその時は我まつたく力を失ひて氣息も止らんばかりなりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, '人の形のごとき者ふたたび我に捫り我に力をつけて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, '言けるは愛せらるる人よ懼るる勿れ安んぜよ心強かれ心強かれと斯われに言ければ我力づきて曰り我主よ語りたまへ汝われに力をつけたまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, '彼われに言けるは汝は我が何のために汝に臨めるかを知るや我今また歸りゆきてペルシヤの君と戰はんとす我が出行ん後にギリシヤの君きたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, '但し我まづ眞實の書に記されたる所を汝に示すべし我を助けて彼らに敵る者は汝らの君ミカエルのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, '我はまたメデア人ダリヨスの元年にかれを助け彼に力をそへたる事ありしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, '我いま眞實を汝に示さん視よ此後ペルシヤに三人の王興らんその第四の者は富ること一切の者に勝りその富強の大なるを恃みて一切を激發してギリシヤの國を攻ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'また一箇の強き王おこり大なる威權を振ふて世を治めその意のままに事を爲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, '但し彼の正に旺盛なる時にその國は破裂して天の四方に分れん其は彼の兒孫に歸せず又かれの振ひしほどの威權あらず即ち彼の國は抜とられて是等の外なる者等に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, '南の王は強からん然どその大臣の一人これに逾て強くなり威權を振はんその威權は大なる威權なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, '年を經て後彼等相結ばん即ち南の王の女子北の王に適て和好を圖らん然どその腕には力なしまたその王およびその腕は立ことを得じこの女とこれを導ける者とこれを生せたる者とこれに力をつけたる者はみな時におよびて付されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, '斯て後この女の根より出たる芽興りて之に代り北の王の軍勢にむかひて來りこれが城に打いりて之を攻て勝を得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, '之が神々鑄像および金銀の貴き器具をエジプトに携へさらん彼は北の王の上に立て年を重ねん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, '彼南の王の國に打入ことあらん然ど自己の國に退くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'その子等また憤激して許多の大軍を聚め進みきたり溢れて往來しその城まで攻寄せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, '是において南の王大に怒り出きたりて北の王と戰ふべし彼大軍を興してこれに當らん然れどもその軍兵はこれが手に付されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, '大軍すなはち興りて彼心に高ぶり數萬人を仆さん然れどもその勢力はこれがために増さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'また北の王は退きて初よりも大なる軍兵を興し或時すなはち或年數を經て後かならず大兵を率ゐ莫大の輜重を備へて攻來らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, '是時にあたりて衆多の者興りて南の王に敵せん又なんぢの民の中の奸惡人等みづから高ぶりて事を爲しつひに預言をして應ぜしめん即ち彼らは自ら仆るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, '茲に北の王襲ひきたり壘を築きて堅城を攻おとさん南の王の腕はこれに當ることを得じ又その撰抜の民もこれに當る力なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, '之に攻きたる者はその意に任せて事をなさんその前に立ことを得る者なかるべし彼は美しき地に到らんその地はこれがために荒さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, '彼その全國の力を盡して打入んとその面をこれに向べけれどまたこれと和好をなして婦人の女子を之に與へん然るにその婦人の女子は之がために身を滅すに至り何事をも成あたはす毫も彼のために益する所なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, '彼またその面を島々にむけて之を多く取らん茲に一人の大將ありて彼が與へたる恥辱を雪ぎその恥辱をかれの身に與へかへさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'かくて彼その面を自己の國の城々に向ん而して終に躓き仆れて亡ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, '彼に代りて興る者は榮光の國に人を出して租税を征斂しめん但し彼は忿怒にも戰門にもよらずして數日の内に滅亡せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'また之にかはりて起る者は賤まるる者にして國の尊榮これに歸せざらん然れども彼不意に來り巧言をもて國を獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, '洪水のごとき軍勢かれのために押流されて敗れん契約の君たる者も然らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, '彼は之に契約をむすびて後詭計を行ひ上りきたりて僅少の民をもて勢を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, '彼すなはち不意にきたりてその國の膏腴なる處に攻いりその父もその父の父も爲ざりしところの事を行はん彼はその奪ひたる物掠めたる物および財寳を衆人の中に散すべし彼は謀略をめぐらして堅固なる城々を攻取べし時の至るまで斯のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, '彼はその勢力を奮ひ心を勵まし大軍を率ゐて南の王に攻よせん南の王もまた自ら奮ひ甚だ大なる強き軍勢をもて迎へ戰はん然ど謀略をめぐらして攻るが故にこれに當ることを得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'すなはち彼の珍膳に與り食ふ者彼を倒さんその軍兵溢れん打死する者衆かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, '此二人の王は害をなさんと心にはかり同席に共に食して詭計を言ん然どもその志ならざるべし定まれる時のいたる迄は其事終らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, '彼は莫大の財寳をもちて自己の國に歸らん彼は聖約に敵する心を懐きて事をなし而してその國にかへらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, '定まれる時にいたりて彼また進みて南に到らん然ど後の模樣は先の模樣のごとくならざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, '即ちキツテムの船かれに到るべければ彼力をおとして還り聖約にむかひて忿怒をもらして事をなさん而して彼歸りゆき聖約を棄る者と相謀らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, '彼より腕おこりて聖所すなはち堅城を汚し常供の物を撤除かせかつ殘暴可惡者を立ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, '彼はまた契約に關て罪を獲る者等を巧言をもて引誘して背かせん然どその神を知る人々は力ありて事をなさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, '民の中の頴悟者ども衆多の人を敎ふるあらん然ながら彼らは暫時の間刃にかかり火にやかれ擄はれ掠められ等して仆れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'その仆るる時にあたりて彼らは少しく扶助を獲ん又衆多の人詐りて彼らに合せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'また穎悟者等の中にも仆るる者あらん斯のごとく彼らの中に試むる事淨むる事潔よくする事おこなはれて終の時にいたらん即ち定まれる時まで然るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, '此王その意のままに事をおこなひ萬の神に逾て自己を高くし自己を大にし神々の神たる者にむかひて大言を吐き等して忿怒の息む時までその志を得ん其はその定まれるところの事成ざるべからざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, '彼はその先祖の神々を顧みず婦女の愉快を思はずまた何の神をも顧みざらん其は彼一切に逾て自己を大にすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, '彼は之の代に軍神を崇め金銀珠玉および寳物をもてその先祖等の識ざりし神を崇めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, '彼はこの異邦の神に由り要害の城々にむかひて事を爲ん凡て彼を尊ぶ者には彼加ふるに榮を以てし之をして衆多の人を治めしめ土地をこれに分ち與へて賞賜とせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, '終の時にいたりて南の王彼と戰はん北の王は車と馬と衆多の船をもて大風のごとく之に攻寄せ國に打いりて潮のごとく溢れ渉らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, '彼はまた美しき國に進み入ん彼のために亡ぶる者多かるべし然どエドム、モアブ、アンモン人の中の第一なる者などは彼の手を免かれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, '彼國々にその手を伸さんエジプトの地も免かれがたし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, '彼は遂にエジプトの金銀財寳を手に入れんリブア人とエテオピア人は彼の後に從はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, '彼東と北より報知を得て周章ふためき許多の人を滅し絶んと大に忿りて出ゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, '彼は海の間において美しき聖山に天幕の宮殿をしつらはん然ど彼つひにその終にいたらん之を助くる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'その時汝の民の人々のために立ところの大なる君ミカエル起あがらん是艱難の時なり國ありてより以來その時にいたるまで斯る艱難ありし事なかるべしその時汝の民は救はれん即ち書にしるされたる者はみな救はれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'また地の下に睡りをる者の中衆多の者目を醒さんその中永生を得る者ありまた恥辱を蒙りて限なく羞る者あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, '穎悟者は空の光輝のごとくに耀かんまた衆多の人を義に導ける者は星のごとくなりて永遠にいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'ダニエルよ終末の時まで此言を秘し此書を封じおけ衆多の者跋渉らん而して知識増べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, '茲に我ダニエル觀に別にまた二箇の者ありて一箇は河の此旁の岸にあり一箇は河の彼旁の岸にありけるが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'その一箇の者かの布の衣を衣て河の水の上に立る人にむかひて言り此奇跡は何の時にいたりて終るべきやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, '我聞にかの布の衣を衣て河の水の上に立る人天にむかひてその右の手と左の手を擧げ永久に生る者を指て誓ひて言りその間は一時と二時と半時なり聖民の手の碎くること終らん時に是等の事みな終るべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, '我聞たれども暁ることを得ざりき我また言りわが主よ是等の事の終は何ぞやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, '彼いひけるはダニエルよ往け此言は終極の時まで秘しかつ封じ置るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, '衆多の者淨められ潔よくせられ試みられん然ど惡き者は惡き事を行はん惡き者は一人も暁ること無るべし然ど頴悟者は暁るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, '常供の者を除き殘暴可惡者を立ん時よりして一千二百九十日あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, '待をりて一千三百三十五日に至る者は幸福なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, '汝終りに進み行け汝は安息に入り日の終りに至り起て汝の分を享ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'これユダの王ウジヤ、ヨタム、アハズ、ヒゼキヤの世イスラエルの王ヨアシの子ヤラベアムの世にベエリの子ホセアに臨めるヱホバの言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'ヱホバはじめホセアによりて語りたまへる時ヱホバ、ホセアに宣はく汝ゆきて淫行の婦人を娶り淫行の子等を取れ この國ヱホバに遠ざかりてはなはだしき淫行をなせばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, '是において彼ゆきてデブライムの女子ゴメルを妻に娶りけるがその婦はらみて男子を產り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'ヱホバまた彼にいひ給ひけるは汝その名をヱズレルと名くべし 暫時ありて我ヱズレルの血をヱヒウの家に報いイスラエルの家の國をほろぼすべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'その日われヱズレルの谷にてイスラエルの弓を折べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'ゴメルまた孕みて女子を產ければヱホバ、ホセアに言たまひけるは汝その名をロルマハ(憐まれぬ者)と名くべしそは我もはやイスラエルの家をあはれみて赦すが如きことを爲ざるべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, '然どわれユダの家をあはれまん その神ヱホバによりて之をすくはん 我は弓劍戰爭馬騎兵などによりてすくふことをせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'ロルハマ乳をやめゴメルまた孕みて男子を產けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'ヱホバ言たまひけるはその子の名をロアンミ(吾民に非ざる者)と名くべし 其は汝らは吾民にあらず我は汝らの神に非ざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, '然どイスラエルの子孫の數は濱の沙石のごとくに成ゆきて量ることも數ふる事も爲しがたく前になんぢらわが民にあらずと言れしその處にて汝らは活神の子なりと言れんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, '斯てユダの子孫とイスラエルの子孫は共に集り一人の首をたててその地より上り來らん ヱズレルの日は大なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, '汝らの兄弟に向ひてはアンミ(わが民)と言ひ汝らの姉妹にむかひてはルハマ(憐まるる者)と言へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'なんぢらの母とあげつらへ論辨ふことをせよ彼はわが妻にあらず我はかれの夫にあらざるなりなんぢら斯してかれにその面より淫行を除かせその乳房の間より姦淫をのぞかしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, '然らざれば我かれを剥て赤體にしその生れいでたる日のごとくにしまた荒野のごとくならしめ潤ひなき地のごとくならしめ渇によりて死しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, '我その子等を憐まじ淫行の子等なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'かれらの母は淫行をなせりかれらを生る者は恥べき事をおこなへり蓋かれいへる言あり我はわが戀人等につきしたがはん彼らはわがパンわが水わが羊毛わが麻わが油わが飮物などを我に與ふるなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'この故にわれ荊棘をもてなんぢの路をふさぎ垣をたてて彼にその徑をえざらしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, '彼はその戀人たちの後をしたひゆけども追及ことなく之をたづぬれども遇ことなし是において彼いはん我ゆきてわが前の夫にかへるべしかのときのわが状態は今にまさりて善りきと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, '彼が得る穀物と酒と油はわが與ふるところ彼がバアルのために用ゐたる金銀はわが彼に増あたへたるところなるを彼はしらざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'これによりて我わが穀物をその時におよびて奪ひわが酒をその季にいたりてうばひ又かれの裸體をおほふに用ゆべきわが羊毛およびわが麻をとらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, '今われかれの恥るところをその戀人等の目のまへに露すべし彼をわが手より救ふものあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, '我かれがすべての喜樂すなはち祝筵新月のいはひ安息日および一切の節會をして息しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'また彼の葡萄の樹と無花果樹をそこなはん彼さきに此等をさしてわが戀人の我にあたへし賞賜なりと言しがわれこれを林となし野の獣をしてくらはしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'われかれが耳環頸玉などを掛てその戀人らをしたひゆき我をわすれ香をたきて事へしもろもろのバアルの日のゆゑをもてその罪を罰せんヱホバかく言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, '斯るがゆゑに我かれを誘ひて荒野にみちびきいり終にかれの心をなぐさめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'かしこを出るや直ちにわれかれにその葡萄園を與へアコル(艱難)の谷を望の門となしてあたへん彼はわかかりし時のごとくエジプトの國より上りきたりし時のごとくかしこにて歌うたはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'ヱホバ言たまふその日にはなんぢ我をふたたびバアリとよばずしてイシ(吾夫)とよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, '我もろもろのバアルの名をかれが口よりとりのぞき重ねてその名を世に記憶せらるること無らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'その日には我かれら(我民)のために野の獣そらの鳥および地の昆蟲と誓約をむすびまた弓箭ををり戰爭を全世界よりのぞき彼らをして安らかに居しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'われ汝をめとりて永遠にいたらん公義と公平と寵愛と憐憫とをもてなんぢを娶り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'かはることなき眞實をもて汝をめとるべし汝ヱホバをしらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'ヱホバいひ給ふその日われ應へん我は天にこたへ天は地にこたへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, '地は穀物と酒と油とに應へまた是等のものはヱズレルに應へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, '我わがためにかれを地にまき憐まれざりし者をあはれみわが民ならざりし者にむかひて汝はわが民なりといはんかれらは我にむかひて汝はわが神なりといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'ヱホバわれに言給ひけるは汝ふたたび往てヱホバに愛せらるれども轉りてほかのもろもろの神にむかひ葡萄の菓子を愛するイスラエルの子孫のごとく そのつれそふものに愛せらるれども姦淫をおこなふ婦人をあいせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'われ銀十五枚おほむぎ一ホメル半をもてわが爲にその婦人をえたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, '我これにいひけるは汝おほくの日わがためにとどまりて淫行をなすことなく他の人にゆくことなかれ 我もまた汝にむかひて然せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'イスラエルの子輩は多くの日王なく君なく犠牲なく表柱なくエボデなくテラビムなくして居らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'その後イスラエルの子輩はかへりてその神ヱホバとその王ダビデをたづねもとめ末日にをののきてヱホバとその恩惠とにむかひてゆかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'イスラエルの子輩よヱホバの言を聽けヱホバこの地に住る者と爭辨たまふ其は此地には誠實なく愛情なく神を知る事なければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'ただ詛偽凶殺盗姦淫のみにして互に相襲ひ血血につづき流る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'このゆゑにその地うれひにしづみ之にすむものはみな野のけもの空のとりとともにおとろへ海の魚もまた絶はてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'されど何人もあらそふべからずいましむ可らず汝の民は祭司と爭ふ者の如くなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, '汝は晝つまづき汝と偕なる預言者は夜つまづかん我なんぢの母を亡すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'わが民は知識なきによりて亡さるなんぢ知識を棄つるによりて我もまた汝を棄ててわが祭司たらしめじ汝おのが神の律法を忘るるによりて我もなんぢの子等を忘れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, '彼らは大なるにしたがひてますます我に罪を犯せば我かれらの榮を辱に變ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, '彼らはわが民の罪をくらひ心をかたむけてその罪ををかすを願へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'このゆゑに民の遇ふところは祭司もまた同じわれその途をかれらにきたらせその行爲をもて之にむくゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'かれらは食へども飽ず淫行をなせどもその數まさずその心をヱホバにとむることを止ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, '淫行と酒と新しき酒はその人の心をうばふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'わが民木にむかひて事をとふその杖かれらに事をしめす是かれら淫行の霊にまよはされその神の下を離れて淫行を爲すなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, '彼らは山々の巓にて犠牲を献げ岡の上にて香を焚き橡樹 楊樹 栗樹の下にてこの事をおこなふ此はその樹蔭の美しきによりてなりここをもてなんぢらの女子は淫行をなしなんぢらの兒婦は姦淫をおこなふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, '我なんぢらのむすめ淫行をなせども罰せずなんぢらの兒婦かんいんをおこなへども刑せじ其はなんぢらもみづから離れゆきて妓女とともに居り淫婦とともに献物をそなふればなり悟らざる民はほろぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'イスラエルよ汝淫行をなすともユダに罪を犯さする勿れギルガルに往なかれベテアベンに上るなかれヱホバは活くと曰て誓ふなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'イスラエルは頑強なる牛のごとくに頑強なり今ヱホバ恙羊をひろき野にはなてるが如くして之を牧はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'エフライムは偶像にむすびつらなれりその爲にまかせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'かれらの酒はくされかれらの淫行はやまずかれらの楯となるべき者等は恥を愛しいたく之を愛せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'かれは風の翼につつまれかれらはその禮物によりて恥辱をかうむらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, '祭司等よこれを聽けイスラエルの家よ耳をかたむけよ 王のいへよ之にこころを注よ さばきは汝等にのぞまん そは我らはミズパに設くる羂タボルに張れる網のごとくなればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, '悖逆者はふかく罪にしづみたり我かれらをことごとく懲しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, '我はエフライムを知る イスラエルはわれに隱るるところ無し エフライムよなんぢ今すでに淫行をなせりイスラエルはすでに汚れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'かれらの行爲かれらをしてその神に歸ること能はざらしむ そは淫行の霊その衷にありてヱホバを知ることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'イスラエルの驕傲はその面にむかひて證をなしその罪によりてイスラエルとエフライムは仆れユダもまた之とともにたふれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'かれらは羊のむれ牛の群をたづさへ往てヱホバを尋ね求めん然どあふことあらじヱホバ旣にかれらより離れ給ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'かれらヱホバにむかひ貞操を守らずして他人の子を產り新月かれらとその產業とをともに滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'なんぢらギベアにて角をふきラマにてラッパを吹ならしベテアベンにて呼はりて言へベニヤミンよなんぢの後にありと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, '罰せらるるの日にエフライムは荒廢れん我イスラエルの支派の中にかならず有るべきことを示せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'ユダの牧伯等は境界をうつすもののごとくなれり我わが震怒を水のごとくに彼らのうへに斟がん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'エフライムは甘んじて人のさだめたるところに從ひあゆむがゆゑに鞫をうけて虐げられ圧られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'われエフライムには蠧のごとくユダの家には腐朽のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'エフライムおのれに病あるを見ユダおのれに傷あるをみたり斯てエフライムはアツスリヤに往きヤレブ王に人をつかはしたれど彼はなんぢらを醫すことをえず又なんぢらの傷をのぞきさることを得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'われエフライムには獅子のごとくユダの家にはわかき獅子のごとし我しも我は抓劈てさり掠めゆけども救ふ者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, '我ふたたびわが處にかへりゆき彼らがその罪をくいてひたすらわが面をたづね求むるまで其處にをらん彼らは艱難によりて我をたづねもとむることをせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '來れわれらヱホバにかへるべし ヱホバわれらを抓劈たまひたれどもまた醫すことをなし我儕をうち給ひたれどもまたその傷をつつむことを爲したまふ可ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'ヱホバは二日ののちわれらむ活かへし三日にわれらを起せたまはん 我らその前にて生ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'この故にわれらヱホバをしるべし切にヱホバを知ることを求むべしヱホバは晨光のごとく必ずあらはれいで雨のごとくわれらにのぞみ後の雨のごとく地をうるほし給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'エフライムよ我なんぢに何をなさんやユダよ我なんぢに何をなさんやなんぢの愛情はあしたの雲のごとくまたただちにきゆる露のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'このゆゑにわれ預言者等をもてかれらを撃ちわが口の言をもてかれらえを殺せりわが審判はあらはれいづる光明のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'われは愛情をよろこびて犠牲をよろこばず神をしるを悦ぶこと燔祭にまされり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, '然るに彼らはアダムのごとく誓をやぶりかしこにて不義をわれにおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'ギレアデは惡をおこなふものの邑にして血の足跡そのなかに徧し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, '祭司のともがらは山賊の群のごとく伏伺して人をそこなひシケムに往く大路にて人をころす彼等はかくのごとき惡きことをおこなへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'われイスラエルのいへに憎むべきことあるを見たりかの處にてエフライムは淫をおこなふイスフルは汚れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'ユダよ我わが民の俘囚をかへさんときまた汝のためにも穫刈をそなへん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'われイスラエルを醫さんときエフライムの愆とサマリヤのあしきわざと露るかれらは詐詭をおこなひ内には偸盗いるあり外には山賊のむれ掠めさるあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'かれら心にわがその一切の惡をしたためたることを思はず今その行爲はかれらを圍みふさぎて皆わが目前にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'かれらはその惡をもて王を悦ばせその詐詭をもてもろもろの牧伯を悦ばせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'かれらはみな姦淫をおこなふ者にしてパンを作るものに燒るる爐のごとし揑粉をこねてその發酵ときまでしばらく火をおこすことをせざるのみなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'われらの王の日にもろもろの牧伯は酒の熱によりて疾し王は嘲るものとともに手を伸ぶ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'かれら伏伺するほどに心を爐のごとくして備をなすそのパンを燒くものは終夜ねむりにつき朝におよべばまた焔のごとく燃ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'かれらはみな爐のごとくに熱してその審士をやくそのもろもろの王はみな仆るかれらの中には我をよぶもの一人だになし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'エフライムは異邦人にいりまじるエフライムはかへさざる餹餅となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'かれは他邦人らにその力をのまるれども之をしらず白髮その身に雑り生れどもこれをさとらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'イスラエルの驕傲はその面にむかひて證をなすかれらは此もろもろの事あれどもその神ヱホバに歸ることをせず又もとむることをせざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'エフライムは智慧なくして愚なる鴿のごとし彼等はエジプトにむかひて呼求めまたアツスリヤに往く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, '我かれらの往ときわが網をその上にはりて天空の鳥のごとくに引堕し前にその公會に告しごとくかれらを懲しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, '禍なるかなかれらは我をはなれて迷ひいでたり敗壞かれらにきたらんかれらは我にむかひて罪ををかしたり我かれらを贖はんとおもへどもかれら我にさからひて謊言をいへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'かれら誠心をもて我をよばず唯牀にありて哀號べりかれらは穀物とあたらしき酒のゆゑをもて相集りかつわれに逆らふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, '我かれらを敎へその腕をつよくせしかども彼らはわれにもとりて惡きことを謀る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'かれらは歸るされども至高者にかへらず彼らはたのみがたき弓のごとし彼らのもろもろの牧伯はその舌のあらき言によりて劍にたふれん彼らは之がためにエジプトの國にて嘲笑をうくべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'ラッパをなんぢの口にあてよ敵は鷲のごとくヱホバの家にのぞめりこの民わが契約をやぶりわが律法を犯ししによる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'かれら我にむかひてわが神よわれらイスラエルはなんぢを知れりと叫ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'イスラエルは善をいみきらへり敵これを追ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'かれら王をたてたり然れども我により立しにあらずかれら牧伯をたてたり然れども我がしらざるところなり彼らまたその金銀をもて己がために偶像をつくれりその造れるは毀ちすてられんが爲にせしにことならず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'サマリヤよなんぢの犢は忌きらふべきものなりわが怒かれらにむかひて燃ゆかれら何れの時にか罪なきにいたらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'この犢はイスラエルより出づ匠人のつくれる者にして神にあらずサマリヤの犢はくだけて粉とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'かれらは風をまきて狂風をかりとらん種ところは生長る穀物なくその穂はみのらざるべしたとひ實るとも他邦人これを呑ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'イスラエルは旣に呑れたり彼等いま列國の中において悦ばれざる器のごとく視做るるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, '彼らは獨ゐし野の驢馬のごとくアッスリヤにゆけりエフライムは物を餽りて戀人を得たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'かれら列國の民に物を餽りたりと雖も今われ彼等をつどへ集む彼らは諸侯伯の王に負せらるる重擔のために衰へ始めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'エフライムは多くの祭壇を造りて罪を犯すこの祭壇はかれらが罪に陷る階とはなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, '我かれらのために律法をしるして數件の箇條を示したれど彼らは反て之を異物とおもへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'かれらは我に献ふべき物を献ふれども只肉をそなへて己みづから之を食ふヱホバは之を納たまはず今かれらの愆を記え彼らの罪を罰したまはん彼らはエジプトに歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'イスラエルは己が造主を忘れてもろもろの社廟を建てユダは塀をとりまはせる邑を多く増し加へたり然どわれ火をその邑々におくりて諸の城を燒亡さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'イスラエルよ異邦人のごとく喜びすさむ勿れなんぢ淫行をなして汝の神を離る汝すべての麥の打塲にて賜はる淫行の賞賜を愛せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, '打場と酒榨とはかれらを養はじ亦あたらしき酒もむなしくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'かれらはヱホバの地にとどまらずエフライムはエジプトに歸りアッスリヤにて汚穢たる物を食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, '彼等はヱホバにむかひて酒を灌ぐべき者にあらずその祭物はヱホバの悦びたまふ所にあらずかれらの犠牲は喪に居もののパンのごとし凡てこれを食ふものは汚るべし彼等のパンは只おのが食ふためにのみ用ゐべくしてヱホバの家に入るべきにあらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'なんぢら集會の日とヱホバの節會の日に何をなさんとするや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, '視よかれら滅亡の故によりて去ゆきぬエジプトかれらをあつめメンピスかれらを葬らん蒺藜かれらが銀の寳物を獲いばら彼らの天幕に蔓らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, '刑罰の日きたり應報の日きたれりイスラエルこれを知ん預言者は愚なるもの霊に感じたるものは狂へるものなりこれ汝の惡おほく汝の怨恨おほいなるに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'エフライムは我が神にならべて他の神をも佇望めり預言者の一切の途は鳥を捕ふる者の網のごとく且その神の室の中にて怨恨を懐けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'かれらはギベアの日のごとく甚だしく惡き事を行へりヱホバはその惡をこころに記てその罪を罰したまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, '在昔われイスラエルを見ること荒野の葡萄のごとく汝らの先祖等を看ること無花果樹の始にむすべる最先の果の如くなししに彼等はバアルペオルにゆきて身を恥辱にゆだねその愛する物とともに憎むべき者とはなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'エフライムの榮光は鳥のごとく飛さらん即ち產ことも孕むことも妊娠こともなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, '假令かれら子等を育つるとも我その子を喪ひて遺る人なきにいたらしめん我が離るる時かれらの禍大なる哉');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'われエフライムを美地に植てツロのごとくなししかどもエフライムはその子等を携へいだして人を殺すに付さんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'ヱホバよ彼らに與へたまへ汝なにを與へんとしたまふや孕まざる胎と乳なき乳房とを與へたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'かれらが凡の惡はギルガルにあり此故に我かしこにて之を惡めりその行爲あしければ我が家より逐いだし重て愛することをせじその牧伯等はみな悖れる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'エフライムは撃れその根はかれて果を結ぶまじ若し產ことあらば我その胎なる愛しむ實を殺さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'かれら聽從はざるによりて我が神これを棄たまふべしかれらは列國民のうちに流離人とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'イスラエルは果をむすびて茂り榮る葡萄の樹その果の多くなるがままに祭壇をましその地の饒かなるがままに偶像を美しくせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'かれらは二心をいだけり今かれら罪せらるべし神はその祭壇を打毀ちその偶像を折棄てたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'かれら今いふべし我儕神を畏れざりしに因て我らに王なしこの王はわれらのために何をかなさんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'かれらは虚しき言をいだし偽の誓をなして約をたつ審判は畑の畝にもえいづる茵蔯のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'サマリヤの居民はベテアベンの犢の故によりて戰慄かんその民とこれを悦ぶ祭司等はその榮のうせたるが爲になげかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, '犢はアッスリヤに携へられ禮物としてヤレブ王に献げらるべしエフライムは羞をかうむりイスラエルはおのが計議を恥ぢん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'サマリヤはほろびその王は水のうへの木片のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'イスラエルの罪なるアベンの崇邱は荒はてて荊棘と蒺藜その壇のうへにはえ茂らんその時かれら山にむかひて我儕をおほへ陵にむかひて我儕のうへに倒れよといはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'イスラエルよ汝はギベアの日より罪ををかせり彼等はそこに立り邪惡のひとびとを攻たりし戰爭はギベアにてかれらに及ばざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, '我思ふままに彼等をいましめん彼等その二の罪につながれん時もろもろの民あつまりて之をせめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'エフライムは馴されたる牝牛のごとくにして穀をふむことを好むされどわれその美しき頸に物を負しむべし我エフライムに軛をかけんユダは耕しヤコブは土塊をくだかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'なんぢら義を生ずるために種をまき憐憫にしたがひてかりとり又新地をひらけ今はヱホバを求むべき時なり終にはヱホバきたりて義を雨のごとく汝等のうへに降せたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'なんぢらは惡をたがへし不義を穫をさめ虚偽の果をくらへりこは汝おのれの途をたのみ己が勇士の數衆きをたのめるに縁る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'この故になんぢらの民のなかに擾亂おこりて汝らの城はことごとく打破られんシャルマンが戰門の日にベテアルベルを打破りしにことならず母その子とともに碎かれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'なんぢらの大なる惡のゆゑによりてべテル如此なんぢらに行へるなりイスラエルの王はあしたに滅びん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'イスラエルの幼かりしとき我これを愛しぬ我わが子をエジプトより呼いだしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'かれらは呼るるに隨ひていよいよその呼者に遠ざかり且もろもろのバアルに犠牲をささげ雕たる偶像に香を焚り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'われエフライムに歩むことををしへ彼等をわが腕にのせて抱けり然どかれらは我にいやされたるを知ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'われ人にもちゐる索すなはち愛のつなをもて彼等をひけり我がかれらを待ふは軛をその腮より擧のくるもののごとくにして彼等に食物をあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'かれらはエジプトの地にかへらじ然どかれらがヱホバに歸らざるによりてアッスリヤ人その王とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, '劍かれらの諸邑にまはりゆきてその關門をこぼち彼らをその謀計の故によりて滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'わが民はともすれば我にはなれんとする心あり人これを招きて上に在るものに屬しめんとすれども身をおこすもの一人だになし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'エフライムよ我いかで汝をすてんやイスラエルよ我いかで汝をわたさんや我いかで汝をアデマのごとくせんや爭でなんぢをゼボイムのごとく爲んやわが心わが衷にかはりて我の愛憐ことごとく燃おこれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, '我わが烈しき震怒をほどこすことをせじ我かさねてエフライムを滅すことをせじ我は人にあらず神なればなり我は汝のうちにいます聖者なりいかりをもて臨まじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'かれらは獅子の吼るごとくに聲を出したまふヱホバに隨ひて歩まんヱホバ聲を出したまへば子等は西より急ぎ來らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'かれらエジプトより鳥のごとくアッスリヤより鴿のごとくに急ぎ來らん我かれらをその家々に住はしむべし是ヱホバの聖言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'エフライムは謊言をもてイスラエルの家は詐僞をもて我を圍めりユダは神と信ある聖者とに屬きみつかずみ漂蕩をれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'エフライムは風をくらひ東風をおひ日々に詐僞と暴逆とを増くはへアッスリヤと契約を結び油をエジプトに餽れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'ヱホバはユダと爭辨をなしたまふヤコブをその途にしたがひて罰しその行爲にしたがひて報いたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'ヤコブは胎にゐし時その兄弟の踵をとらへまた己が力をもて神と角力あらそへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'かれは天の使と角力あらそひて勝ちなきて之に恩をもとめたり彼はベテルにて神にあへり其處にて神われらに語ひたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'これは萬軍の神ヱホバなりヱホバは其記念の名なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, '然ばなんぢの神にかへり矜恤と公義とをまもり恒になんぢの神を仰ぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, '彼はカナン人(商賈)なりその手に詭詐の權衡をもち好であざむき取ことをなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'エフライムはいふ誠にわれは富る者となれり我は身に財寳をえたり凡てわが勞したることの中に罪をうべき不義を見いだす者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, '我ヱホバはエジプトの國をいでしより以來なんぢらの神なり我いまも尚なんぢを幕屋にすまはせて節會の日のごとくならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, '我もろもろの預言者にかたり又これに益々おほく異象をしめしたり我もろもろの預言者に托して譬喩をまうく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'ギレアデは不義なる者ならずや彼らは全く虚しかれらはギルガルにて牛を犠牲に献ぐかれらの祭壇は圃の畝につみたる石の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'ヤコブはアラムの野ににげゆけりイスラエルは妻を得んために人に事へ妻を得んために羊を牧へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'ヱホバ一人の預言者をもてイスラエルをエジプトより導きいだし一人の預言者をもて之を護りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'エフライムは怒を激ふること極てはなはだしその主かれが流しし血をかれが上にとどめその恥辱をかれに歸らせたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'エフライム言を出せば人をののけり彼はイスラエルのなかに己をたかうしバアルにより罪を犯して死たりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, '今も尚ますます罪を犯しその銀をもて己のために像を鋳その機巧にしたがひて偶像を作る是みな工人の作なるなり彼らは之につきていふ犠牲を献ぐる者はこの犢に吻を接べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, '是によりて彼らは朝の雲のごとく速にきえうする露のごとく打場より大風に吹散さるる穀殻のごとく窓より出ゆく煙のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'されど我はエジプトの國をいでてより以來なんぢの神ヱホバなり爾われの外に神を知ことなし我のほかに救者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, '我さきに荒野にて水なき地にて爾を顧みたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'かれらは秣場によりて食に飽き飽くによりてその心たかぶり是によりて我を忘れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, '斯るがゆゑに我かれらに對ひて獅子の如くなり途の傍にひそみうかがふ豹のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'われ子をうしなへる熊のごとく彼らに向ひてその心膜を裂き獅子の如くこれを食はん野の獣これを攫斷るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'イスラエルよ汝の滅ぶるは我に背き汝を助くる者に背くが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, '汝のもろもろの邑に汝を助くべき汝の王は今いづくにかあるなんぢらがその王と牧伯等とを我に與へよと言たりし士師等は今いづくにかある');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'われ忿怒をもて汝に王を與へ憤恨をもて之をうばひたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'エフライムの不義は包まれてありその罪はをさめたくはへられたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, '劬勞にかかれる婦のかなしみ之に臨まん彼は愚なる子なり時に臨みてもなほ產門に入らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, '我かれらを陰府の手より贖はん我かれらを死より贖はん死よなんぢの疫は何處にあるか陰府よなんぢの災は何處にあるか悔改はかくれて我が目にみえず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, '彼は兄弟のなかにて果を結ぶこと多けれども東風吹きたりヱホバの息荒野より吹おこらん之がためにその泉は乾その源は涸れんその積蓄へたるもろもろの賓貴器皿は掠め奪はるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'サマリヤはその神にそむきたれば刑せられ劍に斃れんその嬰兒はなげくだかれその孕たる婦は剖れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'イスラエルよ汝の神ヱホバに歸れよ汝は不義のために仆れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, '汝ら言詞をたづさへ來りヱホバに歸りていへ諸の不義は赦して善ところを受納れたまへ斯て我らは唇をもて牛のごとくに汝に献げん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'アッスリヤはわれらを授けじ我らは馬に騎らじまたふたたび我儕みづからの手にて作れる者にむかひわが神なりと言じ孤兒は爾によりて憐憫を得べければなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, '我かれらの反逆を醫し悦びて之を愛せん我が怒はかれを離れ去たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, '我イスラエルに對しては露のごとくならん彼は百合花のごとく花さきレバノンのごとく根をはらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'その枝は茂りひろがり其美麗は橄欖の樹のごとくその芬芳はレバノンのごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'その蔭に住む者かへり來らんかれらは穀物の如く活かへり葡萄樹のごとく花さきその馨香はレバノンの酒のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'エフライムはいふ我また偶像と何のあづかる所あらんやと我これに應へたり我かれを顧みん我は蒼翠の松のごとし汝われより果を得ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, '誰か智慧ある者ぞその人はこの事を暁らん誰か頴悟ある者ぞその人は之を知んヱホバの道は凡て直し義者は之を歩む然ど罪人は之に躓かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'ペトエルの子ヨエルに臨めるヱホバの言');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, '老たる人よ汝ら是を聽け すべて此地に住む者汝ら耳を傾けよ 汝らの世あるは汝らの先祖の世にも是のごとき事ありしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, '汝ら之を子に語り子はまた之をその子に語りその子之を後の代に語りつたへよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, '噬くらふ蝗虫の遺せる者は群ゐる蝗虫のくらふ所となりその遺せる者はなめつくすおほねむしのくらふ所となりその遺せる者は喫ほろぼす蝗虫の食ふ所となれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, '醉る者よ汝ら目を醒して泣け すべて酒をのむ者よ哭きさけべ あたらしき酒なんぢらの口に絶えたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'そはことなる民わが國に攻よすればなり その勢ひ強くその數はかられずその齒は獅子の齒のごとくその牙は牝獅子の牙のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, '彼等わが葡萄の樹を荒しわが無花果の樹を折りその皮をはぎはだかにして之を棄つ その枝白くなれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, '汝ら哀哭かなしめ 貞女その若かりしときの夫のゆゑに麻布を腰にまとひて哀哭かなしむがごとくせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, '素祭灌祭ともにヱホバの家に絶えヱホバに事ふる祭司等哀傷をなす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, '田は荒れ地は哀傷む 是穀物荒はて新しき酒つき油たえんとすればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'こむぎ大むぎの故をもて農夫羞ぢよ 葡萄をつくり哭けよ 田の禾稼うせはてたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, '葡萄樹は枯れ無花果樹は萎れ石榴椰子林檎および野の諸の樹は凋みたり 是をもて世の人の喜樂かれうせぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, '祭司よ汝ら麻布を腰にまとひてなきかなしめ 祭壇に事ふる者よ汝らなきさけべ 神に事ふる者よなんぢら來り麻布をまとひて夜をすごせ 其は素祭も灌祭も汝らの神の家に入ことあらざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, '汝ら斷食を定め集會を設け長老等を集め國の居民をことごとく汝らの神ヱホバの家に集めヱホバにむかひて號呼れよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'ああその日は禍なるかな ヱホバの日近く暴風のごとくに全能者より來らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, '我らがまのあたりに食物絶えしにあらずや 我らの神の家に歡喜と快樂絶しにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, '種は土の下に朽ち倉は壞れ廩は圯る そは穀物ほろぼされたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'いかに畜獸は哀み鳴くや 牛の群は亂れ迷ふ 草なければなり 羊の群もまた死喪ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'ヱホバよ我なんぢに向ひて呼はらん 荒野の諸の草は火にて燒け野の諸の樹は火熖にてやけつくればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, '野の獸もまた汝にむかひて呼はらん 其は水の流涸はて荒野の草火にてやけつくればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, '汝らシオンにて喇叭を吹け 我聖山にて音たかく之を吹鳴せ 國の民みな慄ひわななかん そはヱホバの日きたらんとすればなり すでに近づけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'この日は黑くをぐらき日雲むらがるまぐらき日にしてしののめの山々にたなびくが如し 數おほく勢さかんなる民むれいたらん かかる者はいにしへよりありしことなくのちの代々の年にもあることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, '火彼らの前を焚き火熖かれらの後にもゆ その過さる前は地エデンのごとくその過しのちは荒はてたる野の如し 此をのがれうるもの一としてあることなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, '彼らの状は馬のかたちのごとく其馳ありくことは軍馬のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'その山の嶺にとびをどる音は車の轟聲がごとし また火の稗株をやくおとの如くしてその樣強き民の行伍をたてて戰陣にのぞむに似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'そのむかふところ諸民戰慄きその面みな色を失ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, '彼らは勇士の如くに趨あるき軍人のごとくに石垣に攀のぼる 彼ら各々おのが道を進みゆきてその列を亂さず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, '彼ら互に推あはず各々その道にしたがひて進み行く 彼らは刄に觸るとも身を害はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, '彼らは邑をかけめぐり石垣の上に奔り家に攀登り盗賊のごとくに窓より入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'そのむかふところ地ゆるぎ天震ひ日も月も暗くなり星その光明を失ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'ヱホバその軍勢の前にて聲をあげたまふ 其軍旅はなはだ大なればなり 其言を爲とぐる者は強し ヱホバの日は大にして甚だ畏るべきが故に誰かこれに耐ることを得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, '然どヱホバ言たまふ 今にても汝ら斷食と哭泣と悲哀とをなし心をつくして我に歸れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, '汝ら衣を裂かずして心を裂き汝等の神ヱホバに歸るべし 彼は恩惠あり憐憫ありかつ怒ることゆるく愛憐大にして災害をなすを悔たまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, '誰か彼のあるひは立歸り悔て祝福をその後にとめのこし汝らをして素祭と灌祭とをなんぢらの神ヱホバにささげしめたまはじと知んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, '汝らシオンにて喇叭を吹きならし斷食を定め公會をよびつどへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, '民を集めその會を潔くし老たる人をあつめ孩童と乳哺子を集め新郎をその室より呼いだし新婦をその密室より呼いだせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, '而してヱホバに事ふる祭司等は廊と祭壇の間にて泣て言へ ヱホバよ汝の民を赦したまへ 汝の產業を恥辱しめらるるに任せ之を異邦人に治めさする勿れ 何ぞ異邦人をして彼らの神は何處にあると言しむべけんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, '然せばヱホバ己の地にために嫉妬を起しその民を憐みたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'ヱホバ應へてその民に言たまはん 視よ我穀物とあたらしき酒と油を汝におくる 汝ら之に飽ん 我なんぢらをして重ねて異邦人の中に恥辱を蒙らしめじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, '我北よりきたる軍を遠く汝らより離れしめうるほひなき荒地に逐やらん 其前軍を東の海にその後軍を西の海に入れん その臭味立ちその惡臭騰らん 是大なる事を爲たるに因る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, '地よ懼るる勿れ 喜び樂しめ ヱホバ大なる事を行ひたまふなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, '野の獸よ懼るる勿れ あれ野の牧草はもえいで樹は果を結び無花果樹葡萄樹はその力をめざすなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'シオンの子等よ 汝らの神ヱホバによりて樂め喜べ ヱホバは秋の雨を適當なんぢらに賜ひまた前のごとく秋の雨と春の雨とを汝らの上に降せたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, '打塲には穀物盈ち甕にはあたらしき酒と油溢れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, '我が汝らに遣しし大軍すなはち群ゐる蝗なめつくす蝗喫ほろぼす蝗噬くらふ蝗の觸あらせる年をわれ汝らに賠はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, '汝らは食ひ食ひて飽き よのつねならずなんぢらを待ひたまひし汝らの神ヱホバの名をほめ頌へん 我民はとこしへに辱しめらるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'かくて汝らはイスラエルの中に我が居るを知り汝らの神ヱホバは我のみにて外に無きことを知らん 我民は永遠に辱かしめらるることなかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'その後われ吾靈を一切の人に注がん 汝らの男子女子は預言せん 汝らの老たる人は夢を見 汝らの少き人は異象を見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'その日我またわが靈を僕婢に注がん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'また天と地に徴證を顯さん 即ち血あり火あり煙の柱あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'ヱホバの大なる畏るべき日の來らん前に日は暗く月は血に變らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, '凡てヱホバの名を龥ぶ者は救はるべし そはヱホバの宣ひし如くシオンの山とヱルサレムとに救はれし者あるべければなり 其遺れる者の中にヱホバの召し給へるものあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '觀よ我ユダとヱルサレムの俘囚人を歸さん その日その時');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, '萬國の民を集め之を携へてヨシヤパテの谷にくだりかしこにて我民我ゆづりの產なるイスラエルのために彼らをさばかん 彼らこれを國々に散してその地を分ち取りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, '彼らは籤をひきて我民を取り童子を娼妓に換へ童女を賣り酒に換て飮めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'ツロ、シドンよベリシテのすべての國よ 汝ら我と何のかかはりあらんや 汝ら我がなししことに返をなさんとするや 若し我に返報をなさんとならば我忽ち迅速に汝らがなししことをもてその首に歸らしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, '是は汝らは我の金銀を取り我のしたふべき寶を汝らの宮にたづさへゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'またユダの人とヱルサレムの人をギリシヤ人に賣りてその本國より遠く離らせたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, '視よ我かられを起して汝らが賣りたる處より出し汝らがなししことをもてその首にかへらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, '我はなんぢらの男子女子をユダの人の手に賣り彼らは之を遠き民なるシバ人に賣らん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'もろもろの國に宣つたへよ 戰爭の準備を爲し勇士をはげまし軍人をことごとくちかより來らしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, '汝等の鋤を劍に打かへ汝らの鎌を鎗に打かへよ 弱き者も我は強しと言へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, '四周の國々の民よ汝ら急ぎ上りて集れ ヱホバよ汝の勇士をかしこに降したまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, '國々の民よ起て上りヨシヤパテの谷に至れ 彼處に我座をしめて四周の國々の民をことごとく鞫かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, '鎌をいれよ 穀物は熟せり 來り踏めよ酒榨は盈ち甕は溢る 彼らの惡大なればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'かまびすしきかな無數の民審判の谷にありてかまびすし ヱホバの日審判の谷に近づくが故なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, '日も月も暗くなり星その光明を失ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'ヱホバ、シオンよりよびとどろかしヱルサレムより聲をはなち天地を震ひうごかしたまふ 然れどヱホバはその民の避所イスラエルの子孫の城となりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'かくて汝ら我はヱホバ汝等の神にして我聖山シオンに住むことをしるべし ヱルサレムは聖き所となり他國の人は重ねてその中をかよふまじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'その日山にあたらしき酒滴り岡に乳流れユダのもろもろの河に水流れヱホバの家より泉水流れいでてシッテムの谷に灌がん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'エジプトは荒すたれエドムは荒野とならん 是はかれらユダの子孫を虐げ辜なき者の血をその國に流したればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'されどユダは永久にすまひヱルサレムは世々に保たん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, '我さきにはかれらが流しし血の罪を報いざりしが今はこれをむくいん ヱホバ、シオンに住みたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'テコアの牧者の中なるアモスの言 是はユダの王ウジヤの世 イスラエルの王ヨアシの子ヤラベアムの世 地震の二年前に彼が見されたる者にてイスラエルの事を論るなり 其言に云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'ヱホバ、シオンより呼號りエルサレムより聲を出したまふ 牧者の牧塲は哀きカルメルの巓は枯る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'ヱホバかく言たまふ ダマスコは三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼らは鐵の打禾車をもてギレアデを打り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, '我ハザエルの家に火を遣りベネハダデの宮殿を焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, '我ダマスコの關を碎きアベンの谷の中よりその居民を絶のぞきベテエデンの中より王の杖を執る者を絶のぞかん スリアの民は擄へられてキルにゆかん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'ヱホバかく言たまふ ガザは三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼らは俘囚をことごとく曳ゆきてこれをエドムに付せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, '我ガザの石垣の内に火を遣り一切の殿を焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, '我アシドドの中よりその居民を絶のぞきアシケロンの中より王の杖を執る者を絶除かん 我また手を反してエクロンを撃ん ペリシテ人の遺れる者亡ぶべし 主ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'ヱホバかく言たまふ ツロは三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼らは俘囚をことごとくエドムに付しまた兄弟の契約を忘れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, '我ツロの石垣の内に火を遣り一切の殿を焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'ヱホバかく言たまふ エドムは三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼は劍をもてその兄弟を追ひ全く憐憫の情を斷ち恒に怒りて人を害し永くその憤恨をたくはへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, '我テマンに火を遣りポヅラの一切の殿を焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'ヱホバかく言たまふ アンモンの人々は三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼らはその國境を廣めんとてギレアデの孕める婦を剖たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, '我ラバの石垣の内に火を放ちその一切の殿を焚ん 是は戰鬪の日に吶喊の聲をもて爲され暴風の日に旋風をもて爲されん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, '彼らの王はその牧伯等と諸共に擄へられて往ん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'ヱホバかく言たまふ モアブは三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼はエドムの王の骨を燒て灰となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, '我モアブに火を遣りケリオテの一切の殿を焚ん モアブは噪擾と吶喊の聲と喇叭の音の中に死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, '我その中より審判長を絶除きその諸の牧伯を之とともに殺さん ヱホバはこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'ヱホバかく言たまふ ユダは三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼らはヱホバの律法を輕んじその法度を守らずその先祖等が從ひし僞の物に惑はさる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, '我ユダに火を遣りエルサレムの諸の殿を焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'ヱホバかく言たまふ イスラエルは三の罪あり 四の罪あれば我かならず之を罰して赦さじ 即ち彼らは義者を金のために賣り貧者を鞋一足のために賣る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, '彼らは弱き者の頭に地の塵のあらんことを喘ぎて求め柔かき者の道を曲げ又父子共に一人の女子に行て我聖名を汚す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, '彼らは質に取れる衣服を一切の壇の傍に敷きてその上に偃し罰金をもて得たる酒をその神の家に飮む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, '嚮に我はアモリ人を彼らの前に絶たり アモリ人はその高きこと香柏のごとくその強きこと橡の樹のごとくなりしが我その上の果と下の根とをほろぼしたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, '我は汝らをエジプトの地より携へのぼり四十年のあひだ荒野において汝らを導き終にアモリ人の地を汝らに獲させたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, '我は汝らの子等の中より預言者を興し汝らの少者の中よりナザレ人を興したり イスラエルの子孫よ然るにあらずや ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, '然るに汝らはナザレ人に酒を飮ませ預言者に命じて預言するなかれと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, '視よ我麥束を積滿せる車の物を壓するがごとく汝らを壓せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'その時は疾走者も逃るに暇あらず 強き者もその力を施すを得ず 勇士も己の生命を救ふこと能はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, '弓を執る者も立ことを得ず 足駛の者も自ら救ふ能はず 馬に騎れる者も己の生命を救ふこと能はず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, '勇士の中の心剛き者もその日には裸にて逃ん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'イスラエルの子孫よヱホバが汝らにむかひて言ところ我がエジプトの地より導き上りし全家にむかひて言ところの此言を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, '地の諸の族の中にて我ただ汝ら而已を知れり この故に我なんぢらの諸の罪のために汝らを罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, '二人もし相會せずば爭で共に歩かんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, '獅子もし獲物あらずば豈林の中に吼んや 猛獅子もし物を攫まずば豈その穴より聲を出さんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'もし羂の設なくば鳥あに地に張れる網にかからんや 網もし何の得るところも無くば豈地よりあがらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, '邑にて喇叭を吹かば民おどらかざらんや 邑に災禍のおこるはヱホバのこれを降し給ふならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, '夫主ヱホバはその隱れたる事をその僕なる預言者に傳へずしては何事をも爲たまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, '獅子吼ゆ 誰か懼れざらんや 主ヱホバ言語たまふ 誰か預言せざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'アシドドの一切の殿に傳へエジプトの地の一切の殿に宣て言へ 汝等サマリヤの山々に集りその中にある大なる紛亂を觀その中間におこなはるる虐遇を觀よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'ヱホバいひたまふ 彼らは正義をおこなふことを知ず 虐げ取し物と奪ひたる物とをその宮殿に積蓄ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, '是故に主ヱホバかく言たまふ 敵ありて此國を攻かこみ汝の權力を汝より取下さん 汝の一切の殿は掠めらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'ヱホバかく言たまふ 牧羊者は獅子の口より羊の兩足あるひは片耳を取かへし得るのみ サマリヤに於て床の隅またはダマスコ錦の榻に坐するイスラエルの子孫もその救はるること是のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, '萬軍の神 主ヱホバかく言たまふ 汝ら聽てヤコブの家に證せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, '我イスラエルの諸の罪を罰する日にはベテルの壇を罰せん 其壇の角は折て地に落べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, '我また冬の家および夏の家をうたん 象牙の家ほろび大きなる家失ん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'バシヤンの牝牛等よ汝ら此言を聽け 汝らはサマリヤの山に居り弱者を虐げ貧者を壓し又その主にむかひて此に持きたりて我らに飮せよと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, '主ヱホバ己の聖を指し誓ひて云ふ 視よ日汝らの上に臨む その日には人汝らを鈎にかけ汝等の遺餘者を釣魚鈎にかけて曳いださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, '汝らは各々その前なる石垣の破壞たる處より奔出てハルモンに逃往ん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, '汝らベテルに往て罪を犯しギルガルに往て益々おほく罪を犯せ 朝ごとに汝らの犠牲を携へゆけ 三日ごとに汝らの什一を携へゆけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, '酵いれたる者を感謝祭に獻げ願意よりする禮物を召てこれを告示せ イスラエルの子孫よ 汝らは斯するを好むなりと主ヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'また我汝らの一切の邑に於て汝らの齒を清からしめ汝らの一切の處において汝らの食を乏しからしめたり 然るに汝らは我に歸らずとヱホバ言給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'また我収穫までには尚三月あるに雨をとどめて汝らに下さず かの邑には雨を降しこの邑には雨をふらさざりき 此田圃は雨を得 彼田圃は雨を得ずして枯れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, '二三の邑別の一の邑に躚めきゆきて水を飮ども飽ことあたはず 然るに汝らは我に歸らずとヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '我枯死殻と朽腐穗とをもて汝等を撃なやませり また汝らの衆多の園と葡萄園と無花果樹と橄欖樹とは蝗これを食へり 然るに汝らは我に歸らずとヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '我なんぢらの中にエジプトに爲し如く疫病をおこし劍をもて汝らの少き人を殺し又汝らの馬を奪さり汝らの營の臭氣をして騰りて汝らの鼻を撲しめたり 然るも汝らは我に歸らずとヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '我なんぢらの中の邑を滅すことソドム、ゴモラを神の滅したまひし如くしたれば汝らは熖の中より取いだしたる燃柴のごとくなれり 然るも汝らは我に歸らずとヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'イスラエルよ然ば我かく汝に行はん 我是を汝に行ふべければイスラエルよ汝の神に會ふ準備をせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, '彼は即ち山を作りなし風を作り出し人の思想の如何なるをその人に示しまた晨光をかへて黑暗となし地の高處を踏む者なり その名を萬軍の神ヱホバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'イスラエルの家よ我が汝らに對ひて宣る此言を聽け 是は哀歎の歌なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, '處女イスラエルは仆れて復起あがらず彼は己の地に扑倒さる 之を扶け起す者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, '主ヱホバかく言たまふ イスラエルの家においては前に千人出たる邑は只百人のみのこり前に百人出たる邑は只十人のみのこらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'ヱホバかくイスラエルの家に言たまふ 汝ら我を求めよ さらば生べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'ベテルを求むるなかれ ギルガルに往なかれ ベエルシバに赴く勿れ ギルガルは必ず擄へられゆきベテルは無に歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, '汝らヱホバを求めよ 然ば生べし 恐くはヱホバ火のごとくにヨセフの家に落くだりたまひてその火これを燒ん ベテルのためにこれを熄す者一人もあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, '汝ら公道を茵蔯に變じ正義を地に擲つる者よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, '昴宿および參宿を造り死の蔭を變じて朝となし晝を暗くして夜となし海の水を呼て地の面に溢れさする者を求めよ 其名はヱホバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, '彼は滅亡を忽然強者に臨ましむ 滅亡つひに城に臨む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, '彼らは門にありて勸戒る者を惡み正直を言ふ者を忌嫌ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, '汝らは貧き者を踐つけ麥の贐物を之より取る この故に汝らは鑿石の家を建しと雖どもその中に住ことあらじ 美しき葡萄園を作りしと雖どもその酒を飮ことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, '我知る汝らの愆は多く汝らの罪は大なり 汝らは義き者を虐げ賄賂を取り門において貧き者を推抂ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, '是故に今の時は賢き者默す 是惡き時なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, '汝ら善を求めよ 惡を求めざれ 然らば汝ら生べし また汝らが言ごとく萬軍の神ヱホバ汝らと偕に在さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, '汝ら惡を惡み善を愛し門にて公義を立よ 萬軍の神ヱホバあるひはヨセフの遺れる者を憐れみたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, '是故に主たる萬軍の神ヱホバかく言たまふ 諸の街衢にて啼ことあらん 諸の大路にて人哀哉哀哉と呼ん 又農夫を呼きたりて哀哭しめ啼女を招きて啼しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'また諸の葡萄園にも啼こと有べし 其は我汝らの中を通るべければなり ヱホバこれを言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'ヱホバの日を望む者は禍なるかな 汝ら何とてヱホバの日を望むや 是は昏くして光なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, '人獅子の前を逃れて熊に遇ひ又家にいりてその手を壁に附て蛇に咬るるに宛も似たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'ヱホバの日は昏くして光なく暗にして耀なきに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, '我は汝らの節筵を惡みかつ藐視む また汝らの集會を悦ばじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, '汝ら我に燔祭または素祭を獻ぐるとも我之を受納れじ 汝らの肥たる犢の感謝祭は我これを顧みじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, '汝らの歌の聲を我前に絶て汝らの琴の音は我これを聽じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, '公道を水のごとくに正義をつきざる河のごとくに流れしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'イスラエルの家よ汝らは四十年荒野に居し間犠牲と供物を我に獻げたりしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'かへつて汝らは汝らの王シクテを負ひ汝らの偶像キウンを負へり 是即ち汝らの神とする星にして汝らの自ら造り設けし者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, '然ば我汝らをダマスコの外に移さん 萬軍の神ととなふるヱホバこれを言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, '身を安くしてシオンに居る者思ひわづらはずしてサマリヤの山に居る者 諸の國にて勝れたる國の中なる聞高くしてイスラエルの家に就きしたがはるる者は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'カルネに渉りゆき彼處より大ハマテに至りまたペリシテ人のガテに下りて視よ其等は此二國に愈るや 彼らの土地は汝らの土地よりも大なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, '汝等は災禍の日をもて尚遠しと爲し強暴の座を近づけ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, '自ら象牙の牀に臥し寢臺の上に身を伸し群の中より羔羊を取り圏の中より犢牛を取て食ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, '琴の音にあはせて唄ひ噪ぎダビデのごとくに樂器を製り出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, '大斝をもて酒を飮み最も貴とき膏を身に抹りヨセフの艱難を憂へざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, '是故に今彼等は擄はれて俘囚人の眞先に立て往んかの身を伸したる者等の嘈の聲止べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, '萬軍の神ヱホバ言たまふ 主ヱホバ己を指て誓へり 我ヤコブが誇る所の物を忌嫌ひその宮殿を惡む 我この邑とその中に充る者とを付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, '一の家に十人遺りをるとも皆死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, '而してその親戚すなはち之を焚く者その死骸を家より運びいださんとて之を取あげまたその家の奧に潛み居る者に向ひて他になほ汝とともに居る者あるやと言ふとき對へて一人も無しと言ん 此時かの人また言べし 默せよヱホバの名を口に擧ること有べからずと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, '視よヱホバ命を下し大なる家を撃て墟址とならしめ小き家を撃て微塵とならしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, '馬あに能く岩の上を走らんや 人あに牛をもて岩を耕へすことを得んや 然るに汝らは公道を毒に變じ正義の果を茵蔯に變じたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, '汝らは無物を喜び我儕は自分の力をもて角を得しにあらずやと言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, '是をもて萬軍の神ヱホバ言たまふ イスラエルの家よ我一の國を起して汝らに敵せしめん 是はハマテの入口よりアラバの川までも汝らをなやまさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, '主ヱホバの我に示したまへるところ是のごとし 即ち草の再び生ずる時にあたりて彼蝗を造りたまふ その草は王の刈たる後に生じたるものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'その蝗地の靑物を食盡しし後我言り 主ヱホバよ願くは赦したまへ ヤコブは小し 爭でか立ことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'ヱホバその行へる事につきて悔をなし我これを爲じと言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, '主ヱホバの我に示したまへる所是のごとし 即ち主ヱホバ火をもて罰せんとて火を呼たまひければ火大淵を焚きまた產業の地を焚かんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, '時に我言り 主ヱホバよ願くは止みたまへ ヤコブは小し爭でか立ことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'ヱホバその行へる事につきて悔をなし我これをなさじと主ヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'また我に示したまへるところ是のごとし 即ち準縄をもて築ける石垣の上にヱホバ立ちその手に準縄を執たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, '而してヱホバ我にむかひアモス汝何を見るやと言たまひければ準縄を見ると我答へしに主また言たまはく我準縄を我民イスラエルの中に設く 我再び彼らを見過しにせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'イサクの崇邱は荒されイスラエルの聖所は毀たれん 我劍をもちてヤラベアムの家に起むかはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, '時にベテルの祭司アマジヤ、イスラエルの王ヤラベアムに言遣しけるはイスラエルの家の眞中にてアモス汝に叛けり 彼の諸の言には此地も堪るあたはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, '即ちアモスかく言り ヤラベアムは劍によりて死ん イスラエルは必ず擄へられてゆきてその國を離れんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, '而してアマジヤ、アモスに言けるは先見者よ 汝往てユダの地に逃れ彼處にて預言して汝の食物を得よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, '然どベテルにては重ねて預言すべからず 是は王の聖所王の宮なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'アモス對へてアマジヤに言けるは我は預言者にあらず また預言者の子にも非ず 我は牧者なり 桑の樹を作る者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, '然るにヱホバ羊に從ふ所より我を取り往て我民イスラエルに預言せよとヱホバわれに宣へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, '今ヱホバの言を聽け 汝は言ふイスラエルにむかひて預言する勿れ イサクの家にむかひて言を出すなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, '是故にヱホバかく言たまふ 汝の妻は邑の中にて妓婦となり汝の男子女子は劍に斃れ汝の地は繩をもて分たれん 而して汝は穢れたる地に死にイスラエルは擄られゆきてその國を離れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, '主ヱホバの我に示したまへるところ是のごとし 即ち熟したる果物一筐あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'ヱホバわれにむかひてアモス汝何を見るやと言たまひければ熟したる果物一筐を見ると答へしにヱホバ我に言たまはく我民イスラエルの終いたれり 我ふたたび彼らを見過しにせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, '主ヱホバ言たまふ 其日には宮殿の歌は哀哭に變らん 死屍おびただしくあり 人これを遍き處に投棄ん 默せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, '汝ら喘ぎて貧しき者に迫り且地の困難者を滅す者よ之を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, '汝らは言ふ月朔は何時過去んか 我等穀物を賣んとす 安息日は何時過去んか 我ら麥倉を開かんとす 我らエパを小くしシケルを大くし僞の權衡をもて欺く事をなし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, '銀をもて賤しき者を買ひ鞋一足をもて貧き者を買ひかつ屑麥を賣いださんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'ヱホバ、ヤコブの榮光を指て誓ひて言たまふ 我かならず彼等の一切の行爲を何時までも忘れじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, '之がために地震はざらんや地に住る者みな哭かざらんや 地みな河のごとく噴あがらん エジプトの河のごとく湧あがり又沈まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, '主ヱホバ言たまふ其日には我日をして眞晝に沒せしめ地をして白晝に暗くならしめ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, '汝らの節筵を悲傷に變らせ汝らの歌を盡く哀哭に變らせ一切の人に麻布を腰に纒はしめ一切の人に頂を剃しめ其日をして獨子を喪へる哀傷のごとくならしめ其終をして苦き日のごとくならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, '主ヱホバ言たまふ 視よ日至らんとす その時我饑饉たを此國におくらん 是はパンに乏しきに非ず 水に渇くに非ず ヱホバの言を聽ことの饑饉なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, '彼らは海より海とさまよひ歩き北より東と奔まはりてヱホバの言を求めん 然ど之を得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'その日には美しき處女も少き男もともに渇のために絶いらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'かのサマリヤの罪を指て誓ひダンよ汝の神は活くと言ひまたベエルシバの路は活くと言る者等は必ず仆れん 復興ることあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, '我觀るに主壇の上に立て言たまはく柱の頭を撃て閾を震はせ之を打碎きて一切の人の首に落かからしめよ 其遺れる者をば我劍をもて殺さん 彼らの逃る者も逃おほすることを得ず 彼らの遁るる者もたすからじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, '假令かれら陰府に掘くだるとも我手をもて之を其處より曳いださん 假令かれら天に攀のぼるとも我これを其處より曳おろさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, '假令かれらカルメルの巓に匿るるとも我これを捜して其處より曳いださん 假令かれら海の底に匿れて我目を逃るるとも我蛇に命じて其處にて之を咬しめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, '假令かれらその敵に擄はれゆくとも我劍に命じて其處にて之を殺さしめん 我かれらの上に我目を注ぎて災禍を降さん 福祉を降さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, '主たる萬軍のヱホバ地に捫れば地鎔けその中に住む者みな哀む 即ち全地は河のごとくに噴あがりエジプトの河のごとくにまた沈むなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, '彼は樓閣を天に作り穹蒼の基を地の上に置ゑまた海の水を呼て地の面にこれを斟ぐなり 其名をヱホバといふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'ヱホバ言たまふ イスラエルの子孫よ 我は汝らを視ことエテオピア人を觀がごとくするにあらずや 我はイスラエルをエジプトの國よりペリシテ人をカフトルよりスリア人をキルより導き來りしにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, '視よ我主ヱホバその目を此罪を犯すところの國に注ぎ之を地の面より滅し絶ん 但し我はヤコブの家を盡くは滅さじ ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, '我すなはち命を下し篩にて物を篩ふがごとくイスラエルの家を萬國の中にて篩はん 一粒も地に落ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, '我民の罪人即ち災禍われらに及ばず我らに降らじと言をる者等は皆劍によりて死ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, '其日には我ダビデの倒れたる幕屋を興しその破壞を修繕ひその傾\\圯たるを興し古代の日のごとくに之を建なほすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, '而して彼らはエドムの遺餘者および我名をもて稱へらるる一切の民を獲ん 此事を行ふ ヱホバかく言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'ヱホバ言ふ 視よ日いたらんとす その時には耕者は刈者に相繼ぎ葡萄を踐む者は播種者に相繼がん また山々には酒滴り岡は皆鎔て流れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, '我わが民イスラエルの俘囚を返さん 彼らは荒たる邑々を建なほして其處に住み葡萄園を作りてその酒を飮み園圃を作りてその果を食はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, '我かれらをその地に植つけん 彼らは我がこれに與ふる地より重ねて抜とらるることあらじ 汝の神ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'オバデヤの預言 主ヱホバ、エドムにつきて斯いひたまふ 我らヱホバより出たる音信を聞けり 一人の使者國々の民の中に遣されて云ふ 起よ我儕起てエドムを攻撃んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, '我汝をして國々の中において小き者たらしむ 汝は大に藐視らるるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, '山崖の巖屋に居り高き處に住む者よ 汝が心の傲慢なんぢを欺けり 汝心の中に謂ふ誰か我を地に曵くだすことを得んと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, '汝たとひ鷲のごとくに高く擧り星の間に巣を造るとも我そこより汝を曵くださん ヱホバこれを言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, '盜賊汝に來り 強盜夜なんぢに來り竊むともその心に滿るときは止ざらんや 嗚呼なんぢは滅されて絶ゆ 葡萄を摘む者汝にいたるも尚 幾何を遺さざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, '嗚呼エサウは搜されその隱しおける物は探りいださる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, '汝と盟約を結べる人々はみな汝を國境に逐やり汝と和好をなせる人々はみな汝を欺きて汝に勝ち汝の食物を食ふ者等は汝の下に羂を設く 彼の中には穎悟あらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'ヱホバ言たまふ當日には我智慧ある者をヱドムより絶除き穎悟をエサウの山より絶除かざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'テマンよ汝の勇士は驚き懼れん 而して人みな終に殺されてエサウの山より絶除かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, '汝はその兄弟ヤコブに暴虐を加へたるに因て恥辱なんぢを蒙はん 汝は永遠に至るまで絶るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, '汝が遠く離れて立をりし日即ち異邦人これが財寳を奪ひ他國人これが門に進み入りエルサレムのために籤を掣たる日には汝も彼らの一人のごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, '汝は汝の兄弟の日すなはちその災禍の日を觀るべからず 又ユダの子孫の滅亡の日を喜ぶべからず その苦難の日には汝口を大きく開べからざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, '我民の滅ぶる日には汝その門に入べからず其滅ぶる日には汝その患難を見べからず 又その滅ぶる日には汝その財寳に手をかく可らず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, '汝路の辻々に立て その逃亡者を斬べからず 其患難の日にこれが遺る者を付すべからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'ヱホバの日萬國に臨むこと邇し 汝の爲せるごとく汝も爲られ汝の應報なんぢの首に歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, '汝等のわが聖山にて飮しごとく萬國の民も恒に飮ん 即ちみな飮かつ啜りて從前より有ざりし者のごとく成ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'シオン山には救はるる者等をりてその山聖所とならん またヤコブの家はその產業を獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'ヤコブの家は火となりヨセフの家は火燄となりエサウの家は藁とならん 即ち彼等これが上に燃てこれを焚ん エサウの家には遺る者一人も無にいたるべし ヱホバこれを言なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, '南の人はエサウの山を獲 平地の人はペリシテを獲ん 又彼らはエフライムの地およびサマリヤの地を獲 べニヤミンはギレアデを獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'かの擄はれゆきしイスラエルの軍旅はカナン人に屬する地をザレパテまで取ん セパラデにあるエルサレムの俘擄人は南の邑々を獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, '然る時に救者シオンの山に上りてエサウの山を鞫かん而して國はヱホバに歸すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'ヱホバの言アミタイの子ヨナに臨めりいはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '起てかの大なる邑ニネベに往きこれを呼はり責めよ そは其惡わが前に上り來ればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, '然るにヨナはヱホバの面をさけてタルシシへ逃れんと起てヨツパに下り行けるが機しもタルシシへ往く舟に遇ければその價値を給へヱホバの面をさけて偕にタルシシへ行んとてその舟に乗れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, '時にヱホバ大風を海の上に起したまひて烈しき颺風海にありければ舟は幾んど破れんとせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'かかりしかば船夫恐れて各おのれの神を呼び又舟を輕くせんとてその中なる載荷を海に投すてたり 然るにヨナは舟の奧に下りゐて臥て酣睡せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, '船長來りて彼に云けるは汝なんぞかく酣睡するや起て汝の神を呼べあるひは彼われらを眷顧て淪亡ざらしめんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'かくて人衆互に云けるは此災の我儕にのぞめるは誰の故なるかを知んがため去來鬮を掣んと やがて鬮をひきしに鬮ヨナに當りければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'みな彼に云けるはこの災禍なにゆゑに我らにのぞめるか請ふ告げよ 汝の業は何なるや 何處より來れるや 汝の國は何處ぞや 何處の民なるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'ヨナ彼等にいひけるは我はヘブル人にして海と陸とを造りたまひし天の神ヱホバを畏るる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, '是に於て船夫甚だしく懼れて彼に云けるは汝なんぞ其事をなせしやと その人々は彼がヱホバの面をさけて逃れしなるを知れり 其はさきにヨナ彼等に告たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, '遂に船夫彼にいひけるは我儕のために海を靜かにせんには汝に如何がなすべきや 其は海いよいよ甚だしく狂蕩たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'ヨナ彼等に曰けるはわれを取りて海に投いれよ さらば海は汝等の爲に靜かにならん そはこの大なる颺風の汝等にのぞめるはわが故なるを知ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'されど船夫は陸に漕もどさんとつとめたりしが終にあたはざりき 其は海かれらにむかひていよいよ烈しく蕩たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'ここにおいて彼等ヱホバに呼はりて曰けるはヱホバよこひねがはくは此人の命の爲に我儕を滅亡したまふ勿れ 又罪なきの血をわれらに歸し給ふなかれ そはヱホバよ汝聖意にかなふところを爲し給へるなればなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'すなわちヨナを取りて海に投入たり しかして海のあるることやみぬ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'かかりしかばその人々おほいにヱホバを畏れヱホバに犧牲を獻げ誓願を立たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'さてヱホバすでに大なる魚を備へおきてヨナを呑しめたまへり ヨナは三日三夜魚の腹の中にありき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'ヨナ魚の腹の中よりその神ヱホバに祈祷て');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, '曰けるは われ患難の中よりヱホバを呼びしに彼われこたへたまへり われ陰府の腹の中より呼はりしに汝わが聲を聽たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, '汝我を淵のうち海の中心に投いれたまひて海の水我を環り汝の波濤と巨浪すべて我上にながる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'われ曰けるは我なんぢの目の前より逐れたれども復汝の聖殿を望まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, '水われを環りて 魂にも及ばんとし淵我をとりかこみ海草わが頭に纒へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'われ山の根基にまで下れり 地の關木いつも我うしろにありき しかるに我神ヱホバよ汝はわが命を深き穴より救ひあげたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'わが靈魂衷に弱りしとき我ヱホバをおもへり しかしてわが祈なんぢに至りなんぢの聖殿におよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'いつはりなる虚き者につかふるものは自己の恩たる者を棄つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'されど我は感謝の聲をもて汝に獻祭をなし 又わが誓願をなんぢに償さん 救はヱホバより出るなりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'ヱホバ其魚に命じたまひければヨナを陸に吐出せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'ヱホバの言ふたたびヨナに臨めり 曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '起てかの大なる府ニネベに往きわが汝に命ずるところを宣よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'ヨナすなはちヱホバの言に循ひて起てニネベに往り ニネベは甚だ大なる邑にしてこれをめぐるに三日を歴る程なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'ヨナその邑に入はじめ一日路を行つつ呼はり曰けるは四十日を歴ばニネベは滅亡さるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'かかりしかばニネベの人々神を信じ斷食を宣れ大なる者より小き者に至るまでみな麻布を衣たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'この言ニネベの王に聞えければ彼 位より起ち朝服を脱ぎ麻布を身に纒ふて灰の中に坐せり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'また王大臣とともに命をくだしてニネベ中に宣しめて曰く人も畜も牛も羊もともに何をも味ふべからず 又物をくらひ水を飮べからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, '人も畜も麻布をまとひ只管神に呼はり且おのおの其惡き途および其手に作す邪惡を離るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, '或は神その聖旨をかへて悔い其烈しき怒を息てわれらを滅亡さざらん 誰かその然らざるを知んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, '神かれらの爲すところをかんがみ其あしき途を離るるを見そなはし彼等になさんと言し所の災禍を悔て之をなしたまはざりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'ヨナこの事を甚だ惡しとして烈く怒り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'ヱホバに祈りて曰けるはヱホバよ我なほ本國にありし時斯あらんと曰しに非ずや さればこそ前にタルシシへ逃れたるなれ 其は我なんぢは矜恤ある神 憐憫あり 怒ること遲く慈悲深くして災禍を悔たまふものなりと知ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'ヱホバよ願くは今わが命を取たまへ 其は生ることよりも死るかた我に善ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'ヱホバ曰たまひけるは汝の怒る事いかで宜しからんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'ヨナは邑より出てその東の方に居り己が爲に其處に一の小屋をしつらひその蔭の下に坐して府の如何に成行くかを見る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'ヱホバ神瓢を備へこれをして發生てヨナの上を覆はしめたり こはヨナの首の爲に庇蔭をまうけてその憂を慰めんが爲なりき ヨナはこの瓢の木によりて甚だ喜べり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'されど神あくる日の夜明に虫をそなへて其ひさごを噛せたまひければ瓢は枯たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'かくて日の出し時神暑き東風を備へ給ひ又日ヨナの首を照しければ彼よわりて心の中に死ることを願ひて言ふ 生ることよりも死るかた我に善し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, '神またヨナに曰たまひけるは瓢の爲に汝のいかる事いかで宜しからんや 彼曰けるはわれ怒りて死るともよろし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'ヱホバ曰たまひけるは汝は勞をくはへず生育ざる此の一夜に生じて一夜に亡びし瓢を惜めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'まして十二萬餘の右左を辨へざる者と許多の家畜とあるこの大なる府ニネベをわれ惜まざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'ユダの王ヨタム、アハズおよびヒゼキヤの代にモレシテ人ミカに臨めるヱホバの言是すなはちサマリアとエルサレムの事につきて彼が示されたる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, '萬民よ聽け 地とその中の者よ耳を傾けよ 主ヱホバ汝らに對ひて證を立たまはん 即ち主その聖殿より之を立たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, '視よヱホバその處より出てくだり地の高處を踏たまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, '山は彼の下に融け谷は裂けたり 火の前なる蝋のごとく坡に流るる水の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, '是みなヤコブの咎の故イスラエルの家の罪のゆゑなり ヤコブの愆とは何か サマリヤにあらずや ユダの崇邱とは何か エルサレムにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, '是故に我サマリヤを野の石堆となし葡萄を植る處と爲し又その石を谷に投おとしその基を露さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'その石像はみな碎かれその獲たる價金はみな火にて焚れん 我その偶像をことごとく毀たん 彼妓女の價金よりこれを積たれば是はまた歸りて妓女の價金となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, '我これがために哭き咷ばん 衣を脱ぎ裸體にて歩行ん 山犬のごとくに哭き駝鳥のごとくに啼ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'サマリヤの傷は醫すべからざる者にてすでにユダに至り我民の門エルサレムにまでおよべり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'ガテに傳ふるなかれ 泣さけぶ勿れ ベテレアフラにて我塵の中に輾びたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'サピルに住る者よ 汝ら裸になり辱を蒙りて進みゆけ ザアナンに住る者は敢て出ず ベテエゼルのの哀哭によりて汝らは立處を得ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'マロテに住る者は己の幸福につきて思ひなやむ 其は災禍ヱホバより出てエルサレムの門に臨めばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'ラキシに住る者よ馬に車をつなげ ラキシはシオンの女の罪の根本なり イスラエルの愆は汝の中に見ゆ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'この故に汝モレセテガテに離別の饋物を與へよ アクジブの家々はイスラエルの王等におけること人を欺く溪川のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'マレシヤにすめる者よ 我また汝の地を獲べき者を汝に携へ往べし イスラエルの榮光アドラムに往ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, '汝その悦ぶところの子等の故によりて汝の髮を剃おろせ 汝の首の剃し處を大きくして鷲のごとくにせよ 其は彼等擄へられて汝を離るればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'その牀にありて不義を圖り惡事を工夫る者等には禍あるべし 彼らはその手に力あるが故に天亮におよべばこれを行ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, '彼らは田圃を貧りてこれを奪ひ家を貧りて是を取りまた人を虐げてその家を掠め人を虐げてその產業をかすむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, '是故にヱホバかく言たまふ 視よ我此族にむかひて災禍を降さんと謀る 汝らはその頸を是より脱すること能はじ また首をあげて歩くこと能はざるべし 其時は災禍の時なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'その日には人汝らにつきて詩を作り悲哀の歌をもて悲哀て言ん 事旣にいたれり 我等は悉く滅さる 彼わが民の產業を人に與ふ 如何なれば我よりこれを離すや 我儕の田圃を違逆者に分ち與ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, '然ば汝らヱホバの會衆の中には籤によりて繩をうつ者一人も有じ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '預言する勿れ 彼らは預言す 彼らは是等の者等にむかひて預言せじ 恥辱彼らを離れざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, '汝ヤコブの家と稱へらるる者よ ヱホバの氣短からんや ヱホバの行爲是のごとくならんや 我言は品行正直者の益とならざらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, '然るに我民は近頃起りて敵となれり 汝らは夫の戰爭を避て心配なく過るところの者等に就てその衣服の外衣を奪ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, '我民の婦女をその悦ぶところの家より逐いだしその子等より我の妝飾を永く奪ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, '起て去れ 是は汝らの安息の地にあらず 是は已に汚れたれば必ず汝らを滅さん 其滅亡は劇かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, '人もし風に歩み謊言を宣べ我葡萄酒と濃酒の事につきて汝に預言せんと言ことあらばその人はこの民の預言者とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'ヤコブよ我かならず汝をことごとく集へ 必ずイスラエルの遺餘者を聚めん 而して我之を同一に置てボヅラの羊のごとく成しめん 彼らは人數衆きによりて牧塲の中なる群のごとくにその聲をたてん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, '打破者かれらに先だちて登彼ら遂に門を打敗り之を通りて出ゆかん 彼らの王その前にたちて進みヱホバその首に立たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, '我言ふヤコブの首領よイスラエルの家の侯伯よ 汝ら聽け公義は汝らの知べきことに非ずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, '汝らは善を惡み惡を好み民の身より皮を剥ぎ骨より肉を剔り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, '我民の肉を食ひその皮を剥ぎその骨を碎きこれを切きざみて鍋に入る物のごとくし鼎の中にいるる肉のごとくす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, '然ば彼時に彼らヱホバに呼はるともヱホバかれらに應へたまはじ 却てその時には面を彼らに隱したまはん 彼らの行惡ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, '我民を惑す預言者は齒にて噛べき物を受る時は平安あらんと呼はれども何をもその口に與へざる者にむかひては戰門の準備をなす ヱホバ彼らにつきて斯いひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, '然ば汝らは夜に遭べし 復異象を得じ 黑暗に遭べし 復卜兆を得じ 日はその預言者の上をはなれて沒りその上は晝も暗かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, '見者は愧を抱き卜者は面を赧らめ皆共にその唇を掩はん 神の垂應あらざればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, '然れども我はヱホバの御靈によりて能力身に滿ち公義および勇氣衷に滿ればヤコブにその愆を示しイスラエルにその罪を示すことを得');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'ヤコブの家の首領等およびイスラエルの家の牧伯等公義を惡み一切の正直事を曲る者よ汝ら之を聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, '彼らは血をもてシオンを建て不義をもてエルサレムを建つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'その首領等は賄賂をとりて審判をなしその祭司等は値錢を取て敎晦をなす 又その預言者等は銀子を取て占卜を爲しヱホバに倚賴みて云ふヱホバわれらと偕に在すにあらずや 然ば災禍われらに降らじと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, '是によりてシオンは汝のゆゑに田圃となりて耕へされエルサレムは石堆となり宮の山は樹の生しげる高處とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, '末の日にいたりてヱホバの家の山諸の山の巓に立ち諸の嶺にこえて高く聳へ萬民河のごとく之に流れ歸せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, '即ち衆多の民來りて言ん 去來我儕ヱホバの山に登ヤコブの神の家にゆかん ヱホバその道を我らに敎へて我らにその路を歩ましめたまはん 律法はシオンより出でヱホバの言はエルサレムより出べければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, '彼衆多の民の間を鞫き強き國を規戒め遠き處にまでも然したまふべし 彼らはその劍を鋤に打かへその鎗を鎌に打かへん 國と國とは劍を擧て相攻めず また重て戰爭を習はじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, '皆その葡萄の樹の下に坐しその無花果樹の下に居ん 之を懼れしむる者なかるべし 萬軍のヱホバの口之を言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, '一切の民はみな各々その神の名によりて歩む 然れども我らはわれらの神ヱホバの名によりて永遠に歩まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'ヱホバ言たまふ 其日には我かの足蹇たる者を集へかの散されし者および我が苦しめし者を聚め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'その足蹇たる者をもて遺餘民となし遠く逐やられたりし者をもて強き民となさん 而してヱホバ、シオンの山において今より永遠にこれが王とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, '羊樓シオンの女の山よ最初の權汝に歸らん 即ちエルサレムの女の國祚なんぢに歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, '汝なにとて喚叫ぶや 汝の中に王なきや 汝の議者絶果しや 汝は產婦のごとくに痛苦を懷くなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'シオンの女よ產婦のごとく劬勞て產め 汝は今邑を出て野に宿りバビロンに往ざるを得ず 彼處にて汝救はれん ヱホバ汝を彼處にて汝の敵の手より贖ひ取り給ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, '今許多の國民あつまりて汝におしよせて言ふ 願くはシオンの汚されんことを 我ら目にシオンを觀てなぐさまんと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, '然ながら彼らはヱホバの思念を知ずまたその御謀議を曉らず ヱホバ麥束を打塲にあつむるごとくに彼らを聚め給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'シオンの女よ起てこなせ 我なんぢの角を鐵にし汝の蹄を銅にせん 汝許多の國民を打碎くべし 汝かれらの掠取物をヱホバに獻げ彼らの財產を全地の主に奉納べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, '軍隊の女よ今なんぢ集りて隊をつくれ 敵われらを攻圍み杖をもてイスラエルの士師の頬を撃つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'ベテレヘム、エフラタ汝はユダの郡中にて小き者なり 然れどもイスラエルの君となる者汝の中より我ために出べし その出る事は古昔より永遠の日よりなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, '是故に產婦の產おとすまで彼等を付しおきたまはん 然る後その遺れる兄弟イスラエルの子孫とともに歸るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, '彼はヱホバの力に由りその神ヱホバの名の威光によりて立てその群を牧ひ之をして安然に居しめん 今彼は大なる者となりて地の極にまでおよばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, '彼は平和なり アッスリヤ人われらの國に入り我らの宮殿を踏あらさんとする時は我儕七人の牧者八人の人君を立てこれに當らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, '彼ら劍をもてアッスリヤの地をほろぼしニムロデの地の邑々をほろぼさん アッスリヤの人我らの地に攻いり我らの境を踏あらす時には彼その手より我らを救はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'ヤコブの遺餘者は衆多の民の中に在こと人に賴ず世の人を俟ずしてヱホバより降る露の如く靑草の上にふりしく雨の如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'ヤコブの遺餘者の國々にをり衆多の民の中にをる樣は林の獸の中に獅子の居るごとく羊の群の中に猛き獅子の居るごとくならん その過るときは踏みかつ裂ことをなす救ふ者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, '望らくは汝の手汝が諸の敵の上にあげられ汝がもろもろの仇ことごとく絶れんことを');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'ヱホバ言たまふ其日には我なんぢの馬を汝の中より絶ち汝の車を毀ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, '汝の國の邑々を絶し汝の一切の城をことごとく圮さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, '我また汝の手より魔術を絶ん 汝の中に卜筮師無にいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, '我なんぢの彫像および柱像を汝の中より絶ん 汝の手にて作れる者を汝重て拜むこと無るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, '我また汝のアシラ像を汝の中より抜たふし汝の邑々を滅さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, '而して我忿怒と憤恨をもてその聽從はざる國民に仇を報いん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, '請ふ汝らヱホバの宣まふところを聽け 汝起あがりて山の前に辨爭へ 崗に汝の聲を聽しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, '山々よ地の易ることなき基よ 汝らヱホバの辨爭を聽け ヱホバその民と辨爭を爲しイスラエルと論ぜん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '我民よ我何を汝になししや 何において汝を疲勞たるや 我にむかひて證せよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, '我はエジプトの國より汝を導きのぼり奴隸の家より汝を贖ひいだしモーセ、アロンおよびミリアムを遣して汝に先だたしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, '我民よ請ふモアブの王バラクが謀りし事およびベオルの子バラムがこれに應へし事を念ひシツテムよりギルガルにいたるまでの事等を念へ 然らば汝ヱホバの正義を知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '我ヱホバの前に何をもちゆきて高き神を拜せん 燔祭の物および當歳の犢をもてその御前にいたるべきか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'ヱホバ數千の牡羊萬流の油を悦びたまはんか 我愆のためにわが長子を獻げんか 我靈魂の罪のために我身の產を獻げんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, '人よ彼さきに善事の何なるを汝に告たり ヱホバの汝に要めたまふ事は唯正義を行ひ憐憫を愛し謙遜りて汝の神とともに歩む事ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'ヱホバの聲邑にむかひて呼はる 智慧ある者はなんぢの名を仰がん 汝ら笞杖および之をおくらんと定めし者に聽け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, '惡人の家に猶惡財ありや 詛ふべき縮小たる升ありや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, '我もし正からざる權衡を用ひ袋に僞の碼子をいれおかば爭で潔からんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'その富る人は強暴にて充ち其居民は謊言を言ひその舌は口の中にて欺くことを爲す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, '是をもて我も汝を撃て重傷を負はせ汝の罪のために汝を滅す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, '汝は食ふとも飽ず腹はつねに空ならん 汝は移すともつひに拯ふことを得じ 汝が拯ひし者は我これを劍に付すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, '汝は種播とも刈ることあらず 橄欖を踐ともその油を身に抹ることあらず 葡萄を踐ともその酒を飮ことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, '汝らはオムリの法度を守りアハブの家の一切の行爲を行ひて彼等の謀計に遵ふ 是は我をして汝を荒さしめ且その居民を胡盧となさしめんが爲なり 汝らはわが民の恥辱を任べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, '我は禍なるかな 我の景况は夏の菓物を採る時のごとく遺れる葡萄を斂むる時に似たり 食ふべき葡萄あること無く我が心に嗜む初結の無花果あること無し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, '善人地に絶ゆ 人の中に直き者なし 皆血を流さんと伏て伺ひ各々網をもてその兄弟を獵る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, '兩手は惡を善なすに急がし 牧伯は要求め裁判人は賄賂を取り力ある人はその心の惡き望を言あらはし斯共にその惡をあざなひ合す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, '彼らの最も善き者も荊棘のごとく最も直き者も刺ある樹の垣より惡し 汝の觀望人の日すなはち汝の刑罰の日いたる 彼らの中に今混亂あらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, '汝ら伴侶を信ずる勿れ 朋友を恃むなかれ 汝の懐に寢る者にむかひても汝の口の戸を守れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, '男子は父を藐視め女子は母の背き媳は姑に背かん 人の敵はその家の者なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, '我はヱホバを仰ぎ望み我を救ふ神を望み俟つ 我神われに聽たまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, '我敵人よ我につきて喜ぶなかれ 我仆るれば興あがる 幽暗に居ればヱホバ我の光となりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'ヱホバわが訴訟を理し我ために審判をおこなひたまふまで我は忍びてその忿怒をかうむらん 其は我これに罪を得たればなり ヱホバつひに我を光明に携へいだし給はん 而して我ヱホバの正義を見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'わが敵これを見ん 汝の神ヱホバは何處にをるやと我に言る者恥辱をかうむらん 我かれを目に見るべし 彼は街衢の泥のごとくに踏つけらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, '汝の垣を築く日いたらん 其日には法度遠く徙るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'その日にはアッスリヤよりエジプトの邑々より人々汝に來りエジプトより河まで海より海まで山より山までの人々汝に來り就ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'その日地はその居民の故によりて荒はつべし 是その行爲の果報なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, '汝の杖をもて汝の民即ち獨離れてカルメルの中の林にをる汝の產業の羊を牧養ひ之をして古昔の日のごとくバシヤンおよびギレアデにおいて草を食はしめたまへ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '汝がエジプトの國より出來し日のごとく我ふしぎなる事等を彼にしめさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, '國々の民見てその一切の能力を恥ぢその手を口にあてん その耳は聾となるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, '彼らは蛇のごとくに塵を餂め地に匍ふ者の如くにその城より振ひて出で戰慄て我らの神ヱホバに詣り汝のために懼れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, '何の神か汝に如ん 汝は罪を赦しその產業の遺餘者の愆を見過したまふなり 神は憐憫を悦ぶが故にその震怒を永く保ちたまはず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'ふたたび顧みて我らを憐み我らの愆を踏つけ我らの諸の罪を海の底に投しづめたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, '汝古昔の日われらの先祖に誓ひたりし其眞實をヤコブに賜ひ憐憫をアブラハムに賜はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'ニネベに關る重き預言 エルコシ人ナホムの異象の書');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'ヱホバは妬みかつ仇を報ゆる神 ヱホバは仇を報ゆる者また忿怒の主 ヱホバは己に逆らふ者に仇を報い己に敵する者にむかひて憤恨を含む者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'ヱホバは怒ることの遲く能力の大なる者 また罰すべき者をば必ず赦すことを爲ざる者 ヱホバの道は旋風に在り 大風に在り 雲はその足の塵なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, '彼海を指斥て之を乾かし河々をしてことごとく涸しむ バシヤンおよびカルメルの草木は枯れレバノンの花は凋む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, '彼の前には山々ゆるぎ嶺々溶く 彼の前には地墳上り世界およびその中に住む者皆ふきあげらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, '誰かその憤恨に當ることを得ん 誰かその燃る忿怒に堪ることを得ん 其震怒のそそぐこと火のごとし 巖も之がために裂く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'ヱホバは善なる者にして患難の時の要害なり 彼は己に倚賴む者を善知たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, '彼みなぎる洪水をもてその處を全く滅し己に敵する者を幽暗處に逐やりたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, '汝らヱホバに對ひて何を謀るや 彼全く滅したまふべし 患難かさねて起らじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, '彼等むすびからまれる荊棘のごとくなるとも酒に浸りをるとも乾ける藁のごとくに焚つくさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'ヱホバに對ひて惡事を謀る者一人汝の中より出て邪曲なる事を勸む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'ヱホバかく言たまふ 彼等全くしてその數夥多しかるとも必ず芟たふされて皆絶ん 我前にはなんぢを苦めたれども重て汝を苦めじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'いま我かれが汝に負せし軛を碎き汝の縛を切はなすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'ヱホバ汝の事につきて命令を下す 汝の名を負ふ者再び播るること有じ 汝の神々の室より我雕像および鑄像を除き絶べし 我汝の墓を備へん 汝輕ければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, '嘉音信を傳ふる者の脚山の上に見ゆ 彼平安を宣ぶ ユダよ汝の節筵を行ひ汝の誓願を果せ 邪曲なる者重て汝の中を通らざるべし 彼は全く絶る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, '撃破者攻のぼりて汝の前に至る 汝城を守り路を窺ひ腰を強くし汝の力を大に強くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'ヱホバはヤコブの榮を舊に復してイスラエルの榮のごとくしたまふ 其は掠奪者これを掠めその葡萄蔓を壞ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'その勇士は楯を紅にしその軍兵は紅に身を甲ふ 其行伍を立つる時には戰車の鐵灼燦て火のごとし 鎗また閃めきふるふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, '戰車街衢に狂ひ奔り大路に推あふ 其形状火炬のごとく其疾く馳すること電光の如し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, '彼その將士を憶ひいだす 彼らはその途にて躓き仆れその石垣に奔ゆき大楯を備ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, '河々の門啓け宮消うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'この事定まれり 彼は裸にせられて擄はれゆきその宮女胸を打て鴿のごとくに啼くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'ニネベはその建し日より以來水の滿る池に似たりしがその民今は逃奔る 止れ止れと呼ども後を顧みる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, '白銀を奪へよ 黄金を奪へよ その寳物限なく諸の貴とき噐用夥多し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, '滅亡たり 空虚なれり 荒果たり 心は消え膝は慄ひ腰には凡て劇しき痛あり 面はみな色を失ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, '獅子の穴は何處ぞや 少き獅子の物を食ふ處は何處ぞや 雄獅子雌獅子その小獅子とともに彼處に歩むに之を懼れしむる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, '雄獅子は小獅子のために物を噛ころし雌獅子の爲に物をくびり殺しその掠獲たる物をもて穴に充しその裂殺しし物をもて住所に滿す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, '萬軍のヱホバ言たまふ 視よ我なんぢに臨む 我なんぢの戰車を焚て煙となすべし 汝の少き獅子はみな劍の殺す所とならん 我また汝の獲物を地より絶べし 汝の使者の聲かさねて聞ゆること無らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, '禍なるかな血を流す邑 その中には全く詭譎および暴行充ち掠め取ること息まず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, '鞭の音あり輪の轟く音あり 馬は躍り跳ね車は輾り行く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, '騎兵馳のぼり劍きらめき鎗ひらめく 殺さるる者夥多しくして死屍山を爲し死骸限なし 皆死屍に躓きて倒る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, '是はかの魔術の主なる美しき妓女多く淫行を行ひその淫行をもて諸國を奪ひその魔術をもて諸族を惑したるに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, '萬軍のヱホバ言たまふ 視よ我なんぢに臨む 我なんぢの裳裾を掲げて面の上にまで及ぼし汝の陰所を諸民に見し汝の羞る所を諸國に見すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, '我また穢はしき物を汝の上に投かけて汝を辱しめ汝をして賽物とならしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, '凡て汝を見る者はみな汝を避て奔り去りニネベは亡びたりと言ん 誰か汝のために哀かんや 何處よりして我なんぢを弔ふ者を尋ね得んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, '汝あにノアモンに愈らんや ノアモンは河々の間に立ち水をその周圍に環らし海をもて壕となし海をもて垣となせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'かつその勢力たる者はエテオピア人およびエジプト人などにして限あらず フテ人ルビ人等汝を助けたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, '然るに是も俘囚となりて擄はれてゆきその子女は一切の衢の隅々にて投付られて碎け又その尊貴者は籤にて分たれ其大なる者はみな鏈に繋がれたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, '汝もまた酔せられて終に隱匿ん 汝もまた敵を避て逃るる處を尋ね求めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, '汝の城々はみな初に結びし果のなれる無花果樹のごとし 之を撼がせばその果落て食はんとする者の口にいる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, '汝の中にある民は婦人のごとし 汝の地の門はみな汝の敵の前に廣く開きてあり 火なんぢの關を焚ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, '汝水を汲て圍まるる時の用に備へ汝の城々を堅くし泥の中に入て踐て石灰を作りかつ瓦燒窰を修理へよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, '其處にて火汝を燒き劍なんぢを斬ん 其なんぢを滅すこと吸蝗のごとくなるべし 汝吸蝗のごとく數多からば多かれ 汝群蝗のごとく數多からば多かれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, '汝はおのれの商賣を空の星よりも多くせり 吸蝗掠めて飛さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, '汝の重臣は群蝗のごとく汝の軍長は蝗の群のごとし 寒き日には垣に巣窟を構へ日出きたれば飛て去る その在る處を知る者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'アッスリヤの王よ汝の牧者は睡り汝の貴族は臥す 又なんぢの民は山々に散さる 之を聚むる者なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, '汝の傷は愈ること無し 汝の創は重し 汝の事を聞およぶ者はみな汝の故によりて手を拍ん 誰か汝の惡行を恒に身に受ざる者やある');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, '預言者ハバククが示を蒙りし預言の重負');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'ヱホバよ我呼はるに汝の我に聽たまはざること何時までぞや 我なんぢにむかひて強暴を訴ふれども汝は助けたまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, '汝なにとて我に害惡を見せたまふや 何とて艱難を瞻望居たまふや 奪掠および強暴わが前に行はる且爭論あり鬪諍おこる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, '是によりて律法弛み公義正しく行はれず惡き者義しき者を圍むが故に公義曲りて行はる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, '汝ら國々の民の中を望み觀おどろけ駭け 汝らの日に我一の事を爲ん 之を告る者あるとも汝ら信ぜざらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, '視よ我カルデヤ人を興さんとす 是すなはち猛くまた荒き國人にして地を縦横に行めぐり 己の有ならざる住處を奪ふ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, '是は懼るべく又驚くべし 其是非威光は己より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'その馬は豹よりも迅く夜求食する豺狼よりも疾し 其騎兵は跑まはる 即ちその騎兵は遠き處より來る 其飛ことは物を食はんと急ぐ鷲のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, '是は全く強暴のために來り 其面を前にむけて頻に進むその俘虜を寄集むることは砂のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, '是は王等を侮り君等を笑ひ諸の城々を笑ひ土を積あげてこれを取ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, '斯て風のごとくに行めぐり進みわたりて罪を獲ん 是は己の力を神とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'ヱホバわが神わが聖者よ 汝は永遠より在すに非ずや 我らは死なじ ヱホバよ汝は是を審判のために設けたまへり 磐よ汝は是を懲戒のために立たまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, '汝は目清くして肯て惡を觀たまはざる者 肯て不義を視たまはざる者なるに何ゆゑ邪曲の者を觀すて置たまふや 惡き者を己にまさりて義しき者を呑噬ふに何ゆゑ汝默し居たまふや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, '汝は人をして海の魚のごとくならしめ君あらぬ昆蟲のごとくならしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, '彼鈎をもて之を盡く釣あげ網をもて之を寄せ集め引網をもて之を捕ふるなり 是に因て彼歡び樂しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, '是故に彼その網に犠牲を獻げその引網に香を焚く 其は之がためにその分肥まさりその食饒になりたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, '然ど彼はその網を傾けつつなほたえず國々の人を惜みなく殺すことをするならんか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, '我わが觀望所に立ち戍樓に身を置ん 而して我候ひ望みて其われに何と宣まふかを見 わが訴言に我みづから何と答ふべきかを見ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'ヱホバわれに答へて言たまはく 此默示を書しるして之を板の上に明白に鐫つけ奔りながらも之を讀むべからしめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'この默示はなほ定まれる時を俟てその終を急ぐなり 僞ならず 若し遲くあらば待べし 必ず臨むべし 濡滯りはせじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, '視よ彼の心は高ぶりその中にありて直からず 然ど義き者はその信仰によりて活べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'かの酒に耽る者は邪曲なる者なり 驕傲者にして安んぜず彼はその情慾を陰府のごとくに濶くす また彼は死のごとし 又足ことを知ず 萬國を集へて己に歸せしめ萬民を聚めて己に就しむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, '其等の民みな諺語をもて彼を評し嘲弄の詩歌をもて彼を諷せざらんや 即ち言ん己に屬せざる物を積累ぬる者は禍なるかな 斯て何の時にまでおよばんや 嗟かの質物の重荷を身に負ふ者よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, '汝を噬む者にはかに興らざらんや 汝を惱ます者醒出ざらんや 汝は之に掠めらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, '汝衆多の國民を掠めしに因てその諸の民の遺れる者なんぢを掠めん 是人の血を流ししに因る また強暴を地上に行ひて邑とその内に住る一切の者とに及ぼせしに因るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, '災禍の手を免れんが爲に高き處に巣を構へんとして己の家に不義の利を取る者は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, '汝は事を圖りて己の家に恥辱を來らせ衆多の民を滅して自ら罪を取れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, '石垣の石叫び建物の梁これに應へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, '血をもて邑を建て惡をもて城を築く者は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, '諸の民は火のために勞し諸の國人は虚空事のために疲る 是は萬軍のヱホバより出る者ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'ヱホバの榮光を認むるの知識地上に充て宛然海を水の掩ふが如くならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, '人に酒を飮せ己の忿怒を酌和へて之を酔せ而して之が陰所を見んとする者は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, '汝は榮譽に飽ずして羞辱に飽り 汝もまた飮て汝の不割禮を露はせ ヱホバの右の手の杯汝に巡り來るべし 汝は汚なき物を吐て榮耀を掩はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, '汝がレバノンに爲たる強暴と獣を懼れしめしその殲滅とは汝の上に報いきたるべし 是人の血を流ししに因りまた強暴を地上に行ひて邑とその内に住る一切の者とに及ぼししに因るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, '雕像はその作者これを刻みたりとて何の益あらんや 又鑄像および僞師は語はぬ偶像なればその像の作者これを作りて賴むとも何の益あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, '木にむかひて興ませと言ひ 語はぬ石にむかひて起たまへと言ふ者は禍なるかな 是あに敎晦を爲んや 視よ是は金銀に着せたる者にてその中には全く氣息なし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, '然りといへどもヱホバはその聖殿に在ますぞかし 全地その御前に默すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'シギヨノテに合せて歌へる預言者ハバククの祈禱');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'ヱホバよ我なんぢの宣ふ所を聞て懼る ヱホバよこの諸の年の中間に汝の運動を活齑かせたまへ 此諸の年の間に之を顯現したまへ 怒る時にも憐憫を忘れ給はざれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, '神テマンより來り聖者パラン山より臨みたまふ セラ 其榮光諸天を蔽ひ其讃美世界に徧ねし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'その朗耀は日のごとく光線その手より出づ 彼處はその權能の隱るる所なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, '疫病その前に先だち行き熱病その足下より出づ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, '彼立て地を震はせ觀まはして萬國を戰慄しめたまふ 永久の山は崩れ常磐の岡は陷る 彼の行ひたまふ道は永久なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, '我觀るにクシヤンの天幕は艱難に罹りミデアンの地の幃幕は震ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'ヱホバよ汝は馬を驅り汝の拯救の車に乗りたまふ 是河にむかひて怒りたまふなるか 河にむかひて汝の忿怒を發したまふなるか 海にむかひて汝の憤恨を洩し給ふなるか');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, '汝の弓は全く嚢を出で杖は言をもて言かためらる セラ 汝は地を裂て河となし給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, '山々汝を見て震ひ洪水溢れわたり淵聲を出してその手を高く擧ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, '汝の奔る矢の光のため汝の鎗の電光のごとき閃燦のために日月その住處に立とどまる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, '汝は憤ほりて地を行めぐり 怒りて國民を踏つけ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, '汝は汝の民を救んとて出きたり 汝の膏沃げる者を救はんとて臨みたまふ 汝は惡き者の家の頭を碎きその石礎を露はして頸におよぼし給へり セラ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, '汝は彼の鎗をもてその將帥の首を刺とほし給ふ 彼らは我を散さんとて大風のごとくに進みきたる 彼らは貧き者を密に呑ほろぼす事をもてその樂とす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, '汝は汝の馬をもて海を乗とほり大水の逆卷ところを渉りたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, '我聞て膓を斷つ 我唇その聲によりて震ふ 腐朽わが骨に入り我下體わななく 其は我患難の日の來るを待ばなり 其時には即ち此民に攻寄る者ありて之に押逼らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'その時には無花果の樹は花咲ず葡萄の樹には果ならず 橄欖の樹の產は空くなり 田圃は食糧を出さず圏には羊絶え小屋には牛なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, '然ながら我はヱホバによりて樂み わが拯救の神によりて喜ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, '主ヱホバは我力にして我足を鹿の如くならしめ 我をして我高き處を歩ましめ給ふ 伶長これを我琴にあはすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'アモンの子ユダの王ヨシヤの世にゼパニヤに臨めるヱホバの言 ゼパニヤはクシの子 クシはゲダリアの子 ゲダリアはアマリヤの子 アマリヤはヒゼキヤの子なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'ヱホバ言たまふ われ地の面よりすべての物をはらひのぞかん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'われ人と獣畜をほろぼし空の鳥 海の魚および躓礙になる者と惡人とを滅さん 我かならず地の面より人をほろぼし絶ん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, '我ユダとエルサレムの一切の居民との上に手を伸ん 我 この處よりかの漏のこれるバアルを絶ちケマリムの名を祭司と與に絶ち');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'また屋上にて天の衆軍を拜む者ヱホバに誓を立てて拜みながらも亦おのれの王を指て誓ふことをする者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'ヱホバに悖り離るる者ヱホバを求めず尋ねざる者を絶ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, '汝 主ヱホバの前に默せよ そはヱホバの日近づきヱホバすでに犠牲を備へその招くべき者をさだめ給ひたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'ヱホバの犠牲の日に我もろもろの牧伯と王の子等および凡て異邦の衣服を着る者を罰すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'その日には我また凡て閾をとびこえ強暴と詭譎をもて獲たる物をおのが主の家に滿す者等を罰せん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'ヱホバ曰たまはく その日には魚の門より號呼の聲おこり下邑より喚く聲おこり山々より大なる敗壞おこらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'マクテシの民よ汝ら叫べ 其は商賣する民 悉くほろび銀を擔ふ者 悉く絶たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'その時はわれ燈をもちてエルサレムの中を尋ねん 而して滓の上に居着て心の中にヱホバは福をもなさず災をもなさずといふものを罰すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'かれらの財寳は掠められ彼らの家は荒果ん かれら家を造るともその中に住ことを得ず 葡萄を植るともその葡萄酒を飮ことを得ざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'ヱホバの大なる日近づけり 近づきて速かに來る 聽よ是ヱホバの日なるぞ 彼處に勇士のいたく叫ぶあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'その日は忿怒の日 患難および痛苦の日 荒かつ亡ぶるの日 黑暗またをぐらき日 濃き雲および黑雲の日');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, '箛をふき鯨聲をつくり堅き城を攻め高き櫓を攻るの日なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'われ人々に患難を蒙らせて盲者のごとくに惑ひあるかしめん 彼らヱホバにむかひて罪を犯したればなり 彼らの血は流されて塵のごとくになり彼らの肉は捨られて糞土のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'かれらの銀も金もヱホバの烈き怒の日には彼らを救ふことあたはず 全地その嫉妬の火に呑るべし 即ちヱホバ地の民をことごとく滅したまはん 其事まことに速なるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, '汝等羞恥を知ぬ民早く自ら内に省みよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, '夫日は糠粃の如く過ぎさる 然ば詔言のいまだ行はれざる先ヱホバの烈き怒のいまだ汝等に臨まざる先ヱホバの忿怒の日のいまだ汝等にきたらざるさきに自ら省みるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'すべてヱホバの律法を行ふ斯地の遜るものよ 汝等ヱホバを求め公義を求め謙遜を求めよ 然すれば汝等ヱホバの忿怒の日に或は匿さるることあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, '夫ガザは棄られアシケロンは荒はてアシドドは白晝に逐はらはれエクロンは抜さらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, '海邊に住る者およびケレテの國民は禍なるかな ベリシテ人の國カナンよ ヱホバの言なんぢらを攻む 我なんぢを滅して住者なきに至らしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, '海邊は必ず牧塲となり牧者の洞および羊の牢そこに在ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, '此地はユダの家の殘餘れる者に歸せん 彼ら其處にて草飼ひ暮に至ればアシケロンの家に臥ん そは彼らの神ヱホバかれらを顧みその俘囚を歸したまふべければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, '我すでにモアブの嘲弄とアンモンの子孫の罵言を聞けり 彼らはわが民を嘲り自ら誇りて之が境界を侵せしなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, '是故に萬軍のヱホバ、イスラエルの神 言たまふ 我は活く 必ずモアブはソドムのごとくになりアンモンの子孫はゴモラのごとくにならん 是は共に蕁麻の蔓延る處となり鹽坑の地となりて長久に荒はつべし 我民の遺れる者かれらを掠めわが國民の餘されたる者かれらを獲ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'この事の彼らに臨むはその傲慢による 即ち彼ら萬軍のヱホバの民を嘲りて自ら誇りたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'ヱホバは彼等に對ひては畏ろしくましまし地の諸の神や饑し滅したまふなり 諸の國の民おのおのその處より出てヱホバを拜まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'エテオピア人よ汝等もまたわが劍にかかりて殺さる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'ヱホバ北に手を伸てアッスリヤを滅したまはん 亦ニネベを荒して荒野のごとき旱地となしたまはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, '而して畜の群もろもろの類の生物その中に伏し鸅鸕および刺猬其柱の頂に住み囀る者の聲窓の内にきこえ荒落たる物閾の上に積り香柏の板の細工露顯になるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, '是邑は驕り傲ぶりて安泰に立をり 唯我あり 我の外には誰もなしと心の中に言つつありし者なるが斯も荒はてて畜獣の臥す處となる者かな 此を過る者はみな嘶きて手をふるはん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, '此暴虐を行ふ悖りかつ汚れたる邑は禍なるかな');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, '是は聲を聽いれず敎晦を承ずヱホバに依賴まずおのれの神に近よらず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'その中にをる牧伯等は吼る獅子の如くその審士は明旦までに何をも遺さざる 夜求食する狼のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'その預言者は傲りかつ詐る人なり その祭司は聖物を汚し律法を破ることをなせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'その中にいますヱホバは義くして不義を行なひたまはず朝な朝な己の公義を顯して缺ることなし 然るに不義なる者は恥を知ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, '我國々の民を滅したればその櫓は凡て荒たり 我これが街を荒凉れしめたれば往來する者なし その邑々は滅びて人なく住む者なきに至れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'われ前に言り 汝ただ我を畏れまた警敎を受べし 然らばその住家は我が凡て之につきて定めたる所の如くに滅されざるべしと 然るに彼等は夙に起て己の一切の行状を壞れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'ヱホバ曰たまふ 是ゆゑに汝らわが起て獲物をする日いたるまで我を俟て 我もろもろの民を集へ諸の國を聚めてわが憤恨とわが烈き忿怒を盡くその上にそそがんと思ひ定む 全地はわが嫉妬の火に燒ほろぼさるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'その時われ國々の民に清き唇をあたへ彼らをして凡てヱホバの名を呼しめ心をあはせて之につかへしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'わが散せし者等の女即ち我を拜む者エテオピアの河々の彼旁よりもきたりて我に禮ものをささぐべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'その日には汝われに對てをかしきたりし諸の行爲をもて羞を得ことなかるべし その時には我なんぢの中より高ぶり樂む者等を除けば汝かさねてわが聖山にて傲り高ぶることなければなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'われ柔和にして貧き民をなんぢの中にのこさん 彼らはヱホバの名に依賴むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'イスラエルの遺れる者は惡を行はず 謊をいはず その口のうちには詐僞の舌なし 彼らは草食ひ臥やすまん 之を懼れしむる者なかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'シオンの女よ歡喜の聲を擧よ イスラエルよ樂み呼はれ エルサレムの女よ心のかぎり喜び樂め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'ヱホバすでに汝の鞫を止め汝の敵を逐はらひたまへり イスラエルの王ヱホバ汝の中にいます 汝はかさねて災禍にあふことあらじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'その日にはエルサレムに向ひて言あらん 懼るるなかれ シオンよ 汝の手をしなえ垂るるなかれと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'なんぢの神ヱホバなんぢの中にいます 彼は拯救を施す勇士なり 彼なんぢのために喜び樂み愛の餘りに默し汝のために喜びて呼はりたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'われ節會のことにつきて憂ふるものを集めん 彼等は汝より出し者なり 恥辱かれらに蒙むること重負のごとし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, '視よその時われ汝を虐遇る者を盡く處置し足蹇たるものを救ひ逐はなたれたる者を集め彼らをして其羞辱を蒙りし一切の國にて稱譽を得させ名を得さすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'その時われ汝らを携へその時われ汝らを集むべし 我なんぢらの目の前において汝らの俘囚をかへし汝らをして地上の萬國に名を得させ稱譽を得さすべし ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'ダリヨス王の二年六月其月の一日にヱホバの言預言者ハガイによりてシヤルテルの子ユダの方伯ゼルバベルおよびヨザダクの子 祭司の長ヨシユアに臨めりいはく');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '萬軍のヱホバかくいひたまふ是民はヱホバの殿を建べき時期未だ來らずといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'ヱホバの言また預言者ハガイによりて臨めり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '此殿かく毀壞をれば汝等板をもてはれる家に居るべき時ならんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'されば今萬軍のヱホバかく曰たまふ 汝等おのれの行爲を省察べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, '汝らは多く播ども収入るところは少く食へども飽ことを得ず 飮ども滿足ことを得ず 衣れども暖きことを得ず 又工價を得るものは之を破れたる袋に入る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, '萬軍のヱホバまた曰たまふ 汝等おのれの行爲を省察べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, '山に上り木を携へ來て殿を建てよ さすれば我これを悦び又榮光を受ん ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'なんぢら多く得んと望みたりしに反て少かりき 又汝等これを家に携へ歸りしとき我これを吹はらへり 萬軍のヱホバいひたまふ 是何故ぞや 是は我が殿破壞をるに汝等おのおの己の室に走り至ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'この故になんぢらの上の天は雨露を止め地はその產物を止めたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, '且われ地にも山にも穀物にも新酒にも油にも地の生ずる物にも人にも家畜にも手のもろもろの工にもすべて毀壞を召きかうむらしめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'シヤルテルの子ゼルバベルとヨザダクの子祭司の長ヨシユアおよびその殘れるすべての民ともに其神ヱホバの聲と預言者ハガイの言に聽したがへり 是は其神ヱホバかれを遣したまひしに因る 民みなヱホバの前に敬畏たり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, '時にヱホバの使者ハガイ、ヱホバの命により民に告て曰けるは我なんぢらと偕に在りとヱホバ曰たまふと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'ヱホバ、シヤルテルの子ユダの方伯ゼルバベルの心とヨザダクの子 祭司の長ヨシユアの心およびその殘れるすべての民の心をふりおこしたまひければ彼等來りて其神萬軍のヱホバの殿にて工作を爲り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'これダリヨス王の二年六月二十四日なりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, '七月其月の二十一日ヱホバの言預言者ハガイによりて臨めり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'シヤルテルの子ユダの方伯ゼルバベルとヨザダクの子祭司の長ヨシユアおよびその殘れる一切の民に告よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'なんぢら遺れる者の中この殿の從前の榮光を見しものは誰ぞや 今これを如何に見るや かの殿にくらぶれば是は汝らの目に何もなきが如く見ゆるにあらずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'ヱホバ曰たまふゼルバベルよ自ら強くせよ ヨザダクの子祭司の長ヨシユアよ自ら強くせよ ヱホバ言たまふ この地の民よ自らつよくしてはたらけ 我なんぢらとともに在り 萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, '汝らがエジプトよりいでし時わがなんぢらに約せし言およびわが靈なほなんぢらの中に留れり 懼るるなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, '萬軍のヱホバかくいひたまふ いま一度しばらくありてわれ天と地と海と陸とを震動はん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, '又われ萬國を震動はん また萬國の願ふところのもの來らん 又われ榮光をもてこの殿に充滿さん 萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, '銀も我ものなり 金もわが物なりと萬軍のヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'この殿の後の榮光は從前の榮光より大ならんと萬軍のヱホバいひたまふ この處においてわれ平康をあたへんと萬軍のヱホバいひたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'ダリヨスの二年九月二十四日ヱホバのことば預言者ハガイによりて臨めり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '萬軍のヱホバかく曰たまふ 律法につきて祭司に問ふて曰ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, '人衣の裾にて聖肉を携へたらんにその裾もしパン或は羮あるひは酒あるひは油あるひは他の食物に捫らばそれらは聖ものとなるや 祭司たち答へて曰けるはしからず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'ハガイまたいひけるは屍體に捫りて汚れしもの若これらの物にさはらば其ものはけがるべきや 祭司等こたへて曰けるは汚れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'ここに於てハガイ答へて曰けるはヱホバ曰たまふ 我前此民もかくの如くまた此國もかくの如し 又其手の一切のわざもかくのごとく彼等がその處に獻ぐるものもけがれたるものなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'また今われ汝らに乞 この日より以前すなはちヱホバの殿にて石の上に石の置れざりし時を憶念べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'かの時には二十舛もあるべき麥束につきてわづかに十を得 また酒榨につきて五十桶汲んとせしにただ二十を得たるのみ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, '汝が手をもて爲せる一切の事に於てわれ不實穗と朽腐穗と雹を以てなんぢらを撃り されど汝ら我にかへらざりき ヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'なんぢらこの日より以前を憶念みよ 即ち九月二十四日よりヱホバの殿の基を置し日までをおもひ見よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, '種子なほ倉にあるや 葡萄の樹 無花果の樹 石榴の樹 橄欖の樹もいまだ實を結ばざりき 此日よりのちわれ汝らを惠まん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, '此月の二十四日にヱホバのことば再びハガイに臨めり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'ユダの方伯ゼルバベルに告よ われ天地を震動ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, '列國の位を倒さん また異邦の諸國の權勢を滅さん 又車および之に駕る者を倒さん 馬および之に騎る者もおのおの其伴侶の劍によりてたふれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, '萬軍のヱホバ曰たまはくシヤルテルの子わが僕ゼルバベルよヱホバいふその日に我なんぢを取りなんぢを印の如くにせん そはわれ汝をえらびたればなり 萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'ダリヨスの二年八月のヱホバの言イドの子ベレキヤの子なる預言者ゼカリヤに臨めり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'ヱホバいたく汝らの父等を怒りたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, '萬軍のヱホバかく言ふと汝かれらに告よ萬軍のヱホバ言ふ汝ら我に歸れ萬軍のヱホバいふ我も汝らに歸らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, '汝らの父等のごとくならざれ前の預言者等かれらに向ひて呼はりて言り萬軍のヱホバかく言たまふ請ふ汝らその惡き道を離れその惡き行を棄てて歸れと然るに彼等は聽ず耳を我に傾けざりきヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, '汝らの父等は何處にありや預言者たち永遠に生んや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, '然ながら我僕なる預言者等に我が命じたる吾言とわが法度とは汝らの父等に追及たるに非ずや然ゆゑに彼らかへりて言り萬軍のヱホバ我らの道に循ひ我らの行に循ひて我らに爲んと思ひたまひし事を我らに爲たまへりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'ダリヨスの二年十一月すなはちセバテといふ月の二十四日にヱホバの言イドの子ベレキヤの子なる預言者ゼカリヤに臨めり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, '我夜觀しに一箇の人赤馬に乗て谷の裏なる鳥拈樹の中に立ちその後に赤馬駁馬白馬をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, '我わが主よ是等は何ぞやと問けるに我と語ふ天の使われにむかひて是等の何なるをわれ汝に示さんと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, '鳥拈樹の中に立る人答へて言けるは是等は地上を遍く歩かしめんとてヱホバの遣したまひし者なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, '彼ら答へて鳥拈樹の中に立るヱホバの使に言けるは我ら地上を行めぐり觀しに全地は穩にして安し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'ヱホバの使こたへて言ふ萬軍のヱホバよ汝いつまでヱルサレムとユダの邑々を恤みたまはざるか汝はこれを怒りたまひてすでに七十年になりぬと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'ヱホバ我と語ふ天の使に嘉事慰事をもて答へたまへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'かくて我と語ふ天の使我に言けるは汝呼はりて言へ萬軍のヱホバかく言たまふ我ヱルサレムのためシオンのために甚だしく心を熱して嫉妬おもひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, '安居せる國々の民を太く怒る其は我すこしく怒りしに彼ら力を出して之に害を加へたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'ヱホバかく言ふ是故に我憐憫をもてヱルサレムに歸る萬軍のヱホバのたまふ我室その中に建られ量繩ヱルサレムに張られん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, '汝また呼はりて言へ萬軍のヱホバかく宣ふ我邑々には再び嘉物あふれんヱホバふたたびシオンを慰め再びヱルサレムを簡びたまふべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'かくて我目を擧て觀しに四の角ありければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, '我に語ふ天の使に是等は何なるやと問しに彼われに答へけるは是等はユダ、イスラエルおよびヱルサレムを散したる角なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, '時にヱホバ四箇の鍛冶を我に見し給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, '我是等は何を爲んとて來れるやと問しに斯こたへ給へり是等の角はユダを散して人にその頭を擧しめざりし者なるが今この四箇の者來りて之を威しかのユダの地にむかひて角を擧て之を散せし諸國の角を擲たんとす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, '茲に我目を擧て觀しに一箇の人量繩を手に執居ければ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, '汝は何處へ往くやと問しにヱルサレムを量りてその廣と長の幾何なるを觀んとすと我に答ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, '時に我に語ふ天の使出行たりしが又一箇の天の使出きたりて之に會ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, '之に言けるは走ゆきてこの少き人に告て言へヱルサレムはその中に人と畜と饒なるによりて野原のごとくに廣く亘るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'ヱホバ言たまふ我その四周にて火の垣となりその中にて榮光とならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'ヱホバいひたまふ來れ來れ北の地より逃きたれ我なんぢらを四方の天風のごとくに行わたらしむればなりヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, '來れバビロンの女子とともに居るシオンよ遁れ來れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, '萬軍のヱホバかく言たまふヱホバ汝等を擄へゆきし國々へ榮光のために我儕を遣したまふ汝らを打つ者は彼の目の珠を打なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, '即ち我手をかれらの上に搖ん彼らは己に事へし者の俘虜となるべし汝らは萬軍のヱホバの我を遣したまへるなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'ヱホバ言たまふシオンの女子よ喜び樂め我きたりて汝の中に住ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'その日には許多の民ヱホバに附て我民とならん我なんぢの中に住べし汝は萬軍のヱホバの我を遣したまへるなるを知ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'ヱホバ聖地の中にてユダを取て己の分となし再びヱルサレムを簡びたまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'ヱホバ起てその聖住所よりいでたまへば凡そ血肉ある者ヱホバの前に粛然たれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, '彼祭司の長ヨシユアがヱホバの使の前に立ちサタンのその右に立てこれに敵しをるを我に見す');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'ヱホバ、サタンに言たまひけるはサタンよヱホバ汝をせむべし即ちヱルサレムを簡びしヱホバ汝をいましむ是は火の中より取いだしたる燃柴ならずやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'ヨシユア汚なき衣服を衣て使の前に立をりしが');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'ヱホバ己の前に立る者等に告て汚なき衣服を之に脱せよと宣ひまたヨシユアに向ひて觀よ我なんぢの罪を汝の身より取のぞけり汝に美服を衣すべしと宣へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, '我また潔き冠冕をその首に冠らせよと言り是において潔き冠冕をその首に冠らせ衣服をこれに衣すヱホバの使は立をる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'ヱホバの使證してヨシユアに言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '萬軍のヱホバかく言たまふ汝もし我道を歩みわが職守を守らば我家を司どり我庭を守ることを得ん我また此に立る者等の中に往來する路を汝に與ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, '祭司の長ヨシユアよ請ふ汝と汝の前に坐する汝の同僚とともに聽べし彼らは即ち前表となるべき人なり我かならず我僕たる枝を來らすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'ヨシユアの前に我が立るところの石を視よ此一箇の石の上に七箇の目あり我自らその彫刻をなす萬軍のヱホバこれを言ふなり我この地の罪を一日の内に除くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, '萬軍のヱホバ言たまふ其日には汝等おのおの互に相招きて葡萄の樹の下無花果の樹の下にあらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, '我に語へる天の使また來りて我を呼醒せり我は睡れる人の呼醒されしごとくなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, '彼我にむかひて汝何を見るやと言ければ我いへり我觀に惣金の燈臺一箇ありてその頂に油を容る噐ありまた燈臺の上に七箇の燭盞ありその燭盞は燈臺の頂にありて之に各七本づつの管あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'また燈臺の側に橄欖の樹二本ありて一は油を容る噐の右にあり一はその左にあり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, '我答へて我と語ふ天の使の問言けるは我主よ是等は何ぞやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, '我と語ふ天の使我に答へて汝是等の何なるを知ざるかと言しにより我主よ知ずとわれ言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, '彼また答へて我に言けるはゼルバベルにヱホバの告たまふ言は是のごとし萬軍のヱホバ宣ふ是は權勢に由らず能力に由らず我靈に由るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'ゼルバベルの前にあたれる大山よ汝は何者ぞ汝は平地とならん彼は恩惠あれ之に恩惠あれと呼はる聲をたてて頭石を曳いださん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'ヱホバの言われに臨めり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'ゼルバベルの手この室の石礎を置たり彼の手これを成終ん汝しらん萬軍のヱホバ我を汝等に遣したまひしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, '誰か小き事の日を藐視むる者ぞ夫の七の者は遍く全地に往來するヱホバの目なり準繩のゼルバベルの手にあるを見て喜ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, '我また彼に問て燈臺の右左にある此二本の橄欖の樹は何なるやと言ひ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, '重ねてまた彼に問て此二本の金の管によりて金の油をその中より斟ぎ出す二枝の橄欖は何ぞやと言しに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, '彼われに答へて汝是等の何なるを知ざるかと言ければ我主よ知ずと言けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, '彼言らく是等は油の二箇の子にして全地の主の前に立つ者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, '我また目を擧て觀しに卷物の飛あり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, '彼われに汝何を見るやと言ければ我言ふ我卷物の飛ぶを見る其長は二十キユビトその寛は十キユビト');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, '彼またわれに言けるは是は全地の表面を往めぐる呪詛の言なり凡て竊む者は卷物のこの面に照して除かれ凡て誓ふ者は卷物の彼の面に照して除かるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, '萬軍のヱホバのたまふ我これを出せり是は竊盗者の家に入りまた我名を指て僞り誓ふ者の家に入てその家の中に宿りその木と石とを並せて盡く之を燒べしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, '我に語へる天の使進み來りて我に言けるは請ふ目を擧てこの出きたれる物の何なるを見よ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'これは何なるやと我言ければ彼言ふ此出來れる者はエパ舛なり又言ふ全地において彼等の形状は是のごとしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'かくて鉛の圓き蓋を取あぐれば一人の婦人エパ舛の中に坐し居る');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, '彼是は罪惡なりと言てその婦人をエパ舛の中に投いれ鉛の錘をその舛の口に投かぶらせたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, '我また目を擧て觀しに婦人二人出きたれり之に鶴の翼のごとき翼ありてその翼風を含む彼等そのエパ舛を天地の間に持擧ぐ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, '我すなはち我に語ふ天の使にむかひて彼等エパ舛を何處へ携へゆくなるやと言けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, '彼我に言ふシナルの地にて之がために家を建んとてなり是は彼處に置られてその臺の上に立ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, '我また目を擧て觀しに四輌の車二の山の間より出きたれりその山は銅の山なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, '第一の車には赤馬を着け第二の車には黑馬を着け');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, '第三の車には白馬を着け第四の車には白點なる強馬を着く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, '我すなはち我に語ふ天の使に問て我主よ是等は何なるやと言けるに');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, '天の使こたへて我に言ふ是は四の天風にして全地の主の前より罷り出たる者なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, '黑馬は北の地をさして進み行き白馬その後に從ふ又白點馬は南の地をさして進みゆき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, '強馬は進み出て地を徧く行めぐらんとす彼汝ら往き地を徧くめぐれと言たまひければ則ち地を行めぐれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, '彼われを呼て我に告て言ふこの北の地に往る者等は北の地にて我靈を安んず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'ヱホバの言われに臨めり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '汝かの囚虜人の中の者ヘルダイ、トビヤおよびヱダヤより取ことをせよ即ちその日に汝かれらがバビロンより歸りて宿りをるゼパニヤの子ヨシヤの家に到り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, '金銀を取て冠冕を造りヨザダクの子なる祭司の長ヨシユアの首にこれを冠らせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, '彼に語りて言べし萬軍のヱホバ斯言たまふ視よ人ありその名を枝といふ彼おのれの處より生いでてヱホバの宮を建ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, '即ち彼者ヱホバの宮を建て尊榮を帶びその位に坐して政事を施しその位にありて祭司とならん此二の者の間に平和の計議あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, '偖またその冠冕はヘレム、トビヤ、ユダヤおよびゼパニヤの子ヘンの記念のために之をヱホバの殿に納むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, '遠き處の者等來りてヱホバの殿を建ん而して汝らは萬軍のヱホバの我を遣したまひしなるを知にいたらん汝らもし汝らの神ヱホバの聲に聽したがはば是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'ダリヨス王の四年の九月すなはちキスリウといふ月の四日にヱホバの言ゼカリヤに臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'ベテルかの時シヤレゼル、レゲンメレクおよびその從者を遣してヱホバを和めさせ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'かつ萬軍のヱホバの室にをる祭司に問しめ且預言者に問しめて言けらく我今まで年久しく爲きたりしごとく尚五月をもて哭きかつ齋戒すべきやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'ここにおいて萬軍のヱホバの言我に臨めり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '國の諸民および祭司に告て言へ汝らは七十年のあひだ五月と七月とに斷食しかつ哀哭せしがその斷食せし時果して我にむかひて斷食せしや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, '汝ら食ひかつ飮は全く己のために食ひ己のために飮ならずや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, '在昔ヱルサレムおよび周圍の邑々人の住ふありて平安なりし時南の地および平野にも人の住ひをりし時に已往の預言者によりてヱホバの宣ひたりし言を汝ら知ざるや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'ヱホバの言ゼカリヤに臨めり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '萬軍のヱホバかく宣へり云く正義き審判を行ひ互に相愛しみ相憐め');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, '寡婦孤兒旅客および貧者を虐ぐるなかれ人を害せんと心に圖る勿れと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, '然るに彼等は肯て耳を傾けず背を向け耳を鈍くして聽ず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, '且その心を金剛石のごとくし萬軍のヱホバがその御霊をもて已往の預言者に由て傳へたまひし律法と言詞に聽したがはざりき是をもて大なる怒萬軍のヱホバより出て臨めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, '彼かく呼はりたれども彼等聽ざりき其ごとく彼ら呼はるとも我聽じ萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, '我かれらをその識ざる諸の國に吹散すべし其後にてこの地は荒て往來する者なきに至らん彼等かく美しき國を荒地となす');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, '萬軍のヱホバの言われに臨めり曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '萬軍のヱホバかく言たまふ我シオンのために甚だしく心を熱して妬く思ひ大なる忿怒を起して之がために妬く思ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'ヱホバかく言たまふ今我シオンに歸れり我ヱルサレムの中に住んヱルサレムは誠實ある邑と稱へられ萬軍のヱホバの山は聖山と稱へらるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, '萬軍のヱホバかく言たまふヱルサレムの街衢には再び老たる男老たる女坐せん皆年高くして各々杖を手に持べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'またその邑の街衢には男の兒女の兒滿て街衢に遊び戯れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, '萬軍のヱホバかく言たまふこの事その日には此民の遺餘者の目に奇といふとも我目に何の奇きこと有んや萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, '萬軍のヱホバかく言たまふ視よ我わが民を日の出る國より日の入る國より救ひ出し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'かれらを携へ來りてヱルサレムの中に住しめん彼らは我民となり我は彼らの神となりて共に誠實と正義に居ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, '萬軍のヱホバかく言たまふ汝ら萬軍のヱホバの室なる殿を建んとて其基礎を置たる日に起りし預言者等の口の言詞を今日聞く者よ汝らの腕を強くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, '此日の先には人も工の價を得ず獸畜も工の價を得ず出者も入者も仇の故をもて安然ならざりき即ち我人々をして互に相攻しめたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, '然れども今は我此民の遺餘者に對すること曩の日の如くならずと萬軍のヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, '即ち平安の種子あるべし葡萄の樹は果を結び地は產物を出し天は露を與へん我この民の遺餘者にこれを盡く獲さすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'ユダの家およびイスラエルの家よ汝らが國々の中に呪詛となりしごとく此度は我なんぢらを救ふて祝言とならしめん懼るる勿れ汝らの腕を強くせよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, '萬軍のヱホバかく言たまふ在昔汝らの先祖我を怒らせし時に我これに災禍を降さんと思ひて之を悔ざりき萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, '是のごとく我また今日ヱルサレムとユダの家に福祉を降さんと思ふ汝ら懼るる勿れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, '汝らの爲べき事は是なり汝ら各々たがひに眞實を言べし又汝等の門にて審判する時は眞實を執て平和の審判を爲べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, '汝等すべて人の災害を心に圖る勿れ僞の誓を好む勿れ是等はみな我が惡む者なりとヱホバ言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, '萬軍のヱホバの言われに臨めり云く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '萬軍のヱホバかく言たまふ四月の斷食五月の斷食七月の斷食十月の斷食かへつてユダの家の宴樂となり欣喜となり佳節となるべし惟なんぢら眞實と平和を愛すべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, '萬軍のヱホバかく言たまふ國々の民および衆多の邑の居民來り就ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, '即ちこの邑の居民往てかの邑の者に向ひ我儕すみやかに往てヱホバを和め萬軍のヱホバを求めんと言んに我も往べしと答へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, '衆多の民強き國民ヱルサレムに來りて萬軍のヱホバを求めヱホバを和めん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, '萬軍のヱホバかく言たまふ其日には諸の國語の民十人にてユダヤ人一箇の裾を拉へん即ち之を拉へて言ん我ら汝らと與に往べし其は我ら神の汝らと偕にいますを聞たればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'ヱホバの言詞の重負ハデラクの地に臨むダマスコはその止る所なりヱホバ世の人を眷みイスラエルの一切の支派を眷みたまへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, '之に界するハマテも然りツロ、シドンも亦はなはだ怜悧ければ同じく然るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'ツロは自己のために城郭を構へ銀を塵のごとくに積み金を街衢の土のごとくに積めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, '視よ主これを攻取り海にて之が力を打ほろぼしたまふべし是は火にて焚うせん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'アシケロンこれを見て懼れガザもこれを見て太く慄ふエクロンもその望む所の者辱しめらるるに因て亦然りガザには王絶えアシケロンには住者なきに至らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'アシドドにはまた雑種の民すまん我ペリシテ人が誇る所の者を絶べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, '我これが口より血を取除き之が齒の間より憎むべき物を取除かん是も遺りて我儕の神に歸しユダの牧伯のごとくに成べしまたエクロンはヱブス人のごとくになるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, '我わが家のために陣を張て敵軍に當り之をして往來すること無らしめん虐遇者かさねて逼ること無るべし我いま我目をもて親ら見ればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'シオンの女よ大に喜べヱルサレムの女よ呼はれ視よ汝の王汝に來る彼は正義して拯救を賜り柔和にして驢馬に乗る即ち牝驢馬の子なる駒に乗るなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, '我エフライムより車を絶ちヱルサレムより馬を絶ん戰爭弓も絶るべし彼國々の民に平和を諭さん其政治は海より海に及び河より地の極におよぶべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, '汝についてはまた汝の契約の血のために我かの水なき坑より汝の被俘人を放ち出さん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, '望を懷く被俘人よ汝等城に歸れ我今日もなほ告て言ふ我かならず倍して汝等に賚ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, '我ユダを張て弓となしエフライムを矢となして之につがへんシオンよ我汝の人々を振起してギリシヤの人々を攻しめ汝をして大丈夫の劍のごとくならしむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'ヱホバこれが上に顯れてその箭を電光のごとくに射いだしたまはん主ヱホバ喇叭を吹ならし南の暴風に乗て出來まさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, '萬軍のヱホバ彼らを護りたまはん彼等は食ふことを爲し投石器の石を踏つけん彼等は飮ことを爲し酒に醉るごとくに聲を擧ん其これに盈さるることは血を盛る鉢のごとく祭壇の隅のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, '彼らの神ヱホバ當日に彼らを救ひその民を羊のごとくに救ひたまはん彼等は冠冕の玉のごとくになりて其地に輝くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'その福祉は如何計ぞや其美麗は如何計ぞや穀物は童男を長ぜしめ新酒は童女を長ぜしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, '汝ら春の雨の時に雨をヱホバに乞へヱホバは電光を造り大雨を人々に賜ひ田野において草蔬を各々に賜ふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, '夫テラピムは空虚き事を言ひ卜筮師はその見る所眞實ならずして虚僞の夢を語る其慰むる所は徒然なり是をもて民は羊のごとくに迷ひ牧者なきに因て惱む');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, '我牧者にむかひて怒を發す我牡山羊を罰せん萬軍のヱホバその群なるユダの家を顧み之をしてその美しき軍馬のごとくならしめたまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, '隅石彼より出で釘かれより出で軍弓かれより出で宰たる者みな齊く彼より出ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, '彼等戰ふ時は勇士のごとくにして街衢の泥の中に敵を蹂躙らんヱホバかれらとともに在せば彼ら戰はん馬に騎れる者等すなはち媿を抱くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, '我ユダの家を強くしヨセフの家を救はん我かれらを恤むが故に彼らをして歸り住しめん彼らは我に棄られし事なきが如くなるべし我は彼らの神ヱホバなり我かれらに聽べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'エフライム人は勇士に等しくして酒を飮たるごとく心に歡ばん其子等は見て喜びヱホバに因て心に樂しまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, '我かれらに向ひて嘯きて之を集めん其は我これを贖ひたればなり彼等は昔殖増たる如くに殖増ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, '我かれらを國々の民の中に捲ん彼等は遠き國において我をおぼへん彼らは其子等とともに生ながらへて歸り來るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, '我かれらをエジプトの國より携へかへりアッスリヤより彼等を集めギレアデの地およびレバノンに彼らを携へゆかんその居處も無きほどなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, '彼艱難の海を通り海の浪を撃破りたまふナイルの淵は盡く涸るアッスリヤの傲慢は卑くせられエジプトの杖は移り去ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, '我彼らをしてヱホバに由て強くならしめん彼等はヱホバの名をもて歩まんヱホバこれを言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'レバノンよ汝の門を啓き火をして汝の香柏を焚しめよ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, '松よ叫べ香柏は倒れ威嚴樹はそこなはれたりバシヤンの橡よ叫べ高らかなる林は倒れたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, '牧者の叫ぶ聲あり其榮そこなはれたればなり猛き獅子の吼る聲ありヨルダンの叢そこなはれたればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, '我神ヱホバかく言たまふ宰らるべき羔を牧へ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, '之を買ふ者は之を宰るとも罪なし之を賣る者は言ふ我富を得ればヱホバを祝すべしと其牧者もこれを惜まざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'ヱホバ言たまふ我かさねて地の居民を惜まじ視よ我人を各々その隣人の手に付しその王の手に付さん彼ら地を荒すべし我これを彼らの手より救ひ出さじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, '我すなはち其宰らるべき羊を牧り是は最も憫然なる羊なり我みづから二本の杖を取り一を恩と名け一を結と名けてその羊を牧り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, '我一月に牧者三人を絶り我心に彼らを厭ひしが彼等も心に我を惡めり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, '我いへり我は汝らを飼はじ死る者は死に絶るる者は絶れ遺る者は互にその肉を食ひあふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, '我恩といふ杖を取て之を折れり是諸の民に立し我契約を廢せんとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, '是は其日に廢せられたり是に於てかの我に聽したがひし憫然なる羊は之をヱホバの言なりしと知れり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, '我彼らに向ひて汝等もし善と視なば我價を我に授けよ若しからずば止めよと言ければ彼等すなはち銀三十を權りて我價とせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'ヱホバ我に言たまひけるは彼等に我が估價せられしその善價を陶人に投あたへよと我すなはち銀三十を取てヱホバの室に投いれて陶人に歸せしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, '我また結といふ杖を折れり是ユダとイスラエルの間の和好を絶んとてなりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'ヱホバ我に言たまはく汝また愚なる牧者の器を取れ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, '視よ我地に一人の牧者を興さん彼は亡ぶる者を顧みず迷へる者を尋ねず傷つける者を醫さず健剛なる者を飼はず肥たる者の肉を食ひ且その蹄を裂ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, '其羊の群を棄る惡き牧者は禍なるかな劍その腕に臨みその右の目に臨まん其腕は全く枯えその右の目は全く盲れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'イスラエルにかかはるヱホバの言詞の重負 ヱホバ即ち天を舒べ地の基を置ゑ人のうちの靈魂を造る者言たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, '視よ我ヱルサレムをしてその周圍の國民を蹌踉はする杯とならしむべしヱルサレムの攻圍まるる時是はユダにも及ばん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, '其日には我ヱルサレムをして諸の國民に對ひて重石とならしむべし之を持擧る者は大傷を受ん地上の諸國みな集りて之に攻寄べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'ヱホバ言たまふ當日には我一切の馬を撃て駭かせその騎手を撃て狂はせん而して我ユダの家の上に我目を開き諸の國民の馬を撃て盲になすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'ユダの牧伯等その心の中に謂んヱルサレムの居民はその神萬軍のヱホバに由て我力となるべしと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, '當日には我ユダの牧伯等をして薪の下にある火盤のごとく麥束の下にある炬火のごとくならしむべし彼等は右左にむかひその周圍の國民を盡く焚んヱルサレム人はなほヱルサレムにてその本の處に居ことを得べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'ヱホバまづユダの幕屋を救ひたまはん是ダビデの家の榮およびヱルサレムの居民の榮のユダに勝ること無らんためたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, '當日ヱホバ、ヱルサレムの居民を護りたまはん彼らの中の弱き者もその日にはダビデのごとくなるべしまたダビデの家は神のごとく彼らに先だつヱホバの使のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'その日には我ヱルサレムに攻きたる國民をことごとく滅すことを務むべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, '我ダビデの家およびヱルサレムの居民に恩惠と祈禱の靈をそそがん彼等はその刺たりし我を仰ぎ觀獨子のため哭くがごとく之がために哭き長子のために悲しむがごとく之がために痛く悲しまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'その日にはヱルサレムに大なる哀哭あらん是はメギドンの谷なるハダデリンモンに在し哀哭のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, '國中の族おのおの別れ居て哀哭べし即ちダビデの族別れ居て哀哭きその妻等別れ居て哀哭きナタンの家の族別れ居て哀哭きその妻等別れ居て哀哭かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'レビの家の族別れ居て哀哭きその妻等別れ居て哀哭きシメイの族別れ居て哀哭きその妻等わかれ居て哀哭かん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'その他の族も凡て然りすなはち族おのおの別れ居て哀哭きその妻等別れ居て哀哭くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'その日罪と汚穢を清むる一の泉ダビデの家とヱルサレムの居民のために開くべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, '萬軍のヱホバ言たまふ其日には我地より偶像の名を絶のぞき重て人に記憶らるること無らしむべし我また預言者および汚穢の靈を地より去しむべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, '人もしなほ預言することあらば其生の父母これに言ん汝は生べからず汝はヱホバの名をもて虚僞を語るなりと而してその生の父母これが預言しをるを刺ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'その日には預言者等預言するに方りてその異象を羞ん重て人を欺かんために毛衣を纒はじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, '彼言ん我は預言者にあらず地を耕へす者なり即ち我は若き時より人に買れたりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, '若これに向ひて然らば汝の兩手の間の傷は何ぞやと言あらば是は我が愛する者の家にて受たる傷なりと答へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, '萬軍のヱホバ言たまふ劍よ起て我牧者わが伴侶なる人を攻よ牧者を撃て然らばその羊散らん我また我手を小き者等の上に伸べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'ヱホバ言たまふ全地の人二分は絶れて死に三分の一はその中に遺らん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, '我その三分の一を携へて火にいれ銀を熬分るごとくに之を熬分け金を試むるごとくに之を試むべし彼らわが名を呼ん我これにこたへん我これは我民なりと言ん彼等またヱホバは我神なりと言ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, '視よヱホバの日來る汝の貨財奪はれて汝の中にて分たるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, '我萬國の民を集めてヱルサレムを攻撃しめん邑は取られ家は掠められ婦女は犯され邑の人は半は擄へられてゆかん然どその餘の民は邑より絶れじ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'その時ヱホバ出きたりて其等の國人を攻撃たまはん在昔その軍陣の日に戰ひたまひしごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, '其日にはヱルサレムの前に當りて東にあるところの橄欖山の上に彼の足立たん而して橄欖山その眞中より西東に裂て甚だ大なる谷を成しその山の半は北に半は南に移るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, '汝らは我山の谷に逃いらん其山の谷はアザルにまで及ぶべし汝らはユダの王ウジヤの世に地震を避て逃しごとくに逃ん我神ヱホバ來りたまはん諸の聖者なんぢとともなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'その日には光明なかるべく輝く者消うすべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, '茲に只一の日あるべしヱホバこれを知たまふ是は晝にもあらず夜にもあらず夕暮の頃に明くなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'その日に活る水ヱルサレムより出でその半は東の海にその半は西の海に流れん夏も冬も然あるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'ヱホバ全地の王となりたまはん其日には只ヱホバのみ只その御名のみにならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, '全地はアラバのごとくなりてゲバよりヱルサレムの南のリンモンまでの間のごとくなるべし而してヱルサレムは高くなりてその故の處に立ちベニヤミンの門より第一の門の處に及び隅の門にいたりハナニエルの戍樓より王の酒榨倉までに渉るべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'その中には人住ん重て呪詛あらじヱルサレムは安然に立べし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'ヱルサレムを攻撃し諸の民にヱホバ災禍を降してこれを撃なやましたまふこと是のごとくなるべし即ち彼らその足にて立をる中に肉腐れ目その孔の中にて腐れ舌その口の中にて腐れん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'その日にはヱホバかれらをして大に狼狽しめたまはん彼らは各々人の手を執へん此手と彼手撃あふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'ユダもまたヱルサレムに於て戰ふべしその四周の一切の國人の財寳金銀衣服など甚だ多く聚められん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'また馬騾駱駝驢馬およびその諸營の一切の家畜の蒙る災禍もこの災禍のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'ヱルサレムに攻きたりし諸の國人の遺れる者はみな歳々に上りきてその王なる萬軍のヱホバを拜み結茅の節を守るにいたるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, '地上の諸族の中その王なる萬軍のヱホバを拜みにヱルサレムに上らざる者の上には凡て雨ふらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, '例ばエジプトの族もし上り來らざる時はその上に雨ふらじヱホバその結茅の節を守りに上らざる一切の國人を撃なやます災禍を之に降したまふべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'エジプトの罪凡て結茅の節を守りに上り來らざる國人の罪是のごとくなるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'その日には馬の鈴にまでヱホバに聖としるさん又ヱホバの家の鍋は壇の前の鉢と等しかるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'ヱルサレムおよびユダの鍋は都て萬軍のヱホバの聖物となるべし凡そ犠牲を獻ぐる者は來りてこれを取り其中にて祭肉を煮ん其日には萬軍のヱホバの室に最早カナン人あらざるべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'これマラキに托てイスラエルに臨めるヱホバの言の重負なり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'ヱホバ曰たまふ我汝らを愛したり 然るに汝ら云ふ 汝いかに我儕を愛せしやと ヱホバいふエサウはヤコブの兄に非ずや されど我はヤコブを愛し');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'エサウを惡めり 且つわれ彼の山を荒し其嗣業を山犬にあたへたり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'エドムは我儕ほろぼされたれども再び荒たる所を建んといふによりて萬軍のヱホバかく曰たまふ 彼等は建ん されど我これを倒さん 人は彼等を惡境とよび又ヱホバの恒に怒りたまふ人民と稱へん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, '汝らこれを目に見て云ん ヱホバはイスラエルの地に大なりと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, '子は其父を敬ひ僕はその主を敬ふ されば我もし父たらば我を敬ふこと安にあるや 我もし主たらば我をおそるること安にあるや なんぢら我が名を藐視る祭司よと萬軍のヱホバいひたまふ 然るに汝曹はいふ我儕何に汝の名を藐視りしやと');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, '汝ら汚れたるパンをわが壇の上に獻げしかして言ふ我儕何に爾を汚せしやと 汝曹ヱホバの臺は卑しきなりと云しがゆゑなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, '汝ら盲目なる者を犠牲に獻ぐるは惡に非ずや 又跛足なるものと病者を獻ぐるは惡に非ずや 今これを汝の方伯に獻げよ されば彼なんぢを悦ぶや 汝を受納るや 萬軍のヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, '請ふ汝ら神に我らをあはれみ給はんことをもとめよ これらは凡て汝らの手になれり 彼なんぢらを納んや 萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, '汝らがわが壇の上にいたづらに火をたくこと無らんために汝らの中一人扉を閉づる者あらまほし われ汝らを悦ばず 又なんぢらの手より獻物を受じと萬軍のヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, '日の出る處より沒る處までの列國の中に我名は大ならん 又何處にても香と潔き獻物を我名に獻げん そはわが名列國の中に大なるべければなりと萬軍のヱホバいひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'しかるになんぢら之を褻したり そは爾曹はヱホバの臺は汚れたり また其果すなはちその食物は卑しと云ばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'なんぢらは又如何に煩勞しきことにあらずやといひ且これを藐視たり 萬軍のヱホバこれをいふ 又なんぢらは奪ひし物跛足たる者病る者を携へ來れり 汝らかく獻物を携へ來ればわれ之を汝らの手より受べけんや ヱホバこれをいひ給へり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, '群の中に牡あるに誓を立てて疵あるものをヱホバに獻ぐる詐僞者は詛はるべし そは我は大なる王また我名は列國に畏れらるべきなればなり 萬軍のヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, '祭司等よ今この命令なんぢらにあたへらる');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, '萬軍のヱホバいひたまふ汝等もし聽きしたがはず又これを心にとめず我名に榮光を歸せずばわれ汝らの上に詛を來らせん 又なんぢらの祝福を詛はん われすでに此等を詛へり 汝らこれを心にとめざりしに因てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, '視よ我なんぢらのために種をいましめん また糞すなはち汝らの犠牲の糞を汝らの面の上に撒さん 汝らこれとともに携へさられん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'わが此命令をなんぢらに下し與ふるは我契約をしてレビに保たしめんためなるを汝ら知るべし 萬軍のヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'わが彼と結びし契約は生命と平安とにあり 我がこれを彼に與へしは彼に我を畏れしめんが爲なり 彼われを懼れわが名の前にをののけり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, '眞理の法彼の口に在て不義その口唇にあらず 彼平安と公義をとりて我とともにあゆみ又多の人を不義より立歸らせたりき');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, '夫れ祭司の口唇に知識を持べく又人彼の口より法を諮詢べし そは祭司は萬軍のヱホバの使者なればなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'しかるに汝らは道を離れ衆多の人を法に躓礙かせレビの契約を壞りたり 萬軍のヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, '汝らは我道を守らず法をおこなふに當りて人に偏りし故にわれも汝らを一切の民の前に輕められまた賤められしむ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, '我儕の父は皆同一なるにあらずや われらを造りし神は同一なるにあらずや 我儕先祖等の契約を破りて各々おのれの兄弟にいつはりを行ふは何ぞ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'ユダは誓約にそむけり イスラエル及びエルサレムの中には憎むべき事行はる すなはちユダはヱホバの愛したまふ聖所を褻して他神の女をめとれり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'ヱホバこれをおこなふ人をば主なるものをも事ふる者をもヤコブの幕屋よりのぞきたまはん 萬軍のヱホバに獻物をささぐるものにてもまた然り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'つぎに又なんぢらはこれをなせり 即ち涙と泣と歎とをもてヱホバの壇をおほはしめたり 故に彼もはや獻物を顧みずまたこれを汝らの手より悦び納たまはざるなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, '汝らはなほ何故ぞやと言ふ そは是はヱホバ汝となんぢの若き時の妻の間にいりて證をなしたまへばなり 彼はなんぢの伴侶汝が契約をなせし妻なるに汝誓約に背きてこれを棄つ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'ヱホバは只一を造りたまひしにあらずや されども彼にはなほ靈の餘ありき 何故にひとつのみなりしや 是は神を敬虔の裔を得んが爲なりき 故になんぢら心に謹みその若き時の妻を誓約にそむきて棄るなかれ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'イスラエルの神ヱホバいひたまふ われは離縁を惡みまた虐遇をもて其衣を蔽ふ人を惡む 故に汝ら誓約にそむきて妻を待遇はざるやう心につつしむべし 萬軍のヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'なんぢらは言をもてヱホバを煩勞はせり されど汝ら言ふ 何にわづらはせしやと 如何となればなんぢら凡て惡をなすものはヱホバの目に善と見えかつ彼に悦ばると言ひ また審判の神は安にあるやといへばなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, '視よ我わが使者を遣さん かれ我面の前に道を備へん また汝らが求むるところの主すなはち汝らの悦樂ぶ契約の使者忽然その殿に來らん 視よ彼來らんと萬軍のヱホバ云たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'されど其來る日には誰か堪えんや その顯著る時には誰か立えんや 彼は金をふきわくる者の火の如く布晒の灰汁のごとくならん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'かれは銀をふきわけてこれを潔むる者のごとく坐せん 彼はレビの裔を潔め金銀の如くかれらをきよめん 而して彼等は義をもて獻物をヱホバにささげん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'その時ユダとエルサレムの獻物はむかし日の如く又先の年のごとくヱホバに悦ばれん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'われ汝らにちかづきて審判をなし巫術者にむかひ姦淫を行ふ者にむかひ僞の誓をなせる者にむかひ傭人の價金をかすめ寡婦と孤子をしへたげ異邦人を推抂げ我を畏れざるものどもにむかひて速に證をなさんと萬軍のヱホバ云たまふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'それわれヱホバは易らざる者なり 故にヤコブの子等よ汝らは亡されず');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'なんぢら其先祖等の日よりこのかたわが律例をはなれてこれを守らざりき 我にかへれ われ亦なんぢらに歸らん 萬軍のヱホバこれを言ふ 然るに汝らはわれら何においてかへるべきやと言り');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'ひと神の物をぬすむことをせんや されど汝らはわが物を盗めり 汝らは又何において汝の物をぬすみしやといへり 十分の一および獻物に於てなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, '汝らは呪詛をもて詛はる またなんぢら一切の國人はわが物をぬすめり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'わが殿に食物あらしめんために汝ら什一をすべて我倉にたづさへきたれ 而して是をもて我を試みわが天の窓をひらきて容べきところなきまでに恩澤を汝らにそそぐや否やを見るべし 萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, '我また噬食ふ者をなんぢらの爲に抑へてなんぢらの地の產物をやぶらざらしめん 又なんぢらの葡萄の樹をして時のいたらざる前にその實を圃におとさざらしめん 萬軍のヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, '又萬國の人なんぢらを幸福なる者ととなへん そは汝ら樂しき地となるべければなり 萬軍のヱホバこれをいふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'ヱホバ云たまふ 汝らは言詞をはげしくして我に逆らへり しかるも汝らは我儕なんぢらにさからひて何をいひしやといへり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, '汝らは言らく神に服事ることは徒然なり われらその命令をまもりかつ萬軍のヱホバの前に悲みて歩みたりとて何の益あらんや');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, '今われらは驕傲ものを幸福なりと稱ふ また惡をおこなふものも盛になり 神を試むるものすらも救はると');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'その時ヱホバをおそるる者互に相かたりヱホバ耳をかたむけてこれを聽たまへり またヱホバを畏るる者およびその名を記憶る者のためにヱホバの前に記念の書をかきしるせり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, '萬軍のヱホバいひたまふ 我わが設くる日にかれらをもて我寳となすべし また人の己につかふる子をあはれむがごとく我彼等をあはれまん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'その時汝らは更にまた義者と惡きものと神に服事るものと事へざる者との區別をしらん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, '萬軍のヱホバいひたまふ 視よ爐のごとくに燒る日來らん すべて驕傲者と惡をおこなふ者は藁のごとくにならん 其きたらんとする日彼等を燒つくして根も枝ものこらざらしめん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'されど我名をおそるる汝らには義の日いでて昇らん その翼には醫す能をそなへん 汝らは牢よりいでし犢の如く躍跳ん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, '又なんぢらは惡人を踐つけん 即ちわが設くる日にかれらは汝らの脚の掌の下にありて灰のごとくならん 萬軍のヱホバこれを言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'なんぢらわが僕モーセの律法をおぼえよ すなはち我がホレブにてイスラエル全體のために彼に命ぜし法度と誡命をおぼゆべし');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, '視よヱホバの大なる畏るべき日の來るまへにわれ預言者エリヤを汝らにつかはさん');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'かれ父の心にその子女の心を慈はせ 子女の心にその父をおもはしめん 是は我が來りて詛をもて地を撃ことなからんためなり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'アブラハムの子、ダビデの子、イエス・キリストの系圖。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'アブラハム、イサクを生み、イサク、ヤコブを生み、ヤコブ、ユダとその兄弟らとを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'ユダ、タマルによりてパレスとザラとを生み、パレス、エスロンを生み、エスロン、アラムを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'アラム、アミナダブを生み、アミナダブ、ナアソンを生み、ナアソン、サルモンを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'サルモン、ラハブによりてボアズを生み、ボアズ、ルツによりてオベデを生み、オベデ、エツサイを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'エツサイ、ダビデ王を生めり。ダビデ、ウリヤの妻たりし女によりてソロモンを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'ソロモン、レハベアムを生み、レハベアム、アビヤを生み、アビヤ、アサを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'アサ、ヨサパテを生み、ヨサパテ、ヨラムを生み、ヨラム、ウジヤを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'ウジヤ、ヨタムを生み、ヨタム、アハズを生み、アハズ、ヒゼキヤを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'ヒゼキヤ、マナセを生み、マナセ、アモンを生み、アモン、ヨシヤを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'バビロンに移さるる頃、ヨシヤ、エコニヤとその兄弟らとを生めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'バビロンに移されて後、エコニヤ、サラテルを生み、サラテル、ゾロバベルを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'ゾロバベル、アビウデを生み、アビウデ、エリヤキムを生み、エリヤキム、アゾルを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'アゾル、サドクを生み、サドク、アキムを生み、アキム、エリウデを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'エリウデ、エレアザルを生み、エレアザル、マタンを生み、マタン、ヤコブを生み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'ヤコブ、マリヤの夫ヨセフを生めり。此のマリヤよりキリストと稱ふるイエス生れ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'されば總て世をふる事、アブラハムよりダビデまで十四代、ダビデよりバビロンに移さるるまで十四代、バビロンに移されてよりキリストまで十四代なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'イエス・キリストの誕生は左のごとし。その母マリヤ、ヨセフと許嫁したるのみにて、未だ偕にならざりしに、聖 靈によりて孕り、その孕りたること顯れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, '夫ヨセフは正しき人にして、之を公然にするを好まず、私に離縁せんと思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'かくて、これらの事を思ひ囘らしをるとき、視よ、主の使、夢に現れて言ふ『ダビデの子ヨセフよ、妻マリヤを納るる事を恐るな。その胎に宿る者は聖 靈によるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'かれ子を生まん、汝その名をイエスと名づくべし。己が民をその罪より救ひ給ふ故なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'すべて此の事の起りしは、預言者によりて主の云ひ給ひし言の成就せん爲なり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '『視よ、處女みごもりて子を生まん。その名はインマヌエルと稱へられん』之を釋けば、神われらと偕に在すといふ意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'ヨセフ寐より起き、主の使の命ぜし如くして妻を納れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'されど子の生るるまでは、相 知る事なかりき。かくてその子をイエスと名づけたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'イエスはヘロデ王の時、ユダヤのベツレヘムに生れ給ひしが、視よ、東の博士たちエルサレムに來りて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, '『ユダヤ人の王とて生れ給へる者は、何處に在すか。我ら東にてその星を見たれば、拜せんために來れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'ヘロデ王これを聞きて惱みまどふ、エルサレムも皆 然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, '王、民の祭司長・學者らを皆あつめて、キリストの何處に生るべきを問ひ質す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'かれら言ふ『ユダヤのベツレヘムなり。それは預言者によりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '「ユダの地ベツレヘムよ、汝はユダの長たちの中にて最 小き者にあらず、汝の中より一人の君いでて、わが民イスラエルを牧せん」と録されたるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'ここにヘロデ密に博士たちを招きて、星の現れし時を詳細にし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, '彼らをベツレヘムに遣さんとして言ふ『往きて幼兒のことを細にたづね、之にあはば我に告げよ。我も往きて拜せん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, '彼ら王の言をききて往きしに、視よ、前に東にて見し星、先だちゆきて、幼兒の在すところの上に止る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'かれら星を見て、歡喜に溢れつつ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, '家に入りて、幼兒のその母マリヤと偕に在すを見、平伏して拜し、かつ寶の匣をあけて、黄金・乳香・沒藥など禮物を献げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'かくて夢にてヘロデの許に返るなとの御告を蒙り、ほかの路より己が國に去りゆきぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'その去り往きしのち、視よ、主の使、夢にてヨセフに現れていふ『起きて、幼兒とその母とを携へ、エジプトに逃れ、わが告ぐるまで彼處に留れ。ヘロデ幼兒を索めて亡さんとするなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'ヨセフ起きて、夜の間に幼兒とその母とを携へて、エジプトに去りゆき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'ヘロデの死ぬるまで彼處に留りぬ。これ主が預言者によりて『我エジプトより我が子を呼び出せり』と云ひ給ひし言の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'ここにヘロデ、博士たちに賺されたりと悟りて、甚だしく憤ほり、人を遣し、博士たちに由りて詳細にせし時を計り、ベツレヘム及び凡てその邊の地方なる、二 歳 以下の男の兒をことごとく殺せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'ここに預言者エレミヤによりて云はれたる言は成就したり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '『聲ラマにありて聞ゆ、慟哭なり、いとどしき悲哀なり。ラケル己が子らを歎き、子 等のなき故に慰めらるるを厭ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'ヘロデ死にてのち、視よ、主の使、夢にてエジプトなるヨセフに現れて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, '『起きて、幼兒とその母とを携へ、イスラエルの地にゆけ。幼兒の生命を索めし者どもは死にたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'ヨセフ起きて、幼兒とその母とを携へ、イスラエルの地に到りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'アケラオその父ヘロデに代りてユダヤを治むと聞き、彼處に往くことを恐る。また夢にて御告を蒙り、ガリラヤの地方に退き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'ナザレといふ町に到りて住みたり。これは預言者たちに由りて、『彼はナザレ人と呼ばれん』と云はれたる言の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'その頃バプテスマのヨハネ來り、ユダヤの荒野にて教を宣べて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '『なんぢら悔改めよ、天國は近づきたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'これ預言者イザヤによりて、斯く云はれし人なり、曰く『荒野に呼はる者の聲す「主の道を備へ、その路すぢを直くせよ」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'このヨハネは駱駝の毛織衣をまとひ、腰に皮の帶をしめ、蝗と野蜜とを食とせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'ここにエルサレム及びユダヤ全國、またヨルダンの邊なる全地方の人々、ヨハネの許に出できたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, '罪を言ひ表し、ヨルダン川にてバプテスマを受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'ヨハネ、パリサイ人およびサドカイ人のバプテスマを受けんとて、多く來るを見て、彼らに言ふ『蝮の裔よ、誰が汝らに、來らんとする御怒を避くべき事を示したるぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'さらば悔改に相應しき果を結べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, '汝ら「われらの父にアブラハムあり」と心のうちに言はんと思ふな。我なんぢらに告ぐ、神は此らの石よりアブラハムの子らを起し得給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, '斧ははや樹の根に置かる。されば凡て善き果を結ばぬ樹は、伐られて火に投げ入れらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, '我は汝らの悔改のために、水にてバプテスマを施す。されど我より後にきたる者は、我よりも能力あり、我はその鞋をとるにも足らず、彼は聖 靈と火とにて汝らにバプテスマを施さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, '手には箕を持ちて禾場をきよめ、その麥は倉に納め、殼は消えぬ火にて燒きつくさん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'ここにイエス、ヨハネにバプテスマを受けんとて、ガリラヤよりヨルダンに來り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'ヨハネ之を止めんとして言ふ『われは汝にバプテスマを受くべき者なるに、反つて我に來り給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'イエス答へて言ひたまふ『今は許せ、われら斯く正しき事をことごとく爲遂ぐるは、當然なり』ヨハネ乃ち許せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'イエス、バプテスマを受けて直ちに水より上り給ひしとき、視よ、天ひらけ、神の御靈の、鴿のごとく降りて己が上にきたるを見 給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'また天より聲あり、曰く『これは我が愛しむ子、わが悦ぶ者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'ここにイエス御靈によりて荒野に導かれ給ふ、惡魔に試みられんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, '四十 日 四十 夜 斷食して、後に飢ゑたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, '試むる者きたりて言ふ『汝もし神の子ならば、命じて此 等の石をパンと爲らしめよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, '答へて言ひ給ふ『「人の生くるはパンのみに由るにあらず、神の口より出づる凡ての言に由る」と録されたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'ここに惡魔イエスを聖なる都につれゆき、宮の頂上に立たせて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, '『汝もし神の子ならば己が身を下に投げよ。それは「なんぢの爲に御使たちに命じ給はん。彼ら手にて汝を支へ、その足を石にうち當つること無からしめん」と録されたるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'イエス言ひたまふ『「主なる汝の神を試むべからず」と、また録されたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, '惡魔またイエスを最 高き山につれゆき、世のもろもろの國と、その榮華とを示して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, '『汝もし平伏して我を拜せば、此 等を皆なんぢに與へん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'ここにイエス言ひ給ふ『サタンよ、退け「主なる汝の神を拜し、ただ之にのみ事へ奉るべし」と録されたるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'ここに惡魔は離れ去り、視よ、御使たち來り事へぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'イエス、ヨハネの囚はれし事をききて、ガリラヤに退き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, '後ナザレを去りて、ゼブルンとナフタリとの境なる、海邊のカペナウムに到りて住み給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'これは預言者イザヤによりて云はれたる言の成就せん爲なり。曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '『ゼブルンの地、ナフタリの地、海の邊、ヨルダンの彼方、異邦人のガリラヤ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, '暗きに坐する民は、大なる光を見、死の地と死の蔭とに坐する者に、光のぼれり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'この時よりイエス教を宣べはじめて言ひ給ふ『なんぢら悔改めよ、天國は近づきたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'かくて、ガリラヤの海邊をあゆみて、二人の兄弟ペテロといふシモンとその兄弟アンデレとが、海に網うちをるを見 給ふ、かれらは漁人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'これに言ひたまふ『我に從ひきたれ、さらば汝らを人を漁る者となさん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'かれら直ちに網をすてて從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, '更に進みゆきて、また二人の兄弟、ゼベダイの子ヤコブとその兄弟ヨハネとが、父ゼベダイとともに舟にありて網を繕ひをるを見て呼び給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, '直ちに舟と父とを置きて從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'イエスあまねくガリラヤを巡り、會堂にて教をなし、御國の福音を宣べつたへ、民の中のもろもろの病、もろもろの疾患をいやし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'その噂あまねくシリヤに弘り、人々すべての惱めるもの、即ちさまざまの病と苦痛とに罹れるもの、惡鬼に憑かれたるもの、癲癇および中風の者などを連れ來りたれば、イエス之を醫したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'ガリラヤ、デカポリス、エルサレム、ユダヤ及びヨルダンの彼方より、大なる群衆きたり從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'イエス群衆を見て、山にのぼり、座し給へば、弟子たち御許にきたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'イエス口をひらき、教へて言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '『幸福なるかな、心の貧しき者。天國はその人のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, '幸福なるかな、悲しむ者。その人は慰められん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, '幸福なるかな、柔和なる者。その人は地を嗣がん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, '幸福なるかな、義に飢ゑ渇く者。その人は飽くことを得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, '幸福なるかな、憐憫ある者。その人は憐憫を得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, '幸福なるかな、心の清き者。その人は神を見ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, '幸福なるかな、平和ならしむる者。その人は神の子と稱へられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, '幸福なるかな、義のために責められたる者。天國はその人のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, '我がために、人なんぢらを罵り、また責め、詐りて各樣の惡しきことを言ふときは、汝ら幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, '喜びよろこべ、天にて汝らの報は大なり。汝 等より前にありし預言者たちをも、斯く責めたりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, '汝らは地の鹽なり、鹽もし效力を失はば、何をもてか之に鹽すべき。後は用なし、外にすてられて人に蹈まるるのみ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, '汝らは世の光なり。山の上にある町は隱るることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'また人は燈火をともして升の下におかず、燈臺の上におく。かくて燈火は家にある凡ての物を照すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'かくのごとく汝らの光を人の前にかがやかせ。これ人の汝らが善き行爲を見て、天にいます汝らの父を崇めん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'われ律法また預言者を毀つために來れりと思ふな。毀たんとて來らず、反つて成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, '誠に汝らに告ぐ、天 地の過ぎ往かぬうちに、律法の一點、一畫も廢ることなく、ことごとく全うせらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'この故にもし此 等のいと小き誡命の一つをやぶり、且その如く人に教ふる者は、天國にて最 小き者と稱へられ、之を行ひ、かつ人に教ふる者は、天國にて大なる者と稱へられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, '我なんぢらに告ぐ、汝らの義、學者・パリサイ人に勝らずば、天國に入ること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, '古への人に「殺すなかれ、殺す者は審判にあふべし」と云へることあるを汝 等きけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'されど我は汝らに告ぐ、すべて兄弟を怒る者は、審判にあふべし。また兄弟に對ひて、愚 者よといふ者は、衆議にあふべし。また痴者よといふ者は、ゲヘナの火にあふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'この故に汝もし供物を祭壇にささぐる時、そこにて兄弟に怨まるる事あるを思ひ出さば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, '供物を祭壇のまへに遺しおき、先づ往きて、その兄弟と和睦し、然るのち來りて、供物をささげよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'なんぢを訴ふる者とともに途に在るうちに、早く和解せよ。恐らくは、訴ふる者なんぢを審判 人にわたし、審判 人は下役にわたし、遂になんぢは獄に入れられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'まことに汝に告ぐ、一 厘ものこりなく償はずば、其處をいづること能はじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, '「姦淫するなかれ」と云へることあるを汝 等きけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'されど我は汝らに告ぐ、すべて色情を懷きて女を見るものは、既に心のうち姦淫したるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'もし右の目なんぢを躓かせば、抉り出して棄てよ、五體の一つ亡びて、全身ゲヘナに投げ入れられぬは益なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'もし右の手なんぢを躓かせば、切りて棄てよ、五體の一つ亡びて、全身ゲヘナに往かぬは益なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'また「妻をいだす者は離縁状を與ふべし」と云へることあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'されど我は汝らに告ぐ、淫行の故ならで其の妻をいだす者は、これに姦淫を行はしむるなり。また出されたる女を娶るものは、姦淫を行ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'また古への人に「いつはり誓ふなかれ、なんぢの誓は主に果すべし」と云へる事あるを汝ら聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'されど我は汝らに告ぐ、一切ちかふな、天を指して誓ふな、神の御座なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, '地を指して誓ふな、神の足臺なればなり。エルサレムを指して誓ふな、大君の都なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, '己が頭を指して誓ふな、なんぢ頭髮 一筋だに白くし、また黒くし能はねばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'ただ然り然り、否 否といへ、之に過ぐるは惡より出づるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, '「目には目を、齒には齒を」と云へることあるを汝ら聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'されど我は汝らに告ぐ、惡しき者に抵抗ふな。人もし汝の右の頬をうたば、左をも向けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'なんぢを訟へて下衣を取らんとする者には、上衣をも取らせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, '人もし汝に一里ゆくことを強ひなば、共に二里ゆけ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'なんぢに請ふ者にあたへ、借らんとする者を拒むな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, '「なんぢの隣を愛し、なんぢの仇を憎むべし」と云へることあるを汝 等きけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'されど我は汝らに告ぐ、汝らの仇を愛し、汝らを責むる者のために祈れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'これ天にいます汝らの父の子とならん爲なり。天の父は、その日を惡しき者のうへにも善き者のうへにも昇らせ、雨を正しき者にも正しからぬ者にも降らせ給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'なんぢら己を愛する者を愛すとも何の報をか得べき、取税人も然するにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, '兄弟にのみ挨拶すとも何の勝ることかある、異邦人も然するにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'さらば汝らの天の父の全きが如く、汝らも全かれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '汝ら見られんために己が義を人の前にて行はぬやうに心せよ。然らずば、天にいます汝らの父より報を得じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'さらば施濟をなすとき、僞善者が人に崇められんとて會堂や街にて爲すごとく、己が前にラッパを鳴すな。誠に汝らに告ぐ、彼らは既にその報を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, '汝は施濟をなすとき、右の手のなすことを左の手に知らすな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, '是はその施濟の隱れん爲なり。さらば隱れたるに見たまふ汝の父は報い給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'なんぢら祈るとき、僞善者の如くあらざれ。彼らは人に顯さんとて、會堂や大路の角に立ちて祈ることを好む。誠に汝らに告ぐ、かれらは既にその報を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'なんぢは祈るとき、己が部屋にいり、戸を閉ぢて隱れたるに在す汝の父に祈れ。さらば隱れたるに見 給ふなんぢの父は報い給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'また祈るとき、異邦人の如くいたづらに言を反復すな。彼らは言 多きによりて聽かれんと思ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'さらば彼らに效ふな、汝らの父は求めぬ前に、なんぢらの必要なる物を知りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'この故に汝らは斯く祈れ。「天にいます我らの父よ、願はくは御名の崇められん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, '御國の來らんことを。御意の天のごとく地にも行はれん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, '我らの日用の糧を今日もあたへ給へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, '我らに負債ある者を我らの免したる如く、我らの負債をも免し給へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, '我らを嘗試に遇はせず、惡より救ひ出したまへ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, '汝 等もし人の過失を免さば、汝らの天の父も汝らを免し給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'もし人を免さずば、汝らの父も汝らの過失を免し給はじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'なんぢら斷食するとき、僞善者のごとく、悲しき面容をすな。彼らは斷食することを人に顯さんとて、その顏 色を害ふなり。誠に汝らに告ぐ、彼らは既にその報を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'なんぢは斷食するとき、頭に油をぬり、顏をあらへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'これ斷食することの人に顯れずして、隱れたるに在す汝の父にあらはれん爲なり。さらば隱れたるに見たまふ汝の父は報い給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'なんぢら己がために財寶を地に積むな、ここは蟲と錆とが損ひ、盜人うがちて盜むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'なんぢら己がために財寶を天に積め、かしこは蟲と錆とが損はず、盜人うがちて盜まぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'なんぢの財寶のある所には、なんぢの心もあるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, '身の燈火は目なり。この故に汝の目ただしくば、全身あかるからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'されど汝の目あしくば、全身くらからん。もし汝の内の光、闇ならば、その闇いかばかりぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, '人は二人の主に兼ね事ふること能はず、或はこれを憎み彼を愛し、或はこれに親しみ彼を輕しむべければなり。汝ら神と富とに兼ね事ふること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'この故に我なんぢらに告ぐ、何を食ひ、何を飮まんと生命のことを思ひ煩ひ、何を著んと體のことを思ひ煩ふな。生命は糧にまさり、體は衣に勝るならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, '空の鳥を見よ、播かず、刈らず、倉に收めず、然るに汝らの天の父は、これを養ひたまふ。汝らは之よりも遙に優るる者ならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, '汝らの中たれか思ひ煩ひて身の長 一尺を加へ得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, '又なにゆゑ衣のことを思ひ煩ふや。野の百合は如何にして育つかを思へ、勞せず、紡がざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'されど我なんぢらに告ぐ、榮華を極めたるソロモンだに、その服裝この花の一つにも及かざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, '今日ありて明日 爐に投げ入れらるる野の草をも、神はかく裝ひ給へば、まして汝らをや、ああ信仰うすき者よ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'さらば何を食ひ、何を飮み、何を著んとて思ひ煩ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, '是みな異邦人の切に求むる所なり。汝らの天の父は、凡てこれらの物の汝らに必要なるを知り給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'まづ神の國と神の義とを求めよ、さらば凡てこれらの物は汝らに加へらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'この故に明日のことを思ひ煩ふな、明日は明日みづから思ひ煩はん。一日の苦勞は一日にて足れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'なんぢら人を審くな、審かれざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, '己がさばく審判にて己もさばかれ、己がはかる量にて己も量らるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, '何ゆゑ兄弟の目にある塵を見て、おのが目にある梁木を認めぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, '視よ、おのが目に梁木のあるに、いかで兄弟にむかひて、汝の目より塵をとり除かせよと言ひ得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, '僞善者よ、まづ己が目より梁木をとり除け、さらば明かに見えて、兄弟の目より塵を取りのぞき得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, '聖なる物を犬に與ふな。また眞珠を豚の前に投ぐな。恐らくは足にて蹈みつけ、向き返りて汝らを噛みやぶらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, '求めよ、さらば與へられん。尋ねよ、さらば見出さん。門を叩け、さらば開かれん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'すべて求むる者は得、たづぬる者は見いだし、門をたたく者は開かるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, '汝 等のうち、誰かその子パンを求めんに石を與へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, '魚を求めんに蛇を與へんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'さらば、汝ら惡しき者ながら、善き賜物をその子らに與ふるを知る。まして天にいます汝らの父は、求むる者に善き物を賜はざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'さらば凡て人に爲られんと思ふことは、人にも亦その如くせよ。これは律法なり、預言者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, '狹き門より入れ、滅にいたる門は大きく、その路は廣く、之より入る者おほし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, '生命にいたる門は狹く、その路は細く、之を見 出す者すくなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, '僞 預言者に心せよ、羊の扮裝して來れども、内は奪ひ掠むる豺狼なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'その果によりて彼らを知るべし。茨より葡萄を、薊より無花果をとる者あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, '斯く、すべて善き樹は善き果をむすび、惡しき樹は惡しき果をむすぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, '善き樹は惡しき果を結ぶこと能はず、惡しき樹はよき果を結ぶこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'すべて善き果を結ばぬ樹は、伐られて火に投げ入れらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'さらばその果によりて彼らを知るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, '我に對ひて主よ主よといふ者、ことごとくは天國に入らず、ただ天にいます我が父の御意をおこなふ者のみ、之に入るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'その日おほくの者われに對ひて「主よ、主よ、我らは汝の名によりて預言し、汝の名によりて惡鬼を逐ひいだし、汝の名によりて多くの能力ある業を爲ししにあらずや」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'その時われ明白に告げん「われ斷えて汝らを知らず、不法をなす者よ、我を離れされ」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'さらば凡て我がこれらの言をききて行ふ者を、磐の上に家をたてたる慧き人に擬へん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, '雨ふり流みなぎり、風ふきてその家をうてど倒れず、これ磐の上に建てられたる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'すべて我がこれらの言をききて行はぬ者を、沙の上に家を建てたる愚なる人に擬へん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, '雨ふり流みなぎり、風ふきて其の家をうてば、倒れてその顛倒はなはだし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'イエスこれらの言を語りをへ給へるとき、群衆その教に驚きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'それは學者らの如くならず、權威ある者のごとく教へ給へる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'イエス山を下り給ひしとき、大なる群衆これに從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, '視よ、一人の癩病人みもとに來り、拜して言ふ『主よ、御意ならば、我を潔くなし給ふを得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'イエス手をのべ、彼につけて『わが意なり、潔くなれ』と言ひ給へば、癩病ただちに潔れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'イエス言ひ給ふ『つつしみて誰にも語るな、ただ往きて己を祭司に見せ、モーセが命じたる供物を献げて、人々に證せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'イエス、カペナウムに入り給ひしとき、百卒長きたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, '請ひていふ『主よ、わが僕、中風を病み、家に臥しゐて甚く苦しめり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'イエス言ひ給ふ『われ往きて醫さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, '百卒長こたへて言ふ『主よ、我は汝をわが屋根の下に入れまつるに足らぬ者なり。ただ御言のみを賜へ、さらば我が僕はいえん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, '我みづから權威の下にある者なるに、我が下にまた兵卒ありて、此に「ゆけ」と言へば往き、彼に「きたれ」と言へば來り、わが僕に「これを爲せ」といへば爲すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'イエス聞きて怪しみ、從へる人々に言ひ給ふ『まことに汝らに告ぐ、かかる篤き信仰はイスラエルの中の一人にだに見しことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, '又なんぢらに告ぐ、多くの人、東より西より來り、アブラハム、イサク、ヤコブとともに天國の宴につき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, '御國の子らは外の暗きに逐ひ出され、そこにて哀哭・切齒することあらん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'イエス百卒長に『ゆけ、汝の信ずるごとく汝になれ』と言ひ給へば、このとき僕いえたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'イエス、ペテロの家に入り、その外姑の熱を病みて臥しをるを見、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'その手に觸り給へば、熱 去り、女おきてイエスに事ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, '夕になりて、人々、惡鬼に憑かれたる者をおほく御許につれ來りたれば、イエス言にて靈を逐ひいだし、病める者をことごとく醫し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'これは預言者イザヤによりて『かれは自ら我らの疾患をうけ、我らの病を負ふ』と云はれし言の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'さてイエス群衆の己を環れるを見て、ともに彼方の岸に往かんことを弟子たちに命じ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, '一人の學者きたりて言ふ『師よ、何處にゆき給ふとも、我は從はん』。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'イエス言ひたまふ『狐は穴あり、空の鳥は塒あり、されど人の子は枕する所なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'また弟子の一人いふ『主よ、先づ、往きて、我が父を葬ることを許したまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'イエス言ひたまふ『我に從へ、死にたる者にその死にたる者を葬らせよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'かくて舟に乘り給へば、弟子たちも從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, '視よ、海に大なる暴風おこりて、舟 波に蔽はるるばかりなるに、イエスは眠りゐ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, '弟子たち御許にゆき、起して言ふ『主よ、救ひたまへ、我らは亡ぶ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, '彼らに言ひ給ふ『なにゆゑ臆するか、信仰うすき者よ』乃ち起きて、風と海とを禁め給へば、大なる凪となりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, '人々あやしみて言ふ『こは如何なる人ぞ、風も海も從ふとは』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'イエス彼方にわたり、ガダラ人の地にゆき給ひしとき、惡鬼に憑かれたる二人のもの、墓より出できたりて之に遇ふ。その猛きこと甚だしく、其處の途を人の過ぎ得ぬほどなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, '視よ、かれら叫びて言ふ『神の子よ、われら汝と何の關係あらん、未だ時いたらぬに、我らを責めんとて此處にきたり給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, '遙にへだたりて多くの豚の一 群、食しゐたりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, '惡鬼ども請ひて言ふ『もし我らを逐ひ出さんとならば、豚の群に遣したまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, '彼らに言ひ給ふ『ゆけ』惡鬼いでて豚に入りたれば、視よ、その群みな崖より海に駈け下りて、水に死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, '飼ふ者ども逃げて町にゆき、すべての事と惡鬼に憑かれたりし者の事とを告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, '視よ、町 人こぞりてイエスに逢はんとて出できたり、彼を見て、この地方より去り給はんことを請へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'イエス舟にのり、渡りて己が町にきたり給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, '視よ、中風にて床に臥しをる者を、人々みもとに連れ來れり。イエス彼らの信仰を見て、中風の者に言ひたまふ『子よ、心 安かれ、汝の罪ゆるされたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, '視よ、或 學者ら心の中にいふ『この人は神を瀆すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'イエスその思を知りて言ひ給ふ『何ゆゑ心に惡しき事をおもふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, '汝の罪ゆるされたりと言ふと、起きて歩めと言ふと、孰か易き。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, '人の子 地にて罪を赦す權威あることを汝らに知らせん爲に』――ここに中風の者に言ひ給ふ――『起きよ、床をとりて汝の家にかへれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, '彼おきてその家にかへる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, '群衆これを見ておそれ、かかる能力を人にあたへ給へる神を崇めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'イエス此處より進みて、マタイといふ人の收税所に坐しをるを見て『我に從へ』と言ひ給へば、立ちて從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, '家にて食事の席につき居給ふとき、視よ、多くの取税人・罪人ら來りて、イエス及び弟子たちと共に列る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'パリサイ人これを見て弟子たちに言ふ『なに故なんぢらの師は、取税人・罪人らと共に食するか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, '之を聞きて、言ひたまふ『健かなる者は醫者を要せず、ただ、病める者これを要す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'なんぢら往きて學べ「われ憐憫を好みて、犧牲を好まず」とは如何なる意ぞ。我は正しき者を招かんとにあらで、罪人を招かんとて來れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'ここにヨハネの弟子たち御許にきたりて言ふ『われらとパリサイ人は斷食するに、何 故なんぢの弟子たちは斷食せぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'イエス言ひたまふ『新郎の友だち、新郎と偕にをる間は、悲しむことを得んや。されど新郎をとらるる日きたらん、その時には斷食せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, '誰も新しき布の裂を舊き衣につぐことは爲じ、補ひたる裂は、その衣をやぶりて、破綻さらに甚だしかるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'また新しき葡萄酒をふるき革嚢に入るることは爲じ。もし然せば、嚢はりさけ酒ほどばしり出でて、嚢もまた廢らん。新しき葡萄酒は新しき革嚢にいれ、かくて兩ながら保つなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'イエス此 等のことを語りゐ給ふとき、視よ、一人の司きたり、拜して言ふ『わが娘いま死にたり。されど來りて御手を之におき給はば活きん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'イエス起ちて彼に伴ひ給ふに、弟子たちも從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, '視よ、十 二年 血漏を患ひゐたる女、イエスの後にきたりて、御衣の總にさはる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'それは、御衣にだに觸らば救はれんと心の中にいへるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'イエスふりかへり、女を見て言ひたまふ『娘よ、心 安かれ、汝の信仰なんぢを救へり』女この時より救はれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'かくてイエス司の家にいたり、笛ふく者と騷ぐ群衆とを見て言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, '『退け、少女は死にたるにあらず、寐ねたるなり』人々イエスを嘲笑ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, '群衆の出されし後、いりてその手をとり給へば、少女おきたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'この聲聞あまねく其の地に弘りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'イエス此處より進みたまふ時、ふたりの盲人さけびて『ダビデの子よ、我らを憫みたまへ』と言ひつつ從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'イエス家にいたり給ひしに、盲人ども御許に來りたれば、之に言ひたまふ『我この事をなし得と信ずるか』彼 等いふ『主よ、然り』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, '爰にイエスかれらの目に觸りて言ひたまふ『なんぢらの信仰のごとく汝らに成れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, '乃ち彼らの目あきたり。イエス嚴しく戒めて言ひたまふ『愼みて誰にも知らすな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'されど彼ら出でて、あまねくその地にイエスの事をいひ弘めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, '盲人どもの出づるとき、視よ、人々、惡鬼に憑かれたる唖者を御許につれきたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, '惡鬼おひ出されて唖者ものいひたれば、群衆あやしみて言ふ『かかる事は未だイスラエルの中に顯れざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, '然るにパリサイ人いふ『かれは惡鬼の首によりて惡鬼を逐ひ出すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'イエスあまねく町と村とを巡り、その會堂にて教へ、御國の福音を宣べつたへ、もろもろの病、もろもろの疾患をいやし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'また群衆を見て、その牧ふ者なき羊のごとく惱み、且たふるるを甚く憫み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, '遂に弟子たちに言ひたまふ『收穫はおほく勞動人はすくなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'この故に收穫の主に、勞動人をその收穫場に遣し給はんことを求めよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'かくてイエスその十二 弟子を召し、穢れし靈を制する權威をあたへて、之を逐ひ出し、もろもろの病、もろもろの疾患を醫すことを得しめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, '十二 使徒の名は左のごとし。先づペテロといふシモン及びその兄弟アンデレ、ゼベダイの子ヤコブ及びその兄弟ヨハネ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'ピリポ及びバルトロマイ、トマス及び取税人マタイ、アルパヨの子ヤコブ及びタダイ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, '熱心 黨のシモン及びイスカリオテのユダ、このユダはイエスを賣りし者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'イエスこの十二 人を遣さんとて、命じて言ひたまふ。『異邦人の途にゆくな、又サマリヤ人の町に入るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'むしろイスラエルの家の失せたる羊にゆけ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, '往きて宣べつたへ「天國は近づけり」と言へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, '病める者をいやし、死にたる者を甦へらせ、癩病人をきよめ、惡鬼を逐ひいだせ。價なしに受けたれば價なしに與へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, '帶のなかに金・銀または錢をもつな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, '旅の嚢も、二 枚の下衣も、鞋も、杖ももつな。勞動人の、その食物を得るは相應しきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'いづれの町いづれの村に入るとも、その中にて相應しき者を尋ねいだして、立ち去るまでは其處に留れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, '人の家に入らば平安を祈れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'その家もし之に相應しくば、汝らの祈る平安はその上に臨まん。もし相應しからずば、その平安はなんぢらに歸らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, '人もし汝らを受けず、汝らの言を聽かずば、その家その町を立ち去るとき、足の塵をはらへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'まことに汝らに告ぐ、審判の日には、その町よりもソドム、ゴモラの地のかた耐へ易からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, '視よ、我なんぢらを遣すは、羊を豺狼のなかに入るるが如し。この故に蛇のごとく慧く、鴿のごとく素直なれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, '人々に心せよ、それは汝らを衆議所に付し、會堂にて鞭うたん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'また汝 等わが故によりて、司たち王たちの前に曳かれん。これは彼らと異邦人とに證をなさん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'かれら汝らを付さば、如何に何を言はんと思ひ煩ふな、言ふべき事は、その時さづけらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'これ言ふものは汝 等にあらず、其の中にありて言ひたまふ汝らの父の靈なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, '兄弟は兄弟を、父は子を死に付し、子どもは親に逆ひて之を死なしめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, '又なんぢら我が名のために凡ての人に憎まれん。されど終まで耐へ忍ぶものは救はるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'この町にて責めらるる時は、かの町に逃れよ。誠に汝らに告ぐ、なんぢらイスラエルの町々を巡り盡さぬうちに人の子は來るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, '弟子はその師にまさらず、僕はその主にまさらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, '弟子はその師のごとく、僕はその主の如くならば足れり。もし家主をベルゼブルと呼びたらんには、ましてその家の者をや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'この故に、彼らを懼るな。蔽はれたるものに露れぬはなく、隱れたるものに知られぬは無ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, '暗黒にて我が告ぐることを光明にて言へ。耳をあてて聽くことを屋の上にて宣べよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, '身を殺して靈魂をころし得ぬ者どもを懼るな、身と靈魂とをゲヘナにて滅し得る者をおそれよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, '二 羽の雀は一錢にて賣るにあらずや、然るに、汝らの父の許なくば、その一 羽も地に落つること無からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, '汝らの頭の髮までも皆かぞへらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'この故におそるな、汝らは多くの雀よりも優るるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'されど凡そ人の前にて我を言ひあらはす者を、我もまた天にいます我が父の前にて言ひ顯さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'されど人の前にて我を否む者を、我もまた天にいます我が父の前にて否まん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'われ地に平和を投ぜんために來れりと思ふな。平和にあらず、反つて劍を投ぜん爲に來れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'それ我が來れるは、人をその父より、娘をその母より、嫁をその姑嫜より分たん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, '人の仇はその家の者なるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, '我よりも父または母を愛する者は、我に相應しからず。我よりも息子または娘を愛する者は、我に相應しからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, '又おのが十字架をとりて我に從はぬ者は、我に相應しからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, '生命を得る者はこれを失ひ、我がために生命を失ふ者はこれを得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, '汝らを受くる者は、我を受くるなり。我をうくる者は、我を遣し給ひし者を受くるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, '預言者たる名の故に預言者をうくる者は、預言者の報をうけ、義人たる名のゆゑに義人をうくる者は、義人の報を受くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, '凡そわが弟子たる名の故に、この小き者の一人に冷かなる水 一杯にても與ふる者は、まことに汝らに告ぐ、必ずその報を失はざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'イエス十二 弟子に命じ終へてのち、町々にて教へ、かつ、宣傳へんとて、此處を去り給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'ヨハネ牢舍にてキリストの御業をきき、弟子たちを遣して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'イエスに言はしむ『來るべき者は汝なるか、或は、他に待つべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, '答へて言ひたまふ『ゆきて、汝らが見 聞する所をヨハネに告げよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, '盲人は見、跛者はあゆみ、癩病人は潔められ、聾者はきき、死人は甦へらせられ、貧しき者は福音を聞かせらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'おほよそ我に躓かぬ者は幸福なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, '彼らの歸りたるをり、ヨハネの事を群衆に言ひ出でたまふ『なんぢら何を眺めんとて野に出でし、風にそよぐ葦なるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'さらば何を見んとて出でし、柔かき衣を著たる人なるか。視よ、やはらかき衣を著たる者は、王の家に在り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'さらば何のために出でし、預言者を見んとてか。然り、汝らに告ぐ、預言者よりも勝る者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, '「視よ、わが使をなんぢの顏の前につかはす。彼はなんぢの前に、なんぢの道をそなへん」と録されたるは此の人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, '誠に汝らに告ぐ、女の産みたる者のうち、バプテスマのヨハネより大なる者は起らざりき。されど天國にて小き者も、彼よりは大なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'バプテスマのヨハネの時より今に至るまで、天國は烈しく攻めらる、烈しく攻むる者はこれを奪ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, '凡ての預言者と律法との預言したるは、ヨハネの時までなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'もし汝 等わが言をうけんことを願はば、來るべきエリヤは此の人なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, '耳ある者は聽くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'われ今の代を何に比へん、童子、市場に坐し、友を呼びて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, '「われら汝 等のために笛 吹きたれど、汝ら踊らず、歎きたれど、汝ら胸うたざりき」と言ふに似たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'それは、ヨハネ來りて飮食せざれば「惡鬼に憑かれたる者なり」といひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, '人の子 來りて飮食すれば、「視よ、食を貪り酒を好む人、また取税人・罪人の友なり」と言ふなり。されど智慧は己が業によりて正しとせらる』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, '爰にイエス多くの能力ある業を行ひ給へる町々の悔改めぬによりて、之を責めはじめ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '『禍害なる哉コラジンよ、禍害なる哉ベツサイダよ、汝らの中にて行ひたる能力ある業を、ツロとシドンとにて行ひしならば、彼らは早く荒布を著、灰の中にて悔改めしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'されば汝らに告ぐ、審判の日にはツロとシドンとのかた汝 等よりも耐へ易からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'カペナウムよ、なんぢは天にまで擧げらるべきか、黄泉にまで下らん。汝のうちにて行ひたる能力ある業を、ソドムにて行ひしならば、今日までもかの町は遺りしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'されば汝らに告ぐ、審判の日にはソドムの地のかた汝よりも耐へ易からん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'その時イエス答へて言ひたまふ『天 地の主なる父よ、われ感謝す、此 等のことを智き者 慧き者にかくして、嬰兒に顯し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, '父よ、然り、かくの如きは御意に適へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'すべての物は我わが父より委ねられたり。子を知る者は父の外になく、父をしる者は子または子の欲するままに顯すところの者の外になし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, '凡て勞する者・重荷を負ふ者、われに來れ、われ汝らを休ません。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, '我は柔和にして心 卑ければ、我が軛を負ひて我に學べ、さらば靈魂に休息を得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'わが軛は易く、わが荷は輕ければなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'その頃イエス安息 日に麥 畠をとほり給ひしに、弟子たち飢ゑて穗を摘み、食ひ始めたるを、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'パリサイ人 見てイエスに言ふ『視よ、なんぢの弟子は安息 日に爲まじき事をなす』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, '彼らに言ひ給ふ『ダビデがその伴へる人々とともに飢ゑしとき、爲しし事を讀まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, '即ち神の家に入りて、祭司のほかは、己もその伴へる人々も食ふまじき供のパンを食へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'また安息 日に祭司らは宮の内にて安息 日を犯せども、罪なきことを律法にて讀まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'われ汝らに告ぐ、宮より大なる者ここに在り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, '「われ憐憫を好みて犧牲を好まず」とは、如何なる意かを汝ら知りたらんには、罪なき者を罪せざりしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'それ人の子は安息 日の主たるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'イエス此處を去りて、彼らの會堂に入り給ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, '視よ、片手なえたる人あり。人々イエスを訴へんと思ひ、問ひていふ『安息 日に人を醫すことは善きか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, '彼らに、言ひたまふ『汝 等のうち一匹の羊をもてる者あらんに、もし安息 日に穴に陷らば、之を取りあげぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, '人は羊より優るること如何ばかりぞ。さらば安息 日に善をなすは可し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'ここにかの人に言ひ給ふ『なんぢの手を伸べよ』かれ伸べたれば、他の手のごとく癒ゆ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'パリサイ人いでていかにしてかイエスを亡さんと議る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'イエス之を知りて此處を去りたまふ。多くの人したがひ來りたれば、ことごとく之を醫し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'かつ我を人に知らすなと戒め給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'これ預言者イザヤによりて云はれたる言の成就せんためなり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '『視よ、わが選びたる我が僕、わが心の悦ぶ我が愛しむ者、我わが靈を彼に與へん、彼は異邦人に正義を告げ示さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, '彼は爭はず、叫ばず、その聲を大路にて聞く者なからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, '正義をして勝ち遂げしむるまでは、傷へる葦を折ることなく、煙れる亞麻を消すことなからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, '異邦人も彼の名に望をおかん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'ここに惡鬼に憑かれたる盲目の唖者を御許に連れ來りたれば、之を醫して、唖者の物 言ひ見ゆるやうに爲し給ひぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, '群衆みな驚きて言ふ『これはダビデの子にあらぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, '然るにパリサイ人ききて言ふ『この人、惡鬼の首ベルゼブルによらでは、惡鬼を逐ひ出すことなし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'イエス彼らの思を知りて言ひ給ふ『すべて分れ爭ふ國はほろび、分れ爭ふ町また家はたたず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'サタンもしサタンを逐ひ出さば、自ら分れ爭ふなり。さらばその國いかで立つべき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, '我もしベルゼブルによりて惡鬼を逐ひ出さば、汝らの子は誰によりて之を逐ひ出すか。この故に彼らは汝らの審判 人となるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'されど我もし神の靈によりて惡鬼を逐ひ出さば、神の國は既に汝らに到れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, '人まづ強き者を縛らずば、いかで強き者の家に入りて、その家財を奪ふことを得ん、縛りて後その家を奪ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, '我と偕ならぬ者は我にそむき、我とともに集めぬ者は散すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'この故に汝らに告ぐ、人の凡ての罪と瀆とは赦されん、されど御靈を瀆すことは赦されじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, '誰にても言をもて人の子に逆ふ者は赦されん、されど言をもて聖 靈に逆ふ者は、この世にても後の世にても赦されじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, '或は樹をも善しとし、果をも善しとせよ。或は樹をも惡しとし、果をも惡しとせよ。樹は果によりて知らるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, '蝮の裔よ、なんぢら惡しき者なるに、爭で善きことを言ひ得んや。それ心に滿つるより口に言はるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, '善き人は善き倉より善き物をいだし、惡しき人は惡しき倉より惡しき物をいだす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'われ汝らに告ぐ、人の語る凡ての虚しき言は、審判の日に糺さるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'それは汝の言によりて義とせられ、汝の言によりて罪せらるるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'ここに或 學者・パリサイ人ら答へて言ふ『師よ、われら汝の徴を見んことを願ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, '答へて言ひたまふ『邪曲にして不義なる代は徴を求む、されど預言者ヨナの徴のほかに徴は與へられじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, '即ち「ヨナが三日 三夜、大魚の腹の中に在りし」ごとく、人の子も三日 三夜、地の中に在るべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'ニネベの人、審判のとき今の代の人とともに立ちて之が罪を定めん、彼らはヨナの宣ぶる言によりて悔改めたり。視よ、ヨナよりも勝るもの此處に在り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, '南の女王、審判のとき今の代の人とともに起きて之が罪を定めん、彼はソロモンの智慧を聽かんとて地の極より來れり。視よ、ソロモンよりも勝る者ここに在り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, '穢れし靈、人を出づるときは、水なき處を巡りて休を求む、而して得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, '乃ち「わが出でし家に歸らん」といひ、歸りて、その家の空きて掃き淨められ、飾られたるを見、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, '遂に往きて己より惡しき他の七つの靈を連れきたり、共に入りて此處に住む。されば其の人の後の状は前よりも惡しくなるなり。邪曲なる此の代もまた斯くの如くならん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'イエスなほ群衆にかたり居給ふとき、視よ、その母と兄弟たちと、彼に物 言はんとて外に立つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, '或 人イエスに言ふ『視よ、なんぢの母と兄弟たちと、汝に物 言はんとて外に立てり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'イエス告げし者に答へて言ひたまふ『わが母とは誰ぞ、わが兄弟とは誰ぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'かくて手をのべ、弟子たちを指して言ひたまふ『視よ、これは我が母、わが兄弟なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, '誰にても天にいます我が父の御意をおこなふ者は、即ち我が兄弟、わが姉妹、わが母なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'その日イエスは家を出でて、海邊に坐したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, '大なる群衆みもとに集りたれば、イエスは舟に乘りて坐したまひ、群衆はみな岸に立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, '譬にて數多のことを語りて言ひたまふ、『視よ、種 播く者まかんとて出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, '播くとき路の傍らに落ちし種あり、鳥きたりて啄む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, '土うすき磽地に落ちし種あり、土 深からぬによりて速かに萠え出でたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, '日の昇りし時やけて根なき故に枯る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, '茨の地に落ちし種あり、茨そだちて之を塞ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, '良き地に落ちし種あり、あるひは百 倍、あるひは六十 倍、あるひは三十 倍の實を結べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, '耳ある者は聽くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, '弟子たち御許に來りて言ふ『なにゆゑ譬にて彼らに語り給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, '答へて言ひ給ふ『なんぢらは天國の奧義を知ることを許されたれど、彼らは許されず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'それ誰にても、有てる人は與へられて愈々 豐ならん。されど有たぬ人は、その有てる物をも取らるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'この故に彼らには譬にて語る、これ彼らは見ゆれども見ず、聞ゆれども聽かず、また悟らぬ故なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'かくてイザヤの預言は、彼らの上に成就す。曰く、「なんぢら聞きて聞けども悟らず、見て見れども認めず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'この民の心は鈍く、耳は聞くに懶く、目は閉ぢたればなり。これ目にて見、耳にて聽き、心にて悟り、飜へりて、我に醫さるる事なからん爲なり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'されど汝らの目なんぢらの耳は、見るゆゑに聞くゆゑに、幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'まことに汝らに告ぐ、多くの預言者・義人は、汝らが見る所を見んとせしが見ず、なんぢらが聞く所を聞かんとせしが聞かざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'されば汝ら種 播く者の譬を聽け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, '誰にても天國の言をききて悟らぬときは、惡しき者きたりて、其の心に播かれたるものを奪ふ。路の傍らに播かれしとは斯かる人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, '磽地に播かれしとは、御言をききて、直ちに喜び受くれども、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, '己に根なければ暫し耐ふるのみにて、御言のために艱難あるひは迫害の起るときは、直ちに躓くものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, '茨の中に播かれしとは、御言をきけども、世の心勞と財貨の惑とに、御言を塞がれて實らぬものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, '良き地に播かれしとは、御言をききて悟り、實を結びて、あるひは百 倍、あるひは六十 倍、あるひは三十 倍に至るものなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'また他の譬を示して言ひたまふ『天國は良き種を畑にまく人のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, '人々の眠れる間に、仇きたりて麥のなかに毒 麥を播きて去りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, '苗はえ出でて實りたるとき、毒 麥もあらはる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, '僕ども來りて家主にいふ「主よ、畑に播きしは良き種ならずや、然るに如何にして毒 麥あるか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, '主人いふ「仇のなしたるなり」僕ども言ふ「さらば我らが往きて之を拔き集むるを欲するか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, '主人いふ「いな、恐らくは毒 麥を拔き集めんとて、麥をも共に拔かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, '兩ながら收穫まで育つに任せよ。收穫のとき我かる者に「まづ毒 麥を拔きあつめて、焚くために之を束ね、麥はあつめて我が倉に納れよ」と言はん」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'また他の譬を示して言ひたまふ『天國は一粒の芥種のごとし、人これを取りてその畑に播くときは、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, '萬の種よりも小けれど、育ちては他の野菜よりも大く、樹となりて、空の鳥きたり其の枝に宿るほどなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'また他の譬を語りたまふ『天國はパンだねのごとし、女これを取りて、三 斗の粉の中に入るれば、ことごとく脹れいだすなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'イエスすべて此 等のことを、譬にて群衆に語りたまふ、譬ならでは何事も語り給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'これ預言者によりて云はれたる言の成就せん爲なり。曰く、『われ譬を設けて口を開き、世の創より隱れたる事を言ひ出さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'ここに群衆を去らしめて、家に入りたまふ。弟子たち御許に來りて言ふ『畑の毒 麥の譬を我らに解きたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, '答へて言ひ給ふ『良き種を播く者は人の子なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, '畑は世界なり、良き種は天國の子どもなり、毒 麥は惡しき者の子どもなり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, '之を播きし仇は惡魔なり、收穫は世の終なり、刈る者は御使たちなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'されば毒 麥の集められて火に焚かるる如く、世の終にも斯くあるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, '人の子その使たちを遣さん。彼ら御國の中より凡ての顛躓となる物と不法をなす者とを集めて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, '火の爐に投げ入るべし、其處にて哀哭・切齒することあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, '其のとき義人は父の御國にて日のごとく輝かん。耳ある者は聽くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, '天國は畑に隱れたる寶のごとし。人 見出さば、之を隱しおきて、喜びゆき、有てる物をことごとく賣りて其の畑を買ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'また天國は良き眞珠を求むる商人のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, '價たかき眞珠 一つを見出さば、往きて有てる物をことごとく賣りて、之を買ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'また天國は、海におろして各樣のものを集むる網のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, '充つれば岸にひきあげ、坐して良きものを器に入れ、惡しきものを棄つるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, '世の終にも斯くあるべし。御使たち出でて、義人の中より惡人を分ちて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, '之を火の爐に投げ入るべし。其處にて哀哭・切齒することあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, '汝 等これらの事をみな悟りしか』彼 等いふ『然り』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'また言ひ給ふ『この故に、天國のことを教へられたる凡ての學者は、新しき物と舊き物とをその倉より出す家主のごとし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'イエスこれらの譬を終へて此處を去りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, '己が郷にいたり、會堂にて教へ給へば、人々おどろきて言ふ『この人はこの智慧と此 等の能力とを何處より得しぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'これ木匠の子にあらずや、其の母はマリヤ、其の兄弟はヤコブ、ヨセフ、シモン、ユダにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, '又その姉妹も皆われらと共にをるに非ずや。然るに此 等のすべての事は何處より得しぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, '遂に人々かれに躓けり。イエス彼らに言ひたまふ『預言者は、おのが郷おのが家の外にて尊ばれざる事なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, '彼らの不 信仰によりて其處にては多くの能力ある業を爲し給はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'そのころ、國守ヘロデ、イエスの噂をききて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, '侍臣どもに言ふ『これバプテスマのヨハネなり。かれ死人の中より甦へりたり、さればこそ此 等の能力その内に働くなれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'ヘロデ先に、己が兄弟ピリポの妻ヘロデヤの爲にヨハネを捕へ、縛りて獄に入れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'ヨハネ、ヘロデに『かの女を納るるは宜しからず』と言ひしに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'かくてヘロデ、ヨハネを殺さんと思へど、群衆を懼れたり。群衆ヨハネを預言者とすればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, '然るにヘロデの誕生日に當り、ヘロデヤの娘その席上に舞をまひてヘロデを喜ばせたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'ヘロデ之に何にても求むるままに與へんと誓へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, '娘その母に唆かされて言ふ『バプテスマのヨハネの首を盆に載せてここに賜はれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, '王 憂ひたれど、その誓と席に在る者とに對して、之を與ふることを命じ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, '人を遣し獄にてヨハネの首を斬り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'その首を盆にのせて持ち來らしめ、之を少女に與ふ。少女はこれを母に捧ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'ヨハネの弟子たち來り、屍體を取りて葬り、往きて、イエスに告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'イエス之を聞きて人を避け、其處より舟にのりて寂しき處に往き給ひしを群衆ききて町々より徒歩にて從ひゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'イエス出でて大なる群衆を見、これを憫みて、その病める者を醫し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, '夕になりたれば、弟子たち御許に來りて言ふ『ここは寂しき處、はや時も晩し、群衆を去らしめ、村々に往きて、己が爲に食物を買はせ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'イエス言ひ給ふ『かれら往くに及ばず、汝ら之に食物を與へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, '弟子たち言ふ『われらが此處にもてるは、唯 五つのパンと二つの魚とのみ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'イエス言ひ給ふ『それを我に持ちきたれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'かくて群衆に命じて草の上に坐せしめ、五つのパンと二つの魚とを取り、天を仰ぎて祝し、パンを裂きて、弟子たちに與へ給へば、弟子たち之を群衆に與ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, '凡ての人 食ひて飽く、裂きたる餘を集めしに十二の筐に滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, '食ひし者は、女と子供とを除きて凡そ五 千 人なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'イエス直ちに弟子たちを強ひて舟に乘らせ、自ら群衆をかへす間に、彼方の岸に先に往かしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'かくて群衆を去らしめてのち、祈らんとて竊に山に登り、夕になりて獨そこにゐ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, '舟ははや陸より數丁はなれ、風 逆ふによりて波に難されゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, '夜明の四時ごろ、イエス海の上を歩みて、彼らに到り給ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, '弟子たち其の海の上を歩み給ふを見て心 騷ぎ、變化の者なりと言ひて懼れ叫ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'イエス直ちに彼らに語りて言ひたまふ『心 安かれ、我なり、懼るな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'ペテロ答へて言ふ『主よ、もし汝ならば我に命じ、水を蹈みて御許に到らしめ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, '『來れ』と言ひ給へば、ペテロ舟より下り、水の上を歩みてイエスの許に往く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, '然るに風を見て懼れ、沈みかかりければ、叫びて言ふ『主よ、我を救ひたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'イエス直ちに御手を伸べ、これを捉へて言ひ給ふ『ああ信仰うすき者よ、何ぞ疑ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, '相 共に舟に乘りしとき、風やみたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, '舟に居る者どもイエスを拜して言ふ『まことに汝は神の子なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, '遂に渡りてゲネサレの地に著きしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'その處の人々イエスを認めて、あまねく四方に人をつかはし、又すべての病める者を連れきたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'ただ御衣の總にだに觸らしめ給はんことを願ふ、觸りし者はみな醫されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'ここにパリサイ人・學者ら、エルサレムより來りてイエスに言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '『なにゆゑ汝の弟子は、古への人の言傳を犯すか、食事のときに手を洗はぬなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, '答へて言ひ給ふ『なにゆゑ汝らは、また汝らの言傳によりて神の誡命を犯すか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, '即ち神は「父 母を敬へ」と言ひ「父または母を罵る者は必ず殺さるべし」と言ひたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, '然るに汝らは「誰にても父または母に對ひて、我が負ふ所のものは供物となりたりと言はば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, '父または母を敬ふに及ばず」と言ふ。斯くその言傳によりて神の言を空しうす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, '僞善者よ、宜なる哉、イザヤは汝らに就きて能く預言せり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '「この民は口唇にて我を敬ふ、されど其の心は我に遠ざかる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'ただ徒らに我を拜む。人の訓誡を教とし教へて」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'かくて群衆を呼び寄せて言ひたまふ『聽きて悟れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, '口に入るものは人を汚さず、されど口より出づるものは、これ人を汚すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'ここに弟子たち御許に來りていふ『御言をききてパリサイ人の躓きたるを知り給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, '答へて言ひ給ふ『わが天の父の植ゑ給はぬものは、みな拔かれん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, '彼らを捨ておけ、盲人を手引する盲人なり、盲人もし盲人を手引せば、二人とも穴に落ちん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'ペテロ答へて言ふ『その譬を我らに解き給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'イエス言ひ給ふ『なんぢらも今なほ悟りなきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, '凡て口に入るものは腹にゆき、遂に厠に棄てらるる事を悟らぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'されど口より出づるものは心より出づ、これ人を汚すものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'それ心より惡しき念いづ、すなはち殺人・姦淫・淫行・竊盜・僞證・誹謗、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'これらは人を汚すものなり、されど洗はぬ手にて食する事は人を汚さず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'イエスここを去りてツロとシドンとの地方に往き給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, '視よ、カナンの女その邊より出できたり、叫びて『主よ、ダビデの子よ、我を憫み給へ、わが娘、惡鬼につかれて甚く苦しむ』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'されどイエス一言も答へ給はず。弟子たち來り請ひて言ふ『女を歸したまへ、我らの後より叫ぶなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, '答へて言ひたまふ『我はイスラエルの家の失せたる羊のほかに遣されず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, '女きたり拜して言ふ『主よ、我を助けたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, '答へて言ひたまふ『子供のパンをとりて小狗に投げ與ふるは善からず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, '女いふ『然り、主よ、小狗も主人の食卓よりおつる食屑を食ふなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'ここにイエス答へて言ひたまふ『をんなよ、汝の信仰は大なるかな、願のごとく汝になれ』娘この時より癒えたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'イエス此處を去り、ガリラヤの海邊にいたり、而して山に登り、そこに坐し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, '大なる群衆、跛者・不具・盲人・唖者および他の多くの者を連れ來りて、イエスの足下に置きたれば、醫し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, '群衆は、唖者の物いひ、不具の癒え、跛者の歩み、盲人の見えたるを見て之を怪しみ、イスラエルの神を崇めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'イエス弟子たちを召して言ひ給ふ『われ此の群衆をあはれむ、既に三日われと偕にをりて食ふべき物なし。飢ゑたるままにて歸らしむるを好まず、恐らくは途にて疲れ果てん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, '弟子たち言ふ『この寂しき地にて、斯く大なる群衆を飽かしむべき多くのパンを、何處より得べき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'イエス言ひ給ふ『パン幾つあるか』彼らいふ『七つ、また小き魚すこしあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'イエス群衆に命じて地に坐せしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, '七つのパンと魚とを取り、謝して之をさき弟子たちに與へ給へば、弟子たちこれを群衆に與ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, '凡ての人くらひて飽き、裂きたる餘を拾ひしに、七つの籃に滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, '食ひし者は、女と子供とを除きて四千 人なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'イエス群衆をかへし、舟に乘りてマガダンの地方に往き給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'パリサイ人とサドカイ人と來りてイエスを試み、天よりの徴を示さんことを請ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, '答へて言ひたまふ『夕には汝ら「空あかき故に晴ならん」と言ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'また朝には「そら赤くして曇る故に、今日は風雨ならん」と言ふ。なんぢら空の氣色を見分くることを知りて、時の徴を見分くること能はぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, '邪曲にして不義なる代は徴を求む、されどヨナの徴の外に徴は與へられじ』かくて彼らを離れて去り給ひぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, '弟子たち彼方の岸に到りしに、パンを携ふることを忘れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'イエス言ひたまふ『愼みてパリサイ人とサドカイ人とのパン種に心せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, '弟子たち互に『我らはパンを携へざりき』と語り合ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'イエス之を知りて言ひ給ふ『ああ信仰うすき者よ、何ぞパン無きことを語り合ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, '未だ悟らぬか、五つのパンを五 千 人に分ちて、その餘を幾籃ひろひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'また七つのパンを四千 人に分ちて、その餘を幾籃ひろひしかを覺えぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, '我が言ひしはパンの事にあらぬを何ぞ悟らざる。唯パリサイ人とサドカイ人とのパンだねに心せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'ここに弟子たちイエスの心せよと言ひ給ひしは、パンの種にはあらで、パリサイ人とサドカイ人との教なることを悟れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'イエス、ピリポ・カイザリヤの地方にいたり、弟子たちに問ひて言ひたまふ『人々は人の子を誰と言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, '彼 等いふ『或 人はバプテスマのヨハネ、或 人はエリヤ、或 人はエレミヤ、また預言者の一人』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, '彼らに言ひたまふ『なんぢらは我を誰と言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'シモン・ペテロ答へて言ふ『なんぢはキリスト、活ける神の子なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'イエス答へて言ひ給ふ『バルヨナ・シモン、汝は幸福なり、汝に之を示したるは血肉にあらず、天にいます我が父なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, '我はまた汝に告ぐ、汝はペテロなり、我この磐の上に我が教會を建てん、黄泉の門はこれに勝たざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'われ天國の鍵を汝に與へん、凡そ汝が地にて縛ぐ所は天にても縛ぎ、地にて解く所は天にても解くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'ここにイエス、己がキリストなる事を誰にも告ぐなと、弟子たちを戒め給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'この時よりイエス・キリスト、弟子たちに、己のエルサレムに往きて、長老・祭司長・學者らより多くの苦難を受け、かつ殺され、三日めに甦へるべき事を示し始めたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'ペテロ、イエスを傍にひき戒め出でて言ふ『主よ、然あらざれ、此の事なんぢに起らざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'イエス振反りてペテロに言ひ給ふ『サタンよ、我が後に退け、汝はわが躓物なり、汝は神のことを思はず、反つて人のことを思ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'ここにイエス弟子たちに言ひたまふ『人もし我に從ひ來らんと思はば、己をすて、己が十字架を負ひて、我に從へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, '己が生命を救はんと思ふ者は、これを失ひ、我がために己が生命をうしなふ者は、之を得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, '人、全世界を贏くとも、己が生命を損せば、何の益あらん、又その生命の代に何を與へんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, '人の子は父の榮光をもて、御使たちと共に來らん。その時おのおのの行爲に隨ひて報ゆべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'まことに汝らに告ぐ、ここに立つ者のうちに、人の子のその國をもて來るを見るまでは、死を味はぬ者どもあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, '六日の後、イエス、ペテロ、ヤコブ及びヤコブの兄弟ヨハネを率きつれ、人を避けて高き山に登りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'かくて彼らの前にてその状かはり、其の顏は日のごとく輝き、その衣は光のごとく白くなりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, '視よ、モーセとエリヤとイエスに語りつつ彼らに現る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'ペテロ差出でてイエスに言ふ『主よ、我らの此處に居るは善し。御意ならば我ここに三つの廬を造り、一つを汝のため、一つをモーセのため、一つをエリヤの爲にせん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, '彼なほ語りをるとき、視よ、光れる雲かれらを覆ふ。また雲より聲あり、曰く『これは我が愛しむ子、わが悦ぶ者なり、汝ら之に聽け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, '弟子たち之を聞きて倒れ伏し、懼るること甚だし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'イエスその許にきたり之に觸りて『起きよ、懼るな』と言ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, '彼ら目を擧げしに、イエス一人の他は誰も見えざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, '山を下るとき、イエス彼らに命じて言ひたまふ『人の子の死人の中より甦へるまでは、見たることを誰にも語るな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, '弟子たち問ひて言ふ『さらばエリヤ先づ來るべしと學者らの言ふは何ぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, '答へて言ひたまふ『實にエリヤ來りて萬の事をあらためん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, '我なんぢらに告ぐ、エリヤは既に來れり。されど人々これを知らず、反つて心のままに待へり。かくのごとく人の子もまた人々より苦しめらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'ここに弟子たちバプテスマのヨハネを指して言ひ給ひしなるを悟れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'かれら群衆の許に到りしとき、或 人 御許にきたり跪づきて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, '『主よ、わが子を憫みたまへ。癲癇にて難み、しばしば火の中に、しばしば水の中に倒るるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, '之を御弟子たちに連れ來りしに、醫すこと能はざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'イエス答へて言ひ給ふ『ああ信なき曲れる代なるかな、我いつまで汝らと偕にをらん、何時まで汝らを忍ばん。その子を我に連れきたれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, '遂にイエスこれを禁め給へば、惡鬼いでてその子この時より癒えたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'ここに弟子たち竊にイエスに來りて言ふ『われらは何 故に逐ひ出し得ざりしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, '彼らに言ひ給ふ『なんぢら信仰うすき故なり。まことに汝らに告ぐ、もし芥種 一粒ほどの信仰あらば、この山に「此處より彼處に移れ」と言ふとも移らん、かくて汝ら能はぬこと無かるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, '彼らガリラヤに集ひをる時、イエス言ひたまふ『人の子は人の手に付され、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, '人々は之を殺さん、かくて三日めに甦へるべし』弟子たち甚く悲しめり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, '彼らカペナウムに到りしとき、納金を集むる者どもペテロに來りて言ふ『なんぢらの師は納金を納めぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'ペテロ『納む』と言ひ、やがて家に入りしに、逸速くイエス言ひ給ふ『シモンいかに思ふか、世の王たちは税または貢を誰より取るか、己が子よりか、他の者よりか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'ペテロ言ふ『ほかの者より』イエス言ひ給ふ『されば子は自由なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'されど彼らを躓かせぬ爲に、海に往きて釣をたれ、初に上る魚をとれ、其の口をひらかば銀貨 一つを得ん、それを取りて我と汝との爲に納めよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'そのとき弟子たちイエスに來りて言ふ『しからば天國にて大なるは誰か』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'イエス幼兒を呼び、彼らの中に置きて言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, '『まことに汝らに告ぐ、もし汝ら飜へりて幼兒の如くならずば、天國に入るを得じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'されば誰にても此の幼兒のごとく己を卑うする者は、これ天國にて大なる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'また我が名のために、かくのごとき一人の幼兒を受くる者は、我を受くるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'されど我を信ずる此の小き者の一人を躓かする者は、寧ろ大なる碾臼を頸に懸けられ、海の深處に沈められんかた益なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'この世は躓物あるによりて禍害なるかな。躓物は必ず來らん、されど躓物を來らする人は禍害なるかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'もし汝の手または足なんぢを躓かせば、切りて棄てよ。不具または蹇跛にて生命に入るは、兩手 兩足ありて永遠の火に投げ入れらるるよりも勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'もし汝の眼なんぢを躓かせば、拔きて棄てよ。片眼にて生命に入るは、兩眼ありて火のゲヘナに投げ入れらるるよりも勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, '汝ら愼みて此の小き者の一人をも侮るな。我なんぢらに告ぐ、彼らの御使たちは天にありて、天にいます我が父の御顏を常に見るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, '汝 等いかに思ふか、百匹の羊を有てる人あらんに、若しその一匹まよはば、九 十 九 匹を山に遺しおき、往きて迷へるものを尋ねぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'もし之を見出さば、まことに汝らに告ぐ、迷はぬ九 十 九 匹に勝りて此の一匹を喜ばん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'かくのごとく此の小き者の一人の亡ぶるは、天にいます汝らの父の御意にあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'もし汝の兄弟 罪を犯さば、往きてただ彼とのみ相 對して諫めよ。もし聽かば其の兄弟を得たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'もし聽かずば、一人・二人を伴ひ往け、これ二 三の證人の口に由りて、凡ての事の慥められん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'もし彼 等にも聽かずば、教會に告げよ。もし教會にも聽かずば、之を異邦人または取税人のごとき者とすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'まことに汝らに告ぐ、すべて汝らが地にて縛ぐ所は天にても縛ぎ、地にて解く所は天にても解くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'また誠に汝らに告ぐ、もし汝 等のうち二人、何にても求むる事につき地にて心を一つにせば、天にいます我が父は之を成し給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, '二三人わが名によりて集る所には、我もその中に在るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'ここにペテロ御許に來りて言ふ『主よ、わが兄弟われに對して罪を犯さば幾たび赦すべきか、七度までか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'イエス言ひたまふ『否、われ「七度まで」とは言はず「七度を七 十 倍するまで」と言ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'この故に、天國はその家來どもと計算をなさんとする王のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, '計算を始めしとき、一萬タラントの負債ある家來つれ來られしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, '償ひ方なかりしかば、其の主人、この者とその妻 子と凡ての所有とを賣りて償ふことを命じたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'その家來ひれ伏し拜して言ふ「寛くし給へ、さらば悉とく償はん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'その家來の主人あはれみて之を解き、その負債を免したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, '然るに其の家來いでて、己より百デナリを負ひたる一人の同僚にあひ、之をとらへ、喉を締めて言ふ「負債を償へ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'その同僚ひれ伏し、願ひて「寛くし給へ、さらば償はん」と言へど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, '肯はずして往き、その負債を償ふまで之を獄に入れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, '同僚ども有りし事を見て甚く悲しみ、往きて有りし凡ての事をその主人に告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'ここに主人かれを呼び出して言ふ「惡しき家來よ、なんぢ願ひしによりて、かの負債をことごとく免せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'わが汝を憫みしごとく、汝もまた同僚を憫むべきにあらずや」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, '斯くその主人、怒りて、負債をことごとく償ふまで彼を獄卒に付せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'もし汝 等おのおの心より兄弟を赦さずば、我が天の父も亦なんぢらに斯のごとく爲し給ふべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'イエスこれらの言を語り終へて、ガリラヤを去り、ヨルダンの彼方なるユダヤの地方に來り給ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, '大なる群衆したがひたれば、此處にて彼らを醫し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'パリサイ人ら來り、イエスを試みて言ふ『何の故にかかはらず、人その妻を出すは可きか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, '答へて言ひたまふ『人を造り給ひしもの、元始より之を男と女とに造り、而して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, '「かかる故に人は父 母を離れ、その妻に合ひて、二人のもの一體となるべし」と言ひ給ひしを未だ讀まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'されば、はや二人にはあらず、一體なり。この故に神の合せ給ひし者は、人これを離すべからず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, '彼らイエスに言ふ『さらば何 故モーセは離縁状を與へて出すことを命じたるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, '彼らに言ひ給ふ『モーセは汝の心つれなきによりて妻を出すことを許したり。されど元始より然にはあらぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'われ汝らに告ぐ、おほよそ淫行の故ならで其の妻をいだし他に娶る者は、姦淫を行ふなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, '弟子たちイエスに言ふ『人もし妻のことに於てかくのごとくば、娶らざるに如かず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, '彼らに言ひたまふ『凡ての人この言を受け容るるにはあらず、ただ授けられたる者のみなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'それ生れながらの閹人あり、人に爲られたる閹人あり、また天國のために自らなりたる閹人あり、之を受け容れうる者は受け容るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'ここに人々イエスの手をおきて祈り給はんことを望みて、幼兒らを連れ來りしに、弟子たち禁めたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'イエス言ひたまふ『幼兒らを許せ、我に來るを止むな、天國はかくのごとき者の國なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'かくて手を彼らの上におきて此處を去り給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, '視よ、或 人みもとに來りて言ふ『師よ、われ永遠の生命をうる爲には、如何なる善き事を爲すべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'イエス言ひたまふ『善き事につきて何ぞ我に問ふか、善き者は唯ひとりのみ。汝もし生命に入らんと思はば誡命を守れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, '彼いふ『孰を』イエス言ひたまふ『「殺すなかれ」「姦淫するなかれ」「盜むなかれ」「僞證を立つる勿れ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, '「父と母とを敬へ」また「己のごとく汝の隣を愛すべし」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'その若者いふ『我みな之を守れり、なほ何を缺くか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'イエス言ひたまふ『なんぢ若し全からんと思はば、往きて汝の所有を賣りて貧しき者に施せ、さらば財寶を天に得ん。かつ來りて我に從へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'この言をききて、若者 悲しみつつ去りぬ。大なる資産を有てる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'イエス弟子たちに言ひ給ふ『まことに汝らに告ぐ、富める者の天國に入るは難し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, '復なんぢらに告ぐ、富める者の神の國に入るよりは、駱駝の針の孔を通るかた反つて易し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, '弟子たち之をきき、甚だしく驚きて言ふ『さらば誰か救はるることを得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'イエス彼らに目を注めて言ひ給ふ『これは人に能はねど、神は凡ての事をなし得るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'ここにペテロ答へて言ふ『視よ、われら一切をすてて汝に從へり、されば何を得べきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'イエス彼らに言ひ給ふ『まことに汝らに告ぐ、世あらたまりて人の子その榮光の座位に坐するとき、我に從へる汝 等もまた十二の座位に坐して、イスラエルの十二の族を審かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'また凡そ我が名のために、或は家、あるひは兄弟、あるひは姉妹、あるひは父、あるひは母、あるひは子、あるひは田畑を棄つる者は、數倍を受け、また永遠の生命を嗣がん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'されど多くの先なる者 後に、後なる者 先になるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '天國は勞動人を葡萄園に雇ふために、朝 早く出でたる主人のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, '一日 一デナリの約束をなして、勞動人どもを葡萄園に遣す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'また九時ごろ出でて市場に空しく立つ者どもを見て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, '「なんぢらも葡萄園に往け、相當のものを與へん」といへば、彼らも往く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, '十二 時 頃と三時 頃とに復いでて前のごとくす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, '五 時 頃また出でしに、なほ立つ者どものあるを見ていふ「何ゆゑ終日ここに空しく立つか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'かれら言ふ「たれも我らを雇はぬ故なり」主人いふ「なんぢらも葡萄園に往け」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, '夕になりて葡萄園の主人その家 司に言ふ「勞動人を呼びて、後の者より始め、先の者にまで賃銀をはらへ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'かくて五 時ごろに雇はれしもの來りて、おのおの一デナリを受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, '先の者きたりて、多く受くるならんと思ひしに、之も亦おのおの一デナリを受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, '受けしとき、家主にむかひ呟きて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, '「この後の者どもは僅に一 時間はたらきたるに、汝は一日の勞と暑さとを忍びたる我らと均しく之を遇へり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, '主人こたへて其の一人に言ふ「友よ、我なんぢに不正をなさず、汝は我と一デナリの約束をせしにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, '己が物を取りて往け、この後の者に汝とひとしく與ふるは、我が意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'わが物を我が意のままにするは可からずや、我よきが故に汝の目あしきか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'かくのごとく後なる者は先に、先なる者は後になるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'イエス、エルサレムに上らんとし給ふとき、竊に十二 弟子を近づけて、途すがら言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '『視よ、我らエルサレムに上る、人の子は祭司長・學者らに付されん。彼ら之を死に定め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'また嘲弄し、鞭うち、十字架につけん爲に異邦人に付さん、かくて彼は三日めに甦へるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'ここにゼベダイの子らの母、その子らと共に御許にきたり、拜して何事か求めんとしたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'イエス彼に言ひたまふ『何を望むか』かれ言ふ『この我が二人の子が汝の御國にて、一人は汝の右に、一人は左に坐せんことを命じ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'イエス答へて言ひ給ふ『なんぢらは求むる所を知らず、我が飮まんとする酒杯を飮み得るか』かれら言ふ『得るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'イエス言ひたまふ『實に汝らは我が酒杯を飮むべし、されど我が右 左に坐することは、これ我の與ふべきものならず、我が父より備へられたる人こそ與へらるるなれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, '十 人の弟子これを聞き、二人の兄弟の事によりて憤ほる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'イエス彼らを呼びて言ひたまふ『異邦人の君のその民を宰どり、大なる者の民の上に權を執ることは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, '汝らの中にては然らず、汝らの中に大ならんと思ふ者は、汝らの役者となり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, '首たらんと思ふ者は汝らの僕となるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'かくのごとく、人の子の來れるも事へらるる爲にあらず、反つて事ふることをなし、又おほくの人の贖償として己が生命を與へん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, '彼らエリコを出づるとき、大なる群衆イエスに從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, '視よ、二人の盲人、路の傍らに坐しをりしが、イエスの過ぎ給ふことを聞き、叫びて言ふ『主よ、ダビデの子よ、我らを憫みたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, '群衆かれらを禁めて默さしめんとしたれど、愈々 叫びて言ふ『主よ、ダビデの子よ、我らを憫み給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'イエス立ちどまり、彼らを呼びて言ひ給ふ『わが汝らに何を爲さんことを望むか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, '彼ら言ふ『主よ、目の開かれんことなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'イエスいたく憫みて彼らの目に觸り給へば、直ちに物 見ることを得て、イエスに從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, '彼らエルサレムに近づき、オリブ山の邊なるベテパゲに到りし時、イエス二人の弟子を遣さんとして言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, '『向の村にゆけ、やがて繋ぎたる驢馬のその子とともに在るを見ん、解きて我に牽ききたれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, '誰かもし汝らに何とか言はば「主の用なり」と言へ、さらば直ちに之を遣さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, '此の事の起りしは、預言者によりて云はれたる言の成就せん爲なり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '『シオンの娘に告げよ、「視よ、汝の王、なんぢに來り給ふ。柔和にして驢馬に乘り、軛を負ふ驢馬の子に乘りて」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, '弟子たち往きて、イエスの命じ給へる如くして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, '驢馬とその子とを牽ききたり、己が衣をその上におきたれば、イエス之に乘りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, '群衆の多くはその衣を途にしき、或 者は樹の枝を伐りて途に敷く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'かつ前にゆき後にしたがふ群衆よばはりて言ふ『ダビデの子にホサナ、讃むべきかな、主の御名によりて來る者。いと高き處にてホサナ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, '遂にエルサレムに入り給へば、都 擧りて騷 立ちて言ふ『これは誰なるぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, '群衆いふ『これガリラヤのナザレより出でたる預言者イエスなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'イエス宮に入り、その内なる凡ての賣買する者を逐ひいだし、兩替する者の臺、鴿を賣る者の腰掛を倒して言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, '『「わが家は祈の家と稱へらるべし」と録されたるに、汝らは之を強盜の巣となす』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, '宮にて盲人・跛者ども御許に來りたれば、之を醫したまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, '祭司長・學者らイエスの爲し給へる不思議なる業と、宮にて呼はり『ダビデの子にホサナ』と言ひをる子 等とを見、憤ほりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'イエスに言ふ『なんぢ彼らの言ふところを聞くか』イエス言ひ給ふ『然り「嬰兒 乳兒の口に讃美を備へ給へり」とあるを未だ讀まぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, '遂に彼らを離れ、都を出でてベタニヤにゆき、そこに宿り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, '朝 早く都にかへる時、イエス飢ゑたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, '路の傍なる一もとの無花果の樹を見て、その下に到り給ひしに、葉のほかに何をも見出さず、之に對ひて『今より後いつまでも果を結ばざれ』と言ひ給へば、無花果の樹たちどころに枯れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, '弟子たち之を見、怪しみて言ふ『無花果の樹の斯く立刻に枯れたるは何ぞや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'イエス答へて言ひ給ふ『まことに汝らに告ぐ、もし汝ら信仰ありて疑はずば、啻に此の無花果の樹にありし如きことを爲し得るのみならず、此の山に「移りて海に入れ」と言ふとも亦 成るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'かつ祈のとき何にても信じて求めば、ことごとく得べし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, '宮に到りて教へ給ふとき、祭司長・民の長老ら御許に來りて言ふ『何の權威をもて此 等の事をなすか、誰がこの權威を授けしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'イエス答へて言ひたまふ『我も一言なんぢらに問はん、もし夫を告げなば、我もまた何の權威をもて此 等のことを爲すかを告げん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'ヨハネのバプテスマは何處よりぞ、天よりか、人よりか』かれら互に論じて言ふ『もし天よりと言はば「何 故かれを信ぜざりし」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'もし人よりと言はんか、人みなヨハネを預言者と認むれば、我らは群衆を恐る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, '遂に答へて『知らず』と言へり。イエスもまた言ひたまふ『我も何の權威をもて此 等のことを爲すか汝らに告げじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'なんぢら如何に思ふか、或 人ふたりの子ありしが、その兄にゆきて言ふ「子よ、今日、葡萄園に往きて働け」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, '答へて「主よ、我ゆかん」と言ひて終に往かず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'また弟にゆきて同じやうに言ひしに、答へて「往かじ」と言ひたれど、後くいて往きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'この二人のうち孰か父の意を爲しし』彼らいふ『後の者なり』イエス言ひ給ふ『まことに汝らに告ぐ、取税人と遊女とは汝らに先だちて神の國に入るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'それヨハネ義の道をもて來りしに、汝らは彼を信ぜず、取税人と遊女とは信じたり。然るに汝らは之を見し後も、なほ悔改めずして信ぜざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'また一つの譬を聽け、ある家主、葡萄園をつくりて籬をめぐらし、中に酒槽を掘り、櫓を建て、農夫どもに貸して遠く旅立せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, '果期ちかづきたれば、その果を受取らんとて僕らを農夫どもの許に遣ししに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, '農夫どもその僕らを執へて、一人を打ちたたき、一人をころし、一人を石にて撃てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, '復ほかの僕らを前よりも多く遣ししに、之をも同じやうに遇へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, '「わが子は敬ふならん」と言ひて、遂にその子を遣ししに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, '農夫ども此の子を見て互に言ふ「これは世嗣なり、いざ殺して、その嗣業を取らん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'かくて之をとらへ、葡萄園の外に逐ひ出して殺せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'さらば葡萄園の主人きたる時、この農夫どもに何を爲さんか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'かれら言ふ『その惡人どもを飽くまで滅し、果期におよびて果を納むる他の農夫どもに葡萄園を貸し與ふべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'イエス言ひたまふ『聖書に、「造家者らの棄てたる石は、これぞ隅の首石となれる、これ主によりて成れるにて、我らの目には奇しきなり」とあるを汝ら未だ讀まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'この故に汝らに告ぐ、汝らは神の國をとられ、其の果を結ぶ國人は、之を與へらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'この石の上に倒るる者はくだけ、又この石、人のうへに倒るれば、其の人を微塵とせん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, '祭司長・パリサイ人ら、イエスの譬をきき、己らを指して語り給へるを悟り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'イエスを執へんと思へど群衆を恐れたり、群衆かれを預言者とするに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'イエスまた譬をもて答へて言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '『天國は己が子のために婚筵を設くる王のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, '婚筵に招きおきたる人々を迎へんとて僕どもを遺ししに、來るを肯はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, '復ほかの僕どもを遣すとて言ふ「招きたる人々に告げよ、視よ、晝餐は既に備りたり。我が牛も肥えたる畜も屠られて、凡ての物 備りたれば、婚筵に來れと」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, '然るに人々 顧みずして、或 者は己が畑に、或 者は己が商賣に往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'また他の者は僕を執へて、辱しめかつ殺したれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, '王 怒りて軍勢を遣し、かの兇行者を滅して其の町を燒きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'かくて僕どもに言ふ「婚筵は既に備りたれど、招きたる者どもは相應しからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'されば汝ら街に往きて、遇ふほどの者を婚筵に招け」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, '僕ども途に出でて、善きも惡しきも遇ふほどの者をみな集めたれば、婚禮の席は客にて滿てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, '王、客を見んとて入り來り、一人の禮服を著けぬ者あるを見て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, '之に言ふ「友よ、如何なれば禮服を著けずして此處に入りたるか」かれ默しゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'ここに王、侍者らに言ふ「その手 足を縛りて外の暗黒に投げいだせ、其處にて哀哭・切齒することあらん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'それ招かるる者は多かれど、選ばるる者は少し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'ここにパリサイ人ら出でて、如何にしてかイエスを言の羂に係けんと相 議り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'その弟子らをヘロデ黨の者どもと共に遺して言はしむ『師よ、我らは知る、なんじは眞にして、眞をもて神の道を教へ、かつ誰をも憚りたまふ事なし、人の外貌を見 給はぬ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'されば我らに告げたまへ、貢をカイザルに納むるは可きか、惡しきか、如何に思ひたまふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'イエスその邪曲なるを知りて言ひたまふ『僞善者よ、なんぞ我を試むるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, '貢の金を我に見せよ』彼らデナリ一つを持ち來る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'イエス言ひ給ふ『これは誰の像、たれの號なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, '彼ら言ふ『カイザルのなり』ここに彼らに言ひ給ふ『さらばカイザルの物はカイザルに、神の物は神に納めよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, '彼ら之を聞きて怪しみ、イエスを離れて去り往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, '復活なしといふサドカイ人ら、その日みもとに來り問ひて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, '『師よ、モーセは「人もし子なくして死なば、其の兄弟かれの妻を娶りて、兄弟のために世嗣を擧ぐべし」と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, '我らの中に七人の兄弟ありしが、兄めとりて死に、世嗣なくして其の妻を弟に遺したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'その二その三より、その七まで皆かくの如く爲し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, '最後にその女も死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'されば復活の時、その女は七人のうち誰の妻たるべきか、彼ら皆これを妻としたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'イエス答へて言ひ給ふ『なんぢら聖書をも神の能力をも知らぬ故に誤れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'それ人よみがへりの時は、娶らず嫁がず、天に在る御使たちの如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, '死人の復活に就きては、神なんぢらに告げて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '「我はアブラハムの神、イサクの神、ヤコブの神なり」と言ひ給へることを未だ讀まぬか。神は死にたる者の神にあらず、生ける者の神なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, '群衆これを聞きて其の教に驚けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'パリサイ人ら、イエスのサドカイ人らを默さしめ給ひしことを聞きて相 集り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'その中なる一人の教法師、イエスを試むる爲に問ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '『師よ、律法のうち孰の誡命が大なる』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'イエス言ひ給ふ『「なんぢ心を盡し、精神を盡し、思を盡して主なる汝の神を愛すべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'これは大にして第一の誡命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, '第二もまた之にひとし「おのれの如くなんぢの隣を愛すべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, '律法 全體と預言者とは此の二つの誡命に據るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'パリサイ人らの集りたる時、イエス彼らに問ひて言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '『なんぢらはキリストに就きて如何に思ふか、誰の子なるか』かれら言ふ『ダビデの子なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'イエス言ひ給ふ『さらばダビデ御靈に感じて何 故かれを主と稱ふるか。曰く');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '「主わが主に言ひ給ふ、われ汝の敵を汝の足の下に置くまでは、我が右に坐せよ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, '斯くダビデ彼を主と稱ふれば、爭でその子ならんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, '誰も一言だに答ふること能はず、その日より敢へて復イエスに問ふ者なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'ここにイエス群衆と弟子たちとに語りて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, '『學者とパリサイ人とはモーセの座を占む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'されば凡てその言ふ所は守りて行へ、されどその所作には效ふな、彼らは言ふのみにて行はぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'また重き荷を括りて人の肩にのせ、己は指にて之を動かさんともせず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, '凡てその所作は人に見られん爲にするなり。即ちその經札を幅ひろくし、衣の總を大くし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, '饗宴の上席、會堂の上座、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, '市場にての敬禮、また人にラビと呼ばるることを好む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'されど汝らはラビの稱を受くな、汝らの師は一人にして、汝 等はみな兄弟なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, '地にある者を父と呼ぶな、汝らの父は一人、すなはち天に在す者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'また導師の稱を受くな、汝らの導師はひとり、即ちキリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, '汝 等のうち大なる者は、汝らの役者とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, '凡そおのれを高うする者は卑うせられ、己を卑うする者は高うせらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, '禍害なるかな、僞善なる學者、パリサイ人よ、なんぢらは人の前に天國を閉して自ら入らず、入らんとする人の入るをも許さぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, '禍害なるかな、僞善なる學者、パリサイ人よ、汝らは一人の改宗者を得んために海 陸を經めぐり、既に得れば、之を己に倍したるゲヘナの子となすなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, '禍害なるかな、盲目なる手引よ、なんぢらは言ふ「人もし宮を指して誓はば事なし、宮の黄金を指して誓はば果さざるべからず」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, '愚にして盲目なる者よ、黄金と黄金を聖ならしむる宮とは孰か貴き。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'なんぢら又いふ「人もし祭壇を指して誓はば事なし、其の上の供物を指して誓はば果さざるべからず」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, '盲目なる者よ、供物と供物を聖ならしむる祭壇とは孰か貴き。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'されば祭壇を指して誓ふ者は、祭壇とその上の凡ての物とを指して誓ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, '宮を指して誓ふ者は、宮とその内に住みたまふ者とを指して誓ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'また天を指して誓ふ者は、神の御座とその上に坐したまふ者とを指して誓ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, '禍害なるかな、僞善なる學者、パリサイ人よ、汝らは薄荷・蒔蘿・クミンの十分の一を納めて、律法の中にて尤も重き公平と憐憫と忠信とを等閑にす。されど之は行ふべきものなり、而して、彼もまた等閑にすべきものならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, '盲目なる手引よ、汝らは蚋を漉し出して駱駝を呑むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, '禍害なるかな、僞善なる學者、パリサイ人よ、汝らは酒杯と皿との外を潔くす、されど内は貪慾と放縱とにて滿つるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, '盲目なるパリサイ人よ、汝まづ酒杯の内を潔めよ、さらば外も潔くなるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, '禍害なるかな、僞善なる學者、パリサイ人よ、汝らは白く塗りたる墓に似たり、外は美しく見ゆれども、内は死人の骨とさまざまの穢とにて滿つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'かくのごとく汝らも外は人に正しく見ゆれども、内は僞善と不法とにて滿つるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, '禍害なるかな、僞善なる學者、パリサイ人よ、汝らは預言者の墓をたて、義人の碑を飾りて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, '「我らもし先祖の時にありしならば、預言者の血を流すことに與せざりしものを」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'かく汝らは預言者を殺しし者の子たるを自ら證す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'なんぢら己が先祖の桝目を充せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, '蛇よ、蝮の裔よ、なんぢら爭でゲヘナの刑罰を避け得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'この故に視よ、我なんぢらに預言者・智者・學者らを遣さんに、其の中の或 者を殺し、十字架につけ、或 者を汝らの會堂にて鞭うち、町より町に逐ひ苦しめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, '之によりて義人アベルの血より、聖所と祭壇との間にて汝らが殺ししバラキヤの子ザカリヤの血に至るまで、地上にて流したる正しき血は、皆なんぢらに報い來らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'まことに汝らに告ぐ、これらの事はみな今の代に報い來るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'ああエルサレム、エルサレム、預言者たちを殺し、遣されたる人々を石にて撃つ者よ、牝鷄のその雛を翼の下に集むるごとく、我なんぢの子どもを集めんとせしこと幾度ぞや、されど汝らは好まざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, '視よ、汝らの家は廢てられて汝らに遺らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'われ汝らに告ぐ「讃むべきかな、主の名によりて來る者」と、汝 等のいふ時の至るまでは、今より我を見ざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'イエス宮を出でてゆき給ふとき、弟子たち宮の建造物を示さんとて御許に來りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, '答へて言ひ給ふ『なんぢら此の一切の物を見ぬか。誠に汝らに告ぐ、此處に一つの石も崩されずしては石の上に遺らじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'オリブ山に坐し給ひしとき、弟子たち竊に御許に來りて言ふ『われらに告げ給へ、これらの事は何時あるか、又なんぢの來り給ふと世の終とには、何の兆あるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'イエス答へて言ひ給ふ『なんぢら人に惑されぬやうに心せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, '多くの者わが名を冒し來り「我はキリストなり」と言ひて多くの人を惑さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, '又なんぢら戰爭と戰爭の噂とを聞かん、愼みて懼るな。かかる事はあるべきなり、されど未だ終にはあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, '即ち「民は民に、國は國に逆ひて起たん」また處々に饑饉と地震とあらん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, '此 等はみな産の苦難の始なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'そのとき人々なんぢらを患難に付し、また殺さん、汝 等わが名の爲に、もろもろの國人に憎まれん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'その時おほくの人つまづき、且たがひに付し、互に憎まん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, '多くの僞 預言者おこりて、多くの人を惑さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'また不法の増すによりて、多くの人の愛ひややかにならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'されど終まで耐へしのぶ者は救はるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, '御國のこの福音は、もろもろの國人に證をなさんため全世界に宣傅へられん、而してのち終は至るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'なんぢら預言者ダニエルによりて言はれたる「荒す惡むべき者」の聖なる處に立つを見ば(讀む者さとれ)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'その時ユダヤに居る者どもは山に遁れよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, '屋の上に居る者はその家の物を取り出さんとして下るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, '畑にをる者は上衣を取らんとて歸るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'その日には孕りたる者と乳を哺まする者とは禍害なるかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, '汝らの遁ぐることの冬または安息 日に起らぬように祈れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'そのとき大なる患難あらん、世の創より今に至るまでかかる患難はなく、また後にも無からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'その日もし少くせられずば、一人だに救はるる者なからん、されど選民の爲にその日 少くせらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'その時あるひは「視よ、キリスト此處にあり」或は「此處にあり」と言ふ者ありとも信ずな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, '僞キリスト・僞 預言者おこりて、大なる徴と不思議とを現し、爲し得べくば選民をも惑さんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, '視よ、あらかじめ之を汝らに告げおくなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'されば人もし汝らに「視よ、彼は荒野にあり」といふとも出で往くな「視よ、彼は部屋にあり」と言ふとも信ずな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, '電光の東より出でて西にまで閃きわたる如く、人の子の來るも亦 然らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'それ死骸のある處には鷲あつまらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'これらの日の患難ののち直ちに日は暗く、月は光を發たず、星は空より隕ち、天の萬象ふるひ動かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'そのとき人の子の兆、天に現れん。そのとき地上の諸族みな嘆き、かつ人の子の能力と大なる榮光とをもて、天の雲に乘り來るを見ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'また彼は使たちを大なるラッパの聲とともに遣さん。使たちは天の此の極より彼の極まで、四方より選民を集めん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, '無花果の樹よりの譬をまなべ、その枝すでに柔かくなりて葉 芽ぐめば、夏の近きを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'かくのごとく汝らも此 等のすべての事を見ば、人の子すでに近づきて門邊に到るを知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, '誠に汝らに告ぐ、これらの事ことごとく成るまで、今の代は過ぎ往くまじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, '天 地は過ぎゆかん、されど我が言は過ぎ往くことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'その日その時を知る者なし、天の使たちも知らず、子も知らず、ただ父のみ知り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'ノアの時のごとく人の子の來るも然あるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, '曾て洪水の前ノア方舟に入る日までは、人々 飮み食ひ、娶り嫁がせなどし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, '洪水の來りて悉とく滅すまでは知らざりき、人の子の來るも然あるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'そのとき二人の男 畑にをらんに、一人は取られ一人は遺されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, '二人の女 磨ひき居らんに、一人は取られ一人は遺されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'されば目を覺しをれ、汝らの主のきたるは、何れの日なるかを知らざればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, '汝 等これを知れ、家主もし盜人いづれの時きたるかを知らば、目をさまし居て、その家を穿たすまじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'この故に汝らも備へをれ、人の子は思はぬ時に來ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, '主人が時に及びて食物を與へさする爲に、家の者のうへに立てたる忠實にして慧き僕は誰なるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, '主人のきたる時、かく爲し居るを見らるる僕は幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'まことに汝らに告ぐ、主人すべての所有を彼に掌どらすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'もしその僕 惡しくして、心のうちに主人は遲しと思ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'その同輩を扑きはじめ、酒徒らと飮食を共にせば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'その僕の主人おもはぬ日しらぬ時に來りて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, '之を烈しく笞うち、その報を僞善者と同じうせん。其處にて哀哭・切齒することあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'このとき天國は、燈火を執りて新郎を迎へに出づる、十 人の處女に比ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'その中の五 人は愚にして五 人は慧し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, '愚なる者は燈火をとりて油を携へず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, '慧きものは油を器に入れて燈火とともに携へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, '新郎 遲かりしかば、皆まどろみて寢ぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, '夜半に「やよ、新郎なるぞ、出で迎へよ」と呼はる聲す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'ここに處女みな起きてその燈火を整へたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, '愚なる者は慧きものに言ふ「なんぢらの油を分けあたへよ、我らの燈火きゆるなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, '慧きもの答へて言ふ「恐らくは我らと汝らとに足るまじ、寧ろ賣るものに往きて己がために買へ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, '彼ら買はんとて往きたる間に新郎きたりたれば、備へをりし者どもは彼とともに婚筵にいり、而して門は閉されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'その後かの他の處女ども來りて「主よ、主よ、われらの爲にひらき給へ」と言ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, '答へて「まことに汝らに告ぐ、我は汝らを知らず」と言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'されば目を覺しをれ、汝らは其の日その時を知らざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'また或 人とほく旅立せんとして、其の僕どもを呼び、之に己が所有を預くるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, '各人の能力に應じて、或 者には五タラント、或 者には二タラント、或 者には一タラントを與へ置きて旅立せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, '五タラントを受けし者は、直ちに往き、之をはたらかせて他に五タラントを贏け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, '二タラントを受けし者も同じく他に二タラントを贏く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, '然るに一タラントを受けし者は、往きて地を掘り、その主人の銀をかくし置けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, '久しうして後この僕どもの主人きたりて彼らと計算したるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, '五タラントを受けし者は他に五タラントを持ちきたりて言ふ「主よ、なんぢ我に五タラントを預けたりしが、視よ、他に五タラントを贏けたり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, '主人いふ「宜いかな、善かつ忠なる僕、なんぢは僅なる物に忠なりき。我なんぢに多くの物を掌どらせん、汝の主人の勸喜に入れ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, '二タラントを受けし者も來りて言ふ「主よ、なんぢ我に二タラントを預けたりしが、視よ、他に二タラントを贏けたり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, '主人いふ「宜いかな、善かつ忠なる僕、なんぢは僅なる物に忠なりき。我なんぢに多くの物を掌どらせん、汝の主人の勸喜にいれ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'また一タラントを受けし者もきたりて言ふ「主よ、我はなんぢの嚴しき人にて、播かぬ處より刈り、散らさぬ處より斂むることを知るゆゑに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, '懼れてゆき、汝のタラントを地に藏しおけり。視よ、汝はなんぢの物を得たり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, '主人こたへて言ふ「惡しくかつ惰れる僕、わが播かぬ處より刈り、散さぬ處より斂むることを知るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'さらば我が銀を銀行にあづけ置くべかりしなり、我きたりて利子とともに我が物をうけ取りしものを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'されば彼のタラントを取りて十タラントを有てる人に與へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'すべて有てる人は、與へられて愈々 豐ならん。されど有たぬ者は、その有てる物をも取らるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, '而して此の無 益なる僕を外の暗黒に逐ひいだせ、其處にて哀哭・切齒することあらん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, '人の子その榮光をもて、もろもろの御使を率ゐきたる時、その榮光の座位に坐せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'かくてその前にもろもろの國人あつめられん、之を別つこと牧羊者が羊と山羊とを別つ如くして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, '羊をその右に、山羊をその左におかん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'ここに王その右にをる者どもに言はん「わが父に祝せられたる者よ、來りて世の創より汝 等のために備へられたる國を嗣げ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'なんぢら我が飢ゑしときに食はせ、渇きしときに飮ませ、旅人なりし時に宿らせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, '裸なりしときに衣せ、病みしときに訪ひ、獄に在りしときに來りたればなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'ここに、正しき者ら答へて言はん「主よ、何時なんぢの飢ゑしを見て食はせ、渇きしを見て飮ませし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, '何時なんぢの旅人なりしを見て宿らせ、裸なりしを見て衣せし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, '何時なんぢの病みまた獄に在りしを見て、汝にいたりし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, '王こたへて言はん「まことに汝らに告ぐ、わが兄弟なる此 等のいと小き者の一人になしたるは、即ち我に爲したるなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'かくてまた左にをる者どもに言はん「詛はれたる者よ、我を離れて惡魔とその使らとのために備へられたる永遠の火に入れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'なんぢら我が飢ゑしときに食はせず、渇きしときに飮ませず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, '旅人なりしときに宿らせず、裸なりしときに衣せず、病みまた獄にありしときに訪はざればなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'ここに彼らも答へて言はん「主よ、いつ汝の飢ゑ、或は渇き、或は旅人、あるひは裸、あるひは病み、或は獄に在りしを見て事へざりし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'ここに王こたへて言はん「誠になんぢらに告ぐ、此 等のいと小きものの一人に爲さざりしは、即ち我になさざりしなり」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'かくて、これらの者は去りて永遠の刑罰にいり、正しき者は永遠の生命に入らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'イエスこれらの言をみな語りをへて、弟子たちに言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '『なんぢらの知るごとく、二日の後は過越の祭なり、人の子は十字架につけられん爲に賣らるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'そのとき祭司長・民の長老ら、カヤパといふ大 祭司の中庭に集り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, '詭計をもてイエスを捕へ、かつ殺さんと相 議りたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, '又いふ『まつりの間は爲すべからず、恐らくは民の中に亂 起らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'イエス、ベタニヤにて癩病人シモンの家に居給ふ時、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'ある女、石膏の壺に入りたる貴き香 油を持ちて、近づき來り、食事の席に就き居給ふイエスの首に注げり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, '弟子たち之を見て憤ほり言ふ『何 故かく濫なる費をなすか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, '之を多くの金に賣りて、貧しき者に施すことを得たりしものを』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'イエス之を知りて言ひたまふ『何ぞこの女を惱すか、我に善き事をなせるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, '貧しき者は常に汝らと偕にをれど、我は常に偕に居らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'この女の我が體に香 油を注ぎしは、わが葬りの備をなせるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'まことに汝らに告ぐ、全世界いずこにても、この福音の宣傅へらるる處には、この女のなしし事も記念として語らるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'ここに十二 弟子の一人イスカリオテのユダといふ者、祭司長らの許にゆきて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, '『なんぢらに彼を付さば、何ほど我に與へんとするか』彼ら銀 三十を量り出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'ユダこの時よりイエスを付さんと好き機を窺ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, '除酵祭の初の日、弟子たちイエスに來りて言ふ『過越の食をなし給ふために、何處に我らが備ふる事を望み給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'イエス言ひたまふ『都にゆき、某のもとに到りて「師いふ、わが時 近づけり。われ弟子たちと共に過越を汝の家にて守らん」と言へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, '弟子たちイエスの命じ給ひし如くして、過越の備をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, '日 暮れて十二 弟子とともに席に就きて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, '食するとき言ひ給ふ『まことに汝らに告ぐ、汝らの中の一人われを賣らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, '弟子たち甚く憂ひて、おのおの『主よ、我なるか』と言ひいでしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, '答へて言ひたまふ『我とともに手を鉢に入るる者われを賣らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, '人の子は己に就きて録されたる如く逝くなり。されど人の子を賣る者は禍害なるかな、その人は生れざりし方よかりしものを』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'イエスを賣るユダ答へて言ふ『ラビ、我なるか』イエス言ひ給ふ『なんぢの言へる如し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, '彼ら食しをる時、イエス、パンをとり、祝してさき、弟子たちに與へて言ひ給ふ『取りて食へ、これは我が體なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'また酒杯をとりて謝し、彼らに與へて言ひ給ふ『なんぢら皆この酒杯より飮め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'これは契約のわが血なり、多くの人のために、罪の赦を得させんとて流す所のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'われ汝らに告ぐ、わが父の國にて新しきものを汝らと共に飮む日までは、われ今より後この葡萄の果より成るものを飮まじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, '彼ら讃美を歌ひて後オリブ山に出でゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'ここにイエス弟子たちに言ひ給ふ『今宵なんぢら皆われに就きて躓かん「われ牧羊者を打たん、さらば群の羊 散るべし」と録されたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'されど我よみがへりて後、なんぢらに先だちてガリラヤに往かん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'ペテロ答へて言ふ『假令みな汝に就きて躓くとも我はいつまでも躓かじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'イエス言ひ給ふ『まことに汝に告ぐ、こよひ鷄 鳴く前に、なんぢ三たび我を否むべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'ペテロ言ふ『我なんぢと共に死ぬべき事ありとも汝を否まず』弟子たち皆かく言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'ここにイエス彼らと共にゲツセマネといふ處にいたりて、弟子たちに言ひ給ふ『わが彼處にゆきて祈る間、なんぢら此處に坐せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'かくてペテロとゼベダイの子 二人とを伴ひゆき、憂ひ悲しみ出でて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, '『わが心いたく憂ひて死ぬばかりなり。汝ら此處に止りて我と共に目を覺しをれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, '少し進みゆきて、平伏し祈りて言ひ給ふ『わが父よ、もし得べくば此の酒杯を我より過ぎ去らせ給へ。されど我が意の儘にとにはあらず、御意のままに爲し給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, '弟子たちの許にきたり、その眠れるを見てペテロに言ひ給ふ『なんぢら斯く一 時も我と共に目を覺し居ること能はぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, '誘惑に陷らぬやう、目を覺しかつ祈れ。實に心は熱すれども肉體よわきなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'また二度ゆき祈りて言ひ給ふ『わが父よ、この酒杯もし我 飮までは過ぎ去りがたくば、御意のままに成し給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, '復きたりて彼らの眠れるを見たまふ、是その目 疲れたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'また離れゆきて、三たび同じ言にて祈り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, '而して弟子たちの許に來りて言ひ給ふ『今は眠りて休め。視よ、時 近づけり、人の子は罪人らの手に付さるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, '起きよ、我ら往くべし。視よ、我を賣るもの近づけり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'なほ語り給ふほどに、視よ、十二 弟子の一人なるユダ來る、祭司長・民の長老らより遣されたる大なる群衆、劍と棒とをもちて之に伴ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'イエスを賣る者あらかじめ合圖を示して言ふ『わが接吻する者はそれなり、之を捕へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'かくて直ちにイエスに近づき『ラビ、安かれ』といひて接吻したれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'イエス言ひたまふ『友よ、何とて來る』このとき人々すすみてイエスに手をかけて捕ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, '視よ、イエスと偕にありし者のひとり、手をのべ劍を拔きて、大 祭司の僕をうちて、その耳を切り落せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'ここにイエス彼に言ひ給ふ『なんぢの劍をもとに收めよ、すべて劍をとる者は劍にて亡ぶるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, '我わが父に請ひて、十二 軍に餘る御使を今あたへらるること能はずと思ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'もし然せば、斯くあるべく録したる聖書はいかで成就すべき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'この時イエス群衆に言ひ給ふ『なんぢら強盜に向ふごとく劍と棒とをもち、我を捕へんとて出で來るか。我は日々 宮に坐して教へたりしに、汝ら我を捕へざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'されどかくの如くなるは、みな預言者たちの書の成就せん爲なり』ここに弟子たち皆イエスを棄てて逃げさりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'イエスを捕へたる者ども、學者・長老らの集り居る大 祭司カヤパの許に曳きゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'ペテロ遠く離れ、イエスに從ひて大 祭司の中庭まで到り、その成行を見んとて、そこに入り下役どもと共に坐せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, '祭司長らと全 議會と、イエスを死に定めんとて、いつはりの證據を求めたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, '多くの僞證者いでたれども得ず。後に二人の者いでて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, '『この人は「われ神の宮を毀ち三日にて建て得べし」と云へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, '大 祭司たちてイエスに言ふ『この人々が汝に對して立つる證據に何をも答へぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'されどイエス默し居給ひたれば、大 祭司いふ『われ汝に命ず、活ける神に誓ひて我らに告げよ、汝はキリスト、神の子なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'イエス言ひ給ふ『なんぢの言へる如し。かつ我なんぢらに告ぐ、今より後、なんぢら人の子の全能者の右に坐し、天の雲に乘りて來るを見ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'ここに大 祭司おのが衣を裂きて言ふ『かれ瀆言をいへり、何ぞ他に證人を求めん。視よ、なんぢら今この瀆言をきけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'いかに思ふか』答へて言ふ『かれは死に當れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'ここに彼 等その御顏に唾し、拳にて搏ち、或 者どもは手掌にて批きて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, '『キリストよ、我らに預言せよ、汝をうちし者は誰なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'ペテロ外にて中庭に坐しゐたるに、一人の婢女きたりて言ふ『なんぢもガリラヤ人イエスと偕にゐたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'かれ凡ての人の前に肯はずして言ふ『われは汝の言ふことを知らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'かくて門まで出で往きたるとき、他の婢女かれを見て、其處にをる者どもに向ひて『この人はナザレ人イエスと偕にゐたり』と言へるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, '重ねて肯はず、契ひて『我はその人を知らず』といふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, '暫くして其處に立つ者ども近づきてペテロに言ふ『なんぢも慥にかの黨與なり、汝の國訛なんぢを表せり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'ここにペテロ盟ひかつ契ひて『我その人を知らず』と言ひ出づるをりしも、鷄 鳴きぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'ペテロ『にはとり鳴く前に、なんぢ三度われを否まん』と、イエスの言ひ給ひし御言を思ひだし、外に出でて甚く泣けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, '夜明けになりて、凡ての祭司長・民の長老ら、イエスを殺さんと相 議り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, '遂に之を縛り、曳きゆきて總督ピラトに付せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'ここにイエスを賣りしユダ、その死に定められ給ひしを見て悔い、祭司長・長老らに、かの三十の銀をかへして言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, '『われ罪なきの血を賣りて罪を犯したり』彼らいふ『われら何ぞ干らん、汝みづから當るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, '彼その銀を聖所に投げすてて去り、ゆきて自ら縊れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, '祭司長らその銀をとりて言ふ『これは血の價なれば、宮の庫に納むるは可からず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'かくて相 議り、その銀をもて陶工の畑を買ひ、旅人らの墓地とせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, '之によりて其の畑は、今に至るまで血の畑と稱へらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'ここに預言者エレミヤによりて云はれたる言は成就したり。曰く『かくて彼ら値積られしもの、即ちイスラエルの子らが値積りし者の價の銀 三十をとりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, '陶工の畑の代に之を與へたり。主の我に命じ給ひし如し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'さてイエス、總督の前に立ち給ひしに、總督 問ひて言ふ『なんぢはユダヤ人の王なるか』イエス言ひ給ふ『なんぢの言ふが如し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, '祭司長・長老ら訴ふれども、何をも答へ給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'ここにピラト彼に言ふ『聞かぬか、彼らが汝に對して如何におほくの證據を立つるを』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'されど總督の甚く怪しむまで、一言をも答へ給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, '祭の時には、總督 群衆の望にまかせて、囚人 一人を之に赦す例あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'ここにバラバといふ隱れなき囚人あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'されば人々の集れる時、ピラト言ふ『なんぢら我が誰を赦さんことを願ふか。バラバなるか、キリストと稱ふるイエスなるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'これピラト彼らのイエスを付ししは嫉に因ると知る故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, '彼なほ審判の座にをる時、その妻、人を遣して言はしむ『かの義人に係ることを爲な、我けふ夢の中にて彼の故にさまざま苦しめり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, '祭司長・長老ら、群衆にバラバの赦されん事を請はしめ、イエスを亡さんことを勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, '總督こたへて彼らに言ふ『二人の中いづれを我が赦さん事を願ふか』彼らいふ『バラバなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'ピラト言ふ『さらばキリストと稱ふるイエスを我いかにすべきか』皆いふ『十字架につくべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'ピラト言ふ『かれ何の惡事をなしたるか』彼ら烈しく叫びていふ『十字架につくべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'ピラトは何の效なく反つて亂にならんとするを見て、水をとり群衆のまへに手を洗ひて言ふ『この人の血につきて我は罪なし、汝 等みづから當れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, '民みな答へて言ふ『其の血は、我らと我らの子孫とに歸すべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'ここにピラト、バラバを彼らに赦し、イエスを鞭うちて、十字架につくる爲に付せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'ここに總督の兵卒ども、イエスを官邸につれゆき、全 隊を御許に集め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'その衣をはぎて、緋色の上衣をきせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, '茨の冠冕を編みて、その首に冠らせ、葦を右の手にもたせ、且その前に跪づき、嘲弄して言ふ『ユダヤ人の王、安かれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'また之に唾し、かの葦をとりて其の首を叩く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'かく嘲弄してのち、上衣を剥ぎて、故の衣をきせ、十字架につけんとて曳きゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'その出づる時、シモンといふクレネ人にあひしかば、強ひて之にイエスの十字架をおはしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'かくてゴルゴタといふ處、即ち髑髏の地にいたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, '苦味を混ぜたる葡萄酒を飮ませんとしたるに、嘗めて、飮まんとし給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, '彼らイエスを十字架につけてのち、籤をひきて其の衣をわかち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, '且そこに坐して、イエスを守る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'その首の上に『これはユダヤ人の王イエスなり』と記したる罪標を置きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'ここにイエスとともに二人の強盜、十字架につけられ、一人はその右に、一人はその左におかる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, '往來の者どもイエスを譏り、首を振りていふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, '『宮を毀ちて三日のうちに建つる者よ、もし神の子ならば己を救へ、十字架より下りよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, '祭司長らもまた同じく、學者・長老らとともに嘲弄して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '『人を救ひて己を救ふこと能はず。彼はイスラエルの王なり、いま十字架より下りよかし、さらば我ら彼を信ぜん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, '彼は神に依り頼めり、神かれを愛しまば今すくひ給ふべし「我は神の子なり」と云へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'ともに十字架につけられたる強盜どもも、同じ事をもてイエスを罵れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, '晝の十二 時より地の上あまねく暗くなりて、三時に及ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, '三時ごろイエス大聲に叫びて『エリ、エリ、レマ、サバクタニ』と言ひ給ふ。わが神、わが神、なんぞ我を見 棄て給ひしとの意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'そこに立つ者のうち或 人々これを聞きて『彼はエリヤを呼ぶなり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, '直ちにその中の一人はしりゆきて海綿をとり、酸き葡萄酒を含ませ、葦につけてイエスに飮ましむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'その他の者ども言ふ『まて、エリヤ來りて彼を救ふや否や、我ら之を見ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'イエス再び大聲に呼はりて息 絶えたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, '視よ、聖所の幕、上より下まで裂けて二つとなり、また地震ひ、磐さけ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, '墓ひらけて、眠りたる聖徒の屍體おほく活きかへり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'イエスの復活ののち墓をいで、聖なる都に入りて、多くの人に現れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, '百卒長および之と共にイエスを守りゐたる者ども、地震とその有りし事とを見て甚く懼れ『實に彼は神の子なりき』と言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'その處にて遙に望みゐたる多くの女あり、イエスに事へてガリラヤより從ひ來りし者どもなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'その中には、マグダラのマリヤ、ヤコブとヨセフとの母マリヤ、及びゼベダイの子らの母などもゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, '日 暮れて、ヨセフと云ふアリマタヤの富める人きたる。彼もイエスの弟子なるが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'ピラトに往きてイエスの屍體を請ふ。ここにピラト之を付すことを命ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'ヨセフ屍體をとりて淨き亞麻 布につつみ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, '岩にほりたる己が新しき墓に納め、墓の入口に大なる石を轉しおきて去りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, '其處にはマグダラのマリヤと他のマリヤと墓に向ひて坐しゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'あくる日、即ち準備 日の翌日、祭司長らとパリサイ人らとピラトの許に集りて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, '『主よ、かの惑すもの生き居りし時「われ三日の後に甦へらん」と言ひしを、我ら思ひいだせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'されば命じて三日に至るまで墓を固めしめ給へ、恐らくはその弟子ら來りて之を盜み、「彼は死人の中より甦へれり」と民に言はん。然らば後の惑は前のよりも甚だしからん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'ピラト言ふ『なんぢらに番兵あり、往きて力 限り固めよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, '乃ち彼らゆきて石に封印し、番兵を置きて墓を固めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'さて安息 日をはりて、一週の初の日のほの明き頃、マグダラのマリヤと他のマリヤと墓を見んとて來りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, '視よ、大なる地震あり、これ主の使、天より降り來りて、かの石を轉し退け、その上に坐したるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'その状は電光のごとく輝き、その衣は雪のごとく白し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, '守の者ども彼を懼れたれば、戰きて死人の如くなりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, '御使こたへて女たちに言ふ『なんぢら懼るな、我なんぢらが十字架につけられ給ひしイエスを尋ぬるを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, '此處には在さず、その言へる如く甦へり給へり。來りてその置かれ給ひし處を見よ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'かつ速かに往きて、その弟子たちに「彼は死人の中より甦へり給へり。視よ、汝らに先だちてガリラヤに往き給ふ、彼處にて謁ゆるを得ん」と告げよ。視よ、汝らに之を告げたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, '女たち懼と大なる歡喜とをもて、速かに墓を去り、弟子たちに知らせんとて走りゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, '視よ、イエス彼らに遇ひて『安かれ』と言ひ給ひたれば、進みゆき、御足を抱きて拜す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'ここにイエス言ひたまふ『懼るな、往きて我が兄弟たちに、ガリラヤにゆき、彼處にて我を見るべきことを知らせよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, '女たちの往きたるとき、視よ、番兵のうちの數人、都にいたり、凡て有りし事どもを祭司長らに告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, '祭司長ら、長老らと共に集りて相 議り、兵卒どもに多くの銀を與へて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, '『なんぢら言へ「その弟子ら夜きたりて、我らの眠れる間に彼を盜めり」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'この事もし總督に聞えなば、我ら彼を宥めて汝らに憂なからしめん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, '彼ら銀をとりて言ひ含められたる如くしたれば、此の話ユダヤ人の中にひろまりて、今日に至れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, '十 一 弟子たちガリラヤに往きて、イエスの命じ給ひし山にのぼり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, '遂に謁えて拜せり。されど疑ふ者もありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'イエス進みきたり、彼らに語りて言ひたまふ『我は天にても地にても一切の權を與へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'されば汝ら往きて、もろもろの國人を弟子となし、父と子と聖 靈との名によりてバプテスマを施し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'わが汝らに命ぜし凡ての事を守るべきを教へよ。視よ、我は世の終まで常に汝らと偕に在るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, '神の子イエス、キリストの福音の始。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, '預言者イザヤの書に、『視よ、我なんぢの顏の前に、わが使を遣す、彼なんぢの道を設くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, '荒野に呼はる者の聲す、「主の道を備へ、その路すぢを直くせよ」』と録されたる如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'バプテスマのヨハネ出で、荒野にて罪の赦を得さする悔改のバプテスマを宣傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'ユダヤ全國またエルサレムの人々、みな其の許に出で來りて罪を言ひあらはし、ヨルダン川にてバプテスマを受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'ヨハネは駱駝の毛織を著、腰に皮の帶して、蝗と野蜜とを食へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'かれ宣傳へて言ふ『我よりも力ある者、わが後に來る。我は屈みてその鞋の紐をとくにも足らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, '我は水にて汝らにバプテスマを施せり。されど彼は聖 靈にてバプテスマを施さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'その頃イエス、ガリラヤのナザレより來り、ヨルダンにてヨハネよりバプテスマを受け給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'かくて水より上るをりしも、天さけゆき、御靈、鴿のごとく己に降るを見 給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'かつ天より聲 出づ『なんぢは我が愛しむ子なり、我なんぢを悦ぶ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'かくて御靈ただちにイエスを荒野に逐ひやる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, '荒野にて四十 日の間サタンに試みられ、獸とともに居給ふ、御使たち之に事へぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'ヨハネの囚はれし後、イエス、ガリラヤに到り、神の福音を宣傳へて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, '『時は滿てり、神の國は近づけり、汝ら悔改めて福音を信ぜよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'イエス、ガリラヤの海にそひて歩みゆき、シモンと其の兄弟アンデレとが、海に網うちをるを見 給ふ。かれらは漁人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'イエス言ひ給ふ『われに從ひきたれ、汝 等をして人を漁る者とならしめん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, '彼ら直ちに網をすてて從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, '少し進みゆきて、ゼベダイの子ヤコブとその兄弟ヨハネとを見 給ふ、彼らも舟にありて網を繕ひゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, '直ちに呼び給へば、父ゼベダイを雇人とともに舟に遺して從ひゆけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'かくて彼らカペナウムに到る、イエス直ちに安息 日に會堂にいりて教へ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, '人々その教に驚きあへり。それは學者の如くならず、權威ある者のごとく教へ給ふゆゑなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, '時にその會堂に、穢れし靈に憑かれたる人あり、叫びて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, '『ナザレのイエスよ、我らは汝と何の關係あらんや、汝は我らを亡さんとて來給ふ。われは汝の誰なるを知る、神の聖者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'イエス禁めて言ひ給ふ『默せ、その人を出でよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, '穢れし靈その人を痙攣けさせ、大聲をあげて出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, '人々みな驚き相 問ひて言ふ『これ何事ぞ、權威ある新しき教なるかな、穢れし靈すら命ずれば從ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'ここにイエスの噂あまねくガリラヤの四方に弘りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, '會堂をいで、直ちにヤコブとヨハネとを伴ひて、シモン及びアンデレの家に入り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'シモンの外姑、熱をやみて臥しゐたれば、人々ただちに之をイエスに告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'イエス往きて、その手をとり、起し給へば、熱さりて女かれらに事ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, '夕となり、日いりてのち、人々すべての病ある者・惡鬼に憑かれたる者をイエスに連れ來り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, '全町こぞりて門に集る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'イエスさまざまの病を患ふ多くの人をいやし、多くの惡鬼を逐ひいだし、之に物 言ふことを免し給はず、惡鬼イエスを知るに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, '朝まだき暗き程に、イエス起き出でて、寂しき處にゆき、其處にて祈りゐたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'シモン及び之と偕にをる者ども、その跡を慕ひゆき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'イエスに遇ひて言ふ『人みな汝を尋ぬ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'イエス言ひ給ふ『いざ最寄の村々に往かん、われ彼處にも教を宣ぶべし、我はこの爲に出で來りしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, '遂にゆきて、徧くガリラヤの會堂にて教を宣べ、かつ惡鬼を逐ひ出し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, '一人の癩病人みもとに來り、跪づき請ひて言ふ『御意ならば、我を潔くなし給ふを得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'イエス憫みて、手をのべ彼につけて『わが意なり、潔くなれ』と言ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, '直ちに癩病さりて、その人きよまれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'やがて彼を去らしめんとて、嚴しく戒めて言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, '『つつしみて誰にも語るな、唯ゆきて己を祭司に見せ、モーセが命じたる物を汝の潔のために献げて、人々に證せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'されど彼いでて此の事を大に述べつたへ、徧く弘め始めたれば、この後イエスあらはに町に入りがたく、外の寂しき處に留りたまふ。人々 四方より御許に來れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, '數日の後、またカペナウムに入り給ひしに、その家に在することを聞きて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, '多くの人あつまり來り、門口すら隙間なき程なり。イエス彼らに御言を語り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'ここに四人に擔はれたる中風の者を人々つれ來る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, '群衆によりて御許にゆくこと能はざれば、在す所の屋根を穿ちあけて、中風の者を床のまま縋り下せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'イエス彼らの信仰を見て、中風の者に言ひたまふ『子よ、汝の罪ゆるされたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'ある學者たち其處に坐しゐたるが、心の中に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '『この人なんぞ斯く言ふか、これは神を瀆すなり、神ひとりの外は誰か罪を赦すことを得べき』と論ぜしかば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'イエス直ちに彼 等がかく論ずるを心に悟りて言ひ給ふ『なにゆゑ斯かることを心に論ずるか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, '中風の者に「なんぢの罪ゆるされたり」と言ふと「起きよ、床をとりて歩め」と言ふと、孰か易き。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, '人の子の地にて罪を赦す權威ある事を、汝らに知らせん爲に』――中風の者に言ひ給ふ――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '『なんぢに告ぐ、起きよ、床をとりて家に歸れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, '彼おきて直ちに床をとりあげ、人々の眼前いで往けば、皆おどろき、かつ神を崇めて言ふ『われら斯くの如きことは斷えて見ざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'イエスまた海邊に出でゆき給ひしに、群衆みもとに集ひ來りたれば、之を教へ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'かくて過ぎ往くとき、アルパヨの子レビの收税所に坐しをるを見て『われに從へ』と言ひ給へば、立ちて從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, '而して其の家にて食事の席につき居給ふとき、多くの取税人・罪人ら、イエス及び弟子たちと共に席に列る、これらの者おほく居て、イエスに從へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'パリサイ人の學者ら、イエスの罪人・取税人とともに食し給ふを見て、その弟子たちに言ふ『なにゆゑ取税人・罪人とともに食するか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'イエス聞きて言ひ給ふ『健かなる者は醫者を要せず、ただ病ある者これを要す。我は正しき者を招かんとにあらで、罪人を招かんとて來れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'ヨハネの弟子とパリサイ人とは、斷食しゐたり。人々イエスに來りて言ふ『なにゆゑヨハネの弟子とパリサイ人の弟子とは斷食して、汝の弟子は斷食せぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'イエス言ひ給ふ『新郎の友だち、新郎と偕にをるうちは斷食し得べきか、新郎と偕にをる間は、斷食するを得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'されど新郎をとらるる日きたらん、その日には斷食せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, '誰も新しき布の裂を舊き衣に縫ひつくることは爲じ。もし然せば、その補ひたる新しきものは、舊き物をやぶり、破綻さらに甚だしからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, '誰も新しき葡萄酒を、ふるき革嚢に入るることは爲じ。もし然せば、葡萄酒は嚢をはりさきて、葡萄酒も嚢も廢らん。新しき葡萄酒は、新しき革嚢に入るるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'イエス安息 日に麥 畠をとほり給ひしに、弟子たち歩みつつ穗を摘み始めたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'パリサイ人、イエスに言ふ『視よ、彼らは何ゆゑ安息 日に爲まじき事をするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, '答へ給ふ『ダビデその伴へる人々と共に乏しくして飢ゑしとき爲しし事を未だ讀まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, '即ち大 祭司アビアタルの時、ダビデ神の家に入りて、祭司のほかは食ふまじき供のパンを取りて食ひ、おのれと偕なる者にも與へたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'また言ひたまふ『安息 日は人のために設けられて、人は安息 日のために設けられず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'されば人の子は安息 日にも主たるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'また會堂に入り給ひしに、片手なえたる人あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, '人々イエスを訴へんと思ひて、安息 日にかの人を醫すや否やと窺ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'イエス手なえたる人に『中に立て』といひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'また人々に言ひたまふ『安息 日に善をなすと惡をなすと、生命を救ふと殺すと、孰かよき』彼ら默然たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'イエスその心の頑固なるを憂ひて、怒り見囘して、手なえたる人に『手を伸べよ』と言ひ給ふ。かれ手を伸べたれば癒ゆ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'パリサイ人いでて、直ちにヘロデ黨の人とともに、如何にしてイエスを亡さんと議る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'イエスその弟子とともに海邊に退き給ひしに、ガリラヤより來れる夥多しき民衆も從ふ。又ユダヤ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'エルサレム、イドマヤ、ヨルダンの向の地、およびツロ、シドンの邊より夥多しき民衆その爲し給へる事を聞きて、御許に來る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'イエス群衆のおしなやますを逃れんとて、小舟を備へ置くことを弟子に命じ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'これ多くの人を醫し給ひたれば、凡て病に苦しむもの、御體に觸らんとて押迫る故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'また穢れし靈イエスを見る毎に、御前に平伏し、叫びて『なんぢは神の子なり』と言ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, '我を顯すなとて、嚴しく戒め給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'イエス山に登り、御意に適ふ者を召し給ひしに、彼ら御許に來る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'ここに十二 人を擧げたまふ。是かれらを御側におき、また教を宣べさせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, '惡鬼を逐ひ出す權威を用ひさする爲に、遣さんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, '此の十二 人を擧げて、シモンにペテロといふ名をつけ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'ゼベダイの子ヤコブ、その兄弟ヨハネ、此の二人にボアネルゲ、即ち雷霆の子といふ名をつけ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, '又アンデレ、ピリポ、バルトロマイ、マタイ、トマス、アルパヨの子ヤコブ、タダイ、熱心 黨のシモン、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, '及びイスカリオテのユダ、このユダはイエスを賣りしなり。かくてイエス家に入り給ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, '群衆また集り來りたれば、食事する暇もなかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'その親族の者これを聞き、イエスを取押へんとて出で來る、イエスを狂へりと謂ひてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, '又エルサレムより下れる學者たちも『彼はベルゼブルに憑かれたり』と言ひ、かつ『惡鬼の首によりて惡鬼を逐ひ出すなり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'イエス彼らを呼びよせ、譬にて言ひ給ふ『サタンはいかでサタンを逐ひ出し得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'もし國 分れ爭はば、其の國 立つこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'もし家 分れ爭はば、其の家 立つこと能はざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'もしサタン己に逆ひて分れ爭はば、立つこと能はず、反つて亡び果てん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, '誰にても先づ強き者を縛らずば、強き者の家に入りて其の家財を奪ふこと能はじ、縛りて後その家を奪ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'まことに汝らに告ぐ、人の子らの凡ての罪と、けがす瀆とは赦されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'されど聖 靈をけがす者は、永遠に赦されず、永遠の罪に定めらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'これは彼らイエスを『穢れし靈に憑かれたり』と云へるが故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'ここにイエスの母と兄弟と來りて外に立ち、人を遣してイエスを呼ばしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, '群衆イエスを環りて坐したりしが、或 者いふ『視よ、なんぢの母と兄弟 姉妹と外にありて汝を尋ぬ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'イエス答へて言ひ給ふ『わが母、わが兄弟とは誰ぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'かくて周圍に坐する人々を見囘して言ひたまふ『視よ、これは我が母、わが兄弟なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, '誰にても神の御意を行ふものは、是わが兄弟、わが姉妹、わが母なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'イエスまた海邊にて教へ始めたまふ。夥多しき群衆、みもとに集りたれば、舟に乘り海に泛びて坐したまひ、群衆はみな海に沿ひて陸にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, '譬にて數多の事ををしへ、教の中に言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '『聽け、種 播くもの、播かんとて出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, '播くとき、路の傍らに落ちし種あり、鳥きたりて啄む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, '土うすき磽地に落ちし種あり、土 深からぬによりて、速かに萠え出でたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, '日 出でてやけ、根なき故に枯る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, '茨の中に落ちし種あり、茨そだち塞ぎたれば、實を結ばず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, '良き地に落ちし種あり、生え出でて茂り、實を結ぶこと、三十 倍、六十 倍、百 倍せり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'また言ひ給ふ『きく耳ある者は聽くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'イエス人々を離れ居給ふとき、御許にをる者ども、十二 弟子とともに、此 等の譬を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'イエス言ひ給ふ『なんぢらには神の國の奧義を與ふれど、外の者には、凡て譬にて教ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'これ「見るとき見ゆとも認めず、聽くとき聞ゆとも悟らず、飜へりて赦さるる事なからん」爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'また言ひ給ふ『なんぢら此の譬を知らぬか、さらば爭でもろもろの譬を知り得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, '播く者は御言を播くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, '御言の播かれて路の傍らにありとは、かかる人をいふ、即ち聞くとき、直ちにサタン來りて、その播かれたる御言を奪ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, '同じく播かれて磽地にありとは、かかる人をいふ、即ち御言をききて、直ちに喜び受くれども、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'その中に根なければ、ただ暫し保つのみ、御言のために患難また迫害にあふ時は、直ちに躓くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'また播かれて茨の中にありとは、かかる人をいふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'すなはち御言をきけど、世の心勞、財貨の惑、さまざまの慾いりきたり、御言を塞ぐによりて、遂に實らざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, '播かれて良き地にありとは、かかる人をいふ、即ち御言を聽きて受け、三十 倍、六十 倍、百 倍の實を結ぶなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'また言ひたまふ『升のした、寢臺の下におかんとて、燈火をもち來るか、燈臺の上におく爲ならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'それ顯るる爲ならで隱るるものなく、明かにせらるる爲ならで秘めらるるものなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, '聽く耳ある者は聽くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'また言ひ給ふ『なんぢら聽くことに心せよ、汝らが量る量にて量られ、更に増し加へらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'それ有てる人は、なほ與へられ、有たぬ人は、有てる物をも取らるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'また言ひたまふ『神の國は、或 人たねを地に播くが如し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, '日夜 起臥するほどに、種はえ出でて育てども、その故を知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, '地はおのづから實を結ぶものにして、初には苗、つぎに穗、つひに穗の中に充ち足れる穀なる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, '實みのれば直ちに鎌を入る、收穫時の到れるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'また言ひ給ふ『われら神の國を何になずらへ、如何なる譬をもて示さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, '一粒の芥種のごとし、地に播く時は、世にある萬の種よりも小けれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, '既に播きて生え出づれば、萬の野菜よりは大く、かつ大なる枝を出して、空の鳥その蔭に棲み得るほどになるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'かくのごとき數多の譬をもて、人々の聽きうる力に隨ひて、御言を語り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, '譬ならでは語り給はず、弟子たちには、人なき時に凡ての事を釋き給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'その日、夕になりて言ひ給ふ『いざ彼方に往かん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, '弟子たち群衆を離れ、イエスの舟にゐ給ふまま共に乘り出づ、他の舟も從ひゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, '時に烈しき颶風おこり、浪うち込みて、舟に滿つるばかりなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'イエスは艫の方に茵を枕として寢ねたまふ。弟子たち呼び起して言ふ『師よ、我らの亡ぶるを顧み給はぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'イエス起きて風をいましめ、海に言ひたまふ『默せ、鎭れ』乃ち風やみて、大なる凪となりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'かくて弟子たちに言ひ給ふ『なに故かく臆するか、信仰なきは何ぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'かれら甚く懼れて互に言ふ『こは誰ぞ、風も海も順ふとは』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'かくて海の彼方なるゲラセネ人の地に到る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'イエスの舟より上り給ふとき、穢れし靈に憑かれたる人、墓より出でて直ちに遇ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'この人、墓を住處とす、鏈にてすら今は誰も繋ぎ得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, '彼はしばしば足械と鏈とにて繋がれたれど、鏈をちぎり、足械をくだきたり、誰も之を制する力なかりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, '夜も晝も、絶えず墓あるひは山にて叫び、己が身を石にて傷つけゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'かれ遙にイエスを見て、走りきたり、御前に平伏し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, '大聲に叫びて言ふ『いと高き神の子イエスよ、我は汝と何の關係あらん、神によりて願ふ、我を苦しめ給ふな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'これはイエス『穢れし靈よ、この人より出で往け』と言ひ給ひしに因るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'イエスまた『なんぢの名は何か』と問ひ給へば『わが名はレギオン、我ら多きが故なり』と答へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'また己らを此の地の外に逐ひやり給はざらんことを切に求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, '彼處の山邊に豚の大なる群、食しゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, '惡鬼どもイエスに求めて言ふ『われらを遣して豚に入らしめ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'イエス許したまふ。穢れし靈いでて、豚に入りたれば、二千 匹ばかりの群、海に向ひて崖を駈けくだり、海に溺れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, '飼ふ者ども逃げ往きて、町にも里にも告げたれば、人々 何事の起りしかを見んとて出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'かくてイエスに來り、惡鬼に憑かれたりし者、即ちレギオンをもちたりし者の、衣服をつけ、慥なる心にて坐しをるを見て、懼れあへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'かの惡鬼に憑かれたる者の上にありし事と、豚の事とを見し者ども、之を具に告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, '人々イエスにその境を去り給はん事を求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'イエス舟に乘らんとし給ふとき、惡鬼に憑かれたりしもの偕に在らん事を願ひたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, '許さずして言ひ給ふ『なんぢの家に、親しき者に歸りて、主がいかに大なる事を汝に爲し、いかに汝を憫み給ひしかを告げよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, '彼ゆきて、イエスの如何に大なる事を己になし給ひしかを、デカポリスに言ひ弘めたれば、人々みな怪しめり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'イエス舟にて復かなたに渡り給ひしに、大なる群衆みもとに集る、イエス海邊に在せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, '會堂 司の一人、ヤイロという者きたり、イエスを見て、その足下に伏し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, '切に願ひて言ふ『わが稚なき娘、いまはの際なり、來りて手をおき給へ、さらば救はれて活くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'イエス彼と共にゆき給へば、大なる群衆したがひつつ御許に押迫る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'ここに十 二年 血漏を患ひたる女あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, '多くの醫者に多く苦しめられ、有てる物をことごとく費したれど、何の效なく、反つて増々 惡しくなりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'イエスの事をききて、群衆にまじり、後に來りて、御衣にさはる、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, '『その衣にだに觸らば救はれん』と自ら謂へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'かくて血の泉ただちに乾き、病のいえたるを身に覺えたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'イエス直ちに能力の己より出でたるを自ら知り、群衆の中にて、振反り言ひたまふ『誰が我の衣に觸りしぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, '弟子たち言ふ『群衆の押迫るを見て、誰が我に觸りしぞと言ひ給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'イエスこの事を爲しし者を見んとて見囘し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, '女おそれ戰き、己が身になりし事を知り、來りて御前に平伏し、ありしままを告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'イエス言ひ給ふ『娘よ、なんぢの信仰なんぢを救へり、安らかに往け、病いえて健かになれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'かく語り給ふほどに、會堂 司の家より人々きたりて言ふ『なんぢの娘は早や死にたり、爭でなほ師を煩はすべき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'イエス其の告ぐる言を傍より聞きて、會堂 司に言ひたまふ『懼るな、ただ信ぜよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'かくてペテロ、ヤコブその兄弟ヨハネの他は、ともに往く事を誰にも許し給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, '彼ら會堂 司の家に來る。イエス多くの人の、甚く泣きつ叫びつする騷を見、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, '入りて言ひ給ふ『なんぞ騷ぎかつ泣くか、幼兒は死にたるにあらず、寐ねたるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, '人々イエスを嘲笑ふ。イエス彼 等をみな外に出し、幼兒の父と母と己に伴へる者とを率きつれて、幼兒のをる處に入り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, '幼兒の手を執りて『タリタ、クミ』と言ひたまふ。少女よ、我なんぢに言ふ、起きよ、との意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, '直ちに少女たちて歩む、その歳 十二なりければなり。彼ら直ちに甚く驚きおどろけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'イエス此の事を誰にも知れぬやうにせよと、堅く彼らを戒め、また食物を娘に與ふることを命じ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'かくて其處をいで、己が郷に到り給ひしに、弟子たちも從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, '安息 日になりて、會堂にて教へ始め給ひしに、聞きたる多くのもの驚きて言ふ『この人は此 等のことを何處より得しぞ、此の人の授けられたる智慧は何ぞ、その手にて爲すかくのごとき能力あるわざは何ぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, '此の人は木匠にして、マリヤの子、またヤコブ、ヨセ、ユダ、シモンの兄弟ならずや、其の姉妹も此處に我らと共にをるに非ずや』遂に彼に躓けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'イエス彼らに言ひたまふ『預言者は、おのが郷、おのが親族、おのが家の外にて尊ばれざる事なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, '彼處にては、何の能力ある業をも行ひ給ふこと能はず、ただ少數の病める者に、手をおきて醫し給ひしのみ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, '彼らの信仰なきを怪しみ給へり。かくて村々を歴 巡りて教へ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'また十二 弟子を召し、二人づつ遣しはじめ、穢れし靈を制する權威を與へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'かつ旅のために、杖 一つの他は、何をも持たず、糧も嚢も帶の中に錢をも持たず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'ただ草鞋ばかりをはきて、二つの下衣をも著ざることを命じ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'かくて言ひたまふ『何處にても人の家に入らば、その地を去るまで其處に留れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, '何地にても汝らを受けず、汝らに聽かずば、其處を出づるとき、證のために足の裏の塵を拂へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'ここに弟子たち出で往きて、悔改むべきことを宣傅へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, '多くの惡鬼を逐ひいだし、多くの病める者に油をぬりて醫せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'かくてイエスの名 顯れたれば、ヘロデ王ききて言ふ『バプテスマのヨハネ死人の中より甦へりたり。この故に此 等の能力その中に働くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, '或 人は『エリヤなり』といひ、或 人は『預言者、いにしへの預言者のごとき者なり』といふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'ヘロデ聞きて言ふ『わが首斬りしヨハネ、かれ甦へりたるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'ヘロデ先にその娶りたる己が兄弟ピリポの妻ヘロデヤの爲に、みづから人を遣し、ヨハネを捕へて獄に繋げり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'ヨハネ、ヘロデに『その兄弟の妻を納るるは宣しからず』と言へるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'ヘロデヤ、ヨハネを怨みて殺さんと思へど能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'それはヘロデ、ヨハネの義にして聖なる人たるを知りて、之を畏れ、之を護り、且つその教をききて、大に惱みつつも、なほ喜びて聽きたる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, '然るに機よき日 來れり。ヘロデ己が誕生日に、大臣・將校・ガリラヤの貴人たちを招きて饗宴せしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'かのヘロデヤの娘いり來りて、舞をまひ、ヘロデと其の席に列れる者とを喜ばしむ。王、少女に言ふ『何にても欲しく思ふものを求めよ、我あたへん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'また誓ひて言ふ『なんぢ求めば、我が國の半までも與へん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, '娘いでて母にいふ『何を求むべきか』母いふ『バプテスマのヨハネの首を』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, '娘ただちに急ぎて王の許に入りきたり、求めて言ふ『ねがはくは、バプテスマのヨハネの首を盆に載せて速かに賜はれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, '王いたく憂ひたれど、その誓と席に在る者とに對して拒むことを好まず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, '直ちに衞兵を遣し、之にヨハネの首を持ち來ることを命ず、衞兵ゆきて、獄にてヨハネを首斬り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'その首を盆にのせ、持ち來りて少女に與ふ、少女これを母に與ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'ヨハネの弟子たち聞きて來り、その屍體を取りて墓に納めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, '使徒たちイエスの許に集りて、その爲ししこと、教へし事をことごとく告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'イエス言ひ給ふ『なんぢら人を避け、寂しき處に、いざ來りて暫し息へ』これは往來の人おほくして、食する暇だになかりし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'かくて人を避け、舟にて寂しき處にゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, '其の往くを見て、多くの人それと知り、その處を指して、町々より徒歩にてともに走り、彼 等よりも先に往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'イエス出でて大なる群衆を見、その牧ふ者なき羊の如くなるを甚く憫みて、多くの事を教へはじめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, '時すでに晩くなりたれば、弟子たち御許に來りていふ『ここは寂しき處、はや時も晩し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, '人々を去らしめ、周圍の里また村に往きて、己がために食物を買はせ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, '答へて言ひ給ふ『なんぢら食物を與へよ』弟子たち言ふ『われら往きて二 百デナリのパンを買ひ、これに與へて食はすべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'イエス言ひ給ふ『パン幾つあるか、往きて見よ』彼ら見ていふ『五つ、また魚 二つあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'イエス凡ての人の組々となりて、青 草の上に坐することを命じ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, '或は百 人、あるひは五 十 人、畝のごとく列びて坐す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'かくてイエス五つのパンと二つの魚とを取り、天を仰ぎて祝し、パンをさき、弟子たちに付して人々の前に置かしめ、二つの魚をも人 毎に分け給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, '凡ての人 食ひて飽きたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'パンの餘、魚の殘を集めしに、十二の筐に滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'パンを食ひたる男は五 千 人なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'イエス直ちに、弟子たちを強ひて舟に乘らせ、自ら群衆を返す間に、彼方なるベツサイダに先に往かしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, '群衆に別れてのち、祈らんとて山にゆき給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, '夕になりて、舟は海の眞中にあり、イエスはひとり陸に在す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, '風 逆ふに因りて、弟子たちの漕ぎ煩ふを見て、夜明の四時ごろ、海の上を歩み、その許に到りて、往き過ぎんとし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, '弟子たち其の海の上を歩み給ふを見、變化の者ならんと思ひて叫ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, '皆これを見て心 騷ぎたるに因る。イエス直ちに彼らに語りて言ひ給ふ『心 安かれ、我なり、懼るな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'かくて弟子たちの許にゆき、舟に登り給へば、風やみたり。弟子たち心の中にて甚く驚く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, '彼らは先のパンの事をさとらず、反つて其の心 鈍くなりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, '遂に渡りてゲネサレの地に著き、舟がかりす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, '舟より上りしに、人々ただちにイエスを認めて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, '徧くあたりを馳せまはり、その在すと聞く處々に、患ふ者を床のままつれ來る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'その到りたまふ處には、村にても、町にても、里にても、病める者を市場におきて、御衣の總にだに觸らしめ給はんことを願ふ。觸りし者は、みな醫されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'パリサイ人と或 學者らと、エルサレムより來りてイエスの許に集る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, '而して、その弟子たちの中に、潔からぬ手、即ち洗はぬ手にて食事する者のあるを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'パリサイ人および凡てのユダヤ人は、古への人の言傳を固く執りて、懇ろに手を洗はねば食はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'また市場より歸りては、まず禊がざれば食はず。このほか酒杯・鉢・銅の器を濯ぐなど、多くの傳を承けて固く執りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'パリサイ人および學者らイエスに問ふ『なにゆゑ汝の弟子たちは、古への人の言傳に遵ひて歩まず、潔からぬ手にて食事するか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'イエス言ひ給ふ『イザヤは汝ら僞善者につきて能く預言せり。「この民は口唇にて我を敬ふ、されどその心は我に遠ざかる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'ただ徒らに我を拜む、人の訓誡を教とし教へて」と録したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'なんぢらは神の誡命を離れて、人の言傳を固く執る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'また言ひたまふ『汝 等はおのれの言傳を守らんとて、能くも神の誡命を棄つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, '即ちモーセは「なんぢの父、なんぢの母を敬へ」といひ「父また母を詈る者は、必ず殺さるべし」といへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, '然るに汝らは「人もし父また母にむかひ、我が汝に對して負ふ所のものは、コルバン即ち供物なりと言はば可し」と言ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'そののち人をして、父また母に事ふること無からしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'かく汝らの傳へたる言傳によりて、神の言を空しうし、又おほく此の類の事をなしをるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, '更に群衆を呼び寄せて言ひ給ふ『なんぢら皆われに聽きて悟れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, '外より人に入りて、人を汚し得るものなし、されど人より出づるものは、これ人を汚すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'イエス群衆を離れて家に入り給ひしに、弟子たち其の譬を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, '彼らに言ひ給ふ『なんぢらも然か悟なきか、外より人に入る物の、人を汚しえぬを悟らぬか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'これ心には入らず、腹に入りて厠におつるなり』かく凡ての食物を潔しとし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'また言ひたまふ『人より出づるものは、これ人を汚すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'それ内より、人の心より、惡しき念いづ、即ち淫行・竊盜・殺人、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, '姦淫・慳貪・邪曲・詭計・好色・嫉妬・誹謗・傲慢・愚痴。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'すべて此 等の惡しき事は、内より出でて人を汚すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'イエス起ちて此處を去り、ツロの地方に往き、家に入りて人に知られじとし給ひたれど、隱るること能はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'ここに穢れし靈に憑かれたる稚なき娘をもてる女、ただちにイエスの事をきき、來りて御足の許に平伏す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'この女はギリシヤ人にて、スロ・フェニキヤの生なり。その娘より惡鬼を逐ひ出し給はんことを請ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'イエス言ひ給ふ『まづ子供に飽かしむべし、子供のパンをとりて小狗に投げ與ふるは善からず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, '女こたへて言ふ『然り、主よ、食卓の下の小狗も子供の食屑を食ふなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'イエス言ひ給ふ『なんぢ此の言によりて[安んじ]往け、惡鬼は既に娘より出でたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'をんな家に歸りて見るに、子は寢臺の上に臥し、惡鬼は既に出でたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'イエスまたツロの地方を去りて、シドンを過ぎ、デカポリスの地方を經て、ガリラヤの海に來り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, '人々、耳聾にして物 言ふこと難き者を連れ來りて、之に手をおき給はんことを願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'イエス群衆の中より、彼をひとり連れ出し、その兩耳に指をさし入れ、また唾して其の舌に觸り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, '天を仰ぎて嘆じ、その人に對ひて『エパタ』と言ひ給ふ、ひらけよとの意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'かくてその耳ひらけ、舌の縺ただちに解け、正しく物いへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'イエス誰にも告ぐなと人々を戒めたまふ。されど戒むるほど反つて愈々 言ひ弘めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'また甚だしく打驚きて言ふ『かれの爲しし事は皆よし、聾者をも聞えしめ、唖者をも物いはしむ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'その頃また大なる群衆にて食ふべき物なかりしかば、イエス弟子たちを召して言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '『われ此の群衆を憫む、既に三日われと偕にをりて、食ふべき物なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, '飢ゑしままにて其の家に歸らしめば、途にて疲れ果てん。其の中には遠くより來れる者あり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, '弟子たち答へて言ふ『この寂しき地にては、何處よりパンを得て、この人々を飽かしむべき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'イエス問ひ給ふ『パン幾つあるか』答へて『七つ』といふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'イエス群衆に命じて地に坐せしめ、七つのパンを取り、謝して之を裂き、弟子たちに與へて群衆の前におかしむ。弟子たち乃ちその前におく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'また小き魚すこしばかりあり、祝して、之をもその前におけと言ひ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, '人々 食ひて飽き、裂きたる餘を拾ひしに、七つの籃に滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'その人おほよそ四千 人なりき。イエス彼らを歸し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, '直ちに弟子たちと共に舟に乘りて、ダルマヌタの地方に往き給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'パリサイ人いで來りて、イエスと論じはじめ、之を試みて天よりの徴をもとむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'イエス心に深く歎じて言ひ給ふ『なにゆゑ今の代は徴を求むるか、まことに汝らに告ぐ、徴は今の代に斷えて與へられじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'かくて彼らを離れ、また舟に乘りて彼方に往き給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, '弟子たちパンを携ふることを忘れ、舟には唯一つの他パンなかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'イエス彼らを戒めて言ひたまふ『愼みて、パリサイ人のパンだねと、ヘロデのパンだねとに心せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, '弟子たち互に、これはパン無き故ならんと語り合ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'イエス知りて言ひたまふ『何ぞパン無き故ならんと語り合ふか、未だ知らぬか、悟らぬか、汝らの心なほ鈍きか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, '目ありて見ぬか、耳ありて聽かぬか。又なんぢら思ひ出でぬか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, '五つのパンを裂きて、五 千 人に與へし時、その餘を幾筐ひろひしか』弟子たち言ふ『十二』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '『七つのパンを裂きて四千 人に與へし時、その餘を幾籃ひろひしか』弟子たち言ふ『七つ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'イエス言ひたまふ『未だ悟らぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, '彼ら遂にベツサイダに到る。人々、盲人をイエスに連れ來りて、觸り給はんことを願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'イエス盲人の手をとりて、村の外に連れ往き、その目に唾し、御手をあてて『なにか見ゆるか』と問ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, '見 上げて言ふ『人を見る、それは樹の如き物の歩くが見ゆ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'また御手をその目にあて給へば、視凝めたるに、癒えて凡てのもの明かに見えたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'かくて『村にも入るな』と言ひて、その家に歸し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'イエス其の弟子たちとピリポ・カイザリヤの村々に出でゆき、途にて弟子たちに問ひて言ひたまふ『人々は我を誰と言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, '答へて言ふ『バプテスマのヨハネ、或 人はエリヤ、或 人は預言者の一人』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'また問ひ給ふ『なんぢらは我を誰と言ふか』ペテロ答へて言ふ『なんぢはキリストなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'イエス己がことを誰にも告ぐなと、彼らを戒め給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'かくて人の子の必ず多くの苦難をうけ、長老・祭司長・學者らに棄てられ、かつ殺され、三日の後に甦へるべき事を教へはじめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, '此の事をあらはに語り給ふ。ここにペテロ、イエスを傍にひきて戒め出でたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'イエス振反りて弟子たちを見、ペテロを戒めて言ひ給ふ『サタンよ、わが後に退け、汝は神のことを思はず、反つて人のことを思ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'かくて群衆を弟子たちと共に呼び寄せて言ひたまふ『人もし我に從ひ來らんと思はば、己をすて、己が十字架を負ひて我に從へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, '己が生命を救はんと思ふ者は、これを失ひ、我が爲また福音の爲に己が生命をうしなふ者は、之を救はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, '人、全世界を贏くとも、己が生命を損せば、何の益あらん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, '人その生命の代に何を與へんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, '不義なる罪 深き今の代にて、我または我が言を恥づる者をば、人の子もまた、父の榮光をもて、聖なる御使たちと共に來らん時に恥づべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'また言ひ給ふ『まことに汝らに告ぐ、此處に立つ者のうちに、神の國の、權能をもて來るを見るまでは、死を味はぬ者どもあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, '六日の後、イエスただペテロ、ヤコブ、ヨハネのみを率きつれ、人を避けて高き山に登りたまふ。かくて彼らの前にて其の状かはり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, '其の衣かがやきて甚だ白くなりぬ、世の晒布者を爲し得ぬほど白し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'エリヤ、モーセともに彼らに現れて、イエスと語りゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'ペテロ差出でてイエスに言ふ『ラビ、我らの此處に居るは善し。われら三つの廬を造り、一つを汝のため、一つをモーセのため、一つをエリヤのためにせん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, '彼 等いたく懼れたれば、ペテロ何と言ふべきかを知らざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'かくて雲おこり、彼らを覆ふ。雲より聲 出づ『これは我が愛しむ子なり、汝ら之に聽け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, '弟子たち急ぎ見囘すに、イエスと己らとの他には、はや誰も見えざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, '山をくだる時、イエス彼らに、人の子の、死人の中より甦へるまでは、見しことを誰にも語るなと戒め給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, '彼ら此の言を心にとめ『死人の中より甦へる』とは、如何なる事ぞと互に論じ合ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'かくてイエスに問ひて言ふ『學者たちは、何 故エリヤまづ來るべしと言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'イエス言ひ給ふ『實にエリヤ先づ來りて、萬の事をあらたむ。さらば人の子につき、多くの苦難を受け、かつ蔑せらるる事の録されたるは何ぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'されど我なんぢらに告ぐ、エリヤは既に來れり。然るに彼に就きて録されたる如く、人々 心のままに之を待へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, '相 共に弟子たちの許に來りて、大なる群衆の之を環り、學者たちの之と論じゐたるを見 給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, '群衆みなイエスを見るや否や、いたく驚き、御許に走り往きて禮をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'イエス問ひ給ふ『なんぢら何を彼らと論ずるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, '群衆のうちの一人こたふ『師よ、唖の靈に憑かれたる我が子を御許に連れ來れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, '靈いづこにても彼に憑けば、痙攣け泡をふき、齒をくひしばり、而して痩せ衰ふ。御弟子たちに之を逐ひ出すことを請ひたれど能はざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'ここに彼らに言ひ給ふ『ああ信なき代なるかな、我いつまで汝らと偕にをらん、何時まで汝らを忍ばん。その子を我が許に連れきたれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, '乃ち連れきたる。彼イエスを見しとき、靈ただちに之を痙攣けたれば、地に倒れ、泡をふきて轉び廻る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'イエスその父に問ひ給ふ『いつの頃より斯くなりしか』父いふ『をさなき時よりなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, '靈しばしば彼を火のなか水の中に投げ入れて亡さんとせり。されど汝なにか爲し得ば、我らを憫みて助け給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'イエス言ひたまふ『爲し得ばと言ふか、信ずる者には、凡ての事なし得らるるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'その子の父ただちに叫びて言ふ『われ信ず、信仰なき我を助け給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'イエス群衆の走り集るを見て、穢れし靈を禁めて言ひたまふ『唖にて耳聾なる靈よ、我なんぢに命ず、この子より出でよ、重ねて入るな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, '靈さけびて甚だしく痙攣けさせて出でしに、その子、死人の如くなりたれば、多くの者これを死にたりと言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'イエスその手を執りて起し給へば立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'イエス家に入り給ひしとき、弟子たち竊に問ふ『我等いかなれば逐ひ出し得ざりしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, '答へ給ふ『この類は祈に由らざれば、如何にすとも出でざるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, '此處を去りてガリラヤを過ぐ。イエス人の此の事を知るを欲し給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'これは弟子たちに教をなし、かつ『人の子は人々の手にわたされ、人々これを殺し、殺されて三日ののち甦へるべし』と言ひ給ふが故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, '弟子たちはその言を悟らず、また問ふ事を恐れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'かくてカペナウムに到る。イエス家に入りて弟子たちに問ひ給ふ『なんぢら途すがら何を論ぜしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, '弟子たち默然たり、これは途すがら、誰か大ならんと、互に爭ひたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'イエス坐して十二 弟子を呼び、之に言ひたまふ『人もし頭たらんと思はば、凡ての人の後となり、凡ての人の役者となるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'かくてイエス幼兒をとりて彼らの中におき、之を抱きて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '『おほよそ我が名のために斯かる幼兒の一人を受くる者は、我を受くるなり。我を受くる者は、我を受くるにあらず、我を遣しし者を受くるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'ヨハネ言ふ『師よ、我らに從はぬ者の、御名によりて惡鬼を逐ひ出すを見しが、我らに從はぬ故に、之を止めたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'イエス言ひたまふ『止むな、我が名のために能力ある業をおこなひ、俄に我を譏り得る者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, '我らに逆はぬ者は、我らに附く者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'キリストの者たるによりて、汝らに一杯の水を飮まする者は、我まことに汝らに告ぐ、必ずその報を失はざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'また我を信ずる此の小き者の一人を躓かする者は、寧ろ大なる碾臼を頸に懸けられて、海に投げ入れられんかた勝れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'もし汝の手なんぢを躓かせば、之を切り去れ、不具にて生命に入るは、兩手ありてゲヘナの消えぬ火に往くよりも勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'もし汝の足なんぢを躓かせば、之を切り去れ、蹇跛にて生命に入るは、兩足ありてゲヘナに投げ入れらるるよりも勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'もし汝の眼なんぢを躓かせば、之を拔き出せ、片眼にて神の國に入るは、兩眼ありてゲヘナに投げ入れらるるよりも勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, '「彼處にては、その蛆つきず、火も消えぬなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'それ人はみな火をもて鹽つけらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, '鹽は善きものなり、されど鹽もし其の鹽 氣を失はば、何をもて之に味つけん。汝ら心の中に鹽を保ち、かつ互に和ぐべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'イエス此處をたちて、ユダヤの地方およびヨルダンの彼方に來り給ひしに、群衆またも御許に集ひたれば、常のごとく教へ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, '時にパリサイ人ら來り試みて問ふ『人その妻を出すはよきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, '答へて言ひ給ふ『モーセは汝らに何と命ぜしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, '彼ら言ふ『モーセは離縁状を書きて出すことを許せり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'イエス言ひ給ふ『汝らの心つれなきによりて、此の誡命を録ししなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'されど開闢の初より「人を男と女とに造り給へり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, '「かかる故に人はその父 母を離れて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, '二人のもの一體となるべし」さればはや二人にはあらず、一體なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'この故に神の合せ給ふものは、人これを離すべからず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, '家に入りて弟子たち復この事を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'イエス言ひ給ふ『おほよそ其の妻を出して他に娶る者は、その妻に對して姦淫を行ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'また妻もし其の夫を棄てて他に嫁がば、姦淫を行ふなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'イエスの觸り給はんことを望みて、人々 幼兒らを連れ來りしに、弟子たち禁めたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'イエス之を見、いきどほりて言ひたまふ『幼兒らの我に來るを許せ、止むな、神の國は斯くのごとき者の國なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'まことに汝らに告ぐ、凡そ幼兒の如くに神の國をうくる者ならずば、之に入ること能はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'かくて幼兒を抱き、手をその上におきて祝し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'イエス途に出で給ひしに、一人はしり來り、跪づきて問ふ『善き師よ、永遠の生命を嗣ぐためには、我なにを爲すべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'イエス言ひ給ふ『なにゆゑ我を善しと言ふか、神ひとりの他に善き者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, '誡命は汝が知るところなり「殺すなかれ」「姦淫するなかれ」「盜むなかれ」「僞證を立つるなかれ」「欺き取るなかれ」「汝の父と母とを敬へ」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, '彼いふ『師よ、われ幼き時より皆これを守れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'イエス彼に目をとめ、愛しみて言ひ給ふ『なんぢ尚ほ一つを缺く、往きて汝の有てる物をことごとく賣りて、貧しき者に施せ、さらば財寶を天に得ん。且きたりて我に從へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'この言によりて、彼は憂を催し、悲しみつつ去りぬ、大なる資産をもてる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'イエス見囘して弟子たちに言ひたまふ『富ある者の神の國に入るは如何に難いかな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, '弟子たち此の御言に驚く。イエスまた答へて言ひ給ふ『子たちよ、神の國に入るは如何に難いかな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, '富める者の神の國に入るよりは、駱駝の針の孔を通るかた反つて易し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, '弟子たち甚く驚きて互に言ふ『さらば誰か救はるる事を得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'イエス彼らに目を注めて言ひたまふ『人には能はねど、神には然らず、夫れ神は凡ての事をなし得るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'ペテロ、イエスに對ひて『我らは一切をすてて汝に從ひたり』と言ひ出でたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'イエス言ひ給ふ『まことに汝らに告ぐ、我がため、福音のために、或は兄弟、あるひは姉妹、或は父、或は母、或は子、或は田畑をすつる者は、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, '誰にても今、今の時に百 倍を受けぬはなし。即ち家・兄弟・姉妹・母・子・田畑を迫害と共に受け、また後の世にては、永遠の生命を受けぬはなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'されど多くの先なる者は後に、後なる者は先になるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'エルサレムに上る途にて、イエス先だち往き給ひしかば、弟子たち驚き、隨ひ往く者ども懼れたり。イエス再び十二 弟子を近づけて、己が身に起らんとする事どもを語り出で給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '『視よ、我らエルサレムに上る。人の子は祭司長・學者らに付されん。彼ら死に定めて、異邦人に付さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, '異邦人は嘲弄し、唾し、鞭うち、遂に殺さん、かくて彼は三日の後に甦へるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'ここにゼベダイの子ヤコブ、ヨハネ御許に來りて言ふ『師よ、願はくは我らが何にても求むる所を爲したまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'イエス言ひ給ふ『わが汝らに何を爲さんことを望むか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, '彼ら言ふ『なんぢの榮光の中にて、一人をその右に、一人をその左に坐せしめ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'イエス言ひ給ふ『なんぢらは求むる所を知らず、汝 等わが飮む酒杯を飮み、我が受くるバプテスマを受け得るか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, '彼 等いふ『得るなり』イエス言ひ給ふ『なんぢら我が飮む酒杯を飮み、また我が受くるバプテスマを受くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'されど我が右 左に坐することは、我の與ふべきものならず、ただ備へられたる人こそ與へらるるなれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, '十 人の弟子これを聞き、ヤコブとヨハネとの事により憤ほり出でたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'イエス彼らを呼びて言ひたまふ『異邦人の君と認めらるる者の、その民を宰どり、大なる者の、民の上に權を執ることは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'されど汝らの中にては然らず、反つて大ならんと思ふ者は、汝らの役者となり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, '頭たらんと思ふ者は、凡ての者の僕となるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, '人の子の來れるも、事へらるる爲にあらず、反つて事ふることをなし、又おほくの人の贖償として己が生命を與へん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'かくて彼らエリコに到る。イエスその弟子たち及び大なる群衆と共に、エリコを出でたまふ時、テマイの子バルテマイといふ盲目の乞食、路の傍に坐しをりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'ナザレのイエスなりと聞き、叫び出して言ふ『ダビデの子イエスよ、我を憫みたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, '多くの人かれを禁めて默さしめんとしたれど、ますます叫びて『ダビデの子よ、我を憫みたまへ』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'イエス立ち止りて『かれを呼べ』と言ひ給へば、人々 盲人を呼びて言ふ『心 安かれ、起て、なんぢを呼びたまふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, '盲人うはぎを脱ぎ捨て、躍り上りて、イエスの許に來りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'イエス答へて言ひ給ふ『わが汝に何を爲さんことを望むか』盲人いふ『わが師よ、見えんことなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'イエス彼に『ゆけ、汝の信仰なんぢを救へり』と言ひ給へば、直ちに見ることを得、イエスに從ひて途を往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, '彼らエルサレムに近づき、オリブ山の麓なるベテパゲ及びベタニヤに到りし時、イエス二人の弟子を遣さんとして言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, '『むかひの村にゆけ、其處に入らば、やがて人の未だ乘りたることなき驢馬の子の繋ぎあるを見ん、それを解きて牽き來れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, '誰かもし汝らに「なにゆゑ然するか」と言はば「主の用なり、彼ただちに返さん」といへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, '弟子たち往きて、門の外の路に驢馬の子の繋ぎあるを見て解きたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, '其處に立つ人々のうちの或 者『なんぢら驢馬の子を解きて何とするか』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, '弟子たちイエスの告げ給ひし如く言ひしに、彼ら許せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'かくて弟子たち驢馬の子をイエスの許に牽ききたり、己が衣をその上に置きたれば、イエス之に乘り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, '多くの人は己が衣を、或 人は野より伐り取りたる樹の枝を途に敷く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'かつ前に往き後に從ふ者ども呼はりて言ふ『「ホサナ、讃むべきかな、主の御名によりて來る者」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, '讃むべきかな、今し來る我らの父ダビデの國。「いと高き處にてホサナ」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, '遂にエルサレムに到りて宮に入り、凡ての物を見囘し、時はや暮に及びたれば、十二 弟子と共にベタニヤに出で往きたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'あくる日かれらベタニヤより出で來りし時、イエス飢ゑ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, '遙に葉ある無花果の樹を見て、果をや得んと其のもとに到り給ひしに、葉のほかに何をも見出し給はず、是は無花果の時ならぬに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'イエスその樹に對ひて言ひたまふ『今より後いつまでも、人なんぢの果を食はざれ』弟子たち之を聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, '彼らエルサレムに到る。イエス宮に入り、その内にて賣買する者どもを逐ひ出し、兩替する者の臺、鴿を賣るものの腰掛を倒し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'また器物を持ちて宮の内を過ぐることを免し給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'かつ教へて言ひ給ふ『「わが家は、もろもろの國人の祈の家と稱へらるべし」と録されたるにあらずや、然るに汝らは之を「強盜の巣」となせり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, '祭司長・學者ら之を聞き、如何にしてかイエスを亡さんと謀る、それは群衆みな其の教に驚きたれば、彼を懼れしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, '夕になる毎に、イエス弟子たちと共に都を出でゆき給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, '彼ら朝 早く路をすぎしに、無花果の樹の根より枯れたるを見る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'ペテロ思ひ出してイエスに言ふ『ラビ、見 給へ、詛ひ給ひし無花果の樹は枯れたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'イエス答へて言ひ給ふ『神を信ぜよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'まことに汝らに告ぐ、人もし此の山に「移りて海に入れ」と言ふとも、其の言ふところ必ず成るべしと信じて、心に疑はずば、その如く成るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'この故に汝らに告ぐ、凡て祈りて願ふ事は、すでに得たりと信ぜよ、さらば得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'また立ちて祈るとき、人を怨む事あらば免せ、これは天に在す汝らの父の、汝らの過失を免し給はん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'かれら又エルサレムに到る。イエス宮の内を歩み給ふとき、祭司長・學者・長老たち御許に來りて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, '『何の權威をもて此 等の事をなすか、誰が此 等の事を爲すべき權威を授けしか』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'イエス言ひ給ふ『われ一言なんぢらに問はん、答へよ、さらば我も何の權威をもて、此 等の事を爲すかを告げん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'ヨハネのバプテスマは、天よりか、人よりか、我に答へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, '彼ら互に論じて言ふ『もし天よりと言はば「何 故かれを信ぜざりし」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'されど人よりと言はんか......』彼ら群衆を恐れたり、人みなヨハネを實に預言者と認めたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, '遂にイエスに答へて『知らず』と言ふ。イエス言ひ給ふ『われも何の權威をもて此 等の事を爲すか、汝らに告げじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'イエス譬をもて彼らに語り出で給ふ『ある人、葡萄園を造り、籬を環らし、酒槽の穴を掘り、櫓をたて、農夫どもに貸して、遠く旅立せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, '時いたりて農夫より葡萄園の所得を受取らんとて、僕をその許に遣ししに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, '彼ら之を執へて打ちたたき、空手にて歸らしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, '又ほかの僕を遣ししに、その首に傷つけ、かつ辱しめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'また他の者を遣ししに、之を殺したり。又ほかの多くの僕をも、或は打ち或は殺したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'なほ一人あり、即ち其の愛しむ子なり「わが子は敬ふならん」と言ひて、最後に之を遣ししに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'かの農夫ども互に言ふ「これは世嗣なり、いざ之を殺さん、さらばその嗣業は、我らのものとなるべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, '乃ち執へて之を殺し、葡萄園の外に投げ棄てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'さらば葡萄園の主、なにを爲さんか、來りて農夫どもを亡し、葡萄園を他の者どもに與ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, '汝ら聖書に「造家者らの棄てたる石は、これぞ隅の首石となれる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'これ主によりて成れるにて、我らの目には奇しきなり」とある句をすら讀まぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'ここに彼 等イエスを執へんと思ひたれど、群衆を恐れたり、この譬の己らを指して言ひ給へるを悟りしに因る。遂にイエスを離れて去り往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'かくて彼らイエスの言尾をとらへて陷入れん爲に、パリサイ人とヘロデ黨との中より、數人を御許に遣す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'その者ども來りて言ふ『師よ、我らは知る、汝は眞にして、誰をも憚りたまふ事なし、人の外貌を見ず、眞をもて神の道を教へ給へばなり。我ら貢をカイザルに納むるは、宜きか、惡しきか、納めんか、納めざらんか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'イエス其の詐僞なるを知りて『なんぞ我を試むるか、デナリを持ち來りて我に見せよ』と言ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, '彼ら持ち來る。イエス言ひ給ふ『これは誰の像、たれの號なるか』『カイザルのなり』と答ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'イエス言ひ給ふ『カイザルの物はカイザルに、神の物は神に納めよ』彼らイエスに就きて甚だ怪しめり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'また復活なしと云ふサドカイ人ら、イエスに來り問ひて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '『師よ、モーセは、人の兄弟もし子なく妻を遺して死なば、その兄弟かれの妻を娶りて、兄弟のため嗣子を擧ぐべしと、我らに書き遺したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'ここに七人の兄弟ありて、兄 妻を娶り、嗣子なくして死に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, '第二の者その女を娶り、また嗣子なくして死に、第三の者もまた然なし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, '七人とも嗣子なくして死に、終には其の女も死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, '復活のとき彼らみな甦へらんに、この女は誰の妻たるべきか、七人これを妻としたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'イエス言ひ給ふ『なんぢらの誤れるは、聖書をも神の能力をも知らぬ故ならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, '人、死人の中より甦へる時は、娶らず、嫁がず、天に在る御使たちの如くなるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, '死にたる者の甦へる事に就きては、モーセの書の中なる柴の條に、神モーセに「われはアブラハムの神、イサクの神、ヤコブの神なり」と告げ給ひし事あるを、未だ讀まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, '神は死にたる者の神にあらず、生ける者の神なり。なんぢら大に誤れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, '學者の一人、かれらの論じをるを聞き、イエスの善く答へ給へるを知り、進み出でて問ふ『すべての誡命のうち、何か第一なる』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'イエス答へたまふ『第一は是なり「イスラエルよ聽け、主なる我らの神は唯一の主なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'なんぢ心を盡し、精神を盡し、思を盡し、力を盡して、主なる汝の神を愛すべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, '第二は是なり「おのれの如く汝の隣を愛すべし」此の二つより大なる誡命はなし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, '學者いふ『善きかな師よ「神は唯一にして他に神なし」と言ひ給へるは眞なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, '「こころを盡し、知慧を盡し、力を盡して神を愛し、また己のごとく隣を愛する」は、もろもろの燔祭および犧牲に勝るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'イエスその聰く答へしを見て言ひ給ふ『なんぢ神の國に遠からず』此の後たれも敢へてイエスに問ふ者なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'イエス宮にて教ふるとき、答へて言ひ給ふ『なにゆゑ學者らはキリストをダビデの子と言ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'ダビデ聖 靈に感じて自らいへり「主わが主に言ひ給ふ、我なんぢの敵を汝の足の下に置くまでは、我が右に坐せよ」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'ダビデ自ら彼を主と言ふ、されば爭でその子ならんや』大なる群衆は喜びてイエスに聽きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'イエスその教のうちに言ひたまふ『學者らに心せよ、彼らは長き衣を著て歩むこと、市場にての敬禮、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, '會堂の上座、饗宴の上席を好み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'また寡婦らの家を呑み、外見をつくりて長き祈をなす。その受くる審判は更に嚴しからん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'イエス賽錢函に對ひて坐し、群衆の錢を賽錢函に投げ入るるを見 給ふ。富める多くの者は、多く投げ入れしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, '一人の貧しき寡婦きたりて、レプタ二つを投げ入れたり、即ち五 厘ほどなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'イエス弟子たちを呼び寄せて言ひ給ふ『まことに汝らに告ぐ、この貧しき寡婦は、賽錢函に投げ入るる凡ての人よりも多く投げ入れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, '凡ての者は、その豐なる内よりなげ入れ、この寡婦は其の乏しき中より、凡ての所有、即ち己が生命の料をことごとく投げ入れたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'イエス宮を出で給ふとき、弟子の一人いふ『師よ、見 給へ、これらの石、これらの建造物、いかに盛ならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'イエス言ひ給ふ『なんぢ此 等の大なる建造物を見るか、一つの石も崩されずしては石の上に殘らじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'オリブ山にて宮の方に對ひて坐し給へるに、ペテロ、ヤコブ、ヨハネ、アンデレ竊に問ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '『われらに告げ給へ、これらの事は何時あるか、又すべて此 等の事の成し遂げられんとする時は、如何なる兆あるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'イエス語り出で給ふ『なんぢら人に惑されぬやうに心せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, '多くの者わが名を冒し來り「われは夫なり」と言ひて多くの人を惑さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, '戰爭と戰爭の噂とを聞くとき懼るな、かかる事はあるべきなり、されど未だ終にはあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, '即ち「民は民に、國は國に逆ひて起たん」また處々に地震あり、饑饉あらん、これらは産の苦難の始なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, '汝 等みづから心せよ、人々なんぢらを衆議所に付さん。なんぢら會堂に曳かれて打たれ、且わが故によりて、司たち及び王たちの前に立てられん、これは證をなさん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'かくて福音は先づもろもろの國人に宣傳へらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, '人々なんぢらを曳きて付さんとき、何を言はんと預じめ思ひ煩ふな、唯そのとき授けらるることを言へ、これ言ふ者は汝 等にあらず、聖 靈なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, '兄弟は兄弟を、父は子を死にわたし、子らは親たちに逆ひ立ちて死なしめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, '又なんぢら我が名の故に凡ての人に憎まれん、されど終まで耐へ忍ぶ者は救はるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, '「荒す惡むべき者」の立つべからざる所に立つを見ば(讀むもの悟れ)その時ユダヤにをる者どもは、山に遁れよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, '屋の上にをる者は、内に下るな。また家の物を取り出さんとて内に入るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, '畑にをる者は上衣を取らんとて歸るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, '其の日には孕りたる女と、乳を哺まする女とは禍害なるかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'この事の冬おこらぬやうに祈れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'その日は患難の日なればなり。神の萬物を造り給ひし開闢より今に至るまで、かかる患難はなく、また後にもなからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, '主その日を少くし給はずば、救はるる者 一人だになからん。されど其の選び給ひし選民の爲に、その日を少くし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, '其の時なんぢらに「視よ、キリスト此處にあり」「視よ、彼處にあり」と言ふ者ありとも信ずな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, '僞キリスト・僞 預言者ら起りて、徴と不思議とを行ひ、爲し得べくは、選民をも惑さんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, '汝らは心せよ、あらかじめ之を皆なんぢらに告げおくなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, '其の時、その患難ののち、日は暗く、月は光を發たず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, '星は空より隕ち、天にある萬象ふるひ動かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, '其のとき人々、人の子の大なる能力と榮光とをもて、雲に乘り來るを見ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'その時かれは使者たちを遣して、地の極より天の極まで、四方より其の選民をあつめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, '無花果の樹よりの譬を學べ、その枝すでに柔かくなりて葉 芽ぐめば、夏の近きを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'かくの如く此 等のことの起るを見ば、人の子すでに近づきて門邊にいたるを知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'まことに汝らに告ぐ、これらの事ことごとく成るまで、今の代は過ぎ逝くことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, '天 地は過ぎゆかん、されど我が言は過ぎ逝くことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'その日その時を知る者なし。天にある使者たちも知らず、子も知らず、ただ父のみ知り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, '心して目を覺しをれ、汝 等その時の何時なるかを知らぬ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, '例へば家を出づる時、その僕どもに權を委ねて、各自の務を定め、更に門守に、目を覺しをれと命じ置きて、遠く旅立したる人のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'この故に目を覺しをれ、家の主人の歸るは、夕か、夜半か、鷄 鳴くころか、夜明か、いづれの時なるかを知らねばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, '恐らくは俄に歸りて、汝らの眠れるを見ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'わが汝らに告ぐるは、凡ての人に告ぐるなり。目を覺しをれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'さて過越と除酵との祭の二日 前となりぬ。祭司長・學者ら詭計をもてイエスを捕へ、かつ殺さんと企てて言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, '『祭の間は爲すべからず、恐らくは民の亂あるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'イエス、ベタニヤに在して、癩病人シモンの家にて食事の席につき居給ふとき、或 女、價 高き混なきナルドの香 油の入りたる石膏の壺を持ち來り、その壺を毀ちてイエスの首に注ぎたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'ある人々、憤ほりて互に言ふ『なに故かく濫に油を費すか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'この油を三 百デナリ餘に賣りて、貧しき者に施すことを得たりしものを』而して甚く女を咎む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'イエス言ひ給ふ『その爲すに任せよ、何ぞこの女を惱すか、我に善き事をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, '貧しき者は常に汝らと偕にをれば、何時にても心のままに助け得べし、されど我は常に汝らと偕にをらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, '此の女は、なし得る限をなして、我が體に香 油をそそぎ、あらかじめ葬りの備をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'まことに汝らに告ぐ、全世界いづこにても、福音の宣傅へらるる處には、この女の爲しし事も記念として語らるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'ここに十二 弟子の一人なるイスカリオテのユダ、イエスを賣らんとて祭司長の許にゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, '彼 等これを聞きて喜び、銀を與へんと約したれば、ユダ如何にしてか機 好くイエスを付さんと謀る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, '除酵祭の初の日、即ち過越の羔羊を屠るべき日、弟子たちイエスに言ふ『過越の食をなし給ふために、我らが何處に往きて備ふることを望み給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'イエス二人の弟子を遣さんとして言ひたまふ『都に往け、然らば水をいれたる瓶を持つ人、なんぢらに遇ふべし。之に從ひ往き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'その入る所の家主に「師いふ、われ弟子らと共に過越の食をなすべき座敷は何處なるか」と言へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'さらば調へ備へたる大なる二階 座敷を見すべし。其處に我らのために備へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, '弟子たち出で往きて都に入り、イエスの言ひ給ひし如くなるを見て、過越の設備をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, '日 暮れてイエス十二 弟子とともに往き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'みな席に就きて食するとき言ひ給ふ『まことに汝らに告ぐ、我と共に食する汝らの中の一人、われを賣らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, '弟子たち憂ひて一人 一人『われなるか』と言ひ出でしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'イエス言ひたまふ『十二のうちの一人にて、我と共にパンを鉢に浸す者は夫なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, '實に人の子は己に就きて録されたる如く逝くなり。されど人の子を賣る者は禍害なるかな、その人は生れざりし方よかりしものを』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, '彼ら食しをる時、イエス、パンを取り、祝してさき、弟子たちに與へて言ひたまふ『取れ、これは我が體なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'また酒杯を取り、謝して彼らに與へ給へば、皆この酒杯より飮めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'また言ひ給ふ『これは契約の我が血、おほくの人の爲に流す所のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'まことに汝らに告ぐ、神の國にて新しきものを飮む日までは、われ葡萄の果より成るものを飮まじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'かれら讃美をうたひて後、オリブ山に出でゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'イエス弟子たちに言ひ給ふ『なんぢら皆 躓かん、それは「われ牧羊者を打たん、さらば羊 散るべし」と録されたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'されど我よみがへりて後、なんぢらに先だちてガリラヤに往かん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, '時にペテロ、イエスに言ふ『假令みな躓くとも、我は然らじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'イエス言ひ給ふ『まことに汝に告ぐ、今日この夜、鷄ふたたび鳴く前に、なんぢ三たび我を否むべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'ペテロ力をこめて言ふ『われ汝とともに死ぬべき事ありとも、汝を否まず』弟子たち皆かく言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, '彼らゲツセマネと名づくる處に到りし時、イエス弟子たちに言ひ給ふ『わが祈る間、ここに座せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'かくてペテロ、ヤコブ、ヨハネを伴ひゆき、甚く驚き、かつ悲しみ出でて言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, '『わが心いたく憂ひて死ぬばかりなり、汝ら此處に留りて目を覺しをれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, '少し進みゆきて、地に平伏し、若しも得べくば此の時の己より過ぎ往かんことを祈りて言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, '『アバ父よ、父には能はぬ事なし、此の酒杯を我より取り去り給へ。されど我が意のままを成さんとにあらず、御意のままを成し給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, '來りて、その眠れるを見、ペテロに言ひ給ふ『シモンよ、なんぢ眠るか、一 時も目を覺しをること能はぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'なんぢら誘惑に陷らぬやう、目を覺しかつ祈れ。實に心は熱すれども肉體よわきなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, '再びゆき、同じ言にて祈り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'また來りて彼らの眠れるを見たまふ、是その目いたく疲れたるなり、彼ら何と答ふべきかを知らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, '三度 來りて言ひたまふ『今は眠りて休め、足れり、時きたれり、視よ、人の子は罪人らの手に付さるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, '起て、われらは往くべし。視よ、我を賣る者ちかづけり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'なほ語りゐ給ふほどに、十二 弟子の一人なるユダ、やがて近づき來る、祭司長・學者・長老らより遣されたる群衆、劍と棒とを持ちて之に伴ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'イエスを賣るもの、あらかじめ合圖を示して言ふ『わが接吻する者はそれなり、之を捕へて確と引きゆけ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'かくて來りて直ちに御許に往き『ラビ』と言ひて接吻したれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, '人々イエスに手をかけて捕ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, '傍らに立つ者のひとり、劍を拔き、大 祭司の僕を撃ちて、耳を切り落せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'イエス人々に對ひて言ひ給ふ『なんぢら強盜にむかふ如く、劍と棒とを持ち、我を捕へんとて出で來るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, '我は日々なんぢらと偕に宮にありて教へたりしに、我を執へざりき、されど是は聖書の言の成就せん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, '其のとき弟子みなイエスを棄てて逃げ去る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'ある若者、素肌に亞麻 布を纏ひて、イエスに從ひたりしに、人々これを捕へければ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, '亞麻 布を棄て裸にて逃げ去れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, '人々イエスを大 祭司の許に曳き往きたれば、祭司長・長老・學者ら皆あつまる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'ペテロ遠く離れてイエスに從ひ、大 祭司の中庭まで入り、下役どもと共に坐して火に煖まりゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'さて祭司長ら及び全 議會、イエスを死に定めんとて、證據を求むれども得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'それはイエスに對して僞證する者 多くあれども、其の證據あはざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, '遂に或 者ども起ちて僞證して言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '『われら此の人の「われは手にて造りたる此の宮を毀ち、手にて造らぬ他の宮を三日にて建つべし」と云へるを聞けり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, '然れど尚この證據もあはざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'ここに大 祭司、中に立ちイエスに問ひて言ふ『なんぢ何をも答へぬか、此の人々の立つる證據は如何に』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'されどイエス默して何をも答へ給はず。大 祭司ふたたび問ひて言ふ『なんぢは頌むべきものの子キリストなるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'イエス言ひ給ふ『われは夫なり、汝ら、人の子の全能者の右に坐し、天の雲の中にありて來るを見ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, '此のとき大 祭司おのが衣を裂きて言ふ『なんぞ他に證人を求めん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'なんぢら此の瀆言を聞けり、如何に思ふか』かれら擧りてイエスを死に當るべきものと定む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, '而して或 者どもはイエスに唾し、又その顏を蔽ひ、拳にて搏ちなど爲始めて言ふ『預言せよ』下役どもイエスを受け、手掌にてうてり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'ペテロ下にて中庭にをりしに、大 祭司の婢女の一人きたりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'ペテロの火に煖まりをるを見、これに目を注めて『汝もかのナザレ人イエスと偕に居たり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'ペテロ肯はずして『われは汝の言ふことを知らず、又その意をも悟らず』と言ひて庭 口に出でたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, '婢女かれを見て、また傍らに立つ者どもに『この人はかの黨與なり』と言ひ出でしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'ペテロ重ねて肯はず、暫くしてまた傍らに立つ者どもペテロに言ふ『なんぢは慥にかの黨與なり、汝もガリラヤ人なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, '此の時ペテロ盟ひかつ誓ひて『われは汝らの言ふ其の人を知らず』と言ひ出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'その折しも、また鷄なきぬ。ペテロ『にはとり二度なく前に、なんぢ三度われを否まん』とイエスの言ひ給ひし御言を思ひいだし、思ひ反して泣きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, '夜 明るや直ちに、祭司長・長老・學者ら、即ち全 議會ともに相 議りて、イエスを縛り、曳きゆきてピラトに付す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'ピラト、イエスに問ひて言ふ『なんぢはユダヤ人の王なるか』答へて言ひ給ふ『なんぢの言ふが如し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, '祭司長らさまざまに訴ふれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'ピラトまた問ひて言ふ『なにも答へぬか、視よ、如何に多くの事をもて訴ふるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'されどピラトの怪しむばかり、イエス更に何をも答へ給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'さて祭の時には、ピラト民の願に任せて、囚人ひとりを赦す例なるが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'ここに一揆を起し、人を殺して繋がれをる者の中に、バラバといふ者あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, '群衆すすみ來りて、例の如くせんことを願ひ出でたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'ピラト答へて言ふ『ユダヤ人の王を赦さんことを願ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'これピラト、祭司長らのイエスを付ししは、嫉に因ると知る故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'されど祭司長ら群衆を唆かし、反つてバラバを赦さんことを願はしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'ピラトまた答へて言ふ『さらば汝らがユダヤ人の王と稱ふる者をわれ如何にすべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, '人々また叫びて言ふ『十字架につけよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'ピラト言ふ『そも彼は何の惡事を爲したるか』かれら烈しく叫びて『十字架につけよ』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'ピラト群衆の望を滿さんとて、バラバを釋し、イエスを鞭うちたるのち、十字架につくる爲にわたせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, '兵卒どもイエスを官邸の中庭に連れゆき、全 隊を呼び集めて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, '彼に紫色の衣を著せ、茨の冠冕を編みて冠らせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, '『ユダヤ人の王、安かれ』と禮をなし始め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'また葦にて其の首をたたき、唾し、跪づきて拜せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'かく嘲弄してのち、紫色の衣を剥ぎ、故の衣を著せ、十字架につけんとて曳き出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, '時にアレキサンデルとルポスとの父シモンといふクレネ人、田舍より來りて通りかかりしに、強ひてイエスの十字架を負はせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'イエスをゴルゴダ、釋けば髑髏といふ處に連れ往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'かくて沒藥を混ぜたる葡萄酒を與へたれど、受け給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, '彼らイエスを十字架につけ、而して誰が何を取るべきと、鬮を引きて其の衣を分つ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'イエスを十字架につけしは、朝の九時 頃なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'その罪標には『ユダヤ人の王』と書せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'イエスと共に、二人の強盜を十字架につけ、一人をその右に、一人をその左に置く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, '往來の者どもイエスを譏り、首を振りて言ふ『ああ、宮を毀ちて三日のうちに建つる者よ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, '十字架より下りて己を救へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, '祭司長らも亦 同じく、學者らと共に嘲弄して互に言ふ『人を救ひて、己を救ふこと能はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'イスラエルの王キリスト、いま十字架より下りよかし、さらば我ら見て信ぜん』共に十字架につけられたる者どもも、イエスを罵りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, '晝の十二 時に、地のうへ徧く暗くなりて、三時に及ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, '三時にイエス大聲に『エロイ、エロイ、ラマ、サバクタニ』と呼はり給ふ。之を釋けば、わが神、わが神、なんぞ我を見 棄て給ひし、との意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, '傍らに立つ者のうち或 人々これを聞きて言ふ『視よ、エリヤを呼ぶなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, '一人はしり往きて、海綿に酸き葡萄酒を含ませて葦につけ、イエスに飮ましめて言ふ『待て、エリヤ來りて、彼を下すや否や、我ら之を見ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'イエス大聲を出して息 絶え給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, '聖所の幕、上より下まで裂けて二つとなりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'イエスに向ひて立てる百卒長、かかる樣にて息 絶え給ひしを見て言ふ『實にこの人は神の子なりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'また遙に望み居たる女たちあり、その中にはマグダラのマリヤ、小ヤコブとヨセとの母マリヤ、及びサロメなども居たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, '彼らはイエスのガリラヤに居給ひしとき、從ひ事へし者どもなり。此の他イエスと共にエルサレムに上りし多くの女もありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, '日 既に暮れて、準備 日すなはち安息 日の前の日となりたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, '貴き議員にして、神の國を待ち望める、アリマタヤのヨセフ來りて、憚らずピラトの許に往き、イエスの屍體を乞ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'ピラト、イエスは早や死にしかと訝り、百卒長を呼びて、その死にしより時 經しや否やを問ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, '既に死にたる事を百卒長より聞き知りて、屍體をヨセフに與ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'ヨセフ亞麻 布を買ひ、イエスを取下して之に包み、岩に鑿りたる墓に納め、墓の入口に石を轉し置く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'マグダラのマリヤとヨセの母マリヤと、イエスを納めし處を見ゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, '安息 日 終りし時、マグダラのマリヤ、ヤコブの母マリヤ及びサロメ、往きてイエスに抹らんとて香料を買ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, '一週の首の日、日の出でたる頃いと早く墓にゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, '誰か我らの爲に墓の入口より石を轉すべきと語り合ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, '目を擧ぐれば、石の既に轉しあるを見る。この石は甚だ大なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, '墓に入り、右の方に白き衣を著たる若者の坐するを見て甚く驚く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, '若者いふ『おどろくな、汝らは十字架につけられ給ひしナザレのイエスを尋ぬれど、既に甦へりて、此處に在さず。視よ、納めし處は此處なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'されど往きて弟子たちとペテロとに告げよ「汝らに先だちてガリラヤに往き給ふ、彼處にて謁ゆるを得ん、曾て汝らに言ひ給ひしが如し」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, '女たち甚く驚きをののき、墓より逃げ出でしが、懼れたれば一言をも人に語らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, '[一週の首の日の拂曉、イエス甦へりて先づマグダラのマリヤに現れたまふ、前にイエスが七つの惡鬼を逐ひいだし給ひし女なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'マリヤ往きて、イエスと偕にありし人々の、泣き悲しみ居るときに之を告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, '彼らイエスの活き給へる事と、マリヤに見え給ひし事とを聞けども信ぜざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, '此の後その中の二人、田舍に往く途を歩むほどに、イエス異なりたる姿にて現れ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, '此の二人ゆきて、他の弟子たちに之を告げたれど、なほ信ぜざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, '其ののち十 一 弟子の食しをる時に、イエス現れて、己が甦へりたるを見し者どもの言を信ぜざりしにより、其の信仰なきと、其の心の頑固なるとを責め給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'かくて彼らに言ひたまふ『全世界を巡りて凡ての造られしものに福音を宣傳へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, '信じてバプテスマを受くる者は救はるべし、然れど信ぜぬ者は罪に定めらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, '信ずる者には此 等の徴ともなはん。即ち我が名によりて惡鬼を逐ひいだし、新しき言をかたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, '蛇を握るとも、毒を飮むとも、害を受けず、病める者に手をつけなば癒えん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, '語り終へてのち、主イエスは天に擧げられ、神の右に坐し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, '弟子たち出でて、あまねく福音を宣傳へ、主も亦ともに働き、伴ふところの徴をもて、御言を確うし給へり〕');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, '我らの中に成りし事の物語につき、始よりの目撃者にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, '御言の役者となりたる人々の、我らに傳へし其のままを書き列ねんと、手を著けし者あまたある故に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, '我も凡ての事を最初より詳細に推し尋ねたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'テオピロ閣下よ、汝の教へられたる事の慥なるを悟らせん爲に、これが序を正して書き贈るは善き事と思はるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'ユダヤの王ヘロデの時、アビヤの組の祭司に、ザカリヤという人あり。その妻はアロンの裔にて、名をエリサベツといふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, '二人ながら神の前に正しくして、主の誡命と定規とを、みな缺なく行へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'エリサベツ石女なれば、彼らに子なし、また二人とも年 邁みぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'さてザカリヤその組の順番に當りて、神の前に祭司の務を行ふとき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, '祭司の慣例にしたがひて、籤をひき主の聖所に入りて、香を燒くこととなりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, '香を燒くとき、民の群みな外にありて祈りゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, '時に主の使あらはれて、香壇の右に立ちたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'ザカリヤ之を見て、心さわぎ懼を生ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, '御使いふ『ザカリヤよ、懼るな、汝の願は聽かれたり。汝の妻エリサベツ男子を生まん、汝その名をヨハネと名づくべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'なんぢに喜悦と歡樂とあらん、又おほくの人もその生るるを喜ぶべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'この子、主の前に大ならん、また葡萄酒と濃き酒とを飮まず、母の胎を出づるや聖 靈にて滿されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'また多くのイスラエルの子らを、主なる彼らの神に歸らしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, '且エリヤの靈と能力とをもて、主の前に往かん。これ父の心を子に、戻れる者を義人の聰明に歸らせて、整へたる民を主のために備へんとてなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'ザカリヤ御使にいふ『何に據りてか此の事あるを知らん。我は老人にて、妻もまた年 邁みたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, '御使こたへて言ふ『われは神の御前に立つガブリエルなり、汝に語りてこの嘉き音信を告げん爲に遣さる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, '視よ、時いたらば必ず成就すべき我が言を信ぜぬに因り、なんぢ物 言へずなりて、此らの事の成る日までは語ること能はじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, '民はザカリヤを俟ちゐて、其の聖所の内に久しく留るを怪しむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, '遂に出で來りたれど語ること能はねば、彼らその聖所の内にて異象を見たることを悟る。ザカリヤは、ただ首にて示すのみ、なほ唖なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'かくて務の日 滿ちたれば、家に歸りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, '此の後その妻エリサベツ孕りて、五月ほど隱れをりて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '『主わが恥を人の中に雪がせんとて、我を顧み給ふときは、斯く爲し給ふなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'その六月めに、御使ガブリエル、ナザレといふガリラヤの町にをる處女のもとに、神より遣さる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'この處女はダビデの家のヨセフといふ人と許嫁せし者にて、其の名をマリヤと云ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, '御使、處女の許にきたりて言ふ『めでたし、惠まるる者よ、主なんぢと偕に在せり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'マリヤこの言によりて心いたく騷ぎ、斯かる挨拶は如何なる事ぞと思ひ廻らしたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, '御使いふ『マリヤよ、懼るな、汝は神の御前に惠を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, '視よ、なんぢ孕りて男子を生まん、其の名をイエスと名づくべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, '彼は大ならん、至高者の子と稱へられん。また主たる神、これに其の父ダビデの座位をあたへ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'ヤコブの家を永遠に治めん。その國は終ることなかるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'マリヤ御使に言ふ『われ未だ人を知らぬに、如何にして此の事のあるべき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, '御使こたへて言ふ『聖 靈なんぢに臨み、至高者の能力なんぢを被はん。此の故に汝が生むところの聖なる者は、神の子と稱へらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, '視よ、なんぢの親族エリサベツも、年 老いたれど、男子を孕めり。石女といはれたる者なるに、今は孕りてはや六月になりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'それ神の言には能はぬ所なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'マリヤ言ふ『視よ、われは主の婢女なり。汝の言のごとく、我に成れかし』つひに御使はなれ去りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'その頃マリヤ立ちて山里に急ぎ往き、ユダの町にいたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'ザカリヤの家に入りてエリサベツに挨拶せしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'エリサベツその挨拶を聞くや、兒は胎内にて躍れり。エリサベツ聖 靈にて滿され、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, '聲 高らかに呼はりて言ふ『をんなの中にて汝は祝福せられ、その胎の實もまた祝福せられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'わが主の母われに來る、われ何によりてか之を得し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, '視よ、なんぢの挨拶の聲、わが耳に入るや、我が兒、胎内にて喜びをどれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, '信ぜし者は幸福なるかな、主の語り給ふことは必ず成就すべければなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'マリヤ言ふ、『わがこころ主をあがめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'わが靈はわが救主なる神を喜びまつる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'その婢女の卑しきをも顧み給へばなり。視よ、今よりのち萬 世の人われを幸福とせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, '全能者われに大なる事を爲したまへばなり。その御名は聖なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'そのあはれみは代々かしこみ恐るる者に臨むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, '神は御腕にて權力をあらはし、心の念に高ぶる者を散し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, '權勢ある者を座位より下し、いやしき者を高うし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, '飢ゑたる者を善き物に飽かせ、富める者を空しく去らせ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'また我らの先祖に告げ給ひし如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'アブラハムとその裔とに對するあはれみを永遠に忘れじとて、僕イスラエルを助けたまへり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'かくてマリヤは、三月ばかりエルザベツと偕に居りて、己が家に歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'さてエリサベツ産む期みちて男子を生みたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'その最寄のもの親族の者ども、主の大なる憐憫をエリサベツに垂れ給ひしことを聞きて、彼とともに喜ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, '八日めになりて、其の子に割禮を行はんとて人々きたり、父の名に因みてザカリヤと名づけんとせしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, '母こたへて言ふ『否、ヨハネと名づくべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'かれら言ふ『なんぢの親族の中には此の名をつけたる者なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, '而して父に首にて示し、いかに名づけんと思ふか、問ひたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'ザカリヤ書板を求めて『その名はヨハネなり』と書きしかば、みな怪しむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'ザカリヤの口たちどころに開け、舌ゆるみ、物いひて神を讃めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, '最寄に住む者みな懼をいだき、又すべて此 等のこと徧くユダヤの山里に言ひ囃されたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, '聞く者みな之を心にとめて言ふ『この子は如何なる者にか成らん』主の手かれと偕に在りしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'かくて父ザカリヤ聖 靈にて滿され預言して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '『讃むべきかな、主イスラエルの神、その民をかへりみて贖罪をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, '我らのために救の角を、その僕ダビデの家に立て給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'これぞ古へより聖 預言者の口をもて言ひ給ひし如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, '我らを仇より、凡て我らを憎む者の手より、取り出したまふ救なる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, '我らの先祖に憐憫を垂れ、その聖なる契約を思し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, '我らの先祖アブラハムに立て給ひし御誓を忘れずして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, '我らを仇の手より救ひ、生涯、主の御前に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, '聖と義とをもて懼なく事へしめたまふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, '幼兒よ、なんぢは至高者の預言者と稱へられん。これ主の御前に先だちゆきて、其の道を備へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, '主の民に罪の赦による救を知らしむればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'これ我らの神の深き憐憫によるなり。この憐憫によりて朝のひかり、上より臨み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, '暗黒と死の蔭とに坐する者をてらし、我らの足を平和の路にみちびかん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'かくて幼兒は漸に成長し、その靈 強くなり、イスラエルに現るる日まで荒野にゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'その頃、天下の人を戸籍に著かすべき詔令、カイザル・アウグストより出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'この戸籍 登録は、クレニオ、シリヤの總督たりし時に行はれし初のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'さて人みな戸籍に著かんとて、各自その故郷に歸る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'ヨセフもダビデの家系また血統なれば、既に孕める許嫁の妻マリヤとともに、戸籍に著かんとて、ガリラヤの町ナザレを出でてユダヤに上り、ダビデの町ベツレヘムといふ處に到りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'ヨセフもダビデの家系また血統なれば、既に孕める許嫁の妻マリヤとともに、戸籍に著かんとて、ガリラヤの町ナザレを出でてユダヤに上り、ダビデの町ベツレヘムといふ處に到りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, '此處に居るほどに、マリヤ月 滿ちて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, '初子をうみ、之を布に包みて馬槽に臥させたり。旅舍にをる處なかりし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'この地に野宿して、夜 群を守りをる牧者ありしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, '主の使その傍らに立ち、主の榮光その周圍を照したれば、甚く懼る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, '御使かれらに言ふ『懼るな、視よ、この民 一般に及ぶべき、大なる歡喜の音信を我なんぢらに告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, '今日ダビデの町にて汝らの爲に救主うまれ給へり、これ主キリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'なんぢら布にて包まれ、馬槽に臥しをる嬰兒を見ん、是その徴なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, '忽ちあまたの天の軍勢、御使に加はり、神を讃美して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '『いと高き處には榮光、神にあれ。地には平和、主の悦び給ふ人にあれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, '御使 等さりて天に往きしとき、牧者たがひに語る『いざ、ベツレヘムにいたり、主の示し給ひし起れる事を見ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, '乃ち急ぎ往きて、マリヤとヨセフと、馬槽に臥したる嬰兒とに尋ねあふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, '既に見て、この子につき御使の語りしことを告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, '聞く者はみな牧者の語りしことを怪しみたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, '而してマリヤは凡て此 等のことを心に留めて思ひ囘せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, '牧者は御使の語りしごとく凡ての事を見 聞せしによりて、神を崇めかつ讃美しつつ歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, '八日みちて幼兒に割禮を施すべき日となりたれば、未だ胎内に宿らぬ先に御使の名づけし如く、その名をイエスと名づけたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'モーセの律法に定めたる潔の日 滿ちたれば、彼ら幼兒を携へてエルサレムに上る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'これは主の律法に『すべて初子に生るる男子は、主につける聖なる者と稱へらるべし』と録されたる如く、幼兒を主に献げ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'また主の律法に『山鳩 一つがひ或は家 鴿の雛 二 羽』と云ひたるに遵ひて、犧牲を供へん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, '視よ、エルサレムにシメオンといふ人あり。この人は義かつ敬虔にして、イスラエルの慰められんことを待ち望む。聖 靈その上に在す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'また聖 靈に、主のキリストを見ぬうちは死を見ずと示されたれしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, '此とき御靈に感じて宮に入る。兩親その子イエスを携へ、この子のために律法の慣例に遵ひて行はんとて來りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'シメオン、イエスを取りいだき、神を讃めて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '『主よ、今こそ御言に循ひて、僕を安らかに逝かしめ給ふなれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'わが目は、はや主の救を見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, '是もろもろの民の前に備へ給ひし者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, '異邦人をてらす光、御民イスラエルの榮光なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'かく幼兒に就きて語ることを、其の父 母あやしみ居たれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'シメオン彼らを祝して母マリヤに言ふ『視よ、この幼兒は、イスラエルの多くの人の或は倒れ、或は起たん爲に、また言ひ逆ひを受くる徴のために置かる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '――劍なんぢの心をも刺し貫くべし――これは多くの人の心の念の顯れん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'ここにアセルの族パヌエルの娘に、アンナといふ預言者あり、年いたく老ゆ。處女のとき、夫に適きて七 年ともに居り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, '八 十四年 寡婦たり。宮を離れず、夜も晝も斷食と祈祷とを爲して神に事ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'この時すすみ寄りて神に感謝し、また凡てエルサレムの拯贖を待ちのぞむ人に、幼兒のことを語れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'さて主の律法に遵ひて、凡ての事を果したれば、ガリラヤに歸り、己が町ナザレに到れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, '幼兒は漸に成長して健かになり、智慧みち、かつ神の惠その上にありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'かくてその兩親、過越の祭には年毎にエルサレムに往きぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'イエスの十二 歳のとき、祭の慣例に遵ひて上りゆき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, '祭の日 終りて歸る時、その子イエスはエルサレムに止りたまふ。兩親は之を知らずして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, '道伴のうちに居るならんと思ひ、一日 路ゆきて、親族・知邊のうちを尋ぬれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, '遇はぬに因りて復たづねつつエルサレムに歸り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, '三日ののち、宮にて教師のなかに坐し、かつ聽き、かつ問ひゐ給ふに遇ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, '聞く者は皆その聰と答とを怪しむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, '兩親イエスを見て、いたく驚き、母は言ふ『兒よ、何 故かかる事を我らに爲しぞ、視よ、汝の父と我と憂ひて尋ねたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'イエス言ひたまふ『何 故われを尋ねたるか、我はわが父の家に居るべきを知らぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, '兩親はその語りたまふ事を悟らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'かくてイエス彼 等とともに下り、ナザレに往きて順ひ事へたまふ。其の母これらの事をことごとく心に藏む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'イエス智慧も身のたけも彌まさり、神と人とにますます愛せられ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'テベリオ・カイザル在位の十 五 年、ポンテオ・ピラトはユダヤの總督、ヘロデはガリラヤ分封の國守、その兄弟ピリポはイツリヤ及びテラコニテの地の分封の國守、ルサニヤはアビレネ分封の國守たり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'アンナスとカヤパとは大 祭司たりしとき、神の言、荒野にてザカリヤの子ヨハネに臨む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'かくてヨルダン河の邊なる四方の地にゆき、罪の赦を得さする悔改のバプテスマを宣傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, '預言者イザヤの言の書に『荒野に呼はる者の聲す。「主の道を備へ、その路すじを直くせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, '諸の谷は埋められ、諸の山と岡とは平げられ、曲りたるは直く、嶮しきは坦かなる路となり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, '人みな神の救を見ん」』と録されたるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'さてヨハネ、バプテスマを受けんとて出できたる群衆にいふ『蝮の裔よ、誰が汝らに、來らんとする御怒を避くべき事を示したるぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'さらば悔改に相應しき果を結べ。なんぢら「我らの父にアブラハムあり」と心のうちに言ひ始むな。我なんぢらに告ぐ、神はよく此らの石よりアブラハムの子 等を起し得給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, '斧ははや樹の根に置かる。されば凡て善き果を結ばぬ樹は、伐られて火に投げ入れらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, '群衆ヨハネに問ひて言ふ『さらば我ら何を爲すべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, '答へて言ふ『二つの下衣をもつ者は、有たぬ者に分け與へよ。食物を有つ者もまた然せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, '取税人もバプテスマを受けんとて來りて言ふ『師よ、我ら何を爲すべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, '答へて言ふ『定りたるものの外、なにをも促るな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, '兵卒もまた問ひて言ふ『我らは何を爲すべきか』答へて言ふ『人を劫かし、また誣ひ訴ふな、己が給料をもて足れりとせよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, '民、待ち望みゐたれば、みな心の中にヨハネをキリストならんかと論ぜしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'ヨハネ凡ての人に答へて言ふ『我は水にて汝らにバプテスマを施す、されど我よりも能力ある者きたらん、我はその鞋の紐を解くにも足らず。彼は聖 靈と火とにて汝らにバプテスマを施さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, '手には箕を持ちたまふ。禾場をきよめ、麥を倉に納めんとてなり。而して殼は消えぬ火にて焚きつくさん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'ヨハネこの他なほ、さまざまの勸をなして、民に福音を宣傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, '然るに國守ヘロデ、その兄弟の妻ヘロデヤの事につき、又その行ひたる凡ての惡しき事につきて、ヨハネに責められたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, '更に復 一つの惡しき事を加へて、ヨハネを獄に閉ぢこめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, '民みなバプテスマを受けし時、イエスもバプテスマを受けて祈りゐ給へば、天ひらけ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, '聖 靈、形をなして鴿のごとく其の上に降り、かつ天より聲あり、曰く『なんぢは我が愛しむ子なり、我なんぢを悦ぶ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'イエスの、教を宣べ始め給ひしは、年おほよそ三十の時なりき。人にはヨセフの子と思はれ給へり。ヨセフの父はヘリ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'その先はマタテ、レビ、メルキ、ヤンナイ、ヨセフ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'マタテヤ、アモス、ナホム、エスリ、ナンガイ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'マハテ、マタテヤ、シメイ、ヨセク、ヨダ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'ヨハナン、レサ、ゾロバベル、サラテル、ネリ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'メルキ、アデイ、コサム、エルマダム、エル、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'ヨセ、エリエゼル、ヨリム、マタテ、レビ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'シメオン、ユダ、ヨセフ、ヨナム、エリヤキム、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'メレヤ、メナ、マタタ、ナタン、ダビデ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'エツサイ、オベデ、ボアズ、サラ、ナアソン、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'アミナダブ、アデミン、アルニ、エスロン、パレス、ユダ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'ヤコブ、イサク、アブラハム、テラ、ナホル、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'セルグ、レウ、ペレグ、エベル、サラ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'カイナン、アルパクサデ、セム、ノア、ラメク、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'メトセラ、エノク、ヤレデ、マハラレル、カイナン、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'エノス、セツ、アダムに至る。アダムは神の子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'さてイエス聖 靈にて滿ち、ヨルダン河より歸り、荒野にて四十 日のあひだ御靈に導かれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, '惡魔に試みられ給ふ。この間なにをも食はず、日 數 滿ちてのち餓ゑ給ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, '惡魔いふ『なんぢ若し神の子ならば、此の石に命じてパンと爲らしめよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'イエス答へたまふ『「人の生くるはパンのみに由るにあらず」と録されたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, '惡魔またイエスを携へのぼりて、瞬間に天下のもろもろの國を示して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, '『この凡ての權威と國々の榮華とを汝に與へん。我これを委ねられたれば、我が欲する者に與ふるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'この故にもし我が前に拜せば、ことごとく汝の有となるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'イエス答へて言ひたまふ『「主なる汝の神を拜し、ただ之にのみ事ふべし」と録されたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, '惡魔またイエスをエルサレムに連れゆき、宮の頂上に立たせて言ふ『なんぢ若し神の子ならば、此處より己が身を下に投げよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'それは「なんぢの爲に御使たちに命じて守らしめ給はん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, '「かれら手にて汝をささへ、その足を石に打當つる事なからしめん」と録されたるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'イエス答へて言ひたまふ『「主なる汝の神を試むべからず」と云ひてあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, '惡魔あらゆる嘗試を盡してのち、暫くイエスを離れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'イエス御靈の能力をもてガリラヤに歸り給へば、その聲聞あまねく四方の地に弘る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'かくて諸 會堂にて教をなし、凡ての人に崇められ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, '偖その育てられ給ひし處のナザレに到り、例のごとく安息 日に會堂に入りて、聖書を讀まんとて立ち給ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, '預言者イザヤの書を與へたれば、其の書を繙きて、かく録されたる所を見出し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '『主の御靈われに在す。これ我に油を注ぎて貧しき者に福音を宣べしめ、我をつかはして囚人に赦を得ることと、盲人に見ゆることとを告げしめ、壓へらるる者を放ちて自由を與へしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, '主の喜ばしき年を宣傳へしめ給ふなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'イエス書を卷き、係の者に返して坐し給へば、會堂に居る者みな之に目を注ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'イエス言ひ出でたまふ『この聖書は今日なんぢらの耳に成就したり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, '人々みなイエスを譽め、又その口より出づる惠の言を怪しみて言ふ『これヨセフの子ならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'イエス言ひ給ふ『なんぢら必ず我に俚諺を引きて「醫者よ、みづから己を醫せ、カペナウムにて有りしといふ我らが聞ける事どもを、己が郷なる此の地にても爲せ」と言はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'また言ひ給ふ『われ誠に汝らに告ぐ、預言者は己が郷にて喜ばるることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'われ實をもて汝らに告ぐ、エリヤのとき三年 六个月、天とぢて、全地 大なる饑饉なりしが、イスラエルの中に多くの寡婦ありたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'エリヤは其の一人にすら遣されず、唯シドンなるサレプタの一人の寡婦にのみ遣されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'また預言者エリシヤの時、イスラエルの中に多くの癩病人ありしが、其の一人だに潔められず、唯シリヤのナアマンのみ潔められたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, '會堂にをる者みな之を聞きて憤恚に滿ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, '起ちてイエスを町より逐ひ出し、その町の建ちたる山の崖に引き往きて、投げ落さんとせしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'イエスその中を通りて去り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'かくてガリラヤの町カペナウムに下りて、安息 日ごとに人を教へ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, '人々その教に驚きあへり。その言、權威ありたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, '會堂に穢れし惡鬼の靈に憑かれたる人あり、大聲に叫びて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '『ああ、ナザレのイエスよ、我らは汝となにの關係あらんや。我らを亡さんとて來給ふか。我はなんぢの誰なるを知る、神の聖者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'イエス之を禁めて言ひ給ふ『默せ、その人より出でよ』惡鬼その人を人々の中に倒し、傷つけずして出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'みな驚き語り合ひて言ふ『これ如何なる言ぞ、權威と能力とをもて命ずれば、穢れし惡鬼すら出で去る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'ここにイエスの噂あまねく四方の地に弘りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'イエス會堂を立ち出でて、シモンの家に入り給ふ。シモンの外姑おもき熱を患ひ居たれば、人々これが爲にイエスに願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'その傍らに立ちて熱を責めたまへば、熱 去りて女たちどころに起きて彼らに事ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, '日のいる時、さまざまの病を患ふ者をもつ人、みな之をイエスに連れ來れば、一々その上に手を置きて醫し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, '惡鬼もまた多くの人より出でて叫びつつ言ふ『なんぢは神の子なり』之を責めて物 言ふことを免し給はず、惡鬼そのキリストなるを知るに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, '明くる朝イエス出でて寂しき處にゆき給ひしが、群衆たづねて御許に到り、その去り往くことを止めんとせしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'イエス言ひ給ふ『われ又ほかの町々にも神の國の福音を宣傳へざるを得ず、わが遣されしは之が爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'かくてユダヤの諸 會堂にて教を宣べたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, '群衆おし迫りて神の言を聽きをる時、イエス、ゲネサレの湖のほとりに立ちて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, '渚に二 艘の舟の寄せあるを見たまふ、漁人は舟をいでて網を洗ひ居たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'イエスその一艘なるシモンの舟に乘り、彼に請ひて陸より少しく押し出さしめ、坐して舟の中より群衆を教へたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, '語り終へてシモンに言ひたまふ『深處に乘りいだし、網を下して漁れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'シモン答へて言ふ『君よ、われら終夜 勞したるに、何をも得ざりき、されど御言に隨ひて網を下さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'かくて然せしに、魚の夥多しき群を圍みて、網 裂けかかりたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, '他の一艘の舟にをる組の者を差招きて來り助けしむ。來りて魚を二 艘の舟に滿したれば、舟 沈まんばかりになりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'シモン・ペテロ之を見て、イエスの膝 下に平伏して言ふ『主よ、我を去りたまへ。我は罪ある者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'これはシモンも偕に居る者もみな、漁りし魚の夥多しきに驚きたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'ゼベダイの子にしてシモンの侶なるヤコブもヨハネも同じく驚けり。イエス、シモンに言ひたまふ『懼るな、なんぢ今よりのち人を漁らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'かれら舟を陸につけ、一切を棄ててイエスに從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'イエス或 町に居給ふとき、視よ、全身 癩病をわづらふ者あり。イエスを見て平伏し、願ひて言ふ『主よ、御意ならば、我を潔くなし給ふを得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'イエス手をのべ彼につけて『わが意なり、潔くなれ』と言ひ給へば、直ちに癩病されり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'イエス之を誰にも語らぬやうに命じ、かつ言ひ給ふ『ただ往きて己を祭司に見せ、モーセが命じたるごとく汝の潔のために献物して、人々に證せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'されど彌 増々イエスの事ひろまりて、大なる群衆、あるひは教を聽かんとし、或は病を醫されんとして集り來りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'イエス寂しき處に退きて祈り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, '或 日イエス教をなし給ふとき、ガリラヤの村々、ユダヤ及びエルサレムより來りしパリサイ人、教法 學者ら、そこに坐しゐたり。病を醫すべき主の能力イエスと偕にありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, '視よ、人々、中風を病める者を、床にのせて擔ひきたり、之を家に入れて、イエスの前に置かんとすれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, '群衆によりて擔ひ入るべき道を得ざれば、屋根にのぼり、瓦を取り除けて、床のまま人々の中に、イエスの前につり縋り下せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'イエス彼らの信仰を見て言ひたまふ『人よ、汝の罪ゆるされたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'ここに學者・パリサイ人ら論じ出でて言ふ『瀆言をいふ此の人は誰ぞ、神より他に誰か罪を赦すことを得べき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'イエス彼らの論ずる事をさとり、答へて言ひ給ふ『なにを心のうちに論ずるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, '「なんぢの罪ゆるされたり」と言ふと「起きて歩め」と言ふと孰か易き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, '人の子の地にて罪をゆるす權威あることを汝らに知らせん爲に』――中風を病める者に言ひ給ふ――『なんぢに告ぐ、起きよ、床をとりて家に往け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'かれ立刻に人々の前にて起きあがり、臥しゐたる床をとりあげ、神を崇めつつ己が家に歸りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, '人々みな甚く驚きて神をあがめ懼に滿ちて言ふ『今日われら珍しき事を見たり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'この事の後イエス出でて、レビといふ取税人の收税所に坐しをるを見て『われに從へ』と言ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, '一切を棄ておき、起ちて從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'レビ己が家にて、イエスの爲に大なる饗宴を設けしに、取税人および他の人々も多く食事の席に列りゐたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'パリサイ人および其の曹輩の學者ら、イエスの弟子たちに向ひ、呟きて言ふ『なにゆゑ汝らは取税人・罪人らと共に飮食するか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'イエス答へて言ひたまふ『健康なる者は醫者を要せず、ただ病ある者これを要す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, '我は正しき者を招かんとにあらで、罪人を招きて悔改めさせんとて來れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, '彼らイエスに言ふ『ヨハネの弟子たちは、しばしば斷食し祈祷し、パリサイ人の弟子たちも亦 然するに、汝の弟子たちは飮食するなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'イエス言ひたまふ『新郎の友だち新郎と偕にをるうちは、彼らに斷食せしめ得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'されど日 來りて新郎をとられん、その日には斷食せん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'イエスまた譬を言ひ給ふ『たれも新しき衣を切り取りて、舊き衣を繕ふ者はあらじ。もし然せば、新しきものも破れ、かつ新しきものより取りたる裂も舊きものに合はじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, '誰も新しき葡萄酒を、ふるき革嚢に入るることは爲じ。もし然せば、葡萄酒は嚢をはりさき漏れ出でて、嚢も廢らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, '新しき葡萄酒は、新しき革嚢に入るべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, '誰も舊き葡萄酒を飮みてのち、新しき葡萄酒を望む者はあらじ。「舊きは善し」と云へばなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'イエス安息 日に麥 畠を過ぎ給ふとき、弟子たち穗を摘み、手にて揉みつつ食ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'パリサイ人のうち或 者ども言ふ『なんぢらは何ゆゑ安息 日に爲まじき事をするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'イエス答へて言ひ給ふ『ダビデその伴へる人々とともに飢ゑしとき、爲しし事をすら讀まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, '即ち神の家に入りて、祭司の他は食ふまじき供のパンを取りて食ひ、己と偕なる者にも與へたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'また言ひたまふ『人の子は安息 日の主たるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, '又ほかの安息 日に、イエス會堂に入りて教をなし給ひしに、此處に人あり、其の右の手なえたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, '學者・パリサイ人ら、イエスを訴ふる廉を見出さんと思ひて、安息 日に人を醫すや否やを窺ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'イエス彼らの念を知りて、手なえたる人に『起きて中に立て』と言ひ給へば、起きて立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'イエス彼らに言ひ給ふ『われ汝らに問はん、安息 日に善をなすと惡をなすと、生命を救ふと亡すと、孰かよき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'かくて一同を見まはして、手なえたる人に『なんぢの手を伸べよ』と言ひ給ふ。かれ然なしたれば、その手 癒ゆ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, '然るに彼ら狂氣の如くなりて、イエスに何をなさんと語り合へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'その頃イエス祈らんとて山にゆき、神に祈りつつ夜を明したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, '夜明になりて弟子たちを呼び寄せ、その中より十二 人を選びて、之を使徒と名づけたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, '即ちペテロと名づけ給ひしシモンと其の兄弟アンデレと、ヤコブとヨハネと、ピリポとバルトロマイと、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'マタイとトマスと、アルパヨの子ヤコブと熱心 黨と呼ばるるシモンと、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'ヤコブの子ユダとイスカリオテのユダとなり。このユダはイエスを賣る者となりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'イエス此 等とともに下りて、平かなる處に立ち給ひしに、弟子の大なる群衆、およびユダヤ全國、エルサレム又ツロ、シドンの海邊より來りて、或は教を聽かんとし、或は病を醫されんとする民の大なる群も、そこにあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, '穢れし靈に惱されたる者も醫される。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, '能力イエスより出でて、凡ての人を醫せば、群衆みなイエスに觸らん事を求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'イエス目をあげ弟子たちを見て言ひたまふ『幸福なるかな、貧しき者よ、神の國は汝らの有なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, '幸福なる哉、いま飢うる者よ、汝ら飽くことを得ん。幸福なる哉、いま泣く者よ、汝ら笑ふことを得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, '人なんぢらを憎み、人の子のために遠ざけ、謗り、汝らの名を惡しとして棄てなば、汝ら幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'その日には喜び躍れ。視よ、天にて汝らの報は大なり、彼らの先祖が預言者たちに爲ししも斯くありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'されど禍害なるかな、富む者よ、汝らは既にその慰安を受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, '禍害なる哉、いま飽く者よ、汝らは飢ゑん。禍害なる哉、いま笑ふ者よ、汝らは、悲しみ泣かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, '凡ての人、なんぢらを譽めなば、汝ら禍害なり。彼らの先祖が虚僞の預言者たちに爲ししも斯くありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'われ更に汝ら聽くものに告ぐ、なんじらの仇を愛し、汝らを憎む者を善くし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, '汝らを詛ふ者を祝し、汝らを辱しむる者のために祈れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'なんぢの頬を打つ者には、他の頬をも向けよ。なんぢの上衣を取る者には下衣をも拒むな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'すべて求むる者に與へ、なんぢの物を奪ふ者に復 索むな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'なんぢら人に爲られんと思ふごとく、人にも然せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'なんぢら己を愛する者を愛せばとて、何の嘉すべき事あらん、罪人にても己を愛する者を愛するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, '汝 等おのれに善をなす者に善を爲すとも、何の嘉すべき事あらん、罪人にても然するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'なんぢら得る事あらんと思ひて人に貸すとも、何の嘉すべき事あらん、罪人にても均しきものを受けんとて罪人に貸すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, '汝らは仇を愛し、善をなし、何をも求めずして貸せ、さらば、その報は大ならん。かつ至高者の子たるべし。至高者は、恩を知らぬもの惡しき者にも、仁慈あるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, '汝らの父の慈悲なるごとく、汝らも慈悲なれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, '人を審くな、さらば汝らも審かるる事あらじ。人を罪に定むな、さらば、汝らも罪に定めらるる事あらじ。人を赦せ、さらば汝らも赦されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, '人に與へよ、さらば汝らも與へられん。人は量をよくし、押し入れ、搖り入れ、溢るるまでにして、汝らの懷中に入れん。汝 等おのが量る量にて量らるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'また譬にて言ひたまふ『盲人は盲人を手引するを得んや。二人とも穴に落ちざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, '弟子はその師に勝らず、凡そ全うせられたる者は、その師の如くならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, '何ゆゑ兄弟の目にある塵を見て、己が目にある梁木を認めぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'おのが目にある梁木を見ずして、爭で兄弟に向ひて「兄弟よ、汝の目にある塵を取り除かせよ」といふを得んや。僞善者よ、先づ己が目より梁木を取り除け。さらば明かに見えて、兄弟の目にある塵を取りのぞき得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, '惡しき果を結ぶ善き樹はなく、また善き果を結ぶ惡しき樹はなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, '樹はおのおの其の果によりて知らる。茨より無花果を取らず、野荊より葡萄を收めざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, '善き人は心の善き倉より善きものを出し、惡しき人は惡しき倉より惡しき物を出す。それ心に滿つるより、口は物 言ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'なんぢら我を「主よ主よ」と呼びつつ、何ぞ我が言ふことを行はぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, '凡そ我にきたり我が言を聽きて行ふ者は、如何なる人に似たるかを示さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, '即ち家を建つるに、地を深く掘り岩の上に基を据ゑたる人のごとし。洪水いでて流その家を衝けども動かすこと能はず、これ固く建てられたる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'されど聽きて行はぬ者は、基なくして家を土の上に建てたる人のごとし。流その家を衝けば、直ちに崩れて、その破壞はなはだし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'イエス凡て此らの言を民に聞かせ終へて後、カペナウムに入り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, '時に或 百卒長、その重んずる僕やみて死ぬばかりなりしかば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'イエスの事を聽きて、ユダヤ人の長老たちを遣し、來りて僕を救ひ給はんことを願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, '彼らイエスの許にいたり、切に請ひて言ふ『かの人は此の事を爲らるるに相應し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'わが國人を愛し、我らのために會堂を建てたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'イエス共に往き給ひて、その家はや程 近くなりしとき、百卒長、數人の友を遣して言はしむ『主よ、自らを煩はし給ふな。我は汝をわが屋根の下に入れまつるに足らぬ者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'されば御前に出づるにも相應しからずと思へり、ただ御言を賜ひて我が僕をいやし給へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, '我みづから權威の下に置かるる者なるに、我が下にまた兵卒ありて、此に「往け」と言へば往き、彼に「來れ」と言へば來り、わが僕に「これを爲せ」と言へば爲すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'イエス聞きて彼を怪しみ、振反りて從ふ群衆に言ひ給ふ『われ汝らに告ぐ、イスラエルの中にだに斯かるあつき信仰は見しことなし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, '遣されたる者ども家に歸りて僕を見れば、既に健康となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'その後イエス、ナインといふ町にゆき給ひしに、弟子たち及び大なる群衆も共に往く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, '町の門に近づき給ふとき、視よ、舁き出さるる死人あり。これは獨 息子にて母は寡婦なり、町の多くの人々これに伴ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, '主、寡婦を見て憫み『泣くな』と言ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, '近より、柩に手をつけ給へば、舁くもの立ち止る。イエス言ひたまふ『若者よ、我なんぢに言ふ、起きよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, '死人、起きかへりて物 言ひ始む。イエス之を母に付したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, '人々みな懼をいだき、神を崇めて言ふ『大なる預言者われらの中に興れり』また言ふ『神その民を顧み給へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'この事ユダヤ全國および最寄の地に徧くひろまりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, '偖ヨハネの弟子たち、凡て此 等のことを告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'ヨハネ兩 三人の弟子を呼び、主に遣して言はしむ『來るべき者は汝なるか、或は他に待つべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, '彼ら御許に到りて言ふ『バプテスマのヨハネ、我らを遣して言はしむ「來るべき者は汝なるか、或は他に待つべきか」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'この時イエス多くの者の病・疾患を醫し、惡しき靈を逐ひいだし、又おほくの盲人に見ることを得しめ給ひしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, '答へて言ひたまふ『往きて汝らが見 聞せし所をヨハネに告げよ。盲人は見、跛者はあゆみ、癩病人は潔められ、聾者はきき、死人は甦へらせられ、貧しき者は福音を聞かせらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'おほよそ我に躓かぬ者は幸福なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'ヨハネの使の去りたる後、ヨハネの事を群衆に言ひいで給ふ『なんぢら何を眺めんとて野に出でし、風にそよぐ葦なるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'さらば何を見んとて出でし、柔かき衣を著たる人なるか。視よ、華美なる衣をきて奢り暮す者は王宮に在り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'さらば何を見んとて出でし、預言者なるか。然り、我なんぢらに告ぐ、預言者よりも勝る者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, '「視よ、わが使を汝の顏の前につかはす。かれは汝の前になんじの道をそなへん」と録されたるは此の人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'われ汝らに告ぐ、女の産みたる者の中、ヨハネより大なる者はなし。されど神の國にて小き者も、彼よりは大なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, '(凡ての民これを聞きて、取税人までも神を正しとせり。ヨハネのバプテスマを受けたるによる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'されどパリサイ人・教法師らは、其のバプテスマを受けざりしにより、各自にかかはる神の御旨をこばみたり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'さればわれ今の代の人を何に比へん。彼らは何に似たるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, '彼らは、童 市場に坐し、たがひに呼びて「われら汝らの爲に笛 吹きたれど、汝ら躍らず。歎きたれど、汝ら泣かざりき」と云ふに似たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'それはバプテスマのヨハネ來りて、パンをも食はず葡萄酒をも飮まねば、「惡鬼に憑かれたる者なり」と汝ら言ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, '人の子きたりて飮食すれば「視よ、食を貪り、酒を好む人、また取税人・罪人の友なり」と汝ら言ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'されど智慧は己が凡ての子によりて正しとせらる』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'ここに或パリサイ人ともに食せん事をイエスに請ひたれば、パリサイ人の家に入りて、席につき給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, '視よ、この町に罪ある一人の女あり。イエスのパリサイ人の家にて食事の席にゐ給ふを知り、香 油の入りたる石膏の壺を持ちきたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, '泣きつつ御足 近く後にたち、涙にて御足をうるほし、頭の髮にて之を拭ひ、また御足に接吻して香 油を抹れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'イエスを招きたるパリサイ人これを見て、心のうちに言ふ『この人もし預言者ならば、觸る者の誰、如何なる女なるかを知らん、彼は罪人なるに』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'イエス答へて言ひ給ふ『シモン、我なんぢに言ふことあり』シモンいふ『師よ、言ひたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '『或 債主に二人の負債者ありて、一人はデナリ五 百、一人は五 十の負債せしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, '償ひかたなければ、債主この二人を共に免せり。されば二人のうち債主を愛すること孰か多き』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'シモン答へて言ふ『われ思ふに、多く免されたる者ならん』イエス言ひ給ふ『なんぢの判斷は當れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'かくて女の方に振向きてシモンに言ひ給ふ『この女を見るか。我なんぢの家に入りしに、なんぢは我に足の水を與へず、此の女は涙にて我 足を濡し、頭髮にて拭へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'なんぢは我に接吻せず、此の女は我が入りし時より、我が足に接吻して止まず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'なんぢは我が頭に油を抹らず、此の女は我が足に香 油を抹れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'この故に我なんぢに告ぐ、この女の多くの罪は赦されたり。その愛すること大なればなり。赦さるる事の少き者は、その愛する事もまた少し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, '遂に女に言ひ給ふ『なんぢの罪は赦されたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, '同席の者ども心の内に『罪をも赦す此の人は誰なるか』と言ひ出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'ここにイエス女に言ひ給ふ『なんぢの信仰なんぢを救へり、安らかに往け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'この後イエス教を宣べ、神の國の福音を傳へつつ、町々 村々を廻り給ひしに、十二 弟子も伴ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'また前に惡しき靈を逐ひ出され、病を醫されなどせし女たち、即ち七つの惡鬼のいでしマグラダと呼ばるるマリヤ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'ヘロデの家 司クーザの妻ヨハンナ及びスザンナ、此の他にも多くの女ともなひゐて、其の財産をもて彼らに事へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, '大なる群衆むらがり、町々の人みもとに寄り集ひたれば、譬をもて言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '『種 播く者その種を播かんとて出づ。播くとき路の傍らに落ちし種あり、踏みつけられ、また空の鳥これを啄む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, '岩の上に落ちし種あり、生え出でたれど潤澤なきによりて枯る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, '茨の中に落ちし種あり、茨も共に生え出でて之を塞ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, '良き地に落ちし種あり、生え出でて百 倍の實を結べり』これらの事を言ひて呼はり給ふ『きく耳ある者は聽くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, '弟子たち此の譬の如何なる意なるかを問ひたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'イエス言ひ給ふ『なんぢらは神の國の奧義を知ることを許されたれど、他の者は譬にてせらる。彼らの見て見ず、聞きて悟らぬ爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, '譬の意は是なり。種は神の言なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, '路の傍らなるは、聽きたるのち、惡魔きたり、信じて救はるる事のなからんために、御言をその心より奪ふ所の人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, '岩の上なるは、聽きて御言を喜び受くれども、根なければ、暫く信じて嘗試のときに退く所の人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, '茨の中に落ちしは、聽きてのち過ぐるほどに、世の心勞と財貨と快樂とに塞がれて實らぬ所の人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, '良き地なるは、御言を聽き、正しく善き心にて之を守り、忍びて實を結ぶ所の人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, '誰も燈火をともし器にて覆ひ、または寢臺の下におく者なし、入り來る者のその光を見んために、之を燈臺の上に置くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'それ隱れたるものの顯れぬはなく、秘めたるものの知られぬはなく、明かにならぬはなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'されば汝ら聽くこと如何にと心せよ、誰にても有てる人はなほ與へられ、有たぬ人はその有てりと思ふ物をも取らるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'さてイエスの母と兄弟と來りたれど、群衆によりて近づくこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, '或 人イエスに『なんぢの母と兄弟と、汝に逢はんとて外に立つ』と告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, '答へて言ひたまふ『わが母わが兄弟は、神の言を聽き、かつ行ふ此らの者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, '或 日イエス弟子たちと共に舟に乘りて『みづうみの彼方にゆかん』と言ひ給へば、乃ち船出す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, '渡るほどにイエス眠りたまふ。颶風みづうみに吹き下し、舟に水 滿ちんとして危かりしかば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, '弟子たち御側により、呼び起して言ふ『君よ、君よ、我らは亡ぶ』イエス起きて風と浪とを禁め給へば、ともに鎭りて凪となりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'かくて弟子たちに言ひ給ふ『なんぢらの信仰いづこに在るか』かれら懼れ怪しみて互に言ふ『こは誰ぞ、風と水とに命じ給へば順ふとは』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, '遂にガリラヤに對へるゲラセネ人の地に著く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, '陸に上りたまふ時、その町の人にて惡鬼に憑かれたる者きたり遇ふ。この人は久しきあひだ衣を著ず、また家に住まずして墓の中にゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'イエスを見てさけび、御前に平伏して大聲にいふ『至高き神の子イエスよ、我は汝と何の關係あらん、願はくは我を苦しめ給ふな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'これはイエス穢れし靈に、この人より出で往かんことを命じ給ひしに因る。この人けがれし靈にしばしば拘へられ、鏈と足械とにて繋ぎ守られたれど、その繋をやぶり、惡鬼に逐はれて荒野に往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'イエス之に『なんぢの名は何か』と問ひ給へば『レギオン』と答ふ、多くの惡鬼その中に入りたる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, '彼らイエスに、底なき所に往くを命じ給はざらんことを請ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, '彼處の山に、多くの豚の一 群、食し居たりしが、惡鬼ども其の豚に入るを許し給はんことを請ひたれば、イエス許し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, '惡鬼、人を出でて豚に入りたれば、その群、崖より湖水に駈け下りて溺れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, '飼ふ者ども此の起りし事を見て、逃げ往きて、町にも里にも告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, '人々ありし事を見んとて出で、イエスに來りて、惡鬼の出でたる人の、衣服をつけ慥なる心にて、イエスの足下に坐しをるを見て懼れあへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'かの惡鬼に憑かれたる人の救はれし事柄を見し者ども、之を彼らに告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'ゲラセネ地方の民衆、みなイエスに出で去り給はんことを請ふ。これ大に懼れたるなり。ここにイエス舟に乘りて歸り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, '時に惡鬼の出でたる人、ともに在らんことを願ひたれど、之を去らしめんとて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '言ひ給ふ『なんぢの家に歸りて、神が如何に大なる事を汝になし給ひしかを具に告げよ』彼ゆきて、イエスの如何に大なる事を己になし給ひしかを、徧くその町に言ひ弘めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'かくてイエスの歸り給ひしとき、群衆これを迎ふ、みな待ちゐたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, '視よ、會堂 司にてヤイロといふ者あり、來りてイエスの足下に伏し、その家にきたり給はんことを願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'おほよそ十二 歳ほどの一人 娘ありて、死ぬばかりなる故なり。イエスの往き給ふとき、群衆かこみ塞がる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'ここに十 二年このかた血漏を患ひて、醫者の爲に己が身代をことごとく費したれども、誰にも癒され得ざりし女あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'イエスの後に來りて、御衣の總にさはりたれば、血の出づること立刻に止みたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'イエス言ひ給ふ『我に觸りしは誰ぞ』人みな否みたれば、ペテロ及び共にをる者ども言ふ『君よ、群衆なんぢを圍みて押迫るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'イエス言ひ給ふ『われに觸りし者あり、能力の我より出でたるを知る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, '女おのれが隱れ得ぬことを知り、戰き來りて御前に平伏し、觸りし故と立刻に癒えたる事を、人々の前にて告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'イエス言ひ給ふ『むすめよ、汝の信仰なんぢを救へり、安らかに往け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'かく語り給ふほどに、會堂 司の家より人きたりて言ふ『なんぢの娘は早や死にたり、師を煩はすな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'イエス之を聞きて會堂 司に答へたまふ『懼るな、ただ信ぜよ。さらば娘は救はれん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'イエス家に到りて、ペテロ、ヨハネ、ヤコブ及び子の父 母の他は、ともに入ることを誰にも許し給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, '人みな泣き、かつ子のために歎き居たりしが、イエス言ひたまふ『泣くな、死にたるにあらず、寢ねたるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, '人々その死にたるを知れば、イエスを嘲笑ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, '然るにイエス子の手をとり、呼びて『子よ、起きよ』と言ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'その靈かへりて立刻に起く。イエス食物を之に與ふることを命じ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'その兩親おどろきたり。イエス此の有りし事を誰にも語らぬやうに命じ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'イエス十二 弟子を召し寄せて、もろもろの惡鬼を制し、病をいやす能力と權威とを與へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'また神の國を宣傳へしめ、人を醫さしむる爲に、之を遣さんとして言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, '『旅のために何をも持つな、杖も袋も糧も銀も、また二つの下衣をも持つな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'いづれの家に入るとも、其處に留れ、而して其處より立ち去れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, '人もし汝らを受けずば、その町を立ち去るとき、證のために足の塵を拂へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'ここに弟子たち出でて村々を歴 巡り、あまねく福音を宣傳へ、醫すことを爲せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'さて國守ヘロデ、ありし凡ての事をききて周章てまどふ。或 人はヨハネ死人の中より甦へりたりといひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, '或 人はエリヤ現れたりといひ、また或 人は、古への預言者の一人よみがへりたりと言へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'ヘロデ言ふ『ヨハネは我すでに首斬りたり、然るに斯かる事のきこゆる此の人は誰なるか』かくてイエスを見んことを求めゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, '使徒たち歸りきて、其の爲しし事を具にイエスに告ぐ。イエス彼らを携へて竊にベツサイダといふ町に退きたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'されど群衆これを知りて從ひ來りたれば、彼らを接けて、神の國の事を語り、かつ治療を要する人々を醫したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, '日 傾きたれば、十二 弟子きたりて言ふ『群衆を去らしめ、周圍の村また里にゆき、宿をとりて食物を求めさせ給へ。我らは斯かる寂しき所に居るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'イエス言ひ給ふ『なんぢら食物を與へよ』弟子たち言ふ『我らただ五つのパンと二つの魚とあるのみ、此の多くの人のために、往きて買はねば他に食物なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, '男おほよそ五 千 人ゐたればなり。イエス弟子たちに言ひたまふ『人々を組にして五 十 人づつ坐せしめよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, '彼 等その如くなして、人々をみな坐せしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'かくてイエス五つのパンと二つの魚とを取り、天を仰ぎて祝し、擘きて弟子たちに付し、群衆のまへに置かしめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, '彼らは食ひて皆 飽く。擘きたる餘を集めしに十二 筐ほどありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'イエス人々を離れて祈り居給ふとき、弟子たち偕にをりしに、問ひて言ひたまふ『群衆は我を誰といふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, '答へて言ふ『バプテスマのヨハネ、或 人はエリヤ、或 人は古への預言者の一人よみがへりたりと言ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'イエス言ひ給ふ『なんぢらは我を誰と言ふか』ペテロ答へて言ふ『神のキリストなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'イエス彼らを戒めて、之を誰にも告げぬやうに命じ、かつ言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, '『人の子は必ず多くの苦難をうけ、長老・祭司長・學者らに棄てられ、かつ殺され、三日めに甦へるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'また一同の者に言ひたまふ『人もし我に從ひ來らんと思はば、己をすて、日々おのが十字架を負ひて我に從へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, '己が生命を救はんと思ふ者は之を失ひ、我がために己が生命を失ふその人は之を救はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, '人、全世界を贏くとも、己をうしなひ己を損せば、何の益あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, '我と我が言とを恥づる者をば、人の子もまた、己と父と聖なる御使たちとの榮光をもて來らん時に恥づべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'われ實をもて汝らに告ぐ、此處に立つ者のうちに、神の國を見るまでは死を味はぬ者どもあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'これらの言をいひ給ひしのち八日ばかり過ぎて、ペテロ、ヨハネ、ヤコブを率きつれ、祈らんとて山に登り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'かくて祈り給ふほどに、御顏の状かはり、其の衣 白くなりて輝けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, '視よ、二人の人ありてイエスと共に語る。これはモーセとエリヤとにて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, '榮光のうちに現れ、イエスのエルサレムにて遂げんとする逝去のことを言ひゐたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'ペテロ及び共にをる者いたく睡氣ざしたれど、目を覺してイエスの榮光および偕に立つ二人を見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, '二人の者イエスと別れんとする時、ペテロ、イエスに言ふ『君よ、我らの此處に居るは善し、我ら三つの廬を造り、一つを汝のため、一つをモーセのため、一つをエリヤの爲にせん』彼は言ふ所を知らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'この事を言ひ居るほどに、雲おこりて彼らを覆ふ。雲の中に入りしとき、弟子たち懼れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, '雲より聲 出でて言ふ『これは我が選びたる子なり、汝ら之に聽け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, '聲 出でしとき、唯イエスひとり見え給ふ。弟子たち默して、見し事を何 一つ其の頃たれにも告げざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, '次の日、山より下りたるに、大なる群衆イエスを迎ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, '視よ、群衆のうちの或 人さけびて言ふ『師よ、願はくは我が子を顧みたまへ、之は我が獨子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, '視よ、靈の憑くときは俄に叫ぶ、痙攣けて沫をふかせ、甚く害ひ、漸くにして離るるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, '御弟子たちに之を逐ひ出すことを請ひたれど、能はざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'イエス答へて言ひ給ふ『ああ信なき曲れる代なる哉、われ何時まで汝らと偕にをりて、汝らを忍ばん。汝の子をここに連れ來れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, '乃ち來るとき、惡鬼これを打ち倒し、甚く痙攣けさせたり。イエス穢れし靈を禁め、子を醫して、その父に付したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, '人々みな神の稜威に驚きあへり。人々みなイエスの爲し給ひし凡ての事を怪しめる時、イエス弟子たちに言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '『これらの言を汝らの耳にをさめよ。人の子は人々の手に付さるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'かれら此の言を悟らず、辨へぬやうに隱されたるなり。また此の言につきて問ふことを懼れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'ここに弟子たちの中に、誰か大ならんとの爭論おこりたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'イエスその心の爭論を知りて、幼兒をとり御側に置きて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, '『おほよそ我が名のために此の幼兒を受くる者は、我を受くるなり。我を受くる者は、我を遣しし者を受くるなり。汝らの中にて最も小き者は、これ大なるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'ヨハネ答へて言ふ『君よ、御名によりて惡鬼を逐ひいだす者を見しが、我等とともに從はぬ故に、之を止めたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'イエス言ひ給ふ『止むな。汝らに逆はぬ者は、汝らに附く者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'イエス天に擧げらるる時 滿ちんとしたれば、御顏を堅くエルサレムに向けて進まんとし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, '己に先だちて使を遣したまふ。彼ら往きてイエスの爲に備をなさんとて、サマリヤ人の或 村に入りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, '村 人そのエルサレムに向ひて往き給ふさまなるが故に、イエスを受けず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, '弟子のヤコブ、ヨハネ、これを見て言ふ『主よ、我らが天より火を呼び下して彼らを滅すことを欲し給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'イエス顧みて彼らを戒め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, '遂に相 共に他の村に往きたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, '途を往くとき、或 人イエスに言ふ『何處に往き給ふとも我は從はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'イエス言ひたまふ『狐は穴あり、空の鳥は塒あり、されど人の子は枕する所なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'また或 人に言ひたまふ『我に從へ』かれ言ふ『まづ往きて我が父を葬ることを許し給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'イエス言ひたまふ『死にたる者に、その死にたる者を葬らせ、汝は往きて神の國を言ひ弘めよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'また或 人いふ『主よ、我なんぢに從はん、されど先づ家の者に別を告ぐることを許し給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'イエス言ひたまふ『手を鋤につけてのち後を顧みる者は、神の國に適ふ者にあらず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'この事ののち、主、ほかに七 十 人をあげて、自ら往かんとする町々 處々へ、おのれに先だち二人づつを遣さんとして言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, '『收穫はおほく、勞働人は少し。この故に收穫の主に、勞働人をその收穫場に遣し給はんことを求めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, '往け、視よ、我なんぢらを遣すは、羔羊を豺狼のなかに入るるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, '財布も袋も鞋も携ふな。また途にて誰にも挨拶すな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, '孰の家に入るとも、先づ平安この家にあれと言へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'もし平安の子そこに居らば、汝らの祝する平安はその上に留らん。もし然らずば、其の平安は汝らに歸らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'その家にとどまりて、與ふる物を食ひ飮みせよ。勞働人のその値を得るは相應しきなり。家より家に移るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, '孰の町に入るとも、人々なんぢらを受けなば、汝らの前に供ふる物を食し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, '其處にをる病のものを醫し、また「神の國は汝らに近づけり」と言へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, '孰の町に入るとも、人々なんじらを受けずば、大路に出でて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '「我らの足につきたる汝らの町の塵をも、汝らに對して拂ひ棄つ、されど神の國の近づけるを知れ」と言へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'われ汝らに告ぐ、かの日にはソドムの方その町よりも耐へ易からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, '禍害なる哉、コラジンよ、禍害なる哉、ベツサイダよ、汝らの中にて行ひたる能力ある業を、ツロとシドンとにて行ひしならば、彼らは早く荒布をき、灰のなかに坐して、悔改めしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'されば審判には、ツロとシドンとのかた汝 等よりも耐へ易からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'カペナウムよ、汝は天にまで擧げらるべきか、黄泉にまで下らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, '汝 等に聽く者は我に聽くなり、汝らを棄つる者は我を棄つるなり。我を棄つる者は我を遣し給ひし者を棄つるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, '七 十 人よろこび歸りて言ふ『主よ、汝の名によりて惡鬼すら我らに服す』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'イエス彼らに言ひ給ふ『われ天より閃く電光のごとくサタンの落ちしを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, '視よ、われ汝らに蛇・蠍を踏み、仇の凡ての力を抑ふる權威を授けたれば、汝らを害ふもの斷えてなからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'されど靈の汝らに服するを喜ぶな、汝らの名の天に録されたるを喜べ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'その時イエス聖 靈により喜びて言ひたまふ『天 地の主なる父よ、われ感謝す、此 等のことを智きもの慧き者に隱して、嬰兒に顯したまへり。父よ、然り、此のごときは御意に適へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, '凡ての物は我わが父より委ねられたり。子の誰なるを知る者は、父の外になく、父の誰なるを知る者は、子また子の欲するままに顯すところの者の外になし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'かくて弟子たちを顧み竊に言ひ給ふ『なんぢらの見る所を見る眼は幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'われ汝らに告ぐ、多くの預言者も、王も、汝らの見るところを見んと欲したれど見ず、汝らの聞く所を聞かんと欲したれど聞かざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, '視よ、或 教法師、立ちてイエスを試みて言ふ『師よ、われ永遠の生命を嗣ぐためには何をなすべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'イエス言ひたまふ『律法に何と録したるか、汝いかに讀むか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, '答へて言ふ『なんぢ心を盡し精神を盡し、力を盡し、思を盡して、主たる汝の神を愛すべし。また己のごとく汝の隣を愛すべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'イエス言ひ給ふ『なんぢの答は正し。之を行へ、さらば生くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, '彼おのれを義とせんとしてイエスに言ふ『わが隣とは誰なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'イエス答へて言ひたまふ『或 人エルサレムよりエリコに下るとき強盜にあひしが、強盜どもその衣を剥ぎ、傷を負はせ、半死半生にして棄て去りぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, '或 祭司たまたま此の途より下り、之を見てかなたを過ぎ往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, '又レビ人も此處にきたり、之を見て同じく彼方を過ぎ往けり');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, '然るに或るサマリヤ人、旅して其の許にきたり、之を見て憫み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, '近寄りて油と葡萄酒とを注ぎ、傷を包みて己が畜にのせ、旅舍に連れゆきて介抱し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'あくる日デナリ二つを出し、主人に與へて「この人を介抱せよ。費もし増さば、我が歸りくる時に償はん」と言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, '汝いかに思ふか、此の三人のうち、孰か強盜にあひし者の隣となりしぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'かれ言ふ『その人に憐憫を施したる者なり』イエス言ひ給ふ『なんぢも往きて其の如くせよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'かくて彼ら進みゆく間に、イエス或 村に入り給へば、マルタと名づくる女おのが家に迎へ入る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'その姉妹にマリヤといふ者ありて、イエスの足下に坐し、御言を聽きをりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'マルタ饗應のこと多くして心いりみだれ、御許に進みよりて言ふ『主よ、わが姉妹われを一人のこして働かするを、何とも思ひ給はぬか、彼に命じて我を助けしめ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, '主、答へて言ひ給ふ『マルタよ、マルタよ、汝さまざまの事により、思ひ煩ひて心勞す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'されど無くてならぬものは多からず、唯一つのみ、マリヤは善きかたを選びたり。此は彼より奪ふべからざるものなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'イエス或 處にて祈り居給ひしが、その終りしとき、弟子の一人いふ『主よ、ヨハネの其の弟子に教へし如く、祈ることを我らに教へ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'イエス言ひ給ふ『なんぢら祈るときに斯く言へ「父よ、願はくは御名の崇められん事を。御國の來らん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, '我らの日用の糧を日毎に與へ給へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, '我らに負債ある凡ての者を我ら免せば、我らの罪をも免し給へ。我らを嘗試にあはせ給ふな」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'また言ひ給ふ『なんぢらの中たれか友あらんに、夜半にその許に往きて「友よ、我に三つのパンを貸せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'わが友、旅より來りしに、之に供ふべき物なし」と言ふ時、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'かれ内より答へて「われを煩はすな、戸ははや閉ぢ、子らは我と共に臥所にあり、起ちて與へ難し」といふ事ありとも、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'われ汝らに告ぐ、友なるによりては起ちて與へねど、求の切なるにより、起きて其の要する程のものを與へん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'われ汝らに告ぐ、求めよ、さらば與へられん。尋ねよ、さらば見出さん。門を叩け、さらば開かれん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'すべて求むる者は得、尋ぬる者は見出し、門を叩く者は開かるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, '汝 等のうち父たる者、たれか其の子 魚を求めんに、魚の代に蛇を與へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, '卵を求めんに蠍を與へんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'さらば汝ら惡しき者ながら、善き賜物をその子らに與ふるを知る。まして天の父は、求むる者に聖 靈を賜はざらんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'さてイエス唖の惡鬼を逐ひいだし給へば、惡鬼いでて唖もの言ひしにより、群衆あやしめり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, '其の中の或 者ども言ふ『かれは惡鬼の首ベルゼブルによりて惡鬼を逐ひ出すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'また或 者どもは、イエスを試みんとて天よりの徴を求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'イエスその思を知りて言ひ給ふ『すべて分れ爭ふ國は亡び、分れ爭ふ家は倒る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'サタンもし分れ爭はば、その國いかで立つべき。汝 等わが惡鬼を逐ひ出すを、ベルゼブルに由ると言へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, '我もしベルゼブルによりて惡鬼を逐ひ出さば、汝らの子は誰によりて之を逐ひ出すか。この故に彼らは汝らの審判 人となるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'されど我もし神の指によりて惡鬼を逐ひ出さば、神の國は既に汝らに到れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, '強きもの武具をよろひて己が屋敷を守るときは、其の所有 安全なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'されど更に強きもの來りて之に勝つときは、恃とする武具をことごとく奪ひて、分捕物を分たん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, '我と偕ならぬ者は我にそむき、我と共に集めぬ者は散すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, '穢れし靈、人を出づる時は、水なき處を巡りて休を求む。されど得ずして言ふ「わが出でし家に歸らん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, '歸りて其の家の掃き淨められ、飾られたるを見、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, '遂に往きて己よりも惡しき他の七つの靈を連れきたり、共に入りて此處に住む。さればその人の後の状は、前よりも惡しくなるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, '此 等のことを言ひ給ふとき、群衆の中より或 女、聲をあげて言ふ『幸福なるかな、汝を宿しし胎、なんぢの哺ひし乳房は』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'イエス言ひたまふ『更に幸福なるかな、神の言を聽きて之を守る人は』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, '群衆おし集れる時、イエス言ひ出でたまふ『今の世は邪曲なる代にして徴を求む。されどヨナの徴のほかに徴は與へられじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'ヨナがニネベの人に徴となりし如く、人の子もまた今の代に然らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, '南の女王、審判のとき、今の代の人と共に起きて之が罪を定めん。彼はソロモンの智慧を聽かんとて地の極より來れり。視よ、ソロモンよりも勝るもの此處にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'ニネベの人、審判のとき、今の代の人と共に立ちて之が罪を定めん。彼らはヨナの宣ぶる言によりて悔改めたり。視よ、ヨナよりも勝るもの此處に在り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, '誰も燈火をともして、穴藏の中または升の下におく者なし。入り來る者の光を見んために、燈臺の上に置くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, '汝の身の燈火は目なり、汝の目 正しき時は、全身 明るからん。されど惡しき時は、身もまた暗からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'この故に汝の内の光、闇にはあらぬか、省みよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'もし汝の全身 明るくして暗き所なくば、輝ける燈火に照さるる如く、その身 全く明るからん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'イエスの語り給へるとき、或パリサイ人その家にて食事し給はん事を請ひたれば、入りて席に著きたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, '食事 前に手を洗ひ給はぬを、此のパリサイ人 見て怪しみたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, '主これに言ひたまふ『今や汝らパリサイ人は、酒杯と盆との外を潔くす、されど汝らの内は貪慾と惡とにて滿つるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, '愚なる者よ、外を造りし者は、内をも造りしならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, '唯その内にある物を施せ。さらば一切の物なんぢらの爲に潔くなるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, '禍害なるかな、パリサイ人よ、汝らは薄荷・芸香その他あらゆる野菜の十分の一を納めて、公平と神に對する愛とを等閑にす、されど之は行ふべきものなり。而して彼もまた等閑にすべきものならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, '禍害なるかな、パリサイ人よ、汝らは會堂の上座、市場にての敬禮を喜ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, '禍害なるかな、汝らは露れぬ墓のごとし。其の上を歩む人これを知らぬなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, '教法師の一人、答へて言ふ『師よ、斯かることを言ふは、我らをも辱しむるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'イエス言ひ給ふ『なんぢら教法師も禍害なる哉。なんぢら擔ひ難き荷を人に負せて、自ら指 一つだに其の荷につけぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, '禍害なるかな、汝らは預言者たちの墓を建つ、之を殺しし者は汝らの先祖なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'げに汝らは先祖の所作を可しとする證人ぞ。それは彼らは之を殺し、汝らは其の墓を建つればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'この故に神の智慧いへる言あり、われ預言者と使徒とを彼らに遣さんに、その中の或 者を殺し、また逐ひ苦しめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, '世の創より流されたる凡ての預言者の血、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, '即ちアベルの血より、祭壇と聖所との間にて殺されたるザカリヤの血に至るまでを、今の代に糺すべきなり。然り、われ汝らに告ぐ、今の代は糺さるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, '禍害なるかな教法師よ、なんぢらは知識の鍵を取り去りて自ら入らず、入らんとする人をも止めしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, '此處より出で給へば、學者・パリサイ人ら烈しく詰め寄せて、樣々のことを詰りはじめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'その口より何事をか捉へんと待構へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'その時、無數の人あつまりて、群衆ふみ合ふばかりなり。イエスまづ弟子たちに言ひ出で給ふ『なんぢら、パリサイ人のパンだねに心せよ、これ僞善なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, '蔽はれたるものに露れぬはなく、隱れたるものに知られぬはなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'この故に汝らが暗きにて言ふことは、明るきにて聞え、部屋の内にて耳によりて語りしことは、屋の上にて宣べらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, '我が友たる汝らに告ぐ。身を殺して後に何をも爲し得ぬ者どもを懼るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, '懼るべきものを汝らに示さん。殺したる後ゲヘナに投げ入るる權威ある者を懼れよ。われ汝らに告ぐ、げに之を懼れよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, '五 羽の雀は二錢にて賣るにあらずや、然るに其の一 羽だに神の前に忘れらるる事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, '汝らの頭の髮までもみな數へらる。懼るな、汝らは多くの雀よりも優るるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'われ汝らに告ぐ、凡そ人の前に我を言ひあらはす者を、人の子もまた神の使たちの前にて言ひあらはさん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'されど人の前にて我を否む者は、神の使たちの前にて否まれん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, '凡そ言をもて人の子に逆ふ者は赦されん。されど聖 靈を瀆すものは赦されじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, '人なんぢらを會堂、或は司、あるひは權威ある者の前に引きゆかん時、いかに何を答へ、または何を言はんと思ひ煩ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, '聖 靈そのとき言ふべきことを教へ給はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, '群衆のうちの或 人いふ『師よ、わが兄弟に命じて、嗣業を我に分たしめ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, '之に言ひたまふ『人よ、誰が我を立てて汝らの裁判人また分配 者とせしぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'かくて人々に言ひたまふ『愼みて凡ての慳貪をふせげ、人の生命は所有の豐なるには因らぬなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'また譬を語りて言ひ給ふ『ある富める人、その畑 豐に實りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, '心の中に議りて言ふ「われ如何にせん、我が作物を藏めおく處なし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, '遂に言ふ「われ斯く爲さん、わが倉を毀ち、更に大なるものを建てて、其處にわが穀物および善き物をことごとく藏めん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'かくてわが靈魂に言はん、靈魂よ、多年を過すに足る多くの善き物を貯へたれば、安んぜよ、飮食せよ、樂しめよ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, '然るに神かれに「愚なる者よ、今宵なんぢの靈魂とらるべし、さらば汝の備へたる物は、誰がものとなるべきぞ」と言ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, '己のために財を貯へ、神に對して富まぬ者は斯くのごとし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'また弟子たちに言ひ給ふ『この故にわれ汝らに告ぐ、何を食はんと生命のことを思ひ煩ひ、何を著んと體のことを思ひ煩ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, '生命は糧にまさり、體は衣に勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, '鴉を思ひ見よ、播かず、刈らず、納屋も倉もなし。然るに神は之を養ひたまふ、汝ら鳥に優るること幾許ぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, '汝らの中たれか思ひ煩ひて、身の長 一尺を加へ得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'されば最 小き事すら能はぬに、何ぞ他のことを思ひ煩ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, '百合を思ひ見よ、紡がず、織らざるなり。されど我なんぢらに告ぐ、榮華を極めたるソロモンだに、其の服裝この花の一つにも及かざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, '今日ありて、明日 爐に投げ入れらるる野の草をも、神は斯く裝ひ給へば、況て汝らをや、ああ信仰うすき者よ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'なんぢら何を食ひ何を飮まんと求むな、また心を動かすな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, '是みな世の異邦人の切に求むる所なれど、汝らの父は、此 等の物のなんぢらに必要なるを知り給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'ただ父の御國を求めよ。さらば此 等の物は、なんぢらに加へらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, '懼るな、小き群よ、なんぢらに御國を賜ふことは、汝らの父の御意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, '汝らの所有を賣りて施濟をなせ。己がために舊びぬ財布をつくり、盡きぬ財寶を天に貯へよ。かしこは盜人も近づかず、蟲も壞らぬなり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, '汝らの財寶のある所には、汝らの心もあるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'なんぢら腰に帶し、燈火をともして居れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, '主人、婚筵より歸り來りて戸を叩かば、直ちに開くために待つ人のごとくなれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, '主人の來るとき、目を覺しをるを見らるる僕どもは幸福なるかな。われ誠に汝らに告ぐ、主人 帶して其の僕どもを食事の席に就かせ、進みて給仕すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, '主人、夜の半ごろ若くは夜の明くる頃に來るとも、かくの如くなるを見らるる僕どもは幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'なんぢら之を知れ、家主もし盜人いづれの時 來るかを知らば、その家を穿たすまじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, '汝らも備へをれ。人の子は思はぬ時に來ればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'ペテロ言ふ『主よ、この譬を言ひ給ふは我らにか、また凡ての人にか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, '主いひ給ふ『主人が時に及びて僕どもに定の糧を與へさする爲に、その僕どもの上に立つる忠實にして慧き支配人は誰なるか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, '主人のきたる時、かく爲し居るを見らるる僕は幸福なるかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'われ實をもて汝らに告ぐ、主人すべての所有を彼に掌どらすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, '若しその僕、心のうちに、主人の來るは遲しと思ひ、僕・婢女をたたき、飮食して醉ひ始めなば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'その僕の主人、おもはぬ日 知らぬ時に來りて、之を烈しく笞うち、その報を不 忠 者と同じうせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, '主人の意を知りながら用意せず、又その意に從はぬ僕は、笞うたるること多からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'されど知らずして打たるべき事をなす者は、笞うたるること少からん。多く與へらるる者は、多く求められん。多く人に托くれば、更に多くその人より請ひ求むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, '我は火を地に投ぜんとて來れり。此の火すでに燃えたらんには、我また何をか望まん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'されど我には受くべきバプテスマあり。その成し遂げらるるまでは、思ひ逼ること如何ばかりぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'われ地に平和を與へんために來ると思ふか。われ汝らに告ぐ、然らず、反つて分爭なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, '今よりのち一家に五 人あらば、三人は二人に、二人は三人に分れ爭はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, '父は子に、子は父に、母は娘に、娘は母に、姑姆は嫁に、嫁は姑姆に分れ爭はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'イエスまた群衆に言ひ給ふ『なんぢら雲の西より起るを見れば、直ちに言ふ「急雨きたらん」と、果して然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'また南 風ふけば、汝 等いふ「強き暑あらん」と、果して然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, '僞善者よ、汝ら天 地の氣色を辨ふることを知りて、今の時を辨ふること能はぬは何ぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'また何 故みづから正しき事を定めぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'なんぢ訴ふる者とともに司に往くとき、途にて和解せんことを力めよ。恐らくは訴ふる者なんぢを審判 人に引きゆき、審判 人なんぢを下役にわたし、下役なんぢを獄に投げ入れん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'われ汝に告ぐ、一レプタも殘りなく償はずば、其處に出づること能はじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'その折しも或 人々きたりて、ピラトがガリラヤ人らの血を彼らの犧牲にまじへたりし事をイエスに告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, '答へて言ひ給ふ『かのガリラヤ人は斯かることに遭ひたる故に、凡てのガリラヤ人に勝れる罪人なりしと思ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'われ汝らに告ぐ、然らず、汝らも悔改めずば皆おなじく亡ぶべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, '又シロアムの櫓たふれて、壓し殺されし十 八人は、エルサレムに住める凡ての人に勝りて、罪の負債ある者なりしと思ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'われ汝らに告ぐ、然らず、汝らも悔改めずば、みな斯くのごとく亡ぶべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, '又この譬を語りたまふ『或 人おのが葡萄園に植ゑありし無花果の樹に來りて、果を求むれども得ずして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, '園丁に言ふ「視よ、われ三年きたりて此の無花果の樹に果を求むれども得ず。これを伐り倒せ、何ぞ徒らに地を塞ぐか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, '答へて言ふ「主よ、今年も容したまへ、我その周圍を掘りて肥料せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'そののち果を結ばば善し、もし結ばずば伐り倒したまへ」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'イエス安息 日に或 會堂にて教えたまふ時、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, '視よ、十 八 年のあひだ病の靈に憑かれたる女あり、屈まりて少しも伸ぶること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'イエスこの女を見、呼び寄せて『女よ、なんぢは病より解かれたり』と言ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, '之に手を按きたまへば、立刻に身を直にして神を崇めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, '會堂 司イエスの安息 日に病を醫し給ひしことを憤ほり、答へて群衆に言ふ『働くべき日は六日あり、その間に來りて醫されよ。安息 日には爲ざれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, '主こたへて言ひたまふ『僞善者らよ、汝 等おのおの安息 日には、己が牛または驢馬を小屋より解きいだし、水 飼はんとて牽き往かぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'さらば長き十 八 年の間サタンに縛られたるアブラハムの娘なる此の女は、安息 日にその繋より解かるべきならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'イエス此 等のことを言ひ給へば、逆ふ者はみな恥ぢ、群衆は擧りてその爲し給へる榮光ある凡ての業を喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'かくてイエス言ひたまふ『神の國は何に似たるか、我これを何に擬へん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, '一粒の芥種のごとし。人これを取りて己の園に播きたれば、育ちて樹となり、空の鳥その枝に宿れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'また言ひたまふ『神の國を何に擬へんか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'パン種のごとし。女これを取りて、三 斗の粉の中に入るれば、ことごとく脹れいだすなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'イエス教へつつ町々 村々を過ぎて、エルサレムに旅し給ふとき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, '或 人いふ『主よ、救はるる者は少きか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'イエス人々に言ひたまふ『力を盡して狭き門より入れ。我なんぢらに告ぐ、入らん事を求めて入り能はぬ者おほからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, '家主おきて門を閉ぢたる後、なんぢら外に立ちて「主よ、我らに開き給へ」と言ひつつ門を叩き始めんに、主人こたへて「われ汝らが何處の者なるかを知らず」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'その時「われらは御前にて飮食し、なんぢは、我らの町の大路にて教へ給へり」と言ひ出でんに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, '主人こたへて「われ汝らが何處の者なるかを知らず、惡をなす者どもよ、皆われを離れ去れ」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, '汝らアブラハム、イサク、ヤコブ及び凡ての預言者の、神の國に居り、己らの逐ひ出さるるを見ば、其處にて哀哭・切齒する事あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'また人々、東より西より南より北より來りて、神の國の宴に就くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, '視よ、後なる者の先になり、先なる者の後になる事あらん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'そのとき或パリサイ人らイエスに來りて言ふ『いでて此處を去り給へ、ヘロデ汝を殺さんとす』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, '答へて言ひ給ふ『往きてかの狐に言へ。視よ、われ今日 明日、惡鬼を逐ひ出し、病を醫し、而して三日めに全うせられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'されど今日も明日も次の日も我は進み往くべし。それ預言者のエルサレムの外にて死ぬることは有るまじきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, '噫エルサレム、エルサレム、預言者たちを殺し、遣されたる人々を石にて撃つ者よ、牝鷄の己が雛を翼のうちに集むるごとく、我なんぢの子どもを集めんとせしこと幾度ぞや。されど汝らは好まざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, '視よ、汝らの家は棄てられて汝らに遺らん。我なんぢらに告ぐ、「讃むべきかな、主の名によりて來る者」と、汝らの言ふ時の至るまでは、我を見ざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'イエス安息 日に食事せんとて、或パリサイ人の頭の家に入り給へば、人々これを窺ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, '視よ、御前に水腫をわづらふ人ゐたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'イエス答へて教法師とパリサイ人とに言ひたまふ『安息 日に人を醫すことは善しや、否や』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'かれら默然たり。イエスその人を執り、醫して去らしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, '且かれらに言ひ給ふ『なんぢらの中その子あるひは其の牛、井に陷らんに、安息 日には直ちに之を引揚げぬ者あるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, '彼 等これに對して物 言ふこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'イエス招かれたる者の上席をえらぶを見、譬をかたりて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '『なんぢ婚筵に招かるるとき、上席に著くな。恐らくは汝よりも貴き人の招かれんに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, '汝と彼とを招きたる者きたりて「この人に席を讓れ」と言はん。さらば其の時なんぢ恥ぢて末席に往きはじめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, '招かるるとき、寧ろ往きて末席に著け、さらば招きたる者きたりて「友よ、上に進め」と言はん。その時なんぢ同席の者の前に譽あるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, '凡そおのれを高うする者は卑うせられ、己を卑うする者は高うせらるるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'また己を招きたる者にも言ひ給ふ『なんぢ晝餐または夕餐を設くるとき、朋友・兄弟・親族・富める隣 人などをよぶな。恐らくは彼らも亦なんぢを招きて報をなさん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, '饗宴を設くる時は、寧ろ貧しき者・不具・跛者・盲人などを招け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, '彼らは報ゆること能はぬ故に、なんぢ幸福なるべし。正しき者の復活の時に報いらるるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, '同席の者の一人これらの事を聞きてイエスに言ふ『おほよそ神の國にて食事する者は幸福なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, '之に言ひたまふ『或 人、盛なる夕餐を設けて、多くの人を招く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, '夕餐の時いたりて、招きおきたる者の許に僕を遣して「來れ、既に備りたり」と言はしめたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, '皆ひとしく辭りはじむ。初の者いふ「われ田地を買へり。往きて見ざるを得ず。請ふ、許されんことを」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, '他の者いふ「われ五 耜の牛を買へり、之を驗すために往くなり。請ふ、許されんことを」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'また他も者いふ「われ妻を娶れり、此の故に往くこと能はず」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, '僕かへりて此 等の事をその主人に告ぐ、家主いかりて僕に言ふ「とく町の大路と小路とに往きて、貧しき者・不具 者・盲人・跛者などを此處に連れきたれ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, '僕いふ「主よ、仰のごとく爲したれど、尚ほ餘の席あり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, '主人、僕に言ふ「道や籬の邊にゆき、人々を強ひて連れきたり、我が家に充たしめよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'われ汝らに告ぐ、かの招きおきたる者のうち、一人だに我が夕餐を味ひ得る者なし」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'さて大なる群衆イエスに伴ひゆきたれば、顧みて之に言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '『人もし我に來りて、その父 母・妻 子・兄弟・姉妹・己が生命までも憎まずば、我が弟子となるを得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'また己が十字架を負ひて我に從ふ者ならでは、我が弟子となるを得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, '汝らの中たれか櫓を築かんと思はば、先づ坐して其の費をかぞへ、己が所有、竣工までに足るか否かを計らざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, '然らずして基を据ゑ、もし成就すること能はずば、見る者みな嘲笑ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, '「この人は築きかけて成就すること能はざりき」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, '又いづれの王か出でて他の王と戰爭をせんに、先づ坐して、此の一萬 人をもて、かの二萬 人を率ゐきたる者に對ひ得るか否か籌らざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'もし及かずば、敵なほ遠く隔るうちに、使を遣して和睦を請ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'かくのごとく、汝らの中その一切の所有を退くる者ならでは、我が弟子となるを得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, '鹽は善きものなり、然れど鹽もし效力を失はば、何によりてか味つけられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, '土にも肥料にも適せず、外に棄てらるるなり。聽く耳ある者は聽くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, '取税人、罪人ども、みな御言を聽かんとて近寄りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'パリサイ人・學者ら呟きて言ふ、『この人は罪人を迎へて食を共にす』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'イエス之に譬を語りて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '『なんぢらの中たれか百匹の羊を有たんに、若その一匹を失はば、九 十 九 匹を野におき、往きて失せたる者を見 出すまでは尋ねざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, '遂に見出さば、喜びて之を己が肩にかけ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, '家に歸りて其の友と隣 人とを呼び集めて言はん「我とともに喜べ、失せたる我が羊を見出せり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'われ汝らに告ぐ、かくのごとく悔改むる一人の罪人のためには、悔改の必要なき九 十 九 人の正しき者にも勝りて、天に歡喜あるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, '又いづれの女か銀貨 十 枚を有たんに、若しその一 枚を失はば、燈火をともし、家を掃きて見 出すまでは懇ろに尋ねざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, '遂に見出さば、其の友と隣 人とを呼び集めて言はん、「我とともに喜べ、わが失ひたる銀貨を見出せり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'われ汝らに告ぐ、かくのごとく悔改むる一人の罪人のために、神の使たちの前に歡喜あるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'また言ひたまふ『或 人に二人の息子あり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, '弟、父に言ふ「父よ、財産のうち我が受くべき分を我にあたへよ」父その身代を二人に分けあたふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, '幾日も經ぬに、弟おのが物をことごとく集めて、遠國にゆき、其處にて放蕩にその財産を散せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'ことごとく費したる後、その國に大なる饑饉おこり、自ら乏しくなり始めたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, '往きて其の地の或 人に依附りしに、其の人かれを畑に遣して豚を飼はしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'かれ豚の食ふ蝗 豆にて、己が腹を充さんと思ふ程なれど、何をも與ふる人なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, '此のとき我に反りて言ふ『わが父の許には食物あまれる雇人いくばくぞや、然るに我は飢ゑてこの處に死なんとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, '起ちて我が父にゆき「父よ、われは天に對し、また汝の前に罪を犯したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, '今より汝の子と稱へらるるに相應しからず、雇人の一人のごとく爲し給へ』と言はん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, '乃ち起ちて其の父のもとに往く。なほ遠く隔りたるに、父これを見て憫み、走りゆき、其の頸を抱きて接吻せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, '子、父にいふ「父よ、我は天に對し又なんぢの前に罪を犯したり。今より汝の子と稱へらるるに相應しからず」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'されど父、僕どもに言ふ「とくとく最上の衣を持ち來りて之に著せ、その手に指輪をはめ、其の足に鞋をはかせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'また肥えたる犢を牽ききたりて屠れ、我ら食して樂しまん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'この我が子、死にて復 生き、失せて復 得られたり」かくて彼ら樂しみ始む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, '然るに其の兄、畑にありしが、歸りて家に近づきたるとき、音樂と舞踏との音を聞き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, '僕の一人を呼びてその何事なるかを問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, '答へて言ふ「なんぢの兄弟 歸りたり、その恙なきを迎へたれば、汝の父 肥えたる犢を屠れるなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, '兄 怒りて内に入ることを好まざりしかば、父いでて勸めしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, '答へて父に言ふ「視よ、我は幾歳もなんぢに仕へて、未だ汝の命令に背きし事なきに、我には小 山羊 一匹だに與へて友と樂しましめし事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, '然るに遊女らと共に、汝の身代を食ひ盡したる此の汝の子 歸り來れば、之がために肥えたる犢を屠れり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, '父いふ「子よ、なんぢは常に我とともに在り、わが物は皆なんぢの物なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'されど此の汝の兄弟は死にて復 生き、失せて復 得られたれば、我らの樂しみ喜ぶは當然なり」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'イエスまた弟子たちに言ひ給ふ『或 富める人に一人の支配人あり、主人の所有を費しをりと訴へられたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, '主人かれを呼びて言ふ「わが汝につきて聞く所は、これ何事ぞ、務の報告をいだせ、汝こののち支配人たるを得じ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, '支配人 心のうちに言ふ「如何にせん、主人わが職を奪ふ。われ土 掘るには力なく、物 乞ふは恥かし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, '我なすべき事こそ知りたれ、斯く爲ば職を罷めらるるとき、人々その家に我を迎ふるならん」とて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, '主人の負債者を一人 一人 呼びよせて、初の者に言ふ「なんぢ我が主人より負ふところ何 程あるか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, '答へて言ふ「油、百 樽」支配人いふ「なんぢの證書をとり、早く坐して五 十と書け」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, '又ほかの者に言ふ「負ふところ何 程あるか」答へて言ふ「麥、百 石」支配人いふ「なんぢの證書をとりて八 十と書け」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'ここに主人、不義なる支配人の爲しし事の巧なるによりて、彼を譽めたり。この世の子らは、己が時代の事には光の子らよりも巧なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'われ汝らに告ぐ、不義の富をもて、己がために友をつくれ。さらば富の失する時、その友なんぢらを永遠の住居に迎へん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, '小事に忠なる者は大事にも忠なり。小事に不 忠なる者は大事にも不 忠なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'さらば汝 等もし不義の富に忠ならずば、誰か眞の富を汝らに任すべき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'また汝 等もし人のものに忠ならずば、誰か汝 等のものを汝らに與ふべき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, '僕は二人の主に兼ね事ふること能はず、或は之を憎み彼を愛し、或は之に親しみ彼を輕しむべければなり。汝ら神と富とに兼ね事ふること能はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'ここに慾 深きパリサイ人ら、この凡ての事を聞きてイエスを嘲笑ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'イエス彼らに言ひ給ふ『なんぢらは人のまへに己を義とする者なり。されど神は汝らの心を知りたまふ。人のなかに尊ばるる者は、神のまへに憎まるる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, '律法と預言者とはヨハネまでなり、その時より神の國は宣傳へられ、人みな烈しく攻めて之に入る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'されど律法の一畫の落つるよりも、天 地の過ぎ往くは易し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, '凡てその妻を出して、他に娶る者は、姦淫を行ふなり。また夫より出されたる女を娶る者も、姦淫を行ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, '或 富める人あり、紫色の衣と細布とを著て、日々 奢り樂しめり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, '又ラザロといふ貧しき者あり、腫物にて腫れただれ、富める人の門に置かれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'その食卓より落つる物にて飽かんと思ふ。而して犬ども來りて其の腫物を舐れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, '遂にこの貧しきもの死に、御使たちに携へられてアブラハムの懷裏に入れり。富める人もまた死にて葬られしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, '黄泉にて苦惱の中より目を擧げて、遙にアブラハムと其の懷裏にをるラザロとを見る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, '乃ち呼びて言ふ「父アブラハムよ、我を憐みて、ラザロを遣し、その指の先を水に浸して我が舌を冷させ給へ、我はこの焔のなかに悶ゆるなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'アブラハム言ふ「子よ、憶へ、なんぢは生ける間なんぢの善き物を受け、ラザロは惡しき物を受けたり。今ここにて彼は慰められ、汝は悶ゆるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, '然のみならず、此處より汝らに渡り往かんとすとも得ず、其處より我らに來り得ぬために、我らと汝らとの間に大なる淵 定めおかれたり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, '富める人また言ふ「さらば父よ、願はくは我が父の家にラザロを遣したまへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, '我に五 人の兄弟あり、この苦痛のところに來らぬよう、彼らに證せしめ給へ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'アブラハム言ふ「彼らにはモーセと預言者とあり、之に聽くべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, '富める人いふ「いな、父アブラハムよ、もし死人の中より彼らに往く者あらば、悔改めん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'アブラハム言ふ「もしモーセと預言者とに聽かずば、たとひ死人の中より甦へる者ありとも、其の勸を納れざるべし」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'イエス弟子たちに言ひ給ふ『躓物は必ず來らざるを得ず、されど之を來らす者は禍害なるかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'この小き者の一人を躓かするよりは、寧ろ碾臼の石を頸に懸けられて、海に投げ入れられんかた善きなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, '汝 等みづから心せよ。もし汝の兄弟 罪を犯さば、これを戒めよ。もし悔改めなば之をゆるせ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'もし一日に七度なんぢに罪を犯し、七たび「悔改む」と言ひて、汝に歸らば之をゆるせ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, '使徒たち主に言ふ『われらの信仰を増したまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, '主いひ給ふ『もし芥種 一粒ほどの信仰あらば、此の桑の樹に「拔けて海に植れ」と言ふとも汝らに從ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, '汝 等のうち誰か或は耕し、或は牧する僕を有たんに、その僕 畑より歸りたる時、これに對ひて「直ちに來り食に就け」と言ふ者あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, '反つて「わが夕餐の備をなし、我が飮食するあひだ、帶して給仕せよ、然る後に、なんぢ飮食すべし」と言ふにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, '僕、命ぜられし事を爲したればとて、主人これに謝すべきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'かくのごとく汝らも命ぜられし事をことごとく爲したる時「われらは無 益なる僕なり、爲すべき事を爲したるのみ」と言へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'イエス、エルサレムに往かんとて、サマリヤとガリラヤとの間をとほり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, '或 村に入り給ふとき、十 人の癩病人これに遇ひて、遙に立ち止り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, '聲を揚げて言ふ『君イエスよ、我らを憫みたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'イエス之を見て言ひたまふ『なんぢら往きて身を祭司らに見せよ』彼ら往く間に潔められたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'その中の一人、おのが醫されたるを見て、大聲に神を崇めつつ歸りきたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'イエスの足下に平伏して謝す。これはサマリヤ人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'イエス答へて言ひたまふ『十 人みな潔められしならずや、九 人は何處に在るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'この他國人のほかは、神に榮光を歸せんとて歸りきたる者なきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'かくて之に言ひたまふ『起ちて往け、なんぢの信仰なんぢを救へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, '神の國の何時きたるべきかをパリサイ人に問はれし時、イエス答へて言ひたまふ『神の國は見ゆべき状にて來らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'また「視よ、此處に在り」「彼處に在り」と人々 言はざるべし。視よ、神の國は汝らの中に在るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'かくて弟子たちに言ひ給ふ『なんぢら人の子の日の一日を見んと思ふ日きたらん、されど見ることを得じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'そのとき人々なんぢらに「見よ彼處に、見よ此處に」と言はん、されど往くな、從ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'それ電光の天の彼方より閃きて、天の此方に輝くごとく、人の子もその日には然あるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'されど人の子は先づ多くの苦難を受け、かつ今の代に棄てらるべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'ノアの日にありし如く、人の子の日にも然あるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'ノア方舟に入る日までは、人々 飮み食ひ娶り嫁ぎなど爲たりしが、洪水きたりて彼 等をことごとく滅せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'ロトの日にも斯くのごとく、人々 飮み食ひ、賣り買ひ、植ゑつけ、家 造りなど爲たりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'ロトのソドムを出でし日に、天より火と硫黄と降りて、彼 等をことごとく滅せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, '人の子の顯るる日にも、その如くなるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'その日には、人もし屋の上にをりて、器 物 家の内にあらば、之を取らんとて下るな。畑にをる者も同じく歸るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'ロトの妻を憶へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'おほよそ己が生命を全うせんとする者はこれを失ひ、失ふ者はこれを保つべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'われ汝らに告ぐ、その夜ふたりの男、一つ寢臺に居らんに、一人は取られ一人は遣されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, '二人の女ともに臼ひき居らんに、一人は取られ一人は遣されん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, '弟子たち答へて言ふ『主よ、それは何處ぞ』イエス言ひたまふ『屍體のある處には鷲も亦あつまらん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'また彼らに、落膽せずして常に祈るべきことを、譬にて語り言ひ給ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, '『或 町に、神を畏れず人を顧みぬ裁判人あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'その町に寡婦ありて、屡次その許にゆき「我がために仇を審きたまへ」と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'かれ久しく聽き入れざりしが、其ののち心の中に言ふ「われ神を畏れず、人を顧みねど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, '此の寡婦われを煩はせば、我かれが爲に審かん、然らずば絶えず來りて我を惱さん」と』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, '主いひ給ふ『不義なる裁判人の言ふことを聽け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'まして神は夜晝よばはる選民のために、たとひ遲くとも遂に審き給はざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, '我なんぢらに告ぐ、速かに審き給はん。されど人の子の來るとき地上に信仰を見んや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'また己を義と信じ、他人を輕しむる者どもに、此の譬を言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '『二人のもの祈らんとて宮にのぼる、一人はパリサイ人、一人は取税人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'パリサイ人たちて心の中に斯く祈る「神よ、我はほかの人の、強奪・不義・姦淫するが如き者ならず、又この取税人の如くならぬを感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, '我は一週のうちに二度 斷食し、凡て得るものの十分の一を献ぐ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, '然るに取税人は遙に立ちて、目を天に向くる事だにせず、胸を打ちて言ふ「神よ、罪人なる我を憫みたまへ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'われ汝らに告ぐ、この人は、かの人よりも義とせられて、己が家に下り往けり。おほよそ己を高うする者は卑うせられ、己を卑うする者は高うせらるるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'イエスの觸り給はんことを望みて、人々 嬰兒らを連れ來りしに、弟子たち之を見て禁めたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'イエス幼兒らを呼びよせて言ひたまふ『幼兒らの我に來るを許して止むな、神の國はかくのごとき者の國なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'われ誠に汝らに告ぐ、おほよそ幼兒のごとくに神の國をうくる者ならずば、之に入ることは能はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, '或 司 問ひて言ふ『善き師よ、われ何をなして永遠の生命を嗣ぐべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'イエス言ひ給ふ『なにゆゑ我を善しと言ふか、神ひとりの他に善き者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, '誡命はなんぢが知る所なり「姦淫するなかれ」「殺すなかれ」「盜むなかれ」「僞證を立つる勿れ」「なんぢの父と母とを敬へ」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, '彼いふ『われ幼き時より皆これを守れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'イエス之をききて言ひたまふ『なんぢなほ足らぬこと一つあり、汝の有てる物をことごとく賣りて、貧しき者に分ち與へよ、然らば財寶を天に得ん。かつ來りて我に從へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, '彼は之をききて甚く悲しめり、大に富める者なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'イエス之を見て言ひたまふ『富める者の神の國に入るは如何に難いかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, '富める者の神の國に入るよりは、駱駝の針の穴をとほるは反つて易し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, '之をきく人々いふ『さらば誰か救はるる事を得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'イエス言ひたまふ『人のなし得ぬところは、神のなし得る所なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'ペテロ言ふ『視よ、我等わが物をすてて汝に從へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'イエス言ひ給ふ『われ誠に汝らに告ぐ、神の國のために、或は家、或は妻、或は兄弟、あるひは兩親、あるひは子を棄つる者は、誰にても、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, '今の時に數倍を受け、また後の世にて永遠の生命を受けぬはなし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'イエス十二 弟子を近づけて言ひたまふ『視よ、我らエルサレムに上る。人の子につき預言者たちによりて録されたる凡ての事は、成し遂げらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, '人の子は異邦人に付され、嘲弄せられ、辱しめられ、唾せられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, '彼 等これを鞭うち、かつ殺さん。かくて彼は三日めに甦へるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, '弟子たち此 等のことを一つだに悟らず、此の言かれらに隱れたれば、その言ひ給ひしことを知らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'イエス、エリコに近づき給ふとき、一人の盲人、路の傍らに坐して、物 乞ひ居たりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, '群衆の過ぐるを聞きて、その何事なるかを問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, '人々ナザレのイエスの過ぎたまふ由を告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, '盲人よばはりて言ふ『ダビデの子イエスよ、我を憫みたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, '先だち往く者ども、彼を禁めて默さしめんと爲たれど、増々さけびて言ふ『ダビデの子よ、我を憫みたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'イエス立ち止り、盲人を連れ來るべきことを命じ給ふ。かれ近づきたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'イエス問ひ給ふ『わが汝に何を爲さんことを望むか』彼いふ『主よ、見えんことなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'イエス彼に『見ることを得よ、なんぢの信仰なんぢを救へり』と言ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, '立刻に見ることを得、神を崇めてイエスに從ふ。民みな之を見て神を讃美せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'エリコに入りて過ぎゆき給ふとき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, '視よ、名をザアカイといふ人あり、取税人の長にて富める者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'イエスの如何なる人なるかを見んと思へど、丈 矮うして群衆のために見ること能はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, '前に走りゆき、桑の樹にのぼる。イエスその路を過ぎんとし給ふ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'イエス此處に至りしとき、仰ぎ見て言ひたまふ『ザアカイ、急ぎおりよ、今日われ汝の家に宿るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'ザアカイ急ぎおり、喜びてイエスを迎ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, '人々みな之を見て呟きて言ふ『かれは罪人の家に入りて客となれり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'ザアカイ立ちて主に言ふ『主、視よ、わが所有の半を貧しき者に施さん、若しわれ誣ひ訴へて人より取りたる所あらば、四 倍にして償はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'イエス言ひ給ふ『けふ救はこの家に來れり、此の人もアブラハムの子なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'それ人の子の來れるは、失せたる者を尋ねて救はん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, '人々これらの事を聽きゐたるとき、譬を加へて言ひ給ふ。これはイエス、エルサレムに近づき給ひ、神の國たちどころに現るべしと彼らが思ふ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, '乃ち言ひたまふ『或 貴人、王の權を受けて歸らんとて遠き國へ往くとき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, '十 人の僕をよび、之に金 十ミナを付して言ふ「わが歸るまで商賣せよ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, '然るに其の地の民かれを憎み、後より使を遣して「我らは此の人の我らの王となることを欲せず」と言はしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, '貴人、王の權をうけて歸り來りしとき、銀を付し置きたる僕どもの、如何に商賣せしかを知らんとて彼らを呼ばしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, '初のもの進み出でて言ふ「主よ、なんぢの一ミナは十ミナを贏けたり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, '王いふ「善いかな、良き僕、なんぢは小事に忠なりしゆゑ、十の町を司どるべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, '次の者きたりて言ふ「主よ、なんぢの一ミナは五ミナを贏けたり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, '王また言ふ「なんぢも五つの町を司どるべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'また一人きたりて言ふ「主、視よ、なんぢの一ミナは此處に在り。我これを袱紗に包みて藏め置きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'これ汝の嚴しき人なるを懼れたるに因る。なんぢは置かぬものを取り、播かぬものを刈るなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, '王いふ「惡しき僕、われ汝の口によりて汝を審かん。我の嚴しき人にて、置かぬものを取り、播かぬものを刈るを知るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, '何ぞわが金を銀行に預けざりし、さらば我きたりて元金と利子とを請求せしものを」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'かくて傍らに立つ者どもに言ふ「かれの一ミナを取りて十ミナを有てる人に付せ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '彼 等いふ「主よ、かれは既に十ミナを有てり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '「われ汝らに告ぐ、凡て有てる人はなほ與へられ、有たぬ人は有てるものをも取らるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, '而して我が王たる事を欲せぬ、かの仇どもを此處に連れきたり、我が前にて殺せ」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'イエス此 等のことを言ひてのち、先だち進みてエルサレムに上り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'オリブといふ山の麓なるベテパゲ及びベタニヤに近づきし時、イエス二人の弟子を遣さんとして言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, '『向の山にゆけ、其處に入らば、一度も人の乘りたる事なき驢馬の子の繋ぎあるを見ん、それを解きて牽ききたれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, '誰かもし汝らに「なにゆゑ解くか」と問はば、斯く言ふべし「主の用なり」と』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, '遣されたる者ゆきたれば、果して言ひ給ひし如くなるを見る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'かれら驢馬の子をとく時、その持主ども言ふ『なにゆゑ驢馬の子を解くか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, '答へて言ふ『主の用なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'かくて驢馬の子をイエスの許に牽ききたり、己が衣をその上にかけて、イエスを乘せたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'その往き給ふとき、人々おのが衣を途に敷く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'オリブ山の下りあたりまで近づき來り給へば、群れゐる弟子たち皆 喜びて、その見しところの能力ある御業につき、聲 高らかに神を讃美して言ひ始む、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, '『讃むべきかな、主の名によりて來る王。天には平和、至高き處には榮光あれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, '群衆のうちの或パリサイ人ら、イエスに言ふ『師よ、なんぢの弟子たちを禁めよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, '答へて言ひ給ふ『われ汝らに告ぐ、此のともがら默さば、石 叫ぶべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, '既に近づきたるとき、都を見やり、之がために泣きて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, '『ああ汝、なんぢも若しこの日の間に、平和にかかはる事を知りたらんには――されど今なんぢの目に隱れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, '日きたりて敵なんぢの周圍に壘をきづき、汝を取圍みて四方より攻め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, '汝とその内にある子らとを地に打倒し、一つの石をも石の上に遺さざるべし。なんぢ眷顧の時を知らざりしに因る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'かくて宮に入り、商ひする者どもを逐ひ出しはじめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, '之に言ひたまふ『「わが家は祈の家たるべし」と録されたるに、汝らは之を強盜の巣となせり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'イエス日々 宮にて教へたまふ。祭司長・學者ら及び民の重立ちたる者ども、之を殺さんと思ひたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, '民みな耳を傾けてイエスに聽きたれば、爲すべき方を知らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, '或 日イエス宮にて民を教へ、福音を宣べゐ給ふとき、祭司長・學者らは、長老どもと共に近づき來り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'イエスに語りて言ふ『なにの權威をもて此 等の事をなすか、此の權威を授けし者は誰か、我らに告げよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, '答へて言ひ給ふ『われも一言なんぢらに問はん、答へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'ヨハネのバプテスマは天よりか、人よりか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, '彼ら互に論じて言ふ『もし「天より」と言はば「なに故かれを信ぜざりし」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'もし「人より」と言はんか、民みなヨハネを預言者と信ずるによりて、我らを石にて撃たん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, '遂に何處よりか知らぬ由を答ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'イエス言ひたまふ『われも何の權威をもて此 等の事をなすか、汝らに告げじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'かくて次の譬を民に語りいで給ふ『ある人、葡萄園を造りて農夫どもに貸し、遠く旅立して久しくなりぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, '時 至りて、葡萄園の所得を納めしめんとて、一人の僕を農夫の許に遣ししに、農夫ども之を打ちたたき、空手にて歸らしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, '又ほかの僕を遣ししに、之をも打ちたたき、辱しめ、空手にて歸らしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'なほ三度めの者を遣ししに、之をも傷つけて逐ひ出したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, '葡萄園の主いふ「われ何を爲さんか。我が愛しむ子を遣さん、或は之を敬ふなるべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, '農夫ども之を見て互に論じて言ふ「これは世嗣なり。いざ殺して其の嗣業を我らの物とせん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'かくてこれを葡萄園の外に逐ひ出して殺せり。さらば葡萄園の主かれらに何を爲さんか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, '來りてかの農夫どもを亡し、葡萄園を他の者どもに與ふべし』人々これを聽きて言ふ『然はあらざれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'イエス彼らに目を注めて言ひ給ふ『されば「造家者らの棄てる石は、これぞ隅の首石となれる」と録されたるは何ぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, '凡そその石の上に倒るる者は碎け、又その石、人の上に倒るれば、その人を微塵にせん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, '此のとき學者・祭司長ら、イエスに手をかけんと思ひたれど、民を恐れたり。この譬の己どもを指して言ひ給へるを悟りしに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'かくて彼ら機を窺ひ、イエスを司の支配と權威との下に付さんとて、その言を捉ふるために、義人の樣したる間諜どもを遣したれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, '其の者どもイエスに問ひて言ふ『師よ、我らは汝の正しく語り、かつ教へ、外貌を取らず、眞をもて神の道を教へ給ふを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'われら貢をカイザルに納むるは、善きか、惡しきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'イエスその惡巧を知りて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '『デナリを我に見せよ。これは誰の像、たれの號なるか』『カイザルのなり』と答ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'イエス言ひ給ふ『さらばカイザルの物はカイザルに、神の物は神に納めよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'かれら民の前にて其の言をとらへ得ず、且その答を怪しみて默したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'また復活なしと言張るサドカイ人の或 者ども、イエスに來り問ひて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, '『師よ、モーセは、人の兄弟もし妻あり子なくして死なば、其の兄弟かれの妻を娶りて、兄弟のために嗣子を擧ぐべしと、我らに書き遣したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'さて茲に七人の兄弟ありて、兄、妻を娶り、子なくして死に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, '第二、第三の者も之を娶り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, '七人みな同じく子を殘さずして死に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, '後には其の女も死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'されば復活の時、この女は誰の妻たるべきか、七人これを妻としたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'イエス言ひ給ふ『この世の子らは娶り嫁ぎすれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'かの世に入るに、死人の中より甦へるに相應しとせらるる者は、娶り嫁ぎすることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, '彼 等ははや死ぬること能はざればなり。御使たちに等しく、また復活の子どもにして、神の子供たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, '死にたる者の甦へる事は、モーセも柴の條に、主を「アブラハムの神、イサクの神、ヤコブの神」と呼びて之を示せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, '神は死にたる者の神にあらず、生ける者の神なり。それ神の前には皆 生けるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, '學者のうちの或 者ども答へて『師よ、善く言ひ給へり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, '彼 等ははや何事をも問ひ得ざりし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'イエス彼らに言ひたまふ『如何なれば人々、キリストをダビデの子と言ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'ダビデ自ら詩 篇に言ふ「主わが主に言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'われ汝の敵を汝の足臺となすまでは、わが右に坐せよ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'ダビデ斯く彼を主と稱ふれば、爭でその子ならんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, '民の皆ききをる中にて、イエス弟子たちに言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '『學者らに心せよ。彼らは長き衣を著て歩むことを好み、市場にての敬禮、會堂の上座、饗宴の上席を喜び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'また寡婦らの家を呑み、外見をつくりて長き祈をなす。其の受くる審判は更に嚴しからん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'イエス目を擧げて、富める人々の納物を賽錢函に投げ入るるを見、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'また或 貧しき寡婦のレプタ二つを投げ入るるを見て言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, '『われ實をもて汝らに告ぐ、この貧しき寡婦は、凡ての人よりも多く投げ入れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, '彼らは皆その豐なる内より納物の中に投げ入れ、この寡婦はその乏しき中より、己が有てる生命の料をことごとく投げ入れたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, '或 人々、美麗なる石と献物とにて宮の飾られたる事を語りしに、イエス言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '『なんぢらが見る此 等の物は、一つの石も崩されずして石の上に殘らぬ日きたらん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, '彼ら問ひて言ふ『師よ、さらば此 等のことは何時あるか、又これらの事の成らんとする時は如何なる兆あるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'イエス言ひ給ふ『なんぢら惑されぬように心せよ、多くの者わが名を冒し來り「われは夫なり」と言ひ「時は近づけり」と言はん、彼らに從ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, '戰爭と騷亂との事を聞くとき、怖づな。斯かることは先づあるべきなり。然れど終は直ちに來らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'また言ひたまふ『「民は民に、國は國に逆ひて起たん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'かつ大なる地震あり、處々に疫病・饑饉あらん。懼るべき事と天よりの大なる兆とあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'すべて此 等のことに先だちて、人々なんぢらに手をくだし、汝らを責めん、即ち汝らを會堂および獄に付し、わが名のために王たち司たちの前に曳きゆかん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'これは汝らに證の機とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'されば汝ら如何に答へんと預じめ思慮るまじき事を心に定めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'われ汝らに、凡て逆ふ者の言ひ逆ひ言ひ消すことをなし得ざる、口と智慧とを與ふべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, '汝らは兩親・兄弟・親族・朋友にさへ付されん。又かれらは汝らの中の或 者を殺さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, '汝 等わが名の故に凡ての人に憎まるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, '然れど汝らの頭の髮 一すぢだに失せじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, '汝らは忍耐によりて其の靈魂を得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, '汝らエルサレムが軍勢に圍まるるを見ば、其の亡 近づけりと知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'その時ユダヤに居る者どもは山に遁れよ、都の中にをる者どもは出でよ、田舍にをる者どもは都に入るな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'これ録されたる凡ての事の遂げらるべき刑罰の日なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'その日には孕りたる者と、乳を哺まする者とは禍害なるかな。地に大なる艱難ありて、御怒この民に臨み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, '彼らは劍の刃に斃れ、又は捕はれて諸國に曳かれん。而してエルサレムは異邦人の時 滿つるまで、異邦人に蹂躙らるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'また日・月・星に兆あらん。地にては國々の民なやみ、海と濤との鳴り轟くによりて狼狽へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, '人々おそれ、かつ世界に來らんとする事を思ひて膽を失はん。これ天の萬象ふるひ動けばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, '其のとき人々、人の子の能力と大なる榮光とをもて、雲に乘りきたるを見ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'これらの事 起り始めなば、仰ぎて首を擧げよ。汝らの贖罪 近づけるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'また譬を言ひたまふ『無花果の樹また凡ての樹を見よ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, '既に芽ざせば、汝 等これを見てみづから夏の近きを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, '斯くのごとく此 等のことの起るを見ば、神の國の近きを知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'われ誠に汝らに告ぐ、これらの事ことごとく成るまで、今の代は過ぎゆくことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, '天 地は過ぎゆかん、されど我が言は過ぎゆくことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, '汝 等みづから心せよ、恐らくは飮食にふけり、世の煩勞にまとはれて心 鈍り、思ひがけぬ時、かの日 羂のごとく來らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'これは徧く地の面に住める凡ての人に臨むべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'この起るべき凡ての事をのがれ、人の子のまへに立ち得るやう、常に祈りつつ目を覺しをれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'イエス晝は宮にて教へ、夜は出でてオリブといふ山に宿りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, '民はみな御教を聽かんとて、朝とく宮にゆき、御許に集れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'さて過越といふ除酵祭 近づけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, '祭司長・學者らイエスを殺さんとし、その手段いかにと求む、民を懼れたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, '時にサタン、十二の一人なるイスカリオテと稱ふるユダに入る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'ユダ乃ち祭司長・宮守頭どもに往きて、イエスを如何にして付さんと議りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, '彼ら喜びて銀を與へんと約す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'ユダ諾ひて、群衆の居らぬ時にイエスを付さんと好き機をうかがふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, '過越の羔羊を屠るべき除酵祭の日 來りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'イエス、ペテロとヨハネとを遣さんとして言ひたまふ『往きて我らの食せん爲に過越の備をなせ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, '彼ら言ふ『何處に備ふることを望み給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'イエス言ひたまふ『視よ、都に入らば、水をいれたる瓶を持つ人なんぢらに遇ふべし、之に從ひゆき、その入る所の家にいりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, '家の主人に「師なんぢに言ふ、われ弟子らと共に過越の食をなすべき座敷は何處なるか」と言へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'さらば調へたる大なる二階 座敷を見すべし。其處に備へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'かれら出で往きて、イエスの言ひ給ひし如くなるを見て、過越の設備をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, '時いたりてイエス席に著きたまひ、使徒たちも共に著く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'かくて彼らに言ひ給ふ『われ苦難の前に、なんぢらと共にこの過越の食をなすことを望みに望みたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'われ汝らに告ぐ、神の國にて過越の成就するまでは、我 復これを食せざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'かくて酒杯を受け、かつ謝して言ひ給ふ『これを取りて互に分ち飮め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'われ汝らに告ぐ、神の國の來るまでは、われ今よりのち葡萄の果より成るものを飮まじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'またパンを取り謝してさき、弟子たちに與へて言ひ給ふ『これは汝らの爲に與ふる我が體なり。我が記念として之を行へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, '夕餐ののち酒杯をも然して言ひ給ふ『この酒杯は、汝らの爲に流す我が血によりて立つる新しき契約なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'されど視よ、我を賣る者の手、われと共に食卓の上にあり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, '實に人の子は定められたる如く逝くなり。されど之を賣る者は禍害なるかな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, '弟子たち己らの中にて此の事をなす者は、誰ならんと互に問ひ始む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'また彼らの間に、己らの中たれか大ならんとの爭論おこりたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'イエス言ひたまふ『異邦人の王はその民を宰どり、また民を支配する者は恩人と稱へらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'されど汝らは然あらざれ、汝 等のうち大なる者は若き者のごとく、頭たる者は事ふる者の如くなれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, '食事の席に著く者と事ふる者とは、何れか大なる。食事の席に著く者ならずや、されど我は汝らの中にて事ふる者のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, '汝らは我が嘗試のうちに絶えず我とともに居りし者なれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'わが父の我に任じ給へるごとく、我も亦なんぢらに國を任ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'これ汝らの我が國にて我が食卓に飮食し、かつ座位に坐してイスラエルの十二の族を審かん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'シモン、シモン、視よ、サタン汝らを麥のごとく篩はんとて請ひ得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'されど我なんぢの爲に、その信仰の失せぬやうに祈りたり、なんぢ立ち歸りてのち兄弟たちを堅うせよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'シモン言ふ『主よ、我は汝とともに獄にまでも、死にまでも往かんと覺悟せり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'イエス言ひ給ふ『ペテロよ、我なんぢに告ぐ、今日なんぢ三度われを知らずと否むまでは、鷄 鳴かざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'かくて弟子たちに言ひ給ふ『財布・嚢・鞋をも持たせずして汝らを遣ししとき、缺けたる所ありしや』彼ら言ふ『無かりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'イエス言ひ給ふ『されど今は財布ある者は之を取れ、嚢ある者も然すべし。また劍なき者は衣を賣りて劍を買へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'われ汝らに告ぐ「かれは愆人と共に數へられたり」と録されたるは、我が身に成し遂げらるべし。凡そ我に係る事は成し遂げらるればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, '弟子たち言ふ『主、見たまへ、茲に劍 二振あり』イエス言ひたまふ『足れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, '遂に出でて、常のごとくオリブ山に往き給へば、弟子たちも從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, '其處に至りて彼らに言ひたまふ『誘惑に入らぬやうに祈れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'かくて自らは石の投げらるる程かれらより隔り、跪づきて祈り言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, '『父よ、御旨ならば、此の酒杯を我より取り去りたまへ、されど我が意にあらずして御意の成らんことを願ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, '時に天より御使あらはれて、イエスに力を添ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'イエス悲しみ迫り、いよいよ切に祈り給へば、汗は地上に落つる血の雫の如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, '祈を了へ、起ちて弟子たちの許にきたり、その憂によりて眠れるを見て言ひたまふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, '『なんぞ眠るか、起て、誘惑に入らぬやうに祈れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'なほ語りゐ給ふとき、視よ、群衆あらはれ、十二の一人なるユダ先だち來り、イエスに接吻せんとて近寄りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'イエス言ひ給ふ『ユダ、なんぢは接吻をもて人の子を賣るか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, '御側に居る者ども事の及ばんとするを見て言ふ『主よ、われら劍をもて撃つべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'その中の一人、大 祭司の僕を撃ちて、右の耳を切り落せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'イエス答へて言ひたまふ『之にてゆるせ』而して僕の耳に手をつけて醫し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'かくて己に向ひて來れる祭司長・宮守頭・長老らに言ひ給ふ『なんぢら強盜に向ふごとく、劍と棒とを持ちて出できたるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, '我は日々なんぢらと共に宮に居りしに、我が上に手を伸べざりき。されど今は汝らの時、また暗黒の權威なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, '遂に人々イエスを捕へて、大 祭司の家に曳きゆく。ペテロ遠く離れて從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, '人々、中庭のうちに火を焚きて、諸共に坐したれば、ペテロもその中に坐す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, '或 婢女ペテロの火の光を受けて坐し居るを見、これに目を注ぎて言ふ『この人も彼と偕にゐたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'ペテロ肯はずして言ふ『をんなよ、我は彼を知らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, '暫くして他の者ペテロを見て言ふ『なんぢも彼の黨與なり』ペテロ言ふ『人よ、然らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, '一 時ばかりして又ほかの男、言張りて言ふ『まさしく此の人も彼とともに在りき、是ガリラヤ人なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'ペテロ言ふ『人よ、我なんぢの言ふことを知らず』なほ言ひ終へぬに、やがて鷄 鳴きぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, '主、振反りてペテロに目をとめ給ふ。ここにペテロ、主の『今日にはとり鳴く前に、なんぢ三度われを否まん』と言ひ給ひし御言を憶ひいだし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, '外に出でて甚く泣けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, '守る者どもイエスを嘲弄し、之を打ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'その目を蔽ひ問ひて言ふ『預言せよ、汝を撃ちし者は誰なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'この他なほ多くのことを言ひて譏れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, '夜明になりて、民の長老・祭司長・學者ら相 集り、イエスをその議會に曳き出して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, '『なんぢ若しキリストならば、我らに言へ』イエス言ひ給ふ『われ言ふとも汝ら信ぜじ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, '又われ問ふとも汝ら答へじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'されど人の子は今よりのち神の能力の右に坐せん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, '皆いふ『されば汝は神の子なるか』答へ給ふ『なんぢらの言ふごとく我はそれなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, '彼ら言ふ『何ぞなほ他に證據を求めんや。我ら自らその口より聞けり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, '民衆みな起ちて、イエスをピラトの前に曳きゆき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, '訴へ出でて言ふ『われら此の人が、わが國の民を惑し、貢をカイザルに納むるを禁じ、かつ自ら王なるキリストと稱ふるを認めたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'ピラト、イエスに問ひて言ふ『なんぢはユダヤ人の王なるか』答へて言ひ給ふ『なんぢの言ふが如し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'ピラト祭司長らと群衆とに言ふ『われ此の人に愆あるを見ず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, '彼 等ますます言ひ募り『かれはユダヤ全國に教をなして民を騷がし、ガリラヤより始めて、此處に至る』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'ピラト之を聞き、そのガリラヤ人なるかを問ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'ヘロデの權下の者なるを知り、ヘロデ此の頃エルサレムに居たれば、イエスをその許に送れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'ヘロデ、イエスを見て甚く喜ぶ。これは彼に就きて聞く所ありたれば、久しく逢はんことを欲し、何をか徴を行ふを見んと望み居たる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'かくて多くの言をもて問ひたれど、イエス何をも答へ給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, '祭司長・學者ら起ちて激甚くイエスを訴ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'ヘロデその兵卒と共にイエスを侮り、かつ嘲弄し、華美なる衣を著せて、ピラトに返す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'ヘロデとピラトと前には仇たりしが、此の日たがひに親しくなれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'ピラト、祭司長らと司らと民とを呼び集めて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, '『汝らこの人を民を惑す者として曳き來れり。視よ、われ汝らの前にて訊したれど、其の訴ふる所に就きて、この人に愆あるを見ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'ヘロデも亦 然り、彼を我らに返したり。視よ、彼は死に當るべき業を爲さざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'されば懲しめて之を赦さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, '民衆ともに叫びて言ふ『この人を除け、我らにバラバを赦せ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '此のバラバは、都に起りし一揆と殺人との故によりて、獄に入れられたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'ピラトはイエスを赦さんと欲して、再び彼らに告げたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, '彼ら叫びて『十字架につけよ、十字架につけよ』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'ピラト三度まで『彼は何の惡事を爲ししか、我その死に當るべき業を見ず、故に懲しめて赦さん』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'されど人々、大聲をあげ迫りて、十字架につけんことを求めたれば、遂にその聲 勝てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'ここにピラトその求の如くすべしと言渡し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'その求むるままに、かの一揆と殺人との故によりて獄に入れられたる者を赦し、イエスを付して彼らの心の隨ならしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, '人々イエスを曳きゆく時、シモンといふクレネ人の田舍より來るを執へ、十字架を負はせてイエスの後に從はしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, '民の大なる群と、歎き悲しめる女たちの群と之に從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'イエス振反りて女たちに言ひ給ふ『エルサレムの娘よ、わが爲に泣くな、ただ己がため、己が子のために泣け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, '視よ「石婦、兒 産まぬ腹、哺ませぬ乳は幸福なり」と言ふ日きたらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'その時ひとびと「山に向ひて我らの上に倒れよ、岡に向ひて我らを掩へ」と言ひ出でん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'もし青 樹に斯く爲さば、枯樹は如何にせられん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'また他に二人の惡人をも、死罪に行はんとてイエスと共に曳きゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, '髑髏といふ處に到りて、イエスを十字架につけ、また惡人の一人をその右、一人をその左に十字架につく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'かくてイエス言ひたまふ『父よ、彼らを赦し給へ、その爲す所を知らざればなり』彼らイエスの衣を分ちて鬮取にせり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, '民は立ちて見ゐたり。司たちも嘲りて言ふ『かれは他人を救へり、もし神の選び給ひしキリストならば、己をも救へかし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, '兵卒どもも嘲弄しつつ、近よりて酸き葡萄酒をさし出して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, '『なんぢ若しユダヤ人の王ならば、己を救へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, '又イエスの上には『これはユダヤ人の王なり』との罪標あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, '十字架に懸けられたる惡人の一人、イエスを譏りて言ふ『なんぢはキリストならずや、己と我らとを救へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, '他の者これに答へ禁めて言ふ『なんぢ同じく罪に定められながら、神を畏れぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, '我らは爲しし事の報を受くるなれば當然なり。されど此の人は何の不 善をも爲さざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'また言ふ『イエスよ、御國に入り給ふとき、我を憶えたまえ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'イエス言ひ給ふ『われ誠に汝に告ぐ、今日なんぢは我と偕にパラダイスに在るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, '晝の十二 時ごろ、日、光をうしなひ、地のうへ徧く暗くなりて、三時に及び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, '聖所の幕、眞中より裂けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'イエス大聲に呼はりて言ひたまふ『父よ、わが靈を御手にゆだぬ』斯く言ひて息 絶えたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, '百卒長この有りし事を見て、神を崇めて言ふ『實にこの人は義人なりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'これを見んとて集りたる群衆も、ありし事どもを見て、みな胸を打ちつつ歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, '凡てイエスの相識の者およびガリラヤより從ひ來れる女たちも、遙に立ちて此 等のことを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, '議員にして善かつ義なるヨセフといふ人あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '――この人はかの評議と仕業とに與せざりき――ユダヤの町なるアリマタヤの者にて、神の國を待ちのぞめり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, '此の人ピラトの許にゆき、イエスの屍體を乞ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'これを取りおろし、亞麻 布にて包み、巖に鑿りたる未だ人を葬りし事なき墓に納めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'この日は準備 日なり、かつ安息 日 近づきぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'ガリラヤよりイエスと共に來りし女たち後に從ひ、その墓と屍體の納められたる樣とを見、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, '歸りて香料と香 油とを備ふ。かくて誡命に遵ひて、安息 日を休みたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, '一週の初の日、朝まだき、女たち備へたる香料を携へて墓にゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, '然るに石の既に墓より轉し除けあるを見、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, '内に入りたるに、主イエスの屍體を見ず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'これが爲に狼狽へをりしに、視よ、輝ける衣を著たる二人の人その傍らに立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, '女たち懼れて面を地に伏せたれば、その二人の者いふ『なんぞ死にし者どもの中に生ける者を尋ぬるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, '彼は此處に在さず、甦へり給へり。尚ガリラヤに居給へるとき、如何に語り給ひしかを憶ひ出でよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, '即ち「人の子は必ず罪ある人の手に付され、十字架につけられ、かつ三日めに甦へるべし」と言ひ給へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'ここに彼らその御言を憶ひ出で、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, '墓より歸りて、凡て此 等のことを十 一 弟子および凡て他の弟子たちに告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'この女たちはマグダラのマリヤ、ヨハンナ及びヤコブの母マリヤなり、而して彼らと共に在りし他の女たちも、之を使徒たちに告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, '使徒たちは其の言を妄語と思ひて信ぜず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, '[ペテロは起ちて墓に走りゆき、屈みて布のみあるを見、ありし事を怪しみつつ歸れり]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, '視よ、この日 二人の弟子、エルサレムより三里ばかり隔りたるエマオといふ村に往きつつ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, '凡て有りし事どもを互に語りあふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, '語りかつ論じあふ程に、イエス自ら近づきて共に往き給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'されど彼らの目 遮へられて、イエスたるを認むること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'イエス彼らに言ひ給ふ『なんぢら歩みつつ互に語りあふ言は何ぞや』かれら悲しげなる状にて立ち止り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'その一人なるクレオパと名づくるもの答へて言ふ『なんぢエルサレムに寓り居て、獨り此の頃かしこに起りし事どもを知らぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'イエス言ひ給ふ『如何なる事ぞ』答へて言ふ『ナザレのイエスの事なり、彼は神と凡ての民との前にて、業にも言にも能力ある預言者なりしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, '祭司長ら及び我が司らは、死罪に定めんとて之を付し遂に十字架につけたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, '我らはイスラエルを贖ふべき者は、この人なりと望みゐたり、然のみならず、此の事の有りしより今日ははや三日めなるが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'なほ我等のうちの或 女たち、我らを驚かせり、即ち彼ら朝 夙く墓に往きたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, '屍體を見ずして歸り、かつ御使たち現れて、イエスは活き給ふと告げたりと言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, '我らの朋輩の數人もまた墓に往きて見れば、正しく女たちの言ひし如くにしてイエスを見ざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'イエス言ひ給ふ『ああ愚にして預言者たちの語りたる凡てのことを信ずるに心 鈍き者よ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'キリストは必ず此らの苦難を受けて、其の榮光に入るべきならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'かくてモーセ及び凡ての預言者をはじめ、己に就きて凡ての聖書に録したる所を説き示したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, '遂に往く所の村に近づきしに、イエスなほ進みゆく樣なれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, '強ひて止めて言ふ『我らと共に留れ、時 夕に及びて、日も早や暮れんとす』乃ち留らんとて入りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, '共に食事の席に著きたまふ時、パンを取りて祝し、擘きて與へ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, '彼らの目 開けてイエスなるを認む、而してイエス見えずなり給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'かれら互に言ふ『途にて我らと語り、我らに聖書を説明し給へるとき、我らの心、内に燃えしならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'かくて直ちに立ちエルサレムに歸りて見れば、十 一 弟子および之と偕なる者あつまり居て言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, '『主は實に甦へりて、シモンに現れ給へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, '二人の者もまた途にて有りし事と、パンを擘き給ふによりてイエスを認めし事とを述ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, '此 等のことを語る程に、イエスその中に立ち[『平安なんぢらに在れ』と言ひ]給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'かれら怖ぢ懼れて、見る所のものを靈ならんと思ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'イエス言ひ給ふ『なんぢら何ぞ心 騷ぐか、何ゆゑ心に疑惑おこるか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, '我が手わが足を見よ、これ我なり。我を撫でて見よ、靈には肉と骨となし、我にはあり、汝らの見るごとし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, '[斯く言ひて手と足とを示し給ふ]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'かれら歡喜の餘に信ぜずして怪しめる時、イエス言ひたまふ『此處に何か食物あるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'かれら炙りたる魚 一片を捧げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, '之を取り、その前にて食し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'また言ひ給ふ『これらの事は、我がなほ汝らと偕に在りし時に語りて、我に就きモーセの律法・預言者および詩 篇に録されたる凡ての事は、必ず遂げらるべしと言ひし所なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'ここに聖書を悟らしめんとて、彼らの心を開きて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, '『かく録されたり、キリストは苦難を受けて、三日めに死人の中より甦へり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, '且その名によりて罪の赦を得さする悔改は、エルサレムより始りて、もろもろの國人に宣傳へらるべしと。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, '汝らは此 等のことの證人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, '視よ、我は父の約し給へるものを汝らに贈る。汝ら上より能力を著せらるるまでは都に留れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, '遂にイエス彼らをベタニヤに連れゆき、手を擧げて之を祝したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, '祝する間に、彼らを離れ[天に擧げられ]給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, '彼ら[之を拜し]大なる歡喜をもてエルサレムに歸り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, '常に宮に在りて、神を讃めゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, '太初に言あり、言は神と偕にあり、言は神なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'この言は太初に神とともに在り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, '萬の物これに由りて成り、成りたる物に一つとして之によらで成りたるはなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, '之に生命あり、この生命は人の光なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, '光は暗黒に照る、而して暗黒は之を悟らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, '神より遣されたる人いでたり、その名をヨハネといふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'この人は證のために來れり、光に就きて證をなし、また凡ての人の彼によりて信ぜん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, '彼は光にあらず、光に就きて證せん爲に來れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'もろもろの人をてらす眞の光ありて、世にきたれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, '彼は世にあり、世は彼に由りて成りたるに、世は彼を知らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'かれは己の國にきたりしに、己の民は之を受けざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'されど之を受けし者、即ちその名を信ぜし者には、神の子となる權をあたへ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'かかる人は血脈によらず、肉の欲によらず、人の欲によらず、ただ、神によりて生れしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, '言は肉體となりて我らの中に宿りたまへり、我らその榮光を見たり、實に父の獨子の榮光にして、恩惠と眞理とにて滿てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'ヨハネ彼につきて證をなし、呼はりて言ふ『「わが後にきたる者は我に勝れり、我より前にありし故なり」と、我が曾ていへるは此の人なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, '我らは皆その充ち滿ちたる中より受けて、恩惠に恩惠を加へらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, '律法はモーセによりて與へられ、恩惠と眞理とはイエス・キリストによりて來れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, '未だ神を見し者なし、ただ父の懷裡にいます獨子の神のみ之を顯し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'さてユダヤ人、エルサレムより祭司とレビ人とをヨハネの許に遣して『なんぢは誰なるか』と問はせし時、ヨハネの證はかくのごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, '乃ち言ひあらはして諱まず『我はキリストにあらず』と言ひあらはせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'また問ふ『さらば何、エリヤなるか』答ふ『然らず』問ふ『かの預言者なるか』答ふ『いな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'ここに彼ら言ふ『なんぢは誰なるか、我らを遣しし人々に答へ得るやうにせよ、なんぢ己につきて何と言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, '答へて言ふ『我は預言者イザヤの云へるが如く「主の道を直くせよと、荒野に呼はる者の聲」なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'かの遣されたる者はパリサイ人なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'また問ひて言ふ『なんぢ若しキリストに非ず、またエリヤにも、かの預言者にも非ずば、何 故バプテスマを施すか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'ヨハネ答へて言ふ『我は水にてバプテスマを施す。なんじらの中に汝らの知らぬもの一人たてり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, '即ち我が後にきたる者なり、我はその鞋の紐を解くにも足らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'これらの事は、ヨハネのバプテスマを施しゐたりしヨルダンの向なるベタニヤにてありしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, '明くる日ヨハネ、イエスの己が許にきたり給ふを見ていふ『視よ、これぞ世の罪を除く神の羔羊。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'われ曾て「わが後に來る人あり、我にまされり、我より前にありし故なり」と云ひしは此の人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, '我もと彼を知らざりき。然れど彼のイスラエルに顯れんために、我きたりて水にてバプテスマを施すなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'ヨハネまた證をなして言ふ『われ見しに、御靈 鴿のごとく天より降りて、その上に止れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, '我もと彼を知らざりき。されど我を遣し水にてバプテスマを施させ給ふもの、我に告げて「なんぢ御靈くだりて或 人の上に止るを見ん、これぞ聖 靈にてバプテスマを施す者なる」といひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'われ之を見て、その神の子たるを證せしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, '明くる日ヨハネまた二人の弟子とともに立ちて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'イエスの歩み給ふを見ていふ『視よ、これぞ神の羔羊』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'かく語るをききて、二人の弟子イエスに從ひゆきたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'イエス振反りて、その從ひきたるを見て言ひたまふ『何を求むるか』彼 等いふ『ラビ(釋きていへば師)いづこに留り給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'イエス言ひ給ふ『きたれ、さらば見ん』彼ら往きてその留りたまふ所を見、この日ともに留れり、時は第十時ごろなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'ヨハネより聞きてイエスに從ひし二人のうち一人は、シモン・ペテロの兄弟アンデレなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'この人まづ其の兄弟シモンに遇ひ『われらメシヤ(釋けばキリスト)に遇へり』と言ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, '彼をイエスの許に連れきたれり。イエス之に目を注めて言ひ給ふ『なんぢはヨハネの子シモンなり、汝ケパ(釋けばペテロ)と稱へらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, '明くる日イエス、ガリラヤに往かんとし、ピリポにあひて言ひ給ふ『われに從へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'ピリポはアンデレとペテロとの町なるベツサイダの人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'ピリポ、ナタナエルに遇ひて言ふ『我らはモーセが律法に録ししところ、預言者たちが録しし所の者に遇へり、ヨセフの子ナザレのイエスなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'ナタナエル言ふ『ナザレより何の善き者か出づべき』ピリポいふ『來りて見よ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'イエス、ナタナエルの己が許にきたるを見、これを指して言ひたまふ『視よ、これ眞にイスラエル人なり、その衷に虚僞なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'ナタナエル言ふ『如何にして我を知り給ふか』イエス答えて言ひたまふ『ピリポの汝を呼ぶまへに、我なんぢが無花果の樹の下に居るを見たり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'ナタナエル答ふ『ラビ、なんぢは神の子なり、汝はイスラエルの王なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'イエス答へて言ひ給ふ『われ汝が無花果の樹の下にをるを見たりと言ひしに因りて信ずるか、汝これよりも更に大なる事を見ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'また言ひ給ふ『まことに誠に汝らに告ぐ、天ひらけて、人の子のうへに神の使たちの昇り降りするを汝ら見るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, '三日めにガリラヤのカナに婚禮ありて、イエスの母そこに居り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'イエスも弟子たちと共に婚禮に招かれ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, '葡萄酒つきたれば、母イエスに言ふ『かれらに葡萄酒なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'イエス言ひ給ふ『をんなよ、我と汝となにの關係あらんや、我が時は未だ來らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, '母 僕どもに『何にても其の命ずる如くせよ』と言ひおく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, '彼處にユダヤ人の潔の例にしたがひて、四 五 斗 入りの石甕 六個ならべあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'イエス僕に『水を甕に滿せ』といひ給へば、口まで滿す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'また言ひ給ふ『いま汲み取りて饗宴 長に持ちゆけ』乃ち持ちゆけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, '饗宴 長、葡萄酒になりたる水を嘗めて、その何處より來りしかを知らざれば(水を汲みし僕どもは知れり)新郎を呼びて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, '『おほよそ人は先よき葡萄酒を出し、醉のまはる頃ほひ劣れるものを出すに、汝はよき葡萄酒を今まで留め置きたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'イエス此の第一の徴をガリラヤのカナにて行ひ、その榮光を顯し給ひたれば、弟子たち彼を信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'この後イエス及びその母・兄弟・弟子たちカペナウムに下りて、そこに數日 留りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'かくてユダヤ人の過越の祭ちかづきたれば、イエス、エルサレムに上り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, '宮の内に牛・羊・鴿を賣るもの、兩替する者の坐するを見て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, '繩を鞭につくり、羊をも牛をもみな宮より逐ひ出し、兩替する者の金を散し、その臺を倒し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, '鴿をうる者に言ひ給ふ『これらの物を此處より取り去れ、わが父の家を商賣の家とすな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, '弟子たち『なんじの家をおもふ熱心われを食はん』と録されたるを憶ひ出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'ここにユダヤ人こたへてイエスに言ふ『なんぢ此 等の事をなすからには、我らに何の徴を示すか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, '答へて言ひ給ふ『なんぢら此の宮をこぼて、われ三日の間に之を起さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'ユダヤ人いふ『この宮を建つるには四十 六 年を經たり、なんぢは三日のうちに之を起すか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'これはイエス己が體の宮をさして言ひ給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, '然れば死人の中より甦へり給ひしのち、弟子たち斯く言ひ給ひしことを憶ひ出して、聖書とイエスの言ひ給ひし言とを信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, '過越のまつりの間、イエス、エルサレムに在すほどに、多くの人々その爲し給へる徴を見て御名を信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'されどイエス己を彼らに任せ給はざりき。それは凡ての人を知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'また人の衷にある事を知りたまへば、人に就きて證する者を要せざる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'ここにパリサイ人にて名をニコデモといふ人あり、ユダヤ人の宰なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, '夜イエスの許に來りて言ふ『ラビ、我らは汝の神より來る師なるを知る。神もし偕に在さずば、汝が行ふこれらの徴は誰もなし能はぬなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'イエス答へて言ひ給ふ『まことに誠に汝に告ぐ、人あらたに生れずば、神の國を見ること能はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'ニコデモ言ふ『人はや老いぬれば、爭で生るる事を得んや、再び母の胎に入りて生るることを得んや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'イエス答へ給ふ『まことに誠に汝に告ぐ、人は水と靈とによりて生れずば、神の國に入ること能はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, '肉によりて生るる者は肉なり、靈によりて生るる者は靈なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'なんぢら新に生るべしと我が汝に言ひしを怪しむな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, '風は己が好むところに吹く、汝その聲を聞けども、何處より來り何處へ往くを知らず。すべて靈によりて生るる者も斯くのごとし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'ニコデモ答へて言ふ『いかで斯かる事どものあり得べき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'イエス答へて言ひ給ふ『なんぢはイスラエルの師にして、猶かかる事どもを知らぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, '誠にまことに汝に告ぐ、我ら知ることを語り、また見しことを證す、然るに汝らその證を受けず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'われ地のことを言ふに汝ら信ぜずば、天のことを言はんには爭で信ぜんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, '天より降りし者、即ち人の子の他には、天に昇りしものなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'モーセ荒野にて蛇を擧げしごとく、人の子もまた必ず擧げらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'すべて信ずる者の彼によりて永遠の生命を得ん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'それ神はその獨子を賜ふほどに世を愛し給へり、すべて彼を信ずる者の亡びずして、永遠の生命を得んためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, '神その子を世に遣したまへるは、世を審かん爲にあらず、彼によりて世の救はれん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, '彼を信ずる者は審かれず、信ぜぬ者は既に審かれたり。神の獨子の名を信ぜざりしが故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'その審判は是なり。光、世にきたりしに、人その行爲の惡しきによりて、光よりも暗黒を愛したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'すべて惡を行ふ者は光をにくみて光に來らず、その行爲の責められざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, '眞をおこなふ者は光にきたる、その行爲の神によりて行ひたることの顯れん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'この後イエス、弟子たちとユダヤの地にゆき、其處にともに留りてバプテスマを施し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'ヨハネもサリムに近きアイノンにてバプテスマを施しゐたり、其處に水おほくある故なり。人々つどひ來りてバプテスマを受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'ヨハネは未だ獄に入れられざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'ここにヨハネの弟子たちと一人のユダヤ人との間に、潔につきて論 起りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, '彼らヨハネの許に來りて言ふ『ラビ、視よ、汝とともにヨルダンの彼方にありし者、なんぢが證せし者、バプテスマを施し、人みなその許に往くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'ヨハネ答へて言ふ『人は天より與へられずば、何をも受くること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, '「我はキリストにあらず」唯「その前に遣されたる者なり」と我が言ひしことに就きて證する者は汝らなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, '新婦をもつ者は新郎なり、新郎の友は、立ちて新郎の聲をきくとき大に喜ぶ、この我が勸喜いま滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, '彼は必ず盛になり、我は衰ふべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, '上より來るものは凡ての物の上にあり、地より出づるものは地の者にして、その語ることも地の事なり。天より來るものは凡ての物の上にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, '彼その見しところ聞きしところを證したまふに、誰もその證を受けず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'その證を受くる者は、印して神を眞なりとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, '神の遣し給ひし者は神の言をかたる、神、御靈を賜ひて量りなければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, '父は御子を愛し、萬物をその手に委ね給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, '御子を信ずる者は永遠の生命をもち、御子に從はぬ者は生命を見ず、反つて神の怒その上に止るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, '主、おのれの弟子を造り、之にバプテスマを施すこと、ヨハネよりも多しと、パリサイ人に聞えたるを知り給ひし時、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(その實イエス自らバプテスマを施ししにあらず、その弟子たちなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'ユダヤを去りて復ガリラヤに往き給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'サマリヤを經ざるを得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'サマリヤのスカルといふ町にいたり給へるが、この町はヤコブその子ヨセフに與へし土地に近くして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, '此處にヤコブの泉あり。イエス旅路に疲れて泉の傍らに坐し給ふ、時は第六 時 頃なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'サマリヤの或 女、水を汲まんとて來りたれば、イエス之に『われに飮ませよ』と言ひたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '弟子たちは食物を買はんとて町にゆきしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'サマリヤの女いふ『なんぢはユダヤ人なるに、如何なればサマリヤの女なる我に、飮むことを求むるか』これはユダヤ人とサマリヤ人とは交りせぬ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'イエス答へて言ひ給ふ『なんぢ若し神の賜物を知り、また「我に飮ませよ」といふ者の誰なるを知りたらんには、之に求めしならん、さらば汝に活ける水を與へしものを』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, '女いふ『主よ、なんぢは汲む物を持たず、井は深し、その活ける水は何處より得しぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, '汝はこの井を我らに與へし我らの父ヤコブよりも大なるか、彼も、その子らも、その家畜も、これより飮みたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'イエス答へて言ひ給ふ『すべて此の水をのむ者は、また渇かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'されど我があたふる水を飮む者は、永遠に渇くことなし。わが與ふる水は彼の中にて泉となり、永遠の生命の水 湧きいづべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, '女いふ『主よ、わが渇くことなく、又ここに汲みに來ぬために、その水を我にあたへよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'イエス言ひ給ふ『ゆきて夫をここに呼びきたれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, '女こたへて言ふ『われに夫なし』イエス言ひ給ふ『夫なしといふは宜なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, '夫は五 人までありしが、今ある者はなんぢの夫にあらず。無しと云へるは眞なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, '女いふ『主よ、我なんぢを預言者とみとむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, '我らの先祖たちは此の山にて拜したるに、汝らは拜すべき處をエルサレムなりと言ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'イエス言ひ給ふ『をんなよ、我が言ふことを信ぜよ、此の山にもエルサレムにもあらで、汝ら父を拜する時きたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, '汝らは知らぬ者を拜し、我らは知る者を拜す、救はユダヤ人より出づればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'されど眞の禮拜者の、靈と眞とをもて父を拜する時きたらん、今すでに來れり。父はかくのごとく拜する者を求めたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, '神は靈なれば、拜する者も靈と眞とをもて拜すべきなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, '女いふ『我はキリストと稱ふるメシヤの來ることを知る、彼きたらば諸般のことを我らに告げん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'イエス言ひ給ふ『なんぢと語る我はそれなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, '時に弟子たち歸りきたりて、女と語り給ふを怪しみたれど、何を求め給ふか、何 故かれと語り給ふかと問ふもの誰もなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'ここに女その水瓶を遺しおき、町にゆきて人々にいふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '『來りて見よ、わが爲しし事をことごとく我に告げし人を。この人あるいはキリストならんか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, '人々 町を出でてイエスの許にゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'この間に弟子たち請ひて言ふ『ラビ、食し給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'イエス言ひたまふ『我には汝らの知らぬ我が食する食物あり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, '弟子たち互にいふ『たれか食する物を持ち來りしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'イエス言ひ給ふ『われを遣し給へる物の御意を行ひ、その御業をなし遂ぐるは、是わが食物なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'なんぢら收穫時の來るには、なほ四月ありと言はずや。我なんぢらに告ぐ、目をあげて畑を見よ、はや黄ばみて收穫時になれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, '刈る者は價を受けて永遠の生命の實を集む。播く者と刈る者とともに喜ばん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, '俚諺に、彼は播き此は刈るといへるは、斯において眞なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, '我なんぢらを遣して、勞せざりしものを刈らしむ。他の人々さきに勞し、汝らはその勞を收むるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, '此の町の多くのサマリヤ人、女の『わが爲しし事をことごとく告げし』と證したる言によりてイエスを信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'かくてサマリヤ人 御許にきたりて、此の町に留らんことを請ひたれば、此處に二日とどまり給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, '御言によりて猶もおほくの人 信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'かくて女に言ふ『今われらの信ずるは、汝のかたる言によるにあらず、親しく聽きて、これは眞に世の救主なりと知りたる故なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, '二日の後、イエスここを去りてガリラヤに往き給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'イエス自ら證して、預言者は己が郷にて尊ばるる事なしと言ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'かくてガリラヤに往き給へば、ガリラヤ人これを迎へたり。前に彼らも祭に上り、その祭の時にエルサレムにて行ひ給ひし事を見たる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'イエス復ガリラヤのカナに往き給ふ、ここは前に水を葡萄酒になし給ひし處なり。時に王の近臣あり、その子カペナウムにて病みゐたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'イエスのユダヤよりガリラヤに來り給へるを聞き、御許にゆきて、カペナウムに下りその子を醫し給はんことを請ふ、子は死ぬばかりなりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'ここにイエス言ひ給ふ『なんぢら徴と不思議とを見ずば、信ぜじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, '近臣いふ『主よ、わが子の死なぬ間に下り給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'イエス言ひ給ふ『かへれ、汝の子は生くるなり』彼はイエスの言ひ給ひしことを信じて歸りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, '下る途中、僕ども往き遇ひて、その子の生きたることを告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'その癒えはじめし時を問ひしに『昨日の第七 時に熱 去れり』といふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, '父その時の、イエスが『なんぢの子は生くるなり』と言ひ給ひし時と同じきを知り、而して己も家の者もみな信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, '是はイエス、ユダヤよりガリラヤに往きて爲し給へる第二の徴なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'この後ユダヤ人の祭ありて、イエス、エルサレムに上り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'エルサレムにある羊 門のほとりに、ヘブル語にてベテスダといふ池あり、之にそひて五つの廊あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'その内に病める者、盲人、跛者、痩せ衰へたる者ども夥多しく臥しゐたり。(水の動くを待てるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'それは御使のをりをり降りて水を動かすことあれば、その動きたるのち最先に池にいる者は、如何なる病にても癒ゆる故なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, '爰に三十 八 年 病になやむ人ありしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'イエスその臥し居るを見、かつその病の久しきを知り、之に『なんぢ癒えんことを願ふか』と言ひ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, '病める者こたふ『主よ、水の動くとき、我を池に入るる者なし、我が往くほどに、他の人さきだち下るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'イエス言ひ給ふ『起きよ、床を取りあげて歩め』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'この人ただちに癒え、床を取りあげて歩めり。その日は安息 日に當りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'ユダヤ人 醫されたる人にいふ『安息 日なり、床を取りあぐるは宜しからず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, '答ふ『われを醫ししその人「床を取りあげて歩め」と云へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'かれら問ふ『「取りあげて歩め」と言ひし人は誰なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'されど醫されし者は、その誰なるを知らざりき、そこに群衆ゐたればイエス退き給ひしに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'この後イエス宮にて彼に遇ひて言ひたまふ『視よ、なんぢ癒えたり。再び罪を犯すな、恐らくは更に大なる惡しきこと汝に起らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'この人ゆきてユダヤ人に、おのれを醫したる者のイエスなるを告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'ここにユダヤ人、かかる事を安息 日になすとて、イエスを責めたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'イエス答へ給ふ『わが父は今にいたるまで働き給ふ、我もまた働くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, '此に由りてユダヤ人いよいよイエスを殺さんと思ふ。それは安息 日を破るのみならず、神を我が父といひて、己を神と等しき者になし給ひし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'イエス答へて言ひ給ふ『まことに誠に汝らに告ぐ、子は父のなし給ふことを見て行ふほかは、自ら何事をも爲し得ず、父のなし給ふことは子もまた同じく爲すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, '父は子を愛して、その爲す所をことごとく子に示したまふ。また更に大なる業を示し給はん、汝 等をして怪しましめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, '父の死にし者を起して活し給ふごとく、子もまた己が欲する者を活すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, '父は誰をも審き給はず、審判をさへみな子に委ね給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'これ凡ての人の父を敬ふごとくに子を敬はん爲なり。子を敬はぬ者は、之を遣し給ひし父をも敬はぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, '誠にまことに汝らに告ぐ、わが言をききて我を遣し給ひし者を信ずる人は、永遠の生命をもち、かつ審判に至らず、死より生命に移れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, '誠にまことに汝らに告ぐ、死にし人、神の子の聲をきく時きたらん、今すでに來れり、而して聞く人は活くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'これ父みづから生命を有ち給ふごとく、子にも自ら生命を有つことを得させ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'また人の子たるに因りて、審判する權を與へ給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, '汝ら之を怪しむな、墓にある者みな神の子の聲をききて出づる時きたらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, '善をなしし者は生命に甦へり、惡を行ひし者は審判に甦へるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, '我みづから何事もなし能はず、ただ聞くままに審くなり。わが審判は正し、それは我が意を求めずして、我を遣し給ひし者の御意を求むるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, '我もし己につきて證せば、我が證は眞ならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, '我につきて證する者は他にあり、その我につきて證する證の眞なるを我は知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'なんぢら前に人をヨハネに遣ししに、彼は眞につきて證せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, '我は人よりの證を受くる事をせねど、唯なんぢらの救はれん爲に之を言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'かれは燃えて輝く燈火なりしが、汝 等その光にありて暫時よろこぶ事をせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'されど我にはヨハネの證よりも大なる證あり。父の我にあたへて成し遂げしめ給ふわざ、即ち我がおこなふ業は、我につきて父の我を遣し給ひたるを證し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'また我をおくり給ひし父も、我につきて證し給へり。汝らは未だその御聲を聞きし事なく、その御形を見し事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'その御言は汝らの衷にとどまらず、その遣し給ひし者を信ぜぬに因りて知らるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, '汝らは聖書に永遠の生命ありと思ひて之を査ぶ、されどこの聖書は我につきて證するものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, '然るに汝ら生命を得んために我に來るを欲せず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, '我は人よりの譽をうくる事をせず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'ただ汝らの衷に神を愛する事なきを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, '我はわが父の名によりて來りしに、汝 等われを受けず、もし他の人おのれの名によりて來らば之を受けん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, '互に譽をうけて、唯一の神よりの譽を求めぬ汝らは、爭で信ずることを得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'われ父に汝らを訴へんとすと思ふな、訴ふるもの一人あり、汝らが頼とするモーセなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, '若しモーセを信ぜしならば、我を信ぜしならん、彼は我につきて録したればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'されど彼の書を信ぜずば、爭で我が言を信ぜんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'この後イエス、ガリラヤの海、即ちテベリヤの海の彼方にゆき給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, '大なる群衆これに從ふ、これは病みたる者に行ひたまへる徴を見し故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'イエス山に登りて、弟子たちと共にそこに坐し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, '時はユダヤ人の祭なる過越に近し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'イエス眼をあげて大なる群衆のきたるを見て、ピリポに言ひ給ふ『われら何處よりパンを買ひて、此の人々に食はすべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'かく言ひ給ふはピリポを試むるためにて、自ら爲さんとする事を知り給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'ピリポ答へて言ふ『二 百デナリのパンありとも、人々すこしづつ受くるになほ足らじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, '弟子の一人にてシモン・ペテロの兄弟なるアンデレ言ふ');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '『ここに一人の童子あり、大麥のパン五つと小き肴 二つとをもてり、されど此の多くの人には何にかならん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'イエス言ひたまふ『人々を坐せしめよ』その處に多くの草ありて人々 坐せしが、その數おほよそ五 千 人なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'ここにイエス、パンを取りて謝し、坐したる人々に分ちあたへ、また肴をも然なして、その欲するほど與へ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, '人々の飽きたるのち弟子たちに言ひたまふ『廢るもののなきように擘きたる餘をあつめよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, '乃ち集めたるに、五つの大麥のパンの擘きたるを食ひしものの餘、十二の筐に滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, '人々その爲し給ひし徴を見ていふ『實にこれは世に來るべき預言者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'イエス彼らが來りて己をとらへ、王となさんとするを知り、復ひとりにて山に遁れたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, '夕になりて弟子たち海にくだり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, '船にのり海を渡りて、カペナウムに往かんとす。既に暗くなりたるに、イエス未だ來りたまはず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, '大風ふきて海ややに荒出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'かくて四 五 十 丁こぎ出でしに、イエスの海の上をあゆみ、船に近づき給ふを見て懼れたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'イエス言ひたまふ『我なり、懼るな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, '乃ちイエスを船に歓び迎へしに、船は直ちに往かんとする地に著けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, '明くる日、海のかなたに立てる群衆は、一艘のほかに船なく、又イエスは弟子たちと共に乘りたまはず、弟子たちのみ出でゆきしを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(時にテベリヤより數艘の船、主の謝して人々にパンを食はせ給ひし處の近くに來る)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'ここに群衆はイエスも居給はず、弟子たちも居らぬを見て、その船に乘り、イエスを尋ねてカペナウムに往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, '遂に海の彼方にてイエスに遇ひて言ふ『ラビ、何時ここに來り給ひしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'イエス答へて言ひ給ふ『まことに誠に汝らに告ぐ、汝らが我を尋ぬるは、徴を見し故ならで、パンを食ひて飽きたる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, '朽ちる糧のためならで、永遠の生命にまで至る糧のために働け。これは人の子の汝らに與へんとするものなり、父なる神は印して彼を證し給ひたるに因る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'ここに彼ら言ふ『われら神の業を行はんには何をなすべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'イエス答へて言ひたまふ『神の業はその遣し給へる者を信ずる是なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, '彼ら言ふ『さらば我らが見て汝を信ぜしために、何の徴をなすか、何を行ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, '我らの先祖は荒野にてマナを食へり、録して「天よりパンを彼らに與へて食はしめたり」と云へるが如し』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'イエス言ひ給ふ『まことに誠に汝らに告ぐ、モーセは天よりのパンを汝らに與へしにあらず、されど我が父は天よりの眞のパンを與へたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, '神のパンは天より降りて生命を世に與ふるものなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, '彼 等いふ『主よ、そのパンを常に與へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'イエス言ひ給ふ『われは生命のパンなり、我にきたる者は飢ゑず、我を信ずる者はいつまでも渇くことなからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'されど汝らは我を見てなほ信ぜず、我さきに之を告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, '父の我に賜ふものは皆われに來らん、我にきたる者は我これを退けず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, '夫わが天より降りしは、我が意をなさん爲にあらず、我を遣し給ひし者の御意をなさん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, '我を遣し給ひし者の御意は、すべて我に賜ひし者を、我その一つをも失はずして、終の日に甦へらする是なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'わが父の御意は、すべて子を見て信ずる者の永遠の生命を得る是なり。われ終の日にこれを甦へらすべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'ここにユダヤ人ら、イエスの『われは天より降りしパンなり』と言ひ給ひしにより、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, '呟きて言ふ『これはヨセフの子イエスならずや、我等はその父 母を知る、何ぞ今「われは天より降れり」と言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'イエス答へて言ひ給ふ『なんぢら呟き合ふな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, '我を遣しし父ひき給はずば、誰も我に來ること能はず、我これを終の日に甦へらすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, '預言者たちの書に「彼らみな神に教へられん」と録されたり。すべて父より聽きて學びし者は我にきたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'これは父を見し者ありとにあらず、ただ神よりの者のみ父を見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'まことに誠になんぢらに告ぐ、信ずる者は永遠の生命をもつ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, '我は生命のパンなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, '汝らの先祖は、荒野にてマナを食ひしが死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, '天より降るパンは、食ふ者をして死ぬる事なからしむるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, '我は天より降りし活けるパンなり、人このパンを食はば永遠に活くべし。我が與ふるパンは我が肉なり、世の生命のために之を與へん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'ここにユダヤ人たがひに爭ひて言ふ『この人はいかで己が肉を我らに與へて食はしむることを得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'イエス言ひ給ふ『まことに誠になんぢらに告ぐ、人の子の肉を食はず、その血を飮まずば、汝らに生命なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'わが肉をくらひ、我が血をのむ者は、永遠の生命をもつ、われ終の日にこれを甦へらすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, '夫わが肉は眞の食物、わが血は眞の飮物なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'わが肉をくらひ我が血をのむ者は、我に居り、我もまた彼に居る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, '活ける父の我をつかはし、我の父によりて活くるごとく、我をくらふ者も我によりて活くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, '天より降りしパンは、先祖たちが食ひてなほ死にし如きものにあらず、此のパンを食ふものは永遠に活きん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, '此 等のことはイエス、カペナウムにて教ふるとき、會堂にて言ひ給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, '弟子たちの中おほくの者これを聞きて言ふ『こは甚だしき言なるかな、誰か能く聽き得べき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'イエス弟子たちの之に就きて呟くを自ら知りて言ひ給ふ『このことは汝らを躓かするか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'さらば人の子のもと居りし處に昇るを見ば如何に。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, '活すものは靈なり、肉は益する所なし、わが汝らに語りし言は、靈なり、生命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'されど汝らの中に信ぜぬ者どもあり』イエス初より、信ぜぬ者どもは誰、おのれを賣る者は誰なるかを知り給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'かくて言ひたまふ『この故に我さきに汝らに告げて、父より賜はりたる者ならずば我に來るを得ずと言ひしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'ここにおいて、弟子たちのうち多くの者かへり去りて、復イエスと共に歩まざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'イエス十二 弟子に言ひ給ふ『なんじらも去らんとするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'シモン・ペテロ答ふ『主よ、われら誰にゆかん、永遠の生命の言は汝にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, '又われらは信じかつ知る、なんぢは神の聖者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'イエス答へ給ふ『われ汝ら十二 人を選びしにあらずや、然るに汝らの中の一人は惡魔なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'イスカリオテのシモンの子ユダを指して言ひ給へるなり、彼は十二 弟子の一人なれど、イエスを賣らんとする者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'この後イエス、ガリラヤのうちを巡りゐ給ふ、ユダヤ人の殺さんとするに因りて、ユダヤのうちを巡ることを欲し給はぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'ユダヤ人の假廬の祭ちかづきたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, '兄弟たちイエスに言ふ『なんぢの行ふ業を弟子たちにも見せんために、此處を去りてユダヤに往け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, '誰にても自ら顯れんことを求めて、隱に業をなす者なし。汝これらの事を爲すからには、己を世にあらはせ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, '是その兄弟たちもイエスを信ぜぬ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'ここにイエス言ひ給ふ『わが時はいまだ到らず、汝らの時は常に備れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, '世は汝らを憎むこと能はねど我を憎む、我は世の所作の惡しきを證すればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'なんぢら祭に上れ、わが時いまだ滿たねば、我は今この祭にのぼらず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'かく言ひて尚ガリラヤに留り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, '而して兄弟たちの祭にのぼりたる後、あらはならで潜びやかに上り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, '祭にあたりユダヤ人らイエスを尋ねて『かれは何處に居るか』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'また群衆のうちに囁く者おほくありて、或は『イエスは善き人なり』といひ、或は『いな、群衆を惑すなり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'されどユダヤ人を懼るるに因りて、誰もイエスのことを公然に言はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, '祭も、はや半となりし頃、イエス宮にのぼりて教へ給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'ユダヤ人あやしみて言ふ『この人は學びし事なきに、如何にして書を知るか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'イエス答へて言ひ給ふ『わが教はわが教にあらず、我を遣し給ひし者の教なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, '人もし御意を行はんと欲せば、此の教の神よりか、我が己より語るかを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, '己より語るものは己の榮光をもとむ、己を遣しし者の榮光を求むる者は眞なり、その中に不義なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'モーセは汝らに律法を與へしにあらずや、されど汝 等のうちに律法を守る者なし。汝ら何ゆゑ我を殺さんとするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, '群衆こたふ『なんぢは惡鬼に憑かれたり、誰が汝を殺さんとするぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'イエス答へて言ひ給ふ『われ一つの業をなしたれば、汝 等みな怪しめり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'モーセは汝らに割禮を命じたり(これはモーセより起りしとにあらず、先祖より起りしなり)この故に汝ら安息 日にも人に割禮を施す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'モーセの律法の廢らぬために、安息 日に人の割禮を受くる事あらば、何ぞ安息 日に人の全身を健かにせしとて我を怒るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, '外貌によりて裁くな、正しき審判にて審け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'ここにエルサレムの或 人々いふ『これは人々の殺さんとする者ならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, '視よ、公然に語るに、之に對して何をも言ふ者なし、司たちは此の人のキリストたるを眞に認めしならんか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'されど我らは此の人の何處よりかを知る、キリストの來る時には、その何處よりかを知る者なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'ここにイエス宮にて教へつつ呼はりて言ひ給ふ『なんぢら我を知り、亦わが何處よりかを知る。されど我は己より來るにあらず、眞の者ありて我を遣し給へり。汝らは彼を知らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, '我は彼を知る。我は彼より出で、彼は我を遣し給ひしに因りてなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'ここに人々イエスを捕へんと謀りたれど、彼の時いまだ到らぬ故に手出する者なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'かくて群衆のうち多くの人々イエスを信じて『キリスト來るとも、此の人の行ひしより多く徴を行はんや』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'イエスにつきて群衆のかく囁くことパリサイ人の耳に入りたれば、祭司長・パリサイ人ら彼を捕へんとて下役どもを遣ししに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'イエス言ひ給ふ『我なほ暫く汝らと偕に居り、而してのち我を遣し給ひし者の御許に往く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, '汝ら我を尋ねん、されど逢はざるべし、汝 等わが居る處に往くこと能はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'ここにユダヤ人ら互に云ふ『この人われらの逢ひ得ぬいづこに往かんとするか、ギリシヤ人のうちに散りをる者に往きて、ギリシヤ人を教へんとするか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'その言に「なんぢら我を尋ねん、然れど逢はざるべし、汝ら我がをる處に往くこと能はず」と云へるは何ぞや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, '祭の終の大なる日に、イエス立ちて呼はりて言ひたまふ『人もし渇かば我に來りて飮め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, '我を信ずる者は、聖書に云へるごとく、その腹より活ける水、川となりて流れ出づべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'これは彼を信ずる者の受けんとする御靈を指して言ひ給ひしなり。イエス未だ榮光を受け給はざれば、御靈いまだ降らざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, '此 等の言をききて群衆のうちの或 人は『これ眞にかの預言者なり』といひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, '或 人は『これキリストなり』と言ひ、又ある人は『キリストいかでガリラヤより出でんや、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, '聖書に、キリストはダビデの裔またダビデの居りし村ベツレヘムより出づと云へるならずや』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, '斯くイエスの事によりて、群衆のうちに紛爭おこりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'その中には、イエスを捕へんと欲する者もありしが、手出する者なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, '而して下役ども、祭司長・パリサイ人らの許に歸りたれば、彼ら問ふ『なに故かれを曳き來らぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, '下役ども答ふ『この人の語るごとく語りし人は未だなし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'パリサイ人 等これに答ふ『なんぢらも惑されしか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, '司たち又はパリサイ人のうちに、一人だに彼を信ぜし者ありや、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, '律法を知らぬこの群衆は詛はれたる者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, '彼 等のうちの一人にてさきにイエスの許に來りしニコデモ言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '『われらの律法は、先その人に聽き、その爲すところを知るにあらずば、審く事をせんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'かれら答へて言ふ『なんぢもガリラヤより出でしか、査べ見よ、預言者はガリラヤより起る事なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '[斯くておのおの己が家に歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'イエス、オリブ山にゆき給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, '夜明ごろ、また宮に入りしに、民みな御許に來りたれば、坐して教へ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'ここに學者・パリサイ人ら、姦淫のとき捕へられたる女を連れきたり、眞中に立ててイエスに言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, '『師よ、この女は姦淫のをり、そのまま捕へられたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'モーセは律法に、斯かる者を石にて撃つべき事を我らに命じたるが、汝は如何に言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'かく云へるは、イエスを試みて、訴ふる種を得んとてなり。イエス身を屈め、指にて地に物 書き給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'かれら問ひて止まざれば、イエス身を起して『なんぢらの中、罪なき者まづ石を擲て』と言ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'また身を屈めて地に物 書きたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, '彼 等これを聞きて良心に責められ、老人をはじめ若き者まで一人 一人いでゆき、唯イエスと中に立てる女とのみ遺れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'イエス身を起して、女のほかに誰も居らぬを見て言ひ給ふ『をんなよ、汝を訴へたる者どもは何處にをるぞ、汝を罪する者なきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, '女いふ『主よ、誰もなし』イエス言ひ給ふ『われも汝を罪せじ、往け、この後ふたたび罪を犯すな』]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'かくてイエスまた人々に語りて言ひ給ふ『われは世の光なり、我に從ふ者は暗き中を歩まず、生命の光を得べし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'パリサイ人ら言ふ『なんぢは己につきて證す、なんぢの證は眞ならず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'イエス答へて言ひ給ふ『われ自ら己につきて證すとも、我が證は眞なり、我は何處より來り何處に往くを知る故なり。汝らは我が何處より來り、何處に往くを知らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'なんぢらは肉によりて審く、我は誰をも審かず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'されど我もし審かば、我が審判は眞なり、我は一人ならず、我と我を遣し給ひし者と偕なるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'また汝らの律法に、二人の證は眞なりと録されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, '我みづから己につきて證をなし、我を遣し給ひし父も我につきて證をなし給ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'ここに彼ら言ふ『なんぢの父は何處にあるか』イエス答へ給ふ『なんぢらは我をも我が父をも知らず、我を知りしならば、我が父をも知りしならん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'イエス宮の内にて教へし時、これらの事を賽錢函の傍らにて語り給ひしが、彼の時いまだ到らぬ故に、誰も捕ふる者なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'かくてまた人々に言ひ給ふ『われ往く、なんぢら我を尋ねん。されど己が罪のうちに死なん、わが往くところに汝ら來ること能はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'ユダヤ人ら言ふ『「わが往く處に汝ら來ること能はず」と云へるは、自殺せんとてか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'イエス言ひ給ふ『なんぢらは下より出で、我は上より出づ、汝らは此の世より出で、我は此の世より出でず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, '之によりて我なんぢらは己が罪のうちに死なんと云へるなり。汝 等もし我の夫なるを信ぜずば、罪のうちに死ぬべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, '彼ら言ふ『なんぢは誰なるか』イエス言ひ給ふ『われは正しく汝らに告げ來りし所の者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'われ汝らに就きて語るべきこと審くべきこと多し、而して我を遣し給ひし者は眞なり、我は彼に聽きしその事を世に告ぐるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'これは父をさして言ひ給へるを、彼らは悟らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'ここにイエス言ひ給ふ『なんぢら人の子を擧げしのち、我の夫なるを知り、又わが己によりて何事をも爲さず、ただ父の我に教へ給ひしごとく、此 等のことを語りたるを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, '我を遣し給ひし者は、我とともに在す。我つねに御意に適ふことを行ふによりて、我を獨おき給はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, '此 等のことを語り給へるとき、多くの人々イエスを信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'ここにイエス己を信じたるユダヤ人に言ひたまふ『汝 等もし常に我が言に居らば、眞にわが弟子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'また眞理を知らん、而して眞理は汝らに自由を得さすべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'かれら答ふ『われはアブラハムの裔にして、未だ人の奴隷となりし事なし。如何なれば「なんぢら自由を得べし」と言ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'イエス答へ給ふ『まことに誠に汝らに告ぐ、すべて罪を犯す者は罪の奴隷なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, '奴隷はとこしへに家に居らず、子は永遠に居るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'この故に子もし汝らに自由を得させば、汝ら實に自由とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, '我は汝らがアブラハムの裔なるを知る、されど我が言なんぢらの衷に留らぬ故に、我を殺さんと謀る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, '我はわが父の許にて見しことを語り、汝らは又なんぢらの父より聞きしことを行ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'かれら答へて言ふ『われらの父はアブラハムなり』イエス言ひ給ふ『もしアブラハムの子ならば、アブラハムの業をなさん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, '然るに汝らは今、神より聽きたる眞理を汝らに告ぐる者なる我を殺さんと謀る。アブラハムは斯かることを爲さざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, '汝らは汝らの父の業を爲すなり』かれら言ふ『われら淫行によりて生れず、我らの父はただ一人、即ち神なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'イエス言ひたまふ『神もし汝らの父ならば、汝ら我を愛せん、われ神より出でて來ればなり。我は己より來るにあらず、神われを遣し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, '何 故わが語ることを悟らぬか、是わが言をきくこと能はぬに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, '汝らは己が父 惡魔より出でて、己が父の慾を行はんことを望む。彼は最初より人殺なり、また眞その中になき故に眞に立たず、彼は虚僞をかたる毎に己より語る、それは虚僞 者にして虚僞の父なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, '然るに我は眞を告ぐるによりて、汝ら我を信ぜず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, '汝 等のうち誰か我を罪ありとして責め得る。われ眞を告ぐるに、我を信ぜぬは何 故ぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, '神より出づる者は神の言をきく、汝らの聽かぬは神より出でぬに因る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'ユダヤ人こたへて言ふ『なんぢはサマリヤ人にて惡鬼に憑かれたる者なりと、我らが云へるは宜ならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'イエス答へ給ふ『われは惡鬼に憑かれず、反つて我が父を敬ふ、なんぢらは我を輕んず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, '我はおのれの榮光を求めず、之を求めかつ審判し給ふ者あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, '誠にまことに汝らに告ぐ、人もし我が言を守らば、永遠に死を見ざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'ユダヤ人いふ『今ぞなんぢが惡鬼に憑かれたるを知る。アブラハムも預言者たちも死にたり、然るに汝は「人もし我が言を守らば、永遠に死を味はざるべし」と云ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, '汝われらの父アブラハムよりも大なるか、彼は死に、預言者たちも死にたり、汝はおのれを誰とするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'イエス答へたまふ『我もし己に榮光を歸せば、我が榮光は空し。我に榮光を歸する者は我が父なり、即ち汝らが己の神と稱ふる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, '然るに汝らは彼を知らず、我は彼を知る。もし彼を知らずと言はば、汝らの如く僞 者たるべし。されど我は彼を知り、且その御言を守る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, '汝らの父アブラハムは、我が日を見んとて樂しみ且これを見て喜べり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'ユダヤ人いふ『なんぢ未だ五十歳にもならぬにアブラハムを見しか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'イエス言ひ給ふ『まことに誠に汝らに告ぐ、アブラハムの生れいでぬ前より我は在るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'ここに彼ら石をとりてイエスに擲たんとしたるに、イエス隱れて宮を出で給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'イエス途 往くとき、生れながらの盲人を見 給ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, '弟子たち問ひて言ふ『ラビ、この人の盲目にて生れしは、誰の罪によるぞ、己のか、親のか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'イエス答へ給ふ『この人の罪にも親の罪にもあらず、ただ彼の上に神の業の顯れん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, '我を遣し給ひし者の業を我ら晝の間になさざる可からず。夜きたらん、その時は誰も働くこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'われ世にをる間は世の光なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'かく言ひて地に唾し、唾にて泥をつくり、之を盲人の目にぬりて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, '『ゆきてシロアム(釋けば遣されたる者)の池にて洗へ』乃ちゆきて洗ひたれば、見ゆることを得て歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'ここに隣 人および前に彼の乞食なるを見し者ども言ふ『この人は坐して物 乞ひゐたるにあらずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, '或 人は『夫なり』といひ、或 人は『否、ただ似たるなり』といふ。かの者『われは夫なり』と言ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, '人々いふ『さらば汝の目は如何にして開きたるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, '答ふ『イエスといふ人、泥をつくり我が目に塗りて言ふ「シロアムに往きて洗へ」と、乃ち往きて洗ひたれば、物 見ることを得たり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, '彼ら『その人は何處に居るか』と言へば『知らず』と答ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, '人々さきに盲目なりし者をパリサイ人らの許に連れきたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'イエスの泥をつくりて其の人の目をあけし日は安息 日なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'パリサイ人らも亦いかにして物 見ることを得しかと問ひたれば、彼いふ『かの人わが目に泥をぬり、我これを洗ひて見ゆることを得たり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'パリサイ人の中なる或 人は『かの人、安息 日を守らぬ故に、神より出でし者にあらず』と言ひ、或 人は『罪ある人いかで斯かる徴をなし得んや』と言ひて互に相 爭ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'ここにまた盲目なりし人に言ふ『なんぢの目をあけしに因り、汝は彼に就きて如何にいふか』彼いふ『預言者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'ユダヤ人ら、彼が盲目なりしに見ゆるやうになりしことを、未だ信ぜずして、目の開きたる人の兩親を呼び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, '問ひて言ふ『これは盲目にて生れしと言ふ汝らの子なりや、さらば今いかにして見ゆるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, '兩親こたへて言ふ『かれの我が子なることと、盲目にて生れたる事とを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'されど今いかにして見ゆるかを知らず、又その目をあけしは誰なるか、我らは知らず、彼に問へ、年 長けたれば自ら己がことを語らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, '兩親のかく言ひしはユダヤ人を懼れたるなり。ユダヤ人ら相 議りて『若しイエスをキリストと言ひ顯す者あらば、除名すべし』と定めたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, '兩親の『かれ年 長けたれば彼に問へ』と云へるは此の故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'かれら盲目なりし人を再び呼びて言ふ『神に榮光を歸せよ、我等はかの人の罪人たるを知る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, '答ふ『かれ罪人なるか、我は知らず、ただ一つの事をしる、即ち我さきに盲目たりしが、今 見ゆることを得たる是なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, '彼ら言ふ『かれは汝に何をなししか、如何にして目をあけしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, '答ふ『われ既に汝らに告げたれど聽かざりき。何ぞまた聽かんとするか、汝らもその弟子とならんことを望むか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'かれら罵りて言ふ『なんぢは其の弟子なり、我等モーセの弟子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'モーセに神の語り給ひしことを知れど、此の人の何處よりかを知らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, '答へて言ふ『その何處よりかを知らずとは怪しき事なり、彼わが目をあけしに。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, '神は罪人に聽き給はねど、敬虔にして御意をおこなふ人に聽き給ふことを我らは知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, '世の太初より、盲目にて生れし者の目をあけし人あるを聞きし事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'かの人もし神より出でずば、何事をも爲し得ざらん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'かれら答へて『なんぢ全く罪のうちに生れながら、我らを教ふるか』と言ひて、遂に彼を追ひ出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'イエスその追ひ出されしことを聞き、彼に逢ひて言ひ給ふ『なんぢ人の子を信ずるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, '答へて言ふ『主よ、それは誰なる乎、われ信ぜまほし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'イエス言ひ給ふ『なんぢ彼を見たり、汝と語る者は夫なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'ここに彼『主よ、我は信ず』といひて拜せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'イエス言ひ給ふ『われ審判の爲にこの世に來れり。見えぬ人は見え、見ゆる人は盲目とならん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'パリサイ人の中イエスと共に居りし者、これを聞きて言ふ『我らも盲目なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'イエス言ひ給ふ『もし盲目なりしならば、罪なかりしならん、されど見ゆと言ふ汝らの罪は遺れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '『まことに誠に汝らに告ぐ、羊の檻に門より入らずして、他より越ゆる者は、盜人なり、強盜なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, '門より入る者は、羊の牧者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, '門守は彼のために開き、羊はその聲をきき、彼は己の羊の名を呼びて牽きいだす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, '悉とく其の羊をいだしし時、これに先だちゆく、羊その聲を知るによりて從ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, '他の者には從はず、反つて逃ぐ、他の者どもの聲を知らぬ故なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'イエスこの譬を言ひ給へど、彼らその何事をかたり給ふかを知らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'この故にイエス復いひ給ふ『まことに誠に汝らに告ぐ、我は羊の門なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'すべて我より前に來りし者は、盜人なり、強盜なり、羊は之に聽かざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, '我は門なり、おほよそ我によりて入る者は救はれ、かつ出入をなし、草を得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, '盜人のきたるは盜み、殺し、亡さんとするの他なし。わが來るは羊に生命を得しめ、かつ豐に得しめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, '我は善き牧者なり、善き牧者は羊のために生命を捨つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, '牧者ならず、羊も己がものならぬ雇人は、豺狼のきたるを見れば羊を棄てて逃ぐ、――豺狼は羊をうばひ且ちらす――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, '彼は雇人にて、その羊を顧みぬ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, '我は善き牧者にして、我がものを知り、我がものは我を知る、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, '父の我を知り、我の父を知るが如し、我は羊のために生命を捨つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, '我には亦この檻のものならぬ他の羊あり、之をも導かざるを得ず、彼らは我が聲をきかん、遂に一つの群ひとりの牧者となるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, '之によりて父は我を愛し給ふ、それは我ふたたび生命を得んために生命を捨つる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, '人これを我より取るにあらず、我みづから捨つるなり。我は之をすつる權あり、復これを得る權あり、我この命令をわが父より受けたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'これらの言によりて復ユダヤ人のうちに紛爭おこり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'その中なる多くの者いふ『かれは惡鬼に憑かれて氣 狂へり、何ぞ之にきくか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, '他の者ども言ふ『これは惡鬼に憑かれたる者の言にあらず、惡鬼は盲人の目をあけ得んや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'その頃エルサレムに宮 潔の祭あり、時は冬なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'イエス宮の内、ソロモンの廊を歩みたまふに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'ユダヤ人ら之を取圍みて言ふ『何時まで我らの心を惑しむるか、汝キリストならば明白に告げよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'イエス答へ給ふ『われ既に告げたれど汝ら信ぜず、わが父の名によりて行ふわざは、我に就きて證す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'されど汝らは信ぜず、我が羊ならぬ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'わが羊はわが聲をきき、我は彼らを知り、彼らは我に從ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, '我かれらに永遠の生命を與ふれば、彼らは永遠に亡ぶることなく、又かれらを我が手より奪ふ者あらじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, '彼らを我にあたへ給ひし我が父は、一切のものよりも大なれば、誰にても父の御手よりは奪ふこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, '我と父とは一つなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'ユダヤ人また石を取りあげてイエスを撃たんとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'イエス答へ給ふ『われは父によりて多くの善き業を汝らに示したり、その孰の業ゆゑに我を石にて撃たんとするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'ユダヤ人こたふ『なんぢを石にて撃つは善きわざの故ならず、瀆言の故にして、なんぢ人なるに、己を神とする故なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'イエス答へ給ふ『なんぢらの律法に「われ言ふ、汝らは神なり」と録されたるに非ずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'かく神の言を賜はりし人々を神と云へり。聖書は廢るべきにあらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, '然るに父の潔め別ちて世に遣し給ひし者が「われは神の子なり」と言へばとて、何ぞ「瀆言を言ふ」といふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, '我もし我が父のわざを行はずば、我を信ずな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'もし行はば、假令われを信ぜずとも、その業を信ぜよ。さらば父の我にをり、我の父に居ることを知りて悟らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'かれら復イエスを捕へんとせしが、その手より脱れて去り給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'かくてイエス復ヨルダンの彼方、ヨハネの最初にバプテスマを施したる處にいたり、其處にとどまり給ひしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, '多くの人みもとに來りて『ヨハネは何の徴をも行はざりしかど、この人に就きてヨハネの言ひし事は、ことごとく眞なりき』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, '而して多くの人かしこにてイエスを信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'ここに病める者あり、ラザロと云ふ、マリヤとその姉妹マルタとの村ベタニヤの人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '此のマリヤは、主に香 油をぬり、頭髮にて御足を拭ひし者にして、病めるラザロはその兄弟なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, '姉妹ら人をイエスに遣して『主、視よ、なんぢの愛し給ふもの病めり』と言はしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, '之を聞きてイエス言ひ給ふ『この病は死に至らず、神の榮光のため、神の子のこれに由りて榮光を受けんためなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'イエスはマルタと、その姉妹と、ラザロとを愛し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'ラザロの病みたるを聞きて、その居給ひし處になほ二日とどまり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, '而してのち弟子たちに言ひ給ふ『われら復ユダヤに往くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, '弟子たち言ふ『ラビ、この程もユダヤ人、なんぢを石にて撃たんとせしに、復かしこに往き給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'イエス答へたまふ『一日に十二 時あるならずや、人もし晝あるかば、此の世の光を見るゆゑに躓くことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, '夜あるかば、光その人になき故に躓くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'かく言ひて復その後いひ給ふ『われらの友ラザロ眠れり、されど我よび起さん爲に往くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, '弟子たち言ふ『主よ、眠れるならば癒ゆべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'イエスは彼が死にたることを言ひ給ひしなれど、弟子たちは寢ねて眠れるを言ひ給ふと思へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'ここにイエス明白に言ひ給ふ『ラザロは死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, '我かしこに居らざりし事を汝 等のために喜ぶ、汝 等をして信ぜしめんとてなり。されど我ら今その許に往くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'デドモと稱ふるトマス、他の弟子たちに言ふ『われらも往きて彼と共に死ぬべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'さてイエス來り見 給へば、ラザロの墓にあること既に四日なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'ベタニヤはエルサレムに近くして、二 十 五 丁ばかりの距離なるが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, '數多のユダヤ人、マルタとマリヤとをその兄弟の事につき慰めんとて來れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'マルタはイエス來給ふと聞きて出で迎へたれど、マリヤはなほ家に坐し居たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'マルタ、イエスに言ふ『主よ、もし此處に在ししならば、我が兄弟は死なざりしものを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'されど今にても我は知る、何事を神に願ひ給ふとも、神は與へ給はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'イエス言ひ給ふ『なんぢの兄弟は甦へるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'マルタ言ふ『をはりの日、復活のときに甦へるべきを知る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'イエス言ひ給ふ『我は復活なり、生命なり、我を信ずる者は死ぬとも生きん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, '凡そ生きて我を信ずる者は、永遠に死なざるべし。汝これを信ずるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, '彼いふ『主よ然り、我なんぢは世に來るべきキリスト、神の子なりと信ず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'かく言ひて後、ゆきて竊にその姉妹マリヤを呼びて『師きたりて汝を呼びたまふ』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'マリヤ之をきき、急ぎ起ちて御許に往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'イエスは未だ村に入らず、尚マルタの迎へし處に居給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'マリヤと共に家に居りて慰め居たるユダヤ人、その急ぎ立ちて出でゆくを見、かれは歎かんとて墓に往くと思ひて後に隨へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'かくてマリヤ、イエスの居給ふ處にいたり、之を見てその足下に伏し『主よ、もし此處に在ししならば、我が兄弟は死なざりしものを』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'イエスかれが泣き居り、共に來りしユダヤ人も泣き居るを見て、心を傷め悲しみて言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, '『かれを何處に置きしか』彼ら言ふ『主よ、來りて見 給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'イエス涙をながし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'ここにユダヤ人ら言ふ『視よ、いかばかり彼を愛せしぞや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'その中の或 者ども言ふ『盲人の目をあけし此の人にして、彼を死なざらしむること能はざりしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'イエスまた心を傷めつつ墓にいたり給ふ。墓は洞にして石を置きて塞げり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'イエス言ひ給ふ『石を除けよ』死にし人の姉妹マルタ言ふ『主よ、彼ははや臭し、四日を經たればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'イエス言ひ給ふ『われ汝に、もし信ぜば神の榮光を見んと言ひしにあらずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'ここに人々 石を除けたり。イエス目を擧げて言ひたまふ『父よ、我にきき給ひしを謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, '常にきき給ふを我は知る。然るに斯く言ふは、傍らに立つ群衆の爲にして、汝の我を遣し給ひしことを之に信ぜしめんとてなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, '斯く言ひてのち、聲 高く『ラザロよ、出で來れ』と呼はり給へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, '死にしもの布にて足と手とを卷かれたるまま出で來る、顏も手拭にて包まれたり。イエス『これを解きて往かしめよ』と言ひ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'かくてマリヤの許に來りて、イエスの爲し給ひし事を見たる多くのユダヤ人、かれを信じたりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, '或 者はパリサイ人に往きて、イエスの爲し給ひし事を告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'ここに祭司長・パリサイ人ら議會を開きて言ふ『われら如何に爲すべきか、此の人おほくの徴を行ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'もし彼をこのまま捨ておかば、人々みな彼を信ぜん、而してロマ人きたりて、我らの土地と國人とを奪はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'その中の一人にて此の年の大 祭司なるカヤパ言ふ『なんぢら何をも知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'ひとりの人、民のために死にて、國人すべての滅びぬは、汝らの益なるを思はぬなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'これは己より云へるに非ず、この年の大 祭司なれば、イエスの國人のため、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, '又ただに國人の爲のみならず、散りたる神の子らを一つに集めん爲に死に給ふことを預言したるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, '彼 等この日よりイエスを殺さんと議れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'されば此の後イエス顯にユダヤ人のなかを歩み給はず、此處を去りて、荒野にちかき處なるエフライムといふ町に往き、弟子たちと偕に其處に留りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'ユダヤ人の過越の祭 近づきたれば、多くの人々 身を潔めんとて、祭のまへに田舍よりエルサレムに上れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, '彼らイエスをたづね、宮に立ちて互に言ふ『なんぢら如何に思ふか、彼は祭に來らぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, '祭司長・パリサイ人らは、イエスを捕へんとて、その在處を知る者あらば、告げ出づべく預て命令したりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, '過越の祭の六日 前に、イエス、ベタニヤに來り給ふ、ここは死人の中より甦へらせ給ひしラザロの居る處なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, '此處にてイエスのために饗宴を設け、マルタは事へ、ラザロはイエスと共に席に著ける者の中にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'マリヤは價 高き混りなきナルドの香 油 一斤を持ち來りて、イエスの御足にぬり、己が頭髮にて御足を拭ひしに、香 油のかをり家に滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, '御弟子の一人にて、イエスを賣らんとするイスカリオテのユダ言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '『何ぞこの香 油を三 百デナリに賣りて、貧しき者に施さざる』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'かく云へるは貧しき者を思ふ故にあらず、おのれ盜人にして、財嚢を預り、その中に納むる物を掠めゐたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'イエス言ひ給ふ『この女の爲すに任せよ、我が葬りの日のために之を貯へたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, '貧しき者は常に汝らと偕に居れども、我は常に居らぬなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'ユダヤの多くの民ども、イエスの此處に居給ふことを知りて來る、これはイエスの爲のみにあらず、死人の中より甦へらせ給ひしラザロを見んとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'かくて祭司長ら、ラザロをも殺さんと議る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, '彼のために多くのユダヤ人さり往きてイエスを信ぜし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, '明くる日、祭に來りし多くの民ども、イエスのエルサレムに來り給ふをきき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, '棕梠の枝をとりて出で迎へ、『「ホサナ、讃むべきかな、主の御名によりて來る者」イスラエルの王』と呼はる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'イエスは小驢馬を得て之に乘り給ふ。これは録して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '『シオンの娘よ、懼るな。視よ、なんぢの王は驢馬の子に乘りて來り給ふ』と有るが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, '弟子たちは最初これらの事を悟らざりしが、イエスの榮光を受け給ひし後に、これらの事のイエスに就きて録されたると、人々が斯く爲ししとを思ひ出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'ラザロを墓より呼び起し、死人の中より甦へらせ給ひし時に、イエスと偕に居りし群衆、證をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, '群衆のイエスを迎へたるは、かかる徴を行ひ給ひしことを聞きたるに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'パリサイ人ら互に言ふ『見るべし、汝らの謀ることの益なきを。視よ、世は彼に從へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, '禮拜せんとて祭に上りたる者の中に、ギリシヤ人 數人ありしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'ガリラヤなるベツサイダのピリポに來り、請ひて言ふ『君よ、われらイエスに謁えんことを願ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'ピリポ往きてアンデレに告げ、アンデレとピリポと共に往きてイエスに告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'イエス答へて言ひ給ふ『人の子の榮光を受くべき時きたれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, '誠にまことに汝らに告ぐ、一粒の麥、地に落ちて死なずば、唯一つにて在らん、もし死なば、多くの果を結ぶべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, '己が生命を愛する者は、これを失ひ、この世にてその生命を憎む者は、之を保ちて永遠の生命に至るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, '人もし我に事へんとせば、我に從へ、わが居る處に我に事ふる者もまた居るべし。人もし我に事ふることをせば、我が父これを貴び給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, '今わが心さわぐ、われ何を言ふべきか。父よ、この時より我を救ひ給へ、されど我この爲にこの時に到れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, '父よ、御名の榮光をあらはし給へ』ここに天より聲いでて言ふ『われ既に榮光をあらはしたり、復さらに顯さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, '傍らに立てる群衆これを聞きて『雷霆 鳴れり』と言ひ、ある人々は『御使かれに語れるなり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'イエス答へて言ひ給ふ『この聲の來りしは、我が爲にあらず、汝らの爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, '今この世の審判は來れり、今この世の君は逐ひ出さるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, '我もし地より擧げられなば、凡ての人をわが許に引きよせん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'かく言ひて、己が如何なる死にて死ぬるかを示し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, '群衆こたふ『われら律法によりて、キリストは永遠に存へ給ふと聞きたるに、汝いかなれば人の子は擧げらるべしと言ふか、その人の子とは誰なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'イエス言ひ給ふ『なほ暫し光は汝らの中にあり、光のある間に歩みて、暗黒に追及かれぬやうにせよ、暗き中を歩む者は往方を知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, '光の子とならんために、光のある間に光を信ぜよ』イエス此 等のことを語りてのち、彼らを避けて隱れ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'かく多くの徴を人々の前におこなひ給ひたれど、なほ彼を信ぜざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'これ預言者イザヤの言の成就せん爲なり。曰く『主よ、我らに聞きたる言を誰か信ぜし。主の御腕は誰にあらはれし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, '彼らが信じ得ざりしは此の故なり。即ちイザヤまた云へらく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '『彼らの眼を暗くし、心を頑固にし給へり。これ目にて見、心にて悟り、ひるがへりて、我に醫さるる事なからん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'イザヤの斯く云へるは、その榮光を見し故にて、イエスに就きて語りしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'されど司たちの中にもイエスを信じたるもの多かりしが、パリサイ人の故によりて言ひ顯すことをせざりき、除名せられん事を恐れたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, '彼らは神の譽よりも人の譽を愛でしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'イエス呼はりて言ひ給ふ『われを信ずる者は我を信ずるにあらず、我を遣し給ひし者を信じ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, '我を見る者は我を遣し給ひし者を見るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, '我は光として世に來れり、すべて我を信ずる者の暗黒に居らざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, '人たとひ我が言をききて守らずとも、我は之を審かず。夫わが來りしは世を審かん爲にあらず、世を救はん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, '我を棄て我が言を受けぬ者を審く者あり、わが語れる言こそ終の日に之を審くなれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, '我はおのれに由りて語れるにあらず、我を遣し給ひし父みづから、我が言ふべきこと語るべきことを命じ給ひし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, '我その命令の永遠の生命たるを知る。されば我は語るに我が父の我に言ひ給ふままを語るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, '過越のまつりの前に、イエスこの世を去りて父に往くべき己が時の來れるを知り、世に在る己の者を愛して、極まで之を愛し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, '夕餐のとき、惡魔 早くもシモンの子イスカリオテのユダの心に、イエスを賣らんとする思を入れたるが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'イエス父が萬物をおのが手にゆだね給ひしことと、己の神より出でて神に到ることを知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, '夕餐より起ちて上衣をぬぎ、手巾をとりて腰にまとひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, '尋で盥に水をいれて、弟子たちの足をあらひ、纏ひたる手巾にて之を拭ひはじめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'かくてシモン・ペテロに至り給へば、彼いふ『主よ、汝わが足を洗ひ給ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'イエス答へて言ひ給ふ『わが爲すことを汝いまは知らず、後に悟るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'ペテロ言ふ『永遠に我が足をあらひ給はざれ』イエス答へ給ふ『我もし汝を洗はずば、汝われと關係なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'シモン・ペテロ言ふ『主よ、わが足のみならず、手をも頭をも』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'イエス言ひ給ふ『すでに浴したる者は足のほか洗ふを要せず、全身きよきなり。斯く汝らは潔し、されど悉とくは然らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'これ己を賣る者の誰なるを知りたまふ故に『ことごとくは潔からず』と言ひ給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, '彼らの足をあらひ、己が上衣をとり、再び席につきて後いひ給ふ『わが汝らに爲したることを知るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'なんぢら我を師また主ととなふ、然か言ふは宜なり、我は是なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, '我は主また師なるに、尚なんぢらの足を洗ひたれば、汝らも互に足を洗ふべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'われ汝らに模範を示せり、わが爲ししごとく汝らも爲さんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, '誠にまことに汝らに告ぐ、僕はその主よりも大ならず。遣されたる者は之を遣す者よりも大ならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, '汝 等これらの事を知りて之を行はば幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'これ汝ら凡ての者につきて言ふにあらず、我はわが選びたる者どもを知る。されど聖書に「我とともにパンを食ふ者、われに向ひて踵を擧げたり」と云へることは、必ず成就すべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, '今その事の成らぬ前に之を汝らに告ぐ、事の成らん時、わが夫なるを汝らの信ぜんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, '誠にまことに汝らに告ぐ、わが遣す者を受くる者は我をうくるなり。我を受くる者は我を遣し給ひし者を受くるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'イエス此 等のことを言ひ終へて、心さわぎ證をなして言ひ給ふ『まことに誠に汝らに告ぐ、汝らの中の一人われを賣らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, '弟子たち互に顏を見 合せ、誰につきて言ひ給ふかを訝る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'イエスの愛したまふ一人の弟子、イエスの御胸によりそひ居たれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'シモン・ペテロ首にて示し『誰のことを言ひ給ふか、告げよ』といふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, '彼そのまま御胸によりかかりて『主よ、誰なるか』と言ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'イエス答へ給ふ『わが一撮の食物を浸して與ふる者は夫なり』かくて一撮の食物を浸して、シモンの子イスカリオテのユダに與へたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'ユダ一撮の食物を受くるや、惡魔かれに入りたり。イエス彼に言ひたまふ『なんぢが爲すことを速かに爲せ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, '席に著きゐたる者は一人として、何 故かく言ひ給ふかを知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'ある人々は、ユダが財嚢を預るによりて『祭のために要する物を買へ』とイエスの言ひ給へるか、また貧しき者に何か施さしめ給ふならんと思へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'ユダ一撮の食物を受くるや、直ちに出づ、時は夜なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'ユダの出でし後、イエス言ひ給ふ『今や人の子、榮光をうく、神も彼によりて榮光をうけ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, '神かれに由りて榮光をうけ給はば、神も己によりて彼に榮光を與へ給はん、直ちに與へ給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, '若子よ、我なほ暫く汝らと偕にあり、汝らは我を尋ねん、されど曾てユダヤ人に「なんぢらは我が往く處に來ること能はず」と言ひし如く、今 汝らにも然か言ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'われ新しき誡命を汝らに與ふ、なんぢら相 愛すべし。わが汝らを愛せしごとく、汝らも相 愛すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, '互に相 愛する事をせば、之によりて人みな汝らの我が弟子たるを知らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'シモン・ペテロ言ふ『主よ、何處にゆき給ふか』イエス答へ給ふ『わが往く處に、なんぢ今は從ふこと能はず。されど後に從はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'ペテロ言ふ『主よ、いま從ふこと能はぬは何 故ぞ、我は汝のために生命を棄てん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'イエス答へ給ふ『なんぢ我がために生命を棄つるか、誠にまことに汝に告ぐ、なんぢ三度われを否むまでは、鷄 鳴かざるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '『なんぢら心を騷がすな、神を信じ、また我を信ぜよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'わが父の家には住處おほし、然らずば我かねて汝らに告げしならん。われ汝 等のために處を備へに往く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'もし往きて汝らの爲に處を備へば、復きたりて汝らを我がもとに迎へん、わが居るところに汝らも居らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, '汝らは我が往くところに至る道を知る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'トマス言ふ『主よ、何處にゆき給ふかを知らず、いかでその道を知らんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'イエス彼に言ひ給ふ『われは道なり、眞理なり、生命なり、我に由らでは誰にても父の御許にいたる者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, '汝 等もし我を知りたらば、我が父をも知りしならん。今より汝ら之を知る、既に之を見たり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'ピリポ言ふ『主よ、父を我らに示し給へ、さらば足れり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'イエス言ひ給ふ『ピリポ、我かく久しく汝らと偕に居りしに、我を知らぬか。我を見し者は父を見しなり、如何なれば「我らに父を示せ」と言ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, '我の父に居り、父の我に居給ふことを信ぜぬか。わが汝 等にいふ言は、己によりて語るにあらず、父われに在して御業をおこなひ給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'わが言ふことを信ぜよ、我は父にをり、父は我に居給ふなり。もし信ぜずば、我が業によりて信ぜよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, '誠にまことに汝らに告ぐ、我を信ずる者は我がなす業をなさん、かつ之よりも大なる業をなすべし、われ父に往けばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, '汝らが我が名によりて願ふことは、我みな之を爲さん、父、子によりて榮光を受け給はんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, '何事にても我が名によりて我に願はば、我これを成すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, '汝 等もし我を愛せば、我が誡命を守らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'われ父に請はん、父は他に助主をあたへて、永遠に汝らと偕に居らしめ給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'これは眞理の御靈なり、世はこれを受くること能はず、これを見ず、また知らぬに因る。なんぢらは之を知る、彼は汝らと偕に居り、また汝らの中に居給ふべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, '我なんぢらを遣して孤兒とはせず、汝らに來るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, '暫くせば世は復われを見ず、されど汝らは我を見る、われ活くれば汝らも活くべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'その日には、我わが父に居り、なんぢら我に居り、われ汝らに居ることを汝ら知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'わが誡命を保ちて之を守るものは、即ち我を愛する者なり。我を愛する者は我が父に愛せられん、我も之を愛し、之に己を顯すべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'イスカリオテならぬユダ言ふ『主よ、何 故おのれを我らに顯して、世には顯し給はぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'イエス答へて言ひ給ふ『人もし我を愛せば、わが言を守らん、わが父これを愛し、かつ我等その許に來りて住處を之とともにせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, '我を愛せぬ者は、わが言を守らず。汝らが聞くところの言は、わが言にあらず、我を遣し給ひし父の言なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, '此 等のことは我なんぢらと偕にありて語りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, '助主すなはちわが名によりて父の遣したまふ聖 靈は、汝らに萬の事ををしへ、又すべて我が汝らに言ひしことを思ひ出さしむべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'われ平安を汝らに遺す、わが平安を汝らに與ふ。わが與ふるは世の與ふる如くならず、なんぢら心を騷がすな、また懼るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, '「われ往きて汝らに來るなり」と云ひしを汝ら既に聞けり。もし我を愛せば、父にわが往くを喜ぶべきなり、父は我よりも大なるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, '今その事の成らぬ前に、これを汝らに告げたり、事の成らんとき汝らの信ぜんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, '今より後われ汝らと多く語らじ、この世の君きたる故なり。彼は我に對して何の權もなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'されど斯くなるは、我の、父を愛し、父の命じ給ふところに遵ひて行ふことを、世の知らん爲なり。起きよ、いざ此處を去るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '我は眞の葡萄の樹、わが父は農夫なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'おほよそ我にありて果を結ばぬ枝は、父これを除き、果を結ぶものは、いよいよ果を結ばせん爲に之を潔めたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, '汝らは既に潔し、わが語りたる言に因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, '我に居れ、さらば我なんぢらに居らん。枝もし樹に居らずば、自ら果を結ぶこと能はぬごとく、汝らも我に居らずば亦 然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, '我は葡萄の樹、なんぢらは枝なり。人もし我にをり、我また彼にをらば、多くの果を結ぶべし。汝ら我を離るれば、何事をも爲し能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, '人もし我に居らずば、枝のごとく外に棄てられて枯る、人々これを集め火に投げ入れて燒くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, '汝 等もし我に居り、わが言なんぢらに居らば、何にても望に隨ひて求めよ、さらば成らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'なんぢら多くの果を結ばば、わが父は榮光を受け給ふべし、而して汝 等わが弟子とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, '父の我を愛し給ひしごとく、我も汝らを愛したり、わが愛に居れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'なんぢら若しわが誡命をまもらば、我が愛にをらん、我わが父の誡命を守りて、その愛に居るがごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, '我これらの事を語りたるは、我が喜悦の汝らに在り、かつ汝らの喜悦の滿されん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'わが誡命は是なり、わが汝らを愛せしごとく互に相 愛せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, '人その友のために己の生命を棄つる、之より大なる愛はなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, '汝 等もし我が命ずる事をおこなはば、我が友なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, '今よりのち我なんぢらを僕といはず、僕は主人のなす事を知らざるなり。我なんぢらを友と呼べり、我が父に聽きし凡てのことを汝らに知らせたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, '汝ら我を選びしにあらず、我なんぢらを選べり。而して汝らの往きて果を結び、且その果の殘らんために、又おほよそ我が名によりて父に求むるものを、父の賜はんために汝らを立てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'これらの事を命ずるは、汝らの互に相 愛せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, '世もし汝らを憎まば、汝 等より先に我を憎みたることを知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, '汝 等もし世のものならば、世は己がものを愛するならん。汝らは世のものならず、我なんぢらを世より選びたり。この故に世は汝らを憎む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'わが汝らに「僕はその主人より大ならず」と告げし言をおぼえよ。人もし我を責めしならば、汝 等をも責め、わが言を守りしならば、汝らの言をも守らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'すべて此 等のことを我が名の故に汝らに爲さん、それは我を遣し給ひし者を知らぬに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'われ來りて語らざりしならば、彼ら罪なかりしならん。されど今はその罪いひのがるべき樣なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, '我を憎むものは我が父をも憎むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, '我もし誰もいまだ行はぬ事を彼らの中に行はざりしならば、彼ら罪なかりしならん。されど今ははや我をも我が父をも見たり、また憎みたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'これは彼らの律法に「ひとびと故なくして我を憎めり」と録したる言の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, '父の許より我が遣さんとする助主、すなはち父より出づる眞理の御靈のきたらんとき、我につきて證せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, '汝 等もまた初より我とともに在りたれば證するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '我これらの事を語りたるは、汝らの躓かざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, '人なんぢらを除名すべし、然のみならず、汝らを殺す者みな自ら神に事ふと思ふとき來らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'これらの事をなすは、父と我とを知らぬ故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, '我これらの事を語りたるは、時いたりて我が斯く言ひしことを汝らの思ひいでん爲なり。初より此 等のことを言はざりしは、我なんぢらと偕に在りし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, '今われを遣し給ひし者にゆく、然るに汝らの中、たれも我に「何處にゆく」と問ふ者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, '唯これらの事を語りしによりて、憂なんぢらの心にみてり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'されど、われ實を汝らに告ぐ、わが去るは汝らの益なり。我さらずば助主なんぢらに來らじ、我ゆかば之を汝らに遣さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'かれ來らんとき、世をして罪につき、義につき、審判につきて、過てるを認めしめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, '罪に就きてとは、彼ら我を信ぜぬに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, '義に就きてとは、われ父にゆき、汝ら今より我を見ぬに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, '審判に就きてとは、此の世の君さばかるるに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, '我なほ汝らに告ぐべき事あまたあれど、今なんぢら得 耐へず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'されど彼すなはち眞理の御靈きたらん時、なんぢらを導きて眞理をことごとく悟らしめん。かれ己より語るにあらず、凡そ聞くところの事を語り、かつ來らんとする事どもを汝らに示さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, '彼はわが榮光を顯さん、それは我がものを受けて汝らに示すべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'すべて父の有ち給ふものは我がものなり、此の故に我がものを受けて汝らに示さんと云へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, '暫くせば汝ら我を見ず、また暫くして我を見るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'ここに弟子たちのうち或 者たがひに言ふ『「暫くせば我を見ず、また暫くして我を見るべし」と言ひ、かつ「父に往くによりて」と言ひ給へるは、如何なることぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, '復いふ『この暫くとは如何なることぞ、我等その言ひ給ふところを知らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'イエスその問はんと思へるを知りて言ひ給ふ『なんぢら「暫くせば我を見ず、また暫くして我を見るべし」と我が言ひしを尋ねあふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, '誠にまことに汝らに告ぐ、なんぢらは泣き悲しみ、世は喜ばん。汝ら憂ふべし、然れどその憂は喜悦とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'をんな産まんとする時は憂あり、その期いたるに因りてなり。子を産みてのちは苦痛をおぼえず、世に人の生れたる喜悦によりてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, '斯く汝らも今は憂あり、されど我ふたたび汝らを見ん、その時なんぢらの心よろこぶべし、その喜悦を奪ふ者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'かの日には汝ら何事をも我に問ふまじ。誠にまことに汝らに告ぐ、汝 等のすべて父に求むる物をば、我が名によりて賜ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'なんぢら今までは何をも我が名によりて求めたることなし。求めよ、然らば受けん、而して汝らの喜悦みたさるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, '我これらの事を譬にて語りたりしが、また譬にて語らず、明白に父のことを汝らに告ぐるとき來らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'その日には汝 等わが名によりて求めん。我は汝らの爲に父に請ふと言はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, '父みづから汝らを愛し給へばなり。これ汝 等われを愛し、また我の父より出で來りしことを信じたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'われ父より出でて世にきたれり、また世を離れて父に往くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, '弟子たち言ふ『視よ、今は明白に語りて聊かも譬をいひ給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, '我ら今なんぢの知り給はぬ所なく、また人の汝に問ふを待ち給はぬことを知る。之によりて汝の神より出できたり給ひしことを信ず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'イエス答へ給ふ『なんぢら今、信ずるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, '視よ、なんぢら散されて各自おのが處にゆき、我をひとり遺すとき到らん、否すでに到れり。然れど我ひとり居るにあらず、父われと偕に在すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, '此 等のことを汝らに語りたるは、汝ら我に在りて平安を得んが爲なり。なんぢら世にありては患難あり、されど雄々しかれ。我すでに世に勝てり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'イエスこれらの事を語りはて、目を擧げ天を仰ぎて言ひ給ふ『父よ、時 來れり、子が汝の榮光を顯さんために、汝の子の榮光を顯したまへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, '汝より賜はりし凡ての者に、永遠の生命を與へしめんとて、萬民を治むる權威を子に賜ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, '永遠の生命は、唯一の眞の神にいます汝と、なんぢの遣し給ひしイエス・キリストとを知るにあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, '我に成さしめんとて汝の賜ひし業を成し遂げて、我は地上に汝の榮光をあらはせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, '父よ、まだ世のあらぬ前に、わが汝と偕にもちたりし榮光をもて、今 御前にて我に榮光あらしめ給へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, '世の中より我に賜ひし人々に、われ御名をあらはせり。彼らは汝の有なるを我に賜へり、而して彼らは汝の言を守りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, '今かれらは、凡て我に賜ひしものの汝より出づるを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, '我は我に賜ひし言を彼らに與へ、彼らは之を受け、わが汝より出でたるを眞に知り、なんぢの我を遣し給ひしことを信じたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, '我かれらの爲に願ふ、わが願ふは世のためにあらず、汝の我に賜ひたる者のためなり、彼らは即ち汝のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, '我がものは皆なんぢの有、なんぢの有は我がものなり、我かれらより榮光を受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, '今より我は世に居らず、彼らは世に居り、我は汝にゆく。聖なる父よ、我に賜ひたる汝の御名の中に彼らを守りたまへ。これ我等のごとく、彼らの一つとならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, '我かれらと偕にをる間、われに賜ひたる汝の御名の中に彼らを守り、かつ保護したり。其のうち一人だに亡びず、ただ亡の子のみ亡びたり、聖書の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, '今は我なんぢに往く、而して此 等のことを世に在りて語るは、我が喜悦を彼らに全からしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, '我は御言を彼らに與へたり、而して世は彼らを憎めり、我の世のものならぬごとく、彼らも世のものならぬに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'わが願ふは、彼らを世より取り給はんことならず、惡より免れさらせ給はんことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, '我の世のものならぬ如く、彼らも世のものならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, '眞理にて彼らを潔め別ちたまへ、汝の御言は眞理なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, '汝われを世に遣し給ひし如く、我も彼らを世に遣せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'また彼 等のために我は己を潔めわかつ、これ眞理にて彼らも潔め別たれん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, '我かれらの爲のみならず、その言によりて我を信ずる者のためにも願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'これ皆 一つとならん爲なり。父よ、なんぢ我に在し、我なんぢに居るごとく、彼らも我らに居らん爲なり、是なんぢの我を遣し給ひしことを世の信ぜん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, '我は汝の我に賜ひし榮光を彼らに與へたり、是われらの一つなる如く、彼らも一つとならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, '即ち我かれらに居り、汝われに在し、彼ら一つとなりて全くせられん爲なり、是なんぢの我を遣し給ひしことと、我を愛し給ふごとく彼らをも愛し給ふこととを、世の知らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, '父よ、望むらくは、我に賜ひたる人々の我が居るところに我と偕にをり、世の創の前より我を愛し給ひしによりて、汝の我に賜ひたる我が榮光を見んことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, '正しき父よ、げに世は汝を知らず、されど我は汝を知り、この者どもも汝の我を遣し給ひしことを知れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'われ御名を彼らに知らしめたり、復これを知らしめん。これ我を愛し給ひたる愛の、彼らに在りて、我も彼らに居らん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, '此 等のことを言ひ終へて、イエス弟子たちと偕にケデロンの小川の彼方に出でたまふ。彼処に園あり、イエス弟子たちとともども入り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'ここは弟子たちと屡々あつまり給ふ處なれば、イエスを賣るユダもこの處を知れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'かくてユダは一組の兵隊と祭司長・パリサイ人 等よりの下役どもとを受けて、炬火・燈火・武器を携へて此處にきたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'イエス己に臨まんとする事をことごとく知り、進みいでて彼らに言ひたまふ『誰を尋ぬるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, '答ふ『ナザレのイエスを』イエス言ひたまふ『我はそれなり』イエスを賣るユダも彼らと共に立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, '『我はそれなり』と言ひ給ひし時、かれら後退して地に倒れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'ここに再び『たれを尋ぬるか』と問ひ給へば『ナザレのイエスを』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'イエス答へ給ふ『われは夫なりと既に告げたり、我を尋ぬるならば此の人々の去るを容せ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'これさきに『なんぢの我に賜ひし者の中より、われ一人をも失はず』と言ひ給ひし言の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'シモン・ペテロ劍をもちたるが、之を拔き大 祭司の僕を撃ちて、その右の耳を斬り落す、僕の名はマルコスと云ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'イエス、ペテロに言ひたまふ『劍を鞘に收めよ、父の我に賜ひたる酒杯は、われ飮まざらんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'ここにかの兵隊・千卒長・ユダヤ人の下役ども、イエスを捕へて縛り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, '先づアンナスの許に曳き往く、アンナスはその年の大 祭司なるカヤパの舅なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'カヤパはさきにユダヤ人に、一人、民のために死ぬるは益なる事を勸めし者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'シモン・ペテロ及び他の一人の弟子、イエスに從ふ。この弟子は大 祭司に知られたる者なれば、イエスと共に大 祭司の庭に入りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'ペテロは門の外に立てり。ここに大 祭司に知られたる彼の弟子いでて、門を守る女に物 言ひてペテロを連れ入れしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, '門を守る婢女、ペテロに言ふ『なんぢも彼の人の弟子の一人なるか』かれ言ふ『然らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, '時 寒くして僕・下役ども炭火を熾し、その傍らに立ちて煖まり居りしに、ペテロも共に立ちて煖まりゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'ここに大 祭司、イエスにその弟子とその教とにつきて問ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'イエス答へ給ふ『われ公然に世に語れり、凡てのユダヤ人の相 集ふ會堂と宮とにて常に教へ、密には何をも語りし事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, '何ゆゑ我に問ふか、我が語れることは聽きたる人々に問へ。視よ、彼らは我が言ひしことを知るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'かく言ひ給ふとき、傍らに立つ下役の一人、手掌にてイエスを打ちて言ふ『かくも大 祭司に答ふるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'イエス答へ給ふ『わが語りし言もし惡しくば、その惡しき故を證せよ。善くば何とて打つぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'ここにアンナス、イエスを縛りたるままにて、大 祭司カヤパの許に送れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'シモン・ペテロ立ちて煖まり居たるに、人々いふ『なんぢも彼が弟子の一人なるか』否みて言ふ『然らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, '大 祭司の僕の一人にて、ペテロに耳を斬り落されし者の親族なるが言ふ『われ汝が園にて彼と偕なるを見しならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'ペテロまた否む折しも鷄 鳴きぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'かくて人々イエスをカヤパの許より官邸にひきゆく、時は夜明なり。彼ら過越の食をなさんために、汚穢を受けじとて己らは官邸に入らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'ここにピラト彼らの前に出でゆきて言ふ『この人に對して如何なる訴訟をなすか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, '答へて言ふ『もし惡をなしたる者ならずば汝に付さじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'ピラト言ふ『なんぢら彼を引取り、おのが律法に循ひて審け』ユダヤ人いふ『我らに人を殺す權威なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'これイエス、己が如何なる死にて死ぬるかを示して、言ひ給ひし御言の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'ここにピラトまた官邸に入り、イエスを呼び出して言ふ『なんぢはユダヤ人の王なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'イエス答へ給ふ『これは汝おのれより言ふか、將わが事を人の汝に告げたるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'ピラト答ふ『我はユダヤ人ならんや、汝の國人・祭司長ら汝を我に付したり、汝なにを爲ししぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'イエス答へ給ふ『わが國はこの世のものならず、若し我が國この世のものならば、我が僕ら我をユダヤ人に付さじと戰ひしならん。然れど我が國は此の世よりのものならず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'ここにピラト言ふ『されば汝は王なるか』イエス答へ給ふ『われの王たることは汝の言へるごとし。我は之がために生れ、之がために世に來れり、即ち眞理につきて證せん爲なり。凡て眞理に屬する者は我が聲をきく』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'ピラト言ふ『眞理とは何ぞ』かく言ひて再びユダヤ人の前に出でて言ふ『我この人に何の罪あるをも見ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, '過越のとき我なんぢらに一人の囚人を赦す例あり、されば汝らユダヤ人の王をわが赦さんことを望むか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, '彼らまた叫びて『この人ならず、バラバを』と言ふ、バラバは強盜なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'ここにピラト、イエスをとりて鞭うつ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, '兵卒ども茨にて冠冕をあみ、その首にかむらせ、紫色の上衣をきせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, '御許に進みて言ふ『ユダヤ人の王やすかれ』而して手掌にて打てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'ピラト再び出でて人々にいふ『視よ、この人を汝らに引 出す、これは何の罪あるをも我が見ぬことを汝らの知らん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'ここにイエス茨の冠冕をかむり、紫色の上衣をきて出で給へば、ピラト言ふ『視よ、この人なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, '祭司長・下役どもイエスを見て叫びいふ『十字架につけよ、十字架につけよ』ピラト言ふ『なんぢら自らとりて十字架につけよ、我は彼に罪あるを見ず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'ユダヤ人こたふ『我らに律法あり、その律法によれば死に當るべき者なり、彼はおのれを神の子となせり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'ピラトこの言をききて増々おそれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, '再び官邸に入りてイエスに言ふ『なんぢは何處よりぞ』イエス答をなし給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'ピラト言ふ『われに語らぬか、我になんぢを赦す權威あり、また十字架につくる權威あるを知らぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'イエス答へ給ふ『なんぢ上より賜はらずば、我に對して何の權威もなし。この故に我をなんぢに付しし者の罪は更に大なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'ここにおいてピラト、イエスを赦さんことを力む。されどユダヤ人さけびて言ふ『なんぢ若しこの人を赦さば、カイザルの忠臣にあらず、凡そおのれを王となす者はカイザルに叛くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'ピラトこれらの言をききて、イエスを外にひきゆき、敷石(ヘブル語にてガバタ)といふ處にて審判の座につく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'この日は過越の準備 日にて、時は第六時ごろなりき。ピラト、ユダヤ人にいふ『視よ、なんぢらの王なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'かれら叫びていふ『除け、除け、十字架につけよ』ピラト言ふ『われ汝らの王を十字架につくべけんや』祭司長ら答ふ『カイザルの他われらに王なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'ここにピラト、イエスを十字架に釘くるために彼らに付せり。彼らイエスを受取りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'イエス己に十字架を負ひて、髑髏(ヘブル語にてゴルゴダ)といふ處に出でゆき給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, '其處にて彼らイエスを十字架につく。又ほかに二人の者をともに十字架につけ、一人を右に、一人を左に、イエスを眞中に置けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'ピラト罪標を書きて十字架の上に掲ぐ『ユダヤ人の王、ナザレのイエス』と記したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'イエスを十字架につけし處は都に近ければ、多くのユダヤ人この標を讀む、標はヘブル、ロマ、ギリシヤの語にて記したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'ここにユダヤ人の祭司長らピラトに言ふ『ユダヤ人の王と記さず、我はユダヤ人の王なりと自稱せりと記せ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'ピラト答ふ『わが記したることは記したるままに』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, '兵卒どもイエスを十字架につけし後、その衣をとりて四つに分け、おのおの其の一つを得たり。また下衣を取りしが、下衣は縫目なく、上より惣て織りたる物なれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, '兵卒ども互にいふ『これを裂くな、誰がうるか鬮にすべし』これは聖書の成就せん爲なり。曰く『かれら互にわが衣をわけ、わが衣を鬮にせり』兵卒ども斯くなしたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'さてイエスの十字架の傍らには、その母と母の姉妹と、クロパの妻マリヤとマグダラのマリヤと立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'イエスその母とその愛する弟子との近く立てるを見て、母に言ひ給ふ『をんなよ、視よ、なんぢの子なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'また弟子に言ひたまふ『視よ、なんぢの母なり』この時より、その弟子かれを己が家に接けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'この後イエス萬の事の終りたるを知りて、――聖書の全うせられん爲に――『われ渇く』と言ひ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'ここに酸き葡萄酒の滿ちたる器あり、その葡萄酒のふくみたる海綿をヒソプに著けてイエスの口に差附く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'イエスその葡萄酒をうけて後いひ給ふ『事 畢りぬ』遂に首をたれて靈をわたし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'この日は準備 日なれば、ユダヤ人、安息 日に屍體を十字架のうへに留めおかじとて(殊にこの度の安息 日は大なる日なるにより)ピラトに、彼らの脛ををりて屍體を取除かんことを請ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'ここに兵卒ども來りて、イエスとともに十字架に釘けられたる第一の者と他のものとの脛を折り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, '而してイエスに來りしに、はや死に給ふを見て、その脛を折らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, '然るに一人の兵卒、鎗にてその脅をつきたれば、直ちに血と水と流れいづ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, '之を見しもの證をなす、其の證は眞なり、彼はその言ふことの眞なるを知る、これ汝 等にも信ぜしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, '此 等のことの成りたるは『その骨くだかれず』とある聖 句の成就せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'また他に『かれら己が刺したる者を見るべし』と云へる聖 句あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'この後、アリマタヤのヨセフとて、ユダヤ人を懼れ密にイエスの弟子たりし者、イエスの屍體を引 取らんことをピラトに請ひたれば、ピラト許せり、乃ち往きてその屍體を引取る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'また曾て夜 御許に來りしニコデモも、沒藥・沈香の混和物を百 斤ばかり携へて來る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'ここに彼らイエスの屍體をとり、ユダヤ人の葬りの習慣にしたがひて、香料とともに布にて卷けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'イエスの十字架につけられ給ひし處に園あり、園の中にいまだ人を葬りしことなき新しき墓あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'ユダヤ人の準備 日なれば、この墓の近きままに其處にイエスを納めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, '一週のはじめの日、朝まだき暗きうちに、マグダラのマリヤ墓にきたりて、墓より石の取除けあるを見る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, '乃ち走りゆき、シモン・ペテロとイエスの愛し給ひしかの弟子との許に到りて言ふ『たれか主を墓より取去れり、何處に置きしか我ら知らず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'ペテロと、かの弟子といでて墓にゆく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, '二人ともに走りたれど、かの弟子ペテロより疾く走りて先に墓にいたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, '屈みて布の置きたるを見れど、内には入らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'シモン・ペテロ後れ來り、墓に入りて布の置きたるを視、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'また首を包みし手拭は布とともに在らず、他のところに卷きてあるを見る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, '先に墓にきたれる彼の弟子もまた入り、之を見て信ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, '彼らは聖書に録したる、死人の中よりその甦へり給ふべきことを未だ悟らざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, '遂に二人の弟子おのが家にかへれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, '然れどマリヤは墓の外に立ちて泣き居りしが、泣きつつ屈みて墓の内を見るに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'イエスの屍體の置かれし處に、白き衣をきたる二人の御使、首の方にひとり足の方にひとり坐しゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, '而してマリヤに言ふ『をんなよ、何ぞ泣くか』マリヤ言ふ『誰かわが主を取去れり、何處に置きしか我しらず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'かく言ひて後に振反れば、イエスの立ち居給ふを見る、されどイエスたるを知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'イエス言ひ給ふ『をんなよ、何ぞ泣く、誰を尋ぬるか』マリヤは園守ならんと思ひて言ふ『君よ、汝もし彼を取去りしならば、何處に置きしかを告げよ、われ引取るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'イエス『マリヤよ』と言ひ給ふ。マリヤ振反りて『ラボニ』(釋けば師よ)と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'イエス言ひ給ふ『われに觸るな、我いまだ父の許に昇らぬ故なり。我が兄弟たちに往きて「我はわが父すなはち汝らの父、わが神すなはち汝らの神に昇る」といへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'マグダラのマリヤ往きて弟子たちに『われは主を見たり』と告げ、また云々の事を言ひ給ひしと告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'この日すなはち一週のはじめの日の夕、弟子たちユダヤ人を懼るるに因りて、居るところの戸を閉ぢおきしに、イエスきたり彼らの中に立ちて言ひたまふ『平安なんぢらに在れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, '斯く言ひてその手と脅とを見せたまふ、弟子たち主を見て喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'イエスまた言ひたまふ『平安なんぢらに在れ、父の我を遣し給へるごとく、我も亦なんぢらを遣す』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, '斯く言ひて、息を吹きかけ言ひたまふ『聖 靈をうけよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'なんじら誰の罪を赦すとも其の罪ゆるされ、誰の罪を留むるとも其の罪とどめらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'イエス來り給ひしとき、十二 弟子の一人デドモと稱ふるトマスともに居らざりしかば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, '他の弟子これに言ふ『われら主を見たり』トマスいふ『我はその手に釘の痕を見、わが指を釘の痕にさし入れ、わが手をその脅に差入るるにあらずば信ぜじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, '八日ののち弟子たちまた家にをり、トマスも偕に居りて戸を閉ぢおきしに、イエス來り、彼らの中に立ちて言ひたまふ『平安なんぢらに在れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'またトマスに言ひ給ふ『なんぢの指をここに伸べて、わが手を見よ、汝の手をのべて、我が脅にさしいれよ、信ぜぬ者とならで信ずる者となれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'トマス答へて言ふ『わが主よ、わが神よ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'イエス言ひ給ふ『なんぢ我を見しによりて信じたり、見ずして信ずる者は幸福なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'この書に録さざる外の多くの徴を、イエス弟子たちの前にて行ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'されど此 等の事を録ししは、汝 等をしてイエスの神の子キリストたることを信ぜしめ、信じて御名により生命を得しめんが爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'この後、イエス復テベリヤの海邊にて己を弟子たちに現し給ふ、その現れ給ひしこと左のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'シモン・ペテロ、デドモと稱ふるトマス、ガリラヤのカナのナタナエル、ゼベダイの子ら及びほかの弟子 二人もともに居りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'シモン・ペテロ『われ漁獵にゆく』と言へば、彼ら『われらも共に往かん』と言ひ、皆いでて舟に乘りしが、その夜は何をも得ざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, '夜明の頃イエス岸に立ち給ふに、弟子たち其のイエスなるを知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'イエス言ひ給ふ『子どもよ、獲 物ありしか』彼ら『なし』と答ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'イエス言ひたまふ『舟の右のかたに網をおろせ、然らば獲 物あらん』乃ち網を下したるに、魚おびただしくして、網を曳き上ぐること能はざりしかば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'イエスの愛し給ひし弟子、ペテロに言ふ『主なり』シモン・ペテロ『主なり』と聞きて、裸なりしを上衣をまとひて海に飛びいれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, '他の弟子たちは陸を離るること遠からず、僅に五十間ばかりなりしかば、魚の入りたる網を小舟にて曳き來り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, '陸に上りて見れば、炭火ありてその上に肴あり、又パンあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'イエス言ひ給ふ『なんぢらの今とりたる肴を少し持ちきたれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'シモン・ペテロ舟に往きて網を陸に曳き上げしに、百 五 十 三 尾の大なる魚 滿ちたり、斯く多かりしが網は裂けざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'イエス言ひ給ふ『きたりて食せよ』弟子たちその主なるを知れば『なんぢは誰ぞ』と敢へて問ふ者もなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'イエス進みてパンをとり彼らに與へ、肴をも然なし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'イエス死人の中より甦へりてのち、弟子たちに現れ給ひし事、これにて三度なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'かくて食したる後、イエス、シモン・ペテロに言ひ給ふ『ヨハネの子シモンよ、汝この者どもに勝りて我を愛するか』ペテロいふ『主よ、然り、わが汝を愛する事は、なんぢ知り給ふ』イエス言ひ給ふ『わが羔羊を養へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'また二度いひ給ふ『ヨハネの子シモンよ、我を愛するか』ペテロ言ふ『主よ、然り、わが汝を愛する事は、なんぢ、知り給ふ』イエス言ひ給ふ『わが羊を牧へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, '三度いひ給ふ『ヨハネの子シモンよ、我を愛するか』ペテロ三度『われを愛するか』と言ひ給ふを憂ひて言ふ『主よ、知りたまはぬ處なし、わが汝を愛する事は、なんぢ識りたまふ』イエス言ひ給ふ『わが羊をやしなへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'まことに誠になんぢに告ぐ、なんぢ若かりし時は自ら帶して欲する處を歩めり、されど老いては手を伸べて他の人に帶せられ、汝の欲せぬ處に連れゆかれん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'これペテロが如何なる死にて神の榮光を顯すかを示して言ひ給ひしなり。斯く言ひて後かれに言ひ給ふ『われに從へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'ペテロ振反りて、イエスの愛したまひし弟子の從ふを見る。これはさきに夕餐のとき御胸に倚りかかりて『主よ、汝を賣る者は誰か』と問ひし弟子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'ペテロこの人を見てイエスに言ふ『主よ、この人は如何に』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'イエス言ひ給ふ『よしや我、かれが我の來るまで留るを欲すとも、汝になにの關係あらんや、汝は我に從へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'ここに兄弟たちの中に、この弟子 死なずと云ふ話つたはりたり。されどイエスは死なずと言ひ給ひしにあらず『よしや我、かれが我の來るまで留るを欲すとも、汝になにの關係あらんや』と言ひ給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'これらの事につきて、證をなし、又これを録しし者は、この弟子なり、我等はその證の眞なるを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'イエスの行ひ給ひし事は、この外なほ多し、もし一つ一つ録さば、我おもふに世界もその録すところの書を載するに耐へざらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'テオピロよ、我さきに前の書をつくりて、凡そイエスの行ひはじめ教へはじめ給ひしより、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'その選び給へる使徒たちに、聖 靈によりて命じたるのち、擧げられ給ひし日に至るまでの事を記せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'イエスは苦難をうけしのち、多くの慥なる證をもて、己の活きたることを使徒たちに示し、四十 日の間、しばしば彼らに現れて、神の國のことを語り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'また彼 等とともに集りゐて命じたまふ『エルサレムを離れずして、我より聞きし父の約束を待て。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'ヨハネは水にてバプテスマを施ししが、汝らは日ならずして聖 靈にてバプテスマを施されん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, '弟子たち集れるとき問ひて言ふ『主よ、イスラエルの國を囘復し給ふは此の時なるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'イエス言ひたまふ『時また期は父おのれの權威のうちに置き給へば、汝らの知るべきにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, '然れど聖 靈なんぢらの上に臨むとき、汝ら能力をうけん、而してエルサレム、ユダヤ全國、サマリヤ、及び地の極にまで我が證人とならん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, '此 等のことを言ひ終りて、彼らの見るがうちに擧げられ給ふ。雲これを受けて見えざらしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'その昇りゆき給ふとき、彼ら天に目を注ぎゐたりしに、視よ、白き衣を著たる二人の人かたはらに立ちて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, '『ガリラヤの人々よ、何ゆゑ天を仰ぎて立つか、汝らを離れて天に擧げられ給ひし此のイエスは、汝らが天に昇りゆくを見たるその如く復きたり給はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'ここに彼 等オリブといふ山よりエルサレムに歸る。この山はエルサレムに近く、安息 日の道程なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, '既に入りてその留りをる高樓に登る。ペテロ、ヨハネ、ヤコブ及びアンデレ、ピリポ及びトマス、バルトロマイ及びマタイ、アルパヨの子ヤコブ、熱心 黨のシモン及びヤコブの子ユダなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'この人々はみな女たち及びイエスの母マリヤ、イエスの兄弟たちと共に、心を一つにして只管いのりを務めゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'その頃ペテロ、百二十 名ばかり共に集りて群をなせる兄弟たちの中に立ちて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '『兄弟たちよ、イエスを捕ふる者どもの手引となりしユダにつきて、聖 靈ダビデの口によりて預じめ言ひ給ひし聖書は、かならず成就せざるを得ざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, '彼は我らの中に數へられ、此の務に與りたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, '(この人は、かの不義の價をもて地所を得、また俯伏に墜ちて直中より裂けて臓腑みな流れ出でたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'この事エルサレムに住む凡ての人に知られて、その地所は國語にてアケルダマと稱へらる、血の地所との義なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'それは詩 篇に録して「彼の住處は荒れ果てよ、人その中に住はざれ」と云ひ、又「その職はほかの人に得させよ」と云ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, '然れば主イエス我等のうちに往來し給ひし間、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, '即ちヨハネのバプテスマより始り、我らを離れて擧げられ給ひし日に至るまで、常に我らと偕に在りし此の人々のうち一人、われらと共に主の復活の證人となるべきなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'ここにバルサバと稱へられ、またの名をユストと呼ばるるヨセフ及びマツテヤの二人をあげ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, '祈りて言ふ『凡ての人の心を知りたまふ主よ、ユダ己が所に往かんとて此の務と使徒の職とより墮ちたれば、その後を繼がするに、此の二人のうち孰を選び給ふか示したまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, '祈りて言ふ『凡ての人の心を知りたまふ主よ、ユダ己が所に往かんとて此の務と使徒の職とより墮ちたれば、その後を繼がするに、此の二人のうち孰を選び給ふか示したまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'かくて鬮せしに、鬮はマツテヤに當りたれば、彼は十 一の使徒に加へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, '五旬節の日となり、彼らみな一處に集ひ居りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, '烈しき風の吹ききたるごとき響、にはかに天より起りて、その坐する所の家に滿ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'また火の如きもの舌のやうに現れ、分れて各人の上にとどまる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, '彼らみな聖 靈にて滿され、御靈の宣べしむるままに異邦の言にて語りはじむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, '時に敬虔なるユダヤ人ら、天下の國々より來りてエルサレムに住み居りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'この音おこりたれば群衆あつまり來り、おのおの己が國語にて使徒たちの語るを聞きて騷ぎ合ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'かつ驚き怪しみて言ふ『視よ、この語る者は皆ガリラヤ人ならずや、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, '如何にして我等おのおのの生れし國の言をきくか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, '我等はパルテヤ人、メヂヤ人、エラム人、またメソポタミヤ、ユダヤ、カパドキヤ、ポント、アジヤ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'フルギヤ、パンフリヤ、エジプト、リビヤのクレネに近き地方などに住む者、ロマよりの旅人――ユダヤ人および改宗者――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'クレテ人およびアラビヤ人なるに、我が國語にて彼らが神の大なる御業をかたるを聞かんとは』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'みな驚き惑ひて互に言ふ『これ何事ぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, '或 者どもは嘲りて言ふ『かれらは甘き葡萄酒にて滿されたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'ここにペテロ十 一の使徒とともに立ち、聲を揚げ宣べて言ふ『ユダヤの人々および凡てエルサレムに住める者よ、汝 等わが言に耳を傾けて、この事を知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, '今は朝の九時なれば、汝らの思ふごとく彼らは醉ひたるに非ず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'これは預言者ヨエルによりて言はれたる所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '「神いひ給はく、末の世に至りて、我が靈を凡ての人に注がん。汝らの子 女は預言し、汝らの若者は幻影を見、なんぢらの老人は夢を見るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'その世に至りて、わが僕・婢女にわが靈を注がん、彼らは預言すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'われ上は天に不思議を、下は地に徴をあらはさん、即ち血と火と煙の氣とあるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, '主の大なる顯著しき日のきたる前に、日は闇に月は血に變らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'すべて主の御名を呼び頼む者は救はれん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'イスラエルの人々よ、これらの言を聽け。ナザレのイエスは、汝らの知るごとく、神かれに由りて汝らの中に行ひ給ひし能力ある業と不思議と徴とをもて、汝らに證し給へる人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'この人は神の定め給ひし御旨と、預じめ知り給ふ所とによりて付されしが、汝ら不法の人の手をもて釘磔にして殺せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, '然れど神は死の苦難を解きて之を甦へらせ給へり。彼は死に繋がれをるべき者ならざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'ダビデ彼につきて言ふ「われ常に我が前に主を見たり、我が動かされぬ爲に我が右に在せばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'この故に我が心は樂しみ、我が舌は喜べり、かつ我が肉體もまた望の中に宿らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, '汝わが靈魂を黄泉に棄て置かず、汝の聖者の朽果つることを許し給はざればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, '汝は生命の道を我に示し給へり、御顏の前にて我に勸喜を滿し給はん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, '兄弟たちよ、先祖ダビデに就きて、われ憚らず汝らに言ふを得べし、彼は死にて葬られ、その墓は今日に至るまで我らの中にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, '即ち彼は預言者にして、己の身より出づる者をおのれの座位に坐せしむることを、誓をもて神の約し給ひしを知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, '先見して、キリストの復活に就きて語り、その黄泉に棄て置かれず、その肉體の朽果てぬことを言へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, '神はこのイエスを甦へらせ給へり、我らは皆その證人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'イエスは神の右に擧げられ、約束の聖 靈を父より受けて、汝らの見 聞する此のものを注ぎ給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'それダビデは天に昇りしことなし、然れど自ら言ふ「主わが主に言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, '我なんぢの敵を汝の足臺となすまでは、わが右に坐せよ」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, '然ればイスラエルの全家は確と知るべきなり。汝らが十字架に釘けし此のイエスを、神は立てて主となし、キリストとなし給へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, '人々これを聞きて心を刺され、ペテロと他の使徒たちとに言ふ『兄弟たちよ、我ら何をなすべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'ペテロ答ふ『なんぢら悔改めて、おのおの罪の赦を得んために、イエス・キリストの名によりてバプテスマを受けよ、然らば聖 靈の賜物を受けん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'この約束は汝らと汝らの子らと、凡ての遠き者すなはち主なる我らの神の召し給ふ者とに屬くなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'この他なほ多くの言をもて證し、かつ勸めて『この曲れる代より救ひ出されよ』と言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'かくてペテロの言を聽納れし者はバプテスマを受く。この日、弟子に加はりたる者、おほよそ三 千 人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, '彼らは使徒たちの教を受け、交際をなし、パンを擘き、祈祷をなすことを只管つとむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'ここに人みな敬畏を生じ、多くの不思議と徴とは使徒たちに由りて行はれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, '信じたる者はみな偕に居りて諸般の物を共にし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, '資産と所有とを賣り、各人の用に從ひて分け與へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, '日々、心を一つにして弛みなく宮に居り、家にてパンをさき、勸喜と眞心とをもて食事をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, '神を讃美して一般の民に悦ばる。かくて主は救はるる者を日々かれらの中に加へ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, '晝の三時いのりの時に、ペテロとヨハネと宮に上りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'ここに生れながらの跛者かかれて來る。宮に入る人より施濟を乞ふために、日々 宮の美麗といふ門に置かるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'ペテロとヨハネとの宮に入らんとするを見て施濟を乞ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'ペテロ、ヨハネと共に目を注めて『我らを見よ』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'かれ何をか受くるならんと、彼らを見つめたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'ペテロ言ふ『金 銀は我になし、然れど我に有るものを汝に與ふ、ナザレのイエス・キリストの名によりて歩め』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, '乃ち右の手を執りて起ししに、足の甲と踝骨とたちどころに強くなりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, '躍り立ち歩み出して、且あゆみ且をどり、神を讃美しつつ彼らと共に宮に入れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, '民みな其の歩み、また神を讃美するを見て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, '彼が前に乞食にて宮の美麗 門に坐しゐたるを知れば、この起りし事に就きて驚駭と奇異とに充ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'かくて彼がペテロとヨハネとに取りすがり居るほどに、民みな甚だしく驚きてソロモンの廊と稱ふる廊に馳せつどふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'ペテロこれを見て民に答ふ『イスラエルの人々よ、何ぞ此の事を怪しむか、何ぞ我らが己の能力と敬虔とによりて此の人を歩ませしごとく、我らを見つむるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'アブラハム、イサク、ヤコブの神、われらの先祖の神は、その僕イエスに榮光あらしめ給へり。汝 等このイエスを付し、ピラトの之を釋さんと定めしを、其の前にて否みたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, '汝らは、この聖者・義人を否みて、殺人者を釋さんことを求め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, '生命の君を殺したれど、神はこれを死人の中より甦へらせ給へり、我らは其の證人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, '斯くてその御名を信ずるに因りてその御名は、汝らの見るところ識るところの此の人を健くしたり。イエスによる信仰は、汝 等もろもろの前にて斯かる全癒を得させたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, '兄弟よ、われ知る、汝らが、かの事を爲ししは知らぬに因りてなり。汝らの司たちも亦 然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, '然れど神は凡ての預言者の口をもて、キリストの苦難を受くべきことを預じめ告げ給ひしを、斯くは成就し給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, '然れば汝ら罪を消されん爲に、悔改めて心を轉ぜよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'これ主の御前より慰安の時きたり、汝らの爲に預じめ定め給へるキリスト・イエスを遣し給はんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, '古へより神が、その聖なる預言者の口によりて語り給ひし、萬物の革まる時まで、天は必ずイエスを受けおくべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'モーセ云へらく「主なる神は汝らの兄弟の中より我がごとき預言者を起し給はん。その語る所のことは汝 等ことごとく聽くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, '凡てこの預言者に聽かぬ者は民の中より滅し盡さるべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, '又サムエル以來かたりし預言者も、皆この時につきて宣傳へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, '汝らは預言者たちの子孫なり、又なんぢらの先祖たちに神の立て給ひし契約の子孫なり、即ち神アブラハムに告げ給はく「なんぢの裔によりて地の諸族はみな祝福せらるべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, '神はその僕を甦へらせ、まづ汝らに遣し給へり、これ汝ら各人を、その罪より呼びかへして祝福せん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'かれら民に語り居るとき、祭司ら・宮守頭およびサドカイ人ら近づき來りて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'その民を教へ、又イエスの事を引きて死人の中よりの復活を宣ぶるを憂ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, '手をかけて之を捕へしに、はや夕になりたれば、明くる日まで留置場に入れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, '然れど、その言を聽きたる人々の中にも信ぜし者おほくありて、男の數おほよそ五 千 人となりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, '明くる日、司・長老・學者らエルサレムに會し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, '大 祭司アンナス、カヤパ、ヨハネ、アレキサンデル及び大 祭司の一族みな集ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'その中にかの二人を立てて問ふ『如何なる能力いかなる名によりて此の事を行ひしぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'この時ペテロ聖 靈にて滿され、彼らに言ふ『民の司たち及び長老たちよ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, '我らが病める者になしし善き業に就き、その如何にして救はれしかを今日もし訊さるるならば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, '汝ら一同およびイスラエルの民みな知れ、この人の健かになりて汝らの前に立つは、ナザレのイエス・キリスト、即ち汝らが十字架に釘け、神が死人の中より甦へらせ給ひし者の名に頼ることを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'このイエスは汝ら造家者に輕しめられし石にして、隅の首石となりたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, '他の者によりては救を得ることなし、天の下には我らの頼りて救はるべき他の名を、人に賜ひし事なければなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, '彼らはペテロとヨハネとの臆することなきを見、その無學の凡人なるを知りたれば、之を怪しみ、且そのイエスと偕にありし事を認む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'また醫されたる人の之とともに立つを見るによりて、更に言ひ消す辭なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'ここに、命じて彼らを衆議所より退け、相 共に議りて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, '『この人々を如何にすべきぞ。彼 等によりて顯著しき徴の行はれし事は、凡てエルサレムに住む者に知られ、我ら之を否むこと能はねばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, '然れど愈々ひろく民の中に言ひ弘らぬやうに、彼らを脅かして、今より後かの名によりて誰にも語る事なからしめん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, '乃ち彼らを呼び、一切イエスの名によりて語り、また教へざらんことを命じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'ペテロとヨハネと答へていふ『神に聽くよりも汝らに聽くは、神の御前に正しきか、汝ら之を審け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, '我らは見しこと聽きしことを語らざるを得ず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, '民みな此の有りし事に就きて神を崇めたれば、彼らを罰するに由なく、更にまた脅かして釋せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'かの徴によりて醫されし人は四十歳 餘なりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, '彼ら釋されて、その友の許にゆき、祭司長・長老らの言ひし凡てのことを告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, '之を聞きて皆 心を一つにし、神に對ひ、聲を揚げて言ふ『主よ、汝は天と地と海と、其の中のあらゆる物とを造り給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, '曾て聖 靈によりて、汝の僕われらの先祖ダビデでの口をもて「何ゆゑ異邦人は騷ぎ立ち、民らは空しき事を謀るぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, '世の王たちは共に立ち、司らは一つにあつまりて、主および其のキリストに逆ふ」と宣給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, '果してヘロデとポンテオ・ピラトとは、異邦人およびイスラエルの民 等とともに、汝の油そそぎ給ひし聖なる僕イエスに逆ひて、此の都にあつまり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, '御手と御旨とにて、斯く成るべしと預じめ定め給ひし事をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, '主よ、今かれらの脅喝を御覽し、僕らに御言を聊かも臆することなく語らせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, '御手をのべて醫を施させ、汝の聖なる僕イエスの名によりて、徴と不思議とを行はせ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, '祈り終へしとき、其の集りをる處ふるひ動き、みな聖 靈にて滿され、臆することなく神の御言を語れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, '信じたる者の群は、おなじ心おなじ思となり、誰 一人その所有を己が者と謂はず、凡ての物を共にせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'かくて使徒たちは大なる能力をもて、主イエスの復活の證をなし、みな大なる恩惠を蒙りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, '彼らの中には一人の乏しき者もなかりき。これ地所あるいは家屋を有てる者、これを賣り、その賣りたる物の價を持ち來りて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, '使徒たちの足下に置きしを、各人その用に隨ひて分け與へられたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'ここにクプロに生れたるレビ人にて、使徒たちにバルナバ(釋けば慰籍の子)と稱へらるるヨセフ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, '畑ありしを賣りて其の金を持ちきたり、使徒たちの足下に置けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, '然るにアナニヤと云ふ人、その妻サツピラと共に資産を賣り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'その價の幾分を匿しおき、殘る幾分を持ちきたりて使徒たちの足下に置きしが、妻も之を與れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'ここにペテロ言ふ『アナニヤよ、何 故なんぢの心サタンに滿ち、聖 靈に對し詐りて、地所の價の幾分を匿したるぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, '有りし時は汝の物なり、賣りて後も汝の權の内にあるに非ずや、何とて斯ることを心に企てし。なんぢ人に對してにあらず、神に對して詐りしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'アナニヤこの言をきき、倒れて息 絶ゆ。これを聞く者みな大なる懼を懷く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, '若者ども立ちて彼を包み、舁き出して葬れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, '凡そ三 時間を經て、その妻この有りし事を知らずして入り來りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'ペテロ之に向ひて言ふ『なんぢら此 程の價にてかの地所を賣りしか、我に告げよ』女いふ『然り、此 程なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'ペテロ言ふ『なんぢら何ぞ心を合せて主の御靈を試みんとせしか、視よ、なんぢの夫を葬りし者の足は門口にあり、汝をもまた舁き出すべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'をんな立刻にペテロの足下に倒れて息 絶ゆ。若者ども入り來りて、その死にたるを見、これを舁き出して夫の傍らに葬れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'ここに全 教會および此 等のことを聞く者みな大なる懼を懷けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, '使徒たちの手によりて多くの徴と不思議と民の中に行はれたり。彼 等はみな心を一つにして、ソロモンの廊にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, '他の者どもは敢へて近づかず、民は彼らを崇めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, '信ずるもの男女とも増々おほく主に屬けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, '終には人々、病める者を大路に舁ききたり、寢臺または床の上におく。此 等のうち誰にもせよ、ペテロの過ぎん時、その影になりと庇はれんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, '又エルサレムの周圍の町々より多くの人々、病める者・穢れし靈に惱されたる者を携へきたりて集ひたりしが、みな醫されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'ここに大 祭司および之と偕なる者、即ちサドカイ派の人々、みな嫉に滿されて立ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, '使徒たちに手をかけて之を留置場に入る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, '然るに主の使、夜、獄の戸をひらき、彼らを連れ出して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '『往きて宮に立ち、この生命の言をことごとく民に語れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'かれら之を聞き、夜明がた宮に入りて教ふ。大 祭司および之と偕なる者ども集ひきたりて、議會とイスラエル人の元老とを呼びあつめ、使徒たちを曳き來らせんとて人を牢舍に遣したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, '下役ども往きしに、獄のうちに彼らの居らぬを見て、歸りきたり告げて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, '『われら牢舍の堅く閉ぢられて、戸の前に牢番の立ちたるを見しに、開きて見れば、内には誰も居らざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, '宮守頭および祭司長らこの言を聞きて、如何になりゆくべきかと惑ひいたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, '或 人きたり告げて言ふ『視よ、汝らの獄に入れし人は、宮に立ちて民を教へ居るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'ここに宮守頭、下役を伴ひて出でゆき、彼らを曳き來る。されど手暴きことをせざりき、これ民より石にて打たれんことを恐れたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, '彼らを連れ來りて議會の中に立てたれば、大 祭司 問ひて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, '『我等かの名によりて教ふることを堅く禁ぜしに、視よ、汝らは其の教をエルサレムに滿し、かの人の血を我らに負はせんとす』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'ペテロ及び他の使徒たち答へて言ふ『人に從はんよりは神に從ふべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, '我らの先祖の神はイエスを起し給ひしに、汝らは之を木に懸けて殺したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, '神は彼を君とし救主として己が右にあげ、悔改と罪の赦とをイスラエルに與へしめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, '我らは此の事の證人なり。神のおのれに從ふ者に賜ふ聖 靈もまた然り』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'かれら之をききて怒に滿ち、使徒たちを殺さんと思へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, '然るにパリサイ人にて凡ての民に尊ばるる教法 學者ガマリエルと云ふもの、議會の中に立ち、命じて使徒たちを暫く外に出さしめ、議員らに向ひて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, '『イスラエルの人よ、汝らが此の人々に爲さんとする事につきて心せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, '前にチウダ起りて、自ら大なりと稱し、之に附 隨ふ者の數おほよそ四 百 人なりしが、彼は殺され、從へる者はみな散されて跡なきに至れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'そののち戸籍 登録のときガリラヤのユダ起りて、多くの民を誘ひおのれに從はしめしが、彼も亡び從へる者もことごとく散されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, '然れば今なんぢらに言ふ、この人々より離れて、その爲すに任せよ。若しその企圖その所作、人より出でたらんにはおのづから壞れん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'もし神より出でたらんには彼らを壞ること能はず、恐らくは汝ら神に敵する者とならん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, '彼 等その勸告にしたがひ、遂に使徒たちを呼び出して之を鞭うち、イエスの名によりて語ることを堅く禁じて釋せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, '使徒たちは御名のために辱しめらるるに相應しき者とせられたるを喜びつつ、議員らの前を出で去れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'かくて日毎に宮また家にて教をなし、イエスのキリストなる事を宣傳へて止まざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'そのころ弟子のかず増 加はり、ギリシヤ語のユダヤ人、その寡婦らが日々の施濟に漏されたれば、ヘブル語のユダヤ人に對して呟く事あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'ここに十二 使徒すべての弟子を呼び集めて言ふ『われら神の言を差措きて、食卓に事ふるは宣しからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, '然れば兄弟よ、汝らの中より御靈と智慧とにて滿ちたる令聞ある者 七人を見出せ、それに此の事を掌どらせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, '我らは專ら祈をなすことと、御言に事ふることとを務めん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, '集れる凡ての者この言を善しとし、信仰と聖 靈とにて滿ちたるステパノ及びピリポ、プロコロ、ニカノル、テモン、パルメナ、またアンテオケの改宗者ニコラオを選びて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, '使徒たちの前に立てたれば、使徒たち祈りて手をその上に按けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'かくて神の言ますます弘り、弟子の數エルサレムにて甚だ多くなり、祭司の中にも信仰の道に從へるもの多かりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'さてステパノは恩惠と能力とにて滿ち、民の中に大なる不思議と徴とを行へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'ここに世に稱ふるリベルテンの會堂およびクレネ人、アレキサンデリヤ人、またキリキヤとアジヤとの人の諸 會堂より、人々 起ちてステパノと論ぜしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'その語るところの智慧と御靈とに敵すること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, '乃ち或 者どもを唆かして『我らはステパノが、モーセと神とを瀆す言をいふを聞けり』と言はしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, '民および長老・學者らを煽動し、俄に來りてステパノを捕へ、議會に曳きゆき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, '僞證者を立てて言はしむ『この人はこの聖なる所と律法とに逆ふ言を語りて止まず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, '即ち、かのナザレのイエスは此の所を毀ち、かつモーセの傳へし例を變ふべしと、彼が云へるを聞けり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'ここに議會に坐したる者みな目を注ぎてステパノを見しに、その顏は御使の顏の如くなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'かくて大 祭司いふ『此 等のこと果してかくの如きか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'ステパノ言ふ『兄弟たち親たちよ、聽け、我らの先祖アブラハム未だカランに住まずして尚メソポタミヤに居りしとき、榮光の神あらはれて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, '「なんぢの土地、なんぢの親族を離れて、我が示さんとする地に往け」と言ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'ここにカルデヤの地に出でてカランに住みたりしが、その父の死にしのち、神は彼を彼處より汝らの今 住める此の地に移らしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, '此處にて足、蹈立つる程の地をも嗣業に與へ給はざりき。然るに、その地を未だ子なかりし彼と彼の裔とに所有として與へんと約し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, '神また其の裔は他の國に寄寓人となり、その國人は之を四百年のあひだ奴隷となして苦しめん事を告げ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, '神いひ給ふ「われは彼らを奴隷とする國人を審かん、然るのち彼 等その國を出で、この處にて我に事へん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, '神また割禮の契約をアブラハムに與へ給ひたれば、イサクを生みて八日めに之に割禮を行へり。イサクはヤコブを、ヤコブは十二の先祖を生めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, '先祖たちヨセフを嫉みてエジプトに賣りしに、神は彼と偕に在して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, '凡ての患難より之を救ひ出し、エジプトの王パロの前にて寵愛を得させ、また智慧を與へ給ひたれば、パロ之を立ててエジプトと己が全家との宰となせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, '時にエジプトとカナンの全地とに飢饉ありて大なる患難おこり、我らの先祖たち糧を求め得ざりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'ヤコブ、エジプトに穀物あるを聞きて、先づ我らの先祖たちを遣す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, '二度めの時ヨセフその兄弟たちに知られ、ヨセフの氏族パロに明かになれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'ヨセフ言ひ遣して己が父ヤコブと凡ての親族と七 十 五 人を招きたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'ヤコブ、エジプトに下り、彼處にて己も我らの先祖たちも死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, '彼 等シケムに送られ、曾てアブラハムがシケムにてハモルの子 等より銀をもて買ひ置きし墓に葬られたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'かくて神のアブラハムに語り給ひし約束の時 近づくに隨ひて、民はエジプトに蕃えひろがり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'ヨセフを知らぬ他の王、エジプトに起るに及べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, '王は惡計をもて我らの同族にあたり、我らの先祖たちを苦しめて、其の嬰兒の生存ふる事なからんやう、之を棄つるに至らしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'その頃モーセ生れて甚うるはしくして三月のあいだ父の家に育てられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, '遂に棄てられしを、パロの娘ひき上げて己が子として育てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'かくてモーセはエジプト人の凡ての學術を教へられ、言と業とに能力あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, '年齡 四十になりたる時、おのが兄弟たるイスラエルの子孫を顧みる心おこり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, '一人の害はるるを見て之を護り、エジプト人を撃ちて、虐げらるる者の仇を復せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, '彼は己の手によりて神が救を與へんとし給ふことを、兄弟たち悟りしならんと思ひたるに、悟らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, '翌日かれらの相 爭ふところに現れて和睦を勸めて言ふ「人々よ、汝らは兄弟なるに、何ぞ互に害ふか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, '隣を害ふ者モーセを押退けて言ふ「誰が汝を立てて我らの司また審判 人とせしぞ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, '昨日エジプト人を殺したる如く、我をも殺さんとするか」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'この言により、モーセ遁れてミデアンの地の寄寓人となり、彼處にて二人の子を儲けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, '四十 年を歴て後シナイ山の荒野にて、御使、柴の焔のなかに現れたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'モーセ之を見て視るところを怪しみ、認めんとして近づきしとき、主の聲あり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '「我は汝の先祖たちの神、即ちアブラハム、イサク、ヤコブの神なり」モーセ戰慄き敢へて認むることを爲ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, '主いひ給ふ「なんぢの足の鞋を脱げ、なんぢの立つところは聖なる地なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, '我エジプトに居る我が民の苦難を見、その歎息をききて之を救はん爲に降れり。いで我なんぢをエジプトに遣さん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, '斯く彼らが「誰が汝を立てて司また審判 人とせしぞ」と言ひて拒みし此のモーセを、神は柴のなかに現れたる御使の手により、司また救人として遣し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'この人かれらを導き出し、エジプトの地にても、また紅海および四十 年のあひだ荒野にても、不思議と徴とを行ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'イスラエルの子らに「神は汝らの兄弟の中より、我がごとき預言者を起し給はん」と云ひしは此のモーセなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, '彼はシナイ山にて語りし御使および我らの先祖たちと偕に荒野なる集會に在りて汝らに與へん爲に生ける御言を授りし人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, '然るに我らの先祖たちは此の人に從ふことを好まず、反つて之を押退け、その心エジプトに還りて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'アロンに言ふ「我らに先だち往くべき神々を造れ、我らをエジプトの地より導き出しし、かのモーセの如何になりしかを知らざればなり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'その頃かれら犢を造り、その偶像に犧牲をささげて己が手の所作を喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, '爰に神は彼らを離れ、その天の軍勢に事ふるに任せ給へり。これは預言者たちの書に「イスラエルの家よ、なんぢら荒野にて四十 年の間、屠りし畜と犧牲とを我に献げしや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, '汝らは拜せんとして造れる像、すなはちモロクの幕屋と神ロンパの星とを舁きたり。われ汝らをバビロンの彼方に移さん」と録されたるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, '我らの先祖たちは荒野にて證の幕屋を有てり、モーセに語り給ひし者の、彼が見し式に循ひて造れと命じ給ひしままなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, '我らの先祖たちは之を承け繼ぎ、先祖たちの前より神の逐ひいだし給ひし異邦人の領地を收めし時、ヨシユアとともに携へ來りてダビデの日に及べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'ダビデ神の前に恩惠を得て、ヤコブの神のために住處を設けんと求めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, '而して、その家を建てたるはソロモンなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'されど至高者は手にて造れる所に住み給はず、即ち預言者の');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '「主のたまはく、天は我が座位、地は我が足臺なり。汝 等わが爲に如何なる家をか建てん、わが休息のところは何處なるぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'わが手は凡て此 等の物を造りしにあらずや」と云へるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, '項強くして心と耳とに割禮なき者よ、汝らは常に聖 靈に逆ふ、その先祖たちの如く汝らも然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, '汝らの先祖たちは預言者のうちの誰をか迫害せざりし。彼らは義人の來るを預じめ告げし者を殺し、汝らは今この義人を賣り、かつ殺す者となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'なんぢら、御使たちの傳へし律法を受けて、尚これを守らざりき』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, '人々これらの言を聞きて、心いかりに滿ち切齒しつつステパノに向ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'ステパノは聖 靈にて滿ち、天に目を注ぎ、神の榮光およびイエスの神の右に立ちたまふを見て言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, '『視よ、われ天 開けて人の子の神の右に立ち給ふを見る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'ここに彼ら大聲に叫びつつ、耳を掩ひ心を一つにして驅け寄り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'ステパノを町より逐ひいだし、石にて撃てり。證人らその衣をサウロといふ若者の足下に置けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'かくて彼 等がステパノを石にて撃てるとき、ステパノ呼びて言ふ『主イエスよ、我が靈を受けたまへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'また跪づきて大聲に『主よ、この罪を彼らの負はせ給ふな』と呼はる。斯く言ひて眠に就けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'サウロは彼の殺さるるを可しとせり。その日エルサレムに在る教會に對ひて大なる迫害おこり、使徒たちの他は皆ユダヤ及びサマリヤの地方に散さる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, '敬虔なる人々ステパノを葬り、彼のために大に胸 打てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'サウロは教會をあらし、家々に入り男女を引出して獄に付せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'ここに散されたる者ども歴 巡りて御言を宣べしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'ピリポはサマリヤの町に下りてキリストの事を傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, '群衆ピリポの行ふ徴を見 聞して、心を一つにし、謹みて其の語る事どもを聽けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'これ多くの人より、之に憑きたる穢れし靈、大聲に叫びて出で、また中風の者と跛者と多く醫されたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'この故にその町に大なる勸喜おこれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'ここにシモンといふ人あり、前にその町にて魔術を行ひ、サマリヤ人を驚かして自ら大なる者と稱へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, '小より大に至る凡ての人つつしみて之に聽き『この人は、いわゆる神の大能なり』といふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'かく謹みて聽けるは、久しき間その魔術に驚かされし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, '然るにピリポが、神の國とイエス・キリストの御名とに就きて宣傳ふるを人々 信じたれば、男女ともにバプテスマを受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'シモンも亦みづから信じ、バプテスマを受けて、常にピリポと偕に居り、その行ふ徴と、大なる能力とを見て驚けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'エルサレムに居る使徒たちは、サマリヤ人、神の御言を受けたりと聞きて、ペテロとヨハネとを遣したれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, '彼ら下りて人々の聖 靈を受けんことを祈れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'これ主イエスの名によりてバプテスマを受けしのみにて、聖 靈いまだ其の一人にだに降らざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'ここに二人のもの彼らの上に手を按きたれば、みな聖 靈を受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, '使徒たちの按手によりて其の御靈を與へられしを見て、シモン金を持ち來りて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, '『わが手を按くすべての人の聖 靈を受くるやうに、此の權威を我にも與へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'ペテロ彼に言ふ『なんぢの銀は汝とともに亡ぶべし、なんぢ金をもて神の賜物を得んと思へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'なんぢは此の事に關係なく干與なし、なんぢの心、神の前に正しからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, '然ればこの惡を悔改めて主に祈れ、なんぢが心の念あるひは赦されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, '我なんぢが苦き膽汁と不義の繋とに居るを見るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'シモン答へて言ふ『なんぢらの言ふ所のこと一つも我に來らぬやう、汝ら我がために主に祈れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'かくて使徒たちは證をなし、主の御言を語りて後、サマリヤ人の多くの村に福音を宣傳へつつエルサレムに歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, '然るに主の使ピリポに語りて言ふ『なんぢ起ちて南に向ひエルサレムよりガザに下る道に往け。そこは荒野なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'ピリポ起ちて往きたれば、視よ、エテオピヤの女王カンダケの權官にして、凡ての寳物を掌どる閹人エテオピヤ人あり、禮拜の爲にエルサレムに上りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, '歸る途すがら馬車に坐して預言者イザヤの書を讀みゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, '御靈ピリポに言ひ給ふ『ゆきて此の馬車に近寄れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'ピリポ走り寄りて、その預言者イザヤの書を讀むを聽きて言ふ『なんぢ其の讀むところを悟るか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, '閹人いふ『導く者なくば、いかで悟り得ん』而してピリポに、乘りて共に坐せんことを請ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'その讀むところの聖書の文は是なり『彼は羊の屠場に就くが如く曳かれ、羔羊のその毛を剪る者のまへに默すがごとく口を開かず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, '卑しめられて審判を奪はれたり、誰かその代の状を述べ得んや。その生命 地上より取られたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, '閹人こたへてピリポに言ふ『預言者は誰に就きて斯く云へるぞ、己に就きてか、人に就きてか、請ふ示せ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'ピリポ口を開き、この聖 句を始としてイエスの福音を宣傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, '途を進むる程に水ある所に來りたれば、閹人いふ『視よ、水あり、我がバプテスマを受くるに何の障りかある』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, '乃ち命じて馬車を止め、ピリポと閹人と二人ともに水に下りて、ピリポ閹人にバプテスマを授く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, '彼ら水より上りしとき、主の靈ピリポを取去りたれば、閹人ふたたび彼を見ざりしが、喜びつつ其の途に進み往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'かくてピリポはアゾトに現れ、町々を經て福音を宣傳へつつカイザリヤに到れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'サウロは主の弟子たちに對して、なほ恐喝と殺害との氣を充し、大 祭司にいたりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'ダマスコにある諸 教會への添書を請ふ。この道の者を見出さば、男女にかかはらず縛りてエルサレムに曳かん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, '往きてダマスコに近づきたるとき、忽ち天より光いでて、彼を環り照したれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'かれ地に倒れて『サウロ、サウロ、何ぞ我を迫害するか』といふ聲をきく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, '彼いふ『主よ、なんぢは誰ぞ』答へたまふ『われは汝が迫害するイエスなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, '起きて町に入れ、さらば汝なすべき事を告げらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, '同行の人々、物 言ふこと能はずして立ちたりしが、聲は聞けども誰をも見ざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'サウロ地より起きて目をあけたれど何も見えざれば、人その手をひきてダマスコに導きゆきしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, '三日のあひだ見えず、また飮食せざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'さてダマスコにアナニヤといふ一人の弟子あり、幻影のうちに主いひ給ふ『アナニヤよ』答ふ『主よ、我ここに在り』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, '主いひ給ふ『起きて直といふ街にゆき、ユダの家にてサウロといふタルソ人を尋ねよ。視よ、彼は祈りをるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, '又アナニアといふ人の入り來りて、再び見ゆることを得しめんために、手を己がうへに按くを見たり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'アナニヤ答ふ『主よ、われ多くの人より此の人に就きて聞きしに、彼がエルサレムにて汝の聖徒に害を加へしこと如何ばかりぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'また此處にても、凡て汝の御名をよぶ者を縛る權を祭司長らより受けをるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, '主いひ給ふ『往け、この人は異邦人・王たち・イスラエルの子孫のまへに、我が名を持ちゆく我が選の器なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, '我かれに我が名のために如何に多くの苦難を受くるかを示さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'ここにアナニヤ往きて其の家にいり、彼の上に手をおきて言ふ『兄弟サウロよ、主すなはち汝が來る途にて現れ給ひしイエス、われを遣し給へり。なんぢが再び見ることを得、かつ聖 靈にて滿されん爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, '直ちに彼の目より鱗のごときもの落ちて見ることを得、すなはち起きてバプテスマを受け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'かつ食事して力づきたり。サウロは數日の間ダマスコの弟子たちと偕にをり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, '直ちに諸 會堂にて、イエスの神の子なることを宣べたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, '聞く者みな驚きて言ふ『こはエルサレムにて此の名をよぶ者を害ひし人ならずや、又ここに來りしも、之を縛りて祭司長らの許に曳きゆかんが爲ならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'サウロますます能力くははり、イエスのキリストなることを論證して、ダマスコに住むユダヤ人を言ひ伏せたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, '日を經ること久しくして後、ユダヤ人かれを殺さんと相 謀りたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'その計畧サウロに知らる。かくて彼らはサウロを殺さんとて、晝も夜も町の門を守りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'その弟子ら夜中かれを籃にて石垣より縋り下せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'ここにサウロ、エルサレムに到りて弟子たちの中に列らんとすれど、皆かれが弟子たるを信ぜずして懼れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, '然るにバルナバ彼を迎へて、使徒たちの許に伴ひゆき、その途にて主を見しこと、主の之に物 言ひ給ひしこと、又ダマスコにてイエスの名のために臆せず語りし事などを具に告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'ここにサウロはエルサレムにて弟子たちと共に出入し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, '主の御名のために臆せず語り、又ギリシヤ語のユダヤ人と、かつ語りかつ論じたれば、彼 等これを殺さんと謀りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, '兄弟たち知りて彼をカイザリヤに伴ひ下り、タルソに往かしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'かくてユダヤ、ガリラヤ及びサマリヤを通じて、教會は平安を得、ややに堅立し、主を畏れて歩み、聖 靈の祐助によりて人數いや増せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'ペテロは徧く四方をめぐりてルダに住む聖徒の許にいたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, '彼處にてアイネヤといふ人の中風を患ひて八 年のあひだ牀に臥し居るに遇ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'かくてペテロ之に『アイネヤよ、イエス・キリスト汝を醫したまふ、起きて牀を收めよ』と言ひたれば、直ちに起きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'ここにルダ及びサロンに住む者みな之を見て主に歸依せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'ヨツパにタビタと云ふ女の弟子あり、その名を譯すればドルカスなり。此の女は、ひたすら善き業と施濟とをなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, '彼そのころ病みて死にたれば、之を洗ひて高樓に置く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'ルダはヨツパに近ければ、弟子たちペテロの彼處に居るを聞きて、二人の者を遣し『ためらはで我らに來れ』と請はしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'ペテロ起ちてともに往き、遂に到れば、彼を高樓に伴れてのぼりしに、寡婦らみな之をかこみて泣きつつ、ドルカスが偕に居りしほどに製りし下衣・上衣を見せたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'ペテロ彼 等をみな外に出し、跪づきて祈りし後、ふりかへり屍體に向ひて『タビタ、起きよ』と言ひたれば、かれ目を開き、ペテロを見て起反れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'ペテロ手をあたへ、起して聖徒と寡婦とを呼び、タビタを活きたるままにて見す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'この事ヨツパ中に知られたれば、多くの人、主を信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'ペテロ皮工シモンの家にありて日 久しくヨツパに留れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'ここにカイザリヤにコルネリオといふ人あり、イタリヤ隊と稱ふる軍隊の百卒長なるが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, '敬虔にして全家族とともに神を畏れ、かつ民に多くの施濟をなし、常に神に祈れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, '或 日の午後 三時ごろ幻影のうちに神の使きたりて『コルネリオよ』と言ふを明かに見たれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, '之に目をそそぎ怖れて言ふ『主よ、何事ぞ』御使いふ『なんぢの祈と施濟とは、神の前に上りて記念とせらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, '今ヨツパに人を遣してペテロと稱ふるシモンを招け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, '彼は皮工シモンの家に宿る。その家は海邊にあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, '斯く語れる御使の去りし後、コルネリオ己が僕 二人と從卒中の敬虔なる者 一人とを呼び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, '凡ての事を告げてヨツパに遣せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, '明くる日かれらなほ途中にあり、既に町に近づかんとする頃ほひ、ペテロ祈らんとて屋の上に登る、時は晝の十二 時ごろなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, '飢ゑて物欲しくなり、人の食を調ふるほどに我を忘れし心地して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, '天 開け、器のくだるを見る、大なる布のごとき物にして、四隅もて地に縋り下されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'その中には諸種の四 足のもの、地を匐ふもの、空の鳥あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'また聲ありて言ふ『ペテロ、立て、屠りて食せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'ペテロ言ふ『主よ、可からじ、我いまだ潔からぬもの穢れたる物を食せし事なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, '聲 再びありて言ふ『神の潔め給ひし物を、なんぢ潔からずとすな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'かくの如きこと三度にして、器は直ちに天に上げられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'ペテロその見し幻影の何の意なるか、心に惑ふほどに、視よ、コルネリオより遣されたる人、シモンの家を尋ねて門の前に立ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, '訪ひて、ペテロと稱ふるシモンの此處に宿るかを問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'ペテロなほ幻影に就きて打案じゐたるに、御靈いひ給ふ『視よ、三人なんぢを尋ぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, '起ちて下り疑はずして共に往け、彼らを遣したるは我なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'ペテロ下りて、かの人たちに言ふ『視よ、我は汝らの尋ぬる者なり、何の故ありて來るか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'かれら言ふ『義人にして神を畏れ、ユダヤの國人の中に令聞ある百卒長コルネリオ、聖なる御使より、汝を家に招きて、その語ることを聽けとの告を受けたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'ここにペテロ彼らを迎へ入れて宿らす。明くる日たちて彼らと共に出でゆきしが、ヨツパの兄弟も數人ともに往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, '明くる日カイザリヤに入りし時、コルネリオは親族および親しき朋友を呼び集めて彼らを待ちゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'ペテロ入り來れば、コルネリオ之を迎へ、その足下に伏して拜す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'ペテロ彼を起して言ふ『立て、我も人なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'かくて相 語りつつ内に入り、多くの人の集れるを見て、ペテロ之に言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, '『なんぢらの知る如く、ユダヤ人たる者の外の國人と交りまた近づくことは、律法に適はぬ所なり、然れど神は、何 人をも穢れたるもの潔からぬ者と言ふまじきことを我に示したまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'この故に、われ招かるるや躊躇はずして來れり。然れば問ふ、汝らは何の故に我をまねきしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'コルネリオ言ふ『われ四日 前に我が家にて午後 三時の祈をなし、此の時刻に至りしに、視よ、輝く衣を著たる人、わが前に立ちて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, '「コルネリオよ、汝の祈は聽かれ、なんぢの施濟は神の前に憶えられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, '人をヨツパに送りてペテロと稱ふるシモンを招け、かれは海邊なる皮工シモンの家に宿るなり」と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'われ速かに人を汝に遣したるに、汝の來れるは忝けなし。いま我等はみな、主の汝に命じ給ひし凡てのことを聽かんとて、神の前に在り』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'ペテロ口を開きて言ふ、『われ今まことに知る、神は偏ることをせず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, '何れの國の人にても神を敬ひて義をおこなふ者を容れ給ふことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, '神はイエス・キリスト(これ萬民の主)によりて平和の福音をのべ、イスラエルの子孫に言をおくり給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, '即ちヨハネの傳へしバプテスマの後、ガリラヤより始り、ユダヤ全國に弘りし言なるは汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'これは神が聖 靈と能力とを注ぎ給ひしナザレのイエスの事にして、彼は徧くめぐりて善き事をおこなひ、凡て惡魔に制せらるる者を醫せり、神これと偕に在したればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, '我等はユダヤの地およびエルサレムにて、イエスの行ひ給ひし諸般のことの證人なり、人々は彼を木にかけて殺せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, '神は之を三日めに甦へらせ、かつ明かに現したまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, '然れど凡ての民にはあらで、神の預じめ選び給へる證人、即ちイエスの死人の中より甦へり給ひし後、これと共に飮食せし我らに現し給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'イエスは己の生ける者と死にたる者との審判 主に、神より定められしを證することと、民どもに宣傳ふる事とを我らに命じ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, '彼につきては預言者たちも皆、おほよそ彼を信ずる者の、その名によりて罪の赦を得べきことを證す』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'ペテロ尚これらの言を語りをる間に、聖 靈、御言をきく凡ての者に降りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'ペテロと共に來りし割禮ある信者は、異邦人にも聖 靈の賜物のそそがれしに驚けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'そは彼らが異言をかたり、神を崇むるを聞きたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'ここにペテロ答へて言ふ『この人々われらの如く聖 靈をうけたれば、誰か水を禁じて其のバプテスマを受くることを拒み得んや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, '遂にイエス・キリストの御名によりてバプテスマを授けられんことを命じたり。ここに彼らペテロに數日とどまらんことを請へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, '使徒たち及びユダヤに居る兄弟たちは、異邦人も神の言を受けたりと聞く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'かくてペテロのエルサレムに上りしとき、割禮ある者ども彼を詰りて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, '『なんぢ割禮なき者の内に入りて之と共に食せり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'ペテロ有りし事を序 正しく説き出して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '『われヨツパの町にて祈り居るとき、我を忘れし心地し、幻影にて器のくだるを見る、大なる布のごとき物にして、四隅もて天より縋り下され我が許にきたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'われ目を注めて之を視るに、地の四 足のもの、野の獸、匐ふもの、空の鳥を見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'また「ペテロ、立て、屠りて食せよ」といふ聲を聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, '我いふ「主よ、可からじ、潔からぬもの穢れたる物は、曾て我が口に入りしことなし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, '再び天より聲ありて答ふ「神の潔め給ひし物を、なんぢ潔からずと爲な」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'かくの如きこと三度にして、終にはみな天に引上げられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, '視よ、三人の者カイザリヤより我に遣されて、はや我らの居る家の前に立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, '御靈われに、疑はずして彼らと共に往くことを告げ給ひたれば、此の六 人の兄弟も我とともに往きて、かの人の家に入れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, '彼はおのが家に御使の立ちて「人をヨツパに遣し、ペテロと稱ふるシモンを招け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'その人、なんぢと汝の全家族との救はるべき言を語らん」と言ふを、見しことを我らに告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'ここに、われ語り出づるや、聖 靈かれらの上に降りたまふ、初め我らの上に降りし如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'われ主の曾て「ヨハネは水にてバプテスマを施ししが、汝らは聖 靈にてバプテスマを施されん」と宣給ひし御言を思ひ出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, '神われらが主イエス・キリストを信ぜしときに賜ひしと同じ賜物を彼らにも賜ひたるに、われ何 者なれば神を阻み得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, '人々これを聞きて默然たりしが、頓て神を崇めて言ふ『されば神は異邦人にも生命を得さする悔改を與へ給ひしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'かくてステパノによりて起りし迫害のために散されたる者ども、ピニケ、クブロ、アンテオケまで到り、ただユダヤ人にのみ御言を語りたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'その中にクブロ及びクレネの人、數人ありて、アンテオケに來りし時、ギリシヤ人にも語りて主イエスの福音を宣傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, '主の手かれらと偕にありたれば、數多の人、信じて主に歸依せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'この事エルサレムに在る教會に聞えたれば、バルナバをアンテオケに遣す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'かれ來りて、神の恩惠を見てよろこび、彼 等に、みな心を堅くして主にをらんことを勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, '彼は聖 靈と信仰とにて滿ちたる善き人なればなり。ここに多くの人々、主に加はりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'かくてバルナバはサウロを尋ねんとてタルソに往き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, '彼に逢ひてアンテオケに伴ひきたり、二人ともに一年の間かしこの教會の集會に出でて多くの人を教ふ。弟子たちのキリステアンと稱へらるる事はアンテオケより始れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'その頃エルサレムより預言者たちアンテオケに下る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'その中の一人アガボと云ふもの起ちて、大なる飢饉の全世界にあるべきことを御靈によりて示せるが、果してクラウデオの時に起れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'ここに弟子たち各々の力に應じてユダヤに住む兄弟たちに扶助をおくらん事をさだめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, '遂に之をおこなひ、バルナバ及びサウロの手に托して長老たちに贈れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'その頃ヘロデ王、教會のうちの或 人どもを苦しめんとて手を下し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, '劍をもてヨハネの兄弟ヤコブを殺せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'この事ユダヤ人の心に適ひたるを見て、またペテロをも捕ふ、頃は除酵祭の時なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'すでに執りて獄に入れ、過越の後に民のまへに曳き出さんとの心構にて、四人 一組なる四組の兵卒に付して之を守らせたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'かくてペテロは獄のなかに因はれ、教會は熱心に彼のために神に祈をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'ヘロデこれを曳き出さんとする其の前の夜、ペテロは二つの鏈にて繋がれ、二人の兵卒のあひだに睡り、番兵らは門口にゐて獄を守りたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, '視よ、主の使ペテロの傍らに立ちて、光明 室内にかがやく。御使かれの脇をたたき、覺していふ『疾く起きよ』かくて鏈その手より落ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, '御使いふ『帶をしめ、鞋をはけ』彼その如く爲たれば、又いふ『上衣をまとひて我に從へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'ペテロ出でて隨ひしが、御使のする事の眞なるを知らず、幻影を見るならんと思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'かくて第一・第二の警固を過ぎて町に入るところの鐵の門に到れば、門おのづから彼 等のために開け、相 共にいでて一つの街を過ぎしとき、直ちに御使はなれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'ペテロ我に反りて言ふ『われ今まことに知る、主その使を遣して、ヘロデの手およびユダヤの民の凡て思ひ設けし事より、我を救ひ出し給ひしを』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, '斯く悟りてマルコと稱ふるヨハネの母マリヤの家に往きしが、其處には數多のもの集りて祈りゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'ペテロ門の戸を叩きたれば、ロダといふ婢女ききに出できたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'ペテロの聲なるを知りて、勸喜のあまりに門を開けずして走り入り、ペテロの門の前に立てることを告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, '彼ら『なんぢは氣 狂へり』と言ふ。然れどロダは夫なりと言張る。かれら言ふ『それはペテロの御使ならん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, '然るにペテロなほ叩きて止まざれば、かれら門をひらき之を見て驚けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'かれ手を搖かして人々を鎭め、主の己を獄より導きいだし給ひしことを具に語り『これをヤコブと兄弟たちとに告げよ』と言ひて他の處に出で往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, '夜明になりて、ペテロは如何にせしとて兵卒の中の騷 一方ならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'ヘロデ之を索むれど見出さず、遂に守卒を訊して死罪を命じ、而してユダヤよりカイザリヤに下りて留れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, '偖ヘロデ、ツロとシドンとの人々を甚く怒りたれば、其の民ども心を一つにして彼の許にいたり、王の内侍の臣ブラストに取 入りて和諧を求む。かれらの地方は王の國より食品を得るに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'ヘロデ定めたる日に及びて王の服を著け高座に坐して言を宣べたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, '集民よばはりて『これ神の聲なり、人の聲にあらず』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'ヘロデ神に榮光を歸せぬに因りて、主の使たちどころに彼を撃ちたれば、蟲に噛まれて息 絶えたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'かくて主の御言いよいよ増々ひろまる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'バルナバ、サウロはその職務を果し、マルコと稱ふるヨハネを伴ひてエルサレムより歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'アンテオケの教會にバルナバ、ニゲルと稱ふるシメオン、クレネ人ルキオ、國守ヘロデの乳 兄弟マナエン及びサウロなどいふ預言者と教師とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, '彼らが主に事へ斷食したるとき、聖 靈いひ給ふ『わが召して行はせんとする業の爲に、バルナバとサウロとを選び、別て』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'ここに彼ら斷食し、祈りて二人の上に手を按きて往かしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'この二人、聖 靈に遣されてセルキヤに下り、彼處より船にてクプロに渡り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'サラミスに著きてユダヤ人の諸 會堂にて神の言を宣傳へ、またヨハネを助人として伴ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, '徧くこの島を經 行きてパポスに到り、バルイエスといふユダヤ人にて僞 預言者たる魔術 者に遇ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, '彼は地方 總督なる慧き人セルギオ・パウロと偕にありき。總督はバルナバとサウロとを招き神の言を聽かんとしたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'かの魔術 者エルマ(この名を釋けば魔術 者)二人に敵 對して總督を信仰の道より離れしめんとせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'サウロ又の名はパウロ、聖 靈に滿され、彼に目を注めて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, '『ああ有らゆる詭計と奸惡とにて滿ちたる者、惡魔の子、すべての義の敵よ、なんぢ主の直き道を曲げて止まぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, '視よ、いま主の御手なんぢの上にあり、なんぢ盲目となりて暫く日を見ざるべし』かくて立刻に朦と闇とその目を掩ひたれば、探り囘りて導きくるる者を求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'ここに總督この有りし事を見て、主の教に驚きて信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'さてパウロ及び之に伴ふ人々、パポスより船出してパンフリヤのペルガに到り、ヨハネは離れてエルサレムに歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, '彼らはペルガより進み往きてピシデヤのアンテオケに到り、安息 日に會堂に入りて坐せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, '律法および預言者の書の朗讀ありしのち、會堂 司たち人を彼らに遣し『兄弟たちよ、もし民に勸の言あらば言へ』と言はしめたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'パウロ起ちて手を搖かして言ふ、『イスラエルの人々および神を畏るる者よ、聽け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'このイスラエルの民の神は、我らの先祖を選び、そのエジプトの地に寄寓せし時、わが民をおこし、強き御腕にて之を導きいだし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'おほよそ四十 年のあひだ、荒野にて彼らの所作を忍び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'カナンの地にて七つの民族をほろぼし、その地を彼らに嗣がしめて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, '凡そ四 百 五 十 年を經たり。此ののち預言者サムエルの時代まで審判 人を賜ひしを、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, '後に至りて彼ら王を求めたれば、神は之にキスの子サウロと云ふベニヤミンの族の人を四十 年のあひだ賜ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, '之を退けて後、ダビデを擧げて王となし、且これを證して「我エッサイの子ダビデといふ我が心に適ふ者を見出せり、彼わが意をことごとく行はん」と宣給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, '神は約束に隨ひて此の人の裔より、イスラエルの爲に救主イエスを興し給ひしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'その來る前にヨハネ預じめイスラエルの凡ての民に悔改のバプテスマを宣傳へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'かくてヨハネ己が走るべき道程を終へんとする時「なんぢら我を誰と思ふか、我はかの人にあらず、視よ、我に後れて來る者あり、我はその鞋の紐を解くにも足らず」と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, '兄弟たち、アブラハムの血統の子ら及び汝 等のうち神を畏るる者よ、この救の言は我らに贈られたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'それエルサレムに住める者および其の司らは、彼をも安息 日ごとに讀むところの預言者たちの言をも知らず、彼を刑ひて預言を成就せしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'その死に當るべき故を得ざりしかど、ピラトに殺さんことを求め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, '彼につきて記されたる事をことごとく成しをへ、彼を木より下して墓に納めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'されど神は彼を死人の中より甦へらせ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'かくてイエスは己と偕にガリラヤよりエルサレムに上りし者に多くの日のあひだ現れ給へり。その人々は今、民の前にイエスの證人たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, '我らも先祖たちが與へられし約束につきて喜ばしき音信を汝らに告ぐ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, '神はイエスを甦へらせて、その約束を我らの子孫に成就したまへり。即ち詩の第二 篇に「なんぢは我が子なり、われ今日なんぢを生めり」と録されたるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'また朽腐に歸せざる状に彼を死人の中より甦へらせ給ひし事に就きては、斯く宣給へり。曰く「われダビデに約せし確き聖なる恩惠を汝らに與へん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'そは他の篇に「なんぢは汝の聖者を朽腐に歸せざらしむべし」と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'それダビデは、その代にて神の御旨を行ひ、終に眠りて先祖たちと共に置かれ、かつ朽腐に歸したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, '然れど神の甦へらせ給ひし者は朽腐に歸せざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'この故に兄弟たちよ、汝ら知れ。この人によりて罪の赦のなんぢらに傳へらるることを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, '汝らモーセの律法によりて義とせられ得ざりし凡ての事も、信ずる者は皆この人によりて義とせらるる事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, '然れば汝ら心せよ、恐らくは預言者たちの書に云ひたること來らん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '曰く「あなどる者よ、なんぢら視よ、おどろけ、亡びよ、われ汝らの日に一つの事を行はん。これを汝らに具に告ぐる者ありとも信ぜざる程の事なり」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, '彼らが會堂を出づるとき、人々これらの言を次の安息 日にも語らんことを請ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, '集會の散ぜし後、ユダヤ人および敬虔なる改宗者おほくパウロとバルナバとに從ひ往きたれば、彼らに語りて神の恩惠に止らんことを勸めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, '次の安息 日には、神の言を聽かんとて殆ど町 擧りて集りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'されどユダヤ人はその群衆を見て嫉に滿され、パウロの語ることに言ひ逆ひて罵れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'パウロとバルナバとは臆せずして言ふ『神の言を先づ汝らに語るべかりしを、汝 等これを斥けて己を永遠の生命に相應しからぬ者と自ら定むるによりて、視よ、我ら轉じて異邦人に向はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'それ主は斯く我らに命じ給へり。曰く「われ汝を立てて異邦人の光とせり。地の極にまで救とならしめん爲なり」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, '異邦人は之を聽きて喜び、主の言をあがめ、又とこしへの生命に定められたる者はみな信じ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, '主の言この地に徧く弘りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, '然るにユダヤ人ら、敬虔なる貴女たち及び町の重立ちたる人々を唆かして、パウロとバルナバとに迫害をくはへ、遂に彼らを其の境より逐ひ出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, '二人は彼らに對ひて足の塵をはらひ、イコニオムに往く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, '弟子たちは喜悦と聖 靈とにて滿され居たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, '二人はイコニオムにて相 共にユダヤ人の會堂に入りて語りたれば、之に由りてユダヤ人およびギリシヤ人あまた信じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, '然るに從はぬユダヤ人ら異邦人を唆かし、兄弟たちに對して惡意を懷かしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, '二人は久しく留り、主によりて臆せずして語り、主は彼らの手により、徴と不思議とを行ひて惠の御言を證したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'ここに町の人々 相 分れて、或 者はユダヤ人に黨し、或 者は使徒たちに黨せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, '異邦人ユダヤ人および其の司ら相 共に使徒たちを辱しめ、石にて撃たんと企てしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, '彼ら悟りてルカオニヤの町なるルステラ、デルベ及びその邊の地にのがれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, '彼處にて福音を宣傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'ルステラに足 弱き人ありて坐しゐたり、生れながらの跛者にて曾て歩みたる事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'この人パウロの語るを聽きゐたるが、パウロ之に目をとめ、救はるべき信仰あるを見て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, '大聲に『なんぢの足にて眞直に起て』と言ひたれば、かれ躍り上りて歩めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, '群衆、パウロの爲ししことを見て聲を揚げ、ルカオニヤの國語にて『神たち人の形をかりて我らに降り給へり』と言ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'バルナバをゼウスと稱へ、パウロを宗と語る人なる故にヘルメスと稱ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, '而して町の外なるゼウスの宮の祭司、數匹の牛と花 飾とを門の前に携へきたりて、群衆とともに犧牲を献げんとせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, '使徒たち、即ちバルナバとパウロと之を聞きて、己が衣をさき群衆のなかに馳せ入り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, '呼はりて言ふ『人々よ、なんぞ斯かる事をなすか、我らも汝らと同じ情を有てる人なり、汝らに福音を宣べて斯かる虚しき者より離れ、天と地と海とその中にある有らゆる物とを造り給ひし活ける神に歸らしめんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, '過ぎし時代には神、すべての國人の己が道々を歩むに任せ給ひしかど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'また自己を證し給はざりし事なし。即ち善き事をなし、天より雨を賜ひ、豐穰の時をあたへ、食物と勸喜とをもて汝らの心を滿ち足らはせ給ひしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, '斯く言ひて辛うじて群衆の己らに犧牲を献げんとするを止めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, '然るに數人のユダヤ人、アンテオケ及びイコニオムより來り、群衆を勸め、而してパウロを石にて撃ち、既に死にたりと思ひて町の外に曳き出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, '弟子たち之を立 圍みゐたるに、パウロ起きて町に入る。明くる日バルナバと共にデルベに出で往き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'その町に福音を宣傳へ、多くの人を弟子として後、ルステラ、イコニオム、アンテオケに還り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, '弟子たちの心を堅うし信仰に止らんことを勸め、また我らが多くの艱難を歴て神の國に入るべきことを教ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'また教會 毎に長老をえらび、斷食して祈り、弟子たちを其の信ずる所の主に委ぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'かくてピシデヤを經てパンフリヤに到り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'ペルガにて御言を語りて後アタリヤに下り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, '彼處より船出して、その成し果てたる務のために神の惠みに委ねられし處なるアンテオケに往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, '既に到りて教會の人々を集めたれば、神が己らと偕に在して成し給ひし凡てのこと、竝に信仰の門を異邦人にひらき給ひしことを述ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'かくて久しく留りて弟子たちと偕にゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, '或 人々ユダヤより下りて、兄弟たちに『なんぢらモーセの例に遵ひて割禮を受けずば救はるるを得ず』と教ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'ここに彼らとパウロ及びバルナバとの間に、大なる紛爭と議論と起りたれば、兄弟たちはパウロ、バルナバ及びその中の數人をエルサレムに上らせ、此の問題につきて使徒・長老たちに問はしめんと定む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'かれら教會の人々に見 送られて、ピニケ及びサマリヤを經、異邦人の改宗せしことを具に告げて、凡ての兄弟に大なる喜悦を得させたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'エルサレムに到り、教會と使徒と長老とに迎へられ、神が己らと偕に在して爲し給ひし凡ての事を述べたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, '信者となりたるパリサイ派の或 人々 立ちて『異邦人にも割禮を施し、モーセの律法を守ることを命ぜざる可からず』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'ここに使徒・長老たち此の事につきて協議せんとて集る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, '多くの議論ありし後、ペテロ起ちて言ふ『兄弟たちよ、汝らの知るごとく、久しき前に神は、なんぢらの中より我を選び、わが口より異邦人に福音の言を聞かせ、之を信ぜしめんとし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, '人の心を知りたまふ神は、我らと同じく、彼 等にも聖 靈を與へて證をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'かつ信仰によりて彼らの心をきよめ、我らと彼らとの間に隔を置き給はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, '然るに何ぞ神を試みて、弟子たちの頸に我らの先祖も我らも負ひ能はざりし軛をかけんとするか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, '然らず、我らの救はるるも彼らと均しく主イエスの恩惠に由ることを我らは信ず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'ここに會衆みな默して、バルナバとパウロとの、己 等によりて神が異邦人のうちに爲し給ひし多くの徴と不思議とを述ぶるを聽く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, '彼らの語り終へし後、ヤコブ答へて言ふ『兄弟たちよ、我に聽け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'シメオン既に神の初めて異邦人を顧み、その中より御名を負ふべき民を取り給ひしことを述べしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, '預言者たちの言もこれと合へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '録して「こののち我かへりて、倒れたるダビデの幕屋を再び造り、その頽れし所をふたたび造り、而して之を立てん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'これ殘餘の人々、主を尋ね求め、凡て我が名をもて稱へらるる異邦人もまた然せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, '古へより此 等のことを知らしめ給ふ主、これを言ひ給ふ」とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, '之によりて我は判斷す、異邦人の中より神に歸依する人を煩はすべきにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'ただ書き贈りて、偶像に穢されたる物と、淫行と、絞殺したる物と、血とを避けしむべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, '昔より、いづれの町にもモーセを宣ぶる者ありて、安息 日 毎に諸 會堂にてその書を讀めばなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'ここに使徒・長老たち及び全 教會は、その中より人を選びてパウロ、バルナバと共にアンテオケに送ることを可しとせり。選ばれたるは、バルサバと稱ふるユダとシラスとにて、兄弟たちの中の重立ちたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, '之に托したる書にいふ『使徒および長老たる兄弟ら、アンテオケ、シリヤ、キリキヤに在る異邦人の兄弟たちの平安を祈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, '我等のうちの或 人々われらが命じもせぬに、言をもて汝らを煩はし、汝らの心を亂したりと聞きたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, '我ら心を一つにして人を選びて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, '我らの主イエス・キリストの名のために生命を惜まざりし者なる、我らの愛するバルナバ、パウロと共に汝らに遣すことを可しとせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, '之によりて我らユダとシラスとを遣す、かれらも口づから此 等のことを述べん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, '聖 靈と我らとは左の肝要なるものの他に何をも汝らに負はせぬを可しとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, '即ち偶像に献げたる物と、血と、絞殺したる物と、淫行とを避くべき事なり、汝 等これを愼まば善し。なんぢら健かなれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'かれら別を告げてアンテオケに下り、人々を集めて書を付す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, '人々これを讀み慰安を得て喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'ユダもシラスもまた預言者なれば、多くの言をもて兄弟たちを勸めて彼らを堅うし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, '暫く留りてのち、兄弟たちに平安を祝せられ、別を告げて、己らを遣しし者に歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, '斯てパウロとバルナバとは尚アンテオケに留りて多くの人とともに主の御言を教へ、かつ宣傳へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, '數日の後パウロはバルナバに言ふ『いざ、我ら曩に主の御言を傳へし凡ての町にまた往きて、兄弟たちを訪ひ、その安否を尋ねん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'バルナバはマルコと稱ふるヨハネを伴はんと望み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'パウロは彼が曾てパンフリヤより離れ去りて、勤勞のために共に往かざりしをもて、伴ふは宣しからずと思ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, '激しき爭論となりて遂に二人 相 別れ、バルナバはマルコを伴ひ、舟にてクプロに渡り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'パウロはシラスを選び、兄弟たちより主の恩惠に委ねられて出で立ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'シリヤ、キリキヤを經て諸 教會を堅うせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'かくてパウロ、デルベとルステラとに到りたるに、視よ、彼處にテモテと云ふ弟子あり、その母は信者なるユダヤ人にて、父はギリシヤ人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, '彼はルステラ、イコニオムの兄弟たちの中に令聞ある者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'パウロかれの共に出で立つことを欲したれば、その邊に居るユダヤ人のために之に割禮を行へり、その父のギリシヤ人たるを凡ての人の知る故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'かくて町々を經ゆきて、エルサレムに居る使徒・長老たちの定めし規を守らせんとて、之を人々に授けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'ここに諸 教會はその信仰を堅うせられ、人員 日毎にいや増せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, '彼らアジヤにて御言を語ることを聖 靈に禁ぜられたれば、フルギヤ及びガラテヤの地を經ゆきて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'ムシヤに近づき、ビテニヤに往かんと試みたれど、イエスの御靈ゆるし給はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, '遂にムシヤを過ぎてトロアスに下れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'パウロ夜、幻影を見たるに、一人のマケドニヤ人あり、立ちて己を招き『マケドニヤに渡りて我らを助けよ』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'パウロこの幻影を見たれば、我らは神のマケドニヤ人に福音を宣傳へしむる爲に、我らを召し給ふことと思ひ定めて、直ちにマケドニヤに赴かんとせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'さてトロアスより船出して、眞直にはせてサモトラケにいたり、次の日ネアポリスにつき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, '彼處よりピリピにゆく。ここはマケドニヤの中にて、この邊の第一の町にして殖民地なり、われら數日の間この町に留る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, '安息 日に町の門を出でて、祈場あらんと思はるる河のほとりに往き、其處に坐して、集れる女たちに語りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'テアテラの町の紫 布の商人にして、神を敬ふルデヤと云ふ女きき居りしが、主その心をひらき、謹みてパウロの語る言をきかしめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, '彼は己も家族もバプテスマを受けてのち、我らに勸めて言ふ『なんぢら我を主の信者なりとせば、我が家に來りて留れ』斯く強ひて我らを留めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'われら祈場に往く途中、卜筮の靈に憑れて卜筮をなし、其の主人らに多くの利を得さする婢女、われらに遇ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, '彼はパウロ及び我らの後に從ひつつ叫びて言ふ『この人たちは至高き神の僕にて、汝らに救の道を教ふる者なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, '幾日も斯くするをパウロ憂ひて、振反りその靈に言ふ『イエス・キリストの名によりて、汝にこの女より出でん事を命ず』靈ただちに出でたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, '然るにこの女の主人ら利を得る望のなくなりたるをみて、パウロとシラスとを捕へ、市場に曳きて司たちに往き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, '之を上役らに出して言ふ『この人々はユダヤ人にて、我らの町を甚く騷がし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, '我らロマ人たる者の受くまじく行ふまじき習慣を傳ふるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, '群衆も齊しく起り立ちたれば、上役ら命じて其の衣を褫ぎ、かつ笞にて打たしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, '多く打ちてのち獄に入れ、獄守に固く守るべきことを命ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, '獄守この命令を受けて二人を奧の獄に入れ、桎にてその足を締め置きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, '夜半ごろパウロとシラスと祈りて神を讃美する囚人ら聞きゐたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, '俄に大なる地震おこりて牢舍の基ふるひ動き、その戸たちどころに皆ひらけ、凡ての囚人の縲絏とけたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, '獄守、目さめ獄の戸の開けたるを見て、囚人にげ去れりと思ひ、刀を拔きて自殺せんとしたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'パウロ大聲に呼はりて言ふ『みづから害ふな、我ら皆ここに在り』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, '獄守、燈火を求め、駈け入りて戰きつつパウロとシラスとの前に平伏し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, '之を連れ出して言ふ『君たちよ、われ救はれん爲に何をなすべきか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, '二人は言ふ『主イエスを信ぜよ、然らば汝も汝の家族も救はれん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'かくて神の言を獄守とその家に居る凡ての人々に語れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'この夜、即時に獄守かれらを引取りて、その打傷を洗ひ、遂に己も己に屬する者もみな直ちにバプテスマを受け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'かつ二人を自宅に伴ひて食事をそなへ、全家とともに神を信じて喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, '夜明になりて上役らは警吏どもを遣して『かの人々を釋せ』と言はせたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, '獄守これらの言をパウロに告げて言ふ『上役、人を遣して汝らを釋さんとす。然れば今いでて安らかに往け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'ここにパウロ警吏に言ふ『我らはロマ人たるに罪を定めずして公然に鞭うち、獄に投げ入れたり。然るに今ひそかに我らを出さんと爲るか。然るべからず、彼 等みづから來りて我らを連れ出すべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, '警吏これらの言を上役に告げたれば、其のロマ人たるを聞きて懼れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, '來り宥めて、二人を連れ出し、かつ町を去らんことを請ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, '二人は獄を出でてルデヤの家に入り、兄弟たちに逢ひ、勸をなして出で往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'かくてアムピポリス及びアポロニヤを經てテサロニケに到る。此處にユダヤ人の會堂ありたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'パウロは例のごとく彼らの中に入り、三つの安息 日にわたり、聖書に基きて論じ、かつ解き明して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'キリストの必ず苦難をうけ、死人の中より甦へるべきことを述べ『わが汝らに傳ふる此のイエスはキリストなり』と證せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'その中のある人々および敬虔なる數多のギリシヤ人、また多くの重立ちたる女も信じてパウロとシラスとに從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'ここにユダヤ人ら嫉を起して市の無頼者をかたらひ、群衆を集めて町を騷がし、又ふたりを集民の前に曳き出さんとしてヤソンの家を圍みしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, '見出さざれば、ヤソンと數人の兄弟とを町 司たちの前に曳ききたり、呼はりて言ふ『天下を顛覆したる彼の者ども此處にまで來れるを、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'ヤソン迎へ入れたり。この曹輩は皆カイザルの詔勅にそむき、他にイエスと云ふ王ありと言ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, '之をききて群衆と町 司たちと心をさわがし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, '保證を取りてヤソンと他の人々とを釋せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, '兄弟たち直ちに夜の間にパウロとシラスとをベレヤに送りいだす。二人は彼處につきてユダヤ人の會堂にいたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, '此處の人々はテサロニケに居る人よりも善良にして、心より御言をうけ、この事 正しく然るか然らぬか、日々 聖書をしらぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'この故にその中の多くのもの信じたり、又ギリシヤの貴女、男子にして信じたる者も少からざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, '然るにテサロニケのユダヤ人ら、パウロがベレヤにも神の言を傳ふることを聞きたれば、此處にも來りて群衆を動かし、かつ騷がしたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'ここに兄弟たち直ちにパウロを送り出して海邊に往かしめ、シラスとテモテとは尚ベレヤに留れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'パウロを導ける人々はアテネまで伴ひ往き、パウロよりシラスとテモテとに、疾く我に來れとの命を受けて立ち去れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'パウロ、アテネにて彼らを待ちをる間に、町に偶像の滿ちたるを見て、その心に憤慨を懷く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'されば會堂にてはユダヤ人および敬虔なる人々と論じ、市場にては日々 逢ふところの者と論じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, '斯てエピクロス派ならびにストア派の哲學者 數人これと論じあひ、或 者らは言ふ『この囀る者なにを言はんとするか』或 者らは言ふ『かれは異なる神々を傳ふる者の如し』是はパウロがイエスと復活とを宣べたる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, '遂にパウロをアレオパゴスに連れ往きて言ふ『なんぢが語るこの新しき教の如何なるものなるを、我ら知り得べきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'なんぢ異なる事を我らの耳に入るるが故に、我らその何事たるを知らんと思ふなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'アテネ人も、彼處に住む旅人も、皆ただ新しき事を或は語り、或は聞きてのみ日を送りゐたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'パウロ、アレオパゴスの中に立ちて言ふ『アテネ人よ、我すべての事に就きて汝らが神々を敬ふ心の篤きを見る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'われ汝らが拜むものを見つつ道を過ぐるほどに「知らざる神に」と記したる一つの祭壇を見出したり。然れば我なんぢらが知らずして拜む所のものを汝らに示さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, '世界とその中のあらゆる物とを造り給ひし神は、天 地の主にましませば、手にて造れる宮に住み給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'みづから凡ての人に生命と息と萬の物とを與へ給へば、物に乏しき所あるが如く、人の手にて事ふることを要し給はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, '一人よりして諸種の國人を造りいだし、之を地の全面に住ましめ、時期の限と住居の界とを定め給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'これ人をして神を尋ねしめ、或は探りて見 出す事あらしめん爲なり。されど神は我等おのおのを離れ給ふこと遠からず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, '我らは神の中に生き、動きまた在るなり。汝らの詩人の中の或 者どもも「我らは又その裔なり」と云へる如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'かく神の裔なれば、神を金・銀・石など人の工と思考とにて刻める物と等しく思ふべきにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, '神はかかる無知の時代を見 過しにし給ひしが、今は何處にても凡ての人に悔改むべきことを告げたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, '曩に立て給ひし一人によりて、義をもて世界を審かんために日をさだめ、彼を死人の中より甦へらせて保證を萬人に與へ給へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, '人々、死人の復活をききて、或 者は嘲笑ひしが、或 者は『われら復この事を汝に聞かん』と言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'ここにパウロ人々のなかを出で去る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'されど彼に附隨ひて信じたるもの數人あり。其の中にアレオパゴスの裁判人デオヌシオ及びダマリスと名づくる女あり、尚その他にもありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'この後パウロ、アテネを離れてコリントに到り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'アクラと云ふポントに生れたるユダヤ人に遇ふ。クラウデオ、ユダヤ人にことごとくロマを退くべき命を下したるによりて、近頃その妻プリスキラと共にイタリヤより來りし者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'パウロ其の許に到りしに、同業なりしかば偕に居りて工をなせり。彼らの業は幕屋 製造なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'かくて安息 日 毎に會堂にて論じ、ユダヤ人とギリシヤ人とを勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'シラスとテモテとマケドニヤより來りて後は、パウロ專ら御言を宣ぶることに力め、イエスのキリストたることをユダヤ人に證せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, '然るに、彼ら之に逆ひかつ罵りたれば、パウロ衣を拂ひて言ふ『なんぢらの血は汝らの首に歸すべし、我はいさぎよし、今より異邦人に往かん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, '遂に此處を去りて、神を敬ふテテオ・ユストと云ふ人の家に到る。この家は會堂に隣れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, '會堂 司クリスポその家族 一同と共に主を信じ、また多くのコリント人も聽きて信じ、かつバプテスマを受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, '主は夜まぼろしの中にパウロに言ひ給ふ『おそるな、語れ、默すな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, '我なんぢと偕にあり、誰も汝を攻めて害ふ者なからん。此の町には多くの我が民あり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'かくてパウロ一年 六个月ここに留りて神の言を教へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'ガリオ、アカヤの總督たる時、ユダヤ人、心を一つにしてパウロを攻め、審判の座に曳きゆき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, '『この人は律法にかなはぬ仕方にて神を拜むことを人に勸む』と言ひたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'パウロ口を開かんとせしに、ガリオ、ユダヤ人に言ふ『ユダヤ人よ、不正または奸惡の事ならば、我が汝らに聽くは道理なれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'もし言・名あるいは汝らの律法にかかはる問題ならば、汝 等みづから理むべし。我かかる事の審判 人となるを好まず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'かくて彼らを審判の座より逐ひいだす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'ここに人々みな會堂 司ソステネを執へ、審判の座の前にて打ち抃きたり。ガリオは凡て此らの事を意とせざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'パウロなほ久しく留りてのち、兄弟たちに別を告げ、プリスキラとアクラとを伴ひ、シリヤに向ひて船出す。早くより誓願ありたれば、ケンクレヤにて髮を剃れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'かくてエペソに著き、其處にこの二人を留めおき、自らは會堂に入りてユダヤ人と論ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, '人々かれに今しばらく居らんことを請ひたれど、肯んぜずして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, '別を告げ『神の御意ならば復なんぢらに返らん』と言ひてエペソより船出し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'カイザリヤにつき、而してエルサレムに上り、教會の安否を問ひてアンテオケに下り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, '此處に暫く留りて後、また去りてガラテヤ、フルギヤの地を次々に經て凡ての弟子を堅うせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, '時にアレキサンデリヤ生れのユダヤ人にて、聖書に通達したるアポロと云ふ能辯なる者エペソに下る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'この人は曩に主の道を教へられ、ただヨハネのバプテスマを知るのみなれど、熱心にして詳細にイエスの事を語り、かつ教へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'かれ會堂にて臆せずして語り始めしを、プリスキラとアクラと聞きゐて之を迎へ入れ、なほも詳細に神の道を解き明せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'アポロ遂にアカヤに渡らんとしたれば、兄弟たち之を勵まし、かつ弟子たちに彼を受け容るるやうに書き贈れり。彼かしこに往き、既に恩惠によりて信じたる者に多くの益を與ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, '即ち聖書に基き、イエスのキリストたる事を示して、激甚くかつ公然にユダヤ人を言ひ伏せたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'かくてアポロ、コリントに居りし時、パウロ東の地方を經てエペソに到り、或 弟子たちに逢ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, '『なんぢら信者となりしとき聖 靈を受けしか』と言ひたれば、彼 等いふ『いな、我らは聖 靈の有ることすら聞かず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'パウロ言ふ『されば何によりてバプテスマを受けしか』彼 等いふ『ヨハネのバプテスマなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'パウロ言ふ『ヨハネは悔改のバプテスマを授けて、己に後れて來るもの(即ちイエス)を信ずべきことを民に云へるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, '彼 等これを聞きて主イエスの名によりてバプテスマを受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'パウロ手を彼らの上に按きしとき、聖 靈その上に望みたれば、彼ら異言を語り、かつ預言せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'この人々は凡て十二 人ほどなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'ここにパウロ會堂に入りて、三个月のあひだ臆せずして神の國に就きて論じ、かつ勸めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, '然るに或 者ども頑固になりて從はず、會衆の前に神の道を譏りたれば、パウロ彼らを離れ、弟子たちをも退かしめ、日毎にツラノの會堂にて論ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, '斯くすること二年の間なりしかば、アジヤに住む者は、ユダヤ人もギリシヤ人もみな主の言を聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, '而して神はパウロの手によりて尋常ならぬ能力ある業を行ひたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, '即ち人々かれの身より或は手拭あるひは前垂をとりて病める者に著くれば、病は去り惡 靈は出でたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'ここに諸國 遍歴の咒文 師なるユダヤ人 數人あり、試みに惡 靈に憑かれたる者に對して、主イエスの名を呼び『われパウロの宣ぶるイエスによりて、汝らに命ず』と言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, '斯くなせる者の中に、ユダヤの祭司長スケワの七人の子もありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, '惡 靈こたへて言ふ『われイエスを知り、又パウロを知る。然れど汝らは誰ぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'かくて惡 靈の入りたる人、かれらに跳びかかりて二人に勝ち、これを打拉ぎたれば、彼ら裸體になり傷を受けてその家を逃げ出でたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, '此の事エペソに住む凡てのユダヤ人とギリシヤ人とに知れたれば、懼かれら一同のあひだに生じ、主イエスの名 崇めらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, '信者となりし者おほく來り、懴悔して自らの行爲を告ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'また魔術を行ひし多くの者ども、その書物を持ちきたり、衆人の前にて焚きたるが、其の價を算ふれば銀 五 萬ほどなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, '主の言、大に弘りて權力を得しこと斯くの如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, '此 等の事のありし後、パウロ、マケドニヤ、アカヤを經てエルサレムに往かんと心を決めて言ふ『われ彼處に到りてのち必ずロマをも見るべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'かくて己に事ふる者の中にてテモテとエラストとの二人をマケドニヤに遣し、自己はアジヤに暫く留る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'その頃この道に就きて一方ならぬ騷擾おこれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'デメテリオと云ふ銀 細工人ありしが、アルテミスの銀の小宮を造りて細工人らに多くの業を得させたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'それらの者および同じ類の職業 者を集めて言ふ『人々よ、われらが此の業に頼りて利 益を得ることは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, '然るに、かのパウロは手にて造れる物は神にあらずと云ひて、唯にエペソのみならず、殆ど全アジヤにわたり、多くの人々を説き勸めて惑したり、これ亦なんぢらの見 聞する所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'かくては啻に我らの職業の輕しめらるる恐あるのみならず、また大女神アルテミスの宮も蔑せられ、全アジヤ全世界のをがむ大女神の稜威も滅ぶるに至らん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, '彼 等これを聞きて憤恚に滿され、叫びて言ふ『大なる哉、エペソ人のアルテミス』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'かくて町 擧りて騷ぎ立ち、人々パウロの同行 者なるマケドニヤ人ガイオとアリスタルコとを捕へ、心を一つにして劇場に押入りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'パウロ集民のなかに入らんとしたれど、弟子たち許さず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, '又アジヤの祭の司のうちの或 者どもも彼と親しかりしかば、人を遣して劇場に入らぬやうにと勸めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'ここに會衆おほいに亂れ、大方はその何のために集りたるかを知らずして、或 者はこの事を、或 者はかの事を叫びたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, '遂に群衆の或 者ども、ユダヤ人の推し出したるアレキサンデルに勸めたれば、かれ手を搖かして集民に辯明をなさんとすれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, '其のユダヤ人たるを知り、みな同音に『おほいなる哉、エペソ人のアルテミス』と呼はりて二 時間ばかりに及ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, '時に書記役、群衆を鎭めおきて言ふ『さてエペソ人よ、誰かエペソの町が大女神アルテミス及び天より降りし像の宮守なることを知らざる者あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'これは言ひ消し難きことなれば、なんぢら靜なるべし、妄なる事を爲すべからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'この人々は宮の物を盜む者にあらず、我らの女 神を謗る者にもあらず、然るに汝ら之を曳き來れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'もしデメテリオ及び偕にをる細工人ら、人に就きて訴ふべき事あらば、裁判の日あり、かつ司あり、彼 等おのおの訴ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'もし又ほかの事につきて議する所あらば、正式の議會にて決すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, '我ら今日の騷擾につきては、何の理由もなきにより咎を受くる恐あり。この會合につきて言ひひらくこと能はねばなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, '斯く言ひて集會を散じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, '騷亂のやみし後、パウロ弟子たちを招きて勸をなし、之に別を告げ、マケドニヤに往かんとて出で立つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, '而して、かの地方を巡り多くの言をもて弟子たちを勸めし後、ギリシヤに到る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'そこに留ること三个月にして、シリヤに向ひて船出せんとする時、おのれを害はんとするユダヤ人らの計略に遭ひたれば、マケドニヤを經て歸らんと心を決む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, '之に伴へる人々はベレア人にしてプロの子なるソパテロ、テサロニケ人アリスタルコ及びセクンド、デルベ人ガイオ及びテモテ、アジヤ人テキコ及びトロピモなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, '彼らは先だちゆき、トロアスにて我らを待てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, '我らは除酵祭の後ピリピより船出し、五日にしてトロアスに著き、彼らの許に到りて七日のあひだ留れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, '一週の首の日われらパンを擘かんとて集りしが、パウロ明日いで立たんとて彼 等とかたり、夜半まで語り續けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, '集りたる高樓には多くの燈火ありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'ここにユテコといふ若者 窓に倚りて坐しゐたるが、甚く眠氣ざすほどに、パウロの語ること愈々 久しくなりたれば、遂に熟睡して三階より落つ。これを扶け起したるに、はや死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'パウロ降りて其の上に伏し、かき抱きて言ふ『なんぢら騷ぐな、生命はなほ内にあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, '乃ち復のぼりてパンを擘き、食してのち久しく語りあひ、夜明に至り遂に出でたてり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, '人々かの若者の活きたるを連れきたり、甚く慰藉を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'かくて我らは先だちて船に乘り、アソスにてパウロを載せんとして彼處に船出せり。彼は徒歩にて往かんとて斯くは定めたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, '我らアソスにてパウロを待ち迎へ、これを載せてミテレネに渡り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'また彼處より船出して翌日キヨスの彼方にいたり、次の日サモスに立ち寄り、その次の日ミレトに著く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'パウロ、アジヤにて時を費さぬ爲に、エペソには船を寄せずして過ぐることに定めしなり。これは成るべく五旬節の日エルサレムに在ることを得んとて急ぎしに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, '而してパウロ、ミレトより人をエペソに遣し、教會の長老たちを呼びて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'その來りし時かれらに言ふ『わがアジヤに來りし初の日より、如何なる状にて常に汝らと偕に居りしかは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, '即ち謙遜の限をつくし、涙を流し、ユダヤ人の計略によりて迫り來し艱難に耐へて主につかへ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, '益となる事は何くれとなく憚らずして告げ、公然にても家々にても汝らを教へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'ユダヤ人にもギリシヤ人にも、神に對して悔改め、われらの主イエスに對して信仰すべきことを證せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, '視よ、今われは心 搦められてエルサレムに往く。彼處にて如何なる事の我に及ぶかを知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'ただ聖 靈いづれの町にても我に證して、縲絏と患難と我を待てりと告げたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, '然れど我わが走るべき道程と、主イエスより承けし職、すなわち神の惠の福音を證する事とを果さん爲には、固より生命をも重んぜざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, '視よ、今われは知る、前に汝らの中を歴 巡りて御國を宣傳へし我が顏を、汝ら皆ふたたび見ざるべきを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'この故に、われ今日なんぢらに證す、われは凡ての人の血につきていさぎよし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, '我は憚らずして神の御旨をことごとく汝らに告げしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, '汝 等みづから心せよ、又すべての群に心せよ、聖 靈は汝 等を群のなかに立てて監督となし、神の己の血をもて買ひ給ひし教會を牧せしめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'われ知る、わが出で去るのち、暴き豺狼なんぢらの中に入りきたりて、群を惜まず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, '又なんぢらの中よりも、弟子たちを己が方に引き入れんとて、曲れることを語るもの起らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'されば汝ら目を覺しをれ。三年の間わが夜も晝も休まず、涙をもて汝 等おのおのを訓戒せしことを憶えよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'われ今なんぢらを、主および其の惠の御言に委ぬ。御言は汝らの徳を建て、すべての潔められたる者とともに嗣業を受けしめ得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, '我は人の金 銀・衣服を貪りし事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'この手は我が必要に供へ、また我と偕なる者に供へしことを汝 等みづから知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, '我すべての事に於て例を示せり、即ち汝らも斯く働きて、弱き者を助け、また主イエスの自ら言ひ給ひし「與ふるは受くるよりも幸福なり」との御言を記憶すべきなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, '斯く言ひて後、パウロ跪づきて一同とともに祈れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'みな大に歎きパウロの頸を抱きて接吻し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'そのふたたび我が顏を見ざるべしと云ひし言によりて特に憂ひ、遂に彼を船まで送りゆけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'ここに我ら人々と別れて船出をなし、眞直にはせてコスに到り、次の日ロドスにつき、彼處よりパタラにわたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, '此の處にてピニケにゆく船に遇ひ、これに乘りて船出す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'クプロを望み、之を左にして過ぎ、シリヤに向ひて進み、ツロに著きたり、此處にて船 荷を卸さんとすればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'かくて弟子たちに尋ね逢ひて七日 留れり。かれら御靈によりてパウロに、エルサレムに上るまじき事を云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, '然るに我ら七日 終りて後、いでて旅立ちたれば、彼 等みな妻 子とともに町の外まで送りきたり、諸共に濱邊に跪づきて祈り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, '相 互に別を告げて我らは船に乘り、彼らは家に歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'ツロをいでトレマイに到りて船路つきたり。此處にて兄弟たちの安否を訪ひ、かれらの許に一日 留り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, '明くる日ここを去りてカイザリヤにいたり、傳道者ピリポの家に入りて留る、彼はかの七人の一人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'この人に預言する四人の娘ありて、處女なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, '我ら數日 留り居るうちに、アガボと云ふ預言者ユダヤより下り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, '我らの許に來りてパウロの帶をとり、己が足と手とを縛りて言ふ『聖 靈かく言ひ給ふ「エルサレムにて、ユダヤ人この帶の主を斯くの如く縛りて異邦人の手に付さん」と』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'われら之を聞きて此の地の人々とともにパウロに、エルサレムに上らざらんことを勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'その時パウロ答ふ『なんぢら何ぞ歎きて我が心を挫くか、我エルサレムにて、主イエスの名のために、唯に縛らるるのみかは、死ぬることをも覺悟せり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, '斯く我らの勸告を納れるによりて『主の御意の如くなれかし』と言ひて止む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'この後われら行李を整へてエルサレムに上る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'カイザリヤに居る弟子も數人ともに往き、我らの宿らんとするクプロ人マナソンといふ舊き弟子のもとに案内したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'エルサレムに到りたれば、兄弟たち歡びて我らを迎へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, '翌日パウロ我らと共にヤコブの許に往きしに、長老たちみなあつまり居たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'パウロその安否を問ひて後、おのが勤勞によりて異邦人のうちに神の行ひ給ひしことを、一々 告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, '彼ら聞きて神を崇め、またパウロに言ふ『兄弟よ、なんぢの見るごとく、ユダヤ人のうち、信者となりたるもの數萬人あり、みな律法に對して熱心なる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, '彼らは、汝が異邦人のうちに居る凡てのユダヤ人に對ひて、その兒らに割禮を施すな、習慣に從ふなと云ひて、モーセに遠ざかることを教ふと聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, '如何にすべきか、彼らは必ず汝の來りたるを聞かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'されば汝われらの言ふ如くせよ、我らの中に誓願あるもの四人あり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, '汝かれらと組みて之とともに潔をなし、彼 等のために費を出して髮を剃らしめよ。さらば人々みな汝につきて聞きたることの虚僞にして、汝も律法を守りて正しく歩み居ることを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, '異邦人の信者となりたる者につきては、我ら既に書き贈りて、偶像に献げたる物と、血と、絞殺したる物と、淫行とに遠ざかるべき事を定めたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'ここにパウロその人々と組みて、次の日ともどもに潔をなして宮に入り、潔の期 滿ちて各人のために献物をささぐべき日を告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'かくて七日の終らんとする時、アジヤより來りしユダヤ人ら、宮の内にパウロの居るを見て、群衆を騷がし、かれに手をかけ叫びて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, '『イスラエルの人々 助けよ、この人はいたる處にて民と律法と此の所とに悖れることを人々に教ふる者なり、然のみならず、ギリシヤ人を宮に率き入れて、此の聖なる所をも汚したり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'からら曩にエペソ人トロピモがパウロとともに市中にゐたるを見て、パウロ之を宮に率き入れしと思ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'ここに市中みな騷ぎたち、民ども馳せ集り、パウロを捕へて宮の外に曳き出せり、かくて門は直ちに鎖されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, '彼らパウロを殺さんとせしとき、軍隊の千卒長に、エルサレム中さわぎ立てりとの事きこえたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'かれ速かに兵卒および百卒長らを率ゐて馳せ下る。かれら千卒長と兵卒とを見て、パウロを打つことを止む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, '千卒長、近よりてパウロを執へ、命じて二つの鏈にて繋がせ、その何 人なるか、何事をなしたるかを尋ぬるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, '群衆の中にて或 者はこの事を、或 者はかの事を呼はり、騷亂のために確なる事を知るに由なく、命じて陣營に曳き來らしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, '階段に至れるに、群衆の手暴きによりて、兵卒パウロを負ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'これ群れる民ども『彼を除け』と叫びつつ隨ひ迫れる故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'パウロ陣營に曳き入れられんとするとき、千卒長に言ふ『われ汝に語りて可きか』かれ言ふ『なんぢギリシヤ語を知るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, '汝はかのエジプト人にして、曩に亂を起して四千 人の刺客を荒野に率ゐ出でし者ならずや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'パウロ言ふ『我はキリキヤなるタルソのユダヤ人、鄙しからぬ市の市民なり。請ふ民に語るを許せ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, '之を許したれば、パウロ階段の上に立ち、民に對ひて手を搖かし、大に靜まれる時、ヘブルの語にて語りて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '『兄弟たち親たちよ、今なんぢらに對する辯明を聽け』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, '人々そのヘブルの語を語るを聞きてますます靜になりたれば、又いふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '『我はユダヤ人にてキリキヤのタルソに生れしが、此の都にて育てられ、ガマリエルの足下にて先祖たちの律法の嚴しき方に遵ひて教へられ、今日の汝らのごとく神に對して熱心なる者なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, '我この道を迫害し、男女を縛りて獄に入れ、死にまで至らしめしことは、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, '大 祭司も凡ての長老も我に就きて證するなり。我は彼 等より兄弟たちへの書を受けて、ダマスコに寓り居る者どもを縛り、エルサレムに曳き來りて罰を受けしめんとて彼處にゆけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, '往きてダマスコに近づきたるに、正午ごろ忽ち大なる光、天より出でて我を環り照せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'その時われ地に倒れ、かつ我に語りて「サウロ、サウロ、何ぞ我を迫害するか」といふ聲を聞き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, '「主よ、なんぢは誰ぞ」と答へしに「われは汝が迫害するナザレのイエスなり」と言ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, '偕に居る者ども光は見しが、我に語る者の聲は聞かざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'われ復いふ「主よ、我なにを爲すべきか」主いひ給ふ「起ちてダマスコに往け、なんぢの爲すべき定りたる事は彼處にて悉とく告げらるべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, '我は、かの光の晃耀にて目 見えずなりたれば、偕にをる者に手を引かれてダマスコに入りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'ここに律法に據れる敬虔の人にして、其の町に住む凡てのユダヤ人に令聞あるアナニヤという者あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, '彼われに來り傍らに立ちて「兄弟サウロよ、見ることを得よ」と言ひたれば、その時、仰ぎて彼を見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'かれ又いふ「我らの先祖の神は、なんぢを選びて御意を知らしめ、又かの義人を見、その御口の聲を聞かしめんとし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'これは汝の見 聞したる事につきて、凡ての人に對し彼の證人とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, '今なんぞ躊躇ふか、起て、その御名を呼び、バプテスマを受けて汝の罪を洗ひ去れ」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'かくて我エルサレムに歸り、宮にて祈りをるとき、我を忘れし心地して主を見 奉るに、我に斯く言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, '「なんぢ急げ、早くエルサレムを去れ、人々われに係る汝の證を受けぬ故なり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, '我いふ「主よ、我さきに汝を信ずる者を獄に入れ、諸 會堂にて之を扑ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, '又なんぢの證人ステパノの血の流されしとき、我もその傍らに立ちて之を可しとし、殺す者どもの衣を守りしことは、彼らの知る所なり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'われに言ひ給ふ「往け、我なんぢを遠く異邦人に遣すなり」と』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, '人々きき居たりしが、此の言に及び、聲を揚げて言ふ『斯くのごとき者をば地より除け、生かしおくべき者ならず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, '斯く叫びつつ其の衣を脱ぎすて、塵を空中に撒きたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, '千卒長、人々が何 故パウロにむかひて斯く叫び呼はるかを知らんとし、鞭うちて訊ぶることを命じて、彼を陣營に曳き入れしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, '革鞭をあてんとてパウロを引き張りし時、かれ傍らに立つ百卒長に言ふ『ロマ人たる者を罪も定めずして鞭うつは可きか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, '百卒長これを聞きて千卒長に往き、告げて言ふ『なんぢ何をなさんとするか、此の人はロマ人なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, '千卒長きたりて言ふ『なんぢはロマ人なるか、我に告げよ』かれ言ふ『然り』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, '千卒長こたふ『我は多くの金をもて此の民 籍を得たり』パウロ言ふ『我は生れながらなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'ここに訊べんとせし者どもは直ちに去り、千卒長はそのロマ人なるを知り、之を縛りしことを懼れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, '明くる日、千卒長かれが何 故ユダヤ人に訴へられしか、確なる事を知らんと欲して、彼の縛を解き、命じて祭司長らと全 議會とを呼び集め、パウロを曳き出して其の前に立たしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'パウロ議會に目を注ぎて言ふ『兄弟たちよ、我は今日に至るまで事 毎に良心に從ひて神に事へたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, '大 祭司アナニヤ傍らに立つ者どもに、彼の口を撃つことを命ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'ここにパウロ言ふ『白く塗りたる壁よ、神なんぢを撃ち給はん、なんぢ律法によりて我を審くために坐しながら、律法に悖りて我を撃つことを命ずるか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, '傍らに立つ者いふ『なんぢ神の大 祭司を罵るか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'パウロ言ふ『兄弟たちよ、我その大 祭司たることを知らざりき。録して「なんぢの民の司をそしる可からず」とあればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'かくてパウロ、その一部はサドカイ人、その一部はパリサイ人たるを知りて、議會のうちに呼はりて言ふ『兄弟たちよ、我はパリサイ人にしてパリサイ人の子なり、我は死人の甦へることの希望につきて審かるるなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, '斯く言ひしに因りて、パリサイ人とサドカイ人との間に紛爭おこりて、會衆 相 分れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'サドカイ人は復活もなく御使も靈もなしと言ひ、パリサイ人は兩ながらありと云ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, '遂に大なる喧噪となりて、パリサイ人の中の學者 數人たちて爭ひて言ふ『われら此の人に惡しき事あるを見ず、もし靈または御使かれに語りたるならば如何』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, '紛爭いよいよ激しくなりたれば、千卒長、パウロの彼らに引 裂かれんことを恐れ、兵卒どもに命じて下りゆかしめ、彼らの中より引取りて陣營に連れ來らしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'その夜、主パウロの傍らに立ちて言ひ給ふ『雄々しかれ、汝エルサレムにて我につきて證をなしたる如く、ロマにても證をなすべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, '夜明になりてユダヤ人、徒黨を組み盟約を立てて、パウロを殺すまでは飮食せじと言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'この徒黨を結びたる者は四十 人 餘なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, '彼らは祭司長・長老らに往きて言ふ『われらパウロを殺すまでは何をも味ふまじと堅く盟約を立てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'されば汝 等なほ詳細に訊べんとする状して、彼を汝らの許に連れ下らすることを、議會とともに千卒長に訴へよ。我等その近くならぬ間に殺す準備をなせり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'パウロの姉妹の子この待伏の事をきき、往きて陣營に入りパウロに告げたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'パウロ百卒長の一人を呼びて言ふ『この若者を千卒長につれ往け、告ぐる事あり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, '百卒長これを携へ、千卒長に至りて言ふ『囚人パウロ我を呼びて、この若者なんぢに言ふべき事ありとて、汝に連れ往くことを請へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, '千卒長その手を執り退きて、私に問ふ『われに告ぐる事とは何ぞ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, '若者いふ『ユダヤ人は、汝がパウロの事をなほ詳細に訊ぶる爲にとて、明日かれを議會に連れ下ることを汝に請はんと申合せたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, '汝その請に從ふな、彼らの中にて四十 人 餘の者、パウロを待伏せ、之を殺すまでは飮食せじと盟約を立て、今その準備をなして汝の許諾を待てり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'ここに千卒長、若者に『これらの事を我に訴へたりと誰にも語るな』と命じて歸せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'さて百卒長を兩 三人よびて言ふ『今夜 九時ごろカイザリヤに向けて往くために、兵卒 二 百、騎兵 七 十、槍をとる者 二 百を整へよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'また畜を備へ、パウロを乘せて安全に總督ペリクスの許に護送することを命じ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'かつ左のごとき書をかき贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '『クラウデオ・ルシヤ謹みて總督ペリクス閣下の平安を祈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'この人はユダヤ人に捕へられて殺されんとせしを、我そのロマ人なるを聞き、兵卒どもを率ゐ往きて救へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'ユダヤ人の彼を訴ふる理由を知らんと欲して、その議會に引き往きたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, '彼らの律法の問題につき訴へられたるにて、死もしくは縛に當る罪の訴訟にあらざるを知りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, '又この人を害せんとする謀計ありと我に聞えたれば、われ俄にこれを汝のもとに送り、これを訴ふる者に、なんぢの前にて彼を訴へんことを命じたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'ここに兵卒ども命ぜられたる如くパウロを受けとりて、夜中アンテパトリスまで連れてゆき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, '翌日これを騎兵に委ね、ともに往かしめて陣營に歸れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, '騎兵はカイザリヤに入り、總督に書をわたし、パウロを其の前に立たしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, '總督、書を讀みて、パウロのいづこの國の者なるかを問ひ、そのキリキヤ人なるを知りて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, '『汝を訴ふる者の來らんとき、尚つまびらかに汝のことを聽かん』と言ひ、かつ命じて、ヘロデでの官邸に之を守らしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, '五日ののち、大 祭司アナニヤ數人の長老およびテルトロと云ふ辯護士とともに下りて、パウロを總督に訴ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'パウロ呼び出されたれば、テルトロ訴へ出でて言ふ『ペリクス閣下よ、われらは汝によりて太平を樂しみ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'なんぢの先見によりて、此の國人のために時に隨ひ處に隨ひて、惡しき事の改められたるを感謝して罷まず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'ここに喃々しく陳べて汝を妨ぐまじ、願はくは寛容をもて我が少しの言を聽け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, '我等この人を見るに、恰も疫病のごとくにて、全世界のユダヤ人のあひだに騷擾をおこし、且ナザレ人の異端の首にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, '宮をさへ瀆さんとしたれば、之を捕へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, '汝この人に就きて訊さば、我らの訴ふる所をことごとく知り得べし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'ユダヤ人も之に加へて、誠にその如くなりと主張す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, '總督、首にて示しパウロに言はしめたれば、答ふ『なんぢが年 久しくこの國人の審判 人たることを我は知るゆゑに、喜びて我が辯明をなさん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'なんぢ知り得べし、我が禮拜のためにエルサレムに上りてより僅か十二 日に過ぎず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'また彼らは、我が宮にても會堂にても市中にても、人と爭ひ群衆を騷がしたるを見ず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'いま訴へたる我が事につきても證明すること能はざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, '我ただ此の一事を汝に言ひあらはさん、即ち我は彼らが異端と稱ふる道に循ひて、我が先祖たちの神につかへ、律法と預言者の書とに録したる事をことごとく信じ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'かれら自らも待てるごとく、義者と不義者との復活あるべしと、神を仰ぎて望を懷くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'この故に、われ常に神と人とに對して良心の責なからんことを勉む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, '我は多くの年を經てのち歸りきたり、我が民に施濟をなし、また献物をささげゐたりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'その時かれらは我が潔をなして宮にをるを見たるのみにて、群衆もなく騷擾もなかりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, '然るにアジアより來れる數人のユダヤ人ありて――もし我に咎むべき事あらば、彼らが汝の前に出でて訴ふることを爲べきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, '或はまた此處なる人々、わが先に議會に立ちしとき、我に何の不義を認めしか言へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, '唯われ彼らの中に立ちて「死人の甦へる事につきて我けふ汝らの前にて審かる」と呼はりし一言の他には何もなかるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'ペリクスこの道のことを詳しく知りたれば、審判を延して言ふ『千卒長ルシヤの下るを待ちて汝らの事を定むべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'かくて百卒長に命じパウロを守らせ、寛かならしめ、かつ友の之に事ふるをも禁ぜざらしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, '數日の後ペリクス、その妻なるユダヤ人の女ドルシラとともに來り、パウロを呼びよせてキリスト・イエスに對する信仰のことを聽き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'パウロが正義と節制と來らんとする審判とにつきて論じたる時、ペリクス懼れて答ふ『今は去れ、よき機を得てまた招かん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'かくてパウロより金を與へられんことを望みて、尚しばしば彼を呼びよせては語れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, '二年を經てポルシオ・フェスト、ペリクスの任に代りしが、ペリクス、ユダヤ人の意を迎へんとして、パウロを繋ぎたるままに差措けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'フェスト任國にいたりて三日の後、カイザリヤよりエルサレムに上りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, '祭司長ら及びユダヤ人の重立ちたる者ども、パウロを訴へ之を害はんとして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'フェストの好意にて彼をエルサレムに召し出されんことを願ふ。斯くして道に待伏し、之を殺さんと思へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, '然るにフェスト答へて、パウロのカイザリヤに囚はれ在ることと、己が程なく歸るべき事とを告げ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '『もし彼に不 善あらんには、汝 等のうち然るべき者ども我とともに下りて訴ふべし』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'かくて彼處に八日 十日ばかり居りてカイザリヤに下り、明くる日、審判の座に坐し、命じてパウロを引出さしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'その出で來りし時、エルサレムより下りしユダヤ人ら、これを取圍みて樣々の重き罪を言ひ立てて訴ふれども、證すること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'パウロは辯明して言ふ『我はユダヤ人の律法に對しても、宮に對しても、カイザルに對しても、罪を犯したる事なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'フェスト、ユダヤ人の意を迎へんとしてパウロに答へて言ふ『なんぢエルサレムに上り、彼處にて我が前に審かるることを諾ふか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'パウロ言ふ『我はわが審かるべきカイザルの審判の座の前に立ちをるなり。汝の能く知るごとく、我はユダヤ人を害ひしことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, '若しも罪を犯して死に當るべき事をなしたらんには、死ぬるを厭はじ。然れど此の人々の訴ふること實ならずば、誰も我を彼らに付すことを得じ、我はカイザルに上訴せん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'ここにフェスト陪席の者と相 議りて答ふ『なんぢカイザルに上訴せんとす、カイザルの許に往くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, '數日を經て後、アグリッパ王とベルニケとカイザリヤに到りてフェストの安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, '多くの日 留りゐたれば、フェスト、パウロのことを王に告げて言ふ『ここにペリクスが囚人として遺しおきたる一人の人あり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, '我エルサレムに居りしとき、ユダヤ人の祭司長・長老ら之を訴へて罪に定めんことを願ひしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, '我は答へて、訴へらるる者の未だ訴ふる者の面前にて辯明する機を與へられぬ前に付すは、ロマ人の慣例にあらぬ事を告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'この故に彼 等ここに集りたれば、時を延さず次の日 審判の座に坐し、命じてかの者を引出さしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, '訴ふる者かれを圍みて立ちしが、思ひしごとき惡しき事は一つも陳ぶる所なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'ただ己らの宗教、またはイエスと云ふ者の死にたるを活きたりと、パウロが主張するなどに關する問題のみなれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'かかる審理には我も當惑せし故、かの人に「なんぢエルサレムに往き彼處にて審かるる事を好むか」と問ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'パウロは上訴して皇帝の判決を受けん爲に守られんことを願ひしにより、命じて之をカイザルに送るまで守らせ置けり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'アグリッパ、フェストに言ふ『我もその人に聽かんと欲す』フェスト言ふ『なんぢ明日かれに聽くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, '明くる日アグリッパとベルニケと大に威儀を整へてきたり、千卒長ら及び市の重立ちたる者どもと共に訊問所に入りたれば、フェストの命によりてパウロ引出さる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'フェスト言ふ『アグリッパ王、竝びに此處に居る凡ての者よ、汝らの見るこの人は、ユダヤの民衆が擧りて生かしおくべきにあらずと呼はりて、エルサレムにても此處にても我に訴へし者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, '然るに我はその死に當るべき惡しき事を一つだに犯したるを認めねば、彼の自ら皇帝に上訴せんとする隨にその許に送らんと決めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, '而して彼につきて我が主に上書すべき實 情を得ず。この故に汝 等のまへ、特にアグリッパ王よ、なんぢの前に引出し、訊問をなしてのち、上書すべき箇條を得んと思へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, '囚人を送るに訴訟の次第を陳べざるは道理ならずと思ふ故なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'アグリッパ、パウロに言ふ『なんぢは自己のために陳ぶることを許されたり』ここにパウロ手を伸べ、辯明して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '『アグリッパ王よ、我ユダヤ人より訴へられし凡ての事につきて、今日なんぢらの前に辯明するを我が幸福とす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, '汝がユダヤ人の凡ての習慣と問題とを知るによりて殊に然りとす。されば請ふ、忍びて我に聽け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'わが始より國人のうちに又エルサレムに於ける幼き時よりの生活の状は、ユダヤ人のみな知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, '彼 等もし證せんと思はば、わが我らの宗教の最も嚴しき派に從ひて、パリサイ人の生活をなしし事を始より知れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, '今わが立ちて審かるるは、神が我らの先祖たちに約束し給ひしことの希望に因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, '之を得んことを望みて、我が十二の族は夜も晝も熱心に神に事ふるなり。王よ、この希望につきて、我はユダヤ人に訴へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, '神は死人を甦へらせ給ふとも、汝 等なんぞ信じ難しとするか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, '我も曩にはナザレ人イエスの名に逆ひて樣々の事をなすを宜きことと自ら思へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, '我エルサレムにて之をおこなひ、祭司長らより權威を受けて多くの聖徒を獄にいれ、彼らの殺されし時これに同意し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, '諸 教會堂にてしばしば彼らを罰し、強ひて瀆言を言はしめんとし、甚だしく狂ひ、迫害して外國の町にまで至れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, '此のとき祭司長らより權威と委任とを受けてダマスコに赴きしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, '王よ、その途にて正午ごろ天よりの光を見たり、日にも勝りて輝き、我と伴侶とを圍み照せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, '我等みな地に倒れたるに、ヘブルの語にて「サウロ、サウロ、何ぞ我を迫害するか、刺ある策を蹴るは難し」といふ聲を我きけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'われ言ふ「主よ、なんぢは誰ぞ」主いひ給ふ「われは汝が迫害するイエスなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, '起きて汝の足にて立て、わが汝に現れしは、汝をたてて其の見しことと我が汝に現れて示さんとする事との役者また證人たらしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, '我なんぢを此の民および異邦人より救はん、又なんぢを彼らに遣し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'その目をひらきて暗より光に、サタンの權威より神に立ち歸らせ、我に對する信仰によりて罪の赦と潔められたる者のうちの嗣業とを得しめん」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'この故にアグリッパ王よ、われは天よりの顯示に背かずして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, '先づダマスコに居るもの、次にエルサレム及びユダヤ全國、また異邦人にまで、悔改めて神に立ちかへり、其の悔改にかなふ業をなすべきことを宣傅へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, '之がためにユダヤ人われを宮にて捕へ、かつ殺さんとせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, '然るに神の祐によりて今日に至るまで尚 存へて、小なる人にも大なる人にも證をなし、言ふところは預言者およびモーセが必ず來るべしと語りしことの外ならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, '即ちキリストの苦難を受くべきこと、最先に死人の中より甦へる事によりて、民と異邦人とに光を傳ふべきこと是なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'パウロ斯く辯明しつつある時、フェスト大聲に言ふ『パウロよ、なんぢ狂氣せり、博學なんぢを狂氣せしめたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'パウロ言ふ『フェスト閣下よ、我は狂氣せず、宣ぶる所は眞にして慥なる言なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, '王は此 等のことを知るゆゑに、我その前に憚らずして語る。これらの事は片隅に行はれたるにあらねば、一つとして王の眼に隱れたるはなしと信ずるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'アグリッパ王よ、なんぢ預言者の書を信ずるか、我なんぢの信ずることを知る』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'アグリッパ、パウロに言ふ『なんぢ説くこと僅にして我をキリステアンたらしめんとするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'パウロ言ふ『説くことの僅なるにもせよ、多きにもせよ、神に願ふは、啻に汝のみならず、凡て今日われに聽ける者の、この縲絏なくして我がごとき者とならんことなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'ここに王も總督もベルニケも、列座の者どもも皆ともに立つ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, '退きてのち相 語りて言ふ『この人は死罪または縲絏に當るべき事をなさず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'アグリッパ、フェストに言ふ『この人カイザルに上訴せざりしならば釋さるべかりしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'すでに我等をイタリヤに渡らしむること決りたれば、パウロ及びその他 數人の囚人を、近衞 隊の百卒長ユリアスと云ふ人に付せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'ここに我らアジヤの海邊なる各處に寄せゆくアドラミテオの船の出帆せんとするに乘りて出づ。テサロニケのマケドニヤ人アリスタルコも我らと共にありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, '次の日シドンに著きたれば、ユリアス懇切にパウロを遇ひ、その友らの許にゆきて歡待を受くることを許せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'かくて此處より船出せしが、風の逆ふによりてクプロの風下の方をはせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'キリキヤ及びパンフリヤの沖を過ぎてルキヤのミラに著く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, '彼處にてイタリヤにゆくアレキサンデリヤの船に遇ひたれば、百卒長われらを之に乘らしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, '多くの日のあひだ船の進み遲く、辛うじてクニドに對へる處に到りしが、風に阻へられてサルモネの沖を過ぎ、クレテの風下の方をはせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, '陸に沿ひ辛うじて良き港といふ處につく。その近き處にラサヤの町あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, '船路 久しきを歴て、斷食の期節も既に過ぎたれば、航海 危きにより、パウロ人々に勸めて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, '『人々よ、我この航海の害あり損 多くして、ただ積荷と船とのみならず、我らの生命にも及ぶべきを認む』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'されど百卒長は、パウロの言ふ所よりも船 長と船 主との言を重んじたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, '且この港は冬を過すに不便なるより、多數の者も、なし得んにはピニクスに到り、彼處にて冬を過さんとて、此處を船出するを可しとせり。ピニクスはクレテの港にて東 北と東 南とに向ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, '南 風おもむろに吹きたれば、彼ら志望を得たりとして錨をあげ、クレテの岸邊に沿ひて進みたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, '幾程もなくユーラクロンといふ疾風その島より吹きおろし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, '之がために船は吹き流され、風に向ひて進むこと能はねば、船は風の追ふに任す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'クラウダといふ小島の風下の方にいたり、辛うじて小艇を收め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'これを船に引上げてのち、備綱にて船體を卷き縛り、またスルテスの洲に乘りかけんことを恐れ、帆を下して流る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'いたく暴風に惱され、次の日、船の者ども積荷を投げすて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, '三日めに手づから船具を棄てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, '數日のあひだ日も星も見えず、暴風はげしく吹き荒びて、我らの救はるべき望ついに絶え果てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, '人々の食せぬこと久しくなりたる時、パウロその中に立ちて言ふ『人々よ、なんぢら前に我が勸をきき、クレテより船出せずして、この害と損とを受けずあるべき筈なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'いま我なんぢらに勸む、心 安かれ、汝 等のうち一人だに生命をうしなふ者なし、ただ船を失はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'わが屬するところ我が事ふる所の神の使、昨夜わが傍らに立ちて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, '「パウロよ、懼るな、なんぢ必ずカイザルの前に立たん、視よ、神は汝と同船する者をことごとく汝に賜へり」と云ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'この故に人々よ、心 安かれ、我はその我に語り給ひしごとく必ず成るべしと神を信ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, '而して我らは或 島に推上げらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'かくて十 四日めの夜に至りて、アドリヤの海を漂ひゆきたるに、夜半ごろ水夫ら陸に近づきたりと思ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, '水を測りたれば、二 十 尋なるを知り、少しく進みてまた測りたれば、十 五 尋なるを知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, '岩に乘り上げんことを恐れて、艫より錨を四つ投して夜明を待ちわぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, '然るに水夫ら船より逃れ去らんと欲し、舳より錨を曳きゆくに言 寄せて小艇を海に下したれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'パウロ、百卒長と兵卒らとに言ふ『この者ども若し船に留らずば、汝ら救はるること能はず』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'ここに兵卒ら小艇の綱を斷切りて、その流れゆくに任す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, '夜の明けんとする頃、パウロ凡ての人に食せんことを勸めて言ふ『なんぢら待ち待ちて食事せぬこと今日にて十 四日なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'されば汝らに食せんことを勸む、これ汝らが救のためなり、汝らの頭髮 一筋だに首より落つる事なし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, '斯く言ひて後みづからパンを取り、一同の前にて神に謝し、擘きて食し始めたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, '人々もみな心を安んじて食したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, '船に居る我らは凡て二 百 七 十 六 人なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, '人々 食し飽きてのち、穀物を海に投げ棄てて船を輕くせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, '夜明になりて、孰の土地かは知らねど、砂濱の入江を見出し、なし得べくば此處に船を寄せんと相 議り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, '錨を斷ちて海に棄つるとともに、舵纜をゆるめ舳の帆を揚げて、風にまかせつつ砂濱さして進む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, '然るに潮の流れあふ處にいたりて船を淺瀬に乘り上げたれば、舳 膠著きて動かず、艫は浪の激しきに破れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, '兵卒らは囚人の泳ぎて逃れ去らんことを恐れ、これを殺さんと議りしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, '百卒長パウロを救はんと欲して、その議るところを阻み、泳ぎうる者に命じ、海に跳び入りてまず上陸せしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'その他の者をば或は板あるひは船の碎片に乘らしむ。斯くしてみな上陸して救はるるを得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'われら救はれて後、この島のマルタと稱ふるを知れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, '土人ら一方ならぬ情を我らに表し、降りしきる雨と寒氣とのために、火を焚きて我ら一同を待遇せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'パウロ柴を束ねて火にくべたれば、熱によりて蝮いでて其の手につく。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, '蛇のその手に懸りたるを土人ら見て互に言ふ『この人は必ず殺人者なるべし、海より救はれしも、天道はその生くるを容さぬなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'パウロ蛇を火のなかに振り落して何の害をも受けざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, '人々は彼が腫れ出づるか、または忽ち倒れ死ぬるならんと候ふ。久しく窺ひたれど、聊かも害を受けぬを見て、思を變へて、此は神なりと言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'この處の邊に島司のもてる土地あり、島司の名はポプリオといふ。此の人われらを迎へて懇切に三日の間もてなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'ポプリオの父、熱と痢病とに罹りて臥し居たれば、パウロその許にいたり、祈りかつ手を按きて醫せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'この事ありてより、島の病める人々みな來りて醫されたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, '禮を厚くして我らを敬ひ、また船出の時には必要なる品々を贈りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, '三月の後、われらはこの島に冬籠せしデオスクリの號あるアレキサンデリヤの船にて出で、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'シラクサにつきて三日とまり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, '此處より繞りてレギオンにいたり、一日を過ぎて南 風ふき起りたれば、我ら二日めにポテオリに著き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, '此處にて兄弟たちに逢ひ、その勸によりて七日のあひだ留り、而して遂にロマに往く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'かしこの兄弟たち我らの事をききて、アピオポロおよびトレスタベルネまで來りて我らを迎ふ。パウロこれを見て神に感謝し、その心 勇みたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, '我らロマに入りて後、パウロは己を守る一人の兵卒とともに別に住むことを許さる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, '三日すぎてパウロ、ユダヤ人の重立ちたる者を呼び集む。その集りたる時これに言ふ『兄弟たちよ、我はわが民わが先祖たちの慣例に悖ることを一つも爲さざりしに、エルサレムより囚人となりて、ロマ人の手に付されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'かれら我を審きて死に當ることなき故に、我を釋さんと思ひしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'ユダヤ人さからひたれば、餘義なくカイザルに上訴せり。然れど我が國人を訴へんとせしにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'この故に我なんぢらに會ひ、かつ共に語らんことを願へり、我はイスラエルの懷く希望の爲にこの鎖に繋がれたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'かれら言ふ『われら汝につきてユダヤより書を受けず、また兄弟たちの中より來りて、汝の善からぬ事を告げたる者も、語りたる者もなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'ただ我らは汝の思ふところを聞かんと欲するなり。それは此の宗旨の到る處にて非 難せらるるを知ればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'ここに日を定めて多くの人パウロの宿に來りたれば、パウロ朝より夕まで神の國のことを説明して證をなし、かつモーセの律法と預言者の書とを引きてイエスのことを勸めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'パウロのいふ言を或 者は信じ、或 者は信ぜず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, '互に相 合はずして退かんとしたるに、パウロ一言を述べて言ふ『宜なるかな、聖 靈は預言者イザヤによりて汝らの先祖たちに語り給へり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, '「なんぢらこの民に往きて言へ、なんぢら聞きて聞けども悟らず、見て見れども認めず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'この民の心はにぶく、耳は聞くにものうく、目は閉ぢたればなり。これ目にて見、耳にて聞き、心にてさとり、ひるがへりて我に醫さるることなからん爲なり」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, '然れば汝ら知れ、神のこの救は異邦人に遣されたり、彼らは之を聽くべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'パウロは滿 二年のあひだ、己が借り受けたる家に留り、その許にきたる凡ての者を迎へて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, '更に臆せずまた妨げられずして、神の國をのべ、主イエス・キリストの事を教へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'キリスト・イエスの僕、召されて使徒となり、神の福音のために選び別たれたるパウロ――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'この福音は神その預言者たちにより、聖書の中に預じめ御子に就きて約し給ひしものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, '御子は肉によれば、ダビデの裔より生れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, '潔き靈によれば、死人の復活により大能をもて神の子と定められ給へり、即ち我らの主イエス・キリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, '我等その御名の爲にもろもろの國人を信仰に從順ならしめんとて、彼より恩惠と使徒の職とを受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, '汝 等もその中にあり、てイエス・キリストの有とならん爲に召されたるなり。――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'われ書をロマに在りて神に愛せられ、召されて聖徒となりたる凡ての者に贈る。願はくは我らの父なる神および主イエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, '汝らの信仰、全世界に言ひ傳へられたれば、我まづ汝ら一同の爲にイエス・キリストによりて我が神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'その御子の福音に於て我が靈をもて事ふる神は、わが絶えず祈のうちに汝らを覺え、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, '如何にしてか御意に適ひ、いつか汝らに到るべき途を得んと、常に冀がふことを我がために證し給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'われ汝らを見んことを切に望むは、汝らの堅うせられん爲に靈の賜物を分け與へんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, '即ち我なんぢらの中にありて、互の信仰により相 共に慰められん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, '兄弟よ、我ほかの異邦人の中より得しごとく、汝らの中よりも實を得んとて、屡次なんぢらに往かんとしたれど、今に至りてなほ妨げらる、此の事を汝らの知らざるを欲せず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, '我はギリシヤ人にも夷人にも、智き者にも愚なる者にも負債あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'この故に我はロマに在る汝らにも福音を宣傳へんことを頻りに願ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, '我は福音を恥とせず、この福音はユダヤ人を始めギリシヤ人にも、凡て信ずる者に救を得さする神の力たればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, '神の義はその福音のうちに顯れ、信仰より出でて信仰に進ましむ。録して『義人は信仰によりて生くべし』とある如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'それ神の怒は、不義をもて眞理を阻む人の、もろもろの不虔と不義とに對ひて天より顯る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'その故は、神につきて知り得べきことは彼らに顯著なればなり、神これを顯し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'それ神の見るべからざる永遠の能力と神性とは、造られたる物により世の創より悟りえて明かに見るべければ、彼ら言ひ遁るる術なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, '神を知りつつも尚これを神として崇めず、感謝せず、その念は虚しく、その愚なる心は暗くなれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, '自ら智しと稱へて愚となり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, '朽つることなき神の榮光を易へて、朽つべき人および禽獸・匍ふ物に似たる像となす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'この故に神は彼らを其の心の慾にまかせて、互にその身を辱しむる汚穢に付し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, '彼らは神の眞を易へて虚僞となし、造物主を措きて造られたる物を拜し、且これに事ふ、造物主は永遠に讃むべき者なり、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, '之によりて神は彼らを恥づべき慾に付し給へり。即ち女は順性の用を易へて逆性の用となし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, '男もまた同じく女の順性の用を棄てて互に情 慾を熾し、男と男と恥づることを行ひて、その迷に値すべき報を己が身に受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'また神を心に存むるを善しとせざれば、神もその邪曲なる心の隨に爲まじき事をするに任せ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, '即ちもろもろの不義・惡・慳貪・惡意にて滿つる者、また嫉妬・殺意・紛爭・詭計・惡念の溢るる者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, '讒言する者・謗る者・神に憎まるる者・侮る者・高ぶる者・誇る者・惡事を企つる者・父母に逆ふ者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, '無知・違約・無情・無 慈悲なる者にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'かかる事どもを行ふ者の死罪に當るべき神の定を知りながら、啻に自己これらの事を行ふのみならず、また人の之を行ふを可しとせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'されば凡て人を審く者よ、なんぢ言ひ遁るる術なし、他の人を審くは、正しく己を罪するなり。人をさばく汝もみづから同じ事を行へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'かかる事をおこなふ者を罪する神の審判は眞理に合へりと我らは知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'かかる事をおこなふ者を審きて自己これを行ふ人よ、なんぢ神の審判を遁れんと思ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, '神の仁慈なんぢを悔改に導くを知らずして、その仁慈と忍耐と寛容との豐なるを輕んずるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'なんぢ頑固と悔改めぬ心とにより、己のために神の怒を積みて、その正しき審判の顯るる怒の日に及ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, '神はおのおのの所作に隨ひて報い、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, '耐へ忍びて善をおこない光榮と尊貴と朽ちざる事とを求むる者には、永遠の生命をもて報い、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, '徒黨により眞理に從はずして不義にしたがう者には、怒と憤恚とをもて報い給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'すべて惡をおこなふ人には、ユダヤ人を始めギリシヤ人にも患難と苦難とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, '凡て善をおこなふ人には、ユダヤ人を始めギリシヤ人にも光榮と尊貴と平安とあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'そは神には偏り視 給ふこと無ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, '凡そ律法なくして罪を犯したる者は律法なくして滅び、律法ありて罪を犯したる者は律法によりて審かるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '律法を聞くもの神の前に義たるにあらず、律法をおこなふ者のみ義とせらるべし。――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, '律法を有たぬ異邦人、もし本性のまま律法に載せたる所をおこなふ時は、律法を有たずともおのづから己が律法たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, '即ち律法の命ずる所のその心に録されたるを顯し、おのが良心もこれを證をなして、その念、たがひに或は訴へ或は辯明す。――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, '是わが福音に云へる如く、神のキリスト・イエスによりて人々の隱れたる事を審きたまふ日に成るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, '汝ユダヤ人と稱へられ、律法に安んじ、神を誇り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'その御意を知り、律法に教へられて善惡を辨へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'また律法のうちに知識と眞理との式を有てりとして、盲人の手引、暗黒にをる者の光明、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, '愚なる者の守役、幼兒の教師なりと自ら信ずる者よ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, '何ゆゑ人に教へて己を教へぬか、竊む勿れと宣べて自ら竊むか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, '姦淫する勿れと言ひて姦淫するか、偶像を惡みて宮の物を奪ふか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, '律法に誇りて律法を破り神を輕んずるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, '録して『神の名は汝らの故によりて異邦人の中に涜さる』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'なんぢ律法を守らば割禮は益あり、律法を破らば汝の割禮は無 割禮となるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, '割禮なき者も律法の義を守らば、その無 割禮は割禮とせらるるにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, '本性のまま割禮なくして律法を全うする者は、儀文と割禮とありてなほ律法をやぶる汝を審かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'それ表面のユダヤ人はユダヤ人たるにあらず、肉に在る表面の割禮は割禮たるにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, '隱なるユダヤ人はユダヤ人なり、儀文によらず、靈による心の割禮は割禮なり、その譽は人よりにあらず、神より來るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'さらばユダヤ人に何の優るる所ありや、また割禮に何の益ありや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, '凡ての事に益おほし、先づ第一に彼らは神の言を委ねられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'されど如何ん、ここに信ぜざる者ありとも、その不 信は神の眞實を廢つべきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, '決して然らず、人をみな虚僞 者とすとも神を誠實とすべし。録して『なんぢは其の言にて義とせられ、審かるるとき勝を得給はん爲なり』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, '然れど若し我らの不義は神の義を顯すとせば何と言はんか、怒を加へたまふ神は不義なるか(こは人の言ふごとく言ふなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, '決して然らず、若し然あらば神は如何にして世を審き給ふべき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'わが虚僞によりて神の誠實いよいよ顯れ、その榮光とならんには、いかで我なほ罪人として審かるる事あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'また『善を來らせん爲に惡をなすは可からずや』(或 者われらを譏りて之を我らの言なりといふ)かかる人の罪に定めらるるは正し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'さらば如何ん、我らの勝る所ありや、有ることなし。我ら既にユダヤ人もギリシヤ人もみな罪の下に在りと告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, '録して『義人なし、一人だになし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, '聰き者なく、神を求むる者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'みな迷ひて相 共に空しくなれり、善をなす者なし、一人だになし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, '彼らの咽は開きたる墓なり、舌には詭計あり、口唇のうちには蝮の毒あり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'その口は詛と苦とにて滿つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'その足は血を流すに速し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, '破壞と艱難とその道にあり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, '彼らは平和の道を知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'その眼前に神をおそるる畏なし』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'それ律法の言ふところは律法の下にある者に語ると我らは知る、これは凡ての口ふさがり、神の審判に全世界の服せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, '律法の行爲によりては、一人だに神のまへに義とせられず、律法によりて罪は知らるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, '然るに今や律法の外に神の義は顯れたり、これ律法と預言者とに由りて證せられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'イエス・キリストを信ずるに由りて凡て信ずる者に與へたまふ神の義なり。之には何 等の差別あるなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, '凡ての人、罪を犯したれば神の榮光を受くるに足らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, '功なくして神の恩惠により、キリスト・イエスにある贖罪によりて義とせらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, '即ち神は忍耐をもて過來しかたの罪を見遁し給ひしが、己の義を顯さんとて、キリストを立て、その血によりて信仰によれる宥の供物となし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'これ今おのれの義を顯して、自ら義たらん爲、またイエスを信ずる者を義とし給はん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'さらば誇るところ何處にあるか。既に除かれたり、何の律法に由りてか、行爲の律法か、然らず、信仰の律法に由りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, '我らは思ふ、人の義とせらるるは、律法の行爲によらず、信仰に由るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, '神はただユダヤ人のみの神なるか、また異邦人の神ならずや、然り、また異邦人の神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, '神は唯一にして、割禮ある者を信仰によりて義とし、割禮なき者をも信仰によりて義とし給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, '然らば我ら信仰をもて律法を空しくするか、決して然らず、反つて律法を堅うするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'さらば我らの先祖アブラハムは肉につきて何を得たりと言はんか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'アブラハム若し行爲によりて義とせられたらんには誇るべき所あり、然れど神の前には有ることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, '聖書に何と云へるか『アブラハム神を信ず、その信仰を義と認められたり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'それ働く者への報酬は恩惠といはず、負債と認めらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'されど働く事なくとも、敬虔ならぬ者を義としたまふ神を信ずる者は、その信仰を義と認めらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'ダビデもまた行爲なくして神に義と認めらるる人の幸福につきて斯く云へり。曰く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '『不法を免され、罪を蔽はれたる者は幸福なるかな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, '主が罪を認め給はぬ人は幸福なるかな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'されば此の幸福はただ割禮ある者にのみあるか、また割禮なき者にもあるか、我らは言ふ『アブラハムはその信仰を義と認められたり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, '如何なるときに義と認められたるか、割禮ののちか、無 割禮のときか、割禮の後ならず、無 割禮の時なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, '而して無 割禮のときの信仰によれる義の印として割禮の徽を受けたり、これ無 割禮にして信ずる凡ての者の義と認められん爲に、その父となり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'また割禮のみに由らず、我らの父アブラハムの無 割禮のときの信仰の跡をふむ割禮ある者の父とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'アブラハム世界の世嗣たるべしとの約束を、アブラハムとその裔との與へられしは、律法に由らず、信仰の義に由れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'もし律法による者ども世嗣たらば、信仰は空しく約束は廢るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'それ律法は怒を招く、律法なき所には罪を犯すこともなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'この故に世嗣たることの恩惠に干らんために信仰に由るなり、是かの約束のアブラハムの凡ての裔、すなわち律法による裔のみならず、彼の信仰に效ふ裔にも堅うせられん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '彼はその信じたる所の神、すなはち死人を活し、無きものを有るものの如く呼びたまふ神の前にて、我等すべての者の父たるなり。録して『われ汝を立てて多くの國人の父とせり』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, '彼は望むべくもあらぬ時になほ望みて信じたり、是なんぢの裔はかくの如くなるべしと言ひ給ひしに隨ひて、多くの國人の父とならん爲なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'かくて凡そ百歳に及びて己が身の死にたるがごとき状なると、サラの胎の死にたるが如きとを認むれども、その信仰よわらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, '不 信をもて神の約束を疑はず、信仰により強くなりて神に榮光を歸し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'その約し給へることを、成し得給ふと確信せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, '之に由りて其の信仰を義と認められたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, '斯く『義と認められたり』と録したるは、アブラハムの爲のみならず、また我らの爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, '我らの主イエスを死人の中より甦へらせ給ひし者を信ずる我らも、その信仰を義と認められん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, '主は我らの罪のために付され、我らの義とせられん爲に甦へらせられ給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, '斯く我ら信仰によりて義とせられたれば、我らの主イエス・キリストに頼り、神に對して平和を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'また彼により信仰によりて、今 立つところの恩惠に入ることを得、神の榮光を望みて喜ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, '然のみならず患難をも喜ぶ、そは患難は忍耐を生じ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, '忍耐は練達を生じ、練達は希望を生ずと知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, '希望は恥を來らせず、我らに賜ひたる聖 靈によりて神の愛われらの心に注げばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, '我等のなほ弱かりし時、キリスト定りたる日に及びて、敬虔ならぬ者のために死に給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'それ義人のために死ぬるもの殆どなし、仁者のためには死ぬることを厭はぬ者もやあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, '然れど我等がなほ罪人たりし時、キリスト我等のために死に給ひしに由りて、神は我らに對する愛をあらはし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, '斯く今その血に頼りて我ら義とせられたらんには、まして彼によりて怒より救はれざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, '我等もし敵たりしとき御子の死に頼りて神と和ぐことを得たらんには、まして和ぎて後その生命によりて救はれざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, '然のみならず今われらに和睦を得させ給へる我らの主イエス・キリストに頼りて神を喜ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'それ一人の人によりて罪は世に入り、また罪によりて死は世に入り、凡ての人 罪を犯しし故に、死は凡ての人に及べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, '律法のきたる前にも罪は世にありき、されど律法なくば罪は認めらるること無し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, '然るにアダムよりモーセに至るまで、アダムの咎と等しき罪を犯さぬ者の上にも死は王たりき。アダムは來らんとする者の型なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'されど恩惠の賜物は、かの咎の如きにあらず、一人の咎によりて多くの人の死にたらんには、まして神の恩惠と一人の人イエス・キリストによる恩惠の賜物とは、多くの人に溢れざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, '又この賜物は罪を犯しし一人より來れるものの如きにあらず、審判は一人よりして罪を定むるに至りしが、恩惠の賜物は多くの咎よりして義とするに至るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'もし一人の咎のために一人によりて死は王となりたらんには、まして恩惠と義の賜物とを豐に受くる者は、一人のイエス・キリストにより生命に在りて王たらざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'されば一つの咎によりて罪を定むることの凡ての人に及びしごとく、一つの正しき行爲によりて義とせられ生命を得るに至ることも、凡ての人に及べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'それは一人の不 從順によりて多くの人の罪人とせられし如く、一人の從順によりて多くの人、義人とせらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, '律法の來りしは咎の増さんためなり。されど罪の増すところには恩惠も彌増せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'これ罪の死によりて王たりし如く、恩惠も義によりて王となり、我らの主イエス・キリストに由りて永遠の生命に至らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'されば何をか言はん、恩惠の増さんために罪のうちに止るべきか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, '決して然らず、罪に就きて死にたる我らは爭で尚その中に生きんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'なんじら知らぬか、凡そキリスト・イエスに合ふバプテスマを受けたる我らは、その死に合ふバプテスマを受けしを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, '我らはバプテスマによりて彼とともに葬られ、その死に合せられたり。これキリスト父の榮光によりて死人の中より甦へらせられ給ひしごとく、我らも新しき生命に歩まんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, '我らキリストに接がれて、その死の状にひとしくば、その復活にも等しかるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, '我らは知る、われらの舊き人、キリストと共に十字架につけられたるは、罪の體ほろびて、此ののち罪に事へざらん爲なるを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'そは死にし者は罪より脱るるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, '我等もしキリストと共に死にしならば、また彼とともに活きんことを信ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'キリスト死人の中より甦へりて復 死に給はず、死もまた彼に主とならぬを我ら知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'その死に給へるは罪につきて一たび死に給へるにて、その活き給へるは神につきて活き給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, '斯くのごとく汝らも己を罪につきては死にたるもの、神につきては、キリスト・イエスに在りて活きたる者と思ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'されば罪を汝らの死ぬべき體に王たらしめて其の慾に從ふことなく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, '汝らの肢體を罪に献げて不義の器となさず、反つて死人の中より活き返りたる者のごとく己を神にささげ、その肢體を義の器として神に献げよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, '汝らは律法の下にあらずして恩惠の下にあれば、罪は汝らに主となる事なきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, '然らば如何に、我らは律法の下にあらず、恩惠の下にあるが故に、罪を犯すべきか、決して然らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'なんぢら知らぬか、己を献げ僕となりて、誰に從ふとも其の僕たることを。或は罪の僕となりて死に至り、或は從順の僕となりて義に至る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, '然れど神に感謝す、汝 等はもと罪の僕なりしが、傳へられし教の範に心より從ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, '罪より解放されて義の僕となりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, '斯く人の事をかりて言ふは、汝らの肉よわき故なり。なんぢら舊その肢體をささげ、穢と不法との僕となりて不法に到りしごとく、今その肢體をささげ、義の僕となりて潔に到れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'なんぢら罪の僕たりしときは義に對して自由なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'その時に今は恥とする所の事によりて何の實を得しか、これらの事の極は死なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, '然れど今は罪より解放されて神の僕となりたれば、潔にいたる實を得たり、その極は永遠の生命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'それ罪の拂ふ價は死なり、然れど神の賜物は我らの主キリスト・イエスにありて受くる永遠の生命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, '兄弟よ、なんぢら知らぬか、(われ律法を知る者に語る)律法は人の生ける間のみ之に主たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, '夫ある婦は律法によりて夫の生ける中は之に縛らる。然れど夫 死なば夫の律法より解かるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'されば夫の生ける中に他の人に適かば淫婦と稱へらるれど、夫 死なばその律法より解放さるる故に、他の人に適くとも淫婦とはならぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'わが兄弟よ、斯くのごとく汝 等もキリストの體により律法に就きて死にたり。これ他の者、すなはち死人の中より甦へらせられ給ひし者に適き、神のために實を結ばん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'われら肉に在りしとき、律法に由れる罪の情は我らの肢體のうちに働きて、死のために實を結ばせたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'されど縛られたる所に就きて我等いま死にて律法より解かれたれば、儀文の舊きによらず、靈の新しきに從ひて事ふることを得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'さらば何をか言はん、律法は罪なるか、決して然らず、律法に由らでは、われ罪を知らず、律法に『貪る勿れ』と言はずば、慳貪を知らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'されど罪は機に乘じ誡命によりて各樣の慳貪を我がうちに起せり、律法なくば罪は死にたるものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'われ曾て律法なくして生きたれど、誡命きたりし時に罪は生き、我は死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, '而して我は生命にいたるべき誡命の反つて死に到らしむるを見出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'これ罪は機に乘じ誡命によりて我を欺き、かつ之によりて我を殺せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'それ律法は聖なり、誡命もまた聖にして正しく、かつ善なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'されば善なるもの我に死となりたるか。決して然らず、罪は罪たることの現れんために、善なる者によりて我が内に死を來らせたるなり。これ誡命によりて罪の甚だしき惡とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'われら律法は靈なるものと知る、されど我は肉なる者にて罪の下に賣られたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'わが行ふことは我しらず、我が欲する所は之をなさず、反つて我が憎むところは之を爲すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'わが欲せぬ所を爲すときは律法の善なるを認む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, '然れば之を行ふは我にあらず、我が中に宿る罪なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, '我はわが中、すなわち我が肉のうちに善の宿らぬを知る、善を欲すること我にあれど、之を行ふ事なければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'わが欲する所の善は之をなさず、反つて欲せぬ所の惡は之をなすなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, '我もし欲せぬ所の事をなさば、之を行ふは我にあらず、我が中に宿る罪なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, '然れば善をなさんと欲する我に惡ありとの法を、われ見出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'われ中なる人にては神の律法を悦べど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'わが肢體のうちに他の法ありて、我が心の法と戰ひ、我を肢體の中にある罪の法の下に虜とするを見る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, '噫われ惱める人なるかな、此の死の體より我を救はん者は誰ぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, '我らの主イエス・キリストに頼りて神に感謝す、然れば我みづから心にては神の律法につかへ、内にては罪の法に事ふるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'この故に今やキリスト・イエスに在る者は罪の定めらるることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'キリスト・イエスに在る生命の御靈の法は、なんじを罪と死との法より解放したればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, '肉によりて弱くなれる律法の成し能はぬ所を神は爲し給へり、即ち己の子を罪ある肉の形にて罪のために遣し、肉に於て罪を定めたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'これ肉に從はず靈に從ひて歩む我らの中に、律法の義の完うせられん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, '肉にしたがふ者は肉の事をおもひ、靈にしたがふ者は靈の事をおもふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, '肉の念は死なり、靈の念は生命なり、平安なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, '肉の念は神に逆ふ、それは神の律法に服はず、否したがふこと能はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'また肉に居る者は神を悦ばすこと能はざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, '然れど神の御靈なんぢらの中に宿り給はば、汝らは肉に居らで靈に居らん、キリストの御靈なき者はキリストに屬する者にあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, '若しキリスト汝らに在さば、體は罪によりて死にたる者なれど、靈は義によりて生命に在らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, '若しイエスを死人の中より甦へらせ給ひし者の御靈なんぢらの中に宿り給はば、キリスト・イエスを死人の中より甦へらせ給ひし者は、汝らの中に宿りたまふ御靈によりて、汝らの死ぬべき體をも活し給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'されば兄弟よ、われらは負債あれど、肉に負ふ者ならねば、肉に從ひて活くべきにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, '汝 等もし肉に從ひて活きなば、死なん。もし靈によりて體の行爲を殺さば活くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'すべて神の御靈に導かるる者は、これ神の子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, '汝らは再び懼を懷くために僕たる靈を受けしにあらず、子とせられたる者の靈を受けたり、之によりて我らはアバ父と呼ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, '御靈みづから我らの靈とともに我らが神の子たることを證す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'もし子たらば世嗣たらん、神の嗣子にしてキリストと共に世嗣たるなり。これはキリストとともに榮光を受けん爲に、その苦難をも共に受くるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'われ思うに、今の時の苦難は、われらの上に顯れんとする榮光にくらぶるに足らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'それ造られたる者は、切に慕ひて神の子たちの現れんことを待つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, '造られたるものの虚無に服せしは、己が願によるにあらず、服せしめ給ひし者によるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, '然れどなほ造られたる者にも滅亡の僕たる状より解かれて、神の子たちの光榮の自由に入る望は存れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, '我らは知る、すべて造られたるものの今に至るまで共に嘆き、ともに苦しむことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, '然のみならず、御靈の初の實をもつ我らも自ら心のうちに嘆きて、子とせられんこと、即ちおのが軆の贖はれんことを待つなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, '我らは望によりて救はれたり、眼に見ゆる望は望にあらず、人その見るところを爭でなほ望まんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, '我等もし其の見ぬところを望まば、忍耐をもて之を待たん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, '斯くのごとく御靈も我らの弱を助けたまふ。我らは如何に祈るべきかを知らざれども、御靈みづから言ひ難き歎をもて執成し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'また人の心を極めたまふ者は御靈の念をも知りたまふ。御靈は神の御意に適ひて聖徒のために執成し給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, '神を愛する者、すなはち御旨によりて召されたる者の爲には、凡てのこと相 働きて益となるを我らは知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, '神は預じめ知りたまふ者を御子の像に象らせんと預じめ定め給へり。これ多くの兄弟のうちに、御子を嫡子たらせんが爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, '又その預じめ定めたる者を召し、召したる者を義とし、義としたる者には光榮を得させ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, '然れば此 等の事につきて何をか言はん、神もし我らの味方ならば、誰か我らに敵せんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, '己の御子を惜まずして我ら衆のために付し給ひし者は、などか之にそへて萬物を我らに賜はざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, '誰か神の選び給へる者を訴へん、神は之を義とし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, '誰か之を罪に定めん、死にて甦へり給ひしキリスト・イエスは神の右に在して、我らの爲に執成し給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, '我等をキリストの愛より離れしむる者は誰ぞ、患難か、苦難か、迫害か、飢か、裸か、危險か、劍か。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, '録して『汝のために我らは、終日ころされて屠らるべき羊の如きものとせられたり』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'されど凡てこれらの事の中にありても、我らを愛したまふ者に頼り、勝ち得て餘あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'われ確く信ず、死も生命も、御使も、權威ある者も、今ある者も後あらん者も、力ある者も、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, '高きも深きも、此の他の造られたるものも、我らの主キリスト・イエスにある神の愛より、我らを離れしむるを得ざることを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, '我キリストに在りて眞をいひ虚僞を言はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, '我に大なる憂あることと心に絶えざる痛あることとを、我が良心も聖 靈によりて證す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'もし我が兄弟わが骨肉の爲にならんには、我みづから詛はれてキリストに棄てらるるも亦ねがふ所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, '彼 等はイスラエル人にして、彼らには神の子とせられたることと、榮光と、もろもろの契約と、授けられたる律法と、禮拜と、もろもろの約束とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, '先祖たちも彼 等のものなり、肉によれば、キリストも彼 等より出で給ひたり。キリストは萬物の上にあり、永遠に讃むべき神なり、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'それ神の言は廢りたるに非ず。イスラエルより出づる者みなイスラエルなるに非ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'また彼 等はアブラハムの裔なればとて皆その子たるに非ず『イサクより出づる者は、なんぢの裔と稱へらるべし』とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, '即ち肉の子らは神の子らにあらず、ただ約束の子 等のみ其の裔と認めらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, '約束の御言は是なり、曰く『時ふたたび巡り來らば、我きたりてサラに男子あらん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, '然のみならず、レベカも我らの先祖イサク一人によりて孕りたる時、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'その子いまだ生れず、善も惡もなさぬ間に、神の選の御旨は動かず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, '行爲によらで召す者によらん爲に『兄は次弟に事ふべし』とレベカに宣へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, '『われヤコブを愛しエザウを憎めり』と録されたる如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'さらば何をか言はん、神には不義あるか。決して然らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'モーセに言ひ給ふ『われ憐まんとする者をあはれみ、慈悲を施さんとする者に慈悲を施すべし』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'されば欲する者にも由らず、走る者にも由らず、ただ憐みたまふ神に由るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'パロにつきて聖書に言ひ給ふ『わが汝を起したるは此の爲なり、即ち我が能力を汝によりて顯し、且わが名の全世界に傳へられん爲なり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'されば神はその憐まんと欲する者を憐み、その頑固にせんと欲する者を頑固にし給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'さらば汝あるいは我に言はん『神なんぞなほ人を咎め給ふか、誰かその御定に悖る者あらん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'ああ人よ、なんぢ誰なれば神に言ひ逆ふか、造られしもの造りたる者に對ひて『なんぢ何ぞ我を斯く造りし』と言ふべきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, '陶工は同じ土塊をもて、此を貴きに用ふる器とし、彼を賤しきに用ふる器とするの權なからんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'もし神、怒をあらはし權力を示さんと思しつつも、なほ大なる寛容をもて、滅亡に備れる怒の器を忍び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'また光榮のために預じめ備へ給ひし憐憫の器に對ひて、その榮光の富を示さんとし給ひしならば如何に。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'この憐憫の器は我等にして、ユダヤ人の中よりのみならず、異邦人の中よりも召し給ひしものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'ホゼヤの書に『我わが民たらざる者を我が民と呼び、愛せられざる者を愛せらるる者と呼ばん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, '「なんぢら我が民にあらず」と言ひし處にて、彼らは活ける神の子と呼ばるべし』と宣へる如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'イザヤもイスラエルに就きて叫べり『イスラエルの子孫の數は海の砂のごとくなりとも、救はるるはただ殘の者のみならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, '主、地の上に御言をなし了へ、これを遂げ、これを速かにし給はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'また『萬軍の主われらに裔を遺し給はずば、我等ソドムの如くになり、ゴモラと等しかりしならん』とイザヤの預言せしが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, '然らば何をか言はん、義を追ひ求めざりし異邦人は義を得たり、即ち信仰による義なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'イスラエルは義の律法を追ひ求めたれど、その律法に到らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, '何の故か、かれらは信仰によらず、行爲によりて追ひ求めたる故なり。彼らは躓く石に躓きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, '録して『視よ、我つまづく石さまたぐる岩をシオンに置く、之に依頼む者は辱しめられじ』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, '兄弟よ、わが心のねがひ、神に對する祈は、彼らの救はれんことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'われ彼らが神のために熱心なることを證す、されど其の熱心は知識によらざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'それは神の義を知らず、己の義を立てんとして、神の義に服はざればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'キリストは凡て信ずる者の義とせられん爲に律法の終となり給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'モーセは、律法による義をおこなふ人は之によりて生くべしと録したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'されど信仰による義は斯くいふ『なんぢ心に「誰か天に昇らん」と言ふなかれ』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'これキリストを引下さんとするなり『また「たれか底なき所に下らん」と言ふなかれ』と。是キリストを死人の中より引上げんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'さらば何と言ふか『御言はなんぢに近し、なんぢの口にあり、汝の心にあり』と。これ我らが宣ぶる信仰の言なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, '即ち、なんぢ口にてイエスを主と言ひあらはし、心にて神の之を死人の中より甦へらせ給ひしことを信ぜば、救はるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'それ人は心に信じて義とせられ、口に言ひあらはして救はるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, '聖書にいふ『すべて彼を信ずる者は辱しめられじ』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'ユダヤ人とギリシヤ人との區別なし、同一の主は萬民の主にましまして、凡て呼び求むる者に對して豐なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, '『すべて主の御名を呼び求むる者は救はるべし』とあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, '然れど未だ信ぜぬ者を爭で呼び求むることをせん、未だ聽かぬ者を爭で信ずることをせん、宣傳ふる者なくば爭で聽くことをせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, '遣されずば爭で宣傳ふることをせん『ああ美しきかな、善き事を告ぐる者の足よ』と録されたる如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'されど、みな福音に從ひしにはあらず、イザヤいふ『主よ、われらに聞きたる言を誰か信ぜし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, '斯く信仰は聞くにより、聞くはキリストの言による。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'されど我いふ、彼ら聞えざりしか、然らず『その聲は全地にゆきわたり、其の言は世界の極にまで及べり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, '我また言ふ、イスラエルは知らざりしか、先づモーセ言ふ『われ民ならぬ者をもて汝らに嫉を起させ、愚なる民をもて汝らを怒らせん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'またイザヤ憚らずして言ふ『我を求めざる者に、われ見出され、我を尋ねざる者に我あらはれたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, '更にイスラエルに就きては『われ服はずして言ひさからふ民に、終日 手を伸べたり』と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'されば我いふ、神はその民を棄て給ひしか。決して然らず。我もイスラエル人にしてアブラハムの裔ベニヤミンの族の者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, '神はその預じめ知り給ひし民を棄て給ひしにあらず。汝らエリヤに就きて聖書に云へることを知らぬか、彼イスラエルを神に訴へて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '『主よ、彼らは汝の預言者たちを殺し、なんぢの祭壇を毀ち、我ひとり遺りたるに、亦わが生命をも求めんとするなり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, '然るに御答は何と云へるか『われバアルに膝を屈めぬ者、七 千 人を我がために遺し置けり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, '斯くのごとく今もなほ恩惠の選によりて遺れる者あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'もし恩惠によるとせば、もはや行爲によるにあらず。然らずば恩惠はもはや恩惠たらざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'さらば如何に、イスラエルはその求むる所を得ず、選ばれたる者は之を得たり、その他の者は鈍くせられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '『神は今日に至るまで、彼らに眠れる心、見えぬ目、聞えぬ耳を與へ給へり』と録されたるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'ダビデも亦いふ『かれらの食卓は羂となれ、網となれ、つまづきとなれ、報となれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'その眼は眩みて見えずなれ、常にその背を屈めしめ給へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'されば我いふ、彼らの躓きしは倒れんが爲なりや。決して然らず、反つて其の落度によりて救は異邦人に及べり、これイスラエルを勵まさん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'もし彼らの落度、世の富となり、その衰微、異邦人の富となりたらんには、まして彼らの數 滿つるに於てをや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'われ異邦人なる汝 等にいふ、我は異邦人の使徒たるによりて己が職を重んず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'これ或は我が骨肉の者を勵まし、その中の幾許かを救はん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'もし彼らの棄てらるること世の平和となりたらんには、其の受け納れらるるは、死人の中より活くると等しからずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'もし初穗の粉 潔くば、パンの團塊も潔く、樹の根 潔くば、其の枝も潔からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, '若しオリブの幾許の枝きり落されて野のオリブなる汝、その中に接がれ、共にその樹の液汁ある根に與らば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'かの枝に對ひて誇るな、たとひ誇るとも汝は根を支へず、根は反つて汝を支ふるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'なんぢ或は言はん『枝の折られしは我が接がれん爲なり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, '實に然り、彼らは不 信によりて折られ、汝は信仰によりて立てるなり、高ぶりたる思をもたず、反つて懼れよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'もし神、原 樹の枝を惜み給はざりしならば、汝をも惜み給はじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, '神の仁慈と、その嚴肅とを見よ。嚴肅は倒れし者にあり、仁慈はその仁慈に止る汝にあり、若しその仁慈に止らずば、汝も切り取らるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, '彼らも若し不 信に止らずば、接がるることあらん、神は再び彼らを接ぎ得給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'なんぢ生來の野のオリブより切り取られ、その生來に悖りて善きオリブに接がれたらんには、まして原 樹のままなる枝は己がオリブに接がれざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, '兄弟よ、われ汝らが自己を聰しとする事なからん爲に、この奧義を知らざるを欲せず、即ち幾許のイスラエルの鈍くなれるは、異邦人の入り來りて數 滿つるに及ぶ時までなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'かくしてイスラエルは悉とく救はれん。録して『救ふ者シオンより出で來りて、ヤコブより不虔を取り除かん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'われその罪を除くときに彼らに立つる我が契約は是なり』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, '福音につきて云へば、汝 等のために彼らは敵とせられ、選につきて云へば、先祖たちの爲に彼らは愛せらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'それ神の賜物と召とは變ることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, '汝ら前には神に從はざりしが、今は彼らの不順によりて憐まれたる如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, '彼らも汝らの受くる憐憫によりて憐まれん爲に、今は從はざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, '神は凡ての人を憐まんために、凡ての人を不順の中に取籠め給ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'ああ神の智慧と知識との富は深いかな、その審判は測り難く、その途は尋ね難し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, '『たれか主の心を知りし、誰かその議士となりし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'たれか先づ主に與へて其の報を受けんや』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'これ凡ての物は神より出で、神によりて成り、神に歸すればなり、榮光とこしへに神にあれ。アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'されば兄弟よ、われ神のもろもろの慈悲によりて汝らに勸む、己が身を神の悦びたまふ潔き活ける供物として献げよ、これ靈の祭なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, '又この世に效ふな、神の御意の善にして悦ぶべく、かつ全きことを辨へ知らんために、心を更へて新にせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'われ與へられし恩惠によりて汝 等おのおのに告ぐ、思ふべき所を超えて自己を高しとすな。神のおのおのに分ち給ひし信仰の量にしたがひ愼みて思ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, '人は一つ體におほくの肢あれども、凡ての肢その運用を同じうせぬ如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, '我らも多くあれど、キリストに在りて一つ體にして、各人たがひに肢たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'われらが有てる賜物はおのおの與へられし恩惠によりて異なる故に、或は預言あらば信仰の量にしたがひて預言をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, '或は務あらば務をなし、或は教をなす者は教をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, '或は勸をなす者は勸をなし、施す者はをしみなく施し、治むる者は心を盡して治め、憐憫をなす者は喜びて憐憫をなすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, '愛には虚僞あらざれ、惡はにくみ、善はしたしみ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, '兄弟の愛をもて互に愛しみ、禮儀をもて相 讓り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, '勤めて怠らず、心を熱くし、主につかへ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, '望みて喜び、患難にたへ、祈を恆にし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, '聖徒の缺乏を賑し、旅人を懇ろに待せ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, '汝らを責むる者を祝し、これを祝して詛ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, '喜ぶ者と共によろこび、泣く者と共になけ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, '相 互に心を同じうし、高ぶりたる思をなさず、反つて卑きに附け。なんぢら己を聰しとすな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, '惡をもて惡に報いず、凡ての人のまへに善からんことを圖り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, '汝らの爲し得るかぎり力めて凡ての人と相 和げ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, '愛する者よ、自ら復讐すな、ただ神の怒に任せまつれ。録して『主いひ給ふ、復讐するは我にあり、我これに報いん』とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, '『もし汝の仇 飢ゑなば之に食はせ、渇かば之に飮ませよ、なんぢ斯するは熱き火を彼の頭に積むなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, '惡に勝たるることなく、善をもて惡に勝て。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, '凡ての人、上にある權威に服ふべし。そは神によらぬ權威なく、あらゆる權威は神によりて立てらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'この故に權威にさからふ者は神の定に悖るなり、悖る者は自らその審判を招かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, '長たる者は善き業の懼にあらず、惡しき業の懼なり、なんぢ權威を懼れざらんとするか、善をなせ、然らば彼より譽を得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'かれは汝を益せんための神の役者なり。然れど惡をなさば懼れよ、彼は徒らに劍をおびず、神の役者にして、惡をなす者に怒をもて報ゆるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, '然れば服はざるべからず、啻に怒の爲のみならず、良心のためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'また之がために汝ら貢を納む、彼らは神の仕人にして此の職に勵むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, '汝 等その負債をおのおのに償へ、貢を受くべき者に貢ををさめ、税を受くべき者に税ををさめ、畏るべき者をおそれ、尊ぶべき者をたふとべ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, '汝 等たがひに愛を負ふのほか何をも人に負ふな。人を愛する者は律法を全うするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'それ『姦淫する勿れ、殺すなかれ、盜むなかれ、貪るなかれ』と云へるこの他なほ誡命ありとも『おのれの如く隣を愛すべし』といふ言の中にみな籠るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, '愛は隣を害はず、この故に愛は律法の完全なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'なんぢら時を知る故に、いよいよ然なすべし。今は眠より覺むべき時なり。始めて信ぜし時よりも今は我らの救 近ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, '夜ふけて日 近づきぬ、然れば我ら暗黒の業をすてて光明の甲を著るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, '晝のごとく正しく歩みて宴樂・醉酒に、淫樂・好色に、爭鬪・嫉妬に歩むべきに非ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'ただ汝ら主イエス・キリストを衣よ、肉の慾のために備すな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'なんぢら信仰の弱き者を容れよ、その思ふところを詰るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, '或 人は凡ての物を食ふを可しと信じ、弱き人はただ野菜を食ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, '食ふ者は食はぬ者を蔑すべからず、食はぬ者は食ふ者を審くべからず、神は彼を容れ給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'なんぢ如何なる者なれば、他人の僕を審くか、彼が立つも倒るるも其の主人に由れり。彼は必ず立てられん、主は能く之を立たせ給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, '或 人は此の日を彼の日に勝ると思ひ、或 人は凡ての日を等しとおもふ、各人おのが心の中に確く定むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, '日を重んずる者は主のために之を重んず。食ふ者は主のために食ふ、これ神に感謝すればなり。食はぬ者も主のために食はず、かつ神に感謝するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, '我等のうち己のために生ける者なく、己のために死ぬる者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'われら生くるも主のために生き、死ぬるも主のために死ぬ。然れば生くるも死ぬるも我らは主の有なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'それキリストの死にて復 生き給ひしは、死にたる者と生ける者との主とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'なんぢ何ぞその兄弟を審くか、汝なんぞ其の兄弟を蔑するか、我等はみな神の審判の座の前に立つべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, '録して『主いひ給ふ、我は生くるなり、凡ての膝はわが前に屈み、凡ての舌は神を讃め稱へん』とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, '我等おのおの神のまへに己の事を陳ぶべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'されば今より後、われら互に審くべからず、むしろ兄弟のまへに妨碍または躓物を置かぬように心を決めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'われ如何なる物も自ら潔からぬ事なきを主イエスに在りて知り、かつ確く信ず。ただ潔からずと思ふ人にのみ潔からぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'もし食物によりて兄弟を憂ひしめば、汝は愛によりて歩まざるなり、キリストの代りて死に給ひし人を、汝の食物によりて亡すな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, '汝らの善きことの譏られぬようにせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'それ神の國は飮食にあらず、義と平和と聖 靈によれる歡喜とに在るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'かくしてキリストに事ふる者は神に悦ばれ、人々に善しとせらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'されば我ら平和のことと互に徳を建つる事とを追ひ求むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'なんぢ食物のために神の御業を毀つな。凡ての物は潔し、されど之を食ひて人を躓かする者には惡とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, '肉を食はず、葡萄酒を飮まず、その他なんぢの兄弟を躓かする事をせぬは善し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'なんぢの有てる信仰を己みづから神の前に保て。善しとする所につきて自ら咎めなき者は幸福なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, '疑ひつつ食ふ者は罪せらる。これ信仰によらぬ故なり、凡て信仰によらぬ事は罪なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'われら強き者はおのれを喜ばせずして、力なき者の弱を負ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'おのおの隣 人の徳を建てん爲に、その益を圖りて之を喜ばすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'キリストだに己を喜ばせ給はざりき。録して『なんぢを謗る者の謗は我に及べり』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, '夙くより録されたる所は、みな我らの教訓のために録ししものにして、聖書の忍耐と慰安とによりて希望を保たせんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, '願はくは忍耐と慰安との神、なんぢらをしてキリスト・イエスに效ひ、互に思を同じうせしめ給はん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'これ汝らが心を一つにし口を一つにして、我らの主イエス・キリストの父なる神を崇めん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, '此の故にキリスト汝らを容れ給ひしごとく、汝らも互に相 容れて神の榮光を彰すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'われ言ふ、キリストは神の眞理のために割禮の役者となり給へり。これ先祖たちの蒙りし約束を堅うし給はん爲、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'また異邦人も憐憫によりて神を崇めんためなり。録して『この故に、われ異邦人の中にて汝を讃めたたへ、又なんぢの名を謳はん』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'また曰く『異邦人よ、主の民と共に喜べ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, '又いはく『もろもろの國人よ、主を讃め奉れ、もろもろの民よ、主を稱へ奉れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, '又イザヤ言ふ『エツサイの萠薛 生じ、異邦人を治むるもの興らん。異邦人は彼に望をおかん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, '願はくは希望の神、信仰より出づる凡ての喜悦と平安とを汝らに滿たしめ、聖 靈の能力によりて希望を豐ならしめ給はんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'わが兄弟よ、われは汝らが自ら善に滿ち、もろもろの知識に滿ちて互に訓戒し得ることを確く信ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'されど我なほ汝らに憶ひ出させん爲に、ここかしこ少しく憚らずして書きたる所あり、これ神の我に賜ひたる恩惠に因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, '即ち異邦人のためにキリスト・イエスの仕人となり、神の福音につきて祭司の職をなす。これ異邦人の聖 靈によりて潔められ、御心に適ふ献物とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'されば、われ神の事につきては、キリスト・イエスによりて誇る所あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, '我は、キリストの異邦人を服はせん爲に我を用ひて、言と業と、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'また徴と不思議との能力、および聖 靈の能力にて働き給ひし事のほかは敢へて語らず、エルサレムよりイルリコの地方に到るまで、徧くキリストの福音を充たせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, '我は努めて他人の置ゑたる基礎のうへに建てじとて、未だキリストの御名の稱へられぬ所にのみ福音を宣傅へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, '録して『未だ彼のことを傳へられざりし者は見、いまだ聞かざりし者は悟るべし』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'この故に、われ汝らに往かんとせしが、しばしば妨げられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'されど今は此の地方に働くべき處なく、且なんぢらに往かんことを多年 切に望みゐたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'イスパニヤに赴かんとき立寄りて汝らを見、ほぼ意に滿つるを得てのち汝らに送られんとを望むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'されど今、聖徒に事へん爲にエルサレムに往かんとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'マケドニアとアカヤとの人々は、エルサレムに在る聖徒の貧しき者に幾許かの施與をするを善しとせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, '實に之を善しとせり、また聖徒に對して斯くする負債あり。異邦人もし彼らの靈の物に與りたらんには、肉の物をもて彼らに事ふべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'されば此の事を成し了へ、この果を付してのち、汝らを歴てイスパニヤに往かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'われ汝らに到るときは、キリストの滿ち足れる祝福をもて到らんことを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, '兄弟よ、我らの主イエス・キリストにより、また御靈の愛によりて汝らに勸む、なんぢらの祈のうちに、我とともに力を盡して我がために神に祈れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'これユダヤにをる從はぬ者の中より我が救はれ、又エルサレムに對する我が務の聖徒の心に適ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'かつ神の御意により、歡喜をもて汝 等にいたり、共に安んぜん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, '願はくは平和の神なんぢら衆と偕に在さんことを、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, '我ケンクレヤの教會の執事なる我らの姉妹フィベを汝らに薦む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'なんぢら主にありて聖徒たるに相應しく彼を容れ、何にても其の要する所を助けよ、彼は夙くより多くの人の保護者また我が保護者たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'プリスカとアクラとに安否を問へ、彼らはキリスト・イエスに在る我が同勞者にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'わが生命のために己の首をも惜まざりき。彼らに感謝するは、ただ我のみならず、異邦人の諸 教會もまた然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, '又その家にある教會にも安否を問へ。又わが愛するエパネトに安否を問へ。彼はアジヤにて結べるキリストの初の實なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, '汝 等のために甚く勞せしマリヤに安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, '我とともに囚人たりし我が同族アンデロニコとユニアスとに安否を問へ、彼らは使徒たちの中に名聲あり、かつ我に先だちてキリストに歸せし者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, '主にありて我が愛するアンプリヤに安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'キリストにある我らの同勞者ウルパノと我が愛するスタキスとに安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'キリストに在りて錬達せるアペレに安否を問へ。アリストブロの家の者に安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'わが同族ヘロデオンに安否を問へ。ナルキソの家なる主に在る者に安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, '主に在りて勞せしツルパナとツルポサとに安否を問へ。主に在りて甚く勞せし愛するペルシスに安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, '主に在りて選ばれたるルポスと其の母とに安否を問へ、彼の母は我にもまた母なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'アスンクリト、フレゴン、ヘルメス、パトロバ、ヘルマス及び彼らと偕に在る兄弟たちに安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'ピロロゴ及びユリヤ、ネレオ及びその姉妹、またオルンパ及び彼らと偕に在る凡ての聖徒に安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, '潔き接吻をもて互に安否を問へ。キリストの諸 教會みな汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, '兄弟よ、われ汝らに勸む、おほよそ汝らの學びし教に背きて分離を生じ、顛躓をおこす者に心して之に遠ざかれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'かかる者は我らの主キリストに事へず、反つて己が腹に事へ、また甘き言と媚諂とをもて質朴なる人の心を欺くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, '汝らの從順は凡ての人に聞えたれば、我なんぢらの爲に喜べり。而して我が欲する所は、汝らが善に智く、惡に疏からんことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, '平和の神は速かにサタンを汝らの足の下に碎き給ふべし。願はくは我らの主イエスの恩惠、なんぢらと偕に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'わが同勞者テモテ及び我が同族ルキオ、ヤソン、ソシパテロ汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'この書を書ける我テルテオも主にありて汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, '我と全 教會との家主ガイオ汝らに安否を問ふ。町の庫司エラストと兄弟クワルトと汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '[なし]');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, '願はくは長き世のあひだ隱れたれども、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, '今 顯れて、永遠の神の命にしたがひ、預言者たちの書によりて信仰の從順を得しめん爲に、もろもろの國人に示されたる奧義の默示に循へる我が福音と、イエス・キリストを宣ぶる事とによりて、汝らを堅うし得る、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, '唯一の智き神に、榮光 世々 限りなくイエス・キリストに由りて在らんことを、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, '神の御意により召されてイエス・キリストの使徒となれるパウロ及び兄弟ソステネ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, '書をコリントに在る神の教會、即ちいづれの處にありても、我らの主、ただに我等のみならず彼らの主なるイエス・キリストの名を呼び求むる者とともに、聖徒となるべき召を蒙り、キリスト・イエスに在りて潔められたる汝らに贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, '願はくは我らの父なる神および主イエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'われ汝らがキリスト・イエスに在りて神より賜はりし恩惠に就きて、常に神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, '汝らはキリストに在りて、諸般のこと即ち凡ての言と凡ての悟とに富みたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'これキリストの證なんぢらの中に堅うせられたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, '斯く汝らは凡ての賜物に缺くる所なくして、我らの主イエス・キリストの現れ給ふを待てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, '彼は汝らを終まで堅うして、我らの主イエス・キリストの日に責むべき所なからしめ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, '汝らを召して其の子われらの主イエス・キリストの交際に入らしめ給ふ神は眞實なる哉。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, '兄弟よ、我らの主イエス・キリストの名に頼りて汝らに勸む、おのおの語るところを同じうし、分爭する事なく、同じ心おなじ念にて全く一つになるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'わが兄弟よ、クロエの家の者、なんぢらの中に紛爭あることを我に知らせたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, '即ち汝 等おのおの『我はパウロに屬す』『われはアポロに』『我はケパに』『我はキリストに』と言ふこれなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'キリストは分たるる者ならんや、パウロは汝らの爲に十字架につけられしや、汝らパウロの名に頼りてバプテスマを受けしや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, '我は感謝す、クリスポとガイオとの他には、我なんぢらの中の一人にもバプテスマを施さざりしを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, '是わが名に頼りて汝らがバプテスマを受けしと人の言ふ事なからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'またステパノの家族にバプテスマを施しし事あり、此の他には我バプテスマを施しし事ありや知らざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'そはキリストの我を遣し給へるはバプテスマを施させん爲にあらず、福音を宣傳へしめんとてなり。而して言の智慧をもつてせず、是キリストの十字架の虚しくならざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'それ十字架の言は亡ぶる者には愚なれど、救はるる我らには神の能力なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, '録して、『われ智者の智慧をほろぼし、慧き者のさときを空しうせん』とあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, '智者いづこにか在る、學者いづこにか在る、この世の論者いづこにか在る、神は世の智慧をして愚ならしめ給へるにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, '世は己の智慧をもて神を知らず(これ神の智慧に適へるなり)この故に神は宣教の愚をもて、信ずる者を救ふを善しとし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'ユダヤ人は徴を請ひ、ギリシヤ人は智慧を求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'されど我らは十字架に釘けられ給ひしキリストを宣傳ふ。これはユダヤ人に躓物となり、異邦人に愚となれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, '召されたる者にはユダヤ人にもギリシヤ人にも、神の能力また神の智慧たるキリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, '神の愚は人よりも智く、神の弱は人よりも強ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, '兄弟よ、召を蒙れる汝らを見よ、肉によれる智き者おほからず、能力ある者おほからず、貴きもの多からず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'されど神は智き者を辱しめんとて世の愚なる者を選び、強き者を辱しめんとて弱き者を選び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, '有る者を亡さんとて世の卑しきもの、輕んぜらるる者、すなわち無きが如き者を選び給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'これ神の前に人の誇る事なからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, '汝らは神に頼りてキリスト・イエスに在り、彼は神に立てられて我らの智慧と義と聖と救贖とになり給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'これ『誇る者は主に頼りて誇るべし』と録されたる如くならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, '兄弟よ、われ曩に汝らに到りしとき、神の證を傳ふるに言と智慧との優れたるを用ひざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'イエス・キリスト及びその十字架に釘けられ給ひし事のほかは、汝らの中にありて何をも知るまじと心を定めたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, '我なんぢらと偕に居りし時に、弱くかつ懼れ、甚く戰けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'わが談話も、宣教も、智慧の美しき言によらずして、御靈と能力との證明によりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'これ汝らの信仰の、人の智慧によらず、神の能力に頼らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'されど我らは成人したる者の中にて智慧を語る。これ此の世の智慧にあらず、又この世の廢らんとする司たちの智慧にあらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, '我らは奧義を解きて神の智慧を語る、即ち隱れたる智慧にして、神われらの光榮のために、世の創の先より預じめ定め給ひしものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'この世の司には之を知る者なかりき、もし知らば榮光の主を十字架に釘けざりしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, '録して『神のおのれを愛する者のために備へ給ひし事は、眼いまだ見ず、耳いまだ聞かず、人の心いまだ思はざりし所なり』と有るが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'されど我らには神これを御靈によりて顯し給へり。御靈はすべての事を究め、神の深き所まで究むればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'それ人のことは己が中にある靈のほかに誰か知る人あらん、斯くのごとく神のことは神の御靈のほかに知る者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, '我らの受けし靈は世の靈にあらず、神より出づる靈なり、是われらに神の賜ひしものを知らんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, '又われら之を語るに人の智慧の教ふる言を用ひず、御靈の教ふる言を用ふ、即ち靈の事に靈の言を當つるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, '性來のままなる人は神の御靈のことを受けず、彼には愚なる者と見ゆればなり。また之を悟ること能はず、御靈のことは靈によりて辨ふべき者なるが故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'されど靈に屬する者は、すべての事をわきまふ、而して己は人に辨へらるる事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, '誰か主の心を知りて主を教ふる者あらんや。然れど我らはキリストの心を有てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, '兄弟よ、われ靈に屬する者に對する如く汝らに語ること能はず、反つて肉に屬するもの、即ちキリストに在る幼兒に對する如く語れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'われ汝らに乳のみ飮ませて堅き食物を與へざりき。汝 等そのとき食ふこと能はざりし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, '今もなほ食ふこと能はず、今もなほ肉に屬する者なればなり。汝らの中に嫉妬と紛爭とあるは、これ肉に屬する者にして世の人の如くに歩むならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, '或 者は『われパウロに屬す』といひ、或 者は『われアポロに屬す』と言ふ、これ世の人の如くなるにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'アポロは何 者ぞ、パウロは何 者ぞ、彼 等はおのおの主の賜ふところに隨ひ、汝らをして信ぜしめたる役者に過ぎざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, '我は植ゑ、アポロは水 灌げり、されど育てたるは神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'されば種うる者も、水 灌ぐ者も數ふるに足らず、ただ尊きは育てたまふ神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, '種うる者も、水 灌ぐ者も歸する所は一つなれど、各自おのが勞に隨ひて其の値を得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, '我らは神と共に働く者なり。汝らは神の畠なり、また神の建築物なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, '我は神の賜ひたる恩惠に隨ひて、熟錬なる建築師のごとく基を据ゑたり、而して他の人その上に建つるなり。然れど如何にして建つべきか、おのおの心して爲すべし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, '既に置きたる基のほかは誰も据うること能はず、この基は即ちイエス・キリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, '人もし此の基の上に金・銀・寳石・木・草・藁をもつて建てなば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, '各人の工は顯るべし。かの日これを明かにせん、かの日は火をもつて顯れ、その火おのおのの工の如何を驗すべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'その建つる所の工、もし保たば値を得、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'もし其の工 燒けなば損すべし。然れど己は火より脱れ出づる如くして救はれん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, '汝ら知らずや、汝らは神の宮にして、神の御靈なんぢらの中に住み給ふを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, '人もし神の宮を毀たば神かれを毀ち給はん。それ神の宮は聖なり、汝らも亦かくの如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, '誰も自ら欺くな。汝 等のうち此の世にて自ら智しと思ふ者は、智くならんために愚なる者となれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'そは此の世の智慧は神の前に愚なればなり。録して『彼は智者をその惡巧によりて捕へ給ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'また『主は智者の念の虚しきを知り給ふ』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'さらば誰も人を誇とすな、萬の物は汝らの有なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, '或はパウロ、或はアポロ、或はケパ、或は世界、あるひは生、あるひは死、あるひは現在のもの、或は未來のもの、皆なんぢらの有なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, '汝 等はキリストの有、キリストは神のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, '人よろしく我らをキリストの役者また神の奧義を掌どる家 司のごとく思ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'さて家 司に求むべきは忠實ならん事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, '我は汝らに審かれ、或は人の審判によりて審かるることを最 小き事とし、また自らも己を審かず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, '我みづから責むべき所あるを覺えねど、之に由りて義とせらるる事なければなり。我を審きたまふ者は主なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, '然れば主の來り給ふまでは時に先だちて審判すな。主は暗にある隱れたる事を明かにし、心の謀計をあらはし給はん。その時おのおの神より其の譽を得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, '兄弟よ、われ汝 等のために此 等のことを我とアポロとの上に當てて言へり。これ汝らが『録されたる所を踰ゆまじき』を我らの事によりて學び、この人をあげ、かの人を貶して誇らざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, '汝をして人と異ならしむる者は誰ぞ、なんぢの有てる物に何か受けぬ物あるか。もし受けしならば、何ぞ受けぬごとく誇るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'なんぢら既に飽き、既に富めり、我らを差措きて王となれり。われ實に汝らが王たらんことを願ふ、われらも共に王たることを得んが爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, '我おもふ、神は使徒たる我らを死に定められし者のごとく、後の者として見せ給へり。實に我らは宇宙のもの、即ち御使にも、衆人にも、觀物にせられたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, '我らはキリストのために愚なる者となり、汝らはキリストに在りて慧き者となれり。我等は弱く汝らは強し、汝らは尊く我らは卑し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, '今の時にいたるまで我らは飢ゑ、渇き、また裸となり、また打たれ、定れる住家なく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, '手づから働きて勞し、罵らるるときは祝し、責めらるるときは忍び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, '譏らるるときは勸をなせり。我らは今に至るまで世の塵芥のごとく、萬の物の垢のごとくせられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'わが斯く書すは汝らを辱しめんとにあらず、我が愛する子として訓戒せんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, '汝 等にはキリストに於ける守役 一萬ありとも、父は多くあることなし。そはキリスト・イエスに在りて福音により汝らを生みたるは、我なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'この故に汝らに勸む、我に效ふ者とならんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, '之がために主にありて忠實なる我が愛子テモテを汝らに遣せり。彼は我がキリストにありて行ふところ、即ち常に各地の教會に教ふる所を、汝らに思ひ出さしむべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'わが汝らに到ること無しとして誇る者あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'されど主の御意ならば速かに汝 等にいたり、誇る者の言にはあらで、その能力を知らんとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, '神の國は言にあらず、能力にあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, '汝ら何を欲するか、われ笞をもて到らんか、愛と柔和の心とをもて到らんか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, '現に聞く所によれば、汝らの中に淫行ありと、而してその淫行は異邦人の中にもなき程にして、或 人その父の妻を有てりと云ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, '斯くてもなほ汝ら誇ることをなし、かかる行爲をなしし者の除かれんことを願ひて悲しまざるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'われ身は汝らを離れ居れども、心は偕に在りて其處に居るごとく、かかる事を行ひし者を既に審きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'すなはち汝ら及び我が靈の、我らの主イエスの能力をもて偕に集らんとき、主イエスの名によりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, '斯くのごとき者をサタンに付さんとす、是その肉は亡されて、其の靈は主イエスの日に救はれん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, '汝らの誇は善からず。少しのパン種の、粉の團塊をみな膨れしむるを知らぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'なんぢら新しき團塊とならんために舊きパン種を取り除け、汝らはパン種なき者なればなり。夫われらの過越の羔羊すなはちキリスト既に屠られ給へり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'されば我らは舊きパン種を用ひず、また惡と邪曲とのパン種を用ひず、眞實と眞との種なしパンを用ひて祭を行ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'われ前の書にて淫行の者と交るなと書き贈りしは、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, '此の世の淫行の者、または貪欲のもの、奪ふ者、または偶像を拜む者と更に交るなと言ふにあらず(もし然せば世を離れざるを得ず)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'ただ兄弟と稱ふる者の中に、或は淫行のもの、或は貪欲のもの、或は偶像を拜む者、あるひは罵るもの、或は酒に醉ふもの、或は奪ふ者あらば、斯かる人と交ることなく、共に食する事だにすなとの意なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, '外の者を審くことは我の干る所ならんや、汝らの審くは、ただ内の者ならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, '外にある者は神これを審き給ふ。かの惡しき者を汝らの中より退けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, '汝 等のうち互に事あるとき、之を聖徒の前に訴へずして、正しからぬ者の前に訴ふることを敢へてする者あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, '汝ら知らぬか、聖徒は世を審くべき者なるを。世もし汝らに審かれんには、汝ら最 小き事を審くに足らぬ者ならんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'なんぢら知らぬか、我らは御使を審くべき者なるを、ましてこの世の事をや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, '然るに汝ら審くべき此の世の事のあるとき、教會にて輕しむる所の者を審判の座に坐らしむるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'わが斯く言ふは汝らを辱しめんとてなり。汝 等のうちに兄弟の間のことを審き得る智きもの一人だになく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, '兄弟は兄弟を、而も不 信者の前に訴ふるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, '互に相 訴ふるは既に當しく汝らの失態なり。何 故むしろ不義を受けぬか、何 故むしろ欺かれぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, '然るに汝ら不義をなし、詐欺をなし、兄弟にも之を爲す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, '汝ら知らぬか、正しからぬ者の神の國を嗣ぐことなきを。自ら欺くな、淫行のもの、偶像を拜むもの、姦淫をなすもの、男娼となるもの、男色を行ふ者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, '盜するもの、貪欲のもの、酒に醉ふもの、罵るもの、奪ふ者などは、みな神の國を嗣ぐことなきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, '汝 等のうち曩には斯くのごとき者ありしかど、主イエス・キリストの名により、我らの神の御靈によりて、己を洗ひかつ潔められ、かつ義とせらるることを得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, '一切のもの我に可からざるなし、然れど一切のもの益あるにあらず。一切のもの我に可からざるなし、されど我は何 物にも支配せられず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, '食物は腹のため、腹は食物のためなり。されど神は之をも彼をも亡し給はん。身は淫行をなさん爲にあらず、主の爲なり、主はまた身の爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, '神は既に主を甦へらせ給へり、又その能力をもて我等をも甦へらせ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, '汝らの身はキリストの肢體なるを知らぬか、然らばキリストの肢體をとりて遊女の肢體となすべきか、決して然すべからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, '遊女につく者は彼と一つ體となることを知らぬか『二人のもの一體となるべし』と言ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, '主につく者は之と一つ靈となるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, '淫行を避けよ。人のをかす罪はみな身の外にあり、されど淫行をなす者は己が身を犯すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, '汝らの身は、その内にある神より受けたる聖 靈の宮にして、汝らは己の者にあらざるを知らぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, '汝らは價をもて買はれたる者なり、然らばその身をもて神の榮光を顯せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, '汝らが我に書きおくりし事に就きては、男の女に觸れぬを善しとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, '然れど淫行を免れんために、男はおのおの其の妻をもち、女はおのおの其の夫を有つべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, '夫はその分を妻に盡し、妻もまた夫に然すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, '妻は己が身を支配する權をもたず、之を持つ者は夫なり。斯くのごとく夫も己が身を支配する權を有たず、之を有つ者は妻なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, '相 共に拒むな、ただ祈に身を委ぬるため合意にて暫く相 別れ、後また偕になるは善し。これ汝らが情の禁じがたきに乘じてサタンの誘ふことなからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'されど我が斯くいふは命ずるにあらず、許すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'わが欲する所は、すべての人の我が如くならん事なり。然れど神より各自おのが賜物を受く、此は此のごとく、彼は彼のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, '我は婚姻せぬ者および寡婦に言ふ。もし我が如くにして居らば、彼 等のために善し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'もし自ら制すること能はずば婚姻すべし、婚姻するは胸の燃ゆるよりも勝ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'われ婚姻したる者に命ず(命ずる者は我にあらず、主なり)妻は夫と別るべからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'もし別るる事あらば、嫁がずして居るか、又は夫と和げ。夫もまた妻を去るべからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'その外の人に我いふ(主の言ひ給ふにあらず)もし或 兄弟に不 信者なる妻ありて偕に居ることを可しとせば、之を去るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'また女に不 信者なる夫ありて偕に居ることを可しとせば、夫を去るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'そは不 信者なる夫は妻によりて潔くなり、不 信者なる妻は夫によりて潔くなりたればなり。然なくば汝らの子供は潔からず、されど今は潔き者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, '不 信者みづから離れ去らば、その離るるに任せよ。斯くのごとき事あらば、兄弟または姉妹、もはや繋がるる所なし。神の汝らを召し給へるは平和を得させん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, '妻よ、汝いかで夫を救ひ得るや否やを知らん。夫よ、汝いかで妻を救ひ得るや否やを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, '唯おのおの主の分ち賜ふところ、神の召し給ふところに循ひて歩むべし。凡ての教會に我が命ずるは斯くのごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, '割禮ありて召されし者あらんか、その人、割禮を廢つべからず。割禮なくして召されし者あらんか、その人、割禮を受くべからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, '割禮を受くるも受けぬも數ふるに足らず、ただ貴きは神の誡命を守ることなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, '各人その召されし時の状に止るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'なんぢ奴隷にて召されたるか、之を思ひ煩ふな(もし釋さるることを得ばゆるされよ)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, '召されて主にある奴隷は、主につける自主の人なり。斯くのごとく自主にして召されたる者は、キリストの奴隷なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, '汝らは價をもて買はれたる者なり。人の奴隷となるな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, '兄弟よ、おのおの召されし時の状に止りて神と偕に居るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, '處女のことに就きては主の命を受けず、然れど主の憐憫によりて忠實の者となりたれば、我が意見を告ぐべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'われ思ふに、目前の患難のためには、人その在るが隨にて止るぞ善き。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'なんぢ妻に繋がるる者なるか、釋くことを求むな。妻に繋がれぬ者なるか、妻を求むな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'たとひ妻を娶るとも罪を犯すにはあらず。處女もし嫁ぐとも罪を犯すにあらず。然れどかかる者はその身、苦難に遭はん、我なんぢらを苦難に遭はすに忍びず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, '兄弟よ、われ之を言はん、時は縮れり。されば此よりのち妻を有てる者は有たぬが如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, '泣く者は泣かぬが如く、喜ぶ者は喜ばぬが如く、買ふ者は有たぬが如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, '世を用ふる者は用ひ盡さぬが如くすべし。此の世の状態は過ぎ往くべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'わが欲する所は汝らが思ひ煩はざらん事なり。婚姻せぬ者は如何にして主を喜ばせんと主のことを慮ぱかり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, '婚姻せし者は如何にして妻を喜ばせんと、世のことを慮ぱかりて心を分つなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, '婚姻せぬ女と處女とは身も靈も潔くならんために主のことを慮ぱかり、婚姻せし者は如何にしてその夫を喜ばせんと世のことを慮ぱかるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'わが之を言ふは汝らを益せん爲にして、汝らに絆を置かんとするにあらず、寧ろ汝らを宣しきに適はせ、餘念なく只管、主に事へしめんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, '人もし處女たる己が娘に對すること宣しきに適はずと思ひ、年の頃もまた過ぎんとし、かつ然せざるを得ずば、心のままに行ふべし。これ罪を犯すにあらず、婚姻せさすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'されど人もし其の心を堅くし、止むを得ざる事もなく、又おのが心の隨になすを得て、その娘を留め置かんと心のうちに定めたらば、然するは善きなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'されば其の娘を嫁がする者の行爲は善し。されど之を嫁がせぬ者の行爲は更に善し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, '妻は夫の生ける間は繋がるるなり。然れど夫もし死なば、欲するままに嫁ぐ自由を得べし、また主にある者にのみ適くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, '然れど我が意見にては、その儘に止らば殊に幸福なり。我もまた神の御靈に感じたりと思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, '偶像の供物に就きては我等みな知識あることを知る。知識は人を誇らしめ、愛は徳を建つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'もし人みづから知れりと思はば、知るべき程の事をも知らぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'されど人もし神を愛せば、その人、神に知られたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, '偶像の供物を食ふことに就きては、我ら偶像の世になき者なるを知り、また唯一の神の外には神なきを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, '神と稱ふるもの、或は天に或は地にありて、多くの神、おほくの主あるが如くなれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, '我らには父なる唯一の神あるのみ、萬物これより出で、我らも亦これに歸す。また唯一の主イエス・キリストあるのみ、萬物これに由り、我らも亦これに由れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'されど人みな此の知識あるにあらず、或 人は今もなほ偶像に慣れ、偶像の献物として食する故に、その良心よわくして汚さるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, '我らを神の前に立たしむるものは食物にあらず、されば食するも益なく、食せざるも損なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'されど心して汝らの有てる此の自由を弱き者の躓物とすな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, '人もし知識ある汝が偶像の宮にて食事するを見んに、その人 弱きときは良心そそのかされて偶像の献物を食せざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'さらばキリストの代りて死に給ひし弱き兄弟は、汝の知識によりて亡ぶべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, '斯くのごとく汝ら兄弟に對して罪を犯し、その弱き良心を傷めしむるは、キリストに對して罪を犯すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'この故に、もし食物わが兄弟を躓かせんには、兄弟を躓かせぬ爲に、我は何時までも肉を食はじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, '我は自主の者ならずや、使徒にあらずや、我らの主イエスを見しにあらずや、汝らは主に在りて我が業ならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'われ他の人には使徒ならずとも汝らには使徒なり。汝らは主にありて我が使徒たる職の印なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'われを審く者に對する我が辯明は斯くのごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, '我らは飮食する權なきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, '我らは他の使徒たち主の兄弟たち及びケパのごとく、姉妹たる妻を携ふる權なきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'ただ我とバルナバとのみ工を止むる權なきか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, '誰か己の財にて兵卒を務むる者あらんや。誰か葡萄畑を作りてその果を食はぬ者あらんや。誰か群を牧ひてその乳を飮まぬ者あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, '我ただ人の思にのみ由りて此 等のことを言はんや、律法も亦かく言ふにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'モーセの律法に『穀物を碾す牛には口籠を繋くべからず』と録したり。神は牛のために慮ぱかり給へるか、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'また專ら我等のために之を言ひ給ひしか、然り、我らのために録されたり。それ耕す者は望をもて耕し、穀物をこなす者は之に與る望をもて碾すべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'もし我ら靈の物を汝らに蒔きしならば、汝らの肉の物を刈り取るは過分ならんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'もし他の人なんぢらに對してこの權あらんには、まして我らをや。然れど我等はこの權を用ひざりき。唯キリストの福音に障碍なきやうに一切のことを忍ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'なんぢら知らぬか、聖なる事を務むる者は宮のものを食し、祭壇に事ふる者は祭壇のものに與るを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, '斯くのごとく主もまた福音を宣傳ふる者の福音によりて生活すべきことを定め給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'されど我は此 等のことを一つだに用ひし事なし、また自ら斯くせられんために之を書き贈るにあらず、斯くせられんよりは寧ろ死ぬるを善しとすればなり。誰もわが誇を空しくせざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'われ福音を宣傳ふとも誇るべき所なし、已むを得ざるなり。もし福音を宣傳へずば、我は禍害なるかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, '若しわれ心より之をなさば報を得ん、たとひ心ならずとも我はその務を委ねられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, '然らば我が報は何ぞ、福音を宣傳ふるに、人をして費なく福音を得しめ、而も福音によりて我が有てる權を用ひ盡さぬこと是なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'われ凡ての人に對して自主の者なれど、更に多くの人を得んために、自ら凡ての人の奴隷となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, '我ユダヤ人にはユダヤ人の如くなれり、これユダヤ人を得んが爲なり。律法の下にある者には――律法の下に我はあらねど――律法の下にある者の如くなれり。これ律法の下にある者を得んが爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, '律法なき者には――われ神に向ひて律法なきにあらず、反つてキリストの律法の下にあれど――律法なき者の如くなれり、これ律法なき者を得んがためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, '弱き者には弱き者となれり、これ弱き者を得んためなり。我すべての人には凡ての人の状に從へり、これ如何にもして幾許かの人を救はんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'われ福音のために凡ての事をなす、これ我も共に福音に與らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'なんぢら知らぬか、馳場を走る者はみな走れども、褒美を得る者の、ただ一人なるを。汝らも得んために斯く走れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'すべて勝を爭ふ者は何事をも節し愼む、彼らは朽つる冠冕を得んが爲なれど、我らは朽ちぬ冠冕を得んがために之をなすなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, '斯く我が走るは目標なきが如きにあらず、我が拳鬪するは空を撃つが如きにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'わが體を打ち擲きて之を服從せしむ。恐らくは他人に宣傳へて自ら棄てらるる事あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, '兄弟よ、我なんぢらが之を知らぬを好まず。即ち我らの先祖はみな雲の下にあり、みな海をとほり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'みな雲と海とにてバプテスマを受けてモーセにつけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, '而して皆おなじく靈なる食物を食し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'みな同じく靈なる飮物を飮めり。これ彼らに隨ひし靈なる岩より飮みたるなり、その岩は即ちキリストなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, '然れど彼らのうち多くは神の御意に適はず、荒野にて亡されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, '此 等のことは我らの鑑にして、彼らが貪りし如く惡を貪らざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, '彼らの中の或 者に效ひて偶像を拜する者となるな、即ち『民は坐して飮食し立ちて戯る』と録されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, '又かれらの中の或 者に效ひて我ら姦淫すべからず、姦淫を行ひしもの一日に二萬 三 千 人 死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'また彼 等のうちの或 者に效ひて我ら主を試むべからず、主を試みしもの蛇に亡されたり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, '又かれらの中の或 者に效ひて呟くな、呟きしもの亡す者に亡されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, '彼らが遭へる此 等のことは鑑となれり、かつ末の世に遭へる我らの訓戒のために録されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'さらば自ら立てりと思ふ者は倒れぬやうに心せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, '汝らが遭ひし試煉は人の常ならぬはなし。神は眞實なれば、汝らを耐へ忍ぶこと能はぬほどの試煉に遭はせ給はず。汝らが試煉を耐へ忍ぶことを得んために之と共に遁るべき道を備へ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'さらば我が愛する者よ、偶像を拜することを避けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'され慧き者に言ふごとく言はん、我が言ふところを判斷せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, '我らが祝ふところの祝の酒杯は、これキリストの血に與るにあらずや。我らが擘く所のパンは、これキリストの體に與るにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'パンは一つなれば、多くの我らも一體なり、皆ともに一つのパンに與るに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, '肉によるイスラエルを視よ、供物を食ふ者は祭壇に與るにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'さらば我が言ふところは何ぞ、偶像の供物はあるものと言ふか、また、偶像はあるものと言ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, '否、我は言ふ、異邦人の供ふる物は神に供ふるにあらず、惡鬼に供ふるなりと。我なんぢらが惡鬼と交るを欲せず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'なんぢら主の酒杯と惡鬼の酒杯とを兼ね飮むこと能はず。主の食卓と惡鬼の食卓とに兼ね與ること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'われら主の妬を惹起さんとするか、我らは主よりも強き者ならんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, '一切のもの可からざるなし、然れど一切のもの益あるにあらず、一切のもの可からざるなし、されど、一切のもの徳を建つるにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, '各人おのが益を求むることなく、人の益を求めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'すべて市場にて賣る物は、良心のために何をも問はずして食せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'そは地と之に滿つる物とは主の物なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'もし不 信者に招かれて往かんとせば、凡て汝らの前に置く物を、良心のために何をも問はずして食せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, '人もし此は犧牲にせし肉なりと言はば、告げし者のため、また良心のために食すな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, '良心とは汝の良心にあらず、かの人の良心を言ふなり。何ぞわが自由を他の人の良心によりて審かるる事をせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'もし感謝して食する事をせば、何ぞわが感謝する所のものに就きて譏らるる事をせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'さらば食ふにも飮むにも何事をなすにも、凡て神の榮光を顯すやうにせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'ユダヤ人にもギリシヤ人にも、また、神の教會にも躓物となるな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, '我も凡ての事を凡ての人の心に適ふやうに力め、人々の救はれんために、己の益を求めずして多くの人の益を求むるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, '我がキリストに效ふ者なる如く、なんぢら我に效ふ者となれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, '汝らは凡ての事につきて我を憶え、且わが傳へし所をそのまま守るに因りて、我なんぢらを譽む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'されど我なんぢらが之を知らんことを願ふ。凡ての男の頭はキリストなり、女の頭は男なり、キリストの頭は神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'すべて男は祈をなし、預言をなすとき、頭に物を被るは其の頭を辱しむるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'すべて女は祈をなし、預言をなすとき、頭に物を被らぬは其の頭を辱しむるなり。これ薙髮と異なる事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, '女もし物を被らずば、髮をも剪るべし。されど髮を剪り或は薙ることを女の恥とせば、物を被るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, '男は神の像、神の榮光なれば、頭に物を被るべきにあらず、されど女は男の光榮なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, '男は女より出でずして、女は男より出で、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, '男は女のために造られずして、女は男のために造られたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'この故に女は御使たちの故によりて頭に權の徽を戴くべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'されど主に在りては、女は男に由らざるなく、男は女に由らざるなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, '女の男より出でしごとく、男は女によりて出づ。而して萬物はみな神より出づるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, '汝 等みづから判斷せよ、女の物を被らずして神に祈るは宣しき事なるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'なんぢら自然に知るにあらずや、男もし長き髮の毛あらば恥づべきことにして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, '女もし長き髮の毛あらばその光榮なるを。それ女の髮の毛は被物として賜はりたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, '假令これを坑辯ふ者ありとも、斯くのごとき例は我らにも神の諸 教會にもある事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, '我これらの事を命じて汝らを譽めず。汝らの集ること益を受けずして損を招けばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, '先づ汝らが教會に集るとき分爭ありと聞く、われ略これを信ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'それは汝 等のうちに是とせらるべき者の現れんために黨派も必ず起るべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'なんぢら一處に集るとき、主の晩餐を食すること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, '食する時おのおの人に先だちて己の晩餐を食するにより、饑うる者あり、醉ひ飽ける者あればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, '汝ら飮食すべき家なきか、神の教會を輕んじ、また乏しき者を辱しめんとするか、我なにを言ふべきか、汝らを譽むべきか、之に就きては譽めぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'わが汝らに傳へしことは主より授けられたるなり。即ち主イエス付され給ふ夜、パンを取り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, '祝して之を擘き、而して言ひ給ふ『これは汝 等のための我が體なり。我が記念として之を行へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, '夕餐ののち酒杯をも前の如くして言ひたまふ『この酒杯は我が血によれる新しき契約なり。飮むごとに我が記念として之をおこなへ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, '汝 等このパンを食し、この酒杯を飮むごとに、主の死を示して其の來りたまふ時にまで及ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'されば宣しきに適はずして主のパンを食し、主の酒杯を飮む者は、主の體と血とを犯すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, '人みづから省みて後、そのパンを食し、その酒杯を飮むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, '御體を辨へずして飮食する者は、その飮食によりて自ら審判を招くべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'この故に汝 等のうちに弱きもの病めるもの多くあり、また眠に就きたる者も少からず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, '我等もし自ら己を辨へなば審かるる事なからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'されど審かるる事のあるは、我らを世の人とともに罪に定めじとて、主の懲しめ給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'この故に、わが兄弟よ、食せんとて集るときは互に待ち合せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'もし飢うる者あらば、汝らの集會の審判を招くこと無からん爲に、己が家にて食すべし。その他のことは我いたらん時これを定めん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, '兄弟よ、靈の賜物に就きては、我なんぢらが知らぬを好まず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'なんぢら異邦人なりしとき、誘はるるままに物を言はぬ偶像のもとに導き往かれしは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, '然れば我なんぢらに示さん、神の御靈に感じて語る者は、誰も『イエスは詛はるべき者なり』と言はず、また聖 靈に感ぜざれば、誰も『イエスは主なり』と言ふ能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, '賜物は殊なれども、御靈は同じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, '務は殊なれども、主は同じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, '活動は殊なれども、凡ての人のうちに凡ての活動を爲したまふ神は同じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, '御靈の顯現をおのおのに賜ひたるは、益を得させんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, '或 人は御靈によりて智慧の言を賜はり、或 人は同じ御靈によりて知識の言、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, '或 人は同じ御靈によりて信仰、ある人は一つ御靈によりて病を醫す賜物、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, '或 人は異能ある業、ある人は預言、ある人は靈を辨へ、或 人は異言を言ひ、或 人は異言を釋く能力を賜はる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, '凡て此 等のことは同じ一つの御靈の活動にして、御靈その心に隨ひて各人に分け與へたまふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, '體は一つにして肢は多し、體の肢は多くとも一つの體なるが如く、キリストも亦 然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, '我らはユダヤ人・ギリシヤ人・奴隷・自主の別なく、一體とならん爲に、みな一つ御靈にてバプテスマを受けたり。而してみな一つ御靈を飮めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, '體は一 肢より成らず、多くの肢より成るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, '足もし『我は手にあらぬ故に體に屬せず』と云ふとも、之によりて體に屬せぬにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, '耳もし『それは眼にあらぬ故に體に屬せず』と云ふとも、之によりて體に屬せぬにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'もし全身、眼ならば、聽くところ何れか。もし全身、聽く所ならば、臭ぐところ何れか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'げに神は御意のままに肢をおのおの體に置き給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, '若しみな一 肢ならば、體は何れか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'げに肢は多くあれど、體は一つなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, '眼は手に對ひて『われ汝を要せず』と言ひ、頭は足に對ひて『われ汝を要せず』と言ふこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, '否、からだの中にて最も弱しと見ゆる肢は、反つて必要なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, '體のうちにて尊からずと思はるる所に、物を纏ひて殊に之を尊ぶ。斯く我らの美しからぬ所は、一層すぐれて美しくすれども、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, '美しき所には、物を纏ふの要なし。神は劣れる所に殊に尊榮を加へて、人の體を調和したまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'これ體のうちに分爭なく、肢々 一致して互に相 顧みんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'もし一つの肢 苦しまば、もろもろの肢ともに苦しみ、一つの肢 尊ばれなば、もろもろの肢ともに喜ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, '乃ち汝らはキリストの體にして各自その肢なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, '神は第一に使徒、第二に預言者、第三に教師、その次に異能ある業、次に病を醫す賜物、補助をなす者、治むる者、異言などを教會に置きたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, '是みな使徒ならんや、みな預言者ならんや、みな教師ならんや、みな異能ある業を行ふ者ならんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'みな病を醫す賜物を有てる者ならんや、みな異言を語る者ならんや、みな異言を釋く者ならんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'なんぢら優れたる賜物を慕へ、而して我さらに善き道を示さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'たとひ我もろもろの國人の言および御使の言を語るとも、愛なくば鳴る鐘や響く鐃鈸の如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, '假令われ預言する能力あり、又すべての奧義と凡ての知識とに達し、また山を移すほどの大なる信仰ありとも、愛なくば數ふるに足らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'たとひ我わが財産をことごとく施し、又わが體を燒かるる爲に付すとも、愛なくば我に益なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, '愛は寛容にして慈悲あり。愛は妬まず、愛は誇らず、驕らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, '非禮を行はず、己の利を求めず、憤ほらず、人の惡を念はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, '不義を喜ばずして、眞理の喜ぶところを喜び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, '凡そ事 忍び、おほよそ事 信じ、おほよそ事 望み、おほよそ事 耐ふるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, '愛は長久までも絶ゆることなし。然れど預言は廢れ、異言は止み、知識もまた廢らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'それ我らの知るところ全からず、我らの預言も全からず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, '全き者の來らん時は全からぬもの廢らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'われ童子の時は語ることも童子のごとく、思ふことも童子の如く、論ずる事も童子の如くなりしが、人と成りては童子のことを棄てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, '今われらは鏡をもて見るごとく見るところ朧なり。然れど、かの時には顏を對せて相 見ん。今わが知るところ全からず、然れど、かの時には我が知られたる如く全く知るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'げに信仰と希望と愛と此の三つの者は限りなく存らん、而して其のうち最も大なるは愛なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, '愛を追ひ求めよ、また靈の賜物、ことに預言する能力を慕へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, '異言を語る者は人に語るにあらずして神に語るなり。そは靈にて奧義を語るとも、誰も悟る者なければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'されど預言する者は人に語りて其の徳を建て、勸をなし、慰安を與ふるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, '異言を語る者は己の徳を建て、預言する者は教會の徳を建つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'われ汝 等がみな異言を語らんことを欲すれど、殊に欲するは預言せん事なり。異言を語る者、もし釋きて教會の徳を建つるにあらずば、預言する者のかた勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, '然らば兄弟よ、我もし汝らに到りて異言をかたり、或は默示、あるいは知識、あるいは預言、あるいは教をもて語らずば、何の益かあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, '生命なくして聲を出すもの、或は笛、あるいは立琴、その音もし差別なくば、爭で吹くところ彈くところの何たるを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'ラッパ若し定りなき音を出さば、誰か戰鬪の備をなさん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, '斯くのごとく汝らも舌をもて明かなる言を出さずば、いかで語るところの何たるを知らん、これ汝 等ただ空氣に語るのみ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, '世には國語の類おほかれど、一つとして意義あらぬはなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, '我もし國語の意義を知らずば、語る者に對して夷人となり、語る者も我に對して夷人とならん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, '然らば汝らも靈の賜物を慕ふ者なれば、教會の徳を建つる目的にて賜物の豐ならん事を求めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'この故に異言を語る者は自ら釋き得んことをも祈るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, '我もし異言をもて祈らば、我が靈は祈るなれど、我が心は果を結ばず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, '然らば如何にすべきか、我は靈をもて祈り、また心をもて祈らん。我は靈をもて謳ひ、また心をもて謳はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, '汝もし然せずば、靈をもて祝するとき、凡人は汝の語ることを知らねば、その感謝に對し如何にしてアァメンと言はんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'なんぢの感謝はよし、然れど、その人の徳を建つることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, '我なんぢら衆の者よりも多く異言を語ることを神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, '然れど我は教會にて異言をもて一萬 言を語るよりも、寧ろ人を教へんために我が心をもて五言を語らんことを欲するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, '兄弟よ、智慧に於ては子供となるな、惡に於ては幼兒となり、智慧に於ては成人となれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, '律法に録して『主、宣はく、他し言の民により、他し國人の口唇をもて此の民に語らん、然れど尚かれらは我に聽かじ』とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'されば異言は、信者の爲ならで不 信者のための徴なり。預言は、不 信者の爲ならで信者のためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'もし全 教會 一處に集れる時、みな異言にて語らば、凡人または不 信者いり來らんに、汝らを狂へる者と言はざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, '然れど若しみな預言せば、不 信者または凡人の入りきたるとき、會衆のために自ら責められ、會衆のために是非せられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'その心の秘密あらはるる故に、伏して神を拜し『神は實に汝らの中に在す』と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, '兄弟よ、さらば如何にすべきか、汝らの集る時はおのおの聖歌あり、教あり、默示あり、異言あり、釋く能力あり、みな徳を建てん爲にすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'もし異言を語る者あらば、二人、多くとも三人、順次に語りて一人これを釋くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'もし釋く者なき時は、教會にては默し、而して己に語り、また神に語るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, '預言者は二人もしくは三人かたり、その他の者はこれを辨ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'もし坐しをる、他のもの默示を蒙らば、先のもの默すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, '汝らは皆すべての人に學ばせ勸を受けしめんために、一人 一人 預言することを得べければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'また預言者の靈は預言者に制せらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'それ神は亂の神にあらず、平和の神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, '聖徒の諸 教會のするごとく、女は教會にて默すべし。彼らは語ることを許されず。律法に云へるごとく順ふべき者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, '何事か學ばんとする事あらば、家にて己が夫に問ふべし、女の教會にて語るは恥づべき事なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, '神の言は汝 等より出でしか、また汝 等にのみ來りしか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, '人もし自己を預言者とし、或は御靈に感じたる者と思はば、わが汝らに書きおくる言を主の命なりと知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'もし知らずば其の知らざるに任せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'されば我が兄弟よ、預言することを慕ひ、また異言を語ることを禁ずな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, '凡ての事、宣しきに適ひ、かつ秩序を守りて行へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, '兄弟よ、曩にわが傳へし福音を更に復なんぢらに示す。汝らは之を受け、之に頼りて立ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'なんぢら徒らに信ぜずして、我が傳へしままを堅く守らば、この福音に由りて救はれん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'わが第一に汝らに傳へしは、我が受けし所にして、キリスト聖書に應じて我らの罪のために死に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'また葬られ、聖書に應じて三日めに甦へり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'ケパに現れ、後に十二 弟子に現れ給ひし事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, '次に五 百 人 以上の兄弟に同時にあらはれ給へり。その中には既に眠りたる者もあれど、多くは今なほ世にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, '次にヤコブに現れ、次にすべての使徒に現れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, '最終には月 足らぬ者のごとき我にも現れ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, '我は神の教會を迫害したれば、使徒と稱へらるるに足らぬ者にて、使徒のうち最 小き者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, '然るに我が今の如くなるは、神の恩惠に由るなり。斯くてその賜はりし御惠は空しくならずして、凡ての使徒よりも我は多く働けり。これ我にあらず、我と偕にある神の恩惠なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'されば我にもせよ、彼 等にもせよ、宣傳ふる所はかくの如くにして、汝らは斯くのごとく信じたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'キリストは死人の中より甦へり給へりと宣傳ふるに、汝 等のうちに、死人の復活なしと云ふ者のあるは何ぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'もし死人の復活なくば、キリストもまた甦へり給はざりしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'もしキリスト甦へり給はざりしならば、我らの宣教も空しく、汝らの信仰もまた空しからん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'かつ我らは神の僞證 人と認められん。我ら神はキリストを甦へらせ給へりと證したればなり。もし死人の甦へることなくば、神はキリストを甦へらせ給はざりしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'もし死人の甦へる事なくば、キリストも甦へり給はざりしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, '若しキリスト甦へり給はざりしならば、汝らの信仰は空しく、汝 等なほ罪に居らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, '然ればキリストに在りて眠りたる者も亡びしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, '我等この世にあり、キリストに頼りて空しき望みを懷くに過ぎずば、我らは凡ての人の中にて最も憫むべき者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, '然れど正しくキリストは死人の中より甦へり、眠りたる者の初穗となり給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'それ人によりて死の來りし如く、死人の復活もまた人に由りて來れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, '凡ての人、アダムに由りて死ぬるごとく、凡ての人、キリストに由りて生くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, '而して各人その順序に隨ふ。まづ初穗なるキリスト、次はその來り給ふときキリストに屬する者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, '次には終きたらん、その時キリストは、もろもろの權能・權威・權力を亡して國を父なる神に付し給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, '彼は凡ての敵をその足の下に置き給ふまで、王たらざるを得ざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, '最後の敵なる死もまた亡されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, '『神は萬の物を彼の足の下に服はせ給ひ』たればなり。萬の物を彼に服はせたりと宣ふときは、萬の物を服はせ給ひし者のその中になきこと明かなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, '萬の物かれに服ふときは、子も亦みづから萬の物を己に服はせ給ひし者に服はん。これ神は萬の物に於て萬の事となり給はん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'もし復活なくば、死人の爲にバプテスマを受くるもの何をなすか、死人の甦へること全くなくば、死人のためにバプテスマを受くるは何の爲ぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'また我らが何時も危険を冒すは何の爲ぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, '兄弟よ、われらの主イエス・キリストに在りて、汝 等につき我が有てる誇によりて誓ひ、我は日々に死すと言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, '我がエペソにて獸と鬪ひしこと、若し人のごとき思にて爲ししならば、何の益あらんや。死人もし甦へる事なくば『我等いざ飮食せん、明日 死ぬべければなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'なんぢら欺かるな、惡しき交際は善き風儀を害ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'なんぢら醒めて正しうせよ、罪を犯すな。汝 等のうちに神を知らぬ者あり、我が斯く言ふは汝 等を辱しめんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'されど人あるひは言はん、死人いかにして甦へるべきか、如何なる體をもて來るべきかと。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, '愚なる者よ、なんぢの播く所のもの先づ死なずば生きず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, '又その播く所のものは後に成るべき體を播くにあらず、麥にても他の穀にても、ただ種粒のみ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, '然るに神は御意に隨ひて之に體を予へ、おのおのの種にその體を予へたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, '凡ての肉、おなじ肉にあらず、人の肉あり、獸の肉あり、鳥の肉あり、魚の肉あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, '天上の體あり、地上の體あり、されど天上の物の光榮は地上の物と異なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, '日の光榮あり、月の光榮あり、星の光榮あり、此の星は彼の星と光榮を異にす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, '死人の復活もまた斯くのごとし。朽つる物にて播かれ、朽ちぬものに甦へらせられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, '卑しき物にて播かれ、光榮あるものに甦へらせられ、弱きものにて播かれ、強きものに甦へらせられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, '血氣の體にて播かれ、靈の體に甦へらせられん。血氣の體ある如く、また靈の體あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, '録して、始の人アダムは、活ける者となれるとあるが如し。而して終のアダムは、生命を與ふる靈となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, '靈のものは前にあらず、反つて血氣のもの前にありて靈のもの後にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, '第一の人は地より出でて土に屬し、第二の人は天より出でたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'この土に屬する者に、すべて土に屬する者は似、この天に屬する者に、すべて天に屬する者は似るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, '我ら土に屬する者の形を有てるごとく、天に屬する者の形をも有つべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, '兄弟よ、われ之を言はん、血肉は神の國を嗣ぐこと能はず、朽つるものは朽ちぬものを嗣ぐことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, '視よ、われ汝らに奧義を告げん、我らは悉とく眠るにはあらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, '終のラッパの鳴らん時みな忽ち瞬間に化せん。ラッパ鳴りて死人は朽ちぬ者に甦へり、我らは化するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'そは此の朽つる者は朽ちぬものを著、この死ぬる者は死なぬものを著るべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, '此の朽つるものは朽ちぬものを著、この死ぬる者は死なぬものを著んとき『死は勝に呑まれたり』と録されたる言は成就すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '『死よ、なんぢの勝は何處にかある。死よ、なんぢの刺は何處にかある』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, '死の刺は罪なり、罪の力は律法なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'されど感謝すべきかな、神は我らの主イエス・キリストによりて勝を與へたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, '然れば我が愛する兄弟よ、確くして搖くことなく、常に勵みて主の事を務めよ、汝 等その勞の、主にありて空しからぬを知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, '聖徒たちの爲にする寄附の事に就きては、汝らも我がガラテヤの諸 教會に命ぜしごとくせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, '一週の首の日ごとに、各人その得る所にしたがひて己が家に貯へ置け、これ我が到らんとき始めて寄附を集むる事なからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'われ到らば、汝らが選ぶところの人々に添書をあたへ、汝らの惠む物をエルサレムに携へ往かしめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'もし我も往くべきならば、彼らは我と共に往くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, '我マケドニヤを通らんとすれば、マケドニヤを過ぎて後に汝らの許にゆかん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'かくて汝らの中に留りゐて、或は冬を過すこともあらん、是わが何處に往くも汝らに送られん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, '我は今なんぢらを途の次に見ることを欲せず、主ゆるし給はば、暫く汝らと偕に留らんことを望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'われ五旬節まではエペソに留らんとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'そは活動のために大なる門わが前にひらけ、また逆ふ者も多ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'テモテもし到らば、愼みて汝 等のうちに懼なく居らしめよ、彼は我と同じく主の業を務むる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'されば誰も之を卑しむることなく、安らかに送りて我が許に來らしめよ、我かれが兄弟たちと共に來るを待てるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, '兄弟アポロに就きては、我かれに兄弟たちと共に汝らに到らんことを懇ろに勸めたりしが、今は往くことを更に欲せず、されど好き機を得ば往くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, '目を覺し、堅く信仰に立ち、雄々しく、かつ剛かれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, '一切のこと愛をもて行へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, '兄弟よ、ステパナの家はアカヤの初穗にして、彼らが身を委ねて聖徒に事へたることは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'われ汝らに勸む、斯くのごとき人々また凡て之とともに働きて勞する者に服せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, '我ステパナとポルトナトとアカイコとの來るを喜ぶ。かれらは汝らの居らぬを補ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, '彼らは我が心と汝らの心とを安んじたり、斯くのどとき者を認めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'アジヤの諸 教會なんぢらに安否を問ふ。アクラとプリスカ及びその家の教會、主に在りて懇ろに汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'すべての兄弟なんぢらに安否を問ふ。なんぢら潔き接吻をもて互に安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, '我パウロ自筆をもて汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'もし人、主を愛せずば詛はるべし、我らの主きたり給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, '願はくは主イエスの恩惠なんぢらと偕にあらんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'わが愛はキリスト・イエスに在りて汝 等すべての者とともに在るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, '神の御意によりてイエス・キリストの使徒となれるパウロ及び兄弟テモテ、書をコリントに在る神の教會、ならびにアカヤ全國に在る凡ての聖徒に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, '願はくは我らの父なる神および主イエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, '讃むべき哉、われらの主イエス・キリストの父なる神、即ちもろもろの慈悲の父、一切の慰安の神、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'われらを凡ての患難のうちに慰め、我等をして自ら神に慰めらるる慰安をもて、諸般の患難に居る者を慰むることを得しめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'そはキリストの苦難われらに溢るる如く、我らの慰安も亦キリストによりて溢るればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, '我ら或は患難を受くるも汝らの慰安と救とのため、或は慰安を受くるも汝らの慰安の爲にして、その慰安は汝らの中に働きて、我らが受くる如き苦難を忍ぶことを得しむるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'かくて汝らが苦難に與るごとく、また慰安にも與ることを知れば、汝らに對する我らの望は堅し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, '兄弟よ、我らがアジヤにて遭ひし患難を汝らの知らざるを好まず、すなはち壓せらるること甚だしく、力 耐へがたくして、生くる望を失ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, '心のうちに死を期するに至れり。これ己を頼まずして、死人を甦へらせ給ふ神を頼まん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, '神は斯かる死より我らを救ひ給へり、また救ひ給はん。我らは後もなほ救ひ給はんことを望みて神を頼み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, '汝らも我らの爲に祈をもて助く。これ多くの人の願望によりて賜はる恩惠を、多くの人の感謝するに至らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'われら世に在りて殊に汝らに對し、神の清淨と眞實とをもて、また肉の智慧によらず、神の恩惠によりて行ひし事は、我らの良心の證する所にして、我らの誇なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, '我らの書き贈ることは、汝らの讀むところ知る所の他ならず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, '而して我は汝 等のうち或 者の既に知れる如く、我らの主イエスの日に我らが汝らの誇、なんぢらが我らの誇たるを終まで知らんことを望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'この確信をもて先づ汝らに到り、再び益を得させ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'かくて汝らを經てマケドニアに往き、マケドニアより更に復なんぢらに到り、而して汝らに送られてユダヤに往かんことを定めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'かく定めたるは浮きたる事ならんや。わが定むるところ肉によりて定め、然り然り、否 々と言ふが如きこと有らんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, '神は眞實にて在せば、我らが汝らに對する言も、然りまた否と言ふが如きにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, '我ら即ちパウロ、シルワノ、テモテが汝らの中に傳へたる神の子キリスト・イエスは、然りまた否と言ふが如き者にあらず、然りと言ふことは彼によりて成りたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, '神の約束は多くありとも、然りと言ふことは彼によりて成りたれば、彼によりてアァメンあり、我ら神に榮光を歸するに至る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, '汝らと共に我らをキリストに堅くし、且われらに膏を注ぎ給ひし者は神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, '神はまた我らに印し、保證として御靈を我らの心に賜へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, '我わが靈魂を賭けて神の證を求む、我がコリントに往くことの遲きは、汝らを寛うせん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'されど我らは汝らの信仰を掌どる者にあらず、汝らの喜悦を助くる者なり、汝らは信仰によりて立てばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'われ再び憂をもて汝らに到らじと自ら定めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, '我もし汝らを憂ひしめば、我が憂ひしむる者のほかに誰か我を喜ばせんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'われ前に此の事を書き贈りしは、我が到らんとき、我を喜ばすべきもの、反つて我を憂ひしむる事のなからん爲にして、汝らは皆わが喜悦を喜悦とするを信ずるに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'われ大なる患難と心の悲哀とにより、多くの涙をもて汝らに書き贈れり。これ汝らを憂ひしめんとにあらず、我が汝らに對する愛の溢るるばかりなるを知らしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'もし憂ひしむる人あらば、我を憂ひしむるにあらず、幾許か汝ら衆を憂ひしむるなり。(幾許かと云へるは、われ激しく責むるを好まぬ故なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'かかる人の多數の者より受けたる懲罰は足れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'されば汝ら寧ろ彼を恕し、かつ慰めよ、恐らくは其の人、甚だしき愁に沈まん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'この故に我なんぢらの愛を彼に顯さんことを勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, '前に書き贈りしは、凡ての事につきて汝らが從順なりや否やをも試み知らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'なんぢら何事にても人を恕さば、我も亦これを恕さん、われ恕したる事あらば、汝らの爲にキリストの前に恕したるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'これサタンに欺かれざらん爲なり、我等はその詭謀を知らざるにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, '我キリストの福音の爲にトロアスに到り、主われに門を開き給ひたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, '我が兄弟テトスに逢はぬによりて心に平安をえず、彼處の者に別を告げてマケドニヤに往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, '感謝すべきかな、神は何時にてもキリストにより、我らを執へて凱旋し、何處にても我等によりてキリストを知る知識の馨をあらはし給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, '救はるる者にも亡ぶる者にも、我らは神に對してキリストの香しき馨なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'この人には死よりいづる馨となりて死に至らしめ、かの人には生命より出づる馨となりて生命に至らしむ。誰か此の任に耐へんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, '我らは多くの人のごとく神の言を曲げず、眞實により神による者のごとく、神の前にキリストに在りて語るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, '我等ふたたび己を薦め始めんや、また或 人のごとく人の推薦の書を汝らに齎し、また汝 等より受くることを要せんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, '汝らは即ち我らの書にして我らの心に録され、又すべての人に知られ、かつ讀まるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, '汝らは明かに我らの職によりて書かれたるキリストの書なり。而も墨にあらで活ける神の御靈にて録され、石碑にあらで心の肉碑に録されたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, '我らはキリストにより、神に對して斯かる確信あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'されど己は何事をも自ら定むるに足らず、定むるに足るは神によるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, '神は我らを新約の役者となるに足らしめ給へり、儀文の役者にあらず、靈の役者なり。そは儀文は殺し、靈は活せばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, '石に彫り書されたる死の法の職にも光榮ありて、イスラエルの子 等はそのやがて消ゆべきモーセの顏の光榮を見つめ得ざりし程ならんには、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'まして靈の職は光榮なからんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, '罪を定むる職もし光榮あらんには、まして義とする職は光榮に溢れざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'もと光榮ありし者も更に勝れる光榮に比ぶれば、光榮なき者となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'もし消ゆべき者に光榮ありしならんには、まして永存ふるものに光榮なからんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, '我らは斯くのごとき希望を有つゆゑに、更に臆せずして言ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, '又モーセの如くせざるなり。彼は消ゆべき者の消えゆくをイスラエルの子らに見せぬために、面帕を顏におほひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, '然れど彼らの心 鈍くなれり。キリストによりて面帕の廢るべきを悟らねば、今日に至るまで舊約を讀む時その面帕なほ存れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, '今日に至るまでモーセの書を讀むとき、面帕は彼らの心のうへに置かれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, '然れど主に歸する時、その面帕は取り除かるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, '主は即ち御靈なり、主の御靈のある所には自由あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, '我等はみな面帕なくして、鏡に映るごとく主の榮光を見、榮光より榮光にすすみ、主たる御靈によりて主と同じ像に化するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'この故に我ら憐憫を蒙りて此の職を受けたれば、落膽せず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, '恥づべき隱れたる事をすて、惡巧に歩まず、神の言をみださず、眞理を顯して神の前に己を凡ての人の良心に薦むるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'もし我らの福音おほはれ居らば、亡ぶる者に覆はれをるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'この世の神は此 等の不 信者の心を暗まして、神の像なるキリストの榮光の福音の光を照さざらしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, '我らは己の事を宣べず、ただキリスト・イエスの主たる事と、我らがイエスのために汝らの僕たる事とを宣ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, '光、暗より照り出でよと宣ひし神は、イエス・キリストの顏にある神の榮光を知る知識を輝かしめんために、我らの心を照し給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, '我等この寶を土の器に有てり、これ優れて大なる能力の我等より出でずして、神より出づることの顯れんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'われら四方より患難を受くれども窮せず、爲ん方つくれども希望を失はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, '責めらるれども棄てられず、倒さるれども亡びず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, '常にイエスの死を我らの身に負ふ。これイエスの生命の我らの身にあらはれん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'それ我ら生ける者の常にイエスのため死に付さるるは、イエスの生命の我らの死ぬべき肉體にあらはれん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'さらば死は我等のうちに働き、生命は汝 等のうちに働くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, '録して『われ信ずるによりて語れり』とあるごとく、我等にも同じ信仰の靈あり、信ずるに因りて語るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'これ主イエスを甦へらせ給ひし者の我等をもイエスと共に甦へらせ、汝らと共に立たしめ給ふことを我ら知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, '凡ての事は汝らの益なり。これ多くの人によりて御惠の増し加はり、感謝いや増りて神の榮光の顯れん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'この故に我らは落膽せず、我らが外なる人は壞るれども、内なる人は日々に新なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'それ我らが受くる暫くの輕き患難は、極めて大なる永遠の重き光榮を得しむるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, '我らの顧みる所は見ゆるものにあらで見えぬものなればなり。見ゆるものは暫時にして、見えぬものは永遠に至るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, '我らは知る、我らの幕屋なる地上の家、壞るれば、神の賜ふ建造物、すなはち天にある、手にて造らぬ、永遠の家あることを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, '我等はその幕屋にありて歎き、天より賜ふ住所をこの上に著んことを切に望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, '之を著るときは裸にてある事なからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, '我等この幕屋にありて重荷を負へる如くに歎く、之を脱がんとにあらで、此の上に著んことを欲すればなり。これ死ぬべき者の生命に呑まれん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, '我らを此の事に適ふものとなし、その證として御靈を賜ひし者は神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'この故に我らは常に心 強し、かつ身に居るうちは主より離れ居るを知る、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '見ゆる所によらず、信仰によりて歩めばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, '斯く心 強し、願ふところは寧ろ身を離れて主と偕に居らんことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, '然れば身に居るも身を離るるも、ただ御心に適はんことを力む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, '我等はみな必ずキリストの審判の座の前にあらはれ、善にもあれ惡にもあれ、各人その身になしたる事に隨ひて報を受くべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, '斯く主の畏るべきを知るによりて人々に説き勸む。われら既に神に知られたり、亦なんぢらの良心にも知られたりと思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, '我等は再び己を汝らに薦むるにあらず、ただ我等をもて誇とする機を汝らに與へ、心によらず外貌によりて誇る人々に答ふることを得させんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, '我等もし心 狂へるならば、神の爲なり、心 慥ならば、汝らの爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'キリストの愛われらに迫れり。我ら思ふに、一人すべての人に代りて死にたれば、凡ての人すでに死にたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'その凡ての人に代りて死に給ひしは、生ける人の最早おのれの爲に生きず、己に代り死にて甦へり給ひし者のために、生きん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'されば今より後われ肉によりて人を知るまじ、曾て肉によりてキリストを知りしが、今より後は斯くの如くに知ることをせじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, '人もしキリストに在らば新に造られたる者なり、古きは既に過ぎ去り、視よ、新しくなりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'これらの事はみな神より出づ、神はキリストによりて我らを己と和がしめ、かつ和がしむる職を我らに授け給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, '即ち神はキリストに在りて世を己と和がしめ、その罪を之に負はせず、かつ和がしむる言を我らに委ね給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'されば我等はキリストの使者たり、恰も神の我等によりて汝らを勸め給ふがごとし。我等キリストに代りて願ふ、なんぢら神を和げ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, '神は罪を知り給はざりし者を我らの代に罪となし給へり、これ我らが彼に在りて神の義となるを得んためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, '我らは神とともに働く者なれば、神の恩惠を汝らが徒らに受けざらんことを更に勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(神いひ給ふ『われ惠の時に汝に聽き、救の日に汝を助けたり』と。視よ、今は惠のとき、視よ、今は救の日なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, '我等この職の謗られぬ爲に何事にも人を躓かせず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, '反つて凡ての事において神の役者のごとく己をあらはす、即ち患難にも、窮乏にも、苦難にも、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, '打たるるにも、獄に入るにも、騷擾にも、勞動にも、眠らぬにも、斷食にも、大なる忍耐を用ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'また廉潔と知識と寛容と仁慈と聖 靈と虚僞なき愛と、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, '眞の言と神の能力と左右に持ちたる義の武器とにより、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'また光榮と恥辱と惡名と美名とによりて表す。我らは人を惑す者の如くなれども眞、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, '人に知られぬ者の如くなれども人に知られ、死なんとする者の如くなれども、視よ、生ける者、懲さるる者の如くなれども殺されず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, '憂ふる者の如くなれども常に喜び、貧しき者の如くなれども多くの人を富ませ、何も有たぬ者の如くなれども凡ての物を有てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'コリント人よ、我らの口は汝らに向ひて開け、我らの心は廣くなれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, '汝らの狹くせらるるは我らに因るにあらず、反つて己が心に因るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, '汝らも心を廣くして我に報をせよ。(我わが子に對する如く言ふなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, '不 信者と軛を同じうすな、釣合はぬなり、義と不義と何の干與かあらん、光と暗と何の交際かあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'キリストとベリアルと何の調和かあらん、信者と不 信者と何の關係かあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, '神の宮と偶像と何の一致かあらん、我らは活ける神の宮なり、即ち神の言ひ給ひしが如し。曰く『われ彼らの中に住み、また歩まん。我かれらの神となり、彼 等わが民とならん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'この故に『主いひ給ふ、「汝 等かれらの中より出で、之を離れ、穢れたる者に觸るなかれ」と。「さらば我なんぢらを受け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'われ汝らの父となり、汝 等わが息子むすめとならん」と、全能の主いひ給ふ』とあるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'されば愛する者よ、我らかかる約束を得たれば、肉と靈との汚穢より全く己を潔め、神を畏れてその清潔を成就すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, '我らを受け容れよ、われら誰にも不義をなしし事なく、誰をも害ひし事なく、誰をも掠めし事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'わが斯く言ふは、汝らを咎めんとにあらず、そは我が既に言へる如く、汝らは我らの心にありて、共に死に共に生くればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, '我なんぢらを信ずること大なり、また汝 等をもて誇とすること大なり、我は慰安にみち、凡ての患難の中にも喜悦あふるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'マケドニヤに到りしとき、我らの身はなほ聊かも平安を得ずして、樣々の患難に遭ひ、外には分爭、内には恐懼ありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, '然れど哀なる者を慰むる神は、テトスの來るによりて我らを慰め給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, '唯その來るに因りてのみならず、彼が汝らによりて得たる慰安をもて慰め給へり。即ち汝らの我を慕ふこと、歎くこと、我に對して熱心なることを我らに告ぐるによりて、我ますます喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'われ書をもて汝らを憂ひしめたれども悔いず、その書の汝らを暫く憂ひしめしを見て、前には悔いたれども今は喜ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'わが喜ぶは汝らの憂ひしが故にあらず、憂ひて悔改に至りし故なり。汝らは神に從ひて憂ひたれば、我等より聊かも損を受けざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'それ神にしたがふ憂は、悔なきの救を得るの悔改を生じ、世の憂は死を生ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, '視よ、汝らが神に從ひて憂ひしことは、如何ばかりの奮勵・辯明・憤激・恐懼・愛慕・熱心・罪を責むる心などを汝らの中に生じたりしかを。汝 等かの事に就きては全く潔きことを表せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'されば前に書を汝らに書き贈りしも、不義をなしたる人の爲にあらず、また不義を受けたり人の爲にあらず、我らに對する汝らの奮勵の、神の前にて汝らに顯れん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'この故に我らは慰安を得たり。慰安を得たる上にテトスの喜悦によりて更に喜べり。そは彼の心なんぢら一同によりて安んぜられたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'われ曩に彼の前に汝らに就きて誇りたれど恥づることなし、我らが汝らに語りし事のみな誠實なりし如く、テトスの前に誇りし事もまた誠實となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, '彼は汝 等みな從順にして畏れ戰き、己を迎へしことを思ひ出して、心を汝らに寄すること増々 深し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'われ凡ての事に汝らに就きて心 強きを喜ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, '兄弟よ、我らマケドニヤの諸 教會に賜ひたる神の恩惠を汝らに知らす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, '即ち患難の大なる試練のうちに彼らの喜悦あふれ、又その甚だしき貧窮は吝みなく施す富の溢るるに至れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'われ證す、彼らは聖徒に事ふることに與る惠を切に我らに請ひ求め、みづから進みて、力に應じ、否これに過ぎて施濟をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'われ證す、彼らは聖徒に事ふることに與る惠を切に我らに請ひ求め、みづから進みて、力に應じ、否これに過ぎて施濟をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, '我らの望のほかに先づ己を主にささげ、神の御意によりて我らにも身を委ねたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'されば我らはテトスが前に此の慈惠のことを汝らの中に始めたれば、又これを成就せんことを勸めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, '汝 等もろもろの事、すなはち信仰に、言に、知識に、凡ての奮勵に、また我らに對する愛に富めるごとく、此の慈惠にも富むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'われ斯く言ふは汝らに命ずるにあらず、ただ他の人の奮勵によりて、汝らの愛の眞實を試みん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, '汝らは我らの主イエス・キリストの恩惠を知る。即ち富める者にて在したれど、汝 等のために貧しき者となり給へり。これ汝らが彼の貧窮によりて富める者とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, '施濟のことに就きて我ただ意見を述ぶ、これは汝らの益なり。汝らは此の事をただに一年 前より人に先だちて行ひしのみならず、又これを願い始めし事なれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, '今これを成し遂げよ、汝らが心より願ひしごとく、所有に應じて成し遂げよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, '人もし志望あらば、其の有たぬ所に由るにあらず、其の有つ所に由りて嘉納せらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'これ他の人を安くして汝らを苦しめんとにあらず、均しくせんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'すなはち今なんぢらの餘るところは彼らの足らざるを補ひ、後また彼らの餘る所は汝らの足らざるを補ひて、均しくなるに至らんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, '録して『多く集めし者にも餘る所なく、少く集めし者にも足らざる所なかりき』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, '汝らに對する同じ熱心をテトスの心にも賜へる神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, '彼はただに勸を容れしのみならず、甚だ熱心にして、自ら進んで汝らに往くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, '我等また彼とともに一人の兄弟を遣す。この人は福音をもて諸 教會のうちに譽を得たる上に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, '主の榮光と我らの志望とを顯さんがために、掌どれる此の慈惠に就きて、諸 教會より我らの道伴として選ばれたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, '彼を遣すは、此の大なる醵金を掌どるに、人に咎めらるる事を避けんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'そは主の前のみならず、人の前にも善からんことを慮ぱかりてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'また一人の兄弟を彼らと共につかはす、我らは多くの事につきて屡次かれの熱心なるを認めたり。而して今は彼が汝らを深く信ずるに因りて、その熱心の更に加はるを認む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'テトスのことを言へば、我が友なり、汝らに對して我が同勞者なり。この兄弟たちの事をいへば、彼らは諸 教會の使なり、キリストの榮光なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'されば汝らの愛と我らが汝らに就きて誇れる事との證を、諸 教會の前にて彼らに顯せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, '聖徒に施すことに就きては汝らに書きおくるに及ばず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, '我なんぢらの志望あるを知ればなり。その志望につき汝らの事をマケドニヤ人に誇りて、アカヤは既に一年 前に準備をなせりと云へり。かくて汝らの熱心は多くの人を勵ましたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'されどわれ兄弟たちを遣すは、我が言ひしごとく汝らに準備をなさしめ、之につきて我らの誇りし事の空しくならざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'もしマケドニヤ人われと共に來りて汝らの準備なきを見ば、汝らは言ふに及ばず、我らも確信せしによりて恐らくは恥を受けん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'この故に兄弟たちを勸めて、先づ汝らに往かしめ、曩に汝らが約束したる慈惠を、吝むが如くせずして、惠む心よりせん爲に預じめ調へしむるは、必要のことと思へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'それ少く播く者は少く刈り、多く播く者は多く刈るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'おのおの吝むことなく、強ひてすることなく、その心に定めし如くせよ。神は喜びて與ふる人を愛し給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, '神は汝 等をして常に凡ての物に足らざることなく、凡ての善き業に溢れしめんために、凡ての恩惠を溢るるばかり與ふることを得給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, '録して『彼は散して貧しき者に與へたり。その正義は永遠に存らん』とある如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, '播く人に種と食するパンとを與ふる者は、汝らにも種をあたへ、且これを殖し、また汝らの義の果を増し給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, '汝らは一切に富みて吝みなく施すことを得、かくて我らの事により、人々 神に感謝するに至るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, '此の施濟の務は、ただに聖徒の窮乏を補ふのみならず、充ち溢れて神に對する感謝を多からしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, '即ち彼らは此の務を證據として、汝らがキリストの福音に對する言明に順ふことと、彼らにも凡ての人にも吝みなく施すこととに就きて、神に榮光を歸し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'かつ神の汝らに給ひし優れたる恩惠により、汝らを慕ひて汝 等のために祈らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, '言ひ盡しがたき神の賜物につきて感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, '汝らに對し面前にては謙だり、離れゐては勇ましき我パウロ、自らキリストの柔和と寛容とをもて汝らに勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, '我らを肉に從ひて歩むごとく思ふ者あれば、斯かる者に對しては雄々しくせんと思へど、願ふ所は我が汝らに逢ふとき斯く勇ましくせざらん事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, '我らは肉にありて歩めども、肉に從ひて戰はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'それ我らの戰爭の武器は肉に屬するにあらず、神の前には城砦を破るほどの能力あり、我等はもろもろの論説を破り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, '神の示教に逆ひて建てたる凡ての櫓を毀ち、凡ての念を虜にしてキリストに服はしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, '且なんぢらの從順の全くならん時、すべての不 從順を罰せんと覺悟せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, '汝らは外貌のみを見る、若し人みづからキリストに屬する者と信ぜば、己がキリストに屬する如く、我らも亦キリストに屬する者なることを更に考ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, '假令われ汝らを破る爲ならずして建つる爲に、主が我らに賜ひたる權威につきて誇ること稍 過ぐとも恥とはならじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'われ書をもて汝らを嚇すと思はざれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, '彼らは言ふ『その書は重くかつ強し、その逢ふときの容貌は弱く、言は鄙し』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, '斯くのごとき人は思ふべし。我らが離れをる時おくる書の言のごとく、逢ふときの行爲も亦 然るを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, '我らは己を譽むる人と敢へて竝び、また較ぶる事をせず、彼らは己によりて己を度り、己をもて己に較ぶれば智なき者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, '我らは範圍を踰えて誇らず、神の我らに分ち賜ひたる範圍にしたがひて誇らん。その範圍は汝らに及べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, '汝らに及ばぬ者のごとく範圍を踰えて身を延すに非ず、キリストの福音を傳へて汝らにまで到れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, '我らは己が範圍を踰えて他の人の勞を誇らず、唯なんぢらの信仰の彌増すにより、我らの範圍に循ひて汝らのうちに更に大ならんことを望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'これ他の人の範圍に既に備りたるものを誇らず、汝らを踰えて外の處に福音を宣傳へん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, '誇る者は主によりて誇るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'そは是とせらるるは己を譽むる者にあらず、主の譽め給ふ者なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, '願はくは汝 等わが少しの愚を忍ばんことを。請ふ我を忍べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'われ神の熱心をもて汝らを慕ふ、われ汝らを潔き處女として一人の夫なるキリストに献げんとて、之に許嫁したればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'されど我が恐るるは、蛇の惡巧によりてエバの惑されし如く、汝らの心 害はれてキリストに對する眞心と貞操とを失はん事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'もし人きたりて我らの未だ宣べざる他のイエスを宣ぶる時、また汝らが未だ受けざる他の靈を受け、未だ受け容れざる他の福音を受くるときは、汝ら能く之を忍ばん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, '我は何事にもかの大使徒たちに劣らずと思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'われ言に拙けれども知識には然らず、凡ての事にて全く之を汝らに顯せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'われ汝らを高うせんために自己を卑うし、價なくして神の福音を傳へたるは罪なりや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, '我は他の教會より奪ひ取り、その俸給をもて汝らに事へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, '又なんぢらの中に在りて乏しかりしとき、誰をも煩はさず、マケドニヤより來りし兄弟たち我が窮乏を補へり。斯く凡ての事に汝らを煩はすまじと愼みたるが、此の後もなほ愼まん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, '我に在るキリストの誠實によりて言ふ、我この誇をアカヤの地方にて阻まるる事あらじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'これ何 故ぞ、汝らを愛せぬに因るか、神は知りたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, '我わが行ふ所をなほ行はん、これ機會をうかがふ者の機會を斷ち、彼 等をしてその誇る所につき我らの如くならしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'かくの如きは僞 使徒また詭計の勞動人にして、己をキリストの使徒に扮へる者どもなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'これ珍しき事にあらず、サタンも己を光の御使に扮へば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'その役者らが義の役者のごとく扮ふは大事にはあらず、彼 等の終局はその業に適ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'われ復いはん、誰も我を愚と思ふな。もし然おもふとも、少しく誇る機を我にも得させん爲に、愚なる者として受け容れよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, '今いふ所は主によりて言ふにあらず、愚なる者として大膽に誇りて言ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, '多くの人、肉によりて誇れば、我も誇るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, '汝らは智き者なれば喜びて愚なる者を忍ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, '人もし汝らを奴隷とすとも、食ひ盡すとも、掠めとるとも、驕るとも、顏を打つとも、汝らは之を忍ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'われ恥ぢて言ふ、我らは弱き者の如くなりき。されど人の雄々しき所は我もまた雄々し、われ愚にも斯く言ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, '彼らヘブル人なるか、我も然り、彼らイスラエル人なるか、我も然り、彼らアブラハムの裔なるか、我も然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, '彼らキリストの役者なるか、われ狂へる如く言ふ、我はなほ勝れり。わが勞は更におほく、獄に入れられしこと更に多く、鞭うたれしこと更に夥だしく、死に瀕みたりしこと屡次なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'ユダヤ人より四十に一つ足らぬ鞭を受けしこと五度、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, '笞にて打たれしこと三たび、石にて打たれしこと一たび、破船に遭ひしこと三度にして、一晝夜 海にありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'しばしば旅行して河の難、盜賊の難、同族の難、異邦人の難、市中の難、荒野の難、海上の難、僞 兄弟の難にあひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, '勞し、苦しみ、しばしば眠らず、飢ゑ渇き、しばしば斷食し、凍え、裸なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'ここに擧げざる事もあるに、なほ日々われに迫る諸 教會の心勞あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, '誰か弱りて我 弱らざらんや、誰か躓きて我 燃えざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'もし誇るべくは、我が弱き所につきて誇らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, '永遠に讃むべき者、すなはち主イエスの神また父は、我が僞らざるを知り給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'ダマスコにてアレタ王の下にある總督、われを捕へんとてダマスコ人の町を守りたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, '我は籠にて窓より石垣傳ひに縋り下されて其の手を脱れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'わが誇るは益なしと雖も止むを得ざるなり、茲に主の顯示と默示とに及ばん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, '我はキリストにある一人の人を知る。この人、十四年 前に第三の天にまで取去られたり(肉體にてか、われ知らず、肉體を離れてか、われ知らず、神しり給ふ)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'われ斯くのごとき人を知る(肉體にてか、肉體の外にてか、われ知らず、神しり給ふ)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'かれパラダイスに取去られて、言ひ得ざる言、人の語るまじき言を聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'われ斯くのごとき人のために誇らん、されど我が爲には弱き事のほか誇るまじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'もし自ら誇るとも我が言ふところ誠實なれば、愚なる者とならじ。されど之を罷めん。恐らくは人の我を見われに聞くところに過ぎて、我を思ふことあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, '我は我が蒙りたる默示の鴻大なるによりて高ぶることのなからん爲に、肉體に一つの刺を與へらる、即ち高ぶることなからん爲に我を撃つサタンの使なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'われ之がために三度まで之を去らしめ給はんことを主に求めたるに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, '言ひたまふ『わが恩惠なんぢに足れり、わが能力は弱きうちに全うせらるればなり』さればキリストの能力の我を庇はんために、寧ろ大に喜びて我が微弱を誇らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'この故に我はキリストの爲に微弱・恥辱・艱難・迫害・苦難に遭ふことを喜ぶ、そは我よわき時に強ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'われ汝らに強ひられて愚になれり、我は汝らに譽めらるべかりしなり。我は數ふるに足らぬ者なれども、何事にもかの大使徒たちに劣らざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, '我は徴と不思議と能力ある業とを行ひ、大なる忍耐を用ひて汝 等のうちに使徒の徴をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'なんぢら他の教會に何の劣る所かある、唯わが汝らを煩はさざりし事のみならずや、此の不義は請ふ我に恕せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, '視よ、茲に三度なんぢらに到らんとして準備したれど、尚なんぢらを煩はすまじ。我は汝らの所有を求めず、ただ汝らを求む。それ子は親のために貯ふべきにあらず、親は子のために貯ふべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, '我は大に喜びて汝らの靈魂のために物を費し、また身をも費さん。我なんぢらを多く愛するによりて、汝ら我を少く愛するか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, '或 人いはん、我なんぢらを煩はさざりしも、狡猾にして詭計をもて取りしなりと。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, '然れど我なんぢらに遣しし者のうちの誰によりて汝らを掠めしや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, '我テトスを勸めて汝らに遣し、これと共にかの兄弟を遣せり、テトスは汝らを掠めしや。我らは同じ御靈によりて歩み、同じ足跡を蹈みしにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, '汝らは夙くより我等なんぢらに對して辯明すと思ひしならん。されど我らはキリストに在りて神の前にて語る。愛する者よ、これ皆なんぢらの徳を建てん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'わが到りて汝らを見ん時、わが望の如くならず、汝らが我を見んとき、亦なんぢらの望の如くならざらんことを恐れ、かつ分爭・嫉妬・憤恚・徒黨・誹謗・讒言・驕傲・騷亂などの有らんことを恐る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'また重ねて到らん時、わが神われを汝 等のまへにて辱しめ、且おほくの人の、前に罪を犯して行ひし不潔と姦淫と好色とを悔改めざるを悲しましめ給ふことあらん乎と恐る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, '今われ三度なんぢらに到らんとす、二 三の證人の口によりて凡てのこと慥めらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'われ既に告げたれど、今 離れをりて、二度なんぢらに逢ひし時のごとく、前に罪を犯したる者とその他の凡ての人々とに預じめ告ぐ、われ復いたらば決して宥さじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, '汝らはキリストの我にありて語りたまふ證據を求むればなり。キリストは汝らに對ひて弱からず、汝 等のうちに強し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, '微弱によりて十字架に釘けられ給ひたれど、神の能力によりて生き給へばなり。我らもキリストに在りて弱き者なれど、汝らに向ふ神の能力によりて彼と共に生きん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'なんぢら信仰に居るや否や、みづから試み自ら驗しみよ。汝らみづから知らざらんや、若し棄てらるる者ならずば、イエス・キリストの汝らの中に在す事を、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, '我は我らの棄てらるる者ならぬを汝らの知らんことを望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, '我らは汝らの少しにても惡を行はざらんことを神に祈る。これ我らの是とせらるるを顯さん爲にあらず、よし我らは棄てらるる者の如くなるとも、汝らの善を行はん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, '我らは眞理に逆ひて能力なく、眞理のためには能力あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'われら弱くして汝らの強きことを喜ぶ、また之に就きて祈るは、汝らの全くならん事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'われ離れ居りて此 等のことを書き贈るは、汝らに逢ふとき、主の破る爲ならずして建つる爲に我に賜ひたる權威に隨ひて嚴しくせざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, '終に言はん、兄弟よ、汝ら喜べ、全くなれ、慰安を受けよ、心を一つにせよ、睦み親しめ、然らば愛と平和との神なんぢらと偕に在さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, '潔き接吻をもて相 互に安否を問へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, '凡ての聖徒なんぢらに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '願はくは主イエス・キリストの恩惠・神の愛・聖 靈の交感、なんぢら凡ての者と偕にあらんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, '人よりに非ず、人に由るにも非ず、イエス・キリスト及び之を死人の中より甦へらせ給ひし父なる神に由りて使徒となれるパウロ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, '及び我と偕にある凡ての兄弟、書をガラテヤの諸 教會に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, '願はくは、我らの父なる神および主イエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, '主は我らの父なる神の御意に隨ひて、我らを今の惡しき世より救ひ出さんとて、己が身を我らの罪のために與へたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, '願はくは榮光、世々 限りなく神にあらん事を、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, '我は汝らが斯くも速かにキリストの恩惠をもて召し給ひし者より離れて、異なる福音に移りゆくを怪しむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, '此は福音と言ふべき者にあらず、ただ或 人々が汝らを擾してキリストの福音を變へんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'されど我等にもせよ、天よりの御使にもせよ、我らの曾て宣傳へたる所に背きたる福音を汝らに宣傳ふる者あらば詛はるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'われら前に言ひし如く今また言はん、汝らの受けし所に背きたる福音を宣傳ふる者あらば詛はるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, '我いま人に喜ばれんとするか、或は神に喜ばれんとするか、抑もまた人を喜ばせんことを求むるか。もし我なほ人を喜ばせをらば、キリストの僕にあらじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, '兄弟よ、われ汝らに示す、わが傳へたる福音は、人に由れるものにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, '我は人より之を受けず、また教へられず、唯イエス・キリストの默示に由れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, '我がユダヤ教に於ける曩の日の擧動は、なんぢら既に聞けり、即ち烈しく神の教會を責め、かつ暴したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, '又わが國人のうち、我と同じ年輩なる多くの者にも勝りてユダヤ教に進み、わが先祖たちの言傳に對して甚だ熱心なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'されど母の胎を出でしより我を選び別ち、その恩惠をもて召し給へる者');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, '御子を我が内に顯して其の福音を異邦人に宣傳へしむるを可しとし給へる時、われ直ちに血肉と謀らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, '我より前に使徒となりし人々に逢はんとてエルサレムにも上らず、アラビヤに出で往きて遂にまたダマスコに返れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'その後 三年を歴て、ケパを尋ねんとエルサレムに上り、十 五 日の間かれと偕に留りしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, '主の兄弟ヤコブのほか孰の使徒にも逢はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, '(茲に書きおくる事は、視よ、神の前にて僞らざるなり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'その後シリヤ、キリキヤの地方に往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'キリストにあるユダヤの諸 教會は我が顏を知らざりしかど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'ただ人々の『われらを前に責めし者、曾て暴したる信仰の道を今は傳ふ』といふを聞き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'わが事によりて神を崇めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'その後 十四年を歴て、バルナバと共にテトスをも連れて、復エルサレムに上れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, '我が上りしは默示に因りてなり。かくて異邦人の中に宣ぶる福音を彼らに告げ、また名ある者どもに私に告げたり、これは我が走ること、又すでに走りしことの空しからざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, '而して我と偕なるギリシヤ人テトスすら割禮を強ひられざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'これ私に入りたる僞 兄弟あるに因りてなり。彼らの忍び入りたるは、我らがキリスト・イエスに在りて有てる自由を窺ひ、且われらを奴隷とせん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, '然れど福音の眞理の汝らの中に留らんために、我ら一 時も彼らに讓り從はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, '然るに、かの名ある者どもより――彼らは如何なる人なるにもせよ、我には關係なし、神は人の外面を取り給はず――實にかの名ある者どもは我に何をも加へず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, '反つてペテロが割禮ある者に對する福音を委ねられたる如く、我が割禮なき者に對する福音を委ねられたるを認め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(ペテロに能力を與へて割禮ある者の使徒となし給ひし者は、我にも異邦人のために能力を與へ給へり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'また我に賜はりたる恩惠をさとりて、柱と思はるるヤコブ、ケパ、ヨハネは、交誼の印として我とバルナバとに握手せり。これは我らが異邦人にゆき、彼らが割禮ある者に往かん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, '唯その願ふところは我らが貧しき者を顧みんことなり、我も固より此の事を勵みて行へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'されどケパがアンテオケに來りしとき、責むべき事のありしをもて面前これと諍ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'その故はある人々のヤコブの許より來るまでは、かれ異邦人と共に食しゐたるに、かの人々の來りてよりは、割禮ある者どもを恐れ、退きて異邦人と別れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, '他のユダヤ人も彼とともに僞行をなし、バルナバまでもその僞行に誘はれゆけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'されど我かれらが福音の眞理に循ひて正しく歩まざるを見て、會衆の前にてケパに言ふ『なんぢユダヤ人なるにユダヤ人の如くせず、異邦人のごとく生活せば、何ぞ強ひて異邦人をユダヤ人の如くならしめんとするか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, '我らは生來のユダヤ人にして、罪人なる異邦人にあらざれども、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, '人の義とせらるるは律法の行爲に由らず、唯キリスト・イエスを信ずる信仰に由るを知りて、キリスト・イエスを信じたり。これ律法の行爲に由らず、キリストを信ずる信仰によりて義とせられん爲なり。律法の行爲によりては義とせらるる者 一人だになし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, '若しキリストに在りて義とせららんことを求めて、なほ罪人と認められなば、キリストは罪の役者なるか、決して然らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, '我もし前に毀ちしものを再び建てなば、己みづから犯罪者たるを表す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, '我は神に生きんために、律法によりて律法に死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, '我キリストと偕に十字架につけられたり。最早われ生くるにあらず、キリスト我が内に在りて生くるなり。今われ肉體に在りて生くるは、我を愛して我がために己が身を捨て給ひし神の子を信ずるに由りて生くるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, '我は神の恩惠を空しくせず、もし義とせらるること律法に由らば、キリストの死に給へるは徒然なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, '愚なる哉、ガラテヤ人よ、十字架につけられ給ひしままなるイエス・キリスト、汝らの眼前に顯されたるに、誰が汝らを誑かししぞ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, '我は汝 等より唯この事を聞かんと欲す。汝らが御靈を受けしは律法の行爲に由るか、聽きて信じたるに由るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, '汝らは斯くも愚なるか、御靈によりて始りしに、今 肉によりて全うせらるるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, '斯程まで多くの苦難を受けしことは徒然なるか、徒然にはあるまじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, '然らば汝らに御靈を賜ひて汝らの中に能力ある業を行ひ給へるは、律法の行爲に由るか、聽きて信ずるに由るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, '録して『アブラハム神を信じ、その信仰を義とせられたり』とあるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'されば知れ、信仰に由る者は是アブラハムの子なるを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, '聖書は神が異邦人を信仰に由りて義とし給ふことを知りて、預じめ福音をアブラハムに傳へて言ふ『なんぢに由りてもろもろの國人は祝福せられん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'この故に信仰による者は、信仰ありしアブラハムと共に祝福せらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'されど凡て律法の行爲による者は詛の下にあり。録して『律法の書に記されたる凡ての事を常に行はぬ者はみな詛はるべし』とあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, '律法に由りて神の前に義とせらるる事なきは明かなり『義人は信仰によりて生くべし』とあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, '律法は信仰に由るにあらず、反つて『律法を行ふ者は之に由りて生くべし』と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'キリストは我等のために詛はるる者となりて、律法の詛より我らを贖ひ出し給へり。録して『木に懸けらるる者は凡て詛はるべし』と云へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'これアブラハムの受けたる祝福の、イエス・キリストによりて異邦人におよび、且われらが信仰に由りて約束の御靈を受けん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, '兄弟よ、われ人の事を藉りて言はん、人の契約すら既に定むれば、之を廢しまた加ふる者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'かの約束はアブラハムと其の裔とに與へ給ひし者なり。多くの者を指すごとく『裔々に』とは云はず、一人を指すごとく『なんぢの裔に』と云へり、これ即ちキリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, '然れば我いはん、神の預じめ定め給ひし契約は、その後 四百三十年を歴て起りし律法に廢せらるることなく、その約束も空しくせらるる事なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'もし嗣業を受くること律法に由らば、もはや約束には由らず、然るに神は約束に由りて之をアブラハムに賜ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, '然れば律法は何のためぞ。これ罪の爲に加へ給ひしものにて、御使たちを經て中保の手によりて立てられ、約束を與へられたる裔の來らん時にまで及ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, '(中保は一方のみの者にあらず、然れど神は唯一に在せり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'さらば律法は神の約束に悖るか、決して然らず。もし人を生かすべき律法を與へられたらんには、實に義とせらるるは律法に由りしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'されど聖書は凡ての者を罪の下に閉ぢ籠めたり。これ信ずる者のイエス・キリストに對する信仰に由れる約束を與へられん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, '信仰の出で來らぬ前は、われら律法の下に守られて、後に顯れんとする信仰の時まで閉ぢ籠められたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'かく信仰によりて我らの義とせられん爲に、律法は我らをキリストに導く守役となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'されど信仰の出で來りし後は、我等もはや守役の下に居らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, '汝らは信仰によりキリスト・イエスに在りて、みな神の子たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, '凡そバプテスマに由りてキリストに合ひし汝らは、キリストを衣たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, '今はユダヤ人もギリシヤ人もなく、奴隷も自主もなく、男も女もなし、汝らは皆キリスト・イエスに在りて一體なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, '汝 等もしキリストのものならば、アブラハムの裔にして約束に循へる世嗣たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'われ言ふ、世嗣は全業の主なれども、成人とならぬ間は僕と異なることなく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, '父の定めし時の至るまでは後見者と家令との下にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, '斯くのごとく我らも成人とならぬほどは、世の小學の下にありて僕たりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'されど時 滿つるに及びては、神その御子を遣し、これを女より生れしめ、律法の下に生れしめ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'これ律法の下にある者をあがなひ、我等をして子たることを得しめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'かく汝ら神の子たる故に、神は御子の御靈を我らの心に遣して『アバ、父』と呼ばしめ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'されば最早なんぢは僕にあらず、子たるなり、既に子たらば亦 神に由りて世嗣たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'されど汝ら神を知らざりし時は、その實 神にあらざる神々に事へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, '今は神を知り、むしろ神に知られたるに、何ぞ復かの弱くして賤しき小學に還りて、再びその僕たらんとするか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, '汝らは日と月と季節と年とを守る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, '我は汝らの爲に働きし事の或は無 益にならんことを恐る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, '兄弟よ、我なんぢらに請ふ、われ汝 等のごとく成りたれば、汝ら我がごとく成れ。汝ら何事にも我を害ひしことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'わが初め汝らに福音を傳へしは、肉體の弱かりし故なるを汝ら知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'わが肉體に汝らの試錬となる者ありたれど汝ら之を卑しめず、又きらはず、反つて我を神の使の如く、キリスト・イエスの如く迎へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, '汝らの其の時の幸福はいま何處に在るか。我なんぢらに就きて證す、もし爲し得べくば己が目を抉りて我に與へんとまで思ひしを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, '然るに我なんぢらに眞を言ふによりて仇となりたるか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'かの人々の汝らに熱心なるは善き心にあらず、汝らを我らより離して己らに熱心ならしめんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, '善き心より熱心に慕はるるは、啻に我が汝らと偕にをる時のみならず、何時にても宜しき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'わが幼兒よ、汝らの衷にキリストの形 成るまでは、我ふたたび産の苦痛をなす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, '今なんぢらに到りて我が聲を易へんことを願ふ、汝らに就きて惑へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, '律法の下にあらんと願ふ者よ、我にいへ、汝ら律法をきかぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, '即ちアブラハムに子 二人あり、一人は婢女より、一人は自主の女より生れたりと録されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, '婢女よりの子は肉によりて生れ、自主の女よりの子は約束による。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'この中に譬あり、二人の女は二つの契約なり、その一つはシナイ山より出でて、奴隷たる子を生む、これハガルなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'このハガルはアラビヤに在るシナイ山にして今のエルサレムに當る。エルサレムはその子らとともに奴隷たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'されど上なるエルサレムは、自主にして我らの母なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, '録していふ『石女にして産まぬものよ、喜べ。産の苦痛せぬ者よ、聲をあげて呼はれ。獨住の女の子は多し、夫ある者の子よりも多し』とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, '兄弟よ、なんぢらはイサクのごとく約束の子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, '然るに其の時、肉によりて生れし者 御靈によりて生れし者を責めしごとく、今なほ然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'されど聖書は何と云へるか『婢女とその子とを逐ひいだせ、婢女の子は自主の女の子と共に業を嗣ぐべからず』とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'されば兄弟よ、われらは婢女の子ならず、自主の女の子なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'キリストは自由を得させん爲に我らを釋き放ちたまへり。されば堅く立ちて再び奴隷の軛に繋がるな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, '視よ、我パウロ汝らに言ふ、もし割禮を受けば、キリストは汝らに益なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, '又さらに凡て割禮を受くる人に證す、かれは律法の全體を行ふべき負債あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, '律法に由りて義とせられんと思ふ汝らは、キリストより離れたり、恩惠より墮ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, '我らは御靈により、信仰によりて希望をいだき、義とせらるることを待てるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'キリスト・イエスに在りては、割禮を受くるも割禮を受けぬも益なく、ただ愛に由りてはたらく信仰のみ益あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'なんぢら前には善く走りたるに、誰が汝らの眞理に從ふを阻みしか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'かかる勸は汝らを召したまふ者より出づるにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, '少しのパン種は粉の團塊をみな膨れしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'われ汝らに就きては、その聊かも異念を懷かぬことを主によりて信ず。されど汝らを擾す者は、誰にもあれ審判を受けん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, '兄弟よ、我もし今も割禮を宣傳へば、何ぞなほ迫害せられんや。もし然せば十字架の顛躓も止みしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, '願はくは汝らを亂す者どもの自己を不具にせんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, '兄弟よ、汝らの召されたるは自由を與へられん爲なり。ただ其の自由を肉に從ふ機會となさず、反つて愛をもて互に事へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'それ律法の全體は『おのれの如くなんぢの隣を愛すべし』との一言にて全うせらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, '心せよ、若し互に咬み食はば相 共に亡されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, '我いふ、御靈によりて歩め、さらば肉の慾を遂げざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, '肉の望むところは御靈にさからひ、御靈の望むところは肉にさからひて互に相 戻ればなり。これ汝らの欲する所をなし得ざらしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, '汝 等もし御靈に導かれなば、律法の下にあらじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'それ肉の行爲はあらはなり。即ち淫行・汚穢・好色・');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, '偶像 崇拜・呪術・怨恨・紛爭・嫉妬・憤恚・徒黨・分離・異端・');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, '猜忌・醉酒・宴樂などの如し。我すでに警めたるごとく、今また警む。斯かることを行ふ者は神の國を嗣ぐことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'されど御靈の果は愛・喜悦・平和・寛容・仁慈・善良・忠信・');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, '柔和・節制なり。斯かるものを禁ずる律法はあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'キリスト・イエスに屬する者は、肉とともに其の情と慾とを十字架につけたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'もし我ら御靈に由りて生きなば、御靈に由りて歩むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, '互に挑み互に妬みて、虚しき譽を求むることを爲な。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, '兄弟よ、もし人の罪を認むることあらば、御靈に感じたる者、柔和なる心をもて之を正すべし、且おのおの自ら省みよ、恐らくは己も誘はるる事あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'なんぢら互に重を負へ、而してキリストの律法を全うせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, '人もし有ること無くして自ら有りとせば、是みづから欺くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, '各自おのが行爲を驗し見よ、さらば誇るところは他にあらで、ただ己にあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, '各自おのが荷を負ふべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, '御言を教へらるる人は、教ふる人と凡ての善き物を共にせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, '自ら欺くな、神は侮るべき者にあらず、人の播く所は、その刈る所とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, '己が肉のために播く者は肉によりて滅亡を刈りとり、御靈のために播く者は御靈によりて永遠の生命を刈りとらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'われら善をなすに倦まざれ、もし撓まずば、時いたりて刈り取るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'この故に機に隨ひて、凡ての人、殊に信仰の家族に善をおこなへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, '視よ、われ手づから如何に大なる文字にて汝らに書き贈るかを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, '凡そ肉において美しき外觀をなさんと欲する者は、汝らに割禮を強ふ。これ唯キリストの十字架の故によりて責められざらん爲のみ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'そは割禮をうくる者すら自ら律法を守らず、而も汝らに割禮をうけしめんと欲するは、汝らの肉につきて誇らんが爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'されど我には、我らの主イエス・キリストの十字架のほかに誇る所あらざれ。之によりて世は我に對して十字架につけられたり、我が世に對するも亦 然り。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'それ割禮を受くるも受けぬも、共に數ふるに足らず、ただ貴きは新に造らるる事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, '此の法に循ひて歩む凡ての者の上に、神のイスラエルの上に、平安と憐憫とあれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, '今よりのち誰も我を煩はすな、我はイエスの印を身に佩びたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, '兄弟よ、願はくは我らの主イエス・キリストの恩惠、なんぢらの靈とともに在らんことを、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, '神の御意によりてキリスト・イエスの使徒となれるパウロ、書をエペソに居る聖徒、キリストに在りて忠實なる者に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, '願はくは我らの父なる神および主イエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, '讃むべきかな、我らの主イエス・キリストの父なる神、かれはキリストに由りて靈のもろもろの祝福をもて天の處にて我らを祝し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, '御前にて潔く瑕なからしめん爲に、世の創の前より我等をキリストの中に選び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, '御意のままにイエス・キリストに由り愛をもて己が子となさんことを定め給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, '是その愛しみ給ふ者によりて我らに賜ひたる恩惠の榮光に譽あらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, '我らは彼にありて恩惠の富に隨ひ、その血に頼りて贖罪、すなはち罪の赦を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, '神は我らに諸般の知慧と聰明とを與へてその恩惠を充しめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, '御意の奧義を御意のままに示し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, '即ち時 滿ちて經綸にしたがひ、天に在るもの地にあるものを、悉とくキリストに在りて一つに歸せしめ給ふ。これ自ら定め給ひし所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, '我らは、凡ての事を御意の思慮のままに行ひたまふ者の御旨によりて預じめ定められ、キリストに在りて神の産業とせられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'これ夙くよりキリストに希望を置きし我らが、神の榮光の譽とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, '汝 等もキリストに在りて、眞の言すなはち汝らの救の福音をきき、彼を信じて約束の聖 靈にて印せられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'これは我らが受くべき嗣業の保證にして、神に屬けるものの贖はれ、かつ神の榮光に譽あらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'この故に我も汝らが主イエスに對する信仰と凡ての聖徒に對する愛とを聞きて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, '絶えず汝らのために感謝し、わが祈のうちに汝らを憶え、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, '我らの主イエス・キリストの神、榮光の父、なんぢらに智慧と默示との靈を與へて、神を知らしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, '汝らの心の眼を明かにし、神の召にかかはる望と、聖徒にある神の嗣業の榮光の富と、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, '神の大能の勢威の活動によりて信ずる我らに對する能力の極めて大なるとを知らしめ給はんことを願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, '神はその大能をキリストのうちに働かせて、之を死人の中より甦へらせ、天の所にて己の右に坐せしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'もろもろの政治・權威・能力・支配、また啻に此の世のみならず、來らんとする世にも稱ふる凡ての名の上に置き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, '萬の物をその足の下に服はせ、彼を萬の物の上に首として教會に與へ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'この教會は彼の體にして、萬の物をもて萬の物に滿し給ふ者の滿つる所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, '汝ら前には咎と罪とによりて死にたる者にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'この世の習慣に從ひ、空中の權を執る宰、すなはち不 從順の子らの中に今なほ働く靈の宰にしたがひて歩めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, '我等もみな前には彼らの中にをり、肉の慾に從ひて日をおくり、肉と心との欲する隨をなし、他の者のごとく生れながら怒の子なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'されど神は憐憫に富み給ふが故に、我らを愛する大なる愛をもて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, '咎によりて死にたる我等をすら、キリスト・イエスに由りてキリストと共に活し、(汝らの救はれしは恩惠によれり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, '共に甦へらせ、共に天の處に坐せしめ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'これキリスト・イエスに由りて我らに施したまふ仁慈をもて、其の恩惠の極めて大なる富を、來らんとする後の世々に顯さんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, '汝らは恩惠により、信仰によりて救はれたり、是おのれに由るにあらず、神の賜物なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, '行爲に由るにあらず、これ誇る者のなからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, '我らは神に造られたる者にして、神の預じめ備へ給ひし善き業に歩むべく、キリスト・イエスの中に造られたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'されば記憶せよ、肉によりては異邦人にして、手にて肉に行ひたるかの割禮ありと稱ふる者に無 割禮と稱へらるる汝ら、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, '曩にはキリストなく、イスラエルの民 籍に遠く、約束に屬する諸般の契約に與りなく、世に在りて希望なく、神なき者なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'されど前に遠かりし汝ら今キリスト・イエスに在りて、キリストの血によりて近づくことを得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, '彼は我らの平和にして、己が肉により、樣々の誡命の規より成る律法を廢して、二つのものを一つとなし、怨なる隔の中籬を毀ち給へり。これは二つのものを己に於て一つの新しき人に造りて平和をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, '彼は我らの平和にして、己が肉により、樣々の誡命の規より成る律法を廢して、二つのものを一つとなし、怨なる隔の中籬を毀ち給へり。これは二つのものを己に於て一つの新しき人に造りて平和をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, '十字架によりて怨を滅し、また之によりて二つのものを一つの體となして神と和がしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'かつ來りて、遠かりし汝 等にも平和を宣べ、近きものにも平和を宣べ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'そはキリストによりて我ら二つのもの一つ御靈にありて父に近づくことを得たればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'されば汝 等はもはや旅人また寄寓人にあらず、聖徒と同じ國人また神の家族なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, '汝らは使徒と預言者との基の上に建てられたる者にして、キリスト・イエス自らその隅の首石たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'おのおのの建造物、かれに在りて建て合せられ、彌増に聖なる宮、主のうちに成るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, '汝 等もキリストに在りて共に建てられ、御靈によりて神の御住となるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'この故に汝ら異邦人のためにキリスト・イエスの囚人となれる我パウロ――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, '汝 等のために我に賜ひたる神の恩惠の經綸は汝ら聞きしならん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, '即ち我まへに簡單に書きおくりし如く、この奧義は默示にて我に示されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, '汝 等これを讀みてキリストの奧義にかかはる我が悟を知ることを得べし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'この奧義は、いま御靈によりて聖 使徒と聖 預言者とに顯されし如くに、前代には人の子らに示されざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, '即ち異邦人が福音によりキリスト・イエスに在りて共に世嗣となり、共に一體となり、共に約束に與る者となる事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, '我はその福音の役者とせらる。これ神の能力の活動に隨ひて我に賜ふ惠の賜物によるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, '我は凡ての聖徒のうちの最 小き者よりも小き者なるに、キリストの測るべからざる富を異邦人に傳へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'また萬物を造り給ひし神のうちに、世々 隱れたる奧義の經綸の如何なるもの乎をあらはす恩惠を賜はりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'いま教會によりて神の豐なる知慧を、天の處にある政治と權威とに知らしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'これは永遠より我らの主キリスト・イエスの中に、神の定め給ひし御旨によるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, '我らは彼に在りて彼を信ずる信仰により、臆せず疑はずして神に近づくことを得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'されば汝らに請ふ、わが汝 等のために受くる患難に就きて落膽すな、是なんぢらの譽なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'この故に我は天と地とに在る諸族の名の起るところの父に跪づきて願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'この故に我は天と地とに在る諸族の名の起るところの父に跪づきて願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, '父その榮光の富にしたがひて、御靈により力をもて汝らの内なる人を強くし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, '信仰によりてキリストを汝らの心に住はせ、汝らをして愛に根ざし、愛を基とし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, '凡ての聖徒とともにキリストの愛の廣さ・長さ・高さ・深さの如何ばかりなるかを悟り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'その測り知るべからざる愛を知ることを得しめ、凡て神に滿てる者を汝らに滿しめ給はん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, '願はくは我らの中にはたらく能力に隨ひて、我らの凡て求むる所、すべて思ふ所よりも甚く勝る事をなし得る者に、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, '榮光 世々 限りなく教會によりて、又キリスト・イエスによりて在らんことを、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'されば主に在りて囚人たる我なんぢらに勸む。汝ら召されたる召に適ひて歩み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, '事 毎に謙遜と柔和と寛容とを用ひ、愛をもて互に忍び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, '平和の繋のうちに勉めて御靈の賜ふ一致を守れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, '體は一つ、御靈は一つなり。汝らが召にかかはる一つ望をもて召されたるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, '主は一つ、信仰は一つ、バプテスマは一つ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, '凡ての者の父なる神は一つなり。神は凡てのものの上に在し、凡てのものを貫き、凡てのものの内に在したまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, '我等はキリストの賜物の量に隨ひて、おのおの恩惠を賜はりたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'されば云へることあり『かれ高きところに昇りしとき、多くの虜をひきゐ、人々に賜物を賜へり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '既に昇りしと云へば、まづ地の低き處まで降りしにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, '降りし者は即ち萬の物に滿たん爲に、もろもろの天の上に昇りし者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, '彼は或 人を使徒とし、或 人を預言者とし、或 人を傳道者とし、或 人を牧師・教師として與へ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'これ聖徒を全うして職を行はせ、キリストの體を建て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, '我等をしてみな信仰と神の子を知る知識とに一致せしめ、全き人、すなはちキリストの滿ち足れるほどに至らせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'また我等はもはや幼童ならず、人の欺騙と誘惑の術たる惡巧とより起る樣々の教の風に吹きまはされず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'ただ愛をもて眞を保ち、育ちて凡てのこと首なるキリストに達せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, '彼を本とし全身は凡ての節々の助にて整ひ、かつ聯り、肢體おのおの量に應じて働くにより、その體 成長し、自ら愛によりて建てらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'されば我これを言ひ、主に在りて證す、なんぢら今よりのち、異邦人のその心の虚無に任せて歩むが如く歩むな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, '彼らは念 暗くなりて、其の内なる無知により、心の頑固によりて神の生命に遠ざかり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, '恥を知らず、放縱に凡ての汚穢を行はんとて己を好色に付せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'されど汝らはかくの如くならん爲にキリストを學べるにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, '汝らは彼に聞き、彼に在りてイエスにある眞理に循ひて教へられしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, '即ち汝ら誘惑の慾のために亡ぶべき前の動作に屬ける舊き人を脱ぎすて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, '心の靈を新にし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, '眞理より出づる義と聖とにて、神に象り造られたる新しき人を著るべきことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'されば虚僞をすてて各自その隣に實をかたれ、我ら互に肢なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, '汝ら怒るとも罪を犯すな、憤恚を日の入るまで續くな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, '惡魔に機會を得さすな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, '盜する者は今よりのち盜すな、むしろ貧しき者に分け與へ得るために手づから働きて善き業をなせ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, '惡しき言を一切なんぢらの口より出すな、ただ時に隨ひて人の徳を建つべき善き言を出して、聽く者に益を得させよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, '神の聖 靈を憂ひしむな、汝らは贖罪の日のために聖 靈にて印せられたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, '凡ての苦・憤恚・怒・喧噪・誹謗、および凡ての惡意を汝 等より棄てよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, '互に仁慈と憐憫とあれ、キリストに在りて神の汝らを赦し給ひしごとく、汝らも互に赦せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'されば汝ら愛せらるる子供のごとく、神に效ふ者となれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, '又キリストの汝らを愛し、我らのために己を馨しき香の献物とし犧牲として、神に献げ給ひし如く、愛の中をあゆめ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, '聖徒たるに適ふごとく、淫行、もろもろの汚穢、また慳貪を汝らの間にて稱ふる事だに爲な。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'また恥づべき言・愚なる話・戯言を言ふな、これ宜しからぬ事なり、寧ろ感謝せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, '凡て淫行のもの、汚れたるもの、貪るもの、即ち偶像を拜む者どもの、キリストと神との國の世嗣たることを得ざるは、汝らの確く知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, '汝ら人の虚しき言に欺かるな、神の怒はこれらの事によりて不 從順の子らに及ぶなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'この故に彼らに與する者となるな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, '汝ら舊は闇なりしが、今は主に在りて光となれり、光の子供のごとく歩め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(光の結ぶ實はもろもろの善と正義と誠實となり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, '主の喜び給ふところの如何なるかを辨へ知れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, '實を結ばぬ暗き業に與する事なく、反つて之を責めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, '彼らが隱れて行ふことは之を言ふだに恥づべき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, '凡てかかる事は、責めらるるとき光にて顯さる、顯さるる者はみな光となるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'この故に言ひ給ふ『眠れる者よ、起きよ、死人の中より立ち上れ。さらばキリスト汝を照し給はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'されば愼みてその歩むところに心せよ、智からぬ者の如くせず、智き者の如くし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'また機會をうかがへ、そは時 惡しければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'この故に愚とならず、主の御意の如何を悟れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, '酒に醉ふな、放蕩はその中にあり、むしろ御靈にて滿され、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, '詩と讃美と靈の歌とをもて語り合ひ、また主に向ひて心より且うたひ、かつ讃美せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, '凡ての事に就きて常に我らの主イエス・キリストの名によりて父なる神に感謝し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'キリストを畏みて互に服へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, '妻たる者よ、主に服ふごとく己の夫に服へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'キリストは自ら體の救主にして教會の首なるごとく、夫は妻の首なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, '教會のキリストに服ふごとく、妻も凡てのこと夫に服へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, '夫たる者よ、キリストの教會を愛し、之がために己を捨て給ひしごとく、汝らも妻を愛せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'キリストの己を捨て給ひしは、水の洗をもて言によりて教會を潔め、これを聖なる者として、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, '汚點なく皺なく、凡て斯くのごとき類なく、潔き瑕なき尊き教會を、おのれの前に建てん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, '斯くのごとく夫はその妻を己の體のごとく愛すべし。妻を愛するは己を愛するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, '己の身を憎む者は曾てあることなし、皆これを育て養ふ、キリストの教會に於けるも亦かくの如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, '我らは彼の體の肢なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '『この故に人は父 母を離れ、その妻に合ひて二人のもの一體となるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'この奧義は大なり、わが言ふ所はキリストと教會とを指せるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, '汝 等おのおの己のごとく其の妻を愛せよ、妻も亦その夫を敬ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, '子たる者よ、なんぢら主にありて兩親に順へ、これ正しき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '『なんぢの父 母を敬へ(これ約束を加へたる誡命の首なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'さらばなんぢ幸福を得、また地の上に壽 長からん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, '父たる者よ、汝らの子供を怒らすな、ただ主の薫陶と訓戒とをもて育てよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, '僕たる者よ、キリストに從ふごとく畏れをののき、眞心をもて肉につける主人に從へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, '人を喜ばする者の如く、ただ目の前の事のみを勤めず、キリストの僕のごとく心より神の御旨をおこなひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, '人に事ふる如くせず、主に事ふるごとく快くつかへよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'そは奴隷にもあれ、自主にもあれ、各自おこなふ善き業によりて主より其の報を受くることを汝ら知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, '主人たる者よ、汝らも僕に對し斯く行ひて威嚇を止めよ、そは彼らと汝らとの主は天に在して、偏り視たまふことなきを汝ら知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, '終に言はん、汝ら主にありて其の大能の勢威に頼りて強かれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, '惡魔の術に向ひて立ち得んために、神の武具をもて鎧ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, '我らは血肉と戰ふにあらず、政治・權威、この世の暗黒を掌どるもの、天の處にある惡の靈と戰ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'この故に神の武具を執れ、汝ら惡しき日に遭ひて仇に立ちむかひ、凡ての事を成就して立ち得んためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, '汝ら立つに誠を帶として腰に結び、正義を胸當として胸に當て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, '平和の福音の備を靴として足に穿け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'この他なほ信仰の盾を執れ、之をもて惡しき者の凡ての火矢を消すことを得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'また救の冑および御靈の劍、すなはち神の言を執れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, '常にさまざまの祈と願とをなし、御靈によりて祈り、また目を覺して凡ての聖徒のためにも願ひて倦まざれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, '又わが口を開くとき言を賜はり、憚らずして福音の奧義を示し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, '語るべき所を憚らず語り得るように、我がためにも祈れ、我はこの福音のために使者となりて鎖に繋がれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, '愛する兄弟、主に在りて忠實なる役者テキコ、我が情況わが爲す所のことを、具に汝らに知らせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'われ彼を遣すは、我が事を汝らに知らせて、汝らの心を慰めしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, '願はくは父なる神および主イエス・キリストより賜ふ平安と、信仰に伴へる愛と、兄弟たちに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, '願はくは朽ちぬ愛をもて我らの主イエス・キリストを愛する凡ての者に御惠あらんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'キリスト・イエスの僕たる我ら、パウロとテモテと、書をピリピにをるキリスト・イエスに在る凡ての聖徒、および監督たちと執事たちとに贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, '願はくは我らの父なる神および主イエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'われ汝らを憶ふごとに、我が神に感謝し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, '常に汝ら衆のために、願のつどつど喜びて願をなす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, '是なんぢら初の日より今に至るまで、福音を弘むることに與るが故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, '我は汝らの衷に善き業を始め給ひし者の、キリスト・イエスの日まで之を全うし給ふべきことを確信す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'わが斯くも汝ら衆を思ふは當然の事なり、我が縲絏にある時にも、福音を辯明して之を堅うする時にも、汝らは皆われと共に恩惠に與るによりて、我が心にあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, '我いかにキリスト・イエスの心をもて汝ら衆を戀ひ慕ふか、その證をなし給ふ者は神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, '我は祈る、汝らの愛、知識ともろもろの悟とによりて彌が上にも増し加はり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, '善惡を辨へ知り、キリストの日に至るまで潔よくして躓くことなく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'イエス・キリストによる義の果を充して、神の榮光と譽とを顯さん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, '兄弟よ、我はわが身にありし事の反つて福音の進歩の助となりしを汝らが知らんことを欲するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, '即ち我が縲絏のキリストの爲なることは、近衞の全營にも、他の凡ての人にも顯れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'かつ兄弟のうちの多くの者は、わが縲絏によりて主を信ずる心を厚くし、懼るる事なく、ますます勇みて神の言を語るに至れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, '或 者は嫉妬と分爭とによりてキリストを宣傳へ、あるものは善き心によりて之を宣傳ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'これは福音を辯明するために我が立てられたることを知り、愛によりてキリストを宣べ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'かれは我が縲絏に患難を加へんと思ひ、誠意によらず、徒黨によりて之を宣ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'さらば如何、外貌にもあれ、眞にもあれ、孰も宣ぶる所はキリストなれば、我これを喜ぶ、また之を喜ばん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'そは此のことの汝らの祈とイエス・キリストの御靈の賜物とによりて、我が救となるべきを知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'これは我が何事をも恥ぢずして、今も常のごとく聊かも臆することなく、生くるにも、死ぬるにも、我が身によりてキリストの崇められ給はんことを切に願ひ、また望むところに適へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, '我にとりて、生くるはキリストなり、死ぬるもまた益なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'されど若し肉體にて生くる事わが勤勞の果となるならば、孰を選ぶべきか、我これを知らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, '我はこの二つの間に介まれたり。わが願は世を去りてキリストと偕に居らんことなり、これ遙に勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'されど我なほ肉體に留るは汝らの爲に必要なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, '我これを確信する故に、なほ存へて汝らの信仰の進歩と喜悦とのために、汝 等すべての者と偕に留らんことを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'これは我が再び汝らに到ることにより、汝らキリスト・イエスに在りて我にかかはる誇を増さん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, '汝 等ただキリストの福音に相應しく日を過せ、さらば我が往きて汝らを見るも、離れゐて汝らの事をきくも、汝らが靈を一つにして堅く立ち、心を一つにして福音の信仰のために共に戰ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, '凡ての事において逆ふ者に驚かされぬを知ることを得ん。その驚かされぬは、彼らには亡の兆、なんぢらには救の兆にて、此は神より出づるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, '汝 等はキリストのために啻に彼を信ずる事のみならず、また彼のために苦しむ事をも賜はりたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, '汝らが遭ふ戰鬪は、曩に我の上に見しところ、今また我に就きて聞くところに同じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'この故に若しキリストによる勸、愛による慰安、御靈の交際、また憐憫と慈悲とあらば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'なんぢら念を同じうし、愛を同じうし、心を合せ、思ふことを一つにして、我が喜悦を充しめよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, '何事にまれ、徒黨また虚榮のためにすな、おのおの謙遜をもて互に人を己に勝れりとせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'おのおの己が事のみを顧みず、人の事をも顧みよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, '汝らキリスト・イエスの心を心とせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, '即ち彼は神の貌にて居給ひしが、神と等しくある事を固く保たんとは思はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, '反つて己を空しうし、僕の貌をとりて人の如くなれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, '既に人の状にて現れ、己を卑うして死に至るまで、十字架の死に至るまで順ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'この故に神は彼を高く上げて、之に諸般の名にまさる名を賜ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'これ天に在るもの、地に在るもの、地の下にあるもの、悉とくイエスの名によりて膝を屈め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, '且もろもろの舌の『イエス・キリストは主なり』と言ひあらはして、榮光を父なる神に歸せん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'されば我が愛する者よ、なんぢら常に服ひしごとく、我が居る時のみならず、我が居らぬ今もますます服ひ、畏れ戰きて己が救を全うせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, '神は御意を成さんために汝らの衷にはたらき、汝 等をして志望をたて、業を行はしめ給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'なんぢら呟かず疑はずして、凡ての事をおこなへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, '是なんぢら責むべき所なく素直にして、此の曲れる邪惡なる時代に在りて神の瑕なき子とならん爲なり。汝らは生命の言を保ちて、世の光のごとく此の時代に輝く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'かくて我が走りしところ勞せしところ空しからず、キリストの日にわれ誇ることを得ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'さらば汝らの信仰の供物と祭とに加へて、我が血を灌ぐとも我は喜ばん、なんぢら衆と共に喜ばん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'かく汝 等もよろこべ、我とともに喜べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'われ汝らの事を知りて慰安を得んとて、速かにテモテを汝らに遣さんことを主イエスに頼りて望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'そは彼のほかに我と同じ心をもて眞實に汝らのことを慮ぱかる者なければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, '人は皆イエス・キリストの事を求めず、唯おのれの事のみを求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'されどテモテの錬達なるは汝らの知る所なり、即ち子の父に於ける如く我とともに福音のために勤めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'この故に我わが身の成行を見ば、直ちに彼を遣さんことを望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, '我もまた速かに往くべきを主によりて確信す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'されど今は先われと共に働き共に戰ひし兄弟、すなはち汝らの使として我が窮乏を補ひしエパフロデトを、汝らに遣すを必要のことと思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, '彼は汝 等すべての者を戀ひしたひ、又おのが病みたることの汝らに聞えしを以て悲しみ居るに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, '彼は實に病にかかりて死ぬばかりなりしが、神は彼を憐みたまへり、啻に彼のみならず、我をも憐み、憂に憂を重ねしめ給はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'この故に急ぎて彼を遣す、なんぢらが再び彼を見て喜ばん爲なり。又わが憂を少うせん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'されば汝ら主にありて歡喜を盡して彼を迎へ、かつ斯くのごとき人を尊べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, '彼は汝らが我を助くるに當り、汝らの居らぬを補はんとて、己が生命を賭け、キリストの事業のために死ぬばかりになりたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, '終に言はん、我が兄弟よ、なんぢら主に在りて喜べ。なんぢらに同じことを書きおくるは、我に煩はしきことなく、汝 等には安然なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'なんぢら犬に心せよ、惡しき勞動人に心せよ、肉の割禮ある者に心せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, '神の御靈によりて禮拜をなし、キリスト・イエスによりて誇り、肉を恃まぬ我らは眞の割禮ある者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'されど我は肉にも恃むことを得るなり。もし他の人、肉に恃むところありと思はば、我は更に恃む所あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, '我は八日めに割禮を受けたる者にして、イスラエルの血統、ベニヤミンの族、ヘブル人より出でたるヘブル人なり。律法に就きてはパリサイ人、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, '熱心につきては教會を迫害したるもの、律法によれる義に就きては責むべき所なかりし者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'されど曩に我が益たりし事はキリストのために損と思ふに至れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, '然り、我はわが主キリスト・イエスを知ることの優れたるために、凡ての物を損なりと思ひ、彼のために既に凡ての物を損せしが、之を塵芥のごとく思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'これキリストを獲、かつ律法による己が義ならで、唯キリストを信ずる信仰による義、すなはち信仰に基きて神より賜はる義を保ち、キリストに在るを認められ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'キリストとその復活の力とを知り、又その死に效ひて彼の苦難にあづかり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, '如何にもして死人の中より甦へることを得んが爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'われ既に取れり、既に全うせられたりと言ふにあらず、唯これを捉へんとて追ひ求む。キリストは之を得させんとて我を捉へたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, '兄弟よ、われは既に捉へたりと思はず、唯この一事を務む、即ち後のものを忘れ、前のものに向ひて勵み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, '標準を指して進み、神のキリスト・イエスに由りて上に召したまふ召にかかはる褒美を得んとて之を追ひ求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'されば我等のうち成人したる者は、みな斯くのごとき思を懷くべし、汝 等もし何事にても異なる思を懷き居らば、神これをも示し給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'ただ我等はその至れる所に隨ひて歩むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, '兄弟よ、なんぢら諸共に我に效ふものとなれ、且なんぢらの模範となる我らに循ひて歩むものを視よ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'そは我しばしば汝らに告げ、今また涙を流して告ぐる如く、キリストの十字架に敵して歩む者おほければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, '彼らの終は滅亡なり。おのが腹を神となし、己が恥を光榮となし、ただ地の事のみを念ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'されど我らの國籍は天に在り、我らは主イエス・キリストの救主として其の處より來りたまふを待つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, '彼は萬物を己に服はせ得る能力によりて、我らの卑しき状の體を化へて、己が榮光の體に象らせ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'この故に我が愛するところ慕ふところの兄弟、われの喜悦われの冠冕たる愛する者よ、斯くのごとく主にありて堅く立て。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, '我ユウオデヤに勸めスントケに勸む、主にありて心を同じうせんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'また眞實に我と軛を共にする者よ、なんぢに求む。この二人の女を助けよ。彼らはクレメンス其のほか生命の書に名を録されたる我が同勞者と同じく、福音のために我とともに勤めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, '汝ら常に主にありて喜べ、我また言ふ、なんぢら喜べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, '凡ての人に汝らの寛容を知らしめよ、主は近し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, '何事をも思ひ煩ふな、ただ事ごとに祈をなし、願をなし、感謝して汝らの求を神に告げよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'さらば凡て人の思にすぐる神の平安は、汝らの心と思とをキリスト・イエスによりて守らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, '終に言はん、兄弟よ、凡そ眞なること、凡そ尊ぶべきこと、凡そ正しきこと、凡そ潔よきこと、凡そ愛すべきこと、凡そ令聞あること、如何なる徳いかなる譽にても、汝 等これを念へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'なんぢら我に學びしところ、受けしところ、聞きしところ、見し所を皆おこなへ、さらば平和の神なんぢらと偕に在さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, '汝らが我を思ふ心の今また萠したるを、われ主にありて甚く喜ぶ。汝らは固より我を思ひゐたるなれど、機を得ざりしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'われ窮乏によりて之を言ふにあらず、我は如何なる状に居るとも、足ることを學びたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, '我は卑賤にをる道を知り、富にをる道を知る。また飽くことにも、飢うることにも、富むことにも、乏しき事にも、一切の秘訣を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, '我を強くし給ふ者によりて、凡ての事をなし得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'されど汝らが我が患難に與りしは善き事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'ピリピ人よ、汝らも知る、わが汝らに福音を傳ふる始、マケドニヤを離れ去るとき、授受して我が事に與りしは、汝 等のみにして、他の教會には無かりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, '汝らは我がテサロニケに居りし時に、一度ならず二度までも我が窮乏に物 贈れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'これ贈物を求むるにあらず、唯なんぢらの益となる實の繁からんことを求むるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, '我には凡ての物そなはりて餘あり、既にエパフロデトより汝らの贈物を受けたれば、飽き足れり。これは馨しき香にして神の享け給ふところ、喜びたまふ所の供物なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'かくてわが神は己の富に隨ひ、キリスト・イエスによりて汝らの凡ての窮乏を榮光のうちに補ひ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, '願はくは榮光 世々 限りなく、我らの父なる神にあれ、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, '汝らキリスト・イエスに在りて聖徒おのおのに安否を問へ、我と偕にある兄弟たち汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, '凡ての聖徒、殊にカイザルの家のもの、汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, '願はくは主イエス・キリストの恩惠、なんぢらの靈と偕に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, '神の御心によりてキリスト・イエスの使徒となれるパウロ及び兄弟テモテ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, '書をコロサイに居る聖徒、キリストにありて忠實なる兄弟に贈る。願はくは我らの父なる神より賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, '我らは常に汝らの爲に祈りて、我らの主イエス・キリストの父なる神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'これキリスト・イエスを信ずる汝らの信仰と、凡ての聖徒に對する汝らの愛とにつきて聞きたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'かく聖徒を愛するは、汝らの爲に天に蓄へあるものを望むに因る。この望のことは汝らに及べる福音の眞の言によりて汝らが曾て聞きし所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'この福音は全世界にも及び、果を結びて増々 大になれり。汝らが神の恩惠をききて眞に之を知りし日より、汝らの中に然りしが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, '汝らが、我らと共に僕たる愛するエパフラスより學びたるは、この福音なり。彼は汝らの爲にキリストの忠實なる役者にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, '汝らが御靈によりて懷ける愛を我らに告げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'この故に我らこの事を聞きし日より、汝 等のために絶えず祈りかつ求むるは、汝ら靈のもろもろの知慧と穎悟とをもて神の御意を具に知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, '凡てのこと主を悦ばせんが爲に、その御意に從ひて歩み、凡ての善き業によりて果を結び、いよいよ神を知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'また神の榮光の勢威に隨ひて賜ふもろもろの力によりて強くなり、凡ての事よろこびて忍び、かつ耐へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, '而して我らを光にある聖徒の嗣業に與るに足る者とし給ひし父に感謝せん事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, '父は我らを暗黒の權威より救ひ出して、その愛しみ給ふ御子の國に遷したまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, '我らは御子に在りて贖罪すなはち罪の赦を得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, '彼は見 得べからざる神の像にして、萬の造られし物の先に生れ給へる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, '萬の物は彼によりて造らる、天に在るもの、地に在るもの、見ゆるもの、見えぬもの、或は位、あるひは支配、あるひは政治、あるひは權威、みな彼によりて造られ、彼のために造られたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, '彼は萬の物より先にあり、萬の物は彼によりて保つことを得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, '而して彼はその體なる教會の首なり、彼は始にして死人の中より最先に生れ給ひし者なり。これ凡ての事に就きて長とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, '神は凡ての滿ち足れる徳を彼に宿して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'その十字架の血によりて平和をなし、或は地にあるもの、或は天にあるもの、萬の物をして己と和がしむるを善しとし給ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, '汝 等もとは惡しき業を行ひて神に遠ざかり、心にて其の敵となりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, '今は神キリストの肉の體をもて、其の死により汝 等をして己と和がしめ、潔く瑕なく責むべき所なくして、己の前に立たしめんし給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, '汝 等もし信仰に止り、之に基きて堅く立ち、福音の望より移らずば、斯くせらるることを得べし。此の福音は汝らの聞きし所、また天の下なる凡ての造られし物に宣傳へられたるものにして、我パウロはその役者となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'われ今なんぢらの爲に受くる苦難を喜び、又キリストの體なる教會のために、我が身をもてキリストの患難の缺けたるを補ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'われ神より汝 等のために與へられたる職に隨ひて教會の役者となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'これ神の言、すなはち歴世 歴代かくれて、今 神の聖徒に顯れたる奧義を宣傳へんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, '神は聖徒をして異邦人の中なるこの奧義の榮光の富の如何ばかりなるかを知らしめんと欲し給へり、此の奧義は汝らの中に在すキリストにして榮光の望なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, '我らは此のキリストを傳へ、知慧を盡して凡ての人を訓戒し、凡ての人を教ふ。これ凡ての人をしてキリストに在り、全くなりて神の前に立つことを得しめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'われ之がために我が衷に能力をもて働き給ふものの活動にしたがひ、力を盡して勞するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, '我なんぢら及びラオデキヤに居る人々、その他すべて我が肉體の顏をまだ見ぬ人のために、如何に苦心するかを汝らの知らんことを欲す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'かく苦心するは、彼らが心 慰められ、愛をもて相 列り、全き穎悟の凡ての富を得て、神の奧義なるキリストを知らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'キリストには知慧と知識との凡ての寶 藏れあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, '我これを言ふは、巧なる言をもて人の汝らを欺くこと勿らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'われ肉體にては汝らと離れ居れど、靈にては汝らと偕に居りて喜び、また汝らの秩序あるとキリストに對する信仰の堅きとを見るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, '汝らキリスト・イエスを主として受けたるにより、其のごとく彼に在りて歩め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'また彼に根ざしてその上に建てられ、かつ教へられし如く信仰を堅くし、溢るるばかり感謝せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'なんぢら心すべし、恐らくはキリストに從はずして人の言傳と世の小學とに從ひ、人を惑す虚しき哲學をもて汝らを奪ひ去る者あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'それ神の滿ち足れる徳はことごとく形體をなしてキリストに宿れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, '汝らは彼に在りて滿ち足れるなり。彼は凡ての政治と權威との首なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, '汝らまた彼に在りて手をもてせざる割禮を受けたり、即ち肉の體を脱ぎ去るものにして、キリストの割禮なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, '汝らバプテスマを受けしとき、彼とともに葬られ、又かれを死人の中より甦へらせ給ひし神の活動を信ずるによりて、彼と共に甦へらせられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, '汝ら前には諸般の咎と肉の割禮なきとに因りて死にたる者なりしが、神は汝らを彼と共に生かし、我らの凡ての咎を赦し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'かつ我らを責むる規の證書、すなはち我らに逆ふ證書を塗抹し、これを中間より取り去りて十字架につけ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, '政治と權威とを褫ぎて之を公然に示し、十字架によりて凱旋し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, '然れば汝ら食物あるひは飮物につき、祭あるいは月朔あるいは安息 日の事につきて、誰にも審かるな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, '此 等はみな來らんとする者の影にして、其の本體はキリストに屬けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, '殊更に謙遜をよそほひ御使を拜する者に、汝らの褒美を奪はるな。かかる者は見し所のものに基き、肉の念に隨ひて徒らに誇り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, '首に屬くことをせざるなり。全體は、この首によりて節々 維々に助けられ、相 聯り、神の育にて生長するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, '汝 等もしキリストと共に死にて此の世の小學を離れしならば、何ぞなほ世に生ける者のごとく人の誡命と教とに循ひて');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '『捫るな、味ふな、觸るな』と云ふ規の下に在るか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '(此 等はみな用ふれば盡くる物なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'これらの誡命は、みづから定めたる禮拜と謙遜と身を惜まぬ事とによりて知慧あるごとく見ゆれど、實は肉 慾の放縱を防ぐ力なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, '汝 等もしキリストと共に甦へらせられしならば、上にあるものを求めよ、キリスト彼處に在りて神の右に坐し給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, '汝ら上にあるものを念ひ、地に在るものを念ふな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, '汝らは死にたる者にして、其の生命はキリストとともに神の中に隱れ在ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, '我らの生命なるキリストの現れ給ふとき、汝らも之とともに榮光のうちに現れん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'されば地にある肢體、すなはち淫行・汚穢・情 慾・惡 慾・また慳貪を殺せ、慳貪は偶像 崇拜なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, '神の怒は、これらの事によりて不 從順の子らに來るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, '汝らもかかる人の中に日を送りし時は、これらの惡しき事に歩めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'されど今は凡て此 等のこと及び怒・憤恚・惡意を棄て、譏と恥づべき言とを汝らの口より棄てよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, '互に虚言をいふな、汝らは既に舊き人とその行爲とを脱ぎて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, '新しき人を著たればなり。この新しき人は、これを造り給ひしものの像に循ひ、いよいよ新になりて知識に至るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'かくてギリシヤ人とユダヤ人、割禮と無 割禮、あるひは夷狄、スクテヤ人・奴隷・自主の別ある事なし、それキリストは萬の物なり、萬のものの中にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'この故に汝らは神の選民にして聖なる者また愛せらるる者なれば、慈悲の心・仁慈・謙遜・柔和・寛容を著よ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'また互に忍びあひ、若し人に責むべき事あらば互に恕せ、主の汝らを恕し給へる如く汝らも然すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, '凡て此 等のものの上に愛を加へよ、愛は徳を全うする帶なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'キリストの平和をして汝らの心を掌どらしめよ、汝らの召されて一體となりたるはこれが爲なり、汝ら感謝の心を懷け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'キリストの言をして豐に汝らの衷に住ましめ、凡ての知慧によりて、詩と讃美と靈の歌とをもて、互に教へ互に訓戒し、恩惠に感じて心のうちに神を讃美せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'また爲す所の凡ての事、あるひは言あるひは行爲、みな主イエスの名に頼りて爲し、彼によりて父なる神に感謝せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, '妻たる者よ、その夫に服へ、これ主にある者のなすべき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, '夫たる者よ、その妻を愛せよ、苦をもて之を待ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, '子たる者よ、凡ての事みな兩親に順へ、これ主の喜びたまふ所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, '父たる者よ、汝らの子供を怒らすな、或は落膽することあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, '僕たる者よ、凡ての事みな肉につける主人にしたがへ、人を喜ばする者の如く、ただ眼の前の事のみを勤めず、主を畏れ、眞心をもて從へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, '汝ら何事をなすにも人に事ふる如くせず、主に事ふる如く心より行へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, '汝らは主より報として嗣業を受くることを知ればなり。汝らは主キリストに事ふる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, '不義を行ふ者はその不義の報を受けん、主は偏り視 給ふことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, '主人たる者よ、汝らも天に主あるを知れば、義と公平とをもて其の僕をあしらへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, '汝ら感謝しつつ目を覺して祈を常にせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'また我らの爲にも祈りて、神の我らに御言を傳ふる門をひらき、我等をしてキリストの奧義を語らしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, '之を我が語るべき如く顯させ給はんことを願へ、我はこの奧義のために繋がれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'なんぢら機をうかがひ、外の人に對し知慧をもて行へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, '汝らの言は常に惠を用ひ、鹽にて味つけよ。然らば如何にして各人に答ふべきかを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, '愛する兄弟、忠實なる役者、主にありて我とともに僕たるテキコ、我がことを具に汝らに知らせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'われ殊に彼を汝らに遣すは、我らの事を知らしめ、又なんぢらの心を慰めしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, '汝らの中の一人、忠實なる愛する兄弟オネシモを彼と共につかはす、彼 等この處の事を具に汝らに知らせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, '我と共に囚人となれるアリスタルコ及びバルナバの從弟なるマルコ、汝らに安否を問ふ。此のマルコに就きては汝ら既に命を受けたり、彼もし汝らに到らば之を接けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'またユストと云へるイエス汝らに安否を問ふ。割禮の者の中ただ此の三人のみ、神の國のために働く我が同勞者にして我が慰安となりたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, '汝らの中の一人にてキリスト・イエスの僕なるエパフラス汝らに安否を問ふ。彼は常に汝らの爲に力を盡して祈をなし、汝らが全くなり、凡て神の御意を確信して立たんことを願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, '我かれが汝らとラオデキヤ及びヒエラポリスに在る者との爲に甚く心を勞することを證す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, '愛する醫者ルカ及びデマス汝らに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, '汝らラオデキヤにある兄弟とヌンパ及びその家にある教會とに安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'この書を汝らの中にて讀みたらば、之をラオデキヤ人の教會にも讀ませ、汝 等はまたラオデキヤより來る書を讀め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'アルキポに言へ『主にありて受けし職を愼みて盡せ』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, '我パウロ手づから安否を問ふ。わが縲絏を記憶せよ。願はくは御惠なんぢらと偕に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'パウロ、シルワノ、テモテ、書を父なる神および主イエス・キリストにあるテサロニケ人の教會に贈る。願はくは恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'われら祈のときに汝らを憶えて、常に汝ら衆人のために神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'これ汝らが信仰のはたらき、愛の勞苦、主イエス・キリストに對する望の忍耐を、我らの父なる神の前に絶えず念ふに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, '神に愛せらるる兄弟よ、また汝らの選ばれたることを知るに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'それ我らの福音の汝らに至りしは、言にのみ由らず、能力と聖 靈と大なる確信とに由れり。且われらが汝らの中にありて汝らの爲に如何なる行爲をなししかは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'かくて汝らは大なる患難のうちにも、聖 靈による喜悦をもて御言をうけ、我ら及び主に效ふ者となり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, '而してマケドニヤ及びアカヤに在る凡ての信者の模範となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'それは主のことば汝 等より出でて、啻にマケドニヤ及びアカヤに響きしのみならず、神に對する汝らの信仰のことは諸方に弘りたるなり。されば之に就きては何をも語るに及ばず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, '人々 親しく我らが汝らの中に入りし状を告げ、また汝らが偶像を棄てて神に歸し、活ける眞の神に事へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, '神の死人の中より甦へらせ給ひし御子、すなはち我らを來らんとする怒より救ひ出すイエスの、天より降りたまふを待ち望むことを告ぐればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, '兄弟よ、我らの汝らに到りしことの空しからざりしは、汝ら自ら知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, '前に我らは汝らの知るごとく、ピリピにて苦難と侮辱とを受けたれど、我らの神に頼りて大なる紛爭のうちに、憚らず神の福音を汝らに語れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, '我らの勸は、迷より出でず、汚穢より出でず、詭計を用ひず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, '神に嘉せられて福音を委ねられたる者なれば、人を喜ばせんとせず、我らの心を鑒たまふ神を喜ばせ奉つらんとして語るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, '我らは汝らの知るごとく何時にても諂諛の言を用ひず、事によせて慳貪をなさず(神これを證し給ふ)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'キリストの使徒として重んぜらるべき者なれども、汝らにも他の者にも人よりは譽を求めず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, '汝らの中にありて優しきこと、母の己が子を育てやしなふ如くなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'かく我らは汝らを戀ひ慕ひ、なんぢらは我らの愛する者となりたれば、啻に神の福音のみならず、我らの生命をも與へんと願へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, '兄弟よ、なんぢらは我らの勞と苦難とを記憶す、われらは汝らの中の一人をも累はすまじとて、夜晝 工をなし、勞しつつ福音を宣傳へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'また信じたる汝 等にむかひて、如何に潔く正しく責むべき所なく行ひしかは、汝らも證し神も證し給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, '汝らは知る、我らが父のその子に對するごとく各人に對し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, '御國と榮光とに招きたまふ神の心に適ひて歩むべきことを勸め、また勵まし、また諭したるを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'かくてなほ我ら神に感謝して巳まざるは、汝らが神の言を我らより聞きし時、これを人の言とせず、神の言として受けし事なり。これは誠に神の言にして、汝ら信ずる者のうちに働くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, '兄弟よ、汝らはユダヤに於けるキリスト・イエスにある神の教會に效ふ者となれり、彼らのユダヤ人に苦しめられたる如く、汝らも己が國人に苦しめられたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'ユダヤ人は主イエスをも預言者をも殺し、我らを追ひ出し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, '我らが異邦人に語りて救を得させんとするを拒み、神を悦ばせず、かつ萬民に逆ひ、かくして常に己が罪を充すなり。而して神の怒はかれらに臨みてその極に至れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, '兄弟よ、われら心は離れねど、顏にて暫時なんぢらと離れ居れば、汝らの顏を見んことを愈々 切に願ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, '(我パウロは一度ならず再度までも)なんぢらに到らんと爲たれど、サタンに妨げられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, '我らの主イエスの來り給ふとき、御前における我らの希望、また喜悦、また誇の冠冕は誰ぞ、汝らならずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, '實に汝らは我らの光榮、我らの喜悦なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'この故に、もはや忍ぶこと能はず、我等のみアテネに留ることに決し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'キリストの福音において神の役者たる我らの兄弟テモテを汝らに遣せり。これは汝らを堅うし、また信仰につきて勸め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'この患難によりて動かさるる者の無からん爲なり。患難に遭ふことの我らに定りたるは、汝 等みづから知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, '我らが患難に遭ふべきことは、汝らと偕に在りしとき預じめ告げたるが、今 果して汝らの知るごとく然か成れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'この故に最早われ忍ぶこと能はず、試むる者の汝らを試みて、我らの勞の空しくならんことを恐れ、なんぢらの信仰を知らんとて人を遣せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, '然るに今テモテ汝らより歸りて、汝らの信仰と愛とにつきて喜ばしき音信を聞かせ、又なんぢら常に我らを懇ろに念ひ、我らに逢はんことを切に望み居るは、我らが汝らに逢はんことを望むに等しと告げたるによりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, '兄弟よ、われらは諸般の苦難と患難との中にも、汝らの信仰によりて慰安を得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, '汝 等もし主に在りて堅く立たば我らは生くるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, '汝 等につきて我らの神の前によろこぶ大なる喜悦のために、如何なる感謝をか神に献ぐべき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, '我らは夜晝 祈りて、汝らの顏を見んことと、汝らの信仰の足らぬ所を補はんこととを切に願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, '願はくは我らの父なる神みづからと我らの主なるイエスと、我らを導きて汝らに到らせ給はんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, '願はくは主、なんぢら相 互の愛および凡ての人に對する愛を増し、かつ豐にして、我らが汝らを愛する如くならしめ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'かくして汝らの心を堅うし、我らの主イエスの、凡ての聖徒と偕に來りたまふ時、われらの父なる神の前に潔くして責むべき所なからしめ給はんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'されば兄弟よ、終に我ら主イエスによりて汝らに求め、かつ勸む。なんぢら如何に歩みて神を悦ばすべきかを我等より學びし如く、また歩みをる如くに増々 進まんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, '我らが主イエスに頼りて如何なる命令を與へしかは、汝らの知る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'それ神の御旨は、なんぢらの潔からんことにして、即ち淫行をつつしみ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, '各人おのが妻を得て、潔くかつ貴くし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, '神を知らぬ異邦人のごとく情 慾を放縱にすまじきを知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'かかる事によりて兄弟を欺き、また掠めざらんことなり。凡て此 等のことを行ふ者に主の報し給ふは、わが既に汝らに告げ、かつ證せしごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, '神の我らを招き給ひしは、汚穢を行はしめん爲にあらず、潔からしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'この故に之を拒む者は人を拒むにあらず、汝らに聖 靈を與へたまふ神を拒むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, '兄弟の愛につきては汝らに書きおくるに及ばず。汝らは互に相 愛する事を親しく神に教へられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'また既にマケドニヤ全國に在るすべての兄弟を愛するに因りてなり。されど兄弟よ、なんぢらに勸む。ますます之を行ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, '我らが前に命ぜしことく力めて安靜にし、己の業をなし、手づから働け。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'これ外の人に對して正しく行ひ、また自ら乏しきことなからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, '兄弟よ、既に眠れる者のことに就きては、汝らの知らざるを好まず、希望なき他の人のごとく歎かざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, '我らの信ずる如く、イエスもし死にて甦へり給ひしならば、神はイエスによりて眠に就きたる者を、イエスと共に連れきたり給ふべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'われら主の言をもて汝らに言はん、我等のうち主の來りたまふ時に至るまで生きて存れる者は、既に眠れる者に決して先だたじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'それ主は、號令と御使の長の聲と神のラッパと共に、みづから天より降り給はん。その時キリストにある死人まづ甦へり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, '後に生きて存れる我らは、彼らと共に雲のうちに取り去られ、空中にて主を迎へ、斯くていつまでも主と偕に居るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'されば此 等の言をもて互に相 慰めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, '兄弟よ、時と期とに就きては汝らに書きおくるに及ばず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, '汝らは主の日の盜人の夜きたるが如くに來ることを、自ら詳細に知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, '人々の平和 無事なりと言ふほどに、滅亡にはかに彼らの上に來らん、妊める婦に産の苦痛の臨むがごとし、必ず遁るることを得じ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'されど兄弟よ、汝らは暗に居らざれば、盜人の來るごとく其の日なんぢらに追及くことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'それ汝 等はみな光の子ども晝の子供なり。我らは夜に屬く者にあらず、暗に屬く者にあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'されば他の人のごとく眠るべからず、目を覺して愼むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, '眠る者は夜 眠り、酒に醉ふ者は夜 醉ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'されど我らは晝に屬く者なれば、信仰と愛との胸當を著け、救の望の兜をかむりて愼むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'それ神は我らを怒に遭はせんとにあらず、主イエス・キリストに頼りて救を得させんと定め給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, '主の我等のために死に給へるは、我等をして寤めをるとも眠りをるとも己と共に生くることを得しめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, '此の故に互に勸めて各自の徳を建つべし、これ汝らが常に爲す所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, '兄弟よ、汝らに求む。なんぢらの中に勞し、主にありて汝らを治め、汝らを訓戒する者を重んじ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'その勤勞によりて厚く之を愛し敬へ。また互に相 和ぐべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, '兄弟よ、汝らに勸む、妄なる者を訓戒し、落膽せし者を勵まし、弱き者を扶け、凡ての人に對して寛容なれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, '誰も人に對し惡をもて惡に報いぬやう愼め。ただ相 互に、また凡ての人に對して常に善を追ひ求めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, '常に喜べ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, '絶えず祈れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, '凡てのことを感謝せよ、これキリスト・イエスに由りて神の汝らに求め給ふ所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, '御靈を熄すな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, '預言を蔑すな、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, '凡てのこと試みて善きものを守り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, '凡て惡の類に遠ざかれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, '願はくは平和の神、みづから汝らを全く潔くし、汝らの靈と心と體とを全く守りて、我らの主イエス・キリストの來り給ふとき責むべき所なからしめ給はん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, '汝らを召したまふ者は眞實なれば、之を成し給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, '兄弟よ、我らのために祈れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'きよき接吻をもて凡ての兄弟の安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, '主によりて汝らに命ず、この書を凡ての兄弟に讀み聞かせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, '願はくは主イエス・キリストの恩惠、なんぢらと偕に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'パウロ、シルワノ、テモテ、書を我らの父なる神および主イエス・キリストに在るテサロニケ人の教會に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, '願はくは父なる神および主イエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, '兄弟よ、われら汝 等につきて常に神に感謝せざるを得ず、これ當然の事なり。そは汝らの信仰おほいに加はり、各自みな互の愛を厚くしたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'されば我らは、汝らが忍べる凡ての迫害と患難との中にありて保ちたる忍耐と信仰とを、神の諸 教會の間に誇る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'これ神の正しき審判の兆にして、汝らが神の國に相應しき者とならん爲なり。今その御國のために苦難を受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, '汝らに患難を加ふる者に患難をもて報い、患難を受くる汝らに、我らと共に安息をもて報い給ふは、神の正しき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, '即ち主イエス焔の中にその能力の御使たちと共に天より顯れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, '神を知らぬ者と我らの主イエスの福音に服はぬ者とに報いをなし給ふとき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'かかる者どもは主の顏とその能力の榮光とを離れて、限りなき滅亡の刑罰を受くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'その時は主おのが聖徒によりて崇められ、凡ての信ずる者(なんぢらも我らの證を信じたる者なり)によりて讃められんとて來りたまふ日なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'これに就きて我ら常に汝らのために祈るは、我らの神の汝 等をして召に適ふ者となし、能力をもて汝らの凡て善に就ける願と信仰の業とを成就せしめ給はんことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'これ我らの神および主イエス・キリストの惠によりて、我らの主イエスの御名の汝らの中に崇められ、又なんぢらも彼に在りて崇められん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, '兄弟よ、我らの主イエス・キリストの來り給ふこと、又われらが主の許に集ふことに就きては、汝らに求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, '或は靈により、或は言により、或は我等より出でし如き書により、主の日すでに來れりとて、容易く心を動かしかつ驚かざらん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, '誰が如何にすとも、それに欺かるな。その日の前に背教の事あり、不法の人すなはち滅亡の子あらはれざるを得ず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, '彼はすべて神と稱ふる者および人の拜む者に逆ひ、此 等よりも己を高くし、遂に神の聖所に坐し己を神として見する者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'われ汝らと偕に在りし時、これらの事を告げしを汝ら憶えぬか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, '彼をして己が時に至りて顯れしめんために、彼を阻めをる者を汝らは知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, '不法の秘密は既に働けり、然れど此はただ阻めをる者の除かるるまでなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'かくて其のとき不法の者あらはれん、而して主イエス御口の氣息をもて彼を殺し、降臨の輝耀をもて彼を亡し給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, '彼はサタンの活動に從ひて來り、もろもろの虚僞なる力と徴と不思議と、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, '不義のもろもろの誑惑とを行ひて、亡ぶる者どもに向はん、彼らは眞理を愛する愛を受けずして、救はるることを爲ざればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'この故に神は、彼らが虚僞を信ぜんために惑をその中に働かせ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'これ眞理を信ぜず不義を喜ぶ者の、みな審かれん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'されど主に愛せらるる兄弟よ、われら常に汝 等のために神に感謝せざるを得ず。神は御靈によれる潔と眞理に對する信仰とをもて、始より汝らを救に選び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'また我らの主イエス・キリストの榮光を得させんとて、我らの福音をもて汝らを招き給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'されば兄弟よ、堅く立ちて我らの言あるひは書に由りて教へられたる傳を守れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, '我らの主イエス・キリスト、及び我らを愛し恩惠をもて永遠の慰安と善き望とを與へ給ふ我らの父なる神、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, '願はくは汝らの心を慰めて、凡ての善き業と言とに堅うし給はんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, '終に言はん、兄弟よ、我らの爲に祈れ、主の言の汝らの中における如く、疾く弘りて崇められん事と、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'われらが無法なる惡人より救はれんこととを祈れ。そは人みな信仰あるに非ざればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'されど神は眞實なれば、汝らを堅うし汝らを護りて、惡しき者より救ひ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'かくて我らの命ずることを汝らが今も行ひ、後もまた行はんことを主によりて信ずるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, '願はくは主なんぢらの心を、神の愛とキリストの忍耐とに導き給はんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, '兄弟よ、我らの主イエス・キリストの名によりて汝らに命ず、我等より受けし傳に從はずして妄に歩む凡ての兄弟に遠ざかれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, '如何にして我らに效ふべきかは、汝らの自ら知る所なり。我らは汝らの中にありて妄なる事をせず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, '價なしに人のパンを食せず、反つて汝 等のうち一人をも累はさざらんために勞と苦難とをもて、夜晝はたらけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'これは權 利なき故にあらず、汝 等をして我らに效はしめん爲に、自ら模範となりたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'また汝らと偕に在りしとき、人もし働くことを欲せずば食すべからずと命じたりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, '聞く所によれば、汝 等のうちに妄に歩みて何の業をもなさず、徒事にたづさはる者ありと。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, '我ら斯くのごとき人に、靜に業をなして己のパンを食せんことを、我らの主イエス・キリストに由りて命じかつ勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, '兄弟よ、なんぢら善を行ひて倦むな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'もし此の書にいへる我らの言に從はぬ者あらば、その人を認めて交ることをすな、彼みづから恥ぢんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, '然れど彼を仇の如くせず、兄弟として訓戒せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, '願はくは平和の主、みづから何時にても凡ての事に平和を汝らに與へ給はんことを。願はくは主なんぢら凡ての者と偕に在さん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, '我パウロ手づから筆を執りて汝らの安否を問ふ。これ我がすべての書の記章なり。わが書けるものは斯くの如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, '願はくは我らの主イエス・キリストの恩惠なんぢら凡ての者と偕ならんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, '我らの救主なる神と我らの希望なるキリスト・イエスとの命によりて、キリスト・イエスの使徒となれるパウロ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, '書を信仰に由りて我が眞實の子たるテモテに贈る。願はくは父なる神および我らの主キリスト・イエスより賜ふ恩惠と憐憫と平安と、汝に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, '我マケドニヤに往きしとき汝に勸めし如く、汝なほエペソに留まり、ある人々に命じて、異なる教を傳ふることなく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, '昔話と窮りなき系圖とに心を寄する事なからしめよ。此 等のことは信仰に基ける神の經綸の助とならず、反つて議論を生ずるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, '命令の目的は清き心と善き良心と僞りなき信仰とより出づる愛にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'ある人々これらの事より外れて虚しき物語にうつり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, '律法の教師たらんと欲して、反つて其の言ふ所その確證する所を自ら悟らず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, '律法は道理に循ひて之を用ひば善き者なるを我らは知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, '律法を用ふる者は、律法の正しき人の爲にあらずして、不法のもの、服從せぬもの、敬虔ならぬもの、罪あるもの、潔からぬもの、妄なるもの、父を撃つもの、母を撃つもの、人を殺す者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, '淫行のもの、男色を行ふもの、人を誘拐すもの、僞るもの、いつはり誓ふ者の爲、そのほか健全なる教に逆ふ凡ての事のために設けられたるを知るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'これは我に委ね給ひし幸福なる神の榮光の福音に循へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, '我に能力を賜ふ我らの主キリスト・イエスに感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'われ曩には涜す者、迫害する者、暴行の者なりしに、我を忠實なる者として、この職に任じ給ひたればなり。われ信ぜぬ時に知らずして行ひし故に憐憫を蒙れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, '而して我らの主の恩惠は、キリスト・イエスに由れる信仰および愛とともに溢るるばかり彌増せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, '『キリスト・イエス罪人を救はん爲に世に來り給へり』とは、信ずべく正しく受くべき言なり、其の罪人の中にて我は首なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, '然るに我が憐憫を蒙りしは、キリスト・イエス我を首に寛容をことごとく顯し、この後、かれを信じて永遠の生命を受けんとする者の模範となし給はん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, '願はくは萬世の王、すなはち朽ちず見えざる唯一の神に、世々 限りなく尊貴と榮光とあらん事を、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'わが子テモテよ、汝を指したる凡ての預言に循ひて、我この命令を汝に委ぬ。これ汝がその預言により、信仰と善き良心とを保ちて、善き戰鬪を戰はん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, '或 人よき良心を棄てて信仰の破船をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'その中にヒメナオとアレキサンデルとあり、彼らに涜すまじきことを學ばせんとて、我これをサタンに付せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'さればわれ第一に勸む、凡ての人のため、王たち及び凡て權を有つものの爲に、おのおの願・祈祷・とりなし・感謝せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, '是われら敬虔と謹嚴とを盡して、安らかに靜に一生を過さん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, '斯くするは美事にして、我らの救主なる神の御意に適ふことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, '神は凡ての人の救はれて、眞理を悟るに至らんことを欲し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'それ神は唯一なり、また神と人との間の中保も唯一にして、人なるキリスト・イエス是なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, '彼は己を與へて凡ての人の贖價となり給へり、時 至りて證せらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, '我これが爲に立てられて宣傳者となり、使徒となり(我は眞を言ひて虚僞を言はず)また信仰と眞とをもて異邦人を教ふる教師となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'これ故にわれ望む、男は怒らず爭はず、何れの處にても潔き手をあげて祈らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'また女は恥を知り、愼みて宜しきに合ふ衣にて己を飾り、編みたる頭髮と金と眞珠と價 貴き衣とを飾とせず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, '善き業をもて飾とせんことを。これ神を敬はんと公言する女に適へる事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, '女は凡てのこと從順にして靜に道を學ぶべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'われ女の教ふることと男の上に權を執ることとを許さず、ただ靜にすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'それアダムは前に造られ、エバは後に造られたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'アダムは惑されず、女は惑されて罪に陷りたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, '然れど女もし愼みて信仰と愛と潔とに居らば、子を生むことに因りて救はるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, '『人もし監督の職を慕はば、これよき業を願ふなり』とは、信ずべき言なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'それ監督は責むべき所なく、一人の妻の夫にして、自ら制し、愼み、品行 正しく、旅人を懇ろに待し、能く教へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, '酒を嗜まず、人を打たず、寛容にし、爭はず、金を貪らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, '善く己が家を理め、謹嚴にして子女を從順ならしむる者たるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(人もし己が家を理むることを知らずば、爭でが神の教會を扱ふことを得ん)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'また新に教に入りし者ならざるべし、恐らくは傲慢になりて惡魔と同じ審判を受くるに至らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, '外の人にも令聞ある者たるべし、然らずば誹謗と惡魔の羂とに陷らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, '執事もまた同じく謹嚴にして、言を二つにせず、大酒せず、恥づべき利をとらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, '潔き良心をもて信仰の奧義を保つものたるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'まづ彼らを試みて責むべき所なくば、執事の職に任ずべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, '女もまた謹嚴にして人を謗らず、自ら制して凡ての事に忠實なる者たるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, '執事は一人の妻の夫にして、子女と己が家とを善く理むる者たるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, '善く執事の職をなす者は良き地位を得、かつキリスト・イエスに於ける信仰につきて大なる勇氣を得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'われ速かに汝に往かんことを望めど、今これらの事を書きおくるは、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, '若し遲からんとき、人の如何に神の家に行ふべきかを汝に知らしめん爲なり。神の家は活ける神の教會なり、眞理の柱、眞理の基なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, '實に大なるかな、敬虔の奧義『キリストは肉にて顯され、靈にて義とせられ、御使たちに見られ、もろもろの國人に宣傳へられ、世に信ぜられ、榮光のうちに上げられ給へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'されど御靈あきらかに、或 人の後の日に及びて、惑す靈と惡鬼の教とに心を寄せて、信仰より離れんことを言ひ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'これ虚僞をいふ者の僞善に由りてなり。彼らは良心を燒金にて烙かれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, '婚姻するを禁じ、食を斷つことを命ず。されど食は神の造り給へる物にして、信じかつ眞理を知る者の感謝して受くべきものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, '神の造り給へる物はみな善し、感謝して受くる時は棄つべき物なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'そは神の言と祈とによりて潔めらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, '汝もし此 等のことを兄弟に教へば、信仰と汝の從ひたる善き教との言にて養はるる所のキリスト・イエスの良き役者たるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'されど妄なる談と老いたる女の昔話とを捨てよ、また自ら敬虔を修行せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, '體の修行もいささかは益あれど、敬虔は今の生命と後の生命との約束を保ちて凡ての事に益あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'これ信ずべく正しく受くべき言なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, '我らは之がために勞しかつ苦心す、そは我ら凡ての人、殊に信ずる者の救主なる活ける神に望を置けばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, '汝これらの事を命じかつ教へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'なんぢ年 若きをもて人に輕んぜらるな、反つて言にも、行状にも、愛にも、信仰にも、潔にも、信者の模範となれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'わが到るまで、讀むこと勸むること教ふる事に心を用ひよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'なんぢ長老たちの按手を受け、預言によりて賜はりたる賜物を等閑にすな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'なんぢ心を傾けて此 等のことを專ら務めよ。汝の進歩の明かならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'なんぢ己とおのれの教とを愼みて此 等のことに怠るな、斯くなして己と聽く者とを救ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, '老人を譴責すな、反つて之を父のごとく勸め、若き人を兄弟の如くに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, '老いたる女を母の如くに勸め、若き女を姉妹の如くに全き貞潔をもて勸めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, '寡婦のうちの眞の寡婦を敬へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'されど寡婦に子もしくは孫あらば、彼ら先づ己の家に孝を行ひて親に恩を報ゆることを學ぶべし。これ神の御意にかなふ事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, '眞の寡婦にして獨殘りたる者は、望を神におきて、夜も晝も絶えず願と祈とを爲す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'されど佚樂を放恣にする寡婦は、生けりと雖も死にたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'これらの事を命じて彼らに責むべき所なからしめよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, '人もし其の親族、殊に己が家族を顧みずば、信仰を棄てたる者にて、不 信者よりも更に惡しきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, '六十歳 以下の寡婦は寡婦の籍に記すべからず、記すべきは一人の夫の妻たりし者にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, '善き業の聲聞あり、或は子女をそだて、或は旅人を宿し、或は聖徒の足を洗ひ、或は惱める者を助くる等、もろもろの善き業に從ひし者たるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, '若き寡婦は籍に記すな、彼らキリストに背きて心 亂るる時は、嫁ぐことを欲し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, '初の誓約を棄つるに因りて批難を受くべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, '彼 等はまた懶惰に流れて家々を遊びめぐる、啻に懶惰なるのみならず、言 多くして徒事にたづさはり、言ふまじき事を言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'されば若き寡婦は嫁ぎて子を生み、家を理めて敵に少しにても謗るべき機を與へざらんことを我は欲す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, '彼らの中には既に迷ひてサタンに從ひたる者あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, '信者たる女もし其の家に寡婦あらば、自ら之を助けて教會を煩はすな。これ眞の寡婦を教會の助けん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, '善く治むる長老、殊に言と教とをもて勞する長老を一層 尊ぶべき者とせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, '聖書に『穀物を碾す牛に口籠を繋くべからず』また『勞動人のその價を得るは相應しきなり』と云へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, '長老に對する訴訟は二三人の證人なくば受くべからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, '罪を犯せる者をば衆の前にて責めよ、これ他の人をも懼れしめんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'われ神とキリスト・イエスと選ばれたる御使たちとの前にて嚴かに汝に命ず、何事をも偏り行はず、偏頗なく此 等のことを守れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, '輕々しく人に手を按くな、人の罪に與るな、自ら守りて潔くせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, '今よりのち水のみを飮まず、胃のため、又しばしば病に罹る故に、少しく葡萄酒を用ひよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, '或 人の罪は明かにして先だちて審判に往き、或 人の罪は後にしたがふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, '斯くのごとく善き業も明かなり、然らざる者も遂には隱るること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'おほよそ軛の下にありて奴隷たる者は、おのれの主人を全く尊ぶべき者とすべし。これ神の名と教との譏られざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, '信者たる主人を有てる者は、その兄弟なるに因りて之を輕んぜず、反つて彌 増々これに事ふべし。その益を受くる主人は信者にして愛せらるる者なればなり。汝これらの事を教へかつ勧めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'もし異なる教を傳へて、健全なる言すなはち我らの主イエス・キリストの言と、敬虔にかなふ教とを肯はぬ者あらば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'その人は傲慢にして何をも知らず、ただ議論と言爭とにのみ耽るなり、之によりて嫉妬・爭鬪・惡しき念おこり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'また心 腐りて眞理をはなれ、敬虔を利 益の道とおもふ者の爭論おこるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'されど足ることを知りて敬虔を守る者は、大なる利 益を得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, '我らは何をも携へて世に來らず、また何をも携へて世を去ること能はざればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'ただ衣食あらば足れりとせん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'されど富まんと欲する者は、誘惑と羂、また人を滅亡と沈淪とに溺らす愚にして害ある各樣の慾に陷るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'それ金を愛するは諸般の惡しき事の根なり、ある人々これを慕ひて信仰より迷ひ、さまざまの痛をもて自ら己を刺しとほせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, '神の人よ、なんぢは此 等のことを避けて、義と敬虔と信仰と愛と忍耐と柔和とを追ひ求め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, '信仰の善き戰闘をたたかへ、永遠の生命をとらへよ。汝これが爲に召を蒙り、また多くの證人の前にて善き言明をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'われ凡ての物を生かしたまふ神のまへ、及びポンテオ・ピラトに向ひて善き言明をなし給ひしキリスト・イエスの前にて汝に命ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, '汝われらの主イエス・キリストの現れたまふ時まで汚點なく責むべき所なく、誡命を守れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, '時いたらば幸福なる唯一の君主、もろもろの王の王、もろもろの主の主、これを顯し給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, '主は唯ひとり不 死を保ち近づきがたき光に住み、人の未だ見ず、また見ること能はぬ者なり。願はくは尊貴と限りなき權力と彼にあらんことを、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, '汝この世の富める者に命ぜよ。高ぶりたる思をもたず、定なき富をたのまずして、唯われらを樂しませんとて萬の物を豐に賜ふ神に依頼み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, '善をおこなひ、善き業に富み、惜みなく施し、分け與ふることを喜び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'かくて己のために善き基を蓄へ、未來の備をなして眞の生命を捉ふることを爲よと。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'テモテよ、なんぢ委ねられたる事を守り、妄なる虚しき物語、また僞りて知識と稱ふる反對論を避けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'ある人々この知識を裝ひて信仰より外れたり。願はくは御惠なんじと偕に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, '神の御意により、キリスト・イエスにある生命の約束に循ひて、キリスト・イエスの使徒になれるパウロ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, '書を我が愛する子テモテに贈る。願はくは父なる神および我らの主キリスト・イエスより賜ふ、恩惠と憐憫と平安と汝に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'われ夜も晝も祈の中に絶えず汝を思ひて、わが先祖に效ひ清き良心をもて事ふる神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, '我なんぢの涙を憶え、わが歡喜の滿ちん爲に汝を見んことを欲す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, '是なんぢに在る虚僞なき信仰をおもひ出すに因りてなり。その信仰の曩に汝の祖母ロイス及び母ユニケに宿りしごとく、汝にも然るを確信す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'この故に、わが按手に因りて汝の内に得たる神の賜物をますます熾にせんことを勸む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'そは神の我らに賜ひたるは、臆する靈にあらず、能力と愛と謹愼との靈なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'されば汝われらの主の證をなす事と、主の囚人たる我とを恥とすな、ただ神の能力に隨ひて福音のために我とともに苦難を忍べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, '神は我らを救ひ聖なる召をもて召し給へり。是われらの行爲に由るにあらず、神の御旨にて創世の前にキリスト・イエスをもて我らに賜ひし恩惠に由るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'この恩惠は今われらの救主キリスト・イエスの現れ給ふに因りて顯れたり。彼は死をほろぼし、福音をもて生命と朽ちざる事とを明かにし給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, '我はこの福音のために立てられて宣傳者・使徒・教師となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, '之がために我これらの苦難に遭ふ。されど之を恥とせず、我わが依頼む者を知り、且わが委ねたる者を、かの日に至るまで守り得給ふことを確信すればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, '汝キリスト・イエスにある信仰と愛とをもて我より聽きし健全なる言の模範を保ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'かつ委ねられたる善きものを我等のうちに宿りたまふ聖 靈に頼りて守るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'アジヤに居る者みな我を棄てしは汝の知る所なり、その中にフゲロとヘルモゲネとあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, '願はくは主オネシポロの家に憐憫を賜はんことを。彼はしばしば我を慰め、又わが鎖を恥とせず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'そのロマに居りし時には懇ろに尋ね來りて、遂に逢ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, '願はくは主かの日にいたり主の憐憫を彼に賜はんことを、彼がエペソにて我に事へしことの如何ばかりなりしかは、汝の能く知るところなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'わが子よ、汝キリスト・イエスにある恩惠によりて強かれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, '且おほくの證人の前にて、我より聽きし所のことを他の者に教へ得る忠實なる人々に委ねよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, '汝キリスト・イエスのよき兵卒として我とともに苦難を忍べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, '兵卒を務むる者は生活のために纏はるる事なし、これ募れる者を喜ばせんとすればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, '技を競ふ者、もし法に隨ひて競はずば冠冕を得ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, '勞する農夫まづ實の分配を得べきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, '汝わが言ふ所をおもへ、主なんぢに凡ての事に就きて悟を賜はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'わが福音に云へる如く、ダビデの裔にして死人の中より甦へり給へるイエス・キリストを憶えよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, '我はこの福音のために苦難を受けて惡人のごとく繋がるるに至れり、されど神の言は繋がれたるにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'この故に我えらばれたる者のために凡ての事を忍ぶ。これ彼 等をして永遠の光榮と共にキリスト・イエスによる救を得しめんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'ここに信ずべき言あり『我等もし彼と共に死にたる者ならば、彼と共に生くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'もし耐へ忍ばば、彼と共に王となるべし。若し彼を否まば、彼も我らを否み給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, '我らは眞實ならずとも、彼は絶えず眞實にましませり、彼は己を否み給ふこと能はざればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, '汝かれらに此 等のことを思ひ出さしめ、かつ言爭する事なきやう神の前にて嚴かに命ぜよ、言爭は益なくして聞く者を滅亡に至らしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'なんぢ眞理の言を正しく教へ、恥づる所なき勞動人となりて、神の前に錬達せる者とならんことを勵め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'また妄なる虚しき物語を避けよ。かかる者はますます不 敬虔に進み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'その言は脱疽のごとく腐れひろがるべし、ヒメナオとピレトとは斯くのごとき者の中にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, '彼らは眞理より外れ、復活ははや過ぎたりと云ひて、或 人々の信仰を覆へすなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'されど神の据ゑ給へる堅き基は立てり、之に印あり、記して曰ふ『主おのれの者を知り給ふ』また『凡て主の名を稱ふる者は不義を離るべし』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, '大なる家の中には金 銀の器あるのみならず、木また土の器もあり、貴きに用ふるものあり、また賤しきに用ふるものあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, '人もし賤しきものを離れて自己を潔よくせば貴きに用ひらるる器となり、淨められて主の用に適ひ、凡ての善き業に備へらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, '汝わかき時の慾を避け、主を清き心にて呼び求むる者とともに、義と信仰と愛と平和とを追ひ求めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, '愚なる無學の議論を棄てよ、これより分爭の起るを知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, '主の僕は爭ふべからず、凡ての人に優しく能く教へ忍ぶことをなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, '逆ふ者をば柔和をもて戒むべし、神あるひは彼らに悔改むる心を賜ひて眞理を悟らせ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, '彼ら一度は惡魔に囚はれたれど、醒めてその羂をのがれ、神の御心を行ふに至らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'されど汝これを知れ、末の世に苦しき時きたらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, '人々おのれを愛する者・金を愛する者・誇るもの・高ぶる者・罵るもの・父 母に逆ふもの・恩を忘るる者・潔からぬ者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, '無情なる者・怨を解かぬ者・譏る者・節制なき者・殘刻なる者・善を好まぬ者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, '友を賣る者・放縱なる者・傲慢なる者・神よりも快樂を愛する者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, '敬虔の貌をとりてその徳を捨つる者とならん、斯かる類の者を避けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, '彼らの中には人の家に潜り入りて愚なる女を虜にする者あり、斯くせらるる女は罪を積み重ねて各樣の慾に引かれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, '常に學べども眞理を知る知識に至ること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, '彼の者らはヤンネとヤンブレとがモーセに逆ひし如く、眞理に逆ふもの、心の腐れたる者、また信仰につきて棄てられたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'されど此の上になほ進むこと能はじ、そはかの二人のごとく彼らの愚なる事も亦すべての人に顯るべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, '汝は我が教誨・品行・志望・信仰・寛容・愛・忍耐・迫害、および苦難を知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'またアンテオケ、イコニオム、ルステラにて起りし事、わが如何なる迫害を忍びしかを知る。主は凡てこれらの中より我を救ひ出したまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, '凡そキリスト・イエスに在りて敬虔をもて一生を過さんと欲する者は迫害を受くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, '惡しき人と人を欺く者とは、ますます惡にすすみ、人を惑し、また人に惑されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'されど汝は學びて確信したる所に常に居れ。なんぢ誰より之を學びしかを知り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'また幼き時より聖なる書を識りし事を知ればなり。この書はキリスト・イエスを信ずる信仰によりて救に至らしむる知慧を汝に與へ得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, '聖書はみな神の感動によるものにして、教誨と譴責と矯正と義を薫陶するとに益あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'これ神の人の全くなりて諸般の善き業に備を全うせん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'われ神の前また生ける者と死にたる者とを審かんとし給ふキリスト・イエスの前にて、その顯現と御國とをおもひて嚴かに汝に命ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'なんぢ御言を宣傳へよ、機を得るも機を得ざるも常に勵め、寛容と教誨とを盡して責め、戒め、勸めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, '人々 健全なる教に堪へず、耳 痒くして私慾のまにまに己がために教師を増し加へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, '耳を眞理より背けて昔話に移る時 來らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'されど汝は何事にも愼み、苦難を忍び、傳道者の業をなし、なんぢの職を全うせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, '我は今 供物として血を灑がんとす、わが去るべき時は近づけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'われ善き戰鬪をたたかひ、走るべき道程を果し、信仰を守れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, '今よりのち義の冠冕わが爲に備はれり。かの日に至りて正しき審判 主なる主、これを我に賜はん、啻に我のみならず、凡てその顯現を慕ふ者にも賜ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'なんぢ勉めて速かに我に來れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'デマスは此の世を愛し、我を棄ててテサロニケに往き、クレスケンスはガラテヤに、テトスはダルマテヤに往きて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, '唯ルカのみ我とともに居るなり。汝マルコを連れて共に來れ、彼は職のために我に益あればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, '我テキコをエペソに遣せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, '汝きたる時わがトロアスにてカルポの許に遺し置きたる外衣を携へきたれ、また書物、殊に羊皮紙のものを携へきたれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, '金 細工人アレキサンデル大に我を惱せり。主はその行爲に隨ひて彼に報いたまふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, '汝もまた彼に心せよ、かれは甚だしく我らの言に逆ひたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'わが始の辯明のとき誰も我を助けず、みな我を棄てたり、願はくはこの罪の彼らに歸せざらんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'されど主われと偕に在して我を強めたまへり。これ我によりて宣教の全うせられ、凡ての異邦人のこれを聞かん爲なり。而して我は獅子の口より救ひ出されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'また主は我を凡ての惡しき業より救ひ出し、その天の國に救ひ入れたまはん。願はくは榮光 世々 限りなく彼にあらん事を、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, '汝プリスカ及びアクラ、またオネシポロの家に安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'エラストはコリントに留れり。トロピモは病ある故に我かれをミレトに遺せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'なんぢ勉めて冬のまへに我に來れ、ユブロ、プデス、リノス、クラウデヤ、及び凡ての兄弟、なんぢに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, '願はくは主なんぢの靈と偕に在し、御惠なんぢらと偕に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, '神の僕またイエス・キリストの使徒パウロ――我が使徒となれるは、永遠の生命の望に基きて神の選民の信仰を堅うし、また彼らを敬虔にかなふ眞理を知る知識に至らしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, '僞りなき神は、創世の前に、この生命を約束し給ひしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, '時いたりて御言を宣教にて顯さんとし、その宣教を我らの救主たる神の命令をもて我に委ねたまへり。――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'われ書を同じ信仰によりて我が眞實の子たるテトスに贈る。願はくは父なる神および我らの救主キリスト・イエスより賜ふ恩惠と平安と、汝にあらんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'わが汝をクレテに遣し置きたる故は、汝をして缺けたる所を正し、且わが命ぜしごとく町々に長老を立てしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, '長老は責むべき所なく、一人の女の夫にして、子女もまた放蕩をもて訴へらるる事なく、服從せぬことなき信者たるべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'それ監督は神の家 司なれば、責むべき所なく、放縱ならず、輕々しく怒らず、酒を嗜まず、人を打たず、恥づべき利を取らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, '反つて旅人を懇ろに待ひ、善を愛し、謹愼あり、正しく潔く節制にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, '教に適ふ信ずべき言を守る者たるべし。これ健全なる教をもて人を勸め、かつ言ひ逆ふ者を言ひ伏することを得んためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, '服從せず、虚しき事をかたり、人の心を惑す者おほし、殊に割禮ある者のうちに多し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, '彼らの口を箝がしむべし、彼らは恥づべき利を得んために、教ふまじき事を教へて全家を覆へすなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'クレテ人の中なる或る預言者いふ『クレテ人は常に虚僞をいふ者、あしき獸、また懶惰の腹なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'この證は眞なり。されば汝きびしく彼らを責めよ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, '彼らがユダヤ人の昔話と眞理を棄てたる人の誡命とに心を寄することなく、信仰を健全にせん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, '潔き人には凡ての物きよく、汚れたる人と不 信者とには一つとして潔き物なし、彼らは既に心も良心も汚れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'みづから神を知ると言ひあらはせど、其の行爲にては神を否む。彼らは憎むべきもの、服はぬ者、すべての善き業に就きて棄てられたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'されど汝は健全なる教に適ふことを語れ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, '老人には自ら制することと謹嚴と謹愼とを勸め、また信仰と愛と忍耐とに健全ならんことを勸めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, '老いたる女にも同じく、清潔にかなふ行爲をなし、人を謗らず、大酒の奴隷とならず、善き事を教ふる者とならんことを勸めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'かつ彼 等をして若き女に夫を愛し、子を愛し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, '謹愼と貞操とを守り、家の務をなし、仁慈をもち、己が夫に服はんことを教へしめよ。これ神の言の汚されざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, '若き人にも同じく謹愼を勸め、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'なんぢ自ら凡ての事につきて善き業の模範を示せ。教をなすには邪曲なきことと謹嚴と、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, '責むべき所なき健全なる言とを以てすべし。これ逆ふ者をして我らの惡を言ふに由なく、自ら恥づる所あらしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, '奴隷には己が主人に服ひ、凡ての事において之を喜ばせ、之に言ひ逆はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, '物を盜まず、反つて全き忠信を顯すべきことを勸めよ。これ凡ての事において我らの救主なる神の教を飾らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, '凡ての人に救を得さする神の恩惠は既に顯れて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, '不 敬虔と世の慾とを棄てて謹愼と正義と敬虔とをもて此の世を過し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, '幸福なる望、すなはち大なる神、われらの救主イエス・キリストの榮光の顯現を待つべきを我らに教ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'キリストは我等のために己を與へたまへり。是われらを諸般の不法より贖ひ出して、善き業に熱心なる特選の民を己がために潔めんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'なんぢ全き權威をもて此 等のことを語り、勸め、また責めよ。なんぢ人に輕んぜらるな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, '汝かれらに司と權威ある者とに服し、かつ從ひ、凡ての善き業をおこなふ備をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, '人を謗らず、爭はず、寛容にし、常に柔和を凡ての人に顯すべきことを思ひ出させよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, '我らも前には愚なるもの、順はぬもの、迷へる者、さまざまの慾と快樂とに事ふるもの、惡意と嫉妬とをもて過すもの、憎むべき者、また互に憎み合ふ者なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'されど我らの救主なる神の仁慈と、人を愛したまふ愛との顯れしとき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, '我らの行ひし義の業にはよらで、唯その憐憫により、更生の洗と、我らの救主イエス・キリストをもて豐に注ぎたまふ聖 靈による維新とにて、我らを救ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, '我らの行ひし義の業にはよらで、唯その憐憫により、更生の洗と、我らの救主イエス・キリストをもて豐に注ぎたまふ聖 靈による維新とにて、我らを救ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'これ我らが其の恩惠によりて義とせられ、永遠の生命の望にしたがひて世嗣とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'この言は信ずべきなれば、我なんぢが此 等につきて確證せんことを欲す。神を信じたる者をして愼みて善き業を務めしめん爲なり。かくするは善き事にして人に益あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'されど愚なる議論・系圖・爭鬪、また律法に就きての分爭を避けよ。これらは益なくして空しきものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, '異端の者をば一度もしくは二度、訓戒して後これを棄てよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'かかる者は汝の知るごとく、邪曲にして自ら罪を認めつつ尚これを犯すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, '我アルテマス或はテキコを汝に遣さん、その時なんぢ急ぎてニコポリなる我がもとに來れ。われ彼處にて冬を過さんと定めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, '教法師ゼナス及びアポロを懇ろに送りて、乏しき事なからしめよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'かくて我らの伴侶も善き業を務めて必要を資けんことを學ぶべし、これ果を結ばぬ事なからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, '我と偕に居る者みな汝に安否を問ふ。信仰に在りて我らを愛する者に安否を問へ。願はくは御惠、なんぢら凡ての者と偕にあらん事を。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'キリスト・イエスの囚人たるパウロ及び兄弟テモテ、書を我らが愛する同勞者ピレモン、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, '我らの姉妹アピヤ、我らと共に戰鬪をなせるアルキポ及び汝の家にある教會に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, '願はくは我らの父なる神および主イエス・キリストより賜ふ恩惠と平安と、汝らに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'われ祈るとき常に汝をおぼえて我が神に感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'これ主イエスと凡ての聖徒とに對する汝の愛と信仰とを聞きたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, '願ふところは、汝の信仰の交際の活動により、人々われらの中なる凡ての善き業を知りて、榮光をキリストに歸するに至らんことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, '兄弟よ、我なんぢの愛によりて大なる勸喜と慰安とを得たり。聖徒の心は汝によりて安んぜられたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'この故に、われキリストに在りて、汝になすべき事を聊かも憚らず命じ得れど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'むしろ愛の故によりて汝にねがふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, '既に年 老いて今はキリスト・イエスの囚人となれる我パウロ、縲絏の中にて生みし我が子オネシモの事をなんぢに願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'かれ前には汝に益なき者なりしが、今は汝にも我にも益ある者となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, '我かれを汝に歸す、かれは我が心なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, '我は彼をわが許に留めおきて、我が福音のために縲絏にある間、なんぢに代りて我に事へしめんと欲したれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'なんぢの承諾を經ずして斯くするを好まざりき、是なんぢの善の止むを得ざるに出でずして心より出でんことを欲したればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, '彼が暫時なんぢを離れしは、或は汝かれを永遠に保ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'もはや奴隷の如くせず、奴隷に勝りて愛する兄弟の如くせん爲なりしやも知るべからず。我は殊に彼を愛す、まして汝は肉によりても主によりても、之を愛せざる可けんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, '汝もし我を友とせば、請ふ、われを納るるごとく彼を納れよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, '彼もし汝に不義をなし、または汝に負債あらば、之を我に負はせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, '我パウロ手づから之を記す、われ償はん、汝われに身を以て償ふべき負債あれど、我これを言はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, '兄弟よ、請ふ、なんぢ主に在りて我に益を得させよ、キリストに在りて我が心を安んぜよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, '我なんぢの從順を確信して之を書き贈る。わが言ふところに勝りて汝の行はんことを知るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, '而して我がために宿を備へよ、我なんぢらの祈により、遂に我が身の汝らに與へられんことを望めばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'キリスト・イエスに在りて我とともに囚人となれるエパフラス、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, '及び我が同勞者マルコ、アリスタルコ、デマス、ルカ皆なんぢに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, '願はくは主イエス・キリストの恩惠、なんぢらの靈と偕にあらんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, '神むかしは預言者 等により、多くに分ち、多くの方法をもて先祖たちに語り給ひしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'この末の世には御子によりて、我らに語り給へり。神は曾て御子を立てて萬の物の世嗣となし、また御子によりて諸般の世界を造り給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, '御子は神の榮光のかがやき、神の本質の像にして、己が權能の言をもて萬の物を保ちたまふ。また罪の潔をなして、高き處にある稜威の右に坐し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'その受け給ひし名の御使の名に勝れるごとく、御使よりは更に勝る者となり給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, '神は孰の御使に曾て斯くは言ひ給ひしぞ『なんぢは我が子なり、われ今日なんぢを生めり』と。また『われ彼の父となり、彼わが子とならん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'また初子を再び世に入れ給ふとき『神の凡ての使は之を拜すべし』と言ひ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'また御使たちに就きては『神は、その使たちを風となし、その事ふる者を焔となす』と言ひ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'されど御子に就きては『神よ、なんじの御座は世々 限りなく、汝の國の杖は正しき杖なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'なんぢは義を愛し、不法をにくむ。この故に神なんぢの神は歡喜の油を、汝の友に勝りて汝にそそぎ給へり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'また『主よ、なんぢ太初に地の基を置きたまへり、天も御手の業なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'これらは滅びん、されど汝は常に存へたまはん。これらはみな衣のごとく舊びん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, '而して汝これらを袍のごとく疊み給はん、これらは衣のごとく變らん。されど汝はかはり給ふことなく汝の齡は終らざるなり』と言ひたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, '又いづれの御使に曾て斯くは言ひ給ひしぞ『われ汝の仇を汝の足臺となすまでは、我が右に坐せよ』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, '御使はみな事へまつる靈にして、救を嗣がんとする者のために職を執るべく遣されたる者にあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'この故に我ら聞きし所をいよいよ篤く愼むべし、恐らくは流れ過ぐる事あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, '若し御使によりて語り給ひし言すら堅くせられて、咎と不 從順とみな正しき報を受けたらんには、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, '我ら斯くのごとき大なる救を等閑にして爭でか遁るることを得ん。この救は初め主によりて語り給ひしものにして、聞きし者ども之を我らに確うし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, '神また徴と不思議とさまざまの能力ある業と、御旨のままに分ち與ふる聖 靈とをもて證を加へたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'それ神は我らの語るところの來らんとする世界を、御使たちには服はせ給はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, '或 篇に人 證して言ふ『人は如何なる者なれば、之を御心にとめ給ふか。人の子は如何なる者なれば、之を顧み給ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, '汝これを御使よりも少しく卑うし、光榮と尊貴とを冠らせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, '萬の物をその足の下の服はせ給へり』と。既に萬の物を之に服はせ給ひたれば、服はぬものは一つだに殘さるる事なし。されど今もなほ我らは萬の物の之に服ひたるを見ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'ただ御使よりも少しく卑くせられしイエスの、死の苦難を受くるによりて榮光と尊貴とを冠らせられ給へるを見る。これ神の恩惠によりて萬民のために死を味ひ給はんとてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'それ多くの子を光榮に導くに、その救の君を苦難によりて全うし給ふは、萬の物の歸するところ、萬の物を造りたまふ所の者に相應しき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, '潔めたまふ者も、潔めらるる者も、皆ただ一つより出づ。この故に彼らを兄弟と稱ふるを恥とせずして言ひ給ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, '『われ御名を我が兄弟たちに告げ、集會の中にて汝を讃め歌はん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'また『われ彼に依頼まん』又『視よ、我と神の我に賜ひし子 等とは......』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, '子 等はともに血肉を具ふれば、主もまた同じく之を具へ給ひしなり。これは死の權力を有つもの、即ち惡魔を死によりて亡し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'かつ死の懼によりて生涯、奴隷となりし者どもを解放ち給はんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, '實に主は御使を扶けずしてアブラハムの裔を扶けたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'この故に神の事につきて憐憫ある忠實なる大 祭司となりて、民の罪を贖はんために、凡ての事において兄弟の如くなり給ひしは宜なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, '主は自ら試みられて苦しみ給ひたれば、試みられるる者を助け得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'されば共に天の召を蒙れる聖なる兄弟よ、我らが言ひあらはす信仰の使徒たり大 祭司たるイエスを思ひ見よ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, '彼の己を立て給ひし者に忠實なるは、モーセが神の全家に忠實なりしが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, '家を造る者の家より勝りて尊ばるる如く、彼もモーセに勝りて大なる榮光を受くるに相應しき者とせられ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, '家は凡て之を造る者あり、萬の物を造り給ひし者は神なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'モーセは後に語り傳へられんと爲ることの證をせんために、僕として神の全家に忠實なりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'キリストは子として神の家を忠實に掌どり給へり。我等もし確信と希望の誇とを終まで堅く保たば、神の家なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'この故に聖 靈の言ひ給ふごとく『今日なんぢら神の聲を聞かば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'その怒を惹きし時のごとく、荒野の嘗試の日のごとく、こころを頑固にするなかれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, '彼處にて汝らの先祖たちは我をこころみて驗し、かつ四十 年の間わが業を見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'この故に我この代の人を憤ほりて云へり、「彼らは常に心まよい、わが途を知らざりき」と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'われ怒をもて「彼らは、我が休に入るべからず」と誓へり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, '兄弟よ、心せよ、恐らくは汝 等のうち活ける神を離れんとする不 信仰の惡しき心を懷く者あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, '汝 等のうち誰も罪の誘惑によりて頑固にならぬやう、今日と稱ふる間に日々 互に相 勸めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'もし始の確信を終まで堅く保たば、我らはキリストに與る者となるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'それ『今日なんじら神の聲を聞かば、その怒を惹きし時のごとく、こころを頑固にするなかれ』と云へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, '然れば聞きてなほ怒を惹きし者は誰なるか、モーセによりてエジプトを出でし凡ての人にあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'また四十 年のあひだ、神は誰に對して憤ほり給ひしか、罪を犯してその死屍を荒野に横たへし人々にあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, '又かれらは我が安息に入るべからずとは、誰に對して誓ひ給ひしか、不 從順なる者にあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, '之によりて見れば、彼らの入ること能はざりしは、不 信仰によりてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, '然れば我ら懼るべし、その安息に入るべき約束はなほ遺れども、恐らくは汝らの中これに達せざる者あらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'それは彼らのごとく我らも善き音信を傳へられたり、然れど彼らには聞きし所の言 益なかりき。聞くもの之に信仰をまじへざりしに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'われら信じたる者は、かの休に入ることを得るなり。『われ怒をもて「彼らは、わが休に入るべからず」と誓へり』と云ひ給ひしが如し。されど世の創より御業は既に成れるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, '或 篇に七日めに就きて斯く云へり『七日めに神その凡ての業を休みたまへり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'また茲に『かれらは、我が休に入るべからず』と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, '然れば之に入るべき者なほ在り、曩に善き音信を傳へられし者らは、不 從順によりて入ることを得ざりしなれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, '久しきを經てのち復、日を定めダビデによりて『今日』と言ひ給ふ。曩に記したるが如し。曰く『今日なんじら神の聲を聞かば、こころを頑固にするなかれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, '若しヨシュア既に休を彼らに得しめしならば、神はその後、ほかの日につきて語り給はざりしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, '然れば神の民の爲になほ安息は遺れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, '既に神の休に入りたる者は、神のその業を休み給ひしごとく、己が業を休めり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'されば我等はこの休に入らんことを務むべし、是かの不 從順の例にならひて誰も墮つることなからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, '神の言は生命あり、能力あり、兩刃の劍よりも利くして、精神と靈魂、關節と骨髓を透して之を割ち、心の念と志望とを驗すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'また造られたる物に一つとして神の前に顯れぬはなし、萬の物は我らが係れる神の目のまへに裸にて露るるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, '我等には、もろもろの天を通り給ひし偉なる大 祭司、神の子イエスあり。然れば我らが言ひあらはす信仰を堅く保つべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, '我らの大 祭司は我らの弱を思ひ遣ること能はぬ者にあらず、罪を外にして凡ての事、われらと等しく試みられ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'この故に我らは憐憫を受けんが爲、また機に合ふ助となる惠を得んがために、憚らずして惠の御座に來るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, '凡そ大 祭司は人の中より選ばれ、罪のために供物と犧牲とを献げんとて、人にかはりて神に事ふることを任ぜらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, '彼は自らも弱に纒はるるが故に、無知なるもの、迷へる者を思ひ遣ることを得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, '之によりて民のために爲すごとく、また己のためにも罪に就きて献物をなさざるべからず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, '又この貴き位はアロンのごとく神に召さるるにあらずば、誰も自ら之を取る者なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, '斯くの如くキリストも己を崇めて自ら大 祭司となり給はず。之に向ひて『なんじは我が子なり、われ今日なんじを生めり』と語り給ひし者、これを立てたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'また他の篇に『なんじは永遠にメルキゼデクの位に等しき祭司たり』と言ひ給へるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'キリストは肉體にて在ししとき、大なる叫と涙とをもて、己を死より救ひ得る者に祈と願とを献げ、その恭敬によりて聽かれ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, '彼は御子なれど、受けし所の苦難によりて從順を學び、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'かつ全うせられたれば、凡て己に順ふ者のために永遠の救の原となりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, '神よりメルキゼデクの位に等しき大 祭司と稱へられ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, '之に就きて我ら多くの言ふべき事あれど、汝ら聞くに鈍くなりたれば釋き難し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'なんじら時を經ること久しければ、教師となるべき者なるに、今また神の言の初歩を人より教へられざるを得ず、汝らは堅き食物ならで乳を要する者となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'おほよそ乳を用ふる者は幼兒なれば、未だ義の言に熟せず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, '堅き食物は智力を練習して善惡を辨ふる成人の用ふるものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'この故に我らはキリストの教の初歩に止ることなく、再び死にたる行爲の悔改と神に對する信仰との基、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'また各樣のバプテスマと按手と、死人の復活と永遠の審判との教の基を置かずして完全に進むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, '神もし許し給はば、我ら之をなさん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, '一たび照されて天よりの賜物を味ひ、聖 靈に與る者となり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, '神の善き言と來世の能力とを味ひて後、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, '墮落する者は更にまた自ら神の子を十字架に釘けて肆し者とする故に、再びこれを悔改に立返らすること能はざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'それ地しばしば其の上に降る雨を吸ひ入れて耕す者の益となるべき作物を生ぜば、神より祝福を受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'されど茨と薊とを生ぜば、棄てられ、かつ詛に近く、その果ては焚かるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, '愛する者よ、われら斯くは語れど、汝らには更に善きこと、即ち救にかかはる事あるを深く信ず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, '神は不義に在さねば、汝らの勤勞と、前に聖徒につかへ、今もなほ之に事へて御名のために顯したる愛とを忘れ給ふことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, '我らは汝 等がおのおの終まで前と同じ勵をあらはして全き望を保ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, '怠ることなく、信仰と耐忍とをもて約束を嗣ぐ人々に效はんことを求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'それ神はアブラハムに約し給ふとき、指して誓ふべき己より大なる者なき故に、己を指して誓ひて言ひ給へり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, '『われ必ず、なんぢを惠み惠まん、なんぢを殖し殖さん』と、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, '斯くの如くアブラハムは耐へ忍びて約束のものを得たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'おほよそ人は己より大なる者を指して誓ふ、その誓はすべての爭論を罷むる保證たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'この故に神は約束を嗣ぐ者に御旨の變らぬことを充分に示さんと欲して誓を加へ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'これ神の謊ること能はぬ二つの變らぬものによりて、己の前に置かれたる希望を捉へんとて遁れたる我らに強き奨勵を與へん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'この希望は我らの靈魂の錨のごとく安全にして動かず、かつ幔の内に入る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'イエス我等のために前驅し、永遠にメルキゼデクの位に等しき大 祭司となりて、その處に入り給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, '此のメルキゼデクはサレムの王にて至高き神の祭司たりしが、王たちを破りて還るアブラハムを迎へて祝福せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'アブラハムは彼に凡ての物の十分の一を分け與へたり。その名を釋けば第一に義の王、次にサレムの王、すなはち平和の王なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, '父なく、母なく、系圖なく、齡の始なく、生命の終なく、神の子の如くにして限りなく祭司たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, '先祖アブラハム分捕物のうち十分の一、最も善き物を之に與へたれば、その人の如何に尊きかを思ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'レビの子 等のうち祭司の職を受くる者は、律法によりて、民すなはちアブラハムの腰より出でたる己が兄弟より、十分の一を取ることを命ぜらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'されど此の血脈にあらぬ彼は、アブラハムより十分の一を取りて約束を受けし者を祝福せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'それ小なる者の大なる者に祝福せらるるは論なき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'かつ此所にては死ぬべき者 十分の一を受くれども、彼處にては『活くるなり』と證せられた者これを受く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'また十分の一を受くるレビすら、アブラハムに由りて十分の一を納めたりと云ふも可なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'そはメルキゼデクのアブラハムを迎へし時に、レビはなほ父の腰に在りたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'もしレビの系なる祭司によりて全うせらるる事ありしならば(民は之によりて律法を受けたり)何ぞなほ他にアロンの位に等しからぬメルキゼデクの位に等しき祭司の起る必要あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, '祭司の易る時には律法も亦 必ず易るべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, '此 等のことは曾て祭壇に事へたることなき他の族に屬する者をさして云へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'それ我らの主のユダより出で給へるは明かにして、此の族につき、モーセは聊かも祭司に係ることを云はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, '又メルキゼデクのごとき他の祭司おこり、肉の誡命の法に由らず、朽ちざる生命の能力によりて立てられたれば、我が言ふ所いよいよ明かなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, '又メルキゼデクのごとき他の祭司おこり、肉の誡命の法に由らず、朽ちざる生命の能力によりて立てられたれば、我が言ふ所いよいよ明かなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'そは『なんぢは永遠にメルキゼデクの位に等しき祭司たり』と證せられ給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, '前の誡命は弱く、かつ益なき故に廢せられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(律法は何をも全うせざりしなり)更に優れたる希望を置かれたり、この希望によりて我らは神に近づくなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'かの人々は誓なくして祭司とせられたれども、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '彼は誓なくしては爲られず、誓をもて祭司とせられ給へり。即ち彼に就きて『主ちかひて悔い給はず、「なんじは永遠に祭司たり」』と言ひ給ひしが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'イエスは斯くも優れたる契約の保證となり給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'かの人々は死によりて永くその職に留ることを得ざる故に、祭司となりし者の數 多かりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'されど彼は永遠に在せば易ることなき祭司の職を保ちたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'この故に彼は己に頼りて神にきたる者のために執成をなさんとて常に生くれば、之を全く救ふこと得給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, '斯くのごとき大 祭司こそ我らに相應しき者なれ、即ち聖にして惡なく、穢なく、罪人より遠ざかり、諸般の天よりも高くせられ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, '他の大 祭司のごとく先づ己の罪のため、次に民の罪のために日々 犧牲を献ぐるを要し給はず、その一たび己を献げて之を成し給ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, '律法は弱みある人々を立てて大 祭司とすれども、律法の後なる誓の御言は、永遠に全うせられ給へる御子を大 祭司となせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, '今いふ所の要點は斯くのごとき大 祭司の我らにある事なり。彼は天にては稜威の御座の右に坐し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, '聖所および眞の幕屋に事へたまふ。この幕屋は人の設くるものにあらず、主の設けたまふ所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'おおよそ大 祭司の立てらるるは供物と犧牲とを献げん爲なり、この故に彼もまた献ぐべき物あるべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, '然るに若し地に在さば、既に律法に循ひて供物を献ぐる祭司 等あるによりて祭司とはなり給はざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, '彼らの事ふるは、天にある物の型と影となり。モーセが幕屋を建てんとする時に『愼め、山にて汝が示されたる式に效ひて凡ての物を造れ』との御告を受けしが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'されどキリストは更に勝れる約束に基きて立てられし勝れる契約の中保となりたれば、更に勝る職を受け給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'かつ初の契約もし虧くる所なくば、第二の契約を求むる事なかりしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, '然るに彼らを咎めて言ひ給ふ『主いひ給ふ「視よ、我イスラエルの家とユダの家とに、新しき契約を設くる日 來らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'この契約は我かれらの先祖の手を執りて、エジプトの地より導き出しし時に立てし所の如きにあらず、彼らは我が契約にとどまらず、我も彼らを顧みざりしなり」と主いひ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, '「されば、かの日の後に我がイスラエルの家と立つる契約は是なり」と主いひ給ふ。「われ我が律法を彼らの念に置き、そのこころに之を記さん、また我かれらの神となり、彼らは我が民とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, '彼らはまた各人その國人に、その兄弟に教へて、なんじ主を知れと言はざるべし。そは小より大に至るまで、皆われを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, '我もその不義を憐み、この後また其の罪を思ひ出でざるべし』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, '既に『新し』と言ひ給へば、初のものを舊しとし給へるなり、舊びて衰ふるものは、消失せんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, '初の契約には禮拜の定と世に屬する聖所とありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, '設けられたる幕屋あり、前なるを聖所と稱へ、その中に燈臺と案と供のパンとあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'また第二の幕の後に至 聖所と稱ふる幕屋あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'その中に金の香壇と金にて徧く覆ひたる契約の櫃とあり、この中にマナを納れたる金の壺と芽したるアロンの杖と契約の石碑とあり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, '櫃の上に榮光のケルビムありて贖罪所を覆ふ。これらの物に就きては、今 一々 言ふこと能はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, '此 等のもの斯く備りたれば、祭司たちは常に前なる幕屋に入りて禮拜をおこなふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'されど奧なる幕屋には、大 祭司のみ年に一度おのれと民との過失のために献ぐる血を携へて入るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, '之によりて聖 靈は前なる幕屋のなほ存するあひだ、至 聖所に入る道の未だ顯れざるを示し給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'この幕屋はその時のために設けられたる比喩なり、之に循ひて献げたる供物と犧牲とは、禮拜をなす者の良心を全うすること能はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, '此 等はただ食物・飮物さまざまの濯事などに係り、肉に屬する定にして、改革の時まで負せられたるのみ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, '然れどキリストは來らんとする善き事の大 祭司として來り、手にて造らぬ此の世に屬せぬ更に大なる全き幕屋を經て、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, '山羊と犢との血を用ひず、己が血をもて只 一たび至 聖所に入りて、永遠の贖罪を終へたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'もし山羊および牡牛の血、牝牛の灰などを穢れし者にそそぎて其の肉體を潔むることを得ば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'まして永遠の御靈により瑕なくして己を神に献げ給ひしキリストの血は、我らの良心を死にたる行爲より潔めて活ける神に事へしめざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'この故に彼は新しき契約の中保なり。これ初の契約の下に犯したる咎を贖ふべき死あるによりて、召されたる者に約束の永遠の嗣業を受けさせん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'それ遺言は必ず遺言 者の死を要す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, '遺言は遺言 者 死にてのち始めて效あり、遺言 者の生くる間は效なきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'この故に初の契約も血なくして立てしにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'モーセ律法に循ひて諸般の誡命をすべての民に告げてのち、犢と山羊との血また水と緋色の毛とヒソプとをとりて、書および凡ての民にそそぎて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, '『これ神の汝らに命じたまふ契約の血なり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'また同じく幕屋と祭のすべての器とに血をそそげり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'おほよそ律法によれば、萬のもの血をもて潔めらる。もし血を流すことなくば、赦さるることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'この故に天に在るものに象りたる物は此 等にて潔められ、天にある物は此 等に勝りたる犧牲をもて潔めらるべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'キリストは眞のものに象れる、手にて造りたる聖所に入らず、眞の天に入りて今より我等のために神の前にあらはれ給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'これ大 祭司が年ごとに他の物の血をもて聖所に入るごとく、屡次おのれを献ぐる爲にあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'もし然らずば世の創より以來しばしば苦難を受け給ふべきなり。然れど今、世の季にいたり己を犧牲となして罪を除かんために一たび現れたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, '一たび死ぬることと死にてのち審判を受くることとの人に定りたる如く、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'キリストも亦おほくの人の罪を負はんが爲に一たび献げられ、復 罪を負ふことなく、己を待 望む者に再び現れて救を得させ給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'それ律法は來らんとする善き事の影にして眞の形にあらねば、年毎にたえず献ぐる同じ犧牲にて、神にきたる者を何時までも全うすることを得ざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'もし之を得ば、禮拜をなす者、一たび潔められて復 心に罪を憶えねば、献ぐることを止めしならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, '然れど犧牲によりて、年ごとに罪を憶ゆるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'これ牡牛と山羊との血は罪を除くこと能はざるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'この故にキリスト世に來るとき言ひ給ふ『なんぢ犧牲と供物とを欲せず、唯わが爲に體を備へたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'なんぢ燔祭と罪祭とを悦び給はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'その時われ言ふ「神よ、我なんぢの御意を行はんとて來る」我につきて書の卷に録されたるが如し』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, '先には『汝いけにへと供物と燔祭と罪祭と(即ち律法に循ひて献ぐる物)を欲せず、また悦ばず』と言ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, '後に『視よ、我なんぢの御意を行はんとて來る』と言ひ給へり。その後なる者を立てん爲に、その先なる者を除き給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'この御意に適ひてイエス・キリストの體の一たび献げられしに由りて我らは潔められたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'すべての祭司は日毎に立ちて事へ、いつまでも罪を除くこと能はぬ同じ犧牲をしばしば献ぐ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, '然れどキリストは罪のために一つの犧牲を献げて限りなく神の右に坐し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, '斯くて己が仇の己が足臺とせられん時を待ちたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'そは潔めらるる者を一つの供物にて限りなく全うし給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, '聖 靈も亦われらに之を證して');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '『「この日の後、われ彼らと立つる契約は是なり」と主いひ給ふ。また「わが律法をその心に置き、その念に銘さん」』と言ひ給ひて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, '『この後また彼らの罪と不法とを思ひ出でざるべし』と言ひたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'かかる赦ある上は、もはや罪のために献物をなす要なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, '然れば兄弟よ、我らイエスの血により、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'その肉體たる幔を經て我らに開き給へる新しき活ける路より憚らずして至 聖所に入ることを得、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'かつ神の家を治むる大なる祭司を得たれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, '心は濯がれて良心の咎をさり、身は清き水にて洗はれ、眞の心と全き信仰とをもて神に近づくべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'また約束し給ひし者は忠實なれば、我ら言ひあらはす所の望を動かさずして堅く守り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, '互に相 顧み、愛と善き業とを勵まし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, '集會をやむる或 人の習慣の如くせず、互に勸め合ひ、かの日のいよいよ近づくを見て、ますます斯くの如くすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, '我等もし眞理を知る知識をうけたる後、ことさらに罪を犯して止めずば、罪のために犧牲、もはや無し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'ただ畏れつつ審判を待つことと、逆ふ者を焚きつくす烈しき火とのみ遺るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'モーセの律法を蔑する者は慈悲を受くることなく、二三人の證人によりて死に至る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'まして神の子を蹈みつけ、己が潔められし契約の血を潔からずとなし、恩惠の御靈を侮る者の受くべき罰の重きこと如何許とおもふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, '『仇を復すは我に在り、われ之を報いん』と言ひ、また『主その民を審かん』と言ひ給ひし者を我らは知るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, '活ける神の御手に陷るは畏るべきかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'なんぢら御光を受けしのち苦難の大なる戰鬪に耐へし前の日を思ひ出でよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, '或は誹謗と患難とに遭ひて觀物にせられ、或は斯かることに遭ふ人の友となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'また囚人となれる者を思ひやり、永く存する尤も勝れる所有の己にあるを知りて、我が所有を奪はるるをも喜びて忍びたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'されば大なる報を受くべき汝らの確信を投げすつな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'なんぢら神の御意を行ひて約束のものを受けん爲に必要なるは忍耐なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, '『いま暫くせば、來るべき者きたらん、遲からじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, '我に屬ける義人は、信仰によりて活くべし。もし退かば、わが心これを喜ばじ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, '然れど我らは退きて滅亡に至る者にあらず、靈魂を得るに至る信仰を保つ者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'それ信仰は望むところを確信し、見ぬ物を眞實とするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, '古への人は之によりて證せられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, '信仰によりて我等は、もろもろの世界の神の言にて造られ、見ゆる物の顯るる物より成らざるを悟る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, '信仰に由りてアベルはカインよりも勝れる犧牲を神に献げ、之によりて正しと證せられたり。神その供物につきて證し給へばなり。彼は死ぬれども、信仰によりて今なほ語る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, '信仰に由りてエノクは死を見ぬように移されたり。神これを移し給ひたれば見出されざりき。その移さるる前に神に喜ばるることを證せられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, '信仰なくしては神に悦ばるること能はず、そは神に來る者は、神の在すことと神の己を求むる者に報い給ふこととを、必ず信ずべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, '信仰に由りてノアは、未だ見ざる事につきて御告を蒙り、畏みてその家の者を救はん爲に方舟を造り、かつ之によりて世の罪を定め、また信仰に由る義の世嗣となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, '信仰に由りてアブラハムは召されしとき嗣業として受くべき地に出で往けとの命に遵ひ、その往く所を知らずして出で往けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, '信仰により異國に在るごとく約束の地に寓り、同じ約束を嗣ぐべきイサクとヤコブと共に幕屋に住めり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'これ神の營み造りたまふ基礎ある都を望めばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, '信仰に由りてサラも約束したまふ者の忠實なるを思ひし故に、年 邁ぎたれど胤をやどす力を受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'この故に死にたる者のごとき一人より天の星のごとく、また海邊の數へがたき砂のごとく夥多しく生れ出でたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, '彼 等はみな信仰を懷きて死にたり、未だ約束の物を受けざりしが、遙にこれを見て迎へ、地にては旅人また寓れる者なるを言ひあらはせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, '斯く言ふは、己が故郷を求むることを表すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, '若しその出でし處を念はば、歸るべき機ありしなるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'されど彼らの慕ふ所は天にある更に勝りたる所なり。この故に神は彼らの神と稱へらるるを恥とし給はず、そは彼 等のために都を備へ給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, '信仰に由りてアブラハムは試みられし時イサクを献げたり、彼は約束を喜び受けし者なるに、その獨子を献げたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, '彼に對しては『イサクより出づる者なんぢの裔と稱へらるべし』と云ひ給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'かれ思へらく、神は死人の中より之を甦へらすることを得給ふと、乃ち死より之を受けしが如くなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, '信仰に由りてイサクは來らんとする事につきヤコブとエサウとを祝福せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, '信仰に由りてヤコブは死ぬる時ヨセフの子 等をおのおの祝福し、その杖の頭によりて禮拜せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, '信仰に由りてヨセフは生命の終らんとする時、イスラエルの子らの出で立つことに就きて語り、又おのが骨のことを命じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, '信仰に由りて兩親はモーセの生れたる時、その美しき子なるを見て、王の命をも畏れずして三月の間これを匿したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, '信仰に由りてモーセは人と成りしときパロの女の子と稱へらるるを否み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, '罪のはかなき歡樂を受けんよりは、寧ろ神の民とともに苦しまんことを善しとし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'キリストに因る謗はエジプトの財寶にまさる大なる富と思へり、これ報を望めばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, '信仰に由りて彼は王の憤恚を畏れずしてエジプトを去れり。これ見えざる者を見るがごとく耐ふる事をすればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, '信仰に由りて彼は過越と血を灑ぐこととを行へり、これ初子を滅す者の彼らに觸れざらん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, '信仰に由りてイスラエル人は紅海を乾ける地のごとく渡りしが、エジプト人は然せんと試みて溺れ死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, '信仰に由りて七日のあいだ廻りたればエリコの石垣は崩れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, '信仰に由りて遊女ラハブは平和をもて間者を接けたれば、不 從順の者とともに亡びざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'この外なにを言ふべきか、ギデオン、バラク、サムソン、エフタ、またダビデ、サムエル及び預言者たちに就きて語らば、時 足らざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, '彼らは信仰によりて國々を服へ、義をおこなひ、約束のものを得、獅子の口をふさぎ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, '火の勢力を消し、劍の刃をのがれ、弱よりして強くせられ、戰爭に勇ましくなり、異國人の軍勢を退かせたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, '女は死にたる者の復活を得、ある人は更に勝りたる復活を得んために、免さるることを願はずして極刑を甘んじたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'その他の者は嘲笑と鞭と、また縲絏と牢獄との試錬を受け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, '或 者は石にて撃たれ、試みられ、鐵鋸にて挽かれ、劍にて殺され、羊・山羊の皮を纏ひて經あるき、乏しくなり、惱され、苦しめられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(世は彼らを置くに堪へず)荒野と山と洞と地の穴とに徨へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, '彼 等はみな信仰に由りて證せられたれども約束のものを得ざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'これ神は我らの爲に勝りたるものを備へ給ひし故に、彼らも我らと偕ならざれば、全うせらるる事なきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'この故に我らは斯く多くの證人に雲のごとく圍まれたれば、凡ての重荷と纏へる罪とを除け、忍耐をもて我らの前に置かれたる馳場をはしり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, '信仰の導師また之を全うする者なるイエスを仰ぎ見るべし。彼はその前に置かれたる歡喜のために、恥をも厭はずして十字架をしのび、遂に神の御座の右に坐し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'なんじら倦み疲れて心を喪ふこと莫らんために、罪人らの斯く己に逆ひしことを忍び給へる者をおもへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, '汝らは罪と鬪ひて未だ血を流すまで抵抗しことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'また子に告ぐるごとく汝らに告げ給ひし勸言を忘れたり。曰く『わが子よ、主の懲戒を輕んずるなかれ、主に戒めらるるとき倦むなかれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'そは主、その愛する者を懲しめ、凡てその受け給ふ子を鞭うち給へばなり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, '汝らの忍ぶは懲戒の爲なり、神は汝らを子のごとく待ひたまふ、誰か父の懲しめぬ子あらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, '凡ての人の受くる懲戒、もし汝らに無くば、それは私生兒にして眞の子にあらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'また我らの肉體の父は、我らを懲しめし者なるに尚これを敬へり、況して靈魂の父に服ひて生くることを爲ざらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'そは肉體の父は暫くの間その心のままに懲しむることを爲しが、靈魂の父は我らを益するために、その聖潔に與らせんとて懲しめ給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, '凡ての懲戒、今は喜ばしと見えず、反つて悲しと見ゆ、されど後これに由りて練習する者に、義の平安なる果を結ばしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'されば衰へたる手、弱りたる膝を強くし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, '足蹇へたる者の履み外すことなく、反つて醫されんために汝らの足に直なる途を備へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, '力めて凡ての人と和ぎ、自ら潔からんことを求めよ。もし潔からずば、主を見ること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'なんじら愼め、恐らくは神の恩惠に至らぬ者あらん。恐らくは苦き根はえいでて汝らを惱し、多くの人これに由りて汚されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, '恐らくは淫行のもの、或は一飯のために長子の特權を賣りしエサウの如き妄なるもの起らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, '汝らの知るごとく、彼はそののち祝福を受けんと欲したれども棄てられ、涙を流して之を求めたれど囘復の機を得ざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, '汝らの近づきたるは、火の燃ゆる觸り得べき山・黒 雲・黒闇・嵐、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'ラッパの音、言の聲にあらず、この聲を聞きし者は此の上に言の加へられざらんことを願へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'これ『獸すら山に觸れなば、石にて撃るべし』と命ぜられしを、彼らは忍ぶこと能はざりし故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'その現れしところ極めて怖しかりしかば、モーセは『われ甚く怖れ戰けり』と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'されど汝らの近づきたるはシオンの山、活ける神の都なる天のエルサレム、千萬の御使の集會、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, '天に録されたる長子どもの教會、萬民の審判 主なる神、全うせられたる義人の靈魂、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, '新約の仲保なるイエス及びアベルの血に勝りて物 言ふ灑の血なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'なんじら心して語りたまふ者を拒むな、もし地にて示し給ひし時これを拒みし者ども遁るる事なかりしならば、況して天より示し給ふとき、我ら之を退けて遁るることを得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'その時、その聲、地を震へり、されど今は誓ひて言ひたまふ『我なほ一たび地のみならず、天をも震はん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, '此の『なほ一度』とは震はれぬ物の存らんために、震はるる物すなはち造られたる物の取り除かるることを表すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'この故に我らは震はれぬ國を受けたれば、感謝して恭敬と畏懼とをもて御心にかなふ奉仕を神になすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, '我らの神は燒き盡す火なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, '兄弟の愛を常に保つべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, '旅人の接待を忘るな、或 人これに由り、知らずして御使を舍したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, '己も共に繋がるるごとく囚人を思へ、また己も肉體に在れば、苦しむ者を思へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, '凡ての人、婚姻のことを貴べ、また寢床を汚すな。神は淫行のもの、姦淫の者を審き給ふべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, '金を愛することなく、有てるものを以て足れりとせよ。主みづから『われ更に汝を去らず、汝を捨てじ』と言ひ給ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, '然れば我ら心を強くして斯く言はん『主わが助主なり、我おそれじ。人われに何をなさん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, '神の言を汝らに語りて汝らを導きし者どもを思へ、その行状の終を見てその信仰に效へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'イエス・キリストは昨日も今日も永遠までも變り給ふことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, '各樣の異なる教のために惑さるな。飮食によらず、恩惠によりて心を堅うするは善し、飮食によりて歩みたる者は益を得ざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, '我らに祭壇あり、幕屋に事ふる者は之より食する權を有たず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, '大 祭司、罪のために活物の血を携へて至 聖所に入り、その活物の體は陣營の外にて燒かるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'この故にイエスも己が血をもて民を潔めんが爲に、門の外にて苦難を受け給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'されば我らは彼の恥を負ひ、陣營より出でてその御許に往くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'われら此處には永遠の都なくして、ただ來らんとする者を求むればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, '此の故に我らイエスによりて常に讃美の供物を神に献ぐべし、乃ちその御名を頌むる口唇の果なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'かつ仁慈と施濟とを忘るな、神は斯くのごとき供物を喜びたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, '汝らを導く者に順ひ之に服せよ。彼らは己が事を神に陳ぶべき者なれば、汝らの靈魂のために目を覺しをるなり。彼らを歎かせず、喜びて斯く爲さしめよ、然らずば汝らに益なかるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, '我らの爲に祈れ、我らは善き良心ありて凡てのこと正しく行はんと欲するを信ずるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'われ速かに汝らに歸ることを得んために、汝らの祈らんことを殊に求む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, '願はくは永遠の契約の血によりて、羊の大牧者となれる我らの主イエスを、死人の中より引上げ給ひし平和の神、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'その悦びたまふ所を、イエス・キリストに由りて我らの衷に行ひ、御意を行はしめん爲に凡ての善き事につきて、汝らを全うし給はんことを。世々 限りなく榮光、かれに在れ、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, '兄弟よ、請ふ我が勸の言を容れよ、我なんじらに手短く書き贈りたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'なんじら知れ、我らの兄弟テモテは釋されたり。彼もし速かに來らば、我かれと偕に汝らを見ん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, '汝らの凡ての導く者、および凡ての聖徒に安否を問へ。イタリヤの人々、なんぢらに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, '願はくは恩惠なんぢら衆と偕に在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, '神および主イエス・キリストの僕ヤコブ、散り居る十二の族の平安を祈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'わが兄弟よ、なんぢら各樣の試錬に遭ふとき、只管これを歡喜とせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'そは汝らの信仰の驗は、忍耐を生ずるを知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, '忍耐をして全き活動をなさしめよ。これ汝らが全くかつ備りて、缺くる所なからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, '汝らの中もし智慧の缺くる者あらば、咎むることなくまた惜む事なく、凡ての人に與ふる神に求むべし、さらば與へられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, '但し疑ふことなく、信仰をもて求むべし。疑ふ者は、風に動かされて翻へる海の波のごときなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'かかる人は主より何 物をも受くと思ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, '斯かる人は二心にして、凡てその歩むところの途 定りなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, '卑き兄弟は、おのが高くせられたるを喜べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, '富める者は、おのが卑くせられたるを喜べ。そは草の花のごとく過ぎゆくべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, '日 出で熱き風 吹きて草を枯らせば、花 落ちてその麗しき姿ほろぶ。富める者もまた斯くのごとく、その途の半にして己まづ消え失せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, '試錬に耐ふる者は幸福なり、之を善しとせらるる時は、主のおのれを愛する者に、約束し給ひし生命の冠冕を受くべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, '人 誘はるるとき『神われを誘ひたまふ』と言ふな、神は惡に誘はれ給はず、又みづから人を誘ひ給ふことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, '人の誘はるるは己の慾に引かれて惑さるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, '慾 孕みて罪を生み、罪 成りて死を生む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'わが愛する兄弟よ、自ら欺くな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, '凡ての善き賜物と凡ての全き賜物とは、上より、もろもろの光の父より降るなり。父は變ることなく、また囘轉の影もなき者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'その造り給へる物の中にて我らを初穗のごとき者たらしめんとて、御旨のままに眞理の言をもて、我らを生み給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'わが愛する兄弟よ、汝らは之を知る。されば、おのおの聽くことを速かにし、語ることを遲くし、怒ることを遲くせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, '人の怒は神の義を行はざればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'されば凡ての穢と溢るる惡とを捨て、柔和をもて其の植ゑられたる所の靈魂を救ひ得る言を受けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'ただ御言を聞くのみにして、己を欺く者とならず、之を行ふ者となれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'それ御言を聞くのみにして之を行はぬ者は、鏡にて己が生來の顏を見る人に似たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, '己をうつし見て立ち去れば、直ちにその如何なる姿なりしかを忘る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'されど全き律法、すなはち自由の律法を懇ろに見て離れぬ者は、業を行ふ者にして、聞きて忘るる者にあらず、その行爲によりて幸福ならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, '人もし自ら信心ふかき者と思ひて、その舌に轡を著けず、己が心を欺かば、その信心は空しきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, '父なる神の前に潔くして穢なき信心は、孤兒と寡婦とをその患難の時に見舞ひ、また自ら守りて世に汚されぬ是なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'わが兄弟よ、榮光の主なる我らの主イエス・キリストに對する信仰を保たんには、人を偏り視るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, '金の指輪をはめ華美なる衣を著たる人、なんぢらの會堂に入りきたり、また粗末なる衣を著たる貧しき者いり來らんに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, '汝 等その華美なる衣を著たる人を重んじ視て『なんぢ此の善き處に坐せよ』と言ひ、また貧しき者に『なんぢ彼處に立つか、又はわが足下に坐せよ』と言はば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, '汝らの中にて區別をなし、また惡しき思をもてる審判 人となるに非ずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'わが愛する兄弟よ、聽け、神は世の貧しき者を選びて信仰に富ませ、神を愛する者に約束し給ひし國の世繼たらしめ給ひしに非ずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, '然るに汝らは貧しき者を輕んじたり、汝らを虐げ、また裁判所に曳くものは、富める者にあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, '彼らは汝らの上に稱へらるる尊き名を汚すものに非ずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, '汝 等もし聖書にある『おのれの如く汝の隣を愛すべし』との尊き律法を全うせば、その爲すところ善し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'されど若し人を偏り視れば、これ罪を行ふなり。律法、なんぢらを犯罪者と定めん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, '人、律法 全體を守るとも、その一つに躓かば是すべてを犯すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'それ『姦淫する勿れ』と宣ひし者、また『殺す勿れ』と宣ひたれば、なんぢ姦淫せずとも、若し人を殺さば律法を破る者となるなり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'なんぢら自由の律法によりて審かれんとする者のごとく語り、かつ行ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, '憐憫を行はぬ者は憐憫なき審判を受けん、憐憫は審判にむかひて勝ち誇るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'わが兄弟よ、人みづから信仰ありと言ひて、もし行爲なくば何の益かあらん、かかる信仰は彼を救ひ得んや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'もし兄弟 或は姉妹、裸體にて日用の食物に乏しからんとき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, '汝 等のうち、或 人これに『安らかにして往け、温かなれ、飽くことを得よ』といひて體に無くてならぬ物を與へずば、何の益かあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, '斯くのごとく信仰もし行爲なくば、死にたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, '人もまた言はん『なんぢ信仰あり、われ行爲あり、汝の行爲なき信仰を我に示せ、我わが行爲によりて信仰を汝に示さん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'なんぢ神は唯一なりと信ずるか、かく信ずるは善し、惡鬼も亦 信じて慄けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'ああ虚しき人よ、なんぢ行爲なき信仰の徒然なるを知らんと欲するか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, '我らの父アブラハムはその子イサクを祭壇に献げしとき、行爲によりて義とせられたるに非ずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'なんぢ見るべし、その信仰、行爲と共にはたらき、行爲によりて全うせられたるを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'またアブラハム神を信じ、その信仰を義と認められたりと云へる聖書は成就し、かつ彼は神の友と稱へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'かく人の義とせらるるは、ただ信仰のみに由らずして行爲に由ることは、汝らの見る所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'また遊女ラハブも使者を受け、これを他の途より去らせたるとき、行爲によりて義とせられたるに非ずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, '靈魂なき體の死にたる者なるが如く、行爲なき信仰も死にたるものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'わが兄弟よ、なんぢら多く教師となるな。教師たる我らの更に嚴しき審判を受くることを、汝ら知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, '我らは皆しばしば躓く者なり、人もし言に蹉跌なくば、これ全き人にして全身に轡を著け得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'われら馬を己に馴はせんために轡をその口に置くときは、その全身を馭し得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'また船を見よ、その形は大く、かつ激しき風に追はるるとも、最 小き舵にて舵人の欲するままに運すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, '斯くのごとく舌もまた小きものなれど、その誇るところ大なり。視よ、いかに小き火の、いかに大なる林を燃すかを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, '舌は火なり、不義の世界なり、舌は我らの肢體の中にて、全身を汚し、また地獄より燃え出でて一生の車輪を燃すものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, '獸・鳥・匍ふもの・海にあるもの等、さまざまの種類みな制せらる、既に人に制せられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'されど誰も舌を制すること能はず、舌は動きて止まぬ惡にして死の毒の滿つるものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'われら之をもて主たる父を讃め、また之をもて神に象りて造られたる人を詛ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, '讃美と呪詛と同じ口より出づ。わが兄弟よ、かかる事はあるべきにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, '泉は同じ穴より甘き水と苦き水とを出さんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'わが兄弟よ、無花果の樹オリブの實を結び、葡萄の樹、無花果の實を結ぶことを得んや。斯くのごとく鹽 水は甘き水を出すこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, '汝 等のうち智くして慧き者は誰なるか、その人は善き行状により柔和なる智慧をもて行爲を顯すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'されど汝 等もし心のうちに苦き妬と黨派心とを懷かば、誇るな、眞理に悖りて僞るな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'かかる智慧は上より下るにあらず、地に屬し、情 慾に屬し、惡鬼に屬するものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, '妬と黨派心とある所には亂と各樣の惡しき業とあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'されど上よりの智慧は第一に潔よく、次に平和・寛容・温順また憐憫と善き果とに滿ち、人を偏り視ず、虚僞なきものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, '義の果は平和をおこなふ者の平和をもて播くに因るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, '汝 等のうちの戰爭は何處よりか、分爭は何處よりか、汝らの肢體のうちに戰ふ慾より來るにあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, '汝ら貪れども得ず、殺すことをなし、妬むことを爲れども得ること能はず、汝らは爭ひまた戰す。汝らの得ざるは求めざるに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, '汝ら求めてなほ受けざるは慾のために費さんとて妄に求むるが故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, '姦淫をおこなふ者よ、世の友となるは、神に敵するなるを知らぬか、誰にても世の友とならんと欲する者は、己を神の敵とするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, '聖書に『神は我らの衷に住ませ給ひし靈を、妬むほどに慕ひたまふ』と云へるを虚しきことと汝ら思ふか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, '神は更に大なる恩惠を賜ふ。されば言ふ『神は高ぶる者を拒ぎ、へりくだる者に恩惠を與へ給ふ』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'この故に汝ら神に服へ、惡魔に立ち向へ、さらば彼なんぢらを逃げ去らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, '神に近づけ、さらば神なんぢらに近づき給はん。罪人よ、手を淨めよ、二心の者よ、心を潔よくせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'なんぢら惱め、悲しめ、泣け、なんぢらの笑を悲歎に、なんぢらの歡喜を憂に易へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, '主の前に己を卑うせよ、然らば主なんぢらを高うし給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, '兄弟よ、互に謗るな。兄弟を謗る者、兄弟を審く者は、これ律法を誹り、律法を審くなり。汝もし律法を審かば、律法をおこなふ者にあらずして審判 人なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, '立法者また審判者は唯 一人にして、救ふことをも滅ぼすことをも爲し得るなり。なんぢ誰なれば隣を審くか。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, '聽け『われら今日もしくは明日それがしの町に往きて、一年の間かしこに留り、賣買して利を得ん』と言ふ者よ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, '汝らは明日のことを知らず、汝らの生命は何ぞ、暫く現れて遂に消ゆる霧なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, '汝 等その言ふところに易へて『主の御意ならば、我ら活きて此のこと、或は彼のことを爲さん』と言ふべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'されど今なんぢらは高ぶりて誇る、斯くのごとき誇はみな惡しきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, '人 善を行ふことを知りて、之を行はぬは罪なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, '聽け、富める者よ、なんぢらの上に來らんとする艱難のために泣きさけべ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, '汝らの財は朽ち、汝らの衣は蠧み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, '汝らの金 銀は錆びたり。この錆なんぢらに對ひて證をなし、かつ火のごとく汝らの肉を蝕はん。汝 等この末の世に在りてなほ財を蓄へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, '視よ、汝 等がその畑を刈り入れたる勞動人に拂はざりし値は叫び、その刈りし者の呼聲は萬軍の主の耳に入れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, '汝らは地にて奢り樂しみ、屠らるる日に在りて尚おのが心を飽かせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, '汝らは正しき者を罪に定め、且これを殺せり、彼は汝らに抵抗することなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, '兄弟よ、主の來り給ふまで耐へ忍べ。視よ、農夫は地の貴き實を、前と後との雨を得るまで耐へ忍びて待つなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, '汝らも耐へ忍べ、なんぢらの心を堅うせよ。主の來り給ふこと近づきたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, '兄弟よ、互に怨言をいふな、恐らくは審かれん。視よ、審判 主、門の前に立ちたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, '兄弟よ、主の名によりて語りし預言者たちを苦難と耐忍との模範とせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, '視よ、我らは忍ぶ者を幸福なりと思ふ。なんぢらヨブの忍耐を聞けり、主の彼に成し給ひし果を見たり、即ち主は慈悲ふかく、かつ憐憫あるものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'わが兄弟よ、何事よりも先づ誓ふな、或は天、あるひは地、あるひは其の他のものを指して誓ふな。只なんぢら然りは然り否は否とせよ、罪に定めらるる事なからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, '汝 等のうち苦しむ者あるか、その人、祈せよ。喜ぶ者あるか、その人、讃美せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, '汝 等のうち病める者あるか、その人、教會の長老たちを招け。彼らは主の名により其の人に油をぬりて祈るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'さらば信仰の祈は病める者を救はん、主かれを起し給はん、もし罪を犯しし事あらば赦されん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'この故に互に罪を言ひ表し、かつ癒されんために相 互に祈れ、正しき人の祈ははたらきて大なる力あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'エリヤは我らと同じ情をもてる人なるに、雨 降らざることを切に祈りしかば、三年 六个月のあひだ地に雨 降らざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'かくて再び祈りたれば、天 雨を降らし、地その果を生ぜり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'わが兄弟よ、汝 等のうち眞理より迷ふ者あらんに、誰か之を引囘さば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'その人は知れ、罪人をその迷へる道より引囘す者は、かれの靈魂を死より救ひ、多くの罪を掩ふことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'イエス・キリストの使徒ペテロ、書をポント、ガラテヤ、カパドキヤ、アジヤ、ピテニヤに散りて宿れる者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, '即ち父なる神の預じめ知り給ふところに隨ひて、御靈の潔により柔順ならんため、イエス・キリストの血の灑を受けんために選ばれたる者に贈る。願はくは恩惠と平安と汝らに増さんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, '讃むべきかな、我らの主イエス・キリストの父なる神、その大なる憐憫に隨ひ、イエス・キリストの死人の中より甦へり給へることに由り、我らを新に生れしめて生ける望を懷かせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, '汝らの爲に天に蓄へある、朽ちず汚れず萎まざる嗣業を繼がしめ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, '汝らは終のときに顯れんとて備りたる救を得んために、信仰によりて神の力に護らるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'この故に汝ら今しばしの程さまざまの試煉によりて憂へざるを得ずとも、なほ大に喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, '汝らの信仰の驗は、壞つる金の火にためさるるよりも貴くして、イエス・キリストの現れ給ふとき譽と光榮と尊貴とを得べきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, '汝らイエスを見しことなけれど之を愛し、今 見ざれども之を信じて、言ひがたく、かつ光榮ある喜悦をもて喜ぶ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'これ信仰の極、すなはち靈魂の救を受くるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, '汝らの受くべき恩惠を預言したる預言者たちは、この救につきて具に尋ね査べたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, '即ち彼らは己が中に在すキリストの靈の、キリストの受くべき苦難および其の後の榮光を預じめ證して、何時のころ如何なる時を示し給ひしかを査べたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, '彼 等はその勤むるところ己のためにあらず、汝らの爲なることを默示によりて知れり。即ち天より遣され給へる聖 靈によりて福音を宣ぶる者どもの、汝らに傳へたる所にして、御使たちも之を懇ろに視んと欲するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'この故に、なんぢら心の腰に帶し、愼みてイエス・キリストの現れ給ふときに、與へられんとする恩惠を疑はずして望め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, '從順なる子 等の如くして、前の無知なりし時の慾に效はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, '汝らを召し給ひし聖者に效ひて、自ら凡ての行状に潔かれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, '録して『われ聖なれば、汝らも聖なるべし』とあればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'また偏ることなく各人の業に隨ひて審きたまふ者を父と呼ばば、畏をもて世に寓る時を過せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'なんぢらが先祖たちより傳はりたる虚しき行状より贖はれしは、銀や金のごとき朽つる物に由るにあらず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, '瑕なく汚點なき羔羊の如きキリストの貴き血に由ることを知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, '彼は世の創の前より預じめ知られたまひしが、この末の世に現れ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'これは彼を死人の中より甦へらせて之に榮光を與へ給ひし神を、彼によりて信ずる汝らの爲なり、この故に汝らの信仰と希望とは神に由れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'なんぢら眞理に從ふによりて靈魂をきよめ、僞りなく兄弟を愛するに至りたれば、心より熱く相 愛せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, '汝らは朽つる種に由らで、朽つることなき種、すなはち神の活ける限りなく保つ言に由りて新に生れたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, '『人はみな草のごとく、その光榮はみな草の花の如し、草は枯れ、花は落つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'されど主の御言は永遠に保つなり』汝らに宣傅へたる福音の言は即ちこれなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'されば凡ての惡意、すべての詭計・僞善・嫉妬および凡ての謗を棄てて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'いま生れし嬰兒のごとく靈の眞の乳を慕へ、之により育ちて救に至らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'なんぢら既に主の仁慈あることを味ひ知りたらんには、然すべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, '主は人に棄てられ給へど、神に選ばれたる貴き活ける石なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'なんぢら彼にきたり、活ける石のごとく建てられて靈の家となれ。これ潔き祭司となり、イエス・キリストに由りて神に喜ばるる靈の犧牲を献げん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, '聖書に『視よ、選ばれたる貴き隅の首石を我シオンに置く。之に依頼む者は辱しめられじ』とあるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'されば信ずる汝らには尊きなれど、信ぜぬ者には『造家者らの棄てたる石は、隅の首石となれる』にて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, '『つまづく石、礙ぐる岩』となるなり。彼らは服はぬに因りて御言に躓く。これは斯く定められたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'されど汝らは選ばれたる族、王なる祭司・潔き國人・神に屬ける民なり、これ汝らを暗黒より召して、己の妙なる光に入れ給ひし者の譽を顯させん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'なんぢら前には民にあらざりしが、今は神の民なり。前には憐憫を蒙らざりしが、今は憐憫を蒙れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, '愛する者よ、われ汝らに勸む。汝らは旅人また宿れる者なれば、靈魂に逆ひて戰ふ肉の慾を避け、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, '異邦人の中にありて行状を美しく爲よ、これ汝らを謗りて惡をおこなふ者と云へる人々の、汝らの善き行爲を見て、反つて眷顧の日に神を崇めん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'なんぢら主のために凡て人の立てたる制度に服へ。或は上に在る王、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, '或は惡をおこなふ者を罰し、善をおこなふ者を賞せんために王より遣されたる司に服へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, '善を行ひて愚なる人の無知の言を止むるは、神の御意なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'なんぢら自由なる者のごとくすとも、その自由をもて惡の覆となさず、神の僕のごとくせよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'なんぢら凡ての人を敬ひ、兄弟を愛し、神を畏れ、王を尊べ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, '僕たる者よ、大なる畏をもて主人に服へ、啻に善きもの、寛容なる者にのみならず、情なき者にも服へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, '人もし受くべからざる苦難を受け、神を認むるに因りて憂に堪ふる事をせば、これ譽むべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'もし罪を犯して撻たるるとき、之を忍ぶとも何の功かある。されど若し善を行ひてなほ苦しめらるる時これを忍ばば、これ神の譽めたまふ所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, '汝らは之がために召されたり、キリストも汝らの爲に苦難をうけ、汝らを其の足跡に隨はしめんとて模範を遺し給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, '彼は罪を犯さず、その口に虚僞なく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'また罵られて罵らず、苦しめられて脅かさず、正しく審きたまふ者に己を委ね、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, '木の上に懸りて、みづから我らの罪を己が身に負ひ給へり。これ我らが罪に就きて死に、義に就きて生きん爲なり。汝らは彼の傷によりて癒されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'なんぢら前には羊のごとく迷ひたりしが、今は汝らの靈魂の牧者たる監督に歸りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, '妻たる者よ、汝らもその夫に服へ。たとひ御言に遵はぬ夫ありとも、汝らの潔く、かつ恭敬しき行状を見て、言によらず妻の行状によりて救に入らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, '妻たる者よ、汝らもその夫に服へ。たとひ御言に遵はぬ夫ありとも、汝らの潔く、かつ恭敬しき行状を見て、言によらず妻の行状によりて救に入らん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, '汝らは髮を辮み、金をかけ、衣服を裝ふごとき表面のものを飾とせず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, '心のうちの隱れたる人、すなはち柔和、恬靜なる靈の朽ちぬ物を飾とすべし、是こそは神の前にて價 貴きものなれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'むかし神に望を置きたる潔き女たちも、かくの如くその夫に服ひて己を飾りたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, '即ちサラがアブラハムを主と呼びて之に服ひし如し。汝らも善を行ひて何事にも戰き懼れずばサラの子たるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, '夫たる者よ、汝らその妻を己より弱き器の如くし、知識にしたがひて偕に棲み、生命の恩惠を共に嗣ぐ者として之を貴べ、これ汝らの祈に妨害なからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, '終に言ふ、汝らみな心を同じうし、互に思ひ遣り、兄弟を愛し、憐み、へりくだり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, '惡をもて惡に、謗をもて謗に報ゆることなく、反つて之を祝福せよ。汝らの召されたるは祝福を嗣がん爲なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, '『生命を愛し、善き日を送らんとする者は、舌を抑へて惡を避け、口唇を抑へて虚僞を語らず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, '惡より遠ざかりて善をおこなひ、平和を求めて之を追ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'それ主の目は義人の上にとどまり、その耳は彼らの祈にかたむく。されど主の御顏は惡をおこなふ者に向ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, '汝 等もし善に熱心ならば、誰か汝らを害はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'たとひ義のために苦しめらるる事ありとも、汝ら幸福なり『彼 等の威嚇を懼るな、また心を騷がすな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, '心の中にキリストを主と崇めよ、また汝らの衷にある望の理由を問ふ人には、柔和と畏懼とをもて常に辯明すべき準備をなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'かつ善き良心を保て。これ汝 等のキリストに在りて行ふ善き行状を罵る者の、その謗ることに就きて自ら愧ぢん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'もし善をおこなひて苦難を受くること神の御意ならば、惡を行ひて苦難を受くるに勝るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'キリストも汝らを神に近づかせんとて、正しきもの正しからぬ者に代りて、一たび罪のために死に給へり、彼は肉體にて殺され、靈にて生かされ給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'また靈にて往き、獄にある靈に宣傅へたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'これらの靈は、昔ノアの時代に方舟の備へらるるあひだ寛容をもて神の待ち給へるとき、服はざりし者どもなり、その方舟に入り水を經て救はれし者は、僅にしてただ八人なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'その水に象れるバプテスマは肉の汚穢を除くにあらず、善き良心の神に對する要求にして、イエス・キリストの復活によりて今なんぢらを救ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, '彼は天に昇りて神の右に在す。御使たち及びもろもろの權威と能力とは彼に服ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'キリスト肉體にて苦難を受け給ひたれば、汝らも亦おなじ心をもて自ら鎧へ。――肉體にて苦難を受くる者は罪を止むるなり――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'これ今よりのち、人の慾に從はず、神の御意に從ひて、肉體に寓れる殘の時を過さん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'なんぢら過ぎにし日は、異邦人の好む所をおこなひ、好色・慾 情・酩酊・宴樂・暴飮・律法にかなはぬ偶像 崇拜に歩みて、もはや足れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, '彼らは汝らの己とともに放蕩の極に走らぬを怪しみて譏るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, '彼らは生ける者と死にたる者とを審く準備をなし給へる者に己のことを陳ぶべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, '福音の死にたる者に宣傅へられしは、彼らが肉體にて人のごとく審かれ、靈にて神のごとく生きん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, '萬の物のをはり近づけり、然れば汝ら心を慥にし、愼みて祈せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, '何事よりも先づ互に熱く相 愛せよ。愛は多くの罪を掩へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'また吝むことなく互に懇ろに待せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, '神のさまざまの恩惠を掌どる善き家 司のごとく、各人その受けし賜物をもて互に事へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'もし語るならば、神の言をかたる者のごとく語り、事ふるならば、神の與へたまふ能力を受けたる者のごとく事へよ。是イエス・キリストによりて事々に神の崇められ給はん爲なり。榮光と權力とは世々 限りなく彼に歸するなり、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, '愛する者よ、汝らを試みんとて來れる火のごとき試煉を異なる事として怪しまず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, '反つてキリストの苦難に與れば、與るほど喜べ、なんぢら彼の榮光の顯れん時にも喜び樂しまん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'もし汝 等キリストの名のために謗られなば幸福なり。榮光の御靈すなはち神の御靈なんじらの上に留り給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, '汝 等のうち誰にても或は殺人、あるひは盜人、あるひは惡を行ふ者、あるひは妄に他人の事に干渉する者となりて苦難に遭ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'されど若しキリステアンたるをもて苦難を受けなば、之を恥づることなく、反つて此の名によりて神を崇めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, '既に時いたれり、審判は神の家より始るべし。まづ我等より始るとせば、神の福音に從はざる者のその結局は如何にぞや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, '義人もし辛うじて救はるるならば、不 敬虔なるもの、罪ある者は何處にか立たん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'されば神の御意に從ひて苦難を受くる者は、善を行ひて己が靈魂を眞實なる造物主にゆだね奉るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'われ汝らの中なる長老たちに勸む(我は汝らと同じく長老たる者、またキリストの苦難の證人、顯れんとする榮光に與る者なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, '汝らの中にある神の群羊を牧へ。止むを得ずして爲さず、神に從ひて心より爲し、利を貪るために爲さず、悦びてなし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, '委ねられたる者の主とならず、群羊の模範となれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'さらば大牧者の現れ給ふとき、萎まざる光榮の冠冕を受けん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, '若き者よ、なんぢら長老たちに服へ、かつ皆たがひに謙遜をまとへ『神は高ぶる者を拒ぎ、へりくだる者に恩惠を與へ給ふ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'この故に神の能力ある御手の下に己を卑うせよ、さらば時に及びて神なんぢらを高うし給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, '又もろもろの心勞を神に委ねよ、神なんぢらの爲に慮ぱかり給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, '愼みて目を覺しをれ、汝らの仇なる惡魔、ほゆる獅子のごとく歴迴りて呑むべきものを尋ぬ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'なんぢら信仰を堅うして彼を禦げ、なんぢらは世にある兄弟たちの同じ苦難に遭ふを知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'もろもろの恩惠の神、すなはち永遠の榮光を受けしめんとて、キリストによりて汝らを召し給へる神は、汝らが暫く苦難をうくる後、なんぢらを全うし、堅うし、強くして、その基を定め給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, '願はくは權力 世々 限りなく神にあれ、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'われ忠實なる兄弟なりと思ふシルワノに由りて、簡單に書き贈りて汝らに勸め、かつ此は神の眞の恩惠なることを證す、汝 等この恩惠に立て。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, '汝らと共に選ばれてバビロンに在る教會、なんぢらに安否を問ふ、わが子マルコも安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'なんぢら愛の接吻をもて互に安否を問へ。願はくはキリストに在る汝ら衆に平安あらんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'イエス・キリストの僕また使徒なるシメオン・ペテロ、書を我らの神および救主イエス・キリストの義によりて、我らと同じ貴き信仰を受けたる者に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, '願はくは神および我らの主イエスを知るによりて、恩惠と平安と汝らに増さんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'キリストの神たる能力は、生命と敬虔とに係る凡てのものを我らに賜へり。是おのれの榮光と徳とをもて召し給へる者を我ら知るに因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'その榮光と徳とによりて我らに貴き大なる約束を賜へり、これは汝らが世に在る慾の滅亡をのがれ、神の性質に與る者とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'この故に勵み勉めて汝らの信仰に徳を加へ、徳に知識を、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, '知識に節制を、節制に忍耐を、忍耐に敬虔を、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, '敬虔に兄弟の愛を、兄弟の愛に博愛を加へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, '此 等のもの汝らの衷にありて彌増すときは、汝 等われらの主イエス・キリストを知るに怠ることなく、實を結ばぬこと無きに至らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, '此 等のものの無きは盲人にして遠く見ること能はず、己が舊き罪を潔められしことを忘れたるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'この故に兄弟よ、ますます勵みて汝らの召されたること、選ばれたることを堅うせよ。若し此 等のことを行はば躓くことなからん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'かくて汝らは我らの主なる救主イエス・キリストの永遠の國に入る恩惠を豐に與へられん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'されば汝らは此 等のことを知り、既に受けたる眞理に堅うせられたれど、我つねに此 等のことを思ひ出させんとするなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, '我は尚この幕屋に居るあいだ、汝らに思ひ出させて勵ますを正當なりと思ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'そは我らの主イエス・キリストの我に示し給へるごとく、我わが幕屋を脱ぎ去ることの速かなるを知ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, '我また汝 等をして我が世を去らん後にも、常に此 等のことを思ひ出させんと勉むべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, '我らは我らの主イエス・キリストの能力と來りたまふ事とを汝らに告ぐるに、巧なる作話を用ひざりき、我らは親しくその稜威を見し者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'いとも貴き榮光の中より聲 出でて『こは我が愛しむ子なり、我これを悦ぶ』と言ひ給へるとき、主は父なる神より尊貴と榮光とを受け給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, '我らも彼と偕に聖なる山に在りしとき、天より出づる此の聲をきけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'かくて我らが有てる預言の言は堅うせられたり。汝 等この言を暗き處にかがやく燈火として、夜明け、明星の汝らの心の中にいづるまで顧みるは善し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'なんじら先づ知れ、聖書の預言は、すべて己がままに釋くべきものにあらぬを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, '預言は人の心より出でしにあらず、人々 聖 靈に動かされ、神によりて語れるものなればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'されど民のうちに僞 預言者おこりき、その如く汝らの中にも僞 教師あらん。彼らは滅亡にいたる異端を持ち入れ、己らを買ひ給ひし主をさへ否みて、速かなる滅亡を自ら招くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'また多くの人かれらの好色に隨はん、之によりて眞の道を譏らるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, '彼らは貪慾によりて飾言を設け、汝 等より利をとらん。彼らの審判は古へより定められたれば遲からず、その滅亡は寢ねず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, '神は罪を犯しし御使たちを赦さずして地獄に投げいれ、之を黒闇の穴におきて審判の時まで看守し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'また古き世を容さずして、ただ義の宣傅者なるノアと他の七人とをのみ護り、敬虔ならぬ者の世に洪水を來らせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'またソドムとゴモラとの町を滅亡に定めて灰となし、後の不 敬虔をおこなふ者の鑑とし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'ただ無法の者どもの好色の擧動を憂ひし正しきロトのみを救ひ給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(この正しき人は彼らの中に住みて、日々その不法の行爲を見 聞して、己が正しき心を傷めたり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'かく主は敬虔なる者を試煉の中より救ひ、また正しからぬ者を審判の日まで看守して之を罰し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, '別けて、肉に隨ひて、汚れたる情 慾のうちを歩み、權ある者を輕んずる者を罰することを知り給ふ。この曹輩は膽 太く放縱にして、尊き者どもを譏りて畏れぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, '御使たちはかの尊き者どもに勝りて、大なる權勢と能力とあれど、彼らを主の御前に譏り訴ふることをせず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, '然れど、かの曹輩は恰も捕へられ屠らるるために生れたる辯別なき生物のごとし、知らぬことを譏り、不義の價をえて必ず亡さるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, '彼らは晝もなほ酒食を快樂とし誘惑を樂しみ、汝らと共に宴席に與りて、汚點となり瑕となる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'その目は淫婦にて滿ち罪に飽くことなし、彼らは靈魂の定らぬ者を惑し、その心は貪欲に慣れて呪詛の子たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, '彼らは正しき道を離れて迷ひいで、ベオルの子バラムの道に隨へり。バラムは不義の報を愛して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'その不法を咎められたり。物 言はぬ驢馬、人の聲して語り、かの預言者の狂を止めたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'この曹輩は水なき井なり、颶風に逐はるる雲霧なり、黒き闇かれらの爲に備へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, '彼らは虚しき誇をかたり、迷の中にある者どもより辛うじて遁れたる者を、肉の慾と好色とをもて惑し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, '之に自由を與ふることを約すれど、自己は滅亡の奴隷たり、敗くる者は勝つ者に奴隷とせらるればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, '彼 等もし主なる救主イエス・キリストを知るによりて、世の汚穢をのがれしのち、復これに纏はれて敗くる時は、その後の状は前よりもなほ惡しくなるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, '義の道を知りて、その傳へられたる聖なる誡命を去り往かんよりは寧ろ義の道を知らぬを勝れりとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, '俚諺に『犬おのが吐きたる物に歸り來り、豚 身を洗ひてまた泥の中に轉ぶ』と云へるは眞にして、能く彼らに當れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, '愛する者よ、われ今この第二の書を汝らに書き贈り、第一なると之とをもて汝らに思ひ出させ、その潔よき心を勵まし、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, '聖なる預言者たちの預じめ云ひし言、および汝らの使徒たちの傳へし主なる救主の誡命を憶えさせんとす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, '汝 等まづ知れ、末の世には嘲る者 嘲笑をもて來り、おのが慾に隨ひて歩み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'かつ言はん『主の來りたまふ約束は何處にありや、先祖たちの眠りしのち、萬のもの開闢の初と等しくして變らざるなり』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, '彼らは殊更に次の事を知らざるなり、即ち古へ神の言によりて天あり、地は水より出で水によりて成立ちしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'その時の世は之により水に淹はれて滅びたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'されど同じ御言によりて今の天と地とは蓄へられ、火にて燒かれん爲に、敬虔ならぬ人々の審判と滅亡との日まで保たるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, '愛する者よ、なんぢら此の一事を忘るな。主の御前には一日は千年のごとく、千年は一日のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, '主その約束を果すに遲きは、或 人の遲しと思ふが如きにあらず、ただ一人の亡ぶるをも望み給はず、凡ての人の悔改に至らんことを望みて汝らを永く忍び給ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'されど主の日は盜人のごとく來らん、その日には天とどろきて去り、もろもろの天體は燒け崩れ、地とその中にある工とは燒け盡きん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'かく此 等のものはみな崩るべければ、汝 等いかに潔き行状と敬虔とをもて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, '神の日の來るを待ち之を速かにせんことを勉むべきにあらずや、その日には天 燃え崩れ、もろもろの天體 燒け溶けん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'されど我らは神の約束によりて、義の住むところの新しき天と新しき地とを待つ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'この故に愛する者よ、汝 等これを待てば、神の前に汚點なく瑕なく安然に在らんことを勉めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, '且われらの主の寛容を救なりと思へ、これは我らの愛する兄弟パウロも、その與へられたる智慧にしたがひ曾て汝らに書き贈りし如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, '彼はその凡ての書にも此 等のことに就きて語る、その中には悟りがたき所あり、無學のもの心の定らぬ者は、他の聖書のごとく之をも強ひ釋きて自ら滅亡を招くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'されば愛する者よ、なんぢら預じめ之を知れば、愼みて無法の者の迷にさそはれて己が堅き心を失はず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'ますます我らの主なる救主イエス・キリストの恩寵と主を知る知識とに進め。願はくは今および永遠の日までも榮光かれに在らんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, '太初より有りし所のもの、我等が聞きしところ、目にて見し所、つらつら視て手觸りし所のもの、即ち生命の言につきて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '――この生命すでに顯れ、われら之を見て證をなし、その曾て父と偕に在して、今われらに顯れ給へる永遠の生命を汝らに告ぐ――');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, '我らの見しところ聞きし所を汝らに告ぐ、これ汝 等をも我らの交際に與らしめん爲なり。我らは父および其の子イエス・キリストの交際に與るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, '此 等のことを書き贈るは、我らの喜悦の滿ちん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, '我らが彼より聞きて、また汝らに告ぐる音信は是なり、即ち神は光にして少しの暗き所なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'もし神と交際ありと言ひて暗きうちを歩まば、我ら僞りて眞理を行はざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'もし神の光のうちに在すごとく光のうちを歩まば、我ら互に交際を得、また其の子イエスの血、すべての罪より我らを潔む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'もし罪なしと言はば、是みづから欺けるにて眞理われらの中になし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'もし己の罪を言ひあらはさば、神は眞實にして正しければ、我らの罪を赦し、凡ての不義より我らを潔め給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'もし罪を犯したる事なしといはば、これ神を僞 者とするなり、神の言われらの中になし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'わが若子よ、これらの事を書き贈るは、汝らが罪を犯さざらん爲なり。人もし罪を犯さば、我等のために父の前に助主あり、即ち義なるイエス・キリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, '彼は我らの罪のために宥の供物たり、啻に我らの爲のみならず、また全世界の爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, '我らその誡命を守らば、之によりて彼を知ることを自ら悟る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, '『われ彼を知る』と言ひて其の誡命を守らぬ者は僞 者にして眞理その衷になし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'その御言を守る者は誠に神の愛、その衷に全うせらる。之によりて我ら彼に在ることを悟る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, '彼に居ると言ふ者は、彼の歩み給ひしごとく自ら歩むべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, '愛する者よ、わが汝らに書き贈るは、新しき誡命にあらず、汝らが初より有てる舊き誡命なり。この舊き誡命は汝らが聞きし所の言なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, '然れど我が汝らに書き贈るところは、また新しき誡命にして、主にも汝らにも眞なり、その故は眞の光すでに照りて、暗黒はややに過ぎ去ればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, '光に在りと言ひて其の兄弟を憎むものは、今もなほ暗黒にあるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'その兄弟を愛する者は、光に居りて顛躓その衷になし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'その兄弟を憎む者は暗黒にあり、暗きうちを歩みて己が往くところを知らず、これ暗黒はその眼を矇したればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, '若子よ、我この書を汝らに贈るは、なんぢら主の御名によりて罪を赦されたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, '父たちよ、我この書を汝らに贈るは、汝ら太初より在す者を知りたるに因る。若き者よ、我この書を汝らに贈るは、なんぢら惡しき者に勝ちたるに因る。子供よ、我この書を汝らに贈りたるは、汝ら御父を知りたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, '父たちよ、我この書を汝らに贈りたるは、汝ら太初より在す者を知りたるに因る。若き者よ、我この書を汝らに贈りたるは、汝ら強くかつ神の言その衷に留り、また惡しき者に勝ちたるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'なんぢら世をも世にある物をも愛すな。人もし世を愛せば、御父を愛する愛その衷になし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'おほよそ世にあるもの、即ち肉の慾、眼の慾、所有の誇などは、御父より出づるにあらず、世より出づるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, '世と世の慾とは過ぎ往く、されど神の御意をおこなふ者は永遠に在るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, '子供よ、今は末の時なり、汝らが非キリスト來らんと聞きしごとく、今や非キリスト多く起れり、之によりて我等その末の時なるを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, '彼らは我等より出でゆきたれど、固より我等のものに非ざりき。我らの屬ならば、我らと共に留りしならん。されどその出でゆきしは、皆われらの屬ならぬことの顯れん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, '汝らは聖なる者より油を注がれたれば、凡ての事を知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, '我この書を汝らに贈るは、汝ら眞理を知らぬ故にあらず、眞理を知り、かつ凡ての虚僞の眞理より出でぬことを知るに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, '僞 者は誰なるか、イエスのキリストなるを否む者にあらずや。御父と御子とを否む者は非キリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, '凡そ御子を否む者は御父をも有たず、御子を言ひあらはす者は御父をも有つなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, '初より聞きし所を汝らの衷に居らしめよ。初より聞きしところ汝らの衷に居らば、汝らも御子と御父とに居らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, '我らに約し給ひし約束は是なり、即ち永遠の生命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, '汝らを惑す者どもに就きて我これらの事を書き贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'なんぢらの衷には、主より注がれたる油とどまる故に、人の汝らに物を教ふる要なし。此の油は汝らに凡ての事を教へ、かつ眞にして虚僞なし、汝 等はその教へしごとく主に居るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'されば若子よ、主に居れ。これ主の現れ給ふときに臆することなく、其の來り給ふときに恥づることなからん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'なんぢら主を正しと知らば、凡て正義をおこなふ者の主より生れたることを知らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, '視よ、父の我らに賜ひし愛の如何に大なるかを。我ら神の子と稱へらる。既に神の子たり、世の我らを知らぬは、父を知らぬによりてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, '愛する者よ、我等いま神の子たり、後いかん、未だ顯れず、主の現れたまふ時われら之に肖んことを知る。我らその眞の状を見るべければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, '凡て主による此の希望を懷く者は、その清きがごとく己を潔くす。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'すべて罪をおこなふ者は不法を行ふなり、罪は即ち不法なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, '汝らは知る、主の現れ給ひしは罪を除かん爲なるを。主には罪あることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'おほよそ主に居る者は罪を犯さず、おほよそ罪を犯す者は未だ主を見ず、主を知らぬなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, '若子よ、人に惑さるな、義をおこなふ者は義人なり、即ち主の義なるがごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, '罪を行ふものは惡魔より出づ、惡魔は初より罪を犯せばなり。神の子の現れ給ひしは、惡魔の業を毀たん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, '凡て神より生るる者は罪を行はず、神の種、その衷に止るに由る。彼は神より生るる故に罪を犯すこと能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, '之に由りて神の子と惡魔の子とは明かなり。おほよそ義を行はぬ者および己が兄弟を愛せぬ者は神より出づるにあらず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'われら互に相 愛すべきは汝らが初より聞きし音信なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'カインに效ふな、彼は惡しき者より出でて己が兄弟を殺せり。何 故ころしたるか、己が行爲は惡しく、その兄弟の行爲は正しかりしに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, '兄弟よ、世は汝らを憎むとも怪しむな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'われら兄弟を愛するによりて、死より生命に移りしを知る、愛せぬ者は死のうちに居る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'おほよそ兄弟を憎む者は即ち人を殺す者なり、凡そ人を殺す者の、その内に永遠の生命なきを汝らは知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, '主は我らの爲に生命を捨てたまへり、之によりて愛といふことを知りたり、我等もまた兄弟のために生命を捨つべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, '世の財寶をもちて兄弟の窮乏を見、反つて憐憫の心を閉づる者は、いかで神の愛その衷にあらんや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, '若子よ、われら言と舌とをもて相 愛することなく、行爲と眞實とを以てすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, '之に由りて我ら眞理より出でしを知り、且われらの心われらを責むとも神の前に心を安んずべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, '神は我らの心よりも大にして一切のことを知り給へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, '愛する者よ、我らが心みづから責むる所なくば、神に向ひて懼なし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, '且すべて求むる所を神より受くべし。是その誡命を守りて御心にかなふ所を行へばなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'その誡命はこれなり、即ち我ら神の子イエス・キリストの名を信じ、その命じ給ひしごとく互に相 愛すべきことなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, '神の誡命を守る者は神に居り、神もまた彼に居給ふ。我らその賜ふところの御靈に由りて其の我らに居給ふことを知るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, '愛する者よ、凡ての靈を信ずな、その靈の神より出づるか否かを試みよ。多くの僞 預言者 世に出でたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, '凡そイエス・キリストの肉體にて來り給ひしことを言ひあらはす靈は神より出づ、なんぢら之によりて神の御靈を知るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, '凡そイエスを言ひ表さぬ靈は神より出でしにあらず、これは非キリストの靈なり。その來ることは汝ら聞けり、この靈いま既に世にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, '若子よ、汝らは神より出でし者にして既に彼らに勝てり。汝らに居給ふ者は世に居る者よりも大なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, '彼らは世より出でし者なり、之によりて世の事をかたり、世も亦かれらに聽く。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, '我らは神より出でし者なり。神を知る者は我らに聽き、神より出でぬ者は我らに聽かず。之によりて眞理の靈と迷謬の靈とを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, '愛する者よ、われら互に相 愛すべし。愛は神より出づ、おほよそ愛ある者は、神より生れ神を知るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, '愛なき者は、神を知らず、神は愛なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, '神の愛われらに顯れたり。神はその生み給へる獨子を世に遣し、我等をして彼によりて生命を得しめ給ふに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, '愛といふは、我ら神を愛せしにあらず、神われらを愛し、その子を遣して我らの罪のために宥の供物となし給ひし是なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, '愛する者よ、斯くのごとく神われらを愛し給ひたれば、我らも亦たがひに相 愛すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, '未だ神を見し者あらず、我等もし互に相 愛せば、神われらに在し、その愛も亦われらに全うせらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, '神、御靈を賜ひしに因りて、我ら神に居り神われらに居給ふことを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, '又われら父のその子を遣して世の救主となし給ひしを見て、その證をなすなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, '凡そイエスを神の子と言ひあらはす者は、神かれに居り、かれ神に居る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, '我らに對する神の愛を我ら既に知り、かつ信ず。神は愛なり、愛に居る者は神に居り、神も亦かれに居給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'かく我らの愛 完全をえて、審判の日に懼なからしむ。我等この世にありて主の如くなるに因る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, '愛には懼なし、全き愛は懼を除く、懼には苦難あればなり。懼るる者は、愛いまだ全からず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, '我らの愛するは、神まづ我らを愛し給ふによる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, '人もし『われ神を愛す』と言ひて、その兄弟を憎まば、これ僞 者なり。既に見るところの兄弟を愛せぬ者は、未だ見ぬ神を愛すること能はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, '神を愛する者は亦その兄弟をも愛すべし。我等この誡命を神より受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, '凡そイエスをキリストと信ずる者は、神より生れたるなり。おほよそ之を生み給ひし神を愛する者は、神より生れたる者をも愛す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, '我等もし神を愛して、その誡命を行はば、之によりて神の子供を愛することを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, '神の誡命を守るは即ち神を愛するなり、而してその誡命は難からず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'おほよそ神より生るる者は世に勝つ、世に勝つ勝利は我らの信仰なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, '世に勝つものは誰ぞ、イエスを神の子と信ずる者にあらずや。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'これ水と血とに由りて來り給ひし者、即ちイエス・キリストなり。啻に水のみならず、水と血とをもて來り給ひしなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, '證する者は御靈なり。御靈は眞理なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, '證する者は三つ、御靈と水と血となり。この三つ合ひて一つとなる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, '我等もし人の證を受けんには、神の證は更に大なり。神の證はその子につきて證し給ひし是なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, '神の子を信ずる者はその衷にこの證をもち、神を信ぜぬ者は神を僞 者とす。これ神その子につきて證せし證を信ぜぬが故なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'その證はこれなり、神は永遠の生命を我らに賜へり、この生命はその子にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, '御子をもつ者は生命をもち、神の子をもたぬ者は生命をもたず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'われ神の子の名を信ずる汝らに此 等のことを書き贈るは、汝らに自ら永遠の生命を有つことを知らしめん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, '我らが神に向ひて確信する所は是なり、即ち御意にかなふ事を求めば、必ず聽き給ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'かく求むるところ、何事にても聽き給ふと知れば、求めし願を得たる事をも知るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, '人もし其の兄弟の死に至らぬ罪を犯すを見ば、神に求むべし。さらば彼に、死に至らぬ罪を犯す人々に生命を與へ給はん。死に至る罪あり、我これに就きて請ふべしと言はず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, '凡ての不義は罪なり、されど死に至らぬ罪あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, '凡て神より生れたる者の罪を犯さぬことを我らは知る。神より生れ給ひし者、これを守りたまふ故に、惡しきもの觸るる事をせざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, '我らは神より出で、全世界は惡しき者に屬するを我らは知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'また神の子すでに來りて我らに眞の者を知る知識を賜ひしを我らは知る。而して我らは眞の者に居り、その子イエス・キリストに居るなり、彼は眞の神にして永遠の生命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, '若子よ、自ら守りて偶像に遠ざかれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, '長老、書を選ばれたる婦人および其の子供に贈る。われ眞をもて汝らを愛す。啻に我のみならず、凡て眞理を知る者はみな汝らを愛す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'これは我らの衷に止りて永遠に偕にあらんとする眞理に因りてなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, '父なる神および父の子イエス・キリストより賜ふ恩惠と憐憫と平安とは、眞と愛との中にて我らと偕にあらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'われ汝の子供のうちに、我らが父より誡命を受けし如く、眞理に循ひて歩む者あるを見て甚だ喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, '婦人よ、われ今なんぢに願ふは、我らが互に相 愛すべき事なり。これは新しき誡命を書き贈るにあらず、我らが初より有てる誡命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, '彼の誡命に循ひて歩むは即ち愛なり、汝らが初より聞きしごとく、愛に歩むは即ち誡命なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, '人を惑すもの多く世にいで、イエス・キリストの肉體にて來り給ひしことを言ひ表さず、かかる者は人を惑す者にして、非キリストなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'なんぢら我らが働きし所を空しくせず、滿ち足れる報を得んために自ら心せよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, '凡そキリストの教に居らずして、之を越えゆく者は神を有たず、キリストの教にをる者は父と子とを有つなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, '人もし此の教を有たずして汝らに來らば、之を家に入るな、安かれと言ふな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, '之に安かれと言ふ者は、その惡しき行爲に與するなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, '我なほ汝らに書き贈ること多くあれど、紙と墨とにてするを好まず、我らの歡喜を充さんために汝 等にいたり、顏をあわせて語らんことを望む。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, '選ばれたる汝の姉妹の子供、なんぢに安否を問ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, '長老、書を愛するガイオ、わが眞をもて愛する者に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, '愛する者よ、我なんぢが靈魂の榮ゆるごとく汝すべての事に榮え、かつ健かならんことを祈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, '兄弟たち來りて汝が眞理を保つこと、即ち眞理に循ひて歩むことを證したれば、われ甚だ喜べり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, '我には我が子供の、眞理に循ひて歩むことを聞くより大なる喜悦はなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, '愛する者よ、なんぢ旅人なる兄弟たちにまで行ふ所みな忠實をもて爲せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'かれら教會の前にて汝の愛につきて證せり。なんぢ神の御意に適ふやうに彼らを見 送らば、その行ふところ善からん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, '彼らは異邦人より何をも受けずして御名のために旅立せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'されば斯かる人を助くべきなり、我らも彼らと共に眞理のために働く者とならん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'われ曩に聊か教會に書きおくれり。然れど彼らの中に長たらんと欲するデオテレペス我らを受けず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'この故に我もし往かば、その行へる業を思ひ出させん。彼は惡しき言をもて我らを罵り、なほ足れりとせずして自ら兄弟たちを接けず、之を接けんとする者をも拒みて教會より逐ひ出す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, '愛する者よ、惡に效ふな、善にならへ。善をおこなふ者は神より出で、惡をおこなふ者は未だ神を見ざるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'デメテリオは凡ての人にも眞理にも證せらる。我等もまた證す、なんぢ我らの證の眞なるを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, '我なほ汝に書き贈ること多くあれど、墨と筆とにてするを欲せず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, '速かに汝を見、たがひに顏をあはせて語らんことを望む。 汝に平安あれ、朋友たち安否を問ふ。なんぢ名をさして友たちに安否を問へ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'イエス・キリストの僕にしてヤコブの兄弟なるユダ、書を召されたる者、すなはち父なる神に愛せられ、イエス・キリストの爲に守らるる者に贈る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, '願はくは憐憫と平安と愛と、なんぢらに増さんことを。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, '愛する者よ、われ我らが共に與る救につき勵みて汝らに書き贈らんとせしが、聖徒の一たび傳へられたる信仰のために戰はんことを勸むる書を、汝らに贈るを必要と思へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'そは敬虔ならずして我らの神の恩惠を好色に易へ、唯一の主なる我らの主イエス・キリストを否むものども潜り入りたればなり。彼らが此の審判を受くべきことは昔より預じめ録されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, '汝らは固より凡ての事を知れど、我さらに汝 等をして思ひ出さしめんとする事あり、即ち主エジプトの地より民を救ひ出して、後に信ぜぬ者を亡し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, '又おのが位を保たずして己が居所を離れたる御使を、大なる日の審判まで、闇黒のうちに長久の繩目をもて看守し給へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'ソドム、ゴモラ及びその周圍の町々も亦これと同じく、淫行に耽り、背倫の肉 慾に走り、永遠の火の刑罰をうけて鑑とせられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'かくの如くかの夢 見る者どもも肉を汚し、權威ある者を輕んじ、尊き者を罵る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, '御使の長ミカエル惡魔と論じてモーセの屍體を爭ひし時に、敢へて罵りて審かず、唯『ねがはくは主なんぢを戒め給はんことを』と云へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'されど此の人々は知らぬことを罵り、無知の獸のごとく、自然に知る所によりて亡ぶるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, '禍害なるかな、彼らはカインの道にゆき、利のためにバラムの迷に走り、またコラの如き謀反によりて亡びたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, '彼らは汝らと共に宴席に與り、その愛餐の暗礁たり、憚らずして自己をやしなふ牧者、風に逐はるる水なき雲、枯れて又かれ、根より拔かれたる果なき秋の木、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'おのが恥を湧き出す海のあらき波、さまよふ星なり。彼らの爲に暗き闇、とこしへに蓄へ置かれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'アダムより七代に當るエノク彼らに就きて預言せり。曰く『視よ、主はその聖なる千萬の衆を率ゐて來りたまへり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'これ凡ての人の審判をなし、すべて敬虔ならぬ者の不 敬虔を行ひたる不 敬虔の凡ての業と、敬虔ならぬ罪人の、主に逆ひて語りたる凡ての甚だしき言とを責め給はんとてなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, '彼らは呟くもの、不滿をならす者にして、おのが慾に隨ひて歩み、口に誇をかたり、利のために人に諂ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, '愛する者よ、汝らは我らの主イエス・キリストの使徒たちの預じめ言ひし言を憶えよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, '即ち汝らに曰らく『末の時に嘲る者おこり、己が不 敬虔なる慾に隨ひて歩まん』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, '彼らは分裂をなし、情 慾に屬し、御靈を有たぬ者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'されど愛する者よ、なんぢらは己がいと潔き信仰の上に徳を建て、聖 靈によりて祈り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, '神の愛のうちに己をまもり、永遠の生命を得るまで我らの主イエス・キリストの憐憫を待て。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'また彼らの中なる疑ふ者をあはれみ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, '或 者を火より取出して救ひ、或 者をその肉に汚れたる下衣をも厭ひ、かつ懼れつつ憐め。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, '願はくは汝らを守りて躓かしめず、瑕なくして榮光の御前に歡喜をもて立つことを得しめ給ふ者、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, '即ち我らの救主なる唯一の神に、榮光・稜威・權力・權威、われらの主イエス・キリストに由りて、萬 世の前にも今も萬 世までも在らんことを、アァメン');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'これイエス・キリストの默示なり。即ち、かならず速かに起るべき事を、その僕どもに顯させんとて、神の彼に與へしものなるを、彼その使を僕ヨハネに遣して示し給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'ヨハネは神の言とイエス・キリストの證とに就きて、その見しところを悉とく證せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, '此の預言の言を讀む者と之を聽きて其の中に録されたることを守る者どもとは幸福なり、時 近ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'ヨハネ書をアジヤに在る七つの教會に贈る。願はくは今 在し、昔 在し、後 來りたまふ者、および其の御座の前にある七つの靈、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'また忠實なる證人、死人の中より最先に生れ給ひしもの、地の諸 王の君なるイエス・キリストより賜ふ恩惠と平安と汝らに在らんことを。願はくは我らを愛し、その血をもて我らを罪より解放ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'われらを其の父なる神のために國民となし祭司となし給へる者に、世々 限りなく榮光と權力とあらんことを、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, '視よ、彼は雲の中にありて來りたまふ、諸衆の目、殊に彼を刺したる者これを見ん、かつ地上の諸族みな彼の故に歎かん、然り、アァメン。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, '今いまし、昔いまし、後きたり給ふ主なる全能の神いひ給ふ『我はアルパなり、オメガなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, '汝らの兄弟にして汝らと共にイエスの艱難と國と忍耐とに與る我ヨハネ、神の言とイエスの證との爲にパトモスといふ島に在りき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'われ主日に御靈に感じゐたるに、我が後にラッパのごとき大なる聲を聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, '曰く『なんぢの見る所のことを書に録して、エペソ、スミルナ、ペルガモ、テアテラ、サルデス、ヒラデルヒヤ、ラオデキヤに在る七つの教會に贈れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'われ振反りて我に語る聲を見んとし、振反り見れば七つの金の燈臺あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'また燈臺の間に人の子のごとき者ありて、足まで垂るる衣を著、胸に金の帶を束ね、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'その頭と頭髮とは白き毛のごとく雪のごとく白く、その目は焔のごとく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'その足は爐にて燒きたる輝ける眞鍮のごとく、その聲は衆の水の聲のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'その右の手に七つの星を持ち、その口より兩刃の利き劍いで、その顏は烈しく照る日のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, '我これを見しとき其の足下に倒れて死にたる者の如くなれり。彼その右の手を我に按きて言ひたまふ『懼るな、我は最先なり、最後なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, '活ける者なり、われ曾て死にたりしが、視よ、世々 限りなく生く。また死と陰府との鍵を有てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'されば汝が見しことと今あることと、後に成らんとする事とを録せ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, '即ち汝が見しところの我が右の手にある七つの星と七つの金の燈臺との奧義なり。七つの星は七つの教會の使にして、七つの燈臺は七つの教會なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'エペソに在る教會の使に書きおくれ。「右の手に七つの星を持つ者、七つの金の燈臺の間に歩むもの斯く言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'われ汝の行爲と勞と忍耐とを知る。また汝が惡しき者を忍び得ざることと、自ら使徒と稱へて使徒にあらぬ者どもを試みて、その虚僞なるを見あらはししこととを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'なんぢは忍耐を保ち、我が名のために忍びて倦まざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'されど我なんぢに責むべき所あり、なんぢは初の愛を離れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'さればなんぢ何處より墜ちしかを思へ、悔改めて初の行爲をなせ、然らずして若し悔改めずば、我なんぢに到り汝の燈臺を、その處より取除かん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'されど汝に取るべき所あり、汝はニコライ宗の行爲を憎む、我も之を憎むなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, '耳ある者は御靈の諸 教會に言ひ給ふことを聽くべし、勝を得る者には、われ神のパラダイスに在る生命の樹の實を食ふことを許さん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'スミルナに在る教會の使に書きおくれ。「最先にして最後なる者、死人となりて復 生きし者かく言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'われ汝の艱難と貧窮とを知る――されど汝は富める者なり。我はまた自らユダヤ人と稱へてユダヤ人にあらず、サタンの會に屬く者より汝が譏を受くるを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'なんぢ受けんとする苦難を懼るな、視よ、惡魔なんぢらを試みんとて、汝らの中の或 者を獄に入れんとす。汝ら十日のあひだ患難を受けん、なんぢ死に至るまで忠實なれ、然らば我なんぢに生命の冠冕を與へん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, '耳ある者は御靈の諸 教會に言ひ給ふことを聽くべし。勝を得るものは第二の死に害はるることなし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'ペルガモに在る教會の使に書きおくれ。「兩刃の利き劍を持つもの斯く言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'われ汝の住むところを知る、彼處にはサタンの座位あり、汝わが名を保ち、わが忠實なる證人アンテパスが、汝 等のうち即ちサタンの住む所にて殺されし時も、なほ我を信ずる信仰を棄てざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'されど我なんぢに責むべき一二の事あり、汝の中にバラムの教を保つ者どもあり、バラムはバラクに教へ、彼をしてイスラエルの子孫の前に躓物を置かしめ、偶像に献げし物を食はせ、かつ淫行をなさしめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, '斯くのごとく汝らの中にもニコライ宗の教を保つ者あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'さらば悔改めよ、然らずば我すみやかに汝に到り、わが口の劍にて彼らと戰はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, '耳ある者は御靈の諸 教會に言ひ給ふことを聽くべし、勝を得る者には我かくれたるマナを與へん、また受くる者の外たれも知らざる新しき名を録したる白き石を與へん」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'テアテラに在る教會の使に書きおくれ。「目は焔のごとく、足は輝ける眞鍮の如くなる神の子かく言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'われ汝の行爲および汝の愛と信仰と職と忍耐とを知る、又なんぢの初の行爲よりは後の行爲の多きことを知る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'されど我なんぢに責むべき所あり、汝はかの自ら預言者と稱へて我が僕を教へ惑し、淫行をなさしめ、偶像に献げし物を食はしむる女イゼベルを容れおけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, '我かれに悔改むる機を與ふれど、その淫行を悔改むることを欲せず。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, '視よ、我かれを牀に投げ入れん、又かれと共に姦淫を行ふ者も、その行爲を悔改めずば、大なる患難に投げ入れん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, '又かれの子供を打ち殺さん、斯くてもろもろの教會は、わが人の腎と心とを究むる者なるを知るべし、我は汝 等おのおのの行爲に隨ひて報いん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, '我この他のテアテラの人にして未だかの教を受けず、所謂サタンの深きところを知らぬ汝らに斯くいふ、我ほかの重を汝らに負はせじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'ただ汝 等はその有つところを我が到らん時まで保て。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, '勝を得て終に至るまで我が命ぜしことを守る者には、諸國の民を治むる權威を與へん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, '彼は鐵の杖をもて之を治め、土の器を碎くが如くならん、我が父より我が受けたる權威のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, '我また彼に曙の明星を與へん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, '耳ある者は御靈の諸 教會に言ひ給ふことを聽くべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'サルデスに在る教會の使に書きおくれ。「神の七つの靈と七つの星とを持つ者かく言ふ、われ汝の行爲を知る、汝は生くる名あれど死にたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'なんぢ目を覺し、殆ど死なんとする殘のものを堅うせよ、我なんぢの行爲のわが神の前に全からぬを見とめたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'されば汝の如何に受けしか、如何に聽きしかを思ひいで、之を守りて悔改めよ。もし目を覺さずば、盜人のごとく我きたらん、汝わが何れの時きたるかを知らざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'されどサルデスにて衣を汚さぬもの數名あり、彼らは白き衣を著て我とともに歩まん、斯くするに相應しき者なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, '勝を得る者は斯くのごとく白き衣を著せられん、我その名を生命の書より消し落さず、我が父のまへと御使の前とにてその名を言ひあらはさん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, '耳ある者は御靈の諸 教會に言ひ給ふことを聽くべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'ヒラデルヒヤにある教會の使に書きおくれ。「聖なるもの眞なる者、ダビデの鍵を持ちて、開けば閉づる者なく、閉づれば開く者なき者かく言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'われ汝の行爲を知る、視よ、我なんぢの前に開けたる門を置く、これを閉ぢ得る者なし。汝すこしの力ありて、我が言を守り、我が名を否まざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, '視よ、我サタンの會、すなはち自らユダヤ人と稱へてユダヤ人にあらず、ただ虚僞をいふ者の中より、或 者をして汝の足下に來り拜せしめ、わが汝を愛せしことを知らしめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, '汝わが忍耐の言を守りし故に、我なんぢを守りて、地に住む者どもを試むるために全世界に來らんとする試錬のときに免れしめん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'われ速かに來らん、汝の有つものを守りて、汝の冠冕を人に奪はれざれ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'われ勝を得る者を我が神の聖所の柱とせん、彼は再び外に出でざるべし、又かれの上に、わが神の名および我が神の都、すなはち天より我が神より降る新しきエルサレムの名と、我が新しき名とを書き記さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, '耳ある者は御靈の諸 教會に言ひ給ふことを聽くべし」');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'ラオデキヤに在る教會の使に書きおくれ。「アァメンたる者、忠實なる眞なる證人、神の造り給ふものの本源たる者かく言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'われ汝の行爲を知る、なんぢは冷かにもあらず熱きにもあらず、我はむしろ汝が冷かならんか、熱からんかを願ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'かく熱きにもあらず、冷かにもあらず、ただ微温きが故に、我なんぢを我が口より吐き出さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'なんぢ、我は富めり、豐なり、乏しき所なしと言ひて、己が惱める者・憐むべき者・貧しき者・盲目なる者・裸なる者たるを知らざれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, '我なんぢに勸む、なんぢ我より火にて煉りたる金を買ひて富め、白き衣を買ひて身に纏ひ、なんぢの裸體の恥を露さざれ、眼藥を買ひて汝の目に塗り、見ることを得よ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, '凡てわが愛する者は、我これを戒め之を懲す。この故に、なんぢ勵みて悔改めよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, '視よ、われ戸の外に立ちて叩く、人もし我が聲を聞きて戸を開かば、我その内に入りて彼とともに食し、彼もまた我とともに食せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, '勝を得る者には我とともに我が座位に坐することを許さん、我の勝を得しとき、我が父とともに其の御座に坐したるが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, '耳ある者は御靈の諸 教會に言ひ給ふことを聽くべし」』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'この後われ見しに、視よ、天に開けたる門あり。初に我に語るを聞きしラッパのごとき聲いふ『ここに登れ、我この後おこるべき事を汝に示さん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, '直ちに、われ御靈に感ぜしが、視よ、天に御座 設けあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'その御座に坐したまふ者あり、その坐し給ふものの状は碧玉・赤瑪瑙のごとく、かつ御座の周圍には緑玉のごとき虹ありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'また御座のまはりに二十四の座位ありて、二十四人の長老、白き衣を纏ひ、首に金の冠冕を戴きて、その座位に坐せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, '御座より數多の電光と聲と雷霆と出づ。また御座の前に燃えたる七つの燈火あり、これ神の七つの靈なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, '御座のまへに水晶に似たる玻璃の海あり。御座の中央と御座の周圍とに四つの活物ありて、前も後も數々の目にて滿ちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, '第一の活物は獅子のごとく、第二の活物は牛のごとく、第三の活物は面のかたち人のごとく、第四の活物は飛ぶ鷲のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'この四つの活物おのおの六つの翼あり、翼の内も外も數々の目にて滿ちたり、日も夜も絶間なく言ふ、『聖なるかな、聖なるかな、聖なるかな、昔いまし、今いまし、のち來りたまふ主たる全能の神』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'この活物ら御座に坐し、世々 限りなく活きたまふ者に榮光と尊崇とを歸し、感謝する時、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, '二十四人の長老、御座に坐したまふ者のまへに伏し、世々 限りなく活きたまふ者を拜し、おのれの冠冕を御座のまへに投げ出して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '『我らの主なる神よ、榮光と尊崇と能力とを受け給ふは宜なり。汝は萬物を造りたまひ、萬物は御意によりて存し、かつ造られたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, '我また御座に坐し給ふ者の右の手に、卷 物のあるを見たり、その裏表に文字あり、七つの印をもて封ぜらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'また大聲に『卷 物を開きてその封印を解くに相應しき者は誰ぞ』と呼はる強き御使を見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, '然るに天にも地にも、地の下にも、卷 物を開きて之を見 得る者なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, '卷 物を開き、これを見るに相應しき者の見えざりしに因りて、我いたく泣きゐたりしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, '長老の一人われに言ふ『泣くな、視よ、ユダの族の獅子・ダビデの萠蘗、すでに勝を得て卷 物とその七つの封印とを開き得るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, '我また御座および四つの活物と長老たちとの間に、屠られたるが如き羔羊の立てるを見たり、之に七つの角と七つの目とあり、この目は全世界に遣されたる神の七つの靈なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'かれ來りて御座に坐したまふ者の右の手より卷 物を受けたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, '卷 物を受けたるとき、四つの活物および二十四人の長老、おのおの立琴と香の滿ちたる金の鉢とをもちて、羔羊の前に平伏せり、此の香は聖徒の祈祷なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'かくて新しき歌を謳ひて言ふ『なんぢは卷 物を受け、その封印を解くに相應しきなり、汝は屠られ、その血をもて諸種の族・國語・民・國の中より人々を神のために買ひ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, '之を我らの神のために國民となし、祭司となし給へばなり。彼らは地の上に王となるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, '我また見しに、御座と活物と長老たちとの周圍にをる多くの御使の聲を聞けり。その數、千々萬々にして、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, '大聲にいふ『屠られ給ひし羔羊こそ、能力と富と知慧と、勢威と尊崇と、榮光と讃美とを受くるに相應しけれ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, '我また天に、地に、地の下に、海にある萬の造られたる物、また凡てその中にある物の云へるを聞けり。曰く『願はくは御座に坐し給ふものと羔羊とに、讃美と尊崇と榮光と權力と世々 限りなくあらん事を』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, '四つの活物はアァメンと言ひ、長老たちは平伏して拜せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, '羔羊その七つの封印の一つを解き給ひし時、われ見しに、四つの活物の一つが雷霆のごとき聲して『來れ』と言ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'また見しに、視よ、白き馬あり、之に乘るもの弓を持ち、かつ冠冕を與へられ、勝ちて復 勝たんとて出でゆけり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, '第二の封印を解き給ひたれば、第二の活物の『來れ』と言ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'かくて赤き馬いで來り、これに乘るもの地より平和を奪ひ取ることと、人をして互に殺さしむる事とを許され、また大なる劍を與へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, '第三の封印を解き給ひたれば、第三の活物の『來れ』と言ふを聞けり。われ見しに、視よ、黒き馬あり、之に乘るもの手に權衝を持てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'かくてわれ四つの活物の間より出づるごとき聲を聞けり。曰く『小麥 五合は一デナリ、大麥 一升 五合は一デナリなり、油と葡萄酒とを害ふな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, '第四の封印を解き給ひたれば、第四の活物の『來れ』と言ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'われ見しに、視よ、青ざめたる馬あり、之に乘る者の名を死といひ、陰府これに隨ふ。かれらは地の四 分の一を支配し、劍と饑饉と死と地の獸とをもて人を殺すことを許されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, '第五の封印を解き給ひたれば、曾て神の言のため、又その立てし證のために殺されし者の靈魂の祭壇の下に在るを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, '彼ら大聲に呼はりて言ふ『聖にして眞なる主よ、何時まで審かずして地に住む者に我らの血の復讐をなし給はぬか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'ここにおのおの白き衣を與へられ、かつ己 等のごとく殺されんとする同じ僕たる者と兄弟との數の滿つるまで、なほ暫く安んじて待つべきを言ひ聞けられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, '第六の封印を解き給ひし時、われ見しに、大なる地震ありて日は荒き毛 布のごとく黒く、月は全面 血の如くなり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, '天の星は無花果の樹の大風に搖られて、生り後の果の落つるごとく地におち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, '天は卷 物を卷くごとく去りゆき、山と島とは悉とくその處を移されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, '地の王たち・大臣・將校・富める者・強き者・奴隷・自主の人、みな洞と山の巖間とに匿れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, '山と巖とに對ひて言ふ『請ふ、我らの上に墜ちて御座に坐したまふ者の御顏より、羔羊の怒より、我らを隱せ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'そは御怒の大なる日 既に來ればなり。誰か立つことを得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'この後、われ四人の御使の地の四隅に立つを見たり、彼らは地の四方の風を引止めて、地にも海にも諸種の樹にも風を吹かせざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'また他の一人の御使の、活ける神の印を持ちて日の出づる方より登るを見たり、かれ地と海とを害ふ權を與へられたる四人の御使にむかひ、大聲に呼はりて言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, '『われらが我らの神の僕の額に印するまでは、地をも海をも樹をも害ふな』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'われ印せられたる者の數を聽きしに、イスラエルの子 等のもろもろの族の中にて印せられたるもの合せて十四萬 四千あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'ユダの族の中にて一萬 二千 印せられ、ルベンの族の中にて一萬 二千、ガドの族の中にて一萬 二千、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'アセルの族の中にて一萬 二千、ナフタリの族の中にて一萬 二千、マナセの族の中にて一萬 二千、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'シメオンの族の中にて一萬 二千、レビの族の中にて一萬 二千、イサカルの族の中にて一萬 二千、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'ゼブルンの族の中にて一萬 二千、ヨセフの族の中にて一萬 二千、ベニヤミンの族の中にて一萬 二千 印せられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'この後われ見しに、視よ、もろもろの國・族・民・國語の中より、誰も數へつくすこと能はぬ大なる群衆、しろき衣を纏ひて手に棕梠の葉をもち、御座と羔羊との前に立ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, '大聲に呼はりて言ふ『救は御座に坐したまふ我らの神と羔羊とにこそ在れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, '御使みな御座および長老たちと四つの活物との周圍に立ちて、御座の前に平伏し神を拜して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, '『アァメン、讃美・榮光・知慧・感謝・尊貴・能力・勢威、世々 限りなく我らの神にあれ、アァメン』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, '長老たちの一人われに向ひて言ふ『この白き衣を著たるは如何なる者にして何處より來りしか』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, '我いふ『わが主よ、なんぢ知れり』かれ言ふ『かれらは大なる患難より出できたり、羔羊の血に己が衣を洗ひて白くしたる者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'この故に神の御座の前にありて、晝も夜もその聖所にて神に事ふ。御座に坐したまふ者は彼らの上に幕屋を張り給ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, '彼らは重ねて飢ゑず、重ねて渇かず、日も熱も彼らを侵すことなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, '御座の前にいます羔羊は、彼らを牧して生命の水の泉にみちびき、神は彼らの目より凡ての涙を拭ひ給ふべければなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, '第七の封印を解き給ひたれば、凡そ半時のあひだ天 靜なりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'われ神の前に立てる七人の御使を見たり、彼らは七つのラッパを與へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'また他の一人の御使、金の香爐を持ちきたりて祭壇の前に立ち、多くの香を與へられたり。これは凡ての聖徒の祈に加へて、御座の前なる金の香壇の上に献げんためなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, '而して香の煙、御使の手より聖徒たちの祈とともに神の前に上れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, '御使その香爐をとり、之に祭壇の火を盛りて地に投げたれば、數多の雷霆と聲と電光と、また地震おこれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'ここに七つのラッパをもてる七人の御使これを吹く備をなせり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, '第一の御使ラッパを吹きしに、血の混りたる雹と火とありて、地にふりくだり、地の三分の一 燒け失せ、樹の三分の一 燒け失せ、もろもろの青 草 燒け失せたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, '第二の御使ラッパを吹きしに、火にて燃ゆる大なる山の如きもの海に投げ入れられ、海の三分の一 血に變じ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, '海の中の造られたる生命あるものの三分の一 死に、船の三分の一 滅びたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, '第三の御使ラッパを吹きしに、燈火のごとく燃ゆる大なる星、天より隕ちきたり、川の三分の一と水の源泉との上におちたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'この星の名は苦艾といふ。水の三分の一は苦艾となり、水の苦くなりしに因りて多くの人 死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, '第四の御使ラッパを吹きしに、日の三分の一と月の三分の一と星の三分の一と撃たれて、その三分の一は暗くなり、晝も三分の一は光なく、夜も亦おなじ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'また見しに、一つの鷲の中空を飛び、大なる聲して言ふを聞けり。曰く『地に住める者どもは禍害なるかな、禍害なるかな、禍害なるかな、尚ほかに三人の御使の吹かんとするラッパの聲あるに因りてなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, '第五の御使ラッパを吹きしに、われ一つの星の天より地に隕ちたるを見たり。この星は底なき坑の鍵を與へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'かくて底なき坑を開きたれば、大なる爐の煙のごとき煙、坑より立ちのぼり、日も空も坑の煙にて暗くなれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, '煙の中より蝗 地上に出でて、地の蝎のもてる力のごとき力を與へられ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, '地の草すべての青きもの又すべての樹を害ふことなく、ただ額に神の印なき人をのみ害ふことを命ぜられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'されど彼らを殺すことを許されず、五月のあひだ苦しむることを許さる、その苦痛は、蝎に刺されたる苦痛のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'このとき人々、死を求むとも見出さず、死なんと欲すとも死は逃げ去るべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'かの蝗の形は戰爭の爲に具へたる馬のごとく、頭には金に似たる冠冕の如きものあり、顏は人の顏のごとく、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, '之に女の頭髮のごとき頭髮あり、齒は獅子の齒のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'また鐵の胸當のごとき胸當あり、その翼の音は軍車の轟くごとく、多くの馬の戰鬪に馳せゆくが如し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'また蝎のごとき尾ありて之に刺あり、この尾に五月のあひだ人を害ふ力あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'この蝗に王あり。底なき所の使にして、名をヘブル語にてアバドンと云ひ、ギリシヤ語にてアポルオンと云ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, '第一の禍害すぎ去れり、視よ、此の後なほ二つの禍害きたらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, '第六の御使ラッパを吹きしに、神の前なる金の香壇の四つの角より聲ありて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'ラッパを持てる第六の御使に『大なるユウフラテ川の邊に繋がれをる四人の御使を解放て』と言ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'かくてその時その日その月その年に至りて、人の三分の一を殺さん爲に備へられたる四人の御使は解放たれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, '騎兵の數は二億なり、我その數を聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'われ幻影にてその馬と之に乘る者とを見しに、彼らは火・煙・硫黄の色したる胸當を著く。馬の頭は獅子の頭のごとくにて、その口よりは火と煙と硫黄と出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'この三つの苦痛、すなはち其の口より出づる火と煙と硫黄とに因りて、人の三分の一 殺されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, '馬の力はその口とその尾とにあり、その尾は蛇の如くにして頭あり、之をもて人を害ふなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'これらの苦痛にて殺されざりし殘の人々は、おのが手の業を悔改めずして、なほ惡鬼を拜し、見ること聞くこと歩むこと能はぬ、金・銀・銅・石・木の偶像を拜せり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, '又その殺人・咒術・淫行・竊盜を悔改めざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, '我また一人の強き御使の、雲を著て天より降るを見たり。その頭の上に虹あり、その顏は日の如く、その足は火の柱のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'その手には展きたる小き卷 物をもち、右の足を海の上におき、左の足を地の上におき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, '獅子の吼ゆる如く大聲に呼はれり、呼はりたるとき七つの雷霆おのおの聲を出せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, '七つの雷霆の語りし時、われ書き記さんとせしに、天より聲ありて『七つの雷霆の語りしことは封じて書き記すな』といふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'かくて我が見しところの海と地とに跨り立てる御使は、天にむかひて右の手を擧げ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, '天および其の中に在るもの、地および其の中にあるもの、海および其の中にある物を造り給ひし、世々 限りなく生きたまふ者を指し、誓ひて言ふ『この後、時は延ぶることなし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, '第七の御使の吹かんとするラッパの聲の出づる時に至りて、神の僕なる預言者たちに示し給ひし如く、その奧義は成就せらるべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'かくて我が前に天より聞きし聲のまた我に語りて『なんぢ往きて、海と地とに跨り立てる御使の手にある展きたる卷 物を取れ』と言ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'われ御使のもとに往きて、小き卷 物を我に與へんことを請ひたれば、彼いふ『これを取りて食ひ盡せ、さらば汝の腹 苦くならん、然れど其の口には蜜のごとく甘からん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'われ御使の手より小き卷 物をとりて食ひ盡したれば、口には蜜のごとく甘かりしが、食ひし後わが腹は苦くなれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'また或 物われに言ふ『なんぢ再び多くの民・國・國語・王たちに就きて預言すべし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'ここにわれ杖のごとき間竿を與へられたり、かくて或 者いふ『立ちて神の聖所と香壇と其處に拜する者どもとを度れ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, '聖所の外の庭は差措きて度るな、これは異邦人に委ねられたり、彼らは四十 二个月のあひだ聖なる都を蹂躙らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, '我わが二人の證人に權を與へん、彼らは荒布を著て千二百 六十日のあひだ預言すべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, '彼らは地の主の御前に立てる二つのオリブの樹、二つの燈臺なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'もし彼らを害はんとする者あらば、火その口より出でてその敵を焚き盡さん。もし彼らを害はんとする者あらば、必ず斯くのごとく殺さるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, '彼らは預言するあひだ雨を降らせぬやうに天を閉づる權力あり、また水を血に變らせ、思ふままに幾度にても諸種の苦難をもて地を撃つ權力あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, '彼 等がその證を終へんとき、底なき所より上る獸ありて之と戰鬪をなし、勝ちて之を殺さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'その屍體は大なる都の衢に遺らん。この都を譬へてソドムと云ひ、エジプトの云ふ、即ち彼らの主もまた十字架に釘けられ給ひし所なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'もろもろの民・族・國語・國のもの、三日半の間その屍體を見、かつ其の屍體を墓に葬ることを許さざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, '地に住む者どもは彼らに就きて喜び樂しみ互に禮物を贈らん、此の二人の預言者は地に住む者を苦しめたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, '三日半ののち生命の息、神より出でて彼らに入り、かれら足にて起ちたれば、之を見るもの大に懼れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, '天より大なる聲して『ここに昇れ』と言ふを彼ら聞きたれば、雲に乘りて天に昇れり、その敵も之を見たり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'このとき大なる地震ありて、都の十分の一は倒れ、地震のために死にしもの七 千 人にして、遺れる者は懼をいだき天の神に榮光を歸したり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, '第二の禍害すぎ去れり、視よ、第三の禍害すみやかに來るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, '第七の御使ラッパを吹きしに、天に數多の大なる聲ありて『この世の國は我らの主および其のキリストの國となれり。彼は世々 限りなく王たらん』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'かくて神の前にて座位に坐する二十四人の長老ひれふし神を拜して言ふ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, '『今いまし、昔います主たる全能の神よ、なんぢの大なる能力を執りて王と成り給ひしことを感謝す。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, '諸國の民 怒をいだけり、なんぢの怒も亦いたれり、死にたる者を審き、なんぢの僕なる預言者および聖徒、また小なるも大なるも汝の名を畏るる者に報賞をあたへ、地を亡す者を亡したまふ時いたれり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, '斯くて天にある神の聖所ひらけ、聖所のうちに契約の櫃 見え、數多の電光と聲と雷霆と、また地震と大なる雹とありき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'また天に大なる徴 見えたり。日を著たる女ありて、其の足の下に月あり、其の頭に十二の星の冠冕あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'かれは孕りをりしが、子を産まんとして産みの苦痛と惱とのために叫べり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'また天に他の徴 見えたり。視よ、大なる赤き龍あり、これに七つの頭と十の角とありて、頭には七つの冠冕あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'その尾は天の星の三分の一を引きて之を地に落せり。龍は子を産まんとする女の前に立ち、産むを待ちて其の子を食ひ盡さんと構へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, '女は男子を産めり、この子は鐵の杖もて諸種の國人を治めん。かれは神の許に、その御座の下に擧げられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, '女は荒野に逃げゆけり。彼處に千二百 六十日の間かれが養はるる爲に神の備へ給へる所あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'かくて天に戰爭おこれり、ミカエル及びその使たち龍とたたかふ。龍もその使たちも之と戰ひしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, '勝つこと能はず、天には、はや其の居る所なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'かの大なる龍、すなわち惡魔と呼ばれ、サタンと呼ばれたる全世界をまどはす古き蛇は落され、地に落され、その使たちも共に落されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, '我また天に大なる聲ありて『われらの神の救と能力と國と神のキリストの權威とは、今すでに來れり。我らの兄弟を訴へ夜晝われらの神の前に訴ふるもの落されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, '而して兄弟たちは羔羊の血と己が證の言とによりて勝ち、死に至るまで己が生命を惜まざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'この故に天および天に住める者よ、よろこべ、地と海とは禍害なるかな、惡魔おのが時の暫時なるを知り、大なる憤恚をいだきて汝 等のもとに下りたればなり』と云ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'かくて龍はおのが地に落されしを見て、男子を生みし女を責めたりしが、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, '女は荒野なる己が處に飛ぶために、大なる鷲の兩の翼を與へられたれば、其處にいたり、一年、二年、また半年のあひだ蛇のまへを離れて養はれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, '蛇はその口より水を川のごとく、女の背後に吐きて之を流さんとしたれど、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, '地は女を助け、その口を開きて龍の口より吐きたる川を呑み盡せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, '龍は女を怒りてその裔の殘れるもの、即ち神の誡命を守りイエスの證を有てる者に、戰鬪を挑まんとて出でゆき、 海邊の砂の上に立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, '我また一つの獸の海より上るを見たり。之に十の角と七つの頭とあり、その角に十の冠冕あり、頭の上には神を涜す名あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'わが見し獸は豹に似て、その足は熊のごとく、その口は獅子の口のごとし。龍はこれに己が能力と己が座位と大なる權威とを與へたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, '我その頭の一つ傷つけられて死ぬばかりなるを見しが、その死ぬべき傷いやされたれば、全地の者これを怪しみて獸に從へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'また龍おのが權威を獸に與へしによりて、彼ら龍を拜し、且その獸を拜して言ふ『たれか此の獸に等しき者あらん、誰か之と戰ふことを得ん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, '獸また大言と涜言とを語る口を與へられ、四十 二个月のあひだ働く權威を與へらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, '彼は口をひらきて神を涜し、又その御名とその幕屋すなはち天に住む者どもとを涜し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'また聖徒に戰鬪を挑みて、之に勝つことを許され、且もろもろの族・民・國語・國を掌どる權威を與へらる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, '凡て地に住む者にて、其の名を屠られ給ひし羔羊の生命の書に、世の創より記されざる者は、これを拜せん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, '人もし耳あらば聽くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, '虜にせらるべき者は虜にせられん、劍にて殺す者はおのれも劍にて殺さるべし、聖徒たちの忍耐と信仰とは茲にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, '我また他の獸の地より上るを見たり。これに羔羊のごとき角 二つありて龍のごとく語り、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, '先の獸の凡ての權威を彼の前にて行ひ、地と地に住む者とをして死ぬべき傷の醫されたる先の獸を拜せしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'また大なる徴をおこなひ、人々の前にて火を天より地に降らせ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'かの獸の前にて行ふことを許されし徴をもて地に住む者どもを惑し、劍にうたれてなほ生ける獸の像を造ることを地に住む者どもに命じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, '而してその獸の像に息を與へて物 言はしめ、且その獸の像を拜せぬ者をことごとく殺さしむる事を許され、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'また凡ての人をして、大小・貧富・自主・奴隷の別なく、或はその右の手、あるいは其の額に徽章を受けしむ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'この徽章を有たぬ凡ての者に賣買することを得ざらしめたり。その徽章は獸の名、もしくは其の名の數字なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, '智慧は茲にあり、心ある者は獸の數字を算へよ。獸の數字は人の數字にして、その數字は六 百 六十 六なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'われ見しに、視よ、羔羊シオンの山に立ちたまふ。十四萬 四千の人これと偕に居り、その額には羔羊の名および羔羊の父の名 記しあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'われ天よりの聲を聞けり、多くの水の音のごとく、大なる雷霆の聲のごとし。わが聞きし此の聲は彈琴者の立琴を彈く音のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'かれら新しき歌を御座の前および四つの活物と長老たちとの前にて歌ふ。この歌は地より贖はれたる十四萬 四千 人の他は誰も學びうる者なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, '彼らは女に汚されぬ者なり、潔き者なり、何處にまれ羔羊の往き給ふところに隨ふ。彼らは人の中より贖はれて神と羔羊とのために初穗となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'その口に虚僞なし、彼らは瑕なき者なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, '我また他の御使の中空を飛ぶを見たり。かれは地に住むもの、即ちもろもろの國・族・國語・民に宣傳へんとて、永遠の福音を携へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, '大聲にて言ふ『なんぢら神を畏れ、神に榮光を歸せよ。その審判のとき既に至りたればなり。汝ら天と地と海と水の源泉とを造り給ひし者を拜せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'ほかの第二の御使、かれに從ひて言ふ『倒れたり、倒れたり。大なるバビロン、己が淫行より出づる憤恚の葡萄酒をもろもろの國人に飮ませし者』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'ほかの第三の御使、かれらに從ひ大聲にて言ふ『もし獸とその像とを拜し、且その額あるいは手に徽章を受くる者あらば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, '必ず神の怒の酒杯に盛りたる混りなき憤恚の葡萄酒を飮み、かつ聖なる御使たち及び羔羊の前にて、火と硫黄とにて苦しめらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'その苦痛の煙は世々 限りなく立ち昇りて、獸とその像とを拜する者、また其の名の徽章を受けし者は、夜も晝も休息を得ざらん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, '神の誡命とイエスを信ずる信仰とを守る聖徒の忍耐は茲にあり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, '我また天より聲ありて『書き記せ「今よりのち主にありて死ぬる死人は幸福なり」御靈も言ひたまふ「然り、彼 等はその勞役を止めて息まん。その業これに隨ふなり」』と言ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'また見しに、視よ、白き雲あり、その雲の上に人の子の如きもの坐して、首には金の冠冕をいただき、手には利き鎌を持ちたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, '又ほかの御使、聖所より出で、雲のうへに坐したまふ者にむかひ、大聲に呼はりて『なんぢの鎌を入れて刈れ、地の穀物は全く熟し、既に刈り取るべき時 至ればなり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'かくて雲の上に坐したまふ者その鎌を地に入れたれば、地の穀物は刈り取られたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, '又ほかの御使、天の聖所より出で、同じく利き鎌を持てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, '又ほかの火を掌どる御使、祭壇より出で、利き鎌を持つ者にむかひ大聲に呼はりて『なんぢの利き鎌を入れて地の葡萄の樹の房を刈り收めよ、葡萄は既に熟したり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, '御使その鎌を地に入れて地の葡萄を刈りをさめ、神の憤恚の大なる酒槽に投げ入れたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'かくて都の外にて酒槽を踐みしに、血 酒槽より流れ出でて馬の轡に達くほどになり、一 千 六 百 町に廣がれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, '我また天に他の大なる怪しむべき徴を見たり。即ち七人の御使ありて最後の七つの苦難を持てり、神の憤恚は之にて全うせらるるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, '我また火の混りたる玻璃の海を見しに、獸とその像とその名の數字とに勝ちたる者ども、神の立琴を持ちて玻璃の海の邊に立てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, '彼ら神の僕モーセの歌と羔羊の歌とを歌ひて言ふ『主なる全能の神よ、なんぢの御業は大なるかな、妙なるかな、萬國の王よ、なんぢの道は義なるかな、眞なるかな。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, '主よ、たれか汝を畏れざる、誰か御名を尊ばざる、汝のみ聖なり、諸種の國人きたりて御前に拜せん。なんぢの審判は既に現れたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'この後われ見しに、天にある證の幕屋の聖所ひらけて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'かの七つの苦難を持てる七人の御使、きよき輝ける亞麻 布を著、金の帶を胸に束ねて聖所より出づ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, '四つの活物の一つ、その七人の御使に、世々 限りなく生きたまふ神の憤恚の滿ちたる七つの金の鉢を與へしかば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, '聖所は神の榮光とその權力とより出づる煙にて滿ち、七人の御使の七つの苦難の終るまでは、誰も聖所に入ること能はざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, '我また聖所より大なる聲ありて、七人の御使に『往きて神の憤恚の七つの鉢を地の上に傾けよ』と言ふを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'かくて第一の者ゆきて其の鉢を地の上に傾けたれば、獸の徽章を有てる人々とその像を拜する人々との身に、惡しき苦しき腫物 生じたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, '第二の者その鉢を海の上に傾けたれば、海は死人の血の如くなりて、海にある生物ことごとく死にたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, '第三の者その鉢をもろもろの河と、もろもろの水の源泉との上に傾けたれば、みな血となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'われ水を掌どる御使の『いま在し昔います聖なる者よ、なんぢの斯く定め給ひしは正しき事なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, '彼らは聖徒と預言者との血を流したれば、之に血を飮ませ給ひしは相應しきなり』と云へるを聞けり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, '我また祭壇の物 言ふを聞けり『然り、主なる全能の神よ、なんぢの審判は眞なるかな、義なるかな』と。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, '第四の者その鉢を太陽の上に傾けたれば、太陽は火をもて人を燒くことを許さる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'かくて人々 烈しき熱に燒かれて、此 等の苦難を掌どる權威を有たちまふ神の名を涜し、かつ悔改めずして神に榮光を歸せざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, '第五の者その鉢を獸の座位の上に傾けたれば、獸の國 暗くなり、その國人 痛によりて己の舌を齧み、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'その痛と腫物とによりて天の神を涜し、かつ己が行爲を悔改めざりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, '第六の者その鉢を大なる河ユウフラテの上に傾けたれば、河の水 涸れたり。これ日の出づる方より來る王たちの途を備へん爲なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, '我また龍の口より、獸の口より、僞 預言者の口より、蛙のごとき三つの穢れし靈の出づるを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'これは徴をおこなふ惡鬼の靈にして、全能の神の大なる日の戰鬪のために全世界の王たちを集めんとて、その許に出でゆくなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(視よ、われ盜人のごとく來らん、裸にて歩み羞所を見らるることなからん爲に、目を覺してその衣を守る者は幸福なり)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'かの三つの靈、王たちをヘブル語にてハルマゲドンと稱ふる處に集めたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, '第七の者その鉢を空中に傾けたれば、聖所より御座より大なる聲いでて『事すでに成れり』と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'かくて數多の電光と聲と雷霆とあり、また大なる地震おこれり、人の地の上に在りし以來かかる大なる地震なかりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, '大なる都は三つに裂かれ、諸國の町々は倒れ、大なるバビロンは神の前におもひ出されて、劇しき御怒の葡萄酒を盛りたる酒杯を與へられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, '凡ての島は逃げさり、山は見えずなれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'また天より百 斤ほどの大なる雹、人々の上に降りしかば、人々 雹の苦難によりて神を涜せり。是その苦難 甚だしく大なればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, '七つの鉢を持てる七人の御使の一人きたり、我に語りて言ふ『來れ、われ多くの水の上に坐する大淫婦の審判を汝に示さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, '地の王たちは之と淫をおこなひ、地に住む者らは其の淫行の葡萄酒に醉ひたり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'かくてわれ御靈に感じ、御使に携へられて荒野にゆき、緋色の獸に乘れる女を見たり、この獸の體は神を涜す名にて覆はれ、また七つの頭と十の角とあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, '女は紫色と緋とを著、金・寶石・眞珠にて身を飾り、手には憎むべきものと己が淫行の汚とにて滿ちたる金の酒杯を持ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, '額には記されたる名あり。曰く『奧義 大なるバビロン、地の淫婦らと憎むべき者との母』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, '我この女を見るに、聖徒の血とイエスの證人の血とに醉ひたり。我これを見て大に怪しみたれば、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, '御使われに言ふ『なにゆゑ怪しむか、我この女と之を乘せたる七つの頭、十の角ある獸との奧義を汝に告げん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'なんぢの見し獸は前に有りしも今あらず、後に底なき所より上りて滅亡に往かん、地に住む者にて世の創より其の名を生命の書に記されざる者は、獸の前にありて今あらず、後に來るを見て怪しまん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, '智慧の心は茲にあり。七つの頭は女の坐する七つの山なり、また七人の王なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, '五 人は既に倒れて一人は今あり、他の一人は未だ來らず、來らば暫時のほど止るべきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, '前にありて今あらぬ獸は第八なり、前の七人より出でたる者にして滅亡に往くなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, '汝の見し十の角は十 人の王にして未だ國を受けざれども、一時のあひだ獸と共に王のごとき權威を受くべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, '彼らは心を一つにして己が能力と權威とを獸にあたふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, '彼らは羔羊と戰はん。而して羔羊かれらに勝ち給ふべし、彼は主の主、王の王なればなり。これと偕なる召されたるもの、選ばれたるもの、忠實なる者も勝を得べし』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, '御使また我に言ふ『なんぢの見し水、すなわち淫婦の坐する處は、もろもろの民・群衆・國・國語なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'なんぢの見し十の角と獸とは、かの淫婦を憎み、之をして荒涼ばしめ、裸ならしめ、且その肉を喰ひ、火をもて之を燒き盡さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, '神は彼らに御旨を行ふことと、心を一つにすることと、神の御言の成就するまで國を獸に與ふることとを思はしめ給ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'なんぢの見し女は地の王たちを宰どる大なる都なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'この後また他の一人の御使の大なる權威を有ちて天より降るを見しに、地はその榮光によりて照されたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'かれ強き聲にて呼はりて言ふ『大なるバビロンは倒れたり、倒れたり、かつ惡魔の住家、もろもろの穢れたる靈の檻、もろもろの穢れたる憎むべき鳥の檻となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'もろもろの國人はその淫行の憤恚の葡萄酒を飮み、地の王たちは彼と淫をおこなひ、地の商人らは彼の奢の勢力によりて富みたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'また天より他の聲あるを聞けり。曰く『わが民よ、かれの罪に干らず、彼の苦難を共に受けざらんため、その中を出でよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'かれの罪は積りて天にいたり、神その不義を憶え給ひたればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, '彼が爲しし如く彼に爲し、その行爲に應じ倍して之を報い、かれが酌み與へし酒杯に倍して之に酌み與へよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'かれが自ら尊びみづから奢りしと同じほどの苦難と悲歎とを之に與へよ。彼は心のうちに「われは女王の位に坐する者にして寡婦にあらず、決して悲歎を見ざるべし」と言ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'この故に、さまざまの苦難、一日のうちに彼の身にきたらん、即ち死と悲歎と饑饉となり。彼また火にて燒き盡されん、彼を審きたまふ主なる神は強ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, '彼と淫をおこなひ、彼とともに奢りたる地の王たちは、其の燒かるる煙を見て泣きかつ歎き、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'その苦難を懼れ、遙に立ちて「禍害なるかな、禍害なるかな、大なる都、堅固なる都バビロンよ、汝の審判は時の間に來れり」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, '地の商人かれが爲に泣き悲しまん。今より後その商品を買ふ者なければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'その商品は金・銀・寶石・眞珠・細布・紫色・絹・緋色および各樣の香木、また象牙のさまざまの器、價 貴き木、眞鍮・鐵・蝋石などの各樣の器、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'また肉桂・香料・香・香 油・乳香・葡萄酒・オリブ油・麥粉・麥・牛・羊・馬・車・奴隷および人の靈魂なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'なんぢの靈魂の嗜みたる果物は汝を去り、すべての美味、華美なる物は亡びて汝を離れん、今より後これを見ること無かるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'これらの物を商ひ、バビロンに由りて富を得たる商人らは、其の苦難を懼れて遙に立ち、泣き悲しみて言はん、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, '「禍害なるかな、禍害なるかな、細布と紫色と緋とを著、金・寶石・眞珠をもて身を飾りたる大なる都、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, '斯ばかり大なる富の時の間に荒涼ばんとは」而して凡ての船 長、すべて海をわたる人々、舟子および海によりて生活を爲すもの遙かに立ち、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'バビロンの燒かるる煙を見て叫び「いづれの都か、この大なる都に比ぶべき」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, '彼 等また塵をおのが首に被りて泣き悲しみ叫びて「禍害なるかな、禍害なるかな、此の大なる都、その奢によりて海に船を有てる人々の富を得たる都、かく時の間に荒涼ばんとは」と言はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, '天よ、聖徒・使徒・預言者よ、この都につきて喜べ、神なんぢらの爲に之を審き給ひたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'ここに一人の強き御使、大なる碾臼のごとき石を擡げ海に投げて言ふ『おほいなる都バビロンは斯くのごとく烈しく撃ち倒されて、今より後 見えざるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, '今よりのち立琴を彈くもの、樂を奏するもの、笛を吹く者、ラッパを鳴す者の聲なんぢの中に聞えず、今より後さまざまの細工をなす細工人なんぢの中に見えず、碾臼の音なんぢの中に聞えず、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, '今よりのち燈火の光なんぢの中に輝かず、今よりのち新郎・新婦の聲なんぢの中に聞えざるべし。そは汝の商人は地の大臣となり、諸種の國人はなんぢの咒術に惑され、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'また預言者・聖徒および凡て地の上に殺されし者の血は、この都の中に見出されたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'この後われ天に大なる群衆の大聲のごとき者ありて、かく言ふを聞けり。曰く『ハレルヤ、救と榮光と權力とは、我らの神のものなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'その御審は眞にして義なるなり、己が淫行をもて地を汚したる大淫婦を審き、神の僕らの血の復讐を彼になし給ひしなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'また再び言ふ『ハレルヤ、彼の燒かるる煙は世々 限りなく立ち昇るなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'ここに二十四人の長老と四つの活物と平伏して御座に坐したまふ神を拜し『アァメン、ハレルヤ』と言へり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'また御座より聲 出でて言ふ『すべて神の僕たるもの、神を畏るる者よ、小なるも大なるも、我らの神を讃め奉れ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'われ大なる群衆の聲おほくの水の音のごとく、烈しき雷霆の聲の如きものを聞けり。曰く『ハレルヤ全能の主、われらの神は統治らすなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'われら喜び樂しみて之に榮光を歸し奉らん。そは羔羊の婚姻の時いたり、既にその新婦みづから準備したればなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, '彼は輝ける潔き細布を著ることを許されたり、此の細布は聖徒たちの正しき行爲なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, '御使また我に言ふ『なんぢ書き記せ、羔羊の婚姻の宴席に招かれたる者は幸福なり』と。また我に言ふ『これ神の眞の言なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, '我その足下に平伏して拜せんとしたれば、彼われに言ふ『愼みて然すな、我は汝およびイエスの證を保つ汝の兄弟とともに僕たるなり。なんぢ神を拜せよ、イエスの證は即ち預言の靈なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, '我また天の開けたるを見しに、視よ、白き馬あり、之に乘りたまふ者は「忠實また眞」と稱へられ、義をもて審きかつ戰ひたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, '彼の目は焔のごとく、その頭には多くの冠冕あり、また記せる名あり、之を知る者は彼の他になし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, '彼は血に染みたる衣を纏へり、その名は「神の言」と稱ふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, '天に在る軍勢は白く潔き細布を著、白き馬に乘りて彼にしたがふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, '彼の口より利き劍いづ、之をもて諸國の民をうち、鐵の杖をもて之を治め給はん。また自ら全能の神の烈しき怒の酒槽を踐みたまふ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'その衣と股とに『王の王、主の主』と記せる名あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, '我また一人の御使の太陽のなかに立てるを見たり。大聲に呼はりて、中空を飛ぶ凡ての鳥に言ふ『いざ、神の大なる宴席に集ひきたりて、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, '王たちの肉、將校の肉、強き者の肉、馬と之に乘る者との肉、すべての自主および奴隷、小なるもの大なる者の肉を食へ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, '我また獸と地の王たちと彼らの軍勢とが相 集りて、馬に乘りたまふ者および其の軍勢に對ひて戰鬪を挑むを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'かくて獸は捕へられ、又その前に不思議を行ひて獸の徽章を受けたる者と、その像を拜する者とを惑したる僞 預言者も、之とともに捕へられ、二つながら生きたるまま硫黄の燃ゆる火の池に投げ入れられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'その他の者は馬に乘りたまふ者の口より出づる劍にて殺され、凡ての鳥その肉を食ひて飽きたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, '我また一人の御使の底なき所の鍵と大なる鎖とを手に持ちて、天より降るを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, '彼は龍、すなわち惡魔たりサタンたる古き蛇を捕へて、之を千年のあひだ繋ぎおき、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, '底なき所に投げ入れ閉ぢ込めて、その上に封印し、千年の終るまでは諸國の民を惑すことなからしむ。その後、暫時のあひだ解放さるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, '我また多くの座位を見しに、之に座する者あり、審判する權威を與へられたり。我またイエスの證および神の御言のために馘られし者の靈魂、また獸をもその像をも拜せず、己が額あるいは手にその徽章を受けざりし者どもを見たり。彼らは生きかへりて千年の間キリストと共に王となれり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, '(その他の死人は千年の終るまで生きかへらざりき)これは第一の復活なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, '幸福なるかな、聖なるかな、第一の復活に干る人。この人々に對して第二の死は權威を有たず、彼らは神とキリストとの祭司となり、キリストと共に千年のあひだ王たるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, '千年 終りて後サタンは其の檻より解放たれ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, '出でて地の四方の國の民、ゴグとマゴグとを惑し戰鬪のために之を集めん、その數は海の砂のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'かくて彼らは地の全面に上りて、聖徒たちの陣營と愛せられたる都とを圍みしが、天より火くだりて彼 等を燒き盡し、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, '彼らを惑したる惡魔は、火と硫黄との池に投げ入れられたり。ここは獸も僞 預言者もまた居る所にして、彼らは世々 限りなく晝も夜も苦しめらるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, '我また大なる白き御座および之に座し給ふものを見たり。天も地もその御顏の前を遁れて跡だに見えずなりき。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, '我また死にたる者の大なるも小なるも御座の前に立てるを見たり。而して數々の書 展かれ、他にまた一つの書ありて展かる、即ち生命の書なり、死人は此 等の書に記されたる所の、その行爲に隨ひて審かれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, '海はその中にある死人を出し、死も陰府もその中にある死人を出したれば、各自その行爲に隨ひて審かれたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'かくて死も陰府も火の池に投げ入れられたり、此の火の池は第二の死なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'すべて生命の書に記されぬ者はみな火の池に投げ入れられたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, '我また新しき天と新しき地とを見たり。これ前の天と前の地とは過ぎ去り、海も亦なきなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, '我また聖なる都、新しきエルサレムの、夫のために飾りたる新婦のごとく準備して、神の許をいで、天より降るを見たり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'また大なる聲の御座より出づるを聞けり。曰く『視よ、神の幕屋、人と偕にあり、神、人と偕に住み、人、神の民となり、神みづから人と偕に在して、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'かれらの目の涙をことごとく拭ひ去り給はん。今よりのち死もなく、悲歎も號叫も苦痛もなかるべし。前のもの既に過ぎ去りたればなり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'かくて御座に坐し給ふもの言ひたまふ『視よ、われ一切のものを新にするなり』また言ひたまふ『書き記せ、これらの言は信ずべきなり、眞なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'また我に言ひたまふ『事すでに成れり、我はアルパなり、オメガなり、始なり、終なり、渇く者には價なくして生命の水の泉より飮むことを許さん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, '勝を得る者は此 等のものを嗣がん、我はその神となり、彼は我が子とならん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'されど臆するもの、信ぜぬもの、憎むべきもの、人を殺すもの、淫行のもの、咒術をなすもの、偶像を拜する者および凡て僞る者は、火と硫黄との燃ゆる池にて其の報を受くべし、これ第二の死なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, '最後の七つの苦難の滿ちたる七つの鉢を持てる七人の御使の一人きたり、我に語りて言ふ『來れ、われ羔羊の妻なる新婦を汝に見せん』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, '御使、御靈に感じたる我を携へて大なる高き山にゆき、聖なる都エルサレムの、神の榮光をもて神の許を出でて天より降るを見せたり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'その都の光輝はいと貴き玉のごとく、透徹る碧玉のごとし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, '此處に大なる高き石垣ありて十二の門あり、門の側らに一人づつ十二の御使あり、門の上に一つづつイスラエルの子孫の十二の族の名を記せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, '東に三つの門、北に三つの門、南に三つの門、西に三つの門あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, '都の石垣には十二の基あり、これに羔羊の十二の使徒の十二の名を記せり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, '我と語る者は都と門と石垣とを測らん爲に金の間竿を持てり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, '都は方形にして、その長さ廣さ相 均し。彼は間竿にて都を測りしに一千 二百 町あり、長さ廣さ高さみな相 均し。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'また石垣を測りしに、人の度すなはち御使の度に據れば百 四十 四 尺あり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, '石垣は碧玉にて築き、都は清らかなる玻璃のごとき純金にて造れり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, '都の石垣の基はさまざまの寶石にて飾れり。第一の基は碧玉、第二は瑠璃、第三は玉髓、第四は緑玉、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, '第五は紅縞 瑪瑙、第六は赤瑪瑙、第七は貴橄欖石、第八は緑柱石、第九は黄玉石、第十は緑玉髓、第十 一は青玉、第十二は紫 水晶なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, '十二の門は十二の眞珠なり、おのおのの門は一つの眞珠より成り、都の大路は透徹る玻璃のごとき純金なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'われ都の内にて宮を見ざりき、主なる全能の神および羔羊はその宮なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, '都は日月の照すを要せず、神の榮光これを照し、羔羊はその燈火なり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, '諸國の民は都の光のなかを歩み、地の王たちは己が光榮を此處にたづさへきたる。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, '都の門は終日 閉ぢず(此處に夜あることなし)');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, '人々は諸國の民の光榮と尊貴とを此處にたづさえ來らん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, '凡て穢れたる者また憎むべき事と虚僞とを行ふ者は、此處に入らず、羔羊の生命の書に記されたる者のみ此處に入るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, '御使また水晶のごとく透徹れる生命の水の河を我に見せたり。この河は神と羔羊との御座より出でて都の大路の眞中を流る。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, '河の左右に生命の樹ありて十二 種の實を結び、その實は月 毎に生じ、その樹の葉は諸國の民を醫すなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, '今よりのち詛はるべき者は一つもなかるべし。神と羔羊との御座は都の中にあり。その僕らは之に事へ、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, '且その御顏を見ん、その御名は彼らの額にあるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, '今よりのち夜ある事なし、燈火の光をも日の光をも要せず、主なる神かれらを照し給へばなり。彼らは世々 限りなく王たるべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, '彼また我に言ふ『これらの言は信ずべきなり、眞なり、預言者たちの靈魂の神たる主は、速かに起るべき事をその僕どもに示さんとて、御使を遣し給へるなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, '視よ、われ速かに到らん、この書の預言の言を守る者は幸福なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'これらの事を聞き、かつ見し者は我ヨハネなり。かくて見 聞せしとき我これらの事を示したる御使の足下に平伏して拜せんとせしに、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'かれ言ふ『つつしみて然すな、われは汝および汝の兄弟たる預言者、また此の書の言を守る者と等しく僕たるなり、なんじ神を拜せよ』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'また我に言ふ『この書の預言の言を封ずな、時 近ければなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, '不義をなす者はいよいよ不義をなし不淨なる者はいよいよ不淨をなし、義なる者はいよいよ義をおこなひ、清き者はいよいよ清くすべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, '視よ、われ報をもて速かに到らん、各人の行爲に隨ひて之を與ふべし。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, '我はアルパなり、オメガなり、最先なり、最後なり、始なり、終なり、');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'おのが衣を洗ふ者は幸福なり、彼らは生命の樹にゆく權威を與へられ、門を通りて都に入ることを得るなり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, '犬および咒術をなすもの、淫行のもの、人を殺すもの、偶像を拜する者、また凡て虚僞を愛して之を行ふ者は外にあり。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'われイエスは我が使を遣して諸 教會のために此 等のことを汝らに證せり。我はダビデの萠蘗また其の裔なり、輝ける曙の明星なり』');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, '御靈も新婦もいふ『來りたまへ』聞く者も言へ『きたり給へ』と、渇く者はきたれ、望む者は價なくして生命の水を受けよ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'われ凡てこの書の預言の言を聞く者に證す。もし之に加ふる者あらば、神はこの書に記されたる苦難を彼に加へ給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, '若しこの預言の書の言を省く者あらば、神はこの書に記されたる生命の樹、また聖なる都より彼の受くべき分を省き給はん。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'これらの事を證する者いひ給ふ『然り、われ速かに到らん』アァメン、主イエスよ、來りたまへ。');
INSERT INTO `JapBungo_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, '願はくは主イエスの恩惠なんぢら凡ての者と偕に在らんことを。');
